def _v612_combined_score_floor_invariant(raw_floor: float, effective_floor: float) -> bool:
    """Validate the final live floor, not a softer intermediate family floor.

    Family/strategy offsets can produce a raw intermediate below the global
    floor. The admission floor must be finite and >=70; the intermediate must
    remain finite and positive so it cannot mask malformed inputs.
    """
    try:
        hard_min = max(70.0, float(CONFIG.get("V453_SCORE_FLOOR_MIN", 70.0)))
        raw = float(raw_floor)
        effective = float(effective_floor)
        return math.isfinite(raw) and raw > 0.0 and math.isfinite(effective) and effective >= hard_min and hard_min >= 70.0
    except Exception:
        return False


def _score_floor_invariant_check() -> bool:
    """Single-source global score hard-floor invariant; fail closed on drift."""
    try:
        floor = float(CONFIG.get("V45_SCORE_HARD_FLOOR", float("nan")))
        base = float(CONFIG.get("V45_SCORE_BASE", float("nan")))
        levels = tuple(float(x) for x in (CONFIG.get("V45_SCORE_RECOVERY_LEVELS", ()) or ()))
        if not (math.isfinite(floor) and math.isfinite(base)) or floor <= 0.0 or base < floor:
            return False
        return all(math.isfinite(x) and floor <= x <= base for x in levels)
    except Exception:
        return False


def _v45_patch_at_least(min_patch: int) -> bool:
    """Compatibility check for additive 4.5.x closures; never hard-code one patch."""
    try:
        raw = str(SCRIPT_VERSION).split("-", 1)[0]
        parts = raw.split(".")
        if len(parts) != 3 or parts[0] != "4" or parts[1] != "5":
            return False
        patch = int(parts[2])
        return patch >= int(min_patch)
    except Exception:
        return False


def _wall_age_sec(timestamp_sec_or_ms: Any) -> Optional[float]:
    """Age helper for Unix wall-clock timestamps (seconds or milliseconds)."""
    try:
        if timestamp_sec_or_ms is None:
            return None
        ts = float(timestamp_sec_or_ms)
        if not math.isfinite(ts) or ts <= 0.0:
            return None
        # Normalize the common Unix timestamp units without silently interpreting
        # microseconds/nanoseconds as milliseconds. Magnitude thresholds are
        # disjoint for current-era timestamps; future values remain future values.
        if ts >= 1.0e17:       # nanoseconds
            ts /= 1.0e9
        elif ts >= 1.0e14:     # microseconds
            ts /= 1.0e6
        elif ts >= 1.0e11:     # milliseconds
            ts /= 1.0e3
        # Otherwise treat as seconds.
        if not math.isfinite(ts) or ts <= 0.0:
            return None
        # Preserve negative age as evidence of a future-dated clock/source.
        # Freshness gates must reject it rather than silently turning it into age 0.
        return WALL_NOW() - ts
    except Exception:
        return None


def _v455_candidate_freshness_ok(generated_at_ms: Any) -> Tuple[bool, str, Optional[float]]:
    """Canonical fail-closed freshness check for Unix wall-clock candidate timestamps."""
    try:
        if not bool(CONFIG.get("V453_CANDIDATE_CLOCK_FIX_ENABLE", True)):
            age = _wall_age_sec(generated_at_ms)
        else:
            age = _wall_age_sec(generated_at_ms)
        if age is None:
            return False, "freshness.unverifiable", None
        max_age = float(CONFIG.get("V45_CANDIDATE_MAX_AGE_SEC", 390))
        if not math.isfinite(max_age) or max_age <= 0.0:
            return False, "freshness.config_invalid", age
        allowed_skew = max(0.0, float(CONFIG.get("V702_ALLOWED_FUTURE_CLOCK_SKEW_SEC", 2.0)))
        if age < -allowed_skew:
            return False, "freshness.future_timestamp", age
        if age > max_age:
            return False, "freshness.stale_candidate", age
        return True, "", age
    except Exception:
        return False, "freshness.unverifiable", None

