def _v647_record_suppressed_exception() -> None:
    """Non-decision telemetry for legacy fail-soft exception sites.

    This never raises and never changes a trading decision. It only increments a
    bounded counter and emits a sampled DEBUG message, preventing silent
    exception swallowing from becoming invisible during production diagnosis.
    """
    try:
        n = int(STATS.get("v647_suppressed_exception_count", 0) or 0) + 1
        STATS["v647_suppressed_exception_count"] = n
        if n <= 3 or n % 100 == 0:
            logger.debug("[V647-EXCEPTION] legacy fail-soft exception suppressed count=%d", n)
    except Exception:
        return


def _v593_note_suppressed_exception(stage: str, exc: BaseException) -> None:
    """Record otherwise-nonfatal exceptions in critical observability paths.

    This is telemetry only: it never converts an exception into an allow-path
    and never changes trade/risk state.
    """
    try:
        key = str(stage or "unknown")[:120]
        STATS["suppressed_exception_count"] = int(
            STATS.get("suppressed_exception_count", 0) or 0
        ) + 1
        counts = STATS.get("suppressed_exception_by_stage")
        if not isinstance(counts, dict):
            counts = {}
            STATS["suppressed_exception_by_stage"] = counts
        counts[key] = int(counts.get(key, 0) or 0) + 1
        STATS["last_suppressed_exception"] = {
            "stage": key,
            "type": type(exc).__name__,
            "error": str(exc)[:240],
            "ts": WALL_NOW(),
        }
    except Exception as _telemetry_exc:
        try:
            logger.debug(
                f"[ExceptionTelemetry] update suppressed stage={stage}: {_telemetry_exc}"
            )
        except Exception:
            _v647_record_suppressed_exception()



def _timeframe_to_seconds(tf: str) -> int:
    """Minimal timeframe parser for dedup / cooldown coherence."""
    try:
        s = str(tf).strip().lower()
        if s.endswith("m"):
            return max(1, int(float(s[:-1]) * 60))
        if s.endswith("h"):
            return max(1, int(float(s[:-1]) * 3600))
        if s.endswith("d"):
            return max(1, int(float(s[:-1]) * 86400))
        if s.endswith("w"):
            return max(1, int(float(s[:-1]) * 604800))
    except Exception as e:
        logger.debug(f"[TimeframeParser] suppressed: {e}")
    return 300


