# v4.0.6 FIX F — soft entry-only block flag. Independent of LIVE_BLOCKED.
# When active, PreSendGate/SizingEngine refuse NEW entries but PositionManager
# continues managing open trades (TP/SL/staircase/trailing/exit). Balance
# reconciler flips this when free-balance is low or fetch is transiently
# failing; only a hard BLOCK (fetch failed + cache expired) additionally
# escalates to LIVE_BLOCKED via LiveStateMachine.block().
LIVE_ENTRIES_BLOCKED: Dict[str, Any] = {
    "active": False,
    "reason": None,
    "where": None,
    "since": None,
}

def live_entries_block(reason: str, where: str = "") -> None:
    incoming_reason = str(reason or "").strip().lower()
    try:
        # A later balance-refresh failure must never overwrite an already active
        # execution/protection/startup latch with a softer, auto-recoverable
        # balance reason. Otherwise a subsequent REAL balance read could turn an
        # unrelated critical block into a clearable balance-only latch.
        if bool(LIVE_ENTRIES_BLOCKED.get("active")):
            current_reason = str(LIVE_ENTRIES_BLOCKED.get("reason") or "").strip().lower()
            recoverable = globals().get("_AUTO_BALANCE_RECOVERABLE_BLOCK_REASONS", frozenset())
            if incoming_reason in recoverable and current_reason not in recoverable:
                STATS["v702_a39_block_reason_overwrite_prevented"] = int(
                    STATS.get("v702_a39_block_reason_overwrite_prevented", 0) or 0
                ) + 1
                logger.critical(
                    "[V702-A39-BLOCK] retained sticky non-balance entry block reason=%s; "
                    "refused balance-only overwrite=%s @ %s",
                    current_reason[:100], incoming_reason[:100], str(where or "unknown")[:100],
                )
                return
    except Exception as exc:
        # Failure to inspect the previous block is not permission to overwrite it.
        logger.critical("[V702-A39-BLOCK] reason-priority check failed; preserving active block: %s", exc)
        if bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
            return
    if not LIVE_ENTRIES_BLOCKED["active"]:
        LIVE_ENTRIES_BLOCKED["since"] = WALL_NOW()
    LIVE_ENTRIES_BLOCKED["active"] = True
    LIVE_ENTRIES_BLOCKED["reason"] = reason
    LIVE_ENTRIES_BLOCKED["where"] = where

# v4.2.2 FIX — reason-aware unblock policy (fail-closed).
# A block may ONLY be cleared automatically when its recorded reason belongs
# to a SAFE family — i.e. a transient, self-healing condition whose recovery
# is provable by the very fact that the caller now observes a healthy state
# (a real balance fetch succeeded, a cache refreshed, a truth-seal re-sealed).
_SAFE_UNBLOCK_PREFIXES: Tuple[str, ...] = (
    "balance_",      # balance_below_minimum, balance_cache_untrusted, ...
    "reconciler_",   # reconciler transient failures
    "truthseal_",    # truth-seal transient failures
    "cache_",        # stale-cache style soft blocks
    "soft_",         # generic soft blocks
    "real_balance_recovered",
)
# DANGEROUS families must NEVER be auto-cleared: they indicate an active
# structural hazard (unprotected exposure, ambiguous order state, failed
# emergency exit). Clearing requires explicit operator/reconciler action.
_HARD_UNBLOCK_SUBSTRINGS: Tuple[str, ...] = (
    "stopless_exposure",
    "cancel_unverified",
    "sl_cancel_unverified",
    "emergency_sell_failed",
    "emergency_close",
    "kill_switch",
    # A fresh USDT balance cannot resolve an ambiguous order/fill/protection state.
    "execution_intent",
    "submission_unknown",
    "execution_unknown",
    "maker_path_outcome_unknown",
    "maker_order_id_unknown",
    "fill_reconcile",
    "entry_reconcile",
    "target_order_unknown",
    "unprotected",
    "protection_exception",
    "snapshot_persist_failed",
    "startup_execution_intent_recovery_failed",
    "startup_unresolved_execution_intents",
)

# A successful balance read may automatically clear ONLY these balance-specific
# transient latches. All other reasons require their own recovery proof or an
# explicit operator action; balance telemetry is not order reconciliation.
_AUTO_BALANCE_RECOVERABLE_BLOCK_REASONS = frozenset({
    "balance_below_minimum",
    "balance_cache_untrusted",
    "balance_reconciler_block",
})

def live_entries_unblock(reason: str = "", where: str = "") -> bool:
    """v4.2.2 FIX — reason-aware unblock (fail-closed).

    Clearing LIVE_ENTRIES_BLOCKED is allowed ONLY when BOTH hold:
      (a) the caller-supplied `reason` belongs to a SAFE family, and
      (b) the CURRENTLY RECORDED block reason is NOT in a dangerous family.
    Dangerous recorded reasons (stopless exposure / unverified cancel /
    failed emergency sell / ...) are never auto-cleared here — they require
    explicit operator/reconciler proof that the hazard is gone.
    Returns True if the block was actually cleared, False otherwise.
    """
    try:
        if not LIVE_ENTRIES_BLOCKED.get("active"):
            return True  # nothing to clear — already open
        rec_reason = str(LIVE_ENTRIES_BLOCKED.get("reason") or "").lower()
        req_reason = str(reason or "").lower()
        # A balance fetch proves only balance recovery. It must not clear unrelated
        # startup execution-intent, submission-unknown, stop/protection or other
        # entry blocks merely because their reason was absent from an older denylist.
        if rec_reason not in _AUTO_BALANCE_RECOVERABLE_BLOCK_REASONS:
            logger.warning(
                f"[Entries] balance-only unblock REFUSED: recorded reason '{rec_reason or 'unspecified'}' "
                f"is not a recoverable balance latch (requested by '{req_reason}' @ {where})"
            )
            return False
        # (b) never auto-clear a dangerous recorded reason.
        for hard in _HARD_UNBLOCK_SUBSTRINGS:
            if hard in rec_reason:
                logger.warning(
                    f"[Entries] unblock REFUSED: recorded reason '{rec_reason}' "
                    f"is hazardous ({hard}); requires explicit recovery proof "
                    f"(requested by '{req_reason}' @ {where})"
                )
                return False
        # (a) caller must prove a safe recovery reason.
        if req_reason and any(req_reason.startswith(p) or req_reason == p
                              for p in _SAFE_UNBLOCK_PREFIXES):
            LIVE_ENTRIES_BLOCKED["active"] = False
            LIVE_ENTRIES_BLOCKED["reason"] = None
            LIVE_ENTRIES_BLOCKED["where"] = None
            LIVE_ENTRIES_BLOCKED["since"] = None
            logger.info(
                f"[Entries] LIVE_ENTRIES_BLOCKED cleared (reason='{req_reason}' @ {where})"
            )
            return True
        logger.warning(
            f"[Entries] unblock REFUSED: caller reason '{req_reason or 'unspecified'}' "
            f"is not a recognized safe-recovery family (@ {where})"
        )
        return False
    except Exception as _ue:
        # Fail-closed: on any error, keep the block as-is.
        logger.warning(f"[Entries] unblock error (kept blocked): {_ue}")
        return False

def live_entries_hard_recover_after_verified_exit(symbol: str, *, residual_qty: float = 0.0,
                                              exit_verified: bool = False,
                                              where: str = "") -> bool:
    """v4.5.53 explicit recovery proof for a previously hazardous entry block.

    This is deliberately NOT part of the generic auto-unblock policy. It may
    clear only when the exact blocked symbol is proven flat after a verified
    emergency/protection exit. Any uncertainty keeps the block intact.
    """
    try:
        if not exit_verified:
            return False
        if float(residual_qty or 0.0) > 1e-12:
            return False
        if symbol in ACTIVE_TRADES:
            return False
        if not LIVE_ENTRIES_BLOCKED.get("active"):
            return True
        rec_reason = str(LIVE_ENTRIES_BLOCKED.get("reason") or "").lower()
        sym_key = str(symbol or "").lower()
        if sym_key and sym_key not in rec_reason:
            return False
        hazardous = ("stopless_exposure", "entry_protection_failed",
                     "emergency_sell_failed", "cancel_unverified")
        if not any(h in rec_reason for h in hazardous):
            return False
        LIVE_ENTRIES_BLOCKED["active"] = False
        LIVE_ENTRIES_BLOCKED["reason"] = None
        LIVE_ENTRIES_BLOCKED["where"] = None
        LIVE_ENTRIES_BLOCKED["since"] = None
        STATS["v553_hard_entry_block_recovered"] = int(STATS.get("v553_hard_entry_block_recovered", 0) or 0) + 1
        logger.critical(
            f"[V553-RECOVERY] VERIFIED FLAT EXIT for {symbol}; "
            f"cleared exact-symbol LIVE_ENTRIES_BLOCKED @ {where or 'unknown'}"
        )
        return True
    except Exception as exc:
        logger.warning(f"[V553-RECOVERY] proof-based unblock refused: {exc}")
        return False

