class KillSwitch:
    @staticmethod
    def is_active() -> bool:
        # env
        env_val = str(ENV.get("KILL_SWITCH", "0")).strip().lower()
        if env_val in ("1", "true", "yes", "on"):
            return True
        # STOP file
        try:
            if os.path.exists(CONFIG["KILL_SWITCH_FILE"]):
                return True
        except Exception as e:
            logger.debug(f"[KillSwitch] file check suppressed: {e}")
        return False


# =============================================================================
# V702 A39 — canonical MEXC/CCXT balance parsing
# =============================================================================
def _v702_a39_extract_usdt_balance(balance: Dict[str, Any]) -> Tuple[float, Optional[float], Optional[float]]:
    """Return (free, used, total) USDT without ever treating locked funds as free.

    CCXT normally exposes balance buckets at top level (free/used/total), while
    some adapters/fixtures also expose per-asset objects. Both documented shapes
    are accepted. `total` is diagnostic only and is NEVER a spendable fallback.
    """
    if not isinstance(balance, dict):
        raise ValueError("balance_payload_not_mapping")
    asset = balance.get("USDT")
    free_map = balance.get("free")
    used_map = balance.get("used")
    total_map = balance.get("total")

    if isinstance(free_map, dict) and "USDT" in free_map:
        raw_free = free_map.get("USDT")
    elif isinstance(asset, dict) and "free" in asset:
        raw_free = asset.get("free")
    elif isinstance(free_map, dict):
        # A valid CCXT free-bucket mapping with no USDT entry means zero free USDT.
        raw_free = 0.0
    else:
        raise ValueError("free_usdt_field_missing")

    try:
        free = float(raw_free)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError("free_usdt_not_numeric") from exc
    if not math.isfinite(free) or free < 0.0:
        raise ValueError("free_usdt_not_finite_or_negative")

    def _optional_bucket(mapping, key):
        raw = mapping.get("USDT") if isinstance(mapping, dict) else None
        if raw is None and isinstance(asset, dict):
            raw = asset.get(key)
        if raw is None:
            return None
        try:
            value = float(raw)
        except (TypeError, ValueError, OverflowError):
            return None
        return value if math.isfinite(value) and value >= 0.0 else None

    used = _optional_bucket(used_map, "used")
    total = _optional_bucket(total_map, "total")
    return free, used, total


# =============================================================================
#  SECTION 8 — BALANCE RECONCILER (from hybrid — single canonical)
# =============================================================================

class BalanceReconciler:
    """
    Single source of truth for account balance.
    States:   REAL  -> freshly fetched from exchange
              CACHE -> aged past TTL but within grace
              BLOCK -> untrusted; triggers LIVE_BLOCKED
    """
    _last_real_value: float = 0.0
    _last_real_ts: float = 0.0  # monotonic for duration math
    _last_real_wall_ts: float = 0.0  # wall-clock for display/snapshot
    _last_state: str = "BLOCK"
    _last_source: str = "init"
    _sealed: bool = False

    @classmethod
    def seal_real(cls, free_usdt: float, source: str = "seal") -> bool:
        try:
            v = float(free_usdt)
            if v < 0:
                return False
            cls._last_real_value = v
            cls._last_real_ts = MONO_NOW()
            cls._last_real_wall_ts = WALL_NOW()
            cls._last_state = "REAL"
            cls._last_source = source
            cls._sealed = True
            logger.info(f"[Reconciler] SEAL_REAL free={v:.4f} src={source}")
            return True
        except Exception as e:
            logger.error(f"[Reconciler] seal_real failure: {e}")
            return False

    @classmethod
    def cache_gates_new_entries(cls) -> bool:
        """v4.0.2 PATCH D: In live, CACHE must NOT be trusted for sizing new entries.
        Existing exits continue to be managed; new entries are blocked."""
        return bool(CONFIG.get("BALANCE_CACHE_BLOCKS_NEW_ENTRIES", True))

    @classmethod
    async def fetch(cls, exchange) -> Tuple[float, str]:
        """
        Returns (usable_usdt, state) where state in {REAL, CACHE, BLOCK}.

        REAL  — freshly fetched from exchange within the last fetch call.
        CACHE — fetch failed but last REAL value is still within TTL grace.
                Usable ONLY for managing existing exits; SizingEngine will
                reject new entries under CACHE when BALANCE_CACHE_BLOCKS_NEW_ENTRIES.
        BLOCK — fetch failed AND cache is expired/empty. Triggers LIVE_BLOCKED.
                No new trades may open.  Existing trades continue to be managed.
        """
        is_live = bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and \
                 not bool(CONFIG.get("PAPER_TRADING_MODE", False))

        # Attempt REAL fetch
        # v4.0.11 R1 — factory + retry_safe=True so safe_api_call performs a
        # REAL single retry on transient network errors. Previously we passed
        # a raw coroutine (which cannot be re-awaited), so retry_safe was a
        # no-op even if it had been set. Semantics of REAL/CACHE/BLOCK are
        # preserved exactly — only the call surface changes.
        fetch_failed = False
        try:
            bal = await safe_api_call("reconciler_fetch_balance",
                                      lambda: exchange.fetch_balance(),
                                      retry_safe=True)
            free, used, total = _v702_a39_extract_usdt_balance(bal)
            try:
                _locked = max(0.0, total - free) if total is not None else (used if used is not None else None)
                STATS["v702_a39_balance_snapshot"] = {
                    "free_usdt": float(free), "used_usdt": used, "total_usdt": total,
                    "locked_or_nonfree_usdt": _locked, "source": "fetch_balance",
                    "ts": float(WALL_NOW()), "spendable_basis": "FREE_ONLY_NO_DOUBLE_DEDUCT",
                }
                # Account-wide snapshot shared with the portfolio drawdown guard.
                # Only normalized balance buckets are retained; API credentials
                # and opaque exchange response metadata are never copied.
                STATS["v702_equity_balance_snapshot"] = {
                    "free": dict(bal.get("free") or {}),
                    "used": dict(bal.get("used") or {}),
                    "total": dict(bal.get("total") or {}),
                    "state": "REAL", "ts": float(WALL_NOW()),
                    "source": "BalanceReconciler.fetch_balance",
                }
                logger.info(
                    "[V702-A39-BALANCE] free_usdt=%.6f used_usdt=%s total_usdt=%s nonfree_usdt=%s "
                    "spendable_basis=FREE_ONLY locked_open_orders_not_subtracted_twice",
                    free, "NA" if used is None else f"{used:.6f}",
                    "NA" if total is None else f"{total:.6f}",
                    "NA" if _locked is None else f"{_locked:.6f}",
                )
            except Exception:
                _v647_record_suppressed_exception()
            if free >= float(CONFIG.get("BALANCE_MIN_ACCEPT_USDT", 5.0)):
                cls._last_real_value = free
                cls._last_real_ts = MONO_NOW()
                cls._last_real_wall_ts = WALL_NOW()
                cls._last_state = "REAL"
                cls._last_source = "fetch_balance"
                cls._sealed = True
                # v4.0.6 FIX F — REAL fetch OK: clear any prior soft entries-block
                # that came from a transient low-balance/fetch failure. Hard
                # LIVE_BLOCKED is NOT auto-cleared here (operator intervention).
                # v4.2.2 FIX — pass an EXPLICIT safe-recovery reason. The new
                # reason-aware live_entries_unblock() will refuse to clear if
                # the recorded block reason is hazardous (stopless exposure /
                # unverified cancel / failed emergency sell), so a plain REAL
                # fetch can no longer silently mask an active structural risk.
                try:
                    if LIVE_ENTRIES_BLOCKED.get("active"):
                        _cleared = live_entries_unblock(
                            reason="real_balance_recovered",
                            where="BalanceReconciler.fetch",
                        )
                        if _cleared:
                            logger.info("[Reconciler] LIVE_ENTRIES_BLOCKED cleared (real_balance_recovered)")
                except Exception:
                    _v647_record_suppressed_exception()
                return free, "REAL"
            # v4.0.6 FIX F — balance below minimum is an ENTRY-block only,
            # NOT a system block. Keep managing existing positions; refuse
            # new entries via LIVE_ENTRIES_BLOCKED (soft).
            logger.warning(
                f"[Reconciler] REAL fetch returned free={free:.4f} < min_accept — ENTRIES_BLOCKED"
            )
            cls._last_state = "BLOCK"
            live_entries_block("balance_below_minimum", where="BalanceReconciler.fetch")
            return 0.0, "BLOCK"
        except Exception as e:
            fetch_failed = True
            logger.warning(f"[Reconciler] fetch_balance failed: {e}")

        # Fallback to CACHE if still fresh (only if fetch failed, not if balance was low)
        if fetch_failed:
            ttl = float(CONFIG.get("BALANCE_CACHE_TTL_SEC", 90))
            age = MONO_NOW() - cls._last_real_ts
            if cls._sealed and age <= ttl and cls._last_real_value > 0:
                cls._last_state = "CACHE"
                logger.info(
                    f"[Reconciler] using CACHE (age={age:.1f}s, ttl={ttl}s, val={cls._last_real_value:.4f})"
                )
                # Canonical live semantics: CACHE is manage-only. Explicitly
                # raise the entry-only block so every entry path sees the same
                # state, rather than relying on a secondary sizing check.
                if is_live and cls.cache_gates_new_entries():
                    live_entries_block("balance_cache_untrusted", where="BalanceReconciler.fetch")
                return cls._last_real_value, "CACHE"

        # BLOCK — fetch failed AND cache expired/empty. This is a HARD block:
        # we cannot trust ANY balance number, so keep the LIVE_BLOCKED
        # escalation. v4.0.6 FIX F: also raise the soft entries-block flag
        # for redundancy-safety at the pre-send gate.
        cls._last_state = "BLOCK"
        live_entries_block("balance_reconciler_block", where="BalanceReconciler.fetch")
        LiveStateMachine.block("balance_reconciler_block", where="BalanceReconciler.fetch")
        _validation_log = bool(globals().get("_V699_VALIDATE_ONLY_REQUEST", False)) or bool(globals().get("V644_SELFTEST_ACTIVE", False))
        (logger.info if _validation_log else logger.critical)(
            "[Reconciler%s] BLOCK: fetch failed AND cache expired/empty — LIVE_BLOCKED",
            "-SELFTEST" if _validation_log else "",
        )
        return 0.0, "BLOCK"

    @classmethod
    def snapshot(cls) -> Dict[str, Any]:
        return {
            "last_real_value": cls._last_real_value,
            "last_real_ts": cls._last_real_wall_ts or 0.0,
            "last_real_mono_ts": cls._last_real_ts,
            "state": cls._last_state,
            "source": cls._last_source,
            "sealed": cls._sealed,
        }


# =============================================================================
#  SECTION 9 — API LATENCY MONITOR + EXCHANGE WATCHDOG (single canonical each)
# =============================================================================

class APILatencyMonitor:
    _samples: Dict[str, "deque[float]"] = {}
    _maxlen: int = int(CONFIG.get("API_LATENCY_MAXLEN", 500))

    @classmethod
    def record(cls, op_label: str, duration_ms: float) -> None:
        try:
            dq = cls._samples.get(op_label)
            if dq is None:
                dq = deque(maxlen=cls._maxlen)
                cls._samples[op_label] = dq
            dq.append(float(duration_ms))
        except Exception:
            _v647_record_suppressed_exception()

    @staticmethod
    def _quantile(arr_sorted: List[float], p: float) -> float:
        if not arr_sorted:
            return 0.0
        n = len(arr_sorted)
        k = min(n - 1, max(0, int(round(p * (n - 1)))))
        return float(arr_sorted[k])

    @classmethod
    def stats(cls, op_label: Optional[str] = None) -> Dict[str, Any]:
        def _for(label: str, dq: deque) -> Dict[str, float]:
            arr = sorted(dq)
            return {
                "p50": cls._quantile(arr, 0.50),
                "p95": cls._quantile(arr, 0.95),
                "p99": cls._quantile(arr, 0.99),
                "n": len(arr),
            }
        if op_label is not None:
            dq = cls._samples.get(op_label) or deque()
            return _for(op_label, dq)
        return {lbl: _for(lbl, dq) for lbl, dq in cls._samples.items()}


def _v563_watchdog_should_record(op_label: str) -> bool:
    """Exclude expected native-SL probing noise from the transport watchdog."""
    try:
        label = str(op_label or "").lower()
        prefixes = tuple(str(x).lower() for x in CONFIG.get("V563_WATCHDOG_IGNORE_OP_PREFIXES", ()))
        return not any(label == p or label.startswith(p) for p in prefixes)
    except Exception:
        return True


# =============================================================================
# V651 WATCHDOG READ-ONLY ISOLATION
# =============================================================================
# Read-only scanner latency/errors are tracked separately from entry-critical
# transport health. A slow OHLCV/ticker request must never turn into a global
# `safety.watchdog` entry block. Data-sufficiency, per-read and per-symbol
# timeouts remain fail-closed.
def _v651_is_readonly_market_data_op(op_label: str) -> bool:
    try:
        label = str(op_label or "").lower()
        prefixes = (
            "ohlcv_", "ticker_", "universe_", "v650_liquidity500_",
            "v650_radar_", "market_data_", "btc_context_",
        )
        return any(label == p or label.startswith(p) for p in prefixes)
    except Exception:
        return False


class ExchangeWatchdog:
    _errors: "deque[float]" = deque(maxlen=1000)
    _tripped_until: float = 0.0
    _trips: int = 0
    _last_reason: str = ""
    _readonly_errors: int = 0

    @classmethod
    def record_error(cls, op_label: str = "") -> None:
        if not _v563_watchdog_should_record(op_label):
            return
        if _v651_is_readonly_market_data_op(op_label):
            cls._readonly_errors += 1
            try:
                STATS["v651_market_data_transport_errors"] = int(
                    STATS.get("v651_market_data_transport_errors", 0) or 0
                ) + 1
            except Exception:
                pass
            return
        cls._errors.append(MONO_NOW())

    @classmethod
    def is_tripped(cls) -> bool:
        if MONO_NOW() < cls._tripped_until:
            return True
        # Only ENTRY-CRITICAL transport failures can trip the entry watchdog.
        window = float(CONFIG.get("WATCHDOG_WINDOW_SEC", 120))
        threshold = int(CONFIG.get("WATCHDOG_ERR_THRESHOLD", 8))
        cutoff = MONO_NOW() - window
        recent = sum(1 for t in cls._errors if t >= cutoff)
        if recent >= threshold:
            cls._trip("error_threshold")
            return True
        # Market-data p95 is telemetry-only; critical p95 remains fail-closed.
        p95_cap = float(CONFIG.get("WATCHDOG_LATENCY_MS_P95", 4500))
        for lbl, s in APILatencyMonitor.stats().items():
            if _v651_is_readonly_market_data_op(lbl):
                continue
            if s.get("n", 0) >= 20 and s.get("p95", 0) > p95_cap:
                cls._trip(f"latency_p95_{lbl}")
                return True
        return False

    @classmethod
    def _trip(cls, reason: str) -> None:
        trip_sec = float(CONFIG.get("WATCHDOG_TRIP_SEC", 90))
        cls._tripped_until = MONO_NOW() + trip_sec
        cls._trips += 1
        cls._last_reason = str(reason or "unknown")
        logger.warning(f"[Watchdog] TRIPPED reason={reason} until={cls._tripped_until:.0f}")

    @classmethod
    def snapshot(cls) -> Dict[str, Any]:
        tripped = cls.is_tripped()
        window = float(CONFIG.get("WATCHDOG_WINDOW_SEC", 120.0))
        cutoff = MONO_NOW() - max(1.0, window)
        recent = sum(1 for ts in cls._errors if ts >= cutoff)
        return {
            "tripped": tripped,
            "tripped_until": cls._tripped_until,
            "trips": cls._trips,
            "recent_errors_count": recent,
            "readonly_market_data_errors": int(getattr(cls, "_readonly_errors", 0) or 0),
            "reason": cls._last_reason if tripped else (cls._last_reason or ""),
        }


# ---- v4.0.3 PATCH M — transient network error keywords (single retry only) --
_TRANSIENT_ERR_KEYS = (
    "timeout", "timed out", "read timed out", "connection reset",
    "reset by peer", "broken pipe", "temporarily unavailable",
)

def _is_transient_network_error(err: Exception) -> bool:
    try:
        msg = str(err).lower()
    except Exception:
        return False
    return any(k in msg for k in _TRANSIENT_ERR_KEYS)


def _v703_route_orderbook_error_token(exc: BaseException, max_detail_chars: int = 96) -> str:
    """Bounded, credential-redacted route diagnostic for compact operator telemetry."""
    error_type = type(exc).__name__
    try:
        detail = str(exc).strip()
        detail = re.sub(r"https?://\S+", "<url>", detail, flags=re.IGNORECASE)
        detail = re.sub(
            r"(?i)(api[_-]?key|secret|token|password|authorization|signature)(\s*[:=]\s*)[^\s,;]+",
            r"\1\2<redacted>", detail,
        )
        detail = re.sub(r"[^A-Za-z0-9_.:-]+", "_", detail).strip("_")
        try:
            limit = max(1, min(128, int(max_detail_chars)))
        except Exception:
            limit = 96
        if detail:
            return f"{error_type}:{detail[:limit]}"
    except Exception:
        pass
    return error_type


class V702PlatformRateLimiter:
    """One process-wide MEXC request token bucket with safety-first priority.

    Research waits first, scanner traffic second, then execution; position
    protection/reconciliation always has first claim on newly refilled tokens.
    CCXT's native enableRateLimit remains enabled as the venue adapter backstop.
    """
    def __init__(self):
        self.tokens = 0.0
        self.updated = time.monotonic()
        self.capacity = 24.0
        self.rate = 12.0
        self._loop = None
        self._lock = None

    @staticmethod
    def priority(op_label: str) -> Tuple[int, str]:
        label = str(op_label or "").lower()
        # Protection reads must be classified before the broad ticker/ohlcv
        # scanner matcher; otherwise protected_fetch_ticker_* is starved as SCAN.
        if any(x in label for x in (
            "protected_fetch_ticker", "position_manager", "stop_loss", "stoploss",
            "create_sl", "sl_", "tp1_sell", "tp2_sell", "tp3_sell",
            "take_profit", "cancel", "protection", "reconcile", "fetch_order",
            "fetch_open_orders", "fetch_closed_orders", "fetch_my_trades",
            "emergency_exit", "exit_order",
        )):
            return 0, "PROTECTION"
        # Ordinary market-data reads are scanner inputs, not execution operations.
        if any(x in label for x in ("fetch_order_book", "order_book", "orderbook", "ticker", "ohlcv", "universe", "load_markets", "scan")):
            return 2, "SCAN"
        if any(x in label for x in ("create_", "submit", "market_buy", "market_sell", "limit_buy", "order", "balance", "truthseal", "preflight")):
            return 1, "EXECUTION"
        if any(x in label for x in ("knowledge", "shadow", "counterfactual", "intraday", "research")):
            return 3, "RESEARCH"
        return 3, "RESEARCH"

    async def acquire(self, op_label: str) -> None:
        if not bool(CONFIG.get("V702_PLATFORM_RATE_LIMIT_ENABLE", True)):
            return
        raw_rate = CONFIG.get("V702_PLATFORM_RATE_LIMIT_RPS", 12.0)
        raw_capacity = CONFIG.get("V702_PLATFORM_RATE_LIMIT_BURST", 24.0)
        if isinstance(raw_rate, bool) or isinstance(raw_capacity, bool):
            raise ValueError("platform_rate_limit_numeric_config_required")
        rate = float(raw_rate)
        capacity = float(raw_capacity)
        if not math.isfinite(rate) or not 1.0 <= rate <= 50.0:
            raise ValueError("platform_rate_limit_rps_out_of_range")
        if not math.isfinite(capacity) or not 8.0 <= capacity <= 100.0:
            # The RESEARCH lane reserves seven tokens; a burst below eight
            # makes that lane mathematically unable to acquire its first token.
            raise ValueError("platform_rate_limit_burst_below_progress_floor_8")
        tier, tier_name = self.priority(op_label)
        loop = asyncio.get_running_loop()
        if self._loop is not loop or self._lock is None:
            self._loop = loop
            self._lock = asyncio.Lock()
            self.tokens = capacity
            self.updated = time.monotonic()
        while True:
            async with self._lock:
                now = time.monotonic()
                self.tokens = min(capacity, self.tokens + max(0.0, now - self.updated) * rate)
                self.updated = now
                reserve = 0.0 if tier <= 1 else (3.0 if tier == 2 else 7.0)
                if self.tokens >= 1.0 + reserve:
                    self.tokens -= 1.0
                    STATS["v702_platform_api_requests"] = int(STATS.get("v702_platform_api_requests", 0) or 0) + 1
                    STATS[f"v702_platform_api_priority_{tier_name.lower()}"] = int(STATS.get(f"v702_platform_api_priority_{tier_name.lower()}", 0) or 0) + 1
                    return
                delay = max(0.01, (1.0 + reserve - self.tokens) / rate)
                STATS["v702_platform_api_throttle_waits"] = int(STATS.get("v702_platform_api_throttle_waits", 0) or 0) + 1
            await asyncio.sleep(min(1.0, delay))


_V702_PLATFORM_RATE_LIMITER = V702PlatformRateLimiter()


async def safe_api_call(op_label: str, coro_or_factory, *, retry_safe: bool = False):
    """
    Wraps every exchange call with latency + error recording.

    v4.0.4 PATCH Q (additive over v4.0.3 PATCH M):
      - Accepts either a raw coroutine (LEGACY — unchanged behaviour, no retry)
        OR a zero-arg callable/factory that returns a fresh coroutine.
      - retry_safe=True enables a SINGLE retry on transient network errors
        ONLY when a factory was supplied (a coroutine cannot be awaited twice).
      - retry_safe MUST NOT be set for state-changing order calls
        (buy / sell / create_sl / cancel / emergency_*) — duplicate-execution
        hazard. Callers that pass a raw coroutine get zero retries regardless.
      - Non-transient errors are raised immediately (no retry, fail-closed).
      - Latency, watchdog and transient-counter semantics preserved.
    """
    is_factory = callable(coro_or_factory) and not hasattr(coro_or_factory, "__await__")

    async def _run_once():
        t0 = MONO_NOW()
        try:
            # Every request routed through the canonical exchange wrapper shares
            # one platform-level token bucket. Retries also reacquire a token.
            await _V702_PLATFORM_RATE_LIMITER.acquire(op_label)
            res = await (coro_or_factory() if is_factory else coro_or_factory)
            dt_ms = (MONO_NOW() - t0) * 1000.0
            APILatencyMonitor.record(op_label, dt_ms)
            return res, None
        except Exception as e:
            dt_ms = (MONO_NOW() - t0) * 1000.0
            APILatencyMonitor.record(op_label, dt_ms)
            ExchangeWatchdog.record_error(op_label)
            return None, e

    res, err = await _run_once()
    if err is None:
        return res

    if _is_transient_network_error(err):
        STATS["api_transient_errors"] = STATS.get("api_transient_errors", 0) + 1
        # Real retry only when caller explicitly opted-in AND provided a factory
        if retry_safe and is_factory:
            logger.warning(
                f"[safe_api_call:{op_label}] transient error: {err} — single retry"
            )
            STATS["api_transient_retries"] = STATS.get("api_transient_retries", 0) + 1
            res2, err2 = await _run_once()
            if err2 is None:
                return res2
            if _is_transient_network_error(err2):
                STATS["api_transient_retry_failed"] = \
                    STATS.get("api_transient_retry_failed", 0) + 1
            logger.warning(f"[safe_api_call:{op_label}] retry failed: {err2}")
            raise err2
        logger.warning(f"[safe_api_call:{op_label}] transient error: {err}")
    else:
        logger.warning(f"[safe_api_call:{op_label}] error: {err}")
    raise err


# =============================================================================
#  SECTION 10 — BOOT ORCHESTRATOR + TRUTH SEAL (from scalp_pack P22/P24)
# =============================================================================

class TruthSeal:
    """Mandatory direct-fetch of balance before LIVE gate opens."""

    @staticmethod
    async def mandatory_direct_fetch(exchange, retries: int = 5, timeout_sec: float = 15.0) -> bool:
        # v4.2.1 UNBLOCK-PATCH — retries 3→5: a single API blip at boot was
        # enough to halt the whole pipeline. After attempt 3 we cross-check
        # against the BalanceReconciler CACHE (if fresh) instead of failing
        # blind; final failure still fails closed (LIVE_BLOCKED upstream).
        for attempt in range(1, retries + 1):
            try:
                bal = await asyncio.wait_for(
                    safe_api_call(
                        "truthseal_fetch_balance",
                        lambda: exchange.fetch_balance(),
                        retry_safe=True,
                    ),
                    timeout=timeout_sec,
                )
                free, _used, _total = _v702_a39_extract_usdt_balance(bal)
                min_accept = float(CONFIG.get("BALANCE_MIN_ACCEPT_USDT", 5.0))
                if free >= min_accept:
                    ok = BalanceReconciler.seal_real(free, source="truthseal_direct_fetch")
                    if ok:
                        logger.info(f"[TruthSeal] SEALED free={free:.4f}")
                        return True
                logger.warning(
                    f"[TruthSeal] attempt {attempt}/{retries}: free={free:.4f} < min_accept={min_accept}"
                )
            except Exception as e:
                logger.warning(f"[TruthSeal] attempt {attempt}/{retries} failed: {e}")
            # v4.2.1 UNBLOCK-PATCH — after the 3rd failed attempt, cross-check
            # against a FRESH BalanceReconciler REAL/CACHE value before giving
            # up. This absorbs transient boot-time API blips without weakening
            # the seal: the cross-check only succeeds if the reconciler holds
            # a recent REAL reading >= min_accept. Final failure still returns
            # False (fail-closed => LIVE_BLOCKED upstream). REAL/CACHE/BLOCK
            # semantics themselves are untouched.
            if attempt >= 3:
                try:
                    _ts_cache_val = float(getattr(BalanceReconciler, "_last_real_value", 0.0) or 0.0)
                    _ts_cache_ts = float(getattr(BalanceReconciler, "_last_real_ts", 0.0) or 0.0)
                    _ts_ttl = float(CONFIG.get("BALANCE_CACHE_TTL_SEC", 45))
                    _ts_min = float(CONFIG.get("BALANCE_MIN_ACCEPT_USDT", 5.0))
                    if (_ts_cache_ts > 0
                            and (MONO_NOW() - _ts_cache_ts) <= max(_ts_ttl, 60.0)
                            and _ts_cache_val >= _ts_min):
                        ok = BalanceReconciler.seal_real(
                            _ts_cache_val, source="truthseal_cache_crosscheck")
                        if ok:
                            logger.warning(
                                f"[TruthSeal] sealed via CACHE cross-check "
                                f"free={_ts_cache_val:.4f} age={MONO_NOW()-_ts_cache_ts:.1f}s")
                            return True
                except Exception as _ts_cc_e:
                    logger.debug(f"[TruthSeal] cache cross-check suppressed: {_ts_cc_e}")
            await asyncio.sleep(min(2.0 * attempt, 8.0))
        return False



class ProductionCapabilityGate:
    """
    v4.4 production certification gate.

    This gate never submits a real order. It proves that the installed CCXT/MEXC
    adapter exposes the execution primitives required by the live lifecycle:
      - authenticated spot market access
      - market buy/sell
      - trigger/stop-market capability
      - fetch/cancel order lifecycle
      - valid active USDT spot symbols
      - required precision/limits metadata
    Any uncertainty blocks FULL_LIVE_RUNNING.
    """
    _checked = False
    _stop_mode = None
    _details: Dict[str, Any] = {}

    @classmethod
    def stop_mode(cls) -> Optional[str]:
        return cls._stop_mode

    @classmethod
    def snapshot(cls) -> Dict[str, Any]:
        return dict(cls._details)

    @classmethod
    def _feature_value(cls, exchange, symbol: str, path: str) -> Optional[bool]:
        try:
            fn = getattr(exchange, "feature_value", None)
            if callable(fn):
                val = fn(symbol, "createOrder", path)
                if isinstance(val, bool):
                    return val
        except Exception as exc:
            logger.debug(f"[ProdGate] feature_value({path}) unavailable: {exc}")
        try:
            features = getattr(exchange, "features", None) or {}
            spot = features.get("spot") or features.get("default") or {}
            create_order = spot.get("createOrder") or {}
            cur: Any = create_order
            for part in str(path).split("."):
                if not isinstance(cur, dict):
                    return None
                cur = cur.get(part)
            return cur if isinstance(cur, bool) else None
        except Exception as exc:
            logger.debug(f"[ProdGate] feature tree lookup({path}) unavailable: {exc}")
            return None

    @classmethod
    def _detect_stop_mode(cls, exchange, symbol: str) -> Optional[str]:
        """Detect only *explicitly certified* server-side stop support.

        A callable helper is not evidence that the venue actually supports a
        spot trigger endpoint. This distinction is critical for MEXC spot: a
        generic CCXT stop helper may exist while the adapter advertises no spot
        trigger/stop capability. In that case the safe live mode is the
        hardened local software-SL path, not a BUY->unverified-stop->SELL loop.
        """
        has_flag = getattr(exchange, "has", {}) or {}

        # v4.5.70 ROOT FIX: MEXC Spot native trigger semantics are not trusted
        # merely because the CCXT adapter exposes a generic capability flag.
        # Force the proven software watchdog unless native stops are explicitly
        # opted back in by the operator.
        ex_id = str(getattr(exchange, "id", "") or "").lower()
        if ex_id == "mexc" and bool(CONFIG.get("V570_MEXC_FORCE_SOFTWARE_SL", True)):
            try:
                market = exchange.market(symbol) or {}
                if bool(market.get("spot")):
                    if bool(CONFIG.get("LIVE_ENTRY_ALLOW_SOFTWARE_SL_FALLBACK", True)):
                        return "software_sl_only"
                    return None
            except Exception:
                return None

        # Strongest evidence: explicit adapter capability flag.
        if has_flag.get("createStopMarketOrder") is True:
            return "dedicated_stop_market"

        # Next: explicit per-symbol feature support.
        sl_support = cls._feature_value(exchange, symbol, "stopLossPrice")
        if sl_support is True:
            return "create_order_stoploss_market"

        trig_support = cls._feature_value(exchange, symbol, "triggerPrice")
        if trig_support is True:
            return "create_order_trigger_market"

        # MEXC SPOT currently exposes no explicit CCXT trigger capability.
        # Allow a truthful software-only live protection mode when enabled.
        ex_id = str(getattr(exchange, "id", "") or "").lower()
        try:
            market = exchange.market(symbol) or {}
            is_spot = bool(market.get("spot"))
        except Exception:
            is_spot = False
        if ex_id == "mexc" and is_spot and bool(CONFIG.get("LIVE_ENTRY_ALLOW_SOFTWARE_SL_FALLBACK", True)):
            return "software_sl_only"

        # For any other venue, absence of explicit native support remains a
        # hard production-capability failure.
        return None

    @classmethod
    async def validate(cls, exchange, universe: Optional[List[str]] = None) -> bool:
        try:
            if str(getattr(exchange, "id", "")).lower() != "mexc":
                raise RuntimeError(f"unexpected_exchange:{getattr(exchange, 'id', None)}")

            has = getattr(exchange, "has", {}) or {}
            required_methods = (
                "fetchBalance",
                "fetchOrder",
                "cancelOrder",
                "fetchOpenOrders",
                "createMarketOrder",
            )
            missing = [k for k in required_methods if has.get(k) is False]
            if missing:
                raise RuntimeError("missing_exchange_capabilities:" + ",".join(missing))

            # Python convenience wrappers must exist for this codebase.
            wrappers = (
                "create_market_buy_order",
                "create_market_sell_order",
                "fetch_order",
                "cancel_order",
                "fetch_open_orders",
            )
            missing_wrappers = [m for m in wrappers if not callable(getattr(exchange, m, None))]
            if missing_wrappers:
                raise RuntimeError("missing_ccxt_wrappers:" + ",".join(missing_wrappers))

            # Determine a concrete spot symbol for stop capability validation.
            symbols = list(universe or [])
            if not symbols:
                symbols = ["BTC/USDT"]
            selected = None
            for sym in symbols:
                m = exchange.markets.get(sym) if hasattr(exchange, "markets") else None
                if m and m.get("spot") and m.get("active", True):
                    selected = sym
                    break
            if selected is None:
                raise RuntimeError("no_valid_active_spot_symbol")

            mode = cls._detect_stop_mode(exchange, selected)
            if not mode:
                raise RuntimeError(
                    "no_verified_stop_market_capability:"
                    "explicit_native_stop_or_enabled_software_sl_required"
                )
            if mode == "software_sl_only" and not bool(CONFIG.get("LIVE_ENTRY_ALLOW_SOFTWARE_SL_FALLBACK", True)):
                raise RuntimeError("software_sl_only_disabled")
            if mode == "software_sl_only" and not bool(CONFIG.get("POSITION_MANAGER_TASK_ENABLE", True)):
                # Software SL is only safe when the dedicated high-frequency
                # position manager is explicitly enabled. Never permit a
                # configuration that can create an unprotected fill simply
                # because the scanner happens to be busy.
                raise RuntimeError("software_sl_requires_dedicated_position_manager")

            # Require real market metadata for safe normalization.
            market = exchange.market(selected)
            if not market or not market.get("spot"):
                raise RuntimeError(f"symbol_not_spot:{selected}")
            if market.get("active") is False:
                raise RuntimeError(f"symbol_inactive:{selected}")
            if str(market.get("quote") or "").upper() != "USDT":
                raise RuntimeError(f"symbol_quote_not_USDT:{selected}")

            # Public exchange time is a harmless connectivity/latency sanity check.
            try:
                await safe_api_call("production_gate_exchange_time",
                                     exchange.fetch_time)
            except Exception:
                # fetch_time is not a hard dependency; market/balance/order lifecycle
                # checks above are the actual gate.
                pass

            cls._stop_mode = mode
            cls._details = {
                "exchange": str(getattr(exchange, "id", "")),
                "symbol": selected,
                "stop_mode": mode,
                "market_count": len(getattr(exchange, "markets", {}) or {}),
                "fetch_balance": bool(has.get("fetchBalance") is not False),
                "fetch_order": bool(has.get("fetchOrder") is not False),
                "cancel_order": bool(has.get("cancelOrder") is not False),
                "fetch_open_orders": bool(has.get("fetchOpenOrders") is not False),
                "create_market_order": bool(has.get("createMarketOrder") is not False),
                "protection_mode": mode,
            }
            cls._checked = True
            logger.info(f"[ProdGate] ✅ production capability check passed: {cls._details}")
            return True
        except Exception as exc:
            cls._checked = False
            cls._stop_mode = None
            cls._details = {"error": str(exc)}
            logger.critical(f"[ProdGate] BLOCKED: {exc}")
            return False



_V702_SOURCE_TEXT_CACHE = None

def _v702_read_source_text() -> str:
    """Return the immutable source text for this running release.

    The bot performs many static self-contract checks during startup. Re-reading
    the same multi-megabyte module for every check adds avoidable I/O latency;
    this cache is process-local and requires a restart after code deployment.
    """
    global _V702_SOURCE_TEXT_CACHE
    if _V702_SOURCE_TEXT_CACHE is not None:
        return _V702_SOURCE_TEXT_CACHE
    try:
        with open(__file__, "r", encoding="utf-8", errors="replace") as _fh:
            _V702_SOURCE_TEXT_CACHE = _fh.read()
    except Exception:
        _V702_SOURCE_TEXT_CACHE = ""
    return _V702_SOURCE_TEXT_CACHE

_V702_SOURCE_LINES_CACHE = None

def _v699_cached_universe_fallback(run_bot: Any, fallback_n: int) -> List[str]:
    """Return only a bounded, previously retained universe; never invent one."""
    try:
        limit = max(1, min(1000, int(fallback_n)))
        cached = list(getattr(run_bot, "_liq_universe", []) or [])[:limit]
    except Exception:
        cached = []
    if cached:
        STATS["v699_universe_last_fallback_state"] = "CACHED_FALLBACK"
        STATS["v699_universe_last_fallback_reason"] = "source_refresh_failed"
        return cached
    STATS["v699_universe_last_fallback_state"] = "EMPTY"
    STATS["v699_universe_last_fallback_reason"] = "source_failed_and_no_cached_universe"
    return []


def _v702_runtime_function_source(fn: Any) -> str:
    """Return only a callable's source span without parsing the 100k-line module.

    inspect.getsource() calls inspect.findsource(), which AST-parses the complete
    module for line discovery. Startup self-tests need only a bounded snippet;
    derive its end from the callable's code-object line table instead.
    """
    global _V702_SOURCE_LINES_CACHE
    try:
        target = getattr(fn, "__func__", fn)
        code = getattr(target, "__code__", None)
        if code is None:
            return ""
        if _V702_SOURCE_LINES_CACHE is None:
            _V702_SOURCE_LINES_CACHE = _v702_read_source_text().splitlines(keepends=True)
        lines = _V702_SOURCE_LINES_CACHE
        start = max(1, int(code.co_firstlineno))
        end = start
        pending = [code]
        seen = set()
        while pending:
            current = pending.pop()
            if id(current) in seen:
                continue
            seen.add(id(current))
            try:
                for _byte_start, _byte_end, lineno in current.co_lines():
                    if lineno is not None:
                        end = max(end, int(lineno))
            except Exception:
                end = max(end, start)
            for const in current.co_consts:
                if hasattr(const, "co_lines") and hasattr(const, "co_consts"):
                    pending.append(const)
        if start > len(lines):
            return ""
        # Python code line tables point to the final executable line. Include
        # one additional physical line for a trailing decorator/continuation.
        return "".join(lines[start - 1:min(len(lines), end + 1)])
    except Exception:
        return ""


def _v702_iter_named_call_segments(source: str, call_name: str):
    """Yield only individual calls named *call_name* without building a file AST.

    Tokenization streams through the source and ignores comments/string content.
    This keeps static safety audits proportional to the relevant call snippets,
    rather than materializing a multi-hundred-megabyte AST for a 5+ MB module.
    """
    _lines = source.splitlines(keepends=True)
    _active = []
    _pending = None
    _previous_sig = None
    _ignore = {tokenize.NL, tokenize.NEWLINE, tokenize.COMMENT, tokenize.INDENT,
               tokenize.DEDENT, tokenize.ENCODING}

    def _segment(_start, _end):
        _sl, _sc = _start
        _el, _ec = _end
        if _sl < 1 or _el < _sl or _el > len(_lines):
            return ""
        if _sl == _el:
            return _lines[_sl - 1][_sc:_ec]
        return "".join([_lines[_sl - 1][_sc:], *_lines[_sl:_el - 1], _lines[_el - 1][:_ec]])

    for _tok in tokenize.generate_tokens(io.StringIO(source).readline):
        if _pending is not None and _tok.type in _ignore:
            continue
        if _pending is not None:
            if _tok.type == tokenize.OP and _tok.string == "(":
                for _ctx in _active:
                    _ctx["depth"] += 1
                _active.append({"depth": 1, "start": _pending})
            _pending = None
        elif _tok.type == tokenize.OP and _tok.string in ("(", "[", "{"):
            for _ctx in _active:
                _ctx["depth"] += 1
        elif _tok.type == tokenize.OP and _tok.string in (")", "]", "}"
        ):
            _completed = []
            for _ctx in _active:
                _ctx["depth"] -= 1
                if _ctx["depth"] == 0:
                    _completed.append(_ctx)
            if _completed:
                _active = [_ctx for _ctx in _active if _ctx["depth"] > 0]
                for _ctx in _completed:
                    _piece = _segment(_ctx["start"], _tok.end)
                    if _piece:
                        yield _piece
        if (_tok.type == tokenize.NAME and _tok.string == call_name
                and _previous_sig != (tokenize.NAME, "def")):
            _pending = _tok.start
        if _tok.type not in _ignore:
            _previous_sig = (_tok.type, _tok.string)


def _v702_count_assignment_targets(source: str) -> Dict[str, int]:
    """Count the three canonical assignment targets using streaming tokens."""
    _counts = {"validate_config": 0, "SignalBuilder.build_and_route": 0,
               "OrderExecutor.submit_entry": 0}
    _sig = []
    _ignored = {tokenize.NL, tokenize.NEWLINE, tokenize.COMMENT, tokenize.INDENT,
                tokenize.DEDENT, tokenize.ENCODING}
    for _tok in tokenize.generate_tokens(io.StringIO(source).readline):
        if _tok.type in _ignored:
            continue
        _sig.append((_tok.type, _tok.string))
        if len(_sig) > 4:
            _sig.pop(0)
        if len(_sig) >= 2 and _sig[-2:] == [(tokenize.NAME, "validate_config"), (tokenize.OP, "=")]:
            _counts["validate_config"] += 1
        if len(_sig) >= 4:
            _tail = _sig[-4:]
            if _tail == [(tokenize.NAME, "SignalBuilder"), (tokenize.OP, "."),
                         (tokenize.NAME, "build_and_route"), (tokenize.OP, "=")]:
                _counts["SignalBuilder.build_and_route"] += 1
            elif _tail == [(tokenize.NAME, "OrderExecutor"), (tokenize.OP, "."),
                           (tokenize.NAME, "submit_entry"), (tokenize.OP, "=")]:
                _counts["OrderExecutor.submit_entry"] += 1
    return _counts


def _v702_release_startup_memory() -> None:
    """Collect temporary validator allocations after fail-closed startup checks.

    Source text remains cached for lightweight runtime diagnostics.  This
    best-effort cleanup is not part of trading logic; failure to collect or
    trim memory must never affect startup or execution safety.
    """
    try:
        gc.collect()
    except Exception:
        pass
    if sys.platform.startswith("linux"):
        try:
            import ctypes as _ctypes
            _libc = _ctypes.CDLL(None)
            _trim = getattr(_libc, "malloc_trim", None)
            if _trim is not None:
                _trim.argtypes = [_ctypes.c_size_t]
                _trim.restype = _ctypes.c_int
                _trim(0)
        except Exception:
            # malloc_trim is glibc-specific and is not required for correctness.
            pass

class ConfigValidators:
    """Fail-closed startup invariant checks."""

    @staticmethod
    def tp_invariant_check() -> None:
        """
        Exit-percentage invariant — fail-closed at boot.
          Runner OFF:  TP1_EXIT_PCT + TP2_EXIT_PCT              == 1.0
          Runner ON:   TP1_EXIT_PCT + TP2_EXIT_PCT + RUNNER_KEEP == 1.0
        """
        if not CONFIG.get("V4_TP_INVARIANT_CHECK", True):
            return
        try:
            tp1 = float(CONFIG["TP1_EXIT_PCT"])
            tp2 = float(CONFIG["TP2_EXIT_PCT"])
            runner_on = bool(CONFIG.get("ENABLE_RUNNER_MODE", False))
            runner_keep = float(CONFIG.get("RUNNER_KEEP_PCT_AT_TP3", 0.0)) if runner_on else 0.0
        except Exception:
            logger.critical("[Config] TP exit pcts non-numeric — refusing to start")
            raise SystemExit("tp_invariant_non_numeric")
        tol = float(CONFIG.get("V4_TP_INVARIANT_TOLERANCE", 0.001))
        total = tp1 + tp2 + runner_keep
        if abs(total - 1.0) > tol:
            mode_desc = (f"TP1={tp1} + TP2={tp2} + RUNNER_KEEP={runner_keep} "
                         if runner_on else f"TP1={tp1} + TP2={tp2} ")
            msg = (f"TP invariant violated: {mode_desc}= {total:.6f} (expected 1.0 ± {tol})")
            logger.critical(msg)
            if bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and not bool(CONFIG.get("PAPER_TRADING_MODE", False)):
                raise SystemExit(f"tp_invariant_violation:{total:.6f}")
            else:
                logger.warning("[Config] non-live mode — continuing despite TP invariant violation")
        else:
            parts = f"TP1={tp1}, TP2={tp2}"
            if runner_on:
                parts += f", RUNNER_KEEP={runner_keep}"
            logger.info(f"[Config] TP invariant OK ({parts}, sum={total:.6f})")

    @staticmethod
    def secrets_check_live() -> None:
        if bool(CONFIG.get("PAPER_TRADING_MODE", False)):
            return
        if not bool(CONFIG.get("ENABLE_LIVE_TRADING", True)):
            return
        if not ENV.get("MEXC_API_KEY") or not ENV.get("MEXC_API_SECRET"):
            logger.critical("[Config] LIVE mode requires MEXC_API_KEY + MEXC_API_SECRET env vars")
            raise SystemExit("missing_exchange_secrets")

    @staticmethod
    def config_summary() -> None:
        logger.info(
            "[Config] MODE=%s RISK=%.2f%% MAX_SL=%.2f%% TP1_RR=%.2f TP2_RR=%.2f "
            "MIN_LIVE_SCORE=%s SIZING=%s",
            "LIVE" if bool(CONFIG["ENABLE_LIVE_TRADING"]) and not bool(CONFIG["PAPER_TRADING_MODE"]) else "PAPER",
            CONFIG["RISK_PER_TRADE_PCT"], CONFIG["MAX_SL_PCT"],
            CONFIG["TP1_RR"], CONFIG["TP2_RR"],
            CONFIG["MIN_LIVE_SCORE"], CONFIG["POSITION_SIZING_MODE"],
        )


class WithdrawalIsolation:
    """v4.0.2 PATCH D: default = HARD_BLOCK. ADVISORY requires explicit
    env override WITHDRAWAL_POLICY_OVERRIDE=ADVISORY."""

    @staticmethod
    def decide_policy() -> str:
        # Fail-closed: unknown / missing config => HARD_BLOCK
        pol = str(CONFIG.get("WITHDRAWAL_POLICY", "HARD_BLOCK")).upper()
        if pol not in ("ADVISORY", "HARD_BLOCK", "LEGACY_STRICT"):
            pol = "HARD_BLOCK"
        # Guard: refuse ADVISORY in LIVE unless env override was explicitly set
        is_live = bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and \
                  not bool(CONFIG.get("PAPER_TRADING_MODE", False))
        if pol == "ADVISORY" and is_live:
            ov = ENV.get("WITHDRAWAL_POLICY_OVERRIDE") if isinstance(ENV, dict) else None
            if not ov or str(ov).strip().upper() != "ADVISORY":
                logger.critical(
                    "[Withdraw] ADVISORY requested in LIVE without explicit env "
                    "override — forcing HARD_BLOCK (fail-closed)."
                )
                pol = "HARD_BLOCK"
        logger.info(f"[Withdraw] policy={pol}")
        return pol

    @staticmethod
    def strip_advisory_block_reasons(reason: Optional[str]) -> Optional[str]:
        """Only strips when policy is ADVISORY (explicit override in live)."""
        if reason is None:
            return None
        pol = WithdrawalIsolation.decide_policy()
        if pol != "ADVISORY":
            return reason
        blocked = ("withdraw_permission_risk", "withdraw_enabled_block")
        if any(b in reason for b in blocked):
            logger.info(f"[Withdraw] stripping advisory block reason: {reason}")
            return None
        return reason


class BootOrchestrator:
    """Enforces: no LIVE trading until all production capability gates pass."""

    @staticmethod
    async def run_preflight(exchange, universe: Optional[List[str]] = None) -> bool:
        LiveStateMachine.transition("CONNECTING")

        # Kill switch pre-check
        if KillSwitch.is_active():
            LiveStateMachine.block("kill_switch_active", where="BootOrchestrator")
            return False

        # Config invariants (raise SystemExit if violated in LIVE)
        ConfigValidators.secrets_check_live()
        ConfigValidators.tp_invariant_check()
        ConfigValidators.config_summary()

        # Production hard-gates are mandatory for real money.
        is_live = bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and not bool(CONFIG.get("PAPER_TRADING_MODE", False))
        if is_live and str(ENV.get("PRODUCTION_HARD_GATES", "1")).strip() != "1":
            LiveStateMachine.block("production_hard_gates_disabled", where="BootOrchestrator")
            return False

        LiveStateMachine.transition("AUTHENTICATING")

        # Try to load markets
        try:
            await safe_api_call("load_markets", exchange.load_markets)
            LiveStateMachine.transition("MARKETS_READY")
        except Exception as e:
            LiveStateMachine.block(f"load_markets_failed:{e}", where="BootOrchestrator")
            return False

        # Truth seal (BALANCE_VERIFIED)
        sealed = await TruthSeal.mandatory_direct_fetch(exchange)
        if not sealed:
            LiveStateMachine.block("truth_seal_failed", where="BootOrchestrator")
            return False
        LiveStateMachine.transition("BALANCE_VERIFIED")

        # Production execution capability certification.
        if is_live:
            if not await ProductionCapabilityGate.validate(exchange, universe):
                LiveStateMachine.block(
                    "production_capability_gate_failed",
                    where="BootOrchestrator",
                )
                return False

        policy = WithdrawalIsolation.decide_policy()
        logger.info(f"[Boot] withdrawal_policy={policy}")

        LiveStateMachine.transition("PRECHECK_READY")
        LiveStateMachine.transition("LIVE_READY")

        # Final re-checks immediately before opening the order-submission state.
        if KillSwitch.is_active():
            LiveStateMachine.block("kill_switch_active", where="BootOrchestrator.final")
            return False
        if is_live and not ProductionCapabilityGate._checked:
            LiveStateMachine.block("production_capability_not_certified", where="BootOrchestrator.final")
            return False

        LiveStateMachine.transition("FULL_LIVE_RUNNING")
        logger.info(
            "[Boot] ✅ Preflight complete. FULL_LIVE_RUNNING "
            "stop_mode=%s",
            ProductionCapabilityGate.stop_mode(),
        )
        return True


