# V702 FINAL — canonical exit contract helpers.  The snapshot is immutable
# provenance for the geometry that reached execution/protection.  Dynamic BE or
# trailing changes may update TradeState.current_sl, but they never rewrite the
# approved entry/fill/TP contract stored here.
def _v702_make_exit_snapshot(*, final_entry: float, final_sl: float, final_tp1: float,
                             final_tp2: float, final_tp3: float, exit_profile: Any,
                             source: str = "FINAL_BUILDER", fill_px: Optional[float] = None) -> Dict[str, Any]:
    entry = float(final_entry); sl = float(final_sl)
    tp1 = float(final_tp1); tp2 = float(final_tp2); tp3 = float(final_tp3)
    if not all(math.isfinite(v) and v > 0 for v in (entry, sl, tp1, tp2, tp3)):
        raise ValueError("canonical_exit_nonfinite")
    if not (entry > sl and sl < entry < tp1 < tp2 < tp3):
        raise ValueError("canonical_exit_geometry_invalid")
    r = max(entry - sl, 1e-12)
    rr1 = (tp1-entry)/r; rr2 = (tp2-entry)/r; rr3 = (tp3-entry)/r
    if not all(math.isfinite(v) and v > 0 for v in (rr1, rr2, rr3)):
        raise ValueError("canonical_exit_rr_invalid")
    ep = exit_profile
    ep_id = ""
    try:
        ep_id = (
            f"{str(getattr(ep,'strategy_mode','') or '').upper()}"
            f":{float(getattr(ep,'tp1_rr',rr1)):.6g}"
            f"/{float(getattr(ep,'tp2_rr',rr2)):.6g}"
            f"/{float(getattr(ep,'tp3_rr',rr3)):.6g}"
        )
    except Exception:
        ep_id = "UNKNOWN"
    return {
        "final_entry": entry, "final_sl": sl,
        "final_tp1": tp1, "final_tp2": tp2, "final_tp3": tp3,
        "rr1": rr1, "rr2": rr2, "rr3": rr3,
        "exit_profile_id": ep_id,
        "source": str(source or "FINAL_BUILDER")[:80],
        "fill_px": float(fill_px) if fill_px is not None and math.isfinite(float(fill_px)) else None,
        "created_mono": MONO_NOW(), "created_wall": WALL_NOW(),
    }

def _v702_exit_snapshot_for_trade(trade: Any) -> Dict[str, Any]:
    snap = getattr(trade, "canonical_exit_snapshot", None)
    if isinstance(snap, dict) and snap.get("final_entry"):
        return snap
    return _v702_make_exit_snapshot(
        final_entry=float(getattr(trade,"effective_entry",0.0) or getattr(trade,"entry",0.0) or 0.0),
        final_sl=float(getattr(trade,"current_sl",0.0) or getattr(trade,"original_sl",0.0) or 0.0),
        final_tp1=float(getattr(trade,"tp1",0.0) or 0.0),
        final_tp2=float(getattr(trade,"tp2",0.0) or 0.0),
        final_tp3=float(getattr(trade,"tp3",0.0) or 0.0),
        exit_profile=getattr(trade,"exit_profile",{}) or {},
        source="TRADE_STATE_FALLBACK",
        fill_px=float(getattr(trade,"entry_fill_price",0.0) or 0.0) or None,
    )


# =============================================================================
#  SECTION 12 — INDICATORS (fail-soft: use pandas_ta if available, else inline)
# =============================================================================

class Indicators:

    @staticmethod
    def ema(series, period: int):
        if _PDNP_OK:
            return series.ewm(span=period, adjust=False).mean()
        # Very simple fallback (not used in production)
        out = []
        alpha = 2 / (period + 1)
        prev = None
        for x in series:
            prev = x if prev is None else (alpha * x + (1 - alpha) * prev)
            out.append(prev)
        return out

    @staticmethod
    def rsi(series, period: int = 14):
        # v4.0.2 PATCH D: no silent swallowing; failure tagged in STATS
        try:
            if _PTA_OK:
                return pta.rsi(series, length=period)
            if not _PDNP_OK:
                STATS["indicator_calc_unavailable_rsi"] = \
                    STATS.get("indicator_calc_unavailable_rsi", 0) + 1
                return None
        except (ValueError, TypeError, KeyError, AttributeError) as e:
            STATS["indicator_calc_error_rsi"] = STATS.get("indicator_calc_error_rsi", 0) + 1
            logger.debug(f"[Indicators.rsi] error: {e}")
            return None
        delta = series.diff()
        up = delta.clip(lower=0).rolling(period, min_periods=period).mean()
        dn = -delta.clip(upper=0).rolling(period, min_periods=period).mean()
        # Canonical fail-closed RSI fallback: zero-loss/zero-gain windows are
        # valid market states, not missing data.  Avoid NaN in monotonic trends
        # while keeping the standard bounds: gain-only=>100, loss-only=>0,
        # flat=>50.  This prevents false `indicator unavailable`/overextension
        # decisions in long trends when pandas_ta is not installed.
        rs = up.div(dn.replace(0, np.nan))
        out = 100 - (100 / (1 + rs))
        out = out.where(~((dn == 0) & (up > 0)), 100.0)
        out = out.where(~((up == 0) & (dn > 0)), 0.0)
        out = out.where(~((up == 0) & (dn == 0)), 50.0)
        return out

    @staticmethod
    def atr(df, period: int = 14):
        if _PTA_OK:
            return pta.atr(df["high"], df["low"], df["close"], length=period)
        if not _PDNP_OK:
            return None
        h_l = df["high"] - df["low"]
        h_c = (df["high"] - df["close"].shift()).abs()
        l_c = (df["low"] - df["close"].shift()).abs()
        tr = pd.concat([h_l, h_c, l_c], axis=1).max(axis=1)
        return tr.rolling(period).mean()

    @staticmethod
    def adx(df, period: int = 14):
        if _PTA_OK:
            try:
                out = pta.adx(df["high"], df["low"], df["close"], length=period)
                # pandas_ta returns DataFrame w/ ADX_<period>
                col = f"ADX_{period}"
                return out[col] if col in out.columns else out.iloc[:, 0]
            except Exception:
                _v647_record_suppressed_exception()
        return None


    # v4.2.2 - session-agnostic rolling VWAP (typical price * volume).
    # Fail-closed: callers treat None as "anchor unavailable". Used ONLY
    # as an additional pullback anchor / near-miss metric; never creates a
    # signal by itself.
    @staticmethod
    def vwap(df):
        try:
            if not _PDNP_OK or df is None or len(df) < 5:
                return None
            tp = (df["high"] + df["low"] + df["close"]) / 3.0
            vol = df["volume"].astype(float)
            cum_pv = (tp * vol).rolling(20).sum()
            cum_v = vol.rolling(20).sum().replace(0, np.nan)
            return cum_pv / cum_v
        except Exception:
            return None


# =============================================================================
#  SECTION 13 — LIQUIDITY TIER CLASSIFIER (from htf_pullback)
# =============================================================================

class LiquidityTier:
    MAJORS, LARGE, MID, MICRO, BELOW = "MAJORS", "LARGE", "MID", "MICRO", "BELOW"

    @staticmethod
    def classify(quote_volume_24h: float) -> str:
        q = float(quote_volume_24h or 0.0)
        if q >= CONFIG["TIER_MAJORS_MIN"]:
            return LiquidityTier.MAJORS
        if q >= CONFIG["TIER_LARGE_MIN"]:
            return LiquidityTier.LARGE
        if q >= CONFIG["TIER_MID_MIN"]:
            return LiquidityTier.MID
        if q >= CONFIG["TIER_BELOW_FLOOR"]:
            return LiquidityTier.MICRO
        return LiquidityTier.BELOW

    @staticmethod
    def score_points(tier: str) -> float:
        return {"MAJORS": 5.0, "LARGE": 4.0, "MID": 3.0, "MICRO": 1.5, "BELOW": 0.0}.get(tier, 0.0)

    @staticmethod
    def is_tradeable(tier: str) -> bool:
        return tier != LiquidityTier.BELOW


def _v702_normalize_liquidity_tier(raw_tier: Any, quote_volume_24h: Any) -> Optional[str]:
    """Normalize explicit tier metadata; unknown labels are not permission to trade."""
    try:
        if raw_tier is None or not str(raw_tier).strip():
            if quote_volume_24h is None:
                return None
            quote_volume = float(quote_volume_24h)
            if not math.isfinite(quote_volume) or quote_volume < 0.0:
                return None
            tier = str(LiquidityTier.classify(quote_volume)).strip().upper()
        else:
            tier = str(raw_tier).strip().upper()
        valid = {LiquidityTier.MAJORS, LiquidityTier.LARGE, LiquidityTier.MID,
                 LiquidityTier.MICRO, LiquidityTier.BELOW}
        return tier if tier in valid else None
    except Exception:
        return None


# =============================================================================
#  SECTION 14 — MARKET REGIME (with hysteresis) + BTC CONTEXT
# =============================================================================

class MarketRegime:
    _last_regime: str = "NEUTRAL"
    _pending_regime: str = "NEUTRAL"
    _pending_bars: int = 0
    # v4.0.2 PATCH E.4 — dwell tracking + last-pct snapshot for observability
    _last_shift_ts: float = 0.0
    _last_pct: float = 0.0
    _hysteresis_blocks: int = 0   # counts flip-flops suppressed by dwell/hyst.

    @classmethod
    def _classify_legacy(cls, pct: float) -> str:
        """Original single-threshold classifier (kept for fallback)."""
        bull = float(CONFIG["REGIME_BULL_THRESHOLD_PCT"])
        bear = float(CONFIG["REGIME_BEAR_THRESHOLD_PCT"])
        return "BULLISH" if pct > bull else ("BEARISH" if pct < bear else "NEUTRAL")

    @classmethod
    def _classify_hysteresis(cls, pct: float) -> str:
        """
        v4.0.2 PATCH E.4 — asymmetric enter/exit thresholds.
        The candidate returned here is a *proposal*; dwell + confirm-bars are
        applied by the caller before it becomes the effective regime.
        """
        cur = cls._last_regime
        bull_enter = float(CONFIG.get("REGIME_BULL_ENTER_PCT", 0.80))
        bull_exit = float(CONFIG.get("REGIME_BULL_EXIT_PCT", 0.30))
        bear_enter = float(CONFIG.get("REGIME_BEAR_ENTER_PCT", -0.80))
        bear_exit = float(CONFIG.get("REGIME_BEAR_EXIT_PCT", -0.30))

        if cur == "BEARISH":
            # only exit BEARISH if pct rises above the (less strict) exit level
            if pct >= bear_exit:
                return "BULLISH" if pct > bull_enter else "NEUTRAL"
            return "BEARISH"
        if cur == "BULLISH":
            if pct <= bull_exit:
                return "BEARISH" if pct < bear_enter else "NEUTRAL"
            return "BULLISH"
        # cur == NEUTRAL: entering a directional regime requires the stricter enter level
        if pct < bear_enter:
            return "BEARISH"
        if pct > bull_enter:
            return "BULLISH"
        return "NEUTRAL"

    @classmethod
    def classify_from_btc_4h(cls, df_btc_4h) -> str:
        if not _PDNP_OK or df_btc_4h is None or len(df_btc_4h) < 210:
            return cls._last_regime
        ema200 = Indicators.ema(df_btc_4h["close"], 200)
        last_close = float(df_btc_4h["close"].iloc[-1])
        last_ema = float(ema200.iloc[-1])
        pct = (last_close - last_ema) / last_ema * 100.0
        cls._last_pct = pct

        # v4.0.2 PATCH E.4 — pick classifier
        if bool(CONFIG.get("REGIME_HYSTERESIS_ENABLE", True)):
            cand = cls._classify_hysteresis(pct)
        else:
            cand = cls._classify_legacy(pct)

        # Pending-bars confirm (unchanged semantics)
        if cand == cls._pending_regime:
            cls._pending_bars += 1
        else:
            cls._pending_regime = cand
            cls._pending_bars = 1

        # v4.0.2 PATCH E.4 — enforce minimum dwell time between shifts
        now = MONO_NOW()
        dwell = float(CONFIG.get("REGIME_MIN_DWELL_SEC", 0))
        confirmed = cls._pending_bars >= int(CONFIG["REGIME_CONFIRM_BARS"])
        want_shift = (cand != cls._last_regime) and confirmed

        if want_shift and dwell > 0 and cls._last_shift_ts > 0 \
                and (now - cls._last_shift_ts) < dwell:
            # Suppress the shift — not enough dwell time in current regime
            cls._hysteresis_blocks += 1
            STATS["regime_hysteresis_blocks"] = \
                STATS.get("regime_hysteresis_blocks", 0) + 1
            return cls._last_regime

        if want_shift:
            logger.info(
                f"[Regime] shift {cls._last_regime} -> {cand} "
                f"(pct={pct:.2f}% dwell_ok=True)"
            )
            cls._last_regime = cand
            cls._last_shift_ts = now
        return cls._last_regime

    @classmethod
    def snapshot(cls) -> Dict[str, Any]:
        """v4.0.2 PATCH E.6 — lightweight regime observability."""
        return {
            "current": cls._last_regime,
            "pending": cls._pending_regime,
            "pending_bars": cls._pending_bars,
            "last_pct": round(cls._last_pct, 3),
            "last_shift_ts": cls._last_shift_ts,
            "seconds_in_regime": (MONO_NOW() - cls._last_shift_ts)
                                  if cls._last_shift_ts > 0 else None,
            "hysteresis_blocks": cls._hysteresis_blocks,
        }


class BTCContext:
    """
    OK / WEAK / CRASH — fail-closed on CRASH.
    Acts as GENERAL market context for ALL symbols (not just BTC).
    If BTC data is unavailable in LIVE mode: configurable fail-closed.
    """

    _state: str = "OK"
    _last_eval_ts: float = 0.0
    _eval_count: int = 0
    _data_available: bool = False

    @classmethod
    def evaluate(cls, df_btc_15m) -> str:
        cls._eval_count += 1
        cls._last_eval_ts = MONO_NOW()
        if not _PDNP_OK or df_btc_15m is None or len(df_btc_15m) < 20:
            cls._data_available = False
            # Fail-closed: in LIVE mode, missing BTC data => cannot evaluate market risk.
            if bool(CONFIG.get("BTC_CONTEXT_FAIL_CLOSED_ON_MISSING", True)) and \
               bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and \
               not bool(CONFIG.get("PAPER_TRADING_MODE", False)):
                # Do NOT fall back to stale "OK" — set BLOCK and let blocks_new_entries catch it.
                cls._state = "BLOCK"
                logger.warning("[BTCContext] No BTC data in LIVE mode — fail-closed (BLOCK)")
                return cls._state
            # Paper mode: use "OK" as neutral default (explicit fallback).
            cls._state = "OK"
            logger.debug("[BTCContext] No BTC data in paper mode — neutral OK fallback")
            return cls._state
        cls._data_available = True
        try:
            # v4.0.5 FIX #6 — slightly wider window + softer thresholds.
            # Reason : the previous 4-candle (~1h) / -2% WEAK / -5% CRASH
            #          setup flipped to WEAK/CRASH too easily on normal noise,
            #          starving live entries.
            # Effect : evaluate over ~2h (8 x 15m) and use -3% WEAK / -6%
            #          CRASH; still fail-closed, just less trigger-happy.
            window = 8 if len(df_btc_15m) >= 9 else min(4, len(df_btc_15m) - 1)
            first = float(df_btc_15m["close"].iloc[-(window + 1)])
            last = float(df_btc_15m["close"].iloc[-1])
            drop_pct = (last - first) / first * 100.0
            if drop_pct <= -6.0:
                cls._state = "CRASH"
            elif drop_pct <= -3.0:
                cls._state = "WEAK"
            else:
                cls._state = "OK"
        except Exception as e:
            cls._data_available = False
            if bool(CONFIG.get("BTC_CONTEXT_FAIL_CLOSED_ON_MISSING", True)) and \
               bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and \
               not bool(CONFIG.get("PAPER_TRADING_MODE", False)):
                cls._state = "BLOCK"
                logger.warning(f"[BTCContext] eval error in LIVE: {e} — fail-closed (BLOCK)")
            else:
                cls._state = "OK"
        return cls._state

    @classmethod
    def blocks_new_entries(cls) -> bool:
        return cls._state in ("CRASH", "BLOCK")

    @classmethod
    def is_data_available(cls) -> bool:
        return cls._data_available

    @classmethod
    def snapshot(cls) -> Dict[str, Any]:
        return {
            "state": cls._state,
            "data_available": cls._data_available,
            "last_eval_ts": cls._last_eval_ts,
            "eval_count": cls._eval_count,
        }


