class HTFGrader:
    """State ∈ {STRICT_BULLISH, NEAR_BULLISH, NEUTRAL, BEARISH}"""

    @staticmethod
    def grade(df, label: str = "") -> Tuple[bool, str, float, str]:
        """Grade only a sufficiently warmed, valid CLOSED-candle history.

        Missing or malformed data is UNKNOWN/ERROR, never a market BEARISH
        verdict. Downstream policy remains fail-closed for UNKNOWN/ERROR.
        """
        if not _PDNP_OK or df is None:
            return False, "UNKNOWN", 0.0, "insufficient_data"
        try:
            required = max(210, int(CONFIG.get("HTF_MIN_CANDLES_1H", 240) or 240))
            if len(df) < required or "close" not in getattr(df, "columns", ()):
                return False, "UNKNOWN", 0.0, "insufficient_data"
            close = pd.to_numeric(df["close"], errors="coerce")
            recent = [float(x) for x in close.iloc[-required:].tolist()]
            if len(recent) < required or any((not math.isfinite(x)) or x <= 0.0 for x in recent):
                return False, "UNKNOWN", 0.0, "invalid_close_history"
            ema50 = Indicators.ema(close, CONFIG["EMA_MID"])
            ema200 = Indicators.ema(close, CONFIG["EMA_SLOW"])
            # Decisions use the last CLOSED candle; the forming candle is not evidence.
            price = float(close.iloc[-2])
            e50 = float(ema50.iloc[-2])
            e200 = float(ema200.iloc[-2])
            if not all(math.isfinite(x) and x > 0.0 for x in (price, e50, e200)):
                return False, "UNKNOWN", 0.0, "invalid_closed_values"
            tol_base = float(CONFIG["EMA200_TOL_BASE"])
            tol_rel = float(CONFIG["EMA200_TOL_RELAXED"])
            price_vs_e200 = (price - e200) / e200
            e50_vs_e200 = (e50 - e200) / e200

            if e50 > e200 and price_vs_e200 >= -tol_base:
                strength = min(100.0, 60.0 + 40.0 * min(1.0, max(0.0, e50_vs_e200 * 20)))
                return True, "STRICT_BULLISH", strength, "strict_ok"
            if price_vs_e200 >= -tol_rel and abs(e50_vs_e200) <= tol_rel:
                strength = max(0.0, 60.0 - CONFIG["HTF_NEAR_BULLISH_PENALTY"])
                return bool(CONFIG["HTF_RELAXED_MODE"]), "NEAR_BULLISH", strength, "near_bullish"
            if e50_vs_e200 >= -tol_rel and price_vs_e200 >= -tol_rel:
                strength = max(0.0, 55.0 - CONFIG["HTF_NEUTRAL_PENALTY"])
                return bool(CONFIG["HTF_RELAXED_MODE"]), "NEUTRAL", strength, "neutral"
            return False, "BEARISH", 0.0, "bearish"
        except Exception as e:
            logger.debug(f"[HTFGrader] error: {type(e).__name__}: {e}")
            return False, "ERROR", 0.0, f"error:{type(e).__name__}"


