# =============================================================================
# v4.5.18 — BOUNDED NEUTRAL/LOCAL-BULLISH HTF BRIDGE
# =============================================================================
def _v518_neutral_local_htf_bridge(df_1h, df_4h, df_15m, df_5m,
                                   regime: str, local_regime: str,
                                   base_htf_strength: float,
                                   strategy_mode: str = "") -> Tuple[bool, float, Dict[str, Any]]:
    """Bounded bridge for NEUTRAL macro + LOCAL_BULLISH symbols.

    It does not bypass downstream policy/risk/execution gates. It only prevents
    a neutral 1H classification from killing a materially aligned 4H/15m/5m
    continuation setup before the strategy router can evaluate it.
    """
    ctx = {"enabled": False, "reason": "not_eligible"}
    try:
        if not bool(CONFIG.get("V518_NEUTRAL_LOCAL_HTF_BRIDGE_ENABLE", True)):
            return False, float(base_htf_strength), ctx
        r = str(regime or "").upper(); lr = str(local_regime or "").upper(); sm = str(strategy_mode or "").upper()
        if r != "NEUTRAL" or lr != "LOCAL_BULLISH":
            return False, float(base_htf_strength), ctx
        if not V425BearishSeverity.allows_new_long("NORMAL"):
            return False, float(base_htf_strength), {"enabled": False, "reason": "severity"}
        allow = {str(x).upper() for x in CONFIG.get("V518_BRIDGE_ALLOW_FAMILIES", ())}
        if sm and sm not in allow:
            return False, float(base_htf_strength), {"enabled": False, "reason": "family_not_allowlisted"}
        if not _PDNP_OK or any(x is None for x in (df_1h, df_4h, df_15m, df_5m)):
            return False, float(base_htf_strength), {"enabled": False, "reason": "data_missing"}
        if bool(CONFIG.get("V521_BRIDGE_REQUIRE_HTF_DATA_SUFFICIENCY", True)):
            _req_1h = max(60, int(CONFIG.get("V521_BRIDGE_MIN_1H_CANDLES", CONFIG.get("HTF_MIN_CANDLES_1H", 240))))
            _req_4h = max(60, int(CONFIG.get("V521_BRIDGE_MIN_4H_CANDLES", CONFIG.get("HTF_MIN_CANDLES_4H", 200))))
            _req_15 = max(60, int(CONFIG.get("V521_BRIDGE_MIN_15M_CANDLES", CONFIG.get("HTF_MIN_CANDLES_15M", 350))))
            _req_5 = max(20, int(CONFIG.get("V521_BRIDGE_MIN_5M_CANDLES", 60)))
            if len(df_1h) < _req_1h:
                return False, float(base_htf_strength), {"enabled": False, "reason": "1h_insufficient_data", "required": _req_1h, "actual": len(df_1h)}
            if len(df_4h) < _req_4h:
                return False, float(base_htf_strength), {"enabled": False, "reason": "4h_insufficient_data", "required": _req_4h, "actual": len(df_4h)}
            if len(df_15m) < _req_15:
                return False, float(base_htf_strength), {"enabled": False, "reason": "15m_insufficient_data", "required": _req_15, "actual": len(df_15m)}
            if len(df_5m) < _req_5:
                return False, float(base_htf_strength), {"enabled": False, "reason": "5m_insufficient_data", "required": _req_5, "actual": len(df_5m)}
        elif any(len(x) < 60 for x in (df_1h, df_4h, df_15m, df_5m)):
            return False, float(base_htf_strength), {"enabled": False, "reason": "insufficient_data"}

        def f(df):
            e20=Indicators.ema(df["close"],20); e50=Indicators.ema(df["close"],50)
            c=float(df["close"].iloc[-2]); e20c=float(e20.iloc[-2]); e50c=float(e50.iloc[-2]); e50p=float(e50.iloc[-6])
            atrs=Indicators.atr(df,int(CONFIG.get("ATR_PERIOD",14))); atr=float(atrs.iloc[-2])
            vs=float(df["volume"].iloc[-2]); va=float(df["volume"].iloc[-22:-2].mean()); vr=vs/max(va,1e-12)
            rs=Indicators.rsi(df["close"],int(CONFIG.get("RSI_PERIOD",14))); rsi=float(rs.iloc[-2]) if rs is not None else float("nan")
            return c,e20c,e50c,e50p,atr,vr,rsi

        c4,e204,e504,e504p,atr4,vr4,rsi4=f(df_4h)
        c1,e201,e501,e501p,atr1,vr1,rsi1=f(df_1h)
        c15,e2015,e5015,e5015p,atr15,vr15,rsi15=f(df_15m)
        c5,e205,e505,e505p,atr5,vr5,rsi5=f(df_5m)
        vals=(c4,e204,e504,e504p,c1,e201,e501,e501p,c15,e2015,e5015,e5015p,c5,e205,e505,e505p,atr5,vr5,rsi5)
        if not all(math.isfinite(float(v)) for v in vals):
            return False, float(base_htf_strength), {"enabled": False, "reason": "non_finite"}
        e2004=float(Indicators.ema(df_4h["close"],200).iloc[-2])
        e2001=float(Indicators.ema(df_1h["close"],200).iloc[-2])
        d4=(c4-e504)/max(abs(c4-e2004),1e-9)
        if not (c4>e204>e504 and e504>e504p):
            return False, float(base_htf_strength), {"enabled": False, "reason": "4h_stack_missing"}
        if d4 < float(CONFIG.get("V518_BRIDGE_MIN_4H_STRENGTH",0.50)):
            return False, float(base_htf_strength), {"enabled": False, "reason": "4h_strength_low"}
        if c1 < e2001*(1.0-float(CONFIG.get("EMA200_TOL_RELAXED",0.02))):
            return False, float(base_htf_strength), {"enabled": False, "reason": "1h_below_ema200"}
        if bool(CONFIG.get("V518_BRIDGE_REQUIRE_15M_BULL_STACK",True)) and not (c15>e2015>e5015):
            return False, float(base_htf_strength), {"enabled": False, "reason": "15m_stack_missing"}
        if bool(CONFIG.get("V518_BRIDGE_REQUIRE_5M_CONFIRM",True)):
            lc=df_5m.iloc[-2]; pc=df_5m.iloc[-3]; p2=df_5m.iloc[-4]
            bull=float(lc["close"])>float(lc["open"]) and float(lc["close"])>=float(pc["close"])
            hl=float(lc["low"])>float(pc["low"])>float(p2["low"])
            reclaim=c5>e205
            if not (bull or hl or reclaim):
                return False, float(base_htf_strength), {"enabled": False, "reason": "5m_confirmation_missing"}
        if vr5 < float(CONFIG.get("V518_BRIDGE_MIN_5M_VOLUME_RATIO",0.80)):
            return False, float(base_htf_strength), {"enabled": False, "reason": "5m_volume_low"}
        if rsi5 > float(CONFIG.get("V518_BRIDGE_MAX_5M_RSI",72.0)):
            return False, float(base_htf_strength), {"enabled": False, "reason": "5m_overextended"}
        chase=max(0.0,(c5-max(c15,e2015))/max(atr5,1e-9))
        if chase > float(CONFIG.get("V518_BRIDGE_MAX_CHASE_ATR",1.60)):
            return False, float(base_htf_strength), {"enabled": False, "reason": "chase_excessive"}
        floor=float(CONFIG.get("V518_BRIDGE_SWING_MIN_HTF_STRENGTH",48.0) if sm=="SWING_PULLBACK" else CONFIG.get("V518_BRIDGE_MIN_HTF_STRENGTH",40.0))
        eff=max(float(base_htf_strength),floor,min(60.0,42.0+18.0*min(1.0,d4)))
        ctx={"enabled":True,"reason":"neutral_local_mtf_bridge","strategy_mode":sm,
             "base_htf_strength":float(base_htf_strength),"effective_htf_strength":eff,
             "four_h_strength":d4,"volume_ratio_5m":vr5,"rsi_5m":rsi5,"chase_atr":chase}
        return True,eff,ctx
    except Exception as exc:
        return False,float(base_htf_strength),{"enabled":False,"reason":f"exception:{exc}"}

class MicroStructure:
    """
    Bounded confirmation helpers used by the Opportunity families.
    NEVER a standalone entry router — always subordinate to HTF.
    """

    @staticmethod
    def micro_bos_confirm(df_5m) -> Tuple[bool, float]:
        """Returns (confirmed, break_strength_pct)."""
        if not _PDNP_OK or df_5m is None or len(df_5m) < 20:
            return False, 0.0
        try:
            # Look at the closed window (skip forming candle)
            recent = df_5m.iloc[-11:-1]
            prev_high = float(recent["high"].iloc[:-1].max())
            last = df_5m.iloc[-2]
            body = abs(float(last["close"]) - float(last["open"]))
            rng = max(1e-9, float(last["high"]) - float(last["low"]))
            body_ratio = body / rng
            close = float(last["close"])
            break_pct = (close - prev_high) / prev_high if prev_high > 0 else 0.0
            if break_pct >= CONFIG["MICRO_BOS_MIN_BREAK"] and body_ratio >= CONFIG["BOS_BODY_MIN_RATIO"]:
                return True, break_pct
        except Exception:
            _v647_record_suppressed_exception()
        return False, 0.0

    @staticmethod
    def fake_break_filter(df_5m, zone_ref=None, family="") -> bool:
        """Returns True if NOT a fake break (i.e., safe).

        v4.0.5 FIX #5 — Looser semantics: only flag as fake-break when the
        MAJORITY of the recent closes fall below the tolerance floor (real
        breakout failure), instead of a single close dip triggering rejection.
        Reason : original `any(...)` logic rejected valid entries after any
                 natural pullback within the recent-high band.
        Effect : keeps detection of genuine breakout/retest failure while
                 allowing legitimate closes that briefly dip near the high.
        """
        if not _PDNP_OK or df_5m is None or len(df_5m) < 5:
            # Fail-closed for live gating: absence/insufficient data is NOT
            # evidence that a breakout is safe.
            return False
        try:
            lookahead = max(3, int(CONFIG["FAKE_BREAK_LOOKAHEAD_BARS"]))
            tol = max(0.0, float(CONFIG["FAKE_BREAK_TOLERANCE_PCT"]))
            fam = str(family or "").upper()
            zone = None
            if fam in {"PULLBACK", "MTF_PULLBACK"} and zone_ref is not None:
                try:
                    zone = float(zone_ref)
                except Exception:
                    zone = None
            if zone is None or not math.isfinite(zone) or zone <= 0:
                zone = float(df_5m["high"].iloc[-(lookahead + 2):-1].max())
            floor = zone * (1.0 - tol)
            recent_closes = list(df_5m["close"].iloc[-lookahead:])
            if not recent_closes:
                return True
            below = sum(1 for c in recent_closes if float(c) < floor)
            required = min(len(recent_closes), max(2, int(CONFIG.get("FAKE_BREAK_BELOW_REQUIRED_BARS", 3))))
            # V700: the latest CLOSED bar is the decisive retest verdict.
            # Older closes during a healthy pullback must not override a closed
            # reclaim/hold above the breakout floor. If the latest close remains
            # below the floor, the existing repeated-failure requirement stays hard.
            latest_closed = float(df_5m["close"].iloc[-2])
            if bool(CONFIG.get("V700_FAKE_BREAK_REQUIRE_LATEST_CLOSE_BELOW", True)) and latest_closed >= floor:
                return True
            if below >= required:
                return False
            return True
        except Exception:
            return False

    @staticmethod
    def zone_quality_class(distance_atr: float, freshness_bars: int) -> str:
        if distance_atr > CONFIG["ZONE_TOO_FAR_ATR_MULT"]:
            return "TOO_FAR"
        if freshness_bars <= 2 and distance_atr <= 0.6:
            return "STRONG_FRESH"
        if freshness_bars <= 6 and distance_atr <= 1.0:
            return "ACCEPTABLE"
        return "WEAK_STALE"

    @staticmethod
    def zone_quality_bonus(zone_class: str) -> float:
        return {
            "STRONG_FRESH": CONFIG["ZONE_STRONG_FRESH_BONUS"],
            "ACCEPTABLE": CONFIG["ZONE_ACCEPTABLE_PENALTY"],
            "WEAK_STALE": CONFIG["ZONE_WEAK_STALE_PENALTY"],
            "TOO_FAR": -999.0,
        }.get(zone_class, 0.0)

    @staticmethod
    def rejection_candle_confirm(df_5m) -> bool:
        if not _PDNP_OK or df_5m is None or len(df_5m) < 2:
            return False
        try:
            c = df_5m.iloc[-2]
            body = abs(float(c["close"]) - float(c["open"]))
            rng = max(1e-9, float(c["high"]) - float(c["low"]))
            body_ratio = body / rng
            is_bullish = float(c["close"]) > float(c["open"])
            lower_wick = (min(float(c["open"]), float(c["close"])) - float(c["low"])) / rng
            # Hammer or bullish engulfing style
            if is_bullish and (body_ratio >= CONFIG["REJECTION_BODY_MIN_RATIO"] or lower_wick >= 0.5):
                return True
        except Exception:
            _v647_record_suppressed_exception()
        return False


