class SessionScoring:
    @staticmethod
    def bonus() -> float:
        try:
            hour_utc = datetime.now(timezone.utc).hour
            ov_s, ov_e, ov_bonus = CONFIG["SESSION_OVERLAP"]
            if ov_s <= hour_utc < ov_e:
                return float(ov_bonus)
            ln_s, ln_e, ln_bonus = CONFIG["SESSION_LONDON"]
            if ln_s <= hour_utc < ln_e:
                return float(ln_bonus)
            ny_s, ny_e, ny_bonus = CONFIG["SESSION_NY"]
            if ny_s <= hour_utc < ny_e:
                return float(ny_bonus)
            as_s, as_e, as_bonus = CONFIG["SESSION_ASIAN"]
            if as_s <= hour_utc < as_e:
                return float(as_bonus)
        except Exception:
            _v647_record_suppressed_exception()
        return 0.0


