# v4.5.7 — bounded Pullback forensic stages (telemetry-only)
def _v457_pullback_diag_note(symbol: str, reason: str, ctx: Optional[Dict[str, Any]] = None) -> None:
    try:
        if not bool(CONFIG.get("V457_PB_DIAG_ENABLE", True)):
            return
        reason = str(reason or "unknown")
        STATS[f"v457_pb_{reason}"] = int(STATS.get(f"v457_pb_{reason}", 0) or 0) + 1
        if reason in {"valid_candidate","valid_but_not_ranked"}:
            STATS["v457_pb_valid"] = int(STATS.get("v457_pb_valid",0) or 0) + 1
            STATS["PB_VALID"] = int(STATS.get("PB_VALID",0) or 0) + 1
        if reason in {"no_anchor_in_zone","ema20_outside","ema50_outside","vwap_outside"}:
            STATS["v457_pb_stage_anchor_rejects"] = int(STATS.get("v457_pb_stage_anchor_rejects",0) or 0) + 1
            STATS["PB_STAGE_ANCHOR"] = int(STATS.get("PB_STAGE_ANCHOR",0) or 0) + 1
        elif reason == "micro_uptrend_missing":
            STATS["v457_pb_stage_micro_rejects"] = int(STATS.get("v457_pb_stage_micro_rejects",0) or 0) + 1
            STATS["PB_STAGE_MICRO"] = int(STATS.get("PB_STAGE_MICRO",0) or 0) + 1
        elif reason == "family_policy_block":
            STATS["v457_pb_stage_policy_rejects"] = int(STATS.get("v457_pb_stage_policy_rejects",0) or 0) + 1
            STATS["PB_STAGE_POLICY"] = int(STATS.get("PB_STAGE_POLICY",0) or 0) + 1
        elif reason == "htf_block":
            STATS["v457_pb_stage_htf_rejects"] = int(STATS.get("v457_pb_stage_htf_rejects",0) or 0) + 1
            STATS["PB_STAGE_HTF"] = int(STATS.get("PB_STAGE_HTF",0) or 0) + 1
        elif reason == "score_block":
            STATS["v457_pb_stage_score_rejects"] = int(STATS.get("v457_pb_stage_score_rejects",0) or 0) + 1
            STATS["PB_STAGE_SCORE"] = int(STATS.get("PB_STAGE_SCORE",0) or 0) + 1
    except Exception:
        _v647_record_suppressed_exception()


class V424PullbackDiagnostics:
    """v4.2.4 — forensic telemetry for PULLBACK rejects and near-misses.

    Read-only observer. It never changes routing, scoring, or safety gates.
    """
    _lock = threading.RLock()
    _events = deque(maxlen=4096)

    @classmethod
    def _enabled(cls):
        return bool(CONFIG.get("V424_PULLBACK_DIAG_ENABLE", True))

    @classmethod
    def _prune(cls):
        now = MONO_NOW()
        window = float(CONFIG.get("V424_PULLBACK_DIAG_WINDOW_SEC", 900))
        while cls._events and (now - cls._events[0][0]) > window:
            cls._events.popleft()

    @classmethod
    def record(cls, symbol, reason, stage="router", details=None):
        if not cls._enabled():
            return
        try:
            with cls._lock:
                cls._events.append((MONO_NOW(), {
                    "symbol": str(symbol or ""),
                    "reason": str(reason or "unknown"),
                    "stage": str(stage or "unknown"),
                    "details": dict(details or {}),
                }))
                cls._prune()
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def diagnose_detector(cls, symbol, df_15m, df_5m):
        """Diagnostic mirror of PULLBACK distance logic using CLOSED bars."""
        out = {"family": "PULLBACK", "symbol": str(symbol or "")}
        try:
            if not _PDNP_OK or df_15m is None or df_5m is None:
                out["reason"] = "missing_data"; return out
            if len(df_15m) < 60 or len(df_5m) < max(25, int(CONFIG.get("RSI_PERIOD",14))+5):
                out["reason"] = "insufficient_candles"; return out
            close = float(df_5m["close"].iloc[-2])
            atr_s = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
            atr = float(atr_s.iloc[-2]) if atr_s is not None else float("nan")
            if not math.isfinite(close) or not math.isfinite(atr) or atr <= 0:
                out["reason"] = "atr_invalid"; return out
            e20 = float(Indicators.ema(df_15m["close"], CONFIG["EMA_FAST"]).iloc[-2])
            e50 = float(Indicators.ema(df_15m["close"], CONFIG["EMA_MID"]).iloc[-2])
            max_atr = float(CONFIG.get("PULLBACK_MAX_DISTANCE_ATR",2.0))
            max_pct = float(CONFIG.get("PULLBACK_MAX_DISTANCE_PCT",2.5))
            neg = float(CONFIG.get("PULLBACK_NEG_ATR_ALLOWED",0.5))
            relaxed=False
            try:
                relaxed = bool(CONFIG.get("PULLBACK_RELAXED_ENABLE",True)) and "V420FunnelWatchdog" in globals() and V420FunnelWatchdog.is_relaxed()
            except Exception:
                relaxed=False
            if relaxed:
                max_atr=min(float(CONFIG.get("PULLBACK_RELAXED_MAX_DISTANCE_ATR",max_atr)), max_atr*1.5)
                max_pct=min(float(CONFIG.get("PULLBACK_RELAXED_MAX_DISTANCE_PCT",max_pct)), max_pct*1.5)
                neg=min(float(CONFIG.get("PULLBACK_RELAXED_NEG_ATR_ALLOWED",neg)),1.0)
            def pack(anchor, ref):
                da=(close-ref)/max(atr,1e-9); dp=(close-ref)/max(ref,1e-9)*100.0
                return {"anchor":anchor,"dist_atr_signed":round(da,4),"dist_atr_abs":round(abs(da),4),"dist_pct_signed":round(dp,4),"within_atr":bool(0<=da<=max_atr),"within_pct":bool(0<=dp<=max_pct),"negative_allowed":bool(-neg<=da<0)}
            out["ema20"]=pack("EMA20",e20); out["ema50"]=pack("EMA50",e50); out["relaxed"]=relaxed
            rs=None
            try:
                r=Indicators.rsi(df_5m["close"],CONFIG["RSI_PERIOD"]); rs=float(r.iloc[-2]) if r is not None else None
            except Exception: pass
            out["rsi_5m"]=rs; out["rsi_recovery_ok"]=bool(rs is not None and 40.0<=rs<=65.0)
            try:
                vs=Indicators.vwap(df_5m); vw=float(vs.iloc[-2]) if vs is not None else float("nan")
                out["vwap"] = pack("VWAP",vw) if math.isfinite(vw) and vw>0 else {"available":False}
                if out["vwap"].get("available",True):
                    out["vwap"]["within_vwap_atr"] = bool(0<=out["vwap"]["dist_atr_signed"]<=float(CONFIG.get("PULLBACK_VWAP_MAX_DISTANCE_ATR",2.0)))
            except Exception:
                out["vwap"]={"available":False}
            vals=[x.get("dist_atr_abs") for x in (out.get("ema20"),out.get("ema50"),out.get("vwap")) if isinstance(x,dict) and x.get("dist_atr_abs") is not None]
            out["near_distance_atr"]=min(vals) if vals else None
            # v4.2.7: near-miss must be wider than the actual pullback entry
            # envelope, otherwise telemetry labels non-actionable 4+ ATR setups
            # as "near" and inflates recoverability.
            _strict_nm = float(CONFIG.get("PULLBACK_MAX_DISTANCE_ATR", 2.0))
            _relaxed_nm = float(CONFIG.get("PULLBACK_RELAXED_MAX_DISTANCE_ATR", _strict_nm))
            _cfg_nm = float(CONFIG.get("V424_PULLBACK_NEAR_DISTANCE_ATR", 3.0))
            _near_cut = min(3.5, max(_cfg_nm, _strict_nm + 1.0, _relaxed_nm + 0.4))
            out["near_miss_threshold_atr"] = round(_near_cut, 4)
            out["is_near_miss"]=bool(out["near_distance_atr"] is not None and out["near_distance_atr"]<=_near_cut)
            reasons=[]
            if not out["ema50"].get("within_atr") or not out["ema50"].get("within_pct"): reasons.append("EMA50_distance")
            if not out["ema20"].get("within_atr") or not out["ema20"].get("within_pct"): reasons.append("EMA20_distance")
            if out.get("vwap",{}).get("available",True) and not out["vwap"].get("within_vwap_atr",False): reasons.append("VWAP_distance")
            if out["ema20"].get("negative_allowed") and not out.get("rsi_recovery_ok"): reasons.append("RSI_recovery_missing_for_negative_EMA20")
            out["primary_reasons"]=reasons[:6] or ["detector_condition_unmet"]
            return out
        except Exception as e:
            out["reason"]=f"diagnostic_error:{type(e).__name__}"; return out

    @classmethod
    def note_router_reject(cls, symbol, diag):
        if not cls._enabled(): return
        try:
            for reason in (diag.get("primary_reasons",[]) or [])[:6]:
                cls.record(symbol,reason,"router",diag)
            if diag.get("is_near_miss"): cls.record(symbol,"NEAR_MISS_PULLBACK","router",diag)
        except Exception: pass

    @classmethod
    def note_pipeline_reject(cls, symbol, reason, stage, ctx=None):
        if not cls._enabled(): return
        cls.record(symbol,reason,stage,ctx)
        # v4.2.5 §18 — recoverable-near-miss telemetry for PULLBACK rejects at
        # the family-policy stages. `recoverable_near_miss` is INDEPENDENT of
        # `is_near_miss`: it fires when the reject was policy/regime-driven
        # (not structure-driven) so it marks a candidate that the Bearish
        # Recovery engine could plausibly have rescued. Read-only.
        try:
            r = str(reason or "")
            if r in ("family_regime_disallowed", "family_htf_strength_below_floor",
                     "family_tier_below_floor"):
                fam = str((ctx or {}).get("family", "")).upper()
                if fam == "PULLBACK":
                    cls.record(symbol, "RECOVERABLE_NEAR_MISS_PULLBACK", stage, ctx)
                    STATS["recoverable_near_miss_count"] = \
                        STATS.get("recoverable_near_miss_count", 0) + 1
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def snapshot(cls):
        if not cls._enabled(): return {}
        try:
            with cls._lock:
                cls._prune(); rows=list(cls._events)
            reasons=defaultdict(int); stages=defaultdict(int); symbols=defaultdict(int); near=0
            rec_nm=0
            for _,p in rows:
                reasons[p.get("reason","unknown")]+=1; stages[p.get("stage","unknown")]+=1
                if p.get("symbol"): symbols[p["symbol"]]+=1
                if p.get("reason")=="NEAR_MISS_PULLBACK": near+=1
                if p.get("reason")=="RECOVERABLE_NEAR_MISS_PULLBACK": rec_nm+=1
            def top(d,n=8): return dict(sorted(d.items(),key=lambda kv:kv[1],reverse=True)[:n])
            return {"window_sec":float(CONFIG.get("V424_PULLBACK_DIAG_WINDOW_SEC",900)),"total_events":len(rows),"top_reasons":top(reasons),"stage_counts":top(stages,5),"top_symbols":top(symbols,5),"near_miss_count":near,"recoverable_near_miss_count":rec_nm,"near_miss_rate_pct":round(100.0*near/len(rows),2) if rows else 0.0}
        except Exception:
            return {}


class OpportunityDetectors:
    """
    Each detector returns (matched: bool, meta: dict).
    Families:
      1. PULLBACK (A/B/C)
      2. BREAKOUT_RETEST
      3. BREAKOUT_CONTINUATION
      4. LIQUIDITY_SWEEP_REVERSAL
      5. MOMENTUM_EXPANSION
      6. MEAN_REVERSION
    """

    @staticmethod
    def _last_atr(df) -> float:
        """ATR aligned to the last CLOSED bar; never use the forming candle."""
        try:
            a = Indicators.atr(df, CONFIG["ATR_PERIOD"])
            return float(a.iloc[-2]) if a is not None and len(a) >= 2 else 0.0
        except Exception:
            return 0.0

    @staticmethod
    def detect_pullback(df_15m, df_5m) -> Tuple[bool, Dict]:
        # v4.0.8 STARV-C — widened recall: also match retracement toward
        # EMA20 (fast) as an alternate anchor, and allow a mild negative
        # distance below the anchoring EMA when RSI is in the bullish
        # recovery band. This closes obvious false-negatives during
        # healthy uptrends. Structural gates downstream are unchanged.
        if not _PDNP_OK or df_15m is None or df_5m is None or len(df_15m) < 60:
            return False, {}
        try:
            # v4.2.2 - effective (possibly RELAXED) distance envelopes.
            _max_atr = float(CONFIG["PULLBACK_MAX_DISTANCE_ATR"])
            _max_pct = float(CONFIG["PULLBACK_MAX_DISTANCE_PCT"])
            _neg_allowed = float(CONFIG.get("PULLBACK_NEG_ATR_ALLOWED", 0.5))
            _relaxed_active = False
            try:
                if bool(CONFIG.get("PULLBACK_RELAXED_ENABLE", True)) and \
                        "V420FunnelWatchdog" in globals() and \
                        V420FunnelWatchdog.is_relaxed():
                    _relaxed_active = True
                    _max_atr = float(CONFIG.get("PULLBACK_RELAXED_MAX_DISTANCE_ATR", _max_atr))
                    _max_pct = float(CONFIG.get("PULLBACK_RELAXED_MAX_DISTANCE_PCT", _max_pct))
                    _neg_allowed = float(CONFIG.get("PULLBACK_RELAXED_NEG_ATR_ALLOWED", _neg_allowed))
                    # Hard safety clamp: relaxed envelope <= 1.5x strict.
                    _max_atr = min(_max_atr, float(CONFIG["PULLBACK_MAX_DISTANCE_ATR"]) * 1.5)
                    _max_pct = min(_max_pct, float(CONFIG["PULLBACK_MAX_DISTANCE_PCT"]) * 1.5)
                    _neg_allowed = min(_neg_allowed, 1.0)
            except Exception:
                _relaxed_active = False
            ema50 = Indicators.ema(df_15m["close"], CONFIG["EMA_MID"])
            last_price = float(df_5m["close"].iloc[-2])
            e50 = float(ema50.iloc[-2])
            atr_series = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
            atr = float(atr_series.iloc[-2]) if atr_series is not None else 0.0
            if not math.isfinite(atr) or atr <= 0:
                return False, {}
            dist_atr_e50 = (last_price - e50) / max(atr, 1e-9)
            dist_pct_e50 = (last_price - e50) / max(e50, 1e-9) * 100.0

            # Legacy anchor: EMA50 with strictly non-negative distance
            if (0 <= dist_pct_e50 <= CONFIG["PULLBACK_MAX_DISTANCE_PCT"] and
                    0 <= dist_atr_e50 <= CONFIG["PULLBACK_MAX_DISTANCE_ATR"]):
                cls = "A" if dist_atr_e50 <= 0.5 else ("B" if dist_atr_e50 <= 1.0 else "C")
                return True, {"family": "PULLBACK", "sub": cls,
                               "dist_atr": dist_atr_e50, "zone_ref": e50,
                               "anchor": "EMA50"}

            # v4.0.8 STARV-C — optional EMA20 anchor + mild-negative-distance path.
            if bool(CONFIG.get("PULLBACK_ALLOW_EMA20_ANCHOR", True)):
                try:
                    ema20 = Indicators.ema(df_15m["close"], CONFIG["EMA_FAST"])
                    e20 = float(ema20.iloc[-2])
                    dist_atr_e20 = (last_price - e20) / max(atr, 1e-9)
                    dist_pct_e20 = (last_price - e20) / max(e20, 1e-9) * 100.0
                    neg_allowed = float(CONFIG.get("PULLBACK_NEG_ATR_ALLOWED", 0.5))

                    # RSI recovery band check (bounded, uses last CLOSED bar)
                    rsi_ok = False
                    try:
                        rsi = Indicators.rsi(df_5m["close"], CONFIG["RSI_PERIOD"])
                        if rsi is not None:
                            _r = float(rsi.iloc[-2])
                            rsi_ok = (40.0 <= _r <= 65.0)
                    except Exception:
                        rsi_ok = False

                    # Non-negative side vs EMA20 (typical pullback into fast EMA)
                    if (0 <= dist_pct_e20 <= CONFIG["PULLBACK_MAX_DISTANCE_PCT"] and
                            0 <= dist_atr_e20 <= CONFIG["PULLBACK_MAX_DISTANCE_ATR"]):
                        cls = "A" if dist_atr_e20 <= 0.5 else ("B" if dist_atr_e20 <= 1.0 else "C")
                        return True, {"family": "PULLBACK", "sub": cls,
                                       "dist_atr": dist_atr_e20, "zone_ref": e20,
                                       "anchor": "EMA20"}
                    # Mild-negative-side vs EMA20 (deep pullback with RSI recovery)
                    if rsi_ok and (-neg_allowed) <= dist_atr_e20 < 0:
                        return True, {"family": "PULLBACK", "sub": "C",
                                       "dist_atr": abs(dist_atr_e20),
                                       "zone_ref": e20,
                                       "anchor": "EMA20_NEG_RSIOK"}

                    # v4.4 REPAIRED — higher-low OR alternative; detector-only recall.
                    if bool(CONFIG.get("PULLBACK_ACCEPT_HIGHER_LOW", True)):
                        try:
                            low_now = float(df_5m["low"].iloc[-2])
                            low_prev = float(df_5m["low"].iloc[-3])
                            close_now = float(df_5m["close"].iloc[-2])
                            ema20s = Indicators.ema(df_15m["close"], CONFIG["EMA_FAST"])
                            ema20_now = float(ema20s.iloc[-2])
                            ema20_prev = float(ema20s.iloc[-3])
                            if low_now > low_prev and close_now >= ema20_now and ema20_now >= ema20_prev:
                                ref = min(ema20_now, e50)
                                dist = abs((close_now - ref) / max(atr, 1e-9))
                                if dist <= min(_max_atr, float(CONFIG.get("PULLBACK_MAX_DISTANCE_ATR",2.0))*1.5):
                                    return True, {"family":"PULLBACK","sub":"HL","dist_atr":dist,
                                                  "zone_ref":ref,"anchor":"HIGHER_LOW"}
                        except Exception:
                            _v647_record_suppressed_exception()

                    if bool(CONFIG.get("PULLBACK_VWAP_ANCHOR_ENABLE", True)):
                        try:
                            _vwap_s = Indicators.vwap(df_5m)
                            _vwap = float(_vwap_s.iloc[-2]) if _vwap_s is not None else float("nan")
                            if math.isfinite(_vwap) and _vwap > 0:
                                _dv = (last_price - _vwap) / max(atr, 1e-9)
                                _dp = (last_price - _vwap) / _vwap * 100.0
                                _vmax = float(CONFIG.get("PULLBACK_VWAP_MAX_DISTANCE_ATR", 2.0))
                                if 0 <= _dv <= _vmax and 0 <= _dp <= _max_pct:
                                    _cls = "A" if _dv <= 0.5 else ("B" if _dv <= 1.0 else "C")
                                    return True, {"family":"PULLBACK","sub":_cls,
                                                  "dist_atr":_dv,"zone_ref":_vwap,"anchor":"VWAP"}
                        except Exception:
                            _v647_record_suppressed_exception()
                except Exception:
                    _v647_record_suppressed_exception()
        except Exception:
            _v647_record_suppressed_exception()
        _v457_pullback_diag_note("PULLBACK", "no_anchor_in_zone")
        return False, {}

    @staticmethod
    def detect_mtf_pullback(df_1d, df_4h, df_15m, df_5m) -> Tuple[bool, Dict]:
        """v4.2.6 — 1D Trend -> 4H Confirm -> 15m Pullback -> 5m Confirm.

        This detector is deliberately conservative and CLOSED-BAR only. It
        does not place orders and does not bypass any downstream gate. The
        returned zone_ref is the nearest valid pullback anchor; execution still
        uses the live price later in SignalBuilder, so there is no planned/live
        price desynchronization.
        """
        if not bool(CONFIG.get("MTF_PULLBACK_ENABLE", True)):
            return False, {}
        if not _PDNP_OK or any(x is None for x in (df_1d, df_4h, df_15m, df_5m)):
            return False, {}
        try:
            min_d1 = int(CONFIG.get("MTF_PULLBACK_MIN_D1_CANDLES", 60))
            min_4h = int(CONFIG.get("MTF_PULLBACK_MIN_4H_CANDLES", 80))
            if len(df_1d) < min_d1 or len(df_4h) < min_4h or len(df_15m) < 60 or len(df_5m) < 40:
                return False, {}

            def _closed_frame_values(df, fast=20, slow=50):
                ema_fast = Indicators.ema(df["close"], fast)
                ema_slow = Indicators.ema(df["close"], slow)
                i = -2
                c = float(df["close"].iloc[i])
                ef = float(ema_fast.iloc[i])
                es = float(ema_slow.iloc[i])
                slope = float(ema_fast.iloc[i]) - float(ema_fast.iloc[i-4])
                return c, ef, es, slope

            d1_close, d1_e20, d1_e50, d1_slope = _closed_frame_values(df_1d)
            h4_close, h4_e20, h4_e50, h4_slope = _closed_frame_values(df_4h)
            p15_close, p15_e20, p15_e50, _p15_slope = _closed_frame_values(df_15m)
            for v in (d1_close, d1_e20, d1_e50, d1_slope, h4_close, h4_e20, h4_e50, h4_slope, p15_close, p15_e20, p15_e50):
                if not math.isfinite(v):
                    return False, {}

            if bool(CONFIG.get("MTF_PULLBACK_REQUIRE_1D_TREND", True)):
                if not (d1_close > d1_e20 > d1_e50 and d1_slope >= 0.0):
                    return False, {}
            if bool(CONFIG.get("MTF_PULLBACK_REQUIRE_4H_TREND", True)):
                if not (h4_close > h4_e20 > h4_e50 and h4_slope >= 0.0):
                    return False, {}
            if bool(CONFIG.get("MTF_PULLBACK_REQUIRE_15M_STACK", True)):
                if not (p15_close > p15_e20 > p15_e50):
                    return False, {}

            atr_s = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
            atr = float(atr_s.iloc[-2]) if atr_s is not None else 0.0
            if not math.isfinite(atr) or atr <= 0:
                return False, {}
            c5 = float(df_5m["close"].iloc[-2])
            o5 = float(df_5m["open"].iloc[-2])
            if not all(math.isfinite(v) for v in (c5, o5)):
                return False, {}

            vwap_s = Indicators.vwap(df_5m)
            vwap = float(vwap_s.iloc[-2]) if vwap_s is not None else float("nan")
            anchors = [("EMA20", p15_e20), ("EMA50", p15_e50)]
            if math.isfinite(vwap) and vwap > 0:
                anchors.append(("VWAP", vwap))

            # Prefer EMA20 when it is a genuine pullback zone; otherwise choose
            # the nearest valid anchor. Long entries must be above the anchor.
            pref = float(CONFIG.get("MTF_PULLBACK_PREFER_EMA20_ATR", 0.60))
            max_zone = float(CONFIG.get("MTF_PULLBACK_MAX_ZONE_DISTANCE_ATR", 1.0))
            valid = []
            for name, z in anchors:
                if not math.isfinite(z) or z <= 0:
                    continue
                dist = (c5 - z) / atr
                if 0.0 <= dist <= max_zone:
                    valid.append((name, z, dist))
            if not valid:
                return False, {}
            valid.sort(key=lambda t: (0 if t[0] == "EMA20" and t[2] <= pref else 1, t[2]))
            anchor, zone_ref, dist_atr = valid[0]

            # The live/forming bar is deliberately ignored. The last closed 5m
            # candle must show a bullish response and not be materially extended.
            rsi_s = Indicators.rsi(df_5m["close"], CONFIG["RSI_PERIOD"])
            rsi = float(rsi_s.iloc[-2]) if rsi_s is not None else float("nan")
            if not math.isfinite(rsi):
                return False, {}
            rsi_min = float(CONFIG.get("MTF_PULLBACK_RSI_MIN", 45.0))
            rsi_max = float(CONFIG.get("MTF_PULLBACK_RSI_MAX", 68.0))
            if not (rsi_min <= rsi <= rsi_max):
                return False, {}
            bullish_close = c5 > o5
            try:
                hl = float(df_5m["low"].iloc[-2]) > float(df_5m["low"].iloc[-3]) > float(df_5m["low"].iloc[-4])
            except Exception:
                hl = False
            ema20_5 = Indicators.ema(df_5m["close"], CONFIG["EMA_FAST"])
            ema20_5_last = float(ema20_5.iloc[-2]) if ema20_5 is not None else float("nan")
            micro_stack = math.isfinite(ema20_5_last) and c5 >= ema20_5_last
            if not (bullish_close or hl or micro_stack):
                return False, {}

            try:
                v_last = float(df_5m["volume"].iloc[-2])
                v_avg = float(df_5m["volume"].iloc[-22:-2].mean())
                vol_ratio = (v_last / v_avg) if v_avg > 0 else float("nan")
            except Exception:
                vol_ratio = float("nan")
            min_vol = float(CONFIG.get("MTF_PULLBACK_MIN_VOLUME_RATIO", 0.80))
            if not math.isfinite(vol_ratio) or vol_ratio < min_vol:
                return False, {}


            # Do not accept a pullback if price has already stretched too far
            # above the validated zone; this keeps the strategy from chasing.
            max_entry_dist = float(CONFIG.get("MTF_PULLBACK_MAX_ENTRY_DISTANCE_ATR", 0.55))
            if dist_atr > max_entry_dist:
                return False, {}

            # 15m confirmation: the closed candle is also above its 20 EMA and
            # has either a bullish body or a higher low.
            p15 = df_15m.iloc[-2]
            p15_bull = float(p15["close"]) > float(p15["open"])
            try:
                p15_hl = float(df_15m["low"].iloc[-2]) > float(df_15m["low"].iloc[-3])
            except Exception:
                p15_hl = False
            if not (p15_bull or p15_hl):
                return False, {}

            return True, {
                "family": "MTF_PULLBACK",
                "sub": "A" if dist_atr <= 0.30 else ("B" if dist_atr <= 0.55 else "C"),
                "dist_atr": float(dist_atr),
                "zone_ref": float(zone_ref),
                "anchor": anchor,
                "d1_trend": "BULLISH",
                "h4_trend": "BULLISH",
                "p15_stack": True,
                "rsi_5m": float(rsi),
                "volume_ratio": float(vol_ratio),
                "higher_low_5m": bool(hl),
                "bullish_close_5m": bool(bullish_close),
            }
        except Exception:
            return False, {}

    @staticmethod
    def detect_measured_move_breakout(df_15m, df_5m) -> Tuple[bool, Dict]:
        """v4.2.8 — bullish impulse + descending contraction + closed breakout."""
        if not bool(CONFIG.get("MEASURED_MOVE_BREAKOUT_ENABLE", True)):
            return False, {}
        if not _PDNP_OK or df_15m is None or df_5m is None:
            return False, {}
        try:
            pb=max(10,int(CONFIG.get("MEASURED_MOVE_PATTERN_BARS",14)))
            ib=max(6,int(CONFIG.get("MEASURED_MOVE_IMPULSE_BARS",10)))
            if len(df_15m) < pb+ib+8 or len(df_5m) < 35:
                return False, {}
            closed15=df_15m.iloc[:-1].copy()
            pattern=closed15.iloc[-pb:]
            impulse=closed15.iloc[-(pb+ib):-pb]
            imp_low=float(impulse["low"].min()); imp_high=float(impulse["high"].max())
            if not all(math.isfinite(x) and x>0 for x in (imp_low,imp_high)) or imp_high<=imp_low:
                return False, {}
            atr15_s=Indicators.atr(closed15,CONFIG["ATR_PERIOD"]); atr15=float(atr15_s.iloc[-1]) if atr15_s is not None else 0.0
            if not math.isfinite(atr15) or atr15<=0:
                return False, {}
            impulse_leg=imp_high-imp_low
            impulse_atr=impulse_leg/atr15
            if impulse_atr<float(CONFIG.get("MEASURED_MOVE_MIN_IMPULSE_ATR",2.5)):
                return False, {}
            if float(impulse["close"].iloc[-1])<=float(impulse["close"].iloc[0]):
                return False, {}
            x=np.arange(pb,dtype=float)
            hi=pattern["high"].astype(float).to_numpy(); lo=pattern["low"].astype(float).to_numpy()
            if not (np.isfinite(hi).all() and np.isfinite(lo).all()):
                return False, {}
            su,iu=np.polyfit(x,hi,1); sl,il=np.polyfit(x,lo,1)
            width_start=float(hi[0]-lo[0]); width_end=float(hi[-1]-lo[-1])
            if width_start<=0 or width_end<=0:
                return False, {}
            contraction=(width_start-width_end)/width_start*100.0
            if contraction<float(CONFIG.get("MEASURED_MOVE_MIN_CONTRACTION_PCT",18.0)):
                return False, {}
            if width_start/atr15>float(CONFIG.get("MEASURED_MOVE_MAX_START_WIDTH_ATR",8.0)):
                return False, {}
            if width_end/atr15>float(CONFIG.get("MEASURED_MOVE_MAX_END_WIDTH_ATR",4.0)):
                return False, {}
            if not (su<0 and su<sl):
                return False, {}
            if (su/atr15)>float(CONFIG.get("MEASURED_MOVE_MIN_UPPER_SLOPE_ATR",-0.05)):
                return False, {}
            if (sl/atr15)>float(CONFIG.get("MEASURED_MOVE_MAX_LOWER_SLOPE_ATR",0.10)):
                return False, {}
            upper_now=float(su*x[-1]+iu)
            lower_now=float(sl*x[-1]+il)
            if not all(math.isfinite(v) for v in (upper_now,lower_now)):
                return False, {}
            bar=df_5m.iloc[-2]
            c=float(bar["close"]); o=float(bar["open"]); h=float(bar["high"]); l=float(bar["low"]); v=float(bar["volume"])
            body_ratio=abs(c-o)/max(h-l,1e-9)
            if c<=o or body_ratio<float(CONFIG.get("MEASURED_MOVE_MIN_BODY_RATIO",0.45)):
                return False, {}
            v_avg=float(df_5m["volume"].iloc[-22:-2].mean())
            volume_ratio=v/max(v_avg,1e-9)
            if not math.isfinite(volume_ratio) or volume_ratio<float(CONFIG.get("MEASURED_MOVE_MIN_VOLUME_RATIO",1.05)):
                return False, {}
            atr5_s=Indicators.atr(df_5m,CONFIG["ATR_PERIOD"]); atr5=float(atr5_s.iloc[-2]) if atr5_s is not None else 0.0
            if not math.isfinite(atr5) or atr5<=0:
                return False, {}
            breakout_level=upper_now
            excess=(c-breakout_level)/atr5
            buffer_atr=float(CONFIG.get("MEASURED_MOVE_BREAKOUT_BUFFER_ATR",0.10))
            if excess<buffer_atr:
                return False, {}
            if excess>float(CONFIG.get("MEASURED_MOVE_MAX_CHASE_ATR",0.90)):
                return False, {}
            canonical_sl=c-float(CONFIG.get("ATR_SL_MULT",1.2))*atr5
            measured_target=breakout_level+impulse_leg
            measured_rr=(measured_target-c)/max(c-canonical_sl,1e-9)
            if not math.isfinite(measured_rr) or measured_rr<float(CONFIG.get("MEASURED_MOVE_MIN_TARGET_RR",2.4)):
                return False, {}
            tp3=c+float(CONFIG.get("TP3_RR",5.0))*(c-canonical_sl)
            return True,{
                "family":"BREAKOUT_RETEST","strategy_mode":"MEASURED_MOVE",
                "zone_ref":float(breakout_level),"breakout_level":float(breakout_level),
                "impulse_low":imp_low,"impulse_high":imp_high,"impulse_leg":impulse_leg,
                "impulse_atr":impulse_atr,"measured_target":float(measured_target),
                "measured_rr":float(measured_rr),"pattern_contraction_pct":float(contraction),
                "volume_ratio":float(volume_ratio),"body_ratio":float(body_ratio),
                "breakout_excess_atr":float(excess),
                "target_vs_tp3_atr":float((measured_target-tp3)/max(atr5,1e-9)),
                "anchor":"MEASURED_MOVE_BREAKOUT"}
        except Exception:
            return False, {}

    @staticmethod
    def detect_breakout_retest(df_15m, df_5m) -> Tuple[bool, Dict]:
        if not _PDNP_OK or df_15m is None or len(df_15m) < 30:
            return False, {}
        try:
            prev_high = float(df_15m["high"].iloc[-20:-2].max())
            # Closed 5m close + closed-bar ATR; forming-bar price is never used.
            last = float(df_5m["close"].iloc[-2])
            atr = OpportunityDetectors._last_atr(df_5m)
            tol = 0.35 * atr
            if abs(last - prev_high) <= tol and last >= prev_high - tol:
                return True, {"family": "BREAKOUT_RETEST", "prev_high": prev_high, "zone_ref": prev_high}
        except Exception:
            _v647_record_suppressed_exception()
        return False, {}

    @staticmethod
    def detect_breakout_continuation(df_15m, df_5m) -> Tuple[bool, Dict]:
        if not _PDNP_OK or df_15m is None or len(df_15m) < 30:
            return False, {}
        try:
            # CLOSED bars only: exclude the currently forming 15m candle.
            highs = df_15m["high"].iloc[-7:-1]
            closes = df_15m["close"].iloc[-7:-1]
            if all(float(highs.iloc[i]) >= float(highs.iloc[i - 1]) for i in range(1, len(highs))):
                if float(closes.iloc[-1]) > float(closes.iloc[-2]):
                    return True, {"family": "BREAKOUT_CONTINUATION",
                                  "zone_ref": float(closes.iloc[-1])}
        except Exception:
            _v647_record_suppressed_exception()
        return False, {}

    @staticmethod
    def detect_liquidity_sweep(df_15m, df_5m) -> Tuple[bool, Dict]:
        """Detect a closed-bar liquidity sweep + rejection + reclaim setup.

        V638 upgrades the legacy wick-only detector into a compact confluence
        model: the last CLOSED 5m candle must sweep a prior 15m swing low,
        reject the low with a meaningful lower wick, close back above the
        swept level, and show volume confirmation. The detector never places
        orders and remains downstream of the existing canonical gates.
        """
        if not _PDNP_OK or df_15m is None or df_5m is None:
            return False, {}
        try:
            if not bool(CONFIG.get("V638_LIQ_SWEEP_CONFLUENCE_ENABLE", True)):
                # Legacy fallback preserved as an explicit rollback path.
                if len(df_15m) < 30 or len(df_5m) < 25:
                    return False, {}
                prev_low = float(df_15m["low"].iloc[-20:-2].min())
                last = df_5m.iloc[-2]
                l = float(last["low"]); c = float(last["close"]); o = float(last["open"])
                rng = max(1e-9, float(last["high"]) - l)
                lower_wick = (min(o, c) - l) / rng
                if l < prev_low and c > prev_low and lower_wick >= 0.55:
                    return True, {"family": "LIQUIDITY_SWEEP_REVERSAL",
                                  "swept_low": prev_low, "zone_ref": prev_low,
                                  "v638_mode": "legacy"}
                return False, {}

            lookback_15 = max(8, int(CONFIG.get("V638_LIQ_SWEEP_LOOKBACK_15M", 20)))
            if len(df_15m) < lookback_15 + 4 or len(df_5m) < 30:
                return False, {}

            # Strictly closed-bar clock domain.
            last = df_5m.iloc[-2]
            prev5 = df_5m.iloc[-3]
            h = float(last["high"]); l = float(last["low"]); c = float(last["close"]); o = float(last["open"])
            ph = float(prev5["high"]); pl = float(prev5["low"]); pc = float(prev5["close"])
            rng = max(1e-9, h - l)
            body = abs(c - o)
            lower_wick = max(0.0, min(o, c) - l) / rng
            body_ratio = body / rng
            close_location = (c - l) / rng
            bullish = c > o

            # Prior 15m liquidity pool excludes the two newest bars so the
            # current sweep cannot manufacture its own reference level.
            prior_slice = df_15m["low"].iloc[-(lookback_15 + 2):-2]
            prev_low = float(prior_slice.min())
            if not all(math.isfinite(v) for v in (h, l, c, o, prev_low)):
                return False, {}

            # Closed 5m ATR provides the distance normalization.
            atr_s = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
            atr = float(atr_s.iloc[-2]) if atr_s is not None and len(atr_s) >= 2 else 0.0
            if not math.isfinite(atr) or atr <= 0:
                return False, {}

            sweep_depth_atr = (prev_low - l) / atr
            swept = l < prev_low
            reclaimed = c > prev_low
            not_overextended = 0.0 < sweep_depth_atr <= float(CONFIG.get("V638_LIQ_SWEEP_MAX_SWEEP_ATR", 0.85))

            # Volume uses the same closed-bar clock and excludes the current
            # forming candle plus the signal candle from its baseline.
            v_now = float(last["volume"])
            v_base_s = df_5m["volume"].iloc[-22:-2]
            v_base = float(v_base_s.mean()) if len(v_base_s) else 0.0
            volume_ratio = v_now / max(v_base, 1e-9) if v_base > 0 else 0.0

            # A small prior-close relationship prevents a single noisy wick
            # from qualifying when there is no immediate rejection context.
            prior_context = bool(pc <= prev_low or pl <= prev_low or c >= pc)

            if not swept or not reclaimed or not not_overextended:
                return False, {}
            if bool(CONFIG.get("V638_LIQ_SWEEP_REQUIRE_WICK", True)) and lower_wick < float(CONFIG.get("V638_LIQ_SWEEP_MIN_LOWER_WICK_RATIO", 0.55)):
                return False, {}
            if bool(CONFIG.get("V638_LIQ_SWEEP_REQUIRE_VOLUME", True)) and volume_ratio < float(CONFIG.get("V638_LIQ_SWEEP_MIN_VOLUME_RATIO", 1.10)):
                return False, {}
            if bool(CONFIG.get("V638_LIQ_SWEEP_REQUIRE_BULLISH_CLOSE", True)) and not bullish:
                return False, {}
            if close_location < float(CONFIG.get("V638_LIQ_SWEEP_MIN_CLOSE_LOCATION", 0.62)):
                return False, {}
            if body_ratio < float(CONFIG.get("V638_LIQ_SWEEP_MIN_BODY_RATIO", 0.10)):
                return False, {}
            if bool(CONFIG.get("V638_LIQ_SWEEP_REQUIRE_RECLAIM", True)) and not reclaimed:
                return False, {}

            # Optional prior-bar context is deliberately soft: do not reject a
            # valid sweep merely because the previous bar did not touch the pool.
            score = float(CONFIG.get("V638_LIQ_SWEEP_SCORE_BASE", 0.68))
            score += float(CONFIG.get("V638_LIQ_SWEEP_SCORE_WICK", 0.10)) * _clamp(
                (lower_wick - float(CONFIG.get("V638_LIQ_SWEEP_MIN_LOWER_WICK_RATIO", 0.55))) / 0.30, 0.0, 1.0)
            score += float(CONFIG.get("V638_LIQ_SWEEP_SCORE_VOLUME", 0.08)) * _clamp((volume_ratio - 1.0) / 1.5, 0.0, 1.0)
            score += float(CONFIG.get("V638_LIQ_SWEEP_SCORE_CLOSE", 0.06)) * _clamp(
                (close_location - float(CONFIG.get("V638_LIQ_SWEEP_MIN_CLOSE_LOCATION", 0.62))) / 0.38, 0.0, 1.0)
            score += float(CONFIG.get("V638_LIQ_SWEEP_SCORE_RECLAIM", 0.04)) * (1.0 if reclaimed else 0.0)
            score += float(CONFIG.get("V638_LIQ_SWEEP_SCORE_BULLISH", 0.04)) * (1.0 if bullish else 0.0)
            score = min(float(CONFIG.get("V638_LIQ_SWEEP_SCORE_MAX", 0.92)), max(0.0, score))

            return True, {
                "family": "LIQUIDITY_SWEEP_REVERSAL",
                "swept_low": prev_low,
                "zone_ref": prev_low,
                "sweep_depth_atr": sweep_depth_atr,
                "lower_wick_ratio": lower_wick,
                "body_ratio": body_ratio,
                "close_location": close_location,
                "volume_ratio": volume_ratio,
                "reclaim": reclaimed,
                "bullish_close": bullish,
                "prior_context": prior_context,
                "v638_mode": "LIQUIDITY_SWEEP_RECLAIM_CONFLUENCE",
                "signal_quality": score,
            }
        except Exception:
            return False, {}

    @staticmethod
    def detect_momentum_expansion(df_5m) -> Tuple[bool, Dict]:
        if not _PDNP_OK or df_5m is None or len(df_5m) < 30:
            return False, {}
        try:
            atr = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
            if atr is None or len(atr.dropna()) < 15:
                return False, {}
            # The current forming bar can distort ATR and create repainting.
            # Align both recent and baseline measurements to CLOSED bars only.
            recent_atr = float(atr.iloc[-2])
            base_atr = float(atr.iloc[-16:-6].mean())
            ratio = recent_atr / max(base_atr, 1e-9)
            last = df_5m.iloc[-2]
            body = abs(float(last["close"]) - float(last["open"]))
            rng = max(1e-9, float(last["high"]) - float(last["low"]))
            body_ratio = body / rng
            is_bull = float(last["close"]) > float(last["open"])
            if ratio >= 1.15 and body_ratio >= 0.5 and is_bull:
                return True, {"family": "MOMENTUM_EXPANSION", "atr_ratio": ratio,
                              "zone_ref": float(last["close"])}
        except Exception:
            _v647_record_suppressed_exception()
        return False, {}

    @staticmethod
    def detect_mean_reversion(df_5m) -> Tuple[bool, Dict]:
        if not _PDNP_OK or df_5m is None or len(df_5m) < 30:
            return False, {}
        try:
            rsi = Indicators.rsi(df_5m["close"], CONFIG["RSI_PERIOD"])
            if rsi is None:
                return False, {}
            last_rsi = float(rsi.iloc[-2])
            if last_rsi <= 32.0:
                return True, {"family": "MEAN_REVERSION", "rsi": last_rsi,
                              "zone_ref": float(df_5m["close"].iloc[-2])}
        except Exception:
            _v647_record_suppressed_exception()
        return False, {}

    # v4.0.8 STARV-C — NEW soft trend-continuation detector (lowest priority).
    # Purpose: close the no_family_matched gap when NO other family matches
    # but 15m trend is objectively healthy (price>EMA20>EMA50) and last
    # CLOSED 5m bar is a bullish body. Emitted family = "TREND_CONTINUATION"
    # which is subject to the SAME BOS/reclaim hard-gate downstream as
    # BREAKOUT_RETEST / BREAKOUT_CONTINUATION — so this widens recall
    # WITHOUT relaxing structural rigor. Bounded, fail-closed on any error.
    @staticmethod
    def detect_trend_continuation_soft(df_15m, df_5m) -> Tuple[bool, Dict]:
        """Closed-bar continuation recall with a strict primary and a bounded retest lane.

        Primary lane preserves the historical rule: 15m price > EMA20 > EMA50
        plus a bullish closed 5m body. Secondary lane exists only for an
        established 15m trend where the closed 5m structure has reclaimed/held
        EMA20 with objective higher-low or close persistence. Router priority is
        still lowest, and SignalBuilder keeps the canonical downstream gate.
        """
        if not bool(CONFIG.get("ROUTER_ENABLE_TREND_CONTINUATION_SOFT", True)):
            return False, {}
        if not _PDNP_OK or df_15m is None or df_5m is None:
            return False, {}
        if len(df_15m) < max(60, int(CONFIG.get("EMA_MID", 50)) + 5) or len(df_5m) < 25:
            return False, {}
        try:
            ema20_15m = Indicators.ema(df_15m["close"], CONFIG["EMA_FAST"])
            ema50_15m = Indicators.ema(df_15m["close"], CONFIG["EMA_MID"])
            e20_15 = float(ema20_15m.iloc[-2])
            e50_15 = float(ema50_15m.iloc[-2])
            p15 = float(df_15m["close"].iloc[-2])
            if not all(math.isfinite(x) for x in (e20_15, e50_15, p15)) or not (p15 > e20_15 > e50_15):
                return False, {}

            lc = df_5m.iloc[-2]
            prev = df_5m.iloc[-3]
            prev2 = df_5m.iloc[-4]
            close = float(lc["close"]); open_ = float(lc["open"])
            bullish = close > open_
            # Preserve the exact historical primary path.
            if bullish:
                return True, {"family": "TREND_CONTINUATION", "zone_ref": e20_15,
                              "anchor": "EMA20_15M", "soft": True, "lane": "primary"}

            # Secondary lane: objective 5m retest/recovery evidence.
            ema20_5s = Indicators.ema(df_5m["close"], CONFIG["EMA_FAST"])
            ema50_5s = Indicators.ema(df_5m["close"], CONFIG["EMA_MID"])
            atrs = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
            e20_5 = float(ema20_5s.iloc[-2]); e50_5 = float(ema50_5s.iloc[-2]); atr5 = float(atrs.iloc[-2])
            if not all(math.isfinite(x) and x > 0 for x in (e20_5, e50_5, atr5, close)):
                return False, {}
            if not (close > e20_5 > e50_5):
                return False, {}

            ema_slope_ok = False
            try:
                slope_bars = max(3, int(CONFIG.get("TREND_CONT_SECONDARY_SLOPE_BARS", 4)))
                ema_s = ema20_15m
                ema_slope_ok = float(ema_s.iloc[-2]) > float(ema_s.iloc[-2-slope_bars])
            except Exception:
                ema_slope_ok = False

            higher_low = False
            close_persistence = False
            try:
                higher_low = (float(lc["low"]) > float(prev["low"]) > float(prev2["low"]))
                close_persistence = (close > float(prev["close"]) > float(prev2["close"]))
            except Exception:
                pass

            vol_ok = False
            try:
                avg = float(df_5m["volume"].iloc[-22:-2].mean())
                curv = float(lc["volume"])
                vol_ok = avg > 0 and math.isfinite(avg) and (curv / avg) >= float(CONFIG.get("TREND_CONT_SECONDARY_MIN_VOLUME_RATIO", 0.90))
            except Exception:
                vol_ok = False

            dist_above = (close - e20_5) / max(atr5, 1e-9)
            chase_ok = dist_above <= float(CONFIG.get("TREND_CONT_SECONDARY_MAX_CHASE_ATR", 0.75))
            reclaim_ok = float(prev["close"]) <= e20_5 * (1.0 + 0.003) or higher_low
            evidence_ok = (higher_low or close_persistence) and vol_ok and chase_ok and reclaim_ok and ema_slope_ok
            if not evidence_ok:
                return False, {}
            return True, {"family": "TREND_CONTINUATION", "zone_ref": e20_15,
                          "anchor": "EMA20_15M_SECONDARY_RETEST", "soft": True,
                          "lane": "secondary", "higher_low": higher_low,
                          "close_persistence": close_persistence, "volume_ratio": float(lc["volume"]) / max(float(df_5m["volume"].iloc[-22:-2].mean()), 1e-9),
                          "chase_atr": dist_above}
        except Exception:
            return False, {}


# =============================================================================
#  SECTION 19 — OPPORTUNITY ROUTER (single canonical winner selection)
# =============================================================================

def _v423_nearest_family(df_15m, df_5m, regime="", tier="", htf_strength=None,
                         volume_ratio=None, symbol="") -> Dict[str, Any]:
    out={"closest_detector":"unknown","dist_atr_ema20":None,
         "dist_atr_ema50":None,"dist_atr_vwap":None,"rsi_5m":None,
         "regime":regime,"tier":tier,"htf_strength":htf_strength,
         "volume_ratio":volume_ratio,"symbol":symbol}
    try:
        if not _PDNP_OK or df_15m is None or df_5m is None: return out
        if len(df_15m) < max(60,int(CONFIG.get("EMA_MID",50))+5) or len(df_5m)<25: return out
        close=float(df_5m["close"].iloc[-2])
        atr_s=Indicators.atr(df_5m,CONFIG["ATR_PERIOD"]); atr=float(atr_s.iloc[-2])
        if not math.isfinite(close) or not math.isfinite(atr) or atr<=0: return out
        e20=float(Indicators.ema(df_15m["close"],CONFIG["EMA_FAST"]).iloc[-2])
        e50=float(Indicators.ema(df_15m["close"],CONFIG["EMA_MID"]).iloc[-2])
        out["dist_atr_ema20"]=round(abs(close-e20)/atr,4)
        out["dist_atr_ema50"]=round(abs(close-e50)/atr,4)
        try:
            rs=Indicators.rsi(df_5m["close"],CONFIG["RSI_PERIOD"])
            if rs is not None: out["rsi_5m"]=float(rs.iloc[-2])
        except Exception: pass
        try:
            vs=Indicators.vwap(df_5m); vw=float(vs.iloc[-2]) if vs is not None else float("nan")
            if math.isfinite(vw) and vw>0: out["dist_atr_vwap"]=round(abs(close-vw)/atr,4)
        except Exception: pass
        dist=[("EMA20",out["dist_atr_ema20"]),("EMA50",out["dist_atr_ema50"]),
              ("VWAP",out["dist_atr_vwap"])]
        dist=[x for x in dist if x[1] is not None]
        if dist:
            out["closest_detector"]="PULLBACK_"+min(dist,key=lambda x:x[1])[0]
        if close>e20>e50: out["trend_continuation_distance_atr"]=0.0
        try:
            prev_high=float(df_15m["high"].iloc[-22:-2].max())
            if math.isfinite(prev_high) and prev_high>0:
                out["breakout_retest_distance_atr"]=round(abs(close-prev_high)/atr,4)
        except Exception: pass
        return out
    except Exception:
        return out


class OpportunityRouter:

    @staticmethod
    def classify(ctx: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        df_1d = ctx.get("df_1d")
        df_4h = ctx.get("df_4h")
        df_15m = ctx.get("df_15m")
        df_5m = ctx.get("df_5m")
        symbol = str(ctx.get("symbol") or "")
        results: List[Dict] = []
        # v4.0.8 STARV-C — detect_trend_continuation_soft added as LOWEST
        # priority candidate. It only fires when the 15m trend is healthy
        # AND no higher-priority family already matched, so it strictly
        # WIDENS recall without disturbing existing routing decisions.
        detector_specs = (
            ("MTF_PULLBACK", lambda: OpportunityDetectors.detect_mtf_pullback(df_1d, df_4h, df_15m, df_5m)),
            ("PULLBACK", lambda: OpportunityDetectors.detect_pullback(df_15m, df_5m)),
            ("MEASURED_MOVE_BREAKOUT", lambda: OpportunityDetectors.detect_measured_move_breakout(df_15m, df_5m)),
            ("BREAKOUT_RETEST", lambda: OpportunityDetectors.detect_breakout_retest(df_15m, df_5m)),
            ("BREAKOUT_CONTINUATION", lambda: OpportunityDetectors.detect_breakout_continuation(df_15m, df_5m)),
            ("LIQUIDITY_SWEEP_REVERSAL", lambda: OpportunityDetectors.detect_liquidity_sweep(df_15m, df_5m)),
            ("MOMENTUM_EXPANSION", lambda: OpportunityDetectors.detect_momentum_expansion(df_5m)),
            ("MEAN_REVERSION", lambda: OpportunityDetectors.detect_mean_reversion(df_5m)),
            ("TREND_CONTINUATION", lambda: OpportunityDetectors.detect_trend_continuation_soft(df_15m, df_5m)),
        )
        for det_name, det in detector_specs:
            try:
                matched, meta = det()
                if matched:
                    m=dict(meta or {}); m.setdefault("detector",det_name); results.append(m)
                elif symbol:
                    try:
                        V422NearMiss.note_detector_reject(det_name, symbol)
                    except Exception:
                        _v647_record_suppressed_exception()
                    if det_name == "PULLBACK":
                        try:
                            _pdiag = V424PullbackDiagnostics.diagnose_detector(symbol, df_15m, df_5m)
                            V424PullbackDiagnostics.note_router_reject(symbol, _pdiag)
                        except Exception:
                            _v647_record_suppressed_exception()
            except Exception as e:
                logger.debug(f"[Router] detector error {det_name}: {e}")
        if not results:
            return None
        # Priority order (higher = preferred):
        #   PULLBACK > BREAKOUT_RETEST > CONTINUATION > SWEEP > MOMENTUM >
        #   MEAN_REVERSION > TREND_CONTINUATION (soft, tail catch-all).
        priority = {
            "MTF_PULLBACK": 8, "PULLBACK": 7, "BREAKOUT_RETEST": 6, "BREAKOUT_CONTINUATION": 5,
            "LIQUIDITY_SWEEP_REVERSAL": 4, "MOMENTUM_EXPANSION": 3,
            "MEAN_REVERSION": 2, "TREND_CONTINUATION": 1,
        }
        detector_priority = {"MEASURED_MOVE_BREAKOUT": 7.5}
        if bool(CONFIG.get("ROUTER_COMPOSITE_TIEBREAK_ENABLE", True)):
            def _router_quality(x):
                q=0.0
                d=x.get("dist_atr")
                if isinstance(d,(int,float)) and math.isfinite(float(d)):
                    q += max(0.0,3.0-min(3.0,float(d)))
                if bool(x.get("soft",False)): q -= 0.25
                if str(x.get("anchor","")).upper().startswith("VWAP"): q += 0.10
                return q
            results.sort(key=lambda x:(detector_priority.get(x.get("detector",""),priority.get(x.get("family",""),0)),_router_quality(x)),reverse=True)
        else:
            results.sort(key=lambda x:detector_priority.get(x.get("detector",""),priority.get(x.get("family",""),0)),reverse=True)
        return results[0]


# =============================================================================
#  SECTION 20 — COMPOSITE SCORE ENGINE (from hybrid — single canonical)
# =============================================================================

def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, x))


class CompositeScorer:
    """
    Score = 0-100 base + bounded boosters (≤ +6 confluence, ±6 session).
    HARD GATE: if htf_passed is False, score = 0.
    DATA-SUFFICIENCY GATE: any input that is None or a sentinel (MISSING)
      => the entire score is 0 (C_REJECT) when REJECT_ON_INSUFFICIENT_SCORE_DATA is True.
    No placeholder/fallback constants influence the decision.
    """

    _MISSING = -999.0   # sentinel for "data not available"

    @staticmethod
    def _is_missing(val) -> bool:
        """Return True only for missing-data representations, not for valid zeroes.

        Non-finite values are rejected separately by build(); they must never
        enter the optional-input soft-mode substitution path.
        """
        if val is None:
            return True
        try:
            number = float(val)
            return math.isnan(number) or number == float(CompositeScorer._MISSING)
        except Exception:
            return True

    @staticmethod
    def build(*, htf_passed: bool, htf_strength: float, htf_state: str,
              structure_confidence: Optional[float], reclaim_detected: bool, bos_detected: bool,
              retest_quality_score: Optional[float], volume_ratio: Optional[float],
              vol_delta_score: Optional[float],
              orderbook_imbalance: Optional[float], momentum_score_val: Optional[float],
              rs_score_val: Optional[float], spread_pct: Optional[float],
              liquidity_tier: str, sweep_detected: bool,
              equal_lows_sweep: bool, rejection_type: str, zone_quality_class: str,
              fvg_present: bool = False, fib_golden: bool = False, rsi_div: bool = False,
              symbol: str = "", strategy_mode: str = "", measured_rr: Optional[float] = None
              ) -> Tuple[float, str, Dict[str, float]]:

        breakdown: Dict[str, float] = {}
        if not htf_passed:
            return 0.0, "C_REJECT", {"htf": 0.0, "reason": "htf_not_passed"}

        # Reject corrupt numeric evidence before missing-data soft mode or score
        # clamping. Ranges are limited to units implied by this scorer's formulas;
        # optional/unavailable inputs remain subject to the existing sufficiency gate.
        _numeric_contract = {
            "htf_strength": (htf_strength, 0.0, 100.0),
            "structure_confidence": (structure_confidence, 0.0, 100.0),
            "retest_quality_score": (retest_quality_score, 0.0, 100.0),
            "volume_ratio": (volume_ratio, 0.0, float(CONFIG.get("SCORE_VOLUME_RATIO_MAX_VALID", 100.0))),
            "vol_delta_score": (vol_delta_score, -10.0, 10.0),
            "orderbook_imbalance": (orderbook_imbalance, 0.0, 1.0),
            "momentum_score_val": (momentum_score_val, 0.0, 10.0),
            "rs_score_val": (rs_score_val, 0.0, 8.0),
            "spread_pct": (spread_pct, 0.0, 100.0),
            "measured_rr": (measured_rr, 0.0, 100.0),
        }
        _invalid_numeric = []
        for _name, (_raw_value, _min_value, _max_value) in _numeric_contract.items():
            if _raw_value is None:
                continue
            try:
                _value = float(_raw_value)
            except (TypeError, ValueError, OverflowError):
                _invalid_numeric.append(f"{_name}:not_numeric")
                continue
            # The sentinel means missing; it is handled by the sufficiency gate
            # below and must not be treated as a numeric quality signal.
            if _value == float(CompositeScorer._MISSING):
                continue
            if not math.isfinite(_value):
                _invalid_numeric.append(f"{_name}:non_finite")
            elif _value < _min_value or _value > _max_value:
                _invalid_numeric.append(f"{_name}:out_of_range")
        if _invalid_numeric:
            try:
                STATS["composite_scorer_invalid_numeric_total"] = int(
                    STATS.get("composite_scorer_invalid_numeric_total", 0) or 0
                ) + 1
                STATS["composite_scorer_invalid_numeric_last"] = {
                    "symbol": str(symbol or "")[:64],
                    "fields": _invalid_numeric[:12], "ts": float(WALL_NOW()),
                }
            except Exception:
                pass
            return 0.0, "C_REJECT", {
                "reason": "invalid_score_input",
                "invalid_fields": ",".join(_invalid_numeric[:12]),
            }

        # ---- Data sufficiency gate (fail-closed) ----
        # Core quantitative inputs MUST be present; if any is missing/None,
        # the score is rejected — no placeholder substitution.
        # v4.0.8 STARV-E — critical vs non-critical split. Critical fields
        # still force C_REJECT unconditionally; non-critical fields (rs, spread)
        # can be softened via SCORE_INPUT_SOFT_MODE with a bounded penalty.
        # Missing fields are ALSO recorded in a rolling window so top feed
        # instability is observable without changing the contract.
        required_numeric = {
            "htf_strength": htf_strength,
            "structure_confidence": structure_confidence,
            "retest_quality_score": retest_quality_score,
            "volume_ratio": volume_ratio,
            "orderbook_imbalance": orderbook_imbalance,
            "momentum_score_val": momentum_score_val,
            "rs_score_val": rs_score_val,
            "spread_pct": spread_pct,
        }
        _critical_fields = {
            "htf_strength", "structure_confidence", "retest_quality_score", "volume_ratio",
            "orderbook_imbalance", "momentum_score_val",
        }
        missing_keys = [k for k, v in required_numeric.items()
                        if CompositeScorer._is_missing(v)]
        # STARV-E — rolling observability window (bounded, non-blocking).
        if missing_keys:
            try:
                _obs = STATS.get("score_input_missing_top")
                if _obs is None or not isinstance(_obs, deque):
                    _obs = deque(maxlen=int(CONFIG.get(
                        "SCORE_INPUT_MISSING_WINDOW", 200)))
                    STATS["score_input_missing_top"] = _obs
                _obs.append({"ts": time.time(), "symbol": symbol,
                             "missing": list(missing_keys)})
            except Exception:
                _v647_record_suppressed_exception()

        _reject_on_missing = bool(CONFIG.get("REJECT_ON_INSUFFICIENT_SCORE_DATA", True))
        _soft_mode = bool(CONFIG.get("SCORE_INPUT_SOFT_MODE", False))
        _soft_penalty = float(CONFIG.get("SCORE_INPUT_SOFT_PENALTY", 3.0))
        _soft_applied = 0.0
        if missing_keys and _reject_on_missing:
            _has_critical_missing = any(k in _critical_fields for k in missing_keys)
            # Soft path: exactly one non-critical field missing AND soft mode ON.
            if (_soft_mode and (not _has_critical_missing)
                    and len(missing_keys) == 1):
                # Substitute a neutral value and apply a bounded penalty.
                if "rs_score_val" in missing_keys:
                    rs_score_val = 2.0  # neutral RS (mild positive)
                if "spread_pct" in missing_keys:
                    spread_pct = float(CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15))
                _soft_applied = _soft_penalty
                try:
                    STATS["score_input_soft_applied"] = \
                        STATS.get("score_input_soft_applied", 0) + 1
                except Exception:
                    _v647_record_suppressed_exception()
                logger.info(
                    f"[Scorer] {symbol} SOFT-MODE proceeding with 1 non-critical "
                    f"missing field: {missing_keys} (penalty={_soft_penalty})"
                )
            else:
                logger.info(
                    f"[Scorer] {symbol} REJECT — insufficient data for: {missing_keys}"
                )
                return 0.0, "C_REJECT", {
                    "reason": "insufficient_score_data",
                    "missing_fields": float(len(missing_keys)),
                    "missing_names": ",".join(missing_keys),
                }

        # 1. HTF Bias (max 20)
        htf_mult = {"STRICT_BULLISH": 1.0, "NEAR_BULLISH": 0.75, "NEUTRAL": 0.50}.get(htf_state, 0.5)
        htf_score = _clamp(htf_strength / 100.0 * 20.0 * htf_mult, 0.0, 20.0)
        breakdown["htf"] = htf_score

        # 2. Structure/Reclaim (max 15) — from real data only
        struct_conf = float(structure_confidence)
        struct_score = _clamp(struct_conf / 100.0 * 15.0, 0.0, 15.0)
        if reclaim_detected:
            struct_score *= 1.25
        if bos_detected:
            struct_score *= 1.15
        struct_score = _clamp(struct_score, 0.0, 15.0)
        breakdown["structure"] = struct_score

        # 3. Retest Quality (max 10) — from real data only
        rq = float(retest_quality_score)
        retest_score = _clamp(rq / 100.0 * 10.0, 0.0, 10.0)
        if zone_quality_class in ("STRONG_FRESH",):
            retest_score *= 1.15
        elif zone_quality_class in ("WEAK_STALE",):
            retest_score *= 0.5
        retest_score = _clamp(retest_score, 0.0, 10.0)
        breakdown["retest"] = retest_score

        # 4. Volume expansion (max 10)
        vol_score = _clamp((volume_ratio - 0.8) * 20.0, 0.0, 10.0) + float(vol_delta_score or 0.0)
        vol_score = _clamp(vol_score, 0.0, 10.0)
        breakdown["volume"] = vol_score

        # 5. Orderbook imbalance (max 10) — from real data only
        ob_raw = float(orderbook_imbalance)
        if ob_raw > 0.5:
            ob_score = _clamp((ob_raw - 0.5) * 20.0, 0.0, 10.0)
        elif ob_raw < 0.4:
            ob_score = -2.0
        else:
            ob_score = 0.0
        breakdown["orderbook"] = ob_score

        # 6. Momentum (max 10) — from real data only
        mom = _clamp(float(momentum_score_val), 0.0, 10.0)
        breakdown["momentum"] = mom

        # 7. RS vs BTC (max 8) — from real data only
        rs = _clamp(float(rs_score_val), 0.0, 8.0)
        breakdown["rs_btc"] = rs

        # 8. Spread quality (max 5) — from real data only
        # v4.0.5 FIX #8 — replaced hardcoded 0.15 with CONFIG key so a single
        # source of truth governs the spread ceiling (was drifting from
        # SCORE_SPREAD_CEIL_PCT). Effect: consistent tuning surface.
        spread_ceiling = float(CONFIG["SCORE_SPREAD_CEIL_PCT"])
        ratio = float(spread_pct) / max(spread_ceiling, 1e-9)
        if ratio < 0.5:
            spread_score = 5.0
        elif ratio < 1.0:
            spread_score = 3.0
        elif ratio < 1.5:
            spread_score = 1.0
        else:
            spread_score = 0.0
        breakdown["spread"] = spread_score

        # 9. Liquidity tier (max 5)
        liq_score = LiquidityTier.score_points(liquidity_tier)
        breakdown["liquidity_tier"] = liq_score

        # 10. Sweep / fake-BOS context (max 7)
        sweep_score = 0.0
        if sweep_detected:
            sweep_score += 4.2
        if equal_lows_sweep:
            sweep_score += 2.1
        if rejection_type in ("hammer", "engulfing"):
            sweep_score += 0.7
        sweep_score = _clamp(sweep_score, 0.0, 7.0)
        breakdown["sweep_context"] = sweep_score

        # Base sum
        base = (htf_score + struct_score + retest_score + vol_score + ob_score
                + mom + rs + spread_score + liq_score + sweep_score)

        # Bounded boosters
        conf_boost = 0.0
        if fvg_present:
            conf_boost += 3.0
        if fib_golden:
            conf_boost += 4.0
        if rsi_div:
            conf_boost += 3.0
        conf_boost = _clamp(conf_boost, 0.0, float(CONFIG["CONFLUENCE_BOOST_MAX_TOTAL"]))
        breakdown["confluence_boosters"] = conf_boost

        # Session (bounded ±6)
        sess = _clamp(SessionScoring.bonus(), -float(CONFIG["SESSION_SCORE_CAP"]),
                      float(CONFIG["SESSION_SCORE_CAP"]))
        breakdown["session"] = sess

        # Zone quality direct booster
        zone_bonus = MicroStructure.zone_quality_bonus(zone_quality_class)
        if zone_bonus < -100:  # TOO_FAR sentinel
            zone_bonus = 0.0
        breakdown["zone_quality"] = zone_bonus

        # v4.0.8 STARV-E — apply soft-mode penalty (if any) BEFORE class banding
        # so the final `total` reflects the discount and downstream min_score
        # comparison remains a single source of truth.
        measured_move_boost=0.0
        if str(strategy_mode or "").upper()=="MEASURED_MOVE" and bool(CONFIG.get("MEASURED_MOVE_BREAKOUT_ENABLE",True)):
            try:
                mm_rr=float(measured_rr if measured_rr is not None else 0.0)
                mm_min=float(CONFIG.get("MEASURED_MOVE_MIN_TARGET_RR",2.4))
                raw_mm=_clamp((mm_rr-mm_min)/4.0*float(CONFIG.get("MEASURED_MOVE_BONUS_POINTS",4.0)),0.0,float(CONFIG.get("MEASURED_MOVE_MAX_BONUS",4.0)))
                measured_move_boost=_clamp(raw_mm,0.0,max(0.0,float(CONFIG.get("CONFLUENCE_BOOST_MAX_TOTAL",6.0))-conf_boost))
            except Exception:
                measured_move_boost=0.0
        breakdown["measured_move_confluence"]=measured_move_boost
        total = _clamp(base + conf_boost + sess + zone_bonus + measured_move_boost - float(_soft_applied),
                       0.0, 100.0)

        if total >= CONFIG["SIGNAL_CLASS_A_MIN"]:
            sig_class = "A_STRONG"
        elif total >= CONFIG["SIGNAL_CLASS_B_MIN"]:
            sig_class = "B_MEDIUM"
        else:
            sig_class = "C_REJECT"

        breakdown["total"] = total
        if _soft_applied:
            breakdown["soft_penalty"] = float(_soft_applied)
        return total, sig_class, breakdown


# =============================================================================
#  SECTION 21 — SIZING ENGINE (single canonical, fee-aware)
# =============================================================================

def _v702_unified_round_trip_cost_pct(*, measured_cost_pct=None, spread_pct=None, fee_cost_pct=None) -> Dict[str, float]:
    """Canonical round-trip cost model; measured all-in friction supersedes fallback.

    A measured PreSend value already includes order-book/VWAP friction and the
    symbol-specific venue fee, so only the configured safety buffer is added.
    When measurement is absent, the function falls back to observed spread (or
    the configured fallback), two-sided slippage, and the conservative fee rate.
    """
    return _v702_cost_model(
        CONFIG,
        measured_cost_pct=measured_cost_pct,
        spread_pct=spread_pct,
        fee_cost_pct=fee_cost_pct,
    )



class SizingEngine:
    """
    Single canonical sizing model.
    Returns a SizingDecision with full audit trail.
    """

    @staticmethod
    async def decide(exchange, symbol: str, entry: float, sl: float,
                     tp1: float, tp2: float, tp3: Optional[float] = None,
                     strategy_mode: str = "",
                     strategy_score: float = 0.0, strategy_style: str = "SCALP",
                     strategy_risk_factor: float = 1.0, quality_grade: str = "",
                     spread_pct: Optional[float] = None) -> SizingDecision:
        d = SizingDecision(mode=str(CONFIG["POSITION_SIZING_MODE"]), strategy_mode=str(strategy_mode or ""))

        # Reject malformed/non-finite price geometry before any balance/API read
        # or arithmetic.  In particular, min()/max() can mask NaN values and
        # otherwise leave NaN quantities in an otherwise rejected decision.
        try:
            entry = float(entry)
            sl = float(sl)
            tp1 = float(tp1)
            tp2 = float(tp2)
            tp3 = float(tp3) if tp3 is not None else None
            spread_pct = float(spread_pct) if spread_pct is not None else None
        except (TypeError, ValueError, OverflowError):
            d.status = "REJECT"
            d.reject_reason = "invalid_price_geometry"
            STATS["sizing_reject_invalid_price_geometry"] = int(
                STATS.get("sizing_reject_invalid_price_geometry", 0) or 0
            ) + 1
            return d

        _required_prices = (entry, sl, tp1, tp2)
        _optional_prices = (tp3,) if tp3 is not None else ()
        _spread_valid = spread_pct is None or (math.isfinite(spread_pct) and spread_pct >= 0.0)
        if (not all(math.isfinite(value) for value in (*_required_prices, *_optional_prices))
                or not _spread_valid
                or entry <= 0.0 or not (0.0 < sl < entry)
                or tp1 <= entry or tp2 <= entry):
            d.status = "REJECT"
            d.reject_reason = "invalid_price_geometry"
            STATS["sizing_reject_invalid_price_geometry"] = int(
                STATS.get("sizing_reject_invalid_price_geometry", 0) or 0
            ) + 1
            return d

        # v4.4: quality-aware risk. This can only scale BELOW the canonical
        # base risk and is hard-clamped; no strategy can increase base risk.
        try:
            factor=float(strategy_risk_factor)
            if bool(CONFIG.get("DYNAMIC_RISK_BY_QUALITY_ENABLE",True)):
                q=float(strategy_score)
                if q >= 85.0: qf=float(CONFIG.get("DYNAMIC_RISK_A_PLUS_FACTOR",1.0))
                elif q >= 80.0: qf=float(CONFIG.get("DYNAMIC_RISK_A_FACTOR",0.85))
                elif q >= 72.0: qf=float(CONFIG.get("DYNAMIC_RISK_B_FACTOR",0.65))
                else: qf=float(CONFIG.get("DYNAMIC_RISK_C_FACTOR",0.50))
                factor=min(factor,qf)
            factor=_clamp(factor,float(CONFIG.get("DYNAMIC_RISK_MIN_FACTOR",0.35)),min(1.0,float(CONFIG.get("DYNAMIC_RISK_MAX_FACTOR",1.0))))
        except Exception:
            factor=0.35
        d.adaptive_risk_factor=factor
        # 1. Balance (single truth source)
        balance, state = await BalanceReconciler.fetch(exchange)
        d.balance_state = state
        d.balance_free_usdt = balance
        if state == "BLOCK" or balance <= 0:
            d.status = "REJECT"
            d.reject_reason = "balance_block"
            return d
        # v4.0.2 PATCH D: fail-closed on CACHE for NEW entries in live
        is_live_now = bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and \
                     not bool(CONFIG.get("PAPER_TRADING_MODE", False))
        if state == "CACHE" and is_live_now and BalanceReconciler.cache_gates_new_entries():
            d.status = "REJECT"
            d.reject_reason = "balance_cache_blocks_new_entry"
            STATS["reject_balance_cache_blocks_new_entry"] = \
                STATS.get("reject_balance_cache_blocks_new_entry", 0) + 1
            return d

        # 2. Risk unit
        risk_pct = (float(CONFIG["RISK_PER_TRADE_PCT"]) / 100.0) * float(d.adaptive_risk_factor)
        target_risk_usdt = balance * risk_pct
        d.target_risk_usdt = target_risk_usdt
        risk_unit = entry - sl
        if risk_unit <= 0 or entry <= 0:
            d.status = "REJECT"
            d.reject_reason = "invalid_risk_unit"
            return d
        sl_pct = (entry - sl) / entry * 100.0
        _min_sl_pct = float(CONFIG.get("MIN_SL_PCT", 0.40))
        # V665: exact-boundary numeric tolerance only. A stop exactly at the
        # configured hard floor must not fail because binary floating-point
        # evaluates 0.40% as 0.399999999... . The floor itself is unchanged.
        if sl_pct < _min_sl_pct - 1e-9:
            d.status = "REJECT"
            d.reject_reason = "min_sl_pct_breached"
            STATS["reject_min_sl_pct"] = int(STATS.get("reject_min_sl_pct", 0) or 0) + 1
            return d
        if sl_pct > float(CONFIG["MAX_SL_PCT"]):
            d.status = "REJECT"
            d.reject_reason = "max_sl_pct_exceeded"
            return d

        # 3. Raw position
        raw_qty = target_risk_usdt / risk_unit
        raw_notional = raw_qty * entry
        d.raw_position_value = raw_notional

        # 4. Apply caps (HYBRID_CAP model)
        fixed_cap = float(CONFIG["FIXED_POSITION_SIZE_USDT"])
        max_cap = float(CONFIG["MAX_POSITION_SIZE_USDT"])
        min_notional = float(CONFIG["MIN_POSITION_SIZE_USDT"])
        d.fixed_cap = fixed_cap
        d.max_cap = max_cap
        d.min_notional = min_notional

        mode = str(CONFIG["POSITION_SIZING_MODE"]).upper()
        if mode == "FIXED":
            final_notional = min(fixed_cap, raw_notional)
            d.cap_reason = "fixed_cap"
        elif mode == "RISK_BASED":
            final_notional = min(max_cap, raw_notional)
            d.cap_reason = "max_cap" if raw_notional >= max_cap else "risk_based"
        else:  # HYBRID_CAP
            final_notional = min(max_cap, max(min(fixed_cap, raw_notional), 0.0))
            d.cap_reason = "hybrid_cap"

        # V702-R32: retain the exact risk-safe notional ceiling produced by the
        # original canonical sizing path before any grade policy is applied.
        # Grade tickets are targets/caps, never risk overrides.
        _grade_risk_safe_cap = float(final_notional)

        # V702-R31 GRADE-TICKET CLOSURE: the displayed canonical Grade is the
        # ticket policy the operator expects. Do not silently convert A into a
        # smaller risk-factor ticket. The ticket target is still bounded by
        # max/min configuration, then by the existing balance/exposure/fee and
        # execution gates below. This changes ticket sizing only; it does not
        # authorize any new opportunity or bypass any safety/economic gate.
        if bool(CONFIG.get("V702_GRADE_TICKET_SIZING_ENABLE", True)):
            try:
                _g = str(quality_grade or "").strip().upper().replace("_PLUS", "+")
                if _g in {"A+", "A_PLUS", "A PLUS"}:
                    _grade_target = float(CONFIG.get("V702_GRADE_TICKET_A_PLUS_USDT", max_cap))
                    _grade_label = "A+"
                elif _g == "A":
                    _grade_target = float(CONFIG.get("V702_GRADE_TICKET_A_USDT", max_cap))
                    _grade_label = "A"
                elif _g == "B":
                    _grade_target = float(CONFIG.get("V702_GRADE_TICKET_B_USDT", 45.0))
                    _grade_label = "B"
                elif _g == "C":
                    _grade_target = float(CONFIG.get("V702_GRADE_TICKET_C_USDT", 30.0))
                    _grade_label = "C"
                else:
                    _grade_target = 0.0
                    _grade_label = "UNKNOWN"
                if _grade_target > 0.0:
                    _grade_target = min(max_cap, max(min_notional, _grade_target))
                    # R32 closure: the grade target is an upper bound. It may
                    # never increase the risk-safe ticket already computed by
                    # SizingEngine (including the adaptive risk factor).
                    final_notional = min(_grade_risk_safe_cap, _grade_target)
                    d.cap_reason += f"|grade_ticket:{_grade_label}"
                    d.grade_ticket_usdt = float(_grade_target)
                    STATS["v702_grade_ticket_applied"] = int(STATS.get("v702_grade_ticket_applied", 0) or 0) + 1
                    STATS[f"v702_grade_ticket.{_grade_label}"] = int(STATS.get(f"v702_grade_ticket.{_grade_label}", 0) or 0) + 1
            except Exception as _grade_ticket_exc:
                # Preserve fail-safe sizing on policy-resolution uncertainty.
                final_notional = min(final_notional, max_cap)
                STATS["v702_grade_ticket_errors"] = int(STATS.get("v702_grade_ticket_errors", 0) or 0) + 1
                logger.debug("[V702-R31] grade-ticket sizing fallback: %s", _grade_ticket_exc)
        elif bool(CONFIG.get("V702_QUALITY_SCALED_TICKET_ENABLE", True)):
            # Backward-compatible fallback for explicit legacy opt-out.
            try:
                quality_cap = min(max_cap, max(min_notional, max_cap * float(d.adaptive_risk_factor)))
                if final_notional > quality_cap:
                    final_notional = quality_cap
                    d.cap_reason += "|quality_factor"
            except Exception:
                final_notional = min(final_notional, max_cap)

        # 5. Exposure headroom — v4.0.6 FIX C.
        # Count REMAINING notional, not the frozen original
        # `final_notional_after_caps`. A runner or a post-TP1 leg must not
        # reserve headroom for size it no longer holds. Falls back to the
        # original notional only when remaining_position / effective_entry
        # cannot be read safely.
        def _remaining_notional(t) -> float:
            try:
                rem = float(getattr(t, "remaining_position", 0.0) or 0.0)
                if rem <= 0:
                    return 0.0
                px = float(getattr(t, "effective_entry", 0.0) or 0.0) \
                     or float(getattr(t, "entry", 0.0) or 0.0)
                if px <= 0:
                    return float(getattr(t, "final_notional_after_caps", 0.0) or 0.0)
                return rem * px
            except Exception:
                return float(getattr(t, "final_notional_after_caps", 0.0) or 0.0)
        current_exposure = sum(_remaining_notional(t) for t in ACTIVE_TRADES.values())
        _reserve_usdt = max(0.0, float(CONFIG.get("TRADING_BALANCE_RESERVE_USDT", 0.0)))
        _cap_pct = max(0.0, min(100.0, float(CONFIG.get("MAX_TOTAL_EXPOSURE_PCT", 99.0))))
        # V666: make sizing's exposure headroom mathematically coherent with
        # the final LIVE balance preflight. A market BUY also consumes taker fee
        # plus the bounded quote-drift buffer, so reserve that cost here instead
        # of allowing SizingEngine to hand an amount to OrderExecutor that can
        # deterministically fail the last-mile balance check. The operator reserve
        # and all hard safety gates remain unchanged.
        _fee_pct = max(0.0, float(CONFIG.get("TAKER_FEE_PCT", 0.10))) / 100.0
        _buffer_pct = max(0.0, float(CONFIG.get("V626_BALANCE_PREFLIGHT_BUFFER_PCT", 0.20))) / 100.0
        _quote_factor = max(1.0, 1.0 + _fee_pct + _buffer_pct)
        _balance_room_after_costs = max(
            0.0, (balance - _reserve_usdt) / _quote_factor
        )
        exposure_cap = min(
            balance * (_cap_pct / 100.0),
            _balance_room_after_costs,
        )
        room = max(0.0, exposure_cap - current_exposure)
        if final_notional > room:
            final_notional = room
            d.cap_reason += "|exposure_room"

        # 6. Min notional check
        if final_notional < min_notional:
            d.status = "REJECT"
            d.reject_reason = "below_min_position"
            d.notional_after_caps = final_notional
            return d

        # 7. Compute quantity + effective risk
        qty = final_notional / entry
        eff_risk = qty * risk_unit
        d.notional_after_caps = final_notional
        d.quantity_asset = qty
        d.effective_risk_usdt = eff_risk
        d.risk_capture_ratio = eff_risk / max(target_risk_usdt, 1e-9)

        # 8. Fee-aware viability (P9)
        _small_net_mode = bool(CONFIG.get("V702_SMALL_NET_PROFIT_MODE_ENABLE", False))
        _fee_detail = SizingEngine.fee_viability_detail(
            entry, sl, tp1, tp2, final_notional,
            spread_pct=spread_pct, small_net_mode=_small_net_mode
        )
        if bool(_fee_detail.get("ok", False)) and _small_net_mode and tp3 is not None:
            _compression = SizingEngine.small_net_compress_targets(
                entry, sl, tp1, tp2, tp3, final_notional,
                spread_pct=spread_pct, strategy_style=strategy_style
            )
            if bool(_compression.get("applied", False)):
                d.small_net_targets_compressed = True
                d.compressed_tp1 = float(_compression["tp1"])
                d.compressed_tp2 = float(_compression["tp2"])
                d.compressed_tp3 = float(_compression["tp3"])
                d.small_net_target_compression_rr_saved = float(_compression.get("rr1_saved", 0.0) or 0.0)
                tp1, tp2, tp3 = d.compressed_tp1, d.compressed_tp2, d.compressed_tp3
                _fee_detail = dict(_compression.get("detail") or _fee_detail)
                STATS["v702_small_net_targets_compressed"] = int(STATS.get("v702_small_net_targets_compressed", 0) or 0) + 1
                STATS["v702_small_net_last_compression"] = {
                    "symbol":str(symbol), "old_tp1_rr":float(_compression.get("old_rr1", 0.0)),
                    "new_tp1_rr":float(_compression.get("new_rr1", 0.0)),
                    "old_tp2_rr":float(_compression.get("old_rr2", 0.0)),
                    "new_tp2_rr":float(_compression.get("new_rr2", 0.0)),
                    "net_profit_pct_tp1":float(_fee_detail.get("net_profit_pct_tp1", 0.0)),
                    "reason":"cost_aware_small_net_target_compression",
                    "hard_gate_bypass":False,
                }
        STATS["v702_small_net_last_fee_check"] = dict(_fee_detail)
        if not bool(_fee_detail.get("ok", False)):
            STATS["v702_fee_raw_reject"] = int(STATS.get("v702_fee_raw_reject", 0) or 0) + 1
            STATS["v702_fee_rescue_attempt"] = int(STATS.get("v702_fee_rescue_attempt", 0) or 0) + 1
            # v4.5.50 — bounded target expansion for strong PULLBACK setups.
            # This is invoked ONLY after the original canonical fee gate fails.
            # It does not lower any fee threshold and does not alter SL/risk/size.
            _rescue_ok = False
            _rescue_tp1, _rescue_tp2, _rescue_tp3 = float(tp1), float(tp2), float(tp3 or 0.0)
            _rescue_reason = ""
            try:
                _rescue_ok, _rescue_tp1, _rescue_tp2, _rescue_tp3, _rescue_reason = (
                    V420FeeRescue.try_expand_targets(
                        entry, sl, tp1, tp2, tp3, final_notional,
                        float(strategy_score), str(strategy_mode or ""),
                        spread_pct=spread_pct, small_net_mode=_small_net_mode
                    )
                )
            except Exception as _e:
                _rescue_ok = False
                _rescue_reason = f"exception:{type(_e).__name__}"

            if _rescue_ok:
                # Re-check the ORIGINAL canonical fee function with the new targets.
                _final_fee_detail = SizingEngine.fee_viability_detail(
                    entry, sl, _rescue_tp1, _rescue_tp2, final_notional,
                    spread_pct=spread_pct, small_net_mode=_small_net_mode
                )
                _v604_record_fee_rescue_forensics(
                    symbol,
                    entry=entry, sl=sl, tp1=tp1, tp2=tp2, tp3=float(tp3 or 0.0),
                    nominal=final_notional, score=float(strategy_score),
                    strategy_mode=str(strategy_mode or ""), stage="sizing",
                    result="rescue_candidate_passed" if bool(_final_fee_detail.get("ok", False))
                    else "rescue_candidate_failed",
                    detail=_final_fee_detail,
                    reason=str(_rescue_reason),
                )
                if bool(_final_fee_detail.get("ok", False)):
                    STATS["v702_fee_rescue_accept"] = int(STATS.get("v702_fee_rescue_accept", 0) or 0) + 1
                    d.status = "OK"
                    d.reject_reason = ""
                    d.fee_target_rescued = True
                    d.rescued_tp1 = float(_rescue_tp1)
                    d.rescued_tp2 = float(_rescue_tp2)
                    d.rescued_tp3 = float(_rescue_tp3)
                    d.fee_target_rescue_rr1 = (float(_rescue_tp1) - float(entry)) / max(risk_unit, 1e-12)
                    d.fee_target_rescue_rr2 = (float(_rescue_tp2) - float(entry)) / max(risk_unit, 1e-12)
                    d.net_rr_tp1 = float(_final_fee_detail.get("net_rr_tp1", 0.0) or 0.0)
                    STATS["fee_last_detail"] = _final_fee_detail
                    try:
                        STATS["v550_fee_target_rescue_reason"] = str(_rescue_reason)
                    except Exception:
                        _v647_record_suppressed_exception()
                    return d

            d.status = "REJECT"
            d.reject_reason = "fee_unviable"
            try:
                STATS["v702_fee_rescue_reject"] = int(STATS.get("v702_fee_rescue_reject", 0) or 0) + 1
                STATS["v702_fee_final_reject"] = int(STATS.get("v702_fee_final_reject", 0) or 0) + 1
                STATS["fee_unviable_count"] = STATS.get("fee_unviable_count", 0) + 1
                STATS["fee_last_detail"] = _fee_detail
                STATS["v550_fee_target_rescue_last_reject"] = str(_rescue_reason)
                _v604_record_fee_rescue_forensics(
                    symbol,
                    entry=entry, sl=sl, tp1=tp1, tp2=tp2, tp3=float(tp3 or 0.0),
                    nominal=final_notional, score=float(strategy_score),
                    strategy_mode=str(strategy_mode or ""), stage="sizing",
                    result="hard_reject",
                    detail=_fee_detail,
                    reason=str(_rescue_reason),
                )
            except Exception:
                _v647_record_suppressed_exception()
            return d

        d.status = "OK"
        d.net_rr_tp1 = float(_fee_detail.get("net_rr_tp1", 0.0) or 0.0)
        return d

    @staticmethod
    def roundtrip_fee_usdt(notional: float) -> float:
        fee_pct = float(CONFIG["TAKER_FEE_PCT"]) / 100.0
        mult = float(CONFIG["ROUNDTRIP_FEE_MULT"])
        return notional * fee_pct * mult

    @staticmethod
    def small_net_nonfee_cost_usdt(notional: float, spread_pct: Optional[float] = None) -> Dict[str, float]:
        """Non-fee remainder of the canonical shared round-trip cost model."""
        n = max(0.0, float(notional))
        fee_pct = max(0.0, float(CONFIG.get("TAKER_FEE_PCT", 0.10)) * float(CONFIG.get("ROUNDTRIP_FEE_MULT", 2.0)))
        model = _v702_unified_round_trip_cost_pct(spread_pct=spread_pct, fee_cost_pct=fee_pct)
        extra_pct = max(0.0, model["round_trip_cost_pct"] - fee_pct)
        return {
            **model,
            "extra_cost_pct": extra_pct,
            "extra_cost_usdt": n * extra_pct / 100.0,
        }

    @staticmethod
    def small_net_required_tp1_rr(entry: float, sl: float, notional: float,
                                  spread_pct: Optional[float] = None) -> float:
        """Derive the minimum TP1 RR needed for costs + net-profit floor.

        Includes round-trip commission, spread, two-sided slippage, the existing
        TP1/fee coverage ratio and a small RR safety margin. It never changes SL.
        """
        e, stop, n = float(entry), float(sl), max(0.0, float(notional))
        if e <= 0 or not (0 < stop < e) or n <= 0:
            raise ValueError("invalid_entry_stop_or_notional")
        risk_usdt = n * ((e - stop) / e)
        if risk_usdt <= 0:
            raise ValueError("invalid_risk")
        fees = SizingEngine.roundtrip_fee_usdt(n)
        extra = SizingEngine.small_net_nonfee_cost_usdt(n, spread_pct)
        total_cost = fees + extra["extra_cost_usdt"]
        net_floor = n * max(0.0, float(CONFIG.get("V702_SMALL_NET_MIN_NET_PROFIT_PCT", 0.10))) / 100.0
        min_net_rr = max(0.0, float(CONFIG.get("V702_SMALL_NET_MIN_NET_RR_TP1", 0.25)))
        fee_ratio = max(0.0, float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5)))
        rr = max(1.0, (total_cost + net_floor) / risk_usdt,
                 total_cost / risk_usdt + min_net_rr, fee_ratio * fees / risk_usdt)
        return rr + max(0.0, float(CONFIG.get("V702_SMALL_NET_RR_SAFETY_MARGIN", 0.02)))

    @staticmethod
    def small_net_compress_targets(entry: float, sl: float, tp1: float, tp2: float,
                                   tp3: Optional[float], notional: float,
                                   spread_pct: Optional[float] = None,
                                   strategy_style: str = "SCALP") -> Dict[str, Any]:
        """Compress already-viable scalp targets toward cost-aware minimums.

        This never lowers SL and never rescues a currently unviable plan. The
        proposed TP1/TP2 must still pass the same R40 net-cost check, overall
        net-R threshold, strict ordering, and downstream S/R/precision gates.
        Swing targets and plans that cannot safely compress remain unchanged.
        """
        out: Dict[str, Any] = {"applied": False, "reason": "not_applicable"}
        try:
            if not bool(CONFIG.get("V702_SMALL_NET_PROFIT_MODE_ENABLE", False)) or not bool(CONFIG.get("V702_SMALL_NET_TARGET_COMPRESSION_ENABLE", False)):
                out["reason"] = "disabled"
                return out
            style = str(strategy_style or "SCALP").strip().upper().replace("-", "_")
            if style not in {"SCALP", "SCALPING", "INTRADAY", "DAY", "DAY_TRADE", "DAYTRADE"}:
                out["reason"] = f"style_not_compressible:{style}"
                return out
            e, stop, t1, t2 = float(entry), float(sl), float(tp1), float(tp2)
            t3 = float(tp3 or 0.0)
            n = max(0.0, float(notional))
            if not (e > stop > 0 and t1 > e and t2 > t1 and t3 > t2 and n > 0):
                out["reason"] = "invalid_geometry"
                return out
            before = SizingEngine.fee_viability_detail(
                e, stop, t1, t2, n, spread_pct=spread_pct, small_net_mode=True
            )
            if not bool(before.get("ok", False)):
                out["reason"] = f"original_plan_not_viable:{before.get('reason','unknown')}"
                return out
            risk_unit = e - stop
            old_rr1 = (t1 - e) / risk_unit
            old_rr2 = (t2 - e) / risk_unit
            saving_floor = max(0.05, float(CONFIG.get("V702_SMALL_NET_TARGET_COMPRESSION_MIN_SAVING_R", 0.15)))
            rr1_buffer = max(0.0, float(CONFIG.get("V702_SMALL_NET_TARGET_TP1_BUFFER_R", 0.03)))
            rr2_buffer = max(0.0, float(CONFIG.get("V702_SMALL_NET_TARGET_TP2_BUFFER_R", 0.05)))
            target_rr1 = SizingEngine.small_net_required_tp1_rr(e, stop, n, spread_pct) + rr1_buffer
            if not math.isfinite(target_rr1) or old_rr1 - target_rr1 < saving_floor:
                out["reason"] = "tp1_saving_below_threshold"
                return out
            risk_usdt = float(before.get("risk_usdt", 0.0) or 0.0)
            cost_r = float(before.get("total_costs_usdt", 0.0) or 0.0) / max(risk_usdt, 1e-12)
            w1 = max(0.0, float(CONFIG.get("TP1_EXIT_PCT", 0.60)))
            w2 = max(0.0, float(CONFIG.get("TP2_EXIT_PCT", 0.30)))
            wr = max(0.0, float(CONFIG.get("RUNNER_KEEP_PCT_AT_TP3", 0.10))) if bool(CONFIG.get("ENABLE_RUNNER_MODE", False)) else 0.0
            wsum = w1 + w2 + wr
            if wsum <= 0 or (w2 + wr) <= 0:
                out["reason"] = "invalid_exit_weights"
                return out
            w1n = w1 / wsum
            w2n = (w2 + wr) / wsum
            overall_floor = max(0.0, float(CONFIG.get("V702_SMALL_NET_MIN_NET_RR_OVERALL", 0.50)))
            target_rr2 = max(
                float(CONFIG.get("V702_SMALL_NET_MIN_TP2_RR", 1.80)),
                target_rr1 + max(0.02, float(CONFIG.get("V702_SMALL_NET_TP2_MIN_GAP_R", 0.05))),
                (overall_floor + cost_r - w1n * target_rr1) / w2n + rr2_buffer,
            )
            max_rr2 = max(float(CONFIG.get("V702_SMALL_NET_MIN_TP2_RR", 1.80)), float(CONFIG.get("V702_SMALL_NET_MAX_TP2_RR", 3.20)))
            if not math.isfinite(target_rr2) or target_rr2 > max_rr2 + 1e-9:
                out["reason"] = "required_tp2_rr_exceeds_compression_cap"
                return out
            # Never move TP2 farther away while claiming this is compression.
            target_rr2 = min(old_rr2, target_rr2)
            if target_rr2 <= target_rr1 + 1e-9:
                out["reason"] = "compressed_targets_not_ordered"
                return out
            nt1 = e + target_rr1 * risk_unit
            nt2 = e + target_rr2 * risk_unit
            # Keep the runner target above TP2; it is intentionally not used to
            # justify an otherwise unviable TP1/TP2 plan.
            nt3 = t3
            after = SizingEngine.fee_viability_detail(
                e, stop, nt1, nt2, n, spread_pct=spread_pct, small_net_mode=True
            )
            if not bool(after.get("ok", False)):
                out["reason"] = f"compressed_plan_not_viable:{after.get('reason','unknown')}"
                out["detail"] = after
                return out
            if old_rr1 - target_rr1 < saving_floor:
                out["reason"] = "tp1_saving_below_threshold_after_checks"
                return out
            return {
                "applied": True, "reason": "cost_aware_small_net_target_compression",
                "tp1": nt1, "tp2": nt2, "tp3": nt3,
                "old_rr1": old_rr1, "new_rr1": target_rr1,
                "old_rr2": old_rr2, "new_rr2": target_rr2,
                "rr1_saved": old_rr1 - target_rr1,
                "before": before, "detail": after,
                "hard_gate_bypass": False, "stop_loss_changed": False,
            }
        except Exception as exc:
            return {"applied": False, "reason": f"exception:{type(exc).__name__}"}

    @staticmethod
    def fee_viability_detail(entry: float, sl: float, tp1: float, tp2: float,
                             notional: float,
                             fee_ratio_override: Optional[float] = None,
                             spread_pct: Optional[float] = None,
                             small_net_mode: bool = False) -> Dict[str, Any]:
        try:
            e, stop, t1, t2, n = float(entry), float(sl), float(tp1), float(tp2), max(0.0, float(notional))
            if e <= 0 or not (0 < stop < e) or not (t1 > e and t2 > e) or n <= 0:
                return {"ok": False, "reason": "invalid_risk_or_geometry"}
            fees = SizingEngine.roundtrip_fee_usdt(n)
            risk_usdt = n * ((e - stop) / e)
            if risk_usdt <= 0:
                return {"ok":False,"reason":"invalid_risk"}
            extra = SizingEngine.small_net_nonfee_cost_usdt(n, spread_pct) if small_net_mode else {
                "spread_pct_used": 0.0, "slippage_per_side_pct": 0.0,
                "extra_cost_pct": 0.0, "extra_cost_usdt": 0.0}
            total_costs = fees + float(extra["extra_cost_usdt"])
            gross_tp1 = n * ((t1-e)/e)
            net_profit_tp1 = gross_tp1 - total_costs
            net_profit_pct_tp1 = 100.0 * net_profit_tp1 / n
            net_rr_tp1 = net_profit_tp1 / risk_usdt
            _exit_w1 = max(0.0, float(CONFIG.get("TP1_EXIT_PCT", 0.60)))
            _exit_w2 = max(0.0, float(CONFIG.get("TP2_EXIT_PCT", 0.30)))
            _exit_wr = (max(0.0, float(CONFIG.get("RUNNER_KEEP_PCT_AT_TP3", 0.10)))
                        if bool(CONFIG.get("ENABLE_RUNNER_MODE", True)) else 0.0)
            _exit_weight_total = _exit_w1 + _exit_w2 + _exit_wr
            _tp1_partial_fraction = (_exit_w1 / _exit_weight_total) if _exit_weight_total > 0 else 0.0
            _tp1_partial_net_usdt = net_profit_tp1 * _tp1_partial_fraction
            _tp1_partial_cost_usdt = total_costs * _tp1_partial_fraction
            _tp1_partial_net_pct_of_original = 100.0 * _tp1_partial_net_usdt / n
            _tp1_partial_net_pct_of_sold = (100.0 * _tp1_partial_net_usdt / (n * _tp1_partial_fraction)
                                             if _tp1_partial_fraction > 0 else 0.0)
            req_tp1 = (max(0.0, float(CONFIG.get("V702_SMALL_NET_MIN_NET_RR_TP1", 0.25)))
                       if small_net_mode else float(CONFIG["MIN_NET_RR_TP1"]))
            fee_ratio = (float(fee_ratio_override) if fee_ratio_override is not None
                         else float(CONFIG["MIN_TP1_TO_FEE_RATIO"]))
            net_floor_pct = max(0.0, float(CONFIG.get("V702_SMALL_NET_MIN_NET_PROFIT_PCT", 0.10))) if small_net_mode else 0.0
            base = {"fees":fees, "extra_costs_usdt":float(extra["extra_cost_usdt"]),
                    "total_costs_usdt":total_costs, "risk_usdt":risk_usdt,
                    "gross_tp1":gross_tp1, "net_profit_tp1_usdt":net_profit_tp1,
                    "TP1_FULL_CLOSE_NET_USDT":net_profit_tp1,
                    "TP1_FULL_CLOSE_NET_PCT":net_profit_pct_tp1,
                    "TP1_PARTIAL_EXIT_FRACTION":_tp1_partial_fraction,
                    "TP1_PARTIAL_REALIZED_NET_USDT":_tp1_partial_net_usdt,
                    "TP1_PARTIAL_REALIZED_COST_USDT":_tp1_partial_cost_usdt,
                    "TP1_PARTIAL_REALIZED_NET_PCT_OF_ORIGINAL":_tp1_partial_net_pct_of_original,
                    "TP1_PARTIAL_REALIZED_NET_PCT_OF_SOLD":_tp1_partial_net_pct_of_sold,
                    "net_profit_pct_tp1":net_profit_pct_tp1, "net_rr_tp1":net_rr_tp1,
                    "spread_pct_used":float(extra["spread_pct_used"]),
                    "slippage_per_side_pct":float(extra["slippage_per_side_pct"])}
            if net_rr_tp1 < req_tp1 - 1e-9:
                return {**base, "ok":False,"reason":"tp1_net_rr","actual":net_rr_tp1,"required":req_tp1}
            if small_net_mode and net_profit_pct_tp1 + 1e-12 < net_floor_pct:
                return {**base, "ok":False, "reason":"tp1_net_profit_pct",
                        "actual":net_profit_pct_tp1, "required":net_floor_pct}
            # The historical TP1/fee ratio stays based on commission and is never reduced.
            if gross_tp1 + 1e-12 < fee_ratio*fees:
                return {**base, "ok":False,"reason":"tp1_fee_ratio","actual":gross_tp1,"required":fee_ratio*fees}
            gross_tp2 = n * ((t2-e)/e)
            w1=float(CONFIG.get("TP1_EXIT_PCT",0.5)); w2=float(CONFIG.get("TP2_EXIT_PCT",0.5))
            wr=float(CONFIG.get("RUNNER_KEEP_PCT_AT_TP3",0.0)) if bool(CONFIG.get("ENABLE_RUNNER_MODE",False)) else 0.0
            ws=w1+w2+wr
            if ws<=0: return {**base, "ok":False,"reason":"invalid_exit_weights"}
            blended=((w1*gross_tp1)+((w2+wr)*gross_tp2))/ws
            net_overall=(blended-total_costs)/risk_usdt
            req_overall=(max(0.0, float(CONFIG.get("V702_SMALL_NET_MIN_NET_RR_OVERALL", 0.50)))
                         if small_net_mode else float(CONFIG["MIN_NET_RR_OVERALL"]))
            out = {**base, "gross_tp2":gross_tp2,"blended_gross":blended,
                   "net_rr_overall":net_overall,"required_min_tp1_rr":req_tp1,
                   "required_min_net_rr_overall":req_overall,
                   "required_min_net_profit_pct_tp1":net_floor_pct,
                   "small_net_mode":bool(small_net_mode)}
            return ({**out,"ok":True,"reason":"ok"} if net_overall >= req_overall - 1e-9
                    else {**out,"ok":False,"reason":"overall_net_rr","actual":net_overall,"required":req_overall})
        except Exception as e:
            return {"ok":False,"reason":f"exception:{type(e).__name__}"}

    @staticmethod
    def fee_viability_ok(entry: float, sl: float, tp1: float, tp2: float, notional: float) -> bool:
        try:
            return bool(SizingEngine.fee_viability_detail(entry, sl, tp1, tp2, notional).get("ok",False))
        except Exception:
            return False


# =============================================================================
#  SECTION 22 — LIQUIDITY DEPTH / EXPOSURE / RISK COHERENCE (pre-send checks)
# =============================================================================

class LiquidityDepth:
    @staticmethod
    async def check(exchange, symbol: str, required_notional: float,
                    cached_ob: Optional[Dict[str, Any]] = None
                    ) -> Tuple[bool, str, float]:
        """v4.0.9 DS-6 — accepts an optional `cached_ob` (the orderbook already
        fetched in the scoring path). When it carries usable asks we skip the
        second fetch_order_book call; otherwise we fall back to a fresh fetch
        to preserve the fail-closed contract."""
        try:
            ob = None
            if cached_ob and isinstance(cached_ob, dict):
                _asks_cache = cached_ob.get("asks") or []
                if _asks_cache:
                    ob = cached_ob
                    try:
                        STATS["ld_ob_cache_reused"] = STATS.get("ld_ob_cache_reused", 0) + 1
                    except Exception:
                        _v647_record_suppressed_exception()
            if ob is None:
                ob = await safe_api_call(
                    f"fetch_ob_{symbol}",
                    lambda: exchange.fetch_order_book(symbol, limit=20),
                    retry_safe=True,
                )
                try:
                    STATS["ld_ob_cache_missed"] = STATS.get("ld_ob_cache_missed", 0) + 1
                except Exception:
                    _v647_record_suppressed_exception()
            asks = ob.get("asks", [])[:5]
            if not asks:
                return False, "empty_book", 0.0
            cum_notional = sum(px * qty for px, qty in asks)
            ratio = cum_notional / max(required_notional, 1e-9)
            if ratio < float(CONFIG["MIN_ORDER_BOOK_DEPTH_RATIO"]):
                return False, "insufficient_depth", ratio
            return True, "ok", ratio
        except Exception as e:
            return False, f"error:{e}", 0.0


# ---------------------------------------------------------------------------
# v4.2.2 ENHANCEMENT (1) — CORRELATION HARD-CAP on simultaneous long exposure.
# The existing CORRELATION_SOFT_PENALTY_MAX only nudges the SCORE. This layer
# adds a portfolio-level HARD ceiling: no more than N open longs inside the
# same correlation cluster (default majors). Fail-closed: any evaluation
# error => entry REFUSED. Long-only spot semantics preserved.
# ---------------------------------------------------------------------------
_CORR_CLUSTERS: Tuple[frozenset, ...] = (
    frozenset({"BTC/USDT", "ETH/USDT", "SOL/USDT", "BNB/USDT", "XRP/USDT",
               "ADA/USDT", "DOGE/USDT", "AVAX/USDT", "LINK/USDT", "DOT/USDT",
               "LTC/USDT", "TRX/USDT", "ATOM/USDT", "NEAR/USDT"}),  # majors / high-beta
)

class CorrelationHardCap:
    """Portfolio-level clustering guard for simultaneous LONG spot exposure."""

    @staticmethod
    def _cluster_of(symbol: str) -> Optional[frozenset]:
        for cl in _CORR_CLUSTERS:
            if symbol in cl:
                return cl
        return None

    @classmethod
    def check(cls, symbol: str) -> Tuple[bool, str]:
        try:
            if not CONFIG.get("CORRELATION_HARD_CAP_ENABLE", True):
                return True, "ok"
            cl = cls._cluster_of(symbol)
            if cl is None:
                return True, "ok"  # symbol not in any tracked cluster
            cap = int(CONFIG.get("CORRELATION_HARD_CAP_MAX_CLUSTER", 2))
            open_in_cluster = sum(
                1 for s in ACTIVE_TRADES.keys() if s in cl
            )
            if open_in_cluster >= cap:
                return False, f"correlation_hard_cap({open_in_cluster}/{cap} in cluster)"
            return True, "ok"
        except Exception as e:
            # Fail-closed: refuse the entry on any evaluation error.
            return False, f"correlation_hard_cap_error:{e}"



# ---------------------------------------------------------------------------
# v4.2.2 ENHANCEMENT (4) — PER-SYMBOL EXPECTANCY COOLDOWN.
# Bounded + in-memory. Fail-closed on evaluation errors.
# ---------------------------------------------------------------------------
_SYMBOL_R_LEDGER: Dict[str, list] = {}
_SYMBOL_CD: Dict[str, float] = {}

class SymbolExpectancyCooldown:
    @classmethod
    def record(cls, symbol: str, realized_r: float) -> None:
        try:
            if not CONFIG.get("SYMBOL_EXPECTANCY_CD_ENABLE", True):
                return
            led = _SYMBOL_R_LEDGER.setdefault(symbol, [])
            led.append(float(realized_r))
            # bound the ledger
            while len(led) > 64:
                led.pop(0)
            min_trades = int(CONFIG.get("SYMBOL_EXPECTANCY_MIN_TRADES", 4))
            if len(led) >= min_trades:
                window = led[-min_trades:]
                avg = sum(window) / max(len(window), 1)
                if avg <= float(CONFIG.get("SYMBOL_EXPECTANCY_MIN_AVG_R", -0.5)):
                    _SYMBOL_CD[symbol] = MONO_NOW() + float(
                        CONFIG.get("SYMBOL_EXPECTANCY_CD_SEC", 7200))
                    logger.warning(
                        f"[ExpectancyCD] {symbol} cooldown armed: avg_r={avg:+.3f} "
                        f"over last {len(window)} trades"
                    )
                    led.clear()  # avoid immediate re-trigger
        except Exception as e:
            logger.debug(f"[ExpectancyCD] record suppressed {symbol}: {e}")

    @classmethod
    def check(cls, symbol: str) -> Tuple[bool, str]:
        try:
            if not CONFIG.get("SYMBOL_EXPECTANCY_CD_ENABLE", True):
                return True, "ok"
            until = _SYMBOL_CD.get(symbol, 0.0)
            _now_sec = MONO_NOW()
            if until and _now_sec < until:
                return False, f"symbol_expectancy_cooldown({int(until - _now_sec)}s)"
            if until and _now_sec >= until:
                _SYMBOL_CD.pop(symbol, None)
            return True, "ok"
        except Exception as e:
            return False, f"symbol_expectancy_cd_error:{e}"


# ---------------------------------------------------------------------------
# v4.4 — STRATEGY EXPECTANCY MEMORY / SYMBOL×STRATEGY MEMORY
# Persistent, bounded and ranking-only. Adaptive memory can never override a
# crash guard, hard gate, SL/RR invariant, sizing cap or execution block.
# ---------------------------------------------------------------------------
_STRAT_EXP_MEM: Dict[Tuple[str,str,str,str], Dict[str,float]] = {}
_SYM_STRAT_EXP_MEM: Dict[Tuple[str,str], Dict[str,float]] = {}

class StrategyPerformanceMemory:
    _loaded = False
    _db_ready = False

    @staticmethod
    def session_bucket(ts: Optional[float] = None) -> str:
        try:
            h = datetime.fromtimestamp(float(ts or WALL_NOW()), tz=timezone.utc).hour
            if 7 <= h < 13: return "LONDON"
            if 13 <= h < 16: return "LONDON_NY_OVERLAP"
            if 16 <= h < 21: return "NEW_YORK"
            if 0 <= h < 7: return "ASIA"
            return "OFF_HOURS"
        except Exception:
            return "UNKNOWN"

    @classmethod
    def _ensure_db(cls) -> None:
        if cls._db_ready: return
        conn = None
        try:
            table=str(CONFIG.get("STRATEGY_EXPECTANCY_DB_TABLE","strategy_expectancy_v44"))
            conn=sqlite3.connect(str(CONFIG.get("DB_PATH","./unified_scalper.db")),timeout=3)
            conn.execute(f"CREATE TABLE IF NOT EXISTS {table} (strategy TEXT NOT NULL, regime TEXT NOT NULL, session TEXT NOT NULL, style TEXT NOT NULL, trades INTEGER NOT NULL, sum_r REAL NOT NULL, sum_r2 REAL NOT NULL, updated_ts REAL NOT NULL, PRIMARY KEY(strategy,regime,session,style))")
            stable=str(CONFIG.get("SYMBOL_STRATEGY_EXPECTANCY_DB_TABLE","symbol_strategy_expectancy_v44"))
            conn.execute(f"CREATE TABLE IF NOT EXISTS {stable} (symbol TEXT NOT NULL, strategy TEXT NOT NULL, trades INTEGER NOT NULL, sum_r REAL NOT NULL, updated_ts REAL NOT NULL, PRIMARY KEY(symbol,strategy))")
            conn.commit(); cls._db_ready=True
        except Exception as exc:
            logger.debug(f"[V44.Expectancy] DB init suppressed: {exc}")
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @classmethod
    def _load_once(cls) -> None:
        if cls._loaded: return
        cls._ensure_db()
        conn = None
        try:
            if cls._db_ready:
                table=str(CONFIG.get("STRATEGY_EXPECTANCY_DB_TABLE","strategy_expectancy_v44"))
                conn=sqlite3.connect(str(CONFIG.get("DB_PATH","./unified_scalper.db")),timeout=3)
                rows=conn.execute(f"SELECT strategy,regime,session,style,trades,sum_r,sum_r2 FROM {table} ORDER BY updated_ts DESC LIMIT ?",(int(CONFIG.get("STRATEGY_EXPECTANCY_MAX_KEYS",128)),)).fetchall()
                for strategy,regime,session,style,trades,sum_r,sum_r2 in rows:
                    _STRAT_EXP_MEM[(str(strategy),str(regime),str(session),str(style))]={"n":float(trades),"sum":float(sum_r),"sum2":float(sum_r2)}
                stable=str(CONFIG.get("SYMBOL_STRATEGY_EXPECTANCY_DB_TABLE","symbol_strategy_expectancy_v44"))
                for symbol,strategy,trades,sum_r in conn.execute(f"SELECT symbol,strategy,trades,sum_r FROM {stable} ORDER BY updated_ts DESC LIMIT ?",(int(CONFIG.get("STRATEGY_EXPECTANCY_MAX_KEYS",128))*8,)).fetchall():
                    _SYM_STRAT_EXP_MEM[(str(symbol),str(strategy))]={"n":float(trades),"sum":float(sum_r)}
        except Exception as exc:
            logger.debug(f"[V44.Expectancy] load suppressed: {exc}")
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass
        cls._loaded=True

    @classmethod
    def record(cls,strategy:str,regime:str,session:str,style:str,realized_r:float,symbol:str="") -> None:
        try:
            if not CONFIG.get("STRATEGY_EXPECTANCY_ENABLE",True): return
            s=str(strategy or "UNKNOWN").upper(); r=str(regime or "UNKNOWN").upper(); se=str(session or cls.session_bucket()).upper(); st=str(style or "SCALP").upper(); x=float(realized_r)
            if not math.isfinite(x): return
            key=(s,r,se,st); rec=_STRAT_EXP_MEM.setdefault(key,{"n":0.0,"sum":0.0,"sum2":0.0})
            rec["n"]+=1.0; rec["sum"]+=x; rec["sum2"]+=x*x
            max_keys=int(CONFIG.get("STRATEGY_EXPECTANCY_MAX_KEYS",128))
            if len(_STRAT_EXP_MEM)>max_keys:
                victim=min(_STRAT_EXP_MEM.items(),key=lambda kv:(kv[1].get("n",0.0),kv[0]))[0]
                if victim!=key: _STRAT_EXP_MEM.pop(victim,None)
            if symbol and CONFIG.get("SYMBOL_STRATEGY_EXPECTANCY_ENABLE",True):
                sk=(str(symbol),s); sr=_SYM_STRAT_EXP_MEM.setdefault(sk,{"n":0.0,"sum":0.0}); sr["n"]+=1.0; sr["sum"]+=x
                if len(_SYM_STRAT_EXP_MEM)>max_keys*8:
                    victim2=min(_SYM_STRAT_EXP_MEM.items(),key=lambda kv:kv[1].get("n",0.0))[0]; _SYM_STRAT_EXP_MEM.pop(victim2,None)
            cls._ensure_db()
            if cls._db_ready:
                table=str(CONFIG.get("STRATEGY_EXPECTANCY_DB_TABLE","strategy_expectancy_v44"))
                conn = None
                try:
                    conn=sqlite3.connect(str(CONFIG.get("DB_PATH","./unified_scalper.db")),timeout=3)
                    conn.execute(f"INSERT INTO {table}(strategy,regime,session,style,trades,sum_r,sum_r2,updated_ts) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(strategy,regime,session,style) DO UPDATE SET trades=excluded.trades,sum_r=excluded.sum_r,sum_r2=excluded.sum_r2,updated_ts=excluded.updated_ts",(s,r,se,st,int(rec["n"]),rec["sum"],rec["sum2"],WALL_NOW()))
                    if symbol and CONFIG.get("SYMBOL_STRATEGY_EXPECTANCY_ENABLE",True):
                        stable=str(CONFIG.get("SYMBOL_STRATEGY_EXPECTANCY_DB_TABLE","symbol_strategy_expectancy_v44")); sr=_SYM_STRAT_EXP_MEM.get((str(symbol),s),{"n":0.0,"sum":0.0})
                        conn.execute(f"INSERT INTO {stable}(symbol,strategy,trades,sum_r,updated_ts) VALUES(?,?,?,?,?) ON CONFLICT(symbol,strategy) DO UPDATE SET trades=excluded.trades,sum_r=excluded.sum_r,updated_ts=excluded.updated_ts",(str(symbol),s,int(sr["n"]),sr["sum"],WALL_NOW()))
                    conn.commit()
                except Exception as exc:
                    logger.debug(f"[V44.Expectancy] persist suppressed: {exc}")
                finally:
                    if conn is not None:
                        try: conn.close()
                        except Exception: pass
        except Exception as exc:
            logger.debug(f"[V44.Expectancy] record suppressed: {exc}")

    @classmethod
    def _stats(cls,strategy:str,regime:str,session:str,style:str):
        cls._load_once()
        rec=_STRAT_EXP_MEM.get((str(strategy).upper(),str(regime).upper(),str(session).upper(),str(style).upper()))
        if not rec or rec.get("n",0)<int(CONFIG.get("STRATEGY_EXPECTANCY_MIN_TRADES",8)): return None
        n=max(1.0,float(rec["n"])); avg=float(rec["sum"])/n
        var=max(0.0,float(rec["sum2"])/n-avg*avg); return n,avg,math.sqrt(var)

    @classmethod
    def rank_adjustment(cls,strategy:str,regime:str,session:str,style:str,symbol:str="") -> float:
        try:
            cap=float(CONFIG.get("STRATEGY_EXPECTANCY_ADJUSTMENT_CAP",0.04)); shrink=max(0.5,float(CONFIG.get("STRATEGY_EXPECTANCY_SHRINK_R",0.75))); adj=0.0
            st=cls._stats(strategy,regime,session,style)
            if st:
                _,avg,_=st; scale=float(CONFIG.get("STRATEGY_EXPECTANCY_POS_BONUS_CAP",0.025)) if avg>=0 else float(CONFIG.get("STRATEGY_EXPECTANCY_NEG_PENALTY_CAP",0.04))
                adj += _clamp(avg/shrink,-1.0,1.0)*scale
            if symbol and CONFIG.get("SYMBOL_STRATEGY_EXPECTANCY_ENABLE",True):
                sr=_SYM_STRAT_EXP_MEM.get((str(symbol),str(strategy).upper()))
                if sr and sr.get("n",0)>=int(CONFIG.get("SYMBOL_STRATEGY_EXPECTANCY_MIN_TRADES",4)):
                    savg=float(sr["sum"])/max(float(sr["n"]),1.0); adj += _clamp(savg/shrink,-1.0,1.0)*float(CONFIG.get("SYMBOL_STRATEGY_EXPECTANCY_PENALTY_CAP",0.03))
            return _clamp(adj,-cap,cap)
        except Exception: return 0.0

    @classmethod
    def score_floor_adjustment(cls,strategy:str,regime:str,session:str,style:str) -> float:
        try:
            st=cls._stats(strategy,regime,session,style)
            if not st: return 0.0
            _,avg,_=st
            return min(3.0,abs(avg)*2.0) if avg<-0.35 else 0.0
        except Exception: return 0.0


# ---------------------------------------------------------------------------
# v4.2.2 ENHANCEMENT (5) — NEWS BLACKOUT FILTER (optional, env-fed).
# SCALPER_NEWS_BLACKOUT_TS = "<unix_ts>,<unix_ts>,...". Bounded window around
# each event. No-op unless explicitly enabled AND timestamps are provided.
# Fail-closed ONLY while a blackout window is actively in effect.
# ---------------------------------------------------------------------------
def _load_news_blackout_ts() -> list:
    out = []
    try:
        raw = os.environ.get("SCALPER_NEWS_BLACKOUT_TS", "") or ""
        for tok in raw.split(","):
            tok = tok.strip()
            if not tok:
                continue
            try:
                out.append(float(tok))
            except Exception:
                continue
    except Exception as e:
        try:
            STATS["signal_handler_install_errors"] = STATS.get("signal_handler_install_errors", 0) + 1
        except Exception:
            _v647_record_suppressed_exception()
        logger.warning(f"[SignalHandlers] install suppressed: {e}")
    return out

_NEWS_EVENTS_TS: list = _load_news_blackout_ts()

class NewsBlackout:
    @staticmethod
    def check() -> Tuple[bool, str]:
        try:
            if not CONFIG.get("NEWS_BLACKOUT_ENABLE", False):
                return True, "ok"
            if not _NEWS_EVENTS_TS:
                return True, "ok"
            # SCALPER_NEWS_BLACKOUT_TS values are UNIX epoch timestamps;
            # compare them in the same WALL clock domain, never monotonic time.
            now = WALL_NOW()
            pre = float(CONFIG.get("NEWS_BLACKOUT_PRE_SEC", 900))
            post = float(CONFIG.get("NEWS_BLACKOUT_POST_SEC", 900))
            for ev in _NEWS_EVENTS_TS:
                if (ev - pre) <= now <= (ev + post):
                    return False, f"news_blackout_window(event@{int(ev)})"
            return True, "ok"
        except Exception as e:
            return False, f"news_blackout_error:{e}"


class ExposureProtection:
    """
    Effective exposure protection — uses BOTH concurrent-count AND
    balance-relative total-exposure cap.  No computed-without-effect variables.
    """

    @staticmethod
    def check(new_notional: float,
              balance_free: Optional[float] = None,
              symbol: str = "") -> Tuple[bool, str]:
        # 1. Concurrent trades count
        cur_open = len(ACTIVE_TRADES)
        max_open = int(CONFIG["MAX_CONCURRENT_TRADES"])
        if cur_open >= max_open:
            return False, f"max_concurrent_trades({cur_open}/{max_open})"

        # 1b. v4.2.2 ENHANCEMENT (1) — correlation hard-cap (fail-closed).
        if symbol:
            _ok_corr, _why_corr = CorrelationHardCap.check(symbol)
            if not _ok_corr:
                return False, _why_corr

        # 2. Total exposure (sum of REMAINING notionals) — v4.0.6 FIX C.
        # Using remaining_position * effective_entry avoids over-reservation
        # by runners / post-TP1 legs that already exited part of their size.
        def _remaining_notional(t) -> float:
            try:
                rem = float(getattr(t, "remaining_position", 0.0) or 0.0)
                if rem <= 0:
                    return 0.0
                px = float(getattr(t, "effective_entry", 0.0) or 0.0) \
                     or float(getattr(t, "entry", 0.0) or 0.0)
                if px <= 0:
                    return float(getattr(t, "final_notional_after_caps", 0.0) or 0.0)
                return rem * px
            except Exception:
                return float(getattr(t, "final_notional_after_caps", 0.0) or 0.0)
        total_exposure = sum(
            _remaining_notional(t) for t in ACTIVE_TRADES.values()
        )

        # 3. Balance-relative cap (effective, not cosmetic)
        if bool(CONFIG.get("EXPOSURE_USE_BALANCE_RELATIVE_CAP", True)):
            bal = balance_free if balance_free is not None and balance_free > 0 \
                  else BalanceReconciler._last_real_value
            if bal > 0:
                _reserve_usdt = max(0.0, float(CONFIG.get("TRADING_BALANCE_RESERVE_USDT", 0.0)))
                _cap_pct = max(0.0, min(100.0, float(CONFIG.get("MAX_TOTAL_EXPOSURE_PCT", 99.0))))
                # V666: align the exposure cap with the final real-balance
                # preflight's fee + drift buffer. This removes a deterministic
                # sizing/execution mismatch without relaxing the reserve.
                _fee_pct = max(0.0, float(CONFIG.get("TAKER_FEE_PCT", 0.10))) / 100.0
                _buffer_pct = max(0.0, float(CONFIG.get("V626_BALANCE_PREFLIGHT_BUFFER_PCT", 0.20))) / 100.0
                _quote_factor = max(1.0, 1.0 + _fee_pct + _buffer_pct)
                exposure_cap = min(
                    bal * (_cap_pct / 100.0),
                    max(0.0, (bal - _reserve_usdt) / _quote_factor),
                )
                projected = total_exposure + new_notional
                if projected > exposure_cap:
                    return False, (f"exposure_cap_exceeded"
                                   f"(total={total_exposure:.2f}+new={new_notional:.2f}"
                                   f"={projected:.2f} > cap={exposure_cap:.2f})")
            elif bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and \
                 not bool(CONFIG.get("PAPER_TRADING_MODE", False)):
                # LIVE mode + no trusted balance => fail-closed
                return False, "exposure_no_trusted_balance"

        # 4. Zero / negative notional
        if new_notional <= 0:
            return False, "zero_notional"

        return True, "ok"


class RiskCoherence:
    @staticmethod
    def check(entry: float, sl: float, tp1: float, tp2: float,
              tp3: Optional[float] = None) -> Tuple[bool, str]:
        """v4.0.6 FIX #2 / #3:
          FIX #2: replace the hidden `MAX_SL_PCT * 3.0` multiplier with a
                  direct, explicit ceiling `RISK_COHERENCE_MAX_SL_PCT`.
                  Falls back to `MAX_SL_PCT * 3.0` only when the new key is
                  absent from CONFIG (backward-compat).
          FIX #3: optionally validate tp3 ordering (sl < entry < tp1 < tp2 < tp3)
                  when tp3 is provided, so the post-repricing invariant can
                  be enforced through this single canonical checker.
        """
        if entry <= 0 or sl <= 0 or tp1 <= 0 or tp2 <= 0:
            return False, "non_positive_price"
        if entry <= sl:
            return False, "entry_le_sl"
        if tp1 <= entry or tp2 <= tp1:
            return False, "tp_ordering"
        if tp3 is not None:
            if tp3 <= 0:
                return False, "non_positive_price"
            if tp3 <= tp2:
                return False, "tp_ordering"
        sl_pct = (entry - sl) / entry * 100.0
        rc_min_sl = float(CONFIG.get("MIN_SL_PCT", 0.40))
        # V665: exact-boundary numeric tolerance only. A stop exactly at the
        # configured hard floor must not fail because binary floating-point
        # represents 0.40% as a value fractionally below 0.40. The configured
        # floor is unchanged; a true breach still fails closed.
        if not math.isfinite(sl_pct) or sl_pct < rc_min_sl - 1e-9:
            return False, "sl_too_tight"
        # v4.0.6 FIX #2 — explicit ceiling; no hidden multiplier.
        rc_max_sl = float(CONFIG.get(
            "RISK_COHERENCE_MAX_SL_PCT",
            float(CONFIG["MAX_SL_PCT"]) * 3.0,
        ))
        if sl_pct > rc_max_sl:
            return False, "sl_too_wide"
        return True, "ok"


# =============================================================================
#  SECTION 23 — DAILY CIRCUIT BREAKERS + FAILED-SEND CB
# =============================================================================


class DailyCircuitBreaker:
    _date: str = ""
    _realized_r: float = 0.0
    _trades: int = 0
    _blocked_reason: Optional[str] = None
    # V702 R4 — persisted consecutive-loss state.
    _consecutive_losses: int = 0
    _loss_streak_block_until: float = 0.0

    @classmethod
    def _snapshot(cls) -> Dict[str, Any]:
        return {
            "date": cls._date,
            "realized_r": cls._realized_r,
            "daily_trades": cls._trades,
            "blocked_reason": cls._blocked_reason,
            "consecutive_losses": int(cls._consecutive_losses),
            "loss_streak_block_until": float(cls._loss_streak_block_until),
        }

    @classmethod
    def _persist(cls) -> None:
        try:
            DBManager.save_daily_state(
                cls._date,
                cls._realized_r,
                cls._trades,
                cls._blocked_reason,
                int(cls._consecutive_losses),
                float(cls._loss_streak_block_until),
            )
        except Exception as e:
            logger.debug(f"[DailyCB] persist suppressed: {e}")

    @classmethod
    def restore_state(cls) -> None:
        try:
            row = DBManager.load_daily_state()
            if not row:
                return
            cls._date = str(row.get("date") or cls._date)
            cls._realized_r = float(row.get("realized_r") or 0.0)
            cls._trades = int(row.get("daily_trades") or 0)
            cls._blocked_reason = row.get("blocked_reason") or None
            cls._consecutive_losses = max(0, int(row.get("consecutive_losses") or 0))
            cls._loss_streak_block_until = max(0.0, float(row.get("loss_streak_block_until") or 0.0))
            logger.info(
                f"[DailyCB] restored date={cls._date} trades={cls._trades} "
                f"realized_r={cls._realized_r:+.3f} blocked={cls._blocked_reason}"
            )
        except Exception as e:
            logger.debug(f"[DailyCB] restore suppressed: {e}")

    @classmethod
    async def arestore_state(cls) -> None:
        """v4.2.2 FIX — non-blocking variant: the SQLite read is offloaded to
        a worker thread so run_bot's event loop is never stalled at boot."""
        try:
            row = await DBManager.aload_daily_state()
            if not row:
                return
            cls._date = str(row.get("date") or cls._date)
            cls._realized_r = float(row.get("realized_r") or 0.0)
            cls._trades = int(row.get("daily_trades") or 0)
            cls._blocked_reason = row.get("blocked_reason") or None
            cls._consecutive_losses = max(0, int(row.get("consecutive_losses") or 0))
            cls._loss_streak_block_until = max(0.0, float(row.get("loss_streak_block_until") or 0.0))
            logger.info(
                f"[DailyCB] restored date={cls._date} trades={cls._trades} "
                f"realized_r={cls._realized_r:+.3f} blocked={cls._blocked_reason}"
            )
        except Exception as e:
            logger.debug(f"[DailyCB] arestore suppressed: {e}")

    @classmethod
    def _reset_if_new_day(cls):
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        if cls._date != today:
            cls._date = today
            cls._realized_r = 0.0
            cls._trades = 0
            cls._blocked_reason = None
            cls._consecutive_losses = 0
            cls._loss_streak_block_until = 0.0
            cls._persist()

    @classmethod
    def can_open_new(cls) -> Tuple[bool, str]:
        cls._reset_if_new_day()
        if cls._blocked_reason:
            return False, cls._blocked_reason
        # V702 R4 — temporary loss-streak throttle. This is intentionally
        # independent from candidate scoring/policy so it cannot make the
        # strategy itself stricter; it only pauses the portfolio briefly.
        if bool(CONFIG.get("V702_LOSS_STREAK_COOLDOWN_ENABLE", True)):
            now = float(WALL_NOW())
            until = float(cls._loss_streak_block_until or 0.0)
            if until > now:
                remain = int(max(1.0, until - now))
                return False, f"consecutive_loss_cooldown:{remain}s"
            if until > 0.0:
                cls._loss_streak_block_until = 0.0
                cls._persist()
        if cls._trades >= int(CONFIG["DAILY_MAX_TRADES"]):
            cls._blocked_reason = "daily_max_trades"
            cls._persist()
            return False, cls._blocked_reason
        if cls._realized_r <= float(CONFIG["DAILY_MAX_LOSS_R"]):
            cls._blocked_reason = "daily_max_loss_r"
            cls._persist()
            return False, cls._blocked_reason
        if cls._realized_r >= float(CONFIG["DAILY_MAX_PROFIT_R"]):
            cls._blocked_reason = "daily_max_profit_r"
            cls._persist()
            return False, cls._blocked_reason
        return True, "ok"

    @classmethod
    def register_trade(cls):
        cls._reset_if_new_day()
        cls._trades += 1
        cls._persist()

    @classmethod
    def add_realized_r(cls, r: float):
        cls._reset_if_new_day()
        x = float(r)
        cls._realized_r += x
        # V702 R5 — progressive portfolio throttle on consecutive realized losses.
        # A non-loss outcome clears the streak; a loss adds one strike. We keep the
        # daily max-loss breaker unchanged as the hard backstop.
        if bool(CONFIG.get("V702_LOSS_STREAK_COOLDOWN_ENABLE", True)):
            if x < 0.0:
                cls._consecutive_losses = int(cls._consecutive_losses) + 1
                if cls._consecutive_losses == 1:
                    cd = max(0.0, float(CONFIG.get("V702_LOSS_STREAK_FIRST_LOSS_COOLDOWN_SEC", 180.0)))
                elif cls._consecutive_losses >= int(CONFIG.get("MAX_CONSECUTIVE_LOSSES", 2)):
                    cd = max(0.0, float(CONFIG.get("V702_LOSS_STREAK_HARD_COOLDOWN_SEC", 900.0)))
                else:
                    cd = max(0.0, float(CONFIG.get("V702_LOSS_STREAK_FIRST_LOSS_COOLDOWN_SEC", 180.0)))
                if cd > 0.0:
                    cls._loss_streak_block_until = float(WALL_NOW()) + cd
                _loss_log = logger.info if _v702_selftest_log_context_active() else logger.warning
                _loss_log(
                    f"[DailyCB-R5] realized loss {x:+.3f}R; streak={cls._consecutive_losses} "
                    f"cooldown={cd:.0f}s"
                )
            else:
                if cls._consecutive_losses or cls._loss_streak_block_until:
                    logger.info(
                        f"[DailyCB-R5] loss streak reset by realized outcome {x:+.3f}R"
                    )
                cls._consecutive_losses = 0
                cls._loss_streak_block_until = 0.0
        cls._persist()


# =============================================================================
#  V702 FINAL — RETIRED EQUITY DRAWDOWN HALT (COMPATIBILITY SHIM)
#  The historical EquityDrawdownHalt API is retained so external integrations
#  and old telemetry parsers do not break. It has NO authority over entries.
#  Portfolio drawdown may be observed externally, but it cannot trip an entry
#  latch, change the starvation root, or block SignalBuilder/ExecutionFunnel.
# =============================================================================
class EquityDrawdownHalt:
    _peak_equity_usdt: Optional[float] = None
    _last_equity_usdt: Optional[float] = None
    _halted: bool = False
    _halt_reason: str = ""
    _halt_since: float = 0.0

    @classmethod
    def _current_equity_usdt(cls) -> Optional[float]:
        # Retained for source/API compatibility only. No runtime DD authority.
        return None

    @classmethod
    def observe(cls) -> None:
        # V702 FINAL: intentionally inert. Never creates an entry-block latch.
        cls._halted = False
        cls._halt_reason = ""
        cls._halt_since = 0.0

    @classmethod
    def blocks_new_entries(cls) -> bool:
        # Hard invariant: retired feature can never block a new entry.
        return False

    @classmethod
    def reason(cls) -> str:
        return "disabled"

    @classmethod
    def reset_explicit(cls, reason: str) -> None:
        # Compatibility no-op. Keep argument validation for callers that relied
        # on the historical API contract, but never re-base or alter execution.
        if not str(reason or "").strip():
            raise ValueError("explicit reset reason required")
        cls._halted = False
        cls._halt_reason = ""
        cls._halt_since = 0.0
        logger.info(f"[EquityDD] retired compatibility reset ignored: {reason}")

    @classmethod
    def snapshot(cls) -> Dict[str, Any]:
        return {
            "enabled": False,
            "peak_equity_usdt": None,
            "last_equity_usdt": None,
            "halted": False,
            "reason": "disabled",
            "since": 0.0,
        }


class FailedSendCircuitBreaker:
    _fail_counts: Dict[str, int] = defaultdict(int)
    _open_until: Dict[str, float] = {}
    THRESHOLD = int(CONFIG.get("FAILED_SEND_CB_THRESHOLD", 3))
    OPEN_SEC = int(CONFIG.get("FAILED_SEND_CB_OPEN_SEC", 600))

    @classmethod
    def record_failure(cls, symbol: str):
        cls._fail_counts[symbol] += 1
        if cls._fail_counts[symbol] >= cls.THRESHOLD:
            cls._open_until[symbol] = MONO_NOW() + cls.OPEN_SEC
            logger.warning(f"[FailedSendCB] TRIPPED {symbol} for {cls.OPEN_SEC}s")

    @classmethod
    def is_open(cls, symbol: str) -> bool:
        until = cls._open_until.get(symbol, 0)
        return MONO_NOW() < until

    @classmethod
    def clear(cls, symbol: str):
        cls._fail_counts[symbol] = 0
        cls._open_until.pop(symbol, None)

# =============================================================================
#  SECTION 24 — ADAPTIVE ENTRY REPRICING (AE-1)
# =============================================================================

class AdaptiveRepricing:

    @staticmethod
    def maybe_reprice(planned_entry: float, live_price: float, atr: float
                      ) -> Tuple[bool, float, float, float, str]:
        """
        Returns (reprice_ok, new_entry, new_sl, new_tp1, reason)
        Never widens beyond configured drift ceiling.

        v4.0.6 FIX A — TP1 recompute now uses the CANONICAL TP1_RR to keep
        repricing consistent with the rest of the TP1 policy
        (fee_viability_ok, gate, exit weights). `ADAPTIVE_REPRICE_MIN_TP1_RR`
        is retained only as a soft alias for backwards compatibility: if
        present in config we still honor its value but default it to TP1_RR
        when absent — preventing any future drift between the two paths.
        drift_pct handling is unchanged: negative drift still returns
        "price_below_planned" (not repriced), per original semantics.
        """
        if not bool(CONFIG["ADAPTIVE_REPRICE_ENABLED"]):
            return False, planned_entry, 0.0, 0.0, "disabled"
        drift_pct = (live_price - planned_entry) / max(planned_entry, 1e-9) * 100.0
        max_drift = float(CONFIG["ADAPTIVE_REPRICE_MAX_DRIFT_PCT"])
        atr_drift = float(CONFIG["ADAPTIVE_REPRICE_ATR_MULT"]) * atr
        if drift_pct > max_drift and (live_price - planned_entry) > atr_drift:
            return False, planned_entry, 0.0, 0.0, "drift_exceeded"
        if drift_pct < 0:
            return False, planned_entry, 0.0, 0.0, "price_below_planned"
        # Recompute
        new_entry = live_price
        new_sl = new_entry - float(CONFIG["ADAPTIVE_REPRICE_SL_ATR_MULT"]) * atr
        # v4.0.6 FIX A — canonical TP1_RR (alias fallback only). If the alias
        # was left at a legacy value inconsistent with TP1_RR, bias to the
        # canonical policy to avoid TP1-desync between repricing and
        # fee_viability_ok / gate sizing.
        tp1_rr_canonical = float(CONFIG["TP1_RR"])
        tp1_rr = float(CONFIG.get("ADAPTIVE_REPRICE_MIN_TP1_RR", tp1_rr_canonical))
        if abs(tp1_rr - tp1_rr_canonical) > 1e-9:
            tp1_rr = tp1_rr_canonical
        new_tp1 = new_entry + tp1_rr * (new_entry - new_sl)
        return True, new_entry, new_sl, new_tp1, "repriced"


# =============================================================================
#  SECTION 25 — CANDLE DEDUP + HANDOFF OWNERSHIP
# =============================================================================

class CandleDedup:
    _seen: "OrderedDict[str, float]" = OrderedDict()
    _max = 500

    @classmethod
    def key(cls, symbol: str, timeframe: str, candle_ts: int) -> str:
        return f"{symbol}|{timeframe}|{candle_ts}"

    @classmethod
    def seen_recently(cls, k: str, ttl: int) -> bool:
        now = MONO_NOW()
        # evict expired
        while cls._seen and (now - next(iter(cls._seen.values()))) > ttl:
            cls._seen.popitem(last=False)
        return k in cls._seen

    @classmethod
    def mark(cls, k: str):
        cls._seen[k] = MONO_NOW()
        while len(cls._seen) > cls._max:
            cls._seen.popitem(last=False)


class HandoffOwnership:
    _locks: Dict[str, asyncio.Lock] = {}

    @classmethod
    def lock_for(cls, symbol: str) -> asyncio.Lock:
        # setdefault keeps the unified-symbol lock creation atomic enough for
        # the single-process asyncio runtime used by this bot.
        return cls._locks.setdefault(symbol, asyncio.Lock())


