class V410Telemetry:
    """Bounded diagnostics; no telemetry path may decide an entry."""
    _repeat: Dict[str, Dict[str, Any]] = {}

    @classmethod
    def inc(cls, key: str, n: int = 1) -> None:
        try: STATS[key] = int(STATS.get(key, 0)) + n
        except Exception: pass

    @classmethod
    def reject(cls, trace_id: str, symbol: str, category: str, reason: str, stage: str, ctx: Optional[Dict[str, Any]]=None) -> None:
        cls.inc("v410_reject_" + category)
        try: record_rejection(trace_id, symbol, category, reason, stage, ctx=ctx or {})
        except Exception: pass

    @classmethod
    def note_divergence(cls, symbol: str, legacy: bool, canonical: bool, context: str) -> None:
        if legacy != canonical:
            cls.inc("decision_divergence")
            try: logger.info("[V410.divergence] %s %s legacy=%s canonical=%s", symbol, context, legacy, canonical)
            except Exception: pass

class FamilyPolicyLayer:
    @staticmethod
    def get_family_policy(family: str) -> Dict[str, Any]:
        # Extracted policy owner helper is pure: config lookup only, no runtime
        # mutation, order authority, or regime broadening.
        return family_policy_from_config(CONFIG, family)

    @staticmethod
    def regime_policy_detail(family: str, regime: str,
                             strategy_mode: str = "",
                             local_regime: str = "",
                             market_phase: str = "",
                             severity: str = "",
                             strategy_style: str = "") -> Tuple[bool, str, Dict[str, Any]]:
        if not CONFIG.get("V410_FAMILY_POLICY_ENABLE", True):
            return True, "disabled", {}
        fam = str(family or "").upper()
        r = str(regime or "").upper()
        sm = str(strategy_mode or "").upper()
        lr = str(local_regime or "").upper()
        ph = str(market_phase or "").upper()
        sev = str(severity or "").upper()
        sty = str(strategy_style or "").upper()
        # R36: missing macro context is not NEUTRAL and cannot enter any neutral
        # recovery/bridge path. Make the policy rejection explicit and fail-closed.
        if r in {"", "UNKNOWN", "NONE", "UNAVAILABLE", "DATA_MISSING", "N/A", "NA"}:
            return False, "macro_context_unavailable", {
                "family": fam, "regime": r, "reason": "macro_context_unavailable",
                "policy_context": "FAIL_CLOSED", "local_regime": lr,
                "severity": sev, "snapshot_context_required": True,
            }
        # V702 canonical context vocabulary closure: NON_BEARISH is a historical
        # presentation alias for LOCAL_BULLISH outside an explicitly bearish
        # macro regime. Apply the already-defined V669 semantic aliases at the
        # actual policy boundary, where strategy arbitration really happens.
        # This changes representation only; bearish/crash semantics remain strict.
        _raw_lr, _raw_sev = lr, sev
        try:
            lr = _v669_canon_local(lr, r)
            sev = _v669_canon_severity(sev, r)
        except Exception:
            pass
        if lr != _raw_lr:
            STATS["v702_policy_context_local_alias_non_bearish"] = int(
                STATS.get("v702_policy_context_local_alias_non_bearish", 0) or 0
            ) + 1
        if sev != _raw_sev:
            STATS["v702_policy_context_severity_alias"] = int(
                STATS.get("v702_policy_context_severity_alias", 0) or 0
            ) + 1
        # v4.5.10-FIX: there are two historical policy registries in this
        # file. Strategy-aware candidates must use the explicit V43_STRATEGY_META
        # registry when available; legacy family policy remains the fallback for
        # older families. This removes policy-authority drift without weakening
        # any downstream HTF/tier/score/structure gate.
        strategy_meta = {}
        if bool(CONFIG.get("V455_PREQUAL_POLICY_CANONICAL_META_ENABLE", True)):
            try:
                # v4.5.11: V43_STRATEGY_POLICY_META is the single authoritative
                # runtime registry. CONFIG["V43_STRATEGY_META"] is only a
                # synchronized compatibility mirror populated by the policy
                # consistency layer below. No runtime decision reads the mirror.
                _meta_root = CanonicalStrategyPolicyRegistry.data()
                if isinstance(_meta_root, dict):
                    _candidate_meta = _meta_root.get(sm)
                    if isinstance(_candidate_meta, dict):
                        strategy_meta = dict(_candidate_meta)
                    elif fam != sm and isinstance(_meta_root.get(fam), dict):
                        strategy_meta = dict(_meta_root.get(fam))
            except Exception:
                strategy_meta = {}

        policies = {
            "LOCAL_STRENGTH_BREAKOUT": (
                {"BULLISH","NEUTRAL","BEARISH"}, {"LOCAL_BULLISH"},
                {"BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""},
                {"TREND","EXPANSION","BREAKOUT","PULLBACK","UNKNOWN"}, {"SCALP"}),
            "COMPRESSION_EXPANSION": (
                {"BULLISH","NEUTRAL","BEARISH"}, {"LOCAL_BULLISH","LOCAL_RECOVERY","LOCAL_NEUTRAL"},
                {"BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""},
                {"COMPRESSION","EXPANSION","BREAKOUT","UNKNOWN"}, {"SCALP"}),
            "CONTINUATION_RECLAIM": (
                {"BULLISH","NEUTRAL","BEARISH"}, {"LOCAL_BULLISH","LOCAL_RECOVERY"},
                {"BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""},
                {"TREND","PULLBACK","EXPANSION","BREAKOUT","UNKNOWN"}, {"SCALP"}),
            "FAILED_BREAKOUT_RECLAIM": (
                {"BULLISH","NEUTRAL","BEARISH"}, {"LOCAL_BULLISH","LOCAL_RECOVERY"},
                {"BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""},
                {"BREAKOUT","EXPANSION","REVERSAL","UNKNOWN"}, {"SCALP"}),
            "SWING_PULLBACK": (
                {"BULLISH","NEUTRAL"}, {"LOCAL_BULLISH","LOCAL_RECOVERY","LOCAL_NEUTRAL"},
                {"NORMAL","STRESSED","BEARISH_NORMAL","BEARISH_STRESSED",""},
                {"PULLBACK","TREND","EXPANSION","UNKNOWN"}, {"SWING"}),
            "EXTREME_FLUSH_REVERSAL": (
                {"BULLISH","NEUTRAL","BEARISH"}, {"LOCAL_RECOVERY","LOCAL_BULLISH","LOCAL_NEUTRAL"},
                {"BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""},
                {"REVERSAL","EXPANSION","BREAKOUT","UNKNOWN"}, {"SCALP"}),
        }
        ctx = {
            "family": fam, "strategy_mode": sm, "regime": r, "local_regime": lr,
            "market_phase": ph, "severity": sev, "strategy_style": sty,
            "allowed_regimes": (), "allowed_local_regimes": (),
            "allowed_severity": (), "allowed_phases": (), "allowed_styles": (),
            "policy_source": "legacy_family_policy",
        }

        # Canonical strategy-mode registry takes precedence when present.
        if strategy_meta:
            regimes = set(str(x).upper() for x in strategy_meta.get("allowed_regimes", ()))
            locals_ok = set(str(x).upper() for x in strategy_meta.get("allowed_local_regimes", ()))
            sevs = set(str(x).upper() for x in strategy_meta.get("allowed_severity", ()))
            phases = set(str(x).upper() for x in strategy_meta.get("allowed_phases", ()))
            styles = set(str(x).upper() for x in strategy_meta.get("allowed_styles", ()))
            ctx.update({
                "allowed_regimes": tuple(sorted(regimes)),
                "allowed_local_regimes": tuple(sorted(locals_ok)),
                "allowed_severity": tuple(sorted(sevs)),
                "allowed_phases": tuple(sorted(phases)),
                "allowed_styles": tuple(sorted(styles)),
                "policy_source": "V43_STRATEGY_META",
            })
            if bool(strategy_meta.get("enabled", True)) is False:
                return False, "disabled", ctx
            if r == "BEARISH" and sev in {"BEARISH_CRASH","CRASH"}:
                return False, "severity", ctx
            if regimes and r not in regimes:
                return False, "macro", ctx
            # Dedicated recovery routes must carry their positive local and
            # severity evidence all the way into canonical Prequal.  Empty
            # context is not an implicit pass for these explicitly marked modes.
            if bool(strategy_meta.get("require_local_regime", False)) and not lr:
                ctx["required_local_regime_missing"] = True
                return False, "local", ctx
            if locals_ok and lr and lr not in locals_ok:
                return False, "local", ctx
            if bool(strategy_meta.get("require_severity", False)) and not sev:
                ctx["required_severity_missing"] = True
                return False, "severity", ctx
            if sevs and sev and sev not in sevs:
                return False, "severity", ctx
            if phases and ph and ph not in phases:
                return False, "phase", ctx
            if styles and sty and sty not in styles:
                return False, "style", ctx
            # A10: mean-reversion is valid in BULLISH/NEUTRAL only with a known
            # local setup state. In BEARISH macro, LONG_ONLY entries require a
            # positively classified LOCAL_RECOVERY; this is not an HTF bypass.
            if (fam == "MEAN_REVERSION" or sm == "MEAN_REVERSION") and not bool(globals().get("_V702_A9_BUILDING_REGIME_MATRIX", False)):
                if r == "BEARISH" and lr != "LOCAL_RECOVERY":
                    ctx.update({"v702_mr_bearish_local_recovery_required": True,
                                "observed_local_regime": lr})
                    return False, "local", ctx
                if r in {"BULLISH", "NEUTRAL"} and lr not in {"LOCAL_RECOVERY", "LOCAL_BULLISH", "LOCAL_NEUTRAL"}:
                    ctx.update({"v702_mr_local_confirmation_required": True,
                                "observed_local_regime": lr})
                    return False, "local", ctx
            return True, "allow", ctx

        if sm in policies:
            regimes, locals_ok, sevs, phases, styles = policies[sm]
            ctx.update({
                "allowed_regimes": tuple(sorted(regimes)),
                "allowed_local_regimes": tuple(sorted(locals_ok)),
                "allowed_severity": tuple(sorted(sevs)),
                "allowed_phases": tuple(sorted(phases)),
                "allowed_styles": tuple(sorted(styles)),
            })
            if r == "BEARISH" and sev in {"BEARISH_CRASH","CRASH"}:
                return False, "severity", ctx
            if r not in regimes:
                return False, "macro", ctx
            if lr and lr not in locals_ok:
                return False, "local", ctx
            if sev and sev not in sevs:
                return False, "severity", ctx
            if ph and ph not in phases:
                return False, "phase", ctx
            if sty and sty not in styles:
                return False, "style", ctx
            if sm == "LOCAL_STRENGTH_BREAKOUT" and r == "BEARISH" and lr != "LOCAL_BULLISH":
                return False, "local", ctx
            return True, "allow", ctx
        allowed = tuple(str(x).upper() for x in FamilyPolicyLayer.get_family_policy(fam).get(
            "allowed_regimes", ("NEUTRAL",)))
        ctx["allowed_regimes"] = allowed
        if r not in set(allowed):
            return False, "macro", ctx
        return True, "allow", ctx

    @classmethod
    def bounded_neutral_recovery_allowed(cls, family: str, regime: str,
                                         strategy_mode: str = "",
                                         local_regime: str = "",
                                         market_phase: str = "",
                                         severity: str = "",
                                         strategy_style: str = "",
                                         candidate_features: Optional[Dict[str, Any]] = None,
                                         snapshot: Optional[Dict[str, Any]] = None,
                                         htf_strength: Optional[float] = None) -> Tuple[bool, str, Dict[str, Any]]:
        """Bounded NEUTRAL+LOCAL_BULLISH policy recovery inside the canonical policy layer."""
        fam = str(family or "").upper()
        sm = str(strategy_mode or fam).upper()
        r = str(regime or "").upper()
        lr = str(local_regime or "").upper()
        sev = str(severity or "").upper()
        sty = str(strategy_style or "SCALP").upper()
        feat = dict(candidate_features or {})
        snap = dict(snapshot or {})
        ctx = {
            "family": fam, "mode": sm, "regime": r, "local_regime": lr,
            "severity": sev, "phase": str(market_phase or "").upper(),
            "style": sty, "htf_strength": htf_strength,
        }
        allow_families = set(str(x).upper() for x in CONFIG.get("V457_POLICY_RECOVERY_FAMILIES", ()))
        if not bool(CONFIG.get("V457_POLICY_RECOVERY_ENABLE", True)):
            return False, "disabled", ctx
        try:
            if not bool(_v457_policy_recovery_active()):
                return False, "recovery_inactive", ctx
        except Exception:
            return False, "recovery_inactive", ctx
        if r != "NEUTRAL" or lr != "LOCAL_BULLISH" or sev not in {"NORMAL", ""}:
            return False, "context_not_eligible", ctx
        if fam not in allow_families and sm not in allow_families:
            return False, "family_not_allowlisted", ctx
        if not bool(feat.get("hard_valid", True)):
            return False, "hard_invalid", ctx

        try:
            if htf_strength is None or not math.isfinite(float(htf_strength)):
                return False, "htf_unavailable", ctx
            tier = str(snap.get("tier") or "")
            if not tier or not LiquidityTier.is_tradeable(tier):
                return False, "tier_invalid", ctx
            sp = snap.get("spread_pct", feat.get("spread_pct"))
            if sp is None or not math.isfinite(float(sp)):
                return False, "spread_unavailable", ctx
            ok_sp, why_sp = tier_spread_hard_ok_v410(float(sp), tier)
            if not ok_sp:
                return False, why_sp, ctx
        except Exception:
            return False, "hard_data_error", ctx

        d5 = snap.get("df_5m")
        bullish_close = higher_low = ema20_slope_up = False
        try:
            if d5 is not None and len(d5) >= 8:
                c, p1, p2 = d5.iloc[-2], d5.iloc[-3], d5.iloc[-4]
                bullish_close = float(c.close) > float(c.open) and float(c.close) >= float(p1.close)
                higher_low = float(c.low) > float(p1.low) > float(p2.low)
                e20 = Indicators.ema(d5["close"], CONFIG["EMA_FAST"])
                ema20_slope_up = len(e20) >= 7 and float(e20.iloc[-2]) > float(e20.iloc[-7])
        except Exception:
            _v647_record_suppressed_exception()
        volume_ratio = feat.get("volume_ratio")
        if volume_ratio is None:
            try:
                volume_ratio = float(d5["volume"].iloc[-2]) / max(float(d5["volume"].iloc[-12:-2].mean()), 1e-12)
            except Exception:
                volume_ratio = None
        if volume_ratio is None or not math.isfinite(float(volume_ratio)):
            return False, "volume_unavailable", ctx
        ctx.update({
            "volume_ratio": float(volume_ratio),
            "bullish_close": bullish_close,
            "higher_low": higher_low,
            "ema20_slope_up": ema20_slope_up,
        })

        if fam in {"PULLBACK", "MTF_PULLBACK"}:
            if not (bullish_close or higher_low or ema20_slope_up):
                return False, "micro_confirmation_missing", ctx
            dist = feat.get("dist_atr")
            if dist is not None and float(dist) > float(CONFIG.get("PULLBACK_MAX_DISTANCE_ATR", 2.4)) * 1.5:
                return False, "pullback_too_far", ctx
        elif fam == "LOCAL_STRENGTH_BREAKOUT":
            if float(feat.get("rs_5m", -999.0)) < float(CONFIG.get("LOCAL_STRENGTH_MIN_RS", 0.003)):
                return False, "rs_5m_below_min", ctx
            if float(feat.get("rs_15m", -999.0)) < float(CONFIG.get("LOCAL_STRENGTH_MIN_RS_15M", 0.003)):
                return False, "rs_15m_below_min", ctx
            if float(feat.get("rs_persistence", 0.0)) < float(CONFIG.get("LOCAL_STRENGTH_MIN_RS_PERSISTENCE", 0.5)):
                return False, "rs_persistence_below_min", ctx
            if float(volume_ratio) < float(CONFIG.get("LOCAL_STRENGTH_MIN_VOLUME_RATIO", 1.2)):
                return False, "volume_below_min", ctx
            if float(feat.get("chase_atr", 999.0)) > float(CONFIG.get("LOCAL_STRENGTH_MAX_CHASE_ATR", 1.5)):
                return False, "chase_excessive", ctx
        elif fam == "COMPRESSION_EXPANSION":
            if float(feat.get("atr_percentile", 1.0)) > float(CONFIG.get("COMPRESSION_MAX_ATR_PERCENTILE", 0.35)):
                return False, "compression_missing", ctx
            if float(feat.get("range_ratio", 999.0)) > float(CONFIG.get("COMPRESSION_MAX_RANGE_RATIO", 6.0)):
                return False, "compression_range_too_wide", ctx
            if float(volume_ratio) < float(CONFIG.get("EXPANSION_MIN_VOLUME_RATIO", 1.3)):
                return False, "expansion_volume_below_min", ctx
            if float(feat.get("target_rr", 0.0)) < float(CONFIG.get("EXPANSION_MIN_RR", 2.0)):
                return False, "expansion_target_rr_below_min", ctx
            if float(feat.get("chase_atr", 999.0)) > float(CONFIG.get("EXPANSION_MAX_CHASE_ATR", 1.6)):
                return False, "expansion_chase_excessive", ctx
        elif fam == "CONTINUATION_RECLAIM":
            if not feat.get("trend_alignment") or not feat.get("reclaim"):
                return False, "continuation_structure_missing", ctx
            if float(volume_ratio) < float(CONFIG.get("CONTINUATION_RECLAIM_MIN_VOLUME_RATIO", 0.95)):
                return False, "continuation_volume_below_min", ctx
            if float(feat.get("rs_5m", -999.0)) < float(CONFIG.get("CONTINUATION_RECLAIM_MIN_RS", 0.0)):
                return False, "continuation_rs_below_min", ctx
            if float(feat.get("chase_atr", 999.0)) > float(CONFIG.get("CONTINUATION_RECLAIM_MAX_CHASE_ATR", 1.25)):
                return False, "continuation_chase_excessive", ctx
        elif fam == "TREND_CONTINUATION":
            if not (bullish_close and ema20_slope_up):
                return False, "trend_continuation_confirmation_missing", ctx
            if float(volume_ratio) < float(CONFIG.get("TREND_CONT_MIN_VOL_RATIO", 0.80)):
                return False, "trend_continuation_volume_below_min", ctx
        else:
            return False, "family_not_supported", ctx
        return True, "recovered", ctx

    @staticmethod
    def strategy_allowed(strategy_mode: str, regime: str, local_regime: str = "",
                         market_phase: str = "", severity: str = "",
                         strategy_style: str = "") -> bool:
        ok, _reason, _ctx = FamilyPolicyLayer.regime_policy_detail(
            strategy_mode, regime, strategy_mode=strategy_mode,
            local_regime=local_regime, market_phase=market_phase,
            severity=severity, strategy_style=strategy_style)
        return bool(ok)

    @staticmethod
    def htf_min_strength(family: str) -> float:
        return float(FamilyPolicyLayer.get_family_policy(family).get("min_htf_strength", 60.0))

    @staticmethod
    def min_score(base: float, family: str) -> float:
        return max(0.0, float(base) + float(FamilyPolicyLayer.get_family_policy(family).get("min_score_offset", 0.0)))

    @staticmethod
    def liquidity_acceptable(family: str, tier: str) -> bool:
        policy = FamilyPolicyLayer.get_family_policy(family)
        return _FAMILY_RANK.get(str(tier), -1) >= _FAMILY_RANK.get(str(policy.get("min_tier", "MID")), 2)

    @staticmethod
    def tp1_distance_ok(entry: float, tp1: float, atr: float, family: str) -> bool:
        floor = float(FamilyPolicyLayer.get_family_policy(family).get("tp1_atr_floor", 0.7))
        return atr > 0 and ((tp1 - entry) / atr) >= floor

    # v4.2.2 - per-family preferred anchor zones (advisory only).
    @staticmethod
    def preferred_zones(family: str):
        try:
            z = FamilyPolicyLayer.get_family_policy(family).get("preferred_zones", ())
            return tuple(str(x).upper() for x in z) if z else tuple()
        except Exception:
            return tuple()

    @staticmethod
    def zone_preferred(family: str, anchor: str) -> bool:
        """v4.2.2 - True when candidate anchor is in the family preferred
        zone list. Advisory: a mismatch is a bounded soft penalty, NEVER a
        reject. Unknown anchor => True (no penalty for unclassified anchors)."""
        try:
            prefs = FamilyPolicyLayer.preferred_zones(family)
            if not prefs:
                return True
            a = str(anchor or "").upper()
            if not a:
                return True
            return any(a.startswith(p) or p in a for p in prefs)
        except Exception:
            return True

    @staticmethod
    def volume_floor_ratio(family: str) -> float:
        try:
            return float(FamilyPolicyLayer.get_family_policy(family).get("volume_floor_ratio", 1.0))
        except Exception:
            return 1.0

    @staticmethod
    def volume_floor_ok(family: str, volume_ratio) -> bool:
        """v4.2.2 - advisory volume floor. Missing ratio => True."""
        try:
            if volume_ratio is None:
                return True
            return float(volume_ratio) >= FamilyPolicyLayer.volume_floor_ratio(family)
        except Exception:
            return True

    @staticmethod
    def fake_break_allowed(df, family: str, original_ok: bool) -> bool:
        if original_ok: return True
        # Only a tight reclaim exception for continuation families; ambiguity stays reject.
        if not CONFIG.get("V410_MICROSTRUCTURE_ENABLE", True) or str(family) not in {"PULLBACK", "MTF_PULLBACK", "TREND_CONTINUATION", "BREAKOUT_RETEST"}: return False
        try:
            c = df.iloc[-2]; p = df.iloc[-3]
            rng = max(float(c.high) - float(c.low), 1e-12)
            return float(c.close) > float(c.open) and float(c.close) >= float(p.close) and abs(float(c.close)-float(c.high))/rng <= 0.35
        except Exception: return False

    @staticmethod
    def tail_catcher(df_15m, df_5m) -> Optional[Dict[str, Any]]:
        if not CONFIG.get("FAMILY_TAIL_CATCHER_ENABLE", True) or df_15m is None or df_5m is None or len(df_15m) < 30 or len(df_5m) < 25: return None
        try:
            ema20 = Indicators.ema(df_15m["close"], 20)
            ema50 = Indicators.ema(df_15m["close"], 50)
            atr = Indicators.atr(df_5m, int(CONFIG.get("ATR_PERIOD", 14)))
            close = float(df_5m.close.iloc[-2]); a = float(atr.iloc[-2])
            trend = float(ema20.iloc[-2]) > float(ema50.iloc[-2]) and float(df_15m.close.iloc[-2]) > float(ema20.iloc[-2])
            local_low = float(df_5m.low.iloc[-6:-1].min())
            clean_pb = a > 0 and (close-local_low) <= float(CONFIG["FAMILY_TAIL_CATCHER_MAX_PULLBACK_ATR"])*a and close > float(df_5m.open.iloc[-2])
            if trend and clean_pb: return {"family":"TREND_CONTINUATION", "zone_ref":float(ema20.iloc[-2]), "v410_tail":True}
        except Exception: pass
        return None

def detect_micro_bos_at_index(df, idx: int) -> Optional[MicroBOS]:
    try:
        if df is None or idx < 5 or idx >= len(df): return None
        c = df.iloc[idx]; prior = df.iloc[idx-5:idx]
        swing = float(prior.high.max()); low = float(prior.low.min()); close = float(c.close); op = float(c.open)
        rng = max(float(c.high)-float(c.low), 1e-12); body = abs(close-op)/rng
        volmean = max(float(prior.volume.mean()), 1e-12); vr = float(c.volume)/volmean
        min_break = float(CONFIG.get("MICRO_BOS_MIN_BREAK", 0.0006)); strong = float(CONFIG.get("BOS_STRONG_BREAK_PCT", 0.0022)); minbody = float(CONFIG.get("BOS_BODY_MIN_RATIO", 0.45))
        if close > swing*(1+min_break) and body >= minbody and vr >= 0.8:
            return MicroBOS("LONG", idx, swing, close, min(1.0,(close/swing-1)/max(strong,1e-12)), body, vr)
        return None
    except Exception: return None

def find_retest_zone_at_index(df, bos: Optional[MicroBOS], idx: int) -> Optional[RetestZone]:
    if bos is None: return None
    try:
        # Last bearish candle before the break is the order-block candidate.
        for j in range(idx-1, max(0, idx-10), -1):
            r = df.iloc[j]
            if float(r.close) < float(r.open):
                lo, hi = float(r.low), float(r.high)
                return RetestZone("ORDER_BLOCK", lo, hi, (lo+hi)/2, j, idx-j)
        ema = Indicators.ema(df.close, 20); mid = float(ema.iloc[idx])
        atr = Indicators.atr(df, int(CONFIG.get("ATR_PERIOD", 14))); width = max(float(atr.iloc[idx])*0.25, mid*0.0005)
        return RetestZone("EMA_FALLBACK", mid-width, mid+width, mid, idx, 0)
    except Exception: return None

def rejection_candle_confirm_v410(df, idx: int, zone: Optional[RetestZone]) -> bool:
    try:
        if zone is None or idx < 0: return False
        c = df.iloc[idx]; rng=max(float(c.high)-float(c.low),1e-12); body=abs(float(c.close)-float(c.open))/rng
        lower=(min(float(c.open),float(c.close))-float(c.low))/rng
        in_zone=float(c.low) <= zone.high and float(c.high) >= zone.low
        return in_zone and float(c.close)>float(c.open) and body >= float(CONFIG.get("REJECTION_BODY_MIN_RATIO",0.25)) and lower >= 0.25
    except Exception: return False

def detect_fair_value_gap_v410(df) -> Tuple[bool, float]:
    try:
        if df is None or len(df) < 4: return False, 0.0
        a,b,c = df.iloc[-4],df.iloc[-3],df.iloc[-2]
        gap=float(c.low)-float(a.high)
        return (gap > 0, max(0.0, gap/max(float(b.high)-float(b.low),1e-12)))
    except Exception: return False,0.0

def detect_rsi_divergence_v410(df) -> bool:
    try:
        if df is None or len(df)<25: return False
        rsi=Indicators.rsi(df.close,14)
        # bullish regular divergence on closed candles: lower price low, higher RSI low.
        p1=float(df.low.iloc[-12:-7].min()); p2=float(df.low.iloc[-7:-2].min())
        r1=float(rsi.iloc[-12:-7].min()); r2=float(rsi.iloc[-7:-2].min())
        return p2 < p1 and r2 > r1
    except Exception: return False

def detect_fibonacci_golden_pocket_v410(df, price: float) -> bool:
    try:
        if df is None or len(df)<25: return False
        hi=float(df.high.iloc[-22:-2].max()); lo=float(df.low.iloc[-22:-2].min()); span=hi-lo
        if span <= 0: return False
        return (lo+0.618*span) <= price <= (lo+0.705*span)
    except Exception: return False

def confluence_boost_v410(df, bos: bool, entry: float) -> Tuple[float, Dict[str, Any]]:
    if not CONFIG.get("V410_CONFLUENCE_ENABLE", True): return 0.0, {}
    fvg, gap = detect_fair_value_gap_v410(df); div=detect_rsi_divergence_v410(df); fib=detect_fibonacci_golden_pocket_v410(df,entry)
    raw=(float(CONFIG["CONFLUENCE_FVG_BOOST"]) if fvg else 0)+(float(CONFIG["CONFLUENCE_RSI_DIV_BOOST"]) if div else 0)+(float(CONFIG["CONFLUENCE_FIB_BOOST"]) if fib else 0)+(float(CONFIG["CONFLUENCE_MICRO_BOS_BOOST"]) if bos else 0)
    return min(raw,float(CONFIG["CONFLUENCE_MAX_BOOST"])), {"fvg":fvg,"fvg_gap":gap,"rsi_div":div,"fib":fib,"raw":raw}

def d1_bias_score_v410(df_1d) -> Tuple[float, str]:
    """Return bounded daily-bias adjustment: (-penalty, label), 0 neutral.
    Uses only CLOSED daily candles and never creates a signal by itself.
    """
    try:
        if not CONFIG.get("V410_D1_BIAS_ENABLE", True):
            return 0.0, "disabled"
        if df_1d is None or len(df_1d) < int(CONFIG.get("V410_D1_MIN_CANDLES", 80)):
            return 0.0, "missing"
        ema20 = Indicators.ema(df_1d["close"], 20)
        ema50 = Indicators.ema(df_1d["close"], 50)
        i = -2
        close = float(df_1d["close"].iloc[i])
        e20 = float(ema20.iloc[i]); e50 = float(ema50.iloc[i])
        if close > e20 > e50:
            return float(CONFIG.get("D1_BIAS_POSITIVE_SCORE_BOOST", 1.0)), "bullish"
        if close < e20 < e50:
            return -float(CONFIG.get("D1_BIAS_NEGATIVE_SCORE_PENALTY", 3.0)), "bearish"
        return 0.0, "neutral"
    except Exception:
        return 0.0, "missing"

def breadth_adjustment_v410(market_data: Dict[str, Any]) -> Tuple[float, str]:
    """Use an externally computed breadth score when available.
    Missing breadth is neutral and never opens a gate."""
    try:
        if not CONFIG.get("V410_BREADTH_ENABLE", True):
            return 0.0, "disabled"
        raw = market_data.get("breadth_score")
        if raw is None:
            return 0.0, "missing"
        x = float(raw)
        if not math.isfinite(x):
            return 0.0, "missing"
        # -1..+1 normalized breadth -> bounded +/-2 score adjustment.
        return _clamp(x, -1.0, 1.0) * 2.0, ("bullish" if x > 0.15 else "bearish" if x < -0.15 else "neutral")
    except Exception:
        return 0.0, "missing"

def tier_spread_hard_ok_v410(spread_pct: Optional[float], tier: str) -> Tuple[bool, str]:
    """Tier-aware spread ceiling. BELOW is always hard rejected."""
    if str(tier).upper() == "BELOW":
        return False, "below_tier"
    if spread_pct is None or not math.isfinite(float(spread_pct)):
        return False, "spread_missing"
    if not CONFIG.get("V410_TIER_SPREAD_HARD_REJECT", True):
        return True, "disabled"
    ceiling = float(CONFIG.get("TIER_SPREAD_CEIL_PCT", {}).get(str(tier).upper(), CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15)))
    return float(spread_pct) <= ceiling, f"spread={float(spread_pct):.4f}%<=ceil={ceiling:.4f}%"

def htf_repeat_backoff_v410(symbol: str, failed: bool) -> None:
    """Bounded telemetry/backoff bookkeeping; never converts an HTF fail to allow."""
    if not failed:
        COOLDOWNS.get("htf_backoff", {}).pop(symbol, None)
        return
    now = MONO_NOW()
    cur = COOLDOWNS.setdefault("htf_backoff", {}).get(symbol)
    level = int(cur[0]) + 1 if isinstance(cur, tuple) else 1
    level = min(level, int(CONFIG.get("HTF_REPEAT_BACKOFF_MAX_LEVEL", 3)))
    base = float(CONFIG.get("HTF_REPEAT_REJECT_COOLDOWN_SEC", 45.0))
    cap = float(CONFIG.get("HTF_REPEAT_BACKOFF_MAX_SEC", 180.0))
    until = now + min(cap, base * (2 ** max(0, level - 1)))
    COOLDOWNS["htf_backoff"][symbol] = (level, until)
    STATS["htf_repeat_backoff_armed"] = STATS.get("htf_repeat_backoff_armed", 0) + 1

class ExecutionRescue:
    @staticmethod
    async def try_depth_rescue(exchange, symbol: str, sd: Any, cached_ob: Optional[Dict[str, Any]]=None) -> Tuple[bool, Any, str]:
        if not CONFIG.get("V410_EXECUTION_RESCUE_ENABLE", True) or sd is None: return False, sd, "disabled"
        try:
            ratio=float(CONFIG.get("SIZE_DOWN_RESCUE_RATIO",0.60)); old=float(sd.notional_after_caps); new=old*ratio
            minimum=float(CONFIG.get("MIN_POSITION_SIZE_USDT",15.0))
            if not (0 < ratio < 1 and new >= minimum): return False, sd, "below_min_position"
            ok,msg,_=await LiquidityDepth.check(exchange,symbol,new,cached_ob=cached_ob)
            if not ok: return False,sd,"depth_still_insufficient"
            sd.notional_after_caps=new; sd.quantity_asset=float(sd.quantity_asset)*ratio
            if hasattr(sd,"final_notional_after_caps"): sd.final_notional_after_caps=new
            V410Telemetry.inc("size_down_rescue_success")
            return True,sd,"size_down_rescue"
        except Exception as e:
            V410Telemetry.inc("size_down_rescue_error"); return False,sd,"rescue_error"

