def _v563_trade_protection_healthy(trade: Any) -> bool:
    """Return True only when the active trade has a valid native or software SL."""
    try:
        if trade is None:
            return False
        qty = float(getattr(trade, "remaining_position", 0.0) or 0.0)
        entry = float(getattr(trade, "entry", 0.0) or 0.0)
        sl = float(getattr(trade, "current_sl", 0.0) or getattr(trade, "original_sl", 0.0) or 0.0)
        # A live protective stop may legitimately be at/above entry after
        # breakeven or profit-lock. Geometry is checked separately at entry;
        # protection health must validate the active stop, not require a loss stop.
        if qty <= 0 or entry <= 0 or sl <= 0:
            return False
        native = bool(getattr(trade, "sl_order_id", None)) and str(
            getattr(trade, "sl_health_state", "") or ""
        ).upper() == "CONFIRMED"
        software = bool(getattr(trade, "software_sl_active", False)) and str(
            getattr(trade, "sl_health_state", "") or ""
        ).upper() in {"SOFTWARE_SL_ACTIVE", "SOFTWARE_SL_DEGRADED", "SOFTWARE_ALERT_ONLY"}
        if native:
            return True
        if software and bool(CONFIG.get("V563_PROTECTED_SOFTWARE_SL_COUNTS_AS_PROTECTED", True)):
            # A degraded/stale software monitor is not healthy enough to clear a hard block.
            if str(getattr(trade, "sl_health_state", "") or "").upper() == "SOFTWARE_SL_DEGRADED":
                try:
                    return SoftwareSLTelemetry.heartbeat_ok()
                except Exception:
                    return False
            return True
        return False
    except Exception:
        return False


def _v563_stopless_block_resolved_for_entry() -> bool:
    """Resolve only the old stopless-exposure block when that exact live exposure is now protected."""
    try:
        if not bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
            return True
        reason = str(LIVE_ENTRIES_BLOCKED.get("reason") or "").lower()
        if not bool(CONFIG.get("V563_SOFT_STOPLESS_BLOCK_IGNORE_WHEN_PROTECTED", True)):
            return False
        if "stopless_exposure_" not in reason:
            return False
        for symbol, trade in list(ACTIVE_TRADES.items()):
            if str(symbol).lower() in reason and _v563_trade_protection_healthy(trade):
                return True
        return False
    except Exception:
        return False


def _v563_entry_block_applies(symbol: str) -> bool:
    try:
        if not bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
            return False
        reason = str(LIVE_ENTRIES_BLOCKED.get("reason") or "").lower()
        if _v563_stopless_block_resolved_for_entry() and "stopless_exposure_" in reason:
            return False
        return True
    except Exception:
        return True


def _v563_clear_resolved_protection_block() -> bool:
    """Clear only a stopless exposure block whose exact trade is currently protected."""
    try:
        if not bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
            return False
        reason = str(LIVE_ENTRIES_BLOCKED.get("reason") or "")
        low = reason.lower()
        if "stopless_exposure_" not in low:
            return False
        symbol = reason.split("stopless_exposure_", 1)[1]
        # normalize only enough to match the exact ACTIVE_TRADES key
        symbol = symbol.strip()
        trade = None
        for sym, tr in ACTIVE_TRADES.items():
            if str(sym).lower() == symbol.lower():
                trade = tr
                symbol = sym
                break
        if trade is None or not _v563_trade_protection_healthy(trade):
            return False
        LIVE_ENTRIES_BLOCKED["active"] = False
        LIVE_ENTRIES_BLOCKED["reason"] = None
        LIVE_ENTRIES_BLOCKED["where"] = None
        LIVE_ENTRIES_BLOCKED["since"] = None
        STATS["v563_stopless_block_cleared_by_software_protection"] = int(
            STATS.get("v563_stopless_block_cleared_by_software_protection", 0) or 0
        ) + 1
        logger.warning(
            f"[V563-ENTRIES] cleared stale stopless-exposure block for {symbol}: "
            "software/native SL protection is now positively active"
        )
        return True
    except Exception as exc:
        logger.debug(f"[V563-ENTRIES] protection-block clear suppressed: {exc}")
        return False


