def _v702_position_manager_health_ok() -> bool:
    """Fail closed unless production stop capability is certified and local-SL health is sound.

    The production capability gate must have completed successfully and must
    expose one of the exact stop modes understood by OrderExecutor. Unknown or
    absent capability state is never interpreted as native-stop support.
    In software-SL mode the dedicated task must also have completed at least
    one successful cycle, keep a fresh health lease, and protect every open trade.
    """
    stats = globals().get("STATS", {})
    try:
        if not bool(CONFIG.get("POSITION_MANAGER_TASK_ENABLE", True)):
            stats["v702_pm_health_last_reason"] = "position_manager_task_disabled"
            return False
        capability_gate = globals().get("ProductionCapabilityGate")
        if capability_gate is None or not callable(getattr(capability_gate, "stop_mode", None)):
            stats["v702_pm_health_last_reason"] = "production_capability_gate_missing"
            return False
        if getattr(capability_gate, "_checked", False) is not True:
            stats["v702_pm_health_last_reason"] = "production_capability_not_certified"
            return False
        try:
            stop_mode = capability_gate.stop_mode()
        except Exception:
            stats["v702_pm_health_last_reason"] = "production_stop_mode_unreadable"
            return False
        allowed_stop_modes = {
            "dedicated_stop_market",
            "create_order_stoploss_market",
            "create_order_trigger_market",
            "software_sl_only",
        }
        if stop_mode not in allowed_stop_modes:
            stats["v702_pm_health_last_reason"] = "production_stop_mode_unverified"
            return False
        # Native venue-stop support does not certify the local manager's
        # current health: it still owns exits, runner state, reconciliation and
        # any software fallback for already-open positions.
        if str(stats.get("v702_pm_task_state") or "").upper() != "RUNNING":
            stats["v702_pm_health_last_reason"] = "position_manager_not_running"
            return False
        try:
            healthy_ticks = stats.get("v702_pm_healthy_ticks", 0)
            if isinstance(healthy_ticks, bool) or int(healthy_ticks) < 1:
                stats["v702_pm_health_last_reason"] = "position_manager_no_successful_cycle"
                return False
        except Exception:
            stats["v702_pm_health_last_reason"] = "position_manager_healthy_ticks_invalid"
            return False
        stamp = float(stats.get("v702_pm_last_healthy_ts", 0.0) or 0.0)
        now = float(WALL_NOW())
        interval = max(0.20, float(CONFIG.get("POSITION_MANAGER_INTERVAL_SEC", 0.50) or 0.50))
        max_age = max(3.0, interval * 6.0)
        if not math.isfinite(stamp) or stamp <= 0 or not math.isfinite(now) or stamp > now + 1.0 or now - stamp > max_age:
            stats["v702_pm_health_last_reason"] = "position_manager_heartbeat_stale_or_invalid"
            return False
        for trade in list((globals().get("ACTIVE_TRADES") or {}).values()):
            remaining = float(getattr(trade, "remaining_position", 0.0) or 0.0)
            if remaining > 1e-12 and not _v563_trade_protection_healthy(trade):
                stats["v702_pm_health_last_reason"] = f"active_trade_protection_unhealthy:{str(getattr(trade, 'symbol', '?'))[:48]}"
                return False
        stats["v702_pm_health_last_reason"] = (
            "ok_native_stop_and_pm_healthy" if stop_mode != "software_sl_only"
            else "ok_software_sl_and_pm_healthy"
        )
        return True
    except Exception as exc:
        try:
            stats["v702_pm_health_last_reason"] = f"health_check_error:{type(exc).__name__}"
        except Exception:
            pass
        return False


def _v702_live_operator_armed() -> bool:
    """A55 two-key live arm plus runtime and (when needed) software-SL health."""
    try:
        return bool(
            str(os.environ.get("UNIFIED_LIVE_PILOT_ENABLE", "")).strip() == "1"
            and str(os.environ.get("UNIFIED_A55_LIVE_ARM", "")).strip() == "1"
            and not KillSwitch.is_active()
            and LiveStateMachine.is_live_runnable()
            and not bool((LIVE_ENTRIES_BLOCKED or {}).get("active"))
            and _v702_position_manager_health_ok()
        )
    except Exception:
        return False


def _v702_live_buy_possible(intent_context: Optional[Dict[str, Any]] = None) -> bool:
    """Final live-entry authorization; non-empty candidate context and same-recipe Edge are mandatory."""
    if not _v702_live_operator_armed():
        return False
    # Never grant a BUY from a context-free diagnostic or legacy caller.
    if not isinstance(intent_context, dict) or not intent_context:
        try:
            STATS["v702_a56_contextless_live_buy_blocks"] = int(STATS.get("v702_a56_contextless_live_buy_blocks", 0) or 0) + 1
        except Exception:
            pass
        return False
    try:
        edge_gate = globals().get("EdgeGate")
        if edge_gate is None or not callable(getattr(edge_gate, "live_permitted", None)):
            return False
        allowed, reason = edge_gate.live_permitted(intent_context)
        STATS["v702_a55_last_live_edge_verdict"] = {"allowed": bool(allowed), "reason": str(reason)[:180], "ts": float(WALL_NOW())}
        return bool(allowed)
    except Exception as exc:
        STATS["v702_a55_live_edge_gate_errors"] = int(STATS.get("v702_a55_live_edge_gate_errors", 0) or 0) + 1
        logger.error("[V702-A55-EDGE] final BUY EdgeGate failed closed: %s", type(exc).__name__)
        return False


class PreSendGate:

    @staticmethod
    async def evaluate(exchange, trace_id: str, symbol: str, entry: float,
                       sl: float, tp1: float, tp2: float,
                       tp3: Optional[float] = None,
                       cached_ob: Optional[Dict[str, Any]] = None,
                       strategy_mode: str = "", strategy_score: float = 0.0,
                       strategy_style: str = "SCALP", strategy_risk_factor: float = 1.0,
                       quality_grade: str = "", spread_pct: Optional[float] = None,
                       timeframe_profile: str = "", htf_strength: Optional[float] = None,
                       strategy_family: str = ""
                       ) -> Tuple[bool, str, Optional[SizingDecision]]:
        # v4.0.9 DS-6 — optional `cached_ob` forwarded to LiquidityDepth.check
        # so the scoring-path orderbook is reused. Backward-compatible:
        # callers that omit it keep the original fresh-fetch behaviour.

        # 0. Kill switch + Watchdog + Live state
        if KillSwitch.is_active():
            record_rejection(trace_id, symbol, "circuit_breaker", "kill_switch", "pre_send")
            return False, "kill_switch", None
        if _v702_env_is_explicitly_off("UNIFIED_LIVE_PILOT_ENABLE"):
            record_rejection(trace_id, symbol, "policy", "monitor_only_forced_off", "pre_send")
            return False, "monitor_only_forced_off", None
        if not LiveStateMachine.is_live_runnable():
            record_rejection(trace_id, symbol, "circuit_breaker", "live_not_runnable", "pre_send")
            return False, "live_not_runnable", None
        if not _v702_live_operator_armed():
            record_rejection(trace_id, symbol, "policy", "live_operator_two_key_arm_missing", "pre_send")
            return False, "live_operator_two_key_arm_missing", None
        _edge_context = {
            "family": str(strategy_family or strategy_mode or "UNKNOWN"),
            "strategy_mode": str(strategy_mode or "UNKNOWN"),
            "strategy_style": str(strategy_style or "UNKNOWN"),
            "timeframe_profile": str(timeframe_profile or "UNKNOWN"),
            "htf_strength": htf_strength,
        }
        _edge_gate = globals().get("EdgeGate")
        if _edge_gate is None or not callable(getattr(_edge_gate, "live_permitted", None)):
            record_rejection(trace_id, symbol, "policy", "edge_gate_unavailable", "pre_send")
            return False, "edge_gate_unavailable", None
        _edge_ok, _edge_reason = _edge_gate.live_permitted(_edge_context)
        if not _edge_ok:
            record_rejection(trace_id, symbol, "policy", f"edge_gate:{_edge_reason}", "pre_send")
            return False, f"edge_gate:{_edge_reason}", None
        # v4.0.6 FIX F — entry-only soft block (balance transiently unusable).
        # Existing positions continue to be managed by PositionManager; only
        # NEW entries are rejected here.
        if _v563_entry_block_applies(symbol):
            record_rejection(
                trace_id, symbol, "balance",
                f"entries_blocked:{LIVE_ENTRIES_BLOCKED.get('reason') or 'unspecified'}",
                "pre_send",
            )
            return False, "entries_blocked", None
        # V702 FINAL: retired portfolio drawdown is never a pre-send gate.
        if ExchangeWatchdog.is_tripped():
            record_rejection(trace_id, symbol, "exchange", "watchdog_tripped", "pre_send")
            return False, "watchdog_tripped", None
        if FailedSendCircuitBreaker.is_open(symbol):
            record_rejection(trace_id, symbol, "circuit_breaker", "failed_send_open", "pre_send")
            return False, "failed_send_open", None

        # 1. Risk coherence — v4.0.6 FIX #3: pass tp3 so the strict ordering
        # invariant (sl < entry < tp1 < tp2 < tp3) is enforced INSIDE the
        # canonical checker instead of being left outside the gate.
        rc_ok, rc_msg = RiskCoherence.check(entry, sl, tp1, tp2, tp3=tp3)
        if not rc_ok:
            record_rejection(trace_id, symbol, "sl" if "sl" in rc_msg else "structural",
                             rc_msg, "pre_send")
            return False, rc_msg, None

        # 2. Sizing decision
        sd = await SizingEngine.decide(exchange, symbol, entry, sl, tp1, tp2, tp3=tp3,
                                       strategy_mode=strategy_mode, strategy_score=strategy_score,
                                       strategy_style=strategy_style, strategy_risk_factor=strategy_risk_factor,
                                       quality_grade=quality_grade, spread_pct=spread_pct)
        if sd.status != "OK":
            record_rejection(trace_id, symbol, "sizing" if sd.reject_reason != "balance_block" else "balance",
                             sd.reject_reason, "pre_send")
            return False, f"sizing:{sd.reject_reason}", sd

        # R40: apply the cost-aware lower target ladder only when SizingEngine
        # proved that it still passes the same net-cost economics. Re-check the
        # strict TP ordering before any exposure/liquidity step; no SL mutation.
        if bool(getattr(sd, "small_net_targets_compressed", False)):
            _c_tp1 = float(getattr(sd, "compressed_tp1", tp1) or tp1)
            _c_tp2 = float(getattr(sd, "compressed_tp2", tp2) or tp2)
            _c_tp3 = float(getattr(sd, "compressed_tp3", tp3 or 0.0) or (tp3 or 0.0))
            _cc_ok, _cc_msg = RiskCoherence.check(entry, sl, _c_tp1, _c_tp2, tp3=_c_tp3)
            if not _cc_ok:
                record_rejection(trace_id, symbol, "structural", f"small_net_compression_ordering:{_cc_msg}", "pre_send")
                return False, f"small_net_compression_ordering:{_cc_msg}", sd
            tp1, tp2, tp3 = _c_tp1, _c_tp2, _c_tp3
            LifecycleTrace.record(trace_id, "SMALL_NET_TARGET_COMPRESSION", {
                "tp1":tp1, "tp2":tp2, "tp3":tp3,
                "rr1_saved":float(getattr(sd, "small_net_target_compression_rr_saved", 0.0) or 0.0),
                "net_profit_floor_pct":float(CONFIG.get("V702_SMALL_NET_MIN_NET_PROFIT_PCT", 0.10)),
                "stop_loss_changed":False, "hard_gate_bypass":False,
            })
        # v4.5.50 — if fee-target rescue changed the TP geometry, re-assert
        # the full ordering gate BEFORE any exposure/liquidity work continues.
        if bool(getattr(sd, "fee_target_rescued", False)):
            _r_tp1 = float(getattr(sd, "rescued_tp1", tp1) or tp1)
            _r_tp2 = float(getattr(sd, "rescued_tp2", tp2) or tp2)
            _r_tp3 = float(getattr(sd, "rescued_tp3", tp3 or 0.0) or (tp3 or 0.0))
            _rc2_ok, _rc2_msg = RiskCoherence.check(
                entry, sl, _r_tp1, _r_tp2, tp3=_r_tp3
            )
            if not _rc2_ok:
                record_rejection(
                    trace_id, symbol, "structural", f"fee_rescue_ordering:{_rc2_msg}", "pre_send"
                )
                return False, f"fee_rescue_ordering:{_rc2_msg}", sd
            tp1, tp2, tp3 = _r_tp1, _r_tp2, _r_tp3
            LifecycleTrace.record(
                trace_id, "FEE_TARGET_RESCUE",
                {
                    "tp1": tp1, "tp2": tp2, "tp3": tp3,
                    "rr1": getattr(sd, "fee_target_rescue_rr1", 0.0),
                    "rr2": getattr(sd, "fee_target_rescue_rr2", 0.0),
                    "family": strategy_mode,
                }
            )
            try:
                STATS["v550_fee_target_rescues_applied"] = STATS.get(
                    "v550_fee_target_rescues_applied", 0
                ) + 1
                _v604_record_fee_rescue_forensics(
                    symbol,
                    entry=entry, sl=sl, tp1=tp1, tp2=tp2, tp3=tp3,
                    nominal=float(sd.notional_after_caps),
                    score=float(strategy_score),
                    strategy_mode=strategy_mode,
                    stage="presend",
                    result="applied_final_geometry",
                    detail={
                        "rr1": float(getattr(sd, "fee_target_rescue_rr1", 0.0) or 0.0),
                        "rr2": float(getattr(sd, "fee_target_rescue_rr2", 0.0) or 0.0),
                    },
                    reason="canonical_fee_rescue_consumed",
                )
            except Exception:
                _v647_record_suppressed_exception()

        # 3. Exposure (effective — concurrent count + balance-relative cap +
        #    v4.2.2 correlation hard-cap). Also layered here: per-symbol
        #    expectancy cooldown + optional news blackout (both bounded).
        ep_ok, ep_msg = ExposureProtection.check(
            sd.notional_after_caps, balance_free=sd.balance_free_usdt,
            symbol=symbol)
        if not ep_ok:
            record_rejection(trace_id, symbol, "sizing", ep_msg, "pre_send")
            return False, f"exposure:{ep_msg}", sd
        _ok_exp, _why_exp = SymbolExpectancyCooldown.check(symbol)
        if not _ok_exp:
            record_rejection(trace_id, symbol, "cooldown", _why_exp, "pre_send")
            return False, f"expectancy_cd:{_why_exp}", sd
        _ok_news, _why_news = NewsBlackout.check()
        if not _ok_news:
            record_rejection(trace_id, symbol, "circuit_breaker", _why_news, "pre_send")
            return False, f"news_blackout:{_why_news}", sd

        # 4. Liquidity depth — v4.0.9 DS-6: reuse cached_ob when available.
        ld_ok, ld_msg, ratio = await LiquidityDepth.check(
            exchange, symbol, sd.notional_after_caps, cached_ob=cached_ob)
        if not ld_ok:
            # V4.1 one-shot bounded rescue: only after a depth reject, only if
            # the reduced notional remains above minimum. No retry loop.
            rescued, sd_rescued, rescue_reason = await ExecutionRescue.try_depth_rescue(
                exchange, symbol, sd, cached_ob=cached_ob)
            if rescued:
                LifecycleTrace.record(trace_id, "SIZE_DOWN_RESCUE", {"reason": rescue_reason})
                return True, rescue_reason, sd_rescued
            record_rejection(trace_id, symbol, "liquidity", ld_msg, "pre_send",
                             ctx={"depth_ratio": ratio, "rescue": rescue_reason})
            return False, f"liquidity:{ld_msg}", sd

        return True, "ok", sd


class ShadowPreSendGate:
    """Balance-independent, read-only market/economic preflight for Paper evidence.

    It is intentionally NOT the live PreSendGate: it uses a virtual notional,
    cached order book and venue taker fee metadata only. It cannot reserve funds,
    create orders, mutate risk, or authorize execution. Live PreSendGate remains
    mandatory for every real order.
    """

    @staticmethod
    def _levels(raw, descending=False):
        rows = []
        for item in list(raw or [])[:20]:
            try:
                px, qty = float(item[0]), float(item[1])
                if math.isfinite(px) and math.isfinite(qty) and px > 0 and qty > 0:
                    rows.append((px, qty))
            except Exception:
                continue
        rows.sort(key=lambda x: x[0], reverse=bool(descending))
        return rows

    @staticmethod
    def _buy_vwap_for_quote(asks, quote_amount):
        remaining = float(quote_amount); spent = 0.0; bought = 0.0
        for px, qty in asks:
            take = min(qty, remaining / px)
            if take <= 0:
                continue
            cost = take * px; spent += cost; bought += take; remaining -= cost
            if remaining <= max(1e-8, quote_amount * 1e-10):
                break
        if remaining > max(1e-8, quote_amount * 1e-6) or bought <= 0:
            return None, None
        return spent / bought, bought

    @staticmethod
    def _sell_vwap_for_base(bids, base_amount):
        remaining = float(base_amount); received = 0.0; sold = 0.0
        for px, qty in bids:
            take = min(qty, remaining)
            if take <= 0:
                continue
            received += take * px; sold += take; remaining -= take
            if remaining <= max(1e-12, base_amount * 1e-10):
                break
        if remaining > max(1e-12, base_amount * 1e-6) or sold <= 0:
            return None
        return received

    @staticmethod
    async def _taker_fee_rate(exchange, symbol):
        cache = STATS.setdefault("v702_a55_taker_fee_cache", {})
        cached = cache.get(str(symbol)) if isinstance(cache, dict) else None
        if isinstance(cached, dict) and cached.get("rate") is not None:
            try:
                if float(WALL_NOW()) - float(cached.get("ts", 0.0) or 0.0) <= 3600.0:
                    return float(cached["rate"]), str(cached.get("source") or "cache")
            except Exception:
                pass
            cache.pop(str(symbol), None)
        rate = None; source = ""
        try:
            market = (getattr(exchange, "markets", {}) or {}).get(symbol) or {}
            raw = market.get("taker")
            if raw is not None:
                rate = float(raw); source = "exchange_market_taker"
        except Exception:
            rate = None
        if rate is None:
            try:
                trading_fees = ((getattr(exchange, "fees", {}) or {}).get("trading", {}) or {})
                raw = trading_fees.get("taker")
                if raw is not None:
                    rate = float(raw); source = "exchange_trading_fee_metadata"
            except Exception:
                rate = None
        if rate is None and callable(getattr(exchange, "fetch_trading_fee", None)):
            try:
                fee_call = exchange.fetch_trading_fee(symbol)
                if hasattr(fee_call, "__await__"):
                    fee_payload = await asyncio.wait_for(fee_call, timeout=2.5)
                else:
                    fee_payload = fee_call
                raw = (fee_payload or {}).get("taker") if isinstance(fee_payload, dict) else None
                if raw is not None:
                    rate = float(raw); source = "exchange_fetch_trading_fee"
            except Exception:
                rate = None
        if rate is None or not math.isfinite(rate) or rate < 0 or rate > 0.02:
            return None, "taker_fee_unavailable_or_invalid"
        cache[str(symbol)] = {"rate": rate, "source": source, "ts": float(WALL_NOW())}
        while len(cache) > 512:
            cache.pop(next(iter(cache)))
        return rate, source

    @classmethod
    async def evaluate(cls, exchange, symbol, entry, sl, tp1, tp2, tp3,
                       market_data=None, cached_ob=None, strategy_score=0.0,
                       strategy_mode="", strategy_style="SCALP",
                       timeframe_profile="", htf_strength=None, strategy_family=""):
        result = {"eligible": False, "reason": "not_evaluated", "ts": float(WALL_NOW()),
                  "mode": "SHADOW_ONLY", "exchange_order_submitted": False}
        try:
            md = market_data if isinstance(market_data, dict) else {}
            forbidden_checker = globals().get("_v587_is_forbidden_coin")
            if not callable(forbidden_checker):
                result["reason"] = "forbidden_asset_guard_unavailable"; return result
            is_forbidden, forbidden_reason = forbidden_checker(symbol)
            if is_forbidden:
                result["reason"] = f"forbidden_asset:{str(forbidden_reason)[:120]}"; return result
            e, stop, t1, t2, t3 = map(float, (entry, sl, tp1, tp2, tp3))
            if str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() != "SPOT":
                result["reason"] = "spot_only_contract_failed"; return result
            if not bool(CONFIG.get("LONG_ONLY", True)) or bool(CONFIG.get("ALLOW_SHORT", False)):
                result["reason"] = "long_only_contract_failed"; return result
            if not all(math.isfinite(x) and x > 0 for x in (e, stop, t1, t2, t3)):
                result["reason"] = "invalid_price_geometry"; return result
            rc_ok, rc_reason = RiskCoherence.check(e, stop, t1, t2, tp3=t3)
            if not rc_ok:
                result["reason"] = f"risk_geometry:{rc_reason}"; return result
            score = float(strategy_score or 0.0)
            score_floor = max(70.0, float(CONFIG.get("MIN_LIVE_SCORE", 70.0) or 70.0))
            if not math.isfinite(score) or score < score_floor:
                result["reason"] = "canonical_score_below_live_floor"; return result
            book = cached_ob if isinstance(cached_ob, dict) else (md.get("orderbook") or md.get("_v703_route_score_orderbook"))
            if not isinstance(book, dict):
                result["reason"] = "orderbook_missing"; return result
            stamp = md.get("orderbook_ts") or md.get("v703_route_orderbook_captured_ts") or md.get("spread_ts")
            if stamp is None:
                result["reason"] = "orderbook_timestamp_missing"; return result
            stamp = float(stamp)
            if stamp > 1e12:
                stamp /= 1000.0
            now_ts = float(WALL_NOW())
            if not math.isfinite(stamp) or stamp <= 0 or not math.isfinite(now_ts):
                result["reason"] = "orderbook_timestamp_invalid"
                return result
            # Small clock skew is tolerated; genuinely future-dated market data
            # is rejected instead of being clamped to age=0 and treated as fresh.
            future_tolerance_sec = 1.0
            if stamp > now_ts + future_tolerance_sec:
                result["reason"] = "orderbook_timestamp_in_future"
                result["orderbook_future_skew_sec"] = round(stamp - now_ts, 3)
                return result
            age = max(0.0, now_ts - stamp)
            max_age = max(1.0, float(CONFIG.get("V702_SHADOW_MAX_BOOK_AGE_SEC", CONFIG.get("V689_MAX_BOOK_AGE_SEC", 15.0))))
            if not math.isfinite(age) or age > max_age:
                result["reason"] = "orderbook_stale"; result["orderbook_age_sec"] = age; return result
            asks = cls._levels(book.get("asks"), descending=False)
            bids = cls._levels(book.get("bids"), descending=True)
            if not asks or not bids or bids[0][0] >= asks[0][0]:
                result["reason"] = "orderbook_invalid"; return result
            best_bid, best_ask = bids[0][0], asks[0][0]
            mid = (best_bid + best_ask) / 2.0
            spread_pct = 100.0 * (best_ask - best_bid) / mid
            max_spread = max(0.01, min(2.0, float(CONFIG.get("V702_SHADOW_MAX_SPREAD_PCT", CONFIG.get("V453_UNIVERSE_MAX_SPREAD_PCT", 0.50)))))
            if not math.isfinite(spread_pct) or spread_pct > max_spread:
                result["reason"] = "spread_above_shadow_limit"; result["spread_pct"] = spread_pct; return result
            notional = max(1.0, min(1000.0, float(os.environ.get("UNIFIED_PAPER_SIM_NOTIONAL_USDT", CONFIG.get("V702_SHADOW_VIRTUAL_NOTIONAL_USDT", 75.0)))))
            ask_depth = sum(px * qty for px, qty in asks[:5])
            bid_depth = sum(px * qty for px, qty in bids[:5])
            depth_ratio = max(0.0, min(ask_depth, bid_depth) / notional)
            required_depth = max(1.0, float(CONFIG.get("MIN_ORDER_BOOK_DEPTH_RATIO", 1.6)))
            if depth_ratio < required_depth:
                result.update({"reason": "insufficient_two_sided_depth", "depth_ratio": depth_ratio,
                               "required_depth_ratio": required_depth, "spread_pct": spread_pct})
                return result
            buy_vwap, base_qty = cls._buy_vwap_for_quote(asks, notional)
            if buy_vwap is None:
                result["reason"] = "insufficient_ask_depth_for_virtual_notional"; return result
            sell_proceeds = cls._sell_vwap_for_base(bids, base_qty)
            if sell_proceeds is None:
                result["reason"] = "insufficient_bid_depth_for_virtual_exit"; return result
            taker_rate, fee_source = await cls._taker_fee_rate(exchange, symbol)
            if taker_rate is None:
                result["reason"] = "taker_fee_unavailable_or_invalid"; return result
            market_friction_pct = max(0.0, 100.0 * (notional - sell_proceeds) / notional)
            fee_cost_usdt = taker_rate * (notional + sell_proceeds)
            fee_cost_pct = 100.0 * fee_cost_usdt / notional
            measured_cost_pct = market_friction_pct + fee_cost_pct
            if not math.isfinite(measured_cost_pct) or measured_cost_pct < 0.0:
                result["reason"] = "invalid_measured_round_trip_cost"; return result
            _cost_model = _v702_unified_round_trip_cost_pct(
                measured_cost_pct=measured_cost_pct, spread_pct=spread_pct,
                fee_cost_pct=fee_cost_pct,
            )
            round_trip_cost_pct = float(_cost_model["round_trip_cost_pct"])
            slippage_buy_pct = max(0.0, 100.0 * (buy_vwap - best_ask) / best_ask)
            slippage_sell_pct = max(0.0, 100.0 * (best_bid - sell_proceeds / base_qty) / best_bid)
            max_slip = max(0.01, float(CONFIG.get("V702_SHADOW_MAX_SLIPPAGE_PER_SIDE_PCT", 0.20)))
            if max(slippage_buy_pct, slippage_sell_pct) > max_slip:
                result.update({"reason": "slippage_above_shadow_limit", "slippage_buy_pct": slippage_buy_pct,
                               "slippage_sell_pct": slippage_sell_pct, "spread_pct": spread_pct})
                return result
            q1 = float(CONFIG.get("TP1_EXIT_PCT", 0.60))
            q2 = float(CONFIG.get("TP2_EXIT_PCT", 0.30))
            q3 = float(CONFIG.get("RUNNER_KEEP_PCT_AT_TP3", 0.10)) if bool(CONFIG.get("ENABLE_RUNNER_MODE", True)) else max(0.0, 1.0-q1-q2)
            if min(q1, q2, q3) < 0 or abs((q1+q2+q3)-1.0) > 1e-6:
                result["reason"] = "invalid_exit_split"; return result
            risk_pct = 100.0 * (e-stop) / e
            gross_tp1_pct = 100.0 * (t1-e) / e
            gross_tp2_pct = 100.0 * (t2-e) / e
            gross_tp3_pct = 100.0 * (t3-e) / e
            net_tp1_pct = gross_tp1_pct - round_trip_cost_pct
            net_tp1_rr = net_tp1_pct / max(risk_pct, 1e-12)
            blended_net_pct = q1*gross_tp1_pct + q2*gross_tp2_pct + q3*gross_tp3_pct - round_trip_cost_pct
            net_overall_rr = blended_net_pct / max(risk_pct, 1e-12)
            small_net = bool(CONFIG.get("V702_SMALL_NET_PROFIT_MODE_ENABLE", False))
            min_tp1_rr = float(CONFIG.get("V702_SMALL_NET_MIN_NET_RR_TP1", 0.25)) if small_net else float(CONFIG.get("MIN_NET_RR_TP1", 0.8))
            min_overall_rr = float(CONFIG.get("V702_SMALL_NET_MIN_NET_RR_OVERALL", 0.50)) if small_net else float(CONFIG.get("MIN_NET_RR_OVERALL", 1.2))
            min_net_pct = float(CONFIG.get("V702_SMALL_NET_MIN_NET_PROFIT_PCT", 0.10)) if small_net else 0.0
            gross_tp1_usdt = notional * gross_tp1_pct / 100.0
            min_fee_ratio = float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5))
            if net_tp1_rr < min_tp1_rr or net_overall_rr < min_overall_rr or net_tp1_pct < min_net_pct or gross_tp1_usdt < (min_fee_ratio * fee_cost_usdt):
                result.update({"reason": "net_economics_below_hard_floor", "net_tp1_rr": net_tp1_rr,
                               "net_overall_rr": net_overall_rr, "net_tp1_pct": net_tp1_pct,
                               "round_trip_cost_pct": round_trip_cost_pct, "required_tp1_rr": min_tp1_rr,
                               "required_overall_rr": min_overall_rr, "minimum_net_profit_pct": min_net_pct})
                return result
            result.update({
                "eligible": True, "reason": "shadow_presend_pass", "virtual_notional_usdt": notional,
                "round_trip_cost_pct": round_trip_cost_pct,
                "round_trip_cost_model": _cost_model,
                "round_trip_cost_r": (e * round_trip_cost_pct / 100.0) / max(e-stop, 1e-12),
                "market_friction_pct": market_friction_pct, "fee_cost_pct": fee_cost_pct,
                "taker_fee_rate": taker_rate, "taker_fee_source": fee_source,
                "spread_pct": spread_pct, "slippage_buy_pct": slippage_buy_pct,
                "slippage_sell_pct": slippage_sell_pct, "depth_ratio": depth_ratio,
                "vwap_buy": buy_vwap, "vwap_sell": sell_proceeds/base_qty,
                "net_tp1_rr": net_tp1_rr, "net_overall_rr": net_overall_rr,
                "net_tp1_pct": net_tp1_pct, "entry": e, "sl": stop, "tp1": t1, "tp2": t2, "tp3": t3,
                "family": str(strategy_family or strategy_mode or "UNKNOWN").upper(),
                "style": str(strategy_style or "UNKNOWN").upper(),
                "timeframe_profile": str(timeframe_profile or "UNKNOWN").upper(),
                "htf_strength": htf_strength, "account_specific_exposure_excluded": True,
            })
            return result
        except Exception as exc:
            result["reason"] = f"shadow_presend_exception:{type(exc).__name__}"
            return result


# =============================================================================
#  SECTION 27 — ORDER EXECUTOR (SL chain + Software SL fallback)
# =============================================================================

CONFIG.update({
    "V626_BALANCE_PREFLIGHT_TIMEOUT_SEC": 15.0,
    "V626_BALANCE_PREFLIGHT_BUFFER_PCT": 0.20,
})

# =============================================================================
# v4.5.99-V640 FINAL — LAST-MILE REAL BALANCE PREFLIGHT
# -----------------------------------------------------------------------------
# The live BUY path calls this helper immediately before the state-changing
# order call. The uploaded build referenced it but did not define it.
# This implementation is read-only, fail-closed, and does not resize/reprice
# or retry an order. It reuses the canonical BalanceReconciler authority.
# =============================================================================
async def _v626_execution_balance_preflight(
    exchange, symbol: str, qty: float, price: float,
    stage: str = "market_buy", trace_id: Optional[str] = None,
) -> Tuple[bool, str]:
    try:
        q = float(qty); px = float(price)
        if not (math.isfinite(q) and math.isfinite(px) and q > 0.0 and px > 0.0):
            return False, "invalid_order_cost_inputs"

        live = bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and not bool(
            CONFIG.get("PAPER_TRADING_MODE", False)
        )
        if not live:
            return True, "non_live_mode"

        # Fresh REAL balance is mandatory for a state-changing BUY. CACHE is
        # intentionally rejected here even when it is still usable for exits.
        timeout_sec = max(2.0, float(CONFIG.get("V626_BALANCE_PREFLIGHT_TIMEOUT_SEC", 15.0)))
        try:
            free, state = await asyncio.wait_for(
                BalanceReconciler.fetch(exchange), timeout=timeout_sec
            )
        except Exception as exc:
            return False, f"balance_prefetch_exception:{type(exc).__name__}"

        if str(state).upper() != "REAL":
            return False, f"balance_state_{str(state).lower()}"
        free = float(free)
        if not math.isfinite(free) or free <= 0.0:
            return False, "balance_unusable"

        # BUY by quantity reserves quote ~= qty*price. Include the configured
        # taker fee plus a tiny bounded quote buffer for market-order drift,
        # then preserve the mandatory operator reserve. This never authorizes
        # more than the canonical SizingEngine already decided.
        fee_pct = max(0.0, float(CONFIG.get("TAKER_FEE_PCT", 0.10))) / 100.0
        buffer_pct = max(0.0, float(CONFIG.get("V626_BALANCE_PREFLIGHT_BUFFER_PCT", 0.20))) / 100.0
        reserve = max(0.0, float(CONFIG.get("TRADING_BALANCE_RESERVE_USDT", 3.0)))
        required = (q * px) * (1.0 + fee_pct + buffer_pct) + reserve
        if not math.isfinite(required) or free + 1e-9 < required:
            reason = (
                f"insufficient_real_balance:free={free:.6f}"
                f"<required={required:.6f}:stage={stage}"
            )
            try:
                STATS["v626_balance_last_block"] = {
                    "symbol": str(symbol), "stage": str(stage),
                    "free": free, "required": required,
                    "qty": q, "price": px,
                }
            except Exception:
                _v647_record_suppressed_exception()
            return False, reason

        return True, f"real_balance_ok:{free:.6f}>={required:.6f}"
    except Exception as exc:
        # Any uncertainty at the final wire boundary is a hard block.
        return False, f"balance_prefight_fail_closed:{type(exc).__name__}"


def _v702_a52_client_order_params(exchange, method_name: str, *, allow=True):
    """Return a persisted, venue-scoped clientOrderId only when the API method can accept params.

    The ID is created before intent persistence/submission. It is never used to
    authorize a retry; it only strengthens exact-order reconciliation after a
    timeout/restart. Non-MEXC or incompatible adapters retain the old single-call
    path and are never probed by sending speculative orders.
    """
    try:
        if not allow or str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() != "SPOT":
            return "", {}
        if not bool(CONFIG.get("LONG_ONLY", True)):
            return "", {}
        if not bool(CONFIG.get("V702_A52_CLIENT_ORDER_ID_ENABLE", True)):
            return "", {}
        if str(getattr(exchange, "id", "") or "").lower() != "mexc":
            return "", {}
        # Inspect the underlying venue adapter. A proxy may expose a permissive
        # `params` signature while the actual CCXT/custom adapter does not.
        venue_exchange = getattr(exchange, "_exchange", exchange)
        method = getattr(venue_exchange, method_name, None)
        if not callable(method):
            return "", {}
        import inspect as _inspect
        try:
            params = _inspect.signature(method).parameters
            accepts_params = ("params" in params or any(
                item.kind in (_inspect.Parameter.VAR_POSITIONAL, _inspect.Parameter.VAR_KEYWORD)
                for item in params.values()))
        except Exception:
            accepts_params = False
        if not accepts_params:
            STATS["v702_a52_client_order_id_unavailable"] = int(
                STATS.get("v702_a52_client_order_id_unavailable", 0) or 0
            ) + 1
            return "", {}
        # MEXC client IDs are kept short and stable for the whole persisted intent.
        cid = "us" + uuid.uuid4().hex[:28]
        return cid, {"clientOrderId": cid}
    except Exception as exc:
        STATS["v702_a52_client_order_id_helper_errors"] = int(
            STATS.get("v702_a52_client_order_id_helper_errors", 0) or 0
        ) + 1
        logger.warning("[A52-CLIENT-ID] optional client id unavailable: %s", type(exc).__name__)
        return "", {}


def _v702_last_mile_entry_authorized(exchange, intent_context=None) -> Tuple[bool, str]:
    """Revalidate permission only when an exchange-create factory is invoked.

    safe_api_call may wait for the platform token bucket before invoking its
    factory. This check therefore runs after that await, immediately before the
    state-changing exchange method. The internal mock bypass is limited to the
    same exact active test harness as the initial submit boundary.
    """
    if KillSwitch.is_active():
        return False, "last_mile_kill_switch_no_order"
    try:
        if _v702_live_buy_possible(intent_context):
            return True, "authorized"
    except Exception:
        pass
    mock_type = globals().get("_V516MockExchange")
    proxy_type = globals().get("_V517ExchangeProxy")
    exchange_obj = getattr(exchange, "_exchange", None) if isinstance(proxy_type, type) and isinstance(exchange, proxy_type) else exchange
    is_test_mock = bool(globals().get("V644_SELFTEST_ACTIVE", False)) and isinstance(mock_type, type) and isinstance(exchange_obj, mock_type)
    if is_test_mock:
        return True, "authorized_internal_selftest_mock"
    try:
        blocked = globals().get("LIVE_ENTRIES_BLOCKED")
        if isinstance(blocked, dict) and bool(blocked.get("active")):
            return False, "last_mile_entry_block_no_order"
    except Exception:
        return False, "last_mile_entry_block_no_order"
    if _v702_env_is_explicitly_off("UNIFIED_LIVE_PILOT_ENABLE"):
        return False, "last_mile_authorization_revoked_no_order"
    try:
        ctx = intent_context if isinstance(intent_context, dict) else {}
        generated = ctx.get("candidate_generated_at_ms", ctx.get("generated_at_ms"))
        if generated is not None:
            fresh, reason, age = _v455_candidate_freshness_ok(generated)
            if not fresh:
                return False, "last_mile_candidate_stale_no_order:" + str(reason)[:80]
    except Exception:
        return False, "last_mile_candidate_stale_no_order:validation_error"
    return False, "last_mile_authorization_revoked_no_order"


class OrderExecutor:

    # ---- v4.0.2 PATCH C — Granular send-fail taxonomy --------------------
    @staticmethod
    def _classify_send_error(err: Exception) -> str:
        """Map raw exchange exception -> canonical send-fail reason code.
        Reason codes (all prefixed 'send_fail_'):
          balance | network_timeout | depth | price_deviation |
          exchange_reject | rate_limit | unknown
        """
        try:
            msg = str(err).lower()
        except Exception:
            msg = ""
        # Balance / funds
        if any(k in msg for k in ("insufficient", "balance", "not enough",
                                   "funds", "available")):
            return "balance"
        # Network / timeout
        if any(k in msg for k in ("timeout", "timed out", "connection",
                                   "connect", "reset by peer", "unreachable",
                                   "read timed out")):
            return "network_timeout"
        # Depth / liquidity
        if any(k in msg for k in ("depth", "liquidity", "not enough liquidity",
                                   "cannot be filled", "no bids", "no asks")):
            return "depth"
        # Price deviation / drift
        if any(k in msg for k in ("deviation", "price", "tick", "filter",
                                   "price_out_of_bounds", "invalid price")):
            return "price_deviation"
        # Rate limit
        if any(k in msg for k in ("rate limit", "too many requests", "429")):
            return "rate_limit"
        # Exchange reject (generic 4xx-ish)
        if any(k in msg for k in ("reject", "invalid", "forbidden", "400",
                                   "401", "403", "404", "lot size", "min notional",
                                   "min_notional", "symbol")):
            return "exchange_reject"
        return "unknown"

    @staticmethod
    def _record_send_fail(symbol: str, err: Exception,
                          trace_id: Optional[str] = None,
                          ctx: Optional[Dict[str, Any]] = None) -> str:
        """Emit granular reject.send.<reason> + per-reason counter, then trip CB."""
        reason = OrderExecutor._classify_send_error(err)
        if bool(CONFIG.get("SEND_FAIL_TAXONOMY_ENABLE", True)):
            key = f"send_fail_{reason}"
            STATS[key] = STATS.get(key, 0) + 1
            STATS["signals_failed_send"] = STATS.get("signals_failed_send", 0) + 1
            try:
                record_rejection(
                    trace_id or "n/a", symbol, "execution",
                    f"send_fail:{reason}", "submit_entry",
                    ctx={"error": str(err)[:220], **(ctx or {})}
                )
            except Exception as re:
                logger.debug(f"[SendFailTaxonomy] record_rejection suppressed: {re}")
        FailedSendCircuitBreaker.record_failure(symbol)
        try:
            STATS["last_send_fail_reason"] = str(reason)
            STATS[f"last_send_fail_reason.{symbol}"] = str(reason)
            STATS["last_send_fail_ts"] = MONO_NOW()
        except Exception:
            _v647_record_suppressed_exception()
        return reason

    # ---- v4.0.2 PATCH D — Precision / min-notional preflight -------------
    @staticmethod
    def _normalize_qty_price(exchange, symbol: str, qty: float,
                             price: Optional[float] = None
                             ) -> Tuple[Optional[float], Optional[float], Optional[str]]:
        """Normalize exchange quantity/price only with verified metadata.

        When precision preflight is enabled, missing metadata or precision
        methods are a hard error. Raw values are never forwarded as a fallback.
        """
        if not bool(CONFIG.get("PRECISION_PREFLIGHT_ENABLE", True)):
            try:
                q = float(qty)
                px = None if price is None else float(price)
                if not math.isfinite(q) or q <= 0 or (px is not None and (not math.isfinite(px) or px <= 0)):
                    return None, None, "precision_input_non_finite_or_non_positive"
                return q, px, None
            except Exception:
                return None, None, "precision_input_invalid"
        try:
            if isinstance(qty, bool) or (price is not None and isinstance(price, bool)):
                return None, None, "precision_input_boolean_invalid"
            raw_qty = float(qty)
            raw_price = None if price is None else float(price)
            if not math.isfinite(raw_qty) or raw_qty <= 0:
                return None, None, "precision_input_qty_non_finite_or_non_positive"
            if raw_price is not None and (not math.isfinite(raw_price) or raw_price <= 0):
                return None, None, "precision_input_price_non_finite_or_non_positive"

            market_fn = getattr(exchange, "market", None)
            amount_fn = getattr(exchange, "amount_to_precision", None)
            price_fn = getattr(exchange, "price_to_precision", None)
            if not callable(market_fn) or not callable(amount_fn):
                return None, None, "precision_preflight_error:required_market_or_amount_precision_method_missing"
            market = market_fn(symbol)
            if not isinstance(market, dict) or not market:
                return None, None, "precision_preflight_error:market_metadata_unavailable"
            qty_text = amount_fn(symbol, raw_qty)
            qty_norm = float(qty_text)
            if not math.isfinite(qty_norm) or qty_norm <= 0:
                return None, None, "precision_normalized_qty_non_finite_or_non_positive"

            price_norm = None
            if raw_price is not None:
                if not callable(price_fn):
                    return None, None, "precision_preflight_error:price_precision_method_missing"
                price_text = price_fn(symbol, raw_price)
                price_norm = float(price_text)
                if not math.isfinite(price_norm) or price_norm <= 0:
                    return None, None, "precision_normalized_price_non_finite_or_non_positive"

            limits = market.get("limits") or {}
            if not isinstance(limits, dict):
                return None, None, "precision_preflight_error:market_limits_malformed"
            amount_limits = limits.get("amount") or {}
            cost_limits = limits.get("cost") or {}
            if not isinstance(amount_limits, dict) or not isinstance(cost_limits, dict):
                return None, None, "precision_preflight_error:market_limits_malformed"

            def _finite_limit(container, key):
                value = container.get(key)
                if value is None:
                    return None
                if isinstance(value, bool):
                    raise ValueError("boolean_limit")
                number = float(value)
                if not math.isfinite(number) or number < 0:
                    raise ValueError("invalid_limit")
                return number

            min_amount = _finite_limit(amount_limits, "min")
            max_amount = _finite_limit(amount_limits, "max")
            min_cost = _finite_limit(cost_limits, "min")
            max_cost = _finite_limit(cost_limits, "max")
            if min_amount is not None and qty_norm < min_amount:
                return None, None, f"qty_below_min({qty_norm:.10f}<{min_amount})"
            if max_amount is not None and qty_norm > max_amount:
                return None, None, f"qty_above_max({qty_norm:.10f}>{max_amount})"
            notional_price = price_norm if price_norm is not None else raw_price
            if notional_price is not None:
                notional = qty_norm * notional_price
                if not math.isfinite(notional) or notional <= 0:
                    return None, None, "precision_notional_non_finite_or_non_positive"
                if min_cost is not None and notional < min_cost:
                    return None, None, f"notional_below_min_cost({notional:.8f}<{min_cost})"
                if max_cost is not None and notional > max_cost:
                    return None, None, f"notional_above_max_cost({notional:.8f}>{max_cost})"
            return qty_norm, price_norm, None
        except Exception as exc:
            return None, None, f"precision_preflight_error:{type(exc).__name__}:{str(exc)[:120]}"

    @staticmethod
    async def _normalize_qty_price_with_reload(exchange, symbol: str, qty: float,
                                               price: Optional[float] = None
                                               ) -> Tuple[Optional[float], Optional[float], Optional[str]]:
        """v4.2.1 UNBLOCK-PATCH — one-shot market-metadata recovery wrapper.
        On a precision/market-metadata error ONLY (never on deterministic
        limit violations like qty_below_min / notional_below_min_cost), reload
        exchange markets ONCE and retry the normalization ONCE. A second
        failure stays fail-closed (error returned, no order fires). A
        per-symbol reload throttle (300s) prevents reload storms. The sync
        _normalize_qty_price core is untouched.
        """
        qty_n, price_n, err = OrderExecutor._normalize_qty_price(
            exchange, symbol, qty, price)
        if err is None:
            return qty_n, price_n, None
        if not str(err).startswith("precision_preflight_error"):
            # Deterministic geometry/limit rejection — reload cannot fix it.
            return qty_n, price_n, err
        try:
            _rl_map = getattr(OrderExecutor, "_precision_reload_ts", None)
            if _rl_map is None:
                _rl_map = {}
                OrderExecutor._precision_reload_ts = _rl_map
            _now_rl = MONO_NOW()
            _last_rl = float(_rl_map.get(symbol, 0.0) or 0.0)
            if (_now_rl - _last_rl) < 300.0:
                # Already reloaded recently — fail closed on the original error.
                return None, None, f"precision_reload_throttled:{err}"
            _rl_map[symbol] = _now_rl
            _reload_res = exchange.load_markets(reload=True)
            if asyncio.iscoroutine(_reload_res):
                await _reload_res
            logger.warning(f"[Precision] {symbol}: markets reloaded once after "
                           f"metadata error; retrying normalization")
        except Exception as _rl_e:
            return None, None, f"precision_reload_failed:{_rl_e}:{err}"
        # Single retry — result returned as-is (fail-closed on 2nd failure).
        return OrderExecutor._normalize_qty_price(exchange, symbol, qty, price)

    @staticmethod
    async def submit_entry(exchange, symbol: str, qty: float, price: float,
                           is_paper: bool = False,
                           trace_id: Optional[str] = None,
                           intent_context: Optional[Dict[str, Any]] = None
                           ) -> Tuple[bool, Optional[str], float]:
        if is_paper:
            return True, f"PAPER_{uuid.uuid4().hex[:8]}", price
        # A real BUY requires explicit operator opt-in, a runnable live state,
        # no KillSwitch, and no active entry block. Missing/invalid env is OFF.
        # Only the exact in-process self-test adapter may bypass this guard.
        if not _v702_live_buy_possible(intent_context):
            _mock_exchange_type = globals().get("_V516MockExchange")
            _mock_proxy_type = globals().get("_V517ExchangeProxy")
            _selftest_exchange = exchange
            if isinstance(_mock_proxy_type, type) and isinstance(_selftest_exchange, _mock_proxy_type):
                _selftest_exchange = getattr(_selftest_exchange, "_exchange", None)
            _authorized_selftest_mock = (
                bool(globals().get("V644_SELFTEST_ACTIVE", False))
                and isinstance(_mock_exchange_type, type)
                and isinstance(_selftest_exchange, _mock_exchange_type)
            )
            if not _authorized_selftest_mock:
                try:
                    record_rejection(trace_id or "n/a", symbol, "policy",
                                     "live_operator_opt_in_or_runtime_gate_missing", "submit_entry_final_guard")
                except Exception as _off_rej_exc:
                    _v593_note_suppressed_exception("submit_entry.live_authorization_guard_telemetry", _off_rej_exc)
                STATS["v702_submit_entry_monitor_only_blocks"] = int(
                    STATS.get("v702_submit_entry_monitor_only_blocks", 0) or 0
                ) + 1
                logger.warning("[V702-EXEC-OFF] final BUY submission boundary blocked symbol=%s; explicit live opt-in/runtime gate required", symbol)
                return False, None, 0.0
            logger.info("[V702-EXEC-OFF] authorized internal mock self-test adapter; no live exchange client")
        # v4.0.2 PATCH D — precision preflight (fail-closed)
        # v4.2.1 UNBLOCK-PATCH — routed through the one-shot reload wrapper:
        # stale market metadata now triggers a single load_markets(reload=True)
        # + single retry instead of an immediate fail-closed reject.
        qty_n, price_n, prec_err = await OrderExecutor._normalize_qty_price_with_reload(
            exchange, symbol, qty, price
        )
        if prec_err or qty_n is None:
            STATS["send_fail_precision"] = STATS.get("send_fail_precision", 0) + 1
            STATS["signals_failed_send"] = STATS.get("signals_failed_send", 0) + 1
            try:
                record_rejection(trace_id or "n/a", symbol, "execution",
                                 f"send_fail:precision:{prec_err}",
                                 "submit_entry_preflight",
                                 ctx={"qty": qty, "price": price})
            except Exception as _rej_exc:
                _v593_note_suppressed_exception("submit_entry.precision_rejection_telemetry", _rej_exc)
            logger.warning(f"[submit_entry] precision preflight rejected {symbol}: {prec_err}")
            return False, None, 0.0
        # v4.2.1 UNBLOCK-PATCH — KillSwitch in-flight guard: re-check
        # IMMEDIATELY before the buy hits the wire. PreSendGate checks
        # earlier in the pipeline; a halt triggered during sizing/liquidity
        # would otherwise still ship the order. Treated as pre-fire reject.
        if KillSwitch.is_active():
            logger.critical(f"[submit_entry] KillSwitch active — aborting in-flight buy {symbol}")
            try:
                record_rejection(trace_id or "n/a", symbol, "circuit_breaker",
                                 "kill_switch_inflight", "submit_entry")
            except Exception as _ks_exc:
                _v593_note_suppressed_exception("submit_entry.kill_switch_telemetry", _ks_exc)
            return False, None, 0.0
        # v4.2.2 ENHANCEMENT (2) — MAKER-FIRST entry (optional, bounded).
        # The system is already fee-aware (net-RR after fees), so we first try
        # a passive LIMIT buy a few bps below the ask and wait a short,
        # bounded window for a fill. If it does NOT fill within the window we
        # CANCEL the resting limit and fall back to the EXISTING market path
        # (unchanged). Disabled by default (MAKER_FIRST_ENTRY_ENABLE=False).
        # Fail-closed: ANY error in the maker attempt falls through to the
        # normal market path; a cancel failure aborts the entry (we never
        # leave an ambiguous resting order before buying).
        if CONFIG.get("MAKER_FIRST_ENTRY_ENABLE", False):
            _maker_intent_id = ""
            _maker_terminal_no_fill = False
            try:
                _ticker = await safe_api_call(
                    "maker_first_ticker", lambda: exchange.fetch_ticker(symbol))
                _ask = float((_ticker or {}).get("ask") or 0.0)
                _ref = _ask if _ask > 0 else float(price_n or price)
                # Never place the resting LIMIT above the canonical planned entry.
                # For PULLBACK this keeps the entry thesis intact even when the ask
                # has already moved higher during the short handoff window.
                _planned_cap = float(price_n or price)
                _raw_lim_px = _ref * (1.0 - float(CONFIG.get("MAKER_FIRST_OFFSET_BPS", 5.0)) / 1e4)
                _lim_px = min(_raw_lim_px, _planned_cap) if _planned_cap > 0 else _raw_lim_px
                _qn2, _pn2, _perr2 = await OrderExecutor._normalize_qty_price_with_reload(
                    exchange, symbol, qty_n, _lim_px)
                if not _perr2 and _qn2 is not None and _pn2 is not None:
                    # V626 merged: final REAL-balance preflight immediately before
                    # the state-changing maker LIMIT BUY. It never resizes,
                    # reprices, lowers a gate, or retries an order.
                    _v626_bal_ok, _v626_bal_reason = await _v626_execution_balance_preflight(
                        exchange, symbol, _qn2, _pn2, stage="maker_limit", trace_id=trace_id
                    )
                    if not _v626_bal_ok:
                        logger.warning(
                            f"[V626-BALANCE] {symbol} maker entry blocked before wire: "
                            f"{_v626_bal_reason}"
                        )
                        return False, None, 0.0
                    # V702 telemetry coherence: maker-first LIMIT BUY is a
                    # state-changing venue submission and must be counted.
                    STATS["v701_order_submit_attempts"] = int(
                        STATS.get("v701_order_submit_attempts", 0) or 0
                    ) + 1
                    STATS["v701_cycle_order_submit_attempts"] = int(
                        STATS.get("v701_cycle_order_submit_attempts", 0) or 0
                    ) + 1
                    STATS["v701_last_order_submit"] = {
                        "method": "create_limit_buy_order",
                        "symbol": str(symbol),
                        "cycle_id": int(STATS.get("v681_runtime_cycle_id", 0) or 0),
                        "ts": WALL_NOW(),
                    }
                    if KillSwitch.is_active():
                        live_entries_block(f"kill_switch_before_maker_buy_{symbol}", where="OrderExecutor.submit_entry")
                        return False, None, 0.0
                    _maker_client_id, _maker_client_params = _v702_a52_client_order_params(
                        exchange, "create_limit_buy_order")
                    _maker_intent_id = await DBManager.abegin_execution_intent(
                        symbol, str(trace_id or ""), "BUY", "LIMIT",
                        float(_qn2), float(_pn2),
                        details={**dict(intent_context or {}), "intent_stage":"MAKER_FIRST",
                                 **({"clientOrderId":_maker_client_id, "a52_client_order_id":_maker_client_id}
                                    if _maker_client_id else {})},
                    )
                    try:
                        def _maker_submit_call():
                            _allowed, _why = _v702_last_mile_entry_authorized(exchange, intent_context)
                            if not _allowed:
                                raise ValueError(_why)
                            if not (math.isfinite(float(_qn2)) and float(_qn2) > 0 and math.isfinite(float(_pn2)) and float(_pn2) > 0):
                                raise ValueError("last_mile_authorization_revoked_no_order:invalid_normalized_values")
                            if _maker_client_params:
                                return exchange.create_limit_buy_order(symbol, _qn2, _pn2, _maker_client_params)
                            return exchange.create_limit_buy_order(symbol, _qn2, _pn2)
                        _lim = await safe_api_call("create_limit_buy", _maker_submit_call)
                    except Exception as _maker_submit_exc:
                        _maker_rejected = _v702_definitive_no_order_rejection(_maker_submit_exc)
                        await DBManager.aupdate_execution_intent(
                            _maker_intent_id, "REJECTED_NO_ORDER" if _maker_rejected else "SUBMISSION_UNKNOWN",
                            details={"exception_type":type(_maker_submit_exc).__name__, "exception":str(_maker_submit_exc)[:240],
                                     "definitive_rejection":bool(_maker_rejected),
                                     **({"clientOrderId":_maker_client_id} if _maker_client_id else {})},
                        )
                        if _maker_rejected:
                            _maker_terminal_no_fill = True
                        raise
                    _lim_id = str((_lim or {}).get("id") or "")
                    if not _lim_id:
                        await DBManager.aupdate_execution_intent(
                            _maker_intent_id, "SUBMISSION_UNKNOWN",
                            details={"reason":"venue_order_id_missing_after_create"},
                        )
                        live_entries_block(f"maker_order_id_unknown_{symbol}", where="OrderExecutor.submit_entry")
                        raise _V517UnknownExecution("maker_order_id_missing")
                    try:
                        await DBManager.aupdate_execution_intent(
                            _maker_intent_id, "ORDER_KNOWN", venue_order_id=_lim_id,
                            details={"venue_status":str((_lim or {}).get("status") or "unknown"),
                                     **({"clientOrderId":_maker_client_id} if _maker_client_id else {})},
                        )
                    except Exception as _maker_order_persist_exc:
                        # The exchange returned a real order ID. Persistence failure
                        # must not bypass fetch/cancel/fill reconciliation and protection.
                        live_entries_block(f"maker_order_persistence_failed_{symbol}", where="OrderExecutor.submit_entry")
                        STATS["v702_maker_order_known_persist_failures"] = int(
                            STATS.get("v702_maker_order_known_persist_failures", 0) or 0
                        ) + 1
                        logger.critical("[A52-INTENT] %s maker order %s is known but ORDER_KNOWN persistence failed: %s",
                                        symbol, _lim_id, type(_maker_order_persist_exc).__name__)
                    _deadline = MONO_NOW() + float(CONFIG.get("MAKER_FIRST_WAIT_SEC", 4.0))
                    _filled_px = 0.0
                    while MONO_NOW() < _deadline:
                        try:
                            _o = await safe_api_call(
                                "maker_first_fetch_order",
                                lambda: exchange.fetch_order(_lim_id, symbol))
                            _st = str((_o or {}).get("status") or "").lower()
                            _filled_amt = float((_o or {}).get("filled") or 0.0)
                            if _st == "closed" or (_filled_amt >= float(_qn2) * 0.999):
                                _filled_px = float((_o or {}).get("average") or
                                                   (_o or {}).get("price") or _pn2)
                                break
                        except Exception:
                            break
                        await asyncio.sleep(0.5)
                    if _filled_px > 0:
                        _maker_fq = 0.0
                        _maker_fa = 0.0
                        try:
                            _source = _o if isinstance(_o, dict) else _lim
                            _maker_fq, _maker_fa, _auth = await _v553_reconcile_buy_fill(
                                exchange, symbol, _source, _qn2, float(_pn2 or _lim_px)
                            )
                            with _V553_BUY_FILL_CONTEXTS_LOCK:
                                if _lim_id in _V553_BUY_FILL_CONTEXTS:
                                    _V553_BUY_FILL_CONTEXTS[_lim_id]["execution_intent_id"] = _maker_intent_id
                            await DBManager.aupdate_execution_intent(
                                _maker_intent_id, "FILL_CONFIRMED", venue_order_id=_lim_id,
                                details={"filled_qty":float(_maker_fq),"fill_price":float(_maker_fa),"order_status":str((_auth or {}).get("status") or "unknown")},
                            )
                            _filled_px = _maker_fa
                        except Exception as _re:
                            # If authoritative fill facts were already obtained, a DB
                            # exception is not permission to forget exposure. Keep the
                            # fill context, block new entries and return it for adoption.
                            if (_maker_fq > 0.0 and _maker_fa > 0.0
                                    and math.isfinite(float(_maker_fq)) and math.isfinite(float(_maker_fa))):
                                live_entries_block(f"maker_post_fill_persistence_recovery_{symbol}", where="OrderExecutor.submit_entry")
                                try:
                                    await DBManager.aupdate_execution_intent(
                                        _maker_intent_id, "FILL_CONFIRMED", venue_order_id=_lim_id,
                                        details={"filled_qty":float(_maker_fq), "fill_price":float(_maker_fa),
                                                 "post_fill_recovery_required":True, "exception_type":type(_re).__name__},
                                    )
                                except Exception:
                                    STATS["v702_post_fill_intent_persist_failures"] = int(
                                        STATS.get("v702_post_fill_intent_persist_failures", 0) or 0
                                    ) + 1
                                with _V553_BUY_FILL_CONTEXTS_LOCK:
                                    if _lim_id in _V553_BUY_FILL_CONTEXTS:
                                        _V553_BUY_FILL_CONTEXTS[_lim_id]["execution_intent_id"] = _maker_intent_id
                                        _V553_BUY_FILL_CONTEXTS[_lim_id]["entry_reconcile_required"] = True
                                logger.critical("[A52-INTENT] %s maker fill confirmed; preserving known fill for adoption/protection despite persistence failure", symbol)
                                return True, _lim_id, float(_maker_fa)
                            logger.critical(
                                f"[V553-FILL] {symbol} limit fill could not be reconciled: {_re}"
                            )
                            live_entries_block(f"maker_fill_reconcile_unknown_{symbol}", where="OrderExecutor.submit_entry")
                            return False, None, 0.0
                        logger.info(
                            f"[MakerFirst] {symbol} filled via limit @ {_filled_px:.8f}"
                        )
                        return True, _lim_id, _filled_px
                    # Cancel the resting limit before deciding whether fallback is safe.
                    # A timeout can hide a fill racing the cancel; always fetch the final
                    # order state after verified cancellation before considering another BUY.
                    _canceled = await OrderExecutor.cancel_order_safe(
                        exchange, _lim_id, symbol)
                    if _canceled is not True:
                        # Cancellation is ambiguous, so never submit the market fallback.
                        # Make one authoritative order-state read: a known fill must be adopted;
                        # an unknown result stays durable and blocks all subsequent entries.
                        try:
                            _uncertain_order = await safe_api_call(
                                "maker_first_order_after_cancel_unknown",
                                lambda: exchange.fetch_order(_lim_id, symbol),
                            )
                            _uncertain_qty = float((_uncertain_order or {}).get("filled") or (_uncertain_order or {}).get("executedQty") or 0.0)
                            if _uncertain_qty > 0:
                                _ufq, _ufa, _uauth = await _v553_reconcile_buy_fill(
                                    exchange, symbol, _uncertain_order, _qn2, float(_pn2 or _lim_px)
                                )
                                with _V553_BUY_FILL_CONTEXTS_LOCK:
                                    if _lim_id in _V553_BUY_FILL_CONTEXTS:
                                        _V553_BUY_FILL_CONTEXTS[_lim_id]["execution_intent_id"] = _maker_intent_id
                                        _V553_BUY_FILL_CONTEXTS[_lim_id]["entry_reconcile_required"] = True
                                await DBManager.aupdate_execution_intent(
                                    _maker_intent_id, "FILL_CONFIRMED", venue_order_id=_lim_id,
                                    details={"fill_qty":float(_ufq),"fill_price":float(_ufa),"cancel_unverified":True},
                                )
                                live_entries_block(f"maker_cancel_unverified_filled_{symbol}", where="OrderExecutor.submit_entry")
                                return True, _lim_id, float(_ufa)
                        except Exception as _uncertain_exc:
                            logger.critical("[MakerFirst] %s could not reconcile cancel-unknown order: %s", symbol, _uncertain_exc)
                        await DBManager.aupdate_execution_intent(
                            _maker_intent_id, "SUBMISSION_UNKNOWN", venue_order_id=_lim_id,
                            details={"reason":"maker_cancel_unverified"},
                        )
                        with _V553_BUY_FILL_CONTEXTS_LOCK:
                            _V553_BUY_FILL_CONTEXTS[_lim_id] = {
                                "symbol":str(symbol),"requested_qty":float(_qn2),"gross_filled_qty":0.0,
                                "filled_qty":0.0,"net_filled_qty":0.0,"fill_price":float(_pn2 or _lim_px),
                                "partial_fill":False,"oversized_fill":False,"entry_reconcile_required":True,
                                "fill_quantity_unverified":True,"order_status":"unknown","order_ids":[_lim_id],
                                "execution_intent_id":_maker_intent_id,"fee_records":[],"fill_cost_estimate":0.0,
                            }
                        live_entries_block(f"maker_cancel_unverified_{symbol}", where="OrderExecutor.submit_entry")
                        logger.critical(
                            f"[MakerFirst] {symbol} limit cancel UNVERIFIED (id={_lim_id}); "
                            "market fallback suppressed; unresolved zero-known-fill intent retained for reconciliation"
                        )
                        return True, _lim_id, float(_pn2 or _lim_px)
                    try:
                        _final_limit = await safe_api_call(
                            "maker_first_final_order_after_cancel",
                            lambda: exchange.fetch_order(_lim_id, symbol),
                        )
                        if not isinstance(_final_limit, dict):
                            raise RuntimeError("maker_cancel_final_state_unavailable")
                        _final_status = str(_final_limit.get("status") or "unknown").lower()
                        _final_filled = float(_final_limit.get("filled") or _final_limit.get("executedQty") or 0.0)
                        _terminal_states = {"canceled", "cancelled", "expired", "rejected", "closed", "filled", "complete"}
                        if _final_status not in _terminal_states:
                            raise RuntimeError(f"maker_cancel_not_terminal:{_final_status}")
                        if _final_filled > 0.0:
                            _fq, _fa, _auth = await _v553_reconcile_buy_fill(
                                exchange, symbol, _final_limit, _qn2, float(_pn2 or _lim_px)
                            )
                            with _V553_BUY_FILL_CONTEXTS_LOCK:
                                if _lim_id in _V553_BUY_FILL_CONTEXTS:
                                    _V553_BUY_FILL_CONTEXTS[_lim_id]["execution_intent_id"] = _maker_intent_id
                            await DBManager.aupdate_execution_intent(
                                _maker_intent_id, "FILL_CONFIRMED", venue_order_id=_lim_id,
                                details={"fill_qty":float(_fq),"fill_price":float(_fa),"status_after_cancel":_final_status},
                            )
                            if _fq > 0:
                                # Adopt only the confirmed partial/full maker fill. Do
                                # not add another planned-quantity BUY on top of it.
                                logger.critical(
                                    "[MakerFirst] %s adopting terminal post-cancel fill qty=%.10f/%.10f; "
                                    "market fallback suppressed to prevent overbuy",
                                    symbol, _fq, _qn2,
                                )
                                if _fq < _qn2 * float(CONFIG.get("EXIT_FILL_MIN_CONFIRM_RATIO", 0.995)):
                                    live_entries_block(
                                        f"maker_partial_fill_adopted_{symbol}",
                                        where="OrderExecutor.submit_entry.maker_first",
                                    )
                                return True, _lim_id, float(_fa)
                    except Exception as _final_reconcile_exc:
                        # Only a definitive terminal zero-fill order permits the
                        # market fallback. Unknown post-cancel state blocks retries.
                        logger.critical(
                            "[MakerFirst] %s post-cancel state not safe for fallback: %s",
                            symbol, _final_reconcile_exc,
                        )
                        live_entries_block(
                            f"maker_cancel_final_state_unknown_{symbol}",
                            where="OrderExecutor.submit_entry.maker_first",
                        )
                        return False, None, 0.0
                    await DBManager.aupdate_execution_intent(
                        _maker_intent_id, "NO_FILL_TERMINAL", venue_order_id=_lim_id,
                        details={"status_after_cancel":_final_status,"filled_qty":0.0},
                    )
                    _maker_terminal_no_fill = True
                    try:
                        _fb_t = await safe_api_call(
                            "maker_first_fallback_ticker",
                            lambda: exchange.fetch_ticker(symbol),
                        )
                        _fb_ask = float((_fb_t or {}).get("ask") or (_fb_t or {}).get("last") or 0.0)
                        _fallback_max = float(CONFIG.get("MAKER_FIRST_MARKET_FALLBACK_MAX_DRIFT_PCT", 0.20))
                        _planned = float(price_n or price)
                        if _fb_ask <= 0 or _planned <= 0:
                            raise RuntimeError("fallback_price_unavailable")
                        _fb_drift = max(0.0, (_fb_ask - _planned) / _planned * 100.0)
                        if _fb_drift > _fallback_max:
                            logger.warning(
                                f"[MakerFirst] {symbol} market fallback refused: "
                                f"ask={_fb_ask:.8f} planned={_planned:.8f} drift={_fb_drift:.4f}%>{_fallback_max:.4f}%"
                            )
                            return False, None, 0.0
                    except Exception as _fb_exc:
                        logger.warning(f"[MakerFirst] {symbol} fallback validation failed: {_fb_exc}")
                        return False, None, 0.0
                    logger.info(
                        f"[MakerFirst] {symbol} limit not filled in window; "
                        f"market fallback allowed within {_fallback_max:.4f}% of planned entry"
                    )
            except Exception as _mf_e:
                # v4.5.53: an unknown LIMIT outcome is NOT safe to treat as a
                # harmless maker error because the order may already be resting.
                if _v517_is_unknown_execution_error(_mf_e):
                    try:
                        _rows = await _v517_fetch_recent_orders(exchange, symbol)
                        _match = _v517_match_order(
                            _rows, symbol=symbol, side="buy", qty=qty_n,
                            price=price_n or price,
                            started_wall=WALL_NOW() - float(CONFIG.get("V517_UNKNOWN_ORDER_LOOKBACK_SEC", 20.0)),
                            client_order_id=_maker_client_id, require_identity=True,
                        )
                        if _match:
                            _fq, _fa, _auth = await _v553_reconcile_buy_fill(
                                exchange, symbol, _match, qty_n, float(price_n or price)
                            )
                            _matched_id = str(_auth.get("id") or _match.get("id") or "")
                            if _maker_intent_id and _matched_id:
                                with _V553_BUY_FILL_CONTEXTS_LOCK:
                                    if _matched_id in _V553_BUY_FILL_CONTEXTS:
                                        _V553_BUY_FILL_CONTEXTS[_matched_id]["execution_intent_id"] = _maker_intent_id
                                        _V553_BUY_FILL_CONTEXTS[_matched_id]["entry_reconcile_required"] = True
                                await DBManager.aupdate_execution_intent(
                                    _maker_intent_id, "FILL_CONFIRMED", venue_order_id=_matched_id,
                                    details={"fill_qty":float(_fq),"fill_price":float(_fa),"recovered_recent_order":True},
                                )
                            live_entries_block(f"unknown_maker_fill_recovered_{symbol}", where="OrderExecutor.submit_entry")
                            return True, _matched_id, _fa
                    except Exception as _recon_exc:
                        _v593_note_suppressed_exception("submit_entry.limit_fill_reconcile_telemetry", _recon_exc)
                    live_entries_block(
                        f"execution_unknown_limit_entry_{symbol}",
                        where="OrderExecutor.submit_entry.maker_first"
                    )
                    STATS["v553_unknown_limit_entry_blocked"] = int(
                        STATS.get("v553_unknown_limit_entry_blocked", 0) or 0
                    ) + 1
                    logger.critical(
                        f"[V553-FILL] {symbol} LIMIT entry outcome unknown; "
                        "market fallback suppressed and new entries remain blocked"
                    )
                    return False, None, 0.0
                if _maker_intent_id and not _maker_terminal_no_fill:
                    try:
                        await DBManager.aupdate_execution_intent(
                            _maker_intent_id, "SUBMISSION_UNKNOWN",
                            details={"reason":"maker_path_exception_before_terminal_zero_fill", "exception_type":type(_mf_e).__name__, "exception":str(_mf_e)[:240]},
                        )
                    except Exception as _v705_exc:
                        _v705_note_persist_failure("maker_submission_unknown", symbol, _v705_exc)
                    live_entries_block(f"maker_path_outcome_unknown_{symbol}", where="OrderExecutor.submit_entry.maker_first")
                    logger.critical(
                        "[MakerFirst] %s maker path failed before terminal zero-fill proof; market fallback suppressed: %s",
                        symbol, _mf_e,
                    )
                    return False, None, 0.0
                # Only a proven terminal zero-fill maker order may fall through to market.
                logger.debug(f"[MakerFirst] {symbol} verified no-fill maker path; guarded market fallback may proceed: {_mf_e}")

        # V626 merged: last-mile REAL balance/funds preflight immediately before
        # the MARKET BUY reaches the exchange. This closes the observed
        # insufficient-balance failure without resizing or retrying.
        _v626_bal_ok, _v626_bal_reason = await _v626_execution_balance_preflight(
            exchange, symbol, qty_n, float(price_n or price),
            stage="market_buy", trace_id=trace_id
        )
        if not _v626_bal_ok:
            logger.warning(
                f"[V626-BALANCE] {symbol} market entry blocked before wire: "
                f"{_v626_bal_reason}"
            )
            return False, None, 0.0
        try:
            if KillSwitch.is_active():
                live_entries_block(f"kill_switch_before_market_buy_{symbol}", where="OrderExecutor.submit_entry")
                return False, None, 0.0
            _market_client_id, _market_client_params = _v702_a52_client_order_params(
                exchange, "create_market_buy_order")
            _market_intent_id = await DBManager.abegin_execution_intent(
                symbol, str(trace_id or ""), "BUY", "MARKET",
                float(qty_n), float(price_n or price),
                details={**dict(intent_context or {}), "intent_stage":"MARKET_BUY",
                         **({"clientOrderId":_market_client_id, "a52_client_order_id":_market_client_id}
                            if _market_client_id else {})},
            )
            _market_intent_status = "SUBMISSION_STARTED"
            try:
                def _market_submit_call():
                    _allowed, _why = _v702_last_mile_entry_authorized(exchange, intent_context)
                    if not _allowed:
                        raise ValueError(_why)
                    if not (math.isfinite(float(qty_n)) and float(qty_n) > 0 and math.isfinite(float(price_n or price)) and float(price_n or price) > 0):
                        raise ValueError("last_mile_authorization_revoked_no_order:invalid_normalized_values")
                    if _market_client_params:
                        return exchange.create_market_buy_order(symbol, qty_n, _market_client_params)
                    return exchange.create_market_buy_order(symbol, qty_n)
                order = await safe_api_call("create_market_buy", _market_submit_call)
            except Exception as _market_submit_exc:
                _market_rejected = _v702_definitive_no_order_rejection(_market_submit_exc)
                _market_intent_status = "REJECTED_NO_ORDER" if _market_rejected else "SUBMISSION_UNKNOWN"
                await DBManager.aupdate_execution_intent(
                    _market_intent_id, "REJECTED_NO_ORDER" if _market_rejected else "SUBMISSION_UNKNOWN",
                    details={"exception_type":type(_market_submit_exc).__name__, "exception":str(_market_submit_exc)[:240],
                             "definitive_rejection":bool(_market_rejected),
                             **({"clientOrderId":_market_client_id} if _market_client_id else {})},
                )
                if not _market_rejected:
                    live_entries_block(f"market_buy_submission_unknown_{symbol}", where="OrderExecutor.submit_entry")
                raise
            oid = str(order.get("id") or "")
            if not oid:
                _market_intent_status = "SUBMISSION_UNKNOWN"
                await DBManager.aupdate_execution_intent(
                    _market_intent_id, "SUBMISSION_UNKNOWN",
                    details={"reason":"venue_order_id_missing_after_create"},
                )
                live_entries_block(f"market_order_id_unknown_{symbol}", where="OrderExecutor.submit_entry")
                raise _V517UnknownExecution("market_order_id_missing")
            _market_intent_status = "ORDER_KNOWN"
            try:
                await DBManager.aupdate_execution_intent(
                    _market_intent_id, "ORDER_KNOWN", venue_order_id=oid,
                    details={"venue_status":str((order or {}).get("status") or "unknown"),
                             **({"clientOrderId":_market_client_id} if _market_client_id else {})},
                )
            except Exception as _market_order_persist_exc:
                # Exchange acceptance and exact ID are authoritative even when the
                # ledger write failed. Keep the live-entry latch, but continue immediate
                # venue fill reconciliation so known exposure can be adopted/protected.
                live_entries_block(f"market_order_persistence_failed_{symbol}", where="OrderExecutor.submit_entry")
                STATS["v702_maker_order_known_persist_failures"] = int(
                    STATS.get("v702_maker_order_known_persist_failures", 0) or 0
                ) + 1
                logger.critical("[A52-INTENT] %s market order %s is known but ORDER_KNOWN persistence failed: %s",
                                symbol, oid, type(_market_order_persist_exc).__name__)
            try:
                _fq, fill_px, _auth_order = await _v553_reconcile_buy_fill(
                    exchange, symbol, order, qty_n, float(price_n or price)
                )
                with _V553_BUY_FILL_CONTEXTS_LOCK:
                    if oid in _V553_BUY_FILL_CONTEXTS:
                        _V553_BUY_FILL_CONTEXTS[oid]["execution_intent_id"] = _market_intent_id
                _market_intent_status = "FILL_CONFIRMED"
                await DBManager.aupdate_execution_intent(
                    _market_intent_id, "FILL_CONFIRMED", venue_order_id=oid,
                    details={"fill_qty":float(_fq),"fill_price":float(fill_px),"order_status":str((_auth_order or {}).get("status") or "unknown")},
                )
                _market_status = str((_auth_order or {}).get("status") or "unknown").lower()
                _market_terminal = _market_status in {"closed", "filled", "complete", "canceled", "cancelled", "expired", "rejected"}
                if not _market_terminal:
                    # A partial/open MARKET response must not be followed by another BUY
                    # while the original order could still complete.
                    _market_cancel_ok = await OrderExecutor.cancel_order_safe(exchange, oid, symbol)
                    if _market_cancel_ok is True:
                        try:
                            _market_final = await safe_api_call(
                                "market_buy_final_after_cancel", lambda: exchange.fetch_order(oid, symbol), retry_safe=False
                            )
                            _market_final_status = str((_market_final or {}).get("status") or "unknown").lower()
                            if isinstance(_market_final, dict) and _market_final_status in {"closed", "filled", "complete", "canceled", "cancelled", "expired", "rejected"}:
                                _fq, fill_px, _auth_order = await _v553_reconcile_buy_fill(
                                    exchange, symbol, _market_final, qty_n, float(price_n or price)
                                )
                                with _V553_BUY_FILL_CONTEXTS_LOCK:
                                    if oid in _V553_BUY_FILL_CONTEXTS:
                                        _V553_BUY_FILL_CONTEXTS[oid]["execution_intent_id"] = _market_intent_id
                                await DBManager.aupdate_execution_intent(
                                    _market_intent_id, "FILL_CONFIRMED", venue_order_id=oid,
                                    details={"fill_qty":float(_fq),"fill_price":float(fill_px),"order_status":_market_final_status,"residual_cancel_verified":True},
                                )
                                _market_terminal = True
                        except Exception as _market_final_exc:
                            logger.critical("[BUY-FILL] %s final market order reconciliation failed: %s", symbol, _market_final_exc)
                    if not _market_terminal:
                        with _V553_BUY_FILL_CONTEXTS_LOCK:
                            if oid in _V553_BUY_FILL_CONTEXTS:
                                _V553_BUY_FILL_CONTEXTS[oid]["entry_reconcile_required"] = True
                                _V553_BUY_FILL_CONTEXTS[oid]["order_status"] = _market_status
                        live_entries_block(f"market_buy_nonterminal_fill_{symbol}", where="OrderExecutor.submit_entry")
                        STATS["market_buy_nonterminal_fill_blocked"] = int(STATS.get("market_buy_nonterminal_fill_blocked", 0) or 0) + 1
            except Exception as _fill_exc:
                # If the venue reconciliation already produced an authoritative fill,
                # a later intent-DB write error is a persistence fault, not an unknown
                # fill. Preserve the fill context and return the known order so the
                # caller can adopt the exposure and attempt protection.
                try:
                    _known_fq = float(locals().get("_fq", 0.0) or 0.0)
                    _known_fill_px = float(locals().get("fill_px", 0.0) or 0.0)
                except Exception:
                    _known_fq, _known_fill_px = 0.0, 0.0
                if (_known_fq > 0.0 and _known_fill_px > 0.0
                        and math.isfinite(_known_fq) and math.isfinite(_known_fill_px)
                        and str(locals().get("_market_intent_status", "")).upper() == "FILL_CONFIRMED"):
                    live_entries_block(f"post_fill_persistence_recovery_{symbol}", where="OrderExecutor.submit_entry")
                    try:
                        await DBManager.aupdate_execution_intent(
                            _market_intent_id, "FILL_CONFIRMED", venue_order_id=oid,
                            details={"fill_qty":_known_fq,"fill_price":_known_fill_px,
                                     "post_fill_recovery_required":True,"exception_type":type(_fill_exc).__name__,
                                     "exception":str(_fill_exc)[:180]},
                        )
                    except Exception as _retry_fill_persist_exc:
                        STATS["v702_post_fill_intent_persist_failures"] = int(
                            STATS.get("v702_post_fill_intent_persist_failures", 0) or 0
                        ) + 1
                        logger.critical("[ExecutionIntent] %s fill confirmed but DB persistence remains unavailable: %s",
                                        symbol, type(_retry_fill_persist_exc).__name__)
                    logger.critical("[V553-FILL] %s fill is authoritative; preserve order/fill for adoption and SL attempt",
                                    symbol)
                    return True, oid, _known_fill_px
                reason = f"send_fail:fill_reconcile:{_fill_exc}"
                logger.critical(f"[V553-FILL] {symbol} BUY fill reconciliation failed: {_fill_exc}")
                try:
                    record_rejection(
                        trace_id or "n/a", symbol, "execution", reason,
                        "submit_entry_fill_reconcile",
                        ctx={"qty": qty_n, "planned_entry": price_n or price, "order_id": oid}
                    )
                except Exception as _rej_exc:
                    _v593_note_suppressed_exception("submit_entry.fill_reconcile_telemetry", _rej_exc)
                live_entries_block(f"execution_unknown_fill_{symbol}", where="OrderExecutor.submit_entry")
                try:
                    await DBManager.aupdate_execution_intent(
                        _market_intent_id, "SUBMISSION_UNKNOWN", venue_order_id=oid,
                        details={"reason":"fill_reconciliation_failed","exception":str(_fill_exc)[:240]},
                    )
                    with _V553_BUY_FILL_CONTEXTS_LOCK:
                        _V553_BUY_FILL_CONTEXTS[oid] = {
                            "symbol":str(symbol),"requested_qty":float(qty_n),"gross_filled_qty":0.0,
                            "filled_qty":0.0,"net_filled_qty":0.0,"fill_price":float(price_n or price),
                            "partial_fill":False,"oversized_fill":False,"entry_reconcile_required":True,
                            "fill_quantity_unverified":True,"order_status":"unknown","order_ids":[oid],
                            "execution_intent_id":_market_intent_id,"fee_records":[],"fill_cost_estimate":0.0,
                        }
                    return True, oid, float(price_n or price)
                except Exception as _v705_exc:
                    _v705_note_persist_failure("market_fill_unknown", symbol, _v705_exc)
                return False, None, 0.0
            return True, oid, fill_px
        except Exception as e:
            if locals().get("_market_intent_id"):
                _intent_status = str(locals().get("_market_intent_status", "") or "").upper()
                _known_order_id = str(locals().get("oid", "") or "")
                _known_fill_qty = locals().get("_fq", 0.0)
                _known_fill_px = locals().get("fill_px", 0.0)
                # A definitive no-order rejection is terminal evidence. Preserve it
                # and retry persistence best-effort instead of poisoning it into an
                # unknown-submission latch. Anything sent/accepted but not safely
                # reconciled remains fail-closed and carries the known order id.
                if _intent_status == "REJECTED_NO_ORDER":
                    try:
                        await DBManager.aupdate_execution_intent(
                            _market_intent_id, "REJECTED_NO_ORDER",
                            details={"exception_type":type(e).__name__,"exception":str(e)[:240],
                                     "definitive_rejection":True,"persistence_retry":True},
                        )
                    except Exception as _persist_reject_exc:
                        STATS["v702_rejected_no_order_persist_failures"] = int(
                            STATS.get("v702_rejected_no_order_persist_failures", 0) or 0
                        ) + 1
                        logger.critical("[ExecutionIntent] definitive rejection persistence failed for %s: %s",
                                        symbol, type(_persist_reject_exc).__name__)
                else:
                    try:
                        # Never downgrade a locally confirmed fill to an unknown
                        # fill merely because a later DB update failed. Keep the
                        # live-entry latch active and let trade adoption/protection
                        # plus reconciliation finish from the confirmed venue facts.
                        if (_intent_status == "FILL_CONFIRMED" and _known_order_id
                                and math.isfinite(float(_known_fill_qty or 0.0))
                                and float(_known_fill_qty or 0.0) > 0.0
                                and math.isfinite(float(_known_fill_px or 0.0))
                                and float(_known_fill_px or 0.0) > 0.0):
                            try:
                                await DBManager.aupdate_execution_intent(
                                    _market_intent_id, "FILL_CONFIRMED", venue_order_id=_known_order_id,
                                    details={"fill_qty":float(_known_fill_qty),"fill_price":float(_known_fill_px),
                                             "post_fill_recovery_required":True,"persistence_retry":True,
                                             "exception_type":type(e).__name__},
                                )
                            except Exception as _v705_exc:
                                _v705_note_persist_failure("post_fill_confirmed", symbol, _v705_exc)
                            live_entries_block(f"post_fill_recovery_required_{symbol}", where="OrderExecutor.submit_entry")
                            reason = OrderExecutor._record_send_fail(
                                symbol, e, trace_id=trace_id,
                                ctx={"qty":qty_n,"price":_known_fill_px,"stage":"post_fill_persistence"},
                            )
                            logger.critical("[ExecutionIntent] %s fill is confirmed; returning known order for adoption/protection despite persistence fault", symbol)
                            return True, _known_order_id, float(_known_fill_px)
                        await DBManager.aupdate_execution_intent(
                            _market_intent_id, "SUBMISSION_UNKNOWN", venue_order_id=_known_order_id or None,
                            details={"exception_type":type(e).__name__,"exception":str(e)[:240],
                                     "reconciliation_required":True},
                        )
                        live_entries_block(f"market_submission_outcome_unknown_{symbol}", where="OrderExecutor.submit_entry")
                    except Exception as _persist_exc:
                        STATS["v702_execution_intent_persist_failures"] = int(
                            STATS.get("v702_execution_intent_persist_failures", 0) or 0
                        ) + 1
                        live_entries_block(f"execution_intent_persistence_failed_{symbol}", where="OrderExecutor.submit_entry")
                        logger.critical("[ExecutionIntent] persistence failed after submission for %s; entries remain blocked: %s",
                                        symbol, type(_persist_exc).__name__)
            reason = OrderExecutor._record_send_fail(
                symbol, e, trace_id=trace_id,
                ctx={"qty": qty_n, "price": price_n or price, "stage": "create_market_buy"}
            )
            _validation_log = bool(globals().get("_V699_VALIDATE_ONLY_REQUEST", False)) or bool(globals().get("V644_SELFTEST_ACTIVE", False))
            (logger.info if _validation_log else logger.error)(
                f"[OrderExecutor{"-SELFTEST" if _validation_log else ""}] submit_entry failed {symbol} reason={reason}: {e}"
            )
            return False, None, 0.0

    @staticmethod
    async def place_sl(exchange, trade: TradeState,
                       sl_price_override: Optional[float] = None) -> Tuple[bool, Optional[str]]:
        """v4.0.2 PATCH A: SL quantity is ALWAYS derived from remaining_position,
        never from the original position_size_asset. Prevents over-sized SL
        (double-stop hazard) after partial exits."""
        max_retries = int(CONFIG["SL_RETRIES_MAX"])
        symbol = trade.symbol
        # ---- Bind SL qty to actual remaining ---------------------------------
        sl_qty = float(getattr(trade, "remaining_position", 0.0) or 0.0)
        if sl_qty <= 0:
            sl_qty = float(trade.position_size_asset or 0.0)
        if sl_qty <= 0:
            logger.warning(f"[SL] {symbol} refusing to place SL: qty<=0")
            trade.sl_health_state = "UNVERIFIED"
            trade.sl_failure_reason = "sl_qty_non_positive"
            return False, None
        # Precision preflight for SL (qty + price)
        if sl_price_override is not None:
            _requested_sl = float(sl_price_override)
        else:
            try:
                _requested_sl = float(_v702_exit_snapshot_for_trade(trade).get("final_sl") or trade.current_sl)
            except Exception:
                _requested_sl = float(trade.current_sl)
        qty_n, price_n, prec_err = OrderExecutor._normalize_qty_price(
            exchange, symbol, sl_qty, _requested_sl
        )
        if prec_err or qty_n is None:
            logger.warning(f"[SL] {symbol} precision preflight failed: {prec_err}")
            trade.software_sl_active = True
            trade.sl_health_state = "UNVERIFIED"
            trade.sl_failure_reason = f"sl_precision:{prec_err}"
            SoftwareSLTelemetry.register_activation(symbol, reason="sl_precision_fail")
            return False, None
        sl_qty = qty_n
        sl_price = price_n if price_n and price_n > 0 else _requested_sl

        # v4.5.56: MEXC SPOT software-only protection mode. Do not call a
        # generic CCXT stop helper when the venue has not explicitly certified
        # trigger support. Mark the software watchdog active and let the caller
        # keep the real filled position alive under the dedicated PM task.
        try:
            _cert_stop_mode = ProductionCapabilityGate.stop_mode()
        except Exception:
            _cert_stop_mode = None
        if _cert_stop_mode == "software_sl_only":
            trade.sl_failure_reason = "native_spot_stop_not_certified:software_sl_only"
            trade.sl_order_id = None
            try:
                _armed = await _v560_arm_software_sl(
                    trade, "native_spot_stop_not_certified:software_sl_only"
                )
                if not _armed:
                    trade.software_sl_active = True
                    trade.sl_health_state = "UNVERIFIED"
                    trade.software_sl_activated_ts = MONO_NOW()
                    SoftwareSLTelemetry.register_activation(
                        symbol, reason="mexc_spot_software_sl_only"
                    )
            except Exception:
                trade.software_sl_active = True
                trade.sl_health_state = "UNVERIFIED"
                trade.software_sl_activated_ts = MONO_NOW()
                try:
                    SoftwareSLTelemetry.register_activation(
                        symbol, reason="mexc_spot_software_sl_only"
                    )
                except Exception as _tele_exc:
                    _v593_note_suppressed_exception("place_sl.software_sl_activation_telemetry", _tele_exc)
            logger.warning(
                f"[SL:V556] {symbol} native MEXC spot stop not explicitly certified; "
                "software-SL protection mode armed — no immediate emergency SELL"
            )
            return False, None

        # v4.0.9 DS-1 — post-create verification config
        _pcv_enable = bool(CONFIG.get("SL_POST_CREATE_VERIFY_ENABLE", True))
        _pcv_tol_pct = float(CONFIG.get("SL_POST_CREATE_VERIFY_TOLERANCE_PCT", 0.15))
        _pcv_settle_sec = float(CONFIG.get("SL_POST_CREATE_VERIFY_SETTLE_SEC", 0.4))
        for attempt in range(1, max_retries + 1):
            try:
                # v4.4 execution hardening: use the exact stop path certified at boot.
                _stop_mode = ProductionCapabilityGate.stop_mode() or "dedicated_stop_market"
                _stop_method = "create_stop_market_order" if _stop_mode == "dedicated_stop_market" else "create_order"
                _stop_client_id, _stop_client_params = _v702_a52_client_order_params(exchange, _stop_method)
                if _stop_mode == "dedicated_stop_market":
                    order = await safe_api_call(
                        "create_sl",
                        lambda: exchange.create_stop_market_order(
                            symbol, "sell", sl_qty, sl_price, _stop_client_params
                        ) if _stop_client_params else exchange.create_stop_market_order(
                            symbol, "sell", sl_qty, sl_price
                        )
                    )
                elif _stop_mode == "create_order_stoploss_market":
                    _sl_params = {"stopLossPrice": sl_price, **_stop_client_params}
                    order = await safe_api_call(
                        "create_sl",
                        lambda: exchange.create_order(
                            symbol, "market", "sell", sl_qty, None, _sl_params
                        )
                    )
                elif _stop_mode == "create_order_trigger_market":
                    _sl_params = {"triggerPrice": sl_price, "triggerDirection": "descending", **_stop_client_params}
                    order = await safe_api_call(
                        "create_sl",
                        lambda: exchange.create_order(
                            symbol, "market", "sell", sl_qty, None, _sl_params
                        )
                    )
                else:
                    raise RuntimeError(f"unsupported_certified_stop_mode:{_stop_mode}")
                oid = str(order.get("id") or "")
                if _stop_client_id:
                    trade.sl_client_order_id = str(_stop_client_id)
                if not oid or oid == "None":
                    raise RuntimeError("create_sl returned no order id")
                # v4.0.9 DS-1 — POST-CREATE VERIFICATION. A returned id is NOT
                # proof the STOP_MARKET is live and correctly configured on
                # MEXC spot. Fetch the order back and confirm: (a) status is
                # open/new/pending/untriggered, (b) the returned stop/trigger
                # price matches sl_price within tolerance, (c) side == sell.
                # On ANY failure → treat as unverified: best-effort cancel the
                # suspect id, mark POST_CREATE_UNVERIFIED, and continue the
                # retry loop (software-SL fallback engages after max retries).
                verified = True
                verify_detail = "verification_disabled"
                if _pcv_enable:
                    verified = False
                    verify_detail = "pending"
                    try:
                        if _pcv_settle_sec > 0:
                            await asyncio.sleep(_pcv_settle_sec)
                        fetched = await safe_api_call(
                            "fetch_order_sl_verify",
                            lambda: exchange.fetch_order(oid, symbol),
                        )
                        _status_raw = str(fetched.get("status") or "").lower()
                        _ok_status = _status_raw in (
                            "open", "new", "pending", "untriggered", "accepted",
                        )
                        _info = fetched.get("info") or {}
                        _trig = None
                        for _c in (
                            fetched.get("stopPrice"),
                            fetched.get("triggerPrice"),
                            _info.get("stopLossPrice"),
                            _info.get("stopPrice"),
                            _info.get("triggerPrice"),
                            _info.get("activationPrice"),
                        ):
                            try:
                                if _c is None:
                                    continue
                                _cv = float(_c)
                                if _cv > 0:
                                    _trig = _cv
                                    break
                            except Exception:
                                continue
                        _trigger_ok = False
                        _trig_dev_pct = -1.0
                        if _trig is not None and sl_price > 0:
                            _trig_dev_pct = abs(_trig - sl_price) / sl_price * 100.0
                            # v4.2.1 UNBLOCK-PATCH — tick-aware tolerance.
                            # On low-priced MEXC pairs one tick can exceed
                            # the flat 0.30% band, producing false
                            # POST_CREATE_UNVERIFIED → software fallback.
                            # Effective tolerance = max(flat, 2*tick/price).
                            # Fail-closed kept: pairs whose tick/price
                            # exceeds SL_TICK_PRICE_HARD_REJECT_PCT are NOT
                            # accepted here — verification stays failed.
                            _eff_tol = _pcv_tol_pct
                            if bool(CONFIG.get("SL_POST_CREATE_VERIFY_DYNAMIC_TICK_ENABLE", True)):
                                try:
                                    _mkt = exchange.market(symbol) or {}
                                    _tick = float((_mkt.get("precision") or {}).get("price") or 0.0)
                                    # ccxt precision may be a decimal count; convert
                                    if _tick > 0 and _tick == int(_tick) and _tick >= 1:
                                        _tick = 10.0 ** (-_tick)
                                    if _tick > 0 and sl_price > 0:
                                        _tick_pct = (_tick / sl_price) * 100.0
                                        _hard = float(CONFIG.get("SL_TICK_PRICE_HARD_REJECT_PCT", 0.5))
                                        if _tick_pct <= _hard:
                                            _eff_tol = max(_pcv_tol_pct, 2.0 * _tick_pct)
                                except Exception:
                                    _eff_tol = _pcv_tol_pct
                            _trigger_ok = (_trig_dev_pct <= _eff_tol)
                        _side_raw = str(fetched.get("side") or _info.get("side") or "").lower()
                        _side_ok = (_side_raw == "sell") if _side_raw else True
                        if _ok_status and _trigger_ok and _side_ok:
                            verified = True
                            verify_detail = (
                                f"ok:status={_status_raw}"
                                f":trig={_trig}:dev={_trig_dev_pct:.4f}%"
                            )
                        else:
                            verify_detail = (
                                f"fail:status={_status_raw}:trig={_trig}"
                                f":dev={_trig_dev_pct:.4f}%:side={_side_raw}"
                            )
                    except Exception as _ve:
                        verified = False
                        verify_detail = f"exception:{_ve}"
                if not verified:
                    # v4.5.53 — second proof path for stop orders that are
                    # live at the venue but poorly represented by fetch_order().
                    try:
                        _fallback_stop = await _v553_verify_live_stop(
                            exchange, symbol, sl_qty, sl_price, expected_id=oid
                        )
                        if _fallback_stop:
                            _fb_id = str(_fallback_stop.get("id") or oid)
                            if _fb_id:
                                oid = _fb_id
                            verified = True
                            verify_detail = (
                                f"fallback_open_order_ok:id={oid}:"
                                f"status={_fallback_stop.get('status')}:"
                                f"trigger={_v553_trigger_from_order(_fallback_stop)}"
                            )
                            STATS["v553_sl_open_order_recovered"] = int(
                                STATS.get("v553_sl_open_order_recovered", 0) or 0
                            ) + 1
                            logger.critical(
                                f"[V553-SL] {symbol} STOP verified by open/recent-order fallback "
                                f"id={oid} detail={verify_detail}"
                            )
                    except Exception as _fb_sl_exc:
                        logger.debug(
                            f"[V553-SL] {symbol} fallback verification suppressed: {_fb_sl_exc}"
                        )

                if not verified:
                    STATS["sl_post_create_verify_failed"] = \
                        STATS.get("sl_post_create_verify_failed", 0) + 1
                    (logger.info if bool(globals().get("V644_SELFTEST_ACTIVE", False)) else logger.critical)(
                        f"[SL:DS-1] {symbol} POST-CREATE VERIFY FAILED "
                        f"(attempt {attempt}/{max_retries} id={oid}) {verify_detail}"
                    )
                    # Best-effort cancel of the potentially-live-but-malformed
                    # id so we don't leave an orphan trigger; tolerated on
                    # failure — software SL fallback will engage regardless.
                    _cleanup_cancel_verified = False
                    try:
                        _cleanup_cancel_verified = await OrderExecutor.cancel_order_safe(exchange, oid, symbol) is True
                    except Exception as _cancel_exc:
                        _v593_note_suppressed_exception("place_sl.cleanup_cancel", _cancel_exc)
                    trade.sl_health_state = "POST_CREATE_UNVERIFIED"
                    trade.sl_failure_reason = f"post_create_verify_failed:{verify_detail}"
                    if not _cleanup_cancel_verified:
                        # Do not create another stop while a malformed/unknown
                        # prior trigger may still be live. Software stop remains
                        # the single fallback; order state needs reconciliation.
                        trade.sl_health_state = "CANCEL_UNVERIFIED"
                        trade.sl_failure_reason = f"prior_sl_cancel_unverified:{oid}:{verify_detail}"
                        live_entries_block(
                            f"native_sl_cancel_unverified_{symbol}",
                            where="OrderExecutor.place_sl",
                        )
                        logger.critical(
                            "[SL-CRITICAL] %s stop id=%s could not be proven canceled; "
                            "refusing duplicate stop submission",
                            symbol, oid,
                        )
                        trade.software_sl_active = True
                        trade.software_sl_activated_ts = MONO_NOW()
                        SoftwareSLTelemetry.register_activation(symbol, reason="native_sl_cancel_unverified")
                        return False, None
                    await asyncio.sleep(min(1.5 * attempt, 4.0))
                    continue
                # ---- Verified branch ----
                trade.sl_order_id = oid
                trade.sl_health_state = "CONFIRMED"
                trade.sl_last_verified_ts = MONO_NOW()
                trade.sl_verify_consec_unverified = 0
                # Snapshot the qty this SL covers, for later reconciliation checks
                trade.sl_covered_qty = sl_qty  # v4.0.2 PATCH A
                # If software SL was previously active and we now have a real SL,
                # clear the fallback flag.
                if trade.software_sl_active:
                    logger.info(f"[SL] {symbol} exchange SL restored — clearing software_sl_active")
                    trade.software_sl_active = False
                    trade.software_sl_activated_ts = 0.0
                if _pcv_enable:
                    logger.info(f"[SL:DS-1] {symbol} SL verified post-create: {verify_detail}")
                return True, oid
            except Exception as e:
                logger.warning(f"[SL] attempt {attempt}/{max_retries} {symbol}: {e}")
                await asyncio.sleep(min(2.0 * attempt, 6.0))
        # All retries failed — activate software SL fallback (PATCH B telemetry)
        trade.software_sl_active = True
        trade.sl_health_state = "UNVERIFIED"
        trade.sl_failure_reason = "exchange_sl_all_retries_failed"
        trade.software_sl_activated_ts = MONO_NOW()
        SoftwareSLTelemetry.register_activation(symbol, reason="exchange_sl_all_retries_failed")
        (logger.info if bool(globals().get("V644_SELFTEST_ACTIVE", False)) else logger.critical)(f"[SL] {symbol} SOFTWARE_SL_ACTIVE — exchange SL unreliable")
        return False, None

    @staticmethod
    async def cancel_order_safe(exchange, order_id: str, symbol: str) -> bool:
        """Returns True ONLY if cancel is confirmed."""
        try:
            await safe_api_call(
                "cancel_order",
                lambda: exchange.cancel_order(order_id, symbol)
            )
            # Verify
            try:
                o = await safe_api_call(
                    "fetch_order",
                    lambda: exchange.fetch_order(order_id, symbol)
                )
                status = str(o.get("status") or "").lower()
                if status in ("canceled", "cancelled"):
                    return True
                if status in ("closed", "filled", "rejected"):
                    logger.warning(
                        f"[cancel_order_safe] {order_id}: non-cancel terminal "
                        f"status={status}; treating cancel as UNVERIFIED"
                    )
                else:
                    logger.warning(
                        f"[cancel_order_safe] {order_id}: status={status or 'unknown'} "
                        "does not prove cancellation"
                    )
                return False
            except Exception:
                # If fetch fails, we cannot confirm — return False (fail-closed)
                return False
        except Exception as e:
            logger.warning(f"[cancel_order_safe] {order_id}: {e}")
            return False

    @staticmethod
    async def emergency_close(exchange, trade: TradeState, reason: str,
                              exit_px: Optional[float] = None) -> bool:
        """v4.0.3 PATCH F: cancel the live SL BEFORE selling to prevent an
        orphan SL from firing after the market-sell (double-sell / negative-
        balance hazard). Cancel is best-effort verified.

        v4.2.2 FIX (docstring/sbehavior unification): failure to cancel the SL
        is NO LONGER 'logged but non-aborting'. When the SL cancel cannot be
        VERIFIED (cancel returned non-True or raised), the trade is declared
        CANCEL_UNVERIFIED, `sl_order_id` is preserved intact (never cleared),
        `sl_health_state` is never flipped to a healthy value, the market-sell
        is DEFERRED, LIVE_ENTRIES_BLOCKED is raised, and this method returns
        False (fail-closed). The market-sell only proceeds after a CONFIRMED
        cancel. The paragraph below originally described the pre-v4.1.1
        behavior; the executable reality (and this docstring) is fail-closed.

        v4.0.4 PATCH S: UNIFIED ACCOUNTING. After cancel-SL + market-sell
        (or short-circuit when qty<=0) route through _finalize_and_record_r()
        so R is recorded in DailyCircuitBreaker and the trade is popped from
        ACTIVE_TRADES in the SAME path. Finalizer is idempotent (guarded by
        _FINALIZED_TRADE_IDS), so callers that already invoke it after
        emergency_close remain safe (no double R, no double pop).

        v4.0.6 FIX D: SL-cancel confirmation is now an EXPLICIT declared
        state. If cancel cannot be verified we do NOT flip `sl_order_id` to
        None, we do NOT reset `sl_health_state` to a healthy value, and we
        do NOT re-place any SL. The market-sell is DEFERRED until cancellation
        is proven; the residual/ambiguous SL is loudly declared
        `CANCEL_UNVERIFIED` so operators / audits cannot mistake an unverified
        state for a safe one.
        """
        try:
            # v4.5.71: central exit authority MUST run before any SL mutation.
            _auth_ok, _auth_reason = _v571_exit_authority(
                trade, reason=str(reason), exit_px=exit_px
            )
            if not _auth_ok:
                STATS["v571_exit_authority_blocks"] = int(
                    STATS.get("v571_exit_authority_blocks", 0) or 0
                ) + 1
                logger.critical(
                    f"[V571-EXIT] BLOCKED emergency/market SELL {trade.symbol} "
                    f"reason={reason} authority={_auth_reason}"
                )
                if _v570_protection_sell_reason(str(reason)):
                    try:
                        live_entries_block(
                            f"exit_authority_block_{trade.symbol}",
                            where="OrderExecutor.emergency_close",
                        )
                    except Exception as _block_exc:
                        _v593_note_suppressed_exception("emergency_close.exit_authority_block", _block_exc)
                return False

            sl_cancel_unverified = False
            # ---- v4.0.3 PATCH F + v4.0.6 FIX D + v4.0.6 FIX #2:
            # cancel SL first (strict verify). Explicit contract:
            #   * sl_order_id is set to None ONLY on a CONFIRMED cancel.
            #   * Any failure / exception path → sl_cancel_unverified=True,
            #     sl_order_id is preserved intact, sl_health_state is set
            #     to "CANCEL_UNVERIFIED" and NEVER downgraded to a healthy
            #     value later in this call.
            #   * NO new SL is placed anywhere in this method (single path).
            #   * A single market-sell follows for unified accounting; the
            #     CANCEL_UNVERIFIED marker survives finalization so operators
            #     see the residual/ambiguous SL. Idempotent finalizer keeps
            #     double-sell / double-R impossible.
            if getattr(trade, "sl_order_id", None):
                _sl_id_snapshot = trade.sl_order_id
                try:
                    cancelled = await OrderExecutor.cancel_order_safe(
                        exchange, _sl_id_snapshot, trade.symbol
                    )
                    if cancelled is True:
                        # CONFIRMED cancel — only now is it safe to clear the id.
                        trade.sl_order_id = None
                    else:
                        # v4.0.6 FIX D + FIX #2 — unverified. DO NOT clear id,
                        # DO NOT re-place, DO NOT flip health to healthy.
                        sl_cancel_unverified = True
                        trade.sl_health_state = "CANCEL_UNVERIFIED"
                        trade.sl_failure_reason = \
                            f"emergency_close_cancel_unverified:{reason}"
                        STATS["emergency_sl_cancel_unverified"] = \
                            STATS.get("emergency_sl_cancel_unverified", 0) + 1
                        logger.critical(
                            f"[EmergencyClose] {trade.symbol} SL CANCEL UNVERIFIED "
                            f"(id={_sl_id_snapshot}); NOT clearing id, NOT re-placing SL; "
                            f"proceeding to market-sell for accounting."
                        )
                except Exception as ce:
                    # Exception path → unverified (fail-closed on state).
                    sl_cancel_unverified = True
                    trade.sl_health_state = "CANCEL_UNVERIFIED"
                    trade.sl_failure_reason = \
                        f"emergency_close_cancel_exception:{ce}"
                    STATS["emergency_sl_cancel_unverified"] = \
                        STATS.get("emergency_sl_cancel_unverified", 0) + 1
                    logger.warning(f"[EmergencyClose] SL cancel err {trade.symbol}: {ce}")

            # CRITICAL V4.1.1 safety correction:
            # An unverified SL cancellation means we cannot prove that a live
            # exchange stop no longer exists. Selling the full residual anyway
            # can create a double-sell if that stop later triggers. Keep the
            # trade owned, block NEW entries, and retry verification on the next
            # PositionManager tick. If the order is already terminal/filled,
            # SLHealthAuditor will own the normal finalization path.
            if sl_cancel_unverified:
                live_entries_block(
                    f"sl_cancel_unverified_{trade.symbol}",
                    where="OrderExecutor.emergency_close",
                )
                trade.sl_health_state = "CANCEL_UNVERIFIED"
                trade.status = "sl_unverified"
                STATS["emergency_close_deferred_sl_cancel_unverified"] =                     STATS.get("emergency_close_deferred_sl_cancel_unverified", 0) + 1
                logger.critical(
                    f"[EmergencyClose] {trade.symbol}: DEFERRED market-sell because "
                    "SL cancellation is UNVERIFIED; residual remains owned and "
                    "entry submissions are blocked until SL state is proven."
                )
                return False

            # v4.5.71: exit authority was already checked before SL mutation.
            qty = trade.remaining_position or trade.position_size_asset
            sell_px_for_finalize = exit_px  # may be None → finalizer will fallback

            if qty <= 0:
                trade.status = "emergency_closed"
                # v4.0.6 FIX D — preserve CANCEL_UNVERIFIED if it was raised.
                if not sl_cancel_unverified:
                    trade.sl_health_state = "EMERGENCY_CLOSED"
                # v4.0.4 PATCH S — still finalize so ACTIVE_TRADES is cleaned & R recorded
                try:
                    await _finalize_and_record_r(
                        trade, exit_reason=f"emergency_close:{reason}",
                        exit_px=sell_px_for_finalize
                    )
                except Exception as fe:
                    logger.error(f"[EmergencyClose] finalize suppressed {trade.symbol}: {fe}")
                return True

            # Precision-preflight on emergency sell as well (fail-soft: use raw qty on error)
            qty_n, _, prec_err = OrderExecutor._normalize_qty_price(
                exchange, trade.symbol, qty, None
            )
            use_qty = qty_n if (qty_n is not None and not prec_err) else qty
            # v4.0.11 R6 — STOPLESS_EXPOSURE guard. If the market-sell RAISES
            # AFTER we have verified-cancelled the SL, the position is now
            # UNPROTECTED and unaccounted. We must (a) NOT declare the trade
            # closed, (b) leave it in ACTIVE_TRADES so PositionManager keeps
            # retrying, (c) declare stopless_exposure so operators see it,
            # and (d) raise LIVE_ENTRIES_BLOCKED so no NEW entry can be
            # issued while an unprotected residual is on the books. This is
            # a strict addition to the existing except handler below — no
            # new layer, no rollback attempt, just an explicit declaration.
            try:
                sell_res = await _v572_submit_market_sell_authorized(
                    exchange, trade, use_qty,
                    float(exit_px or trade.last_mark_price or trade.entry or 0.0),
                    reason=str(reason), stage="emergency_sell"
                )
                if str(getattr(trade, "last_exit_authority", "")) == "SAFETY_HAZARD":
                    trade.safety_hazard_sell_reconciled = True
            except Exception as _sell_err:
                # v4.5.53 — a market-sell timeout/transport error is not proof
                # that the sell was rejected. Reconcile the venue before
                # declaring STOPLESS_EXPOSURE and blocking the whole entry side.
                try:
                    _recovered_sell = await _v553_reconcile_emergency_sell(
                        exchange, trade, use_qty,
                        float(exit_px or trade.last_mark_price or trade.entry or 0.0),
                        "emergency_close"
                    )
                except Exception:
                    _recovered_sell = None

                if _recovered_sell is not None:
                    _rq = float(_recovered_sell.get("_v553_fill_qty") or use_qty)
                    _rpx = float(_recovered_sell.get("_v553_fill_px") or exit_px or trade.entry)
                    trade.remaining_position = max(0.0, float(trade.remaining_position or 0.0) - _rq)
                    trade.total_sold_qty = float(trade.total_sold_qty or 0.0) + _rq
                    if str(getattr(trade, "last_exit_authority", "")) == "SAFETY_HAZARD":
                        trade.safety_hazard_sell_reconciled = True
                    trade.status = "emergency_closed"
                    trade.sl_health_state = "EMERGENCY_CLOSED"
                    try:
                        await _finalize_and_record_r(
                            trade,
                            exit_reason=f"emergency_close_reconciled:{reason}",
                            exit_px=_rpx,
                        )
                    except Exception as _fe:
                        logger.error(f"[V553-RECOVER] finalize suppressed {trade.symbol}: {_fe}")
                    live_entries_hard_recover_after_verified_exit(
                        trade.symbol, residual_qty=trade.remaining_position,
                        exit_verified=True, where="OrderExecutor.emergency_close.reconciled_sell"
                    )
                    return True

                STATS["emergency_sell_failed"] = \
                    STATS.get("emergency_sell_failed", 0) + 1
                trade.sl_health_state = (
                    "STOPLESS_EXPOSURE" if not sl_cancel_unverified
                    else "CANCEL_UNVERIFIED_AND_SELL_FAILED"
                )
                trade.sl_failure_reason = f"emergency_sell_failed:{_sell_err}"
                try:
                    live_entries_block(
                        f"stopless_exposure_{trade.symbol}",
                        where="OrderExecutor.emergency_close",
                    )
                except Exception:
                    _v647_record_suppressed_exception()
                logger.critical(
                    f"[EmergencyClose] {trade.symbol} MARKET-SELL FAILED "
                    f"after SL cancel={'unverified' if sl_cancel_unverified else 'verified'} "
                    f"— STOPLESS_EXPOSURE declared, LIVE_ENTRIES_BLOCKED raised, "
                    f"trade retained in ACTIVE_TRADES for retry. err={_sell_err}"
                )
                # Fail-closed: do NOT finalize, do NOT pop ACTIVE_TRADES, do
                # NOT record R. The next PositionManager tick will re-enter
                # SLHealth/emergency logic and try again.
                return False
            # Try to capture actual fill price for accurate R accounting
            try:
                if sell_px_for_finalize is None and isinstance(sell_res, dict):
                    _px = float(sell_res.get("average") or sell_res.get("price") or 0.0)
                    if _px > 0:
                        sell_px_for_finalize = _px
            except Exception:
                _v647_record_suppressed_exception()

            trade.remaining_position = 0.0
            trade.total_sold_qty = float(trade.total_sold_qty or 0.0) + float(use_qty)
            trade.status = "emergency_closed"
            # v4.0.6 FIX D + FIX #2 — keep the CANCEL_UNVERIFIED marker visible
            # if the SL cancel could not be confirmed; otherwise mark
            # EMERGENCY_CLOSED. Under CANCEL_UNVERIFIED we do NOT re-place any
            # SL and do NOT run any additional cleanup layer here — the state
            # itself is the operator-visible signal (diagnostic only).
            if not sl_cancel_unverified:
                trade.sl_health_state = "EMERGENCY_CLOSED"
            else:
                logger.critical(
                    f"[EmergencyClose] {trade.symbol} finalized with SL state=CANCEL_UNVERIFIED "
                    f"(residual SL id={trade.sl_order_id})"
                )
            logger.critical(f"[EmergencyClose] {trade.symbol} reason={reason}")

            # v4.0.4 PATCH S — unified finalization (idempotent).
            # NOTE: _finalize_and_record_r is guarded by _FINALIZED_TRADE_IDS,
            # so this call is safe even if a caller already invoked it.
            try:
                await _finalize_and_record_r(
                    trade, exit_reason=f"emergency_close:{reason}",
                    exit_px=sell_px_for_finalize
                )
            except Exception as fe:
                logger.error(f"[EmergencyClose] finalize suppressed {trade.symbol}: {fe}")
            # v4.0.6 FIX #2 — diagnostic-only warning if a residual SL id is
            # still attached after finalization (audit / manual reconcile).
            # Purely advisory: NO extra cancel attempt, NO re-place, NO logic.
            try:
                if sl_cancel_unverified and getattr(trade, "sl_order_id", None):
                    logger.warning(
                        f"[EmergencyClose:AUDIT] {trade.symbol} residual SL id="
                        f"{trade.sl_order_id} left in CANCEL_UNVERIFIED state; "
                        "manual reconcile recommended."
                    )
            except Exception as _audit_exc:
                _v593_note_suppressed_exception("emergency_close.audit_log", _audit_exc)
            # v4.5.53 — once the exact emergency/protection exit is proven
            # filled and the trade has been removed, a prior same-symbol
            # stopless/protection block can be cleared explicitly.
            try:
                live_entries_hard_recover_after_verified_exit(
                    trade.symbol,
                    residual_qty=float(getattr(trade, "remaining_position", 0.0) or 0.0),
                    exit_verified=True,
                    where="OrderExecutor.emergency_close.finalized",
                )
            except Exception as _recover_exc:
                _v593_note_suppressed_exception("emergency_close.verified_exit_recovery", _recover_exc)
            return True
        except Exception as e:
            logger.critical(f"[EmergencyClose] FAILED {trade.symbol}: {e}")
            return False


# =============================================================================
#  v4.0.3 PATCH G — CENTRAL FINALIZATION (weighted R + ACTIVE_TRADES pop)
#  Every exit path (TP2-full, SL_HIT, emergency_close, time_based_exit) MUST
#  route through here so DailyCircuitBreaker sees the realized R and no ghost
#  trade is left in ACTIVE_TRADES.
# =============================================================================

_FINALIZED_TRADE_IDS: "set" = set()  # bounded via periodic prune below


async def _finalize_and_record_r(trade: "TradeState",
                                  exit_reason: str,
                                  exit_px: Optional[float] = None) -> float:
    """Compute weighted realized R across partial fills + optional residual
    exit at exit_px, add it to DailyCircuitBreaker, pop trade from
    ACTIVE_TRADES, and DB-snapshot the final state.
    Idempotent: safe to call multiple times per trade (guards via trace_id).
    Returns the weighted R contributed (0.0 if already finalized).
    """
    try:
        tid = getattr(trade, "trace_id", None) or f"{trade.symbol}:{id(trade)}"
        if tid in _FINALIZED_TRADE_IDS:
            return 0.0
        _FINALIZED_TRADE_IDS.add(tid)
        try:
            # v4.2.2 FIX — offloaded to a worker thread (non-blocking).
            await DBManager.asave_finalized_trade_id(tid, getattr(trade, "symbol", ""), exit_reason)
        except Exception as _e:
            logger.debug(f"[Finalize] persist finalized id suppressed: {_e}")
        # Bound the set (best-effort)
        if len(_FINALIZED_TRADE_IDS) > 2000:
            for _old in list(_FINALIZED_TRADE_IDS)[:1000]:
                _FINALIZED_TRADE_IDS.discard(_old)

        risk_unit = max(trade.entry - trade.original_sl, 1e-9)
        original_qty = float(trade.position_size_asset or 0.0)
        weighted_r = 0.0
        contributed_qty = 0.0
        if original_qty > 0:
            for rec in trade.partial_tp_records:
                try:
                    rec_qty = float(rec.get("qty", 0.0))
                    rec_px = float(rec.get("px", 0.0))
                    if rec_qty <= 0 or rec_px <= 0:
                        continue
                    wr = (rec_px - trade.entry) / risk_unit
                    w = rec_qty / original_qty
                    weighted_r += wr * w
                    contributed_qty += rec_qty
                except Exception:
                    continue
            # Any residual quantity (not yet in partial_tp_records) exits at exit_px.
            residual = max(0.0, original_qty - contributed_qty)
            if residual > 0 and exit_px and exit_px > 0:
                wr = (float(exit_px) - trade.entry) / risk_unit
                w = residual / original_qty
                weighted_r += wr * w
        else:
            if exit_px and exit_px > 0:
                weighted_r = (float(exit_px) - trade.entry) / risk_unit

        try:
            _outcome_mode = "PAPER" if bool(getattr(trade, "is_paper", False)) else "LIVE"
            _outcome_style = str(getattr(trade, "strategy_style", "SCALP") or "SCALP").upper()
            _outcome_strategy = str(getattr(trade, "strategy_mode", "") or getattr(trade, "signal_family", "UNKNOWN") or "UNKNOWN").upper()
            _outcome_tf = str(getattr(trade, "timeframe_profile", "") or "UNKNOWN").upper()
            STATS[f"v702_trade_closed_style.{_outcome_mode}.{_outcome_style}.count"] = int(
                STATS.get(f"v702_trade_closed_style.{_outcome_mode}.{_outcome_style}.count", 0) or 0
            ) + 1
            STATS[f"v702_trade_closed_style.{_outcome_mode}.{_outcome_style}.sum_r"] = float(
                STATS.get(f"v702_trade_closed_style.{_outcome_mode}.{_outcome_style}.sum_r", 0.0) or 0.0
            ) + float(weighted_r)
            STATS[f"v702_trade_closed_mode.{_outcome_mode}.{_outcome_strategy}.count"] = int(
                STATS.get(f"v702_trade_closed_mode.{_outcome_mode}.{_outcome_strategy}.count", 0) or 0
            ) + 1
            STATS[f"v702_trade_closed_mode.{_outcome_mode}.{_outcome_strategy}.sum_r"] = float(
                STATS.get(f"v702_trade_closed_mode.{_outcome_mode}.{_outcome_strategy}.sum_r", 0.0) or 0.0
            ) + float(weighted_r)
            logger.info(
                "[STRATEGY-OUTCOME] mode=%s execution=%s style=%s tf=%s realized_r=%+.3f trace=%s exit_reason=%s",
                _outcome_strategy, _outcome_mode, _outcome_style, _outcome_tf, float(weighted_r), str(tid), str(exit_reason or "unknown")
            )
        except Exception as _outcome_obs_exc:
            logger.warning("[STRATEGY-OUTCOME-OBS-FAILED] trace=%s error=%s:%s", str(tid), type(_outcome_obs_exc).__name__, str(_outcome_obs_exc)[:160])
        try:
            DailyCircuitBreaker.add_realized_r(weighted_r)
        except Exception as e:
            logger.warning(f"[Finalize] add_realized_r suppressed: {e}")
        # v4.2.2 ENHANCEMENT (4) — feed the per-symbol expectancy ledger so a
        # symbol with a clearly negative expectancy is cooled down (bounded).
        try:
            SymbolExpectancyCooldown.record(trade.symbol, weighted_r)
        except Exception:
            _v647_record_suppressed_exception()
        # v4.4 persistent strategy × regime × session × style expectancy.
        try:
            StrategyPerformanceMemory.record(
                getattr(trade,"strategy_mode","") or getattr(trade,"signal_family","UNKNOWN"),
                getattr(trade,"strategy_regime","UNKNOWN"),
                getattr(trade,"strategy_session_bucket",StrategyPerformanceMemory.session_bucket()),
                getattr(trade,"strategy_style","SCALP"), weighted_r, symbol=trade.symbol)
        except Exception as _pexp:
            logger.debug(f"[Finalize] strategy expectancy suppressed: {_pexp}")

        trade.total_realized_r = float(weighted_r)
        trade.remaining_position = 0.0
        try:
            rc = dict(getattr(trade, "rescue_context", {}) or {})
            lane = str(rc.get("lane", "ordinary") or "ordinary")
            STATS[f"expectancy_lane_{lane}_trades"] = int(STATS.get(f"expectancy_lane_{lane}_trades", 0) or 0) + 1
            STATS[f"expectancy_lane_{lane}_sum_r"] = float(STATS.get(f"expectancy_lane_{lane}_sum_r", 0.0) or 0.0) + float(weighted_r)
            bucket = "rescue" if lane != "ordinary" else "ordinary"
            STATS[f"expectancy_{bucket}_trades"] = int(STATS.get(f"expectancy_{bucket}_trades", 0) or 0) + 1
            STATS[f"expectancy_{bucket}_sum_r"] = float(STATS.get(f"expectancy_{bucket}_sum_r", 0.0) or 0.0) + float(weighted_r)
            rc.update({"realized_r": float(weighted_r), "exit_reason": str(exit_reason or ""), "finalized_at": WALL_NOW()})
            trade.rescue_context = rc
        except Exception as _rescue_exp_exc:
            try: _v593_note_suppressed_exception("finalize.rescue_expectancy", _rescue_exp_exc)
            except Exception: logger.warning(f"[Finalize] rescue expectancy observation failed: {_rescue_exp_exc}")
        if trade.status not in ("emergency_closed", "sl_hit"):
            trade.status = "finalized"
        try:
            LifecycleTrace.record(tid, "FINALIZED",
                                  {"weighted_r": weighted_r,
                                   "exit_reason": exit_reason,
                                   "exit_px": exit_px})
        except Exception:
            _v647_record_suppressed_exception()
        try:
            ACTIVE_TRADES.pop(trade.symbol, None)
        except Exception:
            _v647_record_suppressed_exception()
        # v4.0.7 TWEAK — arm re-entry cooldown on exit. Prevents fast churn
        # on the same symbol immediately after a close (SL / TP / emergency).
        # v4.0.9 DS-4 — dynamic per-exit-reason cooldown: writes a tuple
        # (armed_ts, cd_sec) so the gate can honour per-reason durations.
        # Backward-compat: legacy float timestamps remain supported.
        try:
            _now_arm = MONO_NOW()
            if bool(CONFIG.get("REENTRY_COOLDOWN_DYNAMIC_ENABLE", True)):
                _table = CONFIG.get("REENTRY_COOLDOWN_BY_REASON", {}) or {}
                _reason_root = str(exit_reason or "").split(":", 1)[0].strip().lower()
                _cd_sec = None
                for _k, _v in _table.items():
                    try:
                        if str(_k).strip().lower() == _reason_root:
                            _cd_sec = float(_v)
                            break
                    except Exception:
                        continue
                if _cd_sec is None:
                    _cd_sec = float(_table.get("default",
                                               CONFIG.get("REENTRY_COOLDOWN_SEC", 1800)))
                COOLDOWNS["reentry"][trade.symbol] = (_now_arm, float(_cd_sec))
                logger.info(
                    f"[Reentry:DS-4] {trade.symbol} armed cooldown={_cd_sec:.0f}s "
                    f"(exit_reason={exit_reason})"
                )
            else:
                COOLDOWNS["reentry"][trade.symbol] = _now_arm
        except Exception as _cd_e:
            logger.debug(f"[Reentry:DS-4] arm suppressed {trade.symbol}: {_cd_e}")
        try:
            # v4.2.2 FIX — offloaded to a worker thread (non-blocking).
            await DBManager.asave_trade_snapshot(trade)
        except Exception:
            _v647_record_suppressed_exception()
        logger.info(
            f"[Finalize] {trade.symbol} reason={exit_reason} "
            f"weighted_r={weighted_r:+.3f} exit_px={exit_px}"
        )
        try:
            _exit_reason_text = str(exit_reason or "").strip()
            _exit_reason_norm = _exit_reason_text.lower().replace("-", "_")
            if "software_sl_breach" in _exit_reason_norm or "stop_loss" in _exit_reason_norm or _exit_reason_norm in {"sl_hit", "stoploss", "stop_loss_hit"}:
                _exit_event = "STOP LOSS HIT — SOFTWARE AUTO-SELL" if "software_sl_breach" in _exit_reason_norm else "STOP LOSS HIT"
            else:
                _exit_event = f"TRADE FINALIZED — {_exit_reason_text.upper()}"
            await OpportunityTelegramNotifier.notify_exit_event(
                trade, _exit_event,
                fill_px=float(exit_px) if exit_px else None,
                remaining=trade.remaining_position,pnl_r=weighted_r,
                extra=f"Exit reason={_exit_reason_text or 'unknown'} | Total realized={weighted_r:+.3f}R"
            )
        except Exception:
            _v647_record_suppressed_exception()
        return weighted_r
    except Exception as e:
        logger.error(f"[Finalize] {getattr(trade,'symbol','?')} err: {e}")
        return 0.0


# =============================================================================
#  SECTION 28 — EXIT MANAGER (TP1/TP2, BE, Staircase, Trailing, Runner)
# =============================================================================

class ExitManager:

    @staticmethod
    async def move_to_break_even(exchange, trade: TradeState) -> bool:
        """After TP1: cancel old SL (verify!) then place new SL slightly above
        entry to cover roundtrip fees (v4.0.3 PATCH K).
        Previously SL was placed EXACTLY at entry, which turned a 'break-even'
        exit into a small net loss equal to roundtrip fees.

        v4.0.6 PATCH #1 — Decisive failure semantics. If cancel is verified but
        `place_sl` fails, `trade.current_sl` is restored to its previous value
        before returning False. The caller MUST treat False as a real
        protection failure (no silent fall-open) and act (emergency_close /
        halt further exit logic on this tick).
        """
        if not CONFIG.get("V4_SL_CANCEL_VERIFY", True):
            logger.warning("[BE] SL_CANCEL_VERIFY disabled — proceeding without verify (RISK)")
        if trade.sl_order_id:
            cancelled = await OrderExecutor.cancel_order_safe(
                exchange, trade.sl_order_id, trade.symbol)
            if not cancelled:
                # Keep current_sl/status at the proven old state. Replacing now
                # could create two sell stops; old exchange SL remains the only
                # assumed protection and the marker makes ambiguity observable.
                trade.sl_health_state = "CANCEL_UNVERIFIED"
                trade.sl_failure_reason = "be_move_cancel_unverified"
                logger.warning(
                    f"[BE] {trade.symbol}: old SL cancel UNVERIFIED (id={trade.sl_order_id}); "
                    "state preserved at old SL; no BE claim/no replacement."
                )
                STATS["sl_cancel_unverified"] = STATS.get("sl_cancel_unverified", 0) + 1
                return False
            trade.sl_order_id = None  # ONLY clear after CONFIRMED cancel
        # Candidate-first mutation: internal state is committed only after
        # verified cancel AND verified replacement (DS-1) succeed.
        prev_sl = trade.current_sl
        prev_cov = trade.sl_covered_qty
        try:
            fee_pct = float(CONFIG.get("TAKER_FEE_PCT", 0.10)) / 100.0
            fee_mult = float(CONFIG.get("ROUNDTRIP_FEE_MULT", 2.0))
            candidate_sl = trade.entry * (1.0 + fee_pct * fee_mult)
        except Exception:
            candidate_sl = trade.entry
        ok, oid = await OrderExecutor.place_sl(exchange, trade, candidate_sl)
        if ok:
            trade.current_sl = candidate_sl
            trade.status = "be_moved"
            try:
                trade.be_protection_price = float(candidate_sl)
                trade.be_fee_covered = True
            except Exception:
                _v647_record_suppressed_exception()
            logger.info(
                f"[BE] {trade.symbol}: verified fee-covered BE SL={candidate_sl:.10f} "
                f"entry={trade.entry:.10f}"
            )
            await OpportunityTelegramNotifier.notify_exit_event(
                trade, "SL MOVED TO FEE-COVERED BE",
                fill_px=trade.last_partial_exit_price or None,
                remaining=trade.remaining_position,
                extra=f"Verified SL={candidate_sl:.10f}"
            )
            return True
        # v4.0.6 PATCH #1 — place_sl failed AFTER a verified cancel. The trade
        # is now UNPROTECTED. Restore the previous SL fields so downstream
        # accounting/audits still see the last known-good numbers, mark the
        # health state, and return False so the caller can escalate (fail-
        # closed emergency_close).
        trade.current_sl = prev_sl
        trade.sl_covered_qty = prev_cov
        try:
            trade.sl_health_state = "BE_REPLACE_FAILED"
            trade.sl_failure_reason = "move_to_break_even_place_failed"
        except Exception:
            _v647_record_suppressed_exception()
        STATS["be_replace_failed"] = STATS.get("be_replace_failed", 0) + 1
        logger.critical(
            f"[BE] {trade.symbol}: place_sl FAILED after verified cancel — "
            f"position UNPROTECTED; caller must fail-close."
        )
        return False

    @staticmethod
    def maybe_advance_staircase(trade: TradeState, current_price: float) -> Optional[float]:
        """Returns candidate new SL if a milestone was hit, else None.

        v4.0.6 FIX E — This function now returns a CANDIDATE only. It does
        NOT mutate `trade.staircase_level_hit` and does NOT touch
        `trade.current_sl`. The caller (PositionManager.tick) is responsible
        for committing both fields ONLY after a successful cancel+replace of
        the exchange SL. Prevents silent desync when the SL replace fails.
        """
        if not bool(CONFIG["ENABLE_STAIRCASE_LOCK"]):
            return None
        risk_unit = trade.entry - trade.original_sl
        if risk_unit <= 0:
            return None
        r_multiple = (current_price - trade.entry) / risk_unit
        levels = list(CONFIG["STAIRCASE_LOCK_LEVELS"])
        cushion = float(CONFIG["STAIRCASE_LOCK_CUSHION_R"])
        new_level_hit = -1
        for i, lvl in enumerate(levels):
            if r_multiple >= lvl:
                new_level_hit = i
        if new_level_hit > trade.staircase_level_hit:
            # v4.0.6 FIX E — do NOT promote staircase_level_hit here; the
            # caller commits it after a verified cancel/replace of the SL.
            new_sl_r = levels[new_level_hit] - cushion
            candidate_sl = trade.entry + new_sl_r * risk_unit
            if candidate_sl > trade.current_sl:
                return candidate_sl
        return None

    @staticmethod
    def compute_staircase_target_level(trade: TradeState, current_price: float) -> int:
        """v4.0.6 FIX E helper — returns the target staircase level index for
        the current price. Used by the caller (PositionManager.tick) to commit
        `staircase_level_hit` ONLY after a successful SL cancel+replace.
        """
        if not bool(CONFIG["ENABLE_STAIRCASE_LOCK"]):
            return trade.staircase_level_hit
        risk_unit = trade.entry - trade.original_sl
        if risk_unit <= 0:
            return trade.staircase_level_hit
        r_multiple = (current_price - trade.entry) / risk_unit
        levels = list(CONFIG["STAIRCASE_LOCK_LEVELS"])
        target = trade.staircase_level_hit
        for i, lvl in enumerate(levels):
            if r_multiple >= lvl:
                target = i
        return target

    @staticmethod
    def maybe_activate_runner(trade: TradeState, current_price: float) -> bool:
        if not bool(CONFIG["ENABLE_RUNNER_MODE"]) or trade.runner_active:
            return False
        risk_unit = trade.entry - trade.original_sl
        if risk_unit <= 0:
            return False
        r = (current_price - trade.entry) / risk_unit
        # v4.5.27: use the trade's canonical strategy-specific TP3 R when
        # available; falling back to global TP3_RR would strand low-target
        # profiles (e.g. SCOUT 3.0R / trend 3.8R) below the runner trigger.
        profile = getattr(trade, "exit_profile", {}) or {}
        try:
            tp3_rr = float(profile.get("tp3_rr", CONFIG["TP3_RR"]))
        except Exception:
            tp3_rr = float(CONFIG["TP3_RR"])
        if r >= tp3_rr:
            trade.runner_active = True
            trade.peak_r = r
            trade.status = "runner"
            try:
                trade.runner_trigger_r = float(tp3_rr)
            except Exception:
                _v647_record_suppressed_exception()
            logger.info(f"[Runner] {trade.symbol} activated at r={r:.2f} trigger={tp3_rr:.2f}R")
            return True
        return False

    @staticmethod
    async def arm_runner_protection(exchange, trade: TradeState, current_price: float) -> bool:
        """At TP3: keep runner open but guarantee a bounded minimum R-lock."""
        try:
            if not bool(CONFIG.get("RUNNER_ARM_AT_TP3_ENABLE",True)):
                return True
            if not bool(CONFIG.get("TP3_RUNNER_LOCK_ENABLE",True)):
                return True
            risk_unit=max(float(trade.entry)-float(trade.original_sl),1e-12)
            target=max(float(trade.current_sl),
                       float(trade.entry)+float(CONFIG.get("TP3_RUNNER_LOCK_R",3.0))*risk_unit)
            if target <= float(trade.current_sl)+1e-12:
                return True
            async with HandoffOwnership.lock_for(trade.symbol):
                if trade.sl_order_id:
                    ok_cancel=await OrderExecutor.cancel_order_safe(exchange,trade.sl_order_id,trade.symbol)
                    if not ok_cancel:
                        trade.sl_health_state="CANCEL_UNVERIFIED"
                        trade.sl_failure_reason="tp3_runner_lock_cancel_unverified"
                        return False
                    trade.sl_order_id=None
                ok_place,_=await OrderExecutor.place_sl(exchange,trade,target)
                if not ok_place:
                    trade.sl_failure_reason="tp3_runner_lock_place_failed"
                    return False
                trade.current_sl=target
            return True
        except Exception as exc:
            trade.sl_failure_reason=f"tp3_runner_lock_error:{exc}"
            return False

    @staticmethod
    def compute_trailing_sl(trade: TradeState, current_price: float, atr: float) -> Optional[float]:
        risk_unit = trade.entry - trade.original_sl
        if risk_unit <= 0:
            return None
        r = (current_price - trade.entry) / risk_unit
        if r < float(CONFIG["TRAIL_ACTIVATION_R"]):
            return None
        profile = getattr(trade, "exit_profile", {}) or {}
        try:
            profile_trail = float(profile.get("trail_atr", 0.0) or 0.0)
        except Exception:
            profile_trail = 0.0
        if trade.runner_active:
            # Runner stays on the dedicated post-TP3 trail, but never below
            # the strategy's own trail envelope when that profile is tighter.
            base_after_tp3 = float(CONFIG["TRAIL_ATR_MULT_AFTER_TP3"])
            mult = max(base_after_tp3, profile_trail) if profile_trail > 0 else base_after_tp3
        else:
            mult = profile_trail if profile_trail > 0 else float(CONFIG["TRAIL_ATR_MULTIPLIER"])
        new_sl = current_price - mult * atr
        if new_sl > trade.current_sl:
            return new_sl
        return None


# =============================================================================
#  SECTION 29 — SL HEALTH + SOFTWARE FALLBACK WATCHDOG
# =============================================================================


async def _v560_arm_software_sl(trade: TradeState, reason: str = "") -> bool:
    """Idempotently arm automatic software SL; never submits a SELL."""
    try:
        qty = float(getattr(trade, "remaining_position", 0.0) or 0.0)
        entry = float(getattr(trade, "entry", 0.0) or 0.0)
        sl = float(
            getattr(trade, "current_sl", 0.0)
            or getattr(trade, "original_sl", 0.0)
            or 0.0
        )
        if (not math.isfinite(qty) or not math.isfinite(entry) or not math.isfinite(sl)
                or qty <= 0 or entry <= 0 or sl <= 0):
            logger.critical(
                f"[V564-SL] {getattr(trade,'symbol','?')} cannot arm software SL "
                f"qty={qty} entry={entry} sl={sl}"
            )
            return False
        # current_sl is a live protective stop, not necessarily the original
        # entry stop. A breakeven or profit-lock stop at/above entry is valid.
        # If it is already breached, still arm tracking so the next PM tick can
        # execute the safety path rather than leaving the position unprotected.

        already = bool(getattr(trade, "software_sl_active", False))
        trade.software_sl_active = True
        if not float(getattr(trade, "software_sl_activated_ts", 0.0) or 0.0):
            trade.software_sl_activated_ts = MONO_NOW()

        trade.sl_health_state = "SOFTWARE_SL_ACTIVE"
        trade.sl_monitor_mode = "AUTO_SELL"
        trade.sl_failure_reason = str(reason or "native_sl_unavailable")

        # Crucial: do not count/re-arm an already active software stop.
        if already:
            return True

        try:
            SoftwareSLTelemetry.register_activation(
                trade.symbol,
                reason=str(reason or "native_sl_unavailable"),
            )
        except Exception:
            _v647_record_suppressed_exception()

        trade.sl_failover_count = int(
            getattr(trade, "sl_failover_count", 0) or 0
        ) + 1
        STATS["v560_software_sl_armed"] = int(
            STATS.get("v560_software_sl_armed", 0) or 0
        ) + 1

        logger.critical(
            f"[V564-SL] {trade.symbol} AUTOMATIC SOFTWARE SL ARMED "
            f"entry={entry:.10g} sl={sl:.10g} qty={qty:.10f} "
            f"reason={reason or 'native_unavailable'}"
        )
        return True
    except Exception as exc:
        logger.critical(
            f"[V564-SL] arm failed {getattr(trade,'symbol','?')}: {exc}"
        )
        return False


async def _v564_notify_sl_failover_once(
    trade: TradeState,
    reason: str,
    previous_sl: float = 0.0,
) -> None:
    """Notify only on a new failover reason/state transition, with cooldown."""
    if not bool(CONFIG.get("V564_SL_FAILOVER_NOTIFY_ENABLE", True)):
        return
    try:
        now = MONO_NOW()
        rs = str(reason or "sl_replace_failed")
        last_reason = str(getattr(trade, "sl_failover_last_reason", "") or "")
        last_ts = float(getattr(trade, "sl_failover_last_notify_ts", 0.0) or 0.0)
        cooldown = max(
            1.0,
            float(CONFIG.get("V564_SL_FAILOVER_NOTIFY_COOLDOWN_SEC", 900.0)),
        )

        if (
            bool(getattr(trade, "sl_failover_notified", False))
            and last_reason == rs
        ):
            return
        if last_ts > 0 and (now - last_ts) < cooldown:
            return

        trade.sl_failover_notified = True
        trade.sl_failover_last_reason = rs
        trade.sl_failover_last_notify_ts = now

        STATS["v564_sl_failover_notifications"] = int(
            STATS.get("v564_sl_failover_notifications", 0) or 0
        ) + 1

        msg = (
            f"🟠 <b>SL FAILOVER ACTIVE</b> {trade.symbol}\n"
            f"Model SL: {float(trade.current_sl):.10g}\n"
            f"Reason: {rs}\n"
            "Automatic software SL is active; native SL retry loop is suppressed."
        )
        try:
            prev = float(previous_sl or 0.0)
            if prev > 0:
                msg += f"\nPrevious SL: {prev:.10g}"
        except Exception:
            _v647_record_suppressed_exception()
        await TelegramDispatcher.enqueue(msg)
    except Exception as exc:
        logger.debug(
            f"[V564-SL] failover notify suppressed "
            f"{getattr(trade,'symbol','?')}: {exc}"
        )


class SLHealthAuditor:

    @staticmethod
    async def verify(exchange, trade: TradeState) -> str:
        """Returns SL health state; escalates to emergency_close if MISSING.
        v4.0.3 PATCH J: SL 'closed' / 'filled' status is now recognised as an
        SL_HIT event — the trade is finalized (weighted R contributed to the
        DailyCircuitBreaker) instead of trying to replace an SL on a position
        that no longer exists.
        """
        _policy = str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper()
        if bool(getattr(trade, "target_only_mode", False)) and _policy in {"TARGET_ONLY", "SOFTWARE_ALERT"}:
            return "target_only"
        if trade.software_sl_active:
            return "software_sl_active"
        if not trade.sl_order_id:
            trade.sl_health_state = "MISSING"
            trade.sl_verify_consec_unverified = 0
            # v4.5.60: missing native SL is NOT a SELL trigger. Arm the
            # automatic software SL and keep the filled position alive.
            if (
                str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() == "HYBRID_AUTO"
                and bool(CONFIG.get("V560_AUTO_SL_ENABLE", True))
                and await _v560_arm_software_sl(trade, "sl_missing_no_id")
            ):
                return "SOFTWARE_SL_ACTIVE"
            if str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() in {"TARGET_ONLY", "SOFTWARE_ALERT"}:
                await _v559_activate_sl_failure_policy(
                    exchange, trade, "sl_missing_no_id"
                )
                return "TARGET_ONLY"
            await OrderExecutor.emergency_close(exchange, trade, "sl_missing_no_id")
            return "MISSING"
        try:
            o = await safe_api_call(
                "fetch_order_sl",
                lambda: exchange.fetch_order(trade.sl_order_id, trade.symbol),
                retry_safe=True,
            )
            status = str(o.get("status") or "").lower()
            if status in ("open", "new"):
                trade.sl_health_state = "CONFIRMED"
                trade.sl_last_verified_ts = MONO_NOW()
                trade.sl_verify_consec_unverified = 0
                return "CONFIRMED"
            # v4.0.3 PATCH J: SL was executed by the exchange — finalize the trade.
            if status in ("closed", "filled"):
                fill_px = None
                try:
                    fill_px = float(o.get("average") or o.get("price") or trade.current_sl)
                except Exception:
                    fill_px = float(trade.current_sl)
                logger.warning(
                    f"[SLHealth] {trade.symbol} SL FILLED @ {fill_px:.6f} — finalizing"
                )
                # v4.0.6 FIX #1 — SL accounting: derive the SL-filled qty from
                # what the SL was actually bound to (remaining_position first,
                # then sl_covered_qty if it is known-fresh). Never fall back
                # to position_size_asset here — it is the ORIGINAL size and
                # after partial exits it overstates the SL fill (bad R math).
                # sl_covered_qty is maintained fresh at every event that
                # rebinds SL: place_sl, TP1 (BE re-place), TP2 (re-place),
                # staircase re-place, and trailing re-place.
                _sl_qty_snapshot = float(getattr(trade, "remaining_position", 0.0) or 0.0)
                if _sl_qty_snapshot <= 0:
                    _sl_qty_snapshot = float(getattr(trade, "sl_covered_qty", 0.0) or 0.0)
                trade.sl_health_state = "CONFIRMED"
                trade.sl_verify_consec_unverified = 0
                trade.status = "sl_hit"
                trade.remaining_position = 0.0
                trade.partial_tp_records.append({
                    "level": "SL", "px": fill_px,
                    "qty": _sl_qty_snapshot,
                    "ts": time.time(), "reason": "sl_hit",
                })
                try:
                    await OpportunityTelegramNotifier.notify_exit_event(
                        trade,"STOP LOSS HIT",fill_px=fill_px,fill_qty=_sl_qty_snapshot,
                        pnl_r=_v526_event_r(trade,fill_px),remaining=0.0,
                        extra="Exchange SL was confirmed as filled."
                    )
                except Exception as _notify_exc:
                    _v593_note_suppressed_exception("sl_health.notify_exit", _notify_exc)
                try:
                    await _finalize_and_record_r(trade, exit_reason="sl_hit",
                                                  exit_px=fill_px)
                except Exception as _e:
                    logger.debug(f"[SLHealth] finalize suppressed: {_e}")
                return "SL_HIT"
            if status in ("canceled", "cancelled", "rejected"):
                logger.warning(f"[SLHealth] {trade.symbol} SL {status} — replacing")
                trade.sl_order_id = None
                ok, _ = await OrderExecutor.place_sl(exchange, trade)
                if ok:
                    trade.sl_verify_consec_unverified = 0
                else:
                    # v4.5.60: SL replacement failure falls back to
                    # automatic software SL under the default hybrid policy.
                    if str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() == "HYBRID_AUTO":
                        await _v560_arm_software_sl(trade, "sl_replace_failed")
                    elif str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() in {"TARGET_ONLY", "SOFTWARE_ALERT"}:
                        await _v559_activate_sl_failure_policy(
                            exchange, trade, "sl_replace_failed"
                        )
                    else:
                        await OrderExecutor.emergency_close(
                            exchange, trade, "sl_replace_failed"
                        )
                return trade.sl_health_state
            return status or "UNKNOWN"
        except Exception as e:
            trade.sl_health_state = "UNVERIFIED"
            trade.sl_failure_reason = str(e)
            trade.sl_verify_consec_unverified = int(getattr(trade, "sl_verify_consec_unverified", 0) or 0) + 1
            if trade.sl_verify_consec_unverified >= int(CONFIG.get("SL_VERIFY_CONSEC_UNVERIFIED_MAX", 3)):
                if (
                    str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() == "HYBRID_AUTO"
                    and bool(CONFIG.get("V560_AUTO_SL_ENABLE", True))
                ):
                    await _v560_arm_software_sl(
                        trade, "sl_verify_consecutive_unverified"
                    )
                    return "SOFTWARE_SL_ACTIVE"
                trade.software_sl_active = True
                trade.software_sl_activated_ts = MONO_NOW()
                SoftwareSLTelemetry.register_activation(
                    trade.symbol,
                    reason="sl_verify_consecutive_unverified",
                )
                logger.warning(
                    f"[SLHealth] {trade.symbol} UNVERIFIED x{trade.sl_verify_consec_unverified} "
                    "— activating software SL fallback"
                )
            return "UNVERIFIED"


# ---- v4.0.2 PATCH B — SoftwareSL telemetry + heartbeat + escalation ------

class SoftwareSLTelemetry:
    """Central bookkeeping for software SL fallback events.
    Escalates the system to LIVE_BLOCKED if activations exceed
    SOFTWARE_SL_ESCALATION_MAX_HITS within SOFTWARE_SL_ESCALATION_WINDOW_SEC.
    Also tracks the last PositionManager tick to serve as a heartbeat proxy;
    a stale heartbeat means the software watchdog cannot be trusted.
    """
    _activations: "deque[float]" = deque(maxlen=200)
    _last_pm_tick_ts: float = 0.0  # monotonic

    @classmethod
    def register_pm_tick(cls) -> None:
        cls._last_pm_tick_ts = MONO_NOW()

    @classmethod
    def heartbeat_age_sec(cls) -> float:
        if cls._last_pm_tick_ts <= 0:
            return float("inf")
        return MONO_NOW() - cls._last_pm_tick_ts

    @classmethod
    def heartbeat_ok(cls) -> bool:
        # v4.0.6 FIX #3 — realistic heartbeat window.
        #   * Default raised (see CONFIG) so a normal scanner cycle over a
        #     modest universe cannot trip false emergency_close.
        #   * A hard floor (SOFTWARE_SL_HEARTBEAT_MIN_FLOOR_SEC) guarantees
        #     the effective threshold is never shorter than the actual
        #     cycle length even if operator sets max_age too low.
        # Protection is NOT disabled: a genuinely wedged PositionManager
        # (no tick for far longer than a full cycle) still trips.
        max_age = float(CONFIG.get("SOFTWARE_SL_HEARTBEAT_MAX_AGE_SEC", 240))
        floor   = float(CONFIG.get("SOFTWARE_SL_HEARTBEAT_MIN_FLOOR_SEC", 90))
        effective = max(max_age, floor)
        return cls.heartbeat_age_sec() <= effective

    @classmethod
    def register_trade_protection_check(cls, trade: Any, current_price: float, *,
                                        healthy: bool, reason: str = "") -> None:
        """Refresh the per-position protection lease only after a valid trade
        protection evaluation, never merely because PositionManager is alive."""
        try:
            now = MONO_NOW()
            trade.protection_lease_ts = now
            trade.protection_lease_state = "HEALTHY" if healthy else "DEGRADED"
            trade.protection_last_price_ts = now if float(current_price or 0.0) > 0 else float(getattr(trade, "protection_last_price_ts", 0.0) or 0.0)
            trade.protection_last_sl_ts = now if float(getattr(trade, "current_sl", 0.0) or 0.0) > 0 else float(getattr(trade, "protection_last_sl_ts", 0.0) or 0.0)
            trade.protection_reconcile_required = not healthy
            trade.protection_reconcile_reason = str(reason or "")[:180] if not healthy else ""
            STATS["v702_protection_checks"] = int(STATS.get("v702_protection_checks",0) or 0) + 1
            if healthy:
                STATS["v702_protection_checks_healthy"] = int(STATS.get("v702_protection_checks_healthy",0) or 0) + 1
            else:
                STATS["v702_protection_checks_degraded"] = int(STATS.get("v702_protection_checks_degraded",0) or 0) + 1
        except Exception as exc:
            _v593_note_suppressed_exception("v702.protection_lease", exc)

    @classmethod
    def protection_lease_age_sec(cls, trade: Any) -> float:
        try:
            ts = float(getattr(trade, "protection_lease_ts", 0.0) or 0.0)
            return float("inf") if ts <= 0 else max(0.0, MONO_NOW() - ts)
        except Exception:
            return float("inf")

    @classmethod
    def protection_lease_ok(cls, trade: Any) -> bool:
        if not bool(getattr(trade, "software_sl_active", False)):
            return True
        limit = max(2.0, float(CONFIG.get("V702_PROTECTION_LEASE_STALE_SEC", 12.0)))
        return cls.protection_lease_age_sec(trade) <= limit and str(getattr(trade,"protection_lease_state","")).upper() == "HEALTHY"

    @classmethod
    def register_activation(cls, symbol: str, reason: str = "") -> None:
        now = MONO_NOW()
        cls._activations.append(now)
        STATS["software_sl_activated"] = STATS.get("software_sl_activated", 0) + 1
        window = float(CONFIG.get("SOFTWARE_SL_ESCALATION_WINDOW_SEC", 900))
        max_hits = int(CONFIG.get("SOFTWARE_SL_ESCALATION_MAX_HITS", 2))
        cutoff = now - window
        recent = [t for t in cls._activations if t >= cutoff]
        logger.warning(
            f"[SoftwareSL] activation {symbol} reason={reason} "
            f"recent={len(recent)}/{max_hits} within {window:.0f}s"
        )
        if len(recent) >= max_hits:
            STATS["software_sl_escalations"] = STATS.get("software_sl_escalations", 0) + 1
            logger.warning(
                f"[SoftwareSL] activation burst {len(recent)}/{max_hits}; "
                "software protection remains valid — no LIVE_BLOCKED escalation"
            )
            if bool(CONFIG.get("V563_SOFTWARE_SL_BURST_HARD_BLOCK_ENABLE", False)):
                live_entries_block(
                    f"software_sl_activation_burst_{len(recent)}hits",
                    where="SoftwareSLTelemetry.register_activation",
                )

    @classmethod
    def register_breach(cls) -> None:
        STATS["software_sl_breach"] = STATS.get("software_sl_breach", 0) + 1

    @classmethod
    def register_timeout(cls) -> None:
        STATS["software_sl_timeout"] = STATS.get("software_sl_timeout", 0) + 1

    @classmethod
    def register_heartbeat_missing(cls) -> None:
        STATS["software_sl_heartbeat_missing"] = \
            STATS.get("software_sl_heartbeat_missing", 0) + 1

    @classmethod
    def snapshot(cls) -> Dict[str, Any]:
        return {
            "activations_total": STATS.get("software_sl_activated", 0),
            "breaches": STATS.get("software_sl_breach", 0),
            "timeouts": STATS.get("software_sl_timeout", 0),
            "heartbeat_missing": STATS.get("software_sl_heartbeat_missing", 0),
            "escalations": STATS.get("software_sl_escalations", 0),
            "last_pm_tick_age_sec": cls.heartbeat_age_sec(),
            "heartbeat_ok": cls.heartbeat_ok(),
        }


def _v570_entry_age_sec(trade: TradeState) -> float:
    """Best-effort monotonic age of the filled position."""
    try:
        ts = float(getattr(trade, "entry_filled_mono_ts", 0.0) or 0.0)
        if ts > 0.0:
            return max(0.0, MONO_NOW() - ts)
    except Exception:
        _v647_record_suppressed_exception()
    try:
        dt = datetime.fromisoformat(str(getattr(trade, "entry_time", "") or ""))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return max(0.0, (datetime.now(timezone.utc) - dt).total_seconds())
    except Exception:
        return float("inf")


def _v570_protection_sell_reason(reason: str) -> bool:
    r = str(reason or "").lower()
    return (r.startswith("software_sl_") or r in {
        "sl_missing_no_id", "sl_replace_failed", "tp1_be_replace_failed",
        "tp2_sl_replace_failed", "tp3_runner_lock_failed",
        "trailing_fresh_place_failed", "tp1_be_replace_failed_reconciled",
        "tp2_sl_replace_failed_reconciled",
    })


def _v571_entry_age_ok(trade: TradeState, guard_sec: Optional[float] = None) -> Tuple[bool, float, float]:
    """Return whether post-fill stabilization has elapsed."""
    age = _v570_entry_age_sec(trade)
    try:
        guard = max(
            0.0,
            float(CONFIG.get("V570_POST_ENTRY_AUTO_SELL_GUARD_SEC", 15.0)
                  if guard_sec is None else guard_sec)
        )
    except Exception:
        guard = 15.0
    return bool(math.isfinite(age) and age >= guard), float(age), float(guard)


def _v571_exit_authority(
    trade: TradeState,
    reason: str,
    exit_px: Optional[float] = None,
    stage: Optional[str] = None,
) -> Tuple[bool, str]:
    """
    Central market-SELL authority.

    Normal exits:
      * TP1
      * TP2
      * SOFTWARE_SL breach

    Explicit safety hazards may use emergency_close only when their reason is
    allow-listed and the operator has left the bounded safety-hazard switch ON.
    All unknown reasons fail closed.
    """
    if not bool(CONFIG.get("V571_EXIT_AUTHORITY_ENABLE", True)):
        return True, "legacy_exit_authority_disabled"

    r = str(reason or "").strip().lower()
    px = float(exit_px or getattr(trade, "last_mark_price", 0.0) or 0.0)
    tol_pct = max(0.0, float(CONFIG.get("V571_TP_TRIGGER_TOLERANCE_PCT", 0.0))) / 100.0

    # v4.5.72 — no normal MARKET SELL without a valid observed price.
    if not math.isfinite(px) or px <= 0.0:
        return False, "exit_price_unverifiable"

    # Any protection/failover path is subject to the post-fill guard, but the
    # guard is checked BEFORE SL cancel / SELL so a blocked request cannot
    # mutate protection first.
    protection_reason = (
        r == "software_sl_breach"
        or r == "structural_invalidation"
        or _v570_protection_sell_reason(r)
        or r.startswith("entry_protection_failed:")
        or r in {
            "tp1_be_replace_failed_reconciled",
            "tp2_sl_replace_failed_reconciled",
            "oversell_guard",
        }
    )
    if protection_reason:
        ok_age, age, guard = _v571_entry_age_ok(trade)
        if not ok_age and r not in {"oversell_guard"}:
            return False, f"post_entry_guard:{age:.2f}s<{guard:.2f}s"

    # V702 R2 structural thesis-failure exit: only an armed, persisted context
    # can authorize this reason, only before TP1, and only while the trigger is
    # materially above the model SL.
    if r == "structural_invalidation":
        if not bool(CONFIG.get("V702_STRUCTURAL_FAILURE_EXIT_ENABLE", True)):
            return False, "structural_invalidation_disabled"
        if not bool(getattr(trade, "structural_invalidation_armed", False)):
            return False, "structural_invalidation_unarmed"
        if bool(getattr(trade, "tp1_exit_completed", False)) or str(getattr(trade, "status", "")) != "entry_filled":
            return False, "structural_invalidation_post_tp1_or_consumed"
        fam = str(getattr(trade, "signal_family", "") or getattr(trade, "strategy_mode", "")).upper()
        allowed = {str(x).upper() for x in CONFIG.get("V702_STRUCTURAL_FAILURE_FAMILIES", ())}
        if fam not in allowed:
            return False, "structural_invalidation_family_not_allowed"
        trigger = float(getattr(trade, "structural_invalidation_trigger", 0.0) or 0.0)
        current_sl = float(getattr(trade, "current_sl", 0.0) or getattr(trade, "original_sl", 0.0) or 0.0)
        if not (math.isfinite(trigger) and trigger > 0 and math.isfinite(current_sl) and current_sl > 0 and trigger > current_sl):
            return False, "structural_invalidation_trigger_invalid"
        if px > trigger:
            return False, "structural_invalidation_not_proven"
        trade.last_exit_authority = "STRUCTURAL_INVALIDATION"
        return True, "STRUCTURAL_INVALIDATION"

    # Canonical SOFTWARE SL exit: price MUST actually be at/below the model SL.
    if r == "software_sl_breach":
        sl = float(
            getattr(trade, "current_sl", 0.0)
            or getattr(trade, "original_sl", 0.0)
            or 0.0
        )
        if not math.isfinite(sl) or sl <= 0:
            return False, "software_sl_invalid"
        if bool(CONFIG.get("V572_EXIT_REQUIRE_SL_BREACH", True)) and px > sl:
            return False, "software_sl_breach_not_proven"
        trade.last_exit_authority = "SL_BREACH"
        return True, "SL_BREACH"

    # Canonical profit exits.
    if r in {"tp1_sell", "tp2_sell"}:
        target_name = "tp1" if r == "tp1_sell" else "tp2"
        target = float(getattr(trade, target_name, 0.0) or 0.0)
        if not math.isfinite(target) or target <= 0.0:
            return False, f"{target_name}_invalid"
        if bool(CONFIG.get("V572_EXIT_REQUIRE_TARGET_REACHED", True)) and (px + 1e-12) < target * (1.0 - tol_pct):
            return False, f"{target_name}_not_reached"
        # v4.5.73 — explicit per-stage completion latch survives status changes
        # and restart/reconciliation. It is stronger than status alone.
        if bool(CONFIG.get("V573_TARGET_COMPLETION_LATCH_ENABLE", True)) and bool(
            getattr(trade, f"{target_name}_exit_completed", False)
        ):
            return False, f"{target_name}_already_completed"
        status = str(getattr(trade, "status", "") or "")
        if target_name == "tp1" and status in {"tp1_hit", "be_moved", "trailing", "tp2_hit", "runner", "tp3_hit"}:
            return False, "tp1_already_consumed"
        if target_name == "tp2" and status in {"tp2_hit", "runner", "tp3_hit"}:
            return False, "tp2_already_consumed"
        trade.last_exit_authority = target_name.upper()
        return True, target_name.upper()

    # Explicit safety-hazard exits are allowed only when they are clearly
    # classified; strategy/time/monitor/unknown exits are NOT normal SELLs.
    safety_allowed = {
        "tp1_be_replace_failed",
        "tp2_sl_replace_failed",
        "tp3_runner_lock_failed",
        "trailing_fresh_place_failed",
        "structural_invalidation",
        "tp1_be_replace_failed_reconciled",
        "tp2_sl_replace_failed_reconciled",
        "oversell_guard",
    }
    if r.startswith("entry_protection_failed:") or r in safety_allowed:
        if not bool(CONFIG.get("V571_ALLOW_SAFETY_HAZARD_MARKET_SELL", False)) or            not bool(CONFIG.get("V574_ALLOW_SAFETY_HAZARD_MARKET_SELL", False)):
            return False, "safety_hazard_market_sell_disabled"
        if bool(CONFIG.get("V576_SAFETY_HAZARD_SINGLE_ATTEMPT", True)) and bool(
            getattr(trade, "safety_hazard_sell_attempted", False)
        ):
            return False, "safety_hazard_already_attempted"
        # v4.5.73 — safety exits are explicitly separated from normal TP/SL.
        trade.last_exit_authority = "SAFETY_HAZARD"
        trade.safety_hazard_exit_count = int(getattr(trade, "safety_hazard_exit_count", 0) or 0) + 1
        STATS["v573_safety_hazard_sell_authorized"] = int(
            STATS.get("v573_safety_hazard_sell_authorized", 0) or 0
        ) + 1
        return True, "SAFETY_HAZARD"

    # Deliberately prohibited automatic market-SELL reasons.
    return False, f"exit_reason_not_authorized:{r or 'missing_reason'}"


async def _v572_submit_market_sell_authorized(
    exchange: Any, trade: TradeState, qty: float, current_price: float,
    reason: str, stage: Optional[str] = None
) -> Dict[str, Any]:
    """Single last-mile MARKET SELL gateway; no exchange SELL bypass."""
    _reason = str(reason or stage or "").strip().lower()
    _stage = str(stage or _reason or "exit")
    if bool(CONFIG.get("V572_EXIT_FINAL_SUBMIT_AUTH_ENABLE", True)):
        ok, auth = _v571_exit_authority(
            trade, _reason, exit_px=current_price, stage=_stage
        )
        if not ok:
            STATS["v572_final_submit_blocks"] = int(STATS.get("v572_final_submit_blocks", 0) or 0) + 1
            logger.critical(
                f"[V572-EXIT] BLOCKED final MARKET SELL {trade.symbol} reason={_reason} authority={auth} px={current_price}"
            )
            raise _V517UnknownExecution(f"exit_authority_block:{auth}")
    q = float(qty or 0.0)
    if not math.isfinite(q) or q <= 0.0:
        raise _V517UnknownExecution("exit_qty_invalid")
    STATS["v572_final_authorized_market_sells"] = int(STATS.get("v572_final_authorized_market_sells", 0) or 0) + 1
    if auth == "SAFETY_HAZARD":
        trade.safety_hazard_sell_attempted = True
        if bool(CONFIG.get("V573_EXIT_SAFETY_SEPARATION_ENABLE", True)):
            STATS["v573_safety_hazard_market_sells"] = int(
                STATS.get("v573_safety_hazard_market_sells", 0) or 0
            ) + 1
            logger.critical(
                f"[V573-SAFETY-SELL] {trade.symbol} authorized SAFETY_HAZARD "
                f"market SELL reason={_reason} px={current_price}"
            )
    elif auth in {"TP1", "TP2", "SL_BREACH"} and bool(CONFIG.get("V573_EXIT_SAFETY_SEPARATION_ENABLE", True)):
        STATS[f"v573_normal_{auth.lower()}_market_sells"] = int(
            STATS.get(f"v573_normal_{auth.lower()}_market_sells", 0) or 0
        ) + 1
    _sell_client_id, _sell_client_params = _v702_a52_client_order_params(
        exchange, "create_market_sell_order"
    )
    trade.v517_last_exit_client_order_id = str(_sell_client_id or "")
    trade.v517_last_exit_started_ts = float(WALL_NOW())
    def _market_sell_factory():
        if _sell_client_params:
            return exchange.create_market_sell_order(trade.symbol, q, _sell_client_params)
        return exchange.create_market_sell_order(trade.symbol, q)
    return await safe_api_call(_stage, _market_sell_factory)


class SoftwareSLFallback:
    """Automatic local SL watchdog used after native SL is unavailable/unverified."""

    @staticmethod
    async def check(exchange, trade: TradeState, current_price: float) -> bool:
        policy = str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper()

        # v4.5.74: TARGET_ONLY/SOFTWARE_ALERT no longer disables automatic
        # Software-SL. They only control target-order policy / notification mode.
        if not bool(getattr(trade, "software_sl_active", False)):
            return False

        # v4.5.70 ROOT FIX: protection SELL is forbidden during a bounded
        # post-fill stabilization window. A short 2s grace was insufficient to
        # prevent BUY->SELL races during exchange/PM startup.
        try:
            activated = float(getattr(trade, "software_sl_activated_ts", 0.0) or 0.0)
            grace = max(0.0, float(CONFIG.get("V560_SOFTWARE_SL_GRACE_SEC", 2.0)))
            guard_sec = max(0.0, float(CONFIG.get("V570_POST_ENTRY_AUTO_SELL_GUARD_SEC", 15.0)))
            elapsed = _v570_entry_age_sec(trade)
            if activated > 0 and MONO_NOW() - activated < grace:
                return False
            if elapsed < guard_sec:
                STATS["v570_post_entry_protection_sell_guard"] = int(
                    STATS.get("v570_post_entry_protection_sell_guard", 0) or 0
                ) + 1
                return False
        except Exception:
            # Unknown post-fill age is not proof of a breach. Fail closed on the
            # automated protection exit itself rather than issuing an early SELL.
            return False

        # Hard monitoring-staleness threshold is evaluated directly from the
        # PM heartbeat. We do not delegate to the older 240s heartbeat default.
        try:
            age = float(SoftwareSLTelemetry.heartbeat_age_sec())
        except Exception:
            age = float("inf")

        stale_limit = max(
            2.0,
            float(CONFIG.get(
                "V562_SOFTWARE_SL_MONITOR_STALE_HARD_SEC",
                CONFIG.get("V560_SOFTWARE_SL_MAX_MISSED_HEARTBEAT_SEC", 12.0),
            )),
        )

        if not math.isfinite(age) or age > stale_limit:
            trade.sl_health_state = "SOFTWARE_SL_DEGRADED"
            try:
                SoftwareSLTelemetry.register_trade_protection_check(
                    trade, current_price, healthy=False, reason=f"pm_heartbeat_stale:{age:.2f}s"
                )
            except Exception:
                _v647_record_suppressed_exception()
            trade.protection_reconcile_required = True
            trade.protection_reconcile_reason = "pm_heartbeat_stale"
            if bool(CONFIG.get("V560_SOFTWARE_SL_BLOCK_NEW_ENTRIES_ON_DEGRADED", True)):
                live_entries_block(
                    f"software_sl_monitor_degraded_{trade.symbol}",
                    where="V562.SoftwareSLFallback"
                )
            # Do not use one stale read as proof of a live price breach.
            # Persistent monitor loss is the actual emergency protection case.
            logger.critical(
                f"[V571-SL] {trade.symbol} monitor stale age={age:.2f}s "
                f"> limit={stale_limit:.2f}s — NEW entries blocked; NO automatic SELL"
            )
            STATS["v571_monitor_stale_no_sell"] = int(
                STATS.get("v571_monitor_stale_no_sell", 0) or 0
            ) + 1
            # v4.5.73: monitor staleness is NOT a market-sell trigger.
            # It blocks NEW entries and preserves the position until a real TP/SL
            # condition is proven.
            return False

        # Optional age timeout remains disabled by default and is separate from
        # monitor health.
        hard_to = max(
            0.0,
            float(CONFIG.get("V560_SOFTWARE_SL_HARD_TIMEOUT_SEC", 0.0))
        )
        if hard_to > 0:
            activated = float(getattr(trade, "software_sl_activated_ts", 0.0) or 0.0)
            if activated > 0 and MONO_NOW() - activated > hard_to:
                SoftwareSLTelemetry.register_timeout()
                live_entries_block(
                    f"software_sl_hard_timeout_{trade.symbol}",
                    where="V571.SoftwareSLFallback",
                )
                logger.critical(
                    f"[V571-SL] {trade.symbol} software-SL age timeout reached "
                    f"({hard_to:.1f}s) — NO automatic SELL; TP/SL exit authority remains"
                )
                # v4.5.73: hard-timeout is a control-plane hazard, not a
                # price-independent exit. Never MARKET SELL for age alone.

        cur = float(current_price or 0.0)
        sl = float(
            getattr(trade, "current_sl", 0.0)
            or getattr(trade, "original_sl", 0.0)
            or 0.0
        )
        if cur <= 0 or sl <= 0 or cur >= 1e30:
            return False
        # Persist the exact protection observation for post-trade forensics.
        try:
            trade.protection_last_trigger_price = cur
            trade.protection_last_trigger_ts = MONO_NOW()
        except Exception:
            _v593_note_suppressed_exception("v702.protection.observation", Exception("field_write_failed"))

        # V702 FINAL: the per-trade lease is refreshed only after a concrete
        # price+SL evaluation is possible. This closes the process-live/trade-
        # protected ambiguity without turning monitor staleness into a SELL.
        try:
            SoftwareSLTelemetry.register_trade_protection_check(
                trade, cur, healthy=True, reason="price_sl_evaluated"
            )
        except Exception:
            _v647_record_suppressed_exception()

        # V702 FINAL: the dedicated protection tick is already an exchange price
        # observation. One confirmed breach is the canonical default; optional
        # multi-tick confirmation remains available by explicit configuration.
        confirm_ticks = max(
            1,
            int(CONFIG.get(
                "V702_SOFTWARE_SL_BREACH_CONFIRM_TICKS",
                CONFIG.get("V570_SOFTWARE_SL_BREACH_CONFIRM_TICKS", 1),
            ))
        )
        confirm_spacing = max(
            0.0,
            float(CONFIG.get("V570_SOFTWARE_SL_BREACH_MIN_CONFIRM_SPACING_SEC", 0.30)),
        )
        state_key = f"{trade.symbol}:v570_sl_breach_ticks"
        ts_key = f"{state_key}:last_ts"

        # v4.5.74: if price is decisively below the model SL by a bounded
        # percentage, one current observation is enough. This avoids delaying a
        # genuine fast move while retaining the normal 3 spaced confirmations
        # for ordinary/noisy touches.
        decisive_enable = bool(CONFIG.get("V574_SOFTWARE_SL_DECISIVE_BREACH_ENABLE", True))
        decisive_pct = max(
            0.0,
            float(CONFIG.get("V574_SOFTWARE_SL_DECISIVE_BREACH_PCT", 0.20))
        ) / 100.0
        decisive_breach = bool(
            decisive_enable
            and math.isfinite(decisive_pct)
            and cur <= sl * (1.0 - decisive_pct)
        )
        if decisive_breach:
            STATS[state_key] = max(
                int(CONFIG.get("V570_SOFTWARE_SL_BREACH_CONFIRM_TICKS", 3)),
                int(STATS.get(state_key, 0) or 0),
            )
            STATS[ts_key] = MONO_NOW()
        elif cur <= sl:
            now_mono = MONO_NOW()
            last_ts = float(STATS.get(ts_key, 0.0) or 0.0)
            if last_ts > 0.0 and (now_mono - last_ts) < confirm_spacing:
                return False
            STATS[ts_key] = now_mono
            count = int(STATS.get(state_key, 0) or 0) + 1
            STATS[state_key] = count
        else:
            STATS[state_key] = 0
            STATS[ts_key] = 0.0
            return False

        if int(STATS.get(state_key, 0) or 0) < confirm_ticks:
            return False

        SoftwareSLTelemetry.register_breach()
        trade.sl_health_state = "SOFTWARE_SL_ACTIVE"
        logger.critical(
            f"[V702-SL] {trade.symbol} AUTOMATIC SL BREACH CONFIRMED "
            f"trigger={cur:.10g} mark={float(getattr(trade, 'protection_last_mark_price', 0.0) or 0.0):.10g} "
            f"bid={float(getattr(trade, 'protection_last_bid_price', 0.0) or 0.0):.10g} "
            f"sl={sl:.10g} ticks={confirm_ticks} — MARKET SELL"
        )

        if not bool(CONFIG.get("V560_AUTO_SL_BREACH_SELL_ENABLE", True)):
            live_entries_block(
                f"software_sl_breach_auto_sell_disabled_{trade.symbol}",
                where="V562.SoftwareSLFallback"
            )
            return False

        try:
            ok = await OrderExecutor.emergency_close(
                exchange, trade, "software_sl_breach", exit_px=cur
            )
        except Exception as exc:
            logger.critical(
                f"[V562-SL] {trade.symbol} breach SELL exception: {exc}"
            )
            return False

        if ok:
            STATS["v560_software_sl_auto_exits"] = int(
                STATS.get("v560_software_sl_auto_exits", 0) or 0
            ) + 1
            STATS[state_key] = 0
        return bool(ok)


# =============================================================================
#  v4.5.65 — PULLBACK STRUCTURAL RECOVERY / STARVATION HELPERS
# =============================================================================

_V565_STRUCTURAL_REJECTS = defaultdict(deque)
_V565_STRUCTURAL_QUARANTINE_UNTIL = {}


def _v565_note_structural_reject(symbol: str) -> None:
    if not bool(CONFIG.get("V565_DISCOVERY_STRUCTURAL_QUARANTINE_ENABLE", True)):
        return
    try:
        now = MONO_NOW()
        sym = str(symbol or "").upper()
        q = _V565_STRUCTURAL_REJECTS[sym]
        q.append(now)
        window = max(60.0, float(CONFIG.get("V565_DISCOVERY_STRUCTURAL_QUARANTINE_WINDOW_SEC", 900.0)))
        while q and now - q[0] > window:
            q.popleft()
        threshold = max(1, int(CONFIG.get("V565_DISCOVERY_STRUCTURAL_QUARANTINE_REJECTS", 3)))
        if len(q) >= threshold:
            _V565_STRUCTURAL_QUARANTINE_UNTIL[sym] = now + max(
                60.0, float(CONFIG.get("V565_DISCOVERY_STRUCTURAL_QUARANTINE_SEC", 1800.0))
            )
    except Exception:
        _v647_record_suppressed_exception()


def _v565_symbol_structural_quarantined(symbol: str) -> bool:
    if not bool(CONFIG.get("V565_DISCOVERY_STRUCTURAL_QUARANTINE_ENABLE", True)):
        return False
    try:
        now = MONO_NOW()
        sym = str(symbol or "").upper()
        until = float(_V565_STRUCTURAL_QUARANTINE_UNTIL.get(sym, 0.0) or 0.0)
        if until > now:
            return True
        if until:
            _V565_STRUCTURAL_QUARANTINE_UNTIL.pop(sym, None)
        return False
    except Exception:
        return False


def _v565_structural_recovery_candidate(
    candidate: Any,
    *,
    close_price: Optional[float] = None,
    ema50: Optional[float] = None,
    chase_atr: Optional[float] = None,
) -> bool:
    """Very narrow PULLBACK recovery; never bypasses final canonical gates."""
    if not bool(CONFIG.get("V565_STRUCTURAL_BYPASS_ENABLE", True)):
        return False
    try:
        if candidate is None:
            return False

        # Use the canonical candidate context so StrategyCandidate.engine_score
        # (0..1) is consistently normalized to the 0..100 scale expected by
        # the V565 thresholds.
        if isinstance(candidate, dict):
            raw = dict(candidate)
            family = str(
                raw.get("family")
                or raw.get("strategy_mode")
                or (raw.get("features") or {}).get("strategy_mode", "")
            ).upper()
            engine = float(raw.get("score", raw.get("engine_score", 0.0)) or 0.0)
            if 0.0 <= engine <= 1.0:
                engine *= 100.0
            reviewed = float(
                raw.get("reviewed_score", (raw.get("features") or {}).get("reviewed_score", engine))
                or engine
            )
            if 0.0 <= reviewed <= 1.0:
                reviewed *= 100.0
            htf = float(
                raw.get("htf_strength", (raw.get("features") or {}).get("htf_strength", 0.0))
                or 0.0
            )
            ch0 = raw.get("chase_atr", (raw.get("features") or {}).get("chase_atr", None))
            ch = float(chase_atr) if chase_atr is not None else (
                float(ch0) if ch0 is not None else 999.0
            )
        else:
            cctx = _v540_candidate_ctx(candidate, {})
            family = str(
                getattr(candidate, "family", "")
                or getattr(candidate, "strategy_mode", "")
                or cctx.get("family", "")
            ).upper()
            engine = float(cctx.get("score", 0.0) or 0.0)
            reviewed = float(cctx.get("reviewed_score", engine) or engine)
            htf = float(cctx.get("htf", 0.0) or 0.0)
            ch = (
                float(chase_atr)
                if chase_atr is not None
                else float(cctx.get("chase", 999.0) or 999.0)
            )

        allowed = {
            str(x).upper()
            for x in CONFIG.get(
                "V565_STRUCTURAL_BYPASS_ALLOWED_FAMILIES",
                ("PULLBACK", "MTF_PULLBACK"),
            )
        }
        if family not in allowed:
            return False
        if engine < float(CONFIG.get("V565_STRUCTURAL_BYPASS_MIN_ENGINE_SCORE", 97.0)):
            return False
        if reviewed < float(CONFIG.get("V565_STRUCTURAL_BYPASS_MIN_REVIEWED_SCORE", 90.0)):
            return False
        if htf < float(CONFIG.get("V565_STRUCTURAL_BYPASS_MIN_HTF", 95.0)):
            return False
        if not math.isfinite(ch) or ch > float(CONFIG.get("V565_STRUCTURAL_BYPASS_MAX_CHASE_ATR", 0.50)):
            return False

        # Preserve HTF trend location whenever the data is available.
        if close_price is not None and ema50 is not None:
            cp = float(close_price)
            e50 = float(ema50)
            if not (math.isfinite(cp) and math.isfinite(e50) and cp > e50):
                return False

        return True
    except Exception:
        return False


def _v565_starvation_mode_from_window(
    *,
    generated: int,
    prequal: int,
    ranked: int,
    selected: int,
    queued: int,
    sent: int,
    reject_htf: int,
    reject_liq: int,
    reject_structure: int,
    reject_score: int,
    reject_execution: int = 0,
    reject_policy: int = 0,
) -> str:
    """Attribute the bottleneck to the dominant actual rejection pressure."""
    try:
        total_attr = max(
            1,
            int(reject_htf)
            + int(reject_liq)
            + int(reject_structure)
            + int(reject_score)
            + int(reject_execution)
            + int(reject_policy)
        )
        # No evidence means UNATTRIBUTED; never let tied zeros elect HTF.
        if total_attr == 1 and not any(int(x) > 0 for x in (
            reject_htf, reject_liq, reject_structure, reject_score,
            reject_execution, reject_policy
        )):
            return "UNATTRIBUTED"
        structural_pressure = float(reject_structure) / float(total_attr)
        if structural_pressure >= float(
            CONFIG.get("V565_STARVATION_STRUCTURAL_PRESSURE_MIN", 0.40)
        ):
            return "STRUCTURE"

        if int(generated) > 0 and int(prequal) == 0:
            if int(reject_policy) > max(int(reject_htf), int(reject_liq), int(reject_structure), int(reject_score), int(reject_execution)):
                return "POLICY"
            if int(reject_htf) >= max(int(reject_liq), int(reject_structure), int(reject_score), int(reject_policy), int(reject_execution)) and int(reject_htf) > 0:
                return "HTF"
            if int(reject_liq) >= max(int(reject_htf), int(reject_structure), int(reject_score), int(reject_policy), int(reject_execution)) and int(reject_liq) > 0:
                return "LIQUIDITY"
            if int(reject_structure) >= max(int(reject_htf), int(reject_liq), int(reject_score), int(reject_policy), int(reject_execution)) and int(reject_structure) > 0:
                return "STRUCTURE"
            if int(reject_score) > 0:
                return "SCORE"
            if int(reject_execution) > 0:
                return "EXECUTION"
            if int(reject_policy) > 0:
                return "POLICY"
            return "UNATTRIBUTED"

        if int(selected) > int(queued) and int(queued) == 0:
            if int(reject_execution) > max(int(reject_score), int(reject_structure)):
                return "EXECUTION"
            if int(reject_structure) >= max(int(reject_htf), int(reject_liq), int(reject_score)):
                return "STRUCTURE"
            return "SCORE"

        if int(queued) > int(sent):
            return "EXECUTION"
        return "NONE"
    except Exception:
        return "SYSTEM"



# =============================================================================
#  SECTION 30 — CONSISTENCY CHECKER
# =============================================================================

class ConsistencyChecker:

    @staticmethod
    async def tick(exchange) -> Dict[str, Any]:
        report = {"missing_sl": 0, "orphan_orders": 0, "checked_at": WALL_NOW()}
        try:
            open_orders = await safe_api_call("fetch_open_orders",
                                              exchange.fetch_open_orders())
            by_symbol: Dict[str, List] = defaultdict(list)
            for o in open_orders:
                by_symbol[o.get("symbol", "")].append(o)
            known_ids = set()
            for t in list(ACTIVE_TRADES.values()):
                if t.sl_order_id:
                    known_ids.add(str(t.sl_order_id))
                    found = any(str(o.get("id")) == str(t.sl_order_id)
                                for o in by_symbol.get(t.symbol, []))
                    if not found:
                        report["missing_sl"] += 1
            for sym, orders in by_symbol.items():
                for o in orders:
                    if str(o.get("id")) not in known_ids:
                        report["orphan_orders"] += 1
        except Exception as e:
            logger.warning(f"[Consistency] tick error: {e}")
        STATS["last_consistency_check"] = report
        return report


# =============================================================================
#  SECTION 31 — STARVATION GUARD + FUNNEL INVARIANT
# =============================================================================

class StarvationGuard:
    """
    v4.0.2 PATCH E.2 — 3 independent detectors (all additive):
      (A) G→E blindness    : G rising strongly but E stuck at ~0 for N minutes.
                              ALERT ONLY (telemetry) — does NOT escalate LIVE_BLOCKED.
      (B) Q→S starvation   : existing behavior preserved verbatim (LIVE_BLOCKED escalation).
      (C) Stage stagnation : each funnel stage tracked for last-advance timestamp;
                              log a warning if a stage stops advancing for too long.
    """
    _last_check: float = 0.0
    _consec_stuck: int = 0   # (B) Q→S consecutive minutes stuck (delta-based, v4.0.5)
    # v4.0.5 FIX #3 — delta-counter baselines for Q→S starvation detection.
    _qs_last_queued: int = 0
    _qs_last_sent: int = 0
    # v4.0.10: per-UTC-day escalation ledger and observability split.
    _events_date: str = ""
    _events_today: int = 0
    _suppression_ticks: int = 0
    _blindness_ticks: int = 0

    # --- (A) G→E blindness state ---------------------------------------------
    _ge_last_g: int = 0
    _ge_last_e: int = 0
    _ge_blind_minutes: int = 0
    _ge_blind_alerts_emitted: int = 0

    # --- (C) stage stagnation state ------------------------------------------
    _stage_last_val: Dict[str, int] = {

        "generated": 0, "eligible": 0, "queued": 0, "sent": 0
    }
    _stage_last_change_ts: Dict[str, float] = {}
    _stage_stag_alerts: Dict[str, int] = {
        "generated": 0, "eligible": 0, "queued": 0, "sent": 0
    }

    @classmethod
    def _update_stage_stagnation(cls, now: float) -> Dict[str, float]:
        """(C) track when each funnel counter last advanced.
        Returns a snapshot of seconds-since-last-advance per stage.
        """
        stages = {
            "generated": STATS.get("signals_generated", 0),
            "eligible":  STATS.get("signals_eligible", 0),
            "queued":    STATS.get("signals_queued", 0),
            "sent":      STATS.get("signals_sent", 0),
        }
        stag_snap: Dict[str, float] = {}
        threshold = float(CONFIG.get("STARVATION_STAGE_STAGNATION_SEC", 900))
        # Snapshot baselines before mutating them so an upstream-advance test is
        # genuinely delta-based for THIS watchdog tick. The previous expression
        # compared against the just-updated baseline minus one, making the test
        # effectively always true and producing false stagnation diagnostics.
        prev_values = {name: int(cls._stage_last_val.get(name, 0) or 0) for name in stages}
        for name, val in stages.items():
            prev = prev_values[name]
            if int(val) > int(prev):
                cls._stage_last_val[name] = val
                cls._stage_last_change_ts[name] = now
            last_ts = cls._stage_last_change_ts.get(name, now)
            age = now - last_ts
            stag_snap[name] = age
            # Only alert when the *upstream* stage actually advances during this
            # same tick while this stage remains stagnant.
            if age >= threshold:
                upstream = {"eligible": "generated",
                            "queued": "eligible",
                            "sent": "queued"}.get(name)
                upstream_advanced = bool(
                    upstream and
                    int(stages.get(upstream, 0) or 0) > int(prev_values.get(upstream, 0) or 0)
                )
                if upstream and upstream_advanced:
                    # log once per stagnation window
                    if cls._stage_stag_alerts.get(name, 0) < 1 + int(age // threshold):
                        if not bool(getattr(cls, "_selftest_suppress_stage_logs", False)):
                            logger.warning(
                                f"[Starvation] stage '{name}' stagnant for {int(age)}s "
                                f"(upstream '{upstream}' advanced this tick)"
                            )
                        cls._stage_stag_alerts[name] = 1 + int(age // threshold)
                        STATS[f"starvation_stage_stagnation_{name}"] = \
                            STATS.get(f"starvation_stage_stagnation_{name}", 0) + 1
        return stag_snap

    @classmethod
    def _check_ge_blindness(cls) -> Optional[str]:
        """(A) G→E blindness: G rising, E stuck near 0.
        Alert-only; NEVER escalates LIVE_BLOCKED (per PATCH E.2 spec).
        Returns an alert string if triggered this minute, else None.
        """
        g = int(STATS.get("signals_generated", 0))
        e = int(STATS.get("signals_eligible", 0))
        d_g = g - cls._ge_last_g
        d_e = e - cls._ge_last_e
        cls._ge_last_g = g
        cls._ge_last_e = e

        min_growth = int(CONFIG.get("STARVATION_GE_BLIND_MIN_GROWTH", 20))
        min_minutes = int(CONFIG.get("STARVATION_GE_BLIND_MIN_MINUTES", 5))

        # "G rising strongly and E flat-or-zero" this minute?
        if d_g >= min_growth and d_e <= 0:
            cls._ge_blind_minutes += 1
        else:
            cls._ge_blind_minutes = 0

        if cls._ge_blind_minutes >= min_minutes:
            cls._ge_blind_alerts_emitted += 1
            STATS["starvation_ge_blind_alerts"] = \
                STATS.get("starvation_ge_blind_alerts", 0) + 1
            msg = (f"[Starvation] G rising but E=0 — funnel blind "
                   f"(G={g}, E={e}, minutes={cls._ge_blind_minutes})")
            logger.warning(msg)
            # Reset counter to space out alerts (one per window)
            cls._ge_blind_minutes = 0
            return msg
        return None

    @classmethod
    def tick(cls):
        if not bool(CONFIG["V4_STARVATION_GUARD_ENABLE"]):
            return
        now = MONO_NOW()
        if now - cls._last_check < 60:
            return
        cls._last_check = now

        # (A) G→E blindness (alert-only)
        try:
            cls._check_ge_blindness()
        except Exception as _e:
            logger.debug(f"[Starvation] ge_blindness check err: {_e}")

        # (C) stage stagnation snapshot (alerts inside)
        try:
            cls._update_stage_stagnation(now)
        except Exception as _e:
            logger.debug(f"[Starvation] stage stagnation err: {_e}")

        # Daily rollover prevents an old, healthy-market suppression period
        # from accumulating into a future hard block.
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        if cls._events_date != today:
            cls._events_date = today
            cls._events_today = 0
            cls._suppression_ticks = 0
            cls._blindness_ticks = 0
            cls._consec_stuck = 0
            if bool(CONFIG.get("STARVATION_DAILY_COUNTER_RESET", True)):
                STATS["starvation_events"] = 0

        # Q→S is the only escalation candidate: actual candidates reached the
        # queue but none were sent. No queue growth is normal suppression
        # (bad regime / filters / no-signal) and is telemetry-only.
        queued = STATS.get("signals_queued", 0)
        sent = STATS.get("signals_sent", 0)
        d_queued = queued - int(getattr(cls, "_qs_last_queued", 0))
        d_sent = sent - int(getattr(cls, "_qs_last_sent", 0))
        cls._qs_last_queued = queued
        cls._qs_last_sent = sent
        if d_queued > 0 and d_sent == 0:
            cls._blindness_ticks += 1
            STATS["starvation_blindness_ticks"] = STATS.get("starvation_blindness_ticks", 0) + 1
            cls._consec_stuck += 1
            if cls._consec_stuck >= 3:
                cls._events_today += 1
                STATS["starvation_events"] = cls._events_today
                logger.warning(
                    f"[Starvation] Q→S BLINDNESS dQ={d_queued} dS=0 "
                    f"for {cls._consec_stuck} min; events_today={cls._events_today}"
                )
                max_events = int(CONFIG.get("V4_STARVATION_ESCALATE_MAX_EVENTS", 5))
                if cls._events_today >= max_events and \
                        bool(CONFIG.get("STARVATION_ESCALATE_ON_BLINDNESS_ONLY", True)):
                    logger.critical(
                        f"[Starvation] confirmed Q→S blindness events_today="
                        f"{cls._events_today}/{max_events} — LIVE_BLOCKED"
                    )
                    LiveStateMachine.block(
                        f"starvation_qs_blindness_{cls._events_today}",
                        where="StarvationGuard.tick",
                    )
        else:
            if d_queued <= 0:
                cls._suppression_ticks += 1
                STATS["starvation_suppression_ticks"] = STATS.get("starvation_suppression_ticks", 0) + 1
            cls._consec_stuck = 0

    @classmethod
    def snapshot(cls) -> Dict[str, Any]:
        """v4.0.2 PATCH E.6 — starvation observability for heartbeat/snapshot."""
        now = MONO_NOW()
        return {
            "qs_consec_stuck_min": cls._consec_stuck,
            "ge_blind_minutes": cls._ge_blind_minutes,
            "ge_blind_alerts_emitted": cls._ge_blind_alerts_emitted,
            "stage_age_sec": {
                k: round(now - cls._stage_last_change_ts.get(k, now), 1)
                for k in ("generated", "eligible", "queued", "sent")
            },
            "starvation_events": int(STATS.get("starvation_events", 0)),
            "events_date": cls._events_date,
            "events_today": cls._events_today,
            "suppression_ticks_today": cls._suppression_ticks,
            "blindness_ticks_today": cls._blindness_ticks,
            "suppression_ticks_total": int(STATS.get("starvation_suppression_ticks", 0)),
            "blindness_ticks_total": int(STATS.get("starvation_blindness_ticks", 0)),
        }

    @staticmethod
    def funnel_invariant_check():
        g = STATS.get("signals_generated", 0)
        e = STATS.get("signals_eligible", 0)
        q = STATS.get("signals_queued", 0)
        s = STATS.get("signals_sent", 0)
        if not (g >= e >= q >= s):
            logger.error(f"[FunnelInvariant] VIOLATION: G={g} E={e} Q={q} S={s}")
            STATS["funnel_stage_invariant_violation"] = STATS.get(
                "funnel_stage_invariant_violation", 0) + 1


# =============================================================================
#  SECTION 32 — SQLITE PERSISTENCE
# =============================================================================

class DBManager:

    @staticmethod
    def init_schema():
        path = str(CONFIG.get("DB_PATH") or "./unified_scalper.db")
        # Production hosts commonly point SCALPER_DB into a mounted volume
        # (for example /data/unified_scalper.db). Make a missing parent
        # directory explicit before SQLite opens the file; otherwise startup
        # fails with an opaque "unable to open database file" exception.
        # Keep SQLite's special in-memory path untouched for isolated tests.
        if path != ":memory:":
            db_parent = os.path.dirname(os.path.abspath(path))
            os.makedirs(db_parent, exist_ok=True)
            if not os.path.isdir(db_parent):
                raise RuntimeError(f"SCALPER_DB parent is not a directory: {db_parent}")
            if not os.access(db_parent, os.W_OK):
                raise PermissionError(f"SCALPER_DB parent is not writable by runtime UID: {db_parent}")
        conn = None
        try:
            conn = sqlite3.connect(path, timeout=5)
            conn.execute("PRAGMA busy_timeout=5000")
            conn.execute("PRAGMA journal_mode=WAL")
            c = conn.cursor()
            c.execute("""CREATE TABLE IF NOT EXISTS active_trades (
                symbol TEXT PRIMARY KEY,
                trade_id TEXT,
                snapshot_json TEXT NOT NULL,
                updated_at TEXT NOT NULL)""")
            c.execute("""CREATE TABLE IF NOT EXISTS finalized_trade_ids (
                trade_id TEXT PRIMARY KEY,
                symbol TEXT,
                reason TEXT,
                finalized_at TEXT NOT NULL)""")
            c.execute("""CREATE TABLE IF NOT EXISTS daily_state (
                date TEXT PRIMARY KEY,
                realized_r REAL NOT NULL DEFAULT 0,
                daily_trades INTEGER NOT NULL DEFAULT 0,
                blocked INTEGER NOT NULL DEFAULT 0,
                snapshot_json TEXT NOT NULL,
                updated_at TEXT NOT NULL)""")
            c.execute("""CREATE TABLE IF NOT EXISTS rejection_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                ts TEXT NOT NULL, stage TEXT, symbol TEXT,
                reason TEXT, score REAL, trace_id TEXT, context_json TEXT)""")
            c.execute("""CREATE TABLE IF NOT EXISTS execution_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                ts TEXT NOT NULL, event_type TEXT NOT NULL,
                symbol TEXT, trace_id TEXT, details_json TEXT)""")
            # Durable pre-wire journal. SUBMISSION_STARTED survives process death and
            # blocks new entries until exchange outcome is reconciled explicitly.
            c.execute("""CREATE TABLE IF NOT EXISTS execution_intents (
                intent_id TEXT PRIMARY KEY, symbol TEXT NOT NULL, trace_id TEXT,
                side TEXT NOT NULL, order_type TEXT NOT NULL,
                requested_qty REAL NOT NULL, planned_price REAL NOT NULL,
                status TEXT NOT NULL, venue_order_id TEXT,
                details_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL, updated_at TEXT NOT NULL)""")
            c.execute("CREATE INDEX IF NOT EXISTS idx_execution_intents_status ON execution_intents(status)")
            c.execute("CREATE INDEX IF NOT EXISTS idx_execution_intents_symbol ON execution_intents(symbol)")
            c.execute("""CREATE TABLE IF NOT EXISTS telegram_outbox (
                outbox_id TEXT PRIMARY KEY, message_key TEXT NOT NULL, message TEXT NOT NULL,
                status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_error TEXT
            )""")
            c.execute("CREATE INDEX IF NOT EXISTS idx_telegram_outbox_status ON telegram_outbox(status, created_at)")
            c.execute("CREATE INDEX IF NOT EXISTS idx_telegram_outbox_key ON telegram_outbox(message_key)")
            c.execute("CREATE INDEX IF NOT EXISTS idx_rejection_ts ON rejection_events(ts)")
            c.execute("CREATE INDEX IF NOT EXISTS idx_rejection_symbol ON rejection_events(symbol)")
            c.execute("CREATE INDEX IF NOT EXISTS idx_execevt_ts ON execution_events(ts)")
            c.execute("CREATE INDEX IF NOT EXISTS idx_execevt_symbol ON execution_events(symbol)")
            conn.commit()
            conn.close()
            logger.info(f"[DB] Schema initialized at {path}")
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def begin_execution_intent(symbol: str, trace_id: str, side: str, order_type: str,
                               requested_qty: float, planned_price: float,
                               details: Optional[Dict[str, Any]] = None) -> str:
        intent_id = uuid.uuid4().hex
        now = datetime.now(timezone.utc).isoformat()
        conn = None
        try:
            qty = float(requested_qty); px = float(planned_price)
            if not math.isfinite(qty) or qty <= 0 or not math.isfinite(px) or px <= 0:
                raise ValueError("execution_intent_invalid_quantity_or_price")
            payload = json.dumps(dict(details or {}), default=str, allow_nan=False)
            conn = sqlite3.connect(CONFIG["DB_PATH"], timeout=5.0)
            conn.execute("PRAGMA busy_timeout=5000")
            # Ensure compatibility for offline/embedded callers that exercise the
            # executor without first running the application startup routine.
            conn.execute("""CREATE TABLE IF NOT EXISTS execution_intents (
                intent_id TEXT PRIMARY KEY, symbol TEXT NOT NULL, trace_id TEXT,
                side TEXT NOT NULL, order_type TEXT NOT NULL,
                requested_qty REAL NOT NULL, planned_price REAL NOT NULL,
                status TEXT NOT NULL, venue_order_id TEXT,
                details_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL, updated_at TEXT NOT NULL)""")
            conn.execute("CREATE INDEX IF NOT EXISTS idx_execution_intents_status ON execution_intents(status)")
            conn.execute("CREATE INDEX IF NOT EXISTS idx_execution_intents_symbol ON execution_intents(symbol)")
            conn.execute("""INSERT INTO execution_intents
                (intent_id,symbol,trace_id,side,order_type,requested_qty,planned_price,status,
                 venue_order_id,details_json,created_at,updated_at)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
                (intent_id, str(symbol), str(trace_id or ""), str(side).upper(),
                 str(order_type).upper(), qty, px, "SUBMISSION_STARTED", None,
                 payload, now, now))
            conn.commit()
            STATS["execution_intents_durable_started"] = int(STATS.get("execution_intents_durable_started", 0) or 0) + 1
            return intent_id
        except Exception as exc:
            STATS["execution_intent_durable_failures"] = int(STATS.get("execution_intent_durable_failures", 0) or 0) + 1
            try:
                live_entries_block(f"execution_intent_persistence_failed_{symbol}", where="DBManager.begin_execution_intent")
            except Exception:
                pass
            logger.critical("[EXEC-INTENT] cannot durably record pre-wire intent for %s; order is blocked: %s", symbol, exc)
            raise RuntimeError(f"execution_intent_persistence_failed:{symbol}") from exc
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def update_execution_intent(intent_id: str, status: str, venue_order_id: str = "",
                                details: Optional[Dict[str, Any]] = None) -> None:
        iid = str(intent_id or "").strip()
        if not iid:
            raise ValueError("execution_intent_id_missing")
        conn = None
        now = datetime.now(timezone.utc).isoformat()
        try:
            conn = sqlite3.connect(CONFIG["DB_PATH"], timeout=5.0)
            conn.execute("PRAGMA busy_timeout=5000")
            cur = conn.execute("SELECT details_json FROM execution_intents WHERE intent_id=?", (iid,))
            row = cur.fetchone()
            if row is None:
                raise RuntimeError("execution_intent_not_found")
            merged = json.loads(row[0] or "{}")
            if not isinstance(merged, dict): merged = {}
            merged.update(dict(details or {}))
            conn.execute("""UPDATE execution_intents SET status=?, venue_order_id=COALESCE(NULLIF(?,''),venue_order_id),
                details_json=?, updated_at=? WHERE intent_id=?""",
                (str(status).upper(), str(venue_order_id or ""),
                 json.dumps(merged, default=str, allow_nan=False), now, iid))
            conn.commit()
            STATS[f"execution_intent_status_{str(status).lower()}"] = int(STATS.get(f"execution_intent_status_{str(status).lower()}", 0) or 0) + 1
        except Exception as exc:
            STATS["execution_intent_update_failures"] = int(STATS.get("execution_intent_update_failures", 0) or 0) + 1
            try:
                live_entries_block("execution_intent_update_failed", where="DBManager.update_execution_intent")
            except Exception:
                pass
            logger.critical("[EXEC-INTENT] status update failed intent=%s status=%s: %s", iid, status, exc)
            raise RuntimeError(f"execution_intent_update_failed:{iid}:{status}") from exc
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def unresolved_execution_intents() -> List[Dict[str, Any]]:
        conn = None
        try:
            conn = sqlite3.connect(CONFIG["DB_PATH"], timeout=5.0)
            conn.execute("PRAGMA busy_timeout=5000")
            rows = conn.execute("""SELECT intent_id,symbol,trace_id,side,order_type,requested_qty,
                planned_price,status,venue_order_id,details_json,created_at,updated_at
                FROM execution_intents WHERE status NOT IN
                ('NO_FILL_TERMINAL','REJECTED_PRE_SUBMISSION','REJECTED_NO_ORDER','PROTECTION_ARMED','CLOSED_RECONCILED')
                ORDER BY created_at""").fetchall()
            out=[]
            for r in rows:
                try: details=json.loads(r[9] or "{}")
                except Exception: details={}
                out.append({"intent_id":r[0],"symbol":r[1],"trace_id":r[2],"side":r[3],
                    "order_type":r[4],"requested_qty":r[5],"planned_price":r[6],"status":r[7],
                    "venue_order_id":r[8],"details":details,"created_at":r[10],"updated_at":r[11]})
            STATS["execution_intents_unresolved_last"] = len(out)
            return out
        except Exception as exc:
            STATS["execution_intents_recovery_read_failures"] = int(STATS.get("execution_intents_recovery_read_failures", 0) or 0) + 1
            try: live_entries_block("execution_intents_recovery_read_failed", where="DBManager.unresolved_execution_intents")
            except Exception: pass
            logger.critical("[EXEC-INTENT] unable to inspect durable execution intents: %s", exc)
            raise RuntimeError("execution_intents_recovery_read_failed") from exc
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def find_execution_intent_id_for_order(order_id: str) -> str:
        oid = str(order_id or "").strip()
        if not oid: return ""
        conn = None
        try:
            conn = sqlite3.connect(CONFIG["DB_PATH"], timeout=5.0)
            row = conn.execute("SELECT intent_id FROM execution_intents WHERE venue_order_id=? ORDER BY updated_at DESC LIMIT 1", (oid,)).fetchone()
            return str(row[0] or "") if row else ""
        finally:
            if conn is not None: conn.close()

    @staticmethod
    def delete_trade_snapshot(symbol: str, trade_id: str = "") -> None:
        conn = None
        try:
            conn = sqlite3.connect(CONFIG["DB_PATH"], timeout=5.0)
            conn.execute("PRAGMA busy_timeout=5000")
            if trade_id:
                conn.execute("DELETE FROM active_trades WHERE symbol=? AND trade_id=?", (str(symbol), str(trade_id)))
            else:
                conn.execute("DELETE FROM active_trades WHERE symbol=?", (str(symbol),))
            conn.commit()
        except Exception as exc:
            live_entries_block(f"pending_trade_snapshot_delete_failed_{symbol}", where="DBManager.delete_trade_snapshot")
            logger.critical("[EXEC-INTENT] unable to delete verified zero-fill pending snapshot %s: %s", symbol, exc)
            raise RuntimeError("pending_trade_snapshot_delete_failed") from exc
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    async def adelete_trade_snapshot(symbol: str, trade_id: str = "") -> None:
        await asyncio.to_thread(DBManager.delete_trade_snapshot, symbol, trade_id)

    @staticmethod
    async def abegin_execution_intent(*args, **kwargs) -> str:
        return await asyncio.to_thread(DBManager.begin_execution_intent, *args, **kwargs)

    @staticmethod
    async def aupdate_execution_intent(*args, **kwargs) -> None:
        await asyncio.to_thread(DBManager.update_execution_intent, *args, **kwargs)

    @staticmethod
    async def aunresolved_execution_intents() -> List[Dict[str, Any]]:
        return await asyncio.to_thread(DBManager.unresolved_execution_intents)

    @staticmethod
    def save_trade_snapshot(trade: TradeState):
        conn = None
        try:
            path = CONFIG["DB_PATH"]
            conn = sqlite3.connect(path, timeout=5.0)
            conn.execute("PRAGMA busy_timeout=5000")
            c = conn.cursor()
            snap = json.dumps(asdict(trade), default=str, allow_nan=False)
            now = datetime.now(timezone.utc).isoformat()
            c.execute("""INSERT OR REPLACE INTO active_trades
                (symbol, trade_id, snapshot_json, updated_at)
                VALUES (?, ?, ?, ?)""",
                      (trade.symbol, trade.trace_id, snap, now))
            conn.commit()
            STATS["db_trade_snapshot_save_ok"] = int(STATS.get("db_trade_snapshot_save_ok", 0) or 0) + 1
        except Exception as e:
            STATS["db_trade_snapshot_save_failures"] = int(STATS.get("db_trade_snapshot_save_failures", 0) or 0) + 1
            try:
                live_entries_block(
                    f"trade_snapshot_persistence_failed_{getattr(trade, 'symbol', 'unknown')}",
                    where="DBManager.save_trade_snapshot",
                )
            except Exception:
                pass
            logger.critical(
                "[DB-CRITICAL] TradeState snapshot not durable symbol=%s trace_id=%s; "
                "entry flow must remain blocked: %s",
                getattr(trade, "symbol", "?"), getattr(trade, "trace_id", "?"), e,
            )
            raise RuntimeError(f"trade_snapshot_persistence_failed:{getattr(trade, 'symbol', '?')}") from e
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def recover_active_trades() -> Dict[str, TradeState]:
        out: Dict[str, TradeState] = {}
        conn = None
        try:
            finalized_ids = DBManager.recover_finalized_trade_ids()
            path = CONFIG["DB_PATH"]
            conn = sqlite3.connect(path)
            c = conn.cursor()
            c.execute("SELECT trade_id, snapshot_json FROM active_trades")
            for trade_id, snap_json in c.fetchall():
                if trade_id and trade_id in finalized_ids:
                    continue
                try:
                    d = json.loads(snap_json)
                    t = TradeState(**{k: v for k, v in d.items() if k in TradeState.__dataclass_fields__})
                    if getattr(t, "trace_id", None) and t.trace_id in finalized_ids:
                        continue
                    out[t.symbol] = t
                except Exception:
                    continue
            if out:
                logger.info(f"[DB] Recovered {len(out)} active trades")
        except Exception as e:
            logger.warning(f"[DB] recover_active_trades: {e}")
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass
        return out

    @staticmethod
    def save_finalized_trade_id(trade_id: str, symbol: str = "", reason: str = "") -> None:
        conn = None
        try:
            path = CONFIG["DB_PATH"]
            conn = sqlite3.connect(path, timeout=5.0)
            conn.execute("PRAGMA busy_timeout=5000")
            c = conn.cursor()
            c.execute("""INSERT OR REPLACE INTO finalized_trade_ids
                (trade_id, symbol, reason, finalized_at)
                VALUES (?, ?, ?, ?)""",
                      (trade_id, symbol, reason, datetime.now(timezone.utc).isoformat()))
            conn.commit()
            STATS["db_finalized_trade_save_ok"] = int(STATS.get("db_finalized_trade_save_ok", 0) or 0) + 1
        except Exception as e:
            STATS["db_finalized_trade_save_failures"] = int(STATS.get("db_finalized_trade_save_failures", 0) or 0) + 1
            try:
                live_entries_block(
                    f"finalized_trade_persistence_failed_{symbol or 'unknown'}",
                    where="DBManager.save_finalized_trade_id",
                )
            except Exception:
                pass
            logger.critical(
                "[DB-CRITICAL] Finalized trade marker not durable trade_id=%s symbol=%s reason=%s: %s",
                trade_id, symbol, reason, e,
            )
            raise RuntimeError(f"finalized_trade_persistence_failed:{trade_id}") from e
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def recover_finalized_trade_ids() -> set:
        out = set()
        conn = None
        try:
            path = CONFIG["DB_PATH"]
            conn = sqlite3.connect(path)
            c = conn.cursor()
            c.execute("SELECT trade_id FROM finalized_trade_ids")
            for (trade_id,) in c.fetchall():
                if trade_id:
                    out.add(str(trade_id))
            if out:
                logger.info(f"[DB] Recovered {len(out)} finalized trade ids")
        except Exception as e:
            logger.debug(f"[DB] recover_finalized_trade_ids: {e}")
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass
        return out

    @staticmethod
    def enqueue_telegram_outbox(message: str) -> str:
        """Persist an operator message before admitting it to the volatile queue."""
        raw = str(message or "")
        if not raw.strip():
            raise ValueError("telegram_outbox_message_empty")
        key = hashlib.sha256(raw.encode("utf-8", errors="replace")).hexdigest()
        outbox_id = uuid.uuid4().hex
        now = datetime.now(timezone.utc).isoformat()
        conn = None
        try:
            path = str(CONFIG.get("DB_PATH") or "./unified_scalper.db")
            conn = sqlite3.connect(path, timeout=5.0)
            conn.execute("PRAGMA busy_timeout=5000")
            conn.execute("""CREATE TABLE IF NOT EXISTS telegram_outbox (
                outbox_id TEXT PRIMARY KEY, message_key TEXT NOT NULL, message TEXT NOT NULL,
                status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_error TEXT
            )""")
            conn.execute("INSERT INTO telegram_outbox(outbox_id,message_key,message,status,attempts,created_at,updated_at,last_error) VALUES(?,?,?,?,?,?,?,?)",
                         (outbox_id, key, raw, "QUEUED", 0, now, now, None))
            conn.commit()
            STATS["v702_a66_telegram_outbox_enqueued"] = int(STATS.get("v702_a66_telegram_outbox_enqueued", 0) or 0) + 1
            return outbox_id
        except Exception as exc:
            STATS["v702_a66_telegram_outbox_errors"] = int(STATS.get("v702_a66_telegram_outbox_errors", 0) or 0) + 1
            raise RuntimeError(f"telegram_outbox_persist_failed:{type(exc).__name__}") from exc
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def list_pending_telegram_outbox(limit: int = 500) -> List[Dict[str, Any]]:
        conn = None
        try:
            path = str(CONFIG.get("DB_PATH") or "./unified_scalper.db")
            conn = sqlite3.connect(path, timeout=5.0)
            conn.row_factory = sqlite3.Row
            conn.execute("PRAGMA busy_timeout=5000")
            conn.execute("""CREATE TABLE IF NOT EXISTS telegram_outbox (
                outbox_id TEXT PRIMARY KEY, message_key TEXT NOT NULL, message TEXT NOT NULL,
                status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_error TEXT
            )""")
            rows = conn.execute(
                "SELECT outbox_id,message_key,message,status,attempts,created_at FROM telegram_outbox "
                "WHERE status IN ('QUEUED','SENDING','RETRY_PENDING') ORDER BY created_at ASC LIMIT ?",
                (max(1, min(5000, int(limit))),),
            ).fetchall()
            return [dict(row) for row in rows]
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def prune_telegram_outbox(retention_days: int = 30, max_terminal_rows: int = 5000) -> Dict[str, int]:
        """Bound terminal Telegram history without ever pruning work in flight."""
        retention_days = max(1, min(3650, int(retention_days)))
        max_terminal_rows = max(100, min(100000, int(max_terminal_rows)))
        cutoff = (datetime.now(timezone.utc) - timedelta(days=retention_days)).isoformat()
        conn = None
        try:
            path = str(CONFIG.get("DB_PATH") or "./unified_scalper.db")
            conn = sqlite3.connect(path, timeout=5.0)
            conn.execute("PRAGMA busy_timeout=5000")
            conn.execute("""CREATE TABLE IF NOT EXISTS telegram_outbox (
                outbox_id TEXT PRIMARY KEY, message_key TEXT NOT NULL, message TEXT NOT NULL,
                status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_error TEXT
            )""")
            terminal = ("DELIVERED", "DEAD_LETTER")
            old_cur = conn.execute(
                "DELETE FROM telegram_outbox WHERE status IN (?,?) AND updated_at < ?",
                (terminal[0], terminal[1], cutoff),
            )
            deleted_old = max(0, int(old_cur.rowcount or 0))
            terminal_count = int(conn.execute(
                "SELECT COUNT(*) FROM telegram_outbox WHERE status IN (?,?)", terminal
            ).fetchone()[0])
            excess = max(0, terminal_count - max_terminal_rows)
            deleted_cap = 0
            if excess:
                cap_cur = conn.execute(
                    "DELETE FROM telegram_outbox WHERE outbox_id IN ("
                    "SELECT outbox_id FROM telegram_outbox WHERE status IN (?,?) "
                    "ORDER BY updated_at ASC,created_at ASC LIMIT ?) ",
                    (terminal[0], terminal[1], excess),
                )
                deleted_cap = max(0, int(cap_cur.rowcount or 0))
            conn.commit()
            pending = int(conn.execute(
                "SELECT COUNT(*) FROM telegram_outbox WHERE status IN ('QUEUED','SENDING','RETRY_PENDING')"
            ).fetchone()[0])
            remaining = int(conn.execute(
                "SELECT COUNT(*) FROM telegram_outbox WHERE status IN (?,?)", terminal
            ).fetchone()[0])
            return {"deleted_by_age": deleted_old, "deleted_by_cap": deleted_cap,
                    "terminal_remaining": remaining, "pending_preserved": pending}
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def update_telegram_outbox(outbox_id: str, status: str, attempts: Optional[int] = None,
                               last_error: Optional[str] = None) -> bool:
        oid = str(outbox_id or "").strip()
        if not oid:
            return False
        now = datetime.now(timezone.utc).isoformat()
        conn = None
        try:
            path = str(CONFIG.get("DB_PATH") or "./unified_scalper.db")
            conn = sqlite3.connect(path, timeout=5.0)
            conn.execute("PRAGMA busy_timeout=5000")
            if attempts is None:
                cur = conn.execute("UPDATE telegram_outbox SET status=?,updated_at=?,last_error=? WHERE outbox_id=?",
                                   (str(status), now, str(last_error or "")[:240] or None, oid))
            else:
                cur = conn.execute("UPDATE telegram_outbox SET status=?,attempts=?,updated_at=?,last_error=? WHERE outbox_id=?",
                                   (str(status), max(0, int(attempts)), now, str(last_error or "")[:240] or None, oid))
            conn.commit()
            return bool(cur.rowcount)
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    # ---------------------------------------------------------------------
    # v4.2.2 FIX — ASYNC NON-BLOCKING WRAPPERS.
    # The sync methods above use the stdlib sqlite3 driver, which is fully
    # BLOCKING. Calling them directly inside the asyncio event loop (run_bot,
    # PositionManager.tick, _finalize_and_record_r, ...) stalls the whole
    # loop for the duration of the disk I/O. The wrappers below offload each
    # call to a worker thread via asyncio.to_thread(...), preserving the
    # exact same semantics / ordering guarantees while keeping the loop hot.
    # ---------------------------------------------------------------------
    @staticmethod
    async def ainit_schema() -> None:
        await asyncio.to_thread(DBManager.init_schema)

    @staticmethod
    async def asave_trade_snapshot(trade: "TradeState") -> None:
        await asyncio.to_thread(DBManager.save_trade_snapshot, trade)

    @staticmethod
    async def arecover_active_trades() -> Dict[str, "TradeState"]:
        return await asyncio.to_thread(DBManager.recover_active_trades)

    @staticmethod
    async def asave_finalized_trade_id(trade_id: str, symbol: str = "", reason: str = "") -> None:
        await asyncio.to_thread(DBManager.save_finalized_trade_id, trade_id, symbol, reason)

    @staticmethod
    async def arecover_finalized_trade_ids() -> set:
        return await asyncio.to_thread(DBManager.recover_finalized_trade_ids)

    @staticmethod
    async def asave_daily_state(date: str, realized_r: float, daily_trades: int, blocked_reason: Optional[str],
                                 consecutive_losses: int = 0, loss_streak_block_until: float = 0.0) -> None:
        await asyncio.to_thread(DBManager.save_daily_state, date, realized_r, daily_trades, blocked_reason,
                                consecutive_losses, loss_streak_block_until)

    @staticmethod
    async def aload_daily_state(date: Optional[str] = None) -> Optional[Dict[str, Any]]:
        return await asyncio.to_thread(DBManager.load_daily_state, date)

    @staticmethod
    def save_daily_state(date: str, realized_r: float, daily_trades: int, blocked_reason: Optional[str],
                         consecutive_losses: int = 0, loss_streak_block_until: float = 0.0) -> None:
        conn = None
        try:
            path = CONFIG["DB_PATH"]
            conn = sqlite3.connect(path)
            c = conn.cursor()
            payload = {
                "date": date,
                "realized_r": float(realized_r),
                "daily_trades": int(daily_trades),
                "blocked_reason": blocked_reason,
                "consecutive_losses": int(consecutive_losses),
                "loss_streak_block_until": float(loss_streak_block_until),
            }
            now = datetime.now(timezone.utc).isoformat()
            c.execute("""INSERT OR REPLACE INTO daily_state
                (date, realized_r, daily_trades, blocked, snapshot_json, updated_at)
                VALUES (?, ?, ?, ?, ?, ?)""",
                      (date, float(realized_r), int(daily_trades),
                       1 if blocked_reason else 0, json.dumps(payload), now))
            conn.commit()
        except Exception as e:
            logger.debug(f"[DB] save_daily_state: {e}")
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @staticmethod
    def load_daily_state(date: Optional[str] = None) -> Optional[Dict[str, Any]]:
        conn = None
        try:
            target = date or datetime.now(timezone.utc).strftime("%Y-%m-%d")
            path = CONFIG["DB_PATH"]
            conn = sqlite3.connect(path)
            c = conn.cursor()
            c.execute("SELECT date, realized_r, daily_trades, blocked, snapshot_json FROM daily_state WHERE date = ?", (target,))
            row = c.fetchone()
            if not row:
                return None
            d = {"date": row[0], "realized_r": row[1], "daily_trades": row[2], "blocked": row[3]}
            try:
                extra = json.loads(row[4]) if row[4] else {}
                d.update(extra if isinstance(extra, dict) else {})
            except Exception:
                _v647_record_suppressed_exception()
            d["blocked_reason"] = d.get("blocked_reason") or ("persisted_block" if int(d.get("blocked") or 0) else None)
            return d
        except Exception as e:
            logger.debug(f"[DB] load_daily_state: {e}")
            return None
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass


def _v702_r4_loss_streak_self_test() -> Dict[str, Any]:
    """Deterministic, network-free regression for the R4 consecutive-loss throttle.

    The throttle is portfolio-state only: one loss causes a short pause, two
    consecutive losses cause a longer pause, and any non-loss realized outcome
    clears the streak. State must survive persistence through the existing
    daily_state snapshot without changing the table schema.
    """
    checks: Dict[str, bool] = {}
    details: Dict[str, Any] = {}
    old_db = CONFIG.get("DB_PATH")
    _selftest_log_context_token = V702_SELFTEST_LOG_CONTEXT.set(True)
    old_state = {
        "date": DailyCircuitBreaker._date,
        "realized_r": DailyCircuitBreaker._realized_r,
        "trades": DailyCircuitBreaker._trades,
        "blocked_reason": DailyCircuitBreaker._blocked_reason,
        "consecutive_losses": DailyCircuitBreaker._consecutive_losses,
        "loss_streak_block_until": DailyCircuitBreaker._loss_streak_block_until,
    }
    tmp_path = ""
    try:
        checks["enabled"] = bool(CONFIG.get("V702_LOSS_STREAK_COOLDOWN_ENABLE", False))
        checks["threshold"] = int(CONFIG.get("MAX_CONSECUTIVE_LOSSES", 0)) == 2
        checks["first_cooldown"] = float(CONFIG.get("V702_LOSS_STREAK_FIRST_LOSS_COOLDOWN_SEC", 0)) > 0
        checks["hard_cooldown"] = float(CONFIG.get("V702_LOSS_STREAK_HARD_COOLDOWN_SEC", 0)) >= float(CONFIG.get("V702_LOSS_STREAK_FIRST_LOSS_COOLDOWN_SEC", 0))
        if not all(checks.values()):
            return {"pass": False, "checks": checks, "details": details}

        fd, tmp_path = tempfile.mkstemp(prefix="v702_r4_streak_", suffix=".db")
        os.close(fd)
        CONFIG["DB_PATH"] = tmp_path
        DBManager.init_schema()

        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        DailyCircuitBreaker._date = today
        DailyCircuitBreaker._realized_r = 0.0
        DailyCircuitBreaker._trades = 0
        DailyCircuitBreaker._blocked_reason = None
        DailyCircuitBreaker._consecutive_losses = 0
        DailyCircuitBreaker._loss_streak_block_until = 0.0

        ok0, why0 = DailyCircuitBreaker.can_open_new()
        DailyCircuitBreaker.add_realized_r(-1.0)
        ok1, why1 = DailyCircuitBreaker.can_open_new()
        checks["clean_open"] = bool(ok0 and why0 == "ok")
        checks["first_loss_blocks"] = bool((not ok1) and str(why1).startswith("consecutive_loss_cooldown:"))
        checks["first_loss_counted"] = int(DailyCircuitBreaker._consecutive_losses) == 1

        # Simulate expiry of the first temporary pause, then take a second loss.
        DailyCircuitBreaker._loss_streak_block_until = 0.0
        ok_after_first, _ = DailyCircuitBreaker.can_open_new()
        DailyCircuitBreaker.add_realized_r(-1.05)
        ok2, why2 = DailyCircuitBreaker.can_open_new()
        checks["one_streak_expiry_reopens"] = bool(ok_after_first)
        checks["second_loss_hard_blocks"] = bool((not ok2) and str(why2).startswith("consecutive_loss_cooldown:"))
        checks["second_loss_counted"] = int(DailyCircuitBreaker._consecutive_losses) == 2

        persisted = DBManager.load_daily_state() or {}
        details["persisted"] = {
            "consecutive_losses": int(persisted.get("consecutive_losses") or 0),
            "loss_streak_block_until": float(persisted.get("loss_streak_block_until") or 0.0),
        }
        checks["streak_persisted"] = int(persisted.get("consecutive_losses") or 0) == 2 and float(persisted.get("loss_streak_block_until") or 0.0) > float(WALL_NOW())

        # Any non-loss outcome resets the temporary streak guard.
        DailyCircuitBreaker.add_realized_r(+1.20)
        ok3, why3 = DailyCircuitBreaker.can_open_new()
        checks["non_loss_resets_streak"] = int(DailyCircuitBreaker._consecutive_losses) == 0 and float(DailyCircuitBreaker._loss_streak_block_until or 0.0) == 0.0 and bool(ok3) and why3 == "ok"
        details["realized_r"] = float(DailyCircuitBreaker._realized_r)
        return {"pass": bool(all(checks.values())), "checks": checks, "details": details}
    except Exception as exc:
        checks["exception_free"] = False
        return {"pass": False, "checks": checks, "details": details, "error": f"{type(exc).__name__}:{exc}"}
    finally:
        DailyCircuitBreaker._date = old_state["date"]
        DailyCircuitBreaker._realized_r = old_state["realized_r"]
        DailyCircuitBreaker._trades = old_state["trades"]
        DailyCircuitBreaker._blocked_reason = old_state["blocked_reason"]
        DailyCircuitBreaker._consecutive_losses = old_state["consecutive_losses"]
        DailyCircuitBreaker._loss_streak_block_until = old_state["loss_streak_block_until"]
        CONFIG["DB_PATH"] = old_db
        V702_SELFTEST_LOG_CONTEXT.reset(_selftest_log_context_token)
        if tmp_path:
            for suffix in ("", "-wal", "-shm"):
                try:
                    Path(tmp_path + suffix).unlink(missing_ok=True)
                except Exception:
                    pass

_V702_R4_LOSS_STREAK_SELF_TEST = _v702_r4_loss_streak_self_test()
STATS["v702_r4_loss_streak_self_test"] = _V702_R4_LOSS_STREAK_SELF_TEST


# =============================================================================
#  SECTION 33 — TELEGRAM DISPATCHER (NON-BLOCKING)
# =============================================================================

class TelegramDispatcher:
    _queue: "deque[str]" = deque(maxlen=int(CONFIG["TELEGRAM_RETRY_QUEUE_MAX"]))
    _last_ok_ts: float = 0.0
    _running: bool = False
    _session: Optional["aiohttp.ClientSession"] = None
    _attempts: Dict[str, int] = defaultdict(int)
    _max_attempts: int = 3
    # Delivery acknowledgements are kept separate from the text queue so
    # knowledge-only research records are registered only after Telegram
    # actually accepts the message.  The queue remains string-compatible with
    # all legacy callers.
    _delivery_callbacks: Dict[str, List[Tuple[Any, Any]]] = defaultdict(list)
    _outbox_ids_by_key: Dict[str, deque] = defaultdict(deque)
    _outbox_inflight_keys: set = set()
    _recent_enqueued_keys: Dict[str, float] = {}
    _recent_enqueued_lock = threading.RLock()

    @classmethod
    def _message_key(cls, msg: str) -> str:
        import hashlib
        return hashlib.sha256(str(msg).encode("utf-8", errors="replace")).hexdigest()

    @classmethod
    async def _fire_delivery_callbacks(cls, msg: str, ok: bool, permanent: bool, reason: str = "") -> None:
        key = cls._message_key(msg)
        callbacks = cls._delivery_callbacks.pop(key, [])
        if not callbacks:
            return
        for success_cb, failure_cb in callbacks:
            cb = success_cb if ok else failure_cb if permanent else None
            if not callable(cb):
                continue
            try:
                result = await asyncio.to_thread(cb, reason)
                if asyncio.iscoroutine(result):
                    await result
                STATS["telegram_delivery_callbacks_fired"] = int(STATS.get("telegram_delivery_callbacks_fired", 0) or 0) + 1
            except Exception as exc:
                STATS["telegram_delivery_callback_errors"] = int(STATS.get("telegram_delivery_callback_errors", 0) or 0) + 1
                logger.warning("[Telegram] delivery callback suppressed: %s: %s", type(exc).__name__, exc)

    @classmethod
    def _drop_oldest_with_callbacks(cls):
        """Remove one queued message and return it so enqueue can settle callbacks."""
        try:
            limit = getattr(cls._queue, "maxlen", None)
            if limit is None or limit <= 0 or len(cls._queue) < limit or not cls._queue:
                return None
            oldest = cls._queue.popleft()
            key = cls._message_key(oldest)
            callbacks = cls._delivery_callbacks.get(key, [])
            if callbacks:
                STATS["telegram_delivery_callbacks_evicted"] = int(
                    STATS.get("telegram_delivery_callbacks_evicted", 0) or 0
                ) + len(callbacks)
            return oldest
        except Exception as exc:
            logger.warning("[Telegram] callback eviction bookkeeping suppressed: %s", exc)
            return None

    @classmethod
    async def _ensure_session(cls) -> Optional["aiohttp.ClientSession"]:
        if not _AIOHTTP_OK:
            return None
        if cls._session is None or cls._session.closed:
            timeout = aiohttp.ClientTimeout(total=10)
            cls._session = aiohttp.ClientSession(timeout=timeout)
        return cls._session

    @classmethod
    async def close(cls) -> None:
        try:
            if cls._session is not None and not cls._session.closed:
                await cls._session.close()
        except Exception as e:
            logger.debug(f"[Telegram] session close suppressed: {e}")
        finally:
            cls._session = None

    @classmethod
    async def enqueue(cls, msg: str, on_success=None, on_failure=None):
        if not bool(CONFIG["TELEGRAM_ENABLED"]):
            STATS["telegram_enqueue_disabled"] = STATS.get("telegram_enqueue_disabled", 0) + 1
            if callable(on_failure):
                try:
                    await asyncio.to_thread(on_failure, "telegram_disabled")
                except Exception:
                    STATS["telegram_delivery_callback_errors"] = int(STATS.get("telegram_delivery_callback_errors", 0) or 0) + 1
            return False
        if not ENV.get("TELEGRAM_TOKEN") or not ENV.get("TELEGRAM_CHAT"):
            STATS["telegram_missing_credentials"] = STATS.get("telegram_missing_credentials", 0) + 1
            if callable(on_failure):
                try:
                    await asyncio.to_thread(on_failure, "missing_credentials")
                except Exception:
                    STATS["telegram_delivery_callback_errors"] = int(STATS.get("telegram_delivery_callback_errors", 0) or 0) + 1
            return False
        # Exact duplicate payload suppression is transport-only. Never suppress
        # an enqueue that carries delivery callbacks because those callbacks are
        # part of the outcome/registration contract.
        key = cls._message_key(msg)
        has_callback = callable(on_success) or callable(on_failure)
        if bool(CONFIG.get("V702_TELEGRAM_EXACT_DUPLICATE_SUPPRESS_ENABLE", True)) and not has_callback:
            now_dup = MONO_NOW()
            ttl_dup = max(1.0, float(CONFIG.get("V702_TELEGRAM_EXACT_DUPLICATE_SUPPRESS_SEC", 30.0) or 30.0))
            with cls._recent_enqueued_lock:
                prev_dup = float(cls._recent_enqueued_keys.get(key, 0.0) or 0.0)
                if prev_dup > 0.0 and (now_dup - prev_dup) < ttl_dup:
                    STATS["v702_telegram_exact_duplicate_suppressed"] = int(STATS.get("v702_telegram_exact_duplicate_suppressed", 0) or 0) + 1
                    return False
                cls._recent_enqueued_keys[key] = now_dup
                if len(cls._recent_enqueued_keys) > 2048:
                    cutoff_dup = now_dup - ttl_dup * 4.0
                    for k_dup, ts_dup in list(cls._recent_enqueued_keys.items()):
                        if float(ts_dup or 0.0) < cutoff_dup:
                            cls._recent_enqueued_keys.pop(k_dup, None)
        # Persist before volatile queue admission. This is an at-least-once
        # outbox: a process crash after Telegram accepts but before the DB ACK may
        # replay the same message, which is safer than silent loss.
        # Coalesce an identical payload already queued/in-flight. Attach any
        # semantic callback to the existing delivery instead of creating a
        # second durable row whose callback could be fired by the wrong send.
        _already_pending = key in {cls._message_key(x) for x in list(cls._queue)} or key in cls._outbox_inflight_keys
        if _already_pending:
            if has_callback:
                cls._delivery_callbacks[key].append((on_success, on_failure))
            STATS["v702_a66_telegram_outbox_coalesced"] = int(STATS.get("v702_a66_telegram_outbox_coalesced", 0) or 0) + 1
            return True
        try:
            _outbox_id = await asyncio.to_thread(DBManager.enqueue_telegram_outbox, msg)
            cls._outbox_ids_by_key[key].append(_outbox_id)
        except Exception as _outbox_exc:
            # A failed durable write must not poison the short duplicate-suppress
            # window; callers must be able to retry the same important message.
            with cls._recent_enqueued_lock:
                cls._recent_enqueued_keys.pop(key, None)
            STATS["v702_a66_telegram_outbox_enqueue_blocked"] = int(STATS.get("v702_a66_telegram_outbox_enqueue_blocked", 0) or 0) + 1
            logger.critical("[V702-A66-TG-OUTBOX] message not queued because durable persistence failed: %s", _outbox_exc)
            if callable(on_failure):
                try: await asyncio.to_thread(on_failure, "durable_outbox_persist_failed")
                except Exception: pass
            return False
        # Settle the evicted message's callback before admitting the new item.
        # The old row moves to DEAD_LETTER and the digest callback restores its
        # source window for a fresh message with a new durable id.
        if getattr(cls._queue, "maxlen", None) is not None and cls._queue.maxlen <= 0:
            STATS["telegram_enqueue_zero_capacity"] = int(STATS.get("telegram_enqueue_zero_capacity", 0) or 0) + 1
            try:
                await asyncio.to_thread(DBManager.update_telegram_outbox, _outbox_id, "DEAD_LETTER", 0, "queue_capacity_zero")
            except Exception as _zero_capacity_db_exc:
                logger.critical("[V702-A66-TG-OUTBOX] zero-capacity dead-letter persistence failed: %s", _zero_capacity_db_exc)
            _ids = cls._outbox_ids_by_key.get(key)
            if _ids:
                try: _ids.remove(_outbox_id)
                except ValueError: pass
                if not _ids: cls._outbox_ids_by_key.pop(key, None)
            if callable(on_failure):
                try:
                    await asyncio.to_thread(on_failure, "queue_capacity_zero")
                except Exception:
                    STATS["telegram_delivery_callback_errors"] = int(STATS.get("telegram_delivery_callback_errors", 0) or 0) + 1
            return False
        _evicted_msg = cls._drop_oldest_with_callbacks()
        if _evicted_msg is not None:
            _evicted_key = cls._message_key(_evicted_msg)
            _evicted_ids = cls._outbox_ids_by_key.get(_evicted_key)
            if _evicted_ids:
                _evicted_id = _evicted_ids.popleft()
                if not _evicted_ids:
                    cls._outbox_ids_by_key.pop(_evicted_key, None)
                try:
                    await asyncio.to_thread(DBManager.update_telegram_outbox, _evicted_id, "DEAD_LETTER", None, "queue_evicted")
                except Exception as _evict_db_exc:
                    STATS["v702_a66_telegram_outbox_errors"] = int(STATS.get("v702_a66_telegram_outbox_errors", 0) or 0) + 1
                    logger.critical("[V702-A66-TG-OUTBOX] queue-evicted message state update failed: %s", _evict_db_exc)
            await cls._fire_delivery_callbacks(_evicted_msg, ok=False, permanent=True, reason="queue_evicted")
            STATS["telegram_queue_evicted"] = int(STATS.get("telegram_queue_evicted", 0) or 0) + 1
        if has_callback:
            cls._delivery_callbacks[key].append((on_success, on_failure))
        cls._queue.append(msg)
        STATS["telegram_enqueued"] = STATS.get("telegram_enqueued", 0) + 1
        return True

    @classmethod
    async def _send_one(cls, msg: str) -> Tuple[bool, bool]:
        """Return (ok, permanent_failure)."""
        if not _AIOHTTP_OK:
            return False, False
        sess = await cls._ensure_session()
        if sess is None:
            return False, False
        url = f"https://api.telegram.org/bot{ENV['TELEGRAM_TOKEN']}/sendMessage"
        payload = {"chat_id": ENV["TELEGRAM_CHAT"], "text": msg,
                   "parse_mode": "HTML", "disable_web_page_preview": True}
        try:
            async with sess.post(url, json=payload) as r:
                if r.status == 200:
                    body = ""
                    try:
                        body = await r.text()
                    except Exception:
                        body = ""
                    try:
                        api_obj = json.loads(body) if body else {}
                        if isinstance(api_obj, dict) and api_obj.get("ok") is False:
                            logger.warning("[Telegram] HTTP 200 API-not-ok: %s", body[:240])
                            return False, True
                    except Exception:
                        # Preserve transport-success semantics when the success body
                        # cannot be parsed. V696 performs the same defensive check
                        # with explicit delivery telemetry.
                        pass
                    return True, False
                # 4xx are permanent for the current payload; do not loop forever.
                if 400 <= r.status < 500:
                    try:
                        body = await r.text()
                    except Exception:
                        body = ""
                    logger.warning(f"[Telegram] permanent HTTP {r.status}: {body[:200]}")
                    return False, True
                return False, False
        except Exception as e:
            logger.debug(f"[Telegram] send suppressed: {e}")
            return False, False

    @classmethod
    async def run_forever(cls):
        cls._running = True
        try:
            while cls._running:
                try:
                    if cls._queue:
                        msg = cls._queue.popleft()
                        key = cls._message_key(msg)
                        ok, permanent = await cls._send_one(msg)
                        if ok:
                            cls._last_ok_ts = MONO_NOW()
                            cls._attempts.pop(key, None)
                            await cls._fire_delivery_callbacks(msg, True, False, "delivered")
                        else:
                            cls._attempts[key] += 1
                            if permanent or cls._attempts[key] >= cls._max_attempts:
                                STATS["telegram_drop_permanent"] = STATS.get("telegram_drop_permanent", 0) + 1
                                cls._attempts.pop(key, None)
                                await cls._fire_delivery_callbacks(
                                    msg, False, True, "permanent_failure" if permanent else "retry_exhausted"
                                )
                            else:
                                # bounded retry with a small jitter; never let one bad
                                # payload monopolize the queue forever.
                                cls._queue.appendleft(msg)
                                await asyncio.sleep(2.0 + random.random())
                    await asyncio.sleep(1.0)
                except Exception as e:
                    STATS["telegram_loop_errors"] = STATS.get("telegram_loop_errors", 0) + 1
                    logger.debug(f"[Telegram] loop err: {e}")
                    await asyncio.sleep(2.0)
        finally:
            await cls.close()



# =============================================================================
# v4.5.61 — TELEGRAM REMOTE ORDER CONTROL
# =============================================================================

class TelegramCommandController:
    """Authenticated Telegram command listener for operator-only order control."""

    _running: bool = False
    _offset: Optional[int] = None
    _poll_lock: Optional[asyncio.Lock] = None

    @classmethod
    def _authorized(cls, message: Dict[str, Any]) -> bool:
        """Fail-closed Telegram control authorization.

        The configured chat ID alone is never treated as proof of sender identity.
        Private control is allowed to the chat owner (chat_id == sender_id), or to
        an explicitly allowlisted sender. Group/supergroup control always requires
        TELEGRAM_ALLOWED_USER_IDS. This protects order-control commands from other
        members of a configured group chat.
        """
        try:
            msg = message if isinstance(message, dict) else {}
            chat = msg.get("chat") if isinstance(msg.get("chat"), dict) else {}
            sender = msg.get("from") if isinstance(msg.get("from"), dict) else {}
            configured = str(ENV.get("TELEGRAM_CHAT", "") or "").strip()
            actual_chat = str(chat.get("id", "") or "").strip()
            sender_id = str(sender.get("id", "") or "").strip()
            chat_type = str(chat.get("type", "") or "").strip().lower()
            if not configured or actual_chat != configured or not sender_id:
                return False
            if bool(sender.get("is_bot", False)):
                return False
            raw_allow = str(os.environ.get("TELEGRAM_ALLOWED_USER_IDS", "") or "").strip()
            allowed_users = {token.strip() for token in re.split(r"[,;\s]+", raw_allow) if token.strip()}
            if chat_type == "private":
                return sender_id == actual_chat or sender_id in allowed_users
            return bool(allowed_users) and sender_id in allowed_users
        except Exception:
            return False

    @classmethod
    async def _call_api(cls, method: str, payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        if not _AIOHTTP_OK or not ENV.get("TELEGRAM_TOKEN"):
            return None
        sess = await TelegramDispatcher._ensure_session()
        if sess is None:
            return None
        url = f"https://api.telegram.org/bot{ENV['TELEGRAM_TOKEN']}/{method}"
        try:
            async with sess.post(
                url,
                json=payload,
                timeout=aiohttp.ClientTimeout(total=35),
            ) as r:
                if r.status != 200:
                    body = await r.text()
                    logger.warning(
                        f"[V561-TG] API {method} HTTP {r.status}: {body[:200]}"
                    )
                    return None
                data = await r.json(content_type=None)
                return data if isinstance(data, dict) else None
        except Exception as exc:
            logger.debug(f"[V561-TG] API {method} suppressed: {exc}")
            return None

    @classmethod
    async def _reply(cls, chat_id: Any, text: str) -> None:
        text = str(text or "")[:3500]
        await TelegramDispatcher.enqueue(
            f"<b>V561 CONTROL</b>\n{text}"
        )

    @classmethod
    async def _fetch_open_orders(cls, exchange, symbol: Optional[str] = None) -> List[Dict[str, Any]]:
        try:
            if symbol:
                rows = await safe_api_call(
                    "v561_fetch_open_orders_symbol",
                    lambda: exchange.fetch_open_orders(symbol),
                    retry_safe=True,
                )
            else:
                rows = await safe_api_call(
                    "v561_fetch_open_orders_all",
                    lambda: exchange.fetch_open_orders(),
                    retry_safe=True,
                )
            result = list(rows or []) if isinstance(rows, list) else []
            _scope = str(symbol or "ALL")
            STATS[f"v561_open_orders_status_{_scope}"] = "SUCCESS_ROWS" if result else "SUCCESS_EMPTY"
            STATS[f"v561_open_orders_last_error_{_scope}"] = None
            return result
        except Exception as exc:
            _scope = str(symbol or "ALL")
            STATS[f"v561_open_orders_status_{_scope}"] = "ERROR"
            STATS[f"v561_open_orders_last_error_{_scope}"] = f"{type(exc).__name__}:{str(exc)[:160]}"
            logger.warning(f"[V561-TG] fetch_open_orders failed: {exc}")
            return []

    @classmethod
    def _is_target_sell(cls, order: Dict[str, Any]) -> bool:
        try:
            side = str(order.get("side") or "").lower()
            typ = str(order.get("type") or "").lower()
            return (
                side == "sell"
                and typ in {"limit", "limit_maker", "post_only"}
            )
        except Exception:
            return False

    @classmethod
    async def _cancel_orders_for_symbol(
        cls, exchange, symbol: str, *, all_orders: bool = False
    ) -> Tuple[int, int, List[str]]:
        rows = await cls._fetch_open_orders(exchange, symbol)
        matched = []
        trade = ACTIVE_TRADES.get(symbol)
        owned_ids = set()
        if trade is not None:
            for field in ("sl_order_id", "tp1_order_id", "tp2_order_id", "tp3_order_id"):
                _owned = str(getattr(trade, field, "") or "").strip()
                if _owned:
                    owned_ids.add(_owned)
        for order in rows:
            _oid_candidate = str((order or {}).get("id") or "").strip()
            if all_orders:
                matched.append(order)
            elif cls._is_target_sell(order) and _oid_candidate in owned_ids:
                matched.append(order)

        ok_count = 0
        fail_count = 0
        ids: List[str] = []

        for order in matched:
            oid = str(order.get("id") or "")
            if not oid:
                continue
            ids.append(oid)
            try:
                async with HandoffOwnership.lock_for(symbol):
                    ok = await OrderExecutor.cancel_order_safe(
                        exchange, oid, symbol
                    )
                if ok:
                    ok_count += 1
                else:
                    fail_count += 1
            except Exception as exc:
                fail_count += 1
                logger.warning(
                    f"[V561-TG] cancel failed symbol={symbol} id={oid}: {exc}"
                )

        # Mark the matching live TradeState so PositionManager cannot recreate
        # target LIMITs after the operator deliberately canceled them.
        trade = ACTIVE_TRADES.get(symbol)
        if trade is not None and not all_orders:
            trade.target_recreate_disabled = True
            trade.target_recreate_disabled_ts = WALL_NOW()
            trade.target_recreate_disabled_reason = "telegram_cancel"
            STATS["v561_target_recreate_disabled"] = int(
                STATS.get("v561_target_recreate_disabled", 0) or 0
            ) + 1

        if all_orders and trade is not None:
            trade.target_recreate_disabled = True
            trade.target_recreate_disabled_ts = WALL_NOW()
            trade.target_recreate_disabled_reason = "telegram_cancel_all"
        return ok_count, fail_count, ids

    @classmethod
    async def _cancel_all_target_orders(cls, exchange) -> Tuple[int, int, Dict[str, int]]:
        rows = await cls._fetch_open_orders(exchange, None)
        by_symbol: Dict[str, int] = defaultdict(int)
        ok_count = 0
        fail_count = 0

        # Cancel only target orders owned by this bot's active TradeState.
        # Explicit /cancel_all SYMBOL remains the separately named broad action.
        owned_targets = {}
        for _symbol, _trade in list(ACTIVE_TRADES.items()):
            for _field in ("tp1_order_id", "tp2_order_id", "tp3_order_id"):
                _oid = str(getattr(_trade, _field, "") or "").strip()
                if _oid:
                    owned_targets[_oid] = str(_symbol)
        for order in rows:
            if not cls._is_target_sell(order):
                continue
            symbol = str(order.get("symbol") or "")
            oid = str(order.get("id") or "")
            if not symbol or not oid or owned_targets.get(oid) != symbol:
                continue
            by_symbol[symbol] += 1
            try:
                async with HandoffOwnership.lock_for(symbol):
                    ok = await OrderExecutor.cancel_order_safe(exchange, oid, symbol)
                if ok:
                    ok_count += 1
                else:
                    fail_count += 1
            except Exception:
                fail_count += 1

        for symbol, trade in list(ACTIVE_TRADES.items()):
            if by_symbol.get(symbol, 0) > 0 or bool(getattr(trade, "target_only_mode", False)):
                trade.target_recreate_disabled = True
                trade.target_recreate_disabled_ts = WALL_NOW()
                trade.target_recreate_disabled_reason = "telegram_cancel_all_targets"

        return ok_count, fail_count, dict(by_symbol)

    @classmethod
    async def _format_orders(cls, exchange, symbol: Optional[str]) -> str:
        rows = await cls._fetch_open_orders(exchange, symbol)
        _scope = str(symbol or "ALL")
        _read_status = str(STATS.get(f"v561_open_orders_status_{_scope}", "UNKNOWN") or "UNKNOWN")
        if _read_status == "ERROR":
            _detail = str(STATS.get(f"v561_open_orders_last_error_{_scope}", "read_failed") or "read_failed")
            return f"{_scope}: open orders UNKNOWN (read failed: {_detail[:120]})."
        if not rows:
            return f"{_scope}: no open orders (verified empty)."

        lines = [f"Open orders: {len(rows)}"]
        for o in rows[:20]:
            lines.append(
                f"{o.get('symbol','?')} | {o.get('side','?')} | {o.get('type','?')} | "
                f"qty={o.get('amount','?')} | px={o.get('price','?')} | id={o.get('id','?')}"
            )
        if len(rows) > 20:
            lines.append(f"... +{len(rows)-20} more")
        return "\n".join(lines)

    @classmethod
    async def _handle(cls, exchange, message: Dict[str, Any]) -> None:
        if not cls._authorized(message):
            return

        chat_id = ((message or {}).get("chat") or {}).get("id")
        text = str(((message or {}).get("text") or "")).strip()
        if not text.startswith("/"):
            return

        parts = text.split()
        if not parts:
            return

        command = parts[0].split("@", 1)[0].lower()
        arg = parts[1].upper().replace("-", "/") if len(parts) > 1 else ""

        if command in {"/help", "/commands"}:
            await cls._reply(
                chat_id,
                "/cancel ENA — cancel target LIMIT SELLs for ENA/USDT; "
                "also disables target recreation.\n"
                "/cancel_all_targets — cancel all open target LIMIT SELLs.\n"
                "/cancel_all ENA — cancel ALL open orders for ENA/USDT (dangerous).\n"
                "/orders [ENA] — show open orders.\n"
                "/sl ENA — show active software/native SL state.\n"
                "/ping — control channel test."
            )
            return

        if command == "/ping":
            await cls._reply(chat_id, "OK — Telegram control channel is alive.")
            return

        if command == "/orders":
            symbol = arg if arg else None
            if symbol and "/" not in symbol:
                symbol = f"{symbol}/USDT"
            await cls._reply(chat_id, await cls._format_orders(exchange, symbol))
            return

        if command == "/cancel":
            if not arg:
                await cls._reply(chat_id, "Usage: /cancel ENA")
                return
            symbol = arg if "/" in arg else f"{arg}/USDT"
            okc, failc, ids = await cls._cancel_orders_for_symbol(
                exchange, symbol, all_orders=False
            )
            await cls._reply(
                chat_id,
                f"{symbol}: target SELL cancel result\n"
                f"confirmed={okc} failed_or_unverified={failc}\n"
                f"recreation_disabled=True\n"
                f"ids={','.join(ids) or '-'}"
            )
            return

        if command == "/cancel_all_targets":
            okc, failc, by_symbol = await cls._cancel_all_target_orders(exchange)
            await cls._reply(
                chat_id,
                f"All target LIMIT SELL cancellation\n"
                f"confirmed={okc} failed_or_unverified={failc}\n"
                f"symbols={','.join(sorted(by_symbol)) or '-'}\n"
                "recreation_disabled=True"
            )
            return

        if command == "/cancel_all":
            if not arg:
                await cls._reply(chat_id, "Usage: /cancel_all ENA  (all open orders on ENA/USDT)")
                return
            symbol = arg if "/" in arg else f"{arg}/USDT"
            okc, failc, ids = await cls._cancel_orders_for_symbol(
                exchange, symbol, all_orders=True
            )
            await cls._reply(
                chat_id,
                f"{symbol}: ALL open-order cancellation\n"
                f"confirmed={okc} failed_or_unverified={failc}\n"
                f"ids={','.join(ids) or '-'}"
            )
            return

        if command == "/sl":
            symbol = arg if "/" in arg else f"{arg}/USDT" if arg else ""
            trade = ACTIVE_TRADES.get(symbol) if symbol else None
            if trade is None:
                await cls._reply(chat_id, f"{symbol or 'symbol'}: no ACTIVE_TRADES record.")
            else:
                await cls._reply(
                    chat_id,
                    f"{symbol}\n"
                    f"entry={trade.entry:.10g} current_sl={trade.current_sl:.10g}\n"
                    f"native_sl_id={getattr(trade,'sl_order_id',None) or '-'}\n"
                    f"software_sl_active={getattr(trade,'software_sl_active',False)}\n"
                    f"sl_health={getattr(trade,'sl_health_state','?')}\n"
                    f"target_recreate_disabled={getattr(trade,'target_recreate_disabled',False)}\n"
                    f"sl_failover_count={getattr(trade,'sl_failover_count',0)}\n"
                    f"sl_failover_last_reason={getattr(trade,'sl_failover_last_reason','') or '-'}"
                )
            return

        await cls._reply(chat_id, "Unknown command. Use /help")

    @classmethod
    async def run_forever(cls, exchange):
        if not bool(CONFIG.get("V561_TELEGRAM_COMMANDS_ENABLE", True)):
            return
        if not ENV.get("TELEGRAM_TOKEN") or not ENV.get("TELEGRAM_CHAT"):
            logger.warning("[V561-TG] command control disabled: Telegram credentials missing")
            return

        cls._running = True
        logger.info("[V561-TG] authenticated Telegram command control ACTIVE")
        while cls._running and (_SHUTDOWN is None or not _SHUTDOWN.is_set()):
            try:
                payload = {
                    "timeout": 25,
                    "offset": cls._offset,
                    "allowed_updates": ["message"],
                }
                data = await cls._call_api("getUpdates", payload)
                if not data or not data.get("ok"):
                    await asyncio.sleep(float(CONFIG.get("V561_TELEGRAM_POLL_SEC", 1.0)))
                    continue

                updates = data.get("result") or []
                for upd in updates:
                    try:
                        uid = int(upd.get("update_id"))
                        cls._offset = uid + 1
                        msg = upd.get("message") or {}
                        if cls._authorized(msg):
                            await cls._handle(exchange, msg)
                    except Exception as exc:
                        logger.error(f"[V561-TG] update handling error: {exc}")
            except Exception as exc:
                STATS["v561_telegram_command_errors"] = int(
                    STATS.get("v561_telegram_command_errors", 0) or 0
                ) + 1
                logger.warning(f"[V561-TG] polling error: {exc}")
                await asyncio.sleep(
                    max(1.0, float(CONFIG.get("V561_TELEGRAM_POLL_SEC", 1.0)))
                )

        logger.info("[V561-TG] authenticated Telegram command control STOPPED")



# =============================================================================
# v4.5.23 — OPPORTUNITY-FIRST TELEGRAM NOTIFIER
# =============================================================================
class OpportunityTelegramNotifier:
    """Non-authoritative Telegram notifications for REAL canonical opportunities.

    v4.5.24 closure:
      * BUY alerts are emitted only AFTER the canonical CompositeScorer and
        effective live score floor have passed, immediately before PreSendGate.
      * Global selection alone is NEVER called an opportunity.
      * Blocked alerts are emitted only for an opportunity previously notified
        by the canonical alert path.
      * No method in this class authorizes, sizes, or submits an order.
    """
    _lock = threading.RLock()
    _candidate_seen: Dict[str, float] = {}
    _blocked_seen: Dict[str, float] = {}
    _pending: Dict[str, Dict[str, Any]] = {}

    @classmethod
    def _runtime_allowed(cls) -> bool:
        try:
            if not bool(CONFIG.get("TELEGRAM_OPPORTUNITY_ALERTS_ENABLE", True)):
                return False
            if bool(CONFIG.get("TELEGRAM_OPPORTUNITY_REQUIRE_FULL_LIVE", True)):
                if str(getattr(LIVE_STATE, "current", "")) != "FULL_LIVE_RUNNING":
                    return False
            return bool(CONFIG.get("TELEGRAM_ENABLED", True))
        except Exception:
            return False

    @staticmethod
    def _escape(value: Any) -> str:
        import html
        try:
            return html.escape(str(value), quote=False)
        except Exception:
            return str(value).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    @staticmethod
    def _fmt_px(value: Any) -> str:
        try:
            v = float(value)
            if not math.isfinite(v) or v <= 0:
                return "—"
            if abs(v) >= 1000:
                return f"{v:,.2f}"
            if abs(v) >= 1:
                return f"{v:.6f}".rstrip("0").rstrip(".")
            if abs(v) >= 0.01:
                return f"{v:.8f}".rstrip("0").rstrip(".")
            return f"{v:.10f}".rstrip("0").rstrip(".")
        except Exception:
            return "—"

    @staticmethod
    def _opportunity_key(symbol: str, candle_ts: int, family: str = "") -> str:
        return f"{str(symbol)}|{int(candle_ts)}|{str(family).upper()}"

    @classmethod
    def _dedup_ok(cls, bucket: Dict[str, float], key: str, ttl: float) -> bool:
        now = MONO_NOW()
        with cls._lock:
            prev = float(bucket.get(key, 0.0) or 0.0)
            if prev > 0 and (now - prev) < max(1.0, ttl):
                return False
            bucket[key] = now
            if len(bucket) > 2048:
                cutoff = now - max(60.0, ttl) * 4.0
                for k in list(bucket.keys()):
                    if float(bucket.get(k, 0.0) or 0.0) < cutoff:
                        bucket.pop(k, None)
        return True

    @staticmethod
    def _opportunity_grade(score: float, floor: float, htf: Any, vol: Any, rs: Any,
                           chase: Any, liquidity: Any, family: str = "") -> Tuple[str, float]:
        """Quality label only; it never changes execution authorization."""
        try:
            s=float(score); f=float(floor)
        except Exception:
            return "C", 0.0
        pts=0.0
        if s >= float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_A_PLUS",75.0)): pts+=50
        elif s >= float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_A",70.0)): pts+=43
        elif s >= float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_B",66.0)): pts+=35
        else: pts+=25
        try:
            h=float(htf)
            pts += 18 if h>=90 else 13 if h>=75 else 7 if h>=60 else 0
        except Exception: pass
        try:
            v=float(vol)
            pts += 12 if v>=1.50 else 9 if v>=1.20 else 5 if v>=1.00 else 0
        except Exception: pass
        try:
            r=max(0.0,float(rs))  # LONG-only: negative RS earns no quality bonus
            pts += 10 if r>=0.07 else 7 if r>=0.04 else 4 if r>=0.02 else 0
        except Exception: pass
        try:
            c=float(chase)
            pts += 7 if c<=0.50 else 4 if c<=1.00 else 1 if c<=1.60 else 0
        except Exception: pass
        liq=str(liquidity or "").upper()
        pts += 5 if liq in {"MAJORS","LARGE"} else 3 if liq=="MID" else 0
        fam=str(family or "").upper()
        if fam in {"BREAKOUT_RETEST","MTF_PULLBACK","PULLBACK"} and s>=max(f,70.0):
            pts += 2
        if s >= float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_A_PLUS",75.0)) and pts>=88:
            grade="A+"
        elif s >= float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_A",70.0)) and pts>=76:
            grade="A"
        elif s >= float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_B",66.0)) and pts>=64:
            grade="B"
        else:
            grade="C"
        return grade,min(100.0,pts)

    @classmethod
    def _tradingview_link(cls, symbol: str) -> str:
        """HTTPS universal TradingView link targeting MEXC spot."""
        if not bool(CONFIG.get("TELEGRAM_TV_LINK_ENABLE",True)):
            return ""
        try:
            from urllib.parse import quote
            base,q=str(symbol).split("/",1)
            tvsym=f"MEXC:{base.upper()}{q.upper()}"
            mode=str(CONFIG.get("TELEGRAM_TV_PREFERRED_URL_MODE","chart_symbol")).lower()
            if mode=="symbol_page":
                return f"https://www.tradingview.com/symbols/{quote(tvsym.split(':',1)[1],safe='')}?exchange=MEXC"
            return f"https://www.tradingview.com/chart/?symbol={quote(tvsym,safe='')}"
        except Exception:
            return ""

    @classmethod
    def _telegram_link(cls, opportunity_id: str = "") -> str:
        """Build a Telegram URL without inventing private/numeric chat links."""
        try:
            explicit = str(CONFIG.get("TELEGRAM_OPPORTUNITY_PUBLIC_URL", "") or "").strip()
            if not explicit:
                explicit = str(CONFIG.get("TELEGRAM_PUBLIC_URL", "") or "").strip()
            if explicit:
                return explicit
            public_user = str(CONFIG.get("TELEGRAM_PUBLIC_CHAT_USERNAME", "") or "").strip().lstrip("@")
            if public_user:
                return f"https://t.me/{public_user}"
            chat = str(ENV.get("TELEGRAM_CHAT", "") or "").strip()
            if chat.startswith("@") and len(chat) > 1:
                return f"https://t.me/{chat.lstrip('@')}"
            bot_user = str(CONFIG.get("TELEGRAM_BOT_USERNAME", "") or "").strip().lstrip("@")
            if not bot_user:
                bot_user = str(CONFIG.get("TELEGRAM_CHANNEL_USERNAME", "") or "").strip().lstrip("@")
            if bot_user:
                if opportunity_id:
                    from urllib.parse import quote
                    payload = quote(str(opportunity_id)[:64], safe="")
                    return f"https://t.me/{bot_user}?start={payload}"
                return f"https://t.me/{bot_user}"
            return ""
        except Exception:
            return ""

    @classmethod
    def _mexc_link(cls, symbol: str) -> str:
        if not bool(CONFIG.get("TELEGRAM_MEXC_LINK_ENABLE", True)):
            return ""
        try:
            base, quote = str(symbol).split("/", 1)
            return f"https://www.mexc.com/exchange/{base.upper()}_{quote.upper()}"
        except Exception:
            return ""

    @classmethod
    def _links_html(cls, symbol: str, candle_ts: int, family: str) -> str:
        opportunity_id = f"{str(symbol).replace('/', '')}-{int(candle_ts)}-{str(family).upper()}"
        parts = []
        tv = cls._tradingview_link(symbol)
        if tv:
            label = "📱 TradingView" if bool(CONFIG.get("TELEGRAM_TV_OPEN_APP_HINT",True)) else "📈 TradingView"
            parts.append(f'<a href="{cls._escape(tv)}">{label}</a>')
        tg = cls._telegram_link(opportunity_id)
        if tg:
            parts.append(f'<a href="{cls._escape(tg)}">💬 Telegram</a>')
        mx = cls._mexc_link(symbol)
        if mx:
            parts.append(f'<a href="{cls._escape(mx)}">🟢 MEXC</a>')
        if not parts:
            return "<i>Links: not configured</i>"
        return " | ".join(parts)

    @classmethod
    def _reason_lines(cls, family: str, mode: str, htf: Any, vol: Any, rs: Any,
                      chase: Any, structure: Any, liquidity: Any) -> List[str]:
        reasons = [f"{family} / {mode}"]
        try:
            if htf is not None and math.isfinite(float(htf)):
                reasons.append(f"HTF {float(htf):.0f}")
        except Exception:
            _v647_record_suppressed_exception()
        try:
            if vol is not None and math.isfinite(float(vol)):
                reasons.append(f"Vol x{float(vol):.2f}")
        except Exception:
            _v647_record_suppressed_exception()
        try:
            if rs is not None and math.isfinite(float(rs)):
                reasons.append(f"RS {float(rs)*100:.2f}%")
        except Exception:
            _v647_record_suppressed_exception()
        try:
            if chase is not None and math.isfinite(float(chase)):
                reasons.append(f"Chase {float(chase):.2f} ATR")
        except Exception:
            _v647_record_suppressed_exception()
        try:
            if structure is not None and math.isfinite(float(structure)):
                reasons.append(f"Structure {float(structure):.2f}")
        except Exception:
            _v647_record_suppressed_exception()
        try:
            if liquidity is not None:
                reasons.append(f"Liquidity {str(liquidity)}")
        except Exception:
            _v647_record_suppressed_exception()
        return reasons[:max(1, int(CONFIG.get("TELEGRAM_OPPORTUNITY_MAX_REASONS", 6)))]

    @classmethod
    def _message_from_payload(cls, payload: Dict[str, Any], blocked: bool = False) -> str:
        symbol = str(payload.get("symbol", "") or "")
        candle_ts = int(payload.get("candle_ts", int(WALL_NOW())) or int(WALL_NOW()))
        family = str(payload.get("family", "PULLBACK") or "PULLBACK").upper()
        mode = str(payload.get("mode", family) or family).upper()
        style = str(payload.get("style", "SCALP") or "SCALP").upper()
        score = float(payload.get("score", 0.0) or 0.0)
        floor = float(payload.get("floor", 0.0) or 0.0)
        entry = float(payload.get("entry", 0.0) or 0.0)
        sl = float(payload.get("sl", 0.0) or 0.0)
        tp1 = float(payload.get("tp1", 0.0) or 0.0)
        tp2 = float(payload.get("tp2", 0.0) or 0.0)
        tp3 = float(payload.get("tp3", 0.0) or 0.0)
        rr1 = float(payload.get("rr1", 0.0) or 0.0)
        rr2 = float(payload.get("rr2", 0.0) or 0.0)
        rr3 = float(payload.get("rr3", 0.0) or 0.0)
        regime = str(payload.get("regime", "") or "").upper()
        local = str(payload.get("local", "") or "").upper()
        phase = str(payload.get("phase", "") or "")
        reasons = payload.get("reasons") or []
        opp_id = str(payload.get("opportunity_id", "") or "")
        stage = str(payload.get("stage", "") or "")
        reason = str(payload.get("reason", "") or "")
        grade = str(payload.get("grade", "") or "")
        grade_conf = float(payload.get("grade_confidence", 0.0) or 0.0)
        execution_ready = payload.get("execution_ready")

        if blocked:
            headline = "🟠 <b>HIGH-QUALITY OPPORTUNITY — EXECUTION BLOCKED</b>"
        elif execution_ready is True:
            headline = "🟢 <b>BUY OPPORTUNITY — READY FOR SUBMISSION</b>"
        else:
            headline = "🟢 <b>BUY OPPORTUNITY — PENDING FINAL GATES</b>"
        tf_profile = str(payload.get("timeframe_profile", "") or "").upper()
        _tf_labels = {
            "SWING_PULLBACK": "4H → 1H → 15M",
            "MTF_PULLBACK": "1D → 4H → 15M → 5M",
            "PULLBACK": "15M → 5M",
            "BREAKOUT_RETEST": "15M → 5M",
            "BREAKOUT_CONTINUATION": "15M → 5M",
        }
        if tf_profile and "_" in tf_profile:
            _tf_display = " → ".join(part for part in tf_profile.split("_") if part)
        else:
            _tf_display = _tf_labels.get(family) or ("4H → 1H → 15M" if style == "SWING" else "15M → 5M")
        lines = [
            headline,
            "",
            f"<b>{cls._escape(symbol)}</b>",
            f"Strategy: <b>{cls._escape(family)}</b> / {cls._escape(mode)}",
            f"Style: {cls._escape(style)} | TF: {cls._escape(_tf_display)}",
            "",
            f"Entry: <b>{cls._fmt_px(entry)}</b>",
            f"SL: <b>{cls._fmt_px(sl)}</b>",
            f"TP1: {cls._fmt_px(tp1)}",
            f"TP2: {cls._fmt_px(tp2)}",
            f"TP3: {cls._fmt_px(tp3)}",
            f"RR Ladder: <b>{rr1:.2f}R / {rr2:.2f}R / {rr3:.2f}R</b> | Score: <b>{score:.1f}</b> | Floor: <b>{floor:.1f}</b>",
            (f"Grade: <b>{cls._escape(grade)}</b> | Quality {grade_conf:.0f}/100" if grade else ""),
            f"Execution: <b>{'READY' if execution_ready is True else 'BLOCKED' if execution_ready is False else 'PENDING'} </b>",
            f"Regime: {cls._escape(regime or 'N/A')} | Local: {cls._escape(local or 'N/A')}",
            f"Phase: {cls._escape(phase or 'N/A')}",
        ]
        if reasons:
            lines += ["", "<b>Reasons</b>: " + cls._escape(" | ".join(map(str, reasons)))]
        if blocked:
            lines += [
                f"Stage: <b>{cls._escape(stage or 'unknown')}</b>",
                f"Reason: <b>{cls._escape(reason or 'unknown')}</b>",
                "<i>No order was authorized/sent on this path.</i>",
            ]
        elif execution_ready is True:
            lines += [
                "",
                "<i>Canonical score + PreSend/Balance/SL/economic gates passed. ExecutionFunnel remains the only order authority; READY does not mean filled.</i>",
            ]
        else:
            lines += [
                "",
                "<i>Canonical score gate passed. Final PreSend/Balance/SL/economic/execution gates must pass before submission.</i>",
            ]
        if bool(CONFIG.get("TELEGRAM_INCLUDE_OPPORTUNITY_ID", True)) and opp_id:
            lines.append(f"ID: <code>{cls._escape(opp_id)}</code>")
        lines += ["", cls._links_html(symbol, candle_ts, family)]
        return "\n".join(lines)

    @classmethod
    async def _enqueue_tracked_message(cls, message: str, *, event: str,
                                       symbol: str = "", trace_id: str = "") -> bool:
        """Enqueue a lifecycle alert and record real Telegram delivery outcomes.

        True means the message entered the dispatcher queue, not that Telegram
        accepted it. Delivery callbacks separately record actual ACK/failure.
        """
        event_key = re.sub(r"[^A-Z0-9_]+", "_", str(event or "UNKNOWN").upper())[:64] or "UNKNOWN"
        state = {"success": False, "failure": False}
        def _delivered(reason="delivered"):
            if state["success"] or state["failure"]:
                return None
            state["success"] = True
            STATS["telegram_lifecycle_delivered"] = int(STATS.get("telegram_lifecycle_delivered", 0) or 0) + 1
            STATS[f"telegram_lifecycle_delivered.{event_key}"] = int(STATS.get(f"telegram_lifecycle_delivered.{event_key}", 0) or 0) + 1
            STATS["telegram_lifecycle_last_delivered_ts"] = WALL_NOW()
            logger.info("[TG-LIFECYCLE-DELIVERED] event=%s symbol=%s trace=%s ack=%s", event_key, symbol or "-", trace_id or "-", str(reason or "delivered"))
        def _failed(reason="delivery_failed"):
            if state["success"] or state["failure"]:
                return None
            state["failure"] = True
            why = str(reason or "delivery_failed")[:220]
            STATS["telegram_lifecycle_failed"] = int(STATS.get("telegram_lifecycle_failed", 0) or 0) + 1
            STATS[f"telegram_lifecycle_failed.{event_key}"] = int(STATS.get(f"telegram_lifecycle_failed.{event_key}", 0) or 0) + 1
            STATS["telegram_lifecycle_last_failure"] = {"event": event_key, "symbol": str(symbol or ""), "trace_id": str(trace_id or ""), "reason": why, "ts": WALL_NOW()}
            logger.error("[TG-LIFECYCLE-DELIVERY-FAILED] event=%s symbol=%s trace=%s reason=%s", event_key, symbol or "-", trace_id or "-", why)
        try:
            queued = await TelegramDispatcher.enqueue(str(message), on_success=_delivered, on_failure=_failed)
            if queued is False:
                _failed("enqueue_returned_false")
                return False
            STATS["telegram_lifecycle_enqueued"] = int(STATS.get("telegram_lifecycle_enqueued", 0) or 0) + 1
            STATS[f"telegram_lifecycle_enqueued.{event_key}"] = int(STATS.get(f"telegram_lifecycle_enqueued.{event_key}", 0) or 0) + 1
            return True
        except Exception as exc:
            _failed(f"{type(exc).__name__}:{str(exc)[:180]}")
            return False

    @classmethod
    def _schedule_tracked_message(cls, message: str, *, event: str,
                                  symbol: str = "", trace_id: str = "") -> bool:
        """Schedule an alert from sync call-sites without claiming delivery."""
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            STATS["telegram_tracked_schedule_no_loop"] = int(STATS.get("telegram_tracked_schedule_no_loop", 0) or 0) + 1
            _schedule_log = logger.debug if _v702_selftest_log_context_active() else logger.error
            _schedule_log("[TG-LIFECYCLE-UNSCHEDULED] event=%s symbol=%s trace=%s reason=no_running_loop", event, symbol or "-", trace_id or "-")
            return False
        try:
            loop.create_task(cls._enqueue_tracked_message(message, event=event, symbol=symbol, trace_id=trace_id))
            STATS["telegram_lifecycle_scheduled"] = int(STATS.get("telegram_lifecycle_scheduled", 0) or 0) + 1
            return True
        except Exception as exc:
            STATS["telegram_tracked_schedule_failed"] = int(STATS.get("telegram_tracked_schedule_failed", 0) or 0) + 1
            logger.error("[TG-LIFECYCLE-SCHEDULE-FAILED] event=%s symbol=%s trace=%s error=%s:%s", event, symbol or "-", trace_id or "-", type(exc).__name__, str(exc)[:160])
            return False

    @classmethod
    def notify_canonical(cls, *, symbol: str, candle_ts: int, score: float, floor: float,
                         family: str, mode: str, style: str, entry: float, sl: float,
                         tp1: float, tp2: float, tp3: float, rr1: float, rr2: float, rr3: float,
                         regime: str, local: str, phase: str,
                         features: Optional[Dict[str, Any]] = None,
                         breakdown: Optional[Dict[str, Any]] = None,
                         execution_ready: Optional[bool] = None) -> bool:
        """Emit the only real BUY alert path: after canonical score/floor passes."""
        if not cls._runtime_allowed():
            return False
        try:
            if not all(math.isfinite(float(x)) for x in (score, floor, entry, sl, tp1, tp2, tp3, rr1, rr2, rr3)):
                return False
            if not (entry > sl > 0 and sl < entry < tp1 < tp2 < tp3):
                return False
            min_alert = max(float(floor), float(CONFIG.get("TELEGRAM_OPPORTUNITY_MIN_SCORE", 62.0)))
            if float(score) < min_alert:
                return False

            family = str(family or "PULLBACK").upper()
            mode = str(mode or family).upper()
            key = cls._opportunity_key(symbol, int(candle_ts), family)
            ttl = float(CONFIG.get("TELEGRAM_OPPORTUNITY_DEDUP_SEC", 900))
            if not cls._dedup_ok(cls._candidate_seen, key, ttl):
                STATS["telegram_opportunity_dedup_suppressed"] = STATS.get("telegram_opportunity_dedup_suppressed", 0) + 1
                return False

            fs = dict(features or {})
            bd = dict(breakdown or {})
            _grade, _grade_conf = cls._opportunity_grade(
                score, floor,
                fs.get("htf_strength", fs.get("htf_alignment")),
                fs.get("volume_ratio"),
                fs.get("rs_5m"),
                fs.get("chase_atr"),
                fs.get("liquidity_tier", fs.get("tier")),
                family,
            )
            reasons = cls._reason_lines(
                family, mode,
                fs.get("htf_strength", fs.get("htf_alignment")),
                fs.get("volume_ratio"),
                fs.get("rs_5m"),
                fs.get("chase_atr"),
                bd.get("structure_quality", fs.get("structure_quality")),
                fs.get("liquidity_tier", fs.get("tier")),
            )
            opportunity_id = f"{str(symbol).replace('/', '')}-{int(candle_ts)}-{family}"
            payload = {
                "symbol": str(symbol),
                "candle_ts": int(candle_ts),
                "score": float(score),
                "floor": float(floor),
                "family": family,
                "mode": mode,
                "style": str(style or "SCALP").upper(),
                "entry": float(entry), "sl": float(sl), "tp1": float(tp1),
                "tp2": float(tp2), "tp3": float(tp3),
                "rr1": float(rr1), "rr2": float(rr2), "rr3": float(rr3),
                "regime": str(regime or ""), "local": str(local or ""),
                "phase": str(phase or ""), "reasons": reasons,
                "grade": _grade,
                "grade_confidence": float(_grade_conf),
                # v4.5.86/V700: score/floor is never execution authority; the
                # final live-ready commit supplies execution_ready=True.
                "execution_ready": execution_ready,
                "opportunity_id": opportunity_id,
                "created_wall": WALL_NOW(),
            }
            with cls._lock:
                cls._pending[key] = dict(payload)
                if len(cls._pending) > 512:
                    cutoff = WALL_NOW() - max(60.0, ttl) * 4.0
                    for pk in list(cls._pending.keys()):
                        if float(cls._pending[pk].get("created_wall", 0.0) or 0.0) < cutoff:
                            cls._pending.pop(pk, None)

            _message = cls._message_from_payload(payload, blocked=False)
            _scheduled = cls._schedule_tracked_message(
                _message, event="OPPORTUNITY", symbol=str(symbol), trace_id=opportunity_id
            )
            if not _scheduled:
                # Preserve canonical opportunity evidence for offline/self-test
                # callers, but never claim the alert was scheduled/delivered.
                STATS["telegram_opportunity_schedule_failed"] = int(STATS.get("telegram_opportunity_schedule_failed", 0) or 0) + 1
            STATS["telegram_opportunity_alerts"] = STATS.get("telegram_opportunity_alerts", 0) + 1
            STATS["telegram_last_opportunity_ts"] = WALL_NOW()
            STATS["telegram_last_opportunity_symbol"] = str(symbol)
            return True
        except Exception as exc:
            logger.debug(f"[V524-TG] canonical notify suppressed: {exc}")
            return False

    @classmethod
    def _pending_for(cls, symbol: str, candle_ts: Optional[int]) -> Optional[Tuple[str, Dict[str, Any]]]:
        try:
            with cls._lock:
                candidates = []
                for key, payload in cls._pending.items():
                    if str(payload.get("symbol")) != str(symbol):
                        continue
                    if candle_ts is not None and int(payload.get("candle_ts", -1)) != int(candle_ts):
                        continue
                    candidates.append((key, payload))
                if not candidates:
                    return None
                candidates.sort(key=lambda kv: float(kv[1].get("created_wall", 0.0) or 0.0), reverse=True)
                return candidates[0]
        except Exception:
            return None

    @classmethod
    def pending_metadata(cls, symbol: str, candle_ts: Optional[int] = None) -> Dict[str, Any]:
        pending = cls._pending_for(symbol, candle_ts)
        return dict(pending[1] or {}) if pending else {}

    @classmethod
    async def notify_protection_failure(cls, symbol: str, *, candle_ts: Optional[int],
                                        fill_px: float, reason: str,
                                        grade: str = "", opportunity_id: str = "") -> None:
        if not bool(CONFIG.get("LIVE_ENTRY_SL_FAILURE_TELEGRAM_ENABLE", True)):
            return
        try:
            links=[]
            tv=cls._tradingview_link(symbol)
            tg=cls._telegram_link(opportunity_id)
            if tv: links.append(f'<a href="{cls._escape(tv)}">📱 TradingView</a>')
            if tg: links.append(f'<a href="{cls._escape(tg)}">💬 Telegram</a>')
            mx=cls._mexc_link(symbol)
            if mx: links.append(f'<a href="{cls._escape(mx)}">🟢 MEXC</a>')
            lines=[
                "🔴 <b>LIVE ENTRY PROTECTION FAILURE</b>",
                "",
                f"<b>{cls._escape(symbol)}</b>",
                f"Fill: <b>{cls._fmt_px(fill_px)}</b>",
                f"Grade: <b>{cls._escape(grade or 'N/A')}</b>",
                f"Reason: <b>{cls._escape(reason or 'exchange_sl_unverified')}</b>",
                "<i>Entry filled but exchange SL was not verified. Emergency protection exit was invoked; this was NOT treated as a healthy protected trade.</i>",
            ]
            if opportunity_id: lines.append(f"ID: <code>{cls._escape(opportunity_id)}</code>")
            if links: lines += [""," | ".join(links)]
            await TelegramDispatcher.enqueue("\n".join(lines))
        except Exception as exc:
            logger.debug(f"[V525-TG] protection failure notify suppressed: {exc}")

    @classmethod
    def mark_protection_failed(cls, symbol: str, candle_ts: Optional[int] = None) -> None:
        """Remove a pending opportunity after a protection failure so a second
        generic blocked alert cannot be emitted for the same fill."""
        try:
            with cls._lock:
                for key in list(cls._pending.keys()):
                    payload = cls._pending.get(key) or {}
                    if str(payload.get("symbol")) != str(symbol):
                        continue
                    if candle_ts is not None and int(payload.get("candle_ts",-1)) != int(candle_ts):
                        continue
                    cls._pending.pop(key, None)
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    async def notify_entry_event(cls, trade, event: str, *,
                                 protection: str = "PENDING", extra: str = "") -> None:
        """Report a confirmed fill independently of whether stop protection succeeds."""
        try:
            if not bool(CONFIG.get("TELEGRAM_ENTRY_EVENTS_ENABLE", True)):
                return
            symbol = str(getattr(trade, "symbol", "") or "")
            if not symbol:
                return
            trace_id = str(getattr(trade, "trace_id", "") or "")
            mode = "PAPER" if bool(getattr(trade, "is_paper", False)) else str(getattr(trade, "execution_mode", "LIVE") or "LIVE").upper()
            strategy = str(getattr(trade, "strategy_mode", "UNKNOWN") or "UNKNOWN").upper()
            style = str(getattr(trade, "strategy_style", "SCALP") or "SCALP").upper()
            timeframe = str(getattr(trade, "timeframe_profile", "UNKNOWN") or "UNKNOWN").upper()
            try:
                score = float(getattr(trade, "score", 0.0) or 0.0)
                score_text = f"{score:.1f}" if math.isfinite(score) else "N/A"
            except Exception:
                score_text = "N/A"
            def _positive_finite(value):
                try:
                    number = float(value)
                    return math.isfinite(number) and number > 0.0
                except Exception:
                    return False
            fill_px = getattr(trade, "entry_fill_price", None)
            if not _positive_finite(fill_px):
                fill_px = getattr(trade, "entry", 0.0)
            fill_qty = getattr(trade, "entry_fill_amount", None)
            if not _positive_finite(fill_qty):
                fill_qty = getattr(trade, "remaining_position", 0.0)
            lines = [f"📌 <b>{cls._escape(str(event or 'ENTRY EVENT'))}</b>", "", f"<b>{cls._escape(symbol)}</b>"]
            lines.extend([
                f"Mode: <b>{cls._escape(mode)}</b>",
                f"Strategy: <b>{cls._escape(strategy)}</b> | Style: <b>{cls._escape(style)}</b>",
                f"Timeframes: <b>{cls._escape(timeframe)}</b> | Score: <b>{score_text}</b>",
                f"Actual fill: <b>{cls._fmt_px(fill_px)}</b>",
                f"Filled quantity: <b>{float(fill_qty or 0.0):.10f}</b>",
                f"Fill reconciliation: <b>{cls._escape(str(getattr(trade, 'fill_reconciliation_status', 'UNKNOWN') or 'UNKNOWN'))}</b>",
                f"Stop: <b>{cls._fmt_px(getattr(trade, 'current_sl', 0.0))}</b> | TP1: {cls._fmt_px(getattr(trade, 'tp1', 0.0))}",
                f"TP2: {cls._fmt_px(getattr(trade, 'tp2', 0.0))} | TP3: {cls._fmt_px(getattr(trade, 'tp3', 0.0))}",
                f"Protection state: <b>{cls._escape(str(protection or 'UNKNOWN'))}</b>",
            ])
            _entry_order_ids = list(getattr(trade, "entry_order_ids", []) or [])
            if _entry_order_ids:
                lines.append(f"Order ID(s): <code>{cls._escape(','.join(str(v) for v in _entry_order_ids)[:180])}</code>")
            if trace_id:
                lines.append(f"Trace ID: <code>{cls._escape(trace_id)}</code>")
            if extra:
                lines.append(cls._escape(str(extra)))
            await cls._enqueue_tracked_message(
                "\n".join(lines), event=str(event or "ENTRY_EVENT"),
                symbol=symbol, trace_id=trace_id
            )
        except Exception as exc:
            STATS["telegram_entry_lifecycle_build_errors"] = int(STATS.get("telegram_entry_lifecycle_build_errors", 0) or 0) + 1
            logger.error("[ENTRY-TG-BUILD-FAILED] symbol=%s trace=%s error=%s:%s", str(getattr(trade, "symbol", "") or "-"), str(getattr(trade, "trace_id", "") or "-"), type(exc).__name__, str(exc)[:180])

    @classmethod
    def schedule_entry_event(cls, trade, event: str, *,
                             protection: str = "PENDING", extra: str = "") -> bool:
        """Schedule a fill/protection message without delaying protection placement."""
        try:
            loop = asyncio.get_running_loop()
            loop.create_task(cls.notify_entry_event(trade, event, protection=protection, extra=extra))
            STATS["telegram_entry_lifecycle_scheduled"] = int(STATS.get("telegram_entry_lifecycle_scheduled", 0) or 0) + 1
            return True
        except Exception as exc:
            STATS["telegram_entry_lifecycle_schedule_failed"] = int(STATS.get("telegram_entry_lifecycle_schedule_failed", 0) or 0) + 1
            logger.critical("[ENTRY-TG-UNSCHEDULED] symbol=%s trace=%s event=%s error=%s:%s", str(getattr(trade, "symbol", "") or "-"), str(getattr(trade, "trace_id", "") or "-"), str(event or "ENTRY_EVENT"), type(exc).__name__, str(exc)[:180])
            return False

    @classmethod
    async def notify_exit_event(cls, trade: "TradeState", event: str, *,
                                fill_px: Optional[float] = None,
                                fill_qty: Optional[float] = None,
                                pnl_r: Optional[float] = None,
                                remaining: Optional[float] = None,
                                extra: str = "") -> None:
        """v4.5.26 — compact exit-lifecycle notification; telemetry only."""
        try:
            if not bool(CONFIG.get("TELEGRAM_EXIT_EVENTS_ENABLE", True)):
                return
            symbol = str(getattr(trade, "symbol", "") or "")
            if not symbol:
                return
            event = str(event or "EXIT_EVENT").upper()
            key = f"exit|{symbol}|{event}|{int(float(getattr(trade,'total_sold_qty',0.0) or 0.0)*1e6)}|{int(getattr(trade,'staircase_level_hit',-1) or -1)}"
            if not cls._dedup_ok(cls._blocked_seen, key, float(CONFIG.get("TELEGRAM_EXIT_EVENT_DEDUP_SEC",30))):
                return
            trace_id = str(getattr(trade, "trace_id", "") or "")
            mode = "PAPER" if bool(getattr(trade, "is_paper", False)) else str(getattr(trade, "execution_mode", "LIVE") or "LIVE").upper()
            lines = [f"📌 <b>{cls._escape(event)}</b>", "", f"<b>{cls._escape(symbol)}</b>"]
            lines.append(f"Mode: <b>{cls._escape(mode)}</b>")
            if trace_id:
                lines.append(f"Trace ID: <code>{cls._escape(trace_id)}</code>")
            lines.append(f"Status: <b>{cls._escape(getattr(trade,'status','UNKNOWN'))}</b>")
            lines.append(f"Entry: {cls._fmt_px(getattr(trade,'entry',0.0))}")
            if fill_px is not None and bool(CONFIG.get("TELEGRAM_EXIT_INCLUDE_REAL_FILL", True)):
                lines.append(f"Actual fill: <b>{cls._fmt_px(fill_px)}</b>")
            if fill_qty is not None:
                lines.append(f"Filled qty: {float(fill_qty):.10f}")
            if remaining is not None:
                lines.append(f"Remaining: {float(remaining):.10f}")
            if pnl_r is not None:
                try:
                    lines.append(f"Event R: <b>{float(pnl_r):+.3f}R</b>")
                except Exception:
                    _v647_record_suppressed_exception()
            if extra:
                lines.append(cls._escape(str(extra)))
            links=[]
            if bool(CONFIG.get("TELEGRAM_EXIT_LINKS_ENABLE", True)):
                tv=cls._tradingview_link(symbol)
                tg=cls._telegram_link("")
                mx=cls._mexc_link(symbol)
                if tv: links.append(f'<a href="{cls._escape(tv)}">📱 TradingView</a>')
                if tg: links.append(f'<a href="{cls._escape(tg)}">💬 Telegram</a>')
                if mx: links.append(f'<a href="{cls._escape(mx)}">🟢 MEXC</a>')
            if links: lines += ["", " | ".join(links)]
            _exit_queued = await cls._enqueue_tracked_message(
                "\n".join(lines), event=event, symbol=symbol, trace_id=trace_id
            )
            if not _exit_queued:
                try:
                    with cls._lock:
                        cls._blocked_seen.pop(key, None)
                except Exception:
                    _v647_record_suppressed_exception()
        except Exception as exc:
            STATS["telegram_lifecycle_message_build_errors"] = int(STATS.get("telegram_lifecycle_message_build_errors", 0) or 0) + 1
            logger.error("[TG-LIFECYCLE-BUILD-FAILED] event=%s symbol=%s error=%s:%s", str(event or "UNKNOWN"), str(getattr(trade, "symbol", "") or "-"), type(exc).__name__, str(exc)[:180])

    @classmethod
    def mark_executed(cls, symbol: str, candle_ts: Optional[int] = None) -> None:
        try:
            with cls._lock:
                for key in list(cls._pending.keys()):
                    payload = cls._pending.get(key) or {}
                    if str(payload.get("symbol")) != str(symbol):
                        continue
                    if candle_ts is not None and int(payload.get("candle_ts", -1)) != int(candle_ts):
                        continue
                    cls._pending.pop(key, None)
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def notify_blocked(cls, symbol: str, *, candle_ts: Optional[int] = None,
                       reason: str = "unknown", stage: str = "", score: Optional[float] = None) -> bool:
        if not cls._runtime_allowed() or not bool(CONFIG.get("TELEGRAM_OPPORTUNITY_BLOCKED_ALERT_ENABLE", True)):
            return False
        try:
            pending = cls._pending_for(symbol, candle_ts)
            if pending is None:
                STATS["telegram_blocked_without_pending_suppressed"] = STATS.get("telegram_blocked_without_pending_suppressed", 0) + 1
                return False
            key, payload = pending
            try:
                asyncio.get_running_loop()
            except RuntimeError:
                STATS["telegram_blocked_schedule_no_loop"] = int(STATS.get("telegram_blocked_schedule_no_loop", 0) or 0) + 1
                logger.error("[TG-BLOCKED-UNSCHEDULED] symbol=%s candle_ts=%s stage=%s reason=%s", symbol, candle_ts, stage, reason)
                return False
            blocked_key = f"blocked|{key}|{str(reason)}"
            if not cls._dedup_ok(cls._blocked_seen, blocked_key,
                                 float(CONFIG.get("TELEGRAM_OPPORTUNITY_BLOCKED_DEDUP_SEC", 300))):
                return False
            payload = dict(payload)
            if score is not None:
                try:
                    if math.isfinite(float(score)):
                        payload["score"] = float(score)
                except Exception:
                    _v647_record_suppressed_exception()
            payload["stage"] = str(stage or "unknown")
            payload["reason"] = str(reason or "unknown")
            _message = cls._message_from_payload(payload, blocked=True)
            _scheduled = cls._schedule_tracked_message(
                _message, event="OPPORTUNITY_BLOCKED", symbol=str(symbol),
                trace_id=str(payload.get("opportunity_id", "") or key)
            )
            if not _scheduled:
                STATS["telegram_blocked_schedule_failed"] = int(STATS.get("telegram_blocked_schedule_failed", 0) or 0) + 1
                return False
            with cls._lock:
                cls._pending.pop(key, None)
            STATS["telegram_opportunity_blocked_alerts"] = STATS.get("telegram_opportunity_blocked_alerts", 0) + 1
            STATS["telegram_last_blocked_ts"] = WALL_NOW()
            return True
        except Exception as exc:
            logger.debug(f"[V524-TG] blocked notify suppressed: {exc}")
            return False

    # Backward-compatible API kept for self-tests/callers, but it is
    # intentionally NOT a global-selection trigger anymore.
    @classmethod
    def notify_candidate(cls, ranked: Any) -> bool:
        return False


# =============================================================================
#  SECTION 34 — HEARTBEAT + LIVE READINESS REPORT
# =============================================================================

class Telemetry:

    # ---- v4.0.2 PATCH E.1 / E.6 helpers -------------------------------------
    @staticmethod
    def _top_rejects(n: int) -> List[Tuple[str, int]]:
        """Return top-N rejection (key, count) pairs, most frequent first."""
        try:
            rej = STATS.get("rejections", {})
            items = list(rej.items()) if hasattr(rej, "items") else []
            items.sort(key=lambda kv: kv[1], reverse=True)
            return items[:max(1, int(n))]
        except Exception:
            return []

    @staticmethod
    def _top_rejects_str(n: int) -> str:
        """E.1 — short one-line 'top_rejects=' representation."""
        top = Telemetry._top_rejects(n)
        if not top:
            return "none"
        return " ".join(f"{k}:{v}" for k, v in top)

    @staticmethod
    def _funnel_ratios(f: Dict[str, int]) -> Dict[str, float]:
        """E.6 — percentages between funnel stages (safe against div-by-zero)."""
        g = float(f.get("generated", 0) or 0)
        e = float(f.get("eligible", 0) or 0)
        q = float(f.get("queued", 0) or 0)
        s = float(f.get("sent", 0) or 0)
        def _pct(num: float, den: float) -> float:
            return round((num / den) * 100.0, 2) if den > 0 else 0.0
        return {
            "g_to_e_pct": _pct(e, g),
            "e_to_q_pct": _pct(q, e),
            "q_to_s_pct": _pct(s, q),
            "overall_pct": _pct(s, g),
        }

    @staticmethod
    def _stage_counters() -> Dict[str, int]:
        """E.3 — collect declared stage counters (only non-zero for brevity)."""
        out: Dict[str, int] = {}
        for k in _STAGE_COUNTER_KEYS:
            v = int(STATS.get(k, 0))
            if v:
                out[k] = v
        return out

    # v4.0.8 STARV-E — aggregate top missing score-input fields from the
    # rolling window (bounded read, never blocks). Surfaces feed instability
    # (orderbook / spread / RS / momentum / BTC context) in heartbeat.
    @staticmethod
    def _score_input_missing_top() -> Dict[str, int]:
        try:
            obs = STATS.get("score_input_missing_top")
            if obs is None:
                return {}
            counts: Dict[str, int] = defaultdict(int)
            # dequeue may be updated concurrently — iterate a snapshot list.
            for row in list(obs):
                for k in row.get("missing", []) or []:
                    counts[str(k)] += 1
            # Return top-5 most-missing fields for compact display.
            top = dict(sorted(counts.items(),
                              key=lambda kv: kv[1], reverse=True)[:5])
            return top
        except Exception:
            return {}

    @staticmethod
    def snapshot() -> Dict[str, Any]:
        funnel = {
            "generated": STATS.get("signals_generated", 0),
            "eligible": STATS.get("signals_eligible", 0),
            "queued": STATS.get("signals_queued", 0),
            "sent": STATS.get("signals_sent", 0),
            "failed_send": STATS.get("signals_failed_send", 0),
            # v4.0.8 STARV-B — symbols suppressed by cooldown pre-gates
            # (does NOT inflate G) — kept adjacent for observability.
            "cooldown_skipped": STATS.get("signals_scanned_cooldown_skipped", 0),
        }
        snap: Dict[str, Any] = {
            "ts": time.time(),
            "live_state": LiveStateMachine.snapshot(),
            "reconciler": BalanceReconciler.snapshot(),
            "watchdog": ExchangeWatchdog.snapshot(),
            "latency": APILatencyMonitor.stats(),
            "active_trades_count": len(ACTIVE_TRADES),
            "funnel": funnel,
            "rejections_top": dict(sorted(STATS["rejections"].items(),
                                          key=lambda kv: kv[1], reverse=True)[:10]),
        }
        # v4.0.2 PATCH E.6 — additive fields (never removes anything above)
        try:
            snap["funnel_ratios"] = Telemetry._funnel_ratios(funnel)
            snap["stage_counters"] = Telemetry._stage_counters()
            snap["top_rejects"] = Telemetry._top_rejects(
                int(CONFIG.get("HB_TOP_REJECTS_N", 3))
            )
            snap["regime"] = MarketRegime.snapshot()
            snap["starvation"] = StarvationGuard.snapshot()
            snap["btc_context"] = BTCContext.snapshot()
            # v4.0.8 STARV-E — feed-stability observability
            snap["score_input_missing_top"] = Telemetry._score_input_missing_top()
            snap["score_input_soft_applied"] = int(
                STATS.get("score_input_soft_applied", 0))
            snap["v423_funnel"] = V423Funnel.snapshot()
            snap["v422_near_miss"] = V422NearMiss.snapshot()
            snap["v424_pullback_diagnostics"] = V424PullbackDiagnostics.snapshot()
            snap["mse_status"] = dict(MSE_STATUS)
            snap["mse_funnel"] = {
                "G": int(STATS.get("mse_generated",0) or 0),
                "V": int(STATS.get("mse_hard_valid",0) or 0),
                "R": int(STATS.get("mse_ranked",0) or 0),
                "W": int(STATS.get("mse_winners",0) or 0),
                "fallback": int(MSE_STATUS.get("fallback_count",0) or 0),
            }
        except Exception as _e:
            snap["telemetry_ext_error"] = str(_e)[:180]
        return snap

    @staticmethod
    async def emit_heartbeat():
        snap = Telemetry.snapshot()
        n_top = int(CONFIG.get("HB_TOP_REJECTS_N", 3))
        top_str = Telemetry._top_rejects_str(n_top)
        regime_cur = snap.get("regime", {}).get("current", "?")
        starv = snap.get("starvation", {})
        starv_flag = ""
        if starv.get("qs_consec_stuck_min", 0) >= 2:
            starv_flag = f" starv_qs={starv.get('qs_consec_stuck_min')}m"
        elif starv.get("ge_blind_alerts_emitted", 0) > 0:
            starv_flag = f" starv_ge_blind={starv.get('ge_blind_alerts_emitted')}"

        # v4.0.8 STARV-B/E — cooldown_skipped + score-input feed instability
        # surfaced next to the funnel line so operators can see if G is being
        # suppressed by cooldown vs by feed problems.
        cd_skipped = snap['funnel'].get('cooldown_skipped', 0)
        _mt = snap.get("score_input_missing_top") or {}
        _pd = snap.get("v424_pullback_diagnostics") or {}
        if _pd:
            logger.info(f"[HB-PULLBACK] rejects={_pd.get("total_events",0)} top={_pd.get("top_reasons",{})} near={_pd.get("near_miss_rate_pct",0)}%")
        _mt_line = ""
        if _mt:
            _mt_line = " score_missing=" + ",".join(f"{k}:{v}" for k, v in _mt.items())
        # v4.2.1 UNBLOCK-PATCH — starvation diagnostics appended to the HB
        # line (purely additive, never blocks execution):
        #   * nfm: cumulative no_family_matched rejects (router stage)
        #   * relaxed: RELAXED_MODE state + remaining TTL seconds
        #   * reentry: up to 3 symbols with remaining reentry cooldown time
        _nfm_hb = int(STATS.get("no_family_matched_count", 0) or 0)
        _relax_hb = ""
        try:
            _rl_until = float(_V420State.relaxed_mode_until_ts or 0.0)
            if _rl_until > 0:
                _rl_rem = max(0, int(_rl_until - MONO_NOW()))
                _relax_hb = f" relaxed={'ON' if _rl_rem > 0 else 'expired'}({_rl_rem}s)"
        except Exception:
            _relax_hb = ""
        _reentry_hb = ""
        try:
            _now_hb = MONO_NOW()
            _re_items = []
            for _sym_hb, _ent_hb in list(COOLDOWNS.get("reentry", {}).items()):
                try:
                    if isinstance(_ent_hb, tuple) and len(_ent_hb) == 2:
                        _arm_hb, _cd_hb = float(_ent_hb[0] or 0.0), float(_ent_hb[1] or 0.0)
                    else:
                        _arm_hb = float(_ent_hb or 0.0)
                        _cd_hb = float(CONFIG.get("REENTRY_COOLDOWN_SEC", 0) or 0)
                    _rem_hb = int(_cd_hb - (_now_hb - _arm_hb))
                    if _rem_hb > 0:
                        _re_items.append((_rem_hb, _sym_hb))
                except Exception:
                    continue
            if _re_items:
                _re_items.sort(reverse=True)
                _reentry_hb = " reentry=" + ",".join(
                    f"{s}:{r}s" for r, s in _re_items[:3])
        except Exception:
            _reentry_hb = ""
        # v4.2.5 — informative heartbeat: surface macro severity, local regime,
        # NFM ratio, bearish-recovery funnel and watchdog state so operators
        # can interpret a long BEARISH market beyond "nfm=1809".
        _sev_hb = STATS.get("v425_macro_severity", "?")
        _loc_hb = STATS.get("v425_local_regime", STATS.get("v45_last_local_regime", "UNKNOWN"))
        _nfmr_hb = STATS.get("v425_nfm_ratio", 0.0)
        try:
            _truth_hb_fn = globals().get("_v699_truthful_starvation_snapshot")
            _truth_hb = dict(_truth_hb_fn() or {}) if callable(_truth_hb_fn) else {}
            _truth_root_hb = str(_truth_hb.get("root") or "NONE").upper()
            _starv_mode_hb = "NONE" if _truth_root_hb in ("", "NONE") else f"{_truth_root_hb}_STARVATION"
        except Exception:
            _starv_mode_hb = STATS.get("v425_starvation_mode", "NONE")
        _brc = int(STATS.get("bearish_recovery_candidates", 0) or 0)
        _brq = int(STATS.get("bearish_recovery_qualified", 0) or 0)
        _brr = int(STATS.get("bearish_recovery_rejects", 0) or 0)
        _brb = int(STATS.get("bearish_recovery_crash_blocks", 0) or 0)
        _wdt = int(STATS.get("watchdog_ticks", 0) or 0)
        _wdtrig = int(STATS.get("watchdog_triggers", 0) or 0)
        _wd_snap_hb = dict(snap.get("watchdog") or {})
        _wd_reason_hb = str(_wd_snap_hb.get("reason") or "")[:90] or "-"
        _wd_recent_hb = int(_wd_snap_hb.get("recent_errors_count", 0) or 0)
        _tech_starv = int(STATS.get("technical_starvation_events", 0) or 0)
        _mse_stat = str(MSE_STATUS.get("status", "DEGRADED"))
        _mse_fb = int(MSE_STATUS.get("fallback_count", 0) or 0)
        _fG = int(snap['funnel'].get('generated',0) or 0)
        _fE = int(snap['funnel'].get('eligible',0) or 0)
        _fQ = int(snap['funnel'].get('queued',0) or 0)
        _fS = int(snap['funnel'].get('sent',0) or 0)
        _rat_ge = (100.0*_fE/_fG) if _fG else 0.0
        _rat_eq = (100.0*_fQ/_fE) if _fE else 0.0
        _rat_qs = (100.0*_fS/_fQ) if _fQ else 0.0
        _opp_starv = int(STATS.get("opportunity_starvation_events", 0) or 0)
        _div = int(STATS.get("bearish_policy_divergence", 0) or 0)
        try:
            _mse_display_cycle_hb = dict(_v684_public_cycle() if callable(globals().get("_v684_public_cycle")) else {})
        except Exception:
            _mse_display_cycle_hb = {}
        _mse_cg = int(_mse_display_cycle_hb.get("generated", STATS.get("v648_cycle_mse_generated", 0)) or 0)
        _mse_cp = int(_mse_display_cycle_hb.get("prequal", STATS.get("v648_cycle_mse_prequalified", 0)) or 0)
        _mse_cr = int(_mse_display_cycle_hb.get("ranked", STATS.get("v648_cycle_mse_ranked", 0)) or 0)
        _mse_cs = int(_mse_display_cycle_hb.get("selected", STATS.get("v648_cycle_mse_selected", 0)) or 0)
        _mse_cq = int(_mse_display_cycle_hb.get("queued", STATS.get("v648_cycle_mse_queued", 0)) or 0)
        _mse_ct = int(_mse_display_cycle_hb.get("sent", STATS.get("v648_cycle_mse_sent", 0)) or 0)
        _root_hb = dict(STATS.get("v647_root_cause") or {})
        # V701: the operator-visible heartbeat root must come from the same
        # terminal active-cycle truth used by Starvation Alert. Legacy
        # v647_root_cause remains a compatibility fallback only.
        _truth_hb = {}
        try:
            _truth_fn_hb = globals().get("_v699_truthful_starvation_snapshot")
            _truth_hb = dict(_truth_fn_hb() or {}) if callable(_truth_fn_hb) else {}
        except Exception:
            _truth_hb = {}
        _root_mode_hb = str(_truth_hb.get("root") or _root_hb.get("mode") or "NONE")
        _root_reason_hb = str(_truth_hb.get("detail") or _truth_hb.get("source") or _root_hb.get("reason") or "-")[:110]
        _bridge_ca = int(STATS.get("v596_bridge_cycle_attempts", 0) or 0)
        _bridge_cr = int(STATS.get("v596_bridge_cycle_ready", 0) or 0)
        _bridge_cs = int(STATS.get("v596_bridge_cycle_sent", 0) or 0)
        _bridge_cb = int(STATS.get("v596_bridge_cycle_blocks", 0) or 0)
        line = (f"[HB] state={snap['live_state']['current']} "
                f"trades={snap['active_trades_count']} "
                f"funnel G/E/Q/S={snap['funnel']['generated']}/"
                f"{snap['funnel']['eligible']}/{snap['funnel']['queued']}/"
                f"{snap['funnel']['sent']} "
                f"exec_try={int(STATS.get('v535_execution_attempts',0) or 0)} "
                f"exec_try_scope=ROUTE_ATTEMPTS "
                f"exec_try_cycle={int(STATS.get('v535_cycle_execution_attempts',0) or 0)} "
                f"live_ready={int(STATS.get('v534_live_ready',0) or 0)} "
                f"live_ready_scope=EPOCH_TOTAL "
                f"send_fail={int(STATS.get('v535_send_failures',0) or 0)} "
                f"ambig={int(STATS.get('v535_ambiguous_execution_blocks',0) or 0)} "
                f"bal_retry={int(STATS.get('v535_balance_same_candidate_retry',0) or 0)} "
                f"refill={int(STATS.get('v535_same_symbol_alternate_promotions',0) or 0)} "
                f"prot={int(STATS.get('signals_protected', 0) or 0)} "
                f"prot_soft={int(STATS.get('signals_protected_software', 0) or 0)} "
                f"prot_fail={int(STATS.get('signals_protection_failed', 0) or 0)} "
                f"pm_mode={ProductionCapabilityGate.stop_mode() or 'UNKNOWN'} "
                f"dd_halt=0 "
                f"cd_skip={cd_skipped} "
                f"regime={regime_cur} sev={_sev_hb} local={_loc_hb} "
                f"watchdog={snap['watchdog']['tripped']} wd_reason={_wd_reason_hb} wd_err={_wd_recent_hb} "
                f"ticks={_wdt} trig={_wdtrig}{starv_flag}{_mt_line}"
                f" nfm={_nfm_hb} nfm_ratio={_nfmr_hb}{_relax_hb}{_reentry_hb}"
                f" brc={_brc} brq={_brq} brr={_brr} brb={_brb}"
                f" starv_mode={_starv_mode_hb} tech_starv={_tech_starv}"
                f" opp_starv={_opp_starv} pol_div={_div}"
                f" mse_cycle={_mse_cg}/{_mse_cp}/{_mse_cr}/{_mse_cs}/{_mse_cq}/{_mse_ct}"
                f" root={_root_mode_hb}:{_root_reason_hb}"
                f"{_v43_hb_segment() if bool(CONFIG.get('V43_ADAPTIVE_ROUTER_ENABLE', True)) else ''}"
                f" mse_rank_starv={int(int(STATS.get('v681_runtime_cycle_generated',0) or 0)>0 and int(STATS.get('v681_runtime_cycle_raw_ranked',0) or 0)==0)}"
                f" mse_rank_top={str(sorted(((str(k),int(v or 0)) for k,v in (STATS.get('v681_runtime_cycle_rank_reject_reasons',{}) or {}).items() if int(v or 0)>0),key=lambda kv:(-kv[1],kv[0]))[:5])[:240]}"
                f" v596_bridge_cycle={_bridge_ca}/{_bridge_cr}/{_bridge_cs}/{_bridge_cb}"
                f" bridge_total={int(STATS.get('v596_bridge_attempts',0) or 0)}/"
                f"{int(STATS.get('v596_bridge_ready',0) or 0)}/"
                f"{int(STATS.get('v596_bridge_sent',0) or 0)}")
        # v4.0.2 PATCH E.1 — top_rejects line (log + Telegram)
        top_line = f"[HB] top_rejects_scope=CUMULATIVE_DIAGNOSTIC top_rejects={top_str}"
        try:
            _v545_r = STATS.get("v545_jit_advisory_reasons") or {}
            _v545_top = sorted(_v545_r.items(), key=lambda kv: kv[1], reverse=True)[:int(CONFIG.get("V545_HB_TOP_BLOCKERS",3))]
            _v545_top_s = ",".join(f"{k}:{v}" for k,v in _v545_top) or "-"
            logger.info(
                f"[V545-HANDOFF] jit_pass={int(STATS.get('v545_jit_advisory_pass',0) or 0)} "
                f"jit_block={int(STATS.get('v545_jit_advisory_block',0) or 0)} "
                f"builder_block={int(STATS.get('v545_builder_blocker',0) or 0)} "
                f"cycle_ready={int(STATS.get('v545_cycle_live_ready',0) or 0)} "
                f"cycle_builder_block={int(STATS.get('v545_cycle_builder_blocks',0) or 0)} "
                f"handoff_pool={int(STATS.get('v546_pending_count',0) or 0)} "
                f"handoff_try={int(STATS.get('v546_cycle_handoff_attempts',0) or 0)} "
                f"handoff_ok={int(STATS.get('v546_cycle_handoff_successes',0) or 0)} "
                f"last={STATS.get('v545_last_builder_blocker','-')} top={_v545_top_s}"
            )
        except Exception:
            _v647_record_suppressed_exception()
        try:
            logger.info(
                f"[V547-CYCLE] selected_to_exec={int(STATS.get('v547_cycle_selected_to_exec',0) or 0)} "
                f"pending_to_exec={int(STATS.get('v547_cycle_pending_to_exec',0) or 0)} "
                f"reserve_to_exec={int(STATS.get('v547_cycle_reserve_to_exec',0) or 0)} "
                f"builder_calls={int(STATS.get('v547_cycle_builder_calls',0) or 0)} "
                f"builder_blocks={int(STATS.get('v547_cycle_builder_blocks',0) or 0)} "
                f"live_ready={int(STATS.get('v547_cycle_live_ready_delta',0) or 0)} "
                f"queued={int(STATS.get('v547_cycle_queued_delta',0) or 0)} "
                f"sent={int(STATS.get('v547_cycle_sent_delta',0) or 0)} "
                f"score_blocks={int(STATS.get('v547_cycle_score_blocks',0) or 0)} "
                f"liquidity_blocks={int(STATS.get('v547_cycle_liquidity_blocks',0) or 0)} "
                f"execution_blocks={int(STATS.get('v547_cycle_execution_blocks',0) or 0)} "
                f"other_blocks={int(STATS.get('v547_cycle_other_blocks',0) or 0)}")
        except Exception:
            _v647_record_suppressed_exception()
        logger.info(line)
        logger.info(top_line)
        # Non-blocking: enqueue is a bounded deque; heartbeat never blocks loop.
        try:
            await TelegramDispatcher.enqueue(
                f"<b>Heartbeat</b>\n<code>{line}</code>\n<code>{top_line}</code>"
            )
        except Exception as _e:
            logger.debug(f"[HB] telegram enqueue suppressed: {_e}")


# =============================================================================
#  SECTION 34.5 — MULTI-STRATEGY CANDIDATE ENGINE (v4.0.7-MSE additive layer)
# =============================================================================
#
#  Additive / minimal-diff / fail-closed layer added on top of v4.0.6.
#
#  Purpose
#  -------
#  Convert the single-winner OpportunityRouter into a Multi-Candidate
#  Generation stage while preserving ONE unified execution funnel.
#
#      Multi-Strategy here means:
#          Multi-Candidate Generation + Unified Ranking + Single Execution Funnel
#      NOT Multi-Execution.
#
#  Hard invariants preserved (checked at boot):
#     * LONG_ONLY spot execution — every StrategyCandidate.side is "long".
#     * Single execution funnel — engines produce candidates ONLY. They MUST
#       NOT touch ACTIVE_TRADES, balance truth, exposure truth, order state,
#       or SL/TP execution.
#     * fail-closed SL chain — any missing / NaN / non-positive SL, entry or
#       TP1 causes the candidate to be dropped before ranking.
#     * fee viability — the canonical SizingEngine.fee_viability_ok is reused
#       verbatim through a thin wrapper (no parallel logic).
#     * canonical TP1_RR — every engine builds TP1 from CONFIG["TP1_RR"] only.
#     * exposure / balance truth — ExposureProtection + BalanceReconciler
#       remain the ONLY authorities; the MSE never queries or mutates them.
#     * Existing AdaptiveRepricing / RiskCoherence / PreSendGate / SizingEngine
#       / OrderExecutor / PositionManager semantics are untouched — the MSE
#       returns a chosen family/zone_ref that flows through the same builder.
#
#  Integration point
#  -----------------
#  SignalBuilder.build_and_route calls MultiStrategyEngine.pick_opportunity
#  RIGHT BEFORE OpportunityRouter.classify. On any failure or when the
#  layer is disabled via CONFIG["MSE_ENABLED"]=False, we fall back to the
#  legacy router — behaviour then is byte-for-byte identical to v4.0.6.
# =============================================================================


# ---- CONFIG defaults (registered lazily so no diff in the main CONFIG dict) --
def _mse_register_defaults() -> None:
    """Register MSE config defaults if not already present. Idempotent."""
    defaults = {
        # Master switch. False => layer is inert, legacy router is used.
        "MSE_ENABLED": True,
        # Shadow mode: run the layer but DO NOT use its winner; still emit
        # telemetry so operators can compare before flipping MSE_ENABLED live.
        "MSE_SHADOW_MODE": False,
        # Top-N kept per symbol pass (usually 1 — one entry per symbol per
        # scanner tick). Kept as a config knob for future multi-symbol batches.
        "MSE_TOP_N": 1,
        # Composite weights (must sum to 1.0; validated at boot).
        "MSE_W_ENGINE_SCORE":    0.35,
        "MSE_W_RR_RATIO":        0.25,
        "MSE_W_LIQUIDITY":       0.20,
        "MSE_W_REGIME_FIT":      0.20,
        # RR capping (raw rr_ratio divided by this before entering the score).
        "MSE_RR_CAP":            3.0,
        # Per-engine enable flags.
        "MSE_ENGINE_MTF_PULLBACK":      True,
        "MSE_ENGINE_MEASURED_MOVE":     True,
        "MSE_ENGINE_PULLBACK":         True,
        "MSE_ENGINE_BREAKOUT":         True,
        "MSE_ENGINE_LIQ_SWEEP":        True,
        # V638: professional candle/liquidity confluence for the existing
        # LIQUIDITY_SWEEP_REVERSAL family. Disabled only for rollback; when
        # enabled it remains read-only and still flows through all canonical
        # ranking / risk / PreSend / execution gates.
        "V638_LIQ_SWEEP_CONFLUENCE_ENABLE": True,
        "V638_LIQ_SWEEP_LOOKBACK_15M": 20,
        "V638_LIQ_SWEEP_MIN_LOWER_WICK_RATIO": 0.55,
        "V638_LIQ_SWEEP_MIN_CLOSE_LOCATION": 0.62,
        "V638_LIQ_SWEEP_MIN_VOLUME_RATIO": 1.10,
        "V638_LIQ_SWEEP_MIN_BODY_RATIO": 0.10,
        "V638_LIQ_SWEEP_MAX_SWEEP_ATR": 1.50,
        "V638_LIQ_SWEEP_REQUIRE_BULLISH_CLOSE": True,
        "V638_LIQ_SWEEP_REQUIRE_RECLAIM": True,
        "V638_LIQ_SWEEP_REQUIRE_VOLUME": True,
        "V638_LIQ_SWEEP_REQUIRE_WICK": True,
        "V638_LIQ_SWEEP_SCORE_BASE": 0.68,
        "V638_LIQ_SWEEP_SCORE_WICK": 0.10,
        "V638_LIQ_SWEEP_SCORE_VOLUME": 0.08,
        "V638_LIQ_SWEEP_SCORE_CLOSE": 0.06,
        "V638_LIQ_SWEEP_SCORE_RECLAIM": 0.04,
        "V638_LIQ_SWEEP_SCORE_BULLISH": 0.04,
        "V638_LIQ_SWEEP_SCORE_MAX": 0.92,
        "MSE_ENGINE_MEAN_REVERSION":   True,
        "MSE_ENGINE_TREND_CONT":       True,
        # Circuit breaker per engine.
        "MSE_ENGINE_CB_MAX_ERRORS": 5,       # errors within window
        "MSE_ENGINE_CB_WINDOW_SEC": 60.0,    # rolling window
        "MSE_ENGINE_CB_COOLDOWN_SEC": 180.0, # auto-recover after
        # Diversity bonus (small, bounded).
        "MSE_DIVERSITY_BONUS_PCT": 0.0,
    }
    for k, v in defaults.items():
        if k not in CONFIG:
            CONFIG[k] = v


_mse_register_defaults()


# ---- Canonical Candidate schema ---------------------------------------------
@dataclass(frozen=True)
class StrategyCandidate:
    """Frozen, side-effect-free candidate produced by a strategy engine.

    Engines MUST return only this shape (or an empty list). Anything else is
    dropped by the aggregator, per fail-closed policy.
    """
    engine_id: str                  # "pullback" | "breakout" | "liq_sweep" |
                                    # "mean_reversion" | "trend_cont"
    symbol: str
    side: str                       # invariant: MUST equal "long"
    generated_at_ms: int

    entry_ref: float                # reference entry (typically last close)
    sl_price: float                 # fail-closed hard SL
    tp1_rr: float                   # strategy-native RR; revalidated by canonical economic gates
    tp2_rr: float
    tp3_rr: float

    engine_score: float             # 0..1 — engine's own confidence
    rr_ratio: float                 # raw (entry-sl to tp1) R:R
    liquidity_score: float          # 0..1
    regime_fit: float               # 0..1

    # Family identifier consumed by the downstream builder to preserve the
    # exact existing pipeline semantics (BOS hard gates, family restrictions,
    # sweep flags, zone_ref math). Must be one of the OpportunityRouter
    # canonical family names.
    family: str
    zone_ref: float

    # Frozen provenance / soft warnings (audit trail only).
    features_snapshot: Dict[str, Any] = field(default_factory=dict)
    reject_reasons: Tuple[str, ...] = ()

    strategy_mode: str = ""
    strategy_style: str = "SCALP"
    market_phase: str = "UNKNOWN"
    macro_regime: str = ""
    local_regime: str = ""
    bearish_severity: str = ""
    timeframe_profile: str = ""
    quality_grade: str = "C"


@dataclass
class EngineHealth:
    engine_id: str
    enabled: bool = True
    errors_in_window: int = 0
    total_errors: int = 0
    total_generated: int = 0
    circuit_tripped_until: float = 0.0
    last_error: str = ""

    def is_tripped(self) -> bool:
        return MONO_NOW() < self.circuit_tripped_until


# ---- Engine registry / telemetry --------------------------------------------
class _MSEState:
    """Module-level MSE state (health, per-engine counters, rolling errors).

    NOT a general orchestrator — pure telemetry / circuit-breaker state.
    """
    health: Dict[str, EngineHealth] = {}
    error_ts: Dict[str, "deque[float]"] = {}  # engine_id -> deque of ts

    # Per-run funnel counters (reset per pick_opportunity call).
    last_run_counts: Dict[str, Any] = {
        "generated": {},
        "passed_fee": {},
        "passed_invariants": {},
        "rejected": {},
        "reject_reasons": defaultdict(int),
        "winners": [],
    }

    @classmethod
    def ensure(cls, engine_id: str) -> EngineHealth:
        h = cls.health.get(engine_id)
        if h is None:
            h = EngineHealth(engine_id=engine_id)
            cls.health[engine_id] = h
            cls.error_ts[engine_id] = deque(maxlen=256)
        return h

    @classmethod
    def register_error(cls, engine_id: str, err: str) -> None:
        h = cls.ensure(engine_id)
        h.total_errors += 1
        h.last_error = err[:200]
        window = float(CONFIG.get("MSE_ENGINE_CB_WINDOW_SEC", 60.0))
        max_errs = int(CONFIG.get("MSE_ENGINE_CB_MAX_ERRORS", 5))
        cooldown = float(CONFIG.get("MSE_ENGINE_CB_COOLDOWN_SEC", 180.0))
        dq = cls.error_ts[engine_id]
        now = MONO_NOW()
        dq.append(now)
        # Prune
        while dq and (now - dq[0]) > window:
            dq.popleft()
        h.errors_in_window = len(dq)
        if h.errors_in_window >= max_errs:
            h.circuit_tripped_until = now + cooldown
            STATS[f"mse_engine_cb_tripped.{engine_id}"] = \
                STATS.get(f"mse_engine_cb_tripped.{engine_id}", 0) + 1
            logger.warning(
                f"[MSE] engine={engine_id} circuit-tripped for {cooldown:.0f}s "
                f"(errors_in_window={h.errors_in_window}/{max_errs}) "
                f"last_error={h.last_error}"
            )
            dq.clear()

    @classmethod
    def reset_run_counts(cls) -> None:
        cls.last_run_counts = {
            "generated": defaultdict(int),
            "passed_fee": defaultdict(int),
            "passed_invariants": defaultdict(int),
            "rejected": defaultdict(int),
            "reject_reasons": defaultdict(int),
            "ranked": 0,
            "conflict_lost": 0,
            "winners": [],
        }


# v4.5.78 — canonical pullback stop helper.
# The stop remains fail-closed and bounded by the pre-existing MAX_SL_PCT
# ceiling. For PULLBACK/MTF_PULLBACK only, prefer protection below the actual
# pullback structure instead of a blind entry-minus-ATR stop.
def _v579_confirmed_pullback_swing_low(df_5m, lookback_bars: int = 7,
                                      zone_ref: Optional[float] = None,
                                      atr: Optional[float] = None) -> Optional[float]:
    """Return the most recent confirmed closed-bar swing low inside a bounded window."""
    try:
        if df_5m is None or len(df_5m) < 7:
            return None
        n = max(5, min(12, int(lookback_bars)))
        left = max(1, int(CONFIG.get("V579_PULLBACK_SWING_PIVOT_LEFT", 1)))
        right = max(1, int(CONFIG.get("V579_PULLBACK_SWING_PIVOT_RIGHT", 1)))
        zone_val = None
        atr_val = None
        try:
            if zone_ref is not None:
                z0 = float(zone_ref)
                if math.isfinite(z0) and z0 > 0:
                    zone_val = z0
            if atr is not None:
                a0 = float(atr)
                if math.isfinite(a0) and a0 > 0:
                    atr_val = a0
        except Exception:
            _v647_record_suppressed_exception()
        # Work only on CLOSED candles. Exclude the live candle at -1.
        closed_lows = [float(x) for x in df_5m["low"].iloc[-(n + 1):-1]]
        if len(closed_lows) < (left + right + 3):
            return None
        pivots = []
        last_idx = len(closed_lows) - right - 1
        for i in range(left, last_idx + 1):
            v = closed_lows[i]
            if not math.isfinite(v) or v <= 0:
                continue
            left_vals = closed_lows[i-left:i]
            right_vals = closed_lows[i+1:i+1+right]
            if not left_vals or not right_vals:
                continue
            if v <= min(left_vals) and v <= min(right_vals) and (v < min(left_vals) or v < min(right_vals)):
                if zone_val is not None and atr_val is not None:
                    max_below = max(0.50, float(CONFIG.get("V581_PULLBACK_SWING_MAX_BELOW_ZONE_ATR", 1.60)))
                    if (zone_val - v) / atr_val > max_below:
                        continue
                pivots.append((i, v))
        if not pivots:
            return None
        # Prefer the most recent confirmed pivot, not the absolute lowest wick.
        return float(pivots[-1][1])
    except Exception:
        return None


def _v578_pullback_stop(df_5m, entry: float, atr: float, zone_ref: Optional[float] = None) -> Optional[float]:
    """Canonical bounded structural SL for PULLBACK / MTF_PULLBACK."""
    try:
        if not bool(CONFIG.get("V578_PULLBACK_STRUCTURAL_SL_ENABLE", True)):
            sl = entry - float(CONFIG.get("ATR_SL_MULT", 1.2)) * atr
            return float(sl) if math.isfinite(sl) and sl > 0 and sl < entry else None
        if not (math.isfinite(float(entry)) and math.isfinite(float(atr)) and entry > 0 and atr > 0):
            return None

        min_atr = max(0.50, float(CONFIG.get("V578_PULLBACK_SL_MIN_ATR", 1.00)))
        max_atr = max(min_atr, float(CONFIG.get("V578_PULLBACK_SL_MAX_ATR", 1.80)))
        base_atr = max(min_atr, min(max_atr, float(CONFIG.get("ATR_SL_MULT", 1.2))))
        atr_sl = entry - base_atr * atr

        structural_refs = []
        if zone_ref is not None:
            z = float(zone_ref)
            if math.isfinite(z) and 0 < z < entry:
                structural_refs.append(
                    z - float(CONFIG.get("V578_PULLBACK_SL_ZONE_BUFFER_ATR", 0.20)) * atr
                )

        swing_low = _v579_confirmed_pullback_swing_low(
            df_5m, int(CONFIG.get("V579_PULLBACK_SWING_LOOKBACK_BARS", 7)),
            zone_ref=zone_ref, atr=atr
        )
        if swing_low is not None and 0 < swing_low < entry:
            structural_refs.append(
                swing_low - float(CONFIG.get("V579_PULLBACK_SWING_BUFFER_ATR", 0.10)) * atr
            )

        # Preserve a conservative fallback for symbols that have no clean
        # confirmed pivot; the validated zone can still define invalidation.
        if not structural_refs:
            sl = atr_sl
        else:
            # Protection must sit BELOW the structural invalidation, therefore
            # select the wider valid stop and then enforce the hard envelope.
            sl = min([atr_sl] + [x for x in structural_refs if math.isfinite(x) and x > 0 and x < entry])

        max_sl_pct = float(CONFIG.get("MAX_SL_PCT", 1.8))
        min_allowed_sl = entry * (1.0 - max_sl_pct / 100.0)
        if sl < min_allowed_sl:
            return None
        if (entry - sl) / atr > max_atr + 1e-9:
            return None
        if sl <= 0 or sl >= entry:
            return None
        if bool(CONFIG.get("V581_PULLBACK_REQUIRE_SL_BELOW_ZONE", True)) and zone_ref is not None:
            zf = float(zone_ref)
            if math.isfinite(zf) and zf > 0 and sl >= zf:
                return None
        return float(sl)
    except Exception:
        return None


def _v580_pullback_entry_zone_ok(entry: float, atr: float, zone_ref: Optional[float], df_5m=None) -> Tuple[bool, str]:
    """Final-entry coherence guard for PULLBACK/MTF_PULLBACK.

    The setup is supposed to buy a controlled recovery from a validated zone,
    not convert into a late chase after adaptive repricing. This helper is
    deliberately narrow: it does not loosen any other hard gate and it fails
    closed on invalid numeric state.
    """
    try:
        if not bool(CONFIG.get("V580_PULLBACK_ENTRY_ZONE_ENABLE", True)):
            return True, "disabled"
        if not (math.isfinite(float(entry)) and math.isfinite(float(atr)) and entry > 0 and atr > 0):
            return False, "invalid_entry_or_atr"
        if zone_ref is None:
            return False, "zone_missing"
        z = float(zone_ref)
        if not (math.isfinite(z) and z > 0):
            return False, "zone_invalid"
        max_above_atr = max(0.20, float(CONFIG.get("V580_PULLBACK_MAX_ENTRY_ABOVE_ZONE_ATR", 1.20)))
        if entry < z:
            zone_gap_atr = (z - entry) / atr
            max_below_atr = max(0.20, float(CONFIG.get("V581_PULLBACK_MAX_ENTRY_BELOW_ZONE_ATR", 0.75)))
            if zone_gap_atr > max_below_atr + 1e-9:
                return False, f"entry_below_zone:{zone_gap_atr:.3f}ATR>max={max_below_atr:.3f}ATR"
        else:
            zone_gap_atr = (entry - z) / atr
            if zone_gap_atr > max_above_atr + 1e-9:
                return False, f"entry_above_zone:{zone_gap_atr:.3f}ATR>max={max_above_atr:.3f}ATR"
        # Final chase guard is intentionally stricter than the broad family
        # envelope. It only rejects a reprice that materially moved away from
        # the original pullback thesis.
        if df_5m is not None and len(df_5m) >= 2:
            lc = float(df_5m["close"].iloc[-2])
            if math.isfinite(lc) and lc > 0:
                chase_atr = abs(entry - lc) / atr
                max_chase = max(0.30, float(CONFIG.get("V580_PULLBACK_FINAL_MAX_CHASE_ATR", 0.90)))
                if chase_atr > max_chase + 1e-9:
                    return False, f"final_chase:{chase_atr:.3f}ATR>max={max_chase:.3f}ATR"
        return True, f"zone_gap={zone_gap_atr:.3f}ATR"
    except Exception as exc:
        return False, f"exception:{type(exc).__name__}"

# v4.5.80 — remaining PULLBACK coherence closure (additive/fail-closed):
#   * Shallow retracement is supporting evidence, never standalone confirmation.
#   * Confirmed closed-bar swing-low preferred for PULLBACK structural SL.
#   * Repricing re-applies the structural SL using the final entry.
#   * Existing single JIT transient spread recheck remains in place; no new
#     spread relaxation and tier hard gate remains authoritative.

# ---- Strategy engines --------------------------------------------------------
# Each engine is a pure candidate GENERATOR. It:
#   * Reuses existing OpportunityDetectors for the raw structural detection
#     (no parallel indicator math — respects "no new layer" rule).
#   * Computes SL/TP1/TP2/TP3 with the CANONICAL formulas (same as the
#     builder), so the downstream pipeline sees identical geometry.
#   * Emits engine_score / regime_fit / liquidity_score as normalized 0..1
#     signals sourced from the same market snapshot the builder already has.
#   * MUST NOT call the exchange, mutate ACTIVE_TRADES, place orders, touch
#     balance/exposure, or execute anything.

class _EngineBase:
    engine_id: str = "base"
    family_map: Tuple[str, ...] = ()

    @classmethod
    def _config_enabled(cls) -> bool:
        return True

    @classmethod
    def enabled(cls) -> bool:
        h = _MSEState.ensure(cls.engine_id)
        if h.is_tripped():
            return False
        return bool(cls._config_enabled())

    @classmethod
    def _canonical_levels(cls, entry: float, sl: float) -> Tuple[float, float, float]:
        tp1 = entry + float(CONFIG["TP1_RR"]) * (entry - sl)
        tp2 = entry + float(CONFIG["TP2_RR"]) * (entry - sl)
        tp3 = entry + float(CONFIG["TP3_RR"]) * (entry - sl)
        return tp1, tp2, tp3

    @classmethod
    def _atr_and_entry(cls, df_5m) -> Tuple[Optional[float], Optional[float]]:
        try:
            a = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
            idx = -2 if bool(CONFIG.get("MSE_USE_CLOSED_BAR_ENTRY", True)) else -1
            atr_val = float(a.iloc[idx]) if a is not None else 0.0
            if atr_val <= 0 or math.isnan(atr_val):
                return None, None
            entry = float(df_5m["close"].iloc[idx])
            if entry <= 0 or math.isnan(entry):
                return None, None
            return atr_val, entry
        except Exception:
            return None, None

    @classmethod
    def _regime_fit(cls, regime: str, family: str) -> float:
        """0..1 alignment score between BTC regime and the family.

        Mirrors the builder's BEARISH soft-gate: reversion / sweep families
        keep a higher fit under bearish; structural longs get a lower one.
        """
        r = (regime or "").upper()
        f = (family or "").upper()
        if r in ("BULLISH", ""):
            return 1.0
        if r == "NEUTRAL":
            return 0.75
        # BEARISH
        if f in ("LIQUIDITY_SWEEP_REVERSAL", "MEAN_REVERSION"):
            return 0.55
        # v4.3 local-opportunity families are explicitly designed to exploit
        # strong symbol-relative behavior inside non-crash bearish regimes.
        # They remain policy-gated and CrashGuard-protected; this is ranking
        # fit, not permission.
        if f == "LOCAL_STRENGTH_BREAKOUT":
            return 0.75
        if f == "COMPRESSION_EXPANSION":
            return 0.65
        if f == "EXTREME_FLUSH_REVERSAL":
            return 0.70
        return 0.0  # other structural longs in bearish — down-weighted

    @classmethod
    def _liquidity_score(cls, tier: str) -> float:
        """0..1 from LiquidityTier classification (no OB fetch here)."""
        t = (tier or "").upper()
        if t in ("TIER_S", "TIER_A", "S", "A"):
            return 1.0
        if t in ("TIER_B", "B"):
            return 0.8
        if t in ("TIER_C", "C"):
            return 0.6
        return 0.4

    @classmethod
    def generate(cls, mkt_snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        raise NotImplementedError



class MTFPullbackEngine(_EngineBase):
    engine_id = "mtf_pullback"
    family_map = ("MTF_PULLBACK",)

    @classmethod
    def _config_enabled(cls) -> bool:
        return bool(CONFIG.get("MSE_ENGINE_MTF_PULLBACK", True)) and bool(CONFIG.get("MTF_PULLBACK_ENABLE", True))

    @classmethod
    def generate(cls, mkt_snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        matched, meta = OpportunityDetectors.detect_mtf_pullback(
            mkt_snapshot.get("df_1d"), mkt_snapshot.get("df_4h"),
            mkt_snapshot.get("df_15m"), mkt_snapshot.get("df_5m"))
        if not matched:
            return []
        atr_val, entry = cls._atr_and_entry(mkt_snapshot.get("df_5m"))
        if atr_val is None or entry is None:
            return []
        _d15 = mkt_snapshot.get("df_15m")
        _a15s = Indicators.atr(_d15, int(CONFIG.get("ATR_PERIOD",14))) if _d15 is not None else None
        _a15 = float(_a15s.iloc[-2]) if _a15s is not None and len(_a15s)>2 else 0.0
        sl = _v702_mtf_structural_sl(_d15, entry, _a15, meta.get("zone_ref")) if _a15>0 else None
        if sl is None:
            sl = _v578_pullback_stop(df_5m=mkt_snapshot.get("df_5m"), entry=entry,
                                     atr=atr_val, zone_ref=meta.get("zone_ref"))
        if sl is None:
            return []
        # Canonical MTF-PULLBACK is a SWING_EARLY strategy. Use its native exit
        # profile at the source so downstream metadata and geometry cannot diverge.
        profile = StrategyExitProfiles.profile_for("MTF_PULLBACK", "SWING")
        if not profile.validate():
            return []
        risk = max(entry - sl, 1e-9)
        tp1 = entry + profile.tp1_rr * risk
        tp2 = entry + profile.tp2_rr * risk
        tp3 = entry + profile.tp3_rr * risk
        rr = profile.tp1_rr
        sub = str(meta.get("sub", "B")).upper()
        dist = float(meta.get("dist_atr", 0.5))
        base = {"A": 0.97, "B": 0.91, "C": 0.84}.get(sub, 0.84)
        engine_score = min(1.0, base + max(0.0, 0.05 - min(0.05, dist * 0.03)))
        fs = {
            "sub": sub, "dist_atr": dist, "anchor": meta.get("anchor"),
            "d1_trend": meta.get("d1_trend"), "h4_trend": meta.get("h4_trend"),
            "rsi_5m": meta.get("rsi_5m"), "volume_ratio": meta.get("volume_ratio"),
            "atr": atr_val, "entry_ref": entry, "strategy_mode": "MTF_PULLBACK",
            "strategy_style": "SWING", "timeframe_profile": "1D_4H_15M_5M",
            "exit_profile": asdict(profile), "execution_quality": 0.80,
            "macro_regime": mkt_snapshot.get("macro_regime", mkt_snapshot.get("regime", "")),
            "local_regime": mkt_snapshot.get("local_regime", ""),
            "bearish_severity": mkt_snapshot.get("bearish_severity", mkt_snapshot.get("macro_severity", "")),
            "htf_strength": mkt_snapshot.get("htf_strength"),
            "mtf_sl_source": "15M_structural_invalidation" if (_a15 > 0 and _v702_mtf_structural_sl(_d15, entry, _a15, meta.get("zone_ref")) is not None) else "5M_V578_fallback",
            "family_native_sl_ref": float(meta.get("zone_ref", entry)),
        }
        return [StrategyCandidate(
            engine_id=cls.engine_id, symbol=mkt_snapshot["symbol"], side="long",
            generated_at_ms=int(time.time() * 1000), entry_ref=entry, sl_price=sl,
            tp1_rr=float(profile.tp1_rr), tp2_rr=float(profile.tp2_rr), tp3_rr=float(profile.tp3_rr),
            engine_score=engine_score, rr_ratio=rr,
            liquidity_score=cls._liquidity_score(mkt_snapshot.get("tier", "")),
            regime_fit=cls._regime_fit(mkt_snapshot.get("regime", ""), "MTF_PULLBACK"),
            family="MTF_PULLBACK", zone_ref=float(meta.get("zone_ref", entry)),
            features_snapshot=fs, strategy_mode="MTF_PULLBACK", strategy_style="SWING",
            market_phase=str(((mkt_snapshot.get("market_phase") or {}).get("phase", "")
                              if isinstance(mkt_snapshot.get("market_phase"), dict) else (mkt_snapshot.get("market_phase") or "UNKNOWN"))),
            macro_regime=str(mkt_snapshot.get("macro_regime", mkt_snapshot.get("regime", "")) or ""),
            local_regime=str(mkt_snapshot.get("local_regime", "") or ""),
            bearish_severity=str(mkt_snapshot.get("bearish_severity", mkt_snapshot.get("macro_severity", "")) or ""),
            timeframe_profile="1D_4H_15M_5M", quality_grade=("A+" if engine_score >= 0.85 else "A" if engine_score >= 0.75 else "B"),
        )]


class PullbackEngine(_EngineBase):
    engine_id = "pullback"
    family_map = ("PULLBACK",)

    @classmethod
    def _config_enabled(cls) -> bool:
        return bool(CONFIG.get("MSE_ENGINE_PULLBACK", True))

    @classmethod
    def generate(cls, mkt_snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        df_15m = mkt_snapshot.get("df_15m")
        df_5m = mkt_snapshot.get("df_5m")
        matched, meta = OpportunityDetectors.detect_pullback(df_15m, df_5m)
        if not matched:
            return []
        atr_val, entry = cls._atr_and_entry(df_5m)
        if atr_val is None or entry is None:
            return []
        sl = _v578_pullback_stop(df_5m=df_5m, entry=entry, atr=atr_val,
                                zone_ref=meta.get("zone_ref"))
        if sl is None:
            return []
        profile = StrategyExitProfiles.profile_for("PULLBACK", "SCALP")
        if not profile.validate():
            return []
        tp1 = entry + profile.tp1_rr * (entry - sl)
        tp2 = entry + profile.tp2_rr * (entry - sl)
        tp3 = entry + profile.tp3_rr * (entry - sl)
        rr = profile.tp1_rr
        # Engine confidence: A/B/C sub-grade + tightness to EMA50.
        sub = str(meta.get("sub", "C")).upper()
        base = {"A": 0.90, "B": 0.75, "C": 0.55}.get(sub, 0.5)
        dist_atr = float(meta.get("dist_atr", 1.0))
        tight_bonus = max(0.0, min(0.1, (1.0 - dist_atr) * 0.1))
        engine_score = min(1.0, base + tight_bonus)
        return [StrategyCandidate(
            engine_id=cls.engine_id, symbol=mkt_snapshot["symbol"], side="long",
            generated_at_ms=int(time.time() * 1000),
            entry_ref=entry, sl_price=sl,
            tp1_rr=float(profile.tp1_rr),
            tp2_rr=float(profile.tp2_rr),
            tp3_rr=float(profile.tp3_rr),
            engine_score=engine_score, rr_ratio=rr,
            liquidity_score=cls._liquidity_score(mkt_snapshot.get("tier", "")),
            regime_fit=cls._regime_fit(mkt_snapshot.get("regime", ""), "PULLBACK"),
            family="PULLBACK",
            zone_ref=float(meta.get("zone_ref", entry)),
            features_snapshot={"exit_profile": asdict(profile), "sub": sub, "dist_atr": dist_atr,
                               "strategy_mode": "PULLBACK", "strategy_style": "SCALP", "timeframe_profile": "15M_5M",
                               "atr": atr_val, "entry_ref": entry},
        )]


class BreakoutEngine(_EngineBase):
    engine_id = "breakout"
    family_map = ("BREAKOUT_RETEST", "BREAKOUT_CONTINUATION")

    @classmethod
    def _config_enabled(cls) -> bool:
        return bool(CONFIG.get("MSE_ENGINE_BREAKOUT", True))

    @classmethod
    def generate(cls, mkt_snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        df_15m = mkt_snapshot.get("df_15m")
        df_5m = mkt_snapshot.get("df_5m")
        out: List[StrategyCandidate] = []
        # v4.2.8 measured-move specialization shares BREAKOUT_RETEST
        # execution semantics; downstream gates remain authoritative.
        if bool(CONFIG.get("MSE_ENGINE_MEASURED_MOVE", True)):
            mm_ok, mm = OpportunityDetectors.detect_measured_move_breakout(df_15m, df_5m)
            if mm_ok:
                atr_val, entry = cls._atr_and_entry(df_5m)
                if atr_val is not None and entry is not None:
                    sl = entry - float(CONFIG["ATR_SL_MULT"]) * atr_val
                    profile = StrategyExitProfiles.profile_for("MEASURED_MOVE", "SCALP")
                    if not profile.validate():
                        return out
                    tp1 = entry + profile.tp1_rr * (entry - sl)
                    tp2 = entry + profile.tp2_rr * (entry - sl)
                    tp3 = entry + profile.tp3_rr * (entry - sl)
                    rr = profile.tp1_rr
                    mm_rr=float(mm.get("measured_rr",0.0))
                    rr_q=_clamp((mm_rr-float(CONFIG.get("MEASURED_MOVE_MIN_TARGET_RR",2.4)))/2.0,0.0,1.0)
                    vol_q=_clamp((float(mm.get("volume_ratio",1.05))-1.05)/0.95,0.0,1.0)
                    engine_score=min(1.0,0.86+0.08*rr_q+0.06*vol_q)
                    out.append(StrategyCandidate(
                        engine_id="measured_move", symbol=mkt_snapshot["symbol"], side="long",
                        generated_at_ms=int(time.time()*1000), entry_ref=entry, sl_price=sl,
                        tp1_rr=float(profile.tp1_rr), tp2_rr=float(profile.tp2_rr), tp3_rr=float(profile.tp3_rr),
                        engine_score=engine_score, rr_ratio=rr,
                        liquidity_score=cls._liquidity_score(mkt_snapshot.get("tier","")),
                        regime_fit=cls._regime_fit(mkt_snapshot.get("regime",""),"BREAKOUT_RETEST"),
                        family="BREAKOUT_RETEST", zone_ref=float(mm.get("zone_ref",entry)),
                        features_snapshot={
                            "exit_profile":asdict(profile),
                            "strategy_mode":"MEASURED_MOVE","measured_target":mm.get("measured_target"),
                            "measured_rr":mm_rr,"impulse_leg":mm.get("impulse_leg"),"impulse_atr":mm.get("impulse_atr"),
                            "pattern_contraction_pct":mm.get("pattern_contraction_pct"),"volume_ratio":mm.get("volume_ratio"),
                            "body_ratio":mm.get("body_ratio"),"breakout_excess_atr":mm.get("breakout_excess_atr"),
                            "target_vs_tp3_atr":mm.get("target_vs_tp3_atr"),"strategy_style":"SCALP",
                            "timeframe_profile":"15M_5M","atr":atr_val,"entry_ref":entry},
                    ))
        for family, det in (
            ("BREAKOUT_RETEST",
             lambda: OpportunityDetectors.detect_breakout_retest(df_15m, df_5m)),
            ("BREAKOUT_CONTINUATION",
             lambda: OpportunityDetectors.detect_breakout_continuation(df_15m, df_5m)),
        ):
            matched, meta = det()
            if not matched:
                continue
            atr_val, entry = cls._atr_and_entry(df_5m)
            if atr_val is None or entry is None:
                continue
            sl = entry - float(CONFIG["ATR_SL_MULT"]) * atr_val
            profile = StrategyExitProfiles.profile_for(family, "SCALP")
            if not profile.validate():
                continue
            tp1 = entry + profile.tp1_rr * (entry - sl)
            tp2 = entry + profile.tp2_rr * (entry - sl)
            tp3 = entry + profile.tp3_rr * (entry - sl)
            rr = profile.tp1_rr
            # Retest scores slightly higher than continuation by default —
            # continuation catches parabolic legs which are more prone to
            # false continuation. Both are bounded.
            base = 0.78 if family == "BREAKOUT_RETEST" else 0.70
            out.append(StrategyCandidate(
                engine_id=cls.engine_id, symbol=mkt_snapshot["symbol"], side="long",
                generated_at_ms=int(time.time() * 1000),
                entry_ref=entry, sl_price=sl,
                tp1_rr=float(profile.tp1_rr),
                tp2_rr=float(profile.tp2_rr),
                tp3_rr=float(profile.tp3_rr),
                engine_score=base, rr_ratio=rr,
                liquidity_score=cls._liquidity_score(mkt_snapshot.get("tier", "")),
                regime_fit=cls._regime_fit(mkt_snapshot.get("regime", ""), family),
                family=family,
                zone_ref=float(meta.get("zone_ref", entry)),
                features_snapshot={"exit_profile":asdict(profile), "atr": atr_val, "entry_ref": entry,
                                   "strategy_mode": family, "strategy_style": "SCALP",
                                   "timeframe_profile": "15M_5M",
                                   "raw_meta": {k: meta.get(k) for k in meta.keys()
                                                if k in ("prev_high",)}},
            ))
        return out


class LiquiditySweepEngine(_EngineBase):
    engine_id = "liq_sweep"
    family_map = ("LIQUIDITY_SWEEP_REVERSAL",)

    @classmethod
    def _config_enabled(cls) -> bool:
        return bool(CONFIG.get("MSE_ENGINE_LIQ_SWEEP", True))

    @classmethod
    def generate(cls, mkt_snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        df_15m = mkt_snapshot.get("df_15m")
        df_5m = mkt_snapshot.get("df_5m")
        matched, meta = OpportunityDetectors.detect_liquidity_sweep(df_15m, df_5m)
        if not matched:
            return []
        atr_val, entry = cls._atr_and_entry(df_5m)
        if atr_val is None or entry is None:
            return []
        sl = entry - float(CONFIG["ATR_SL_MULT"]) * atr_val
        profile = StrategyExitProfiles.profile_for("LIQUIDITY_SWEEP_REVERSAL", "SCALP")
        if not profile.validate():
            return []
        tp1 = entry + profile.tp1_rr * (entry - sl)
        tp2 = entry + profile.tp2_rr * (entry - sl)
        tp3 = entry + profile.tp3_rr * (entry - sl)
        rr = profile.tp1_rr
        # V638 quality score is derived from the actual closed-bar candle
        # confluence (wick + volume + close location + reclaim), not from the
        # existence of a wick alone. Keep a bounded floor/ceiling so ranking
        # behavior remains stable and all downstream hard gates remain intact.
        try:
            swept_low = float(meta.get("swept_low", entry))
            reclaim_atr = (entry - swept_low) / max(atr_val, 1e-9)
            reclaim_bonus = max(0.0, min(0.04, reclaim_atr * 0.02))
        except Exception:
            reclaim_bonus = 0.0
        engine_score = min(0.92, max(0.68, float(meta.get("signal_quality", 0.68)) + reclaim_bonus))
        return [StrategyCandidate(
            engine_id=cls.engine_id, symbol=mkt_snapshot["symbol"], side="long",
            generated_at_ms=int(time.time() * 1000),
            entry_ref=entry, sl_price=sl,
            tp1_rr=float(profile.tp1_rr),
            tp2_rr=float(profile.tp2_rr),
            tp3_rr=float(profile.tp3_rr),
            engine_score=engine_score, rr_ratio=rr,
            liquidity_score=cls._liquidity_score(mkt_snapshot.get("tier", "")),
            regime_fit=cls._regime_fit(mkt_snapshot.get("regime", ""),
                                       "LIQUIDITY_SWEEP_REVERSAL"),
            family="LIQUIDITY_SWEEP_REVERSAL",
            zone_ref=float(meta.get("zone_ref", entry)),
            features_snapshot={
                "atr": atr_val, "entry_ref": entry,
                "swept_low": meta.get("swept_low"),
                "sweep": True,
                "reclaim": bool(meta.get("reclaim", True)),
                "lower_wick_ratio": float(meta.get("lower_wick_ratio", 0.0) or 0.0),
                "body_ratio": float(meta.get("body_ratio", 0.0) or 0.0),
                "close_location": float(meta.get("close_location", 0.0) or 0.0),
                "volume_ratio": float(meta.get("volume_ratio", 0.0) or 0.0),
                "bullish_close": bool(meta.get("bullish_close", False)),
                "prior_context": bool(meta.get("prior_context", False)),
                "signal_quality": float(meta.get("signal_quality", engine_score)),
                "strategy_mode": "LIQUIDITY_SWEEP_REVERSAL", "strategy_style": "SCALP",
                "timeframe_profile": "15M_5M",
            },
        )]


class MeanReversionEngine(_EngineBase):
    engine_id = "mean_reversion"
    family_map = ("MEAN_REVERSION",)

    @classmethod
    def _config_enabled(cls) -> bool:
        return bool(CONFIG.get("MSE_ENGINE_MEAN_REVERSION", True))

    @classmethod
    def generate(cls, mkt_snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        df_5m = mkt_snapshot.get("df_5m")
        matched, meta = OpportunityDetectors.detect_mean_reversion(df_5m)
        if not matched:
            return []
        atr_val, entry = cls._atr_and_entry(df_5m)
        if atr_val is None or entry is None:
            return []
        sl = entry - float(CONFIG["ATR_SL_MULT"]) * atr_val
        profile = StrategyExitProfiles.profile_for("MEAN_REVERSION", "SCALP")
        if not profile.validate():
            return []
        tp1 = entry + profile.tp1_rr * (entry - sl)
        tp2 = entry + profile.tp2_rr * (entry - sl)
        tp3 = entry + profile.tp3_rr * (entry - sl)
        rr = profile.tp1_rr
        # Deeper RSI oversold -> higher confidence, bounded.
        try:
            rsi_val = float(meta.get("rsi", 32.0))
        except Exception:
            rsi_val = 32.0
        deep = max(0.0, (32.0 - rsi_val) / 32.0)   # 0..1
        engine_score = min(1.0, 0.55 + 0.25 * deep)
        return [StrategyCandidate(
            engine_id=cls.engine_id, symbol=mkt_snapshot["symbol"], side="long",
            generated_at_ms=int(time.time() * 1000),
            entry_ref=entry, sl_price=sl,
            tp1_rr=float(profile.tp1_rr),
            tp2_rr=float(profile.tp2_rr),
            tp3_rr=float(profile.tp3_rr),
            engine_score=engine_score, rr_ratio=rr,
            liquidity_score=cls._liquidity_score(mkt_snapshot.get("tier", "")),
            regime_fit=cls._regime_fit(mkt_snapshot.get("regime", ""),
                                       "MEAN_REVERSION"),
            family="MEAN_REVERSION",
            zone_ref=float(meta.get("zone_ref", entry)),
            features_snapshot={"atr": atr_val, "entry_ref": entry,
                               "rsi": rsi_val, "strategy_mode": "MEAN_REVERSION",
                               "strategy_style": "SCALP", "timeframe_profile": "5M"},
        )]


class TrendContinuationEngine(_EngineBase):
    engine_id = "trend_cont"
    family_map = ("MOMENTUM_EXPANSION",)

    @classmethod
    def _config_enabled(cls) -> bool:
        return bool(CONFIG.get("MSE_ENGINE_TREND_CONT", True))

    @classmethod
    def generate(cls, mkt_snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        df_5m = mkt_snapshot.get("df_5m")
        df_15m = mkt_snapshot.get("df_15m")
        if df_5m is None or df_15m is None or len(df_15m) < 60:
            return []
        matched, meta = OpportunityDetectors.detect_momentum_expansion(df_5m)
        if not matched:
            return []
        _e20_15 = Indicators.ema(df_15m["close"], 20)
        _e50_15 = Indicators.ema(df_15m["close"], 50)
        _p15 = float(df_15m["close"].iloc[-2])
        if not (math.isfinite(_p15) and _p15 > float(_e20_15.iloc[-2]) > float(_e50_15.iloc[-2])):
            return []
        atr_val, entry = cls._atr_and_entry(df_5m)
        if atr_val is None or entry is None:
            return []
        sl = entry - float(CONFIG["ATR_SL_MULT"]) * atr_val
        profile = StrategyExitProfiles.profile_for("MOMENTUM_EXPANSION", "SCALP")
        if not profile.validate():
            return []
        tp1 = entry + profile.tp1_rr * (entry - sl)
        tp2 = entry + profile.tp2_rr * (entry - sl)
        tp3 = entry + profile.tp3_rr * (entry - sl)
        rr = profile.tp1_rr
        try:
            ratio = float(meta.get("atr_ratio", 1.15))
        except Exception:
            ratio = 1.15
        # 1.15 => 0, 1.6+ => cap
        expansion = max(0.0, min(1.0, (ratio - 1.15) / 0.45))
        engine_score = min(1.0, 0.60 + 0.25 * expansion)
        return [StrategyCandidate(
            engine_id=cls.engine_id, symbol=mkt_snapshot["symbol"], side="long",
            generated_at_ms=int(time.time() * 1000),
            entry_ref=entry, sl_price=sl,
            tp1_rr=float(profile.tp1_rr),
            tp2_rr=float(profile.tp2_rr),
            tp3_rr=float(profile.tp3_rr),
            engine_score=engine_score, rr_ratio=rr,
            liquidity_score=cls._liquidity_score(mkt_snapshot.get("tier", "")),
            regime_fit=cls._regime_fit(mkt_snapshot.get("regime", ""),
                                       "MOMENTUM_EXPANSION"),
            family="MOMENTUM_EXPANSION",
            zone_ref=float(meta.get("zone_ref", entry)),
            features_snapshot={"atr": atr_val, "entry_ref": entry,
                               "atr_ratio": ratio, "strategy_mode": "MOMENTUM_EXPANSION",
                               "strategy_style": "SCALP", "timeframe_profile": "15M_5M",
                               "trend_15m_confirmed": True, "entry_anchor": float(_e20_15.iloc[-2])},
        )]


_MSE_ENGINES: Tuple[Any, ...] = (
    MTFPullbackEngine, PullbackEngine, BreakoutEngine, LiquiditySweepEngine,
    MeanReversionEngine, TrendContinuationEngine,
    # v4.3 adaptive engines (registered dynamically below; appended post-def)
)


# V702 FINAL: ranking chase normalization must use the candidate family's native
# chase envelope, not the LOCAL_STRENGTH_BREAKOUT cap globally. Otherwise a
# safety tightening applied to LSB would unfairly zero chase quality for
# otherwise-valid families such as Swing/Scout/Volatility/RS.
def _v702_ranking_chase_cap(candidate: Any) -> float:
    try:
        fam = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
        mode = str(getattr(candidate, "strategy_mode", "") or fam).upper()
        caps = {
            "PULLBACK": float(CONFIG.get("V580_PULLBACK_FINAL_MAX_CHASE_ATR", 0.90)),
            "MTF_PULLBACK": float(CONFIG.get("V580_PULLBACK_FINAL_MAX_CHASE_ATR", 0.90)),
            "LOCAL_STRENGTH_BREAKOUT": min(0.60, float(CONFIG.get("V702_LSB_FINAL_MAX_CHASE_ATR", 0.60))),
            "COMPRESSION_EXPANSION": float(CONFIG.get("EXPANSION_MAX_CHASE_ATR", 1.60)),
            "BREAKOUT_RETEST": 1.20,
            "BREAKOUT_CONTINUATION": 1.00,
            "MEASURED_MOVE": float(CONFIG.get("MEASURED_MOVE_MAX_CHASE_ATR", 0.90)),
            "LIQUIDITY_SWEEP_REVERSAL": 1.20,
            "MEAN_REVERSION": 0.90,
            "MOMENTUM_EXPANSION": 1.10,
            "SWING_PULLBACK": 0.60,
            "EXTREME_FLUSH_REVERSAL": float(CONFIG.get("EXTREME_FLUSH_MAX_CHASE_ATR", 1.20)),
            "CONTINUATION_RECLAIM": float(CONFIG.get("CONTINUATION_RECLAIM_MAX_CHASE_ATR", 1.25)),
            "FAILED_BREAKOUT_RECLAIM": float(CONFIG.get("FAILED_BREAKOUT_RECLAIM_MAX_CHASE_ATR", 1.00)),
            "VOLATILITY_BURST": float(CONFIG.get("V45_VOLATILITY_BURST_MAX_CHASE_ATR", 1.10)),
            "RELATIVE_STRENGTH": float(CONFIG.get("V45_RS_LEADER_MAX_CHASE_ATR", 1.30)),
            "RELATIVE_STRENGTH_LEADER": float(CONFIG.get("V45_RS_LEADER_MAX_CHASE_ATR", 1.30)),
            "TREND_CONTINUATION": float(CONFIG.get("V459_MICRO_TREND_MAX_CHASE_ATR", 1.15)),
            "MICRO_TREND_CONTINUATION": float(CONFIG.get("V459_MICRO_TREND_MAX_CHASE_ATR", 1.15)),
            "OPPORTUNITY_SCOUT": float(CONFIG.get("V521_SCOUT_MAX_CHASE_ATR", 1.20)),
        }
        cap = caps.get(fam, caps.get(mode, 1.20))
        return max(0.50, float(cap))
    except Exception:
        return 1.20

# ---- Composite ranking + conflict resolver ----------------------------------
@dataclass(frozen=True)
class RankedCandidate:
    candidate: StrategyCandidate
    composite: float
    tp1_abs: float
    tp2_abs: float
    tp3_abs: float


def _v702_fallback_ranked_candidate(candidate: StrategyCandidate) -> RankedCandidate:
    """Build the canonical ranked shape when weighted ranking is disabled."""
    entry = float(candidate.entry_ref)
    risk = entry - float(candidate.sl_price)
    return RankedCandidate(
        candidate=candidate,
        composite=float(candidate.engine_score),
        tp1_abs=entry + float(candidate.tp1_rr) * risk,
        tp2_abs=entry + float(candidate.tp2_rr) * risk,
        tp3_abs=entry + float(candidate.tp3_rr) * risk,
    )


def _v702_apply_mse_diversity_bonus(ranked: List[RankedCandidate], bonus: float) -> List[RankedCandidate]:
    """Apply a bounded tie bonus without mutating frozen RankedCandidate values."""
    cap = max(0.0, min(0.02, float(bonus)))
    if cap <= 0.0 or len(ranked) < 2:
        return list(ranked)
    top_score = float(ranked[0].composite)
    top_mode = ranked[0].candidate.strategy_mode
    adjusted = []
    for item in ranked:
        score = float(item.composite)
        if item is not ranked[0] and abs(top_score - score) <= 0.005 and item.candidate.strategy_mode != top_mode:
            score = min(1.0, score + cap)
        adjusted.append(replace(item, composite=score) if score != item.composite else item)
    return sorted(adjusted, key=lambda item: item.composite, reverse=True)



def _v554_record_mse_rank_reject(symbol: str, reason: str, candidate: Any = None, **ctx) -> None:
    """Record the exact reason a discovery candidate was dropped before canonical prequal.

    Telemetry only. This never changes execution authority.
    """
    try:
        if not bool(CONFIG.get("V554_BRIDGE_TELEMETRY_ENABLE", True)):
            return
        key = str(reason or "unknown")
        counts = STATS.setdefault("v554_mse_rank_reject_reasons", defaultdict(int))
        counts[key] += 1
        hist = STATS.setdefault("v554_mse_rank_reject_history", deque(maxlen=int(CONFIG.get("V554_MSE_REASON_HISTORY_MAX", 1024))))
        sym = str(symbol or getattr(candidate, "symbol", "") or "")
        fs = dict(getattr(candidate, "features_snapshot", {}) or {}) if candidate is not None else {}
        hist.append({
            "ts": WALL_NOW(), "symbol": sym, "reason": key,
            "engine_score": float(getattr(candidate, "engine_score", 0.0) or 0.0) * 100.0 if candidate is not None else None,
            "family": str(getattr(candidate, "family", "") or ""),
            "strategy_mode": str(getattr(candidate, "strategy_mode", "") or ""),
            "ctx": dict(ctx or {}),
            "volume_ratio": fs.get("volume_ratio"),
            "htf_strength": fs.get("htf_strength"),
            "chase_atr": fs.get("chase_atr"),
        })
        STATS["v554_last_mse_rank_reject_reason"] = key
        STATS["v554_last_mse_rank_reject_symbol"] = sym
    except Exception:
        _v647_record_suppressed_exception()


def _v554_fee_rank_rescue_probe(candidate: Any) -> Tuple[bool, Dict[str, Any]]:
    """Probe whether the EXISTING bounded fee-target rescue can repair ranking.

    This is intentionally fail-closed: it never authorizes an order and it never
    changes the candidate geometry. The live SizingEngine must re-run the real
    fee gate and apply the actual final targets before submission.
    """
    out: Dict[str, Any] = {"ok": False}
    try:
        if not bool(CONFIG.get("V554_RANK_FEE_RESCUE_ENABLE", True)):
            out["reason"] = "disabled"; return False, out
        c = candidate
        family_raw = str(getattr(c, "strategy_mode", "") or getattr(c, "family", "") or "").upper()
        family = family_raw.split("/", 1)[0].strip() if family_raw else ""
        allowed = {str(x).upper().strip() for x in CONFIG.get("V554_RANK_FEE_RESCUE_FAMILIES", ("PULLBACK", "MTF_PULLBACK"))}
        if family not in allowed:
            out["reason"] = "family_not_allowed"; return False, out
        score = float(getattr(c, "engine_score", 0.0) or 0.0) * 100.0
        if not math.isfinite(score) or score < float(CONFIG.get("V554_RANK_FEE_RESCUE_MIN_ENGINE_SCORE", 64.0)):
            out["reason"] = "score_below_probe_floor"; return False, out
        entry = float(getattr(c, "entry_ref", 0.0) or 0.0)
        sl = float(getattr(c, "sl_price", 0.0) or 0.0)
        risk = entry - sl
        if entry <= 0 or risk <= 0:
            out["reason"] = "invalid_geometry"; return False, out
        tp1 = entry + float(getattr(c, "tp1_rr", 1.0) or 1.0) * risk
        tp2 = entry + float(getattr(c, "tp2_rr", 2.0) or 2.0) * risk
        tp3 = entry + float(getattr(c, "tp3_rr", 5.0) or 5.0) * risk
        # V664: ranking-time fee rescue must use the same economic ticket scale
        # that the live SizingEngine will actually evaluate. The old fixed 15-USDT
        # probe could mark a viable 75-USDT ticket as fee_unviable before it ever
        # reached canonical prequalification. This remains a READ-ONLY ranking
        # probe; live SizingEngine re-runs the original hard fee gate.
        try:
            _min_ticket = max(1.0, float(CONFIG.get("MIN_POSITION_SIZE_USDT", 15.0)))
            _fixed_ticket = max(0.0, float(CONFIG.get("FIXED_POSITION_SIZE_USDT", 0.0)))
            _max_ticket = max(_min_ticket, float(CONFIG.get("MAX_POSITION_SIZE_USDT", 75.0)))
            _requested_ticket = max(0.0, float(CONFIG.get("V576_REQUESTED_POSITION_USDT", _fixed_ticket or _max_ticket)))
            _configured_ticket = _fixed_ticket if _fixed_ticket > 0 else _requested_ticket
            nominal = min(_max_ticket, max(_min_ticket, _configured_ticket))
        except Exception:
            nominal = max(1.0, float(CONFIG.get("V554_RANK_FEE_RESCUE_PROBE_NOTIONAL_USDT", 15.0)))
        STATS["v664_fee_rank_probe_notional"] = float(nominal)
        # V420FeeRescue is defined later in source order but always exists when
        # this runtime method is called (module fully loaded before main()).
        _spread = (getattr(c, "features_snapshot", {}) or {}).get("spread_pct")
        _small_net = bool(CONFIG.get("V702_SMALL_NET_PROFIT_MODE_ENABLE", False))
        ok, n1, n2, n3, reason = V420FeeRescue.try_expand_targets(
            entry, sl, tp1, tp2, tp3, nominal, score, family,
            spread_pct=_spread, small_net_mode=_small_net
        )
        out.update({
            "reason": str(reason or ""), "family": family, "score": score,
            "original_rr1": (tp1-entry)/risk, "original_rr2": (tp2-entry)/risk,
            "rescued_rr1": (float(n1)-entry)/risk if ok else 0.0,
            "rescued_rr2": (float(n2)-entry)/risk if ok else 0.0,
            "rescued_rr3": (float(n3)-entry)/risk if ok else 0.0,
        })
        if not ok:
            return False, out
        # Re-run the original hard fee gate on the proposed rescued targets.
        _spread = (getattr(c, "features_snapshot", {}) or {}).get("spread_pct")
        _small_net = bool(CONFIG.get("V702_SMALL_NET_PROFIT_MODE_ENABLE", False))
        detail = SizingEngine.fee_viability_detail(entry, sl, float(n1), float(n2), nominal,
                                                  spread_pct=_spread, small_net_mode=_small_net)
        if not bool(detail.get("ok", False)):
            out["reason"] = f"rescue_probe_failed:{detail.get('reason','fee_unviable')}"
            out["detail"] = detail
            return False, out
        out["detail"] = detail
        out["ok"] = True
        return True, out
    except Exception as exc:
        out["reason"] = f"exception:{type(exc).__name__}"
        return False, out


def _v554_rank_reject_top(n: int = 5) -> List[Tuple[str, int]]:
    try:
        d = STATS.get("v554_mse_rank_reject_reasons") or {}
        return sorted(((str(k), int(v or 0)) for k, v in d.items() if int(v or 0) > 0),
                      key=lambda kv: kv[1], reverse=True)[:max(1, int(n))]
    except Exception:
        return []


# Pullback-only forensic hook. It records the raw fake-break context so future
# tuning is evidence-driven; it never alters a gate.
