# =============================================================================
#  SECTION 35A — V4.2.3 UNIFIED FUNNEL / BOTTLENECK / EXPLAINABILITY
#  Additive, non-blocking telemetry. Never relaxes hard gates.
# =============================================================================
class V423Funnel:
    _lock = threading.RLock()
    _events = deque(maxlen=8192)       # (mono_ts, "R", payload)
    _stage_events = deque(maxlen=8192) # (mono_ts, G/E/Q/S)
    _score_acc = {
        "accepted_sum": 0.0, "accepted_n": 0,
        "rejected_sum": 0.0, "rejected_n": 0,
        "near_miss_n": 0, "near_miss_gap_sum": 0.0, "near_miss_gap_n": 0,
    }

    @classmethod
    def _enabled(cls):
        return bool(CONFIG.get("V423_FUNNEL_ENABLE", True))

    @classmethod
    def note_stage(cls, stage: str):
        if not cls._enabled():
            return
        try:
            st = str(stage).upper()
            if st in {"G", "E", "Q", "S"}:
                with cls._lock:
                    cls._stage_events.append((MONO_NOW(), st))
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def note_reject(cls, *, taxonomy, code, stage, symbol="", family="",
                    regime="", score=None, threshold=None, ctx=None):
        if not cls._enabled():
            return
        try:
            st = str(stage or "").lower()
            if st in {"universe_pruning", "regime", "htf_grader", "router",
                      "microstruct", "family_policy", "d1_bias", "liquidity"}:
                bucket = "g_to_e"
            elif st in {"scorer", "daily_cb", "dedup", "post_reprice"}:
                bucket = "e_to_q"
            elif st in {"cooldown", "presend_gate", "pre_send", "submit",
                        "execution", "sizing"}:
                bucket = "q_to_s"
            else:
                bucket = "unknown"

            try:
                gap = float(threshold) - float(score) if score is not None and threshold is not None else None
            except Exception:
                gap = None

            payload = {
                "bucket": bucket,
                "taxonomy": str(taxonomy or ""),
                "code": str(code or "").split(":",1)[0],
                "symbol": str(symbol or ""),
                "family": str(family or ""),
                "regime": str(regime or ""),
                "score": score,
                "threshold": threshold,
                "distance_to_threshold": gap,
                "ctx": dict(ctx or {}),
            }
            with cls._lock:
                cls._events.append((MONO_NOW(), "R", payload))
                if score is not None and bucket == "e_to_q":
                    cls._score_acc["rejected_sum"] += float(score)
                    cls._score_acc["rejected_n"] += 1
                max_gap = float(CONFIG.get("V423_NEAR_MISS_MAX_POINTS", 5.0))
                if gap is not None and 0 < gap <= max_gap:
                    cls._score_acc["near_miss_n"] += 1
                    cls._score_acc["near_miss_gap_sum"] += gap
                    cls._score_acc["near_miss_gap_n"] += 1
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def note_accepted_score(cls, score):
        if not cls._enabled():
            return
        try:
            with cls._lock:
                cls._score_acc["accepted_sum"] += float(score)
                cls._score_acc["accepted_n"] += 1
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def snapshot(cls):
        if not cls._enabled():
            return {}
        try:
            window = float(CONFIG.get("V423_FUNNEL_WINDOW_SEC", 900))
            now = MONO_NOW()
            with cls._lock:
                while cls._stage_events and now - cls._stage_events[0][0] > window:
                    cls._stage_events.popleft()
                while cls._events and now - cls._events[0][0] > window:
                    cls._events.popleft()
                stages = [x[1] for x in cls._stage_events]
                rejects = [x[2] for x in cls._events if x[1] == "R"]
                sc = dict(cls._score_acc)

            g,e,q,s = stages.count("G"),stages.count("E"),stages.count("Q"),stages.count("S")
            def pct(a,b): return round(100.0*a/b,2) if b else 0.0
            buckets={b:defaultdict(int) for b in ("g_to_e","e_to_q","q_to_s")}
            syms={b:defaultdict(int) for b in buckets}
            fams={b:defaultdict(int) for b in buckets}
            for r in rejects:
                b=r.get("bucket")
                if b not in buckets: continue
                code=r.get("code","unknown")
                buckets[b][code]+=1
                if r.get("symbol"): syms[b][r["symbol"]]+=1
                if r.get("family"): fams[b][r["family"]]+=1
            def top(d,n=5): return dict(sorted(d.items(), key=lambda kv:kv[1], reverse=True)[:n])
            allr=defaultdict(int)
            for r in rejects: allr[f'{r.get("bucket","?")}:{r.get("code","unknown")}']+=1
            near_gap=(sc["near_miss_gap_sum"]/sc["near_miss_gap_n"]
                      if sc["near_miss_gap_n"] else None)
            return {
                "window_sec":window,"G":g,"E":e,"Q":q,"S":s,
                "g_to_e_pct":pct(e,g),"e_to_q_pct":pct(q,e),
                "q_to_s_pct":pct(s,q),"overall_pct":pct(s,g),
                "top_rejects":[k for k,_ in sorted(allr.items(), key=lambda kv:kv[1], reverse=True)[:3]],
                "bottlenecks":{
                    b:{
                        "count":sum(buckets[b].values()),
                        "by_reason_pct":{k:pct(v,sum(buckets[b].values()))
                                         for k,v in sorted(buckets[b].items(),key=lambda kv:kv[1],reverse=True)[:8]},
                        "top_symbols":top(syms[b]),
                        "top_families":top(fams[b]),
                    } for b in buckets
                },
                "avg_score_accepted":round(sc["accepted_sum"]/sc["accepted_n"],2) if sc["accepted_n"] else None,
                "avg_score_rejected":round(sc["rejected_sum"]/sc["rejected_n"],2) if sc["rejected_n"] else None,
                "near_miss_count":int(sc["near_miss_n"]),
                "avg_missing_points_to_threshold":round(near_gap,2) if near_gap is not None else None,
                "cooldown_skips":int(STATS.get("signals_scanned_cooldown_skipped",0) or 0),
                "no_family_rate":round(100.0*float(STATS.get("no_family_matched_count",0) or 0)/
                                      max(1.0,float(STATS.get("signals_generated",0) or 0)),2),
            }
        except Exception:
            return {}


class V423Decision:
    def __init__(self, symbol: str, trace_id: str):
        self.symbol=symbol; self.trace_id=trace_id
        self.family=""; self.regime=""; self.tier=""
        self.htf_strength=None; self.score=None; self.threshold=None
        self.passes=[]; self.soft_penalties=[]; self.reject_reason=None
        self.final_state="pending"
    def add_pass(self,x): self.passes.append(str(x))
    def add_soft(self,x): self.soft_penalties.append(str(x))
    def reject(self,x): self.reject_reason=str(x); self.final_state="rejected"
    def finalize(self,x): self.final_state=str(x)
    def emit(self):
        try:
            base=f"[DECISION] {self.symbol} family={self.family or '-'} regime={self.regime or '-'} tier={self.tier or '-'}"
            if self.score is not None and self.threshold is not None:
                base+=f" score={self.score:.1f}/{self.threshold:.1f}"
            if self.passes: base+=" PASS["+",".join(self.passes)+"]"
            if self.soft_penalties: base+=" SOFT["+",".join(self.soft_penalties)+"]"
            if self.reject_reason: base+=f" REJECT[{self.reject_reason}]"
            base+=f" => {self.final_state}"
            logger.info(base) if self.final_state in {"eligible","queued","sent"} else logger.debug(base)
        except Exception:
            _v647_record_suppressed_exception()


# =============================================================================
#  SECTION 35 — SIGNAL BUILDER (glue that ties everything together)
# =============================================================================

def _v520_fake_break_gate(df_5m, family="", strategy_mode="", zone_ref=None,
                          atr_value=None):
    """Pullback-aware soft structural gate; breakout families remain strict."""
    ctx = {}
    try:
        fam = str(family or strategy_mode or "").upper()
        if df_5m is None or len(df_5m) < 20:
            return False, {"mode": "SOFT_REJECT", "reason": "structure.data_insufficient"}

        lc = float(df_5m["close"].iloc[-2])
        pc = float(df_5m["close"].iloc[-3])
        lo = float(df_5m["open"].iloc[-2])
        hi = float(df_5m["high"].iloc[-2])
        low = float(df_5m["low"].iloc[-2])

        if atr_value is None:
            try:
                atr_value = float(Indicators.atr(df_5m, int(CONFIG.get("ATR_PERIOD", 14))).iloc[-2])
            except Exception:
                atr_value = None

        atr_ok = atr_value is not None and math.isfinite(float(atr_value)) and float(atr_value) > 0
        atr = float(atr_value) if atr_ok else 0.0

        ema20_series = df_5m["close"].ewm(span=20, adjust=False).mean()
        ema50_series = df_5m["close"].ewm(span=50, adjust=False).mean()
        ema20 = float(ema20_series.iloc[-2])
        ema50 = float(ema50_series.iloc[-2])

        if not atr_ok:
            # Invalid ATR must never masquerade as a 0-ATR chase.
            return False, {
                "mode": "SOFT_REJECT",
                "reason": "structure.atr_invalid",
                "atr_valid": False,
                "chase_atr": None,
            }

        chase = max(0.0, (lc - ema20) / atr)
        max_chase = float(CONFIG.get("FAKE_BREAK_SOFT_MAX_CHASE_ATR", 1.80))

        reclaim = False
        try:
            z = float(zone_ref if zone_ref is not None else ema20)
            reclaim = bool(pc < z <= lc)
        except Exception:
            reclaim = False

        bullish = bool(lc > lo and lc >= pc)
        higher_low = False
        ema20_slope_up = False
        shallow_pullback = False

        if fam in {"PULLBACK", "MTF_PULLBACK"}:
            max_chase = min(
                max_chase,
                float(CONFIG.get("V540_FAKE_BREAK_PULLBACK_SOFT_MAX_CHASE_ATR", max_chase)),
                float(CONFIG.get("V548_FAKE_BREAK_PULLBACK_MAX_CHASE_ATR", max_chase)),
                float(CONFIG.get("V565_PULLBACK_RECOVERY_MAX_CHASE_ATR", max_chase)),
            )

            try:
                l1 = float(df_5m["low"].iloc[-2])
                l2 = float(df_5m["low"].iloc[-3])
                l3 = float(df_5m["low"].iloc[-4])
                higher_low = bool(l1 > l2 and l2 >= l3)
            except Exception:
                higher_low = False

            try:
                bars = max(5, int(CONFIG.get("V565_PULLBACK_SLOPE_BARS", 8)))
                closed_ema = ema20_series.iloc[-(bars + 1):-1]
                if len(closed_ema) >= 2:
                    ema0 = float(closed_ema.iloc[0])
                    ema1 = float(closed_ema.iloc[-1])
                    ema20_slope_up = bool(
                        math.isfinite(ema0) and math.isfinite(ema1)
                        and ema1 > ema0 * (1.0 + float(CONFIG.get("V565_PULLBACK_SLOPE_MIN_REQUIRED_R", 0.0001)))
                    )
            except Exception:
                ema20_slope_up = False

            try:
                rng = max(hi - low, 0.0)
                body = abs(lc - lo)
                lower_wick = max(0.0, min(lc, lo) - low)
                upper_wick = max(0.0, hi - max(lc, lo))
                body_ratio = body / rng if rng > 0 else 0.0
                lower_wick_ratio = lower_wick / rng if rng > 0 else 0.0
                # A shallow, controlled retracement can legitimately end on a
                # bearish/small candle while the higher-timeframe trend is intact.
                shallow_pullback = bool(
                    rng > 0
                    and body_ratio <= float(CONFIG.get("V565_PULLBACK_SHALLOW_RETRACE_MAX_BODY_RATIO", 0.65))
                    and lower_wick_ratio <= float(CONFIG.get("V565_PULLBACK_SHALLOW_RETRACE_MAX_WICK_RATIO", 0.40))
                    and lc >= ema50
                    and lc >= ema20 - 0.35 * atr
                )
            except Exception:
                shallow_pullback = False

        else:
            # Breakout families retain strict behavior.
            if fam in {"BREAKOUT_RETEST", "BREAKOUT_CONTINUATION"}:
                hard_confirmation, _ = MicroStructure.micro_bos_confirm(df_5m)
                confirmation = bool(hard_confirmation or reclaim or bullish)
                return bool(confirmation and chase <= max_chase), {
                    "mode": "SOFT" if bool(confirmation and chase <= max_chase) else "SOFT_REJECT",
                    "reclaim": reclaim,
                    "bullish_close": bullish,
                    "higher_low": False,
                    "ema20_slope_up": False,
                    "shallow_pullback": False,
                    "chase_atr": chase,
                    "atr_valid": True,
                    "hard_breakout_family": True,
                }

        # v4.5.80 — shallow retracement is SUPPORTING evidence only. It may
        # describe a healthy pullback candle, but it does not prove recovery.
        # Require one actual structural confirmation before this gate passes.
        _structural_confirmation = bool(
            reclaim
            or bullish
            or (bool(CONFIG.get("V548_FAKE_BREAK_PULLBACK_HIGHER_LOW_ENABLE", True)) and higher_low)
            or ema20_slope_up
        )
        _shallow_support = bool(
            bool(CONFIG.get("V565_PULLBACK_AWARE_FAKE_BREAK_ENABLE", True))
            and shallow_pullback
            and bool(CONFIG.get("V579_PULLBACK_SHALLOW_SUPPORT_ONLY", True))
        )
        if bool(CONFIG.get("V579_PULLBACK_REQUIRE_STRUCTURAL_CONFIRMATION", True)):
            confirmation = _structural_confirmation
        else:
            confirmation = bool(_structural_confirmation or _shallow_support)

        ok = bool(confirmation and chase <= max_chase)

        return ok, {
            **ctx,
            "mode": "SOFT" if ok else "SOFT_REJECT",
            "reclaim": reclaim,
            "bullish_close": bullish,
            "higher_low": higher_low,
            "ema20_slope_up": ema20_slope_up,
            "shallow_pullback": shallow_pullback,
            "chase_atr": chase,
            "atr_valid": True,
            "ema20": ema20,
            "ema50": ema50,
            "close": lc,
        }
    except Exception as exc:
        return False, {
            **ctx,
            "mode": "SOFT_REJECT_EXCEPTION",
            "error": type(exc).__name__,
        }


def _v520_microstructure_parity(df_5m, family, strategy_mode, zone_ref, bos_confirmed=None, candidate_features=None):
    """Single coherent microstructure evidence gate; avoids duplicate PULLBACK tests."""
    if not bool(CONFIG.get("V520_PREQUAL_MICROSTRUCTURE_ENABLE", True)):
        return True, {"disabled": True}
    if df_5m is None or len(df_5m) < 20:
        return False, {"reason": "microstruct.data_insufficient"}

    fam = str(family or "").upper()
    mode = str(strategy_mode or "").upper()

    try:
        if bos_confirmed is None:
            bos_confirmed, _ = MicroStructure.micro_bos_confirm(df_5m)

        lc = float(df_5m["close"].iloc[-2])
        pc = float(df_5m["close"].iloc[-3])
        fs = dict(candidate_features or {}) if isinstance(candidate_features, dict) else {}

        # V689: LIQUIDITY_SWEEP_REVERSAL gets a native structure contract.
        # Never invent a recovery zone from the current close.
        if fam == "LIQUIDITY_SWEEP_REVERSAL" or mode == "LIQUIDITY_SWEEP_REVERSAL":
            zone = zone_ref
            if zone is None:
                zone = fs.get("swept_low") or fs.get("sr_support") or fs.get("strategy_native_recovery_zone") or fs.get("zone_ref")
            if zone is None:
                return False, {"mode":"LSR_NATIVE_REJECT", "reason":"lsr.zone_unverifiable"}
            try:
                zone = float(zone)
                if not math.isfinite(zone): raise ValueError("zone")
                hi=float(df_5m["high"].iloc[-2]); lo=float(df_5m["low"].iloc[-2]); op=float(df_5m["open"].iloc[-2])
                rng=max(hi-lo,1e-9); body_ratio=abs(lc-op)/rng; lower_wick=max(0.0,min(lc,op)-lo)/rng; close_location=(lc-lo)/rng
                vol_ratio=1.0
                if "volume" in df_5m.columns:
                    base=float(df_5m["volume"].iloc[-12:-2].mean()); vol_ratio=float(df_5m["volume"].iloc[-2])/max(base,1e-9)
                atr=float(Indicators.atr(df_5m, CONFIG.get("ATR_PERIOD",14)).iloc[-2])
                if not math.isfinite(atr) or atr<=0: raise ValueError("atr")
            except Exception:
                return False, {"mode":"LSR_NATIVE_REJECT", "reason":"lsr.native_facts_unverifiable"}
            sweep_like=bool(fs.get("sweep") or fs.get("swept_low") is not None or lower_wick >= float(CONFIG.get("V689_LSR_MIN_LOWER_WICK_RATIO",0.55)))
            native_reclaim=bool(fs.get("reclaim") or fs.get("sr_recovery_verified"))
            recent_reclaim=bool(native_reclaim or (pc < zone <= lc) or (lc >= zone and pc >= zone))
            micro_bos=bool(bos_confirmed or fs.get("micro_bos") or fs.get("bos_confirmed"))
            recovery=bool((lc-zone)/max(atr,1e-9) >= float(CONFIG.get("V689_LSR_MIN_RECLAIM_ATR",0.20)))
            bearish_displacement=bool(fs.get("genuine_bearish_displacement",False) or ((lc<zone and pc<zone) and (pc-lc)/max(atr,1e-9) >= float(CONFIG.get("V689_LSR_BEARISH_DISPLACEMENT_ATR",1.0))))
            if bearish_displacement:
                return False, {"mode":"LSR_NATIVE_REJECT", "reason":"lsr.genuine_bearish_displacement", "sweep":sweep_like, "reclaim":recent_reclaim, "micro_bos":micro_bos}
            ok=bool((sweep_like and (recovery or recent_reclaim)) or recent_reclaim or micro_bos)
            if not ok:
                return False, {"mode":"LSR_NATIVE_REJECT", "reason":"lsr.native_confirmation_missing", "sweep":sweep_like, "reclaim":recent_reclaim, "micro_bos":micro_bos}
            return True, {"mode":"LSR_NATIVE","sweep":sweep_like,"reclaim":recent_reclaim,"micro_bos":micro_bos,"bullish_close":bool(lc>op and lc>=pc),"lower_wick_ratio":lower_wick,"body_ratio":body_ratio,"close_location":close_location,"volume_ratio":vol_ratio,"bearish_displacement":False}

        zone = float(zone_ref if zone_ref is not None else lc)

        reclaim = bool(pc < zone <= lc)
        bullish = bool(lc > float(df_5m["open"].iloc[-2]) and lc >= pc)

        higher_low = False
        ema20_slope_up = False
        shallow_pullback = False

        if fam in {"PULLBACK", "MTF_PULLBACK"} or mode in {"PULLBACK", "MTF_PULLBACK"}:
            try:
                l1 = float(df_5m["low"].iloc[-2])
                l2 = float(df_5m["low"].iloc[-3])
                l3 = float(df_5m["low"].iloc[-4])
                higher_low = bool(l1 > l2 and l2 >= l3)
            except Exception:
                _v647_record_suppressed_exception()

            try:
                ema20 = df_5m["close"].ewm(span=20, adjust=False).mean()
                bars = max(5, int(CONFIG.get("V565_PULLBACK_SLOPE_BARS", 8)))
                closed = ema20.iloc[-(bars + 1):-1]
                if len(closed) >= 2:
                    a = float(closed.iloc[0])
                    b = float(closed.iloc[-1])
                    ema20_slope_up = bool(
                        math.isfinite(a) and math.isfinite(b)
                        and b > a * (1.0 + float(CONFIG.get("V565_PULLBACK_SLOPE_MIN_REQUIRED_R", 0.0001)))
                    )
            except Exception:
                _v647_record_suppressed_exception()

            try:
                hi = float(df_5m["high"].iloc[-2])
                lo = float(df_5m["low"].iloc[-2])
                op = float(df_5m["open"].iloc[-2])
                rng = max(hi - lo, 0.0)
                body = abs(lc - op)
                lower_wick = max(0.0, min(lc, op) - lo)
                shallow_pullback = bool(
                    rng > 0
                    and body / rng <= float(CONFIG.get("V565_PULLBACK_SHALLOW_RETRACE_MAX_BODY_RATIO", 0.65))
                    and lower_wick / rng <= float(CONFIG.get("V565_PULLBACK_SHALLOW_RETRACE_MAX_WICK_RATIO", 0.40))
                )
            except Exception:
                _v647_record_suppressed_exception()

            structural_evidence_count = sum(
                bool(x) for x in (reclaim, bullish, higher_low, ema20_slope_up)
            )
            evidence_count = structural_evidence_count + int(bool(shallow_pullback))

            # v4.5.80 — the pullback candle can support the thesis, but a
            # shallow retracement alone is not a recovery confirmation. Keep
            # the gate coherent with the fake-break gate and require one real
            # structural confirmation by default.
            if bool(CONFIG.get("V579_PULLBACK_REQUIRE_STRUCTURAL_CONFIRMATION", True)):
                ok = bool(structural_evidence_count >= 1)
            else:
                ok = bool(evidence_count >= 1)

            return ok, {
                "mode": "PULLBACK_COHERENT" if ok else "PULLBACK_REJECT",
                "reclaim": reclaim,
                "bullish_close": bullish,
                "higher_low": higher_low,
                "ema20_slope_up": ema20_slope_up,
                "shallow_pullback": shallow_pullback,
                "structural_evidence_count": structural_evidence_count,
                "shallow_support_only": bool(shallow_pullback and bool(CONFIG.get("V579_PULLBACK_SHALLOW_SUPPORT_ONLY", True))),
                "evidence_count": evidence_count,
                "bos_confirmed": bool(bos_confirmed),
            }

        # Existing hard BOS families remain hard.
        hard = set(CONFIG.get("BOS_HARD_GATE_FAMILIES", ("BREAKOUT_RETEST", "BREAKOUT_CONTINUATION")))
        if fam in hard:
            ok = bool(bos_confirmed or reclaim)
        else:
            ok = bool(bos_confirmed or reclaim or bullish)

        return ok, {
            "mode": "HARD" if fam in hard else "SOFT",
            "bos_confirmed": bool(bos_confirmed),
            "reclaim": reclaim,
            "bullish_close": bullish,
        }
    except Exception as exc:
        return False, {"reason": "microstruct.exception", "error": type(exc).__name__}

def _v558_target_family_key(trade_or_family: Any) -> str:
    try:
        if isinstance(trade_or_family, str):
            raw = trade_or_family
        else:
            raw = (
                getattr(trade_or_family, "signal_family", None)
                or getattr(trade_or_family, "strategy_mode", None)
                or ""
            )
        raw = str(raw).upper().strip()
        return raw.split("/", 1)[0].strip() if raw else "PULLBACK"
    except Exception:
        return "PULLBACK"


def _v558_target_quality_multiplier(score: float) -> float:
    try:
        s = float(score)
        if not math.isfinite(s):
            return 1.0
        if s < 70.0:
            return max(
                float(CONFIG.get("V558_TARGET_SCORE_B_MULT_BOUNDS", (0.88, 0.96))[0]),
                min(
                    float(CONFIG.get("V558_TARGET_SCORE_B_MULT_BOUNDS", (0.88, 0.96))[1]),
                    0.96 - max(0.0, 70.0 - s) * 0.006,
                ),
            )
        if s < 85.0:
            return float(CONFIG.get("V558_TARGET_SCORE_A_MULT", 1.00))
        if s < 95.0:
            return float(CONFIG.get("V558_TARGET_SCORE_A_PLUS_MULT", 1.08))
        return float(CONFIG.get("V558_TARGET_SCORE_ELITE_MULT", 1.12))
    except Exception:
        return 1.0


def _v558_target_volatility_multiplier(entry: float, atr: float) -> float:
    try:
        entry_f = float(entry)
        atr_f = float(atr)
        if entry_f <= 0 or atr_f <= 0 or not math.isfinite(entry_f) or not math.isfinite(atr_f):
            return 1.0
        atr_pct = (atr_f / entry_f) * 100.0
        if atr_pct >= float(CONFIG.get("V558_TARGET_EXTREME_VOL_PCT", 6.0)):
            return float(CONFIG.get("V558_TARGET_EXTREME_VOL_MULT", 0.90))
        if atr_pct >= float(CONFIG.get("V558_TARGET_HIGH_VOL_PCT", 3.0)):
            return float(CONFIG.get("V558_TARGET_HIGH_VOL_MULT", 0.95))
        if atr_pct <= float(CONFIG.get("V558_TARGET_LOW_VOL_PCT", 0.40)):
            return float(CONFIG.get("V558_TARGET_LOW_VOL_MULT", 1.04))
        return 1.0
    except Exception:
        return 1.0


def _v558_dynamic_rrs(
    *,
    family: str,
    score: float,
    entry: float,
    sl: float,
    atr: float,
    base_rrs: Tuple[float, float, float],
) -> Tuple[float, float, float, Dict[str, Any]]:
    """Bounded dynamic RR selection; never changes SL or risk model."""
    b1, b2, b3 = (float(base_rrs[0]), float(base_rrs[1]), float(base_rrs[2]))
    meta: Dict[str, Any] = {"enabled": False, "multiplier": 1.0}
    if not bool(CONFIG.get("V558_DYNAMIC_TARGETS_ENABLE", True)):
        return b1, b2, b3, meta

    try:
        q = _v558_target_quality_multiplier(score)
        v = _v558_target_volatility_multiplier(entry, atr)
        fam = _v558_target_family_key(family)
        # SWING_PULLBACK has an intentionally strategy-native 2/3/4R ladder.
        # Do not let the generic dynamic-target multiplier distort the Swing
        # profile; the risk unit itself is already strategy-native.
        if str(fam).upper() == "SWING_PULLBACK":
            meta.update({"enabled": False, "reason": "strategy_native_swing_locked",
                         "family": fam, "base_rrs": (b1, b2, b3),
                         "dynamic_rrs": (b1, b2, b3)})
            return b1, b2, b3, meta
        fmult = float(
            (CONFIG.get("V558_TARGET_FAMILY_MULTIPLIERS", {}) or {}).get(fam, 1.0)
        )

        low, high = CONFIG.get("V558_TARGET_TOTAL_MULT_BOUNDS", (0.88, 1.12))
        total = max(float(low), min(float(high), q * v * fmult))

        # Keep the TP ladder monotonic and never let dynamic scaling dip below
        # the canonical hard economic TP1 floor.
        _hard_tp1_rr = max(0.0, float(CONFIG.get("MIN_NET_RR_TP1", 0.8)))
        _configured_tp1_rr = max(
            float(CONFIG.get("V558_TARGET_MIN_TP1_RR", 0.75)),
            _hard_tp1_rr,
        )
        rr1 = max(_configured_tp1_rr, b1 * total)
        _family_key = str(fam).upper()
        _tp2_floor = 2.40 if _family_key == "MEASURED_MOVE" else 0.0
        rr2 = max(rr1 + 0.10, _tp2_floor, b2 * total)
        rr3 = max(rr2 + 0.20, b3 * total)
        rr3 = min(float(CONFIG.get("V558_TARGET_MAX_TP3_RR", 6.50)), rr3)
        if rr3 <= rr2:
            rr2 = min(rr3 - 0.20, rr2)
        if rr2 <= rr1:
            rr1 = max(float(CONFIG.get("V558_TARGET_MIN_TP1_RR", 0.75)), rr2 - 0.20)

        # Never exceed the strongest bounded ExitProfile ceiling of 8R.
        rr1 = min(4.0, rr1)
        rr2 = min(8.0, rr2)
        rr3 = min(8.0, rr3)
        if not (0.5 <= rr1 < rr2 < rr3 <= 8.0):
            return b1, b2, b3, meta

        meta.update({
            "enabled": True,
            "score": float(score),
            "family": fam,
            "quality_mult": q,
            "vol_mult": v,
            "family_mult": fmult,
            "multiplier": total,
            "base_rrs": (b1, b2, b3),
            "dynamic_rrs": (rr1, rr2, rr3),
            "hard_tp1_rr_floor": _hard_tp1_rr,
        })
        return rr1, rr2, rr3, meta
    except Exception:
        return b1, b2, b3, meta


def _v558_apply_dynamic_targets_to_trade(
    trade: TradeState,
    *,
    entry: Optional[float] = None,
    sl: Optional[float] = None,
    atr: Optional[float] = None,
    score: Optional[float] = None,
    family: Optional[str] = None,
) -> Tuple[float, float, float, Dict[str, Any]]:
    """Apply dynamic target geometry to an existing TradeState."""
    e = float(entry if entry is not None else trade.entry)
    s = float(sl if sl is not None else trade.current_sl)
    a = float(atr if atr is not None else getattr(trade, "atr", 0.0))
    sc = float(score if score is not None else getattr(trade, "score", 0.0))
    fam = _v558_target_family_key(family if family is not None else trade)

    risk = e - s
    if e <= 0 or risk <= 0:
        return trade.tp1, trade.tp2, trade.tp3, {"enabled": False, "reason": "invalid_risk"}

    ep = getattr(trade, "exit_profile", {}) or {}
    base_rrs = (
        float(ep.get("tp1_rr", CONFIG.get("TP1_RR", 1.0))),
        float(ep.get("tp2_rr", CONFIG.get("TP2_RR", 2.0))),
        float(ep.get("tp3_rr", CONFIG.get("TP3_RR", 5.0))),
    )
    rr1, rr2, rr3, meta = _v558_dynamic_rrs(
        family=fam, score=sc, entry=e, sl=s, atr=a, base_rrs=base_rrs
    )

    tp1 = e + rr1 * risk
    tp2 = e + rr2 * risk
    tp3 = e + rr3 * risk

    # Hard ordering and family floor remain authoritative.
    try:
        if bool(CONFIG.get("V410_MASTER_ENABLE", True)):
            if not FamilyPolicyLayer.tp1_distance_ok(
                e, tp1, a, fam
            ):
                # Fall back to the canonical profile geometry.
                tp1 = e + base_rrs[0] * risk
                tp2 = e + base_rrs[1] * risk
                tp3 = e + base_rrs[2] * risk
                meta["fallback_reason"] = "family_tp1_floor"
    except Exception:
        _v647_record_suppressed_exception()

    trade.tp1, trade.tp2, trade.tp3 = float(tp1), float(tp2), float(tp3)
    meta["levels"] = (trade.tp1, trade.tp2, trade.tp3)
    return trade.tp1, trade.tp2, trade.tp3, meta


# =============================================================================
# v4.5.99-V640 FINAL — STRUCTURAL RECOVERY DEFINITIONS / LEGACY ADAPTER
# -----------------------------------------------------------------------------
# These helpers are called by SignalBuilder after the canonical fake-break
# detector rejects. The previous uploaded build referenced them but contained
# no definitions, so their NameError was swallowed and converted into a hard
# structural reject. Recovery remains PULLBACK/MTF_PULLBACK-only and every
# successful recovery continues through the canonical downstream gates.
# =============================================================================

def _v640_recovery_float(v: Any, default: float = float("nan")) -> float:
    try:
        x = float(v)
        return x if math.isfinite(x) else default
    except Exception:
        return default


def _v640_structural_recovery_core(
    candidate: Any, df_5m: Any, fake_ctx: Optional[Dict[str, Any]] = None,
    *, min_engine: float, min_htf: float, min_volume: float,
    min_rs: float, max_chase: float, min_confirmations: int,
    require_reclaim_or_hl: bool = True,
) -> Tuple[bool, Dict[str, Any]]:
    out: Dict[str, Any] = {"mode": "V640_PULLBACK_STRUCTURAL_RECOVERY", "reason": "not_eligible"}
    try:
        if candidate is None or df_5m is None or len(df_5m) < 35:
            return False, out
        fam = str(
            getattr(candidate, "family", "")
            or getattr(candidate, "strategy_mode", "")
            or (candidate.get("family") if isinstance(candidate, dict) else "")
            or ""
        ).upper()
        sm = str(
            getattr(candidate, "strategy_mode", "")
            or (candidate.get("strategy_mode") if isinstance(candidate, dict) else "")
            or fam
        ).upper()
        if fam not in {"PULLBACK", "MTF_PULLBACK"} and sm not in {"PULLBACK", "MTF_PULLBACK"}:
            return False, out

        fs = {}
        try:
            fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        except Exception:
            fs = {}
        if isinstance(candidate, dict):
            fs.update(dict(candidate.get("features_snapshot") or {}))

        eng = _v640_recovery_float(getattr(candidate, "engine_score", fs.get("engine_score", 0.0)))
        if not math.isfinite(eng) and isinstance(candidate, dict):
            eng = _v640_recovery_float(candidate.get("score", 0.0), 0.0) / 100.0
        # Legacy/current candidate engines use 0..1; tolerate a legacy 0..100
        # score only at the adapter boundary.
        if math.isfinite(eng) and eng > 1.0:
            eng /= 100.0

        htf = _v640_recovery_float(fs.get("htf_strength"), float("nan"))
        if not math.isfinite(htf):
            htf = _v640_recovery_float(fs.get("htf_alignment"), float("nan"))
            if math.isfinite(htf) and -1e-9 <= htf <= 1.0 + 1e-9:
                htf *= 100.0

        rs5 = _v640_recovery_float(fs.get("rs_5m", fs.get("rs_score_val", fs.get("relative_strength"))), float("nan"))
        if math.isfinite(rs5) and abs(rs5) > 1.5:
            rs5 /= 100.0
        if not math.isfinite(rs5):
            rs5 = 0.0

        lc = _v640_recovery_float(df_5m["close"].iloc[-2])
        pc = _v640_recovery_float(df_5m["close"].iloc[-3])
        op = _v640_recovery_float(df_5m["open"].iloc[-2])
        hi = _v640_recovery_float(df_5m["high"].iloc[-2])
        lo = _v640_recovery_float(df_5m["low"].iloc[-2])
        if not all(math.isfinite(x) and x > 0.0 for x in (lc, pc, op, hi, lo)) or hi < lo:
            return False, out

        prev_lows = [_v640_recovery_float(df_5m["low"].iloc[-i]) for i in (2, 3, 4)]
        higher_low = bool(all(math.isfinite(x) for x in prev_lows) and prev_lows[0] > prev_lows[1] >= prev_lows[2])
        bullish = bool(lc > op and lc >= pc)

        e20 = df_5m["close"].ewm(span=20, adjust=False).mean()
        e50 = df_5m["close"].ewm(span=50, adjust=False).mean()
        e20c = _v640_recovery_float(e20.iloc[-2])
        e20p = _v640_recovery_float(e20.iloc[-7]) if len(e20) >= 7 else float("nan")
        e50c = _v640_recovery_float(e50.iloc[-2])
        ema20_slope_up = bool(math.isfinite(e20c) and math.isfinite(e20p) and e20c > e20p)

        zone = getattr(candidate, "zone_ref", None)
        if zone is None and isinstance(candidate, dict):
            zone = candidate.get("zone_ref")
        if zone is None and isinstance(fake_ctx, dict):
            zone = fake_ctx.get("zone_ref")
        zone = _v640_recovery_float(zone, float("nan"))
        reclaim = bool(math.isfinite(zone) and pc < zone <= lc)

        rng = max(hi - lo, 1e-12)
        body_ratio = abs(lc - op) / rng
        lower_wick_ratio = max(0.0, min(lc, op) - lo) / rng

        vol = _v640_recovery_float(fs.get("volume_ratio"), float("nan"))
        if not math.isfinite(vol):
            try:
                avg = float(df_5m["volume"].iloc[-22:-2].mean())
                last = float(df_5m["volume"].iloc[-2])
                vol = last / avg if avg > 0 else float("nan")
            except Exception:
                vol = float("nan")
        if not math.isfinite(vol):
            return False, out

        atr = float("nan")
        try:
            atr_s = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
            atr = _v640_recovery_float(atr_s.iloc[-2])
        except Exception:
            _v647_record_suppressed_exception()
        if not math.isfinite(atr) or atr <= 0:
            return False, out
        chase = abs(_v640_recovery_float(getattr(candidate, "entry_ref", lc), lc) - lc) / atr
        if isinstance(fake_ctx, dict):
            fch = _v640_recovery_float(fake_ctx.get("chase_atr"), float("nan"))
            if math.isfinite(fch):
                chase = max(chase, fch)

        confirmations = sum(bool(x) for x in (bullish, reclaim, higher_low, ema20_slope_up))
        # Do not allow a bare shallow/low-wick candle to constitute the quorum.
        if require_reclaim_or_hl and not (reclaim or higher_low):
            return False, {**out, "reason": "no_zone_reclaim_or_higher_low"}

        if not (
            math.isfinite(eng) and eng >= float(min_engine)
            and math.isfinite(htf) and htf >= float(min_htf)
            and math.isfinite(vol) and vol >= float(min_volume)
            and math.isfinite(rs5) and rs5 >= float(min_rs)
            and math.isfinite(body_ratio) and body_ratio >= 0.20
            and math.isfinite(chase) and chase <= float(max_chase)
            and confirmations >= int(min_confirmations)
        ):
            return False, {
                **out, "reason": "quality_or_structure_threshold",
                "engine_score": eng, "htf_strength": htf, "volume_ratio": vol,
                "rs_5m": rs5, "body_ratio": body_ratio, "chase_atr": chase,
                "confirmations": confirmations,
            }

        out.update({
            "mode": "V640_PULLBACK_STRUCTURAL_RECOVERY",
            "reason": "verified_pullback_reclaim_quorum",
            "family": fam if fam in {"PULLBACK", "MTF_PULLBACK"} else sm,
            "engine_score": float(eng), "htf_strength": float(htf),
            "volume_ratio": float(vol), "rs_5m": float(rs5),
            "chase_atr": float(chase), "confirmations": int(confirmations),
            "bullish_close": bullish, "reclaim": reclaim,
            "higher_low": higher_low, "ema20_slope_up": ema20_slope_up,
            "body_ratio": float(body_ratio), "lower_wick_ratio": float(lower_wick_ratio),
            "e50_5m": float(e50c) if math.isfinite(e50c) else None,
        })
        return True, out
    except Exception as exc:
        return False, {**out, "reason": f"recovery_exception:{type(exc).__name__}"}


def _v631_verified_reclaim_structural_recovery(
    candidate: Any, df_5m: Any, fake_ctx: Optional[Dict[str, Any]] = None,
) -> bool:
    ok, ctx = _v640_structural_recovery_core(
        candidate, df_5m, fake_ctx,
        min_engine=0.86, min_htf=75.0, min_volume=0.90,
        min_rs=-0.0020, max_chase=0.80, min_confirmations=2,
        require_reclaim_or_hl=True,
    )
    if ok:
        STATS["v631_verified_reclaim_structural_recoveries"] = int(
            STATS.get("v631_verified_reclaim_structural_recoveries", 0) or 0
        ) + 1
    return bool(ok)


def _v642_adaptive_structural_recovery(
    candidate: Any, df_5m: Any, fake_ctx: Optional[Dict[str, Any]] = None,
) -> Tuple[bool, Dict[str, Any]]:
    ok, ctx = _v640_structural_recovery_core(
        candidate, df_5m, fake_ctx,
        min_engine=0.84, min_htf=70.0, min_volume=0.75,
        min_rs=-0.0025, max_chase=0.90, min_confirmations=2,
        require_reclaim_or_hl=True,
    )
    return bool(ok), dict(ctx or {})


def _v654_recovery_candidate_from_opp(
    symbol: str, opp: Any, df_5m: Any, **meta: Any
) -> Optional[StrategyCandidate]:
    """Read-only adapter from the current legacy opportunity into the canonical candidate shape."""
    try:
        if not isinstance(opp, dict):
            return None
        fam = str(opp.get("family") or opp.get("strategy_mode") or "").upper()
        if fam not in {"PULLBACK", "MTF_PULLBACK"}:
            return None

        fs = dict(opp.get("features_snapshot") or {})
        fs.update({k: v for k, v in opp.items() if k in {
            "htf_strength", "htf_alignment", "volume_ratio", "rs_5m",
            "strategy_mode", "strategy_style", "market_phase",
        }})
        entry = _v640_recovery_float(opp.get("entry_ref", opp.get("entry")), float("nan"))
        sl = _v640_recovery_float(opp.get("sl_price", opp.get("sl")), float("nan"))
        if not (math.isfinite(entry) and entry > 0 and math.isfinite(sl) and sl > 0 and sl < entry):
            if df_5m is not None:
                try:
                    entry = float(df_5m["close"].iloc[-2])
                    atr_s = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
                    atr = float(atr_s.iloc[-2])
                    sl = entry - float(CONFIG.get("ATR_SL_MULT", 1.2)) * atr
                except Exception:
                    return None
            else:
                return None
        risk = entry - sl
        rr1 = _v640_recovery_float(opp.get("tp1_rr"), float(CONFIG.get("TP1_RR", 1.0)))
        rr2 = _v640_recovery_float(opp.get("tp2_rr"), float(CONFIG.get("TP2_RR", 2.0)))
        rr3 = _v640_recovery_float(opp.get("tp3_rr"), float(CONFIG.get("TP3_RR", 5.0)))
        if not all(math.isfinite(x) and x > 0 for x in (rr1, rr2, rr3)):
            rr1, rr2, rr3 = float(CONFIG.get("TP1_RR", 1.0)), float(CONFIG.get("TP2_RR", 2.0)), float(CONFIG.get("TP3_RR", 5.0))

        fs.setdefault("htf_strength", meta.get("htf_strength"))
        fs.setdefault("tier", meta.get("tier"))
        return StrategyCandidate(
            engine_id="legacy_recovery_adapter",
            symbol=str(symbol), side="long",
            generated_at_ms=int(WALL_NOW() * 1000),
            entry_ref=float(entry), sl_price=float(sl),
            tp1_rr=float(rr1), tp2_rr=float(rr2), tp3_rr=float(rr3),
            engine_score=max(0.0, min(1.0, float(_v640_recovery_float(
                opp.get("_mse_global_engine_score", opp.get("engine_score", opp.get("score", 0.0) / 100.0)), 0.84
            )))),
            rr_ratio=float(risk and ((entry * 0.0 + rr1 * risk) / risk) or rr1),
            liquidity_score=float(_v640_recovery_float(opp.get("liquidity_score"), 1.0)),
            regime_fit=float(_v640_recovery_float(opp.get("regime_fit"), 1.0)),
            family=fam, zone_ref=float(_v640_recovery_float(opp.get("zone_ref"), entry)),
            features_snapshot=fs,
            strategy_mode=str(opp.get("strategy_mode") or fam).upper(),
            strategy_style=str(opp.get("strategy_style") or "SCALP").upper(),
            market_phase=str(opp.get("market_phase") or meta.get("market_phase") or "UNKNOWN"),
            macro_regime=str(opp.get("macro_regime") or meta.get("regime") or ""),
            local_regime=str(opp.get("local_regime") or meta.get("local_regime") or ""),
            bearish_severity=str(opp.get("bearish_severity") or meta.get("macro_severity") or ""),
        )
    except Exception:
        return None


def _v648_mtf_promotion_allowed(preferred_candidate: Optional["StrategyCandidate"]) -> bool:
    """Preserve Global Selection family/tier parity during canonical execution.

    A preferred candidate has already passed canonical prequalification under
    its selected family. Reclassifying PULLBACK -> MTF_PULLBACK after selection
    would mutate the policy contract and can create a false selected->queue
    tier-floor failure. Unpinned candidates may still receive the existing MTF
    promotion; candidates already selected as MTF remain eligible.
    """
    try:
        if preferred_candidate is None:
            return True
        family = str(
            getattr(preferred_candidate, "family", "")
            or getattr(preferred_candidate, "strategy_mode", "")
            or ""
        ).upper()
        return family == "MTF_PULLBACK"
    except Exception:
        # Fail-closed: preserve the selected family when candidate identity is
        # not reliably readable.
        return False


# =============================================================================
# V700 TERMINAL CLOSURE HELPERS — GLOBAL SL FLOOR COHERENCE
# =============================================================================
def _v700_enforce_global_sl_floor(*, entry: float, sl: float, atr: float, family: str = "") -> Optional[float]:
    """Repair an over-tight long stop to the existing configured hard floor.

    No hard floor is lowered. No structure, liquidity, fee, balance, exposure,
    PreSend, or execution gate is bypassed. Uncertainty fails closed.
    """
    try:
        e = float(entry); s = float(sl); a = float(atr)
        if not (math.isfinite(e) and math.isfinite(s) and e > 0.0 and 0.0 < s < e and math.isfinite(a) and a > 0.0):
            return None
        min_pct = max(0.0, float(CONFIG.get("MIN_SL_PCT", 0.40)))
        max_pct = max(min_pct, float(CONFIG.get("MAX_SL_PCT", 1.80)))
        current_pct = (e - s) / e * 100.0
        if current_pct + 1e-9 < min_pct:
            repaired = e * (1.0 - min_pct / 100.0)
            repaired_pct = (e - repaired) / e * 100.0
            if not (math.isfinite(repaired) and 0.0 < repaired < e and repaired_pct + 1e-9 >= min_pct and repaired_pct <= max_pct + 1e-9):
                STATS["v700_sl_floor_repair_rejects"] = int(STATS.get("v700_sl_floor_repair_rejects", 0) or 0) + 1
                return None
            STATS["v700_sl_floor_repairs"] = int(STATS.get("v700_sl_floor_repairs", 0) or 0) + 1
            STATS["v700_last_sl_floor_repair"] = {
                "family": str(family or ""), "entry": e, "old_sl": s,
                "new_sl": float(repaired), "old_pct": current_pct,
                "new_pct": repaired_pct, "atr": a, "ts": WALL_NOW(),
            }
            return float(repaired)
        return float(s)
    except Exception as exc:
        STATS["v700_sl_floor_errors"] = int(STATS.get("v700_sl_floor_errors", 0) or 0) + 1
        logger.warning("[V700-SL] floor repair exception: %s: %s", type(exc).__name__, exc)
        return None

def _v700_apply_final_sl_floor(entry: float, sl: float, atr: float, family: str, breakdown: Optional[Dict[str, Any]] = None) -> Optional[float]:
    out = _v700_enforce_global_sl_floor(entry=entry, sl=sl, atr=atr, family=family)
    if out is None:
        return None
    try:
        pct = (float(entry) - float(out)) / max(float(entry), 1e-12) * 100.0
        if breakdown is not None:
            breakdown["v700_final_sl_pct"] = float(pct)
            breakdown["v700_sl_floor_ok"] = bool(pct + 1e-9 >= float(CONFIG.get("MIN_SL_PCT", 0.40)))
    except Exception:
        _v647_record_suppressed_exception()
    return float(out)


# =============================================================================
# V702.1 FINAL AUDIT PATCH — NATIVE STRUCTURAL SL REFINEMENT
# -----------------------------------------------------------------------------
# Bounded, fail-closed refinement for non-PULLBACK native families. The generic
# V700 global floor remains the first authority; this layer may only widen the
# stop to a concrete, exact-candidate structural invalidation reference carried
# by the already prepared snapshot. No exchange read is performed here.
# =============================================================================
_V702_STRUCTURAL_SL_FAMILIES = frozenset({
    "BREAKOUT_RETEST", "BREAKOUT_CONTINUATION", "MEASURED_MOVE",
    "LIQUIDITY_SWEEP_REVERSAL", "MEAN_REVERSION", "MOMENTUM_EXPANSION",
    "LOCAL_STRENGTH_BREAKOUT", "COMPRESSION_EXPANSION", "SWING_PULLBACK",
    "EXTREME_FLUSH_REVERSAL", "CONTINUATION_RECLAIM", "FAILED_BREAKOUT_RECLAIM",
    "RELATIVE_STRENGTH", "RELATIVE_STRENGTH_LEADER", "TREND_CONTINUATION",
    "MICRO_TREND_CONTINUATION", "VOLATILITY_BURST", "OPPORTUNITY_SCOUT",
})

# V702 R2 — LOSS-CLOSURE EXIT GUARD. EXIT-ONLY: no entry gate, score floor,
# HTF floor, liquidity floor, ranking, or queue rule is changed.
CONFIG["V702_STRUCTURAL_FAILURE_EXIT_ENABLE"] = True
CONFIG["V702_STRUCTURAL_FAILURE_FAMILIES"] = (
    "LOCAL_STRENGTH_BREAKOUT", "COMPRESSION_EXPANSION",
    "BREAKOUT_RETEST", "BREAKOUT_CONTINUATION", "MEASURED_MOVE",
    "PULLBACK", "MTF_PULLBACK",
)
CONFIG["V702_STRUCTURAL_FAILURE_BUFFER_ATR"] = 0.10
CONFIG["V702_STRUCTURAL_FAILURE_CONFIRM_TICKS"] = 2
CONFIG["V702_STRUCTURAL_FAILURE_CONFIRM_SPACING_SEC"] = 0.30
CONFIG["V702_STRUCTURAL_FAILURE_MIN_AGE_SEC"] = 15.0
CONFIG["V702_STRUCTURAL_FAILURE_MIN_TRIGGER_R"] = 0.20
# LSB-only exit refinement: allow structural invalidation when the preserved
# trigger is 0.10R-0.20R above the live model SL. EXIT-ONLY; entry policy is
# unchanged.
CONFIG["V702_STRUCTURAL_FAILURE_MIN_TRIGGER_R_BY_FAMILY"] = {
    "LOCAL_STRENGTH_BREAKOUT": 0.10,
    # PULLBACK is stricter than the legacy default: exit only after a material
    # structural break remains clearly above the model SL, reducing full-stop
    # losses without touching entry eligibility.
    "PULLBACK": 0.35,
    "MTF_PULLBACK": 0.40,
}
CONFIG["V702_STRUCTURAL_FAILURE_CONTEXT_VERSION"] = "R5_PB_EXIT_LOSS_CLOSURE"
# Telegram transport noise guard: suppress only exact duplicate payloads within a
# short window when no delivery callback depends on the enqueue operation.
# Opportunity/exit semantics are unchanged; this is transport hygiene only.
CONFIG["V702_TELEGRAM_EXACT_DUPLICATE_SUPPRESS_ENABLE"] = True
CONFIG["V702_TELEGRAM_EXACT_DUPLICATE_SUPPRESS_SEC"] = 30.0

def _v702_structural_sl_num(v):
    try:
        x=float(v)
        return x if math.isfinite(x) and x > 0 else None
    except Exception:
        return None

def _v702_recent_closed_pivot_low(df_5m, lookback=7):
    try:
        if df_5m is None or len(df_5m) < 5:
            return None
        end=max(2, len(df_5m)-1)  # exclude current forming bar
        start=max(1, end-int(max(3, lookback)))
        vals=[]
        for i in range(start,end):
            v=_v702_structural_sl_num(df_5m["low"].iloc[i])
            if v is not None: vals.append(v)
        return min(vals) if vals else None
    except Exception:
        return None

def _v702_mtf_structural_sl(df_15m, entry: float, atr15: float, zone_ref: Optional[float] = None) -> Optional[float]:
    """MTF_Pullback stop anchored to the 15m pullback invalidation, not 5m ATR.

    The 1D/4H layers define direction; the 15m layer defines the pullback
    structure being invalidated. The 5m layer remains the trigger only.
    """
    try:
        e=float(entry); a=float(atr15)
        if df_15m is None or len(df_15m)<8 or not (math.isfinite(e) and e>0 and math.isfinite(a) and a>0):
            return None
        end=max(2, len(df_15m)-1)
        start=max(1, end-int(CONFIG.get("MTF_STRUCTURAL_SL_LOOKBACK_15M",8)))
        low=float(pd.to_numeric(df_15m["low"], errors="coerce").iloc[start:end].min())
        refs=[]
        if math.isfinite(low) and low>0 and low<e:
            refs.append(low - float(CONFIG.get("MTF_STRUCTURAL_SL_BUFFER_ATR",0.10))*a)
        if zone_ref is not None:
            z=float(zone_ref)
            if math.isfinite(z) and 0<z<e:
                refs.append(z - float(CONFIG.get("MTF_ZONE_SL_BUFFER_ATR",0.15))*a)
        refs=[x for x in refs if math.isfinite(x) and 0<x<e]
        if not refs: return None
        sl=min(refs)
        pct=(e-sl)/e*100.0
        min_pct=float(CONFIG.get("MIN_SL_PCT",0.40)); max_pct=float(CONFIG.get("MAX_SL_PCT",1.80))
        if pct < min_pct:
            sl=e*(1.0-min_pct/100.0); pct=min_pct
        if pct > max_pct:
            return None
        return float(sl)
    except Exception:
        return None


# Universal final-entry coherence: the strategy was evaluated on the last
# closed 5m candle, so a live reprice cannot be allowed to drift materially
# beyond the selected candidate or its strategy anchor. This is a hard
# anti-chase guard, not a signal-quality relaxation.
def _v702_final_entry_coherence(candidate: Any, opp: Dict[str, Any], entry: float, atr: float) -> Tuple[bool,str]:
    try:
        e=float(entry); a=float(atr)
        if not (math.isfinite(e) and e>0 and math.isfinite(a) and a>0):
            return False,"invalid_entry_or_atr"
        fam=str(opp.get("family", "") or "").upper()
        mode=str(opp.get("strategy_mode", fam) or fam).upper()
        fs={}
        if candidate is not None:
            fs.update(dict(getattr(candidate,"features_snapshot",{}) or {}))
        if isinstance(opp,dict):
            for k,v in opp.items():
                if k not in fs and k not in {"features_snapshot"}: fs[k]=v
        pref=0.0
        try:
            pref=float(getattr(candidate,"entry_ref",0.0) or 0.0) if candidate is not None else 0.0
        except Exception: pref=0.0
        if pref<=0:
            try: pref=float(fs.get("entry_ref",0.0) or 0.0)
            except Exception: pref=0.0
        # Candidate-to-live drift is hard capped for every strategy. This closes
        # the forming-bar/reprice gap without forcing an exchange refetch.
        max_drift_pct=float(CONFIG.get("V702_FINAL_ENTRY_MAX_DRIFT_PCT",0.50))
        max_drift_atr=float(CONFIG.get("V702_FINAL_ENTRY_MAX_DRIFT_ATR",0.60))
        if pref>0:
            dp=(e-pref)/pref*100.0
            da=(e-pref)/a
            if dp>max_drift_pct+1e-9 or da>max_drift_atr+1e-9:
                return False,f"candidate_drift:{dp:.3f}%/{da:.3f}ATR"
        # Family-native execution anchor. Only the families with an explicit
        # anchor are checked here; PULLBACK/MTF use their existing V580 zone guard.
        anchor=None
        for key in ("breakout_ref","retest_ref","reclaim_ref","zone_ref","family_native_entry_ref","entry_anchor","prior_high"):
            if fs.get(key) is not None:
                try:
                    z=float(fs.get(key));
                    if math.isfinite(z) and z>0:
                        anchor=z; break
                except Exception: pass
        if anchor is None:
            try:
                z=float(opp.get("zone_ref"));
                if math.isfinite(z) and z>0: anchor=z
            except Exception: pass
        if anchor is None or fam in {"PULLBACK","MTF_PULLBACK"}:
            return True,"ok"
        # For continuation/breakout families, entering materially above the
        # structure means the original thesis has changed. Use the detector's
        # native max-chase when available, otherwise a conservative 1.20 ATR.
        native_caps={
            # V702 risk-first closure: the observed live LSB loss entered at
            # roughly 0.65 ATR above its breakout reference. Keep detector recall
            # broad, but hard-cap final live authorization at 0.60 ATR.
            "LOCAL_STRENGTH_BREAKOUT": min(0.60, float(CONFIG.get("V702_LSB_FINAL_MAX_CHASE_ATR",0.60))),
            "COMPRESSION_EXPANSION": float(CONFIG.get("EXPANSION_MAX_CHASE_ATR",1.60)),
            "BREAKOUT_RETEST": 1.20,
            "BREAKOUT_CONTINUATION": 1.00,
            "MEASURED_MOVE": float(CONFIG.get("MEASURED_MOVE_MAX_CHASE_ATR",0.90)),
            "VOLATILITY_BURST": float(CONFIG.get("V45_VOLATILITY_BURST_MAX_CHASE_ATR",1.10)),
            "RELATIVE_STRENGTH": float(CONFIG.get("V45_RS_LEADER_MAX_CHASE_ATR",1.30)),
            "RELATIVE_STRENGTH_LEADER": float(CONFIG.get("V45_RS_LEADER_MAX_CHASE_ATR",1.30)),
            "TREND_CONTINUATION": float(CONFIG.get("V459_MICRO_TREND_MAX_CHASE_ATR",1.15)),
            "MICRO_TREND_CONTINUATION": float(CONFIG.get("V459_MICRO_TREND_MAX_CHASE_ATR",1.15)),
            "EXTREME_FLUSH_REVERSAL": float(CONFIG.get("EXTREME_FLUSH_MAX_CHASE_ATR",1.20)),
            "CONTINUATION_RECLAIM": float(CONFIG.get("CONTINUATION_RECLAIM_MAX_CHASE_ATR",1.25)),
            "FAILED_BREAKOUT_RECLAIM": float(CONFIG.get("FAILED_BREAKOUT_RECLAIM_MAX_CHASE_ATR",1.00)),
            "OPPORTUNITY_SCOUT": float(CONFIG.get("V521_SCOUT_MAX_CHASE_ATR",1.20)),
            "MOMENTUM_EXPANSION": 1.10,
        }
        cap=max(0.50,native_caps.get(fam,native_caps.get(mode,1.20)))
        chase=max(0.0,(e-anchor)/a)
        if chase>cap+1e-9:
            return False,f"final_anchor_chase:{chase:.3f}ATR>max={cap:.3f}ATR"
        return True,"ok"
    except Exception as exc:
        return False,f"exception:{type(exc).__name__}"


def _v702_structural_sl_candidates(candidate, snapshot):
    fs={}
    try: fs.update(dict(getattr(candidate,"features_snapshot",{}) or {}))
    except Exception: pass
    if isinstance(candidate,dict):
        try: fs.update(dict(candidate.get("features_snapshot") or {}))
        except Exception: pass
    if isinstance(snapshot,dict):
        try:
            snap_fs=snapshot.get("features_snapshot") or snapshot.get("prepared_features") or {}
            if isinstance(snap_fs,dict): fs.update(snap_fs)
        except Exception: pass
    out=[]
    for key in ("family_native_sl_ref","structural_invalidation","invalidation_level",
                "sweep_low","swept_low","support_lower","pullback_low","zone_ref",
                "breakout_ref","retest_low"):
        v=_v702_structural_sl_num(fs.get(key))
        if v is None and key=="zone_ref":
            try: v=_v702_structural_sl_num(getattr(candidate,"zone_ref",None))
            except Exception: v=None
        if v is not None: out.append((key,v))
    _df5 = fs.get("df_5m")
    if _df5 is None and isinstance(snapshot,dict):
        _df5 = snapshot.get("df_5m")
    pivot=_v702_recent_closed_pivot_low(_df5)
    if pivot is None:
        try: pivot=_v702_recent_closed_pivot_low(getattr(candidate,"df_5m",None))
        except Exception: pivot=None
    if pivot is not None: out.append(("recent_closed_pivot_low",pivot))
    # deterministic de-duplication, preserving source priority
    seen=set(); clean=[]
    for k,v in out:
        q=round(float(v),12)
        if q not in seen:
            seen.add(q); clean.append((k,float(v)))
    return clean

def _v702_refine_structural_sl(entry, sl, atr, family, breakdown=None):
    try:
        e=float(entry); current=float(sl); a=float(atr); fam=str(family or "").upper()
        if not bool(CONFIG.get("V702_STRUCTURAL_SL_ENABLE", True)):
            return current
        if fam in {"PULLBACK","MTF_PULLBACK"} or fam not in _V702_STRUCTURAL_SL_FAMILIES:
            return current
        ctx=globals().get("_V702_NATIVE_STRUCTURE_CTX")
        ctx=ctx.get() if ctx is not None and hasattr(ctx,"get") else None
        if not isinstance(ctx,dict):
            if breakdown is not None: breakdown["v702_structural_sl"]={"status":"context_unavailable"}
            return current
        cand=ctx.get("candidate"); snap=ctx.get("snapshot")
        if cand is None or not isinstance(snap,dict):
            if breakdown is not None: breakdown["v702_structural_sl"]={"status":"exact_context_missing"}
            return current
        if str(getattr(cand,"symbol","") or (cand.get("symbol") if isinstance(cand,dict) else "")).upper() != str(getattr(ctx,"symbol",snap.get("symbol","") if isinstance(snap,dict) else "") or snap.get("symbol","")).upper():
            # exact context object is authoritative; an explicit symbol conflict is fail-closed
            if breakdown is not None: breakdown["v702_structural_sl"]={"status":"symbol_context_mismatch"}
            return current
        fs=getattr(cand,"features_snapshot",{}) or (cand.get("features_snapshot") if isinstance(cand,dict) else {}) or {}
        if isinstance(fs,dict) and fs.get("hard_valid") is False:
            if breakdown is not None: breakdown["v702_structural_sl"]={"status":"candidate_hard_invalid"}
            return current
        closed_ts=snap.get("closed_candle_ts") or snap.get("candle_ts")
        if closed_ts is None:
            if breakdown is not None: breakdown["v702_structural_sl"]={"status":"closed_bar_data_unavailable"}
            return current
        # The context wrapper already binds the prepared snapshot and candidate.
        min_pct=max(0.40,float(CONFIG.get("MIN_SL_PCT",0.40)))
        max_pct=max(min_pct,float(CONFIG.get("MAX_SL_PCT",1.80)))
        buf=max(0.05,min(0.20,float(CONFIG.get("V702_STRUCTURAL_SL_BUFFER_ATR",0.10))))
        best=current; meta=None
        for label,ref in _v702_structural_sl_candidates(cand,snap):
            if not (math.isfinite(ref) and ref>0 and ref<e): continue
            proposed=ref-buf*a
            if not (math.isfinite(proposed) and proposed>0): continue
            proposed=max(proposed, e*(1.0-max_pct/100.0))
            pct=(e-proposed)/e*100.0
            if pct+1e-9<min_pct or pct-1e-9>max_pct: continue
            if proposed < best-1e-12:
                best=proposed; meta={"reference":label,"reference_price":ref,"buffer_atr":buf,"atr":a,"sl_pct":pct}
        if best < current-1e-12:
            STATS["v702_structural_sl_refinements"]=int(STATS.get("v702_structural_sl_refinements",0) or 0)+1
            STATS[f"v702_structural_sl_family.{fam}"]=int(STATS.get(f"v702_structural_sl_family.{fam}",0) or 0)+1
            if breakdown is not None: breakdown["v702_structural_sl"]={"status":"applied","old_sl":current,"new_sl":best,**(meta or {})}
            return float(best)
        if breakdown is not None: breakdown["v702_structural_sl"]={"status":"unchanged_no_safe_widening"}
        return current
    except Exception as exc:
        STATS["v702_structural_sl_errors"]=int(STATS.get("v702_structural_sl_errors",0) or 0)+1
        try: _v593_note_suppressed_exception("v702.structural_sl",exc)
        except Exception: pass
        return sl

_V702_V700_FLOOR_IMPL=_v700_apply_final_sl_floor
def _v702_apply_final_sl_floor_with_structure(entry, sl, atr, family, breakdown=None):
    out=_V702_V700_FLOOR_IMPL(entry,sl,atr,family,breakdown)
    if out is None: return None
    refined=_v702_refine_structural_sl(entry,out,atr,family,breakdown)
    if refined is None or not math.isfinite(float(refined)): return None
    e=float(entry); pct=(e-float(refined))/e*100.0 if e>0 else float("inf")
    if pct < max(0.40,float(CONFIG.get("MIN_SL_PCT",0.40)))-1e-9:
        refined=e*(1.0-max(0.40,float(CONFIG.get("MIN_SL_PCT",0.40)))/100.0); pct=(e-refined)/e*100.0
    if pct > float(CONFIG.get("MAX_SL_PCT",1.80))+1e-9: return None
    if breakdown is not None:
        breakdown["v702_final_sl_pct"]=pct
        breakdown["v702_sl_bounds_ok"]=True
    return float(refined)

_v700_apply_final_sl_floor=_v702_apply_final_sl_floor_with_structure


def _v702_build_structural_invalidation_context(candidate: Any, snapshot: Dict[str, Any],
                                                family: str, entry: float, sl: float,
                                                atr: float) -> Dict[str, Any]:
    """Create immutable, execution-only thesis-failure context from exact candidate data."""
    try:
        fam = str(family or "").upper()
        allowed = {str(x).upper() for x in CONFIG.get("V702_STRUCTURAL_FAILURE_FAMILIES", ())}
        e, current_sl, a = float(entry), float(sl), float(atr)
        if not (fam in allowed and math.isfinite(e) and e > 0 and math.isfinite(current_sl)
                and current_sl > 0 and current_sl < e and math.isfinite(a) and a > 0):
            return {"version":"R5","armed":False,"reason":"invalid_base_context","family":fam}
        fs: Dict[str, Any] = {}
        try:
            cfs = getattr(candidate, "features_snapshot", {}) or {}
            if isinstance(cfs, dict): fs.update(cfs)
        except Exception:
            pass
        if isinstance(candidate, dict):
            try:
                cfs = candidate.get("features_snapshot") or {}
                if isinstance(cfs, dict): fs.update(cfs)
            except Exception:
                pass
        if isinstance(snapshot, dict):
            try:
                for key in ("features_snapshot", "prepared_features"):
                    x = snapshot.get(key) or {}
                    if isinstance(x, dict):
                        for k, v in x.items():
                            fs.setdefault(k, v)
            except Exception:
                pass
        refs = (
            ("structural_invalidation", fs.get("structural_invalidation")),
            ("invalidation_level", fs.get("invalidation_level")),
            ("breakout_ref", fs.get("breakout_ref")),
            ("retest_ref", fs.get("retest_ref")),
            ("reclaim_ref", fs.get("reclaim_ref")),
            ("prior_high", fs.get("prior_high")),
            ("zone_ref", fs.get("zone_ref")),
        )
        try:
            z = getattr(candidate, "zone_ref", None)
            if z is not None: refs = refs + (("candidate.zone_ref", z),)
        except Exception:
            pass
        ref = None; source = ""
        for label, raw in refs:
            try:
                x = float(raw)
                if math.isfinite(x) and x > 0 and x < e:
                    ref, source = x, label
                    break
            except Exception:
                continue
        if ref is None:
            return {"version":"R5","armed":False,"reason":"reference_unavailable","family":fam}
        buf = max(0.05, min(0.20, float(CONFIG.get("V702_STRUCTURAL_FAILURE_BUFFER_ATR", 0.10))))
        trigger = ref - buf * a
        if not (math.isfinite(trigger) and trigger > 0 and trigger > current_sl):
            return {"version":"R5","armed":False,"reason":"trigger_not_above_current_sl",
                    "family":fam,"reference":ref,"source":source,"buffer_atr":buf}
        risk = max(e - current_sl, 1e-12)
        trigger_room_r = (e - trigger) / risk
        _family_min_map = CONFIG.get("V702_STRUCTURAL_FAILURE_MIN_TRIGGER_R_BY_FAMILY", {})
        _family_min_raw = _family_min_map.get(fam) if isinstance(_family_min_map, dict) else None
        min_room = max(0.10, float(_family_min_raw if _family_min_raw is not None
                                    else CONFIG.get("V702_STRUCTURAL_FAILURE_MIN_TRIGGER_R", 0.20)))
        if not (math.isfinite(trigger_room_r) and trigger_room_r >= min_room):
            return {"version":"R5","armed":False,"reason":"trigger_room_below_min",
                    "family":fam,"reference":ref,"trigger":trigger,"trigger_room_r":trigger_room_r,
                    "min_trigger_r":min_room,"source":source,"buffer_atr":buf}
        return {
            "version":"R5","armed":True,"family":fam,"reference":float(ref),
            "trigger":float(trigger),"source":source,"buffer_atr":float(buf),"atr":float(a),
            "entry":float(e),"model_sl":float(current_sl),"trigger_room_r":float(trigger_room_r),
            "min_trigger_r":float(min_room),"armed_at":WALL_NOW(),
        }
    except Exception as exc:
        STATS["v702_structural_invalidation_context_errors"] = int(
            STATS.get("v702_structural_invalidation_context_errors", 0) or 0
        ) + 1
        try: _v593_note_suppressed_exception("v702.structural_invalidation_context", exc)
        except Exception: pass
        return {"version":"R5","armed":False,"reason":f"exception:{type(exc).__name__}"}


async def _v702_structural_failure_guard(exchange: Any, trade: TradeState, current_price: float) -> bool:
    """Exit-only structural thesis-failure guard routed through the canonical exit authority."""
    try:
        if not bool(CONFIG.get("V702_STRUCTURAL_FAILURE_EXIT_ENABLE", True)):
            return False
        if not bool(getattr(trade, "structural_invalidation_armed", False)):
            return False
        if bool(getattr(trade, "tp1_exit_completed", False)) or str(getattr(trade, "status", "")) != "entry_filled":
            return False
        fam = str(getattr(trade, "signal_family", "") or getattr(trade, "strategy_mode", "")).upper()
        allowed = {str(x).upper() for x in CONFIG.get("V702_STRUCTURAL_FAILURE_FAMILIES", ())}
        if fam not in allowed:
            return False
        age = _v570_entry_age_sec(trade)
        if not math.isfinite(age) or age < max(0.0, float(CONFIG.get("V702_STRUCTURAL_FAILURE_MIN_AGE_SEC", 15.0))):
            return False
        px = float(current_price or 0.0)
        trigger = float(getattr(trade, "structural_invalidation_trigger", 0.0) or 0.0)
        cur_sl = float(getattr(trade, "current_sl", 0.0) or getattr(trade, "original_sl", 0.0) or 0.0)
        if not (math.isfinite(px) and px > 0 and math.isfinite(trigger) and trigger > 0
                and math.isfinite(cur_sl) and cur_sl > 0 and trigger > cur_sl and px <= trigger):
            if math.isfinite(px) and px > trigger:
                trade.structural_invalidation_fail_count = 0
            return False
        now = MONO_NOW()
        last = float(getattr(trade, "structural_invalidation_last_ts", 0.0) or 0.0)
        spacing = max(0.0, float(CONFIG.get("V702_STRUCTURAL_FAILURE_CONFIRM_SPACING_SEC", 0.30)))
        if last > 0 and now - last < spacing:
            return False
        trade.structural_invalidation_last_ts = now
        trade.structural_invalidation_fail_count = int(getattr(trade, "structural_invalidation_fail_count", 0) or 0) + 1
        need = max(1, int(CONFIG.get("V702_STRUCTURAL_FAILURE_CONFIRM_TICKS", 2) or 2))
        if trade.structural_invalidation_fail_count < need:
            logger.info(
                f"[V702-R5] {trade.symbol} structural thesis breach confirmation "
                f"{trade.structural_invalidation_fail_count}/{need} px={px:.10g} trigger={trigger:.10g}"
            )
            return False
        trade.last_exit_authority = "STRUCTURAL_INVALIDATION_PENDING"
        ok = await OrderExecutor.emergency_close(exchange, trade, "structural_invalidation", exit_px=px)
        if ok:
            STATS["v702_structural_invalidation_exits"] = int(
                STATS.get("v702_structural_invalidation_exits", 0) or 0
            ) + 1
            STATS[f"v702_structural_invalidation_exits.{fam}"] = int(
                STATS.get(f"v702_structural_invalidation_exits.{fam}", 0) or 0
            ) + 1
            trade.structural_invalidation_fail_count = 0
            logger.warning(
                f"[V702-R5] {trade.symbol} STRUCTURAL_INVALIDATION exit family={fam} "
                f"px={px:.10g} trigger={trigger:.10g} "
                f"ref={float(getattr(trade,'structural_invalidation_reference',0.0) or 0.0):.10g}"
            )
            return True
        return False
    except Exception as exc:
        STATS["v702_structural_invalidation_guard_errors"] = int(
            STATS.get("v702_structural_invalidation_guard_errors", 0) or 0
        ) + 1
        logger.warning("[V702-R5] structural invalidation guard suppressed %s: %s", getattr(trade, "symbol", "?"), exc)
        return False


async def _v702_a52_persist_protected_trade(trade: "TradeState", protection_mode: str,
                                           venue_order_id: str = "") -> bool:
    """Best-effort durable update after protection is already armed/verified.

    Storage failure never erases a live in-memory position or escapes before the
    caller returns that position. It latches new entries and logs a recovery event.
    """
    symbol = str(getattr(trade, "symbol", "") or "UNKNOWN")
    all_ok = True
    try:
        await DBManager.asave_trade_snapshot(trade)
    except Exception as exc:
        all_ok = False
        live_entries_block(f"protected_trade_snapshot_persist_failed_{symbol}",
                           where="SignalBuilder.post_protection_persist")
        STATS["v702_post_protection_snapshot_failures"] = int(
            STATS.get("v702_post_protection_snapshot_failures", 0) or 0
        ) + 1
        logger.critical("[A52-PROTECTION] %s is protected in memory, but snapshot persistence failed: %s",
                        symbol, type(exc).__name__)
    intent_id = str(getattr(trade, "entry_intent_id", "") or "")
    if intent_id:
        state = "FILL_RECONCILIATION_PENDING" if bool(getattr(trade, "entry_reconcile_required", False)) else "PROTECTION_ARMED"
        details = {"protection_mode": str(protection_mode),
                   "sl": _v557_safe_float(getattr(trade, "current_sl", 0.0)),
                   "entry_reconcile_required": bool(getattr(trade, "entry_reconcile_required", False)),
                   "post_protection_persist_helper": True}
        if str(protection_mode).upper() == "NATIVE_SL_VERIFIED":
            details["sl_order_id"] = str(venue_order_id or getattr(trade, "sl_order_id", "") or "")
        try:
            await DBManager.aupdate_execution_intent(
                intent_id, state, venue_order_id=str(venue_order_id or "") or None, details=details)
        except Exception as exc:
            all_ok = False
            live_entries_block(f"protected_intent_persist_failed_{symbol}",
                               where="SignalBuilder.post_protection_persist")
            STATS["v702_post_protection_intent_failures"] = int(
                STATS.get("v702_post_protection_intent_failures", 0) or 0
            ) + 1
            logger.critical("[A52-PROTECTION] %s protection is active, but execution intent state persistence failed: %s",
                            symbol, type(exc).__name__)
    return all_ok


class SignalBuilder:

    @staticmethod
    async def build_and_route(exchange, symbol: str, market_data: Dict, preferred_candidate: Optional[StrategyCandidate] = None) -> Optional[TradeState]:
        """
        End-to-end pipeline for a single symbol:
          Regime → HTF → Router → Micro-struct confirm → Score → PreSend → Submit
        """
        df_4h = market_data.get("df_4h")
        df_1h = market_data.get("df_1h")
        df_15m = market_data.get("df_15m")
        df_5m = market_data.get("df_5m")
        df_btc_5m = market_data.get("df_btc_5m")
        df_btc_15m = market_data.get("df_btc_15m")
        df_btc_1h = market_data.get("df_btc_1h")
        df_btc_4h = market_data.get("df_btc_4h")
        quote_vol_24h = float(market_data.get("quote_vol_24h", 0))

        trace_id = LifecycleTrace.new(symbol)

        # ---- v4.0.8 STARV-A/B — COOLDOWN pre-gates (REENTRY only) + G-count
        # ordering ----
        # Rationale: the v4.0.7 pre-gate armed SYMBOL_COOLDOWN at the TOP of
        # build_and_route BEFORE any pipeline work, which suppressed re-scan
        # of a symbol for a full SYMBOL_COOLDOWN_SEC window even if the
        # symbol never reached scoring/execution. That single decision was
        # the dominant contributor to reject.cooldown.symbol_scan in top-
        # rejects and to overall E/Q/S starvation.
        #
        # STARV-A relocates the symbol_scan arm to AFTER microstructure
        # (see below). REENTRY cooldown stays here because it protects
        # against re-entering a JUST-CLOSED position — a real risk gate,
        # not a scan throttle.
        #
        # STARV-B: STATS["signals_generated"] is now incremented AFTER the
        # reentry / pre-gate symbol_scan check so the G counter only counts
        # symbols that ACTUALLY entered the analysis pipeline; suppressed
        # ones go into signals_scanned_cooldown_skipped instead. This fixes
        # the misleading G/E ratio in telemetry.
        _sym_cd_mode = str(CONFIG.get("SYMBOL_COOLDOWN_MODE", "post_microstruct")).lower()
        try:
            _now_cd = MONO_NOW()
            _sym_cd_sec = float(CONFIG.get("SYMBOL_COOLDOWN_SEC", 0) or 0)
            _reentry_cd_sec = float(CONFIG.get("REENTRY_COOLDOWN_SEC", 0) or 0)

            # Legacy pre_gate mode kept for A/B rollback — arms scan cooldown
            # at the top exactly like v4.0.7 did.
            if _sym_cd_mode == "pre_gate" and _sym_cd_sec > 0:
                _last_scan_ts = float(COOLDOWNS.get("symbol_scan", {}).get(symbol, 0.0) or 0.0)
                if _last_scan_ts > 0 and (_now_cd - _last_scan_ts) < _sym_cd_sec:
                    STATS["signals_scanned_cooldown_skipped"] = \
                        STATS.get("signals_scanned_cooldown_skipped", 0) + 1
                    record_rejection(trace_id, symbol, "cooldown", "symbol_scan",
                                     "cooldown",
                                     ctx={"age_sec": _now_cd - _last_scan_ts,
                                          "cooldown_sec": _sym_cd_sec,
                                          "mode": _sym_cd_mode})
                    return None
                COOLDOWNS.setdefault("symbol_scan", {})[symbol] = _now_cd

            # REENTRY cooldown ALWAYS applies at the top — it protects
            # against churn on the same symbol immediately after an exit.
            # v4.0.9 DS-4 — entry may be a legacy bare float (uniform
            # REENTRY_COOLDOWN_SEC) OR a tuple (armed_ts, cd_sec) written by
            # _finalize_and_record_r when the dynamic feature is enabled.
            _re_entry = COOLDOWNS.get("reentry", {}).get(symbol)
            _last_exit_ts = 0.0
            _dyn_cd_sec = _reentry_cd_sec
            _dyn_source = "legacy_uniform"
            if isinstance(_re_entry, tuple) and len(_re_entry) == 2:
                try:
                    _last_exit_ts = float(_re_entry[0] or 0.0)
                    _dyn_cd_sec = float(_re_entry[1] or _reentry_cd_sec)
                    _dyn_source = "dynamic_by_reason"
                except Exception:
                    _last_exit_ts = 0.0
                    _dyn_cd_sec = _reentry_cd_sec
            else:
                try:
                    _last_exit_ts = float(_re_entry or 0.0)
                except Exception:
                    _last_exit_ts = 0.0
            if _dyn_cd_sec > 0 and _last_exit_ts > 0 \
               and (_now_cd - _last_exit_ts) < _dyn_cd_sec:
                STATS["signals_scanned_cooldown_skipped"] = \
                    STATS.get("signals_scanned_cooldown_skipped", 0) + 1
                record_rejection(trace_id, symbol, "cooldown", "reentry_recent_exit",
                                 "cooldown",
                                 ctx={"age_sec": _now_cd - _last_exit_ts,
                                      "cooldown_sec": _dyn_cd_sec,
                                      "source": _dyn_source})
                return None
        except Exception as _cd_e:
            logger.debug(f"[Cooldown] pre-gate suppressed {symbol}: {_cd_e}")

        # STARV-B — count G only for symbols that reached the pipeline.
        STATS["signals_generated"] += 1
        try:
            V423Funnel.note_stage("G")
            _V420State.note_g()
        except Exception:
            _v647_record_suppressed_exception()

        # ---- Layer 3: Regime / BTC / Tier ----
        tier = LiquidityTier.classify(quote_vol_24h)
        if not LiquidityTier.is_tradeable(tier):
            record_rejection(trace_id, symbol, "liquidity", "below_tier",
                             "universe_pruning", ctx={"tier": tier})
            record_stage_reject("stage_g_to_e_rejected_by_liquidity")
            return None

        # BTC regime: general market context for ALL symbols (not just BTC itself).
        # If df_btc_4h is None for non-BTC symbols, regime uses last-known (hysteresis).
        # v4.0.7 TWEAK — BEARISH is no longer an absolute hard block. It is now
        # a bounded soft-gate:
        #   (a) only counter-trend / reversion families are allowed to proceed
        #       (LIQUIDITY_SWEEP_REVERSAL, MEAN_REVERSION);
        #   (b) a score penalty is applied AFTER scoring (higher effective
        #       min_score) instead of returning None here.
        # This preserves fail-closed intent (bearish regime still restrictive)
        # while reducing starvation from reject.htf.regime_bearish. Structural
        # long families in BEARISH are still rejected — kept explicit below.
        regime = MarketRegime.classify_from_btc_4h(df_btc_4h)

        # v4.2.5 — MACRO severity + LOCAL regime (additive, fail-closed).
        # macro regime stays the BTC truth; we decompose BEARISH into
        # NORMAL/STRESSED/CRASH and compute a per-symbol LOCAL regime so a
        # long-bearish market no longer implies unconditional no-trade.
        # Crash Guard is ABSOLUTE: it can never be overridden by recovery.
        try:
            macro_severity = V425BearishSeverity.classify(regime, df_btc_15m, df_btc_4h)
        except Exception:
            macro_severity = V425BearishSeverity.CRASH  # fail-closed
        try:
            local_regime = V425LocalRegime.classify(regime, df_15m, df_5m)
        except Exception:
            local_regime = V425LocalRegime.BEARISH  # fail-closed
        try:
            STATS['v425_local_regime'] = local_regime
            STATS['v425_macro_severity'] = macro_severity
        except Exception:
            _v647_record_suppressed_exception()
        # v4.2.5 — Crash Guard hard gate: BEARISH_CRASH => zero new longs.
        if regime == "BEARISH" and not V425BearishSeverity.allows_new_long(macro_severity):
            STATS['bearish_recovery_crash_blocks'] = STATS.get('bearish_recovery_crash_blocks', 0) + 1
            record_rejection(trace_id, symbol, "htf", "bearish_crash_guard", "regime",
                             ctx={"severity": macro_severity, "regime": regime})
            record_stage_reject("stage_g_to_e_rejected_by_regime")
            return None

        # BTC short-term context: general market risk for ALL symbols.
        btc_ctx = BTCContext.evaluate(df_btc_15m)
        if BTCContext.blocks_new_entries():
            record_rejection(trace_id, symbol, "htf",
                             f"btc_context_{btc_ctx.lower()}", "regime",
                             ctx=BTCContext.snapshot())
            record_stage_reject("stage_g_to_e_rejected_by_btc_context")
            return None

        # ---- Layer 4: HTF Grading ----
        _v425_countertrend_prefilter = False
        htf_pass, htf_state, htf_strength, htf_reason = HTFGrader.grade(df_1h, label=symbol)
        try:
            _rh,_rsrc,_rage=_v689_resolve_htf_strength(symbol,{"symbol":symbol,"df_1h":df_1h,"df_4h":df_4h,"df_5m":df_5m,"htf_strength":htf_strength,"htf_state":htf_state,"htf_reason":htf_reason},preferred_candidate)
            if _rh is not None and float(htf_strength or 0.0)<=0:
                htf_strength=float(_rh); htf_reason="htf.recomputed"; htf_state=str(_rsrc); htf_pass=False
        except Exception:
            pass
        htf_repeat_backoff_v410(symbol, not htf_pass)
        # v4.2.5 — family/regime-aware HTF rule. We do NOT reinterpret macro
        # bearish as bullish: htf_pass stays False in BEARISH and the macro
        # floor is NOT zeroed. Instead, when macro=BEARISH we first attempt a
        # bounded Bearish Recovery candidate; if the recovery engine qualifies
        # it (closed-bars local confirmations + bounded recovery score +
        # non-crash severity), the candidate proceeds on LOCAL evidence with
        # strategy_mode='BEARISH_RECOVERY'. Any failure => original reject.
        _v425_recovery_opp = None
        if not htf_pass and regime == "BEARISH" and htf_state == "BEARISH":
            try:
                _v425_rs = None
                if df_btc_15m is not None and len(df_btc_15m) >= 21 and len(df_5m) >= 21:
                    _btc_r = (float(df_btc_15m["close"].iloc[-2]) - float(df_btc_15m["close"].iloc[-21])) / max(1e-9, float(df_btc_15m["close"].iloc[-21]))
                    _sym_r = (float(df_5m["close"].iloc[-2]) - float(df_5m["close"].iloc[-21])) / max(1e-9, float(df_5m["close"].iloc[-21]))
                    _v425_rs = _sym_r - _btc_r
            except Exception:
                _v425_rs = None
            try:
                _v425_recovery_opp = V425BearishRecovery.try_build(
                    symbol, regime, macro_severity, tier, df_15m, df_5m,
                    rs_vs_btc=_v425_rs)
            except Exception as _v425_e:
                logger.debug(f"[V425] recovery build suppressed {symbol}: {_v425_e}")
                _v425_recovery_opp = None
            if _v425_recovery_opp is None:
                # v4.2.7: bounded countertrend prefilter. In macro BEARISH,
                # allow routing ONLY when a closed-bar liquidity sweep or mean-
                # reversion detector already sees a concrete reversal setup.
                # Crash remains an absolute block.
                if (bool(CONFIG.get("V425_COUNTERTREND_ROUTING_ENABLE", True))
                        and V425BearishSeverity.allows_new_long(macro_severity)):
                    try:
                        _sw_match, _ = OpportunityDetectors.detect_liquidity_sweep(df_15m, df_5m)
                    except Exception:
                        _sw_match = False
                    try:
                        _mr_match, _ = OpportunityDetectors.detect_mean_reversion(df_5m)
                    except Exception:
                        _mr_match = False
                    _allow_sw = bool(CONFIG.get("V425_COUNTERTREND_ALLOW_SWEEP_IN_BEARISH", True))
                    _allow_mr = bool(CONFIG.get("V425_COUNTERTREND_ALLOW_MR_IN_BEARISH", True))
                    _v425_countertrend_prefilter = bool((_sw_match and _allow_sw) or (_mr_match and _allow_mr))
                if not _v425_countertrend_prefilter:
                    record_rejection(trace_id, symbol, "htf", "core_not_aligned",
                                     "htf_grader", ctx={"state": htf_state, "reason": htf_reason,
                                                        "backoff": COOLDOWNS.get("htf_backoff", {}).get(symbol),
                                                        "local_regime": local_regime,
                                                        "macro_severity": macro_severity})
                    record_stage_reject("stage_g_to_e_rejected_by_htf")
                    return None
                STATS["bearish_countertrend_prefilter_hits"] = STATS.get("bearish_countertrend_prefilter_hits", 0) + 1
            else:
                # recovery qualified: macro HTF stays bearish, proceed on local
                # evidence. htf_strength remains 0.0 by design.
                STATS["bearish_recovery_qualified"] = STATS.get("bearish_recovery_qualified", 0) + 1
        elif not htf_pass:
            # v4.5.18 bounded MTF bridge: neutral 1H may pass only when
            # 4H+15m+5m closed-bar alignment is materially bullish.
            _bridge_ok, _bridge_strength, _bridge_ctx = _v518_neutral_local_htf_bridge(
                df_1h, df_4h, df_15m, df_5m, regime, local_regime, htf_strength, ""
            )
            if _bridge_ok:
                htf_pass=True; htf_state="BRIDGED_BULLISH"; htf_strength=float(_bridge_strength)
                STATS["v518_htf_bridge_pass"] = STATS.get("v518_htf_bridge_pass",0)+1
                if bool(CONFIG.get("V518_POLICY_RECOVERY_OBS_ENABLE",True)):
                    LifecycleTrace.record(trace_id,"V518_HTF_BRIDGE_PASS",dict(_bridge_ctx or {}))
            else:
                # Establish the identical market-phase context before any HTF
                # recovery path consumes it. Phase failure remains descriptive and
                # fail-closed; it must not become an UnboundLocalError.
                try:
                    _phase_ctx = MarketPhaseDetector.detect(
                        df_5m=df_5m, df_15m=df_15m, df_1h=df_1h,
                        macro_regime=regime, local_regime=local_regime
                    )
                except Exception as _phase_exc:
                    _phase_ctx = {"phase": "UNKNOWN", "context_error": type(_phase_exc).__name__}
                    STATS["v702_phase_context_errors"] = int(STATS.get("v702_phase_context_errors", 0) or 0) + 1
                # V646 SELECTED→CANONICAL PARITY: a globally-selected candidate
                # may have already passed the existing bounded V528 HTF recovery
                # contract during canonical prequalification. Re-evaluate that
                # SAME contract against the CURRENT snapshot before declaring a
                # fresh hard HTF failure. This closes the observed mismatch where
                # prequal=PASS/selected=1 was followed by builder=htf.core_not_aligned.
                # Unknown/error/missing data remains fail-closed inside V528.
                _v646_selected_htf_recovered = False
                _v646_selected_htf_ctx = {}
                try:
                    if (preferred_candidate is not None
                            and bool(CONFIG.get("V646_SELECTED_HTF_PARITY_ENABLE", True))
                            and callable(globals().get("_v528_htf_recovery_allowed"))):
                        _v646_snap = dict(market_data or {})
                        _v646_snap.update({
                            "tier": tier, "regime": regime, "macro_regime": regime,
                            "local_regime": local_regime,
                            "market_phase": _phase_ctx,
                            "macro_severity": macro_severity,
                            "bearish_severity": macro_severity,
                            "htf_strength": htf_strength,
                            "htf_pass": False, "htf_state": htf_state,
                            "htf_reason": htf_reason,
                            "symbol": symbol,
                        })
                        _v646_selected_htf_recovered, _v646_selected_htf_ctx = _v528_htf_recovery_allowed(
                            preferred_candidate, _v646_snap, "htf.core_not_aligned"
                        )
                        if _v646_selected_htf_recovered:
                            _v646_eff = float((_v646_selected_htf_ctx or {}).get(
                                "effective_htf", htf_strength) or htf_strength
                            )
                            htf_pass = True
                            htf_state = "V528_SELECTED_RECOVERED"
                            htf_strength = max(float(htf_strength), _v646_eff)
                            STATS["v646_selected_htf_parity_pass"] = int(
                                STATS.get("v646_selected_htf_parity_pass", 0) or 0
                            ) + 1
                            try:
                                LifecycleTrace.record(trace_id, "V646_SELECTED_HTF_PARITY_PASS",
                                                       dict(_v646_selected_htf_ctx or {}))
                            except Exception:
                                _v647_record_suppressed_exception()
                            logger.info(
                                f"[V646-HTF-PARITY] {symbol} selected=1 recovered=1 "
                                f"htf={htf_strength:.1f} reason=V528_SELECTED_RECOVERED"
                            )
                except Exception as _v646_sel_htf_exc:
                    STATS["v646_selected_htf_parity_errors"] = int(
                        STATS.get("v646_selected_htf_parity_errors", 0) or 0
                    ) + 1
                    logger.debug(f"[V646-HTF-PARITY] suppressed {symbol}: {_v646_sel_htf_exc}")

                if not _v646_selected_htf_recovered:
                    _v702_soft_builder_ok, _v702_soft_builder_ctx = _v702_soft_htf_alignment_allowed(
                        preferred_candidate, family=str(getattr(preferred_candidate, "family", "") or ""),
                        strategy_mode=str(getattr(preferred_candidate, "strategy_mode", "") or ""),
                        regime=regime, local_regime=local_regime, severity=str(macro_severity),
                        htf_state=htf_state, htf_strength=htf_strength, htf_reason=htf_reason,
                        snapshot={**dict(market_data or {}), "regime": regime, "macro_regime": regime,
                                  "local_regime": local_regime, "htf_strength": htf_strength,
                                  "htf_state": htf_state, "htf_reason": htf_reason})
                    if _v702_soft_builder_ok:
                        # This is not an alignment claim: only the local-first strategy gate may continue.
                        _v646_selected_htf_recovered = True
                        STATS["v702_htf_soft_builder_context_passes"] = int(STATS.get("v702_htf_soft_builder_context_passes", 0) or 0) + 1
                        try:
                            LifecycleTrace.record(trace_id, "V702_HTF_SOFT_BUILDER_CONTEXT_PASS", dict(_v702_soft_builder_ctx))
                        except Exception:
                            _v647_record_suppressed_exception()
                    else:
                        STATS["v518_htf_bridge_reject"] = STATS.get("v518_htf_bridge_reject",0)+1
                        record_rejection(trace_id, symbol, "htf", "core_not_aligned",
                                         "htf_grader", ctx={"state": htf_state, "reason": htf_reason,
                                                            "backoff": COOLDOWNS.get("htf_backoff", {}).get(symbol),
                                                            "bridge": _bridge_ctx,
                                                            "soft_context": dict(_v702_soft_builder_ctx or {})})
                        record_stage_reject("stage_g_to_e_rejected_by_htf")
                        return None

        # ---- Layer 4: Opportunity Router ----
        # V703 FINAL: MTF/PULLBACK are independent strategies. The MTF lane must
        # never depend on the ordinary PULLBACK detector to obtain its 1D context.
        # The scanner now supplies D1 on a bounded rotating MTF lane; this builder
        # fallback remains only for legacy/single-symbol calls that arrive without
        # D1. It therefore never gates D1 acquisition on PULLBACK anymore.
        if bool(CONFIG.get("MTF_PULLBACK_ENABLE", True)) and market_data.get("df_1d") is None:
            try:
                raw_1d = await safe_api_call(
                    f"ohlcv_1d_mtf_{symbol}",
                    exchange.fetch_ohlcv(
                        symbol, "1d",
                        limit=max(
                            int(CONFIG.get("MTF_PULLBACK_MIN_D1_CANDLES", 60)),
                            int(CONFIG.get("V410_D1_MIN_CANDLES", 80)),
                            80,
                        ) + 5,
                    ))
                if _PDNP_OK:
                    _cols_1d = ["ts", "open", "high", "low", "close", "volume"]
                    _df1d_mtf = pd.DataFrame(raw_1d, columns=_cols_1d)
                    _df1d_mtf["ts"] = pd.to_datetime(_df1d_mtf["ts"], unit="ms", utc=True)
                    _df1d_mtf.set_index("ts", inplace=True)
                    if len(_df1d_mtf) >= int(CONFIG.get("MTF_PULLBACK_MIN_D1_CANDLES", 60)):
                        market_data["df_1d"] = _df1d_mtf
                        STATS["mtf_pullback_d1_fetches"] = int(STATS.get("mtf_pullback_d1_fetches", 0) or 0) + 1
                    else:
                        STATS["mtf_pullback_d1_fetch_short"] = int(STATS.get("mtf_pullback_d1_fetch_short", 0) or 0) + 1
            except Exception as _mtf_d1_e:
                STATS["mtf_pullback_d1_fetch_failed"] = int(STATS.get("mtf_pullback_d1_fetch_failed", 0) or 0) + 1
                logger.debug(f"[MTF-PB] D1 independent fallback fetch suppressed {symbol}: {_mtf_d1_e}")

        # v4.0.7-MSE — Multi-Strategy Candidate Engine hook (additive,
        # minimal-diff, fail-closed). When MSE is enabled it produces the
        # winner via multi-engine generation + composite ranking + conflict
        # resolution. On disabled / shadow / any failure it returns None and
        # we transparently fall back to the legacy OpportunityRouter — the
        # v4.0.6 behaviour is byte-for-byte preserved in that path.
        opp = None
        try:
            _phase_ctx = MarketPhaseDetector.detect(
                df_5m=df_5m, df_15m=df_15m, df_1h=df_1h,
                macro_regime=regime, local_regime=local_regime
            )
            _mse_snapshot = {
                "symbol": symbol,
                "df_1d": market_data.get("df_1d"),
                "df_4h": df_4h,
                "df_1h": df_1h,
                "df_15m": df_15m,
                "df_5m": df_5m,
                "df_btc_5m": df_btc_5m,
                "df_btc_15m": df_btc_15m,
                "df_btc_1h": df_btc_1h,
                "df_btc_4h": df_btc_4h,
                "tier": tier,
                "regime": regime,
                "macro_regime": regime,
                "local_regime": local_regime,
                "macro_severity": macro_severity,
                "bearish_severity": macro_severity,
                "market_phase": _phase_ctx,
                "btc_context": btc_ctx,
                "htf_strength": htf_strength,
            }
            _snap_ok, _snap_reason = validate_mse_snapshot(_mse_snapshot)
            if not _snap_ok:
                MSE_STATUS["fallback_count"] = int(MSE_STATUS.get("fallback_count",0) or 0) + 1
                STATS["mse_router_fallback_missing_context"] = STATS.get("mse_router_fallback_missing_context",0)+1
                # V700-AUDIT: a selected candidate is an exact canonical handoff.
                # Never discard its identity and fall through to the legacy router,
                # because that creates the observed SELECTED -> router:no_family_matched
                # false failure. Missing mandatory context is still fail-closed.
                if preferred_candidate is not None:
                    _snap_detail = str(STATS.get("mse_snapshot_invalid_detail") or _snap_reason or "mse_snapshot_invalid")
                    _handoff_reason = f"preferred_candidate_snapshot:{_snap_detail}"
                    STATS["v701_current_builder_block"] = {"symbol":str(symbol),"stage":"preferred_candidate_handoff",
                                                           "reason":_handoff_reason,"cycle_id":V702PipelineMetrics._cycle(),
                                                           "candidate_key":V702PipelineMetrics.current_candidate_key(),
                                                           "trace_id":trace_id,"ts":WALL_NOW()}
                    STATS["v701_last_handoff_reason"] = _handoff_reason
                    STATS["v700_selected_handoff_blocks"] = int(STATS.get("v700_selected_handoff_blocks",0) or 0) + 1
                    STATS["v545_last_builder_blocker"] = _handoff_reason
                    try:
                        record_rejection(
                            trace_id, symbol, "execution", _handoff_reason,
                            "preferred_candidate_handoff",
                            ctx={"snapshot_reason": _snap_reason, "selected_candidate": True}
                        )
                    except Exception:
                        _v647_record_suppressed_exception()
                    return None
                opp = None
            else:
                if preferred_candidate is not None:
                    # Global Brain already selected this exact candidate. Pin
                    # the strategy/family metadata into the canonical builder
                    # while still forcing every downstream policy/score/risk/SL
                    # gate to run normally. Never trust caller-side geometry.
                    _pc = preferred_candidate
                    _pc_reason = CompositeRankingEngine._validate_fail_closed(_pc)
                    _pc_fresh_ok, _pc_fresh_reason, _pc_age = _v455_candidate_freshness_ok(
                        getattr(_pc, "generated_at_ms", None)
                    )
                    if (not _pc_fresh_ok) or _pc_reason or _pc.symbol != symbol or _pc.side != "long":
                        STATS["v45_preferred_candidate_invalidated"] = STATS.get("v45_preferred_candidate_invalidated",0)+1
                        _pin_reason = str(_pc_reason or _pc_fresh_reason or "preferred_candidate_invalid")
                        _handoff_reason = f"preferred_candidate_invalid:{_pin_reason}"
                        STATS["v701_current_builder_block"] = {"symbol":str(symbol),"stage":"preferred_candidate_handoff",
                                                               "reason":_handoff_reason,"cycle_id":V702PipelineMetrics._cycle(),
                                                               "candidate_key":V702PipelineMetrics.current_candidate_key(),
                                                               "trace_id":trace_id,"ts":WALL_NOW()}
                        STATS["v701_last_handoff_reason"] = _handoff_reason
                        STATS["v545_last_builder_blocker"] = _handoff_reason
                        STATS["v545_builder_blocker"] = int(STATS.get("v545_builder_blocker",0) or 0) + 1
                        STATS["v545_builder_blocker_reasons"] = STATS.get("v545_builder_blocker_reasons") or {}
                        STATS["v545_builder_blocker_reasons"][_handoff_reason] = int(
                            STATS["v545_builder_blocker_reasons"].get(_handoff_reason,0) or 0
                        ) + 1
                        STATS["v700_selected_handoff_blocks"] = int(STATS.get("v700_selected_handoff_blocks",0) or 0) + 1
                        logger.info(
                            f"[V700-HANDOFF-BLOCK] {symbol} stage=preferred_candidate "
                            f"reason={_pin_reason} age={_pc_age}"
                        )
                        try:
                            record_rejection(
                                trace_id, symbol, "execution", _handoff_reason,
                                "preferred_candidate_handoff",
                                ctx={"fresh": _pc_fresh_ok, "fresh_reason": _pc_fresh_reason,
                                     "candidate_reason": _pc_reason, "age_sec": _pc_age,
                                     "selected_candidate": True}
                            )
                        except Exception:
                            _v647_record_suppressed_exception()
                        # Crucial: a selected candidate must never mutate into a
                        # different legacy strategy after selection. Reject only.
                        return None
                    else:
                        _pf = dict(_pc.features_snapshot or {})
                        opp = dict(_pf)
                        opp.update({
                            "symbol": symbol,
                            "family": str(_pc.family or _pc.strategy_mode or "PULLBACK").upper(),
                            "strategy_mode": str(_pc.strategy_mode or _pc.family or "").upper(),
                            "strategy_style": str(_pc.strategy_style or "SCALP").upper(),
                            "timeframe_profile": str(_pc.timeframe_profile or (_pf.get("timeframe_profile") if isinstance(_pf, dict) else "") or ""),
                            "exit_profile": dict(_pf.get("exit_profile") or {}),
                            "candidate_sl_price": float(_pc.sl_price),
                            "candidate_entry_ref": float(_pc.entry_ref),
                            "candidate_tp1_rr": float(_pc.tp1_rr),
                            "candidate_tp2_rr": float(_pc.tp2_rr),
                            "candidate_tp3_rr": float(_pc.tp3_rr),
                            "zone_ref": float(_pc.zone_ref),
                            "score": float(_pc.engine_score) * 100.0,
                            "entry_ref": float(_pc.entry_ref),
                            "_mse_global_composite": float(_mse_global_composite if '_mse_global_composite' in locals() else _pc.engine_score),
                            "_mse_global_engine_score": float(_pc.engine_score),
                            "_mse_global_candidate": True,
                        })
                        STATS["v45_global_pinned_routes"] = STATS.get("v45_global_pinned_routes",0)+1
                        _set_mse_status("ACTIVE", "mse_global_candidate_pinned")
                        LifecycleTrace.record(trace_id, "V45_GLOBAL_PIN", {
                            "strategy_mode": opp.get("strategy_mode"),
                            "family": opp.get("family"),
                            "zone_ref": opp.get("zone_ref"),
                            "engine_score": _pc.engine_score,
                        })
                else:
                    opp = MultiStrategyEngine.pick_opportunity(_mse_snapshot)
                    if opp is not None:
                        STATS["mse_router_hits"] = STATS.get("mse_router_hits", 0) + 1
                        _set_mse_status("ACTIVE", "mse_cycle_ok")
                        LifecycleTrace.record(trace_id, "MSE_PICK", opp.get("_mse", {}))
        except Exception as _mse_e:
            STATS["mse_router_fallback_exception"] =                 STATS.get("mse_router_fallback_exception", 0) + 1
            MSE_STATUS["fallback_count"] = int(MSE_STATUS.get("fallback_count",0) or 0) + 1
            MSE_STATUS["engine_errors"] = int(MSE_STATUS.get("engine_errors",0) or 0) + 1
            _set_mse_status("DEGRADED", f"mse_router_fallback_exception:{type(_mse_e).__name__}")
            if preferred_candidate is not None:
                # Selected candidate handoff failures are terminal for this exact
                # candidate. Do not mutate the strategy through legacy routing.
                _handoff_reason = f"preferred_candidate_handoff:engine_exception:{type(_mse_e).__name__}"
                STATS["v701_current_builder_block"] = {"symbol":str(symbol),"stage":"preferred_candidate_handoff",
                                                       "reason":_handoff_reason,"cycle_id":V702PipelineMetrics._cycle(),
                                                       "candidate_key":V702PipelineMetrics.current_candidate_key(),
                                                       "trace_id":trace_id,"ts":WALL_NOW()}
                STATS["v701_last_handoff_reason"] = _handoff_reason
                STATS["v700_selected_handoff_blocks"] = int(STATS.get("v700_selected_handoff_blocks",0) or 0) + 1
                STATS["v545_last_builder_blocker"] = _handoff_reason
                try:
                    record_rejection(trace_id, symbol, "execution", _handoff_reason,
                                     "preferred_candidate_handoff",
                                     ctx={"error": type(_mse_e).__name__, "selected_candidate": True})
                except Exception:
                    _v647_record_suppressed_exception()
                logger.warning(f"[V700-HANDOFF-BLOCK] {symbol}: {_mse_e} — selected candidate rejected fail-closed")
                return None
            logger.warning(f"[MSE.router-hook] {symbol}: {_mse_e} — falling back to legacy OpportunityRouter")
            opp = None
        if opp is None and preferred_candidate is not None:
            # Defensive terminal handoff rule: a selected candidate may only be
            # accepted as itself or rejected; it may not become a router candidate.
            _handoff_reason = "preferred_candidate_handoff:unresolved"
            STATS["v701_current_builder_block"] = {"symbol":str(symbol),"stage":"preferred_candidate_handoff",
                                                   "reason":_handoff_reason,"cycle_id":V702PipelineMetrics._cycle(),
                                                   "candidate_key":V702PipelineMetrics.current_candidate_key(),
                                                   "trace_id":trace_id,"ts":WALL_NOW()}
            STATS["v701_last_handoff_reason"] = _handoff_reason
            STATS["v700_selected_handoff_blocks"] = int(STATS.get("v700_selected_handoff_blocks",0) or 0) + 1
            STATS["v545_last_builder_blocker"] = _handoff_reason
            try:
                record_rejection(trace_id, symbol, "execution", _handoff_reason,
                                 "preferred_candidate_handoff",
                                 ctx={"selected_candidate": True})
            except Exception:
                _v647_record_suppressed_exception()
            return None
        if opp is None:
            opp = OpportunityRouter.classify({
                "symbol":symbol,"df_1d":market_data.get("df_1d"),"df_4h":df_4h,
                "df_15m":df_15m,"df_5m":df_5m,
                "regime":regime,"tier":tier,"htf_strength":htf_strength})
        if opp is None and CONFIG.get("V410_MASTER_ENABLE", True):
            # Lowest-priority tail path; never substitutes for later safety gates.
            opp = FamilyPolicyLayer.tail_catcher(df_15m, df_5m)
            if opp is not None:
                V410Telemetry.inc("family_tail_catcher_matched")
        # v4.2.5 — if a Bearish Recovery candidate was qualified at the HTF
        # gate it takes precedence here: the router/tail could not match a
        # family under macro BEARISH (by design), so the recovery engine is the
        # ONLY source of a bounded long candidate. Downstream hard gates apply.
        if _v425_recovery_opp is not None:
            if opp is None:
                opp = _v425_recovery_opp
                try:
                    V410Telemetry.inc("bearish_recovery_router_candidate")
                    LifecycleTrace.record(trace_id, "BEARISH_RECOVERY_CANDIDATE",
                                          {"score": _v425_recovery_opp.get("recovery_score"),
                                           "local_regime": _v425_recovery_opp.get("local_regime"),
                                           "severity": _v425_recovery_opp.get("macro_severity")})
                except Exception:
                    _v647_record_suppressed_exception()
            else:
                # Router matched a family despite macro BEARISH (e.g. sweep /
                # reversion). Keep the router result but tag the recovery
                # context so downstream diagnostics stay coherent.
                try:
                    opp.setdefault("_v425_recovery_available", True)
                except Exception:
                    _v647_record_suppressed_exception()
        if opp is None:
            STATS["no_family_matched_count"] = STATS.get("no_family_matched_count", 0) + 1
            try:
                _V420State.note_nfm()
            except Exception:
                _v647_record_suppressed_exception()
            _near_ctx = _v423_nearest_family(
                df_15m, df_5m, regime=regime, tier=tier,
                htf_strength=htf_strength, symbol=symbol)
            _near_ctx["btc_context"] = btc_ctx
            _near_ctx["volume_ratio"] = None
            try:
                V422NearMiss.note_router_miss(symbol, _near_ctx)
            except Exception:
                _v647_record_suppressed_exception()
            record_rejection(
                trace_id, symbol, "structural", "no_family_matched", "router",
                ctx=_near_ctx)
            record_stage_reject("stage_g_to_e_rejected_by_router")
            return None

        # Optional D1 context: fetch only for symbols that already have a
        # routed opportunity. Any D1 ambiguity is neutral for scoring; it never
        # creates a signal and D1_BIAS_HARD_BLOCK remains opt-in.
        if CONFIG.get("V410_D1_FETCH_ENABLE", True) and market_data.get("df_1d") is None:
            try:
                raw_1d = await safe_api_call(
                    f"ohlcv_1d_{symbol}",
                    exchange.fetch_ohlcv(symbol, "1d", limit=int(CONFIG.get("V410_D1_MIN_CANDLES", 80)) + 5))
                if _PDNP_OK:
                    _cols_1d = ["ts", "open", "high", "low", "close", "volume"]
                    _df1d = pd.DataFrame(raw_1d, columns=_cols_1d)
                    _df1d["ts"] = pd.to_datetime(_df1d["ts"], unit="ms", utc=True)
                    _df1d.set_index("ts", inplace=True)
                    market_data["df_1d"] = _df1d
            except Exception as _d1e:
                STATS["v410_d1_fetch_failed"] = STATS.get("v410_d1_fetch_failed", 0) + 1
                logger.debug(f"[D1] {symbol}: {_d1e}")

        # v4.2.6 / V648 — promote an UNPINNED normal pullback to the stricter
        # MTF family only when 1D + 4H + 15m + 5m confluence is fully proven.
        # A globally-selected preferred_candidate is already canonically
        # prequalified under its exact family/tier policy. Re-promoting it here
        # would mutate PULLBACK -> MTF_PULLBACK after prequalification and can
        # create a deterministic post-selection tier-floor rejection. Therefore
        # pinned candidates keep their selected family/strategy metadata intact;
        # an already-MTF selected candidate remains MTF. This is parity-only:
        # no gate is lowered and no new execution path is created.
        try:
            _mtf_ok, _mtf_meta = OpportunityDetectors.detect_mtf_pullback(
                market_data.get("df_1d"), df_4h, df_15m, df_5m)
            if _mtf_ok:
                _preferred_family = str(
                    getattr(preferred_candidate, "family", "")
                    or getattr(preferred_candidate, "strategy_mode", "")
                    or ""
                ).upper()
                _preferred_pinned = preferred_candidate is not None
                _allow_promotion = _v648_mtf_promotion_allowed(preferred_candidate)
                if _allow_promotion:
                    opp = dict(opp or {})
                    opp.update(_mtf_meta)
                    opp["family"] = "MTF_PULLBACK"
                    opp["strategy_mode"] = "MTF_PULLBACK"
                    STATS["mtf_pullback_qualified"] = STATS.get("mtf_pullback_qualified", 0) + 1
                    LifecycleTrace.record(trace_id, "MTF_PULLBACK_QUALIFIED", {
                        "anchor": _mtf_meta.get("anchor"),
                        "zone_ref": _mtf_meta.get("zone_ref"),
                        "dist_atr": _mtf_meta.get("dist_atr"),
                        "rsi_5m": _mtf_meta.get("rsi_5m"),
                        "volume_ratio": _mtf_meta.get("volume_ratio"),
                        "pinned_candidate": bool(_preferred_pinned),
                        "promotion_blocked_for_parity": bool(
                            _preferred_pinned and _preferred_family != "MTF_PULLBACK"
                        ),
                    })
                    if _preferred_pinned and _preferred_family == "MTF_PULLBACK":
                        STATS["v648_selected_mtf_promotion_parity_passes"] = int(
                            STATS.get("v648_selected_mtf_promotion_parity_passes", 0) or 0
                        ) + 1
                elif _preferred_pinned:
                    STATS["v648_selected_family_promotion_blocks"] = int(
                        STATS.get("v648_selected_family_promotion_blocks", 0) or 0
                    ) + 1
                    LifecycleTrace.record(trace_id, "V648_SELECTED_FAMILY_PARITY",
                                          {"selected_family": _preferred_family,
                                           "detected_family": "MTF_PULLBACK",
                                           "reason": "preserve_prequalified_family"})
        except Exception as _mtf_promote_e:
            logger.debug(f"[MTF-PB] promotion suppressed {symbol}: {_mtf_promote_e}")

        # V4.1 family policy: rejects are explicit and bounded by family;
        # this does not relax balance, SL, circuit breaker, or exchange gates.
        _v410_family = str(opp.get("family", "PULLBACK")).upper()
        # v4.2.5 — candidate strategy mode (empty for ordinary candidates).
        _v425_mode = str(opp.get("strategy_mode", "")).upper()
        # Universal Dual Confirmation keeps its engine-level mode for registry
        # telemetry, but its selected branch family is the canonical policy/exit
        # identity used by the builder. Otherwise the generic mode would fall
        # back to PULLBACK exits even when the selected branch is BREAKOUT_RETEST.
        if _v425_mode == "DUAL_CONFIRMATION_ENTRY" and _v410_family in {"PULLBACK", "BREAKOUT_RETEST"}:
            _v425_mode = _v410_family
        _v425_is_recovery = (_v425_mode == "BEARISH_RECOVERY")
        if _v425_mode == "MEASURED_MOVE":
            try:
                mm_target=float(opp.get("measured_target",0.0) or 0.0)
                mm_rr=float(opp.get("measured_rr",0.0) or 0.0)
                mm_min=float(CONFIG.get("MEASURED_MOVE_MIN_TARGET_RR",2.4))
                if mm_target<=0 or mm_rr<mm_min:
                    record_rejection(trace_id,symbol,"structural","measured_move_target_infeasible","router",ctx={"measured_target":mm_target,"measured_rr":mm_rr,"min_rr":mm_min})
                    record_stage_reject("stage_g_to_e_rejected_by_router")
                    return None
                STATS["measured_move_qualified"]=STATS.get("measured_move_qualified",0)+1
                LifecycleTrace.record(trace_id,"MEASURED_MOVE_QUALIFIED",{"target":mm_target,"rr":mm_rr,"impulse_leg":opp.get("impulse_leg"),"contraction_pct":opp.get("pattern_contraction_pct")})
            except Exception as e:
                logger.debug(f"[MeasuredMove] validation suppressed {symbol}: {e}")
                record_rejection(trace_id,symbol,"structural","measured_move_validation_error","router")
                record_stage_reject("stage_g_to_e_rejected_by_router")
                return None
        _v689_reuse_prequal = False
        try:
            _v689_reuse_prequal = bool(preferred_candidate is not None and _v689_prequal_snapshot_reusable(preferred_candidate, market_data))
            if _v689_reuse_prequal: STATS["v689_builder_reused_prequal"]=int(STATS.get("v689_builder_reused_prequal",0) or 0)+1
        except Exception:
            _v689_reuse_prequal=False
        if CONFIG.get("V410_MASTER_ENABLE", True) and CONFIG.get("V410_FAMILY_POLICY_ENABLE", True):
            # --- canonical regime gate (FamilyPolicyLayer is the ONLY source) ---
            _phase_raw = opp.get("market_phase")
            if isinstance(_phase_raw, dict):
                _policy_phase = str(_phase_raw.get("phase", "") or "")
            elif isinstance(_phase_raw, str):
                _policy_phase = _phase_raw
            else:
                _policy_phase = ""
            _policy_style = str(opp.get("strategy_style", ""))
            _canonical_regime_ok, _policy_reason, _policy_ctx = FamilyPolicyLayer.regime_policy_detail(
                _v410_family, regime,
                strategy_mode=_v425_mode or _v410_family,
                local_regime=local_regime,
                market_phase=_policy_phase,
                severity=str(macro_severity),
                strategy_style=_policy_style,
            )
            # Bounded v4.5.7 recovery remains inside FamilyPolicyLayer and is
            # used only for eligible NEUTRAL+LOCAL_BULLISH candidates. It never
            # bypasses structure, HTF, tier, liquidity, score or execution gates.
            _policy_recovered = False
            _policy_recovery_reason = "not_attempted"
            if not _canonical_regime_ok:
                _recovered, _policy_recovery_reason, _policy_recovery_ctx = FamilyPolicyLayer.bounded_neutral_recovery_allowed(
                    _v410_family, regime,
                    strategy_mode=_v425_mode or _v410_family,
                    local_regime=local_regime,
                    market_phase=_policy_phase,
                    severity=str(macro_severity),
                    strategy_style=_policy_style,
                    candidate_features=dict(opp or {}),
                    snapshot=dict(market_data or {}),
                    htf_strength=htf_strength,
                )
                if _recovered:
                    _canonical_regime_ok = True
                    _policy_recovered = True
                    STATS["v457_policy_recovery_runtime_passes"] = STATS.get("v457_policy_recovery_runtime_passes", 0) + 1
                    LifecycleTrace.record(trace_id, "POLICY_RECOVERY_PASS", dict(_policy_recovery_ctx or {}))
            # v4.2.5 — Bearish Recovery exception remains explicit and isolated.
            if not _canonical_regime_ok and _v425_is_recovery and \
                    bool(CONFIG.get("V425_BEARISH_RECOVERY_ENABLE", True)):
                _canonical_regime_ok = True
                V410Telemetry.inc("bearish_recovery_regime_gate_pass")
            # v4.5.19 DIRECT POLICY MACRO BRIDGE: the v4.5.18 bridge could
            # repair the HTF-strength gate, but it was reached only AFTER the
            # canonical family regime gate.  That left the exact starvation
            # seen in production logs intact: `family_regime_disallowed.macro`
            # could terminate the candidate before the strong 4H/15m/5m bridge
            # was allowed to speak.  We may bypass ONLY the macro-regime policy
            # mismatch, and ONLY for NEUTRAL + LOCAL_BULLISH + NORMAL contexts
            # with the full closed-bar MTF bridge.  Local/phase/style/severity
            # mismatches remain hard rejects.  All downstream HTF/tier/score/
            # structure/balance/SL/PreSend/execution gates remain authoritative.
            _v518_policy_bridge_ok = False
            _v518_policy_bridge_ctx = {}
            if (not _canonical_regime_ok
                    and str(_policy_reason or "").lower() == "macro"
                    and bool(CONFIG.get("V518_DIRECT_POLICY_MACRO_BRIDGE_ENABLE", True))):
                try:
                    _v518_policy_bridge_ok, _v518_policy_bridge_strength, _v518_policy_bridge_ctx = (
                        _v518_neutral_local_htf_bridge(
                            df_1h, df_4h, df_15m, df_5m, regime, local_regime,
                            htf_strength, _v425_mode or _v410_family
                        )
                    )
                    if _v518_policy_bridge_ok:
                        _canonical_regime_ok = True
                        _policy_recovered = True
                        htf_strength = max(float(htf_strength), float(_v518_policy_bridge_strength))
                        STATS["v518_direct_policy_macro_bridge_pass"] = int(
                            STATS.get("v518_direct_policy_macro_bridge_pass", 0) or 0) + 1
                        if bool(CONFIG.get("V518_POLICY_RECOVERY_OBS_ENABLE", True)):
                            LifecycleTrace.record(trace_id, "V518_POLICY_MACRO_BRIDGE_PASS", dict(_v518_policy_bridge_ctx or {}))
                except Exception as _v518_bridge_policy_exc:
                    _v518_policy_bridge_ctx = {
                        "enabled": False,
                        "reason": "bridge_exception",
                        "exception_type": type(_v518_bridge_policy_exc).__name__,
                    }
            if not _canonical_regime_ok and _v689_reuse_prequal:
                # A prior prequal verdict cannot override current macro/family
                # policy. Record the attempted reuse, then preserve the reject.
                STATS["v702_a47_policy_reuse_override_blocked"] = int(
                    STATS.get("v702_a47_policy_reuse_override_blocked", 0) or 0) + 1
                if isinstance(_policy_ctx, dict):
                    _policy_ctx["prequal_reuse_policy_override"] = "BLOCKED_CURRENT_POLICY_AUTHORITATIVE"
                    _policy_ctx["prequal_reuse_cycle_scoped"] = True
            if not _canonical_regime_ok:
                _ctx = dict(_policy_ctx or {})
                _ctx.update({"policy_reason": _policy_reason,
                             "recovery_attempted": True,
                             "recovery_reason": _policy_recovery_reason,
                             "recovery_active": bool(_v457_policy_recovery_active()),
                             "family": _v410_family, "regime": regime,
                             "local_regime": local_regime, "severity": macro_severity,
                             "tier": tier, "htf_strength": htf_strength,
                             "v518_policy_bridge": _v518_policy_bridge_ctx})
                V410Telemetry.reject(trace_id, symbol, "htf", f"family_regime_disallowed.{_policy_reason}", "family_policy", _ctx)
                try: _v455_record_prequal_reason(symbol, f"family_regime_disallowed.{_policy_reason}", stage="family_policy", context=_ctx)
                except Exception: pass
                record_stage_reject("stage_g_to_e_rejected_by_regime")
                return None
            # --- strategy-aware HTF/tier policy -----------------------------
            # v4.3 strategies have explicit policy metadata. They must NOT
            # inherit legacy HTF/tier restrictions merely because a legacy
            # family name is used downstream. Hard safety remains unchanged.
            _v43_meta = CanonicalStrategyPolicyRegistry.get(str(_v425_mode).upper())
            if _v43_meta is not None:
                _sev_up = str(macro_severity or "").upper()
                if regime == "BEARISH" and _sev_up in {"BEARISH_NORMAL", "BEARISH_STRESSED", "NORMAL", "STRESSED"}:
                    _htf_floor = None
                else:
                    _htf_floor = float(_v43_meta.get("min_htf_strength_non_bearish", 55.0))
                    _htf_floor = _v457_htf_relief_floor(_v410_family, _htf_floor, regime, local_regime)
                _htf_floor = _v702_effective_htf_floor(_v410_family, _v425_mode, regime, local_regime, _htf_floor,
                                                      getattr(preferred_candidate, "features_snapshot", {}) or {})
                _v45_l3 = _v45_rescue_level() >= 3 and _v45_strategy_rescue_allowed(_v425_mode, _v410_family)
                _v518_ok, _v518_strength, _v518_ctx = _v518_neutral_local_htf_bridge(df_1h,df_4h,df_15m,df_5m,regime,local_regime,htf_strength,_v425_mode or _v410_family)
                if _v518_ok: htf_strength=max(float(htf_strength),float(_v518_strength)); STATS["v518_candidate_htf_bridge_pass"]=STATS.get("v518_candidate_htf_bridge_pass",0)+1
                if _htf_floor is not None and htf_strength < _htf_floor and not (_v45_l3 or _v518_ok or _v689_reuse_prequal):
                    V410Telemetry.reject(trace_id, symbol, "htf", "family_htf_strength_below_floor", "v43_strategy_policy",
                                         {"strategy_mode":_v425_mode,"strength":htf_strength,"floor":_htf_floor})
                    record_stage_reject("stage_g_to_e_rejected_by_htf")
                    return None
                _min_rank = _FAMILY_RANK.get(str(_v43_meta.get("min_tier","MID")), 2)
                _a7_micro_tier_pass = _v702_a7_micro_handoff_allowed(preferred_candidate, market_data, tier)
                if str(tier).upper() == "MICRO" and not _a7_micro_tier_pass:
                    _mh_diag = STATS.get("v702_a19_micro_handoff_last", {}) or {}
                    V410Telemetry.reject(trace_id, symbol, "liquidity", "micro_handoff_unverified", "v702_a7_micro_handoff", {
                        "strategy_mode":_v425_mode, "tier":tier,
                        "evidence_reason":str(_mh_diag.get("reason") or STATS.get("v702_a7_micro_handoff_last_block_reason", "unknown"))[:100],
                        "candidate_ref":str(_mh_diag.get("candidate_ref") or "")[:40],
                        "snapshot_id":str(_mh_diag.get("snapshot_id") or "")[:80],
                    })
                    record_stage_reject("stage_g_to_e_rejected_by_liquidity")
                    return None
                if _FAMILY_RANK.get(str(tier), -1) < _min_rank and not _v45_l3 and not _v689_reuse_prequal and not _a7_micro_tier_pass:
                    V410Telemetry.reject(trace_id, symbol, "liquidity", "family_tier_below_floor", "v43_strategy_policy",
                                         {"strategy_mode":_v425_mode,"tier":tier,"min_tier":_v43_meta.get("min_tier")})
                    record_stage_reject("stage_g_to_e_rejected_by_liquidity")
                    return None
                if _a7_micro_tier_pass:
                    STATS["v702_a7_micro_builder_handoff_passes"] = int(STATS.get("v702_a7_micro_builder_handoff_passes", 0) or 0) + 1
                    LifecycleTrace.record(trace_id, "V702_A7_MICRO_TIER_HANDOFF", {"symbol":symbol,"tier":tier,"reason":"book_spread_fee_score_verified"})
                if _v45_l3:
                    STATS["v45_l3_policy_rescues"] = STATS.get("v45_l3_policy_rescues",0) + 1
            else:
                _htf_floor = V425FamilyPolicyAdj.effective_htf_floor(_v410_family, regime, _v425_mode)
                _htf_floor = _v702_effective_htf_floor(_v410_family, _v425_mode, regime, local_regime, _htf_floor,
                                                      getattr(preferred_candidate, "features_snapshot", {}) or {})
                _v45_l3 = _v45_rescue_level() >= 3 and _v45_strategy_rescue_allowed(_v425_mode, _v410_family)
                _v518_ok, _v518_strength, _v518_ctx = _v518_neutral_local_htf_bridge(df_1h,df_4h,df_15m,df_5m,regime,local_regime,htf_strength,_v425_mode or _v410_family)
                if _v518_ok: htf_strength=max(float(htf_strength),float(_v518_strength)); STATS["v518_candidate_htf_bridge_pass"]=STATS.get("v518_candidate_htf_bridge_pass",0)+1
                if _htf_floor is not None and htf_strength < _htf_floor and not (_v45_l3 or _v518_ok):
                    V410Telemetry.reject(trace_id, symbol, "htf", "family_htf_strength_below_floor", "family_policy", {"family":_v410_family,"strength":htf_strength,"floor":_htf_floor})
                    record_stage_reject("stage_g_to_e_rejected_by_htf")
                    return None
                _a7_micro_tier_pass = _v702_a7_micro_handoff_allowed(preferred_candidate, market_data, tier)
                if str(tier).upper() == "MICRO" and not _a7_micro_tier_pass:
                    _mh_diag = STATS.get("v702_a19_micro_handoff_last", {}) or {}
                    V410Telemetry.reject(trace_id, symbol, "liquidity", "micro_handoff_unverified", "v702_a7_micro_handoff", {
                        "family":_v410_family, "tier":tier,
                        "evidence_reason":str(_mh_diag.get("reason") or STATS.get("v702_a7_micro_handoff_last_block_reason", "unknown"))[:100],
                        "candidate_ref":str(_mh_diag.get("candidate_ref") or "")[:40],
                        "snapshot_id":str(_mh_diag.get("snapshot_id") or "")[:80],
                    })
                    record_stage_reject("stage_g_to_e_rejected_by_liquidity")
                    return None
                if not V425FamilyPolicyAdj.liquidity_acceptable(_v410_family, tier, regime) and not _v45_l3 and not _a7_micro_tier_pass:
                    V410Telemetry.reject(trace_id, symbol, "liquidity", "family_tier_below_floor", "family_policy", {"family":_v410_family,"tier":tier})
                    record_stage_reject("stage_g_to_e_rejected_by_liquidity")
                    return None
                if _a7_micro_tier_pass:
                    STATS["v702_a7_micro_builder_handoff_passes"] = int(STATS.get("v702_a7_micro_builder_handoff_passes", 0) or 0) + 1
                    LifecycleTrace.record(trace_id, "V702_A7_MICRO_TIER_HANDOFF", {"symbol":symbol,"tier":tier,"reason":"book_spread_fee_score_verified"})
                if _v45_l3:
                    STATS["v45_l3_policy_rescues"] = STATS.get("v45_l3_policy_rescues",0) + 1
            # --- BEARISH structural compensation for sweep / mean-reversion --
            # Lowered bearish volume floor / MID tier are ONLY permitted with
            # extra structural evidence. Fail-closed: missing features => reject.
            if regime == "BEARISH":
                _v425_feats = V425LocalRegime._features(df_15m, df_5m)
                if _v410_family == "LIQUIDITY_SWEEP_REVERSAL":
                    if not V425FamilyPolicyAdj.sweep_bearish_structural_ok(_v425_feats):
                        V410Telemetry.reject(trace_id, symbol, "structural", "sweep_bearish_confirmation_missing", "family_policy", {"family":_v410_family})
                        record_stage_reject("stage_g_to_e_rejected_by_microstruct")
                        return None
                elif _v410_family == "MEAN_REVERSION":
                    _tier_rank = _FAMILY_RANK.get(str(tier), -1)
                    _large_rank = _FAMILY_RANK.get("LARGE", 3)
                    if _tier_rank < _large_rank:  # below LARGE => need strong confirmation
                        if not V425FamilyPolicyAdj.mr_bearish_structural_ok(_v425_feats):
                            V410Telemetry.reject(trace_id, symbol, "structural", "mr_bearish_confirmation_missing", "family_policy", {"family":_v410_family})
                            record_stage_reject("stage_g_to_e_rejected_by_microstruct")
                            return None

        # v4.3 strategy-aware downstream hard gate. Ranking never substitutes for policy.
        if _v425_mode in {
            "LOCAL_STRENGTH_BREAKOUT", "COMPRESSION_EXPANSION",
            "SWING_PULLBACK", "EXTREME_FLUSH_REVERSAL"
        }:
            try:
                _phase_name = opp.get("market_phase", "")
                if isinstance(_phase_name, dict):
                    _phase_name = _phase_name.get("phase", "")
                if not FamilyPolicyLayer.strategy_allowed(
                    _v425_mode, regime, local_regime, str(_phase_name or ""),
                    str(macro_severity), str(opp.get("strategy_style", "SCALP"))
                ):
                    record_rejection(trace_id, symbol, "htf", "v43_strategy_policy_disallowed",
                                     "family_policy", ctx={"strategy_mode": _v425_mode,
                                                           "regime": regime, "local_regime": local_regime,
                                                           "phase": _phase_name, "severity": macro_severity})
                    record_stage_reject("stage_g_to_e_rejected_by_regime")
                    return None
            except Exception as _v43_policy_e:
                record_rejection(trace_id, symbol, "htf", "v43_strategy_policy_error",
                                 "family_policy", ctx={"strategy_mode": _v425_mode})
                record_stage_reject("stage_g_to_e_rejected_by_regime")
                return None

        # v4.5.16 POLICY-CLOSURE: the canonical FamilyPolicyLayer is the only
        # policy authority. No hard-coded family whitelist/shadow policy is
        # consulted here. Any policy exception must flow through the canonical
        # strategy/family policy checks above; contradictory policy state is
        # fail-closed via the policy audit at boot.

        # ---- Layer 4: Micro-structure confirmation (bounded) ----
        bos_confirmed, bos_strength = MicroStructure.micro_bos_confirm(df_5m)
        _fb_family = str(opp.get("family", "PULLBACK") or "PULLBACK")
        _fb_zone = opp.get("zone_ref")
        try:
            _fb_atr = float(Indicators.atr(df_5m, CONFIG["ATR_PERIOD"]).iloc[-2])
        except Exception:
            _fb_atr = 0.0
        fake_ok, fake_ctx = _v520_fake_break_gate(
            df_5m, family=_fb_family, zone_ref=_fb_zone, atr_value=_fb_atr
        )
        if not fake_ok:
            _recovered_struct = False
            # V654: use the concrete current opportunity when MSE has no winner.
            # The existing V565/V642 recovery authorities stay final; this only
            # repairs candidate continuity at the structural-recovery input.
            _v654_structural_view = preferred_candidate
            if _v654_structural_view is None:
                _v654_structural_view = opp
            try:
                if _v565_structural_recovery_candidate(
                    _v654_structural_view,
                    close_price=float(df_5m["close"].iloc[-2]),
                    ema50=float(df_5m["close"].ewm(span=50,adjust=False).mean().iloc[-2]),
                    chase_atr=fake_ctx.get("chase_atr") if isinstance(fake_ctx, dict) else None,
                ):
                    _recovered_struct = True
                    STATS["v565_structural_recoveries"] = int(
                        STATS.get("v565_structural_recoveries", 0) or 0
                    ) + 1
                    fake_ctx = {**dict(fake_ctx or {}), "structural_recovery_lane": True}
            except Exception:
                _recovered_struct = False
            if not _recovered_struct:
                # V631: permit one narrowly-scoped structural interpretation for
                # the V630 verified reclaim lane. This does NOT disable the
                # fake-break detector globally: it requires independent closed-bar
                # reclaim + higher-low + trend/HTF/volume evidence and remains
                # subject to every downstream microstructure/risk/execution gate.
                try:
                    _v631_verified = _v631_verified_reclaim_structural_recovery(
                        _v654_structural_view, df_5m, fake_ctx
                    )
                except Exception:
                    _v631_verified = False
                if _v631_verified:
                    _recovered_struct = True
                    STATS["v631_verified_reclaim_structural_recoveries"] = int(
                        STATS.get("v631_verified_reclaim_structural_recoveries", 0) or 0
                    ) + 1
                    fake_ctx = {**dict(fake_ctx or {}), "v631_verified_reclaim": True}
                if not _recovered_struct:
                    # V642: final PULLBACK adaptive structural recall lane. This
                    # is NOT a generic fake-break bypass. It requires a fresh
                    # PULLBACK candidate, strong candidate quality, non-hostile
                    # HTF/location context, and a closed-bar evidence quorum with
                    # at least one genuine price-structure confirmation. The
                    # candidate still returns through the exact same downstream
                    # score/liquidity/fee/risk/PreSend/execution authorities.
                    try:
                        _v642_target_candidate = preferred_candidate
                        if _v642_target_candidate is None and _v654_structural_view is not None and not isinstance(_v654_structural_view, dict):
                            _v642_target_candidate = _v654_structural_view
                        # V654: when MSE has no winner, the builder may still
                        # have a valid legacy/router opportunity in `opp`.
                        # Recovery used to receive None in that case, making
                        # every V642/V644/V646 structural lane fail closed
                        # before it could inspect the actual closed-bar setup.
                        # Build a read-only StrategyCandidate adapter from the
                        # current opportunity so the existing recovery authority
                        # can evaluate it normally. No order path is added.
                        if _v642_target_candidate is None:
                            try:
                                _v654_make = globals().get("_v654_recovery_candidate_from_opp")
                                if callable(_v654_make):
                                    _v642_target_candidate = _v654_make(
                                        symbol, opp, df_5m,
                                        regime=regime, local_regime=local_regime,
                                        macro_severity=macro_severity,
                                        htf_strength=htf_strength, tier=tier,
                                    )
                            except Exception:

                                _v642_target_candidate = None
                        _v642_ok, _v642_ctx = _v642_adaptive_structural_recovery(
                            _v642_target_candidate, df_5m, fake_ctx
                        )
                    except Exception:
                        _v642_ok, _v642_ctx = False, {}
                    if _v642_ok:
                        _recovered_struct = True
                        STATS["v642_adaptive_structural_recoveries"] = int(
                            STATS.get("v642_adaptive_structural_recoveries", 0) or 0
                        ) + 1
                        fake_ctx = {
                            **dict(fake_ctx or {}),
                            **dict(_v642_ctx or {}),
                            "v642_adaptive_structural_reclaim": True,
                        }
                if not _recovered_struct:
                    # V646 RECALL: allow only an independently verified SR/sweep
                    # recovery for LSR. This is not a fake-break bypass: the
                    # candidate must already be strong and then continues through
                    # every downstream canonical gate unchanged.
                    _v646_sr_recovered = False
                    try:
                        _v646_sr_recovered = bool(_v646_sr_structural_recovery_allowed(
                            symbol, opp, market_data, df_15m, df_5m, preferred_candidate,
                            regime, tier
                        ))
                    except Exception:
                        _v646_sr_recovered = False
                    if not _v646_sr_recovered:
                        _v565_note_structural_reject(symbol)
                        record_rejection(trace_id, symbol, "structural", "fake_break_detected", "microstruct", ctx=fake_ctx)
                        record_stage_reject("stage_g_to_e_rejected_by_microstruct")
                        return None
                    try:
                        STATS["v646_sr_structural_recoveries"] = int(
                            STATS.get("v646_sr_structural_recoveries", 0) or 0
                        ) + 1
                        LifecycleTrace.record(trace_id, "V646_SR_STRUCTURAL_RECOVERY", {
                            "symbol": symbol,
                            "family": str(opp.get("family", "")),
                            "reason": "verified_sweep_reclaim",
                        })
                    except Exception:
                        _v647_record_suppressed_exception()
        if not bool(fake_ctx.get("raw_safe", True)):
            V410Telemetry.inc("fake_break_reclaim_exception")
            LifecycleTrace.record(trace_id, "FAKE_BREAK_SOFT_RECOVERY", fake_ctx)
        rej_confirmed = MicroStructure.rejection_candle_confirm(df_5m)
        _v410_bos = detect_micro_bos_at_index(df_5m, len(df_5m)-2) if CONFIG.get("V410_MICROSTRUCTURE_ENABLE", True) else None
        _v410_zone = find_retest_zone_at_index(df_5m, _v410_bos, len(df_5m)-2) if _v410_bos else None
        _v410_retest_confirmed = rejection_candle_confirm_v410(df_5m, len(df_5m)-2, _v410_zone)
        if _v410_bos is not None:
            bos_confirmed = True
            bos_strength = max(float(bos_strength or 0.0), float(_v410_bos.strength))
            rej_confirmed = bool(rej_confirmed or _v410_retest_confirmed)
            V410Telemetry.inc("micro_bos_detected")

        # ---- v4.2.1 UNBLOCK-PATCH — SYMBOL_SCAN cooldown CHECK only here ---
        # STARV-A (v4.0.8) relocated the ARM from top-of-pipeline to this
        # post-microstruct site. v4.2.1 goes one step further: we still CHECK
        # the cooldown here, but we DO NOT arm it. Arming is deferred until
        # AFTER family matching has succeeded AND the prelim composite score
        # reaches at least (dynamic floor - 5) — see the two
        # "UNBLOCK_ARM_SCAN_COOLDOWN" sites at the scorer gate below.
        # Rationale: ~40% of all rejects were reject.cooldown.symbol_scan
        # produced by symbols that were rejected at router/family stage —
        # i.e. they never consumed scoring work yet still blinded the bot to
        # that symbol for the full cooldown window. Early rejections (regime,
        # family matching, no_family_matched) now cost NO cooldown.
        # Fail-closed preserved: on ANY doubt/exception we simply do NOT arm
        # (re-evaluation next candle is strictly safer than a blind lockout).
        try:
            if _sym_cd_mode == "post_microstruct":
                _sym_cd_sec_pm = float(CONFIG.get("SYMBOL_COOLDOWN_SEC", 0) or 0)
                if _sym_cd_sec_pm > 0:
                    _last_scan_ts_pm = float(
                        COOLDOWNS.get("symbol_scan", {}).get(symbol, 0.0) or 0.0)
                    _now_pm = MONO_NOW()
                    if _last_scan_ts_pm > 0 and \
                       (_now_pm - _last_scan_ts_pm) < _sym_cd_sec_pm:
                        STATS["signals_scanned_cooldown_skipped"] = \
                            STATS.get("signals_scanned_cooldown_skipped", 0) + 1
                        record_rejection(trace_id, symbol, "cooldown",
                                         "symbol_scan", "cooldown",
                                         ctx={"age_sec": _now_pm - _last_scan_ts_pm,
                                              "cooldown_sec": _sym_cd_sec_pm,
                                              "mode": _sym_cd_mode,
                                              "stage": "post_microstruct_check"})
                        return None
                    # ARM REMOVED HERE — deferred to post-family/prelim-score
                    # sites (search: UNBLOCK_ARM_SCAN_COOLDOWN).
            # "candle_dedup" mode intentionally does nothing here — dedup
            # downstream (CandleDedup.seen_recently) is the sole throttle.
        except Exception as _cd_pm_e:
            logger.debug(f"[Cooldown] post-microstruct check suppressed {symbol}: {_cd_pm_e}")

        # ---- v4.0.6 FIX #4 — BOS/Reclaim HARD GATE for structural families ----
        # For structure-sensitive setups (breakout/pullback), the entry thesis
        # is that a break-of-structure or a reclaim has occurred. If neither
        # is confirmed, score alone must NOT be allowed to substitute for the
        # missing structural event. This gate runs BEFORE final scoring so we
        # never queue a structural setup lacking its defining confirmation.
        # Reclaim is evaluated here (same rule as the scorer path below) to
        # keep the hard-gate self-contained; the value is not cached to avoid
        # cross-section coupling.
        try:
            _family = str(opp.get("family", ""))
            # v4.0.7 TWEAK — PULLBACK removed from BOS hard gate default.
            # v4.0.8 STARV-C — TREND_CONTINUATION (soft router candidate)
            # inherits the SAME BOS/reclaim hard-gate as breakout families.
            # Adding it to the default set preserves structural rigor while
            # allowing the soft detector to catch trend-continuation setups.
            _hard_gate_families = set(CONFIG.get(
                "BOS_HARD_GATE_FAMILIES",
                ["BREAKOUT_RETEST", "BREAKOUT_CONTINUATION"],
            ))
            if _v425_mode in {
                "LOCAL_STRENGTH_BREAKOUT", "COMPRESSION_EXPANSION",
                "SWING_PULLBACK", "EXTREME_FLUSH_REVERSAL"
            }:
                _hard_gate_families.discard(_v410_family)
            # v4.0.7 TWEAK — use CLOSED bars for structural confirmation:
            # last closed = iloc[-2]; prior closed = iloc[-3]. Prevents
            # flicker driven by the still-forming candle at iloc[-1].
            _zone_ref_raw = opp.get("zone_ref")
            if str(_v425_mode or _v410_family or "").upper() == "LIQUIDITY_SWEEP_REVERSAL" and _zone_ref_raw is None:
                _zone_ref_raw = opp.get("swept_low") or opp.get("sr_support") or opp.get("strategy_native_recovery_zone")
            if str(_v425_mode or _v410_family or "").upper() == "LIQUIDITY_SWEEP_REVERSAL" and _zone_ref_raw is None:
                record_stage_reject("stage_g_to_e_rejected_by_microstruct")
                try: V410Telemetry.reject(trace_id, symbol, "structural", "lsr.zone_unverifiable", "CanonicalStructureAuthority", {"family":_v410_family})
                except Exception: pass
                return None
            _zone_ref_gate = float(_zone_ref_raw if _zone_ref_raw is not None else float(df_5m["close"].iloc[-2]))
            _last_close_gate = float(df_5m["close"].iloc[-2])
            _prev_close_gate = float(df_5m["close"].iloc[-3])
            _reclaim_gate = (_prev_close_gate < _zone_ref_gate
                             and _last_close_gate >= _zone_ref_gate)
            # v4.2.1 UNBLOCK-PATCH — TREND_CONTINUATION soft confirmation.
            # This family is a tail-catcher: it structurally lacks a clean
            # BOS event, so the strict hard gate rejected nearly all of them.
            # Replaced with: close > EMA20 > EMA50 AND (volume pulse OR
            # N-bar close persistence). Fail-closed: missing/NaN inputs or
            # any exception => NOT confirmed => reject (never falls open).
            if _family == "TREND_CONTINUATION" and bool(
                CONFIG.get("TREND_CONT_SOFT_CONFIRM_ENABLE", True)
            ):
                _tc_ok = False
                _tc_reason = "missing_inputs"
                try:
                    _tc_close = float(df_5m["close"].iloc[-2])
                    _tc_ema20 = float(df_5m["close"].ewm(span=20, adjust=False).mean().iloc[-2])
                    _tc_ema50 = float(df_5m["close"].ewm(span=50, adjust=False).mean().iloc[-2])
                    if not (math.isfinite(_tc_close) and math.isfinite(_tc_ema20)
                            and math.isfinite(_tc_ema50)):
                        raise ValueError("non_finite_ema")
                    _tc_stack_ok = (_tc_close > _tc_ema20 > _tc_ema50)
                    _tc_vol_ok = False
                    try:
                        _tc_v_last = float(df_5m["volume"].iloc[-2])
                        _tc_v_avg = float(df_5m["volume"].iloc[-22:-2].mean())
                        if _tc_v_avg > 0 and math.isfinite(_tc_v_avg):
                            _tc_vol_ok = (_tc_v_last / _tc_v_avg) >= float(
                                CONFIG.get("TREND_CONT_MIN_VOL_RATIO", 0.80))
                    except Exception:
                        _tc_vol_ok = False
                    _tc_pers_ok = False
                    try:
                        _tc_pers_n = int(CONFIG.get("TREND_CONT_MIN_PERSISTENCE_BARS", 2))
                        if len(df_5m) >= _tc_pers_n + 3:
                            _tc_closes = [float(df_5m["close"].iloc[-2 - i])
                                          for i in range(_tc_pers_n + 1)]
                            _tc_pers_ok = all(
                                _tc_closes[i] > _tc_closes[i + 1]
                                for i in range(_tc_pers_n))
                    except Exception:
                        _tc_pers_ok = False
                    _tc_ok = bool(_tc_stack_ok and (_tc_vol_ok or _tc_pers_ok))
                    _tc_reason = (f"stack={_tc_stack_ok},vol={_tc_vol_ok},"
                                  f"pers={_tc_pers_ok}")
                except Exception as _tc_e:
                    _tc_ok = False
                    _tc_reason = f"exc:{_tc_e}"
                if not _tc_ok:
                    record_rejection(
                        trace_id, symbol, "structural",
                        "trend_cont_soft_confirm_missing",
                        "microstruct",
                        ctx={"family": _family, "detail": _tc_reason},
                    )
                    record_stage_reject("stage_g_to_e_rejected_by_microstruct")
                    return None
            elif _family in _hard_gate_families:
                if not (bool(bos_confirmed) or bool(_reclaim_gate)):
                    record_rejection(
                        trace_id, symbol, "structural",
                        "bos_reclaim_missing_hard_gate",
                        "microstruct",
                        ctx={"family": _family,
                             "bos_confirmed": bool(bos_confirmed),
                             "reclaim_detected": bool(_reclaim_gate)},
                    )
                    record_stage_reject("stage_g_to_e_rejected_by_microstruct")
                    return None
            elif _family in ("PULLBACK", "MTF_PULLBACK"):
                # v4.0.7 TWEAK — light micro_uptrend_confirm replacement for
                # BOS on PULLBACK: accept ANY of (a) bos_confirmed,
                # (b) reclaim across zone_ref, or (c) last CLOSED bar is a
                # bullish body above prior close.
                # v4.0.8 STARV-D — also accept (d) higher-low pattern on the
                # last 3 CLOSED 5m bars (iloc[-2], iloc[-3], iloc[-4]).
                # Adds a fourth objective anchor without loosening downstream
                # gates. Structural score gate remains the final arbiter.
                _lc = df_5m.iloc[-2]
                _bullish_close = (float(_lc["close"]) > float(_lc["open"])
                                  and float(_lc["close"]) >= _prev_close_gate)
                _higher_low = False
                _ema20_slope_up = False
                _shallow_pullback = False
                if bool(CONFIG.get("V565_PULLBACK_AWARE_FAKE_BREAK_ENABLE", True)):
                    try:
                        _hi = float(df_5m["high"].iloc[-2])
                        _lo = float(df_5m["low"].iloc[-2])
                        _op = float(df_5m["open"].iloc[-2])
                        _cl = float(df_5m["close"].iloc[-2])
                        _rng = max(_hi - _lo, 0.0)
                        _body = abs(_cl - _op)
                        _lw = max(0.0, min(_cl, _op) - _lo)
                        _body_ratio = _body / _rng if _rng > 0 else 0.0
                        _lw_ratio = _lw / _rng if _rng > 0 else 0.0
                        _ema20_now = float(Indicators.ema(df_5m["close"], CONFIG["EMA_FAST"]).iloc[-2])
                        _ema50_now = float(Indicators.ema(df_5m["close"], CONFIG["EMA_MID"]).iloc[-2])
                        _atr_pb = float(Indicators.atr(df_5m, CONFIG["ATR_PERIOD"]).iloc[-2])
                        _shallow_pullback = bool(
                            _rng > 0 and math.isfinite(_atr_pb) and _atr_pb > 0
                            and _body_ratio <= float(CONFIG.get("V565_PULLBACK_SHALLOW_RETRACE_MAX_BODY_RATIO", 0.65))
                            and _lw_ratio <= float(CONFIG.get("V565_PULLBACK_SHALLOW_RETRACE_MAX_WICK_RATIO", 0.40))
                            and _cl >= _ema50_now
                            and _cl >= _ema20_now - 0.35 * _atr_pb
                        )
                    except Exception:
                        _shallow_pullback = False
                if bool(CONFIG.get("PULLBACK_ACCEPT_EMA20_SLOPE", True)):
                    try:
                        _bars=max(2,int(CONFIG.get("PULLBACK_EMA20_SLOPE_BARS",5)))
                        _ema_s=Indicators.ema(df_5m["close"],CONFIG["EMA_FAST"])
                        if len(df_5m)>=_bars+3:
                            _ema20_slope_up=float(_ema_s.iloc[-2])>float(_ema_s.iloc[-2-_bars])
                    except Exception:
                        _ema20_slope_up=False
                if bool(CONFIG.get("PULLBACK_ACCEPT_HIGHER_LOW", True)):
                    try:
                        if len(df_5m) >= 5:
                            _low_m1 = float(df_5m["low"].iloc[-2])
                            _low_m2 = float(df_5m["low"].iloc[-3])
                            _low_m3 = float(df_5m["low"].iloc[-4])
                            # Two consecutive higher lows on closed bars
                            _higher_low = (_low_m1 > _low_m2 > _low_m3)
                    except Exception:
                        _higher_low = False
                if not (bool(bos_confirmed) or bool(_reclaim_gate)
                        or bool(_bullish_close) or bool(_higher_low)
                        or bool(_ema20_slope_up) or bool(_shallow_pullback)):
                    STATS["v545_builder_blocker"] = int(STATS.get("v545_builder_blocker",0) or 0) + 1
                    STATS["v545_last_builder_blocker"] = "pullback_micro_uptrend_missing"
                    _br = STATS.get("v545_builder_blocker_reasons") or {}
                    _br["pullback_micro_uptrend_missing"] = int(_br.get("pullback_micro_uptrend_missing",0) or 0) + 1
                    STATS["v545_builder_blocker_reasons"] = _br
                    record_rejection(
                        trace_id, symbol, "structural",
                        "pullback_micro_uptrend_missing",
                        "microstruct",
                        ctx={"family": _family,
                             "bos_confirmed": bool(bos_confirmed),
                             "reclaim_detected": bool(_reclaim_gate),
                             "bullish_close": bool(_bullish_close),
                             "higher_low": bool(_higher_low),
                             "ema20_slope_up": bool(_ema20_slope_up),
                             "shallow_pullback": bool(_shallow_pullback)},
                    )
                    record_stage_reject("stage_g_to_e_rejected_by_microstruct")
                    return None
        except Exception as _e:
            logger.debug(f"[BOSHardGate] {symbol}: {_e}")

        # ---- Zone quality (bounded booster) ----
        # v4.0.7 TWEAK — use CLOSED bar (iloc[-2]) as zone_ref fallback and
        # as the reference price for zone-quality classification, to keep the
        # decision aligned with closed-bar structure. Entry price itself stays
        # LIVE (iloc[-1]) further below.
        try:
            _zone_ref_raw = opp.get("zone_ref")
            if str(_v425_mode or _v410_family or "").upper() == "LIQUIDITY_SWEEP_REVERSAL" and _zone_ref_raw is None:
                _zone_ref_raw = opp.get("swept_low") or opp.get("sr_support") or opp.get("strategy_native_recovery_zone")
            if str(_v425_mode or _v410_family or "").upper() == "LIQUIDITY_SWEEP_REVERSAL" and _zone_ref_raw is None:
                record_stage_reject("stage_g_to_e_rejected_by_microstruct")
                return None
            zone_ref = float(_zone_ref_raw if _zone_ref_raw is not None else float(df_5m["close"].iloc[-2]))
            atr_series = Indicators.atr(df_5m, CONFIG["ATR_PERIOD"])
            atr_val = float(atr_series.iloc[-2]) if atr_series is not None else 0.0
            if atr_val <= 0 or math.isnan(atr_val):
                record_rejection(trace_id, symbol, "structural", "atr_invalid",
                                 "microstruct", ctx={"atr": atr_val})
                record_stage_reject("stage_g_to_e_rejected_by_microstruct")
                return None
            price_closed = float(df_5m["close"].iloc[-2])
            dist_atr = abs(price_closed - zone_ref) / max(atr_val, 1e-9)
            zone_class = MicroStructure.zone_quality_class(dist_atr, freshness_bars=3)
        except Exception as e:
            record_rejection(trace_id, symbol, "structural", f"zone_atr_error:{e}",
                             "microstruct")
            record_stage_reject("stage_g_to_e_rejected_by_microstruct")
            return None

        # ---- REAL score inputs (computed from market data — NO placeholders) ----

        # Volume ratio: last CLOSED bar volume vs 20-bar mean (excluding forming bar)
        # v4.0.3 PATCH N — tag missing-input diagnostics (no silent None swallowing)
        # v4.0.7 TWEAK — exclude the still-forming bar from ratio numerator.
        volume_ratio: Optional[float] = None
        try:
            vol = df_5m["volume"].iloc[-21:-1]  # closed 20-bar window
            vol_mean = float(vol.mean())
            if vol_mean > 0:
                volume_ratio = float(df_5m["volume"].iloc[-2]) / vol_mean
            else:
                STATS["score_input_missing_volume_ratio"] = \
                    STATS.get("score_input_missing_volume_ratio", 0) + 1
        except Exception as _e:
            STATS["score_input_missing_volume_ratio"] = \
                STATS.get("score_input_missing_volume_ratio", 0) + 1
            logger.debug(f"[ScoreInput] volume_ratio {symbol}: {_e}")

        # Volume delta score: last bar volume vs prev bar (0..10 scale)
        vol_delta_score: Optional[float] = None
        try:
            v_last = float(df_5m["volume"].iloc[-2])
            v_prev = float(df_5m["volume"].iloc[-3])
            if v_prev > 0:
                vd_ratio = v_last / v_prev
                vol_delta_score = _clamp((vd_ratio - 1.0) * 5.0, 0.0, 3.0)
        except Exception as _e:
            logger.debug(f"[ScoreInput] vol_delta {symbol}: {_e}")

        # Structure confidence: derived from BOS confirmation + candle body quality
        # v4.0.7 TWEAK — reclaim now evaluated on CLOSED bars only
        # (last closed = iloc[-2], prior closed = iloc[-3]).
        structure_confidence: Optional[float] = None
        reclaim_detected: bool = False
        try:
            sc = 0.0
            if bos_confirmed:
                # v4.0.6 FIX #5 — BOS strength→score scaling promoted to CONFIG
                # (was hard-coded 5000.0). Default preserves prior behavior.
                _bos_mult = float(CONFIG.get("BOS_STRENGTH_SCORE_MULT", 5000.0))
                sc += 45.0 + min(25.0, float(bos_strength) * _bos_mult)
            # Reclaim: last CLOSED bar closed back above zone_ref after pullback
            last_close = float(df_5m["close"].iloc[-2])
            prev_close = float(df_5m["close"].iloc[-3])
            reclaim_detected = (prev_close < zone_ref and last_close >= zone_ref)
            if reclaim_detected:
                sc += 20.0
            # Body strength of confirmation candle
            try:
                lc = df_5m.iloc[-2]
                body = abs(float(lc["close"]) - float(lc["open"]))
                rng = max(1e-9, float(lc["high"]) - float(lc["low"]))
                body_ratio = body / rng
                sc += min(10.0, body_ratio * 10.0)
            except Exception:
                _v647_record_suppressed_exception()
            structure_confidence = _clamp(sc, 0.0, 100.0)
        except Exception as _e:
            STATS["score_input_missing_structure"] = \
                STATS.get("score_input_missing_structure", 0) + 1
            logger.debug(f"[ScoreInput] structure {symbol}: {_e}")

        # Retest quality score: distance from zone + zone quality class
        retest_quality_score: Optional[float] = None
        try:
            rq = 0.0
            # Closer to zone => higher quality
            if dist_atr <= 0.3:
                rq += 60.0
            elif dist_atr <= 0.6:
                rq += 40.0
            elif dist_atr <= 1.0:
                rq += 20.0
            else:
                rq += 5.0
            # Zone quality class bonus
            if zone_class == "STRONG_FRESH":
                rq += 30.0
            elif zone_class == "ACCEPTABLE":
                rq += 15.0
            elif zone_class == "WEAK_STALE":
                rq -= 10.0
            # Current closed-bar recovery evidence. These are not substitutes
            # for the separate confirmation gate; they make the retest metric
            # measure the actual recovery rather than only zone geometry.
            try:
                if reclaim_detected:
                    rq += 10.0
            except Exception:
                pass
            try:
                if bool(_higher_low):
                    rq += 10.0
            except Exception:
                pass
            try:
                if bool(_bullish_close):
                    rq += 5.0
            except Exception:
                pass
            try:
                if bool(_ema20_slope_up):
                    rq += 5.0
            except Exception:
                pass
            # Rejection candle confirmation remains an additional confirmation.
            if rej_confirmed:
                rq += 10.0
            retest_quality_score = _clamp(rq, 0.0, 100.0)
        except Exception as _e:
            STATS["score_input_missing_retest"] = \
                STATS.get("score_input_missing_retest", 0) + 1
            logger.debug(f"[ScoreInput] retest_quality {symbol}: {_e}")

        # Orderbook imbalance: prefer the exact route snapshot captured immediately
        # before the canonical Builder. The live fetch remains the fallback for
        # non-route callers / legacy paths, preserving existing functionality.
        # R35 closes the selected->builder orderbook drift that could change the
        # final score after selection.
        orderbook_imbalance: Optional[float] = None
        cached_ob: Optional[Dict[str, Any]] = None
        try:
            _route_ob = market_data.get("_v703_route_score_orderbook") if isinstance(market_data, dict) else None
            _route_ob_sym = str((market_data or {}).get("_v703_route_score_orderbook_symbol", "")) if isinstance(market_data, dict) else ""
            if isinstance(_route_ob, dict) and _route_ob_sym == str(symbol):
                cached_ob = dict(_route_ob)
                STATS["v703_builder_orderbook_handoff_reused"] = int(STATS.get("v703_builder_orderbook_handoff_reused", 0) or 0) + 1
                STATS["v703_last_builder_orderbook_source"] = "ROUTE_HANDOFF"
            else:
                cached_ob = await safe_api_call(f"fetch_ob_score_{symbol}",
                                                 exchange.fetch_order_book(symbol, limit=20))
                STATS["v703_builder_orderbook_handoff_missed"] = int(STATS.get("v703_builder_orderbook_handoff_missed", 0) or 0) + 1
                STATS["v703_last_builder_orderbook_source"] = "BUILDER_FETCH"
            bids = (cached_ob or {}).get("bids", [])[:10]
            asks = (cached_ob or {}).get("asks", [])[:10]
            bid_depth = sum(float(qty) for _, qty in bids)
            ask_depth = sum(float(qty) for _, qty in asks)
            if bid_depth + ask_depth > 0:
                orderbook_imbalance = bid_depth / (bid_depth + ask_depth)
            else:
                STATS["score_input_missing_ob"] = \
                    STATS.get("score_input_missing_ob", 0) + 1
        except Exception as _e:
            STATS["score_input_missing_ob"] = \
                STATS.get("score_input_missing_ob", 0) + 1
            logger.debug(f"[ScoreInput] orderbook {symbol}: {_e}")

        # Momentum score: RSI + ADX + ATR expansion combined (0..10 scale)
        # v4.0.7 TWEAK — RSI/ADX read from last CLOSED bar (iloc[-2]) so the
        # decision does not flicker with the forming candle.
        momentum_score_val: Optional[float] = None
        try:
            rsi_series = Indicators.rsi(df_5m["close"], CONFIG["RSI_PERIOD"])
            last_rsi = float(rsi_series.iloc[-2]) if rsi_series is not None else 50.0
            # RSI in bullish recovery zone (40-65) = positive
            ms = 0.0
            if 40.0 <= last_rsi <= 65.0:
                ms += 4.0
            elif last_rsi > 65.0:
                ms += 2.0  # overbought — less ideal
            elif last_rsi < 30.0:
                ms += 3.0  # oversold bounce potential
            # ADX
            adx_series = Indicators.adx(df_5m, CONFIG["ADX_PERIOD"])
            if adx_series is not None:
                last_adx = float(adx_series.iloc[-2])
                if last_adx >= float(CONFIG["ADX_BASE_THRESHOLD"]):
                    ms += 3.0
                elif last_adx >= float(CONFIG["ADX_SOFT_PENALTY"]):
                    ms += 1.5
            # ATR expansion (from momentum detector)
            if opp.get("family") == "MOMENTUM_EXPANSION":
                ms += 3.0
            momentum_score_val = _clamp(ms, 0.0, 10.0)
        except Exception as _e:
            STATS["score_input_missing_momentum"] = \
                STATS.get("score_input_missing_momentum", 0) + 1
            logger.debug(f"[ScoreInput] momentum {symbol}: {_e}")

        # RS vs BTC: relative strength of symbol vs BTC (0..8 scale)
        # v4.0.7 TWEAK — compare on CLOSED bars (iloc[-2] vs iloc[-21]) to
        # avoid mid-candle flicker in relative-strength scoring.
        rs_score_val: Optional[float] = None
        try:
            if df_btc_15m is not None and len(df_btc_15m) >= 21:
                sym_ret = (float(df_5m["close"].iloc[-2]) - float(df_5m["close"].iloc[-21])) \
                          / float(df_5m["close"].iloc[-21])
                btc_ret = (float(df_btc_15m["close"].iloc[-2]) - float(df_btc_15m["close"].iloc[-21])) \
                          / float(df_btc_15m["close"].iloc[-21])
                rs_val = sym_ret - btc_ret
                if rs_val > 0.02:
                    rs_score_val = 8.0
                elif rs_val > 0.01:
                    rs_score_val = 6.0
                elif rs_val > 0.0:
                    rs_score_val = 4.0
                elif rs_val > -0.01:
                    rs_score_val = 2.0
                else:
                    rs_score_val = 0.0
            elif not bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) or \
                 bool(CONFIG.get("PAPER_TRADING_MODE", False)):
                # Paper mode: neutral RS when BTC data unavailable
                rs_score_val = 4.0
        except Exception as _e:
            STATS["score_input_missing_rs"] = \
                STATS.get("score_input_missing_rs", 0) + 1
            logger.debug(f"[ScoreInput] rs_btc {symbol}: {_e}")

        # Spread: from cached orderbook first (v4.0.3 PATCH P) to avoid an
        # extra fetch_ticker call; fall back to fetch_ticker only if the OB is
        # unavailable / malformed.
        spread_pct: Optional[float] = None
        try:
            if cached_ob is not None:
                _bids = cached_ob.get("bids") or []
                _asks = cached_ob.get("asks") or []
                if _bids and _asks:
                    top_bid = float(_bids[0][0])
                    top_ask = float(_asks[0][0])
                    mid = (top_bid + top_ask) / 2.0
                    if mid > 0 and top_bid > 0 and top_ask > 0:
                        spread_pct = (top_ask - top_bid) / mid * 100.0
            if spread_pct is None:
                ticker = await safe_api_call(f"ticker_spread_{symbol}",
                                             exchange.fetch_ticker(symbol))
                bid = float(ticker.get("bid") or 0)
                ask = float(ticker.get("ask") or 0)
                mid = (bid + ask) / 2.0
                if mid > 0 and bid > 0 and ask > 0:
                    spread_pct = (ask - bid) / mid * 100.0
        except Exception as _e:
            STATS["score_input_missing_spread"] = \
                STATS.get("score_input_missing_spread", 0) + 1
            logger.debug(f"[ScoreInput] spread {symbol}: {_e}")

        # Tier-aware spread hard ceiling is an execution-quality gate, not a
        # score preference. BELOW remains hard rejected. This prevents a
        # permissive global spread ceiling from leaking into MICRO/MID.
        if CONFIG.get("V410_MASTER_ENABLE", True):
            _spread_ok, _spread_reason = tier_spread_hard_ok_v410(spread_pct, tier)
            # v4.5.39: transient-spread recheck. One fresh orderbook/ticker
            # observation may clear a single bad tick; if it still fails, the
            # normal hard gate remains authoritative. No score/tier relaxation.
            if (not _spread_ok and bool(CONFIG.get("V538_SPREAD_RECHECK_ENABLE", True)
                    and CONFIG.get("V410_MASTER_ENABLE", True))):
                try:
                    await asyncio.sleep(float(CONFIG.get("V538_SPREAD_RECHECK_DELAY_SEC", 0.25)))
                    _rechecked = None
                    if bool(CONFIG.get("V538_SPREAD_RECHECK_USE_ORDERBOOK", True)):
                        _ob2 = await asyncio.wait_for(exchange.fetch_order_book(symbol, limit=5),
                                                      timeout=float(CONFIG.get("V538_SPREAD_RECHECK_TIMEOUT_SEC", 3.0)))
                        _b2 = _ob2.get("bids") or []; _a2 = _ob2.get("asks") or []
                        if _b2 and _a2:
                            _bp = float(_b2[0][0]); _ap = float(_a2[0][0]); _mid2 = (_bp + _ap) / 2.0
                            if _mid2 > 0 and _bp > 0 and _ap > 0:
                                _rechecked = (_ap - _bp) / _mid2 * 100.0
                    if _rechecked is None:
                        _tk2 = await asyncio.wait_for(exchange.fetch_ticker(symbol),
                                                      timeout=float(CONFIG.get("V538_SPREAD_RECHECK_TIMEOUT_SEC", 3.0)))
                        _bp = float(_tk2.get("bid") or 0); _ap = float(_tk2.get("ask") or 0); _mid2 = (_bp + _ap) / 2.0
                        if _mid2 > 0 and _bp > 0 and _ap > 0:
                            _rechecked = (_ap - _bp) / _mid2 * 100.0
                    if _rechecked is not None and math.isfinite(float(_rechecked)):
                        spread_pct = float(_rechecked)
                        _spread_ok, _spread_reason = tier_spread_hard_ok_v410(spread_pct, tier)
                        STATS["v538_spread_rechecks"] = int(STATS.get("v538_spread_rechecks", 0) or 0) + 1
                        if _spread_ok:
                            STATS["v538_spread_recheck_passes"] = int(STATS.get("v538_spread_recheck_passes", 0) or 0) + 1
                        else:
                            STATS["v538_spread_recheck_rejects"] = int(STATS.get("v538_spread_recheck_rejects", 0) or 0) + 1

                    # V629: one additional read-only spread observation for a
                    # near-ceiling transient. The hard tier ceiling itself is
                    # NEVER raised; the second observation can only confirm a
                    # normal PASS under the same authoritative ceiling.
                    if (
                        not _spread_ok
                        and bool(CONFIG.get("V629_SPREAD_SECOND_RECHECK_ENABLE", False))
                        and spread_pct is not None
                        and math.isfinite(float(spread_pct))
                    ):
                        try:
                            _base_ceil = float((CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}).get(
                                str(tier).upper(), CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15)
                            ))
                            _gap = float(spread_pct) - _base_ceil
                            if 0.0 < _gap <= float(CONFIG.get("V629_SPREAD_SECOND_RECHECK_MAX_ABOVE_CEILING_PCT", 0.06)):
                                await asyncio.sleep(float(CONFIG.get("V629_SPREAD_SECOND_RECHECK_DELAY_SEC", 0.15)))
                                _rechecked3 = None
                                if bool(CONFIG.get("V538_SPREAD_RECHECK_USE_ORDERBOOK", True)):
                                    _ob3 = await asyncio.wait_for(exchange.fetch_order_book(symbol, limit=5), timeout=float(CONFIG.get("V629_SPREAD_SECOND_RECHECK_TIMEOUT_SEC", 2.0)))
                                    _b3 = _ob3.get("bids") or []; _a3 = _ob3.get("asks") or []
                                    if _b3 and _a3:
                                        _bp3 = float(_b3[0][0]); _ap3 = float(_a3[0][0]); _mid3 = (_bp3 + _ap3) / 2.0
                                        if _mid3 > 0 and _bp3 > 0 and _ap3 > 0:
                                            _rechecked3 = (_ap3 - _bp3) / _mid3 * 100.0
                                if _rechecked3 is None:
                                    _tk3 = await asyncio.wait_for(exchange.fetch_ticker(symbol), timeout=float(CONFIG.get("V629_SPREAD_SECOND_RECHECK_TIMEOUT_SEC", 2.0)))
                                    _bp3 = float(_tk3.get("bid") or 0); _ap3 = float(_tk3.get("ask") or 0); _mid3 = (_bp3 + _ap3) / 2.0
                                    if _mid3 > 0 and _bp3 > 0 and _ap3 > 0:
                                        _rechecked3 = (_ap3 - _bp3) / _mid3 * 100.0
                                STATS["v629_spread_second_rechecks"] = int(STATS.get("v629_spread_second_rechecks", 0) or 0) + 1
                                if _rechecked3 is not None and math.isfinite(float(_rechecked3)):
                                    spread_pct = float(_rechecked3)
                                    _spread_ok, _spread_reason = tier_spread_hard_ok_v410(spread_pct, tier)
                                    if _spread_ok:
                                        STATS["v629_spread_second_recheck_passes"] = int(STATS.get("v629_spread_second_recheck_passes", 0) or 0) + 1
                                    else:
                                        STATS["v629_spread_second_recheck_rejects"] = int(STATS.get("v629_spread_second_recheck_rejects", 0) or 0) + 1
                            else:
                                STATS["v629_spread_second_recheck_skips"] = int(STATS.get("v629_spread_second_recheck_skips", 0) or 0) + 1
                        except Exception as _v629_spread_exc:
                            STATS["v629_spread_second_recheck_errors"] = int(STATS.get("v629_spread_second_recheck_errors", 0) or 0) + 1
                            try:
                                _v593_note_suppressed_exception("v629.spread_second_recheck", _v629_spread_exc)
                            except Exception:
                                _v647_record_suppressed_exception()
                except Exception as _recheck_exc:
                    STATS["v538_spread_recheck_errors"] = int(STATS.get("v538_spread_recheck_errors", 0) or 0) + 1
                    logger.debug(f"[V538-SPREAD] recheck suppressed {symbol}: {_recheck_exc}")
            if not _spread_ok:
                _v538_record_execution_blocker(symbol, "liquidity.tier_spread_ceiling", "g_to_e")
                record_rejection(trace_id, symbol, "liquidity", "tier_spread_ceiling", "liquidity",
                                 ctx={"tier": tier, "spread_pct": spread_pct, "detail": _spread_reason, "rechecked": True})
                record_stage_reject("stage_g_to_e_rejected_by_liquidity")
                return None

        # ---- Layer 5: Composite score (real data only, fail-closed on missing) ----
        score, sig_class, breakdown = CompositeScorer.build(
            htf_passed=htf_pass, htf_strength=htf_strength, htf_state=htf_state,
            structure_confidence=structure_confidence,
            reclaim_detected=reclaim_detected, bos_detected=bos_confirmed,
            retest_quality_score=retest_quality_score,
            volume_ratio=volume_ratio, vol_delta_score=vol_delta_score,
            orderbook_imbalance=orderbook_imbalance,
            momentum_score_val=momentum_score_val,
            rs_score_val=rs_score_val, spread_pct=spread_pct,
            liquidity_tier=tier,
            sweep_detected=(opp["family"] == "LIQUIDITY_SWEEP_REVERSAL"),
            equal_lows_sweep=False,
            rejection_type=("hammer" if rej_confirmed else ""),
            zone_quality_class=zone_class,
            symbol=symbol,
            strategy_mode=str(opp.get("strategy_mode", "") or ""),
            measured_rr=(float(opp.get("measured_rr")) if opp.get("measured_rr") is not None else None),
        )

        # V4.1 additive confluence: helpers cannot produce a signal; capped boost
        # only applies after all existing real-data score inputs have passed.
        _v410_boost, _v410_confluence = confluence_boost_v410(df_5m, bool(bos_confirmed), float(df_5m["close"].iloc[-2])) if CONFIG.get("V410_MASTER_ENABLE", True) else (0.0, {})
        _d1_adj, _d1_label = d1_bias_score_v410(market_data.get("df_1d"))
        _breadth_adj, _breadth_label = breadth_adjustment_v410(market_data)
        score = _clamp(float(score) + _v410_boost + _d1_adj + _breadth_adj, 0.0, 100.0)
        breakdown["v410_confluence"] = _v410_boost
        # v4.2.6 — bounded MTF confluence bonus. Hard MTF conditions have
        # already been proven by the detector; this only rewards the confluence
        # inside the existing composite score and never substitutes for it.
        if str(opp.get("family", "")).upper() == "MTF_PULLBACK":
            try:
                _mtf_bonus = 0.0
                if str(opp.get("anchor", "")).upper().startswith("EMA20"): _mtf_bonus += 1.5
                elif str(opp.get("anchor", "")).upper().startswith("EMA50"): _mtf_bonus += 1.0
                elif str(opp.get("anchor", "")).upper().startswith("VWAP"): _mtf_bonus += 0.75
                _mrsi = float(opp.get("rsi_5m", 50.0))
                if 50.0 <= _mrsi <= 62.0: _mtf_bonus += 1.5
                elif float(CONFIG.get("MTF_PULLBACK_RSI_MIN", 45.0)) <= _mrsi <= float(CONFIG.get("MTF_PULLBACK_RSI_MAX", 68.0)): _mtf_bonus += 0.75
                _mvr = float(opp.get("volume_ratio", 0.8))
                if _mvr >= 1.20: _mtf_bonus += 1.5
                elif _mvr >= 1.00: _mtf_bonus += 0.75
                if bool(opp.get("higher_low_5m")): _mtf_bonus += 0.75
                _mtf_bonus = min(float(CONFIG.get("MTF_PULLBACK_CONFLUENCE_BOOST_MAX", 6.0)), max(0.0, _mtf_bonus))
                score = _clamp(score + _mtf_bonus, 0.0, 100.0)
                breakdown["mtf_pullback_confluence"] = _mtf_bonus
            except Exception:
                _v647_record_suppressed_exception()

        # v4.5.20 — fake-break soft warning becomes a bounded score penalty for
        # non-breakout families; it never bypasses downstream hard gates.
        try:
            if not fake_ctx.get("raw_safe", True):
                _fbp = max(0.0, float(CONFIG.get("FAKE_BREAK_SOFT_PENALTY", 4.0)))
                score = _clamp(score - _fbp, 0.0, 100.0)
                breakdown["fake_break_soft_penalty"] = _fbp
                breakdown["total"] = score
        except Exception:
            _v647_record_suppressed_exception()

        # v4.2.3 — preferred zone / volume floor are bounded SOFT penalties.
        # They are quality preferences, not structural safety conditions.
        _family_name = str(opp.get("family", "PULLBACK"))
        _family_soft_penalty = 0.0
        if bool(CONFIG.get("V423_FAMILY_ZONE_PENALTY_ENABLE", True)):
            try:
                _anchor = str(opp.get("anchor") or opp.get("zone_type") or "")
                if _anchor and not FamilyPolicyLayer.zone_preferred(_family_name, _anchor):
                    _zmax = max(0.0, float(CONFIG.get("FAMILY_ZONE_MISMATCH_PENALTY_MAX", 6.0)))
                    _family_soft_penalty += _zmax
                    breakdown["family_zone_penalty"] = -_zmax
            except Exception:
                _v647_record_suppressed_exception()
        if bool(CONFIG.get("V423_FAMILY_VOLUME_PENALTY_ENABLE", True)):
            try:
                _floor = FamilyPolicyLayer.volume_floor_ratio(_family_name)
                if _floor > 0 and volume_ratio is not None and math.isfinite(float(volume_ratio))                         and float(volume_ratio) < _floor:
                    _gap_ratio = max(0.0, min(1.0, (_floor - float(volume_ratio)) / _floor))
                    _vmax = max(0.0, float(CONFIG.get("FAMILY_VOLUME_FLOOR_PENALTY_MAX", 4.0)))
                    _vp = min(_vmax, _vmax * _gap_ratio)
                    _family_soft_penalty += _vp
                    breakdown["family_volume_penalty"] = -_vp
            except Exception:
                _v647_record_suppressed_exception()
        if _family_soft_penalty > 0:
            score = _clamp(score - _family_soft_penalty, 0.0, 100.0)
            breakdown["total_before_family_soft_penalty"] = float(breakdown.get("total", score + _family_soft_penalty))
            breakdown["family_soft_penalty"] = _family_soft_penalty
            breakdown["total"] = score
            sig_class = ("A_STRONG" if score >= float(CONFIG["SIGNAL_CLASS_A_MIN"])
                         else ("B_MEDIUM" if score >= float(CONFIG["SIGNAL_CLASS_B_MIN"]) else "C_REJECT"))
        breakdown["d1_bias"] = _d1_adj
        breakdown["d1_bias_state"] = _d1_label
        breakdown["breadth_adjustment"] = _breadth_adj
        breakdown["breadth_state"] = _breadth_label
        V410Telemetry.inc("d1_bias_bearish") if _d1_label == "bearish" else None
        V410Telemetry.inc("breadth_bearish") if _breadth_label == "bearish" else None
        if _d1_label == "bearish" and CONFIG.get("D1_BIAS_HARD_BLOCK", False):
            record_rejection(trace_id, symbol, "htf", "d1_bias_hard_block", "d1_bias",
                             ctx={"d1_state": _d1_label})
            record_stage_reject("stage_g_to_e_rejected_by_htf")
            return None

        # v4.5 — order-book confirmation is additive quality logic, not a
        # bypass. MICRO has stricter depth/spread/imbalance requirements.
        try:
            _v45_ob_ok, _v45_ob_reason = _v45_orderbook_confirmation(
                cached_ob, {
                    "spread_pct": spread_pct or 0.0,
                    "depth_ratio": float(depth_ratio or 0.0) if 'depth_ratio' in locals() else 0.0,
                    "volume_ratio": float(volume_ratio or 0.0),
                    "structure_confidence": float(structure_confidence or 0.0),
                    "structure_quality": float(breakdown.get("structure_quality", structure_confidence or 0.0)),
                    "chase_atr": float(opp.get("chase_atr", 0.0) or 0.0),
                }, tier)
            breakdown["v45_orderbook_confirmation"] = _v45_ob_reason
            if not _v45_ob_ok:
                if str(tier).upper() == "MICRO":
                    record_rejection(trace_id, symbol, "liquidity", "v45_micro_orderbook_confirmation", "v45_orderbook",
                                     ctx={"tier":tier,"reason":_v45_ob_reason})
                    record_stage_reject("stage_g_to_e_rejected_by_liquidity")
                    return None
            else:
                score = _clamp(score + 1.5, 0.0, 100.0)
                breakdown["v45_orderbook_bonus"] = 1.5
        except Exception:
            _v647_record_suppressed_exception()

        # ---- Entry gate: score threshold (MIN_LIVE_SCORE for live, MIN_PAPER_SCORE for paper) ----
        is_live = bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and \
                  not bool(CONFIG.get("PAPER_TRADING_MODE", False))
        min_score = float(CONFIG["MIN_LIVE_SCORE"]) if is_live else float(CONFIG["MIN_PAPER_SCORE"])
        # v4.0.7 TWEAK — BEARISH soft-gate score penalty. In BEARISH regime
        # (family already restricted above), require a higher effective
        # min_score instead of blocking outright. Bounded +8 so it never
        # drifts into the general threshold policy.
        if regime == "BEARISH":
            min_score = min_score + 8.0
        # v4.2.2 ENHANCEMENT (3) — regime-adaptive score floor. Adds a small
        # bounded per-regime offset ON TOP of the existing min_score (the
        # BEARISH +8 hard add above stays intact). Total drift is hard-clamped
        # to ±6 score points so it can never drift into general threshold
        # policy. Fail-closed: on any error the offset defaults to 0 (no-op).
        try:
            if CONFIG.get("REGIME_SCORE_FLOOR_ENABLE", True):
                _offs = CONFIG.get("REGIME_SCORE_FLOOR_OFFSETS", {}) or {}
                _off = float(_offs.get(str(regime), 0.0) or 0.0)
                _off = max(-6.0, min(6.0, _off))  # hard bound
                min_score = min_score + _off
        except Exception:
            _v647_record_suppressed_exception()
        if CONFIG.get("V410_MASTER_ENABLE", True):
            _v43_mode_for_score = str(opp.get("strategy_mode", "") or "").upper()
            if _v43_mode_for_score in CanonicalStrategyPolicyRegistry.data():
                min_score = max(min_score, float(CanonicalStrategyPolicyRegistry.get(_v43_mode_for_score,{}).get("min_score", min_score)))
            else:
                _v410_fam_score = FamilyPolicyLayer.min_score(min_score, str(opp.get("family", "PULLBACK")))
                min_score = _v410_fam_score
            try:
                _soff=float((CONFIG.get("MSE_STRATEGY_MIN_SCORE_OFFSETS",{}) or {}).get(_v43_mode_for_score,0.0))
                _sess=StrategyPerformanceMemory.session_bucket()
                _learned=StrategyPerformanceMemory.score_floor_adjustment(_v43_mode_for_score,regime,_sess,str(opp.get("strategy_style","SCALP")))
                min_score=max(min_score+_soff,min_score+_learned)
            except Exception:
                _v647_record_suppressed_exception()
        _canonical_min_score = float(min_score)
        # v4.5.4 — compose V453 canonical relief and the legacy V45 rescue
        # ladder without stacking two independent score relaxations. Each
        # mechanism remains independently testable, but the LIVE decision
        # path uses the MORE RESTRICTIVE of the two effective floors.
        _adaptive_floor = _canonical_min_score
        _v45_floor = _canonical_min_score
        try:
            _adaptive_floor = float(getattr(_V420State, "adaptive_floor", _canonical_min_score) or _canonical_min_score)
            _adaptive_floor = max(float(CONFIG.get("V453_SCORE_FLOOR_MIN", 70.0)),
                                  min(_canonical_min_score, _adaptive_floor))
            if _adaptive_floor < _canonical_min_score:
                breakdown["v453_adaptive_floor"] = _adaptive_floor
        except Exception:
            _adaptive_floor = _canonical_min_score
        try:
            _v45_floor = float(_v45_effective_score_floor(_canonical_min_score))
            _v45_floor = max(float(CONFIG.get("V453_SCORE_FLOOR_MIN", 70.0)),
                             min(_canonical_min_score, _v45_floor))
        except Exception:
            _v45_floor = _canonical_min_score
        try:
            # Do NOT let an inactive legacy rescue floor pin the new V453
            # relief valve at the original family floor.  When legacy rescue is
            # inactive, V453 adaptive relief is the sole bounded relaxer. If
            # both mechanisms are active, use the more restrictive floor so
            # their relaxations never stack.
            _rescue_lvl = _v45_rescue_level()
            if _rescue_lvl > 0:
                _effective_floor = max(_adaptive_floor, _v45_floor)
            else:
                _effective_floor = _adaptive_floor
            breakdown["v45_canonical_min_score"] = _canonical_min_score
            breakdown["v453_adaptive_floor"] = _adaptive_floor
            breakdown["v45_rescue_floor"] = _v45_floor
            breakdown["v45_effective_score_floor"] = _effective_floor
            breakdown["v45_rescue_level"] = _rescue_lvl
            if not _v612_combined_score_floor_invariant(_canonical_min_score, _effective_floor):
                STATS["v612_score_floor_invariant_failures"] = int(STATS.get("v612_score_floor_invariant_failures", 0) or 0) + 1
                logger.error(
                    f"[V612-Floor] combined score-floor invariant failed: "
                    f"canonical={_canonical_min_score!r} effective={_effective_floor!r}"
                )
                return None
            breakdown["v612_combined_score_floor_ok"] = True
            min_score = _effective_floor
        except Exception:
            min_score = _canonical_min_score

        # V702 R5 ELITE LIVE QUALITY CLOSURE — the family-specific live floor
        # is re-applied after every bounded rescue/adaptive-floor mechanism.
        # R15 adds a tightly bounded starvation relief floor: only after a long
        # no-send interval, only on a LIVE non-hazardous cycle, and never below
        # the global MIN_LIVE_SCORE/economic hard gates. This prevents 24h+
        # starvation while preserving all structural/HTF/liquidity/fee/SL gates.
        try:
            if is_live and bool(CONFIG.get("V702_ELITE_LIVE_QUALITY_GATE_ENABLE", True)):
                _elite_floor = float(_v702_live_quality_score_floor(opp))
                _elite_floor_before = _elite_floor
                try:
                    _relieved, _relief_meta = _v704_starvation_score_floor_override(opp, float(score), float(_elite_floor))
                    if _relieved:
                        _elite_floor = float(_relief_meta.get("effective_floor", _elite_floor))
                        # This is the actual bounded starvation relief: lower the
                        # effective live score floor to the verified relief floor,
                        # but never below MIN_LIVE_SCORE/global hard floor.
                        _global_relief_floor = _v704_hard_global_score_floor()
                        min_score = max(_global_relief_floor, min(float(min_score), _elite_floor))
                        breakdown["v704_starvation_score_relief"] = dict(_relief_meta)
                        STATS["v704_starvation_score_relief_applied"] = int(STATS.get("v704_starvation_score_relief_applied", 0) or 0) + 1
                    else:
                        min_score = max(float(min_score), _elite_floor)
                except Exception as _v704_relief_exc:
                    logger.debug("[V704] starvation score relief probe suppressed: %s", _v704_relief_exc)
                    min_score = max(float(min_score), _elite_floor)
                breakdown["v702_elite_live_score_floor"] = float(_elite_floor)
                breakdown["v702_elite_live_score_floor_original"] = float(_elite_floor_before)
        except Exception as _v702_elite_floor_exc:
            # Fail closed for LIVE quality policy: malformed elite policy means
            # the standard canonical floor stays active and no relaxation occurs.
            logger.warning("[V702-R5] elite score-floor application failed: %s: %s", type(_v702_elite_floor_exc).__name__, _v702_elite_floor_exc)
            try:
                min_score = max(float(min_score), float(_canonical_min_score))
            except Exception:
                pass

        try:
            if score < _canonical_min_score and score >= (min_score - float(CONFIG.get("V45_NEARMISS_SCORE_GAP",6.0))):
                NearMissOpportunityQueue.add({
                    "symbol": symbol,
                    "candle_ts": str(df_5m.index[-2]) if len(df_5m) > 1 else None,
                    "strategy_mode": str(opp.get("strategy_mode","")),
                    "family": str(opp.get("family","")),
                    "score": float(score),
                    "score_floor": float(_canonical_min_score),
                    "features": {
                        "rs_score": rs_score_val, "volume_ratio": volume_ratio,
                        "structure_confidence": structure_confidence,
                        "spread_pct": spread_pct, "regime": regime, "tier": tier,
                    },
                })
        except Exception:
            _v647_record_suppressed_exception()
        if score < min_score:
            # v4.2.1 UNBLOCK_ARM_SCAN_COOLDOWN (site A) — family matching has
            # succeeded and scoring ran; arm the scan cooldown ONLY when the
            # prelim score at least approached the dynamic floor (floor - 5).
            # Cheap far-below-floor rejections cost NO cooldown — the symbol
            # stays re-eligible next scan. Fail-closed: exceptions => no arm.
            try:
                if _sym_cd_mode == "post_microstruct":
                    _sym_cd_sec_arm = float(CONFIG.get("SYMBOL_COOLDOWN_SEC", 0) or 0)
                    if _sym_cd_sec_arm > 0 and score >= (float(min_score) - 5.0):
                        COOLDOWNS.setdefault("symbol_scan", {})[symbol] = MONO_NOW()
            except Exception as _cd_arm_e:
                logger.debug(f"[Cooldown] deferred arm suppressed {symbol}: {_cd_arm_e}")
            # A29: observe the 65-69.99 band as SHADOW ONLY. It never changes
            # `min_score`, selection, queueing, Telegram, or execution authority.
            try:
                if is_live and 65.0 <= float(score) < 70.0:
                    _a29_shadow_fn = globals().get("_v702_a29_record_score_shadow")
                    if callable(_a29_shadow_fn):
                        _a29_shadow_fn(
                            symbol=symbol, score=float(score), floor=float(min_score),
                            family=str(opp.get("family", "")),
                            regime=str(regime or ""), tier=str(tier or ""),
                            reason="canonical_live_score_floor",
                        )
            except Exception:
                _v647_record_suppressed_exception()
            # Preserve both the effective threshold and the canonical pre-relief
            # threshold. This is diagnostic only; the existing hard score floor
            # and all downstream gates remain authoritative.
            try:
                breakdown["score_floor_used"] = float(min_score)
                breakdown["score_floor_canonical"] = float(_canonical_min_score)
                breakdown["score_floor_source"] = "canonical_builder_effective_floor"
                breakdown["score_floor_hard_global"] = float(_v704_hard_global_score_floor()) if callable(globals().get("_v704_hard_global_score_floor")) else float(CONFIG.get("MIN_LIVE_SCORE", 70.0))
            except Exception:
                pass
            record_rejection(trace_id, symbol, "score",
                             f"score_below_threshold:{score:.1f}<{min_score}",
                             "scorer", score=score, ctx={"breakdown": breakdown,
                                                          "min_score": min_score,
                                                          "score_floor_used": min_score,
                                                          "score_floor_canonical": _canonical_min_score,
                                                          "threshold": min_score,
                                                          "distance_to_threshold": min_score-score,
                                                          "family": str(opp.get("family","")),
                                                          "regime": regime, "tier": tier,
                                                          "sig_class": sig_class})
            record_stage_reject("stage_e_to_q_rejected_by_score")
            return None

        # v4.5.21: do NOT arm scan cooldown at E. A canonical E->Q rejection
        # must remain retryable within the same cycle so a prequalified
        # alternate strategy can be tested. Cooldown is committed only at Q.
        if not bool(CONFIG.get("V521_COOLDOWN_ARM_ON_QUEUE_ONLY", True)):
            try:
                if _sym_cd_mode == "post_microstruct":
                    _sym_cd_sec_arm = float(CONFIG.get("SYMBOL_COOLDOWN_SEC", 0) or 0)
                    if _sym_cd_sec_arm > 0:
                        COOLDOWNS.setdefault("symbol_scan", {})[symbol] = MONO_NOW()
            except Exception as _cd_arm_e2:
                logger.debug(f"[Cooldown] eligible arm suppressed {symbol}: {_cd_arm_e2}")

        # V702 R5 ELITE LIVE QUALITY GATE — require cross-factor agreement
        # after the canonical score has already passed. This is deliberately
        # stricter than the normal floor and is applied only to LIVE entries.
        if is_live and bool(CONFIG.get("V702_ELITE_LIVE_QUALITY_GATE_ENABLE", True)):
            try:
                _eq_ok, _eq_reason, _eq_ctx = _v702_elite_live_context_gate(
                    opp=opp, score=float(score), htf_strength=float(htf_strength or 0.0),
                    volume_ratio=volume_ratio, rs_score_val=rs_score_val,
                    structure_confidence=structure_confidence,
                    retest_quality_score=retest_quality_score,
                    chase_atr=float(opp.get("chase_atr", 0.0) or 0.0),
                    tier=str(tier or ""),
                    regime=str(regime or ""),
                    severity=str(opp.get("macro_severity", opp.get("bearish_severity", "")) or ""),
                )
                breakdown["v702_elite_quality_context"] = dict(_eq_ctx or {})
                if not _eq_ok:
                    try:
                        _advisory_ok, _advisory_meta = _v704_starvation_elite_context_advisory(
                            opp=opp, score=float(score), reason=str(_eq_reason or ""), ctx=dict(_eq_ctx or {})
                        )
                    except Exception:
                        _advisory_ok, _advisory_meta = False, {}
                    if _advisory_ok:
                        breakdown["v704_elite_context_advisory"] = dict(_advisory_meta)
                        STATS["v704_elite_context_advisories"] = int(STATS.get("v704_elite_context_advisories", 0) or 0) + 1
                        logger.info("[V704-STARV] elite context advisory %s %s", symbol, _advisory_meta)
                    else:
                        _eq_l = str(_eq_reason or "quality_contract_failed").lower()
                        _v702_a49_record_elite_quality_rejection(
                            trace_id=trace_id,
                            symbol=symbol,
                            reason=str(_eq_reason or "quality_contract_failed"),
                            score=score,
                            family=str(opp.get("family", "")),
                            mode=str(opp.get("strategy_mode", "")),
                            context=dict(_eq_ctx or {}),
                        )
                        record_stage_reject("stage_e_to_q_rejected_by_quality")
                        STATS["v702_elite_quality_rejects"] = int(STATS.get("v702_elite_quality_rejects", 0) or 0) + 1
                        STATS[f"v702_elite_quality_rejects.{str(_eq_reason or 'unknown')}"] = int(STATS.get(f"v702_elite_quality_rejects.{str(_eq_reason or 'unknown')}", 0) or 0) + 1
                        return None
                STATS["v702_elite_quality_passes"] = int(STATS.get("v702_elite_quality_passes", 0) or 0) + 1
            except Exception as _eq_exc:
                # Fail-closed for a LIVE elite contract; do not turn an audit
                # exception into an entry permission.
                STATS["v702_elite_quality_errors"] = int(STATS.get("v702_elite_quality_errors", 0) or 0) + 1
                record_rejection(trace_id, symbol, "structure", "v702.elite_quality.unverifiable", "v702_elite_quality_gate", score=score)
                record_stage_reject("stage_e_to_q_rejected_by_quality")
                logger.warning("[V702-R5] elite quality gate failed closed for %s: %s: %s", symbol, type(_eq_exc).__name__, _eq_exc)
                return None

        STATS["signals_eligible"] += 1
        try:
            V423Funnel.note_stage("E")
            _V420State.note_e()
            V423Funnel.note_accepted_score(score)
        except Exception:
            _v647_record_suppressed_exception()

        # ---- Compute entry / SL / TP ----
        entry = float(df_5m["close"].iloc[-1])
        _mode = str(getattr(preferred_candidate, "strategy_mode", "")
                    or opp.get("strategy_mode", "") or opp.get("family", "") or "").upper()
        _family_for_contract = str(getattr(preferred_candidate, "family", "")
                                   or opp.get("family", "") or "").upper()
        _mode, _style, _contract_tf, _has_strategy_contract = _v701_3_resolve_strategy_identity(
            _mode, _family_for_contract,
            fallback_style=str(opp.get("strategy_style", "SCALP") or "SCALP"),
            fallback_timeframe=str(opp.get("timeframe_profile", "") or ""),
        )
        if _has_strategy_contract:
            # The same contract drives entry risk geometry, exit profile and
            # telemetry. Do not allow stale opp/feature metadata to turn a
            # higher-timeframe SWING candidate back into a SCALP at the Builder.
            opp["strategy_style"] = _style
            if _contract_tf:
                opp["timeframe_profile"] = _contract_tf
        _strategy_risk_factor=float(opp.get("_v44_risk_factor",1.0) or 1.0)
        # V702.1 ELITE PULLBACK RISK BRIDGE: a one-variable elite recovery
        # may enter only after the original V669 hard contract re-check passes.
        # Its dedicated 0.65 factor compounds with existing strategy/rescue
        # factors and therefore reduces notional; it never relaxes eligibility.
        try:
            _v702_elite_recovery = bool(opp.get("v702_pb_elite_recovery", False))
            _v702_elite_rf = float(opp.get("v702_pb_elite_risk_factor", 1.0) or 1.0)
            if _v702_elite_recovery and math.isfinite(_v702_elite_rf) and 0.35 <= _v702_elite_rf < 1.0:
                _strategy_risk_factor *= _v702_elite_rf
                _strategy_risk_factor = max(0.35, min(1.0, _strategy_risk_factor))
                opp["v702_pb_elite_effective_risk_factor"] = float(_strategy_risk_factor)
                STATS["v702_pb_elite_risk_bridge_applied"] = int(STATS.get("v702_pb_elite_risk_bridge_applied", 0) or 0) + 1
        except Exception:
            _v647_record_suppressed_exception()
        try:
            if bool(CONFIG.get("V459_HIGH_RECALL_ENABLE", True)):
                _hr_mode = str(opp.get("strategy_mode", opp.get("family", "")) or "").upper()
                _hr_family = str(opp.get("family", "") or "").upper()
                _hr_factor = _v459_risk_factor_for(_hr_mode, _hr_family)
                if _hr_factor < 1.0:
                    _strategy_risk_factor *= _hr_factor
                    opp["_v459_low_target"] = True
                    opp["_v459_risk_factor"] = _hr_factor
        except Exception:
            _v647_record_suppressed_exception()
        # V689 bounded MID rescue: use the existing canonical sizing authority.
        # This only applies when the same canonical tier helper has explicitly
        # allowed a LARGE-preference family to operate in MID during rescue.
        try:
            _v689_family=str(opp.get("family",_mode) or _mode).upper()
            _v689_tier=str(opp.get("tier",tier) or tier).upper()
            _v689_features=dict(opp or {})
            _v689_mid_ok=_v689_tier_allowed(_v689_family,_mode,_v689_tier,_v689_score_to_01(score),_v689_features)
            _v689_min_t=str((_v689_policy_for(_v689_family,_mode) or {}).get("min_tier","MID") or "MID").upper()
            if _v689_mid_ok and _v689_tier=="MID" and _v689_min_t=="LARGE" and not bool(opp.get("_v689_mid_rescue_applied",False)):
                _strategy_risk_factor *= float(CONFIG.get("V689_MID_RESCUE_RISK_FACTOR",0.50))
                opp["_v689_mid_rescue_applied"]=True
                opp["_v689_effective_risk_factor"]=float(_strategy_risk_factor)
        except Exception:
            _v647_record_suppressed_exception()
        try:
            _strategy_risk_factor *= float(_v45_rescue_risk_factor())
            _strategy_risk_factor = max(0.35, min(1.0, _strategy_risk_factor))
            opp["_v45_rescue_level"] = _v45_rescue_level()
            opp["_v45_risk_factor"] = _strategy_risk_factor
        except Exception:
            _v647_record_suppressed_exception()
        # V702-R31: resolve the exact same operator-facing quality grade before
        # PreSend so ticket sizing and the Telegram grade cannot disagree.
        _quality_grade = str(opp.get("quality_grade", "") or "").strip().upper()
        try:
            _rs_for_grade = (rs_score_val / 100.0) if rs_score_val is not None and abs(float(rs_score_val)) > 1.5 else rs_score_val
            _quality_grade, _quality_grade_conf = OpportunityTelegramNotifier._opportunity_grade(
                float(score), float(min_score), htf_strength, volume_ratio, _rs_for_grade,
                float(opp.get("chase_atr", 0.0) or 0.0), str(tier or ""), str(opp.get("family", _mode) or _mode)
            )
            opp["quality_grade"] = _quality_grade
            opp["quality_grade_confidence"] = float(_quality_grade_conf)
            STATS["v702_grade_ticket_last_grade"] = str(_quality_grade)
        except Exception as _grade_resolve_exc:
            logger.debug("[V702-R31] grade resolution fallback %s: %s", symbol, _grade_resolve_exc)
            _quality_grade = str(opp.get("quality_grade", "C") or "C").upper()
        _strategy_session=StrategyPerformanceMemory.session_bucket()
        # V702 SWING geometry closure: preserve the exact strategy-native stop
        # distance generated by SwingPullbackEngine (15M ATR / native structure)
        # instead of rebuilding it from the Builder's 5M ATR. The generic 0.40%
        # floor remains only a hard minimum; it must never become the default
        # Swing stop when the native candidate supplied a wider valid risk unit.
        _native_candidate_risk_distance = None
        _native_candidate_family = str(getattr(preferred_candidate, "family", "") or "").upper() if preferred_candidate is not None else ""
        if _native_candidate_family == "SWING_PULLBACK" and preferred_candidate is not None:
            try:
                _ce = float(getattr(preferred_candidate, "entry_ref", 0.0) or 0.0)
                _cs = float(getattr(preferred_candidate, "sl_price", 0.0) or 0.0)
                _rd = _ce - _cs
                if math.isfinite(_rd) and _rd > 0 and math.isfinite(_ce) and _ce > 0:
                    _native_candidate_risk_distance = float(_rd)
            except Exception:
                _native_candidate_risk_distance = None
        _ep_raw = opp.get("exit_profile") or {}
        _ep = None
        if isinstance(_ep_raw, dict):
            try:
                _ep = ExitProfile(
                    float(_ep_raw["tp1_rr"]), float(_ep_raw["tp2_rr"]), float(_ep_raw["tp3_rr"]),
                    float(_ep_raw.get("trail_atr", CONFIG["TRAIL_ATR_MULTIPLIER"])),
                    float(_ep_raw.get("max_hold_hours", CONFIG["TIME_BASED_EXIT_HOURS"])),
                    _mode or _style)
                if not _ep.validate():
                    _ep = None
            except Exception:
                _ep = None
        if _ep is None:
            try:
                _exit_mode = str(_v425_mode or _mode or "PULLBACK").upper()
                _ep = StrategyExitProfiles.profile_for(_exit_mode, _style)
            except Exception:
                _ep = ExitProfile(
                    float(CONFIG["TP1_RR"]), float(CONFIG["TP2_RR"]), float(CONFIG["TP3_RR"]),
                    float(CONFIG["TRAIL_ATR_MULTIPLIER"]),
                    float(CONFIG.get("SWING_MAX_HOLD_HOURS", CONFIG["TIME_BASED_EXIT_HOURS"])) if _style == "SWING"
                    else float(CONFIG["RUNNER_MAX_HOLD_HOURS"]),
                    _mode or _style)
        # v4.5.58: dynamic target geometry is derived from the already-selected
        # strategy exit profile, signal quality and ATR volatility.
        try:
            _rr1, _rr2, _rr3, _v558_tmeta = _v558_dynamic_rrs(
                family=str(_v425_mode or _mode or opp.get("family", "PULLBACK") or "PULLBACK"),
                score=float(score),
                entry=float(entry),
                sl=float(entry - (
                    float(CONFIG.get("SWING_ATR_SL_MULT", CONFIG["ATR_SL_MULT"])) if _style == "SWING"
                    else float(CONFIG["ATR_SL_MULT"])
                ) * float(atr_val)),
                atr=float(atr_val),
                base_rrs=(float(_ep.tp1_rr), float(_ep.tp2_rr), float(_ep.tp3_rr)),
            )
            _ep = replace(_ep, tp1_rr=_rr1, tp2_rr=_rr2, tp3_rr=_rr3)
            if bool(CONFIG.get("V558_TARGET_DYNAMIC_TELEMETRY", True)):
                opp["_v558_target_meta"] = _v558_tmeta
        except Exception:
            _v647_record_suppressed_exception()

        try:
            if bool(CONFIG.get("V459_ENTRY_CLASS_TELEMETRY", True)):
                opp["_v459_entry_class"] = _v459_entry_class(_mode, str(opp.get("family","") or ""))
                _ec = opp["_v459_entry_class"]
                STATS[f"v459_entry_class.{_ec}.eligible"] = STATS.get(
                    f"v459_entry_class.{_ec}.eligible", 0) + 1
        except Exception:
            _v647_record_suppressed_exception()
        sl_mult = float(CONFIG.get("SWING_ATR_SL_MULT", CONFIG["ATR_SL_MULT"])) if _style == "SWING" else float(CONFIG["ATR_SL_MULT"])
        if _native_candidate_risk_distance is not None:
            # Exact selected-candidate handoff: use the Swing engine's native
            # risk unit at the Builder entry, preserving its 15M-based geometry.
            sl = float(entry) - float(_native_candidate_risk_distance)
            if breakdown is not None:
                breakdown["v702_swing_native_sl"] = {
                    "status": "candidate_native",
                    "candidate_entry_ref": float(getattr(preferred_candidate, "entry_ref", 0.0) or 0.0),
                    "candidate_sl": float(getattr(preferred_candidate, "sl_price", 0.0) or 0.0),
                    "risk_distance": float(_native_candidate_risk_distance),
                    "builder_entry": float(entry),
                    "sl_pct": (float(entry)-sl)/max(float(entry),1e-12)*100.0,
                }
        elif str(opp.get("family", "")).upper() in {"PULLBACK", "MTF_PULLBACK"}:
            _pb_sl = _v578_pullback_stop(
                df_5m=df_5m, entry=entry, atr=atr_val,
                zone_ref=opp.get("zone_ref")
            )
            if _pb_sl is None:
                record_rejection(
                    trace_id, symbol, "risk", "pullback_structural_sl_infeasible",
                    "sl_geometry", ctx={"entry": entry, "atr": atr_val, "zone_ref": opp.get("zone_ref")}
                )
                record_stage_reject("stage_e_to_q_rejected_by_sl_geometry")
                return None
            sl = _pb_sl
        else:
            sl = entry - sl_mult * atr_val

        # V700: one global hard SL floor at the final geometry boundary for all
        # families. PULLBACK keeps its structural stop; this only fixes a true
        # configured percentage-floor breach.
        sl = _v700_apply_final_sl_floor(
            entry, sl, atr_val, str(opp.get("family", _mode) or _mode), breakdown
        )
        if sl is None:
            record_rejection(
                trace_id, symbol, "risk", "sl_floor_repair_infeasible",
                "sl_geometry", ctx={"entry": entry, "atr": atr_val, "family": str(opp.get("family", _mode) or _mode)}
            )
            record_stage_reject("stage_e_to_q_rejected_by_sl_geometry")
            return None

        # v4.5.80 — the final entry must still belong to the original
        # zone-based pullback thesis. This is checked both before and after
        # AdaptiveRepricing; here it is the canonical final-state assertion.
        if str(opp.get("family", _mode)).upper() in {"PULLBACK", "MTF_PULLBACK"}:
            _zone_ok, _zone_reason = _v580_pullback_entry_zone_ok(
                entry=entry, atr=atr_val, zone_ref=opp.get("zone_ref"), df_5m=df_5m
            )
            if not _zone_ok:
                record_rejection(
                    trace_id, symbol, "structural", "pullback_entry_zone_drift",
                    "entry_coherence", ctx={"family": _mode, "entry": entry,
                                             "zone_ref": opp.get("zone_ref"),
                                             "atr": atr_val, "detail": _zone_reason}
                )
                record_stage_reject("stage_e_to_q_rejected_by_entry_coherence")
                return None

        tp1 = entry + float(_ep.tp1_rr) * (entry - sl)
        tp2 = entry + float(_ep.tp2_rr) * (entry - sl)
        tp3 = entry + float(_ep.tp3_rr) * (entry - sl)
        # A22 FIX: this TP1 geometry is provisional. AdaptiveRepricing and the
        # final SR-aware target planner below recompute entry/SL/TPs. Rejecting
        # here could discard a candidate whose FINAL geometry becomes viable.
        # Keep the observation, but leave the hard family TP1 floor to the
        # post-reprice checks below (including the SR-capped final target).
        try:
            _a22_pre_tp1_ok = (not CONFIG.get("V410_MASTER_ENABLE", True) or
                FamilyPolicyLayer.tp1_distance_ok(entry, tp1, atr_val, str(opp.get("family", "PULLBACK"))))
            if not _a22_pre_tp1_ok:
                STATS["v702_a22_pre_reprice_tp1_floor_warnings"] = int(
                    STATS.get("v702_a22_pre_reprice_tp1_floor_warnings", 0) or 0) + 1
                LifecycleTrace.record(trace_id, "A22_PRE_REPRICE_TP1_FLOOR_WARNING", {
                    "symbol": str(symbol), "family": str(opp.get("family", "PULLBACK")),
                    "entry_pre_reprice": float(entry), "sl_pre_reprice": float(sl),
                    "tp1_pre_reprice": float(tp1), "atr": float(atr_val),
                    "tp1_distance_atr": ((float(tp1)-float(entry))/float(atr_val)) if float(atr_val)>0 else None,
                    "note": "diagnostic_only_final_geometry_gate_remains_hard",
                })
        except Exception:
            STATS["v702_a22_pre_reprice_tp1_diag_errors"] = int(
                STATS.get("v702_a22_pre_reprice_tp1_diag_errors", 0) or 0) + 1

        # ---- Daily circuit breaker (hard pre-gate) ----
        can, why = DailyCircuitBreaker.can_open_new()
        if not can:
            record_rejection(trace_id, symbol, "circuit_breaker", why, "daily_cb")
            record_stage_reject("stage_e_to_q_rejected_by_daily_cb")
            return None

        # ---- Candle dedup ----
        # Deduplicate by the latest CLOSED entry candle only. Using the current
        # forming candle makes repeated ticks look like distinct opportunities
        # and can consume ranking/selection budget without new information.
        try:
            candle_ts = int(_coherence_closed_ts(df_5m))
        except Exception:
            candle_ts = 0
        if candle_ts <= 0:
            record_rejection(trace_id, symbol, "system", "closed_candle_identity_unavailable", "dedup")
            record_stage_reject("stage_e_to_q_rejected_by_missing_closed_candle")
            return None
        k = CandleDedup.key(symbol, CONFIG["TF_ENTRY"], candle_ts)
        dedup_ttl_sec = max(
            int(CONFIG["SIGNAL_DEDUP_TTL_SEC"]),
            int(math.ceil(_timeframe_to_seconds(str(CONFIG.get("TF_ENTRY", "5m"))) * 1.1)),
        )
        if CandleDedup.seen_recently(k, dedup_ttl_sec):
            record_rejection(trace_id, symbol, "cooldown", "candle_dup", "dedup")
            record_stage_reject("stage_e_to_q_rejected_by_dedup")
            return None
        # v4.5.21: defer CandleDedup.mark until the signal is actually queued.
        # A pre-send reject must not consume the whole closed candle.
        _candle_dedup_key_deferred = k

        # ---- Adaptive repricing (bounded) ----
        # v4.0.5 FIX #2 — Repricing now runs BEFORE PreSendGate so sizing /
        # risk-coherence / caps are evaluated on the FINAL (entry, sl, tp1,
        # tp2, tp3) that will actually be submitted. Previously the gate
        # sized against the planned entry and repricing then mutated entry/
        # sl/tp under it, causing desync between gate decisions and the
        # order that shipped.
        # Effect : PreSendGate decisions match the submitted order exactly;
        #          no code-path added, only reordered + tp3 recompute kept.
        try:
            # Final execution reference comes from the fresh venue ticker.
            # For a LONG market buy, ask is the executable-side reference when valid.
            _entry_ticker = await asyncio.wait_for(
                exchange.fetch_ticker(symbol),
                timeout=float(CONFIG.get("V702_ENTRY_TICKER_TIMEOUT_SEC", 3.0))
            )
            _ask = float((_entry_ticker or {}).get("ask") or 0.0)
            _last = float((_entry_ticker or {}).get("last") or (_entry_ticker or {}).get("close") or 0.0)
            live_price = _ask if bool(CONFIG.get("V702_ENTRY_TICKER_USE_ASK", True)) and _ask > 0 else _last
            if not (math.isfinite(live_price) and live_price > 0):
                raise ValueError("entry_ticker_price_unavailable")
            re_ok, ne, nsl, ntp, rreason = AdaptiveRepricing.maybe_reprice(
                entry, live_price, atr_val)
            if re_ok:
                entry, sl = ne, nsl
                # v4.5.80 — AdaptiveRepricing changes entry and temporarily
                # derives an ATR stop; reapply the same structural PULLBACK SL
                # to the FINAL entry so repricing cannot silently revert the
                # trade back to ATR-only protection. Failure is fail-closed.
                if (
                    bool(CONFIG.get("V579_PULLBACK_REPRICE_STRUCTURAL_SL_ENABLE", True))
                    and str(opp.get("family", _mode)).upper() in {"PULLBACK", "MTF_PULLBACK"}
                ):
                    _re_sl = _v578_pullback_stop(
                        df_5m=df_5m, entry=entry, atr=atr_val,
                        zone_ref=opp.get("zone_ref")
                    )
                    if _re_sl is None:
                        record_rejection(
                            trace_id, symbol, "risk", "pullback_structural_sl_infeasible_after_reprice",
                            "sl_geometry", ctx={"entry": entry, "atr": atr_val, "zone_ref": opp.get("zone_ref")}
                        )
                        record_stage_reject("stage_e_to_q_rejected_by_sl_geometry")
                        return None
                    sl = _re_sl

                # V700/V702: AdaptiveRepricing can change FINAL entry. Re-run
                # the strategy-native stop authority after repricing so an ATR-only
                # temporary stop cannot erase a wider structural stop. Swing keeps
                # its original native risk unit; PULLBACK/MTF keep V578/V702 logic.
                _final_family = str(opp.get("family", _mode) or _mode).upper()
                if _final_family == "SWING_PULLBACK" and _native_candidate_risk_distance is not None:
                    sl = float(entry) - float(_native_candidate_risk_distance)
                elif _final_family == "MTF_PULLBACK":
                    _mtf_a15s = Indicators.atr(df_15m, int(CONFIG.get("ATR_PERIOD",14))) if df_15m is not None else None
                    _mtf_a15 = float(_mtf_a15s.iloc[-2]) if _mtf_a15s is not None and len(_mtf_a15s)>2 else 0.0
                    if _mtf_a15 > 0:
                        _mtf_sl2 = _v702_mtf_structural_sl(df_15m, entry, _mtf_a15, opp.get("zone_ref"))
                        if _mtf_sl2 is not None: sl = _mtf_sl2
                        else:
                            _re_sl = _v578_pullback_stop(df_5m=df_5m, entry=entry, atr=atr_val, zone_ref=opp.get("zone_ref"))
                            if _re_sl is None:
                                record_rejection(trace_id,symbol,"risk","mtf_structural_sl_infeasible_after_reprice","sl_geometry")
                                record_stage_reject("stage_e_to_q_rejected_by_sl_geometry")
                                return None
                            sl = _re_sl
                elif _final_family not in {"PULLBACK","MTF_PULLBACK"}:
                    sl = _v700_apply_final_sl_floor(
                        entry, sl, atr_val, _final_family, breakdown
                    )
                if sl is None:
                    record_rejection(
                        trace_id, symbol, "risk", "sl_floor_repair_infeasible_after_reprice",
                        "sl_geometry", ctx={"entry": entry, "atr": atr_val, "family": str(opp.get("family", _mode) or _mode)}
                    )
                    record_stage_reject("stage_e_to_q_rejected_by_sl_geometry")
                    return None

                # v4.5.80 — reprice is accepted only while the final entry
                # remains inside the original pullback zone/chase envelope.
                if str(opp.get("family", _mode)).upper() in {"PULLBACK", "MTF_PULLBACK"}:
                    _zone_ok, _zone_reason = _v580_pullback_entry_zone_ok(
                        entry=entry, atr=atr_val, zone_ref=opp.get("zone_ref"), df_5m=df_5m
                    )
                    if not _zone_ok:
                        record_rejection(
                            trace_id, symbol, "structural", "pullback_entry_zone_drift_after_reprice",
                            "entry_coherence", ctx={"family": _mode, "entry": entry,
                                                     "zone_ref": opp.get("zone_ref"),
                                                     "atr": atr_val, "detail": _zone_reason}
                        )
                        record_stage_reject("stage_e_to_q_rejected_by_entry_coherence")
                        return None

                # v4.5.10 — preserve the strategy-native ExitProfile after
                # adaptive repricing; never silently revert HR targets to the
                # global TP1/TP2/TP3 settings.
                tp1 = entry + float(_ep.tp1_rr) * (entry - sl)
                tp2 = entry + float(_ep.tp2_rr) * (entry - sl)
                tp3 = entry + float(_ep.tp3_rr) * (entry - sl)
                LifecycleTrace.record(trace_id, "REPRICED",
                                      {"reason": rreason, "new_entry": entry,
                                       "new_tp3": tp3})
                if bool(CONFIG.get("V558_TARGET_DYNAMIC_TELEMETRY", True)):
                    LifecycleTrace.record(
                        trace_id, "V558_DYNAMIC_TARGETS_FINAL",
                        {"family": str(opp.get("family", _mode)),
                         "score": float(score),
                         "rr1": float(_ep.tp1_rr),
                         "rr2": float(_ep.tp2_rr),
                         "rr3": float(_ep.tp3_rr),
                         "entry": float(entry), "sl": float(sl),
                         "tp1": float(tp1), "tp2": float(tp2), "tp3": float(tp3)}
                    )
        except Exception:
            _v647_record_suppressed_exception()

        # V702 FINAL SL BOUND AFTER REPRICE: once the live entry and any
        # strategy-native risk distance have been finalized, re-run ONLY the
        # global hard percentage envelope. This prevents a valid native Swing
        # risk distance from becoming <0.40% solely because the executable ask
        # moved, while avoiding a second generic structural rewrite here.
        try:
            _post_rp_sl = _v700_enforce_global_sl_floor(
                entry=float(entry), sl=float(sl), atr=float(atr_val),
                family=str(opp.get("family", _mode) or _mode)
            )
        except Exception:
            _post_rp_sl = None
        if _post_rp_sl is None:
            record_rejection(trace_id, symbol, "risk", "final_sl_bounds_invalid",
                             "sl_geometry", ctx={"entry":entry,"sl":sl,"family":str(opp.get("family",_mode) or _mode)})
            record_stage_reject("stage_e_to_q_rejected_by_sl_geometry")
            return None
        sl = float(_post_rp_sl)

        # V702 R38: bind entry/SL precision BEFORE S/R planning and PreSend sizing.
        # The same tick-normalized prices now feed the target plan, economics, TradeState
        # and the native stop request. A precision failure is a documented hard rejection.
        try:
            _entry_px_ok, _entry_px_final, _entry_px_reason = _v702_price_to_precision(
                exchange, symbol, float(entry)
            )
            _sl_px_ok, _sl_px_final, _sl_px_reason = _v702_price_to_precision(
                exchange, symbol, float(sl)
            )
        except Exception as _px_exc:
            _entry_px_ok, _sl_px_ok = False, False
            _entry_px_final, _sl_px_final = float(entry), float(sl)
            _entry_px_reason = _sl_px_reason = f"precision_exception:{type(_px_exc).__name__}"
        if not (_entry_px_ok and _sl_px_ok and 0 < float(_sl_px_final) < float(_entry_px_final)):
            _precision_reason = str(_entry_px_reason if not _entry_px_ok else _sl_px_reason)
            record_rejection(
                trace_id, symbol, "risk", "final_entry_sl_precision_invalid",
                "target_precision", ctx={"entry":float(entry),"sl":float(sl),
                "entry_reason":str(_entry_px_reason),"sl_reason":str(_sl_px_reason),
                "detail":_precision_reason}
            )
            record_stage_reject("stage_q_to_s_rejected_by_presend_gate")
            return None
        entry = float(_entry_px_final)
        sl = float(_sl_px_final)

        _sr_target_ctx = {}
        # V702 SR-AWARE TARGETS: re-anchor the strategy-native RR geometry to the
        # FINAL executable entry and FINAL bounded stop, then cap TP1/TP2 before
        # confirmed overhead 15m resistance levels where the economic room allows.
        # Existing PreSend fee/RR, family-distance, risk and ordering gates remain
        # authoritative; missing SR context falls back to canonical ExitProfile RR.
        try:
            _sr_base_risk = float(entry) - float(sl)
            if not (math.isfinite(_sr_base_risk) and _sr_base_risk > 0):
                raise ValueError("final_risk_unit_invalid_for_targets")
            tp1 = float(entry) + float(_ep.tp1_rr) * _sr_base_risk
            tp2 = float(entry) + float(_ep.tp2_rr) * _sr_base_risk
            tp3 = float(entry) + float(_ep.tp3_rr) * _sr_base_risk
            _sr_target_ctx = _v702_sr_aware_target_plan(
                entry=float(entry), sl=float(sl), tp1_rr=float(_ep.tp1_rr),
                tp2_rr=float(_ep.tp2_rr), tp3_rr=float(_ep.tp3_rr),
                df_15m=df_15m, family=str(opp.get("family", _mode) or _mode),
            )
            if bool(_sr_target_ctx.get("blocked", False)):
                record_rejection(
                    trace_id, symbol, "structural", "sr_target_room_insufficient",
                    "sr_aware_targets", ctx={"family":str(opp.get("family",_mode) or _mode),
                    "entry":float(entry),"sl":float(sl),**_sr_target_ctx}
                )
                record_stage_reject("stage_q_to_s_rejected_by_presend_gate")
                return None
            tp1 = float(_sr_target_ctx.get("tp1", tp1))
            tp2 = float(_sr_target_ctx.get("tp2", tp2))
            tp3 = float(_sr_target_ctx.get("tp3", tp3))
            # The first TP distance is checked again because S/R may have capped
            # the profile target. This reuses the existing family hard-floor; it
            # does not lower the floor to accommodate the new target.
            if CONFIG.get("V410_MASTER_ENABLE", True) and not FamilyPolicyLayer.tp1_distance_ok(
                float(entry), float(tp1), float(atr_val), str(opp.get("family", "PULLBACK"))
            ):
                _a22_tp1_floor = float(FamilyPolicyLayer.get_family_policy(str(opp.get("family", "PULLBACK"))).get("tp1_atr_floor", 0.7))
                _a22_tp1_dist_atr = ((float(tp1)-float(entry))/float(atr_val)) if float(atr_val)>0 else None
                _a22_tp1_diag = {
                    "family":str(opp.get("family", "PULLBACK")), "atr":float(atr_val),
                    "entry":float(entry), "tp1":float(tp1), "tp1_source":_sr_target_ctx.get("tp1_source"),
                    "tp1_distance_atr":_a22_tp1_dist_atr, "required_tp1_distance_atr":_a22_tp1_floor,
                    "shortfall_atr":(max(0.0, _a22_tp1_floor-float(_a22_tp1_dist_atr)) if _a22_tp1_dist_atr is not None else None),
                    "nearest_resistance":(_sr_target_ctx.get("resistance_levels") or [None])[0],
                    "sr_target_context":_sr_target_ctx,
                }
                STATS["v702_a22_final_tp1_floor_blocks"] = int(STATS.get("v702_a22_final_tp1_floor_blocks", 0) or 0) + 1
                STATS["v702_a22_last_final_tp1_floor_block"] = dict(_a22_tp1_diag)
                _tp1_distance_text = "NA" if _a22_tp1_dist_atr is None else f"{float(_a22_tp1_dist_atr):.3f}"
                _tp1_floor_reason = (
                    f"family_tp1_distance_below_floor:tp1_atr={_tp1_distance_text}<{_a22_tp1_floor:.3f}"
                )
                V410Telemetry.reject(
                    trace_id, symbol, "structural", _tp1_floor_reason,
                    "sr_aware_targets", _a22_tp1_diag
                )
                record_stage_reject("stage_e_to_q_rejected_by_score")
                return None
            if isinstance(breakdown, dict):
                breakdown["v702_sr_aware_targets"] = dict(_sr_target_ctx)
            if _sr_target_ctx.get("tp1_source") == "RESISTANCE" or _sr_target_ctx.get("tp2_source") == "RESISTANCE":
                STATS["v702_sr_target_plan_applied"] = int(STATS.get("v702_sr_target_plan_applied",0) or 0) + 1
            LifecycleTrace.record(
                trace_id, "V702_SR_AWARE_TARGETS_FINAL",
                {"family":str(opp.get("family",_mode) or _mode),"entry":float(entry),
                 "sl":float(sl),"tp1":float(tp1),"tp2":float(tp2),"tp3":float(tp3),
                 **_sr_target_ctx}
            )
        except Exception as _sr_target_exc:
            # Optional structure targeting must never produce malformed orders.
            # On calculator/telemetry failure, preserve the canonical RR profile
            # using the already-final entry and stop; downstream hard gates remain.
            tp1 = float(entry) + float(_ep.tp1_rr) * (float(entry) - float(sl))
            tp2 = float(entry) + float(_ep.tp2_rr) * (float(entry) - float(sl))
            tp3 = float(entry) + float(_ep.tp3_rr) * (float(entry) - float(sl))
            STATS["v702_sr_target_fallback_error"] = int(STATS.get("v702_sr_target_fallback_error",0) or 0) + 1
            logger.warning("[V702-SR-TARGETS] fallback to ExitProfile RR for %s: %s", symbol, type(_sr_target_exc).__name__)

        # V702 FINAL ENTRY COHERENCE: all strategy families are evaluated on a
        # closed-bar snapshot, so the live entry may not drift into a new thesis.
        try:
            _entry_coh_ok, _entry_coh_reason = _v702_final_entry_coherence(
                preferred_candidate, opp, float(entry), float(atr_val)
            )
        except Exception as _entry_coh_exc:
            _entry_coh_ok, _entry_coh_reason = False, f"exception:{type(_entry_coh_exc).__name__}"
        if not _entry_coh_ok:
            record_rejection(
                trace_id, symbol, "structural", f"final_entry_coherence.{_entry_coh_reason}",
                "entry_coherence", ctx={"family":str(opp.get("family",_mode) or _mode),"mode":_mode,"entry":entry,"candidate_entry":getattr(preferred_candidate,"entry_ref",None),"atr":atr_val}
            )
            record_stage_reject("stage_e_to_q_rejected_by_entry_coherence")
            return None

        # ---- v4.0.6 FIX #3 — Post-repricing structural invariant --------------
        # After AdaptiveRepricing and IMMEDIATELY BEFORE PreSendGate, verify
        # the strict ordering invariant:
        #     sl < entry < tp1 < tp2 < tp3
        # If it fails, reject the signal with an explicit structural/reprice
        # rejection — do NOT send the order. This closes the gap where a
        # repricing edit could have silently violated the ordering while the
        # gate below only checked entry→tp1→tp2 without tp3.
        try:
            _inv_ok = (sl > 0 and entry > 0 and tp1 > 0 and tp2 > 0 and tp3 > 0
                       and (sl < entry < tp1 < tp2 < tp3))
        except Exception:
            _inv_ok = False
        if not _inv_ok:
            # v4.2.1 UNBLOCK-PATCH — single bounded repair attempt before
            # rejecting: recompute tp1/tp2/tp3 from the canonical RR multiples
            # off the CURRENT (entry, sl), then enforce a minimal tp1 gap of
            # max(0.1% of entry, 1 tick-equivalent) so fee geometry cannot
            # collapse the ordering. Runs ONCE; a second failure rejects with
            # the full level snapshot for diagnosability. SL/TP math itself
            # (RR multiples, ATR-based sl) is unchanged.
            _repaired = False
            try:
                if sl > 0 and entry > sl:
                    _risk = entry - sl
                    _tp1_r = entry + float(_ep.tp1_rr) * _risk
                    _tp2_r = entry + float(_ep.tp2_rr) * _risk
                    _tp3_r = entry + float(_ep.tp3_rr) * _risk
                    # V636: never replace strategy-native TP1 RR with an
                    # arbitrary percentage gap. The exit profile is the
                    # canonical geometry; if it cannot satisfy ordering,
                    # reject rather than silently changing the strategy.
                    if (_tp1_r > entry and _tp2_r > _tp1_r and _tp3_r > _tp2_r):
                        tp1, tp2, tp3 = _tp1_r, _tp2_r, _tp3_r
                        _inv_ok = True
                        _repaired = True
                        LifecycleTrace.record(trace_id, "REPRICE_INVARIANT_REPAIRED",
                                              {"entry": entry, "sl": sl,
                                               "tp1": tp1, "tp2": tp2, "tp3": tp3})
            except Exception:
                _inv_ok = False
        if not _inv_ok:
            record_rejection(
                trace_id, symbol, "structural",
                "reprice_invariant_violation",
                "post_reprice",
                ctx={"sl": sl, "entry": entry,
                     "tp1": tp1, "tp2": tp2, "tp3": tp3,
                     "repair_attempted": True},
            )
            record_stage_reject("stage_q_to_s_rejected_by_presend_gate")
            return None

        # V700: remove the pre-PreSend score-only Telegram commit. The final
        # BUY alert is emitted only after canonical PreSend/live-ready.

        # ---- v4.0.9 DS-5 — EXECUTION_COOLDOWN pre-gate (RELOCATED) ----
        # Previously ran AFTER PreSendGate.evaluate (post-sizing); the whole
        # gate/sizing/liquidity pass was wasted on a cooldown-blocked symbol.
        # Now runs immediately BEFORE the gate. No invariant change.
        try:
            _exec_cd_sec = float(CONFIG.get("EXECUTION_COOLDOWN_SEC", 0) or 0)
            if _exec_cd_sec > 0:
                _last_exec_ts = float(COOLDOWNS.get("execution", {}).get(symbol, 0.0) or 0.0)
                _now_exec = MONO_NOW()
                if _last_exec_ts > 0 and (_now_exec - _last_exec_ts) < _exec_cd_sec:
                    record_rejection(trace_id, symbol, "cooldown", "execution_recent",
                                     "cooldown",
                                     ctx={"age_sec": _now_exec - _last_exec_ts,
                                          "cooldown_sec": _exec_cd_sec,
                                          "stage": "pre_presend_gate"})
                    record_stage_reject("stage_q_to_s_rejected_by_presend_gate")
                    return None
        except Exception as _cd_e2:
            logger.debug(f"[Cooldown] execution pre-gate suppressed {symbol}: {_cd_e2}")

        # ---- Layer 6: Pre-send gate (now evaluated on repriced levels) ----
        # v4.0.6 FIX #3 — tp3 is now passed through to RiskCoherence via the
        # gate so the canonical checker enforces the full ordering invariant
        # on the FINAL levels that will actually be submitted.
        # v4.0.9 DS-6 — forward `cached_ob` so PreSendGate→LiquidityDepth can
        # reuse the scoring-path orderbook instead of a second fetch.
        _shadow_pre = await ShadowPreSendGate.evaluate(
            exchange, symbol, entry, sl, tp1, tp2, tp3,
            market_data=market_data, cached_ob=cached_ob, strategy_score=score,
            strategy_mode=_mode, strategy_style=_style,
            timeframe_profile=str(getattr(preferred_candidate, "timeframe_profile", "") or market_data.get("timeframe_profile", "UNKNOWN")),
            htf_strength=htf_strength,
            strategy_family=str(getattr(preferred_candidate, "family", "") or _mode or "UNKNOWN"),
        )
        try:
            _shadow_ctx = _V702_PIPELINE_CONTEXT.get() or {}
            _shadow_key = str(_shadow_ctx.get("candidate_key") or _v702_candidate_wrap(preferred_candidate, market_data, symbol))
            _shadow_attempt_id = str(_shadow_ctx.get("evaluation_attempt_id") or "")
            _shadow_cycle_id = int(_shadow_ctx.get("cycle_id", V702PipelineMetrics._cycle()) or 0)
            _shadow_record = dict(_shadow_pre)
            _shadow_record.update({
                "reached": True,
                "candidate_key": _shadow_key,
                "evaluation_attempt_id": _shadow_attempt_id,
                "cycle_id": _shadow_cycle_id,
                "evaluated_at": float(WALL_NOW()),
                "exchange_order_submitted": False,
            })
            _shadow_store = STATS.setdefault("v702_shadow_presend_by_candidate", {})
            _shadow_store[_shadow_key] = _shadow_record
            _attempt_store = STATS.setdefault("v702_shadow_presend_by_attempt", {})
            if _shadow_attempt_id:
                _attempt_store[_shadow_attempt_id] = _shadow_record
                while len(_attempt_store) > 1024:
                    _attempt_store.pop(next(iter(_attempt_store)))
            while len(_shadow_store) > 512:
                _shadow_store.pop(next(iter(_shadow_store)))
            STATS["v702_a55_shadow_presend_passes" if _shadow_pre.get("eligible") else "v702_a55_shadow_presend_blocks"] = int(
                STATS.get("v702_a55_shadow_presend_passes" if _shadow_pre.get("eligible") else "v702_a55_shadow_presend_blocks", 0) or 0
            ) + 1
        except Exception:
            _v647_record_suppressed_exception()
        gate_ok, gate_msg, sd = await PreSendGate.evaluate(
            exchange, trace_id, symbol, entry, sl, tp1, tp2, tp3=tp3,
            cached_ob=cached_ob, strategy_mode=_mode, strategy_score=score,
            strategy_style=_style, strategy_risk_factor=_strategy_risk_factor,
            quality_grade=_quality_grade, spread_pct=spread_pct,
            timeframe_profile=str(getattr(preferred_candidate, "timeframe_profile", "") or market_data.get("timeframe_profile", "UNKNOWN")),
            htf_strength=htf_strength,
            strategy_family=str(getattr(preferred_candidate, "family", "") or _mode or "UNKNOWN"))
        # v4.5.50 — consume any fee-target rescue levels so the ORDER and
        # TradeState use the exact geometry that passed the canonical gate.
        if gate_ok and sd is not None and bool(getattr(sd, "fee_target_rescued", False)):
            _rescued_tp1 = float(getattr(sd, "rescued_tp1", tp1) or tp1)
            _rescued_tp2 = float(getattr(sd, "rescued_tp2", tp2) or tp2)
            _sr_rescue_ok, _sr_rescue_reason = _v702_sr_target_rescue_compatible(
                entry=float(entry), tp1=_rescued_tp1, tp2=_rescued_tp2, context=_sr_target_ctx
            )
            if not _sr_rescue_ok:
                record_rejection(
                    trace_id, symbol, "economic", "sr_target_fee_rescue_crossed_resistance",
                    "sr_aware_targets", ctx={"entry":float(entry),"tp1":_rescued_tp1,
                    "tp2":_rescued_tp2,"reason":_sr_rescue_reason,"sr_target_context":_sr_target_ctx}
                )
                record_stage_reject("stage_q_to_s_rejected_by_presend_gate")
                return None
            tp1 = _rescued_tp1
            tp2 = _rescued_tp2
            tp3 = float(getattr(sd, "rescued_tp3", tp3 or 0.0) or (tp3 or 0.0))
        if gate_ok and sd is not None and bool(getattr(sd, "small_net_targets_compressed", False)):
            _compressed_tp1 = float(getattr(sd, "compressed_tp1", tp1) or tp1)
            _compressed_tp2 = float(getattr(sd, "compressed_tp2", tp2) or tp2)
            _compressed_tp3 = float(getattr(sd, "compressed_tp3", tp3 or 0.0) or (tp3 or 0.0))
            _compression_family = str(opp.get("family", _mode) or _mode)
            _compression_family_ok = False
            _compression_family_reason = "family_tp1_atr_floor_not_met"
            try:
                _compression_family_ok = bool(FamilyPolicyLayer.tp1_distance_ok(
                    float(entry), _compressed_tp1, float(atr_val or 0.0), _compression_family
                ))
            except Exception as _compression_family_exc:
                _compression_family_reason = f"family_tp1_validation_error:{type(_compression_family_exc).__name__}"
            _sr_compress_ok, _sr_compress_reason = _v702_sr_target_rescue_compatible(
                entry=float(entry), tp1=_compressed_tp1, tp2=_compressed_tp2, context=_sr_target_ctx
            )
            # Compression is an optional optimization, not a new rejection lane.
            # If family-native ATR distance or S/R caps don't allow the closer
            # targets, retain the already viable original target geometry.
            if not _compression_family_ok or not _sr_compress_ok:
                sd.small_net_targets_compressed = False
                _why_compression_skipped = _compression_family_reason if not _compression_family_ok else str(_sr_compress_reason)
                STATS["v702_small_net_compression_skipped_family_or_sr"] = int(
                    STATS.get("v702_small_net_compression_skipped_family_or_sr", 0) or 0
                ) + 1
                LifecycleTrace.record(trace_id, "SMALL_NET_TARGET_COMPRESSION_SKIPPED", {
                    "reason": _why_compression_skipped, "fallback": "original_viable_targets",
                    "stop_loss_changed": False, "hard_gate_bypass": False,
                })
            else:
                tp1, tp2, tp3 = _compressed_tp1, _compressed_tp2, _compressed_tp3
                STATS["v702_small_net_compression_consumed"] = int(STATS.get("v702_small_net_compression_consumed", 0) or 0) + 1
                LifecycleTrace.record(trace_id, "SMALL_NET_TARGET_COMPRESSION_CONSUMED", {
                    "tp1":tp1,"tp2":tp2,"tp3":tp3,"stop_loss_changed":False,"hard_gate_bypass":False,
                })
        if not gate_ok:
            # v4.5.41: make the real final blocker explicit. This is telemetry
            # only and never changes the gate decision.
            try:
                _msg = str(gate_msg or "presend_rejected")
                STATS["v545_builder_blocker"] = int(STATS.get("v545_builder_blocker",0) or 0) + 1
                STATS["v545_last_builder_blocker"] = _msg[:240]
                _br = STATS.get("v545_builder_blocker_reasons") or {}
                _br[_msg[:180]] = int(_br.get(_msg[:180],0) or 0) + 1
                STATS["v545_builder_blocker_reasons"] = _br
                _v538_record_execution_blocker(symbol, _msg[:240], "pre_send")
                STATS["v541_presend_blockers"] = int(STATS.get("v541_presend_blockers", 0) or 0) + 1
            except Exception:
                _v647_record_suppressed_exception()
            # v4.0.2 PATCH E.3 — stage counter for Q→S rejections at the gate
            record_stage_reject("stage_q_to_s_rejected_by_presend_gate")
            return None

        # V702 R38 FINAL TARGET LOCK: PreSend may apply the bounded fee rescue, so
        # normalize its output again and re-assert geometry, S/R ceilings and the
        # original net-fee floors on the exact levels that will be queued.
        _final_geom = _v702_normalize_final_geometry(
            exchange=exchange, symbol=symbol, entry=entry, sl=sl,
            tp1=tp1, tp2=tp2, tp3=tp3, sr_context=_sr_target_ctx,
            notional=float(getattr(sd, "notional_after_caps", 0.0) or 0.0),
            check_economics=True, family=str(opp.get("family",_mode) or _mode), atr=float(atr_val),
            spread_pct=spread_pct,
        )
        if not bool(_final_geom.get("ok", False)):
            _geom_reason = str(_final_geom.get("reason") or "final_target_geometry_invalid")
            record_rejection(
                trace_id, symbol, "economic" if _geom_reason.startswith("fee_") else "structural",
                f"final_target_geometry.{_geom_reason}", "target_precision",
                ctx={"entry":entry,"sl":sl,"tp1":tp1,"tp2":tp2,"tp3":tp3,
                     "sr_context":_sr_target_ctx,"geometry":_final_geom}
            )
            STATS["v702_final_target_geometry_rejects"] = int(
                STATS.get("v702_final_target_geometry_rejects", 0) or 0
            ) + 1
            record_stage_reject("stage_q_to_s_rejected_by_presend_gate")
            return None
        entry = float(_final_geom["entry"])
        sl = float(_final_geom["sl"])
        tp1 = float(_final_geom["tp1"])
        tp2 = float(_final_geom["tp2"])
        tp3 = float(_final_geom["tp3"])
        if bool(getattr(sd, "fee_target_rescued", False)):
            sd.rescued_tp1, sd.rescued_tp2, sd.rescued_tp3 = tp1, tp2, tp3
        LifecycleTrace.record(trace_id, "V702_FINAL_TARGET_GEOMETRY_LOCKED", {
            "entry":entry,"sl":sl,"tp1":tp1,"tp2":tp2,"tp3":tp3,
            "revision":V702_SR_TARGETS_REVISION,"precision_applied":True,
            "sr_reason":str(_sr_target_ctx.get("reason", "unknown")),
            "fee_rescue":bool(getattr(sd, "fee_target_rescued", False)),
            "small_net_compression":bool(getattr(sd, "small_net_targets_compressed", False)),
            "hard_gate_bypass":False,
        })

        # v4.5.34: explicit LIVE-READY commit. This means the candidate has
        # passed canonical score/floor and all final PreSend hard gates. The
        # exchange has not yet accepted the entry.
        STATS["v534_live_ready"] = int(STATS.get("v534_live_ready",0) or 0) + 1
        STATS["v545_cycle_live_ready"] = int(STATS.get("v545_cycle_live_ready",0) or 0) + 1
        try:
            _v689_update_family("live_ready",str(opp.get("family",_mode) or _mode).upper())
        except Exception: pass
        STATS["v534_last_live_ready_symbol"] = str(symbol)
        STATS["v534_last_live_ready_score"] = float(score)
        STATS["v534_last_live_ready_ts"] = WALL_NOW()
        try:
            LifecycleTrace.record(trace_id, "LIVE_READY", {
                "score": float(score), "floor": float(min_score),
                "entry": float(entry), "sl": float(sl),
                "tp1": float(tp1), "tp2": float(tp2), "tp3": float(tp3),
            })
        except Exception:
            _v647_record_suppressed_exception()
        logger.info(
            f"[LIVE-READY] {symbol} score={float(score):.2f} floor={float(min_score):.2f} "
            f"entry={float(entry):.10g} sl={float(sl):.10g} "
            f"tp1={float(tp1):.10g} tp2={float(tp2):.10g} tp3={float(tp3):.10g} "
            f"family={_mode} style={_style}"
        )

        STATS["signals_queued"] += 1
        if bool(CONFIG.get("V646_EXECUTION_TRUTH_TELEMETRY_ENABLE", True)):
            STATS["v646_last_queue_symbol"] = str(symbol)
            STATS["v646_last_queue_ts"] = WALL_NOW()
            logger.info(
                f"[V646-QUEUE] {symbol} score={float(score):.2f} entry={float(entry):.10g} "
                f"sl={float(sl):.10g} tp1={float(tp1):.10g} tp2={float(tp2):.10g} "
                f"tp3={float(tp3):.10g} family={_mode} queue_commit=1"
            )
        # v4.5.21: queue is the commit point for symbol/candle throttles.
        try:
            if bool(CONFIG.get("V521_CANDLE_DEDUP_MARK_ON_QUEUE_ONLY", True)):
                CandleDedup.mark(_candle_dedup_key_deferred)
            if bool(CONFIG.get("V521_COOLDOWN_ARM_ON_QUEUE_ONLY", True)) and _sym_cd_mode == "post_microstruct":
                _sym_cd_sec_arm = float(CONFIG.get("SYMBOL_COOLDOWN_SEC", 0) or 0)
                if _sym_cd_sec_arm > 0:
                    COOLDOWNS.setdefault("symbol_scan", {})[symbol] = MONO_NOW()
        except Exception as _q_commit_e:
            logger.debug(f"[V521] queue throttle commit suppressed {symbol}: {_q_commit_e}")
        try:
            V423Funnel.note_stage("Q")
        except Exception:
            _v647_record_suppressed_exception()
        try:
            _qfam = _V457_FAMILY_SYMBOL_MAP.get(str(symbol))
            if _qfam:
                _V456_EVENTS.add("family_queued", {"symbol": str(symbol), "family": _qfam})
        except Exception:
            _v647_record_suppressed_exception()
        StarvationGuard.funnel_invariant_check()

        # V700 FINAL TELEGRAM COMMIT: Telegram is observational only; the
        # canonical queue has already committed the opportunity and exchange
        # acceptance/fill remains a separate execution step below.
        try:
            if bool(CONFIG.get("V700_TELEGRAM_FINAL_ONLY", True)):
                OpportunityTelegramNotifier.notify_canonical(
                    symbol=symbol, candle_ts=candle_ts, score=float(score),
                    floor=float(min_score), family=str(opp.get("family", "PULLBACK")),
                    mode=_mode, style=_style, entry=float(entry), sl=float(sl),
                    tp1=float(tp1), tp2=float(tp2), tp3=float(tp3),
                    rr1=float((tp1-entry)/max(entry-sl,1e-12)),
                    rr2=float((tp2-entry)/max(entry-sl,1e-12)), rr3=float((tp3-entry)/max(entry-sl,1e-12)),
                    regime=regime, local=str(local_regime or ""),
                    phase=str(opp.get("market_phase", market_data.get("market_phase", "")) or ""),
                    features={
                        **dict(opp or {}), "htf_strength": htf_strength,
                        "volume_ratio": volume_ratio,
                        "rs_5m": rs_score_val / 100.0 if rs_score_val is not None and abs(float(rs_score_val)) > 1.5 else rs_score_val,
                        "chase_atr": opp.get("chase_atr", 0.0),
                        "liquidity_tier": tier, "tier": tier,
                    },
                    breakdown=breakdown, execution_ready=True,
                )
                STATS["v700_final_telegram_alerts"] = int(STATS.get("v700_final_telegram_alerts", 0) or 0) + 1
        except Exception as _v700_tg_can_e:
            logger.warning("[V700-TG] final opportunity hook failed %s: %s", symbol, _v700_tg_can_e)

        try:
            _v540_lr_ctx = _v540_candidate_ctx(preferred_candidate, {
                "score": float(score),
                "htf": float(htf_strength),
                "vol": float(volume_ratio or 0.0),
                "rs": float(rs_score_val or 0.0),
                "chase": float(max(0.0, (float(entry) - float(opp.get("zone_ref", entry))) / max(float(atr_val), 1e-9))),
                "tier": str(tier),
                "family": str(_mode),
            })
            if _v540_is_elite(_v540_lr_ctx):
                _v540_live_ready_alert(
                    symbol, float(score), str(_mode), float(entry), float(sl),
                    float(tp1), float(tp2), float(tp3), _v540_lr_ctx
                )
        except Exception:
            _v647_record_suppressed_exception()

        # ---- Submit ----
        async with HandoffOwnership.lock_for(symbol):
            ok, oid, fill_px = await OrderExecutor.submit_entry(
                exchange, symbol, sd.quantity_asset, entry,
                is_paper=bool(CONFIG["PAPER_TRADING_MODE"]),
                trace_id=trace_id,
                intent_context={
                    "planned_entry":float(entry), "planned_sl":float(sl),
                    "planned_tp1":float(tp1), "planned_tp2":float(tp2),
                    "planned_tp3":float(tp3 or 0.0),
                    "family":str(getattr(preferred_candidate, "family", "") or opp.get("family") or _mode or ""),
                    "strategy_mode":str(_mode or ""), "score":float(score),
                    "strategy_style":str(_style or ""),
                    "timeframe_profile":str(getattr(preferred_candidate, "timeframe_profile", "") or market_data.get("timeframe_profile", "UNKNOWN")),
                    "htf_strength":float(htf_strength or 0.0),
                })
            if not ok:
                # v4.5.33: OrderExecutor already records the exact send-fail
                # taxonomy and increments signals_failed_send. Do not double-
                # count it or overwrite the root cause with a generic label.
                _send_reason = str(STATS.get("last_send_fail_reason", "unknown") or "unknown")
                record_rejection(
                    trace_id, symbol, "execution",
                    f"submit_failed:{_send_reason}", "submit",
                    ctx={"send_reason": _send_reason}
                )
                # Balance rejection is deterministic for THIS order, but the
                # account may have changed since the preceding pre-send fetch.
                # Refresh canonical balance truth once so subsequent ranked
                # candidates are not needlessly starved by stale balance state.
                # v4.5.35: queue/candle throttles are provisional until an
                # actual exchange send succeeds. If submission fails before
                # acceptance, roll back only the provisional scan-throttles so
                # the bounded balance recovery can re-evaluate the same candle.
                if bool(CONFIG.get("V535_ROLLBACK_QUEUE_THROTTLES_ON_SEND_FAIL", True)):
                    try:
                        _kd = locals().get("_candle_dedup_key_deferred")
                        if _kd:
                            CandleDedup._seen.pop(_kd, None)
                        if str(CONFIG.get("SYMBOL_COOLDOWN_MODE", "post_microstruct")).lower() == "post_microstruct":
                            _scd = COOLDOWNS.setdefault("symbol_scan", {})
                            _scd.pop(symbol, None)
                        STATS["v535_queue_throttle_rollbacks"] = int(STATS.get("v535_queue_throttle_rollbacks",0) or 0) + 1
                    except Exception as _rb_e:
                        logger.debug(f"[V535] queue-throttle rollback suppressed {symbol}: {_rb_e}")
                if bool(CONFIG.get("V535_EXECUTION_TELEMETRY_ENABLE", True)):
                    STATS["v535_send_failures"] = int(STATS.get("v535_send_failures",0) or 0) + 1
                    STATS["v535_last_send_fail_symbol"] = str(symbol)
                    STATS["v535_last_send_fail_reason"] = str(_send_reason)
                    STATS["v535_last_send_fail_ts"] = WALL_NOW()

                if _send_reason == "balance" and bool(CONFIG.get("V533_BALANCE_RECHECK_ON_SEND_FAIL", True)):
                    try:
                        _bal, _bst = await BalanceReconciler.fetch(exchange)
                        STATS["v533_balance_rechecks"] = int(STATS.get("v533_balance_rechecks", 0) or 0) + 1
                        STATS["v533_last_balance_recheck_state"] = str(_bst)
                        STATS["v533_last_balance_recheck_free"] = float(_bal or 0.0)
                    except Exception as _bre:
                        STATS["v533_balance_recheck_errors"] = int(STATS.get("v533_balance_recheck_errors", 0) or 0) + 1
                        logger.warning(f"[V533-BalanceRecovery] {symbol} recheck failed: {_bre}")
                elif _send_reason == "network_timeout":
                    # Never blindly repeat create_market_buy_order: timeout is
                    # ambiguous with respect to whether the exchange accepted it.
                    STATS["v533_ambiguous_send_blocked"] = int(STATS.get("v533_ambiguous_send_blocked", 0) or 0) + 1
                return None

            # Reconciliation is the only authority for filled quantity. The planned
            # sizing amount is not the fill amount (notably on partial maker/market fills).
            _entry_fill_context = _v553_take_buy_fill_context(oid)
            _requested_qty_asset = float(sd.quantity_asset)
            _actual_qty_asset = float((_entry_fill_context or {}).get("net_filled_qty") or (_entry_fill_context or {}).get("filled_qty") or 0.0)
            if bool(CONFIG.get("PAPER_TRADING_MODE")):
                _actual_qty_asset = _requested_qty_asset
            if not math.isfinite(_actual_qty_asset) or _actual_qty_asset <= 0.0:
                live_entries_block(
                    f"successful_buy_missing_fill_quantity_{symbol}",
                    where="SignalBuilder.fill_adoption",
                )
                _entry_fill_context = dict(_entry_fill_context or {})
                _entry_fill_context["fill_quantity_unverified"] = True
                _entry_fill_context["entry_reconcile_required"] = True
                _entry_fill_context["order_ids"] = list(_entry_fill_context.get("order_ids") or ([str(oid)] if oid else []))
                _intent_id = str(_entry_fill_context.get("execution_intent_id") or "")
                if not _intent_id and oid:
                    try: _intent_id = await asyncio.to_thread(DBManager.find_execution_intent_id_for_order, str(oid))
                    except Exception: _intent_id = ""
                if not bool(CONFIG.get("PAPER_TRADING_MODE", False)) and oid:
                    # Zero known fills is not zero exposure when venue state is ambiguous.
                    # Store a pending order record and let the reconciliation loop query it;
                    # do not fabricate a filled quantity or place a stop sized from the plan.
                    _pending_px = float(fill_px or entry or 0.0)
                    _pending_sl = float(sl or 0.0)
                    _pending = TradeState(
                        symbol=symbol, trace_id=str(trace_id), entry=_pending_px,
                        planned_entry=float(entry or _pending_px), effective_entry=_pending_px,
                        original_sl=_pending_sl, current_sl=_pending_sl,
                        tp1=0.0, tp2=0.0, tp3=0.0, target_plan_pending=True,
                        status="entry_pending_reconcile", entry_filled=False, entry_fill_price=0.0,
                        entry_fill_amount=0.0, entry_requested_amount=_requested_qty_asset,
                        entry_intent_id=_intent_id, entry_order_ids=list(_entry_fill_context.get("order_ids") or [str(oid)]),
                        entry_reconcile_required=True, fill_reconciliation_status="UNKNOWN",
                        position_size_asset=0.0, remaining_position=0.0,
                        is_paper=False, execution_mode="LIVE", entry_time=datetime.now(timezone.utc).isoformat(),
                        last_update=datetime.now(timezone.utc).isoformat(),
                        signal_family=str(opp.get("family") or ""), strategy_mode=str(_mode or ""),
                        strategy_style=str(_style or "SCALP"),
                        timeframe_profile=str(((getattr(preferred_candidate, "features_snapshot", {}) or {}).get("timeframe_profile")
                                               or getattr(preferred_candidate, "timeframe_profile", "")
                                               or (_V701_3_STRATEGY_CONTRACTS.get(str(_mode or "").upper(), {}) or {}).get("tf", ""))),
                        strategy_regime=str(regime or ""), score=float(score),
                    )
                    ACTIVE_TRADES[symbol] = _pending
                    try:
                        await DBManager.asave_trade_snapshot(_pending)
                    except Exception as _pending_save_exc:
                        live_entries_block(f"pending_execution_snapshot_failed_{symbol}", where="SignalBuilder.fill_adoption")
                        logger.critical("[ENTRY-ADOPTION] pending execution could not be persisted %s: %s", symbol, _pending_save_exc)
                    logger.critical(
                        "[ENTRY-ADOPTION] %s order outcome remains UNKNOWN id=%s; zero-quantity pending state stored, "
                        "no fabricated fill and no duplicate BUY permitted",
                        symbol, oid,
                    )
                    return _pending
                # No authoritative live order identity means we cannot safely infer or size exposure.
                # The durable execution-intent journal remains open and holds the entry gate.
                logger.critical("[ENTRY-ADOPTION] %s has no authoritative fill quantity/order identity; keeping entries blocked", symbol)
                return None
            _fill_qty_ratio = _actual_qty_asset / max(_requested_qty_asset, 1e-12)
            if bool((_entry_fill_context or {}).get("partial_fill", False)) or bool((_entry_fill_context or {}).get("entry_reconcile_required", False)):
                live_entries_block(
                    f"partial_or_unresolved_buy_fill_adopted_{symbol}",
                    where="SignalBuilder.partial_fill_adoption",
                )
                STATS["v702_partial_fill_positions_adopted"] = int(
                    STATS.get("v702_partial_fill_positions_adopted", 0) or 0
                ) + 1
            if _fill_qty_ratio > 1.005:
                live_entries_block(
                    f"oversized_buy_fill_adopted_{symbol}",
                    where="SignalBuilder.oversized_fill_adoption",
                )
            if bool(CONFIG.get("V646_EXECUTION_TRUTH_TELEMETRY_ENABLE", True)):
                STATS["v646_last_live_symbol"] = str(symbol)
                STATS["v646_last_live_ts"] = WALL_NOW()
                STATS["v646_last_live_order_id"] = str(oid or "")
                logger.info(
                    f"[V646-LIVE] {symbol} order_id={oid} fill={float(fill_px):.10g} "
                    f"qty={float(_actual_qty_asset):.10g} requested_qty={float(_requested_qty_asset):.10g} score={float(score):.2f} live=1"
                )
            # v4.5.25: keep opportunity pending until exchange SL verification.
            try:
                _sfam = _V457_FAMILY_SYMBOL_MAP.get(str(symbol))
                if _sfam:
                    _V456_EVENTS.add("family_sent", {"symbol": str(symbol), "family": _sfam})
            except Exception:
                _v647_record_suppressed_exception()
            try:
                V423Funnel.note_stage("S")
                _V420State.note_s()
                V422StarvationAlerter.note_send()
            except Exception:
                _v647_record_suppressed_exception()
            FailedSendCircuitBreaker.clear(symbol)
            DailyCircuitBreaker.register_trade()
            # v4.0.7 TWEAK — arm execution cooldown after a successful send so
            # rapid duplicate submissions on the same symbol are throttled.
            try:
                COOLDOWNS.setdefault("execution", {})[symbol] = MONO_NOW()
            except Exception:
                _v647_record_suppressed_exception()

            # ---- v4.0.6 FIX B — Post-fill level recalibration ----
            # Rebuild SL / TP1 / TP2 / TP3 from the REAL fill_px so exit
            # levels are coherent with what actually executed. If the drift
            # between planned_entry and fill_px exceeds FILL_DRIFT_ABORT_PCT,
            # abort the trade immediately via unified finalization to keep
            # accounting invariants intact.
            planned_entry = float(entry)
            planned_sl = float(sl)
            planned_tp1 = float(tp1)
            planned_tp2 = float(tp2)
            planned_tp3 = float(tp3) if tp3 is not None else 0.0
            fill_drift_pct = abs(fill_px - planned_entry) / max(planned_entry, 1e-9) * 100.0
            abort_pct = float(CONFIG.get("FILL_DRIFT_ABORT_PCT", 0.75))
            if fill_drift_pct > abort_pct:
                STATS["fill_drift_aborts"] = int(STATS.get("fill_drift_aborts", 0) or 0) + 1
                STATS["v571_fill_drift_recalibrated"] = int(
                    STATS.get("v571_fill_drift_recalibrated", 0) or 0
                ) + 1
                logger.critical(
                    f"[V571-Fill] {symbol} drift={fill_drift_pct:.4f}% > alert="
                    f"{abort_pct:.4f}% (planned={planned_entry:.6f} fill={fill_px:.6f}) "
                    "— keeping FILLED position; actual fill remains authoritative; "
                    "SL/TP will be recalibrated, NO immediate market SELL"
                )
                if bool(CONFIG.get("V571_FILL_DRIFT_IMMEDIATE_SELL_ENABLE", False)):
                    # Optional legacy/safety behavior is routed through the same
                    # centralized authority and therefore remains fail-closed.
                    live_entries_block(
                        f"fill_drift_emergency_disabled_by_default_{symbol}",
                        where="V571.fill_drift",
                    )

            # Fill drift is an entry-quality incident, not evidence that the fill
            # did not occur. Keep the filled position on the state/protection path.
            # Drift above the configured threshold blocks subsequent entries and
            # still re-anchors protection/targets to the authoritative fill.
            if fill_drift_pct > abort_pct:
                live_entries_block(
                    f"filled_entry_drift_requires_review_{symbol}",
                    where="SignalBuilder.post_fill_drift",
                )

            # Recalibrate levels around fill_px so the
            # geometry (SL distance, TP1/TP2/TP3 R-multiples) stays coherent
            # with the ACTUAL fill instead of the planned entry.
            sl_dist = max(planned_entry - planned_sl, 1e-9)  # positive (long-only)
            # Preserve the exact post-PreSend TP offsets (including SR ceilings and
            # a fee rescue that passed the same hard gates) across fill re-anchoring.
            # Rebuilding from ExitProfile here used to silently erase SR caps/rescue.
            _target_plan_pending = False
            try:
                _post_fill_geom = _v702_reanchor_targets_after_fill(
                    exchange=exchange, symbol=symbol, planned_entry=planned_entry,
                    fill_entry=float(fill_px), planned_sl=planned_sl,
                    planned_tp1=planned_tp1, planned_tp2=planned_tp2, planned_tp3=planned_tp3,
                    sr_context=_sr_target_ctx,
                )
                if not bool(_post_fill_geom.get("ok", False)):
                    raise ValueError(str(_post_fill_geom.get("reason") or "post_fill_target_geometry_invalid"))
                recal_sl = float(_post_fill_geom["sl"])
                recal_tp1 = float(_post_fill_geom["tp1"])
                recal_tp2 = float(_post_fill_geom["tp2"])
                recal_tp3 = float(_post_fill_geom["tp3"])
                STATS["v702_post_fill_target_geometry_passes"] = int(
                    STATS.get("v702_post_fill_target_geometry_passes", 0) or 0
                ) + 1
                LifecycleTrace.record(trace_id, "V702_POST_FILL_TARGET_GEOMETRY", dict(_post_fill_geom))
            except Exception as _post_fill_geom_exc:
                # An entry may already be filled. Never leave that position without
                # a TradeState/protection path; stop further entries and use the
                # legacy profile geometry only as an explicitly flagged management
                # fallback for this already-open position. No new entry is authorized.
                live_entries_block(
                    f"post_fill_sr_target_geometry_invalid_{symbol}",
                    where="SignalBuilder.post_fill_target_geometry",
                )
                STATS["v702_post_fill_target_geometry_fallbacks"] = int(
                    STATS.get("v702_post_fill_target_geometry_fallbacks", 0) or 0
                ) + 1
                logger.critical(
                    "[V702-SR-TARGETS] post-fill geometry fallback for %s: %s; "
                    "entries blocked, existing fill still receives managed state",
                    symbol, _post_fill_geom_exc,
                )
                _emergency_post_fill = _v702_post_fill_emergency_targets(
                    exchange=exchange, symbol=symbol, planned_entry=planned_entry,
                    fill_entry=float(fill_px), planned_sl=planned_sl,
                    planned_tp1=planned_tp1, planned_tp2=planned_tp2, planned_tp3=planned_tp3,
                    tp1_rr=float(_ep.tp1_rr), tp2_rr=float(_ep.tp2_rr), tp3_rr=float(_ep.tp3_rr),
                    sr_context=_sr_target_ctx,
                )
                if bool(_emergency_post_fill.get("ok", False)):
                    recal_sl = float(_emergency_post_fill["sl"])
                    recal_tp1 = float(_emergency_post_fill["tp1"])
                    recal_tp2 = float(_emergency_post_fill["tp2"])
                    recal_tp3 = float(_emergency_post_fill["tp3"])
                    STATS["v702_post_fill_emergency_management_only"] = int(
                        STATS.get("v702_post_fill_emergency_management_only", 0) or 0
                    ) + 1
                    if bool(_emergency_post_fill.get("sr_buffer_exception", False)):
                        STATS["v702_post_fill_sr_buffer_exception"] = int(
                            STATS.get("v702_post_fill_sr_buffer_exception", 0) or 0
                        ) + 1
                    logger.critical(
                        "[V702-SR-TARGETS] emergency management-only geometry active for %s: %s; "
                        "no new entry authorized; hard physical resistance ceiling retained",
                        symbol, _emergency_post_fill.get("reason", "unknown"),
                    )
                    LifecycleTrace.record(trace_id, "V702_POST_FILL_EMERGENCY_TARGET_GEOMETRY", dict(_emergency_post_fill))
                else:
                    # Last-resort geometry is permitted only when the fill has no
                    # overhead physical resistance to protect. If overhead SR exists
                    # and a valid capped ladder cannot be built, abort state creation
                    # rather than silently write targets through resistance.
                    _remaining_overhead = []
                    for _lv in (_sr_target_ctx.get("resistance_levels") or []):
                        try:
                            if float(_lv) > float(fill_px): _remaining_overhead.append(float(_lv))
                        except Exception: pass
                    if bool(_sr_target_ctx.get("enabled", False)) and _remaining_overhead:
                        # The fill is real even when no defensible TP ladder exists.
                        # Keep the position under its stop with targets explicitly
                        # pending; never invent targets through a physical ceiling.
                        live_entries_block(
                            f"post_fill_sr_geometry_unrecoverable_{symbol}",
                            where="SignalBuilder.post_fill_target_geometry",
                        )
                        _target_plan_pending = True
                        recal_sl = float(fill_px) - max(float(sl_dist), float(fill_px) * 0.004)
                        _ok_sl, _fixed_sl, _sl_reason = _v702_price_to_precision(
                            exchange, symbol, float(recal_sl)
                        )
                        if _ok_sl and 0 < float(_fixed_sl) < float(fill_px):
                            recal_sl = float(_fixed_sl)
                        recal_tp1 = 0.0
                        recal_tp2 = 0.0
                        recal_tp3 = 0.0
                        STATS["v702_target_plan_pending_positions"] = int(
                            STATS.get("v702_target_plan_pending_positions", 0) or 0
                        ) + 1
                        logger.critical(
                            "[V702-SR-TARGETS] %s filled position adopted in MANAGEMENT_ONLY "
                            "mode: valid SR-capped target ladder unavailable; SL remains mandatory; "
                            "no TP order or new entry is authorized",
                            symbol,
                        )
                    else:
                        recal_sl = float(fill_px) - sl_dist
                        recal_tp1 = float(fill_px) + float(_ep.tp1_rr) * sl_dist
                        recal_tp2 = float(fill_px) + float(_ep.tp2_rr) * sl_dist
                        recal_tp3 = float(fill_px) + float(_ep.tp3_rr) * sl_dist
                    for _nm in ("recal_sl", "recal_tp1", "recal_tp2", "recal_tp3"):
                        _ok_px, _px, _why_px = _v702_price_to_precision(exchange, symbol, float(locals()[_nm]))
                        if _ok_px:
                            if _nm == "recal_sl": recal_sl = float(_px)
                            elif _nm == "recal_tp1": recal_tp1 = float(_px)
                            elif _nm == "recal_tp2": recal_tp2 = float(_px)
                            else: recal_tp3 = float(_px)
                    if not (0 < recal_sl < float(fill_px) < recal_tp1 < recal_tp2 < recal_tp3):
                        recal_sl = min(float(recal_sl), float(fill_px) * 0.99)
                        recal_tp1 = float(fill_px) + max(sl_dist, float(fill_px) * 0.001)
                        recal_tp2 = recal_tp1 + max(sl_dist, float(fill_px) * 0.001)
                        recal_tp3 = recal_tp2 + max(sl_dist, float(fill_px) * 0.001)
            if fill_drift_pct > 0:
                logger.info(
                    f"[Fill] {symbol} recalibrated from fill_px={fill_px:.6f} "
                    f"(drift={fill_drift_pct:.4f}%): SL {planned_sl:.6f}->{recal_sl:.6f} "
                    f"TP1 {planned_tp1:.6f}->{recal_tp1:.6f}"
                )

            # V702 FINAL: bind the immutable post-fill canonical exit contract once.
            # Protection/exits may move dynamic current_sl later, but they do not
            # reinterpret the entry/TP geometry from a second policy source.
            _canonical_exit_snapshot = (
                {} if _target_plan_pending else _v702_make_exit_snapshot(
                    final_entry=fill_px, final_sl=recal_sl,
                    final_tp1=recal_tp1, final_tp2=recal_tp2, final_tp3=recal_tp3,
                    exit_profile=_ep, source="FINAL_BUILDER_FILL_RECONCILIATION", fill_px=fill_px,
                )
            )

            # V702 R2: bind the exact post-fill structural thesis-failure context
            # once. EXIT-ONLY provenance; it cannot authorize an entry.
            _v702_struct_inv_ctx = _v702_build_structural_invalidation_context(
                preferred_candidate, market_data, _mode, fill_px, recal_sl, atr_val
            )

            # Build trade state (v4.0.6 FIX B — levels now derived from fill_px)
            trade = TradeState(
                symbol=symbol, trace_id=trace_id,
                entry=fill_px, planned_entry=planned_entry, effective_entry=fill_px,
                original_sl=recal_sl, current_sl=recal_sl,
                tp1=recal_tp1, tp2=recal_tp2, tp3=recal_tp3,
                target_plan_pending=bool(_target_plan_pending),
                status="entry_filled",
                entry_filled=True, entry_fill_price=fill_px,
                entry_fill_amount=_actual_qty_asset,
                position_size_asset=_actual_qty_asset,
                remaining_position=_actual_qty_asset,
                entry_order_ids=list((_entry_fill_context or {}).get("order_ids") or ([str(oid)] if oid else [])),
                entry_intent_id=str((_entry_fill_context or {}).get("execution_intent_id") or ""),
                entry_requested_amount=_requested_qty_asset,
                entry_fill_cost_usdt=float((_entry_fill_context or {}).get("fill_cost_estimate") or (_actual_qty_asset * float(fill_px))),
                entry_fill_fees=list((_entry_fill_context or {}).get("fee_records") or []),
                entry_reconcile_required=bool((_entry_fill_context or {}).get("entry_reconcile_required", False)),
                fill_reconciliation_status=("UNVERIFIED" if (_entry_fill_context or {}).get("fill_quantity_unverified") else ("RECONCILE_PENDING" if (_entry_fill_context or {}).get("entry_reconcile_required") else ("PARTIAL" if (_entry_fill_context or {}).get("partial_fill") else "CONFIRMED"))),
                is_paper=bool(CONFIG["PAPER_TRADING_MODE"]),
                execution_mode="LIVE" if not CONFIG["PAPER_TRADING_MODE"] else "PAPER",
                atr=atr_val,
                risk_amount_usdt=sd.target_risk_usdt * _fill_qty_ratio,
                effective_risk_usdt=sd.effective_risk_usdt * _fill_qty_ratio,
                effective_risk_pct=(sd.effective_risk_usdt * _fill_qty_ratio) / max(sd.balance_free_usdt, 1e-9) * 100.0,
                size_cap_reason=(str(sd.cap_reason or "") + ("|actual_fill_ratio" if abs(_fill_qty_ratio - 1.0) > 1e-9 else "")),
                final_notional_before_qty=sd.raw_position_value * _fill_qty_ratio,
                final_notional_after_caps=sd.notional_after_caps * _fill_qty_ratio,
                entry_time=datetime.now(timezone.utc).isoformat(),
                last_update=datetime.now(timezone.utc).isoformat(),
                entry_filled_mono_ts=MONO_NOW(),
                score=score, signal_class=sig_class,
                signal_family=opp.get("family", ""),
                zone_quality_class=zone_class,
                strategy_mode=_mode, strategy_style=_style,
                timeframe_profile=str(_contract_tf
                                       or (_V701_3_STRATEGY_CONTRACTS.get(str(_mode or "").upper(), {}) or {}).get("tf", "")
                                       or ((getattr(preferred_candidate, "features_snapshot", {}) or {}).get("timeframe_profile"))
                                       or getattr(preferred_candidate, "timeframe_profile", "")),
                strategy_regime=str(regime or ""), strategy_session_bucket=_strategy_session,
                exit_profile=asdict(_ep),
                canonical_exit_snapshot=_canonical_exit_snapshot,
                structural_invalidation_armed=bool(_v702_struct_inv_ctx.get("armed", False)),
                structural_invalidation_reference=float(_v702_struct_inv_ctx.get("reference", 0.0) or 0.0),
                structural_invalidation_trigger=float(_v702_struct_inv_ctx.get("trigger", 0.0) or 0.0),
                structural_invalidation_source=str(_v702_struct_inv_ctx.get("source", "") or ""),
                structural_invalidation_context=dict(_v702_struct_inv_ctx),
                rescue_context={
                    "level": int(_v45_rescue_level()),
                    "lane": (
                        "fee_rescue" if bool(getattr(sd, "fee_target_rescued", False)) else
                        "near_miss" if bool(opp.get("near_miss_recovered", False)) else
                        str((opp.get("features_snapshot") or {}).get("rescue_lane", "ordinary")) if isinstance(opp.get("features_snapshot"), dict) else "ordinary"
                    ),
                    "floor_at_entry": float(GlobalOpportunityArbiter._effective_min_score()) if "GlobalOpportunityArbiter" in globals() else float(CONFIG.get("V45_SCORE_BASE", 0.54)),
                    "strategy_mode": str(_mode or ""),
                    "captured_at": WALL_NOW(),
                },
            )
            ACTIVE_TRADES[symbol] = trade
            # A filled BUY must never be silent while we attempt to install its
            # stop. This is distinct from the later protection-confirmed event.
            _fill_reconcile_state = str(getattr(trade, "fill_reconciliation_status", "CONFIRMED") or "CONFIRMED").upper()
            _fill_notice_event = (
                "ENTRY FILL RECONCILIATION PENDING — PROTECTION PENDING"
                if bool(getattr(trade, "entry_reconcile_required", False)) or _fill_reconcile_state in {"UNVERIFIED", "RECONCILE_PENDING", "PARTIAL"}
                else "ENTRY FILLED — PROTECTION PENDING"
            )
            OpportunityTelegramNotifier.schedule_entry_event(
                trade, _fill_notice_event, protection="PENDING",
                extra=f"Fill reconciliation: {_fill_reconcile_state}. Exchange-stop protection is still being verified."
            )
            _fill_mode = "PAPER" if bool(getattr(trade, "is_paper", False)) else "LIVE"
            _fill_style = str(getattr(trade, "strategy_style", "SCALP") or "SCALP").upper()
            _fill_strategy = str(getattr(trade, "strategy_mode", "") or "UNKNOWN").upper()
            _fill_tf = str(getattr(trade, "timeframe_profile", "") or "UNKNOWN").upper()
            STATS[f"v702_entry_filled_style.{_fill_mode}.{_fill_style}"] = int(
                STATS.get(f"v702_entry_filled_style.{_fill_mode}.{_fill_style}", 0) or 0
            ) + 1
            STATS[f"v702_entry_filled_mode.{_fill_mode}.{_fill_strategy}"] = int(
                STATS.get(f"v702_entry_filled_mode.{_fill_mode}.{_fill_strategy}", 0) or 0
            ) + 1
            logger.info(
                "[STRATEGY-FILLED] mode=%s symbol=%s execution=%s style=%s tf=%s score=%.2f trace=%s order_id=%s",
                _fill_strategy, symbol, _fill_mode, _fill_style, _fill_tf, float(score), str(trace_id), str(oid or "-")
            )
            if getattr(trade, "entry_intent_id", ""):
                try:
                    await DBManager.aupdate_execution_intent(
                        trade.entry_intent_id, "FILL_ADOPTED",
                        venue_order_id=str(oid or ""),
                        details={"trade_id":str(trade.trace_id),"net_position_qty":float(trade.remaining_position),
                                 "entry_price":float(trade.entry),"target_plan_pending":bool(trade.target_plan_pending)},
                    )
                except Exception as _fill_adopt_persist_exc:
                    # In-memory exposure is already authoritative. A failed adoption
                    # journal write must not unwind the builder before the immediate SL
                    # attempt; latch new entries, preserve the trade, and keep reconciling.
                    live_entries_block(f"fill_adoption_intent_persist_failed_{symbol}", where="SignalBuilder.fill_adoption")
                    STATS["v702_fill_adoption_persist_failures"] = int(
                        STATS.get("v702_fill_adoption_persist_failures", 0) or 0
                    ) + 1
                    logger.critical("[ENTRY-ADOPTION] %s fill adopted in memory; intent state write failed, continuing to protection: %s",
                                    symbol, type(_fill_adopt_persist_exc).__name__)
            try:
                _pipe_metrics = globals().get("V702PipelineMetrics")
                if _pipe_metrics is not None:
                    _pipe_metrics.record_current("TRADE_STATE_CREATED", symbol=symbol,
                        candidate_key=_pipe_metrics.current_candidate_key(),
                        details={"entry":float(trade.entry),"sl":float(trade.current_sl),
                                 "tp1":float(trade.tp1),"tp2":float(trade.tp2),"tp3":float(trade.tp3),
                                 "order_id":str(oid or "")})
            except Exception:
                _v647_record_suppressed_exception()
            LifecycleTrace.record(trace_id, "SENT",
                                  {"order_id": oid, "qty": _actual_qty_asset,
                                   "requested_qty": _requested_qty_asset,
                                   "px": fill_px,
                                   "planned_entry": planned_entry,
                                   "fill_drift_pct": fill_drift_pct,
                                   "recal_sl": recal_sl,
                                   "recal_tp1": recal_tp1,
                                   "recal_tp2": recal_tp2,
                                   "recal_tp3": recal_tp3})

            # Durable exposure snapshot before the protection routine can yield or fail.
            # A storage failure blocks future entries but we still attempt to arm protection now.
            try:
                await DBManager.asave_trade_snapshot(trade)
            except Exception as _preprotect_persist_exc:
                live_entries_block(f"pre_protection_trade_persist_failed_{symbol}", where="SignalBuilder.pre_protection_snapshot")
                logger.critical("[ENTRY-ADOPTION] %s state is in memory but not durably stored; immediate protection continues: %s", symbol, _preprotect_persist_exc)

            # v4.5.25 CRITICAL: ENTRY_FILLED is not a protected LIVE trade
            # until place_sl() returns True after its own post-create verification.
            sl_ok, sl_oid = await OrderExecutor.place_sl(exchange, trade)
            _software_fallback_ok = (
                not sl_ok
                and bool(CONFIG.get("LIVE_ENTRY_ALLOW_SOFTWARE_SL_FALLBACK", True))
                and bool(getattr(trade, "software_sl_active", False))
                and str(getattr(trade, "sl_health_state", "")) in {"UNVERIFIED", "SOFTWARE_SL_ACTIVE"}
            )

            # v4.5.60: after a real BUY fill, native SL failure does NOT
            # cause an immediate SELL. Arm automatic software SL instead.
            if (not sl_ok
                    and str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() == "HYBRID_AUTO"
                    and bool(CONFIG.get("V560_AUTO_SL_ENABLE", True))):
                _v560_reason = str(
                    getattr(trade, "sl_failure_reason", "") or "exchange_sl_unverified"
                )
                if await _v560_arm_software_sl(trade, _v560_reason):
                    try:
                        _pipe_metrics = globals().get("V702PipelineMetrics")
                        if _pipe_metrics is not None:
                            _pipe_metrics.record_current("PROTECTED", symbol=symbol, details={"protection_mode":"SOFTWARE_SL_AUTO","reason":_v560_reason})
                    except Exception:
                        _v647_record_suppressed_exception()
                    STATS["signals_protected_software"] = int(
                        STATS.get("signals_protected_software", 0) or 0
                    ) + 1
                    OpportunityTelegramNotifier.schedule_entry_event(
                        trade, "ENTRY PROTECTED — SOFTWARE AUTO-SELL", protection="SOFTWARE AUTO-SELL",
                        extra="Native exchange stop was unavailable/unverified; software auto-sell is armed."
                    )
                    try:
                        _meta = OpportunityTelegramNotifier.pending_metadata(symbol, candle_ts)
                        _meta["execution_ready"] = True
                        _meta["protection_mode"] = "SOFTWARE_SL_AUTO"
                    except Exception:
                        _v647_record_suppressed_exception()
                    await _v702_a52_persist_protected_trade(trade, "SOFTWARE_SL_AUTO", str(oid or ""))
                    try:
                        OpportunityTelegramNotifier.mark_executed(symbol, candle_ts)
                    except Exception:
                        _v647_record_suppressed_exception()
                    return trade

                live_entries_block(
                    f"automatic_sl_arm_failed_{symbol}",
                    where="ExecutionFunnel.post_entry_sl_verify"
                )
                logger.critical(
                    f"[V560-PROTECT] {symbol}: BUY is filled but automatic software SL could not be armed; position remains a critical protection incident"
                )
                STATS["v702_entry_protection_failures"] = int(STATS.get("v702_entry_protection_failures", 0) or 0) + 1
                OpportunityTelegramNotifier.schedule_entry_event(
                    trade, "CRITICAL — ENTRY FILLED BUT STOP PROTECTION FAILED", protection="FAILED",
                    extra=f"Immediate manual intervention required. Reason: {_v560_reason}. New entries are blocked."
                )
                try:
                    _pipe_metrics = globals().get("V702PipelineMetrics")
                    if _pipe_metrics is not None:
                        _pipe_metrics.record_current("PROTECTION_FAILED", symbol=symbol, details={"reason":"automatic_sl_arm_failed", "trade_filled":True})
                except Exception:
                    _v647_record_suppressed_exception()
                try:
                    LifecycleTrace.record(trace_id, "PROTECTION_FAILED", {"symbol":symbol, "reason":"automatic_sl_arm_failed", "filled":True, "order_id":str(oid or "")})
                except Exception:
                    _v647_record_suppressed_exception()
                try:
                    OpportunityTelegramNotifier.mark_executed(symbol, candle_ts)
                except Exception:
                    _v647_record_suppressed_exception()
                # The position exists despite protection failure. Returning None here
                # falsely reported that no trade executed and could generate a wrong
                # blocked-opportunity notification; keep the actual state visible.
                return trade

            if _software_fallback_ok and not sl_ok:
                try:
                    _pipe_metrics = globals().get("V702PipelineMetrics")
                    if _pipe_metrics is not None:
                        _pipe_metrics.record_current("PROTECTED", symbol=symbol, details={"protection_mode":"SOFTWARE_SL_FALLBACK","reason":str(getattr(trade,"sl_failure_reason","") or "native_sl_unverified")})
                except Exception:
                    _v647_record_suppressed_exception()
                STATS["signals_protected_software"] = int(STATS.get("signals_protected_software", 0) or 0) + 1
                logger.critical(
                    f"[V556-PROTECT] {symbol} entry retained under SOFTWARE_SL_ONLY; "
                    "exchange-native stop was not certified. No immediate SELL."
                )
                OpportunityTelegramNotifier.schedule_entry_event(
                    trade, "ENTRY PROTECTED — SOFTWARE STOP", protection="SOFTWARE AUTO-SELL",
                    extra="Native exchange stop was unavailable/unverified; software stop is active."
                )
                try:
                    _meta = OpportunityTelegramNotifier.pending_metadata(symbol, candle_ts)
                    _meta["execution_ready"] = True
                    _meta["protection_mode"] = "SOFTWARE_SL_ONLY"
                except Exception:
                    _v647_record_suppressed_exception()
                await _v702_a52_persist_protected_trade(trade, "SOFTWARE_SL_ONLY", str(oid or ""))
                try:
                    OpportunityTelegramNotifier.mark_executed(symbol, candle_ts)
                except Exception:
                    _v647_record_suppressed_exception()
                return trade

            if not sl_ok:
                _unprotected_reason = str(getattr(trade, "sl_failure_reason", "") or "native_stop_unverified_without_fallback")
                live_entries_block(f"stop_protection_unverified_{symbol}", where="ExecutionFunnel.post_entry_sl_verify")
                STATS["v702_entry_protection_failures"] = int(STATS.get("v702_entry_protection_failures", 0) or 0) + 1
                logger.critical("[PROTECTION-UNVERIFIED] %s BUY fill exists but neither verified native SL nor active software stop is available; reason=%s", symbol, _unprotected_reason)
                OpportunityTelegramNotifier.schedule_entry_event(
                    trade, "CRITICAL — ENTRY FILLED BUT STOP PROTECTION FAILED", protection="FAILED",
                    extra=f"Immediate manual intervention required. Reason: {_unprotected_reason}. New entries are blocked."
                )
                try:
                    _pipe_metrics = globals().get("V702PipelineMetrics")
                    if _pipe_metrics is not None:
                        _pipe_metrics.record_current("PROTECTION_FAILED", symbol=symbol, details={"reason":_unprotected_reason, "trade_filled":True})
                except Exception:
                    _v647_record_suppressed_exception()
                try:
                    LifecycleTrace.record(trace_id, "PROTECTION_FAILED", {"symbol":symbol, "reason":_unprotected_reason, "filled":True, "order_id":str(oid or "")})
                except Exception:
                    _v647_record_suppressed_exception()
                try:
                    await DBManager.asave_trade_snapshot(trade)
                except Exception as _unprotected_persist_exc:
                    live_entries_block(f"unprotected_trade_persist_failed_{symbol}", where="ExecutionFunnel.protection_failure_snapshot")
                    logger.critical("[PROTECTION-UNVERIFIED] %s failed to persist the actual filled position: %s", symbol, type(_unprotected_persist_exc).__name__)
                try:
                    OpportunityTelegramNotifier.mark_executed(symbol, candle_ts)
                except Exception:
                    _v647_record_suppressed_exception()
                # A fill is not a no-execution outcome even when protection fails.
                return trade

            STATS["signals_protected"] += 1
            await _v702_a52_persist_protected_trade(trade, "NATIVE_SL_VERIFIED", str(sl_oid or ""))

            try:
                _meta = OpportunityTelegramNotifier.pending_metadata(symbol, candle_ts)
                _meta["execution_ready"] = True
            except Exception:
                _v647_record_suppressed_exception()
            OpportunityTelegramNotifier.schedule_entry_event(
                trade, "ENTRY PROTECTED — EXCHANGE STOP VERIFIED", protection="NATIVE EXCHANGE STOP VERIFIED",
                extra=f"Exchange stop verified @ {recal_sl:.10f}. Targets remain attached to the active trade state."
            )
            try:
                OpportunityTelegramNotifier.mark_executed(symbol, candle_ts)
            except Exception:
                _v647_record_suppressed_exception()
            return trade




# =============================================================================
#  v4.5.59 — SL MONITOR-ONLY / TARGET-ONLY POLICY
# =============================================================================

async def _v559_monitor_sl_only(trade: TradeState, current_price: float) -> str:
    """Monitor model SL and alert; NEVER submit or finalize a SELL."""
    if not bool(CONFIG.get("V559_SL_MONITOR_ENABLE", True)):
        return "disabled"
    try:
        entry = float(trade.entry)
        sl = float(trade.current_sl or trade.original_sl)
        cur = float(current_price)
        if entry <= 0 or sl <= 0 or cur <= 0 or entry <= sl:
            return "invalid_geometry"

        risk = max(entry - sl, 1e-12)
        r_now = (cur - entry) / risk
        distance_r = (cur - sl) / risk
        near_r = max(0.0, float(CONFIG.get("V559_SL_MONITOR_NEAR_R_MULT", 0.25)))

        if distance_r <= 0:
            state = "SL_BREACH"
        elif distance_r <= near_r:
            state = "SL_NEAR"
        else:
            state = "OK"

        trade.sl_monitor_mode = "ALERT_ONLY"
        trade.sl_monitor_last_state = state

        if state == "OK":
            return state

        now = MONO_NOW()
        cooldown = max(
            1.0,
            float(CONFIG.get("V559_SL_MONITOR_ALERT_COOLDOWN_SEC", 60.0)),
        )
        last = float(getattr(trade, "sl_monitor_last_alert_ts", 0.0) or 0.0)
        if last > 0 and (now - last) < cooldown:
            return state

        trade.sl_monitor_last_alert_ts = now

        if state == "SL_BREACH":
            trade.sl_monitor_breach_count = int(
                getattr(trade, "sl_monitor_breach_count", 0) or 0
            ) + 1
            STATS["v559_sl_breach_alerts"] = int(
                STATS.get("v559_sl_breach_alerts", 0) or 0
            ) + 1
            logger.critical(
                f"[V559-SL-MONITOR] {trade.symbol} SL BREACH observed "
                f"cur={cur:.10g} sl={sl:.10g} R={r_now:.3f} — NO SELL"
            )
            try:
                await TelegramDispatcher.enqueue(
                    f"🔴 <b>SL BREACH — MANUAL ACTION</b> {trade.symbol}\n"
                    f"Current: {cur:.10g} | Model SL: {sl:.10g} | R: {r_now:.2f}\n"
                    "<b>No automatic SELL was issued.</b> TARGET_ONLY remains active."
                )
            except Exception:
                _v647_record_suppressed_exception()
        else:
            STATS["v559_sl_near_alerts"] = int(
                STATS.get("v559_sl_near_alerts", 0) or 0
            ) + 1
            logger.warning(
                f"[V559-SL-MONITOR] {trade.symbol} SL NEAR "
                f"cur={cur:.10g} sl={sl:.10g} distance={distance_r:.3f}R — NO SELL"
            )
            try:
                await TelegramDispatcher.enqueue(
                    f"🟠 <b>SL NEAR</b> {trade.symbol}\n"
                    f"Current: {cur:.10g} | Model SL: {sl:.10g}\n"
                    f"Distance: {distance_r:.2f}R\n"
                    "No automatic SELL will be issued."
                )
            except Exception:
                _v647_record_suppressed_exception()
        return state
    except Exception as exc:
        logger.debug(f"[V559-SL-MONITOR] {getattr(trade,'symbol','?')}: {exc}")
        return "monitor_error"


async def _v559_activate_sl_failure_policy(
    exchange,
    trade: TradeState,
    reason: str,
    preferred_targets: Optional[Tuple[float, float, float]] = None,
) -> TradeState:
    """Compatibility policy router. HYBRID_AUTO is the production default."""
    policy = str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper()
    trade.sl_failure_reason = str(reason or "sl_failure")
    if preferred_targets:
        try:
            trade.tp1, trade.tp2, trade.tp3 = map(float, preferred_targets)
        except Exception:
            _v647_record_suppressed_exception()

    if policy == "LEGACY_EMERGENCY":
        await OrderExecutor.emergency_close(
            exchange, trade, f"entry_protection_failed:{reason}",
            exit_px=trade.entry
        )
        return trade

    if policy == "HYBRID_AUTO":
        armed = await _v560_arm_software_sl(trade, reason)
        if armed:
            trade.target_only_mode = False
            return trade

        live_entries_block(
            f"automatic_sl_arm_failed_{trade.symbol}",
            where="V560.activate_sl_failure_policy"
        )
        logger.critical(
            f"[V560-SL] {trade.symbol}: automatic software SL could not be armed; "
            "position remains owned and new entries are blocked."
        )
        try:
            await TelegramDispatcher.enqueue(
                f"🔴 <b>AUTO-SL ARM FAILED</b> {trade.symbol}\n"
                f"Reason: {trade.sl_failure_reason}\n"
                "No blind market SELL was issued; protection must be restored."
            )
        except Exception:
            _v647_record_suppressed_exception()
        return trade

    # v4.5.74: TARGET_ONLY remains available for LIMIT target management,
    # but automatic Software-SL protection is mandatory for a live position.
    trade.target_only_mode = True
    armed = False
    try:
        armed = bool(await _v560_arm_software_sl(trade, reason))
    except Exception as exc:
        logger.critical(f"[V574-SL] {trade.symbol}: software-SL arm exception: {exc}")
    if armed:
        trade.sl_monitor_mode = "AUTO_SELL"
        trade.sl_health_state = "SOFTWARE_SL_ACTIVE"
    else:
        trade.sl_monitor_mode = "ALERT_ONLY"
        trade.sl_health_state = "SOFTWARE_SL_ARM_FAILED"
        live_entries_block(
            f"software_sl_arm_failed_target_only_{trade.symbol}",
            where="V574.activate_sl_failure_policy"
        )
        logger.critical(
            f"[V574-SL] {trade.symbol}: software-SL could not be armed; "
            "position remains owned but NEW entries stay blocked."
        )
    try:
        await _v557_place_target_only_orders(exchange, trade)
    except Exception as exc:
        logger.critical(f"[V559-TARGET] {trade.symbol}: target placement failed: {exc}")
    live_entries_block(
        f"sl_failure_target_only_{trade.symbol}",
        where="V574.activate_sl_failure_policy"
    )
    return trade


async def _v559_recover_entries_after_target_exit(symbol: str) -> bool:
    """Proof-based clear after target-only position is demonstrably flat."""
    try:
        if symbol in ACTIVE_TRADES:
            return False
        if not LIVE_ENTRIES_BLOCKED.get("active"):
            return True
        reason = str(LIVE_ENTRIES_BLOCKED.get("reason") or "").lower()
        if str(symbol).lower() not in reason:
            return False
        if "sl_failure_target_only" not in reason:
            return False
        LIVE_ENTRIES_BLOCKED["active"] = False
        LIVE_ENTRIES_BLOCKED["reason"] = None
        LIVE_ENTRIES_BLOCKED["where"] = None
        LIVE_ENTRIES_BLOCKED["since"] = None
        STATS["v559_target_only_entry_block_recovered"] = int(
            STATS.get("v559_target_only_entry_block_recovered", 0) or 0
        ) + 1
        logger.info(f"[V559-RECOVERY] target-only position flat; entry block cleared for {symbol}")
        return True
    except Exception:
        return False



# v4.5.59 compatibility alias — callers from v4.5.57 still resolve safely.
_v557_enter_target_only_mode = _v559_activate_sl_failure_policy

# =============================================================================
#  v4.5.57 — TARGET-ONLY EXIT ENGINE
# =============================================================================

def _v557_safe_float(v: Any, default: float = 0.0) -> float:
    try:
        x = float(v)
        return x if math.isfinite(x) else default
    except Exception:
        return default


def _v557_target_attr(level: str) -> str:
    return {"TP1": "tp1_order_id", "TP2": "tp2_order_id", "TP3": "tp3_order_id"}[level]


def _v557_target_plan(trade: TradeState) -> List[Tuple[str, float, float]]:
    # Target distances are dynamic; exit weights remain the canonical 50/30/20.
    plan = [
        ("TP1", _v557_safe_float(getattr(trade, "tp1", 0.0)),
         _v557_safe_float(CONFIG.get("TP1_EXIT_PCT", 0.5))),
    ]
    if bool(CONFIG.get("ENABLE_RUNNER_MODE", True)):
        plan.append((
            "TP2", _v557_safe_float(getattr(trade, "tp2", 0.0)),
            _v557_safe_float(CONFIG.get("TP2_EXIT_PCT", 0.3)),
        ))
        if bool(CONFIG.get("SL_FAILURE_TARGET_ONLY_ALLOW_TP3", True)):
            plan.append((
                "TP3", _v557_safe_float(getattr(trade, "tp3", 0.0)),
                _v557_safe_float(CONFIG.get("RUNNER_KEEP_PCT_AT_TP3", 0.2)),
            ))
    else:
        plan.append((
            "TP2", _v557_safe_float(getattr(trade, "tp2", 0.0)),
            1.0 - _v557_safe_float(CONFIG.get("TP1_EXIT_PCT", 0.5)),
        ))

    status = str(getattr(trade, "status", "") or "")
    if status in {"tp1_hit", "be_moved", "trailing", "tp2_hit", "tp3_hit", "runner"} or bool(getattr(trade, "tp1_exit_completed", False)):
        plan = [x for x in plan if x[0] != "TP1"]
    if status in {"tp2_hit", "tp3_hit", "runner"} or bool(getattr(trade, "tp2_exit_completed", False)):
        plan = [x for x in plan if x[0] != "TP2"]
    if status == "tp3_hit":
        plan = [x for x in plan if x[0] != "TP3"]
    return plan


async def _v557_place_target_only_orders(exchange, trade: TradeState) -> int:
    """Install LIMIT SELL targets without duplicating reserved or ambiguous orders.

    Existing open target orders reserve their remaining quantity. An unknown
    response stops the batch immediately; there is no speculative retry and no
    later target is created until the prior outcome can be reconciled.
    """
    if not bool(CONFIG.get("SL_FAILURE_TARGET_ONLY_PLACE_LIMITS", True)):
        return 0
    if not bool(getattr(trade, "target_only_mode", False)):
        return 0
    if bool(getattr(trade, "target_recreate_disabled", False)):
        return 0
    if bool(getattr(trade, "target_order_ambiguous", False)):
        STATS["v557_target_place_blocked_ambiguous"] = int(
            STATS.get("v557_target_place_blocked_ambiguous", 0) or 0
        ) + 1
        return 0

    remaining = _v557_safe_float(getattr(trade, "remaining_position", 0.0))
    original = _v557_safe_float(getattr(trade, "position_size_asset", 0.0))
    if not math.isfinite(remaining) or not math.isfinite(original) or remaining <= 0 or original <= 0:
        trade.target_orders_active = False
        return 0

    placed = 0
    reserved = 0.0
    # Account for currently-open orders whose IDs already exist on the TradeState.
    # Do not infer available quantity from trade.remaining_position alone: on Spot,
    # assets committed to open limit sells can be unavailable for other exits.
    for _level in ("TP1", "TP2", "TP3"):
        _oid = getattr(trade, _v557_target_attr(_level), None)
        if not _oid:
            continue
        try:
            _existing = await safe_api_call(
                f"target_only_existing_reserve_{_level}",
                lambda _oid=_oid: exchange.fetch_order(_oid, trade.symbol),
                retry_safe=True,
            )
            if not isinstance(_existing, dict):
                raise ValueError("existing_target_response_not_mapping")
            _status = str(_existing.get("status") or "").strip().lower()
            if _status in {"open", "new", "pending", "partially_filled", "partial"}:
                _amount_raw = _existing.get("amount")
                _filled_raw = _existing.get("filled", 0.0)
                _amount = float(_amount_raw)
                _filled = float(_filled_raw or 0.0)
                if (not math.isfinite(_amount) or not math.isfinite(_filled)
                        or _amount <= 0.0 or _filled < 0.0 or _filled > _amount + max(1e-12, _amount * 1e-8)):
                    raise ValueError("existing_target_quantity_unverifiable")
                reserved += max(0.0, _amount - _filled)
            elif _status in {"closed", "filled", "complete", "canceled", "cancelled", "expired", "rejected"}:
                # Let the canonical reconciler apply terminal fill deltas/cancel policy
                # before any new target is considered. This invocation only reserves.
                trade.target_order_ambiguous = True
                trade.target_order_ambiguous_reason = "terminal_order_requires_reconcile"
                STATS["v557_target_terminal_reconcile_required"] = int(
                    STATS.get("v557_target_terminal_reconcile_required", 0) or 0
                ) + 1
                return 0
            else:
                raise ValueError("existing_target_status_unverifiable")
        except Exception as _existing_exc:
            trade.target_order_ambiguous = True
            trade.target_order_ambiguous_reason = "target_state_unknown"
            live_entries_block(
                f"target_order_state_unknown_{trade.symbol}",
                where="V557.target_order_reserve",
            )
            logger.critical(
                "[V557-TARGET] %s existing target %s state unknown; no additional targets created: %s",
                trade.symbol, _level, type(_existing_exc).__name__,
            )
            return 0

    if reserved >= remaining - max(1e-12, remaining * 1e-9):
        STATS["v557_target_all_remaining_reserved"] = int(
            STATS.get("v557_target_all_remaining_reserved", 0) or 0
        ) + 1
        return 0

    for level, target_px, frac in _v557_target_plan(trade):
        attr = _v557_target_attr(level)
        if getattr(trade, attr, None):
            continue

        px = _v557_safe_float(target_px)
        frac = max(0.0, _v557_safe_float(frac))
        target_total_qty = max(0.0, original * frac)
        already_filled_for_level = _v557_safe_float(
            (getattr(trade, "target_order_filled_qty", {}) or {}).get(level), 0.0
        )
        raw_qty = min(
            max(0.0, target_total_qty - already_filled_for_level),
            max(0.0, remaining - reserved),
        )
        if level == "TP2" and not bool(CONFIG.get("ENABLE_RUNNER_MODE", True)):
            raw_qty = max(0.0, remaining - reserved)
        if px <= 0 or raw_qty <= 0:
            continue

        qty_n, px_n, prec_err = await OrderExecutor._normalize_qty_price_with_reload(
            exchange, trade.symbol, raw_qty, px
        )
        if prec_err or qty_n is None or qty_n <= 0 or px_n is None or px_n <= 0:
            STATS["v557_target_order_precision_reject"] = int(
                STATS.get("v557_target_order_precision_reject", 0) or 0
            ) + 1
            logger.warning(
                f"[V557-TARGET] {trade.symbol} {level} precision rejected "
                f"qty={raw_qty:.10f} px={px:.10f} err={prec_err}"
            )
            continue

        try:
            # Unknown create results must never be retried or followed by other sells.
            order = await exchange.create_limit_sell_order(trade.symbol, qty_n, px_n)
            oid = str((order or {}).get("id") or "")
            if not oid:
                trade.target_order_ambiguous = True
                trade.target_order_ambiguous_reason = "venue_order_id_missing_after_create"
                live_entries_block(f"target_order_unknown_{trade.symbol}", where="V557.target_order_place")
                logger.critical(
                    f"[V557-TARGET] {trade.symbol} {level} LIMIT SELL returned no id; "
                    "batch stopped and no duplicate retry will be sent."
                )
                return placed

            setattr(trade, attr, oid)
            trade.target_order_filled_qty[level] = 0.0
            reserved += float(qty_n)
            placed += 1
            STATS["v557_target_orders_placed"] = int(STATS.get("v557_target_orders_placed", 0) or 0) + 1
            logger.info(
                f"[V557-TARGET] {trade.symbol} {level} LIMIT SELL placed "
                f"qty={qty_n:.10f} px={px_n:.10f} id={oid}"
            )
        except Exception as exc:
            STATS["v557_target_orders_failed"] = int(STATS.get("v557_target_orders_failed", 0) or 0) + 1
            # Only a strongly classified definitive rejection may allow trying a
            # different level; timeout/connection/unknown exceptions stop the batch.
            try:
                definitive_reject = bool(_v702_definitive_no_order_rejection(exc))
            except Exception:
                definitive_reject = False
            if definitive_reject:
                logger.warning("[V557-TARGET] %s %s definitive no-order rejection: %s", trade.symbol, level, type(exc).__name__)
                continue
            trade.target_order_ambiguous = True
            trade.target_order_ambiguous_reason = "target_creation_outcome_unknown"
            live_entries_block(f"target_order_unknown_{trade.symbol}", where="V557.target_order_place")
            logger.critical(
                f"[V557-TARGET] {trade.symbol} {level} LIMIT SELL outcome unknown: {exc}; "
                "batch stopped; reconcile before another target submission."
            )
            return placed

    if placed:
        trade.target_orders_active = True
        trade.target_orders_placed_ts = WALL_NOW()
        trade.target_orders_last_reconcile_ts = 0.0
    return placed


async def _v557_reconcile_target_only_orders(
    exchange, trade: TradeState, current_price: float = 0.0
) -> bool:
    """Reconcile target LIMIT SELL fills; finalize only when residual is zero."""
    if not bool(getattr(trade, "target_only_mode", False)):
        return False

    now = MONO_NOW()
    interval = max(
        0.0,
        _v557_safe_float(CONFIG.get("SL_FAILURE_TARGET_ONLY_RECONCILE_SEC", 1.0), 1.0),
    )
    last = _v557_safe_float(
        getattr(trade, "target_orders_last_reconcile_ts", 0.0)
    )
    if last > 0 and (now - last) < interval:
        return False
    trade.target_orders_last_reconcile_ts = now

    changed = False
    _all_target_states_verified = True
    for level in ("TP1", "TP2", "TP3"):
        attr = _v557_target_attr(level)
        oid = getattr(trade, attr, None)
        if not oid:
            continue
        try:
            order = await safe_api_call(
                f"target_only_fetch_{level}",
                lambda oid=oid: exchange.fetch_order(oid, trade.symbol),
                retry_safe=True,
            )
        except Exception as exc:
            _all_target_states_verified = False
            trade.target_order_ambiguous = True
            trade.target_order_ambiguous_reason = "target_state_unknown"
            live_entries_block(f"target_order_state_unknown_{trade.symbol}", where="V557.target_reconcile")
            logger.critical(
                f"[V557-TARGET] {trade.symbol} {level} order state unknown "
                f"id={oid}: {exc}; preserving id and refusing duplicate."
            )
            continue

        status = str((order or {}).get("status") or "").lower()
        if status not in ("open", "new", "pending", "partially_filled", "partial", "closed", "filled", "complete", "canceled", "cancelled", "rejected", "expired"):
            _all_target_states_verified = False
            trade.target_order_ambiguous = True
            trade.target_order_ambiguous_reason = "target_state_unknown"
            live_entries_block(f"target_order_state_unknown_{trade.symbol}", where="V557.target_reconcile")
            continue
        _filled_known = isinstance(order, dict) and "filled" in order and order.get("filled") is not None
        _amount_known = isinstance(order, dict) and "amount" in order and order.get("amount") is not None
        try:
            filled = float(order.get("filled")) if _filled_known else float("nan")
            amount = float(order.get("amount")) if _amount_known else float("nan")
        except (TypeError, ValueError, OverflowError):
            filled, amount = float("nan"), float("nan")
        previous = _v557_safe_float(
            (getattr(trade, "target_order_filled_qty", {}) or {}).get(level), 0.0
        )
        if (not math.isfinite(filled) or not math.isfinite(amount) or amount <= 0.0
                or filled < 0.0 or filled > amount + max(1e-12, amount * 1e-8)):
            _all_target_states_verified = False
            trade.target_order_ambiguous = True
            trade.target_order_ambiguous_reason = "target_fill_quantity_unverifiable"
            live_entries_block(f"target_fill_quantity_unknown_{trade.symbol}", where="V557.target_reconcile")
            logger.critical("[V557-TARGET] %s %s has missing/invalid fill accounting; keeping order identity and blocking new entries", trade.symbol, level)
            continue

        delta = max(0.0, filled - previous)
        if delta > 0:
            delta = min(
                delta,
                _v557_safe_float(getattr(trade, "remaining_position", 0.0)),
            )
            if delta > 0:
                trade.remaining_position = max(
                    0.0, trade.remaining_position - delta
                )
                trade.total_sold_qty = (
                    _v557_safe_float(getattr(trade, "total_sold_qty", 0.0)) + delta
                )
                px = _v557_safe_float(
                    (order or {}).get("average") or (order or {}).get("price"),
                    current_price or getattr(trade, "last_mark_price", trade.entry),
                )
                trade.last_partial_exit_price = px
                trade.target_order_filled_qty[level] = previous + delta
                trade.partial_tp_records.append({
                    "level": level,
                    "px": px,
                    "qty": delta,
                    "ts": WALL_NOW(),
                    "reason": "target_only_limit_fill",
                })
                trade.status = {
                    "TP1": "tp1_hit",
                    "TP2": "tp2_hit",
                    "TP3": "tp3_hit",
                }[level]
                if level == "TP1" and bool(CONFIG.get("V573_TARGET_COMPLETION_LATCH_ENABLE", True)):
                    trade.tp1_exit_completed = True
                elif level == "TP2" and bool(CONFIG.get("V573_TARGET_COMPLETION_LATCH_ENABLE", True)):
                    trade.tp2_exit_completed = True
                changed = True
                logger.info(
                    f"[V557-TARGET] {trade.symbol} {level} FILLED "
                    f"delta={delta:.10f} px={px:.10f} "
                    f"remaining={trade.remaining_position:.10f}"
                )

        trade.target_order_filled_qty[level] = max(previous, filled)

        if status in ("canceled", "cancelled", "rejected", "expired"):
            setattr(trade, attr, None)
            changed = True
            if not bool(CONFIG.get("V561_TARGET_RECREATE_ON_CANCEL", False)) or                     bool(getattr(trade, "target_recreate_disabled", False)):
                logger.warning(
                    f"[V561-TARGET] {trade.symbol} {level} terminal status={status}; "
                    "id cleared; automatic recreation is DISABLED."
                )
            else:
                logger.warning(
                    f"[V557-TARGET] {trade.symbol} {level} terminal status={status}; "
                    "id cleared for bounded re-placement."
                )

    _amb_reason = str(getattr(trade, "target_order_ambiguous_reason", "") or "")
    if (_all_target_states_verified and _amb_reason in {"target_state_unknown", "terminal_order_requires_reconcile"}
            and all(getattr(trade, _v557_target_attr(_lvl), None) is None or bool(getattr(trade, _v557_target_attr(_lvl), None))
                    for _lvl in ("TP1", "TP2", "TP3"))):
        trade.target_order_ambiguous = False
        trade.target_order_ambiguous_reason = ""

    if trade.remaining_position <= 0:
        trade.target_orders_active = False
        trade.target_only_mode = False
        await _finalize_and_record_r(
            trade,
            exit_reason="target_only_tp_full_exit",
            exit_px=current_price or trade.last_partial_exit_price or trade.entry,
        )
        try:
            await _v559_recover_entries_after_target_exit(trade.symbol)
        except Exception:
            _v647_record_suppressed_exception()
        return True

    if (
        not trade.target_order_ambiguous
        and bool(CONFIG.get("V561_TARGET_RECREATE_ON_CANCEL", False))
        and not bool(getattr(trade, "target_recreate_disabled", False))
    ):
        await _v557_place_target_only_orders(exchange, trade)

    if changed:
        try:
            await DBManager.asave_trade_snapshot(trade)
        except Exception:
            _v647_record_suppressed_exception()
    return changed



# =============================================================================
#  v4.5.62 — NATIVE SL REPLACEMENT FAILURE RECOVERY
# =============================================================================

async def _v562_recover_after_sl_replace_failure(
    exchange,
    trade: TradeState,
    previous_sl: float,
    reason: str,
) -> bool:
    """Restore the safest known model SL and activate software protection once."""
    try:
        prev = float(previous_sl or 0.0)
        current = float(
            getattr(trade, "current_sl", 0.0)
            or getattr(trade, "original_sl", 0.0)
            or 0.0
        )

        if prev > 0 and prev < float(trade.entry):
            # Never move an already-active software SL backwards.
            trade.current_sl = max(current, prev) if trade.software_sl_active else prev

        trade.sl_failure_reason = str(reason or "sl_replace_failed")
        trade.sl_order_id = None

        was_active = bool(getattr(trade, "software_sl_active", False))
        if not await _v560_arm_software_sl(trade, str(reason or "sl_replace_failed")):
            logger.critical(
                f"[V564-SL] {trade.symbol} software protection could not be armed"
            )
            live_entries_block(
                f"software_sl_arm_failed_{trade.symbol}",
                where="V564.recover_after_sl_replace_failure"
            )
            return False

        if was_active:
            STATS["v564_sl_failover_reentry_suppressed"] = int(
                STATS.get("v564_sl_failover_reentry_suppressed", 0) or 0
            ) + 1
            return True

        STATS["v562_sl_replace_to_software"] = int(
            STATS.get("v562_sl_replace_to_software", 0) or 0
        ) + 1
        trade.sl_health_state = "SOFTWARE_SL_ACTIVE"

        logger.critical(
            f"[V564-SL] {trade.symbol} native SL replacement failed; "
            f"software AUTO-SL active at {trade.current_sl:.10g}"
        )
        await _v564_notify_sl_failover_once(
            trade, str(reason or "sl_replace_failed"), previous_sl=prev
        )
        return True
    except Exception as exc:
        logger.critical(
            f"[V564-SL] replacement recovery exception {trade.symbol}: {exc}"
        )
        live_entries_block(
            f"software_sl_arm_failed_{trade.symbol}",
            where="V564.recover_after_sl_replace_failure"
        )
        return False




# =============================================================================
#  SECTION 36 — POSITION MANAGER LOOP
# =============================================================================

async def _v702_reconcile_entry_intent_for_trade(exchange, trade: TradeState) -> bool:
    """Reconcile a durable/ambiguous BUY before ordinary management work.

    Returns True when the caller may continue normal price/protection management;
    a zero-known-fill pending state must wait for a later authoritative order read.
    """
    order_ids = list(getattr(trade, "entry_order_ids", []) or [])
    if not order_ids:
        live_entries_block(f"entry_reconcile_order_id_missing_{trade.symbol}", where="PositionManager.entry_reconcile")
        return float(getattr(trade, "remaining_position", 0.0) or 0.0) > 0.0
    oid = str(order_ids[-1])
    try:
        order = await safe_api_call(
            f"entry_intent_fetch_order_{trade.symbol}",
            lambda: exchange.fetch_order(oid, trade.symbol),
            retry_safe=False,
        )
        if not isinstance(order, dict):
            raise RuntimeError("entry_reconcile_order_response_invalid")
    except Exception as exc:
        STATS["entry_intent_reconcile_read_errors"] = int(STATS.get("entry_intent_reconcile_read_errors", 0) or 0) + 1
        live_entries_block(f"entry_reconcile_read_failed_{trade.symbol}", where="PositionManager.entry_reconcile")
        logger.critical("[ENTRY-RECONCILE] %s order=%s state unavailable: %s", trade.symbol, oid, exc)
        return float(getattr(trade, "remaining_position", 0.0) or 0.0) > 0.0

    status = str(order.get("status") or "unknown").lower()
    try: reported = float(order.get("filled") or order.get("executedQty") or 0.0)
    except Exception: reported = 0.0
    terminal = status in {"closed", "filled", "complete", "canceled", "cancelled", "expired", "rejected"}

    # Any nonterminal order is unresolved. Attempt cancellation even with a zero-fill
    # initial read; an execution can race that read before it reaches the venue cache.
    if not terminal:
        canceled = await OrderExecutor.cancel_order_safe(exchange, oid, trade.symbol)
        if canceled is True:
            try:
                final_order = await safe_api_call(
                    f"entry_intent_final_order_{trade.symbol}",
                    lambda: exchange.fetch_order(oid, trade.symbol), retry_safe=False,
                )
                if isinstance(final_order, dict) and str(final_order.get("status") or "unknown").lower() in {
                    "closed", "filled", "complete", "canceled", "cancelled", "expired", "rejected"
                }:
                    order = final_order
                    status = str(order.get("status") or "unknown").lower()
                    terminal = True
                    reported = float(order.get("filled") or order.get("executedQty") or reported)
            except Exception as exc:
                logger.critical("[ENTRY-RECONCILE] %s post-cancel fetch unresolved: %s", trade.symbol, exc)
        if not terminal:
            trade.entry_reconcile_required = True
            trade.fill_reconciliation_status = "RECONCILE_PENDING"
            live_entries_block(f"entry_remainder_cancel_unverified_{trade.symbol}", where="PositionManager.entry_reconcile")

    if reported <= 0:
        if terminal and float(getattr(trade, "entry_fill_amount", 0.0) or 0.0) <= 0:
            trade.status = "entry_no_fill_terminal"
            trade.entry_reconcile_required = False
            try:
                iid = str(getattr(trade, "entry_intent_id", "") or "")
                if iid:
                    await DBManager.aupdate_execution_intent(iid, "NO_FILL_TERMINAL", venue_order_id=oid,
                        details={"terminal_status":status,"filled_qty":0.0})
                ACTIVE_TRADES.pop(trade.symbol, None)
                await DBManager.adelete_trade_snapshot(trade.symbol, trade.trace_id)
                STATS["entry_intent_confirmed_zero_fill"] = int(STATS.get("entry_intent_confirmed_zero_fill", 0) or 0) + 1
            except Exception as exc:
                live_entries_block(f"entry_no_fill_finalize_failed_{trade.symbol}", where="PositionManager.entry_reconcile")
                logger.critical("[ENTRY-RECONCILE] %s zero-fill terminal state not durable: %s", trade.symbol, exc)
            return False
        trade.entry_reconcile_required = not terminal
        trade.fill_reconciliation_status = "RECONCILE_PENDING" if not terminal else "CONFIRMED"
        if not terminal:
            live_entries_block(f"entry_fill_not_yet_confirmed_{trade.symbol}", where="PositionManager.entry_reconcile")
        return float(getattr(trade, "remaining_position", 0.0) or 0.0) > 0.0

    try:
        requested = float(getattr(trade, "entry_requested_amount", 0.0) or order.get("amount") or reported)
        qty_gross, px, auth = await _v553_reconcile_buy_fill(exchange, trade.symbol, order, requested, float(trade.planned_entry or trade.entry or 0.0))
        ctx = _v553_take_buy_fill_context(str(auth.get("id") or oid)) or {}
        net_qty = float(ctx.get("net_filled_qty") or ctx.get("filled_qty") or qty_gross)
        if not math.isfinite(net_qty) or net_qty <= 0 or px <= 0:
            raise RuntimeError("entry_reconcile_fill_not_positive")
    except Exception as exc:
        trade.entry_reconcile_required = True
        trade.fill_reconciliation_status = "RECONCILE_PENDING"
        live_entries_block(f"entry_fill_reconcile_failed_{trade.symbol}", where="PositionManager.entry_reconcile")
        logger.critical("[ENTRY-RECONCILE] %s authoritative fill failed: %s", trade.symbol, exc)
        return float(getattr(trade, "remaining_position", 0.0) or 0.0) > 0.0

    old_total = float(getattr(trade, "entry_fill_amount", 0.0) or 0.0)
    old_remaining = float(getattr(trade, "remaining_position", 0.0) or 0.0)
    delta = max(0.0, net_qty - old_total)
    if old_total <= 0.0 and net_qty > 0.0:
        risk_dist = max(float(trade.planned_entry or px) - float(trade.original_sl or 0.0), float(px) * 0.004)
        new_sl = px - risk_dist
        trade.entry = trade.effective_entry = trade.entry_fill_price = float(px)
        trade.entry_filled = True
        trade.entry_fill_amount = net_qty
        trade.position_size_asset = net_qty
        trade.remaining_position = net_qty
        trade.original_sl = trade.current_sl = float(min(new_sl, px * 0.99))
        trade.tp1 = trade.tp2 = trade.tp3 = 0.0
        trade.target_plan_pending = True
        trade.status = "entry_filled_management_only"
        trade.fill_reconciliation_status = "RECONCILE_PENDING" if not terminal else "CONFIRMED"
        STATS["entry_intent_pending_fill_adopted"] = int(STATS.get("entry_intent_pending_fill_adopted", 0) or 0) + 1
    _rearm_protection_allowed = True
    if old_total > 0.0 and delta > 1e-12:
        # Cumulative venue quantity grew after an earlier partial fill. Resize protection
        # only after attempting to verify cancellation of the previous native stop.
        trade.entry_fill_amount = net_qty
        trade.position_size_asset += delta
        trade.remaining_position = old_remaining + delta
        trade.entry_fill_price = float(px)
        trade.entry = trade.effective_entry = float(px)
        if trade.sl_order_id:
            canceled_sl = await OrderExecutor.cancel_order_safe(exchange, trade.sl_order_id, trade.symbol)
            if canceled_sl is True:
                trade.sl_order_id = None
            else:
                _rearm_protection_allowed = False
                live_entries_block(f"entry_growth_prior_sl_cancel_unverified_{trade.symbol}", where="PositionManager.entry_reconcile")
                await _v560_arm_software_sl(trade, "entry_fill_grew_after_unverified_native_sl_cancel")
    trade.entry_fill_cost_usdt = float(ctx.get("fill_cost_estimate") or (net_qty * px))
    trade.entry_fill_fees = list(ctx.get("fee_records") or [])
    trade.entry_order_ids = list(dict.fromkeys((order_ids + [str(auth.get("id") or oid)])))
    trade.entry_reconcile_required = not terminal
    trade.fill_reconciliation_status = "CONFIRMED" if terminal else "RECONCILE_PENDING"
    if not terminal:
        live_entries_block(f"entry_order_still_nonterminal_{trade.symbol}", where="PositionManager.entry_reconcile")
    elif getattr(trade, "entry_intent_id", ""):
        try:
            await DBManager.aupdate_execution_intent(
                trade.entry_intent_id, "FILL_ADOPTED", venue_order_id=oid,
                details={"fill_qty":net_qty,"fill_price":px,"terminal_status":status},
            )
        except Exception:
            trade.entry_reconcile_required = True

    # Re-arm after any adopted/increased quantity. Do not clear a verified native SL
    # until its cancellation was confirmed; software SL is the conservative fallback.
    if _rearm_protection_allowed and trade.remaining_position > 0 and (
            delta > 1e-12 or not (trade.sl_order_id or getattr(trade, "software_sl_active", False))):
        try:
            sl_ok, sl_oid = await OrderExecutor.place_sl(exchange, trade)
            if sl_ok:
                trade.sl_order_id = sl_oid
            else:
                armed = await _v560_arm_software_sl(trade, "entry_intent_reconciliation_protection")
                if not armed:
                    live_entries_block(f"entry_intent_reconciled_unprotected_{trade.symbol}", where="PositionManager.entry_reconcile")
        except Exception as exc:
            live_entries_block(f"entry_intent_protection_exception_{trade.symbol}", where="PositionManager.entry_reconcile")
            logger.critical("[ENTRY-RECONCILE] %s protection re-arm failed: %s", trade.symbol, exc)
    try:
        await DBManager.asave_trade_snapshot(trade)
        iid = str(getattr(trade, "entry_intent_id", "") or "")
        if iid and terminal and (trade.sl_order_id or trade.software_sl_active):
            await DBManager.aupdate_execution_intent(iid, "PROTECTION_ARMED", venue_order_id=oid,
                details={"protection_mode":"NATIVE" if trade.sl_order_id else "SOFTWARE",
                         "remaining_position":trade.remaining_position,"sl":trade.current_sl})
    except Exception as exc:
        live_entries_block(f"entry_intent_reconcile_persist_failed_{trade.symbol}", where="PositionManager.entry_reconcile")
        logger.critical("[ENTRY-RECONCILE] %s durable state save failed: %s", trade.symbol, exc)
    return float(getattr(trade, "remaining_position", 0.0) or 0.0) > 0.0


class PositionManager:

    _tick_lock: Optional[asyncio.Lock] = None

    @classmethod
    def _get_tick_lock(cls) -> asyncio.Lock:
        if cls._tick_lock is None:
            cls._tick_lock = asyncio.Lock()
        return cls._tick_lock

    @classmethod
    async def tick(cls, exchange):
        # v4.5.56: serialize every PM invocation. This matters once the
        # dedicated 1s protection task runs alongside any legacy caller.
        async with cls._get_tick_lock():
            return await cls._tick_locked(exchange)

    @staticmethod
    async def _tick_locked(exchange):
        # A cycle is healthy only when every position present at cycle start
        # received a valid market mark and protection evaluation, or was
        # conclusively closed during this cycle. Per-symbol exceptions must not
        # be hidden by the loop's best-effort continuation.
        _pm_cycle_started = float(WALL_NOW())
        _pm_cycle_snapshot = list(ACTIVE_TRADES.items())
        _pm_cycle_symbols = [str(x) for x, _trade in _pm_cycle_snapshot]
        _pm_cycle_identity_by_symbol = {
            str(_sym): _v702_position_identity(_sym, _trade)
            for _sym, _trade in _pm_cycle_snapshot
        }
        _pm_cycle_status = {sym: "PENDING" for sym in _pm_cycle_symbols}
        for _sym, _identity in _pm_cycle_identity_by_symbol.items():
            if not _identity:
                _pm_cycle_status[_sym] = "INCOMPLETE:POSITION_IDENTITY_MISSING"
        def _pm_set_status(_sym, _state):
            _pm_cycle_status[str(_sym)] = str(_state)[:180]
        # v4.0.2 PATCH B: heartbeat for SoftwareSLFallback consumers
        try:
            SoftwareSLTelemetry.register_pm_tick()
            _v563_clear_resolved_protection_block()
        except Exception as _pm_telemetry_exc:
            _v593_note_suppressed_exception("position_manager.tick.telemetry", _pm_telemetry_exc)
        # v4.0.4 PATCH R — closed-state guard used after any awaited exit path.
        # Detects trades that were finalized (popped) / drained / closed by
        # SLHealthAuditor.verify or SoftwareSLFallback.check inside this tick.
        _CLOSED_STATES = ("sl_hit", "emergency_closed", "finalized", "tp2_full_exit")

        def _is_trade_closed_locally(sym: str, t) -> bool:
            try:
                if sym not in ACTIVE_TRADES:
                    return True
                if float(getattr(t, "remaining_position", 0.0) or 0.0) <= 0:
                    return True
                if getattr(t, "status", "") in _CLOSED_STATES:
                    return True
            except Exception:
                # Fail-closed: unknown → treat as closed to avoid stale ops
                return True
            return False

        for symbol, trade in list(ACTIVE_TRADES.items()):
            try:
                if (str(getattr(trade, "status", "")) == "entry_pending_reconcile"
                        or bool(getattr(trade, "entry_reconcile_required", False))):
                    _may_manage = await _v702_reconcile_entry_intent_for_trade(exchange, trade)
                    if float(getattr(trade, "remaining_position", 0.0) or 0.0) <= 0.0:
                        _pm_set_status(symbol, "CLOSED")
                        continue
                    if not _may_manage:
                        _pm_set_status(symbol, "INCOMPLETE:ENTRY_RECONCILIATION")
                        continue
                # Fetch current price. Protection reads deliberately avoid the
                # generic transient retry path: duplicating a read is harmless,
                # but delaying a software-SL decision is not. The next dedicated
                # PM tick is the bounded retry point.
                ticker = await safe_api_call(
                    f"protected_fetch_ticker_{symbol}",
                    lambda: exchange.fetch_ticker(symbol),
                    retry_safe=bool(CONFIG.get("V702_PROTECTION_TICKER_RETRY_SAFE", False)),
                )
                cur = float(ticker.get("last") or ticker.get("close") or 0)
                if cur <= 0 or not math.isfinite(cur):
                    _pm_set_status(symbol, "INCOMPLETE:INVALID_MARK_PRICE")
                    continue
                bid = 0.0
                try:
                    bid = float(ticker.get("bid") or 0.0)
                except Exception:
                    bid = 0.0
                protect_cur = min(cur, bid) if (
                    bool(CONFIG.get("V702_SOFTWARE_SL_BID_GUARD_ENABLE", True))
                    and bid > 0
                ) else cur
                trade.highest_price = max(trade.highest_price, cur)
                trade.last_mark_price = cur
                try:
                    trade.protection_last_mark_price = cur
                    trade.protection_last_bid_price = bid
                except Exception:
                    _v593_note_suppressed_exception("position_manager.protection_observation", Exception("field_write_failed"))

                # V702 FINAL NEAR-TRIGGER RECHECK: only when an active software
                # SL exists and the executable protection price is still just
                # above it. No recheck is performed after a breach is visible,
                # so the safety path never waits for a second read to exit.
                try:
                    active_sw = bool(getattr(trade, "software_sl_active", False))
                    model_sl = float(getattr(trade, "current_sl", 0.0) or getattr(trade, "original_sl", 0.0) or 0.0)
                    near_pct = max(0.0, float(CONFIG.get("V702_SOFTWARE_SL_NEAR_TRIGGER_RECHECK_PCT", 0.20))) / 100.0
                    near_trigger = bool(active_sw and model_sl > 0 and protect_cur > model_sl and (protect_cur - model_sl) / model_sl <= near_pct)
                    if near_trigger and bool(CONFIG.get("V702_SOFTWARE_SL_NEAR_TRIGGER_RECHECK_ENABLE", True)):
                        recheck = await safe_api_call(
                            f"protected_fetch_ticker_{symbol}",
                            lambda: exchange.fetch_ticker(symbol),
                            retry_safe=False,
                        )
                        re_last = float(recheck.get("last") or recheck.get("close") or 0.0)
                        re_bid = float(recheck.get("bid") or 0.0)
                        if re_last > 0:
                            cur = re_last
                        if re_bid > 0:
                            bid = re_bid
                        protect_cur = min(cur, bid) if (
                            bool(CONFIG.get("V702_SOFTWARE_SL_BID_GUARD_ENABLE", True)) and bid > 0
                        ) else cur
                        trade.highest_price = max(trade.highest_price, cur)
                        trade.last_mark_price = cur
                        try:
                            trade.protection_last_mark_price = cur
                            trade.protection_last_bid_price = bid
                            trade.protection_last_trigger_price = protect_cur
                            trade.protection_last_trigger_ts = MONO_NOW()
                        except Exception:
                            _v593_note_suppressed_exception("position_manager.protection_recheck_observation", Exception("field_write_failed"))
                        STATS["v702_protection_near_rechecks"] = int(STATS.get("v702_protection_near_rechecks", 0) or 0) + 1
                except Exception as _protect_recheck_exc:
                    # A failed near-trigger recheck never blocks the normal
                    # software-SL evaluation; the current valid ticker remains
                    # authoritative for this tick.
                    STATS["v702_protection_near_recheck_errors"] = int(STATS.get("v702_protection_near_recheck_errors", 0) or 0) + 1
                    _v593_note_suppressed_exception("position_manager.protection_near_recheck", _protect_recheck_exc)

                # v4.5.59 ROOT POLICY:
                # After an SL failure, TARGET_ONLY is the terminal automated-exit
                # branch. Monitor the model SL (alerts only), reconcile LIMIT SELL
                # targets, and do not run any market SELL/SL mutation/time exit.
                if bool(getattr(trade, "target_only_mode", False)):
                    # v4.5.74: TARGET_ONLY is target-order policy, NOT
                    # "no automatic SL". Software-SL remains mandatory.
                    try:
                        _sw_closed = await SoftwareSLFallback.check(exchange, trade, protect_cur)
                    except Exception as _sw_e:
                        _sw_closed = False
                        logger.error(f"[V574-SL] {symbol} target-only software-SL check failed: {_sw_e}")
                    if _is_trade_closed_locally(symbol, trade) or _sw_closed:
                        _pm_set_status(symbol, "CLOSED")
                        continue
                    try:
                        await _v559_monitor_sl_only(trade, cur)
                    except Exception as _mon_e:
                        logger.debug(f"[V559-SL-MONITOR] {symbol}: {_mon_e}")
                    try:
                        await _v557_reconcile_target_only_orders(
                            exchange, trade, cur
                        )
                    except Exception as _tgt_e:
                        logger.error(
                            f"[V559-TARGET] {symbol} reconcile failed: {_tgt_e}"
                        )
                    _pm_set_status(symbol, "PROTECTED" if _v563_trade_protection_healthy(trade) else "INCOMPLETE:PROTECTION_UNHEALTHY")
                    continue

                # v4.5.17: reconcile ambiguous SL/TP outcomes before any new
                # mutation; unresolved ambiguity never permits a blind retry.
                if hasattr(trade, "v517_pending_sl_reconcile"):
                    if not await _v517_reconcile_pending_sl(exchange, trade):
                        _pm_set_status(symbol, "INCOMPLETE:PENDING_SL_RECONCILIATION")
                        continue
                if hasattr(trade, "v517_pending_exit_reconcile"):
                    if not await _v517_reconcile_pending_exit(exchange, trade):
                        _pm_set_status(symbol, "INCOMPLETE:PENDING_EXIT_RECONCILIATION")
                        continue

                # SL health audit — may finalize (SL_HIT / MISSING) and pop trade.
                await SLHealthAuditor.verify(exchange, trade)
                # v4.0.4 PATCH R — short-circuit if audit finalized/closed the trade
                if _is_trade_closed_locally(symbol, trade):
                    _pm_set_status(symbol, "CLOSED")
                    STATS["tick_shortcircuit_after_audit"] = \
                        STATS.get("tick_shortcircuit_after_audit", 0) + 1
                    continue

                await SoftwareSLFallback.check(exchange, trade, protect_cur)
                # v4.0.4 PATCH R — short-circuit if software fallback finalized/closed
                if _is_trade_closed_locally(symbol, trade):
                    _pm_set_status(symbol, "CLOSED")
                    STATS["tick_shortcircuit_after_swsl"] = \
                        STATS.get("tick_shortcircuit_after_swsl", 0) + 1
                    continue
                if not _v563_trade_protection_healthy(trade):
                    _pm_set_status(symbol, "INCOMPLETE:PROTECTION_UNHEALTHY_AFTER_AUDIT")
                else:
                    _pm_set_status(symbol, "PROTECTED")

                # V702 R3 LSB LOSS CLOSURE: confirmed breakout-thesis failure can
                # exit before the generic ATR stop. EXIT-ONLY; no entry gate is changed.
                try:
                    _v702_struct_closed = await _v702_structural_failure_guard(
                        exchange, trade, protect_cur
                    )
                except Exception as _v702_struct_e:
                    _v702_struct_closed = False
                    logger.warning(
                        f"[V702-R4] structural failure check failed {symbol}: {_v702_struct_e}"
                    )
                if _v702_struct_closed or _is_trade_closed_locally(symbol, trade):
                    _pm_set_status(symbol, "CLOSED" if _is_trade_closed_locally(symbol, trade) else _pm_cycle_status.get(symbol, "INCOMPLETE:STRUCTURAL_EXIT"))
                    STATS["tick_shortcircuit_after_structural_invalidation"] = int(
                        STATS.get("tick_shortcircuit_after_structural_invalidation", 0) or 0
                    ) + 1
                    continue

                # TP1 hit — v4.0.2 PATCH A: safety-clamp qty to remaining
                if (trade.status == "entry_filled"
                        and not bool(getattr(trade, "target_plan_pending", False))
                        and float(getattr(trade, "tp1", 0.0) or 0.0) > 0.0
                        and cur >= trade.tp1):
                    qty_tp1 = trade.position_size_asset * float(CONFIG["TP1_EXIT_PCT"])
                    # Never sell more than remaining
                    qty_tp1 = min(qty_tp1, trade.remaining_position)
                    # Precision preflight (fail-closed on unresolvable qty)
                    qty_tp1_n, _, prec_err = OrderExecutor._normalize_qty_price(
                        exchange, symbol, qty_tp1, cur
                    )
                    if prec_err or qty_tp1_n is None or qty_tp1_n <= 0:
                        logger.warning(
                            f"[TP1] {symbol} precision preflight failed: {prec_err}; skipping"
                        )
                    else:
                        try:
                            _tp1_order = await _v517_market_sell_reconciled(
                                exchange, trade, symbol, qty_tp1_n, cur, "tp1_sell")
                            _tp1_fill_qty = float((_tp1_order or {}).get("_v526_fill_qty") or qty_tp1_n)
                            _tp1_fill_px = float((_tp1_order or {}).get("_v526_fill_px") or cur)
                            if _tp1_fill_qty < qty_tp1_n * float(CONFIG.get("EXIT_FILL_MIN_CONFIRM_RATIO",0.995)):
                                raise _V517UnknownExecution(f"tp1_partial_fill:{_tp1_fill_qty:.10f}/{qty_tp1_n:.10f}")
                            trade.remaining_position=max(0.0,trade.remaining_position-_tp1_fill_qty)
                            trade.total_sold_qty += _tp1_fill_qty
                            trade.last_partial_exit_price=_tp1_fill_px
                            trade.status="tp1_hit"
                            if bool(CONFIG.get("V573_TARGET_COMPLETION_LATCH_ENABLE", True)):
                                trade.tp1_exit_completed = True
                            trade.partial_tp_records.append({
                                "level":"TP1","px":_tp1_fill_px,"qty":_tp1_fill_qty,"ts":time.time(),
                                "expected_px":cur,
                                "slippage_pct":((cur-_tp1_fill_px)/max(cur,1e-12))*100.0})
                            await OpportunityTelegramNotifier.notify_exit_event(
                                trade,"TP1 HIT",fill_px=_tp1_fill_px,fill_qty=_tp1_fill_qty,
                                pnl_r=_v526_event_r(trade,_tp1_fill_px),
                                remaining=trade.remaining_position,
                                extra="Partial profit taken; fee-covered BE protection follows."
                            )
                            LifecycleTrace.record(trade.trace_id, "TP1_HIT",
                                                  {"px": cur, "qty": qty_tp1_n,
                                                   "remaining": trade.remaining_position})
                            # v4.0.6 FIX #1 — Refresh sl_covered_qty to the
                            # NEW remaining immediately after the partial
                            # exit. move_to_break_even will re-place SL and
                            # place_sl will re-snapshot sl_covered_qty from
                            # the (already correct) remaining_position; this
                            # assignment keeps the field consistent in the
                            # transient window between the partial fill and
                            # the successful re-place.
                            # SL must be resized to remaining BEFORE re-placement
                            # v4.0.6 PATCH #1 — decisive SL failure handling.
                            # move_to_break_even now returns False on a real
                            # protection failure (cancel verified but place_sl
                            # failed). Leaving the remaining position without
                            # an SL is not acceptable → emergency_close and
                            # short-circuit the rest of this tick (skip TP2 /
                            # staircase / trailing on the same iteration).
                            # v4.0.9 DS-2 — wrap the SL cancel+replace in the
                            # SAME symbol lock used by build_and_route so no
                            # entry-side SL work can interleave mid-mutation.
                            # Capture the exact pre-BE stop in this trade scope.
                            # Recovery must never depend on a local left over from
                            # another symbol or on an unrelated ExitManager path.
                            prev_sl = float(getattr(trade, "current_sl", 0.0) or
                                            getattr(trade, "original_sl", 0.0) or 0.0)
                            if (
                                bool(getattr(trade, "software_sl_active", False))
                                and bool(CONFIG.get("V564_SOFTWARE_SL_LOCAL_BE_ENABLE", True))
                            ):
                                try:
                                    fee_pct = float(CONFIG.get("TAKER_FEE_PCT", 0.10)) / 100.0
                                    fee_mult = float(CONFIG.get("ROUNDTRIP_FEE_MULT", 2.0))
                                    candidate_be_sl = float(trade.entry) * (1.0 + fee_pct * fee_mult)
                                    trade.current_sl = max(float(trade.current_sl), candidate_be_sl)
                                    trade.status = "be_moved"
                                    trade.sl_health_state = "SOFTWARE_SL_ACTIVE"
                                    trade.sl_monitor_mode = "AUTO_SELL"
                                    be_ok = True
                                    STATS["v564_software_local_be_updates"] = int(
                                        STATS.get("v564_software_local_be_updates", 0) or 0
                                    ) + 1
                                    logger.info(
                                        f"[V564-SL] {symbol} local fee-covered BE "
                                        f"SL={trade.current_sl:.10g}"
                                    )
                                except Exception as _be_e:
                                    logger.warning(
                                        f"[V564-SL] {symbol} local BE update failed: {_be_e}"
                                    )
                                    be_ok = False
                            else:
                                async with HandoffOwnership.lock_for(symbol):
                                    be_ok = await ExitManager.move_to_break_even(exchange, trade)
                            if not be_ok and trade.remaining_position > 0:
                                if trade.sl_health_state == "CANCEL_UNVERIFIED":
                                    # The old stop may still be live. Do not sell
                                    # into a possible still-live oversized stop;
                                    # preserve state and defer to SL health audit.
                                    logger.critical(
                                        f"[TP1] {symbol}: BE cancel UNVERIFIED — "
                                        "skip further exit mutations this tick."
                                    )
                                    continue
                                logger.critical(
                                    f"[TP1] {symbol}: BE re-placement FAILED after "
                                    "verified cancel — TARGET_ONLY fallback; no market SELL."
                                )
                                STATS["tp1_be_fail_target_only"] =                                     STATS.get("tp1_be_fail_target_only", 0) + 1
                                if str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() == "HYBRID_AUTO":
                                    await _v562_recover_after_sl_replace_failure(
                                        exchange, trade, prev_sl, "tp1_be_replace_failed"
                                    )
                                elif str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() in {"TARGET_ONLY", "SOFTWARE_ALERT"}:
                                    await _v559_activate_sl_failure_policy(
                                        exchange, trade, "tp1_be_replace_failed"
                                    )
                                else:
                                    await OrderExecutor.emergency_close(
                                        exchange, trade, "tp1_be_replace_failed"
                                    )
                                continue
                        except Exception as e:
                            logger.error(f"[TP1] {symbol}: {e}")
                            if hasattr(trade, "v517_pending_exit_reconcile"):
                                continue

                # TP2 hit — runner-aware exit split (no conflict with TP2_EXIT_PCT)
                #
                #   Runner OFF: sell ALL remaining at TP2 (TP1_EXIT_PCT + TP2_EXIT_PCT == 1.0)
                #   Runner ON:  sell TP2_EXIT_PCT fraction at TP2,
                #               keep RUNNER_KEEP_PCT_AT_TP3 fraction for runner.
                #   (TP1_EXIT_PCT + TP2_EXIT_PCT + RUNNER_KEEP_PCT_AT_TP3 == 1.0)
                # TP2 hit — v4.0.2 PATCH A: FIX runner math (broken paren in v4.0.1)
                #
                # v4.0.1 formula had this bug:
                #   float(CONFIG["TP2_EXIT_PCT"] + float(CONFIG["RUNNER_KEEP_PCT_AT_TP3"]))
                #                              ^
                # This wrapped an inner sum in float() twice and closed the paren
                # on the wrong term, effectively yielding the wrong denominator.
                #
                # Correct semantics:
                #   - Runner OFF: sell ALL remaining (invariant TP1+TP2 == 1.0)
                #   - Runner ON : sell TP2_EXIT_PCT fraction of ORIGINAL position,
                #                 keep RUNNER_KEEP_PCT_AT_TP3 as runner.
                #                 (invariant TP1+TP2+RUNNER == 1.0)
                if (trade.status in ("tp1_hit", "be_moved", "trailing")
                        and not bool(getattr(trade, "target_plan_pending", False))
                        and float(getattr(trade, "tp2", 0.0) or 0.0) > 0.0
                        and cur >= trade.tp2):
                    exit_reason = ""
                    if not bool(CONFIG["ENABLE_RUNNER_MODE"]):
                        qty_tp2 = trade.remaining_position
                        exit_reason = "tp2_full_exit"
                    else:
                        # Sell TP2_EXIT_PCT of the ORIGINAL position (canonical).
                        # The runner is what's left AFTER this sell.
                        qty_tp2 = trade.position_size_asset * float(CONFIG["TP2_EXIT_PCT"])
                        exit_reason = "tp2_partial_keep_runner"
                    # Safety invariant: never sell more than remaining
                    qty_tp2 = min(qty_tp2, trade.remaining_position)
                    # Precision preflight
                    qty_tp2_n, _, prec_err = OrderExecutor._normalize_qty_price(
                        exchange, symbol, qty_tp2, cur
                    )
                    if prec_err or qty_tp2_n is None or qty_tp2_n <= 0:
                        logger.warning(
                            f"[TP2] {symbol}: qty_tp2={qty_tp2:.10f} rejected by "
                            f"precision preflight ({prec_err}) — skipping"
                        )
                    else:
                        try:
                            _tp2_order = await _v517_market_sell_reconciled(
                                exchange, trade, symbol, qty_tp2_n, cur, "tp2_sell")
                            _tp2_fill_qty = float((_tp2_order or {}).get("_v526_fill_qty") or qty_tp2_n)
                            _tp2_fill_px = float((_tp2_order or {}).get("_v526_fill_px") or cur)
                            if _tp2_fill_qty < qty_tp2_n * float(CONFIG.get("EXIT_FILL_MIN_CONFIRM_RATIO",0.995)):
                                raise _V517UnknownExecution(f"tp2_partial_fill:{_tp2_fill_qty:.10f}/{qty_tp2_n:.10f}")
                            trade.remaining_position=max(0.0,trade.remaining_position-_tp2_fill_qty)
                            trade.total_sold_qty += _tp2_fill_qty
                            trade.last_partial_exit_price=_tp2_fill_px
                            trade.status="tp2_hit"
                            if bool(CONFIG.get("V573_TARGET_COMPLETION_LATCH_ENABLE", True)):
                                trade.tp2_exit_completed = True
                            trade.partial_tp_records.append({
                                "level":"TP2","px":_tp2_fill_px,"qty":_tp2_fill_qty,"ts":time.time(),
                                "reason":exit_reason,"expected_px":cur,
                                "slippage_pct":((cur-_tp2_fill_px)/max(cur,1e-12))*100.0})
                            await OpportunityTelegramNotifier.notify_exit_event(
                                trade,"TP2 HIT",fill_px=_tp2_fill_px,fill_qty=_tp2_fill_qty,
                                pnl_r=_v526_event_r(trade,_tp2_fill_px),
                                remaining=trade.remaining_position,
                                extra=("Runner remains active after TP2; residual SL will be verified again."
                                       if bool(CONFIG["ENABLE_RUNNER_MODE"]) else "Remaining position is closing.")
                            )
                            LifecycleTrace.record(trade.trace_id, "TP2_HIT",
                                                  {"px": cur, "qty": qty_tp2_n,
                                                   "remaining": trade.remaining_position,
                                                   "reason": exit_reason})
                            # v4.0.6 FIX #1 — Refresh sl_covered_qty to the
                            # NEW remaining right after the TP2 partial fill.
                            # The subsequent cancel+re-place re-snapshots it
                            # via place_sl; this keeps it correct in the
                            # transient window in between.
                            # v4.0.2 PATCH A: SL MUST be re-sized to the new remaining
                            # v4.0.6 PATCH #2 — decisive SL failure handling on
                            # the TP2 partial path. If the old SL cancel is
                            # verified but the new place_sl FAILS, the runner
                            # residual is unprotected. We must NOT continue to
                            # runner/trailing; fail-closed → emergency_close
                            # the residual and short-circuit the tick.
                            if trade.remaining_position > 0 and trade.sl_order_id:
                                # v4.0.9 DS-2 — lock the cancel+place pair
                                # against concurrent entry-side SL work.
                                async with HandoffOwnership.lock_for(symbol):
                                    # Cancel current SL (verify) + place new SL bound to remaining
                                    ok_cancel = await OrderExecutor.cancel_order_safe(
                                        exchange, trade.sl_order_id, symbol
                                    )
                                    if ok_cancel:
                                        trade.sl_order_id = None
                                        place_ok_tp2, _oid_tp2 = await OrderExecutor.place_sl(
                                            exchange, trade
                                        )
                                if ok_cancel:
                                    if not place_ok_tp2 and trade.remaining_position > 0:
                                        try:
                                            trade.sl_health_state = "TP2_REPLACE_FAILED"
                                            trade.sl_failure_reason = \
                                                "tp2_partial_sl_replace_failed"
                                        except Exception:
                                            _v647_record_suppressed_exception()
                                        STATS["tp2_sl_replace_failed_target_only"] =                                             STATS.get("tp2_sl_replace_failed_target_only", 0) + 1
                                        logger.critical(
                                            f"[TP2] {symbol}: SL re-placement FAILED after "
                                            "verified cancel — TARGET_ONLY fallback; no market SELL."
                                        )
                                        if str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() == "HYBRID_AUTO":
                                            await _v562_recover_after_sl_replace_failure(
                                                exchange, trade, trade.current_sl, "tp2_sl_replace_failed"
                                            )
                                        elif str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() in {"TARGET_ONLY", "SOFTWARE_ALERT"}:
                                            await _v559_activate_sl_failure_policy(
                                                exchange, trade, "tp2_sl_replace_failed"
                                            )
                                        else:
                                            await OrderExecutor.emergency_close(
                                                exchange, trade, "tp2_sl_replace_failed"
                                            )
                                        continue
                                else:
                                    trade.sl_health_state = "CANCEL_UNVERIFIED"
                                    trade.sl_failure_reason = "tp2_partial_cancel_unverified"
                                    STATS["sl_cancel_unverified"] = \
                                        STATS.get("sl_cancel_unverified", 0) + 1
                                    logger.warning(
                                        f"[TP2] {symbol}: old SL cancel UNVERIFIED; "
                                        "state preserved and no replacement submitted."
                                    )
                            if trade.remaining_position <= 0:
                                # v4.0.3 PATCH G — central finalization path
                                await _finalize_and_record_r(
                                    trade, exit_reason="tp2_full_exit", exit_px=cur
                                )
                                continue
                        except Exception as e:
                            logger.error(f"[TP2] {symbol}: {e}")
                            if hasattr(trade, "v517_pending_exit_reconcile"):
                                continue

                # v4.5.26: TP3 is an ARM milestone, not a forced full exit.
                # Runner remains open; verified staircase/trailing protects it.
                if trade.status == "tp2_hit":
                    _runner_activated = ExitManager.maybe_activate_runner(trade, cur)
                    if _runner_activated:
                        if (
                            bool(getattr(trade, "software_sl_active", False))
                            and bool(CONFIG.get("V564_SOFTWARE_SL_LOCAL_RUNNER_LOCK_ENABLE", True))
                        ):
                            try:
                                risk_unit = max(
                                    float(trade.entry) - float(trade.original_sl), 1e-12
                                )
                                runner_lock = float(trade.entry) + float(
                                    CONFIG.get("TP3_RUNNER_LOCK_R", 3.0)
                                ) * risk_unit
                                trade.current_sl = max(float(trade.current_sl), runner_lock)
                                trade.sl_health_state = "SOFTWARE_SL_ACTIVE"
                                trade.sl_monitor_mode = "AUTO_SELL"
                                _lock_ok = True
                                STATS["v564_software_local_runner_lock"] = int(
                                    STATS.get("v564_software_local_runner_lock", 0) or 0
                                ) + 1
                            except Exception as _run_e:
                                logger.warning(
                                    f"[V564-SL] {symbol} local runner lock failed: {_run_e}"
                                )
                                _lock_ok = False
                        else:
                            _lock_ok = await ExitManager.arm_runner_protection(exchange, trade, cur)
                        if not _lock_ok and bool(CONFIG.get("RUNNER_TRAIL_REQUIRES_VERIFIED_SL", True)):
                            logger.critical(f"[TP3] {symbol}: runner protection lock failed.")
                            await OpportunityTelegramNotifier.notify_exit_event(
                                trade,"TP3 RUNNER PROTECTION FAILED",fill_px=cur,
                                remaining=trade.remaining_position,
                                extra="Runner protection was not verified."
                            )
                            # v4.5.57: SL failure switches residual to
                            # TARGET_ONLY instead of market-selling it.
                            if trade.sl_health_state != "CANCEL_UNVERIFIED" and not getattr(trade, "sl_order_id", None):
                                if str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() == "HYBRID_AUTO":
                                    await _v562_recover_after_sl_replace_failure(
                                        exchange, trade, trade.current_sl, "tp3_runner_lock_failed"
                                    )
                                elif str(CONFIG.get("V559_SL_FAILURE_POLICY", "HYBRID_AUTO")).upper() in {"TARGET_ONLY", "SOFTWARE_ALERT"}:
                                    await _v559_activate_sl_failure_policy(
                                        exchange, trade, "tp3_runner_lock_failed"
                                    )
                                else:
                                    await OrderExecutor.emergency_close(
                                        exchange, trade, "tp3_runner_lock_failed", exit_px=cur
                                    )
                            continue
                        await OpportunityTelegramNotifier.notify_exit_event(
                            trade,"TP3 REACHED — RUNNER ACTIVE",fill_px=cur,
                            remaining=trade.remaining_position,pnl_r=_v526_event_r(trade,cur),
                            extra=f"TP3 is not a forced sell. Runner stays open; minimum lock={float(CONFIG.get('TP3_RUNNER_LOCK_R',3.0)):.1f}R and trailing continues."
                        )

                # v4.0.3 PATCH O — Oversell guard (should almost never trigger)
                try:
                    orig = float(trade.position_size_asset or 0.0)
                    sold = float(trade.total_sold_qty or 0.0)
                    if orig > 0 and sold > orig * 1.005:
                        logger.critical(
                            f"[Oversell] {symbol} sold={sold:.10f} > orig={orig:.10f} "
                            f"(ratio={sold/orig:.4f}) — finalizing"
                        )
                        STATS["oversell_events"] = STATS.get("oversell_events", 0) + 1
                        await _finalize_and_record_r(
                            trade, exit_reason="oversell_guard", exit_px=cur
                        )
                        continue
                except Exception:
                    _v647_record_suppressed_exception()

                # Staircase lock — v4.0.6 FIX E: candidate-first commit order.
                # trade.current_sl and trade.staircase_level_hit are promoted
                # ONLY after cancel+replace succeeds. If cancel is unverified
                # or place_sl fails, state remains at the previous milestone.
                candidate_sl_stair = ExitManager.maybe_advance_staircase(trade, cur)
                if (
                    bool(getattr(trade, "software_sl_active", False))
                    and bool(CONFIG.get("V564_SOFTWARE_SL_LOCAL_TRAIL_ENABLE", True))
                    and candidate_sl_stair
                    and candidate_sl_stair > trade.current_sl
                ):
                    target_level = ExitManager.compute_staircase_target_level(trade, cur)
                    trade.current_sl = float(candidate_sl_stair)
                    trade.staircase_level_hit = target_level
                    trade.sl_health_state = "SOFTWARE_SL_ACTIVE"
                    trade.sl_monitor_mode = "AUTO_SELL"
                    STATS["v564_software_local_staircase_updates"] = int(
                        STATS.get("v564_software_local_staircase_updates", 0) or 0
                    ) + 1
                    logger.info(
                        f"[V564-SL] {symbol} local staircase SL={trade.current_sl:.10g} "
                        f"level={target_level}"
                    )
                elif candidate_sl_stair and candidate_sl_stair > trade.current_sl:
                    target_level = ExitManager.compute_staircase_target_level(trade, cur)
                    prev_sl = trade.current_sl
                    prev_level = trade.staircase_level_hit
                    prev_cov = trade.sl_covered_qty
                    replace_ok = False
                    # v4.0.9 DS-2 — wrap the whole cancel+place under the
                    # symbol lock to prevent interleaving with entry-side SL.
                    async with HandoffOwnership.lock_for(symbol):
                        if trade.sl_order_id:
                            cancel_ok = await OrderExecutor.cancel_order_safe(
                                exchange, trade.sl_order_id, symbol)
                            if cancel_ok:
                                trade.sl_order_id = None
                                # Submit the candidate without changing durable state.
                                place_ok, _oid = await OrderExecutor.place_sl(
                                    exchange, trade, candidate_sl_stair)
                                if place_ok:
                                    trade.current_sl = candidate_sl_stair
                                    trade.staircase_level_hit = target_level
                                    replace_ok = True
                                else:
                                    # Verified old-SL cancel + failed replacement:
                                    # restore the prior model level and arm software AUTO-SL.
                                    trade.sl_covered_qty = prev_cov
                                    trade.staircase_level_hit = prev_level
                                    logger.critical(
                                        f"[Staircase] {symbol} place_sl FAILED after cancel; "
                                        f"rolling back to prev_sl={prev_sl:.6f} and arming software SL"
                                    )
                                    await _v562_recover_after_sl_replace_failure(
                                        exchange, trade, prev_sl, "staircase_replace_failed"
                                    )
                            else:
                                STATS["sl_cancel_unverified"] = \
                                    STATS.get("sl_cancel_unverified", 0) + 1
                                trade.sl_health_state = "CANCEL_UNVERIFIED"
                                trade.sl_failure_reason = "staircase_cancel_unverified"
                                logger.warning(
                                    f"[Staircase] {symbol} cancel UNVERIFIED; "
                                    f"state preserved at prev_sl={prev_sl:.6f} level={prev_level}"
                                )
                        else:
                            # No prior SL id — place fresh candidate; commit level on success
                            place_ok, _oid = await OrderExecutor.place_sl(
                                exchange, trade, candidate_sl_stair)
                            if place_ok:
                                trade.current_sl = candidate_sl_stair
                                trade.staircase_level_hit = target_level
                                replace_ok = True
                            else:
                                trade.sl_covered_qty = prev_cov
                                trade.staircase_level_hit = prev_level
                                logger.critical(
                                    f"[Staircase] {symbol} fresh place_sl FAILED; arming software SL on existing model"
                                )
                                await _v562_recover_after_sl_replace_failure(
                                    exchange, trade, prev_sl, "staircase_fresh_place_failed"
                                )
                    if replace_ok:
                        logger.info(
                            f"[Staircase] {symbol} committed SL={trade.current_sl:.6f} "
                            f"level={trade.staircase_level_hit}"
                        )
                        await OpportunityTelegramNotifier.notify_exit_event(
                            trade,f"STAIRCASE SL LOCK {trade.staircase_level_hit}",
                            fill_px=cur,remaining=trade.remaining_position,
                            pnl_r=_v526_event_r(trade,cur),
                            extra=f"Verified SL={trade.current_sl:.10f}"
                        )

                # Trailing — v4.0.6 FIX E: candidate-first commit order.
                candidate_sl_trail = ExitManager.compute_trailing_sl(trade, cur, trade.atr)
                if (
                    bool(getattr(trade, "software_sl_active", False))
                    and bool(CONFIG.get("V564_SOFTWARE_SL_LOCAL_TRAIL_ENABLE", True))
                    and candidate_sl_trail
                    and candidate_sl_trail > trade.current_sl
                ):
                    trade.current_sl = float(candidate_sl_trail)
                    trade.sl_health_state = "SOFTWARE_SL_ACTIVE"
                    trade.sl_monitor_mode = "AUTO_SELL"
                    STATS["v564_software_local_trailing_updates"] = int(
                        STATS.get("v564_software_local_trailing_updates", 0) or 0
                    ) + 1
                    logger.info(
                        f"[V564-SL] {symbol} local trailing SL={trade.current_sl:.10g}"
                    )
                elif candidate_sl_trail and candidate_sl_trail > trade.current_sl:
                    prev_sl = trade.current_sl
                    prev_status = trade.status
                    prev_cov = trade.sl_covered_qty
                    replace_ok = False
                    # v4.0.9 DS-2 — same symbol lock wraps trailing mutations.
                    async with HandoffOwnership.lock_for(symbol):
                        if trade.sl_order_id:
                            cancel_ok = await OrderExecutor.cancel_order_safe(
                                exchange, trade.sl_order_id, symbol)
                            if cancel_ok:
                                trade.sl_order_id = None
                                place_ok, _oid = await OrderExecutor.place_sl(
                                    exchange, trade, candidate_sl_trail)
                                if place_ok:
                                    trade.current_sl = candidate_sl_trail
                                    trade.status = "trailing"
                                    replace_ok = True
                                else:
                                    trade.sl_covered_qty = prev_cov
                                    trade.status = prev_status
                                    logger.critical(
                                        f"[Trailing] {symbol} place_sl FAILED after cancel; "
                                        f"rolling back to prev_sl={prev_sl:.6f} and arming software SL"
                                    )
                                    await _v562_recover_after_sl_replace_failure(
                                        exchange, trade, prev_sl, "trailing_replace_failed"
                                    )
                            else:
                                STATS["sl_cancel_unverified"] = \
                                    STATS.get("sl_cancel_unverified", 0) + 1
                                trade.sl_health_state = "CANCEL_UNVERIFIED"
                                trade.sl_failure_reason = "trailing_cancel_unverified"
                                logger.warning(
                                    f"[Trailing] {symbol} cancel UNVERIFIED; "
                                    f"state preserved at prev_sl={prev_sl:.6f}"
                                )
                        else:
                            place_ok, _oid = await OrderExecutor.place_sl(
                                exchange, trade, candidate_sl_trail)
                            if place_ok:
                                trade.current_sl = candidate_sl_trail
                                trade.status = "trailing"
                                replace_ok = True
                            else:
                                trade.sl_covered_qty = prev_cov
                                trade.status = prev_status
                                logger.critical(
                                    f"[Trailing] {symbol} fresh place_sl FAILED; arming software SL on existing model"
                                )
                                await _v562_recover_after_sl_replace_failure(
                                    exchange, trade, prev_sl, "trailing_fresh_place_failed"
                                )

                if replace_ok and candidate_sl_trail:
                    await OpportunityTelegramNotifier.notify_exit_event(
                        trade,"TRAILING SL UPDATED",fill_px=cur,remaining=trade.remaining_position,
                        pnl_r=_v526_event_r(trade,cur),
                        extra=f"Verified SL={trade.current_sl:.10f}"
                    )

                # Time-based exit — v4.0.3 PATCH G: applies to any status that is
                # still open (entry_filled OR partial states after TP1). Route
                # through central finalize so DailyCircuitBreaker sees the R.
                try:
                    entry_dt = datetime.fromisoformat(trade.entry_time)
                    age_h = (datetime.now(timezone.utc) - entry_dt).total_seconds() / 3600.0
                    non_runner_states = ("entry_filled", "tp1_hit", "be_moved",
                                         "trailing", "tp2_hit")
                    should_exit = False
                    reason = "time_based_exit"
                    if trade.remaining_position > 0:
                        if trade.status in non_runner_states and \
                                age_h >= float((trade.exit_profile or {}).get("max_hold_hours", CONFIG["TIME_BASED_EXIT_HOURS"])):
                            should_exit = True
                        elif trade.status == "runner":
                            if bool(CONFIG.get("RUNNER_EXEMPT_FROM_TIME_EXIT", True)):
                                if age_h >= float(CONFIG.get("RUNNER_MAX_HOLD_HOURS", 24)):
                                    should_exit = True
                                    reason = "runner_max_hold_exit"
                            elif age_h >= float((trade.exit_profile or {}).get("max_hold_hours", CONFIG["TIME_BASED_EXIT_HOURS"])):
                                should_exit = True
                    if should_exit:
                        _pnl_pct = ((cur - float(trade.entry)) / max(float(trade.entry), 1e-12)) * 100.0
                        logger.warning(
                            f"[TimeExit] {symbol} status={trade.status} age={age_h:.2f}h "
                            f"reason={reason} entry={float(trade.entry):.8f} "
                            f"cur={cur:.8f} pnl_pct={_pnl_pct:.4f}%"
                        )
                        live_entries_block(
                            f"time_exit_reached_{symbol}",
                            where="V571.PositionManager",
                        )
                        # v4.5.73: time-based exit is control-plane only.
                        # It blocks NEW entries but MUST NOT generate a normal
                        # MARKET SELL. Natural exit remains TP/SL.
                        logger.warning(
                            f"[V573-TimeExit] {symbol}: no MARKET SELL issued; "
                            "position remains under TP/SL authority."
                        )
                        STATS["v571_time_exit_no_sell"] = int(
                            STATS.get("v571_time_exit_no_sell", 0) or 0
                        ) + 1
                        # The time-exit policy is an entry-control event, not a
                        # failed protection evaluation. Keep the PM lease healthy
                        # only when the already-active stop remains verified.
                        _pm_set_status(
                            symbol,
                            "PROTECTED" if _v563_trade_protection_healthy(trade)
                            else "INCOMPLETE:PROTECTION_UNHEALTHY_AT_TIME_EXIT",
                        )
                        continue
                except Exception as _time_exit_exc:
                    _v593_note_suppressed_exception(
                        "position_manager.time_exit_guard", _time_exit_exc
                    )
                    logger.warning(
                        f"[PositionManager] {symbol} time-exit evaluation suppressed: "
                        f"{type(_time_exit_exc).__name__}: {_time_exit_exc}"
                    )

                trade.last_update = datetime.now(timezone.utc).isoformat()
                # v4.2.2 FIX — non-blocking snapshot (worker thread) so the
                # PositionManager tick loop is never stalled by disk I/O.
                await DBManager.asave_trade_snapshot(trade)
                if _is_trade_closed_locally(symbol, trade):
                    _pm_set_status(symbol, "CLOSED")
                elif _v563_trade_protection_healthy(trade):
                    _pm_set_status(symbol, "PROTECTED")
                else:
                    _pm_set_status(symbol, "INCOMPLETE:PROTECTION_UNHEALTHY_AT_CYCLE_END")

            except Exception as e:
                _pm_set_status(symbol, f"ERROR:{type(e).__name__}:{str(e)[:120]}")
                logger.critical(f"[PositionManager] protection cycle incomplete for {symbol}: {type(e).__name__}: {e}")

        _pm_failed = {sym: state for sym, state in _pm_cycle_status.items()
                      if state not in {"PROTECTED", "CLOSED"}}
        _pm_managed_ids = []
        _pm_open_ids = []
        # A health lease covers exact positions, not a positive count. Reject a
        # trade that appeared, disappeared/replaced, or lost its stable identity
        # during this cycle; it will be evaluated on the next complete tick.
        for _sym, _trade in list(ACTIVE_TRADES.items()):
            _key = str(_sym)
            _identity = _v702_position_identity(_sym, _trade)
            if _identity:
                _pm_open_ids.append(_identity)
            _start_identity = _pm_cycle_identity_by_symbol.get(_key)
            if not _identity or not _start_identity:
                _pm_failed.setdefault(_key, "INCOMPLETE:POSITION_IDENTITY_MISSING")
                continue
            if _identity != _start_identity:
                _pm_failed.setdefault(_key, "INCOMPLETE:POSITION_IDENTITY_CHANGED_DURING_CYCLE")
                continue
            if _pm_cycle_status.get(_key) != "PROTECTED" or not _v563_trade_protection_healthy(_trade):
                _pm_failed.setdefault(_key, "INCOMPLETE:ACTIVE_POSITION_NOT_PROTECTED")
                continue
            _pm_managed_ids.append(_identity)
        _pm_open_ids = sorted(_pm_open_ids)
        _pm_managed_ids = sorted(_pm_managed_ids)
        if len(_pm_open_ids) != len(ACTIVE_TRADES) or len(set(_pm_open_ids)) != len(_pm_open_ids):
            _pm_failed.setdefault("__coverage__", "INCOMPLETE:OPEN_POSITION_IDENTITIES_NOT_UNIQUE")
        if set(_pm_managed_ids) != set(_pm_open_ids):
            _pm_failed.setdefault("__coverage__", "INCOMPLETE:POSITION_MANAGER_COVERAGE_MISMATCH")
        _pm_report = {
            "started_ts": _pm_cycle_started, "completed_ts": float(WALL_NOW()),
            "positions_at_start": len(_pm_cycle_symbols),
            "positions_open_at_end": len(ACTIVE_TRADES),
            "open_position_ids": _pm_open_ids,
            "managed_position_ids": _pm_managed_ids,
            "status_by_symbol": dict(_pm_cycle_status),
            "failed_by_symbol": _pm_failed,
            "healthy": not bool(_pm_failed),
            "source": "POSITION_MANAGER_EXACT_POSITION_IDENTITY_PROTECTION_EVALUATION",
        }
        STATS["v702_pm_cycle_report"] = _pm_report
        if _pm_failed:
            STATS["v702_pm_cycle_incomplete_total"] = int(STATS.get("v702_pm_cycle_incomplete_total", 0) or 0) + 1
        else:
            STATS["v702_pm_cycle_complete_total"] = int(STATS.get("v702_pm_cycle_complete_total", 0) or 0) + 1
        return _pm_report


# =============================================================================
#  v4.5.68 — STARTUP RECOVERED-TRADE PROTECTION RECONCILIATION
# =============================================================================

async def _v568_reconcile_recovered_protection(exchange) -> None:
    """Restore persisted protection state without inventing exchange state."""
    if not bool(CONFIG.get("V568_RESTART_PROTECTION_RECONCILE_ENABLE", True)):
        return
    if not ACTIVE_TRADES:
        return

    for symbol, trade in list(ACTIVE_TRADES.items()):
        try:
            qty=float(getattr(trade,"remaining_position",0.0) or 0.0)
            entry=float(getattr(trade,"entry",0.0) or 0.0)
            sl=float(getattr(trade,"current_sl",0.0) or getattr(trade,"original_sl",0.0) or 0.0)
            # A recovered BE/profit-lock stop at or above entry is valid.
            # Do not misclassify it as a malformed original entry stop.
            if qty<=0 or entry<=0 or sl<=0:
                live_entries_block(
                    f"recovered_trade_protection_invalid_{symbol}",
                    where="V568.startup_reconcile"
                )
                logger.critical(
                    f"[V568-START] invalid recovered trade {symbol}: "
                    f"qty={qty} entry={entry} sl={sl}"
                )
                continue

            native_id=str(getattr(trade,"sl_order_id","") or "")
            native_state=str(getattr(trade,"sl_health_state","") or "").upper()
            software=bool(getattr(trade,"software_sl_active",False))

            # Existing software protection is safe to re-arm because V564/V565
            # arming is idempotent and does not place an exit order.
            if software:
                ok=await _v560_arm_software_sl(
                    trade,"restart_rearm_existing_software_sl"
                )
                if ok:
                    trade.sl_monitor_mode="AUTO_SELL"
                    trade.sl_health_state="SOFTWARE_SL_ACTIVE"
                    await DBManager.asave_trade_snapshot(trade)
                    logger.info(
                        f"[V568-START] {symbol} software AUTO-SL restored "
                        f"SL={trade.current_sl:.10g}"
                    )
                else:
                    live_entries_block(
                        f"recovered_software_sl_arm_failed_{symbol}",
                        where="V568.startup_reconcile"
                    )
                continue

            # Persisted native SL: verify it before making any state change.
            if native_id and native_state=="CONFIRMED":
                try:
                    fetched=await safe_api_call(
                        "v568_recover_fetch_sl",
                        lambda: exchange.fetch_order(native_id,symbol),
                        retry_safe=True,
                    )
                    status=str((fetched or {}).get("status") or "").lower()
                    if status in {"open","new","accepted","triggered"}:
                        trade.sl_health_state="CONFIRMED"
                        trade.sl_last_verified_ts=MONO_NOW()
                        trade.protection_lease_ts=MONO_NOW()
                        trade.protection_lease_state="HEALTHY"
                        await DBManager.asave_trade_snapshot(trade)
                        continue
                    if status in {"closed","filled"}:
                        trade.sl_health_state="SL_HIT_PENDING_RECONCILE"
                        await DBManager.asave_trade_snapshot(trade)
                        logger.warning(
                            f"[V568-START] {symbol} persisted native SL is {status}; "
                            "normal reconciliation will determine final position state."
                        )
                        continue
                    trade.sl_health_state="NATIVE_SL_UNVERIFIED"
                    live_entries_block(
                        f"recovered_native_sl_unverified_{symbol}",
                        where="V568.startup_reconcile"
                    )
                    await DBManager.asave_trade_snapshot(trade)
                    continue
                except Exception as exc:
                    trade.sl_health_state="NATIVE_SL_UNVERIFIED"
                    live_entries_block(
                        f"recovered_native_sl_fetch_failed_{symbol}",
                        where="V568.startup_reconcile"
                    )
                    logger.critical(
                        f"[V568-START] {symbol} native SL verification failed: {exc}"
                    )
                    continue

            # No native SL id is present: restore automatic software protection.
            if not native_id:
                ok=await _v560_arm_software_sl(
                    trade,"restart_rearm_no_native_sl"
                )
                if ok:
                    trade.sl_health_state="SOFTWARE_SL_ACTIVE"
                    trade.sl_monitor_mode="AUTO_SELL"
                    await DBManager.asave_trade_snapshot(trade)
                    if bool(CONFIG.get("V568_RESTART_PROTECTION_NOTIFY_ENABLE",True)):
                        try:
                            await TelegramDispatcher.enqueue(
                                f"🟠 <b>RESTART PROTECTION RESTORED</b> {symbol}\n"
                                f"Model SL: {trade.current_sl:.10g}\n"
                                "<b>Automatic software SL is active.</b>"
                            )
                        except Exception as _notify_exc:
                            _v593_note_suppressed_exception(
                                "V568.restart_protection_notify", _notify_exc
                            )
                else:
                    live_entries_block(
                        f"recovered_no_protection_{symbol}",
                        where="V568.startup_reconcile"
                    )
        except Exception as exc:
            live_entries_block(
                f"recovered_trade_reconcile_exception_{symbol}",
                where="V568.startup_reconcile"
            )
            logger.critical(
                f"[V568-START] {symbol} recovery exception: {exc}"
            )



# =============================================================================
#  SECTION 37 — SUPERVISOR + MAIN LOOP
# =============================================================================

_V702_PROCESS_BOOT_ID = uuid.uuid4().hex

def _v702_atomic_heartbeat_write(path_value: str, payload: Dict[str, Any]) -> None:
    """Atomically publish a small runtime/PM heartbeat without blocking asyncio."""
    target = Path(str(path_value))
    target.parent.mkdir(parents=True, exist_ok=True)
    temp = target.with_name(target.name + f".{os.getpid()}.tmp")
    data = json.dumps(payload, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    temp.write_text(data, encoding="utf-8")
    os.replace(str(temp), str(target))

def _v702_position_identity(symbol: Any, trade: Any) -> Optional[str]:
    """Return a stable, non-empty identity for one currently-open trade."""
    try:
        _sym = str(symbol or getattr(trade, "symbol", "") or "").strip().upper()
        _trace = str(getattr(trade, "trace_id", "") or "").strip()
        if not _sym or not _trace:
            return None
        return f"{_sym}|{_trace}"
    except Exception:
        return None


def _v702_open_position_ids() -> List[str]:
    _ids = []
    for _symbol, _trade in list(ACTIVE_TRADES.items()):
        _identity = _v702_position_identity(_symbol, _trade)
        if _identity:
            _ids.append(_identity)
    return sorted(_ids)


def _v702_pm_heartbeat_payload() -> Dict[str, Any]:
    _open_ids = _v702_open_position_ids()
    _report = STATS.get("v702_pm_cycle_report", {})
    _managed_ids = []
    if isinstance(_report, dict) and bool(_report.get("healthy")):
        _managed_ids = sorted(set(str(x) for x in (_report.get("managed_position_ids", []) or []) if str(x)))
    return {
        "timestamp": float(time.time()),
        "boot_id": _V702_PROCESS_BOOT_ID,
        "pid": int(os.getpid()),
        "state": str(STATS.get("v702_pm_task_state", "STARTING")),
        "open_positions": int(len(ACTIVE_TRADES)),
        "open_position_ids": _open_ids,
        "managed_position_ids": _managed_ids,
        "healthy_ticks": int(STATS.get("v702_pm_healthy_ticks", 0) or 0),
        "source": "POSITION_MANAGER_SUCCESSFUL_CYCLE",
    }

async def _v702_runtime_heartbeat_task():
    """Independent process heartbeat; healthcheck uses it to detect a stalled PM."""
    path = str(os.environ.get("V702_RUNTIME_HEARTBEAT_FILE", "/tmp/unified_scalper_runtime_heartbeat.json"))
    interval = max(2.0, min(15.0, float(CONFIG.get("V702_RUNTIME_HEARTBEAT_INTERVAL_SEC", 5.0))))
    while _SHUTDOWN is None or not _SHUTDOWN.is_set():
        try:
            payload = {
                "timestamp": float(time.time()), "boot_id": _V702_PROCESS_BOOT_ID,
                "pid": int(os.getpid()), "state": str(LIVE_STATE.state.value if hasattr(LIVE_STATE.state, "value") else LIVE_STATE.state),
                "open_positions": int(len(ACTIVE_TRADES)),
                "open_position_ids": _v702_open_position_ids(),
                "pm_last_healthy_ts": float(STATS.get("v702_pm_last_healthy_ts", 0.0) or 0.0),
                "source": "INDEPENDENT_RUNTIME_WATCHDOG",
            }
            await asyncio.to_thread(_v702_atomic_heartbeat_write, path, payload)
            STATS["v702_runtime_heartbeat_last_write_ts"] = payload["timestamp"]
            STATS["v702_runtime_heartbeat_write_errors"] = 0
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            STATS["v702_runtime_heartbeat_write_errors"] = int(STATS.get("v702_runtime_heartbeat_write_errors", 0) or 0) + 1
            STATS["v702_runtime_heartbeat_last_error"] = f"{type(exc).__name__}:{str(exc)[:120]}"
            try:
                _software_sl_active = ProductionCapabilityGate.stop_mode() == "software_sl_only"
            except Exception:
                _software_sl_active = True  # Fail closed if stop mode cannot be resolved.
            if _software_sl_active and ACTIVE_TRADES:
                live_entries_block("runtime_heartbeat_write_failed_with_open_position", where="runtime_heartbeat")
        await asyncio.sleep(interval)

class Supervisor:

    @staticmethod
    async def run_loop(exchange, account_exchange=None):
        """Run public telemetry continuously; run private reconciliation only with an account client."""
        last_hb = 0.0
        last_consistency = 0.0
        while True:
            try:
                if KillSwitch.is_active():
                    LiveStateMachine.block("kill_switch_active", where="Supervisor")
                    await asyncio.sleep(5)
                    continue

                now = MONO_NOW()
                if now - last_hb >= float(CONFIG["HEARTBEAT_INTERVAL_SEC"]):
                    await Telemetry.emit_heartbeat()
                    last_hb = now

                if account_exchange is not None:
                    if now - last_consistency >= float(CONFIG["V4_CONSISTENCY_CHECK_INTERVAL_SEC"]):
                        await ConsistencyChecker.tick(account_exchange)
                        last_consistency = now
                    await LiveStateMachine.recover_runtime_if_safe(account_exchange)
                else:
                    STATS["v702_supervisor_private_checks_skipped_public_only"] = int(STATS.get("v702_supervisor_private_checks_skipped_public_only", 0) or 0) + 1
                StarvationGuard.tick()
                StarvationGuard.funnel_invariant_check()
                # V702 FINAL: retired drawdown halt has no supervisor authority.

                await asyncio.sleep(10)
            except Exception as e:
                logger.error(f"[Supervisor] {e}")
                await asyncio.sleep(5)


async def _position_manager_task(exchange):
    """Dedicated high-frequency protection/exit loop with an explicit health lease.

    The loop is independent from the market scanner. In software-SL mode its
    successful heartbeat is also a final new-entry prerequisite; a stalled or
    repeatedly failing worker therefore blocks additional exposure.
    """
    interval = max(0.20, float(CONFIG.get("POSITION_MANAGER_INTERVAL_SEC", 1.0)))
    STATS["v702_pm_task_state"] = "RUNNING"
    STATS["v702_pm_task_started_ts"] = float(WALL_NOW())
    # A task-start timestamp is not proof of a successful protection cycle.
    # Keep the lease invalid until PositionManager.tick (or a healthy idle cycle)
    # completes successfully for the first time.
    STATS["v702_pm_last_healthy_ts"] = 0.0
    STATS["v702_pm_healthy_ticks"] = 0
    STATS["v702_pm_last_error"] = None
    STATS["v702_pm_health_last_reason"] = "awaiting_first_healthy_cycle"
    logger.info(f"[V556-PM] dedicated position-manager task enabled interval={interval:.2f}s")
    try:
        while _SHUTDOWN is None or not _SHUTDOWN.is_set():
            t0 = MONO_NOW()
            try:
                if ACTIVE_TRADES:
                    _pm_result = await PositionManager.tick(exchange)
                    if not isinstance(_pm_result, dict) or not bool(_pm_result.get("healthy")):
                        _failed_symbols = dict((_pm_result or {}).get("failed_by_symbol", {}) or {}) if isinstance(_pm_result, dict) else {}
                        raise RuntimeError(f"position_protection_cycle_incomplete:{_failed_symbols}")
                # No open trades is a healthy idle cycle; an incomplete per-trade
                # evaluation deliberately leaves the previous health lease stale.
                next_ticks = int(STATS.get("v702_pm_healthy_ticks", 0) or 0) + 1
                payload = _v702_pm_heartbeat_payload()
                payload["timestamp"] = float(time.time())
                payload["healthy_ticks"] = next_ticks
                await asyncio.to_thread(
                    _v702_atomic_heartbeat_write,
                    str(os.environ.get("V702_PM_HEARTBEAT_FILE", "/tmp/unified_scalper_pm_heartbeat.json")),
                    payload,
                )
                STATS["v702_pm_last_healthy_ts"] = float(WALL_NOW())
                STATS["v702_pm_healthy_ticks"] = next_ticks
                STATS["v702_pm_last_error"] = None
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                STATS["v556_pm_task_errors"] = int(STATS.get("v556_pm_task_errors", 0) or 0) + 1
                STATS["v702_pm_last_error"] = f"{type(exc).__name__}:{str(exc)[:160]}"
                logger.critical(f"[V556-PM] protection task error: {exc}")
            elapsed = MONO_NOW() - t0
            await asyncio.sleep(max(0.05, interval - elapsed))
    finally:
        STATS["v702_pm_task_state"] = "STOPPED"
        STATS["v702_pm_task_stopped_ts"] = float(WALL_NOW())


