class ExchangeFactory:

    @staticmethod
    def create_mexc_public_async():
        """Create an unauthenticated MEXC Spot client for public market data only.

        Public OHLCV, ticker, market metadata and order-book reads do not require
        wallet balance or private API credentials. This client must never be used
        for private account or order operations.
        """
        if not _CCXT_OK:
            logger.critical(f"[Exchange] ccxt not available: {_CCXT_IMPORT_ERR}")
            raise SystemExit("ccxt_missing")
        ex = ccxt_async.mexc({
            "enableRateLimit": True,
            "options": {"defaultType": "spot"},
        })
        STATS["v702_public_market_client_created"] = True
        STATS["v702_public_market_client_authenticated"] = False
        return ex

    @staticmethod
    def create_mexc_async():
        if not _CCXT_OK:
            logger.critical(f"[Exchange] ccxt not available: {_CCXT_IMPORT_ERR}")
            raise SystemExit("ccxt_missing")
        if not ENV.get("MEXC_API_KEY") or not ENV.get("MEXC_API_SECRET"):
            logger.critical(
                "[V702-BOOT-STOP][V702-ACCOUNT-STOP] MEXC_API_KEY and MEXC_API_SECRET are required only for private account/position operations. "
                "Public market discovery uses the unauthenticated client and does not require these credentials. "
                "Set both through the host secret manager; values are never logged."
            )
            raise SystemExit("missing_exchange_secrets")
        ex = ccxt_async.mexc({
            "apiKey": ENV["MEXC_API_KEY"],
            "secret": ENV["MEXC_API_SECRET"],
            "enableRateLimit": True,
            "options": {"defaultType": "spot"},
        })
        return ex


# =============================================================================
#  SECTION 39 — SIGNAL HANDLING (graceful shutdown)
# =============================================================================

_SHUTDOWN = asyncio.Event() if hasattr(asyncio, "Event") else None


def _install_signal_handlers(loop: Optional[asyncio.AbstractEventLoop] = None) -> bool:
    """Install SIGINT/SIGTERM handlers on the ACTIVE event loop only.

    Passing the loop explicitly from run_bot() prevents the v4.5.92 regression
    where get_running_loop() was called from synchronous main() before
    asyncio.run() had started the loop.  The helper remains fail-soft for
    platforms that do not support add_signal_handler (for example Windows),
    while recording the failure explicitly.
    """
    try:
        active_loop = loop if loop is not None else asyncio.get_running_loop()
        for s in (signal.SIGINT, signal.SIGTERM):
            active_loop.add_signal_handler(
                s, lambda: _SHUTDOWN.set() if _SHUTDOWN else None
            )
        STATS["signal_handlers_installed"] = int(
            STATS.get("signal_handlers_installed", 0) or 0
        ) + 1
        return True
    except Exception as e:
        try:
            STATS["signal_handler_install_errors"] = (
                int(STATS.get("signal_handler_install_errors", 0) or 0) + 1
            )
        except Exception as _stats_e:
            logger.debug(f"[SignalHandlers] telemetry update suppressed: {_stats_e}")
        logger.warning(f"[SignalHandlers] install suppressed: {e}")
        return False


