                                    int(_m.get("post_cost_target_viable_signals", 0) or 0), int(_m.get("post_cost_target_capped_signals", 0) or 0),
                                    _m.get("avg_signal_cost_pct"), int(_m.get("samples", 0) or 0),
                                    int(_m.get("resolved", 0) or 0), int(_m.get("pending", 0) or 0),
