def _v525_validate_opportunity_telegram_config() -> bool:
    try:
        vals=[
            float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_C",62.0)),
            float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_B",66.0)),
            float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_A",70.0)),
            float(CONFIG.get("TELEGRAM_OPPORTUNITY_GRADE_A_PLUS",75.0)),
        ]
        if vals != sorted(vals):
            logger.critical("[V525] opportunity grade thresholds are not monotonic")
            return False
        if float(CONFIG.get("TELEGRAM_OPPORTUNITY_MIN_SCORE",62.0)) < vals[0]:
            logger.critical("[V525] opportunity min score below grade-C floor")
            return False
        return True
    except Exception as exc:
        logger.critical(f"[V525] opportunity config validation failed: {exc}")
        return False


def _v550_fee_target_rescue_self_test() -> Tuple[bool, str]:
    """Offline arithmetic check for the fee-target expansion lane."""
    try:
        old_enable = CONFIG.get("V550_FEE_TARGET_RESCUE_ENABLE", True)
        CONFIG["V550_FEE_TARGET_RESCUE_ENABLE"] = True

        cases = [
            ("LTC", 50.34, 50.170286, 50.509714, 50.679429, 51.188571, 40.0, 66.4),
            ("BNB", 695.74, 694.518571, 696.961429, 698.182857, 701.847143, 40.0, 68.5),
        ]
        for name, entry, sl, tp1, tp2, tp3, notional, score in cases:
            ok, n1, n2, n3, reason = V420FeeRescue.try_expand_targets(
                entry, sl, tp1, tp2, tp3, notional, score, "PULLBACK / PULLBACK"
            )
            if not ok:
                return False, f"{name}:rescue_not_found:{reason}"
            detail = SizingEngine.fee_viability_detail(
                entry, sl, n1, n2, notional
            )
            if not bool(detail.get("ok", False)):
                return False, f"{name}:rescued_geometry_still_unviable:{detail}"
            r1 = (n1-entry)/(entry-sl)
            r2 = (n2-entry)/(entry-sl)
            # v4.5.51 — the rescue must actually increase the TP geometry for
            # the production fee-failure cases, while staying within bounds.
            if n1 <= tp1 or n2 <= tp2:
                return False, f"{name}:targets_not_expanded"
            if name == "BNB" and r1 < 1.90:
                return False, f"{name}:dynamic_rr_too_low:{r1:.3f}"
            if r1 > float(CONFIG.get("V551_FEE_TARGET_MAX_TP1_RR", 3.00)) + 1e-9:
                return False, f"{name}:tp1_rr_cap_broken"
            if r2 > float(CONFIG.get("V551_FEE_TARGET_MAX_TP2_RR", 6.00)) + 1e-9:
                return False, f"{name}:tp2_rr_cap_broken"
            if not (sl < entry < n1 < n2 < n3):
                return False, f"{name}:ordering_broken"
        CONFIG["V550_FEE_TARGET_RESCUE_ENABLE"] = old_enable
        return True, "PASS"
    except Exception as e:
        try:
            CONFIG["V550_FEE_TARGET_RESCUE_ENABLE"] = old_enable
        except Exception:
            _v647_record_suppressed_exception()
        return False, f"exception:{type(e).__name__}:{e}"

def _validate_config_base() -> bool:
    if not _v525_validate_opportunity_telegram_config():
        return False
    """Public helper for external tests: returns True if config is coherent."""
    try:
        ConfigValidators.tp_invariant_check()
    except SystemExit:
        return False
    # v4.2.0 — boot-time validation for the V420 unblock layer.
    try:
        _v420_boot_validate()
    except Exception as _v420_be:
        try:
            logger.warning(f"[V420] boot validator suppressed: {_v420_be}")
        except Exception:
            _v647_record_suppressed_exception()
    # v4.2.5 — Bearish Recovery boot validation (dead-config / threshold sanity).
    try:
        _v425_boot_validate()
    except Exception as _v425_be:
        try:
            logger.warning(f"[V425] boot validator suppressed: {_v425_be}")
        except Exception:
            _v647_record_suppressed_exception()
    # v4.0.7-MSE — fail-closed self-tests for the Multi-Strategy layer.
    # If any test fails and MSE is enabled, we auto-disable it so the bot
    # still boots (falls back to legacy OpportunityRouter transparently).
    try:
        ok, failures = _mse_self_tests()
        if not ok and bool(CONFIG.get("MSE_ENABLED", True)):
            logger.critical(
                f"[MSE.selftest] disabling MSE due to failures: {failures}"
            )
            CONFIG["MSE_ENABLED"] = False
    except Exception as _mse_e:
        logger.critical(f"[MSE.selftest] exception: {_mse_e} — disabling MSE")
        CONFIG["MSE_ENABLED"] = False
    return True


def main():
    # Signal handlers are installed inside run_bot() on the live asyncio loop.
    # Installing them here would be too early because asyncio.run() has not
    # created its running loop yet.
    # Default mode: dynamic TOP-500 source MEXC SPOT/USDT by 24h quote volume.
    # Optional SCALPER_UNIVERSE remains available as an explicit manual override.
    uni_env = os.environ.get("SCALPER_UNIVERSE", "").strip()
    if uni_env:
        universe = [s.strip() for s in uni_env.split(",") if s.strip()]
        logger.info(f"[Main] Manual SCALPER_UNIVERSE override detected: {len(universe)} symbols")
    else:
        universe = []
        logger.info(
            f"[Main] Dynamic liquidity universe enabled: TOP {int(CONFIG.get('TOP_LIQUIDITY_SYMBOLS',500))} "
            f"MEXC SPOT/USDT symbols by 24h quote volume")
    # v4.2.2 FIX — version string now reflects the ACTUAL build.
    logger.info("[V702-R40-PACKAGE] small_net=%s min_net_tp1_pct=%.3f%% spread_fallback=%.3f%% slippage_per_side=%.3f%% tp_splits=%.2f/%.2f/%.2f macro4h_min=%d",
                bool(CONFIG.get("V702_SMALL_NET_PROFIT_MODE_ENABLE", False)),
                float(CONFIG.get("V702_SMALL_NET_MIN_NET_PROFIT_PCT", 0.10)),
                float(CONFIG.get("V702_SMALL_NET_SPREAD_FALLBACK_PCT", 0.15)),
                float(CONFIG.get("V702_SMALL_NET_SLIPPAGE_PER_SIDE_PCT", 0.05)),
                float(CONFIG.get("TP1_EXIT_PCT", 0.60)), float(CONFIG.get("TP2_EXIT_PCT", 0.30)),
                float(CONFIG.get("RUNNER_KEEP_PCT_AT_TP3", 0.10)),
                int(CONFIG.get("BTC_SHARED_CONTEXT_MIN_CANDLES_4H", 0) or 0))
    _runtime_identity = globals().get("FINAL_CANONICAL_RUNTIME") or {}
    _post_audit_patch_revision = str(
        _runtime_identity.get("active_post_audit_patch_revision_current")
        or _runtime_identity.get("active_post_audit_patch_revision")
        or "UNREPORTED"
    )
    _audit_merge_revision = str(
        _runtime_identity.get("active_audit_merge_revision_current") or "UNREPORTED"
    )
    _entrypoint_identity_revision = str(
        _runtime_identity.get("active_entrypoint_identity_revision_current") or "UNREPORTED"
    )
    _distribution_release = str(
        _runtime_identity.get("active_distribution_release_tag")
        or _runtime_identity.get("active_release_tag")
        or globals().get("V702_FINAL_CANONICAL_RELEASE", "V702")
    )
    logger.info(
        f"[Main] Starting Unified Scalper release={_distribution_release} "
        f"package_revision={globals().get('V702_PACKAGE_AUDIT_REVISION', 'UNKNOWN')} "
        f"post_audit_patch_revision={_post_audit_patch_revision} "
        f"audit_merge_revision={_audit_merge_revision} "
        f"entrypoint_identity_revision={_entrypoint_identity_revision} "
        f"runtime_identity={SCRIPT_VERSION} provenance={V699_FINAL_IDENTITY} with {len(universe)} symbols"
    )
    # v4.2.2 FIX — boot validation is FAIL-CLOSED. Previously validate_config()
    # was called and its False return silently ignored, so a broken config
    # still reached the live loop. Now: any failure (False return, SystemExit
    # from tp_invariant_check, or an unexpected exception) aborts the boot
    # with SystemExit("config_invalid") BEFORE the exchange loop starts.
    _startup_validation_started = float(MONO_NOW())
    _cfg_ok = None
    logger.info(
        "[V702-STARTUP-PHASE] phase=validate_config_begin release=%s package_revision=%s",
        _distribution_release,
        globals().get("V702_PACKAGE_AUDIT_REVISION", "UNKNOWN"),
    )
    try:
        _cfg_ok = validate_config()
    except SystemExit as _se:
        # Preserve the precise fail-closed exit while making the failed stage
        # explicit in hosted logs (Railway may truncate the final traceback).
        logger.critical("[V702-BOOT-STOP] stage=validate_config reason=%s", str(_se)[:240])
        raise
    except Exception as _e:
        # Preserve the actual traceback in Railway/container logs. The previous
        # message-only record reduced a validator crash to "config_invalid".
        logger.critical(
            "[V702-BOOT-FAIL] validate_config raised; refusing to boot",
            exc_info=True,
        )
        raise SystemExit("config_invalid")
    finally:
        # The static AST has no runtime role after the canonical validator.
        _v702_release_startup_memory()
        try:
            logger.info(
                "[V702-STARTUP-PHASE] phase=validate_config_end passed=%s elapsed_sec=%.3f",
                bool(_cfg_ok), max(0.0, float(MONO_NOW()) - _startup_validation_started),
            )
        except Exception:
            pass
    if not _cfg_ok:
        # Report the *active* terminal validators. Older deployments printed only
        # R23/V704 fields here, which can be empty when the A7-A24 terminal layer
        # rejects startup; that obscures the actual failing contract.
        def _compact_validation_report(_report, _depth=0):
            if not isinstance(_report, dict) or _depth > 2:
                return {"type": type(_report).__name__}
            _out = {}
            for _flag in ("pass", "base", "previous_validation", "retry_used", "historical", "superseded_by", "revision", "closure"):
                if _flag in _report:
                    _value = _report.get(_flag)
                    _out[_flag] = (str(_value)[:180] if isinstance(_value, str) else _value)
            _failed = _report.get("failed")
            _checks = _report.get("checks")
            if not isinstance(_failed, list) and isinstance(_checks, dict):
                _failed = [str(_k) for _k, _v in _checks.items() if not bool(_v)]
            elif not isinstance(_failed, list):
                _failed = [str(_k) for _k, _v in _report.items()
                           if isinstance(_v, bool) and not _v and str(_k) != "pass"]
            if isinstance(_failed, list) and _failed:
                _out["failed"] = [str(_x) for _x in _failed[:25]]
            if isinstance(_checks, dict):
                _out["check_count"] = len(_checks)
            if _report.get("error"):
                _out["error"] = str(_report.get("error"))[:240]
            _details = _report.get("details")
            if isinstance(_details, dict):
                _out["details"] = {
                    str(_k): (str(_v)[:180] if not isinstance(_v, (bool, int, float, type(None))) else _v)
                    for _k, _v in list(_details.items())[:8]
                }
            for _nested in ("report", "a24_report"):
                if isinstance(_report.get(_nested), dict):
                    _out[_nested] = _compact_validation_report(_report[_nested], _depth + 1)
            return _out

        _active_validation_diagnostics = {}
        _always_report_names = {
            "v702_a23_final_validation", "v702_a24_final_validation",
            "v702_a23_terminal_self_test", "v702_a24_terminal_self_test",
            "v702_r23_final_validation", "v702_r23_validation_components",
            "v702_r23_failed_components", "v699_full_validation_observability",
            "v699_observability_closure_test",
        }
        for _name, _report in sorted(STATS.items()):
            _name_s = str(_name)
            if not isinstance(_report, dict):
                continue
            _checks = _report.get("checks") if isinstance(_report.get("checks"), dict) else {}
            _failed_checks = [str(_k) for _k, _v in _checks.items() if not bool(_v)]
            _failed_flag = (_report.get("pass") is False or bool(_failed_checks)
                            or bool(_report.get("failed")))
            _is_validation_report = (
                _name_s in _always_report_names
                or (_name_s.startswith("v702_r") and
                    (_name_s.endswith("_final_validation") or _name_s.endswith("_final_self_test")))
            )
            if _is_validation_report and (_failed_flag or _name_s in _always_report_names):
                _active_validation_diagnostics[_name_s] = _compact_validation_report(_report)
        logger.critical(
            "[V702-CONFIG] active_terminal_validation_diagnostics=%s",
            _active_validation_diagnostics or {"status": "active reports unavailable; refusing to boot"},
        )
        # Retain legacy fields but label them as historical/compatibility telemetry.
        logger.critical(
            "[V702-CONFIG] legacy_R23_diagnostics failed=%s components=%s",
            STATS.get("v702_r23_failed_components", []),
            STATS.get("v702_r23_validation_components", {}),
        )
        logger.critical(
            "[V704-CONFIG] legacy_validation_details first=%s retry=%s retry_used=%s failed_checks=%s",
            STATS.get("v704_validation_first_pass"),
            STATS.get("v704_validation_retry_pass"),
            STATS.get("v704_validation_retry_used", False),
            STATS.get("v704_validation_failed_checks", []),
        )
        logger.critical("[Main] canonical validate_config returned False — refusing to boot")
        raise SystemExit("config_invalid")
    # The LIVE epoch and watchdog must not be armed until every terminal config
    # invariant above has passed. A failed configuration exits without arming.
    try:
        _v699_arm_live_epoch()
        logger.info("[V702-STARTUP-PHASE] phase=runtime_epoch_armed entry_policy=%s",
                    FINAL_CANONICAL_RUNTIME.get("effective_entry_policy", "UNKNOWN"))
    except Exception as _arm_exc:
        logger.critical("[V702-BOOT] runtime epoch arm failed after validation: %s", _arm_exc)
        raise SystemExit("runtime_epoch_arm_failed")
    try:
        logger.info("[V702-STARTUP-PHASE] phase=run_bot_enter universe_symbols=%d", len(universe))
        asyncio.run(run_bot(universe))
    except KeyboardInterrupt:
        logger.info("[Main] KeyboardInterrupt — shutting down")
    except SystemExit as se:
        logger.critical(f"[Main] SystemExit: {se}")
        raise
    except Exception:
        # Keep an explicit crash marker and full traceback in hosted logs.
        # Re-raise unchanged so the process supervisor still sees the failure;
        # this is observability, not a fail-open recovery path.
        logger.critical(
            "[V702-CRASH] uncaught runtime exception; process will exit with failure",
            exc_info=True,
        )
        raise


# =============================================================================
#  SECTION V4.2.0 — UNBLOCK & SCALP-PACK COMPLETION LAYER
#  (additive, flag-gated, fail-closed; NO invariant of prior layers is broken)
# -----------------------------------------------------------------------------
#  Root causes addressed vs live heartbeat pattern
#    G/E/Q/S=13854/3/0/0  cd_skip=6822  regime=BULLISH
#    top: reject.cooldown.symbol_scan / reject.structural.no_family_matched /
#         reject.htf.family_regime_disallowed
#
#  This layer:
#   (V420-A) Cooldown segmentation: scan / reentry / execution — with hard
#            enforcement that scan cooldown is ARMED ONLY post-microstruct.
#   (V420-B) Micro-BOS/Retest thresholds regime-aware softening (bounded).
#   (V420-C) Router auditor: fixes MEAN_REVERSION mis-classification in
#            BULLISH regime (RSI must be truly ≤ 32 on a CLOSED bar).
#   (V420-D) Family policy audit + BULLISH-safe defaults (Momentum/LSR added).
#   (V420-E) Adaptive score floor keyed on rolling E/G recall rate.
#   (V420-F) Regime-aware family weights (soft ranking booster only).
#   (V420-G) Quantum Score Tie-Breaker (ranking layer; never a rejection).
#   (V420-H) Order-Block detection (full: body>55% + volume>1.7x + freshness).
#   (V420-I) Equal-lows sweep detection (stronger than legacy).
#   (V420-J) Volume Delta / Relative-Strength-vs-BTC score modifiers.
#   (V420-K) Fee-viability rescue (bounded soft-accept for high-score setups).
#   (V420-L) P3 Penalty Cap (aggregate soft penalties bounded by tier).
#   (V420-M) Canonical Decision Service (single arbitration point with
#            divergence telemetry — read-only observer, never overrides
#            an existing hard reject).
#   (V420-N) Rejection heatmap: family x stage x regime x tier x reason.
#   (V420-O) Funnel Health Watchdog (auto strict→relaxed toggle, bounded).
#   (V420-P) Family-aware backoff keying (symbol,family) instead of symbol.
#
#  Non-negotiables preserved:
#    * LONG-ONLY spot on MEXC. No shorts. No leverage. No futures.
#    * Fail-closed SL chain: exchange SL → software SL → emergency close.
#    * Balance-truth model still first (P22 seed order).
#    * DailyCircuitBreaker / KillSwitch / Watchdog remain authoritative.
#    * Telemetry NEVER decides an entry; it only ranks and observes.
# =============================================================================

# ---------------------------------------------------------------------------
# V420 CONFIG UPDATE — every knob below is fully overridable via env / config.
