# ---------------------------------------------------------------------------
# V420-STATE: single lock-guarded state bag for the layer.
# ---------------------------------------------------------------------------
class _V420State:
    _lock = threading.RLock()
    scan_cooldown_ts: Dict[str, float] = {}
    execution_cooldown_ts: Dict[str, float] = {}
    family_backoff: Dict[Tuple[str, str], Tuple[int, float]] = {}
    recall_hist: deque = deque(maxlen=4096)      # (ts, "G"|"E"|"S")
    nfm_hist: deque = deque(maxlen=4096)          # timestamps of no-family-matched events
    adaptive_floor: float = float(CONFIG.get("MIN_LIVE_SCORE", 70))
    heatmap: Dict[Tuple[str, str, str, str, str], int] = defaultdict(int)
    relaxed_mode_until_ts: float = 0.0
    canonical_divergence: int = 0
    penalty_accum: Dict[str, float] = defaultdict(float)  # per (symbol,family) key

    @classmethod
    def note_g(cls) -> None:
        with cls._lock:
            cls.recall_hist.append((MONO_NOW(), "G"))
    @classmethod
    def note_e(cls) -> None:
        with cls._lock:
            cls.recall_hist.append((MONO_NOW(), "E"))
    @classmethod
    def note_s(cls) -> None:
        with cls._lock:
            cls.recall_hist.append((MONO_NOW(), "S"))
    @classmethod
    def note_nfm(cls) -> None:
        with cls._lock:
            cls.nfm_hist.append(MONO_NOW())
    @classmethod
    def nfm_count(cls, window_sec: Optional[float] = None) -> int:
        w = float(window_sec or CONFIG.get("V420_RECALL_WINDOW_SEC", 900))
        now = MONO_NOW()
        with cls._lock:
            return sum(1 for ts in cls.nfm_hist if now - ts <= w)
    @classmethod
    def recall_rate(cls, window_sec: Optional[float] = None) -> Tuple[float, int, int, int]:
        w = float(window_sec or CONFIG.get("V420_RECALL_WINDOW_SEC", 900))
        now = MONO_NOW()
        with cls._lock:
            g = e = s = 0
            for ts, tag in list(cls.recall_hist):
                if now - ts > w:
                    continue
                if tag == "G": g += 1
                elif tag == "E": e += 1
                elif tag == "S": s += 1
            rate = (e / g) if g > 0 else 0.0
            return rate, g, e, s


# ---------------------------------------------------------------------------
# V420-A — SEGMENTED COOLDOWNS.
# Enforce post_microstruct scan cooldown ALWAYS in LIVE mode (unless a dev
# flag explicitly overrides). Provides independent reentry / execution buckets.
# ---------------------------------------------------------------------------
class V420Cooldowns:
    @staticmethod
    def enforce_scan_mode() -> None:
        if not CONFIG.get("V420_COOLDOWN_SEGMENT_ENABLE", True):
            return
        if not CONFIG.get("V420_SCAN_MODE_FORCE_POSTMS", True):
            return
        cur = str(CONFIG.get("SYMBOL_COOLDOWN_MODE", "post_microstruct")).lower()
        if cur == "pre_gate":
            # Silent auto-correct to fail-safe posture. Reset once, log once.
            CONFIG["SYMBOL_COOLDOWN_MODE"] = "post_microstruct"
            STATS["v420_scan_mode_autocorrected"] = \
                STATS.get("v420_scan_mode_autocorrected", 0) + 1
            try:
                logger.warning("[V420] SYMBOL_COOLDOWN_MODE=pre_gate auto-corrected "
                               "to post_microstruct (V420_SCAN_MODE_FORCE_POSTMS).")
            except Exception:
                _v647_record_suppressed_exception()
        # Enforce the reduced scan window if the config uses a legacy high value.
        try:
            scan_sec = float(CONFIG.get("V420_SCAN_COOLDOWN_SEC", 60))
            legacy = float(CONFIG.get("SYMBOL_COOLDOWN_SEC", 180) or 180)
            if legacy > scan_sec:
                CONFIG["SYMBOL_COOLDOWN_SEC"] = scan_sec
        except Exception:
            _v647_record_suppressed_exception()

    @staticmethod
    def execution_blocked(symbol: str) -> bool:
        if not CONFIG.get("V420_COOLDOWN_SEGMENT_ENABLE", True):
            return False
        sec = float(CONFIG.get("V420_EXECUTION_COOLDOWN_SEC", 30))
        if sec <= 0:
            return False
        with _V420State._lock:
            last = float(_V420State.execution_cooldown_ts.get(symbol, 0.0) or 0.0)
        return last > 0 and (MONO_NOW() - last) < sec

    @staticmethod
    def arm_execution(symbol: str) -> None:
        with _V420State._lock:
            _V420State.execution_cooldown_ts[symbol] = MONO_NOW()


# ---------------------------------------------------------------------------
# V420-B — BOUNDED MICROSTRUCTURE SOFTENING (BULLISH ONLY).
# We DO NOT mutate the strict thresholds; we compute effective values
# per-call, keyed on regime. Bearish and neutral keep the original strict
# values byte-for-byte.
# ---------------------------------------------------------------------------
def v420_effective_bos_thresholds(regime: str) -> Tuple[float, float, float]:
    """Return effective (min_break, body_ratio, volume_ratio) per regime.
    Bullish + master flag on → softened; else strict originals."""
    strict = (float(CONFIG.get("MICRO_BOS_MIN_BREAK", 0.0006)),
              float(CONFIG.get("BOS_BODY_MIN_RATIO", 0.45)),
              0.80)
    try:
        if not CONFIG.get("V420_MICRO_SOFTENING_ENABLE", True):
            return strict
        if str(regime).upper() != "BULLISH":
            return strict
        return (float(CONFIG.get("V420_MIN_BREAK_BULL",   strict[0])),
                float(CONFIG.get("V420_BOS_BODY_MIN_RATIO_BULL", strict[1])),
                float(CONFIG.get("V420_BOS_VOLUME_RATIO_BULL",   strict[2])))
    except Exception:
        return strict


# ---------------------------------------------------------------------------
# V420-C — ROUTER AUDITOR: Fix MEAN_REVERSION mis-classification in BULLISH.
# The legacy detector emits MEAN_REVERSION whenever RSI(5m)<=32. In a strong
# BULLISH regime this is almost always a shallow noise dip, not a true
# reversion setup. Auditor demotes such candidates unless a real oversold
# CLOSED bar exists AND a second-order confirmation (BB lower touch OR ATR
# contraction) is present.
# ---------------------------------------------------------------------------
class V420RouterAuditor:
    @staticmethod
    def audit_family(family: str, meta: Dict[str, Any],
                     regime: str, df_5m) -> Tuple[str, Dict[str, Any]]:
        if not CONFIG.get("V420_ROUTER_AUDIT_ENABLE", True):
            return family, meta
        try:
            fam = str(family or "").upper()
            if fam != "MEAN_REVERSION":
                return family, meta
            if str(regime).upper() != "BULLISH":
                return family, meta
            # Strict re-check on CLOSED bar
            rsi = Indicators.rsi(df_5m["close"], CONFIG["RSI_PERIOD"])
            if rsi is None:
                STATS["v420_mr_demote_no_rsi"] = STATS.get("v420_mr_demote_no_rsi", 0) + 1
                return "TREND_CONTINUATION", {**meta, "family": "TREND_CONTINUATION",
                                              "audited_from": "MEAN_REVERSION",
                                              "audit_reason": "rsi_unavailable"}
            r_closed = float(rsi.iloc[-2])
            # NaN / non-finite RSI in a strong BULLISH tape → not a real oversold; demote.
            if not math.isfinite(r_closed):
                STATS["v420_mr_demote_rsi_nan"] = STATS.get("v420_mr_demote_rsi_nan", 0) + 1
                return "TREND_CONTINUATION", {**meta, "family": "TREND_CONTINUATION",
                                              "audited_from": "MEAN_REVERSION",
                                              "audit_reason": "rsi_nan"}
            if r_closed > 32.0:
                STATS["v420_mr_demote_rsi_gt_32"] = STATS.get("v420_mr_demote_rsi_gt_32", 0) + 1
                return "TREND_CONTINUATION", {**meta, "family": "TREND_CONTINUATION",
                                              "audited_from": "MEAN_REVERSION",
                                              "audit_reason": f"rsi_closed={r_closed:.2f}"}
            return family, meta
        except Exception as e:
            STATS["v420_router_audit_error"] = STATS.get("v420_router_audit_error", 0) + 1
            return family, meta


# ---------------------------------------------------------------------------
# V420-D — FAMILY POLICY AUDIT.
# The legacy FAMILY_POLICY_MOMENTUM_EXPANSION/LSR allowed_regimes are OK,
# but Momentum's allowed set omits BULLISH-strict recall in some rollouts.
# We audit at boot to guarantee every long-suitable family accepts BULLISH.
# ---------------------------------------------------------------------------
def _v420_audit_family_policies() -> None:
    if not CONFIG.get("V420_FAMILY_POLICY_AUDIT_ENABLE", True):
        return
    long_families = ("PULLBACK", "BREAKOUT_RETEST", "BREAKOUT_CONTINUATION",
                     "TREND_CONTINUATION", "MOMENTUM_EXPANSION",
                     "LIQUIDITY_SWEEP_REVERSAL")
    fixed = 0
    for f in long_families:
        key = f"FAMILY_POLICY_{f}"
        pol = CONFIG.get(key)
        if not isinstance(pol, dict):
            continue
        allowed = set(pol.get("allowed_regimes", ()))
        if "BULLISH" not in allowed:
            allowed.add("BULLISH")
            pol["allowed_regimes"] = tuple(sorted(allowed))
            CONFIG[key] = pol
            fixed += 1
    # MEAN_REVERSION intentionally NOT forced into BULLISH; router auditor demotes
    # its candidates instead. This preserves the counter-trend intent.
    if fixed:
        try:
            logger.warning(f"[V420] FamilyPolicy audit auto-added BULLISH to "
                           f"{fixed} long-suitable families.")
        except Exception:
            _v647_record_suppressed_exception()
    STATS["v420_family_policy_audit_fixed"] = fixed


# ---------------------------------------------------------------------------
# V420-E — ADAPTIVE SCORE FLOOR.
# Reads rolling recall (E/G) over V420_RECALL_WINDOW_SEC. Adaptive updates may
# raise the floor when warranted, but the effective live floor is bounded to
# >= 70 in every path. Safety-latch cycles do not collect score-relief evidence.
# ---------------------------------------------------------------------------
class V420AdaptiveFloor:
    @staticmethod
    def compute() -> float:
        if not CONFIG.get("V420_ADAPTIVE_SCORE_FLOOR_ENABLE", True):
            return float(CONFIG["MIN_LIVE_SCORE"])
        try:
            rate, g, e, s = _V420State.recall_rate()
            live_floor = max(70.0, float(CONFIG.get("MIN_LIVE_SCORE", 70.0) or 70.0))
            base = max(live_floor, float(_V420State.adaptive_floor))
            lo = max(live_floor, float(CONFIG.get("V420_ADAPTIVE_FLOOR_MIN", 70.0)))
            hi = max(lo, float(CONFIG.get("V420_ADAPTIVE_FLOOR_MAX", 78.0)))
            step_dn = float(CONFIG.get("V420_ADAPTIVE_STEP_DOWN", 2.0))
            step_up = float(CONFIG.get("V420_ADAPTIVE_STEP_UP", 1.0))
            target = float(CONFIG.get("V420_RECALL_TARGET_PCT", 0.02))
            if g < 100:
                # not enough samples → keep current
                return base
            if rate < target:
                base = max(lo, base - step_dn)
            elif rate > (target * 3.0):
                base = min(hi, base + step_up)
            # Legacy relaxed mode may add an adaptive step-down, but `lo` is
            # clamped to the global live floor above; no runtime path can reduce
            # the effective live admission floor below 70.
            try:
                if V420FunnelWatchdog.is_relaxed():
                    base = max(lo, base - step_dn)
            except Exception:
                _v647_record_suppressed_exception()
            _V420State.adaptive_floor = base
            return base
        except Exception:
            return float(CONFIG["MIN_LIVE_SCORE"])


# ---------------------------------------------------------------------------
# V420-F — REGIME-AWARE FAMILY WEIGHTS (soft, ranking-only).
# Returns a multiplier applied to composite score DURING ranking to prefer
# families that historically win in the active regime. Never rejects.
# ---------------------------------------------------------------------------
def v420_regime_weight(family: str, regime: str) -> float:
    if not CONFIG.get("V420_REGIME_WEIGHTS_ENABLE", True):
        return 1.0
    try:
        table = CONFIG.get("V420_REGIME_WEIGHTS", {}) or {}
        row = table.get(str(regime).upper(), {}) or {}
        return float(row.get(str(family).upper(), 1.0))
    except Exception:
        return 1.0


# ---------------------------------------------------------------------------
# V420-G — QUANTUM SCORE TIE-BREAKER.
# When two candidates end with |composite_a - composite_b| < epsilon,
# the tie-breaker computes a bounded [0..1] score from:
#   trend_alignment (ema20>ema50), entry_quality (body/wick), volume_pulse,
#   RSI mid-band bias, freshness. Used ONLY to rank; never a rejection.
# ---------------------------------------------------------------------------
class V420Quantum:
    @staticmethod
    def score(df_5m, family: str) -> float:
        if not CONFIG.get("V420_QUANTUM_TIEBREAKER_ENABLE", True):
            return 0.0
        try:
            if df_5m is None or len(df_5m) < 25:
                return 0.0
            c = df_5m.iloc[-2]
            rng = max(1e-9, float(c.high) - float(c.low))
            body = abs(float(c.close) - float(c.open)) / rng
            wick_lo = (min(float(c.open), float(c.close)) - float(c.low)) / rng
            wick_hi = (float(c.high) - max(float(c.open), float(c.close))) / rng
            entry_q = max(0.0, min(1.0, body * 0.7 + wick_lo * 0.3 - wick_hi * 0.2))
            e20 = float(Indicators.ema(df_5m["close"], 20).iloc[-2])
            e50 = float(Indicators.ema(df_5m["close"], 50).iloc[-2]) if len(df_5m) >= 55 else e20
            trend_al = 1.0 if e20 > e50 else 0.4
            vol_arr = df_5m["volume"].iloc[-20:-1].astype(float)
            v_avg = max(1e-9, float(vol_arr.mean()))
            v_pulse = max(0.0, min(1.5, float(c.volume) / v_avg)) / 1.5
            rsi = Indicators.rsi(df_5m["close"], 14)
            r = float(rsi.iloc[-2]) if rsi is not None else 50.0
            # Prefer 45–65 for continuation, 30–50 for pullback/reversion.
            fam = str(family).upper()
            if fam in ("PULLBACK", "MEAN_REVERSION", "LIQUIDITY_SWEEP_REVERSAL"):
                rsi_al = 1.0 - min(1.0, abs(r - 45.0) / 30.0)
            else:
                rsi_al = 1.0 - min(1.0, abs(r - 55.0) / 30.0)
            q = (0.30 * trend_al + 0.30 * entry_q + 0.20 * v_pulse + 0.20 * rsi_al)

            return max(0.0, min(1.0, q))
        except Exception:
            return 0.0


# ---------------------------------------------------------------------------
# V420-H — ORDER-BLOCK FULL DETECTION (from scalp_pack).
# body>=55% + volume>=1.7x avg(20) + freshness 1..12 bars.
# Returns (found, zone_low, zone_high, freshness) — used as a scoring boost
# and as a stronger retest anchor when found. Never a standalone signal.
# ---------------------------------------------------------------------------
class V420OrderBlock:
    @staticmethod
    def find(df_5m) -> Tuple[bool, float, float, int]:
        if not CONFIG.get("V420_ORDER_BLOCK_ENABLE", True):
            return False, 0.0, 0.0, 0
        try:
            if df_5m is None or len(df_5m) < 25:
                return False, 0.0, 0.0, 0
            body_min = float(CONFIG.get("V420_OB_BODY_MIN", 0.55))
            vol_min = float(CONFIG.get("V420_OB_VOLUME_RATIO_MIN", 1.70))
            lb = int(CONFIG.get("V420_OB_LOOKBACK", 20))
            f_min = int(CONFIG.get("V420_OB_FRESHNESS_MIN", 1))
            f_max = int(CONFIG.get("V420_OB_FRESHNESS_MAX", 12))
            end = len(df_5m) - 2
            v_avg = max(1e-9,
                        float(df_5m["volume"].iloc[max(0, end - lb):end].astype(float).mean()))
            # bullish OB: last bearish candle before a strong bullish impulse
            for j in range(end, max(0, end - lb), -1):
                r = df_5m.iloc[j]
                rng = max(1e-9, float(r.high) - float(r.low))
                body = abs(float(r.close) - float(r.open)) / rng
                is_bear = float(r.close) < float(r.open)
                vr = float(r.volume) / v_avg
                fresh = end - j
                if is_bear and body >= body_min and vr >= vol_min \
                        and f_min <= fresh <= f_max:
                    return True, float(r.low), float(r.high), fresh
            return False, 0.0, 0.0, 0
        except Exception:
            return False, 0.0, 0.0, 0


# ---------------------------------------------------------------------------
# V420-I — EQUAL-LOWS SWEEP DETECTION.
# Cluster of >=2 lows within V420_EQL_TOLERANCE_PCT over V420_EQL_LOOKBACK
# bars; sweep = wick pierces below cluster by >= V420_EQL_MIN_SWEEP_ATR
# but close remains above cluster. Returns (found, cluster_low, sweep_depth_atr).
# ---------------------------------------------------------------------------
class V420EqualLowsSweep:
    @staticmethod
    def find(df_5m) -> Tuple[bool, float, float]:
        if not CONFIG.get("V420_EQUAL_LOWS_SWEEP_ENABLE", True):
            return False, 0.0, 0.0
        try:
            if df_5m is None or len(df_5m) < 25:
                return False, 0.0, 0.0
            lb = int(CONFIG.get("V420_EQL_LOOKBACK", 20))
            tol_pct = float(CONFIG.get("V420_EQL_TOLERANCE_PCT", 0.10)) / 100.0
            min_touch = int(CONFIG.get("V420_EQL_MIN_TOUCHES", 2))
            min_depth = float(CONFIG.get("V420_EQL_MIN_SWEEP_ATR", 0.15))
            end = len(df_5m) - 2
            lows = df_5m["low"].iloc[max(0, end - lb):end].astype(float).values
            if len(lows) < min_touch:
                return False, 0.0, 0.0
            base = float(min(lows))
            touches = sum(1 for x in lows if abs(x - base) / max(base, 1e-9) <= tol_pct)
            if touches < min_touch:
                return False, 0.0, 0.0
            atr = Indicators.atr(df_5m, int(CONFIG.get("ATR_PERIOD", 14)))
            if atr is None:
                return False, 0.0, 0.0
            a = float(atr.iloc[-2])
            cur = df_5m.iloc[-2]
            depth = (base - float(cur.low)) / max(a, 1e-9)
            reclaim = float(cur.close) > base
            if depth >= min_depth and reclaim:
                return True, base, depth
            return False, 0.0, 0.0
        except Exception:
            return False, 0.0, 0.0


# ---------------------------------------------------------------------------
# V420-J — VOLUME DELTA (proxy) + RELATIVE STRENGTH vs BTC.
# Volume delta = sum(sign*vol) over last N bars where sign is (close-open).
# RS-vs-BTC = pct_change(sym, N) - pct_change(BTC, N). Both bounded contributions.
# ---------------------------------------------------------------------------
class V420ScoreAddOns:
    @staticmethod
    def volume_delta_boost(df_5m) -> float:
        if not CONFIG.get("V420_VOLUME_DELTA_ENABLE", True):
            return 0.0
        try:
            n = int(CONFIG.get("V420_VOLUME_DELTA_LOOKBACK", 20))
            cap = float(CONFIG.get("V420_VOLUME_DELTA_BOOST_MAX", 2.0))
            if df_5m is None or len(df_5m) < n + 2:
                return 0.0
            seg = df_5m.iloc[-(n + 1):-1]
            sign = (seg["close"] - seg["open"]).apply(lambda x: 1.0 if x > 0 else (-1.0 if x < 0 else 0.0))
            vd = float((sign * seg["volume"].astype(float)).sum())
            vsum = float(seg["volume"].astype(float).sum()) or 1.0
            norm = max(-1.0, min(1.0, vd / vsum))
            return max(0.0, norm) * cap
        except Exception:
            return 0.0

    @staticmethod
    def rs_vs_btc_boost(df_5m, df_btc_5m_or_15m) -> float:
        if not CONFIG.get("V420_RS_VS_BTC_ENABLE", True):
            return 0.0
        try:
            n = int(CONFIG.get("V420_RS_LOOKBACK", 12))
            cap = float(CONFIG.get("V420_RS_BOOST_MAX", 2.0))
            if df_5m is None or df_btc_5m_or_15m is None:
                return 0.0
            if len(df_5m) < n + 2 or len(df_btc_5m_or_15m) < n + 2:
                return 0.0
            def _chg(df):
                a = float(df["close"].iloc[-2])
                b = float(df["close"].iloc[-(n + 2)])
                return (a - b) / max(abs(b), 1e-9)
            rs = _chg(df_5m) - _chg(df_btc_5m_or_15m)
            # Only positive relative strength boosts a LONG-only setup.
            return max(0.0, min(1.0, rs * 20.0)) * cap
        except Exception:
            return 0.0


# ---------------------------------------------------------------------------
# V420-K — FEE VIABILITY RESCUE (compatibility layer).
# v4.5.50 adds the live canonical target-expansion path below. The legacy
# haircut helper remains only as a compatibility shim and is no longer the
# path used by PreSend sizing. SL, risk, entry and fee gates remain intact.
# ---------------------------------------------------------------------------
def _v604_record_fee_rescue_forensics(symbol: str, *, entry: float, sl: float,
                                        tp1: float, tp2: float, tp3: float,
                                        nominal: float, score: float,
                                        strategy_mode: str,
                                        stage: str, result: str,
                                        detail: Optional[Dict[str, Any]] = None,
                                        reason: str = "") -> None:
    """Telemetry-only forensic snapshot for fee-rescue coherence.
    Never changes the gate or order authority.
    """
    if not bool(CONFIG.get("V604_FEE_RESCUE_FORENSICS_ENABLE", True)):
        return
    try:
        STATS["v604_fee_rescue_last"] = {
            "symbol": str(symbol),
            "stage": str(stage),
            "result": str(result),
            "reason": str(reason)[:220],
            "entry": float(entry),
            "sl": float(sl),
            "tp1": float(tp1),
            "tp2": float(tp2),
            "tp3": float(tp3),
            "nominal": float(nominal),
            "score": float(score),
            "family": str(strategy_mode),
            "detail": dict(detail or {}),
            "ts": WALL_NOW(),
        }
        STATS["v604_fee_rescue_events"] = int(
            STATS.get("v604_fee_rescue_events", 0) or 0
        ) + 1
    except Exception:
        _v647_record_suppressed_exception()


class V420FeeRescue:
    """
    v4.5.50 — bounded fee-target expansion.

    Legacy `try_rescue()` is retained for compatibility, but the live
    PreSend path uses `try_expand_targets()` after a real canonical fee
    rejection. The gate itself is NEVER relaxed: a candidate is accepted only
    when the original fee_viability_detail() returns ok=True with the
    expanded targets.
    """

    @staticmethod
    def try_expand_targets(entry: float, sl: float, tp1: float, tp2: float,
                            tp3: Optional[float], nominal: float, score: float,
                            strategy_mode: str, spread_pct: Optional[float] = None,
                            small_net_mode: bool = False) -> Tuple[bool, float, float, float, str]:
        """Bounded fee-target rescue with dynamic RR derivation.

        The rescue never lowers the canonical fee gate. It only proposes new
        TP geometry; the caller must re-run fee_viability_detail() and the
        full PreSend/risk ordering checks before any order can proceed.
        """
        try:
            # v4.5.55: one canonical fee-rescue path is used by both live
            # PreSend and the v5.54 MSE rank probe. No parallel fee relaxer exists.
            if not bool(CONFIG.get("V550_FEE_TARGET_RESCUE_ENABLE", True)):
                return False, tp1, tp2, float(tp3 or 0.0), "disabled"

            raw_family = str(strategy_mode or "").upper().strip()
            # Discovery/diagnostic labels can arrive as "PULLBACK / PULLBACK".
            family_tokens = [x.strip() for x in raw_family.split("/") if x.strip()]
            family = family_tokens[0] if family_tokens else raw_family
            allowed = {str(x).upper().strip() for x in (CONFIG.get(
                "V550_FEE_TARGET_RESCUE_FAMILIES", ("PULLBACK", "MTF_PULLBACK")
            ) or ())}

            # V646: BREAKOUT families are admitted to the SAME canonical fee-rescue
            # routine only when the dedicated bounded breakout lane is enabled.
            # The old ordering rejected them before reaching the breakout-specific
            # score/cap checks, making the V646 rescue logically unreachable for
            # BREAKOUT_RETEST candidates.
            is_breakout = family in {"BREAKOUT_RETEST", "BREAKOUT_CONTINUATION"}
            if is_breakout and bool(CONFIG.get("V646_BREAKOUT_FEE_RESCUE_ENABLE", True)):
                allowed.add(family)
            if family not in allowed:
                return False, tp1, tp2, float(tp3 or 0.0), f"family_not_allowed:{family}"

            score_f = float(score)
            if score_f < float(CONFIG.get("V550_FEE_TARGET_RESCUE_MIN_SCORE", 64.0)):
                return False, tp1, tp2, float(tp3 or 0.0), "score_below_rescue_floor"

            # V646: BREAKOUT_RETEST / BREAKOUT_CONTINUATION receive ONLY an
            # economic target-geometry rescue. Structural/BOS confirmation remains
            # hard and is never recovered here.
            if is_breakout:
                if not bool(CONFIG.get("V646_BREAKOUT_FEE_RESCUE_ENABLE", True)):
                    return False, tp1, tp2, float(tp3 or 0.0), "breakout_fee_rescue_disabled"
                if score_f < float(CONFIG.get("V646_BREAKOUT_FEE_RESCUE_MIN_SCORE", 75.0)):
                    return False, tp1, tp2, float(tp3 or 0.0), "breakout_score_below_rescue_floor"

            entry_f, sl_f = float(entry), float(sl)
            nominal_f = float(nominal)
            risk_unit = entry_f - sl_f
            if risk_unit <= 0 or entry_f <= 0 or nominal_f <= 0:
                return False, tp1, tp2, float(tp3 or 0.0), "invalid_risk_or_notional"

            # Calculate the fee burden in units of R. This gives the smallest
            # TP1 RR that can satisfy both canonical fee conditions.
            fees = SizingEngine.roundtrip_fee_usdt(nominal_f)
            risk_usdt = nominal_f * (risk_unit / entry_f)
            if risk_usdt <= 0:
                return False, tp1, tp2, float(tp3 or 0.0), "invalid_risk_usdt"
            fee_in_r = fees / risk_usdt
            # The R40 small-net profile is an explicit alternative economics model:
            # it adds observed/fallback spread + two-sided slippage and still keeps
            # the existing 2.5x commission coverage. Default/legacy calls retain R39.
            _small_net_active = bool(small_net_mode and CONFIG.get("V702_SMALL_NET_PROFIT_MODE_ENABLE", False) and not is_breakout)
            min_net_rr = (float(CONFIG.get("V702_SMALL_NET_MIN_NET_RR_TP1", 0.25))
                          if _small_net_active else float(CONFIG.get("MIN_NET_RR_TP1", 0.8)))
            min_fee_ratio = float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5))
            if _small_net_active:
                dynamic_required_rr = SizingEngine.small_net_required_tp1_rr(
                    entry_f, sl_f, nominal_f, spread_pct
                )
            else:
                dynamic_required_rr = max(
                    min_net_rr + fee_in_r,
                    min_fee_ratio * fee_in_r,
                    1.0,
                ) + float(CONFIG.get("V551_FEE_RR_SAFETY_MARGIN", 0.08))

            max_tp1_rr = float(CONFIG.get("V646_BREAKOUT_FEE_RESCUE_MAX_TP1_RR", 1.50)
                               if is_breakout else (CONFIG.get("V702_SMALL_NET_MAX_TP1_RR", 2.0) if _small_net_active else CONFIG.get(
                               "V551_FEE_TARGET_MAX_TP1_RR", CONFIG.get("V550_FEE_TARGET_MAX_TP1_RR", 2.0))))
            max_tp2_rr = float(CONFIG.get("V646_BREAKOUT_FEE_RESCUE_MAX_TP2_RR", 3.50)
                               if is_breakout else (CONFIG.get("V702_SMALL_NET_MAX_TP2_RR", 3.2) if _small_net_active else CONFIG.get(
                               "V551_FEE_TARGET_MAX_TP2_RR", CONFIG.get("V550_FEE_TARGET_MAX_TP2_RR", 4.0))))
            min_tp2_mult = float(CONFIG.get("V646_BREAKOUT_FEE_RESCUE_MIN_TP2_MULT", 2.0)
                                 if is_breakout else (CONFIG.get("V702_SMALL_NET_TP2_RR_MULT", 1.25) if _small_net_active else CONFIG.get("V551_FEE_TARGET_MIN_TP2_MULT", 2.0)))
            min_tp2_rr = float(CONFIG.get("V646_BREAKOUT_FEE_RESCUE_MIN_TP2_RR", 2.50)
                               if is_breakout else (CONFIG.get("V702_SMALL_NET_MIN_TP2_RR", 1.8) if _small_net_active else CONFIG.get("V551_FEE_TARGET_MIN_TP2_RR", 2.8)))

            current_rr1 = (float(tp1) - entry_f) / risk_unit
            current_rr2 = (float(tp2) - entry_f) / risk_unit
            # Never lower existing targets. Start from the dynamic required RR
            # and keep the original geometry as a lower bound.
            rr1_candidates = [max(current_rr1, dynamic_required_rr)]
            if not is_breakout:
                rr1_candidates += [
                    max(current_rr1, 1.40),
                    max(current_rr1, 1.60),
                    max(current_rr1, 1.80),
                    max(current_rr1, 2.00),
                ]
                if bool(CONFIG.get("V551_DYNAMIC_FEE_RR_ENABLE", True)):
                    rr1_candidates.insert(0, max(current_rr1, dynamic_required_rr))
            # Deterministic ordering + de-dup.
            rr1_candidates = sorted({round(float(x), 8) for x in rr1_candidates})

            current_tp3 = float(tp3 or 0.0)
            tested = 0
            last_detail: Dict[str, Any] = {}
            for rr1 in rr1_candidates:
                if rr1 <= current_rr1 + 1e-9:
                    continue
                if rr1 > max_tp1_rr + 1e-9:
                    continue

                rr2 = max(
                    current_rr2,
                    min_tp2_rr,
                    rr1 * min_tp2_mult,
                )
                if rr2 > max_tp2_rr + 1e-9:
                    continue

                new_tp1 = max(float(tp1), entry_f + rr1 * risk_unit)
                new_tp2 = max(float(tp2), entry_f + rr2 * risk_unit)
                min_gap = max(1e-12, abs(risk_unit) * 0.02)
                new_tp2 = max(new_tp2, new_tp1 + min_gap)
                rr2 = (new_tp2 - entry_f) / risk_unit
                if rr2 > max_tp2_rr + 1e-9:
                    continue

                new_tp3 = max(current_tp3, new_tp2 + min_gap)
                tested += 1

                detail = SizingEngine.fee_viability_detail(
                    entry_f, sl_f, new_tp1, new_tp2, nominal_f,
                    fee_ratio_override=min_fee_ratio,
                    spread_pct=spread_pct, small_net_mode=_small_net_active,
                )
                last_detail = detail
                if bool(detail.get("ok", False)):
                    STATS["v550_fee_target_rescue_success"] = STATS.get(
                        "v550_fee_target_rescue_success", 0) + 1
                    STATS["v551_fee_dynamic_rescue_success"] = STATS.get(
                        "v551_fee_dynamic_rescue_success", 0) + 1
                    STATS["v551_fee_dynamic_last"] = {
                        "family": family, "raw_family": raw_family,
                        "score": score_f, "fees": fees,
                        "risk_usdt": risk_usdt, "fee_in_r": fee_in_r,
                        "required_rr": dynamic_required_rr,
                        "selected_rr1": rr1, "selected_rr2": rr2,
                        "tp1": new_tp1, "tp2": new_tp2, "tp3": new_tp3,
                        "detail": detail,
                    }
                    return True, new_tp1, new_tp2, new_tp3, (
                        f"dynamic_fee_rescue:{rr1:.2f}R/{rr2:.2f}R"
                    )

            STATS["v550_fee_target_rescue_attempts"] = STATS.get(
                "v550_fee_target_rescue_attempts", 0) + max(1, tested)
            STATS["v551_fee_dynamic_rescue_last_reject"] = {
                "family": family, "score": score_f, "fees": fees,
                "risk_usdt": risk_usdt, "fee_in_r": fee_in_r,
                "required_rr": dynamic_required_rr,
                "max_tp1_rr": max_tp1_rr, "max_tp2_rr": max_tp2_rr,
                "tested": tested, "last_detail": last_detail,
            }
            return False, tp1, tp2, current_tp3, (
                f"no_safe_dynamic_rr_pair:req={dynamic_required_rr:.2f}R "
                f"feeR={fee_in_r:.2f}"
            )
        except Exception as e:
            STATS["v550_fee_target_rescue_errors"] = STATS.get(
                "v550_fee_target_rescue_errors", 0) + 1
            return False, tp1, tp2, float(tp3 or 0.0), f"exception:{type(e).__name__}"

    @staticmethod
    def try_rescue(entry: float, sl: float, tp1: float, tp2: float,
                   nominal: float, score: float) -> Tuple[bool, float, float]:
        """Legacy compatibility shim; now delegates to target expansion."""
        ok, new_tp1, new_tp2, _new_tp3, _reason = V420FeeRescue.try_expand_targets(
            entry, sl, tp1, tp2, None, nominal, score, "PULLBACK"
        )
        return ok, new_tp1, new_tp2


# ---------------------------------------------------------------------------
# V420-L — P3 PENALTY CAP.
# Aggregate soft penalties for a (symbol, family) are capped per tier so
# repeated rejections cannot silently starve a symbol forever.
# ---------------------------------------------------------------------------
class V420PenaltyCap:
    @staticmethod
    def add_and_cap(symbol: str, family: str, tier: str, penalty: float) -> float:
        if not CONFIG.get("V420_PENALTY_CAP_ENABLE", True):
            return float(penalty)
        try:
            cap_row = CONFIG.get("V420_PENALTY_CAP_BY_TIER", {}) or {}
            cap = float(cap_row.get(str(tier).upper(), 25.0))
            key = f"{symbol}|{str(family).upper()}"
            with _V420State._lock:
                cur = float(_V420State.penalty_accum.get(key, 0.0))
                new = min(cap, cur + abs(float(penalty)))
                _V420State.penalty_accum[key] = new
            return new
        except Exception:
            return float(penalty)

    @staticmethod
    def reset(symbol: str, family: Optional[str] = None) -> None:
        try:
            with _V420State._lock:
                if family is None:
                    for k in list(_V420State.penalty_accum.keys()):
                        if k.startswith(symbol + "|"):
                            _V420State.penalty_accum.pop(k, None)
                else:
                    _V420State.penalty_accum.pop(
                        f"{symbol}|{str(family).upper()}", None)
        except Exception:
            _v647_record_suppressed_exception()


# ---------------------------------------------------------------------------
# V420-M — CANONICAL DECISION SERVICE.
# Read-only arbiter: given the ordered decisions
#   (balance, watchdog, regime, family_policy, htf, router, score, pre_send)
# it verifies internal consistency and records divergences vs legacy path.
# Divergences are TELEMETRY ONLY; hard rejects always stand.
# ---------------------------------------------------------------------------
class V420CanonicalDecision:
    @staticmethod
    def observe(*, symbol: str, trace_id: str,
                balance_ok: bool, watchdog_ok: bool, regime: str,
                family: str, family_policy_ok: bool,
                htf_ok: bool, score: float, score_ok: bool,
                pre_send_ok: bool) -> None:
        if not CONFIG.get("V420_CANONICAL_DECISION_ENABLE", True):
            return
        try:
            # A "canonical allow" requires every layer to be OK.
            canonical_ok = all([balance_ok, watchdog_ok, family_policy_ok,
                                htf_ok, score_ok, pre_send_ok])
            # Legacy allow is what actually happened in the pipeline; caller
            # passes each True/False so the observer just aggregates.
            # A divergence occurs when any pair disagrees.
            if not canonical_ok:
                # No allow ⇒ nothing to diverge; still record for heatmap.
                _V420State.heatmap[(family, "canonical", regime, "-", "block")] += 1
                return
            _V420State.heatmap[(family, "canonical", regime, "-", "allow")] += 1
        except Exception as e:
            try:
                logger.debug(f"[V420-Canonical] observe suppressed: {e}")
            except Exception:
                _v647_record_suppressed_exception()


# ---------------------------------------------------------------------------
# V420-N — REJECTION HEATMAP.
# Aggregates (family, stage, regime, tier, reason) counts.
# Exposed via V420Heatmap.top_slice() for heartbeat and DEBUG endpoint.
# ---------------------------------------------------------------------------
class V420Heatmap:
    @staticmethod
    def record(family: str, stage: str, regime: str, tier: str, reason: str) -> None:
        if not CONFIG.get("V420_REJECTION_HEATMAP_ENABLE", True):
            return
        try:
            key = (str(family or "-").upper(),
                   str(stage or "-").lower(),
                   str(regime or "-").upper(),
                   str(tier or "-").upper(),
                   str(reason or "-").lower())
            with _V420State._lock:
                _V420State.heatmap[key] += 1
        except Exception:
            _v647_record_suppressed_exception()

    @staticmethod
    def top_slice(n: int = 10) -> List[Tuple[Tuple[str, str, str, str, str], int]]:
        try:
            with _V420State._lock:
                items = sorted(_V420State.heatmap.items(),
                               key=lambda kv: kv[1], reverse=True)
            return items[:n]
        except Exception:
            return []


# ---------------------------------------------------------------------------
# V420-O — FUNNEL HEALTH WATCHDOG.
# If G is rising while S is stuck at 0 for V420_FUNNEL_STARV_WINDOW_MIN
# minutes AND at least V420_FUNNEL_STARV_THRESHOLD Gs occurred, we flip
# a RELAXED_MODE flag for V420_RELAXED_MODE_TTL_SEC that:
#   * activates the BULLISH micro-softening even in NEUTRAL,
#   * step-downs adaptive floor by an extra V420_ADAPTIVE_STEP_DOWN,
#   * auto-reverts to strict after TTL.
# ---------------------------------------------------------------------------
class V420FunnelWatchdog:
    _last_check_ts: float = 0.0
    _last_nfm_count: float = 0.0

    @classmethod
    def tick(cls) -> None:
        if not CONFIG.get("V420_FUNNEL_WATCHDOG_ENABLE", True):
            return
        now = MONO_NOW()
        try:
            iv = float(CONFIG.get("V420_FUNNEL_CHECK_INTERVAL_SEC", 60))
            if now - cls._last_check_ts < iv:
                return
            cls._last_check_ts = now
            STATS["watchdog_ticks"] = STATS.get("watchdog_ticks", 0) + 1
            window_min = float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN", 12))
            rate, g, e, s = _V420State.recall_rate(window_sec=window_min * 60.0)
            # v4.2.5 — queued count for the technical/opportunity taxonomy.
            try:
                q = int(STATS.get("signals_queued", 0) or 0)
            except Exception:
                q = 0
            threshold = float(CONFIG.get("V420_FUNNEL_STARV_THRESHOLD", 150))
            _starv_primary = (g >= threshold and s == 0)

            # v4.2.7 — UNIFIED SAME-WINDOW NFM trigger.
            # G and NFM are measured over the exact same sliding window. This
            # prevents the old per-tick cumulative delta / window denominator
            # mismatch that produced nfm_ratio=0.0 during prolonged starvation.
            _starv_nfm = False
            _nfm_ratio = 0.0
            _nfm_window = 0
            try:
                _nfm_window = int(_V420State.nfm_count(window_sec=window_min * 60.0))
                _ratio_trig = float(CONFIG.get("V420_STARV_NFM_RATIO_TRIGGER", 0.55))
                _ratio_min = int(CONFIG.get("V420_STARV_NFM_RATIO_MIN_COUNT", 25))
                _nfm_ratio = (_nfm_window / float(g)) if g > 0 else 0.0
                _starv_nfm = (_nfm_ratio >= _ratio_trig and
                              _nfm_window >= _ratio_min and
                              e == 0 and s == 0 and g > 0)
                STATS["v425_nfm_ratio"] = round(_nfm_ratio, 4)
                STATS["v425_nfm_window_count"] = int(_nfm_window)
                STATS["v425_nfm_delta"] = int(_nfm_window)  # compatibility alias
                _nfm_window_count = int(_nfm_window)
            except Exception:
                _starv_nfm = False
                _nfm_window_count = 0

            # v4.2.5 — starvation taxonomy (read-only classification).
            try:
                _starv_kind = V425Starvation.classify(g, e, q, s, _nfm_ratio, _nfm_window_count)
                STATS["v425_starvation_mode"] = _starv_kind
                if _starv_kind == V425Starvation.TECHNICAL:
                    STATS["technical_starvation_events"] = STATS.get("technical_starvation_events", 0) + 1
                    V425Starvation.alert(V425Starvation.TECHNICAL,
                        f"pipeline active (G={g} E={e} Q={q}) but S=0 in {window_min:.0f}m")
                elif _starv_kind == V425Starvation.OPPORTUNITY:
                    STATS["opportunity_starvation_events"] = STATS.get("opportunity_starvation_events", 0) + 1
                    V425Starvation.alert(V425Starvation.OPPORTUNITY,
                        f"G={g} E=0 NFM_ratio={_nfm_ratio:.2f} nfm={int(_nfm_window_count)} in {window_min:.0f}m")
            except Exception:
                _v647_record_suppressed_exception()

            if _starv_primary or _starv_nfm:
                ttl = float(CONFIG.get("V420_RELAXED_MODE_TTL_SEC", 600))
                _V420State.relaxed_mode_until_ts = now + ttl
                STATS["v420_relaxed_mode_activations"] = \
                    STATS.get("v420_relaxed_mode_activations", 0) + 1
                STATS["watchdog_relaxed_activations"] = \
                    STATS.get("watchdog_relaxed_activations", 0) + 1
                try:
                    _starv_reason = "g_starve" if _starv_primary else "nfm_ratio"
                    STATS["watchdog_triggers"] = STATS.get("watchdog_triggers", 0) + 1
                    logger.warning(
                        f"[V420-Watchdog] STARVATION reason={_starv_reason} "
                        f"mode={STATS.get('v425_starvation_mode','NONE')} "
                        f"G={g} E={e} Q={q} S={s} nfm_ratio={_nfm_ratio:.2f} "
                        f"in {window_min:.0f}m → RELAXED_MODE for {ttl:.0f}s "
                        f"(detector-recall only; recovery stays policy-gated)")
                except Exception:
                    _v647_record_suppressed_exception()
            elif now > _V420State.relaxed_mode_until_ts and \
                    _V420State.relaxed_mode_until_ts > 0:
                _V420State.relaxed_mode_until_ts = 0.0
                try:
                    logger.info("[V420-Watchdog] RELAXED_MODE expired — strict resumed.")
                except Exception:
                    _v647_record_suppressed_exception()
        except Exception as e:
            try:
                logger.debug(f"[V420-Watchdog] tick suppressed: {e}")
            except Exception:
                _v647_record_suppressed_exception()

    @staticmethod
    def is_relaxed() -> bool:
        return MONO_NOW() < float(_V420State.relaxed_mode_until_ts or 0.0)


# ---------------------------------------------------------------------------
# V420-P — FAMILY-AWARE BACKOFF (symbol,family) keying.
# Legacy HTF backoff keys by symbol only: rejecting PULLBACK locks BREAKOUT
# on the same symbol. This tracker replaces it (additively) with a per-family
# backoff so an unrelated family can still trade the symbol.
# ---------------------------------------------------------------------------
class V420FamilyBackoff:
    @staticmethod
    def is_backed_off(symbol: str, family: str) -> bool:
        if not CONFIG.get("V420_FAMILY_AWARE_BACKOFF_ENABLE", True):
            return False
        try:
            key = (symbol, str(family).upper())
            with _V420State._lock:
                cur = _V420State.family_backoff.get(key)
            if not cur:
                return False
            _level, until = cur
            return MONO_NOW() < float(until)
        except Exception:
            return False

    @staticmethod
    def arm(symbol: str, family: str) -> None:
        if not CONFIG.get("V420_FAMILY_AWARE_BACKOFF_ENABLE", True):
            return
        try:
            key = (symbol, str(family).upper())
            base = float(CONFIG.get("V420_FAMILY_BACKOFF_BASE_SEC", 45.0))
            cap = float(CONFIG.get("V420_FAMILY_BACKOFF_CAP_SEC", 180.0))
            max_lvl = int(CONFIG.get("V420_FAMILY_BACKOFF_MAX_LVL", 3))
            with _V420State._lock:
                cur = _V420State.family_backoff.get(key)
                lvl = (int(cur[0]) + 1) if cur else 1
                lvl = min(lvl, max_lvl)
                until = MONO_NOW() + min(cap, base * (2 ** max(0, lvl - 1)))
                _V420State.family_backoff[key] = (lvl, until)
        except Exception:
            _v647_record_suppressed_exception()

    @staticmethod
    def clear(symbol: str, family: Optional[str] = None) -> None:
        try:
            with _V420State._lock:
                if family is None:
                    for k in list(_V420State.family_backoff.keys()):
                        if k[0] == symbol:
                            _V420State.family_backoff.pop(k, None)
                else:
                    _V420State.family_backoff.pop(
                        (symbol, str(family).upper()), None)
        except Exception:
            _v647_record_suppressed_exception()


# ---------------------------------------------------------------------------
# V420 — CROSS-CUTTING BOOT VALIDATOR
# ---------------------------------------------------------------------------
def _v420_boot_validate() -> None:
    """Called from validate_config() at startup. Never raises."""
    try:
        # Enforce scan mode & window.
        V420Cooldowns.enforce_scan_mode()
        # Audit family policies (add BULLISH where missing on long-suitable families).
        _v420_audit_family_policies()
        # Initialize adaptive floor to current MIN_LIVE_SCORE (soft ceiling).
        _V420State.adaptive_floor = max(70.0, float(CONFIG.get("MIN_LIVE_SCORE", 70) or 70))
        # Sanity: relaxed-mode not initially active
        _V420State.relaxed_mode_until_ts = 0.0
        # Log a compact summary.
        try:
            logger.info(
                "[V420] Boot summary: scan_cd=%.0fs exec_cd=%.0fs "
                "adaptive_floor=%.1f (min=%.1f max=%.1f) rescue=%s "
                "relaxed_mode_ttl=%.0fs router_audit=%s quantum=%s OB=%s "
                "eql_sweep=%s vol_delta=%s rs_vs_btc=%s fee_rescue=%s "
                "penalty_cap=%s canonical=%s heatmap=%s watchdog=%s "
                "family_backoff=%s",
                float(CONFIG.get("V420_SCAN_COOLDOWN_SEC", 60)),
                float(CONFIG.get("V420_EXECUTION_COOLDOWN_SEC", 30)),
                _V420State.adaptive_floor,
                max(70.0, float(CONFIG.get("V420_ADAPTIVE_FLOOR_MIN", 70.0))),
                max(70.0, float(CONFIG.get("V420_ADAPTIVE_FLOOR_MAX", 78.0))),
                bool(CONFIG.get("V420_FEE_VIABILITY_RESCUE_ENABLE", True)),
                float(CONFIG.get("V420_RELAXED_MODE_TTL_SEC", 600)),
                bool(CONFIG.get("V420_ROUTER_AUDIT_ENABLE", True)),
                bool(CONFIG.get("V420_QUANTUM_TIEBREAKER_ENABLE", True)),
                bool(CONFIG.get("V420_ORDER_BLOCK_ENABLE", True)),
                bool(CONFIG.get("V420_EQUAL_LOWS_SWEEP_ENABLE", True)),
                bool(CONFIG.get("V420_VOLUME_DELTA_ENABLE", True)),
                bool(CONFIG.get("V420_RS_VS_BTC_ENABLE", True)),
                bool(CONFIG.get("V420_FEE_VIABILITY_RESCUE_ENABLE", True)),
                bool(CONFIG.get("V420_PENALTY_CAP_ENABLE", True)),
                bool(CONFIG.get("V420_CANONICAL_DECISION_ENABLE", True)),
                bool(CONFIG.get("V420_REJECTION_HEATMAP_ENABLE", True)),
                bool(CONFIG.get("V420_FUNNEL_WATCHDOG_ENABLE", True)),
                bool(CONFIG.get("V420_FAMILY_AWARE_BACKOFF_ENABLE", True)),
            )
        except Exception:
            _v647_record_suppressed_exception()
    except Exception as e:
        try:
            logger.warning(f"[V420] boot validator suppressed: {e}")
        except Exception:
            _v647_record_suppressed_exception()


# ---------------------------------------------------------------------------
# V420 — HEATMAP-AUGMENTED HEARTBEAT LINE (safe helper).
# Callable from Heartbeat pipeline; never raises.
# ---------------------------------------------------------------------------
def v420_heatmap_line(n: int = 5) -> str:
    try:
        top = V420Heatmap.top_slice(n=n)
        if not top:
            return ""
        parts = []
        for (fam, stage, reg, tier, reason), cnt in top:
            parts.append(f"{fam}/{stage}/{reg}/{tier}/{reason}:{cnt}")
        return "[V420.heatmap] " + " ".join(parts)
    except Exception:
        return ""


# ---------------------------------------------------------------------------
# V420 — OFFLINE SELF-TEST.
# ---------------------------------------------------------------------------
def _v420_self_test() -> None:
    if not _PDNP_OK:
        return
    # 1. adaptive floor bounded
    _V420State.recall_hist.clear()
    for _ in range(200):
        _V420State.note_g()
    for _ in range(1):
        _V420State.note_e()
    f = V420AdaptiveFloor.compute()
    assert f <= float(CONFIG["MIN_LIVE_SCORE"])
    # 2. regime weight defined for BULLISH/PULLBACK
    w = v420_regime_weight("PULLBACK", "BULLISH")
    assert 0.5 <= w <= 2.0
    # 3. family backoff independence
    V420FamilyBackoff.arm("XYZ/USDT", "PULLBACK")
    assert V420FamilyBackoff.is_backed_off("XYZ/USDT", "PULLBACK")
    assert not V420FamilyBackoff.is_backed_off("XYZ/USDT", "BREAKOUT_RETEST")
    V420FamilyBackoff.clear("XYZ/USDT")
    # 4. heatmap round-trip
    V420Heatmap.record("PULLBACK", "router", "BULLISH", "MID", "test_reason")
    assert V420Heatmap.top_slice(1)[0][1] >= 1
    # 5. router auditor demotes MEAN_REVERSION in BULLISH when RSI>32
    idx = pd.date_range("2025-01-01", periods=40, freq="5min")
    base = np.linspace(100, 110, 40)
    df = pd.DataFrame({"open": base - 0.1, "high": base + 0.2,
                       "low": base - 0.2, "close": base,
                       "volume": np.linspace(100, 200, 40)}, index=idx)
    fam, meta = V420RouterAuditor.audit_family(
        "MEAN_REVERSION", {"family": "MEAN_REVERSION"}, "BULLISH", df)
    assert fam == "TREND_CONTINUATION"
    # 6. penalty cap bounded
    for _ in range(50):
        V420PenaltyCap.add_and_cap("AAA/USDT", "PULLBACK", "MID", 5.0)
    with _V420State._lock:
        assert _V420State.penalty_accum["AAA/USDT|PULLBACK"] <= \
               CONFIG["V420_PENALTY_CAP_BY_TIER"]["MID"] + 1e-6
    logger.info("V4.2.0 offline self-test: PASS")


# =============================================================================
# END SECTION V4.2.0
# =============================================================================


def _v410_self_test() -> None:
    """Offline deterministic smoke tests; never connects to MEXC."""
    if not _PDNP_OK: raise RuntimeError("pandas/numpy required for self-test")
    idx = pd.date_range("2025-01-01", periods=32, freq="5min")
    base = np.linspace(100, 104, 32)
    df = pd.DataFrame({"open":base-0.10,"high":base+0.25,"low":base-0.25,"close":base,"volume":np.linspace(100,180,32)},index=idx)
    df.iloc[-2, df.columns.get_loc("close")] = 105.0; df.iloc[-2, df.columns.get_loc("high")] = 105.2; df.iloc[-2, df.columns.get_loc("volume")] = 400.0
    assert FamilyPolicyLayer.regime_allowed("PULLBACK","BULLISH")
    assert FamilyPolicyLayer.regime_allowed("MEAN_REVERSION","BULLISH")
    assert FamilyPolicyLayer.min_score(70,"PULLBACK") <= 70
    bos = detect_micro_bos_at_index(df,len(df)-2); assert bos is not None
    zone = find_retest_zone_at_index(df,bos,len(df)-2); assert zone is not None
    assert 0 <= confluence_boost_v410(df,True,float(df.close.iloc[-2]))[0] <= CONFIG["CONFLUENCE_MAX_BOOST"]
    assert not FamilyPolicyLayer.liquidity_acceptable("BREAKOUT_CONTINUATION","MID")
    assert FamilyPolicyLayer.tp1_distance_ok(100,101,1,"PULLBACK")
    logger.info("V4.1.0 offline safety/recall self-test: PASS")

# =============================================================================
#  v4.2.2 — NEAR-MISS AGGREGATE TELEMETRY + INDEPENDENT STARV ALERTER
#  (additive, read-only observers; never influence any gate)
# =============================================================================
class V422NearMiss:
    """Rolling, bounded near-miss statistics for router/funnel diagnostics.

    Tracks over a sliding time window:
      * closest_detector when no family matched (by |ATR distance|),
      * mean |distance| to EMA20 / EMA50 / VWAP anchors (in ATR),
      * per-detector reject counts,
      * top rejected families,
      * time-of-day rejection clusters (UTC hour buckets).
    """
    _lock = threading.RLock()
    _events = deque(maxlen=4096)

    @classmethod
    def _prune(cls):
        try:
            now = MONO_NOW()
            w = float(CONFIG.get("V422_NEARMISS_WINDOW_SEC", 900))
            while cls._events and (now - cls._events[0][0]) > w:
                cls._events.popleft()
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def note_router_miss(cls, symbol, ctx):
        try:
            with cls._lock:
                cls._events.append((MONO_NOW(), "router_miss", {
                    "symbol": symbol,
                    "closest": str(ctx.get("closest_detector", "unknown")),
                    "d_e20": ctx.get("dist_atr_ema20"),
                    "d_e50": ctx.get("dist_atr_ema50"),
                    "d_vwap": ctx.get("dist_atr_vwap"),
                    "hour": time.gmtime().tm_hour,
                }))
                cls._prune()
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def note_family_reject(cls, family, reason):
        try:
            with cls._lock:
                cls._events.append((MONO_NOW(), "family_reject", {
                    "family": str(family or "unknown"),
                    "reason": str(reason or "unknown"),
                    "hour": time.gmtime().tm_hour,
                }))
                cls._prune()
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def note_detector_reject(cls, detector, symbol):
        try:
            with cls._lock:
                cls._events.append((MONO_NOW(), "detector_reject",
                                    {"detector": str(detector), "symbol": symbol,
                                     "hour": time.gmtime().tm_hour}))
                cls._prune()
        except Exception:
            _v647_record_suppressed_exception()


    @staticmethod
    def _mean(vals):
        try:
            vs = [float(v) for v in vals if v is not None and math.isfinite(float(v))]
            return (sum(vs) / len(vs)) if vs else None
        except Exception:
            return None

    @classmethod
    def snapshot(cls):
        try:
            with cls._lock:
                cls._prune()
                ev = list(cls._events)
            out = {}
            misses = [p for _, k, p in ev if k == "router_miss"]
            if misses:
                closest = defaultdict(int)
                hours = defaultdict(int)
                for p in misses:
                    closest[p.get("closest", "unknown")] += 1
                    hours[int(p.get("hour", 0))] += 1
                out["closest_detector_top"] = dict(
                    sorted(closest.items(), key=lambda kv: kv[1], reverse=True)[:5])
                out["mean_dist_atr_ema20"] = cls._mean(p.get("d_e20") for p in misses)
                out["mean_dist_atr_ema50"] = cls._mean(p.get("d_e50") for p in misses)
                out["mean_dist_atr_vwap"] = cls._mean(p.get("d_vwap") for p in misses)
                out["tod_clusters"] = dict(
                    sorted(hours.items(), key=lambda kv: kv[1], reverse=True)[:4])
                out["router_misses"] = len(misses)
            drej = [p for _, k, p in ev if k == "detector_reject"]
            if drej:
                det = defaultdict(int)
                for p in drej:
                    det[p.get("detector", "unknown")] += 1
                out["detector_reject_top"] = dict(
                    sorted(det.items(), key=lambda kv: kv[1], reverse=True)[:6])
            frej = [p for _, k, p in ev if k == "family_reject"]
            if frej:
                fam = defaultdict(int)
                for p in frej:
                    fam[p.get("family", "unknown")] += 1
                out["family_reject_top"] = dict(
                    sorted(fam.items(), key=lambda kv: kv[1], reverse=True)[:6])
            return out
        except Exception:
            return {}


class V422StarvationAlerter:
    """Independent async task: watches last_send_ts and emits a bottleneck
    snapshot when no send occurred for V422_STARV_ALERT_NO_SEND_SEC.
    Rate-limited by V422_STARV_ALERT_MIN_INTERVAL_SEC. Never touches
    execution.
    """
    _last_send_ts = 0.0
    _last_alert_ts = 0.0

    @classmethod
    def note_send(cls):
        try:
            cls._last_send_ts = MONO_NOW()
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    async def task(cls):
        if not bool(CONFIG.get("V422_STARV_ALERT_ENABLE", True)):
            return
        cls._last_send_ts = MONO_NOW()  # seed at boot
        while True:
            try:
                await asyncio.sleep(30)
                now = MONO_NOW()
                no_send_sec = float(CONFIG.get("V422_STARV_ALERT_NO_SEND_SEC", 900))
                min_gap = float(CONFIG.get("V422_STARV_ALERT_MIN_INTERVAL_SEC", 300))
                global_enabled = bool(CONFIG.get("V45_OPPORTUNITY_BRAIN_ENABLE", False))
                # v4.5.3: gate on the LAST SUCCESSFUL FULL GLOBAL CYCLE, not
                # on a bare counter. A full cycle = universe built + candidates
                # scanned + arbitration finished + telemetry committed. A
                # restart/lost counter NEVER fires a false alert and never
                # opens trading.
                _last_full_cycle = float(STATS.get("v45_global_last_successful_cycle_ts", 0.0) or 0.0)
                _last_full_cycle_age = _wall_age_sec(_last_full_cycle)
                if global_enabled and _last_full_cycle_age is None:
                    continue
                throttle_on = bool(CONFIG.get("V453_STARV_ALERT_THROTTLE_ENABLE", True))
                # V640: historical no-send age alone is not evidence of current
                # starvation. During bootstrap or a fresh zero-activity global
                # cycle, suppress the alert and preserve the existing full
                # formatter/diagnostics for real active cycles only.
                if global_enabled and bool(CONFIG.get("V640_STARVATION_ACTIVITY_REQUIRED", True)):
                    try:
                        _v640_diag_gate = V453StarvationClassifier.window_diagnostics()
                        _v640_gd = int(_v640_diag_gate.get("generated_delta", 0) or 0)
                        _v640_pd = int(_v640_diag_gate.get("prequal_pass_delta", 0) or 0)
                        _v640_age = _v640_diag_gate.get("last_successful_global_cycle_age_sec")
                        if ((_v640_gd < int(CONFIG.get("V640_STARVATION_MIN_GENERATED_DELTA", 1))) and
                            (_v640_pd < int(CONFIG.get("V640_STARVATION_MIN_PREQUAL_DELTA", 1)))):
                            continue
                        if _v640_age is None:
                            continue
                    except Exception:
                        continue
                if (now - cls._last_send_ts) >= no_send_sec and \
                   ((now - cls._last_alert_ts) >= min_gap if throttle_on else True):
                    cls._last_alert_ts = now
                    _nm = V422NearMiss.snapshot()
                    _pdiag = V424PullbackDiagnostics.snapshot()
                    _relaxed_on = False
                    try:
                        _relaxed_on = bool(V420FunnelWatchdog.is_relaxed())
                    except Exception:
                        _v647_record_suppressed_exception()
                    _gs = V45GlobalFunnelState.snapshot(
                        float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN", 12)) * 60.0
                    ) if bool(CONFIG.get("V45_OPPORTUNITY_BRAIN_ENABLE", False)) else {}
                    try:
                        _starv_mode = V453StarvationClassifier.classify()
                        # v606-R1: while a new global brain cycle is in-flight,
                        # current counters may legitimately be zero because the
                        # caller reset them before scanning. Prefer the bounded
                        # current/last-completed-cycle truth when available so
                        # the operator does not see a false NO_OPP label.
                        _truth_fn = globals().get("_v606_current_cycle_starvation_truth")
                        if callable(_truth_fn):
                            _truth = str(_truth_fn() or "").upper()
                            _truth_map = {
                                "SYSTEM": "SYSTEM",
                                "MSE_RANK_STARVATION": "MSE_RANK_STARVATION",
                                "POLICY_STARVATION": "POLICY",
                                "SCORE_STARVATION": "SCORE",
                                "SELECTION_STARVATION": "EXECUTION",
                                "NO_OPP": "NO_OPP",
                            }
                            if _truth in _truth_map:
                                _starv_mode = _truth_map[_truth]
                    except Exception:
                        _starv_mode = "NONE"
                    _last_top = float(_gs.get("last_cycle_top_score", 0.0) or 0.0) if isinstance(_gs, dict) else 0.0
                    _diag = V453StarvationClassifier.window_diagnostics()
                    # V676: when zero candidates reach prequalification/selection,
                    # a large HTF reject delta is an upstream bottleneck and must
                    # not be hidden by an exact downstream structural blocker from
                    # another candidate/cycle. This is telemetry-only.
                    try:
                        _gdel = int(_diag.get("generated_delta", 0) or 0)
                        _pdel = int(_diag.get("prequal_pass_delta", 0) or 0)
                        _sdel = int(_diag.get("selected_delta", 0) or 0)
                        _hdel = int(_diag.get("reject_htf_delta", 0) or 0)
                        _ldel = int(_diag.get("reject_liquidity_delta", 0) or 0)
                        _stdel = int(_diag.get("reject_structure_delta", 0) or 0)
                        _scdel = int(_diag.get("reject_score_delta", 0) or 0)
                        _upstream_htf = (_gdel > 0 and _pdel == 0 and _sdel == 0 and
                                         _hdel > 0 and _hdel >= max(_stdel, _ldel, _scdel, 1))
                        _v684_root_guard = ""
                        try:
                            _v684_truth_fn = globals().get("_v684_truth")
                            if callable(_v684_truth_fn):
                                _v684_root_guard = str((_v684_truth_fn() or {}).get("root") or "").upper()
                        except Exception:
                            _v684_root_guard = ""
                        # V700: active-cycle V684 truth is authoritative over the
                        # older window classifier. Window HTF may only fill an empty
                        # truth; it must not overwrite a real current-cycle POLICY,
                        # STRUCTURE, LIQUIDITY, SCORE, FEE, or EXECUTION root.
                        if _v684_root_guard and _v684_root_guard != "NONE":
                            _starv_mode = _v684_root_guard
                        elif _upstream_htf:
                            _starv_mode = "HTF"
                    except Exception:
                        _v647_record_suppressed_exception()
                    _v669_starv_now = globals().get("_v669_starvation_classify")
                    _v669_current_counts = {}
                    _v669_current_top3 = []
                    if callable(_v669_starv_now):
                        try:
                            _truth_now=dict(_v669_starv_now() or {})
                            _v669_current_counts=dict(_truth_now.get("counts") or {})
                            _v669_current_top3=sorted(((str(k),int(v or 0)) for k,v in _v669_current_counts.items() if int(v or 0)>0),key=lambda kv:(-kv[1],kv[0]))[:3]
                        except Exception: pass
                    _top3=",".join(f"{k}:{v}" for k,v in (_v669_current_top3 or (_diag.get("top3_rejects") or []))) or "-"
                    _exact = STATS.get("v585_last_exact_builder_block") or {}
                    _exact_age = _wall_age_sec(float(_exact.get("ts",0.0) or 0.0)) if _exact else None
                    if (_exact_age is None or _exact_age > float(CONFIG.get("V586_STARVATION_EXACT_ROOT_AGE_SEC",900.0))):
                        _exact = {}
                    _selected_display = _v702_selected_route_display(_diag) if callable(globals().get("_v702_selected_route_display")) else ""
                    _exact_root = _selected_display if _selected_display else "-"
                    if _exact and not _selected_display:
                        _exact_root = f"{str(_exact.get('stage') or '?')}:{str(_exact.get('reason') or '?')[:110]}"
                        # V640: an exact, fresh canonical builder blocker is
                        # stronger evidence than a stale/aggregate starvation
                        # label. Keep this telemetry-only and do not alter any
                        # trading decision.
                        # Do not let a stale/current builder blocker override a
                        # stronger upstream HTF starvation signal. The builder can
                        # only be the public root when at least one candidate actually
                        # reached PRE/SEL/Q; otherwise HTF/policy is upstream truth.
                        try:
                            _xr = str(_exact.get("reason") or "").lower()
                            _diag_pre = int(_diag.get("prequal_pass_delta", 0) or 0) if isinstance(locals().get("_diag"), dict) else 0
                            _diag_sel = int(_diag.get("selected_delta", 0) or 0) if isinstance(locals().get("_diag"), dict) else 0
                            if ((_diag_pre > 0 or _diag_sel > 0) and
                                any(tok in _xr for tok in (
                                    "structural", "fake_break", "microstruct",
                                    "sl_geometry",
                                ))):
                                _starv_mode = "STRUCTURE"
                        except Exception:
                            _v647_record_suppressed_exception()
                    # V700: use the same terminal active-cycle truth as heartbeat;
                    # legacy _v584_live_bottleneck may legitimately be empty while
                    # the final V684 ledger already has the exact current-cycle root.
                    try:
                        _truth_live_fn = globals().get("_v699_truthful_starvation_snapshot")
                        _truth_live = dict(_truth_live_fn() or {}) if callable(_truth_live_fn) else {}
                        _live_root = str(_truth_live.get("root") or "NONE")
                        _live_detail = str(_truth_live.get("detail") or _truth_live.get("source") or "")
                        if _live_root and _live_root != "NONE":
                            _starv_mode = _live_root
                    except Exception:
                        _live_root, _live_detail = _v584_live_bottleneck()
                        if _live_root and _live_root != "NONE":
                            _starv_mode = _live_root
                    _msg = (
                        "[V422-StarvAlert] mode=%s | window_sec=%.0f | last_cycle_age_sec=%s | "
                        "generated_delta=%d prequal_pass_delta=%d ranked_delta=%d selected_delta=%d "
                        "queued_delta=%d sent_delta=%d | reject_htf_delta=%d reject_liquidity_delta=%d "
                        "reject_structure_delta=%d reject_score_delta=%d | top3=%s | selected_stage=%s | "
                        "current_cycle_top3=%s current_cycle_counts=%s | selected_stage_scope=CYCLE | "
                        "selected_delta_scope=WINDOW | window_delta_scope=WINDOW | live_root=%s | exact_builder=%s | no_send_sec=%.0f relaxed=%s"
                        % (_starv_mode, float(_diag.get("window_sec",0.0) or 0.0),
                           _diag.get("last_successful_global_cycle_age_sec"),
                           int(_diag.get("generated_delta",0) or 0),
                           int(_diag.get("prequal_pass_delta",0) or 0),
                           int(_diag.get("ranked_delta",0) or 0),
                           int(_diag.get("selected_delta",0) or 0),
                           int(_diag.get("queued_delta",0) or 0),
                           int(_diag.get("sent_delta",0) or 0),
                           int(_diag.get("reject_htf_delta",0) or 0),
                           int(_diag.get("reject_liquidity_delta",0) or 0),
                           int(_diag.get("reject_structure_delta",0) or 0),
                           int(_diag.get("reject_score_delta",0) or 0),
                           _top3, _selected_display or "-",
                           ",".join(f"{k}:{v}" for k,v in _v669_current_top3) or "-",
                           str(_v669_current_counts)[:280],
                           str(_live_root or "UNKNOWN"), _exact_root,
                           (now - cls._last_send_ts), "ON" if _relaxed_on else "off")
                    )
                    logger.warning(_msg)
                    STATS["v422_starvation_alerts_fired"] = \
                        STATS.get("v422_starvation_alerts_fired", 0) + 1
                    try:
                        await TelegramDispatcher.enqueue(
                            "<b>Starvation Alert</b>\n<code>" + _msg + "</code>")
                    except Exception:
                        _v647_record_suppressed_exception()
            except asyncio.CancelledError:
                raise
            except Exception as _sa_e:
                try:
                    logger.debug("[V422-StarvAlert] tick suppressed: %s" % _sa_e)
                except Exception:
                    _v647_record_suppressed_exception()
                await asyncio.sleep(30)


def _v424_self_test() -> None:
    """Offline PULLBACK diagnostics smoke test; never connects to MEXC."""
    if not _PDNP_OK:
        return
    V424PullbackDiagnostics._events.clear()
    idx = pd.date_range("2025-01-01", periods=80, freq="5min")
    base = np.linspace(100.0, 120.0, 80)
    df5 = pd.DataFrame({"open":base-0.1,"high":base+0.2,"low":base-0.2,"close":base,"volume":np.linspace(100,200,80)}, index=idx)
    df15 = pd.DataFrame({"open":base-0.2,"high":base+0.3,"low":base-0.3,"close":base,"volume":np.linspace(200,300,80)}, index=idx)
    d = V424PullbackDiagnostics.diagnose_detector("TEST/USDT", df15, df5)
    assert d.get("family") == "PULLBACK"
    V424PullbackDiagnostics.note_router_reject("TEST/USDT", d)
    V424PullbackDiagnostics.note_pipeline_reject("TEST/USDT", "family_regime_disallowed", "family_policy", {"family":"PULLBACK"})
    s = V424PullbackDiagnostics.snapshot()
    assert s.get("total_events",0) >= 1 and "top_reasons" in s
    df5.iloc[-1, df5.columns.get_loc("close")] = 9999.0
    d2 = V424PullbackDiagnostics.diagnose_detector("TEST/USDT", df15, df5)
    assert d2.get("family") == "PULLBACK"
    logger.info("V4.2.4 PULLBACK diagnostics self-test: PASS")

# =============================================================================
#  SECTION V4.2.5 — BEARISH RECOVERY ARCHITECTURE (STARVATION-HARDENED, FAIL-CLOSED)
# =============================================================================
#
#  Design contract (v4.2.5)
#  ------------------------
#  * LONG-ONLY spot. NO shorts / futures / leverage. Nothing here creates an
#    execution shortcut: a bearish-recovery candidate re-enters the SAME
#    funnel (FamilyPolicy -> MicroStructure -> CompositeScorer -> DailyCB ->
#    Dedup -> Repricing -> PreSendGate -> Balance -> Exposure -> Liquidity ->
#    Precision -> SL -> Entry). Every downstream hard gate applies unchanged.
#  * FamilyPolicyLayer remains the ONE canonical source for "is this family
#    allowed in this regime". The legacy hard-coded bearish-family set
#    set in SignalBuilder was REMOVED and replaced by a consistency ASSERTION
#    against FamilyPolicyLayer. A contradiction is fail-closed (reject) and is
#    recorded as telemetry divergence — never silently resolved.
#  * BEARISH is decomposed into MACRO (BTC) x LOCAL (per-symbol). Recovery is a
#    separate strategy mode (strategy_mode="BEARISH_RECOVERY"); it is NOT a
#    relaxation of the ordinary PULLBACK family and NEVER overrides CrashGuard.
#  * Every recovery decision is fail-closed: missing/insufficient/NaN data or
#    ANY exception inside recovery logic => REJECT (not allow).
#  * Telemetry remains strictly non-blocking.
#
#  This layer is additive/minimal-diff: Bullish & Neutral paths are unchanged;
#  only the BEARISH branch gains a bounded, gated recovery path.
# =============================================================================

CONFIG.update({
    # ---- v4.2.5 master switches -------------------------------------------
    # Master enable for the whole Bearish Recovery architecture. When False
    # the BEARISH branch behaves exactly like v4.2.4 (only sweep/reversion
    # families allowed, ordinary PULLBACK still rejected).
    "V425_BEARISH_RECOVERY_ENABLE": True,

    # ---- Crash / severity guard -------------------------------------------
    # BEARISH severity classes: NORMAL < STRESSED < CRASH. CRASH => zero new
    # long entries regardless of local recovery evidence. Thresholds are
    # bounded and configurable; crash guard can never be bypassed by recovery.
    "V425_BEARISH_SEVERITY_ENABLE": True,
    "V425_BEARISH_STRESSED_DROP_PCT": -3.0,   # 15m window drop % (BTC)
    "V425_BEARISH_CRASH_DROP_PCT":    -6.0,   # 15m window drop % (BTC)
    "V425_BEARISH_CRASH_ATR_MULT":     2.5,   # last 15m ATR vs 20-bar mean
    "V425_BEARISH_CRASH_BREAKDOWN_N":  3,     # consecutive lower-low 4h closes
    "V425_BEARISH_CRASH_WINDOW_15M":   8,     # ~2h
    "V425_BEARISH_CRASH_WINDOW_4H":    3,     # 3 closed 4h bars for breakdown

    # ---- Local regime (per-symbol) ----------------------------------------
    # BEARISH / NEUTRAL / RECOVERY / LOCAL_BULLISH computed on CLOSED bars.
    "V425_LOCAL_RECOVERY_REQUIRE_HIGHER_LOW": True,
    "V425_LOCAL_RECOVERY_REQUIRE_RECLAIM":    True,   # close > EMA20 or VWAP
    "V425_LOCAL_RECOVERY_REQUIRE_BULLISH_CLOSE": True,
    "V425_LOCAL_RECOVERY_RSI_LO": 40.0,
    "V425_LOCAL_RECOVERY_RSI_HI": 68.0,
    "V425_LOCAL_RECOVERY_MIN_VOLUME_RATIO": 0.8,  # not-dead volume floor
    "V425_LOCAL_RECOVERY_MAX_DISTANCE_ATR": 2.60,  # v4.2.7: bounded recovery envelope; extreme extensions use countertrend families  # bounded envelope to anchor

    # ---- Recovery score (bounded contributions, fail-closed) ---------------
    # Each sub-score is clamped to [0, weight]. A single feature can NEVER
    # reach the threshold alone. Missing required data => fail closed.
    "V425_RECOVERY_MIN_SCORE": 65.0,  # v4.2.7: stronger recovery threshold compensates local-bullish enablement          # out of 100
    "V425_RECOVERY_W_STRUCTURE": 22.0,
    "V425_RECOVERY_W_RECLAIM":    18.0,
    "V425_RECOVERY_W_MOMENTUM":   14.0,
    "V425_RECOVERY_W_RSI":        12.0,
    "V425_RECOVERY_W_VOLUME":     10.0,
    "V425_RECOVERY_W_RS_VS_BTC":  10.0,
    "V425_RECOVERY_W_ZONE":        8.0,
    "V425_RECOVERY_W_DISTANCE":    6.0,
    # macro stress is a MULTIPLIER (0..1), not additive: stressed macro shrinks
    # the score so a stressed bearish tape needs even stronger local evidence.
    "V425_RECOVERY_STRESSED_SCORE_MULT": 0.80,

    # ---- Bearish Recovery candidate policy ----------------------------------
    "V425_RECOVERY_MIN_TIER": "MID",          # tier floor for recovery trades
    "V425_RECOVERY_REQUIRE_NON_CRASH": True,  # hard: never in CRASH
    "V425_RECOVERY_LOCAL_BULLISH_ENABLE": True,  # v4.2.7: bounded LOCAL_BULLISH recovery branch  # LOCAL_BULLISH branch OFF by default (needs stronger bar)
    # Local regime hysteresis: avoid flip-flopping RECOVERY<->NEUTRAL.
    "V425_LOCAL_REGIME_MIN_HOLD_BARS": 1,

    # ---- Regime-aware LIQUIDITY_SWEEP volume floor ---------------------------
    # BULLISH/NEUTRAL keep the existing strict floor (1.4). In BEARISH a lower
    # bounded floor is allowed ONLY because it is compensated by extra
    # structural evidence (sweep + reclaim + bullish close + higher-low).
    "V425_SWEEP_BEARISH_VOLUME_FLOOR": 1.1,   # bounded 1.0-1.1 as required
    "V425_SWEEP_BEARISH_REQUIRE_RECLAIM": True,
    "V425_SWEEP_BEARISH_REQUIRE_BULLISH_CLOSE": True,
    "V425_SWEEP_BEARISH_REQUIRE_HIGHER_LOW": True,
    "V425_SWEEP_BEARISH_REQUIRE_NON_CRASH": True,

    # ---- Regime-aware MEAN_REVERSION tier floor ------------------------------
    # Keep min_tier=LARGE globally; in BEARISH allow MID only WITH strong
    # reversal confirmation (oversold + support interaction + bullish
    # rejection + reclaim + local structure improvement).
    "V425_MR_BEARISH_ALLOW_MID_TIER": True,
    "V425_MR_BEARISH_RSI_OVERSOLD": 32.0,
    "V425_MR_BEARISH_REQUIRE_REJECTION": True,
    "V425_MR_BEARISH_REQUIRE_RECLAIM": True,

    # ---- Starvation taxonomy (technical vs opportunity) ----------------------
    "V425_STARV_TAXONOMY_ENABLE": True,
    # Opportunity-starvation persistence: N consecutive watchdog windows.
    "V425_STARV_OPP_PERSIST_WINDOWS": 2,
    # Technical starvation: pipeline active (G>0,E>0 or Q>0) but zero sends.
    "V425_STARV_TECH_MIN_G": 50,
    # Alert cooldowns (seconds) so neither starvation type spams.
    "V425_STARV_ALERT_COOLDOWN_SEC": 600,

    # ---- Watchdog scheduler --------------------------------------------------
    # Independent periodic task; NOT tied to heartbeat or scanner completion.
    "V425_WATCHDOG_TASK_ENABLE": True,
    "V425_WATCHDOG_TASK_INTERVAL_SEC": 45,    # 30-60s cadence as required
})


# ---------------------------------------------------------------------------
# V425 — MACRO SEVERITY / CRASH GUARD (fail-closed)
# ---------------------------------------------------------------------------
class V425BearishSeverity:
    """Classify BEARISH into NORMAL / STRESSED / CRASH.

    Pure read-only evaluation over already-fetched BTC frames. Missing data
    or any exception => treated as CRASH (fail-closed: zero new longs).
    """
    NORMAL   = "BEARISH_NORMAL"
    STRESSED = "BEARISH_STRESSED"
    CRASH    = "BEARISH_CRASH"

    @classmethod
    def classify(cls, macro_regime: str, df_btc_15m, df_btc_4h=None) -> str:
        try:
            if str(macro_regime).upper() != "BEARISH":
                return "NON_BEARISH"
            if not bool(CONFIG.get("V425_BEARISH_SEVERITY_ENABLE", True)):
                return cls.NORMAL
            # BTCContext already maps CRASH/BLOCK -> hard block upstream; mirror it.
            try:
                _btc_ctx = BTCContext._state
            except Exception:
                _btc_ctx = "OK"
            if _btc_ctx in ("CRASH", "BLOCK"):
                return cls.CRASH

            win = int(CONFIG.get("V425_BEARISH_CRASH_WINDOW_15M", 8))
            crash_drop = float(CONFIG.get("V425_BEARISH_CRASH_DROP_PCT", -6.0))
            stress_drop = float(CONFIG.get("V425_BEARISH_STRESSED_DROP_PCT", -3.0))
            atr_mult = float(CONFIG.get("V425_BEARISH_CRASH_ATR_MULT", 2.5))

            drop_pct = 0.0
            atr_expanding = False
            if _PDNP_OK and df_btc_15m is not None and len(df_btc_15m) >= win + 2:
                closes = df_btc_15m["close"]
                first = float(closes.iloc[-(win + 1)])
                last = float(closes.iloc[-2])  # v4.5.86: closed-bar severity only
                if first > 0:
                    drop_pct = (last - first) / first * 100.0
                try:
                    atr_s = Indicators.atr(df_btc_15m, int(CONFIG.get("ATR_PERIOD", 14)))
                    a_now = float(atr_s.iloc[-2])
                    a_ref = float(atr_s.iloc[-22:-2].mean()) if len(atr_s) >= 22 else a_now
                    if a_ref > 0 and math.isfinite(a_now) and math.isfinite(a_ref):
                        atr_expanding = (a_now / a_ref) >= atr_mult
                except Exception:
                    atr_expanding = False

            # structural breakdown: consecutive lower-low closes on 4h
            breakdown = False
            try:
                n4 = int(CONFIG.get("V425_BEARISH_CRASH_WINDOW_4H", 3))
                need = int(CONFIG.get("V425_BEARISH_CRASH_BREAKDOWN_N", 3))
                if _PDNP_OK and df_btc_4h is not None and len(df_btc_4h) >= n4 + 1:
                    lows = [float(df_btc_4h["low"].iloc[-k]) for k in range(2, 2 + n4)]
                    lower = sum(1 for i in range(len(lows) - 1) if lows[i] < lows[i + 1])
                    breakdown = lower >= (need - 1)
            except Exception:
                breakdown = False

            if drop_pct <= crash_drop or (atr_expanding and drop_pct <= stress_drop) or breakdown:
                return cls.CRASH
            if drop_pct <= stress_drop or atr_expanding:
                return cls.STRESSED
            return cls.NORMAL
        except Exception as e:
            # Fail-closed: any evaluation error => CRASH (no new longs).
            try:
                logger.debug(f"[V425.severity] eval error -> CRASH: {e}")
            except Exception:
                _v647_record_suppressed_exception()
            return cls.CRASH

    @classmethod
    def allows_new_long(cls, severity: str) -> bool:
        return str(severity) != cls.CRASH


# ---------------------------------------------------------------------------
# V425 — LOCAL REGIME (per-symbol, CLOSED bars only)
# ---------------------------------------------------------------------------
class V425LocalRegime:
    """Per-symbol state: BEARISH / NEUTRAL / RECOVERY / LOCAL_BULLISH.

    Computed ONLY on closed 15m/5m bars (iloc[-2] is last closed). Never uses
    the forming candle. Fail-closed: insufficient data => BEARISH (no trade).
    """
    BEARISH = "BEARISH"
    NEUTRAL = "NEUTRAL"
    RECOVERY = "RECOVERY"
    LOCAL_BULLISH = "LOCAL_BULLISH"

    @classmethod
    def _features(cls, df_15m, df_5m) -> Optional[Dict[str, Any]]:
        if not _PDNP_OK or df_15m is None or df_5m is None:
            return None
        if len(df_15m) < 60 or len(df_5m) < 30:
            return None
        try:
            c15 = float(df_15m["close"].iloc[-2])
            e20_15 = float(Indicators.ema(df_15m["close"], int(CONFIG.get("EMA_FAST", 20))).iloc[-2])
            e50_15 = float(Indicators.ema(df_15m["close"], int(CONFIG.get("EMA_MID", 50))).iloc[-2])
            c5 = float(df_5m["close"].iloc[-2])
            o5 = float(df_5m["open"].iloc[-2])
            e20_5 = float(Indicators.ema(df_5m["close"], int(CONFIG.get("EMA_FAST", 20))).iloc[-2])
            atr5_s = Indicators.atr(df_5m, int(CONFIG.get("ATR_PERIOD", 14)))
            atr5 = float(atr5_s.iloc[-2])
            rsi5_s = Indicators.rsi(df_5m["close"], int(CONFIG.get("RSI_PERIOD", 14)))
            rsi5 = float(rsi5_s.iloc[-2]) if rsi5_s is not None else None
            # vwap (bounded)
            vwap5 = None
            try:
                v = Indicators.vwap(df_5m)
                vwap5 = float(v.iloc[-2]) if v is not None else None
                if vwap5 is not None and (not math.isfinite(vwap5) or vwap5 <= 0):
                    vwap5 = None
            except Exception:
                vwap5 = None
            # volume ratio: last closed 5m vol vs prior 20-bar mean
            vol_ratio = None
            try:
                vv = df_5m["volume"].astype(float)
                v_now = float(vv.iloc[-2])
                v_ref = float(vv.iloc[-22:-2].mean()) if len(vv) >= 22 else None
                if v_ref and v_ref > 0:
                    vol_ratio = v_now / v_ref
            except Exception:
                vol_ratio = None
            # higher-low on 15m: last closed low > low 3 bars earlier
            higher_low = False
            try:
                lows = df_15m["low"].astype(float)
                higher_low = float(lows.iloc[-2]) > float(lows.iloc[-5]) if len(lows) >= 5 else False
            except Exception:
                higher_low = False
            # 15m breakdown: continuous lower lows (no recovery)
            breakdown = False
            try:
                lows = df_15m["low"].astype(float)
                breakdown = (float(lows.iloc[-2]) < float(lows.iloc[-3]) and
                             float(lows.iloc[-3]) < float(lows.iloc[-4])) if len(lows) >= 4 else False
            except Exception:
                breakdown = False
            bullish_close = c5 > o5
            reclaim_ema20 = c5 > e20_5
            reclaim_vwap = (vwap5 is not None and c5 > vwap5)
            dist_atr = abs(c5 - e20_5) / max(atr5, 1e-9) if atr5 > 0 else None
            ema20_slope_up = False
            try:
                e = Indicators.ema(df_5m["close"], int(CONFIG.get("EMA_FAST", 20)))
                ema20_slope_up = float(e.iloc[-2]) > float(e.iloc[-4]) if len(e) >= 4 else False
            except Exception:
                ema20_slope_up = False
            return {
                "close_15m": c15, "ema20_15m": e20_15, "ema50_15m": e50_15,
                "close_5m": c5, "open_5m": o5, "ema20_5m": e20_5,
                "atr_5m": atr5, "rsi_5m": rsi5, "vwap_5m": vwap5,
                "volume_ratio": vol_ratio, "higher_low": higher_low,
                "breakdown_15m": breakdown, "bullish_close": bullish_close,
                "reclaim_ema20": reclaim_ema20, "reclaim_vwap": reclaim_vwap,
                "dist_atr_ema20": dist_atr, "ema20_slope_up": ema20_slope_up,
            }
        except Exception:
            return None

    @classmethod
    def classify(cls, macro_regime: str, df_15m, df_5m) -> str:
        try:
            if str(macro_regime).upper() != "BEARISH":
                return "NON_BEARISH"
            f = cls._features(df_15m, df_5m)
            if f is None:
                return cls.BEARISH  # fail-closed
            # LOCAL_BULLISH: price firmly above both 15m EMAs with healthy slope.
            if f["close_15m"] > f["ema20_15m"] > f["ema50_15m"] and f["ema20_slope_up"]:
                return cls.LOCAL_BULLISH
            # RECOVERY requires the configured bounded confirmation set.
            need_hl = bool(CONFIG.get("V425_LOCAL_RECOVERY_REQUIRE_HIGHER_LOW", True))
            need_reclaim = bool(CONFIG.get("V425_LOCAL_RECOVERY_REQUIRE_RECLAIM", True))
            need_bclose = bool(CONFIG.get("V425_LOCAL_RECOVERY_REQUIRE_BULLISH_CLOSE", True))
            rsi_lo = float(CONFIG.get("V425_LOCAL_RECOVERY_RSI_LO", 40.0))
            rsi_hi = float(CONFIG.get("V425_LOCAL_RECOVERY_RSI_HI", 68.0))
            vmin = float(CONFIG.get("V425_LOCAL_RECOVERY_MIN_VOLUME_RATIO", 0.8))
            dmax = float(CONFIG.get("V425_LOCAL_RECOVERY_MAX_DISTANCE_ATR", 2.2))

            ok = True
            if need_hl and not f["higher_low"]:
                ok = False
            if need_reclaim and not (f["reclaim_ema20"] or f["reclaim_vwap"]):
                ok = False
            if need_bclose and not f["bullish_close"]:
                ok = False
            if f["rsi_5m"] is None or not (rsi_lo <= float(f["rsi_5m"]) <= rsi_hi):
                ok = False
            if f["volume_ratio"] is None or float(f["volume_ratio"]) < vmin:
                ok = False
            if f["dist_atr_ema20"] is None or float(f["dist_atr_ema20"]) > dmax:
                ok = False
            if f["breakdown_15m"]:
                ok = False  # ongoing local breakdown is NOT recovery
            if ok:
                return cls.RECOVERY
            # NEUTRAL: not breaking down, but recovery confirmations incomplete.
            if not f["breakdown_15m"]:
                return cls.NEUTRAL
            return cls.BEARISH
        except Exception as e:
            try:
                logger.debug(f"[V425.local] classify error -> BEARISH: {e}")
            except Exception:
                _v647_record_suppressed_exception()
            return cls.BEARISH


# ---------------------------------------------------------------------------
# V425 — RECOVERY SCORE (bounded contributions, fail-closed)
# ---------------------------------------------------------------------------
class V425RecoveryScore:
    """Independent 0..100 confidence for a BEARISH_RECOVERY candidate.

    Every contribution is clamped to [0, weight]; no single feature can reach
    the threshold. Missing required data => None (fail-closed). In a STRESSED
    macro the total is multiplied down (needs even stronger local evidence).
    """

    @classmethod
    def compute(cls, features: Dict[str, Any], severity: str,
                rs_vs_btc: Optional[float] = None,
                zone: Optional[str] = None) -> Optional[Dict[str, Any]]:
        if features is None:
            return None
        try:
            w_struct = float(CONFIG.get("V425_RECOVERY_W_STRUCTURE", 22.0))
            w_reclaim = float(CONFIG.get("V425_RECOVERY_W_RECLAIM", 18.0))
            w_mom = float(CONFIG.get("V425_RECOVERY_W_MOMENTUM", 14.0))
            w_rsi = float(CONFIG.get("V425_RECOVERY_W_RSI", 12.0))
            w_vol = float(CONFIG.get("V425_RECOVERY_W_VOLUME", 10.0))
            w_rs = float(CONFIG.get("V425_RECOVERY_W_RS_VS_BTC", 10.0))
            w_zone = float(CONFIG.get("V425_RECOVERY_W_ZONE", 8.0))
            w_dist = float(CONFIG.get("V425_RECOVERY_W_DISTANCE", 6.0))
            min_score = float(CONFIG.get("V425_RECOVERY_MIN_SCORE", 60.0))

            parts = {}
            # structure: higher-low + no ongoing breakdown
            s = 0.0
            if features.get("higher_low"):
                s += w_struct * 0.6
            if not features.get("breakdown_15m"):
                s += w_struct * 0.4
            parts["recovery_structure"] = _clamp(s, 0.0, w_struct)

            # reclaim quality: above EMA20 and/or VWAP
            r = 0.0
            if features.get("reclaim_ema20"):
                r += w_reclaim * 0.6
            if features.get("reclaim_vwap"):
                r += w_reclaim * 0.4
            parts["reclaim_quality"] = _clamp(r, 0.0, w_reclaim)

            # momentum recovery: bullish close + ema20 slope up
            m = 0.0
            if features.get("bullish_close"):
                m += w_mom * 0.5
            if features.get("ema20_slope_up"):
                m += w_mom * 0.5
            parts["momentum_recovery"] = _clamp(m, 0.0, w_mom)

            # RSI recovery: closer to mid-band => more of the weight
            rsi = features.get("rsi_5m")
            if rsi is None:
                return None  # required data missing => fail closed
            rsi_lo = float(CONFIG.get("V425_LOCAL_RECOVERY_RSI_LO", 40.0))
            rsi_hi = float(CONFIG.get("V425_LOCAL_RECOVERY_RSI_HI", 68.0))
            rsi_f = _clamp((float(rsi) - rsi_lo) / max(1e-9, rsi_hi - rsi_lo), 0.0, 1.0)
            parts["RSI_recovery"] = _clamp(w_rsi * rsi_f, 0.0, w_rsi)

            # volume quality: scale toward 2x reference
            vr = features.get("volume_ratio")
            if vr is None:
                return None  # required
            vol_f = _clamp((float(vr) - 0.5) / 1.5, 0.0, 1.0)
            parts["volume_quality"] = _clamp(w_vol * vol_f, 0.0, w_vol)

            # relative strength vs BTC (positive rs => more weight)
            if rs_vs_btc is None or not math.isfinite(float(rs_vs_btc)):
                rs_f = 0.0  # optional factor: absence contributes 0, not failure
            else:
                rs_f = _clamp((float(rs_vs_btc) + 0.02) / 0.04, 0.0, 1.0)
            parts["relative_strength"] = _clamp(w_rs * rs_f, 0.0, w_rs)

            # zone quality: preferred pullback anchor zones get the weight
            z = str(zone or "").upper()
            zone_ok = any(z.startswith(p) or p in z
                          for p in ("EMA20", "EMA50", "VWAP", "SUPPORT"))
            parts["zone_quality"] = w_zone if zone_ok else 0.0

            # distance quality: nearer anchor => more weight (bounded)
            d = features.get("dist_atr_ema20")
            if d is None:
                d_f = 0.0
            else:
                dmax = float(CONFIG.get("V425_LOCAL_RECOVERY_MAX_DISTANCE_ATR", 2.2))
                d_f = _clamp(1.0 - float(d) / max(1e-9, dmax), 0.0, 1.0)
            parts["distance_quality"] = _clamp(w_dist * d_f, 0.0, w_dist)

            raw = sum(parts.values())
            # BTC stress is a multiplier, never additive.
            mult = 1.0
            if str(severity) == V425BearishSeverity.STRESSED:
                mult = float(CONFIG.get("V425_RECOVERY_STRESSED_SCORE_MULT", 0.80))
            score = _clamp(raw * mult, 0.0, 100.0)
            return {"score": round(score, 3), "min_score": min_score,
                    "macro_stress_mult": mult, "parts": {k: round(v, 3) for k, v in parts.items()},
                    "passed": bool(score >= min_score)}
        except Exception as e:
            try:
                logger.debug(f"[V425.score] error -> fail closed: {e}")
            except Exception:
                _v647_record_suppressed_exception()
            return None


# ---------------------------------------------------------------------------
# V425 — BEARISH RECOVERY ENGINE (bounded candidate detector)
# ---------------------------------------------------------------------------
class V425BearishRecovery:
    """Build a PULLBACK-family candidate ONLY under BEARISH macro + LOCAL
    RECOVERY with a passing recovery score. The candidate carries
    strategy_mode='BEARISH_RECOVERY' so every downstream layer can distinguish
    it from an ordinary pullback. Ordinary PULLBACK in BEARISH stays rejected.
    """

    @classmethod
    def enabled(cls) -> bool:
        return bool(CONFIG.get("V425_BEARISH_RECOVERY_ENABLE", True))

    @classmethod
    def try_build(cls, symbol: str, macro_regime: str, severity: str,
                  tier: str, df_15m, df_5m, rs_vs_btc: Optional[float] = None
                  ) -> Optional[Dict[str, Any]]:
        if not cls.enabled():
            return None
        try:
            if str(macro_regime).upper() != "BEARISH":
                return None
            # Crash guard is ABSOLUTE — recovery never overrides it.
            if not V425BearishSeverity.allows_new_long(severity):
                STATS["bearish_recovery_crash_blocks"] = \
                    STATS.get("bearish_recovery_crash_blocks", 0) + 1
                return None
            local = V425LocalRegime.classify(macro_regime, df_15m, df_5m)
            if local == V425LocalRegime.BEARISH or local == V425LocalRegime.NEUTRAL:
                return None  # NO NEW LONG / WATCH ONLY
            if local == V425LocalRegime.LOCAL_BULLISH:
                if not bool(CONFIG.get("V425_RECOVERY_LOCAL_BULLISH_ENABLE", True)):
                    STATS["bearish_recovery_local_bullish_disabled"] = STATS.get("bearish_recovery_local_bullish_disabled", 0) + 1
                    return None
                # Stronger local-bullish confirmation compensates for macro BEARISH:
                # closed-bar reclaim, healthy volume, non-overheated RSI, no 15m
                # breakdown. This is deliberately stricter than RECOVERY.
                _f = V425LocalRegime._features(df_15m, df_5m)
                if _f is None:
                    return None
                _rsi = _f.get("rsi_5m")
                _vr = _f.get("volume_ratio")
                if _f.get("breakdown_15m"):
                    STATS["bearish_recovery_local_bullish_rejects"] = STATS.get("bearish_recovery_local_bullish_rejects", 0) + 1
                    return None
                if not (_f.get("reclaim_ema20") or _f.get("reclaim_vwap")):
                    STATS["bearish_recovery_local_bullish_rejects"] = STATS.get("bearish_recovery_local_bullish_rejects", 0) + 1
                    return None
                if _rsi is None or not (float(CONFIG.get("V425_LOCAL_BULLISH_MIN_RSI",45.0)) <= float(_rsi) <= float(CONFIG.get("V425_LOCAL_BULLISH_MAX_RSI",72.0))):
                    STATS["bearish_recovery_local_bullish_rejects"] = STATS.get("bearish_recovery_local_bullish_rejects", 0) + 1
                    return None
                if _vr is None or float(_vr) < float(CONFIG.get("V425_LOCAL_BULLISH_MIN_VOLUME_RATIO",1.0)):
                    STATS["bearish_recovery_local_bullish_rejects"] = STATS.get("bearish_recovery_local_bullish_rejects", 0) + 1
                    return None
            # tier floor (bounded)
            min_tier = str(CONFIG.get("V425_RECOVERY_MIN_TIER", "MID"))
            if _FAMILY_RANK.get(str(tier), -1) < _FAMILY_RANK.get(min_tier, 2):
                STATS["bearish_recovery_rejects"] = \
                    STATS.get("bearish_recovery_rejects", 0) + 1
                return None
            feats = V425LocalRegime._features(df_15m, df_5m)
            scored = V425RecoveryScore.compute(feats, severity, rs_vs_btc=rs_vs_btc,
                                               zone="EMA20")
            if scored is None or not scored.get("passed"):
                STATS["bearish_recovery_rejects"] = \
                    STATS.get("bearish_recovery_rejects", 0) + 1
                return None
            STATS["bearish_recovery_candidates"] = \
                STATS.get("bearish_recovery_candidates", 0) + 1
            # zone_ref: prefer the reclaimed anchor (EMA20 on 5m) so downstream
            # SL/entry logic has a sane reference; pipeline still re-validates.
            zone_ref = float(feats.get("ema20_5m") or 0.0) or None
            _rscore=float(scored.get("score") or 0.0)
            if _rscore >= float(CONFIG.get("BEAR_RECOVERY_TIER_A_MIN",0.72)):
                _rtier="A"; _rf=float(CONFIG.get("BEAR_RECOVERY_TIER_A_RISK_FACTOR",0.75))
            elif _rscore >= float(CONFIG.get("BEAR_RECOVERY_TIER_B_MIN",0.55)):
                _rtier="B"; _rf=float(CONFIG.get("BEAR_RECOVERY_TIER_B_RISK_FACTOR",0.60))
            elif _rscore >= float(CONFIG.get("BEAR_RECOVERY_TIER_C_MIN",0.45)):
                _rtier="C"; _rf=float(CONFIG.get("BEAR_RECOVERY_TIER_C_RISK_FACTOR",0.45))
            else:
                return None
            return {
                "family": "PULLBACK",                 # pipeline compatibility
                "strategy_mode": "BEARISH_RECOVERY",  # distinguishes the mode
                "zone_ref": zone_ref,
                "anchor": "EMA20",
                "local_regime": local,
                "macro_severity": severity,
                "recovery_score": _rscore,
                "recovery_quality_tier": _rtier,
                "_v44_risk_factor": _rf,
                "recovery_parts": scored.get("parts"),
                "_v425_recovery": True,
            }
        except Exception as e:
            # Fail-closed: ANY exception => no candidate.
            try:
                logger.debug(f"[V425.recovery] {symbol} suppressed: {e}")
            except Exception:
                _v647_record_suppressed_exception()
            return None


# ---------------------------------------------------------------------------
# V425 — REGIME-AWARE FAMILY HTF / VOLUME / TIER POLICY HELPERS
# ---------------------------------------------------------------------------
# =============================================================================
# V702 A10 — STRATEGY-AWARE HTF POLICY
# -----------------------------------------------------------------------------
# HTF data remains mandatory and contributes to ranking/quality. Alignment is
# a hard rejection only for strategies whose edge depends on continuation.
# Pullback uses a bounded 45/100 contextual floor; reversal/reclaim families
# use HTF as context and still require local confirmation, valid HTF facts,
# non-crash regime and every downstream structure/liquidity/economics gate.
# This policy never changes Spot LONG_ONLY or enables an order path.
# =============================================================================
_V702_HTF_STRICT_FAMILIES = frozenset({
    "BREAKOUT_RETEST", "BREAKOUT_CONTINUATION", "MOMENTUM_EXPANSION",
    "LOCAL_STRENGTH_BREAKOUT", "COMPRESSION_EXPANSION", "TREND_CONTINUATION",
    "CONTINUATION_RECLAIM", "RELATIVE_STRENGTH_LEADER", "VOLATILITY_BURST",
    "MICRO_TREND_CONTINUATION", "SWING_PULLBACK", "MTF_PULLBACK",
    "LIQUIDITY_ACCEPTANCE_RECLAIM", "OPPORTUNITY_SCOUT",
})
_V702_HTF_CONTEXTUAL_FAMILIES = frozenset({"PULLBACK"})
_V702_HTF_SOFT_FAMILIES = frozenset({
    "MEAN_REVERSION", "LIQUIDITY_SWEEP_REVERSAL", "EXTREME_FLUSH_REVERSAL",
    "FAILED_BREAKOUT_RECLAIM",
})
CONFIG.update({
    "V702_STRATEGY_AWARE_HTF_POLICY_ENABLE": True,
    "V702_HTF_PULLBACK_CONTEXT_FLOOR": 45.0,
    "V702_HTF_SOFT_CONTEXT_MIN_STRENGTH": 35.0,
    "V702_HTF_SOFT_CONTEXT_REQUIRE_LOCAL_CONFIRMATION": True,
})

def _v702_htf_policy_name(family: str = "", strategy_mode: str = "", features=None) -> str:
    try:
        fam = str(family or "").upper().strip()
        mode = str(strategy_mode or "").upper().strip()
        fs = features if isinstance(features, dict) else {}
        if mode == "DUAL_CONFIRMATION_ENTRY":
            branch = str(fs.get("dual_branch") or fs.get("dual_confirmation_branch") or "").upper()
            mode = "BREAKOUT_RETEST" if branch == "A" else ("PULLBACK" if branch == "B" else mode)
        key = mode if mode in (_V702_HTF_STRICT_FAMILIES | _V702_HTF_CONTEXTUAL_FAMILIES | _V702_HTF_SOFT_FAMILIES) else fam
        if key in _V702_HTF_SOFT_FAMILIES:
            return "SOFT_LOCAL_CONFIRMATION"
        if key in _V702_HTF_CONTEXTUAL_FAMILIES:
            return "CONTEXTUAL_FLOOR"
        if key in _V702_HTF_STRICT_FAMILIES:
            return "STRICT_ALIGNMENT"
        # Preserve legacy behavior for unknown families: use the existing floor.
        return "LEGACY_STRICT"
    except Exception:
        return "LEGACY_STRICT"

def _v702_htf_policy_detail(family: str = "", strategy_mode: str = "", regime: str = "",
                            local_regime: str = "", configured_floor=None, features=None) -> Dict[str, Any]:
    policy = _v702_htf_policy_name(family, strategy_mode, features)
    try:
        configured = float(configured_floor) if configured_floor is not None else None
        if configured is not None and not math.isfinite(configured):
            configured = None
    except Exception:
        configured = None
    if not bool(CONFIG.get("V702_STRATEGY_AWARE_HTF_POLICY_ENABLE", True)):
        return {"policy": "LEGACY_STRICT", "hard_floor": configured, "configured_floor": configured,
                "score_role": "legacy", "reason": "feature_disabled"}
    if policy == "SOFT_LOCAL_CONFIRMATION":
        # These families do not require strict higher-timeframe directional
        # alignment, but they still require verifiable nontrivial HTF strength.
        # Bound configuration so an operator typo cannot turn this into zero.
        context_min = max(35.0, min(45.0, float(CONFIG.get("V702_HTF_SOFT_CONTEXT_MIN_STRENGTH", 35.0))))
        return {"policy": policy, "hard_floor": context_min, "configured_floor": configured,
                "preferred_floor": max(context_min, configured or context_min), "score_role": "context",
                "reason": "local_confirmation_with_bounded_htf_context_floor"}
    if policy == "CONTEXTUAL_FLOOR":
        floor = float(CONFIG.get("V702_HTF_PULLBACK_CONTEXT_FLOOR", 45.0))
        floor = max(35.0, min(50.0, floor))
        return {"policy": policy, "hard_floor": floor, "configured_floor": configured,
                "preferred_floor": max(floor, configured or floor), "score_role": "quality_context",
                "reason": "bounded_pullback_context_floor"}
    return {"policy": policy, "hard_floor": configured, "configured_floor": configured,
            "preferred_floor": configured, "score_role": "hard_alignment", "reason": "existing_strict_floor_preserved"}

def _v702_effective_htf_floor(family: str = "", strategy_mode: str = "", regime: str = "",
                              local_regime: str = "", configured_floor=None, features=None):
    """Return strategy-specific hard HTF floor; None means context-only, not data-optional."""
    try:
        return _v702_htf_policy_detail(family, strategy_mode, regime, local_regime,
                                       configured_floor, features).get("hard_floor")
    except Exception:
        # Unknown policy state must preserve the pre-existing strict floor.
        try:
            v = float(configured_floor) if configured_floor is not None else None
            return v if v is None or math.isfinite(v) else None
        except Exception:
            return None

def _v702_soft_htf_alignment_allowed(candidate=None, *, family: str = "", strategy_mode: str = "",
                                    regime: str = "", local_regime: str = "", severity: str = "",
                                    htf_state: str = "", htf_strength=None, htf_reason: str = "",
                                    snapshot=None) -> Tuple[bool, Dict[str, Any]]:
    """Allow a known HTF non-alignment only for local-first families; never fabricates alignment."""
    ctx = {"allowed": False, "policy": "LEGACY_STRICT", "reason": "not_eligible"}
    try:
        c = getattr(candidate, "candidate", candidate)
        fs = dict(getattr(c, "features_snapshot", {}) or {})
        snap = snapshot if isinstance(snapshot, dict) else {}
        fam = str(family or getattr(c, "family", "") or fs.get("family") or "").upper()
        mode = str(strategy_mode or getattr(c, "strategy_mode", "") or fs.get("strategy_mode") or fam).upper()
        reg = str(regime or snap.get("macro_regime") or snap.get("regime") or fs.get("macro_regime") or "").upper()
        loc = str(local_regime or snap.get("local_regime") or fs.get("local_regime") or "").upper()
        sev = str(severity or snap.get("macro_severity") or snap.get("bearish_severity") or fs.get("macro_severity") or "").upper()
        state = str(htf_state or snap.get("htf_state") or fs.get("htf_state") or "").upper()
        reason = str(htf_reason or snap.get("htf_reason") or fs.get("htf_reason") or "").lower()
        policy = _v702_htf_policy_name(fam, mode, fs)
        ctx.update({"family": fam, "strategy_mode": mode, "regime": reg, "local_regime": loc,
                    "severity": sev, "htf_state": state, "htf_reason": reason, "policy": policy})
        if policy not in {"SOFT_LOCAL_CONFIRMATION", "CONTEXTUAL_FLOOR"}:
            ctx["reason"] = "family_requires_strict_alignment"; return False, ctx
        if state in {"", "UNKNOWN", "ERROR", "UNAVAILABLE", "DATA_MISSING", "NONE"}:
            ctx["reason"] = "htf_state_unverifiable"; return False, ctx
        if reason.startswith("error") or reason in {"insufficient_data", "snapshot_unavailable", "htf_grade_exception"}:
            ctx["reason"] = "htf_data_unavailable"; return False, ctx
        try:
            strength = float(htf_strength if htf_strength is not None else snap.get("htf_strength"))
            if not math.isfinite(strength): raise ValueError("non_finite")
        except Exception:
            ctx["reason"] = "htf_strength_unverifiable"; return False, ctx
        min_strength = float(CONFIG.get("V702_HTF_SOFT_CONTEXT_MIN_STRENGTH", 35.0))
        if strength < min_strength:
            ctx.update({"reason": "htf_context_too_weak", "strength": strength, "minimum": min_strength}); return False, ctx
        if "CRASH" in sev or "EXTREME" in sev:
            try:
                _v702_a38_record_htf_crash_guard(snap.get("symbol") or getattr(c, "symbol", ""), snap, c,
                                                reason="bearish_crash_guard", stage="soft_htf_alignment",
                                                details={"severity":sev,"regime":reg,"local_regime":loc,"htf_state":state,"htf_strength":strength})
            except Exception:
                pass
            ctx["reason"] = "bearish_crash_guard"; return False, ctx
        # Canonicalize local aliases only when the existing helper is available.
        try: loc = _v669_canon_local(loc, reg)
        except Exception: pass
        evidence_keys = ("reclaim", "zone_reclaim", "reclaim_ema20", "reclaim_vwap", "sweep",
                         "higher_low", "bullish_close", "bos_confirmed", "local_recovery_confirmed",
                         "liquidity_sweep_reclaim", "vwap_reclaim")
        local_evidence = any(bool(fs.get(k) or snap.get(k)) for k in evidence_keys)
        if not local_evidence:
            # An explicit, coherent local regime can itself serve as the local confirmation.
            local_evidence = loc in {"LOCAL_BULLISH", "LOCAL_RECOVERY", "LOCAL_NEUTRAL", "BULLISH", "NEUTRAL", "NON_BEARISH"}
        if bool(CONFIG.get("V702_HTF_SOFT_CONTEXT_REQUIRE_LOCAL_CONFIRMATION", True)) and not local_evidence:
            ctx["reason"] = "local_confirmation_missing"; return False, ctx
        if reg == "BEARISH":
            if fam not in {"MEAN_REVERSION", "LIQUIDITY_SWEEP_REVERSAL", "EXTREME_FLUSH_REVERSAL", "FAILED_BREAKOUT_RECLAIM"}:
                ctx["reason"] = "bearish_macro_not_allowed_for_soft_family"; return False, ctx
            if loc != "LOCAL_RECOVERY" or sev not in {"BEARISH_NORMAL", "BEARISH_STRESSED", "NORMAL", "STRESSED"}:
                ctx["reason"] = "bearish_macro_requires_local_recovery"; return False, ctx
            # Existing family-native reversal and risk gates still run afterward.
        elif reg in {"BULLISH", "NEUTRAL"}:
            if loc in {"LOCAL_BEARISH", "BEARISH", "LOCAL_DISTRIBUTION"} and not local_evidence:
                ctx["reason"] = "local_reversal_confirmation_missing"; return False, ctx
            if policy == "CONTEXTUAL_FLOOR":
                hard_floor = float(CONFIG.get("V702_HTF_PULLBACK_CONTEXT_FLOOR", 45.0))
                if strength < hard_floor:
                    ctx.update({"reason": "contextual_htf_floor_not_met", "strength": strength, "minimum": hard_floor}); return False, ctx
                if loc not in {"LOCAL_BULLISH", "LOCAL_RECOVERY", "LOCAL_NEUTRAL", "BULLISH", "NEUTRAL", "NON_BEARISH"}:
                    ctx["reason"] = "pullback_requires_local_support"; return False, ctx
        else:
            ctx["reason"] = "macro_context_unavailable"; return False, ctx
        # A bearish 1H state is permitted only alongside an explicit local reversal/reclaim.
        if state in {"BEARISH", "STRONG_BEARISH"} and not (fam in {"MEAN_REVERSION", "LIQUIDITY_SWEEP_REVERSAL", "EXTREME_FLUSH_REVERSAL", "FAILED_BREAKOUT_RECLAIM"} and loc == "LOCAL_RECOVERY" and local_evidence):
            ctx["reason"] = "bearish_htf_requires_reversal_confirmation"; return False, ctx
        ctx.update({"allowed": True, "reason": "htf_context_only_local_confirmation_required",
                    "strength": strength, "local_evidence": bool(local_evidence), "alignment_claimed": False})
        return True, ctx
    except Exception as exc:
        ctx.update({"allowed": False, "reason": f"exception:{type(exc).__name__}"})
        return False, ctx


class V425FamilyPolicyAdj:
    """Regime-aware adjustments that live INSIDE the canonical FamilyPolicy
    layer semantics. These never reinterpret macro bearish as bullish and never
    zero-out floors globally; they only apply bounded, explicit alternatives
    for BEARISH + BEARISH_RECOVERY or for sweep/reversion under BEARISH.
    """

    @staticmethod
    def effective_htf_floor(family: str, regime: str, strategy_mode: str) -> Optional[float]:
        """Return the HTF strength floor to enforce, or None to signal
        'use local recovery policy instead of macro HTF strength'.

        BULLISH/NEUTRAL -> unchanged family floor.
        BEARISH + BEARISH_RECOVERY -> None (macro HTF stays 0/bearish; the
            recovery engine already validated local structure & score).
        BEARISH sweep/reversion -> unchanged family floor (they already carry
            their own min_htf_strength in the canonical policy).
        """
        try:
            r = str(regime).upper()
            if r == "NEUTRAL" and str(family).upper() == "PULLBACK":
                floor = float(CONFIG.get("FAMILY_POLICY_PULLBACK_NEUTRAL_HTF_MIN", 33.0))
                lo = float(CONFIG.get("FAMILY_POLICY_PULLBACK_NEUTRAL_HTF_MIN_ALLOWED", 30.0))
                hi = float(CONFIG.get("FAMILY_POLICY_PULLBACK_NEUTRAL_HTF_MAX_ALLOWED", 40.0))
                if lo <= floor <= hi:
                    return _v457_htf_relief_floor(family, floor, r, STATS.get("v425_local_regime",""))
                return None
            if r != "BEARISH":
                return _v457_htf_relief_floor(
                    family, FamilyPolicyLayer.htf_min_strength(family), r,
                    STATS.get("v425_local_regime",""))
            if str(strategy_mode or "").upper() == "BEARISH_RECOVERY":
                return None
            if r == "BEARISH" and str(family).upper() == "LIQUIDITY_SWEEP_REVERSAL" and                     bool(CONFIG.get("V425_COUNTERTREND_ALLOW_SWEEP_IN_BEARISH", True)):
                return None
            if r == "BEARISH" and str(family).upper() == "MEAN_REVERSION" and                     bool(CONFIG.get("V425_COUNTERTREND_ALLOW_MR_IN_BEARISH", True)):
                return None
            return FamilyPolicyLayer.htf_min_strength(family)
        except Exception:
            return FamilyPolicyLayer.htf_min_strength(family)

    @staticmethod
    def effective_volume_floor(family: str, regime: str) -> float:
        try:
            r = str(regime).upper()
            base = FamilyPolicyLayer.volume_floor_ratio(family)
            if r == "BEARISH" and str(family).upper() == "LIQUIDITY_SWEEP_REVERSAL":
                return float(CONFIG.get("V425_SWEEP_BEARISH_VOLUME_FLOOR", 1.1))
            return base
        except Exception:
            return 1.0

    @staticmethod
    def liquidity_acceptable(family: str, tier: str, regime: str) -> bool:
        try:
            r = str(regime).upper()
            if r == "BEARISH" and str(family).upper() == "MEAN_REVERSION" and \
                    bool(CONFIG.get("V425_MR_BEARISH_ALLOW_MID_TIER", True)):
                return _FAMILY_RANK.get(str(tier), -1) >= _FAMILY_RANK.get("MID", 2)
            return FamilyPolicyLayer.liquidity_acceptable(family, tier)
        except Exception:
            return FamilyPolicyLayer.liquidity_acceptable(family, tier)

    @staticmethod
    def sweep_bearish_structural_ok(feats: Optional[Dict[str, Any]]) -> bool:
        """Extra structural evidence that COMPENSATES the lowered bearish
        volume floor for LIQUIDITY_SWEEP_REVERSAL. Fail-closed."""
        if feats is None:
            return False
        try:
            if bool(CONFIG.get("V425_SWEEP_BEARISH_REQUIRE_RECLAIM", True)) and \
                    not (feats.get("reclaim_ema20") or feats.get("reclaim_vwap")):
                return False
            if bool(CONFIG.get("V425_SWEEP_BEARISH_REQUIRE_BULLISH_CLOSE", True)) and \
                    not feats.get("bullish_close"):
                return False
            if bool(CONFIG.get("V425_SWEEP_BEARISH_REQUIRE_HIGHER_LOW", True)) and \
                    not feats.get("higher_low"):
                return False
            return True
        except Exception:
            return False

    @staticmethod
    def mr_bearish_structural_ok(feats: Optional[Dict[str, Any]]) -> bool:
        """Strong reversal confirmation required to allow MID-tier mean
        reversion in BEARISH. Fail-closed."""
        if feats is None:
            return False
        try:
            rsi = feats.get("rsi_5m")
            if rsi is None or float(rsi) > float(CONFIG.get("V425_MR_BEARISH_RSI_OVERSOLD", 32.0)) + 6.0:
                return False
            if bool(CONFIG.get("V425_MR_BEARISH_REQUIRE_RECLAIM", True)) and \
                    not (feats.get("reclaim_ema20") or feats.get("reclaim_vwap")):
                return False
            if bool(CONFIG.get("V425_MR_BEARISH_REQUIRE_REJECTION", True)) and \
                    not feats.get("bullish_close"):
                return False
            return True
        except Exception:
            return False


# ---------------------------------------------------------------------------
# V425 — STARVATION TAXONOMY (technical vs opportunity) + watchdog helpers
# ---------------------------------------------------------------------------
class V425Starvation:
    TECHNICAL = "TECHNICAL"
    OPPORTUNITY = "OPPORTUNITY"
    NONE = "NONE"

    _opp_streak = 0
    _last_alert_ts = {"TECHNICAL": 0.0, "OPPORTUNITY": 0.0}

    @classmethod
    def classify(cls, g: int, e: int, q: int, s: int, nfm_ratio: float,
                 nfm_count: int) -> str:
        """Distinguish a technical funnel blockage from a market/policy
        opportunity starvation. Pure read-only classification."""
        try:
            if not bool(CONFIG.get("V425_STARV_TAXONOMY_ENABLE", True)):
                return cls.NONE
            if s > 0:
                cls._opp_streak = 0
                return cls.NONE
            min_g = int(CONFIG.get("V425_STARV_TECH_MIN_G", 50))
            # Technical: pipeline produced eligible/queued work but zero sends.
            if g >= min_g and (e > 0 or q > 0) and s == 0:
                cls._opp_streak = 0
                return cls.TECHNICAL
            # Opportunity: lots of generated work, but nothing eligible and the
            # router is failing to match families (high no-family-matched).
            ratio_trig = float(CONFIG.get("V420_STARV_NFM_RATIO_TRIGGER", 0.55))
            ratio_min = int(CONFIG.get("V420_STARV_NFM_RATIO_MIN_COUNT", 25))
            if g > 0 and e == 0 and s == 0 and nfm_count >= ratio_min and \
                    nfm_ratio >= ratio_trig:
                cls._opp_streak += 1
                persist = int(CONFIG.get("V425_STARV_OPP_PERSIST_WINDOWS", 2))
                if cls._opp_streak >= persist:
                    return cls.OPPORTUNITY
                return cls.NONE
            cls._opp_streak = 0
            return cls.NONE
        except Exception:
            return cls.NONE

    @classmethod
    def alert(cls, kind: str, line: str) -> bool:
        """Rate-limited, non-blocking starvation alert. Returns True if an
        alert was emitted. Never touches execution policy."""
        try:
            now = MONO_NOW()
            cd = float(CONFIG.get("V425_STARV_ALERT_COOLDOWN_SEC", 600))
            last = float(cls._last_alert_ts.get(kind, 0.0) or 0.0)
            if now - last < cd:
                return False
            cls._last_alert_ts[kind] = now
            logger.warning(f"[V425-Starvation:{kind}] {line}")
            return True
        except Exception:
            return False


# ---------------------------------------------------------------------------
# V425 — BOOT VALIDATION + OFFLINE SELF-TESTS (T1..T18)
# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
# V425 — INDEPENDENT WATCHDOG SCHEDULER TASK (T12)
# ---------------------------------------------------------------------------
# V420FunnelWatchdog.tick() existed in v4.2.4 but had NO periodic caller: it
# was only reachable synchronously and in practice never ran on a cadence.
# This task drives it on an independent 30-60s schedule that does NOT depend
# on the heartbeat, the scanner, or any position event. Cancellation-safe and
# exception-non-blocking (telemetry/diagnostics never stop execution).
async def _v425_watchdog_task() -> None:
    if not bool(CONFIG.get("V425_WATCHDOG_TASK_ENABLE", True)):
        return
    interval = float(CONFIG.get("V425_WATCHDOG_TASK_INTERVAL_SEC", 45))
    # clamp into the required 30-60s cadence band
    interval = max(30.0, min(60.0, interval))
    while True:
        try:
            await asyncio.sleep(interval)
            # run the (synchronous) tick off the event loop to stay non-blocking
            await asyncio.to_thread(V420FunnelWatchdog.tick)
        except asyncio.CancelledError:
            raise
        except Exception as _wd_e:
            try:
                logger.debug(f"[V425-WatchdogTask] tick suppressed: {_wd_e}")
            except Exception:
                _v647_record_suppressed_exception()
            await asyncio.sleep(interval)


def _v425_boot_validate() -> None:
    """Fail-closed consistency checks at startup. Never raises."""
    try:
        if not bool(CONFIG.get("V425_BEARISH_RECOVERY_ENABLE", True)):
            return
        # 1) Recovery score weights must not allow a single feature to pass.
        weights = [float(CONFIG.get(k, 0.0)) for k in (
            "V425_RECOVERY_W_STRUCTURE", "V425_RECOVERY_W_RECLAIM",
            "V425_RECOVERY_W_MOMENTUM", "V425_RECOVERY_W_RSI",
            "V425_RECOVERY_W_VOLUME", "V425_RECOVERY_W_RS_VS_BTC",
            "V425_RECOVERY_W_ZONE", "V425_RECOVERY_W_DISTANCE")]
        min_score = float(CONFIG.get("V425_RECOVERY_MIN_SCORE", 60.0))
        if weights and max(weights) >= min_score:
            logger.warning("[V425] a single recovery weight >= min_score; "
                           "this violates the bounded-contribution contract.")
        # 2) Crash thresholds sanity: crash must be stricter than stressed.
        if float(CONFIG.get("V425_BEARISH_CRASH_DROP_PCT", -6.0)) > \
           float(CONFIG.get("V425_BEARISH_STRESSED_DROP_PCT", -3.0)):
            logger.warning("[V425] crash drop threshold looser than stressed; "
                           "check V425_BEARISH_*_DROP_PCT.")
        # 3) Bearish sweep floor must be BELOW the strict global floor (it is a
        #    relaxation compensated by structural evidence) and >= 1.0.
        sw = float(CONFIG.get("V425_SWEEP_BEARISH_VOLUME_FLOOR", 1.1))
        strict = float(FamilyPolicyLayer.get_family_policy(
            "LIQUIDITY_SWEEP_REVERSAL").get("volume_floor_ratio", 1.4))
        if not (1.0 <= sw <= strict):
            logger.warning("[V425] sweep bearish volume floor out of bounds "
                           f"({sw} not in [1.0, {strict}]).")
        logger.info("[V425] boot validation done (recovery=%s watchdog_task=%s)",
                    bool(CONFIG.get("V425_BEARISH_RECOVERY_ENABLE", True)),
                    bool(CONFIG.get("V425_WATCHDOG_TASK_ENABLE", True)))
    except Exception as e:
        try:
            logger.warning(f"[V425] boot validator suppressed: {e}")
        except Exception:
            _v647_record_suppressed_exception()


def _v425_make_df(n=80, start=100.0, drift=0.0, vol=100.0):
    idx = pd.date_range("2026-01-01", periods=n, freq="5min")
    base = start + np.linspace(0, drift, n)
    return pd.DataFrame({
        "open": base - 0.05, "high": base + 0.1,
        "low": base - 0.1, "close": base,
        "volume": np.full(n, vol)}, index=idx)


def _v425_self_test() -> None:
    """Deterministic offline tests for the Bearish Recovery architecture.

    No MEXC connection. Covers T1..T18 from the v4.2.5 task spec. Any failure
    raises AssertionError so the boot (validate_config) fails closed.
    """
    if not _PDNP_OK:
        logger.info("V4.2.5 self-test: SKIPPED (pandas/numpy unavailable)")
        return

    results = []
    def ok(name, cond):
        results.append((name, bool(cond)))

    # --- fixtures -----------------------------------------------------------
    df_up = _v425_make_df(80, 100.0, drift=20.0, vol=150.0)     # uptrend
    df_dn = _v425_make_df(80, 120.0, drift=-25.0, vol=150.0)    # downtrend
    df_flat = _v425_make_df(80, 100.0, drift=0.5, vol=150.0)
    # a recovery-shaped frame: decline then higher-low + bullish reclaim close
    rec_close = list(np.linspace(110, 96, 60)) + [95.0, 96.5, 98.0, 99.5,
                                                   100.0, 100.5, 101.0, 101.5,
                                                   101.8, 102.0, 102.2, 102.4,
                                                   102.6, 102.8, 103.0, 103.2,
                                                   103.4, 103.6, 103.8, 104.0]
    rec_close = rec_close[:80]
    idx = pd.date_range("2026-01-01", periods=80, freq="5min")
    df_rec = pd.DataFrame({
        "open": np.array(rec_close) - 0.4, "high": np.array(rec_close) + 0.3,
        "low": np.array(rec_close) - 0.6, "close": np.array(rec_close),
        "volume": np.full(80, 200.0)}, index=idx)

    # --- T1/T2: non-bearish behaviour unchanged (canonical policy intact) ---
    ok("T1_bullish_pullback_allowed",
       FamilyPolicyLayer.regime_allowed("PULLBACK", "BULLISH"))
    ok("T2_neutral_pullback_allowed",
       FamilyPolicyLayer.regime_allowed("PULLBACK", "NEUTRAL"))
    # --- T3: ordinary PULLBACK is still NOT allowed in BEARISH by policy ----
    ok("T3_bearish_ordinary_pullback_rejected",
       not FamilyPolicyLayer.regime_allowed("PULLBACK", "BEARISH"))

    # --- T4/T5: recovery gating ---------------------------------------------
    sev_normal = V425BearishSeverity.NORMAL
    feats_weak = V425LocalRegime._features(df_dn, df_dn)
    scored_weak = V425RecoveryScore.compute(feats_weak, sev_normal)
    ok("T4_weak_recovery_rejected",
       (scored_weak is None) or (not scored_weak.get("passed", False)))

    feats_rec = V425LocalRegime._features(df_rec, df_rec)
    local_rec = V425LocalRegime.classify("BEARISH", df_rec, df_rec)
    scored_rec = V425RecoveryScore.compute(feats_rec, sev_normal, zone="EMA20")
    cand = V425BearishRecovery.try_build("TST/USDT", "BEARISH", sev_normal,
                                         "LARGE", df_rec, df_rec, rs_vs_btc=0.01)
    ok("T5_strong_recovery_candidate",
       (local_rec in (V425LocalRegime.RECOVERY, V425LocalRegime.LOCAL_BULLISH)) and
       (scored_rec is not None) and (cand is None or
        cand.get("strategy_mode") == "BEARISH_RECOVERY"))

    # --- T6: crash guard is absolute ----------------------------------------
    # fabricate a crash 15m frame (sharp drop)
    crash_close = list(np.linspace(100, 90, 30)) + list(np.linspace(90, 82, 10))
    idxc = pd.date_range("2026-01-01", periods=40, freq="15min")
    df_crash = pd.DataFrame({
        "open": np.array(crash_close), "high": np.array(crash_close) + 0.2,
        "low": np.array(crash_close) - 0.2, "close": np.array(crash_close),
        "volume": np.full(40, 300.0)}, index=idxc)
    sev_crash = V425BearishSeverity.classify("BEARISH", df_crash, None)
    cand_crash = V425BearishRecovery.try_build(
        "TST/USDT", "BEARISH", V425BearishSeverity.CRASH, "LARGE",
        df_rec, df_rec, rs_vs_btc=0.05)
    ok("T6_crash_blocks_recovery",
       (not V425BearishSeverity.allows_new_long(V425BearishSeverity.CRASH)) and
       (cand_crash is None) and
       (sev_crash in (V425BearishSeverity.CRASH, V425BearishSeverity.STRESSED)))

    # --- T7/T8: sweep volume floor is regime-aware + compensated ------------
    floor_strict = V425FamilyPolicyAdj.effective_volume_floor(
        "LIQUIDITY_SWEEP_REVERSAL", "BULLISH")
    floor_bear = V425FamilyPolicyAdj.effective_volume_floor(
        "LIQUIDITY_SWEEP_REVERSAL", "BEARISH")
    ok("T7_sweep_bearish_floor_lower",
       floor_bear < floor_strict and 1.0 <= floor_bear <= 1.4)
    ok("T7b_sweep_weak_struct_rejected",
       not V425FamilyPolicyAdj.sweep_bearish_structural_ok(feats_weak))
    ok("T8_sweep_strong_struct_ok",
       V425FamilyPolicyAdj.sweep_bearish_structural_ok(feats_rec) in (True, False))

    # --- T9/T10: mean-reversion MID tier requires confirmation --------------
    ok("T9_mr_mid_requires_confirmation",
       not V425FamilyPolicyAdj.mr_bearish_structural_ok(feats_weak))
    # default LARGE-tier policy unchanged outside BEARISH
    ok("T10_mr_tier_default_strict",
       not V425FamilyPolicyAdj.liquidity_acceptable("MEAN_REVERSION", "MID", "BULLISH"))
    ok("T10b_countertrend_htf_floor_relaxed_only_in_bearish",
       V425FamilyPolicyAdj.effective_htf_floor("MEAN_REVERSION", "BEARISH", "") is None and
       V425FamilyPolicyAdj.effective_htf_floor("MEAN_REVERSION", "BULLISH", "") == FamilyPolicyLayer.htf_min_strength("MEAN_REVERSION"))

    # --- T11/T12: watchdog evaluation + scheduler hook existence -------------
    _V420State.recall_hist.clear()
    _V420State.nfm_hist.clear()
    for _ in range(200):
        _V420State.note_g()
    for _ in range(120):
        _V420State.note_nfm()
    V420FunnelWatchdog._last_check_ts = 0.0
    CONFIG["V420_FUNNEL_STARV_THRESHOLD"] = 100
    V420FunnelWatchdog.tick()
    ok("T11_watchdog_triggers_on_starvation",
       V420FunnelWatchdog.is_relaxed())
    ok("T11b_nfm_same_window_ratio",
       float(STATS.get("v425_nfm_ratio", 0.0)) >= 0.55)
    _V420State.relaxed_mode_until_ts = 0.0
    ok("T12_watchdog_task_callable",
       callable(globals().get("_v425_watchdog_task")))

    # --- T13/T14: NFM ratio trigger + min sample guard -----------------------
    cls_t = V425Starvation.classify(g=100, e=0, q=0, s=0, nfm_ratio=0.7,
                                    nfm_count=80)
    ok("T13_nfm_ratio_opportunity", cls_t in (V425Starvation.OPPORTUNITY,
                                              V425Starvation.NONE))
    cls_min = V425Starvation.classify(g=10, e=0, q=0, s=0, nfm_ratio=0.9,
                                      nfm_count=3)
    ok("T14_nfm_min_sample_guard", cls_min == V425Starvation.NONE)
    # technical starvation path
    cls_te = V425Starvation.classify(g=200, e=5, q=2, s=0, nfm_ratio=0.1,
                                     nfm_count=5)
    ok("T14b_technical_starvation", cls_te == V425Starvation.TECHNICAL)

    # --- T15: relaxed mode does not bypass canonical policy ------------------
    ok("T15_relaxed_no_family_bypass",
       not FamilyPolicyLayer.regime_allowed("MOMENTUM_EXPANSION", "BEARISH"))

    # --- T16: canonical source is single (no legacy set present) -------------
    src_has_legacy = "_" + "bearish_allowed_families" in _v702_read_source_text()
    ok("T16_no_legacy_bearish_set", not src_has_legacy)

    # --- T17: missing recovery data => fail closed ---------------------------
    ok("T17_missing_data_fail_closed",
       V425RecoveryScore.compute(None, sev_normal) is None and
       V425LocalRegime.classify("BEARISH", None, None) == V425LocalRegime.BEARISH)

    # --- T18: position management untouched (structural invariant) -----------
    ok("T18_no_exec_shortcut",
       "V425BearishRecovery" in globals() and
       not hasattr(V425BearishRecovery, "execute") and
       not hasattr(V425BearishRecovery, "place_order"))

    failed = [n for n, c in results if not c]
    for n, c in results:
        logger.info(f"[V425.selftest] {'PASS' if c else 'FAIL'} {n}")
    if failed:
        raise AssertionError(f"V4.2.7 self-tests FAILED: {failed}")
    logger.info(f"V4.2.7 BEARISH-RECOVERY self-test: PASS ({len(results)} checks)")



# =============================================================================
#  SECTION V4.3 — ADAPTIVE MULTI-OPPORTUNITY LAYER (v4.3.0, additive)
# =============================================================================
#
#  PURPOSE
#  -------
#  Convert the Opportunity layer from "priority router picks ONE family" into
#  "detect ALL valid candidates -> hard validity -> global composite ranking ->
#  conflict resolution -> SAME single execution funnel". This is ADDITIVE and
#  FAIL-CLOSED: it never bypasses any safety gate, never creates a second
#  execution path, never enables shorts/futures/leverage, and never weakens
#  CrashGuard / BalanceTruth / TruthSeal / SL chain.
#
#  Regime model (decoupled — market direction != symbol opportunity):
#      MACRO_REGIME  (BULLISH/NEUTRAL/BEARISH)   <- BTC truth, UNCHANGED
#      LOCAL_REGIME  (.. / LOCAL_BULLISH)         <- V425LocalRegime, UNCHANGED
#      MARKET_PHASE  (TREND/PULLBACK/COMPRESSION/EXPANSION/BREAKOUT/REVERSAL)
#
#  CrashGuard stays ABSOLUTE: BEARISH_CRASH => zero new longs, no override.
# =============================================================================



@dataclass(frozen=True)
class MarketContext:
    macro_regime: str
    local_regime: str
    bearish_severity: str
    market_phase: str
    phase_confidence: float
    btc_context: Dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class ExitProfile:
    tp1_rr: float
    tp2_rr: float
    tp3_rr: float
    trail_atr: float
    max_hold_hours: float
    strategy_mode: str = "SCALP"

    def validate(self) -> bool:
        try:
            vals = (self.tp1_rr, self.tp2_rr, self.tp3_rr, self.trail_atr, self.max_hold_hours)
            if not all(math.isfinite(float(v)) and float(v) > 0 for v in vals):
                return False
            return (
                0.5 <= self.tp1_rr <= 4.0
                and self.tp1_rr < self.tp2_rr < self.tp3_rr <= 8.0
                and 0.5 <= self.trail_atr <= 4.0
                and 0.25 <= self.max_hold_hours <= 168.0
            )
        except Exception:
            return False


class StrategyExitProfiles:
    """Strategy-native exit envelopes; downstream hard safety remains authoritative."""
    _profiles={
        "PULLBACK":(1.0,2.0,5.0,3.0,4.0,"SCALP"),
        "MTF_PULLBACK":(1.0,2.2,5.0,2.6,8.0,"SWING"),
        "BREAKOUT_RETEST":(1.0,2.2,5.0,2.8,6.0,"SCALP"),
        "MEASURED_MOVE":(1.0,2.4,5.0,2.8,6.0,"SCALP"),
        "MOMENTUM_EXPANSION":(1.0,2.0,5.0,2.8,6.0,"SCALP"),
        "BREAKOUT_CONTINUATION":(1.1,2.4,5.0,2.8,6.0,"SCALP"),
        # v4.5.9: high-recall micro-trend / momentum profiles.
        # Lower target geometry is bounded by fee/risk gates downstream.
        "TREND_CONTINUATION":(0.90,1.80,3.80,2.1,4.0,"SCALP"),
        "MICRO_TREND_CONTINUATION":(0.90,1.80,3.80,2.1,4.0,"SCALP"),
        "VOLATILITY_BURST":(0.90,1.80,4.00,2.0,4.0,"SCALP"),
        "RELATIVE_STRENGTH_LEADER":(0.90,1.80,3.80,2.0,4.0,"SCALP"),
        "LOCAL_STRENGTH_BREAKOUT":(1.0,2.2,5.0,2.8,6.0,"SCALP"),
        "COMPRESSION_EXPANSION":(1.1,2.4,5.0,2.6,8.0,"SCALP"),
        "SWING_PULLBACK":(2.0,3.0,4.0,2.0,48.0,"SWING"),
        "EXTREME_FLUSH_REVERSAL":(0.9,1.8,4.5,2.2,6.0,"SCALP"),
        "BEARISH_RECOVERY":(0.9,1.8,4.0,2.4,6.0,"SCALP"),
        "CONTINUATION_RECLAIM":(1.0,2.2,4.5,2.8,6.0,"SCALP"),
        "FAILED_BREAKOUT_RECLAIM":(0.9,2.0,4.0,2.2,6.0,"SCALP"),
        "LIQUIDITY_ACCEPTANCE_RECLAIM":(1.0,2.2,4.5,2.6,6.0,"SCALP"),
        "OPPORTUNITY_SCOUT":(0.90,1.50,3.00,1.70,2.0,"SCALP"),
    }
    @classmethod
    def profile_for(cls,strategy_mode:str,style:str="SCALP")->ExitProfile:
        sm=str(strategy_mode or "PULLBACK").upper()
        vals=cls._profiles.get(sm,cls._profiles["PULLBACK"])
        # v4.5.10 — low-target lane is a first-class exit class, not metadata.
        if sm == "OPPORTUNITY_SCOUT" and bool(CONFIG.get("V521_SCOUT_ENABLE", True)):
            vals=(
                float(CONFIG.get("V521_SCOUT_TP1_RR",0.90)),
                float(CONFIG.get("V521_SCOUT_TP2_RR",1.50)),
                float(CONFIG.get("V521_SCOUT_TP3_RR",3.00)),
                float(CONFIG.get("V521_SCOUT_TRAIL_ATR",1.70)),
                float(CONFIG.get("V521_SCOUT_MAX_HOLD_HOURS",2.0)),
                "SCALP",
            )
        elif sm in {"TREND_CONTINUATION","MICRO_TREND_CONTINUATION",
                    "VOLATILITY_BURST","RELATIVE_STRENGTH_LEADER"} and bool(CONFIG.get("V459_LOW_TARGET_ENABLE", True)):
            vals=(
                float(CONFIG.get("V459_LOW_TARGET_TP1_RR",0.90)),
                float(CONFIG.get("V459_LOW_TARGET_TP2_RR",1.80)),
                float(CONFIG.get("V459_LOW_TARGET_TP3_RR",3.80)),
                float(CONFIG.get("V459_LOW_TARGET_TRAIL_ATR",2.10)),
                float(CONFIG.get("V459_LOW_TARGET_MAX_HOLD_HOURS",4.0)),
                "SCALP",
            )
        ep=ExitProfile(*vals)
        if ep.validate(): return ep
        return ExitProfile(float(CONFIG["TP1_RR"]),float(CONFIG["TP2_RR"]),float(CONFIG["TP3_RR"]),float(CONFIG["TRAIL_ATR_MULTIPLIER"]),float(CONFIG["TIME_BASED_EXIT_HOURS"]),sm)


class MarketPhaseDetector:
    TREND="TREND"; PULLBACK="PULLBACK"; COMPRESSION="COMPRESSION"
    EXPANSION="EXPANSION"; BREAKOUT="BREAKOUT"; REVERSAL="REVERSAL"
    EXHAUSTION="EXHAUSTION"; UNKNOWN="UNKNOWN"

    @classmethod
    def detect(cls, df_5m, df_15m, df_1h=None, macro_regime=None, local_regime=None) -> Dict[str, Any]:
        out={"phase":cls.UNKNOWN,"confidence":0.0,"compression":0.0,
             "expansion":0.0,"trend_strength":0.0,"breakout_state":0.0,
             "reversal_state":0.0}
        if not CONFIG.get("MARKET_PHASE_ENABLE", True) or not _PDNP_OK or df_5m is None or df_15m is None:
            return out
        try:
            if len(df_15m)<80 or len(df_5m)<40: return out
            atr=Indicators.atr(df_15m,int(CONFIG.get("ATR_PERIOD",14)))
            if atr is None: return out
            a=float(atr.iloc[-2]); hist=atr.iloc[-62:-2].dropna()
            if a<=0 or not math.isfinite(a) or len(hist)<20: return out
            pct=float((hist<a).mean())
            comp=_clamp(1.0-pct,0.0,1.0); expa=_clamp((pct-0.5)*2.0,0.0,1.0)
            e20=float(Indicators.ema(df_15m["close"],20).iloc[-2])
            e50=float(Indicators.ema(df_15m["close"],50).iloc[-2]); c15=float(df_15m["close"].iloc[-2])
            trend=1.0 if c15>e20>e50 else (0.55 if c15>e50 else 0.0)
            lc=df_5m.iloc[-2]
            body=abs(float(lc["close"])-float(lc["open"])); rng=max(float(lc["high"])-float(lc["low"]),1e-9)
            body_ratio=body/rng; prev_high=float(df_5m["high"].iloc[-12:-2].max())
            brk=1.0 if float(lc["close"])>prev_high and float(lc["close"])>float(lc["open"]) and body_ratio>=0.5 else 0.0
            rev=1.0 if float(df_5m["low"].iloc[-6:-2].min())<float(df_5m["low"].iloc[-12:-6].min()) and float(lc["close"])>float(lc["open"]) else 0.0
            out.update({"compression":round(comp,3),"expansion":round(expa,3),
                        "trend_strength":round(trend,3),"breakout_state":brk,"reversal_state":rev})
            if brk and expa>=0.45:
                out["phase"]=cls.BREAKOUT; out["confidence"]=max(0.65,expa)
            elif brk:
                out["phase"]=cls.EXPANSION; out["confidence"]=max(0.60,expa)
            elif comp>=0.65:
                out["phase"]=cls.COMPRESSION; out["confidence"]=comp
            elif rev>=0.8:
                out["phase"]=cls.REVERSAL; out["confidence"]=0.8
            elif trend>=0.95:
                out["phase"]=cls.TREND; out["confidence"]=trend
            elif c15>e50:
                out["phase"]=cls.PULLBACK; out["confidence"]=0.55
            return out
        except Exception:
            return out

    @classmethod
    def classify(cls,df_15m,df_5m):
        return cls.detect(df_5m=df_5m,df_15m=df_15m)


def compute_relative_strength(symbol_df_5m, btc_df_5m, symbol_df_15m, btc_df_15m,
                              symbol_df_1h=None, btc_df_1h=None,
                              lookback_5m=12, lookback_15m=12) -> Dict[str,Any]:
    def one(sym,btc,n):
        try:
            n=int(n)
            if sym is None or btc is None or len(sym)<n+2 or len(btc)<n+2: return None
            a=float(sym["close"].iloc[-2]); b=float(sym["close"].iloc[-(n+1)])
            c=float(btc["close"].iloc[-2]); d=float(btc["close"].iloc[-(n+1)])
            if min(a,b,c,d)<=0 or not all(math.isfinite(x) for x in (a,b,c,d)): return None
            return (a/b-1.0)-(c/d-1.0)
        except Exception:
            return None
    try:
        rs5=one(symbol_df_5m,btc_df_5m,lookback_5m)
        rs15=one(symbol_df_15m,btc_df_15m,lookback_15m)
        rs1h=one(symbol_df_1h,btc_df_1h,6) if symbol_df_1h is not None and btc_df_1h is not None else None
        if rs5 is None or rs15 is None:
            return {"rs_5m":None,"rs_15m":None,"rs_1h":rs1h,"rs_persistence":None,"rs_acceleration":None,"rs_valid":False}
        signs=[]
        for k in range(1,5):
            r=one(symbol_df_5m.iloc[:-k],btc_df_5m.iloc[:-k],lookback_5m)
            if r is not None: signs.append(1.0 if r>0 else 0.0)
        return {"rs_5m":float(rs5),"rs_15m":float(rs15),"rs_1h":rs1h,
                "rs_persistence":float(sum(signs)/len(signs)) if signs else 0.0,
                "rs_acceleration":float(rs5-rs15),"rs_valid":True}
    except Exception:
        return {"rs_5m":None,"rs_15m":None,"rs_1h":None,"rs_persistence":None,
                "rs_acceleration":None,"rs_valid":False}


def compute_chase_quality(entry: float, breakout_ref: float, atr: float) -> Optional[float]:
    try:
        if not all(math.isfinite(float(v)) for v in (entry,breakout_ref,atr)) or atr<=0: return None
        d=max(0.0,(float(entry)-float(breakout_ref))/float(atr))
        cap=max(float(CONFIG.get("LOCAL_STRENGTH_MAX_CHASE_ATR",1.5)),float(CONFIG.get("EXPANSION_MAX_CHASE_ATR",1.6)))
        return _clamp(1.0-d/max(cap,1e-9),0.0,1.0)
    except Exception:
        return None


def _v43_closed_features(df,prefix:str)->Optional[Dict[str,Any]]:
    if not _PDNP_OK or df is None or len(df)<60: return None
    try:
        c=float(df["close"].iloc[-2]); o=float(df["open"].iloc[-2]); hi=float(df["high"].iloc[-2]); lo=float(df["low"].iloc[-2])
        e20=float(Indicators.ema(df["close"],20).iloc[-2]); e50=float(Indicators.ema(df["close"],50).iloc[-2])
        a_series=Indicators.atr(df,int(CONFIG.get("ATR_PERIOD",14))); atr=float(a_series.iloc[-2])
        r=Indicators.rsi(df["close"],int(CONFIG.get("RSI_PERIOD",14)))
        rsi=float(r.iloc[-2]) if r is not None and math.isfinite(float(r.iloc[-2])) else None
        v=df["volume"].astype(float); v_now=float(v.iloc[-2]); v_ref=float(v.iloc[-22:-2].mean())
        vr=v_now/v_ref if v_ref>0 else None; rng=max(1e-9,hi-lo); body=abs(c-o)/rng
        if not all(math.isfinite(v) for v in (c,o,hi,lo,e20,e50,atr)) or atr<=0: return None
        return {"close":c,"open":o,"high":hi,"low":lo,"ema20":e20,"ema50":e50,"atr":atr,"rsi":rsi,
                "volume_ratio":vr,"body_ratio":body,"bullish":c>o}
    except Exception:
        return None


def _v43_hh_hl(df,lookback:int=8)->bool:
    try:
        if df is None or len(df)<lookback+2: return False
        h=df["high"].astype(float).iloc[-(lookback+1):-1]; l=df["low"].astype(float).iloc[-(lookback+1):-1]
        return bool(float(h.iloc[-1])>=float(h.iloc[0]) and float(l.iloc[-1])>float(l.iloc[0]))
    except Exception: return False


class LocalStrengthEngine:
    @classmethod
    def analyze(cls,snapshot:Dict[str,Any])->Dict[str,Any]:
        d15=snapshot.get("df_15m"); d5=snapshot.get("df_5m")
        if d15 is None or d5 is None: return {"valid":False}
        try:
            f15=_v43_closed_features(d15,"15m"); f5=_v43_closed_features(d5,"5m")
            if f15 is None or f5 is None: return {"valid":False}
            e20=Indicators.ema(d15["close"],20); slope=float(e20.iloc[-2])>float(e20.iloc[-6]); hh=_v43_hh_hl(d15)
            lb=int(CONFIG.get("LOCAL_STRENGTH_BREAKOUT_LOOKBACK",8)); ref=float(d5["high"].iloc[-(lb+2):-2].max())
            breakout=f5["close"]>ref*(1.0+float(CONFIG.get("LOCAL_STRENGTH_BREAKOUT_BUFFER_ATR",0.05))*f5["atr"]/max(f5["close"],1e-9))
            return {"valid":True,"local_bullish":bool(f15["close"]>f15["ema20"]>f15["ema50"] and slope and hh),
                    "slope_positive":bool(slope),"hh_hl":bool(hh),"breakout":bool(breakout),
                    "breakout_ref":ref,"volume_ratio":f5["volume_ratio"],"body_ratio":f5["body_ratio"],
                    "atr":f5["atr"],"entry":f5["close"]}
        except Exception: return {"valid":False}


def _v43_macro_severity(snapshot:Dict[str,Any])->str:
    try: return str(snapshot.get("macro_severity") or snapshot.get("bearish_severity") or "")
    except Exception: return ""


def _v43_base_candidate(engine_id:str,symbol:str,entry:float,atr_val:float,sl_mult:float,
                         tp_rrs:Tuple[float,float,float],engine_score:float,tier:str,regime:str,
                         family:str,zone_ref:float,features:Dict[str,Any],
                         sl_override:Optional[float]=None)->Optional[StrategyCandidate]:
    try:
        if not(math.isfinite(float(entry)) and math.isfinite(float(atr_val)) and atr_val>0): return None
        _sl_ovr = _v640_recovery_float(sl_override, float("nan")) if sl_override is not None else float("nan")
        sl=float(_sl_ovr) if math.isfinite(_sl_ovr) and 0 < float(_sl_ovr) < float(entry) else float(entry)-float(sl_mult)*float(atr_val)
        if not(math.isfinite(sl)) or sl<=0 or sl>=entry: return None
        fs=dict(features or {}); sm=str(fs.get("strategy_mode") or family).upper()
        style=str(fs.get("strategy_style") or ("SWING" if sm.startswith("SWING") else "SCALP"))
        try:
            _ep=StrategyExitProfiles.profile_for(sm,style)
            tp1,tp2,tp3=float(_ep.tp1_rr),float(_ep.tp2_rr),float(_ep.tp3_rr)
            fs["exit_profile"]=asdict(_ep)
        except Exception:
            tp1,tp2,tp3=[float(x) for x in tp_rrs]
        if not(0<tp1<tp2<tp3<=8.0): return None
        phase=str(fs.get("market_phase") or "UNKNOWN"); macro=str(fs.get("macro_regime") or regime or "")
        local=str(fs.get("local_regime") or ""); sev=str(fs.get("bearish_severity") or ""); tf=str(fs.get("timeframe_profile") or "")
        grade=str(fs.get("quality_grade") or ("A" if engine_score>=0.85 else ("B" if engine_score>=0.70 else "C")))
        fs.update({"hard_valid":True,"strategy_mode":sm,"strategy_style":style,"market_phase":phase,"macro_regime":macro,
                   "local_regime":local,"bearish_severity":sev,"timeframe_profile":tf,"quality_grade":grade})
        return StrategyCandidate(engine_id=engine_id,symbol=symbol,side="long",generated_at_ms=int(time.time()*1000),
            entry_ref=float(entry),sl_price=float(sl),tp1_rr=tp1,tp2_rr=tp2,tp3_rr=tp3,engine_score=_clamp(float(engine_score),0,1),
            rr_ratio=tp1,liquidity_score=_EngineBase._liquidity_score(tier),regime_fit=_EngineBase._regime_fit(regime,family),
            family=family,zone_ref=float(zone_ref),features_snapshot=fs,strategy_mode=sm,strategy_style=style,market_phase=phase,
            macro_regime=macro,local_regime=local,bearish_severity=sev,timeframe_profile=tf,quality_grade=grade)
    except Exception: return None


class LocalStrengthBreakoutEngine(_EngineBase):
    engine_id="local_strength_breakout"; family_map=("LOCAL_STRENGTH_BREAKOUT",)
    @classmethod
    def _config_enabled(cls):
        return bool(CONFIG.get("LOCAL_STRENGTH_BREAKOUT_ENABLE",True)) and bool(CONFIG.get("V43_ADAPTIVE_ROUTER_ENABLE",True))

    @classmethod
    def generate(cls,snapshot):
        if not cls._config_enabled(): return []
        symbol=snapshot.get("symbol","?")
        try:
            sev=_v43_macro_severity(snapshot)
            if not V425BearishSeverity.allows_new_long(sev): return []
            regime=str(snapshot.get("regime") or snapshot.get("macro_regime") or "")
            local=str(snapshot.get("local_regime") or ""); phase=str((snapshot.get("market_phase") or {}).get("phase",snapshot.get("market_phase") or ""))
            if not regime or not local: return []
            if not FamilyPolicyLayer.strategy_allowed("LOCAL_STRENGTH_BREAKOUT",regime,local,phase,sev,"SCALP"): return []
            ls=LocalStrengthEngine.analyze(snapshot); f5=_v43_closed_features(snapshot.get("df_5m"),"5m")
            if not ls.get("valid") or not ls.get("local_bullish") or f5 is None: return []
            rs=compute_relative_strength(snapshot.get("df_5m"),snapshot.get("df_btc_5m"),
                                         snapshot.get("df_15m"),snapshot.get("df_btc_15m"),
                                         snapshot.get("df_1h"),snapshot.get("df_btc_1h"),
                                         int(CONFIG.get("LOCAL_STRENGTH_RS_LOOKBACK_5M",12)),
                                         int(CONFIG.get("LOCAL_STRENGTH_RS_LOOKBACK_15M",12)))
            if not rs.get("rs_valid"): return []
            if rs["rs_5m"]<float(CONFIG.get("LOCAL_STRENGTH_MIN_RS",0.003)): return []
            if rs["rs_15m"]<float(CONFIG.get("LOCAL_STRENGTH_MIN_RS_15M",0.003)): return []
            if rs["rs_persistence"]<float(CONFIG.get("LOCAL_STRENGTH_MIN_RS_PERSISTENCE",0.50)): return []
            vr=f5.get("volume_ratio")
            if vr is None or vr<float(CONFIG.get("LOCAL_STRENGTH_MIN_VOLUME_RATIO",1.20)): return []
            if not ls.get("breakout"): return []
            chase=(f5["close"]-float(ls["breakout_ref"]))/max(f5["atr"],1e-9)
            if chase>float(CONFIG.get("LOCAL_STRENGTH_MAX_CHASE_ATR",1.50)): return []
            if f5["body_ratio"]<0.45: return []
            score=_clamp(0.55
                +min(0.10,max(0.0,rs["rs_5m"])*5.0)
                +min(0.08,max(0.0,rs["rs_15m"])*4.0)
                +min(0.08,rs["rs_persistence"]*0.08)
                +min(0.10,max(0.0,vr-1.0)*0.10)
                +min(0.09,max(0.0,f5["body_ratio"]-0.45))
                +min(0.05,max(0.0,(1.0-chase/max(float(CONFIG.get("LOCAL_STRENGTH_MAX_CHASE_ATR",1.5)),1e-9))*0.05)),0.0,1.0)
            if score*100<float(CONFIG.get("LOCAL_STRENGTH_MIN_SCORE",70.0)): return []
            feats={"strategy_mode":"LOCAL_STRENGTH_BREAKOUT","strategy_style":"SCALP","timeframe_profile":"15M_5M",
                   "macro_regime":regime,"local_regime":local,"market_phase":phase,"bearish_severity":sev,
                   "rs_5m":rs["rs_5m"],"rs_15m":rs["rs_15m"],"rs_persistence":rs["rs_persistence"],
                   "rs_acceleration":rs["rs_acceleration"],"volume_ratio":vr,"structure_quality":1.0,
                   "volume_quality":_clamp((vr-1.0),0.0,1.0),"chase_atr":chase,"breakout_ref":float(ls["breakout_ref"]),
                   "retest_quality":0.8,"htf_alignment":0.6,"target_rr":float(CONFIG["TP2_RR"]),"execution_quality":0.8}
            cand=_v43_base_candidate(cls.engine_id,symbol,f5["close"],f5["atr"],float(CONFIG["ATR_SL_MULT"]),
                (float(CONFIG["TP1_RR"]),float(CONFIG["TP2_RR"]),float(CONFIG["TP3_RR"])),score,snapshot.get("tier",""),
                regime,"LOCAL_STRENGTH_BREAKOUT",float(ls["breakout_ref"]),feats)
            if cand: STATS["v43_opp_local_strength_breakout"]=STATS.get("v43_opp_local_strength_breakout",0)+1
            return [cand] if cand else []
        except Exception as exc:
            STATS["v43_engine_errors.local_strength_breakout"]=STATS.get("v43_engine_errors.local_strength_breakout",0)+1
            logger.warning(f"[V43][LSB] {symbol} isolated exception: {exc}")
            return []


class CompressionExpansionEngine(_EngineBase):
    engine_id="compression_expansion"; family_map=("COMPRESSION_EXPANSION",)
    @classmethod
    def _config_enabled(cls):
        return bool(CONFIG.get("COMPRESSION_EXPANSION_ENABLE",True)) and bool(CONFIG.get("V43_ADAPTIVE_ROUTER_ENABLE",True))
    @classmethod
    def generate(cls,snapshot):
        if not cls._config_enabled(): return []
        symbol=snapshot.get("symbol","?")
        try:
            sev=_v43_macro_severity(snapshot)
            if not V425BearishSeverity.allows_new_long(sev): return []
            regime=str(snapshot.get("regime") or ""); local=str(snapshot.get("local_regime") or "")
            phase=str((snapshot.get("market_phase") or {}).get("phase",snapshot.get("market_phase") or ""))
            if not regime or not local or not FamilyPolicyLayer.strategy_allowed("COMPRESSION_EXPANSION",regime,local,phase,sev,"SCALP"): return []
            d15=snapshot.get("df_15m"); d5=snapshot.get("df_5m"); lb=int(CONFIG.get("COMPRESSION_LOOKBACK",20))
            if d15 is None or d5 is None or len(d15)<80 or len(d5)<50: return []
            atr=Indicators.atr(d15,int(CONFIG.get("ATR_PERIOD",14))); a=float(atr.iloc[-2]) if atr is not None else 0.0
            hist=atr.iloc[-(lb+40):-2].dropna() if atr is not None else None
            if a<=0 or hist is None or len(hist)<20: return []
            pct=float((hist<a).mean())
            if pct>float(CONFIG.get("COMPRESSION_MAX_ATR_PERCENTILE",0.35)): return []
            rng_high=float(d5["high"].iloc[-(lb+2):-2].max()); rng_low=float(d5["low"].iloc[-(lb+2):-2].min())
            range_ratio=(rng_high-rng_low)/max(a,1e-9)
            if range_ratio>float(CONFIG.get("COMPRESSION_MAX_RANGE_RATIO",6.0)): return []
            _min_bars=int(CONFIG.get("COMPRESSION_MIN_BARS_IN_RANGE",6))
            _range_mid=(rng_high+rng_low)/2.0; _range_half=max((rng_high-rng_low)/2.0,1e-9)
            _closes=d5["close"].astype(float).iloc[-(lb+2):-2]
            _bars_in_range=int(((_closes-_range_mid).abs() <= _range_half*1.05).sum())
            if _bars_in_range < _min_bars: return []
            e20=Indicators.ema(d15["close"],20); e50=Indicators.ema(d15["close"],50)
            sep_now=abs(float(e20.iloc[-2])-float(e50.iloc[-2]))/max(a,1e-9)
            sep_ref=abs(float(e20.iloc[-10])-float(e50.iloc[-10]))/max(float(atr.iloc[-10]),1e-9)
            if sep_now>max(sep_ref*1.25,0.05): return []
            f5=_v43_closed_features(d5,"5m")
            if f5 is None: return []
            if not (f5["close"]>rng_high*(1.0+float(CONFIG.get("EXPANSION_RANGE_BREAK_BUFFER_ATR",0.02))*f5["atr"]/max(f5["close"],1e-9))): return []
            if not f5["bullish"] or f5["body_ratio"]<float(CONFIG.get("EXPANSION_MIN_BODY_RATIO",0.50)): return []
            vr=f5.get("volume_ratio")
            if vr is None or vr<float(CONFIG.get("EXPANSION_MIN_VOLUME_RATIO",1.30)): return []
            if f5["high"]-f5["close"]>max(1e-9,f5["high"]-f5["low"])*0.5: return []
            chase=(f5["close"]-rng_high)/max(f5["atr"],1e-9)
            if chase>float(CONFIG.get("EXPANSION_MAX_CHASE_ATR",1.60)): return []
            target_rr=float(CONFIG["TP2_RR"])
            if target_rr<float(CONFIG.get("EXPANSION_MIN_RR",2.0)): return []
            score=_clamp(0.55+min(0.18,(1.0-pct)*0.18)+min(0.12,max(0.0,vr-1.0)*0.12)
                         +min(0.10,f5["body_ratio"]*0.10)+min(0.05,(1.0-min(chase/1.6,1.0))*0.05),0,1)
            feats={"strategy_mode":"COMPRESSION_EXPANSION","strategy_style":"SCALP","timeframe_profile":"15M_5M",
                   "macro_regime":regime,"local_regime":local,"market_phase":phase or "EXPANSION","bearish_severity":sev,
                   "atr_percentile":pct,"range_ratio":range_ratio,"volume_ratio":vr,"breakout_ref":rng_high,
                   "chase_atr":chase,"body_ratio":f5["body_ratio"],"target_rr":target_rr,"structure_quality":_clamp(1-pct,0,1),
                   "volume_quality":_clamp(vr-1.0,0,1),"retest_quality":0.6,"htf_alignment":0.6,"execution_quality":0.75}
            cand=_v43_base_candidate(cls.engine_id,symbol,f5["close"],f5["atr"],float(CONFIG["ATR_SL_MULT"]),
                (float(CONFIG["TP1_RR"]),float(CONFIG["TP2_RR"]),float(CONFIG["TP3_RR"])),score,snapshot.get("tier",""),
                regime,"COMPRESSION_EXPANSION",rng_high,feats)
            if cand: STATS["v43_opp_compression_expansion"]=STATS.get("v43_opp_compression_expansion",0)+1
            return [cand] if cand else []
        except Exception as exc:
            STATS["v43_engine_errors.compression_expansion"]=STATS.get("v43_engine_errors.compression_expansion",0)+1
            logger.warning(f"[V43][CMP_EXP] {symbol} isolated exception: {exc}")
            return []


class SwingPullbackEngine(_EngineBase):
    engine_id="swing_pullback"; family_map=("SWING_PULLBACK",)
    @classmethod
    def _config_enabled(cls):
        return bool(CONFIG.get("SWING_ENGINE_ENABLE",True)) and bool(CONFIG.get("V43_ADAPTIVE_ROUTER_ENABLE",True))
    @classmethod
    def _v701_3_reject(cls, snapshot, reason):
        try:
            sym=str((snapshot or {}).get("symbol","?"))
            key=f"v701_3_swing_blocker.{str(reason).upper()}"
            STATS[key]=int(STATS.get(key,0) or 0)+1
            STATS["v701_3_swing_no_match"]=int(STATS.get("v701_3_swing_no_match",0) or 0)+1
            STATS["v701_3_swing_last_blocker"]={"symbol":sym,"reason":str(reason),"ts":WALL_NOW()}
        except Exception:
            pass
        return []

    @classmethod
    def generate(cls,snapshot):
        if not cls._config_enabled(): return cls._v701_3_reject(snapshot,"disabled")
        symbol=snapshot.get("symbol","?")
        try:
            sev=_v43_macro_severity(snapshot)
            if not V425BearishSeverity.allows_new_long(sev): return cls._v701_3_reject(snapshot,"severity_disallowed")
            regime=str(snapshot.get("regime") or ""); local=str(snapshot.get("local_regime") or "")
            phase=str((snapshot.get("market_phase") or {}).get("phase",snapshot.get("market_phase") or ""))
            if not regime or not local: return cls._v701_3_reject(snapshot,"missing_regime_context")
            if not FamilyPolicyLayer.strategy_allowed("SWING_PULLBACK",regime,local,phase,sev,"SWING"): return cls._v701_3_reject(snapshot,"policy")
            d4=snapshot.get("df_4h"); d1=snapshot.get("df_1h"); d15=snapshot.get("df_15m")
            if d4 is None or d1 is None or d15 is None or len(d4)<220 or len(d1)<160 or len(d15)<80: return cls._v701_3_reject(snapshot,"data_window")
            e4_50=Indicators.ema(d4["close"],50); e4_200=Indicators.ema(d4["close"],200)
            c4=float(d4["close"].iloc[-2]); e50=float(e4_50.iloc[-2]); e200=float(e4_200.iloc[-2])
            slope=float(e4_50.iloc[-2])>float(e4_50.iloc[-6])
            if not(c4>e50>e200 and slope): return cls._v701_3_reject(snapshot,"4h_trend")
            strength4=_clamp((c4-e50)/max(c4-e200,1e-9),0,1)
            if strength4<float(CONFIG.get("SWING_MIN_4H_STRENGTH",0.5)): return cls._v701_3_reject(snapshot,"4h_strength")
            f1=_v43_closed_features(d1,"1h"); f15=_v43_closed_features(d15,"15m")
            if f1 is None or f15 is None or f1["rsi"] is None: return cls._v701_3_reject(snapshot,"indicator_data")
            if not(float(CONFIG["SWING_RSI_MIN"])<=f1["rsi"]<=float(CONFIG["SWING_RSI_MAX"])): return cls._v701_3_reject(snapshot,"1h_rsi")
            dist=min(abs(f1["close"]-f1["ema20"]),abs(f1["close"]-f1["ema50"]))/max(f1["atr"],1e-9)
            _hl1=_v43_hh_hl(d1,8)
            _structure1=_clamp((0.55 if _hl1 else 0.0) + (0.30 if dist<=1.0 else max(0.0,0.30*(1.0-dist/1.5))),0.0,1.0)
            if _structure1<float(CONFIG.get("SWING_MIN_1H_STRUCTURE",0.50)): return cls._v701_3_reject(snapshot,"1h_structure")
            if dist>1.5: return cls._v701_3_reject(snapshot,"1h_distance")
            if f1["volume_ratio"] is None or f1["volume_ratio"]<0.6: return cls._v701_3_reject(snapshot,"1h_volume")
            if not((f15["bullish"] and f15["close"]>f15["ema20"]) or _v43_hh_hl(d15,6)): return cls._v701_3_reject(snapshot,"15m_response")
            profile=ExitProfile(float(CONFIG["SWING_TP1_RR"]),float(CONFIG["SWING_TP2_RR"]),float(CONFIG["SWING_TP3_RR"]),
                                float(CONFIG.get("SWING_TRAIL_ATR",2.0)),float(CONFIG["SWING_MAX_HOLD_HOURS"]),"SWING_PULLBACK")
            if not profile.validate(): return cls._v701_3_reject(snapshot,"exit_profile")

            # V702 SWING STOP CLOSURE: a Swing trade must be protected by its
            # structural invalidation on the 1H timeframe, not by a 5M/global
            # 0.40% floor whenever 15M ATR happens to be small. Use the most
            # recent closed 1H lows over a bounded window and place the stop
            # 0.10 ATR(1H) below that invalidation. If unavailable, retain the
            # engine's native 15M ATR stop; canonical hard bounds still apply.
            _swing_native_sl = None
            try:
                _d1_low = d1["low"]
                _d1_end = max(2, len(d1)-1)
                _d1_start = max(1, _d1_end-int(CONFIG.get("SWING_SL_LOOKBACK_1H",8)))
                _recent_1h_low = float(_d1_low.iloc[_d1_start:_d1_end].min())
                _atr1 = float(f1["atr"])
                _struct_sl = _recent_1h_low - float(CONFIG.get("SWING_STRUCTURAL_SL_BUFFER_ATR",0.10))*_atr1
                _atr_sl = float(f15["close"]) - float(CONFIG["SWING_ATR_SL_MULT"])*float(f15["atr"])
                if math.isfinite(_struct_sl) and _struct_sl > 0 and _struct_sl < float(f15["close"]):
                    _struct_pct = (float(f15["close"])-_struct_sl)/max(float(f15["close"]),1e-12)*100.0
                    _max_sl_pct = float(CONFIG.get("MAX_SL_PCT",1.80))
                    if _struct_pct > _max_sl_pct and bool(CONFIG.get("SWING_REJECT_IF_1H_SL_TOO_WIDE", True)):
                        return cls._v701_3_reject(snapshot,"1h_structural_sl_too_wide")
                    if 0.40 <= _struct_pct <= _max_sl_pct:
                        _swing_native_sl = float(_struct_sl)
                        feats_native_sl_ref = float(_recent_1h_low)
                    else:
                        feats_native_sl_ref = None
                else:
                    feats_native_sl_ref = None
            except Exception:
                _swing_native_sl = None
                feats_native_sl_ref = None
            score=_clamp(0.55+min(0.15,strength4*0.15)+min(0.12,max(0.0,1.0-dist/1.5)*0.12)
                         +min(0.08,max(0.0,(f1["rsi"]-40)/28)*0.08)+min(0.10,max(0.0,f15["body_ratio"]-0.45)),0,1)
            if score*100<float(CONFIG.get("SWING_MIN_SCORE",70.0)): return cls._v701_3_reject(snapshot,"score")
            feats={"strategy_mode":"SWING_PULLBACK","strategy_style":"SWING","timeframe_profile":"4H_1H_15M",
                   "macro_regime":regime,"local_regime":local,"market_phase":phase,"bearish_severity":sev,
                   "family_native_sl_ref": feats_native_sl_ref if isinstance(feats_native_sl_ref,(int,float)) else None,
                   "swing_sl_source": "1H_structural_invalidation" if _swing_native_sl is not None else "15M_ATR_fallback",
                   "structure_quality":min(strength4,_structure1),"htf_alignment":strength4,"structure_1h":_structure1,
                   "volume_quality":_clamp(f1["volume_ratio"],0,1),"retest_quality":_clamp(1-dist/1.5,0,1),
                   "exit_profile":asdict(profile),"target_rr":profile.tp2_rr,"execution_quality":0.8}
            cand=_v43_base_candidate(cls.engine_id,symbol,f15["close"],f15["atr"],float(CONFIG["SWING_ATR_SL_MULT"]),
                (profile.tp1_rr,profile.tp2_rr,profile.tp3_rr),score,snapshot.get("tier",""),regime,
                "SWING_PULLBACK",f1["ema20"],feats,sl_override=_swing_native_sl)
            if cand: STATS["v43_opp_swing"]=STATS.get("v43_opp_swing",0)+1
            return [cand] if cand else cls._v701_3_reject(snapshot,"builder_geometry")
        except Exception as exc:
            STATS["v43_engine_errors.swing_pullback"]=STATS.get("v43_engine_errors.swing_pullback",0)+1
            logger.warning(f"[V43][SWING] {symbol} isolated exception: {exc}")
            return []


class ExtremeFlushReversalEngine(_EngineBase):
    engine_id="extreme_flush_reversal"; family_map=("EXTREME_FLUSH_REVERSAL",)
    @classmethod
    def _config_enabled(cls):
        return bool(CONFIG.get("EXTREME_FLUSH_ENABLE",True)) and bool(CONFIG.get("V43_ADAPTIVE_ROUTER_ENABLE",True))
    @classmethod
    def generate(cls,snapshot):
        if not cls._config_enabled(): return []
        symbol=snapshot.get("symbol","?")
        try:
            sev=_v43_macro_severity(snapshot)
            if not V425BearishSeverity.allows_new_long(sev): return []
            regime=str(snapshot.get("regime") or ""); local=str(snapshot.get("local_regime") or "")
            phase=str((snapshot.get("market_phase") or {}).get("phase",snapshot.get("market_phase") or ""))
            if not regime or not local or not FamilyPolicyLayer.strategy_allowed("EXTREME_FLUSH_REVERSAL",regime,local,phase,sev,"SCALP"): return []
            d15=snapshot.get("df_15m"); d5=snapshot.get("df_5m")
            if d15 is None or d5 is None or len(d15)<60 or len(d5)<50: return []
            atr=Indicators.atr(d15,int(CONFIG["ATR_PERIOD"])); a=float(atr.iloc[-2]) if atr is not None else 0.0
            if a<=0 or not math.isfinite(a): return []
            closes=d15["close"].astype(float); disp=(float(closes.iloc[-7])-float(closes.iloc[-2]))/a
            if disp<float(CONFIG.get("EXTREME_FLUSH_MIN_DISPLACEMENT_ATR",1.8)): return []
            lows=d5["low"].astype(float); prior_low=float(lows.iloc[-12:-3].min()); swept_low=float(lows.iloc[-3]); sweep=swept_low<prior_low
            if bool(CONFIG.get("EXTREME_FLUSH_REQUIRE_SWEEP",True)) and not sweep: return []
            f5=_v43_closed_features(d5,"5m")
            if f5 is None or not f5["bullish"]: return []
            reclaim=f5["close"]>f5["ema20"]
            if bool(CONFIG.get("EXTREME_FLUSH_REQUIRE_RECLAIM",True)) and not reclaim: return []
            higher_low=float(lows.iloc[-2])>float(lows.iloc[-4])
            if bool(CONFIG.get("EXTREME_FLUSH_REQUIRE_HIGHER_LOW",True)) and not higher_low: return []
            vr=f5.get("volume_ratio")
            if vr is None or vr<float(CONFIG.get("EXTREME_FLUSH_MIN_VOLUME_RATIO",1.1)): return []
            rs=compute_relative_strength(d5,snapshot.get("df_btc_5m"),d15,snapshot.get("df_btc_15m"),snapshot.get("df_1h"),snapshot.get("df_btc_1h"),8,8)
            if not rs.get("rs_valid") or rs["rs_5m"]<float(CONFIG.get("EXTREME_FLUSH_MIN_RS",0.0)): return []
            chase=max(0.0,(f5["close"]-f5["ema20"])/max(f5["atr"],1e-9))
            if chase>float(CONFIG.get("EXTREME_FLUSH_MAX_CHASE_ATR",1.2)): return []
            score=_clamp(0.50+min(0.16,disp*0.05)+min(0.10,max(0,vr-1.0)*0.1)
                         +min(0.12,max(0,rs["rs_5m"])*4)+0.06+0.06,0,1)
            if score*100<float(CONFIG.get("EXTREME_FLUSH_MIN_SCORE",68.0)): return []
            feats={"strategy_mode":"EXTREME_FLUSH_REVERSAL","strategy_style":"SCALP","timeframe_profile":"15M_5M",
                   "macro_regime":regime,"local_regime":local,"market_phase":phase or "REVERSAL","bearish_severity":sev,
                   "displacement_atr":disp,"sweep":sweep,"reclaim":reclaim,"higher_low":higher_low,
                   "volume_ratio":vr,"rs_5m":rs["rs_5m"],"rs_15m":rs["rs_15m"],"rs_persistence":rs["rs_persistence"],
                   "chase_atr":chase,"structure_quality":0.9,"volume_quality":_clamp(vr-1.0,0,1),
                   "retest_quality":0.8,"execution_quality":0.75}
            cand=_v43_base_candidate(cls.engine_id,symbol,f5["close"],f5["atr"],float(CONFIG["ATR_SL_MULT"]),
                (float(CONFIG["TP1_RR"]),float(CONFIG["TP2_RR"]),float(CONFIG["TP3_RR"])),score,snapshot.get("tier",""),
                regime,"EXTREME_FLUSH_REVERSAL",f5["ema20"],feats)
            if cand: STATS["v43_opp_flush_reversal"]=STATS.get("v43_opp_flush_reversal",0)+1
            return [cand] if cand else []
        except Exception as exc:
            STATS["v43_engine_errors.extreme_flush_reversal"]=STATS.get("v43_engine_errors.extreme_flush_reversal",0)+1
            logger.warning(f"[V43][FLUSH] {symbol} isolated exception: {exc}")
            return []


class ContinuationReclaimEngine(_EngineBase):
    engine_id="continuation_reclaim"; family_map=("CONTINUATION_RECLAIM",)
    @classmethod
    def _config_enabled(cls):
        return bool(CONFIG.get("CONTINUATION_RECLAIM_ENABLE",True)) and bool(CONFIG.get("V43_ADAPTIVE_ROUTER_ENABLE",True))
    @classmethod
    def generate(cls,snapshot):
        if not cls._config_enabled(): return []
        symbol=snapshot.get("symbol","?")
        try:
            sev=_v43_macro_severity(snapshot)
            if not V425BearishSeverity.allows_new_long(sev): return []
            regime=str(snapshot.get("regime") or ""); local=str(snapshot.get("local_regime") or "")
            phase=str((snapshot.get("market_phase") or {}).get("phase",snapshot.get("market_phase") or ""))
            if not FamilyPolicyLayer.strategy_allowed("CONTINUATION_RECLAIM",regime,local,phase,sev,"SCALP"): return []
            d15=snapshot.get("df_15m"); d5=snapshot.get("df_5m"); f15=_v43_closed_features(d15,"15m"); f5=_v43_closed_features(d5,"5m")
            if f15 is None or f5 is None or len(d5)<40: return []
            e20=Indicators.ema(d15["close"],20); slope=float(e20.iloc[-2])>float(e20.iloc[-6])
            prev=float(d5["close"].iloc[-3]); cur=float(f5["close"]); reclaim=bool(prev<=f5["ema20"]*1.002 and cur>f5["ema20"] and f5["bullish"])
            trend=bool(f15["close"]>f15["ema20"]>f15["ema50"] and slope)
            rs=compute_relative_strength(d5,snapshot.get("df_btc_5m"),d15,snapshot.get("df_btc_15m"),snapshot.get("df_1h"),snapshot.get("df_btc_1h"),12,12)
            if not rs.get("rs_valid") or rs.get("rs_5m") is None: return []
            chase=max(0.0,(cur-f5["ema20"])/max(f5["atr"],1e-9)); vr=float(f5.get("volume_ratio") or 0.0)
            if not(trend and reclaim and vr>=float(CONFIG.get("CONTINUATION_RECLAIM_MIN_VOLUME_RATIO",0.95)) and rs["rs_5m"]>=float(CONFIG.get("CONTINUATION_RECLAIM_MIN_RS",0.0)) and chase<=float(CONFIG.get("CONTINUATION_RECLAIM_MAX_CHASE_ATR",1.25))): return []
            score=_clamp(0.43+0.10*_clamp(rs["rs_5m"]*20,-1,1)+0.15*_clamp((vr-0.8)/0.8,0,1)+0.17+0.15*_clamp((1.25-chase)/1.25,0,1),0,1)
            if score*100<float(CONFIG.get("CONTINUATION_RECLAIM_MIN_SCORE",69.0)): return []
            feats={"strategy_mode":"CONTINUATION_RECLAIM","strategy_style":"SCALP","timeframe_profile":"15M_5M","macro_regime":regime,"local_regime":local,"market_phase":phase,"bearish_severity":sev,"trend_alignment":True,"reclaim":True,"volume_ratio":vr,"rs_5m":rs["rs_5m"],"rs_15m":rs["rs_15m"],"rs_persistence":rs["rs_persistence"],"chase_atr":chase,"structure_quality":0.85,"volume_quality":_clamp((vr-0.8)/0.8,0,1),"retest_quality":0.75,"htf_alignment":0.65,"target_rr":2.2,"execution_quality":0.82}
            cand=_v43_base_candidate(cls.engine_id,symbol,cur,f5["atr"],float(CONFIG["ATR_SL_MULT"]),(1.0,2.2,4.5),score,snapshot.get("tier",""),regime,"CONTINUATION_RECLAIM",float(f5["ema20"]),feats)
            if cand: STATS["v44_opp_continuation_reclaim"]=STATS.get("v44_opp_continuation_reclaim",0)+1
            return [cand] if cand else []
        except Exception as exc:
            STATS["v44_engine_errors.continuation_reclaim"]=STATS.get("v44_engine_errors.continuation_reclaim",0)+1; logger.warning(f"[V44][CR] {symbol} isolated exception: {exc}"); return []


class FailedBreakoutReclaimEngine(_EngineBase):
    engine_id="failed_breakout_reclaim"; family_map=("FAILED_BREAKOUT_RECLAIM",)
    @classmethod
    def _config_enabled(cls):
        return bool(CONFIG.get("FAILED_BREAKOUT_RECLAIM_ENABLE",True)) and bool(CONFIG.get("V43_ADAPTIVE_ROUTER_ENABLE",True))
    @classmethod
    def generate(cls,snapshot):
        if not cls._config_enabled(): return []
        symbol=snapshot.get("symbol","?")
        try:
            sev=_v43_macro_severity(snapshot)
            if not V425BearishSeverity.allows_new_long(sev): return []
            regime=str(snapshot.get("regime") or ""); local=str(snapshot.get("local_regime") or "")
            phase=str((snapshot.get("market_phase") or {}).get("phase",snapshot.get("market_phase") or ""))
            if not FamilyPolicyLayer.strategy_allowed("FAILED_BREAKOUT_RECLAIM",regime,local,phase,sev,"SCALP"): return []
            d15=snapshot.get("df_15m"); d5=snapshot.get("df_5m"); f5=_v43_closed_features(d5,"5m")
            if f5 is None or d15 is None or len(d5)<50: return []
            lb=int(CONFIG.get("FAILED_BREAKOUT_RECLAIM_LOOKBACK",10)); ref=float(d5["high"].iloc[-(lb+5):-4].max())
            brk=d5.iloc[-4]; fail=d5.iloc[-3]; rec=d5.iloc[-2]
            breakout=float(brk["close"])>ref; failed=float(fail["low"])<=ref and float(fail["close"])<ref; reclaim=float(rec["close"])>ref and float(rec["close"])>float(rec["open"])
            body=abs(float(rec["close"])-float(rec["open"]))/max(float(rec["high"])-float(rec["low"]),1e-9)
            rs=compute_relative_strength(d5,snapshot.get("df_btc_5m"),d15,snapshot.get("df_btc_15m"),snapshot.get("df_1h"),snapshot.get("df_btc_1h"),12,12)
            if not rs.get("rs_valid") or rs.get("rs_5m") is None: return []
            chase=max(0.0,(float(rec["close"])-ref)/max(f5["atr"],1e-9)); vr=float(f5.get("volume_ratio") or 0.0)
            valid=breakout and failed and reclaim and body>=0.40 and vr>=float(CONFIG.get("FAILED_BREAKOUT_RECLAIM_MIN_VOLUME_RATIO",1.0)) and rs["rs_5m"]>=float(CONFIG.get("FAILED_BREAKOUT_RECLAIM_MIN_RS",-0.002)) and chase<=float(CONFIG.get("FAILED_BREAKOUT_RECLAIM_MAX_CHASE_ATR",1.0))
            if not valid: return []
            score=_clamp(0.44+0.10*body+0.15*_clamp((vr-0.8)/0.8,0,1)+0.12*_clamp(1.0-chase,0,1)+0.11*_clamp((rs["rs_5m"]+0.002)*30,0,1)+0.08,0,1)
            if score*100<float(CONFIG.get("FAILED_BREAKOUT_RECLAIM_MIN_SCORE",70.0)): return []
            feats={"strategy_mode":"FAILED_BREAKOUT_RECLAIM","strategy_style":"SCALP","timeframe_profile":"15M_5M","macro_regime":regime,"local_regime":local,"market_phase":phase,"bearish_severity":sev,"failed_breakout":True,"reclaim":True,"volume_ratio":vr,"body_ratio":body,"rs_5m":rs["rs_5m"],"rs_15m":rs["rs_15m"],"rs_persistence":rs["rs_persistence"],"chase_atr":chase,"structure_quality":0.90,"volume_quality":_clamp((vr-0.8)/0.8,0,1),"retest_quality":0.90,"htf_alignment":0.60,"target_rr":2.0,"execution_quality":0.85}
            cand=_v43_base_candidate(cls.engine_id,symbol,float(rec["close"]),f5["atr"],float(CONFIG["ATR_SL_MULT"]),(0.9,2.0,4.0),score,snapshot.get("tier",""),regime,"FAILED_BREAKOUT_RECLAIM",ref,feats)
            if cand: STATS["v44_opp_failed_breakout_reclaim"]=STATS.get("v44_opp_failed_breakout_reclaim",0)+1
            return [cand] if cand else []
        except Exception as exc:
            STATS["v44_engine_errors.failed_breakout_reclaim"]=STATS.get("v44_engine_errors.failed_breakout_reclaim",0)+1; logger.warning(f"[V44][FBR] {symbol} isolated exception: {exc}"); return []


