# A10 explicit HTF semantics are metadata, not execution bypass flags.
for _mode702 in (_V702_HTF_STRICT_FAMILIES | _V702_HTF_CONTEXTUAL_FAMILIES | _V702_HTF_SOFT_FAMILIES):
    _meta702 = V43_STRATEGY_POLICY_META.setdefault(_mode702, {})
    _policy702 = _v702_htf_policy_name(_mode702, _mode702, {})
    _meta702["htf_policy"] = _policy702
    if _policy702 == "CONTEXTUAL_FLOOR":
        _meta702["min_htf_strength_non_bearish"] = float(CONFIG.get("V702_HTF_PULLBACK_CONTEXT_FLOOR", 45.0))
    elif _policy702 == "SOFT_LOCAL_CONFIRMATION":
        # Preserve the original number as a preferred/reference value for diagnostics;
        # the canonical gate uses the policy label and does not treat it as a hard floor.
        _meta702.setdefault("preferred_htf_strength_non_bearish", 50.0)

for _mode590, _ctx590 in _V590_CANONICAL_CONTEXT_DEFAULTS.items():
    _rec590 = V43_STRATEGY_POLICY_META.setdefault(_mode590, {})
    for _key590, _vals590 in _ctx590.items():
        _rec590.setdefault(_key590, _vals590)
    _rec590.setdefault("enabled", True)

# v4.5.90 — align the high-recall canonical floors with the actual live engine
# floors.  This does not loosen any existing engine gate; it only removes a
# lower canonical floor that could create SELECTED->BUILDER policy ambiguity.
for _mode590, _score590 in {
    "VOLATILITY_BURST": 68.0,
    "RELATIVE_STRENGTH_LEADER": 67.0,
    "MICRO_TREND_CONTINUATION": 62.0,
}.items():
    try:
        V43_STRATEGY_POLICY_META[_mode590]["min_score"] = max(
            float(V43_STRATEGY_POLICY_META[_mode590].get("min_score", 0.0)),
            float(_score590),
        )
    except Exception:
        _v647_record_suppressed_exception()

# V702 A47 — make the effective macro-regime allow-list explicit before the
# canonical policy registry bootstraps. Existing explicit V43/A10 policy wins;
# missing entries inherit the matching legacy family allow-list. If no legacy
# policy exists, fail closed to NEUTRAL rather than interpreting empty as allow-all.
_V702_A47_REGIME_POLICY_SOURCE = {}
for _mode_a47, _meta_a47 in V43_STRATEGY_POLICY_META.items():
    _meta_a47 = _meta_a47 if isinstance(_meta_a47, dict) else {}
    _existing_a47 = _meta_a47.get("allowed_regimes")
    if isinstance(_existing_a47, (list, tuple, set, frozenset)) and _existing_a47:
        _allowed_a47 = tuple(sorted({str(x).strip().upper() for x in _existing_a47 if str(x).strip()}))
        _source_a47 = "existing_canonical_metadata"
    else:
        _legacy_a47 = CONFIG.get("FAMILY_POLICY_" + str(_mode_a47).upper(), {})
        _legacy_allowed_a47 = _legacy_a47.get("allowed_regimes", ()) if isinstance(_legacy_a47, dict) else ()
        if isinstance(_legacy_allowed_a47, (list, tuple, set, frozenset)) and _legacy_allowed_a47:
            _allowed_a47 = tuple(sorted({str(x).strip().upper() for x in _legacy_allowed_a47 if str(x).strip()}))
            _source_a47 = "legacy_family_policy_materialized"
        else:
            _allowed_a47 = ("NEUTRAL",)
            _source_a47 = "fail_closed_neutral_default"
    _meta_a47["allowed_regimes"] = _allowed_a47
    _meta_a47.setdefault("allowed_regimes_source", _source_a47)
    V43_STRATEGY_POLICY_META[_mode_a47] = _meta_a47
    _V702_A47_REGIME_POLICY_SOURCE[str(_mode_a47).upper()] = _source_a47

for _k, _v in V43_DEFAULTS.items():
    CONFIG.setdefault(_k, _v)



def _v43_self_test() -> None:
    if not _PDNP_OK:
        logger.info("V4.3 self-test: SKIPPED (pandas/numpy unavailable)")
        return
    results = []
    def ok(name, cond):
        results.append((name, bool(cond)))

    def df(n=240,start=100.0,drift=0.15,vol=400.0):
        return _v425_make_df(n,start,drift=drift,vol=vol)

    up15=df(260,100,0.18,500)
    up5=df(260,100,0.10,550)
    btc15=df(260,110,-0.30,350)
    # Deliberately make the final closed BTC 15m window materially weaker than
    # the symbol so the RS_15M hard gate is genuinely exercised.
    _rs_tail = np.linspace(1.0, 0.94, 30)
    btc15.loc[btc15.index[-30:], "close"] = btc15["close"].iloc[-30:].astype(float).to_numpy() * _rs_tail
    btc5=df(260,110,-0.05,350)
    _rs5_tail = np.linspace(1.0, 0.985, 20)
    btc5.loc[btc5.index[-20:], "close"] = btc5["close"].iloc[-20:].astype(float).to_numpy() * _rs5_tail
    up4=df(260,100,0.20,600)
    up1=df(220,100,0.12,400)

    ref=float(up5["high"].iloc[-20:-2].max())
    i=up5.index[-2]
    _atr_test=float(Indicators.atr(up5, int(CONFIG["ATR_PERIOD"])).iloc[-2])
    _atr_test=max(_atr_test,0.1)
    up5.loc[i,"open"]=ref+0.10*_atr_test
    up5.loc[i,"low"]=ref-0.10*_atr_test
    up5.loc[i,"close"]=ref+0.65*_atr_test
    up5.loc[i,"high"]=ref+0.85*_atr_test
    up5.loc[i,"volume"]=float(up5["volume"].iloc[-22:-2].mean())*2.0

    phase=MarketPhaseDetector.detect(up5,up15,up1,"BEARISH","LOCAL_BULLISH")
    ok("market_phase_structured",isinstance(phase,dict) and "phase" in phase)

    base={
        "symbol":"TST/USDT","df_15m":up15,"df_5m":up5,"df_4h":up4,"df_1h":up1,
        "df_btc_5m":btc5,"df_btc_15m":btc15,"df_btc_1h":btc5,"tier":"LARGE",
        "regime":"BEARISH","macro_regime":"BEARISH","local_regime":"LOCAL_BULLISH",
        "macro_severity":V425BearishSeverity.NORMAL,
        "market_phase":{"phase":phase.get("phase","EXPANSION"),"confidence":phase.get("confidence",0.8)}
    }

    lsb=LocalStrengthBreakoutEngine.generate(dict(base))
    ok("LSB_valid_candidate",any(c.strategy_mode=="LOCAL_STRENGTH_BREAKOUT" for c in lsb))
    ok("LSB_crash_reject",not LocalStrengthBreakoutEngine.generate(dict(base,macro_severity=V425BearishSeverity.CRASH)))
    ok("LSB_missing_RS_reject",not LocalStrengthBreakoutEngine.generate(dict(base,df_btc_5m=None,df_btc_15m=None)))

    no_break=df(260,100,0.02,550)
    ok("LSB_no_breakout_reject",not LocalStrengthBreakoutEngine.generate(dict(base,df_5m=no_break)))

    ce=CompressionExpansionEngine.generate(dict(base))
    ok("Compression_safe",isinstance(ce,list))
    ok("Compression_crash_reject",not CompressionExpansionEngine.generate(dict(base,macro_severity=V425BearishSeverity.CRASH)))

    ep=ExitProfile(2.0,3.0,4.0,2.0,48.0,"SWING_PULLBACK")
    ok("Swing_exit_profile_valid",ep.validate())

    ok("Swing_missing_4H_reject",not SwingPullbackEngine.generate(dict(base,df_4h=None)))
    ok("Swing_crash_reject",not SwingPullbackEngine.generate(dict(base,regime="BULLISH",macro_severity=V425BearishSeverity.CRASH)))

    ok("Flush_crash_reject",not ExtremeFlushReversalEngine.generate(dict(base,macro_severity=V425BearishSeverity.CRASH)))

    ok("Policy_LSB_Bearish_LocalBullish",
       FamilyPolicyLayer.strategy_allowed("LOCAL_STRENGTH_BREAKOUT","BEARISH","LOCAL_BULLISH",
                                           "EXPANSION",V425BearishSeverity.NORMAL,"SCALP"))
    ok("Policy_LSB_Bearish_LocalBearish_reject",
       not FamilyPolicyLayer.strategy_allowed("LOCAL_STRENGTH_BREAKOUT","BEARISH","LOCAL_BEARISH",
                                               "EXPANSION",V425BearishSeverity.NORMAL,"SCALP"))
    ok("Policy_Crash_absolute",
       not FamilyPolicyLayer.strategy_allowed("LOCAL_STRENGTH_BREAKOUT","BEARISH","LOCAL_BULLISH",
                                              "BREAKOUT",V425BearishSeverity.CRASH,"SCALP"))
    ok("StrategyProfile_CR_valid", StrategyExitProfiles.profile_for("CONTINUATION_RECLAIM").validate())
    ok("StrategyProfile_FBR_valid", StrategyExitProfiles.profile_for("FAILED_BREAKOUT_RECLAIM").validate())
    ok("StrategyProfile_BEAR_valid", StrategyExitProfiles.profile_for("BEARISH_RECOVERY").validate())

    invalid=StrategyCandidate(
        engine_id="test",symbol="TST/USDT",side="long",generated_at_ms=0,
        entry_ref=100,sl_price=99,tp1_rr=1,tp2_rr=2,tp3_rr=3,engine_score=1,
        rr_ratio=1,liquidity_score=1,regime_fit=1,family="LOCAL_STRENGTH_BREAKOUT",zone_ref=100,
        features_snapshot={"strategy_mode":"LOCAL_STRENGTH_BREAKOUT","hard_valid":False,
                           "market_phase":"BREAKOUT","macro_regime":"BEARISH","local_regime":"LOCAL_BULLISH"})
    ok("Hard_validation_rejects_weak_candidate",CompositeRankingEngine._validate_fail_closed(invalid) is not None)

    for eng in (LocalStrengthBreakoutEngine,CompressionExpansionEngine,SwingPullbackEngine,ExtremeFlushReversalEngine,ContinuationReclaimEngine,FailedBreakoutReclaimEngine):
        ok(f"{eng.engine_id}_missing_data",eng.generate({"symbol":"X/USDT"})==[])

    for c in lsb+ce:
        ok(f"{c.engine_id}_long_only",c.side=="long")

    failed=[n for n,c in results if not c]
    for n,c in results:
        logger.info(f"[V43.selftest] {'PASS' if c else 'FAIL'} {n}")
    if failed:
        raise AssertionError(f"V4.3 self-tests FAILED: {failed}")
    logger.info(f"V4.3 ADAPTIVE-MULTI-OPPORTUNITY self-test: PASS ({len(results)} checks)")


def _v43_hb_segment() -> str:
    """Bounded heartbeat summary for opportunity and MSE coverage."""
    try:
        opp_keys=[("PB","v43_opp_pullback"),("LSB","v43_opp_local_strength_breakout"),
                  ("CMP","v43_opp_compression_expansion"),("SWG","v43_opp_swing"),
                  ("REV","v43_opp_flush_reversal"),("CR","v44_opp_continuation_reclaim"),
                  ("FBR","v44_opp_failed_breakout_reclaim")]
        nfm_keys=[("PB","pullback"),("BRK","breakout"),("RS","local_strength_breakout"),
                  ("CMP","compression_expansion"),("SWG","swing_pullback"),("REV","extreme_flush_reversal"),
                   ("CR","continuation_reclaim"),("FBR","failed_breakout_reclaim")]
        opp="OPP["+",".join(f"{k}={int(STATS.get(v,0) or 0)}" for k,v in opp_keys)+"]"
        nfm="NFM[scope=TOTAL,"+",".join(f"{k}={int(STATS.get('v43_nfm.'+v,0) or 0)}" for k,v in nfm_keys)+"]"
        mse=(f"MSE[CYCLE G={int(STATS.get('v681_runtime_cycle_generated',0) or 0)},"
             f"V={int(STATS.get('v681_runtime_cycle_hard_valid',0) or 0)},"
             f"R={int(STATS.get('v681_runtime_cycle_ranked',0) or 0)},"
             f"W={int(STATS.get('v681_runtime_cycle_selected',0) or 0)},"
             f"Q={int(STATS.get('v681_runtime_cycle_queued',0) or 0)},"
             f"S={int(STATS.get('v681_runtime_cycle_sent',0) or 0)};"
             f"CUM G={int(STATS.get('mse_generated',0) or 0)},"
             f"V={int(STATS.get('mse_hard_valid',0) or 0)},"
             f"R={int(STATS.get('mse_ranked',0) or 0)},"
             f"W={int(STATS.get('mse_winners',0) or 0)},"
             f"RCL={int(STATS.get('v607_mse_quality_recovered_cycle',0) or 0)},"
             f"NM={int(STATS.get('v607_near_miss_telegram_cycle',0) or 0)}]")
        _mse_rank_last=getattr(_MSEState, "last_run_counts", {}) or {}
        _mse_rank_gen=sum(int(v or 0) for v in (_mse_rank_last.get("generated",{}) or {}).values())
        _mse_ranked=int(_mse_rank_last.get("ranked",0) or 0)
        _mse_rank_top=sorted(((str(k),int(v or 0)) for k,v in (_mse_rank_last.get("reject_reasons",{}) or {}).items() if int(v or 0)>0),key=lambda kv:(-kv[1],kv[0]))[:5]
        _mse_rank_starv=int(_mse_rank_gen>0 and _mse_ranked==0)
        rank_starv=(f" MSE_RANK[G={_mse_rank_gen},R={_mse_ranked},S={_mse_rank_starv},top={str(_mse_rank_top)[:180]} source=CURRENT_RUN]")
        bridge = (
            f" LEGACY_BRIDGE[A={int(STATS.get('v596_bridge_attempts',0) or 0)},"
            f"R={int(STATS.get('v596_bridge_ready',0) or 0)},"
            f"S={int(STATS.get('v596_bridge_sent',0) or 0)},"
            f"B={int(STATS.get('v596_bridge_blocks',0) or 0)}]"
        )
        return " "+opp+" "+mse+rank_starv+bridge+" "+nfm
    except Exception:
        return ""



def _v44_repaired_self_test() -> None:
    """Production repair acceptance suite. Offline only; never touches exchange."""
    if not _PDNP_OK:
        raise RuntimeError("pandas/numpy required for repaired self-test")
    results = []
    def ok(name, cond):
        results.append((name, bool(cond)))
    def mkdf(n=360, start=100.0, drift=0.08):
        idx = pd.date_range("2026-01-01", periods=n, freq="5min")
        close = np.array([start + drift*i for i in range(n)], dtype=float)
        return pd.DataFrame({"open":close-0.05,"high":close+0.12,
                             "low":close-0.12,"close":close,
                             "volume":np.linspace(100.0,300.0,n)}, index=idx)
    btc5, btc15, btc1h, btc4h = mkdf(360), mkdf(360), mkdf(260), mkdf(220)
    snapshot = {
        "symbol":"AAA/USDT","df_1d":mkdf(120),"df_4h":btc4h,"df_1h":btc1h,
        "df_15m":btc15,"df_5m":btc5,"df_btc_5m":btc5,"df_btc_15m":btc15,
        "df_btc_1h":btc1h,"df_btc_4h":btc4h,"tier":"LARGE","regime":"BULLISH",
        "macro_regime":"BULLISH","local_regime":"BULLISH","macro_severity":"NORMAL",
        "bearish_severity":"NORMAL","market_phase":{"phase":"TREND"},
        "btc_context":"OK","htf_strength":70.0,
    }
    good, reason = validate_mse_snapshot(snapshot)
    ok("mse_snapshot_valid", good and reason == "ok")
    bad = dict(snapshot); bad["df_btc_5m"] = None
    good2, reason2 = validate_mse_snapshot(bad)
    ok("missing_btc_5m_rejected_explicitly", (not good2) and reason2 == "mse_missing_btc_context")
    _set_mse_status("ACTIVE","selftest_recovered")
    ok("mse_no_df_btc_5m_nameerror", "df_btc_5m" in snapshot)
    ok("correlation_canonical_reference", hasattr(CorrelationHardCap,"_cluster_of"))
    try:
        ok("correlation_no_cluster_no_penalty", CorrelationHardCap._cluster_of("UNKNOWN/USDT") is None)
    except Exception:
        ok("correlation_no_cluster_no_penalty", False)

    _V420State.recall_hist.clear(); _V420State.nfm_hist.clear()
    for _ in range(200): _V420State.note_g()
    for _ in range(120): _V420State.note_nfm()
    ratio, g, e, s = _V420State.recall_rate(window_sec=900)
    nfm_window = _V420State.nfm_count(window_sec=900)
    ok("nfm_same_window_ratio", g == 200 and nfm_window == 120 and abs((nfm_window/g)-0.6)<1e-9)
    ok("starvation_window_argument_defined",
       isinstance(V425Starvation.classify(g,e,0,s,0.6,nfm_window), str))

    _V420State.relaxed_mode_until_ts = MONO_NOW() + 60
    ok("relaxed_mode_activate", V420FunnelWatchdog.is_relaxed())
    _V420State.relaxed_mode_until_ts = MONO_NOW() - 1
    ok("relaxed_mode_expire", not V420FunnelWatchdog.is_relaxed())
    _V420State.relaxed_mode_until_ts = 0.0

    neutral_strength = max(0.0,55.0-float(CONFIG.get("HTF_NEUTRAL_PENALTY",22.0)))
    neutral_floor = float(CONFIG.get("FAMILY_POLICY_PULLBACK_NEUTRAL_HTF_MIN",33.0))
    ok("neutral_pullback_floor_bounded", 30.0 <= neutral_floor <= 40.0)
    ok("neutral_pullback_floor_reachable", neutral_strength >= neutral_floor)

    failed=[n for n,p in results if not p]
    for n,p in results: logger.info(f"[V44-REPAIRED.selftest] {'PASS' if p else 'FAIL'} {n}")
    if failed: raise AssertionError(f"V4.4-REPAIRED self-tests FAILED: {failed}")
    logger.info(f"V4.4-REPAIRED acceptance self-test: PASS ({len(results)} checks)")


def _v44_self_test() -> None:
    """
    Lightweight, side-effect-free acceptance suite for the V4.4 additions.
    It deliberately does NOT place/cancel real orders and does NOT mutate the
    persistent expectancy database.
    """
    results = []

    def ok(name: str, cond: bool) -> None:
        results.append((name, bool(cond)))

    # Cold-start expectancy must be neutral.
    ok(
        "expectancy_cold_start_neutral",
        abs(StrategyPerformanceMemory.rank_adjustment(
            "LOCAL_STRENGTH_BREAKOUT", "BULLISH", "ASIA", "SCALP", "TEST/USDT"
        )) <= 1e-12,
    )

    # Exit profiles must remain valid for all strategy families.
    for name in (
        "LOCAL_STRENGTH_BREAKOUT",
        "COMPRESSION_EXPANSION",
        "SWING_PULLBACK",
        "EXTREME_FLUSH_REVERSAL",
        "CONTINUATION_RECLAIM",
        "FAILED_BREAKOUT_RECLAIM",
    ):
        try:
            ok(f"exit_profile_{name}", bool(StrategyExitProfiles.profile_for(name).validate()))
        except Exception:
            ok(f"exit_profile_{name}", False)

    # Production gate remains non-ordering and starts uncertified.
    ok(
        "production_gate_snapshot_structured",
        isinstance(ProductionCapabilityGate.snapshot(), dict),
    )
    ok(
        "production_gate_never_submits_orders",
        "submit" not in " ".join(ProductionCapabilityGate.snapshot().keys()).lower(),
    )

    failed = [name for name, passed in results if not passed]
    for name, passed in results:
        logger.info(f"[V44.selftest] {'PASS' if passed else 'FAIL'} {name}")
    if failed:
        raise AssertionError(f"V4.4 self-tests FAILED: {failed}")
    logger.info(f"V4.4 ADAPTIVE-EXPECTANCY acceptance self-test: PASS ({len(results)} checks)")


# v4.3 — register adaptive engines into the MSE tuple (post-definition).
try:
    _MSE_ENGINES = tuple(list(_MSE_ENGINES) + [
        LocalStrengthBreakoutEngine, CompressionExpansionEngine,
        SwingPullbackEngine, ExtremeFlushReversalEngine,
        ContinuationReclaimEngine, FailedBreakoutReclaimEngine])
except Exception:
    _v647_record_suppressed_exception()


