# =============================================================================
# v4.5.11 — CANONICAL STRATEGY POLICY CONSISTENCY / DRIFT GUARD
# =============================================================================
# V43_STRATEGY_POLICY_META is the sole runtime policy authority. The historical
# CONFIG["V43_STRATEGY_META"] registry is normalized into that authority and
# then rewritten as a compatibility mirror. Numeric minimums are merged using
# the stricter value (max score / max HTF / max tier rank); boolean enablement
# is fail-closed (AND); allowed-context sets use the intersection when both
# registries define them. This prevents policy drift without opening a bypass.

_F456_TIER_RANK = {
    "BELOW": 0, "MICRO": 1, "MID": 2, "LARGE": 3, "MAJOR": 4,
}
_F456_POLICY_ALLOWED_KEYS = (
    "allowed_regimes", "allowed_local_regimes", "allowed_severity",
    "allowed_phases", "allowed_styles",
)

def _v456_normalize_allowed(value: Any) -> tuple:
    try:
        vals = [str(x).upper() for x in (value or ()) if str(x).strip()]
        return tuple(sorted(set(vals)))
    except Exception:
        return ()

def _v456_merge_strategy_policy(canonical: Dict[str, Any], mirror: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(canonical or {})
    mir = dict(mirror or {})
    # Hard enablement: disagreement resolves to disabled, never enabled.
    if "enabled" in mir or "enabled" in out:
        out["enabled"] = bool(out.get("enabled", True)) and bool(mir.get("enabled", True))
    # Safety-critical numeric minima merge to the stricter value.
    for key in ("min_score", "min_htf_strength_non_bearish"):
        vals=[]
        for obj in (out, mir):
            try:
                if key in obj and math.isfinite(float(obj[key])):
                    vals.append(float(obj[key]))
            except Exception:
                _v647_record_suppressed_exception()
        if vals:
            out[key] = max(vals)
    if "min_tier" in out or "min_tier" in mir:
        a=str(out.get("min_tier", "MICRO")).upper()
        b=str(mir.get("min_tier", "MICRO")).upper()
        if a not in _F456_TIER_RANK or b not in _F456_TIER_RANK:
            # Unknown tier names are not silently accepted. Keep the canonical
            # value when valid; otherwise fall back to MID conservatively.
            if a in _F456_TIER_RANK: out["min_tier"] = a
            elif b in _F456_TIER_RANK: out["min_tier"] = b
            else: out["min_tier"] = "MID"
        else:
            out["min_tier"] = a if _F456_TIER_RANK[a] >= _F456_TIER_RANK[b] else b
    # Non-numeric descriptive fields prefer the explicit canonical value.
    if not out.get("style") and mir.get("style"):
        out["style"] = str(mir.get("style")).upper()
    for key in _F456_POLICY_ALLOWED_KEYS:
        ca=_v456_normalize_allowed(out.get(key))
        mi=_v456_normalize_allowed(mir.get(key))
        if ca and mi:
            inter=tuple(sorted(set(ca).intersection(mi)))
            out[key] = inter
        elif mi:
            out[key] = mi
        elif ca:
            out[key] = ca
    return out

def _v456_sync_strategy_policy_registries() -> Dict[str, Any]:
    """Canonical-only policy sync. Historical CONFIG mirror is diagnostics-only."""
    report={"modes":0,"conflicts":0,"missing":0,"disabled_conflicts":0,"mirror_only":0,"details":[],"drift_detected":0}
    try:
        canonical=V43_STRATEGY_POLICY_META if isinstance(V43_STRATEGY_POLICY_META,dict) else {}
        mirror=CONFIG.get("V43_STRATEGY_META",{}); mirror=mirror if isinstance(mirror,dict) else {}
        defaults={
            "LOCAL_STRENGTH_BREAKOUT":{"allowed_regimes":("BULLISH","NEUTRAL","BEARISH"),"allowed_local_regimes":("LOCAL_BULLISH",),"allowed_severity":("BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""),"allowed_phases":("TREND","EXPANSION","BREAKOUT","PULLBACK","UNKNOWN"),"allowed_styles":("SCALP",)},
            "COMPRESSION_EXPANSION":{"allowed_regimes":("BULLISH","NEUTRAL","BEARISH"),"allowed_local_regimes":("LOCAL_BULLISH","LOCAL_RECOVERY","LOCAL_NEUTRAL"),"allowed_severity":("BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""),"allowed_phases":("COMPRESSION","EXPANSION","BREAKOUT","UNKNOWN"),"allowed_styles":("SCALP",)},
            "CONTINUATION_RECLAIM":{"allowed_regimes":("BULLISH","NEUTRAL","BEARISH"),"allowed_local_regimes":("LOCAL_BULLISH","LOCAL_RECOVERY"),"allowed_severity":("BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""),"allowed_phases":("TREND","PULLBACK","EXPANSION","BREAKOUT","UNKNOWN"),"allowed_styles":("SCALP",)},
            "FAILED_BREAKOUT_RECLAIM":{"allowed_regimes":("BULLISH","NEUTRAL","BEARISH"),"allowed_local_regimes":("LOCAL_BULLISH","LOCAL_RECOVERY"),"allowed_severity":("BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""),"allowed_phases":("BREAKOUT","EXPANSION","REVERSAL","UNKNOWN"),"allowed_styles":("SCALP",)},
            "SWING_PULLBACK":{"allowed_regimes":("BULLISH","NEUTRAL"),"allowed_local_regimes":("LOCAL_BULLISH","LOCAL_RECOVERY","LOCAL_NEUTRAL"),"allowed_severity":("NORMAL","STRESSED","BEARISH_NORMAL","BEARISH_STRESSED",""),"allowed_phases":("PULLBACK","TREND","EXPANSION","UNKNOWN"),"allowed_styles":("SWING",)},
            "EXTREME_FLUSH_REVERSAL":{"allowed_regimes":("BULLISH","NEUTRAL","BEARISH"),"allowed_local_regimes":("LOCAL_RECOVERY","LOCAL_BULLISH","LOCAL_NEUTRAL"),"allowed_severity":("BEARISH_NORMAL","BEARISH_STRESSED","NORMAL","STRESSED",""),"allowed_phases":("REVERSAL","EXPANSION","BREAKOUT","UNKNOWN"),"allowed_styles":("SCALP",)},
        }
        for mode,ctx in defaults.items():
            if mode in canonical and isinstance(canonical[mode],dict):
                for k,v in ctx.items(): canonical[mode].setdefault(k,v)
        for mode,mrec in mirror.items():
            if mode not in canonical:
                report["mirror_only"]+=1
                if len(report["details"])<32: report["details"].append({"mode":mode,"keys":["mirror_only"]})
                continue
            c=dict(canonical.get(mode) or {}); m=dict(mrec or {}); diffs=[]
            for key in ("enabled","min_score","min_tier","min_htf_strength_non_bearish") + _F456_POLICY_ALLOWED_KEYS:
                if key in c and key in m and c.get(key)!=m.get(key): diffs.append(key)
            if diffs:
                report["conflicts"]+=len(diffs); report["drift_detected"]+=len(diffs)
                if "enabled" in diffs: report["disabled_conflicts"]+=1
                if len(report["details"])<32: report["details"].append({"mode":mode,"keys":diffs})
        # Canonical-only closure: the compatibility mirror is regenerated from
        # the canonical registry and can never participate in runtime policy.
        # Preserve the observed pre-normalization drift for audit telemetry, but
        # expose zero post-normalization conflicts to the runtime consistency gate.
        report["pre_normalization_drift"] = int(report.get("drift_detected", 0) or 0)
        report["pre_normalization_conflicts"] = int(report.get("conflicts", 0) or 0)
        CONFIG["V43_STRATEGY_META"]={k:dict(v) for k,v in canonical.items()}
        report["post_normalization_conflicts"] = 0
        report["conflicts"] = 0
        report["drift_detected"] = 0
        report["modes"]=len(canonical)
        return report
    except Exception as exc:
        report["exception"]=f"{type(exc).__name__}:{exc}"
        return report

_V456_POLICY_AUDIT_REPORT = _v456_sync_strategy_policy_registries()
STATS["v456_policy_registry_modes"] = int(_V456_POLICY_AUDIT_REPORT.get("modes",0) or 0)
STATS["v456_policy_registry_conflicts"] = int(_V456_POLICY_AUDIT_REPORT.get("conflicts",0) or 0)
STATS["v515_policy_registry_drift_detected"] = int(_V456_POLICY_AUDIT_REPORT.get("drift_detected",0) or 0)
STATS["v456_policy_registry_missing"] = int(_V456_POLICY_AUDIT_REPORT.get("missing",0) or 0)
if int(_V456_POLICY_AUDIT_REPORT.get("conflicts",0) or 0) > 0:
    logger.warning("[V515-POLICY-AUDIT] canonical registry drift detected=%s; mirror ignored and regenerated details=%s",
                   _V456_POLICY_AUDIT_REPORT.get("conflicts",0),
                   _V456_POLICY_AUDIT_REPORT.get("details",[])[:8])


def _v456_policy_consistency_audit(strict: bool = True) -> Tuple[bool, Dict[str, Any]]:
    """Verify the canonical policy registry is self-consistent and complete."""
    issues=[]; checked=0
    try:
        meta=V43_STRATEGY_POLICY_META if isinstance(V43_STRATEGY_POLICY_META,dict) else {}
        required_modes=set(meta.keys())
        for mode in sorted(required_modes):
            checked += 1
            rec=meta.get(mode)
            if not isinstance(rec,dict):
                issues.append(f"missing:{mode}"); continue
            if "min_score" in rec:
                try:
                    if not math.isfinite(float(rec["min_score"])) or float(rec["min_score"]) < 0:
                        issues.append(f"invalid_min_score:{mode}")
                except Exception: issues.append(f"invalid_min_score:{mode}")
            if "min_htf_strength_non_bearish" in rec:
                try:
                    if not math.isfinite(float(rec["min_htf_strength_non_bearish"])) or not (0 <= float(rec["min_htf_strength_non_bearish"]) <= 100):
                        issues.append(f"invalid_min_htf:{mode}")
                except Exception: issues.append(f"invalid_min_htf:{mode}")
            tier=str(rec.get("min_tier","MICRO")).upper()
            if tier not in _F456_TIER_RANK:
                issues.append(f"invalid_min_tier:{mode}:{tier}")
            for key in _F456_POLICY_ALLOWED_KEYS:
                vals=_v456_normalize_allowed(rec.get(key))
                if rec.get(key) is not None and not isinstance(rec.get(key),(tuple,list,set)):
                    issues.append(f"invalid_{key}:{mode}")
                if key == "allowed_regimes" and vals:
                    if not set(vals).issubset({"BULLISH","NEUTRAL","BEARISH"}):
                        issues.append(f"invalid_regime_set:{mode}")
        ok=(not issues)
        return ok, {"checked":checked,"issues":issues[:64],"issue_count":len(issues)}
    except Exception as exc:
        return False, {"checked":checked,"issues":[f"audit_exception:{type(exc).__name__}:{exc}"],"issue_count":1}

# Re-run after all V43 metadata additions above; this is the authoritative
# startup audit used by validate_config/self-test.
_V456_POLICY_AUDIT_OK, _V456_POLICY_AUDIT_FINAL = _v456_policy_consistency_audit(strict=True)
STATS["v456_policy_audit_ok"] = bool(_V456_POLICY_AUDIT_OK)
STATS["v456_policy_audit_checked"] = int(_V456_POLICY_AUDIT_FINAL.get("checked",0) or 0)
STATS["v456_policy_audit_issue_count"] = int(_V456_POLICY_AUDIT_FINAL.get("issue_count",0) or 0)
if not _V456_POLICY_AUDIT_OK:
    logger.critical("[V456-POLICY-AUDIT] FAILED: %s", _V456_POLICY_AUDIT_FINAL)


# ---- Universe health --------------------------------------------------------
def _v455_universe_quote_eligible(quote_volume: float) -> bool:
    try:
        qv=float(quote_volume)
        min_quote=float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME",3_000_000.0))
        return math.isfinite(qv) and qv >= min_quote
    except Exception:
        return False


async def _v45_build_top_liquidity_universe(exchange, max_symbols: int = 120) -> List[str]:
    """Build a true TOP-N MEXC Spot/USDT liquidity universe.

    Ranking eligibility is deliberately separate from downstream execution
    tiers. When fetch_tickers() returns an incomplete subset, a bounded
    symbol-list fetch fallback fills the missing ticker coverage before
    declaring the universe degraded. No new symbol bypasses Spot/USDT/active
    market checks, and no downstream safety gate is relaxed here.
    """
    if not _CCXT_OK:
        raise RuntimeError("ccxt_missing")
    max_symbols = max(1, int(max_symbols))
    min_quote = float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 3_000_000))
    attempts = 1 + (int(CONFIG.get("V45_UNIVERSE_RETRY_COUNT", 1))
                    if CONFIG.get("V45_UNIVERSE_RETRY_ON_SHORTFALL", True) else 0)
    last_err = None

    def _eligible_market_symbols(markets):
        out=[]
        for sym, m in (markets or {}).items():
            try:
                if str(m.get("quote") or "").upper() != "USDT":
                    continue
                if not bool(m.get("spot", False)):
                    continue
                if m.get("active") is False:
                    continue
                out.append(sym)
            except Exception:
                continue
        return out

    for attempt in range(attempts):
        try:
            tickers = await safe_api_call(
                f"v45_universe_fetch_tickers_{attempt}",
                lambda: exchange.fetch_tickers(),
                retry_safe=True,
            )
            if not isinstance(tickers, dict):
                raise RuntimeError("universe_fetch_tickers_invalid")

            markets = getattr(exchange, "markets", {}) or {}
            eligible_markets = _eligible_market_symbols(markets)
            eligible_before = len(eligible_markets)

            def _rank_from_tickers(tk):
                candidates=[]
                for symbol, ticker in (tk or {}).items():
                    try:
                        if symbol not in markets:
                            continue
                        market=markets[symbol]
                        if str(market.get("quote") or "").upper() != "USDT":
                            continue
                        if not bool(market.get("spot", False)) or market.get("active") is False:
                            continue
                        tk = ticker or {}
                        qv = float(tk.get("quoteVolume") or 0.0)
                        if not math.isfinite(qv) or qv <= 0:
                            base_v = float(tk.get("baseVolume") or 0.0)
                            last_px = float(tk.get("last") or tk.get("close") or 0.0)
                            if math.isfinite(base_v) and math.isfinite(last_px) and base_v > 0 and last_px > 0:
                                qv = base_v * last_px
                        if not math.isfinite(qv) or qv <= max(0.0, min_quote):
                            continue
                        # ---- v4.5.3 execution-aware filter (ticker data ONLY,
                        # no orderbook fetch): keep only symbols the canonical
                        # funnel would not kill on sight --------------------
                        if CONFIG.get("V453_UNIVERSE_EXECUTION_AWARE", True):
                            # 1) liquidity tier must NOT be BELOW (these are
                            #    hard-rejected downstream as below_tier).
                            if not LiquidityTier.is_tradeable(LiquidityTier.classify(qv)):
                                STATS["v453_universe_skipped_below_tier"] = \
                                    int(STATS.get("v453_universe_skipped_below_tier", 0) or 0) + 1
                                continue
                            # 2) bounded spread sanity from the ticker itself.
                            try:
                                _b = float(tk.get("bid") or 0.0); _a = float(tk.get("ask") or 0.0)
                                if _b > 0 and _a > 0 and _a >= _b:
                                    _sp = (_a - _b) / max((_a + _b) / 2.0, 1e-12) * 100.0
                                    if math.isfinite(_sp) and _sp > float(CONFIG.get("V453_UNIVERSE_MAX_SPREAD_PCT", 0.50)):
                                        STATS["v453_universe_skipped_spread"] = \
                                            int(STATS.get("v453_universe_skipped_spread", 0) or 0) + 1
                                        continue

                                    # v4.5.99-V602 — exact canonical tier-spread
                                    # prefilter. The downstream tier-aware
                                    # spread gate remains authoritative; this
                                    # simply removes symbols that the same hard
                                    # gate would deterministically reject later.
                                    if bool(CONFIG.get("V602_TIER_SPREAD_PREFILTER_ENABLE", True)):
                                        try:
                                            _tier_for_spread = str(
                                                LiquidityTier.classify(qv) or "BELOW"
                                            ).upper()
                                            _tier_ceiling = float(
                                                (CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}).get(
                                                    _tier_for_spread,
                                                    CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15),
                                                )
                                            )
                                            if (
                                                math.isfinite(_sp)
                                                and math.isfinite(_tier_ceiling)
                                                and _tier_ceiling > 0.0
                                                and _sp > _tier_ceiling
                                            ):
                                                STATS["v602_universe_skipped_tier_spread"] = int(
                                                    STATS.get("v602_universe_skipped_tier_spread", 0) or 0
                                                ) + 1
                                                continue
                                        except Exception:
                                            # Do not invent a pass/fail outcome
                                            # from malformed tier metadata; the
                                            # canonical gate remains fail-closed.
                                            pass
                            except Exception:
                                _v647_record_suppressed_exception()
                        candidates.append((qv,symbol))
                    except Exception:
                        continue
                # v4.5.99-V601 — execution-aware universe ordering:
                # quote volume remains the primary liquidity signal, but when
                # symbols are close in liquidity the bounded spread-headroom
                # factor prefers assets that are less likely to die later at
                # the tier-aware hard spread gate. This does NOT relax the
                # ceiling and does NOT admit any symbol that fails the existing
                # universe spread sanity filter.
                if bool(CONFIG.get("V601_LIQUIDITY_HEADROOM_ORDER_ENABLE", True)):
                    def _v601_order_key(item):
                        try:
                            qv_local, sym_local = float(item[0]), str(item[1])
                            tk_local = (tk or {}).get(sym_local) or {}
                            bid_local = float(tk_local.get("bid") or 0.0)
                            ask_local = float(tk_local.get("ask") or 0.0)
                            tier_local = str(LiquidityTier.classify(qv_local) or "BELOW").upper()
                            ceil_local = float(
                                (CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}).get(
                                    tier_local,
                                    CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15),
                                )
                            )
                            if bid_local > 0 and ask_local > 0 and ask_local >= bid_local and ceil_local > 0:
                                sp_local = (ask_local - bid_local) / max((ask_local + bid_local) / 2.0, 1e-12) * 100.0
                                headroom_local = max(0.0, min(1.0, (ceil_local - sp_local) / ceil_local))
                            else:
                                headroom_local = 0.50
                            # Keep quote volume dominant: only a bounded 15%
                            # ordering tilt is permitted in close-liquidity cases.
                            tilt = _clamp(
                                float(CONFIG.get("V601_LIQUIDITY_HEADROOM_TILT_MAX_PCT", 15.0)) / 100.0,
                                0.0, 0.15
                            )
                            execution_factor = (1.0 - tilt) + tilt * headroom_local
                            return qv_local * execution_factor
                        except Exception:
                            return float(item[0] or 0.0)
                    candidates.sort(key=_v601_order_key, reverse=True)
                else:
                    candidates.sort(key=lambda x:x[0], reverse=True)
                return candidates

            candidates=_rank_from_tickers(tickers)

            # If the aggregate ticker endpoint exposes too few symbols, fetch
            # additional spot/USDT ticker coverage in bounded chunks. This is
            # still one read-only market-data phase and never touches orders.
            target=int(max_symbols)
            if len(candidates) < target and len(eligible_markets) > len(tickers):
                missing_symbols=[s for s in eligible_markets if s not in tickers]
                chunk_size=max(20,int(CONFIG.get("V45_UNIVERSE_TICKER_CHUNK_SIZE",100)))
                max_chunks=max(1,int(CONFIG.get("V45_UNIVERSE_MAX_CHUNK_FETCHES",8)))
                merged=dict(tickers)
                chunk_count=0
                for i in range(0,len(missing_symbols),chunk_size):
                    if chunk_count>=max_chunks:
                        break
                    chunk=missing_symbols[i:i+chunk_size]
                    try:
                        part=await safe_api_call(
                            f"v45_universe_fetch_chunk_{attempt}_{chunk_count}",
                            lambda chunk=chunk: exchange.fetch_tickers(chunk),
                            retry_safe=True,
                        )
                        if isinstance(part,dict) and part:
                            merged.update(part)
                            chunk_count+=1
                        else:
                            break
                    except Exception as e:
                        STATS["v45_universe_chunk_errors"]=STATS.get("v45_universe_chunk_errors",0)+1
                        logger.debug(f"[Universe-V45] chunk fetch suppressed: {e}")
                        break
                candidates=_rank_from_tickers(merged)
                STATS["v45_universe_chunk_fetches"]=STATS.get("v45_universe_chunk_fetches",0)+chunk_count

            # Last bounded fallback: individual ticker calls for a small sample
            # when the venue rejects symbol-list ticker requests.
            if len(candidates) < target:
                fallback_syms=[s for s in eligible_markets if s not in tickers][:int(CONFIG.get("V45_UNIVERSE_INDIVIDUAL_TICKER_FALLBACK",20))]
                extra=dict(tickers)
                for sym in fallback_syms:
                    try:
                        t=await safe_api_call(
                            f"v45_universe_fetch_one_{attempt}_{sym}",
                            lambda sym=sym: exchange.fetch_ticker(sym),
                            retry_safe=True,
                        )
                        if isinstance(t,dict):
                            extra[sym]=t
                    except Exception:
                        continue
                candidates=_rank_from_tickers(extra)

            # ---- v4.5.3 bounded auto-expansion (quality over quantity) ----
            # If the execution-eligible pool is too small (<100) because of
            # liquidity eligibility — NOT because of an API/data failure —
            # allow ONE bounded expansion 120->150 to complete the candidate
            # set. Never 200/300/500. If the market still lacks enough
            # execution-eligible symbols, the universe simply stays smaller;
            # BELOW-tier symbols are NEVER added just to fill the number.
            if (CONFIG.get("V453_UNIVERSE_EXPAND_ENABLE", True)
                    and len(candidates) < int(CONFIG.get("V453_UNIVERSE_EXPAND_THRESHOLD", 100))):
                _exp_key = "v453_universe_last_expand_ts"
                _last_exp = float(STATS.get(_exp_key, 0.0) or 0.0)
                _exp_target = int(CONFIG.get("V453_UNIVERSE_EXPAND_TARGET", 150))
                if (MONO_NOW() - _last_exp) >= float(CONFIG.get("V453_UNIVERSE_EXPAND_COOLDOWN_SEC", 900)):
                    STATS[_exp_key] = MONO_NOW()
                    target = min(_exp_target, max(target, _exp_target))
                    STATS["v453_universe_expansions"] = int(STATS.get("v453_universe_expansions", 0) or 0) + 1
                    logger.info(f"[Universe-V453] bounded expansion active: target->{target} "
                                f"(eligible={len(candidates)} < {int(CONFIG.get('V453_UNIVERSE_EXPAND_THRESHOLD',100))})")
            universe=[s for _,s in candidates[:target]]
            target=max(1,target)
            degraded=len(universe) < int(target*float(CONFIG.get("V45_UNIVERSE_TARGET_TOLERANCE",.80)))
            STATS["v45_universe_target"]=target
            STATS["v45_universe_eligible"]=len(candidates)
            STATS["v45_universe_eligible_market_count"]=eligible_before
            STATS["v45_universe_selected"]=len(universe)
            STATS["v45_universe_missing"]=max(0,target-len(universe))
            STATS["v45_universe_degraded"]=bool(degraded)
            STATS["v45_universe_complete"]=bool(len(universe)>=target)
            logger.info(
                f"[Universe-V45] selected={len(universe)}/{target} "
                f"eligible={len(candidates)} market_eligible={eligible_before} "
                f"attempt={attempt+1}/{attempts} degraded={degraded} "
                f"min_quote={min_quote:,.0f}"
            )
            if universe and (len(universe)>=target or not degraded or attempt==attempts-1):
                return universe
        except Exception as e:
            last_err=e
            STATS["v45_universe_refresh_error"]=STATS.get("v45_universe_refresh_error",0)+1
            logger.warning(f"[Universe-V45] attempt={attempt+1}/{attempts} failed: {e}")
    raise RuntimeError(f"v45_top_liquidity_universe_failed:{last_err}")


# Replace the legacy universe function at module load; semantics stay bounded.
build_top_liquidity_universe = _v45_build_top_liquidity_universe


# ---- ATR percentile + adaptive pullback ------------------------------------
class ATRPercentileEngine:
    @staticmethod
    def percentile(series, lookback: int = 240) -> float:
        try:
            if series is None or len(series) < 30:
                return 0.50
            s = pd.Series(series).astype(float).replace([np.inf, -np.inf], np.nan).dropna()
            if len(s) < 30:
                return 0.50
            cur = float(s.iloc[-1])
            hist = s.iloc[-min(len(s), lookback):].values
            return float(np.mean(hist <= cur))
        except Exception:
            return 0.50


def _v45_adaptive_pullback_envelope(df_5m, atr, base_atr, base_pct, base_neg_atr, relaxed=False):
    if not CONFIG.get("V45_ADAPTIVE_PULLBACK_ENABLE", True) or df_5m is None:
        return base_atr, base_pct, base_neg_atr
    try:
        c = pd.to_numeric(df_5m["close"], errors="coerce")
        h = pd.to_numeric(df_5m["high"], errors="coerce")
        l = pd.to_numeric(df_5m["low"], errors="coerce")
        prev_c = c.shift(1)
        tr = pd.concat([(h-l), (h-prev_c).abs(), (l-prev_c).abs()], axis=1).max(axis=1)
        atr_series = tr.rolling(int(CONFIG.get("ATR_PERIOD",14)), min_periods=10).mean()
        pctl = ATRPercentileEngine.percentile(atr_series)
        widen = 0.0
        if pctl >= float(CONFIG.get("V45_PULLBACK_ATR_PCTL_LOW",1.0)):
            widen = min(0.30, (pctl - 0.85) * 0.60)
        if relaxed:
            max_atr = float(CONFIG.get("V45_PULLBACK_ATR_MAX_RELAXED",3.8))
            max_pct = float(CONFIG.get("V45_PULLBACK_PCT_MAX_RELAXED",4.2))
        else:
            max_atr = float(CONFIG.get("V45_PULLBACK_ATR_MAX_STRICT",3.0))
            max_pct = float(CONFIG.get("V45_PULLBACK_PCT_MAX_STRICT",3.5))
        eff_atr = min(max_atr, float(base_atr) * (1.0 + widen))
        eff_pct = min(max_pct, float(base_pct) * (1.0 + widen))
        # Never exceed strict*1.5, even in rescue/relaxed.
        strict_base = float(CONFIG.get("PULLBACK_MAX_DISTANCE_ATR", 2.4))
        if relaxed:
            eff_atr = min(eff_atr, strict_base * 1.5)
        eff_neg = min(float(base_neg_atr), 0.90 if relaxed else 0.60)
        return eff_atr, eff_pct, eff_neg
    except Exception:
        return base_atr, base_pct, base_neg_atr


# ---- Near-miss recheck queue ------------------------------------------------
class NearMissOpportunityQueue:
    _lock = threading.RLock()
    _items: Dict[str, Dict[str, Any]] = {}

    @classmethod
    def add(cls, candidate: Dict[str, Any]) -> None:
        if not CONFIG.get("V45_NEARMISS_ENABLE", True):
            return
        try:
            symbol = str(candidate.get("symbol") or "")
            if not symbol:
                return
            score = float(candidate.get("score", 0.0))
            floor = float(candidate.get("score_floor", CONFIG.get("MIN_LIVE_SCORE",70)))
            gap = floor - score
            if gap < 0 or gap > float(CONFIG.get("V45_NEARMISS_SCORE_GAP",6.0)):
                return
            # Hard safety exclusions: these candidates must never be queued.
            # v4.5.3 — Near-Miss means "close to the score floor AFTER passing
            # hard eligibility". Any hard reject (below-tier, invalid HTF,
            # crash, bad orderbook/spread, structural invalidity, balance or
            # execution hazard) keeps the candidate OUT of the queue.
            hard = str(candidate.get("hard_reject") or "").lower()
            if hard:
                return
            _rej = str(candidate.get("reject_reason") or candidate.get("last_reject") or "").lower()
            if _rej and _rej.startswith(_V453_HARD_CATEGORY_PREFIXES):
                return
            _feats = candidate.get("features") or {}
            try:
                _t = str(_feats.get("tier") or "").upper()
                if _t == "BELOW":
                    return
            except Exception:
                return  # unverifiable tier => fail-closed, do not queue
            now = MONO_NOW()
            with cls._lock:
                same = [k for k,v in cls._items.items() if v.get("symbol")==symbol]
                max_per = int(CONFIG.get("V45_NEARMISS_MAX_PER_SYMBOL",2))
                if len(same) >= max_per:
                    return
                key = f"{symbol}|{candidate.get('candle_ts')}|{candidate.get('strategy_mode') or candidate.get('family')}"
                cls._items[key] = {
                    "symbol": symbol,
                    "created_ts": now,
                    "candle_ts": candidate.get("candle_ts"),
                    "strategy_mode": candidate.get("strategy_mode") or candidate.get("family",""),
                    "score": score,
                    "score_floor": floor,
                    "features": dict(candidate.get("features") or {}),
                }
                STATS["v45_nearmiss_added"] = STATS.get("v45_nearmiss_added",0) + 1
        except Exception:
            return

    @classmethod
    def contains(cls, symbol: str, strategy_mode: str) -> bool:
        with cls._lock:
            now=MONO_NOW()
            sm=str(strategy_mode or "").upper()
            for item in cls._items.values():
                if str(item.get("symbol") or "")==str(symbol) and str(item.get("strategy_mode") or "").upper()==sm:
                    created = float(item.get("created_ts", now) or now)
                    if now-created <= float(CONFIG.get("V45_NEARMISS_TTL_SEC",900)):
                        return True
            return False

    @classmethod
    def mark_recovered(cls, symbol: str, strategy_mode: str) -> None:
        with cls._lock:
            sm=str(strategy_mode or "").upper()
            for key,item in list(cls._items.items()):
                if str(item.get("symbol") or "")==str(symbol) and str(item.get("strategy_mode") or "").upper()==sm:
                    item["recovered"]=True
                    item["recovered_ts"]=MONO_NOW()
                    STATS["v45_nearmiss_recovered"] = STATS.get("v45_nearmiss_recovered",0)+1
                    cls._items.pop(key,None)

    @classmethod
    def expire(cls) -> None:
        now = MONO_NOW()
        ttl = float(CONFIG.get("V45_NEARMISS_TTL_SEC",900))
        with cls._lock:
            for k,v in list(cls._items.items()):
                if now - float(v.get("created_ts",0)) > ttl:
                    cls._items.pop(k,None)

    @classmethod
    def size(cls) -> int:
        cls.expire()
        with cls._lock:
            return len(cls._items)

    @classmethod
    def snapshot(cls) -> Dict[str, Any]:
        cls.expire()
        with cls._lock:
            return {"size": len(cls._items),
                    "items": list(cls._items.values())[:64]}


# ---- Session quality model --------------------------------------------------
class SessionQualityModel:
    @staticmethod
    def adjustment(strategy: str, hour_utc: int) -> float:
        if not CONFIG.get("V45_SESSION_MODEL_ENABLE", True):
            return 0.0
        try:
            samples = int(STATS.get(f"v45_session_samples.{strategy}.{hour_utc}",0) or 0)
            if samples < int(CONFIG.get("V45_SESSION_MIN_SAMPLES",12)):
                return 0.0
            r = float(STATS.get(f"v45_session_mean_r.{strategy}.{hour_utc}",0.0) or 0.0)
            cap = float(CONFIG.get("V45_SESSION_CAP_POINTS",3.0))
            return max(-cap, min(cap, r * cap))
        except Exception:
            return 0.0

    @classmethod
    def record(cls, strategy: str, hour_utc: int, realized_r: float) -> None:
        try:
            k = f"v45_session_samples.{strategy}.{hour_utc}"
            kr = f"v45_session_mean_r.{strategy}.{hour_utc}"
            n = int(STATS.get(k,0) or 0)
            old = float(STATS.get(kr,0.0) or 0.0)
            STATS[k] = n + 1
            STATS[kr] = old + (float(realized_r)-old)/float(n+1)
        except Exception:
            _v647_record_suppressed_exception()


# ---- v4.5.9 high-recall helpers -------------------------------------------
def _v459_low_target_mode(mode: str = "", family: str = "") -> bool:
    if not bool(CONFIG.get("V459_HIGH_RECALL_ENABLE", True)):
        return False
    if not bool(CONFIG.get("V459_LOW_TARGET_ENABLE", True)):
        return False
    sm = str(mode or "").upper()
    fam = str(family or "").upper()
    return sm in {str(x).upper() for x in CONFIG.get("V459_LOW_TARGET_FAMILIES", ())} or fam in {
        str(x).upper() for x in CONFIG.get("V459_LOW_TARGET_FAMILIES", ())
    }


def _v459_risk_factor_for(mode: str = "", family: str = "") -> float:
    sm = str(mode or "").upper(); fam = str(family or "").upper()
    if sm == "OPPORTUNITY_SCOUT":
        return _clamp(float(CONFIG.get("V521_SCOUT_RISK_FACTOR", 0.45)), 0.35, 1.0)
    if sm == "RELATIVE_STRENGTH_LEADER":
        return _clamp(float(CONFIG.get("V459_RS_LEADER_RISK_FACTOR", 0.60)), 0.35, 1.0)
    if sm == "VOLATILITY_BURST":
        return _clamp(float(CONFIG.get("V459_VOLATILITY_BURST_RISK_FACTOR", 0.65)), 0.35, 1.0)
    if sm in {"TREND_CONTINUATION", "MICRO_TREND_CONTINUATION"} or fam == "TREND_CONTINUATION":
        return _clamp(float(CONFIG.get("V459_TREND_RISK_FACTOR", 0.65)), 0.35, 1.0)
    return 1.0


def _v459_entry_class(mode: str = "", family: str = "") -> str:
    """Explicit opportunity class: A_STRONG vs B_HIGH_RECALL."""
    return "B_HIGH_RECALL" if _v459_low_target_mode(mode, family) else "A_STRONG"


# ---- New shadow-safe engines ------------------------------------------------
def _atr(df, period: int = 14):
    """Canonical ATR series helper; leaves closed-bar selection to callers."""
    try:
        return Indicators.atr(df, int(period)) if df is not None else None
    except Exception:
        return None


def _rs_pct_move(symbol_df, btc_df, lookback: int = 6) -> Optional[float]:
    """Relative return (decimal units) on closed bars; None means unavailable."""
    try:
        n = max(1, int(lookback))
        if symbol_df is None or btc_df is None or len(symbol_df) < n + 2 or len(btc_df) < n + 2:
            return None
        a = float(pd.to_numeric(symbol_df["close"], errors="coerce").iloc[-2])
        b = float(pd.to_numeric(symbol_df["close"], errors="coerce").iloc[-(n + 2)])
        c = float(pd.to_numeric(btc_df["close"], errors="coerce").iloc[-2])
        d = float(pd.to_numeric(btc_df["close"], errors="coerce").iloc[-(n + 2)])
        if not all(math.isfinite(x) and x > 0.0 for x in (a, b, c, d)):
            return None
        result = (a / b - 1.0) - (c / d - 1.0)
        return result if math.isfinite(result) else None
    except Exception:
        return None


def _v702_record_engine_runtime_error(engine_id: str, snapshot: Dict[str, Any], exc: Exception) -> None:
    """Count engine defects separately from valid no-signal outcomes."""
    try:
        eid = str(engine_id or "UNKNOWN")[:80]
        errors = STATS.setdefault("v702_engine_runtime_errors", {})
        if not isinstance(errors, dict):
            errors = {}
            STATS["v702_engine_runtime_errors"] = errors
        errors[eid] = int(errors.get(eid, 0) or 0) + 1
        STATS["v702_engine_runtime_last"] = {
            "engine_id": eid,
            "symbol": str((snapshot or {}).get("symbol") or "")[:64],
            "error_type": type(exc).__name__,
            "error": str(exc)[:180],
            "ts": float(WALL_NOW()),
        }
        now = float(WALL_NOW())
        throttle = STATS.setdefault("v702_engine_runtime_log_ts", {})
        last = float(throttle.get(eid, 0.0) or 0.0)
        if now - last >= 60.0:
            logger.warning("[ENGINE-RUNTIME] %s symbol=%s error=%s: %s", eid,
                           str((snapshot or {}).get("symbol") or ""), type(exc).__name__, exc)
            throttle[eid] = now
    except Exception:
        pass


class VolatilityBurstEngine(_EngineBase):
    engine_id = "volatility_burst_v45"
    strategy_mode = "VOLATILITY_BURST"
    family_map = ("VOLATILITY_BURST",)
    priority = 4

    @classmethod
    def _config_enabled(cls) -> bool:
        return bool(CONFIG.get("V45_VOLATILITY_BURST_ENABLE", True)) and bool(CONFIG.get("V459_VOLATILITY_BURST_LIVE_ENABLE", True))

    @classmethod
    def generate(cls, snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        if not CONFIG.get("V45_VOLATILITY_BURST_ENABLE", True) or not CONFIG.get("V459_VOLATILITY_BURST_LIVE_ENABLE", True):
            return []
        try:
            df5 = snapshot.get("df_5m"); df15 = snapshot.get("df_15m")
            if df5 is None or df15 is None or len(df5)<80 or len(df15)<40:
                return []
            c = pd.to_numeric(df5["close"], errors="coerce")
            h = pd.to_numeric(df5["high"], errors="coerce")
            l = pd.to_numeric(df5["low"], errors="coerce")
            o = pd.to_numeric(df5["open"], errors="coerce")
            v = pd.to_numeric(df5["volume"], errors="coerce")
            prev_c = c.shift(1)
            tr = pd.concat([(h-l),(h-prev_c).abs(),(l-prev_c).abs()],axis=1).max(axis=1)
            atr = tr.rolling(14,min_periods=14).mean()
            cur_atr = float(atr.iloc[-2]); prev_atr = float(atr.iloc[-10])
            if not (math.isfinite(cur_atr) and math.isfinite(prev_atr) and prev_atr>0):
                return []
            atr_ratio = cur_atr/prev_atr
            vol_mean = float(v.iloc[-22:-2].mean())
            vol_ratio = float(v.iloc[-2]/vol_mean) if vol_mean>0 else 0.0
            body = abs(float(c.iloc[-2])-float(o.iloc[-2]))
            rng = max(float(h.iloc[-2])-float(l.iloc[-2]),1e-12)
            body_ratio = body/rng
            prior_high = float(h.iloc[-12:-2].max())
            close = float(c.iloc[-2])
            if close <= prior_high:
                return []
            chase_atr = max(0.0, (close-prior_high)/max(cur_atr,1e-12))
            if atr_ratio < float(CONFIG.get("V45_VOLATILITY_BURST_MIN_ATR_RATIO",1.35)):
                return []
            if vol_ratio < float(CONFIG.get("V45_VOLATILITY_BURST_MIN_VOLUME_RATIO",1.25)):
                return []
            if body_ratio < 0.45:
                return []
            if chase_atr > float(CONFIG.get("V45_VOLATILITY_BURST_MAX_CHASE_ATR",1.10)):
                return []
            entry = close
            sl = float(c.iloc[-6:-2].min())
            risk = entry-sl
            if not math.isfinite(risk) or risk<=0:
                return []
            target_rr = float(StrategyExitProfiles.profile_for(cls.strategy_mode, "SCALP").tp2_rr)
            _rs5 = _rs_pct_move(df5, snapshot.get("df_btc_5m"), 6)
            _rs15 = _rs_pct_move(df15, snapshot.get("df_btc_15m"), 6)
            if _rs5 is None or _rs15 is None:
                STATS["v702_volatility_burst_rs_unavailable"] = int(STATS.get("v702_volatility_burst_rs_unavailable", 0) or 0) + 1
                return []
            rs5, rs15 = float(_rs5), float(_rs15)
            if rs5 < -0.002 and rs15 < -0.002:
                return []
            feats = {
                "hard_valid": True, "strategy_mode": cls.strategy_mode,
                "market_phase": "EXPANSION", "volume_ratio": vol_ratio,
                "atr_expansion_ratio": atr_ratio, "body_ratio": body_ratio,
                "chase_atr": chase_atr, "target_rr": target_rr,
                "rr_ratio": target_rr, "rs_5m": rs5, "rs_15m": rs15,
                "rs_quality": _clamp(0.5+(rs5+rs15)*30.0,0,1),
                "volume_quality": _clamp(vol_ratio/2.0,0,1),
                "structure_quality": _clamp(body_ratio,0,1),
                "phase_fit": 0.95, "local_fit": 0.85,
                "htf_alignment": _clamp(float(snapshot.get("htf_strength",55.0))/100.0,0,1),
            }
            score = _clamp(
                0.28*min(1.0,atr_ratio/1.6)+0.20*min(1.0,vol_ratio/2.0)+
                0.16*body_ratio+0.18*feats["rs_quality"]+0.18*feats["htf_alignment"],0,1)
            if score < float(CONFIG.get("V45_VOLATILITY_BURST_MIN_SCORE",.68)):
                return []
            _ep_hr = StrategyExitProfiles.profile_for(cls.strategy_mode, "SCALP")
            cnd = StrategyCandidate(
                engine_id=cls.engine_id, symbol=snapshot["symbol"], side="long",
                generated_at_ms=int(WALL_NOW()*1000), entry_ref=entry, sl_price=sl,
                tp1_rr=float(_ep_hr.tp1_rr), tp2_rr=float(_ep_hr.tp2_rr),
                tp3_rr=float(_ep_hr.tp3_rr), engine_score=score, rr_ratio=target_rr,
                liquidity_score=_clamp(float(snapshot.get("liquidity_score",0.7)),0,1),
                regime_fit=_clamp(float(snapshot.get("regime_fit",0.7)),0,1),
                family="VOLATILITY_BURST", zone_ref=prior_high, features_snapshot={**feats, "breakout_ref": prior_high},
                strategy_mode=cls.strategy_mode, strategy_style="SCALP",
                market_phase="EXPANSION", macro_regime=str(snapshot.get("macro_regime","")),
                local_regime=str(snapshot.get("local_regime","")),
                bearish_severity=str(snapshot.get("bearish_severity","")),
                timeframe_profile="5M_15M", quality_grade="B")
            STATS["v45_volatility_burst_generated"] = STATS.get("v45_volatility_burst_generated",0)+1
            return [cnd]
        except Exception as _engine_exc:
            _v702_record_engine_runtime_error("volatility_burst_v45", snapshot, _engine_exc)
            return []


class RelativeStrengthLeaderEngine(_EngineBase):
    engine_id = "relative_strength_leader_v45"
    strategy_mode = "RELATIVE_STRENGTH_LEADER"
    family_map = ("RELATIVE_STRENGTH",)
    priority = 4

    @classmethod
    def _config_enabled(cls) -> bool:
        return bool(CONFIG.get("V45_RS_LEADER_ENABLE", True)) and bool(CONFIG.get("V459_RS_LEADER_LIVE_ENABLE", True))

    @classmethod
    def generate(cls, snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        if not CONFIG.get("V45_RS_LEADER_ENABLE", True) or not CONFIG.get("V459_RS_LEADER_LIVE_ENABLE", True):
            return []
        try:
            df5, df15 = snapshot.get("df_5m"), snapshot.get("df_15m")
            btc5, btc15 = snapshot.get("df_btc_5m"), snapshot.get("df_btc_15m")
            if any(x is None for x in (df5,df15,btc5,btc15)):
                return []
            _rs5 = _rs_pct_move(df5, btc5, 6)
            _rs15 = _rs_pct_move(df15, btc15, 6)
            if _rs5 is None or _rs15 is None:
                STATS["v702_rs_leader_rs_unavailable"] = int(STATS.get("v702_rs_leader_rs_unavailable", 0) or 0) + 1
                return []
            rs5, rs15 = float(_rs5), float(_rs15)
            if rs5 < float(CONFIG.get("V45_RS_LEADER_MIN_RS_5M",0.003)) or rs15 < float(CONFIG.get("V45_RS_LEADER_MIN_RS_15M",0.003)):
                return []
            r = pd.to_numeric(df5["close"],errors="coerce")
            ema20 = r.ewm(span=20,adjust=False).mean()
            persistence = float(np.mean((r.iloc[-22:-2].values > ema20.iloc[-22:-2].values).astype(float)))
            vol = pd.to_numeric(df5["volume"],errors="coerce")
            vol_ratio = float(vol.iloc[-2]/max(vol.iloc[-22:-2].mean(),1e-12))
            if persistence < float(CONFIG.get("V45_RS_LEADER_MIN_PERSISTENCE",.55)):
                return []
            if vol_ratio < float(CONFIG.get("V45_RS_LEADER_MIN_VOLUME_RATIO",1.10)):
                return []
            close = float(r.iloc[-2])
            # 15m trend confirmation, closed bars only.
            c15 = pd.to_numeric(df15["close"],errors="coerce")
            e20 = c15.ewm(span=20,adjust=False).mean()
            e50 = c15.ewm(span=50,adjust=False).mean()
            if not (close > float(e20.iloc[-2]) > float(e50.iloc[-2])):
                return []
            atr = _atr(df5, int(CONFIG.get("ATR_PERIOD",14)))
            atrv = float(atr.iloc[-2])
            ema20_5 = ema20.iloc[-2]
            slope = float((ema20.iloc[-2]-ema20.iloc[-7])/max(atrv,1e-12))
            if slope <= 0:
                return []
            prior_high = float(pd.to_numeric(df5["high"],errors="coerce").iloc[-12:-2].max())
            chase = max(0.0,(close-prior_high)/max(atrv,1e-12))
            if chase > float(CONFIG.get("V45_RS_LEADER_MAX_CHASE_ATR",1.3)):
                return []
            sl = float(pd.to_numeric(df5["low"],errors="coerce").iloc[-6:-2].min())
            risk = close-sl
            if risk <= 0:
                return []
            feats={
                "hard_valid":True,"strategy_mode":cls.strategy_mode,"market_phase":"TREND",
                "rs_5m":rs5,"rs_15m":rs15,"rs_persistence":persistence,
                "rs_quality":_clamp(.5+(rs5+rs15)*25,0,1),
                "volume_ratio":vol_ratio,"volume_quality":_clamp(vol_ratio/1.8,0,1),
                "structure_quality":_clamp(.55+.15*min(1.0,slope),0,1),
                "phase_fit":.92,"local_fit":.95,"chase_atr":chase,
                "target_rr":float(StrategyExitProfiles.profile_for(cls.strategy_mode, "SCALP").tp2_rr),
                "htf_alignment":_clamp(float(snapshot.get("htf_strength",55.0))/100,0,1)}
            score=_clamp(
                .26*feats["rs_quality"]+.20*feats["volume_quality"]+
                .18*feats["structure_quality"]+.18*feats["phase_fit"]+
                .18*feats["htf_alignment"],0,1)
            if score < float(CONFIG.get("V45_RS_LEADER_MIN_SCORE",.67)):
                return []
            _ep_hr = StrategyExitProfiles.profile_for(cls.strategy_mode, "SCALP")
            cnd=StrategyCandidate(
                engine_id=cls.engine_id,symbol=snapshot["symbol"],side="long",
                generated_at_ms=int(WALL_NOW()*1000),entry_ref=close,sl_price=sl,
                tp1_rr=float(_ep_hr.tp1_rr),tp2_rr=float(_ep_hr.tp2_rr),tp3_rr=float(_ep_hr.tp3_rr),
                engine_score=score,rr_ratio=float(_ep_hr.tp1_rr),
                liquidity_score=_clamp(float(snapshot.get("liquidity_score",.7)),0,1),
                regime_fit=_clamp(float(snapshot.get("regime_fit",.7)),0,1),
                family="RELATIVE_STRENGTH",zone_ref=close,features_snapshot=feats,
                strategy_mode=cls.strategy_mode,strategy_style="SCALP",market_phase="TREND",
                macro_regime=str(snapshot.get("macro_regime","")),local_regime=str(snapshot.get("local_regime","")),
                bearish_severity=str(snapshot.get("bearish_severity","")),timeframe_profile="5M_15M_1H",quality_grade="B")
            STATS["v45_rs_leader_generated"]=STATS.get("v45_rs_leader_generated",0)+1
            return [cnd]
        except Exception as _engine_exc:
            _v702_record_engine_runtime_error("relative_strength_leader_v45", snapshot, _engine_exc)
            return []


class MicroTrendContinuationEngine(_EngineBase):
    family_map = ("TREND_CONTINUATION",)
    """v4.5.9 high-recall micro-trend lane.

    Closed-bar only; deliberately simple: bullish stack, higher closes /
    higher-low persistence, adequate volume, bounded chase, and valid HTF.
    It never bypasses the canonical TREND_CONTINUATION safety path.
    """
    engine_id = "micro_trend_cont_v459"
    strategy_mode = "MICRO_TREND_CONTINUATION"
    priority = 5

    @classmethod
    def _config_enabled(cls) -> bool:
        return bool(CONFIG.get("V459_HIGH_RECALL_ENABLE", True)) and bool(CONFIG.get("V459_MICRO_TREND_ENABLE", True))

    @classmethod
    def generate(cls, snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        if not cls._config_enabled():
            return []
        try:
            d5, d15 = snapshot.get("df_5m"), snapshot.get("df_15m")
            if d5 is None or d15 is None or len(d5) < 40 or len(d15) < 80:
                return []
            c5 = pd.to_numeric(d5["close"], errors="coerce")
            o5 = pd.to_numeric(d5["open"], errors="coerce")
            h5 = pd.to_numeric(d5["high"], errors="coerce")
            l5 = pd.to_numeric(d5["low"], errors="coerce")
            v5 = pd.to_numeric(d5["volume"], errors="coerce")
            e20_15 = d15["close"].ewm(span=20, adjust=False).mean()
            e50_15 = d15["close"].ewm(span=50, adjust=False).mean()
            p15 = float(d15["close"].iloc[-2])
            e20 = float(e20_15.iloc[-2]); e50 = float(e50_15.iloc[-2])
            if not all(math.isfinite(x) for x in (p15,e20,e50)) or not (p15 > e20 > e50):
                return []
            atr = _atr(d5, int(CONFIG.get("ATR_PERIOD",14)))
            atrv = float(atr.iloc[-2])
            close = float(c5.iloc[-2]); open_ = float(o5.iloc[-2])
            if not all(math.isfinite(x) for x in (atrv,close,open_)) or atrv <= 0 or close <= 0:
                return []

            # Last closed bars: higher closes AND at least one higher low chain.
            pers_n = max(2, int(CONFIG.get("V459_MICRO_TREND_MIN_PERSISTENCE_BARS",2)))
            closes = [float(c5.iloc[-2-i]) for i in range(pers_n+1)]
            highs = [float(h5.iloc[-2-i]) for i in range(pers_n+1)]
            lows = [float(l5.iloc[-2-i]) for i in range(pers_n+1)]
            higher_closes = all(closes[i] > closes[i+1] for i in range(pers_n))
            higher_lows = all(lows[i] >= lows[i+1] for i in range(pers_n))
            bullish_last = close > open_

            vavg = float(v5.iloc[-22:-2].mean())
            vol_ratio = float(v5.iloc[-2] / vavg) if vavg > 0 else 0.0
            if vol_ratio < float(CONFIG.get("V459_MICRO_TREND_MIN_VOLUME_RATIO",0.85)):
                return []

            rsi = Indicators.rsi(c5, int(CONFIG.get("RSI_PERIOD",14)))
            rsi_v = float(rsi.iloc[-2]) if rsi is not None else float("nan")
            if not math.isfinite(rsi_v) or not (float(CONFIG.get("V459_MICRO_TREND_MIN_RSI",45.0)) <= rsi_v <= float(CONFIG.get("V459_MICRO_TREND_MAX_RSI",70.0))):
                return []

            prior_high = float(h5.iloc[-12:-2].max())
            chase = max(0.0, (close-prior_high)/max(atrv,1e-12))
            if chase > float(CONFIG.get("V459_MICRO_TREND_MAX_CHASE_ATR",1.15)):
                return []
            slope_atr = (e20 - float(e20_15.iloc[-7])) / max(atrv,1e-12)
            if slope_atr <= 0:
                return []

            # HTF remains a real gate; no bearish countertrend bypass here.
            htf_strength = float(snapshot.get("htf_strength",0.0) or 0.0)
            if htf_strength < float(CONFIG.get("V459_MICRO_TREND_MIN_HTF",52.0)):
                return []

            trend_q = _clamp(0.55 + 0.15*min(1.0,slope_atr) + 0.10*(1.0 if higher_lows else 0.0),0,1)
            pers_q = 1.0 if higher_closes else (0.65 if bullish_last and higher_lows else 0.0)
            rs = compute_relative_strength(d5, snapshot.get("df_btc_5m"), d15, snapshot.get("df_btc_15m"),
                                           snapshot.get("df_1h"), snapshot.get("df_btc_1h"), 6, 6)
            rs5 = float(rs.get("rs_5m") or 0.0)
            rs15 = float(rs.get("rs_15m") or 0.0)
            score = _clamp(0.32*trend_q + 0.22*pers_q + 0.18*_clamp(vol_ratio/1.5,0,1) +
                           0.14*_clamp((rsi_v-45.0)/25.0,0,1) + 0.08*_clamp(1.0-chase/max(1.15,1e-9),0,1) +
                           0.06*_clamp(0.5+(rs5+rs15)*25.0,0,1),0,1)
            if score < float(CONFIG.get("V459_MICRO_TREND_MIN_SCORE",0.62)):
                return []

            sl = min(float(l5.iloc[-2]), float(l5.iloc[-3])) - 0.10*atrv
            risk = close-sl
            if not math.isfinite(risk) or risk <= 0:
                return []
            feats = {
                "hard_valid": True, "strategy_mode": cls.strategy_mode,
                "market_phase": "TREND", "volume_ratio": vol_ratio,
                "volume_quality": _clamp(vol_ratio/1.5,0,1),
                "structure_quality": trend_q, "phase_fit": 0.90, "local_fit": 0.95,
                "retest_quality": 0.65, "rs_5m": rs5, "rs_15m": rs15,
                "rs_persistence": float(rs.get("rs_persistence") or 0.0),
                "rs_quality": _clamp(0.5+(rs5+rs15)*25.0,0,1),
                "chase_atr": chase, "target_rr": 1.80, "rr_ratio": 0.90,
                "htf_alignment": _clamp(htf_strength/100.0,0,1),
                "higher_closes": higher_closes, "higher_lows": higher_lows,
                "rsi": rsi_v, "slope_atr": slope_atr,
            }
            _ep_hr = StrategyExitProfiles.profile_for(cls.strategy_mode, "SCALP")
            return [StrategyCandidate(
                engine_id=cls.engine_id, symbol=snapshot["symbol"], side="long",
                generated_at_ms=int(WALL_NOW()*1000), entry_ref=close, sl_price=sl,
                tp1_rr=float(_ep_hr.tp1_rr), tp2_rr=float(_ep_hr.tp2_rr), tp3_rr=float(_ep_hr.tp3_rr),
                engine_score=score, rr_ratio=0.90,
                liquidity_score=_clamp(float(snapshot.get("liquidity_score",0.7)),0,1),
                regime_fit=_clamp(float(snapshot.get("regime_fit",0.7)),0,1),
                family="TREND_CONTINUATION", zone_ref=e20, features_snapshot=feats,
                strategy_mode="MICRO_TREND_CONTINUATION", strategy_style="SCALP",
                market_phase="TREND", macro_regime=str(snapshot.get("macro_regime",snapshot.get("regime",""))),
                local_regime=str(snapshot.get("local_regime","")),
                bearish_severity=str(snapshot.get("bearish_severity","")),
                timeframe_profile="15M_5M", quality_grade="B")
            ]
        except Exception as _engine_exc:
            _v702_record_engine_runtime_error("micro_trend_cont_v459", snapshot, _engine_exc)
            return []




class OpportunityScoutEngine(_EngineBase):
    """v4.5.21 bounded real-time opportunity lane.

    Signal evidence is closed-bar only; execution still uses the live price and
    canonical order-book/PreSend gates. The lane is intentionally small-risk
    and short-target, and never submits orders itself.
    """
    engine_id = "opportunity_scout_v521"
    strategy_mode = "OPPORTUNITY_SCOUT"
    priority = 6
    family_map = ("OPPORTUNITY_SCOUT",)

    @classmethod
    def _config_enabled(cls) -> bool:
        return (bool(CONFIG.get("V521_SCOUT_ENABLE", True))
                and bool(CONFIG.get("V45_OPPORTUNITY_BRAIN_ENABLE", True))
                and bool(CONFIG.get("V459_HIGH_RECALL_ENABLE", True)))

    @classmethod
    def generate(cls, snapshot: Dict[str, Any]) -> List[StrategyCandidate]:
        if not cls._config_enabled():
            return []
        try:
            symbol = str(snapshot.get("symbol") or "")
            d5 = snapshot.get("df_5m")
            d15 = snapshot.get("df_15m")
            d1 = snapshot.get("df_1h")
            d4 = snapshot.get("df_4h")
            btc5 = snapshot.get("df_btc_5m")
            if not _PDNP_OK or any(x is None for x in (d5, d15, d1, d4, btc5)):
                return []
            if min(len(d5), len(d15), len(d1), len(d4), len(btc5)) < 60:
                return []
            tier = str(snapshot.get("tier") or "").upper()
            order = {"BELOW":0, "MID":1, "LARGE":2, "MAJOR":3}
            if order.get(tier, -1) < order.get(str(CONFIG.get("V521_SCOUT_MIN_TIER","MID")).upper(),1):
                return []

            c5 = float(d5["close"].iloc[-2]); o5 = float(d5["open"].iloc[-2])
            h5 = float(d5["high"].iloc[-2]); l5 = float(d5["low"].iloc[-2])
            atr5s = Indicators.atr(d5, int(CONFIG.get("ATR_PERIOD",14)))
            if atr5s is None:
                return []
            atr5 = float(atr5s.iloc[-2])
            if not math.isfinite(atr5) or atr5 <= 0:
                return []
            body = abs(c5-o5); rng = max(h5-l5, 1e-9)
            body_ratio = body/rng
            if c5 <= o5 or body_ratio < float(CONFIG.get("V521_SCOUT_MIN_BODY_RATIO",0.25)):
                return []

            ema20_5 = Indicators.ema(d5["close"], int(CONFIG["EMA_FAST"]))
            ema50_5 = Indicators.ema(d5["close"], int(CONFIG["EMA_MID"]))
            ema20_15 = Indicators.ema(d15["close"], int(CONFIG["EMA_FAST"]))
            ema50_15 = Indicators.ema(d15["close"], int(CONFIG["EMA_MID"]))
            e20_5=float(ema20_5.iloc[-2]); e50_5=float(ema50_5.iloc[-2])
            e20_15=float(ema20_15.iloc[-2]); e50_15=float(ema50_15.iloc[-2])
            if not (c5 > e20_5 > e50_5):
                return []
            c15=float(d15["close"].iloc[-2])
            if not (c15 > e20_15 > e50_15):
                return []

            vr = _v43_closed_features(d5, "5m")
            if vr is None or vr.get("volume_ratio") is None:
                return []
            volume_ratio=float(vr["volume_ratio"])
            if volume_ratio < float(CONFIG.get("V521_SCOUT_MIN_5M_VOLUME_RATIO",0.85)):
                return []
            rsi=float(vr.get("rsi", 50.0) or 50.0)
            if not (float(CONFIG.get("V521_SCOUT_MIN_RSI",45.0)) <= rsi <= float(CONFIG.get("V521_SCOUT_MAX_RSI",72.0))):
                return []

            nper=max(2,int(CONFIG.get("V521_SCOUT_MIN_PERSISTENCE_BARS",3)))
            closes=d5["close"].iloc[-(nper+2):-1].astype(float).tolist()
            if len(closes) < nper or any(closes[i] <= closes[i-1] for i in range(1,len(closes))):
                return []
            chase=max(0.0,(c5-e20_5)/max(atr5,1e-9))
            if chase > float(CONFIG.get("V521_SCOUT_MAX_CHASE_ATR",1.20)):
                return []

            _rs_ctx = compute_relative_strength(
                d5, btc5, d15, snapshot.get("df_btc_15m"),
                d1, snapshot.get("df_btc_1h"),
                lookback_5m=12, lookback_15m=12)
            rs5 = _rs_ctx.get("rs_5m") if isinstance(_rs_ctx, dict) else None
            if rs5 is None or not math.isfinite(float(rs5)):
                return []
            rs5=float(rs5)
            if rs5 < float(CONFIG.get("V521_SCOUT_MIN_RS_5M",0.0010)):
                return []

            htf_strength=float(snapshot.get("htf_strength") or 0.0)
            if not math.isfinite(htf_strength) or htf_strength < float(CONFIG.get("V521_SCOUT_MIN_HTF_STRENGTH",48.0)):
                return []

            rs_quality=_clamp(0.50 + rs5*30.0,0.0,1.0)
            vol_quality=_clamp(volume_ratio/1.5,0.0,1.0)
            struct_quality=_clamp(0.55 + 0.20*min(1.0,(c5-e20_5)/max(atr5,1e-9)),0.0,1.0)
            trend_quality=_clamp(0.50 + 0.25*min(1.0,(c15-e20_15)/max(float(Indicators.atr(d15,int(CONFIG.get("ATR_PERIOD",14))).iloc[-2]),1e-9)),0.0,1.0)
            phase_fit=float(snapshot.get("regime_fit",0.70) or 0.70)
            score=_clamp(0.24*rs_quality + 0.22*vol_quality + 0.24*struct_quality + 0.16*trend_quality + 0.14*_clamp(htf_strength/100.0,0.0,1.0),0.0,1.0)
            if score < float(CONFIG.get("V521_SCOUT_MIN_SCORE",0.49)):
                return []

            sl=c5-float(CONFIG.get("ATR_SL_MULT",1.2))*atr5
            if not (math.isfinite(sl) and sl < c5):
                return []
            ep=StrategyExitProfiles.profile_for("OPPORTUNITY_SCOUT","SCALP")
            feats={
                "hard_valid": True,
                "strategy_mode":"OPPORTUNITY_SCOUT",
                "strategy_style":"SCALP",
                "macro_regime":str(snapshot.get("macro_regime",snapshot.get("regime",""))),
                "local_regime":str(snapshot.get("local_regime","")),
                "market_phase":str((snapshot.get("market_phase") or {}).get("phase", snapshot.get("market_phase","TREND"))),
                "bearish_severity":str(snapshot.get("bearish_severity","NORMAL")),
                "structure_quality":struct_quality,
                "volume_quality":vol_quality,
                "retest_quality":0.70,
                "phase_fit":_clamp(phase_fit,0.0,1.0),
                "local_fit":0.85,
                "rs_5m":rs5,
                "rs_quality":rs_quality,
                "volume_ratio":volume_ratio,
                "chase_atr":chase,
                "htf_alignment":_clamp(htf_strength/100.0,0.0,1.0),
                "target_rr":float(ep.tp2_rr),
                "execution_quality":0.80,
                "exit_profile":asdict(ep),
                "v521_scout":True,
            }
            cnd=StrategyCandidate(
                engine_id=cls.engine_id,symbol=symbol,side="long",
                generated_at_ms=int(WALL_NOW()*1000),entry_ref=c5,sl_price=sl,
                tp1_rr=float(ep.tp1_rr),tp2_rr=float(ep.tp2_rr),tp3_rr=float(ep.tp3_rr),
                engine_score=score,rr_ratio=float(ep.tp1_rr),
                liquidity_score=_clamp(float(snapshot.get("liquidity_score",0.75) or 0.75),0.0,1.0),
                regime_fit=_clamp(float(snapshot.get("regime_fit",0.75) or 0.75),0.0,1.0),
                family="OPPORTUNITY_SCOUT",zone_ref=e20_5,features_snapshot=feats,
                strategy_mode=cls.strategy_mode,strategy_style="SCALP",
                market_phase=str(feats["market_phase"]),
                macro_regime=feats["macro_regime"],local_regime=feats["local_regime"],
                bearish_severity=feats["bearish_severity"],timeframe_profile="15M_5M",quality_grade="B")
            STATS["v521_scout_generated"]=int(STATS.get("v521_scout_generated",0) or 0)+1
            return [cnd]
        except Exception as exc:
            STATS["v521_scout_errors"]=int(STATS.get("v521_scout_errors",0) or 0)+1
            logger.debug(f"[V521][SCOUT] isolated exception: {exc}")
            return []

try:
    _MSE_ENGINES = tuple(list(_MSE_ENGINES) + [VolatilityBurstEngine, RelativeStrengthLeaderEngine])
    if bool(CONFIG.get("V459_HIGH_RECALL_ENABLE", True)):
        _MSE_ENGINES = tuple(list(_MSE_ENGINES) + [MicroTrendContinuationEngine])
    if bool(CONFIG.get("V521_SCOUT_ENABLE", True)):
        _MSE_ENGINES = tuple(list(_MSE_ENGINES) + [OpportunityScoutEngine])
except Exception:
    _v647_record_suppressed_exception()


# ---- Tier-aware micro hard protections / orderbook confirmation -------------
def _v45_orderbook_confirmation(orderbook: Any, opp: Dict[str, Any], tier: str) -> Tuple[bool, str]:
    if not CONFIG.get("V45_ORDERBOOK_CONFIRM_ENABLE", True):
        return True, "disabled"
    try:
        t = str(tier or "").upper()
        if not isinstance(orderbook, dict):
            return False, "orderbook_missing"
        bids = orderbook.get("bids") or []; asks = orderbook.get("asks") or []
        if not bids or not asks:
            return False, "orderbook_empty"
        bidv = sum(float(x[1]) for x in bids[:5] if len(x)>=2)
        askv = sum(float(x[1]) for x in asks[:5] if len(x)>=2)
        imb = bidv/max(bidv+askv,1e-12)
        spread = float(opp.get("spread_pct", 0.0) or 0.0)
        _req = max(float(CONFIG.get("MIN_POSITION_SIZE_USDT",15.0)),
                   min(float(CONFIG.get("MAX_POSITION_SIZE_USDT",80.0)),
                       float(CONFIG.get("FIXED_POSITION_SIZE_USDT",80.0))))
        _bid_notional = sum(float(x[0])*float(x[1]) for x in bids[:5] if len(x)>=2)
        _ask_notional = sum(float(x[0])*float(x[1]) for x in asks[:5] if len(x)>=2)
        depth = float(opp.get("depth_ratio", 0.0) or 0.0)
        if depth <= 0.0:
            depth = _bid_notional / max(_req,1e-9)
        volr = float(opp.get("volume_ratio", 0.0) or 0.0)
        struct = float(opp.get("structure_confidence", opp.get("structure_quality",50.0)) or 0.0)
        if t == "MICRO":
            if spread > float(CONFIG.get("V45_TIER_MICRO_MAX_SPREAD_PCT",.30)): return False,"micro_spread"
            if depth < float(CONFIG.get("V45_TIER_MICRO_MIN_DEPTH_RATIO",1.90)): return False,"micro_depth"
            if volr < float(CONFIG.get("V45_TIER_MICRO_MIN_VOL_RATIO",.95)): return False,"micro_volume"
            if float(opp.get("chase_atr",0.0) or 0.0) > float(CONFIG.get("V45_TIER_MICRO_MAX_CHASE_ATR",1.15)): return False,"micro_chase"
            if imb < .58: return False,"micro_imbalance"
            if struct < 55: return False,"micro_structure"
        else:
            if imb < .62 or struct < 50: return False,"imbalance_or_structure"
        return True, f"imbalance={imb:.3f}"
    except Exception:
        return False, "orderbook_confirmation_error"


# ---- Strategy-aware L3 rescue policy ---------------------------------------
def _v45_strategy_rescue_allowed(strategy_mode: str, family: str = "") -> bool:
    sm = str(strategy_mode or family or "").upper()
    return sm in set(str(x).upper() for x in CONFIG.get("V45_RESCUE_L3_FAMILIES",()))


def _v45_rescue_level() -> int:
    try:
        until = float(getattr(_V420State,"rescue_until_ts",0.0) or 0.0)
        lvl = int(getattr(_V420State,"rescue_level",0) or 0)
        if lvl and MONO_NOW() < until:
            return lvl
        if lvl:
            _V420State.rescue_level = 0
            _V420State.rescue_until_ts = 0.0
        return 0
    except Exception:
        return 0


def _v45_activate_rescue(level: int, reason: str) -> None:
    level = max(0,min(3,int(level)))
    now = MONO_NOW()
    if level <= 0:
        return
    cooldown = float(CONFIG.get("V45_RESCUE_COOLDOWN_SEC",300))
    last = float(getattr(_V420State,"rescue_last_activation_ts",0.0) or 0.0)
    if now-last < cooldown and level <= int(getattr(_V420State,"rescue_level",0) or 0):
        return
    ttl = {1: float(CONFIG.get("V45_RESCUE_L1_TTL_SEC",600)),
           2: float(CONFIG.get("V45_RESCUE_L2_TTL_SEC",300)),
           3: float(CONFIG.get("V45_RESCUE_L3_TTL_SEC",180))}.get(level,300)
    _V420State.rescue_level = level
    _V420State.rescue_until_ts = now + ttl
    _V420State.rescue_last_activation_ts = now
    STATS["v45_rescue_activations"] = STATS.get("v45_rescue_activations",0)+1
    STATS["v45_rescue_level"] = level
    STATS["v45_rescue_reason"] = reason
    # Preserve legacy detector relaxed timestamp as an L1 compatibility path.
    if level >= 1:
        _V420State.relaxed_mode_until_ts = max(float(_V420State.relaxed_mode_until_ts or 0), now + ttl)
    logger.warning(f"[V45-Rescue] level=L{level} reason={reason} ttl={ttl:.0f}s")


# Dynamic state fields on the existing V420 state bag.
for _name, _default in (("rescue_level",0),("rescue_until_ts",0.0),("rescue_last_activation_ts",0.0),("v606_l1_zero_cycles",0)):
    if not hasattr(_V420State,_name):
        setattr(_V420State,_name,_default)


# Replace watchdog behavior with the bounded 3-level rescue ladder.
def _v45_watchdog_tick(cls):
    if not CONFIG.get("V420_FUNNEL_WATCHDOG_ENABLE", True) or not CONFIG.get("V45_RESCUE_ENABLE", True):
        return
    now=MONO_NOW()
    iv=float(CONFIG.get("V420_FUNNEL_CHECK_INTERVAL_SEC",60))
    if now-float(getattr(cls,"_last_check_ts",0.0)) < iv:
        return
    cls._last_check_ts=now
    STATS["watchdog_ticks"]=STATS.get("watchdog_ticks",0)+1
    window=float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN",5))*60
    rate,g,e,s=_V420State.recall_rate(window)
    nfm=_V420State.nfm_count(window)
    # Numerator and denominator are read from the same monotonic V420 event
    # histories and the same watchdog window. Diagnostic/rescue telemetry only.
    ratio=(nfm/float(g)) if g else 0.0
    STATS["v425_nfm_ratio"]=round(ratio,4); STATS["v425_nfm_window_count"]=nfm
    STATS["v679_nfm_ratio_denominator_g"]=int(g)
    STATS["v679_nfm_ratio_source"]="V420_SAME_MONOTONIC_WINDOW"
    zero_send = s == 0
    min_nfm=int(CONFIG.get("V420_STARV_NFM_RATIO_MIN_COUNT",25))
    primary=(g>=int(CONFIG.get("V420_FUNNEL_STARV_THRESHOLD",60)) and zero_send)
    nfm_trigger=(ratio>=float(CONFIG.get("V420_STARV_NFM_RATIO_TRIGGER",.20)) and nfm>=min_nfm and e==0 and zero_send and g>=min_nfm)
    current=_v45_rescue_level()
    if zero_send and (primary or nfm_trigger):
        elapsed=float(getattr(cls,"_last_check_ts",now))-float(getattr(_V420State,"rescue_last_activation_ts",0.0) or 0.0)
        if elapsed < float(CONFIG.get("V45_RESCUE_MIN_DURATION_SEC",60)) and current:
            lvl=current
        elif e==0 and g>=int(CONFIG.get("V420_FUNNEL_STARV_THRESHOLD",60)):
            lvl=2 if (nfm_trigger or ratio>=.25 or rate<.01) else 1
            if nfm_trigger and ratio>=.40:
                lvl=3
        else:
            lvl=1
        _elig_fn=globals().get("_v689_rescue_activation_eligible")
        if not callable(_elig_fn) or bool(_elig_fn()):
            _v45_activate_rescue(lvl, "g_starve" if primary else "nfm_ratio")
        else:
            STATS["v689_rescue_activation_blocked"] = int(STATS.get("v689_rescue_activation_blocked",0) or 0) + 1
            STATS["v689_rescue_blocked_reason"] = "no_recoverable_blocker_evidence"
    else:
        if current and now >= float(getattr(_V420State,"rescue_until_ts",0.0) or 0.0):
            _V420State.rescue_level=0; _V420State.rescue_until_ts=0.0
            _V420State.relaxed_mode_until_ts=0.0
            STATS["v45_rescue_level"]=0
            logger.info("[V45-Rescue] expired -> STRICT")
        elif s>0 and current:
            _V420State.rescue_level=0; _V420State.rescue_until_ts=0.0
            _V420State.relaxed_mode_until_ts=0.0
            _V420State.v606_l1_zero_cycles = 0
            STATS["v45_rescue_level"]=0
            STATS["v606_l1_zero_cycles"]=0
            logger.info("[V45-Rescue] send observed -> STRICT")
    STATS["v45_rescue_level"]=_v45_rescue_level()
    STATS["v45_nfm_trigger"]=bool(nfm_trigger)
    try:
        _v457_policy_controller_tick()
        _v457_global_trace_tick()
    except Exception:
        _v647_record_suppressed_exception()

V420FunnelWatchdog.tick = classmethod(_v45_watchdog_tick)


# Legacy relaxed query now maps to L1+ only; L2/L3 also imply relaxed detector
# envelopes, but not global hard-gate bypass.
@staticmethod
def _v45_watchdog_is_relaxed():
    try:
        return (_v45_rescue_level() >= 1 or
                MONO_NOW() < float(_V420State.relaxed_mode_until_ts or 0.0))
    except Exception:
        return False
V420FunnelWatchdog.is_relaxed = _v45_watchdog_is_relaxed


def _v45_effective_score_floor(base_floor: float) -> float:
    """Compatibility helper.

    Global rescue is a separate 0..1 arbitration policy. Canonical execution
    score (0..100) is controlled only by V453CanonicalScoreFloor. Keeping this
    helper identity-based removes cross-scale stacking and policy drift.
    """
    try:
        return float(base_floor)
    except Exception:
        return float(CONFIG.get("MIN_LIVE_SCORE", 70.0))


def _v45_rescue_risk_factor() -> float:
    lvl=_v45_rescue_level()
    return {0:1.0,1:float(CONFIG.get("V45_RESCUE_L1_RISK_MULT",.85)),
            2:float(CONFIG.get("V45_RESCUE_L2_RISK_MULT",.70)),
            3:float(CONFIG.get("V45_RESCUE_L3_RISK_MULT",.60))}.get(lvl,1.0)


# ---- Global market-wide funnel state / bounded rescue controller ------------
class V45GlobalFunnelState:
    _lock = threading.RLock()
    _history = deque(maxlen=32)
    _zero_winner_streak = 0
    _last_cycle_ts = 0.0
    # ---- v4.5.3: cumulative cycle state (disambiguated from windowed view) ----
    _cumulative_cycles = 0
    _process_start_ts = WALL_NOW()
    _last_successful_global_cycle_ts = 0.0
    _last_complete_cycle_ts = 0.0
    _persist_loaded = False
    _last_persist_ts = 0.0
    _funnel_history = deque(maxlen=256)
    _funnel_prev_cum: Dict[str, int] = {}

    # ------------------------------------------------------------------
    # Minimal SQLite persistence (TELEMETRY ONLY). A missing/corrupt value
    # NEVER gates, opens, or blocks trading; counters simply restart at 0.
    # ------------------------------------------------------------------
    @classmethod
    def _persist_restore(cls):
        if cls._persist_loaded or not CONFIG.get("V453_CYCLE_PERSIST_ENABLE", True):
            return
        cls._persist_loaded = True
        conn = None
        try:
            conn = sqlite3.connect(CONFIG["DB_PATH"]); c = conn.cursor()
            c.execute("CREATE TABLE IF NOT EXISTS kv_meta (k TEXT PRIMARY KEY, v TEXT, updated_at TEXT)")
            row = c.execute("SELECT v FROM kv_meta WHERE k='v453_cycle_meta'").fetchone()
            if row and row[0]:
                d = json.loads(row[0])
                cls._cumulative_cycles = max(0, int(d.get("cumulative_cycles", 0) or 0))
                cls._last_successful_global_cycle_ts = float(d.get("last_successful_global_cycle_ts", 0.0) or 0.0)
                STATS["v45_global_cumulative_cycles"] = cls._cumulative_cycles
                STATS["v45_global_last_successful_cycle_wall_ts"] = cls._last_successful_global_cycle_ts
        except Exception as _e:
            try:
                logger.debug(f"[V453.cycle-persist] restore suppressed: {_e}")
            except Exception:
                _v647_record_suppressed_exception()
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @classmethod
    def _persist_store(cls):
        if not CONFIG.get("V453_CYCLE_PERSIST_ENABLE", True):
            return
        conn = None
        try:
            now = MONO_NOW()
            if now - cls._last_persist_ts < 60.0:
                return
            cls._last_persist_ts = now
            conn = sqlite3.connect(CONFIG["DB_PATH"]); c = conn.cursor()
            c.execute("CREATE TABLE IF NOT EXISTS kv_meta (k TEXT PRIMARY KEY, v TEXT, updated_at TEXT)")
            c.execute("INSERT OR REPLACE INTO kv_meta (k, v, updated_at) VALUES (?,?,?)",
                      ("v453_cycle_meta",
                       json.dumps({"cumulative_cycles": int(cls._cumulative_cycles),
                                   "last_successful_global_cycle_ts": float(cls._last_successful_global_cycle_ts)}),
                       datetime.now(timezone.utc).isoformat()))
            conn.commit()
        except Exception as _e:
            try:
                logger.debug(f"[V453.cycle-persist] store suppressed: {_e}")
            except Exception:
                _v647_record_suppressed_exception()
        finally:
            if conn is not None:
                try: conn.close()
                except Exception: pass

    @classmethod
    def note_cycle(cls, generated: int, eligible: int, ranked: int, winners: int, top_score: float = 0.0,
                   canonical_pass: int = 0, canonical_reject: int = 0, submitted: int = 0, sent: int = 0,
                   complete: bool = True, hard_valid: int = 0, raw_ranked: int = 0, pool: int = 0):
        """Record one global cycle. A cycle counts as COMPLETE only when the
        full sequence ran: universe built -> candidates scanned -> arbitration
        finished -> telemetry committed (callers pass complete=True only then)."""
        now = MONO_NOW()
        with cls._lock:
            cls._persist_restore()
            cls._last_cycle_ts = now
            if winners <= 0 and ranked > 0:
                cls._zero_winner_streak += 1
            elif winners > 0:
                cls._zero_winner_streak = 0
            cls._history.append((now, int(generated), int(eligible), int(ranked), int(winners), float(top_score or 0.0)))
            if complete:
                cls._cumulative_cycles += 1
                cls._last_complete_cycle_ts = now
                cls._last_successful_global_cycle_ts = WALL_NOW()
                cls._persist_store()
            STATS["v45_global_last_cycle_ts"] = now
            STATS["v45_global_zero_winner_streak"] = cls._zero_winner_streak
            STATS["v45_global_cycles"] = int(cls._cumulative_cycles)
            STATS["v45_global_cumulative_cycles"] = int(cls._cumulative_cycles)
            # Wall-clock persisted cycle timestamp is the canonical "last successful" age source.
            # Keep the runtime monotonic completion timestamp under an explicit name.
            STATS["v45_global_last_successful_cycle_ts"] = cls._last_successful_global_cycle_ts
            STATS["v45_global_last_complete_cycle_mono_ts"] = cls._last_complete_cycle_ts
            STATS["v45_global_process_start_ts"] = cls._process_start_ts
            STATS["v45_global_last_cycle_generated"] = int(generated)
            STATS["v45_global_last_prequalified"] = int(eligible)
            STATS["v45_global_last_cycle_ranked"] = int(ranked)
            STATS["v45_global_last_cycle_selected"] = int(winners)
            STATS["v45_global_last_cycle_top_score"] = float(top_score or 0.0)
            STATS["v45_global_last_canonical_pass"] = int(canonical_pass)
            STATS["v45_global_last_canonical_reject"] = int(canonical_reject)
            STATS["v45_global_last_submitted"] = int(submitted)
            STATS["v45_global_last_sent"] = int(sent)

            # v4.5.5: truthful per-cycle window telemetry.
            try:
                _bks = ("htf", "policy", "liquidity", "score", "structure", "pre_send", "balance", "execution", "other")
                _cum_now = {
                    "queued": int(STATS.get("signals_queued", 0) or 0),
                    "sent": int(STATS.get("signals_sent", 0) or 0),
                    "canonical_pass": int(STATS.get("global_canonical_pass", 0) or 0),
                    "canonical_reject": int(STATS.get("global_canonical_reject", 0) or 0),
                }
                for _b in _bks:
                    _cum_now[f"reject_{_b}"] = int(STATS.get(f"global_reject.{_b}", 0) or 0)
                _prev = dict(cls._funnel_prev_cum)
                _delta = {k: max(0, v-int(_prev.get(k, v) if _prev else v)) for k,v in _cum_now.items()}
                cls._funnel_prev_cum = _cum_now
                cls._funnel_history.append({
                    "mono_ts": now, "generated": int(generated),
                    "hard_valid": int(hard_valid), "raw_ranked": int(raw_ranked), "pool": int(pool),
                    "prequalified": int(eligible), "ranked": int(ranked),
                    "selected": int(winners), **_delta})
            except Exception:
                _v647_record_suppressed_exception()

    @classmethod
    def funnel_window_deltas(cls, window_sec: float) -> Dict[str, int]:
        now = MONO_NOW()
        with cls._lock:
            rows = [r for r in cls._funnel_history
                    if now-float(r.get("mono_ts",0.0)) <= float(window_sec)]
            keys=("generated","hard_valid","raw_ranked","pool","prequalified","ranked","selected","canonical_pass","canonical_reject",
                  "queued","sent","reject_htf","reject_policy","reject_liquidity","reject_score","reject_structure",
                  "reject_pre_send","reject_balance","reject_execution","reject_other")
            return {k: sum(int(r.get(k,0) or 0) for r in rows) for k in keys}

    @classmethod
    def snapshot(cls, window_sec: float = 900.0) -> Dict[str, Any]:
        now = MONO_NOW()
        with cls._lock:
            cls._persist_restore()
            rows = [r for r in cls._history if now-r[0] <= window_sec]
            return {
                # v4.5.3: disambiguated names — window_cycles is the bounded
                # rolling view; cumulative_cycles survives the whole runtime
                # (and is restored from SQLite across restarts, best-effort).
                "window_cycles": len(rows),
                "cycles": len(rows),  # legacy alias (windowed) — do not read as cumulative
                "cumulative_cycles": int(cls._cumulative_cycles),
                "generated": sum(r[1] for r in rows),
                "eligible": sum(r[2] for r in rows),
                "ranked": sum(r[3] for r in rows),
                "winners": sum(r[4] for r in rows),
                "top_score": max((r[5] for r in rows), default=0.0),
                "last_cycle_top_score": (float(rows[-1][5]) if rows else float(STATS.get("v45_global_last_cycle_top_score", 0.0) or 0.0)),
                "zero_winner_streak": cls._zero_winner_streak,
                "last_cycle_age_sec": (now-cls._last_cycle_ts) if cls._last_cycle_ts else None,
                "process_start_ts": cls._process_start_ts,
                "last_successful_global_cycle_ts": cls._last_successful_global_cycle_ts,
                "last_successful_global_cycle_age_sec": _wall_age_sec(cls._last_successful_global_cycle_ts),
                "last_complete_cycle_age_sec": (now-cls._last_complete_cycle_ts) if cls._last_complete_cycle_ts else None,
            }

    @classmethod
    def maybe_rescue(cls) -> int:
        if not CONFIG.get("V45_RESCUE_ENABLE", True):
            return 0
        snap = cls.snapshot(float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN", 12)) * 60.0)
        generated = int(snap.get("generated", 0) or 0)
        ranked = int(snap.get("ranked", 0) or 0)
        winners = int(snap.get("winners", 0) or 0)
        top = float(snap.get("top_score", 0.0) or 0.0)
        streak = int(snap.get("zero_winner_streak", 0) or 0)
        hard = float(CONFIG.get("V45_SCORE_HARD_FLOOR", 0.50))
        if winners > 0:
            return _v45_rescue_level()
        if generated <= 0 or ranked <= 0 or top < hard:
            return _v45_rescue_level()

        lvl = _v45_rescue_level()
        # First rescue: strong candidates exist but no global winner.
        if lvl == 0:
            if top >= float(CONFIG.get("V45_GLOBAL_RESCUE_MIN_SCORE_L1", 0.52)):
                _v45_activate_rescue(1, "global_zero_winner")
            elif top >= float(CONFIG.get("V45_GLOBAL_RESCUE_MIN_SCORE_L2", 0.50)):
                _v45_activate_rescue(2, "global_zero_winner_l2")
            elif top >= float(CONFIG.get("V45_GLOBAL_RESCUE_MIN_SCORE_L3", 0.48)) and streak >= 1:
                _v45_activate_rescue(3, "global_zero_winner_l3")
        elif lvl == 1 and streak >= 2 and top >= float(CONFIG.get("V45_GLOBAL_RESCUE_MIN_SCORE_L2", 0.50)):
            _v45_activate_rescue(2, "global_zero_winner_escalation")
        elif lvl == 2 and streak >= 3 and top >= float(CONFIG.get("V45_GLOBAL_RESCUE_MIN_SCORE_L3", 0.48)):
            _v45_activate_rescue(3, "global_zero_winner_escalation")
        return _v45_rescue_level()




# =============================================================================
#  v4.5.3 — CANONICAL PREQUALIFICATION + REJECT ATTRIBUTION + STARVATION
#  CLASSIFIER + BOUNDED ADAPTIVE CANONICAL FLOOR (additive, fail-closed).
#  No new trading layer: prequalification only RE-USES facts already present
#  in the MSE snapshot (tier / htf_strength / regime / severity / phase /
#  freshness / hard_valid / cached spread) and the same canonical policy
#  functions SignalBuilder calls. It can only REMOVE a would-be-rejected
#  winner early — it can NEVER allow anything the canonical funnel rejects.
# =============================================================================

V453_REJECT_REASON_HISTORY = deque(maxlen=4096)

_V453_HARD_CATEGORY_PREFIXES = (
    "htf.", "liquidity.", "structure.", "balance.", "safety.",
    "regime.", "policy.", "active_trade.", "freshness.", "precision.",
)


def _v453_last_canonical_reject(symbol: str, window_sec: float = 120.0) -> str:
    """Best-effort lookup of the most recent canonical reject reason for a
    symbol (telemetry attribution only; never influences any gate)."""
    try:
        now = time.time()
        det = STATS.get("rejection_details")
        if not det:
            return "unknown"
        for ev in reversed(list(det)):
            try:
                if float(ev.get("ts", 0) or 0) < now - window_sec:
                    break
                if str(ev.get("symbol") or "") != str(symbol):
                    continue
                reason = str(ev.get("reason") or "")
                return reason.split("reject.", 1)[-1] if reason.startswith("reject.") else (reason or "unknown")
            except Exception:
                continue
    except Exception:
        _v647_record_suppressed_exception()
    return "unknown"


def _v453_reject_bucket(reason: str) -> str:
    r = str(reason or "").lower()
    if not r or r == "unknown":
        return "other"
    if r.startswith("exception.") or "prequal_exception" in r:
        return "system"
    if "score_below" in r or r.startswith("score"):
        return "score"
    if "below_tier" in r or "tier" in r or "liquidity" in r or "depth" in r or "spread" in r or "orderbook" in r:
        return "liquidity"
    if r.startswith("htf") or "not_aligned" in r or "regime" in r or "bearish" in r or "btc_context" in r or "family_policy" in r or "policy" in r:
        return "htf"
    if "pre_send" in r or "presend" in r:
        return "pre_send"
    if "balance" in r or "sizing" in r or "exposure" in r:
        return "balance"
    if "structure" in r or "invariant" in r or "reprice" in r or "router" in r or "no_family" in r or "family" in r or "measured" in r or "microstruct" in r:
        return "structure"
    if "circuit" in r or "kill" in r or "watchdog" in r or "stale" in r or "precision" in r or "submit" in r or "cooldown" in r or "dedup" in r:
        return "execution"
    return "other"


class V453StarvationClassifier:
    """Classify the DOMINANT starvation mode from WINDOWED funnel telemetry.
    Modes: NONE / NO_OPP / SCAN_STALE / SCORE / HTF / LIQUIDITY / STRUCTURE / EXECUTION / SYSTEM.
    v4.5.4: classification is computed from IN-WINDOW DELTAS of the existing
    counters (generated/ranked/selected/canonical/queued/sent + per-category
    reject deltas) — never from runtime-cumulative counters. Priority:
    SYSTEM > HTF/LIQUIDITY/STRUCTURE > SCORE > EXECUTION. Telemetry-only:
    it never opens, blocks, or routes anything."""

    _win_start_ts: float = 0.0
    _baseline: Dict[str, int] = {}

    _KEYS = (
        ("gen", "v45_global_generated"),
        ("ranked", "v45_global_ranked"),
        ("selected", "global_selected"),
        ("cpass", "global_canonical_pass"),
        ("queued", "signals_queued"),
        ("sent", "signals_sent"),
        ("rj_htf", "global_reject.htf"),
        ("rj_policy", "global_reject.policy"),
        ("rj_liq", "global_reject.liquidity"),
        ("rj_score", "global_reject.score"),
        ("rj_structure", "global_reject.structure"),
        ("rj_pre_send", "global_reject.pre_send"),
        ("rj_balance", "global_reject.balance"),
        ("rj_execution", "global_reject.execution"),
    )

    @classmethod
    def _window_deltas(cls) -> Dict[str, int]:
        return V45GlobalFunnelState.funnel_window_deltas(
            float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN", 12)) * 60.0
        )

    @classmethod
    def window_diagnostics(cls) -> Dict[str, Any]:
        window_sec = float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN", 12)) * 60.0
        d = cls._window_deltas()
        top = {
            "htf": d.get("reject_htf",0),
            "policy": d.get("reject_policy",0),
            "liquidity": d.get("reject_liquidity",0),
            "score": d.get("reject_score",0),
            "structure": d.get("reject_structure",0),
            "pre_send": d.get("reject_pre_send",0),
            "balance": d.get("reject_balance",0),
            "execution": d.get("reject_execution",0),
            "other": d.get("reject_other",0),
        }
        top3=sorted(((k,int(v)) for k,v in top.items() if int(v)>0),
                    key=lambda kv:kv[1], reverse=True)[:3]
        gs=V45GlobalFunnelState.snapshot(window_sec)
        return {
            "window_sec": window_sec,
            "last_cycle_age_sec": gs.get("last_cycle_age_sec"),
            "last_successful_global_cycle_age_sec": gs.get("last_successful_global_cycle_age_sec"),
            "window_cycles": gs.get("window_cycles",0),
            "generated_delta": d.get("generated",0),
            "hard_valid_delta": d.get("hard_valid",0),
            "raw_ranked_delta": d.get("raw_ranked",0),
            "pool_delta": d.get("pool",0),
            "prequal_pass_delta": d.get("prequalified",0),
            "ranked_delta": d.get("ranked",0),
            "selected_delta": d.get("selected",0),
            "queued_delta": d.get("queued",0),
            "sent_delta": d.get("sent",0),
            "reject_htf_delta": d.get("reject_htf",0),
            "reject_policy_delta": d.get("reject_policy",0),
            "reject_liquidity_delta": d.get("reject_liquidity",0),
            "reject_structure_delta": d.get("reject_structure",0),
            "reject_score_delta": d.get("reject_score",0),
            "reject_other_delta": d.get("reject_other",0),
            "canonical_pass_delta": d.get("canonical_pass",0),
            "canonical_reject_delta": d.get("canonical_reject",0),
            "prequal_exception_delta": _v455_prequal_exception_delta(window_sec),
            "prequal_top_reasons": _v455_prequal_top_reasons(5),
            "top3_rejects": top3,
        }


    @classmethod
    def classify(cls) -> str:
        try:
            if KillSwitch.is_active():
                return "SYSTEM"
            if bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
                return "SYSTEM"
            if str(getattr(LIVE_STATE,"current","")) != "FULL_LIVE_RUNNING":
                return "SYSTEM"
            try:
                if ExchangeWatchdog.is_tripped():
                    return "SYSTEM"
            except Exception:
                _v647_record_suppressed_exception()
            try:
                if str((BalanceReconciler.snapshot() or {}).get("state","")).upper()=="BLOCK":
                    return "SYSTEM"
            except Exception:
                _v647_record_suppressed_exception()

            # SYSTEM has already been evaluated first and is always dominant.
            # From here onward, every bottleneck decision uses WINDOWED deltas only.
            d=cls._window_deltas()
            gen_d=int(d.get("generated",0) or 0)
            ranked_d=int(d.get("ranked",0) or 0)
            cpass_d=int(d.get("canonical_pass",0) or 0)
            queued_d=int(d.get("queued",0) or 0)
            sent_d=int(d.get("sent",0) or 0)
            rj_htf=int(d.get("reject_htf",0) or 0)
            rj_liq=int(d.get("reject_liquidity",0) or 0)
            rj_score=int(d.get("reject_score",0) or 0)
            rj_str=int(d.get("reject_structure",0) or 0)
            rj_balance=int(d.get("reject_balance",0) or 0)
            rj_execution=int(d.get("reject_execution",0) or 0)
            rj_policy=int(d.get("reject_policy",0) or 0)

            gs=V45GlobalFunnelState.snapshot(float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN",12))*60.0)
            window_cycles=int(gs.get("window_cycles",0) or 0)
            last_age=gs.get("last_successful_global_cycle_age_sec")
            if window_cycles<=0 and last_age is not None and                float(last_age)>float(CONFIG.get("V420_FUNNEL_SCAN_STALE_SEC",420)):

                return "SCAN_STALE"

            if gen_d<=0 and ranked_d<=0:
                return "NO_OPP"

            sys_flavored=rj_balance+rj_execution
            if sys_flavored>0 and sys_flavored>=max(rj_htf,rj_liq,rj_score,rj_str,rj_policy,1):
                return "SYSTEM"

            # v4.5.65: structural pressure wins when it explains the actual
            # rejection share, preventing misleading SCORE starvation labels.
            _v565_mode = _v565_starvation_mode_from_window(
                generated=gen_d, prequal=cpass_d, ranked=ranked_d,
                selected=int(d.get("selected",0) or 0),
                queued=queued_d, sent=sent_d,
                reject_htf=rj_htf, reject_liq=rj_liq,
                reject_structure=rj_str, reject_score=rj_score,
                reject_execution=rj_execution, reject_policy=rj_policy,
            )
            if _v565_mode == "UNATTRIBUTED":
                return "UNATTRIBUTED"
            if _v565_mode == "POLICY":
                return "POLICY"
            if _v565_mode == "STRUCTURE":
                return "STRUCTURE"

            hard={"HTF":rj_htf,"LIQUIDITY":rj_liq,"STRUCTURE":rj_str}
            total_attr=rj_htf+rj_liq+rj_str+rj_score
            top_name,top_n=max(hard.items(),key=lambda kv:kv[1])
            if top_n>0 and top_n>=rj_score and top_n>=max(1,int(0.5*total_attr)):
                return top_name

            if rj_score>0 and rj_score>=max(rj_htf,rj_liq,rj_str):
                return "SCORE"
            top_g=float(STATS.get("v45_global_top_score",0.0) or 0.0)
            gmin=float(STATS.get("v45_global_min_score",0.54) or 0.54)
            if ranked_d>0 and top_g>0 and (gmin-top_g)<=0.06 and sent_d==0:
                return "SCORE"

            if cpass_d>0 and queued_d==0 and sent_d==0:
                return "EXECUTION"
            return "NONE"
        except Exception:
            return "NONE"

    @staticmethod
    def top_reject_reasons(n: int = 3) -> Dict[str, int]:
        try:
            d=V453StarvationClassifier._window_deltas()
            out={
                "htf":int(d.get("reject_htf",0) or 0),
                "policy":int(d.get("reject_policy",0) or 0),
                "liquidity":int(d.get("reject_liquidity",0) or 0),
                "score":int(d.get("reject_score",0) or 0),
                "structure":int(d.get("reject_structure",0) or 0),
                "pre_send":int(d.get("reject_pre_send",0) or 0),
                "balance":int(d.get("reject_balance",0) or 0),
                "execution":int(d.get("reject_execution",0) or 0),
                "other":int(d.get("reject_other",0) or 0),
            }
            return dict(sorted(((k,v) for k,v in out.items() if v>0),
                               key=lambda kv:kv[1],reverse=True)[:max(1,int(n))])
        except Exception:
            return {}



class V453CanonicalScoreFloor:
    """Adaptive score-floor controller; the live floor cannot fall below 70.

    Arms ONLY when ALL of the following hold:
      1. market is not BEARISH_CRASH;  2. no KillSwitch;
      3. no LIVE_ENTRIES_BLOCKED;      4. no balance/exchange/watchdog hazard;
      5. real, repeated candidates exist (>= V453_SCORE_STARV_MIN_OBS
         consecutive observations, never a single tick);
      6. best candidate is within V453_SCORE_STARV_GAP of the canonical floor;
      7. the bottleneck is genuinely score (htf/liquidity/structure reject
         share stays below V453_SCORE_STARV_MAX_SHARE);
      8. no real send during V453_SCORE_STARV_NO_SEND_SEC.
    Legacy relief evidence remains available for telemetry, but release A44
    wraps the live tick and pins the effective floor at >=70. No relief applies
    during a safety hazard. The floor never exceeds the base floor.
    """
    _obs: "deque[float]" = deque(maxlen=64)
    _last_send_ts: float = 0.0
    _seeded: bool = False
    _relief_ts: float = 0.0  # timestamp of the last relief step (TTL anchor)
    _reject_events: "deque[Tuple[float, str]]" = deque(maxlen=512)

    @classmethod
    def _seed(cls):
        if not cls._seeded:
            cls._seeded = True
            cls._last_send_ts = MONO_NOW()

    @classmethod
    def note_send(cls) -> None:
        """Called on a REAL successful send: revert relief toward base."""
        cls._seed()
        cls._last_send_ts = MONO_NOW()
        cls._obs.clear()
        step = float(CONFIG.get("V453_SCORE_FLOOR_STEP", 2.0))
        base = float(CONFIG.get("MIN_LIVE_SCORE", 70))
        cur = float(getattr(_V420State, "adaptive_floor", base) or base)
        if cur < base:
            _V420State.adaptive_floor = min(base, cur + step)
            cls._relief_ts = MONO_NOW() if _V420State.adaptive_floor < base else 0.0
            logger.info(f"[V453-Floor] send observed -> reverting floor to {_V420State.adaptive_floor:.1f}")
            STATS["v453_floor_reverts"] = int(STATS.get("v453_floor_reverts", 0) or 0) + 1

    @classmethod
    def note_reject(cls, bucket: str) -> None:
        """Keep a bounded rolling window of canonical reject attribution.

        This avoids using process-cumulative reject counters as evidence for a
        current starvation condition.
        """
        try:
            cls._reject_events.append((MONO_NOW(), str(bucket or "other")))
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def _window_rejects(cls, window_sec: float) -> Dict[str, int]:
        now = MONO_NOW()
        try:
            while cls._reject_events and (now - float(cls._reject_events[0][0])) > window_sec:
                cls._reject_events.popleft()
        except Exception:
            _v647_record_suppressed_exception()
        out = defaultdict(int)
        for _ts, _bucket in list(cls._reject_events):
            out[str(_bucket)] += 1
        return dict(out)

    @classmethod
    def tick(cls) -> float:
        """Evaluate starvation evidence and return the bounded effective floor."""
        base = float(CONFIG.get("MIN_LIVE_SCORE", 70))
        lo = float(CONFIG.get("V453_SCORE_FLOOR_MIN", 70.0))
        cls._seed()
        cur = float(getattr(_V420State, "adaptive_floor", base) or base)
        cur = max(lo, min(base, cur))
        try:
            _V420State.adaptive_floor = cur
        except Exception:
            _v647_record_suppressed_exception()

        # ---- TTL: every relief step expires after V453_SCORE_FLOOR_TTL_SEC;
        # the floor then walks back toward the base ONE step at a time (never
        # several steps at once). Tightening is always safe, so this runs
        # before the hazard/evidence evaluation.
        try:
            _ttl = float(CONFIG.get("V453_SCORE_FLOOR_TTL_SEC", 420))
            if cur < base and cls._relief_ts > 0.0 and (MONO_NOW() - cls._relief_ts) >= _ttl:
                _step_up = float(CONFIG.get("V453_SCORE_FLOOR_STEP", 2.0))
                _new_floor = min(base, cur + _step_up)
                _V420State.adaptive_floor = _new_floor
                cls._relief_ts = MONO_NOW() if _new_floor < base else 0.0
                STATS["v453_floor_ttl_reverts"] = int(STATS.get("v453_floor_ttl_reverts", 0) or 0) + 1
                logger.info(f"[V453-Floor] relief TTL expired -> floor {cur:.1f}->{_new_floor:.1f} (one step toward base)")
                cur = _new_floor
        except Exception:
            _v647_record_suppressed_exception()

        # ---- HARD SAFETY: never relieve under any hazard ------------------
        try:
            if KillSwitch.is_active():
                cls._obs.clear(); return cur
        except Exception:
            cls._obs.clear(); return cur
        try:
            if bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
                cls._obs.clear(); return cur
        except Exception:
            cls._obs.clear(); return cur
        try:
            if str(getattr(LIVE_STATE, "current", "")) != "FULL_LIVE_RUNNING":
                cls._obs.clear(); return cur
        except Exception:
            cls._obs.clear(); return cur
        try:
            if ExchangeWatchdog.is_tripped():
                cls._obs.clear(); return cur
        except Exception:
            cls._obs.clear(); return cur
        try:
            if str((BalanceReconciler.snapshot() or {}).get("state", "")).upper() == "BLOCK":
                cls._obs.clear(); return cur
        except Exception:
            cls._obs.clear(); return cur
        try:
            _sev = str(STATS.get("v425_macro_severity", "") or "").upper()
            _reg = str(STATS.get("v425_regime_current", STATS.get("regime_current", "")) or "").upper()
            if _sev == "BEARISH_CRASH" or _reg == "BEARISH_CRASH":
                cls._obs.clear(); return cur
        except Exception:
            cls._obs.clear(); return cur

        # ---- Evidence: real candidates + near-floor best + score bottleneck
        ranked = int(STATS.get("v45_global_ranked", 0) or 0)
        top_score100 = float(STATS.get("v453_top_canonical_score", 0.0) or 0.0)
        gap_cfg = float(CONFIG.get("V453_SCORE_STARV_GAP", 7.0))
        near_floor = top_score100 > 0 and (cur - top_score100) <= gap_cfg
        no_send = (MONO_NOW() - cls._last_send_ts) >= float(CONFIG.get("V453_SCORE_STARV_NO_SEND_SEC", 540))

        # Use ONLY the current rolling attribution window for relief evidence.
        # Process-cumulative counters remain useful for telemetry, but must not
        # drive a live score-relief decision.
        _rw = cls._window_rejects(float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN", 12)) * 60.0)
        rj_htf = int(_rw.get("htf", 0) or 0)
        rj_policy = int(_rw.get("policy", 0) or 0)
        rj_liq = int(_rw.get("liquidity", 0) or 0)
        rj_str = int(_rw.get("structure", 0) or 0)
        rj_score = int(_rw.get("score", 0) or 0)
        hard_rejects = rj_htf + rj_policy + rj_liq + rj_str
        total_attr = hard_rejects + rj_score
        score_is_bottleneck = (
            rj_score > 0 and
            (hard_rejects == 0 or (hard_rejects / float(max(1, total_attr))) < float(CONFIG.get("V453_SCORE_STARV_MAX_SHARE", 0.5)))
        )

        if ranked > 0 and near_floor and no_send and score_is_bottleneck:
            cls._obs.append(MONO_NOW())
        else:
            if cls._obs:
                cls._obs.clear()

        need = int(CONFIG.get("V453_SCORE_STARV_MIN_OBS", 3))
        if len(cls._obs) >= need and cur > lo:
            step = float(CONFIG.get("V453_SCORE_FLOOR_STEP", 2.0))
            new_floor = max(lo, cur - step)
            _V420State.adaptive_floor = new_floor
            cls._relief_ts = MONO_NOW()  # each relief step carries its own TTL
            STATS["v453_floor_reliefs"] = int(STATS.get("v453_floor_reliefs", 0) or 0) + 1
            logger.warning(f"[V453-Floor] score starvation confirmed ({len(cls._obs)} obs, "
                           f"top={top_score100:.1f}, no_send={no_send}) -> floor {cur:.1f}->{new_floor:.1f}")
            cls._obs.clear()
            return new_floor
        return float(getattr(_V420State, "adaptive_floor", cur) or cur)


def _v453_safety_hazard() -> Optional[str]:
    """Shared hard-hazard check (prequalification + floor). Fail-closed."""
    try:
        if KillSwitch.is_active():
            return "safety.kill_switch"
    except Exception:
        return "safety.kill_switch_check_failed"
    try:
        _v563_clear_resolved_protection_block()
        if bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
            return "balance.entries_blocked"
    except Exception:
        _v647_record_suppressed_exception()
    try:
        if ExchangeWatchdog.is_tripped():
            return "safety.watchdog"
    except Exception:
        _v647_record_suppressed_exception()
    try:
        if str((BalanceReconciler.snapshot() or {}).get("state", "")).upper() == "BLOCK":
            return "balance.reconciler_block"
    except Exception:
        _v647_record_suppressed_exception()
    return None


def _v453_htf_strength_from_snapshot(snap: Dict[str, Any]) -> Optional[float]:
    """Derive the canonical 1H HTF strength from already-fetched snapshot data.

    This is a zero-fetch repair for telemetry/runtime snapshots that do not carry
    a precomputed ``htf_strength`` field. Missing/insufficient data remains a
    hard reject, so this cannot create a fall-open path.
    """
    try:
        raw = snap.get("htf_strength") if isinstance(snap, dict) else None
        if raw is not None:
            v = float(raw)
            return v if math.isfinite(v) else None
        df1h = snap.get("df_1h") if isinstance(snap, dict) else None
        min_c = max(60, int(CONFIG.get("HTF_MIN_CANDLES_1H", 240)))
        if df1h is None or len(df1h) < min_c:
            return None
        close = float(df1h["close"].iloc[-2])
        ema50 = float(df1h["close"].ewm(span=50, adjust=False).mean().iloc[-2])
        ema200 = float(df1h["close"].ewm(span=200, adjust=False).mean().iloc[-2])
        if not all(math.isfinite(x) and x > 0 for x in (close, ema50, ema200)):
            return None
        strength = 100.0 if close >= ema200 and ema50 >= ema200 else 55.0 if close >= ema200 * 0.99 else 40.0
        if close > ema50 > ema200:
            strength = min(100.0, strength + 10.0)
        return float(strength)
    except Exception:
        return None


# v4.5.13 — bounded same-symbol HTF recovery cache.
_V457_HTF_RECOVERY_CACHE: Dict[str, Tuple[float, float]] = {}
_V457_HTF_RECOVERY_LOCK = threading.RLock()


def _v457_htf_strength_recovered(sym: str, snap: Dict[str, Any], candidate: Any) -> Tuple[Optional[float], str, float]:
    """Return (strength, source, cache_age_sec). Missing remains fail-closed after TTL."""
    try:
        direct = _v453_htf_strength_from_snapshot(snap)
        now = WALL_NOW()
        if direct is not None and math.isfinite(float(direct)):
            with _V457_HTF_RECOVERY_LOCK:
                _V457_HTF_RECOVERY_CACHE[str(sym)] = (float(direct), now)
            STATS["v4513_htf_fresh_count"] = int(STATS.get("v4513_htf_fresh_count",0) or 0) + 1
            return float(direct), "FRESH", 0.0
        if not bool(CONFIG.get("V457_HTF_DATA_RECOVERY_ENABLE", True)):
            return None, "MISSING", 0.0
        ttl = max(0.0, float(CONFIG.get("V457_HTF_DATA_RECOVERY_TTL_SEC", 180.0)))
        max_cand = max(0.0, float(CONFIG.get("V457_HTF_DATA_RECOVERY_MAX_CANDIDATE_AGE_SEC", 390.0)))
        cand_age = _wall_age_sec(getattr(candidate, "generated_at_ms", None))
        if cand_age is None or cand_age > max_cand or ttl <= 0.0:
            return None, "MISSING", float(cand_age or 0.0)
        with _V457_HTF_RECOVERY_LOCK:
            rec = _V457_HTF_RECOVERY_CACHE.get(str(sym))
        if not rec:
            return None, "MISSING", 0.0
        strength, cached_ts = float(rec[0]), float(rec[1])
        age = max(0.0, now - cached_ts)
        if not math.isfinite(strength) or age > ttl:
            return None, "STALE", age
        STATS["v4513_htf_cached_recovery_count"] = int(STATS.get("v4513_htf_cached_recovery_count",0) or 0) + 1
        STATS["v4513_htf_last_recovery_age_sec"] = age
        try:
            if "_V456_EVENTS" in globals():
                _V456_EVENTS.add("htf_recovered", {"symbol": str(sym), "age_sec": age, "strength": strength, "candidate_age_sec": cand_age})
        except Exception:
            _v647_record_suppressed_exception()
        return strength, "CACHED", age
    except Exception:
        return None, "ERROR", 0.0


def _v453_effective_htf_floor(regime: str, configured_floor: float) -> float:
    """Bounded NEUTRAL-only HTF floor override."""
    base = float(configured_floor)
    if (str(regime or "").upper() == "NEUTRAL"
            and bool(CONFIG.get("V453_HTF_NEUTRAL_OVERRIDE_ENABLE", True))):
        return min(base, float(CONFIG.get("V453_HTF_FLOOR_NEUTRAL", 45.0)))
    return base


def _v457_htf_relief_floor(family: str, base_floor: float, regime: str, local_regime: str = "") -> float:
    try:
        if not bool(CONFIG.get("V457_HTF_RELIEF_ENABLE", True)):
            return float(base_floor)
        if str(regime).upper() != "NEUTRAL" or str(local_regime).upper() != "LOCAL_BULLISH":
            return float(base_floor)
        until = float(getattr(_V420State, "v457_htf_relief_until_ts", 0.0) or 0.0)
        if until <= MONO_NOW():
            return float(base_floor)
        families = set(str(x).upper() for x in CONFIG.get("V457_POLICY_RECOVERY_FAMILIES", ()))
        if str(family).upper() not in families:
            return float(base_floor)
        family_key = str(family or "").upper()
        by_family = CONFIG.get("V457_HTF_RELIEF_MIN_FLOOR_BY_FAMILY", {})
        configured_family_floor = None
        try:
            if isinstance(by_family, dict) and family_key in by_family:
                configured_family_floor = float(by_family[family_key])
        except Exception:
            configured_family_floor = None
        global_floor = float(CONFIG.get("V457_HTF_RELIEF_MIN_FLOOR", 30.0))
        min_floor = max(global_floor, configured_family_floor if configured_family_floor is not None else global_floor)
        drop = min(5.0, float(CONFIG.get("V457_HTF_RELIEF_MAX_DROP", 5.0)))
        return max(min_floor, float(base_floor) - max(0.0, drop))
    except Exception:
        return float(base_floor)


def _v457_policy_recovery_active() -> bool:
    try:
        return bool(CONFIG.get("V457_POLICY_RECOVERY_ENABLE", True)) and (
            float(getattr(_V420State, "v457_policy_recovery_until_ts", 0.0) or 0.0) > MONO_NOW()
        )
    except Exception:
        return False


def _v457_relief_reset(reason: str = "reset") -> None:
    try:
        setattr(_V420State, "v457_policy_recovery_until_ts", 0.0)
        setattr(_V420State, "v457_htf_relief_until_ts", 0.0)
        setattr(_V420State, "v457_policy_consecutive_windows", 0)
        STATS["v457_policy_recovery_active"] = False
        STATS["v457_htf_relief_active"] = False
        STATS["v457_policy_recovery_reason"] = str(reason)
    except Exception:
        _v647_record_suppressed_exception()


def _v453_htf_strength_allowed(regime: str, strength: float, configured_floor: float) -> bool:
    try:
        return float(strength) >= _v453_effective_htf_floor(regime, configured_floor)
    except Exception:
        return False


def _v455_record_prequal_reason(symbol: str, reason: str, *, stage: str = "",
                                  exception_type: str = "", context: Optional[Dict[str, Any]] = None) -> None:
    """Bounded telemetry for canonical-prequalification outcomes.

    Unexpected exceptions receive a dedicated ``exception.*`` reason so they
    cannot be mistaken for normal HTF/structure rejection. Telemetry never
    participates in the trading decision.
    """
    if not bool(CONFIG.get("V455_PREQUAL_EXCEPTION_OBS_ENABLE", True)):
        return
    try:
        key = str(reason or "unknown")[:240]
        max_keys = max(8, int(CONFIG.get("V455_PREQUAL_REASON_TOP_MAX", 64)))
        counts = STATS.get("v455_prequal_reason_counts")
        if not isinstance(counts, dict):
            counts = {}
            STATS["v455_prequal_reason_counts"] = counts
        if key in counts or len(counts) < max_keys:
            counts[key] = int(counts.get(key, 0) or 0) + 1
        else:
            counts["__other__"] = int(counts.get("__other__", 0) or 0) + 1
        rec = {"ts": WALL_NOW(), "symbol": str(symbol or ""), "reason": key, "stage": str(stage or "")}
        if exception_type:
            rec["exception_type"] = str(exception_type)[:160]
        if context:
            for k in ("family", "mode", "regime", "severity", "tier", "htf_strength", "quote_vol_24h", "spread_pct",
                      "snapshot_id", "snapshot_coherent", "macro_context_blocked", "macro_context_block_reason"):
                if k in context:
                    try:
                        v = context[k]
                        if isinstance(v, (str, int, float, bool)) or v is None:
                            rec[k] = v
                    except Exception:
                        _v647_record_suppressed_exception()
        # v4.5.8: explicit policy mismatch window/cumulative counters.
        if key.startswith("family_regime_disallowed"):
            STATS["v457_policy_mismatch_count"] = int(STATS.get("v457_policy_mismatch_count", 0) or 0) + 1
            try:
                ctx0 = context or {}
                for _pk in ("local_regime","market_phase","strategy_style","policy_reason",
                            "allowed_regimes","allowed_local_regimes","allowed_severity",
                            "allowed_phases","allowed_styles","family_htf_floor",
                            "effective_htf_floor","recovery_active","recovery_reason"):
                    if _pk in ctx0:
                        rec[_pk] = ctx0[_pk]
            except Exception:
                _v647_record_suppressed_exception()
        hist = STATS.get("v455_prequal_exception_history")
        if not isinstance(hist, deque):
            hist = deque(maxlen=max(16, int(CONFIG.get("V455_PREQUAL_EXCEPTION_HISTORY_MAX", 256))))
            STATS["v455_prequal_exception_history"] = hist
        hist.append(rec)
        if exception_type:
            STATS["v455_prequal_exception_count"] = int(STATS.get("v455_prequal_exception_count", 0) or 0) + 1
            STATS["v455_prequal_last_exception"] = rec
            lvl_name = str(CONFIG.get("V455_PREQUAL_EXCEPTION_LOG_LEVEL", "WARNING")).upper()
            lvl = getattr(logging, lvl_name, logging.WARNING)
            if str(rec.get("stage") or "").strip().lower() == "selftest" or _v702_selftest_log_context_active():
                lvl = logging.INFO
            logger.log(lvl,
                       f"[V455-PREQUAL-EXCEPTION] symbol={rec['symbol']} stage={rec['stage'] or 'unknown'} "
                       f"type={rec['exception_type']} reason={rec['reason']} "
                       f"family={rec.get('family','')} mode={rec.get('mode','')} "
                       f"regime={rec.get('regime','')} tier={rec.get('tier','')} "
                       f"htf={rec.get('htf_strength','')} spread={rec.get('spread_pct','')}")
        elif bool(CONFIG.get("V455_PREQUAL_REASON_LOG_ENABLE", False)):
            logger.info(f"[V455-PREQUAL-REJECT] symbol={rec['symbol']} stage={rec['stage'] or 'unknown'} reason={rec['reason']}")
    except Exception:
        _v647_record_suppressed_exception()


def _v455_prequal_top_reasons(n: int = 8) -> List[Tuple[str, int]]:
    try:
        counts = STATS.get("v455_prequal_reason_counts") or {}
        return sorted(((str(k), int(v or 0)) for k, v in counts.items() if int(v or 0) > 0),
                      key=lambda kv: kv[1], reverse=True)[:max(1, int(n))]
    except Exception:
        return []


def _v455_prequal_exception_delta(window_sec: float = 900.0) -> int:
    try:
        now = WALL_NOW()
        hist = STATS.get("v455_prequal_exception_history") or ()
        return sum(1 for ev in list(hist) if now - float(ev.get("ts", 0.0) or 0.0) <= float(window_sec))
    except Exception:
        return 0


def _v455_prequal_context(candidate: Any, snap: Dict[str, Any]) -> Dict[str, Any]:
    try:
        feats = dict(getattr(candidate, "features_snapshot", None) or {})
        fam = str(getattr(candidate, "family", "") or "")
        mode = str(getattr(candidate, "strategy_mode", "") or "")
        regime = str(snap.get("macro_regime", snap.get("regime", "")) or "")
        severity = str(snap.get("bearish_severity", snap.get("macro_severity", "")) or "")
        # v4.5.14 fix: this helper must not reference the local variables of
        # _v453_prequalify(). The source/age are published onto the snapshot
        # before this helper is called and are read back safely here.
        _ctx_htf_source = snap.get("v4513_htf_source", "")
        _ctx_htf_age = snap.get("v4513_htf_age_sec", 0.0)
        local = str(snap.get("local_regime", snap.get("v425_local_regime", STATS.get("v425_local_regime", ""))) or "")
        phase = str(snap.get("market_phase", snap.get("phase", "")) or "")
        style = str(snap.get("strategy_style", snap.get("style", "SCALP")) or "SCALP")
        policy_ok = snap.get("policy_allowed")
        if policy_ok is None:
            try:
                policy_ok, policy_reason, policy_ctx = FamilyPolicyLayer.regime_policy_detail(
                    fam, regime, strategy_mode=mode, local_regime=local,
                    market_phase=phase, severity=severity, strategy_style=style
                )
                snap.setdefault("policy_reason", policy_reason)
                if isinstance(policy_ctx, dict):
                    for _pk in ("allowed_regimes","allowed_local_regimes","allowed_severity",
                                "allowed_phases","allowed_styles"):
                        if _pk in policy_ctx:
                            snap.setdefault(_pk, policy_ctx[_pk])
            except Exception:
                _v647_record_suppressed_exception()
        return {
            "family": fam, "mode": mode, "regime": regime, "local_regime": local,
            "severity": severity, "market_phase": phase, "strategy_style": style,
            "snapshot_id": str(snap.get("snapshot_id", "") or ""),
            "snapshot_coherent": snap.get("v703_r36_snapshot_coherent"),
            "macro_context_blocked": bool(snap.get("v702_r36_context_blocked", False)),
            "macro_context_block_reason": str(snap.get("v702_r36_context_block_reason", "") or ""),
            "policy_allowed": policy_ok, "policy_reason": snap.get("policy_reason", ""),
            "allowed_regimes": snap.get("allowed_regimes", ()),
            "allowed_local_regimes": snap.get("allowed_local_regimes", ()),
            "allowed_severity": snap.get("allowed_severity", ()),
            "allowed_phases": snap.get("allowed_phases", ()),
            "allowed_styles": snap.get("allowed_styles", ()),
            "tier": str(snap.get("tier") or ""),
            "htf_strength": snap.get("htf_strength", feats.get("htf_strength")),
            "htf_recovery_source": _ctx_htf_source,
            "htf_recovery_age_sec": float(_ctx_htf_age or 0.0),
            "effective_htf_floor": snap.get("effective_htf_floor", snap.get("family_htf_floor", feats.get("family_htf_floor"))),
            "family_htf_floor": snap.get("family_htf_floor", feats.get("family_htf_floor")),
            "quote_vol_24h": snap.get("quote_vol_24h", feats.get("quote_vol_24h")),
            "spread_pct": snap.get("spread_pct", feats.get("spread_pct")),
        }
    except Exception:
        return {}



class CanonicalStrategyPolicyRegistry:
    """Single runtime policy snapshot. Legacy FAMILY_POLICY_* values are read
    once for missing metadata only; runtime decisions never query them directly."""
    _data: Dict[str, Dict[str, Any]] = {}
    _revision: str = "UNINITIALIZED"
    _bootstrapped: bool = False
    @classmethod
    def bootstrap(cls):
        try:
            src=globals().get("V43_STRATEGY_POLICY_META") or {}
            out={str(k).upper():dict(v or {}) for k,v in src.items()}
            families=("PULLBACK","MTF_PULLBACK","BREAKOUT_RETEST","BREAKOUT_CONTINUATION","TREND_CONTINUATION","LIQUIDITY_SWEEP_REVERSAL","MEAN_REVERSION","MOMENTUM_EXPANSION","LOCAL_STRENGTH_BREAKOUT","COMPRESSION_EXPANSION","SWING_PULLBACK","EXTREME_FLUSH_REVERSAL","BEARISH_RECOVERY","CONTINUATION_RECLAIM","FAILED_BREAKOUT_RECLAIM","VOLATILITY_BURST","RELATIVE_STRENGTH_LEADER","MICRO_TREND_CONTINUATION","OPPORTUNITY_SCOUT","LIQUIDITY_ACCEPTANCE_RECLAIM")
            for fam in families:
                legacy=CONFIG.get("FAMILY_POLICY_"+fam) or {}
                d=dict(out.get(fam,{}) or {})
                if legacy:
                    d.setdefault("allowed_regimes",tuple(legacy.get("allowed_regimes",())))
                    d.setdefault("min_tier",str(legacy.get("min_tier","MID")).upper())
                    if "min_htf_strength_non_bearish" not in d and legacy.get("min_htf_strength") is not None: d["min_htf_strength_non_bearish"]=float(legacy.get("min_htf_strength"))
                d.setdefault("enabled",True)
                out[fam]=d
            for fam in ("BREAKOUT_RETEST","BREAKOUT_CONTINUATION","MOMENTUM_EXPANSION","MEAN_REVERSION"):
                out.setdefault(fam,{})
                out[fam].setdefault("mid_bounded_rescue",True)
            raw=json.dumps(out,sort_keys=True,default=str,separators=(",",":"))
            cls._revision=hashlib.sha256(raw.encode()).hexdigest()[:16]; cls._data=out; cls._bootstrapped=True
            STATS["v689_policy_revision"]=cls._revision; return out
        except Exception:
            cls._data={str(k).upper():dict(v or {}) for k,v in (globals().get("V43_STRATEGY_POLICY_META") or {}).items()}; cls._revision="BOOTSTRAP_ERROR"; cls._bootstrapped=True; STATS["v689_policy_drift"]=True; return cls._data
    @classmethod
    def data(cls):
        if not cls._bootstrapped: cls.bootstrap()
        return cls._data
    @classmethod
    def get(cls,k,default=None): return cls.data().get(str(k or "").upper(),default)
    @classmethod
    def revision(cls): cls.data(); return cls._revision


def _v689_score_to_01(v, source_domain=None):
    try:
        x=float(v)
        if not math.isfinite(x): return 0.0
        domain=str(source_domain or "").lower()
        if domain in {"100","0-100","0..100","execution"}: return _clamp(x/100.0,0.0,1.0)
        # Unannotated values are normalized conservatively at the canonical boundary:
        # values above 1 are interpreted as legacy 0..100, never clipped to 1.0.
        if not domain and x>1.0: return _clamp(x/100.0,0.0,1.0)
        return _clamp(x,0.0,1.0)
    except Exception: return 0.0

def _v689_score_to_100(v, source_domain=None):
    try:
        x=float(v)
        if not math.isfinite(x): return 0.0
        domain=str(source_domain or "").lower()
        if domain in {"100","0-100","0..100","execution"}: return _clamp(x,0.0,100.0)
        return _clamp(x*100.0,0.0,100.0) if 0.0<=x<=1.0 else _clamp(x,0.0,100.0)
    except Exception: return 0.0

def _v689_policy_for(family,mode=""):
    return dict(CanonicalStrategyPolicyRegistry.get(str(mode or family or "").upper(),CanonicalStrategyPolicyRegistry.get(str(family or "").upper(),{})) or {})

def _v689_tier_allowed(family,mode,tier,score_01,features=None):
    try:
        t=str(tier or "").upper()
        if not LiquidityTier.is_tradeable(t): return False
        pol=_v689_policy_for(family,mode); min_t=str(pol.get("min_tier","MID") or "MID").upper()
        if _FAMILY_RANK.get(t,-1)>=_FAMILY_RANK.get(min_t,2): return True
        if t!="MID" or min_t!="LARGE" or not bool(CONFIG.get("V689_MID_RESCUE_ENABLE",True)): return False
        if int(_v45_rescue_level())<1: return False
        f=dict(features or {})
        base=_v689_score_to_100(pol.get("min_score",70.0),"100")
        if _v689_score_to_100(score_01,"01") < base+float(CONFIG.get("V689_MID_RESCUE_SCORE_PREMIUM",4.0)): return False
        if float(f.get("depth_ratio",2.20))<float(CONFIG.get("V689_MID_RESCUE_MIN_DEPTH_RATIO",2.20)): return False
        if f.get("spread_pct") is not None and float(f.get("spread_pct"))>float(CONFIG.get("V689_MID_RESCUE_MAX_SPREAD_PCT",0.15)): return False
        if f.get("chase_atr") is not None and float(f.get("chase_atr"))>float(CONFIG.get("V689_MID_RESCUE_MAX_CHASE_ATR",0.90)): return False
        return True
    except Exception: return False

def _v689_candle_ts(snapshot):
    for k in ("candle_ts","closed_candle_ts"):
        v=snapshot.get(k) if isinstance(snapshot,dict) else None
        if v is not None and str(v): return str(v)
    try:
        df=snapshot.get("df_5m")
        if df is not None and len(df)>=2: return str(df.index[-2])
    except Exception: pass
    return ""

def _v689_spread_bucket(sp,tier):
    try:
        x=float(sp); ceil=float((CONFIG.get("TIER_SPREAD_CEIL_PCT",{}) or {}).get(str(tier).upper(),CONFIG.get("SCORE_SPREAD_CEIL_PCT",0.15)))
        if x<=ceil: return "OK"
        return "NEAR" if x<=ceil+float(CONFIG.get("V689_SPREAD_NEAR_CEILING_TOLERANCE_PCT",0.06)) else "OVER"
    except Exception: return "UNKNOWN"

def _v689_prequal_fingerprint(candidate,snapshot,tier=None,htf_state=None):
    try:
        sym=str(getattr(candidate,"symbol","") or snapshot.get("symbol","") or ""); t=str(tier or snapshot.get("tier") or "").upper(); hs=str(htf_state or snapshot.get("htf_state") or "UNKNOWN").upper(); sp=snapshot.get("spread_pct",(getattr(candidate,"features_snapshot",{}) or {}).get("spread_pct"))
        cid=str(snapshot.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0")
        raw=(sym,_v689_candle_ts(snapshot),cid,t,hs,_v689_spread_bucket(sp,t),CanonicalStrategyPolicyRegistry.revision())
        return hashlib.sha256(repr(raw).encode()).hexdigest()[:24]
    except Exception: return ""

def _v689_market_fact_ages(candidate, snapshot):
    """Return independent ages for candidate/candle/market facts. Missing ages stay None.
    These facts are diagnostics plus builder freshness inputs; they never relax hard safety.
    """
    out={}
    try:
        out["candidate_age_sec"]=_wall_age_sec(getattr(candidate,"generated_at_ms",None))
    except Exception: out["candidate_age_sec"]=None
    now=WALL_NOW()
    snap=snapshot if isinstance(snapshot,dict) else {}
    for key, aliases in {
        "market_snapshot_age_sec":("market_snapshot_ts","snapshot_ts","market_ts"),
        "spread_age_sec":("spread_ts","spread_snapshot_ts"),
        "book_age_sec":("book_ts","orderbook_ts","depth_ts"),
        "candle_age_sec":("closed_candle_ts","candle_ts"),
    }.items():
        ts=None
        for k in aliases:
            if snap.get(k) is not None:
                ts=snap.get(k); break
        try:
            if ts is None: out[key]=None; continue
            x=float(ts)
            if x>1e12: x/=1000.0
            elif x>1e10: x/=1000.0
            out[key]=max(0.0,float(now-x))
        except Exception:
            out[key]=None
    return out

def _v689_prequal_snapshot_reusable(candidate,snapshot):
    try:
        fs=getattr(candidate,"features_snapshot",{}) or {}; v=fs.get("v688_prequal_verdict") or {}
        if not bool(v.get("verdict")) or not isinstance(snapshot,dict): return False
        age=_wall_age_sec(getattr(candidate,"generated_at_ms",None)); max_age=float(CONFIG.get("V542_EXECUTION_PARITY_MAX_CANDIDATE_AGE_SEC",390.0))
        if age is None or age>max_age: return False
        ages=_v689_market_fact_ages(candidate,snapshot)
        # Missing age is not automatically an allow for critical refreshed facts;
        # current snapshots may legitimately lack timestamps, so only enforce
        # explicit/stale timestamps here. The final builder/pre-send remains authoritative.
        for _ak,_limk in (("market_snapshot_age_sec","V689_MAX_MARKET_SNAPSHOT_AGE_SEC"),("spread_age_sec","V689_MAX_SPREAD_AGE_SEC"),("book_age_sec","V689_MAX_BOOK_AGE_SEC"),("candle_age_sec","V689_MAX_CANDLE_AGE_SEC")):
            _av=ages.get(_ak)
            if _av is not None and _av>float(CONFIG.get(_limk,max_age)):
                return False
        fs["v689_fact_ages"] = ages
        if _v689_prequal_fingerprint(candidate,snapshot)!=str(v.get("fingerprint","")): return False
        if str(v.get("tier","")).upper() and str(snapshot.get("tier") or "").upper()!=str(v.get("tier")).upper(): return False
        if v.get("spread_pct") is not None and snapshot.get("spread_pct") is not None and abs(float(v.get("spread_pct"))-float(snapshot.get("spread_pct")))>0.02: return False
        if v.get("htf_strength") is not None and snapshot.get("htf_strength") is not None and abs(float(v.get("htf_strength"))-float(snapshot.get("htf_strength")))>2.5: return False
        return True
    except Exception: return False

def _v689_record_prequal(candidate,snapshot,verdict,reason):
    try:
        if not isinstance(getattr(candidate,"features_snapshot",None),dict): return
        fs=candidate.features_snapshot; tier=str(snapshot.get("tier") or fs.get("tier") or "").upper(); sp=snapshot.get("spread_pct",fs.get("spread_pct")); hs=str(snapshot.get("htf_state") or fs.get("htf_state") or "UNKNOWN")
        fs["v688_prequal_verdict"]={"verdict":bool(verdict),"reason":str(reason),"cycle_id":str(snapshot.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0"),"symbol":str(getattr(candidate,"symbol","") or snapshot.get("symbol") or ""),"candle_ts":_v689_candle_ts(snapshot),"tier":tier,"htf_state":hs,"htf_strength":snapshot.get("htf_strength"),"regime":snapshot.get("macro_regime",snapshot.get("regime")),"local_regime":snapshot.get("local_regime"),"market_phase":snapshot.get("market_phase"),"spread_bucket":_v689_spread_bucket(sp,tier),"spread_pct":sp,"score":_v689_score_to_01(getattr(candidate,"engine_score",0.0)),"score_floor":CONFIG.get("V45_SCORE_BASE",0.54),"structure_verdict":fs.get("v643_canonical_precision_reason",fs.get("structure_verdict")),"policy_revision":CanonicalStrategyPolicyRegistry.revision(),"fingerprint":_v689_prequal_fingerprint(candidate,snapshot,tier,hs),"timestamp":WALL_NOW(),"canonical_authority_version":V689_ROOT_CLOSURE_IDENTITY}
    except Exception: pass

def _v689_htf_evidence_class(raw_strength,state,source):
    st=str(state or "UNKNOWN").upper(); src=str(source or "").upper(); val=float(raw_strength or 0.0)
    if st in {"BEARISH","HARD_REJECT","CRASH","BEARISH_CRASH"} or src=="RAW_HARD_REJECT": return "HTF_HARD_REJECT"
    if src=="UNAVAILABLE": return "HTF_UNAVAILABLE"
    if src=="RECOMPUTED_H0": return "HTF_RECOVERY_ALIGNMENT"
    if val>=75.0: return "HTF_FULL_ALIGNMENT"
    if val>=60.0: return "HTF_CONTINUATION_ALIGNMENT"
    return "HTF_RECOVERY_ALIGNMENT"

def _v689_resolve_htf_strength(symbol,snapshot,candidate=None):
    snap=snapshot if isinstance(snapshot,dict) else {}; raw=snap.get("htf_strength"); state=str(snap.get("htf_state") or "UNKNOWN").upper()
    try: raw=float(raw) if raw is not None else 0.0
    except Exception: raw=0.0
    if raw>0 and math.isfinite(raw):
        snap["htf_evidence_class"]=_v689_htf_evidence_class(raw,state,"RAW")
        return raw,"RAW",0.0
    htf_reason = str(snap.get("htf_reason") or "").strip().lower()
    unusable_htf_reasons = {"insufficient_data", "invalid_close_history", "invalid_closed_values", "snapshot_unavailable", "htf_grade_exception"}
    htf_evidence_unusable = htf_reason in unusable_htf_reasons or htf_reason.startswith("error:")
    if state in {"BEARISH","HARD_REJECT","CRASH","BEARISH_CRASH"} and not htf_evidence_unusable:
        snap["htf_evidence_class"]="HTF_HARD_REJECT"
        return raw,"RAW_HARD_REJECT",0.0
    df1=snap.get("df_1h"); df4=snap.get("df_4h")
    required_1h=max(210,int(CONFIG.get("HTF_MIN_CANDLES_1H",240) or 240))
    required_4h=max(210,int(CONFIG.get("HTF_MIN_CANDLES_4H",200) or 200))
    if df1 is None or df4 is None or len(df1)<required_1h or len(df4)<required_4h:
        STATS["v689_htf_recompute_unavailable"] = int(STATS.get("v689_htf_recompute_unavailable",0) or 0) + 1
        STATS["v689_htf_recompute_unavailable_reason"] = "ema200_warmup_insufficient"
        return None,"UNAVAILABLE",0.0
    try:
        if not _PDNP_OK or "close" not in getattr(df1,"columns",()) or "close" not in getattr(df4,"columns",()):
            return None,"RECOMPUTE_ERROR",0.0
        _c1=pd.to_numeric(df1["close"],errors="coerce")
        _c4=pd.to_numeric(df4["close"],errors="coerce")
        _h1=[float(x) for x in _c1.iloc[-required_1h:].tolist()]
        _h4=[float(x) for x in _c4.iloc[-required_4h:].tolist()]
        if (len(_h1)<required_1h or len(_h4)<required_4h
                or any((not math.isfinite(x)) or x<=0.0 for x in _h1)
                or any((not math.isfinite(x)) or x<=0.0 for x in _h4)):
            STATS["v689_htf_recompute_unavailable"] = int(STATS.get("v689_htf_recompute_unavailable",0) or 0) + 1
            STATS["v689_htf_recompute_unavailable_reason"] = "ema200_history_invalid"
            return None,"UNAVAILABLE",0.0
    except Exception:
        STATS["v689_htf_recompute_unavailable"] = int(STATS.get("v689_htf_recompute_unavailable",0) or 0) + 1
        STATS["v689_htf_recompute_unavailable_reason"] = "ema200_history_invalid"
        return None,"UNAVAILABLE",0.0
    cts=_v689_candle_ts(snap); cid=str(snap.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0"); key=(str(symbol),cts,cid)
    if key in _V689_HTF_CACHE: d=_V689_HTF_CACHE[key]; return d["strength"],d["source"],0.0
    try:
        e1=_c1.ewm(span=50,adjust=False).mean(); e2=_c1.ewm(span=200,adjust=False).mean(); f1=_c4.ewm(span=50,adjust=False).mean(); f2=_c4.ewm(span=200,adjust=False).mean()
        score=25.0*bool(float(f1.iloc[-2])>float(f2.iloc[-2])) + 15.0*bool(float(e1.iloc[-2])>float(e2.iloc[-2])) + 5.0*bool(float(_c1.iloc[-2])>float(e1.iloc[-2])) + 5.0*bool(float(_c4.iloc[-2])>float(f1.iloc[-2]))
        try: score+=5.0*bool(float(e1.iloc[-2])>float(e1.iloc[-7]))
        except Exception: pass
        score=min(float(CONFIG.get("V689_HTF_RECOMPUTE_MAX_STRENGTH",55.0)),float(score)); d={"strength":score,"source":"RECOMPUTED_H0","reason":"raw_zero_or_unavailable"}; _V689_HTF_CACHE[key]=d
        snap.update({"htf_primary_strength":raw,"htf_recomputed_strength":score,"htf_recompute_used":True,"htf_recompute_reason":"raw_zero_or_unavailable","htf_recompute_gap":score-raw,"htf_evidence_class":"HTF_RECOVERY_ALIGNMENT"})
        STATS["v689_htf_recompute_used"]=int(STATS.get("v689_htf_recompute_used",0) or 0)+1
        return score,"RECOMPUTED_H0",0.0
    except Exception: return None,"RECOMPUTE_ERROR",0.0

def _v689_family_starvation_snapshot(now=None):
    now=float(now if now is not None else WALL_NOW())
    out={}; last=dict(STATS.get("v689_family_last_live_ts") or {}); funnel=dict(STATS.get("v689_family_funnel") or {})
    for fam in sorted(set(list(funnel.keys())+list(last.keys()))):
        ts=float(last.get(fam,0.0) or 0.0); age=(now-ts) if ts>0 else float("inf"); row=dict(funnel.get(fam) or {})
        if int(row.get("sent",0) or 0)>0:
            state="STARVED" if age>=float(CONFIG.get("V689_FAMILY_STARVATION_SEC",14400.0)) else ("WATCH" if age>=float(CONFIG.get("V689_FAMILY_STARVATION_SEC",14400.0))/2.0 else "NORMAL")
        elif int(row.get("generated",0) or 0)>0:
            state="STRUCTURALLY_BLOCKED" if int(row.get("prequal",0) or 0)==0 and int(row.get("ranked",0) or 0)==0 else ("POLICY_BLOCKED" if int(row.get("selected",0) or 0)==0 else "WATCH")
        else:
            state="NORMAL"
        out[fam]={"last_live_ts":ts,"no_send_sec":age,"generated":int(row.get("generated",0) or 0),"prequal":int(row.get("prequal",0) or 0),"ranked":int(row.get("ranked",0) or 0),"selected":int(row.get("selected",0) or 0),"queued":int(row.get("queued",0) or 0),"sent":int(row.get("sent",0) or 0),"starvation_state":state}
    STATS["v689_family_starvation"]=out
    return out

def _v689_update_family(stage,family,delta=1):
    try:
        d=dict(STATS.get("v689_family_funnel") or {}); f=str(family or "UNKNOWN").upper(); r=dict(d.get(f) or {})
        for k in ("generated","hard_valid","prequal","ranked","selected","builder","live_ready","queued","sent"): r.setdefault(k,0)
        r[stage]=int(r.get(stage,0) or 0)+int(delta); d[f]=r; STATS["v689_family_funnel"]=d
        _v689_family_starvation_snapshot()
    except Exception: pass


def _v689_note_htf_repeat(symbol,snapshot,reason):
    try:
        snap=snapshot or {}; key=(str(symbol),_v689_candle_ts(snap),str(snap.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0"),str(reason))
        now=WALL_NOW(); row=_V689_HTF_REJECTS.get(key,{"count":0,"first":now,"last":now}); row["count"]=int(row.get("count",0))+1; row["last"]=now; _V689_HTF_REJECTS[key]=row
        suppressed=row["count"]>=int(CONFIG.get("V689_HTF_REPEAT_SUPPRESS_THRESHOLD",3)) and (now-row["first"])<=float(CONFIG.get("V689_HTF_REPEAT_SUPPRESS_SEC",1800.0))
        if suppressed: STATS["v689_htf_repeat_suppressed"]=int(STATS.get("v689_htf_repeat_suppressed",0) or 0)+1
        return bool(suppressed)
    except Exception: return False

def _v689_discovery_verify(candidate,snapshot):
    try:
        c=candidate; fs=dict(getattr(c,"features_snapshot",{}) or {}); fam=str(getattr(c,"family","") or getattr(c,"strategy_mode","") or "").upper(); score=_v689_score_to_100(getattr(c,"engine_score",0.0)); tier=str((snapshot or {}).get("tier") or fs.get("tier") or "").upper(); grade=str(fs.get("grade") or fs.get("reviewed_grade") or "").upper()
        native=(fam!="LIQUIDITY_SWEEP_REVERSAL") or bool(fs.get("sweep") or fs.get("reclaim") or fs.get("sr_recovery_verified"))
        ok=bool(score>=float(CONFIG.get("V689_DISCOVERY_VERIFIED_MIN_SCORE",85.0)) and _FAMILY_RANK.get(tier,-1)>=_FAMILY_RANK.get("MID",2) and native and (not grade or grade in {"A","A+","A_PLUS","A PLUS"}))
        d={"verified":ok,"family":fam,"score":score,"grade":grade,"tier":tier,"risk_factor":float(CONFIG.get("V689_DISCOVERY_VERIFIED_RISK_FACTOR",.25)),"shadow":bool(CONFIG.get("V689_DISCOVERY_VERIFIED_SHADOW",True)),"live_enabled":bool(CONFIG.get("V689_DISCOVERY_VERIFIED_LIVE",False))}
        return ok,d
    except Exception: return False,{"verified":False,"reason":"exception"}

_V689_HTF_CACHE={}; _V689_HTF_REJECTS={}
def _v453_prequalify(r: "RankedCandidate", snap_by_symbol: Dict[str, Dict[str, Any]]) -> Tuple[bool, str]:
    """Lightweight canonical prequalification for a global candidate.

    Uses ONLY facts already present in the MSE snapshot (zero new fetches)
    and the SAME canonical policy functions SignalBuilder invokes. Any
    missing/unreliable datum => reject (fail-closed). Never allows anything
    the canonical funnel would reject.
    """
    if not CONFIG.get("V453_CANON_PREQUAL_ENABLE", True):
        return True, "disabled"
    _stage = "start"
    _sym_for_diag = ""
    try:
        c = r.candidate
        sym = str(getattr(c, "symbol", "") or "")
        _sym_for_diag = sym
        # v4.5.10-FIX: prequalification has its own lifecycle trace. The
        # previous path referenced `trace_id` without defining it, causing a
        # NameError exactly when FamilyPolicy rejected a candidate; that was
        # then mislabeled as htf.family_policy_error and hid the real policy
        # reason. Creating the trace here is telemetry-only and cannot open
        # an execution path.
        trace_id = LifecycleTrace.new(sym)
        # A51: cache an early BEARISH policy decision so an incompatible family
        # is not evaluated twice. The shortcut is only used for explicit BEARISH
        # non-crash snapshots and never grants admission; all later gates remain
        # authoritative for candidates whose policy permits the regime.
        _a51_early_policy_decision = None
        _stage = "candidate"
        if str(getattr(c, "side", "") or "").lower() != "long":
            return False, "structure.side_not_long"
        _stage = "safety_hazard"
        hz = _v453_safety_hazard()
        if hz:
            return False, hz
        _stage = "active_trade"
        # Active-trade exclusion (same-symbol).
        try:
            if sym in ACTIVE_TRADES:
                return False, "active_trade.symbol_open"
        except Exception:
            _v647_record_suppressed_exception()
        _stage = "freshness"
        # Freshness: Unix wall-clock only; missing/invalid/stale is fail-closed.
        try:
            _fresh_ok, _fresh_reason, _fresh_age = _v455_candidate_freshness_ok(
                getattr(c, "generated_at_ms", None)
            )
            if not _fresh_ok:
                return False, _fresh_reason
        except Exception:
            return False, "freshness.unverifiable"
        _stage = "hard_valid"
        # Structural validity flagged by the engines/ranker.
        feats = dict(getattr(c, "features_snapshot", None) or {})
        if not bool(feats.get("hard_valid", True)):
            return False, "structure.hard_invalid"
        _stage = "candidate_validation"
        # Fail-closed candidate validation (same as canonical pin path).
        try:
            _vr = CompositeRankingEngine._validate_fail_closed(c)
            if _vr:
                return False, f"structure.{_vr}"
        except Exception:
            return False, "structure.validation_error"
        _stage = "snapshot_facts"
        # Snapshot facts (already fetched by the global brain).
        snap = snap_by_symbol.get(sym) or {}
        # V669 sanitation is deterministic and read-only. It rejects malformed
        # snapshots before pandas/index operations can become opaque exceptions.
        _sanitizer = globals().get("_v669_validate_market_snapshot")
        if callable(_sanitizer) and bool(CONFIG.get("V669_SNAPSHOT_SANITATION_ENABLE", True)):
            _sv_ok, _sv_reason, _sv_detail = _sanitizer(snap, purpose="prequal")
            if not _sv_ok:
                _ctx_s = dict(_v455_prequal_context(c, snap) or {})
                _ctx_s.update({"reason_detail": str(_sv_detail)[:800], "stage": "snapshot_validation"})
                record_rejection(trace_id, sym, "system" if str(_sv_reason).startswith("data.snapshot_exception") else "structure",
                                 _sv_reason, "snapshot_validation", ctx=_ctx_s)
                return False, _sv_reason
        qv = snap.get("quote_vol_24h", None)
        if qv is None:
            qv = feats.get("quote_vol_24h", None)
        if qv is None:
            return False, "liquidity.quote_volume_missing"
        # Normalize provider/cached tier labels before any comparisons. Unknown
        # explicit labels must fail closed; otherwise is_tradeable() would treat
        # e.g. "below" or "UNRECOGNIZED" as tradeable because it only checks
        # exact equality with BELOW.
        tier = _v702_normalize_liquidity_tier(snap.get("tier"), qv)
        if tier is None:
            STATS["v702_liquidity_tier_unverifiable"] = int(STATS.get("v702_liquidity_tier_unverifiable", 0) or 0) + 1
            return False, "liquidity.tier_unverifiable"
        if not LiquidityTier.is_tradeable(tier):
            return False, "liquidity.below_tier"
        _stage = "spread"
        # Spread (only when already cached on the snapshot — no new fetch).
        sp = snap.get("spread_pct", feats.get("spread_pct", None))
        if sp is not None:
            ok_sp, why_sp = tier_spread_hard_ok_v410(float(sp), tier)
            if not ok_sp:
                _near=float(CONFIG.get("V689_SPREAD_NEAR_CEILING_TOLERANCE_PCT",0.06))
                _ceil=float((CONFIG.get("TIER_SPREAD_CEIL_PCT",{}) or {}).get(str(tier).upper(),CONFIG.get("SCORE_SPREAD_CEIL_PCT",0.15)))
                if float(sp)<=_ceil+_near:
                    feats["v689_spread_recheck_pending"]=True; feats["v689_spread_before"]=float(sp); feats["v689_spread_ceiling"]=_ceil; feats["v689_spread_recheck_reason"]=str(why_sp)
                    STATS["v689_spread_recheck_pending"]=int(STATS.get("v689_spread_recheck_pending",0) or 0)+1
                else:
                    return False, f"liquidity.{why_sp}"

        # V702 A51 — bounded BEARISH policy prefilter / throughput closure.
        # In BEARISH (excluding explicit crash labels), policy-disallowed modes
        # cannot qualify through the existing recovery helper: that helper is
        # NEUTRAL-only. Resolve that terminal denial before orderbook/depth and
        # HTF feature work, which cannot restore eligibility. Preserve spread
        # and volume/tier checks above, the crash-guard path below, and the exact
        # canonical policy authority. This is a rejection-order optimization,
        # not a regime/quality relaxation.
        try:
            _a51_regime = str(snap.get("macro_regime", snap.get("regime", "")) or "")
            _a51_severity = str(snap.get("bearish_severity", snap.get("macro_severity", "")) or "")
            if (_a51_regime.upper() == "BEARISH"
                    and _a51_severity.upper() not in {"BEARISH_CRASH", "CRASH"}
                    and bool(CONFIG.get("V410_MASTER_ENABLE", True))
                    and bool(CONFIG.get("V410_FAMILY_POLICY_ENABLE", True))):
                _a51_family = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
                _a51_mode = str(getattr(c, "strategy_mode", "") or "").upper()
                _a51_style = str(getattr(c, "strategy_style", "") or "SCALP").upper()
                if "market_phase" in snap:
                    _a51_phase = snap.get("market_phase")
                else:
                    _a51_phase = feats.get("market_phase", getattr(c, "market_phase", ""))
                if isinstance(_a51_phase, dict):
                    _a51_phase = _a51_phase.get("phase", "")
                _a51_local = str(snap.get("local_regime", getattr(c, "local_regime", "")) or "")
                _a51_decision = FamilyPolicyLayer.regime_policy_detail(
                    _a51_family, _a51_regime, strategy_mode=_a51_mode,
                    local_regime=_a51_local, market_phase=str(_a51_phase or ""),
                    severity=_a51_severity, strategy_style=_a51_style)
                if isinstance(_a51_decision, tuple) and len(_a51_decision) >= 3:
                    _a51_early_policy_decision = _a51_decision
                    _a51_policy_ok, _a51_policy_reason, _a51_policy_ctx = _a51_decision
                    if not _a51_policy_ok:
                        _a51_recovered, _a51_recovery_reason, _a51_recovery_ctx = FamilyPolicyLayer.bounded_neutral_recovery_allowed(
                            _a51_family, _a51_regime, strategy_mode=_a51_mode,
                            local_regime=_a51_local, market_phase=str(_a51_phase or ""),
                            severity=_a51_severity, strategy_style=_a51_style,
                            candidate_features=feats, snapshot=snap,
                            htf_strength=snap.get("htf_strength"))
                        if not _a51_recovered:
                            _a51_reject_reason = f"family_regime_disallowed.{_a51_policy_reason}"
                            _a51_ctx = dict(_a51_policy_ctx or {})
                            _a51_ctx.update({
                                "policy_reason": _a51_policy_reason,
                                "recovery_attempted": True,
                                "recovery_reason": _a51_recovery_reason,
                                "recovery_active": bool(_v457_policy_recovery_active()),
                                "htf_strength": snap.get("htf_strength"),
                                "tier": tier,
                                "policy_prefilter": "BEARISH_NON_CRASH_TERMINAL_DENIAL",
                                "policy_prefilter_telemetry_only": False,
                                "downstream_checks_skipped": ["orderbook_depth", "htf_strength_resolution"],
                            })
                            STATS["v702_a51_regime_policy_prefilter_blocks"] = int(
                                STATS.get("v702_a51_regime_policy_prefilter_blocks", 0) or 0) + 1
                            STATS["v702_a51_regime_policy_prefilter_saved_checks"] = int(
                                STATS.get("v702_a51_regime_policy_prefilter_saved_checks", 0) or 0) + 2
                            V410Telemetry.reject(trace_id, sym, "htf", _a51_reject_reason, "family_policy", _a51_ctx)
                            _v455_record_prequal_reason(sym, _a51_reject_reason,
                                                        stage="family_policy", context=_a51_ctx)
                            LifecycleTrace.record(trace_id, "PREQUAL_POLICY_PREFILTER_REJECT", _a51_ctx)
                            return False, _a51_reject_reason
                        # Defensive compatibility: if the recovery contract is
                        # ever expanded, do not shortcut it; the canonical path
                        # below must evaluate the full, fresh HTF evidence.
                        _a51_early_policy_decision = None
        except Exception as _a51_prefilter_exc:
            # Optimization failure is non-authoritative: continue through the
            # original fail-closed path, which still handles policy exceptions.
            _a51_early_policy_decision = None
            STATS["v702_a51_regime_policy_prefilter_errors"] = int(
                STATS.get("v702_a51_regime_policy_prefilter_errors", 0) or 0) + 1
            STATS["v702_a51_regime_policy_prefilter_last_error"] = type(_a51_prefilter_exc).__name__

        _stage = "orderbook_depth"
        # Cached orderbook/depth reuse (v4.5.4 — NO new fetch): when the
        # snapshot already carries orderbook facts, use them to improve
        # prequalification attribution. Absence is NOT an allow and NOT a
        # reject — the canonical pre-send LiquidityDepth gate remains the
        # final authority. Malformed cached data is fail-closed.
        _ob = snap.get("orderbook", feats.get("orderbook", None))
        if _ob is None:
            _ob = snap.get("depth", feats.get("depth", None))
        if isinstance(_ob, dict):
            try:
                _bids = _ob.get("bids") or []
                _asks = _ob.get("asks") or []
                if not _bids or not _asks:
                    return False, "liquidity.orderbook_empty"
                _bb = float(_bids[0][0]); _ba = float(_asks[0][0])
                if _bb <= 0 or _ba <= 0 or _ba < _bb:
                    return False, "liquidity.orderbook_crossed"
            except Exception:
                return False, "liquidity.orderbook_unverifiable"
        _dr = snap.get("depth_ratio", feats.get("depth_ratio", None))
        # A9 exact-book handoff deliberately stores 0.0 as a sentinel asking the
        # canonical order-book helper to derive depth from that exact book. Do not
        # interpret that sentinel as measured zero depth before deriving it here.
        # The helper requires explicit source provenance and a fresh book timestamp;
        # malformed/stale evidence remains fail-closed.
        _depth_evidence = None
        try:
            _raw_dr = None if _dr is None else float(_dr)
            if (_raw_dr is None or _raw_dr == 0.0):
                _depth_evidence = _v702_a43_derive_depth_ratio_from_exact_book(snap, c, _ob)
                if isinstance(_depth_evidence, dict) and _depth_evidence.get("trusted_source"):
                    if not _depth_evidence.get("valid"):
                        _v702_a43_record_depth_observation(
                            sym, tier, None, _depth_evidence, None, "liquidity.depth_unverifiable", "prequal"
                        )
                        return False, "liquidity.depth_unverifiable"
                    _dr = float(_depth_evidence["depth_ratio"])
                    snap["depth_ratio"] = _dr
                    snap["v702_a43_depth_ratio_source"] = str(_depth_evidence.get("source") or "DERIVED_EXACT_BOOK")
                    snap["v702_a43_depth_ratio_derived"] = True
            if _dr is not None:
                _dr_value = float(_dr)
                _min_dr = float(CONFIG.get("V45_TIER_MICRO_MIN_DEPTH_RATIO", 1.90)) \
                    if tier == LiquidityTier.MICRO else 1.0
                if not math.isfinite(_dr_value) or _dr_value < 0.0:
                    _v702_a43_record_depth_observation(
                        sym, tier, _dr_value, _depth_evidence, _min_dr, "liquidity.depth_unverifiable", "prequal"
                    )
                    return False, "liquidity.depth_unverifiable"
                if _dr_value < _min_dr:
                    _near_micro = (
                        tier == LiquidityTier.MICRO
                        and isinstance(_ob, dict)
                        and _v702_r41_micro_depth_recheck_eligible(tier, _dr_value, _ob)
                    )
                    _decision_reason = "micro_depth_recheck_deferred" if _near_micro else "liquidity.depth_ratio_below_floor"
                    _v702_a43_record_depth_observation(
                        sym, tier, _dr_value, _depth_evidence, _min_dr, _decision_reason, "prequal"
                    )
                    if _near_micro:
                        snap["v702_r41_micro_depth_recheck_pending"] = True
                        STATS["v702_r41_micro_depth_recheck_deferred"] = int(
                            STATS.get("v702_r41_micro_depth_recheck_deferred", 0) or 0
                        ) + 1
                    else:
                        return False, "liquidity.depth_ratio_below_floor"
                else:
                    _v702_a43_record_depth_observation(
                        sym, tier, _dr_value, _depth_evidence, _min_dr, "depth_floor_pass", "prequal"
                    )
        except Exception as _depth_exc:
            try:
                _v702_a43_record_depth_observation(
                    sym, tier, _dr, _depth_evidence, None,
                    f"liquidity.depth_unverifiable:{type(_depth_exc).__name__}", "prequal"
                )
            except Exception:
                pass
            return False, "liquidity.depth_unverifiable"

        # R34: when the exact cached order book is already in the immutable cycle
        # snapshot, replay the same MICRO terminal confirmation here. This moves a
        # deterministic Builder block upstream without weakening the gate or adding
        # any new market request. Missing cached book => Builder remains authoritative.
        if bool(CONFIG.get("V702_R34_MICRO_ORDERBOOK_PREQUAL_PARITY_ENABLE", True)) and tier == LiquidityTier.MICRO:
            _raw_ob_pre = snap.get("orderbook") or snap.get("depth")
            if isinstance(_raw_ob_pre, dict) and _ob is not None:
                try:
                    _ob_ctx_pre = {
                        "spread_pct": float(sp) if sp is not None else 0.0,
                        "depth_ratio": float(_dr) if _dr is not None else 0.0,
                        "volume_ratio": float(snap.get("volume_ratio", feats.get("volume_ratio", 0.0)) or 0.0),
                        "structure_confidence": float(snap.get("structure_confidence", feats.get("structure_confidence", feats.get("structure_quality", 0.0))) or 0.0),
                        "structure_quality": float(snap.get("structure_confidence", feats.get("structure_quality", 0.0)) or 0.0),
                        "chase_atr": float(feats.get("chase_atr", getattr(c, "chase_atr", 0.0)) or 0.0),
                    }
                    _ob_pre_ok, _ob_pre_reason = _v45_orderbook_confirmation(_raw_ob_pre, _ob_ctx_pre, tier)
                    if not _ob_pre_ok:
                        _defer_micro_depth = bool(
                            _ob_pre_reason == "micro_depth"
                            and snap.get("v702_r41_micro_depth_recheck_pending")
                            and _v702_r41_micro_depth_recheck_eligible(tier, float(_dr or 0.0), _raw_ob_pre)
                        )
                        if _defer_micro_depth:
                            STATS["v702_r41_micro_orderbook_exact_recheck_deferred"] = int(
                                STATS.get("v702_r41_micro_orderbook_exact_recheck_deferred", 0) or 0
                            ) + 1
                        else:
                            STATS["v702_r34_micro_orderbook_prequal_blocks"] = int(STATS.get("v702_r34_micro_orderbook_prequal_blocks", 0) or 0) + 1
                            _v702_a8_note_orderbook_block(sym, "prequal", _ob_pre_reason, _ob_ctx_pre)
                            return False, "liquidity.v45_micro_orderbook_confirmation"
                    else:
                        STATS["v702_r34_micro_orderbook_prequal_passes"] = int(STATS.get("v702_r34_micro_orderbook_prequal_passes", 0) or 0) + 1
                except Exception:
                    return False, "liquidity.v45_micro_orderbook_unverifiable"

        _stage = "htf_strength"
        # HTF eligibility: reuse the canonical snapshot field when present,
        # otherwise derive it from the SAME already-fetched 1H candles.
        htf_strength, _htf_source, _htf_age = _v689_resolve_htf_strength(sym, snap, c)
        try:
            snap["v4513_htf_source"] = str(_htf_source or "")
            snap["v4513_htf_age_sec"] = float(_htf_age or 0.0)
            STATS["v4513_htf_last_recovery_source"] = str(_htf_source or "")
            STATS["v4513_htf_last_recovery_age_sec"] = float(_htf_age or 0.0)
        except Exception:
            _v647_record_suppressed_exception()
        if htf_strength is None:
            STATS["v453_htf_unavailable"] = int(STATS.get("v453_htf_unavailable", 0) or 0) + 1
            if _htf_source == "STALE":
                STATS["v4513_htf_stale_recovery_rejects"] = int(STATS.get("v4513_htf_stale_recovery_rejects",0) or 0) + 1
            return False, "htf.unavailable"
        _stage = "regime_context"
        # Publish the last observed local regime for the operator heartbeat.
        _local_for_hb = str(snap.get("local_regime", getattr(c, "local_regime", "")) or "")
        if _local_for_hb:
            STATS["v425_local_regime"] = _local_for_hb
            STATS["v45_last_local_regime"] = _local_for_hb
        regime = str(snap.get("macro_regime", snap.get("regime", "")) or "")
        severity = str(snap.get("bearish_severity", snap.get("macro_severity", "")) or "")
        if regime == "BEARISH" and severity.upper() == "BEARISH_CRASH":
            try:
                _v702_a38_record_htf_crash_guard(sym, snap, c, reason="htf.bearish_crash_guard", stage="prequal",
                                                details={"severity":severity,"regime":regime,"local_regime":_local_for_hb,
                                                         "htf_state":snap.get("htf_state"),"htf_strength":htf_strength,
                                                         "htf_source":_htf_source,"htf_age_sec":_htf_age})
            except Exception:
                pass
            return False, "htf.bearish_crash_guard"
        _stage = "family_policy"
        # Family/regime policy (canonical authority).
        family = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
        mode = str(getattr(c, "strategy_mode", "") or "").upper()
        style = str(getattr(c, "strategy_style", "") or "SCALP").upper()
        # Snapshot is the canonical per-cycle authority. Candidate phase is
        # fallback-only for legacy/test candidates whose snapshot has no field.
        if "market_phase" in snap:
            phase = snap.get("market_phase")
        else:
            phase = feats.get("market_phase", getattr(c, "market_phase", ""))
        if isinstance(phase, dict):
            phase = phase.get("phase", "")
        local_regime = str(snap.get("local_regime", getattr(c, "local_regime", "")) or "")
        # v4.5.12: telemetry-only audit. The canonical decision trusts the
        # enriched snapshot, never the candidate's copied context.
        try:
            _cand_reg = str(getattr(c, "macro_regime", "") or "").upper()
            _cand_local = str(getattr(c, "local_regime", "") or "").upper()
            _snap_reg = str(regime or "").upper()
            _snap_local = str(local_regime or "").upper()
            _cand_phase = getattr(c, "market_phase", "")
            if isinstance(_cand_phase, dict):
                _cand_phase = _cand_phase.get("phase", "")
            _cand_phase = str(_cand_phase or "").upper()
            _snap_phase = str(phase or "").upper()
            _drift_fields = []
            if _cand_reg and _snap_reg and _cand_reg != _snap_reg:
                _drift_fields.append("macro_regime")
            if _cand_local and _snap_local and _cand_local != _snap_local:
                _drift_fields.append("local_regime")
            if _cand_phase and _snap_phase and _cand_phase != _snap_phase:
                _drift_fields.append("market_phase")
            if _drift_fields:
                STATS["v459_snapshot_candidate_context_drift"] = int(
                    STATS.get("v459_snapshot_candidate_context_drift", 0) or 0) + 1
                STATS["v459_snapshot_candidate_context_drift_last"] = {
                    "symbol": sym,
                    "fields": tuple(_drift_fields),
                    "candidate_regime": _cand_reg,
                    "snapshot_regime": _snap_reg,
                    "candidate_local": _cand_local,
                    "snapshot_local": _snap_local,
                    "candidate_phase": _cand_phase,
                    "snapshot_phase": _snap_phase,
                }
        except Exception:
            _v647_record_suppressed_exception()
        if CONFIG.get("V410_MASTER_ENABLE", True) and CONFIG.get("V410_FAMILY_POLICY_ENABLE", True):
            try:
                if _a51_early_policy_decision is not None:
                    _policy_ok, _policy_reason, _policy_ctx = _a51_early_policy_decision
                else:
                    _policy_ok, _policy_reason, _policy_ctx = FamilyPolicyLayer.regime_policy_detail(
                        family, regime, strategy_mode=mode, local_regime=local_regime,
                        market_phase=str(phase or ""), severity=severity, strategy_style=style)
                if not _policy_ok:
                    _recovered, _recovery_reason, _recovery_ctx = FamilyPolicyLayer.bounded_neutral_recovery_allowed(
                        family, regime, strategy_mode=mode, local_regime=local_regime,
                        market_phase=str(phase or ""), severity=severity, strategy_style=style,
                        candidate_features=feats, snapshot=snap, htf_strength=htf_strength)
                    if not _recovered:
                        _reject_reason = f"family_regime_disallowed.{_policy_reason}"
                        _ctx = dict(_policy_ctx or {})
                        _ctx.update({
                            "policy_reason": _policy_reason,
                            "recovery_attempted": True,
                            "recovery_reason": _recovery_reason,
                            "recovery_active": bool(_v457_policy_recovery_active()),
                            "htf_strength": htf_strength,
                            "tier": tier,
                        })
                        V410Telemetry.reject(trace_id, sym, "htf", _reject_reason, "family_policy", _ctx)
                        _v455_record_prequal_reason(sym, _reject_reason, stage="family_policy", context=_ctx)
                        # Preserve the actual policy reason end-to-end so the
                        # rejection ledger/root-cause classifier doesn't collapse
                        # local/phase/severity/style failures into one generic HTF bucket.
                        return False, _reject_reason
                    STATS["v457_policy_recovery_passes"] = int(STATS.get("v457_policy_recovery_passes",0) or 0) + 1
                    _ctx = dict(_recovery_ctx or {})
                    _ctx.update({"policy_reason": _policy_reason, "recovery_reason": _recovery_reason})
                    _v455_record_prequal_reason(sym, "policy_recovery.family_regime", stage="family_policy", context=_ctx)
                    LifecycleTrace.record(trace_id, "POLICY_RECOVERY_PASS", _ctx)
            except Exception as _policy_exc:
                # v4.5.10-FIX: never collapse a runtime exception into an HTF
                # rejection. Preserve fail-closed behavior, but expose the
                # actual exception so starvation classification is truthful.
                _exc_reason = "exception.prequal:family_policy"
                _exc_ctx = {
                    "family": family,
                    "strategy_mode": mode,
                    "regime": regime,
                    "local_regime": local_regime,
                    "market_phase": str(phase or ""),
                    "severity": severity,
                    "strategy_style": style,
                    "htf_strength": htf_strength,
                    "tier": tier,
                    "policy_exception_type": type(_policy_exc).__name__,
                    "policy_exception": str(_policy_exc)[:240],
                }
                try:
                    STATS["v455_prequal_exception.family_policy"] = int(
                        STATS.get("v455_prequal_exception.family_policy", 0) or 0) + 1
                    _v455_record_prequal_reason(
                        sym, _exc_reason, stage="family_policy",
                        exception_type=type(_policy_exc).__name__, context=_exc_ctx)
                    LifecycleTrace.record(trace_id, "PREQUAL_EXCEPTION", _exc_ctx)
                except Exception:
                    _v647_record_suppressed_exception()
                if bool(CONFIG.get("V455_PREQUAL_EXCEPTION_LOG_ENABLE", True)):
                    logger.exception(
                        f"[V455-PREQUAL-EXCEPTION] symbol={sym} stage=family_policy "
                        f"type={type(_policy_exc).__name__} reason={str(_policy_exc)[:240]}"
                    )
                return False, _exc_reason
            # Strategy-mode metadata gates (tier floor / htf floor).
            try:
                meta = CanonicalStrategyPolicyRegistry.get(mode)
                if meta is not None:
                    if not bool(meta.get("enabled", True)):
                        return False, "policy.strategy_disabled"
                    sev_up = severity.upper()
                    if regime == "BEARISH" and sev_up in {"BEARISH_NORMAL", "BEARISH_STRESSED", "NORMAL", "STRESSED"}:
                        htf_floor = None
                    else:
                        htf_floor = float(meta.get("min_htf_strength_non_bearish", 55.0))
                    if regime == "NEUTRAL":
                        htf_floor = _v453_effective_htf_floor(regime, htf_floor)
                    htf_floor = _v702_effective_htf_floor(family, mode, regime, local_regime, htf_floor, feats)
                    _htf_policy_detail = _v702_htf_policy_detail(family, mode, regime, local_regime, htf_floor, feats)
                    feats["v702_htf_policy"] = dict(_htf_policy_detail)
                    _htf_policy_name = str(_htf_policy_detail.get("policy", "LEGACY_STRICT"))
                    STATS[f"v702_htf_policy_seen.{_htf_policy_name}"] = int(STATS.get(f"v702_htf_policy_seen.{_htf_policy_name}", 0) or 0) + 1
                    if htf_floor is not None and not _v453_htf_strength_allowed(regime, float(htf_strength), htf_floor):
                        _a29_htf_relief_ok, _a29_htf_relief_ctx = (False, {"reason": "not_eligible"})
                        try:
                            _a29_htf_relief_fn = globals().get("_v702_a29_pullback_htf_relief_allowed")
                            if callable(_a29_htf_relief_fn):
                                _a29_htf_relief_ok, _a29_htf_relief_ctx = _a29_htf_relief_fn(
                                    c, snap, family=family, strategy_mode=mode, regime=regime,
                                    local_regime=local_regime, severity=severity,
                                    htf_state=str(snap.get("htf_state", "") or ""),
                                    htf_strength=htf_strength,
                                    htf_reason=str(snap.get("htf_reason", "") or ""),
                                )
                        except Exception:
                            _a29_htf_relief_ok, _a29_htf_relief_ctx = False, {"reason": "exception_fail_closed"}
                        if not _a29_htf_relief_ok:
                            return False, "htf.family_htf_strength_below_floor"
                        feats["v702_a29_contextual_htf_relief"] = dict(_a29_htf_relief_ctx or {})
                        STATS["v702_a29_contextual_htf_relief_passes"] = int(
                            STATS.get("v702_a29_contextual_htf_relief_passes", 0) or 0
                        ) + 1
                        try:
                            LifecycleTrace.record(trace_id, "V702_A29_CONTEXTUAL_HTF_RELIEF", {
                                "symbol": sym, **dict(_a29_htf_relief_ctx or {})
                            })
                        except Exception:
                            _v647_record_suppressed_exception()
                    min_rank = _FAMILY_RANK.get(str(meta.get("min_tier", "MID")), 2)
                    if tier == LiquidityTier.MICRO and bool(CONFIG.get("V702_A7_MICRO_HANDOFF_ENABLE", True)):
                        try:
                            _a7_micro_ok, _a7_micro_reason, _a7_micro_proof = _v702_a7_micro_handoff_evidence(
                                c, snap, tier=tier, record=True
                            )
                            if _a7_micro_ok:
                                feats["v702_a7_micro_handoff"] = dict(_a7_micro_proof or {})
                            else:
                                STATS["v702_a7_micro_handoff_last_block_reason"] = str(_a7_micro_reason)[:180]
                        except Exception as _a7_micro_exc:
                            STATS["v702_a7_micro_handoff_unverifiable"] = int(STATS.get("v702_a7_micro_handoff_unverifiable", 0) or 0) + 1
                            logger.debug("[V702-A7-MICRO] prequal proof fail-closed: %s", type(_a7_micro_exc).__name__)
                    if not _v689_tier_allowed(family, mode, tier, _v689_score_to_01(getattr(c,"engine_score",0.0)), feats):
                        return False, "liquidity.family_tier_below_floor"
            except Exception:
                return False, "policy.meta_error"
        _stage = "strategy_policy"
        # Strategy-mode validity for the v4.3 hard-gated set.
        if mode in {"LOCAL_STRENGTH_BREAKOUT", "COMPRESSION_EXPANSION",
                    "SWING_PULLBACK", "EXTREME_FLUSH_REVERSAL"}:
            try:
                if not FamilyPolicyLayer.strategy_allowed(
                        mode, regime, local_regime, str(phase or ""), severity, style):
                    return False, "htf.v43_strategy_policy_disallowed"
            except Exception:
                return False, "htf.v43_strategy_policy_error"
        # v4.5.20 — canonical parity closure before global arbitration.
        # v4.5.70 — execution-score parity closure: a global winner must not
        # be selected when its canonical engine score is already below the
        # current canonical execution floor. This is NOT a safety bypass; it
        # removes candidates that the live builder is deterministically known
        # to reject at the score gate, preventing SELECTED->SCORE starvation.
        if bool(CONFIG.get("V570_GLOBAL_CANONICAL_SCORE_PARITY_ENABLE", True)):
            try:
                _raw_exec_score = float(getattr(c, "engine_score", 0.0) or 0.0)
                _exec_score_100 = (_raw_exec_score * 100.0) if 0.0 <= _raw_exec_score <= 1.0 else _raw_exec_score
                _base_floor = _v570_strategy_aware_canonical_floor(c, regime, family)
                _floor_min = float(CONFIG.get("V453_SCORE_FLOOR_MIN", 70.0))
                _adaptive_floor = float(getattr(_V420State, "adaptive_floor", _base_floor) or _base_floor)
                _adaptive_floor = max(_floor_min, min(_base_floor, _adaptive_floor))
                _v45_floor = _base_floor
                try:
                    _v45_floor = float(_v45_effective_score_floor(_base_floor))
                    _v45_floor = max(_floor_min, min(_base_floor, _v45_floor))
                except Exception:
                    _v45_floor = _base_floor
                try:
                    _rescue_lvl = _v45_rescue_level()
                except Exception:
                    _rescue_lvl = 0
                _exec_floor = max(_adaptive_floor, _v45_floor) if _rescue_lvl > 0 else _adaptive_floor
                # v4.5.83: engine_score and final SignalBuilder score are
                # different quantities. The latter can receive bounded additive
                # adjustments (confluence, order-book, D1/breadth, etc.). A raw
                # engine score below the floor is therefore NOT sufficient proof
                # of deterministic score rejection. Reject only when even the
                # configured maximum bounded adjustment cannot reach the floor.
                _max_adj = _v584_canonical_score_upper_bound(c, str(family or getattr(c, "strategy_mode", "") or ""), snap)
                _feasible_upper = (_exec_score_100 + _max_adj) if math.isfinite(_exec_score_100) else float("-inf")
                if (not math.isfinite(_exec_score_100) or _feasible_upper < _exec_floor):
                    STATS["v570_prequal_score_rejects"] = int(STATS.get("v570_prequal_score_rejects", 0) or 0) + 1
                    STATS["v570_prequal_score_gap_sum"] = float(STATS.get("v570_prequal_score_gap_sum", 0.0) or 0.0) + max(0.0, _exec_floor - (_feasible_upper if math.isfinite(_feasible_upper) else 0.0))
                    STATS["v570_last_score_block"] = {
                        "symbol": sym, "score": _exec_score_100, "floor": _exec_floor,
                        "base_floor": _base_floor, "adaptive_floor": _adaptive_floor,
                        "legacy_rescue_floor": _v45_floor, "max_adjustment": _max_adj,
                        "feasible_upper": _feasible_upper if math.isfinite(_feasible_upper) else None,
                        "strategy_mode": str(getattr(c, "strategy_mode", "") or ""),
                        "family": str(family or ""),
                        "gap": (_exec_floor - _exec_score_100) if math.isfinite(_exec_score_100) else None,
                    }
                    return False, f"score_below_feasible_floor:{_exec_score_100:.1f}+{_max_adj:.1f}<{_exec_floor:.1f}"
                if math.isfinite(_exec_score_100) and _exec_score_100 < _exec_floor:
                    STATS["v583_score_feasibility_passes"] = int(STATS.get("v583_score_feasibility_passes", 0) or 0) + 1

                # R34: eliminate deterministic SELECTED->SCORE builder churn by
                # replaying the actual downstream score on the exact CLOSED snapshot.
                # This is activated only when parity is fully verifiable; otherwise
                # the original safe feasible-upper-bound path remains authoritative.
                if bool(CONFIG.get("V702_R34_EXACT_SCORE_PREFILTER_ENABLE", True)):
                    try:
                        _projection_fn = globals().get("_v702_projected_canonical_score")
                        if not callable(_projection_fn):
                            # Import-time historical self-tests may execute before the
                            # terminal projection function is defined. In that narrow
                            # phase, keep the existing feasible-upper-bound gate and
                            # do not count a missing-definition as a runtime error.
                            _proj = None
                        else:
                            _proj = _projection_fn(c, snap)
                        _pstat = dict((globals().get("_V702_R34_PROJECTION_STATUS") or {}).get(sym, {}) or {})
                        _complete = bool(_pstat.get("complete", False))
                        # The Builder has a second, deterministic quality-floor layer
                        # above the raw MIN_LIVE_SCORE. Prefer the exact projected
                        # effective floor recorded from the same candidate/snapshot;
                        # otherwise retain the existing canonical prequal floor.
                        _projected_floor = float(_pstat.get("effective_floor", _exec_floor) or _exec_floor)
                        _projected_floor = max(float(CONFIG.get("MIN_LIVE_SCORE", 70.0)), _projected_floor)
                        if _complete and _proj is not None and math.isfinite(float(_proj)):
                            STATS["v702_r34_exact_score_prefilter_evals"] = int(STATS.get("v702_r34_exact_score_prefilter_evals", 0) or 0) + 1
                            if float(_proj) < _projected_floor:
                                STATS["v702_r34_exact_score_prefilter_rejects"] = int(STATS.get("v702_r34_exact_score_prefilter_rejects", 0) or 0) + 1
                                STATS["v702_r34_last_exact_score_prefilter_block"] = {
                                    "symbol": sym, "projected_score": float(_proj), "floor": float(_projected_floor),
                                    "notes": list(_pstat.get("notes", []) or []), "cycle_id": _pstat.get("cycle_id", ""),
                                }
                                return False, f"score.exact_builder_projection_below_floor:{float(_proj):.1f}<{float(_projected_floor):.1f}"
                            STATS["v702_r34_exact_score_prefilter_passes"] = int(STATS.get("v702_r34_exact_score_prefilter_passes", 0) or 0) + 1
                    except Exception:
                        # Never replace the existing fail-closed canonical score path
                        # with an unverifiable prefilter.
                        STATS["v702_r34_exact_score_prefilter_errors"] = int(STATS.get("v702_r34_exact_score_prefilter_errors", 0) or 0) + 1
            except Exception:
                return False, "score.canonical_parity_unverifiable"

        if bool(CONFIG.get("V520_CANONICAL_PARITY_ENABLE",True)):
            if bool(CONFIG.get("V520_PREQUAL_EXACT_HTF_ENABLE",True)) and snap.get("htf_pass") is False:
                _htf_state = str(snap.get("htf_state", "") or "").upper()
                _htf_reason = str(snap.get("htf_reason", "") or "").lower()
                # v4.5.20: bridge is a deterministic recovery path only. It must
                # never rescue missing/unknown/error HTF truth.
                _unknown_htf = (
                    _htf_state in {"UNKNOWN", "ERROR"} or
                    _htf_reason.startswith("error") or
                    _htf_reason in {"insufficient_data", "snapshot_unavailable", "htf_grade_exception"}
                )
                if bool(CONFIG.get("V521_BRIDGE_ALLOW_ONLY_DETERMINISTIC_HTF_REJECT", True)) and _unknown_htf:
                    return False, "htf.unavailable"
                _bridge_ok=False
                try:
                    _bridge_ok, _bridge_strength, _bridge_ctx = _v518_neutral_local_htf_bridge(
                        snap.get("df_1h"), snap.get("df_4h"), snap.get("df_15m"), snap.get("df_5m"),
                        regime, local_regime, float(htf_strength), mode or family)
                except Exception:
                    _bridge_ok=False
                _v697_htf_recovery = False
                try:
                    _rv = (getattr(c, "features_snapshot", {}) or {}).get("v692_htf_recovery") or {}
                    _rv_eff = float(_rv.get("effective")) if _rv.get("effective") is not None else None
                    _v697_htf_recovery = bool(_rv) and _rv_eff is not None and math.isfinite(_rv_eff) and _rv_eff >= 0.0 and bool(_rv.get("bridge", True))
                except Exception:
                    _v697_htf_recovery = False
                if not _bridge_ok and not _v697_htf_recovery:
                    _v702_soft_htf_ok, _v702_soft_htf_ctx = _v702_soft_htf_alignment_allowed(
                        c, family=family, strategy_mode=mode, regime=regime, local_regime=local_regime,
                        severity=severity, htf_state=str(snap.get("htf_state", "")),
                        htf_strength=htf_strength, htf_reason=str(snap.get("htf_reason", "")), snapshot=snap)
                    if not _v702_soft_htf_ok:
                        return False,"htf.core_not_aligned"
                    STATS["v702_htf_soft_alignment_passes"] = int(STATS.get("v702_htf_soft_alignment_passes", 0) or 0) + 1
                    snap["v702_htf_soft_context"] = dict(_v702_soft_htf_ctx)
                    LifecycleTrace.record(trace_id, "V702_HTF_SOFT_CONTEXT_PASS", dict(_v702_soft_htf_ctx))
                if _v697_htf_recovery:
                    _bridge_ok = True
            _zone=getattr(c,"zone_ref",None)
            _bos,_=MicroStructure.micro_bos_confirm(snap.get("df_5m"))
            _ms_ok,_ms_ctx=_v520_microstructure_parity(
                snap.get("df_5m"), family, mode, _zone, bos_confirmed=_bos,
                candidate_features=dict(getattr(c,"features_snapshot",{}) or {})
            )
            if not _ms_ok:
                _ms_reason = str(_ms_ctx.get("reason","structural.microstruct_parity"))
                # V654: one narrow PULLBACK structural-recovery lane. It does
                # not authorize an order; it only permits the candidate to
                # continue into the existing V587 + canonical downstream gates.
                _v654_rec_ok, _v654_rec_ctx = (False, {})
                try:
                    _v654_rec_ok, _v654_rec_ctx = _v654_pullback_structural_recovery_allowed(
                        c, snap, source="microstruct"
                    )
                except Exception:
                    _v654_rec_ok, _v654_rec_ctx = False, {}
                if _v654_rec_ok and str(family).upper() in {"PULLBACK", "MTF_PULLBACK"}:
                    STATS["v654_microstruct_recoveries"] = int(
                        STATS.get("v654_microstruct_recoveries", 0) or 0
                    ) + 1
                    _v654_merge_recovery_telemetry(_v654_rec_ctx, _ms_reason)
                    try:
                        LifecycleTrace.record(trace_id, "V654_MICROSTRUCT_RECOVERY", {
                            "symbol": sym, "family": str(family), "original_reason": _ms_reason,
                            **dict(_v654_rec_ctx or {})
                        })
                    except Exception:
                        _v647_record_suppressed_exception()
                else:
                    if _ms_reason in {"pullback_micro_uptrend", "fake_break_detected", "PULLBACK_REJECT"}:
                        _v565_note_structural_reject(sym)
                    return False, _ms_reason
            if bool(CONFIG.get("V520_PREQUAL_FAKE_BREAK_ENABLE",True)):
                try: _atr_pre=float(Indicators.atr(snap.get("df_5m"),CONFIG["ATR_PERIOD"]).iloc[-2])
                except Exception: _atr_pre=0.0
                _fb_ok,_fb_ctx=_v520_fake_break_gate(
                    snap.get("df_5m"), family=family, zone_ref=_zone, atr_value=_atr_pre
                )
                if not _fb_ok:
                    # v4.5.65 narrow structural recovery lane:
                    # only exceptional PULLBACK/MTF_PULLBACK candidates can pass
                    # this soft structural blocker; final execution gates still run.
                    _d5 = snap.get("df_5m")
                    _cp = float(_d5["close"].iloc[-2]) if _d5 is not None else None
                    _e50 = float(_d5["close"].ewm(span=50,adjust=False).mean().iloc[-2]) if _d5 is not None else None
                    _ch = _fb_ctx.get("chase_atr") if isinstance(_fb_ctx, dict) else None
                    if _v565_structural_recovery_candidate(
                        c, close_price=_cp, ema50=_e50, chase_atr=_ch
                    ):
                        STATS["v565_structural_recoveries"] = int(
                            STATS.get("v565_structural_recoveries", 0) or 0
                        ) + 1
                    else:
                        # V654: broader-than-V565 only in evidence quality, not
                        # in authority. It still requires the full current V587
                        # PULLBACK quality contract plus >=2 independent clues.
                        _v654_fb_ok, _v654_fb_ctx = (False, {})
                        try:
                            _v654_fb_ok, _v654_fb_ctx = _v654_fake_break_recovery_allowed(
                                c, snap, _fb_ctx
                            )
                        except Exception:
                            _v654_fb_ok, _v654_fb_ctx = False, {}
                        if _v654_fb_ok and str(family).upper() in {"PULLBACK", "MTF_PULLBACK"}:
                            STATS["v654_fake_break_recoveries"] = int(
                                STATS.get("v654_fake_break_recoveries", 0) or 0
                            ) + 1
                            _v654_merge_recovery_telemetry(_v654_fb_ctx, "structural.fake_break_detected")
                            try:
                                LifecycleTrace.record(trace_id, "V654_FAKE_BREAK_RECOVERY", {
                                    "symbol": sym, "family": str(family),
                                    **dict(_v654_fb_ctx or {})
                                })
                            except Exception:
                                _v647_record_suppressed_exception()
                        else:
                            return False,"structural.fake_break_detected"

        # V650 SELECTED→BUILDER PARITY — apply the same existing V587
        # PULLBACK precision contract during prequalification. This does not
        # lower quality: it moves an already-authoritative hard rejection
        # earlier, preventing candidates from becoming "selected" and then
        # disappearing inside SignalBuilder with no queue attribution.
        try:
            _family_v650 = str(getattr(c, "family", "") or "").upper()
            if (_family_v650 in ("PULLBACK", "MTF_PULLBACK")
                    and bool(CONFIG.get("V587_PULLBACK_QUALITY_ENABLE", True))
                    and callable(globals().get("_v587_pullback_quality"))):
                _q_v650 = _v587_pullback_quality(c, snap)
                # V587 returns a dict. Keep the prequal parity check type-correct
                # and fail-closed for both dict/object compatibility.
                _q_ok_v650 = (
                    bool(_q_v650.get("ok", False))
                    if isinstance(_q_v650, dict)
                    else bool(getattr(_q_v650, "ok", False))
                )
                if not _q_ok_v650:
                    _qr_v650 = (
                        str(_q_v650.get("reason", "") or "precision_contract_failed")
                        if isinstance(_q_v650, dict)
                        else str(getattr(_q_v650, "reason", "") or "precision_contract_failed")
                    )
                    STATS["v650_prequal_v587_pullback_blocks"] = int(
                        STATS.get("v650_prequal_v587_pullback_blocks", 0) or 0
                    ) + 1
                    _v455_record_prequal_reason(
                        sym,
                        f"structure.pullback_precision.{_qr_v650}",
                        stage="v587_pullback_parity",
                        context={
                            "family": _family_v650, "reason": _qr_v650,
                            "quality_contract": "V587",
                            "quality": float(_q_v650.get("quality", 0.0) or 0.0) if isinstance(_q_v650, dict) else 0.0,
                            "confirmations": int(_q_v650.get("confirmations", 0) or 0) if isinstance(_q_v650, dict) else 0,
                            "volume_ratio": _q_v650.get("volume_ratio") if isinstance(_q_v650, dict) else None,
                            "rs_5m": _q_v650.get("rs_5m") if isinstance(_q_v650, dict) else None,
                            "htf_strength": _q_v650.get("htf_strength") if isinstance(_q_v650, dict) else None,
                            "structure": _q_v650.get("structure") if isinstance(_q_v650, dict) else None,
                            "retest": _q_v650.get("retest") if isinstance(_q_v650, dict) else None,
                            "chase_atr": _q_v650.get("chase") if isinstance(_q_v650, dict) else None,
                        },
                    )
                    return False, f"structure.pullback_precision.{_qr_v650}"
        except Exception as _v650_q_exc:
            STATS["v650_prequal_v587_pullback_errors"] = int(
                STATS.get("v650_prequal_v587_pullback_errors", 0) or 0
            ) + 1
            return False, "structure.pullback_precision.unverifiable"

        try:
            _ctx_pass = _v455_prequal_context(c, snap)
            _ctx_pass["policy_allowed"] = True
            _V456_EVENTS.add("prequal_pass", _ctx_pass | {
                "symbol": sym, "family": str(getattr(c, "family", "") or ""),
                "mode": str(getattr(c, "strategy_mode", "") or ""),
            })
        except Exception:
            _v647_record_suppressed_exception()
        try:
            if str(_htf_source or "").upper() == "CACHED":
                STATS["v4513_htf_cached_prequal_passes"] = int(STATS.get("v4513_htf_cached_prequal_passes", 0) or 0) + 1
        except Exception:
            _v647_record_suppressed_exception()
        return True, "pass"
    except Exception as _e:
        _exc_type = type(_e).__name__
        _exc_msg = str(_e)[:240]
        try:
            _snap = locals().get("snap") or {}
            _ctx = dict(_v455_prequal_context(locals().get("c"), _snap) or {})
            _ctx.update({
                "trace_id": locals().get("trace_id", ""),
                "cycle_id": int(globals().get("_V517_ACTIVE_CYCLE_ID") or STATS.get("v516_cycle_id", 0) or 0),
                "exception_type": _exc_type,
                "exception_message": _exc_msg,
                "stage": _stage,
                "symbol": _sym_for_diag,
            })
            _exc_reason = f"exception.prequal:{_stage}"
            _v455_record_prequal_reason(
                _sym_for_diag, _exc_reason, stage=_stage,
                exception_type=_exc_type, context=_ctx,
            )
            # Bounded, deduplicated traceback logging: first occurrence is full;
            # repeated identical exceptions are sampled every 10th occurrence.
            _sig = f"{_sym_for_diag}|{_stage}|{_exc_type}|{_exc_msg}"
            _seen = STATS.setdefault("v669_prequal_exception_seen", {})
            _count = int(_seen.get(_sig, 0) or 0) + 1
            _seen[_sig] = _count
            if len(_seen) > 256:
                _seen.pop(next(iter(_seen)))
            if _count == 1 or _count % 10 == 0:
                logger.exception(
                    "[V669-PREQUAL-SYSTEM] stage=%s type=%s message=%s trace_id=%s symbol=%s family=%s strategy_mode=%s cycle_id=%s candle_ts=%s",
                    _stage, _exc_type, _exc_msg, _ctx.get("trace_id",""), _sym_for_diag,
                    _ctx.get("family", ""), _ctx.get("strategy_mode", ""),
                    _ctx.get("cycle_id", 0), _ctx.get("candle_ts", "")
                )
            # Populate the final ledger immediately when available.
            _v669_recorder = globals().get("_v669_record_reject_event")
            if callable(_v669_recorder):
                _v669_recorder(trace_id=_ctx.get("trace_id", ""), symbol=_sym_for_diag,
                    taxonomy="system", code=_exc_reason, stage=_stage, score=None,
                    ctx=_ctx, canonical_key=_exc_reason)
        except Exception:
            _v647_record_suppressed_exception()
        return False, f"exception.prequal:{_stage}"


def _v453_note_global_canonical(symbol: str, passed: bool, reason: str = "", gscore: float = 0.0,
                                stage: str = "PREQUAL") -> None:
    """Record canonical attribution without claiming execution occurred.

    ``stage`` is either PREQUAL (before arbitration) or EXEC (after a global
    winner reaches SignalBuilder).  Every rejection is counted for the
    starvation classifier; this is telemetry-only and never changes a gate.
    """
    try:
        st = str(stage or "PREQUAL").upper()
        if passed:
            STATS["global_canonical_pass"] = int(STATS.get("global_canonical_pass", 0) or 0) + 1
            STATS["global_to_canonical_pass"] = int(STATS.get("global_to_canonical_pass", 0) or 0) + 1
            STATS["global_canonical_last_stage"] = st
            logger.info(f"[GLOBAL->CANON:{st}] {symbol} prequal_pass=1 score={gscore:.3f}")
        else:
            STATS["global_canonical_reject"] = int(STATS.get("global_canonical_reject", 0) or 0) + 1
            STATS["global_to_canonical_reject"] = int(STATS.get("global_to_canonical_reject", 0) or 0) + 1
            bucket = _v453_reject_bucket(reason)
            STATS[f"global_reject.{bucket}"] = int(STATS.get(f"global_reject.{bucket}", 0) or 0) + 1
            try:
                V453_REJECT_REASON_HISTORY.append((MONO_NOW(), str(reason or "unknown")))
            except Exception:
                _v647_record_suppressed_exception()
            STATS["global_canonical_last_stage"] = st
            try:
                V453CanonicalScoreFloor.note_reject(bucket)
            except Exception:
                _v647_record_suppressed_exception()
            try:
                top = V453StarvationClassifier.top_reject_reasons(1)
                STATS["global_reject_reason_top"] = next(iter(top.keys()), "")
            except Exception:
                _v647_record_suppressed_exception()
            logger.info(f"[GLOBAL->CANON:{st}] {symbol} prequal=REJECT score={gscore:.3f} reason={reason}")
    except Exception:
        _v647_record_suppressed_exception()

# ---- Global elite recovery helper ------------------------------------------
def _v548_elite_recovery_capacity_ok() -> bool:
    try:
        if not bool(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_REQUIRE_LIVE_CAPACITY", True)):
            return True
        return len(ACTIVE_TRADES) < int(CONFIG.get("MAX_CONCURRENT_TRADES", 3))
    except Exception:
        return False

def _v548_elite_recovery_qualified(ranked: RankedCandidate, global_score: float):
    try:
        c=ranked.candidate
        ctx=_v540_candidate_ctx(c)
        if global_score < float(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_HARD_FLOOR",0.48)):
            return False,"global_score_floor"
        checks=(
            ("engine_score",float(ctx.get("score",0.0)),float(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_MIN_ENGINE_SCORE",90.0))),
            ("reviewed_score",float(ctx.get("reviewed_score",0.0)),float(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_MIN_REVIEWED_SCORE",90.0))),
            ("htf",float(ctx.get("htf",0.0)),float(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_MIN_HTF",90.0))),
            ("volume",float(ctx.get("vol",0.0)),float(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_MIN_VOLUME_RATIO",0.80))),
        )
        for name,val,floor in checks:
            if not math.isfinite(val) or val < floor:
                return False,name
        rs=float(ctx.get("rs",-99.0)); chase=float(ctx.get("chase",99.0))
        if not math.isfinite(rs) or rs < float(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_MIN_RS",0.0)):
            return False,"rs"
        if not math.isfinite(chase) or chase > float(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_MAX_CHASE_ATR",0.90)):
            return False,"chase"
        if str(ctx.get("tier","")).upper() not in {str(x).upper() for x in CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_ALLOWED_TIERS",())}:
            return False,"tier"
        if bool(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_REQUIRE_FRESH",True)):
            ok,reason,_=_v455_candidate_freshness_ok(getattr(c,"generated_at_ms",None))
            if not ok:
                return False,reason
        return True,"elite_recovery"
    except Exception as exc:
        return False,f"exception:{type(exc).__name__}"

def _v548_select_elite_recovery(prepared, max_count=1):
    if not bool(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_ENABLE",True)) or not _v548_elite_recovery_capacity_ok():
        return []
    out=[]; reasons={}
    for g,r in sorted(prepared,key=lambda x:x[0],reverse=True):
        ok,reason=_v548_elite_recovery_qualified(r,float(g))
        if ok:
            out.append(r)
            if len(out)>=max(1,int(max_count)):
                break
        else:
            reasons[reason]=int(reasons.get(reason,0) or 0)+1
    STATS["v548_elite_recovery_seen"]=sum(reasons.values())+len(out)
    STATS["v548_elite_recovery_selected"]=len(out)
    STATS["v548_elite_recovery_reasons"]=reasons
    return out

# v4.5.99-V605 — current-cycle global rescue.
# Uses only the current prepared/prequalified pool. It never lowers the
# hard global floor, never bypasses canonical hard gates, and never creates
# an order. Its purpose is to prevent the rescue ladder from depending on
# a cycle record that has not yet been written.
def _v605_current_cycle_rescue_pick(prepared, max_winners: int = 1):
    if not bool(CONFIG.get("V605_CURRENT_CYCLE_RESCUE_ENABLE", True)):
        return []
    try:
        if not prepared:
            return []
        hard_floor = float(CONFIG.get("V45_SCORE_HARD_FLOOR", 0.50))
        base = float(CONFIG.get("V45_SCORE_BASE", 0.54))
        l1_floor = float(CONFIG.get("V45_GLOBAL_RESCUE_MIN_SCORE_L1", 0.52))
        l2_floor = float(CONFIG.get("V45_GLOBAL_RESCUE_MIN_SCORE_L2", 0.50))
        top = float(prepared[0][0])
        if not math.isfinite(top) or top < hard_floor:
            return []

        level = _v45_rescue_level()
        zero_cycles = int(getattr(_V420State, "v606_l1_zero_cycles", 0) or 0)
        # This function is called only after primary selection produced no winner.
        if level == 1 and top >= l2_floor:
            zero_cycles += 1
            setattr(_V420State, "v606_l1_zero_cycles", zero_cycles)
            STATS["v606_l1_zero_cycles"] = zero_cycles
            if (bool(CONFIG.get("V606_L1_TO_L2_CURRENT_CYCLE_ESCALATION", True))
                    and zero_cycles >= int(CONFIG.get("V606_L1_TO_L2_ZERO_CYCLES", 2))):
                _v45_activate_rescue(2, "current_cycle_l1_to_l2_after_zero_cycles")
        elif level <= 0:
            if top >= l1_floor:
                _v45_activate_rescue(1, "current_cycle_zero_winner")
                zero_cycles = 1 if top >= l2_floor else 0
                setattr(_V420State, "v606_l1_zero_cycles", zero_cycles)
                STATS["v606_l1_zero_cycles"] = zero_cycles
            else:
                return []

        level = _v45_rescue_level()
        if level <= 0:
            return []
        floor = float(GlobalOpportunityArbiter._effective_min_score()) if "GlobalOpportunityArbiter" in globals() else base
        floor = max(hard_floor, min(base, floor))
        out, seen_symbols = [], set()
        cap = max(1, int(CONFIG.get("V605_CURRENT_CYCLE_RESCUE_MAX_PER_CYCLE", 1)))
        for g, r in prepared:
            try:
                c = r.candidate
                sym = str(getattr(c, "symbol", "") or "")
                if not sym or sym in seen_symbols or float(g) < floor:
                    continue
                try:
                    cluster = CorrelationHardCap._cluster_of(sym)
                    if cluster and sum(1 for s in ACTIVE_TRADES if s in cluster):
                        continue
                except Exception as _e:
                    try:
                        _v593_note_suppressed_exception("v605.current_rescue.correlation_check", _e)
                    except Exception:
                        logger.warning(f"[V605-CURRENT-RESCUE] correlation check failed: {_e}")
                    continue
                seen_symbols.add(sym)
                try:
                    fs = dict(getattr(c, "features_snapshot", {}) or {})
                    fs["rescue_lane"] = "current_cycle_rescue"
                    fs["rescue_level"] = int(level)
                    c = replace(c, features_snapshot=fs)
                except Exception as _mark_exc:
                    try: _v593_note_suppressed_exception("v605.current_rescue.mark_candidate", _mark_exc)
                    except Exception: pass
                out.append(r)
                if len(out) >= cap:
                    break
            except Exception as _e:
                try:
                    _v593_note_suppressed_exception("v605.current_rescue.pick", _e)
                except Exception:
                    logger.warning(f"[V605-CURRENT-RESCUE] pick failed: {_e}")
        if out:
            STATS["v605_current_cycle_rescue_selected"] = int(STATS.get("v605_current_cycle_rescue_selected", 0) or 0) + len(out)
            STATS["v605_current_cycle_rescue_last"] = {"top": top, "floor": floor, "level": level,
                "symbols": [str(x.candidate.symbol) for x in out],
                "l1_zero_cycles": int(getattr(_V420State, "v606_l1_zero_cycles", 0) or 0)}
        return out
    except Exception as exc:
        STATS["v605_current_cycle_rescue_errors"] = int(STATS.get("v605_current_cycle_rescue_errors", 0) or 0) + 1
        try:
            _v593_note_suppressed_exception("v605.current_cycle_rescue", exc)
        except Exception:
            logger.warning(f"[V605-CURRENT-RESCUE] exception: {type(exc).__name__}: {exc}")
        return []


# ---- Global market-wide arbitration ----------------------------------------
class GlobalOpportunityArbiter:
    # v4.5.34: bounded execution reserve kept separate from primary selected
    # winners so funnel telemetry remains truthful.
    _last_execution_reserve: List[RankedCandidate] = []
    _last_execution_reserve_cycle_id: int = 0

    @classmethod
    def execution_reserve(cls) -> List[RankedCandidate]:
        try:
            reserve = list(cls._last_execution_reserve or [])
            if not reserve:
                return []
            stored_cycle = int(getattr(cls, "_last_execution_reserve_cycle_id", 0) or 0)
            current_cycle = int(globals().get("_V517_ACTIVE_CYCLE_ID", 0) or 0)
            if stored_cycle <= 0 or current_cycle <= 0 or stored_cycle != current_cycle:
                return []
            return reserve
        except Exception:
            return []

    @staticmethod
    def _effective_min_score() -> float:
        """Return the single active Global Opportunity score floor (0..1)."""
        try:
            base = float(CONFIG.get("V45_SCORE_BASE", 0.54))
            levels = tuple(float(x) for x in (CONFIG.get("V45_SCORE_RECOVERY_LEVELS", (0.52, 0.50)) or ()))
            hard = float(CONFIG.get("V45_SCORE_HARD_FLOOR", 0.50))
            lvl = _v45_rescue_level() if "_v45_rescue_level" in globals() else 0
            floor = base if lvl <= 0 else levels[min(lvl, len(levels)) - 1] if levels else base
            return max(hard, min(base, floor))
        except Exception:
            # Fail-closed: malformed policy falls back to the strict base.
            return 0.54

    @staticmethod
    def _candidate_score(r: RankedCandidate) -> float:
        """Global score: preserve the candidate's validated composite as the
        dominant signal, then apply bounded execution/market-quality support.
        This prevents a strong local MSE composite from being diluted below
        the global floor merely because optional secondary features are sparse.

        v4.5.3 NOTE — two DIFFERENT scales must never be mixed:
          * Global Opportunity Score  : 0.0 .. 1.0  (ranking/arbitration ONLY)
          * Canonical Execution Score : 0 .. 100    (MIN_LIVE_SCORE=70 gate)
        A global score of 0.58 is NOT a canonical failure by itself; global
        selection is ranking only. The canonical funnel remains the final
        execution authority and no global winner may bypass a hard gate.
        """
        c = r.candidate
        f = c.features_snapshot or {}
        base = _clamp(float(r.composite), 0.0, 1.0)
        rr = _clamp(float(c.rr_ratio) / 4.0, 0.0, 1.0)
        exq = _clamp(float(f.get("execution_quality", f.get("liquidity_score", c.liquidity_score))), 0.0, 1.0)
        rs_raw = f.get("rs_quality")
        if rs_raw is None:
            rs_raw = _clamp(abs(float(f.get("rs_5m", 0.0) or 0.0)) * 10.0, 0.0, 1.0)
        rsq = _clamp(float(rs_raw), 0.0, 1.0)
        htf = _clamp(float(f.get("htf_alignment", c.regime_fit)), 0.0, 1.0)
        phase_fit = _clamp(float(f.get("phase_fit", 0.75)), 0.0, 1.0)
        local_fit = _clamp(float(f.get("local_fit", 0.75)), 0.0, 1.0)
        retest = _clamp(float(f.get("retest_quality", 0.5)), 0.0, 1.0)
        structure = _clamp(float(f.get("structure_quality", 0.6)), 0.0, 1.0)
        volume = _clamp(float(f.get("volume_quality", 0.5)), 0.0, 1.0)
        regime_fit = _clamp(float(c.regime_fit), 0.0, 1.0)

        # Secondary support quality is intentionally bounded.
        support = (
            0.18 * rr +
            0.18 * exq +
            0.15 * rsq +
            0.16 * htf +
            0.10 * regime_fit +
            0.09 * phase_fit +
            0.07 * local_fit +
            0.04 * retest +
            0.02 * structure +
            0.01 * volume
        )

        score = 0.72 * base + 0.28 * _clamp(support / 1.0, 0.0, 1.0)

        try:
            session_adj = SessionQualityModel.adjustment(
                c.strategy_mode or c.family,
                datetime.now(timezone.utc).hour,
            )
            score += max(-0.02, min(0.02, session_adj / 150.0))
        except Exception:
            _v647_record_suppressed_exception()

        chase = max(0.0, float(f.get("chase_atr", 0.0) or 0.0))
        score -= min(
            0.06,
            chase * float(CONFIG.get("V45_GLOBAL_CHASE_PENALTY", 0.06)) / 1.5,
        )
        if bool(f.get("near_miss_recovered", False)):
            score += float(CONFIG.get("V45_GLOBAL_NEARMISS_BONUS", 0.01))
        # v4.5.9: bounded preference for high-recall candidates that already
        # passed their own detector. This is a ranking aid, not a hard-gate
        # bypass; canonical execution remains unchanged.
        if _v459_low_target_mode(getattr(c, "strategy_mode", ""), getattr(c, "family", "")):
            score += min(0.02, max(0.0, float(CONFIG.get("V459_LOW_TARGET_COMPOSITE_BONUS",0.012))))
        if str(getattr(c, "strategy_mode", "") or "").upper() == "OPPORTUNITY_SCOUT":
            score += min(0.01, max(0.0, float(CONFIG.get("V521_SCOUT_GLOBAL_BONUS",0.006))))

        # V702 FINAL AUDIT: improve selected-trade quality without increasing
        # strictness. This is a ranking-only bonus for PULLBACK candidates that
        # have already survived the canonical hard precision contract. It uses
        # the existing holistic setup-quality value rather than adding a new
        # rejection condition. A candidate at the hard floor gets no bonus; the
        # bonus grows smoothly only toward exceptional quality and is capped at
        # 1 percentage point of the global 0..1 score.
        if bool(CONFIG.get("V702_PB_RANK_QUALITY_BONUS_ENABLE", True)):
            try:
                _sm = str(getattr(c, "strategy_mode", "") or getattr(c, "family", "") or "").upper()
                if _sm in {"PULLBACK", "MTF_PULLBACK"}:
                    _q100 = f.get("v643_canonical_quality", f.get("v587_setup_quality"))
                    if _q100 is not None:
                        _q100 = float(_q100)
                        if math.isfinite(_q100):
                            _q_floor = float(CONFIG.get("V702_PB_RANK_QUALITY_FLOOR", 78.0))
                            _q_max = max(_q_floor + 1e-9, 100.0)
                            _qb = _clamp((_q100 - _q_floor) / (_q_max - _q_floor), 0.0, 1.0)
                            _bonus = _qb * min(0.01, max(0.0, float(CONFIG.get("V702_PB_RANK_QUALITY_BONUS_MAX", 0.010))))
                            if _bonus > 0.0:
                                score += _bonus
                                STATS["v702_pb_rank_quality_bonus_applied"] = int(STATS.get("v702_pb_rank_quality_bonus_applied", 0) or 0) + 1
            except Exception:
                _v647_record_suppressed_exception()
        return _clamp(score, 0.0, 1.0)

    @classmethod
    def select(cls, ranked: List[RankedCandidate], max_winners: int = 3) -> List[RankedCandidate]:
        if not ranked:
            # v4.5.54: clear cycle-local ranking facts so Starvation/Global-Trace
            # cannot reuse the previous cycle's ranked/top score and incorrectly
            # label the current cycle as SCORE starvation.
            STATS["v45_global_ranked"] = 0
            STATS["v45_global_prefinal_eligible"] = 0
            STATS["global_prefinal_eligible"] = 0
            STATS["v45_global_top_score"] = 0.0
            STATS["v548_global_score_gap_to_floor"] = float(cls._effective_min_score())
            STATS["v548_elite_recovery_seen"] = 0
            STATS["v548_elite_recovery_selected"] = 0
            STATS["v45_global_reject_reason.empty_pool"]=STATS.get("v45_global_reject_reason.empty_pool",0)+1
            return []
        min_score=cls._effective_min_score()
        prepared=[]
        for r in ranked:
            try:
                _fresh_ok, _fresh_reason, age_sec = _v455_candidate_freshness_ok(
                    getattr(r.candidate, "generated_at_ms", None)
                )
                if not _fresh_ok:
                    if _fresh_reason == "freshness.unverifiable":
                        STATS["v45_rejected_unverifiable_timestamp"] = int(STATS.get("v45_rejected_unverifiable_timestamp", 0) or 0) + 1
                        try: _v516_record_selection_event("SELECTION", "freshness_unverifiable", r)
                        except Exception: pass
                        STATS["v45_global_reject_reason.freshness_unverifiable"] = int(STATS.get("v45_global_reject_reason.freshness_unverifiable", 0) or 0) + 1
                    else:
                        STATS["v45_rejected_stale"] = int(STATS.get("v45_rejected_stale",0) or 0) + 1
                        try: _v516_record_selection_event("SELECTION", "stale", r)
                        except Exception: pass
                        STATS["v45_global_reject_reason.stale"] = int(STATS.get("v45_global_reject_reason.stale",0) or 0) + 1
                    continue
                g=cls._candidate_score(r)
                prepared.append((g,r))
            except Exception as e:
                STATS["v45_global_reject_reason.invalid_score"] = STATS.get("v45_global_reject_reason.invalid_score",0)+1
                logger.debug(f"[V45-Global] candidate scoring suppressed: {e}")
        prepared.sort(key=lambda x:x[0], reverse=True)
        STATS["v45_global_ranked"]=len(prepared)
        STATS["global_ranked"]=len(prepared)
        # v4.5.6 FIX: Global arbitration accounting is cumulative in its own
        # namespace.  Never write Global ranking counts into mse_ranked.
        STATS["global_ranked_cumulative"] = int(STATS.get("global_ranked_cumulative", 0) or 0) + len(prepared)
        STATS["v45_global_min_score"]=min_score
        STATS["v548_global_relaxed_active"] = bool(_v45_rescue_level() > 0)
        if prepared:
            STATS["v45_global_top_score"]=prepared[0][0]
            STATS["v548_global_score_gap_to_floor"]=float(max(0.0,min_score-prepared[0][0]))
        else:
            STATS["v548_global_score_gap_to_floor"]=float(min_score)
        selected=[]; selected_symbols=set(); selected_families=defaultdict(int)
        selected_hr_families=defaultdict(int); selected_hr_modes=set()
        rejected_low=0; rejected_family=0; rejected_corr=0; rejected_symbol=0; rejected_diversity=0
        prefinal_eligible = sum(1 for g, _ in prepared if g >= min_score)
        STATS["v45_global_prefinal_eligible"] = prefinal_eligible
        STATS["global_prefinal_eligible"] = prefinal_eligible

        # v4.5.34: bounded execution reserve. These candidates are fresh,
        # prequalified and above the same global quality floor. Diversity and
        # correlation preferences do not populate the reserve; canonical
        # execution remains the final authority.
        cls._last_execution_reserve = []
        if bool(CONFIG.get("V534_EXECUTION_RESERVE_ENABLE", True)):
            try:
                _reserve_max = max(0, int(CONFIG.get("V534_EXECUTION_RESERVE_MAX", 10)))
                _seen_reserve = set()
                for _g_res, _r_res in prepared:
                    _c_res = _r_res.candidate
                    _sym_res = str(_c_res.symbol)
                    _fam_res = str(_c_res.family or _c_res.strategy_mode).upper()
                    _floor_res = min_score
                    if _v459_low_target_mode(getattr(_c_res,"strategy_mode",""), _fam_res):
                        _floor_res = max(float(CONFIG.get("V45_SCORE_HARD_FLOOR", 0.50)),
                                         min(min_score, float(CONFIG.get("V459_LOW_TARGET_GLOBAL_MIN_SCORE",0.51))))
                    if _g_res < _floor_res or _sym_res in _seen_reserve:
                        continue
                    _seen_reserve.add(_sym_res)
                    cls._last_execution_reserve.append(_r_res)
                    if len(cls._last_execution_reserve) >= _reserve_max:
                        break
            except Exception as _res_e:
                cls._last_execution_reserve = []
                STATS["v534_reserve_build_errors"] = int(STATS.get("v534_reserve_build_errors",0) or 0) + 1
                logger.debug(f"[V534-Reserve] build suppressed: {_res_e}")
        try:
            cls._last_execution_reserve_cycle_id = int(globals().get("_V517_ACTIVE_CYCLE_ID", 0) or 0) if cls._last_execution_reserve else 0
        except Exception:
            cls._last_execution_reserve_cycle_id = 0
        STATS["v534_reserve_count"] = len(cls._last_execution_reserve)
        try:
            STATS["v534_reserve_symbols"] = [str(x.candidate.symbol) for x in cls._last_execution_reserve]
        except Exception:
            STATS["v534_reserve_symbols"] = []

        for g,r in prepared:
            c=r.candidate; sym=c.symbol; fam=str(c.family or c.strategy_mode).upper()
            _candidate_floor = min_score
            if _v459_low_target_mode(getattr(c,"strategy_mode",""), fam):
                _candidate_floor = max(float(CONFIG.get("V45_SCORE_HARD_FLOOR", 0.50)),
                                       min(min_score, float(CONFIG.get("V459_LOW_TARGET_GLOBAL_MIN_SCORE",0.51))))
            if g < _candidate_floor:
                rejected_low+=1
                try: _v516_record_selection_event("SELECTION", "low_score", r, extra={"floor": float(_candidate_floor)})
                except Exception: pass
                continue
            if sym in selected_symbols:
                rejected_symbol+=1
                try: _v516_record_selection_event("SELECTION", "same_symbol", r)
                except Exception: pass
                continue
            adjusted=g
            _is_hr = _v459_low_target_mode(getattr(c,"strategy_mode",""), fam)
            if bool(CONFIG.get("V459_DIVERSITY_ENABLE", True)) and selected:
                # Small preference for a new family; bounded so score remains dominant.
                if selected_families[fam] == 0:
                    adjusted += min(0.02, max(0.0, float(CONFIG.get("V459_DIVERSITY_BONUS",0.008))))
                if _is_hr:
                    _hr_max = max(1, int(CONFIG.get("V459_HIGH_RECALL_MAX_PER_FAMILY",1)))
                    if selected_hr_families[fam] >= _hr_max:
                        rejected_diversity += 1
                        try: _v516_record_selection_event("SELECTION", "high_recall_family_cap", r)
                        except Exception: pass
                        continue
            if selected_families[fam]>=1 and len(prepared)>1:
                adjusted -= float(CONFIG.get("V45_GLOBAL_FAMILY_DUP_PENALTY",.02))
                if adjusted < _candidate_floor:
                    rejected_family+=1
                    try: _v516_record_selection_event("SELECTION", "family_dup", r, extra={"adjusted": float(adjusted), "floor": float(_candidate_floor)})
                    except Exception: pass
                    continue
            try:
                cluster=CorrelationHardCap._cluster_of(sym)
                if cluster:
                    overlap=sum(1 for s in ACTIVE_TRADES if s in cluster)
                    if overlap:
                        adjusted -= min(float(CONFIG.get("V45_GLOBAL_CORRELATION_PENALTY",.035)),
                                        float(CONFIG.get("V45_GLOBAL_CORRELATION_PENALTY",.035))*overlap)
                        if adjusted < _candidate_floor:
                            rejected_corr+=1
                            try: _v516_record_selection_event("SELECTION", "correlation", r, extra={"adjusted": float(adjusted), "floor": float(_candidate_floor)})
                            except Exception: pass
                            continue
            except Exception:
                _v647_record_suppressed_exception()
            if adjusted < _candidate_floor:
                rejected_low+=1
                try: _v516_record_selection_event("SELECTION", "low_score_adjusted", r, extra={"adjusted": float(adjusted), "floor": float(_candidate_floor)})
                except Exception: pass
                continue
            selected.append(r); selected_symbols.add(sym); selected_families[fam]+=1
            if _is_hr:
                selected_hr_families[fam] += 1
                selected_hr_modes.add(str(c.strategy_mode or c.family).upper())
            _sel_family = str(c.family or c.strategy_mode).upper()
            STATS[f"v45_global_selected_strategy.{str(c.strategy_mode or c.family)}"] = STATS.get(f"v45_global_selected_strategy.{str(c.strategy_mode or c.family)}",0)+1
            try:
                _V457_FAMILY_SYMBOL_MAP[str(sym)] = _sel_family
                _V456_EVENTS.add("family_selected", {
                    "symbol": str(sym), "family": _sel_family,
                    "mode": str(c.strategy_mode or ""), "score": float(g),
                })
            except Exception:
                _v647_record_suppressed_exception()
            if len(selected)>=max(1,int(max_winners)):
                break
        # v4.5.48: bounded elite recovery when prequalification succeeded but
        # normal global arbitration selected nothing. Canonical SignalBuilder
        # remains the only live-entry authority.
        if not selected and bool(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_ENABLE",True)):
            try:
                _elite_recovery=_v548_select_elite_recovery(
                    prepared,
                    int(CONFIG.get("V548_GLOBAL_ELITE_RECOVERY_MAX_PER_CYCLE",1)),
                )
                if _elite_recovery:
                    selected=_elite_recovery[:max(1,int(max_winners))]
                    for _er in selected:
                        _ec=_er.candidate
                        _efam=str(_ec.family or _ec.strategy_mode).upper()
                        selected_symbols.add(_ec.symbol); selected_families[_efam]+=1
                        STATS[f"v45_global_selected_strategy.{str(_ec.strategy_mode or _ec.family)}"] = STATS.get(f"v45_global_selected_strategy.{str(_ec.strategy_mode or _ec.family)}",0)+1
                    STATS["v548_global_elite_recovery_fired"]=int(STATS.get("v548_global_elite_recovery_fired",0) or 0)+len(selected)
                    logger.warning(f"[V548-ELITE-RECOVERY] selected={len(selected)} top_global={prepared[0][0] if prepared else 0.0:.3f}")
            except Exception as _elite_exc:
                STATS["v548_global_elite_recovery_errors"]=int(STATS.get("v548_global_elite_recovery_errors",0) or 0)+1
                logger.debug(f"[V548-ELITE-RECOVERY] suppressed: {_elite_exc}")

        # v4.5.99-V605: FINAL bounded current-cycle rescue. Unlike the
        # legacy maybe_rescue() call outside this method, this one sees the
        # candidate pool produced in THIS cycle before note_cycle() is called.
        # It uses the same hard global floor and existing rescue ladder only.
        if not selected:
            try:
                _current_rescue = _v605_current_cycle_rescue_pick(
                    prepared, max_winners=max_winners
                )
                if _current_rescue:
                    selected = _current_rescue[:max(1, int(max_winners))]
                    for _cr in selected:
                        _cc = _cr.candidate
                        _cfam = str(_cc.family or _cc.strategy_mode).upper()
                        selected_symbols.add(_cc.symbol)
                        selected_families[_cfam] += 1
                        STATS[f"v45_global_selected_strategy.{str(_cc.strategy_mode or _cc.family)}"] = STATS.get(
                            f"v45_global_selected_strategy.{str(_cc.strategy_mode or _cc.family)}", 0
                        ) + 1
                    STATS["v605_current_cycle_rescue_fired"] = int(
                        STATS.get("v605_current_cycle_rescue_fired", 0) or 0
                    ) + len(selected)
                    logger.warning(
                        f"[V605-CURRENT-RESCUE] selected={len(selected)} "
                        f"top_global={prepared[0][0] if prepared else 0.0:.3f} "
                        f"floor={float(GlobalOpportunityArbiter._effective_min_score()):.3f}"
                    )
            except Exception as _cur_exc:
                STATS["v605_current_cycle_rescue_errors"] = int(
                    STATS.get("v605_current_cycle_rescue_errors", 0) or 0
                ) + 1
                logger.debug(f"[V605-CURRENT-RESCUE] selection suppressed: {_cur_exc}")

        STATS["v45_global_winners"]=len(selected)
        STATS["global_selected"]=len(selected)
        STATS["global_selected_cumulative"] = int(STATS.get("global_selected_cumulative", 0) or 0) + len(selected)
        STATS["v45_global_reject_reason.low_score"]=rejected_low
        STATS["v45_global_reject_reason.family_dup"]=rejected_family
        STATS["v45_global_reject_reason.correlation"]=rejected_corr
        STATS["v45_global_reject_reason.same_symbol"]=rejected_symbol
        STATS["v45_global_reject_reason.diversity"]=rejected_diversity
        STATS["v459_global_selected_hr"] = int(STATS.get("v459_global_selected_hr",0) or 0) + len(selected_hr_modes)
        return selected


class GlobalOpportunityBrain:
    @staticmethod
    def _snapshot(symbol: str, md: Dict[str, Any]) -> Dict[str, Any]:
        df1h=md.get("df_1h"); df15=md.get("df_15m"); df5=md.get("df_5m")
        htf=50.0
        try:
            if df1h is not None and len(df1h)>=60:
                close=float(df1h["close"].iloc[-2])
                ema50=float(df1h["close"].ewm(span=50,adjust=False).mean().iloc[-2])
                ema200=float(df1h["close"].ewm(span=200,adjust=False).mean().iloc[-2])
                htf=100.0 if close>=ema200 and ema50>=ema200 else 55.0 if close>=ema200*.99 else 40.0
                if close>ema50>ema200: htf=min(100.0,htf+10.0)
        except Exception:
            _v647_record_suppressed_exception()
        tier=LiquidityTier.classify(float(md.get("quote_vol_24h",0.0) or 0.0))
        regime=str(STATS.get("v425_regime_current", STATS.get("regime_current","NEUTRAL")) or "NEUTRAL")
        try:
            local = V425LocalRegime.classify(regime, md.get("df_15m"), md.get("df_5m"))
        except Exception:
            local = "LOCAL_BEARISH"
        htf_state="UNKNOWN"; htf_pass=False; htf_reason="snapshot_unavailable"
        try:
            if bool(CONFIG.get("V520_PREQUAL_EXACT_HTF_ENABLE",True)) and df1h is not None:
                htf_pass, htf_state, htf, htf_reason = HTFGrader.grade(df1h, label=symbol)
                htf=float(htf) if htf is not None else 0.0
        except Exception:
            htf_pass=False; htf_state="ERROR"; htf_reason="htf_grade_exception"
        phase="UNKNOWN"
        try:
            phase_obj=MarketPhaseDetector.detect(dict(md, symbol=symbol, macro_regime=regime, local_regime=local))
            phase=str(getattr(phase_obj,"value",phase_obj) or "UNKNOWN").upper()
        except Exception:
            _v647_record_suppressed_exception()
        _closed_ts=""
        try:
            if df5 is not None and len(df5)>=2: _closed_ts=str(_v669_context_scalar(df5.index[-2],field="candle_ts"))
        except Exception: _closed_ts=""
        try:
            _snapshot_id=hashlib.sha256(f"{symbol}|{_closed_ts}|{regime}|{local}|{phase}|{float(htf):.6f}|{tier}".encode("utf-8","replace")).hexdigest()[:20]
        except Exception: _snapshot_id=""
        return {
            **md, "symbol":symbol, "tier":tier, "regime":regime,
            "macro_regime":regime, "local_regime":local, "market_phase":{"phase":phase},
            "closed_candle_ts":_closed_ts, "candle_ts":_closed_ts, "snapshot_id":_snapshot_id,
            "htf_strength":htf, "htf_pass":bool(htf_pass), "htf_state":str(htf_state), "htf_reason":str(htf_reason),
            "regime_fit":.80 if regime=="BULLISH" else .65 if regime=="NEUTRAL" else .55,
            "liquidity_score":_clamp(float(md.get("quote_vol_24h",0.0))/20_000_000,0,1),
            "bearish_severity":str(STATS.get("v425_macro_severity","NORMAL")),
        }

    @classmethod
    def rank_and_select(cls, market_data_map: Dict[str, Dict[str, Any]]) -> List[RankedCandidate]:
        global _V702_ACTIVE_SELECTION_SNAPSHOTS
        # Never retain the previous cycle's DataFrames when a scan is empty.
        try:
            _V702_ACTIVE_SELECTION_SNAPSHOTS.clear()
        except Exception:
            pass
        if not market_data_map:
            return []
        all_ranked=[]
        local_count=0
        generated_total = 0
        hard_valid_total = 0
        raw_ranked_total = 0
        rank_rejected_total = 0
        local_cap_dropped = 0
        local_duplicate_strategy_dropped = 0
        per_mode_generated = defaultdict(int)
        try:
            _MSEState.reset_run_counts()
        except Exception:
            _v647_record_suppressed_exception()
        # v4.5.12 ROOT FIX:
        # MSE candidate generation uses the enriched _snapshot(). The previous
        # implementation later rebuilt snap_by_symbol from raw market_data_map,
        # causing regime/local/phase/HTF coherence drift at prequalification.
        # Reuse the EXACT snapshot the engines already saw. No new fetches.
        prequal_snapshots: Dict[str, Dict[str, Any]] = {}
        for symbol,md in market_data_map.items():
            snap=cls._snapshot(symbol,md)
            _coh_builder = globals().get("_coherence_prepare_cycle_snapshot")
            if callable(_coh_builder):
                try:
                    _coh_cs = _coh_builder(symbol, snap)
                    STATS["coherence_cycle_snapshots_built"] = int(STATS.get("coherence_cycle_snapshots_built", 0) or 0) + 1
                    if isinstance(_coh_cs, dict):
                        snap["coherence_snapshot_id"] = _coh_cs.get("snapshot_id")
                except Exception as _coh_exc:
                    STATS["coherence_cycle_snapshot_errors"] = int(STATS.get("coherence_cycle_snapshot_errors", 0) or 0) + 1
                    logger.debug("[COHERENCE] cycle snapshot mirror suppressed: %s", _coh_exc)
            prequal_snapshots[str(symbol)] = snap
            all_cands=[]
            for eng in _MSE_ENGINES:
                try:
                    all_cands.extend(MultiStrategyEngine._run_engine_safe(eng,snap))
                except Exception:
                    STATS["v45_engine_errors"]=STATS.get("v45_engine_errors",0)+1
            generated_total += len(all_cands)
            hard_valid_total += sum(1 for _c in all_cands if bool((_c.features_snapshot or {}).get("hard_valid", True)))
            try:
                _origin_ctx={
                    "macro_regime":snap.get("macro_regime",snap.get("regime","")),
                    "local_regime":snap.get("local_regime",""),
                    "market_phase":(snap.get("market_phase") or {}).get("phase","") if isinstance(snap.get("market_phase"),dict) else snap.get("market_phase",""),
                    "bearish_severity":snap.get("bearish_severity",""),
                    "htf_strength":snap.get("htf_strength"),
                    "liquidity_tier":snap.get("tier",""),
                    "candle_ts":snap.get("candle_ts",snap.get("closed_candle_ts","")),
                    "snapshot_id":snap.get("snapshot_id",""),
                    "cycle_id": int(
                        globals().get("_V517_ACTIVE_CYCLE_ID")
                        or STATS.get("v681_runtime_cycle_id", 0)
                        or STATS.get("v516_cycle_id", 0)
                        or STATS.get("v669_current_cycle_id", 0)
                        or STATS.get("v669_last_cycle_id", 0)
                        or 0
                    ),
                }
                _enriched=[]
                for _c in all_cands:
                    try:
                        _fs=dict(getattr(_c,"features_snapshot",{}) or {})
                        _fs["v669_origin_context"]=dict(_origin_ctx)
                        for _kk,_vv in _origin_ctx.items():
                            if _kk not in _fs or _fs.get(_kk) in (None,""): _fs[_kk]=_vv
                        _enriched.append(replace(_c, features_snapshot=_fs))
                    except Exception:
                        _v647_record_suppressed_exception()
                        _enriched.append(_c)
                all_cands=_enriched
            except Exception: _v647_record_suppressed_exception()
            for _c in all_cands:
                try:
                    per_mode_generated[str(_c.strategy_mode or _c.family or "UNKNOWN").upper()] += 1
                except Exception:
                    per_mode_generated["UNKNOWN"] += 1
            if not all_cands:
                continue
            # V702 FINAL — exact same-cycle/same-candle/same-recipe coalescing is
            # performed BEFORE composite ranking. The later V653 boundary remains
            # as a defensive secondary deduplication stage.
            try:
                _coalesced, _coalesced_removed = _v702_coalesce_same_cycle_candidates(all_cands, snap)
                if _coalesced_removed:
                    STATS["v702_same_cycle_coalesced_pre_rank"] = int(STATS.get("v702_same_cycle_coalesced_pre_rank", 0) or 0) + int(_coalesced_removed)
                all_cands = _coalesced
            except Exception:
                _v647_record_suppressed_exception()
            ranked=CompositeRankingEngine.rank(all_cands)
            # V654: actually apply V653 same-setup dedup at the global ranking
            # boundary. Per-symbol scope is intentional; different closed
            # candles remain distinct setups.
            try:
                if callable(globals().get("_v653_dedup_candidates")):
                    _before_v654_dedup = len(ranked)
                    _dedup_raw = [getattr(_r, "candidate", _r) for _r in ranked]
                    _dedup_kept = _v653_dedup_candidates(_dedup_raw, snap)
                    _keep_ids = {id(x) for x in _dedup_kept}
                    ranked = [r for r in ranked if id(getattr(r, "candidate", r)) in _keep_ids]
                    STATS["v654_rank_dedup_removed"] = int(
                        STATS.get("v654_rank_dedup_removed", 0) or 0
                    ) + max(0, _before_v654_dedup - len(ranked))
            except Exception:
                _v647_record_suppressed_exception()
            raw_ranked_total += len(ranked)
            rank_rejected_total += max(0, len(all_cands) - len(ranked))
            # Bounded near-miss re-evaluation: if a previously queued candidate
            # returns on a later closed candle with improved quality, mark it as
            # recovered so the global arbiter can give it the small configured
            # recovery bonus. The hard final funnel remains authoritative.
            try:
                for _idx, _r in enumerate(ranked):
                    _sm=str(_r.candidate.strategy_mode or _r.candidate.family).upper()
                    _queued=NearMissOpportunityQueue.contains(_r.candidate.symbol,_sm)
                    if _queued:
                        _fs_nm = dict(getattr(_r.candidate, "features_snapshot", {}) or {})
                        _fs_nm["near_miss_recovered"] = True
                        _c_nm = _v672_set_fs(_r.candidate, _fs_nm) if "_v672_set_fs" in globals() else _r.candidate
                        ranked[_idx] = replace(_r, candidate=_c_nm)
                        NearMissOpportunityQueue.mark_recovered(_c_nm.symbol,_sm)
            except Exception:
                _v647_record_suppressed_exception()
            # V699 actual strategy-aware retention: family caps are applied in
            # the production ranking path, not only in the recall helper.  This
            # prevents one mode/family from consuming the entire symbol pool while
            # still retaining an elite candidate and bounded near-miss diversity.
            _legacy_limit=max(1,int(CONFIG.get("V45_GLOBAL_MAX_LOCAL_PER_SYMBOL",3)))
            _elastic_cap=int(CONFIG.get("V4513_ELASTIC_LOCAL_RETENTION_MAX",5))
            _local_limit=min(max(_legacy_limit,2), max(2, _elastic_cap))
            if bool(CONFIG.get("V699_FAMILY_FAIRNESS_ENABLE", True)):
                _local_limit=min(int(CONFIG.get("V699_GLOBAL_CYCLE_CAP",24)), max(_local_limit, 5))
            _ranked_sorted=list(ranked)
            _distinct_modes=len(set(str(x.candidate.strategy_mode or x.candidate.family or "UNKNOWN").upper() for x in _ranked_sorted))
            STATS["v4513_last_local_limit"]=_local_limit
            STATS["v4513_last_distinct_modes"]=_distinct_modes
            _selected_local=[]
            _seen_keys=set()
            _family_counts=defaultdict(int)
            # Pass 1: elite per family, preserving ranking order.
            for r in _ranked_sorted:
                c=r.candidate
                sm=str(c.strategy_mode or c.family or "UNKNOWN").upper()
                fam=_v699_family_of(sm) if "_v699_family_of" in globals() else str(c.family or sm).upper()
                key=(sm, str(getattr(r,"generated_at_ms",getattr(c,"generated_at_ms",0))))
                if key in _seen_keys or _family_counts[fam] >= 2:
                    continue
                _selected_local.append(r); _seen_keys.add(key); _family_counts[fam]+=1
                if len(_selected_local) >= _local_limit:
                    break
            # Pass 2: one bounded cross-family near-miss/alternate if capacity remains.
            if len(_selected_local) < _local_limit:
                _floor_now=float(STATS.get("v453_effective_canonical_floor",CONFIG.get("MIN_LIVE_SCORE",70)) or 70)
                for r in _ranked_sorted:
                    if r in _selected_local:
                        continue
                    c=r.candidate
                    sm=str(c.strategy_mode or c.family or "UNKNOWN").upper()
                    fam=_v699_family_of(sm) if "_v699_family_of" in globals() else str(c.family or sm).upper()
                    score=float(getattr(c,"engine_score",0.0) or 0.0)*100.0
                    if (score < _floor_now and (_floor_now-score) <= float(CONFIG.get("V699_RECALL_SCORE_GAP_MAX",3.0))) or fam not in _family_counts:
                        _selected_local.append(r); _family_counts[fam]+=1
                    if len(_selected_local) >= _local_limit:
                        break
            if len(_selected_local) < len(_ranked_sorted):
                local_cap_dropped += max(0, len(_ranked_sorted)-len(_selected_local))
                try:
                    for _drop in _ranked_sorted[len(_selected_local):]:
                        _v516_record_selection_event("POOL_RANK", "family_aware_retention", _drop, extra={"limit": int(_local_limit)})
                except Exception:
                    pass
            local_duplicate_strategy_dropped += max(0, len(_ranked_sorted)-len({(str(x.candidate.strategy_mode or x.candidate.family or "UNKNOWN").upper(), str(getattr(x.candidate,"generated_at_ms",0))) for x in _ranked_sorted}))
            all_ranked.extend(_selected_local)
            local_count += len(_selected_local)
        STATS["v45_global_local_candidates"]=local_count
        STATS["v45_global_pool"]=len(all_ranked)
        STATS["v45_global_generated"]=generated_total
        STATS["v45_global_hard_valid"]=hard_valid_total
        STATS["v45_global_raw_ranked"]=raw_ranked_total
        # V648: cycle-local MSE funnel telemetry is intentionally separate from
        # the legacy canonical G/E/Q/S counters.
        STATS["v648_cycle_mse_generated"] = int(generated_total)
        STATS["v648_cycle_mse_raw_ranked"] = int(raw_ranked_total)
        STATS["v648_cycle_mse_ranked"] = int(len(all_ranked))
        STATS["v45_global_rank_rejected"]=rank_rejected_total
        STATS["v45_global_cap_dropped"]=local_cap_dropped
        STATS["v45_global_duplicate_strategy_dropped"]=local_duplicate_strategy_dropped
        STATS["v4513_elastic_local_retention_enabled"]=bool(CONFIG.get("V4513_ELASTIC_LOCAL_RETENTION_ENABLE",True))
        STATS["v4513_elastic_local_retention_max"]=int(CONFIG.get("V4513_ELASTIC_LOCAL_RETENTION_MAX",5))
        STATS["v45_global_rank_coverage_pct"]=(100.0*raw_ranked_total/max(generated_total,1)) if generated_total else 0.0
        STATS["v45_global_pool_retention_pct"]=(100.0*len(all_ranked)/max(raw_ranked_total,1)) if raw_ranked_total else 0.0
        STATS["v45_global_generated_by_mode_top"] = sorted(per_mode_generated.items(), key=lambda kv:(-int(kv[1]),kv[0]))[:int(CONFIG.get("V456_FUNNEL_COVERAGE_TOP_N",5))]
        # v4.5.10 — explicit high-recall lane funnel accounting.
        try:
            STATS["v459_cycle_generated"] = sum(
                1 for _r in all_ranked if _v459_low_target_mode(
                    getattr(_r.candidate,"strategy_mode",""), getattr(_r.candidate,"family","")))
            STATS["v459_cycle_prequalified"] = 0
            STATS["v459_cycle_selected"] = 0
        except Exception:
            STATS["v459_cycle_generated"] = 0
            STATS["v459_cycle_prequalified"] = 0
            STATS["v459_cycle_selected"] = 0

        # Keep canonical MSE telemetry meaningful when the global brain is active.
        STATS["mse_generated"] = int(STATS.get("mse_generated", 0) or 0) + int(generated_total)
        STATS["mse_hard_valid"] = int(STATS.get("mse_hard_valid", 0) or 0) + int(hard_valid_total)

        # ---- v4.5.4: CANONICAL PREQUALIFICATION *BEFORE* GLOBAL ARBITRATION ----
        # Required pipeline order:
        #   MSE candidates -> canonical prequalification -> global arbitration
        #   -> final winners -> canonical execution -> queue -> send.
        # The arbiter now ranks ONLY candidates that already passed canonical
        # prequalification; the old post-arbitration "final = _prequalified"
        # correction is REMOVED. Zero new fetches: prequalification reuses the
        # SAME MSE snapshot facts the canonical funnel knows. Global remains a
        # ranking/arbitration layer ONLY; canonical execution (SignalBuilder)
        # remains the sole execution authority, one final winner per symbol.
        snap_by_symbol = dict(prequal_snapshots)
        # The R5 selector needs only snapshots for candidates that actually
        # reached the canonical prequalified pool. Keeping the entire scanned
        # universe here retains unnecessary DataFrames between ranking and
        # selection and can inflate memory on deep scans.
        _V702_ACTIVE_SELECTION_SNAPSHOTS = {}
        STATS["v702_selection_snapshot_count"] = 0
        STATS["v459_prequal_snapshot_source"] = "ENRICHED_GLOBAL_SNAPSHOT"
        STATS["v459_prequal_snapshot_count"] = int(len(snap_by_symbol))
        _max_w = int(CONFIG.get("V45_GLOBAL_MAX_WINNERS", 3))
        _prequalified: List[RankedCandidate] = []
        if CONFIG.get("V453_CANON_PREQUAL_ENABLE", True):
            for _r in all_ranked:
                try:
                    _sym = str(_r.candidate.symbol)
                    _ok, _reason = _v453_prequalify(_r, snap_by_symbol)
                    try:
                        _g = GlobalOpportunityArbiter._candidate_score(_r)
                    except Exception:
                        _g = 0.0
                    # Count EVERY candidate observation. Suppressing duplicate-symbol
                    # attribution hid the real bottleneck from the relief valve.
                    if not _ok:
                        try:
                            _v455_record_prequal_reason(
                                _sym, _reason, stage="prequal",
                                context=_v455_prequal_context(_r.candidate, snap_by_symbol.get(_sym) or {}))
                        except Exception:
                            _v647_record_suppressed_exception()
                    _v453_note_global_canonical(_sym, _ok, "" if _ok else _reason, _g, stage="PREQUAL")
                    if _ok:
                        _prequalified.append(_r)
                    else:
                        STATS["v453_prequal_rejects"] = int(STATS.get("v453_prequal_rejects", 0) or 0) + 1
                except Exception as _e:
                    try:
                        _sym = str(getattr(getattr(_r, "candidate", None), "symbol", "") or "")
                        _reason = f"exception.arbiter_prequal:{type(_e).__name__}"
                        _v455_record_prequal_reason(
                            _sym, _reason, stage="arbiter_prequal",
                            exception_type=type(_e).__name__,
                            context=_v455_prequal_context(getattr(_r, "candidate", None), snap_by_symbol.get(_sym) or {}))
                        _v453_note_global_canonical(_sym, False, _reason, 0.0, stage="PREQUAL")
                    except Exception:
                        _v647_record_suppressed_exception()
                    STATS["v453_prequal_rejects"] = int(STATS.get("v453_prequal_rejects", 0) or 0) + 1
                    continue
            _arb_pool = _prequalified
        else:
            _arb_pool = list(all_ranked)
        # Bind the R5 active snapshot registry only after canonical prequalification.
        # Every selected/recalled candidate is therefore evaluated against the
        # exact cycle snapshot that its own prequalification used.
        try:
            _V702_ACTIVE_SELECTION_SNAPSHOTS = {
                str(_r.candidate.symbol): snap_by_symbol[str(_r.candidate.symbol)]
                for _r in _arb_pool
                if getattr(_r, "candidate", None) is not None
                and str(_r.candidate.symbol) in snap_by_symbol
            }
            STATS["v702_selection_snapshot_count"] = int(len(_V702_ACTIVE_SELECTION_SNAPSHOTS))
        except Exception:
            _V702_ACTIVE_SELECTION_SNAPSHOTS = {}
            STATS["v702_selection_snapshot_count"] = 0

        STATS["v45_global_prequalified"] = len(_arb_pool)
        STATS["v45_global_last_prequalified"] = len(_arb_pool)
        STATS["v648_cycle_mse_prequalified"] = int(len(_arb_pool))
        # V684: bind eligibility to the active runtime cycle rather than the
        # process-level last-cycle display field. This prevents stale E leakage
        # after _v681_runtime_cycle_begin resets the public funnel.
        STATS["v681_runtime_cycle_prequal"] = int(len(_arb_pool))
        if len(_arb_pool) > 0:
            STATS["v684_active_cycle_has_work"] = True
        try:
            STATS["v459_cycle_prequalified"] = sum(
                1 for _r in _arb_pool if _v459_low_target_mode(
                    getattr(_r.candidate,"strategy_mode",""), getattr(_r.candidate,"family","")))
        except Exception:
            STATS["v459_cycle_prequalified"] = 0

        # Reset per-cycle R5 diagnostics while retaining explicit cumulative totals.
        for _rk in (
            "v702_selection_projected_seen", "v702_selection_projected_rejects",
            "v702_selection_projection_errors", "v702_selection_projection_unverifiable",
            "v702_selection_projection_floor_blocks",
        ):
            _prev = int(STATS.get(_rk, 0) or 0)
            STATS[f"{_rk}_total"] = int(STATS.get(f"{_rk}_total", 0) or 0) + _prev
            STATS[_rk] = 0
        # Global arbitration over the PREQUALIFIED pool only (composite,
        # execution quality, family priority, regime fit, liquidity, RR; one
        # winner per symbol; no symbol duplication).
        final = GlobalOpportunityArbiter.select(_arb_pool, _max_w)

        # If the first pass is empty but prequalified candidates exist near
        # the bounded floor, activate the rescue ladder and retry arbitration
        # once on the SAME prequalified pool. The hard execution funnel still
        # decides whether anything can trade.
        if not final and _arb_pool:
            V45GlobalFunnelState.maybe_rescue()
            final = GlobalOpportunityArbiter.select(_arb_pool, _max_w)

        # V646 RECALL WITHOUT QUALITY LOSS — one bounded elite reserve.
        # A very strong, independently verified setup may be promoted from the
        # already-prequalified pool even when global top-N competition would
        # otherwise omit it. This does NOT bypass ranking/prequalification; it
        # simply preserves one exceptional candidate for the canonical live path.
        try:
            _reserve_max = max(0, int(CONFIG.get("V646_RECALL_ELITE_RESERVE_MAX", 1)))
            if _reserve_max and _arb_pool:
                _final_syms = {str(x.candidate.symbol) for x in final}
                _reserve = []
                _reserve_candidates = sorted(
                    _arb_pool,
                    key=lambda _r: (
                        float(getattr(_r.candidate, "engine_score", 0.0) or 0.0),
                        float(getattr(_r, "composite", 0.0) or 0.0),
                    ), reverse=True)
                for _rr in _reserve_candidates:
                    _c = _rr.candidate
                    _sym = str(getattr(_c, "symbol", "") or "")
                    if not _sym or _sym in _final_syms:
                        continue
                    try:
                        _snap = snap_by_symbol.get(_sym) or {}
                        if _v646_recall_reserve_eligible(_c, _snap):
                            _rg_ok, _rg_reason, _rgated = _v702_selection_projection_route_gate(
                                _rr, _snap, "recall_reserve"
                            )
                            if not _rg_ok or _rgated is None:
                                STATS["v702_recall_selection_projection_blocks"] = int(STATS.get("v702_recall_selection_projection_blocks", 0) or 0) + 1
                                continue
                            _reserve.append(_rgated)
                            _final_syms.add(_sym)
                            STATS["v646_recall_elite_promotions"] = int(
                                STATS.get("v646_recall_elite_promotions", 0) or 0
                            ) + 1
                            break
                    except Exception:
                        continue
                if _reserve:
                    final.extend(_reserve[:_reserve_max])
        except Exception as _v646_reserve_exc:
            STATS["v646_recall_elite_errors"] = int(
                STATS.get("v646_recall_elite_errors", 0) or 0
            ) + 1
            logger.debug(f"[V646-RECALL] elite reserve suppressed: {_v646_reserve_exc}")
        # v4.5.21 ROOT STARVATION CLOSURE: retain already-prequalified
        # same-symbol alternates so a canonical rejection does not erase a
        # symbol before Q. No new fetches and no hard-gate bypass.
        try:
            V521_ALTERNATE_ROUTES.clear()
            if bool(CONFIG.get("V521_RETRY_CANONICAL_ALTERNATES", True)) and final:
                per_symbol=defaultdict(list)
                for _rr in _arb_pool:
                    per_symbol[str(_rr.candidate.symbol)].append(_rr)
                max_alt=max(0,int(CONFIG.get("V521_SCOUT_MAX_CANONICAL_FALLBACKS",2)))
                for _fw in final:
                    _sym=str(_fw.candidate.symbol)
                    alts=[]
                    seen_ids=set()
                    for _rr in sorted(per_symbol.get(_sym,[]), key=GlobalOpportunityArbiter._candidate_score, reverse=True):
                        if _rr is _fw: continue
                        _id=(str(_rr.candidate.strategy_mode or _rr.candidate.family), str(_rr.candidate.generated_at_ms))
                        if _id in seen_ids: continue
                        _ag_ok, _ag_reason, _agated = _v702_selection_projection_route_gate(
                            _rr, snap_by_symbol.get(_sym) or {}, "alternate_capture"
                        )
                        if not _ag_ok or _agated is None:
                            STATS["v702_capture_selection_projection_blocks"] = int(STATS.get("v702_capture_selection_projection_blocks", 0) or 0) + 1
                            continue
                        seen_ids.add(_id); alts.append(_agated)
                        if len(alts)>=max_alt: break
                    V521_ALTERNATE_ROUTES[_sym]=alts
                STATS["v521_alternate_symbols"] = len(V521_ALTERNATE_ROUTES)
                STATS["v521_alternate_candidates"] = sum(len(v) for v in V521_ALTERNATE_ROUTES.values())
        except Exception as _alt_e:
            STATS["v521_alternate_capture_errors"]=int(STATS.get("v521_alternate_capture_errors",0) or 0)+1
            V521_ALTERNATE_ROUTES.clear()
        # Record the best canonical-scale score observed this cycle so the
        # bounded adaptive floor can detect genuine score starvation.
        try:
            if all_ranked:
                STATS["v453_top_canonical_score"] = max(
                    float(_r.candidate.engine_score) * 100.0 for _r in all_ranked[:8])
        except Exception:
            _v647_record_suppressed_exception()
        # Advance the bounded adaptive canonical floor (70->...->62, TTL-bound,
        # auto-revert on send). Never armed by crash/kill/balance/watchdog and
        # never when liquidity/HTF/structure is the dominant reject reason.
        try:
            STATS["v453_effective_canonical_floor"] = float(V453CanonicalScoreFloor.tick())
        except Exception:
            _v647_record_suppressed_exception()

        STATS["v45_global_winners"]=len(final)
        STATS["global_selected"]=len(final)
        STATS["v648_cycle_mse_selected"] = int(len(final))
        if not final:
            logger.warning(
                f"[V548-GLOBAL-TRACE] SEL=0 prequal={len(_arb_pool)} "
                f"top_global={float(STATS.get('v45_global_top_score',0.0) or 0.0):.3f} "
                f"global_floor={float(STATS.get('v45_global_min_score',0.0) or 0.0):.3f} "
                f"gap={float(STATS.get('v548_global_score_gap_to_floor',0.0) or 0.0):.3f} "
                f"elite_seen={int(STATS.get('v548_elite_recovery_seen',0) or 0)} "
                f"elite_selected={int(STATS.get('v548_elite_recovery_selected',0) or 0)} "
                f"relaxed={int(bool(STATS.get('v548_global_relaxed_active',False)))}"
            )
        try:
            STATS["v459_cycle_selected"] = sum(
                1 for _r in final if _v459_low_target_mode(
                    getattr(_r.candidate,"strategy_mode",""), getattr(_r.candidate,"family","")))
        except Exception:
            STATS["v459_cycle_selected"] = 0
        # v4.5.3 semantics fix: global_selected is NOT execution-queued.
        # v45_global_queued now tracks the REAL canonical execution queue
        # (signals_queued) instead of mirroring len(final).
        STATS["v45_global_queued"]=int(STATS.get("signals_queued",0) or 0)
        V45GlobalFunnelState.note_cycle(
            generated_total,
            int(STATS.get("v45_global_prequalified",0) or 0),
            int(STATS.get("v45_global_ranked",0) or 0),
            len(final),
            float(STATS.get("v45_global_top_score",0.0) or 0.0),
            canonical_pass=int(STATS.get("global_canonical_pass",0) or 0),
            canonical_reject=int(STATS.get("global_canonical_reject",0) or 0),
            submitted=int(STATS.get("signals_queued",0) or 0),
            sent=int(STATS.get("signals_sent",0) or 0),
            complete=True,
            hard_valid=int(hard_valid_total),
            raw_ranked=int(raw_ranked_total),
            pool=int(len(all_ranked)),
        )
        # v4.5.14: telemetry-only opportunity quality audit.
        try:
            if bool(CONFIG.get("V514_OPPORTUNITY_AUDIT_ENABLE", True)):
                _v514_opportunity_quality_audit(float(CONFIG.get("V514_OPPORTUNITY_AUDIT_WINDOW_SEC",720.0)))
        except Exception:
            _v647_record_suppressed_exception()
        # v4.5.5/V700: keep raw retained pool and canonical rankable pool explicit.
        # The historical `v45_global_ranked` field remains available for compatibility,
        # but operator output must not present it as a post-prequal rank.
        STATS["v45_global_canonical_ranked"] = int(len(_arb_pool))
        logger.info(
            f"[V45-GLOBAL] GEN={generated_total} "
            f"PRE={int(STATS.get('v45_global_prequalified',0) or 0)} "
            f"RAW_RANK={int(STATS.get('v45_global_ranked',0) or 0)} "
            f"RANK={int(len(_arb_pool))} "
            f"SEL={len(final)} "
            f"CANON_PASS={int(STATS.get('global_canonical_pass',0) or 0)} "
            f"CANON_REJ={int(STATS.get('global_canonical_reject',0) or 0)} "
            f"Q={int(STATS.get('signals_queued',0) or 0)} "
            f"S={int(STATS.get('signals_sent',0) or 0)}"
        )
        if final:
            # Any successful global selection is a reason to revert rescue;
            # actual execution can still fail closed downstream.
            if _v45_rescue_level() > 0:
                _V420State.rescue_level = 0
                _V420State.rescue_until_ts = 0.0
                _V420State.relaxed_mode_until_ts = 0.0
                STATS["v45_rescue_level"] = 0

        # v4.5.6 FIX: DO NOT merge Global arbitration counts into MSE counts.
        # mse_ranked/mse_winners belong exclusively to MultiStrategyEngine;
        # global_ranked_cumulative/global_selected_cumulative belong to the
        # GlobalOpportunityArbiter.  Mixing these values corrupts accounting
        # and can create false PIPELINE-ACCOUNTING-VIOLATION diagnostics.
        STATS["v45_global_scanned"]=len(market_data_map)
        # V700 audit closure: runtime-cycle funnel owns the CANONICAL rank stage.
        # `raw_ranked_total` / `all_ranked` remain explicit raw/pool diagnostics;
        # the public RANK counter must never pretend raw retained candidates have
        # passed canonical prequalification.
        STATS["v681_runtime_cycle_hard_valid"] = int(max(0, hard_valid_total))
        STATS["v681_runtime_cycle_raw_ranked"] = int(max(0, raw_ranked_total))
        STATS["v681_runtime_cycle_pool_ranked"] = int(max(0, len(all_ranked)))
        # Snapshot registry is only needed during this selection/recall cycle.
        # Clear it before returning so large DataFrames cannot be retained until
        # the next scan.
        try:
            _V702_ACTIVE_SELECTION_SNAPSHOTS.clear()
        except Exception:
            pass
        # Ranked is owned by the canonical cycle aggregator below; do not write
        # it here and then add it again, which would double-count the current cycle.
        STATS["v681_runtime_cycle_prequal"] = int(max(0, len(_arb_pool)))
        STATS["v648_cycle_mse_raw_ranked"] = int(max(0, raw_ranked_total))
        STATS["v648_cycle_mse_ranked"] = int(max(0, len(_arb_pool)))
        try:
            _fn = globals().get("_v681_note_runtime_mse")
            if callable(_fn):
                _fn(int(generated_total), int(len(_arb_pool)), int(len(final)),
                    dict(_MSEState.last_run_counts.get("reject_reasons", {}) or {}))
        except Exception:
            _v647_record_suppressed_exception()
        return final


# ---- Lightweight strategy policy extension ---------------------------------
# The new strategy modes route through the existing family policy authority.
_orig_strategy_allowed = FamilyPolicyLayer.strategy_allowed
def _v45_strategy_allowed(strategy_mode, regime, local_regime="", market_phase="",
                           severity="", strategy_style=""):
    sm=str(strategy_mode or "").upper()
    mapping={
        "VOLATILITY_BURST":"MOMENTUM_EXPANSION",
        "RELATIVE_STRENGTH_LEADER":"RELATIVE_STRENGTH",
        "ORDERBOOK_CONFIRMATION":"LOCAL_STRENGTH_BREAKOUT",
        "OPPORTUNITY_SCOUT":"OPPORTUNITY_SCOUT",
    }
    return _orig_strategy_allowed(mapping.get(sm,sm), regime, local_regime, market_phase, severity, strategy_style)
FamilyPolicyLayer.strategy_allowed = staticmethod(_v45_strategy_allowed)


# ---- Near-miss + score rescue integration into the canonical builder -------
_orig_sizing_decide = SizingEngine.decide if hasattr(SizingEngine,"decide") else None
# We do NOT replace the sizing engine. We only feed a bounded risk factor into
# the pre-existing per-strategy risk multiplier variable inside build_and_route.


# Patch the score-floor and risk-factor lines in build_and_route in-place.
# This section is generated at source-edit time; runtime helper below remains
# side-effect free.


# ---- Session model realized-R hook -----------------------------------------
# Use existing finalization telemetry opportunistically, without intercepting
# execution. This is intentionally defensive.
_orig_finalize_and_record_r = globals().get("_finalize_and_record_r")
if _orig_finalize_and_record_r is not None:
    async def _v45_finalize_and_record_r(*args, **kwargs):
        result = await _orig_finalize_and_record_r(*args, **kwargs)
        try:
            trade = args[0] if args else kwargs.get("trade")
            if trade is not None:
                sm=str(getattr(trade,"strategy_mode","") or "").upper()
                R=float(getattr(trade,"realized_R",getattr(trade,"r_multiple",0.0)) or 0.0)
                if sm:
                    SessionQualityModel.record(sm, datetime.now(timezone.utc).hour, R)
                    STATS["v45_realized_r_samples"] = STATS.get("v45_realized_r_samples",0)+1
        except Exception:
            _v647_record_suppressed_exception()
        return result
    _finalize_and_record_r = _v45_finalize_and_record_r


# ---- v4.5 self-test ---------------------------------------------------------
def _v45_self_test() -> None:
    if not _PDNP_OK:
        raise RuntimeError("pandas/numpy required for v4.5 self-test")
    results=[]
    def ok(n,c): results.append((n,bool(c)))
    # Pullback bounds
    df = pd.DataFrame({
        "open":np.linspace(100,120,80),
        "high":np.linspace(101,121,80),
        "low":np.linspace(99,119,80),
        "close":np.linspace(100,120,80),
        "volume":np.ones(80)*100,
    })
    a,p,n = _v45_adaptive_pullback_envelope(df,1.0,2.4,3.0,.5,False)
    ok("adaptive_pullback_hard_bound", a <= 3.0 and a <= 2.4*1.5 + 1e-9)
    ok("rescue_floor_base", abs(_v45_effective_score_floor(70.0)-70.0)<1e-9)
    _v45_activate_rescue(2,"selftest")
    ok("rescue_l2_floor", _v45_effective_score_floor(70.0) <= 65.0)
    _V420State.rescue_level=0; _V420State.rescue_until_ts=0.0; _V420State.relaxed_mode_until_ts=0.0
    NearMissOpportunityQueue._items.clear()
    NearMissOpportunityQueue.add({"symbol":"AAA/USDT","candle_ts":1,"strategy_mode":"PULLBACK","score":66,"score_floor":70,"features":{}})
    ok("near_miss_queue_add", NearMissOpportunityQueue.size()==1)
    # Global arbiter smoke test with synthetic valid candidate.
    c=StrategyCandidate("test","AAA/USDT","long",int(WALL_NOW()*1000),100,99,1,2,5,.8,2.0,.8,.8,
                        "PULLBACK",100,{"hard_valid":True,"strategy_mode":"PULLBACK","market_phase":"TREND",
                        "htf_alignment":.8,"volume_quality":.8,"structure_quality":.8,"phase_fit":.8,"local_fit":.8},
                        (), "PULLBACK","SCALP","TREND","BULLISH","LOCAL_BULLISH","NORMAL","5m","B")
    rr=RankedCandidate(c,.80,101,102,105)
    ok("global_arbiter_select", len(GlobalOpportunityArbiter.select([rr],1))==1)
    ok("volatility_burst_enabled_method", hasattr(VolatilityBurstEngine,"enabled") and callable(VolatilityBurstEngine.enabled))
    ok("rs_leader_enabled_method", hasattr(RelativeStrengthLeaderEngine,"enabled") and callable(RelativeStrengthLeaderEngine.enabled))
    ok("opportunity_scout_registered", "OpportunityScoutEngine" in globals())
    ok("opportunity_scout_low_target", _v459_low_target_mode("OPPORTUNITY_SCOUT","TREND_CONTINUATION"))
    ok("opportunity_scout_exit_profile", abs(StrategyExitProfiles.profile_for("OPPORTUNITY_SCOUT").tp2_rr-float(CONFIG.get("V521_SCOUT_TP2_RR",1.5))) < 1e-9)
    _score_probe = GlobalOpportunityArbiter._candidate_score(rr)
    ok("global_score_preserves_composite", _score_probe >= 0.55)
    ok("global_funnel_state_cycle", hasattr(V45GlobalFunnelState, "note_cycle"))
    ok("prequal_exception_telemetry", callable(_v455_record_prequal_reason))
    ok("prequal_exception_bucket_other", _v453_reject_bucket("exception.prequal:test") == "other")
    ok("global_nearmiss_created_ts", NearMissOpportunityQueue.contains("AAA/USDT","PULLBACK"))
    ok("global_dynamic_floor", GlobalOpportunityArbiter._effective_min_score() >= float(CONFIG.get("V45_SCORE_HARD_FLOOR", 0.50)))
    try:
        _hr_ep = StrategyExitProfiles.profile_for("RELATIVE_STRENGTH_LEADER")
        ok("low_target_tp_geometry", abs(_hr_ep.tp1_rr-float(CONFIG.get("V459_LOW_TARGET_TP1_RR",.90))) < 1e-9
           and _hr_ep.tp1_rr < _hr_ep.tp2_rr < _hr_ep.tp3_rr)
        ok("low_target_risk_factor", 0.35 <= _v459_risk_factor_for("VOLATILITY_BURST") <= 1.0)
        ok("momentum_expansion_explicit_profile", abs(StrategyExitProfiles.profile_for("MOMENTUM_EXPANSION").tp1_rr-1.0)<1e-9 and abs(StrategyExitProfiles.profile_for("MOMENTUM_EXPANSION").tp2_rr-2.0)<1e-9)
        ok("entry_ticker_guard_config", bool(CONFIG.get("V702_ENTRY_TICKER_USE_ASK", True)) and float(CONFIG.get("V702_ENTRY_TICKER_TIMEOUT_SEC",3.0))>0)
        ok("entry_class_split", _v459_entry_class("PULLBACK","PULLBACK") == "A_STRONG"
           and _v459_entry_class("VOLATILITY_BURST","TREND_CONTINUATION") == "B_HIGH_RECALL")
    except Exception:
        ok("low_target_extension_tests", False)
    ok("near_miss_contains", NearMissOpportunityQueue.contains("AAA/USDT","PULLBACK"))
    NearMissOpportunityQueue.mark_recovered("AAA/USDT","PULLBACK")
    ok("near_miss_recovery", NearMissOpportunityQueue.size()==0)
    failed=[n for n,p in results if not p]
    for n,p in results: logger.info(f"[V45.selftest] {'PASS' if p else 'FAIL'} {n}")
    if failed:
        raise AssertionError(f"V4.5 self-tests FAILED: {failed}")
    logger.info(f"V4.5 OPPORTUNITY-BRAIN acceptance self-test: PASS ({len(results)} checks)")


