def _v457_policy_regime_fragment_stats(window_sec: Optional[float] = None) -> Dict[str, Any]:
    """Classify policy mismatch dimensions separately from HTF quality failures."""
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        events = _V456_EVENTS.items(ws, "prequal_reject")
        counts: Dict[str,int] = defaultdict(int); buckets: Dict[str,int] = defaultdict(int)
        for _ts, _k, payload in events:
            counts[str(payload.get("reason","unknown") or "unknown")] += 1
            buckets[str(payload.get("bucket","OTHER") or "OTHER")] += 1
        total = int(sum(counts.values()) or 0)
        macro = int(buckets.get("POLICY_MACRO",0) or 0)
        return {"window_sec":ws,"total_prequal_rejects":total,"fragment_count":macro,
                "fragment_share":(macro/float(total)) if total else 0.0,
                "family_regime_disallowed_macro":int(counts.get("family_regime_disallowed.macro",0) or 0),
                "htf_family_regime_disallowed":int(counts.get("htf.family_regime_disallowed",0) or 0),
                "policy_macro":macro,
                "policy_local":int(buckets.get("POLICY_LOCAL",0) or 0),
                "policy_phase":int(buckets.get("POLICY_PHASE",0) or 0),
                "policy_severity":int(buckets.get("POLICY_SEVERITY",0) or 0),
                "policy_style":int(buckets.get("POLICY_STYLE",0) or 0),
                "policy_other":int(buckets.get("POLICY_OTHER",0) or 0),
                "htf_strength":int(buckets.get("HTF_STRENGTH",0) or 0),
                "htf_unavailable":int(buckets.get("HTF_UNAVAILABLE",0) or 0),
                "buckets":dict(sorted(buckets.items(),key=lambda kv:kv[1],reverse=True))}
    except Exception:
        return {"window_sec":float(window_sec or 0.0),"total_prequal_rejects":0,"fragment_count":0,
                "fragment_share":0.0,"family_regime_disallowed_macro":0,"htf_family_regime_disallowed":0,
                "policy_macro":0,"policy_local":0,"policy_phase":0,"policy_severity":0,"policy_style":0,
                "policy_other":0,"htf_strength":0,"htf_unavailable":0,"buckets":{}}

def _v457_policy_controller_tick() -> None:
    """Arm bounded policy/HTF relief only after repeated windowed evidence."""
    try:
        if not bool(CONFIG.get("V457_POLICY_RECOVERY_ENABLE", True)):
            _v457_relief_reset("disabled")
            return
        if KillSwitch.is_active() or bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
            _v457_relief_reset("hard_safety")
            return
        if str(getattr(LIVE_STATE, "current", "")) != "FULL_LIVE_RUNNING":
            _v457_relief_reset("live_not_running")
            return
        if ExchangeWatchdog.is_tripped():
            _v457_relief_reset("watchdog")
            return
        if str((BalanceReconciler.snapshot() or {}).get("state", "")).upper() == "BLOCK":
            _v457_relief_reset("balance_block")
            return
        regime = str(STATS.get("v425_regime_current", STATS.get("regime_current", "")) or "").upper()
        local = str(STATS.get("v425_local_regime", STATS.get("v45_last_local_regime", "")) or "").upper()
        severity = str(STATS.get("v425_macro_severity", "") or "").upper()
        _continuity_active = (bool(CONFIG.get("V4513_POLICY_RECOVERY_CONTINUITY_ENABLE", True))
                              and _v457_policy_recovery_active()
                              and regime == "BULLISH" and local == "LOCAL_BULLISH"
                              and severity in {"", "NORMAL"})
        if ((regime not in {"NEUTRAL","BULLISH"}) or local != "LOCAL_BULLISH"
                or severity not in {"", "NORMAL"}):
            _v457_relief_reset("context")
            return
        STATS["v4513_policy_context_continuity"] = bool(_continuity_active)
        STATS["v4513_policy_context_regime"] = regime

        ws = float(CONFIG.get("V457_POLICY_RECOVERY_WINDOW_SEC", 720.0))
        dom_reason, share, dom_bucket = _v456_prequal_dominant(ws)
        _frag = _v457_policy_regime_fragment_stats(ws)
        _frag_share = float(_frag.get("fragment_share", 0.0) or 0.0)
        _frag_count = int(_frag.get("fragment_count", 0) or 0)
        # v4.5.12: equivalent policy-mismatch labels are one bottleneck.
        # Keep the raw dominant label for diagnostics, but use the aggregate
        # share for bounded recovery evidence.
        policy_share = max(float(share or 0.0), _frag_share)
        if _frag_count > 0:
            if int(_frag.get("family_regime_disallowed_macro", 0) or 0) >= int(
                _frag.get("htf_family_regime_disallowed", 0) or 0
            ):
                policy_reason = "family_regime_disallowed.macro"
            else:
                policy_reason = "htf.family_regime_disallowed"
        else:
            policy_reason = str(dom_reason or "")
        STATS["v457_policy_regime_fragment_count"] = _frag_count
        STATS["v457_policy_regime_fragment_share"] = policy_share
        STATS["v457_policy_regime_reason"] = policy_reason
        d = V453StarvationClassifier._window_deltas()
        gen = int(d.get("generated", 0) or 0)
        preq = int(d.get("prequalified", 0) or 0)
        rj_htf = int(d.get("reject_htf", 0) or 0)
        rj_liq = int(d.get("reject_liquidity", 0) or 0)
        rj_str = int(d.get("reject_structure", 0) or 0)
        rj_score = int(d.get("reject_score", 0) or 0)
        rj_exec = int(d.get("reject_execution", 0) or 0)
        if gen <= 0:
            return

        no_send = MONO_NOW() - float(V453CanonicalScoreFloor._last_send_ts or MONO_NOW())
        hard_other = rj_liq + rj_str + rj_score + rj_exec
        policy_bottleneck = (
            policy_share >= float(CONFIG.get("V457_POLICY_RECOVERY_DOM_SHARE", 0.35))
            and (
                str(policy_reason).startswith("family_regime_disallowed")
                or str(policy_reason).startswith("htf.family_regime_disallowed")
            )
            and _frag_count > 0
            and rj_htf >= _frag_count
            and hard_other == 0
            and preq <= max(2, int(0.10 * max(gen, 1)))
            and no_send >= float(CONFIG.get("V457_POLICY_RECOVERY_MIN_NO_SEND_SEC", 1800.0))
        )

        marker = int(WALL_NOW() // max(ws, 60.0))
        if marker != int(getattr(_V420State, "v457_policy_last_window_marker", -1)):
            setattr(_V420State, "v457_policy_last_window_marker", marker)
            if policy_bottleneck:
                setattr(
                    _V420State, "v457_policy_consecutive_windows",
                    int(getattr(_V420State, "v457_policy_consecutive_windows", 0) or 0) + 1,
                )
            else:
                setattr(_V420State, "v457_policy_consecutive_windows", 0)

        consec = int(getattr(_V420State, "v457_policy_consecutive_windows", 0) or 0)
        need = max(1, int(CONFIG.get("V457_POLICY_RECOVERY_MIN_CONSEC_WINDOWS", 2)))

        _can_newly_arm = (regime == "NEUTRAL")
        if policy_bottleneck and consec >= need and (_can_newly_arm or _continuity_active):
            ttl = min(1800.0, float(CONFIG.get("V457_POLICY_RECOVERY_TTL_SEC", 1800.0)))
            htf_ttl = min(1800.0, float(CONFIG.get("V457_HTF_RELIEF_TTL_SEC", 1800.0)))
            setattr(_V420State, "v457_policy_recovery_until_ts", MONO_NOW() + ttl)
            setattr(_V420State, "v457_htf_relief_until_ts", MONO_NOW() + htf_ttl)
            STATS["v457_policy_recovery_active"] = True
            STATS["v457_htf_relief_active"] = True
            STATS["v457_policy_recovery_reason"] = str(policy_reason)
            STATS["v457_policy_recovery_dominant_raw"] = str(dom_reason or "")
            STATS["v457_policy_recovery_share_raw"] = float(share or 0.0)
            STATS["v457_policy_recovery_share_aggregated"] = float(policy_share)
            STATS["v457_policy_recovery_ttl"] = ttl
            if not STATS.get("v457_policy_recovery_armed_logged"):
                logger.warning(
                    f"[V457-PolicyRecovery] ACTIVE regime={regime} local={local} "
                    f"dominant={policy_reason} raw={dom_reason or 'n/a'} "
                    f"share={policy_share:.0%} raw_share={share:.0%} windows={consec} "
                    f"ttl={ttl:.0f}s htf_relief_max=5.0"
                )
                STATS["v457_policy_recovery_armed_logged"] = True
        elif _v457_policy_recovery_active():
            if (not policy_bottleneck) or no_send < float(CONFIG.get("V457_POLICY_RECOVERY_MIN_NO_SEND_SEC", 3600.0)):
                _v457_relief_reset("evidence_lost")
                STATS["v457_policy_recovery_armed_logged"] = False
        else:
            STATS["v457_policy_recovery_active"] = False
            STATS["v457_htf_relief_active"] = False
    except Exception:
        _v457_relief_reset("controller_error")


def _v457_global_trace_tick() -> None:
    """Hourly dry-run telemetry of top rejected global candidates."""
    try:
        if not bool(CONFIG.get("V457_GLOBAL_TRACE_ENABLE", True)):
            return
        now = MONO_NOW()
        last = float(getattr(_V420State, "v457_global_trace_last_ts", 0.0) or 0.0)
        if now - last < float(CONFIG.get("V457_GLOBAL_TRACE_INTERVAL_SEC", 3600.0)):
            return
        d = V453StarvationClassifier._window_deltas()
        if int(d.get("selected", 0) or 0) <= 0 or int(d.get("queued", 0) or 0) > 0 or int(d.get("sent", 0) or 0) > 0:
            return
        setattr(_V420State, "v457_global_trace_last_ts", now)
        tops = _v456_top_rejected_symbols(
            int(CONFIG.get("V457_GLOBAL_TRACE_TOP_N", 3)), _v456_window_sec()
        )
        for i, rec in enumerate(tops, 1):
            logger.warning(
                f"[GLOBAL-TRACE] rank={i} symbol={rec.get('symbol')} family={rec.get('family')} "
                f"strategy_mode={rec.get('strategy_mode')} global_score={rec.get('score')} "
                f"composite_score={rec.get('score')} regime={rec.get('regime')} "
                f"local={rec.get('local_regime')} phase={rec.get('market_phase')} "
                f"severity={rec.get('severity','')} style={rec.get('strategy_style')} tier={rec.get('tier')} "
                f"htf_strength={rec.get('htf_strength')} family_htf_floor={rec.get('family_htf_floor')} "
                f"effective_htf_floor={rec.get('effective_htf_floor')} "
                f"canonical_result=REJECT reason={rec.get('top_reason')} "
                f"next_blocker={rec.get('next_blocker')} "
                f"allowed_regimes={rec.get('allowed_regimes')} "
                f"allowed_local={rec.get('allowed_local_regimes')} "
                f"allowed_phases={rec.get('allowed_phases')} "
                f"allowed_styles={rec.get('allowed_styles')}"
            )
    except Exception:
        _v647_record_suppressed_exception()

