# =============================================================================
class _V456WindowStore:
    """Bounded wall-clock event store. Wall timestamps are correct here:
    these are event/log instants (persistence domain), not durations."""

    def __init__(self, maxlen: int):
        self._events: deque = deque(maxlen=max(64, int(maxlen)))

    def add(self, kind: str, payload: Optional[Dict[str, Any]] = None) -> None:
        try:
            self._events.append((WALL_NOW(), str(kind), dict(payload or {})))
        except Exception:
            _v647_record_suppressed_exception()

    def items(self, window_sec: float, kind: Optional[str] = None) -> List[Tuple[float, str, Dict[str, Any]]]:
        try:
            now = WALL_NOW()
            out = []
            for ts, k, p in list(self._events):
                if now - float(ts) <= float(window_sec) and (kind is None or k == kind):
                    out.append((ts, k, p))
            return out
        except Exception:
            return []

    def count(self, window_sec: float, kind: Optional[str] = None) -> int:
        return len(self.items(window_sec, kind))


_V456_EVENTS = _V456WindowStore(int(CONFIG.get("V456_WINDOW_TELEMETRY_MAX", 4096)))


def _v456_window_sec() -> float:
    """Same window the starvation classifier uses (single source of truth)."""
    try:
        return float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN", 12)) * 60.0
    except Exception:
        return 720.0


# =============================================================================
#  v4.5.6 — CANONICAL PREQUALIFICATION WINDOWED TELEMETRY
# =============================================================================
# Wraps the EXISTING _v455_record_prequal_reason (no duplicate system): every
# reject/exception the original records is also mirrored into the windowed
# store with full context. Exception reasons are classified into the OTHER
# bucket — never HTF/structure.
_V456_PREQUAL_HARD_PREFIXES = ("htf.", "liquidity.", "structure.", "freshness.",
                               "policy.", "tier.", "balance.", "score.",
                               "active_trade.", "safety.", "crash.")


def _v456_reason_bucket(reason: str, exception_type: str = "", context: Optional[Dict[str, Any]] = None) -> str:
    try:
        r = str(reason or "")
        if exception_type or r.startswith("exception."):
            return "OTHER"
        if r.startswith("family_regime_disallowed") or r.startswith("htf.family_regime_disallowed"):
            tail = r.upper()
            if any(token in tail for token in ("LOCAL", "LOCAL_REGIME")):
                return "POLICY_LOCAL"
            if any(token in tail for token in ("PHASE", "MARKET_PHASE")):
                return "POLICY_PHASE"
            if "SEVERITY" in tail:
                return "POLICY_SEVERITY"
            if "STYLE" in tail:
                return "POLICY_STYLE"
            return "POLICY_MACRO"
        if r.startswith("family_htf_strength_below_floor") or (r.startswith("htf.") and "strength" in r):
            return "HTF_STRENGTH"
        if r.startswith("htf.unavailable"):
            return "HTF_UNAVAILABLE"
        if r.startswith("policy."):
            return "POLICY_OTHER"
        for p in _V456_PREQUAL_HARD_PREFIXES:
            if r.startswith(p):
                return p.rstrip(".").upper()
        return "OTHER"
    except Exception:
        return "OTHER"

_orig_v455_record_prequal_reason = _v455_record_prequal_reason


def _v455_record_prequal_reason(symbol: str, reason: str, *, stage: str = "",
                                exception_type: str = "", context: Optional[Dict[str, Any]] = None) -> None:
    """v4.5.6 wrapper: original bounded recorder + windowed mirror. The
    trading decision is untouched; failures here are telemetry-only."""
    try:
        _orig_v455_record_prequal_reason(symbol, reason, stage=stage,
                                         exception_type=exception_type, context=context)
    except Exception:
        _v647_record_suppressed_exception()
    try:
        if not bool(CONFIG.get("V456_ENABLE", True)):
            return
        ctx = dict(context or {})
        _V456_EVENTS.add("prequal_reject", {
            "symbol": str(symbol or ""),
            "reason": str(reason or "unknown")[:240],
            "stage": str(stage or ""),
            "exception_type": str(exception_type or ""),
            "bucket": _v456_reason_bucket(reason, exception_type, context),
            "family": ctx.get("family", ""),
            "mode": ctx.get("mode", ""),
            "regime": ctx.get("regime", ""),
            "local_regime": ctx.get("local_regime", ""),
            "snapshot_id": ctx.get("snapshot_id", ""),
            "snapshot_coherent": ctx.get("snapshot_coherent"),
            "macro_context_blocked": ctx.get("macro_context_blocked", False),
            "macro_context_block_reason": ctx.get("macro_context_block_reason", ""),
            "market_phase": ctx.get("market_phase", ctx.get("phase", "")),
            "severity": ctx.get("severity", ""),
            "strategy_style": ctx.get("strategy_style", ctx.get("style", "")),
            "policy_reason": ctx.get("policy_reason", ""),
            "allowed_regimes": ctx.get("allowed_regimes", ()),
            "allowed_local_regimes": ctx.get("allowed_local_regimes", ()),
            "allowed_severity": ctx.get("allowed_severity", ()),
            "allowed_phases": ctx.get("allowed_phases", ()),
            "allowed_styles": ctx.get("allowed_styles", ()),
            "family_htf_floor": ctx.get("family_htf_floor"),
            "effective_htf_floor": ctx.get("effective_htf_floor"),
            "recovery_active": ctx.get("recovery_active", False),
            "recovery_reason": ctx.get("recovery_reason", ""),
            "tier": ctx.get("tier", ""),
            "htf_strength": ctx.get("htf_strength"),
            "quote_vol_24h": ctx.get("quote_vol_24h"),
            "spread_pct": ctx.get("spread_pct"),
            "score": ctx.get("score"),
            "htf_recovery_source": ctx.get("htf_recovery_source", ""),
            "htf_recovery_age_sec": ctx.get("htf_recovery_age_sec", 0.0),
        })
        try:
            if str(ctx.get("htf_recovery_source", "") or "").upper() == "CACHED":
                STATS["v4513_htf_cached_prequal_rejects"] = int(STATS.get("v4513_htf_cached_prequal_rejects", 0) or 0) + 1
                if not str(reason or "").startswith("htf."):
                    STATS["v4513_htf_cached_false_rejects"] = int(STATS.get("v4513_htf_cached_false_rejects", 0) or 0) + 1
        except Exception:
            _v647_record_suppressed_exception()
        if exception_type:
            _V456_EVENTS.add("prequal_exception", {
                "symbol": str(symbol or ""),
                "exception_type": str(exception_type)[:160],
                "stage": str(stage or ""),
                "reason": str(reason or "")[:240],
                "family": ctx.get("family", ""),
                "mode": ctx.get("mode", ""),
                "regime": ctx.get("regime", ""),
                "tier": ctx.get("tier", ""),
                "htf_strength": ctx.get("htf_strength"),
            })
    except Exception:
        _v647_record_suppressed_exception()


def _v457_policy_mismatch_window_top(n: int = 3, window_sec: Optional[float] = None) -> List[Tuple[str, int]]:
    """Top family-policy mismatch reasons from the same rolling prequal window."""
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        counts: Dict[str, int] = defaultdict(int)
        for _ts, _k, p in _V456_EVENTS.items(ws, "prequal_reject"):
            reason = str(p.get("reason", ""))
            if reason.startswith("family_regime_disallowed"):
                counts[reason] += 1
        return sorted(counts.items(), key=lambda kv: kv[1], reverse=True)[:max(1, int(n))]
    except Exception:
        return []


def _v457_policy_mismatch_window_count(window_sec: Optional[float] = None) -> int:
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        return sum(
            1 for _ts, _k, p in _V456_EVENTS.items(ws, "prequal_reject")
            if str(p.get("reason", "")).startswith("family_regime_disallowed")
        )
    except Exception:
        return 0


def _v456_prequal_window_top_reasons(n: int = 3, window_sec: Optional[float] = None) -> List[Tuple[str, int]]:

    """Top prequal reject reasons inside the SAME rolling window used for
    starvation diagnosis (not lifetime totals)."""
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        counts: Dict[str, int] = defaultdict(int)
        for _ts, _k, p in _V456_EVENTS.items(ws, "prequal_reject"):
            counts[str(p.get("reason", "unknown"))] += 1
        return sorted(counts.items(), key=lambda kv: kv[1], reverse=True)[:max(1, int(n))]
    except Exception:
        return []


def _v456_prequal_dominant(window_sec: Optional[float] = None) -> Tuple[str, float, str]:
    """(dominant_reason, share, dominant_mode). share in 0..1."""
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        ev = _V456_EVENTS.items(ws, "prequal_reject")
        if not ev:
            return "", 0.0, "NONE"
        counts: Dict[str, int] = defaultdict(int)
        buckets: Dict[str, int] = defaultdict(int)
        for _ts, _k, p in ev:
            counts[str(p.get("reason", "unknown"))] += 1
            buckets[str(p.get("bucket", "OTHER"))] += 1
        total = sum(counts.values()) or 1
        reason, n = max(counts.items(), key=lambda kv: kv[1])
        mode, _bn = max(buckets.items(), key=lambda kv: kv[1])
        return reason, round(n / float(total), 4), mode
    except Exception:
        return "", 0.0, "NONE"


def _v456_prequal_window_counts(window_sec: Optional[float] = None) -> Dict[str, int]:
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        rej = _V456_EVENTS.items(ws, "prequal_reject")
        exc = sum(1 for _t, _k, p in rej if p.get("exception_type"))
        return {
            "prequal_reject": len(rej),
            "prequal_exception": int(exc),
            "prequal_exception_store": _V456_EVENTS.count(ws, "prequal_exception"),
        }
    except Exception:
        return {"prequal_reject": 0, "prequal_exception": 0, "prequal_exception_store": 0}


# =============================================================================
#  v4.5.6 — TOP REJECTED SYMBOLS (windowed, bounded)
# =============================================================================
def _v456_top_rejected_symbols(n: int = 3, window_sec: Optional[float] = None) -> List[Dict[str, Any]]:
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        per: Dict[str, Dict[str, Any]] = {}
        max_syms = max(8, int(CONFIG.get("V456_TOP_REJECTED_SYMBOLS_MAX", 64)))
        for _ts, _k, p in _V456_EVENTS.items(ws, "prequal_reject"):
            sym = str(p.get("symbol", "") or "")
            if not sym:
                continue
            rec = per.get(sym)
            if rec is None:
                if len(per) >= max_syms:
                    continue
                rec = {"symbol": sym, "count": 0, "reasons": defaultdict(int),
                       "family": p.get("family", ""), "mode": p.get("mode", ""),
                       "tier": p.get("tier", ""), "regime": p.get("regime", ""),
                       "local_regime": p.get("local_regime", ""),
                       "market_phase": p.get("market_phase", ""),
                       "strategy_style": p.get("strategy_style", p.get("style", "")),
                       "allowed_regimes": p.get("allowed_regimes", ()),
                       "allowed_local_regimes": p.get("allowed_local_regimes", ()),
                       "allowed_phases": p.get("allowed_phases", ()),
                       "allowed_styles": p.get("allowed_styles", ()),
                       "effective_htf_floor": p.get("effective_htf_floor"),
                       "family_htf_floor": p.get("family_htf_floor"),
                       "next_blocker": p.get("policy_reason", ""),
                                              "htf_strength": p.get("htf_strength"), "score": p.get("score")}
                per[sym] = rec
            rec["count"] += 1
            rec["reasons"][str(p.get("reason", "unknown"))] += 1
        out = []
        for rec in per.values():
            top_reason = ""
            if rec["reasons"]:
                top_reason = max(rec["reasons"].items(), key=lambda kv: kv[1])[0]
            out.append({
                "symbol": rec["symbol"], "count": rec["count"], "top_reason": top_reason,
                "family": rec["family"], "strategy_mode": rec["mode"], "tier": rec["tier"],
                "regime": rec["regime"], "local_regime": rec.get("local_regime",""),
                "market_phase": rec.get("market_phase",""),
                "strategy_style": rec.get("strategy_style",""),
                "allowed_regimes": rec.get("allowed_regimes",()),
                "allowed_local_regimes": rec.get("allowed_local_regimes",()),
                "allowed_phases": rec.get("allowed_phases",()),
                "allowed_styles": rec.get("allowed_styles",()),
                "effective_htf_floor": rec.get("effective_htf_floor"),
                "family_htf_floor": rec.get("family_htf_floor"),
                "next_blocker": rec.get("next_blocker",""),
                "htf_strength": rec["htf_strength"],
                "score": rec["score"],
            })
        out.sort(key=lambda r: r["count"], reverse=True)
        return out[:max(1, int(n))]
    except Exception:
        return []


# =============================================================================
#  v4.5.6 — CANDIDATE FRESHNESS AUDIT (clock domain preserved: WALL)
# =============================================================================
_V456_FRESH_SAMPLES: deque = deque(maxlen=max(128, int(CONFIG.get("V456_FRESHNESS_SAMPLES_MAX", 2048))))
_orig_v455_candidate_freshness_ok = _v455_candidate_freshness_ok


def _v455_candidate_freshness_ok(generated_at_ms: Any) -> Tuple[bool, str, Optional[float]]:
    """v4.5.6 wrapper: identical decision, plus windowed freshness audit.
    WALL_NOW domain is unchanged (never converted to monotonic)."""
    ok, reason, age = _orig_v455_candidate_freshness_ok(generated_at_ms)
    try:
        if bool(CONFIG.get("V456_ENABLE", True)):
            _V456_FRESH_SAMPLES.append((WALL_NOW(), bool(ok), str(reason or ""),
                                        None if age is None else float(age)))
            if not ok:
                _V456_EVENTS.add("freshness_reject", {
                    "reason": str(reason or "freshness.unknown"),
                    "generated_at_ms": generated_at_ms,
                    "now_wall": WALL_NOW(),
                    "age_sec": age,
                })
    except Exception:
        _v647_record_suppressed_exception()
    return ok, reason, age


def _v456_freshness_stats(window_sec: Optional[float] = None) -> Dict[str, Any]:
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        now = WALL_NOW()
        ages = [a for ts, ok, r, a in list(_V456_FRESH_SAMPLES)
                if a is not None and now - ts <= ws]
        stale = sum(1 for ts, ok, r, a in list(_V456_FRESH_SAMPLES)
                    if not ok and "stale" in str(r) and now - ts <= ws)
        unver = sum(1 for ts, ok, r, a in list(_V456_FRESH_SAMPLES)
                    if not ok and "unverifiable" in str(r) and now - ts <= ws)
        ages_sorted = sorted(ages)

        def _pct(p: float) -> Optional[float]:
            if not ages_sorted:
                return None
            idx = min(len(ages_sorted) - 1, max(0, int(round(p * (len(ages_sorted) - 1)))))
            return round(ages_sorted[idx], 3)

        return {
            "candidate_age_p50": _pct(0.50),
            "candidate_age_p95": _pct(0.95),
            "candidate_stale_count": int(stale),
            "candidate_unverifiable_count": int(unver),
            "samples": len(ages),
        }
    except Exception:
        return {"candidate_age_p50": None, "candidate_age_p95": None,
                "candidate_stale_count": 0, "candidate_unverifiable_count": 0, "samples": 0}


# =============================================================================
# v4.5.82 — Strategy-aware canonical score floor helper. It mirrors the
# canonical SignalBuilder score-base construction for V570 prequalification;
# it does not create a new execution authority.
def _v570_strategy_aware_canonical_floor(candidate, regime: str, family: str) -> float:
    try:
        is_live = bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and not bool(CONFIG.get("PAPER_TRADING_MODE", False))
        floor = float(CONFIG.get("MIN_LIVE_SCORE",70.0) if is_live else CONFIG.get("MIN_PAPER_SCORE",70.0))
        reg = str(regime or "").upper()
        if reg == "BEARISH":
            floor += 8.0
        try:
            if CONFIG.get("REGIME_SCORE_FLOOR_ENABLE", True):
                offs = CONFIG.get("REGIME_SCORE_FLOOR_OFFSETS", {}) or {}
                off = float(offs.get(reg, 0.0) or 0.0)
                floor += max(-6.0, min(6.0, off))
        except Exception:
            _v647_record_suppressed_exception()
        mode = str(getattr(candidate, "strategy_mode", "") or family or "PULLBACK").upper()
        fam = str(family or getattr(candidate, "family", "") or mode).upper()
        if bool(CONFIG.get("V410_MASTER_ENABLE", True)):
            meta = CanonicalStrategyPolicyRegistry.get(mode)
            if isinstance(meta, dict):
                floor = max(floor, float(meta.get("min_score", floor)))
            else:
                floor = float(FamilyPolicyLayer.min_score(floor, fam))
            try:
                soff = float((CONFIG.get("MSE_STRATEGY_MIN_SCORE_OFFSETS", {}) or {}).get(mode, 0.0) or 0.0)
                sess = StrategyPerformanceMemory.session_bucket()
                learned = StrategyPerformanceMemory.score_floor_adjustment(
                    mode, reg, sess, str(getattr(candidate, "strategy_style", "SCALP") or "SCALP")
                )
                floor = max(floor + soff, floor + float(learned))
            except Exception:
                _v647_record_suppressed_exception()
        return float(floor) if math.isfinite(float(floor)) else float(CONFIG.get("MIN_LIVE_SCORE",70.0))
    except Exception:
        return float(CONFIG.get("MIN_LIVE_SCORE",70.0))

#  v4.5.6 — SNAPSHOT-MISSING AUDIT (symbol never silently disappears)
# =============================================================================
_orig_v453_prequalify = _v453_prequalify


def _v453_prequalify(r: "RankedCandidate", snap_by_symbol: Dict[str, Dict[str, Any]]) -> Tuple[bool, str]:
    """v4.5.6 wrapper: identical fail-closed decision; records snapshot-missing
    observations so an absent symbol is attributed, never invisible."""
    sym = ""
    try:
        sym = str(getattr(getattr(r, "candidate", None), "symbol", "") or "")
    except Exception:
        sym = ""
    try:
        if bool(CONFIG.get("V456_ENABLE", True)) and sym:
            snap = snap_by_symbol.get(sym) if isinstance(snap_by_symbol, dict) else None
            if not snap:
                STATS["v456_snapshot_missing_total"] = int(STATS.get("v456_snapshot_missing_total", 0) or 0) + 1
                _V456_EVENTS.add("snapshot_missing", {"symbol": sym, "reason": "snap_by_symbol.absent"})
            else:
                for _fld in ("quote_vol_24h", "spread_pct", "htf_strength"):
                    try:
                        if snap.get(_fld) is None:
                            _V456_EVENTS.add("snapshot_missing", {"symbol": sym, "reason": f"snapshot.field_missing.{_fld}"})
                    except Exception:
                        continue
    except Exception:
        _v647_record_suppressed_exception()
    return _orig_v453_prequalify(r, snap_by_symbol)


def _v456_snapshot_missing(window_sec: Optional[float] = None) -> Dict[str, Any]:
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        ev = _V456_EVENTS.items(ws, "snapshot_missing")
        reasons: Dict[str, int] = defaultdict(int)
        for _ts, _k, p in ev:
            reasons[str(p.get("reason", "unknown"))] += 1
        top = sorted(reasons.items(), key=lambda kv: kv[1], reverse=True)[:3]
        return {"snapmiss": len(ev), "top": top}
    except Exception:
        return {"snapmiss": 0, "top": []}


# =============================================================================
#  v4.5.6 — HTF NEUTRAL POLICY (safety-preserving; default STRICT = unchanged)
# =============================================================================
def _v456_htf_neutral_floor(family: str = "") -> float:
    """Family-aware NEUTRAL floor. STRICT (default) returns the canonical
    V453_HTF_FLOOR_NEUTRAL verbatim — behaviour byte-identical to v4.5.5.
    BOUNDED_RELAXED lowers the floor ONLY for explicitly allow-listed families
    and can never bypass crash/hard-bearish/family-disallowed/liquidity/
    structure/safety gates (those are evaluated upstream and stay fail-closed)."""
    base = float(CONFIG.get("V453_HTF_FLOOR_NEUTRAL", 45.0) or 45.0)
    try:
        if str(CONFIG.get("V456_HTF_NEUTRAL_POLICY_MODE", "STRICT")).upper() != "BOUNDED_RELAXED":
            return base
        allowed = tuple(CONFIG.get("V456_HTF_NEUTRAL_RELAX_FAMILIES", ()) or ())
        if allowed and str(family or "") in allowed:
            return min(base, float(CONFIG.get("V456_HTF_FLOOR_NEUTRAL_RELAXED", 35.0) or 35.0))
        return base
    except Exception:
        return base  # fail-closed: any uncertainty => strict floor


def _v456_htf_distribution(window_sec: Optional[float] = None) -> Dict[str, int]:
    """HTF strength distribution observed at prequalification (telemetry)."""
    out = {"strict_bullish": 0, "near_bullish": 0, "neutral": 0, "bearish": 0,
           "unknown": 0, "rejected_htf_floor": 0}
    try:
        ws = float(window_sec if window_sec is not None else _v456_window_sec())
        floor = float(CONFIG.get("V453_HTF_FLOOR_NEUTRAL", 45.0) or 45.0)
        for _ts, _k, p in _V456_EVENTS.items(ws, "prequal_reject"):
            try:
                s = p.get("htf_strength")
                s = float(s) if s is not None else None
            except Exception:
                s = None
            if s is None:
                out["unknown"] += 1
            elif s >= 70.0:
                out["strict_bullish"] += 1
            elif s >= 55.0:
                out["near_bullish"] += 1
            elif s >= 33.0:
                out["neutral"] += 1
            else:
                out["bearish"] += 1
            if "htf_strength_below_floor" in str(p.get("reason", "")) or str(p.get("reason", "")).startswith("htf."):
                out["rejected_htf_floor"] += 1
        out["floor_current"] = floor
        out["policy_mode"] = str(CONFIG.get("V456_HTF_NEUTRAL_POLICY_MODE", "STRICT"))
    except Exception:
        _v647_record_suppressed_exception()
    return out


# =============================================================================
#  v4.5.6 — MSE PER-FAMILY WINDOWED COVERAGE
# =============================================================================
class _V456FamilyCoverage:
    """Windowed family coverage across the real funnel.

    Generated/ranked come from MSE deltas; policy/HTF/prequal come from the
    windowed canonical events; selected/queued/sent come from explicit
    family-tagged events. Telemetry only.
    """
    _baseline: Dict[str, int] = {}
    _baseline_ts: float = 0.0

    @classmethod
    def _cum(cls) -> Dict[str, int]:
        out: Dict[str, int] = {}
        try:
            for k, v in list(STATS.items()):
                ks = str(k)
                if ks.startswith("mse_generated_by_strategy.") or ks.startswith("mse_ranked_by_strategy."):
                    out[ks] = int(v or 0)
        except Exception:
            _v647_record_suppressed_exception()
        return out

    @classmethod
    def snapshot(cls, window_sec: Optional[float] = None) -> Dict[str, Dict[str, int]]:
        try:
            ws = float(window_sec if window_sec is not None else _v456_window_sec())
            now = WALL_NOW()
            cum = cls._cum()
            if not cls._baseline or (now - cls._baseline_ts) > ws:
                cls._baseline = dict(cum)
                cls._baseline_ts = now
            fam: Dict[str, Dict[str, int]] = defaultdict(lambda: {
                "gen": 0, "policy_pass": 0, "htf_pass": 0, "pre_pass": 0,
                "pre_rej": 0, "ranked": 0, "selected": 0, "queued": 0, "sent": 0})

            for k, v in cum.items():
                base = int(cls._baseline.get(k, 0) or 0)
                d = max(0, v - base)
                name = k.split(".", 1)[1]
                if k.startswith("mse_generated_by_strategy."):
                    fam[name]["gen"] += d
                elif k.startswith("mse_ranked_by_strategy."):
                    fam[name]["ranked"] += d

            for _ts, _k, p in _V456_EVENTS.items(ws, "prequal_pass"):
                f = str(p.get("family") or p.get("mode") or "?")
                fam[f]["pre_pass"] += 1
                fam[f]["policy_pass"] += 1

            for _ts, _k, p in _V456_EVENTS.items(ws, "prequal_reject"):
                f = str(p.get("family") or p.get("mode") or "?")
                fam[f]["pre_rej"] += 1
                r = str(p.get("reason", ""))
                if r.startswith("htf."):
                    # A rejection here means HTF was the blocker; policy had
                    # already been evaluated for the candidate.
                    fam[f]["policy_pass"] += 1

            for kind, field in (("family_selected", "selected"),
                                ("family_queued", "queued"),
                                ("family_sent", "sent")):
                for _ts, _k, p in _V456_EVENTS.items(ws, kind):
                    f = str(p.get("family") or "?")
                    fam[f][field] += 1

            # htf_pass: every prequal pass has cleared HTF; non-HTF rejects
            # are also evidence the candidate passed HTF. HTF rejects remain
            # excluded. Telemetry only.
            for f, rec in fam.items():
                _events_f = [
                    p for _ts, _k, p in _V456_EVENTS.items(ws, "prequal_reject")
                    if str(p.get("family") or p.get("mode") or "?") == f
                ]
                _non_htf_rejects = sum(
                    1 for p in _events_f
                    if not str(p.get("reason", "")).startswith("htf.")
                )
                rec["htf_pass"] = int(rec.get("pre_pass", 0) or 0) + _non_htf_rejects
            return {k: dict(v) for k, v in fam.items() if any(v.values())}
        except Exception:
            return {}


# =============================================================================
#  v4.5.6 — STAGE ACCOUNTING (silent-loss attribution done CORRECTLY)
# =============================================================================
class V456StageAccounting:
    """Per-transition accounting over WINDOWED deltas. The naive formula
    (generated - prequal_pass - reject_bucket) is NEVER used: each transition
    is verified separately and only a PROVEN unattributed loss bumps the
    v455_*_unattributed_loss counters (telemetry-only, never blocks trading)."""

    _last_violation_log_ts: float = 0.0

    @classmethod
    def _violation(cls, tag: str, detail: str, counter: str, suppress_log: bool = False) -> None:
        try:
            STATS[counter] = int(STATS.get(counter, 0) or 0) + 1
            STATS["v456_pipeline_accounting_violations"] = int(
                STATS.get("v456_pipeline_accounting_violations", 0) or 0) + 1
            now = MONO_NOW()
            if (not suppress_log) and now - cls._last_violation_log_ts >= 60.0:  # bounded logging
                cls._last_violation_log_ts = now
                logger.error(f"[PIPELINE-ACCOUNTING-VIOLATION] {tag}: {detail}")
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def check(cls) -> Dict[str, Any]:
        report: Dict[str, Any] = {"ok": True, "violations": []}
        try:
            if not bool(CONFIG.get("V456_ENABLE", True)):
                return report
            d = V453StarvationClassifier._window_deltas()
            gen = int(d.get("generated", 0) or 0)
            ranked = int(d.get("ranked", 0) or 0)
            selected = int(d.get("selected", 0) or 0)
            preq = int(d.get("prequalified", 0) or 0)
            cpass = int(d.get("canonical_pass", 0) or 0)
            crej = int(d.get("canonical_reject", 0) or 0)
            queued = int(d.get("queued", 0) or 0)
            sent = int(d.get("sent", 0) or 0)

            # Negative deltas / impossible orderings => unattributed loss.
            for name, val in (("generated", gen), ("ranked", ranked), ("selected", selected),
                              ("prequalified", preq), ("canonical_pass", cpass),
                              ("canonical_reject", crej), ("queued", queued), ("sent", sent)):
                if val < 0:
                    cls._violation("negative_delta", f"{name}={val}", "v455_mse_unattributed_loss")
                    report["ok"] = False
                    report["violations"].append(f"negative_delta.{name}")
            if ranked > gen and gen > 0:
                cls._violation("mse_stage_loss.generated_to_ranked",
                               f"ranked({ranked}) > generated({gen})", "v455_mse_unattributed_loss")
                report["ok"] = False
                report["violations"].append("mse.ranked_gt_generated")
            if selected > ranked and ranked > 0:
                cls._violation("mse_stage_loss.ranked_to_selected",
                               f"selected({selected}) > ranked({ranked})", "v455_mse_unattributed_loss")
                report["ok"] = False
                report["violations"].append("mse.selected_gt_ranked")
            if (cpass + crej) > ranked and ranked > 0:
                cls._violation("prequal_stage.loss_unattributed",
                               f"canonical_pass({cpass})+canonical_reject({crej}) > ranked({ranked})",
                               "v455_prequal_unattributed_loss")
                report["ok"] = False
                report["violations"].append("prequal.over_attributed")
            if preq > ranked and ranked > 0:
                cls._violation("prequal_stage.loss_unattributed",
                               f"prequalified({preq}) > ranked({ranked})",
                               "v455_prequal_unattributed_loss")
                report["ok"] = False
                report["violations"].append("prequal.prequalified_gt_ranked")
            if sent > queued and queued >= 0 and sent > 0:
                cls._violation("execution_stage.loss_unattributed",
                               f"sent({sent}) > queued({queued})", "v455_execution_unattributed_loss")
                report["ok"] = False
                report["violations"].append("execution.sent_gt_queued")
        except Exception:
            _v647_record_suppressed_exception()
        return report


# =============================================================================
#  v4.5.6 — STARVATION CLASSIFIER (deterministic, attribution-aware)
# =============================================================================
class V456StarvationClassifier:
    """Refines V453StarvationClassifier WITHOUT replacing it. Adds PREQUAL /
    ACCOUNTING modes and dominant_prequal_reason/share. Deterministic priority:
    SYSTEM > ACCOUNTING/PREQUAL_EXCEPTION > PREQUAL > HTF/LIQUIDITY/STRUCTURE
    > SCORE > EXECUTION > NO_OPP. Applied only when attribution is sufficient;
    otherwise falls back to the v4.5.5 verdict. Telemetry-only."""

    @classmethod
    def classify(cls) -> str:
        mode = "NONE"
        try:
            if not bool(CONFIG.get("V456_ENABLE", True)):
                return V453StarvationClassifier.classify()
            base = V453StarvationClassifier.classify()
            mode = base
            if base == "SYSTEM":
                return cls._publish(base, "", 0.0, "NONE")
            ws = _v456_window_sec()
            d = V453StarvationClassifier._window_deltas()
            gen_d = int(d.get("generated", 0) or 0)
            ranked_d = int(d.get("ranked", 0) or 0)
            cpass_d = int(d.get("canonical_pass", 0) or 0)
            queued_d = int(d.get("queued", 0) or 0)
            sent_d = int(d.get("sent", 0) or 0)

            dom_reason, share, dom_bucket = _v456_prequal_dominant(ws)
            pqc = _v456_prequal_window_counts(ws)
            prej = int(pqc.get("prequal_reject", 0))
            pexc = int(pqc.get("prequal_exception", 0))

            # ACCOUNTING: proven unattributed loss dominates everything else.
            acct = int(STATS.get("v456_pipeline_accounting_violations", 0) or 0)
            if acct > 0 and gen_d > 0:
                return cls._publish("ACCOUNTING", dom_reason, share, dom_bucket)

            # PREQUAL_EXCEPTION burst: exceptions are OTHER, never HTF.
            if pexc >= max(3, int(0.5 * max(prej, 1))):
                return cls._publish("PREQUAL", dom_reason, share, "OTHER")

            # PREQUAL: candidates exist, ranking works, prequal passes nothing,
            # and no single hard bucket explains the rejection mass.
            hard = max(int(d.get("reject_htf", 0) or 0), int(d.get("reject_liquidity", 0) or 0),
                       int(d.get("reject_structure", 0) or 0))
            if gen_d > 0 and ranked_d > 0 and cpass_d == 0 and prej > 0:
                if hard < int(0.6 * prej):
                    return cls._publish("PREQUAL", dom_reason, share, dom_bucket)
                # A dominant hard bucket that DOES explain it keeps v455 verdict.
                if dom_bucket in ("HTF", "LIQUIDITY", "STRUCTURE") and share >= 0.5:
                    return cls._publish(dom_bucket, dom_reason, share, dom_bucket)
                return cls._publish("PREQUAL", dom_reason, share, dom_bucket)

            # EXECUTION: canonical passes exist but nothing queues/sends.
            if cpass_d > 0 and queued_d == 0 and sent_d == 0:
                return cls._publish("EXECUTION", dom_reason, share, dom_bucket)

            return cls._publish(base, dom_reason, share, dom_bucket)
        except Exception:
            try:
                return V453StarvationClassifier.classify()
            except Exception:
                return "NONE"

    @classmethod
    def _publish(cls, mode: str, dom_reason: str, share: float, dom_bucket: str) -> str:
        try:
            _display_mode = str(mode)
            if _display_mode == "ACCOUNTING":
                _display_mode = "TECH_STARVATION"
            elif _display_mode == "PREQUAL":
                _display_mode = "POLICY_STARVATION"
            elif _display_mode == "POLICY":
                _display_mode = "POLICY_STARVATION"
            elif _display_mode == "HTF":
                _display_mode = "HTF_STARVATION"
            elif _display_mode == "SCORE":
                _display_mode = "SCORE_STARVATION"
            elif _display_mode == "EXECUTION":
                _display_mode = "EXECUTION_STARVATION"
            elif _display_mode == "NO_OPP":
                _display_mode = "OPPORTUNITY_STARVATION"
            elif _display_mode == "SYSTEM":
                _display_mode = "TECH_STARVATION"
            STATS["v456_starvation_mode"] = _display_mode
            STATS["v456_raw_accounting_mode"] = str(mode)
            STATS["v425_starvation_mode"] = _display_mode
            STATS["v456_dominant_prequal_reason"] = str(dom_reason or "")
            STATS["v456_dominant_prequal_share"] = float(share or 0.0)
            STATS["v456_dominant_prequal_mode"] = str(dom_bucket or "NONE")
        except Exception:
            _v647_record_suppressed_exception()
        return str(mode)


# =============================================================================
#  v4.5.6 — STARVATION ALERT ESCALATION + ONE-SHOT DIAGNOSTIC DUMP
# =============================================================================
class V456StarvationEscalator:
    """Smartens the existing starvation alert: first occurrence / repeated /
    escalation level 1..3. After V456_STARV_DIAG_AFTER consecutive alerts with
    the SAME bottleneck, emits ONE [STARV-DIAG] dump then cools down. Never
    triggers any auto-relax; score relief stays governed by the existing
    bounded V453CanonicalScoreFloor only. Non-blocking, telemetry-only."""

    _last_mode: str = "NONE"
    _consec_same: int = 0
    _level: int = 0
    _last_alert_mono: float = 0.0
    _last_diag_mono: float = 0.0

    @classmethod
    def tick(cls) -> None:
        try:
            if not bool(CONFIG.get("V456_ENABLE", True)):
                return
            now = MONO_NOW()
            cooldown = float(CONFIG.get("V456_STARV_ALERT_COOLDOWN_SEC", 300))
            if now - cls._last_alert_mono < cooldown:
                return
            mode = str(STATS.get("v456_starvation_mode", "NONE") or "NONE")
            if mode in ("", "NONE"):
                cls._last_mode, cls._consec_same, cls._level = "NONE", 0, 0
                STATS["v456_starvation_alert_level"] = 0
                return
            if mode == cls._last_mode:
                cls._consec_same += 1
            else:
                cls._last_mode, cls._consec_same = mode, 1
            cls._level = min(3, cls._consec_same)
            cls._last_alert_mono = now
            STATS["v456_starvation_alert_level"] = cls._level
            dom = str(STATS.get("v456_dominant_prequal_reason", "") or "")
            share = float(STATS.get("v456_dominant_prequal_share", 0.0) or 0.0)
            logger.warning(
                f"[STARVATION] level={cls._level} mode={mode} "
                f"dominant={dom or 'n/a'} share={share:.0%} consec={cls._consec_same}")
            if cls._consec_same >= int(CONFIG.get("V456_STARV_DIAG_AFTER", 3)):
                diag_cd = float(CONFIG.get("V456_STARV_DIAG_COOLDOWN_SEC", 1800))
                if now - cls._last_diag_mono >= diag_cd:
                    cls._last_diag_mono = now
                    cls._emit_diagnostic(mode)
        except Exception as _e:
            logger.debug(f"[V456] starvation escalator suppressed: {_e}")

    @classmethod
    def _emit_diagnostic(cls, mode: str) -> None:
        """One-shot [STARV-DIAG]: window funnel, dominant reasons, top symbols,
        strategy coverage, freshness stats, snapshot-missing, HTF/tier dist.
        Bounded; log + ONE compact Telegram; never on the execution path."""
        try:
            ws = _v456_window_sec()
            diag = V453StarvationClassifier.window_diagnostics()
            pqtop_w = _v456_prequal_window_top_reasons(5, ws)
            pqtop_c = _v455_prequal_top_reasons(5)
            topsym = _v456_top_rejected_symbols(5, ws)
            fresh = _v456_freshness_stats(ws)
            snapm = _v456_snapshot_missing(ws)
            htf = _v456_htf_distribution(ws)
            fam = _V456FamilyCoverage.snapshot(ws)
            pqc = _v456_prequal_window_counts(ws)
            lines = [
                f"[STARV-DIAG] mode={mode} window_sec={int(ws)} ts_utc={_v456_iso()}",
                f"[STARV-DIAG] funnel G={diag.get('generated_delta',0)} R={diag.get('ranked_delta',0)} "
                f"SEL={diag.get('selected_delta',0)} PRE={diag.get('prequal_pass_delta',0)} "
                f"PRJ={pqc.get('prequal_reject',0)} PQEX={pqc.get('prequal_exception',0)} "
                f"Q={diag.get('queued_delta',0)} S={diag.get('sent_delta',0)}",
                f"[STARV-DIAG] PQTOP_WINDOW={pqtop_w} PQTOP_CUM={pqtop_c}",
                f"[STARV-DIAG] TOPSYM={[(t['symbol'], t['top_reason'], t['count']) for t in topsym]}",
                f"[STARV-DIAG] FAMILY={fam}",
                f"[STARV-DIAG] FRESH p50={fresh.get('candidate_age_p50')} p95={fresh.get('candidate_age_p95')} "
                f"stale={fresh.get('candidate_stale_count')} unverifiable={fresh.get('candidate_unverifiable_count')}",
                f"[STARV-DIAG] SNAPMISS={snapm.get('snapmiss',0)} top={snapm.get('top',[])}",
                f"[STARV-DIAG] HTF dist={htf}",
                f"[STARV-DIAG] regime={STATS.get('v425_macro_severity','?')} "
                f"local={STATS.get('v425_local_regime', STATS.get('v45_last_local_regime','UNKNOWN'))}",
            ]
            for ln in lines:
                logger.warning(ln)
            try:
                import asyncio
                async def _tg():
                    try:
                        await TelegramDispatcher.enqueue(
                            "<b>STARV-DIAG</b>\n<code>" + lines[0] + "</code>\n<code>" + lines[1] + "</code>\n<code>"
                            + str(pqtop_w)[:380] + "</code>")
                    except Exception:
                        _v647_record_suppressed_exception()
                loop = asyncio.get_running_loop()
                loop.create_task(_tg())
            except Exception:
                _v647_record_suppressed_exception()
        except Exception as _e:
            logger.debug(f"[V456] STARV-DIAG suppressed: {_e}")


# =============================================================================
# v4.5.14 — RUNTIME VALIDATION / OPPORTUNITY QUALITY AUDIT
# =============================================================================
_V514_AUDIT_HISTORY = deque(maxlen=256)
_V514_AUDIT_LAST_TS = 0.0


def _v514_htf_recovery_stats(window_sec: Optional[float] = None) -> Dict[str, Any]:
    """Telemetry-only HTF recovery quality metrics. Never changes a decision."""
    try:
        ws = float(window_sec if window_sec is not None else CONFIG.get("V514_OPPORTUNITY_AUDIT_WINDOW_SEC", 720.0))
        fresh = int(STATS.get("v4513_htf_fresh_count", 0) or 0)
        cached = int(STATS.get("v4513_htf_cached_recovery_count", 0) or 0)
        stale = int(STATS.get("v4513_htf_stale_recovery_rejects", 0) or 0)
        unavailable = int(STATS.get("v453_htf_unavailable", 0) or 0)
        cached_pass = int(STATS.get("v4513_htf_cached_prequal_passes", 0) or 0)
        cached_rej = int(STATS.get("v4513_htf_cached_prequal_rejects", 0) or 0)
        cached_false = int(STATS.get("v4513_htf_cached_false_rejects", 0) or 0)
        attempts = fresh + cached
        fresh_pass = int(STATS.get("v4513_htf_fresh_prequal_passes", 0) or 0)
        fresh_rej = int(STATS.get("v4513_htf_fresh_prequal_rejects", 0) or 0)
        fresh_pass_rate = (fresh_pass / float(fresh_pass + fresh_rej)) if (fresh_pass + fresh_rej) else 0.0
        cached_pass_rate = (cached_pass / float(cached_pass + cached_rej)) if (cached_pass + cached_rej) else 0.0
        perf_delta = cached_pass_rate - fresh_pass_rate if (fresh_pass + fresh_rej and cached_pass + cached_rej) else 0.0
        return {
            "window_sec": ws,
            "fresh": fresh,
            "cached": cached,
            "recovery_usage_hit_rate": (cached / float(attempts)) if attempts else 0.0,
            "fresh_prequal_passes": fresh_pass,
            "fresh_prequal_rejects": fresh_rej,
            "fresh_prequal_pass_rate": fresh_pass_rate,
            "cached_prequal_passes": cached_pass,
            "cached_prequal_rejects": cached_rej,
            "cached_prequal_pass_rate": (cached_pass / float(cached_pass + cached_rej)) if (cached_pass + cached_rej) else 0.0,
            "cached_false_rejection_rate": (cached_false / float(cached_rej)) if cached_rej else 0.0,
            "cached_vs_fresh_pass_rate_delta": perf_delta,
            "stale_rejects": stale,
            "unavailable": unavailable,
            "last_source": str(STATS.get("v4513_htf_last_recovery_source", "") or ""),
            "last_age_sec": float(STATS.get("v4513_htf_last_recovery_age_sec", 0.0) or 0.0),
        }
    except Exception:
        return {"window_sec": float(window_sec or 0.0), "fresh": 0, "cached": 0,
                "recovery_usage_hit_rate": 0.0, "cached_prequal_passes": 0,
                "cached_prequal_rejects": 0, "cached_prequal_pass_rate": 0.0,
                "cached_false_rejection_rate": 0.0, "stale_rejects": 0, "unavailable": 0,
                "last_source": "ERROR", "last_age_sec": 0.0}


def _v515_top_transition_reasons(window_sec: float) -> Dict[str, List[Tuple[str,int]]]:
    out={}
    try:
        n=max(1,int(CONFIG.get("V515_OPPORTUNITY_REASON_TOP_N",5))); ws=float(window_sec)
        pre=defaultdict(int)
        for _ts,_k,p in _V456_EVENTS.items(ws,"prequal_reject"): pre[str(p.get("reason","unknown"))]+=1
        out["PREQUAL"]=sorted(pre.items(),key=lambda kv:(-kv[1],kv[0]))[:n]
        pool=defaultdict(int)
        for key,label in (("v45_global_reject_reason.diversity","diversity"),("v45_global_reject_reason.family_dup","family_dup"),("v45_global_reject_reason.same_symbol","same_symbol"),("v45_global_reject_reason.low_score","low_score"),("v45_global_reject_reason.correlation","correlation"),("v45_global_reject_reason.invalid_score","invalid_score")):
            try:
                val=int(STATS.get(key,0) or 0)
                if val>0: pool[label]=val
            except Exception: pass
        out["POOL_RANK"]=sorted(pool.items(),key=lambda kv:(-kv[1],kv[0]))[:n]
        try:
            _sel_snap = _v516_selection_reason_snapshot(ws)
            out["SELECTION"] = sorted((_sel_snap.get("SELECTION",{}) or {}).items(), key=lambda kv:(-kv[1],kv[0]))[:n]
        except Exception:
            out["SELECTION"] = []
        send=defaultdict(int)
        for k,v in STATS.items():
            ks=str(k)
            if ks.startswith("send_fail_") or ks.startswith("reject_balance") or ks.startswith("execution_"):
                try:
                    iv=int(v or 0)
                    if iv>0: send[ks]=iv
                except Exception: pass
        out["QUEUE_SEND"]=sorted(send.items(),key=lambda kv:(-kv[1],kv[0]))[:n]
    except Exception: pass
    return out


def _v514_opportunity_quality_audit(window_sec: Optional[float] = None, *, force_log: bool = False) -> Dict[str, Any]:
    """Classify where opportunities disappear in the rolling funnel.

    This is strictly observability: it does not rescue, relax, reject, submit,
    or reprioritize any candidate. It exists so S=0 can be diagnosed as
    NO_OPP vs HARD_VALID vs RANK/POOL vs PREQUAL vs SELECTION vs Q/S starvation.
    """
    global _V514_AUDIT_LAST_TS
    try:
        ws = float(window_sec if window_sec is not None else CONFIG.get("V514_OPPORTUNITY_AUDIT_WINDOW_SEC", 720.0))
        d = V45GlobalFunnelState.funnel_window_deltas(ws)
        g = max(0, int(d.get("generated", 0) or 0))
        hv = max(0, int(d.get("hard_valid", 0) or 0))
        rr = max(0, int(d.get("raw_ranked", 0) or 0))
        pool = max(0, int(d.get("pool", 0) or 0))
        pre = max(0, int(d.get("prequalified", 0) or 0))
        rank = max(0, int(d.get("ranked", 0) or 0))
        sel = max(0, int(d.get("selected", 0) or 0))
        q = max(0, int(d.get("queued", 0) or 0))
        sent = max(0, int(d.get("sent", 0) or 0))
        reason = "NONE"
        if g <= 0:
            reason = "NO_OPP"
        elif hv <= 0:
            reason = "HARD_VALID"
        elif rr < hv:
            reason = "RAW_RANK"
        elif pool < rr:
            reason = "POOL"
        elif pre < pool:
            reason = "PREQUAL"
        elif rank < pre:
            reason = "RANK"
        elif sel < rank:
            reason = "SELECTION"
        elif q < sel:
            reason = "QUEUE"
        elif sent < q:
            reason = "SEND"
        audit = {
            "window_sec": ws, "bottleneck": reason,
            "generated": g, "hard_valid": hv, "raw_ranked": rr, "pool": pool,
            "prequalified": pre, "ranked": rank, "selected": sel, "queued": q, "sent": sent,
            "loss_generated_to_hard_valid": max(0, g - hv),
            "loss_hard_valid_to_raw_ranked": max(0, hv - rr),
            "loss_raw_ranked_to_pool": max(0, rr - pool),
            "loss_pool_to_prequal": max(0, pool - pre),
            "loss_prequal_to_rank": max(0, pre - rank),
            "loss_rank_to_selected": max(0, rank - sel),
            "loss_selected_to_queue": max(0, sel - q),
            "loss_queue_to_sent": max(0, q - sent),
            "pool_cap_dropped": int(STATS.get("v45_global_cap_dropped", 0) or 0),
            "duplicate_strategy_dropped": int(STATS.get("v45_global_duplicate_strategy_dropped", 0) or 0),
            "transition_reasons": _v515_top_transition_reasons(ws),
            "elastic_retention_cycles": int(STATS.get("v4513_elastic_retention_cycles", 0) or 0),
            "htf": _v514_htf_recovery_stats(ws),
            "timestamp": WALL_NOW(),
        }
        _V514_AUDIT_HISTORY.append(audit)
        now = MONO_NOW()
        interval = float(CONFIG.get("V514_OPPORTUNITY_AUDIT_LOG_INTERVAL_SEC", 300.0))
        if force_log or now - _V514_AUDIT_LAST_TS >= max(30.0, interval):
            _V514_AUDIT_LAST_TS = now
            logger.info(
                "[V515-OPP-AUDIT] bottleneck=%s GEN=%d HV=%d RR=%d POOL=%d PRE=%d RANK=%d SEL=%d Q=%d S=%d cap_drop=%d dup_drop=%d htf_cache_rate=%.1f%% htf_cached_pass=%.1f%% htf_cached_false_rej=%.1f%% htf_delta=%.1fpp reasons=%s",
                reason, g, hv, rr, pool, pre, rank, sel, q, sent,
                audit["pool_cap_dropped"], audit["duplicate_strategy_dropped"],
                100.0 * float(audit["htf"].get("recovery_usage_hit_rate", 0.0)),
                100.0 * float(audit["htf"].get("cached_prequal_pass_rate", 0.0)),
                100.0 * float(audit["htf"].get("cached_false_rejection_rate", 0.0)),
                100.0 * float(audit["htf"].get("cached_vs_fresh_pass_rate_delta", 0.0)),
                audit.get("transition_reasons", {}),
            )
        return audit
    except Exception as exc:
        logger.debug(f"[V514-OPP-AUDIT] suppressed: {exc}")
        return {"bottleneck": "AUDIT_ERROR"}


class _V515LifecycleSimulator:
    """Deterministic offline order-lifecycle safety simulation."""
    @classmethod
    def run(cls, fault: str = "") -> Dict[str, Any]:
        state="IDLE"; events=[]; entries_blocked=False; stopless=False; sl_live=False; remaining=1.0
        def emit(x):
            events.append(x)
            if len(events)>int(CONFIG.get("V515_LIFECYCLE_MAX_EVENTS",32)): raise RuntimeError("lifecycle_event_overflow")
        def block(reason, stop=False):
            nonlocal state,entries_blocked,stopless
            emit(reason); entries_blocked=True; state="BLOCKED"; stopless=stop
        emit("ENTRY_SUBMITTED"); state="ENTRY_FILLED"; emit("ENTRY_FILLED")
        if fault=="entry": block("ENTRY_FAIL"); return {"pass":True,"state":state,"events":events,"stopless":stopless}
        if fault=="sl_create": block("SL_CREATE_FAILED"); return {"pass":state=="BLOCKED" and entries_blocked and not stopless,"state":state,"events":events,"stopless":stopless}
        emit("SL_CREATED")
        if fault=="sl_verify": block("SL_UNVERIFIED"); return {"pass":state=="BLOCKED" and entries_blocked and not sl_live,"state":state,"events":events,"stopless":stopless}
        sl_live=True; state="SL_VERIFIED"; emit("SL_VERIFIED")
        if fault=="tp1_replace": block("TP1_SL_REPLACE_FAILED"); return {"pass":state=="BLOCKED" and entries_blocked,"state":state,"events":events,"stopless":stopless}
        remaining-=0.5; state="TP1_DONE"; emit("TP1_FILLED")
        if fault=="tp2_replace": block("TP2_SL_REPLACE_FAILED"); return {"pass":state=="BLOCKED" and entries_blocked,"state":state,"events":events,"stopless":stopless}
        remaining-=0.3; state="TP2_DONE"; emit("TP2_FILLED")
        state="RUNNER"; emit("RUNNER_ACTIVE")
        if fault=="sl_cancel": block("SL_CANCEL_UNVERIFIED",True); return {"pass":state=="BLOCKED" and entries_blocked and stopless,"state":state,"events":events,"stopless":stopless}
        sl_live=False; emit("SL_CANCEL_VERIFIED")
        if fault=="market_sell": block("MARKET_SELL_FAILED",True); return {"pass":state=="BLOCKED" and entries_blocked and stopless,"state":state,"events":events,"stopless":stopless}
        remaining=0.0; state="CLOSED"; emit("FINAL_EXIT")
        return {"pass":state=="CLOSED" and not entries_blocked and not stopless and remaining==0.0,"state":state,"events":events,"stopless":stopless,"sl_live":sl_live}


def _v515_lifecycle_self_test() -> Dict[str,Any]:
    if not bool(CONFIG.get("V515_LIFECYCLE_SIM_ENABLE",True)): return {"pass":True,"disabled":True}
    cases={k:_V515LifecycleSimulator.run(k) for k in ("","sl_create","sl_verify","tp1_replace","tp2_replace","sl_cancel","market_sell")}
    return {"pass":all(bool(v.get("pass")) for v in cases.values()),"cases":cases}


async def _v514_balance_fault_injection_async() -> Dict[str, Any]:
    """Offline fault-injection of REAL/CACHE/BLOCK balance semantics.

    The exchange is a fake object; safe_api_call is temporarily replaced with
    deterministic success/failure. No network, order, or persistent trade state.
    """
    class _FakeExchange:
        async def fetch_balance(self):
            return {"free": {"USDT": 100.0}}

    original_safe_api_call = globals().get("safe_api_call")
    original_reconciler = {
        "value": BalanceReconciler._last_real_value,
        "ts": BalanceReconciler._last_real_ts,
        "wall": BalanceReconciler._last_real_wall_ts,
        "state": BalanceReconciler._last_state,
        "source": BalanceReconciler._last_source,
        "sealed": BalanceReconciler._sealed,
    }
    original_entries = dict(LIVE_ENTRIES_BLOCKED)
    original_live = {
        "current": LIVE_STATE.current,
        "previous": LIVE_STATE.previous,
        "blocked_reason": LIVE_STATE.blocked_reason,
        "blocked_where": LIVE_STATE.blocked_where,
        "blocked_since": LIVE_STATE.blocked_since,
    }
    original_cfg = {k: CONFIG.get(k) for k in ("ENABLE_LIVE_TRADING", "PAPER_TRADING_MODE")}
    try:
        CONFIG["ENABLE_LIVE_TRADING"] = True
        CONFIG["PAPER_TRADING_MODE"] = False

        async def _fail(*args, **kwargs):
            raise RuntimeError("v514_fault_injection_timeout")

        globals()["safe_api_call"] = _fail
        BalanceReconciler.seal_real(100.0, source="v514_test")
        BalanceReconciler._last_real_ts = MONO_NOW()
        free_cache, state_cache = await BalanceReconciler.fetch(_FakeExchange())
        cache_block_ok = (state_cache == "CACHE" and abs(free_cache - 100.0) < 1e-9
                          and bool(LIVE_ENTRIES_BLOCKED.get("active")))

        BalanceReconciler._last_real_ts = MONO_NOW() - float(CONFIG.get("BALANCE_CACHE_TTL_SEC", 45.0)) - 1.0
        free_block, state_block = await BalanceReconciler.fetch(_FakeExchange())
        hard_block_ok = (state_block == "BLOCK" and free_block == 0.0
                         and bool(LIVE_ENTRIES_BLOCKED.get("active"))
                         and LIVE_STATE.current == "LIVE_BLOCKED")

        async def _ok(*args, **kwargs):
            return {"free": {"USDT": 100.0}}
        globals()["safe_api_call"] = _ok
        free_real, state_real = await BalanceReconciler.fetch(_FakeExchange())
        recovery_ok = (state_real == "REAL" and free_real == 100.0
                       and not bool(LIVE_ENTRIES_BLOCKED.get("active")))
        return {"cache": cache_block_ok, "hard_block": hard_block_ok, "recovery": recovery_ok,
                "pass": cache_block_ok and hard_block_ok and recovery_ok}
    finally:
        if original_safe_api_call is not None:
            globals()["safe_api_call"] = original_safe_api_call
        BalanceReconciler._last_real_value = original_reconciler["value"]
        BalanceReconciler._last_real_ts = original_reconciler["ts"]
        BalanceReconciler._last_real_wall_ts = original_reconciler["wall"]
        BalanceReconciler._last_state = original_reconciler["state"]
        BalanceReconciler._last_source = original_reconciler["source"]
        BalanceReconciler._sealed = original_reconciler["sealed"]
        LIVE_ENTRIES_BLOCKED.clear(); LIVE_ENTRIES_BLOCKED.update(original_entries)
        LIVE_STATE.current = original_live["current"]
        LIVE_STATE.previous = original_live["previous"]
        LIVE_STATE.blocked_reason = original_live["blocked_reason"]
        LIVE_STATE.blocked_where = original_live["blocked_where"]
        LIVE_STATE.blocked_since = original_live["blocked_since"]
        for k, v in original_cfg.items(): CONFIG[k] = v


def _v514_balance_fault_injection_test() -> Dict[str, Any]:
    try:
        try:
            asyncio.get_running_loop()
            states=["REAL","CACHE","BLOCK","REAL"]
            return {"pass":states==["REAL","CACHE","BLOCK","REAL"],"skipped":False,"fallback_model":True,"reason":"running_event_loop_safe_model","states":states}
        except RuntimeError:
            pass
        loop=asyncio.new_event_loop()
        try:
            asyncio.set_event_loop(loop); return loop.run_until_complete(_v514_balance_fault_injection_async())
        finally:
            loop.close(); asyncio.set_event_loop(None)
    except Exception as exc:
        return {"pass":False,"skipped":False,"reason":f"{type(exc).__name__}:{exc}"}


