_V516_SELECTION_EVENTS = deque(maxlen=int(CONFIG.get("V516_SELECTION_EVENT_MAX", 4096)))
_V516_COHORT_HISTORY = deque(maxlen=int(CONFIG.get("V516_COHORT_HISTORY_MAX", 256)))
