# Chain validate_config to the existing v4.5.15 validator so the new mandatory
# suite runs whenever V456 boot self-testing is enabled.
_orig_validate_config_v516 = _validate_config_v45

def _validate_config_v516():
    # Existing v4.5.15 validation already invokes _v456_self_test through the
    # v456 wrapper. We keep the function identity stable and only assert that
    # the canonical policy is drift-free after startup normalization.
    ok_base = _orig_validate_config_v516()
    if not ok_base:
        return False
    try:
        rep = _v456_sync_strategy_policy_registries()
        STATS["v516_policy_pre_normalization_drift"] = int(rep.get("pre_normalization_drift",0) or 0)
        STATS["v516_policy_post_normalization_drift"] = int(rep.get("drift_detected",0) or 0)
        if int(rep.get("post_normalization_conflicts", 0) or 0) != 0 or int(rep.get("drift_detected", 0) or 0) != 0:
            logger.critical("[V516] canonical policy remained inconsistent after normalization")
            return False
        if bool(CONFIG.get("V516_CRITICAL_TESTS_STRICT", True)) and bool(CONFIG.get("V45_BOOT_SELFTEST_ENABLE", True)):
            _v456_self_test()
    except Exception as exc:
        logger.critical(f"[V516] comprehensive hardening validation failed: {exc}")
        return False
    return True


