_orig_mse_run_engine_safe_v517 = MultiStrategyEngine._run_engine_safe

@staticmethod
def _v517_run_engine_safe_with_cycle(engine_cls, snapshot):
    out = _orig_mse_run_engine_safe_v517(engine_cls, snapshot)
    try:
        cycle_id = _V517_ACTIVE_CYCLE_ID
        if cycle_id is not None and bool(CONFIG.get("V517_CYCLE_STAMP_ENABLE", True)):
            tagged = []
            for c in out or []:
                fs = dict(getattr(c, "features_snapshot", {}) or {})
                fs["v517_cycle_id"] = int(cycle_id)
                try:
                    c = replace(c, features_snapshot=fs)
                except Exception:
                    # Frozen/non-dataclass candidates cannot be mutated; keep
                    # the audit authoritative via the event cycle_id path.
                    pass
                tagged.append(c)
            out = tagged
    except Exception:
        _v647_record_suppressed_exception()
    return out
MultiStrategyEngine._run_engine_safe = _v517_run_engine_safe_with_cycle

_orig_v516_record_selection_event_v517 = _v516_record_selection_event

def _v517_record_selection_event(stage: str, reason: str, candidate: Any = None,
                                 cycle_id: Optional[int] = None, extra: Optional[Dict[str, Any]] = None) -> None:
    cid = cycle_id
    try:
        if cid is None and _V517_ACTIVE_CYCLE_ID is not None:
            cid = _V517_ACTIVE_CYCLE_ID
    except Exception:
        _v647_record_suppressed_exception()
    return _orig_v516_record_selection_event_v517(stage, reason, candidate, cid, extra)
_v516_record_selection_event = _v517_record_selection_event

# ---- Final cycle wrapper: set active id at GEN and persist cohort after completion.
_orig_rank_and_select_v517 = _orig_rank_and_select_v516.__func__ if hasattr(_orig_rank_and_select_v516, "__func__") else _orig_rank_and_select_v516

@classmethod
def _v517_rank_and_select(cls, market_data_map):
    global _V517_ACTIVE_CYCLE_ID, _V516_CYCLE_ID
    # V681: reuse the outer scanner runtime cycle when one is already armed.
    # This keeps Global Brain, prequal, rejection, and execution telemetry in
    # ONE cycle instead of creating a second hidden cycle inside the brain.
    _runtime_cid = int(STATS.get("v681_runtime_cycle_id", 0) or 0)
    cycle_id = _runtime_cid if _runtime_cid > 0 else _v516_next_cycle_id()
    if _runtime_cid > 0:
        _V516_CYCLE_ID = max(int(_V516_CYCLE_ID), cycle_id)
        STATS["v516_cycle_id"] = cycle_id
    _V517_ACTIVE_CYCLE_ID = cycle_id
    STATS["v517_active_cycle_id"] = cycle_id
    try:
        result = _orig_rank_and_select_v517(cls, market_data_map)
        try:
            for r in result or []:
                c = getattr(r, "candidate", None)
                if c is not None:
                    fs = dict(getattr(c, "features_snapshot", {}) or {})
                    fs["v517_cycle_id"] = cycle_id
                    try:
                        r.candidate = replace(c, features_snapshot=fs)
                    except Exception:
                        _v647_record_suppressed_exception()
        except Exception:
            _v647_record_suppressed_exception()
        return result
    finally:
        try:
            _v516_cohort_record(
                cycle_id,
                generated=int(STATS.get("v45_global_generated", 0) or 0),
                hard_valid=int(STATS.get("v45_global_hard_valid", 0) or 0),
                raw_ranked=int(STATS.get("v45_global_raw_ranked", 0) or 0),
                pool=int(STATS.get("v45_global_pool", 0) or 0),
                prequalified=int(STATS.get("v45_global_prequalified", 0) or 0),
                ranked=int(STATS.get("v45_global_ranked", 0) or 0),
                selected=int(STATS.get("v45_global_winners", 0) or 0),
                canonical_pass=int(STATS.get("global_canonical_pass", 0) or 0),
                canonical_reject=int(STATS.get("global_canonical_reject", 0) or 0),
                queued=int(STATS.get("signals_queued", 0) or 0),
                sent=int(STATS.get("signals_sent", 0) or 0),
            )
        except Exception:
            _v647_record_suppressed_exception()
        _V517_ACTIVE_CYCLE_ID = None
        STATS["v517_active_cycle_id"] = 0
GlobalOpportunityBrain.rank_and_select = _v517_rank_and_select

