def _v553_trigger_from_order(order: Dict[str, Any]) -> Optional[float]:
    try:
        info = order.get("info") or {}
        for key in ("stopPrice", "triggerPrice", "stopLossPrice", "activationPrice"):
            for src in (order, info):
                try:
                    val = src.get(key) if isinstance(src, dict) else None
                    if val is not None and float(val) > 0:
                        return float(val)
                except Exception:
                    continue
    except Exception:
        _v647_record_suppressed_exception()
    return None


def _v553_live_stop_match(rows: List[Dict[str, Any]], *, symbol: str, side: str,
                          qty: float, stop_price: float, expected_id: str = "") -> Optional[Dict[str, Any]]:
    """Match an ACTIVE stop order; unlike _v517_match_order, it never requires filled qty."""
    best = None
    best_ts = -1.0
    tol_base = float(CONFIG.get("SL_POST_CREATE_VERIFY_TOLERANCE_PCT", 0.30))
    amount_tol = float(CONFIG.get("V553_SL_VERIFY_AMOUNT_TOLERANCE_PCT", 5.0))
    for row in list(rows or []):
        try:
            if str(row.get("symbol") or symbol) != symbol:
                continue
            if str(row.get("side") or "").lower() != str(side).lower():
                continue
            rid = str(row.get("id") or "")
            id_match = bool(expected_id and rid and rid == expected_id)
            if not id_match:
                # Similar amount/trigger is only a diagnostic hint. It cannot
                # prove that this bot owns a manually-created or foreign stop.
                continue
            status = str(row.get("status") or "").lower()
            if status and status not in ("open", "new", "pending", "untriggered", "accepted", "active"):
                continue
            if not status and not id_match:
                continue
            trig = _v553_trigger_from_order(row)
            if trig is None or stop_price <= 0:
                continue
            dev = abs(trig - float(stop_price)) / max(float(stop_price), 1e-12) * 100.0
            if dev > max(tol_base, 0.30):
                continue
            try:
                amt = float(row.get("amount") or row.get("origQty") or row.get("quantity") or 0.0)
                amt_ok = (
                    amt > 0.0 and qty > 0.0
                    and abs(amt - float(qty)) / max(float(qty), 1e-12) <= amount_tol / 100.0
                )
            except Exception:
                amt_ok = False
            if not amt_ok:
                continue
            ts = float(row.get("timestamp") or 0.0)
            rank = (1 if id_match else 0, ts)
            best_rank = (1 if best is not None and str(best.get("id") or "") == expected_id else 0, best_ts)
            if best is None or rank > best_rank:
                best = dict(row)
                best_ts = ts
        except Exception:
            continue
    return best


async def _v553_verify_live_stop(exchange, symbol: str, qty: float, stop_price: float,
                                 expected_id: str = "") -> Optional[Dict[str, Any]]:
    """Bounded proof lookup for a stop that may be live but poorly represented by fetch_order()."""
    if not bool(CONFIG.get("V553_SL_OPEN_ORDER_VERIFY_ENABLE", True)):
        return None
    rows: List[Dict[str, Any]] = []
    lookback_ms = int((WALL_NOW() - float(CONFIG.get("V553_SL_VERIFY_LOOKBACK_SEC", 30.0))) * 1000.0)
    max_eps = max(1, int(CONFIG.get("V553_SL_VERIFY_MAX_ENDPOINTS", 3)))
    endpoints = [
        ("fetch_open_orders", getattr(exchange, "fetch_open_orders", None)),
        ("fetch_orders", getattr(exchange, "fetch_orders", None)),
        ("fetch_closed_orders", getattr(exchange, "fetch_closed_orders", None)),
    ]
    used = 0
    for name, fn in endpoints:
        if used >= max_eps or not callable(fn):
            continue
        used += 1
        try:
            if name == "fetch_open_orders":
                raw = await safe_api_call("v553_sl_open_orders", lambda fn=fn: fn(symbol))
            elif name == "fetch_orders":
                raw = await safe_api_call("v553_sl_orders", lambda fn=fn: fn(symbol, lookback_ms))
            else:
                raw = await safe_api_call("v553_sl_closed_orders", lambda fn=fn: fn(symbol))
            if isinstance(raw, dict):
                raw = [raw]
            if isinstance(raw, list):
                rows.extend([dict(x) for x in raw if isinstance(x, dict)])
        except TypeError:
            try:
                raw = await _v517_await_maybe(fn(symbol))
                if isinstance(raw, dict):
                    raw = [raw]
                if isinstance(raw, list):
                    rows.extend([dict(x) for x in raw if isinstance(x, dict)])
            except Exception:
                continue
        except Exception:
            continue
    return _v553_live_stop_match(
        rows, symbol=symbol, side="sell", qty=qty,
        stop_price=stop_price, expected_id=expected_id
    )


_V553_BUY_FILL_CONTEXTS: Dict[str, Dict[str, Any]] = {}
_V553_BUY_FILL_CONTEXTS_LOCK = threading.RLock()


def _v553_store_buy_fill_context(order_id: str, context: Dict[str, Any]) -> None:
    """Keep authoritative fill facts until the matching TradeState adopts them."""
    oid = str(order_id or "").strip()
    if not oid:
        return
    row = dict(context or {})
    row["order_id"] = oid
    row["stored_at"] = float(WALL_NOW())
    with _V553_BUY_FILL_CONTEXTS_LOCK:
        _V553_BUY_FILL_CONTEXTS[oid] = row
        # Bound memory without dropping recent/unadopted execution contexts.
        if len(_V553_BUY_FILL_CONTEXTS) > 2048:
            oldest = sorted(_V553_BUY_FILL_CONTEXTS.items(), key=lambda kv: float(kv[1].get("stored_at", 0.0)))
            for old_id, _ in oldest[:max(1, len(_V553_BUY_FILL_CONTEXTS) - 1536)]:
                _V553_BUY_FILL_CONTEXTS.pop(old_id, None)


def _v553_take_buy_fill_context(order_id: str) -> Optional[Dict[str, Any]]:
    oid = str(order_id or "").strip()
    if not oid:
        return None
    with _V553_BUY_FILL_CONTEXTS_LOCK:
        row = _V553_BUY_FILL_CONTEXTS.pop(oid, None)
    return dict(row) if isinstance(row, dict) else None


def _v702_definitive_no_order_rejection(exc: BaseException) -> bool:
    """Return True only for clear venue rejections that prove no order was accepted.

    Generic network errors, timeouts, and unknown CCXT exceptions deliberately return
    False and remain durable SUBMISSION_UNKNOWN intents.
    """
    name = type(exc).__name__.lower()
    text = str(exc or "").lower()
    definitive_types = {
        "insufficientfunds", "invalidorder", "badrequest", "argumentsrequired",
        "badsymbol", "authenticationerror", "permissiondenied",
    }
    if name in definitive_types:
        return True
    definitive_phrases = (
        "last_mile_authorization_revoked_no_order", "last_mile_kill_switch_no_order",
        "last_mile_entry_block_no_order", "last_mile_candidate_stale_no_order",
        "insufficient balance", "insufficient funds", "not enough balance",
        "invalid symbol", "unknown symbol", "invalid order size",
        "precision is over the maximum", "amount precision", "price precision",
        "min notional", "minimum notional", "lot size filter", "invalid order parameters",
    )
    return any(phrase in text for phrase in definitive_phrases)


async def _v553_reconcile_buy_fill(exchange, symbol: str, order: Dict[str, Any],
                                   requested_qty: float, planned_price: float) -> Tuple[float, float, Dict[str, Any]]:
    """Return actual cumulative filled quantity, authoritative VWAP, and order.

    Partial fills are a real position, not a failed order. Consumers must adopt the
    returned quantity and must not assume the requested quantity executed. An
    oversized reported fill is preserved rather than clipped out of the ledger.
    """
    raw = dict(order or {})
    candidates = [raw]
    oid = str(raw.get("id") or "")
    if bool(CONFIG.get("V553_BUY_FILL_FETCH_ORDER_ENABLE", True)) and oid:
        try:
            settle = float(CONFIG.get("V553_BUY_FILL_FETCH_SETTLE_SEC", 0.20))
            if settle > 0:
                await asyncio.sleep(settle)
            fetched = await safe_api_call(
                "v553_buy_fill_fetch_order",
                lambda: exchange.fetch_order(oid, symbol),
            )
            if isinstance(fetched, dict):
                candidates.insert(0, dict(fetched))
        except Exception:
            _v647_record_suppressed_exception()

    best = candidates[0] if candidates else raw
    best_qty = 0.0
    best_px = 0.0

    for rec in candidates:
        try:
            trades = rec.get("trades") or []
            if isinstance(trades, list) and trades:
                tq = tc = 0.0
                for tr in trades:
                    q = float(tr.get("amount") or tr.get("filled") or 0.0)
                    px = float(tr.get("price") or 0.0)
                    cost = float(tr.get("cost") or (q * px if px > 0 else 0.0))
                    if q > 0 and cost > 0:
                        tq += q
                        tc += cost
                if tq > 0 and tc > 0:
                    best_qty = float(tq)
                    best_px = tc / tq
                    best = rec
                    break

            filled = float(rec.get("filled") or rec.get("executedQty") or 0.0)
            cost = float(rec.get("cost") or 0.0)
            if filled <= 0:
                status = str(rec.get("status") or "").lower()
                if status in ("closed", "filled", "complete"):
                    filled = float(rec.get("amount") or rec.get("origQty") or 0.0)

            if filled > 0 and cost > 0:
                best_qty = float(filled)
                best_px = cost / max(filled, 1e-12)
                best = rec
                break

            avg = float(rec.get("average") or 0.0)
            price = float(rec.get("price") or 0.0)
            if filled > 0 and avg > 0:
                best_qty = float(filled)
                best_px = avg
                best = rec
                break
            if filled > 0 and price > 0:
                best_qty = float(filled)
                best_px = price
                best = rec
                break
        except Exception:
            continue

    if best_qty <= 0 or best_px <= 0:
        raise _V517UnknownExecution("buy_fill_unconfirmed")
    requested = float(requested_qty)
    if not math.isfinite(requested) or requested <= 0.0:
        raise _V517UnknownExecution("buy_requested_quantity_invalid")
    partial = best_qty < requested * float(CONFIG.get("EXIT_FILL_MIN_CONFIRM_RATIO", 0.995))
    oversized = best_qty > requested * 1.005
    if partial:
        STATS["v553_confirmed_partial_buy_fills"] = int(STATS.get("v553_confirmed_partial_buy_fills", 0) or 0) + 1
        logger.critical(
            "[V553-FILL] %s confirmed partial BUY qty=%.10f requested=%.10f; "
            "quantity must be adopted exactly and no full-size replacement BUY is safe",
            symbol, best_qty, requested,
        )
    if oversized:
        STATS["v553_oversized_buy_fills"] = int(STATS.get("v553_oversized_buy_fills", 0) or 0) + 1
        logger.critical(
            "[V553-FILL] %s venue-reported BUY fill exceeds requested qty actual=%.10f requested=%.10f; "
            "preserving full exposure and blocking new entries",
            symbol, best_qty, requested,
        )
        live_entries_block(f"oversized_confirmed_buy_fill_{symbol}", where="_v553_reconcile_buy_fill")

    raw_px = 0.0
    try:
        raw_px = float(raw.get("average") or raw.get("price") or 0.0)
    except Exception:
        raw_px = 0.0
    if raw_px > 0 and abs(best_px - raw_px) / max(raw_px, 1e-12) * 100.0 >= 0.05:
        STATS["v553_buy_fill_price_corrections"] = int(
            STATS.get("v553_buy_fill_price_corrections", 0) or 0
        ) + 1
        logger.warning(
            f"[V553-FILL] {symbol} corrected buy fill raw={raw_px:.8f} "
            f"authoritative={best_px:.8f} dev="
            f"{abs(best_px-raw_px)/max(raw_px,1e-12)*100.0:.4f}%"
        )

    authoritative = dict(best or raw)
    oid = str(authoritative.get("id") or raw.get("id") or "")
    fee_rows = authoritative.get("fees")
    if not isinstance(fee_rows, list):
        fee_rows = [authoritative.get("fee")] if isinstance(authoritative.get("fee"), dict) else []
    # Some spot venues deduct trading fee in base asset. In that case the net
    # sellable amount is lower than gross executed quantity and must be recorded.
    _base_fee_amount = 0.0
    try:
        _market = exchange.market(symbol) or {}
        _base_codes = {str(_market.get("base") or "").upper(), str(_market.get("baseId") or "").upper()}
        _trade_fee_sources = []
        _trades = authoritative.get("trades")
        if isinstance(_trades, list):
            for _tr in _trades:
                if not isinstance(_tr, dict):
                    continue
                _fee = _tr.get("fee")
                if isinstance(_fee, dict): _trade_fee_sources.append(_fee)
                _fees = _tr.get("fees")
                if isinstance(_fees, list): _trade_fee_sources.extend(x for x in _fees if isinstance(x, dict))
        # Per-fill fees may already sum to the top-level aggregate. Never add both.
        _fee_sources = _trade_fee_sources if _trade_fee_sources else list(fee_rows)
        _dedup_fees = []
        _seen_fee_keys = set()
        for _fee in _fee_sources:
            if not isinstance(_fee, dict):
                continue
            _fee_key = (str(_fee.get("currency") or _fee.get("code") or "").upper(),
                        round(float(_fee.get("cost") or _fee.get("amount") or 0.0), 12))
            if _fee_key not in _seen_fee_keys:
                _seen_fee_keys.add(_fee_key)
                _dedup_fees.append(dict(_fee))
        _fee_sources = _dedup_fees
        for _fee in _fee_sources:
            if not isinstance(_fee, dict):
                continue
            _currency = str(_fee.get("currency") or _fee.get("code") or "").upper()
            _amount = float(_fee.get("cost") or _fee.get("amount") or 0.0)
            if _currency and _currency in _base_codes and math.isfinite(_amount) and _amount > 0:
                _base_fee_amount += _amount
    except Exception:
        _base_fee_amount = 0.0
    _net_qty = max(0.0, float(best_qty) - _base_fee_amount)
    if _net_qty <= 0.0:
        live_entries_block(f"buy_fill_net_quantity_invalid_{symbol}", where="_v553_reconcile_buy_fill")
        raise _V517UnknownExecution("buy_fill_net_quantity_non_positive")
    context = {
        "symbol": str(symbol),
        "requested_qty": requested,
        "gross_filled_qty": float(best_qty),
        "filled_qty": float(_net_qty),
        "net_filled_qty": float(_net_qty),
        "base_fee_amount": float(_base_fee_amount),
        "fill_price": float(best_px),
        "fill_cost_estimate": float(best_qty * best_px),
        "partial_fill": bool(partial),
        "oversized_fill": bool(oversized),
        "order_status": str(authoritative.get("status") or "unknown").lower(),
        "entry_reconcile_required": str(authoritative.get("status") or "unknown").lower() not in {
            "closed", "filled", "complete", "canceled", "cancelled", "expired", "rejected"
        },
        "fee_records": [dict(x) for x in fee_rows if isinstance(x, dict)],
        "order_ids": [oid] if oid else [],
        "authoritative_order": {k: authoritative.get(k) for k in ("id", "status", "filled", "cost", "average", "price", "amount", "side", "symbol") if k in authoritative},
    }
    _v553_store_buy_fill_context(oid, context)
    return float(best_qty), float(best_px), authoritative


async def _v553_reconcile_emergency_sell(exchange, trade: TradeState, qty: float,
                                         fallback_px: float, stage: str) -> Optional[Dict[str, Any]]:
    if not bool(CONFIG.get("V553_EMERGENCY_SELL_RECONCILE_ENABLE", True)):
        return None
    try:
        rows = await _v517_fetch_recent_orders(exchange, trade.symbol)
        match = _v517_match_order(
            rows,
            symbol=trade.symbol,
            side="sell",
            qty=float(qty),
            price=fallback_px,
            started_wall=WALL_NOW() - float(CONFIG.get("V553_EMERGENCY_SELL_LOOKBACK_SEC", 30.0)),
            client_order_id=str(getattr(trade, "v517_last_exit_client_order_id", "") or ""),
            require_identity=True,
        )
        if not match:
            return None
        fq, fpx, _ = await _v526_confirm_market_sell(
            exchange, trade.symbol, match, float(qty), fallback_px
        )
        if fq < float(qty) * float(CONFIG.get("V553_EMERGENCY_SELL_FILL_CONFIRM_RATIO", 0.995)):
            return None
        confirmed = dict(match)
        confirmed["_v553_fill_qty"] = float(fq)
        confirmed["_v553_fill_px"] = float(fpx)
        STATS["v553_emergency_sell_recovered"] = int(
            STATS.get("v553_emergency_sell_recovered", 0) or 0
        ) + 1
        logger.critical(
            f"[V553-RECOVER] emergency sell outcome reconciled for {trade.symbol} "
            f"stage={stage} id={confirmed.get('id')} qty={fq:.10f} px={fpx:.8f}"
        )
        return confirmed
    except Exception as exc:
        logger.warning(f"[V553-RECOVER] emergency sell reconciliation failed {trade.symbol}: {exc}")
        return None

# ---- Unknown entry outcome reconciliation ---------------------------------
_orig_submit_entry_v517 = OrderExecutor.submit_entry

@staticmethod
async def _v517_submit_entry(exchange, symbol: str, qty: float, price: float,
                             is_paper: bool = False, trace_id: Optional[str] = None,
                             intent_context: Optional[Dict[str, Any]] = None):
    if not bool(CONFIG.get("V517_UNKNOWN_OUTCOME_RECONCILE_ENABLE", True)):
        return await _orig_submit_entry_v517(exchange, symbol, qty, price, is_paper, trace_id,
                                             intent_context=intent_context)
    proxy = _V517ExchangeProxy(exchange)
    try:
        result = await _orig_submit_entry_v517(proxy, symbol, qty, price, is_paper, trace_id,
                                               intent_context=intent_context)
    except Exception:
        if proxy.unknown_entry:
            live_entries_block(f"execution_unknown_entry_{symbol}", where="OrderExecutor.submit_entry")
        raise
    if proxy.unknown_entry and not result[0]:
        _late_match = None
        try:
            for _i in range(
                max(1, int(CONFIG.get("V559_AMBIGUOUS_ENTRY_RECONCILE_ATTEMPTS", 2)))
            ):
                if _i > 0:
                    await asyncio.sleep(max(
                        0.10,
                        float(CONFIG.get("V559_AMBIGUOUS_ENTRY_RECONCILE_DELAY_SEC", 0.50))
                    ))
                _rows = await _v517_fetch_recent_orders(exchange, symbol)
                _late_match = _v517_match_order(
                    _rows, symbol=symbol, side="buy", qty=qty, price=price,
                    started_wall=proxy.entry_started_wall or (
                        WALL_NOW() - float(CONFIG.get("V517_UNKNOWN_ORDER_LOOKBACK_SEC", 20.0))
                    ),
                    client_order_id=proxy.entry_client_order_id, require_identity=True,
                )
                if _late_match:
                    break
        except Exception:
            _late_match = None

        if _late_match:
            try:
                _fq, _fa, _ = await _v553_reconcile_buy_fill(
                    exchange, symbol, _late_match, qty, price
                )
                proxy.unknown_entry = False
                STATS["v560_late_unknown_entry_recovered"] = int(
                    STATS.get("v560_late_unknown_entry_recovered", 0) or 0
                ) + 1
                (logger.info if bool(globals().get("V644_SELFTEST_ACTIVE", False)) else logger.critical)(
                    f"[V560-RECON] late BUY fill recovered {symbol} "
                    f"id={_late_match.get('id')} — no duplicate BUY"
                )
                return True, str(_late_match.get("id") or ""), float(_fa)
            except Exception as _late_e:
                (logger.warning if bool(globals().get("V644_SELFTEST_ACTIVE", False)) else logger.critical)(
                    f"[V560-RECON] recovered BUY could not be reconciled {symbol}: {_late_e}"
                )

        live_entries_block(
            f"execution_unknown_entry_{symbol}",
            where="OrderExecutor.submit_entry"
        )
        STATS["v517_unknown_entry_unresolved"] = int(
            STATS.get("v517_unknown_entry_unresolved", 0) or 0
        ) + 1
        if bool(globals().get("V644_SELFTEST_ACTIVE", False)):
            logger.warning(
                f"[V517-RECON-SELFTEST] UNKNOWN ENTRY UNRESOLVED {symbol}; "
                "synthetic test entry block only; cleared before the live runtime epoch"
            )
        else:
            logger.critical(
                f"[V517-RECON] UNKNOWN ENTRY UNRESOLVED {symbol}; NEW ENTRIES BLOCKED"
            )
    return result
OrderExecutor.submit_entry = _v517_submit_entry


# ---- Unknown SL outcome reconciliation ------------------------------------
_orig_place_sl_v517 = OrderExecutor.place_sl

@staticmethod
async def _v517_place_sl(exchange, trade: TradeState, sl_price_override: Optional[float] = None):
    if not bool(CONFIG.get("V517_UNKNOWN_OUTCOME_RECONCILE_ENABLE", True)):
        return await _orig_place_sl_v517(exchange, trade, sl_price_override)
    proxy = _V517ExchangeProxy(exchange)
    result = await _orig_place_sl_v517(proxy, trade, sl_price_override)
    if proxy.unknown_stop and not result[0]:
        trade.v517_pending_sl_reconcile = {
            "ts": WALL_NOW(),
            "attempts": 0,
            "symbol": trade.symbol,
            "qty": float(getattr(trade, "remaining_position", getattr(trade, "position_size_asset", 0.0)) or 0.0),
            "price": float(sl_price_override if sl_price_override is not None else getattr(trade, "current_sl", 0.0) or 0.0),
            "client_order_id": str(proxy.stop_client_order_id or getattr(trade, "sl_client_order_id", "") or ""),
        }
        trade.sl_health_state = "SL_CREATE_UNKNOWN"
        trade.sl_failure_reason = "exchange_stop_create_unknown_outcome"
        live_entries_block(f"execution_unknown_sl_{trade.symbol}", where="OrderExecutor.place_sl")
        STATS["v517_unknown_sl_unresolved"] = int(STATS.get("v517_unknown_sl_unresolved", 0) or 0) + 1
        (logger.warning if bool(globals().get("V644_SELFTEST_ACTIVE", False)) else logger.critical)(f"[V517-RECON] UNKNOWN SL UNRESOLVED {trade.symbol}; SL creation frozen until reconciliation")
    return result
OrderExecutor.place_sl = _v517_place_sl


# ---- Cancel reconciliation: if cancel response is ambiguous, prove state before returning False.
_orig_cancel_order_safe_v517 = OrderExecutor.cancel_order_safe

@staticmethod
async def _v517_cancel_order_safe(exchange, order_id: str, symbol: str) -> bool:
    try:
        ok = await _orig_cancel_order_safe_v517(exchange, order_id, symbol)
        if ok:
            return True
        # A false result is ambiguous; perform one bounded explicit status proof.
        try:
            fetched = await safe_api_call("cancel_reconcile_fetch", exchange.fetch_order(order_id, symbol))
            status = str((fetched or {}).get("status") or "").lower()
            if status in ("canceled", "cancelled"):
                STATS["v517_cancel_unknown_recovered"] = int(STATS.get("v517_cancel_unknown_recovered", 0) or 0) + 1
                return True
        except Exception:
            _v647_record_suppressed_exception()
        return False
    except Exception as exc:
        if _v517_is_unknown_execution_error(exc):
            try:
                fetched = await safe_api_call("cancel_unknown_reconcile", exchange.fetch_order(order_id, symbol))
                status = str((fetched or {}).get("status") or "").lower()
                if status in ("canceled", "cancelled"):
                    STATS["v517_cancel_unknown_recovered"] = int(STATS.get("v517_cancel_unknown_recovered", 0) or 0) + 1
                    return True
            except Exception:
                _v647_record_suppressed_exception()
        return False
OrderExecutor.cancel_order_safe = _v517_cancel_order_safe


# ---- v4.5.26 EXIT FILL CONFIRMATION HELPERS -------------------------------
def _v526_order_fill_details(order: Dict[str, Any], requested_qty: float,
                             fallback_px: float) -> Tuple[float, float, str]:
    order = dict(order or {})
    req=max(0.0,float(requested_qty or 0.0))
    try: filled=float(order.get("filled") or 0.0)
    except Exception: filled=0.0
    try: avg=float(order.get("average") or order.get("price") or 0.0)
    except Exception: avg=0.0
    status=str(order.get("status") or "").lower()
    if filled <= 0 and status in ("closed","filled"):
        try: amt=float(order.get("amount") or 0.0)
        except Exception: amt=0.0
        if amt > 0: filled=min(req,amt)
    if filled <= 0 or not math.isfinite(filled):
        raise _V517UnknownExecution("market_sell_fill_unconfirmed")
    if filled > req * 1.005:
        raise RuntimeError(f"sell_fill_oversized:{filled}>{req}")
    if avg <= 0 or not math.isfinite(avg):
        avg=float(fallback_px or 0.0)
    if avg <= 0:
        raise _V517UnknownExecution("market_sell_average_unconfirmed")
    return min(filled,req),avg,status

async def _v526_confirm_market_sell(exchange, symbol: str, order: Dict[str, Any],
                                    requested_qty: float, fallback_px: float) -> Tuple[float,float,Dict[str,Any]]:
    try:
        filled,avg,_=_v526_order_fill_details(order,requested_qty,fallback_px)
        return filled,avg,dict(order or {})
    except Exception:
        if not bool(CONFIG.get("EXIT_FILL_RECONCILE_FETCH_ORDER_ENABLE",True)):
            raise
    oid=str((order or {}).get("id") or "")
    if not oid:
        raise _V517UnknownExecution("market_sell_no_order_id_for_reconcile")
    fetched=await safe_api_call("fetch_exit_fill",lambda: exchange.fetch_order(oid,symbol))
    filled,avg,_=_v526_order_fill_details(fetched,requested_qty,fallback_px)
    return filled,avg,dict(fetched or {})

def _v526_event_r(trade: "TradeState", px: float) -> float:
    try:
        risk_unit=max(float(trade.entry)-float(trade.original_sl),1e-12)
        return (float(px)-float(trade.entry))/risk_unit
    except Exception:
        return 0.0

# ---- Market sell reconciliation helpers -----------------------------------
async def _v517_market_sell_reconciled(exchange, trade: TradeState, symbol: str,
                                       qty: float, cur_px: float, stage: str):
    started=WALL_NOW()
    _inflight_attr = None
    if bool(CONFIG.get("V572_EXIT_PARTIAL_INFLIGHT_GUARD_ENABLE", True)):
        if str(stage) == "tp1_sell":
            _inflight_attr = "tp1_exit_in_progress"
        elif str(stage) == "tp2_sell":
            _inflight_attr = "tp2_exit_in_progress"
        if _inflight_attr:
            if bool(getattr(trade, _inflight_attr, False)):
                raise _V517UnknownExecution(f"duplicate_exit_inflight:{stage}")
            setattr(trade, _inflight_attr, True)
    try:
        allowed, authority = _v571_exit_authority(
            trade, reason=str(stage), exit_px=cur_px, stage=str(stage)
        )
        if not allowed:
            STATS["v571_exit_authority_blocks"] = int(
                STATS.get("v571_exit_authority_blocks", 0) or 0
            ) + 1
            logger.critical(
                f"[V571-EXIT] BLOCKED market SELL {symbol} stage={stage} "
                f"authority={authority} px={cur_px:.10g}"
            )
            raise _V517UnknownExecution(f"exit_authority_block:{authority}")
        STATS["v571_authorized_market_sells"] = int(
            STATS.get("v571_authorized_market_sells", 0) or 0
        ) + 1
        order=await _v572_submit_market_sell_authorized(
            exchange, trade, qty, cur_px, str(stage), stage=str(stage)
        )
        filled_qty,actual_px,confirmed=await _v526_confirm_market_sell(
            exchange,symbol,order,qty,cur_px
        )
        if filled_qty < float(qty)*float(CONFIG.get("EXIT_FILL_MIN_CONFIRM_RATIO",0.995)):
            trade.v517_pending_exit_reconcile={
                "stage":str(stage),"qty":float(qty),"price":float(cur_px),
                "ts":started,"attempts":0,"symbol":symbol,
                "order_id":str((confirmed or {}).get("id") or ""),
                "client_order_id":str(getattr(trade, "v517_last_exit_client_order_id", "") or ""),
                "filled_qty":float(filled_qty),"fill_px":float(actual_px),
            }
            live_entries_block(f"partial_exit_fill_{stage}_{symbol}",where=f"PositionManager.{stage}")
            STATS[f"partial_{stage}_fill"]=int(STATS.get(f"partial_{stage}_fill",0) or 0)+1
            if _inflight_attr:
                setattr(trade, _inflight_attr, False)
            raise _V517UnknownExecution(f"{stage} partial fill {filled_qty:.10f}/{float(qty):.10f}")
        confirmed=dict(confirmed or {})
        confirmed["_v526_fill_qty"]=float(filled_qty)
        confirmed["_v526_fill_px"]=float(actual_px)
        confirmed["_v526_stage"]=str(stage)
        if _inflight_attr:
            setattr(trade, _inflight_attr, False)
        return confirmed
    except Exception as exc:
        if isinstance(exc,_V517UnknownExecution) and hasattr(trade,"v517_pending_exit_reconcile"):
            raise
        if not _v517_is_unknown_execution_error(exc) or not bool(CONFIG.get("V517_UNKNOWN_OUTCOME_RECONCILE_ENABLE",True)):
            raise
        rows=await _v517_fetch_recent_orders(exchange,symbol)
        _exit_client_id = str(getattr(trade, "v517_last_exit_client_order_id", "") or "")
        match=_v517_match_order(rows,symbol=symbol,side="sell",qty=qty,price=cur_px,started_wall=started,
                               client_order_id=_exit_client_id, require_identity=True)
        if match:
            try:
                fq,fpx,_=await _v526_confirm_market_sell(exchange,symbol,match,qty,cur_px)
            except Exception:
                fq=float(match.get("filled") or 0.0)
                fpx=float(match.get("average") or match.get("price") or cur_px)
            match=dict(match); match["_v526_fill_qty"]=fq; match["_v526_fill_px"]=fpx
            STATS[f"v517_unknown_{stage}_recovered"]=int(STATS.get(f"v517_unknown_{stage}_recovered",0) or 0)+1
            (logger.info if bool(globals().get("V644_SELFTEST_ACTIVE", False)) else logger.critical)(f"[V517-RECON] recovered UNKNOWN {stage.upper()} outcome {symbol} id={match.get('id')}")
            if _inflight_attr:
                setattr(trade, _inflight_attr, False)
            return match
        trade.v517_pending_exit_reconcile={
            "stage":str(stage),"qty":float(qty),"price":float(cur_px),
            "ts":started,"attempts":0,"symbol":symbol,
            "client_order_id":str(getattr(trade, "v517_last_exit_client_order_id", "") or ""),
        }
        live_entries_block(f"execution_unknown_{stage}_{symbol}",where=f"PositionManager.{stage}")
        STATS[f"v517_unknown_{stage}_unresolved"]=int(STATS.get(f"v517_unknown_{stage}_unresolved",0) or 0)+1
        raise _V517UnknownExecution(f"{stage} outcome unknown: {exc}") from exc


async def _v517_reconcile_pending_sl(exchange: Any, trade: TradeState) -> bool:
    p = getattr(trade, "v517_pending_sl_reconcile", None)
    if not isinstance(p, dict):
        return True
    _pst = str(p.get("stage", "") or "")
    if _pst == "tp1_sell":
        trade.tp1_exit_in_progress = False
    elif _pst == "tp2_sell":
        trade.tp2_exit_in_progress = False
    attempts = int(p.get("attempts", 0) or 0) + 1
    p["attempts"] = attempts
    if WALL_NOW() - float(p.get("ts", WALL_NOW())) > float(CONFIG.get("V517_UNKNOWN_PENDING_TTL_SEC", 180.0)):
        trade.sl_health_state = "SL_CREATE_UNKNOWN_STALE"
        STATS["v517_unknown_sl_stale"] = int(STATS.get("v517_unknown_sl_stale", 0) or 0) + 1
        return False
    rows = await _v517_fetch_recent_orders(exchange, trade.symbol)
    match = _v517_match_order(rows, symbol=trade.symbol, side="sell", qty=float(p.get("qty", 0.0)),
                               stop_price=float(p.get("price", 0.0)), started_wall=float(p.get("ts", WALL_NOW())),
                               client_order_id=str(p.get("client_order_id") or ""), require_identity=True)
    if not match:
        return False
    oid = str(match.get("id") or "")
    if not oid:
        return False
    trade.sl_order_id = oid
    trade.sl_health_state = "CONFIRMED"
    trade.sl_last_verified_ts = MONO_NOW()
    trade.sl_covered_qty = float(p.get("qty", 0.0) or 0.0)
    trade.sl_failure_reason = ""
    try:
        delattr(trade, "v517_pending_sl_reconcile")
    except Exception:
        _v647_record_suppressed_exception()
    logger.critical(f"[V517-RECON] pending SL reconciled {trade.symbol} id={oid}")
    return True



async def _v517_reconcile_pending_exit(exchange: Any, trade: TradeState) -> bool:
    p = getattr(trade, "v517_pending_exit_reconcile", None)
    if not isinstance(p, dict):
        return True
    attempts = int(p.get("attempts", 0) or 0) + 1
    p["attempts"] = attempts
    rows = await _v517_fetch_recent_orders(exchange, trade.symbol)
    match = _v517_match_order(rows, symbol=trade.symbol, side="sell", qty=float(p.get("qty", 0.0)),
                               price=float(p.get("price", 0.0)), started_wall=float(p.get("ts", WALL_NOW())),
                               client_order_id=str(p.get("client_order_id") or ""), require_identity=True)
    if not match and str(p.get("order_id") or "").strip():
        try:
            _known = await safe_api_call("pending_exit_fetch_known_order", lambda: exchange.fetch_order(str(p.get("order_id")), trade.symbol))
            if isinstance(_known, dict) and str(_known.get("id") or "") == str(p.get("order_id")):
                match = _known
        except Exception:
            _v647_record_suppressed_exception()
    if not match:
        if WALL_NOW() - float(p.get("ts", WALL_NOW())) > float(CONFIG.get("V517_UNKNOWN_PENDING_TTL_SEC", 180.0)):
            trade.status = "execution_unknown_stale"
            STATS["v517_unknown_exit_stale"] = int(STATS.get("v517_unknown_exit_stale", 0) or 0) + 1
        return False
    try:
        qty, px, _ = _v526_order_fill_details(
            match, float(p.get("qty", 0.0) or 0.0), float(p.get("price") or 0.0)
        )
    except Exception:
        return False
    qty = min(qty, float(getattr(trade, "remaining_position", 0.0) or 0.0))
    if qty <= 0:
        try: delattr(trade, "v517_pending_exit_reconcile")
        except Exception: pass
        return True
    trade.remaining_position = max(0.0, float(trade.remaining_position) - qty)
    trade.total_sold_qty += qty
    trade.last_partial_exit_price = px
    stage = str(p.get("stage", ""))
    if stage == "tp1_sell":
        trade.status = "tp1_hit"
        await OpportunityTelegramNotifier.notify_exit_event(
            trade, "TP1 HIT (RECONCILED)", fill_px=px, fill_qty=qty,
            pnl_r=_v526_event_r(trade, px), remaining=trade.remaining_position
        )
        trade.partial_tp_records.append({"level":"TP1","px":px,"qty":qty,"ts":WALL_NOW(),"reconciled":True})
        async with HandoffOwnership.lock_for(trade.symbol):
            be_ok = await ExitManager.move_to_break_even(exchange, trade)
        if not be_ok and trade.remaining_position > 0:
            await OrderExecutor.emergency_close(exchange, trade, "tp1_be_replace_failed_reconciled")
            return trade.status not in ("sl_unverified", "execution_unknown_stale")
    elif stage == "tp2_sell":
        trade.status = "tp2_hit"
        await OpportunityTelegramNotifier.notify_exit_event(
            trade, "TP2 HIT (RECONCILED)", fill_px=px, fill_qty=qty,
            pnl_r=_v526_event_r(trade, px), remaining=trade.remaining_position,
            extra="Runner remains after TP2; protection is re-bound before trailing."
        )
        trade.partial_tp_records.append({"level":"TP2","px":px,"qty":qty,"ts":WALL_NOW(),"reconciled":True})
        if trade.remaining_position > 0 and trade.sl_order_id:
            async with HandoffOwnership.lock_for(trade.symbol):
                ok_cancel = await OrderExecutor.cancel_order_safe(exchange, trade.sl_order_id, trade.symbol)
                if ok_cancel:
                    trade.sl_order_id = None
                    place_ok, _ = await OrderExecutor.place_sl(exchange, trade)
                else:
                    place_ok = False
            if not place_ok and trade.remaining_position > 0:
                await OrderExecutor.emergency_close(exchange, trade, "tp2_sl_replace_failed_reconciled")
                return False
    try:
        delattr(trade, "v517_pending_exit_reconcile")
    except Exception:
        _v647_record_suppressed_exception()
    STATS[f"v517_{stage}_reconciled"] = int(STATS.get(f"v517_{stage}_reconciled", 0) or 0) + 1
    return True


# ---- Patch the two real TP sell call sites to use reconciled execution. ----
# Exact source replacement is limited to the already-existing TP1/TP2 order
# submission statements; no exit sizing or hard gate changes are made.
# (The replacements are applied at generation time below by the build script.)


async def _v517_noop_async_awaitable(awaitable):
    return await awaitable

def _v517_run_awaitable_sync(awaitable):
    try:
        asyncio.get_running_loop()
        # Embedded hosts (for example notebook/event-loop runners) cannot nest
        # asyncio.run(). Close coroutine objects before returning so the caller
        # never leaks an unawaited coroutine warning.
        try:
            if hasattr(awaitable, "close"):
                awaitable.close()
        except Exception:
            pass
        return {"pass": False, "skipped": True, "reason": "active_event_loop_requires_async_test"}
    except RuntimeError:
        loop = asyncio.new_event_loop()
        try:
            asyncio.set_event_loop(loop)
            return loop.run_until_complete(awaitable)
        finally:
            loop.close(); asyncio.set_event_loop(None)

# ---- v4.5.19 bridge + indicator closure self-test ------------------------
def _v519_bridge_indicator_selftest() -> Dict[str, Any]:
    results = {}
    if not _PDNP_OK:
        return {"pass": False, "results": {"pandas_numpy_available": False}, "skipped": True}
    try:
        # Monotonic RSI fallback must be finite and correctly bounded.
        _idx = pd.date_range("2026-01-01", periods=80, freq="5min")
        _mono = pd.Series(np.linspace(100.0, 120.0, 80), index=_idx)
        _r = Indicators.rsi(_mono, 14)
        _rv = float(_r.iloc[-2]) if _r is not None else float("nan")
        results["rsi_monotonic_finite"] = math.isfinite(_rv)
        results["rsi_monotonic_is_100"] = abs(_rv - 100.0) < 1e-9

        def _mk(n=260):
            x = np.arange(n, dtype=float)
            close = 100.0 + 0.06*x + 0.8*np.sin(x/5.0)
            open_ = close - 0.05*np.cos(x/3.0)
            high = np.maximum(open_, close) + 0.20
            low = np.minimum(open_, close) - 0.20
            vol = 1000.0 + 100.0*np.sin(x/7.0) + 80.0*np.cos(x/11.0)
            return pd.DataFrame({"open":open_,"high":high,"low":low,"close":close,"volume":vol}, index=_idx[:n] if n <= len(_idx) else pd.date_range("2026-01-01", periods=n, freq="5min"))

        _d5 = _mk(260); _d15 = _mk(260); _d1 = _mk(260); _d4 = _mk(260)
        _bridge_ok, _bridge_strength, _bridge_ctx = _v518_neutral_local_htf_bridge(
            _d1, _d4, _d15, _d5, "NEUTRAL", "LOCAL_BULLISH", 35.0, "SWING_PULLBACK"
        )
        results["bridge_is_bounded_and_fail_closed"] = isinstance(_bridge_ctx, dict) and _bridge_strength >= 35.0
        # Crash/severity is an absolute blocker.
        _old_allows = V425BearishSeverity.allows_new_long
        try:
            V425BearishSeverity.allows_new_long = staticmethod(lambda _sev: False)
            _b2, _s2, _c2 = _v518_neutral_local_htf_bridge(_d1, _d4, _d15, _d5, "NEUTRAL", "LOCAL_BULLISH", 35.0, "PULLBACK")
            results["bridge_never_bypasses_severity_block"] = (not _b2)
        finally:
            V425BearishSeverity.allows_new_long = _old_allows
        # Policy mismatch is macro-only for the direct bridge; local mismatch remains hard.
        _okm, _rm, _cm = FamilyPolicyLayer.regime_policy_detail(
            "SWING_PULLBACK", "BEARISH", strategy_mode="SWING_PULLBACK",
            local_regime="LOCAL_BULLISH", market_phase="TREND", severity="BEARISH_NORMAL", strategy_style="SWING"
        )
        results["macro_policy_reason_is_explicit"] = (not _okm) and _rm == "macro"
        _okl, _rl, _cl = FamilyPolicyLayer.regime_policy_detail(
            "SWING_PULLBACK", "NEUTRAL", strategy_mode="SWING_PULLBACK",
            local_regime="LOCAL_BEARISH", market_phase="TREND", severity="NORMAL", strategy_style="SWING"
        )
        results["local_policy_mismatch_stays_hard"] = (not _okl) and _rl == "local"
        return {"pass": all(results.values()), "results": results, "skipped": False}
    except Exception as exc:
        results["exception"] = f"{type(exc).__name__}:{exc}"
        return {"pass": False, "results": results, "skipped": False}


