# ---- Unified self-test registry -------------------------------------------
def _v517_register_selftests() -> None:
    _V517_SELFTEST_REGISTRY.clear()
    _V517_SELFTEST_REGISTRY.extend([
        ("V456_COMPREHENSIVE_ALL_INHERITED_AND_LIFECYCLE", _v456_self_test, True),
        ("V519_BRIDGE_AND_INDICATOR_CLOSURE", _v519_bridge_indicator_selftest, True),
        ("V526_EXIT_MANAGEMENT_CLOSURE", _v526_exit_management_self_test, True),
        ("V527_ALL_FIXES_CLOSURE", _v527_all_fixes_closure_selftest, True),
    ])


def _v517_run_selftest_registry() -> Dict[str, Any]:
    import inspect
    if not bool(CONFIG.get("V517_SELFTEST_REGISTRY_ENABLE", True)):
        return {"pass": True, "disabled": True, "results": []}
    if not _V517_SELFTEST_REGISTRY:
        _v517_register_selftests()
    rows = []
    globals()["V644_SELFTEST_ACTIVE"] = True
    try:
        for name, fn, critical in list(_V517_SELFTEST_REGISTRY):
            try:
                result = fn()
                if inspect.isawaitable(result):
                    result = _v517_run_awaitable_sync(result)
                if isinstance(result, dict) and "pass" in result:
                    passed = bool(result.get("pass", False)) and not bool(result.get("skipped", False))
                else:
                    passed = True
                rows.append({"name":name,"pass":passed,"critical":critical,"skipped":bool(isinstance(result,dict) and result.get("skipped",False))})
            except Exception as exc:
                rows.append({"name":name,"pass":False,"critical":critical,"skipped":False,"error":f"{type(exc).__name__}:{exc}"})
    finally:
        globals()["V644_SELFTEST_ACTIVE"] = False
    failed=[r for r in rows if r.get("critical") and not r.get("pass")]
    return {"pass": not failed, "results": rows, "failed": failed}


# ---- Comprehensive tests for unknown outcomes + cycle propagation ---------
async def _v702_a42_run_selftest_in_isolated_db(test_coro_factory):
    """Run executor self-tests against a disposable DB, never the configured live DB."""
    old_db_path = CONFIG.get("DB_PATH")
    previous_test_flag = bool(globals().get("V644_SELFTEST_ACTIVE", False))
    temp_path = None
    result = {"pass": False, "isolation": "DISPOSABLE_SQLITE", "production_db_write_possible": False, "live_gates_relaxed": False, "hard_gate_bypass": False}
    try:
        if not previous_test_flag:
            raise RuntimeError("selftest_db_isolation_requires_selftest_guard")
        current_state = str(getattr(LIVE_STATE, "current", "") or "").upper()
        if current_state in {"FULL_LIVE_RUNNING", "LIVE", "RUNNING"}:
            raise RuntimeError("refuse_selftest_database_swap_while_live_runtime_running")
        fd, temp_path = tempfile.mkstemp(prefix="v702_a42_selftest_", suffix=".db")
        os.close(fd)
        CONFIG["DB_PATH"] = temp_path
        DBManager.init_schema()
        outcome = test_coro_factory()
        if not hasattr(outcome, "__await__"):
            raise TypeError("isolated_selftest_factory_must_return_awaitable")
        outcome = await outcome
        result.update(dict(outcome) if isinstance(outcome, dict) else {"result": str(outcome)[:120]})
        result["pass"] = bool(result.get("pass", False))
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        result.update(pass_=False, error=f"{type(exc).__name__}:{str(exc)[:180]}")
        result["pass"] = False
    finally:
        CONFIG["DB_PATH"] = old_db_path
        removed = True
        if temp_path:
            for suffix in ("", "-wal", "-shm"):
                try:
                    Path(temp_path + suffix).unlink(missing_ok=True)
                except Exception:
                    removed = False
        result["production_db_path_restored"] = CONFIG.get("DB_PATH") == old_db_path
        result["disposable_db_removed"] = bool(not temp_path or (removed and not os.path.exists(temp_path)))
        result["temp_db_distinct_from_configured_db"] = bool(temp_path and os.path.abspath(temp_path) != os.path.abspath(str(old_db_path or "")))
        result["production_db_write_possible"] = bool(
            not result["production_db_path_restored"]
            or (bool(temp_path) and not result["temp_db_distinct_from_configured_db"])
        )
        result["pass"] = bool(result.get("pass", False) and result["production_db_path_restored"]
                               and result["disposable_db_removed"] and result["temp_db_distinct_from_configured_db"]
                               and not result["production_db_write_possible"])
        STATS["v702_a42_selftest_db_isolation"] = {
            "pass": result["pass"], "isolation": result.get("isolation"),
            "production_db_path_restored": result["production_db_path_restored"],
            "disposable_db_removed": result["disposable_db_removed"],
            "temp_db_distinct_from_configured_db": result["temp_db_distinct_from_configured_db"],
            "production_db_write_possible": result["production_db_write_possible"],
            "live_gates_relaxed": False, "hard_gate_bypass": False,
            "error": result.get("error"), "ts": float(WALL_NOW()),
        }
    return result



async def _v517_selftest_unknown_outcomes() -> Dict[str, Any]:
    results = {}
    try:
        # Use the real executor methods with mocks that report timeout AFTER
        # recording the venue-side order; reconciliation must recover it.
        class _UnknownMock(_V516MockExchange):
            def fetch_orders(self, symbol, since=None):
                return list(self.orders.values())
            async def create_market_buy_order(self, symbol, qty, params=None):
                if self.fault == "entry_unknown":
                    self._seq += 1; oid=f"MOCK-UE-{self._seq}"
                    _cid = str((params or {}).get("clientOrderId") or "")
                    self.orders[oid]={"id":oid,"symbol":symbol,"side":"buy","status":"closed","amount":float(qty),"filled":float(qty),"average":100.0,"price":100.0,"timestamp":int(WALL_NOW()*1000),"clientOrderId":_cid}
                    raise TimeoutError("timed out after venue acceptance")
                return await super().create_market_buy_order(symbol, qty, params)
            async def create_stop_market_order(self, symbol, side, qty, price, params=None):
                if self.fault == "sl_unknown":
                    self._seq += 1; oid=f"MOCK-US-{self._seq}"
                    _cid = str((params or {}).get("clientOrderId") or "")
                    self.orders[oid]={"id":oid,"symbol":symbol,"side":side,"status":"open","amount":float(qty),"filled":0.0,"stopPrice":float(price),"triggerPrice":float(price),"timestamp":int(WALL_NOW()*1000),"clientOrderId":_cid,"info":{"stopPrice":float(price),"side":side,"clientOrderId":_cid}}
                    raise TimeoutError("timed out after stop accepted")
                return await super().create_stop_market_order(symbol, side, qty, price, params)
            async def create_market_sell_order(self, symbol, qty, params=None):
                _cid = str((params or {}).get("clientOrderId") or "")
                if self.fault == "tp_unknown":
                    self._seq += 1; oid=f"MOCK-UT-{self._seq}"
                    self.orders[oid]={"id":oid,"symbol":symbol,"side":"sell","status":"closed","amount":float(qty),"filled":float(qty),"average":102.0,"price":102.0,"timestamp":int(WALL_NOW()*1000),"clientOrderId":_cid}
                    raise TimeoutError("timed out after sell accepted")
                self._seq += 1; oid=f"MOCK-T-{self._seq}"
                self.orders[oid]={"id":oid,"symbol":symbol,"side":"sell","status":"closed","amount":float(qty),"filled":float(qty),"average":102.0,"price":102.0,"timestamp":int(WALL_NOW()*1000),"clientOrderId":_cid}
                return self.orders[oid]

        old_stop = getattr(ProductionCapabilityGate, "stop_mode", None)
        old_cap = getattr(ProductionCapabilityGate, "_stop_mode", None)
        old_kill = KillSwitch.is_active
        old_entries = dict(LIVE_ENTRIES_BLOCKED)
        ProductionCapabilityGate._stop_mode = "dedicated_stop_market"
        ProductionCapabilityGate.stop_mode = staticmethod(lambda: "dedicated_stop_market")
        KillSwitch.is_active = staticmethod(lambda: False)
        old_cfg = {k: CONFIG.get(k) for k in ("SL_RETRIES_MAX","SL_POST_CREATE_VERIFY_SETTLE_SEC","MAKER_FIRST_ENTRY_ENABLE")}
        CONFIG["SL_RETRIES_MAX"] = 1; CONFIG["SL_POST_CREATE_VERIFY_SETTLE_SEC"] = 0.0; CONFIG["MAKER_FIRST_ENTRY_ENABLE"] = False
        # Entry unknown -> recovered
        ex1=_UnknownMock("entry_unknown")
        eok,eid,efill=await _v517_submit_entry(ex1,"TEST/USDT",0.1,100.0,False,"V517-UE")
        results["entry_unknown_recovered"] = bool(eok and eid)
        # SL unknown -> recovered
        ex2=_UnknownMock("sl_unknown")
        tok,_,tfill=await _v517_submit_entry(ex2,"TEST/USDT",0.1,100.0,False,"V517-US")
        t=TradeState(symbol="TEST/USDT",trace_id="V517-US",entry=tfill,planned_entry=100.0,effective_entry=tfill,original_sl=98.0,current_sl=98.0,position_size_asset=0.1,remaining_position=0.1)
        sok,sid=await _v517_place_sl(ex2,t,98.0)
        results["sl_unknown_recovered"] = bool(tok and sok and sid and t.sl_health_state=="CONFIRMED")
        # TP unknown -> reconciled by helper
        ex3=_UnknownMock("tp_unknown")
        t2=TradeState(symbol="TEST/USDT",trace_id="V517-UT",entry=100.0,planned_entry=100.0,effective_entry=100.0,original_sl=98.0,current_sl=98.0,tp1=102.0,tp2=103.0,tp3=105.0,position_size_asset=0.1,remaining_position=0.1,status="entry_filled")
        sell = await _v517_market_sell_reconciled(ex3,t2,"TEST/USDT",0.05,102.0,"tp1_sell")
        results["tp_unknown_recovered"] = bool(isinstance(sell,dict) and sell.get("id"))
        # Unknown with no venue evidence -> must block, never silently pass.
        ex4=_V516MockExchange("entry")
        # Force a network-shaped failure without an accepted order.
        async def _fail_unknown(symbol, qty):
            raise TimeoutError("network timeout no acceptance")
        ex4.create_market_buy_order = _fail_unknown
        eok2,_,_=await _v517_submit_entry(ex4,"TEST/USDT",0.1,100.0,False,"V517-UE2")
        results["entry_unknown_unresolved_blocks"] = (not eok2) and bool(LIVE_ENTRIES_BLOCKED.get("active"))
        for k,v in old_cfg.items(): CONFIG[k]=v
        # Cycle stamping must survive GEN -> candidate -> selection.
        global _V517_ACTIVE_CYCLE_ID
        _V517_ACTIVE_CYCLE_ID = 777
        fake = StrategyCandidate(engine_id="selftest", symbol="TEST/USDT", side="long", generated_at_ms=int(WALL_NOW()*1000),
                                 entry_ref=100.0, sl_price=98.0, tp1_rr=1.0, tp2_rr=2.0, tp3_rr=5.0, engine_score=0.8, rr_ratio=2.0,
                                 liquidity_score=1.0, regime_fit=1.0, family="PULLBACK", zone_ref=100.0, features_snapshot={})
        fs = dict(fake.features_snapshot); fs["v517_cycle_id"] = _V517_ACTIVE_CYCLE_ID
        fake = replace(fake, features_snapshot=fs)
        _v516_record_selection_event("SELECTION", "cycle_test", fake, None)
        results["cycle_id_propagation"] = (fake.features_snapshot.get("v517_cycle_id") == 777)
        _V517_ACTIVE_CYCLE_ID = None
        return {"pass": all(results.values()), "results": results, "skipped": False}
    except Exception as exc:
        return {"pass": False, "results": results, "skipped": False, "error": f"{type(exc).__name__}:{exc}"}
    finally:
        try:
            if 'old_stop' in locals() and old_stop is not None: ProductionCapabilityGate.stop_mode = old_stop
            if 'old_cap' in locals() and old_cap is not None: ProductionCapabilityGate._stop_mode = old_cap
            if 'old_kill' in locals(): KillSwitch.is_active = old_kill
            if 'old_entries' in locals():
                LIVE_ENTRIES_BLOCKED.clear(); LIVE_ENTRIES_BLOCKED.update(old_entries)
        except Exception:
            _v647_record_suppressed_exception()


