# Final boot validation: one registry run, no duplicate comprehensive suite.
_orig_validate_config_base_v517 = _orig_validate_config_v45

def _validate_config_v517() -> bool:
    try:
        if not _v525_validate_opportunity_telegram_config():
            return False
        ok_base = _orig_validate_config_base_v517()
        if not ok_base:
            return False
        try:
            _v455_boot_validate()
        except Exception as exc:
            logger.critical(f"[V517] boot validation failed: {exc}")
            return False
        _v523_tg = _v523_opportunity_telegram_self_test()
        STATS["v523_opportunity_telegram_selftest"] = _v523_tg
        if not bool(_v523_tg.get("pass", False)):
            logger.critical(f"[V523] opportunity-Telegram self-test FAILED: {_v523_tg}")
            return False
        _v525 = _v525_protected_entry_telegram_self_test()
        STATS["v525_protected_entry_selftest"] = _v525
        if not bool(_v525.get("pass", False)):
            logger.critical(f"[V525] protected-entry/TradingView self-test FAILED: {_v525}")
            return False
        _v526 = _v526_exit_management_self_test()
        STATS["v526_exit_management_selftest"] = _v526
        if not bool(_v526.get("pass", False)):
            logger.critical(f"[V526] exit-management self-test FAILED: {_v526}")
            return False
        if bool(CONFIG.get("V521_FAIL_CLOSED_SAFETY_ENABLE", True)):
            _v521 = _v520_safety_closure_self_test()
            STATS["v520_safety_closure_selftest"] = _v521
            if not bool(_v521.get("pass", False)):
                logger.critical(f"[V520] safety-closure self-test FAILED: {_v521}")
                return False
        try:
            rep = _v456_sync_strategy_policy_registries()
            STATS["v517_policy_pre_normalization_drift"] = int(rep.get("pre_normalization_drift",0) or 0)
            STATS["v517_policy_post_normalization_drift"] = int(rep.get("post_normalization_conflicts",0) or 0)
            if int(rep.get("post_normalization_conflicts", 0) or 0) != 0:
                logger.critical("[V517] policy registry remained inconsistent after canonical normalization")
                return False
        except Exception as exc:
            logger.critical(f"[V517] policy registry validation failed: {exc}")
            return False
        if bool(CONFIG.get("V517_SELFTEST_REGISTRY_ENABLE", True)):
            _v517_register_selftests()
            registry = _v517_run_selftest_registry()
            # Add unknown-outcome suite to registry only once per boot, after
            # basic registry functions are known to exist. Expected mock recovery
            # diagnostics are downgraded while this suite is running; real live
            # unknown outcomes remain CRITICAL outside the self-test flag.
            _prev_v644_selftest = bool(globals().get("V644_SELFTEST_ACTIVE", False))
            globals()["V644_SELFTEST_ACTIVE"] = True
            try:
                # A42: executor self-tests must use a disposable SQLite database;
                # mock venue order IDs must never enter the configured live DB.
                _fi = _v517_run_awaitable_sync(
                    _v702_a42_run_selftest_in_isolated_db(_v517_selftest_unknown_outcomes)
                )
            finally:
                globals()["V644_SELFTEST_ACTIVE"] = _prev_v644_selftest
            registry["results"].append({"name":"V517_UNKNOWN_OUTCOME_RECONCILIATION",
                                         "pass":bool(_fi.get("pass",False)),"critical":True,
                                         "skipped":bool(_fi.get("skipped",False))})
            if not bool(_fi.get("pass",False)) or bool(_fi.get("skipped",False)):
                registry["pass"] = False
                registry["failed"] = list(registry.get("failed",[])) + [{"name":"V517_UNKNOWN_OUTCOME_RECONCILIATION","pass":False,"critical":True}]
            STATS["v517_selftest_registry"] = registry
            if bool(CONFIG.get("V517_SELFTEST_STRICT", True)) and not bool(registry.get("pass",False)):
                logger.critical(f"[V517] self-test registry FAILED: {registry.get('failed')}")
                return False
            logger.info(f"[V517] unified self-test registry PASS: {len(registry.get('results',[]))} test groups")
        return True
    except Exception as exc:
        logger.critical(f"[V517] validation exception — refusing to boot: {exc}")
        return False


# =============================================================================
# v4.5.28 — HTF RECOVERY + QUALITY-AWARE SPREAD + KNOWLEDGE TELEGRAM CLOSURE
# =============================================================================
# Objectives (all bounded / fail-closed / non-bypass):
#   1) Preserve the canonical live score floor; A44 enforces a minimum of 70.
#   2) Add a tightly bounded HTF recovery path only when HTF starvation is the
#      measured bottleneck AND the candidate has strong closed-bar confluence.
#   3) Distinguish HTF policy vs HTF strength vs HTF alignment in telemetry.
#   4) Add a quality-aware, tiny spread allowance only for exceptional quality
#      MID/LARGE candidates during the current build_and_route context. The
#      normal spread ceiling remains the default and is never relaxed for weak
#      candidates or MICRO/BELOW tiers.
#   5) Keep a rolling Top-5 rejected-candidate forensic ledger for audits.
#   6) Send every strategy candidate with score strictly > 40 to Telegram as a
#      KNOWLEDGE-ONLY signal. These alerts never authorize execution and are
#      explicitly labeled as non-executable information.
# =============================================================================

