def _v528_htf_starvation_active() -> bool:
    try:
        if str(STATS.get("v425_starvation_mode", "")).upper() == "HTF":
            return True
        # Use rolling canonical attribution, not cumulative heartbeat totals.
        rw = V453CanonicalScoreFloor._window_rejects(float(CONFIG.get("V528_HTF_RECOVERY_WINDOW_SEC",720.0)))
        return int(rw.get("htf",0) or 0) >= int(CONFIG.get("V528_HTF_RECOVERY_MIN_REJECTS",8))
    except Exception:
        return False


def _v528_rs_feature(candidate) -> float:
    try:
        fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        for k in ("rs_5m", "rs_score_val", "rs_score", "relative_strength"):
            if k in fs and fs[k] is not None:
                x=float(fs[k])
                # Some score features are 0..100 rather than -1..1.
                return x/100.0 if abs(x)>1.5 else x
    except Exception:
        _v647_record_suppressed_exception()
    return 0.0


def _v528_htf_recovery_allowed(candidate, snap: Dict[str, Any], original_reason: str) -> Tuple[bool, Dict[str, Any]]:
    """Bounded HTF recovery. It may only replace a deterministic HTF rejection
    and immediately re-runs the downstream microstructure/fake-break checks.
    """
    ctx={"enabled":False,"reason":"not_eligible","original_reason":str(original_reason)}
    try:
        if not bool(CONFIG.get("V528_HTF_RECOVERY_ENABLE",True)):
            return False,ctx
        if not _v528_htf_starvation_active():
            return False,{**ctx,"reason":"htf_starvation_not_active"}
        if KillSwitch.is_active():
            return False,{**ctx,"reason":"kill_switch"}
        if bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
            return False,{**ctx,"reason":"entries_blocked"}
        if ExchangeWatchdog.is_tripped():
            return False,{**ctx,"reason":"watchdog"}
        sym=str(getattr(candidate,"symbol",snap.get("symbol","?")))
        family=str(getattr(candidate,"family","") or getattr(candidate,"strategy_mode","") or "").upper()
        allow={str(x).upper() for x in CONFIG.get("V528_HTF_RECOVERY_ALLOW_FAMILIES",())}
        if family not in allow:
            return False,{**ctx,"reason":"family_not_allowlisted","family":family}
        # Recovery only for deterministic HTF/policy mismatch, never data errors.
        rr=str(original_reason or "").lower()
        if not (rr.startswith("htf.") or rr.startswith("family_regime_disallowed") or rr.startswith("policy.")):
            return False,{**ctx,"reason":"not_htf_failure"}
        htf_state=str(snap.get("htf_state","") or "").upper()
        htf_reason=str(snap.get("htf_reason","") or "").lower()
        if htf_state in {"UNKNOWN","ERROR"} or htf_reason.startswith("error") or htf_reason in {"insufficient_data","snapshot_unavailable","htf_grade_exception"}:
            return False,{**ctx,"reason":"htf_truth_unavailable"}
        regime=str(snap.get("regime","") or "").upper()
        local=str(snap.get("local_regime","") or "").upper()
        if regime not in {"BULLISH","NEUTRAL"} or local not in {"LOCAL_BULLISH","NON_BEARISH","BULLISH"}:
            return False,{**ctx,"reason":"regime_local_mismatch","regime":regime,"local":local}
        score=float(getattr(candidate,"engine_score",0.0) or 0.0)*100.0
        if score < float(CONFIG.get("V528_HTF_RECOVERY_MIN_SCORE",65.0)):
            return False,{**ctx,"reason":"score_too_low","score":score}
        tier=str(snap.get("tier","") or "").upper()
        if tier in {"BELOW","MICRO"}:
            return False,{**ctx,"reason":"tier_too_low","tier":tier}
        htf=float(snap.get("htf_strength",0.0) or 0.0)
        if htf < float(CONFIG.get("V528_HTF_RECOVERY_MIN_HTF_STRENGTH",38.0)):
            return False,{**ctx,"reason":"htf_strength_too_low","htf":htf}
        d4=snap.get("df_4h"); d1=snap.get("df_1h"); d15=snap.get("df_15m"); d5=snap.get("df_5m")
        if any(x is None for x in (d4,d1,d15,d5)) or not _PDNP_OK:
            return False,{**ctx,"reason":"data_missing"}
        if min(len(d4),len(d1),len(d15),len(d5)) < 60:
            return False,{**ctx,"reason":"insufficient_data"}
        def feat(df):
            e20=Indicators.ema(df["close"],20); e50=Indicators.ema(df["close"],50); e200=Indicators.ema(df["close"],200)
            atrs=Indicators.atr(df,int(CONFIG.get("ATR_PERIOD",14)))
            rs=Indicators.rsi(df["close"],int(CONFIG.get("RSI_PERIOD",14)))
            c=float(df["close"].iloc[-2]); o=float(df["open"].iloc[-2]); e20c=float(e20.iloc[-2]); e50c=float(e50.iloc[-2]); e200c=float(e200.iloc[-2]); atr=float(atrs.iloc[-2])
            avg=float(df["volume"].iloc[-22:-2].mean()) if len(df)>=24 else 0.0; vr=float(df["volume"].iloc[-2])/max(avg,1e-12)
            r=float(rs.iloc[-2]) if rs is not None else float("nan")
            return c,o,e20c,e50c,e200c,atr,vr,r
        c4,o4,e204,e504,e2004,a4,v4,r4=feat(d4)
        c1,o1,e201,e501,e2001,a1,v1,r1=feat(d1)
        c15,o15,e2015,e5015,e20015,a15,v15,r15=feat(d15)
        c5,o5,e205,e505,e2005,a5,v5,r5=feat(d5)
        vals=[c4,o4,e204,e504,e2004,a4,v4,r4,c1,e201,e501,e2001,c15,e2015,e5015,c5,e205,e505,a5,v5,r5]
        if not all(math.isfinite(float(x)) for x in vals):
            return False,{**ctx,"reason":"non_finite"}
        d4_strength=(c4-e504)/max(abs(c4-e2004),1e-9)
        if not (c4>e204>e504 and e504>float(Indicators.ema(d4["close"],50).iloc[-6])):
            return False,{**ctx,"reason":"4h_stack_missing"}
        if d4_strength < float(CONFIG.get("V528_HTF_RECOVERY_MIN_4H_STRENGTH",0.45)):
            return False,{**ctx,"reason":"4h_strength_low"}
        if c1 < e2001*(1.0-float(CONFIG.get("EMA200_TOL_RELAXED",0.02))):
            return False,{**ctx,"reason":"1h_below_ema200"}
        if not (c15>e2015 and c15>=e5015):
            return False,{**ctx,"reason":"15m_stack_missing"}
        lc=d5.iloc[-2]; pc=d5.iloc[-3]; p2=d5.iloc[-4]
        bull=float(lc["close"])>float(lc["open"]) and float(lc["close"])>=float(pc["close"])
        hl=float(lc["low"])>float(pc["low"])>float(p2["low"])
        reclaim=c5>e205
        if not (bull or hl or reclaim):
            return False,{**ctx,"reason":"5m_confirmation_missing"}
        if v5 < float(CONFIG.get("V528_HTF_RECOVERY_MIN_5M_VOLUME_RATIO",0.90)):
            return False,{**ctx,"reason":"5m_volume_low","vol5":v5}
        if r5 > float(CONFIG.get("V528_HTF_RECOVERY_MAX_5M_RSI",70.0)):
            return False,{**ctx,"reason":"5m_overextended","rsi5":r5}
        chase=max(0.0,(c5-max(c15,e2015))/max(a5,1e-9))
        if chase > float(CONFIG.get("V528_HTF_RECOVERY_MAX_CHASE_ATR",1.25)):
            return False,{**ctx,"reason":"chase_excessive","chase":chase}
        rs=_v528_rs_feature(candidate)
        if rs < float(CONFIG.get("V528_HTF_RECOVERY_MIN_RS",0.03)):
            return False,{**ctx,"reason":"rs_low","rs":rs}
        # Re-run the same deterministic downstream hard checks that follow the
        # HTF gate in canonical prequalification. This recovery never creates a
        # direct execution path and never bypasses fake-break or microstructure.
        zone=getattr(candidate,"zone_ref",None)
        bos,_=MicroStructure.micro_bos_confirm(d5)
        ms_ok,ms_ctx=_v520_microstructure_parity(
            d5, family, str(getattr(candidate,"strategy_mode","") or family), zone,
            bos_confirmed=bos, candidate_features=dict(getattr(candidate,"features_snapshot",{}) or {})
        )
        if not ms_ok:
            _ms_reason = str(ms_ctx.get("reason","microstruct_reject"))
            if _ms_reason in {"pullback_micro_uptrend", "fake_break_detected", "PULLBACK_REJECT"}:
                _v565_note_structural_reject(sym)
            return False,{**ctx,"reason":_ms_reason}
        if bool(CONFIG.get("V520_PREQUAL_FAKE_BREAK_ENABLE",True)):
            try: atr_pre=float(Indicators.atr(d5,CONFIG["ATR_PERIOD"]).iloc[-2])
            except Exception: atr_pre=0.0
            fb_ok,fb_ctx=_v520_fake_break_gate(
                d5, family=family, zone_ref=zone, atr_value=atr_pre
            )
            if not fb_ok:
                return False,{**ctx,"reason":str(fb_ctx.get("reason","fake_break"))}
        eff=max(htf, float(CONFIG.get("V528_HTF_RECOVERY_MIN_HTF_STRENGTH",38.0)))
        return True,{"enabled":True,"reason":"v528_bounded_htf_recovery","family":family,"symbol":sym,
                      "score":score,"base_htf":htf,"effective_htf":eff,"four_h_strength":d4_strength,
                      "vol5":v5,"rsi5":r5,"chase":chase,"rs":rs,"tier":tier}
    except Exception as exc:
        return False,{**ctx,"reason":f"exception:{type(exc).__name__}"}


def _v528_record_reject(candidate, reason: str, stage: str = "prequal") -> None:
    try:
        now=MONO_NOW()
        item={
            "ts":now,
            "symbol":str(getattr(candidate,"symbol","?")),
            "score":round(float(getattr(candidate,"engine_score",0.0) or 0.0)*100.0,1),
            "family":str(getattr(candidate,"family","") or getattr(candidate,"strategy_mode","") or "").upper(),
            "mode":str(getattr(candidate,"strategy_mode","") or "").upper(),
            "tier":str((getattr(candidate,"features_snapshot",{}) or {}).get("liquidity_tier", "") or "").upper(),
            "reason":str(reason),
            "stage":stage,
            "htf":float((getattr(candidate,"features_snapshot",{}) or {}).get("htf_strength",0.0) or 0.0),
            "vol":float((getattr(candidate,"features_snapshot",{}) or {}).get("volume_ratio",0.0) or 0.0),
            "rs":round(_v528_rs_feature(candidate),4),
            "chase":float((getattr(candidate,"features_snapshot",{}) or {}).get("chase_atr",0.0) or 0.0),
        }
        _V528_REJECT_LEDGER.append(item)
        key=reason.split(".")[-1] if reason else "other"
        if str(reason).startswith("family_regime_disallowed") or "family_policy" in str(reason):
            STATS["v528_htf_policy_rejects"] = int(STATS.get("v528_htf_policy_rejects",0) or 0)+1
        elif "htf_strength" in str(reason) or "htf.core" in str(reason):
            STATS["v528_htf_strength_rejects"] = int(STATS.get("v528_htf_strength_rejects",0) or 0)+1
        elif str(reason).startswith("htf."):
            STATS["v528_htf_alignment_rejects"] = int(STATS.get("v528_htf_alignment_rejects",0) or 0)+1
        STATS["v528_rejects_ledgered"] = int(STATS.get("v528_rejects_ledgered",0) or 0)+1
    except Exception:
        _v647_record_suppressed_exception()


def v528_reject_forensics() -> Dict[str, Any]:
    try:
        now=MONO_NOW(); window=float(CONFIG.get("V528_REJECT_LEDGER_WINDOW_SEC",720.0))
        rows=[x for x in list(_V528_REJECT_LEDGER) if now-float(x.get("ts",0))<=window]
        rows.sort(key=lambda x:(-float(x.get("score",0)), str(x.get("symbol",""))))
        top=rows[:int(CONFIG.get("V528_REJECT_LEDGER_TOP_N",5))]
        counts=defaultdict(int)
        for x in rows: counts[str(x.get("reason","other"))]+=1
        return {"window_rows":len(rows),"top":top,"reason_counts":dict(sorted(counts.items(),key=lambda kv:-kv[1])[:10])}
    except Exception:
        return {"window_rows":0,"top":[],"reason_counts":{}}

# Wrap canonical prequalification: recover ONLY a proven HTF starvation case,
# while preserving the deterministic downstream parity gates.
_orig_v453_prequalify_v528 = _v453_prequalify

def _v528_prequalify_wrapper(ranked_candidate, snap_by_symbol):
    ok, reason = _orig_v453_prequalify_v528(ranked_candidate, snap_by_symbol)
    if ok:
        return ok, reason
    try:
        _v528_record_reject(ranked_candidate, reason, "prequal")
        snap=snap_by_symbol.get(str(getattr(ranked_candidate.candidate,"symbol","")), {}) or {}
        recover, ctx=_v528_htf_recovery_allowed(ranked_candidate.candidate, snap, reason)
        if recover:
            STATS["v528_htf_recovery_passes"] = int(STATS.get("v528_htf_recovery_passes",0) or 0)+1
            LifecycleTrace.record("V528", "HTF_RECOVERY_PASS", ctx)
            logger.warning(f"[V528-HTF-RECOVERY] {ranked_candidate.candidate.symbol} family={ctx.get('family')} score={ctx.get('score'):.1f} htf={ctx.get('base_htf'):.1f}->{ctx.get('effective_htf'):.1f}")
            return True, "v528.htf_recovery_pass"
        STATS["v528_htf_recovery_rejects"] = int(STATS.get("v528_htf_recovery_rejects",0) or 0)+1
    except Exception:
        _v647_record_suppressed_exception()
    return False, reason

_v453_prequalify = _v528_prequalify_wrapper

