# v4.5.40 — ELITE-LIVE QUALITY HELPERS
# =============================================================================

def _v702_extract_htf_percent(sources):
    """Return an HTF strength on the canonical 0..100 scale.

    Exact `htf_strength`/`htf` values have precedence (including valid zero).
    Only the alias `htf_alignment` may be normalized from 0..1 to 0..100.
    Source order is supplied by the caller; market snapshots must be first.
    """
    try:
        source_rows = [(str(name), obj) for name, obj in list(sources or ()) if isinstance(obj, dict)]
    except Exception:
        source_rows = []
    for name, obj in source_rows:
        # Source authority outranks field alias preference: a snapshot alias is
        # still more authoritative than any value copied onto a candidate.
        for key in ("htf_strength", "htf"):
            if key in obj and obj.get(key) not in (None, ""):
                try:
                    value = float(obj.get(key))
                    if math.isfinite(value):
                        return value, f"{name}.{key}"
                except Exception:
                    return 0.0, f"{name}.{key}_invalid"
                return 0.0, f"{name}.{key}_invalid"
        if "htf_alignment" in obj and obj.get("htf_alignment") not in (None, ""):
            try:
                value = float(obj.get("htf_alignment"))
                if not math.isfinite(value):
                    return 0.0, f"{name}.htf_alignment_invalid"
                if abs(value) <= 1.0:
                    value *= 100.0
                return value, f"{name}.htf_alignment"
            except Exception:
                return 0.0, f"{name}.htf_alignment_invalid"
    return None, "missing"


def _v540_candidate_ctx(candidate: Any = None, fallback_ctx: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Build a conservative, fail-closed quality context for elite-lane decisions."""
    fs: Dict[str, Any] = {}
    try:
        if candidate is not None:
            fs = dict(getattr(candidate, "features_snapshot", {}) or {})
    except Exception:
        fs = {}
    base = dict(fallback_ctx or {})

    def _pick(*keys, default=None):
        for k in keys:
            if k in fs and fs.get(k) not in (None, ""):
                return fs.get(k)
            if k in base and base.get(k) not in (None, ""):
                return base.get(k)
        return default

    try:
        raw_score = getattr(candidate, "engine_score", None) if candidate is not None else None
        score = float(raw_score) * 100.0 if raw_score is not None else float(_pick("score", default=0.0) or 0.0)
    except Exception:
        score = 0.0
    _htf_value, _htf_source = _v702_extract_htf_percent((("snapshot", base), ("candidate", fs)))
    htf = float(_htf_value) if _htf_value is not None and math.isfinite(float(_htf_value)) else 0.0
    try:
        vol = float(_pick("volume_ratio", "vol", default=0.0) or 0.0)
    except Exception:
        vol = 0.0
    try:
        rs = float(_pick("rs_5m", "rs_score_val", "rs_score", "relative_strength", "rs", default=0.0) or 0.0)
        if abs(rs) > 1.5:
            rs /= 100.0
    except Exception:
        rs = 0.0
    try:
        chase = float(_pick("chase_atr", "chase", default=99.0) or 99.0)
    except Exception:
        chase = 99.0
    tier = str(_pick("liquidity_tier", "tier", default="") or "").upper()
    family = str(_pick("strategy_mode", "family", default="") or "").upper()
    # v4.5.41: derive a reviewed quality score from the same bounded reviewer
    # used by the Discovery channel. This is ranking/relief qualification only;
    # it never replaces canonical live score or PreSend hard gates.
    reviewed = score
    try:
        reviewer = globals().get("_v531_review_discovery_score")
        if callable(reviewer):
            reviewed, _, _ = reviewer(score, {
                "htf": htf, "vol": vol, "rs": rs, "chase": chase, "tier": tier
            }, family or "UNKNOWN")
            reviewed = float(reviewed)
    except Exception:
        reviewed = score
    return {
        "score": score, "reviewed_score": reviewed, "htf": htf, "vol": vol, "rs": rs,
        "chase": chase, "tier": tier, "family": family,
    }


def _v540_is_elite(ctx: Optional[Dict[str, Any]]) -> bool:
    """Elite-lane qualification. Any missing/invalid input fails closed."""
    if not bool(CONFIG.get("V540_ELITE_LIVE_ENABLE", True)):
        return False
    try:
        c = dict(ctx or {})
        score = float(c.get("score", 0.0))
        reviewed = float(c.get("reviewed_score", score))
        htf = float(c.get("htf", 0.0))
        vol = float(c.get("vol", 0.0))
        rs = float(c.get("rs", 0.0))
        chase = float(c.get("chase", 99.0))
        tier = str(c.get("tier", "") or "").upper()
        if not all(math.isfinite(x) for x in (score, reviewed, htf, vol, rs, chase)):
            return False
        return bool(
            score >= float(CONFIG.get("V540_ELITE_MIN_ENGINE_SCORE", 90.0))
            and reviewed >= float(CONFIG.get("V540_ELITE_MIN_REVIEWED_SCORE", 90.0))
            and htf >= float(CONFIG.get("V540_ELITE_MIN_HTF", 90.0))
            and vol >= float(CONFIG.get("V540_ELITE_MIN_VOLUME_RATIO", 0.80))
            and rs >= float(CONFIG.get("V540_ELITE_MIN_RS", 0.0))
            and chase <= float(CONFIG.get("V540_ELITE_MAX_CHASE_ATR", 0.90))
            and tier in {str(x).upper() for x in CONFIG.get("V540_ELITE_ALLOWED_TIERS", ())}
        )
    except Exception:
        return False


def _v540_elite_spread_allow(spread_pct: Optional[float], tier: str,
                             ctx: Optional[Dict[str, Any]]) -> Tuple[bool, str]:
    """Tiny, elite-only spread cushion beyond the normal tier ceiling."""
    if not bool(CONFIG.get("V540_ELITE_SPREAD_RELIEF_ENABLE", True)):
        return False, "elite_spread_relief_disabled"
    if spread_pct is None:
        return False, "elite_spread_missing"
    try:
        sp = float(spread_pct)
        if not math.isfinite(sp):
            return False, "elite_spread_nonfinite"
        if not _v540_is_elite(ctx):
            return False, "elite_not_qualified"
        t = str(tier or "").upper()
        extra = float((CONFIG.get("V540_ELITE_SPREAD_EXTRA_PCT", {}) or {}).get(t, 0.0))
        absolute = float((CONFIG.get("V540_ELITE_SPREAD_ABSOLUTE_MAX_PCT", {}) or {}).get(t, 0.0))
        base = float((CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}).get(
            t, CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15)))
        if extra <= 0.0 or absolute <= 0.0:
            return False, "elite_spread_no_relief_for_tier"
        ceiling = min(base + extra, absolute)
        if sp <= ceiling:
            return True, (
                f"elite_spread_relief:{sp:.4f}%<=ceil={ceiling:.4f}% "
                f"(base={base:.4f}+extra={extra:.4f})"
            )
        return False, f"elite_spread_over_cap:{sp:.4f}%>ceil={ceiling:.4f}%"
    except Exception as exc:
        return False, f"elite_spread_exception:{type(exc).__name__}"


def _v540_live_ready_alert(symbol: str, score: float, family: str,
                           entry: float, sl: float, tp1: float, tp2: float,
                           tp3: float, ctx: Optional[Dict[str, Any]] = None) -> None:
    """Optional diagnostic only: never authorizes an order."""
    if not bool(CONFIG.get("V540_ELITE_LIVE_READY_ALERT_ENABLE", True)):
        return
    try:
        if float(score) < float(CONFIG.get("V540_ELITE_LIVE_READY_ALERT_MIN_SCORE", 90.0)):
            return
        now = MONO_NOW()
        last_map = STATS.get("v540_live_ready_alerts", {})
        if not isinstance(last_map, dict):
            last_map = {}
            STATS["v540_live_ready_alerts"] = last_map
        last = float(last_map.get(symbol, 0.0) or 0.0)
        if now - last < float(CONFIG.get("V540_ELITE_LIVE_READY_ALERT_DEDUP_SEC", 600.0)):
            return
        c = dict(ctx or {})
        lines = [
            "🚦 <b>LIVE-READY — ELITE CANDIDATE</b>",
            f"<b>{OpportunityTelegramNotifier._escape(str(symbol))}</b>",
            f"Strategy: <b>{OpportunityTelegramNotifier._escape(str(family or 'UNKNOWN'))}</b>",
            f"Canonical Score: <b>{float(score):.1f}</b> | Reviewed: {float(c.get('reviewed_score', score)):.1f} | HTF: {float(c.get('htf',0.0)):.1f} | "
            f"Vol: x{float(c.get('vol',0.0)):.2f} | RS: {float(c.get('rs',0.0))*100:.2f}% | "
            f"Chase: {float(c.get('chase',0.0)):.2f} ATR | Tier: {OpportunityTelegramNotifier._escape(str(c.get('tier','')))}",
            f"Entry: <b>{OpportunityTelegramNotifier._fmt_px(entry)}</b> | SL: {OpportunityTelegramNotifier._fmt_px(sl)}",
            f"TP1: {OpportunityTelegramNotifier._fmt_px(tp1)} | TP2: {OpportunityTelegramNotifier._fmt_px(tp2)} | TP3: {OpportunityTelegramNotifier._fmt_px(tp3)}",
            "<i>All canonical PreSend gates passed. Exchange acceptance is still pending.</i>",
        ]
        tv = OpportunityTelegramNotifier._tradingview_link(symbol)
        mx = OpportunityTelegramNotifier._mexc_link(symbol)
        links = []
        if tv:
            links.append(f'<a href="{OpportunityTelegramNotifier._escape(tv)}">📱 TradingView</a>')
        if mx:
            links.append(f'<a href="{OpportunityTelegramNotifier._escape(mx)}">🟢 MEXC</a>')
        if links:
            lines += ["", " | ".join(links)]
        try:
            loop = asyncio.get_running_loop()
            loop.create_task(TelegramDispatcher.enqueue("\n".join(lines)))
            last_map[symbol] = now
            STATS["v540_live_ready_alerts_sent"] = int(STATS.get("v540_live_ready_alerts_sent", 0) or 0) + 1
        except RuntimeError:
            pass
    except Exception:
        _v647_record_suppressed_exception()


# Quality-aware spread allowance is task-local and only applies to a current
# SignalBuilder candidate with exceptional quality. Default spread ceilings
# remain unchanged for every other call.
_orig_tier_spread_hard_ok_v528 = tier_spread_hard_ok_v410

def tier_spread_hard_ok_v410(spread_pct: Optional[float], tier: str) -> Tuple[bool,str]:
    ok, detail = _orig_tier_spread_hard_ok_v528(spread_pct, tier)
    if ok or not bool(CONFIG.get("V528_SPREAD_QUALITY_RELAX_ENABLE",True)):
        return ok,detail
    try:
        ctx=_V528_SPREAD_CONTEXT.get()
        if not ctx or spread_pct is None or not math.isfinite(float(spread_pct)):
            return ok,detail
        t=str(tier or "").upper()
        if t not in {"MID","LARGE"}:
            return ok,detail
        score=float(ctx.get("score",0.0) or 0.0)
        htf=float(ctx.get("htf",0.0) or 0.0)
        vol=float(ctx.get("vol",0.0) or 0.0)
        rs=float(ctx.get("rs",0.0) or 0.0)
        chase=float(ctx.get("chase",99.0) or 99.0)
        if score < float(CONFIG.get("V528_SPREAD_MIN_SCORE",75.0)):
            return ok,detail
        if htf < float(CONFIG.get("V528_SPREAD_MIN_HTF",80.0)) or vol < float(CONFIG.get("V528_SPREAD_MIN_VOL",1.30)):
            return ok,detail
        if rs < float(CONFIG.get("V528_SPREAD_MIN_RS",0.05)) or chase > float(CONFIG.get("V528_SPREAD_MAX_CHASE_ATR",1.00)):
            return ok,detail
        base=float(CONFIG.get("TIER_SPREAD_CEIL_PCT",{}).get(t,CONFIG.get("SCORE_SPREAD_CEIL_PCT",0.15)))
        extra=float(CONFIG.get("V528_SPREAD_MID_EXTRA_PCT",0.04) if t=="MID" else CONFIG.get("V528_SPREAD_LARGE_EXTRA_PCT",0.025))
        if float(spread_pct) <= base+extra:
            STATS["v528_quality_spread_reliefs"] = int(STATS.get("v528_quality_spread_reliefs",0) or 0)+1
            return True, f"quality_spread_relief:{float(spread_pct):.4f}%<=quality_ceil={base+extra:.4f}%"
        # v4.5.40 elite lane: if the existing V528 quality lane is still too
        # strict for a truly exceptional candidate, allow ONLY the tiny V540
        # cushion. The global tier ceiling remains the first authority.
        _elite_ctx = {
            "score": score, "htf": htf, "vol": vol, "rs": rs,
            "chase": chase, "tier": t,
        }
        _elite_ok, _elite_reason = _v540_elite_spread_allow(
            float(spread_pct), t, _elite_ctx)
        if _elite_ok:
            STATS["v540_elite_spread_reliefs"] = int(
                STATS.get("v540_elite_spread_reliefs", 0) or 0) + 1
            return True, _elite_reason
    except Exception:
        _v647_record_suppressed_exception()
    return ok,detail

# Wrap SignalBuilder so the quality-aware spread context exists only for the
# current task and is cleared immediately after the canonical pipeline exits.
_orig_build_and_route_v528 = SignalBuilder.build_and_route

@staticmethod
async def _v528_build_and_route(exchange, symbol: str, market_data: Dict, preferred_candidate: Optional[StrategyCandidate] = None):
    token=None
    try:
        cand=preferred_candidate
        fs=dict(getattr(cand,"features_snapshot",{}) or {}) if cand is not None else {}
        score=float(getattr(cand,"engine_score",0.0) or 0.0)*100.0 if cand is not None else float(fs.get("score",0.0) or 0.0)
        htf=float(fs.get("htf_strength",fs.get("htf_alignment",0.0)) or 0.0)
        vol=float(fs.get("volume_ratio",0.0) or 0.0)
        rs=_v528_rs_feature(cand) if cand is not None else float(fs.get("rs_5m",0.0) or 0.0)
        chase=float(fs.get("chase_atr",0.0) or 0.0)
        token=_V528_SPREAD_CONTEXT.set({"symbol":str(symbol),"score":score,"htf":htf,"vol":vol,"rs":rs,"chase":chase,"ts":MONO_NOW()})
    except Exception:
        token=None
    try:
        return await _orig_build_and_route_v528(exchange,symbol,market_data,preferred_candidate)
    finally:
        try:
            if token is not None:
                _V528_SPREAD_CONTEXT.reset(token)
        except Exception:
            _v647_record_suppressed_exception()

SignalBuilder.build_and_route = _v528_build_and_route

# Knowledge-only Telegram discovery notifier. It is deliberately separate from
# notify_canonical: score > 40 is informational only and never a live signal.
def _v528_knowledge_notify_candidates(candidates: List[StrategyCandidate], snapshot: Optional[Dict[str, Any]] = None) -> None:
    if not bool(CONFIG.get("TELEGRAM_DISCOVERY_ALERTS_ENABLE",True)):
        return
    if bool(CONFIG.get("TELEGRAM_DISCOVERY_REQUIRE_FULL_LIVE",True)):
        if str(getattr(LIVE_STATE,"current","")) != "FULL_LIVE_RUNNING":
            return
    threshold=float(CONFIG.get("TELEGRAM_DISCOVERY_MIN_SCORE",40.0))
    per_cycle_limit=min(int(CONFIG.get("V529_DISCOVERY_MAX_PER_CYCLE",20)),
                       int(CONFIG.get("TELEGRAM_DISCOVERY_MAX_PER_CYCLE",50)))
    sent=0
    snapshot = dict(snapshot or {}) if isinstance(snapshot, dict) else {}
    for c in list(candidates or []):
        try:
            score=float(getattr(c,"engine_score",0.0) or 0.0)*100.0
            if not math.isfinite(score) or score <= threshold:
                continue
            if sent>=per_cycle_limit:
                break
            symbol=str(c.symbol); family=str(c.family or c.strategy_mode or "UNKNOWN").upper()
            candle_ts=int(float(getattr(c,"generated_at_ms",0) or 0)/1000.0) if float(getattr(c,"generated_at_ms",0) or 0)>1e11 else int(float(getattr(c,"generated_at_ms",int(WALL_NOW())) or int(WALL_NOW())))
            key=OpportunityTelegramNotifier._opportunity_key(symbol,candle_ts,f"DISCOVERY:{family}")
            if not OpportunityTelegramNotifier._dedup_ok(OpportunityTelegramNotifier._candidate_seen,key,float(CONFIG.get("TELEGRAM_DISCOVERY_DEDUP_SEC",300))):
                continue
            fs=dict(getattr(c,"features_snapshot",{}) or {})
            # v4.5.29: enrich discovery telemetry from the exact engine snapshot
            # before falling back to placeholders. Candidate engine_score may be
            # valid even when its frozen feature snapshot is intentionally sparse.
            if bool(CONFIG.get("V529_DISCOVERY_CONTEXT_ENABLE", True)):
                for _k in ("htf_strength","htf_alignment","volume_ratio","chase_atr",
                           "liquidity_tier","tier","macro_regime","local_regime",
                           "market_phase","htf_state","htf_reason"):
                    if fs.get(_k) in (None, "", 0, 0.0):
                        if snapshot.get(_k) not in (None, "", 0, 0.0):
                            fs[_k]=snapshot.get(_k)
                if not fs.get("liquidity_tier") and snapshot.get("tier"):
                    fs["liquidity_tier"]=snapshot.get("tier")
            entry=float(c.entry_ref); sl=float(c.sl_price); risk=max(entry-sl,0.0)
            if entry<=0 or sl<=0 or risk<=0:
                continue
            tp1=entry+float(c.tp1_rr)*risk; tp2=entry+float(c.tp2_rr)*risk; tp3=entry+float(c.tp3_rr)*risk
            # Derive any still-missing fields from the same snapshot/closed bars.
            htf=float(fs.get("htf_strength",fs.get("htf_alignment",0.0)) or 0.0)
            vol=float(fs.get("volume_ratio",0.0) or 0.0)
            rs=_v528_rs_feature(c)
            if rs == 0.0 and bool(CONFIG.get("V529_DISCOVERY_CONTEXT_ENABLE", True)):
                try:
                    rs_candidate = dict(fs).get("rs_5m")
                    if rs_candidate is not None:
                        rv=float(rs_candidate); rs=rv/100.0 if abs(rv)>1.5 else rv
                except Exception:
                    _v647_record_suppressed_exception()
            chase=float(fs.get("chase_atr",0.0) or 0.0)
            tier=str(fs.get("liquidity_tier",fs.get("tier", "")) or "").upper()
            _ctx_fields=[htf>0.0, vol>0.0, abs(rs)>0.0, tier not in {"","N/A"}]
            ctx_count=sum(1 for _x in _ctx_fields if _x)
            context_complete = ctx_count >= int(CONFIG.get("V529_DISCOVERY_MIN_CONTEXT_FOR_STRONG_GRADE",3))
            if not context_complete:
                grade="UNVERIFIED"
                _conf=0.0
                if bool(CONFIG.get("V529_DISCOVERY_WARN_INCOMPLETE",True)):
                    STATS["telegram_discovery_incomplete_context"] = int(STATS.get("telegram_discovery_incomplete_context",0) or 0)+1
            else:
                grade,_conf=OpportunityTelegramNotifier._opportunity_grade(score,62.0,htf,vol,rs,chase,tier,family)
            tv=OpportunityTelegramNotifier._tradingview_link(symbol)
            mx=OpportunityTelegramNotifier._mexc_link(symbol)
            links=[]
            if tv: links.append(f'<a href="{OpportunityTelegramNotifier._escape(tv)}">📱 TradingView</a>')
            if mx: links.append(f'<a href="{OpportunityTelegramNotifier._escape(mx)}">🟢 MEXC</a>')
            lines=[
                "ℹ️ <b>DISCOVERY SIGNAL — KNOWLEDGE ONLY</b>",
                "",
                f"<b>{OpportunityTelegramNotifier._escape(symbol)}</b>",
                f"Strategy: <b>{OpportunityTelegramNotifier._escape(family)}</b>",
                f"Engine Score: <b>{score:.1f}</b> | Grade: <b>{OpportunityTelegramNotifier._escape(grade)}</b>",
                f"HTF: {htf:.1f} | Vol: x{vol:.2f} | RS: {rs*100:.2f}% | Chase: {chase:.2f} ATR | Tier: {OpportunityTelegramNotifier._escape(tier or 'N/A')}",
                f"Context: <b>{'VERIFIED' if context_complete else 'INCOMPLETE'}</b> | Source: engine snapshot + candidate features",
                f"Entry: <b>{OpportunityTelegramNotifier._fmt_px(entry)}</b> | SL: {OpportunityTelegramNotifier._fmt_px(sl)}",
                f"TP1: {OpportunityTelegramNotifier._fmt_px(tp1)} | TP2: {OpportunityTelegramNotifier._fmt_px(tp2)} | TP3: {OpportunityTelegramNotifier._fmt_px(tp3)}",
                "<i>This alert is for knowledge/monitoring only. It does NOT authorize, queue, or submit a live order. The canonical live floor remains unchanged.</i>",
            ]
            if links: lines += ["", " | ".join(links)]
            try:
                loop=asyncio.get_running_loop(); loop.create_task(TelegramDispatcher.enqueue("\n".join(lines)))
            except RuntimeError:
                continue
            sent+=1
            STATS["telegram_discovery_alerts"] = int(STATS.get("telegram_discovery_alerts",0) or 0)+1
            STATS["telegram_discovery_last_score"] = score
            STATS["telegram_discovery_last_symbol"] = symbol
        except Exception:
            continue

# Forensics line for the operator heartbeat.
def v528_forensics_line() -> str:
    try:
        f=v528_reject_forensics(); top=f.get("top",[])
        parts=[]
        for x in top[:int(CONFIG.get("V528_REJECT_LEDGER_TOP_N",5))]:
            parts.append(f"{x.get('symbol')}:{x.get('score'):.1f}/{x.get('reason')}")
        return f"[V528-FORENSICS] top_rejected={','.join(parts) or '-'} htf_policy={int(STATS.get('v528_htf_policy_rejects',0) or 0)} htf_strength={int(STATS.get('v528_htf_strength_rejects',0) or 0)} htf_alignment={int(STATS.get('v528_htf_alignment_rejects',0) or 0)} recovery_pass={int(STATS.get('v528_htf_recovery_passes',0) or 0)} spread_relief={int(STATS.get('v528_quality_spread_reliefs',0) or 0)}"
    except Exception:
        return "[V528-FORENSICS] unavailable"

# Add V528 forensics to the existing heartbeat log/Telegram without changing
