def _v531_self_test():
    checks={}
    checks["version_535"] = _v45_patch_at_least(35)
    checks["execution_refill_enabled"] = bool(CONFIG.get("V453_OPPORTUNITY_REFILL_ENABLE", True)) and int(CONFIG.get("V453_OPPORTUNITY_REFILL_MAX_ATTEMPTS",10)) >= 8
    checks["balance_retry_bounded"] = (
        bool(CONFIG.get("V535_RETRY_SAME_CANDIDATE_AFTER_BALANCE_REFRESH", True))
        and 1 <= int(CONFIG.get("V534_PRESEND_BALANCE_RECOVERY_MAX", 1)) <= 2
    )
    checks["network_timeout_not_blind_retried"] = bool(CONFIG.get("V533_NETWORK_TIMEOUT_NO_BLIND_RETRY", True))
    checks["execution_attempt_cap_bounded"] = 1 <= int(CONFIG.get("V535_MAX_TOTAL_EXECUTION_ATTEMPTS_PER_CYCLE",12)) <= 20
    checks["live_floor_preserved"] = float(CONFIG.get("V453_SCORE_FLOOR_MIN",70.0)) >= 70.0
    checks["discovery_raw_prefilter_ge55"] = float(CONFIG.get("V531_DISCOVERY_MIN_SCORE",55.0)) >= 55.0
    checks["discovery_reviewed_floor_ge80"] = float(CONFIG.get("V531_DISCOVERY_MIN_REVIEWED_SCORE",80.0)) >= 80.0
    checks["discovery_cycle_cap_bounded"] = 1 <= int(CONFIG.get("V531_DISCOVERY_MAX_PER_CYCLE",12)) <= 20
    checks["discovery_family_quota_bounded"] = 1 <= int(CONFIG.get("V531_DISCOVERY_MAX_PER_FAMILY_PER_CYCLE",2)) <= 5
    checks["dedup_family_coverage"] = float(CONFIG.get("V531_DISCOVERY_SYMBOL_DEDUP_SEC",1800)) >= 1800
    checks["v570_feasibility_adjustment_bounded"] = 0.0 <= float(CONFIG.get("V570_CANONICAL_MAX_ADJUSTMENT_PTS",16.0)) <= 25.0
    checks["stablecoin_usdc"] = _v531_is_stablecoin("USDC/USDT")
    checks["stablecoin_usdt"] = _v531_is_stablecoin("USDT/USDT")
    checks["stablecoin_dai"] = _v531_is_stablecoin("DAI/USDT")
    checks["stablecoin_usdgo"] = _v531_is_stablecoin("USDGO/USDT")
    checks["nonstable_paxg"] = not _v531_is_stablecoin("GOLD(PAXG)/USDT")
    ctx={"htf":100.0,"vol":0.68,"rs":0.004,"chase":0.0,"tier":"MAJORS"}
    reviewed,bd,grade=_v531_review_discovery_score(78.7,ctx,"PULLBACK")
    checks["score_review_finite"] = math.isfinite(reviewed) and 0<=reviewed<=100
    checks["score_review_does_not_increase_weak"] = _v531_review_discovery_score(55.0,{"htf":100.0,"vol":0.39,"rs":0.0,"chase":0.0,"tier":"MAJORS"},"PULLBACK")[0] < 55.0
    checks["score_review_rewards_strong_rs"] = _v531_review_discovery_score(75.0,{"htf":100.0,"vol":1.4,"rs":0.06,"chase":0.2,"tier":"LARGE"},"BREAKOUT_RETEST")[0] > 75.0
    checks["stablecoin_does_not_get_review"] = _v531_is_stablecoin("USDC/USDT")
    return {"pass": all(checks.values()), "checks": checks, "reviewed_example": {"score": reviewed,"grade":grade,"breakdown":bd}}

_orig_validate_config_v531 = _validate_config_v530

def _validate_config_v531():
    ok=_orig_validate_config_v531()
    if not ok:
        return False
    try:
        rep=_v531_self_test(); STATS["v531_selftest"]=rep
        if not rep.get("pass",False):
            logger.critical(f"[V531] self-test FAILED: {rep}")
            return False
        logger.info("[V531] score-review + stablecoin + discovery-closure PASS")
        return True
    except Exception as exc:
        logger.critical(f"[V531] validation exception: {exc}")
        return False


# =============================================================================
# v4.5.37 — UNIVERSAL DUAL-CONFIRMATION LIVE ENTRY CLOSURE
# =============================================================================
# Root cause addressed from the supplied live logs:
#   GEN/HARD/PRE/RANK/SEL were active, but Q/S remained zero while execution
#   attempts were being made. The existing score/funnel therefore proved only
#   that candidates were discovered/selected; it did not prove that the live
#   entry trigger was structurally confirmed at the current price.
#
# New design, additive and fail-closed:
#   A) BREAKOUT_CONFIRMATION:
#        dynamic 15m resistance -> closed 15m close above it -> volume pulse ->
#        bounded breakout extension/chase -> 1h/4h quality checks.
#   B) SUPPORT_REVERSAL:
#        dynamic 15m support zone -> closed 15m rejection/reversal -> RSI
#        recovery -> rising/adequate volume -> 1h/4h quality checks.
#
# This is UNIVERSAL: no XRP-specific levels. Levels are computed per symbol
# from closed 15m structure. Every existing candidate is still required to pass
# the canonical pipeline, and the new gate is applied immediately before the
# canonical build. Discovery remains knowledge-only.
#
# Safety invariants preserved:
#   LONG_ONLY / MEXC SPOT / stablecoin exclusion / balance truth / exposure /
#   HTF / liquidity / structure / PreSend / TruthSeal / SL verification /
#   watchdog / circuit breakers / execution cooldown / no blind network retry.
# =============================================================================

