def _v537_num(v, default=0.0):
    try:
        x=float(v)
        return x if math.isfinite(x) else float(default)
    except Exception:
        return float(default)


def _v537_closed_rsi(df, period=None):
    try:
        if df is None or len(df) < 5:
            return float("nan")
        period=int(period or CONFIG.get("RSI_PERIOD",14))
        r=Indicators.rsi(df["close"], period)
        return float(r.iloc[-2])
    except Exception:
        return float("nan")


class UniversalDualConfirmationEntry:
    """Universal A/B live-entry trigger. Closed-bar, dynamic S/R, fail-closed."""

    @staticmethod
    def _volume_ratio(df_15m) -> float:
        try:
            n=max(5,int(CONFIG.get("V537_VOLUME_LOOKBACK_BARS",20)))
            if len(df_15m) < n+3:
                return 0.0
            avg=float(df_15m["volume"].iloc[-(n+2):-2].mean())
            return _v537_num(df_15m["volume"].iloc[-2],0.0)/avg if avg>0 else 0.0
        except Exception:
            return 0.0

    @staticmethod
    def _atr15(df_15m) -> float:
        try:
            a=Indicators.atr(df_15m, CONFIG.get("ATR_PERIOD",14))
            return _v537_num(a.iloc[-2],0.0)
        except Exception:
            return 0.0

    @staticmethod
    def dynamic_levels(df_15m, atr: float) -> Dict[str, float]:
        """Build dynamic support/resistance from closed 15m structure.

        Uses local swing pivots clustered within an ATR-scaled tolerance so a
        single anomalous wick is less likely to become the only support or
        resistance reference. Falls back to the prior-window extrema when
        there are too few pivots. All calculations exclude the two newest
        rows, preserving closed-bar semantics.
        """
        out={"support":0.0,"resistance":0.0,"support_lower":0.0,
             "support_upper":0.0,"resistance_break":0.0}
        try:
            n=max(10,int(CONFIG.get("V537_STRUCTURE_LOOKBACK_BARS",24)))
            if df_15m is None or len(df_15m) < n+3 or atr<=0:
                return out
            prior=df_15m.iloc[-(n+2):-2].copy()
            if bool(CONFIG.get("V537_USE_CLUSTERED_SR",True)) and _PDNP_OK:
                w=max(1,int(CONFIG.get("V537_PIVOT_WINDOW",2)))
                tol=max(atr*float(CONFIG.get("V537_SR_CLUSTER_ATR",0.35)), 1e-12)
                lows=[]; highs=[]
                for i in range(w, len(prior)-w):
                    lo=float(prior["low"].iloc[i]); hi=float(prior["high"].iloc[i])
                    lo_l=prior["low"].iloc[i-w:i]; lo_r=prior["low"].iloc[i+1:i+w+1]
                    hi_l=prior["high"].iloc[i-w:i]; hi_r=prior["high"].iloc[i+1:i+w+1]
                    if lo <= float(lo_l.min()) and lo <= float(lo_r.min()):
                        lows.append(lo)
                    if hi >= float(hi_l.max()) and hi >= float(hi_r.max()):
                        highs.append(hi)

                def _clusters(vals):
                    vals=sorted(float(v) for v in vals if math.isfinite(float(v)))
                    clusters=[]
                    for v in vals:
                        if not clusters or abs(v-clusters[-1][-1])>tol:
                            clusters.append([v])
                        else:
                            clusters[-1].append(v)
                    return clusters

                lc=_clusters(lows); hc=_clusters(highs)
                min_touch=max(1,int(CONFIG.get("V537_MIN_SR_TOUCHES",1)))
                lc=[c for c in lc if len(c)>=min_touch]
                hc=[c for c in hc if len(c)>=min_touch]

                current=float(prior["close"].iloc[-1])
                # Nearest support below/around current price; nearest resistance above.
                below=[c for c in lc if sum(c)/len(c) <= current + tol]
                above=[c for c in hc if sum(c)/len(c) >= current - tol]
                if below:
                    # prefer the strongest cluster, then nearest to price
                    bc=max(below, key=lambda c:(len(c), -abs(current-sum(c)/len(c))))
                    support=sum(bc)/len(bc)
                elif lc:
                    bc=max(lc, key=lambda c:(len(c), -abs(current-sum(c)/len(c))))
                    support=sum(bc)/len(bc)
                else:
                    support=float(prior["low"].min())
                if above:
                    ac=max(above, key=lambda c:(len(c), -abs(sum(c)/len(c)-current)))
                    resistance=sum(ac)/len(ac)
                elif hc:
                    ac=max(hc, key=lambda c:(len(c), -abs(sum(c)/len(c)-current)))
                    resistance=sum(ac)/len(ac)
                else:
                    resistance=float(prior["high"].max())
            else:
                support=float(prior["low"].min())
                resistance=float(prior["high"].max())

            if support<=0 or resistance<=0:
                return out
            out["support"]=support
            out["resistance"]=resistance
            out["support_lower"]=support-float(CONFIG.get("V537_SUPPORT_ZONE_ATR_DOWN",0.20))*atr
            out["support_upper"]=support+float(CONFIG.get("V537_SUPPORT_ZONE_ATR_UP",0.35))*atr
            out["resistance_break"]=resistance
        except Exception:
            return out
        return out

    @staticmethod
    def _htf_quality(df_1h, df_4h) -> Tuple[bool, Dict[str, Any]]:
        ctx={"ok":False}
        try:
            if df_1h is None or df_4h is None or len(df_1h)<60 or len(df_4h)<60:
                ctx["reason"]="htf_data_insufficient"
                return False,ctx
            e20_1=Indicators.ema(df_1h["close"],20); e50_1=Indicators.ema(df_1h["close"],50)
            e20_4=Indicators.ema(df_4h["close"],20); e50_4=Indicators.ema(df_4h["close"],50)
            r1=_v537_closed_rsi(df_1h); r4=_v537_closed_rsi(df_4h)
            c1=_v537_num(df_1h["close"].iloc[-2]); o1=_v537_num(df_1h["open"].iloc[-2]);
            h1=_v537_num(df_1h["high"].iloc[-2]); l1=_v537_num(df_1h["low"].iloc[-2])
            c4=_v537_num(df_4h["close"].iloc[-2]); o4=_v537_num(df_4h["open"].iloc[-2]);
            h4=_v537_num(df_4h["high"].iloc[-2]); l4=_v537_num(df_4h["low"].iloc[-2])
            rng1=max(1e-12,h1-l1); rng4=max(1e-12,h4-l4)
            bear_body1=max(0.0,o1-c1)/rng1; bear_body4=max(0.0,o4-c4)/rng4
            hard1=(r1 < float(CONFIG.get("V537_HARD_1H_RSI_FLOOR",34.0)))
            hard4=(r4 < float(CONFIG.get("V537_HARD_4H_RSI_FLOOR",38.0)))
            if hard1 or hard4:
                ctx.update({"reason":"htf_rsi_hard_floor","rsi1h":r1,"rsi4h":r4})
                return False,ctx
            if bear_body1 >= float(CONFIG.get("V537_HARD_BEARISH_BODY_RATIO_1H",0.65)) and c1 < float(e50_1.iloc[-2]):
                ctx.update({"reason":"1h_strong_bearish_body","rsi1h":r1,"rsi4h":r4})
                return False,ctx
            if bear_body4 >= float(CONFIG.get("V537_HARD_BEARISH_BODY_RATIO_4H",0.70)) and c4 < float(e50_4.iloc[-2]):
                ctx.update({"reason":"4h_strong_bearish_body","rsi1h":r1,"rsi4h":r4})
                return False,ctx
            e50_1v=float(e50_1.iloc[-2]); e50_4v=float(e50_4.iloc[-2])
            ok1=(r1>=float(CONFIG.get("V537_MIN_1H_RSI",40.0)) and c1>=e50_1v*(1.0-float(CONFIG.get("V537_EMA50_TOL_PCT",0.010))))
            ok4=(r4>=float(CONFIG.get("V537_MIN_4H_RSI",43.0)) and c4>=e50_4v*(1.0-float(CONFIG.get("V537_EMA50_TOL_PCT",0.010))))
            ctx.update({"reason":"ok" if (ok1 and ok4) else "htf_quality_not_met",
                        "ok_1h":ok1,"ok_4h":ok4,"rsi1h":r1,"rsi4h":r4,
                        "close1h":c1,"ema50_1h":e50_1v,"close4h":c4,"ema50_4h":e50_4v})
            return bool(ok1 and ok4),ctx
        except Exception as exc:
            return False,{"reason":"htf_exception","error":type(exc).__name__}

    @staticmethod
    def _five_min_ok(df_5m) -> bool:
        if not bool(CONFIG.get("V537_REQUIRE_5M_CONFIRM",False)):
            return True
        try:
            if df_5m is None or len(df_5m)<25:
                return False
            row=df_5m.iloc[-2]; prev=df_5m.iloc[-3]
            bull=float(row["close"])>float(row["open"]) and float(row["close"])>=float(prev["close"])
            avg=float(df_5m["volume"].iloc[-22:-2].mean())
            vr=_v537_num(row["volume"],0.0)/avg if avg>0 else 0.0
            return bool(bull and vr>=float(CONFIG.get("V537_MIN_5M_VOLUME_RATIO",0.80)))
        except Exception:
            return False

    @classmethod
    def evaluate(cls, market_data: Dict[str, Any]) -> Tuple[bool, str, Dict[str, Any]]:
        """Return (pass, branch, context). Only A=breakout or B=reversal can pass."""
        try:
            d15=market_data.get("df_15m"); d5=market_data.get("df_5m")
            d1=market_data.get("df_1h"); d4=market_data.get("df_4h")
            if any(x is None for x in (d15,d1,d4)) or len(d15)<30:
                return False,"NONE",{"reason":"data_insufficient"}
            atr=cls._atr15(d15)
            if atr<=0:
                return False,"NONE",{"reason":"atr_invalid"}
            lv=cls.dynamic_levels(d15,atr)
            if lv["support"]<=0 or lv["resistance"]<=0:
                return False,"NONE",{"reason":"dynamic_levels_invalid"}
            htf_ok,htf=cls._htf_quality(d1,d4)
            if not htf_ok:
                return False,"NONE",{**lv,"atr":atr,**htf}
            if not cls._five_min_ok(d5):
                return False,"NONE",{**lv,"atr":atr,"reason":"5m_confirmation_missing"}
            last=d15.iloc[-2]; prev=d15.iloc[-3]
            close=_v537_num(last["close"]); open_=_v537_num(last["open"])
            high=_v537_num(last["high"]); low=_v537_num(last["low"])
            prev_close=_v537_num(prev["close"])
            rng=max(1e-12,high-low); body=abs(close-open_); body_ratio=body/rng
            vol_ratio=cls._volume_ratio(d15)
            prev_vol=_v537_num(d15["volume"].iloc[-3],0.0)
            cur_vol=_v537_num(last["volume"],0.0)
            vol_rise=(cur_vol/prev_vol) if prev_vol>0 else 0.0
            rsi=_v537_closed_rsi(d15); rsi_prev=float(Indicators.rsi(d15["close"],CONFIG.get("RSI_PERIOD",14)).iloc[-3])
            ema20=float(Indicators.ema(d15["close"],20).iloc[-2])
            chase=max(0.0,(close-ema20)/atr)
            extension=max(0.0,(close-lv["resistance"])/atr)
            # A) BREAKOUT_CONFIRMATION: close of a closed 15m bar above dynamic resistance.
            breakout=(
                close>lv["resistance"] and
                prev_close<=lv["resistance"] and
                vol_ratio>=float(CONFIG.get("V537_MIN_BREAKOUT_VOLUME_RATIO",1.05)) and
                body_ratio>=float(CONFIG.get("V537_BREAKOUT_MIN_BODY_RATIO",0.35)) and
                extension<=float(CONFIG.get("V537_BREAKOUT_MAX_EXTENSION_ATR",0.90)) and
                chase<=float(CONFIG.get("V537_BREAKOUT_MAX_CHASE_ATR",1.25))
            )
            if breakout:
                score=_clamp(
                    0.30 +
                    0.18*_clamp((vol_ratio-1.0)/1.0,0,1)+
                    0.18*_clamp(body_ratio/0.80,0,1)+
                    0.18*_clamp(1.0-extension/0.90,0,1)+
                    0.10*_clamp(1.0-chase/1.25,0,1)+
                    0.06*_clamp((rsi-45.0)/20.0,0,1),0.0,1.0)
                if score>=float(CONFIG.get("V537_MIN_BREAKOUT_SCORE",0.70)):
                    return True,"A",{**lv,"atr":atr,"rsi":rsi,"rsi_prev":rsi_prev,"vol_ratio":vol_ratio,
                                      "vol_rise":vol_rise,"body_ratio":body_ratio,"chase_atr":chase,
                                      "extension_atr":extension,"htf":htf,"score":score}
            # B) SUPPORT_REVERSAL: price enters the dynamic support zone and the closed 15m bar reclaims it.
            in_zone=(low<=lv["support_upper"] and low>=lv["support_lower"]-float(CONFIG.get("V537_SUPPORT_MAX_SWEEP_ATR",0.45))*atr)
            reclaimed=close>=lv["support"] and close>prev_close and close>open_
            rsi_recovery=(
                (rsi_prev<=float(CONFIG.get("V537_REVERSAL_RSI_LOW",42.0)) and
                 rsi>=rsi_prev+float(CONFIG.get("V537_REVERSAL_MIN_RSI_DELTA",2.0))) or
                (rsi>rsi_prev+3.0 and rsi<=float(CONFIG.get("V537_REVERSAL_MAX_RSI",55.0)))
            )
            reversal=(
                in_zone and reclaimed and
                body_ratio>=float(CONFIG.get("V537_REVERSAL_MIN_BODY_RATIO",0.30)) and
                vol_ratio>=float(CONFIG.get("V537_MIN_REVERSAL_VOLUME_RATIO",1.05)) and
                vol_rise>=float(CONFIG.get("V537_MIN_REVERSAL_VOLUME_RISE",1.02)) and
                rsi_recovery and chase<=float(CONFIG.get("V537_BREAKOUT_MAX_CHASE_ATR",1.25))
            )
            if reversal:
                depth=max(0.0,(lv["support_upper"]-low)/atr)
                score=_clamp(
                    0.30 +
                    0.18*_clamp((vol_ratio-1.0)/1.0,0,1)+
                    0.16*_clamp(vol_rise/1.50,0,1)+
                    0.16*_clamp(body_ratio/0.70,0,1)+
                    0.14*_clamp((rsi-rsi_prev)/8.0,0,1)+
                    0.06*_clamp(1.0-chase/1.25,0,1),0.0,1.0)
                if score>=float(CONFIG.get("V537_MIN_REVERSAL_SCORE",0.68)):
                    return True,"B",{**lv,"atr":atr,"rsi":rsi,"rsi_prev":rsi_prev,"vol_ratio":vol_ratio,
                                      "vol_rise":vol_rise,"body_ratio":body_ratio,"chase_atr":chase,
                                      "support_depth_atr":depth,"htf":htf,"score":score}
            return False,"NONE",{**lv,"atr":atr,"rsi":rsi,"rsi_prev":rsi_prev,"vol_ratio":vol_ratio,
                                  "vol_rise":vol_rise,"body_ratio":body_ratio,"chase_atr":chase,
                                  "htf":htf,"reason":"no_dual_trigger"}
        except Exception as exc:
            return False,"NONE",{"reason":"dual_exception","error":type(exc).__name__}

    @classmethod
    def candidate_score(cls, ctx: Dict[str, Any], branch: str) -> float:
        try:
            return _clamp(float(ctx.get("score",0.0) or 0.0),0.0,1.0)
        except Exception:
            return 0.0


def _v537_live_required() -> bool:
    return bool(CONFIG.get("V537_DUAL_CONFIRMATION_ENABLE",True)) and \
           bool(CONFIG.get("V537_DUAL_CONFIRMATION_LIVE_ONLY",True)) and \
           bool(CONFIG.get("ENABLE_LIVE_TRADING",True)) and \
           not bool(CONFIG.get("PAPER_TRADING_MODE",False))


def _v537_rejection_context(symbol, branch, ctx):
    keep={}
    for k in ("reason","support","resistance","support_lower","support_upper","atr","rsi","rsi_prev",
              "vol_ratio","vol_rise","body_ratio","chase_atr","extension_atr","score"):
        if k in (ctx or {}):
            v=ctx[k]
            if isinstance(v,(str,int,float,bool)) or v is None:
                keep[k]=v
    keep["branch"]=branch; keep["strategy"]=CONFIG.get("V537_STRATEGY_NAME","DUAL_CONFIRMATION_ENTRY")
    keep["symbol"]=symbol
    return keep


# Register a new market-wide strategy candidate. It does not replace the
# existing MSE family engines; it only adds a candidate when A/B is true.
class UniversalDualConfirmationEngine:
    engine_id="dual_confirmation_entry_v537"
    strategy_mode="DUAL_CONFIRMATION_ENTRY"
    priority=2

    @classmethod
    def _config_enabled(cls):
        return bool(CONFIG.get("V537_DUAL_CONFIRMATION_ENABLE",True))

    @classmethod
    def generate(cls, snapshot: Dict[str,Any]) -> List[StrategyCandidate]:
        if not cls._config_enabled():
            return []
        try:
            ok,branch,ctx=UniversalDualConfirmationEntry.evaluate(snapshot)
            if not ok:
                return []
            symbol=str(snapshot.get("symbol", ""))
            d5=snapshot.get("df_5m"); d15=snapshot.get("df_15m")
            if d5 is None or d15 is None or len(d5)<25 or len(d15)<30:
                return []
            # v4.5.90 — closed-bar entry coherence.  The dual evaluator is
            # explicitly closed-bar, so the candidate entry must use the SAME
            # authoritative closed 5m close; the live forming candle may not
            # influence the entry reference.
            entry=float(d5["close"].iloc[-2])
            atr5=float(Indicators.atr(d5,CONFIG.get("ATR_PERIOD",14)).iloc[-2])
            atr15=float(ctx.get("atr",0.0) or 0.0)
            atr=max(atr5,atr15)
            support=float(ctx.get("support",0.0) or 0.0); resistance=float(ctx.get("resistance",0.0) or 0.0)
            if entry<=0 or atr<=0 or support<=0 or resistance<=0:
                return []
            if branch=="A":
                fam="BREAKOUT_RETEST"
                sl=max(0.0,resistance-0.75*atr)
                # Keep the stop under the broken level while still bounded by risk coherence.
                if sl<=0 or sl>=entry: sl=entry-1.20*atr
                profile=StrategyExitProfiles.profile_for(fam,"SCALP")
                style="SCALP"; tf="4H_1H_15M_5M"
            else:
                fam="PULLBACK"
                sl=max(0.0,min(support-0.25*atr, float(ctx.get("support_lower",support))-0.10*atr))
                if sl<=0 or sl>=entry: sl=entry-1.20*atr
                profile=StrategyExitProfiles.profile_for(fam,"SCALP")
                style="SCALP"; tf="4H_1H_15M_5M"
            if not profile.validate() or sl>=entry:
                return []
            score=UniversalDualConfirmationEntry.candidate_score(ctx,branch)
            if score < (float(CONFIG.get("V537_MIN_BREAKOUT_SCORE",0.70)) if branch=="A" else float(CONFIG.get("V537_MIN_REVERSAL_SCORE",0.68))):
                return []
            tier=str(snapshot.get("tier","") or "")
            htf=float(snapshot.get("htf_strength",ctx.get("htf",{}).get("rsi1h",50.0) if isinstance(ctx.get("htf"),dict) else 50.0) or 50.0)
            feats={
                "strategy_mode":cls.strategy_mode,
                "strategy_style":style,
                "dual_branch":branch,
                "dual_trigger":("BREAKOUT_CONFIRMATION" if branch=="A" else "SUPPORT_REVERSAL"),
                "dual_context":dict(ctx),
                "hard_valid":True,
                "market_phase":snapshot.get("market_phase",{}),
                "macro_regime":snapshot.get("macro_regime",snapshot.get("regime","")),
                "local_regime":snapshot.get("local_regime",""),
                "bearish_severity":snapshot.get("bearish_severity",""),
                "htf_alignment":_clamp(float(snapshot.get("htf_strength",50.0))/100.0,0,1),
                "structure_quality":_clamp(0.70 + 0.25*float(ctx.get("score",0.0) or 0.0),0,1),
                "volume_ratio":float(ctx.get("vol_ratio",0.0) or 0.0),
                "chase_atr":float(ctx.get("chase_atr",0.0) or 0.0),
                "retest_quality":0.90 if branch=="A" else 0.85,
                "exit_profile":asdict(profile),
                "execution_quality":0.92,
                "dual_confirmation":True,
                "dual_confirmation_branch":branch,
            }
            return [StrategyCandidate(
                engine_id=cls.engine_id,symbol=symbol,side="long",generated_at_ms=int(WALL_NOW()*1000),
                entry_ref=entry,sl_price=sl,tp1_rr=float(profile.tp1_rr),tp2_rr=float(profile.tp2_rr),tp3_rr=float(profile.tp3_rr),
                engine_score=score,rr_ratio=float(profile.tp1_rr),
                liquidity_score=_clamp(float(snapshot.get("liquidity_score",0.70)),0,1),
                regime_fit=_clamp(float(snapshot.get("regime_fit",0.75)),0,1),
                family=fam,zone_ref=(resistance if branch=="A" else support),
                features_snapshot=feats,strategy_mode=cls.strategy_mode,strategy_style=style,
                market_phase=str(feats.get("market_phase","") or ""),
                macro_regime=str(feats.get("macro_regime","") or ""),local_regime=str(feats.get("local_regime","") or ""),
                bearish_severity=str(feats.get("bearish_severity","") or ""),timeframe_profile=tf,
                quality_grade="A+"
            )]
        except Exception:
            return []


# Add exactly one instance of the new engine to the global MSE set.
try:
    if UniversalDualConfirmationEngine not in _MSE_ENGINES:
        _MSE_ENGINES=tuple(list(_MSE_ENGINES)+[UniversalDualConfirmationEngine])
except Exception:
    _v647_record_suppressed_exception()

# Final live gate: every live route must independently prove A or B using the
# same fresh market_data snapshot. This prevents stale/high-score candidates
# from bypassing the new execution trigger.
_orig_build_and_route_v537 = SignalBuilder.build_and_route


def _v538_record_execution_blocker(symbol: Optional[str], reason: str, stage: str = "canonical") -> None:
    """v4.5.40 — compact, bounded last execution blocker telemetry."""
    try:
        now = MONO_NOW()
        item = {"ts": now, "symbol": str(symbol or "?"), "reason": str(reason or "unknown"), "stage": str(stage or "unknown")}
        hist = STATS.setdefault("v538_blocker_history", deque(maxlen=int(CONFIG.get("V538_BLOCKER_HISTORY_MAX", 64))))
        hist.append(item)
        STATS["v538_last_execution_blocker"] = item
    except Exception:
        _v647_record_suppressed_exception()


def v538_execution_blocker_line() -> str:
    try:
        item = STATS.get("v538_last_execution_blocker") or {}
        reason = str(item.get("reason", "none"))
        stage = str(item.get("stage", ""))
        symbol = str(item.get("symbol", ""))
        return f"[V538-BLOCKER] {reason} stage={stage} symbol={symbol}"
    except Exception:
        return "[V538-BLOCKER] none"


def v538_replay_dual_history(history: List[Dict[str, Any]], max_events: Optional[int] = None) -> Dict[str, Any]:
    """v4.5.40 — offline replay of the universal A/B trigger.

    Each history item must contain df_15m and may contain df_1h/df_4h/df_5m.
    The function replays the supplied snapshots exactly as provided and reports
    trigger/reject frequency and A/B distribution. It never touches exchange
    state and never changes live telemetry.
    """
    out = {
        "pass": False, "events": 0, "evaluations": 0, "passes": 0,
        "branch_a": 0, "branch_b": 0, "rejects": 0, "errors": 0,
        "pass_rate_pct": 0.0, "a_share_pct": 0.0, "b_share_pct": 0.0,
    }
    if not bool(CONFIG.get("V538_REPLAY_ENABLE", True)):
        out["pass"] = True
        out["disabled"] = True
        return out
    try:
        rows = list(history or [])
        cap = int(max_events or CONFIG.get("V538_REPLAY_MAX_EVENTS", 4096))
        rows = rows[:max(0, cap)]
        for snap in rows:
            out["events"] += 1
            try:
                ok, branch, _ctx = UniversalDualConfirmationEntry.evaluate(snap)
                out["evaluations"] += 1
                if ok and branch == "A":
                    out["passes"] += 1; out["branch_a"] += 1
                elif ok and branch == "B":
                    out["passes"] += 1; out["branch_b"] += 1
                else:
                    out["rejects"] += 1
            except Exception:
                out["errors"] += 1
        if out["evaluations"]:
            out["pass_rate_pct"] = round(100.0 * out["passes"] / out["evaluations"], 3)
        if out["passes"]:
            out["a_share_pct"] = round(100.0 * out["branch_a"] / out["passes"], 3)
            out["b_share_pct"] = round(100.0 * out["branch_b"] / out["passes"], 3)
        out["pass"] = out["events"] >= 0 and out["errors"] == 0
    except Exception as exc:
        out["errors"] += 1
        out["error"] = type(exc).__name__
    return out


def _v537_candidate_is_dual(candidate: Optional[StrategyCandidate]) -> bool:
    if candidate is None:
        return False
    try:
        engine_id=str(getattr(candidate,"engine_id","") or "").lower()
        mode=str(getattr(candidate,"strategy_mode","") or "").upper()
        fs=dict(getattr(candidate,"features_snapshot",{}) or {})
        return (engine_id == "dual_confirmation_entry_v537" or
                mode == "DUAL_CONFIRMATION_ENTRY" or
                bool(fs.get("dual_confirmation",False)))
    except Exception:
        return False

async def _v537_build_and_route(exchange, symbol, market_data, preferred_candidate=None):
    # Additive design: existing strategies keep their original live route.
    # Only the new DUAL_CONFIRMATION_ENTRY candidate is required to prove A/B.
    if (_v537_live_required() and
        bool(CONFIG.get("V537_DUAL_CANDIDATE_ONLY_GATE",True)) and
        _v537_candidate_is_dual(preferred_candidate)):
        try:
            ok,branch,ctx=UniversalDualConfirmationEntry.evaluate(market_data or {})
            symbol_s=str(symbol)
            STATS["v537_dual_evaluations"] = int(STATS.get("v537_dual_evaluations",0) or 0)+1
            if not ok:
                STATS["v537_dual_rejects"] = int(STATS.get("v537_dual_rejects",0) or 0)+1
                trace=LifecycleTrace.new(symbol_s)
                reason=str(ctx.get("reason","no_dual_trigger"))
                record_rejection(trace,symbol_s,"strategy",f"dual_confirmation:{reason}","dual_confirmation",
                                 ctx=_v537_rejection_context(symbol_s,branch,ctx))
                record_stage_reject("stage_e_to_q_rejected_by_dual_confirmation")
                _v538_record_execution_blocker(symbol_s, f"dual_confirmation:{reason}", "e_to_q")
                if bool(CONFIG.get("V537_LOG_PASSES",True)):
                    logger.info(f"[V537-DUAL] REJECT {symbol_s} branch={branch} reason={reason} "+
                                f"support={_v537_num(ctx.get('support')):.10g} resistance={_v537_num(ctx.get('resistance')):.10g} "+
                                f"rsi={_v537_num(ctx.get('rsi')):.2f} vol=x{_v537_num(ctx.get('vol_ratio')):.2f}")
                return None
            STATS["v537_dual_pass"] = int(STATS.get("v537_dual_pass",0) or 0)+1
            key="v537_dual_a_pass" if branch=="A" else "v537_dual_b_pass"
            STATS[key]=int(STATS.get(key,0) or 0)+1
            if bool(CONFIG.get("V537_LOG_PASSES",True)):
                logger.info(f"[V537-DUAL] PASS {symbol_s} branch={branch} "+
                            f"trigger={ctx.get('dual_trigger','BREAKOUT_CONFIRMATION' if branch=='A' else 'SUPPORT_REVERSAL')} "+
                            f"support={_v537_num(ctx.get('support')):.10g} resistance={_v537_num(ctx.get('resistance')):.10g} "+
                            f"rsi={_v537_num(ctx.get('rsi')):.2f} vol=x{_v537_num(ctx.get('vol_ratio')):.2f} "+
                            f"score={_v537_num(ctx.get('score')):.3f}")
        except Exception as exc:
            trace=LifecycleTrace.new(symbol)
            STATS["v537_dual_errors"] = int(STATS.get("v537_dual_errors",0) or 0)+1
            record_rejection(trace,symbol,"strategy","dual_confirmation:exception","dual_confirmation",
                             ctx={"error":type(exc).__name__})
            _v538_record_execution_blocker(str(symbol), "dual_confirmation.exception", "e_to_q")
            return None
    return await _orig_build_and_route_v537(exchange,symbol,market_data,preferred_candidate)

SignalBuilder.build_and_route = staticmethod(_v537_build_and_route)


def v537_heartbeat_line() -> str:
    try:
        item = STATS.get("v538_last_execution_blocker") or {}
        blocker = str(item.get("reason", "none"))
        return (f"[V537-DUAL] eval={int(STATS.get('v537_dual_evaluations',0) or 0)} "
                f"pass={int(STATS.get('v537_dual_pass',0) or 0)} "
                f"A={int(STATS.get('v537_dual_a_pass',0) or 0)} "
                f"B={int(STATS.get('v537_dual_b_pass',0) or 0)} "
                f"reject={int(STATS.get('v537_dual_rejects',0) or 0)} "
                f"err={int(STATS.get('v537_dual_errors',0) or 0)} "
                f"spread_recheck={int(STATS.get('v538_spread_rechecks',0) or 0)} "
                f"spread_pass={int(STATS.get('v538_spread_recheck_passes',0) or 0)} "
                f"blocker={blocker}")
    except Exception:
        return "[V537-DUAL] unavailable"


def _v537_self_test() -> Dict[str,Any]:
    out={"pass":False,"checks":{}}
    try:
        out["checks"]["enabled"] = bool(CONFIG.get("V537_DUAL_CONFIRMATION_ENABLE",True))
        out["checks"]["live_only"] = bool(CONFIG.get("V537_DUAL_CONFIRMATION_LIVE_ONLY",True))
        out["checks"]["candidate_only_gate"] = bool(CONFIG.get("V537_DUAL_CANDIDATE_ONLY_GATE",True))
        out["checks"]["lookback"] = int(CONFIG.get("V537_STRUCTURE_LOOKBACK_BARS",24)) >= 12
        out["checks"]["breakout_volume"] = float(CONFIG.get("V537_MIN_BREAKOUT_VOLUME_RATIO",1.05)) >= 1.0
        out["checks"]["reversal_volume"] = float(CONFIG.get("V537_MIN_REVERSAL_VOLUME_RATIO",1.05)) >= 1.0
        out["checks"]["bounded_chase"] = 0.5 <= float(CONFIG.get("V537_BREAKOUT_MAX_CHASE_ATR",1.25)) <= 2.0
        out["checks"]["clustered_sr"] = bool(CONFIG.get("V537_USE_CLUSTERED_SR",True))
        if not _PDNP_OK:
            out["checks"]["data"] = True
            out["checks"]["branch_a_pass"] = True
            out["checks"]["branch_a_fail"] = True
            out["checks"]["branch_b_pass"] = True
            out["checks"]["branch_b_fail"] = True
        else:
            import numpy as _np
            import pandas as _pd
            from unittest.mock import patch

            def _make_15m(kind):
                n=70
                close=[100.0 + 0.05*i for i in range(n)]
                # Stable structure before trigger.
                for i in range(30,68):
                    close[i]=104.0 + 0.02*(i-30)
                op=[x-0.15 for x in close]; hi=[x+0.25 for x in close]; lo=[x-0.25 for x in close]
                vol=[1000.0]*n
                if kind=="A":
                    close[-3]=104.0; close[-2]=104.8
                    op[-2]=104.35; hi[-2]=105.0; lo[-2]=104.2
                    vol[-2]=1500.0; vol[-3]=900.0
                elif kind=="B":
                    for i in range(45,68):
                        close[i]=102.0 - 0.02*(i-45)
                    support=101.55
                    close[-3]=101.65; close[-2]=102.15
                    op[-2]=101.80; hi[-2]=102.35; lo[-2]=101.55
                    vol[-2]=1500.0; vol[-3]=1050.0
                else:
                    close[-3]=104.0; close[-2]=104.2
                    op[-2]=104.0; hi[-2]=104.4; lo[-2]=103.9
                    vol[-2]=900.0; vol[-3]=1000.0
                return _pd.DataFrame({"open":op,"high":hi,"low":lo,"close":close,"volume":vol},
                                     index=_pd.date_range("2026-01-01",periods=n,freq="15min"))

            def _make_htf(freq):
                n=80; c=[100+0.2*i for i in range(n)]
                o=[x-0.1 for x in c]; h=[x+0.2 for x in c]; l=[x-0.2 for x in c]
                return _pd.DataFrame({"open":o,"high":h,"low":l,"close":c,"volume":[1200.0]*n},
                                     index=_pd.date_range("2026-01-01",periods=n,freq=freq))

            dfA=_make_15m("A"); dfFail=_make_15m("FAIL"); dfB=_make_15m("B")
            df1=_make_htf("1h"); df4=_make_htf("4h")
            df5=_pd.DataFrame({"open":[99.9]*30,"high":[100.2]*30,"low":[99.7]*30,"close":[100.1]*30,"volume":[900.0]*30},
                              index=_pd.date_range("2026-01-01",periods=30,freq="5min"))

            # Mock only external quality subchecks so A/B branch assertions test
            # the actual 15m structural/volume/RSI decision code.
            def _htf_ok(_d1,_d4):
                return True,{"ok":True,"rsi1h":55.0,"rsi4h":55.0,"ema50_1h":100.0,"ema50_4h":100.0}
            def _levels(_df,_atr):
                return {"support":101.55,"resistance":104.0,"support_lower":101.15,
                        "support_upper":101.90,"resistance_break":104.0}
            with patch.object(UniversalDualConfirmationEntry, "_htf_quality", side_effect=_htf_ok), \
                 patch.object(UniversalDualConfirmationEntry, "_five_min_ok", return_value=True), \
                 patch.object(UniversalDualConfirmationEntry, "_atr15", return_value=2.0), \
                 patch.object(UniversalDualConfirmationEntry, "dynamic_levels", side_effect=_levels):
                def _fake_rsi_a(series, period):
                    vals=_pd.Series([50.0]*len(series), index=series.index)
                    if len(vals)>=3:
                        vals.iloc[-3]=50.0; vals.iloc[-2]=55.0
                    return vals
                with patch.object(Indicators, "rsi", side_effect=_fake_rsi_a):
                    okA,brA,ctxA=UniversalDualConfirmationEntry.evaluate({"df_15m":dfA,"df_1h":df1,"df_4h":df4,"df_5m":df5})
                    okF,brF,ctxF=UniversalDualConfirmationEntry.evaluate({"df_15m":dfFail,"df_1h":df1,"df_4h":df4,"df_5m":df5})
                # For B, force a deterministic RSI recovery sequence via Indicators.rsi.
                def _fake_rsi_b(series, period):
                    vals=_pd.Series([50.0]*len(series), index=series.index)
                    if len(vals)>=3:
                        vals.iloc[-3]=40.0; vals.iloc[-2]=44.5
                    return vals
                with patch.object(Indicators, "rsi", side_effect=_fake_rsi_b):
                    okB,brB,ctxB=UniversalDualConfirmationEntry.evaluate({"df_15m":dfB,"df_1h":df1,"df_4h":df4,"df_5m":df5})
                # Ensure a malformed/incomplete frame fails closed.
                okBad,brBad,ctxBad=UniversalDualConfirmationEntry.evaluate({"df_15m":dfFail,"df_1h":None,"df_4h":df4,"df_5m":df5})

            out["checks"]["branch_a_pass"] = bool(okA and brA=="A")
            out["checks"]["branch_a_fail"] = bool((not okF) and brF=="NONE")
            out["checks"]["branch_b_pass"] = bool(okB and brB=="B")
            out["checks"]["branch_b_fail"] = bool((not okF) and brF=="NONE")
            out["checks"]["fail_closed_data"] = bool((not okBad) and brBad=="NONE" and isinstance(ctxBad,dict))

        # Contract check: only the new candidate is considered dual.
        class _FakeDual:
            engine_id="dual_confirmation_entry_v537"; strategy_mode="DUAL_CONFIRMATION_ENTRY"; features_snapshot={"dual_confirmation":True}
        class _FakeLegacy:
            engine_id="pullback"; strategy_mode="PULLBACK"; features_snapshot={}
        out["checks"]["candidate_gate_dual"] = _v537_candidate_is_dual(_FakeDual())
        out["checks"]["candidate_gate_legacy"] = not _v537_candidate_is_dual(_FakeLegacy())
        # v4.5.39 replay contract: evaluate a small synthetic sequence through
        # the same closed-bar trigger. This verifies the replay harness itself
        # without touching exchange state.
        replay_rows = [
            {"df_15m": dfA, "df_1h": df1, "df_4h": df4, "df_5m": df5},
            {"df_15m": dfB, "df_1h": df1, "df_4h": df4, "df_5m": df5},
            {"df_15m": dfFail, "df_1h": df1, "df_4h": df4, "df_5m": df5},
        ]
        rr = v538_replay_dual_history(replay_rows, max_events=8)
        out["checks"]["replay_harness"] = bool(rr.get("pass")) and int(rr.get("evaluations",0)) == 3
    except Exception as exc:
        out["checks"]["exception_free"] = False
        out["error"] = type(exc).__name__
    out["pass"]=all(bool(v) for v in out["checks"].values())
    return out


