def _v540_self_test() -> Dict[str, Any]:
    checks: Dict[str, bool] = {}
    try:
        checks["version_541"] = _v45_patch_at_least(41)

        strong = {
            "score": 96.0, "htf": 96.0, "vol": 0.90,
            "rs": 0.02, "chase": 0.60, "tier": "LARGE"
        }
        weak = {
            "score": 88.0, "htf": 95.0, "vol": 0.80,
            "rs": 0.01, "chase": 0.50, "tier": "LARGE"
        }
        strong["reviewed_score"] = 95.0
        weak["reviewed_score"] = 88.0
        checks["elite_strong_pass"] = _v540_is_elite(strong)
        checks["elite_weak_fail"] = not _v540_is_elite(weak)
        checks["elite_reviewed_gate_present"] = float(CONFIG.get("V540_ELITE_MIN_REVIEWED_SCORE", 0.0)) >= 90.0

        # Final policy: tier spread remains a hard gate; the historical
        # ultra-elite spread override is deliberately disabled.
        checks["elite_spread_override_disabled"] = not bool(
            CONFIG.get("V549_ULTRA_ELITE_SPREAD_ENABLE", True)
        )
        checks["elite_spread_allow_disabled"] = not bool(
            CONFIG.get("V549_ULTRA_ELITE_SPREAD_ENABLE", True)
        )

        # Existing global tier ceiling must still pass ordinary in-range spreads.
        checks["base_spread_still_passes"] = tier_spread_hard_ok_v410(0.12, "MAJORS")[0]

        checks["fake_break_breakout_hard"] = "BREAKOUT_RETEST" in {
            str(x).upper() for x in CONFIG.get("FAKE_BREAK_HARD_FAMILIES", ())
        }
        checks["fake_break_pullback_not_hard"] = "PULLBACK" not in {
            str(x).upper() for x in CONFIG.get("FAKE_BREAK_HARD_FAMILIES", ())
        }

        checks["discovery_reviewed_floor_80"] = float(
            CONFIG.get("V531_DISCOVERY_MIN_REVIEWED_SCORE", 65.0)
        ) >= 80.0
        checks["discovery_cycle_cap_bounded"] = 1 <= int(
            CONFIG.get("V531_DISCOVERY_MAX_PER_CYCLE", 12)
        ) <= 20
        checks["discovery_family_quota_bounded"] = 1 <= int(
            CONFIG.get("V531_DISCOVERY_MAX_PER_FAMILY_PER_CYCLE", 2)
        ) <= 5
        checks["starv_alert_interval_ge15m"] = float(
            CONFIG.get("V422_STARV_ALERT_MIN_INTERVAL_SEC", 300)
        ) >= 900.0
        checks["dual_candidate_only_preserved"] = bool(
            CONFIG.get("V537_DUAL_CANDIDATE_ONLY_GATE", True)
        )
        checks["elite_rank_bonus_bounded"] = 0.0 <= float(
            CONFIG.get("V540_ELITE_RANK_BONUS", 0.012)
        ) <= 0.02

        # The elite lane must not authorize itself without full live state.
        checks["elite_not_execution_authority"] = (
            callable(getattr(PreSendGate, "evaluate", None))
            and str(getattr(LIVE_STATE, "current", "BOOT")) in LIVE_STATES
        )
    except Exception as exc:
        checks["exception_free"] = False
        return {"pass": False, "checks": checks, "error": type(exc).__name__}
    checks["exception_free"] = True
    return {"pass": all(bool(v) for v in checks.values()), "checks": checks}



