# v4.5.46 — PENDING OPPORTUNITY HANDOFF
# =============================================================================
_V546_PENDING_HANDOFF: Dict[str, Dict[str, Any]] = {}
_V546_PENDING_LOCK = threading.RLock()

def _v546_register_pending_candidate(candidate: Any, reviewed_score: float,
                                     preflight_ok: bool, preflight_reason: str,
                                     snapshot: Optional[Dict[str, Any]] = None) -> None:
    """Store a bounded, fresh, knowledge-only opportunity for later handoff.

    This registry never places an order. It is merely a short-lived bridge
    between discovery and the canonical live funnel when global arbitration
    leaves a usable execution slot unused.
    """
    try:
        if not bool(CONFIG.get("V546_PENDING_HANDOFF_ENABLE", True)):
            return
        if candidate is None:
            return
        symbol = str(getattr(candidate, "symbol", "") or "")
        if not symbol or _v531_is_stablecoin(symbol):
            return
        reviewed = float(reviewed_score or 0.0)
        if not math.isfinite(reviewed) or reviewed < float(CONFIG.get("V546_PENDING_HANDOFF_MIN_REVIEWED_SCORE", 90.0)):
            return
        if bool(CONFIG.get("V546_PENDING_HANDOFF_REQUIRE_PREFLIGHT_PASS", True)) and not bool(preflight_ok):
            return
        generated_ms = getattr(candidate, "generated_at_ms", None)
        age = _wall_age_sec(generated_ms)
        ttl = float(CONFIG.get("V546_PENDING_HANDOFF_TTL_SEC", 390.0))
        if age is None or age > ttl:
            return
        entry = float(getattr(candidate, "entry_ref", 0.0) or 0.0)
        sl = float(getattr(candidate, "sl_price", 0.0) or 0.0)
        risk = entry - sl
        if not (entry > 0 and sl > 0 and math.isfinite(entry) and math.isfinite(sl) and risk > 0):
            return
        tp1 = entry + float(getattr(candidate, "tp1_rr", 0.0) or 0.0) * risk
        tp2 = entry + float(getattr(candidate, "tp2_rr", 0.0) or 0.0) * risk
        tp3 = entry + float(getattr(candidate, "tp3_rr", 0.0) or 0.0) * risk
        ranked = RankedCandidate(candidate=candidate, composite=float(getattr(candidate, "engine_score", 0.0) or 0.0),
                                 tp1_abs=tp1, tp2_abs=tp2, tp3_abs=tp3)
        with _V546_PENDING_LOCK:
            _V546_PENDING_HANDOFF[symbol] = {
                "ranked": ranked,
                "reviewed_score": reviewed,
                "preflight_ok": bool(preflight_ok),
                "preflight_reason": str(preflight_reason or "pass"),
                "stored_wall": WALL_NOW(),
                "stored_age_sec": age,
                "family": str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "")),
                "snapshot_hint": dict(snapshot or {}) if isinstance(snapshot, dict) else {},
            }
            max_pending = max(1, int(CONFIG.get("V546_PENDING_HANDOFF_MAX", 6)))
            if len(_V546_PENDING_HANDOFF) > max_pending:
                # Drop the stalest / lowest reviewed opportunity first.
                victims = sorted(_V546_PENDING_HANDOFF.items(),
                                 key=lambda kv: (float(kv[1].get("reviewed_score", 0.0)),
                                                 float(kv[1].get("stored_wall", 0.0))))
                for victim, _ in victims[:max(0, len(_V546_PENDING_HANDOFF) - max_pending)]:
                    _V546_PENDING_HANDOFF.pop(victim, None)
        STATS["v546_pending_registered"] = int(STATS.get("v546_pending_registered", 0) or 0) + 1
        STATS["v546_pending_count"] = len(_V546_PENDING_HANDOFF)
    except Exception:
        _v647_record_suppressed_exception()

def _v546_pending_candidates(current_market_data: Dict[str, Dict[str, Any]],
                             existing_symbols: set) -> List[RankedCandidate]:
    """Return bounded pending candidates that are still fresh and currently scannable."""
    out: List[RankedCandidate] = []
    if not bool(CONFIG.get("V546_PENDING_HANDOFF_ENABLE", True)):
        return out
    now = WALL_NOW()
    ttl = float(CONFIG.get("V546_PENDING_HANDOFF_TTL_SEC", 390.0))
    max_take = max(0, int(CONFIG.get("V546_PENDING_HANDOFF_MAX_PER_CYCLE", 3)))
    with _V546_PENDING_LOCK:
        items = list(_V546_PENDING_HANDOFF.items())
    items.sort(key=lambda kv: float(kv[1].get("reviewed_score", 0.0)), reverse=True)
    expired = []
    for symbol, rec in items:
        if len(out) >= max_take:
            break
        ranked = rec.get("ranked")
        cand = getattr(ranked, "candidate", None)
        if ranked is None or cand is None or symbol in existing_symbols:
            continue
        if symbol not in current_market_data:
            continue
        age = _wall_age_sec(getattr(cand, "generated_at_ms", None))
        if age is None or age > ttl:
            expired.append(symbol)
            continue
        out.append(ranked)
    if expired:
        with _V546_PENDING_LOCK:
            for s in expired:
                _V546_PENDING_HANDOFF.pop(s, None)
    STATS["v546_pending_count"] = len(_V546_PENDING_HANDOFF)
    STATS["v546_pending_eligible_current"] = len(out)
    return out

def _v546_mark_pending_attempt(symbol: str, success: bool = False, reason: str = "") -> None:
    try:
        with _V546_PENDING_LOCK:
            _V546_PENDING_HANDOFF.pop(str(symbol), None)
        STATS["v546_pending_promotions"] = int(STATS.get("v546_pending_promotions", 0) or 0) + 1
        if success:
            STATS["v546_pending_successes"] = int(STATS.get("v546_pending_successes", 0) or 0) + 1
        elif reason:
            reasons = STATS.setdefault("v546_pending_reasons", {})
            reasons[str(reason)[:160]] = int(reasons.get(str(reason)[:160], 0) or 0) + 1
    except Exception:
        _v647_record_suppressed_exception()

# v4.5.42 — EXECUTION PARITY / DISCOVERY-LIVE COHERENCE CLOSURE
# =============================================================================

def _v542_record_preflight(symbol: str, ok: bool, reason: str = "", ctx: Optional[Dict[str, Any]] = None) -> None:
    """Telemetry-only accounting for just-in-time canonical preflight."""
    try:
        if ok:
            STATS["v542_preflight_pass"] = int(STATS.get("v542_preflight_pass", 0) or 0) + 1
            STATS["v542_last_preflight_symbol"] = str(symbol)
            STATS["v542_last_preflight_reason"] = "pass"
            return
        STATS["v542_preflight_block"] = int(STATS.get("v542_preflight_block", 0) or 0) + 1
        key = str(reason or "unknown")[:180]
        counts = STATS.get("v542_preflight_reasons")
        if not isinstance(counts, dict):
            counts = {}
            STATS["v542_preflight_reasons"] = counts
        counts[key] = int(counts.get(key, 0) or 0) + 1
        STATS["v542_last_preflight_symbol"] = str(symbol)
        STATS["v542_last_preflight_reason"] = key
        if ctx:
            STATS["v542_last_preflight_ctx"] = {
                k: ctx.get(k) for k in (
                    "family", "strategy_mode", "regime", "local_regime", "tier",
                    "htf_strength", "candidate_age_sec", "reviewed_score"
                ) if k in ctx
            }
    except Exception:
        _v647_record_suppressed_exception()


def _v542_exact_policy_precheck(symbol: str, candidate: Any, snapshot: Dict[str, Any]) -> Tuple[bool, str, Dict[str, Any]]:
    """Re-run the SAME canonical prequalification used by global arbitration.

    This is deliberately a JIT parity check, not a new strategy. It exists to
    prevent a globally-selected candidate from spending an execution attempt
    when the current live snapshot already proves the candidate is blocked by
    the canonical policy/HTF/structure/fake-break gates.
    """
    ctx: Dict[str, Any] = {
        "symbol": str(symbol or ""),
        "family": str(getattr(candidate, "family", "") or "").upper(),
        "strategy_mode": str(getattr(candidate, "strategy_mode", "") or getattr(candidate, "family", "") or "").upper(),
        "regime": str((snapshot or {}).get("regime") or ""),
        "local_regime": str((snapshot or {}).get("local_regime") or ""),
        "tier": str((snapshot or {}).get("tier") or "").upper(),
    }
    try:
        if not bool(CONFIG.get("V542_EXECUTION_PARITY_ENABLE", True)):
            return True, "disabled", ctx
        if candidate is None or not isinstance(snapshot, dict):
            _v542_record_preflight(symbol, False, "preflight.missing_candidate_or_snapshot", ctx)
            return False, "preflight.missing_candidate_or_snapshot", ctx
        if _v531_is_stablecoin(str(symbol)):
            _v542_record_preflight(symbol, False, "stablecoin_blocked", ctx)
            return False, "stablecoin_blocked", ctx
        if bool(CONFIG.get("V542_EXECUTION_PARITY_REQUIRE_FRESH_CANDIDATE", True)):
            age = _wall_age_sec(getattr(candidate, "generated_at_ms", None))
            ctx["candidate_age_sec"] = age
            max_age = float(CONFIG.get("V542_EXECUTION_PARITY_MAX_CANDIDATE_AGE_SEC", CONFIG.get("V45_CANDIDATE_MAX_AGE_SEC", 390.0)))
            if age is None:
                _v542_record_preflight(symbol, False, "freshness.unverifiable", ctx)
                return False, "freshness.unverifiable", ctx
            if age > max_age:
                _v542_record_preflight(symbol, False, "freshness.stale_candidate", ctx)
                return False, "freshness.stale_candidate", ctx

        # Snapshot context must be sufficiently canonical for the same prequalifier.
        if not all(snapshot.get(k) is not None for k in ("df_1h", "df_4h", "df_15m", "df_5m")):
            _v542_record_preflight(symbol, False, "preflight.snapshot_data_missing", ctx)
            return False, "preflight.snapshot_data_missing", ctx

        try:
            htf = snapshot.get("htf_strength")
            if htf is None:
                htf = _v453_htf_strength_from_snapshot(snapshot)
            htf = float(htf)
            if not math.isfinite(htf):
                raise ValueError("non_finite_htf")
            ctx["htf_strength"] = htf
        except Exception:
            _v542_record_preflight(symbol, False, "htf.unavailable", ctx)
            return False, "htf.unavailable", ctx

        # Use the exact canonical prequalification wrapper already used by the
        # GlobalOpportunityArbiter. No new policy rules are invented here.
        entry = float(getattr(candidate, "entry_ref", 0.0) or 0.0)
        sl = float(getattr(candidate, "sl_price", 0.0) or 0.0)
        risk = max(entry - sl, 0.0)
        tp1 = entry + float(getattr(candidate, "tp1_rr", 0.0) or 0.0) * risk
        tp2 = entry + float(getattr(candidate, "tp2_rr", 0.0) or 0.0) * risk
        tp3 = entry + float(getattr(candidate, "tp3_rr", 0.0) or 0.0) * risk
        ranked = RankedCandidate(
            candidate=candidate,
            composite=float(getattr(candidate, "engine_score", 0.0) or 0.0),
            tp1_abs=tp1,
            tp2_abs=tp2,
            tp3_abs=tp3,
        )
        _prequal_source_token = _V702_PREQUAL_SOURCE.set("preflight")
        try:
            ok, reason = _v453_prequalify(ranked, {str(symbol): snapshot})
        finally:
            _V702_PREQUAL_SOURCE.reset(_prequal_source_token)
        if not ok:
            # Keep the preflight reason verbatim. This is the same reason the
            # canonical arbiter already knows, not a translated heuristic.
            _v542_record_preflight(symbol, False, str(reason), ctx)
            return False, str(reason), ctx

        # v4.5.42 CRITICAL PARITY CLOSURE:
        # The live builder historically repeated an additional policy/HTF/tier
        # gate after global prequalification. Reuse that exact decision shape
        # here so SELECTED cannot be mistaken for LIVE-READY when that second
        # gate is already provably going to reject the same snapshot.
        try:
            family = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "PULLBACK").upper()
            mode = str(getattr(candidate, "strategy_mode", "") or family).upper()
            regime = str(snapshot.get("regime") or "").upper()
            local_regime = str(snapshot.get("local_regime") or "").upper()
            severity = str(snapshot.get("macro_severity", snapshot.get("bearish_severity", "")) or "").upper()
            tier = str(snapshot.get("tier") or "").upper()
            htf_strength = float(ctx.get("htf_strength"))
            _v43_meta = CanonicalStrategyPolicyRegistry.get(mode)
            _v45_l3 = _v45_rescue_level() >= 3 and _v45_strategy_rescue_allowed(mode, family)
            _bridge_ok = False
            _bridge_strength = htf_strength
            try:
                _bridge_ok, _bridge_strength, _bridge_ctx = _v518_neutral_local_htf_bridge(
                    snapshot.get("df_1h"), snapshot.get("df_4h"), snapshot.get("df_15m"), snapshot.get("df_5m"),
                    regime, local_regime, htf_strength, mode or family
                )
            except Exception:
                _bridge_ok = False
            if _bridge_ok:
                htf_strength = max(htf_strength, float(_bridge_strength))
                ctx["bridge_pass"] = True
                ctx["effective_htf_strength"] = htf_strength

            if _v43_meta is not None:
                if not bool(_v43_meta.get("enabled", True)):
                    _v542_record_preflight(symbol, False, "policy.strategy_disabled", ctx)
                    return False, "policy.strategy_disabled", ctx
                if regime == "BEARISH" and severity in {"BEARISH_NORMAL", "BEARISH_STRESSED", "NORMAL", "STRESSED"}:
                    _htf_floor = None
                else:
                    _htf_floor = float(_v43_meta.get("min_htf_strength_non_bearish", 55.0))
                    _htf_floor = _v457_htf_relief_floor(family, _htf_floor, regime, local_regime)
                _htf_floor = _v702_effective_htf_floor(family, mode, regime, local_regime, _htf_floor,
                                                      getattr(candidate, "features_snapshot", {}) or {})
                if _htf_floor is not None and htf_strength < _htf_floor and not (_v45_l3 or _bridge_ok):
                    ctx["effective_htf_floor"] = _htf_floor
                    _v542_record_preflight(symbol, False, "family_htf_strength_below_floor", ctx)
                    return False, "family_htf_strength_below_floor", ctx
                _min_rank = _FAMILY_RANK.get(str(_v43_meta.get("min_tier", "MID")), 2)
                _v697_tier_recovery = False
                try:
                    _tr = (getattr(candidate, "features_snapshot", {}) or {}).get("v692_tier_recovery") or {}
                    _v697_tier_recovery = bool(_tr.get("bounded", False)) and str(_tr.get("tier", tier) or "").upper() == str(tier or "").upper() and _v690_tier_allowed(family, mode, tier, canonical_score_to_01(getattr(candidate, "engine_score", 0.0), None), getattr(candidate, "features_snapshot", {}) or {})
                except Exception:
                    _v697_tier_recovery = False
                _a7_micro_tier_pass = _v702_a7_micro_handoff_allowed(candidate, snapshot, tier)
                if str(tier).upper() == "MICRO" and not _a7_micro_tier_pass:
                    _v542_record_preflight(symbol, False, "liquidity.micro_handoff_unverified", ctx)
                    return False, "liquidity.micro_handoff_unverified", ctx
                if _FAMILY_RANK.get(tier, -1) < _min_rank and not _v45_l3 and not _v697_tier_recovery and not _a7_micro_tier_pass:
                    _v542_record_preflight(symbol, False, "liquidity.family_tier_below_floor", ctx)
                    return False, "liquidity.family_tier_below_floor", ctx
                if _a7_micro_tier_pass:
                    ctx["v702_a7_micro_handoff"] = "PASS:BOOK_SPREAD_FEE_SCORE"
                    STATS["v702_a7_micro_jit_handoff_passes"] = int(STATS.get("v702_a7_micro_jit_handoff_passes", 0) or 0) + 1
                if _v697_tier_recovery:
                    ctx["bounded_tier_recovery"] = True
            else:
                _htf_floor = V425FamilyPolicyAdj.effective_htf_floor(family, regime, mode)
                _htf_floor = _v702_effective_htf_floor(family, mode, regime, local_regime, _htf_floor,
                                                      getattr(candidate, "features_snapshot", {}) or {})
                if _htf_floor is not None and htf_strength < float(_htf_floor) and not (_v45_l3 or _bridge_ok):
                    ctx["effective_htf_floor"] = float(_htf_floor)
                    _v542_record_preflight(symbol, False, "family_htf_strength_below_floor", ctx)
                    return False, "family_htf_strength_below_floor", ctx
                _v697_tier_recovery = False
                try:
                    _tr = (getattr(candidate, "features_snapshot", {}) or {}).get("v692_tier_recovery") or {}
                    _v697_tier_recovery = bool(_tr.get("bounded", False)) and str(_tr.get("tier", tier) or "").upper() == str(tier or "").upper() and _v690_tier_allowed(family, mode, tier, canonical_score_to_01(getattr(candidate, "engine_score", 0.0), None), getattr(candidate, "features_snapshot", {}) or {})
                except Exception:
                    _v697_tier_recovery = False
                _a7_micro_tier_pass = _v702_a7_micro_handoff_allowed(candidate, snapshot, tier)
                if str(tier).upper() == "MICRO" and not _a7_micro_tier_pass:
                    _v542_record_preflight(symbol, False, "liquidity.micro_handoff_unverified", ctx)
                    return False, "liquidity.micro_handoff_unverified", ctx
                if not V425FamilyPolicyAdj.liquidity_acceptable(family, tier, regime) and not _v45_l3 and not _v697_tier_recovery and not _a7_micro_tier_pass:
                    _v542_record_preflight(symbol, False, "liquidity.family_tier_below_floor", ctx)
                    return False, "liquidity.family_tier_below_floor", ctx
                if _a7_micro_tier_pass:
                    ctx["v702_a7_micro_handoff"] = "PASS:BOOK_SPREAD_FEE_SCORE"
                    STATS["v702_a7_micro_jit_handoff_passes"] = int(STATS.get("v702_a7_micro_jit_handoff_passes", 0) or 0) + 1
                if _v697_tier_recovery:
                    ctx["bounded_tier_recovery"] = True
        except Exception as _policy_exc:
            reason = f"preflight.final_policy_exception:{type(_policy_exc).__name__}"
            _v542_record_preflight(symbol, False, reason, ctx)
            return False, reason, ctx

        # Discovery reviewer is informative only; preserve the exact raw score
        # vs reviewed-quality distinction without feeding either into execution.
        try:
            if bool(CONFIG.get("V531_SCORE_REVIEW_ENABLE", True)):
                dctx = _v530_derive_context(str(symbol), candidate, snapshot)
                reviewed, _bd, _grade = _v531_review_discovery_score(
                    float(getattr(candidate, "engine_score", 0.0) or 0.0) * 100.0,
                    dctx,
                    str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "UNKNOWN"))
                )
                ctx["reviewed_score"] = float(reviewed)
        except Exception:
            _v647_record_suppressed_exception()

        _v542_record_preflight(symbol, True, "pass", ctx)
        return True, "pass", ctx
    except Exception as exc:
        reason = f"preflight.exception:{type(exc).__name__}"
        _v542_record_preflight(symbol, False, reason, ctx)
        logger.warning(f"[V542-PREFLIGHT] {symbol} fail-closed: {reason}")
        return False, reason, ctx


def v542_execution_coherence_line() -> str:
    """Compact non-blocking heartbeat line for the new parity closure."""
    try:
        reasons = STATS.get("v542_preflight_reasons") or {}
        top = sorted(reasons.items(), key=lambda kv: kv[1], reverse=True)[:int(CONFIG.get("V542_DISCOVERY_PREVIEW_TOP_REASONS", 3))]
        top_s = ",".join(f"{k}:{v}" for k,v in top) or "-"
        return (
            f"[V542-PARITY] pass={int(STATS.get('v542_preflight_pass',0) or 0)} "
            f"block={int(STATS.get('v542_preflight_block',0) or 0)} "
            f"last={STATS.get('v542_last_preflight_symbol','-')} "
            f"reason={STATS.get('v542_last_preflight_reason','-')} "
            f"top={top_s}"
        )
    except Exception:
        return "[V542-PARITY] unavailable"


# JIT defense-in-depth before the existing canonical SignalBuilder.
_orig_v542_build_and_route = SignalBuilder.build_and_route

async def _v542_build_and_route(exchange, symbol, market_data, preferred_candidate=None):
    """
    v4.5.45: JIT parity is advisory telemetry only.
    IMPORTANT: this wrapper MUST NOT become a second execution authority.
    The canonical SignalBuilder below remains responsible for every hard
    freshness/policy/HTF/structure/score/PreSend/balance/exposure/liquidity/
    precision/SL/execution decision.
    """
    _v702_selected_preflight_already_passed = False
    try:
        _ctxv = globals().get("_V702_SELECTED_PREFLIGHT_CTX")
        _selctx = _ctxv.get(None) if _ctxv is not None else None
        _v702_selected_preflight_already_passed = bool(
            isinstance(_selctx, dict)
            and preferred_candidate is not None
            and int(_selctx.get("candidate_id") or 0) == id(preferred_candidate)
            and str(_selctx.get("symbol") or "") == str(symbol or "")
            and (
                not str(_selctx.get("snapshot_id") or "")
                or str(_selctx.get("snapshot_id") or "") == str((market_data or {}).get("snapshot_id") or "")
            )
        )
        if _v702_selected_preflight_already_passed:
            STATS["v702_jit_preflight_skipped_selected"] = int(
                STATS.get("v702_jit_preflight_skipped_selected", 0) or 0
            ) + 1
            logger.debug("[V702-JIT-SKIP] selected preflight already passed for %s", symbol)
    except Exception:
        _v702_selected_preflight_already_passed = False

    if (not _v702_selected_preflight_already_passed
            and preferred_candidate is not None
            and bool(CONFIG.get("V542_EXECUTION_PARITY_ENABLE", True))
            and bool(CONFIG.get("V542_EXECUTION_PARITY_BLOCK_BEFORE_CANONICAL_BUILDER", True))):
        try:
            ok, reason, ctx = _v542_exact_policy_precheck(
                str(symbol), preferred_candidate, market_data or {}
            )
            # v4.5.45: preserve the full parity verdict for observability,
            # but never preempt the canonical builder with this duplicate gate.
            if ok:
                STATS["v542_jit_preflight_pass"] = int(
                    STATS.get("v542_jit_preflight_pass", 0) or 0
                ) + 1
                STATS["v545_jit_advisory_pass"] = int(
                    STATS.get("v545_jit_advisory_pass", 0) or 0
                ) + 1
                logger.debug(
                    f"[V545-JIT-ADVISORY-PASS] {symbol} "
                    f"family={ctx.get('family','')} mode={ctx.get('strategy_mode','')}"
                )
            else:
                STATS["v545_jit_advisory_block"] = int(
                    STATS.get("v545_jit_advisory_block", 0) or 0
                ) + 1
                reasons = STATS.get("v545_jit_advisory_reasons")
                if not isinstance(reasons, dict):
                    reasons = {}
                    STATS["v545_jit_advisory_reasons"] = reasons
                key = str(reason or "unknown")[:180]
                reasons[key] = int(reasons.get(key, 0) or 0) + 1
                hist = STATS.get("v545_jit_advisory_history")
                if not isinstance(hist, deque):
                    hist = deque(maxlen=max(32, int(CONFIG.get("V545_BOTTLENECK_HISTORY_MAX", 256))))
                    STATS["v545_jit_advisory_history"] = hist
                hist.append({
                    "ts": WALL_NOW(),
                    "symbol": str(symbol),
                    "reason": key,
                    "family": str(ctx.get("family","")),
                    "mode": str(ctx.get("strategy_mode","")),
                    "htf": ctx.get("htf_strength"),
                    "tier": ctx.get("tier"),
                    "age_sec": ctx.get("candidate_age_sec"),
                })
                logger.info(
                    f"[V545-JIT-ADVISORY] {symbol} "
                    f"family={ctx.get('family','')} mode={ctx.get('strategy_mode','')} "
                    f"htf={ctx.get('htf_strength','')} reason={key} "
                    f"-> canonical_builder_recheck=YES"
                )
        except Exception as exc:
            # Advisory telemetry failure is never allowed to alter execution.
            STATS["v545_jit_advisory_errors"] = int(
                STATS.get("v545_jit_advisory_errors", 0) or 0
            ) + 1
            logger.warning(
                f"[V545-JIT-ADVISORY-ERROR] {symbol} "
                f"type={type(exc).__name__} -> canonical_builder_recheck=YES"
            )
    return await _orig_v542_build_and_route(exchange, symbol, market_data, preferred_candidate)

SignalBuilder.build_and_route = staticmethod(_v542_build_and_route)


# Discovery remains knowledge-only, but its message now exposes a truthful
# live-preflight status from the SAME current scanner snapshot.
if bool(CONFIG.get("V542_DISCOVERY_SHOW_LIVE_PREFLIGHT", True)):
    _v542_old_discovery_notify = _v531_knowledge_notify_candidates

    def _v542_discovery_notify_candidates(candidates, snapshot=None):
        # The underlying notifier now performs the exact same preflight and
        # renders PASS/BLOCKED in the knowledge-only message.
        return _v542_old_discovery_notify(candidates, snapshot)

    _v531_knowledge_notify_candidates = _v542_discovery_notify_candidates
    _v530_knowledge_notify_candidates = _v542_discovery_notify_candidates
    _v528_knowledge_notify_candidates = _v542_discovery_notify_candidates


def _v542_self_test() -> Dict[str, Any]:
    """Offline regression checks for the execution-parity closure."""
    checks: Dict[str, bool] = {}
    try:
        checks["version_542"] = _v45_patch_at_least(42)
        checks["parity_enabled"] = bool(CONFIG.get("V542_EXECUTION_PARITY_ENABLE", True))
        checks["live_floor_preserved"] = float(CONFIG.get("MIN_LIVE_SCORE", 70.0)) >= 70.0 and float(CONFIG.get("V453_SCORE_FLOOR_MIN",70.0)) >= 70.0
        checks["no_new_execution_authority"] = (
            hasattr(PreSendGate, "evaluate") and hasattr(OrderExecutor, "submit_entry")
            and not hasattr(_v542_build_and_route, "place_order")
        )
        checks["fake_break_pullback_cap_operational"] = (
            float(CONFIG.get("V540_FAKE_BREAK_PULLBACK_SOFT_MAX_CHASE_ATR",1.20))
            <= float(CONFIG.get("FAKE_BREAK_SOFT_MAX_CHASE_ATR",1.80))
        )
        # Synthetic TUT-like policy state: BULLISH + PULLBACK + HTF 33 must stay blocked.
        checks["bullish_pullback_htf_floor_not_relaxed"] = (
            float(CONFIG.get("FAMILY_POLICY_PULLBACK",{}).get("min_htf_strength",48.0)) > 33.0
        )
        # Discovery must remain explicitly informational.
        try:
            _src_v542 = _v702_read_source_text()
        except Exception:
            _src_v542 = ""
        checks["discovery_is_knowledge_only"] = (
            "Knowledge-only. No live order is authorized, queued, or submitted" in _src_v542
        )
        checks["preflight_callable"] = callable(_v542_exact_policy_precheck)
        checks["heartbeat_line_callable"] = isinstance(v542_execution_coherence_line(), str)
    except Exception as exc:
        return {"pass": False, "checks": checks, "error": f"{type(exc).__name__}:{exc}"}
    return {"pass": all(bool(v) for v in checks.values()), "checks": checks}


# Add a compact parity line after the existing heartbeat chain without replacing
# any authoritative heartbeat logic.
_orig_v542_heartbeat = getattr(Telemetry, "emit_heartbeat", None)
if _orig_v542_heartbeat is not None and not getattr(Telemetry, "_v542_wrapped", False):
    async def _v542_heartbeat_wrapper(*args, **kwargs):
        result = await _orig_v542_heartbeat(*args, **kwargs)
        try:
            logger.info(v542_execution_coherence_line())
        except Exception:
            _v647_record_suppressed_exception()
        return result
    Telemetry.emit_heartbeat = staticmethod(_v542_heartbeat_wrapper)
    try:
        Telemetry._v542_wrapped = True
    except Exception:
        _v647_record_suppressed_exception()



