# v4.5.43 — EXECUTION-STARVATION-RECOVERY-HARDENED
# =============================================================================
CONFIG.update({
    "V543_ENABLE": True,

    # Dual lane: keep the original hard floors, but allow a bounded quality
    # recovery when the strict soft criteria are missed. This affects ONLY the
    # dedicated V537 dual engine candidate generator.
    "V543_DUAL_HTF_RELIEF_ENABLE": True,
    "V543_DUAL_MIN_1H_RSI": 38.0,
    "V543_DUAL_MIN_4H_RSI": 41.0,
    "V543_DUAL_EMA50_TOL_PCT": 0.015,

    # Balance recovery: the route-level recovery budget was raised from 1 to 2
    # attempts earlier in v4.5.43. These are only REAL-balance rechecks.
    "V543_BALANCE_RECOVERY_BACKOFF_BASE_SEC": 0.75,
    "V543_BALANCE_RECOVERY_BACKOFF_MAX_SEC": 3.0,

    # Telemetry-only burst alert. It never opens an entry.
    "V543_EXECUTION_BLOCKER_ALERT_ENABLE": True,
    "V543_EXECUTION_BLOCKER_ALERT_THRESHOLD": 5,
    "V543_EXECUTION_BLOCKER_ALERT_COOLDOWN_SEC": 900.0,

    # Keep the intentionally conservative network/CB semantics.
    "V543_NETWORK_TIMEOUT_RETRY": False,
    "V543_TIGHTEN_FAILED_SEND_CB": False,
})


def _v543_relaxed_htf_quality(df_1h, df_4h):
    """
    v4.5.43 bounded recovery around V537's strict HTF quality check.

    Important:
      * Calls the original strict test first.
      * Only recovers the 'soft quality' miss; hard RSI floors and strong
        bearish-body checks remain absolute.
      * Does not change family HTF floors or any canonical prequalification.
      * Fail-closed on missing/non-finite data.
    """
    strict_ok, strict_ctx = _v543_orig_htf_quality(df_1h, df_4h)
    if strict_ok or not bool(CONFIG.get("V543_DUAL_HTF_RELIEF_ENABLE", True)):
        return strict_ok, strict_ctx
    if not isinstance(strict_ctx, dict) or str(strict_ctx.get("reason", "")) != "htf_quality_not_met":
        return strict_ok, strict_ctx

    try:
        if df_1h is None or df_4h is None or len(df_1h) < 60 or len(df_4h) < 60:
            return False, strict_ctx

        e50_1 = float(Indicators.ema(df_1h["close"], 50).iloc[-2])
        e50_4 = float(Indicators.ema(df_4h["close"], 50).iloc[-2])
        r1 = float(_v537_closed_rsi(df_1h))
        r4 = float(_v537_closed_rsi(df_4h))
        c1 = float(df_1h["close"].iloc[-2]); o1 = float(df_1h["open"].iloc[-2])
        h1 = float(df_1h["high"].iloc[-2]); l1 = float(df_1h["low"].iloc[-2])
        c4 = float(df_4h["close"].iloc[-2]); o4 = float(df_4h["open"].iloc[-2])
        h4 = float(df_4h["high"].iloc[-2]); l4 = float(df_4h["low"].iloc[-2])

        if not all(math.isfinite(x) for x in (e50_1, e50_4, r1, r4, c1, o1, h1, l1, c4, o4, h4, l4)):
            return False, {**strict_ctx, "reason": "htf_non_finite"}

        # Absolute safety floors remain exactly the V537 hard floors.
        if r1 < float(CONFIG.get("V537_HARD_1H_RSI_FLOOR", 34.0)):
            return False, strict_ctx
        if r4 < float(CONFIG.get("V537_HARD_4H_RSI_FLOOR", 38.0)):
            return False, strict_ctx

        rng1 = max(1e-12, h1 - l1)
        rng4 = max(1e-12, h4 - l4)
        bear_body1 = max(0.0, o1 - c1) / rng1
        bear_body4 = max(0.0, o4 - c4) / rng4

        # The existing strong-bearish-body blockers remain untouched.
        if bear_body1 >= float(CONFIG.get("V537_HARD_BEARISH_BODY_RATIO_1H", 0.65)) and c1 < e50_1:
            return False, strict_ctx
        if bear_body4 >= float(CONFIG.get("V537_HARD_BEARISH_BODY_RATIO_4H", 0.70)) and c4 < e50_4:
            return False, strict_ctx

        min_r1 = float(CONFIG.get("V543_DUAL_MIN_1H_RSI", 38.0))
        min_r4 = float(CONFIG.get("V543_DUAL_MIN_4H_RSI", 41.0))
        tol = float(CONFIG.get("V543_DUAL_EMA50_TOL_PCT", 0.015))
        if tol <= 0 or tol > 0.025:
            return False, strict_ctx

        ok1 = r1 >= min_r1 and c1 >= e50_1 * (1.0 - tol)
        ok4 = r4 >= min_r4 and c4 >= e50_4 * (1.0 - tol)
        if not (ok1 and ok4):
            return False, strict_ctx

        ctx = dict(strict_ctx)
        ctx.update({
            "reason": "ok_relaxed_v543",
            "v543_relief": True,
            "rsi1h": r1, "rsi4h": r4,
            "close1h": c1, "ema50_1h": e50_1,
            "close4h": c4, "ema50_4h": e50_4,
            "v543_ema_tol_pct": tol,
        })
        STATS["v543_dual_htf_relief_pass"] = int(STATS.get("v543_dual_htf_relief_pass", 0) or 0) + 1
        return True, ctx
    except Exception:
        return False, strict_ctx


# Patch exactly one method: preserve V537's original implementation and add
# a bounded, fail-closed recovery wrapper around it.
_v543_orig_htf_quality = UniversalDualConfirmationEntry._htf_quality
UniversalDualConfirmationEntry._htf_quality = staticmethod(_v543_relaxed_htf_quality)


