_v543_orig_record_execution_blocker = _v538_record_execution_blocker
_V543_BLOCKER_LAST_ALERT: Dict[str, float] = {}


def _v543_record_execution_blocker(symbol: Optional[str], reason: str, stage: str = "canonical") -> None:
    try:
        _v543_orig_record_execution_blocker(symbol, reason, stage)
    except Exception:
        _v647_record_suppressed_exception()
    if not bool(CONFIG.get("V543_EXECUTION_BLOCKER_ALERT_ENABLE", True)):
        return
    try:
        key = str(reason or "unknown")
        counts = STATS.setdefault("v543_blocker_counts", defaultdict(int))
        counts[key] += 1
        threshold = max(1, int(CONFIG.get("V543_EXECUTION_BLOCKER_ALERT_THRESHOLD", 5)))
        now = MONO_NOW()
        last = float(_V543_BLOCKER_LAST_ALERT.get(key, 0.0) or 0.0)
        cooldown = max(0.0, float(CONFIG.get("V543_EXECUTION_BLOCKER_ALERT_COOLDOWN_SEC", 900.0)))
        if counts[key] >= threshold and (now - last) >= cooldown:
            _V543_BLOCKER_LAST_ALERT[key] = now
            STATS["v543_blocker_alerts"] = int(STATS.get("v543_blocker_alerts", 0) or 0) + 1
            logger.warning(
                f"[V543-EXEC-BLOCKER-ALERT] reason={key} count={counts[key]} "
                f"stage={stage} symbol={symbol or '?'}"
            )
    except Exception:
        _v647_record_suppressed_exception()


_v538_record_execution_blocker = _v543_record_execution_blocker


def v543_execution_recovery_line() -> str:
    try:
        counts = STATS.get("v543_blocker_counts") or {}
        top = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)[:3]
        top_s = ",".join(f"{k}:{v}" for k, v in top) or "-"
        return (
            f"[V543-RECOVERY] dual_htf_relief={int(STATS.get('v543_dual_htf_relief_pass',0) or 0)} "
            f"balance_real_retry={int(STATS.get('v543_balance_real_retry',0) or 0)} "
            f"balance_untrusted={int(STATS.get('v543_balance_recovery_untrusted',0) or 0)} "
            f"alerts={int(STATS.get('v543_blocker_alerts',0) or 0)} top={top_s}"
        )
    except Exception:
        return "[V543-RECOVERY] unavailable"


