_V549_SPREAD_CONTEXT = contextvars.ContextVar("v549_spread_context", default=None)
_V549_MICRO_CONTEXT = contextvars.ContextVar("v549_micro_context", default=None)


def _v549_ultra_elite_spread_allow(spread_pct: Optional[float], tier: str,
                                   ctx: Optional[Dict[str, Any]]) -> Tuple[bool, str]:
    try:
        if not bool(CONFIG.get("V549_ULTRA_ELITE_SPREAD_ENABLE", True)):
            return False, "v549_disabled"
        if spread_pct is None or not math.isfinite(float(spread_pct)):
            return False, "v549_spread_invalid"
        c = dict(ctx or {})
        score = float(c.get("score", 0.0))
        reviewed = float(c.get("reviewed_score", score))
        htf = float(c.get("htf", 0.0))
        vol = float(c.get("vol", 0.0))
        rs = float(c.get("rs", 0.0))
        chase = float(c.get("chase", 99.0))
        t = str(tier or c.get("tier", "") or "").upper()
        if t not in {"MID", "LARGE"}:
            return False, "v549_tier_not_allowed"
        vals = (score, reviewed, htf, vol, rs, chase, float(spread_pct))
        if not all(math.isfinite(x) for x in vals):
            return False, "v549_nonfinite_quality"
        if score < float(CONFIG.get("V549_ULTRA_ELITE_MIN_ENGINE_SCORE", 95.0)):
            return False, "v549_engine"
        if reviewed < float(CONFIG.get("V549_ULTRA_ELITE_MIN_REVIEWED_SCORE", 90.0)):
            return False, "v549_reviewed"
        if htf < float(CONFIG.get("V549_ULTRA_ELITE_MIN_HTF", 90.0)):
            return False, "v549_htf"
        if vol < float(CONFIG.get("V549_ULTRA_ELITE_MIN_VOLUME_RATIO", 1.0)):
            return False, "v549_volume"
        if rs < float(CONFIG.get("V549_ULTRA_ELITE_MIN_RS", -0.0015)):
            return False, "v549_rs"
        if chase > float(CONFIG.get("V549_ULTRA_ELITE_MAX_CHASE_ATR", 0.90)):
            return False, "v549_chase"

        base = float(
            (CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}).get(
                t, CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15)
            )
        )
        extra = float(
            (CONFIG.get("V549_ULTRA_ELITE_EXTRA_PCT", {}) or {}).get(t, 0.0)
        )
        absolute = float(
            (CONFIG.get("V549_ULTRA_ELITE_ABSOLUTE_MAX_PCT", {}) or {}).get(t, 0.0)
        )
        ceiling = min(base + extra, absolute)
        if extra <= 0.0 or absolute <= 0.0:
            return False, "v549_no_ceiling"
        if float(spread_pct) <= ceiling:
            STATS["v549_ultra_elite_spread_reliefs"] = int(
                STATS.get("v549_ultra_elite_spread_reliefs", 0) or 0
            ) + 1
            return True, (
                f"v549_ultra_elite_spread_relief:{float(spread_pct):.4f}%"
                f"<=ceil={ceiling:.4f}%"
            )
        return False, f"v549_over_cap:{float(spread_pct):.4f}%>ceil={ceiling:.4f}%"
    except Exception as exc:
        STATS["v549_ultra_elite_spread_errors"] = int(
            STATS.get("v549_ultra_elite_spread_errors", 0) or 0
        ) + 1
        return False, f"v549_exception:{type(exc).__name__}"


