def _v549_pullback_close_above_ema20(df_5m) -> bool:
    try:
        if not bool(CONFIG.get("V549_PULLBACK_CLOSE_ABOVE_EMA20_RECOVERY_ENABLE", True)):
            return False
        if df_5m is None or len(df_5m) < 25:
            return False
        ema20 = Indicators.ema(df_5m["close"], CONFIG["EMA_FAST"])
        close_c = float(df_5m["close"].iloc[-2])
        ema_c = float(ema20.iloc[-2])
        return bool(math.isfinite(close_c) and math.isfinite(ema_c) and close_c > ema_c)
    except Exception:
        return False


def _v549_pullback_recovery_qualified(candidate: Any, snapshot: Optional[Dict[str, Any]]) -> bool:
    try:
        if candidate is None:
            return False
        ctx = _v540_candidate_ctx(candidate, snapshot or {})
        score = float(ctx.get("score", 0.0))
        reviewed = float(ctx.get("reviewed_score", score))
        htf = float(ctx.get("htf", 0.0))
        vol = float(ctx.get("vol", 0.0))
        rs = float(ctx.get("rs", 0.0))
        chase = float(ctx.get("chase", 99.0))
        tier = str(ctx.get("tier", "") or "").upper()
        if score < float(CONFIG.get("V549_PULLBACK_RECOVERY_MIN_ENGINE_SCORE", 96.0)):
            return False
        if reviewed < float(CONFIG.get("V549_PULLBACK_RECOVERY_MIN_REVIEWED_SCORE", 90.0)):
            return False
        if htf < float(CONFIG.get("V549_PULLBACK_RECOVERY_MIN_HTF", 95.0)):
            return False
        if vol < float(CONFIG.get("V549_PULLBACK_RECOVERY_MIN_VOLUME_RATIO", 0.60)):
            return False
        if rs < float(CONFIG.get("V549_PULLBACK_RECOVERY_MIN_RS", -0.0030)):
            return False
        if chase > float(CONFIG.get("V549_PULLBACK_RECOVERY_MAX_CHASE_ATR", 0.50)):
            return False
        if tier not in {str(x).upper() for x in CONFIG.get("V549_PULLBACK_RECOVERY_ALLOWED_TIERS", ())}:
            return False
        return True
    except Exception:
        return False


_orig_v520_microstructure_parity_v549 = _v520_microstructure_parity


def _v549_microstructure_parity(df_5m, family, mode, zone, bos_confirmed=False, candidate_features=None):
    ok, ctx = _orig_v520_microstructure_parity_v549(
        df_5m, family, mode, zone, bos_confirmed=bos_confirmed, candidate_features=candidate_features
    )
    if ok:
        return ok, ctx
    try:
        if str(family or "").upper() not in {"PULLBACK", "MTF_PULLBACK"}:
            return ok, ctx
        if str(ctx.get("reason", "")) not in {"pullback_micro_uptrend", "PULLBACK_REJECT", "structural.micro_parity"}:
            return ok, ctx
        qctx = _V549_MICRO_CONTEXT.get() or {}
        cand = qctx.get("candidate")
        snapshot = qctx.get("snapshot") or {}
        if not _v549_pullback_recovery_qualified(cand, snapshot):
            return ok, ctx

        _close_above = _v549_pullback_close_above_ema20(df_5m)
        _atr = None
        try:
            _atr = float(Indicators.atr(df_5m, CONFIG["ATR_PERIOD"]).iloc[-2])
        except Exception:
            _atr = None
        _ema50 = None
        try:
            _ema50 = float(df_5m["close"].ewm(span=50,adjust=False).mean().iloc[-2])
        except Exception:
            _ema50 = None
        _shallow_or_strong = _v565_structural_recovery_candidate(
            cand,
            close_price=float(df_5m["close"].iloc[-2]),
            ema50=_ema50,
            chase_atr=(
                max(
                    0.0,
                    (float(df_5m["close"].iloc[-2]) -
                     float(df_5m["close"].ewm(span=20,adjust=False).mean().iloc[-2]))
                    / _atr
                )
                if _atr and math.isfinite(_atr) and _atr > 0 else None
            ),
        )
        if not (_close_above or _shallow_or_strong):
            return ok, ctx
        STATS["v549_pullback_ema20_recoveries"] = int(
            STATS.get("v549_pullback_ema20_recoveries", 0) or 0
        ) + 1
        return True, {
            **dict(ctx or {}),
            "reason": "pullback_micro_uptrend_recovered_close_above_ema20",
            "close_above_ema20": True,
        }
    except Exception:
        return ok, ctx


_v520_microstructure_parity = _v549_microstructure_parity


