_orig_build_and_route_v549 = SignalBuilder.build_and_route


@staticmethod
async def _v549_build_and_route(exchange, symbol: str, market_data: Dict,
                                preferred_candidate: Optional[StrategyCandidate] = None):
    tok_spread = None
    tok_micro = None
    try:
        c = preferred_candidate
        ctx = _v540_candidate_ctx(c, market_data or {})
        try:
            _spread_fields = globals().get("_v702_a34_spread_context_fields")
            if callable(_spread_fields):
                ctx.update(_spread_fields(c, market_data or {}, ctx))
        except Exception:
            # Additional Shadow facts are non-authoritative and cannot block routing.
            pass
        tok_spread = _V549_SPREAD_CONTEXT.set({
            **ctx, "symbol": str(symbol), "ts": MONO_NOW()
        })
        tok_micro = _V549_MICRO_CONTEXT.set({
            "candidate": c,
            "snapshot": dict(market_data or {}),
        })
        return await _orig_build_and_route_v549(
            exchange, symbol, market_data, preferred_candidate=preferred_candidate
        )
    finally:
        try:
            if tok_micro is not None:
                _V549_MICRO_CONTEXT.reset(tok_micro)
        except Exception:
            _v647_record_suppressed_exception()
        try:
            if tok_spread is not None:
                _V549_SPREAD_CONTEXT.reset(tok_spread)
        except Exception:
            _v647_record_suppressed_exception()


SignalBuilder.build_and_route = _v549_build_and_route


# ---------------------------------------------------------------------------
# V549 Pending quality tail: narrow extension below the old 90-point reviewed
# floor, strictly gated by raw score / HTF / volume / chase / tier.
# ---------------------------------------------------------------------------
_orig_v546_register_pending_v549 = _v546_register_pending_candidate


def _v549_register_pending_candidate(candidate: Any, reviewed_score: float,
                                     preflight_ok: bool, preflight_reason: str,
                                     snapshot: Optional[Dict[str, Any]] = None) -> None:
    try:
        rev = float(reviewed_score or 0.0)
        if rev >= float(CONFIG.get("V546_PENDING_HANDOFF_MIN_REVIEWED_SCORE", 90.0)):
            return _orig_v546_register_pending_v549(
                candidate, reviewed_score, preflight_ok, preflight_reason, snapshot
            )
        if not bool(CONFIG.get("V549_PENDING_QUALITY_TAIL_ENABLE", True)):
            return
        if not preflight_ok:
            return
        c = _v540_candidate_ctx(candidate, snapshot or {})
        if rev < float(CONFIG.get("V549_PENDING_QUALITY_TAIL_MIN_REVIEWED", 88.0)):
            return
        if float(c.get("score", 0.0)) < float(CONFIG.get("V549_PENDING_QUALITY_TAIL_MIN_ENGINE", 97.0)):
            return
        if float(c.get("htf", 0.0)) < float(CONFIG.get("V549_PENDING_QUALITY_TAIL_MIN_HTF", 95.0)):
            return
        if float(c.get("vol", 0.0)) < float(CONFIG.get("V549_PENDING_QUALITY_TAIL_MIN_VOLUME_RATIO", 1.0)):
            return
        if float(c.get("chase", 99.0)) > float(CONFIG.get("V549_PENDING_QUALITY_TAIL_MAX_CHASE_ATR", 0.90)):
            return
        if str(c.get("tier", "")).upper() not in {str(x).upper() for x in CONFIG.get("V549_PENDING_QUALITY_TAIL_ALLOWED_TIERS", ())}:
            return
        # Temporarily use the legacy registrar's storage contract without
        # globally lowering its threshold.
        old_floor = CONFIG.get("V546_PENDING_HANDOFF_MIN_REVIEWED_SCORE", 90.0)
        CONFIG["V546_PENDING_HANDOFF_MIN_REVIEWED_SCORE"] = 0.0
        try:
            _orig_v546_register_pending_v549(
                candidate, reviewed_score, preflight_ok, preflight_reason, snapshot
            )
        finally:
            CONFIG["V546_PENDING_HANDOFF_MIN_REVIEWED_SCORE"] = old_floor
        STATS["v549_pending_quality_tail_registered"] = int(
            STATS.get("v549_pending_quality_tail_registered", 0) or 0
        ) + 1
    except Exception:
        _v647_record_suppressed_exception()


_v546_register_pending_candidate = _v549_register_pending_candidate


# ---------------------------------------------------------------------------
# V549 Discovery alert de-dup: same symbol/family cannot spam within 15 minutes.
# ---------------------------------------------------------------------------
_V549_DISCOVERY_SEEN = {}


def _v549_knowledge_notify_candidates(candidates: List[StrategyCandidate],
                                      snapshot: Optional[Dict[str, Any]] = None) -> None:
    try:
        now = MONO_NOW()
        filtered = []
        for c in list(candidates or []):
            sym = str(getattr(c, "symbol", "") or "")
            fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "UNKNOWN").upper()
            if not sym:
                continue
            if _v565_symbol_structural_quarantined(sym):
                STATS["v565_discovery_structural_quarantine_skips"] = int(
                    STATS.get("v565_discovery_structural_quarantine_skips", 0) or 0
                ) + 1
                continue
            key = f"{sym}|{fam}"
            last = float(_V549_DISCOVERY_SEEN.get(key, 0.0) or 0.0)
            if now - last < float(CONFIG.get("V549_DISCOVERY_SYMBOL_DEDUP_SEC", 900.0)):
                STATS["v549_discovery_symbol_dedup"] = int(
                    STATS.get("v549_discovery_symbol_dedup", 0) or 0
                ) + 1
                continue
            _V549_DISCOVERY_SEEN[key] = now
            filtered.append(c)
        return _orig_v528_knowledge_notify_candidates(
            filtered, snapshot
        )
    except Exception:
        return _orig_v528_knowledge_notify_candidates(candidates, snapshot)


_orig_v528_knowledge_notify_candidates = globals().get("_v528_knowledge_notify_candidates")
if callable(_orig_v528_knowledge_notify_candidates):
    _v528_knowledge_notify_candidates = _v549_knowledge_notify_candidates


