_orig_telemetry_emit_heartbeat_v549 = Telemetry.emit_heartbeat


def _v549_heartbeat_line() -> str:
    try:
        top = []
        cycle_counts = {
            "builder_block": int(STATS.get("v547_cycle_builder_blocks", 0) or 0),
            "score": int(STATS.get("v547_cycle_score_blocks", 0) or 0),
            "liquidity": int(STATS.get("v547_cycle_liquidity_blocks", 0) or 0),
            "pre_send": int(STATS.get("v547_cycle_pre_send_blocks", 0) or 0),
            "balance": int(STATS.get("v547_cycle_balance_blocks", 0) or 0),
            "structure": int(STATS.get("v547_cycle_structure_blocks", 0) or 0),
            "htf": int(STATS.get("v547_cycle_htf_blocks", 0) or 0),
            "execution": int(STATS.get("v547_cycle_execution_blocks", 0) or 0),
            "other": int(STATS.get("v547_cycle_other_blocks", 0) or 0),
        }
        for k, v in sorted(cycle_counts.items(), key=lambda kv: (-kv[1], kv[0])):
            if v:
                top.append(f"{k}:{v}")
        top_s = ",".join(top[:int(CONFIG.get("V549_HEARTBEAT_TOP_BLOCKERS", 5))]) or "-"
        last_reason = str(STATS.get("v534_last_route_block_reason", "") or "none")
        last_stage = str(STATS.get("v534_last_route_block_stage", "") or "unknown")
        return (
            f"[V549-EXEC] selected={int(STATS.get('v547_cycle_selected_to_exec',0) or 0)} "
            f"pending={int(STATS.get('v547_cycle_pending_to_exec',0) or 0)} "
            f"reserve={int(STATS.get('v547_cycle_reserve_to_exec',0) or 0)} "
            f"builder={int(STATS.get('v547_cycle_builder_calls',0) or 0)} "
            f"builder_block={int(STATS.get('v547_cycle_builder_blocks',0) or 0)} "
            f"live_ready={int(STATS.get('v547_cycle_live_ready_delta',0) or 0)} "
            f"queued={int(STATS.get('v547_cycle_queued_delta',0) or 0)} "
            f"sent={int(STATS.get('v547_cycle_sent_delta',0) or 0)} "
            f"blocks={top_s} last_stage={last_stage} last_reason={last_reason}"
        )
    except Exception:
        return "[V549-EXEC] unavailable"


