# =============================================================================
# v4.5.69 FINAL — SELECTED->QUEUE STARVATION ROOT-CAUSE / VERSION COHERENCE
# =============================================================================
# Live telemetry root cause addressed from the 2026-08-27 run:
#   GEN=159, PRE=37, RANK=37, SEL=20, Q=0, S=0 while aggregate
#   SCORE/STRUCTURE/LIQUIDITY rejects were still counted over the wider window.
#
# The old starvation classifier correctly measured windowed upstream pressure,
# but it could mislabel a downstream SELECTED->QUEUE choke as SCORE whenever
# aggregate score rejects were numerically larger than the current execution
# blocker. The live router already had cycle-local attempt telemetry; the
# classifier simply was not consulting it first.
#
# v4.5.69 closes that observability gap without weakening a single execution
# gate:
#   1) capture cycle-local PRE_SEND / BALANCE / STRUCTURE / HTF blockers;
#   2) when selected/pending/reserve candidates were actually attempted and
#      Q=S=0, classify from those same-attempt blockers FIRST;
#   3) preserve the existing SYSTEM / NO_OPP / upstream-window fallback rules;
#   4) expose the exact selected-stage reason in telemetry;
#   5) restore CONFIG version identity after a stale legacy CONFIG.update()
#      later in the source had overwritten it to 4.5.54.
#
# IMPORTANT: this patch is telemetry / diagnosis only. It does not lower score,
# HTF, liquidity, structure, balance, PreSend, SL, exposure, or execution gates.
# =============================================================================

CONFIG.update({
    "V569_SELECTED_STAGE_PRIORITY_ENABLE": True,
    "V569_ALERT_INCLUDE_SELECTED_STAGE": True,
})
# The source contains a legacy late CONFIG.update() with a stale SCRIPT_VERSION.
# Make the runtime configuration agree with the canonical module version.
CONFIG["SCRIPT_VERSION"] = SCRIPT_VERSION
CONFIG["SCRIPT_VERSION_FAMILY"] = SCRIPT_VERSION_FAMILY

# v4.5.76 — final canonicalization: legacy flags cannot disable automatic SL
# protection in any live target-only/fallback path. These keys are retained for
# backward compatibility but their semantics are now safety-fixed.
if bool(CONFIG.get("V576_CANONICALIZE_LEGACY_SL_POLICY", True)):
    CONFIG["SL_FAILURE_TARGET_ONLY_DISABLE_SOFTWARE_AUTO_EXIT"] = False
    CONFIG["V574_TARGET_ONLY_KEEP_SOFTWARE_SL"] = True
    CONFIG["V574_SOFTWARE_SL_REQUIRE_ARMED_FOR_OPEN_TRADE"] = True
    CONFIG["V576_REQUIRE_SOFTWARE_SL_FOR_TARGET_ONLY"] = True
    CONFIG["V576_SAFETY_HAZARD_RETRY_ON_AMBIGUOUS"] = False
    # The final safety override requires BOTH explicit switches to be true.
    CONFIG["V571_ALLOW_SAFETY_HAZARD_MARKET_SELL"] = bool(
        CONFIG.get("V571_ALLOW_SAFETY_HAZARD_MARKET_SELL", False)
    ) and bool(CONFIG.get("V574_ALLOW_SAFETY_HAZARD_MARKET_SELL", False))


def _v569_selected_stage_verdict(
    *,
    selected_to_exec: int,
    pending_to_exec: int,
    reserve_to_exec: int,
    queued: int,
    sent: int,
    pre_send_blocks: int,
    balance_blocks: int,
    structure_blocks: int,
    htf_blocks: int,
    liquidity_blocks: int,
    score_blocks: int,
    execution_blocks: int,
    other_blocks: int,
) -> Tuple[Optional[str], str]:
    """Return (public_mode, exact_reason) for current-cycle selected-stage choke.

    The public mode intentionally reuses the existing starvation vocabulary.
    Exact stage detail is kept separately for telemetry, so dashboards do not
    need a new mode enum just to distinguish PreSend vs Balance.
    """
    try:
        attempted = max(0, int(selected_to_exec)) + max(0, int(pending_to_exec)) + max(0, int(reserve_to_exec))
        if attempted <= 0 or int(queued) > 0 or int(sent) > 0:
            return None, ""

        buckets = {
            "pre_send": max(0, int(pre_send_blocks)),
            "balance": max(0, int(balance_blocks)),
            "structure": max(0, int(structure_blocks)),
            "htf": max(0, int(htf_blocks)),
            "liquidity": max(0, int(liquidity_blocks)),
            "score": max(0, int(score_blocks)),
            "execution": max(0, int(execution_blocks)),
            "other": max(0, int(other_blocks)),
        }
        positive = [(k, v) for k, v in buckets.items() if v > 0]
        if not positive:
            return None, "selected_no_block_attribution"

        # The selected-stage ledger is already scoped to the candidates that
        # actually reached the execution handoff. Therefore stage precedence
        # is more informative than raw counts: a later hard gate can coexist
        # with upstream score/HTF rejects, but those upstream rejects did not
        # explain why the already-selected attempt failed to queue.
        stage_groups = (
            ("EXECUTION", ("pre_send", "balance", "execution", "other")),
            ("STRUCTURE", ("structure",)),
            ("LIQUIDITY", ("liquidity",)),
            ("HTF", ("htf",)),
            ("SCORE", ("score",)),
        )
        reason = ""
        mode = ""
        for _mode, _names in stage_groups:
            _present = [(name, buckets[name]) for name in _names if buckets.get(name, 0) > 0]
            if _present:
                _tie = {name: idx for idx, name in enumerate(_names)}
                reason = max(_present, key=lambda kv: (kv[1], -_tie[kv[0]]))[0]
                mode = _mode
                break
        if not reason:
            return None, "selected_no_block_attribution"

        if reason == "structure":
            mode = "STRUCTURE"
        elif reason == "liquidity":
            mode = "LIQUIDITY"
        elif reason == "htf":
            mode = "HTF"
        elif reason == "score":
            mode = "SCORE"
        else:
            mode = "EXECUTION"
        return mode, reason
    except Exception:
        return None, "selected_stage_classifier_exception"


_orig_v453_classify_v569 = V453StarvationClassifier.classify


def _v569_classify_v453(cls) -> str:
    """Selected-stage-first wrapper around the existing fail-closed classifier."""
    try:
        # Let the original classifier establish SYSTEM / normal safety state
        # first. This wrapper must never hide a hard system hazard.
        base = _orig_v453_classify_v569()
        if base == "SYSTEM":
            STATS["v569_selected_stage_mode"] = "SYSTEM"
            STATS["v569_selected_stage_reason"] = "system_hazard"
            return base

        if not bool(CONFIG.get("V569_SELECTED_STAGE_PRIORITY_ENABLE", True)):
            return base

        mode, reason = _v569_selected_stage_verdict(
            selected_to_exec=int(STATS.get("v547_cycle_selected_to_exec", 0) or 0),
            pending_to_exec=int(STATS.get("v547_cycle_pending_to_exec", 0) or 0),
            reserve_to_exec=int(STATS.get("v547_cycle_reserve_to_exec", 0) or 0),
            queued=int(STATS.get("v547_cycle_queued_delta", 0) or 0),
            sent=int(STATS.get("v547_cycle_sent_delta", 0) or 0),
            pre_send_blocks=int(STATS.get("v547_cycle_pre_send_blocks", 0) or 0),
            balance_blocks=int(STATS.get("v547_cycle_balance_blocks", 0) or 0),
            structure_blocks=int(STATS.get("v547_cycle_structure_blocks", 0) or 0),
            htf_blocks=int(STATS.get("v547_cycle_htf_blocks", 0) or 0),
            liquidity_blocks=int(STATS.get("v547_cycle_liquidity_blocks", 0) or 0),
            score_blocks=int(STATS.get("v547_cycle_score_blocks", 0) or 0),
            execution_blocks=int(STATS.get("v547_cycle_execution_blocks", 0) or 0),
            other_blocks=int(STATS.get("v547_cycle_other_blocks", 0) or 0),
        )
        STATS["v569_selected_stage_mode"] = str(mode or "")
        STATS["v569_selected_stage_reason"] = str(reason or "")
        STATS["v569_selected_stage_attempts"] = (
            int(STATS.get("v547_cycle_selected_to_exec", 0) or 0)
            + int(STATS.get("v547_cycle_pending_to_exec", 0) or 0)
            + int(STATS.get("v547_cycle_reserve_to_exec", 0) or 0)
        )
        if mode:
            logger.warning(
                "[V569-STARV-ROOT] selected_stage=%s mode=%s attempts=%d queued=%d sent=%d",
                reason,
                mode,
                int(STATS.get("v569_selected_stage_attempts", 0) or 0),
                int(STATS.get("v547_cycle_queued_delta", 0) or 0),
                int(STATS.get("v547_cycle_sent_delta", 0) or 0),
            )
            return mode
        return base
    except Exception as exc:
        # Telemetry wrapper failure must never become a new blocker.
        STATS["v569_selected_stage_mode"] = ""
        STATS["v569_selected_stage_reason"] = f"wrapper_exception:{type(exc).__name__}"
        return _orig_v453_classify_v569()


V453StarvationClassifier.classify = classmethod(_v569_classify_v453)


def _v569_starvation_telemetry_line() -> str:
    try:
        return (
            f"[V569-STARV] attempts={int(STATS.get('v569_selected_stage_attempts',0) or 0)} "
            f"mode={STATS.get('v569_selected_stage_mode','-') or '-'} "
            f"stage={STATS.get('v569_selected_stage_reason','-') or '-'} "
            f"pre_send={int(STATS.get('v547_cycle_pre_send_blocks',0) or 0)} "
            f"balance={int(STATS.get('v547_cycle_balance_blocks',0) or 0)} "
            f"structure={int(STATS.get('v547_cycle_structure_blocks',0) or 0)} "
            f"htf={int(STATS.get('v547_cycle_htf_blocks',0) or 0)}"
        )
    except Exception:
        return "[V569-STARV] unavailable"


_orig_v422_task_v569 = V422StarvationAlerter.task


async def _v569_v422_task(cls):
    """Wrap the existing alert task so selected-stage detail is emitted after classify."""
    # Keep the original task fully intact; V453 classify now supplies the
    # corrected mode. A lightweight background emitter would risk duplicate
    # alerts, so we only rely on the V453 wrapper + heartbeat telemetry here.
    return await _orig_v422_task_v569()


