def _v580_pullback_coherence_self_test() -> Dict[str, Any]:
    """Offline acceptance tests for the complete v4.5.80 PULLBACK closure."""
    checks: Dict[str, bool] = {}
    try:
        # Synthetic closed candles: two consecutive higher lows and a modest
        # retracement around a valid zone. No network/exchange access.
        import pandas as pd
        rows = []
        base = 100.0
        for i in range(30):
            close = base + 0.10 * i
            low = close - 0.60 - (0.02 if i < 10 else 0.0)
            high = close + 0.50
            op = close - 0.15
            rows.append({"open": op, "high": high, "low": low, "close": close,
                         "volume": 1000.0})
        # Last closed bars encode a higher-low sequence.
        rows[-4]["low"] = 101.00
        rows[-3]["low"] = 101.10
        rows[-2]["low"] = 101.25
        df = pd.DataFrame(rows)
        df.index = pd.date_range("2026-01-01", periods=len(df), freq="5min")

        # Zone-coherent entry passes.
        ok1, why1 = _v580_pullback_entry_zone_ok(102.00, 1.00, 101.50, df)
        checks["zone_entry_pass"] = bool(ok1)
        checks["zone_reason_present"] = bool(why1)

        # Late chase is blocked.
        old = CONFIG.get("V580_PULLBACK_FINAL_MAX_CHASE_ATR", 0.90)
        CONFIG["V580_PULLBACK_FINAL_MAX_CHASE_ATR"] = 0.25
        ok2, _ = _v580_pullback_entry_zone_ok(104.00, 1.00, 101.50, df)
        checks["late_chase_blocked"] = not bool(ok2)
        CONFIG["V580_PULLBACK_FINAL_MAX_CHASE_ATR"] = old

        # Too-far-above-zone entry is blocked.
        ok3, _ = _v580_pullback_entry_zone_ok(103.00, 1.00, 101.50, df)
        checks["zone_drift_blocked"] = not bool(ok3)

        # Structural SL is valid and bounded for the coherent setup.
        sl = _v578_pullback_stop(df, entry=102.00, atr=1.00, zone_ref=101.50)
        checks["structural_sl_valid"] = bool(sl is not None and 0 < sl < 102.0)
        checks["structural_sl_bounded"] = bool(sl is not None and (102.0 - sl) <= 1.80 + 1e-9)

        # Shallow-only cannot substitute for structural confirmation in the
        # canonical microstructure parity implementation.
        checks["shallow_support_only"] = bool(CONFIG.get("V579_PULLBACK_REQUIRE_STRUCTURAL_CONFIRMATION", True))
        checks["single_jit_spread_recheck"] = int(CONFIG.get("V538_SPREAD_RECHECK_MAX_ATTEMPTS", 1)) == 1
        old_below = CONFIG.get("V581_PULLBACK_MAX_ENTRY_BELOW_ZONE_ATR", 0.75)
        CONFIG["V581_PULLBACK_MAX_ENTRY_BELOW_ZONE_ATR"] = 0.25
        ok4, _ = _v580_pullback_entry_zone_ok(100.60, 1.00, 101.50, df)
        checks["below_zone_bound"] = (ok4 is False)
        CONFIG["V581_PULLBACK_MAX_ENTRY_BELOW_ZONE_ATR"] = old_below
        return {"pass": all(checks.values()), "checks": checks}
    except Exception as exc:
        return {"pass": False, "checks": checks, "error": f"{type(exc).__name__}:{exc}"}

