# =============================================================================
# v4.5.96 — BOUNDED LEGACY-ROUTER RECALL BRIDGE
# =============================================================================
def _v596_legacy_recall_candidates(
    market_data_map: Dict[str, Dict[str, Any]],
    max_symbols: int,
    *,
    min_htf: Optional[float] = None,
    cooldown_sec: Optional[float] = None,
) -> List[Tuple[str, Dict[str, Any]]]:
    """Build a bounded, execution-neutral legacy recovery list.

    Used ONLY when the global MSE layer generated/hard-validated candidates but
    ranked zero or prequalified zero. It does not construct an order. The final
    SignalBuilder remains responsible for all entry/SL/TP/Balance/TruthSeal/
    Exposure/PreSend/Liquidity/Execution gates.
    """
    rows: List[Tuple[str, Dict[str, Any]]] = []
    try:
        if not bool(CONFIG.get("V596_LEGACY_RECALL_BRIDGE_ENABLE", True)):
            return rows
        htf_floor = float(
            CONFIG.get("V596_LEGACY_RECALL_BRIDGE_MIN_HTF", 55.0)
            if min_htf is None else min_htf
        )
        cd_sec = max(0.0, float(
            CONFIG.get("V596_LEGACY_RECALL_BRIDGE_COOLDOWN_SEC", 180.0)
            if cooldown_sec is None else cooldown_sec
        ))
        now = MONO_NOW()
        last_map = STATS.get("v596_bridge_last_symbol_ts")
        if not isinstance(last_map, dict):
            last_map = {}
            STATS["v596_bridge_last_symbol_ts"] = last_map
        for symbol, md in list((market_data_map or {}).items()):
            try:
                if symbol in ACTIVE_TRADES:
                    continue
                # v4.5.97: the legacy recall bridge is not allowed to revive a
                # forbidden asset. The authoritative V587 execution guard
                # remains in place, but rejecting it here avoids unnecessary
                # builder work and keeps discovery/recovery telemetry truthful.
                try:
                    if "_v587_is_forbidden_coin" in globals():
                        _fb, _fr = _v587_is_forbidden_coin(symbol)
                        if _fb:
                            STATS["v597_bridge_forbidden_skips"] = int(
                                STATS.get("v597_bridge_forbidden_skips", 0) or 0
                            ) + 1
                            continue
                except Exception:
                    _v647_record_suppressed_exception()
                if cd_sec > 0 and (now - float(last_map.get(symbol, 0.0) or 0.0)) < cd_sec:
                    continue
                htf = float((md or {}).get("htf_strength", 0.0) or 0.0)
                if not math.isfinite(htf) or htf < htf_floor:
                    # htf_strength is not stored in market_data_map in all builds;
                    # derive it from the same already-fetched context when possible.
                    try:
                        _snap = GlobalOpportunityBrain._snapshot(symbol, md)
                        htf = float(_snap.get("htf_strength", 0.0) or 0.0)
                    except Exception:
                        htf = 0.0
                if not math.isfinite(htf) or htf < htf_floor:
                    continue
                opp = OpportunityRouter.classify({
                    "symbol": symbol,
                    "df_1d": md.get("df_1d"),
                    "df_4h": md.get("df_4h"),
                    "df_15m": md.get("df_15m"),
                    "df_5m": md.get("df_5m"),
                    "regime": md.get("regime"),
                    "tier": md.get("tier"),
                    "htf_strength": htf,
                })
                if not opp:
                    continue
                if not isinstance(opp, dict):
                    try:
                        opp = dict(opp)
                    except Exception:
                        STATS["v651_bridge_non_mapping_opportunity"] = int(
                            STATS.get("v651_bridge_non_mapping_opportunity", 0) or 0
                        ) + 1
                        continue
                fam = str(opp.get("family") or opp.get("detector") or "UNKNOWN").upper()
                priority = {
                    "MTF_PULLBACK": 9, "PULLBACK": 8, "BREAKOUT_RETEST": 7,
                    "BREAKOUT_CONTINUATION": 6, "MEASURED_MOVE_BREAKOUT": 6,
                    "LIQUIDITY_SWEEP_REVERSAL": 5, "MOMENTUM_EXPANSION": 4,
                    "MEAN_REVERSION": 2, "TREND_CONTINUATION": 1,
                }.get(fam, 0)
                dist = float(opp.get("dist_atr", 99.0) or 99.0)
                if not math.isfinite(dist):
                    dist = 99.0
                rows.append((symbol, {**dict(opp), "_v596_priority": priority, "_v596_dist_atr": dist, "_v596_htf": htf}))
            except Exception as exc:
                STATS["v596_bridge_router_errors"] = int(STATS.get("v596_bridge_router_errors", 0) or 0) + 1
                STATS["v596_bridge_last_error"] = f"{type(exc).__name__}:{exc}"
        rows.sort(key=lambda kv: (-int(kv[1].get("_v596_priority", 0)), float(kv[1].get("_v596_dist_atr", 99.0)), kv[0]))
        return rows[:max(1, int(max_symbols))]
    except Exception:
        return []


