# ---- Canonical score contract ------------------------------------------------
def _v585_canonical_score_contract(candidate: Any,
                                   snapshot: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """
    Side-effect-free score contract for diagnostics/prequalification.
    The actual SignalBuilder remains the sole execution authority.
    """
    try:
        c = candidate
        fs = dict(getattr(c, "features_snapshot", {}) or {})
        snap = snapshot if isinstance(snapshot, dict) else {}
        fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
        mode = str(getattr(c, "strategy_mode", "") or fam).upper()
        regime = str(
            fs.get("macro_regime") or fs.get("regime") or
            snap.get("macro_regime") or snap.get("regime") or "NEUTRAL"
        ).upper()
        base_floor = _v570_strategy_aware_canonical_floor(c, regime, fam)
        try:
            adaptive = float(getattr(_V420State, "adaptive_floor", base_floor) or base_floor)
        except Exception:
            adaptive = base_floor
        floor_min = float(CONFIG.get("V453_SCORE_FLOOR_MIN", 70.0))
        adaptive = max(floor_min, min(base_floor, adaptive))
        legacy = base_floor
        try:
            legacy = float(_v45_effective_score_floor(base_floor))
            legacy = max(floor_min, min(base_floor, legacy))
        except Exception:
            legacy = base_floor
        rescue_level = 0
        try:
            rescue_level = int(_v45_rescue_level())
        except Exception:
            _v647_record_suppressed_exception()
        effective = max(adaptive, legacy) if rescue_level > 0 else adaptive

        raw = _v584_safe_float(getattr(c, "engine_score", 0.0), 0.0)
        raw100 = raw * 100.0 if 0.0 <= raw <= 1.0 else raw
        max_adj = _v584_canonical_score_upper_bound(c, fam, snap)
        feasible_upper = raw100 + max_adj if math.isfinite(raw100) else None
        return {
            "family": fam,
            "mode": mode,
            "regime": regime,
            "raw_engine_score_100": raw100,
            "base_floor": base_floor,
            "adaptive_floor": adaptive,
            "legacy_rescue_floor": legacy,
            "effective_floor": effective,
            "max_adjustment": max_adj,
            "feasible_upper": feasible_upper,
            "feasible": bool(feasible_upper is not None and feasible_upper >= effective),
        }
    except Exception as exc:
        return {
            "family": str(getattr(candidate, "family", "") or "").upper(),
            "mode": str(getattr(candidate, "strategy_mode", "") or "").upper(),
            "error": f"{type(exc).__name__}:{exc}",
            "feasible": False,
        }


# ---- Bounded Global-ranking volume quality ----------------------------------
_orig_global_candidate_score_v585 = GlobalOpportunityArbiter._candidate_score

def _v585_candidate_score(ranked_candidate: RankedCandidate) -> float:
    score = float(_orig_global_candidate_score_v585(ranked_candidate))
    if not bool(CONFIG.get("V585_VOLUME_RANKING_QUALITY_ENABLE", True)):
        return _clamp(score, 0.0, 1.0)
    try:
        c = ranked_candidate.candidate
        fs = dict(getattr(c, "features_snapshot", {}) or {})
        vr = fs.get("volume_ratio")
        if vr is None:
            # Some MSE candidates store the quality-normalized form only.
            vq = fs.get("volume_quality")
            if vq is not None:
                vr = float(vq)  # normalized fallback, still bounded and ranking-only
        if vr is None:
            return _clamp(score, 0.0, 1.0)
        vr = float(vr)
        if not math.isfinite(vr):
            return _clamp(score, 0.0, 1.0)

        low = float(CONFIG.get("V585_VOLUME_RANKING_LOW_RATIO", 0.60))
        mid = float(CONFIG.get("V585_VOLUME_RANKING_MID_RATIO", 0.85))
        pen = 0.0
        if vr < low:
            pen = max(0.0, min(0.08, float(CONFIG.get("V585_VOLUME_RANKING_PENALTY_LOW", 0.030))))
        elif vr < mid:
            pen = max(0.0, min(0.05, float(CONFIG.get("V585_VOLUME_RANKING_PENALTY_MID", 0.012))))
        if pen > 0:
            score = _clamp(score - pen, 0.0, 1.0)
            STATS["v585_global_volume_quality_penalties"] = int(
                STATS.get("v585_global_volume_quality_penalties", 0) or 0
            ) + 1
            STATS["v585_last_volume_ranking_penalty"] = {"symbol": str(getattr(c, "symbol", "")), "penalty": float(pen)}
    except Exception:
        STATS["v585_global_volume_quality_errors"] = int(
            STATS.get("v585_global_volume_quality_errors", 0) or 0
        ) + 1
    return _clamp(score, 0.0, 1.0)

GlobalOpportunityArbiter._candidate_score = staticmethod(_v585_candidate_score)


# ---- Bounded live family diversity ------------------------------------------
_orig_global_select_v585 = GlobalOpportunityArbiter.select

@classmethod
def _v585_global_select(cls, ranked: List[RankedCandidate], max_winners: int = 3):
    if not bool(CONFIG.get("V585_FAMILY_DIVERSITY_ENABLE", True)):
        return _orig_global_select_v585(ranked, max_winners)

    # The original selector already enforces all hard eligibility and symbol
    # constraints. We only tune its bounded family preference knobs around that
    # same selector, never bypassing it.
    old_dup = CONFIG.get("V45_GLOBAL_FAMILY_DUP_PENALTY", 0.02)
    old_bonus = CONFIG.get("V459_DIVERSITY_BONUS", 0.008)
    try:
        CONFIG["V45_GLOBAL_FAMILY_DUP_PENALTY"] = max(
            0.0, min(0.02, float(CONFIG.get("V585_FAMILY_DUP_PENALTY", 0.008)))
        )
        CONFIG["V459_DIVERSITY_BONUS"] = max(
            0.0, min(0.02, float(CONFIG.get("V585_FAMILY_NEW_BONUS", 0.008)))
        )
        return _orig_global_select_v585(ranked, max_winners)
    finally:
        CONFIG["V45_GLOBAL_FAMILY_DUP_PENALTY"] = old_dup
        CONFIG["V459_DIVERSITY_BONUS"] = old_bonus

GlobalOpportunityArbiter.select = _v585_global_select


# ---- Exact Builder blocker capture ------------------------------------------
_orig_v584_note_builder_outcome_v585 = _v584_note_builder_outcome

def _v585_note_builder_outcome(symbol: str, family: str,
                               before_rejections: Dict[str, int],
                               before_builder_blocks: int,
                               before_ready: int,
                               before_queued: int,
                               before_sent: int) -> None:
    _orig_v584_note_builder_outcome_v585(
        symbol, family, before_rejections, before_builder_blocks,
        before_ready, before_queued, before_sent
    )
    if not bool(CONFIG.get("V585_EXACT_BUILDER_REASON_ENABLE", True)):
        return
    try:
        rec = (STATS.get("v523_last_rejection_by_symbol") or {}).get(str(symbol))
        if isinstance(rec, dict):
            reason = str(rec.get("reason") or "unknown")
            stage = str(rec.get("stage") or "unknown")
            exact = {
                "symbol": str(symbol),
                "family": str(family or "UNKNOWN").upper(),
                "reason": reason[:180],
                "stage": stage[:120],
                "score": rec.get("score"),
                "ts": float(rec.get("ts", WALL_NOW()) or WALL_NOW()),
            }
            STATS["v585_last_exact_builder_block"] = exact
            rr = STATS.setdefault("v585_cycle_exact_builder_reasons", {})
            key = f"{stage}:{reason}"[:220]
            rr[key] = int(rr.get(key, 0) or 0) + 1
            fb = STATS.setdefault("v585_cycle_family_exact_blocks", {})
            frow = fb.setdefault(str(family or "UNKNOWN").upper(), {})
            bucket = _v584_norm_reason(reason)
            frow[bucket] = int(frow.get(bucket, 0) or 0) + 1
            if int(STATS.get("v584_cycle_builder_blocked", 0) or 0) > 0:
                STATS["v585_cycle_exact_builder_blocked"] = int(
                    STATS.get("v585_cycle_exact_builder_blocked", 0) or 0
                ) + 1
    except Exception as exc:
        STATS["v585_exact_reason_errors"] = int(
            STATS.get("v585_exact_reason_errors", 0) or 0
        ) + 1
        logger.debug(f"[V585-EXEC] exact reason capture suppressed: {exc}")


def _v585_wrap_signal_builder():
    # Replace the V584 wrapper with a V585 wrapper that preserves its telemetry
    # and additionally captures the canonical rejection ledger.
    original = getattr(SignalBuilder, "build_and_route")
    if getattr(original, "_v585_wrapped", False):
        return

    async def _wrapped(exchange, symbol, market_data, preferred_candidate=None):
        before_rej = dict(STATS.get("v545_builder_blocker_reasons") or {})
        before_blocks = int(STATS.get("v545_builder_blocker", 0) or 0)
        before_ready = int(STATS.get("v534_live_ready", 0) or 0)
        before_queued = int(STATS.get("signals_queued", 0) or 0)
        before_sent = int(STATS.get("signals_sent", 0) or 0)
        fam = str(
            getattr(preferred_candidate, "family", "")
            or getattr(preferred_candidate, "strategy_mode", "")
            or (
                preferred_candidate.features_snapshot.get("family", "")
                if getattr(preferred_candidate, "features_snapshot", None) else ""
            )
            or "UNKNOWN"
        ).upper()
        try:
            result = await original(
                exchange, symbol, market_data,
                preferred_candidate=preferred_candidate
            )
            if result is None:
                # Capture the most recent canonical symbol-level reason immediately
                # after the builder returns, before another candidate overwrites it.
                rec = (STATS.get("v523_last_rejection_by_symbol") or {}).get(str(symbol))
                if isinstance(rec, dict):
                    STATS["v585_last_exact_builder_block"] = {
                        "symbol": str(symbol),
                        "family": fam,
                        "reason": str(rec.get("reason") or "unknown")[:180],
                        "stage": str(rec.get("stage") or "unknown")[:120],
                        "score": rec.get("score"),
                        "ts": float(rec.get("ts", WALL_NOW()) or WALL_NOW()),
                    }
            return result
        finally:
            _v585_note_builder_outcome(
                symbol, fam, before_rej, before_blocks,
                before_ready, before_queued, before_sent
            )

    _wrapped._v585_wrapped = True
    SignalBuilder.build_and_route = staticmethod(_wrapped)

_v585_wrap_signal_builder()


