# Predeclared fail-closed source for the immutable V702 hard-deny assets.
# The public runtime name is bound to this set later in module initialization;
# early compatibility/self-test calls must still deny these bases before then.


def _v587_norm_symbol(symbol: Any) -> str:
    try:
        return str(symbol or "").strip().upper().replace(" ", "")
    except Exception:
        return ""


def _v587_base_asset(symbol: Any) -> str:
    """Return the base asset from common exchange symbol representations.

    Handles slash pairs (including CCXT contract suffixes), underscore/dash
    exchange IDs, and compact BASEQUOTE IDs when QUOTE is a known market quote.
    Compact parsing is deliberately limited to recognized quote suffixes so an
    arbitrary token name is not truncated speculatively.
    """
    s = _v587_norm_symbol(symbol)
    if not s:
        return ""

    # Common canonical / contract forms: AERO/USDT, AERO/USDT:USDT.
    for separator in ("/", "_", "-", "|", ":", "."):
        if separator in s:
            return s.split(separator, 1)[0].strip()

    # Many exchange APIs expose compact market IDs such as AEROUSDT.
    # Match the longest recognized quote suffix, only when the prefix itself
    # is a known hard-forbidden base. This avoids heuristic truncation of
    # ordinary tokens whose names happen to end with quote-like characters.
    hard_bases = tuple(sorted(
        (str(x).strip().upper() for x in globals().get("V702_HARD_FORBIDDEN_BASES", _V702_PREDECLARED_FORBIDDEN_BASES) if str(x).strip()),
        key=len,
        reverse=True,
    ))
    quote_suffixes = (
        "USDT", "USDC", "FDUSD", "BUSD", "TUSD", "USDE", "USDP",
        "USTC", "DAI", "USD", "BTC", "ETH", "BNB", "EUR", "TRY",
        "BRL", "JPY", "GBP", "AUD", "MXN", "IDR", "RUB", "ZAR",
    )
    for base in hard_bases:
        if s.startswith(base):
            suffix = s[len(base):]
            if suffix in quote_suffixes:
                return base
    return s


def _v587_blacklist_exact_set() -> set:
    # V702 hard deny cannot be removed by environment/config overrides.
    out = set(globals().get("V702_HARD_FORBIDDEN_BASES", _V702_PREDECLARED_FORBIDDEN_BASES))
    try:
        for x in CONFIG.get("FORBIDDEN_COIN_BLACKLIST", ()) or ():
            s = _v587_norm_symbol(x)
            if s:
                out.add(s)
    except Exception:
        _v647_record_suppressed_exception()
    try:
        env_key = str(CONFIG.get("FORBIDDEN_COIN_ENV_KEY", "FORBIDDEN_COIN_BLACKLIST"))
        raw = os.environ.get(env_key, "")
        for x in str(raw or "").split(","):
            s = _v587_norm_symbol(x)
            if s:
                out.add(s)
    except Exception:
        _v647_record_suppressed_exception()
    return out


def _v587_is_forbidden_coin(symbol: Any) -> Tuple[bool, str]:
    """Absolute symbol guard. V702 hard-forbidden bases cannot be disabled."""
    try:
        s = _v587_norm_symbol(symbol)
        base = _v587_base_asset(symbol)
        if base and base in set(globals().get("V702_HARD_FORBIDDEN_BASES", _V702_PREDECLARED_FORBIDDEN_BASES)):
            return True, "v702_hard_blacklist"
        if not bool(CONFIG.get("FORBIDDEN_COIN_BLACKLIST_ENABLE", True)):
            return False, "disabled"
        if not s or not base:
            return True, "invalid_symbol"
        exact = _v587_blacklist_exact_set()
        # Allow env/config entries written as BASE or BASE/QUOTE. Exact match is
        # preferred; BASE-only entries apply to any quoted market.
        if s in exact:
            return True, "exact_blacklist"
        if base in exact:
            return True, "base_blacklist"
        kws = tuple(str(x).strip().upper() for x in (CONFIG.get("FORBIDDEN_COIN_KEYWORDS", ()) or ()) if str(x).strip())
        for kw in kws:
            if kw and kw in base:
                return True, f"keyword:{kw}"
        return False, "allowed"
    except Exception as exc:
        # The blacklist itself is a safety gate: uncertainty means block.
        return True, f"blacklist_check_error:{type(exc).__name__}"


_V599_FORBIDDEN_ALERT_LAST = {}

def _v587_send_forbidden_telegram(symbol: str, reason: str, stage: str) -> None:
    """Non-blocking operator alert; never raises into execution."""
    try:
        if not bool(CONFIG.get("TELEGRAM_FORBIDDEN_COIN_ALERT_ENABLE", True)):
            return
        if not bool(CONFIG.get("TELEGRAM_ENABLED", True)):
            return
        _dedup_key = (
            str(symbol or "").upper(),
            str(reason or "forbidden"),
            str(stage or "UNKNOWN").upper(),
        )
        _dedup_now = MONO_NOW()
        _dedup_ttl = max(0.0, float(CONFIG.get("V599_FORBIDDEN_ALERT_DEDUP_SEC", 1800.0)))
        if _dedup_ttl > 0:
            _prev = float(_V599_FORBIDDEN_ALERT_LAST.get(_dedup_key, 0.0) or 0.0)
            if _dedup_now - _prev < _dedup_ttl:
                STATS["v599_forbidden_alert_dedup_skips"] = int(
                    STATS.get("v599_forbidden_alert_dedup_skips", 0) or 0
                ) + 1
                return
            _V599_FORBIDDEN_ALERT_LAST[_dedup_key] = _dedup_now
        sym = OpportunityTelegramNotifier._escape(symbol)
        msg = (
            "⛔ <b>BUY NOT EXECUTED — FORBIDDEN COIN</b>\n\n"
            f"<b>{sym}</b>\n"
            "Reason: <b>Coin is on the forbidden blacklist</b>\n"
            f"Stage: <b>{OpportunityTelegramNotifier._escape(stage)}</b>\n"
            f"Rule: <b>{OpportunityTelegramNotifier._escape(reason)}</b>\n\n"
            "<i>No BUY order was authorized, queued, or submitted.</i>"
        )
        try:
            asyncio.get_running_loop().create_task(TelegramDispatcher.enqueue(msg))
        except RuntimeError:
            STATS["v587_forbidden_telegram_no_loop"] = int(STATS.get("v587_forbidden_telegram_no_loop", 0) or 0) + 1
        STATS["v587_forbidden_telegram_alerts"] = int(STATS.get("v587_forbidden_telegram_alerts", 0) or 0) + 1
    except Exception as exc:
        STATS["v587_forbidden_telegram_errors"] = int(STATS.get("v587_forbidden_telegram_errors", 0) or 0) + 1
        logger.warning(f"[V587-TG] forbidden alert failed for {symbol}: {exc}")



def _v587_pullback_quality(candidate: Any, market_data: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Deterministic local setup audit. Uses CLOSED 5m bars only for micro evidence."""
    fs = dict(getattr(candidate, "features_snapshot", {}) or {})
    md = dict(market_data or {}) if isinstance(market_data, dict) else {}
    out = {
        "ok": False, "reason": "insufficient_data", "quality": 0.0,
        "volume_ratio": None, "rs_5m": None, "htf_strength": None,
        "structure": None, "retest": None, "chase": None,
        "confirmations": 0, "reclaim": False, "higher_low": False,
        "ema20_slope_up": False, "bullish_close": False,
        "bearish_body_ratio": None,
    }
    try:
        # Prefer candidate-captured values, but fall back to the same live
        # market snapshot when a value was not embedded in the immutable candidate.
        vol = fs.get("volume_ratio", md.get("volume_ratio"))
        rs = fs.get("rs_5m", fs.get("rs_score_val", fs.get("relative_strength", md.get("rs_5m"))))
        htf = fs.get("htf_strength", fs.get("htf_alignment", md.get("htf_strength")))
        structure = fs.get("structure_confidence", fs.get("structure_quality", md.get("structure_confidence", md.get("structure_quality"))))
        retest = fs.get("retest_quality_score", fs.get("retest_quality", md.get("retest_quality_score", md.get("retest_quality"))))
        chase = fs.get("chase_atr", md.get("chase_atr"))
        def sf(v):
            try:
                x=float(v)
                return x if math.isfinite(x) else None
            except Exception:
                return None
        vol, rs, htf, structure, retest, chase = map(sf, (vol, rs, htf, structure, retest, chase))
        if rs is not None and abs(rs) > 1.5:
            rs /= 100.0
        df5 = md.get("df_5m") if isinstance(md, dict) else None
        if df5 is not None and len(df5) >= 24:
            lc = float(df5["close"].iloc[-2]); pc = float(df5["close"].iloc[-3]); op = float(df5["open"].iloc[-2])
            hi = float(df5["high"].iloc[-2]); lo = float(df5["low"].iloc[-2])
            if vol is None:
                av = float(df5["volume"].iloc[-22:-2].mean())
                cv = float(df5["volume"].iloc[-2])
                if av > 0: vol = cv / av
            bullish = bool(lc > op and lc >= pc)
            hl = bool(float(df5["low"].iloc[-2]) > float(df5["low"].iloc[-3]) >= float(df5["low"].iloc[-4]))
            e20 = df5["close"].ewm(span=20, adjust=False).mean()
            bars = 8
            closed = e20.iloc[-(bars+1):-1]
            slope = False
            if len(closed) >= 2:
                slope = bool(float(closed.iloc[-1]) > float(closed.iloc[0]) * 1.0001)
            zone = fs.get("zone_ref", getattr(candidate, "zone_ref", None))
            reclaim = False
            if zone is not None:
                z=float(zone)
                reclaim = bool(pc < z <= lc)
            body_ratio = abs(lc-op) / max(hi-lo, 1e-12)
            out.update({"bullish_close":bullish,"higher_low":hl,"ema20_slope_up":slope,
                        "reclaim":reclaim,"bearish_body_ratio":body_ratio})
        confirmations = sum(bool(x) for x in (out["reclaim"], out["higher_low"], out["ema20_slope_up"], out["bullish_close"]))
        out["confirmations"] = int(confirmations)
        out.update({"volume_ratio":vol,"rs_5m":rs,"htf_strength":htf,"structure":structure,"retest":retest,"chase":chase})

        # Bounded deterministic quality (telemetry + live PULLBACK hard gate).
        trend_q = 0.0 if htf is None else max(0.0, min(100.0, htf))
        pullback_q = 0.0 if retest is None else max(0.0, min(100.0, retest))
        structure_q = 0.0 if structure is None else max(0.0, min(100.0, structure))
        confirm_q = min(100.0, confirmations / 2.0 * 100.0)
        vol_q = 0.0 if vol is None else max(0.0, min(100.0, (vol / 1.5) * 100.0))
        rs_q = 0.0 if rs is None else max(0.0, min(100.0, (rs / 0.07) * 100.0))
        chase_q = 0.0 if chase is None else max(0.0, min(100.0, 100.0 - (chase / max(float(CONFIG.get("V587_PULLBACK_MAX_FINAL_CHASE_ATR",0.90)),0.1))*100.0))
        quality = (0.20*trend_q + 0.20*pullback_q + 0.20*structure_q +
                   0.20*confirm_q + 0.10*vol_q + 0.05*rs_q + 0.05*chase_q)
        out["quality"] = float(max(0.0, min(100.0, quality)))

        if not bool(CONFIG.get("V587_PULLBACK_PRECISION_ENABLE", True)):
            out["ok"] = True; out["reason"] = "disabled"; return out
        floors = [
            (htf is not None and htf >= float(CONFIG.get("V587_PULLBACK_MIN_HTF", 50.0)), "htf_below_floor"),
            (vol is not None and vol >= float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO",0.85)), "volume_below_floor"),
            (rs is not None and rs >= float(CONFIG.get("V587_PULLBACK_MIN_RS",0.0)), "rs_negative"),
            (structure is not None and structure >= float(CONFIG.get("V587_PULLBACK_MIN_STRUCTURE_SCORE",45.0)), "structure_weak"),
        ]
        if retest is None or retest < float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE",45.0)):
            return {**out, "reason":"retest_weak"}
        for ok, reason in floors:
            if not ok:
                return {**out, "reason":reason}
        if chase is None or chase > float(CONFIG.get("V587_PULLBACK_MAX_FINAL_CHASE_ATR",0.90)):
            return {**out, "reason":"chase_too_high"}
        if out.get("bearish_body_ratio") is not None and out["bearish_body_ratio"] >= float(CONFIG.get("V587_PULLBACK_MAX_BEARISH_BODY_RATIO",0.75)) and not out["bullish_close"]:
            return {**out, "reason":"bearish_displacement"}
        if confirmations < int(CONFIG.get("V587_PULLBACK_MIN_CONFIRMATIONS",2)):
            return {**out, "reason":"insufficient_recovery_confirmations"}
        if out["quality"] < float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY",72.0)):
            return {**out, "reason":"setup_quality_below_floor"}
        out["ok"] = True; out["reason"] = "pass"
        return out
    except Exception as exc:
        out["reason"] = f"quality_exception:{type(exc).__name__}"
        return out


# ---- More honest Telegram quality grade ------------------------------------
_orig_v586_grade = OpportunityTelegramNotifier._opportunity_grade

@staticmethod
def _v587_opportunity_grade(score: float, floor: float, htf: Any, vol: Any, rs: Any,
                            chase: Any, liquidity: Any, family: str = "") -> Tuple[str, float]:
    try:
        s=float(score); f=float(floor)
        pts=0.0
        pts += 26.0 if s >= 80 else 22.0 if s >= 75 else 18.0 if s >= 70 else 13.0
        try:
            h=float(htf); pts += 16.0 if h>=90 else 12.0 if h>=75 else 7.0 if h>=60 else 0.0
        except Exception: pass
        try:
            v=float(vol); pts += 15.0 if v>=1.50 else 11.0 if v>=1.20 else 7.0 if v>=1.00 else 0.0
        except Exception: pass
        try:
            r=float(rs)
            pts += 15.0 if r>=0.07 else 10.0 if r>=0.04 else 6.0 if r>=0.02 else 0.0
        except Exception: pass
        try:
            c=float(chase); pts += 12.0 if c<=0.30 else 9.0 if c<=0.60 else 5.0 if c<=0.90 else 0.0
        except Exception: pass
        liq=str(liquidity or "").upper()
        pts += 6.0 if liq in {"MAJORS","LARGE"} else 3.0 if liq=="MID" else 0.0
        if str(family or "").upper() in {"PULLBACK","MTF_PULLBACK"} and s >= max(f,70.0):
            pts += 4.0
        grade = "C"
        if s >= 80 and pts >= 82: grade="A+"
        elif s >= 74 and pts >= 74: grade="A"
        elif s >= 68 and pts >= 64: grade="B"
        return grade, min(100.0, pts)
    except Exception:
        return _orig_v586_grade(score,floor,htf,vol,rs,chase,liquidity,family)

OpportunityTelegramNotifier._opportunity_grade = staticmethod(_v587_opportunity_grade)


# ---- Forbidden symbol guard at the canonical builder ----------------------
_orig_v587_builder = SignalBuilder.build_and_route
_V587_ACTIVE_FAMILY_BY_SYMBOL: Dict[str, str] = {}

async def _v587_build_and_route(exchange, symbol, market_data, preferred_candidate=None):
    blocked, why = _v587_is_forbidden_coin(symbol)
    if blocked:
        STATS["v587_forbidden_builder_blocks"] = int(STATS.get("v587_forbidden_builder_blocks",0) or 0) + 1
        logger.warning(f"[V587-BLACKLIST] {symbol} blocked before canonical build reason={why}")
        _v587_send_forbidden_telegram(str(symbol), why, "CANONICAL_BUILDER")
        return None
    fam = str(getattr(preferred_candidate,"family","") or getattr(preferred_candidate,"strategy_mode","") or "").upper()
    if fam:
        _V587_ACTIVE_FAMILY_BY_SYMBOL[_v587_norm_symbol(symbol)] = fam
    try:
        # Precision gate is deliberately applied before the legacy builder so a
        # weak PULLBACK cannot produce a misleading BUY alert and then fail later.
        if fam in {"PULLBACK","MTF_PULLBACK"} and bool(CONFIG.get("V587_PULLBACK_PRECISION_ENABLE",True)):
            q = _v587_pullback_quality(preferred_candidate, market_data)
            try:
                fs = dict(getattr(preferred_candidate,"features_snapshot",{}) or {})
                fs["v587_setup_quality"] = q.get("quality")
                fs["v587_pullback_confirmations"] = q.get("confirmations")
                fs["v587_pullback_quality_reason"] = q.get("reason")
                fs["v702_a29_pullback_quality_relief"] = dict(q.get("a29_adaptive_relief") or {})
                _a29_ev = q.get("a29_closed_evidence") if isinstance(q.get("a29_closed_evidence"), dict) else {}
                fs["v702_a29_closed_bar_evidence_verified"] = bool(_a29_ev.get("closed_frame_verified", False))
                fs["v702_a29_closed_bar_evidence_groups"] = list(_a29_ev.get("groups") or [])[:8]
                # Bind the validation marker to the exact closed-bar snapshot. A boolean
                # alone is not sufficient if a later stage receives a newer/stale frame.
                fs["v702_a29_closed_bar_evidence_key"] = str(_a29_ev.get("closed_frame_key") or "")[:64]
                preferred_candidate = replace(preferred_candidate, features_snapshot=fs)
            except Exception:
                _v647_record_suppressed_exception()
            if not bool(q.get("ok")):
                reason = str(q.get("reason") or "pullback_precision_reject")
                STATS["v587_pullback_precision_rejects"] = int(STATS.get("v587_pullback_precision_rejects",0) or 0) + 1
                logger.info(f"[V587-PULLBACK] {symbol} precision reject reason={reason} quality={float(q.get('quality',0.0)):.1f}")
                # No "BUY OPPORTUNITY" is emitted: this setup is rejected before
                # entering the authoritative builder path.
                return None
        return await _orig_v587_builder(exchange, symbol, market_data, preferred_candidate)
    finally:
        _V587_ACTIVE_FAMILY_BY_SYMBOL.pop(_v587_norm_symbol(symbol), None)

_v587_build_and_route._v587_wrapped = True
SignalBuilder.build_and_route = staticmethod(_v587_build_and_route)


# ---- Forbidden symbol + JIT execution guard -------------------------------
_orig_v587_submit = OrderExecutor.submit_entry

@staticmethod
async def _v587_submit_entry(exchange, symbol, qty, price, is_paper=False, trace_id=None,
                             intent_context: Optional[Dict[str, Any]] = None):
    blocked, why = _v587_is_forbidden_coin(symbol)
    if blocked and not is_paper:
        STATS["v587_forbidden_execution_blocks"] = int(STATS.get("v587_forbidden_execution_blocks",0) or 0) + 1
        logger.critical(f"[V587-BLACKLIST] {symbol} FINAL BUY BLOCK — reason={why}")
        _v587_send_forbidden_telegram(str(symbol), why, "ORDER_EXECUTOR")
        try:
            record_rejection(trace_id or "n/a", str(symbol), "strategy", f"forbidden_coin:{why}", "v587_submit_entry")
        except Exception:
            _v647_record_suppressed_exception()
        return False, None, 0.0

    fam = str(_V587_ACTIVE_FAMILY_BY_SYMBOL.get(_v587_norm_symbol(symbol),"") or "").upper()
    if (not is_paper and fam in {"PULLBACK","MTF_PULLBACK"}
            and bool(CONFIG.get("V587_PULLBACK_JIT_VALIDATION_ENABLE",True))):
        try:
            planned = float(price)
            tk = await safe_api_call("v587_jit_ticker", lambda: exchange.fetch_ticker(symbol))
            ask = float((tk or {}).get("ask") or 0.0)
            if planned <= 0 or ask <= 0 or not math.isfinite(planned) or not math.isfinite(ask):
                STATS["v587_jit_rejects"] = int(STATS.get("v587_jit_rejects",0) or 0) + 1
                logger.warning(f"[V587-JIT] {symbol} invalid planned/ask; blocking PULLBACK entry")
                return False, None, 0.0
            drift_pct = (ask - planned) / planned * 100.0
            max_up = float(CONFIG.get("V587_PULLBACK_MAX_ENTRY_DRIFT_UP_PCT",0.35))
            max_down = float(CONFIG.get("V587_PULLBACK_MAX_ATR_ENTRY_DRIFT_DOWN_PCT",0.35))
            if drift_pct > max_up or drift_pct < -max_down:
                STATS["v587_jit_rejects"] = int(STATS.get("v587_jit_rejects",0) or 0) + 1
                reason = "ask_above_planned_envelope" if drift_pct > max_up else "ask_below_planned_falling_knife_envelope"
                logger.info(f"[V587-JIT] {symbol} blocked reason={reason} drift={drift_pct:.3f}% planned={planned:.10g} ask={ask:.10g}")
                try:
                    record_rejection(trace_id or "n/a", str(symbol), "strategy", f"jit_pullback:{reason}:{drift_pct:.4f}%", "v587_jit_entry")
                except Exception:
                    _v647_record_suppressed_exception()
                return False, None, 0.0
        except Exception as exc:
            STATS["v587_jit_errors"] = int(STATS.get("v587_jit_errors",0) or 0) + 1
            logger.warning(f"[V587-JIT] {symbol} validation error -> block: {exc}")
            return False, None, 0.0
    # Preserve the exact recipe context through this legacy JIT/blacklist wrapper.
    # A missing context must never turn the final EdgeGate into a context-free arm check.
    return await _orig_v587_submit(
        exchange, symbol, qty, price, is_paper, trace_id,
        intent_context=intent_context,
    )

OrderExecutor.submit_entry = _v587_submit_entry


# ---- Suppress discovery alerts for forbidden symbols ----------------------
_prev_v587_discovery = globals().get("_v531_knowledge_notify_candidates")
if callable(_prev_v587_discovery):
    def _v587_discovery_notify(candidates, snapshot=None):
        safe=[]
        for c in list(candidates or []):
            sym=str(getattr(c,"symbol","") or "")
            blocked, why = _v587_is_forbidden_coin(sym)
            if blocked:
                _v587_send_forbidden_telegram(sym, why, "DISCOVERY")
                continue
            safe.append(c)
        # V702 FINAL: registration is now owned by the canonical V531 discovery
        # emitter's Telegram delivery acknowledgement. Do not infer "emitted"
        # from the local watermark because that watermark is set before the
        # asynchronous Telegram dispatcher actually succeeds.
        result=_prev_v587_discovery(safe, snapshot)
        return result
    _v531_knowledge_notify_candidates = _v587_discovery_notify
    globals()["_v530_knowledge_notify_candidates"] = _v587_discovery_notify
    globals()["_v528_knowledge_notify_candidates"] = _v587_discovery_notify


def _v587_telegram_payload_quality_patch(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Add a compact truthful Setup Quality annotation to existing payloads."""
    try:
        p=dict(payload or {})
        fam=str(p.get("family","") or "").upper()
        if fam not in {"PULLBACK","MTF_PULLBACK"}:
            return p
        # No features are stored in canonical payloads in v4.5.86; use the
        # already-visible score/context to provide a conservative display label.
        score=float(p.get("score",0.0) or 0.0)
        htf=100.0 if p.get("regime","").upper()=="BULLISH" and score>=80 else score
        # This is display-only and intentionally conservative: do not claim
        # precision that the payload does not actually contain.
        p["setup_quality_display"] = round(min(99.0, max(0.0, score)), 1)
        return p
    except Exception:
        return dict(payload or {})

# Keep message rendering backward-compatible, but rename the headline quality
# field so the operator does not interpret it as a success probability.
_prev_v587_msg = OpportunityTelegramNotifier._message_from_payload
@classmethod
def _v587_message_from_payload(cls, payload, blocked=False):
    msg = _prev_v587_msg(payload, blocked=blocked)
    try:
        q = payload.get("setup_quality_display") if isinstance(payload,dict) else None
        if q is not None:
            msg = msg.replace(f"Quality {float(payload.get('grade_confidence',0.0) or 0.0):.0f}/100", f"Setup Quality {float(q):.0f}/100")
    except Exception:
        _v647_record_suppressed_exception()
    return msg
OpportunityTelegramNotifier._message_from_payload = _v587_message_from_payload


