def _v587_self_test() -> Dict[str, Any]:
    checks: Dict[str, bool] = {}
    try:
        checks["version"] = _v45_patch_at_least(87)
        checks["long_only"] = bool(CONFIG.get("LONG_ONLY", True)) and not bool(CONFIG.get("ALLOW_SHORTS", False))
        checks["blacklist_exact"] = _v587_is_forbidden_coin("BET/USDT")[0]
        checks["blacklist_keyword"] = _v587_is_forbidden_coin("MYCASINO/USDT")[0]
        checks["blacklist_allows_normal"] = not _v587_is_forbidden_coin("BTC/USDT")[0]
        msg_seen = []
        class _T:
            @staticmethod
            def _escape(x): return str(x)
        checks["forbidden_exact_reason"] = _v587_is_forbidden_coin("BET/USDT")[1] in {"exact_blacklist","base_blacklist"}
        c = type("C", (), {
            "family":"PULLBACK", "strategy_mode":"PULLBACK",
            "features_snapshot": {
                "volume_ratio":1.1,"rs_5m":0.02,"htf_strength":78.0,
                "structure_confidence":70.0,"retest_quality_score":70.0,"chase_atr":0.3,
                "zone_ref":100.0,
            }, "zone_ref":100.0
        })()
        try:
            import pandas as pd
            rows=[]
            for i in range(30):
                cl=100+0.08*i
                rows.append({"open":cl-0.04,"high":cl+0.20,"low":cl-0.15,"close":cl,"volume":1100.0})
            rows[-4]["low"]=101.8; rows[-3]["low"]=101.9; rows[-2]["low"]=102.1
            rows[-3]["close"]=101.8; rows[-2]["open"]=101.9; rows[-2]["close"]=102.1
            df=pd.DataFrame(rows)
            q=_v587_pullback_quality(c,{"df_5m":df})
            checks["pullback_quality_callable"] = math.isfinite(float(q.get("quality",0.0)))
            checks["pullback_quality_has_confirmations"] = int(q.get("confirmations",0)) >= 2
        except Exception:
            checks["pullback_quality_callable"] = callable(_v587_pullback_quality)
        neg = _v587_opportunity_grade(76,70,98,1.53,-0.02,0.0,"LARGE","PULLBACK")[1]
        pos = _v587_opportunity_grade(76,70,98,1.53,0.02,0.0,"LARGE","PULLBACK")[1]
        checks["negative_rs_penalized"] = float(neg) < float(pos)
        checks["jit_bounds_positive"] = float(CONFIG.get("V587_PULLBACK_MAX_ENTRY_DRIFT_UP_PCT",0.35)) > 0
        checks["jit_bounds_down"] = float(CONFIG.get("V587_PULLBACK_MAX_ATR_ENTRY_DRIFT_DOWN_PCT",0.35)) > 0
        checks["no_execution_bypass"] = callable(getattr(OrderExecutor,"submit_entry",None)) and callable(getattr(SignalBuilder,"build_and_route",None))
        return {"pass": all(bool(v) for v in checks.values()), "checks": checks}
    except Exception as exc:
        return {"pass": False, "checks": checks, "error": f"{type(exc).__name__}:{exc}"}


