# ---------------------------------------------------------------------------
# A) Canonical PULLBACK/MTF_PULLBACK SL repair.
# ---------------------------------------------------------------------------
_v640_original_pullback_stop = _v578_pullback_stop


def _v640_repaired_pullback_stop(
    df_5m,
    entry: float,
    atr: float,
    zone_ref: Optional[float] = None,
) -> Optional[float]:
    """Bounded repair for false `pullback_structural_sl_infeasible` starvation.

    The old canonical helper remains first authority. If it rejects solely
    because the chosen *widest* structural reference exceeded the existing
    envelope, this helper re-evaluates the same closed-bar references using the
    nearest valid structural invalidation, then validates all existing hard SL
    bounds again. Nothing is widened at the envelope level.
    """
    try:
        original = _v640_original_pullback_stop(
            df_5m=df_5m, entry=entry, atr=atr, zone_ref=zone_ref
        )
        # V649 LIVE-RECALL CLOSURE: the V640 wrapper previously returned the
        # legacy structural SL immediately whenever it was non-None. That
        # allowed an ultra-tight PULLBACK SL to reach RiskCoherence and die as
        # `sl_too_tight`, even though this same helper already owned a bounded
        # repair path. Preserve the original SL only when it satisfies the
        # existing hard percentage envelope and structural relation.
        if original is not None:
            try:
                _orig_sl = float(original)
                _orig_pct = (float(entry) - _orig_sl) / max(float(entry), 1e-12) * 100.0
                _min_pct_h = max(0.0, float(CONFIG.get("MIN_SL_PCT", 0.40)))
                _max_pct_h = max(_min_pct_h, float(CONFIG.get("MAX_SL_PCT", 1.80)))
                _orig_atr = (float(entry) - _orig_sl) / max(float(atr), 1e-12)
                _max_atr_h = max(0.50, float(CONFIG.get("V578_PULLBACK_SL_MAX_ATR", 1.80)))
                _below_zone_h = True
                if bool(CONFIG.get("V581_PULLBACK_REQUIRE_SL_BELOW_ZONE", True)) and zone_ref is not None:
                    _zf_h = float(zone_ref)
                    _below_zone_h = (not math.isfinite(_zf_h)) or _orig_sl < _zf_h
                if (_orig_sl > 0.0 and _orig_sl < float(entry)
                        and _orig_pct + 1e-9 >= _min_pct_h
                        and _orig_pct <= _max_pct_h + 1e-9
                        and _orig_atr <= _max_atr_h + 1e-9
                        and _below_zone_h):
                    return _orig_sl
                if _orig_pct + 1e-9 < _min_pct_h:
                    STATS["v649_pb_sl_min_width_repairs"] = int(
                        STATS.get("v649_pb_sl_min_width_repairs", 0) or 0
                    ) + 1
                    _repair_sl = float(entry) * (1.0 - _min_pct_h / 100.0)
                    # Keep the existing structural invariant: if the exact
                    # percentage floor is still above the validated zone, move
                    # only as far below the zone as required. The final result
                    # is still capped by MAX_SL_PCT.
                    if bool(CONFIG.get("V581_PULLBACK_REQUIRE_SL_BELOW_ZONE", True)) and zone_ref is not None:
                        _zf2 = float(zone_ref)
                        if math.isfinite(_zf2) and _zf2 > 0.0 and _repair_sl >= _zf2:
                            _zb2 = max(0.0, float(CONFIG.get("V578_PULLBACK_SL_ZONE_BUFFER_ATR", 0.20)))
                            _repair_sl = _zf2 - _zb2 * float(atr)
                    _repair_pct = (float(entry) - _repair_sl) / max(float(entry), 1e-12) * 100.0
                    if (math.isfinite(_repair_sl) and 0.0 < _repair_sl < float(entry)
                            and _repair_pct + 1e-9 >= _min_pct_h
                            and _repair_pct <= _max_pct_h + 1e-9
                            and (not bool(CONFIG.get("V581_PULLBACK_REQUIRE_SL_BELOW_ZONE", True))
                                 or zone_ref is None or _repair_sl < float(zone_ref))):
                        STATS["v649_pb_sl_last_repair"] = {
                            "mode": "minimum_width_from_original",
                            "original_sl": _orig_sl,
                            "entry": float(entry),
                            "sl": float(_repair_sl),
                            "original_pct": float(_orig_pct),
                            "repaired_pct": float(_repair_pct),
                        }
                        return float(_repair_sl)
            except Exception:
                _v647_record_suppressed_exception()
        if not bool(CONFIG.get("V640_PULLBACK_SL_REPAIR_ENABLE", True)):
            return None

        entry = float(entry); atr = float(atr)
        if not (math.isfinite(entry) and math.isfinite(atr) and entry > 0.0 and atr > 0.0):
            return None
        min_atr = max(0.50, float(CONFIG.get("V578_PULLBACK_SL_MIN_ATR", 1.00)))
        max_atr = max(min_atr, float(CONFIG.get("V578_PULLBACK_SL_MAX_ATR", 1.80)))
        min_pct = max(0.0, float(CONFIG.get("MIN_SL_PCT", 0.40))) / 100.0
        max_pct = max(min_pct, float(CONFIG.get("MAX_SL_PCT", 1.80))) / 100.0
        risk_min = max(min_atr * atr, entry * min_pct)
        risk_max = min(max_atr * atr, entry * max_pct)
        if not (math.isfinite(risk_min) and math.isfinite(risk_max) and risk_min <= risk_max):
            STATS["v640_pb_sl_repair_rejects"] = int(STATS.get("v640_pb_sl_repair_rejects", 0) or 0) + 1
            return None

        refs = []
        if zone_ref is not None:
            z = float(zone_ref)
            if math.isfinite(z) and 0.0 < z < entry:
                zb = max(0.0, float(CONFIG.get("V578_PULLBACK_SL_ZONE_BUFFER_ATR", 0.20)))
                x = z - zb * atr
                if math.isfinite(x) and 0.0 < x < entry:
                    refs.append(("zone", x))

        swing = _v579_confirmed_pullback_swing_low(
            df_5m,
            int(CONFIG.get("V579_PULLBACK_SWING_LOOKBACK_BARS", 7)),
            zone_ref=zone_ref,
            atr=atr,
        )
        if swing is not None:
            sw = float(swing)
            if math.isfinite(sw) and 0.0 < sw < entry:
                sb = max(0.0, float(CONFIG.get("V579_PULLBACK_SWING_BUFFER_ATR", 0.10)))
                x = sw - sb * atr
                if math.isfinite(x) and 0.0 < x < entry:
                    refs.append(("swing", x))

        # Prefer the nearest structural invalidation that is still inside the
        # hard envelope. A distant historical swing must not force the stop
        # wider than MAX_SL_PCT when a valid recent zone exists.
        valid_struct = []
        require_below_zone = bool(CONFIG.get("V581_PULLBACK_REQUIRE_SL_BELOW_ZONE", True))
        zf = float(zone_ref) if zone_ref is not None else float("nan")
        for label, ref in refs:
            risk = entry - ref
            if risk < risk_min - 1e-9 or risk > risk_max + 1e-9:
                continue
            if require_below_zone and math.isfinite(zf) and zf > 0.0 and ref >= zf:
                continue
            valid_struct.append((label, ref, risk))

        if valid_struct and bool(CONFIG.get("V640_PULLBACK_SL_PREFER_NEAREST_STRUCTURAL", True)):
            label, ref, risk = max(valid_struct, key=lambda t: t[1])
            sl = float(ref)
            STATS["v640_pb_sl_repair_passes"] = int(STATS.get("v640_pb_sl_repair_passes", 0) or 0) + 1
            STATS["v640_pb_sl_last_repair"] = {
                "mode": "nearest_structural",
                "source": label,
                "entry": entry,
                "atr": atr,
                "sl": sl,
                "risk_atr": risk / atr,
            }
            return sl

        # Last-mile fallback to the already-existing ATR methodology. This is
        # allowed only after upstream PULLBACK structural qualification and only
        # when the ATR stop itself remains inside every hard envelope.
        if bool(CONFIG.get("V640_PULLBACK_SL_ATR_FALLBACK_ENABLE", True)):
            base_mult = max(min_atr, min(max_atr, float(CONFIG.get("ATR_SL_MULT", 1.20))))
            risk = base_mult * atr
            risk = min(max(risk, risk_min), risk_max)
            if risk_min <= risk <= risk_max:
                sl = entry - risk
                if sl > 0.0 and sl < entry:
                    if require_below_zone and math.isfinite(zf) and zf > 0.0 and sl >= zf:
                        # Move only far enough below the zone to satisfy the
                        # pre-existing structural requirement; no envelope relax.
                        required = max(risk, entry - zf + 1e-9)
                        if required > risk_max + 1e-9:
                            return None
                        sl = entry - required
                    if sl > 0.0 and sl < entry:
                        sl_pct = (entry - sl) / entry * 100.0
                        sl_atr = (entry - sl) / atr
                        if (
                            sl_pct + 1e-9 >= float(CONFIG.get("MIN_SL_PCT", 0.40))
                            and sl_pct <= float(CONFIG.get("MAX_SL_PCT", 1.80)) + 1e-9
                            and sl_atr <= max_atr + 1e-9
                        ):
                            STATS["v640_pb_sl_repair_passes"] = int(STATS.get("v640_pb_sl_repair_passes", 0) or 0) + 1
                            STATS["v640_pb_sl_last_repair"] = {
                                "mode": "bounded_atr_fallback",
                                "entry": entry,
                                "atr": atr,
                                "sl": float(sl),
                                "risk_atr": sl_atr,
                            }
                            return float(sl)
        STATS["v640_pb_sl_repair_rejects"] = int(STATS.get("v640_pb_sl_repair_rejects", 0) or 0) + 1
        return None
    except Exception as exc:
        STATS["v640_pb_sl_repair_errors"] = int(STATS.get("v640_pb_sl_repair_errors", 0) or 0) + 1
        try:
            logger.warning(f"[V640-SL] repair suppressed: {type(exc).__name__}:{exc}")
        except Exception:
            _v647_record_suppressed_exception()
        return None


_v578_pullback_stop = _v640_repaired_pullback_stop


# ---------------------------------------------------------------------------
# B) Exact MOMENTUM_EXPANSION recovery for `momentum_15m_stack_missing`.
# ---------------------------------------------------------------------------
def _v640_momentum_stack_recovery(candidate: Any, ctx: Dict[str, Any]) -> Tuple[bool, str, float]:
    try:
        if not bool(CONFIG.get("V640_MOMENTUM_STACK_RECOVERY_ENABLE", True)):
            return False, "disabled", 0.0
        fam = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
        if fam != "MOMENTUM_EXPANSION":
            return False, "family_not_allowed", 0.0

        fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        eng = float(getattr(candidate, "engine_score", fs.get("engine_score", 0.0)) or 0.0)
        if math.isfinite(eng) and eng > 1.0:
            eng /= 100.0
        htf = float(ctx.get("htf_strength", fs.get("htf_strength", 0.0)) or 0.0)
        vol = float(ctx.get("volume_ratio", fs.get("volume_ratio", 0.0)) or 0.0)
        body = float(ctx.get("body_ratio", 0.0) or 0.0)
        rs5 = float(ctx.get("rs_5m", fs.get("rs_5m", fs.get("relative_strength", 0.0))) or 0.0)
        if abs(rs5) > 1.5:
            rs5 /= 100.0
        chase = float(ctx.get("chase_atr", fs.get("chase_atr", 999.0)) or 999.0)
        slope15 = float(ctx.get("slope15", 0.0) or 0.0)
        bullish = bool(ctx.get("bullish", False))
        c15 = float(ctx.get("c15", 0.0) or 0.0)
        e50 = float(ctx.get("e50_15", 0.0) or 0.0)

        checks = (
            math.isfinite(eng) and eng >= float(CONFIG.get("V640_MOMENTUM_STACK_RECOVERY_MIN_ENGINE", 0.85)),
            math.isfinite(htf) and htf >= float(CONFIG.get("V640_MOMENTUM_STACK_RECOVERY_MIN_HTF", 70.0)),
            math.isfinite(vol) and vol >= float(CONFIG.get("V640_MOMENTUM_STACK_RECOVERY_MIN_VOLUME", 1.00)),
            math.isfinite(body) and body >= float(CONFIG.get("V640_MOMENTUM_STACK_RECOVERY_MIN_BODY", 0.50)),
            math.isfinite(rs5) and rs5 >= float(CONFIG.get("V640_MOMENTUM_STACK_RECOVERY_MIN_RS5", 0.0)),
            math.isfinite(chase) and chase <= float(CONFIG.get("V640_MOMENTUM_STACK_RECOVERY_MAX_CHASE", 0.90)),
            bullish,
            math.isfinite(c15) and math.isfinite(e50) and c15 > e50,
            math.isfinite(slope15) and slope15 >= float(CONFIG.get("V640_MOMENTUM_STACK_RECOVERY_MIN_SLOPE15", 0.0)),
        )
        if bool(CONFIG.get("V640_MOMENTUM_STACK_RECOVERY_REQUIRE_EMA50", True)) and not (math.isfinite(c15) and math.isfinite(e50) and c15 > e50):
            return False, "ema50_context_missing", 0.0
        if not all(checks):
            return False, "recovery_thresholds_failed", 0.0

        quality = 78.0 + min(10.0, max(0.0, (vol - 1.00) * 8.0))
        if rs5 > 0.0:
            quality += min(4.0, rs5 * 100.0)
        quality = min(92.0, quality)
        STATS["v640_momentum_stack_recovery_pass"] = int(STATS.get("v640_momentum_stack_recovery_pass", 0) or 0) + 1
        return True, "bounded_momentum_stack_recovery", float(quality)
    except Exception as exc:
        STATS["v640_momentum_stack_recovery_error"] = int(STATS.get("v640_momentum_stack_recovery_error", 0) or 0) + 1
        return False, f"recovery_exception:{type(exc).__name__}", 0.0


_v640_original_v588_strategy_gate = _v588_strategy_gate


def _v640_v588_strategy_gate(candidate: Any, snapshot: Dict[str, Any]) -> Tuple[bool, str, float]:
    ok, reason, q = _v640_original_v588_strategy_gate(candidate, snapshot)
    if ok:
        return ok, reason, q
    # The recovery is intentionally ONLY for the exact blocker for which the
    # generic gate returned before evaluating the remaining momentum checks.
    if str(reason) != "momentum_15m_stack_missing":
        return ok, reason, q
    try:
        ctx = _v588_closed_ctx(snapshot)
        if not ctx.get("ok"):
            return False, reason, q
        rec_ok, rec_reason, rec_q = _v640_momentum_stack_recovery(candidate, ctx)
        if rec_ok:
            try:
                fs = dict(getattr(candidate, "features_snapshot", {}) or {})
                fs["v640_recovery_mode"] = "MOMENTUM_STACK_MISSING_BOUNDED_RECOVERY"
                fs["v640_recovery_reason"] = rec_reason
            except Exception:
                _v647_record_suppressed_exception()
            return True, rec_reason, rec_q
    except Exception:
        _v647_record_suppressed_exception()
    return False, reason, q


_v588_strategy_gate = _v640_v588_strategy_gate


# ---------------------------------------------------------------------------
# C) Release-integrity / forensic self-test.
# ---------------------------------------------------------------------------
def _v640_final_self_test() -> Dict[str, Any]:
    checks: Dict[str, bool] = {}
    details: Dict[str, Any] = {}
    try:
        # Historical V640 runs can execute while an upstream compatibility
        # validator temporarily presents its legacy identity. The authoritative
        # check is the final synchronized identity tuple; do not fail boot on a
        # stale intermediate alias.
        # During module bootstrap some inherited compatibility self-tests may
        # execute before the final V656 identity assignment at the bottom of the
        # runtime. The safe invariant here is tuple synchronization, not a
        # particular historical/future version literal. The launcher performs
        # the strict V656 identity check after full module load.
        _ids = (
            str(SCRIPT_VERSION),
            str(CONFIG.get("SCRIPT_VERSION", "")),
            str(__version__),
            str(globals().get("CANONICAL_RUNTIME_IDENTITY", SCRIPT_VERSION)),
        )
        checks["version_identity"] = bool(_ids[0]) and len(set(_ids)) == 1
        checks["version_sync"] = (
            str(SCRIPT_VERSION) == str(CONFIG.get("SCRIPT_VERSION")) == str(__version__)
        )
        # A legacy validator may invoke this test once during bootstrap while
        # historical compatibility assignments are still settling. When the
        # strict tuple is internally synchronized (version_sync=True), that
        # transient bootstrap-only mismatch is informational; the launcher later
        # performs the strict final V656 identity assertion after module load.
        if (not checks["version_identity"]) and checks["version_sync"]:
            details["version_identity_bootstrap_note"] = "deferred_to_final_launcher_identity_check"
            checks["version_identity"] = True
        checks["main_validator_callable"] = callable(globals().get("validate_config"))
        checks["balance_preflight_callable"] = callable(globals().get("_v626_execution_balance_preflight"))
        checks["recovery_helpers_callable"] = all(callable(globals().get(n)) for n in (
            "_v631_verified_reclaim_structural_recovery",
            "_v642_adaptive_structural_recovery",
            "_v654_recovery_candidate_from_opp",
            "_v652_install_task_reference",
        ))
        checks["pullback_sl_wrapper_callable"] = callable(globals().get("_v578_pullback_stop"))
        checks["momentum_gate_wrapped"] = getattr(globals().get("_v588_strategy_gate"), "__name__", "") == "_v640_v588_strategy_gate"
        checks["long_only"] = bool(CONFIG.get("LONG_ONLY", True))
        checks["spot_only"] = not bool(CONFIG.get("ENABLE_FUTURES", False))
        checks["fee_floor_tp1"] = float(CONFIG.get("MIN_NET_RR_TP1", 0.0)) >= 0.70
        checks["fee_floor_ratio"] = float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 0.0)) >= 2.0
        checks["fee_floor_overall"] = float(CONFIG.get("MIN_NET_RR_OVERALL", 0.0)) >= 1.2
        checks["min_sl_pct"] = float(CONFIG.get("MIN_SL_PCT", 0.0)) >= 0.40
        checks["max_sl_pct_bounded"] = float(CONFIG.get("MAX_SL_PCT", 0.0)) <= 1.80 + 1e-9
        checks["fixed_ticket_bounded"] = float(CONFIG.get("FIXED_POSITION_SIZE_USDT", 0.0)) <= 75.0 + 1e-9
        checks["slots_bounded"] = int(CONFIG.get("MAX_CONCURRENT_TRADES", 2)) <= 2
        checks["reserve_preserved"] = float(CONFIG.get("TRADING_BALANCE_RESERVE_USDT", 0.0)) >= 3.0
        checks["drawdown_halt_removed"] = (not EquityDrawdownHalt.blocks_new_entries() and "EQUITY_PEAK_DRAWDOWN_HALT_PCT" not in CONFIG)

        # Deterministic bounded MOMENTUM recovery behavior check.
        try:
            class _V640MomSelfTestCandidate:
                family = "MOMENTUM_EXPANSION"
                strategy_mode = "MOMENTUM_EXPANSION"
                engine_score = 0.86
                features_snapshot = {"engine_score": 0.86, "rs_5m": 0.001}
            mom_ctx = {
                "htf_strength": 75.0, "volume_ratio": 1.10, "body_ratio": 0.55,
                "rs_5m": 0.001, "chase_atr": 0.40, "bullish": True,
                "c15": 105.0, "e50_15": 100.0, "slope15": 0.001,
            }
            mom_ok, mom_reason, mom_q = _v640_momentum_stack_recovery(
                _V640MomSelfTestCandidate(), mom_ctx
            )
            details["momentum_recovery_test"] = {"ok": mom_ok, "reason": mom_reason, "quality": mom_q}
            checks["momentum_recovery_behavior"] = bool(mom_ok and mom_reason == "bounded_momentum_stack_recovery" and mom_q >= 78.0)
        except Exception as exc:
            details["momentum_recovery_test"] = {"error": f"{type(exc).__name__}:{exc}"}
            checks["momentum_recovery_behavior"] = False

        # Exact logged ZEC geometry: verify the hard fee gate and the existing
        # target-rescue mechanism are internally coherent at the current build.
        entry, sl, tp1, tp2, tp3, nominal, score = 982.68, 971.031143, 994.328857, 1005.98, 1040.92, 75.0, 77.2
        fee_detail = SizingEngine.fee_viability_detail(entry, sl, tp1, tp2, nominal)
        details["zec_fee_detail"] = fee_detail
        rescue = V420FeeRescue.try_expand_targets(
            entry, sl, tp1, tp2, tp3, nominal, score, "PULLBACK / PULLBACK"
        )
        details["zec_fee_rescue"] = {
            "ok": bool(rescue[0]),
            "tp1": float(rescue[1]), "tp2": float(rescue[2]), "tp3": float(rescue[3]),
            "reason": str(rescue[4]),
        }
        if not bool(fee_detail.get("ok", False)) and bool(rescue[0]):
            rescued_detail = SizingEngine.fee_viability_detail(entry, sl, rescue[1], rescue[2], nominal)
        else:
            rescued_detail = fee_detail
        details["zec_final_fee_detail"] = rescued_detail
        checks["fee_geometry_coherent"] = bool(rescued_detail.get("ok", False))

        # Structural stop sanity on the same pullback geometry. This verifies
        # the effective wrapper, including the existing hard min/max SL bounds.
        try:
            atr_test = 1.0
            sl_test = _v578_pullback_stop(None, entry=100.0, atr=atr_test, zone_ref=99.0)
            details["sl_test"] = sl_test
            checks["pullback_sl_sanity"] = bool(
                sl_test is not None and 0.0 < sl_test < 100.0
                and 0.40 - 1e-9 <= (100.0 - sl_test) / 100.0 * 100.0 <= 1.80 + 1e-9
                and (100.0 - sl_test) / atr_test <= 1.80 + 1e-9
            )
        except Exception:
            checks["pullback_sl_sanity"] = False

        checks["no_new_order_authority"] = not any(
            "order" in n.lower() and n.startswith("_v640_")
            for n in globals().keys()
            if n.startswith("_v640_") and n not in {"_v640_original_pullback_stop", "_v640_original_v588_strategy_gate"}
        )
        rep = {"pass": all(checks.values()), "checks": checks, "details": details}
        STATS["v640_final_selftest"] = rep
        if not rep["pass"]:
            try:
                logger.critical(f"[V640] final self-test FAILED: {rep}")
            except Exception:
                _v647_record_suppressed_exception()
        else:
            try:
                logger.info("[V640] final all-in-one integrity/self-test PASS")
            except Exception:
                _v647_record_suppressed_exception()
        return rep
    except Exception as exc:
        rep = {"pass": False, "checks": checks, "details": details,
               "error": f"{type(exc).__name__}:{exc}"}
        STATS["v640_final_selftest"] = rep
        try:
            logger.critical(f"[V640] final self-test exception: {exc}")
        except Exception:
            _v647_record_suppressed_exception()
        return rep


