# v4.5.99-V641 FINAL — LIVE PRIORITY / SELECTED→QUEUE FORENSICS CLOSURE
# -----------------------------------------------------------------------------
# Purpose:
#   1) Prefer candidates with stronger CURRENT quality instead of letting the
#      raw engine/composite score dominate selection when key live factors are
#      materially weak (volume/HTF/structure/RS/chase).
#   2) Preserve the canonical SignalBuilder / PreSend / Execution authorities.
#      This layer only re-ranks and observes; it never authorizes an order.
#   3) Make every execution handoff attributable. A fresh blocker is recorded
#      for the CURRENT attempt so stale symbol rejection state cannot masquerade
#      as the reason for a later Selected→Queue loss.
#   4) Keep the existing refill/reserve/cooldown/fee/drawdown/safety gates intact.
# =============================================================================

V641_FINAL_ENABLED = True
V641_FINAL_IDENTITY = "4.5.99-V642-FINAL-LIVE-PRIORITY-QUEUE-PRECISION-CLOSURE"

# Small, fixed policy set: deliberately not exposed as a large new CONFIG tree.
V641_MAX_GLOBAL_SCORE_ADJ = 0.070
V641_STRONG_QUALITY_BONUS = 0.020
V641_WEAK_PB_PENALTY = 0.025
V641_MIN_EXEC_ATTEMPTS = 1
V641_MAX_EXEC_ATTEMPTS = 12
V641_ATTRIBUTION_MAX_AGE_SEC = 8.0


def _v641_norm01(value, *, pct=False, default=0.5):
    try:
        x = float(value)
        if not math.isfinite(x):
            return float(default)
        if pct:
            return _clamp(x / 100.0, 0.0, 1.0)
        if x > 1.5:
            x /= 100.0
        return _clamp(x, 0.0, 1.0)
    except Exception:
        return float(default)


def _v641_htf01(f):
    try:
        if f.get("htf_strength") is not None:
            return _v641_norm01(f.get("htf_strength"), pct=True, default=0.5)
        raw = f.get("htf_alignment")
        x = float(raw)
        if not math.isfinite(x):
            return 0.5
        if -1e-9 <= x <= 1.0 + 1e-9:
            return _clamp(x, 0.0, 1.0)
        return _clamp(x / 100.0, 0.0, 1.0)
    except Exception:
        return 0.5


def _v641_rs01(f):
    try:
        raw = f.get("rs_5m", f.get("relative_strength", f.get("rs_score_val", 0.0)))
        x = float(raw)
        if not math.isfinite(x):
            return 0.45
        if abs(x) > 1.5:
            x /= 100.0
        # Positive RS is useful; negative RS remains a real penalty.
        return _clamp(0.50 + (x / 0.04) * 0.50, 0.0, 1.0)
    except Exception:
        return 0.45


def _v641_volume01(f):
    try:
        v = float(f.get("volume_ratio", float("nan")))
        if not math.isfinite(v):
            v = float(f.get("volume_quality", 0.5) or 0.5)
            return _v641_norm01(v, default=0.5)
        # Closed-bar volume ratio: below ~0.5 is weak, 1.0 is healthy,
        # >=1.3 is strong. This is ranking support only.
        if v <= 0.50:
            return 0.05 * max(0.0, v / 0.50)
        if v < 0.80:
            return 0.05 + (v - 0.50) / 0.30 * 0.35
        if v < 1.00:
            return 0.40 + (v - 0.80) / 0.20 * 0.30
        if v < 1.30:
            return 0.70 + (v - 1.00) / 0.30 * 0.20
        return 0.90 + min(0.10, (v - 1.30) / 1.00)
    except Exception:
        return 0.50


def _v641_chase01(f, candidate):
    try:
        x = float(f.get("chase_atr", 0.0) or 0.0)
        if not math.isfinite(x):
            x = 0.0
        if x <= 0.25:
            return 1.0
        if x <= 0.50:
            return 0.90
        if x <= 0.90:
            return 0.65
        if x <= 1.20:
            return 0.30
        return 0.0
    except Exception:
        return 0.70


def _v641_live_quality(r):
    """Return bounded current-candidate quality in 0..1 for ranking only."""
    try:
        c = getattr(r, "candidate", r)
        f = dict(getattr(c, "features_snapshot", {}) or {})
        htf = _v641_htf01(f)
        vol = _v641_volume01(f)
        rs = _v641_rs01(f)
        structure = _v641_norm01(f.get("structure_quality", 0.60), default=0.60)
        retest = _v641_norm01(f.get("retest_quality", 0.50), default=0.50)
        phase = _v641_norm01(f.get("phase_fit", 0.75), default=0.75)
        local = _v641_norm01(f.get("local_fit", 0.75), default=0.75)
        chase = _v641_chase01(f, c)
        q = (
            0.24 * htf +
            0.24 * vol +
            0.14 * rs +
            0.14 * structure +
            0.09 * retest +
            0.08 * chase +
            0.04 * phase +
            0.03 * local
        )
        fam = str(getattr(c, "strategy_mode", "") or getattr(c, "family", "") or "").upper()
        if "PULLBACK" in fam:
            # Pullback specifically needs participation; don't let an extreme
            # engine score erase materially weak volume in arbitration.
            if vol < 0.42:
                q -= 0.08
            elif vol < 0.58:
                q -= 0.04
            if htf < 0.45:
                q -= 0.03
        return _clamp(q, 0.0, 1.0), {
            "htf": htf, "volume": vol, "rs": rs,
            "structure": structure, "retest": retest,
            "chase": chase, "phase": phase, "local": local,
        }
    except Exception:
        return 0.50, {}


# -----------------------------------------------------------------------------
# A) Canonical global arbitration remains authoritative; only its ranking score
#    receives a small quality-aware adjustment. No gate is bypassed.
# -----------------------------------------------------------------------------
try:
    _v641_original_global_candidate_score = GlobalOpportunityArbiter._candidate_score
except Exception:
    _v641_original_global_candidate_score = None

if callable(_v641_original_global_candidate_score):
    def _v641_global_candidate_score(r):
        base_score = float(_v641_original_global_candidate_score(r))
        q, d = _v641_live_quality(r)
        # Translate quality around a neutral 0.62 into a bounded score aid.
        adj = (q - 0.62) * 0.18
        fam = str(getattr(r.candidate, "strategy_mode", "") or getattr(r.candidate, "family", "") or "").upper()
        if "PULLBACK" in fam and d.get("volume", 0.5) < 0.42:
            adj -= V641_WEAK_PB_PENALTY
        if q >= 0.82 and d.get("htf", 0.0) >= 0.70 and d.get("structure", 0.0) >= 0.60:
            adj += V641_STRONG_QUALITY_BONUS
        adj = _clamp(adj, -V641_MAX_GLOBAL_SCORE_ADJ, V641_MAX_GLOBAL_SCORE_ADJ)
        score = _clamp(base_score + adj, 0.0, 1.0)
        try:
            fs = getattr(r.candidate, "features_snapshot", None)
            if isinstance(fs, dict):
                fs["v641_live_quality"] = float(q)
                fs["v641_quality_adjustment"] = float(adj)
        except Exception:
            _v647_record_suppressed_exception()
        return score
    GlobalOpportunityArbiter._candidate_score = staticmethod(_v641_global_candidate_score)


# -----------------------------------------------------------------------------
# B) Selected→Queue exact attribution. This wrapper is telemetry only.
#    It does NOT retry, submit, cancel, alter gates, or change return values.
# -----------------------------------------------------------------------------
try:
    _v641_original_signal_builder = SignalBuilder.build_and_route
except Exception:
    _v641_original_signal_builder = None


def _v641_now_epoch():
    try:
        return float(MONO_NOW())
    except Exception:
        return 0.0


def _v641_record_handoff(symbol, reason, stage="selected_handoff", *, candidate=None, extra=None):
    try:
        sym = str(symbol or "")
        rsn = str(reason or "handoff_no_attribution")
        recs = STATS.setdefault("v641_handoff_rejects", defaultdict(int))
        recs[rsn] += 1
        STATS["v641_last_handoff_symbol"] = sym
        STATS["v641_last_handoff_reason"] = rsn
        STATS["v641_last_handoff_stage"] = str(stage or "selected_handoff")
        STATS["v641_last_handoff_ts"] = WALL_NOW()
        ctx = dict(extra or {})
        ctx.update({
            "symbol": sym,
            "reason": rsn,
            "stage": str(stage or "selected_handoff"),
            "ts": WALL_NOW(),
            "engine_score": float(getattr(candidate, "engine_score", 0.0) or 0.0) * 100.0 if candidate is not None else None,
            "family": str(getattr(candidate, "family", "") or "") if candidate is not None else "",
        })
        hist = STATS.setdefault("v641_handoff_history", deque(maxlen=256))
        hist.append(ctx)
    except Exception:
        _v647_record_suppressed_exception()


if callable(_v641_original_signal_builder):
    async def _v641_signal_builder_with_attribution(exchange, symbol, market_data, preferred_candidate=None):
        # Execution-loop calls are marked by the existing canonical loop.
        tracked = False
        try:
            last_sym = str(STATS.get("v535_last_attempt_symbol", "") or "")
            tracked = last_sym == str(symbol or "")
        except Exception:
            tracked = False
        start = _v641_now_epoch()
        before_q = int(STATS.get("signals_queued", 0) or 0)
        before_l = int(STATS.get("v534_live_ready", 0) or 0)
        before_b = str(STATS.get("v545_last_builder_blocker", "") or "")
        before_rb = str(STATS.get("v534_last_route_block_reason", "") or "")
        before_rr = None
        try:
            before_rr = dict((STATS.get("v523_last_rejection_by_symbol") or {}).get(str(symbol)) or {})
        except Exception:
            before_rr = None
        result = await _v641_original_signal_builder(
            exchange, symbol, market_data, preferred_candidate=preferred_candidate
        )
        if tracked:
            try:
                after_q = int(STATS.get("signals_queued", 0) or 0)
                after_l = int(STATS.get("v534_live_ready", 0) or 0)
                success = (after_q > before_q) or (after_l > before_l) or (result is not None)
                STATS["v641_handoff_attempts"] = int(STATS.get("v641_handoff_attempts", 0) or 0) + 1
                STATS["v641_handoff_success"] = int(STATS.get("v641_handoff_success", 0) or 0) + (1 if success else 0)
                if not success:
                    now = _v641_now_epoch()
                    # Prefer a blocker changed during THIS call.
                    cur_b = str(STATS.get("v545_last_builder_blocker", "") or "")
                    cur_rb = str(STATS.get("v534_last_route_block_reason", "") or "")
                    fresh_rec = None
                    try:
                        rec = (STATS.get("v523_last_rejection_by_symbol") or {}).get(str(symbol))
                        if isinstance(rec, dict):
                            ts = float(rec.get("ts_mono", rec.get("mono_ts", 0.0)) or 0.0)
                            if ts > 0 and (now - ts) <= V641_ATTRIBUTION_MAX_AGE_SEC:
                                fresh_rec = rec
                    except Exception:
                        fresh_rec = None
                    if cur_b and cur_b != before_b:
                        reason, stage = cur_b, "builder"
                    elif cur_rb and cur_rb != before_rb:
                        reason, stage = cur_rb, "route"
                    elif fresh_rec and fresh_rec != before_rr:
                        reason = str(fresh_rec.get("reason") or fresh_rec.get("reject_reason") or "handoff_reject")
                        stage = str(fresh_rec.get("stage") or "builder")
                    else:
                        reason, stage = "handoff_no_new_rejection_record", "selected_handoff"
                    _v641_record_handoff(
                        symbol, reason, stage, candidate=preferred_candidate,
                        extra={
                            "duration_sec": max(0.0, now - start),
                            "preferred": bool(preferred_candidate is not None),
                        },
                    )
                    # Replace stale per-symbol attribution with the exact
                    # current attempt; the existing main loop will then bucket
                    # the current failure rather than an old historical one.
                    try:
                        mp = STATS.setdefault("v523_last_rejection_by_symbol", {})
                        mp[str(symbol)] = {
                            "ts_mono": now,
                            "ts": WALL_NOW(),
                            "reason": str(reason),
                            "stage": str(stage),
                            "score": float(getattr(preferred_candidate, "engine_score", 0.0) or 0.0) * 100.0 if preferred_candidate is not None else 0.0,
                        }
                    except Exception:
                        _v647_record_suppressed_exception()
                return result
            except Exception as exc:
                _v641_record_handoff(symbol, f"telemetry_exception:{type(exc).__name__}", "telemetry", candidate=preferred_candidate)
        return result
    SignalBuilder.build_and_route = staticmethod(_v641_signal_builder_with_attribution)



# =============================================================================
# v4.5.99-V642 FINAL — CANONICAL PRECISION PRESELECTION / ALTERNATE HANDOFF
# -----------------------------------------------------------------------------
# Root cause closed from live logs:
#   High Engine/Composite candidates were being globally selected, then the
#   canonical PULLBACK precision gate rejected them for deterministic blockers
#   such as retest_weak. This could exhaust Selected slots while stronger
#   candidates remained in the prequalified pool.
#
# This closure:
#   1) Applies ONLY a conservative preselection mirror of already-known
#      canonical PULLBACK hard floors. It NEVER invents market data.
#   2) Rejects a candidate before global selection ONLY when the candidate
#      snapshot explicitly contains a value that the canonical gate itself
#      would reject (e.g. retest < floor). Missing values are NOT rejected here.
#   3) Filters same-symbol alternates using the same deterministic preview so
#      a known-doomed alternate cannot consume an execution attempt.
#   4) Captures the exact current canonical precision reason during the
#      Selected→Queue handoff so "handoff_no_new_rejection_record" cannot hide
#      a real PULLBACK precision blocker.
#   5) Keeps SignalBuilder, PreSend, balance, SL, execution, drawdown,
#      blacklist, fee and all other safety authorities unchanged.
# =============================================================================

V642_FINAL_ENABLED = True
V642_FINAL_IDENTITY = "4.5.99-V642-FINAL-LIVE-PRIORITY-QUEUE-PRECISION-CLOSURE"
V642_PRECISION_PREVIEW_ENABLE = True


def _v642_feature_float(fs, *keys):
    for k in keys:
        try:
            if isinstance(fs, dict) and fs.get(k) is not None:
                x = float(fs.get(k))
                if math.isfinite(x):
                    return x
        except Exception:
            continue
    return None



# =============================================================================
# V702 FINAL — PULLBACK PRECISION-COHERENCE / FALSE-REJECT CLOSURE
# -----------------------------------------------------------------------------
# Purpose: recover missing/aliased quality facts from the SAME prepared market
# snapshot before the unchanged hard V587 contract evaluates them.
#
# This layer NEVER:
#   * lowers a PULLBACK hard floor;
#   * accepts an unknown metric;
#   * fetches new market data;
#   * overrides a genuinely failing metric;
#   * bypasses SignalBuilder / PreSend / Balance / Liquidity / Fee / SL / Risk.
# It only prevents a representation or derivation mismatch from rejecting a
# candidate that already has sufficient evidence in the exact snapshot.
# =============================================================================
def _v702_pullback_precision_facts(candidate, market_data=None):
    md = dict(market_data or {}) if isinstance(market_data, dict) else {}
    c = getattr(candidate, "candidate", candidate)
    fs = dict(getattr(c, "features_snapshot", {}) or {})
    out = {"family": str(getattr(c, "family", fs.get("family", "")) or "").upper(),
           "sources": {}}

    def _pick(*keys):
        for key in keys:
            try:
                value = fs.get(key)
                if value is None:
                    continue
                value = float(value)
                if math.isfinite(value):
                    return value, str(key)
            except Exception:
                continue
        return None, ""

    htf, htf_src = _pick("htf_strength", "effective_htf_strength")
    # Recover a missing/zero HTF strength from already-prepared 1H/4H data.
    if htf is None or htf <= 0.0:
        try:
            resolver = globals().get("_v690_resolve_htf_strength")
            if callable(resolver):
                symbol = str(getattr(c, "symbol", "") or "")
                resolved, rsrc, _age = resolver(symbol, md, c)
                if resolved is not None and math.isfinite(float(resolved)) and float(resolved) > 0.0:
                    htf = float(resolved); htf_src = f"derived:{rsrc}"
            if htf is None or htf <= 0.0:
                fallback = globals().get("_v453_htf_strength_from_snapshot")
                if callable(fallback):
                    resolved = fallback(md)
                    if resolved is not None and math.isfinite(float(resolved)) and float(resolved) > 0.0:
                        htf = float(resolved); htf_src = "derived:V453"
        except Exception:
            pass

    structure, structure_src = _pick(
        "structure_score", "structure", "structure_confidence", "structure_quality"
    )
    retest, retest_src = _pick(
        "retest_score", "retest", "retest_quality_score", "retest_quality"
    )
    vol, vol_src = _pick("volume_ratio", "vol_ratio", "volume")
    rs, rs_src = _pick("rs_5m", "rs", "rs_score_val", "relative_strength")
    chase, chase_src = _pick("chase_atr", "chase")

    df5 = md.get("df_5m")
    btc5 = md.get("df_btc_5m")

    # Derive volume only from the current closed 5m candle and its current
    # lookback window. Missing/invalid history remains a hard reject later.
    if vol is None:
        try:
            now = float(df5["volume"].iloc[-2])
            base = float(df5["volume"].iloc[-22:-2].mean())
            if math.isfinite(now) and math.isfinite(base) and base > 0.0:
                vol = now / base; vol_src = "derived:closed_5m_volume"
        except Exception:
            pass

    # Derive RS-vs-BTC from the exact shared BTC snapshot when the candidate
    # carries no usable RS field. This does not soften the RS >= 0 hard floor.
    if rs is not None and abs(rs) > 1.5:
        rs /= 100.0; rs_src = f"normalized:{rs_src}"
    if rs is None:
        try:
            rs_fn = globals().get("_v658_rs_value")
            if callable(rs_fn):
                rb = int(CONFIG.get("V658_RS_SHORT_LOOKBACK", 6))
                resolved = rs_fn(df5, btc5, rb)
                if resolved is not None and math.isfinite(float(resolved)):
                    rs = float(resolved); rs_src = "derived:closed_5m_vs_btc"
        except Exception:
            pass

    # Derive chase from the exact candidate zone + closed 5m ATR. This is only
    # an alternate representation of the already-existing chase fact.
    if chase is None:
        try:
            atr_fn = getattr(Indicators, "atr", None)
            if callable(atr_fn) and df5 is not None and len(df5) >= 30:
                atr_s = atr_fn(df5, int(CONFIG.get("ATR_PERIOD", 14)))
                atr = float(atr_s.iloc[-2])
                zone = fs.get("zone_ref", getattr(c, "zone_ref", None))
                entry = getattr(c, "entry_ref", getattr(c, "entry", None))
                if zone is not None and entry is not None and math.isfinite(float(zone)) and math.isfinite(float(entry)) and math.isfinite(atr) and atr > 0:
                    chase = abs(float(entry) - float(zone)) / atr
                    chase_src = "derived:entry_zone_closed_5m_atr"
        except Exception:
            pass

    for key, value, source in (
        ("htf_strength", htf, htf_src),
        ("structure", structure, structure_src),
        ("retest", retest, retest_src),
        ("volume_ratio", vol, vol_src),
        ("rs_5m", rs, rs_src),
        ("chase_atr", chase, chase_src),
    ):
        out[key] = value
        out["sources"][key] = source or "candidate_snapshot"

    recovered = [k for k,v in out["sources"].items() if isinstance(v, str) and v.startswith("derived:")]
    if recovered:
        STATS["v702_pb_precision_context_recoveries"] = int(STATS.get("v702_pb_precision_context_recoveries", 0) or 0) + 1
        for key in recovered:
            STATS[f"v702_pb_precision_recovered.{key}"] = int(STATS.get(f"v702_pb_precision_recovered.{key}", 0) or 0) + 1
    out["recovered_fields"] = recovered
    return out


def _v642_pullback_precision_preview(candidate):
    """Conservative pre-ranking preview using the same exact prepared-snapshot
    metric aliases/derivations as the final PULLBACK precision authority.

    No quality floor is changed here. The preview exists only to remove a
    duplicate representation gate that could reject before the canonical gate
    gets the exact same facts.
    """
    out = {"family": "", "known_blocker": False}
    try:
        c = getattr(candidate, "candidate", candidate)
        fam = str(getattr(c, "strategy_mode", "") or getattr(c, "family", "") or "").upper()
        out["family"] = fam
        if fam not in {"PULLBACK", "MTF_PULLBACK"}:
            return True, "not_applicable", out
        if not V642_PRECISION_PREVIEW_ENABLE:
            return True, "disabled", out
        facts = _v702_pullback_precision_facts(c, getattr(candidate, "market_data", None) or {})
        # Ranking preview uses the canonical V587 floors exactly; it no longer
        # carries the historical hard-coded HTF=55 mirror that disagreed with
        # the final V702 floor of CONFIG[V587_PULLBACK_MIN_HTF]=50.
        required = (
            ("htf_below_floor", facts.get("htf_strength"), float(CONFIG.get("V587_PULLBACK_MIN_HTF", 50.0)), "min"),
            ("volume_below_floor", facts.get("volume_ratio"), float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO", 0.85)), "min"),
            ("rs_negative", facts.get("rs_5m"), float(CONFIG.get("V587_PULLBACK_MIN_RS", 0.0)), "min"),
            ("structure_weak", facts.get("structure"), float(CONFIG.get("V587_PULLBACK_MIN_STRUCTURE_SCORE", 45.0)), "min"),
            ("retest_weak", facts.get("retest"), float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE", 45.0)), "min"),
            ("chase_too_high", facts.get("chase_atr"), float(CONFIG.get("V587_PULLBACK_MAX_FINAL_CHASE_ATR", 0.90)), "max"),
        )
        out["facts_sources"] = facts.get("sources", {})
        out["recovered_fields"] = facts.get("recovered_fields", [])
        for reason, value, floor, op in required:
            if value is None:
                # Do not invent a reject here; the final canonical quality path
                # will fail closed if the metric cannot actually be supplied.
                continue
            failed = value < floor if op == "min" else value > floor
            if failed:
                out.update({"known_blocker": True, "reason": reason,
                            "value": float(value), "floor": float(floor)})
                return False, reason, out
        setup = _v642_feature_float(getattr(c, "features_snapshot", {}) or {}, "v587_setup_quality", "setup_quality")
        if setup is not None and setup < float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY", 72.0)):
            out.update({"known_blocker": True, "reason": "setup_quality_below_floor",
                        "value": float(setup), "floor": float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY", 72.0))})
            return False, "setup_quality_below_floor", out
        return True, "preview_pass", out
    except Exception as exc:
        # Preview uncertainty remains non-authorizing; preserve the previous
        # conservative behavior and let the final hard gate decide.
        return True, f"preview_exception:{type(exc).__name__}", out


# Patch the canonical global selection entrypoint with a conservative,
# snapshot-only precision filter. Original selector remains final authority.
try:
    _v642_orig_global_select = GlobalOpportunityArbiter.select
except Exception:
    _v642_orig_global_select = None

if callable(_v642_orig_global_select):
    def _v642_global_select(cls, ranked, max_winners=3):
        if not V642_FINAL_ENABLED or not V642_PRECISION_PREVIEW_ENABLE:
            return _v642_orig_global_select(ranked, max_winners)

        kept = []
        rejected = defaultdict(int)
        for r in list(ranked or []):
            ok, reason, detail = _v642_pullback_precision_preview(r)
            if ok:
                kept.append(r)
                continue
            rejected[str(reason)] += 1
            try:
                sym = str(getattr(getattr(r, "candidate", None), "symbol", "") or "")
                STATS["v642_precision_preview_rejects"] = int(
                    STATS.get("v642_precision_preview_rejects", 0) or 0
                ) + 1
                STATS[f"v642_precision_preview_reason.{reason}"] = int(
                    STATS.get(f"v642_precision_preview_reason.{reason}", 0) or 0
                ) + 1
                _v516_record_selection_event(
                    "SELECTION", f"canonical_preview:{reason}", r,
                    extra={"preview": detail, "source": "V642"}
                )
                logger.info(
                    "[V642-PREVIEW-REJECT] %s family=%s reason=%s value=%s floor=%s",
                    sym, detail.get("family", ""), reason,
                    detail.get("value", ""), detail.get("floor", "")
                )
            except Exception:
                _v647_record_suppressed_exception()
