# Make V642's snapshot-only preview fail closed exactly where the canonical
# PULLBACK precision contract fails closed. This prevents "unknown retest"
# candidates from consuming global winners.
def _v643_strict_precision_preview(candidate):
    """Strict preselection parity using exact V702 PULLBACK floors and
    same-snapshot recoveries; genuinely weak metrics still reject."""
    out = {"family": "", "known_blocker": False}
    try:
        c = getattr(candidate, "candidate", candidate)
        fam = str(getattr(c, "strategy_mode", "") or getattr(c, "family", "") or "").upper()
        out["family"] = fam
        if fam not in {"PULLBACK", "MTF_PULLBACK"}:
            return True, "not_applicable", out
        facts = _v702_pullback_precision_facts(c, getattr(candidate, "market_data", None) or {})
        required = (
            ("htf_below_floor", facts.get("htf_strength"), float(CONFIG.get("V587_PULLBACK_MIN_HTF", 50.0)), "min"),
            ("volume_below_floor", facts.get("volume_ratio"), float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO", 0.85)), "min"),
            ("rs_negative", facts.get("rs_5m"), float(CONFIG.get("V587_PULLBACK_MIN_RS", 0.0)), "min"),
            ("structure_weak", facts.get("structure"), float(CONFIG.get("V587_PULLBACK_MIN_STRUCTURE_SCORE", 45.0)), "min"),
            ("retest_weak", facts.get("retest"), float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE", 45.0)), "min"),
            ("chase_too_high", facts.get("chase_atr"), float(CONFIG.get("V587_PULLBACK_MAX_FINAL_CHASE_ATR", 0.90)), "max"),
        )
        out["facts_sources"] = facts.get("sources", {})
        out["recovered_fields"] = facts.get("recovered_fields", [])
        for reason, value, floor, op in required:
            if value is None:
                # Missing data is not a positive signal, but the preview must
                # not reject before the canonical final gate has the opportunity
                # to derive the same fact from the exact prepared snapshot.
                # The final V587 authority remains fail-closed on unresolved data.
                out.setdefault("missing_metrics", []).append(reason)
                continue
            failed = value < floor if op == "min" else value > floor
            if failed:
                out.update({"known_blocker": True, "reason": reason, "value": float(value), "floor": float(floor)})
                return False, reason, out
        setup = _v642_feature_float(getattr(c, "features_snapshot", {}) or {}, "v587_setup_quality", "setup_quality")
        if setup is not None and setup < float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY", 72.0)):
            out.update({"known_blocker": True, "reason": "setup_quality_below_floor", "value": float(setup),
                        "floor": float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY", 72.0))})
            return False, "setup_quality_below_floor", out
        return True, "preview_pass", out
    except Exception as exc:
        return False, f"preview_exception:{type(exc).__name__}", out


_v642_pullback_precision_preview = _v643_strict_precision_preview

