def _v644_current_canonical_recheck(candidate, market_data):
    fam = str(getattr(candidate, "strategy_mode", "") or getattr(candidate, "family", "") or "").upper()
    if fam not in {"PULLBACK", "MTF_PULLBACK"}:
        return True, "not_applicable", {}
    if not bool(CONFIG.get("V644_CURRENT_CANONICAL_PREEXEC_ENABLE", True)):
        return True, "disabled", {}
    if not isinstance(market_data, dict):
        return True, "unavailable_market_data", {}
    try:
        q = _v587_pullback_quality(candidate, market_data)
    except Exception as exc:
        STATS["v644_preexec_recheck_errors"] = int(STATS.get("v644_preexec_recheck_errors", 0) or 0) + 1
        return True, f"recheck_unavailable:{type(exc).__name__}", {"error": f"{type(exc).__name__}:{exc}"}
    if not isinstance(q, dict) or "ok" not in q:
        return True, "unavailable_result", {}
    if bool(q.get("ok")):
        return True, str(q.get("reason") or "pass"), dict(q)
    return False, str(q.get("reason") or "pullback_precision_reject"), dict(q)

