    _v645_original_run_engine_safe = MultiStrategyEngine._run_engine_safe
    if not getattr(_v645_original_run_engine_safe, "_v645_context_wrapper", False):
        @staticmethod
        def _v645_run_engine_safe(engine_cls, snapshot):
            rows = list(_v645_original_run_engine_safe(engine_cls, snapshot) or [])
            if not rows:
                return rows
            for c in rows:
                try:
                    fs = dict(getattr(c, "features_snapshot", {}) or {})
                    # Context facts come from the exact snapshot the engine saw.
                    for key in ("htf_strength", "volume_ratio", "rs_5m", "chase_atr",
                                "structure_quality", "retest_quality_score", "retest_quality",
                                "liquidity_tier", "tier", "regime", "local_regime",
                                "market_phase", "macro_regime", "bearish_severity"):
                        if fs.get(key) in (None, "") and isinstance(snapshot, dict) and snapshot.get(key) not in (None, ""):
                            fs[key] = snapshot.get(key)
                    fs.setdefault("mse_engine_id", str(getattr(c, "engine_id", "") or engine_cls.engine_id))
                    fs.setdefault("mse_family", _v645_family_of(c))
                    fs.setdefault("mse_strategy_mode", _v645_mode_of(c))
                    # Preserve the candidate's own family as authoritative.
                    fs["v645_family_identity"] = _v645_family_of(c)
                    fs["v645_engine_identity"] = str(getattr(c, "engine_id", "") or "")
                    # Derive chase only when the snapshot has enough closed-bar data.
                    if fs.get("chase_atr") in (None, ""):
                        try:
                            d5 = snapshot.get("df_5m") if isinstance(snapshot, dict) else None
                            if d5 is not None and len(d5) >= 24:
                                atr_s = Indicators.atr(d5, CONFIG["ATR_PERIOD"])
                                atr = float(atr_s.iloc[-2]) if atr_s is not None else 0.0
                                px = float(d5["close"].iloc[-2])
                                entry = float(getattr(c, "entry_ref", px) or px)
                                if math.isfinite(atr) and atr > 0 and math.isfinite(px) and px > 0:
                                    fs["chase_atr"] = abs(entry - px) / atr
                        except Exception:
                            _v647_record_suppressed_exception()
                    c.features_snapshot = fs
                except Exception:
                    continue
            return rows
        _v645_run_engine_safe._v645_context_wrapper = True
        MultiStrategyEngine._run_engine_safe = _v645_run_engine_safe
        STATS["v645_mse_context_wrapper_installed"] = True
