_V646_CYCLE_BLOCKER_EVENTS = deque(maxlen=int(CONFIG.get("V646_CURRENT_CYCLE_BLOCKER_HISTORY_MAX", 128)))


def _v646_cycle_blocker_record(symbol: str, family: str, reason: str, stage: str,
                               source: str = "CURRENT") -> None:
    if not bool(CONFIG.get("V646_CURRENT_CYCLE_FORENSICS_ENABLE", True)):
        return
    try:
        row = {"ts_mono": MONO_NOW(), "ts_wall": WALL_NOW(), "symbol": str(symbol or ""),
               "family": str(family or ""), "reason": str(reason or "unknown"),
               "stage": str(stage or "unknown"), "source": str(source or "CURRENT")}
        _V646_CYCLE_BLOCKER_EVENTS.append(row)
        STATS["v646_current_cycle_last_blocker"] = dict(row)
        key = f"v646_cycle_blocker.{row['stage']}.{row['reason']}"
        STATS[key] = int(STATS.get(key, 0) or 0) + 1
    except Exception:
        _v647_record_suppressed_exception()


def _v646_cycle_blocker_snapshot(window_sec: float = 900.0) -> Dict[str, Any]:
    try:
        cutoff = MONO_NOW() - max(1.0, float(window_sec))
        rows = [r for r in list(_V646_CYCLE_BLOCKER_EVENTS)
                if float(r.get("ts_mono", 0.0)) >= cutoff]
        counts = defaultdict(int)
        for r in rows:
            counts[f"{r.get('stage','?')}:{r.get('reason','?')}"] += 1
        top = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)[:5]
        return {"count": len(rows), "top": top, "last": dict(rows[-1]) if rows else {}}
    except Exception:
        return {"count": 0, "top": [], "last": {}}


def _v646_current_cycle_truth_line() -> str:
    try:
        snap = _v646_cycle_blocker_snapshot(900.0)
        last = snap.get("last") or {}
        if not last:
            return "[V646-TRUTH] current_blocker=none"
        return (
            f"[V646-TRUTH] current_blocker={str(last.get('stage','?'))}:{str(last.get('reason','?'))[:120]} "
            f"family={str(last.get('family','?'))[:40]} symbol={str(last.get('symbol','?'))[:30]} "
            f"source={str(last.get('source','?'))} count={int(snap.get('count',0) or 0)}"
        )
    except Exception:
        return "[V646-TRUTH] current_blocker=unavailable"


