def _v646_extract_current_root_from_stats(symbol: str, since_wall: float, start_mono: Optional[float] = None) -> Tuple[str, str, str]:
    """Return only same-attempt evidence: (stage, reason, source)."""
    try:
        rec = (STATS.get("v523_last_rejection_by_symbol") or {}).get(str(symbol))
        if isinstance(rec, dict):
            ts = float(rec.get("ts", rec.get("ts_wall", 0.0)) or 0.0)
            if ts >= float(since_wall) - 0.50:
                return (str(rec.get("stage") or "builder"),
                        str(rec.get("reason") or rec.get("reject_reason") or "unknown"),
                        "CURRENT_SYMBOL_REJECT")
    except Exception:
        _v647_record_suppressed_exception()
    try:
        item = STATS.get("v538_last_execution_blocker") or {}
        ts = float(item.get("ts", 0.0) or 0.0)
        if ts >= float(start_mono if start_mono is not None else MONO_NOW()) - 0.001:
            return (str(item.get("stage") or "execution"),
                    str(item.get("reason") or "unknown"), "CURRENT_EXECUTION_BLOCKER")
    except Exception:
        _v647_record_suppressed_exception()
    try:
        b = str(STATS.get("v545_last_builder_blocker", "") or "")
        bt = float(STATS.get("v545_last_builder_blocker_ts_mono", 0.0) or 0.0)
        if b and bt >= float(start_mono if start_mono is not None else MONO_NOW()) - 0.001:
            return ("builder", b, "CURRENT_BUILDER")
    except Exception:
        _v647_record_suppressed_exception()
    return ("", "", "NONE")


