def _v646_lit_fee_rescue_self_test() -> Dict[str, Any]:
    """Offline regression for the exact LIT/USDT fee-unviable alert geometry."""
    checks: Dict[str, Any] = {}
    old = {}
    try:
        for k in ("V646_BREAKOUT_FEE_RESCUE_ENABLE", "V550_FEE_TARGET_RESCUE_ENABLE"):
            old[k] = CONFIG.get(k)
        CONFIG["V646_BREAKOUT_FEE_RESCUE_ENABLE"] = True
        CONFIG["V550_FEE_TARGET_RESCUE_ENABLE"] = True
        entry, sl = 4.743, 4.70684
        tp1, tp2, tp3 = 4.780606, 4.825733, 4.93103
        nominal, score = 75.0, 76.8
        before = SizingEngine.fee_viability_detail(entry, sl, tp1, tp2, nominal)
        ok, n1, n2, n3, reason = V420FeeRescue.try_expand_targets(
            entry, sl, tp1, tp2, tp3, nominal, score, "BREAKOUT_RETEST"
        )
        after = SizingEngine.fee_viability_detail(entry, sl, n1, n2, nominal)
        rr1 = (float(n1) - entry) / max(entry - sl, 1e-12)
        rr2 = (float(n2) - entry) / max(entry - sl, 1e-12)
        checks.update({
            "original_is_fee_blocked": not bool(before.get("ok", False)),
            "rescue_returns_true": bool(ok),
            "rescued_geometry_fee_viable": bool(after.get("ok", False)),
            "tp1_not_lowered": float(n1) >= tp1 - 1e-12,
            "tp2_not_lowered": float(n2) >= tp2 - 1e-12,
            "tp3_not_lowered": float(n3) >= tp3 - 1e-12,
            "breakout_tp1_cap": rr1 <= float(CONFIG.get("V646_BREAKOUT_FEE_RESCUE_MAX_TP1_RR", 1.50)) + 1e-9,
            "breakout_tp2_cap": rr2 <= float(CONFIG.get("V646_BREAKOUT_FEE_RESCUE_MAX_TP2_RR", 3.50)) + 1e-9,
            "hard_fee_floors_preserved": (
                float(CONFIG.get("MIN_NET_RR_TP1", 0.0)) >= 0.8
                and float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 0.0)) >= 2.5
                and float(CONFIG.get("MIN_NET_RR_OVERALL", 0.0)) >= 1.2
            ),
            "long_only_spot_preserved": (
                bool(CONFIG.get("LONG_ONLY", True))
                and not bool(CONFIG.get("ALLOW_SHORT", False))
                and not bool(CONFIG.get("ALLOW_SHORTS", False))
                and str(CONFIG.get("MARKET_TYPE", "spot")).lower() == "spot"
            ),
            "reason_present": bool(reason),
        })
        rep = {"pass": all(bool(v) for v in checks.values()), "checks": checks,
               "original": before, "rescued": after,
               "rescue": {"ok": ok, "tp1": n1, "tp2": n2, "tp3": n3,
                          "reason": reason, "rr1": rr1, "rr2": rr2}}
        STATS["v646_lit_fee_rescue_selftest"] = rep
        return rep
    except Exception as exc:
        rep = {"pass": False, "checks": checks, "error": f"{type(exc).__name__}:{exc}"}
        STATS["v646_lit_fee_rescue_selftest"] = rep
        return rep
    finally:
        for k, v in old.items():
            try:
                if v is None:
                    CONFIG.pop(k, None)
                else:
                    CONFIG[k] = v
            except Exception:
                _v647_record_suppressed_exception()


