def _v646_recall_num(v, default=0.0):
    try:
        x = float(v)
        return x if math.isfinite(x) else float(default)
    except Exception:
        return float(default)


def _v646_recall_tier_ok(tier: str, minimum: str = "MID") -> bool:
    try:
        return _FAMILY_RANK.get(str(tier or "").upper(), -1) >= _FAMILY_RANK.get(str(minimum or "MID").upper(), 2)
    except Exception:
        return False


def _v646_recall_sr_levels(df_15m, atr: float) -> Dict[str, float]:
    """Compact closed-bar SR context; reuses V537 dynamic levels when available."""
    out = {"support": 0.0, "resistance": 0.0}
    try:
        if not bool(CONFIG.get("V646_RECALL_SR_ENABLE", True)) or df_15m is None or atr <= 0:
            return out
        if "UniversalDualConfirmationEntry" in globals():
            try:
                lv = UniversalDualConfirmationEntry.dynamic_levels(df_15m, atr)
                if lv.get("support", 0) > 0 and lv.get("resistance", 0) > 0:
                    return {"support": float(lv["support"]), "resistance": float(lv["resistance"]),
                            "support_lower": float(lv.get("support_lower", 0) or 0),
                            "support_upper": float(lv.get("support_upper", 0) or 0)}
            except Exception:
                _v647_record_suppressed_exception()
        n = max(12, int(CONFIG.get("V537_STRUCTURE_LOOKBACK_BARS", 24)))
        prior = df_15m.iloc[-(n+2):-2]
        return {"support": float(prior["low"].min()), "resistance": float(prior["high"].max())}
    except Exception:
        return out


def _v646_recall_candidate_review(c, snap: Dict[str, Any]) -> Tuple[float, Dict[str, Any], str]:
    fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
    raw = _v646_recall_num(getattr(c, "engine_score", 0.0)) * 100.0
    fs = dict(getattr(c, "features_snapshot", {}) or {})
    tier = str(snap.get("tier") or fs.get("tier") or fs.get("liquidity_tier") or "").upper()
    htf = _v646_recall_num(fs.get("htf_strength", snap.get("htf_strength", 0.0)))
    vol = _v646_recall_num(fs.get("volume_ratio", 0.0))
    rs = _v646_recall_num(fs.get("rs_5m", fs.get("rs_score_val", 0.0)))
    if abs(rs) > 1.5:
        rs /= 100.0
    chase = _v646_recall_num(fs.get("chase_atr", 0.0))
    ctx = {"htf": htf, "vol": vol, "rs": rs, "chase": chase, "tier": tier}
    try:
        if callable(globals().get("_v531_review_discovery_score")):
            return _v531_review_discovery_score(raw, ctx, fam)
    except Exception:
        _v647_record_suppressed_exception()
    return raw, {}, "A+" if raw >= 85 else "A" if raw >= 75 else "B" if raw >= 65 else "C"


def _v646_recall_sr_signature(c, snap: Dict[str, Any]) -> Dict[str, Any]:
    """Return independent SR/sweep/breakout evidence from CLOSED 15m/5m bars."""
    out = {"ok": False, "type": "NONE", "support": 0.0, "resistance": 0.0}
    try:
        if not bool(CONFIG.get("V646_RECALL_SR_ENABLE", True)):
            return out
        d15 = snap.get("df_15m")
        d5 = snap.get("df_5m")
        if d15 is None or d5 is None or len(d15) < 40 or len(d5) < 25:
            return out
        atr_s = Indicators.atr(d15, CONFIG.get("ATR_PERIOD", 14))
        atr = _v646_recall_num(atr_s.iloc[-2] if atr_s is not None else 0.0)
        if atr <= 0:
            return out
        lv = _v646_recall_sr_levels(d15, atr)
        sup = _v646_recall_num(lv.get("support")); res = _v646_recall_num(lv.get("resistance"))
        last = d15.iloc[-2]; prev = d15.iloc[-3]
        close = _v646_recall_num(last["close"]); op = _v646_recall_num(last["open"])
        high = _v646_recall_num(last["high"]); low = _v646_recall_num(last["low"])
        prev_close = _v646_recall_num(prev["close"])
        rng = max(high - low, 1e-12)
        body_ratio = abs(close - op) / rng
        vol_avg = _v646_recall_num(d15["volume"].iloc[-22:-2].mean(), 0.0)
        vol_ratio = _v646_recall_num(last["volume"], 0.0) / vol_avg if vol_avg > 0 else 0.0
        chase = _v646_recall_num(getattr(c, "entry_ref", close) - close) / atr
        chase = abs(chase)
        tier = str(snap.get("tier") or "").upper()
        htf = _v646_recall_num(snap.get("htf_strength", 0.0))
        fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "")).upper()
        rs = _v646_recall_num((getattr(c, "features_snapshot", {}) or {}).get("rs_5m", 0.0))
        if abs(rs) > 1.5: rs /= 100.0

        sweep_depth = (sup - low) / atr if sup > 0 else 99.0
        reclaim = close >= sup and prev_close < sup if sup > 0 else False
        bullish = close > op and close >= prev_close
        lsr_ok = bool(
            fam == "LIQUIDITY_SWEEP_REVERSAL"
            and htf >= float(CONFIG.get("V646_RECALL_LSR_MIN_HTF", 90.0))
            and vol_ratio >= float(CONFIG.get("V646_RECALL_LSR_MIN_VOLUME_RATIO", 1.50))
            and rs >= float(CONFIG.get("V646_RECALL_LSR_MIN_RS", -0.005))
            and chase <= float(CONFIG.get("V646_RECALL_LSR_MAX_CHASE_ATR", 0.75))
            and body_ratio >= float(CONFIG.get("V646_RECALL_LSR_MIN_BODY_RATIO", 0.30))
            and sweep_depth >= 0.0
            and sweep_depth <= float(CONFIG.get("V646_RECALL_LSR_MAX_SWEEP_ATR", 0.45))
            and reclaim
            and bullish
            and _v646_recall_tier_ok(tier, CONFIG.get("V646_RECALL_LSR_MIN_TIER", "MID"))
        )
        if lsr_ok:
            out.update({"ok": True, "type": "LSR", "support": sup, "resistance": res,
                        "atr": atr, "volume_ratio": vol_ratio, "body_ratio": body_ratio,
                        "chase_atr": chase, "sweep_depth_atr": sweep_depth,
                        "reclaim": reclaim, "bullish_close": bullish})
            return out

        breakout = bool(
            fam in {"BREAKOUT_RETEST", "BREAKOUT_CONTINUATION"}
            and htf >= float(CONFIG.get("V646_RECALL_BREAKOUT_MIN_HTF", 90.0))
            and vol_ratio >= float(CONFIG.get("V646_RECALL_BREAKOUT_MIN_VOLUME_RATIO", 1.40))
            and chase <= float(CONFIG.get("V646_RECALL_BREAKOUT_MAX_CHASE_ATR", 0.75))
            and body_ratio >= float(CONFIG.get("V646_RECALL_BREAKOUT_MIN_BODY_RATIO", 0.35))
            and res > 0
            and prev_close <= res
            and close > res
            and (close - res) / atr <= float(CONFIG.get("V646_RECALL_BREAKOUT_MAX_EXTENSION_ATR", 0.75))
            and _v646_recall_tier_ok(tier, "MID")
        )
        if breakout:
            out.update({"ok": True, "type": "BREAKOUT", "support": sup, "resistance": res,
                        "atr": atr, "volume_ratio": vol_ratio, "body_ratio": body_ratio,
                        "chase_atr": chase, "breakout_extension_atr": (close-res)/atr})
        return out
    except Exception:
        return out



def _v646_sr_structural_recovery_allowed(symbol, opp, market_data, df_15m, df_5m,
                                         preferred_candidate, regime, tier) -> bool:
    """Bounded LSR structural recovery after fake-break rejection.

    This does not waive the structural rule globally. It admits only a strong
    LSR candidate with closed-bar sweep/reclaim evidence and then returns to the
    same canonical downstream gates. Any missing/ambiguous input => reject.
    """
    try:
        if not bool(CONFIG.get("V646_RECALL_SR_ENABLE", True)) or not bool(CONFIG.get("V646_RECALL_LSR_ENABLE", True)):
            return False
        fam = str((opp or {}).get("family", "") or (opp or {}).get("strategy_mode", "")).upper()
        if fam != "LIQUIDITY_SWEEP_REVERSAL":
            return False
        cand = preferred_candidate
        if cand is None:
            return False
        raw = _v646_recall_num(getattr(cand, "engine_score", 0.0))
        if raw < float(CONFIG.get("V646_RECALL_LSR_MIN_ENGINE_SCORE", 0.88)):
            return False
        snap = dict(market_data or {})
        snap.update({"symbol": str(symbol or ""), "df_15m": df_15m, "df_5m": df_5m,
                     "regime": str(regime or ""), "tier": str(tier or "")})
        if _v646_recall_num(snap.get("htf_strength", 0.0)) < float(CONFIG.get("V646_RECALL_LSR_MIN_HTF", 90.0)):
            return False
        sig = _v646_recall_sr_signature(cand, snap)
        if not bool(sig.get("ok")) or sig.get("type") != "LSR":
            return False
        # Require the LSR candidate itself to carry the canonical sweep/reclaim evidence.
        fs = dict(getattr(cand, "features_snapshot", {}) or {})
        if not bool(fs.get("sweep", False)):
            return False
        return bool(sig.get("reclaim") and sig.get("bullish_close"))
    except Exception:
        return False


def _v646_recall_reserve_eligible(c, snap: Dict[str, Any]) -> bool:
    try:
        fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
        if fam not in {"LIQUIDITY_SWEEP_REVERSAL", "BREAKOUT_RETEST", "PULLBACK", "MTF_PULLBACK"}:
            return False
        if str(getattr(c, "side", "long")).lower() != "long":
            return False
        tier = str(snap.get("tier") or "").upper()
        if not _v646_recall_tier_ok(tier, "MID"):
            return False
        raw = _v646_recall_num(getattr(c, "engine_score", 0.0))
        if fam == "LIQUIDITY_SWEEP_REVERSAL" and raw < float(CONFIG.get("V646_RECALL_LSR_MIN_ENGINE_SCORE", 0.88)):
            return False
        if fam != "LIQUIDITY_SWEEP_REVERSAL" and raw < float(CONFIG.get("V646_RECALL_BREAKOUT_MIN_ENGINE_SCORE", 0.86)):
            return False
        reviewed, _, _ = _v646_recall_candidate_review(c, snap)
        min_review = float(CONFIG.get(
            "V646_RECALL_LSR_MIN_REVIEWED_SCORE" if fam == "LIQUIDITY_SWEEP_REVERSAL" else "V646_RECALL_BREAKOUT_MIN_REVIEWED_SCORE",
            88.0,
        ))
        if reviewed < min_review:
            return False
        sig = _v646_recall_sr_signature(c, snap)
        return bool(sig.get("ok", False))
    except Exception:
        return False


def _v646_make_lsr_recovery(cls, snap: Dict[str, Any]) -> Optional[StrategyCandidate]:
    try:
        c0 = getattr(cls, "_atr_and_entry")
        atr, entry = c0(snap.get("df_5m"))
        if atr is None or entry is None or float(atr) <= 0 or float(entry) <= 0:
            return None
        temp = type("_LSRProbe", (), {})()
        temp.family = "LIQUIDITY_SWEEP_REVERSAL"
        temp.strategy_mode = "LIQUIDITY_SWEEP_REVERSAL"
        temp.engine_score = float(CONFIG.get("V646_RECALL_LSR_MIN_ENGINE_SCORE", 0.88))
        temp.entry_ref = float(entry)
        temp.features_snapshot = {}
        sig = _v646_recall_sr_signature(temp, snap)
        if not sig.get("ok") or sig.get("type") != "LSR":
            return None
        sl = float(entry) - float(CONFIG["ATR_SL_MULT"]) * float(atr)
        tp1, tp2, tp3 = cls._canonical_levels(float(entry), sl)
        score = min(0.92, max(0.88, 0.88 + 0.02 * min(1.0, float(sig.get("volume_ratio", 1.5)) / 2.5)))
        return StrategyCandidate(
            engine_id="liq_sweep_sr_recovery", symbol=str(snap.get("symbol", "")), side="long",
            generated_at_ms=int(time.time() * 1000), entry_ref=float(entry), sl_price=float(sl),
            tp1_rr=float(CONFIG["TP1_RR"]), tp2_rr=float(CONFIG["TP2_RR"]), tp3_rr=float(CONFIG["TP3_RR"]),
            engine_score=float(score), rr_ratio=(tp1-entry)/max(entry-sl, 1e-9),
            liquidity_score=cls._liquidity_score(snap.get("tier", "")),
            regime_fit=cls._regime_fit(snap.get("regime", ""), "LIQUIDITY_SWEEP_REVERSAL"),
            family="LIQUIDITY_SWEEP_REVERSAL", zone_ref=float(sig.get("support") or entry),
            features_snapshot={
                "atr": float(atr), "entry_ref": float(entry), "swept_low": float(sig.get("support", entry)),
                "sweep": True, "reclaim": True, "bullish_close": True, "body_ratio": float(sig.get("body_ratio", 0.0)),
                "volume_ratio": float(sig.get("volume_ratio", 0.0)), "chase_atr": float(sig.get("chase_atr", 0.0)),
                "sr_support": float(sig.get("support", 0.0)), "sr_resistance": float(sig.get("resistance", 0.0)),
                "sr_recovery_verified": True, "v646_recall_lane": "LSR_SR_RECOVERY",
                "strategy_mode": "LIQUIDITY_SWEEP_REVERSAL",
            },
        )
    except Exception:
        return None


# Add one high-quality LSR recovery candidate only when the original detector
# produced nothing. It remains a normal MSE candidate and never executes directly.
try:
    _v646_orig_lsr_generate = LiquiditySweepEngine.generate
    @classmethod
    def _v646_lsr_generate(cls, mkt_snapshot):
        out = _v646_orig_lsr_generate.__func__(cls, mkt_snapshot) if hasattr(_v646_orig_lsr_generate, "__func__") else _v646_orig_lsr_generate(mkt_snapshot)
        if out or not bool(CONFIG.get("V646_RECALL_LSR_ENABLE", True)):
            return out or []
        c = _v646_make_lsr_recovery(cls, mkt_snapshot)
        if c is not None:
            STATS["v646_lsr_sr_recovery_generated"] = int(STATS.get("v646_lsr_sr_recovery_generated", 0) or 0) + 1
            return [c]
        return []
    LiquiditySweepEngine.generate = _v646_lsr_generate
except Exception as _v646_lsr_patch_exc:
    logger.debug(f"[V646-RECALL] LSR patch unavailable: {_v646_lsr_patch_exc}")

# Enrich already-generated candidates with SR context for ranking/forensics;
# no score or gate is weakened by this annotation.
try:
    _v646_orig_breakout_generate = BreakoutEngine.generate
    @classmethod
    def _v646_breakout_generate(cls, mkt_snapshot):
        out = _v646_orig_breakout_generate.__func__(cls, mkt_snapshot) if hasattr(_v646_orig_breakout_generate, "__func__") else _v646_orig_breakout_generate(mkt_snapshot)
        updated = []
        for _c in list(out or []):
            try:
                sig = _v646_recall_sr_signature(_c, mkt_snapshot)
                fs = dict(getattr(_c, "features_snapshot", {}) or {})
                if sig.get("support"):
                    fs["sr_support"] = float(sig.get("support"))
                if sig.get("resistance"):
                    fs["sr_resistance"] = float(sig.get("resistance"))
                fs["sr_context_type"] = str(sig.get("type", "NONE"))
                fs["v646_sr_context"] = True
                _c = _v672_set_fs(_c, fs) if "_v672_set_fs" in globals() else _c
            except Exception:
                _v647_record_suppressed_exception()
            updated.append(_c)
        return updated
    BreakoutEngine.generate = _v646_breakout_generate
except Exception as _v646_bo_patch_exc:
    logger.debug(f"[V646-RECALL] breakout SR annotation unavailable: {_v646_bo_patch_exc}")

