    try:
        now = WALL_NOW()
        try:
            KillSwitch.is_active = staticmethod(lambda: False)
            ExchangeWatchdog.is_tripped = staticmethod(lambda: False)
            BalanceReconciler.snapshot = staticmethod(lambda: {"state": "REAL"})
            LIVE_ENTRIES_BLOCKED.clear()
            LIVE_ENTRIES_BLOCKED.update({"active": False, "reason": ""})
            LIVE_STATE.current = "FULL_LIVE_RUNNING"
        except Exception:
            pass

        STATS["v547_cycle_selected_to_exec"] = 3
        STATS["v547_cycle_pending_to_exec"] = 0
        STATS["v547_cycle_reserve_to_exec"] = 0
        STATS["v547_cycle_queued_delta"] = 0
        STATS["v547_cycle_sent_delta"] = 0
        STATS["v535_last_attempt_ts"] = now

        STATS["v585_last_exact_builder_block"] = {
            "reason": "family_policy:reject.liquidity.family_tier_below_floor",
            "stage": "family_policy", "ts": now, "symbol": "TEST/USDT"
        }
        snap = _v647_root_cause_snapshot()
        checks["selected_queue_liquidity_root"] = snap.get("mode") == "LIQUIDITY"

        STATS["v585_last_exact_builder_block"] = {
            "reason": "microstruct:reject.structural.fake_break_detected",
            "stage": "microstruct", "ts": now, "symbol": "TEST/USDT"
        }
        snap2 = _v647_root_cause_snapshot()
        checks["selected_queue_structure_root"] = snap2.get("mode") == "STRUCTURE"
        checks["reason_mapping_liquidity"] = _v647_reason_to_mode("family_policy:reject.liquidity.family_tier_below_floor") == "LIQUIDITY"
        checks["reason_mapping_structure"] = _v647_reason_to_mode("microstruct:reject.structural.fake_break_detected") == "STRUCTURE"
        return {"pass": all(checks.values()), "checks": checks}
    except Exception as exc:
        return {"pass": False, "checks": checks, "error": f"{type(exc).__name__}:{exc}"}
    finally:
        for k, v in backup_stats.items():
            if v is None:
                STATS.pop(k, None)
            else:
                STATS[k] = v
        try:
            LIVE_ENTRIES_BLOCKED.clear()
            if isinstance(backup_block, dict):
                LIVE_ENTRIES_BLOCKED.update(backup_block)
            LIVE_STATE.current = old_state
            if old_ks is not None:
                KillSwitch.is_active = old_ks
            if old_wd is not None:
                ExchangeWatchdog.is_tripped = old_wd
            if old_bal is not None:
                BalanceReconciler.snapshot = old_bal
        except Exception:
            pass


