def _v649_self_test() -> Dict[str, Any]:
    """Offline deterministic checks for the V649 bounded recall closures."""
    checks: Dict[str, bool] = {}
    try:
        checks["hard_sl_floor_unchanged"] = abs(float(CONFIG.get("MIN_SL_PCT", 0.0)) - 0.40) < 1e-9
        checks["hard_sl_ceiling_unchanged"] = abs(float(CONFIG.get("MAX_SL_PCT", 0.0)) - 1.80) < 1e-9
        checks["spread_second_recheck_enabled"] = bool(CONFIG.get("V629_SPREAD_SECOND_RECHECK_ENABLE", False))
    except Exception:
        checks["sl_and_spread_policy"] = False

    # Exercise the exact new SL-repair branch with a temporary legacy helper.
    old_original = globals().get("_v640_original_pullback_stop")
    try:
        if not callable(old_original):
            raise RuntimeError("original_pullback_stop_missing")
        globals()["_v640_original_pullback_stop"] = lambda **kwargs: float(kwargs["entry"]) * (1.0 - 0.0010)
        fake_entry = 100.0
        fake_atr = 0.50
        repaired = _v640_repaired_pullback_stop(None, fake_entry, fake_atr, zone_ref=None)
        checks["tight_original_gets_repaired"] = bool(
            repaired is not None and abs((fake_entry - float(repaired)) / fake_entry * 100.0 - 0.40) < 1e-8
        )
        checks["repaired_sl_is_below_entry"] = bool(repaired is not None and float(repaired) < fake_entry)
        checks["repaired_sl_not_above_max_pct"] = bool(
            repaired is not None and ((fake_entry - float(repaired)) / fake_entry * 100.0) <= 1.80 + 1e-9
        )
    except Exception as exc:
        checks["tight_original_gets_repaired"] = False
        checks["v649_sl_test_error"] = False
        logger.debug(f"[V649-SELFTEST] SL test suppressed: {type(exc).__name__}:{exc}")
    finally:
        globals()["_v640_original_pullback_stop"] = old_original

    # The hard tier spread function must still reject above-ceiling values;
    # V629 is allowed to re-observe, not to change the ceiling.
    try:
        base = float((CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}).get("MAJORS", 0.12))
        ok, _ = tier_spread_hard_ok_v410(base + 0.10, "MAJORS")
        checks["spread_ceiling_still_hard"] = not bool(ok)
    except Exception:
        checks["spread_ceiling_still_hard"] = False

    try:
        checks["long_only_still_on"] = bool(CONFIG.get("LONG_ONLY", True)) and not bool(CONFIG.get("ALLOW_SHORTS", False))
        checks["fee_floors_unchanged"] = (
            abs(float(CONFIG.get("MIN_NET_RR_TP1", 0.8)) - 0.8) < 1e-9
            and abs(float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5)) - 2.5) < 1e-9
            and abs(float(CONFIG.get("MIN_NET_RR_OVERALL", 1.2)) - 1.2) < 1e-9
        )
        checks["ticket_and_slots_unchanged"] = (
            abs(float(CONFIG.get("V576_REQUESTED_POSITION_USDT", 75.0)) - 75.0) < 1e-9
            and int(CONFIG.get("MAX_CONCURRENT_TRADES", 2)) == 2
        )
    except Exception:
        checks["safety_invariants"] = False
    return {"pass": all(bool(v) for v in checks.values()), "checks": checks}

