# Keep the original final policy validator as the safety authority. Because its
# historical identity is intentionally frozen at V647, validate safety against
# that immutable identity temporarily, then add the V653 identity/policy checks.
try:
    _v653_original_v647_policy_validator = _v647_validate_canonical_policy
    def _v653_validate_canonical_policy() -> Tuple[bool, Dict[str, Any]]:
        saved = (
            globals().get("SCRIPT_VERSION"),
            CONFIG.get("SCRIPT_VERSION"),
            globals().get("RUNTIME_BUILD_ID"),
            globals().get("CANONICAL_RUNTIME_IDENTITY"),
        )
        try:
            globals()["SCRIPT_VERSION"] = V647_FINAL_IDENTITY
            CONFIG["SCRIPT_VERSION"] = V647_FINAL_IDENTITY
            globals()["RUNTIME_BUILD_ID"] = V647_FINAL_IDENTITY
            globals()["CANONICAL_RUNTIME_IDENTITY"] = V647_FINAL_IDENTITY
            ok, detail = _v653_original_v647_policy_validator()
        finally:
            globals()["SCRIPT_VERSION"] = saved[0]
            CONFIG["SCRIPT_VERSION"] = saved[1]
            globals()["RUNTIME_BUILD_ID"] = saved[2]
            globals()["CANONICAL_RUNTIME_IDENTITY"] = saved[3]
        try:
            detail = dict(detail or {})
        except Exception:
            detail = {"base": detail}
        detail["v653_identity"] = (
            str(globals().get("SCRIPT_VERSION")) == V653_FINAL_IDENTITY
            == str(CONFIG.get("SCRIPT_VERSION")) == str(globals().get("RUNTIME_BUILD_ID"))
            == str(globals().get("CANONICAL_RUNTIME_IDENTITY"))
        )
        detail["v653_precision_diagnostics"] = bool(CONFIG.get("V653_PRECISION_DIAGNOSTICS_ENABLE", True))
        detail["v653_candidate_dedup"] = bool(CONFIG.get("V653_CANDIDATE_DEDUP_ENABLE", True))
        detail["v653_near_miss_recheck"] = bool(CONFIG.get("V653_NEAR_MISS_RECHECK_ENABLE", True))
        detail["v653_no_threshold_lowering"] = (
            float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO", 0.85)) >= 0.85
            and float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE", 45.0)) >= 45.0
            and float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY", 72.0)) >= 72.0
            and float(CONFIG.get("MIN_NET_RR_TP1", 0.8)) >= 0.8
            and float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5)) >= 2.5
            and float(CONFIG.get("MIN_NET_RR_OVERALL", 1.2)) >= 1.2
        )
        return bool(ok and all(bool(v) for k, v in detail.items() if k.startswith("v653_"))), detail
    _v647_validate_canonical_policy = _v653_validate_canonical_policy
except Exception:
    pass


# Deterministic V653 self-test.
def _v653_self_test() -> Dict[str, Any]:
    checks = {}
    details = {}
    try:
        checks["identity"] = str(SCRIPT_VERSION) == V653_FINAL_IDENTITY == str(CONFIG.get("SCRIPT_VERSION")) == str(RUNTIME_BUILD_ID) == str(CANONICAL_RUNTIME_IDENTITY)
    except Exception:
        checks["identity"] = False
    try:
        c1 = StrategyCandidate(engine_id="pullback", symbol="TEST/USDT", side="long", generated_at_ms=0, entry_ref=100.0, sl_price=99.0, tp1_rr=1.0, tp2_rr=2.0, tp3_rr=5.0, engine_score=0.98, rr_ratio=2.0, liquidity_score=1.0, regime_fit=1.0, family="PULLBACK", zone_ref=100.0, features_snapshot={"candle_ts":"C1"}, strategy_mode="PULLBACK")
        c2 = replace(c1, engine_score=0.96, rr_ratio=1.8, entry_ref=100.02)
        ded = _v653_dedup_candidates([c1,c2], {"df_5m":None})
        checks["candidate_dedup_keeps_strongest"] = len(ded) == 1 and ded[0] is c1
    except Exception:
        checks["candidate_dedup_keeps_strongest"] = False
    try:
        checks["near_miss_strong_gate"] = bool(_v653_precision_failure_is_near(type("C", (), {"engine_score":0.98})(), {"reason":"retest_weak","retest":40.0,"confirmations":1}))
        checks["near_miss_out_of_gap_rejected"] = not bool(_v653_precision_failure_is_near(type("C", (), {"engine_score":0.80})(), {"reason":"retest_weak","retest":20.0,"confirmations":1}))
    except Exception:
        checks["near_miss_strong_gate"] = False
        checks["near_miss_out_of_gap_rejected"] = False
    try:
        # Deterministic fresh-bar volume recovery: original candidate is just
        # below the hard 0.85 volume floor, while the current closed-bar data
        # recomputes a healthy ratio. The same V587 contract must then pass.
        import pandas as _pd_v653
        rows=[]
        for i in range(35):
            cl=100.0+0.01*i
            rows.append({"open":cl-0.03,"high":cl+0.08,"low":cl-0.10,"close":cl,"volume":1000.0})
        rows[-3]["close"] = rows[-3]["open"] - 0.05
        rows[-2]["open"] = 100.30; rows[-2]["close"] = 100.36; rows[-2]["high"] = 100.42; rows[-2]["low"] = 100.20; rows[-2]["volume"] = 1400.0
        df=_pd_v653.DataFrame(rows)
        c=StrategyCandidate(engine_id="pullback", symbol="NM/USDT", side="long", generated_at_ms=0, entry_ref=100.36, sl_price=99.0, tp1_rr=1.0, tp2_rr=2.0, tp3_rr=5.0, engine_score=0.98, rr_ratio=2.0, liquidity_score=1.0, regime_fit=1.0, family="PULLBACK", zone_ref=100.30, features_snapshot={"htf_strength":90.0,"volume_ratio":0.80,"rs_5m":0.01,"structure_confidence":80.0,"retest_quality_score":80.0,"chase_atr":0.10}, strategy_mode="PULLBACK")
        fresh_q=_v587_pullback_quality(c,{"df_5m":df})
        checks["fresh_recheck_passes_when_original_volume_was_near_floor"] = bool(fresh_q.get("ok")) and bool(fresh_q.get("near_miss_rechecked",False))
    except Exception:
        checks["fresh_recheck_passes_when_original_volume_was_near_floor"] = False
    except Exception:
        checks["near_miss_strong_gate"] = False
        checks["near_miss_out_of_gap_rejected"] = False
    try:
        test_payload = {"symbol":"T/USDT","family":"PULLBACK","stage":"prequal","reason":"structure.pullback_precision.retest_weak","context":{"v653_precision":{"reason":"retest_weak","value":40,"floor":45,"retest":40,"confirmations":1}}}
        rendered = _v653_rejection_message(test_payload)
        checks["precision_reason_rendered"] = "retest_weak" in rendered and "40" in rendered and "45" in rendered
    except Exception:
        checks["precision_reason_rendered"] = False
    try:
        checks["precision_diagnostics_enabled"] = bool(CONFIG.get("V653_PRECISION_DIAGNOSTICS_ENABLE", False))
        checks["no_threshold_lowering"] = (
            float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO",0.85)) >= 0.85
            and float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE",45.0)) >= 45.0
            and float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY",72.0)) >= 72.0
            and float(CONFIG.get("MIN_NET_RR_TP1",0.8)) >= 0.8
            and float(CONFIG.get("MIN_TP1_TO_FEE_RATIO",2.5)) >= 2.5
            and float(CONFIG.get("MIN_NET_RR_OVERALL",1.2)) >= 1.2
        )
        checks["long_only_spot"] = bool(CONFIG.get("LONG_ONLY",True)) and not bool(CONFIG.get("ALLOW_SHORTS",False)) and str(CONFIG.get("MARKET_TYPE","SPOT")).upper() == "SPOT"
        checks["candidate_dedup_hook"] = callable(globals().get("_v651_dedup_candidates"))
    except Exception:
        checks["precision_diagnostics_enabled"] = False
        checks["no_threshold_lowering"] = False
        checks["long_only_spot"] = False
        checks["candidate_dedup_hook"] = False
    details["version"] = V653_FINAL_IDENTITY
    return {"pass": all(bool(v) for v in checks.values()), "checks": checks, "details": details}


