def _v654_score100(candidate):
    try:
        x = float(getattr(candidate, "engine_score", 0.0) or 0.0)
        return x * 100.0 if x <= 1.0 else x
    except Exception:
        return 0.0

def _v654_num(v):
    try:
        x = float(v)
        return x if math.isfinite(x) else None
    except Exception:
        return None

def _v654_fs(candidate):
    try:
        return dict(getattr(candidate, "features_snapshot", {}) or {})
    except Exception:
        return {}

def _v654_current_closed_facts(candidate, snap):
    out = {}
    try:
        df5 = (snap or {}).get("df_5m") if isinstance(snap, dict) else None
        if df5 is None or len(df5) < 25:
            return out
        close = float(df5["close"].iloc[-2])
        prev = float(df5["close"].iloc[-3])
        op = float(df5["open"].iloc[-2])
        lo = float(df5["low"].iloc[-2])
        plo = float(df5["low"].iloc[-3])
        pplo = float(df5["low"].iloc[-4])

        out["bullish_close"] = bool(close > op and close >= prev)
        out["higher_low"] = bool(lo > plo >= pplo)

        e20s = df5["close"].ewm(span=20, adjust=False)
        e20 = float(e20s.iloc[-2])
        e50 = float(df5["close"].ewm(span=50, adjust=False).iloc[-2])
        out["above_ema20"] = bool(close >= e20)
        out["above_ema50"] = bool(close > e50)

        atr_s = Indicators.atr(df5, int(CONFIG.get("ATR_PERIOD", 14)))
        atr = float(atr_s.iloc[-2]) if atr_s is not None else 0.0
        out["atr"] = atr
        z = getattr(candidate, "zone_ref", None)
        if z is None:
            z = _v654_fs(candidate).get("zone_ref")
        if z is not None and atr > 0:
            zf = float(z)
            out["zone_ref"] = zf
            out["zone_reclaim"] = bool(prev < zf <= close)
            out["zone_dist_atr"] = abs(close - zf) / atr
        else:
            out["zone_reclaim"] = False

        # Candidate-level 15m/anchor confirmations are independent of the
        # single current 5m candle.
        fs = _v654_fs(candidate)
        out["p15_stack"] = bool(fs.get("p15_stack", False))
        anchor = str(fs.get("anchor", "") or "").upper()
        out["anchor_quality"] = anchor.startswith(("EMA20", "EMA50", "VWAP"))

        if len(df5) >= 24:
            av = float(df5["volume"].iloc[-22:-2].mean())
            cv = float(df5["volume"].iloc[-2])
            out["volume_ratio"] = cv / av if av > 0 else None
        return out
    except Exception:
        return {}

def _v654_independent_confirmation_count(candidate, snap, current):
    fs = _v654_fs(candidate)
    evidence = [
        bool(fs.get("higher_low_5m", False)),
        bool(fs.get("bullish_close_5m", False)),
        bool(fs.get("p15_stack", False)),
        bool(fs.get("d1_trend", "").upper() == "BULLISH"),
        bool(fs.get("h4_trend", "").upper() == "BULLISH"),
        bool(str(fs.get("anchor", "") or "").upper().startswith(("EMA20", "EMA50", "VWAP"))),
        bool(current.get("higher_low", False)),
        bool(current.get("bullish_close", False)),
        bool(current.get("zone_reclaim", False)),
        bool(current.get("above_ema50", False)),
    ]
    return int(sum(evidence))

def _v654_pullback_structural_recovery_allowed(candidate, snap, *, source="microstruct"):
    """Permit only a fully quality-qualified pullback to continue past one
    narrow structural blocker. The downstream canonical path remains hard."""
    try:
        if not bool(CONFIG.get("V654_STRUCTURE_RECOVERY_ENABLE", True)):
            return False, {"reason": "disabled"}
        fam = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
        if fam not in {"PULLBACK", "MTF_PULLBACK"}:
            return False, {"reason": "family_not_allowed"}
        score = _v654_score100(candidate)
        fs = _v654_fs(candidate)
        htf = _v654_num(fs.get("htf_strength", fs.get("htf_alignment")))
        structure = _v654_num(fs.get("structure_confidence", fs.get("structure_quality")))
        retest = _v654_num(fs.get("retest_quality_score", fs.get("retest_quality")))
        volume = _v654_num(fs.get("volume_ratio"))
        rs = _v654_num(fs.get("rs_5m", fs.get("rs_score_val", fs.get("relative_strength"))))
        chase = _v654_num(fs.get("chase_atr"))
        if htf is None or structure is None or retest is None or volume is None or rs is None or chase is None:
            return False, {"reason": "missing_quality_facts"}
        thresholds = (
            ("engine", score, float(CONFIG.get("V654_MICROSTRUCT_RECOVERY_MIN_ENGINE", 96.5))),
            ("htf", htf, float(CONFIG.get("V654_MICROSTRUCT_RECOVERY_MIN_HTF", 65.0))),
            ("structure", structure, float(CONFIG.get("V654_MICROSTRUCT_RECOVERY_MIN_STRUCTURE", 60.0))),
            ("retest", retest, float(CONFIG.get("V654_MICROSTRUCT_RECOVERY_MIN_RETEST", 55.0))),
            ("volume", volume, float(CONFIG.get("V654_MICROSTRUCT_RECOVERY_MIN_VOLUME", 0.90))),
            ("rs", rs, 0.0),
        )
        for name, val, floor in thresholds:
            if val < floor:
                return False, {"reason": f"{name}_below_recovery_floor", "value": val, "floor": floor}
        if chase > float(CONFIG.get("V654_MICROSTRUCT_RECOVERY_MAX_CHASE_ATR", 0.60)):
            return False, {"reason": "chase_too_high_for_recovery", "value": chase,
                           "floor": float(CONFIG.get("V654_MICROSTRUCT_RECOVERY_MAX_CHASE_ATR", 0.60))}
        current = _v654_current_closed_facts(candidate, snap)
        conf = _v654_independent_confirmation_count(candidate, snap, current)
        if conf < int(CONFIG.get("V654_MICROSTRUCT_RECOVERY_MIN_CONFIRMATIONS", 2)):
            return False, {"reason": "confirmations_below_recovery_floor", "value": conf,
                           "floor": int(CONFIG.get("V654_MICROSTRUCT_RECOVERY_MIN_CONFIRMATIONS", 2))}
        # Must still have meaningful present-price location.
        if not (current.get("above_ema50") or current.get("zone_reclaim") or current.get("higher_low")):
            return False, {"reason": "no_present_structural_anchor"}
        # Crucial safety condition: the ORIGINAL V587 contract must pass
        # against this exact current snapshot before this recovery is counted.
        q = _v587_pullback_quality(candidate, snap)
        if not isinstance(q, dict) or not bool(q.get("ok", False)):
            return False, {
                "reason": "v587_quality_not_passed",
                "v587_reason": str((q or {}).get("reason", "") if isinstance(q, dict) else ""),
            }
        out = {
            "source": source, "engine": score, "htf": htf, "structure": structure,
            "retest": retest, "volume": volume, "rs": rs, "chase": chase,
            "confirmations": conf, **current
        }
        return True, out
    except Exception as exc:
        return False, {"reason": f"exception:{type(exc).__name__}"}

def _v654_fake_break_recovery_allowed(candidate, snap, fb_ctx):
    try:
        ok, diag = _v654_pullback_structural_recovery_allowed(candidate, snap, source="fake_break")
        if not ok:
            return False, diag
        chase = _v654_num((fb_ctx or {}).get("chase_atr"))
        if chase is not None and chase > float(CONFIG.get("V654_FAKE_BREAK_RECOVERY_MAX_CHASE_ATR", 0.60)):
            return False, {"reason": "fake_break_chase_too_high", "value": chase, "floor": 0.60}
        # Require the fake-break detector to have valid ATR/current-bar facts.
        if not bool((fb_ctx or {}).get("atr_valid", True)):
            return False, {"reason": "fake_break_atr_invalid"}
        return True, diag
    except Exception:
        return False, {"reason": "exception"}

def _v654_merge_recovery_telemetry(diag, reason):
    try:
        for k in ("source", "engine", "htf", "structure", "retest", "volume", "rs", "chase", "confirmations"):
            v = (diag or {}).get(k)
            if v is not None:
                STATS[f"v654_last_recovery_{k}"] = v
        STATS["v654_last_recovery_reason"] = str(reason or "")
    except Exception:
        pass

