def _v655_self_test():
    checks={}
    try:
        class C: pass
        c=C(); c.family="PULLBACK"; c.strategy_mode="PULLBACK"; c.symbol="TEST/USDT"; c.engine_score=0.99; c.zone_ref=100.0
        c.features_snapshot={
            "htf_strength":85.0,"volume_ratio":1.10,"retest_quality_score":80.0,"rs_5m":0.01,"chase_atr":0.20,
            "higher_low_5m":True,"bullish_close_5m":True,"p15_stack":True,"d1_trend":"BULLISH","h4_trend":"BULLISH"
        }
        checks["canonical_family"]=_v655_family(candidate=c)=="PULLBACK_CANONICAL"
        checks["weak_family_block"] = not _v655_canonical_structural_decision(type("X",(),{"family":"MEAN_REVERSION","strategy_mode":"MEAN_REVERSION","engine_score":0.99,"features_snapshot":{}})(),{},detector_reason="x")[0]
        checks["thresholds_intact"]=(
            float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO",0.85))>=0.85 and
            float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE",45.0))>=45.0 and
            float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY",72.0))>=72.0 and
            float(CONFIG.get("MIN_NET_RR_TP1",0.8))>=0.8 and
            float(CONFIG.get("MIN_TP1_TO_FEE_RATIO",2.5))>=2.5 and
            float(CONFIG.get("MIN_NET_RR_OVERALL",1.2))>=1.2
        )
        # Signature unification is deterministic even without market data.
        a=C(); a.symbol="TEST/USDT"; a.family="PULLBACK"; a.strategy_mode="PULLBACK"; a.engine_score=0.98; a.rr_ratio=2.0; a.features_snapshot={"candle_ts":"123"}
        b=C(); b.symbol="TEST/USDT"; b.family="MTF_PULLBACK"; b.strategy_mode="MTF_PULLBACK"; b.engine_score=0.97; b.rr_ratio=2.0; b.features_snapshot={"candle_ts":"123"}
        checks["pb_mtf_signature_unified"]=_v655_candidate_signature(a)==_v655_candidate_signature(b)
        # Synthetic current-closed-bar recovery proof: a strong PULLBACK with
        # two independent structural anchors is RECOVERABLE, while a weak one
        # remains HARD. This validates the arbiter itself without exchange I/O.
        import pandas as _pd_v655
        rows=[]
        for i in range(40):
            price=100.0 + i*0.08
            rows.append({"open":price-0.03,"high":price+0.10,"low":price-0.10,"close":price,"volume":1000.0})
        rows[-2].update({"open":103.04,"high":103.40,"low":102.95,"close":103.30,"volume":1250.0})
        rows[-3].update({"open":102.90,"high":103.05,"low":102.80,"close":103.00,"volume":1000.0})
        df=_pd_v655.DataFrame(rows)
        snap={"df_5m":df}
        c.zone_ref=103.00
        rec,diag,cls_name=_v655_canonical_structural_decision(c,snap,detector_reason="fake_break_detected")
        checks["strong_structural_recoverable"] = bool(rec and cls_name=="RECOVERABLE")
        weak=C(); weak.family="PULLBACK"; weak.strategy_mode="PULLBACK"; weak.engine_score=0.80; weak.features_snapshot=c.features_snapshot; weak.zone_ref=103.0
        _wr,_,_wc=_v655_canonical_structural_decision(weak,snap,detector_reason="fake_break_detected")
        checks["weak_structural_hard_reject"] = bool(not _wr and _wc=="HARD")
    except Exception:
        return {"pass":False,"checks":checks}
    return {"pass":all(bool(v) for v in checks.values()),"checks":checks,"details":{"version":V655_FINAL_IDENTITY}}

