# =============================================================================
# V657 FINAL — RETEST QUALITY / STRUCTURE ATTRIBUTION / CURRENT-CYCLE CLOSURE
# =============================================================================
# Production evidence from V656 showed a new deterministic bottleneck:
# high-quality PULLBACKs (Engine ~95-100, HTF often strong) were repeatedly
# rejected as `retest_weak`. The root cause was that the retest score was based
# mainly on zone distance/class and did not incorporate the already-confirmed
# current CLOSED-BAR reclaim/higher-low/EMA-slope/bullish-close evidence that
# independently proves the pullback is recovering.
#
# V657 keeps the hard V587 floor (45) unchanged and recalculates ONLY the
# retest-quality metric from current closed bars when those facts are available.
# This is a measurement correction, not a threshold bypass. The original V587
# contract is still run after recomputation. Structural arbiter, fee, risk,
# liquidity, Balance/TruthSeal, execution, LONG_ONLY/SPOT and fail-closed rules
# remain authoritative.
#
# V657 also improves current-cycle starvation attribution: if selected candidates
# are present but queue/send is zero, the heartbeat reports the concrete selected
# stage before historical reject pressure. This prevents a STRUCTURE label from
# masking an actual LIQUIDITY/PRE-SEND/EXECUTION bottleneck.
# =============================================================================

V657_FINAL_IDENTITY = "4.5.99-V657-FINAL-RETEST-STRUCTURE-STARVATION-CLOSURE"
CONFIG.update({
    "V657_RETEST_RECOMPUTE_ENABLE": True,
    "V657_RETEST_MIN_DISTANCE_SCORE": True,
    "V657_RETEST_DISTANCE_A_MAX": 0.30,
    "V657_RETEST_DISTANCE_B_MAX": 0.60,
    "V657_RETEST_DISTANCE_C_MAX": 1.00,
    "V657_RETEST_RECLAIM_BONUS": 10.0,
    "V657_RETEST_HIGHER_LOW_BONUS": 10.0,
    "V657_RETEST_BULLISH_CLOSE_BONUS": 5.0,
    "V657_RETEST_EMA_SLOPE_BONUS": 5.0,
    "V657_RETEST_REJECTION_BONUS": 10.0,
    "V657_RETEST_15M_STACK_BONUS": 5.0,
    "V657_RETEST_MAX_SCORE": 100.0,
    "V657_STARVATION_CURRENT_STAGE_PRIORITY": True,
    "V657_HEARTBEAT_ENABLE": True,
    "V657_REJECTION_PRICE_BUCKET_PCT": 0.08,
    "V657_REJECTION_DEDUP_ENABLE": True,
})


def _v657_recompute_retest_quality(candidate, market_data):
    """Return a closed-bar-only retest score/facts bundle.

    The hard V587 floor remains 45. This function only measures the same setup
    more completely; it never manufactures HTF/RS/volume/structure truth.
    """
    out = {}
    try:
        if not bool(CONFIG.get("V657_RETEST_RECOMPUTE_ENABLE", True)):
            return out
        md = market_data if isinstance(market_data, dict) else {}
        df = md.get("df_5m")
        if df is None or len(df) < 25:
            return out
        lc = float(df["close"].iloc[-2])
        pc = float(df["close"].iloc[-3])
        op = float(df["open"].iloc[-2])
        hi = float(df["high"].iloc[-2])
        lo = float(df["low"].iloc[-2])
        atr_s = Indicators.atr(df, int(CONFIG.get("ATR_PERIOD", 14)))
        atr = float(atr_s.iloc[-2]) if atr_s is not None else 0.0
        if not (math.isfinite(atr) and atr > 0):
            return out
        z = getattr(candidate, "zone_ref", None)
        fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        if z is None:
            z = fs.get("zone_ref")
        if z is None:
            return out
        z = float(z)
        if not (math.isfinite(z) and z > 0):
            return out

        dist_atr = abs(lc - z) / atr
        if dist_atr <= float(CONFIG.get("V657_RETEST_DISTANCE_A_MAX", 0.30)):
            score = 60.0
        elif dist_atr <= float(CONFIG.get("V657_RETEST_DISTANCE_B_MAX", 0.60)):
            score = 40.0
        elif dist_atr <= float(CONFIG.get("V657_RETEST_DISTANCE_C_MAX", 1.00)):
            score = 20.0
        else:
            score = 5.0

        zone_reclaim = bool(pc < z <= lc)
        higher_low = bool(float(df["low"].iloc[-2]) > float(df["low"].iloc[-3]) >= float(df["low"].iloc[-4]))
        bullish_close = bool(lc > op and lc >= pc)
        e20 = df["close"].ewm(span=20, adjust=False).mean()
        closed_e20 = e20.iloc[-9:-1]
        ema20_slope_up = bool(
            len(closed_e20) >= 2 and
            float(closed_e20.iloc[-1]) > float(closed_e20.iloc[0]) * (1.0 + 0.0001)
        )
        p15_stack = bool(fs.get("p15_stack", False))
        try:
            rejection = bool(MicroStructure.rejection_candle_confirm(df))
        except Exception:
            rejection = False

        if zone_reclaim:
            score += float(CONFIG.get("V657_RETEST_RECLAIM_BONUS", 10.0))
        if higher_low:
            score += float(CONFIG.get("V657_RETEST_HIGHER_LOW_BONUS", 10.0))
        if bullish_close:
            score += float(CONFIG.get("V657_RETEST_BULLISH_CLOSE_BONUS", 5.0))
        if ema20_slope_up:
            score += float(CONFIG.get("V657_RETEST_EMA_SLOPE_BONUS", 5.0))
        if rejection:
            score += float(CONFIG.get("V657_RETEST_REJECTION_BONUS", 10.0))
        if p15_stack:
            score += float(CONFIG.get("V657_RETEST_15M_STACK_BONUS", 5.0))

        score = max(0.0, min(float(CONFIG.get("V657_RETEST_MAX_SCORE", 100.0)), score))
        out.update({
            "retest_quality_score": score,
            "retest_quality": score,
            "zone_ref": z,
            "zone_dist_atr": dist_atr,
            "zone_reclaim": zone_reclaim,
            "higher_low": higher_low,
            "bullish_close": bullish_close,
            "ema20_slope_up": ema20_slope_up,
            "rejection_candle": rejection,
            "p15_stack": p15_stack,
        })
        return out
    except Exception as exc:
        STATS["v657_retest_recompute_errors"] = int(STATS.get("v657_retest_recompute_errors", 0) or 0) + 1
        return {"error": type(exc).__name__}


# Run the corrected retest measurement before the existing V653/V587 contract.
try:
    _v657_prev_v587_quality = _v587_pullback_quality
    if not getattr(_v657_prev_v587_quality, "_v657_wrapped", False):
        def _v657_v587_pullback_quality(candidate, market_data=None):
            fam = str(getattr(candidate, "strategy_mode", "") or getattr(candidate, "family", "") or "").upper()
            if fam not in {"PULLBACK", "MTF_PULLBACK"}:
                return _v657_prev_v587_quality(candidate, market_data)
            fresh = _v657_recompute_retest_quality(candidate, market_data)
            if fresh.get("retest_quality_score") is None:
                return _v657_prev_v587_quality(candidate, market_data)
            try:
                fs = dict(getattr(candidate, "features_snapshot", {}) or {})
                # Replace only the retest measurement and its current-bar facts.
                for k, v in fresh.items():
                    if k != "error" and v is not None:
                        fs[k] = v
                refreshed = replace(candidate, features_snapshot=fs)
            except Exception:
                refreshed = candidate
            q = _v657_prev_v587_quality(refreshed, market_data)
            if isinstance(q, dict):
                q = dict(q)
                q["v657_retest_recomputed"] = True
                q["v657_retest_facts"] = {k: v for k, v in fresh.items() if k != "error"}
                if q.get("reason") == "retest_weak":
                    STATS["v657_retest_weak_after_recompute"] = int(STATS.get("v657_retest_weak_after_recompute", 0) or 0) + 1
                elif q.get("ok"):
                    STATS["v657_retest_recompute_passes"] = int(STATS.get("v657_retest_recompute_passes", 0) or 0) + 1
            return q
        _v657_v587_pullback_quality._v657_wrapped = True
        _v587_pullback_quality = _v657_v587_pullback_quality
except Exception:
    pass


