# -----------------------------------------------------------------------------
# V657 rejection dedup closure.
# V653's original key could accidentally include a generated timestamp, making
# the same setup look new on every scan. V657 keys repeated alerts by symbol,
# family, stage, reason and a small price/zone bucket instead. Material price
# changes still create a new key; this is telemetry only and never affects the
# trading decision.
# -----------------------------------------------------------------------------
def _v657_rejection_key(symbol, family, mode, stage, reason, payload):
    try:
        pct = max(0.01, float(CONFIG.get("V657_REJECTION_PRICE_BUCKET_PCT", 0.08))) / 100.0
        def finite_price(value):
            try:
                n = float(value)
                return n if math.isfinite(n) and n > 0.0 else None
            except Exception:
                return None
        entry = finite_price((payload or {}).get("entry", (payload or {}).get("entry_ref")))
        zone = finite_price((payload or {}).get("zone_ref"))
        log_step = math.log1p(pct)
        def bucket(v):
            # Relative/log bucket: unlike v/(abs(v)*pct), this changes as price moves.
            return "na" if v is None or log_step <= 0 else str(int(round(math.log(v) / log_step)))
        return "|".join((
            str(symbol or "").upper(), str(family or "").upper(), str(mode or "").upper(),
            str(stage or "").lower(), str(reason or "").lower(), bucket(entry), bucket(zone)
        ))
    except Exception:
        return f"{symbol}|{family}|{mode}|{stage}|{reason}"

try:
    _v657_prev_enqueue = _v652_enqueue_rejection_telegram
    def _v657_enqueue_rejection_telegram(symbol: str, *, reason: str, stage: str = "",
                                          score: Optional[float] = None,
                                          context: Optional[Dict[str, Any]] = None,
                                          trace_id: Optional[str] = None) -> bool:
        if not bool(CONFIG.get("V657_REJECTION_DEDUP_ENABLE", True)):
            return _v657_prev_enqueue(symbol, reason=reason, stage=stage, score=score,
                                       context=context, trace_id=trace_id)
        ctx = dict(context or {})
        fam = str(ctx.get("family") or ctx.get("strategy_mode") or "UNKNOWN")
        mode = str(ctx.get("mode") or ctx.get("strategy_mode") or fam)
        try:
            key = _v657_rejection_key(symbol, fam, mode, stage, reason, ctx)
            if not _v652_rejection_dedup_ok(key, symbol):
                return False
        except Exception:
            # Dedup is observability-only. If it cannot be evaluated, preserve
            # the canonical alert path rather than risk changing trading.
            pass
        return _v657_prev_enqueue(symbol, reason=reason, stage=stage, score=score,
                                  context=ctx, trace_id=trace_id)
    _v652_enqueue_rejection_telegram = _v657_enqueue_rejection_telegram
except Exception:
    pass

