def _v657_current_stage_reason():
    try:
        for k in (
            "v569_selected_stage_reason",
            "selected_stage",
            "v547_last_selected_stage",
            "v534_last_route_block_stage",
            "v542_last_preflight_reason",
        ):
            v = STATS.get(k)
            if v not in (None, "", "-", "NONE"):
                return str(v)
    except Exception:
        pass
    return ""


def _v657_stage_bucket(reason):
    r = str(reason or "").lower()
    if "liquidity" in r or "tier_below" in r or "spread" in r or "orderbook" in r or "depth" in r:
        return "LIQUIDITY"
    if "pre_send" in r or "presend" in r or "fee" in r:
        return "PRE_SEND"
    if "execution" in r or "send_fail" in r or "balance" in r:
        return "EXECUTION"
    if "htf" in r:
        return "HTF"
    if "structure" in r or "microstruct" in r or "fake_break" in r:
        return "STRUCTURE"
    return "OTHER"


def _v657_starvation_mode_override(default_mode="NONE"):
    try:
        if not bool(CONFIG.get("V657_STARVATION_CURRENT_STAGE_PRIORITY", True)):
            return default_mode
        selected = int(STATS.get("global_selected", STATS.get("v45_global_winners", 0)) or 0)
        queued = int(STATS.get("signals_queued", 0) or 0)
        sent = int(STATS.get("signals_sent", 0) or 0)
        if selected > 0 and queued == 0 and sent == 0:
            stage = _v657_current_stage_reason()
            if stage:
                return _v657_stage_bucket(stage)
        return default_mode
    except Exception:
        return default_mode


