def _v657_self_test():
    checks={}
    try:
        import pandas as pd
        rows=[]
        for i in range(35):
            p=100+0.05*i
            rows.append({"open":p-0.02,"high":p+0.06,"low":p-0.08,"close":p,"volume":1000.0})
        rows[-3]["low"]=101.35; rows[-3]["close"]=101.45
        rows[-2].update({"open":101.43,"high":101.72,"low":101.38,"close":101.68,"volume":1250.0})
        df=pd.DataFrame(rows)
        c=type("C",(),{})(); c.family="PULLBACK"; c.strategy_mode="PULLBACK"; c.zone_ref=101.65; c.entry_ref=101.68; c.engine_score=0.99
        c.features_snapshot={"p15_stack":True,"htf_strength":85.0,"volume_ratio":1.1,"rs_5m":0.01,"structure_confidence":80.0,"chase_atr":0.2}
        r=_v657_recompute_retest_quality(c,{"df_5m":df})
        checks["retest_recomputed"] = float(r.get("retest_quality_score",0.0)) >= 45.0
        checks["retest_closed_bar_facts"] = bool("higher_low" in r and "bullish_close" in r)
        checks["hard_retest_floor_intact"] = float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE",45.0)) >= 45.0
        checks["fee_floor_intact"] = float(CONFIG.get("MIN_TP1_TO_FEE_RATIO",2.5)) >= 2.5
        checks["risk_floor_intact"] = float(CONFIG.get("MIN_NET_RR_OVERALL",1.2)) >= 1.2
        checks["long_only_spot"] = bool(CONFIG.get("LONG_ONLY",True)) and str(CONFIG.get("MARKET_TYPE","SPOT")).upper()=="SPOT"
        k1 = _v657_rejection_key("BTC/USDT","PULLBACK","PULLBACK","prequal","retest_weak",{"entry":100.0,"zone_ref":99.5})
        k2 = _v657_rejection_key("BTC/USDT","PULLBACK","PULLBACK","prequal","retest_weak",{"entry":100.02,"zone_ref":99.5})
        checks["rejection_key_stable_nearby"] = k1 == k2
        checks["rejection_dedup_enabled"] = bool(CONFIG.get("V657_REJECTION_DEDUP_ENABLE",True))
    except Exception:
        checks["retest_recomputed"] = False
        checks["retest_closed_bar_facts"] = False
        checks["hard_retest_floor_intact"] = False
        checks["fee_floor_intact"] = False
        checks["risk_floor_intact"] = False
        checks["long_only_spot"] = False
    return {"pass":all(bool(v) for v in checks.values()),"checks":checks,"details":{"version":V657_FINAL_IDENTITY}}

