def _v658_num(v):
    try:
        x = float(v)
        return x if math.isfinite(x) else None
    except Exception:
        return None


def _v658_family(candidate):
    try:
        return str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
    except Exception:
        return ""


def _v658_rs_value(sym_df, btc_df, lookback):
    try:
        n = int(lookback)
        if sym_df is None or btc_df is None or len(sym_df) < n + 3 or len(btc_df) < n + 3:
            return None
        sa = float(sym_df["close"].iloc[-2]); sb = float(sym_df["close"].iloc[-(n + 2)])
        ba = float(btc_df["close"].iloc[-2]); bb = float(btc_df["close"].iloc[-(n + 2)])
        if min(sa, sb, ba, bb) <= 0 or not all(math.isfinite(v) for v in (sa, sb, ba, bb)):
            return None
        return (sa / sb - 1.0) - (ba / bb - 1.0)
    except Exception:
        return None


def _v658_closed_evidence(candidate, snap):
    out = {}
    try:
        md = snap if isinstance(snap, dict) else {}
        df = md.get("df_5m")
        btc = md.get("df_btc_5m")
        if df is None or len(df) < 30:
            return out
        lc = float(df["close"].iloc[-2]); pc = float(df["close"].iloc[-3])
        op = float(df["open"].iloc[-2]); hi = float(df["high"].iloc[-2]); lo = float(df["low"].iloc[-2])
        atr_s = Indicators.atr(df, int(CONFIG.get("ATR_PERIOD", 14)))
        atr = float(atr_s.iloc[-2]) if atr_s is not None else 0.0
        e20s = df["close"].ewm(span=20, adjust=False).mean()
        e50s = df["close"].ewm(span=50, adjust=False).mean()
        e20 = float(e20s.iloc[-2]); e50 = float(e50s.iloc[-2])
        if not (math.isfinite(atr) and atr > 0 and math.isfinite(e20) and math.isfinite(e50)):
            return out
        fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        zone = getattr(candidate, "zone_ref", None)
        if zone is None:
            zone = fs.get("zone_ref")
        zone = _v658_num(zone)
        out.update({
            "close": lc, "prev_close": pc, "open": op, "high": hi, "low": lo,
            "atr": atr, "above_ema20": bool(lc >= e20), "above_ema50": bool(lc >= e50),
            "bullish_close": bool(lc > op and lc >= pc),
            "higher_low": bool(float(df["low"].iloc[-2]) > float(df["low"].iloc[-3]) >= float(df["low"].iloc[-4])),
            "ema20_slope_up": bool(float(e20s.iloc[-2]) > float(e20s.iloc[-9]) * 1.0001),
            "body_ratio": abs(lc - op) / max(hi - lo, 1e-12),
        })
        if zone is not None and zone > 0:
            out["zone_ref"] = zone
            out["zone_reclaim"] = bool(pc < zone <= lc)
            out["zone_dist_atr"] = abs(lc - zone) / atr
        else:
            out["zone_reclaim"] = False
            out["zone_dist_atr"] = None
        av20 = float(df["volume"].iloc[-22:-2].mean())
        av5 = float(df["volume"].iloc[-7:-2].mean())
        cv = float(df["volume"].iloc[-2])
        out["volume_ratio"] = cv / av20 if av20 > 0 else None
        out["trigger_volume_ratio"] = cv / av5 if av5 > 0 else None
        out["rs_5m"] = _v658_rs_value(df, btc, int(CONFIG.get("V658_RS_SHORT_LOOKBACK", 6)))
        out["rs_3m"] = _v658_rs_value(df, btc, 3)
        out["rs_12m"] = _v658_rs_value(df, btc, int(CONFIG.get("V658_RS_BASE_LOOKBACK", 12)))
        if btc is not None:
            prev_rs = _v658_rs_value(df.iloc[:-1], btc.iloc[:-1], int(CONFIG.get("V658_RS_SHORT_LOOKBACK", 6)))
        else:
            prev_rs = None
        out["rs_prev_short"] = prev_rs
        if out.get("rs_5m") is not None and out.get("rs_12m") is not None:
            out["rs_improvement"] = float(out["rs_5m"] - out["rs_12m"])
        else:
            out["rs_improvement"] = None
        out["p15_stack"] = bool(fs.get("p15_stack", False))
        out["d1_bull"] = str(fs.get("d1_trend", "")).upper() == "BULLISH"
        out["h4_bull"] = str(fs.get("h4_trend", "")).upper() == "BULLISH"
        try:
            out["rejection_candle"] = bool(MicroStructure.rejection_candle_confirm(df))
        except Exception:
            out["rejection_candle"] = False
        return out
    except Exception:
        return {}


def _v658_independent_confirmations(candidate, evidence):
    fs = dict(getattr(candidate, "features_snapshot", {}) or {})
    return int(sum(bool(x) for x in (
        fs.get("higher_low_5m", False),
        fs.get("bullish_close_5m", False),
        fs.get("p15_stack", False),
        str(fs.get("d1_trend", "")).upper() == "BULLISH",
        str(fs.get("h4_trend", "")).upper() == "BULLISH",
        evidence.get("higher_low", False),
        evidence.get("bullish_close", False),
        evidence.get("zone_reclaim", False),
        evidence.get("ema20_slope_up", False),
        evidence.get("above_ema50", False),
        evidence.get("rejection_candle", False),
    )))


def _v658_rebuild_candidate(candidate, features):
    """Copy a candidate with updated features across dataclass and test-double types."""
    fs = dict(features or {})
    try:
        return replace(candidate, features_snapshot=fs)
    except Exception:
        pass
    try:
        import copy as _copy
        clone = _copy.copy(candidate)
        setattr(clone, "features_snapshot", fs)
        return clone
    except Exception:
        return candidate


def _v658_quality_reconcile(candidate, snap):
    """Return a reconciled immutable candidate plus audit context.

    At most one weak measurement can be reconciled. The original V587 hard
    contract is always run AGAIN after the replacement. This is therefore a
    measurement-reconciliation lane, not a generalized bypass.
    """
    try:
        fam = _v658_family(candidate)
        if fam not in {"PULLBACK", "MTF_PULLBACK"} or not bool(CONFIG.get("V658_QUALITY_RECONCILIATION_ENABLE", True)):
            return candidate, {"applied": False, "reason": "family_or_disabled"}
        fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        score = _v658_num(getattr(candidate, "engine_score", 0.0))
        score100 = score * 100.0 if score is not None and score <= 1.0 else score
        htf = _v658_num(fs.get("htf_strength", fs.get("htf_alignment")))
        structure = _v658_num(fs.get("structure_confidence", fs.get("structure_quality")))
        retest = _v658_num(fs.get("retest_quality_score", fs.get("retest_quality")))
        volume = _v658_num(fs.get("volume_ratio"))
        rs = _v658_num(fs.get("rs_5m", fs.get("rs_score_val", fs.get("relative_strength"))))
        original_volume = volume
        original_rs = rs
        chase = _v658_num(fs.get("chase_atr"))
        ev = _v658_closed_evidence(candidate, snap)
        if not ev:
            return candidate, {"applied": False, "reason": "closed_data_unavailable"}
        try:
            fresh_retest = _v657_recompute_retest_quality(candidate, snap) if callable(globals().get("_v657_recompute_retest_quality")) else {}
            if _v658_num(fresh_retest.get("retest_quality_score")) is not None:
                retest = _v658_num(fresh_retest.get("retest_quality_score"))
        except Exception:
            pass
        if _v658_num(ev.get("volume_ratio")) is not None:
            volume = _v658_num(ev.get("volume_ratio"))
        if _v658_num(ev.get("rs_5m")) is not None:
            rs = _v658_num(ev.get("rs_5m"))
        if score100 is None or score100 < float(CONFIG.get("V658_MIN_ENGINE_SCORE",97.0)):
            return candidate, {"applied": False, "reason": "engine_below_floor"}
        if htf is None or htf < float(CONFIG.get("V658_MIN_HTF",65.0)):
            return candidate, {"applied": False, "reason": "htf_below_floor"}
        if structure is None or structure < float(CONFIG.get("V658_MIN_STRUCTURE",60.0)):
            return candidate, {"applied": False, "reason": "structure_below_floor"}
        if chase is None or chase > float(CONFIG.get("V658_MAX_CHASE_ATR",0.60)):
            return candidate, {"applied": False, "reason": "chase_too_high"}
        conf = _v658_independent_confirmations(candidate, ev)
        if conf < int(CONFIG.get("V658_MIN_CONFIRMATIONS",2)):
            return candidate, {"applied": False, "reason": "confirmations_below_floor", "confirmations": conf}
        weaknesses = []
        if retest is None or retest < float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE",45.0)):
            weaknesses.append("retest")
        if original_volume is None or original_volume < float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO",0.85)):
            weaknesses.append("volume")
        if original_rs is None or original_rs < float(CONFIG.get("V587_PULLBACK_MIN_RS",0.0)):
            weaknesses.append("rs")
        if len(weaknesses) != 1:
            return candidate, {"applied": False, "reason": "zero_or_multiple_weaknesses", "weaknesses": weaknesses, "confirmations": conf}
        weakness = weaknesses[0]
        new_fs = dict(fs)
        recovered = False
        why = ""
        if weakness == "retest":
            zd = ev.get("zone_dist_atr")
            structural_anchor = bool(ev.get("zone_reclaim") or ev.get("higher_low") or ev.get("above_ema50"))
            if (zd is not None and zd <= float(CONFIG.get("V658_MAX_RETEST_DISTANCE_ATR",0.75))
                    and structural_anchor and bool(ev.get("bullish_close") or ev.get("rejection_candle"))):
                new_fs["retest_quality_score"] = max(float(CONFIG.get("V657_RETEST_RECOMPUTE_ENABLE", True) and float(CONFIG.get("V658_RETEST_RECOVERY_SCORE",55.0)) or 55.0), float(retest or 0.0))
                new_fs["retest_quality"] = new_fs["retest_quality_score"]
                recovered = True
                why = "closed_bar_reclaim_retest"
        elif weakness == "volume":
            vr = _v658_num(ev.get("volume_ratio"))
            tvr = _v658_num(ev.get("trigger_volume_ratio"))
            if (vr is not None and vr >= float(CONFIG.get("V658_VOLUME_ALT_MIN_BASE_RATIO",0.75))
                    and tvr is not None and tvr >= float(CONFIG.get("V658_VOLUME_TRIGGER_MIN_RATIO",1.10))
                    and bool(ev.get("bullish_close") or ev.get("zone_reclaim") or ev.get("higher_low"))
                    and (retest is None or retest >= float(CONFIG.get("V658_MIN_RETEST",45.0)))
                    and (rs is None or rs >= float(CONFIG.get("V587_PULLBACK_MIN_RS",0.0)))):
                new_fs["volume_ratio"] = max(float(CONFIG.get("V658_VOLUME_RECOVERY_RATIO",0.90)), float(vr))
                new_fs["v658_volume_reconciled"] = True
                new_fs["v658_trigger_volume_ratio"] = tvr
                recovered = True
                why = "reclaim_volume_vs_local_pullback_baseline"
        elif weakness == "rs":
            r5 = _v658_num(ev.get("rs_5m")); r3 = _v658_num(ev.get("rs_3m")); r12 = _v658_num(ev.get("rs_12m")); impr = _v658_num(ev.get("rs_improvement"))
            improving = (impr is not None and impr >= float(CONFIG.get("V658_RS_IMPROVEMENT_MIN",0.0005))) or (r3 is not None and r3 > 0.0)
            if (r5 is not None and r12 is not None and r5 >= float(CONFIG.get("V658_RS_MAX_NEGATIVE",-0.0030))
                    and r12 >= -0.004 and improving
                    and bool(ev.get("bullish_close") or ev.get("zone_reclaim") or ev.get("higher_low"))
                    and (retest is None or retest >= float(CONFIG.get("V658_MIN_RETEST",45.0)))
                    and (volume is None or volume >= float(CONFIG.get("V658_MIN_VOLUME",0.75)))):
                new_fs["rs_5m"] = float(CONFIG.get("V658_RS_RECOVERY_VALUE",0.0))
                new_fs["rs_reconciled"] = True
                new_fs["v658_rs_5m_raw"] = r5
                new_fs["v658_rs_12m"] = r12
                new_fs["v658_rs_improvement"] = impr
                recovered = True
                why = "improving_relative_strength_on_closed_bars"
        if not recovered:
            return candidate, {"applied": False, "reason": f"{weakness}_not_recoverable", "weakness": weakness, "confirmations": conf}
        new_fs["v658_quality_reconciled"] = True
        new_fs["v658_reconciled_weakness"] = weakness
        new_fs["v658_reconciled_reason"] = why
        new_fs["v658_closed_evidence"] = dict(ev)
        reconciled = _v658_rebuild_candidate(candidate, new_fs)
        try:
            if reconciled is candidate and dict(getattr(candidate, "features_snapshot", {}) or {}) != new_fs:
                return candidate, {"applied": False, "reason": "candidate_replace_failed", "weakness": weakness}
        except Exception:
            return candidate, {"applied": False, "reason": "candidate_replace_failed", "weakness": weakness}
        # Critical proof: the ORIGINAL V587 contract must pass after the change.
        _hard_contract = globals().get("_v657_prev_v587_quality")
        if not callable(_hard_contract):
            _hard_contract = globals().get("_v587_pullback_quality")
        q = _hard_contract(reconciled, snap) if callable(_hard_contract) else {}
        if not isinstance(q, dict) or not bool(q.get("ok", False)):
            STATS["v658_reconciliation_contract_failures"] = int(STATS.get("v658_reconciliation_contract_failures",0) or 0) + 1
            return candidate, {
                "applied": False, "reason": "v587_contract_failed_after_reconcile",
                "weakness": weakness, "post_reason": str((q or {}).get("reason", "")), "confirmations": conf,
            }
        STATS["v658_reconciliation_passes"] = int(STATS.get("v658_reconciliation_passes",0) or 0) + 1
        STATS[f"v658_reconciliation_pass.{weakness}"] = int(STATS.get(f"v658_reconciliation_pass.{weakness}",0) or 0) + 1
        return reconciled, {
            "applied": True, "weakness": weakness, "reason": why, "confirmations": conf,
            "post_v587_reason": "pass", "closed_evidence": dict(ev),
        }
    except Exception as exc:
        STATS["v658_reconciliation_errors"] = int(STATS.get("v658_reconciliation_errors",0) or 0) + 1
        return candidate, {"applied": False, "reason": f"exception:{type(exc).__name__}"}


# V658 becomes the last V587 evaluator so all later callers receive the same
# reconciled quality decision.
try:
    _v658_base_v587_quality = _v587_pullback_quality
    def _v658_v587_pullback_quality(candidate, market_data=None):
        fam = _v658_family(candidate)
        if fam not in {"PULLBACK", "MTF_PULLBACK"}:
            return _v658_base_v587_quality(candidate, market_data)
        reconciled, diag = _v658_quality_reconcile(candidate, market_data)
        if diag.get("applied") and callable(globals().get("_v657_prev_v587_quality")):
            q = _v657_prev_v587_quality(reconciled, market_data)
        else:
            q = _v658_base_v587_quality(reconciled, market_data)
        if isinstance(q, dict):
            q = dict(q)
            q["v658_reconciliation"] = dict(diag or {})
            if diag.get("applied"):
                q["v658_quality_reconciled"] = True
                q["v658_reconciled_weakness"] = str(diag.get("weakness", ""))
                q["v658_reconciled_reason"] = str(diag.get("reason", ""))
            else:
                q["v658_quality_reconciled"] = False
        return q
    _v587_pullback_quality = _v658_v587_pullback_quality
except Exception:
    pass


# Structural arbiter consumes the same reconciled candidate/evidence. It remains
# recovery-only for PB/MTF; other strategy families are untouched.
try:
    _v658_base_structural = _v655_canonical_structural_decision
    def _v658_structural(candidate, snap, *, detector_reason=""):
        fam = _v658_family(candidate)
        if fam in {"PULLBACK", "MTF_PULLBACK"}:
            reconciled, diag = _v658_quality_reconcile(candidate, snap)
            if diag.get("applied"):
                try:
                    ev = _v658_closed_evidence(reconciled, snap)
                    score = _v658_num(getattr(reconciled, "engine_score", 0.0))
                    score = score * 100.0 if score is not None and score <= 1.0 else score
                    fs = dict(getattr(reconciled, "features_snapshot", {}) or {})
                    htf = _v658_num(fs.get("htf_strength", fs.get("htf_alignment")))
                    structure = _v658_num(fs.get("structure_confidence", fs.get("structure_quality")))
                    chase = _v658_num(fs.get("chase_atr"))
                    conf = _v658_independent_confirmations(reconciled, ev)
                    anchor = bool(ev.get("zone_reclaim") or ev.get("higher_low") or ev.get("above_ema50") or ev.get("ema20_slope_up"))
                    hard_contract = globals().get("_v657_prev_v587_quality")
                    q = hard_contract(reconciled, snap) if callable(hard_contract) else {}
                    if (isinstance(q, dict) and bool(q.get("ok")) and score is not None and score >= float(CONFIG.get("V658_STRUCTURAL_RECOVERY_MIN_ENGINE",97.0))
                            and htf is not None and htf >= float(CONFIG.get("V658_STRUCTURAL_RECOVERY_MIN_HTF",65.0))
                            and structure is not None and structure >= float(CONFIG.get("V658_STRUCTURAL_RECOVERY_MIN_STRUCTURE",60.0))
                            and chase is not None and chase <= float(CONFIG.get("V658_STRUCTURAL_RECOVERY_MAX_CHASE",0.60))
                            and conf >= int(CONFIG.get("V658_STRUCTURAL_RECOVERY_MIN_CONFIRMATIONS",2)) and anchor
                            and bool(ev.get("bullish_close") or ev.get("rejection_candle"))):
                        STATS["v658_structural_recovered_after_quality"] = int(STATS.get("v658_structural_recovered_after_quality",0) or 0)+1
                        return True, {"reason":"v658.quality_reconciled_structural_recovery", "detector_reason":str(detector_reason or ""), **diag, "closed_evidence":ev, "confirmations":conf}, "RECOVERABLE"
                except Exception:
                    pass
        return _v658_base_structural(candidate, snap, detector_reason=detector_reason)
    _v655_canonical_structural_decision = _v658_structural
except Exception:
    pass


# Improve rejection bucket attribution so "other" no longer masks known
# precision/fee/selection blockers.
try:
    _v658_prev_stage_bucket = _v657_stage_bucket if "_v657_stage_bucket" in globals() else None
    def _v658_stage_bucket(reason):
        r = str(reason or "").lower()
        if any(x in r for x in ("fee_unviable", "fee viability", "sizing.fee", "fee_rank_rescue", "fee_rescue")):
            return "FEE"
        if any(x in r for x in ("retest_weak", "volume_below_floor", "rs_negative", "setup_quality", "pullback_precision")):
            return "STRUCTURE"
        if any(x in r for x in ("family_tier_below_floor", "below_tier", "orderbook", "spread", "liquidity")):
            return "LIQUIDITY"
        if _v658_prev_stage_bucket:
            return _v658_prev_stage_bucket(reason)
        return "OTHER"
    _v657_stage_bucket = _v658_stage_bucket
except Exception:
    pass


