# Final validation/self-test. Critical properties are fail-closed.
def _v658_self_test():
    checks = {}
    try:
        checks["identity_fields_present"] = bool(V658_FINAL_IDENTITY)
        checks["long_only_spot"] = bool(CONFIG.get("LONG_ONLY", True)) and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT"
        checks["hard_retest_floor_intact"] = float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE",45.0)) >= 45.0
        checks["hard_volume_floor_intact"] = float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO",0.85)) >= 0.85
        checks["hard_setup_floor_intact"] = float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY",72.0)) >= 72.0
        checks["fee_floor_intact"] = float(CONFIG.get("MIN_TP1_TO_FEE_RATIO",2.5)) >= 2.5
        checks["rr_floor_intact"] = float(CONFIG.get("MIN_NET_RR_OVERALL",1.2)) >= 1.2
    except Exception:
        for k in ("identity_fields_present","long_only_spot","hard_retest_floor_intact","hard_volume_floor_intact","hard_setup_floor_intact","fee_floor_intact","rr_floor_intact"):
            checks[k] = False
    try:
        # Synthetic closed-bar evidence where exactly ONE weakness (volume)
        # is recoverable via local trigger participation. This proves the lane
        # is selective rather than a general floor bypass.
        import pandas as pd
        rows=[]
        for i in range(40):
            p=100.0 + i*0.06
            rows.append({"open":p-0.01,"high":p+0.08,"low":p-0.05,"close":p+0.02,"volume":1000.0})
        rows[-3]["low"] = rows[-4]["low"] + 0.01
        rows[-2].update({"open":102.10,"high":102.36,"low":102.04,"close":102.30,"volume":1120.0})
        df=pd.DataFrame(rows)
        c=type("C",(),{})(); c.family="PULLBACK"; c.strategy_mode="PULLBACK"; c.symbol="TEST/USDT"; c.engine_score=0.99; c.zone_ref=102.18
        c.features_snapshot={"htf_strength":85.0,"structure_quality":80.0,"retest_quality_score":60.0,"volume_ratio":0.80,"rs_5m":0.01,"chase_atr":0.20,"higher_low_5m":True,"bullish_close_5m":True,"p15_stack":True,"d1_trend":"BULLISH","h4_trend":"BULLISH"}
        rc, diag = _v658_quality_reconcile(c,{"df_5m":df,"df_btc_5m":df.copy()})
        checks["single_weakness_reconciled"] = bool(diag.get("applied")) and diag.get("weakness") in {"volume","retest","rs"}
        q=_v658_base_v587_quality(rc,{"df_5m":df,"df_btc_5m":df.copy()})
        checks["reconciled_candidate_passes_v587"] = bool(q.get("ok",False))
    except Exception:
        checks["single_weakness_reconciled"] = False
        checks["reconciled_candidate_passes_v587"] = False
    return {"pass": all(bool(v) for v in checks.values()), "checks": checks, "details": {"version": V658_FINAL_IDENTITY}}




