def _v659_boot_integrity_self_test():
    """Exercise the exact public validator path used by main()."""
    checks, details = {}, {}
    try:
        ids = (str(SCRIPT_VERSION), str(CONFIG.get("SCRIPT_VERSION", "")),
               str(__version__), str(RUNTIME_BUILD_ID), str(CANONICAL_RUNTIME_IDENTITY))
        checks["identity_tuple"] = ids == (V659_FINAL_IDENTITY,) * 5
        checks["historical_aliases_synced"] = all(
            (name not in globals()) or globals()[name] == V659_FINAL_IDENTITY
            for name in _V659_HISTORICAL_ID_NAMES
        )
        checks["thresholds_intact"] = (
            float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO", 0.85)) >= 0.85
            and float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE", 45.0)) >= 45.0
            and float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY", 72.0)) >= 72.0
            and float(CONFIG.get("MIN_NET_RR_TP1", 0.8)) >= 0.8
            and float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5)) >= 2.5
            and float(CONFIG.get("MIN_NET_RR_OVERALL", 1.2)) >= 1.2
        )
        checks["long_only_spot"] = bool(CONFIG.get("LONG_ONLY", True)) and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT"
        result = validate_config()
        checks["public_validate_config"] = bool(result)
        details["public_validate_config"] = bool(result)
        details["failed_historical_checks"] = [
            k for k,v in (STATS.get("v640_final_selftest", {}).get("checks", {}) or {}).items() if not bool(v)
        ]
    except Exception as exc:
        checks["public_validate_config"] = False
        details["error"] = f"{type(exc).__name__}:{exc}"
    return {"pass": all(bool(v) for v in checks.values()), "checks": checks, "details": details}

