def _v661_prequalify(ranked_candidate, snap_by_symbol):
    c = getattr(ranked_candidate, "candidate", ranked_candidate)
    fam = _v661_family(c)
    if fam == "PULLBACK_CANONICAL":
        try:
            snap = (snap_by_symbol or {}).get(_v661_symbol(c), {}) or {}
            rec, diag = _v661_coordinated_candidate(c, snap)
            if rec is not c:
                try:
                    ranked_candidate = replace(ranked_candidate, candidate=rec)
                except Exception:
                    try:
                        import copy as _copy
                        rc = _copy.copy(ranked_candidate); rc.candidate = rec; ranked_candidate = rc
                    except Exception:
                        pass
            STATS["v661_prequal_reconciled"] = int(STATS.get("v661_prequal_reconciled", 0) or 0) + int(bool(diag.get("applied")))
        except Exception:
            pass
    ok, reason = _v661_previous_prequal(ranked_candidate, snap_by_symbol)
    if ok or fam != "PULLBACK_CANONICAL":
        return ok, reason
    rtxt = str(reason or "")
    recoverable_tokens = ("fake_break", "microstruct", "pullback_micro_uptrend_missing", "precision.retest", "precision.volume", "precision.rs")
    if any(t in rtxt.lower() for t in recoverable_tokens):
        try:
            snap = (snap_by_symbol or {}).get(_v661_symbol(getattr(ranked_candidate, "candidate", ranked_candidate)), {}) or {}
            cc = getattr(ranked_candidate, "candidate", ranked_candidate)
            rec, diag = _v661_coordinated_candidate(cc, snap)
            ok_s, d_s, cls_name = _v661_structural_decision(rec, snap, detector_reason=rtxt)
            if ok_s and cls_name == "RECOVERABLE":
                try:
                    fs = dict(getattr(rec, "features_snapshot", {}) or {})
                    fs["v661_structural_recovery"] = True
                    fs["v661_structural_recovery_reason"] = rtxt[:180]
                    rec = _v660_rebuild(rec, fs) if callable(globals().get("_v660_rebuild")) else rec
                    try: ranked_candidate = replace(ranked_candidate, candidate=rec)
                    except Exception: pass
                except Exception:
                    pass
                # One final original V587 proof after the structural recovery.
                q = _v661_hard_quality(rec, snap)
                if bool(q.get("ok")):
                    STATS["v661_prequal_structural_recoveries"] = int(STATS.get("v661_prequal_structural_recoveries", 0) or 0) + 1
                    return True, "v661.canonical_structural_recovery"
        except Exception:
            pass
    return ok, reason

_v453_prequalify = _v661_prequalify


