class _V662RejectionAggregator:
    _lock = threading.RLock()
    _rows = {}
    _last_flush = 0.0
    _total = 0
    _suppressed = 0
    # Cross-batch notification dedupe. Internal rejection accounting remains
    # untouched; only repetitive Telegram transport is suppressed.
    _recent_notified = {}

    @classmethod
    def _num(cls, v):
        try:
            x=float(v)
            return x if math.isfinite(x) else None
        except Exception:
            return None

    @classmethod
    def _key(cls, symbol, reason, stage, family, payload):
        # V664: entry price is intentionally NOT part of the primary identity.
        # Repricing by a few ticks is the same rejected setup for operator
        # notification purposes. A closed-candle id is retained when available
        # so a genuinely new setup can still generate a fresh notification.
        try:
            p = payload or {}
            candle = p.get("candle_ts") or p.get("closed_candle_ts") or p.get("bar_ts")
            fs = p.get("features_snapshot") if isinstance(p.get("features_snapshot"), dict) else {}
            candle = candle or fs.get("candle_ts") or fs.get("closed_candle_ts")
            candle_key = str(candle or "")[:80]
            return (str(symbol or ""), str(family or "").upper(),
                    str(stage or "").lower(), str(reason or "").lower(), candle_key)
        except Exception:
            return (str(symbol or ""), str(family or "").upper(),
                    str(stage or "").lower(), str(reason or "").lower(), "")

    @classmethod
    def add(cls, symbol, *, reason="unknown", stage="", score=None, context=None, trace_id=None):
        if not bool(CONFIG.get("V662_REJECTION_BATCH_ENABLE", True)):
            return False
        # V702 R10: import-time/self-test rejections are never admitted into
        # the LIVE operator batch. The forensic ledger remains untouched.
        if not bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
            STATS["v702_live_batch_prearm_rejections_blocked"] = int(
                STATS.get("v702_live_batch_prearm_rejections_blocked", 0) or 0
            ) + 1
            return False
        ctx=dict(context or {}) if isinstance(context, dict) else {}
        _stage_norm = str(stage or "").strip().lower()
        if _stage_norm in {"selftest", "validation", "synthetic"} or bool(ctx.get("synthetic")) or bool(ctx.get("validation_only")):
            STATS["v702_live_batch_synthetic_events_blocked"] = int(STATS.get("v702_live_batch_synthetic_events_blocked", 0) or 0) + 1
            return False
        family=str(ctx.get("family") or ctx.get("signal_family") or ctx.get("strategy_mode") or "UNKNOWN")
        key=cls._key(symbol, reason, stage, family, ctx)
        now=MONO_NOW()
        with cls._lock:
            # Keep full internal counts, but suppress re-notification of the
            # same symbol/reason/stage/candle for a bounded TTL across batch
            # flushes. This fixes the repeated 90s spam seen in LIVE logs.
            dedupe_sec = max(60.0, float(CONFIG.get("V664_REJECTION_NOTIFY_DEDUP_SEC", 300.0)))
            last_notice = float(cls._recent_notified.get(key, 0.0) or 0.0)
            if last_notice > 0.0 and (now - last_notice) < dedupe_sec:
                cls._suppressed += 1
                cls._total += 1
                STATS["v664_rejection_notify_dedup"] = int(STATS.get("v664_rejection_notify_dedup", 0) or 0) + 1
                return False
            row=cls._rows.get(key)
            if row is None:
                row={
                    "symbol":str(symbol or ""), "family":family.upper(), "stage":str(stage or ""),
                    "reason":str(reason or "unknown"), "count":0, "best_score":None,
                    "engine":cls._num(ctx.get("engine_score")), "htf":cls._num(ctx.get("htf_strength")),
                    "volume":cls._num(ctx.get("volume_ratio")), "rs":cls._num(ctx.get("rs_5m")),
                    "chase":cls._num(ctx.get("chase_atr")), "entry":cls._num(ctx.get("entry")),
                    "sl":cls._num(ctx.get("sl")), "first_ts":now, "last_ts":now,
                }
                cls._rows[key]=row
            row["count"] += 1
            row["last_ts"] = now
            sc=cls._num(score)
            if sc is None: sc=cls._num(ctx.get("score"))
            if sc is not None:
                row["best_score"] = sc if row["best_score"] is None else max(row["best_score"], sc)
            for k in ("engine_score","htf_strength","volume_ratio","rs_5m","chase_atr","entry","sl"):
                target={"engine_score":"engine","htf_strength":"htf","volume_ratio":"volume","rs_5m":"rs","chase_atr":"chase","entry":"entry","sl":"sl"}[k]
                x=cls._num(ctx.get(k))
                if x is not None: row[target]=x
            cls._total += 1
        return True

    @classmethod
    def snapshot_and_flush(cls, force=False):
        now=MONO_NOW()
        interval=max(30.0,float(CONFIG.get("V662_REJECTION_BATCH_INTERVAL_SEC",90.0)))
        with cls._lock:
            if not force and (now-cls._last_flush) < interval:
                return None
            if not cls._rows:
                cls._last_flush=now
                return None
            rows=list(cls._rows.values())
            notified_keys = list(cls._rows.keys())
            cls._rows={}
            dedupe_sec = max(60.0, float(CONFIG.get("V664_REJECTION_NOTIFY_DEDUP_SEC", 300.0)))
            for _k in notified_keys:
                cls._recent_notified[_k] = now
            if len(cls._recent_notified) > 4096:
                _cut = now - max(dedupe_sec, 60.0)
                cls._recent_notified = {k:v for k,v in cls._recent_notified.items() if v >= _cut}
            suppressed=cls._suppressed
            cls._suppressed=0
            cls._last_flush=now
        rows.sort(key=lambda r:(-int(r.get("count",0)), -(float(r.get("best_score") or 0.0))))
        max_rows=max(1,int(CONFIG.get("V662_REJECTION_BATCH_MAX_ROWS",18)))
        total=sum(int(r.get("count",0)) for r in rows)
        try:
            # V702 R10: the operator-facing batch is explicitly LIVE-EPOCH
            # scoped, preventing boot/self-test events from being reported as
            # live rejections merely because the first flush occurs quickly.
            _v669_events_window = V669RejectionLedger.recent(interval)
            _live_epoch = float(globals().get("_V699_LIVE_TELEMETRY_EPOCH", 0.0) or 0.0)
            if bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)) and _live_epoch > 0.0:
                _v669_events_window = [
                    _ev for _ev in _v669_events_window
                    if float(_ev.get("timestamp", 0.0) or 0.0) >= _live_epoch
                ]
            else:
                _v669_events_window = []
            _v669_unique_window = len({str(e.get("opportunity_id","")) for e in _v669_events_window if str(e.get("opportunity_id",""))})
            _v669_eval_window = len(_v669_events_window)
            _v669_bucket_window = V669RejectionLedger.counts(_v669_events_window)
            _v669_stage_counts = defaultdict(int)
            _v669_exception_types = defaultdict(int)
            for _ev in _v669_events_window:
                _v669_stage_counts[str(_ev.get("stage") or "unknown")] += 1
                if _ev.get("exception_type"):
                    _v669_exception_types[str(_ev.get("exception_type"))] += 1
        except Exception:
            _v669_unique_window = _v669_eval_window = 0
            _v669_bucket_window = {}
            _v669_stage_counts = defaultdict(int)
            _v669_exception_types = defaultdict(int)
        reason_counts={}
        family_counts={}
        for r in rows:
            reason_counts[r["reason"]]=reason_counts.get(r["reason"],0)+int(r["count"])
            family_counts[r["family"]]=family_counts.get(r["family"],0)+int(r["count"])
        top_reasons=sorted(reason_counts.items(),key=lambda kv:(-kv[1],kv[0]))[:6]
        top_fams=sorted(family_counts.items(),key=lambda kv:(-kv[1],kv[0]))[:6]
        lines=[
            "🧾 <b>REJECTION BATCH</b>",
            f"Window: <b>{interval:.0f}s</b> | Rejected evaluations: <b>{_v669_eval_window}</b> | Notification groups: <b>{len(rows)}</b> | Unique opportunities: <b>{_v669_unique_window}</b>",
            f"SYSTEM={_v669_bucket_window.get('SYSTEM',0)} POLICY={_v669_bucket_window.get('POLICY',0)} HTF={_v669_bucket_window.get('HTF',0)} LIQUIDITY={_v669_bucket_window.get('LIQUIDITY',0)} STRUCTURE={_v669_bucket_window.get('STRUCTURE',0)} SCORE={_v669_bucket_window.get('SCORE',0)} FEE={_v669_bucket_window.get('FEE',0)} PRE_SEND={_v669_bucket_window.get('PRE_SEND',0)} EXECUTION={_v669_bucket_window.get('EXECUTION',0)} OTHER={_v669_bucket_window.get('OTHER',0)}",
            "",
            "<b>Top reasons / stages / exception types</b>",
            "Stages: " + (", ".join(f"{k}×{v}" for k,v in sorted(_v669_stage_counts.items(), key=lambda kv:(-kv[1],kv[0]))[:5]) or "-"),
            "Exceptions: " + (", ".join(f"{k}×{v}" for k,v in sorted(_v669_exception_types.items(), key=lambda kv:(-kv[1],kv[0]))[:5]) or "-"),
            "",
            "<b>Top reasons</b>",
            ", ".join(f"{r}×{n}" for r,n in top_reasons) or "-",
            "",
            "<b>Top families</b>",
            ", ".join(f"{f}×{n}" for f,n in top_fams) or "-",
            "",
            "<b>Representative rejected setups</b>",
        ]
        for r in rows[:max_rows]:
            sym=OpportunityTelegramNotifier._escape(r["symbol"])
            rs=r.get("rs"); rs_txt=f" RS {rs*100:.2f}%" if rs is not None else ""
            v=r.get("volume"); v_txt=f" Vx{v:.2f}" if v is not None else ""
            sc=r.get("best_score"); sc_txt=f" S{sc:.1f}" if sc is not None else ""
            h=r.get("htf"); h_txt=f" H{h:.0f}" if h is not None else ""
            lines.append(
                f"• <b>{sym}</b> {OpportunityTelegramNotifier._escape(r['family'])} — "
                f"{OpportunityTelegramNotifier._escape(r['reason'])} ×{r['count']}"
                f"{sc_txt}{h_txt}{v_txt}{rs_txt}"
            )
            if r.get("entry") is not None and r.get("sl") is not None:
                lines.append(f"  Entry {r['entry']:.10g} | SL {r['sl']:.10g}")
        if len(rows)>max_rows:
            lines.append(f"… +{len(rows)-max_rows} additional groups")
        lines += ["", "<i>LIVE mode: each opportunity still passed through the canonical execution gates; this batch contains rejected opportunities only.</i>"]
        msg="\n".join(lines)
        lim=max(1000,int(CONFIG.get("V662_REJECTION_BATCH_MAX_CHARS",3600)))
        return msg[:lim]

    @classmethod
    def stats(cls):
        with cls._lock:
            return {"groups":len(cls._rows),"suppressed":cls._suppressed,"total":cls._total}


def _v662_rejection_batch_enqueue(symbol: str, *, reason: str, stage: str = "",
                                  score: Optional[float] = None,
                                  context: Optional[Dict[str, Any]] = None,
                                  trace_id: Optional[str] = None) -> bool:
    try:
        if not bool(CONFIG.get("TELEGRAM_ENABLED", True)):
            return False
        if not ENV.get("TELEGRAM_TOKEN") or not ENV.get("TELEGRAM_CHAT"):
            return False
        # Preserve the existing "meaningful opportunity" filter so low-value
        # noise does not fill the batch. Critical safety blocks remain included.
        ok, _, ctx = _v652_rejection_worthy(symbol, score, context or {}, reason, stage)
        if not ok:
            return False
        return bool(_V662RejectionAggregator.add(symbol, reason=reason, stage=stage,
                                                 score=score, context=ctx, trace_id=trace_id))
    except Exception:
        return False

# The canonical record_rejection wrappers resolve this global at call time;
# redirect them to the batch aggregator so no individual reject message is sent.
_v652_enqueue_rejection_telegram = _v662_rejection_batch_enqueue

# Direct blocked notifier path is also routed into the same aggregate and never
# emits an individual OPPORTUNITY REJECTED message.
try:
    _v662_prev_notify_blocked = OpportunityTelegramNotifier.notify_blocked.__func__
    @classmethod
    def _v662_notify_blocked_batch(cls, symbol: str, *, candle_ts: Optional[int] = None,
                                   reason: str = "unknown", stage: str = "",
                                   score: Optional[float] = None) -> bool:
        try:
            pending=cls._pending_for(symbol, candle_ts)
            if pending is None:
                STATS["telegram_blocked_without_pending_suppressed"] = STATS.get("telegram_blocked_without_pending_suppressed",0)+1
                return False
            _, payload=pending
            p=dict(payload or {})
            p["symbol"]=str(symbol); p["stage"]=str(stage or "unknown"); p["reason"]=str(reason or "unknown")
            if score is not None: p["score"]=score
            _V662RejectionAggregator.add(symbol, reason=reason, stage=stage, score=score, context=p)
            with cls._lock:
                for k in list(cls._pending.keys()):
                    if str((cls._pending.get(k) or {}).get("symbol"))==str(symbol):
                        if candle_ts is None or int((cls._pending.get(k) or {}).get("candle_ts",-1))==int(candle_ts):
                            cls._pending.pop(k,None)
                            break
            STATS["v662_blocked_batched"] = int(STATS.get("v662_blocked_batched",0) or 0)+1
            return True
        except Exception:
            return False
    OpportunityTelegramNotifier.notify_blocked = _v662_notify_blocked_batch
except Exception:
    pass

async def _v662_rejection_batch_task():
    """Single periodic Telegram writer for all non-critical rejection batches."""
    try:
        while _SHUTDOWN is None or not _SHUTDOWN.is_set():
            await asyncio.sleep(min(30.0, max(5.0, float(CONFIG.get("V662_REJECTION_BATCH_INTERVAL_SEC",90.0))/3.0)))
            msg=_V662RejectionAggregator.snapshot_and_flush(force=False)
            if msg:
                await TelegramDispatcher.enqueue(msg)
                STATS["v662_rejection_batches_sent"] = int(STATS.get("v662_rejection_batches_sent",0) or 0)+1
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        logger.debug(f"[V662-RejectionBatch] task suppressed: {type(exc).__name__}:{exc}")

# Flush once at shutdown where practical; no individual rejection is emitted.
def _v662_flush_pending_rejections_sync_note():
    try:
        d=_V662RejectionAggregator.stats()
        logger.info(f"[V662-RejectionBatch] pending_groups={d['groups']} suppressed={d['suppressed']} total={d['total']}")
    except Exception:
        pass

