# Start the rejection batch task through the existing run_bot task list without
# altering the canonical trading path.
try:
    _v662_orig_run_bot = run_bot
    async def _v662_run_bot(universe: List[str]):
        # LIVE operator mode is reapplied immediately before runtime startup.
        CONFIG["ENABLE_LIVE_TRADING"] = True
        CONFIG["PAPER_TRADING_MODE"] = False
        CONFIG["DEPLOYMENT_PROFILE"] = "live"
        CONFIG["V561_TELEGRAM_COMMANDS_ENABLE"] = True
        batch_task = None
        try:
            batch_task = asyncio.create_task(_v662_rejection_batch_task())
            return await _v662_orig_run_bot(universe)
        finally:
            # Best-effort final flush into the existing Telegram dispatcher.
            try:
                msg = _V662RejectionAggregator.snapshot_and_flush(force=True)
                if msg:
                    await TelegramDispatcher.enqueue(msg)
            except Exception:
                pass
            if batch_task is not None:
                batch_task.cancel()
                try:
                    await batch_task
                except (asyncio.CancelledError, Exception):
                    pass
    run_bot = _v662_run_bot
except Exception:
    pass

