# Deduplicate only the Starvation Alert Telegram transport. Logging and internal
# counters continue on every evaluation, so no diagnostic evidence is lost.
_V664_STARV_NOTICE = {"key": "", "ts": 0.0}
try:
    _v664_prev_starv_enqueue = TelegramDispatcher.enqueue
    async def _v664_starv_aware_enqueue(message, *args, **kwargs):
        try:
            text = str(message or "")
            if "<b>Starvation Alert</b>" in text or "[V422-StarvAlert]" in text:
                line = text.replace("\n", " ")
                import re as _re_v664
                mm = _re_v664.search(r"mode=([^ |]+).*?live_root=([^ |]+).*?exact_builder=([^ |]+)", line)
                key = "|".join(mm.groups()) if mm else line[:220]
                now = MONO_NOW()
                ttl = max(120.0, float(CONFIG.get("V664_STARVATION_NOTIFY_DEDUP_SEC", 300.0)))
                if _V664_STARV_NOTICE.get("key") == key and now - float(_V664_STARV_NOTICE.get("ts", 0.0)) < ttl:
                    STATS["v664_starvation_notify_dedup"] = int(STATS.get("v664_starvation_notify_dedup", 0) or 0) + 1
                    return None
                _V664_STARV_NOTICE.update({"key": key, "ts": now})
        except Exception:
            _v647_record_suppressed_exception()
        return await _v664_prev_starv_enqueue(message, *args, **kwargs)
    TelegramDispatcher.enqueue = staticmethod(_v664_starv_aware_enqueue)
except Exception:
    _v647_record_suppressed_exception()

