def _v666_live_ticket_probe_notional() -> float:
    """Return the configured LIVE ticket scale used for rank-time fee probing."""
    try:
        minimum = max(1.0, float(CONFIG.get("MIN_POSITION_SIZE_USDT", 15.0)))
        fixed = max(0.0, float(CONFIG.get("FIXED_POSITION_SIZE_USDT", 0.0)))
        maximum = max(minimum, float(CONFIG.get("MAX_POSITION_SIZE_USDT", 75.0)))
        requested = max(0.0, float(CONFIG.get("V576_REQUESTED_POSITION_USDT", fixed or maximum)))
        configured = fixed if fixed > 0 else requested
        return min(maximum, max(minimum, configured))
    except Exception:
        return max(1.0, float(CONFIG.get("MIN_POSITION_SIZE_USDT", 15.0)))

