def _v668_now():
    try:
        return MONO_NOW()
    except Exception:
        return time.monotonic()


def _v668_norm_family(candidate):
    try:
        fam = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
        if fam in {"PULLBACK", "MTF_PULLBACK", "PULLBACK_CANONICAL"}:
            return "PULLBACK_CANONICAL"
        return fam
    except Exception:
        return ""


def _v668_feedback_key(symbol, family):
    return (str(symbol or ""), _v668_norm_family(family))


def _v668_feedback_note(symbol, candidate, reason=""):
    if not bool(CONFIG.get("V668_FEEDBACK_ENABLE", True)):
        return
    try:
        fam = _v668_norm_family(candidate)
        key = _v668_feedback_key(symbol, fam)
        now = _v668_now()
        row = _V668_FEEDBACK.get(key)
        if not isinstance(row, dict):
            row = {"count": 0, "last": now, "last_reason": ""}
        row["count"] = int(row.get("count", 0) or 0) + 1
        row["last"] = now
        row["last_reason"] = str(reason or "unknown")[:160]
        _V668_FEEDBACK[key] = row
        if len(_V668_FEEDBACK) > _V668_FEEDBACK_MAX:
            old = sorted(_V668_FEEDBACK.items(), key=lambda kv: float(kv[1].get("last", 0.0) or 0.0))
            for k, _ in old[: max(1, len(_V668_FEEDBACK) - _V668_FEEDBACK_MAX)]:
                _V668_FEEDBACK.pop(k, None)
        STATS["v668_feedback_events"] = int(STATS.get("v668_feedback_events", 0) or 0) + 1
        STATS["v668_feedback_last"] = {
            "symbol": str(symbol or ""), "family": fam,
            "reason": str(reason or "unknown")[:160], "count": row["count"],
        }
    except Exception:
        _v647_record_suppressed_exception()


def _v668_feedback_penalty(candidate):
    if not bool(CONFIG.get("V668_FEEDBACK_ENABLE", True)):
        return 0.0
    try:
        key = _v668_feedback_key(getattr(candidate, "symbol", ""), candidate)
        row = _V668_FEEDBACK.get(key)
        if not isinstance(row, dict):
            return 0.0
        age = max(0.0, _v668_now() - float(row.get("last", _v668_now()) or _v668_now()))
        half = max(60.0, float(CONFIG.get("V668_FEEDBACK_HALF_LIFE_SEC", 1800.0)))
        decay = 0.5 ** (age / half)
        count = max(0, int(row.get("count", 0) or 0))
        step = max(0.0, float(CONFIG.get("V668_FEEDBACK_BASE_STEP", 0.006)))
        repeat = max(0.0, float(CONFIG.get("V668_FEEDBACK_REPEAT_BONUS", 0.004)))
        cap = max(0.0, float(CONFIG.get("V668_FEEDBACK_MAX_PENALTY", 0.045)))
        penalty = min(cap, (step * min(count, 6) + (repeat if count >= 3 else 0.0)) * decay)
        if penalty > 0:
            STATS["v668_feedback_last_penalty"] = float(penalty)
        return penalty
    except Exception:
        return 0.0


