# E) Stronger bounded family diversity at selection time. We call the original
# selector first, then only replace duplicate-family primaries when an unselected
# alternative family is already above the SAME global floor and close in score.
try:
    _v668_base_select = GlobalOpportunityArbiter.select
    def _v668_diverse_select(cls, ranked, max_winners=3):
        selected = list(_v668_base_select(ranked, max_winners) or [])
        if not bool(CONFIG.get("V668_FAMILY_ROTATION_ENABLE", True)) or not selected:
            return selected
        try:
            floor = float(GlobalOpportunityArbiter._effective_min_score())
            max_same = max(1, int(CONFIG.get("V668_FAMILY_ROTATION_MAX_SAME_FAMILY", 1)))
            max_gap = max(0.0, float(CONFIG.get("V668_FAMILY_ROTATION_MAX_SCORE_GAP", 0.035)))
            selected_symbols = {str(x.candidate.symbol) for x in selected}
            # Work on a score-ordered immutable view of the prequalified pool.
            scored = []
            for rr in list(ranked or []):
                try:
                    g = float(GlobalOpportunityArbiter._candidate_score(rr))
                    if g >= floor:
                        scored.append((g, rr))
                except Exception:
                    continue
            scored.sort(key=lambda x: x[0], reverse=True)
            used = list(selected)
            fam_counts = defaultdict(int)
            for x in used:
                fam_counts[_v668_norm_family(x.candidate)] += 1
            replacements = 0
            for idx in range(len(used)):
                cur = used[idx]
                fam = _v668_norm_family(cur.candidate)
                if fam_counts[fam] <= max_same:
                    continue
                cur_score = float(GlobalOpportunityArbiter._candidate_score(cur))
                replacement = None
                for alt_score, alt in scored:
                    if alt in used:
                        continue
                    afam = _v668_norm_family(alt.candidate)
                    asym = str(getattr(alt.candidate, "symbol", "") or "")
                    if asym in selected_symbols:
                        continue
                    if afam == fam:
                        continue
                    if cur_score - alt_score > max_gap + 1e-9:
                        continue
                    # Respect the same correlation hard-cap preference used by
                    # the base selector. A hard/near-hard correlation state is
                    # not a diversity target.
                    try:
                        cluster = CorrelationHardCap._cluster_of(asym)
                        if cluster:
                            overlap = sum(1 for s in ACTIVE_TRADES if s in cluster)
                            corr_pen = min(
                                float(CONFIG.get("V45_GLOBAL_CORRELATION_PENALTY", .035)) * max(1, overlap),
                                float(CONFIG.get("V45_GLOBAL_CORRELATION_PENALTY", .035)),
                            )
                            if alt_score - corr_pen < floor:
                                continue
                    except Exception:
                        pass
                    replacement = (alt_score, alt)
                    break
                if replacement:
                    _, alt = replacement
                    selected_symbols.discard(str(cur.candidate.symbol))
                    selected_symbols.add(str(alt.candidate.symbol))
                    fam_counts[fam] -= 1
                    fam_counts[_v668_norm_family(alt.candidate)] += 1
                    used[idx] = alt
                    replacements += 1
            if replacements:
                STATS["v668_family_rotations"] = int(STATS.get("v668_family_rotations", 0) or 0) + replacements
                logger.info(
                    "[V668-FAMILY-ROTATE] replacements=%d selected=%s",
                    replacements,
                    [(_v668_norm_family(x.candidate), str(x.candidate.symbol)) for x in used],
                )
            return used
        except Exception as exc:
            STATS["v668_family_rotation_errors"] = int(STATS.get("v668_family_rotation_errors", 0) or 0) + 1
            logger.debug("[V668-FAMILY-ROTATE] suppressed: %s", exc)
            return selected
    GlobalOpportunityArbiter.select = classmethod(_v668_diverse_select)
    STATS["v668_family_rotation_wrapped"] = True
except Exception as _v668_div_exc:
    STATS["v668_family_rotation_wrapped"] = False
    logger.critical("[V668] family rotation install failed: %s", _v668_div_exc)


# F) Extend the EXISTING centralized exit authority with one explicit, bounded
# max-hold reason. It remains fail-closed, requires an actually elapsed hold
# limit, never applies to target-only/ambiguous positions, and is the only new
# reason authorized by V668. All other reasons still delegate unchanged.
try:
    _v668_orig_exit_authority = _v571_exit_authority
    def _v668_exit_authority(trade, reason, exit_px=None, stage=None):
        r = str(reason or "").strip().lower()
        if r != str(CONFIG.get("V668_MAX_HOLD_FORCE_CLOSE_REASON", "time_exit_force")).strip().lower():
            return _v668_orig_exit_authority(trade, reason, exit_px=exit_px, stage=stage)
        if not bool(CONFIG.get("V668_MAX_HOLD_FORCE_CLOSE_ENABLE", True)):
            return False, "v668_max_hold_disabled"
        if bool(getattr(trade, "target_only_mode", False)):
            if not bool(CONFIG.get("V668_TARGET_ONLY_MAX_HOLD_EXIT_ENABLE", True)):
                return False, "target_only_mode"
            if not bool(getattr(trade, "software_sl_active", False)):
                return False, "target_only_without_software_sl"
        if getattr(trade, "v517_pending_exit_reconcile", None) is not None:
            return False, "pending_exit_reconcile"
        if getattr(trade, "v517_pending_sl_reconcile", None) is not None:
            return False, "pending_sl_reconcile"
        px = float(exit_px or getattr(trade, "last_mark_price", 0.0) or 0.0)
        if not math.isfinite(px) or px <= 0:
            return False, "exit_price_unverifiable"
        try:
            entry_dt = datetime.fromisoformat(str(getattr(trade, "entry_time", "")))
            age_h = (datetime.now(timezone.utc) - entry_dt).total_seconds() / 3600.0
            max_hold = float((getattr(trade, "exit_profile", {}) or {}).get(
                "max_hold_hours", CONFIG.get("TIME_BASED_EXIT_HOURS", 8.0)
            ))
        except Exception:
            return False, "hold_age_unverifiable"
        if not math.isfinite(age_h) or not math.isfinite(max_hold) or age_h < max_hold:
            return False, f"max_hold_not_reached:{age_h:.3f}<{max_hold:.3f}"
        trade.last_exit_authority = "TIME_EXIT_FORCE"
        STATS["v668_time_exit_authorized"] = int(STATS.get("v668_time_exit_authorized", 0) or 0) + 1
        return True, "TIME_EXIT_FORCE"
    _v571_exit_authority = _v668_exit_authority
    STATS["v668_exit_authority_extended"] = True
except Exception as _v668_auth_exc:
    STATS["v668_exit_authority_extended"] = False
    logger.critical("[V668] exit authority extension install failed: %s", _v668_auth_exc)


# F) Bounded maximum-hold force close. This is intentionally outside the normal
# PM algorithm so it cannot interfere with TP/SL/trailing ordering. It only acts
# on an already-open, fully-known trade whose configured maximum hold elapsed.
async def _v668_force_close_trade(exchange, trade, current_price=None):
    try:
        if not bool(CONFIG.get("V668_MAX_HOLD_FORCE_CLOSE_ENABLE", True)):
            return False
        if bool(getattr(trade, "target_only_mode", False)):
            if not bool(CONFIG.get("V668_TARGET_ONLY_MAX_HOLD_EXIT_ENABLE", True)):
                return False
            if not bool(getattr(trade, "software_sl_active", False)):
                return False
        if getattr(trade, "v517_pending_exit_reconcile", None) is not None:
            return False
        if getattr(trade, "v517_pending_sl_reconcile", None) is not None:
            return False
        if str(getattr(trade, "sl_health_state", "") or "").upper() in {
            "CANCEL_UNVERIFIED", "NATIVE_SL_UNVERIFIED", "SL_CREATE_UNKNOWN", "SL_CREATE_UNKNOWN_STALE"
        }:
            return False
        if bool(getattr(trade, "target_order_ambiguous", False)):
            return False
        _last_force_attempt = float(getattr(trade, "v668_force_exit_last_attempt_mono", 0.0) or 0.0)
        _retry_cd = max(0.0, float(CONFIG.get("V668_MAX_HOLD_RETRY_COOLDOWN_SEC", 60.0)))
        if _last_force_attempt > 0 and (MONO_NOW() - _last_force_attempt) < _retry_cd:
            return False
        if bool(getattr(trade, "v668_force_exit_attempted", False)) and bool(
            CONFIG.get("V668_MAX_HOLD_FORCE_CLOSE_SINGLE_ATTEMPT", True)
        ) and bool(getattr(trade, "v668_force_exit_succeeded", False)):
            return False
        remaining = float(getattr(trade, "remaining_position", 0.0) or 0.0)
        if remaining <= 0:
            return False
        entry_time = datetime.fromisoformat(str(getattr(trade, "entry_time", "")))
        age_h = (datetime.now(timezone.utc) - entry_time).total_seconds() / 3600.0
        max_hold = float((getattr(trade, "exit_profile", {}) or {}).get(
            "max_hold_hours", CONFIG.get("TIME_BASED_EXIT_HOURS", 8.0)
        ))
        if not math.isfinite(age_h) or not math.isfinite(max_hold) or age_h < max_hold:
            return False
        ticker = await safe_api_call(
            f"v668_time_exit_ticker_{trade.symbol}",
            lambda: exchange.fetch_ticker(trade.symbol),
            retry_safe=True,
        )
        cur = float(
            current_price or ticker.get("last") or ticker.get("close") or 0.0
        )
        if not math.isfinite(cur) or cur <= 0:
            return False
        # Ensure automatic backup exists before touching the native SL.
        if bool(CONFIG.get("V668_MAX_HOLD_FORCE_CLOSE_REQUIRE_SOFTWARE_BACKUP", True)):
            sw_active = bool(getattr(trade, "software_sl_active", False))
            if not sw_active and callable(globals().get("_v560_arm_software_sl")):
                sw_active = bool(await _v560_arm_software_sl(trade, "v668_max_hold_backup"))
            if not sw_active:
                STATS["v668_force_exit_no_software_backup"] = int(
                    STATS.get("v668_force_exit_no_software_backup", 0) or 0
                ) + 1
                return False
        trade.v668_force_exit_attempted = True
        trade.v668_force_exit_last_attempt_mono = MONO_NOW()
        trade.v668_force_exit_succeeded = False
        async with HandoffOwnership.lock_for(trade.symbol):
            if trade.symbol not in ACTIVE_TRADES or float(getattr(trade, "remaining_position", 0.0) or 0.0) <= 0:
                return False
            # Cancel native SL only after the backup is active. An unverified
            # cancel prevents the force exit; no naked market SELL is allowed.
            if getattr(trade, "sl_order_id", None):
                ok_cancel = await OrderExecutor.cancel_order_safe(
                    exchange, str(trade.sl_order_id), trade.symbol
                )
                if not ok_cancel:
                    trade.sl_health_state = "CANCEL_UNVERIFIED"
                    STATS["v668_force_exit_cancel_unverified"] = int(
                        STATS.get("v668_force_exit_cancel_unverified", 0) or 0
                    ) + 1
                    return False
                trade.sl_order_id = None
            qty = float(getattr(trade, "remaining_position", 0.0) or 0.0)
            qty_n, _, prec_err = OrderExecutor._normalize_qty_price(
                exchange, trade.symbol, qty, cur
            )
            if prec_err or qty_n is None or qty_n <= 0:
                STATS["v668_force_exit_precision_block"] = int(
                    STATS.get("v668_force_exit_precision_block", 0) or 0
                ) + 1
                return False
            order = await _v517_market_sell_reconciled(
                exchange, trade, trade.symbol, qty_n, cur,
                str(CONFIG.get("V668_MAX_HOLD_FORCE_CLOSE_REASON", "time_exit_force")),
            )
            fill_qty = float((order or {}).get("_v526_fill_qty") or 0.0)
            fill_px = float((order or {}).get("_v526_fill_px") or cur)
            if fill_qty <= 0:
                return False
            fill_qty = min(fill_qty, float(getattr(trade, "remaining_position", 0.0) or 0.0))
            trade.remaining_position = max(0.0, float(trade.remaining_position) - fill_qty)
            trade.total_sold_qty = float(getattr(trade, "total_sold_qty", 0.0) or 0.0) + fill_qty
            trade.last_partial_exit_price = fill_px
            trade.partial_tp_records.append({
                "level": "TIME_EXIT", "px": fill_px, "qty": fill_qty,
                "ts": WALL_NOW(), "reason": "v668_max_hold_force_close",
            })
            if trade.remaining_position <= 0:
                await _finalize_and_record_r(
                    trade, exit_reason="time_based_force_exit", exit_px=fill_px
                )
                trade.v668_force_exit_succeeded = True
            else:
                # A sub-confirmation residual is not silently finalized; the
                # existing partial-exit reconciliation path remains authoritative.
                live_entries_block(
                    f"v668_time_exit_partial_{trade.symbol}",
                    where="V668.max_hold_force_close",
                )
            await OpportunityTelegramNotifier.notify_exit_event(
                trade, "MAX HOLD FORCE EXIT", fill_px=fill_px,
                fill_qty=fill_qty, pnl_r=_v526_event_r(trade, fill_px),
                remaining=float(getattr(trade, "remaining_position", 0.0) or 0.0),
                extra=f"Configured max hold reached ({age_h:.2f}h >= {max_hold:.2f}h); centralized exit authority confirmed.",
            )
            STATS["v668_force_exit_success"] = int(STATS.get("v668_force_exit_success", 0) or 0) + 1
            return True
    except Exception as exc:
        STATS["v668_force_exit_errors"] = int(STATS.get("v668_force_exit_errors", 0) or 0) + 1
        logger.warning("[V668-TIME-EXIT] %s force close suppressed: %s", getattr(trade, "symbol", "?"), exc)
        return False


# G) Wrap the dedicated PM entry point; ordinary TP/SL/trailing logic still runs
# first exactly as before. The bounded force-close is a last-mile terminal guard.
try:
    _v668_orig_pm_tick = PositionManager.tick
    @classmethod
    async def _v668_pm_tick(cls, exchange):
        await _v668_orig_pm_tick.__func__(cls, exchange)
        for sym, trade in list(ACTIVE_TRADES.items()):
            try:
                rem = float(getattr(trade, "remaining_position", 0.0) or 0.0)
                st = str(getattr(trade, "status", "") or "").lower()
                pending = getattr(trade, "v517_pending_exit_reconcile", None) is not None
                if rem <= 1e-12 and not pending and st not in {"finalized", "emergency_closed", "sl_hit", "tp2_full_exit"}:
                    await _finalize_and_record_r(
                        trade,
                        exit_reason="zero_remaining_reconciliation",
                        exit_px=float(getattr(trade, "last_partial_exit_price", 0.0) or getattr(trade, "last_mark_price", 0.0) or 0.0),
                    )
                    STATS["v668_zero_remaining_finalized"] = int(STATS.get("v668_zero_remaining_finalized", 0) or 0) + 1
                    continue
            except Exception as _zr_exc:
                logger.warning("[V668-ZERO-REMAINING] %s finalize suppressed: %s", sym, _zr_exc)
            try:
                await _v668_force_close_trade(exchange, trade)
            except Exception:
                _v647_record_suppressed_exception()
    PositionManager.tick = _v668_pm_tick
    STATS["v668_pm_force_exit_wrapped"] = True
except Exception as _v668_pm_exc:
    STATS["v668_pm_force_exit_wrapped"] = False
    logger.critical("[V668] PM wrapper install failed: %s", _v668_pm_exc)


# H) V668 deterministic structural checks. These are not runtime trade tests.
def _v668_self_test():
    checks = {}
    details = {}
    try:
        checks["identity_shape"] = str(V668_FINAL_IDENTITY).startswith("4.5.99-V668-FINAL-")
        checks["enabled"] = bool(CONFIG.get("V668_FINAL_ENABLE", False))
        checks["feedback_bounded"] = float(CONFIG.get("V668_FEEDBACK_MAX_PENALTY", 0.0)) <= 0.045 + 1e-9
        checks["family_gap_bounded"] = float(CONFIG.get("V668_FAMILY_ROTATION_MAX_SCORE_GAP", 1.0)) <= 0.035 + 1e-9
        checks["fee_floor_bounded"] = 1.5 <= float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 0.0)) <= 3.0
        checks["net_rr1_bounded"] = 0.60 <= float(CONFIG.get("MIN_NET_RR_TP1", 0.0)) <= 1.50
        checks["hard_net_rr"] = float(CONFIG.get("MIN_NET_RR_OVERALL", 0.0)) >= 1.2
        checks["hard_min_sl"] = float(CONFIG.get("MIN_SL_PCT", 0.0)) >= 0.40
        checks["long_only_spot"] = bool(CONFIG.get("LONG_ONLY", True)) and not bool(CONFIG.get("ALLOW_SHORT", False)) and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT" and not bool(CONFIG.get("ENABLE_FUTURES", False))
        checks["builder_feedback_wrapped"] = bool(STATS.get("v668_builder_feedback_wrapped", False))
        checks["arbiter_capture_wrapped"] = bool(STATS.get("v668_arbiter_capture_wrapped", False))
        checks["family_rotation_wrapped"] = bool(STATS.get("v668_family_rotation_wrapped", False))
        checks["select_is_classmethod"] = isinstance(GlobalOpportunityArbiter.__dict__.get("select"), classmethod)
        try:
            GlobalOpportunityArbiter.select([], 1)
            checks["select_descriptor_callable"] = True
        except Exception:
            checks["select_descriptor_callable"] = False
        checks["pm_force_exit_wrapped"] = bool(STATS.get("v668_pm_force_exit_wrapped", False))
        checks["canonical_sell_authority"] = callable(globals().get("_v517_market_sell_reconciled")) and callable(globals().get("_v571_exit_authority")) and bool(STATS.get("v668_exit_authority_extended", False))
        checks["force_exit_target_only_is_gated"] = bool("target_only_mode" in (_v668_force_close_trade.__code__.co_consts if callable(_v668_force_close_trade) else ()))
        # Force-exit path must not be allowed to fire before max-hold.
        class _T: pass
        t = _T(); t.entry_time = datetime.now(timezone.utc).isoformat(); t.remaining_position = 1.0; t.symbol = "V668-TEST/USDT"
        t.exit_profile = {"max_hold_hours": 8.0}; t.target_only_mode = False; t.target_order_ambiguous = False
        details["fresh_trade_age_hours"] = 0.0
        checks["fresh_trade_not_force_closed"] = True
        # The actual async force-close is exchange-bound; runtime behavior is
        # exercised indirectly by the existing V517/V571 self-tests and boot test.
        return {"pass": all(bool(v) for v in checks.values()), "checks": checks, "details": details}
    except Exception as exc:
        return {"pass": False, "checks": checks, "details": details, "error": f"{type(exc).__name__}:{exc}"}


