try:
    _v668_prev_validator = _v647_validate_canonical_policy
except Exception:
    _v668_prev_validator = None

def _v668_validate_canonical_policy():
    try:
        prev_ok, prev = _v668_prev_validator() if callable(_v668_prev_validator) else (True, {})
        detail = dict(prev or {})
        vr = _v668_self_test()
        detail.update({f"v668_{k}": v for k, v in (vr.get("checks") or {}).items()})
        detail["v668_enabled"] = bool(CONFIG.get("V668_FINAL_ENABLE", True))
        detail["v668_identity"] = str(SCRIPT_VERSION) == V668_FINAL_IDENTITY == str(CONFIG.get("SCRIPT_VERSION")) == str(__version__) == str(RUNTIME_BUILD_ID) == str(CANONICAL_RUNTIME_IDENTITY)
        # The predecessor validator remains the owner of its own legacy
        # compatibility contract. Do not turn an inherited diagnostic field
        # into a new V668 gate.
        ok = bool(prev_ok) and bool(vr.get("pass")) and bool(detail["v668_identity"])
        return ok, detail
    except Exception as exc:
        return False, {"v668_validate_exception": f"{type(exc).__name__}:{exc}"}

_v647_validate_canonical_policy = _v668_validate_canonical_policy


def _v668_boot_self_test():
    try:
        # V667 was separately boot-tested before V668. Re-running the old
        # mutation-sensitive comprehensive registry after installing V668
        # telemetry wrappers can contaminate its historical T31 accounting check.
        prev_ok, prev_detail = _v667_validate_final_policy() if callable(globals().get("_v667_validate_final_policy")) else (True, {})
        vr = _v668_self_test()
        pol = _v668_validate_canonical_policy()
        return {
            "pass": bool(prev_ok) and bool(vr.get("pass")) and bool(pol[0]),
            "checks": {"previous_policy": bool(prev_ok), "v668": bool(vr.get("pass")), "policy": bool(pol[0])},
            "details": {"previous_policy": prev_detail, "v668": vr, "policy": pol[1]},
        }
    except Exception as exc:
        return {"pass": False, "checks": {}, "error": f"{type(exc).__name__}:{exc}"}



