# ---- Canonical rejection/event ledger --------------------------------------
class V669RejectionLedger:
    WINDOW_SEC = 900.0
    MAX_EVENTS = 4096
    _events = deque(maxlen=MAX_EVENTS)

    PRIORITY = ("SYSTEM", "POLICY", "HTF", "LIQUIDITY", "STRUCTURE", "SCORE", "FEE", "PRE_SEND", "EXECUTION", "OTHER")

    @classmethod
    def _bucket(cls, taxonomy: str, code: str, canonical_key: str = "") -> str:
        token = f"{taxonomy}.{code}.{canonical_key}".lower()
        if "exception" in token or "system" in token:
            return "SYSTEM"
        # Family-policy decisions are policy even when historical callers prefix
        # them with `htf.`. This prevents policy starvation from being mislabeled
        # as HTF and sending the recovery classifier toward the wrong bottleneck.
        if ("context_drift" in token or "policy" in token or "family_policy" in token or
            "strategy_policy" in token or "family_regime_disallowed" in token or
            "family_htf_strength_below_floor" in token or "family_tier_below_floor" in token):
            return "POLICY"
        if token.startswith(("policy.", "family_policy.", "strategy_policy.")) or ".policy" in token:
            return "POLICY"
        if token.startswith("htf.") or ".htf" in token:
            return "HTF"
        if token.startswith(("liquidity.", "depth.")) or ".liquidity" in token:
            return "LIQUIDITY"
        # Score rejects can arrive through historical callers using the
        # "structural" taxonomy. Their semantic decision must remain SCORE.
        if ("score_below_threshold" in token or
            "score_below_floor" in token or
            token.startswith(("score.", "rank.", "mse_rank"))):
            return "SCORE"
        if token.startswith(("structure.", "structural.")) or ".structure" in token:
            return "STRUCTURE"
        if token.startswith("fee") or "fee_unviable" in token:
            return "FEE"
        if token.startswith(("pre_send.", "presend.")) or "presend" in token:
            return "PRE_SEND"
        if token.startswith("execution.") or ".execution" in token:
            return "EXECUTION"
        return "OTHER"

    @classmethod
    def note(cls, event: Dict[str, Any]) -> None:
        try:
            event = dict(event or {})
            event.setdefault("timestamp", WALL_NOW())
            event["bucket"] = cls._bucket(str(event.get("taxonomy", "")), str(event.get("code", "")), str(event.get("canonical_key", "")))
            event["cycle_id"] = int(event.get("cycle_id", 0) or 0)
            event["opportunity_id"] = str(event.get("opportunity_id", "") or "")
            event["trace_id"] = str(event.get("trace_id", "") or "")
            cls._events.append(event)
        except Exception:
            return

    @classmethod
    def recent(cls, window_sec: Optional[float] = None) -> list:
        ws = float(window_sec if window_sec is not None else cls.WINDOW_SEC)
        now = WALL_NOW()
        return [e for e in list(cls._events) if (now - float(e.get("timestamp", now) or now)) <= ws]

    @classmethod
    def current_cycle(cls, cycle_id: Optional[int] = None) -> list:
        cid = int(cycle_id if cycle_id is not None else (globals().get("_V517_ACTIVE_CYCLE_ID") or STATS.get("v669_last_cycle_id", 0) or 0))
        return [e for e in list(cls._events) if int(e.get("cycle_id", 0) or 0) == cid] if cid else []

    @classmethod
    def counts(cls, events: list) -> Dict[str, int]:
        out = {k: 0 for k in cls.PRIORITY}
        for e in events:
            b = str(e.get("bucket", "OTHER"))
            out[b] = out.get(b, 0) + 1
        return out


# ---- V669-R4 semantic context canonicalization -----------------------------
# These aliases resolve representation/vocabulary differences without weakening
# bearish/crash semantics. They are used by diagnostics and policy input only.
_V669_SEVERITY_EQUIV = {
    "": "NORMAL",
    "NON_BEARISH": "NORMAL",
}
_V669_LOCAL_EQUIV = {
    "NON_BEARISH": "LOCAL_BULLISH",
}

def _v669_canon_severity(value: Any, macro_regime: Any = "") -> str:
    sev = str(value or "").strip().upper()
    macro = str(macro_regime or "").strip().upper()
    # NON_BEARISH is only a non-crash/non-bearish vocabulary alias. Never
    # canonicalize an explicitly bearish severity or a crash state.
    if macro != "BEARISH":
        return _V669_SEVERITY_EQUIV.get(sev, sev)
    return sev

def _v669_canon_local(value: Any, macro_regime: Any = "") -> str:
    local = str(value or "").strip().upper()
    macro = str(macro_regime or "").strip().upper()
    if macro != "BEARISH":
        return _V669_LOCAL_EQUIV.get(local, local)
    return local


def _v669_context_scalar(value: Any, *, field: str = "") -> Any:
    """Normalize context representation without weakening semantic equality."""
    try:
        if isinstance(value, dict):
            if field in {"market_phase", "phase"}:
                value = value.get("phase", value.get("value", value.get("name", "")))
            elif "value" in value and len(value) <= 3:
                value = value.get("value")
        # Timestamp-like values must be normalized BEFORE generic .value
        # unwrapping; pandas.Timestamp.value is nanoseconds, while the canonical
        # candle identity uses epoch milliseconds.
        if field == "candle_ts":
            if value is None or value == "": return ""
            try:
                if hasattr(value, "to_pydatetime"): value = value.to_pydatetime()
                if isinstance(value, datetime):
                    dt = value if value.tzinfo is not None else value.replace(tzinfo=timezone.utc)
                    return str(int(dt.astimezone(timezone.utc).timestamp()*1000))
            except Exception: pass
            try:
                if isinstance(value,(int,float)) and math.isfinite(float(value)):
                    fv=float(value); return str(int(fv if abs(fv)>=1e11 else fv*1000.0))
            except Exception: pass
            try:
                if pd is not None:
                    dt=pd.to_datetime(value,utc=True,errors="coerce")
                    if dt is not None and not pd.isna(dt): return str(int(dt.value//1_000_000))
            except Exception: pass
            return str(value).strip()
        if hasattr(value, "value") and not isinstance(value, (str, bytes, int, float, bool)):
            try: value = value.value
            except Exception: pass
        if field in {"macro_regime","market_phase","strategy_mode","strategy_style","liquidity_tier","family"}:
            return str(value or "").strip().upper()
        if field == "bearish_severity":
            return _v669_canon_severity(value)
        if field == "local_regime":
            return _v669_canon_local(value)
        if field == "htf_strength":
            try:
                fv=float(value); return round(fv,6) if math.isfinite(fv) else None
            except Exception:
                return None if value is None else str(value)
        return value
    except Exception:
        return value


def _v669_context_from(candidate: Any, snapshot: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    c = candidate or {}
    fs = dict(getattr(c, "features_snapshot", {}) or {}) if not isinstance(c, dict) else dict(c)
    snap = dict(snapshot or {})
    # V669-R4: candidates are generated from an immutable, enriched global
    # snapshot.  The generated candidate can later carry derived fields in
    # different representations (or be mutated by a downstream scorer), so
    # coherence must first consult the exact origin context stamped at MSE
    # generation time.  This is not a relaxation: the origin is accepted only
    # when its deterministic snapshot_id matches the current snapshot_id.
    _origin = dict(fs.get("v669_origin_context") or {}) if isinstance(fs.get("v669_origin_context"), dict) else {}
    _origin_id = str(_origin.get("snapshot_id") or "")
    _snap_id = str(snap.get("snapshot_id") or "")
    _origin_bound = bool(_origin_id and _snap_id and _origin_id == _snap_id)
    _source = _origin if _origin_bound else fs
    def pick(k, default=None):
        if _origin_bound:
            v=_origin.get(k,None)
            if v is None or v == "": v=snap.get(k,default)
            return v
        # Preserve the original V669 candidate-top-level precedence for
        # unbound/legacy candidates; only exact bound provenance changes the
        # source of truth. This avoids creating new drift from feature snapshots
        # that merely use an alternate representation.
        if not isinstance(c, dict):
            try:
                cv=getattr(c,k,None)
                if cv is not None and cv != "": return cv
            except Exception: pass
        v=fs.get(k,None)
        if v is None or v == "": v=snap.get(k,default)
        return v
    candle=pick("candle_ts", pick("closed_candle_ts", None))
    if candle is None or candle == "":
        df5=snap.get("df_5m")
        try:
            if df5 is not None and len(df5)>=2: candle=df5.index[-2]
        except Exception: candle=None
    return {
        "macro_regime":_v669_context_scalar(pick("macro_regime", getattr(c,"macro_regime","")),field="macro_regime"),
        "local_regime":_v669_context_scalar(pick("local_regime", getattr(c,"local_regime","")),field="local_regime"),
        "market_phase":_v669_context_scalar(pick("market_phase", getattr(c,"market_phase","")),field="market_phase"),
        "bearish_severity":_v669_context_scalar(pick("bearish_severity", getattr(c,"bearish_severity","")),field="bearish_severity"),
        "strategy_mode":_v669_context_scalar(pick("strategy_mode", getattr(c,"strategy_mode","")),field="strategy_mode"),
        "strategy_style":_v669_context_scalar(pick("strategy_style", getattr(c,"strategy_style","")),field="strategy_style"),
        "htf_strength":_v669_context_scalar(pick("htf_strength", getattr(c,"htf_strength",None)),field="htf_strength"),
        "liquidity_tier":_v669_context_scalar(pick("tier", pick("liquidity_tier","")),field="liquidity_tier"),
        "candle_ts":_v669_context_scalar(candle,field="candle_ts"),
        "snapshot_id":str((_source.get("snapshot_id") if isinstance(_source,dict) else "") or snap.get("snapshot_id",fs.get("snapshot_id","")) or ""),
        "symbol":str(getattr(c,"symbol",fs.get("symbol","")) or ""),
        "family":_v669_context_scalar(getattr(c,"family",fs.get("family","")),field="family"),
        "origin_context_bound": bool(_origin_bound),
    }


def _v669_context_drift(candidate: Any, snapshot: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    cctx=_v669_context_from(candidate,snapshot or {})
    sctx=_v669_context_from({},snapshot or {})
    # Safety-critical coherence: candle identity/freshness and macro regime.
    # Local/phase/severity/HTF/tier are re-evaluated by the canonical policy and
    # downstream gates, so representation drift there is telemetry, not a
    # second hard gate. This removes duplicate distributed-truth rejection.
    safety_compare=("macro_regime","candle_ts")
    telemetry_compare=("local_regime","market_phase","bearish_severity","htf_strength","liquidity_tier")
    safety_drift={}
    telemetry_drift={}
    for key in safety_compare:
        a,b=cctx.get(key),sctx.get(key)
        if key == "candle_ts":
            if str(a) != str(b): safety_drift[key]={"candidate":a,"snapshot":b}
        elif str(a) != str(b):
            safety_drift[key]={"candidate":a,"snapshot":b}
    for key in telemetry_compare:
        a,b=cctx.get(key),sctx.get(key)
        if key == "bearish_severity":
            a=_v669_canon_severity(a,cctx.get("macro_regime")); b=_v669_canon_severity(b,sctx.get("macro_regime"))
        elif key == "local_regime":
            a=_v669_canon_local(a,cctx.get("macro_regime")); b=_v669_canon_local(b,sctx.get("macro_regime"))
        if key == "htf_strength":
            try:
                if a is not None and b is not None and abs(float(a)-float(b)) <= 1e-6: continue
            except Exception: pass
        if str(a) != str(b): telemetry_drift[key]={"candidate":a,"snapshot":b}
    if cctx.get("snapshot_id") and sctx.get("snapshot_id") and cctx["snapshot_id"] != sctx["snapshot_id"]:
        # Snapshot identity mismatch remains safety-critical: the candidate is
        # no longer proven to belong to the snapshot being prequalified.
        safety_drift["snapshot_id"]={"candidate":cctx["snapshot_id"],"snapshot":sctx["snapshot_id"]}
    all_drift=dict(safety_drift)
    all_drift.update(telemetry_drift)
    return {"drift":all_drift,"safety_drift":safety_drift,"telemetry_drift":telemetry_drift,
            "pass":not safety_drift,"candidate":cctx,"snapshot":sctx}

def _v669_record_reject_event(*, trace_id, symbol, taxonomy, code, stage, score, ctx, canonical_key):
    _ctx = dict(ctx or {})
    _cycle_id = int(_ctx.get("cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or STATS.get("v669_last_cycle_id", 0) or 0)
    _family = str(_ctx.get("family") or _ctx.get("signal_family") or "").upper()
    _mode = str(_ctx.get("strategy_mode") or "").upper()
    _candle = _ctx.get("candle_ts") or _ctx.get("closed_candle_ts") or ""
    _zone = _ctx.get("zone_id") or _ctx.get("zone_ref") or ""
    _oid = str(_ctx.get("opportunity_id") or _v669_opportunity_id(symbol or "", _candle, _family, _mode, _zone))
    _opp = V669OpportunityLedger.note(_oid, symbol=str(symbol or ""), cycle_id=_cycle_id, evaluation=False)
    event = {
        "event_id": uuid.uuid4().hex[:16],
        "trace_id": str(trace_id or ""),
        "cycle_id": _cycle_id,
        "opportunity_id": _oid,
        "duplicate_evaluation": bool(_opp.get("duplicate", False)),
        "symbol": str(symbol or ""),
        "family": str(_ctx.get("family") or _ctx.get("signal_family") or "").upper(),
        "strategy_mode": str(_ctx.get("strategy_mode") or "").upper(),
        "stage": str(stage or ""),
        "reason_code": str(code or ""),
        "reason_detail": str(_ctx.get("reason_detail") or _ctx.get("detail") or "")[:400],
        "taxonomy": str(taxonomy or ""),
        "canonical_key": str(canonical_key or ""),
        "score": score,
        "engine_score": _ctx.get("engine_score"),
        "macro_regime": _ctx.get("macro_regime") or _ctx.get("regime"),
        "local_regime": _ctx.get("local_regime"),
        "phase": _ctx.get("market_phase") or _ctx.get("phase"),
        "htf_strength": _ctx.get("htf_strength"),
        "liquidity_tier": _ctx.get("liquidity_tier") or _ctx.get("tier"),
        "entry": _ctx.get("entry"), "sl": _ctx.get("sl"),
        "tp1": _ctx.get("tp1"), "tp2": _ctx.get("tp2"), "fee_detail": _ctx.get("fee_detail"),
        "candle_ts": _ctx.get("candle_ts"),
        "exception_type": _ctx.get("exception_type"),
        "exception_message": str(_ctx.get("exception_message") or "")[:240],
    }
    V669RejectionLedger.note(event)
    try:
        b = str(event.get("bucket"))
        STATS[f"v669_reject_bucket_{b.lower()}"] = int(STATS.get(f"v669_reject_bucket_{b.lower()}", 0) or 0) + 1
    except Exception:
        pass

# ---- Opportunity deduplication ---------------------------------------------
def _v669_opportunity_id(symbol: str, candle_ts: Any, family: str, strategy_mode: str, zone_id: Any = "") -> str:
    # Canonicalize the candle domain exactly as the context gate does. This
    # prevents pandas ns / epoch-ms / ISO representations from creating
    # duplicate evaluation identities for the same closed candle.
    candle_key = _v669_context_scalar(candle_ts, field="candle_ts")
    zone_key = str(zone_id or "").strip().upper()
    raw = "|".join((str(symbol or "").strip().upper(), str(candle_key or ""),
                    str(family or "").upper(), str(strategy_mode or "").upper(), zone_key))
    return hashlib.sha256(raw.encode("utf-8", "replace")).hexdigest()[:24]


class V669OpportunityLedger:
    seen = OrderedDict()
    MAX = 4096
    TTL_SEC = 900.0

    @classmethod
    def note(cls, opportunity_id: str, *, symbol: str, cycle_id: int, evaluation: bool = True):
        try:
            oid = str(opportunity_id or "")
            if not oid:
                return {"unique": False, "duplicate": False}
            now = WALL_NOW()
            # Expire old opportunities so a symbol/candle key cannot become
            # a false duplicate merely because the process stayed alive.
            _expired = []
            for _k, _v in list(cls.seen.items()):
                if now - float((_v or {}).get("first_ts", now) or now) > cls.TTL_SEC:
                    _expired.append(_k)
            for _k in _expired:
                cls.seen.pop(_k, None)
            rec = cls.seen.get(oid)
            if rec is None:
                rec = {"symbol": symbol, "first_ts": WALL_NOW(), "evaluations": 0, "cycle_ids": []}
                cls.seen[oid] = rec
                unique = True
            else:
                unique = False
            if evaluation:
                rec["evaluations"] = int(rec.get("evaluations", 0)) + 1
            if cycle_id and cycle_id not in rec["cycle_ids"]:
                rec["cycle_ids"].append(int(cycle_id))
                rec["cycle_ids"] = rec["cycle_ids"][-8:]
            while len(cls.seen) > cls.MAX:
                cls.seen.popitem(last=False)
            STATS["v669_unique_opportunities"] = len(cls.seen)
            STATS["v669_duplicate_evaluations"] = sum(max(0, int(v.get("evaluations",0))-1) for v in cls.seen.values())
            return {"unique": unique, "duplicate": not unique, **dict(rec)}
        except Exception:
            return {"unique": False, "duplicate": False}

# ---- Family funnel / current-cycle ledger ----------------------------------
class V669CycleLedger:
    _cycles = OrderedDict()
    MAX_CYCLES = 32

    @classmethod
    def begin(cls, cycle_id: int):
        try:
            cid = int(cycle_id)
            cls._cycles[cid] = {"cycle_id": cid, "started": WALL_NOW(), "finished": False,
                                "generated": 0, "hard_valid": 0, "prequal_pass": 0, "ranked": 0,
                                "selected": 0, "builder_pass": 0, "presend_pass": 0, "queued": 0,
                                "sent": 0, "terminal_rejects": 0, "rejects": defaultdict(int),
                                "families": defaultdict(lambda: defaultdict(int)), "mse": defaultdict(int)}
            STATS["v669_current_cycle_id"] = cid
            while len(cls._cycles) > cls.MAX_CYCLES:
                cls._cycles.popitem(last=False)
        except Exception:
            pass

    @classmethod
    def _family_name(cls, fam: str) -> str:
        return str(fam or "UNKNOWN").upper()

    @classmethod
    def note_family(cls, cycle_id: int, family: str, stage: str, value: int = 1):
        try:
            row = cls._cycles.setdefault(int(cycle_id), {"cycle_id": int(cycle_id), "families": defaultdict(lambda: defaultdict(int))})
            fam = cls._family_name(family)
            row.setdefault("families", defaultdict(lambda: defaultdict(int)))[fam][str(stage)] += int(value)
        except Exception:
            pass

    @classmethod
    def note_reject(cls, cycle_id: int, family: str, bucket: str):
        try:
            row = cls._cycles.setdefault(int(cycle_id), {"cycle_id": int(cycle_id), "rejects": defaultdict(int)})
            row.setdefault("rejects", defaultdict(int))[str(bucket)] += 1
            row["terminal_rejects"] = int(row.get("terminal_rejects",0)) + 1
            cls.note_family(cycle_id, family, f"reject_{bucket}", 1)
        except Exception:
            pass

    @classmethod
    def finish(cls, cycle_id: int, market_data_map: Dict[str, Any]):
        try:
            cid = int(cycle_id)
            row = cls._cycles.setdefault(cid, {"cycle_id": cid, "started": WALL_NOW(), "families": defaultdict(lambda: defaultdict(int)), "rejects": defaultdict(int)})
            row["finished"] = True
            row["finished_ts"] = WALL_NOW()
            row["age_sec"] = max(0.0, float(row["finished_ts"] - row.get("started", row["finished_ts"])))
            # Use existing authoritative global funnel counters for the exact cycle snapshot.
            row.update({
                "generated": int(STATS.get("v45_global_generated", 0) or 0),
                "hard_valid": int(STATS.get("v45_global_hard_valid", 0) or 0),
                "ranked": int(STATS.get("v45_global_ranked", 0) or 0),
                "raw_ranked": int(STATS.get("v681_runtime_cycle_raw_ranked", STATS.get("v45_global_ranked", 0)) or 0),
                "pool_ranked": int(STATS.get("v681_runtime_cycle_ranked", STATS.get("v45_global_ranked", 0)) or 0),
                "selected": int(STATS.get("v45_global_winners", 0) or 0),
                "queued": int(STATS.get("signals_queued", 0) or 0),
                "sent": int(STATS.get("signals_sent", 0) or 0),
                "prequal_pass": int(STATS.get("v45_global_prequalified", 0) or 0),
                "builder_pass": int(STATS.get("v534_live_ready", 0) or 0),
                "presend_pass": int(STATS.get("v534_live_ready", 0) or 0),
                "mse_rank_rejected": int(STATS.get("v45_global_rank_rejected", 0) or 0),
                "fee_rejected": int(STATS.get("fee_unviable_count", 0) or 0),
            })
            # Preserve per-family generated evidence from the canonical MSE run.
            try:
                for _fam, _n in list(STATS.get("v45_global_generated_by_mode_top", []) or []):
                    cls.note_family(cid, str(_fam), "generated", int(_n))
                # Enrich with the already-existing cycle-scoped V456 family coverage
                # (no new exchange reads). This avoids rebuilding family logic here.
                _v456_snap = globals().get("_V456FamilyCoverage")
                if _v456_snap is not None and hasattr(_v456_snap, "snapshot"):
                    _cover = _v456_snap.snapshot(float(CONFIG.get("V456_FUNNEL_WINDOW_SEC", 720.0)))
                    for _fam, _rec in (_cover or {}).items():
                        for _stage in ("gen","htf_pass","pre_pass","pre_rej","ranked","selected","queued","sent"):
                            _val = int((_rec or {}).get(_stage, 0) or 0)
                            if _val:
                                cls.note_family(cid, str(_fam), _stage, _val)
                row["families"] = {k: dict(v) for k, v in row.get("families", {}).items()}
            except Exception:
                _v647_record_suppressed_exception()
            STATS["v669_last_cycle_snapshot"] = dict(row)
            STATS["v669_current_cycle_root"] = cls.current_root(cid)
            STATS["v669_current_cycle_age"] = row["age_sec"]
            STATS["v669_family_funnel"] = {k: dict(v) for k, v in row.get("families", {}).items()}
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def sync_execution(cls, cycle_id: int) -> None:
        """Finalize current-cycle execution funnel only after canonical routing runs.

        `finish()` is intentionally called immediately after the Brain phase, before
        SignalBuilder/PreSend/execution.  Those later stages therefore MUST be
        synchronized separately; otherwise the V669 heartbeat can report zeros for
        builder/presend/queue/send even though the same cycle subsequently executed.
        """
        try:
            cid=int(cycle_id)
            row=cls._cycles.get(cid)
            if not row:
                return
            row["builder_pass"] = int(STATS.get("v547_cycle_live_ready_delta", 0) or 0)
            # There is no independent canonical public counter for PreSend-pass;
            # use the explicit pre-send candidate pass counter when available and
            # never infer a pass from queue/send.
            row["presend_pass"] = int(STATS.get("v547_cycle_presend_pass", STATS.get("v644_preexec_canonical_pass", 0)) or 0)
            row["queued"] = int(STATS.get("v547_cycle_queued_delta", 0) or 0)
            row["sent"] = int(STATS.get("v547_cycle_sent_delta", 0) or 0)
            row["execution_attempts"] = int(STATS.get("v535_cycle_execution_attempts", 0) or 0)
            row["live_ready"] = int(STATS.get("v545_cycle_live_ready", 0) or 0)
            row["terminal_rejects"] = max(
                int(row.get("terminal_rejects", 0) or 0),
                sum(1 for e in V669RejectionLedger.current_cycle(cid)
                    if str((e or {}).get("category") or "").upper() in {"SYSTEM","POLICY","HTF","LIQUIDITY","STRUCTURE","SCORE","FEE","PRE_SEND","EXECUTION","OTHER"})
            )
            row["finished_execution_ts"] = WALL_NOW()
            row["execution_age_sec"] = max(0.0, row["finished_execution_ts"] - row.get("started", row["finished_execution_ts"]))
            cls._cycles[cid]=row
            STATS["v669_last_cycle_snapshot"] = dict(row)
            STATS["v669_current_cycle_root"] = cls.current_root(cid)
            STATS["v669_current_cycle_age"] = float(row.get("execution_age_sec", row.get("age_sec", 0.0)) or 0.0)
        except Exception:
            _v647_record_suppressed_exception()

    @classmethod
    def current_root(cls, cycle_id: Optional[int] = None) -> str:
        events = V669RejectionLedger.current_cycle(cycle_id)
        counts = V669RejectionLedger.counts(events)
        for b in V669RejectionLedger.PRIORITY:
            if counts.get(b, 0) > 0:
                return b
        return "NONE"

    @classmethod
    def snapshot(cls, cycle_id: Optional[int] = None) -> Dict[str, Any]:
        cid = int(cycle_id if cycle_id is not None else (STATS.get("v669_last_cycle_id",0) or 0))
        row = dict(cls._cycles.get(cid, {}) or {})
        counts = V669RejectionLedger.counts(V669RejectionLedger.current_cycle(cid))
        row["root"] = cls.current_root(cid)
        row["reject_buckets"] = counts
        row["cycle_id"] = cid
        return row

# ---- Snapshot sanitation ---------------------------------------------------
def _v669_validate_market_snapshot(snapshot: Optional[Dict[str, Any]], *, purpose: str = "prequal") -> Tuple[bool, str, Dict[str, Any]]:
    snap = dict(snapshot or {})
    if not snap:
        return False, "data.snapshot_missing", {"purpose": purpose}
    df_specs = (\
        ("df_5m", 52, True, ("open","high","low","close","volume")),\
        ("df_15m", 30, True, ("open","high","low","close","volume")),\
        ("df_1h", 30, True, ("open","high","low","close","volume")),\
        ("df_4h", 30, True, ("open","high","low","close","volume")),\
    )
    checked = {}
    for name, minimum, required, cols in df_specs:
        df = snap.get(name)
        if df is None:
            if required:
                return False, f"data.missing_dataframe.{name}", {"checked": checked}
            continue
        try:
            if not hasattr(df, "columns") or len(df) < minimum:
                return False, f"data.insufficient_bars.{name}.need_{minimum}", {"checked": checked, "len": int(len(df))}
            missing = [c for c in cols if c not in df.columns]
            if missing:
                return False, f"data.missing_column.{name}:{','.join(missing)}", {"checked": checked}
            for c in cols:
                vals = df[c].iloc[-minimum:]
                try:
                    arr = vals.astype(float)
                except Exception:
                    return False, f"data.invalid_numeric.{name}.{c}", {"checked": checked}
                if not bool(arr.map(math.isfinite).all()):
                    return False, f"data.invalid_numeric.{name}.{c}", {"checked": checked}
            # Closed bar must exist; live candle is index -1 and may be partially formed.
            for c in ("open","high","low","close","volume"):
                float(df[c].iloc[-2])
            checked[name] = int(len(df))
        except (IndexError, KeyError, ValueError, TypeError):
            return False, f"data.closed_bar_unavailable.{name}", {"checked": checked}
        except Exception as exc:
            return False, f"data.snapshot_exception.{name}.{type(exc).__name__}", {"checked": checked}
    # Snapshot-level facts used by the canonical policy must be finite when present.
    for k in ("quote_vol_24h", "spread_pct", "htf_strength", "depth_ratio"):
        if k in snap and snap.get(k) is not None:
            try:
                v = float(snap[k])
                if not math.isfinite(v):
                    return False, f"data.invalid_numeric.snapshot.{k}", {"checked": checked}
            except Exception:
                return False, f"data.invalid_numeric.snapshot.{k}", {"checked": checked}
    # Canonical closed-candle identity: prefer the actual closed 5m dataframe index
    # over a copied snapshot metadata field. A malformed copied timestamp must not
    # invalidate an otherwise valid immutable snapshot when the source dataframe
    # proves the closed candle. Conversely, an invalid dataframe timestamp remains
    # fail-closed.
    if bool(CONFIG.get("V669_TIMESTAMP_CANONICALIZATION_ENABLE", True)):
        try:
            _df5 = snap.get("df_5m")
            _derived = None
            if _df5 is not None and len(_df5) >= 2:
                _raw_closed = _df5.index[-2]
                _derived = _v669_context_scalar(_raw_closed, field="candle_ts")
                try:
                    if isinstance(_raw_closed, (int, float)) and not isinstance(_raw_closed, bool):
                        _derived_num = float(_derived)
                        if not math.isfinite(_derived_num) or _derived_num <= 0:
                            return False, "data.candle_timestamp_invalid", {"checked": checked}
                    elif pd is not None:
                        _parsed_closed = pd.to_datetime(_raw_closed, utc=True, errors="coerce")
                        if pd.isna(_parsed_closed):
                            return False, "data.candle_timestamp_invalid", {"checked": checked}
                    elif not str(_derived or "").strip():
                        return False, "data.candle_timestamp_invalid", {"checked": checked}
                except Exception:
                    return False, "data.candle_timestamp_invalid", {"checked": checked}
            else:
                _derived = None
            _supplied = snap.get("candle_ts") or snap.get("closed_candle_ts")
            if _derived is None:
                if _supplied not in (None, ""):
                    _canon = _v669_context_scalar(_supplied, field="candle_ts")
                    try:
                        _n = float(_canon)
                        if not math.isfinite(_n) or _n <= 0:
                            return False, "data.candle_timestamp_invalid", {"checked": checked}
                    except Exception:
                        if not str(_canon or "").strip():
                            return False, "data.candle_timestamp_invalid", {"checked": checked}
                else:
                    return False, "data.candle_timestamp_invalid", {"checked": checked}
        except Exception:
            return False, "data.candle_timestamp_invalid", {"checked": checked}
    return True, "ok", {"checked": checked}

# ---- Canonical PULLBACK quality --------------------------------------------
def _v669_confirm_q(confirmations: int, total: int = 4) -> float:
    n = max(0, min(int(confirmations or 0), int(total or 4)))
    return float(n) / float(max(1, int(total or 4))) * 100.0


def _v669_rs_quality(rs: Optional[float]) -> Tuple[Optional[float], str]:
    if rs is None:
        return None, "UNKNOWN"
    try:
        x = float(rs)
        if not math.isfinite(x):
            return None, "UNKNOWN"
        # Discrimination only; the hard minimum remains V587_PULLBACK_MIN_RS.
        if x < -0.01:
            return 0.0, "DANGER"
        if x <= 0.01:
            return 20.0 + max(0.0, (x + 0.01) / 0.02) * 20.0, "NEUTRAL"
        if x <= 0.04:
            return 40.0 + (x / 0.04) * 35.0, "GOOD"
        return min(100.0, 75.0 + ((x - 0.04) / 0.04) * 25.0), "STRONG"
    except Exception:
        return None, "UNKNOWN"


def _v669_pullback_quality(candidate: Any, market_data: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    try:
        md = dict(market_data or {})
        c = candidate
        fs = dict(getattr(c, "features_snapshot", {}) or {})
        fam = str(getattr(c, "family", fs.get("family", "")) or "").upper()
        if fam not in {"PULLBACK", "MTF_PULLBACK"}:
            return {"ok": True, "quality": 100.0, "reason": "not_pullback", "confirmations": 0}
        snapshot_ok, snapshot_reason, _ = _v669_validate_market_snapshot(md, purpose="pullback_quality")
        if not snapshot_ok:
            return {"ok": False, "quality": 0.0, "reason": snapshot_reason, "data_contract": "MANDATORY_CLOSED_DATA"}
        df5 = md.get("df_5m")
        idx = -2
        # Derivable confirmation set: reclaim / higher_low / EMA20 slope / bullish close.
        try:
            close = df5["close"].astype(float)
            low = df5["low"].astype(float)
            ema20 = close.ewm(span=20, adjust=False).mean()
            reclaim = float(close.iloc[idx]) > float(fs.get("zone_ref") or getattr(c, "zone_ref", close.iloc[idx]))
            higher_low = float(low.iloc[idx]) > float(low.iloc[idx-1])
            ema_slope = float(ema20.iloc[idx]) > float(ema20.iloc[idx-1])
            bullish_close = float(close.iloc[idx]) > float(df5["open"].iloc[idx])
        except Exception as exc:
            return {"ok": False, "quality": 0.0, "reason": f"data.invalid_confirmation.{type(exc).__name__}"}
        _coh_pb = globals().get("canonical_pullback_confirmations")
        _coh_pb_facts = {
            "reclaim": reclaim, "zone_reclaim": reclaim,
            "higher_low": higher_low,
            "bullish_close": bullish_close,
            "ema_slope": ema_slope, "ema20_slope_up": ema_slope,
            "shallow_pullback": bool(fs.get("shallow_pullback", False)),
            "bos": bool(fs.get("bos_confirmed", fs.get("bos", False))),
        }
        if callable(_coh_pb):
            _coh_q = _coh_pb(_coh_pb_facts)
            STATS["coherence_pullback_quorum_used"] = int(STATS.get("coherence_pullback_quorum_used",0) or 0) + 1
            confirmations = int(_coh_q.get("primary_count", 0) or 0)
            canonical_confirmed = bool(_coh_q.get("confirmed", False))
        else:
            confirmations = int(bool(reclaim)) + int(bool(higher_low)) + int(bool(ema_slope)) + int(bool(bullish_close))
            canonical_confirmed = confirmations >= 2
        confirm_q = _v669_confirm_q(confirmations, 4)
        # Use existing canonical retest recomputation helper when available.
        # CANONICAL SIGNATURE (coherence closure): _v657_recompute_retest_quality(candidate, prepared_snapshot)
        # No caller may pass (df5, zone) as separate positional args. A signature/arity
        # mismatch in this path is a programming error: explicit diagnostic + fail-closed,
        # never a swallowed "except: pass".
        retest = fs.get("retest_score", fs.get("retest", None))
        recompute = globals().get("_v657_recompute_retest_quality")
        if callable(recompute):
            try:
                rv = recompute(c, md)
            except TypeError as exc:
                STATS["retest_signature_mismatch_failclosed"] = int(STATS.get("retest_signature_mismatch_failclosed", 0) or 0) + 1
                return {"ok": False, "quality": 0.0, "reason": f"programming.signature_mismatch.retest_recompute:{type(exc).__name__}", "confirmations": confirmations, "fail_closed": True}
            except Exception as exc:
                STATS["v657_retest_recompute_errors"] = int(STATS.get("v657_retest_recompute_errors", 0) or 0) + 1
                rv = None
            if isinstance(rv, dict):
                retest = rv.get("retest_quality_score", rv.get("retest_quality", retest))
            elif rv is not None:
                retest = rv
        _pb_facts = _v702_pullback_precision_facts(c, md)
        vol = _pb_facts.get("volume_ratio")
        rs = _pb_facts.get("rs_5m")
        htf = _pb_facts.get("htf_strength", getattr(c, "htf_strength", None))
        structure = _pb_facts.get("structure")
        chase = _pb_facts.get("chase_atr")
        retest = _pb_facts.get("retest", retest)
        mandatory = {"htf_strength": htf, "structure": structure, "retest": retest, "chase": chase}
        missing = [k for k,v in mandatory.items() if v is None]
        # Volume/RS are DERIVABLE inputs. If derivation is impossible, reject rather than pass unknown.
        if vol is None:
            try:
                vol_now = float(df5["volume"].iloc[-2])
                vol_base = float(df5["volume"].iloc[-22:-2].mean())
                vol = vol_now / max(vol_base, 1e-12)
            except Exception:
                missing.append("volume_ratio")
        if rs is None:
            missing.append("rs_5m")
        _coh_struct = globals().get("canonical_structure_verdict")
        _coh_struct_verdict = None
        if callable(_coh_struct):
            _sv_facts = dict(_coh_pb_facts)
            _sv_facts.update({
                "closed_candle_ts": md.get("closed_candle_ts") or md.get("candle_ts") or getattr(df5.index[-2], "timestamp", lambda: None)() if len(df5.index) >= 2 else None,
                "zone_ref": fs.get("zone_ref", getattr(c, "zone_ref", None)),
                "chase_atr": chase,
                "family": fam,
            })
            _coh_struct_verdict = _coh_struct(c, _sv_facts)
            STATS["coherence_structure_verdict_used"] = int(STATS.get("coherence_structure_verdict_used", 0) or 0) + 1
        if missing:
            return {"ok": False, "quality": 0.0, "reason": "data.missing_required_metrics:" + ",".join(missing), "confirmations": confirmations, "canonical_structure_verdict": _coh_struct_verdict}
        try:
            vals = {k: float(v) for k,v in {"htf":htf,"structure":structure,"retest":retest,"vol":vol,"rs":rs,"chase":chase}.items()}
            if not all(math.isfinite(v) for v in vals.values()):
                return {"ok": False, "quality": 0.0, "reason": "data.invalid_numeric.pullback_metrics", "confirmations": confirmations}
        except Exception:
            return {"ok": False, "quality": 0.0, "reason": "data.invalid_numeric.pullback_metrics", "confirmations": confirmations}
        rs_q, rs_state = _v669_rs_quality(vals["rs"])
        if rs_q is None:
            return {"ok": False, "quality": 0.0, "reason": "data.invalid_rs", "confirmations": confirmations}
        chase_hard = float(CONFIG.get("V669_CHASE_HARD_ATR", CONFIG.get("V587_PULLBACK_MAX_FINAL_CHASE_ATR",1.10)))
        chase_soft = float(CONFIG.get("V669_CHASE_SOFT_ATR",0.60))
        chase_jit = float(CONFIG.get("V669_CHASE_JIT_ATR",0.90))
        chase_abs = abs(vals["chase"])
        if chase_abs > chase_hard + 1e-9:
            return {"ok": False, "quality": 0.0, "reason": f"chase_hard:{chase_abs:.3f}>{chase_hard:.3f}", "confirmations": confirmations}
        # Equal weights are intentional: no undocumented weighted regression claim.
        vol_q = max(0.0, min(100.0, (vals["vol"] / max(float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO",0.70)),1e-9)) * 70.0))
        htf_q = max(0.0, min(100.0, vals["htf"]))
        structure_q = max(0.0, min(100.0, vals["structure"]))
        retest_q = max(0.0, min(100.0, vals["retest"]))
        chase_q = 100.0 if chase_abs <= chase_soft else (70.0 if chase_abs <= chase_jit else max(0.0, 100.0 - (chase_abs / max(chase_hard,1e-9))*100.0))
        quality = (0.20*htf_q + 0.20*retest_q + 0.20*structure_q + 0.20*confirm_q + 0.10*vol_q + 0.05*rs_q + 0.05*chase_q)
        q_floor = float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY",66.0))
        _reg = str(md.get("macro_regime", md.get("regime", fs.get("macro_regime", ""))) or "").upper()
        _loc = str(md.get("local_regime", fs.get("local_regime", "")) or "").upper()
        _base_htf_floor = float(CONFIG.get("V587_PULLBACK_MIN_HTF",50.0))
        htf_floor = _v702_effective_htf_floor(fam, str(getattr(c, "strategy_mode", "") or fam), _reg, _loc, _base_htf_floor, fs)
        vol_floor = float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO",0.70))
        rs_floor = float(CONFIG.get("V587_PULLBACK_MIN_RS",-0.01))
        retest_floor = float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE",40.0))
        # Existing hard contract: same floors, one precision authority.
        if htf_floor is not None and vals["htf"] < float(htf_floor):
            return {"ok":False,"quality":quality,"reason":"htf_below_floor", "confirmations":confirmations, "confirm_q":confirm_q,
                    "htf_policy": _v702_htf_policy_name(fam, str(getattr(c, "strategy_mode", "") or fam), fs),
                    "htf_floor": float(htf_floor)}
        if vals["vol"] < vol_floor:
            return {"ok":False,"quality":quality,"reason":"volume_below_floor", "confirmations":confirmations, "confirm_q":confirm_q}
        if vals["rs"] < rs_floor:
            return {"ok":False,"quality":quality,"reason":"rs_below_floor", "rs_state":rs_state, "confirmations":confirmations, "confirm_q":confirm_q}
        if vals["retest"] < retest_floor:
            return {"ok":False,"quality":quality,"reason":"retest_below_floor", "confirmations":confirmations, "confirm_q":confirm_q}
        if quality < q_floor:
            return {"ok":False,"quality":quality,"reason":"setup_quality_below_floor", "confirmations":confirmations, "confirm_q":confirm_q}
        return {"ok":True,"quality":quality,"reason":"ok","confirmations":confirmations,"confirm_q":confirm_q,
                "canonical_confirmed": bool(canonical_confirmed),
                "canonical_structure_verdict": _coh_struct_verdict,
                "volume_ratio":vals["vol"],"rs_5m":vals["rs"],"rs_state":rs_state,"htf_strength":vals["htf"],
                "structure":vals["structure"],"retest":vals["retest"],"chase":chase_abs,
                "chase_atr": {"soft_limit":chase_soft,"hard_limit":chase_hard,"jit_limit":chase_jit,"result":"pass","source":"V669_CANONICAL"}}
    except Exception as exc:
        return {"ok":False,"quality":0.0,"reason":f"exception:{type(exc).__name__}","exception_type":type(exc).__name__}

# V587 is the single hard precision authority for PULLBACK. Repoint the runtime
# directly to the deterministic implementation above; no advisory wrapper chain.
_v587_pullback_quality = _v669_pullback_quality


# =============================================================================
# V702.1 FINAL — CONTROLLED PULLBACK ELITE RECOVERY / RISK-FIRST RECALL
# -----------------------------------------------------------------------------
# Purpose:
#   Preserve the canonical PULLBACK/MTF hard contract while recovering only a
#   very small class of exceptional closed-bar setups whose single soft metric
#   is slightly below the normal floor (volume OR short-horizon RS).
#
# Non-negotiables:
#   * The published V669/V587 hard floors remain unchanged.
#   * Setup-quality floor, HTF/structure/retest/chase floors are NOT relaxed.
#   * Missing/unknown data never passes.
#   * Structural fake-break / genuine bearish displacement remains hard.
#   * Recovery requires independent closed-bar evidence and a single weak field.
#   * The recovery is snapshot-only; no new market-data fetch is introduced.
#   * The recovered candidate is re-evaluated by the ORIGINAL V669 contract.
#   * Final SignalBuilder / PreSend / balance / liquidity / fee / SL / execution
#     authorities remain unchanged.
#   * Recovered setups carry a reduced sizing risk factor (0.65) through the
#     existing candidate feature bridge when that bridge is consumed downstream.
#   * A bounded per-cycle recovery-attempt cap prevents a recall lane from
#     becoming a throughput sink.
#
# This is deliberately narrower than V660/V671 recovery and is not a global
# quality relaxation. It exists to recover only an elite one-variable miss.
# =============================================================================

CONFIG.update({
    "V702_PB_ELITE_RECOVERY_ENABLE": True,
    "V702_PB_ELITE_RECOVERY_MAX_ATTEMPTS_PER_CYCLE": 4,
    "V702_PB_ELITE_MIN_ENGINE_SCORE": 98.0,
    "V702_PB_ELITE_MIN_HTF": 75.0,
    "V702_PB_ELITE_MIN_STRUCTURE": 65.0,
    "V702_PB_ELITE_MIN_RETEST": 65.0,
    "V702_PB_ELITE_MAX_CHASE_ATR": 0.55,
    "V702_PB_ELITE_MIN_ANCHORS": 4,
    "V702_PB_ELITE_MIN_COUNTER_ANCHORS": 3,
    "V702_PB_ELITE_VOLUME_MIN": 0.75,
    "V702_PB_ELITE_VOLUME_MEDIAN3_MIN": 0.85,
    "V702_PB_ELITE_VOLUME_TRIGGER_MIN": 1.10,
    "V702_PB_ELITE_VOLUME_SOFT_RATIO": 0.75,
    "V702_PB_ELITE_VOLUME_MIN_SOFT_BARS": 2,
    "V702_PB_ELITE_RS_MIN": -0.0025,
    "V702_PB_ELITE_RS_MEDIAN_MIN": -0.00010,
    "V702_PB_ELITE_RS_R6_R12_MIN": -0.0010,
    "V702_PB_ELITE_RS_SHORT_MIN": 0.0,
    "V702_PB_ELITE_RS_IMPROVEMENT_MIN": 0.00030,
    "V702_PB_ELITE_RECOVERY_RISK_FACTOR": 0.65,
    "V702_PB_ELITE_PREVIEW_DEFER_ENABLE": True,
})

_V702_CANONICAL_PB_HARD_QUALITY = _v669_pullback_quality


def _v702_pb_elite_num(value):
    try:
        x = float(value)
        return x if math.isfinite(x) else None
    except Exception:
        return None


def _v702_pb_elite_score100(candidate):
    x = _v702_pb_elite_num(getattr(candidate, "engine_score", None))
    if x is None:
        try:
            x = _v702_pb_elite_num((getattr(candidate, "features_snapshot", {}) or {}).get("engine_score"))
        except Exception:
            x = None
    if x is None:
        return None
    return x * 100.0 if x <= 1.0 else x


def _v702_pb_elite_cycle_id(snapshot=None):
    try:
        return int(_v702_current_cycle_id(snapshot) or 0)
    except Exception:
        return 0


def _v702_pb_elite_attempt_allowed(snapshot=None):
    try:
        if not bool(CONFIG.get("V702_PB_ELITE_RECOVERY_ENABLE", True)):
            return False
        cid = _v702_pb_elite_cycle_id(snapshot)
        if cid <= 0:
            return True  # no verifiable cycle -> do not introduce a false reject
        last = int(STATS.get("v702_pb_elite_cycle_id", 0) or 0)
        if last != cid:
            STATS["v702_pb_elite_cycle_id"] = cid
            STATS["v702_pb_elite_attempts_cycle"] = 0
        attempts = int(STATS.get("v702_pb_elite_attempts_cycle", 0) or 0)
        return attempts < int(CONFIG.get("V702_PB_ELITE_RECOVERY_MAX_ATTEMPTS_PER_CYCLE", 4))
    except Exception:
        return False


def _v702_pb_elite_mark_attempt(snapshot=None):
    try:
        cid = _v702_pb_elite_cycle_id(snapshot)
        if cid > 0:
            last = int(STATS.get("v702_pb_elite_cycle_id", 0) or 0)
            if last != cid:
                STATS["v702_pb_elite_cycle_id"] = cid
                STATS["v702_pb_elite_attempts_cycle"] = 0
            STATS["v702_pb_elite_attempts_cycle"] = int(STATS.get("v702_pb_elite_attempts_cycle", 0) or 0) + 1
    except Exception:
        _v647_record_suppressed_exception()


def _v702_pb_elite_candidate_snapshot(candidate):
    try:
        return dict(getattr(candidate, "features_snapshot", {}) or {})
    except Exception:
        return {}


def _v702_pb_elite_regime_safe(fs):
    try:
        sm = str(fs.get("strategy_mode", "") or "").upper()
        if sm == "BEARISH_RECOVERY":
            return False
        macro = str(fs.get("macro_regime", fs.get("regime", "")) or "").upper()
        local = str(fs.get("local_regime", "") or "").upper()
        severity = str(fs.get("bearish_severity", fs.get("macro_severity", "")) or "").upper()
        if macro == "BEARISH" or "CRASH" in severity or "EXTREME" in severity:
            return False
        if "BEARISH" in local and local not in {"NON_BEARISH", "LOCAL_BULLISH"}:
            return False
        return True
    except Exception:
        return False


def _v702_pb_elite_preflight(candidate, base_quality=None, *, snapshot=None, require_closed=False):
    """Return bounded eligibility metadata for the one-variable elite lane."""
    try:
        c = getattr(candidate, "candidate", candidate)
        fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
        if fam not in {"PULLBACK", "MTF_PULLBACK"}:
            return False, {"reason": "family_not_allowed"}
        fs = _v702_pb_elite_candidate_snapshot(c)
        if not _v702_pb_elite_regime_safe(fs):
            return False, {"reason": "regime_not_safe"}

        q0 = base_quality if isinstance(base_quality, dict) else {}
        if not q0:
            try:
                q0 = _V702_CANONICAL_PB_HARD_QUALITY(c, snapshot if isinstance(snapshot, dict) else {})
            except Exception as exc:
                return False, {"reason": f"canonical_quality_exception:{type(exc).__name__}"}
        if bool(q0.get("ok")):
            return False, {"reason": "already_passed", "quality": q0.get("quality")}
        base_reason = str(q0.get("reason") or "").lower()
        if base_reason not in {"volume_below_floor", "rs_below_floor"}:
            return False, {"reason": "non_recoverable_reason", "base_reason": base_reason}

        facts = _v702_pullback_precision_facts(c, snapshot if isinstance(snapshot, dict) else {})
        eng = _v702_pb_elite_score100(c)
        htf = _v702_pb_elite_num(facts.get("htf_strength"))
        structure = _v702_pb_elite_num(facts.get("structure"))
        retest = _v702_pb_elite_num(facts.get("retest"))
        chase = _v702_pb_elite_num(facts.get("chase_atr"))
        vol = _v702_pb_elite_num(facts.get("volume_ratio"))
        rs = _v702_pb_elite_num(facts.get("rs_5m"))
        vals = (eng, htf, structure, retest, chase, vol, rs)
        if any(v is None for v in vals):
            return False, {"reason": "missing_elite_quality_fact", "facts": facts}

        if eng < float(CONFIG.get("V702_PB_ELITE_MIN_ENGINE_SCORE", 98.0)):
            return False, {"reason": "engine_below_elite_floor", "value": eng}
        if htf < float(CONFIG.get("V702_PB_ELITE_MIN_HTF", 75.0)):
            return False, {"reason": "htf_below_elite_floor", "value": htf}
        if structure < float(CONFIG.get("V702_PB_ELITE_MIN_STRUCTURE", 65.0)):
            return False, {"reason": "structure_below_elite_floor", "value": structure}
        if retest < float(CONFIG.get("V702_PB_ELITE_MIN_RETEST", 65.0)):
            return False, {"reason": "retest_below_elite_floor", "value": retest}
        if chase > float(CONFIG.get("V702_PB_ELITE_MAX_CHASE_ATR", 0.55)):
            return False, {"reason": "chase_above_elite_floor", "value": chase}

        hard_vol = float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO", 0.85))
        hard_rs = float(CONFIG.get("V587_PULLBACK_MIN_RS", 0.0))
        weak = []
        if vol < hard_vol:
            weak.append("volume")
        if rs < hard_rs:
            weak.append("rs")
        if len(weak) != 1:
            return False, {"reason": "not_exactly_one_weak_metric", "weaknesses": weak}
        if weak[0] == "volume" and not (float(CONFIG.get("V702_PB_ELITE_VOLUME_MIN", 0.75)) <= vol < hard_vol):
            return False, {"reason": "volume_deficit_too_large", "value": vol}
        if weak[0] == "rs" and not (float(CONFIG.get("V702_PB_ELITE_RS_MIN", -0.0025)) <= rs < hard_rs):
            return False, {"reason": "rs_deficit_too_large", "value": rs}

        setup_candidates = (
            fs.get("v587_setup_quality"), fs.get("setup_quality"), fs.get("setup_quality_score")
        )
        setup_seen = False
        for sv in setup_candidates:
            sn = _v702_pb_elite_num(sv)
            if sn is None:
                continue
            setup_seen = True
            if sn < float(CONFIG.get("V587_PULLBACK_MIN_SETUP_QUALITY", 72.0)):
                return False, {"reason": "setup_quality_below_floor", "value": sn}
            break

        # Without a live prepared snapshot, require feature-level confluence so
        # the preview never becomes a blind allow. Final application always uses
        # closed-bar evidence from the prepared snapshot.
        anchors = int(sum(bool(fs.get(k)) for k in (
            "reclaim", "zone_reclaim", "higher_low", "bullish_close",
            "ema20_slope_up", "ema20_slope", "above_ema50", "p15_stack",
        )))
        if require_closed:
            evfn = globals().get("_v660_closed_evidence")
            ev = evfn(c, snapshot) if callable(evfn) and isinstance(snapshot, dict) else {}
            if not ev:
                return False, {"reason": "closed_data_unavailable"}
            afn = globals().get("_v660_anchors")
            anchors = int(afn(c, ev) if callable(afn) else sum(bool(x) for x in (
                ev.get("zone_reclaim"), ev.get("higher_low"), ev.get("bullish_close"),
                ev.get("ema20_slope_up"), ev.get("above_ema50"), ev.get("rejection_candle"),
            )))
            counteranchors = int(sum(bool(x) for x in (
                ev.get("zone_reclaim"), ev.get("higher_low"), ev.get("ema20_slope_up"), ev.get("above_ema50")
            )))
            if anchors < int(CONFIG.get("V702_PB_ELITE_MIN_ANCHORS", 4)):
                return False, {"reason": "anchors_below_elite_floor", "anchors": anchors, "evidence": ev}
            if counteranchors < int(CONFIG.get("V702_PB_ELITE_MIN_COUNTER_ANCHORS", 3)):
                return False, {"reason": "counteranchors_below_elite_floor", "counteranchors": counteranchors, "evidence": ev}
            genuine_bearish = bool(fs.get("genuine_bearish_displacement", False)) or (
                float(ev.get("body_ratio", 0.0) or 0.0) >= 0.75
                and not bool(ev.get("bullish_close"))
                and not bool(ev.get("zone_reclaim"))
                and not bool(ev.get("higher_low"))
                and not bool(ev.get("ema20_slope_up"))
            )
            if genuine_bearish:
                return False, {"reason": "genuine_bearish_displacement", "evidence": ev}
            if not bool(ev.get("bullish_close") or ev.get("zone_reclaim") or ev.get("higher_low")):
                return False, {"reason": "no_current_reclaim_confirmation", "evidence": ev}
            return True, {
                "reason": "elite_closed_bar_eligible", "weakness": weak[0],
                "engine": eng, "htf": htf, "structure": structure, "retest": retest,
                "chase": chase, "volume": vol, "rs": rs, "anchors": anchors,
                "counteranchors": counteranchors, "evidence": ev, "setup_seen": setup_seen,
            }

        if anchors < int(CONFIG.get("V702_PB_ELITE_MIN_ANCHORS", 4)):
            return False, {"reason": "preview_confluence_too_weak", "anchors": anchors, "weakness": weak[0]}
        return True, {
            "reason": "elite_preview_deferred", "weakness": weak[0], "engine": eng,
            "htf": htf, "structure": structure, "retest": retest, "chase": chase,
            "volume": vol, "rs": rs, "anchors": anchors, "setup_seen": setup_seen,
        }
    except Exception as exc:
        STATS["v702_pb_elite_errors"] = int(STATS.get("v702_pb_elite_errors", 0) or 0) + 1
        return False, {"reason": f"exception:{type(exc).__name__}"}


def _v702_pb_elite_recover(candidate, market_data):
    """Apply the elite lane, then re-run the unchanged V669 hard contract."""
    c = getattr(candidate, "candidate", candidate)
    snap = market_data if isinstance(market_data, dict) else {}
    try:
        base = _V702_CANONICAL_PB_HARD_QUALITY(c, snap)
    except Exception as exc:
        return c, {"ok": False, "quality": 0.0, "reason": f"canonical_quality_exception:{type(exc).__name__}"}, {"applied": False, "reason": "base_exception"}
    if isinstance(base, dict) and bool(base.get("ok")):
        return c, base, {"applied": False, "reason": "already_passed"}
    if not _v702_pb_elite_attempt_allowed(snap):
        STATS["v702_pb_elite_attempt_cap_hits"] = int(STATS.get("v702_pb_elite_attempt_cap_hits", 0) or 0) + 1
        return c, base, {"applied": False, "reason": "per_cycle_attempt_cap"}
    pre_ok, pre = _v702_pb_elite_preflight(c, base, snapshot=snap, require_closed=True)
    if not pre_ok:
        STATS["v702_pb_elite_rejects"] = int(STATS.get("v702_pb_elite_rejects", 0) or 0) + 1
        STATS[f"v702_pb_elite_reject.{pre.get('reason','unknown')}"] = int(STATS.get(f"v702_pb_elite_reject.{pre.get('reason','unknown')}", 0) or 0) + 1
        return c, base, {"applied": False, **pre}
    _v702_pb_elite_mark_attempt(snap)
    weakness = str(pre.get("weakness") or "")
    fs = _v702_pb_elite_candidate_snapshot(c)
    ev = dict(pre.get("evidence") or {})
    if weakness == "volume":
        vm = _v702_pb_elite_num(ev.get("volume_ratio_median3"))
        tv = _v702_pb_elite_num(ev.get("trigger_volume_ratio"))
        soft_bars = int(ev.get("volume_bars_above_soft", 0) or 0)
        anchor = bool(ev.get("bullish_close") or ev.get("zone_reclaim") or ev.get("higher_low") or ev.get("rejection_candle"))
        if not (vm is not None and vm >= float(CONFIG.get("V702_PB_ELITE_VOLUME_MEDIAN3_MIN", 0.85)) and
                tv is not None and tv >= float(CONFIG.get("V702_PB_ELITE_VOLUME_TRIGGER_MIN", 1.10)) and
                soft_bars >= int(CONFIG.get("V702_PB_ELITE_VOLUME_MIN_SOFT_BARS", 2)) and anchor):
            STATS["v702_pb_elite_volume_evidence_failures"] = int(STATS.get("v702_pb_elite_volume_evidence_failures", 0) or 0) + 1
            return c, base, {"applied": False, "reason": "volume_closed_evidence_not_strong_enough", "evidence": ev}
        fs.update({
            "v702_pb_elite_recovery": True,
            "v702_pb_elite_weakness": "volume",
            "v702_pb_elite_original_volume": pre.get("volume"),
            "v702_pb_elite_effective_volume": vm,
            "volume_ratio": vm,
            "v702_pb_elite_closed_evidence": dict(ev),
        })
    elif weakness == "rs":
        r3 = _v702_pb_elite_num(ev.get("rs3")); r6 = _v702_pb_elite_num(ev.get("rs6")); r12 = _v702_pb_elite_num(ev.get("rs12")); rm = _v702_pb_elite_num(ev.get("rs_median")); imp = _v702_pb_elite_num(ev.get("rs_improvement"))
        if not (r3 is not None and r3 >= float(CONFIG.get("V702_PB_ELITE_RS_SHORT_MIN", 0.0)) and
                r6 is not None and r6 >= float(CONFIG.get("V702_PB_ELITE_RS_R6_R12_MIN", -0.0010)) and
                r12 is not None and r12 >= float(CONFIG.get("V702_PB_ELITE_RS_R6_R12_MIN", -0.0010)) and
                rm is not None and rm >= float(CONFIG.get("V702_PB_ELITE_RS_MEDIAN_MIN", -0.00010)) and
                imp is not None and imp >= float(CONFIG.get("V702_PB_ELITE_RS_IMPROVEMENT_MIN", 0.00030))):
            STATS["v702_pb_elite_rs_evidence_failures"] = int(STATS.get("v702_pb_elite_rs_evidence_failures", 0) or 0) + 1
            return c, base, {"applied": False, "reason": "rs_closed_evidence_not_strong_enough", "evidence": ev}
        fs.update({
            "v702_pb_elite_recovery": True,
            "v702_pb_elite_weakness": "rs",
            "v702_pb_elite_original_rs": pre.get("rs"),
            "v702_pb_elite_effective_rs": r3,
            "rs_5m": r3,
            "v702_pb_elite_closed_evidence": dict(ev),
        })
    else:
        return c, base, {"applied": False, "reason": "unknown_weakness"}

    fs["v702_pb_elite_risk_factor"] = float(CONFIG.get("V702_PB_ELITE_RECOVERY_RISK_FACTOR", 0.65))
    fs["v702_pb_elite_contract"] = "V669_HARD_RECHECK_REQUIRED"
    fs["v702_pb_elite_applied_at"] = float(WALL_NOW())
    try:
        rec = replace(c, features_snapshot=fs)
    except Exception:
        try:
            rec = _v660_rebuild(c, fs) if callable(globals().get("_v660_rebuild")) else None
        except Exception:
            rec = None
        if rec is None or rec is c:
            return c, base, {"applied": False, "reason": "candidate_rebuild_failed"}
    try:
        q2 = _V702_CANONICAL_PB_HARD_QUALITY(rec, snap)
    except Exception as exc:
        return c, base, {"applied": False, "reason": f"post_recovery_quality_exception:{type(exc).__name__}"}
    if not isinstance(q2, dict) or not bool(q2.get("ok")):
        STATS["v702_pb_elite_contract_failures"] = int(STATS.get("v702_pb_elite_contract_failures", 0) or 0) + 1
        return c, base, {"applied": False, "reason": "v669_contract_failed_after_recovery", "post_reason": str((q2 or {}).get("reason", "")), "evidence": ev}
    STATS["v702_pb_elite_passes"] = int(STATS.get("v702_pb_elite_passes", 0) or 0) + 1
    STATS[f"v702_pb_elite_pass.{weakness}"] = int(STATS.get(f"v702_pb_elite_pass.{weakness}", 0) or 0) + 1
    return rec, dict(q2, v702_pb_elite_recovered=True, v702_pb_elite_weakness=weakness), {
        "applied": True, "reason": "elite_closed_bar_one_variable_recovery",
        "weakness": weakness, "evidence": ev, "risk_factor": fs["v702_pb_elite_risk_factor"],
        "post_quality": q2,
    }


# FINAL PULLBACK quality authority wrapper: base V669 remains the hard contract;
# the only additive behavior is the strictly proven one-variable elite lane.
def _v702_pb_elite_pullback_quality(candidate, market_data=None):
    base = _V702_CANONICAL_PB_HARD_QUALITY(candidate, market_data if isinstance(market_data, dict) else {})
    fam = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
    if fam not in {"PULLBACK", "MTF_PULLBACK"} or bool(base.get("ok")):
        return base
    rec, q2, diag = _v702_pb_elite_recover(candidate, market_data)
    if bool(diag.get("applied")) and bool(q2.get("ok")):
        out = dict(q2)
        out["v702_pb_elite"] = dict(diag)
        return out
    return base

_v702_pb_elite_pullback_quality._v702_pb_elite_final_authority = True
_v587_pullback_quality = _v702_pb_elite_pullback_quality


# =============================================================================
# V702 FINAL AUDIT — PULLBACK QUALITY CACHE / SINGLE-SNAPSHOT DEDUP
# =============================================================================
# Production evidence showed the same PULLBACK opportunity can traverse the
# canonical precision authority several times (prequal parity, selected recheck,
# builder precheck, telemetry/preview). This is not a new trading rule: it is the
# exact same deterministic closed-snapshot contract being recomputed. Repeating
# it wastes CPU and inflates rejection telemetry, which can make the strategy look
# stricter than it really is.
#
# The cache is deliberately narrow and fail-closed:
#   * PULLBACK/MTF_PULLBACK only.
#   * Key includes cycle + snapshot/candle identity + all mutable precision facts
#     that can affect the final result.
#   * TTL and bounded size prevent stale cross-cycle reuse.
#   * The cached value is the FINAL V702 result, including any already-attempted
#     bounded elite recovery.
#   * No market-data fetch, threshold relaxation, or execution bypass is added.
# =============================================================================
CONFIG.update({
    "V702_PB_QUALITY_CACHE_ENABLE": True,
    "V702_PB_QUALITY_CACHE_MAX": 4096,
    "V702_PB_QUALITY_CACHE_TTL_SEC": 900.0,
})
_V702_PB_QUALITY_CACHE = OrderedDict()

def _v702_pb_quality_cache_key(candidate, market_data=None) -> str:
    try:
        c = getattr(candidate, "candidate", candidate)
        fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
        if fam not in {"PULLBACK", "MTF_PULLBACK"}:
            return ""
        fs = dict(getattr(c, "features_snapshot", {}) or {})
        md = market_data if isinstance(market_data, dict) else {}
        df5 = md.get("df_5m")
        candle = md.get("closed_candle_ts") or md.get("candle_ts") or fs.get("closed_candle_ts") or fs.get("candle_ts")
        if not candle and df5 is not None and len(df5) >= 2:
            candle = _v669_context_scalar(df5.index[-2], field="candle_ts")
        snapshot_id = str(md.get("snapshot_id") or fs.get("snapshot_id") or "")
        cycle_id = int(_v702_current_cycle_id(md))
        fields = {
            "symbol": str(getattr(c, "symbol", "") or "").upper(),
            "family": fam,
            "mode": str(getattr(c, "strategy_mode", "") or fam).upper(),
            "cycle_id": cycle_id,
            "snapshot_id": snapshot_id,
            "candle": str(candle or ""),
            "engine_score": getattr(c, "engine_score", None),
            "entry_ref": getattr(c, "entry_ref", None),
            "sl_price": getattr(c, "sl_price", None),
            "zone_ref": fs.get("zone_ref", getattr(c, "zone_ref", None)),
            "htf_strength": fs.get("htf_strength", fs.get("htf_score")),
            "structure": fs.get("structure", fs.get("structure_confidence", fs.get("structure_score"))),
            "retest": fs.get("retest", fs.get("retest_score", fs.get("retest_quality_score"))),
            "volume_ratio": fs.get("volume_ratio"),
            "rs_5m": fs.get("rs_5m", fs.get("rs_score_val")),
            "chase_atr": fs.get("chase_atr"),
            "v702_pb_elite_recovery": fs.get("v702_pb_elite_recovery"),
            "v702_pb_elite_weakness": fs.get("v702_pb_elite_weakness"),
        }
        raw = json.dumps(fields, sort_keys=True, default=str, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8", "replace")).hexdigest()[:32]
    except Exception:
        _v647_record_suppressed_exception()
        return ""

def _v702_pb_quality_cache_get(key: str):
    try:
        if not key or not bool(CONFIG.get("V702_PB_QUALITY_CACHE_ENABLE", True)):
            return None
        rec = _V702_PB_QUALITY_CACHE.get(str(key))
        if not isinstance(rec, dict):
            return None
        now = WALL_NOW()
        if now - float(rec.get("ts", now) or now) > float(CONFIG.get("V702_PB_QUALITY_CACHE_TTL_SEC", 900.0)):
            _V702_PB_QUALITY_CACHE.pop(str(key), None)
            return None
        _V702_PB_QUALITY_CACHE.move_to_end(str(key))
        STATS["v702_pb_quality_cache_hits"] = int(STATS.get("v702_pb_quality_cache_hits", 0) or 0) + 1
        result = rec.get("result")
        return copy.deepcopy(result) if isinstance(result, dict) else result
    except Exception:
        _v647_record_suppressed_exception()
        return None

def _v702_pb_quality_cache_put(key: str, result: dict) -> None:
    try:
        if not key or not isinstance(result, dict) or not bool(CONFIG.get("V702_PB_QUALITY_CACHE_ENABLE", True)):
            return
        _V702_PB_QUALITY_CACHE[str(key)] = {"ts": WALL_NOW(), "result": copy.deepcopy(result)}
        _V702_PB_QUALITY_CACHE.move_to_end(str(key))
        while len(_V702_PB_QUALITY_CACHE) > int(CONFIG.get("V702_PB_QUALITY_CACHE_MAX", 4096)):
            _V702_PB_QUALITY_CACHE.popitem(last=False)
        STATS["v702_pb_quality_cache_entries"] = len(_V702_PB_QUALITY_CACHE)
    except Exception:
        _v647_record_suppressed_exception()

_V702_PB_QUALITY_CACHE_BASE = _v587_pullback_quality

def _v702_cached_pullback_quality(candidate, market_data=None):
    fam = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
    if fam not in {"PULLBACK", "MTF_PULLBACK"} or not bool(CONFIG.get("V702_PB_QUALITY_CACHE_ENABLE", True)):
        return _V702_PB_QUALITY_CACHE_BASE(candidate, market_data)
    key = _v702_pb_quality_cache_key(candidate, market_data)
    if key:
        cached = _v702_pb_quality_cache_get(key)
        if cached is not None:
            return cached
    STATS["v702_pb_quality_cache_misses"] = int(STATS.get("v702_pb_quality_cache_misses", 0) or 0) + 1
    result = _V702_PB_QUALITY_CACHE_BASE(candidate, market_data)
    if isinstance(result, dict) and key:
        _v702_pb_quality_cache_put(key, result)
    return result

_v702_cached_pullback_quality._v702_pb_cache_wrapper = True
_v702_cached_pullback_quality._v702_pb_wrapped_base = _V702_PB_QUALITY_CACHE_BASE
_v587_pullback_quality = _v702_cached_pullback_quality


# PRESELECTION closure: the historical V642 preview may reject a slight single
# variable miss before the real prepared snapshot reaches SignalBuilder. For
# only the elite class, defer the final decision to the exact canonical quality
# wrapper. No unknown candidate is allowed through this lane.
_V702_PB_ELITE_PREVIEW_BASE = globals().get("_v642_pullback_precision_preview")

def _v702_pb_elite_preview(candidate):
    if callable(_V702_PB_ELITE_PREVIEW_BASE):
        base = _V702_PB_ELITE_PREVIEW_BASE(candidate)
    else:
        base = (True, "not_applicable", {})
    try:
        c = getattr(candidate, "candidate", candidate)
        fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
        if fam not in {"PULLBACK", "MTF_PULLBACK"} or bool(base[0]):
            return base
        if not bool(CONFIG.get("V702_PB_ELITE_PREVIEW_DEFER_ENABLE", True)):
            return base
        reason = str(base[1] or "").lower()
        if reason not in {"volume_below_floor", "rs_negative", "rs_below_floor", "precision.volume", "precision.rs", "volume_below_floor"} and not any(x in reason for x in ("volume_below_floor", "rs_below_floor", "precision.volume", "precision.rs")):
            return base
        ok, meta = _v702_pb_elite_preflight(c, snapshot=None, require_closed=False)
        if ok:
            STATS["v702_pb_elite_preview_deferrals"] = int(STATS.get("v702_pb_elite_preview_deferrals", 0) or 0) + 1
            return True, "v702.elite_deferred_to_canonical", {"base_preview": base[2] if len(base) > 2 else {}, "elite": meta}
        return base
    except Exception as exc:
        STATS["v702_pb_elite_preview_errors"] = int(STATS.get("v702_pb_elite_preview_errors", 0) or 0) + 1
        return base

