# ---- Canonical chase helper -------------------------------------------------
def _v669_chase_detail(entry: float, zone: float, atr: float) -> Dict[str, Any]:
    try:
        e,z,a = float(entry),float(zone),float(atr)
        gap = abs(e-z)/max(a,1e-12)
        soft=float(CONFIG.get("V669_CHASE_SOFT_ATR",0.60)); hard=float(CONFIG.get("V669_CHASE_HARD_ATR",1.10)); jit=float(CONFIG.get("V669_CHASE_JIT_ATR",0.90))
        result = "PASS" if gap <= hard else "HARD_REJECT"
        return {"chase_atr":gap,"soft_limit":soft,"hard_limit":hard,"jit_limit":jit,"result":result,"source":"V669_CANONICAL_CHASE"}
    except Exception as exc:
        return {"chase_atr":None,"result":"ERROR","source":"V669_CANONICAL_CHASE","error":type(exc).__name__}

# ---- Fee viability: direct canonical ranking probe ------------------------
def _v669_fee_viable(candidate: Any) -> Tuple[bool, Dict[str, Any]]:
    try:
        c = candidate.candidate if isinstance(candidate, RankedCandidate) else candidate
        entry = float(getattr(c, "entry_ref", 0.0) or 0.0)
        sl = float(getattr(c, "sl_price", 0.0) or 0.0)
        if entry <= 0 or sl <= 0 or sl >= entry:
            STATS["v669_last_fee_probe"] = {"ok":False,"reason":"invalid_geometry"}
            return False
        # Exact live ticket scale. Never use the legacy 15-USDT probe.
        notional = min(float(CONFIG.get("MAX_ENTRY_NOTIONAL_USDT",75.0)), max(0.01, float(CONFIG.get("V576_REQUESTED_POSITION_USDT", CONFIG.get("FIXED_POSITION_SIZE_USDT",75.0)))))
        notional = min(notional, float(CONFIG.get("MAX_POSITION_SIZE_USDT",75.0)))
        tp1 = entry + float(getattr(c,"tp1_rr",0.0) or 0.0) * (entry-sl)
        tp2 = entry + float(getattr(c,"tp2_rr",0.0) or 0.0) * (entry-sl)
        if tp1 <= entry or tp2 <= entry:
            STATS["v669_last_fee_probe"] = {"ok":False,"reason":"invalid_targets","notional":notional}
            return False
        _fs_fee = getattr(c, "features_snapshot", {}) or {}
        detail = SizingEngine.fee_viability_detail(
            entry, sl, tp1, tp2, notional,
            spread_pct=_fs_fee.get("spread_pct") if isinstance(_fs_fee, dict) else None,
            small_net_mode=bool(CONFIG.get("V702_SMALL_NET_PROFIT_MODE_ENABLE", False)),
        )
        detail = dict(detail or {})
        _coh_geo = globals().get("canonical_economic_geometry")
        if callable(_coh_geo):
            try:
                _runner_on = bool(CONFIG.get("ENABLE_RUNNER_MODE", False))
                _w = [float(CONFIG.get("TP1_EXIT_PCT", 0.5)), float(CONFIG.get("TP2_EXIT_PCT", 0.3))]
                if _runner_on:
                    _w.append(float(CONFIG.get("RUNNER_KEEP_PCT_AT_TP3", 0.2)))
                    _tps = [tp1, tp2, entry + float(getattr(c, "tp3_rr", 0.0) or 0.0) * (entry-sl)]
                else:
                    _tps = [tp1, tp2]
                _sumw = sum(_w)
                if _sumw > 0:
                    _w = [x/_sumw for x in _w]
                _g = _coh_geo(entry, sl, _tps, max(0.0, float(CONFIG.get("TAKER_FEE_PCT", 0.10)))/100.0, notional, _w)
                detail["coherence_economic_geometry"] = _g
                STATS["coherence_economic_geometry_used"] = int(STATS.get("coherence_economic_geometry_used", 0) or 0) + 1
            except Exception as _geo_exc:
                detail["coherence_economic_geometry"] = {"ok":False,"reason":f"telemetry_exception:{type(_geo_exc).__name__}"}
        detail.update({"notional":notional,"entry":entry,"sl":sl,"tp1":tp1,"tp2":tp2,"source":"V669_LIVE_TICKET_SCALE"})
        ok = bool(detail.get("ok",False))
        STATS["v669_last_fee_probe"] = detail
        if not ok:
            STATS["v669_mse_fee_rejected"] = int(STATS.get("v669_mse_fee_rejected",0) or 0)+1
        else:
            STATS["v669_mse_fee_passed"] = int(STATS.get("v669_mse_fee_passed",0) or 0)+1
        return ok
    except Exception as exc:
        STATS["v669_mse_fee_exceptions"] = int(STATS.get("v669_mse_fee_exceptions",0) or 0)+1
        STATS["v669_last_fee_probe"] = {"ok":False,"reason":f"exception:{type(exc).__name__}"}
        return False

CompositeRankingEngine._fee_viable = staticmethod(_v669_fee_viable)

