def _v669_watchdog_reset() -> None:
    try:
        ExchangeWatchdog._errors.clear()
        if hasattr(ExchangeWatchdog, "_readonly_errors"):
            ExchangeWatchdog._readonly_errors.clear()
        ExchangeWatchdog._trips = 0
        ExchangeWatchdog._tripped_until = 0.0
        ExchangeWatchdog._last_reason = ""
        ExchangeWatchdog._last_reason_detail = {}
        ExchangeWatchdog._v669_last_trip_ts = 0.0
        ExchangeWatchdog._v669_trip_count = 0
        STATS["v669_watchdog_trip_count"] = 0
        STATS["v669_watchdog_window_error_count"] = 0
    except Exception:
        pass

_V669_WATCHDOG_BUCKETS = ("balance", "cancel_order", "sl", "tp", "reconcile", "other_state_change")
_V669_WATCHDOG_TYPES = ("connection_reset", "exchange_error", "insufficient_balance", "rate_limit", "unknown")

def _v669_watchdog_record_error(op_name: str, reason: str = "") -> None:
    try:
        op = str(op_name or "").lower(); r=str(reason or "")[:240]
        _wd_cls = globals().get("watchdog_classify_op")
        _wd_class = _wd_cls(op_name) if callable(_wd_cls) else ("READ_ONLY_MARKET" if bool(_v651_is_readonly_market_data_op(op)) else "ENTRY_CRITICAL")
        STATS[f"coherence_watchdog_class_{str(_wd_class).lower()}"] = int(STATS.get(f"coherence_watchdog_class_{str(_wd_class).lower()}", 0) or 0) + 1
        readonly = bool(_wd_class == "READ_ONLY_MARKET")
        if readonly:
            try:
                ExchangeWatchdog._readonly_errors.append(MONO_NOW())
            except Exception:
                pass
            return
        bucket = "other_state_change"
        for k in _V669_WATCHDOG_BUCKETS:
            if k in op:
                bucket=k; break
        typ="unknown"
        t=r.lower()
        if "timeout" in t or "reset" in t or "connection" in t: typ="connection_reset"
        elif "rate" in t or "429" in t: typ="rate_limit"
        elif "balance" in t or "insufficient" in t: typ="insufficient_balance"
        elif "exchange" in t or "5xx" in t: typ="exchange_error"
        rec = getattr(ExchangeWatchdog, "_errors", None)
        if rec is not None:
            rec.append(MONO_NOW())
        STATS[f"v669_watchdog_{bucket}"] = int(STATS.get(f"v669_watchdog_{bucket}",0) or 0)+1
        STATS[f"v669_watchdog_type_{typ}"] = int(STATS.get(f"v669_watchdog_type_{typ}",0) or 0)+1
        cls = ExchangeWatchdog
        detail = {"op":op,"bucket":bucket,"type":typ,"reason":r,"timestamp":WALL_NOW()}
        STATS["v669_watchdog_last"] = detail
        try:
            cls._last_reason_detail = detail
        except Exception:
            pass
    except Exception:
        _v647_record_suppressed_exception()


def _v669_watchdog_is_tripped() -> bool:
    try:
        now=MONO_NOW(); threshold=max(1,int(CONFIG.get("V4_WATCHDOG_ERROR_THRESHOLD",8) or 8)); window=max(1.0,float(CONFIG.get("V4_WATCHDOG_WINDOW_SEC",60.0) or 60.0))
        errors=getattr(ExchangeWatchdog,"_errors",deque())
        recent=[t for t in errors if now-float(t)<=window]
        return bool(float(getattr(ExchangeWatchdog,"_tripped_until",0.0) or 0.0)>now or len(recent)>=threshold)
    except Exception:
        return True

ExchangeWatchdog.record_error = staticmethod(_v669_watchdog_record_error)

@classmethod
def _v669_watchdog_is_tripped_authority(cls):
    now = MONO_NOW()
    tripped = _v669_watchdog_is_tripped()
    try:
        if tripped:
            last = float(getattr(cls, "_v669_last_trip_ts", 0.0) or 0.0)
            if last <= 0.0 or now - last > 1.0:
                cls._v669_last_trip_ts = now
                cls._v669_trip_count = int(getattr(cls, "_v669_trip_count", 0) or 0) + 1
                recent_count = len([t for t in getattr(cls, "_errors", deque()) if now - float(t) <= max(1.0, float(CONFIG.get("V4_WATCHDOG_WINDOW_SEC",60.0)))])
                STATS["v669_watchdog_trip_timestamp"] = WALL_NOW()
                STATS["v669_watchdog_trip_count"] = int(getattr(cls, "_v669_trip_count", 0) or 0)
                STATS["v669_watchdog_window_error_count"] = int(recent_count)
                STATS["v669_watchdog_trip_reason"] = dict(getattr(cls, "_last_reason_detail", {}) or {})
    except Exception:
        _v647_record_suppressed_exception()
    return bool(tripped)

ExchangeWatchdog.is_tripped = _v669_watchdog_is_tripped_authority

