# ---- Starvation classifier: CURRENT_CYCLE first, then history --------------
def _v679_starvation_classify(window_sec: Optional[float] = None) -> Dict[str, Any]:
    """Classify starvation from current-cycle counts, not fixed bucket priority.

    SYSTEM is always absolute priority because it represents a safety/runtime
    hazard. For ordinary reject buckets, the largest current-cycle count wins;
    ties use the established priority order. Historical data is only fallback.
    """
    try:
        cid = int(globals().get("_V517_ACTIVE_CYCLE_ID") or STATS.get("v681_runtime_cycle_id", 0) or STATS.get("v680_last_cycle_id", 0) or STATS.get("v669_last_cycle_id", 0) or 0)
        current = V669RejectionLedger.current_cycle(cid)
        current_counts = V669RejectionLedger.counts(current)
        if int(current_counts.get("SYSTEM", 0) or 0) > 0:
            root = "SYSTEM"
        else:
            non_system = {
                str(k): int(v or 0) for k, v in current_counts.items()
                if str(k) != "SYSTEM" and int(v or 0) > 0
            }
            if non_system:
                pri = {name: i for i, name in enumerate(V669RejectionLedger.PRIORITY)}
                root = max(non_system, key=lambda k: (non_system[k], -pri.get(k, 999)))
            else:
                root = "NONE"
        total = sum(int(v or 0) for v in current_counts.values())
        root_count = int(current_counts.get(root, 0) or 0) if root != "NONE" else 0
        root_share = (root_count / float(total)) if total and root != "NONE" else 0.0
        return {
            "mode": root, "source": "CURRENT_CYCLE", "cycle_id": cid,
            "counts": current_counts, "root": root, "root_count": root_count,
            "root_share": round(root_share, 4),
            "current_cycle_age": float(STATS.get("v669_current_cycle_age", 0.0) or 0.0),
        }
    except Exception as exc:
        return {"mode":"SYSTEM", "source":"CURRENT_CYCLE_ERROR", "root":"SYSTEM",
                "error":f"{type(exc).__name__}:{exc}"}

# Existing class is a classmethod authority. Assign a direct final function,
# not another nesting wrapper.
try:
    V453StarvationClassifier.classify = classmethod(lambda cls: _v679_starvation_classify())
except Exception:
    pass

