_original_emit_heartbeat = Telemetry.emit_heartbeat

async def _v669_emit_heartbeat_direct(*args, **kwargs):
    try:
        # Publish the canonical current-cycle starvation truth BEFORE the legacy
        # heartbeat renders its line. This prevents stale v425 TECH_STARVATION from
        # masking a real HTF/POLICY/STRUCTURE root in the operator log.
        try:
            _sc = dict(_v679_starvation_classify() or {})
            _sm = str(_sc.get("mode") or "NONE").upper()
            STATS["v425_starvation_mode"] = {
                "SYSTEM":"SYSTEM_STARVATION", "POLICY":"POLICY_STARVATION",
                "HTF":"HTF_STARVATION", "LIQUIDITY":"LIQUIDITY_STARVATION",
                "STRUCTURE":"STRUCTURE_STARVATION", "SCORE":"SCORE_STARVATION",
                "FEE":"FEE_STARVATION", "PRE_SEND":"PRE_SEND_STARVATION",
                "EXECUTION":"EXECUTION_STARVATION", "OTHER":"TECH_STARVATION",
                "NONE":"NONE"}.get(_sm, _sm)
        except Exception:
            STATS["v425_starvation_mode"] = STATS.get("v425_starvation_mode", "NONE")
        try:
            result = await _original_emit_heartbeat(*args, **kwargs)
        except TypeError:
            result = await _original_emit_heartbeat()
        except Exception as exc:
            STATS["v669_heartbeat_inner_errors"] = int(STATS.get("v669_heartbeat_inner_errors",0) or 0)+1
            logger.exception("[V669-HEARTBEAT] inner telemetry error suppressed: %s", exc)
            result = None
        snap=V669CycleLedger.snapshot()
        rc=snap.get("reject_buckets",{})
        family_counts=STATS.get("v669_family_funnel",{}) or {}
        line=(
            f"[V669-HB] FUNNEL G/H/P/R/S/B/P/Q/S={snap.get('generated',0)}/{snap.get('hard_valid',0)}/"
            f"{snap.get('prequal_pass',0)}/{snap.get('ranked',0)}/{snap.get('selected',0)}/"
            f"{snap.get('builder_pass',0)}/{snap.get('presend_pass',0)}/{snap.get('queued',0)}/{snap.get('sent',0)} "
            f"TOP_SYSTEM={rc.get('SYSTEM',0)} TOP_POLICY={rc.get('POLICY',0)} TOP_HTF={rc.get('HTF',0)} "
            f"TOP_LIQUIDITY={rc.get('LIQUIDITY',0)} TOP_STRUCTURE={rc.get('STRUCTURE',0)} TOP_SCORE={rc.get('SCORE',0)} "
            f"TOP_FEE={rc.get('FEE',0)} TOP_PRE_SEND={rc.get('PRE_SEND',0)} TOP_EXECUTION={rc.get('EXECUTION',0)} "
            f"CURRENT_CYCLE_ROOT={snap.get('root','NONE')} CURRENT_CYCLE_ID={snap.get('cycle_id',0)} CURRENT_CYCLE_AGE={snap.get('age_sec',0):.1f} "
            f"FAMILY_COUNTS={json.dumps(family_counts,ensure_ascii=False,default=str)[:1000]} "
            f"CONTEXT_DRIFT={STATS.get('v669_context_drift_counts',{})}"
        )
        logger.info(line)
        STATS["v669_last_heartbeat"]={"cycle":snap,"reject_buckets":rc,"family_counts":family_counts}
        return result
    except Exception as exc:
        STATS["v669_heartbeat_outer_errors"] = int(STATS.get("v669_heartbeat_outer_errors",0) or 0)+1
        logger.exception("[V669-HEARTBEAT] outer instrumentation exception: %s", exc)
        return None

Telemetry.emit_heartbeat = staticmethod(_v669_emit_heartbeat_direct)

# ---- Context coherence at exact prequal boundary ---------------------------
# We preserve the existing canonical decision path, but make drift visible.
# A drift is explicitly recorded and, unless a caller is in a legacy diagnostic
# fallback, is fail-closed at the prequalification authority.
_old_prequal_active = _v453_prequalify

def _v669_prequal_context_coherent(r: "RankedCandidate", snap_by_symbol: Dict[str, Dict[str, Any]]) -> Tuple[bool, str]:
    sym=str(getattr(getattr(r,"candidate",None),"symbol","") or "")
    snap=(snap_by_symbol or {}).get(sym) or {}
    # Deduplicate BEFORE expensive policy evaluation. The same symbol/family/
    # closed-candle opportunity must consume one canonical evaluation identity.
    try:
        _cc=getattr(r,"candidate",None)
        _fam=str(getattr(_cc,"family","") or getattr(_cc,"strategy_mode","") or "").upper()
        _mode=str(getattr(_cc,"strategy_mode","") or "").upper()
        _cctx=_v669_context_from(_cc,snap)
        _oid=_v669_opportunity_id(sym,_cctx.get("candle_ts"),_fam,_mode,getattr(_cc,"zone_ref",""))
        _seen=V669OpportunityLedger.note(_oid,symbol=sym,cycle_id=int(globals().get("_V517_ACTIVE_CYCLE_ID") or STATS.get("v669_last_cycle_id",0) or 0),evaluation=True)
        if _seen.get("duplicate"):
            _cv=dict(getattr(_cc,"features_snapshot",{}) or {}).get("v688_prequal_verdict") or {}
            if bool(_cv.get("verdict")) and _v689_prequal_snapshot_reusable(_cc,snap):
                STATS["v689_prequal_reuse_hits"]=int(STATS.get("v689_prequal_reuse_hits",0) or 0)+1
                return True,"canonical_prequal_reuse"
            STATS["v669_duplicate_prequal_skips"] = int(STATS.get("v669_duplicate_prequal_skips",0) or 0) + 1
            return False, "policy.duplicate_opportunity"
    except Exception:
        _v647_record_suppressed_exception()
    drift=_v669_context_drift(getattr(r,"candidate",None), snap)
    # Record ALL drift for observability, but hard-reject only safety-critical
    # context mismatch. Canonical policy below remains authoritative for the
    # semantic fields.
    if drift.get("drift"):
        counts=STATS.get("v669_context_drift_counts") or {}
        for k in drift["drift"]:
            counts[k]=int(counts.get(k,0) or 0)+1
        STATS["v669_context_drift_counts"]=counts
        if drift.get("telemetry_drift"):
            tcounts=STATS.get("v669_context_telemetry_drift_counts") or {}
            for k in drift["telemetry_drift"]:
                tcounts[k]=int(tcounts.get(k,0) or 0)+1
            STATS["v669_context_telemetry_drift_counts"]=tcounts
        if drift.get("safety_drift"):
            ctx={"family":str(getattr(r.candidate,"family","") or ""),"strategy_mode":str(getattr(r.candidate,"strategy_mode","") or ""),
                 "macro_regime":drift["candidate"].get("macro_regime"),"candidate_macro":drift["candidate"].get("macro_regime"),
                 "snapshot_macro":drift["snapshot"].get("macro_regime"),"candidate_candle":drift["candidate"].get("candle_ts"),
                 "snapshot_candle":drift["snapshot"].get("candle_ts"),"reason_detail":json.dumps(drift["safety_drift"],default=str)[:1200]}
            try:
                record_rejection("context", sym, "context_drift", "context_drift", "context_coherence", ctx=ctx)
            except Exception:
                pass
            logger.warning("[V669-CONTEXT-DRIFT-SAFETY] symbol=%s drift=%s", sym, drift["safety_drift"])
            return False, "policy.context_drift"
        logger.info("[V669-CONTEXT-DRIFT-TELEMETRY] symbol=%s drift=%s", sym, drift.get("telemetry_drift"))
    return _old_prequal_active(r, snap_by_symbol)

# Keep the prequal authority single: this direct final implementation is the
# only added call-site check; it does not create an alternate execution path.
_v453_prequalify = _v669_prequal_context_coherent

