def _v671_elite_structural_recovery(candidate, snap, *, source="structural"):
    """Very strict PB/MTF recovery after an upstream structural disagreement."""
    try:
        if not bool(CONFIG.get("V671_ELITE_STRUCTURE_RECOVERY_ENABLE", True)):
            return False, {"reason": "disabled"}
        fam = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
        if fam not in {"PULLBACK", "MTF_PULLBACK"}:
            return False, {"reason": "family_not_allowed"}
        snap = snap if isinstance(snap, dict) else {}
        qfn = globals().get("_v587_pullback_quality")
        q = qfn(candidate, snap) if callable(qfn) else {}
        if not isinstance(q, dict) or not bool(q.get("ok", False)):
            return False, {"reason": "v587_quality_not_passed", "v587_reason": str((q or {}).get("reason", ""))}
        fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        engine = _v671_num(getattr(candidate, "engine_score", 0.0))
        if engine is not None and engine <= 1.0:
            engine *= 100.0
        htf = _v671_num(fs.get("htf_strength", fs.get("htf_alignment")))
        structure = _v671_num(fs.get("structure_confidence", fs.get("structure_quality")))
        retest = _v671_num(fs.get("retest_quality_score", fs.get("retest_quality")))
        volume = _v671_num(fs.get("volume_ratio"))
        rs = _v671_num(fs.get("rs_5m", fs.get("rs_score_val", fs.get("relative_strength"))))
        chase = _v671_num(fs.get("chase_atr"))
        values = (engine, htf, structure, retest, volume, rs, chase)
        if any(v is None for v in values):
            return False, {"reason": "missing_elite_quality_fact"}
        floors = {
            "engine": (engine, 98.0), "htf": (htf, 75.0), "structure": (structure, 65.0),
            "retest": (retest, 65.0), "volume": (volume, 1.00), "rs": (rs, -0.0025),
        }
        for name, (value, floor) in floors.items():
            if value < floor:
                return False, {"reason": f"{name}_below_elite_floor", "value": value, "floor": floor}
        if chase > 0.55:
            return False, {"reason": "chase_above_elite_floor", "value": chase, "floor": 0.55}
        evfn = globals().get("_v660_closed_evidence")
        ev = evfn(candidate, snap) if callable(evfn) else {}
        if not ev:
            return False, {"reason": "closed_data_unavailable"}
        afn = globals().get("_v660_anchors")
        anchors = int(afn(candidate, ev) if callable(afn) else sum(bool(x) for x in (
            ev.get("bullish_close"), ev.get("higher_low"), ev.get("zone_reclaim"),
            ev.get("ema20_slope_up"), ev.get("above_ema50"))))
        counteranchors = int(sum(bool(x) for x in (
            ev.get("zone_reclaim"), ev.get("higher_low"), ev.get("ema20_slope_up"), ev.get("above_ema50"))))
        genuine_bearish = (
            float(ev.get("body_ratio", 0.0) or 0.0) >= 0.75
            and not bool(ev.get("bullish_close"))
            and not bool(ev.get("zone_reclaim"))
            and not bool(ev.get("higher_low"))
            and not bool(ev.get("ema20_slope_up"))
        )
        if genuine_bearish:
            return False, {"reason": "genuine_bearish_displacement"}
        if anchors < 4 or counteranchors < 3:
            return False, {"reason": "insufficient_independent_closed_bar_evidence", "anchors": anchors, "counteranchors": counteranchors}
        if not bool(ev.get("bullish_close") or ev.get("zone_reclaim") or ev.get("higher_low")):
            return False, {"reason": "no_current_reclaim_confirmation"}
        zd = _v671_num(ev.get("zone_dist_atr"))
        if zd is not None and zd > 0.90 and not bool(ev.get("higher_low")):
            return False, {"reason": "zone_distance_excessive", "value": zd}
        return True, {
            "source": str(source), "engine": engine, "htf": htf, "structure": structure,
            "retest": retest, "volume": volume, "rs": rs, "chase": chase,
            "anchors": anchors, "counteranchors": counteranchors, "closed_evidence": ev,
            "v587_quality": q, "reason": "v671.elite_closed_bar_structural_recovery",
        }
    except Exception as exc:
        STATS["v671_elite_structural_recovery_errors"] = int(STATS.get("v671_elite_structural_recovery_errors", 0) or 0) + 1
        return False, {"reason": f"exception:{type(exc).__name__}"}


