def _v672_set_fs(candidate, fs):
    """Return an updated candidate without mutating a frozen StrategyCandidate."""
    try:
        if isinstance(candidate, dict):
            out = dict(candidate)
            out["features_snapshot"] = dict(fs)
            return out
        if isinstance(candidate, StrategyCandidate):
            return replace(candidate, features_snapshot=dict(fs))
        try:
            return replace(candidate, features_snapshot=dict(fs))
        except Exception:
            try:
                cloned = copy.copy(candidate)
                setattr(cloned, "features_snapshot", dict(fs))
                return cloned
            except Exception:
                return candidate
    except Exception:
        return candidate


def _v672_enrich_candidate_from_snapshot(candidate, snap, *, source="canonical"):
    """Fill absent PB/MTF quality facts from the exact prepared snapshot.

    This is a data-provenance repair only. Every value is recomputed from
    already-fetched CLOSED bars / candidate geometry or the existing bounded
    HTF recovery cache. Missing or non-finite inputs remain missing.
    """
    diag = {"source": str(source), "applied": [], "missing": [], "errors": []}
    try:
        STATS["v672_snapshot_enrichment_calls"] = int(STATS.get("v672_snapshot_enrichment_calls", 0) or 0) + 1
        if not bool(CONFIG.get("V672_SNAPSHOT_ENRICHMENT_ENABLE", True)):
            return candidate, diag
        md = snap if isinstance(snap, dict) else {}
        fam = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
        if isinstance(candidate, dict):
            fam = str(candidate.get("family") or candidate.get("strategy_mode") or "").upper()
        if fam not in {"PULLBACK", "MTF_PULLBACK", "BREAKOUT_RETEST", "BREAKOUT_CONTINUATION", "MEASURED_MOVE"}:
            return candidate, diag
        fs = _v672_candidate_fs(candidate)
        df5 = md.get("df_5m")
        if df5 is None or len(df5) < 52:
            diag["missing"].append("df_5m")
            STATS["v672_snapshot_enrichment_missing"] = int(STATS.get("v672_snapshot_enrichment_missing", 0) or 0) + 1
            return candidate, diag

        # Closed-bar evidence used across existing gates.
        lc = float(df5["close"].iloc[-2])
        pc = float(df5["close"].iloc[-3])
        op = float(df5["open"].iloc[-2])
        hi = float(df5["high"].iloc[-2])
        lo = float(df5["low"].iloc[-2])
        close_s = df5["close"].astype(float)
        e20s = close_s.ewm(span=20, adjust=False)
        e50s = close_s.ewm(span=50, adjust=False)
        e20 = float(e20s.mean().iloc[-2])
        e50 = float(e50s.mean().iloc[-2])
        atr_s = Indicators.atr(df5, int(CONFIG.get("ATR_PERIOD", 14)))
        atr = float(atr_s.iloc[-2]) if atr_s is not None else float("nan")
        bullish_close = bool(lc > op and lc >= pc)
        higher_low = bool(float(df5["low"].iloc[-2]) > float(df5["low"].iloc[-3]) >= float(df5["low"].iloc[-4]))
        try:
            slope_bars = max(5, int(CONFIG.get("V565_PULLBACK_SLOPE_BARS", 8)))
            closed_ema = e20s.mean().iloc[-(slope_bars + 1):-1]
            ema20_slope_up = bool(len(closed_ema) >= 2 and float(closed_ema.iloc[-1]) > float(closed_ema.iloc[0]) * (1.0 + float(CONFIG.get("V565_PULLBACK_SLOPE_MIN_REQUIRED_R", 0.0001))))
        except Exception:
            ema20_slope_up = False
        zone = _v672_num(fs.get("zone_ref", getattr(candidate, "zone_ref", None) if not isinstance(candidate, dict) else candidate.get("zone_ref")))
        reclaim = bool(zone is not None and pc < zone <= lc)
        body_ratio = abs(lc - op) / max(hi - lo, 1e-12)
        fs.setdefault("bullish_close_5m", bullish_close)
        fs.setdefault("higher_low_5m", higher_low)
        fs.setdefault("ema20_slope_up", ema20_slope_up)
        if zone is not None:
            fs.setdefault("zone_reclaim", reclaim)

        # HTF strength: fresh snapshot first, then the existing bounded cache lane.
        htf = _v672_num(fs.get("htf_strength", fs.get("htf_alignment")))
        if htf is None:
            htf = _v672_num(md.get("htf_strength", md.get("htf_alignment")))
        if htf is None:
            htf = _v672_num(_v453_htf_strength_from_snapshot(md))
            htf_source = "SNAPSHOT"
            if htf is None:
                try:
                    sym = str(getattr(candidate, "symbol", "") if not isinstance(candidate, dict) else candidate.get("symbol", ""))
                    rec_fn = globals().get("_v457_htf_strength_recovered")
                    if callable(rec_fn) and sym:
                        htf, htf_source, _age = rec_fn(sym, md, candidate)
                        htf = _v672_num(htf)
                except Exception:
                    htf = None
            if htf is not None:
                fs["htf_strength"] = htf
                fs["htf_alignment"] = htf
                diag["applied"].append(f"htf_strength:{htf_source}")
            else:
                diag["missing"].append("htf_strength")

        # Structure: reproduce the existing scanner formula from the same closed data.
        structure = _v672_num(fs.get("structure_score", fs.get("structure_confidence", fs.get("structure_quality", fs.get("structure")))))
        if structure is None:
            structure = _v672_num(md.get("structure_confidence", md.get("structure_quality", md.get("structure_score", md.get("structure")))))
        if structure is None:
            try:
                bos_ok, bos_strength = MicroStructure.micro_bos_confirm(df5)
                score = 0.0
                if bool(bos_ok):
                    score += 45.0 + min(25.0, float(bos_strength) * float(CONFIG.get("BOS_STRENGTH_SCORE_MULT", 5000.0)))
                if reclaim:
                    score += 20.0
                score += min(10.0, body_ratio * 10.0)
                structure = _v672_num(_clamp(score, 0.0, 100.0))
            except Exception:
                structure = None
            if structure is not None:
                fs["structure"] = structure
                fs["structure_score"] = structure
                fs["structure_confidence"] = structure
                fs["structure_quality"] = structure
                diag["applied"].append(f"structure:{structure:.2f}")
            else:
                diag["missing"].append("structure")

        # Retest: use the existing canonical recomputation helper on CLOSED bars.
        retest = _v672_num(fs.get("retest_quality_score", fs.get("retest_score", fs.get("retest_quality", fs.get("retest")))))
        if retest is None:
            retest = _v672_num(md.get("retest_quality_score", md.get("retest_quality", md.get("retest_score", md.get("retest")))))
        if retest is None:
            try:
                fn = globals().get("_v657_recompute_retest_quality")
                if callable(fn):
                    fresh_retest = fn(candidate, md)
                    if isinstance(fresh_retest, dict):
                        retest = _v672_num(fresh_retest.get("retest_quality_score", fresh_retest.get("retest_quality")))
                    else:
                        retest = _v672_num(fresh_retest)
            except Exception:
                retest = None
            if retest is not None:
                fs["retest_quality_score"] = retest
                fs["retest_score"] = retest
                fs["retest_quality"] = retest
                fs["retest"] = retest
                diag["applied"].append(f"retest:{retest:.2f}")
            else:
                diag["missing"].append("retest")

        # Volume: same derivation already used by V669 quality.
        vol = _v672_num(fs.get("volume_ratio", fs.get("vol_ratio")))
        if vol is None:
            vol = _v672_num(md.get("volume_ratio", md.get("vol_ratio")))
        if vol is None:
            try:
                vol_now = float(df5["volume"].iloc[-2])
                vol_base = float(df5["volume"].iloc[-22:-2].mean())
                vol = _v672_num(vol_now / max(vol_base, 1e-12))
            except Exception:
                vol = None
            if vol is not None:
                fs["volume_ratio"] = vol
                fs["vol_ratio"] = vol
                diag["applied"].append(f"volume:{vol:.4f}")
            else:
                diag["missing"].append("volume_ratio")

        # Relative strength: exact existing closed-bar calculator, no new fetch.
        rs = _v672_num(fs.get("rs_5m", fs.get("relative_strength", fs.get("rs"))))
        if rs is None:
            rs = _v672_num(md.get("rs_5m", md.get("relative_strength", md.get("rs"))))
        if rs is None:
            try:
                btc5 = md.get("df_btc_5m")
                lookback = int(CONFIG.get("V658_RS_SHORT_LOOKBACK", 6))
                rs = _v672_num(_v658_rs_value(df5, btc5, lookback))
            except Exception:
                rs = None
            if rs is not None:
                fs["rs_5m"] = rs
                _rs_points_fn = globals().get("_v702_rs_points_from_raw")
                _rs_points = _rs_points_fn(rs) if callable(_rs_points_fn) else None
                if _rs_points is not None:
                    fs["rs_score_val"] = _rs_points
                fs["relative_strength"] = rs
                diag["applied"].append(f"rs_5m:{rs:.6f}")
            else:
                diag["missing"].append("rs_5m")

        # Volume delta: same closed-bar bounded metric used by SignalBuilder.
        vol_delta = _v672_num(fs.get("vol_delta_score", md.get("vol_delta_score")))
        if vol_delta is None:
            try:
                v_last = float(df5["volume"].iloc[-2])
                v_prev = float(df5["volume"].iloc[-3])
                if math.isfinite(v_last) and math.isfinite(v_prev) and v_prev > 0:
                    vol_delta = _clamp((v_last / v_prev - 1.0) * 5.0, 0.0, 3.0)
            except Exception:
                vol_delta = None
        if vol_delta is not None:
            fs["vol_delta_score"] = vol_delta

        # Momentum: closed-bar RSI + ADX, matching the live builder's bounded scale.
        mom = _v672_num(fs.get("momentum_score_val", md.get("momentum_score_val")))
        if mom is None:
            try:
                rsi_series = Indicators.rsi(df5["close"], CONFIG["RSI_PERIOD"])
                adx_series = Indicators.adx(df5, CONFIG["ADX_PERIOD"])
                last_rsi = float(rsi_series.iloc[-2]) if rsi_series is not None else float("nan")
                ms = 0.0
                if 40.0 <= last_rsi <= 65.0:
                    ms += 4.0
                elif last_rsi > 65.0:
                    ms += 2.0
                elif last_rsi < 30.0:
                    ms += 3.0
                if adx_series is not None:
                    last_adx = float(adx_series.iloc[-2])
                    if last_adx >= float(CONFIG.get("ADX_BASE_THRESHOLD")):
                        ms += 3.0
                    elif last_adx >= float(CONFIG.get("ADX_SOFT_PENALTY")):
                        ms += 1.5
                mom = _clamp(ms, 0.0, 10.0)
            except Exception:
                mom = None
        if mom is not None:
            fs["momentum_score_val"] = mom
            diag["applied"].append(f"momentum:{mom:.2f}")

        # Chase: candidate entry vs validated zone is the canonical geometry.
        chase = _v672_num(fs.get("chase_atr", fs.get("chase")))
        if chase is None and zone is not None and math.isfinite(atr) and atr > 0:
            entry = _v672_num(getattr(candidate, "entry_ref", None) if not isinstance(candidate, dict) else candidate.get("entry_ref"))
            if entry is not None:
                chase = abs(entry - zone) / atr
        if chase is not None:
            fs["chase_atr"] = chase
            fs["chase"] = chase
            diag["applied"].append(f"chase:{chase:.4f}")
        else:
            diag["missing"].append("chase")

        # Preserve exact snapshot/candle provenance; never fabricate identity.
        snap_id = md.get("snapshot_id") or md.get("v669_snapshot_id") or fs.get("snapshot_id")
        if snap_id is not None:
            fs["v672_enriched_snapshot_id"] = snap_id
        fs["v672_enrichment_source"] = str(source)
        candidate2 = _v672_set_fs(candidate, fs)
        if diag["applied"]:
            STATS["v672_snapshot_enrichment_applied"] = int(STATS.get("v672_snapshot_enrichment_applied", 0) or 0) + 1
        if diag["missing"]:
            STATS["v672_snapshot_enrichment_failures"] = int(STATS.get("v672_snapshot_enrichment_failures", 0) or 0) + 1
        STATS["v672_last_enrichment"] = dict(diag)
        return candidate2, diag
    except Exception as exc:
        STATS["v672_snapshot_enrichment_failures"] = int(STATS.get("v672_snapshot_enrichment_failures", 0) or 0) + 1
        diag["errors"].append(f"{type(exc).__name__}:{exc}")
        STATS["v672_last_enrichment"] = dict(diag)
        return candidate, diag


