def _coherence_deep_freeze(value):
    """Recursively freeze mappings/sequences used by CycleSnapshot facts."""
    from types import MappingProxyType
    if isinstance(value, MappingProxyType):
        return value
    if isinstance(value, dict):
        return MappingProxyType({k: _coherence_deep_freeze(v) for k, v in value.items()})
    if isinstance(value, (list, tuple)):
        return tuple(_coherence_deep_freeze(v) for v in value)
    if isinstance(value, set):
        return frozenset(_coherence_deep_freeze(v) for v in value)
    return value


class CycleSnapshot(dict):
    """Deeply immutable canonical cycle facts after seal()."""
    __slots__ = ("_sealed",)
    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        self._sealed = False
    def seal(self):
        if not self._sealed:
            for k, v in list(self.items()):
                super().__setitem__(k, _coherence_deep_freeze(v))
            object.__setattr__(self, "_sealed", True)
        return self
    def _guard(self):
        if getattr(self, "_sealed", False):
            raise RuntimeError("cyclesnapshot.immutable_after_seal")
    def __setitem__(self, k, v): self._guard(); super().__setitem__(k, v)
    def __delitem__(self, k): self._guard(); super().__delitem__(k)
    def clear(self): self._guard(); super().clear()
    def pop(self, *a): self._guard(); return super().pop(*a)
    def popitem(self): self._guard(); return super().popitem()
    def setdefault(self, *a): self._guard(); return super().setdefault(*a)
    def update(self, *a, **k): self._guard(); return super().update(*a, **k)


class DerivedFactsCache:
    """Bounded derived-facts cache keyed by closed-candle timestamp."""
    def __init__(self, max_entries=512):
        self._d, self._max = {}, int(max_entries)
    @staticmethod
    def key(symbol, timeframe, last_closed_ts):
        return (str(symbol), str(timeframe), int(last_closed_ts or 0))
    def get(self, symbol, timeframe, last_closed_ts):
        return self._d.get(self.key(symbol, timeframe, last_closed_ts))
    def put(self, symbol, timeframe, last_closed_ts, facts):
        if len(self._d) >= self._max and self._d:
            self._d.pop(next(iter(self._d)), None)
        self._d[self.key(symbol, timeframe, last_closed_ts)] = dict(facts or {})
        return self._d[self.key(symbol, timeframe, last_closed_ts)]


class MarketSnapshotCache:
    """Bounded cache of per-TF frames, partitioned by their own closed candle."""
    def __init__(self, max_entries=1024):
        self._d, self._max = {}, int(max_entries)
    @staticmethod
    def key(symbol, timeframe, last_closed_ts):
        return (str(symbol), str(timeframe), int(last_closed_ts or 0))
    def get(self, symbol, timeframe, last_closed_ts):
        return self._d.get(self.key(symbol, timeframe, last_closed_ts))
    def put(self, symbol, timeframe, last_closed_ts, frame):
        if len(self._d) >= self._max and self._d:
            self._d.pop(next(iter(self._d)), None)
        self._d[self.key(symbol, timeframe, last_closed_ts)] = frame
        return frame


