def _coherence_closed_ts(frame):
    try:
        if frame is None or len(frame) < 2:
            return 0
        idx = frame.index[-2]
        if hasattr(idx, "timestamp"):
            return int(float(idx.timestamp()))
        return int(float(idx))
    except Exception:
        return 0


def canonical_structure_verdict(candidate=None, facts=None):
    """Canonical structural verdict; aliases resolve to the same closed-bar evidence."""
    f = dict(facts or getattr(candidate, "features_snapshot", None) or {})
    get = lambda *keys: next((f[k] for k in keys if k in f and f.get(k) is not None), None)
    ev = {
        "closed_candle_ts": get("closed_candle_ts", "candle_ts"),
        "zone": get("zone_ref") if get("zone_ref") is not None else getattr(candidate, "zone_ref", None),
        "reclaim": bool(get("reclaim", "zone_reclaim")),
        "higher_low": bool(get("higher_low", "higher_low_5m")),
        "bullish_close": bool(get("bullish_close", "bullish_close_5m")),
        "ema_slope": bool(get("ema_slope", "ema20_slope_up")),
        "chase_atr": get("chase_atr", "chase"),
        "family": str(get("family") or getattr(candidate, "family", "") or "").upper(),
    }
    if ev["closed_candle_ts"] is None:
        return {"verdict": "INSUFFICIENT_DATA", "evidence": ev}
    prim = sum(1 for k in ("reclaim", "higher_low", "bullish_close", "ema_slope") if ev[k])
    if prim >= 3:
        verdict = "RECOVERY_CONFIRMED"
    elif prim >= 2:
        verdict = "HEALTHY_PULLBACK"
    elif prim == 1:
        verdict = "STRUCTURE_UNCLEAR"
    else:
        verdict = "GENUINE_BREAKOUT_FAILURE"
    return {"verdict": verdict, "evidence": ev, "primary_count": prim}


def canonical_pullback_confirmations(facts=None):
    f = dict(facts or {})
    primary = [k for k in ("reclaim", "zone_reclaim", "higher_low", "higher_low_5m", "bullish_close", "bullish_close_5m", "ema_slope", "ema20_slope_up") if f.get(k)]
    # Collapse aliases to exactly four evidence atoms.
    atoms = {
        "reclaim": bool(f.get("reclaim", f.get("zone_reclaim", False))),
        "higher_low": bool(f.get("higher_low", f.get("higher_low_5m", False))),
        "bullish_close": bool(f.get("bullish_close", f.get("bullish_close_5m", False))),
        "ema_slope": bool(f.get("ema_slope", f.get("ema20_slope_up", False))),
    }
    primary_atoms = [k for k, v in atoms.items() if v]
    return {"primary": primary_atoms, "primary_count": len(primary_atoms),
            "support": {"shallow_pullback": bool(f.get("shallow_pullback", False)), "bos": bool(f.get("bos", f.get("bos_confirmed", False)))},
            "confirmed": len(primary_atoms) >= 2}


def canonical_economic_geometry(entry, sl, tp_levels, fee_rate, notional, exit_weights=None):
    """Canonical V666-compatible geometry calculator used for coherence auditing."""
    try:
        entry, sl = float(entry), float(sl)
        fee_rate, notional = float(fee_rate), float(notional)
        if not (math.isfinite(entry) and math.isfinite(sl) and entry > 0 and 0 < sl < entry and math.isfinite(notional) and notional > 0 and fee_rate >= 0):
            return {"ok": False, "reason": "geometry.invalid", "viable": False}
        tps = [float(x) for x in list(tp_levels or [])]
        if any(not math.isfinite(x) or x <= entry for x in tps):
            return {"ok": False, "reason": "geometry.invalid_targets", "viable": False}
        risk_usdt = (entry - sl) * (notional / entry)
        fee_cost = notional * fee_rate * 2.0
        weights = list(exit_weights) if exit_weights is not None else [1.0 / len(tps)] * len(tps) if tps else []
        if tps:
            if len(weights) != len(tps):
                return {"ok": False, "reason": "geometry.weight_length_mismatch", "viable": False}
            if any((not math.isfinite(float(w)) or float(w) < 0) for w in weights) or abs(sum(map(float, weights)) - 1.0) > 1e-6:
                return {"ok": False, "reason": "geometry.weight_sum_mismatch", "viable": False}
        out = {"ok": True, "entry": entry, "sl": sl, "notional": notional, "risk_usdt": risk_usdt, "fee_cost": fee_cost, "tps": []}
        for tp in tps:
            gross = (tp-entry)/(entry-sl)
            out["tps"].append({"tp":tp, "gross_rr":gross, "net_rr":gross-(fee_cost/max(risk_usdt,1e-12))})
        if out["tps"]:
            out["net_rr_tp1"] = out["tps"][0]["net_rr"]
            out["tp1_to_fee_ratio"] = ((out["tps"][0]["tp"]-entry)*(notional/entry))/max(fee_cost,1e-12)
            out["net_rr_overall"] = sum(t["net_rr"]*float(w) for t,w in zip(out["tps"],weights))
            out["viable"] = bool(
                out["net_rr_tp1"] >= float(CONFIG.get("MIN_NET_RR_TP1",0.8)) and
                out["tp1_to_fee_ratio"] >= float(CONFIG.get("MIN_TP1_TO_FEE_RATIO",2.5)) and
                out["net_rr_overall"] >= float(CONFIG.get("MIN_NET_RR_OVERALL",1.2))
            )
        else:
            out.update({"net_rr_tp1":None,"tp1_to_fee_ratio":None,"net_rr_overall":None,"viable":False})
        return out
    except Exception as exc:
        return {"ok": False, "reason": f"geometry.exception:{type(exc).__name__}", "viable": False}


def _coherence_prepare_cycle_snapshot(symbol, snap):
    """Build one immutable facts snapshot beside the exact engine snapshot."""
    md = dict(snap or {})
    tf_map = (("df_4h","4h"),("df_1h","1h"),("df_15m","15m"),("df_5m","5m"))
    closed = {}
    frame_meta = {}
    for key, tf in tf_map:
        df = md.get(key)
        ts = _coherence_closed_ts(df)
        closed[tf] = ts
        if df is not None and ts:
            MARKET_SNAPSHOT_CACHE.put(symbol, tf, ts, df.copy(deep=True) if hasattr(df,"copy") else df)
            frame_meta[tf] = {"closed_candle_ts": ts, "rows": len(df)}
    facts5 = {}
    try:
        df5 = md.get("df_5m")
        if df5 is not None and len(df5) >= 25:
            lc, pc = float(df5["close"].iloc[-2]), float(df5["close"].iloc[-3])
            op, hi, lo = float(df5["open"].iloc[-2]), float(df5["high"].iloc[-2]), float(df5["low"].iloc[-2])
            e20 = df5["close"].ewm(span=20, adjust=False).mean()
            facts5 = {
                "closed_candle_ts": closed["5m"], "close": lc, "prev_close": pc,
                "open": op, "high": hi, "low": lo,
                "bullish_close": bool(lc > op and lc >= pc),
                "higher_low": bool(lo > float(df5["low"].iloc[-3]) >= float(df5["low"].iloc[-4])),
                "ema20_slope_up": bool(float(e20.iloc[-2]) > float(e20.iloc[-9])*1.0001),
                "zone_reclaim": False,
            }
            if md.get("zone_ref") is not None:
                z=float(md["zone_ref"]); facts5["zone_ref"]=z; facts5["zone_reclaim"]=bool(pc < z <= lc)
            DERIVED_FACTS_CACHE.put(symbol, "5m", closed["5m"], facts5)
    except Exception:
        facts5 = {}
    payload = {
        "snapshot_id": hashlib.sha256(f"{symbol}|{closed.get('5m',0)}|{closed.get('15m',0)}|{closed.get('1h',0)}|{closed.get('4h',0)}".encode()).hexdigest()[:24],
        "cycle_id": int(STATS.get("v516_cycle_id", 0) or 0), "symbol": str(symbol),
        "created_at_monotonic": float(MONO_NOW()), "wall_ts": float(WALL_NOW()),
        "last_closed_candle_ts": closed, "frame_meta": frame_meta,
        "derived": {"5m": facts5},
        "provenance": "V673_COHERENCE_MIRROR_OF_EXACT_GLOBAL_SNAPSHOT",
        "completeness_mask": {k: bool(v) for k,v in closed.items()},
    }
    return CycleSnapshot(payload).seal()


WATCHDOG_OP_CLASSES = frozenset({
    "READ_ONLY_MARKET", "MARKET_DISCOVERY", "RECONCILIATION", "ENTRY_CRITICAL", "EXIT_CRITICAL", "TELEMETRY",
})
WATCHDOG_CRITICAL_OPS = frozenset({
    "create_market_buy", "create_market_sell", "cancel_order", "set_stop_loss", "move_stop_loss", "fetch_balance_truth", "reconcile_position",
})
WATCHDOG_READONLY_OPS = frozenset({"fetch_ohlcv", "fetch_ticker", "fetch_tickers", "fetch_order_book_cached"})


def watchdog_classify_op(op_name):
    op = str(op_name or "").strip()
    low = op.lower()
    if low in WATCHDOG_CRITICAL_OPS:
        return "EXIT_CRITICAL" if any(x in low for x in ("sell", "stop", "cancel")) else "ENTRY_CRITICAL"
    if low in WATCHDOG_READONLY_OPS:
        return "READ_ONLY_MARKET"
    if any(x in low for x in ("discover", "universe")):
        return "MARKET_DISCOVERY"
    if any(x in low for x in ("reconcile", "open_orders", "recover")):
        return "RECONCILIATION"
    if any(x in low for x in ("telegram", "heartbeat", "telemetry", "trace")):
        return "TELEMETRY"
    return "ENTRY_CRITICAL"  # UNKNOWN => CRITICAL


