def should_trigger_full_opportunity_scan(symbol, tf_entry, closed_candle_ts):
    """Authoritative deep-scan eligibility helper; same candle is deduped."""
    try:
        ts = int(closed_candle_ts or 0)
    except Exception:
        ts = 0
    if ts <= 0:
        STATS["coherence_scan_unverifiable"] = int(STATS.get("coherence_scan_unverifiable",0) or 0)+1
        return False
    key = (str(symbol), str(tf_entry), ts)
    if _COHERENCE_SCAN_STATE.get(str(symbol)) == key:
        STATS["coherence_scan_dedup_hits"] = int(STATS.get("coherence_scan_dedup_hits",0) or 0)+1
        return False
    _COHERENCE_SCAN_STATE[str(symbol)] = key
    STATS["coherence_scan_new_closed_candle"] = int(STATS.get("coherence_scan_new_closed_candle",0) or 0)+1
    return True


