def _v674_current_cycle_starvation_truth(window_sec: Optional[float] = None) -> Dict[str, Any]:
    try:
        cid = int(globals().get("_V517_ACTIVE_CYCLE_ID") or STATS.get("v669_last_cycle_id", 0) or 0)
        current = V669RejectionLedger.current_cycle(cid)
        counts = V669RejectionLedger.counts(current)
        # Hard safety/system always wins. Otherwise use actual current-cycle
        # rejection volume. Priority is semantic, not historical noise.
        for bucket in V669RejectionLedger.PRIORITY:
            if int(counts.get(bucket, 0) or 0) > 0:
                return {"mode": bucket, "source": "V674_CANONICAL_CURRENT_CYCLE",
                        "cycle_id": cid, "counts": counts, "root": bucket,
                        "current_cycle_age": float(STATS.get("v669_current_cycle_age", 0.0) or 0.0)}
        hist = V669RejectionLedger.recent(float(window_sec if window_sec is not None else 720.0))
        hc = V669RejectionLedger.counts(hist)
        for bucket in V669RejectionLedger.PRIORITY:
            if int(hc.get(bucket, 0) or 0) > 0:
                return {"mode": bucket, "source": "V674_CANONICAL_WINDOW",
                        "cycle_id": cid, "counts": hc, "root": bucket}
        return {"mode": "NONE", "source": "V674_CANONICAL_CURRENT_CYCLE", "cycle_id": cid,
                "counts": counts, "root": "NONE"}
    except Exception as exc:
        return {"mode": "SYSTEM", "source": "V674_CANONICAL_ERROR", "root": "SYSTEM", "error": type(exc).__name__}

