def _v674_coherence_runtime_probe() -> Dict[str, Any]:
    checks: Dict[str, Any] = {}
    try:
        checks["watchdog_unknown_is_critical"] = watchdog_classify_op("future_unknown_operation") == "ENTRY_CRITICAL"
        checks["watchdog_readonly_class"] = watchdog_classify_op("fetch_ohlcv") == "READ_ONLY_MARKET"
        checks["htf_reason_bucket"] = V669RejectionLedger._bucket("structural", "htf.core_not_aligned", "") == "HTF"
        checks["watchdog_reason_bucket"] = V669RejectionLedger._bucket("structural", "safety.watchdog", "") == "SYSTEM"
        q = canonical_pullback_confirmations({"reclaim": True, "higher_low": True, "bullish_close": False, "ema_slope": False})
        checks["pullback_quorum"] = bool(q.get("confirmed")) and int(q.get("primary_count", 0)) == 2
        sv = canonical_structure_verdict(type("C", (), {"family":"PULLBACK", "zone_ref":100.0})(), {
            "closed_candle_ts": 1, "reclaim": True, "higher_low": True,
            "bullish_close": False, "ema_slope": False, "zone_ref":100.0,
            "chase_atr":0.2, "family":"PULLBACK"
        })
        checks["structure_verdict"] = sv.get("verdict") == "HEALTHY_PULLBACK"
        geo = canonical_economic_geometry(100.0, 99.0, [102.0,104.0], 0.001, 75.0, [0.5,0.5])
        checks["economic_geometry"] = bool(geo.get("ok")) and math.isfinite(float(geo.get("net_rr_tp1", -1)))
        snap = CycleSnapshot({"nested":{"x":[1,{"y":2}]}}).seal()
        deep_immutable = False
        try:
            snap["nested"]["x"] = (3,)
        except Exception:
            deep_immutable = True
        checks["snapshot_deep_immutable"] = deep_immutable
        c = type("C", (), {"symbol":"V674/USDT", "family":"PULLBACK"})()
        lc = CandidateLifecycle("V674-TEST", 674, "V674/USDT", "PULLBACK")
        lc.transition("HARD_VALID", "probe"); lc.transition("FACT_COMPLETE", "probe"); lc.transition("RANKED", "probe"); lc.transition("SELECTED", "probe")
        checks["lifecycle"] = lc.state == "SELECTED"
        return checks
    except Exception as exc:
        checks["exception"] = f"{type(exc).__name__}:{exc}"
        return checks

