# v4.5.99-V675 FINAL — QUALITY-PRESERVING LIVE FUNNEL THROUGHPUT CLOSURE
# -----------------------------------------------------------------------------
# Evidence-driven closure for the LIVE logs:
#   G was very large while E/Q/S frequently stayed at zero; selected PULLBACK
#   candidates were often rejected downstream, while the same arbitration cycle
#   already contained additional ranked/prequalified candidates.
#
# Objective:
#   Increase real LIVE opportunities WITHOUT lowering any quality/safety gate.
#
# Method:
#   1) Reuse the exact prequalified pool already captured at GlobalArbiter.select.
#   2) Feed bounded, quality-ranked reserve candidates into the EXISTING
#      execution_reserve path. No new market fetch and no new execution authority.
#   3) Keep only candidates at/above the SAME effective global floor.
#   4) Prefer family diversity and candidates with less repeated downstream
#      rejection pressure; this is ranking preference only.
#   5) Every reserve candidate still enters the normal SignalBuilder/V587,
#      PreSend, Balance/TruthSeal, Exposure, SL, liquidity and execution gates.
#   6) Tighten market-data freshness within existing bounded concurrency limits.
#
# Explicitly NOT changed:
#   HTF floors, structure gates, fee/RR floors, score hard floors, balance,
#   exposure, liquidity, SL/TP, execution authority, LONG_ONLY/SPOT, or fail-close.
# =============================================================================
V675_FINAL_IDENTITY = "4.5.99-V675-HYBRID-FINAL-ALL-IN-ONE-QUALITY-PRESERVING-LIVE-CLOSURE"
V674_FINAL_IDENTITY = V675_FINAL_IDENTITY
CONFIG.update({
    "V675_FINAL_ENABLE": True,
    "V675_QUALITY_RESERVE_ENABLE": True,
    "V675_QUALITY_RESERVE_MAX": 8,
    "V675_QUALITY_RESERVE_MAX_SAME_FAMILY": 2,
    "V675_QUALITY_RESERVE_SCORE_GAP": 0.0,  # never below the existing effective floor
    "V675_QUALITY_RESERVE_DIVERSITY_ENABLE": True,
    "V675_QUALITY_RESERVE_SKIP_REPEATED_SYMBOL": True,
    "V675_MARKET_DATA_CONCURRENCY": 20,
    "V675_MARKET_DATA_CYCLE_BUDGET_SEC": 75.0,
})
STATS.setdefault("v675_quality_reserve_added", 0)
STATS.setdefault("v675_quality_reserve_last", [])
STATS.setdefault("v675_quality_reserve_skipped", 0)
STATS.setdefault("v675_quality_reserve_errors", 0)


def _v675_candidate_key(ranked):
    try:
        c = getattr(ranked, "candidate", ranked)
        return (
            str(getattr(c, "symbol", "") or ""),
            _v668_norm_family(c) if callable(globals().get("_v668_norm_family")) else str(getattr(c, "family", "") or "").upper(),
        )
    except Exception:
        return ("", "")


def _v675_quality_reserve_candidates(base_rows):
    """Return only already-prequalified candidates at the existing global floor."""
    if not bool(CONFIG.get("V675_FINAL_ENABLE", True)) or not bool(CONFIG.get("V675_QUALITY_RESERVE_ENABLE", True)):
        return list(base_rows or [])
    try:
        pool = list(globals().get("_V668_LAST_ARB_POOL") or [])
        if not pool:
            return list(base_rows or [])
        try:
            floor = float(GlobalOpportunityArbiter._effective_min_score())
        except Exception:
            floor = float(STATS.get("v45_global_min_score", 0.50) or 0.50)
        gap = max(0.0, float(CONFIG.get("V675_QUALITY_RESERVE_SCORE_GAP", 0.0)))
        threshold = floor + gap
        selected_keys = set()
        selected_symbols = set()
        for rr in list(base_rows or []):
            k = _v675_candidate_key(rr)
            selected_keys.add(k)
            sym = k[0]
            if sym:
                selected_symbols.add(sym)

        ranked = []
        seen = set()
        max_same = max(1, int(CONFIG.get("V675_QUALITY_RESERVE_MAX_SAME_FAMILY", 2)))
        for rr in pool:
            k = _v675_candidate_key(rr)
            sym, fam = k
            if not sym or k in seen:
                continue
            seen.add(k)
            if sym in selected_symbols and bool(CONFIG.get("V675_QUALITY_RESERVE_SKIP_REPEATED_SYMBOL", True)):
                continue
            try:
                score = float(GlobalOpportunityArbiter._candidate_score(rr))
            except Exception:
                continue
            if not math.isfinite(score) or score + 1e-12 < threshold:
                continue
            # The candidate is coming from the exact ranked/prequalified pool
            # captured before the selector. Never manufacture a new candidate.
            feedback = 0.0
            try:
                c = getattr(rr, "candidate", rr)
                feedback = float(_v668_feedback_penalty(c)) if callable(globals().get("_v668_feedback_penalty")) else 0.0
            except Exception:
                feedback = 0.0
            # Deterministic family-diverse ordering. A repeated-downstream family
            # is not forbidden; it is simply lower priority than an equally valid
            # alternative family.
            fam_bias = 0.0
            if bool(CONFIG.get("V675_QUALITY_RESERVE_DIVERSITY_ENABLE", True)):
                fam_bias = 0.003 if all(_v675_candidate_key(x)[1] != fam for x in base_rows or []) else 0.0
            ranked.append((score + fam_bias - feedback, score, fam, sym, rr))

        ranked.sort(key=lambda x: (-x[0], -x[1], x[2], x[3]))
        family_counts = defaultdict(int)
        out = list(base_rows or [])
        additions = []
        cap = max(0, int(CONFIG.get("V675_QUALITY_RESERVE_MAX", 8)))
        for _, _, fam, sym, rr in ranked:
            if len(additions) >= cap:
                break
            if family_counts[fam] >= max_same:
                STATS["v675_quality_reserve_skipped"] = int(STATS.get("v675_quality_reserve_skipped", 0) or 0) + 1
                continue
            additions.append(rr)
            family_counts[fam] += 1
        if additions:
            STATS["v675_quality_reserve_added"] = int(STATS.get("v675_quality_reserve_added", 0) or 0) + len(additions)
            STATS["v675_quality_reserve_last"] = [
                {"symbol": _v675_candidate_key(x)[0], "family": _v675_candidate_key(x)[1],
                 "score": float(GlobalOpportunityArbiter._candidate_score(x))}
                for x in additions
            ]
            return out + additions
        return out
    except Exception as exc:
        STATS["v675_quality_reserve_errors"] = int(STATS.get("v675_quality_reserve_errors", 0) or 0) + 1
        logger.debug("[V675-QUALITY-RESERVE] suppressed: %s", exc)
        return list(base_rows or [])


# Preserve the existing reserve provider and append only same-cycle ranked/
# prequalified quality candidates. The provider remains a pure selector helper;
# actual execution is unchanged.
try:
    _v675_prev_execution_reserve = GlobalOpportunityArbiter.execution_reserve
    def _v675_execution_reserve(cls, *args, **kwargs):
        base = _v675_prev_execution_reserve.__func__(cls, *args, **kwargs) if isinstance(_v675_prev_execution_reserve, classmethod) else _v675_prev_execution_reserve(*args, **kwargs)
        return _v675_quality_reserve_candidates(base)
    GlobalOpportunityArbiter.execution_reserve = classmethod(_v675_execution_reserve)
    STATS["v675_quality_reserve_wired"] = True
except Exception as _v675_reserve_exc:
    STATS["v675_quality_reserve_wired"] = False
    STATS["v675_quality_reserve_errors"] = int(STATS.get("v675_quality_reserve_errors", 0) or 0) + 1
    logger.critical("[V675] quality reserve wiring failed: %s", _v675_reserve_exc)

