def _v675_live_funnel_self_test():
    checks = {}
    try:
        checks["enabled"] = bool(CONFIG.get("V675_FINAL_ENABLE", True))
        checks["quality_reserve_enabled"] = bool(CONFIG.get("V675_QUALITY_RESERVE_ENABLE", True))
        checks["floor_not_lowered"] = float(CONFIG.get("V675_QUALITY_RESERVE_SCORE_GAP", 0.0)) >= 0.0
        checks["reserve_cap_bounded"] = 0 <= int(CONFIG.get("V675_QUALITY_RESERVE_MAX", 8)) <= 16
        checks["same_family_cap_bounded"] = 1 <= int(CONFIG.get("V675_QUALITY_RESERVE_MAX_SAME_FAMILY", 2)) <= 4
        checks["scanner_concurrency_bounded"] = 8 <= int(CONFIG.get("V650_MARKET_DATA_CONCURRENCY", 20)) <= 24
        checks["scanner_budget_bounded"] = 45.0 <= float(CONFIG.get("V650_MARKET_DATA_CYCLE_BUDGET_SEC", 75.0)) <= 120.0
        checks["execution_reserve_callable"] = callable(getattr(GlobalOpportunityArbiter, "execution_reserve", None))
        checks["builder_authority_callable"] = callable(getattr(SignalBuilder, "build_and_route", None))
        checks["long_only_spot"] = bool(CONFIG.get("LONG_ONLY", True)) and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT" and not bool(CONFIG.get("ALLOW_SHORT", False))
        checks["fee_floor"] = float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5)) >= 2.5
        checks["rr_tp1_floor"] = float(CONFIG.get("MIN_NET_RR_TP1", 0.8)) >= 0.8
        checks["rr_overall_floor"] = float(CONFIG.get("MIN_NET_RR_OVERALL", 1.2)) >= 1.2
        # Synthetic ranked objects verify that the reserve filter cannot add a
        # candidate below the existing global floor. No exchange or order call.
        class _DummyC:
            def __init__(self, s, f): self.symbol=s; self.family=f; self.strategy_mode=f
        class _DummyR:
            def __init__(self, s, f, score): self.candidate=_DummyC(s,f); self._score=score
        old_pool = globals().get("_V668_LAST_ARB_POOL", [])
        old_eff = getattr(GlobalOpportunityArbiter, "_effective_min_score", None)
        old_score = getattr(GlobalOpportunityArbiter, "_candidate_score", None)
        try:
            globals()["_V668_LAST_ARB_POOL"] = [_DummyR("A/USDT","PULLBACK",0.70), _DummyR("B/USDT","LIQUIDITY_SWEEP_REVERSAL",0.49)]
            GlobalOpportunityArbiter._effective_min_score = staticmethod(lambda: 0.50)
            GlobalOpportunityArbiter._candidate_score = staticmethod(lambda rr: rr._score)
            base = [_DummyR("X/USDT","PULLBACK",0.60)]
            out = _v675_quality_reserve_candidates(base)
            syms = [str(getattr(getattr(x,"candidate",x),"symbol", "")) for x in out]
            checks["below_floor_excluded"] = "B/USDT" not in syms
            checks["above_floor_added"] = "A/USDT" in syms
        finally:
            globals()["_V668_LAST_ARB_POOL"] = old_pool
            if old_eff is not None: GlobalOpportunityArbiter._effective_min_score = old_eff
            if old_score is not None: GlobalOpportunityArbiter._candidate_score = old_score
        return checks
    except Exception as exc:
        checks["exception"] = f"{type(exc).__name__}:{exc}"
        return checks

