# =============================================================================
# V677 FINAL — FUNNEL THROUGHPUT / STARVATION / SNAPSHOT-COHERENCE CLOSURE
# -----------------------------------------------------------------------------
# Final additive closure over V676. The objective is to remove code-level
# throughput bottlenecks without weakening any hard eligibility or execution
# authority.
#
# Guarantees:
#   * SAME canonical market-data snapshot and existing bounded scanner.
#   * SAME effective score / HTF / structure / liquidity / fee / RR / SL floors.
#   * SAME SignalBuilder -> PreSend -> Balance/TruthSeal -> Exposure ->
#     Liquidity -> SL/TP -> Execution authority.
#   * Reserve/alternate candidates come ONLY from the already ranked,
#     prequalified pool. No new exchange read and no alternate order path.
#   * Starvation labels are derived from the current window, while an exact
#     downstream builder blocker is allowed to dominate only after that stage
#     was actually reached in the current cycle.
#   * Current-cycle counters are reset before global ranking and are never
#     inferred from stale cumulative telemetry.
# =============================================================================
V677_FINAL_IDENTITY = "4.5.99-V677-FINAL-THROUGHPUT-STARVATION-COHERENCE-CLOSURE"
CONFIG.update({
    "V677_FINAL_ENABLE": True,
    "V677_FINAL_STARVATION_TRUTH_ENABLE": True,
    "V677_RESERVE_MAX": 12,
    "V677_RESERVE_MAX_SAME_FAMILY": 2,
    "V677_RESERVE_SKIP_REPEATED_SYMBOL": True,
    # Keep the proven bounded transport profile from V676.
    "V650_MARKET_DATA_CONCURRENCY": 16,
    "V650_MARKET_DATA_CYCLE_BUDGET_SEC": 90.0,
    # The execution handoff is already bounded by the existing refill/attempt
    # controls; keep those controls at their validated ceilings.
    "V453_OPPORTUNITY_REFILL_MAX_ATTEMPTS": max(
        14, int(CONFIG.get("V453_OPPORTUNITY_REFILL_MAX_ATTEMPTS", 14) or 14)
    ),
    "V535_MAX_TOTAL_EXECUTION_ATTEMPTS_PER_CYCLE": max(
        16, int(CONFIG.get("V535_MAX_TOTAL_EXECUTION_ATTEMPTS_PER_CYCLE", 16) or 16)
    ),
})


def _v677_family_of_row(row):
    try:
        c = getattr(row, "candidate", row)
        if callable(globals().get("_v668_norm_family")):
            return str(_v668_norm_family(c) or "UNKNOWN").upper()
        return str(getattr(c, "family", "UNKNOWN") or "UNKNOWN").upper()
    except Exception:
        return "UNKNOWN"


def _v677_row_key(row):
    try:
        c = getattr(row, "candidate", row)
        return (str(getattr(c, "symbol", "") or ""), _v677_family_of_row(row))
    except Exception:
        return ("", "UNKNOWN")


def _v677_quality_reserve_candidates(base_rows):
    """Expand only from the captured ranked/prequalified pool, at the SAME floor."""
    base = list(base_rows or [])
    if not bool(CONFIG.get("V677_FINAL_ENABLE", True)):
        return base
    try:
        pool = list(globals().get("_V668_LAST_ARB_POOL") or [])
        if not pool:
            return base
        try:
            floor = float(GlobalOpportunityArbiter._effective_min_score())
        except Exception:
            floor = float(STATS.get("v45_global_min_score", 0.50) or 0.50)
        if not math.isfinite(floor):
            return base
        threshold = floor  # explicitly no floor lowering

        existing_symbols = { _v677_row_key(x)[0] for x in base if _v677_row_key(x)[0] }
        existing_pairs = { _v677_row_key(x) for x in base }
        fam_counts = defaultdict(int)
        for x in base:
            fam_counts[_v677_family_of_row(x)] += 1

        candidates = []
        seen = set()
        active_cycle = int(globals().get("_V517_ACTIVE_CYCLE_ID", 0) or 0)
        for rr in pool:
            key = _v677_row_key(rr)
            try:
                c0 = getattr(rr, "candidate", rr)
                origin0 = dict(getattr(c0, "v669_origin_context", None) or {})
                if origin0 and (active_cycle <= 0 or int(origin0.get("cycle_id") or 0) != active_cycle):
                    STATS["v702_route_provenance_pruned"] = int(STATS.get("v702_route_provenance_pruned", 0) or 0) + 1
                    continue
            except Exception:
                pass
            sym, fam = key
            if not sym or key in seen or key in existing_pairs:
                continue
            seen.add(key)
            if sym in existing_symbols and bool(CONFIG.get("V677_RESERVE_SKIP_REPEATED_SYMBOL", True)):
                continue
            try:
                score = float(GlobalOpportunityArbiter._candidate_score(rr))
            except Exception:
                continue
            if not math.isfinite(score) or score + 1e-12 < threshold:
                continue
            # Diversity is a deterministic ordering preference only.
            diversity_bonus = 0.002 if fam_counts[fam] == 0 else 0.0
            try:
                c = getattr(rr, "candidate", rr)
                feedback = float(_v668_feedback_penalty(c)) if callable(globals().get("_v668_feedback_penalty")) else 0.0
            except Exception:
                feedback = 0.0
            if not math.isfinite(feedback):
                feedback = 0.0
            candidates.append((score + diversity_bonus - feedback, score, fam, sym, rr))

        candidates.sort(key=lambda x: (-x[0], -x[1], x[2], x[3]))
        cap = max(0, min(16, int(CONFIG.get("V677_RESERVE_MAX", 12))))
        max_same = max(1, min(4, int(CONFIG.get("V677_RESERVE_MAX_SAME_FAMILY", 2))))
        additions = []
        for _, score, fam, sym, rr in candidates:
            if len(additions) >= cap:
                break
            if fam_counts[fam] >= max_same:
                continue
            additions.append(rr)
            fam_counts[fam] += 1
        if additions:
            STATS["v677_quality_reserve_added"] = int(STATS.get("v677_quality_reserve_added", 0) or 0) + len(additions)
            STATS["v677_quality_reserve_last"] = [
                {"symbol": _v677_row_key(x)[0], "family": _v677_row_key(x)[1],
                 "score": float(GlobalOpportunityArbiter._candidate_score(x))}
                for x in additions
            ]
        return base + additions
    except Exception as exc:
        STATS["v677_quality_reserve_errors"] = int(STATS.get("v677_quality_reserve_errors", 0) or 0) + 1
        logger.debug("[V677-QUALITY-RESERVE] suppressed: %s", exc)
        return base


# V677-A: one final reserve provider. It supersedes V675 only at the selector
# helper layer; the execution path below remains untouched.
try:
    GlobalOpportunityArbiter.execution_reserve = classmethod(
        lambda cls, *args, **kwargs: _v677_quality_reserve_candidates(
            (_v675_prev_execution_reserve.__func__(cls, *args, **kwargs)
             if isinstance(_v675_prev_execution_reserve, classmethod)
             else _v675_prev_execution_reserve(*args, **kwargs))
        )
    )
    STATS["v677_quality_reserve_wired"] = True
except Exception as _v677_reserve_install_exc:
    STATS["v677_quality_reserve_wired"] = False
    logger.critical("[V677] reserve provider install failed: %s", _v677_reserve_install_exc)


# V677-B: use the truth helper in the actual starvation classifier. This is
# telemetry-only: when PRE/SEL was reached, existing exact downstream blockers
# keep priority; HTF truth wins the zero-prequal upstream case.
try:
    _v677_prev_starvation_classify = V453StarvationClassifier.classify

    def _v677_truthful_classify(cls, *args, **kwargs):
        try:
            current = _v677_prev_starvation_classify.__func__(cls, *args, **kwargs) if isinstance(_v677_prev_starvation_classify, classmethod) else _v677_prev_starvation_classify(*args, **kwargs)
        except Exception:
            current = "NONE"
        if not bool(CONFIG.get("V677_FINAL_STARVATION_TRUTH_ENABLE", True)):
            return current
        try:
            diag = V453StarvationClassifier.window_diagnostics()
            generated = int(diag.get("generated_delta", 0) or 0)
            pre = int(diag.get("prequal_pass_delta", 0) or 0)
            sel = int(diag.get("selected_delta", 0) or 0)
            # Only override a generic/stale upstream label. If the current cycle
            # reached PRE/SEL, the inherited classifier has richer downstream truth.
            if generated > 0 and pre == 0 and sel == 0:
                htf = int(diag.get("reject_htf_delta", 0) or 0)
                liq = int(diag.get("reject_liquidity_delta", 0) or 0)
                struct = int(diag.get("reject_structure_delta", 0) or 0)
                score = int(diag.get("reject_score_delta", 0) or 0)
                if htf > 0 and htf >= max(liq, struct, score, 1):
                    return "HTF"
            return current
        except Exception:
            return current

    V453StarvationClassifier.classify = classmethod(_v677_truthful_classify)
    STATS["v677_starvation_truth_wired"] = True
except Exception as _v677_starv_install_exc:
    STATS["v677_starvation_truth_wired"] = False
    logger.critical("[V677] starvation truth install failed: %s", _v677_starv_install_exc)


# V677-C: remove avoidable work duplication from the existing handoff pool.
# The helper is used as a stable, deterministic finalizer by callers that already
# built the pool; it performs no exchange/network access.
def _v677_dedupe_attempt_pool(rows):
    out = []
    seen_symbols = set()
    seen_pairs = set()
    for row in list(rows or []):
        key = _v677_row_key(row)
        sym, fam = key
        if not sym or sym in seen_symbols:
            continue
        if key in seen_pairs:
            continue
        seen_pairs.add(key)
        seen_symbols.add(sym)
        out.append(row)
    return out


# V677-D: final release identity + invariant self-test.
def _v677_final_self_test():
    checks = {}
    try:
        checks["enabled"] = bool(CONFIG.get("V677_FINAL_ENABLE", True))
        checks["reserve_wired"] = bool(STATS.get("v677_quality_reserve_wired", False))
        checks["starvation_truth_wired"] = bool(STATS.get("v677_starvation_truth_wired", False))
        checks["long_only_spot"] = (
            bool(CONFIG.get("LONG_ONLY", True)) and
            str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT" and
            not bool(CONFIG.get("ALLOW_SHORT", False)) and
            not bool(CONFIG.get("ENABLE_FUTURES", False))
        )
        checks["fee_floor"] = float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5)) >= 2.5
        checks["rr_tp1_floor"] = float(CONFIG.get("MIN_NET_RR_TP1", 0.8)) >= 0.8
        checks["rr_overall_floor"] = float(CONFIG.get("MIN_NET_RR_OVERALL", 1.2)) >= 1.2
        checks["scanner_profile"] = (
            int(CONFIG.get("V650_MARKET_DATA_CONCURRENCY", 0)) == 16 and
            abs(float(CONFIG.get("V650_MARKET_DATA_CYCLE_BUDGET_SEC", 0.0)) - 90.0) <= 1e-9
        )
        checks["builder_authority"] = callable(getattr(SignalBuilder, "build_and_route", None))
        checks["presend_authority"] = callable(getattr(PreSendGate, "evaluate", None))
        checks["runtime_cycle_helpers"] = callable(globals().get("_v681_runtime_cycle_begin")) and callable(globals().get("_v681_runtime_cycle_sync"))
        checks["runtime_snapshot_truth_hook"] = isinstance(Telemetry.__dict__.get("snapshot"), staticmethod)
        checks["reserve_cap"] = 0 <= int(CONFIG.get("V677_RESERVE_MAX", 12)) <= 16
        checks["attempt_cap"] = 1 <= int(CONFIG.get("V535_MAX_TOTAL_EXECUTION_ATTEMPTS_PER_CYCLE", 16)) <= 20
        class _C:
            def __init__(self, s, f): self.symbol=s; self.family=f; self.strategy_mode=f
        class _R:
            def __init__(self, s, f, score): self.candidate=_C(s,f); self.score=score
        old_pool = globals().get("_V668_LAST_ARB_POOL", [])
        old_score = getattr(GlobalOpportunityArbiter, "_candidate_score", None)
        old_eff = getattr(GlobalOpportunityArbiter, "_effective_min_score", None)
        try:
            globals()["_V668_LAST_ARB_POOL"] = [_R("GOOD/USDT","PULLBACK",0.70), _R("BAD/USDT","PULLBACK",0.49)]
            GlobalOpportunityArbiter._candidate_score = staticmethod(lambda rr: float(rr.score))
            GlobalOpportunityArbiter._effective_min_score = staticmethod(lambda: 0.50)
            out = _v677_quality_reserve_candidates([_R("BASE/USDT","PULLBACK",0.60)])
            syms = [_v677_row_key(x)[0] for x in out]
            checks["below_floor_excluded"] = "BAD/USDT" not in syms
            checks["same_floor_candidate_added"] = "GOOD/USDT" in syms
        finally:
            globals()["_V668_LAST_ARB_POOL"] = old_pool
            if old_score is not None: GlobalOpportunityArbiter._candidate_score = old_score
            if old_eff is not None: GlobalOpportunityArbiter._effective_min_score = old_eff
        return checks
    except Exception as exc:
        checks["exception"] = f"{type(exc).__name__}:{exc}"
        return checks


