def _v679_arm_runtime_health() -> None:
    """Start the LIVE watchdog with a clean runtime window after import-time tests."""
    try:
        if not bool(CONFIG.get("V679_BOOT_WATCHDOG_SANITIZE_ENABLE", True)):
            return
        wd = ExchangeWatchdog
        prior = len(getattr(wd, "_errors", ()) or ())
        wd._errors.clear()
        if hasattr(wd, "_readonly_errors"):
            try:
                wd._readonly_errors = 0
            except Exception:
                pass
        wd._tripped_until = 0.0
        wd._last_reason = ""
        try:
            wd._last_reason_detail = {}
        except Exception:
            pass
        STATS["v679_boot_watchdog_quarantine_cleared"] = int(prior)
        _arm_msg = "[V679-RUNTIME-ARM] watchdog armed; synthetic_boot_errors_cleared=%d" % prior
        if bool(globals().get("_V702_SYNTHETIC_RUNTIME_ARM", False)) or bool(globals().get("_V699_VALIDATE_ONLY_REQUEST", False)):
            logger.debug(_arm_msg)
        else:
            logger.info(_arm_msg)
    except Exception as exc:
        logger.critical("[V679-RUNTIME-ARM] watchdog arm failed: %s", exc)


