# ---- Watchdog operation classification: only actual entry/exit transport
# failures are eligible to trip the global ExchangeWatchdog. Reconciliation,
# discovery, read-only market data, and telemetry retain their own counters.
_v680_prev_watchdog_classify = globals().get("watchdog_classify_op")
def _v680_watchdog_classify(op_name: str):
    try:
        low = str(op_name or "").strip().lower()
        # Balance truth is a reconciliation/entry-state dependency. Its
        # dedicated BalanceReconciler/LIVE_ENTRIES_BLOCKED authority decides
        # whether NEW entries are allowed; it is not itself an order transport.
        if any(tok in low for tok in ("fetch_balance", "reconciler_fetch_balance", "balance_truth")):
            return "RECONCILIATION"
        if low.startswith(("reconcile", "open_orders", "recover")) or "reconcile" in low:
            return "RECONCILIATION"
        if low.startswith(("fetch_ohlcv", "fetch_ticker", "fetch_tickers", "ohlcv_", "ticker_", "market_data_", "btc_context_", "v650_radar_", "v650_liquidity500_")):
            return "READ_ONLY_MARKET"
        if low.startswith(("universe_", "discover")) or "universe" in low:
            return "MARKET_DISCOVERY"
        if low.startswith(("telegram", "heartbeat", "telemetry", "trace")):
            return "TELEMETRY"
        if callable(_v680_prev_watchdog_classify):
            return _v680_prev_watchdog_classify(op_name)
    except Exception:
        pass
    return "ENTRY_CRITICAL"

watchdog_classify_op = _v680_watchdog_classify

_v680_prev_watchdog_record = ExchangeWatchdog.record_error

def _v680_watchdog_record_error(op_name: str = "", reason: str = "") -> None:
    try:
        if not bool(CONFIG.get("V680_WATCHDOG_CLASS_ISOLATION_ENABLE", True)):
            return _v680_prev_watchdog_record(op_name, reason)
        cls_name = _v680_watchdog_classify(op_name)
        STATS[f"v680_watchdog_class_{str(cls_name).lower()}"] = int(
            STATS.get(f"v680_watchdog_class_{str(cls_name).lower()}", 0) or 0
        ) + 1
        if cls_name == "ENTRY_CRITICAL" or cls_name == "EXIT_CRITICAL":
            # Preserve the pre-existing exact critical semantics.
            return _v680_prev_watchdog_record(op_name, reason)
        if cls_name == "RECONCILIATION":
            STATS["v680_reconciliation_transport_errors"] = int(
                STATS.get("v680_reconciliation_transport_errors", 0) or 0
            ) + 1
            if "balance" in str(op_name or "").lower():
                STATS["v680_balance_transport_errors"] = int(
                    STATS.get("v680_balance_transport_errors", 0) or 0
                ) + 1
            return
        if cls_name == "READ_ONLY_MARKET":
            STATS["v680_readonly_transport_errors"] = int(
                STATS.get("v680_readonly_transport_errors", 0) or 0
            ) + 1
            return
        STATS["v680_telemetry_transport_errors"] = int(
            STATS.get("v680_telemetry_transport_errors", 0) or 0
        ) + 1
    except Exception:
        try:
            _v680_prev_watchdog_record(op_name, reason)
        except Exception:
            _v647_record_suppressed_exception()

ExchangeWatchdog.record_error = staticmethod(_v680_watchdog_record_error)

