# ---- Same-candle scan reservation rollback after a real brain exception ----
def _v680_rollback_scan_reservations(market_data_map: Optional[Dict[str, Any]]) -> int:
    if not bool(CONFIG.get("V680_SCAN_RETRY_ON_BRAIN_EXCEPTION_ENABLE", True)):
        return 0
    removed = 0
    try:
        state = globals().get("_COHERENCE_SCAN_STATE")
        if not isinstance(state, dict):
            return 0
        for sym, md in (market_data_map or {}).items():
            try:
                fn = globals().get("_coherence_closed_ts")
                ts = int(fn(md.get("df_5m")) or 0) if callable(fn) else 0
                key = (str(sym), str(CONFIG.get("TF_ENTRY", "5m")), ts)
                if ts > 0 and state.get(str(sym)) == key:
                    state.pop(str(sym), None)
                    removed += 1
            except Exception:
                continue
        if removed:
            STATS["v680_scan_reservation_rollbacks"] = int(
                STATS.get("v680_scan_reservation_rollbacks", 0) or 0
            ) + removed
    except Exception:
        _v647_record_suppressed_exception()
    return removed

