def _v681_note_runtime_mse(generated: int = 0, ranked: int = 0, selected: int = 0,
                            reject_reasons: Optional[Dict[str, Any]] = None) -> None:
    try:
        if not bool(CONFIG.get("V681_MSE_RUNTIME_AGGREGATION_ENABLE", True)):
            return
        STATS["v681_runtime_cycle_generated"] = int(STATS.get("v681_runtime_cycle_generated", 0) or 0) + max(0, int(generated or 0))
        STATS["v681_runtime_cycle_ranked"] = int(STATS.get("v681_runtime_cycle_ranked", 0) or 0) + max(0, int(ranked or 0))
        STATS["v681_runtime_cycle_selected"] = int(STATS.get("v681_runtime_cycle_selected", 0) or 0) + max(0, int(selected or 0))
        rr = STATS.setdefault("v681_runtime_cycle_rank_reject_reasons", {})
        if isinstance(reject_reasons, dict):
            for k, v in reject_reasons.items():
                try:
                    rr[str(k)] = int(rr.get(str(k), 0) or 0) + max(0, int(v or 0))
                except Exception:
                    continue
    except Exception:
        _v647_record_suppressed_exception()


