def _v681_runtime_cycle_sync() -> None:
    try:
        cid = int(STATS.get("v681_runtime_cycle_id", 0) or 0)
        if not cid:
            return
        # Current-cycle rejection evidence is canonical for PREQUAL attribution.
        events = V669RejectionLedger.current_cycle(cid)
        counts = V669RejectionLedger.counts(events)
        _global_preq = int(STATS.get("v45_global_last_prequalified", 0) or 0)
        # Rejections never count as eligibility. Only the Global Brain's
        # canonical prequalified count may populate E; per-symbol MSE routing
        # remains E=0 until an explicit canonical prequal-pass counter exists.
        STATS["v681_runtime_cycle_prequal"] = max(0, _global_preq)
        # Use actual canonical execution deltas where available; never infer send
        # from selection. This is telemetry-only and keeps the hard execution path
        # untouched.
        STATS["v681_runtime_cycle_queued"] = int(STATS.get("v547_cycle_queued_delta", 0) or 0)
        STATS["v681_runtime_cycle_sent"] = int(STATS.get("v547_cycle_sent_delta", 0) or 0)
        STATS["v681_runtime_cycle_reject_buckets"] = dict(counts)
        STATS["v681_runtime_cycle_finished_ts"] = WALL_NOW()
        STATS["v681_runtime_cycle_age_sec"] = max(
            0.0, float(STATS["v681_runtime_cycle_finished_ts"]) - float(STATS.get("v681_runtime_cycle_started_ts", STATS["v681_runtime_cycle_finished_ts"]))
        )
        if globals().get("V669CycleLedger") is not None:
            V669CycleLedger.sync_execution(cid)
        STATS["v680_last_cycle_id"] = cid
        STATS["v669_last_cycle_id"] = cid
    except Exception:
        _v647_record_suppressed_exception()


