        # Watchdog isolation regression: reconciliation must not populate the
        # critical error deque; create_market_buy must remain critical.
        _errors = getattr(ExchangeWatchdog, "_errors", None)
        _before = len(_errors) if _errors is not None else -1
        ExchangeWatchdog.record_error("reconciler_fetch_balance", "TimeoutError")
        _after_recon = len(_errors) if _errors is not None else -1
        checks["watchdog_reconciliation_isolated"] = (_before == _after_recon) and (_v680_watchdog_classify("reconciler_fetch_balance") == "RECONCILIATION")
        ExchangeWatchdog.record_error("create_market_buy", "network timeout")
        _after_buy = len(_errors) if _errors is not None else -1
        checks["watchdog_entry_critical_preserved"] = (_after_buy >= _after_recon + 1)
        if _errors is not None:
            _errors.clear()
        try:
            ExchangeWatchdog._tripped_until = 0.0
        except Exception:
            pass

        # Starvation regression: counts with no active cycle resolve from the
        # persisted final cycle id and choose the dominant ordinary bucket.
        old_active = globals().get("_V517_ACTIVE_CYCLE_ID")
        old_last = STATS.get("v680_last_cycle_id")
