        try:
            globals()["_V517_ACTIVE_CYCLE_ID"] = None
            STATS["v680_last_cycle_id"] = 9001
            STATS["v669_last_cycle_id"] = 9000
            _orig_cc = V669RejectionLedger.current_cycle
            _orig_counts = V669RejectionLedger.counts
            V669RejectionLedger.current_cycle = staticmethod(lambda cid: [
                {"bucket": "POLICY"}, {"bucket": "STRUCTURE"},
                {"bucket": "STRUCTURE"}, {"bucket": "HTF"},
            ])
            V669RejectionLedger.counts = staticmethod(lambda rows: {
                "SYSTEM":0,"POLICY":1,"HTF":1,"LIQUIDITY":0,"STRUCTURE":2,
                "SCORE":0,"FEE":0,"PRE_SEND":0,"EXECUTION":0,"OTHER":0,
            })
            sc = _v680_current_cycle_id()
            classified = _v679_starvation_classify()
            checks["starvation_current_cycle_id_fallback"] = sc == 9001
            checks["starvation_dominant_current_count"] = classified.get("root") == "STRUCTURE"
        finally:
            try:
                V669RejectionLedger.current_cycle = _orig_cc
                V669RejectionLedger.counts = _orig_counts
            except Exception:
                pass
            globals()["_V517_ACTIVE_CYCLE_ID"] = old_active
            if old_last is None:
                STATS.pop("v680_last_cycle_id", None)
