def _v682_truth() -> Dict[str, Any]:
    try:
        cid = _v682_authoritative_cycle_id()
        events = V669RejectionLedger.current_cycle(cid) if cid else []
        counts = V669RejectionLedger.counts(events)
        generated = int(STATS.get("v681_runtime_cycle_generated", 0) or 0)
        ranked = int(STATS.get("v681_runtime_cycle_ranked", 0) or 0)
        raw_ranked = int(STATS.get("v681_runtime_cycle_raw_ranked", 0) or 0)
        selected = int(STATS.get("v681_runtime_cycle_selected", 0) or 0)
        rank_rej = dict(STATS.get("v681_runtime_cycle_rank_reject_reasons") or {})
        fee_rank_rej = int(sum(int(v or 0) for k,v in rank_rej.items()
                               if str(k).lower() == "fee_unviable"))
        system = int(counts.get("SYSTEM", 0) or 0)
        ordinary = {str(k): int(v or 0) for k,v in counts.items()
                    if str(k) != "SYSTEM" and int(v or 0) > 0}
        if system > 0:
            root, root_count = "SYSTEM", system
        elif generated > 0 and ranked == 0 and fee_rank_rej > 0:
            root, root_count = "FEE", fee_rank_rej
        elif ordinary:
            pri = {name:i for i,name in enumerate(V669RejectionLedger.PRIORITY)}
            root = max(ordinary, key=lambda k:(ordinary[k], -pri.get(k,999)))
            root_count = ordinary[root]
        elif generated > 0 and raw_ranked == 0:
            top = str(STATS.get("v596_mse_rank_reject_top", "") or "")
            root = "FEE" if "fee_unviable" in top else "SCORE"
            root_count = fee_rank_rej if root == "FEE" else 0
        else:
            root, root_count = "NONE", 0
        evidence = int(sum(int(v or 0) for v in counts.values())) + fee_rank_rej
        return {
            "mode": root, "root": root, "source": "V682_RUNTIME_CYCLE",
            "cycle_id": cid, "counts": counts,
            "generated": generated, "ranked": ranked, "selected": selected,
            "rank_reject_reasons": rank_rej, "root_count": root_count,
            "root_share": round(root_count / float(evidence), 4) if evidence and root != "NONE" else 0.0,
            "evidence": evidence,
        }
    except Exception as exc:
        return {"mode":"SYSTEM", "root":"SYSTEM", "source":"V682_ERROR",
                "error":f"{type(exc).__name__}:{exc}"}

