def _v689_rejection_taxonomy(reason, authority=""):
    """Deterministic primary/secondary taxonomy for forensic attribution."""
    r=str(reason or "").lower(); a=str(authority or "").lower()
    if "family_tier_below_floor" in r or "tier_spread" in r or "orderbook" in r or "depth" in r or r.startswith("liquidity."):
        return {"primary":"LIQUIDITY","secondary":"FAMILY_POLICY_TIER" if "family_tier" in r else ("SPREAD" if "spread" in r else "DEPTH"),"stage":"POLICY" if "family_tier" in r and "spread" not in r else "LIQUIDITY"}
    if "family_regime" in r or "strategy_policy" in r or r.startswith("policy."):
        return {"primary":"POLICY","secondary":"REGIME" if "regime" in r else "STRATEGY_POLICY","stage":"POLICY"}
    if "structural" in r or r.startswith("structure.") or "microstruct" in r or r.startswith("lsr."):
        return {"primary":"STRUCTURE","secondary":"LSR_NATIVE" if r.startswith("lsr.") else "MICROSTRUCTURE","stage":"STRUCTURE"}
    if "htf" in r:
        return {"primary":"HTF","secondary":"CORE" if "core" in r else "STRATEGY_POLICY","stage":"HTF"}
    if "score" in r:
        return {"primary":"SCORE","secondary":"FLOOR","stage":"SCORE"}
    if "fee" in r or "rr" in r:
        return {"primary":"FEE","secondary":"ECONOMICS","stage":"ECONOMICS"}
    if "presend" in r or "execution" in r:
        return {"primary":"EXECUTION","secondary":"PRESEND","stage":"PRE_SEND"}
    if "sl" in r:
        return {"primary":"SL","secondary":"RISK","stage":"RISK"}
    if "balance" in r:
        return {"primary":"BALANCE","secondary":"FUNDS","stage":"RISK"}
    return {"primary":"OTHER","secondary":"UNCLASSIFIED","stage":authority or "OTHER"}

