# V702 BOOTSTRAP ORDER CLOSURE — canonical cycle/fingerprint/coalescer helpers
# are defined before the V689 boot self-test invokes the real MSE handoff.
def _v702_current_cycle_id(snapshot=None) -> int:
    """Return the active runtime cycle id; zero is treated as unverifiable."""
    try:
        snap = snapshot if isinstance(snapshot, dict) else {}
        keys = (
            snap.get("cycle_id"),
            globals().get("_V517_ACTIVE_CYCLE_ID"),
            STATS.get("v681_runtime_cycle_id"),
            STATS.get("v516_cycle_id"),
            STATS.get("v669_current_cycle_id"),
            STATS.get("v669_last_cycle_id"),
        )
        for raw in keys:
            try:
                cid = int(raw or 0)
            except Exception:
                cid = 0
            if cid > 0:
                return cid
    except Exception:
        _v647_record_suppressed_exception()
    return 0


# V702 FINAL — same-cycle candidate coalescing. This is strictly a pool-hygiene
# optimization: it never crosses candle/cycle boundaries and only coalesces
# candidates whose immutable recipe/context fingerprint is identical. The
# highest engine score representative is retained. Missing identity disables
# the optimization rather than dropping a candidate.
def _v702_recipe_fingerprint(candidate: Any) -> str:
    try:
        fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        stable = {
            "family": str(getattr(candidate, "family", "") or "").upper(),
            "strategy_mode": str(getattr(candidate, "strategy_mode", "") or "").upper(),
            "strategy_style": str(getattr(candidate, "strategy_style", "") or "SCALP").upper(),
            "entry_ref": round(float(getattr(candidate, "entry_ref", 0.0) or 0.0), 10),
            "sl_price": round(float(getattr(candidate, "sl_price", 0.0) or 0.0), 10),
            "tp1_rr": round(float(getattr(candidate, "tp1_rr", 0.0) or 0.0), 6),
            "tp2_rr": round(float(getattr(candidate, "tp2_rr", 0.0) or 0.0), 6),
            "tp3_rr": round(float(getattr(candidate, "tp3_rr", 0.0) or 0.0), 6),
        }
        for k in (
            "zone_ref", "htf_alignment", "htf_strength", "volume_ratio",
            "rs_5m", "chase_atr", "structure_quality", "retest_quality",
            "micro_bos", "setup_quality", "liquidity_tier", "tier",
        ):
            v = fs.get(k)
            if isinstance(v, (int, float)):
                stable[k] = round(float(v), 6) if math.isfinite(float(v)) else None
            else:
                stable[k] = str(v or "")[:80]
        raw = json.dumps(stable, sort_keys=True, ensure_ascii=False, separators=(",", ":"), default=str)
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()
    except Exception:
        return ""

def _v702_coalesce_same_cycle_candidates(candidates: List[Any], snapshot: Dict[str, Any]) -> Tuple[List[Any], int]:
    if not bool(CONFIG.get("V702_SAME_CYCLE_COALESCING_ENABLE", True)):
        return list(candidates), 0
    try:
        if not isinstance(snapshot, dict):
            return list(candidates), 0
        cycle_id = int(_v702_current_cycle_id(snapshot))
        candle = str(snapshot.get("closed_candle_ts") or snapshot.get("candle_ts") or "")
        if cycle_id <= 0 or not candle:
            STATS["v702_coalescer_identity_missing"] = int(STATS.get("v702_coalescer_identity_missing", 0) or 0) + 1
            return list(candidates), 0
        best: Dict[str, Any] = {}
        order: List[str] = []
        removed = 0
        for c in list(candidates or []):
            sym = str(getattr(c, "symbol", "") or "")
            fp = _v702_recipe_fingerprint(c)
            if not sym or not fp:
                order.append("")
                continue
            key = f"{cycle_id}|{sym}|{candle}|{fp}"
            prev = best.get(key)
            if prev is None:
                best[key] = c
                order.append(key)
                continue
            prev_score = float(getattr(prev, "engine_score", 0.0) or 0.0)
            cur_score = float(getattr(c, "engine_score", 0.0) or 0.0)
            if cur_score > prev_score:
                best[key] = c
            removed += 1
        out=[]
        seen=set()
        # Preserve original candidate order while replacing duplicates with the best representative.
        for c in list(candidates or []):
            sym=str(getattr(c,"symbol","") or "")
            fp=_v702_recipe_fingerprint(c)
            key=f"{cycle_id}|{sym}|{candle}|{fp}" if sym and fp else ""
            if key and key in best:
                if key in seen:
                    continue
                seen.add(key)
                out.append(best[key])
            else:
                out.append(c)
        if removed:
            STATS["v702_same_cycle_coalesced"] = int(STATS.get("v702_same_cycle_coalesced", 0) or 0) + removed
            STATS["v702_same_cycle_coalescing_cycles"] = int(STATS.get("v702_same_cycle_coalescing_cycles", 0) or 0) + 1
        return out, removed
    except Exception as exc:
        STATS["v702_same_cycle_coalescer_errors"] = int(STATS.get("v702_same_cycle_coalescer_errors", 0) or 0) + 1
        _v593_note_suppressed_exception("v702.same_cycle_coalescer", exc)
        return list(candidates), 0


