# -----------------------------------------------------------------------------
# Canonical score domain: 0..1 for every runtime decision comparison.
# Source-domain conversion is explicit and deterministic; values >1 without a
# source annotation are treated as legacy 0..100, never clipped to 1.
# -----------------------------------------------------------------------------
def canonical_score_to_01(value, source_domain=None):
    try:
        x = float(value)
        if not math.isfinite(x):
            return 0.0
        domain = str(source_domain or "").strip().lower()
        if domain in {"100", "0-100", "0..100", "legacy100", "execution", "score100"}:
            return _clamp(x / 100.0, 0.0, 1.0)
        if not domain and x > 1.0:
            return _clamp(x / 100.0, 0.0, 1.0)
        return _clamp(x, 0.0, 1.0)
    except Exception:
        return 0.0


def canonical_score_to_100(value, source_domain=None):
    try:
        x = float(value)
        if not math.isfinite(x):
            return 0.0
        domain = str(source_domain or "").strip().lower()
        if domain in {"100", "0-100", "0..100", "legacy100", "execution", "score100"}:
            return _clamp(x, 0.0, 100.0)
        if not domain and x > 1.0:
            return _clamp(x, 0.0, 100.0)
        return _clamp(x * 100.0, 0.0, 100.0)
    except Exception:
        return 0.0


def canonical_score_floor_01(policy="base", level=0):
    try:
        p = str(policy or "base").lower()
        if p in {"hard", "hard_floor", "minimum"}:
            return float(CONFIG.get("V690_SCORE_HARD_FLOOR_01", 0.50))
        if p in {"rescue", "recovery"} and int(level) > 0:
            vals = tuple(float(x) for x in CONFIG.get("V690_RESCUE_LEVELS_01", (0.52, 0.50, 0.50)))
            idx = max(1, min(int(level), len(vals))) - 1
            return vals[idx]
        return float(CONFIG.get("V690_SCORE_BASE_01", 0.54))
    except Exception:
        return 0.50


def canonical_score_floor_100(policy="base", level=0):
    return canonical_score_to_100(canonical_score_floor_01(policy, level), "01")

# Expose the same helpers under the legacy V689 names so there is only one
# implementation body at runtime.
_v689_score_to_01 = canonical_score_to_01
_v689_score_to_100 = canonical_score_to_100

# -----------------------------------------------------------------------------
# Canonical policy registry: one normalized decision snapshot.
# -----------------------------------------------------------------------------
def _v690_normalize_policy_registry():
    try:
        data = CanonicalStrategyPolicyRegistry.data()
        legacy = globals().get("V43_STRATEGY_POLICY_META") or {}
        legacy_cfg = {}
        for fam in (
            "PULLBACK", "MTF_PULLBACK", "BREAKOUT_RETEST", "BREAKOUT_CONTINUATION",
            "TREND_CONTINUATION", "LIQUIDITY_SWEEP_REVERSAL", "MEAN_REVERSION",
            "MOMENTUM_EXPANSION", "LOCAL_STRENGTH_BREAKOUT", "COMPRESSION_EXPANSION",
            "CONTINUATION_RECLAIM", "FAILED_BREAKOUT_RECLAIM", "VOLATILITY_BURST",
            "RELATIVE_STRENGTH_LEADER", "MICRO_TREND_CONTINUATION", "BEARISH_RECOVERY"
        ):
            cfg = CONFIG.get("FAMILY_POLICY_" + fam)
            legacy_cfg[fam] = dict(cfg) if isinstance(cfg, dict) else {}
        drift = {}
        for fam in sorted(set(data) | set(legacy_cfg) | set(legacy)):
            d = dict(data.get(fam, {}) or {})
            lc = legacy_cfg.get(fam, {})
            compare = (
                ("min_tier", str(d.get("min_tier", "")).upper(), str(lc.get("min_tier", "")).upper()),
                ("min_htf_strength", d.get("min_htf_strength_non_bearish"), lc.get("min_htf_strength")),
                ("allowed_regimes", tuple(d.get("allowed_regimes", ())), tuple(lc.get("allowed_regimes", ()))),
            )
            mismatches = {}
            for key, a, b in compare:
                if b in (None, "", ()):
                    continue
                try:
                    if float(a) != float(b):
                        mismatches[key] = {"canonical": a, "legacy": b}
                except Exception:
                    if a != b:
                        mismatches[key] = {"canonical": a, "legacy": b}
            if mismatches:
                drift[fam] = mismatches
            # One normalized projection used by all legacy call sites after this
            # point. Canonical registry values always win when present.
            if "min_htf_strength_non_bearish" in d:
                d.setdefault("min_htf_strength", float(d["min_htf_strength_non_bearish"]))
            elif lc.get("min_htf_strength") is not None:
                d["min_htf_strength"] = float(lc["min_htf_strength"])
            if "min_tier" not in d and lc.get("min_tier") is not None:
                d["min_tier"] = str(lc["min_tier"]).upper()
            for key in ("min_score_offset", "tp1_atr_floor", "preferred_zones", "volume_floor_ratio"):
                if key not in d and key in lc:
                    d[key] = lc[key]
            if "allowed_regimes" not in d and lc.get("allowed_regimes"):
                d["allowed_regimes"] = tuple(lc["allowed_regimes"])
            data[fam] = d
        raw = json.dumps(data, sort_keys=True, default=str, separators=(",", ":"))
        CanonicalStrategyPolicyRegistry._data = data
        CanonicalStrategyPolicyRegistry._revision = hashlib.sha256(raw.encode()).hexdigest()[:16]
        CanonicalStrategyPolicyRegistry._bootstrapped = True
        STATS["v690_policy_revision"] = CanonicalStrategyPolicyRegistry._revision
        STATS["v690_policy_drift"] = bool(drift)
        STATS["v690_policy_drift_detail"] = drift
        return data, drift
    except Exception as exc:
        STATS["v690_policy_drift"] = True
        STATS["v690_policy_drift_detail"] = {"EXCEPTION": f"{type(exc).__name__}:{exc}"}
        return CanonicalStrategyPolicyRegistry.data(), STATS["v690_policy_drift_detail"]


V690_CANONICAL_POLICY, V690_POLICY_DRIFT = _v690_normalize_policy_registry()
FINAL_CANONICAL_POLICY = V690_CANONICAL_POLICY


def _v690_get_family_policy(family: str) -> Dict[str, Any]:
    name = str(family or "PULLBACK").upper()
    raw = V690_CANONICAL_POLICY.get(name)
    if not isinstance(raw, dict):
        raw = V690_CANONICAL_POLICY.get("PULLBACK", {})
    return dict(raw or {})


# Rebind the class method itself: no wrapper-over-wrapper chain.
FamilyPolicyLayer.get_family_policy = staticmethod(_v690_get_family_policy)

# -----------------------------------------------------------------------------
# Canonical rejection taxonomy.
# -----------------------------------------------------------------------------
def _v690_rejection_taxonomy(reason, authority=""):
    r = str(reason or "").lower()
    a = str(authority or "").upper()
    if "family_tier_below_floor" in r:
        return {"primary": "LIQUIDITY", "secondary": "FAMILY_POLICY_TIER", "stage": "LIQUIDITY"}
    if "tier_spread" in r or "spread" in r:
        return {"primary": "LIQUIDITY", "secondary": "SPREAD", "stage": "LIQUIDITY"}
    if "orderbook" in r or "depth" in r or r.startswith("liquidity.") or "below_tier" in r:
        return {"primary": "LIQUIDITY", "secondary": "DEPTH", "stage": "LIQUIDITY"}
    if "family_regime" in r or "family_policy" in r or r.startswith("policy."):
        return {"primary": "POLICY", "secondary": "REGIME" if "regime" in r else "STRATEGY_POLICY", "stage": "POLICY"}
    if "structural" in r or r.startswith("structure.") or "microstruct" in r or r.startswith("lsr."):
        return {"primary": "STRUCTURE", "secondary": "LSR_NATIVE" if r.startswith("lsr.") else "MICROSTRUCTURE", "stage": "STRUCTURE"}
    if "htf" in r:
        return {"primary": "HTF", "secondary": "CORE", "stage": "HTF"}
    if "score" in r:
        return {"primary": "SCORE", "secondary": "FLOOR", "stage": "SCORE"}
    if "fee" in r or "rr" in r:
        return {"primary": "FEE", "secondary": "ECONOMICS", "stage": "ECONOMICS"}
    if "presend" in r or "execution" in r:
        return {"primary": "EXECUTION", "secondary": "PRESEND", "stage": "PRE_SEND"}
    if "sl" in r:
        return {"primary": "SL", "secondary": "RISK", "stage": "RISK"}
    if "balance" in r:
        return {"primary": "BALANCE", "secondary": "FUNDS", "stage": "RISK"}
    if "exposure" in r:
        return {"primary": "EXPOSURE", "secondary": "RISK", "stage": "RISK"}
    return {"primary": "OTHER", "secondary": "UNCLASSIFIED", "stage": a or "OTHER"}


_v689_rejection_taxonomy = _v690_rejection_taxonomy

# -----------------------------------------------------------------------------
# Truth fingerprint / canonical prequalification reuse.
# -----------------------------------------------------------------------------
def _v690_truth_fingerprint(candidate, snapshot):
    fs = dict(getattr(candidate, "features_snapshot", {}) or {})
    snap = snapshot if isinstance(snapshot, dict) else {}
    native_keys = (
        "sweep", "reclaim", "bullish_close", "higher_low", "micro_bos",
        "sr_recovery_verified", "swept_low", "zone_ref", "body_ratio",
        "lower_wick_ratio", "volume_ratio", "chase_atr", "dist_atr", "bos_confirmed"
    )
    facts = {
        "symbol": str(getattr(candidate, "symbol", "") or snap.get("symbol", "")),
        "candle_ts": _v689_candle_ts(snap),
        "tier": str(snap.get("tier") or fs.get("tier") or "").upper(),
        "htf_state": str(snap.get("htf_state") or fs.get("htf_state") or "UNKNOWN").upper(),
        "htf_strength": snap.get("htf_strength", fs.get("htf_strength")),
        "regime": snap.get("macro_regime", snap.get("regime", fs.get("macro_regime", ""))),
        "local_regime": snap.get("local_regime", fs.get("local_regime", "")),
        "market_phase": snap.get("market_phase", fs.get("market_phase", "")),
        "spread_pct": snap.get("spread_pct", fs.get("spread_pct")),
        "quote_vol_24h": snap.get("quote_vol_24h", fs.get("quote_vol_24h")),
        "family": str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper(),
        "policy_revision": CanonicalStrategyPolicyRegistry.revision(),
        "native": {k: fs.get(k) for k in native_keys if k in fs},
    }
    return hashlib.sha256(json.dumps(facts, sort_keys=True, default=str, separators=(",", ":")).encode()).hexdigest()[:32]


def _v690_prequal_fingerprint(candidate, snapshot):
    snap = snapshot if isinstance(snapshot, dict) else {}
    tier = str(snap.get("tier") or getattr(candidate, "features_snapshot", {}).get("tier") or "").upper()
    hs = str(snap.get("htf_state") or getattr(candidate, "features_snapshot", {}).get("htf_state") or "UNKNOWN").upper()
    sp = snap.get("spread_pct", getattr(candidate, "features_snapshot", {}).get("spread_pct"))
    cid = str(snap.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0")
    raw = (
        str(getattr(candidate, "symbol", "") or snap.get("symbol", "")),
        _v689_candle_ts(snap), cid, tier, hs, _v689_spread_bucket(sp, tier),
        CanonicalStrategyPolicyRegistry.revision(),
    )
    return hashlib.sha256(repr(raw).encode()).hexdigest()[:24]


def _v690_record_prequal(candidate, snapshot, verdict, reason):
    fs = getattr(candidate, "features_snapshot", None)
    if not isinstance(fs, dict):
        return
    snap = snapshot if isinstance(snapshot, dict) else {}
    tier = str(snap.get("tier") or fs.get("tier") or "").upper()
    sp = snap.get("spread_pct", fs.get("spread_pct"))
    raw_score = getattr(candidate, "engine_score", 0.0)
    score01 = canonical_score_to_01(raw_score)
    ages = _v689_market_fact_ages(candidate, snap)
    cycle_id = str(snap.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0")
    candle_ts = _v689_candle_ts(snap)
    htf_state = str(snap.get("htf_state") or fs.get("htf_state") or "UNKNOWN").upper()
    fp = _v690_prequal_fingerprint(candidate, snap)
    truth_hash = _v690_truth_fingerprint(candidate, snap)
    fs["v688_prequal_verdict"] = {
        "verdict": bool(verdict),
        "reason": str(reason),
        "cycle_id": cycle_id,
        "symbol": str(getattr(candidate, "symbol", "") or snap.get("symbol") or ""),
        "candle_ts": candle_ts,
        "tier": tier,
        "htf_state": htf_state,
        "htf_strength": snap.get("htf_strength", fs.get("htf_strength")),
        "regime": snap.get("macro_regime", snap.get("regime", fs.get("macro_regime"))),
        "local_regime": snap.get("local_regime", fs.get("local_regime")),
        "market_phase": snap.get("market_phase", fs.get("market_phase")),
        "spread_bucket": _v689_spread_bucket(sp, tier),
        "spread_pct": sp,
        "score": score01,
        "score_01": score01,
        "score_100": canonical_score_to_100(score01, "01"),
        "score_domain": "01",
        "score_floor_01": canonical_score_floor_01("base"),
        "score_floor_100": canonical_score_floor_100("base"),
        "structure_verdict": fs.get("v643_canonical_precision_reason", fs.get("structure_verdict")),
        "policy_revision": CanonicalStrategyPolicyRegistry.revision(),
        "fingerprint": fp,
        "truth_fingerprint": truth_hash,
        "timestamp": WALL_NOW(),
        "canonical_authority_version": V690_ROOT_CLOSURE_IDENTITY,
        **ages,
    }
    STATS["v690_last_prequal_snapshot"] = dict(fs["v688_prequal_verdict"])


def _v690_prequal_snapshot_reusable(candidate, snapshot):
    """Permit bounded downstream reuse only for the same fresh runtime cycle.

    Reuse is never an authority to overrule the current canonical family/macro
    policy gate. Both the candidate and its stored verdict must be <=45s old,
    the verdict timestamp must be valid, and its cycle must match the current
    snapshot/runtime cycle exactly.
    """
    try:
        fs = getattr(candidate, "features_snapshot", {}) or {}
        verdict = fs.get("v688_prequal_verdict") or {}
        if not verdict.get("verdict") or not isinstance(snapshot, dict):
            return False
        age = _wall_age_sec(getattr(candidate, "generated_at_ms", None))
        reuse_max_age = min(45.0, max(1.0, float(CONFIG.get("V689_PREQUAL_REUSE_MAX_AGE_SEC", 45.0) or 45.0)))
        if age is None or age < 0.0 or age > reuse_max_age:
            return False
        try:
            verdict_ts = float(verdict.get("timestamp", 0.0) or 0.0)
            verdict_age = float(WALL_NOW()) - verdict_ts
        except Exception:
            return False
        if verdict_ts <= 0.0 or not math.isfinite(verdict_age) or verdict_age < 0.0 or verdict_age > reuse_max_age:
            return False
        current_cycle = str(snapshot.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0")
        verdict_cycle = str(verdict.get("cycle_id") or "")
        if current_cycle in {"", "0", "None"} or not verdict_cycle or verdict_cycle != current_cycle:
            return False
        ages = _v689_market_fact_ages(candidate, snapshot)
        for key, lim in (
            ("market_snapshot_age_sec", "V690_MAX_MARKET_SNAPSHOT_AGE_SEC"),
            ("spread_age_sec", "V690_MAX_SPREAD_AGE_SEC"),
            ("book_age_sec", "V690_MAX_BOOK_AGE_SEC"),
            ("candle_age_sec", "V690_MAX_CANDLE_AGE_SEC"),
        ):
            av = ages.get(key)
            if av is not None and av > float(CONFIG.get(lim, 999999.0)):
                return False
        current_fp = _v690_prequal_fingerprint(candidate, snapshot)
        if current_fp != str(verdict.get("fingerprint", "")):
            return False
        current_truth = _v690_truth_fingerprint(candidate, snapshot)
        if current_truth != str(verdict.get("truth_fingerprint", "")):
            STATS["v690_builder_truth_changed"] = int(STATS.get("v690_builder_truth_changed", 0) or 0) + 1
            return False
        if str(verdict.get("tier", "")).upper() and str(snapshot.get("tier") or "").upper() != str(verdict.get("tier")).upper():
            return False
        if verdict.get("spread_pct") is not None and snapshot.get("spread_pct") is not None:
            if abs(float(verdict["spread_pct"]) - float(snapshot["spread_pct"])) > 0.02:
                return False
        if verdict.get("htf_strength") is not None and snapshot.get("htf_strength") is not None:
            if abs(float(verdict["htf_strength"]) - float(snapshot["htf_strength"])) > 2.5:
                return False
        fs["v690_fact_ages"] = ages
        STATS["v690_builder_reused_prequal"] = int(STATS.get("v690_builder_reused_prequal", 0) or 0) + 1
        return True
    except Exception:
        return False


_v689_prequal_fingerprint = _v690_prequal_fingerprint
_v689_record_prequal = _v690_record_prequal
_v689_prequal_snapshot_reusable = _v690_prequal_snapshot_reusable

# -----------------------------------------------------------------------------
# Canonical HTF evidence ladder + bounded H0 recomputation + repeat suppression.
# -----------------------------------------------------------------------------
def _v690_htf_evidence_class(raw_strength, state, source):
    st = str(state or "UNKNOWN").upper()
    src = str(source or "").upper()
    try:
        val = float(raw_strength or 0.0)
    except Exception:
        val = 0.0
    if st in {"BEARISH", "HARD_REJECT", "CRASH", "BEARISH_CRASH"} or src == "RAW_HARD_REJECT":
        return "HTF_HARD_REJECT"
    if src in {"UNAVAILABLE", "RECOMPUTE_ERROR", "STALE"}:
        return "HTF_UNAVAILABLE"
    if src == "RECOMPUTED_H0":
        return "HTF_RECOVERY_ALIGNMENT"
    if val >= 75.0:
        return "HTF_FULL_ALIGNMENT"
    if val >= 60.0:
        return "HTF_CONTINUATION_ALIGNMENT"
    return "HTF_RECOVERY_ALIGNMENT"


def _v690_resolve_htf_strength(symbol, snapshot, candidate=None):
    snap = snapshot if isinstance(snapshot, dict) else {}
    raw = snap.get("htf_strength")
    state = str(snap.get("htf_state") or "UNKNOWN").upper()
    try:
        raw = float(raw) if raw is not None else 0.0
    except Exception:
        raw = 0.0
    if raw > 0 and math.isfinite(raw):
        snap["htf_primary_strength"] = raw
        snap["htf_recomputed_strength"] = None
        snap["htf_recompute_used"] = False
        snap["htf_evidence_class"] = _v690_htf_evidence_class(raw, state, "RAW")
        return raw, "RAW", 0.0
    htf_reason = str(snap.get("htf_reason") or "").strip().lower()
    unusable_reasons = {"insufficient_data", "invalid_close_history", "invalid_closed_values", "snapshot_unavailable", "htf_grade_exception"}
    evidence_unusable = htf_reason in unusable_reasons or htf_reason.startswith("error:")
    if state in {"BEARISH", "HARD_REJECT", "CRASH", "BEARISH_CRASH"} and not evidence_unusable:
        snap["htf_evidence_class"] = "HTF_HARD_REJECT"
        snap["htf_recompute_used"] = False
        return raw, "RAW_HARD_REJECT", 0.0
    df1, df4 = snap.get("df_1h"), snap.get("df_4h")
    required_1h = max(210, int(CONFIG.get("HTF_MIN_CANDLES_1H", 240) or 240))
    required_4h = max(210, int(CONFIG.get("HTF_MIN_CANDLES_4H", 200) or 200))
    if df1 is None or df4 is None or len(df1) < required_1h or len(df4) < required_4h:
        snap.update({"htf_primary_strength": raw, "htf_recomputed_strength": None, "htf_recompute_used": False,
                     "htf_recompute_reason": "ema200_warmup_insufficient", "htf_evidence_class": "HTF_UNAVAILABLE"})
        STATS["v690_htf_recompute_unavailable"] = int(STATS.get("v690_htf_recompute_unavailable", 0) or 0) + 1
        STATS["v690_htf_recompute_unavailable_reason"] = "ema200_warmup_insufficient"
        return None, "UNAVAILABLE", 0.0
    try:
        if not _PDNP_OK or "close" not in getattr(df1, "columns", ()) or "close" not in getattr(df4, "columns", ()):
            raise ValueError("close_column_unavailable")
        _c1 = pd.to_numeric(df1["close"], errors="coerce")
        _c4 = pd.to_numeric(df4["close"], errors="coerce")
        _h1 = [float(x) for x in _c1.iloc[-required_1h:].tolist()]
        _h4 = [float(x) for x in _c4.iloc[-required_4h:].tolist()]
        if (len(_h1) < required_1h or len(_h4) < required_4h
                or any((not math.isfinite(x)) or x <= 0.0 for x in _h1)
                or any((not math.isfinite(x)) or x <= 0.0 for x in _h4)):
            raise ValueError("ema200_history_invalid")
    except Exception as exc:
        snap.update({"htf_primary_strength": raw, "htf_recomputed_strength": None, "htf_recompute_used": False,
                     "htf_recompute_reason": "ema200_history_invalid", "htf_evidence_class": "HTF_UNAVAILABLE"})
        STATS["v690_htf_recompute_unavailable"] = int(STATS.get("v690_htf_recompute_unavailable", 0) or 0) + 1
        STATS["v690_htf_recompute_unavailable_reason"] = "ema200_history_invalid"
        return None, "UNAVAILABLE", 0.0
    cts = _v689_candle_ts(snap)
    cid = str(snap.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0")
    key = (str(symbol), cts, cid)
    cached = _V689_HTF_CACHE.get(key)
    if cached is not None:
        snap.update({
            "htf_primary_strength": raw,
            "htf_recomputed_strength": cached.get("strength"),
            "htf_recompute_used": True,
            "htf_recompute_reason": "cache_reuse",
            "htf_recompute_gap": float(cached.get("strength", 0.0)) - raw,
            "htf_evidence_class": "HTF_RECOVERY_ALIGNMENT",
        })
        STATS["v690_htf_recompute_cache_hits"] = int(STATS.get("v690_htf_recompute_cache_hits", 0) or 0) + 1
        return float(cached["strength"]), str(cached.get("source", "RECOMPUTED_H0")), 0.0
    try:
        e1 = _c1.ewm(span=50, adjust=False).mean()
        e2 = _c1.ewm(span=200, adjust=False).mean()
        f1 = _c4.ewm(span=50, adjust=False).mean()
        f2 = _c4.ewm(span=200, adjust=False).mean()
        score = (
            25.0 * bool(float(f1.iloc[-2]) > float(f2.iloc[-2])) +
            15.0 * bool(float(e1.iloc[-2]) > float(e2.iloc[-2])) +
            5.0 * bool(float(_c1.iloc[-2]) > float(e1.iloc[-2])) +
            5.0 * bool(float(_c4.iloc[-2]) > float(f1.iloc[-2]))
        )
        try:
            score += 5.0 * bool(float(e1.iloc[-2]) > float(e1.iloc[-7]))
        except Exception:
            pass
        score = min(float(CONFIG.get("V690_HTF_RECOMPUTE_MAX_STRENGTH", 55.0)), float(score))
        cached = {"strength": score, "source": "RECOMPUTED_H0", "reason": "raw_zero_or_unavailable"}
        _V689_HTF_CACHE[key] = cached
        snap.update({
            "htf_primary_strength": raw,
            "htf_recomputed_strength": score,
            "htf_recompute_used": True,
            "htf_recompute_reason": "raw_zero_or_unavailable",
            "htf_recompute_gap": score - raw,
            "htf_evidence_class": "HTF_RECOVERY_ALIGNMENT",
        })
        STATS["v690_htf_recompute_used"] = int(STATS.get("v690_htf_recompute_used", 0) or 0) + 1
        return score, "RECOMPUTED_H0", 0.0
    except Exception:
        snap.update({"htf_primary_strength": raw, "htf_recomputed_strength": None, "htf_recompute_used": False,
                     "htf_recompute_reason": "recompute_error", "htf_evidence_class": "HTF_UNAVAILABLE"})
        return None, "RECOMPUTE_ERROR", 0.0


_v689_htf_evidence_class = _v690_htf_evidence_class
_v689_resolve_htf_strength = _v690_resolve_htf_strength


_V689_HTF_REJECTS_LOCK = threading.RLock()

def _v690_note_htf_repeat(symbol, snapshot, reason):
    """Bounded negative-history cache for HTF rejection repetition only.

    Expiry controls storage lifetime; the independent suppression interval keeps
    its prior decision semantics. This cache never makes a trade admissible.
    """
    try:
        snap = snapshot if isinstance(snapshot, dict) else {}
        key = (
            str(symbol), _v689_candle_ts(snap),
            str(snap.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0"),
            str(reason),
        )
        now = float(WALL_NOW())
        ttl = float(CONFIG.get("V690_HTF_REPEAT_TTL_SEC", 3600.0) or 3600.0)
        if not math.isfinite(ttl) or ttl < 60.0:
            ttl = 3600.0
        ttl = min(86400.0, ttl)
        try:
            cap = int(CONFIG.get("V690_HTF_REPEAT_MAX_ENTRIES", 10000) or 10000)
        except Exception:
            cap = 10000
        cap = max(256, min(50000, cap))
        with _V689_HTF_REJECTS_LOCK:
            # Sweep periodically or under pressure to keep the hot path bounded.
            if len(_V689_HTF_REJECTS) >= cap or (len(_V689_HTF_REJECTS) and len(_V689_HTF_REJECTS) % 64 == 0):
                for _old_key, _old_row in list(_V689_HTF_REJECTS.items()):
                    try:
                        if now - float((_old_row or {}).get("last", now)) > ttl:
                            _V689_HTF_REJECTS.pop(_old_key, None)
                    except Exception:
                        _V689_HTF_REJECTS.pop(_old_key, None)
                if len(_V689_HTF_REJECTS) >= cap:
                    _excess = len(_V689_HTF_REJECTS) - cap + 1
                    _oldest = sorted(
                        _V689_HTF_REJECTS.items(),
                        key=lambda item: float((item[1] or {}).get("last", 0.0) or 0.0),
                    )[:_excess]
                    for _old_key, _ in _oldest:
                        _V689_HTF_REJECTS.pop(_old_key, None)
            row = _V689_HTF_REJECTS.get(key, {"count": 0, "first": now, "last": now})
            if now - float(row.get("first", now)) > ttl:
                row = {"count": 0, "first": now, "last": now}
            row["count"] = int(row.get("count", 0)) + 1
            row["last"] = now
            _V689_HTF_REJECTS[key] = row
            in_window = (now - float(row.get("first", now))) <= float(CONFIG.get("V690_HTF_REPEAT_SUPPRESS_SEC", 1800.0))
            suppressed = row["count"] >= int(CONFIG.get("V690_HTF_REPEAT_SUPPRESS_THRESHOLD", 3)) and in_window
        if suppressed:
            STATS["v690_htf_repeat_suppressed"] = int(STATS.get("v690_htf_repeat_suppressed", 0) or 0) + 1
        STATS["v690_htf_repeat_cache_size"] = len(_V689_HTF_REJECTS)
        return bool(suppressed)
    except Exception:
        return False


_v689_note_htf_repeat = _v690_note_htf_repeat

# -----------------------------------------------------------------------------
# Canonical rescue authority. This is the only function that can mutate the
# V420 rescue state after module initialization.
# -----------------------------------------------------------------------------
def _v690_rescue_evidence(level_hint=None):
    now = WALL_NOW()
    ns = float(STATS.get("v45_no_send_sec", 0.0) or 0.0)
    if ns <= 0:
        ts = float(STATS.get("last_signal_sent_ts", now) or now)
        ns = max(0.0, now - ts)
    blockers = dict(STATS.get("v689_blocker_counts") or {})
    recoverable = sum(int(blockers.get(k, 0) or 0) for k in ("SCORE", "HTF", "POLICY"))
    hard = sum(int(blockers.get(k, 0) or 0) for k in ("FEE", "LIQUIDITY", "SPREAD", "SL", "BALANCE", "EXPOSURE", "EXECUTION", "CRASH"))
    population = int(STATS.get("v690_recoverable_candidate_population", recoverable) or 0)
    share = recoverable / float(max(recoverable + hard, 1))
    if population < int(CONFIG.get("V690_RESCUE_MIN_RECOVERABLE", 3)):
        return False, 0, {"reason": "recoverable_population_below_min", "no_send_sec": ns, "recoverable": recoverable, "hard": hard, "share": share}
    if share < float(CONFIG.get("V690_RESCUE_RECOVERABLE_SHARE_MIN", 0.50)):
        return False, 0, {"reason": "recoverable_share_below_min", "no_send_sec": ns, "recoverable": recoverable, "hard": hard, "share": share}
    thresholds = tuple(float(x) for x in CONFIG.get("V690_RESCUE_MIN_NO_SEND_SEC", (1800.0, 3600.0, 5400.0)))
    computed = 3 if ns >= thresholds[2] else 2 if ns >= thresholds[1] else 1 if ns >= thresholds[0] else 0
    level = computed if level_hint is None else min(computed, max(0, int(level_hint)))
    if level <= 0:
        return False, 0, {"reason": "time_threshold_not_reached", "no_send_sec": ns, "recoverable": recoverable, "hard": hard, "share": share}
    return True, level, {"reason": "evidence_confirmed", "no_send_sec": ns, "recoverable": recoverable, "hard": hard, "share": share}


def _v690_activate_rescue(level: int, reason: str) -> bool:
    try:
        level = max(0, min(3, int(level)))
        if level <= 0 or not bool(CONFIG.get("V45_RESCUE_ENABLE", True)):
            return False
        ok, evidence_level, evidence = _v690_rescue_evidence(level)
        if not ok or evidence_level < level:
            STATS["v690_rescue_activation_blocked"] = int(STATS.get("v690_rescue_activation_blocked", 0) or 0) + 1
            STATS["v690_rescue_blocked_reason"] = str(evidence.get("reason", "evidence_not_ready"))
            STATS["v690_rescue_evidence"] = dict(evidence, eligible=False, requested_level=level)
            return False
        now = MONO_NOW()
        current = int(getattr(_V420State, "rescue_level", 0) or 0)
        last = float(getattr(_V420State, "rescue_last_activation_ts", 0.0) or 0.0)
        cooldown = float(CONFIG.get("V45_RESCUE_COOLDOWN_SEC", 300.0))
        if now - last < cooldown and level <= current:
            return True
        ttl = {1: float(CONFIG.get("V690_RESCUE_L1_TTL_SEC", 600.0)),
               2: float(CONFIG.get("V690_RESCUE_L2_TTL_SEC", 300.0)),
               3: float(CONFIG.get("V690_RESCUE_L3_TTL_SEC", 180.0))}[level]
        _V420State.rescue_level = level
        _V420State.rescue_until_ts = now + ttl
        _V420State.rescue_last_activation_ts = now
        if level >= 1:
            _V420State.relaxed_mode_until_ts = max(float(getattr(_V420State, "relaxed_mode_until_ts", 0.0) or 0.0), now + ttl)
        STATS["v45_rescue_activations"] = int(STATS.get("v45_rescue_activations", 0) or 0) + 1
        STATS["v45_rescue_level"] = level
        STATS["v45_rescue_reason"] = str(reason)
        STATS["v690_rescue_evidence"] = dict(evidence, eligible=True, level=level, requested_level=level)
        _msg = "[V690-Rescue] level=L%s reason=%s ttl=%.0fs recoverable=%s hard=%s share=%.2f" % (level, reason, ttl, evidence["recoverable"], evidence["hard"], evidence["share"])
        if "selftest" in str(reason or "").lower():
            logger.debug(_msg)
        else:
            logger.warning(_msg)
        return True
    except Exception:
        STATS["v690_rescue_activation_blocked"] = int(STATS.get("v690_rescue_activation_blocked", 0) or 0) + 1
        return False


_v45_activate_rescue = _v690_activate_rescue

# One canonical eligibility probe for watchdog/current-cycle rescue paths.
def _v690_rescue_activation_eligible():
    ok, level, evidence = _v690_rescue_evidence()
    STATS["v689_rescue_evidence"] = dict(evidence, eligible=ok, level=level)
    return bool(ok)


_v689_rescue_activation_eligible = _v690_rescue_activation_eligible

# Monotonicity invariants: less restrictive score floor and less risk at higher level.
assert canonical_score_floor_01("base") >= canonical_score_floor_01("rescue", 1) >= canonical_score_floor_01("rescue", 2) >= canonical_score_floor_01("rescue", 3) >= canonical_score_floor_01("hard")
assert float(CONFIG["V690_RESCUE_L1_RISK_FACTOR"]) >= float(CONFIG["V690_RESCUE_L2_RISK_FACTOR"]) >= float(CONFIG["V690_RESCUE_L3_RISK_FACTOR"]) > 0.0

# -----------------------------------------------------------------------------
# MID bounded rescue remains economic/risk constrained; BELOW is absolute.
# -----------------------------------------------------------------------------
def _v690_tier_allowed(family, mode, tier, score_01, features=None):
    try:
        t = str(tier or "").upper()
        if not LiquidityTier.is_tradeable(t):
            return False
        pol = _v690_get_family_policy(mode or family)
        min_t = str(pol.get("min_tier", "MID") or "MID").upper()
        if _FAMILY_RANK.get(t, -1) >= _FAMILY_RANK.get(min_t, 2):
            return True
        if t != "MID" or min_t != "LARGE" or not bool(CONFIG.get("V690_MID_RESCUE_ENABLE", True)):
            return False
        if _v45_rescue_level() < 1:
            return False
        f = dict(features or {})
        score100 = canonical_score_to_100(score_01, "01")
        base100 = canonical_score_to_100(pol.get("min_score", 70.0), "100")
        if score100 < base100 + float(CONFIG.get("V690_MID_RESCUE_SCORE_PREMIUM", 4.0)):
            return False
        if float(f.get("depth_ratio", 0.0) or 0.0) < float(CONFIG.get("V690_MID_RESCUE_MIN_DEPTH_RATIO", 2.20)):
            return False
        if f.get("spread_pct") is not None and float(f["spread_pct"]) > float(CONFIG.get("V690_MID_RESCUE_MAX_SPREAD_PCT", 0.15)):
            return False
        if f.get("chase_atr") is not None and float(f["chase_atr"]) > float(CONFIG.get("V690_MID_RESCUE_MAX_CHASE_ATR", 0.90)):
            return False
        return True
    except Exception:
        return False


_v689_tier_allowed = _v690_tier_allowed

# -----------------------------------------------------------------------------
# Strategy-native LSR validation: direct use of existing V520 authority with
# explicit zone provenance and no current-close fabrication.
# -----------------------------------------------------------------------------
def _v690_lsr_native_contract(df_5m, candidate_features, zone_ref=None):
    fs = dict(candidate_features or {})
    zone = fs.get("swept_low")
    source = "swept_low"
    if zone is None:
        zone = fs.get("sr_support")
        source = "sr_support"
    if zone is None:
        zone = fs.get("strategy_native_recovery_zone")
        source = "strategy_native_recovery_zone"
    if zone is None:
        zone = zone_ref
        source = "zone_ref"
    if zone is None or not math.isfinite(float(zone)):
        return False, "lsr.zone_unverifiable", {"zone_source": "none"}
    try:
        c = df_5m.iloc[-2]
        prev = df_5m.iloc[-3]
        recent = df_5m.iloc[-4:-1] if len(df_5m) >= 4 else df_5m.iloc[:-1]
        zonef = float(zone)
        sweep_like = bool(fs.get("sweep") or fs.get("sweep_detected") or float(c.low) < zonef)
        bullish_close = float(c.close) > float(c.open)
        native_reclaim = bool(fs.get("reclaim") or fs.get("sr_recovery_verified"))
        recent_reclaim = bool(any(float(x.close) >= zonef and float(x.close) >= float(x.open) for _, x in recent.iterrows())) if len(recent) else False
        prior_reclaim = bool(float(prev.close) >= zonef)
        micro_bos = bool(fs.get("micro_bos")) or bool(float(c.close) > float(prev.high))
        bearish_displacement = bool(fs.get("genuine_bearish_displacement")) or (
            float(c.close) < float(c.open) and float(c.close) < zonef and abs(float(c.close) - float(c.open)) > (float(c.high) - float(c.low)) * 0.55
        )
        recovered = bool((sweep_like and (native_reclaim or recent_reclaim or prior_reclaim or micro_bos) and not bearish_displacement))
        detail = {
            "zone": zonef, "zone_source": source, "sweep": sweep_like,
            "bullish_close": bullish_close, "native_reclaim": native_reclaim,
            "recent_reclaim": recent_reclaim, "prior_reclaim": prior_reclaim,
            "micro_bos": micro_bos, "genuine_bearish_displacement": bearish_displacement,
        }
        return recovered, ("lsr.native_recovery" if recovered else "structural.lsr_native_recovery_missing"), detail
    except Exception:
        return False, "lsr.native_contract_error", {"zone_source": source}


# -----------------------------------------------------------------------------
# Spread pending decision helper. Hard ceiling never changes; only a second
# authoritative observation can turn a near-ceiling transient reject into pass.
# -----------------------------------------------------------------------------
def _v690_spread_decision(initial_spread, second_spread, tier):
    try:
        tier_u = str(tier or "").upper()
        ceil = float((CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}).get(tier_u, CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15)))
        initial = float(initial_spread)
        if initial <= ceil:
            return True, "initial_pass", {"spread_before": initial, "spread_after": initial, "ceiling": ceil, "recheck": False}
        near = initial <= ceil + float(CONFIG.get("V690_SPREAD_NEAR_CEILING_TOLERANCE_PCT", 0.06))
        if not near:
            return False, "hard_spread_ceiling", {"spread_before": initial, "spread_after": None, "ceiling": ceil, "recheck": False}
        if second_spread is None or not math.isfinite(float(second_spread)):
            return False, "spread_recheck_unverifiable", {"spread_before": initial, "spread_after": None, "ceiling": ceil, "recheck": True}
        second = float(second_spread)
        return bool(second <= ceil), ("transient_rescued" if second <= ceil else "hard_spread_ceiling_after_recheck"), {
            "spread_before": initial, "spread_after": second, "ceiling": ceil, "recheck": True,
        }
    except Exception:
        return False, "spread_recheck_error", {}

# -----------------------------------------------------------------------------
# Candidate state / selected→builder telemetry. No execution bypass.
# -----------------------------------------------------------------------------
def _v690_handoff_snapshot(candidate, snapshot):
    fs = getattr(candidate, "features_snapshot", None)
    if not isinstance(fs, dict):
        return None
    snap = snapshot if isinstance(snapshot, dict) else {}
    data = {
        "candidate_id": str(getattr(candidate, "candidate_id", "") or id(candidate)),
        "symbol": str(getattr(candidate, "symbol", "") or snap.get("symbol", "")),
        "family": str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper(),
        "strategy_mode": str(getattr(candidate, "strategy_mode", "") or "").upper(),
        "cycle_id": str(snap.get("cycle_id") or STATS.get("v669_last_cycle_id") or globals().get("_V517_ACTIVE_CYCLE_ID") or "0"),
        "candle_ts": _v689_candle_ts(snap),
        "fingerprint": _v690_prequal_fingerprint(candidate, snap),
        "truth_fingerprint": _v690_truth_fingerprint(candidate, snap),
        "policy_revision": CanonicalStrategyPolicyRegistry.revision(),
        "canonical_authority_version": V690_ROOT_CLOSURE_IDENTITY,
        "selected_at": WALL_NOW(),
    }
    fs["v690_selected_handoff"] = data
    return data


def _v690_mark_builder_result(candidate, accepted, reason=""):
    fs = getattr(candidate, "features_snapshot", None)
    if not isinstance(fs, dict):
        return
    handoff = fs.get("v690_selected_handoff") or {}
    current = {"accepted": bool(accepted), "reason": str(reason), "timestamp": WALL_NOW()}
    fs["v690_builder_result"] = current
    if handoff:
        if bool(accepted):
            STATS["v690_selected_to_builder_accept"] = int(STATS.get("v690_selected_to_builder_accept", 0) or 0) + 1
        else:
            STATS["v690_selected_to_builder_reject"] = int(STATS.get("v690_selected_to_builder_reject", 0) or 0) + 1

# -----------------------------------------------------------------------------
# Candidate churn fingerprint and bounded event qualification.
# -----------------------------------------------------------------------------
def _v690_setup_fingerprint(candidate, snapshot):
    fs = dict(getattr(candidate, "features_snapshot", {}) or {})
    native = {k: fs.get(k) for k in ("sweep", "reclaim", "bos_confirmed", "micro_bos", "higher_low", "bullish_close", "zone_ref", "swept_low") if k in fs}
    payload = {
        "symbol": str(getattr(candidate, "symbol", "")),
        "family": str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "")).upper(),
        "strategy_mode": str(getattr(candidate, "strategy_mode", "")).upper(),
        "candle_ts": _v689_candle_ts(snapshot if isinstance(snapshot, dict) else {}),
        "native": native,
    }
    return hashlib.sha256(json.dumps(payload, sort_keys=True, default=str, separators=(",", ":")).encode()).hexdigest()[:24]


def _v690_event_triggered(snapshot):
    try:
        if not isinstance(snapshot, dict):
            return False
        ret = abs(float(snapshot.get("short_return_pct", snapshot.get("return_pct", 0.0)) or 0.0))
        accel = abs(float(snapshot.get("acceleration_pct", 0.0) or 0.0))
        vol = float(snapshot.get("volume_ratio", 0.0) or 0.0)
        vr = float(snapshot.get("volatility_expansion_ratio", 0.0) or 0.0)
        sweep = bool(snapshot.get("confirmed_sweep"))
        breakout = bool(snapshot.get("confirmed_breakout"))
        return bool(ret >= float(CONFIG.get("V690_EVENT_RETURN_ABS_PCT", 5.0)) or accel >= 2.0 or vol >= 2.5 or vr >= 1.8 or sweep or breakout)
    except Exception:
        return False

# -----------------------------------------------------------------------------
# Family starvation and explicit cycle-owned funnel dashboard.
# -----------------------------------------------------------------------------
def _v690_family_starvation_snapshot(now=None):
    now = float(now if now is not None else WALL_NOW())
    out = {}
    last = dict(STATS.get("v689_family_last_live_ts") or {})
    funnel = dict(STATS.get("v689_family_funnel") or {})
    families = set(funnel) | set(last) | {str(x).upper() for x in CONFIG.get("V689_ACTIVE_FAMILIES", ())}
    for fam in sorted(families):
        ts = float(last.get(fam, 0.0) or 0.0)
        age = now - ts if ts > 0 else float("inf")
        row = dict(funnel.get(fam) or {})
        generated = int(row.get("generated", 0) or 0)
        prequal = int(row.get("prequal", 0) or 0)
        ranked = int(row.get("ranked", 0) or 0)
        selected = int(row.get("selected", 0) or 0)
        queued = int(row.get("queued", 0) or 0)
        sent = int(row.get("sent", 0) or 0)
        if sent > 0:
            state = "STARVED" if age >= float(CONFIG.get("V690_FAMILY_STARVATION_SEC", 14400.0)) else ("WATCH" if age >= float(CONFIG.get("V690_FAMILY_STARVATION_SEC", 14400.0)) / 2 else "NORMAL")
        elif generated > 0:
            state = "STRUCTURALLY_BLOCKED" if prequal == 0 and ranked == 0 else ("POLICY_BLOCKED" if selected == 0 else "WATCH")
        else:
            state = "NORMAL"
        out[fam] = {
            "last_live_ts": ts, "no_send_sec": age, "generated": generated,
            "prequal": prequal, "ranked": ranked, "selected": selected,
            "queued": queued, "sent": sent, "starvation_state": state,
        }
    STATS["v690_family_starvation"] = out
    return out


_v689_family_starvation_snapshot = _v690_family_starvation_snapshot


def _v690_funnel_snapshot():
    # Cycle-owned data is preferred; process lifetime counters remain separate.
    cycle = dict(STATS.get("v681_last_cycle_funnel") or STATS.get("v689_cycle_funnel") or {})
    counts = {
        "generated": int(cycle.get("generated", STATS.get("mse_generated", 0)) or 0),
        "hard_valid": int(cycle.get("hard_valid", STATS.get("mse_hard_valid", 0)) or 0),
        "prequal": int(cycle.get("prequal", STATS.get("v688_mse_canonical_prequal_passes", 0)) or 0),
        "ranked": int(cycle.get("ranked", STATS.get("mse_ranked", 0)) or 0),
        "selected": int(cycle.get("selected", STATS.get("mse_winners", 0)) or 0),
        "builder_accept": int(cycle.get("builder", STATS.get("v689_builder_accept", 0)) or 0),
        "live_ready": int(cycle.get("live_ready", STATS.get("v534_live_ready", 0)) or 0),
        "presend": int(cycle.get("presend", STATS.get("v689_presend_pass", 0)) or 0),
        "queued": int(cycle.get("queued", STATS.get("signals_queued", 0)) or 0),
        "send_attempt": int(cycle.get("send_attempt", STATS.get("execution_attempts", STATS.get("exec_try", 0))) or 0),
        "sent": int(cycle.get("sent", STATS.get("signals_sent", 0)) or 0),
    }
    def ratio(dst, src):
        den = float(counts[src]); return (counts[dst] / den) if den > 0 else None
    ratios = {
        "G_to_HV": ratio("hard_valid", "generated"),
        "G_to_PQ": ratio("prequal", "generated"),
        "PQ_to_RANK": ratio("ranked", "prequal"),
        "RANK_to_SEL": ratio("selected", "ranked"),
        "SEL_to_BUILDER": ratio("builder_accept", "selected"),
        "BUILDER_to_READY": ratio("live_ready", "builder_accept"),
        "READY_to_PRESEND": ratio("presend", "live_ready"),
        "READY_to_Q": ratio("queued", "live_ready"),
        "Q_to_S": ratio("sent", "queued"),
    }
    alerts = []
    if counts["generated"] > 0 and (ratios["G_to_PQ"] or 0.0) < 0.05:
        alerts.append("PREQUAL_COLLAPSE")
    if counts["selected"] > 0 and (ratios["SEL_to_BUILDER"] or 0.0) < 0.50:
        alerts.append("SELECTED_BUILDER_COLLAPSE")
    if counts["builder_accept"] > 0 and counts["queued"] == 0:
        alerts.append("BUILDER_QUEUE_COLLAPSE")
    if counts["queued"] > 0 and counts["sent"] == 0:
        alerts.append("QUEUE_SEND_COLLAPSE")
    return {"counts": counts, "ratios": ratios, "alerts": alerts,
            "cycle_scope": "active_cycle" if cycle else "fallback_runtime_snapshot",
            "family_starvation": _v690_family_starvation_snapshot()}


_v689_funnel_snapshot = _v690_funnel_snapshot

