def _v692_truth_changed(candidate, snapshot):
    try:
        fs = getattr(candidate, "features_snapshot", {}) or {}
        stored = dict(fs.get("v690_selected_handoff") or {})
        if not stored:
            stored = dict(fs.get("v688_prequal_verdict") or {})
        if not stored:
            return True
        current_fp = _v690_truth_fingerprint(candidate, snapshot)
        current_pf = _v690_prequal_fingerprint(candidate, snapshot)
        old_truth = str(stored.get("truth_fingerprint") or "")
        old_fp = str(stored.get("fingerprint") or fs.get("fingerprint") or "")
        # A legacy v688 verdict stores only the prequal fingerprint. In that case
        # compare the stronger current fingerprint first and requalify if absent.
        return bool((old_truth and old_truth != current_fp) or (old_fp and old_fp != current_pf))
    except Exception:
        return True


def _v692_hard_bearish(snapshot):
    try:
        s = snapshot if isinstance(snapshot, dict) else {}
        regime = str(s.get("regime", s.get("macro_regime", "")) or "").upper()
        state = str(s.get("htf_state", "") or "").upper()
        severity = str(s.get("macro_severity", s.get("bearish_severity", "")) or "").upper()
        if state in {"BEARISH", "HARD_REJECT", "CRASH", "BEARISH_CRASH"}:
            return True
        if bool(s.get("crash", False)) or severity in {"CRASH", "BEARISH_CRASH"}:
            return True
        if regime == "BEARISH" and severity in {"BEARISH_STRESSED", "CRASH", "BEARISH_CRASH"}:
            return True
        return bool(s.get("genuine_bearish_displacement", False))
    except Exception:
        return True


def _v692_htf_recovery_snapshot(candidate, snapshot):
    """Build one bounded HTF-recovery view from existing prepared facts.

    Raw HTF truth is never overwritten. The recovery view is explicitly tagged
    and is bounded by the existing V690 H0 cap / strategy bridge.
    """
    if not bool(CONFIG.get("V692_HTF_RECOVERY_ENABLE", True)):
        return None
    try:
        snap = dict(snapshot or {})
        family = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
        mode = str(getattr(candidate, "strategy_mode", "") or family).upper()
        regime = str(snap.get("regime", snap.get("macro_regime", "")) or "").upper()
        local = str(snap.get("local_regime", "") or "").upper()
        if _v692_hard_bearish(snap):
            return None
        if regime not in {"BULLISH", "NEUTRAL"}:
            return None
        if local not in {"LOCAL_BULLISH", "LOCAL_RECOVERY", "NON_BEARISH", ""}:
            return None

        raw = snap.get("htf_strength")
        try:
            raw_val = float(raw) if raw is not None else 0.0
        except Exception:
            raw_val = 0.0
        htf_pass = snap.get("htf_pass")
        # Only recover when the current canonical state is actually a failed /
        # unusable classification, never when a valid HTF pass exists.
        if htf_pass is True:
            return None

        eff, source, _ = _v690_resolve_htf_strength(str(getattr(candidate, "symbol", "") or snap.get("symbol", "")), snap, candidate)
        if eff is None:
            return None

        # Existing V687 bridge is strategy-aware and can strengthen a healthy
        # continuation context; it remains bounded and never changes raw truth.
        bridge_ok = False
        bridge_strength = float(eff)
        bridge_ctx = {}
        try:
            bridge_ok, bridge_strength, bridge_ctx = _v518_neutral_local_htf_bridge(
                snap.get("df_1h"), snap.get("df_4h"), snap.get("df_15m"), snap.get("df_5m"),
                regime, local, float(eff), mode or family,
            )
        except Exception:
            bridge_ok = False

        effective = max(float(eff), float(bridge_strength) if bridge_ok else float(eff))
        if source == "RECOMPUTED_H0":
            effective = min(effective, float(CONFIG.get("V692_HTF_RECOMPUTE_MAX", 55.0)))

        # Do not create a fake full alignment. This is only a strategy recovery
        # context and the family policy floor still applies to effective strength.
        out = dict(snapshot or {})
        out.update({
            "htf_pass": True,
            "htf_strength": effective,
            "htf_primary_strength": raw_val,
            "htf_effective_strength_for_strategy": effective,
            "htf_recovery_source": source if source != "RAW" else ("BRIDGE" if bridge_ok else "RAW_RECOVERY"),
            "htf_bridge_pass": bool(bridge_ok),
            "htf_bridge_strength": float(bridge_strength) if bridge_ok else None,
            "htf_recovery_used": True,
            "htf_evidence_class": "HTF_RECOVERY_ALIGNMENT" if source != "RAW_HARD_REJECT" else "HTF_HARD_REJECT",
        })
        STATS["v692_htf_recovery_attempts"] = int(STATS.get("v692_htf_recovery_attempts", 0) or 0) + 1
        return out
    except Exception:
        return None


def _v692_recovery_allowed_for_reason(reason):
    r = str(reason or "").lower()
    return (
        "htf.core_not_aligned" in r
        or r.startswith("htf.family_htf_strength_below_floor")
        or "family_htf_strength_below_floor" in r
        or "liquidity.family_tier_below_floor" in r
        or "family_tier_below_floor" in r
        or "microstruct_parity" in r
        or "fake_break_detected" in r
        or r.startswith("structural.lsr")
        or r.startswith("lsr.")
    )


def _v692_lsr_recovery_candidate(candidate, snapshot):
    if not bool(CONFIG.get("V692_LSR_NATIVE_RECOVERY_ENABLE", True)):
        return False, "disabled", {}
    try:
        family = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
        if family != "LIQUIDITY_SWEEP_REVERSAL":
            return False, "family_not_lsr", {}
        fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        zone_ref = getattr(candidate, "zone_ref", None)
        ok, reason, detail = _v690_lsr_native_contract(snapshot.get("df_5m"), fs, zone_ref)
        return bool(ok), str(reason), dict(detail or {})
    except Exception as exc:
        return False, f"lsr.native_contract_error:{type(exc).__name__}", {}


def _v692_canonical_prequal(ranked, snap_by_symbol):
    """Terminal canonical prequalification authority.

    Normal decision is evaluated once. Only a narrow recoverable semantic
    blocker can enter a single bounded recovery attempt, which then re-enters
    the SAME base authority with one coherent prepared snapshot.
    """
    try:
        candidate = getattr(ranked, "candidate", None)
        if candidate is None:
            return False, "canonical_prequal.missing_candidate"
        symbol = str(getattr(candidate, "symbol", "") or "")
        snap = (snap_by_symbol or {}).get(symbol) if isinstance(snap_by_symbol, dict) else None
        if not isinstance(snap, dict):
            return False, "canonical_prequal.missing_snapshot"

        # Exact reusable verdict: no second semantic interpretation of identical
        # facts. Safety-critical current facts remain downstream live gates.
        if bool(CONFIG.get("V692_BUILDER_REUSE_CANONICAL_ENABLE", True)):
            verdict = (getattr(candidate, "features_snapshot", {}) or {}).get("v688_prequal_verdict") or {}
            if bool(verdict.get("verdict")) and _v690_prequal_snapshot_reusable(candidate, snap):
                STATS["v692_prequal_reuse_hits"] = int(STATS.get("v692_prequal_reuse_hits", 0) or 0) + 1
                _v690_record_prequal(candidate, snap, True, "canonical_prequal_reuse")
                return True, "canonical_prequal_reuse"

        base = _V692_BASE_PREQUAL
        if not callable(base):
            return False, "canonical_prequal.base_unavailable"
        ok, reason = base(ranked, {symbol: snap})
        reason = str(reason or "")
        if ok:
            _v690_record_prequal(candidate, snap, True, reason or "pass")
            _v690_handoff_snapshot(candidate, snap)
            STATS["v692_prequal_pass"] = int(STATS.get("v692_prequal_pass", 0) or 0) + 1
            return True, reason or "pass"

        # One recovery attempt only; never stack recoveries.
        if not _v692_recovery_allowed_for_reason(reason):
            _v690_record_prequal(candidate, snap, False, reason)
            return False, reason
        fs = getattr(candidate, "features_snapshot", {}) or {}
        attempts = int(fs.get("v692_recovery_attempts", 0) or 0)
        if attempts >= int(CONFIG.get("V692_MAX_RECOVERY_PER_CANDIDATE", 1)):
            return False, reason
        fs["v692_recovery_attempts"] = attempts + 1

        family = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
        mode = str(getattr(candidate, "strategy_mode", "") or family).upper()

        # LSR receives the family-native structure ruler instead of inheriting
        # a generic pullback/fake-break rule. No zone fabrication is permitted.
        if family == "LIQUIDITY_SWEEP_REVERSAL" and ("microstruct" in reason.lower() or "fake_break" in reason.lower() or "structural" in reason.lower() or reason.lower().startswith("lsr.")):
            lsr_ok, lsr_reason, lsr_ctx = _v692_lsr_recovery_candidate(candidate, snap)
            if lsr_ok:
                _new = dict(snap)
                _new["v692_lsr_native_recovery"] = True
                _new["v692_lsr_native_recovery_ctx"] = dict(lsr_ctx or {})
                # Re-run only the non-structure portion by using a narrow
                # structure-recovery handoff marker recognized at the final
                # boundary. The underlying base authority remains authoritative
                # for score/economics/HTF/policy; no order is created here.
                # To avoid globally disabling structure, we require the native
                # contract itself to be complete and preserve the rejection
                # details for downstream telemetry.
                _old = globals().get("_v520_microstructure_parity")
                try:
                    if callable(_old):
                        globals()["_v520_microstructure_parity"] = lambda *a, **k: (True, {"reason": "lsr.native_recovery", "canonical_native": True})
                    ok2, reason2 = base(ranked, {symbol: _new})
                finally:
                    if callable(_old):
                        globals()["_v520_microstructure_parity"] = _old
                if ok2:
                    fs["v692_lsr_native_recovery"] = dict(lsr_ctx or {})
                    _v690_record_prequal(candidate, _new, True, "lsr.native_recovery")
                    _v690_handoff_snapshot(candidate, _new)
                    STATS["v692_lsr_recoveries"] = int(STATS.get("v692_lsr_recoveries", 0) or 0) + 1
                    return True, "lsr.native_recovery"

        # HTF recovery path: only non-bearish, evidence-backed, single retry.
        if any(x in reason.lower() for x in ("htf", "family_htf_strength")):
            rec = _v692_htf_recovery_snapshot(candidate, snap)
            if rec is not None:
                try:
                    ok2, reason2 = base(ranked, {symbol: rec})
                except Exception:
                    ok2, reason2 = False, "htf.recovery_requalify_exception"
                if ok2:
                    fs["v692_htf_recovery"] = {
                        "raw": rec.get("htf_primary_strength"),
                        "effective": rec.get("htf_effective_strength_for_strategy", rec.get("htf_strength")),
                        "source": rec.get("htf_recovery_source"),
                        "bridge": bool(rec.get("htf_bridge_pass")),
                    }
                    _v690_record_prequal(candidate, rec, True, "htf.recovery_alignment")
                    _v690_handoff_snapshot(candidate, rec)
                    STATS["v692_htf_recovery_pass"] = int(STATS.get("v692_htf_recovery_pass", 0) or 0) + 1
                    return True, "htf.recovery_alignment"

        # Tier preference rescue. Tradeability remains absolute, and MID rescue
        # must satisfy the existing bounded V690 compensation requirements.
        if bool(CONFIG.get("V692_TIER_RECOVERY_ENABLE", True)) and "family_tier_below_floor" in reason.lower():
            tier = str(snap.get("tier") or "").upper()
            score01 = canonical_score_to_01(getattr(candidate, "engine_score", 0.0), None)
            if _v690_tier_allowed(family, mode, tier, score01, getattr(candidate, "features_snapshot", {}) or {}):
                fs["v692_tier_recovery"] = {
                    "tier": tier,
                    "risk_factor": float(CONFIG.get("V690_MID_RESCUE_RISK_FACTOR", 0.50)),
                    "bounded": True,
                }
                _v690_record_prequal(candidate, snap, True, "tier.bounded_rescue")
                _v690_handoff_snapshot(candidate, snap)
                STATS["v692_tier_recovery_pass"] = int(STATS.get("v692_tier_recovery_pass", 0) or 0) + 1
                return True, "tier.bounded_rescue"

        _v690_record_prequal(candidate, snap, False, reason)
        return False, reason
    except Exception as exc:
        return False, f"canonical_prequal.exception:{type(exc).__name__}"


# Terminal public prequal authority: one exposed function name, one runtime owner.
_v453_prequalify = _v692_canonical_prequal


def _v692_builder_precheck(symbol: str, candidate: Any, snapshot: Dict[str, Any]):
    """Builder parity closure. Reuse canonical verdict when facts are stable.

    This function does not replace execution safety. It prevents the historical
    selected->builder collapse caused by replaying strategy policy/HTF/tier on
    the same immutable snapshot twice.
    """
    ctx = {"symbol": str(symbol or ""), "family": str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper(),
           "strategy_mode": str(getattr(candidate, "strategy_mode", "") or getattr(candidate, "family", "") or "").upper(),
           "tier": str((snapshot or {}).get("tier") or "").upper()}
    if not bool(CONFIG.get("V692_BUILDER_REUSE_CANONICAL_ENABLE", True)):
        return False, "disabled", ctx
    if candidate is None or not isinstance(snapshot, dict):
        return False, "preflight.missing_candidate_or_snapshot", ctx
    try:
        age = _wall_age_sec(getattr(candidate, "generated_at_ms", None))
        ctx["candidate_age_sec"] = age
        max_age = min(float(CONFIG.get("V690_CANDIDATE_MAX_AGE_SEC", 540.0)),
                      float(CONFIG.get("V542_EXECUTION_PARITY_MAX_CANDIDATE_AGE_SEC", 540.0)))
        if age is None or age > max_age:
            return False, "freshness.stale_candidate", ctx
    except Exception:
        return False, "freshness.unverifiable", ctx

    # Reuse is valid only when a canonical pass exists and truth has not changed.
    fs = getattr(candidate, "features_snapshot", {}) or {}
    verdict = fs.get("v688_prequal_verdict") or {}
    if bool(verdict.get("verdict")) and _v690_prequal_snapshot_reusable(candidate, snapshot) and not _v692_truth_changed(candidate, snapshot):
        ctx.update({
            "reuse_canonical_prequal": True,
            "canonical_reason": str(verdict.get("reason") or "pass"),
            "fingerprint": _v690_prequal_fingerprint(candidate, snapshot),
            "truth_fingerprint": _v690_truth_fingerprint(candidate, snapshot),
            "policy_revision": CanonicalStrategyPolicyRegistry.revision(),
        })
        try:
            _v690_mark_builder_result(candidate, True, "canonical_prequal_reuse")
        except Exception:
            pass
        STATS["v692_builder_reused_prequal"] = int(STATS.get("v692_builder_reused_prequal", 0) or 0) + 1
        return True, "canonical_prequal_reuse", ctx

    # Truth changed: re-run the SAME terminal prequal once; no legacy duplicate
    # family-policy replay is allowed here.
    fs["v692_builder_truth_changed"] = True
    ctx["truth_changed"] = True
    try:
        entry = float(getattr(candidate, "entry_ref", 0.0) or 0.0)
        sl = float(getattr(candidate, "sl_price", 0.0) or 0.0)
        risk = max(entry - sl, 0.0)
        ranked = RankedCandidate(
            candidate=candidate,
            composite=float(getattr(candidate, "engine_score", 0.0) or 0.0),
            tp1_abs=entry + float(getattr(candidate, "tp1_rr", 0.0) or 0.0) * risk,
            tp2_abs=entry + float(getattr(candidate, "tp2_rr", 0.0) or 0.0) * risk,
            tp3_abs=entry + float(getattr(candidate, "tp3_rr", 0.0) or 0.0) * risk,
        )
        _terminal_prequal = globals().get("_v702_public_prequal")
        if callable(_terminal_prequal):
            ok, reason = _terminal_prequal(ranked, {str(symbol): snapshot})
            ctx["terminal_owner"] = "V702_PUBLIC_PREQUAL"
        else:
            ok, reason = _v692_canonical_prequal(ranked, {str(symbol): snapshot})
            ctx["terminal_owner"] = "V692_CANONICAL_PREQUAL_FALLBACK"
        ctx["requalified"] = True
        ctx["requal_reason"] = str(reason)
        if ok:
            STATS["v692_builder_requalified"] = int(STATS.get("v692_builder_requalified", 0) or 0) + 1
            try: _v690_mark_builder_result(candidate, True, "canonical_requalify_pass")
            except Exception: pass
            return True, "canonical_requalify_pass", ctx
        try: _v690_mark_builder_result(candidate, False, str(reason))
        except Exception: pass
        STATS["v692_builder_requalify_reject"] = int(STATS.get("v692_builder_requalify_reject", 0) or 0) + 1
        return False, str(reason), ctx
    except Exception as exc:
        try: _v690_mark_builder_result(candidate, False, f"preflight.exception:{type(exc).__name__}")
        except Exception: pass
        return False, f"preflight.exception:{type(exc).__name__}", ctx


