def _v693_rescue_score_floor_01(level: int) -> float:
    try:
        lvl = max(1, min(3, int(level)))
        vals = tuple(float(x) for x in CONFIG.get("V693_RESCUE_SCORE_LEVELS_01", (0.53, 0.52, 0.51)))
        return vals[lvl - 1]
    except Exception:
        return 0.50


def _v693_active_rejection_counts(window_sec: float = 720.0) -> dict:
    """Derive blocker truth from the active-cycle ledger, never from stale history."""
    out = {k: 0 for k in ("SYSTEM", "POLICY", "HTF", "LIQUIDITY", "STRUCTURE", "SCORE", "FEE", "PRE_SEND", "EXECUTION", "OTHER")}
    try:
        cid = int(globals().get("_V517_ACTIVE_CYCLE_ID") or STATS.get("v681_runtime_cycle_id", 0) or STATS.get("v680_last_cycle_id", 0) or 0)
        current = V669RejectionLedger.current_cycle(cid)
        if not current:
            return out
        now = WALL_NOW()
        for row in current:
            try:
                ts = float(row.get("timestamp", row.get("ts", now)) or now)
                if ts > 1e12:
                    ts /= 1000.0
                if max(0.0, now - ts) > float(window_sec):
                    continue
                bucket = str(row.get("bucket") or row.get("taxonomy_bucket") or "OTHER").upper()
                if bucket not in out:
                    bucket = "OTHER"
                out[bucket] += 1
            except Exception:
                continue
    except Exception:
        pass
    return out


def _v693_rescue_evidence(level_hint=None):
    """Final bounded rescue evidence; hard blockers can veto but never activate rescue."""
    try:
        now = WALL_NOW()
        ns = float(STATS.get("v45_no_send_sec", 0.0) or 0.0)
        if ns <= 0:
            last = float(STATS.get("last_signal_sent_ts", now) or now)
            ns = max(0.0, now - last)
        counts = dict(STATS.get("v689_blocker_counts") or {})
        active = _v693_active_rejection_counts(720.0)
        # Active-cycle truth wins when available; cumulative-like counters are a
        # fallback only for missing buckets.
        merged = {}
        for key in active:
            merged[key] = max(int(active.get(key, 0) or 0), int(counts.get(key, 0) or 0))
        recoverable = sum(int(merged.get(k, 0) or 0) for k in ("SCORE", "HTF", "POLICY"))
        # STRUCTURE is intentionally NOT a rescue cause. Hard economic and
        # execution hazards are also never recoverable.
        hard = sum(int(merged.get(k, 0) or 0) for k in ("SYSTEM", "LIQUIDITY", "FEE", "PRE_SEND", "EXECUTION"))
        eligible_population = max(
            recoverable,
            int(STATS.get("v690_recoverable_candidate_population", 0) or 0),
            int(STATS.get("v688_mse_canonical_prequal_rejects", 0) or 0),
        )
        share = recoverable / float(max(recoverable + hard, 1))
        thresholds = tuple(float(x) for x in CONFIG.get("V690_RESCUE_MIN_NO_SEND_SEC", (1800.0, 3600.0, 5400.0)))
        computed = 3 if ns >= thresholds[2] else 2 if ns >= thresholds[1] else 1 if ns >= thresholds[0] else 0
        level = computed if level_hint is None else min(computed, max(0, int(level_hint)))
        evidence = {
            "no_send_sec": ns,
            "recoverable": recoverable,
            "hard": hard,
            "share": share,
            "eligible_population": eligible_population,
            "active_cycle_counts": active,
            "level": level,
        }
        if level <= 0:
            evidence["reason"] = "time_threshold_not_reached"
            return False, 0, evidence
        if eligible_population < int(CONFIG.get("V690_RESCUE_MIN_RECOVERABLE", 3)):
            evidence["reason"] = "recoverable_population_below_min"
            return False, 0, evidence
        if share < float(CONFIG.get("V690_RESCUE_RECOVERABLE_SHARE_MIN", 0.50)):
            evidence["reason"] = "recoverable_share_below_min"
            return False, 0, evidence
        if hard > 0 and recoverable <= hard:
            evidence["reason"] = "hard_blockers_not_outvoted"
            return False, 0, evidence
        evidence["reason"] = "evidence_confirmed"
        return True, level, evidence
    except Exception as exc:
        return False, 0, {"reason": f"exception:{type(exc).__name__}"}


def _v693_activate_rescue(level: int, reason: str) -> bool:
    """Canonical rescue activation; live score floor is never below 70."""
    try:
        # Recovery can help context/selection, but it may not weaken entry
        # admission while any system, balance, execution or protection hazard is active.
        try:
            _rescue_hazard = _v453_safety_hazard()
        except Exception:
            _rescue_hazard = "safety_hazard_check_failed"
        if _rescue_hazard:
            STATS["v693_rescue_activation_blocked"] = int(STATS.get("v693_rescue_activation_blocked", 0) or 0) + 1
            STATS["v693_rescue_blocked_reason"] = f"safety_hazard:{str(_rescue_hazard)[:100]}"
            STATS["v693_rescue_evidence"] = {"eligible":False,"requested_level":int(level or 0),"reason":"safety_hazard","hazard":str(_rescue_hazard)[:120]}
            return False
        level = max(0, min(3, int(level)))
        if level <= 0 or not bool(CONFIG.get("V45_RESCUE_ENABLE", True)):
            return False
        ok, evidence_level, evidence = _v693_rescue_evidence(level)
        if not ok or evidence_level < level:
            STATS["v693_rescue_activation_blocked"] = int(STATS.get("v693_rescue_activation_blocked", 0) or 0) + 1
            STATS["v693_rescue_blocked_reason"] = str(evidence.get("reason", "evidence_not_ready"))
            STATS["v693_rescue_evidence"] = dict(evidence, eligible=False, requested_level=level)
            return False
        now_mono = MONO_NOW()
        current = int(getattr(_V420State, "rescue_level", 0) or 0)
        last = float(getattr(_V420State, "rescue_last_activation_ts", 0.0) or 0.0)
        cooldown = float(CONFIG.get("V45_RESCUE_COOLDOWN_SEC", 300.0))
        ttl = {1: float(CONFIG.get("V690_RESCUE_L1_TTL_SEC", 600.0)),
               2: float(CONFIG.get("V690_RESCUE_L2_TTL_SEC", 300.0)),
               3: float(CONFIG.get("V690_RESCUE_L3_TTL_SEC", 180.0))}[level]
        if now_mono - last < cooldown and level <= current:
            return True
        _V420State.rescue_level = level
        _V420State.rescue_until_ts = now_mono + ttl
        _V420State.rescue_last_activation_ts = now_mono
        _V420State.relaxed_mode_until_ts = max(float(getattr(_V420State, "relaxed_mode_until_ts", 0.0) or 0.0), now_mono + ttl)
        # THIS is the missing coupling in the prior runtime: the rescue level
        # must actually lower only the canonical adaptive score floor.
        base100 = max(70.0, float(CONFIG.get("MIN_LIVE_SCORE", 70.0)))
        hard100 = canonical_score_floor_100("hard")
        requested_target100 = max(hard100 + 0.01, canonical_score_to_100(_v693_rescue_score_floor_01(level), "01"))
        # Rescue may relax only secondary elite thresholds down to the global
        # live floor. It cannot make a <70 live candidate admissible.
        target100 = max(70.0, min(base100, requested_target100))
        cur = max(70.0, float(getattr(_V420State, "adaptive_floor", base100) or base100))
        _V420State.adaptive_floor = max(70.0, min(cur, target100))
        STATS["v45_rescue_activations"] = int(STATS.get("v45_rescue_activations", 0) or 0) + 1
        STATS["v693_rescue_active_floor"] = float(_V420State.adaptive_floor)
        STATS["v693_rescue_evidence"] = dict(evidence, eligible=True, requested_level=level, reason=str(reason), applied_floor=float(_V420State.adaptive_floor))
        _rescue_msg = (
            "[V693-RESCUE] level=%d reason=%s no_send=%.0fs recoverable=%d share=%.2f score_floor=%.1f ttl=%.0fs"
            % (level, reason, float(evidence.get("no_send_sec", 0.0)), int(evidence.get("recoverable", 0)),
               float(evidence.get("share", 0.0)), float(_V420State.adaptive_floor), ttl)
        )
        if "selftest" in str(reason or "").lower():
            logger.debug(_rescue_msg)
        else:
            logger.info(_rescue_msg)
        return True
    except Exception as exc:
        STATS["v693_rescue_activation_errors"] = int(STATS.get("v693_rescue_activation_errors", 0) or 0) + 1
        return False


_v45_activate_rescue = _v693_activate_rescue

