def _v693_native_context_recovery(candidate, snapshot, prior_reason: str):
    """Strategy-native local-context recovery; bounded to closed-bar evidence."""
    if not bool(CONFIG.get("V693_CONTEXT_RECOVERY_ENABLE", True)):
        return None
    try:
        c = getattr(candidate, "candidate", candidate)
        fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
        if fam not in {
            "PULLBACK", "MTF_PULLBACK", "BREAKOUT_RETEST", "BREAKOUT_CONTINUATION",
            "TREND_CONTINUATION", "LIQUIDITY_SWEEP_REVERSAL", "MEAN_REVERSION", "MOMENTUM_EXPANSION",
        }:
            return None
        if "family_regime_disallowed" not in str(prior_reason).lower():
            return None
        snap = dict(snapshot or {})
        regime = str(snap.get("regime", snap.get("macro_regime", "")) or "").upper()
        local = str(snap.get("local_regime", "") or "").upper()
        if regime != "BULLISH" or local not in {"NON_BEARISH", "LOCAL_NEUTRAL", "", "NEUTRAL"}:
            return None
        if _v692_hard_bearish(snap):
            return None
        fs = dict(getattr(c, "features_snapshot", {}) or {})
        # Closed-bar evidence is the only source used here. No network fetch.
        d5 = snap.get("df_5m")
        if d5 is None or len(d5) < 20:
            return None
        close = float(d5["close"].iloc[-2]); open_ = float(d5["open"].iloc[-2])
        bullish = close > open_
        higher_low = bool(float(d5["low"].iloc[-2]) > float(d5["low"].iloc[-3]) >= float(d5["low"].iloc[-4]))
        ema20 = d5["close"].ewm(span=20, adjust=False).mean()
        ema_slope = bool(float(ema20.iloc[-2]) > float(ema20.iloc[-7])) if len(ema20) >= 8 else False
        zone = getattr(c, "zone_ref", None)
        reclaim = False
        if zone is not None:
            try:
                zonef = float(zone)
                reclaim = bool(float(d5["close"].iloc[-3]) < zonef <= close)
            except Exception:
                reclaim = False
        anchors = [bullish, higher_low, ema_slope, reclaim]
        chase = fs.get("chase_atr", snap.get("chase_atr", 0.0))
        try:
            chase = float(chase or 0.0)
        except Exception:
            return None
        if not math.isfinite(chase) or chase > float(CONFIG.get("V693_CONTEXT_RECOVERY_MAX_CHASE_ATR", 0.90)):
            return None
        htf = _v690_resolve_htf_strength(str(getattr(c, "symbol", "") or snap.get("symbol", "")), snap, c)
        strength = htf[0]
        if strength is None or float(strength) <= 0:
            return None
        # Family-specific proof requirements. Hard breakout/LSR cases never gain
        # a generic local-regime bypass; they need their native anchors already.
        required = int(CONFIG.get("V693_CONTEXT_RECOVERY_MIN_ANCHORS_PB", 2))
        if fam == "MTF_PULLBACK":
            required = int(CONFIG.get("V693_CONTEXT_RECOVERY_MIN_ANCHORS_MTF", 3))
            if float(strength) < 58.0:
                return None
        elif fam in {"BREAKOUT_RETEST", "BREAKOUT_CONTINUATION"}:
            bos, _ = MicroStructure.micro_bos_confirm(d5)
            if not bool(bos or reclaim):
                return None
            required = 3
        elif fam == "LIQUIDITY_SWEEP_REVERSAL":
            ok, _, _ = _v690_lsr_native_contract(d5, fs, zone)
            if not ok:
                return None
            required = 2
        elif fam == "TREND_CONTINUATION":
            if not (close > float(ema20.iloc[-2])):
                return None
            required = 2
        # Mean-reversion/momentum are intentionally not opened by a generic local
        # recovery; their existing native detectors remain the authority.
        elif fam in {"MEAN_REVERSION", "MOMENTUM_EXPANSION"}:
            return None
        if sum(bool(x) for x in anchors) < required:
            return None
        out = dict(snap)
        out["local_regime"] = "LOCAL_RECOVERY"
        out["local_regime_recovery"] = True
        out["local_regime_primary"] = local
        out["local_recovery_anchors"] = {
            "bullish_close": bool(bullish), "higher_low": bool(higher_low),
            "ema20_slope_up": bool(ema_slope), "reclaim": bool(reclaim),
            "count": int(sum(bool(x) for x in anchors)),
        }
        out["htf_effective_strength_for_strategy"] = float(strength)
        out["context_recovery_source"] = "V693_NATIVE_CLOSED_BAR"
        return out
    except Exception:
        return None


# Extend the terminal prequal recovery set with a single native-context branch.
_V693_OLD_RECOVERY_ALLOWED = _v692_recovery_allowed_for_reason

def _v693_recovery_allowed_for_reason(reason):
    r = str(reason or "").lower()
    return bool(_V693_OLD_RECOVERY_ALLOWED(reason) or "family_regime_disallowed" in r or "policy.local" in r)


# Rebuild the terminal prequal in one place, preserving the already-final V692
# behavior and adding native context recovery before the single generic fallback.
def _v693_canonical_prequal(ranked, snap_by_symbol):
    candidate = getattr(ranked, "candidate", None)
    symbol = str(getattr(candidate, "symbol", "") or "") if candidate is not None else ""
    snap = (snap_by_symbol or {}).get(symbol) if isinstance(snap_by_symbol, dict) else None
    if candidate is None or not isinstance(snap, dict):
        return False, "canonical_prequal.missing_candidate_or_snapshot"
    try:
        fs = getattr(candidate, "features_snapshot", {}) or {}
        verdict = fs.get("v688_prequal_verdict") or {}
        if bool(verdict.get("verdict")) and _v690_prequal_snapshot_reusable(candidate, snap):
            _v690_record_prequal(candidate, snap, True, "canonical_prequal_reuse")
            return True, "canonical_prequal_reuse"
        base = globals().get("_V692_BASE_PREQUAL")
        if not callable(base):
            return False, "canonical_prequal.base_unavailable"
        ok, reason = base(ranked, {symbol: snap})
        if ok:
            _v690_record_prequal(candidate, snap, True, reason or "pass")
            _v690_handoff_snapshot(candidate, snap)
            return True, reason or "pass"
        reason_s = str(reason or "")
        # First recover policy-local context with the native closed-bar contract.
        if _v693_recovery_allowed_for_reason(reason_s):
            rec_ctx = _v693_native_context_recovery(candidate, snap, reason_s)
            if rec_ctx is not None:
                ok2, reason2 = base(ranked, {symbol: rec_ctx})
                if ok2:
                    fs["v693_context_recovery"] = dict(rec_ctx.get("local_recovery_anchors") or {})
                    _v690_record_prequal(candidate, rec_ctx, True, "context.native_recovery")
                    _v690_handoff_snapshot(candidate, rec_ctx)
                    STATS["v693_context_recovery_passes"] = int(STATS.get("v693_context_recovery_passes", 0) or 0) + 1
                    return True, "context.native_recovery"
        # Then defer to the already-tested V692 bounded recovery ladder.
        return _v692_canonical_prequal(ranked, snap_by_symbol)
    except Exception as exc:
        return False, f"canonical_prequal.exception:{type(exc).__name__}"


