def _v693_terminal_self_test():
    checks = {}
    old_state = {
        "rescue_level": int(getattr(_V420State, "rescue_level", 0) or 0),
        "rescue_until_ts": float(getattr(_V420State, "rescue_until_ts", 0.0) or 0.0),
        "relaxed_mode_until_ts": float(getattr(_V420State, "relaxed_mode_until_ts", 0.0) or 0.0),
        "adaptive_floor": float(getattr(_V420State, "adaptive_floor", CONFIG.get("MIN_LIVE_SCORE", 70.0)) or CONFIG.get("MIN_LIVE_SCORE", 70.0)),
        "rescue_last_activation_ts": float(getattr(_V420State, "rescue_last_activation_ts", 0.0) or 0.0),
    }
    # Synthetic rescue evidence is test-only state. Preserve and restore every
    # telemetry input that can influence the production rescue ladder.
    old_stats = {k: STATS.get(k) for k in (
        "v689_blocker_counts", "v690_recoverable_candidate_population",
        "v45_no_send_sec", "last_signal_sent_ts", "v693_rescue_evidence",
        "v693_rescue_evidence_runtime", "v45_rescue_level",
    )}
    try:
        checks["identity"] = all(str(x) == V693_FINAL_IDENTITY for x in (SCRIPT_VERSION, __version__, RUNTIME_BUILD_ID, CANONICAL_RUNTIME_IDENTITY, CONFIG.get("SCRIPT_VERSION", "")))
        checks["score_monotone"] = canonical_score_floor_01("base") > canonical_score_floor_01("rescue", 1) >= canonical_score_floor_01("rescue", 2) >= canonical_score_floor_01("rescue", 3) > canonical_score_floor_01("hard")
        checks["risk_monotone"] = 0.85 >= 0.70 >= 0.60 > 0
        checks["below_hard"] = not _v690_tier_allowed("BREAKOUT_RETEST", "BREAKOUT_RETEST", "BELOW", .99, {"depth_ratio":9,"spread_pct":.01,"chase_atr":.1})
        # Evidence-only rescue test: rescue may activate after strong evidence,
        # but the live adaptive floor must remain >=70 and must not weaken gates.
        STATS["v689_blocker_counts"] = {"HTF":8,"SCORE":2,"POLICY":2,"SYSTEM":0,"LIQUIDITY":0,"FEE":0,"PRE_SEND":0,"EXECUTION":0,"STRUCTURE":1}
        STATS["v45_no_send_sec"] = 2000.0
        _V420State.rescue_level = 0; _V420State.rescue_until_ts = 0.0; _V420State.rescue_last_activation_ts = 0.0
        _V420State.adaptive_floor = float(CONFIG.get("MIN_LIVE_SCORE",70.0))
        # Force the evidence branch without a wall-clock dependency by asking L1.
        _ok_e, _lvl_e, _ev_e = _v693_rescue_evidence(1)
        checks["rescue_evidence"] = bool(_ok_e and _lvl_e == 1)
        if _ok_e:
            checks["rescue_effective"] = bool(_v693_activate_rescue(1, "selftest") and float(_V420State.adaptive_floor) >= 70.0 and float(_V420State.adaptive_floor) >= canonical_score_floor_100("hard"))
        else:
            checks["rescue_effective"] = False
        # Native PULLBACK context recovery must be bounded and offline.
        if _PDNP_OK:
            rows=[]
            for i in range(40):
                p=100+i*0.12
                rows.append({"open":p-0.04,"high":p+0.12,"low":p-0.12,"close":p,"volume":1000.0})
            rows[-2].update({"open":104.20,"high":104.45,"low":104.10,"close":104.38,"volume":1500.0})
            rows[-3].update({"open":104.00,"high":104.18,"low":103.85,"close":104.08,"volume":1200.0})
            df=pd.DataFrame(rows)
            class _C: pass
            c=_C(); c.symbol="V693/USDT"; c.family="PULLBACK"; c.strategy_mode="PULLBACK"; c.zone_ref=104.08; c.features_snapshot={"chase_atr":0.20}
            rec=_v693_native_context_recovery(c,{"df_5m":df,"regime":"BULLISH","local_regime":"NON_BEARISH","htf_strength":50.0,"htf_state":"BULLISH","symbol":"V693/USDT"},"family_regime_disallowed.local")
            checks["pb_native_context_recovery"] = bool(rec is not None and rec.get("local_regime") == "LOCAL_RECOVERY")
        else:
            checks["pb_native_context_recovery"] = True
        checks["builder_single_authority"] = _v542_exact_policy_precheck is _v692_builder_precheck
        checks["prequal_single_authority"] = _v453_prequalify is _v693_canonical_prequal
        checks["discovery_shadow"] = bool(CONFIG.get("V690_DISCOVERY_VERIFIED_SHADOW", True)) and not bool(CONFIG.get("V690_DISCOVERY_VERIFIED_LIVE", False))
        checks["hard_economics"] = float(CONFIG.get("MIN_TP1_TO_FEE_RATIO",0.0))>=2.5 and float(CONFIG.get("MIN_NET_RR_TP1",0.0))>=0.8 and float(CONFIG.get("MIN_NET_RR_OVERALL",0.0))>=1.2 and float(CONFIG.get("MIN_SL_PCT",0.0))>=0.40
        checks["spot_long_only"] = bool(CONFIG.get("LONG_ONLY",True)) and str(CONFIG.get("MARKET_TYPE","SPOT")).upper()=="SPOT" and not bool(CONFIG.get("ALLOW_SHORT",False)) and not bool(CONFIG.get("ENABLE_FUTURES",False))
    except Exception as exc:
        checks["exception"] = f"{type(exc).__name__}:{exc}"
    finally:
        for k,v in old_state.items():
            try: setattr(_V420State,k,v)
            except Exception: pass
        for k,v in old_stats.items():
            try:
                if v is None:
                    STATS.pop(k, None)
                else:
                    STATS[k] = v
            except Exception:
                pass
    return {"pass": bool(all(bool(v) for v in checks.values())), "checks": checks, "count": len(checks)}


