# -----------------------------------------------------------------------------
# Truthful MSE family heartbeat. Legacy OPP counters are retained; the new
# segment is sourced directly from the current MSE generated/ranked/selected
# counters, exposing the actual active families.
# -----------------------------------------------------------------------------
def _v694_hb_segment() -> str:
    try:
        if not bool(CONFIG.get("V694_MSE_FAMILY_TELEMETRY_ENABLE", True)):
            return _v43_hb_segment()
        gen = dict((k, int(v or 0)) for k, v in (STATS.get("mse_generated_by_strategy") or {}).items())
        rank = dict((k, int(v or 0)) for k, v in (STATS.get("mse_ranked_by_strategy") or {}).items())
        win = dict((k, int(v or 0)) for k, v in (STATS.get("mse_winner_by_strategy") or {}).items())
        fams = set(gen) | set(rank) | set(win)
        top = sorted(
            ((f, gen.get(f,0), rank.get(f,0), win.get(f,0)) for f in fams),
            key=lambda x: (-x[1], -x[2], x[0])
        )[:8]
        fam_txt = ";".join(f"{f}:G{g}/R{r}/W{w}" for f,g,r,w in top) or "-"
        base = _v43_hb_segment()
        return base + f" MSE_FAM[{fam_txt}]"
    except Exception:
        try:
            return _v43_hb_segment()
        except Exception:
            return ""

globals()["_v43_hb_segment"] = _v694_hb_segment

