_V695_HANDOFF_EVENTS = deque(maxlen=256)

def _v695_note_discovery_handoff(candidate, reviewed, preflight_ok, preflight_reason):
    try:
        symbol = str(getattr(candidate, "symbol", "") or "")
        family = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "UNKNOWN").upper()
        rec = {
            "ts": WALL_NOW(), "symbol": symbol, "family": family,
            "reviewed": float(reviewed or 0.0), "preflight_ok": bool(preflight_ok),
            "preflight_reason": str(preflight_reason or ""),
            "status": "REGISTERED" if (
                bool(preflight_ok)
                and float(reviewed or 0.0) >= float(CONFIG.get("V695_DISCOVERY_HANDOFF_MIN_REVIEWED_SCORE", 80.0))
            ) else "NOT_REGISTERED",
        }
        _V695_HANDOFF_EVENTS.append(rec)
        STATS["v695_discovery_handoff_last"] = dict(rec)
        key = "v695_discovery_handoff." + rec["status"]
        STATS[key] = int(STATS.get(key, 0) or 0) + 1
        if rec["status"] == "REGISTERED":
            STATS["v695_discovery_handoff_registered"] = int(STATS.get("v695_discovery_handoff_registered", 0) or 0) + 1
        return rec
    except Exception:
        _v647_record_suppressed_exception()
        return {}

# Wrap the final Discovery notifier (currently V587's closure) only for truth
# telemetry. The original notifier remains responsible for the notification
# and for calling the existing V546 pending registry.
try:
    _v695_prev_discovery_notify = globals().get("_v531_knowledge_notify_candidates")
    if callable(_v695_prev_discovery_notify) and not getattr(_v695_prev_discovery_notify, "_v695_wrapped", False):
        def _v695_discovery_notify(candidates, snapshot=None):
            # The underlying final discovery notifier owns the SINGLE terminal
            # precheck. V695 only harvests its recorded canonical verdict after
            # that call; it must never run a second preflight that can create a
            # false duplicate root or duplicate expensive quality evaluation.
            result = _v695_prev_discovery_notify(candidates, snapshot)
            try:
                snap = dict(snapshot or {}) if isinstance(snapshot, dict) else {}
                if not bool(CONFIG.get("V695_DISCOVERY_LIVE_HANDOFF_ENABLE", True)):
                    return result
                limit = max(0, int(CONFIG.get("V695_DISCOVERY_HANDOFF_MAX_PER_CYCLE", 3)))
                seen = 0
                for c in sorted(list(candidates or []), key=lambda x: float(getattr(x, "engine_score", 0.0) or 0.0), reverse=True):
                    if seen >= limit:
                        break
                    try:
                        raw = float(getattr(c, "engine_score", 0.0) or 0.0) * 100.0
                        if not math.isfinite(raw):
                            continue
                        sym = str(getattr(c, "symbol", "") or "")
                        fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "UNKNOWN").upper()
                        if not sym or _v531_is_stablecoin(sym) or _v587_is_forbidden_coin(sym)[0]:
                            continue
                        if raw < float(CONFIG.get("V695_DISCOVERY_HANDOFF_MIN_REVIEWED_SCORE", 80.0)):
                            continue
                        ctx = _v530_derive_context(sym, c, snap)
                        reviewed = raw
                        try:
                            reviewed, _bd, _grade = _v531_review_discovery_score(raw, ctx, fam)
                            reviewed, _ = _v584_discovery_quality_integrity_score(
                                raw, reviewed, float(ctx.get("vol", 0.0) or 0.0), fam
                            )
                        except Exception:
                            _v647_record_suppressed_exception()
                        fs = dict(getattr(c, "features_snapshot", {}) or {})
                        verdict = fs.get("v688_prequal_verdict") or {}
                        if isinstance(verdict, dict) and verdict:
                            pf_ok = bool(verdict.get("verdict"))
                            pf_reason = str(verdict.get("reason") or ("pass" if pf_ok else "canonical_prequal.reject"))
                            source = "TERMINAL_VERDICT"
                        else:
                            pf_ok = False
                            pf_reason = "not_evaluated_by_terminal_discovery_path"
                            source = "DELEGATED"
                        rec = _v695_note_discovery_handoff(c, reviewed, pf_ok, pf_reason)
                        logger.info(
                            f"[V695-DISCOVERY-HANDOFF] {sym} family={fam} raw={raw:.1f} "
                            f"reviewed={float(reviewed):.1f} preflight={'PASS' if pf_ok else 'BLOCKED'} "
                            f"reason={pf_reason} status={rec.get('status','NOT_REGISTERED')} source={source}"
                        )
                        seen += 1
                    except Exception as exc:
                        logger.debug(f"[V695-DISCOVERY-HANDOFF] suppressed: {exc}")
            except Exception as exc:
                logger.debug(f"[V695-DISCOVERY-HANDOFF] telemetry harvest suppressed: {exc}")
            return result
        _v695_discovery_notify._v695_wrapped = True
        globals()["_v531_knowledge_notify_candidates"] = _v695_discovery_notify
        globals()["_v530_knowledge_notify_candidates"] = _v695_discovery_notify
        globals()["_v528_knowledge_notify_candidates"] = _v695_discovery_notify
        STATS["v695_discovery_wrapper_installed"] = True
    else:
        STATS["v695_discovery_wrapper_installed"] = False
except Exception as exc:
    STATS["v695_discovery_wrapper_installed"] = False
    logger.critical("[V695] discovery wrapper install failed: %s", exc)

# -----------------------------------------------------------------------------
# Correct MSE family heartbeat aggregation from the actual flattened STATS keys.
# ----------------------------------------------------------------------------−
def _v695_mse_family_maps():
    generated, ranked, winners = {}, {}, {}
    try:
        for k, v in STATS.items():
            ks = str(k)
            if ks.startswith("mse_generated_by_strategy."):
                fam = ks.split(".", 1)[1].upper(); generated[fam] = int(v or 0)
            elif ks.startswith("mse_ranked_by_strategy."):
                fam = ks.split(".", 1)[1].upper(); ranked[fam] = int(v or 0)
            elif ks.startswith("mse_winner_by_strategy."):
                fam = ks.split(".", 1)[1].upper(); winners[fam] = int(v or 0)
    except Exception:
        pass
    return generated, ranked, winners

