# Canonical, non-recursive heartbeat body. We intentionally reconstruct the
# original bounded heartbeat fields instead of calling any previously wrapped
# _v43_hb_segment, eliminating wrapper-on-wrapper duplication permanently.
def _v697_base_hb_segment() -> str:
    try:
        opp_keys=[("PB","v43_opp_pullback"),("LSB","v43_opp_local_strength_breakout"),
                  ("CMP","v43_opp_compression_expansion"),("SWG","v43_opp_swing"),
                  ("REV","v43_opp_flush_reversal"),("CR","v44_opp_continuation_reclaim"),
                  ("FBR","v44_opp_failed_breakout_reclaim")]
        nfm_keys=[("PB","pullback"),("BRK","breakout"),("RS","local_strength_breakout"),
                  ("CMP","compression_expansion"),("SWG","swing_pullback"),("REV","extreme_flush_reversal"),
                  ("CR","continuation_reclaim"),("FBR","failed_breakout_reclaim")]
        opp="OPP[scope=TOTAL,"+",".join(f"{k}={int(STATS.get(v,0) or 0)}" for k,v in opp_keys)+"]"
        nfm="NFM[scope=TOTAL,"+",".join(f"{k}={int(STATS.get('v43_nfm.'+v,0) or 0)}" for k,v in nfm_keys)+"]"
        # V702 R10: one display-cycle snapshot is the sole source for both the
        # compact MSE tuple and MSE_RANK. If the active cycle is empty, the
        # canonical completed-cycle fallback is used consistently and its source
        # is exposed explicitly.
        try:
            _display_cycle = dict(_v684_public_cycle() if callable(globals().get("_v684_public_cycle")) else {})
        except Exception:
            _display_cycle = {}
        _cycle_src = str(_display_cycle.get("source", "ACTIVE"))
        _display_cycle_id = int(_display_cycle.get("cycle_id", STATS.get("v681_runtime_cycle_id", 0)) or 0)
        _mse_g = int(_display_cycle.get("generated", STATS.get("v648_cycle_mse_generated", STATS.get("v681_runtime_cycle_generated", 0))) or 0)
        _mse_v = int(_display_cycle.get("prequal", STATS.get("v648_cycle_mse_prequalified", STATS.get("v681_runtime_cycle_hard_valid", 0))) or 0)
        _mse_r = int(_display_cycle.get("ranked", STATS.get("v648_cycle_mse_ranked", STATS.get("v681_runtime_cycle_ranked", 0))) or 0)
        _mse_w = int(_display_cycle.get("selected", STATS.get("v648_cycle_mse_selected", STATS.get("v681_runtime_cycle_selected", 0))) or 0)
        _mse_q = int(_display_cycle.get("queued", STATS.get("v648_cycle_mse_queued", STATS.get("v681_runtime_cycle_queued", 0))) or 0)
        _mse_s = int(_display_cycle.get("sent", STATS.get("v648_cycle_mse_sent", STATS.get("v681_runtime_cycle_sent", 0))) or 0)
        _mse_raw = int(_display_cycle.get("raw_ranked", STATS.get("v681_runtime_cycle_raw_ranked", STATS.get("v648_cycle_mse_raw_ranked", 0))) or 0)
        _mse_pre = int(_display_cycle.get("prequal", STATS.get("v681_runtime_cycle_prequal", 0)) or 0)
        _mse_rank_reasons = dict(_display_cycle.get("rank_reject_reasons") or STATS.get("v681_runtime_cycle_rank_reject_reasons", {}) or {})
        mse=(f"MSE[CYCLE G={_mse_g},V={_mse_v},R={_mse_r},W={_mse_w},Q={_mse_q},S={_mse_s};"
             f"CUM G={int(STATS.get('mse_generated',0) or 0)},"
             f"V={int(STATS.get('mse_hard_valid',0) or 0)},"
             f"R={int(STATS.get('mse_ranked',0) or 0)},"
             f"W={int(STATS.get('mse_winners',0) or 0)},"
             f"RCL={int(STATS.get('v607_mse_quality_recovered_cycle',0) or 0)},"
             f"NM={int(STATS.get('v607_near_miss_telegram_cycle',0) or 0)}]")
        cycle_id=_display_cycle_id
        rank_gen=_mse_g
        rank_ranked=_mse_r
        rank_selected=_mse_w
        rank_queued=_mse_q
        rank_sent=_mse_s
        rank_pre=_mse_pre
        rank_raw=_mse_raw
        rank_top=sorted(((str(k),int(v or 0)) for k,v in _mse_rank_reasons.items() if int(v or 0)>0),key=lambda kv:(-kv[1],kv[0]))[:5]
        # STARV is specifically MSE RAW-RANK starvation: no candidate survived
        # CompositeRankingEngine. A later R=0 can be caused by canonical prequal
        # and must not masquerade as rank starvation.
        rank_starv=int(rank_gen>0 and rank_raw==0)
        rank=(f" MSE_RANK[CYCLE={cycle_id},G={rank_gen},PRE={rank_pre},RAW={rank_raw},R={rank_ranked},S={rank_selected},Q={rank_queued},SEND={rank_sent},STARV={rank_starv},raw_top={str(rank_top)[:180]} source=RUNTIME_CYCLE_CANONICAL CYCLE_SRC={_cycle_src}]")
        bridge=(f" LEGACY_BRIDGE[A={int(STATS.get('v596_bridge_attempts',0) or 0)},"
                f"R={int(STATS.get('v596_bridge_ready',0) or 0)},"
                f"S={int(STATS.get('v596_bridge_sent',0) or 0)},"
                f"B={int(STATS.get('v596_bridge_blocks',0) or 0)}]")
        entry_status = str(STATS.get("v699_live_entry_status", "UNKNOWN") or "UNKNOWN")
        entry_ready = int(bool(STATS.get("v699_live_entry_ready", False)))
        return " "+opp+" "+mse+rank+bridge+" "+nfm+f" ENTRY_READY={entry_ready},ENTRY_STATUS={entry_status}"
    except Exception:
        return ""

def _v697_hb_segment():
    try:
        base=_v697_base_hb_segment().strip()
        gen,rank,win = _v695_mse_family_maps() if callable(globals().get("_v695_mse_family_maps")) else ({},{},{})
        fams=set(gen)|set(rank)|set(win)
        top=sorted(((f,int(gen.get(f,0) or 0),int(rank.get(f,0) or 0),int(win.get(f,0) or 0)) for f in fams), key=lambda x:(-x[1],-x[2],x[0]))[:8]
        fam_txt="scope=WINDOW;" + (";".join(f"{f}:G{g}/R{r}/W{w}" for f,g,r,w in top) or "-")
        last="-"; reg=int(STATS.get("v695_discovery_handoff_registered",0) or 0)
        try:
            ho=globals().get("_V695_HANDOFF_EVENTS")
            if ho:
                ev=ho[-1]
                last=f"{str(ev.get('symbol','-'))}:{str(ev.get('status','-'))}"[:100]
        except Exception:
            last="-"
        ok_ts=float(STATS.get("telegram_last_success_ts",0.0) or 0.0)
        age=_wall_age_sec(ok_ts) if ok_ts else None
        depth=len(getattr(TelegramDispatcher,"_queue",[]) or [])
        tg=(f"TG[D={depth},ok_age={'NA' if age is None else round(float(age),1)},"
            f"ok={int(STATS.get('telegram_sent_ok',0) or 0)},"
            f"rq={int(STATS.get('telegram_requeued',0) or 0)},"
            f"drop={int(STATS.get('telegram_drop_permanent',0) or 0)},"
            f"err={int(STATS.get('telegram_loop_errors',0) or 0)}]")
        ko=(f"KO[reg={int(STATS.get('v702_knowledge_alert_registered',0) or 0)},"
            f"fetch_err={int(STATS.get('v702_knowledge_fetch_errors',0) or 0)},"
            f"proc_err={int(STATS.get('v702_knowledge_process_errors',0) or 0)},"
            f"notice_err={int(STATS.get('v702_knowledge_notice_errors',0) or 0)}]")
        return f"{base} MSE_FAM[{fam_txt}] LIVE_HO[last={last},reg={reg}] {tg} {ko}".strip()
    except Exception:
        return ""
_v697_hb_segment._v697_canonical=True
globals()["_v43_hb_segment"]=_v697_hb_segment
