    if callable(_v697_prev_builder) and not getattr(_v697_prev_builder,"_v697_recovery_parity",False):
        def _v697_builder_recovery_parity(symbol,candidate,snapshot):
            result=_v697_prev_builder(symbol,candidate,snapshot)
            if isinstance(result,tuple) and len(result)>=2 and result[0] is False and bool(CONFIG.get("V697_RECOVERY_BUILDER_PARITY_ENABLE",True)):
                reason=str(result[1] or "")
                fs=getattr(candidate,"features_snapshot",{}) or {}
                htf_rec=fs.get("v692_htf_recovery") or {}
                tier_rec=fs.get("v692_tier_recovery") or {}
                # Never manufacture recovery. Only expose a diagnostic flag when
