                if reason in {"htf.core_not_aligned","family_htf_strength_below_floor"} and bool(htf_rec.get("bridge",False)):
                    STATS["v697_builder_recovery_parity_hits"] = int(STATS.get("v697_builder_recovery_parity_hits",0) or 0)+1
