_V698_LAST_BUILDER_BLOCK = {}


def _v698_cycle_id() -> int:
    try:
        return int(
            globals().get("_V517_ACTIVE_CYCLE_ID")
            or STATS.get("v516_cycle_id", 0)
            or STATS.get("v669_last_cycle_id", 0)
            or STATS.get("v681_runtime_cycle_id", 0)
            or 0
        )
    except Exception:
        return 0


def _v698_candidate_key(symbol: str, candidate: Any, market_data: Optional[Dict[str, Any]] = None) -> tuple:
    c = getattr(candidate, "candidate", candidate)
    fs = dict(getattr(c, "features_snapshot", {}) or {})
    md = dict(market_data or {})
    candle = md.get("closed_candle_ts") or md.get("candle_ts") or fs.get("closed_candle_ts") or fs.get("candle_ts")
    if candle is None:
        try:
            df5 = md.get("df_5m")
            candle = str(df5.index[-2]) if df5 is not None and len(df5.index) >= 2 else "0"
        except Exception:
            candle = "0"
    family = str(getattr(c, "family", "") or fs.get("family", "") or getattr(c, "strategy_mode", "") or "").upper()
    mode = str(getattr(c, "strategy_mode", "") or fs.get("strategy_mode", "") or family).upper()
    return (str(symbol or getattr(c, "symbol", "") or ""), int(_v698_cycle_id()), str(candle), family, mode)


def _v698_tombstone_prune() -> None:
    try:
        now = MONO_NOW()
        ttl = max(60.0, float(CONFIG.get("V698_CANDIDATE_TOMBSTONE_TTL_SEC", 900.0)))
        stale = [k for k, rec in list(_V698_TOMBSTONES.items()) if now - float(rec.get("ts", now)) > ttl]
        for k in stale:
            _V698_TOMBSTONES.pop(k, None)
        # Bound map independently of deque eviction.
        maxn = max(128, int(CONFIG.get("V698_CANDIDATE_TOMBSTONE_MAX", 2048)))
        while len(_V698_TOMBSTONES) > maxn:
            oldest = min(_V698_TOMBSTONES.items(), key=lambda kv: float(kv[1].get("ts", now) or now))[0]
            _V698_TOMBSTONES.pop(oldest, None)
    except Exception:
        pass


def _v698_reason_root(reason: str, stage: str = "") -> str:
    token = f"{stage}:{reason}".lower()
    # A selected candidate that reaches the terminal builder and produces no
    # result without a fresh deterministic rejection is a handoff/execution
    # outcome, not an unknown policy/strategy cause. Keep it explicitly in the
    # EXECUTION root so operator starvation attribution remains truthful.
    _builder_stage = str(stage or "").lower()
    _builder_reason = str(reason or "").lower()
    if _builder_stage in {"builder", "builder_terminal", "selected_builder", "builder_noop"} and _builder_reason in {
        "builder_returned_none",
        "builder_terminal_no_result_unattributed",
        "handoff_no_new_rejection_record",
        "builder_returned_without_queue",
        "builder_terminal_unknown_reason",
    }:
        return "EXECUTION"
    if any(x in token for x in (
        "mse_snapshot_invalid", "mse_missing_btc_context", "snapshot_invalid",
        "snapshot_missing", "data_missing", "freshness.stale_candidate",
        "freshness.unverifiable", "missing_critical_data",
    )):
        return "DATA_MISSING"
    if any(x in token for x in ("balance", "network", "timeout", "exchange", "ambig", "system")):
        return "SYSTEM"
    if any(x in token for x in ("family_tier", "liquidity", "spread", "depth", "orderbook", "tier_below")):
        return "POLICY" if "family_tier" in token or "tier_below" in token else "LIQUIDITY"
    if any(x in token for x in ("htf", "alignment", "family_htf")):
        return "HTF"
    if any(x in token for x in ("fake_break", "microstruct", "structure", "reclaim")):
        return "STRUCTURE"
    if any(x in token for x in ("score", "threshold")):
        return "SCORE"
    if any(x in token for x in ("fee", "economic", "rr", "sl")):
        return "FEE"
    if "execution" in token or "presend" in token or "queue" in token or "send" in token:
        return "EXECUTION"
    return "OTHER"


def _v698_record_builder_block(symbol: str, candidate: Any, market_data: Dict[str, Any], reason: str, stage: str) -> None:
    try:
        _v698_tombstone_prune()
        key = _v698_candidate_key(symbol, candidate, market_data)
        now = MONO_NOW()
        root = _v698_reason_root(reason, stage)
        rec = {
            "ts": now,
            "wall_ts": WALL_NOW(),
            "symbol": str(symbol),
            "family": str(getattr(candidate, "family", "") or ""),
            "strategy_mode": str(getattr(candidate, "strategy_mode", "") or ""),
            "cycle_id": _v698_cycle_id(),
            "stage": str(stage or "builder"),
            "reason": str(reason or "builder_returned_none"),
            "root": root,
        }
        _V698_TOMBSTONES[key] = rec
        _V698_TOMBSTONE_ORDER.append(key)
        _V698_LAST_BUILDER_BLOCK.update({
            "symbol": str(symbol), "stage": str(stage or "builder"),
            "reason": str(reason or "builder_returned_none"), "root": root,
            "cycle_id": _v698_cycle_id(), "ts": WALL_NOW(),
        })
        STATS["v698_builder_blocks"] = int(STATS.get("v698_builder_blocks", 0) or 0) + 1
        STATS["v698_last_builder_root"] = root
        STATS["v698_last_builder_reason"] = str(reason or "builder_returned_none")[:240]
        STATS["v698_cycle_builder_blocks"] = int(STATS.get("v698_cycle_builder_blocks", 0) or 0) + 1
    except Exception:
        pass


def _v698_tombstone_hit(symbol: str, candidate: Any, market_data: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not bool(CONFIG.get("V698_CANDIDATE_TOMBSTONE_ENABLE", True)):
        return None
    try:
        _v698_tombstone_prune()
        key = _v698_candidate_key(symbol, candidate, market_data)
        rec = _V698_TOMBSTONES.get(key)
        if rec:
            STATS["v698_duplicate_candidate_suppressed"] = int(STATS.get("v698_duplicate_candidate_suppressed", 0) or 0) + 1
            return dict(rec)
    except Exception:
        pass
    return None


