def _v698_current_cycle_root() -> str:
    try:
        last = dict(_V698_LAST_BUILDER_BLOCK or {})
        if int(last.get("cycle_id", -1)) == _v698_cycle_id() and last.get("root"):
            return str(last.get("root"))
        d = V45GlobalFunnelState.funnel_window_deltas(float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN", 12)) * 60.0)
        if int(d.get("selected", 0) or 0) > 0 and int(d.get("queued", 0) or 0) == 0 and int(d.get("sent", 0) or 0) == 0:
            return str(STATS.get("v698_last_builder_root") or "EXECUTION")
    except Exception:
        pass
    return "NONE"

