def _v699_self_test():
    checks = {}

    def ok(name, cond):
        checks[name] = bool(cond)
        return checks[name]

    try:
        g_hard = float(CONFIG.get("V45_SCORE_HARD_FLOOR", 0.50))
        c_min = float(CONFIG.get("V453_SCORE_FLOOR_MIN", 70.0))
        base_live = float(CONFIG.get("MIN_LIVE_SCORE", 70))
        # 1) scales are not mixed: global 0..1 vs canonical 0..100
        ok("T01_scales_not_mixed", 0.0 < g_hard <= 1.0 and c_min >= 70.0 and base_live > 1.0)
        # 2) canonical live floor never < 70
        ok("T02_canonical_floor_ge_70", _V699_STARVATION.effective_floor() >= 70.0 and c_min >= 70.0)
        # 3) MIN_LIVE_SCORE base remains >= 70
        ok("T03_min_live_score_base_70", base_live >= 70.0)
        # 4-10) hard gates intact (no rescue bypass possible: flags/values unchanged)
        ok("T04_balance_gate_intact", bool(CONFIG.get("BALANCE_CHECK_ENABLE", CONFIG.get("BALANCE_GUARD_ENABLE", True))))
        ok("T05_truthseal_intact", bool(CONFIG.get("TRUTH_SEAL_ENABLE", CONFIG.get("TRUTHSEAL_ENABLE", True))))
        ok("T06_exposure_intact", bool(CONFIG.get("EXPOSURE_PROTECTION_ENABLE", CONFIG.get("EXPOSURE_GUARD_ENABLE", True))))
        ok("T07_liquidity_depth_intact", bool(CONFIG.get("LIQUIDITY_DEPTH_ENABLE", CONFIG.get("LIQUIDITY_DEPTH_GATE_ENABLE", True))))
        ok("T08_spread_ceiling_unchanged", dict(CONFIG.get("TIER_SPREAD_CEIL_PCT", {})) == _V699_BASELINE_HARD["TIER_SPREAD_CEIL_PCT"])
        ok("T09_presend_intact", bool(CONFIG.get("PRESEND_GATE_ENABLE", CONFIG.get("PRE_SEND_GATE_ENABLE", True))))
        ok("T10_sl_floor_intact", float(CONFIG.get("MIN_SL_PCT", 0.40)) >= _V699_BASELINE_HARD["MIN_SL_PCT"])
        # 11) no short/futures/leverage path
        ok("T11_long_only_spot", bool(CONFIG.get("LONG_ONLY", True))
           and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT"
           and not bool(CONFIG.get("ALLOW_SHORT", False))
           and not bool(CONFIG.get("ENABLE_FUTURES", False))
           and not bool(CONFIG.get("LEVERAGE", 0)))
        # 12) only one execution authority
        sb = globals().get("SignalBuilder")
        ok("T12_single_execution_authority", sb is not None and callable(getattr(sb, "build_and_route", None))
           and bool(CONFIG.get("V699_DISCOVERY_ORDER_FORBIDDEN", True)))
        # 13) same-snapshot recovery performs no network fetch
        rec, still = _v699_same_snapshot_fact_recovery(
            {"volume": 200.0, "volume_ma": 100.0, "price": 10.0, "entry_ref": 9.5}, ["volume_ratio", "chase_pct", "htf_state"])
        ok("T13_snapshot_recovery_no_network", rec.get("volume_ratio") == 2.0
           and abs(rec.get("chase_pct", 0) - (10.0 - 9.5) / 9.5 * 100.0) < 1e-6 and "htf_state" in still)
        # 14) same-candle dedup
        _V699_CANDLE_SEEN.clear()
        first = _v699_candle_dedup("TST/USDT", 1000, "PULLBACK", now=10.0)
        dup = _v699_candle_dedup("TST/USDT", 1000, "PULLBACK", now=11.0)
        newc = _v699_candle_dedup("TST/USDT", 2000, "PULLBACK", now=1000.0)
        ok("T14_candle_dedup", (not first) and dup and (not newc))
        # 15) strategy-family separation
        ok("T15_family_separation", _v699_family_of("VOLATILITY_BURST") == "MOMENTUM_EXPANSION"
           and _v699_family_of("RELATIVE_STRENGTH_LEADER") == "RELATIVE_STRENGTH"
           and _v699_family_of("MICRO_TREND_CONTINUATION") == "TREND_CONTINUATION"
           and _v699_family_of("OPPORTUNITY_SCOUT") == "OPPORTUNITY_SCOUT"
           and "RELATIVE_STRENGTH" in V699_STRATEGY_FAMILIES)
        ok("T15b_engine_family_semantics",
           getattr(VolatilityBurstEngine, "strategy_mode", "") == "VOLATILITY_BURST"
           and getattr(RelativeStrengthLeaderEngine, "strategy_mode", "") == "RELATIVE_STRENGTH_LEADER"
           and getattr(RelativeStrengthLeaderEngine, "family_map", ("",))[0] == "RELATIVE_STRENGTH"
           and getattr(OpportunityScoutEngine, "strategy_mode", "") == "OPPORTUNITY_SCOUT"
           and getattr(OpportunityScoutEngine, "family_map", ("",))[0] == "OPPORTUNITY_SCOUT")
        # 16+17) candidate diversity + one family cannot consume the pool
        pool = []
        for i in range(8):
            pool.append({"symbol": "A/USDT", "candle_ts": 1, "strategy_mode": "PULLBACK", "score": 90 - i})
        pool.append({"symbol": "A/USDT", "candle_ts": 1, "strategy_mode": "RELATIVE_STRENGTH_LEADER", "score": 80})
        pool.append({"symbol": "A/USDT", "candle_ts": 1, "strategy_mode": "VOLATILITY_BURST", "score": 79})
        retained = _v699_select_retained(pool, global_cap=6)
        fams_retained = set(r["family"] for r in retained)
        ok("T16_candidate_diversity", len(fams_retained) >= 3)
        ok("T17_family_pool_cap", sum(1 for r in retained if r["family"] == "PULLBACK") <= int(CONFIG.get("V699_RETENTION_PER_FAMILY_GROUP", 2)) + 1)
        # 18) engine exception != NO_MATCH
        ok("T18_engine_error_not_no_match", _v699_classify_engine_outcome(exc=ValueError("x")) == "ENGINE_ERROR")
        # 19) HALF_OPEN recovery
        br = V699EngineCircuitBreaker("t")
        for _ in range(6):
            br.note_error()
        degraded = br.state == "DEGRADED"
        allowed_probe = br.allow(now=br.state_since + 999.0) and br.state == "HALF_OPEN"
        br.note_success()
        ok("T19_half_open_recovery", degraded and allowed_probe and br.state == "ACTIVE")
        # 20) score relief stops at the hard live floor (70)
        ctl = V699StarvationController()
        t0 = 10000.0
        for i in range(60):
            ctl.note_cycle(True, dominant_root="SCORE", now=t0 + i * 400.0)
            ctl.step_armed_ts = t0 + i * 400.0 - 999.0
            ctl.last_change_ts = t0 + i * 400.0 - 999.0
            ctl.maybe_relax(dominant_root="SCORE", now=t0 + i * 400.0)
        ok("T20_relief_stops_at_70", ctl.effective_floor() >= 70.0 and ctl.effective_floor() == 70.0)
        # 21) fee re-sizing never exceeds max ticket
        cap = float(CONFIG.get("MAX_POSITION_SIZE_USDT", 75.0))
        ok("T21_fee_resize_capped", (_v699_fee_resize(999.0, 500.0) or 0) <= cap and _v699_fee_resize(50.0, 500.0) == 50.0)
        # 22) fee floors unchanged/hard
        ok("T22_fee_floors_hard", float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5)) >= _V699_BASELINE_HARD["MIN_TP1_TO_FEE_RATIO"]
           and float(CONFIG.get("MIN_NET_RR_TP1", 0.8)) >= _V699_BASELINE_HARD["MIN_NET_RR_TP1"]
           and float(CONFIG.get("MIN_NET_RR_OVERALL", 1.2)) >= _V699_BASELINE_HARD["MIN_NET_RR_OVERALL"])
        # 23) spread starvation never lowers spread ceiling
        before = dict(CONFIG.get("TIER_SPREAD_CEIL_PCT", {}))
        _v699_spread_near_miss("TST/USDT", "MID", 9.99, now=1.0)
        ok("T23_spread_ceiling_never_raised", dict(CONFIG.get("TIER_SPREAD_CEIL_PCT", {})) == before
           and len(_V699_SPREAD_RECHECK_QUEUE) >= 1)
        _V699_SPREAD_RECHECK_QUEUE.clear()
        # 24) mean-reversion overbought does not create direct long entry
        tag, allow_long = _v699_mean_reversion_gate(80.0, has_reclaim_evidence=False)
        tag2, allow_long2 = _v699_mean_reversion_gate(21.0, has_reclaim_evidence=True)
        ok("T24_overbought_no_direct_long", tag == "EXHAUSTION_OBSERVATION" and allow_long is False
           and tag2 == "OVERSOLD_DISCOVERY" and allow_long2 is True)
        # 25) recall candidates always re-enter canonical builder
        _prev_floor = STATS.get("v453_effective_canonical_floor")
        STATS["v453_effective_canonical_floor"] = 70.0
        recalled = _v699_recall_candidates([
            {"symbol": "A/USDT", "candle_ts": 1, "strategy_mode": "PULLBACK", "score": 68.5,
             "hard_eligible": True, "failed_dimension": "SCORE"},
            {"symbol": "B/USDT", "candle_ts": 1, "strategy_mode": "BREAKOUT_RETEST", "score": 60.0,
             "hard_eligible": True, "failed_dimension": "SCORE"},
            {"symbol": "C/USDT", "candle_ts": 1, "strategy_mode": "PULLBACK", "score": 69.0,
             "hard_eligible": True, "hard_fail": "LIQUIDITY"},
        ])
        ok("T25_recall_reenters_builder", len(recalled) == 1
           and all(r.get("requires_canonical_builder") and not r.get("direct_execution") for r in recalled))
        if _prev_floor is not None:
            STATS["v453_effective_canonical_floor"] = _prev_floor
        # 26) discovery never places order
        ok("T26_discovery_shadow_only", bool(CONFIG.get("V690_DISCOVERY_VERIFIED_SHADOW", True))
           and not bool(CONFIG.get("V690_DISCOVERY_VERIFIED_LIVE", False))
           and bool(CONFIG.get("V699_DISCOVERY_ORDER_FORBIDDEN", True)))
        # 27) Telegram failure cannot authorize trade (alert gate is read-only)
        ok("T27_telegram_not_authority", _v699_telegram_alert_allowed(61.0) is False)
        # 28) forbidden symbol handling remains fail-closed
        picked, tel = _v699_dynamic_universe(core=["OK/USDT", "BAD/USDT"], forbidden={"BAD/USDT"}, state="NORMAL")
        ok("T28_forbidden_fail_closed", all(s != "BAD/USDT" for s, _ in picked) and tel["skipped_due_to_forbidden"] == 1)
        # 29) runtime identity is singular
        ok("T29_identity_singular", all(str(x) == V699_FINAL_IDENTITY for x in (
            SCRIPT_VERSION, __version__, RUNTIME_BUILD_ID, CANONICAL_RUNTIME_IDENTITY,
            CONFIG.get("SCRIPT_VERSION", ""), STATS.get("script_version", ""), STATS.get("runtime_build_id", ""))))
        # 30) package manifest entries well-formed
        ok("T30_manifest_entries", all(isinstance(f, str) and f for f in _v699_manifest_entries()))
        # A3: no cross-scale rescue — L2/L3 declared shadow-normalized only
        ok("A3_no_cross_scale_rescue",
           str(CONFIG.get("V45_RESCUE_L23_SCALE_DECLARATION", "")).startswith("GLOBAL_NORMALIZED")
           and float(CONFIG.get("V45_RESCUE_L2_SCORE_FLOOR_NORM", 0.5)) <= 1.0)
        # one recovery branch per cycle + root gating
        ctl2 = V699StarvationController()
        b1 = ctl2.note_cycle(True, dominant_root="HTF", now=1.0)
        f1 = ctl2.maybe_relax(dominant_root="HTF", now=2.0)
        ok("REL_root_gated_no_score_relief", b1 == "R2_CONTEXT_RECOVERY" and f1 == ctl2._base_floor())
        b2 = ctl2.note_cycle(True, dominant_root="SYSTEM", hazard=False, now=3.0)
        ok("REL_system_no_relaxation", b2 == "R0_NORMAL")
        b3 = ctl2.note_cycle(True, dominant_root="SCORE", kill_switch=True, now=4.0)
        ok("REL_killswitch_blocks", b3 == "R0_NORMAL")
        # dedup distinguishes mode/profile/zone on same symbol+candle
        k1 = _v699_dedup_key("A/USDT", 1, "PULLBACK")
        k2 = _v699_dedup_key("A/USDT", 1, "RELATIVE_STRENGTH_LEADER")
        k3 = _v699_dedup_key("A/USDT", 1, "MICRO_TREND_CONTINUATION")
        ok("DEDUP_mode_distinct", len({k1, k2, k3}) == 3)
        # canonical survival estimate is read-only and bounded
        est = _v699_estimated_canonical_survival({"price": 1, "atr": 1, "volume_ratio": 1,
                                                  "htf_state": 1, "structure": 1, "entry_ref": 1,
                                                  "score": 75, "policy_allowed": True,
                                                  "liquidity_stable": True, "economics_feasible": True})
        ok("SURVIVAL_readonly_bounded", 0.0 <= est <= 1.0)
        # family budgets redistribute
        budgets = _v699_family_budgets({"PULLBACK", "BREAKOUT_RETEST"}, total_budget=18)
        ok("FAMILY_budget_redistribute", sum(budgets.values()) >= 18
           and budgets["PULLBACK"] >= 1 and budgets["OPPORTUNITY_SCOUT"] >= 1)
        # hot queue bounded
        for i in range(64):
            _v699_hot_enqueue("H%d/USDT" % i, "VOLUME_SPIKE", now=1.0)
        ok("HOT_queue_bounded", len(_V699_HOT_QUEUE) <= int(CONFIG.get("V699_HOT_QUEUE_MAX", 32)))
        _V699_HOT_QUEUE.clear()
        # near-miss policy map complete
        ok("NEARMISS_policy_complete", all(_v699_near_miss_policy(k) != "NO_RESCUE" for k in V699_NEAR_MISS_TYPES))
        # htf telemetry split
        ok("HTF_reason_split", _v699_htf_reject_reason({"stale": True}) == "STALE"
           and _v699_htf_reject_reason({"neutral_bridge_denied": True}) == "NEUTRAL_BRIDGE_DENIED")
        # PolicyDecision: UNKNOWN != allow, UNKNOWN recoverable
        pd_unknown = V699PolicyDecision.unknown("HTF")
        ok("POLICY_unknown_recoverable_not_allow", (not pd_unknown.allowed) and pd_unknown.recoverable and pd_unknown.state == "UNKNOWN")
    except Exception as exc:
        checks["exception"] = "%s:%s" % (type(exc).__name__, exc)
    return {"pass": bool(all(bool(v) for v in checks.values())), "checks": checks, "count": len(checks)}


