# --- Wiring 6: same-snapshot fact recovery inside canonical prequal ----------
try:
    _v699_orig_prequalify = _v453_prequalify

    def _v699_prequalify(r, snap_by_symbol):
        ok, reason = _v699_orig_prequalify(r, snap_by_symbol)
        try:
            if ok or not CONFIG.get("V699_FACT_RECOVERY_RETRY_ENABLE", True):
                return ok, reason
            if _v699_root_of(reason) != "DATA_MISSING":
                return ok, reason
            sym = str(getattr(getattr(r, "candidate", None), "symbol", "") or getattr(r, "symbol", "") or "")
            snap = (snap_by_symbol or {}).get(sym)
            if not isinstance(snap, dict):
                return ok, reason  # fail-closed: nothing to recover from
            missing_keys = [k for k in ("volume_ratio", "atr", "atr_pct", "chase_pct",
                                        "htf_state", "rs_closed", "market_phase")
                            if snap.get(k) is None]
            if not missing_keys:
                return ok, reason
            STATS["v699_fact_recovery_attempts"] = int(STATS.get("v699_fact_recovery_attempts", 0) or 0) + 1
            _v699_daily_note("recovery_attempts")
            recovered, still = _v699_same_snapshot_fact_recovery(snap, missing_keys)
            if recovered and not still:
                # Re-run the SAME canonical prequal with the same-snapshot
                # recovered facts. No network fetch happened here.
                patched = dict(snap_by_symbol)
                merged = dict(snap)
                merged.update(recovered)
                patched[sym] = merged
                ok2, reason2 = _v699_orig_prequalify(r, patched)
                if ok2:
                    STATS["v699_fact_recovery_success"] = int(STATS.get("v699_fact_recovery_success", 0) or 0) + 1
                    _v699_daily_note("recovery_success")
                    return ok2, reason2
                return ok2, "fact_recovery_retry:" + str(reason2)
            # Unrecoverable critical fact: fail-closed, classified DATA_MISSING.
            STATS["v699_data_missing_fail_closed"] = int(STATS.get("v699_data_missing_fail_closed", 0) or 0) + 1
            return False, "data_missing_unrecoverable:" + ",".join(still or ["unknown"])
        except Exception:
            _v647_record_suppressed_exception()
            return ok, reason

    _v453_prequalify = _v699_prequalify
except Exception as _e:
    STATS["v699_rt_wire_errors"] = int(STATS.get("v699_rt_wire_errors", 0) or 0) + 1


