# --- Wiring 9: ranking layer — retention, diversity tie-break, survival,
#     canonical recall on NO_OPP (every recall re-enters SignalBuilder) --------
async def _v699_route_recalled(symbol, md, recalled_candidate=None):
    """Canonical recall routing using the exact recalled candidate provenance.

    SignalBuilder remains the only execution authority and will re-run all hard
    validation, freshness, policy, economics, SL and PreSend gates.
    """
    try:
        if _v699_rt_kill_or_blocked():
            STATS["v699_recall_expired"] = int(STATS.get("v699_recall_expired", 0) or 0) + 1
            return
        ex = _V699_RT_EXCHANGE_REF.get("exchange")
        if ex is None:
            STATS["v699_recall_expired"] = int(STATS.get("v699_recall_expired", 0) or 0) + 1
            return
        if symbol in ACTIVE_TRADES:
            return
        before = int(STATS.get("signals_sent", 0) or 0)
        _v699_daily_note("builder_entered")
        preferred = recalled_candidate if bool(CONFIG.get("V699_TRUE_CANDIDATE_RECALL_ENABLE", True)) else None
        await SignalBuilder.build_and_route(ex, symbol, md or {}, preferred_candidate=preferred)
        after = int(STATS.get("signals_sent", 0) or 0)
        if after > before:
            STATS["v699_recall_send"] = int(STATS.get("v699_recall_send", 0) or 0) + 1
            _V699_STARVATION.note_success()
        else:
            STATS["v699_recall_builder_reject"] = int(STATS.get("v699_recall_builder_reject", 0) or 0) + 1
            _v699_daily_note("builder_rejected")
    except Exception as _re:
        STATS["v699_recall_builder_reject"] = int(STATS.get("v699_recall_builder_reject", 0) or 0) + 1
        logger.debug(f"[V699-RECALL] route suppressed {symbol}: {_re}")


def _v699_remember_rejected_candidate(symbol, reason, candidate=None, **ctx):
    """Store bounded candidate provenance for TRUE candidate recall.

    The object is never serialized into STATS. The history row receives only a
    short opaque key, allowing recall to pass the exact StrategyCandidate back
    into SignalBuilder after all normal freshness and hard validation checks.
    """
    try:
        if not bool(CONFIG.get("V699_TRUE_CANDIDATE_RECALL_ENABLE", True)) or candidate is None:
            return
        key = "%s:%s:%s:%s" % (getattr(candidate, "symbol", symbol),
                               getattr(candidate, "strategy_mode", ""),
                               getattr(candidate, "generated_at_ms", 0), id(candidate))
        _V699_RECALL_CANDIDATE_STORE[key] = candidate
        _V699_RECALL_CANDIDATE_ORDER.append(key)
        while len(_V699_RECALL_CANDIDATE_STORE) > int(CONFIG.get("V699_TRUE_CANDIDATE_RECALL_STORE_MAX", 512)):
            try:
                old = _V699_RECALL_CANDIDATE_ORDER.popleft()
                _V699_RECALL_CANDIDATE_STORE.pop(old, None)
            except IndexError:
                break
        ctx["v699_candidate_key"] = key
    except Exception:
        _v647_record_suppressed_exception()

try:
    _v699_orig_record_mse_rank_reject = _v554_record_mse_rank_reject
    def _v699_record_mse_rank_reject_with_provenance(symbol, reason, candidate=None, **ctx):
        _v699_remember_rejected_candidate(symbol, reason, candidate, **ctx)
        try:
            key = "%s:%s:%s:%s" % (getattr(candidate, "symbol", symbol), getattr(candidate, "strategy_mode", ""), getattr(candidate, "generated_at_ms", 0), id(candidate)) if candidate is not None else ""
            if key:
                ctx = dict(ctx or {})
                ctx["v699_candidate_key"] = key
        except Exception:
            pass
        return _v699_orig_record_mse_rank_reject(symbol, reason, candidate, **ctx)
    _v554_record_mse_rank_reject = _v699_record_mse_rank_reject_with_provenance
except Exception as _e:
    STATS["v699_rt_wire_errors"] = int(STATS.get("v699_rt_wire_errors", 0) or 0) + 1


def _v699_recall_pool_from_telemetry():
    """Build recall candidate dicts from THIS window's rank-reject telemetry.
    Read-only over existing telemetry; no market fetch; no order path."""
    pool = []
    try:
        hist = list(STATS.get("v554_mse_rank_reject_history") or [])[-256:]
        now_w = WALL_NOW()
        for rec in hist:
            try:
                if now_w - float(rec.get("ts", 0.0) or 0.0) > 600.0:
                    continue
                sym = str(rec.get("symbol") or "")
                if not sym:
                    continue
                rsn = str(rec.get("reason") or "")
                root = _v699_root_of(rsn)
                hard = root in ("LIQUIDITY", "SYSTEM", "DATA_MISSING") or any(
                    tok in rsn.lower() for tok in ("forbidden", "blacklist", "balance", "truth", "exposure"))
                pool.append({
                    "symbol": sym,
                    "score": float(rec.get("engine_score") or 0.0),
                    "strategy_mode": str(rec.get("strategy_mode") or rec.get("mode") or "NA"),
                    "candle_ts": rec.get("candle_ts") or int(rec.get("ts", 0) or 0),
                    "hard_fail": hard,
                    "hard_eligible": not hard,
                    "failed_dimension": root if root in ("SCORE", "HTF", "STRUCTURE", "SPREAD", "VOLUME", "ENTRY_ZONE", "FEE") else "SCORE",
                    "recoverable": root in ("HTF", "STRUCTURE", "SPREAD", "VOLUME", "ENTRY_ZONE"),
                    "candidate": _V699_RECALL_CANDIDATE_STORE.get(str((rec.get("ctx") or {}).get("v699_candidate_key") or "")),
                })
            except Exception:
                continue
    except Exception:
        _v647_record_suppressed_exception()
    return pool


try:
    _v699_orig_rank_and_select = GlobalOpportunityBrain.rank_and_select

    def _v699_rank_and_select(cls, market_data_map):
        result = _v699_orig_rank_and_select(market_data_map)
        try:
            ranked_list = list(result or [])
            # -- per-family telemetry + survival estimate (ranking only) ------
            producing = set()
            fam_counts = {}
            for r in ranked_list:
                try:
                    c = getattr(r, "candidate", None)
                    mode = str(getattr(c, "strategy_mode", "") or "")
                    fam = _v699_family_of(mode)
                    producing.add(fam)
                    fam_counts[fam] = fam_counts.get(fam, 0) + 1
                    snap = {
                        "price": 1, "atr": 1, "volume_ratio": 1,
                        "htf_state": True, "structure": True, "entry_ref": 1,
                        "score": float(getattr(r, "composite", 0.0) or 0.0) * 100.0
                        if float(getattr(r, "composite", 0.0) or 0.0) <= 1.0
                        else float(getattr(r, "composite", 0.0) or 0.0),
                    }
                    est = _v699_estimated_canonical_survival(snap)
                    surv = STATS.setdefault("v699_survival_by_symbol", {})
                    surv[str(getattr(c, "symbol", ""))] = est
                except Exception:
                    continue
            for fam, n in fam_counts.items():
                _v699_daily_note("n", n, bucket="per_family_candidates", bucket_key=fam)
            STATS["v699_family_budgets"] = _v699_family_budgets(producing)

            # -- diversity tie-break: reorder ONLY near-ties, never cut -------
            if (CONFIG.get("V699_DIVERSITY_TIEBREAK_ENABLE", True) and len(ranked_list) > 1):
                import functools as _ft

                def _score_of(r):
                    return float(getattr(r, "composite", 0.0) or 0.0)

                def _cmp(a, b):
                    try:
                        da = {"score": _score_of(a), "strategy_mode": str(getattr(getattr(a, "candidate", None), "strategy_mode", "") or "")}
                        db = {"score": _score_of(b), "strategy_mode": str(getattr(getattr(b, "candidate", None), "strategy_mode", "") or "")}
                        rep = fam_counts.keys()
                        tb = _v699_diversity_tiebreak(da, db, rep)
                        if tb != 0:
                            STATS["v699_diversity_tiebreak_applied"] = int(
                                STATS.get("v699_diversity_tiebreak_applied", 0) or 0) + 1
                            return tb
                    except Exception:
                        pass
                    return -1 if _score_of(a) > _score_of(b) else (1 if _score_of(a) < _score_of(b) else 0)

                ranked_list = sorted(ranked_list, key=_ft.cmp_to_key(_cmp))
                result = ranked_list

            # -- canonical recall on empty selection --------------------------
            generated = int(STATS.get("v45_global_generated", 0) or 0)
            pre = int(STATS.get("v45_global_prequalified", 0) or 0)
            if (not ranked_list) and generated > 0 and CONFIG.get("V699_CANONICAL_RECALL_ENABLE", True):
                if _v699_rt_kill_or_blocked():
                    STATS["v699_recall_blocked_hazard"] = int(STATS.get("v699_recall_blocked_hazard", 0) or 0) + 1
                else:
                    pool = _v699_recall_pool_from_telemetry()
                    retained = _v699_select_retained(pool)  # strategy-aware retention in the recall lane
                    retained.sort(key=lambda c: (_v699_estimated_canonical_survival(
                        {"price": 1, "atr": 1, "volume_ratio": 1, "htf_state": True,
                         "structure": True, "entry_ref": 1, "score": c.get("score", 0.0)}),
                        float(c.get("score", 0.0))), reverse=True)
                    recalled = _v699_recall_candidates(retained)[:int(CONFIG.get("V699_RECALL_ROUTE_MAX_PER_CYCLE", 3))]
                    if recalled:
                        try:
                            loop = asyncio.get_running_loop()
                        except RuntimeError:
                            loop = None
                        for c in recalled:
                            sym = str(c.get("symbol") or "")
                            if not sym:
                                continue
                            if _v699_candle_dedup(sym, c.get("candle_ts"), c.get("strategy_mode", "RECALL")):
                                STATS["v699_recall_not_eligible"] = int(STATS.get("v699_recall_not_eligible", 0) or 0) + 1
                                continue
                            md = (market_data_map or {}).get(sym)
                            if md is None:
                                STATS["v699_recall_not_eligible"] = int(STATS.get("v699_recall_not_eligible", 0) or 0) + 1
                                continue
                            if loop is not None:
                                logger.info("[V699-RECALL] routing recalled candidate %s via canonical SignalBuilder", sym)
                                loop.create_task(_v699_route_recalled(sym, md, recalled_candidate=c.get("candidate")))
        except Exception as _rk:
            STATS["v699_rank_layer_errors"] = int(STATS.get("v699_rank_layer_errors", 0) or 0) + 1
            logger.debug(f"[V699-RANK] integration layer suppressed: {_rk}")
        return result

    GlobalOpportunityBrain.rank_and_select = classmethod(_v699_rank_and_select)
except Exception as _e:
    STATS["v699_rt_wire_errors"] = int(STATS.get("v699_rt_wire_errors", 0) or 0) + 1


# --- Wiring 10: unified starvation controller on the canonical funnel ledger --
try:
    _v699_orig_note_cycle = V45GlobalFunnelState.note_cycle

    def _v699_note_cycle(cls, generated, eligible, ranked, winners, top_score=0.0, *a, **kw):
        out = _v699_orig_note_cycle(generated, eligible, ranked, winners, top_score, *a, **kw)
        try:
            zero = int(winners or 0) == 0
            root = "OTHER"
            hazard = False
            try:
                truth_fn = globals().get("_v699_truthful_starvation_snapshot")
                truth = truth_fn() if callable(truth_fn) else {}
                root = str(truth.get("root") or "OTHER").upper()
                hazard = root == "SYSTEM"
            except Exception:
                pass
            ks = False
            try:
                ks = bool(KillSwitch.is_active())
            except Exception:
                ks = True
            live_blocked = False
            try:
                live_blocked = not LiveStateMachine.is_live_runnable()
            except Exception:
                live_blocked = True
            branch = _V699_STARVATION.note_cycle(
                zero, dominant_root=root, hazard=hazard,
                kill_switch=ks, live_blocked=live_blocked)
            floor = _V699_STARVATION.maybe_relax(
                dominant_root=root, hazard=hazard, kill_switch=ks, live_blocked=live_blocked)
            STATS["v699_starvation_branch"] = branch
            STATS["v699_starvation_root"] = root
            STATS["v699_effective_canonical_floor"] = floor
            if int(winners or 0) > 0:
                _V699_STARVATION.note_success()
            # Daily funnel + root distribution telemetry.
            _v699_daily_note("generated", int(generated or 0))
            _v699_daily_note("prequalified", int(eligible or 0))
            _v699_daily_note("ranked", int(ranked or 0))
            _v699_daily_note("selected", int(winners or 0))
            if zero:
                _v699_daily_note("n", 1, bucket="root_distribution", bucket_key=root)
            # Dynamic deep-scan target bounded to [130, 170]; visible in CONFIG
            # and telemetry, applied by the V650 radar on the next cycle.
            try:
                streak = int(getattr(_V699_STARVATION, "zero_winner_streak", 0) or 0)
                if streak >= int(CONFIG.get("V699_ADAPTIVE_STRONG_STREAK", 3)):
                    tgt = int(CONFIG.get("V699_DEEP_SCAN_STARVING_N", 170))
                elif streak >= 1:
                    tgt = int(CONFIG.get("V699_DEEP_SCAN_ELEVATED_N", 150))
                else:
                    tgt = int(CONFIG.get("V699_DEEP_SCAN_NORMAL_N", 130))
                tgt = max(int(CONFIG.get("V699_UNIVERSE_DEEP_MIN", 130)),
                          min(int(CONFIG.get("V699_UNIVERSE_DEEP_MAX", 170)), tgt))
                CONFIG["V650_LIQUIDITY500_DEEP_SCAN_N"] = tgt
                STATS["v699_deep_scan_target"] = tgt
            except Exception:
                _v647_record_suppressed_exception()
        except Exception:
            _v647_record_suppressed_exception()
        return out

    V45GlobalFunnelState.note_cycle = classmethod(_v699_note_cycle)
except Exception as _e:
    STATS["v699_rt_wire_errors"] = int(STATS.get("v699_rt_wire_errors", 0) or 0) + 1


