# =============================================================================
# V699 — OFFLINE DETERMINISTIC SCENARIO TESTS (acceptance #62)
# Decision-layer scenarios; no network, no orders, deterministic.
# =============================================================================
def _v699_offline_scenarios():
    res = {}

    def ok(name, cond):
        res[name] = bool(cond)
        return bool(cond)

    t0 = time.time()
    # 1. strong pullback -> high-score candidate retains in pool
    pool = [{"symbol": "A/USDT", "score": 71.5, "strategy_mode": "PULLBACK", "candle_ts": 1}]
    ok("strong_pullback_retained", len(_v699_select_retained(pool)) == 1)
    # 2. shallow pullback (score below floor, gap<=3) -> near-miss recall eligible.
    # Score is derived from the CURRENT effective floor so the scenario stays
    # valid regardless of any starvation-relief state left by earlier tests.
    _floor_now = float(STATS.get("v453_effective_canonical_floor",
                                 CONFIG.get("MIN_LIVE_SCORE", 70)) or 70)
    nm = [{"symbol": "B/USDT", "score": _floor_now - 1.5, "strategy_mode": "PULLBACK", "candle_ts": 1,
           "hard_eligible": True, "failed_dimension": "SCORE"}]
    rec = _v699_recall_candidates(nm, now=t0)
    ok("shallow_pullback_near_miss_recall", len(rec) == 1 and rec[0].get("requires_canonical_builder") is True
       and rec[0].get("direct_execution") is False)
    # 3. MTF transitional pullback -> recoverable HTF dimension recall eligible
    mtf = [{"symbol": "C/USDT", "score": 60.0, "strategy_mode": "MTF_PULLBACK", "candle_ts": 1,
            "hard_eligible": True, "failed_dimension": "HTF", "recoverable": True}]
    ok("mtf_transitional_recoverable", len(_v699_recall_candidates(mtf, now=t0)) == 1)
    # 4. breakout with delayed volume -> VOLUME near-miss policy exists
    ok("breakout_delayed_volume_policy", _v699_near_miss_policy("VOLUME") == "ONE_CANDLE_CONFIRMATION_WINDOW")
    # 5. sweep with ATR-equal lows -> sweep mode maps to its own family
    ok("sweep_family_mapping", _v699_family_of("LIQUIDITY_SWEEP_REVERSAL") == "LIQUIDITY_SWEEP_REVERSAL")
    # 6. oversold mean reversion (RSI<=22) -> bounded discovery, needs evidence
    tag, allow = _v699_mean_reversion_gate(21.0, has_reclaim_evidence=False)
    ok("oversold_bounded_discovery", tag == "OVERSOLD_DISCOVERY" and allow is False)
    # 7. overbought RSI>78 -> observation only, never direct long
    tag2, allow2 = _v699_mean_reversion_gate(80.0, has_reclaim_evidence=True)
    ok("overbought_no_direct_long", tag2 == "EXHAUSTION_OBSERVATION" and allow2 is False)
    # 8. trend continuation with weak 1D -> HTF weak reason split
    ok("htf_weak_reason", _v699_htf_reject_reason({"weak": True}) == "WEAK")
    # 9. RS leader without breakout -> own family, not LOCAL_STRENGTH alias
    ok("rs_leader_own_family", _v699_family_of("RELATIVE_STRENGTH_LEADER") == "RELATIVE_STRENGTH")
    # 10. compression expansion -> mode keeps family metadata separation
    ok("volatility_burst_family", _v699_family_of("VOLATILITY_BURST") == "MOMENTUM_EXPANSION")
    # 11. swing early setup -> SWING_EARLY execution profile
    ok("swing_early_profile", _v699_execution_profile("SWING_PULLBACK") == "SWING_EARLY")
    # 12. extreme flush delayed higher-low -> RECLAIM policy waits confirmation
    ok("flush_reclaim_policy", _v699_near_miss_policy("RECLAIM") == "WAIT_RECLAIM_CONFIRMATION")
    # 13. continuation reclaim -> family metadata present
    ok("continuation_reclaim_family", isinstance(_v699_family_of("CONTINUATION_RECLAIM"), str))
    # 14. failed breakout multi-bar -> BREAKOUT revalidation policy
    ok("failed_breakout_policy", _v699_near_miss_policy("BREAKOUT") == "REVALIDATE_FROM_FRESH_CLOSED_CANDLE")
    # 15. no-opportunity market -> recall empty, zero winners, no relief without SCORE root
    ok("no_opp_recall_empty", _v699_recall_candidates([], now=t0) == [])
    ctl = V699StarvationController()
    ctl.note_cycle(True, dominant_root="HTF", now=t0)
    f0 = ctl.effective_floor()
    ctl.maybe_relax(dominant_root="HTF", now=t0 + 400.0)
    ok("no_opp_no_score_relief_on_htf_root", ctl.effective_floor() == f0)
    # 16. fee_unviable -> bounded resize never exceeds MAX_POSITION_SIZE_USDT
    cap = float(CONFIG.get("MAX_POSITION_SIZE_USDT", 75.0))
    rz = _v699_fee_resize(999.0, 500.0)
    ok("fee_unviable_resize_capped", rz is not None and rz <= cap)
    ok("fee_resize_none_when_no_balance", _v699_fee_resize(50.0, 0.0) is None)
    # 17. transient spread failure -> near-miss queued, ceiling unchanged
    ceil_before = dict(CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {})
    _v699_spread_near_miss("TST/USDT", "MID", 9.99, now=t0)
    due = _v699_spread_recheck_due(now=t0)
    ok("transient_spread_queued", any(e["symbol"] == "TST/USDT" for e in due))
    ok("spread_ceiling_unchanged", dict(CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}) == ceil_before)
    # 18. missing snapshot field -> recovery or fail-closed DATA_MISSING (no network)
    rec_facts, still = _v699_same_snapshot_fact_recovery(
        {"volume": 10.0, "volume_ma": 5.0, "price": 100.0}, ["volume_ratio", "atr"])
    ok("missing_field_recovery", rec_facts.get("volume_ratio") == 2.0 and "atr" in still)
    # 19. engine exception -> ENGINE_ERROR + breaker DEGRADED -> HALF_OPEN probe
    ok("engine_exception_taxonomy", _v699_classify_engine_outcome(exc=ValueError("x")) == "ENGINE_ERROR")
    br = V699EngineCircuitBreaker("T")
    for _ in range(int(CONFIG.get("V699_ENGINE_CB_ERROR_BURST", 5))):
        br.note_error()
    s1 = br.state
    br.state_since -= float(CONFIG.get("V699_ENGINE_CB_DEGRADED_SEC", 120.0)) + 1
    allowed = br.allow()
    br.note_success()
    ok("breaker_half_open_recovery", s1 == "DEGRADED" and allowed and br.state == "ACTIVE")
    # 20. family collision -> dedup keys differ per mode; retention keeps alt family
    k1 = _v699_dedup_key("A/USDT", 1, "PULLBACK")
    k2 = _v699_dedup_key("A/USDT", 1, "RELATIVE_STRENGTH_LEADER")
    mixed = [{"symbol": "A/USDT", "score": 70 - i * 0.1, "strategy_mode": m, "candle_ts": 1}
             for i, m in enumerate(["PULLBACK", "PULLBACK", "PULLBACK", "RELATIVE_STRENGTH_LEADER",
                                    "MICRO_TREND_CONTINUATION", "VOLATILITY_BURST"])]
    retained = _v699_select_retained(mixed, global_cap=6)
    fams = {c.get("family") for c in retained}
    ok("family_collision_dedup", k1 != k2)
    ok("family_collision_alt_family_kept", len(fams) >= 2)
