def _v699_lifecycle_self_test():
    """Deterministic wiring test for the full candidate handoff contract.

    It does not place an order or contact an exchange. The test validates that
    a rejected candidate can be preserved as provenance and routed through the
    exact preferred_candidate parameter that the canonical builder exposes.
    """
    if not bool(CONFIG.get("V699_LIFECYCLE_TEST_ENABLE", True)):
        return {"pass": True, "checks": {"disabled": True}, "failed": []}
    checks = {}
    try:
        fs = {"hard_valid": True, "volume_ratio": 1.2, "htf_strength": 75, "chase_atr": 0.5}
        c = StrategyCandidate(
            engine_id="lifecycle_test", symbol="V699TEST/USDT", side="long", generated_at_ms=int(time.time()*1000),
            entry_ref=100.0, sl_price=98.0, tp1_rr=float(CONFIG.get("TP1_RR", 1.0)),
            tp2_rr=float(CONFIG.get("TP2_RR", 2.0)), tp3_rr=float(CONFIG.get("TP3_RR", 3.0)),
            engine_score=0.69, rr_ratio=1.5, liquidity_score=0.9, regime_fit=0.8,
            family="RELATIVE_STRENGTH", zone_ref=100.0, features_snapshot=fs,
            strategy_mode="RELATIVE_STRENGTH_LEADER", strategy_style="SCALP",
            market_phase="TRENDING", macro_regime="BULLISH", local_regime="BULLISH")
        _V699_RECALL_CANDIDATE_STORE.clear(); _V699_RECALL_CANDIDATE_ORDER.clear()
        _v699_remember_rejected_candidate(c.symbol, "test.score", c)
        key = "%s:%s:%s:%s" % (c.symbol, c.strategy_mode, c.generated_at_ms, id(c))
        checks["candidate_provenance_stored"] = _V699_RECALL_CANDIDATE_STORE.get(key) is c
        # Recall candidate must be a genuine near-miss below the current base
        # canonical floor; the production effective floor may be relaxed to 62
        # during starvation, so the test pins the base floor explicitly.
        _old_eff_floor = STATS.get("v453_effective_canonical_floor", None)
        STATS["v453_effective_canonical_floor"] = float(CONFIG.get("MIN_LIVE_SCORE", 70.0))
        try:
            pool = [{"symbol": c.symbol, "score": 68.5, "strategy_mode": c.strategy_mode,
                     "candle_ts": c.generated_at_ms, "hard_fail": False, "hard_eligible": True,
                     "failed_dimension": "SCORE", "recoverable": False, "candidate": c}]
            selected = _v699_recall_candidates(pool, now=time.time())
        finally:
            if _old_eff_floor is None:
                STATS.pop("v453_effective_canonical_floor", None)
            else:
                STATS["v453_effective_canonical_floor"] = _old_eff_floor
        checks["recall_retains_exact_candidate"] = bool(selected) and selected[0].get("candidate") is c
        checks["builder_accepts_preferred_parameter"] = "preferred_candidate" in __import__("inspect").signature(SignalBuilder.build_and_route).parameters
        checks["recall_is_discovery_only"] = all(bool(x.get("direct_execution") is False) for x in selected)

        # Exercise the actual async recall route without touching an exchange:
        # monkeypatch only the canonical builder call and verify identity
        # propagation. All real runtime routes still invoke the unchanged builder.
        _captured = {}
        _orig_builder = SignalBuilder.build_and_route
        async def _fake_builder(exchange, symbol, market_data, preferred_candidate=None):
            _captured["symbol"] = symbol
            _captured["preferred_candidate"] = preferred_candidate
            return None
        _old_exchange = _V699_RT_EXCHANGE_REF.get("exchange")
        _V699_RT_EXCHANGE_REF["exchange"] = object()
        try:
            SignalBuilder.build_and_route = staticmethod(_fake_builder)
            old_guard = globals().get("_v699_rt_kill_or_blocked")
            globals()["_v699_rt_kill_or_blocked"] = lambda: False
            _old_active = dict(ACTIVE_TRADES)
            ACTIVE_TRADES.clear()
            try:
                _v517_run_awaitable_sync(_v699_route_recalled(c.symbol, {}, recalled_candidate=c))
            finally:
                ACTIVE_TRADES.clear(); ACTIVE_TRADES.update(_old_active)
            globals()["_v699_rt_kill_or_blocked"] = old_guard
        finally:
            SignalBuilder.build_and_route = _orig_builder
            _V699_RT_EXCHANGE_REF["exchange"] = _old_exchange
        checks["route_passes_exact_candidate_to_builder"] = _captured.get("preferred_candidate") is c
    except Exception as exc:
        checks["exception"] = False
        STATS["v699_lifecycle_self_test_error"] = "%s:%s" % (type(exc).__name__, exc)
    return {"pass": bool(all(checks.values())), "checks": checks,
            "failed": [k for k, v in checks.items() if not v]}


