def _v699_live_top_rejects(n: int = 3):
    try:
        rej = STATS.get("rejections") or {}
        out=[]
        for k,v in rej.items():
            cur=int(v or 0)
            base=int(_V699_BOOT_REJECTION_BASELINE.get(str(k),0) or 0)
            d=max(0,cur-base)
            if d>0:
                out.append((str(k),d))
        out.sort(key=lambda kv:(-kv[1],kv[0]))
        return out[:max(1,int(n))]
    except Exception:
        return []

