# Also sanitize the watchdog recent-error count to the live runtime epoch.
try:
    _v699_prev_snapshot_obs = Telemetry.snapshot
    if not getattr(_v699_prev_snapshot_obs, "_v699_live_epoch", False):
        def _v699_snapshot_live_epoch():
            snap = _v699_prev_snapshot_obs()
            try:
                wd = dict(snap.get("watchdog") or {})
                cutoff = MONO_NOW() - max(1.0, float(CONFIG.get("WATCHDOG_WINDOW_SEC",120.0)))
                epoch = float(_V699_LIVE_WATCHDOG_EPOCH_MONO)
                errs = getattr(ExchangeWatchdog, "_errors", ())
                live_recent = sum(1 for ts in list(errs) if float(ts) >= max(cutoff, epoch))
                wd["recent_errors_count"] = int(live_recent)
                wd["v699_live_epoch"] = True
                snap["watchdog"] = wd
                snap["v699_truth"] = _v699_truthful_starvation_snapshot()
            except Exception:
                pass
            return snap
        _v699_snapshot_live_epoch._v699_live_epoch = True
        Telemetry.snapshot = staticmethod(_v699_snapshot_live_epoch)
except Exception:
    pass

# Append exact cycle-root and DD reason to the heartbeat without changing the
# original heartbeat renderer's existing safety fields.
try:
    _v699_prev_emit_hb = Telemetry.emit_heartbeat
    if not getattr(_v699_prev_emit_hb, "_v699_truth_hb", False):
        async def _v699_emit_heartbeat_truth():
            truth = _v699_truthful_starvation_snapshot()
            STATS["v699_truth_root"] = truth.get("root", "NONE")
            STATS["v699_truth_detail"] = truth.get("detail", "")
            STATS["v425_starvation_mode"] = str(truth.get("root", "NONE"))
            STATS["v699_cycle_nfm"] = _v699_cycle_nfm_count()
            try:
                _nfm_cycle = max(0, int(STATS.get("v699_cycle_nfm", 0) or 0))
                _gen_cycle = max(0, int(STATS.get("v681_runtime_cycle_generated", 0) or 0))
                _nfm_denom = max(1, _nfm_cycle + _gen_cycle)
                STATS["v699_cycle_nfm_ratio"] = round(
                    float(_nfm_cycle) / float(_nfm_denom), 4
                )
                STATS["v699_cycle_nfm_ratio_denominator"] = "generated_plus_nfm"
            except Exception:
                STATS["v699_cycle_nfm_ratio"] = 0.0
                STATS["v699_cycle_nfm_ratio_denominator"] = "generated_plus_nfm"
            def _v699_resolve_live_entry_status(root_value):
                """Report entry authority separately from funnel/starvation causes."""
                root_name = str(root_value or "NONE").upper()
                try:
                    refresh_mode = globals().get("_V702_R39_REFRESH_ENTRY_MODE")
                    monitor_only = bool(refresh_mode()) if callable(refresh_mode) else bool(CONFIG.get("V702_MONITOR_ONLY_MODE", True))
                    policy_name = str(STATS.get("v702_runtime_entry_policy", "MONITOR_ONLY_NO_NEW_BUYS") or "MONITOR_ONLY_NO_NEW_BUYS")
                    if monitor_only or policy_name.startswith("MONITOR_ONLY"):
                        return False, "MONITOR_ONLY", "BLOCKED:MONITOR_ONLY"
                    _a19_diag_raw = os.environ.get("UNIFIED_A19_DIAGNOSTIC_ONLY", "0").strip().lower()
                    _a19_diag_only = _a19_diag_raw not in {"0", "false", "no", "off", "disabled"}
                    if _a19_diag_only:
                        STATS["v702_a19_diagnostic_only_effective"] = True
                        return False, "A19_DIAGNOSTIC_ONLY", "BLOCKED:A19_DIAGNOSTIC_ONLY"
                    STATS["v702_a19_diagnostic_only_effective"] = False
                except Exception:
                    # Mode uncertainty must never be displayed as entry-ready.
                    return False, "ENTRY_MODE_UNVERIFIED", "BLOCKED:ENTRY_MODE_UNVERIFIED"
                try:
                    if KillSwitch.is_active():
                        return False, "KILL_SWITCH", "BLOCKED:KILL_SWITCH"
                except Exception:
                    return False, "KILL_SWITCH_STATE_UNVERIFIED", "BLOCKED:KILL_SWITCH_STATE_UNVERIFIED"
                try:
                    if ExchangeWatchdog.is_tripped():
                        return False, "EXCHANGE_WATCHDOG", "BLOCKED:EXCHANGE_WATCHDOG"
                except Exception:
                    return False, "WATCHDOG_STATE_UNVERIFIED", "BLOCKED:WATCHDOG_STATE_UNVERIFIED"
                base_ready = bool(STATS.get("v684_live_ready", STATS.get("v699_live_ready", 0)) or 0)
                if base_ready:
                    return True, "NONE", "READY"
                cause = root_name if root_name not in ("", "NONE") else "NO_LIVE_READY"
                return False, cause, "BLOCKED:%s" % cause

            try:
                _base_ready_now, _reason_now, _status_now = _v699_resolve_live_entry_status(truth.get("root", "NONE"))
                STATS["v699_entry_block_reason"] = _reason_now
                STATS["v699_live_entry_ready"] = _base_ready_now
                STATS["v699_live_entry_status"] = _status_now
                STATS["v699_live_entry_status_ts"] = float(WALL_NOW())
            except Exception:
                STATS["v699_entry_block_reason"] = "ENTRY_STATUS_UNVERIFIED"
                STATS["v699_live_entry_ready"] = False
                STATS["v699_live_entry_status"] = "BLOCKED:ENTRY_STATUS_UNVERIFIED"
                STATS["v699_live_entry_status_ts"] = float(WALL_NOW())
            try:
                st = await _v699_prev_emit_hb()
                # Add a compact operator-only line; original heartbeat remains intact.
                try:
                    _root2 = str(STATS.get("v699_truth_root", "NONE") or "NONE").upper()
                    _ready2, _reason2, _status2 = _v699_resolve_live_entry_status(_root2)
                    STATS["v699_live_entry_ready"] = _ready2
                    STATS["v699_entry_block_reason"] = _reason2
                    STATS["v699_live_entry_status"] = _status2
                    STATS["v699_live_entry_status_ts"] = float(WALL_NOW())
                except Exception:
                    STATS["v699_live_entry_ready"] = False
                    STATS["v699_live_entry_status"] = "BLOCKED:ENTRY_STATUS_UNVERIFIED"
                    STATS["v699_live_entry_status_ts"] = float(WALL_NOW())
                logger.info(
                    "[V699-TRUTH] cycle=%s root=%s detail=%s mse_cycle=%d/%d/%d/%d/%d/%d "
                    "nfm_cycle=%d ratio=%.4f entry_block=%s eerr_live=%d preq_roots=%s",
                    int(STATS.get("v681_runtime_cycle_id",0) or 0),
                    truth.get("root","NONE"), str(truth.get("detail","") or "")[:180],
                    int(STATS.get("v681_runtime_cycle_generated",0) or 0),
                    int(STATS.get("v681_runtime_cycle_prequal",0) or 0),
                    int(STATS.get("v681_runtime_cycle_ranked",0) or 0),
                    int(STATS.get("v681_runtime_cycle_selected",0) or 0),
                    int(STATS.get("v681_runtime_cycle_queued",0) or 0),
                    int(STATS.get("v681_runtime_cycle_sent",0) or 0),
                    int(STATS.get("v699_cycle_nfm",0) or 0),
                    float(STATS.get("v699_cycle_nfm_ratio",0.0) or 0.0),
                    STATS.get("v699_entry_block_reason","NONE"),
                    int(_v699_daily_live_value("engine_errors") if bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)) else 0),
                    dict(_v699_prequal_root_window(float(CONFIG.get("V420_FUNNEL_STARV_WINDOW_MIN",12))*60.0)),
                )
                return st
            except Exception:
                return None
        _v699_emit_heartbeat_truth._v699_truth_hb = True
        Telemetry.emit_heartbeat = staticmethod(_v699_emit_heartbeat_truth)
except Exception:
    pass

# Final self-test set for this closure. These are structural/telemetry tests;
# none authorize a trade.
def _v699_observability_closure_test():
    checks={}
    error = None
    try:
        checks["live_epoch_baseline"] = isinstance(_V699_BOOT_REJECTION_BASELINE, dict)
        checks["truth_function"] = callable(_v699_truthful_starvation_snapshot)
        checks["summary_truthful"] = "BUILD_IN=" in _v699_daily_summary_text() and "CANON=" in _v699_daily_summary_text()
        checks["boot_test_counters_isolated"] = "eerr=0" in _v699_daily_summary_text() or int(STATS.get("v699_daily_canonical_pass",0) or 0) >= int(_V699_DAILY_BOOT_BASELINE.get("v699_daily_canonical_pass",0) or 0)
        _ratio_probe = 120.0 / max(1.0, 120.0 + 34.0)
        checks["cycle_nfm_ratio_bounded"] = (
            0.0 <= float(_ratio_probe) <= 1.0
            and str(STATS.get("v699_cycle_nfm_ratio_denominator", "generated_plus_nfm")) == "generated_plus_nfm"
        )
        checks["dynamic_universe_seed_bounded"] = int(_seed_target if "_seed_target" in globals() else CONFIG.get("V699_DEEP_SCAN_NORMAL_N",130)) >= 130
        checks["watchdog_live_epoch_sanitizer"] = callable(globals().get("_v699_snapshot_live_epoch"))
        checks["drawdown_halt_removed"] = (not EquityDrawdownHalt.blocks_new_entries() and "EQUITY_PEAK_DRAWDOWN_HALT_PCT" not in CONFIG)
        checks["long_only_spot"] = bool(CONFIG.get("LONG_ONLY",True)) and str(CONFIG.get("MARKET_TYPE","SPOT")).upper()=="SPOT" and not bool(CONFIG.get("ALLOW_SHORT",False)) and not bool(CONFIG.get("ENABLE_FUTURES",False))
        checks["canonical_builder"] = callable(getattr(SignalBuilder,"build_and_route",None))
        checks["validate_only_deferred"] = bool(globals().get("_V699_VALIDATE_ONLY_REQUEST", False) or "_V699_VALIDATE_ONLY_REQUEST" in globals())
        checks["cycle_rank_source_is_runtime"] = callable(globals().get("_v699_base_hb_cycle_accounting"))
        try:
            _hb_probe = _v697_base_hb_segment()
            checks["mse_segment_cycle_scoped"] = "MSE[CYCLE G=" in _hb_probe and "MSE_RANK[CYCLE=" in _hb_probe
        except Exception:
            checks["mse_segment_cycle_scoped"] = False
        checks["entry_status_observable"] = "v699_live_entry_status" in STATS or "v699_entry_block_reason" in STATS
        checks["prequal_root_window_live_epoch_aware"] = callable(globals().get("_v699_prequal_root_window"))
        _dd_truth = _v699_truthful_starvation_snapshot()
        checks["drawdown_not_starvation_root"] = _dd_truth.get("entry_block") != "DD_HALT" and _dd_truth.get("detail") != "equity_drawdown_halt"
        checks["summary_excludes_boot_when_unarmed"] = (not bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)) and "eerr=0" in _v699_daily_summary_text()) or bool(globals().get("_V699_LIVE_EPOCH_ARMED", False))
    except Exception as exc:
        error = f"{type(exc).__name__}:{str(exc)[:240]}"
    failed = [k for k, value in checks.items() if value is not True]
    if error is not None:
        failed.append("exception")
    result = {"pass": bool(error is None and bool(checks) and not failed),
              "checks": checks, "failed": failed}
    if error is not None:
        result["error"] = error
    return result

_V699_OBSERVABILITY_CLOSURE_TEST = _v699_observability_closure_test()
STATS["v699_observability_closure_test"] = _V699_OBSERVABILITY_CLOSURE_TEST

# Extend the already-terminal V699 validator with the observability closure.
_v699_prev_validate = globals().get("validate_config")
def _v699_validate_config_terminal_final():
    base = bool(callable(_v699_prev_validate) and _v699_prev_validate())
    obs = bool(_V699_OBSERVABILITY_CLOSURE_TEST.get("pass", False))
    STATS["v699_full_validation_observability"] = {"base":base,"observability":obs}
    return bool(base and obs)
globals()["validate_config"] = _v699_validate_config_terminal_final


def _v699_arm_live_epoch():
    """Arm LIVE telemetry only after all import-time validators/self-tests have completed."""
    global _V699_LIVE_EPOCH_ARMED, _V699_LIVE_TELEMETRY_EPOCH, _V699_LIVE_WATCHDOG_EPOCH_MONO
    global _V699_BOOT_REJECTION_BASELINE, _V699_DAILY_BOOT_BASELINE, _V699_NFM_BASELINE
    _V699_LIVE_EPOCH_ARMED = True
    _V699_LIVE_TELEMETRY_EPOCH = WALL_NOW()
    _V699_LIVE_WATCHDOG_EPOCH_MONO = MONO_NOW()
    # V702 R11: boot/import self-test watchdog transport errors must not leak into
    # LIVE protection or heartbeat counters.  Do not clear an active trip; the
    # preflight must already have passed when this epoch is armed.
    try:
        if MONO_NOW() >= float(getattr(ExchangeWatchdog, "_tripped_until", 0.0) or 0.0):
            ExchangeWatchdog._errors.clear()
            ExchangeWatchdog._last_reason = ""
    except Exception:
        pass
    # Venue submission telemetry is scoped to this real LIVE epoch so import-time
    # self-tests can never inflate the operator-facing total.
    STATS["v701_live_epoch_order_submit_base"] = int(STATS.get("v701_order_submit_attempts", 0) or 0)
    rej = STATS.get("rejections") or {}
    _V699_BOOT_REJECTION_BASELINE = {str(k): int(v or 0) for k,v in rej.items()} if hasattr(rej, "items") else {}
    _V699_DAILY_BOOT_BASELINE = {k: int(v or 0) for k,v in dict(_V699_DAILY).items() if isinstance(v, (int,float))}
