# Backward-compatibility alias for evidence readers; no runtime wrapper depends on it.
_V701_2_STRATEGY_CONTRACTS = _V701_3_STRATEGY_CONTRACTS


def _v701_3_strategy_family(candidate, engine_cls=None):
    fam = str(getattr(candidate, "family", "") or "").upper()
    if fam:
        return fam
    mode = str(getattr(candidate, "strategy_mode", "") or "").upper()
    if mode in _V701_3_STRATEGY_CONTRACTS:
        return str(_V701_3_STRATEGY_CONTRACTS[mode]["family"]).upper()
    if engine_cls is not None:
        em = str(getattr(engine_cls, "engine_id", "") or getattr(engine_cls, "__name__", "")).lower()
        for rec in _V701_3_STRATEGY_CONTRACTS.values():
            if str(rec.get("engine", "")).lower() == em:
                return str(rec.get("family", "OTHER")).upper()
        fmap = getattr(engine_cls, "family_map", ()) or ()
        if fmap:
            return str(fmap[0] or "OTHER").upper()
    return "OTHER"


def _v701_3_strategy_mode(candidate, family):
    fs = dict(getattr(candidate, "features_snapshot", {}) or {})
    mode = str(getattr(candidate, "strategy_mode", "") or fs.get("strategy_mode") or "").upper()
    return mode or str(family or "OTHER").upper()


def _v701_3_resolve_strategy_identity(strategy_mode, family, *, fallback_style="SCALP", fallback_timeframe=""):
    """Resolve style/timeframe from the canonical contract at every execution boundary."""
    mode = str(strategy_mode or family or "OTHER").upper().strip()
    fam = str(family or "OTHER").upper().strip()
    contract = dict(_V701_3_STRATEGY_CONTRACTS.get(mode) or _V701_3_STRATEGY_CONTRACTS.get(fam) or {})
    style = str(contract.get("style") or fallback_style or "SCALP").upper().strip()
    timeframe = str(contract.get("tf") or fallback_timeframe or "").strip()
    return mode, style, timeframe, bool(contract)


def _v701_3_normalize_candidate(candidate, snapshot=None, engine_cls=None):
    if not isinstance(candidate, StrategyCandidate):
        return candidate
    try:
        family = _v701_3_strategy_family(candidate, engine_cls)
        mode = _v701_3_strategy_mode(candidate, family)
        contract = dict(_V701_3_STRATEGY_CONTRACTS.get(mode) or _V701_3_STRATEGY_CONTRACTS.get(family) or {})
        fs = dict(getattr(candidate, "features_snapshot", {}) or {})
        explicit_style = str(fs.get("strategy_style") or "").upper()
        raw_style = str(getattr(candidate, "strategy_style", "") or "").upper()
        # Strategy-contract style is authoritative whenever a canonical
        # contract exists. A stale/incorrect candidate or feature metadata
        # value must not silently turn a SWING contract into SCALP.
        contract_style = str(contract.get("style") or "").upper()
        if contract_style:
            style = contract_style
        elif explicit_style:
            style = explicit_style
        elif raw_style and raw_style != "SCALP":
            style = raw_style
        elif family in {"MTF_PULLBACK", "SWING_PULLBACK"} or mode in {"MTF_PULLBACK", "SWING_PULLBACK"}:
            style = "SWING"
        else:
            style = "SCALP"
        # The canonical mode contract is authoritative for timeframe metadata,
        # just as it is for strategy style and exit profile. Stale snapshots must
        # not label MTF/SWING candidates with an old 5m/15m scalp timeframe.
        tf = str(contract.get("tf") or fs.get("timeframe_profile") or getattr(candidate, "timeframe_profile", "") or "").strip()
        phase = fs.get("market_phase", getattr(candidate, "market_phase", "UNKNOWN"))
        phase_str = str((phase or {}).get("phase", "") if isinstance(phase, dict) else (phase or "UNKNOWN"))
        macro = str(fs.get("macro_regime") or getattr(candidate, "macro_regime", "") or (snapshot or {}).get("macro_regime") or (snapshot or {}).get("regime") or "").upper()
        local = str(fs.get("local_regime") or getattr(candidate, "local_regime", "") or (snapshot or {}).get("local_regime") or "").upper()
        sev = str(fs.get("bearish_severity") or getattr(candidate, "bearish_severity", "") or (snapshot or {}).get("bearish_severity") or (snapshot or {}).get("macro_severity") or "").upper()
        tier = str(fs.get("tier") or (snapshot or {}).get("tier") or "").upper()
        if not fs.get("strategy_mode"):
            fs["strategy_mode"] = mode
        fs["strategy_style"] = style
        fs["timeframe_profile"] = tf
        fs["market_phase"] = phase_str
        fs["macro_regime"] = macro
        fs["local_regime"] = local
        fs["bearish_severity"] = sev
        fs["family"] = family
        fs["strategy_contract"] = "V701.3"
        fs["execution_profile"] = str(contract.get("profile") or _v699_execution_profile(mode, family=family, counter_trend=(contract.get("profile") == "COUNTER_TREND_BOUNDED")))
        fs["tier"] = tier
        if "execution_quality" not in fs:
            fs["execution_quality"] = float(contract.get("q", 0.75))
        if "quality_grade" not in fs:
            try:
                sc = float(candidate.engine_score) * 100.0
                fs["quality_grade"] = "A+" if sc >= 85 else "A" if sc >= 75 else "B" if sc >= 65 else "C"
            except Exception:
                fs["quality_grade"] = str(getattr(candidate, "quality_grade", "C") or "C")
        # Source correction counters are useful diagnostics, but never gate execution.
        old_mode = str(getattr(candidate, "strategy_mode", "") or "")
        old_style = raw_style or "SCALP"
        if old_mode.upper() != mode or old_style != style:
            STATS["v701_3_metadata_repairs"] = int(STATS.get("v701_3_metadata_repairs", 0) or 0) + 1
            STATS[f"v701_3_style_repair.{old_style}->{style}"] = int(STATS.get(f"v701_3_style_repair.{old_style}->{style}", 0) or 0) + (1 if old_style != style else 0)
        return replace(candidate,
                        strategy_mode=mode, strategy_style=style, market_phase=phase_str,
                        macro_regime=macro, local_regime=local, bearish_severity=sev,
                        timeframe_profile=tf, quality_grade=str(fs.get("quality_grade") or "C"),
                        features_snapshot=fs)
    except Exception as exc:
        STATS["v701_3_normalize_errors"] = int(STATS.get("v701_3_normalize_errors", 0) or 0) + 1
        STATS["v701_3_last_normalize_error"] = f"{type(exc).__name__}:{str(exc)[:220]}"
        return candidate


def _v701_3_normalize_candidates(candidates, snapshot=None, engine_cls=None):
    out = []
    for c in list(candidates or []):
        if isinstance(c, StrategyCandidate):
            nc = _v701_3_normalize_candidate(c, snapshot=snapshot, engine_cls=engine_cls)
            out.append(nc)
            try:
                style = str(nc.strategy_style or "SCALP").upper()
                family = str(nc.family or "OTHER").upper()
                mode = str(nc.strategy_mode or family).upper()
                STATS[f"v701_3_generated_style.{style}"] = int(STATS.get(f"v701_3_generated_style.{style}", 0) or 0) + 1
                STATS[f"v701_3_generated_family.{family}"] = int(STATS.get(f"v701_3_generated_family.{family}", 0) or 0) + 1
                STATS[f"v701_3_generated_mode.{mode}"] = int(STATS.get(f"v701_3_generated_mode.{mode}", 0) or 0) + 1
            except Exception:
                _v647_record_suppressed_exception()
        else:
            out.append(c)
    return out


def _v701_3_execution_profile(strategy_mode, family=None, counter_trend=False, strategy_style=None):
    fam = str(family or _v699_family_of(strategy_mode)).upper()
    mode = str(strategy_mode or "").upper()
    style = str(strategy_style or "").upper()
    if fam == "DISCOVERY": return "DISCOVERY_SHADOW"
    if counter_trend or fam == "BEARISH_RECOVERY": return "COUNTER_TREND_BOUNDED"
    if style == "SWING" or mode in {"MTF_PULLBACK", "SWING_PULLBACK"}: return "SWING_EARLY"
    if mode.endswith("STRICT"): return "SCALP_STRICT"
    return "SCALP_BALANCED"

# Canonical execution-profile authority, with no second runtime wrapper.
globals()["_v699_execution_profile"] = _v701_3_execution_profile


def _v701_3_swing_blocker_top(n=5):
    try:
        pairs=[]
        for k,v in STATS.items():
            ks=str(k)
            if ks.startswith("v701_3_swing_blocker."):
                reason=ks.split(".",1)[1]
                iv=int(v or 0)
                if iv>0: pairs.append((reason,iv))
        return sorted(pairs,key=lambda kv:(-kv[1],kv[0]))[:max(1,int(n))]
    except Exception:
        return []


def _v701_3_strategy_style_line():
    try:
        scalp=int(STATS.get("v701_3_generated_style.SCALP",0) or 0)
        swing=int(STATS.get("v701_3_generated_style.SWING",0) or 0)
        mtf=int(STATS.get("v701_3_generated_family.MTF_PULLBACK",0) or 0)
        swp=int(STATS.get("v701_3_generated_family.SWING_PULLBACK",0) or 0)
        nomatch=int(STATS.get("v701_3_swing_no_match",0) or 0)
        fill_live_scalp=int(STATS.get("v702_entry_filled_style.LIVE.SCALP",0) or 0)
        fill_live_swing=int(STATS.get("v702_entry_filled_style.LIVE.SWING",0) or 0)
        closed_live_scalp=int(STATS.get("v702_trade_closed_style.LIVE.SCALP.count",0) or 0)
        closed_live_swing=int(STATS.get("v702_trade_closed_style.LIVE.SWING.count",0) or 0)
        closed_live_scalp_r=float(STATS.get("v702_trade_closed_style.LIVE.SCALP.sum_r",0.0) or 0.0)
        closed_live_swing_r=float(STATS.get("v702_trade_closed_style.LIVE.SWING.sum_r",0.0) or 0.0)
        top=_v701_3_swing_blocker_top(3)
        active=len([e for e in getattr(MultiStrategyEngine,"_engines",())]) if hasattr(MultiStrategyEngine,"_engines") else len(_MSE_ENGINES)
        enabled=0
        errors=0
        for e in _MSE_ENGINES:
            try:
                if bool(e.enabled()): enabled += 1
            except Exception:
                errors += 1
        _live_err_fn = globals().get("_v702_r24_live_runtime_error_count")
        if callable(_live_err_fn) and bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)) and bool(globals().get("STATS", {}).get("v702_live_epoch_armed", False)):
            runtime_error_engines = int(_live_err_fn() or 0)
            runtime_error_scope = "LIVE_EPOCH"
        else:
            runtime_error_engines=0
            runtime_error_scope = "BOOT_OR_VALIDATION"
            for e in _MSE_ENGINES:
                eid=str(getattr(e,"engine_id","")).lower()
                if any(str(k).startswith(f"mse_engine_exception.{eid}") and int(v or 0)>0 for k,v in STATS.items()):
                    runtime_error_engines += 1
        top_txt=str(top).replace(" ","")[:180]
        v703_cov_txt = "-"
        _v703_cov_fn = globals().get("_v703_coverage_snapshot")
        if callable(_v703_cov_fn):
            try:
                _v703_cov = _v703_cov_fn(top_n=5)
                v703_cov_txt = (
                    f"INV={int(_v703_cov.get('invoked_engines',0) or 0)}/"
                    f"{int(_v703_cov.get('expected_engines',0) or 0)};"
                    f"GENENG={int(_v703_cov.get('generated_engines',0) or 0)};"
                    f"ERR={int(_v703_cov.get('runtime_errors',0) or 0)}"
                )
            except Exception:
                v703_cov_txt = "unavailable"
        return f"STRAT_STYLE[scope=LIVE_EPOCH,GEN_SCALP={scalp},GEN_SWING={swing},MTF_SWING={mtf},SWING_PB={swp},SWING_NOMATCH={nomatch},LIVE_FILL_SCALP={fill_live_scalp},LIVE_FILL_SWING={fill_live_swing},LIVE_CLOSE_SCALP={closed_live_scalp},LIVE_CLOSE_SWING={closed_live_swing},LIVE_CLOSE_SCALP_R={closed_live_scalp_r:+.2f},LIVE_CLOSE_SWING_R={closed_live_swing_r:+.2f}] STRAT_HEALTH[ENG={active},ENABLED={enabled},RUNTIME_ERR_ENG={runtime_error_engines},RUNTIME_ERR_SCOPE={runtime_error_scope},CHECK_ERRORS={errors},CONTRACTS={len(_V701_3_STRATEGY_CONTRACTS)},SWING_BLOCK_TOP={top_txt or '-'},V703_COV={v703_cov_txt}]"
    except Exception:
        return "STRAT_STYLE[unavailable]"


def _v701_3_strategy_contract_self_test():
    checks={}; details={}
    try:
        engines=list(_MSE_ENGINES)
        engine_ids=[]
        engine_errors=[]
        for eng in engines:
            eid=str(getattr(eng,"engine_id","") or getattr(eng,"__name__","")).lower()
            engine_ids.append(eid)
            try:
                if not callable(getattr(eng,"generate",None)) or not callable(getattr(eng,"enabled",None)):
                    engine_errors.append(eid+":api")
                    continue
                enabled=bool(eng.enabled())
                STATS[f"v701_3_engine_enabled.{eid}"]=int(enabled)
                # Missing-data probe must fail closed without exceptions.
                # The probe is isolated so boot self-tests never contaminate live
                # strategy blocker/no-match counters.
                _probe_saved = {}
                if eid == "swing_pullback":
                    for _k,_v in list(STATS.items()):
                        if str(_k).startswith("v701_3_swing_blocker.") or str(_k) in {"v701_3_swing_no_match","v701_3_swing_last_blocker"}:
                            _probe_saved[_k] = _v
                probe=eng.generate({"symbol":"V701_3/USDT"})
                _probe_swing_evidence = _v701_3_swing_blocker_top(10) if eid == "swing_pullback" else []
                if eid == "swing_pullback":
                    for _k in list(STATS):
                        if str(_k).startswith("v701_3_swing_blocker.") or str(_k) in {"v701_3_swing_no_match","v701_3_swing_last_blocker"}:
                            if _k not in _probe_saved:
                                STATS.pop(_k, None)
                    STATS.update(_probe_saved)
                if not isinstance(probe,list):
                    engine_errors.append(eid+":non_list")
                for c in probe:
                    nc=_v701_3_normalize_candidate(c, snapshot={"symbol":"V701_3/USDT"}, engine_cls=eng)
                    if isinstance(nc,StrategyCandidate):
                        if str(nc.side).lower()!="long": engine_errors.append(eid+":short")
                        if not str(nc.strategy_mode): engine_errors.append(eid+":mode")
                        if str(nc.strategy_style).upper() not in {"SCALP","SWING"}: engine_errors.append(eid+":style")
            except Exception as exc:
                engine_errors.append(eid+":"+type(exc).__name__)
        checks["all_registered_engines_unique"] = len(engine_ids)==len(set(engine_ids)) and len(engine_ids)>=17
        checks["all_registered_engines_api_safe"] = not engine_errors
        checks["all_enabled"] = all(int(STATS.get(f"v701_3_engine_enabled.{eid}",1))==1 for eid in engine_ids)
        required_families={str(v.get("family")) for v in _V701_3_STRATEGY_CONTRACTS.values() if v.get("family")}
        produced_fams=set()
        for _eng in engines:
            _fmap = getattr(_eng, "family_map", ()) or ()
            produced_fams.update(str(_f).upper() for _f in _fmap if _f)
        # FAMILY/engine coverage is checked by the explicit contract authority below.
        checks["contract_engine_coverage"] = all(
            (rec.get("engine") in {str(getattr(e,"engine_id","")).lower() for e in engines}) or rec.get("engine") in {"recovery_router","dual_confirmation_entry_v537"}
            for rec in _V701_3_STRATEGY_CONTRACTS.values())
        checks["swing_contracts_present"] = _V701_3_STRATEGY_CONTRACTS["MTF_PULLBACK"]["style"]=="SWING" and _V701_3_STRATEGY_CONTRACTS["SWING_PULLBACK"]["style"]=="SWING"
        checks["scalp_contracts_present"] = all(v["style"]=="SCALP" for k,v in _V701_3_STRATEGY_CONTRACTS.items() if k not in {"MTF_PULLBACK","SWING_PULLBACK"})
        checks["no_discovery_exec"] = bool(CONFIG.get("V699_DISCOVERY_ORDER_FORBIDDEN",True)) and not bool(CONFIG.get("V690_DISCOVERY_VERIFIED_LIVE",False))
        checks["hard_long_only_spot"] = bool(CONFIG.get("LONG_ONLY",True)) and str(CONFIG.get("MARKET_TYPE","SPOT")).upper()=="SPOT" and not bool(CONFIG.get("ALLOW_SHORT",False)) and not bool(CONFIG.get("ENABLE_FUTURES",False))
        checks["score_floor"] = float(CONFIG.get("MIN_LIVE_SCORE",70.0)) >= 70.0
        # Funnel truth: BUILD_IN must be incremented immediately before the
        # real normal-path SignalBuilder call, not only inside recall routing.
        try:
            _src_text = Path(__file__).read_text(encoding="utf-8")
            _builder_call = _src_text.find('await SignalBuilder.build_and_route(exchange, symbol, md, preferred_candidate=_route.candidate)')
            _builder_note = _src_text.rfind('_v699_daily_note("builder_entered")', 0, max(0, _builder_call))
            checks["builder_in_telemetry_at_call"] = _builder_call > 0 and _builder_note > 0 and _builder_call - _builder_note < 800
        except Exception:
            checks["builder_in_telemetry_at_call"] = False
        # Candidate-level contract probes across all 22 modes.
        probe_fail=[]
        for mode, rec in _V701_3_STRATEGY_CONTRACTS.items():
            c=StrategyCandidate(engine_id=str(rec.get("engine","test")),symbol="TEST/USDT",side="long",generated_at_ms=1,
                                 entry_ref=100.0,sl_price=99.0,tp1_rr=1.0,tp2_rr=2.0,tp3_rr=3.0,engine_score=0.8,rr_ratio=1.0,
                                 liquidity_score=0.9,regime_fit=0.9,family=str(rec.get("family")),zone_ref=100.0,features_snapshot={},strategy_mode=mode,strategy_style="SCALP")
            n=_v701_3_normalize_candidate(c, snapshot={"regime":"BULLISH","local_regime":"LOCAL_BULLISH","tier":"LARGE"})
            if n.strategy_mode!=mode or n.strategy_style!=str(rec.get("style")) or n.timeframe_profile!=str(rec.get("tf")):
                probe_fail.append(mode)
        checks["all_strategy_contract_probes"] = not probe_fail
        checks["strategy_runtime_smoke"] = bool(_V701_3_STRATEGY_SMOKE_TEST.get("pass",False))
        details={"engines":engine_ids,"engine_errors":engine_errors,"contracts":len(_V701_3_STRATEGY_CONTRACTS),"contract_probe_failures":probe_fail,"swing_blockers":_v701_3_swing_blocker_top(10),"smoke":_V701_3_STRATEGY_SMOKE_TEST}
    except Exception as exc:
        checks["exception"]=f"{type(exc).__name__}:{exc}"; details={}
    hard_pass = bool(all(bool(v) for v in checks.values())) and "exception" not in checks
    return {"pass":hard_pass,"checks":checks,"details":details}


def _v701_3_strategy_smoke_test():
    """Deterministic, read-only smoke test: every registered engine gets a realistic snapshot.
    The test checks exception safety and candidate metadata, while restoring STATS so
    synthetic boot activity cannot contaminate LIVE telemetry.
    """
    saved_stats = dict(STATS)
    checks = {}
    details = {}
    try:
        import numpy as _np
        import pandas as _pd
        def _smoke_df(n, base):
            idx=_np.arange(int(n), dtype=float)
            close=base*(1.0+0.0009*idx+0.007*_np.sin(idx/9.0))
            open_= _np.r_[close[0], close[:-1]]
            high=_np.maximum(open_,close)*(1.0+0.0025)
            low=_np.minimum(open_,close)*(1.0-0.0025)
            vol=1_200_000.0*(1.0+0.18*_np.sin(idx/6.0))
            return _pd.DataFrame({"open":open_,"high":high,"low":low,"close":close,"volume":vol})
        snap={
            "symbol":"V701_3_SMOKE/USDT","regime":"BULLISH","local_regime":"LOCAL_BULLISH",
            "market_phase":{"phase":"TREND"},"bearish_severity":"NON_BEARISH","tier":"LARGE",
            "spread_pct":0.05,"spread":0.0005,"quote_volume":20_000_000.0,"volume_ratio":1.5,
            "current_price":130.0,"last_price":130.0,"price":130.0,"atr":1.0,"htf_strength":0.8,
            "macro_regime":"BULLISH","btc_change":0.5,"rs":0.2,
            "df_1d":_smoke_df(360,90.0),"df_4h":_smoke_df(340,100.0),"df_1h":_smoke_df(280,110.0),
            "df_15m":_smoke_df(200,120.0),"df_5m":_smoke_df(240,125.0),
        }
        engine_results=[]
        raised=[]
        metadata_fail=[]
        for eng in list(_MSE_ENGINES):
            eid=str(getattr(eng,"engine_id","") or getattr(eng,"__name__","")).lower()
            try:
                out=eng.generate(snap)
                if not isinstance(out,list):
                    raised.append(eid+":non_list")
                    continue
                cand_count=0
                for c in out:
                    if not isinstance(c,StrategyCandidate):
                        metadata_fail.append(eid+":non_candidate")
                        continue
                    cand_count += 1
                    nc=_v701_3_normalize_candidate(c,snapshot=snap,engine_cls=eng)
                    if str(nc.side).lower()!="long": metadata_fail.append(eid+":side")
                    if str(nc.strategy_mode or "").upper()!=str(getattr(nc,"strategy_mode","") or "").upper(): metadata_fail.append(eid+":mode")
                    if str(nc.strategy_style or "").upper() not in {"SCALP","SWING"}: metadata_fail.append(eid+":style")
                    if not nc.timeframe_profile: metadata_fail.append(eid+":tf")
                engine_results.append({"engine":eid,"status":"OK","candidates":cand_count})
            except Exception as exc:
                raised.append(eid+":"+type(exc).__name__+":"+str(exc)[:160])
                engine_results.append({"engine":eid,"status":"ERROR","error":type(exc).__name__})
        checks["all_engines_smoke_no_raise"] = not raised
        checks["all_smoke_candidates_contract_safe"] = not metadata_fail
        checks["all_smoke_engines_covered"] = len(engine_results) == len(_MSE_ENGINES) and len(engine_results) >= 17
        details={"engines":engine_results,"raised":raised,"metadata_failures":metadata_fail}
    except Exception as exc:
        checks["exception"] = f"{type(exc).__name__}:{exc}"
    finally:
        STATS.clear()
        STATS.update(saved_stats)
    return {"pass":bool(checks) and all(bool(v) for v in checks.values()) and "exception" not in checks,
            "checks":checks,"details":details}

_V701_3_STRATEGY_SMOKE_TEST = _v701_3_strategy_smoke_test()
