V702_FINAL_PROTECTION_CLOSURE = "V702-SOFTWARE-SL-FAST-BID-AWARE-PROTECTION"

# V702 FINAL PROTECTION CONFIG IS DEFINED BEFORE THE TERMINAL SELF-TEST RUNS.
# This avoids a boot-order mismatch where the validator executes against legacy
