        checks["runtime_counter_rank_single_writer"] = "STATS[\"v681_runtime_cycle_ranked\"] = int(max(0, len(_arb_pool)))" not in _pre_v702_src
        checks["runtime_raw_pool_cycle_reset_wired"] = _src_self.count('"v681_runtime_cycle_raw_ranked", "v681_runtime_cycle_pool_ranked"') >= 2
        checks["handoff_snapshot_cache_bounded"] = int(_V702_HANDOFF_SNAPSHOT_CACHE_MAX) >= 32 and isinstance(_V702_HANDOFF_SNAPSHOT_CACHE, dict)
        # Cache safety regression: same snapshot/candle ids across cycles must not reuse a prior-cycle handoff.
