            _v695_body = _src_discovery[_i_v695:_i_v695_end] if _i_v695 >= 0 and _i_v695_end > _i_v695 else ""
            checks["discovery_single_terminal_precheck"] = bool(_v531_body.count("_v542_exact_policy_precheck(") == 1)
            checks["discovery_wrapper_no_precheck_replay"] = bool("_v542_exact_policy_precheck(" not in _v695_body)
