def _v702_native_family_heartbeat_summary():
    try:
        keys = sorted(
            (str(k), int(v or 0))
            for k, v in STATS.items()
            if str(k).startswith("v702_native_fake_break_recovered.") or str(k).startswith("v702_native_microstructure_recovered.")
        )
        if not keys:
            return "-"
        # Compact family:value representation; max 8 items keeps heartbeat bounded.
        agg = {}
        for k, v in keys:
            fam = k.rsplit('.', 1)[-1]
            agg[fam] = int(agg.get(fam, 0) or 0) + int(v or 0)
        return ",".join(f"{f}:{n}" for f, n in sorted(agg.items(), key=lambda kv:(-kv[1],kv[0]))[:8])
    except Exception:
        return "-"

# V702 R4 heartbeat: expose loss-streak throttle state without changing funnel
