def _v702_protection_lease_segment() -> str:
    """Compact per-trade software-protection lease truth for heartbeat."""
    try:
        leases = []
        for sym, trade in list(ACTIVE_TRADES.items()):
            if not bool(getattr(trade, "software_sl_active", False)):
                continue
            age = SoftwareSLTelemetry.protection_lease_age_sec(trade)
            state = str(getattr(trade, "protection_lease_state", "UNINITIALIZED") or "UNINITIALIZED").upper()
            leases.append((str(sym), age, state))
        if not leases:
            return " SWLEASE[count=0,health=NA,stale=0]"
        stale_limit = max(2.0, float(CONFIG.get("V702_PROTECTION_LEASE_STALE_SEC", 12.0)))
        stale = [(s,a,st) for s,a,st in leases if a > stale_limit or st != "HEALTHY"]
        top = sorted(leases, key=lambda x:(-x[1], x[0]))[:4]
        txt = ";".join(f"{s}:{('NA' if not math.isfinite(a) else f'{a:.1f}s')}:{st}" for s,a,st in top)
        return f" SWLEASE[count={len(leases)},health={'DEGRADED' if stale else 'HEALTHY'},stale={len(stale)},top={txt[:220]}]"
    except Exception as exc:
        _v593_note_suppressed_exception("v702.heartbeat.protection_lease", exc)
        return " SWLEASE[count=?,health=UNKNOWN,stale=?]"
