# =============================================================================
# V702 FINAL AUDIT CLOSURE — PENDING DISCOVERY SNAPSHOT REHYDRATION + SELECTED
# ROUTE TRUTH
# -----------------------------------------------------------------------------
# Production finding:
#   Discovery PASS candidates keep an exact snapshot_hint in the pending
#   handoff registry, but the selected route previously ignored that hint and
#   depended only on the global V702 handoff cache. If that cache entry was
#   evicted/replaced while the candidate was still fresh, the candidate could
#   fail-closed as a handoff mismatch even though the exact preflight-approved
#   snapshot was still retained with the pending candidate.
#
# Final closure:
#   Rehydrate ONLY the exact stored snapshot_hint immediately before selected
#   handoff, and ONLY when cycle/snapshot/candle provenance and freshness all
#   match the candidate/current snapshot. No new market read, no gate change,
#   no score change, no relaxed execution path.
#
# Telemetry finding:
#   starvation exact_builder was allowed to display the generic/stale builder
#   blocker ledger even when the current cycle had already selected a candidate
#   and reached a different selected-stage outcome.
#
# Final closure:
#   selected_route_last is cycle-owned and preferred for operator truth when
#   selected > 0. This is observability-only and never authorizes execution.
# =============================================================================
CONFIG.update({
    # V702 FINAL HARD-SPREAD ALIGNMENT: the shipped safety contract states that
    # liquidity/spread gates are not weakened. Keep historical V528/V540 helpers
    # callable for compatibility, but disable their relief lanes in the final
    # runtime so tier ceilings remain hard authorities.
    "V528_SPREAD_QUALITY_RELAX_ENABLE": False,
    "V540_ELITE_SPREAD_RELIEF_ENABLE": False,
    "V702_FINAL_AUDIT_CLOSURE_ENABLE": True,
    "V702_PENDING_SNAPSHOT_REHYDRATION_ENABLE": True,
    "V702_PENDING_REHYDRATION_REQUIRE_EXACT_IDS": True,
    "V702_CANONICAL_EXIT_SNAPSHOT_ENABLE": True,
    "V702_PROTECTION_LEASE_STALE_SEC": 12.0,
    "V702_PROTECTION_LEASE_BLOCK_NEW_ENTRIES": True,
    "V702_SAME_CYCLE_COALESCING_ENABLE": True,
    # More bounded prequalified backups; this does NOT raise the live order
    # slot count or relax any execution gate.
    "V546_PENDING_HANDOFF_MAX_PER_CYCLE": max(
        1, min(4, int(CONFIG.get("V546_PENDING_HANDOFF_MAX_PER_CYCLE", 3) or 3))
    ),
    "V546_PENDING_HANDOFF_MAX": max(
        1, min(8, int(CONFIG.get("V546_PENDING_HANDOFF_MAX", 6) or 6))
    ),
})
STATS["v702_final_audit_closure"] = V702_FINAL_AUDIT_CLOSURE


def _v702_rehydrate_pending_snapshot(symbol: str, candidate: Any, fallback: Optional[Dict[str, Any]] = None) -> Tuple[bool, str]:
    """Restore a pending Discovery candidate's exact approved snapshot, fail-closed.

    The snapshot is accepted only when the immutable candidate provenance and
    current prepared snapshot agree on cycle/snapshot/candle identity and the
    candidate is still inside the existing pending TTL. No network call occurs.
    """
    if not bool(CONFIG.get("V702_PENDING_SNAPSHOT_REHYDRATION_ENABLE", True)):
        return False, "disabled"
    try:
        sym = str(symbol or "")
        fb = _v702_exactize_runtime_snapshot(sym, fallback)
        with _V546_PENDING_LOCK:
            rec = dict(_V546_PENDING_HANDOFF.get(sym) or {})
        if not rec:
            return False, "not_pending"
        hint = dict(rec.get("snapshot_hint") or {}) if isinstance(rec.get("snapshot_hint"), dict) else {}
        if not hint:
            STATS["v702_pending_rehydration_missing_hint"] = int(STATS.get("v702_pending_rehydration_missing_hint", 0) or 0) + 1
            return False, "missing_snapshot_hint"

        # Pending freshness remains the existing hard 390s-style TTL contract.
        age = _wall_age_sec(getattr(candidate, "generated_at_ms", None)) if candidate is not None else None
        ttl = float(CONFIG.get("V546_PENDING_HANDOFF_TTL_SEC", 390.0))
        if age is None or age > ttl:
            STATS["v702_pending_rehydration_stale"] = int(STATS.get("v702_pending_rehydration_stale", 0) or 0) + 1
            return False, "candidate_stale"

        expected = _v702_candidate_handoff_expectation(candidate, fb)
        current_cycle = int(_v702_current_cycle_id(fb))
        hint_cycle = int(_v702_current_cycle_id(hint))
        hint_id = str(hint.get("snapshot_id") or "")
        hint_candle = str(hint.get("closed_candle_ts") or hint.get("candle_ts") or "")

        # Exact identity is mandatory for provenance-bearing pending rows.
        if bool(CONFIG.get("V702_PENDING_REHYDRATION_REQUIRE_EXACT_IDS", True)):
            if not expected.get("has_origin"):
                STATS["v702_pending_rehydration_reject_no_origin"] = int(STATS.get("v702_pending_rehydration_reject_no_origin", 0) or 0) + 1
                return False, "candidate_origin_missing"
            if expected.get("cycle_id", 0) <= 0 or current_cycle <= 0 or hint_cycle <= 0:
                STATS["v702_pending_rehydration_reject_cycle_unknown"] = int(STATS.get("v702_pending_rehydration_reject_cycle_unknown", 0) or 0) + 1
                return False, "cycle_unverifiable"
            if hint_cycle != current_cycle or expected.get("cycle_id") != hint_cycle:
                STATS["v702_pending_rehydration_cycle_mismatch"] = int(STATS.get("v702_pending_rehydration_cycle_mismatch", 0) or 0) + 1
                return False, "cycle_mismatch"
            if not hint_id or not expected.get("snapshot_id") or hint_id != str(expected.get("snapshot_id")):
                STATS["v702_pending_rehydration_snapshot_mismatch"] = int(STATS.get("v702_pending_rehydration_snapshot_mismatch", 0) or 0) + 1
                return False, "snapshot_mismatch"
            if not hint_candle or not expected.get("candle_ts") or hint_candle != str(expected.get("candle_ts")):
                STATS["v702_pending_rehydration_candle_mismatch"] = int(STATS.get("v702_pending_rehydration_candle_mismatch", 0) or 0) + 1
                return False, "candle_mismatch"

            fb_id = str(fb.get("snapshot_id") or "")
            fb_candle = str(fb.get("closed_candle_ts") or fb.get("candle_ts") or "")
            # The CURRENT prepared snapshot must carry both exact identity fields.
            # Without them, the pending hint cannot be proven to refer to the same
            # prepared snapshot/candle. Exact mode therefore fails closed.
            if not fb_id or not fb_candle:
                STATS["v702_pending_rehydration_current_identity_missing"] = int(
                    STATS.get("v702_pending_rehydration_current_identity_missing", 0) or 0
                ) + 1
                return False, "current_snapshot_identity_missing"
            # The CURRENT prepared snapshot must also be the same snapshot. This
            # prevents using an older pending hint after the market advanced.
            if fb_id != hint_id:
                STATS["v702_pending_rehydration_current_snapshot_drift"] = int(STATS.get("v702_pending_rehydration_current_snapshot_drift", 0) or 0) + 1
                return False, "current_snapshot_drift"
            if fb_candle != hint_candle:
                STATS["v702_pending_rehydration_current_candle_drift"] = int(STATS.get("v702_pending_rehydration_current_candle_drift", 0) or 0) + 1
                return False, "current_candle_drift"

        _v702_cache_handoff_snapshot(sym, hint)
        STATS["v702_pending_snapshot_rehydrated"] = int(STATS.get("v702_pending_snapshot_rehydrated", 0) or 0) + 1
        STATS["v702_pending_snapshot_rehydrated_last"] = {
            "symbol": sym, "cycle_id": hint_cycle, "snapshot_id": hint_id,
            "candle_ts": hint_candle, "age_sec": age, "ts": WALL_NOW(),
        }
        return True, "rehydrated_exact_snapshot"
    except Exception as exc:
        _v647_record_suppressed_exception()
        STATS["v702_pending_rehydration_errors"] = int(STATS.get("v702_pending_rehydration_errors", 0) or 0) + 1
        return False, f"exception:{type(exc).__name__}"


def _v702_a19_candidate_ref(candidate: Any) -> str:
    """Stable KnowledgeOutcomeLedger identity for exact shadow/live candidate joins.

    This intentionally mirrors KnowledgeOutcomeLedger.register_alert's payload,
    so the reference is the same across route and shadow messages when (and only
    when) the semantic candidate is the same. Invalid candidate geometry yields
    no reference rather than a fuzzy symbol-only match.
    """
    try:
        if candidate is None or str(getattr(candidate, "side", "") or "").lower() != "long":
            return ""
        symbol = str(getattr(candidate, "symbol", "") or "").strip()
        family = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "UNKNOWN").upper()
        generated = str(getattr(candidate, "generated_at_ms", 0) or 0)
        entry = float(KnowledgeOutcomeLedger._num(getattr(candidate, "entry_ref", 0.0)))
        sl = float(KnowledgeOutcomeLedger._num(getattr(candidate, "sl_price", 0.0)))
        t1 = float(KnowledgeOutcomeLedger._num(getattr(candidate, "tp1_rr", 0.0)))
        t2 = float(KnowledgeOutcomeLedger._num(getattr(candidate, "tp2_rr", 0.0)))
        t3 = float(KnowledgeOutcomeLedger._num(getattr(candidate, "tp3_rr", 0.0)))
        raw = max(0.0, float(KnowledgeOutcomeLedger._num(getattr(candidate, "engine_score", 0.0))) * 100.0)
        if not symbol or entry <= 0.0 or sl <= 0.0 or entry <= sl or min(t1, t2, t3) <= 0.0:
            return ""
        payload = "|".join([symbol, family, generated, f"{entry:.16g}", f"{sl:.16g}",
                             f"{t1:.8f}", f"{t2:.8f}", f"{t3:.8f}", f"{raw:.6f}"])
        return hashlib.sha256(payload.encode()).hexdigest()[:40]
    except Exception:
        return ""


def _v702_a19_record_micro_handoff_diagnostic(candidate: Any, snapshot: Any, tier: Any,
                                                ok: bool, reason: str, detail: Any) -> None:
    """Bounded, reason-specific MICRO handoff telemetry; admission decision is unchanged."""
    try:
        reason_key = re.sub(r"[^a-zA-Z0-9_.:-]", "_", str(reason or "unknown"))[:90] or "unknown"
        counts = STATS.setdefault("v702_a19_micro_handoff_reason_counts", {})
        if not isinstance(counts, dict):
            counts = {}
            STATS["v702_a19_micro_handoff_reason_counts"] = counts
        counts[reason_key] = int(counts.get(reason_key, 0) or 0) + 1
        if len(counts) > 32:
            counts = dict(sorted(counts.items(), key=lambda item: int(item[1] or 0), reverse=True)[:24])
            STATS["v702_a19_micro_handoff_reason_counts"] = counts
        snap = snapshot if isinstance(snapshot, dict) else {}
        fs = getattr(candidate, "features_snapshot", {}) if candidate is not None else {}
        fs = fs if isinstance(fs, dict) else {}
        src = detail if isinstance(detail, dict) else {}
        safe = {}
        for key in ("quote_volume_24h", "score_100", "score_floor", "strategy_score_floor",
                    "book_age_sec", "spread_age_sec", "spread_pct", "depth_ratio", "volume_ratio",
                    "orderbook_reason", "fee_reason", "verified", "book_pass", "spread_pass", "fee_pass"):
            val = src.get(key)
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                try:
                    fval = float(val)
                    if math.isfinite(fval): safe[key] = round(fval, 6)
                except Exception:
                    pass
            elif isinstance(val, (str, bool)):
                safe[key] = str(val)[:100] if isinstance(val, str) else bool(val)
        ref_fn = globals().get("_v702_a19_candidate_ref")
        STATS["v702_a19_micro_handoff_last"] = {
            "symbol": str(getattr(candidate, "symbol", "") or snap.get("symbol", "") or "?").upper()[:48],
            "family": str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "UNKNOWN").upper()[:48],
            "strategy_mode": str(getattr(candidate, "strategy_mode", "") or "UNKNOWN").upper()[:48],
            "tier": str(tier or snap.get("tier", "UNKNOWN")).upper()[:16],
            "candidate_ref": ref_fn(candidate) if callable(ref_fn) else "",
            "generated_at_ms": int(getattr(candidate, "generated_at_ms", 0) or 0),
            "snapshot_id": str(snap.get("snapshot_id") or fs.get("snapshot_id") or "")[:80],
            "ok": bool(ok), "reason": reason_key, "detail": safe, "ts": float(WALL_NOW()),
        }
    except Exception:
        try:
            STATS["v702_a19_micro_handoff_diagnostic_errors"] = int(STATS.get("v702_a19_micro_handoff_diagnostic_errors", 0) or 0) + 1
        except Exception:
            pass


def _v702_selected_route_note(symbol: str, stage: str, reason: str = "", *, selected: bool = True,
                              source: str = "ROUTE", candidate: Any = None) -> None:
    """Cycle-owned selected-route outcome with stable candidate identity for diagnostics."""
    try:
        if not selected:
            return
        candidate_ref = _v702_a19_candidate_ref(candidate) if candidate is not None else ""
        rec = {
            "symbol": str(symbol or ""),
            "family": str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()[:64] if candidate is not None else "",
            "strategy_mode": str(getattr(candidate, "strategy_mode", "") or "").upper()[:64] if candidate is not None else "",
            "generated_at_ms": int(getattr(candidate, "generated_at_ms", 0) or 0) if candidate is not None else 0,
            "candidate_ref": candidate_ref,
            "stage": str(stage or "unknown")[:120],
            "reason": str(reason or "")[:240],
            "cycle_id": int(STATS.get("v681_runtime_cycle_id", 0) or 0),
            "ts": WALL_NOW(),
            "source": str(source or "ROUTE")[:80],
        }
        STATS["v702_selected_route_last"] = rec
        STATS["v702_selected_route_last_stage"] = rec["stage"]
        STATS["v702_selected_route_last_reason"] = rec["reason"]
        hist = STATS.setdefault("v702_selected_route_history", [])
        if isinstance(hist, list):
            hist.append(dict(rec))
            if len(hist) > 32:
                del hist[:-32]
        # The operator-facing selected-route record is also the authoritative
        # attribution point for pre-execution outcomes. Structural fake-break,
        # stale handoff, policy parity, canonical recheck and orderbook blocks
        # become explicit PREEXEC_BLOCK events; the exact builder entry marks
        # PREEXEC_PASS. Never relax or skip the decision itself.
        try:
            _stage_key = str(stage or "").strip().lower()
            _route_attempt_id = f"{rec['cycle_id']}:{candidate_ref or 'no-candidate'}:{_stage_key}:{int(float(rec['ts']) * 1000)}"
            _route_details = {"route_stage": _stage_key, "selected": bool(selected),
                              "candidate_ref": candidate_ref, "route_attempt_id": _route_attempt_id}
            if _stage_key in {"selected_preexec_freshness", "selected_preexec_policy", "selected_preexec_canonical",
                              "selected_route_orderbook", "selected_route_projection", "selected_route_orderbook_error"}:
                _v702_pipeline_route_outcome(symbol, "PREEXEC_BLOCK", reason, source,
                                             details=_route_details, candidate=candidate)
            elif _stage_key == "builder_entered":
                _v702_pipeline_route_outcome(symbol, "PREEXEC_PASS", "canonical_preexec_gates_passed", source,
                                             details=_route_details, candidate=candidate)
            elif _stage_key == "builder_exception":
                _v702_pipeline_route_outcome(symbol, "BUILDER_EXCEPTION", reason, source,
                                             details=_route_details, candidate=candidate)
        except Exception:
            _v647_record_suppressed_exception()
    except Exception:
        _v647_record_suppressed_exception()


def _v702_selected_route_display(diag: Optional[Dict[str, Any]] = None) -> str:
    """Return current-cycle selected truth, never stale lifetime builder history."""
    try:
        d = diag if isinstance(diag, dict) else {}
        selected = int(d.get("selected_delta", 0) or 0)
        rec = dict(STATS.get("v702_selected_route_last") or {})
        cid = int(STATS.get("v681_runtime_cycle_id", 0) or 0)
        if selected > 0 and rec and int(rec.get("cycle_id", 0) or 0) == cid:
            stage = str(rec.get("stage") or "unknown")
            reason = str(rec.get("reason") or "")
            return f"{stage}:{reason}" if reason else stage
        # Never fall back to the lifetime V569 stage/reason here. That value can
        # be overwritten by compatibility telemetry after the selected route has
        # already completed, which would make a prior-cycle blocker look current.
        # Current-cycle V702 route state above is the sole selected-stage authority.
        if selected > 0 and str((diag or {}).get("cycle_source") or STATS.get("v684_public_cycle_source") or "") == "LAST_COMPLETED":
            return "selected_stage:LAST_COMPLETED_NOT_CURRENT"
        if selected > 0:
            return "selected_stage:unattributed"
    except Exception:
        _v647_record_suppressed_exception()
    return ""


# Final current-cycle reset hook: do not carry a prior selected-route outcome
# into a new scan cycle. The wrapper owns only V702-selected truth; legacy V569
# compatibility telemetry remains untouched for audit/backward compatibility.
def _v702_reset_selected_route_for_cycle(cycle_id: int) -> None:
    try:
        cid = int(cycle_id or 0)
        if cid <= 0:
            return
        rec = STATS.get("v702_selected_route_last")
        if isinstance(rec, dict) and int(rec.get("cycle_id", 0) or 0) != cid:
            STATS.pop("v702_selected_route_last", None)
            STATS.pop("v702_selected_route_last_stage", None)
            STATS.pop("v702_selected_route_last_reason", None)
            STATS["v702_selected_route_reset_count"] = int(
                STATS.get("v702_selected_route_reset_count", 0) or 0
            ) + 1
        STATS["v702_selected_route_cycle_id"] = cid
    except Exception:
        _v647_record_suppressed_exception()

try:
    _v702_prev_runtime_cycle_begin = globals().get("_v681_runtime_cycle_begin")
    if (
        callable(_v702_prev_runtime_cycle_begin)
        and not getattr(_v702_prev_runtime_cycle_begin, "_v702_cycle_reset_wrapped", False)
    ):
        def _v702_runtime_cycle_begin():
            cid = int(_v702_prev_runtime_cycle_begin() or 0)
            _v702_reset_selected_route_for_cycle(cid)
            try:
                GlobalOpportunityArbiter._last_execution_reserve = []
                GlobalOpportunityArbiter._last_execution_reserve_cycle_id = 0
                globals()["_V668_LAST_ARB_POOL"] = []
                globals().get("V521_ALTERNATE_ROUTES", {}).clear()
            except Exception:
                pass
            return cid
        _v702_runtime_cycle_begin._v702_cycle_reset_wrapped = True
        globals()["_v681_runtime_cycle_begin"] = _v702_runtime_cycle_begin
        STATS["v702_selected_route_reset_wrapped"] = True
    else:
        STATS["v702_selected_route_reset_wrapped"] = False
except Exception as _v702_reset_exc:
    STATS["v702_selected_route_reset_wrapped"] = False
    STATS["v702_selected_route_reset_error"] = f"{type(_v702_reset_exc).__name__}:{_v702_reset_exc}"


# Terminal self-test for the final audit closures. Offline only; no exchange IO.
