            crs=_C(); crs.symbol="V702-PB-ELITE-RS/USDT"; crs.family="PULLBACK"; crs.strategy_mode="PULLBACK"; crs.strategy_style="SCALP"
            crs.zone_ref=100.0; crs.entry_ref=100.35; crs.sl_price=99.6; crs.tp1_rr=1.0; crs.tp2_rr=2.0; crs.tp3_rr=5.0; crs.engine_score=0.985
            crs.features_snapshot={**c.features_snapshot, "volume_ratio":1.20, "rs_5m":-0.0010, "v587_setup_quality":80.0}
            qrsbase=_V702_CANONICAL_PB_HARD_QUALITY(crs, snap)
