        leader = dict(data.get("RELATIVE_STRENGTH_LEADER", {}) or {})
        if leader and "RELATIVE_STRENGTH" not in data:
            data["RELATIVE_STRENGTH"] = dict(leader)
            data["RELATIVE_STRENGTH"]["canonical_family"] = "RELATIVE_STRENGTH"
            data["RELATIVE_STRENGTH"]["source_mode_alias"] = "RELATIVE_STRENGTH_LEADER"
            raw = json.dumps(data, sort_keys=True, default=str, separators=(",", ":"))
            CanonicalStrategyPolicyRegistry._data = data
            CanonicalStrategyPolicyRegistry._revision = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]
