def _v702_terminal_exact_policy_telemetry(window_sec=720.0, top_n=5):
    """Return exact current-live prequal policy blockers from the canonical event ledger."""
    try:
        if not bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
            return []
        now = WALL_NOW()
        rows = []
        events = globals().get("_V456_EVENTS")
        if events is not None:
            try:
                events = list(events)
            except Exception:
                events = []
        for ev in reversed(events or []):
            if not isinstance(ev, dict):
                continue
            ts = ev.get("ts", ev.get("timestamp", ev.get("time", 0.0)))
            try:
                age = max(0.0, float(now) - float(ts)) if ts else 0.0
                if age > float(window_sec):
                    break
            except Exception:
                pass
            stage = str(ev.get("stage") or ev.get("event") or "").lower()
            reason = str(ev.get("reason") or "").strip()
            if "prequal" not in stage and not reason:
                continue
            rl = reason.lower()
            policyish = (
                rl.startswith("policy") or rl.startswith("family_regime_disallowed") or
                "family_policy" in rl or "strategy_incompatible" in rl or
                rl.startswith("macro") or rl.startswith("local") or rl.startswith("phase") or
                rl.startswith("style") or "severity" in rl
            )
            if not policyish:
                continue
            fam = str(ev.get("family") or ev.get("strategy_family") or "-").upper()
            mode = str(ev.get("strategy_mode") or ev.get("mode") or fam).upper()
            key = f"{fam}/{mode}:{reason[:100]}"
            rows.append(key)
        counts = {}
        for key in rows:
            counts[key] = int(counts.get(key, 0) or 0) + 1
        return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:int(top_n)]
    except Exception:
        return []


def _v702_terminal_htf_truth(window_sec=720.0):
    """Split legacy HTF aggregate telemetry into hard-HTF vs family-policy causes."""
    try:
        if not bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
            return {"policy": 0, "hard": 0}
        now = WALL_NOW(); policy = 0; hard = 0
        events = globals().get("_V456_EVENTS")
        for ev in list(events or []):
            if not isinstance(ev, dict):
                continue
            try:
                age = max(0.0, float(now) - float(ev.get("ts", 0.0) or 0.0))
                if age > float(window_sec):
                    continue
            except Exception:
                continue
            stage = str(ev.get("stage") or ev.get("event") or "").lower()
            reason = str(ev.get("reason") or "").lower()
            if "prequal" not in stage and not reason.startswith("htf"):
                continue
            if reason.startswith("htf.family_regime_disallowed") or "family_regime_disallowed" in reason or "family_policy" in reason:
                policy += 1
            elif reason.startswith("htf") or "htf_" in reason:
                hard += 1
        return {"policy": policy, "hard": hard}
    except Exception:
        return {"policy": 0, "hard": 0}

