def _v702_live_quality_score_floor_fail_closed() -> float:
    """Return the most conservative configured family score floor on bad input."""
    candidates = [80.0, 70.0]
    configured = (
        ("V702_ELITE_LIVE_SCORE_FLOOR_DEFAULT", 76.0),
        ("V702_ELITE_PB_MIN_SCORE", 76.0),
        ("V702_ELITE_MTF_PB_MIN_SCORE", 78.0),
        ("V702_ELITE_LSR_MIN_SCORE", 76.0),
        ("V702_ELITE_BREAKOUT_MIN_SCORE", 78.0),
        ("V702_ELITE_LSB_MIN_SCORE", 80.0),
        ("V702_ELITE_MOMENTUM_MIN_SCORE", 78.0),
        ("MIN_LIVE_SCORE", 70.0),
    )
    for key, default in configured:
        try:
            value = float(CONFIG.get(key, default))
            if math.isfinite(value) and 0.0 <= value <= 100.0:
                candidates.append(value)
        except Exception:
            continue
    return max(candidates)


def _v702_live_quality_score_floor(opp: Any) -> float:
    try:
        fam = str((opp or {}).get("family", "") or (opp or {}).get("strategy_mode", "") or "").upper()
        defaults = float(CONFIG.get("V702_ELITE_LIVE_SCORE_FLOOR_DEFAULT", 76.0))
        prof = {
            "PULLBACK": float(CONFIG.get("V702_ELITE_PB_MIN_SCORE", defaults)),
            "MTF_PULLBACK": float(CONFIG.get("V702_ELITE_MTF_PB_MIN_SCORE", 78.0)),
            "LIQUIDITY_SWEEP_REVERSAL": float(CONFIG.get("V702_ELITE_LSR_MIN_SCORE", 76.0)),
            "BREAKOUT_RETEST": float(CONFIG.get("V702_ELITE_BREAKOUT_MIN_SCORE", 78.0)),
            "BREAKOUT_CONTINUATION": float(CONFIG.get("V702_ELITE_BREAKOUT_MIN_SCORE", 78.0)),
            "MEASURED_MOVE": float(CONFIG.get("V702_ELITE_BREAKOUT_MIN_SCORE", 78.0)),
            "LOCAL_STRENGTH_BREAKOUT": float(CONFIG.get("V702_ELITE_LSB_MIN_SCORE", 80.0)),
            "MOMENTUM_EXPANSION": float(CONFIG.get("V702_ELITE_MOMENTUM_MIN_SCORE", 78.0)),
            "MEAN_REVERSION": defaults,
        }
        return max(defaults, float(prof.get(fam, defaults)))
    except Exception:
        # A malformed family/profile cannot fall back to the weaker global 70
        # floor. Fail closed at the highest configured elite family floor.
        try:
            return _v702_live_quality_score_floor_fail_closed()
        except Exception:
            return 80.0


def _v702_rs_points_from_raw(rs: Any) -> Optional[float]:
    try:
        x = float(rs)
        if not math.isfinite(x): return None
        # Candidate rs_5m is stored as a decimal return differential.
        return 8.0 if x > 0.02 else 6.0 if x > 0.01 else 4.0 if x > 0.0 else 2.0 if x > -0.01 else 0.0
    except Exception:
        return None


def _v702_elite_profile(opp: Any) -> Dict[str, float]:
    fam = str((opp or {}).get("family", "") or (opp or {}).get("strategy_mode", "") or "").upper()
    D = {
        "score": float(CONFIG.get("V702_ELITE_LIVE_SCORE_FLOOR_DEFAULT", 76.0)),
        "htf": float(CONFIG.get("V702_ELITE_DEFAULT_MIN_HTF", 75.0)),
        "volume": float(CONFIG.get("V702_ELITE_DEFAULT_MIN_VOLUME", 1.0)),
        "rs_points": float(CONFIG.get("V702_ELITE_DEFAULT_MIN_RS_POINTS", 4.0)),
        "structure": float(CONFIG.get("V702_ELITE_DEFAULT_MIN_STRUCTURE", 70.0)),
        "retest": float(CONFIG.get("V702_ELITE_DEFAULT_MIN_RETEST", 55.0)),
        "chase": float(CONFIG.get("V702_ELITE_DEFAULT_MAX_CHASE", 0.60)),
        "setup": 0.0,
    }
    if fam == "PULLBACK":
        D.update(score=_v702_live_quality_score_floor(opp), htf=float(CONFIG.get("V702_ELITE_PB_MIN_HTF",80.0)), volume=float(CONFIG.get("V702_ELITE_PB_MIN_VOLUME",0.95)), rs_points=float(CONFIG.get("V702_ELITE_PB_MIN_RS_POINTS",4.0)), structure=float(CONFIG.get("V702_ELITE_PB_MIN_STRUCTURE",70.0)), retest=float(CONFIG.get("V702_ELITE_PB_MIN_RETEST",55.0)), chase=float(CONFIG.get("V702_ELITE_PB_MAX_CHASE",0.60)), setup=float(CONFIG.get("V702_ELITE_PB_MIN_SETUP_QUALITY",82.0)))
    elif fam == "MTF_PULLBACK":
        D.update(score=_v702_live_quality_score_floor(opp), htf=float(CONFIG.get("V702_ELITE_MTF_PB_MIN_HTF",85.0)), volume=float(CONFIG.get("V702_ELITE_MTF_PB_MIN_VOLUME",1.0)), rs_points=float(CONFIG.get("V702_ELITE_MTF_PB_MIN_RS_POINTS",4.0)), structure=float(CONFIG.get("V702_ELITE_MTF_PB_MIN_STRUCTURE",75.0)), retest=float(CONFIG.get("V702_ELITE_MTF_PB_MIN_RETEST",60.0)), chase=float(CONFIG.get("V702_ELITE_MTF_PB_MAX_CHASE",0.55)), setup=float(CONFIG.get("V702_ELITE_MTF_PB_MIN_SETUP_QUALITY",85.0)))
    elif fam == "LIQUIDITY_SWEEP_REVERSAL":
        D.update(score=float(CONFIG.get("V702_ELITE_LSR_MIN_SCORE",76.0)), htf=float(CONFIG.get("V702_ELITE_LSR_MIN_HTF",78.0)), volume=float(CONFIG.get("V702_ELITE_LSR_MIN_VOLUME",1.15)), rs_points=float(CONFIG.get("V702_ELITE_LSR_MIN_RS_POINTS",4.0)), structure=float(CONFIG.get("V702_ELITE_LSR_MIN_STRUCTURE",72.0)), retest=float(CONFIG.get("V702_ELITE_LSR_MIN_RETEST",55.0)), chase=float(CONFIG.get("V702_ELITE_LSR_MAX_CHASE",0.50)))
    elif fam in {"BREAKOUT_RETEST","BREAKOUT_CONTINUATION","MEASURED_MOVE"}:
        D.update(score=float(CONFIG.get("V702_ELITE_BREAKOUT_MIN_SCORE",78.0)), htf=float(CONFIG.get("V702_ELITE_BREAKOUT_MIN_HTF",80.0)), volume=float(CONFIG.get("V702_ELITE_BREAKOUT_MIN_VOLUME",1.15)), rs_points=float(CONFIG.get("V702_ELITE_BREAKOUT_MIN_RS_POINTS",4.0)), structure=float(CONFIG.get("V702_ELITE_BREAKOUT_MIN_STRUCTURE",75.0)), retest=float(CONFIG.get("V702_ELITE_BREAKOUT_MIN_RETEST",60.0)), chase=float(CONFIG.get("V702_ELITE_BREAKOUT_MAX_CHASE",0.45)))
    elif fam == "LOCAL_STRENGTH_BREAKOUT":
        D.update(score=float(CONFIG.get("V702_ELITE_LSB_MIN_SCORE",80.0)), htf=float(CONFIG.get("V702_ELITE_LSB_MIN_HTF",85.0)), volume=float(CONFIG.get("V702_ELITE_LSB_MIN_VOLUME",1.20)), rs_points=float(CONFIG.get("V702_ELITE_LSB_MIN_RS_POINTS",6.0)), structure=float(CONFIG.get("V702_ELITE_LSB_MIN_STRUCTURE",80.0)), retest=float(CONFIG.get("V702_ELITE_LSB_MIN_RETEST",55.0)), chase=float(CONFIG.get("V702_ELITE_LSB_MAX_CHASE",0.40)))
    elif fam == "MOMENTUM_EXPANSION":
        D.update(score=float(CONFIG.get("V702_ELITE_MOMENTUM_MIN_SCORE",78.0)), htf=float(CONFIG.get("V702_ELITE_MOMENTUM_MIN_HTF",80.0)), volume=float(CONFIG.get("V702_ELITE_MOMENTUM_MIN_VOLUME",1.20)), rs_points=float(CONFIG.get("V702_ELITE_MOMENTUM_MIN_RS_POINTS",4.0)), structure=float(CONFIG.get("V702_ELITE_MOMENTUM_MIN_STRUCTURE",72.0)), retest=float(CONFIG.get("V702_ELITE_MOMENTUM_MIN_RETEST",50.0)), chase=float(CONFIG.get("V702_ELITE_MOMENTUM_MAX_CHASE",0.55)))
    return D


def _v702_elite_live_context_gate(*, opp: Any, score: float, htf_strength: float,
                                  volume_ratio: Optional[float], rs_score_val: Optional[float],
                                  structure_confidence: Optional[float], retest_quality_score: Optional[float],
                                  chase_atr: float, tier: str, regime: str = "",
                                  severity: str = "") -> Tuple[bool, str, Dict[str, Any]]:
    P = _v702_elite_profile(opp)
    _opp = opp or {}
    fs = dict(_opp.get("features_snapshot") or {}) if isinstance(_opp.get("features_snapshot"), dict) else dict(_opp)
    raw_rs = fs.get("rs_5m", fs.get("relative_strength", _opp.get("rs_5m")))
    rs_points = float(rs_score_val) if rs_score_val is not None and math.isfinite(float(rs_score_val)) else _v702_rs_points_from_raw(raw_rs)
    setup = fs.get("v643_canonical_quality")
    if setup is None:
        setup = fs.get("v587_setup_quality")
    if setup is None:
        setup = fs.get("setup_quality")
    if setup is None:
        setup = _opp.get("v643_canonical_quality")
    if setup is None:
        setup = _opp.get("v587_setup_quality")
    if setup is None:
        setup = _opp.get("setup_quality")
    try:
        setup = float(setup) if setup is not None else 0.0
        # Some StrategyCandidate fixtures expose setup quality as normalized 0..1;
        # the live Builder quality domain is 0..100. Normalize without weakening the gate.
        if 0.0 < setup <= 1.0:
            setup *= 100.0
    except Exception:
        setup = 0.0
    _gate_regime = str(regime or fs.get("macro_regime") or fs.get("regime") or _opp.get("macro_regime") or "").upper()
    _gate_severity = str(severity or fs.get("macro_severity") or fs.get("bearish_severity") or _opp.get("macro_severity") or "").upper()
    _a49_relief_meta = _v702_a49_elite_htf_relief_decision(
        _opp, htf_strength, regime=_gate_regime, severity=_gate_severity
    )
    _a49_relief_meta = _a49_relief_meta if isinstance(_a49_relief_meta, dict) else {"reason": "invalid_decision_payload"}
    _a49_relief_ok = bool(_a49_relief_meta.get("allowed", False))
    _effective_htf_floor = float(_a49_relief_meta.get("effective_floor", P["htf"])) if _a49_relief_ok else float(P["htf"])
    ctx = {
        "family": str((opp or {}).get("family", "")), "score": float(score), "score_floor": float(P["score"]),
        "htf": float(htf_strength), "htf_floor": float(P["htf"]),
        "htf_effective_floor": _effective_htf_floor,
        "htf_relief_applied": bool(_a49_relief_ok),
        "htf_relief": dict(_a49_relief_meta or {}),
        "volume": float(volume_ratio) if volume_ratio is not None else None, "volume_floor": float(P["volume"]),
        "rs_points": rs_points, "rs_points_floor": float(P["rs_points"]),
        "structure": float(structure_confidence) if structure_confidence is not None else None, "structure_floor": float(P["structure"]),
        "retest": float(retest_quality_score) if retest_quality_score is not None else None, "retest_floor": float(P["retest"]),
        "setup_quality": float(setup), "setup_floor": float(P["setup"]),
        "chase": float(chase_atr), "chase_max": float(P["chase"]), "tier": str(tier or ""),
    }
    checks = [
        ("score", score, ">=", P["score"]),
        # Honor only a currently re-verified A36 PULLBACK/MTF_PULLBACK HTF
        # grant for this same candidate and closed-bar snapshot. All other elite
        # dimensions, including score, structure, liquidity, retest and chase,
        # continue to use their original profile thresholds.
        ("htf", htf_strength, ">=", _effective_htf_floor),
        ("volume", volume_ratio, ">=", P["volume"]),
        ("rs", rs_points, ">=", P["rs_points"]),
        ("structure", structure_confidence, ">=", P["structure"]),
        ("retest", retest_quality_score, ">=", P["retest"]),
        ("chase", chase_atr, "<=", P["chase"]),
    ]
    if P["setup"] > 0.0:
        checks.append(("setup_quality", setup, ">=", P["setup"]))
    for name, val, op, floor in checks:
        try:
            if val is None or not math.isfinite(float(val)):
                return False, f"{name}_unverifiable", ctx
            ok = float(val) >= float(floor) if op == ">=" else float(val) <= float(floor)
            if not ok:
                return False, f"{name}_below_floor" if op == ">=" else f"{name}_above_ceiling", ctx
        except Exception:
            return False, f"{name}_unverifiable", ctx
    return True, "pass", ctx


def _v702_projected_builder_score_floors(candidate: Any, snapshot: Optional[Dict[str, Any]],
                                             score: float, features: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Reconstruct the Builder's active score floor for an exact projection.

    This function mirrors the score-floor order in SignalBuilder.build_and_route:
    base/regime adjustment, strategy policy and learned offsets, bounded adaptive
    floor, active V45 rescue, then the LIVE-only Elite layer and its narrowly
    bounded starvation relief. It only reads current policy state; it does not
    grant any permission to trade.
    """
    snap = snapshot if isinstance(snapshot, dict) else {}
    fs = dict(features or getattr(candidate, "features_snapshot", {}) or {})
    fam = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "PULLBACK").upper()
    mode = str(getattr(candidate, "strategy_mode", "") or fam).upper()
    is_live = bool(CONFIG.get("ENABLE_LIVE_TRADING", True)) and not bool(CONFIG.get("PAPER_TRADING_MODE", False))
    regime = str(snap.get("regime", snap.get("macro_regime", getattr(candidate, "macro_regime", "") or
                  STATS.get("regime", STATS.get("v684_regime", "NEUTRAL")) or "NEUTRAL")) or "NEUTRAL").upper()
    base_min = float(CONFIG.get("MIN_LIVE_SCORE", 70.0) if is_live else CONFIG.get("MIN_PAPER_SCORE", 55.0))
    if regime == "BEARISH":
        base_min += 8.0
    try:
        if CONFIG.get("REGIME_SCORE_FLOOR_ENABLE", True):
            offs = CONFIG.get("REGIME_SCORE_FLOOR_OFFSETS", {}) or {}
            base_min += max(-6.0, min(6.0, float(offs.get(regime, 0.0) or 0.0)))
    except Exception:
        pass
    if bool(CONFIG.get("V410_MASTER_ENABLE", True)):
        try:
            policy_data = CanonicalStrategyPolicyRegistry.data()
            if mode in policy_data:
                base_min = max(base_min, float(CanonicalStrategyPolicyRegistry.get(mode, {}).get("min_score", base_min)))
            else:
                base_min = float(FamilyPolicyLayer.min_score(base_min, fam))
            try:
                soff = float((CONFIG.get("MSE_STRATEGY_MIN_SCORE_OFFSETS", {}) or {}).get(mode, 0.0) or 0.0)
                sess = StrategyPerformanceMemory.session_bucket()
                learned = StrategyPerformanceMemory.score_floor_adjustment(
                    mode, regime, sess, str(getattr(candidate, "strategy_style", "SCALP") or "SCALP")
                )
                base_min = max(base_min + soff, base_min + learned)
            except Exception:
                pass
        except Exception:
            # Builder's equivalent policy errors preserve its canonical floor.
            pass
    canonical_floor = float(base_min)
    floor_min = float(CONFIG.get("V453_SCORE_FLOOR_MIN", 70.0))
    try:
        adaptive = float(getattr(_V420State, "adaptive_floor", canonical_floor) or canonical_floor)
        adaptive = max(floor_min, min(canonical_floor, adaptive))
    except Exception:
        adaptive = canonical_floor
    try:
        v45_floor = float(_v45_effective_score_floor(canonical_floor))
        v45_floor = max(floor_min, min(canonical_floor, v45_floor))
    except Exception:
        v45_floor = canonical_floor
    try:
        rescue_level = int(_v45_rescue_level())
    except Exception:
        rescue_level = 0
    effective = max(adaptive, v45_floor) if rescue_level > 0 else adaptive
    opp = {
        "family": fam,
        "strategy_mode": mode,
        "strategy_style": str(getattr(candidate, "strategy_style", "SCALP") or "SCALP"),
        "features_snapshot": fs,
    }
    elite_floor = None
    relief_applied = False
    relief_meta = {}
    if is_live and bool(CONFIG.get("V702_ELITE_LIVE_QUALITY_GATE_ENABLE", True)):
        try:
            elite_floor = float(_v702_live_quality_score_floor(opp))
            relief_fn = globals().get("_v704_starvation_score_floor_override")
            if callable(relief_fn):
                relief_applied, relief_meta = relief_fn(opp, float(score), elite_floor)
            if relief_applied:
                adjusted_elite = float((relief_meta or {}).get("effective_floor", elite_floor))
                hard_global = _v704_hard_global_score_floor()
                effective = max(hard_global, min(float(effective), adjusted_elite))
            else:
                effective = max(float(effective), elite_floor)
        except Exception:
            # Same fail-closed response as Builder if Elite floor evaluation fails.
            try:
                elite_floor = float(_v702_live_quality_score_floor(opp))
                effective = max(float(effective), elite_floor)
            except Exception:
                effective = max(float(effective), canonical_floor, float(CONFIG.get("MIN_LIVE_SCORE", 70.0)))
    return {
        "canonical_floor": float(canonical_floor),
        "effective_floor": float(effective),
        "elite_floor": float(elite_floor) if elite_floor is not None else None,
        "relief_applied": bool(relief_applied),
        "relief": dict(relief_meta or {}),
        "regime": regime,
        "is_live": bool(is_live),
        "rescue_level": int(rescue_level),
    }


def _v702_projected_canonical_score(candidate: Any, snapshot: Dict[str, Any]) -> Optional[float]:
    """Conservative pre-builder canonical projection from the exact cycle snapshot.

    This is a closed-snapshot score projection only. It never authorizes execution.
    R34 replays the deterministic post-CompositeScorer modifiers when their exact
    snapshot facts are available; live rechecks remain Builder/PreSend authority.
    """
    try:
        c = candidate
        fs = dict(getattr(c, "features_snapshot", {}) or {})
        snap = snapshot if isinstance(snapshot, dict) else {}
        sym = str(getattr(c, "symbol", "") or snap.get("symbol", ""))

        def _num(v):
            try:
                x = float(v)
                return x if math.isfinite(x) else None
            except Exception:
                return None

        # HTF must come from the same closed 1H grader as SignalBuilder. The
        # former projection guessed `htf_pass` from a numeric score and normalized
        # unknown states, while Builder can reject/recompute/bridge that same
        # evidence. A guessed HTF verdict must never produce a projection eligible
        # for a pre-Builder hard block.
        htf = _num(snap.get("htf_strength", fs.get("htf_strength")))
        htf_state = str(snap.get("htf_state", fs.get("htf_state", "UNKNOWN")) or "UNKNOWN").upper()
        htf_pass = False
        htf_projection_exact = False
        htf_projection_reason = "htf_closed_frame_unavailable"
        df1h_projection = snap.get("df_1h", fs.get("df_1h"))
        if df1h_projection is not None:
            try:
                _grade_pass, _grade_state, _grade_strength, _grade_reason = HTFGrader.grade(
                    df1h_projection, label=sym
                )
                _grade_strength_num = _num(_grade_strength)
                if _grade_strength_num is not None:
                    htf = _grade_strength_num
                htf_state = str(_grade_state or "UNKNOWN").upper()
                htf_pass = bool(_grade_pass)
                # Builder's next step calls the active HTF resolver when its raw
                # score is zero; that path deliberately sets pass=False if it
                # returns a recomputed score. Replaying resolver recovery/bridges
                # here would be a second policy authority, so keep it incomplete.
                if htf is not None and htf > 0.0 and htf_pass:
                    htf_projection_exact = True
                    htf_projection_reason = ""
                elif htf is not None and htf <= 0.0:
                    htf_pass = False
                    htf_projection_reason = "htf_zero_requires_builder_resolver_revalidation"
                else:
                    # HTF may still pass downstream via existing local bridge or
                    # selected-candidate recovery, which the projection does not
                    # authorize or duplicate.
                    htf_projection_reason = "htf_grader_reject_requires_builder_revalidation"
            except Exception as _htf_projection_exc:
                htf_pass = False
                htf_projection_exact = False
                htf_projection_reason = f"htf_grader_error:{type(_htf_projection_exc).__name__}"
        else:
            # A numeric HTF field alone is not proof of Builder's HTF pass/state.
            # Keep it for advisory scoring metadata only and remain non-authoritative.
            if htf is None:
                htf = 0.0
            htf_pass = False
            htf_projection_reason = "htf_closed_frame_unavailable"

        df5 = snap.get("df_5m")
        if df5 is not None and len(df5) >= 52:
            try:
                close_s = pd.to_numeric(df5["close"], errors="coerce")
                open_s = pd.to_numeric(df5["open"], errors="coerce")
                high_s = pd.to_numeric(df5["high"], errors="coerce")
                low_s = pd.to_numeric(df5["low"], errors="coerce")
                vol_s = pd.to_numeric(df5["volume"], errors="coerce")
                lc = float(close_s.iloc[-2]); pc = float(close_s.iloc[-3]); op = float(open_s.iloc[-2])
                hi = float(high_s.iloc[-2]); lo = float(low_s.iloc[-2])
                atr_s = Indicators.atr(df5, int(CONFIG.get("ATR_PERIOD", 14)))
                atr = float(atr_s.iloc[-2]) if atr_s is not None else float("nan")
                if math.isfinite(atr) and atr > 0:
                    zone = _num(fs.get("zone_ref", getattr(c, "zone_ref", None)))
                    if zone is None:
                        zone = _num(getattr(c, "entry_ref", None))
                    reclaim = bool(zone is not None and pc < zone <= lc)
                    body_ratio = abs(lc - op) / max(hi - lo, 1e-12)

                    # Volume: exact Builder window (20 prior CLOSED bars).
                    if _num(fs.get("volume_ratio")) is None:
                        v_now = float(vol_s.iloc[-2]); v_base = float(vol_s.iloc[-22:-2].mean())
                        if math.isfinite(v_now) and math.isfinite(v_base) and v_base > 0:
                            fs["volume_ratio"] = v_now / v_base

                    # Structure: exact Builder formula from closed BOS/reclaim/body evidence.
                    if _num(fs.get("structure_confidence", fs.get("structure_quality"))) is None:
                        try:
                            bos_ok, bos_strength = MicroStructure.micro_bos_confirm(df5)
                        except Exception:
                            bos_ok, bos_strength = False, 0.0
                        sc = 0.0
                        if bos_ok:
                            sc += 45.0 + min(25.0, float(bos_strength) * float(CONFIG.get("BOS_STRENGTH_SCORE_MULT", 5000.0)))
                        if reclaim:
                            sc += 20.0
                        sc += min(10.0, body_ratio * 10.0)
                        fs["structure_confidence"] = _clamp(sc, 0.0, 100.0)
                        fs["structure_quality"] = fs["structure_confidence"]
                        fs["bos_confirmed"] = bool(bos_ok)
                        fs["micro_bos"] = bool(bos_ok)
                        fs["bos_strength"] = float(bos_strength)
                    fs.setdefault("reclaim_detected", reclaim)

                    # Retest quality: same distance/zone/recovery model used by the
                    # canonical Builder.  This applies to every family at projection
                    # time without altering their generation or execution gates.
                    if _num(fs.get("retest_quality_score", fs.get("retest_quality"))) is None:
                        dist_atr = abs(lc - zone) / max(atr, 1e-9) if zone is not None else 99.0
                        zclass = fs.get("zone_quality_class", fs.get("zone_class"))
                        if not zclass:
                            zclass = MicroStructure.zone_quality_class(dist_atr, freshness_bars=3)
                        rq = 60.0 if dist_atr <= 0.3 else 40.0 if dist_atr <= 0.6 else 20.0 if dist_atr <= 1.0 else 5.0
                        if str(zclass).upper() == "STRONG_FRESH": rq += 30.0
                        elif str(zclass).upper() == "ACCEPTABLE": rq += 15.0
                        elif str(zclass).upper() == "WEAK_STALE": rq -= 10.0
                        higher_low = bool(float(low_s.iloc[-2]) > float(low_s.iloc[-3]) >= float(low_s.iloc[-4]))
                        bullish_close = bool(lc > op and lc >= pc)
                        ema20 = close_s.ewm(span=20, adjust=False).mean()
                        ema20_slope_up = bool(float(ema20.iloc[-2]) > float(ema20.iloc[-9]) * 1.0001)
                        try:
                            rej = bool(MicroStructure.rejection_candle_confirm(df5))
                        except Exception:
                            rej = False
                        if reclaim: rq += 10.0
                        if higher_low: rq += 10.0
                        if bullish_close: rq += 5.0
                        if ema20_slope_up: rq += 5.0
                        if rej: rq += 10.0
                        fs["retest_quality_score"] = _clamp(rq, 0.0, 100.0)
                        fs["retest_quality"] = fs["retest_quality_score"]
                        fs["higher_low_5m"] = higher_low
                        fs["bullish_close_5m"] = bullish_close
                        fs["ema20_slope_up"] = ema20_slope_up
                        fs["zone_quality_class"] = str(zclass).upper()
                        if zone is not None:
                            fs["zone_ref"] = zone

                    # Remaining quantitative inputs are also derived from CLOSED bars.
                    if _num(fs.get("vol_delta_score")) is None:
                        v_last = float(vol_s.iloc[-2]); v_prev = float(vol_s.iloc[-3])
                        if math.isfinite(v_last) and math.isfinite(v_prev) and v_prev > 0:
                            fs["vol_delta_score"] = _clamp((v_last / v_prev - 1.0) * 5.0, 0.0, 3.0)
                    if _num(fs.get("momentum_score_val")) is None:
                        rsi_series = Indicators.rsi(close_s, CONFIG["RSI_PERIOD"])
                        adx_series = Indicators.adx(df5, CONFIG["ADX_PERIOD"])
                        rsi_v = float(rsi_series.iloc[-2]) if rsi_series is not None else float("nan")
                        ms = 0.0
                        if math.isfinite(rsi_v):
                            if 40.0 <= rsi_v <= 65.0: ms += 4.0
                            elif rsi_v > 65.0: ms += 2.0
                            elif rsi_v < 30.0: ms += 3.0
                        if adx_series is not None:
                            adx_v = float(adx_series.iloc[-2])
                            if adx_v >= float(CONFIG.get("ADX_BASE_THRESHOLD")): ms += 3.0
                            elif adx_v >= float(CONFIG.get("ADX_SOFT_PENALTY")): ms += 1.5
                        if str(getattr(c, "family", "") or "").upper() == "MOMENTUM_EXPANSION": ms += 3.0
                        fs["momentum_score_val"] = _clamp(ms, 0.0, 10.0)
                    fs.setdefault("chase_atr", max(0.0, (float(getattr(c, "entry_ref", lc)) - float(zone)) / max(atr, 1e-9)) if zone is not None else 0.0)
                    fs.setdefault("spread_pct", snap.get("spread_pct"))
                    fs.setdefault("orderbook_imbalance", snap.get("orderbook_imbalance"))
            except Exception:
                _v647_record_suppressed_exception()

        # Final fallbacks: use the existing proven snapshot enrichment for fields
        # not reconstructed above. This path does not perform any market fetch.
        structure = snap.get("structure_confidence", snap.get("structure_quality", fs.get("structure_confidence", fs.get("structure_quality"))))
        retest = snap.get("retest_quality_score", snap.get("retest_quality", fs.get("retest_quality_score", fs.get("retest_quality"))))
        volume = snap.get("volume_ratio", fs.get("volume_ratio"))
        if structure is None or retest is None or volume is None:
            c2, diag = _v672_enrich_candidate_from_snapshot(c, snap, source="v702_r5_projection")
            fs2 = dict(getattr(c2, "features_snapshot", {}) or {})
            fs.update(fs2)
            structure = snap.get("structure_confidence", snap.get("structure_quality", fs.get("structure_confidence", fs.get("structure_quality"))))
            retest = snap.get("retest_quality_score", snap.get("retest_quality", fs.get("retest_quality_score", fs.get("retest_quality"))))
            volume = snap.get("volume_ratio", fs.get("volume_ratio"))
        structure = _num(structure); retest = _num(retest); volume = _num(volume)
        if structure is None or retest is None or volume is None:
            STATS["v702_selection_projection_unverifiable"] = int(STATS.get("v702_selection_projection_unverifiable", 0) or 0) + 1
            return None

        rs_points = _num(snap.get("rs_score_val", fs.get("rs_score_val")))
        if rs_points is None:
            rs_points = _v702_rs_points_from_raw(snap.get("rs_5m", fs.get("rs_5m", fs.get("relative_strength", 0.0))))
        if rs_points is None:
            return None
        ob = _num(snap.get("orderbook_imbalance", fs.get("orderbook_imbalance")))
        if ob is None: ob = 0.45
        spread = _num(snap.get("spread_pct", fs.get("spread_pct")))
        if spread is None: spread = float(CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15)) * 0.75
        mom = _num(snap.get("momentum_score_val", fs.get("momentum_score_val")))
        if mom is None: mom = 5.0
        tier = str(snap.get("tier", fs.get("liquidity_tier", fs.get("tier", "MID"))) or "MID").upper()
        zone = str(fs.get("zone_quality_class", fs.get("zone_class", "ACCEPTABLE")) or "ACCEPTABLE").upper()
        fam = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "").upper()
        score, _, _ = CompositeScorer.build(
            htf_passed=htf_pass, htf_strength=htf, htf_state=htf_state,
            structure_confidence=structure, reclaim_detected=bool(fs.get("reclaim_detected", fs.get("zone_reclaim", False))),
            bos_detected=bool(fs.get("bos_confirmed", fs.get("micro_bos", False))),
            retest_quality_score=retest, volume_ratio=volume,
            vol_delta_score=float(fs.get("vol_delta_score", 0.0) or 0.0),
            orderbook_imbalance=float(ob), momentum_score_val=float(mom),
            rs_score_val=float(rs_points), spread_pct=float(spread), liquidity_tier=tier,
            sweep_detected=fam == "LIQUIDITY_SWEEP_REVERSAL", equal_lows_sweep=False,
            rejection_type=str(fs.get("rejection_type", "") or ""), zone_quality_class=zone,
            fvg_present=bool(fs.get("fvg_present", False)), fib_golden=bool(fs.get("fib_golden", False)),
            rsi_div=bool(fs.get("rsi_div", False)), symbol=sym,
            strategy_mode=str(getattr(c, "strategy_mode", "") or fam), measured_rr=float(getattr(c, "rr_ratio", 0.0) or 0.0),
        )
        if not math.isfinite(float(score)):
            return None

        # R34 FINAL SCORE-PARITY CLOSURE
        # Replay the deterministic score modifiers that SignalBuilder applies
        # immediately after CompositeScorer.build(). This is still a CLOSED-snapshot
        # projection: no exchange fetch, no order authorization, and no gate bypass.
        # Missing live-only facts keep the projection advisory/incomplete instead of
        # fabricating a pass.
        parity_complete = bool(htf_projection_exact)
        parity_notes = [] if htf_projection_exact else [str(htf_projection_reason or "htf_projection_not_authoritative")]
        if not htf_projection_exact:
            STATS["v702_a35_projection_htf_incomplete"] = int(STATS.get("v702_a35_projection_htf_incomplete", 0) or 0) + 1
            STATS["v702_a35_projection_htf_last_reason"] = str(htf_projection_reason or "htf_projection_not_authoritative")
        try:
            # Confluence: exact CLOSED 5m replay.
            _entry_px = _num(getattr(c, "entry_ref", None))
            if _entry_px is None and df5 is not None and len(df5) >= 2:
                _entry_px = float(df5["close"].iloc[-2])
            if bool(CONFIG.get("V410_MASTER_ENABLE", True)) and _entry_px is not None and df5 is not None:
                _v410_boost, _ = confluence_boost_v410(df5, bool(fs.get("bos_confirmed", fs.get("micro_bos", False))), float(_entry_px)) if CONFIG.get("V410_MASTER_ENABLE", True) else (0.0,{})
                score = _clamp(float(score) + float(_v410_boost), 0.0, 100.0)
            elif bool(CONFIG.get("V410_MASTER_ENABLE", True)):
                parity_complete = False; parity_notes.append("confluence_unverifiable")

            # D1 adjustment: Builder uses the exact market_data df_1d when available.
            _df1d = snap.get("df_1d")
            if bool(CONFIG.get("V410_D1_BIAS_ENABLE", True)):
                if _df1d is not None and len(_df1d) >= int(CONFIG.get("V410_D1_MIN_CANDLES", 80)):
                    _d1_adj, _ = d1_bias_score_v410(_df1d)
                    score = _clamp(float(score) + float(_d1_adj), 0.0, 100.0)
                else:
                    parity_complete = False; parity_notes.append("d1_unavailable")

            # Breadth is a direct normalized score in the Builder.
            if bool(CONFIG.get("V410_BREADTH_ENABLE", True)):
                _breadth_raw = snap.get("breadth_score")
                if _breadth_raw is not None:
                    _breadth_adj, _ = breadth_adjustment_v410({"breadth_score": _breadth_raw})
                    score = _clamp(float(score) + float(_breadth_adj), 0.0, 100.0)
                else:
                    parity_complete = False; parity_notes.append("breadth_unavailable")

            # MTF confluence: replay exact deterministic branch inputs from candidate context.
            if fam == "MTF_PULLBACK":
                _mtf_bonus = 0.0
                _anchor = str(fs.get("anchor") or fs.get("zone_type") or getattr(c, "anchor", "") or "").upper()
                if _anchor.startswith("EMA20"): _mtf_bonus += 1.5
                elif _anchor.startswith("EMA50"): _mtf_bonus += 1.0
                elif _anchor.startswith("VWAP"): _mtf_bonus += 0.75
                _mrsi = _num(snap.get("rsi_5m", fs.get("rsi_5m")))
                _mvr = _num(snap.get("volume_ratio", fs.get("volume_ratio")))
                if _mrsi is None or _mvr is None:
                    parity_complete = False; parity_notes.append("mtf_inputs_unavailable")
                else:
                    if 50.0 <= _mrsi <= 62.0: _mtf_bonus += 1.5
                    elif float(CONFIG.get("MTF_PULLBACK_RSI_MIN", 45.0)) <= _mrsi <= float(CONFIG.get("MTF_PULLBACK_RSI_MAX", 68.0)): _mtf_bonus += 0.75
                    if _mvr >= 1.20: _mtf_bonus += 1.5
                    elif _mvr >= 1.00: _mtf_bonus += 0.75
                    if bool(fs.get("higher_low_5m", False)): _mtf_bonus += 0.75
                    _mtf_bonus = min(float(CONFIG.get("MTF_PULLBACK_CONFLUENCE_BOOST_MAX", 6.0)), max(0.0, _mtf_bonus))
                    score = _clamp(float(score) + _mtf_bonus, 0.0, 100.0)

            # Fake-break soft penalty: replay the exact gate from the closed snapshot.
            if bool(CONFIG.get("V520_PREQUAL_FAKE_BREAK_ENABLE", True)):
                _d5 = snap.get("df_5m")
                _zone_ref_num = _num(fs.get("zone_ref", getattr(c, "zone_ref", None)))
                if _d5 is None or _zone_ref_num is None or len(_d5) < 20:
                    parity_complete = False; parity_notes.append("fake_break_inputs_unavailable")
                else:
                    try:
                        _atr_p = float(Indicators.atr(_d5, CONFIG["ATR_PERIOD"]).iloc[-2])
                    except Exception:
                        _atr_p = 0.0
                    if not math.isfinite(_atr_p) or _atr_p <= 0.0:
                        parity_complete = False; parity_notes.append("atr_unavailable")
                    else:
                        _fb_ok, _fb_ctx = _v520_fake_break_gate(_d5, family=fam, zone_ref=_zone_ref_num, atr_value=_atr_p)
                        if not bool((_fb_ctx or {}).get("raw_safe", True)):
                            _fbp = max(0.0, float(CONFIG.get("FAKE_BREAK_SOFT_PENALTY", 4.0)))
                            score = _clamp(float(score) - _fbp, 0.0, 100.0)

            # Family soft penalties are deterministic and already part of Builder score.
            _family_name = fam or str(getattr(c, "strategy_mode", "PULLBACK") or "PULLBACK")
            if bool(CONFIG.get("V423_FAMILY_ZONE_PENALTY_ENABLE", True)):
                _anchor = str(fs.get("anchor") or fs.get("zone_type") or getattr(c, "anchor", "") or "")
                if _anchor and not FamilyPolicyLayer.zone_preferred(_family_name, _anchor):
                    _zmax = max(0.0, float(CONFIG.get("FAMILY_ZONE_MISMATCH_PENALTY_MAX", 6.0)))
                    score = _clamp(float(score) - _zmax, 0.0, 100.0)
            if bool(CONFIG.get("V423_FAMILY_VOLUME_PENALTY_ENABLE", True)):
                _vf = FamilyPolicyLayer.volume_floor_ratio(_family_name)
                if _vf > 0 and volume is not None and math.isfinite(float(volume)) and float(volume) < _vf:
                    _gap = max(0.0, min(1.0, (_vf - float(volume)) / _vf))
                    _vmax = max(0.0, float(CONFIG.get("FAMILY_VOLUME_FLOOR_PENALTY_MAX", 4.0)))
                    score = _clamp(float(score) - min(_vmax, _vmax * _gap), 0.0, 100.0)

            # Orderbook bonus / MICRO hard confirmation are terminal builder facts.
            # Only apply the bonus when the exact cached book is present and passes.
            _raw_ob = snap.get("orderbook") or snap.get("depth")
            _ob_complete = False
            if isinstance(_raw_ob, dict) and spread is not None and volume is not None:
                try:
                    _ob_ok, _ob_reason = _v45_orderbook_confirmation(
                        _raw_ob,
                        {
                            "spread_pct": float(spread),
                            "depth_ratio": float(snap.get("depth_ratio", fs.get("depth_ratio", 0.0)) or 0.0),
                            "volume_ratio": float(volume),
                            "structure_confidence": float(structure),
                            "structure_quality": float(structure),
                            "chase_atr": float(fs.get("chase_atr", 0.0) or 0.0),
                        }, tier
                    )
                    _ob_complete = True
                    if _ob_ok:
                        score = _clamp(float(score) + 1.5, 0.0, 100.0)
                    elif str(tier).upper() == "MICRO":
                        parity_complete = False; parity_notes.append("micro_orderbook_would_block")
                except Exception:
                    parity_complete = False; parity_notes.append("orderbook_confirmation_unverifiable")
            else:
                parity_complete = False; parity_notes.append("orderbook_snapshot_unavailable")

            # Spread/orderbook imbalance must be real snapshot facts for parity.
            if _num(snap.get("spread_pct", fs.get("spread_pct"))) is None:
                parity_complete = False; parity_notes.append("spread_unavailable")
            if _num(snap.get("orderbook_imbalance", fs.get("orderbook_imbalance"))) is None:
                parity_complete = False; parity_notes.append("orderbook_imbalance_unavailable")
        except Exception as _parity_exc:
            parity_complete = False
            parity_notes.append(f"post_modifier_error:{type(_parity_exc).__name__}")

        # Per-symbol status lets the prequal stage consume the exact parity result
        # without relying on a global "last candidate" variable in concurrent scans.
        try:
            # Score-floor parity is resolved through the same ordered policy stack
            # as the live Builder, including regime offsets, learned adjustments,
            # bounded rescue, Elite floor, and eligible starvation relief.
            _opp_probe = {
                "family": fam,
                "strategy_mode": str(getattr(c, "strategy_mode", "") or fam),
                "strategy_style": str(getattr(c, "strategy_style", "SCALP") or "SCALP"),
                "features_snapshot": dict(fs),
            }
            _floor_probe = _v702_projected_builder_score_floors(c, snap, float(score), fs)
            _canonical_min_probe = float(_floor_probe.get("canonical_floor", CONFIG.get("MIN_LIVE_SCORE", 70.0)))
            _effective_floor_probe = float(_floor_probe.get("effective_floor", max(70.0, _canonical_min_probe)))
            _st = {
                "score": float(score),
                "effective_floor": float(_effective_floor_probe),
                "canonical_floor": float(_canonical_min_probe),
                "floor_probe": dict(_floor_probe),
                "complete": bool(parity_complete),
                "notes": list(dict.fromkeys(parity_notes))[:16],
                "symbol": sym,
                "candidate_object_id": id(c),
                "family": str(fam or "").upper(),
                "candidate_id": str(snap.get("candidate_id") or getattr(c, "generated_at_ms", "") or ""),
                "candle_ts": str(snap.get("closed_candle_ts") or snap.get("candle_ts") or fs.get("closed_candle_ts") or fs.get("candle_ts") or ""),
                "cycle_id": str(snap.get("cycle_id") or ""),
                "ts": WALL_NOW(),
            }
            _status_map = globals().setdefault("_V702_R34_PROJECTION_STATUS", {})
            _status_map[sym] = _st
            if len(_status_map) > 256:
                _status_map.pop(next(iter(_status_map)))
        except Exception:
            _v647_record_suppressed_exception()

        STATS["v702_selection_projection_computed"] = int(STATS.get("v702_selection_projection_computed", 0) or 0) + 1
        if parity_complete:
            STATS["v702_r34_projection_parity_complete"] = int(STATS.get("v702_r34_projection_parity_complete", 0) or 0) + 1
        else:
            STATS["v702_r34_projection_parity_incomplete"] = int(STATS.get("v702_r34_projection_parity_incomplete", 0) or 0) + 1
        # V702 R11 immutability remains intact: never mutate the candidate object here.
        return float(score)
    except Exception as exc:
        try:
            sym = str(getattr(candidate, "symbol", "") or (snapshot or {}).get("symbol", ""))
            _status_map = globals().setdefault("_V702_R34_PROJECTION_STATUS", {})
            _status_map[sym] = {"score": None, "complete": False, "notes": [f"exception:{type(exc).__name__}"], "symbol": sym, "ts": WALL_NOW()}
        except Exception:
            pass
        return None

def _v702_exact_route_projection_current_status(candidate: Any, snapshot: Optional[Dict[str, Any]],
                                                   projected_score: float, max_age_sec: float = 45.0):
    """Return the exact complete projection status only when its provenance is current."""
    try:
        c = candidate
        snap = snapshot if isinstance(snapshot, dict) else {}
        symbol = str(getattr(c, "symbol", "") or snap.get("symbol", ""))
        if not symbol or not math.isfinite(float(projected_score)):
            return None
        statuses = globals().get("_V702_R34_PROJECTION_STATUS", {})
        status = dict(statuses.get(symbol, {}) or {}) if isinstance(statuses, dict) else {}
        if not status or status.get("complete") is not True:
            return None
        if str(status.get("symbol", "") or "") != symbol:
            return None
        if int(status.get("candidate_object_id", -1) or -1) != id(c):
            return None
        status_score = float(status.get("score"))
        if not math.isfinite(status_score) or abs(status_score - float(projected_score)) > 0.05:
            return None
        ts = float(status.get("ts", 0.0) or 0.0)
        age = float(WALL_NOW()) - ts
        if ts <= 0.0 or age < 0.0 or age > max(1.0, float(max_age_sec)):
            return None
        snap_cycle = str(snap.get("cycle_id") or "")
        status_cycle = str(status.get("cycle_id") or "")
        if snap_cycle and status_cycle and snap_cycle != status_cycle:
            return None
        snap_candle = str(snap.get("closed_candle_ts") or snap.get("candle_ts") or "")
        status_candle = str(status.get("candle_ts") or "")
        if snap_candle and status_candle and snap_candle != status_candle:
            return None
        snap_candidate_id = str(snap.get("candidate_id") or "")
        status_candidate_id = str(status.get("candidate_id") or "")
        if snap_candidate_id and status_candidate_id and snap_candidate_id != status_candidate_id:
            return None
        return status
    except Exception:
        return None


def _v702_exact_route_projection_hard_block_allowed(candidate: Any, snapshot: Optional[Dict[str, Any]],
                                                       projected_score: float, floor: float,
                                                       max_age_sec: float = 45.0) -> bool:
    """Permit an early score rejection only for exact, complete, fresh parity."""
    try:
        if not math.isfinite(float(projected_score)) or float(projected_score) >= float(floor):
            return False
        return _v702_exact_route_projection_current_status(
            candidate, snapshot, projected_score, max_age_sec=max_age_sec
        ) is not None
    except Exception:
        return False


def _v702_exact_route_projection_effective_floor(candidate: Any, snapshot: Optional[Dict[str, Any]],
                                                  projected_score: float, base_floor: float,
                                                  max_age_sec: float = 45.0) -> float:
    """Use the exact Builder floor for current complete projections; otherwise defer."""
    try:
        base = max(float(CONFIG.get("MIN_LIVE_SCORE", 70.0)), float(base_floor))
        status = _v702_exact_route_projection_current_status(
            candidate, snapshot, projected_score, max_age_sec=max_age_sec
        )
        if status is None:
            return base
        effective = float(status.get("effective_floor"))
        if not math.isfinite(effective):
            return base
        # A current status already includes bounded starvation relief when that
        # policy is eligible. Do not re-impose a higher pre-relief base floor.
        return effective
    except Exception:
        return max(float(CONFIG.get("MIN_LIVE_SCORE", 70.0)), float(base_floor))


def _v702_r5_projection_disposition(candidate: Any, snapshot: Dict[str, Any],
                                       projected_score: float, base_score: float,
                                       blend_weight: Optional[float] = None) -> Dict[str, Any]:
    """Decide whether projection is trustworthy enough to rank or reject.

    Incomplete/stale/mismatched parity retains the original arbiter score. A complete
    exact projection below the Builder's actual score floor is rejected before it can
    consume a winner slot. A complete passing projection may influence ordering.
    """
    try:
        w = _clamp(float(CONFIG.get("V702_SELECTION_PROJECTED_BLEND_WEIGHT", 0.40)
                      if blend_weight is None else blend_weight), 0.0, 0.60)
        status = _v702_exact_route_projection_current_status(candidate, snapshot, float(projected_score))
        if status is None:
            return {"complete": False, "hard_block": False, "floor": None,
                    "ranking_score": float(base_score), "status": "INCOMPLETE_KEEP_CANONICAL_RANK"}
        floor = float(status.get("effective_floor"))
        if not math.isfinite(floor):
            return {"complete": False, "hard_block": False, "floor": None,
                    "ranking_score": float(base_score), "status": "INVALID_FLOOR_KEEP_CANONICAL_RANK"}
        projected = float(projected_score)
        if projected < floor:
            return {"complete": True, "hard_block": True, "floor": floor,
                    "ranking_score": float(base_score), "status": "EXACT_UNDERFLOOR"}
        blended = (1.0 - w) * float(base_score) + w * (projected / 100.0)
        return {"complete": True, "hard_block": False, "floor": floor,
                "ranking_score": float(blended), "status": "EXACT_PASS_BLEND"}
    except Exception as exc:
        return {"complete": False, "hard_block": False, "floor": None,
                "ranking_score": float(base_score), "status": f"ERROR_KEEP_CANONICAL_RANK:{type(exc).__name__}"}


def _v702_selection_projection_route_gate(row: Any, snapshot: Optional[Dict[str, Any]] = None,
                                          source: str = "route") -> Tuple[bool, str, Optional[RankedCandidate]]:
    """Attach the R5 projection without introducing a second hard live gate.

    R11 closes the observed starvation mode: the projection floor is an advisory
    ordering/telemetry reference only.  Canonical PreSend/fee/liquidity/structure/
    balance/SL/execution gates remain authoritative and unchanged.  Missing exact
    snapshot provenance is still fail-closed because a projection cannot be
    trusted without the closed-cycle context.
    """
    try:
        if not bool(CONFIG.get("V702_SELECTION_CANONICAL_PROJECTION_ENABLE", True)):
            return True, "disabled", row
        if row is None or not hasattr(row, "candidate"):
            return False, "selection_projection_invalid_row", None
        c = row.candidate
        sym = str(getattr(c, "symbol", "") or "")
        snap = snapshot if isinstance(snapshot, dict) else {}
        if not snap:
            STATS["v702_selection_projection_unverifiable_advisory"] = int(STATS.get("v702_selection_projection_unverifiable_advisory", 0) or 0) + 1
            return True, "selection_projection_unverifiable_advisory", row
        proj = _v702_projected_canonical_score(c, snap)
        floor = float(CONFIG.get("V702_SELECTION_PROJECTED_CANONICAL_FLOOR", 66.0))
        fs = dict(getattr(c, "features_snapshot", {}) or {})
        fs["v702_selection_projection_floor"] = floor
        fs["v702_selection_projection_source"] = "EXACT_CLOSED_SNAPSHOT_ADVISORY"
        if proj is None or not math.isfinite(float(proj)):
            STATS["v702_selection_projection_unverifiable_advisory"] = int(STATS.get("v702_selection_projection_unverifiable_advisory", 0) or 0) + 1
            fs["v702_selection_projection_status"] = "UNVERIFIABLE_ADVISORY"
            r2 = replace(row, candidate=replace(c, features_snapshot=fs))
            return True, "projection_unverifiable_advisory", r2
        fs["v702_projected_canonical_score"] = float(proj)
        if float(proj) < floor:
            STATS["v702_selection_projection_advisory_below_floor"] = int(STATS.get("v702_selection_projection_advisory_below_floor", 0) or 0) + 1
            fs["v702_selection_projection_status"] = "BELOW_FLOOR_ADVISORY"
            logger.debug("[V702-R11-PROJECTION] advisory route=%s symbol=%s projected=%.2f floor=%.2f", source, sym, float(proj), floor)
            r2 = replace(row, candidate=replace(c, features_snapshot=fs))
            return True, f"projection_below_floor_advisory:{float(proj):.2f}<{floor:.2f}", r2
        fs["v702_selection_projection_status"] = "ABOVE_FLOOR"
        r2 = replace(row, candidate=replace(c, features_snapshot=fs))
        STATS["v702_selection_route_projection_pass"] = int(STATS.get("v702_selection_route_projection_pass", 0) or 0) + 1
        return True, "pass", r2
    except Exception as exc:
        STATS["v702_selection_route_projection_errors"] = int(STATS.get("v702_selection_route_projection_errors", 0) or 0) + 1
        return False, f"selection_projection_error:{type(exc).__name__}", None


# V702 R5 selection-context registry. The Global Brain publishes exact
# current-cycle snapshots for the prequalified pool before selector execution.
# This is data-provenance only: no new market read and no stale fallback.
_V702_ACTIVE_SELECTION_SNAPSHOTS: Dict[str, Dict[str, Any]] = {}

# V702 R5 SELECTION AUTHORITY CLOSURE
# The existing arbiter remains the single selector. During the R5 call only,
# its existing _candidate_score authority consumes the R5 blended score that
# was computed from the same candidate snapshot. Outside that bounded context,
# the inherited score function is untouched.
def _v702_note_selection_projection_reject(symbol: str, reason: str, *, score: Optional[float] = None,
                                             projected: Optional[float] = None, floor: Optional[float] = None,
                                             source: str = "select") -> None:
    """Record an R5 selection-projection choke in the canonical rejection ledger.

    Telemetry only. Live-epoch scoped so import-time validation/self-tests never
    contaminate production rejection counts.
    """
    try:
        if not bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
            return
        _cycle_id = int(
            globals().get("_V517_ACTIVE_CYCLE_ID")
            or STATS.get("v681_runtime_cycle_id", 0)
            or STATS.get("v648_cycle_id", 0)
            or STATS.get("v669_last_cycle_id", 0)
            or 0
        )
        ctx = {
            "source": "V702_R5_SELECTION_PROJECTION",
            "projected_canonical_score": projected,
            "projected_floor": floor,
            "cycle_id": _cycle_id,
        }
        # Selection-projection is telemetry-only. Prefer the original canonical
        # recorder before the Telegram wrapper so a ranking choke cannot create a
        # noisy rejection alert; the cycle is already bound explicitly in ctx.
        _telemetry_recorder = globals().get("_orig_v652_record_rejection") or globals().get("record_rejection")
        _telemetry_recorder(None, str(symbol), "score", str(reason), str(source), score=score, ctx=ctx)
        # Defensive ledger fallback: some terminal wrapper stacks may legitimately
        # return after recording STATS/Funnel data without producing the forensic
        # ledger event.  In that case append the event exactly once, preserving the
        # same cycle/stage/reason and never changing selection authority.
        _cycle_id_now = int(ctx.get("cycle_id", 0) or 0)
        _code_now = str(reason)
        _has_event = any(
            int(e.get("cycle_id", 0) or 0) == _cycle_id_now
            and str(e.get("symbol", "")) == str(symbol)
            and str(e.get("stage", "")) == str(source)
            and str(e.get("reason_code", "")) == _code_now
            for e in list(getattr(V669RejectionLedger, "_events", ()))
        )
        if not _has_event:
            _ledger_key = _canonical_reject_code("score", _code_now)
            V669RejectionLedger.note({
                "event_id": uuid.uuid4().hex[:16], "trace_id": "",
                "cycle_id": _cycle_id_now, "opportunity_id": _v669_opportunity_id(
                    str(symbol), "", "", "", ""
                ), "duplicate_evaluation": False,
                "symbol": str(symbol), "family": "", "strategy_mode": "",
                "stage": str(source), "reason_code": _code_now,
                "reason_detail": "", "taxonomy": "score",
                "canonical_key": _ledger_key, "score": score,
                "engine_score": None, "macro_regime": None, "local_regime": None,
                "phase": None, "htf_strength": None, "liquidity_tier": None,
                "entry": None, "sl": None, "tp1": None, "tp2": None,
                "fee_detail": None, "candle_ts": None, "exception_type": None,
                "exception_message": "",
            })
        STATS["v702_selection_projection_ledger_rejects"] = int(
            STATS.get("v702_selection_projection_ledger_rejects", 0) or 0
        ) + 1
    except Exception as exc:
        _v593_note_suppressed_exception("v702.selection_projection_rejection_telemetry", exc)


_V702_SELECTION_BLEND_CTX = {"active": False}
try:
    _v702_r5_base_candidate_score = GlobalOpportunityArbiter._candidate_score
    def _v702_r5_selection_aware_candidate_score(candidate_ranked):
        try:
            if bool(_V702_SELECTION_BLEND_CTX.get("active", False)):
                fs = dict(getattr(getattr(candidate_ranked, "candidate", None), "features_snapshot", {}) or {})
                blended = fs.get("v702_selection_blended_score")
                if blended is not None:
                    val = float(blended)
                    if math.isfinite(val):
                        return _clamp(val, 0.0, 1.0)
        except Exception:
            pass
        return float(_v702_r5_base_candidate_score(candidate_ranked))
    GlobalOpportunityArbiter._candidate_score = staticmethod(_v702_r5_selection_aware_candidate_score)
    STATS["v702_r5_selection_score_authority_wired"] = True
except Exception as _v702_sel_score_exc:
    STATS["v702_r5_selection_score_authority_wired"] = False
    STATS["v702_r5_selection_score_authority_error"] = f"{type(_v702_sel_score_exc).__name__}:{_v702_sel_score_exc}"

# Terminal selection wrapper: eliminate the repeated Selected -> Builder score cliff
# by ranking only candidates that have a credible pre-builder canonical projection,
# and blend the projection into ordering without bypassing family/correlation caps.
try:
    _v702_orig_arbiter_select = GlobalOpportunityArbiter.select
    if not getattr(_v702_orig_arbiter_select, "_v702_r5_wrapped", False):
        @classmethod
        def _v702_arbiter_select_r5(cls, ranked: List[RankedCandidate], max_winners: int = 3):
            if not bool(CONFIG.get("V702_SELECTION_CANONICAL_PROJECTION_ENABLE", True)):
                return _v702_orig_arbiter_select(ranked, max_winners)
            prepared = []
            floor = float(CONFIG.get("V702_SELECTION_PROJECTED_CANONICAL_FLOOR", 66.0))
            blend_w = _clamp(float(CONFIG.get("V702_SELECTION_PROJECTED_BLEND_WEIGHT", 0.40)), 0.0, 0.60)
            base_w = 1.0 - blend_w
            advisory_below = 0
            unverifiable = 0
            seen = 0
            blocked = 0
            for r in list(ranked or []):
                try:
                    c = r.candidate
                    sym = str(getattr(c, "symbol", "") or "")
                    fs = dict(getattr(c, "features_snapshot", {}) or {})
                    snap = dict(_V702_ACTIVE_SELECTION_SNAPSHOTS.get(sym) or {})
                    if not snap:
                        # Projection remains advisory. Missing projection context
                        # cannot form a second hidden hard selector. Downstream
                        # canonical handoff/Builder/PreSend/Execution gates remain hard.
                        unverifiable += 1
                        fs2 = dict(fs)
                        fs2["v702_selection_projection_status"] = "UNVERIFIABLE_ADVISORY"
                        fs2["v702_selection_projection_reason"] = "selection_projection_snapshot_missing"
                        fs2["v702_selection_blended_score"] = float(r.composite)
                        prepared.append(replace(r, candidate=replace(c, features_snapshot=fs2)))
                        STATS["v702_selection_projection_unverifiable_advisory"] = int(STATS.get("v702_selection_projection_unverifiable_advisory", 0) or 0) + 1
                        continue
                    snap.setdefault("symbol", sym)
                    proj = _v702_projected_canonical_score(c, snap)
                    fs2 = dict(fs)
                    fs2["v702_selection_projection_floor"] = floor
                    fs2["v702_selection_projection_source"] = "EXACT_CLOSED_SNAPSHOT_ADVISORY"
                    if proj is None or not math.isfinite(float(proj)):
                        unverifiable += 1
                        fs2["v702_selection_projection_status"] = "UNVERIFIABLE_ADVISORY"
                        fs2["v702_selection_blended_score"] = float(r.composite)
                    else:
                        proj_f = float(proj)
                        fs2["v702_projected_canonical_score"] = proj_f
                        # Only a complete, fresh, same-candidate and same-cycle
                        # projection may be used as a hard pre-builder rejection or
                        # as an ordering signal. An incomplete estimate contains
                        # defaults for unknown factors and must not displace the
                        # canonical arbiter order.
                        _disp = _v702_r5_projection_disposition(
                            c, snap, proj_f, float(r.composite), blend_weight=blend_w
                        )
                        fs2["v702_selection_projection_status"] = str(_disp.get("status", "INCOMPLETE_KEEP_CANONICAL_RANK"))
                        fs2["v702_selection_projection_complete"] = bool(_disp.get("complete", False))
                        fs2["v702_selection_builder_score_floor"] = _disp.get("floor")
                        fs2["v702_selection_blended_score"] = float(_disp.get("ranking_score", r.composite))
                        if bool(_disp.get("hard_block", False)):
                            advisory_below += 1
                            blocked += 1
                            STATS["v702_selection_exact_underfloor_blocks"] = int(STATS.get("v702_selection_exact_underfloor_blocks", 0) or 0) + 1
                            STATS["v702_selection_projected_advisory_below_floor"] = int(STATS.get("v702_selection_projected_advisory_below_floor", 0) or 0) + 1
                            _v702_note_selection_projection_reject(
                                sym,
                                f"exact_builder_projection_below_floor:{proj_f:.1f}<{float(_disp.get('floor')):.1f}",
                                score=float(r.composite), projected=proj_f,
                                floor=float(_disp.get("floor")), source="select",
                            )
                            continue
                        if not bool(_disp.get("complete", False)):
                            unverifiable += 1
                            fs2["v702_selection_projection_reason"] = "projection_incomplete_or_stale_keeps_canonical_rank"
                        elif proj_f < floor:
                            # Advisory threshold is distinct from the hard Builder
                            # floor; a passing exact score may still be below 66 only
                            # if configuration has changed, so this remains telemetry.
                            advisory_below += 1
                            STATS["v702_selection_projected_advisory_below_floor"] = int(STATS.get("v702_selection_projected_advisory_below_floor", 0) or 0) + 1
                    c2 = replace(c, features_snapshot=fs2)
                    prepared.append(replace(r, candidate=c2))
                    seen += 1
                except Exception as _sel_exc:
                    blocked += 1
                    STATS["v702_selection_projection_errors"] = int(STATS.get("v702_selection_projection_errors", 0) or 0) + 1
                    _v702_note_selection_projection_reject(
                        str(getattr(getattr(r, "candidate", None), "symbol", "")),
                        f"selection_projection_error:{type(_sel_exc).__name__}", source="select"
                    )
            # Projection influences ordering when available, but never becomes a
            # new hard permission boundary. Existing family/correlation caps and
            # the canonical arbiter remain the single selection authority.
            prepared.sort(key=lambda x: float((getattr(x.candidate, "features_snapshot", {}) or {}).get("v702_selection_blended_score", x.composite)), reverse=True)
            STATS["v702_selection_projected_seen"] = seen
            STATS["v702_selection_projected_rejected"] = blocked
            STATS["v702_selection_projected_pass"] = seen
            STATS["v702_selection_projected_complete_underfloor"] = int(STATS.get("v702_selection_exact_underfloor_blocks", 0) or 0)
            STATS["v702_selection_projected_advisory_below_floor"] = advisory_below
            STATS["v702_selection_projected_unverifiable_advisory"] = unverifiable
            STATS["v702_selection_snapshot_fallback_used"] = 0
            _V702_SELECTION_BLEND_CTX["active"] = True
            try:
                return _v702_orig_arbiter_select(prepared, max_winners)
            finally:
                _V702_SELECTION_BLEND_CTX["active"] = False
        _v702_arbiter_select_r5._v702_r5_wrapped = True
        GlobalOpportunityArbiter.select = _v702_arbiter_select_r5
        STATS["v702_r5_selection_alignment_wired"] = True
except Exception as _v702_sel_exc:
    STATS["v702_r5_selection_alignment_wired"] = False
    STATS["v702_r5_selection_alignment_error"] = f"{type(_v702_sel_exc).__name__}:{_v702_sel_exc}"


