# V702 R11 — final production closure self-test for the fixes applied in this audit.
def _v702_r11_production_closure_self_test() -> Dict[str, Any]:
    checks: Dict[str, Any] = {}
    details: Dict[str, Any] = {}
    old_active = dict(_V702_ACTIVE_SELECTION_SNAPSHOTS)
    old_events = list(getattr(V669RejectionLedger, "_events", ()))
    agg = globals().get("_V662RejectionAggregator")
    old_agg_rows = dict(getattr(agg, "_rows", {}) or {}) if agg is not None else {}
    old_agg_recent = dict(getattr(agg, "_recent_notified", {}) or {}) if agg is not None else {}
    old_agg_total = getattr(agg, "_total", 0) if agg is not None else 0
    old_agg_suppressed = getattr(agg, "_suppressed", 0) if agg is not None else 0
    old_armed = bool(globals().get("_V699_LIVE_EPOCH_ARMED", False))
    old_epoch = globals().get("_V699_LIVE_TELEMETRY_EPOCH", 0.0)
    wd_errors = list(getattr(ExchangeWatchdog, "_errors", ()) or ())
    wd_until = float(getattr(ExchangeWatchdog, "_tripped_until", 0.0) or 0.0)
    wd_reason = str(getattr(ExchangeWatchdog, "_last_reason", "") or "")
    stats_backup = dict(STATS)
    try:
        # Candidate immutability: projection must never mutate the caller-owned snapshot.
        c = StrategyCandidate(
            engine_id="r11", symbol="R11-IMMUTABLE/USDT", side="long", generated_at_ms=1,
            entry_ref=100.0, sl_price=99.0, tp1_rr=1.5, tp2_rr=2.5, tp3_rr=4.0,
            engine_score=0.90, rr_ratio=2.0, liquidity_score=0.9, regime_fit=0.9,
            family="PULLBACK", zone_ref=99.5,
            features_snapshot={"strategy_mode":"PULLBACK","strategy_style":"SCALP","tier":"MID",
                               "htf_strength":90.0,"htf_state":"STRICT_BULLISH","htf_pass":True,
                               "structure_confidence":82.0,"retest_quality_score":80.0,"volume_ratio":1.2,
                               "rs_5m":0.012,"snapshot_id":"R11","candle_ts":"R11"},
            strategy_mode="PULLBACK", strategy_style="SCALP", market_phase="TREND",
            macro_regime="BULLISH", local_regime="BULLISH", bearish_severity="NORMAL",
            timeframe_profile="15M_5M", quality_grade="A"
        )
        before = dict(c.features_snapshot)
        snap = {"symbol": c.symbol, "htf_strength":90.0,"htf_state":"STRICT_BULLISH","htf_pass":True,
                "tier":"MID","snapshot_id":"R11","closed_candle_ts":"R11"}
        _ = _v702_projected_canonical_score(c, snap)
        checks["projection_does_not_mutate_candidate"] = before == dict(c.features_snapshot)

        # Aggregator semantics: self-test events are never operator-visible after LIVE arm;
        # first admitted event is not counted as suppressed, while a duplicate is.
        if agg is not None:
            agg._rows.clear(); agg._recent_notified.clear(); agg._total=0; agg._suppressed=0
            globals()["_V699_LIVE_EPOCH_ARMED"] = True
            globals()["_V699_LIVE_TELEMETRY_EPOCH"] = WALL_NOW() - 1.0
            blocked = bool(agg.add("R11-SELFTEST/USDT", reason="selftest.foo", stage="selftest"))
            admitted = bool(agg.add("R11-LIVE/USDT", reason="structure.r11", stage="prequal"))
            suppressed_before = int(getattr(agg, "_suppressed", 0) or 0)
            duplicate = bool(agg.add("R11-LIVE/USDT", reason="structure.r11", stage="prequal"))
            suppressed_after = int(getattr(agg, "_suppressed", 0) or 0)
            # Duplicate events within the same batch are aggregated (not transport-suppressed).
            # Suppression applies only after a prior notification has been flushed.
            checks["live_aggregator_blocks_postarm_selftest"] = not blocked
            checks["live_aggregator_admits_real_rejection"] = admitted
            checks["accepted_event_not_marked_suppressed"] = suppressed_before == 0
            checks["same_batch_duplicate_aggregates_without_suppression"] = bool(duplicate) and suppressed_after == 0 and int(next(iter(agg._rows.values())).get("count",0) or 0) == 2
            details["aggregator"] = {"blocked_selftest":blocked,"admitted":admitted,"suppressed_before":suppressed_before,"duplicate_return":duplicate,"suppressed_after":suppressed_after}

        # Watchdog epoch closure: synthetic/boot errors are quarantined before LIVE starts.
        ExchangeWatchdog._errors.clear()
        ExchangeWatchdog._errors.extend([MONO_NOW() - 1.0] * 5)
        ExchangeWatchdog._tripped_until = 0.0
        ExchangeWatchdog._last_reason = "boot_selftest"
        globals()["_V699_LIVE_EPOCH_ARMED"] = False
        _old_synth_arm = bool(globals().get("_V702_SYNTHETIC_RUNTIME_ARM", False))
        globals()["_V702_SYNTHETIC_RUNTIME_ARM"] = True
        try:
            _v699_arm_live_epoch()
        finally:
            globals()["_V702_SYNTHETIC_RUNTIME_ARM"] = _old_synth_arm
        checks["watchdog_boot_errors_cleared_at_live_arm"] = len(getattr(ExchangeWatchdog, "_errors", ()) or ()) == 0
        checks["watchdog_live_arm_not_left_tripped"] = not ExchangeWatchdog.is_tripped()
        details["watchdog_errors_after_arm"] = len(getattr(ExchangeWatchdog, "_errors", ()) or ())

        # Canonical operator label closure.
        try:
            import inspect as _r11_inspect
            _agg_src = _v702_runtime_function_source(_V662RejectionAggregator.snapshot_and_flush) if agg is not None else ""
            checks["rejection_batch_header_is_evaluation_scoped"] = "Rejected evaluations:" in _agg_src and "Notification groups:" in _agg_src
            checks["rejection_batch_header_no_ambiguous_rejections_label"] = "| Rejections: <b>" not in _agg_src
        except Exception:
            checks["rejection_batch_header_is_evaluation_scoped"] = False
            checks["rejection_batch_header_no_ambiguous_rejections_label"] = False
    except Exception as exc:
        checks["exception"] = False
        details["exception"] = f"{type(exc).__name__}:{exc}"
    finally:
        _V702_ACTIVE_SELECTION_SNAPSHOTS.clear(); _V702_ACTIVE_SELECTION_SNAPSHOTS.update(old_active)
        V669RejectionLedger._events.clear(); V669RejectionLedger._events.extend(old_events)
        if agg is not None:
            agg._rows.clear(); agg._rows.update(old_agg_rows)
            agg._recent_notified.clear(); agg._recent_notified.update(old_agg_recent)
            agg._total = old_agg_total
            agg._suppressed = old_agg_suppressed
        globals()["_V699_LIVE_EPOCH_ARMED"] = old_armed
        globals()["_V699_LIVE_TELEMETRY_EPOCH"] = old_epoch
        ExchangeWatchdog._errors.clear(); ExchangeWatchdog._errors.extend(wd_errors)
        ExchangeWatchdog._tripped_until = wd_until
        ExchangeWatchdog._last_reason = wd_reason
        STATS.clear(); STATS.update(stats_backup)
    return {"pass": bool(checks) and all(bool(v) for k,v in checks.items() if k != "exception"), "checks": checks, "details": details}

def _v702_r12_live_route_coherence_self_test() -> Dict[str, Any]:
    """Close runtime-route coherence issues exposed by the latest live log."""
    checks: Dict[str, Any] = {}
    details: Dict[str, Any] = {}
