# =============================================================================
# V703 FINAL CANONICAL — ALL-STRATEGY REACHABILITY + BOUNDED FAIR ROTATION
# =============================================================================
# This is the terminal R13 production closure requested from the live log.
# Goals:
#   1) Prove every registered production engine is invoked on the active
#      global snapshot rather than inferred "enabled" from registry metadata.
#   2) Keep rare strategies from disappearing at per-symbol retention solely
#      because PULLBACK fills the first five ranking slots.
#   3) Add a tiny, deterministic strategy-debt tie preference ONLY among
#      already-prequalified, already-above-floor candidates. No hard gate is
#      bypassed and no below-floor candidate can be rescued by diversity.
#   4) Keep all execution authority exactly where it already is: canonical
#      SignalBuilder -> PreSend -> Balance/TruthSeal/Exposure/Liquidity/Spread/
#      Fee/RR/SL/Execution.
# =============================================================================
V703_FINAL_CANONICAL_RELEASE = V702_FINAL_CANONICAL_RELEASE
V703_FINAL_RUNTIME_IDENTITY = V702_FINAL_RUNTIME_IDENTITY
V703_FINAL_AUDIT_REVISION = "R14-FINAL-CANONICAL-PRODUCTION-AUDIT-IMMUTABILITY-COVERAGE-KNOWLEDGE-DEDUP"
V703_MTF_D1_DISCOVERY_LANE_INSTALLED = True
V703_MTF_D1_NO_PB_PREFILTER = True

CONFIG.update({
    "V703_FINAL_CANONICAL_RELEASE": V703_FINAL_CANONICAL_RELEASE,
    "V703_FINAL_AUDIT_REVISION": V703_FINAL_AUDIT_REVISION,
    "V703_MTF_D1_LANE_ENABLE": True,
    "V703_MTF_D1_LANE_N": 24,
    "V703_STRATEGY_COVERAGE_ENABLE": True,
    "V703_STRATEGY_COVERAGE_TOP_N": 22,
    "V703_STRATEGY_FAIR_ROTATION_ENABLE": True,
    "V703_STRATEGY_FAIR_ROTATION_BONUS_MAX": 0.012,
    "V703_STRATEGY_FAIR_ROTATION_MAX_GAP": 0.040,
    "V703_STRATEGY_FAIR_ROTATION_DEBT_CAP": 3,
    "V703_LOCAL_RETENTION_PER_SYMBOL": 6,
})
CONFIG["V702_CANONICAL_AUDIT_REVISION"] = V703_FINAL_AUDIT_REVISION
STATS["v703_final_canonical_revision"] = V703_FINAL_AUDIT_REVISION

_V703_COVERAGE = {}
_V703_COVERAGE_CURRENT_CYCLE = 0
_V703_STRATEGY_DEBT = defaultdict(int)
_V703_CURRENT_ARBITRATION_TOP = None


def _v703_strategy_key(candidate_or_engine):
    try:
        return str(
            getattr(candidate_or_engine, "strategy_mode", "")
            or getattr(candidate_or_engine, "family", "")
            or getattr(candidate_or_engine, "engine_id", "")
            or "UNKNOWN"
        ).upper()
    except Exception:
        return "UNKNOWN"


def _v703_cycle_id_from_snapshot(snapshot=None):
    try:
        if isinstance(snapshot, dict):
            x = int(snapshot.get("cycle_id", 0) or 0)
            if x:
                return x
        return int(
            globals().get("_V517_ACTIVE_CYCLE_ID", 0)
            or STATS.get("v681_runtime_cycle_id", 0)
            or STATS.get("v516_cycle_id", 0)
            or 0
        )
    except Exception:
        return 0


def _v703_prepare_cycle_coverage(snapshot=None):
    global _V703_COVERAGE_CURRENT_CYCLE
    cid = _v703_cycle_id_from_snapshot(snapshot)
    if cid != _V703_COVERAGE_CURRENT_CYCLE:
        _V703_COVERAGE_CURRENT_CYCLE = cid
        # R14: coverage is cycle-scoped; stale/legacy IDs must not leak into the
        # next epoch and inflate INV=.../expected telemetry.
        _V703_COVERAGE.clear()
        for e in _MSE_ENGINES:
            eid = str(getattr(e, "engine_id", "UNKNOWN") or "UNKNOWN")
            _V703_COVERAGE[eid] = {
                "engine": e.__name__, "enabled": bool(e.enabled()),
                "invoked": 0, "generated": 0, "no_match": 0,
                "runtime_errors": 0, "cycle_id": cid,
            }
    return cid


# Wrap the final runtime invocation point once. This is coverage telemetry, not
# a second engine router.
if not bool(globals().get("_V703_RUN_ENGINE_WRAPPED", False)):
    _V703_ORIG_RUN_ENGINE_SAFE = MultiStrategyEngine._run_engine_safe

    def _v703_run_engine_safe(engine_cls, snapshot):
        _coverage_enabled = bool(CONFIG.get("V703_STRATEGY_COVERAGE_ENABLE", True))
        _coverage_eid = str(getattr(engine_cls, "engine_id", engine_cls.__name__) or engine_cls.__name__)
        _coverage_before_err = int(STATS.get(f"mse_engine_exception.{_coverage_eid}", 0) or 0)
        row = None
        if _coverage_enabled:
            _v703_prepare_cycle_coverage(snapshot)
            row = _V703_COVERAGE.setdefault(_coverage_eid, {
                "engine": engine_cls.__name__, "enabled": bool(engine_cls.enabled()),
                "invoked": 0, "generated": 0, "no_match": 0,
                "runtime_errors": 0, "cycle_id": _V703_COVERAGE_CURRENT_CYCLE,
            })
            row["invoked"] = int(row.get("invoked", 0) or 0) + 1
        try:
            out = _V703_ORIG_RUN_ENGINE_SAFE(engine_cls, snapshot)
        except Exception:
            if _coverage_enabled and row is not None:
                row["runtime_errors"] = int(row.get("runtime_errors", 0) or 0) + 1
            raise
        if _coverage_enabled and row is not None:
            # The canonical V699 engine boundary intentionally isolates exceptions
            # and returns an empty list. Attribute those caught exceptions from the
            # engine-exception counter delta so coverage cannot falsely report ERR=0.
            _coverage_after_err = int(STATS.get(f"mse_engine_exception.{_coverage_eid}", 0) or 0)
            _coverage_err_delta = max(0, _coverage_after_err - _coverage_before_err)
            if _coverage_err_delta:
                row["runtime_errors"] = int(row.get("runtime_errors", 0) or 0) + _coverage_err_delta
            n = len(out or []) if isinstance(out, list) else 0
            row["generated"] = int(row.get("generated", 0) or 0) + n
            if n == 0:
                row["no_match"] = int(row.get("no_match", 0) or 0) + 1
        return out

    MultiStrategyEngine._run_engine_safe = staticmethod(_v703_run_engine_safe)
    globals()["_V703_RUN_ENGINE_WRAPPED"] = True


def _v703_coverage_snapshot(top_n=None):
    current_ids = {str(getattr(e, "engine_id", "UNKNOWN") or "UNKNOWN") for e in _MSE_ENGINES}
    rows = [r for eid, r in _V703_COVERAGE.items() if str(eid) in current_ids]
    rows.sort(key=lambda r: (int(r.get("generated", 0)), int(r.get("invoked", 0)), str(r.get("engine", ""))), reverse=True)
    expected = len(_MSE_ENGINES)
    invoked = sum(1 for r in rows if int(r.get("invoked", 0) or 0) > 0)
    generated_engines = sum(1 for r in rows if int(r.get("generated", 0) or 0) > 0)
    runtime_errors = sum(int(r.get("runtime_errors", 0) or 0) for r in rows)
    return {
        "cycle_id": int(_V703_COVERAGE_CURRENT_CYCLE),
        "expected_engines": expected,
        "invoked_engines": invoked,
        "generated_engines": generated_engines,
        "runtime_errors": runtime_errors,
        "all_expected_invoked": bool(expected == invoked),
        "all_enabled": bool(all(bool(e.enabled()) for e in _MSE_ENGINES)),
        "engines": rows[:int(top_n or CONFIG.get("V703_STRATEGY_COVERAGE_TOP_N", 22))],
    }


# Increase production local retention from the old 5 to a still-bounded 6.
# This is deliberately below the 24 global cycle cap and does not alter any
# canonical hard gate.
try:
    CONFIG["V4513_ELASTIC_LOCAL_RETENTION_MAX"] = max(
        int(CONFIG.get("V4513_ELASTIC_LOCAL_RETENTION_MAX", 5) or 5),
        min(6, int(CONFIG.get("V703_LOCAL_RETENTION_PER_SYMBOL", 6) or 6)),
    )
except Exception:
    pass


# Strategy-fair ranking overlay. It only adds a small preference when the
# candidate already clears the active global floor and sits within a 0.04 score
# neighborhood of the current best. It therefore cannot turn a weak candidate
# into a trade solely because of "fairness".
if not bool(globals().get("_V703_SCORE_WRAPPED", False)):
    _V703_ORIG_CANDIDATE_SCORE = GlobalOpportunityArbiter._candidate_score

    @staticmethod
    def _v703_candidate_score(r):
        base = float(_V703_ORIG_CANDIDATE_SCORE(r))
        if not bool(CONFIG.get("V703_STRATEGY_FAIR_ROTATION_ENABLE", True)):
            return base
        try:
            top = _V703_CURRENT_ARBITRATION_TOP
            if top is None:
                return base
            floor = float(GlobalOpportunityArbiter._effective_min_score())
            if base < floor:
                return base
            if base < float(top) - float(CONFIG.get("V703_STRATEGY_FAIR_ROTATION_MAX_GAP", 0.04)):
                return base
            key = _v703_strategy_key(r.candidate)
            debt = int(_V703_STRATEGY_DEBT.get(key, 0) or 0)
            if debt <= 0:
                return base
            cap = max(0, int(CONFIG.get("V703_STRATEGY_FAIR_ROTATION_DEBT_CAP", 3) or 3))
            bonus_max = min(0.012, max(0.0, float(CONFIG.get("V703_STRATEGY_FAIR_ROTATION_BONUS_MAX", 0.012))))
            bonus = bonus_max * min(max(0, debt), cap) / max(1, cap)
            if bonus > 0:
                STATS["v703_strategy_fairness_bonus_applied"] = int(STATS.get("v703_strategy_fairness_bonus_applied", 0) or 0) + 1
                STATS[f"v703_strategy_fairness_bonus.{key}"] = int(STATS.get(f"v703_strategy_fairness_bonus.{key}", 0) or 0) + 1
            return min(1.0, base + bonus)
        except Exception:
            return base

    GlobalOpportunityArbiter._candidate_score = _v703_candidate_score
    globals()["_V703_SCORE_WRAPPED"] = True


if not bool(globals().get("_V703_SELECT_WRAPPED", False)):
    _V703_ORIG_SELECT = GlobalOpportunityArbiter.select

    @classmethod
    def _v703_select(cls, ranked, max_winners=3):
        global _V703_CURRENT_ARBITRATION_TOP
        try:
            # Compute the top of the SAME candidate pool with the pre-overlay score.
            base_rows = []
            for rr in list(ranked or []):
                try:
                    ok, _why, _age = _v455_candidate_freshness_ok(getattr(rr.candidate, "generated_at_ms", None))
                    if ok:
                        base_rows.append(float(_V703_ORIG_CANDIDATE_SCORE(rr)))
                except Exception:
                    continue
            _V703_CURRENT_ARBITRATION_TOP = max(base_rows) if base_rows else None
            result = _V703_ORIG_SELECT.__func__(cls, ranked, max_winners)
        finally:
            _V703_CURRENT_ARBITRATION_TOP = None
        try:
            # Debt is based on strategy candidates that reached the already-
            # prequalified arbitration pool and cleared the active global floor.
            floor = float(cls._effective_min_score())
            present = set()
            for rr in list(ranked or []):
                try:
                    g = float(_V703_ORIG_CANDIDATE_SCORE(rr))
                    if g >= floor:
                        present.add(_v703_strategy_key(rr.candidate))
                except Exception:
                    pass
            selected = {_v703_strategy_key(rr.candidate) for rr in (result or [])}
            cap = max(1, int(CONFIG.get("V703_STRATEGY_FAIR_ROTATION_DEBT_CAP", 3) or 3))
            for key in present:
                if key in selected:
                    _V703_STRATEGY_DEBT[key] = max(0, int(_V703_STRATEGY_DEBT.get(key, 0) or 0) - 2)
                else:
                    _V703_STRATEGY_DEBT[key] = min(cap, int(_V703_STRATEGY_DEBT.get(key, 0) or 0) + 1)
            for key in set(_V703_STRATEGY_DEBT) - present:
                _V703_STRATEGY_DEBT[key] = max(0, int(_V703_STRATEGY_DEBT.get(key, 0) or 0) - 1)
            STATS["v703_strategy_debt_top"] = sorted(
                ((k, int(v)) for k, v in _V703_STRATEGY_DEBT.items() if int(v) > 0),
                key=lambda x: (-x[1], x[0]),
            )[:10]
            STATS["v703_strategy_present_count"] = len(present)
            STATS["v703_strategy_selected_count"] = len(selected)
            STATS["v703_strategy_coverage_last"] = _v703_coverage_snapshot()
        except Exception:
            pass
        return result

    GlobalOpportunityArbiter.select = _v703_select
    globals()["_V703_SELECT_WRAPPED"] = True


# Terminal validation / self-test for the new closure.
def _v703_final_canonical_self_test():
    checks = {}
    saved = {
        "V703_MTF_D1_LANE_ENABLE": CONFIG.get("V703_MTF_D1_LANE_ENABLE"),
        "V703_STRATEGY_FAIR_ROTATION_ENABLE": CONFIG.get("V703_STRATEGY_FAIR_ROTATION_ENABLE"),
        "V703_LOCAL_RETENTION": CONFIG.get("V4513_ELASTIC_LOCAL_RETENTION_MAX"),
    }
    try:
        checks["identity"] = V703_FINAL_AUDIT_REVISION.startswith("R14-FINAL-CANONICAL")
        checks["hard_long_only_spot"] = bool(CONFIG.get("MSE_LONG_ONLY", True)) and str(CONFIG.get("TRADING_MODE", "SPOT")).upper() != "FUTURES"
        checks["hard_forbidden"] = all(x in V702_HARD_FORBIDDEN_BASES for x in ("CAKE", "PUMP", "BNB", "AERO", "ETHFI"))
        checks["engines_17"] = len(_MSE_ENGINES) == 17 and len(_V702_LIVE_ENGINE_CLASSES) == 17
        checks["all_enabled"] = all(bool(e.enabled()) for e in _MSE_ENGINES)
        checks["coverage_wrapper"] = bool(globals().get("_V703_RUN_ENGINE_WRAPPED", False))
        checks["fair_score_wrapper"] = bool(globals().get("_V703_SCORE_WRAPPED", False))
        checks["fair_select_wrapper"] = bool(globals().get("_V703_SELECT_WRAPPED", False))
        checks["mtf_independent_lane_source"] = bool(globals().get("V703_MTF_D1_DISCOVERY_LANE_INSTALLED", False))
        checks["mtf_no_pb_prefilter_source"] = bool(globals().get("V703_MTF_D1_NO_PB_PREFILTER", False))
        checks["local_retention_bounded"] = 5 <= int(CONFIG.get("V4513_ELASTIC_LOCAL_RETENTION_MAX", 5) or 5) <= 6

        # Probe fairness with two already-eligible near-equal candidates.
        global _V703_CURRENT_ARBITRATION_TOP
        _V703_CURRENT_ARBITRATION_TOP = 0.70
        _V703_STRATEGY_DEBT.clear()
        _V703_STRATEGY_DEBT["MEAN_REVERSION"] = 3
        c1 = StrategyCandidate(
            engine_id="r13_pb", symbol="R13-PB/USDT", side="long", generated_at_ms=int(time.time()*1000),
            entry_ref=100.0, sl_price=99.0, tp1_rr=1.0, tp2_rr=2.0, tp3_rr=4.0,
            engine_score=0.90, rr_ratio=2.0, liquidity_score=0.9, regime_fit=0.9,
            family="PULLBACK", zone_ref=99.0,
            features_snapshot={"execution_quality":0.9,"structure_quality":0.9,"volume_quality":0.9,"rs_quality":0.9,"htf_alignment":0.9},
            strategy_mode="PULLBACK", strategy_style="SCALP", market_phase="TREND",
            macro_regime="BULLISH", local_regime="LOCAL_BULLISH", bearish_severity="NORMAL", timeframe_profile="15M_5M", quality_grade="A",
        )
        c2 = replace(c1, engine_id="r13_mr", symbol="R13-MR/USDT", family="MEAN_REVERSION", strategy_mode="MEAN_REVERSION")
        r1 = RankedCandidate(c1, 0.70, 101.0, 102.0, 104.0)
        r2 = RankedCandidate(c2, 0.70, 101.0, 102.0, 104.0)
        s_pb = float(_V703_ORIG_CANDIDATE_SCORE(r1))
        s_mr = float(GlobalOpportunityArbiter._candidate_score(r2))
        checks["fairness_bonus_bounded"] = (0.0 <= s_mr - s_pb <= 0.012000001)
        checks["fairness_near_top_only"] = abs(s_mr - s_pb) <= 0.012000001
        # Below-floor candidate cannot be boosted into eligibility.
        _V703_CURRENT_ARBITRATION_TOP = float(GlobalOpportunityArbiter._effective_min_score())
        weak = replace(c2, engine_score=0.30)
        wr = RankedCandidate(weak, 0.30, 100.3, 100.6, 101.2)
        base_weak = float(_V703_ORIG_CANDIDATE_SCORE(wr))
        fair_weak = float(GlobalOpportunityArbiter._candidate_score(wr))
        checks["below_floor_never_rescued"] = fair_weak <= base_weak + 1e-12

        # Coverage fixture proves the wrapper records invocation independently
        # from whether a strategy matches.
        fake_snap = {"symbol":"R14-COVERAGE/USDT", "cycle_id": 991403}
        before = dict(_V703_COVERAGE)
        before_cycle = int(_V703_COVERAGE_CURRENT_CYCLE)
        try:
            _v703_prepare_cycle_coverage(fake_snap)
            checks["coverage_registry_exact"] = len(_V703_COVERAGE) == 17
            checks["coverage_fields"] = all(set(("invoked","generated","no_match","runtime_errors","enabled")) <= set(v.keys()) for v in _V703_COVERAGE.values())
            current_ids = {str(getattr(e, "engine_id", "UNKNOWN") or "UNKNOWN") for e in _MSE_ENGINES}
            checks["coverage_ids_current_registry"] = set(_V703_COVERAGE.keys()) == current_ids
            _V703_COVERAGE["R13-PHANTOM-LEGACY"] = {"engine":"legacy", "enabled":True, "invoked":1, "generated":1, "no_match":0, "runtime_errors":0, "cycle_id":991403}
            _v703_prepare_cycle_coverage({"symbol":"R14-COVERAGE-NEXT/USDT", "cycle_id": 991404})
            checks["coverage_rollover_clears_stale"] = "R13-PHANTOM-LEGACY" not in _V703_COVERAGE and set(_V703_COVERAGE.keys()) == current_ids
        finally:
            _V703_COVERAGE.clear(); _V703_COVERAGE.update(before)
            globals()["_V703_COVERAGE_CURRENT_CYCLE"] = before_cycle
    except Exception as exc:
        checks["exception"] = False
        STATS["v703_final_canonical_self_test_error"] = f"{type(exc).__name__}:{exc}"
    finally:
        _V703_CURRENT_ARBITRATION_TOP = None
        for k,v in saved.items():
            if k == "V703_LOCAL_RETENTION":
                CONFIG["V4513_ELASTIC_LOCAL_RETENTION_MAX"] = v
            else:
                CONFIG[k] = v
        _V703_STRATEGY_DEBT.clear()
    return {"pass": bool(checks) and all(bool(v) for k,v in checks.items() if k != "exception"), "checks": checks}

_V703_FINAL_CANONICAL_SELF_TEST = _v703_final_canonical_self_test()
STATS["v703_final_canonical_self_test"] = _V703_FINAL_CANONICAL_SELF_TEST

