def _v704_hard_global_score_floor() -> float:
    """Single fail-closed authority for the live score floor; never below 70."""
    try:
        return max(70.0, float(CONFIG.get("MIN_LIVE_SCORE", 70.0)),
                   float(CONFIG.get("V704_STARVATION_SCORE_RELIEF_FLOOR", 70.0)))
    except Exception:
        return 70.0


def _v704_num(v):
    try:
        x = float(v)
        return x if math.isfinite(x) else None
    except Exception:
        return None


def _v704_no_send_age_sources() -> Dict[str, float]:
    """Return independently computed no-send ages from currently available sources.

    A missing source is omitted; an explicitly present zero remains evidence of
    a recent send/reset. Callers use the minimum available age so one stale
    counter can never keep starvation relief armed after a newer send.
    """
    ages: Dict[str, float] = {}
    try:
        now_wall = float(WALL_NOW())
    except Exception:
        now_wall = 0.0
    try:
        now_mono = float(MONO_NOW())
    except Exception:
        now_mono = 0.0
    try:
        ts = _v704_num(STATS.get("last_signal_sent_ts"))
        if ts is not None and ts > 0 and now_wall > 0:
            ages["last_signal_sent_ts_wall"] = max(0.0, now_wall - ts)
    except Exception:
        pass
    try:
        ts = _v704_num(getattr(V422StarvationAlerter, "_last_send_ts", 0.0))
        if ts is not None and ts > 0 and now_mono > 0:
            ages["v422_last_send_mono"] = max(0.0, now_mono - ts)
    except Exception:
        pass
    try:
        if "v45_no_send_sec" in STATS:
            nfs = _v704_num(STATS.get("v45_no_send_sec"))
            if nfs is not None and nfs >= 0:
                ages["v45_no_send_sec"] = float(nfs)
    except Exception:
        pass
    return ages


def _v704_no_send_age_sec() -> float:
    ages = _v704_no_send_age_sources()
    return min(ages.values()) if ages else 0.0


def _v704_market_hazard() -> bool:
    try:
        if bool(KillSwitch.is_active()) or bool(ExchangeWatchdog.is_tripped()):
            return True
    except Exception:
        return True
    try:
        truth = _v699_truthful_starvation_snapshot() if callable(globals().get("_v699_truthful_starvation_snapshot")) else {}
        root = str(truth.get("root", "") or "").upper()
        detail = str(truth.get("detail", "") or "").upper()
        if root in {"FEE", "PRE_SEND", "EXECUTION", "SYSTEM"}:
            return True
        if "CRASH" in detail or "EXTREME" in detail:
            return True
        reg = str(STATS.get("regime", STATS.get("v684_regime", "")) or "").upper()
        sev = str(STATS.get("severity", STATS.get("bearish_severity", "")) or "").upper()
        if "CRASH" in sev or (reg == "BEARISH" and "NON_BEARISH" not in sev):
            return True
    except Exception:
        return True
    return False


def _v704_starvation_state() -> Dict[str, Any]:
    try:
        ranked = int(STATS.get("v681_runtime_cycle_ranked", 0) or 0)
        selected = int(STATS.get("v681_runtime_cycle_selected", 0) or 0)
        root = str(STATS.get("v699_truth_root", "") or STATS.get("v425_starvation_mode", "") or "NONE").upper()
        if callable(globals().get("_v699_truthful_starvation_snapshot")):
            truth = _v699_truthful_starvation_snapshot()
            root = str(truth.get("root", root) or root).upper()
        age_sources = _v704_no_send_age_sources()
        age = min(age_sources.values()) if age_sources else 0.0
        age_floor = float(CONFIG.get("V704_STARVATION_SCORE_RELIEF_MIN_NO_SEND_SEC", 3600.0))
        activity_floor = int(CONFIG.get("V704_STARVATION_MIN_RANKED_OR_SELECTED", 1))
        if age < age_floor:
            reason = "no_send_window_not_reached"
        elif ranked < activity_floor and selected < activity_floor:
            reason = "no_ranked_or_selected_activity"
        elif root not in {"SCORE", "STRUCTURE", "POLICY", "HTF"}:
            reason = "root_not_eligible"
        elif _v704_market_hazard():
            reason = "market_hazard"
        else:
            reason = "eligible"
        return {
            "age_sec": age, "age_sources_sec": age_sources,
            "age_rule": "MIN_AVAILABLE_SOURCE_AGE_FAIL_CLOSED",
            "ranked": ranked, "selected": selected, "root": root,
            "eligible": reason == "eligible", "eligibility_reason": reason,
        }
    except Exception as exc:
        return {"age_sec":0.0,"age_sources_sec":{},"age_rule":"MIN_AVAILABLE_SOURCE_AGE_FAIL_CLOSED",
                "ranked":0,"selected":0,"root":"UNKNOWN","eligible":False,
                "eligibility_reason":f"state_error:{type(exc).__name__}"}


def _v704_starvation_score_floor_override(opp: Any, score: float, elite_floor: float):
    """Return (applied, metadata). Hard gates have already run at this point.

    The override is intentionally a single bounded score-floor adjustment. It
    does not touch structure/HTF/liquidity/fee/SL/TP/execution contracts and is
    only available after prolonged live starvation with actual ranked/selected
    candidates in the current cycle.
    """
    try:
        meta = _v704_starvation_state()
        fam = str((opp or {}).get("family", "") or (opp or {}).get("strategy_mode", "") or "").upper()
        hard_global = _v704_hard_global_score_floor()
        current = float(score)
        original = float(elite_floor)
        if not bool(CONFIG.get("V704_STARVATION_SCORE_RELIEF_ENABLE", True)) or not meta.get("eligible"):
            return False, {"applied":False,"family":fam,"age_sec":meta.get("age_sec",0.0),"age_sources_sec":meta.get("age_sources_sec",{}),"root":meta.get("root","NONE"),"eligibility_reason":meta.get("eligibility_reason","disabled_or_ineligible"),"effective_floor":original}
        if current < hard_global:
            return False, {"applied":False,"reason":"score_below_hard_global_floor","family":fam,"age_sec":meta.get("age_sec",0.0),"effective_floor":original,"global_floor":hard_global}
        # The only allowed relief is from a stricter secondary elite floor down
        # to the canonical global live floor. This intentionally equals 70 when
        # the configured hard minimum is 70; it is not permission to trade <70.
        effective = hard_global if original > hard_global else max(original, hard_global)
        return True, {
            "applied": True, "family": fam, "root": meta.get("root","NONE"),
            "age_sec": round(float(meta.get("age_sec",0.0)),3),
            "age_sources_sec": dict(meta.get("age_sources_sec",{})),
            "eligibility_reason": meta.get("eligibility_reason","eligible"),
            "ranked": int(meta.get("ranked",0) or 0), "selected": int(meta.get("selected",0) or 0),
            "original_floor": original, "effective_floor": effective,
            "global_floor": hard_global,
        }
    except Exception as exc:
        return False, {"applied":False,"reason":f"exception:{type(exc).__name__}","effective_floor":float(elite_floor)}


def _v704_starvation_elite_context_advisory(*, opp: Any, score: float, reason: str, ctx: Dict[str,Any]):
    """Allow prolonged-starvation candidates through the SECONDARY elite layer
    only when the underlying canonical facts remain sane and above conservative
    hard floors. Missing facts, tier/spread failures, bearish displacement,
    fee/economic failures, and unknown reasons remain hard rejects."""
    try:
        if not bool(CONFIG.get("V704_STARVATION_ADVISORY_ENABLE", True)):
            return False, {"reason":"disabled"}
        age = _v704_no_send_age_sec()
        if age < float(CONFIG.get("V704_STARVATION_ADVISORY_MIN_NO_SEND_SEC",1800.0)):
            return False, {"reason":"starvation_window_not_reached","age_sec":age}
        state = _v704_starvation_state()
        if not state.get("eligible"):
            return False, {"reason":"state_not_eligible","state":state}
        reason_l = str(reason or "").lower()
        if any(x in reason_l for x in ("unverifiable", "tier_", "spread_", "genuine_bearish", "no_current_reclaim", "anchors", "counteranchors")):
            return False, {"reason":"hard_secondary_contract","failed":reason_l}
        fam = str((opp or {}).get("family", "") or (opp or {}).get("strategy_mode", "") or "").upper()
        sc = _v704_num(score)
        htf = _v704_num(ctx.get("htf"))
        vol = _v704_num(ctx.get("volume"))
        rs = _v704_num(ctx.get("rs_points"))
        structure = _v704_num(ctx.get("structure"))
        retest = _v704_num(ctx.get("retest"))
        setup = _v704_num(ctx.get("setup_quality"))
        chase = _v704_num(ctx.get("chase"))
        vals=(sc,htf,vol,rs,structure,retest,setup,chase)
        if any(v is None for v in vals):
            return False, {"reason":"missing_secondary_fact"}
        # Conservative post-hard-gate floor. These are below the V702 elite
        # thresholds but above the V587/canonical PB floors where applicable.
        if sc < 70.0 or htf < 50.0 or vol < 0.70 or rs < 0.0 or structure < 45.0 or retest < 45.0 or chase > 1.10:
            return False, {"reason":"below_conservative_context_floor","family":fam,"score":sc,"htf":htf,"volume":vol,"rs_points":rs,"structure":structure,"retest":retest,"chase":chase}
        if fam in {"PULLBACK","MTF_PULLBACK"} and setup < 72.0:
            return False, {"reason":"setup_below_v587_floor","setup_quality":setup}
        return True, {
            "reason":"prolonged_starvation_secondary_advisory", "age_sec":round(age,3),
            "root":state.get("root","NONE"), "family":fam, "failed_elite_metric":reason_l,
            "score":sc,"htf":htf,"volume":vol,"rs_points":rs,"structure":structure,
            "retest":retest,"setup_quality":setup,"chase":chase,
        }
    except Exception as exc:
        return False, {"reason":f"exception:{type(exc).__name__}"}


def _v704_validation_diagnostics() -> Dict[str, Any]:
    checks = []
    # Prefer the terminal validation structures; include only explicit failures.
    for key, val in STATS.items():
        if isinstance(val, dict) and key.endswith(("self_test", "validation", "closure_test")):
            if val.get("pass") is False:
                bad = val.get("failed") or [k for k,v in val.get("checks",{}).items() if not bool(v)] if isinstance(val.get("checks"),dict) else []
                if bad:
                    checks.extend([f"{key}:{b}" for b in bad])
    return {"failed_checks": checks[:64]}


def _v704_scrub_boot_validation_state() -> Dict[str,Any]:
    """Clear only synthetic import/self-test residue known to contaminate a
    second validation attempt. Never clears active live positions."""
    changed=[]
    try:
        if not bool(globals().get("_V699_LIVE_EPOCH_ARMED",False)):
            if isinstance(globals().get("_V699_BOOT_REJECTION_BASELINE"),dict):
                globals()["_V699_BOOT_REJECTION_BASELINE"] = {}
                changed.append("boot_rejection_baseline")
            if isinstance(globals().get("_V699_DAILY_BOOT_BASELINE"),dict):
                globals()["_V699_DAILY_BOOT_BASELINE"] = {}
                changed.append("daily_boot_baseline")
            try:
                if not bool(KillSwitch.is_active()):
                    try:
                        ExchangeWatchdog._errors.clear()
                        ExchangeWatchdog._last_reason=""
                        if MONO_NOW() >= float(getattr(ExchangeWatchdog,"_tripped_until",0.0) or 0.0):
                            ExchangeWatchdog._tripped_until=0.0
                        changed.append("watchdog_mock_state")
                    except Exception: pass
            except Exception: pass
    except Exception:
        pass
    return {"changed":changed}


