def _v702_r14_production_audit_self_test():
    checks = {}
    try:
        checks["runtime_identity"] = V702_FINAL_RUNTIME_IDENTITY == "4.5.99-V702-FINAL-CANONICAL"
        checks["spot_long_only"] = bool(CONFIG.get("MSE_LONG_ONLY", True)) and str(CONFIG.get("TRADING_MODE", "SPOT")).upper() == "SPOT"
        checks["forbidden_hard_set"] = all(x in V702_HARD_FORBIDDEN_BASES for x in ("CAKE", "PUMP", "BNB", "AERO", "ETHFI"))
        checks["engine_registry"] = len(_MSE_ENGINES) == 17 and len(_V702_LIVE_ENGINE_CLASSES) == 17 and all(bool(e.enabled()) for e in _MSE_ENGINES)
        checks["coverage_r14"] = bool(STATS.get("v703_final_canonical_self_test", {}).get("checks", {}).get("coverage_rollover_clears_stale", False))
        probe = StrategyCandidate(
            engine_id="r14", symbol="R14-IMM-2/USDT", side="long", generated_at_ms=2,
            entry_ref=100.0, sl_price=99.0, tp1_rr=1.0, tp2_rr=2.0, tp3_rr=4.0,
            engine_score=0.9, rr_ratio=1.0, liquidity_score=0.9, regime_fit=0.9,
            family="PULLBACK", zone_ref=99.0, features_snapshot={"a": 1}
        )
        updated = _v672_set_fs(probe, {"a": 1, "b": 2})
        checks["snapshot_not_mutated_in_place"] = "b" not in probe.features_snapshot and updated.features_snapshot.get("b") == 2 and updated is not probe

        # Alert-ID stability is the invariant behind cross-cycle milestone dedupe.
        generated = 1770000000000
        payload="|".join(["R14-KO/USDT","PULLBACK",str(generated),f"{100.0:.16g}",f"{99.0:.16g}",f"{1.0:.8f}",f"{2.0:.8f}",f"{4.0:.8f}",f"{90.0:.6f}"])
        import hashlib as _r14_hashlib
        aid_a=_r14_hashlib.sha256(payload.encode()).hexdigest()[:40]
        aid_b=_r14_hashlib.sha256(payload.encode()).hexdigest()[:40]
        checks["knowledge_alert_id_cycle_stable"] = aid_a == aid_b and len(aid_a) == 40
        # Runtime images built by Dockerfile commonly contain only the declared
        # runtime entrypoint and dependencies. Dockerfile/source-manifest files
        # are build-context artifacts, not runtime invariants; requiring them
        # here caused a false config_invalid on Railway. Packaging integrity is
        # audited offline, while boot validation checks the artifacts actually
        # required by the running process.
        checks["runtime_entrypoint_present"] = Path(__file__).is_file()
        checks["requirements_present"] = Path(__file__).with_name("requirements.txt").exists()
        checks["canonical_runtime_identity"] = (
            str(V702_FINAL_RUNTIME_IDENTITY) == "4.5.99-V702-FINAL-CANONICAL"
            and str(CANONICAL_RUNTIME_IDENTITY) == "4.5.99-V702-FINAL-CANONICAL"
        )
        checks["build_artifacts_not_runtime_blocking"] = True
    except Exception as exc:
        checks["exception_free"] = False
        STATS["v702_r14_production_audit_self_test_error"] = f"{type(exc).__name__}:{exc}"
    return {"pass": bool(checks) and all(bool(v) for v in checks.values()), "checks": checks}

_V702_R14_PRODUCTION_AUDIT_SELF_TEST = _v702_r14_production_audit_self_test()
STATS["v702_r14_production_audit_self_test"] = _V702_R14_PRODUCTION_AUDIT_SELF_TEST


def _v704_final_production_closure_self_test():
    checks = {}
    try:
        checks["r17_revision"] = V702_R15_FINAL_CANONICAL_REVISION.startswith("R17-FINAL-CANONICAL")
        checks["starvation_relief_not_below_global"] = _v704_hard_global_score_floor() >= 70.0
        checks["elite_advisory_callable"] = callable(globals().get("_v704_starvation_elite_context_advisory"))
        checks["score_override_callable"] = callable(globals().get("_v704_starvation_score_floor_override"))
        checks["validation_scrub_callable"] = callable(globals().get("_v704_scrub_boot_validation_state"))
        checks["spot_long_only"] = str(CONFIG.get("TRADING_MODE","SPOT")).upper() == "SPOT" and bool(CONFIG.get("LONG_ONLY",True)) and not bool(CONFIG.get("ALLOW_SHORT",False))
        checks["economic_floor_intact"] = float(CONFIG.get("MIN_NET_RR_TP1",0.80)) >= 0.80 and float(CONFIG.get("MIN_TP1_TO_FEE_RATIO",2.5)) >= 2.5
        checks["canonical_builder"] = callable(getattr(SignalBuilder,"build_and_route",None))
        # Deterministic starvation probes: exercise the actual R15 helpers
        # without invoking the exchange or any execution path.
        _saved = {k: STATS.get(k) for k in ("v45_no_send_sec","v681_runtime_cycle_ranked","v681_runtime_cycle_selected","last_signal_sent_ts")}
        _saved_truth = globals().get("_v699_truthful_starvation_snapshot")
        _saved_hazard = globals().get("_v704_market_hazard")
        _saved_v422_last_send_ts = getattr(V422StarvationAlerter, "_last_send_ts", None)
        try:
            # Independent source ages are combined with MIN(); isolate all of them
            # so a recent boot/self-test timestamp cannot invalidate this synthetic case.
            STATS.pop("last_signal_sent_ts", None)
            if hasattr(V422StarvationAlerter, "_last_send_ts"):
                V422StarvationAlerter._last_send_ts = 0.0
            STATS["v45_no_send_sec"] = 7200.0
            STATS["v681_runtime_cycle_ranked"] = 3
            STATS["v681_runtime_cycle_selected"] = 2
            globals()["_v699_truthful_starvation_snapshot"] = lambda: {"root":"STRUCTURE","detail":"structure_starvation"}
            globals()["_v704_market_hazard"] = lambda: False
            _probe = _v704_starvation_score_floor_override({"family":"PULLBACK"}, 74.0, 76.0)
            checks["starvation_score_relief_probe"] = bool(_probe[0]) and float(_probe[1].get("effective_floor",0.0)) == 70.0
            _adv = _v704_starvation_elite_context_advisory(opp={"family":"PULLBACK"}, score=70.0, reason="volume_below_floor", ctx={"htf":60.0,"volume":0.80,"rs_points":4.0,"structure":50.0,"retest":50.0,"setup_quality":72.0,"chase":0.80})
            checks["starvation_elite_advisory_probe"] = bool(_adv[0])

            # R17 regression: a stagnant downstream stage must NOT be reported
            # as starved unless its upstream stage advanced in the same tick.
            _ss_saved = {
                "last_val": dict(StarvationGuard._stage_last_val),
                "last_ts": dict(StarvationGuard._stage_last_change_ts),
                "alerts": dict(StarvationGuard._stage_stag_alerts),
                "threshold": CONFIG.get("STARVATION_STAGE_STAGNATION_SEC"),
            }
            _ss_stat_saved = {k: STATS.get(k) for k in (
                "signals_generated", "signals_eligible", "signals_queued", "signals_sent",
                "starvation_stage_stagnation_eligible", "starvation_stage_stagnation_queued",
                "starvation_stage_stagnation_sent",
            )}
            _ss_live_cycle_ready_fn = globals().get("_v702_r23_live_cycle_ready")
            try:
                # R23 correctly suppresses stage-starvation telemetry before the
                # first real LIVE cycle. This R17 probe specifically exercises the
                # underlying same-tick upstream-advance gate, so model a ready epoch
                # here; the separate R23 self-test verifies the boot suppression.
                if callable(_ss_live_cycle_ready_fn):
                    globals()["_v702_r23_live_cycle_ready"] = lambda: True
                CONFIG["STARVATION_STAGE_STAGNATION_SEC"] = 1.0
                _selftest_log_suppress = bool(getattr(StarvationGuard, "_selftest_suppress_stage_logs", False))
                StarvationGuard._selftest_suppress_stage_logs = True
                StarvationGuard._stage_last_val = {"generated":100, "eligible":0, "queued":0, "sent":0}
                StarvationGuard._stage_last_change_ts = {"generated":0.0, "eligible":0.0, "queued":0.0, "sent":0.0}
                StarvationGuard._stage_stag_alerts = {"generated":0, "eligible":0, "queued":0, "sent":0}
                STATS["signals_generated"] = 100
                STATS["signals_eligible"] = 0
                STATS["signals_queued"] = 0
                STATS["signals_sent"] = 0
                StarvationGuard._update_stage_stagnation(2.0)
                no_false = int(StarvationGuard._stage_stag_alerts.get("eligible", 0) or 0) == 0
                STATS["signals_generated"] = 101
                StarvationGuard._update_stage_stagnation(3.0)
                true_alert = int(StarvationGuard._stage_stag_alerts.get("eligible", 0) or 0) >= 1
                checks["starvation_stage_upstream_gate"] = bool(no_false and true_alert)
            finally:
                StarvationGuard._selftest_suppress_stage_logs = _selftest_log_suppress
                StarvationGuard._stage_last_val = _ss_saved["last_val"]
                StarvationGuard._stage_last_change_ts = _ss_saved["last_ts"]
                StarvationGuard._stage_stag_alerts = _ss_saved["alerts"]
                if _ss_saved["threshold"] is None:
                    CONFIG.pop("STARVATION_STAGE_STAGNATION_SEC", None)
                else:
                    CONFIG["STARVATION_STAGE_STAGNATION_SEC"] = _ss_saved["threshold"]
                for _k, _v in _ss_stat_saved.items():
                    if _v is None:
                        STATS.pop(_k, None)
                    else:
                        STATS[_k] = _v
                if callable(_ss_live_cycle_ready_fn):
                    globals()["_v702_r23_live_cycle_ready"] = _ss_live_cycle_ready_fn
        finally:
            for _k, _v in _saved.items():
                if _v is None:
                    STATS.pop(_k, None)
                else:
                    STATS[_k] = _v
            if _saved_v422_last_send_ts is not None:
                V422StarvationAlerter._last_send_ts = _saved_v422_last_send_ts
            if _saved_truth is None:
                globals().pop("_v699_truthful_starvation_snapshot", None)
            else:
                globals()["_v699_truthful_starvation_snapshot"] = _saved_truth
            if _saved_hazard is None:
                globals().pop("_v704_market_hazard", None)
            else:
                globals()["_v704_market_hazard"] = _saved_hazard
    except Exception as exc:
        checks["exception"] = False
        STATS["v704_final_production_closure_self_test_error"] = f"{type(exc).__name__}:{exc}"
    return {"pass":bool(checks) and all(bool(v) for v in checks.values()),"checks":checks}

_V704_FINAL_PRODUCTION_CLOSURE_SELF_TEST = _v704_final_production_closure_self_test()
