# R15 terminal validation closure: a single deterministic retry is allowed when
# the first result is False, after scrubbing only synthetic boot/self-test state.
_v703_r14_validator = globals().get("validate_config")
def _v704_validate_config_final():
    try:
        first = bool(callable(_v703_r14_validator) and _v703_r14_validator())
    except Exception as exc:
        first = False
        STATS["v704_validation_exception"] = f"{type(exc).__name__}:{exc}"
    STATS["v704_validation_first_pass"] = first
    if first:
        STATS["v704_validation_failed_checks"] = []
        STATS["v704_validation_retry_used"] = False
        return True
    STATS["v704_validation_failed_checks"] = _v704_validation_diagnostics().get("failed_checks", [])
    if not bool(CONFIG.get("V704_CONFIG_VALIDATION_RETRY_ON_FALSE", True)):
        return False
    try:
        _v704_scrub_boot_validation_state()
    except Exception:
        pass
    try:
        retry = bool(callable(_v703_r14_validator) and _v703_r14_validator())
    except Exception as exc:
        retry = False
        STATS["v704_validation_retry_exception"] = f"{type(exc).__name__}:{exc}"
    STATS["v704_validation_retry_used"] = True
    STATS["v704_validation_retry_pass"] = retry
    if not retry:
        STATS["v704_validation_failed_checks_retry"] = _v704_validation_diagnostics().get("failed_checks", [])
    return retry
globals()["validate_config"] = _v704_validate_config_final


