# R21 starvation truth: downstream routing wins over upstream aggregate pressure
# once a candidate actually reached selection and the builder/route path ran.
try:
    _v702_r21_prev_truth = globals().get("_v684_truth")
    def _v702_r21_truth() -> Dict[str, Any]:
        try:
            # Active hard hazards keep SYSTEM precedence.
            if KillSwitch.is_active() or bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
                return {"mode":"SYSTEM","root":"SYSTEM","source":"R21_SYSTEM_HAZARD","detail":"live_entry_hazard"}
            try:
                if ExchangeWatchdog.is_tripped():
                    return {"mode":"SYSTEM","root":"SYSTEM","source":"R21_WATCHDOG","detail":"watchdog_tripped"}
            except Exception:
                pass
            try:
                if str((BalanceReconciler.snapshot() or {}).get("state", "")).upper() == "BLOCK":
                    return {"mode":"SYSTEM","root":"SYSTEM","source":"R21_BALANCE","detail":"balance_block"}
            except Exception:
                pass

            cycle = _v702_r21_active_cycle_snapshot()
            sel = _v702_r21_num(cycle.get("selected"), 0)
            calls = _v702_r21_num(cycle.get("builder_calls"), 0)
            blocks = _v702_r21_num(cycle.get("builder_blocks"), 0)
            ready = _v702_r21_num(cycle.get("live_ready"), 0)
            q = _v702_r21_num(cycle.get("queued"), 0)
            s = _v702_r21_num(cycle.get("sent"), 0)
            sf = _v702_r21_num(cycle.get("send_fail"), 0)
            if bool(CONFIG.get("V702_R21_HANDOFF_TRUTH_ENABLE", True)) and sel > 0 and calls > 0 and q == 0 and s == 0:
                detail = (
                    f"selected={sel};builder_calls={calls};builder_blocks={blocks};"
                    f"live_ready={ready};queued={q};sent={s};send_fail={sf};"
                    f"stage={'BUILDER_BLOCKED' if blocks else 'ROUTE_HANDOFF_PENDING'}"
                )
                return {
                    "mode":"EXECUTION", "root":"EXECUTION", "source":"R21_SELECTED_TO_ROUTE_HANDOFF",
                    "cycle_id": _v702_r21_num(cycle.get("cycle_id"), 0),
                    "cycle_source": str(cycle.get("source", "R21_ACTIVE")),
                    "generated": _v702_r21_num(cycle.get("generated"), 0),
                    "prequal": _v702_r21_num(cycle.get("prequal"), 0),
                    "ranked": _v702_r21_num(cycle.get("ranked"), 0),
                    "mse_raw_ranked": _v702_r21_num(cycle.get("raw_ranked"), 0),
                    "selected": sel, "builder_calls": calls, "builder_blocks": blocks,
                    "live_ready": ready, "queued": q, "sent": s, "send_fail": sf,
                    "root_count": max(1, blocks, sf), "evidence": max(1, blocks, sf),
                    "root_share": 1.0, "detail": detail,
                }
            if callable(_v702_r21_prev_truth):
                t = dict(_v702_r21_prev_truth() or {})
                t.setdefault("source", "R21_PREVIOUS_TRUTH")
                # The old source can still expose an upstream structural root; it
                # remains valid when no downstream route was actually attempted.
                return t
        except Exception as exc:
            return {"mode":"SYSTEM","root":"SYSTEM","source":"R21_TRUTH_ERROR","detail":f"{type(exc).__name__}:{exc}"}
        return {"mode":"NONE","root":"NONE","source":"R21_NONE","detail":"no_active_evidence"}
    _v702_r21_truth._v702_r21_truth = True
    globals()["_v684_truth"] = _v702_r21_truth
    globals()["_v669_starvation_classify"] = lambda *_a, **_k: dict(_v702_r21_truth())
    STATS["v702_r21_truth_authority"] = True
    # Freeze the R21-native truth callable before R23 intentionally rebinds the
    # public truth symbol. R21 self-tests must validate R21 logic, not R23 logic.
    globals()["_V702_R21_TRUTH_NATIVE"] = _v702_r21_truth
except Exception as exc:
    STATS["v702_r21_truth_authority"] = False
    STATS["v702_r21_truth_error"] = f"{type(exc).__name__}:{exc}"

try:
    V453StarvationClassifier.classify = classmethod(lambda cls, *_a, **_k: _v702_r21_truth().get("root", "NONE"))
except Exception:
    STATS["v702_r21_classifier_rebind_error"] = True


# Engine-error forensic details: keep the existing isolated runtime error model,
# but expose exact engines/types in operator telemetry.
def _v702_r21_engine_error_top(n: int = 3):
    try:
        rows = []
        for k, v in STATS.items():
            sk = str(k)
            if sk.startswith("mse_engine_exception."):
                try:
                    cnt = int(v or 0)
                except Exception:
                    cnt = 0
                if cnt > 0:
                    eid = sk.split(".", 1)[1]
                    typ = str(STATS.get(f"v699_engine_exception_type.{eid}", "unknown") or "unknown")
                    detail = str(STATS.get(f"v699_engine_exception_detail.{eid}", "") or "")
                    rows.append((eid, typ, cnt, detail[-120:]))
        rows.sort(key=lambda x:(-x[2], x[0]))
        return rows[:max(1, int(n))]
    except Exception:
        return []


