# R21 production closure tests. All checks are exchange-free and restore any
# mutated telemetry state before returning.
def _v702_r21_final_self_test() -> Dict[str, Any]:
    checks: Dict[str, Any] = {}
    saved = {}
    saved_balance_state = (getattr(BalanceReconciler, "_last_state", "BLOCK"), getattr(BalanceReconciler, "_last_source", "init"), getattr(BalanceReconciler, "_last_real_value", 0.0), getattr(BalanceReconciler, "_last_real_ts", 0.0), getattr(BalanceReconciler, "_last_real_wall_ts", 0.0), getattr(BalanceReconciler, "_sealed", False))
    saved_blocked = dict(LIVE_ENTRIES_BLOCKED) if isinstance(LIVE_ENTRIES_BLOCKED, dict) else LIVE_ENTRIES_BLOCKED
    saved_wd_errors = list(getattr(ExchangeWatchdog, "_errors", ()) or ())
    saved_wd_until = float(getattr(ExchangeWatchdog, "_tripped_until", 0.0) or 0.0)
    saved_wd_reason = str(getattr(ExchangeWatchdog, "_last_reason", "") or "")
    try:
        # This test is deterministic and must not inherit a BLOCK/watchdog state
        # intentionally injected by an earlier unrelated self-test.
        try:
            BalanceReconciler._last_state = "REAL"
            BalanceReconciler._last_source = "r21_selftest"
        except Exception:
            pass
        try:
            if isinstance(LIVE_ENTRIES_BLOCKED, dict):
                LIVE_ENTRIES_BLOCKED.clear(); LIVE_ENTRIES_BLOCKED.update({"active": False, "reason": None, "where": None, "since": None})
            ExchangeWatchdog._errors.clear(); ExchangeWatchdog._tripped_until = 0.0; ExchangeWatchdog._last_reason = ""
        except Exception:
            pass
        checks["enabled"] = bool(CONFIG.get("V702_R21_FINAL_ENABLE", True))
        checks["revision"] = str(V702_R21_FINAL_CANONICAL_REVISION).startswith("R21-FINAL-CANONICAL")
        checks["single_spot_long_only"] = bool(CONFIG.get("LONG_ONLY", True)) and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT" and not bool(CONFIG.get("ALLOW_SHORT", False)) and not bool(CONFIG.get("ENABLE_FUTURES", False))
        checks["hard_forbidden_set"] = {"CAKE","PUMP","BNB","AERO","ETHFI"}.issubset(set(V702_HARD_FORBIDDEN_BASES))
        checks["engine_count_17"] = len(tuple(globals().get("_MSE_ENGINES", ()) or ())) == 17
        checks["public_cycle_authority"] = bool(STATS.get("v702_r21_public_cycle_authority", False))
        checks["truth_authority"] = bool(STATS.get("v702_r21_truth_authority", False))
        checks["heartbeat_wired"] = bool(STATS.get("v702_r21_heartbeat_wired", False))
        checks["summary_wired"] = bool(STATS.get("v702_r21_summary_wired", False))
        checks["knowledge_scope_wired"] = bool(STATS.get("v702_r21_knowledge_scope_wired", False))
        checks["knowledge_export_scope"] = bool(STATS.get("v702_r21_knowledge_export_scope_wired", False))
        checks["smc_telemetry_wired"] = bool(STATS.get("v702_r21_smc_telemetry_wired", False))
        checks["no_new_execution_authority"] = callable(getattr(SignalBuilder, "build_and_route", None)) and callable(getattr(OrderExecutor, "submit_entry", None))

        # Exact handoff truth simulation.
        keys = ("v681_runtime_cycle_id","v681_runtime_cycle_started_ts","v45_global_last_cycle_ts",
                "v45_global_last_cycle_generated","v45_global_last_prequalified","v45_global_last_cycle_ranked",
                "v45_global_last_cycle_selected","v681_runtime_cycle_raw_ranked","v547_cycle_builder_calls",
                "v547_cycle_builder_blocks","v547_cycle_live_ready_delta","v547_cycle_queued_delta",
                "v547_cycle_sent_delta","v535_cycle_send_failures","v681_runtime_cycle_generated",
                "v681_runtime_cycle_prequal","v681_runtime_cycle_ranked","v681_runtime_cycle_selected")
        saved = {k: STATS.get(k) for k in keys}
        for k,v in saved.items():
            if v is None: STATS.pop(k, None)
        now = WALL_NOW()
        STATS["v681_runtime_cycle_id"] = 99101
        STATS["v681_runtime_cycle_started_ts"] = now - 5.0
        STATS["v45_global_last_cycle_ts"] = now - 1.0
        STATS["v45_global_last_cycle_generated"] = 782
        STATS["v45_global_last_prequalified"] = 13
        STATS["v45_global_last_cycle_ranked"] = 13
        STATS["v45_global_last_cycle_selected"] = 13
        STATS["v681_runtime_cycle_raw_ranked"] = 41
        STATS["v547_cycle_builder_calls"] = 13
        STATS["v547_cycle_builder_blocks"] = 3
        STATS["v547_cycle_live_ready_delta"] = 0
        STATS["v547_cycle_queued_delta"] = 0
        STATS["v547_cycle_sent_delta"] = 0
        STATS["v535_cycle_send_failures"] = 0
        cyc = _v702_r21_active_cycle_snapshot()
        truth_fn = globals().get("_V702_R21_TRUTH_NATIVE") or globals().get("_v702_r21_truth")
        truth = truth_fn() if callable(truth_fn) else {}
        checks["cycle_counts_coherent"] = (cyc.get("generated"),cyc.get("prequal"),cyc.get("ranked"),cyc.get("selected")) == (782,13,13,13)
        checks["handoff_root_exec"] = truth.get("root") == "EXECUTION"
        checks["handoff_detail_exact"] = "builder_calls=13" in str(truth.get("detail")) and "queued=0" in str(truth.get("detail"))
        checks["handoff_no_queue_inference"] = cyc.get("queued") == 0 and cyc.get("sent") == 0

        # Label checks are pure output checks.
        # Preserve cycle state until after rendering, then restore it below.
        hb = _v702_r21_hb_segment()
        checks["heartbeat_handoff_visible"] = "HANDOFF[SEL=13,BUILDER_CALLS=13" in hb
        checks["heartbeat_rank_diag_label"] = "rank_diag_top=" in hb
        summary = _v702_r21_daily_summary_text()
        checks["summary_labels_unambiguous"] = "CANON_PASS=" in summary and "BUILDER=" in summary

        # Knowledge scope check must be deterministic and must not depend on a
        # previous self-test leaving the real production DB in a transient state.
        # Use a temporary isolated DB, then restore the configured path.
        _saved_db_path = CONFIG.get("DB_PATH")
        _tmp_db_path = None
        try:
            _fd, _tmp_db_path = tempfile.mkstemp(prefix="v702_r21_scope_", suffix=".db")
            os.close(_fd)
            CONFIG["DB_PATH"] = _tmp_db_path
            KnowledgeOutcomeLedger.ensure_schema()
            rep = KnowledgeOutcomeLedger._edge_report() if callable(getattr(KnowledgeOutcomeLedger, "_edge_report", None)) else {}
            checks["knowledge_scope_visible"] = (
                isinstance(rep, dict)
                and rep.get("scope") == "KNOWLEDGE_OUTCOMES_DB_SNAPSHOT"
                and rep.get("live_authorized") is False
                and bool(rep.get("generated_at_ts"))
            )
        except Exception:
            checks["knowledge_scope_visible"] = False
        finally:
            if _saved_db_path is None:
                CONFIG.pop("DB_PATH", None)
            else:
                CONFIG["DB_PATH"] = _saved_db_path
            try:
                if _tmp_db_path:
                    os.unlink(_tmp_db_path)
            except Exception:
                pass
    except Exception as exc:
        checks["exception"] = False
        checks["exception_detail"] = f"{type(exc).__name__}:{exc}"
    finally:
        for k, v in saved.items():
            if v is None:
                STATS.pop(k, None)
            else:
                STATS[k] = v
        try:
            (BalanceReconciler._last_state, BalanceReconciler._last_source, BalanceReconciler._last_real_value, BalanceReconciler._last_real_ts, BalanceReconciler._last_real_wall_ts, BalanceReconciler._sealed) = saved_balance_state
        except Exception:
            pass
        try:
            if isinstance(LIVE_ENTRIES_BLOCKED, dict) and isinstance(saved_blocked, dict):
                LIVE_ENTRIES_BLOCKED.clear(); LIVE_ENTRIES_BLOCKED.update(saved_blocked)
            ExchangeWatchdog._errors.clear(); ExchangeWatchdog._errors.extend(saved_wd_errors); ExchangeWatchdog._tripped_until = saved_wd_until; ExchangeWatchdog._last_reason = saved_wd_reason
        except Exception:
            pass
    return {"pass": bool(checks) and all(bool(v) for k,v in checks.items() if k != "exception_detail"), "checks": checks, "count": len(checks)}

V702_R21_FINAL_SELF_TEST = _v702_r21_final_self_test()
STATS["v702_r21_final_self_test"] = V702_R21_FINAL_SELF_TEST
STATS["v702_r21_final_canonical_revision"] = V702_R21_FINAL_CANONICAL_REVISION
FINAL_CANONICAL_RUNTIME["revision"] = V702_R21_FINAL_CANONICAL_REVISION
