def _v702_r24_final_self_test():
    global _V702_R24_ENGINE_ERROR_BASELINE
    checks = {}
    saved = dict(STATS)
    saved_base = dict(_V702_R24_ENGINE_ERROR_BASELINE)
    saved_ts = float(_V702_R24_ENGINE_ERROR_BASELINE_TS or 0.0)
    try:
        checks["revision"] = str(V702_R23_FINAL_CANONICAL_REVISION).startswith("R24-FINAL-CANONICAL")
        checks["epoch_arm_wrapper"] = bool(STATS.get("v702_r24_epoch_arm_wrapper_wired", False))
        checks["heartbeat_error_scope"] = bool(STATS.get("v702_r24_error_scope_heartbeat_wired", False))
        # Synthetic historical error must be excluded until its post-arm delta
        # changes. This is purely telemetry.
        if _MSE_ENGINES:
            eid = str(getattr(_MSE_ENGINES[0], "engine_id", "unknown")).lower()
            STATS[f"mse_engine_exception.{eid}"] = 7
            _V702_R24_ENGINE_ERROR_BASELINE = {eid: 7}
            checks["historical_error_excluded"] = _v702_r24_live_runtime_error_count() == 0
            STATS[f"mse_engine_exception.{eid}"] = 8
            checks["post_arm_error_visible"] = _v702_r24_live_runtime_error_count() == 1
        else:
            checks["historical_error_excluded"] = False
            checks["post_arm_error_visible"] = False
        checks["hard_long_only_spot"] = (bool(CONFIG.get("LONG_ONLY", True)) and str(CONFIG.get("MARKET_TYPE","SPOT")).upper()=="SPOT" and not bool(CONFIG.get("ALLOW_SHORT",False)) and not bool(CONFIG.get("ENABLE_FUTURES",False)))
        return {"pass": bool(all(checks.values())), "checks": checks, "count": len(checks)}
    except Exception as exc:
        checks["exception"] = False
        return {"pass": False, "checks": checks, "count": len(checks), "error": f"{type(exc).__name__}:{exc}"}
    finally:
        STATS.clear(); STATS.update(saved)
        _V702_R24_ENGINE_ERROR_BASELINE.clear(); _V702_R24_ENGINE_ERROR_BASELINE.update(saved_base)
        globals()["_V702_R24_ENGINE_ERROR_BASELINE_TS"] = saved_ts

V702_R24_FINAL_SELF_TEST = _v702_r24_final_self_test()
