# =============================================================================
# V702 R25 — FINAL CANONICAL VALIDATION FRESHNESS / DEPLOYMENT IDENTITY
# =============================================================================
# R25 closes the remaining production-shaped failure mode observed on Railway:
# a terminal validator could trust an import-time R21 closure snapshot that had
# been computed false, even though the current fully-wired runtime passed the
# underlying functional checks.  R25 deliberately refreshes the closure tests
# at the exact terminal validation boundary and then evaluates the fresh results.
#
# Additional operator-facing truth:
#   * the running source SHA-256 is emitted so a Railway deployment can be
#     compared directly against the audited artifact;
#   * validation never treats historical cached self-test booleans as the final
#     authority when a fresh deterministic closure can be executed;
#   * no trading, economic, liquidity, structure, score, SL, PreSend, balance,
#     exposure, LONG_ONLY/SPOT, or execution gate is relaxed.
# =============================================================================
V702_R25_FINAL_CANONICAL_REVISION = "R25-FINAL-CANONICAL-VALIDATION-FRESHNESS-DEPLOYMENT-IDENTITY"
V702_R25_RELEASE_TAG = "UNIFIED-SCALPER-V702-CANONICAL-FINAL-R25"
FINAL_CANONICAL_RUNTIME["revision"] = V702_R25_FINAL_CANONICAL_REVISION
FINAL_CANONICAL_RUNTIME["canonical_final"] = True
FINAL_CANONICAL_RUNTIME["r25_terminal_authority"] = True
CONFIG.update({
    "V702_R25_FINAL_ENABLE": True,
    "V702_R25_FRESH_CLOSURE_VALIDATION_ENABLE": True,
    "V702_R25_SOURCE_FINGERPRINT_ENABLE": True,
})


# =============================================================================
# R25 FINAL RUNTIME HARDENING — PULLBACK ENGINE ERROR BOUNDARY / BUILDER TRUTH
# =============================================================================
# These are production-safety and observability closures derived from the
# supplied Railway log.  They do not loosen any strategy, score, liquidity,
# fee, SL/TP, balance, exposure, Telegram, PreSend, or execution gate.
#
# 1) Strict MSE input contract: malformed OHLCV never reaches an engine.
# 2) PULLBACK TypeError containment: one bounded local repair attempt is made
#    only when the canonical engine boundary reports a TypeError. A second
#    TypeError quarantines the engine for the configured cooldown instead of
#    repeatedly burning scan/CPU cycles.
# 3) Selected->Builder terminal None attribution: a stale previous-cycle
#    blocker may no longer be reported as ``builder_returned_none``.
# 4) Heartbeat exposes R25 + the PULLBACK runtime error counters so deployment
#    identity and current fault state are visible in one operator line.
# =============================================================================
CONFIG.update({
    "V702_R25_PULLBACK_TYPEERROR_GUARD_ENABLE": True,
    "V702_R25_PULLBACK_TYPEERROR_RETRY_ENABLE": True,
    "V702_R25_PULLBACK_TYPEERROR_QUARANTINE_ENABLE": True,
    "V702_R25_PULLBACK_TYPEERROR_QUARANTINE_SEC": 180.0,
    "V702_R25_BUILDER_TRUTH_MAX_AGE_SEC": 20.0,
})


def _v702_r25_pb_frame_contract(df: Any) -> Tuple[bool, str]:
    """Validate the exact DataFrame contract required by PULLBACK."""
    try:
        if not (_PDNP_OK and 'pd' in globals() and pd is not None):
            return False, "pandas_unavailable"
        if not isinstance(df, pd.DataFrame):
            return False, "not_dataframe"
        required = ("open", "high", "low", "close", "volume")
        cols = list(df.columns)
        if any(c not in cols for c in required):
            return False, "missing_ohlcv"
        if len(cols) != len(set(cols)):
            return False, "duplicate_columns"
        if len(df) < 30:
            return False, "too_short"
        for col in required:
            series = df[col]
            if not isinstance(series, pd.Series):
                return False, f"column_not_series:{col}"
            vals = pd.to_numeric(series, errors="coerce").to_numpy(dtype=float)
            if vals.size < 30 or not np.isfinite(vals).all():
                return False, f"nonfinite:{col}"
            if col != "volume" and np.any(vals <= 0):
                return False, f"nonpositive:{col}"
            if col == "volume" and np.any(vals < 0):
                return False, "negative_volume"
        return True, "ok"
    except Exception as exc:
        return False, f"exception:{type(exc).__name__}"


def _v702_r25_repair_pullback_snapshot(snapshot: Any) -> Optional[Dict[str, Any]]:
    """Return a detached *materially repaired* numeric OHLCV snapshot or None.

    A valid numeric snapshot is deliberately not returned: retrying an engine
    with byte-for-byte equivalent market data only repeats a logic TypeError and
    burns scanner capacity. Retry is reserved for a real numeric/dtype repair.
    The input is never mutated.
    """
    try:
        if not isinstance(snapshot, dict):
            return None
        out = dict(snapshot)
        changed = False
        for key in ("df_15m", "df_5m"):
            df = snapshot.get(key)
            if not (_PDNP_OK and 'pd' in globals() and pd is not None and isinstance(df, pd.DataFrame)):
                return None
            cols = list(df.columns)
            required = ("open", "high", "low", "close", "volume")
            if len(cols) != len(set(cols)) or any(c not in cols for c in required):
                return None
            fixed = df.copy(deep=True)
            for col in required:
                fixed[col] = pd.to_numeric(fixed[col], errors="coerce")
            if not fixed[list(required)].equals(df[list(required)]):
                changed = True
            ok, _ = _v702_r25_pb_frame_contract(fixed)
            if not ok:
                return None
            out[key] = fixed
        if not changed:
            STATS["v702_r25_pb_typeerror_retry_skipped_no_change"] = int(
                STATS.get("v702_r25_pb_typeerror_retry_skipped_no_change", 0) or 0
            ) + 1
            return None
        out["v702_r25_pb_repaired"] = True
        out["v702_r25_pb_repair_changed"] = True
        out["v702_r25_pb_repair_ts"] = WALL_NOW()
        return out
    except Exception:
        return None


if not bool(globals().get("_V702_R25_ENGINE_GUARD_WIRED", False)):
    try:
        _V702_R25_ORIG_RUN_ENGINE_SAFE = MultiStrategyEngine._run_engine_safe

        def _v702_r25_run_engine_safe(engine_cls, snapshot):
            name = str(getattr(engine_cls, "engine_id", engine_cls.__name__) or engine_cls.__name__)
            if name.lower() == "pullback" and bool(CONFIG.get("V702_R25_PULLBACK_TYPEERROR_GUARD_ENABLE", True)):
                for key in ("df_15m", "df_5m"):
                    ok, reason = _v702_r25_pb_frame_contract((snapshot or {}).get(key) if isinstance(snapshot, dict) else None)
                    if not ok:
                        STATS["v702_r25_pb_contract_blocks"] = int(STATS.get("v702_r25_pb_contract_blocks", 0) or 0) + 1
                        STATS["v702_r25_pb_contract_last_reason"] = str(reason)[:120]
                        STATS["v702_r25_pb_contract_last_symbol"] = str((snapshot or {}).get("symbol", "") if isinstance(snapshot, dict) else "")
                        logger.warning("[R25-PB-CONTRACT] symbol=%s blocked=%s field=%s", STATS.get("v702_r25_pb_contract_last_symbol",""), reason, key)
                        return []

            before_err = int(STATS.get(f"mse_engine_exception.{name}", 0) or 0)
            out = _V702_R25_ORIG_RUN_ENGINE_SAFE(engine_cls, snapshot)
            after_err = int(STATS.get(f"mse_engine_exception.{name}", 0) or 0)
            delta = max(0, after_err - before_err)
            if name.lower() != "pullback" or delta <= 0 or not bool(CONFIG.get("V702_R25_PULLBACK_TYPEERROR_RETRY_ENABLE", True)):
                return out

            exc_type = str(STATS.get(f"v699_engine_exception_type.{name}", "") or "")
            if exc_type != "TypeError":
                return out

            STATS["v702_r25_pb_typeerror_detected"] = int(STATS.get("v702_r25_pb_typeerror_detected", 0) or 0) + 1
            STATS["v702_r25_pb_typeerror_last_detail"] = str(STATS.get(f"v699_engine_exception_detail.{name}", "") or "")[:500]
            STATS["v702_r25_pb_typeerror_last_symbol"] = str((snapshot or {}).get("symbol", "") if isinstance(snapshot, dict) else "")

            repaired = _v702_r25_repair_pullback_snapshot(snapshot)
            if repaired is not None:
                retry_before = int(STATS.get(f"mse_engine_exception.{name}", 0) or 0)
                retry_out = _V702_R25_ORIG_RUN_ENGINE_SAFE(engine_cls, repaired)
                retry_after = int(STATS.get(f"mse_engine_exception.{name}", 0) or 0)
                retry_delta = max(0, retry_after - retry_before)
                if isinstance(retry_out, list) and retry_out:
                    STATS["v702_r25_pb_typeerror_recovered"] = int(STATS.get("v702_r25_pb_typeerror_recovered", 0) or 0) + 1
                    logger.warning("[R25-PB-RECOVERED] symbol=%s TypeError recovered after numeric snapshot repair", STATS.get("v702_r25_pb_typeerror_last_symbol", ""))
                    return retry_out
                if retry_delta > 0:
                    STATS["v702_r25_pb_typeerror_retry_failed"] = int(STATS.get("v702_r25_pb_typeerror_retry_failed", 0) or 0) + 1
                    h = _MSEState.ensure(name)
                    if bool(CONFIG.get("V702_R25_PULLBACK_TYPEERROR_QUARANTINE_ENABLE", True)):
                        h.circuit_tripped_until = MONO_NOW() + max(30.0, float(CONFIG.get("V702_R25_PULLBACK_TYPEERROR_QUARANTINE_SEC", 180.0)))
                        STATS["v702_r25_pb_typeerror_quarantined"] = int(STATS.get("v702_r25_pb_typeerror_quarantined", 0) or 0) + 1
                        logger.error("[R25-PB-QUARANTINE] symbol=%s repeated TypeError; engine quarantined", STATS.get("v702_r25_pb_typeerror_last_symbol", ""))
            else:
                STATS["v702_r25_pb_typeerror_unrepairable"] = int(STATS.get("v702_r25_pb_typeerror_unrepairable", 0) or 0) + 1
                logger.error("[R25-PB-QUARANTINE] symbol=%s TypeError snapshot not repairable", STATS.get("v702_r25_pb_typeerror_last_symbol", ""))
                h = _MSEState.ensure(name)
                if bool(CONFIG.get("V702_R25_PULLBACK_TYPEERROR_QUARANTINE_ENABLE", True)):
                    h.circuit_tripped_until = MONO_NOW() + max(30.0, float(CONFIG.get("V702_R25_PULLBACK_TYPEERROR_QUARANTINE_SEC", 180.0)))
            return []

        MultiStrategyEngine._run_engine_safe = staticmethod(_v702_r25_run_engine_safe)
        globals()["_V702_R25_ENGINE_GUARD_WIRED"] = True
        STATS["v702_r25_engine_guard_wired"] = True
    except Exception as exc:
        STATS["v702_r25_engine_guard_wired"] = False
        STATS["v702_r25_engine_guard_error"] = f"{type(exc).__name__}:{exc}"


if not bool(globals().get("_V702_R25_BUILDER_TRUTH_WIRED", False)):
    try:
        _V702_R25_ORIG_BUILD_AND_ROUTE = SignalBuilder.build_and_route

        async def _v702_r25_build_and_route(exchange, symbol, market_data, preferred_candidate=None):
            try:
                result = await _V702_R25_ORIG_BUILD_AND_ROUTE(
                    exchange, symbol, market_data, preferred_candidate=preferred_candidate
                )
            except TypeError as exc:
                # R26 terminal policy: no whole-builder positional fallback.
                # The canonical call signature is validated at boot.
                STATS["v702_r26_r25_typeerror_passthrough"] = int(
                    STATS.get("v702_r26_r25_typeerror_passthrough", 0) or 0
                ) + 1
                raise
            if preferred_candidate is not None and result is None:
                now = WALL_NOW()
                fresh = dict(STATS.get("v701_current_builder_block") or {})
                age = now - float(fresh.get("ts", 0.0) or 0.0) if fresh.get("ts") else float("inf")
                same_symbol = str(fresh.get("symbol", "")) == str(symbol)
                max_age = max(1.0, float(CONFIG.get("V702_R25_BUILDER_TRUTH_MAX_AGE_SEC", 20.0)))
                reason = str(fresh.get("reason", "") or "")
                stage = str(fresh.get("stage", "") or "")
                usable = same_symbol and age <= max_age and reason not in {"", "builder_returned_none"}
                if not usable:
                    reason = "builder_terminal_no_result_unattributed"
                    stage = "builder_terminal"
                STATS["v702_r25_builder_terminal_none"] = int(STATS.get("v702_r25_builder_terminal_none", 0) or 0) + 1
                STATS["v702_r25_builder_terminal_last"] = {
                    "symbol": str(symbol), "reason": reason[:240], "stage": stage[:120],
                    "fresh_context": bool(usable), "source_age_sec": None if age == float("inf") else round(age, 3),
                    "ts": now,
                }
                if not usable:
                    STATS["v702_r25_builder_terminal_unattributed"] = int(STATS.get("v702_r25_builder_terminal_unattributed", 0) or 0) + 1
                    logger.warning("[R25-BUILDER-TRUTH] SELECTED->BUILDER terminal None symbol=%s reason=%s", symbol, reason)
            return result

        _v702_r25_build_and_route._v702_r25_builder_truth = True
        SignalBuilder.build_and_route = staticmethod(_v702_r25_build_and_route)
        globals()["_V702_R25_BUILDER_TRUTH_WIRED"] = True
        STATS["v702_r25_builder_truth_wired"] = True
    except Exception as exc:
        STATS["v702_r25_builder_truth_wired"] = False
        STATS["v702_r25_builder_truth_error"] = f"{type(exc).__name__}:{exc}"


if not bool(globals().get("_V702_R25_HB_WIRED", False)):
    try:
        _V702_R25_ORIG_HB_SEG = globals().get("_v43_hb_segment")
        if callable(_V702_R25_ORIG_HB_SEG):
            def _v702_r25_hb_segment():
                base = _V702_R25_ORIG_HB_SEG()
                try:
                    if "V702[" in base and "rev=R25," not in base:
                        base = base.replace("V702[release=", "V702[rev=R25,release=", 1)
                    pb = (
                        f" PBERR={int(STATS.get('mse_engine_exception.pullback',0) or 0)}"
                        f" PBERRTYPE={str(STATS.get('v699_engine_exception_type.pullback','') or '-')[:24]}"
                        f" PBGUARD={int(STATS.get('v702_r25_pb_contract_blocks',0) or 0)}"
                    )
                    return base + pb
                except Exception:
                    return base
            _v702_r25_hb_segment._v702_r25 = True
            globals()["_v43_hb_segment"] = _v702_r25_hb_segment
            globals()["_V702_R25_HB_WIRED"] = True
            STATS["v702_r25_heartbeat_identity_wired"] = True
    except Exception as exc:
        STATS["v702_r25_heartbeat_identity_wired"] = False
        STATS["v702_r25_heartbeat_identity_error"] = f"{type(exc).__name__}:{exc}"

def _v702_r25_source_sha256() -> str:
    try:
        with open(__file__, "rb") as _fh:
            return hashlib.sha256(_fh.read()).hexdigest()
    except Exception:
        return "UNAVAILABLE"


def _v702_r25_refresh_terminal_closures() -> Dict[str, Dict[str, Any]]:
    """Re-run deterministic terminal closures in dependency order.

    This intentionally refreshes the cached closure records used by the
    historical validators.  It prevents a one-time import-order/transient
    self-test result from becoming permanent boot state.
    """
    out: Dict[str, Dict[str, Any]] = {}
    # V700 is intentionally import-order scoped: its active-cycle regression
    # targets the pre-R18 canonical ledger before later truth wrappers rebind
    # the public symbol. Re-running it after R23 would test the wrong authority.
    # The source-level deployment-entrypoint check is semantic and therefore
    # remains valid in the cached import-time V700 audit.
    try:
        STATS["v702_r25_v700_cached_audit_pass"] = bool((globals().get("_V700_PRODUCTION_AUDIT") or {}).get("pass", False))
    except Exception:
        STATS["v702_r25_v700_cached_audit_pass"] = False
    try:
        fn = globals().get("_v702_r18_final_closure_self_test")
        if callable(fn):
            globals()["V702_R18_FINAL_CLOSURE_SELF_TEST"] = fn()
            STATS["v702_r18_final_self_test"] = globals()["V702_R18_FINAL_CLOSURE_SELF_TEST"]
        out["r18"] = dict(globals().get("V702_R18_FINAL_CLOSURE_SELF_TEST", {}) or {})
    except Exception as exc:
        out["r18"] = {"pass": False, "error": f"{type(exc).__name__}:{exc}"}

    try:
        fn = globals().get("_v702_r19_final_self_test")
        if callable(fn):
            globals()["V702_R19_FINAL_SELF_TEST"] = fn()
            STATS["v702_r19_final_self_test"] = globals()["V702_R19_FINAL_SELF_TEST"]
        out["r19"] = dict(globals().get("V702_R19_FINAL_SELF_TEST", {}) or {})
    except Exception as exc:
        out["r19"] = {"pass": False, "error": f"{type(exc).__name__}:{exc}"}

    try:
        fn = globals().get("_v702_r20_smc_self_test")
        if callable(fn):
            globals()["V702_R20_FINAL_SELF_TEST"] = fn()
            STATS["v702_r20_final_self_test"] = globals()["V702_R20_FINAL_SELF_TEST"]
        out["r20"] = dict(globals().get("V702_R20_FINAL_SELF_TEST", {}) or {})
    except Exception as exc:
        out["r20"] = {"pass": False, "error": f"{type(exc).__name__}:{exc}"}

    try:
        fn = globals().get("_v702_r21_final_self_test")
        if callable(fn):
            globals()["V702_R21_FINAL_SELF_TEST"] = fn()
            STATS["v702_r21_final_self_test"] = globals()["V702_R21_FINAL_SELF_TEST"]
        out["r21"] = dict(globals().get("V702_R21_FINAL_SELF_TEST", {}) or {})
    except Exception as exc:
        out["r21"] = {"pass": False, "error": f"{type(exc).__name__}:{exc}"}

    try:
        fn = globals().get("_v702_r23_final_self_test")
        if callable(fn):
            globals()["V702_R23_FINAL_SELF_TEST"] = fn()
            STATS["v702_r23_final_self_test"] = globals()["V702_R23_FINAL_SELF_TEST"]
        out["r23"] = dict(globals().get("V702_R23_FINAL_SELF_TEST", {}) or {})
    except Exception as exc:
        out["r23"] = {"pass": False, "error": f"{type(exc).__name__}:{exc}"}

    try:
        fn = globals().get("_v702_r24_final_self_test")
        if callable(fn):
            globals()["V702_R24_FINAL_SELF_TEST"] = fn()
            STATS["v702_r24_final_self_test"] = globals()["V702_R24_FINAL_SELF_TEST"]
        out["r24"] = dict(globals().get("V702_R24_FINAL_SELF_TEST", {}) or {})
    except Exception as exc:
        out["r24"] = {"pass": False, "error": f"{type(exc).__name__}:{exc}"}

    STATS["v702_r25_fresh_terminal_closures"] = out
    return out


def _v702_r25_terminal_validate_config() -> bool:
    """Single terminal authority for R25.

    The historical V704 functional chain remains mandatory, but closure tests
    are refreshed immediately before the final decision.  Thus a stale false
    cached self-test can never fail boot after the runtime has been fully wired.
    """
    components: Dict[str, bool] = {}
    source_sha = _v702_r25_source_sha256()
    try:
        refreshed = _v702_r25_refresh_terminal_closures() if bool(CONFIG.get("V702_R25_FRESH_CLOSURE_VALIDATION_ENABLE", True)) else {}
        # Refresh closure truth FIRST. The historical V704 chain has captured
        # several compatibility validators over the life of V702; running it
        # after refresh prevents an old cached terminal self-test from becoming
        # a false boot blocker.
        try:
            historical = bool(_v704_validate_config_final())
        except Exception as exc:
            historical = False
            STATS["v702_r25_historical_validation_exception"] = f"{type(exc).__name__}:{exc}"
        components["historical_functional_chain"] = historical
        components["v700_production_audit"] = bool((globals().get("_V700_PRODUCTION_AUDIT") or {}).get("pass", False))
        components["r18_closure"] = bool((refreshed.get("r18") or {}).get("pass", False))
        components["r19_closure"] = bool((refreshed.get("r19") or {}).get("pass", False))
        components["r20_smc_hardening"] = bool((refreshed.get("r20") or {}).get("pass", False))
        components["r21_handoff_telemetry"] = bool((refreshed.get("r21") or {}).get("pass", False))
        components["r23_closure"] = bool((refreshed.get("r23") or {}).get("pass", False))
        components["r24_closure"] = bool((refreshed.get("r24") or {}).get("pass", False))
        components["source_fingerprint_available"] = source_sha not in {"", "UNAVAILABLE"}
        components["spot_long_only"] = (
            bool(CONFIG.get("LONG_ONLY", True))
            and str(CONFIG.get("MARKET_TYPE", CONFIG.get("TRADING_MODE", "SPOT"))).upper() == "SPOT"
            and not bool(CONFIG.get("ALLOW_SHORT", False))
            and not bool(CONFIG.get("ENABLE_FUTURES", False))
        )
        components["forbidden_set"] = {"CAKE","PUMP","BNB","AERO","ETHFI"}.issubset(set(V702_HARD_FORBIDDEN_BASES))
        components["engines_17"] = len(tuple(globals().get("_MSE_ENGINES", ()) or ())) == 17
        components["all_engines_enabled"] = all(bool(e.enabled()) for e in _MSE_ENGINES)
        components["single_execution_authority"] = callable(getattr(SignalBuilder,"build_and_route",None)) and callable(getattr(OrderExecutor,"submit_entry",None))
        components["discovery_shadow_only"] = bool(CONFIG.get("V699_DISCOVERY_ORDER_FORBIDDEN", True)) and not bool(CONFIG.get("V690_DISCOVERY_VERIFIED_LIVE", False))
        components["hard_gate_bypass_false"] = not bool(CONFIG.get("V702_R23_HARD_GATE_BYPASS", False))
        components["economic_floors"] = (
            float(CONFIG.get("MIN_TP1_TO_FEE_RATIO",0.0)) >= 2.5
            and float(CONFIG.get("MIN_NET_RR_TP1",0.0)) >= 0.8
            and float(CONFIG.get("MIN_NET_RR_OVERALL",0.0)) >= 1.2
            and float(CONFIG.get("MIN_SL_PCT",0.0)) >= 0.40
        )
        components["ticket_cap"] = float(CONFIG.get("MAX_ENTRY_NOTIONAL_USDT",75.0)) <= 75.0 and float(CONFIG.get("MAX_POSITION_SIZE_USDT",75.0)) <= 75.0
        components["slot_cap"] = int(CONFIG.get("MAX_CONCURRENT_TRADES",2)) <= 2
        components["smc_hardening"] = components["r20_smc_hardening"] and str(globals().get("V702_R20_SMC_VERSION","")).startswith("SMC-CLOSED-BAR")
        components["knowledge_scope"] = callable(getattr(KnowledgeOutcomeLedger,"_edge_report",None))
        # R25 runtime-boundary regressions. Deterministic, non-authorizing.
        try:
            if _PDNP_OK and 'pd' in globals() and pd is not None:
                _idx = pd.date_range("2026-01-01", periods=40, freq="5min")
                _vals = np.linspace(10.0, 11.0, 40)
                _good = pd.DataFrame({
                    "open": _vals, "high": _vals + 0.2, "low": _vals - 0.2,
                    "close": _vals + 0.05, "volume": np.linspace(100.0, 140.0, 40),
                }, index=_idx)
                _bad = _good.copy(deep=True)
                _bad.loc[_idx[-1], "close"] = np.nan
                _dup = _good.copy(deep=True)
                _dup.columns = ["open", "high", "low", "close", "close"]
                components["r25_strict_mse_data_contract"] = (
                    not _mse_context_ok(_bad, 30) and not _mse_context_ok(_dup, 30)
                )
            else:
                components["r25_strict_mse_data_contract"] = False
        except Exception:
            components["r25_strict_mse_data_contract"] = False
        try:
            _src_r25 = Path(__file__).read_text(encoding="utf-8", errors="replace")
        except Exception:
            _src_r25 = ""
        components["r25_pullback_typeerror_guard_wired"] = (
            bool(STATS.get("v702_r25_engine_guard_wired", False))
            and callable(getattr(MultiStrategyEngine, "_run_engine_safe", None))
            and "v702_r25_pb_typeerror_quarantined" in _src_r25
        )
        # Retry must require a real data repair; a valid numeric frame must not
        # be re-submitted to the engine merely because it raised TypeError.
        try:
            _snap = {"df_15m": _good, "df_5m": _good.copy(deep=True)}
            _same = _v702_r25_repair_pullback_snapshot(_snap)
            _obj = _good.copy(deep=True)
            for _c in ("open", "high", "low", "close", "volume"):
                _obj[_c] = _obj[_c].map(lambda x: f"{float(x):.8f}")
            _obj_snap = {"df_15m": _obj, "df_5m": _obj.copy(deep=True)}
            _changed = _v702_r25_repair_pullback_snapshot(_obj_snap)
            components["r25_pb_retry_requires_material_repair"] = (
                _same is None
                and isinstance(_changed, dict)
                and bool(_changed.get("v702_r25_pb_repair_changed", False))
            )
        except Exception:
            components["r25_pb_retry_requires_material_repair"] = False
        components["r25_builder_terminal_truth_wired"] = (
            bool(STATS.get("v702_r25_builder_truth_wired", False))
            and "builder_terminal_no_result_unattributed" in _src_r25
        )
        try:
            _hb = _v702_runtime_function_source(globals().get("_v43_hb_segment")) if callable(globals().get("_v43_hb_segment")) else ""
            components["r25_heartbeat_identity"] = "rev=R25" in _hb or bool(STATS.get("v702_r25_heartbeat_identity_wired", False))
        except Exception:
            components["r25_heartbeat_identity"] = bool(STATS.get("v702_r25_heartbeat_identity_wired", False))
        failed = [k for k,v in components.items() if not bool(v)]
        result = {
            "pass": not failed,
            "checks": dict(components),
            "failed": list(failed),
            "source_sha256": source_sha,
            "revision": V702_R25_FINAL_CANONICAL_REVISION,
            "fresh_closure_passes": {k: bool((v or {}).get("pass", False)) for k,v in refreshed.items()},
        }
        STATS["v702_r25_validation_components"] = dict(components)
        STATS["v702_r25_failed_components"] = list(failed)
        STATS["v702_r25_validation_source_sha256"] = source_sha
        STATS["v702_r25_final_validation"] = result
        if failed:
            logger.critical("[V702-CONFIG] canonical R25 validation FAIL failed=%s source_sha256=%s", failed, source_sha)
        else:
            logger.info("[V702-CONFIG] canonical R25 validation PASS components=%d source_sha256=%s", len(components), source_sha)
        return not failed
    except Exception as exc:
        STATS["v702_r25_final_validation"] = {
            "pass": False, "checks": dict(components), "failed":["validator_exception"],
            "source_sha256": source_sha, "revision": V702_R25_FINAL_CANONICAL_REVISION,
            "error": f"{type(exc).__name__}:{exc}",
        }
        logger.critical("[V702-CONFIG] canonical R25 validator exception: %s source_sha256=%s", exc, source_sha)
        return False


globals()["validate_config"] = _v702_r25_terminal_validate_config
STATS["v702_r25_terminal_validator_wired"] = True
STATS["v702_r25_final_canonical_revision"] = V702_R25_FINAL_CANONICAL_REVISION
FINAL_CANONICAL_RUNTIME["source_sha256"] = _v702_r25_source_sha256()
FINAL_CANONICAL_RUNTIME["release_tag"] = V702_R25_RELEASE_TAG


# =============================================================================
# R26 — FINAL CANONICAL PRODUCTION HARDENING
# =============================================================================
# This terminal layer supersedes R25 only where an independently verified
# correctness defect was found during the final source+runtime audit:
#
#   (1) A generic TypeError retry around the WHOLE SignalBuilder route was
#       unsafe because the first route can reach venue submission before a
#       TypeError escapes. Retrying the whole route can therefore duplicate a
#       venue order. R26 removes that retry. A leaked TypeError is recorded as a
#       terminal builder fault and the route returns fail-closed.
#
#   (2) The import-time V699 lifecycle test used asyncio.run() directly. R26
#       uses the existing loop-aware synchronous bridge so the test can never
#       leave an unawaited coroutine behind when an event loop is active.
#
#   (3) The packaged R25 identity is historical. R26 becomes the only terminal
#       canonical revision while all historical R18-R25 closure functions remain
#       available for provenance and compatibility.
#
# No safety/economic/venue gate is weakened. No strategy is deleted. Discovery
# remains non-authorizing. SPOT/LONG_ONLY and the hard-forbidden set remain
# unchanged.
# =============================================================================
V702_R26_FINAL_CANONICAL_REVISION = "R26-FINAL-CANONICAL-PRODUCTION-AUDITED-EXECUTION-IDEMPOTENCY"
_inspect_r26 = __import__("inspect")
V702_R26_RELEASE_TAG = "UNIFIED-SCALPER-V702-CANONICAL-FINAL-R26"

FINAL_CANONICAL_RUNTIME["revision"] = V702_R26_FINAL_CANONICAL_REVISION
FINAL_CANONICAL_RUNTIME["canonical_final"] = True
FINAL_CANONICAL_RUNTIME["r26_terminal_authority"] = True
FINAL_CANONICAL_RUNTIME["r25_historical_provenance"] = V702_R25_FINAL_CANONICAL_REVISION
CONFIG.update({
    "V702_R26_FINAL_ENABLE": True,
    "V702_R26_TERMINAL_AUTHORITY": True,
    "V702_R26_BUILDER_TYPEERROR_RETRY_ENABLE": False,
    "V702_R26_ASYNC_SELFTEST_BRIDGE_ENABLE": True,
    "V702_R26_BUILDER_TRUTH_MAX_AGE_SEC": 20.0,
})
STATS["v702_r26_final_canonical_revision"] = V702_R26_FINAL_CANONICAL_REVISION
STATS["v702_r26_terminal_authority"] = True

# --- R26 canonical builder wrapper: NEVER retry a whole route on TypeError. ---
if not bool(globals().get("_V702_R26_BUILDER_WIRED", False)):
    try:
        _V702_R26_ORIG_BUILD_AND_ROUTE = globals().get(
            "_V702_R25_ORIG_BUILD_AND_ROUTE",
            SignalBuilder.build_and_route,
        )

        async def _v702_r26_build_and_route(
            exchange, symbol, market_data, preferred_candidate=None
        ):
            try:
                result = await _V702_R26_ORIG_BUILD_AND_ROUTE(
                    exchange, symbol, market_data,
                    preferred_candidate=preferred_candidate,
                )
            except TypeError as exc:
                # Critical idempotency rule: the first canonical route MAY have
                # reached venue submission before this exception escaped.
                # Retrying the whole builder is therefore forbidden.
                STATS["v702_r26_builder_typeerror"] = int(
                    STATS.get("v702_r26_builder_typeerror", 0) or 0
                ) + 1
                STATS["v702_r26_builder_terminal_last"] = {
                    "symbol": str(symbol),
                    "reason": "builder_typeerror_no_retry",
                    "stage": "builder",
                    "exception_type": type(exc).__name__,
                    "detail": str(exc)[:300],
                    "ts": WALL_NOW(),
                }
                _r26_selftest_log = bool(globals().get("V644_SELFTEST_ACTIVE", False)) or str(symbol).upper().startswith("R26-")
                (logger.info if _r26_selftest_log else logger.error)(
                    "[R26-BUILDER%s] TypeError terminal; whole-route retry disabled "
                    "to preserve execution idempotency symbol=%s detail=%s",
                    "-SELFTEST" if _r26_selftest_log else "",
                    symbol, str(exc)[:240],
                )
                return None

            if preferred_candidate is not None and result is None:
                now = WALL_NOW()
                fresh = dict(STATS.get("v701_current_builder_block") or {})
                age = (
                    now - float(fresh.get("ts", 0.0) or 0.0)
                    if fresh.get("ts") else float("inf")
                )
                same_symbol = str(fresh.get("symbol", "")) == str(symbol)
                max_age = max(
                    1.0,
                    float(CONFIG.get("V702_R26_BUILDER_TRUTH_MAX_AGE_SEC", 20.0)),
                )
                reason = str(fresh.get("reason", "") or "")
                stage = str(fresh.get("stage", "") or "")
                usable = (
                    same_symbol
                    and age <= max_age
                    and reason not in {"", "builder_returned_none"}
                )
                if not usable:
                    reason = "builder_terminal_no_result_unattributed"
                    stage = "builder_terminal"
                STATS["v702_r26_builder_terminal_none"] = int(
                    STATS.get("v702_r26_builder_terminal_none", 0) or 0
                ) + 1
                STATS["v702_r26_builder_terminal_last"] = {
                    "symbol": str(symbol),
                    "reason": reason[:240],
                    "stage": stage[:120],
                    "fresh_context": bool(usable),
                    "source_age_sec": (
                        None if age == float("inf") else round(age, 3)
                    ),
                    "ts": now,
                }
                if not usable:
                    STATS["v702_r26_builder_terminal_unattributed"] = int(
                        STATS.get("v702_r26_builder_terminal_unattributed", 0) or 0
                    ) + 1
                    logger.warning(
                        "[R26-BUILDER-TRUTH] SELECTED->BUILDER terminal None "
                        "symbol=%s reason=%s", symbol, reason
                    )
            return result

        _v702_r26_build_and_route._v702_r26_builder = True
        SignalBuilder.build_and_route = staticmethod(_v702_r26_build_and_route)
        globals()["_V702_R26_BUILDER_WIRED"] = True
        STATS["v702_r26_builder_truth_wired"] = True
    except Exception as exc:
        STATS["v702_r26_builder_truth_wired"] = False
        STATS["v702_r26_builder_truth_error"] = (
            f"{type(exc).__name__}:{exc}"
        )

# --- R26 heartbeat identity: render the actual terminal revision. ---
if not bool(globals().get("_V702_R26_HB_WIRED", False)):
    try:
        _V702_R26_ORIG_HB_SEG = globals().get("_v43_hb_segment")
        if callable(_V702_R26_ORIG_HB_SEG):
            def _v702_r26_hb_segment():
                base = _V702_R26_ORIG_HB_SEG()
                try:
                    if "V702[" in base:
                        base = base.replace(
                            "rev=R25,release=",
                            f"rev=R26,release=",
                            1,
                        )
                        if "rev=R26," not in base:
                            base = base.replace(
                                "V702[release=",
                                "V702[rev=R26,release=",
                                1,
                            )
                    return base
                except Exception:
                    return base
            _v702_r26_hb_segment._v702_r26 = True
            globals()["_v43_hb_segment"] = _v702_r26_hb_segment
            globals()["_V702_R26_HB_WIRED"] = True
            STATS["v702_r26_heartbeat_identity_wired"] = True
    except Exception as exc:
        STATS["v702_r26_heartbeat_identity_wired"] = False
        STATS["v702_r26_heartbeat_identity_error"] = (
            f"{type(exc).__name__}:{exc}"
        )

def _v702_r26_source_sha256() -> str:
    try:
        with open(__file__, "rb") as _fh:
            return hashlib.sha256(_fh.read()).hexdigest()
    except Exception:
        return "UNAVAILABLE"

def _v702_r26_builder_typeerror_retry_audit() -> Dict[str, Any]:
    """Audit the *active* builder wrapper chain for whole-route TypeError retries.

    R26 is the single terminal TypeError authority. Intermediate wrappers may
    annotate and re-raise, but they must never invoke their delegate again from
    a TypeError handler. The check is AST-based to avoid being fooled by a
    comment/string mentioning the legacy retry.
    """
    chain_names = [
        "_v702_r26_build_and_route",
        "_V702_R26_ORIG_BUILD_AND_ROUTE",
        "_r23_builder_prev",
        "_orig_v702_terminal_builder",
        "_v702_orig_builder_final",
        "_v698_coherent_builder",
        "_v698_prev_builder",
        "_v696_build_and_route",
        "_v696_orig_build",
        "_v668_builder_feedback",
        "_v668_orig_builder",
        "_v666_builder_handoff",
        "_v666_orig_builder",
        "_v646_cycle_forensics_wrapper",
    ]
    visited = set()
    chain = []
    violations = []
    signature_failures = []

    def _callee_names(nodes):
        out = set()
        for node in ast.walk(ast.Module(body=nodes, type_ignores=[])):
            if isinstance(node, ast.Call):
                fn = node.func
                if isinstance(fn, ast.Name):
                    out.add(fn.id)
                elif isinstance(fn, ast.Attribute):
                    out.add(fn.attr)
        return out

    for name in chain_names:
        fn = globals().get(name)
        if not callable(fn) or id(fn) in visited:
            continue
        visited.add(id(fn))
        try:
            src = textwrap.dedent(_v702_runtime_function_source(fn))
            tree = ast.parse(src)
            chain.append({"name": name, "function": getattr(fn, "__name__", name)})
            try:
                sig = _inspect_r26.signature(fn)
                p = sig.parameters.get("preferred_candidate")
                if p is None or p.kind not in (
                    _inspect_r26.Parameter.POSITIONAL_OR_KEYWORD,
                    _inspect_r26.Parameter.KEYWORD_ONLY,
                ):
                    signature_failures.append(name)
            except Exception:
                signature_failures.append(name)

            for node in ast.walk(tree):
                if not isinstance(node, ast.Try):
                    continue
                in_try = _callee_names(node.body)
                for handler in node.handlers:
                    typ = handler.type
                    is_typeerror = (
                        isinstance(typ, ast.Name) and typ.id == "TypeError"
                    ) or (
                        isinstance(typ, ast.Tuple)
                        and any(isinstance(x, ast.Name) and x.id == "TypeError" for x in typ.elts)
                    )
                    if not is_typeerror:
                        continue
                    in_handler = _callee_names(handler.body)
                    overlap = sorted(in_try & in_handler)
                    if overlap:
                        violations.append({
                            "wrapper": getattr(fn, "__name__", name),
                            "delegate_calls": overlap,
                        })
        except Exception as exc:
            violations.append({
                "wrapper": name,
                "audit_error": f"{type(exc).__name__}:{exc}",
            })

    return {
        "pass": not violations and not signature_failures and bool(chain),
        "chain": chain,
        "violations": violations,
        "signature_failures": signature_failures,
    }


def _v702_r26_terminal_self_test() -> Dict[str, Any]:
    checks: Dict[str, bool] = {}
    details: Dict[str, Any] = {}
    try:
        checks["identity"] = (
            V702_R26_FINAL_CANONICAL_REVISION
            == "R26-FINAL-CANONICAL-PRODUCTION-AUDITED-EXECUTION-IDEMPOTENCY"
        )
        checks["r26_terminal_authority"] = bool(
            FINAL_CANONICAL_RUNTIME.get("r26_terminal_authority", False)
        )
        checks["spot_long_only"] = (
            bool(CONFIG.get("LONG_ONLY", True))
            and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT"
            and not bool(CONFIG.get("ALLOW_SHORT", False))
            and not bool(CONFIG.get("ENABLE_FUTURES", False))
        )
        checks["hard_forbidden"] = (
            {"CAKE", "PUMP", "BNB", "AERO", "ETHFI"}
            .issubset(set(V702_HARD_FORBIDDEN_BASES))
        )
        checks["engines_17"] = len(tuple(_MSE_ENGINES or ())) == 17
        checks["all_engines_enabled"] = all(
            bool(e.enabled()) for e in _MSE_ENGINES
        )
        checks["hard_score_floor"] = (
            float(CONFIG.get("MIN_LIVE_SCORE", 70.0) or 70.0) >= 70.0
        )
        checks["economic_floors"] = (
            float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5)) >= 2.5
            and float(CONFIG.get("MIN_NET_RR_TP1", 0.8)) >= 0.8
            and float(CONFIG.get("MIN_NET_RR_OVERALL", 1.2)) >= 1.2
            and float(CONFIG.get("MIN_SL_PCT", 0.40)) >= 0.40
        )
        checks["ticket_cap"] = (
            float(CONFIG.get("MAX_POSITION_SIZE_USDT", 75.0)) <= 75.0
            and int(CONFIG.get("MAX_CONCURRENT_TRADES", 2) or 2) <= 2
        )
        checks["builder_direct_call_authority"] = (
            SignalBuilder.build_and_route is not _V702_R25_ORIG_BUILD_AND_ROUTE
        )

        # Critical regression: a leaked TypeError from the canonical builder
        # must invoke it exactly once, never twice.
        _calls = {"n": 0}
        _old_r26_orig = globals().get("_V702_R26_ORIG_BUILD_AND_ROUTE")
        _old_terminal = dict(STATS.get("v702_r26_builder_terminal_last") or {})

        async def _v702_r26_faulty_builder(*args, **kwargs):
            _calls["n"] += 1
            raise TypeError("R26 synthetic builder TypeError")

        try:
            globals()["_V702_R26_ORIG_BUILD_AND_ROUTE"] = _v702_r26_faulty_builder
            outcome = _v517_run_awaitable_sync(
                SignalBuilder.build_and_route(
                    object(), "R26-TEST/USDT", {}, preferred_candidate=object()
                )
            )
            # active event-loop bridge returns a dict with skipped=True in an
            # embedded loop; in a normal sync process it returns None.
            if isinstance(outcome, dict) and bool(outcome.get("skipped", False)):
                checks["builder_typeerror_no_retry"] = (
                    _calls["n"] == 0
                    and "_V702_R26_ORIG_BUILD_AND_ROUTE(" in
                    _v702_runtime_function_source(SignalBuilder.build_and_route)
                )
            else:
                checks["builder_typeerror_no_retry"] = (
                    _calls["n"] == 1
                    and outcome is None
                    and int(STATS.get("v702_r26_builder_typeerror", 0) or 0) >= 1
                )
            details["builder_typeerror_calls"] = _calls["n"]
            details["builder_typeerror_outcome"] = outcome
        finally:
            if _old_r26_orig is None:
                globals().pop("_V702_R26_ORIG_BUILD_AND_ROUTE", None)
            else:
                globals()["_V702_R26_ORIG_BUILD_AND_ROUTE"] = _old_r26_orig
            if _old_terminal:
                STATS["v702_r26_builder_terminal_last"] = _old_terminal

        # Audit the complete active wrapper chain, not just the terminal R26
        # function. Older wrappers are allowed to annotate TypeError, but they
        # must never call their delegate a second time.
        try:
            src_txt = Path(__file__).read_text(
                encoding="utf-8", errors="replace"
            )
        except Exception:
            src_txt = ""
        chain_audit = _v702_r26_builder_typeerror_retry_audit()
        STATS["v702_r26_builder_chain_audit"] = chain_audit
        checks["builder_chain_typeerror_no_retry"] = bool(chain_audit.get("pass", False))
        checks["no_whole_builder_typeerror_retry"] = bool(
            chain_audit.get("pass", False)
            and not bool(CONFIG.get("V702_R26_BUILDER_TYPEERROR_RETRY_ENABLE", True))
        )
        details["builder_chain_typeerror_audit"] = chain_audit

        # End-to-end regression: inject a TypeError at the deepest active
        # builder delegate and ensure the live chain reaches R26 exactly once.
        # This catches nested retry bugs that a terminal-wrapper unit test misses.
        _nested_calls = {"n": 0}
        _old_nested_builder = globals().get("_v698_prev_builder")
        _old_nested_r26_count = int(STATS.get("v702_r26_builder_typeerror", 0) or 0)
        _old_nested_v698_count = int(STATS.get("v702_r26_v698_typeerror_passthrough", 0) or 0)
        _old_nested_v696_count = int(STATS.get("v702_r26_legacy_builder_typeerror_passthrough", 0) or 0)
        _old_nested_r25_count = int(STATS.get("v702_r26_r25_typeerror_passthrough", 0) or 0)

        async def _v702_r26_nested_faulty_builder(*args, **kwargs):
            _nested_calls["n"] += 1
            raise TypeError("R26 nested-chain synthetic TypeError")

        try:
            globals()["_v698_prev_builder"] = _v702_r26_nested_faulty_builder
            nested_outcome = _v517_run_awaitable_sync(
                SignalBuilder.build_and_route(
                    object(), "R26-NESTED-TEST/USDT", {}, preferred_candidate=None
                )
            )
            if isinstance(nested_outcome, dict) and bool(nested_outcome.get("skipped", False)):
                checks["builder_chain_nested_typeerror_no_retry"] = False
            else:
                checks["builder_chain_nested_typeerror_no_retry"] = (
                    _nested_calls["n"] == 1
                    and nested_outcome is None
                    and int(STATS.get("v702_r26_builder_typeerror", 0) or 0) > _old_nested_r26_count
                )
            details["builder_chain_nested_typeerror_calls"] = _nested_calls["n"]
            details["builder_chain_nested_typeerror_outcome"] = nested_outcome
        finally:
            if _old_nested_builder is None:
                globals().pop("_v698_prev_builder", None)
            else:
                globals()["_v698_prev_builder"] = _old_nested_builder
            STATS["v702_r26_builder_typeerror"] = _old_nested_r26_count
            STATS["v702_r26_v698_typeerror_passthrough"] = _old_nested_v698_count
            STATS["v702_r26_legacy_builder_typeerror_passthrough"] = _old_nested_v696_count
            STATS["v702_r26_r25_typeerror_passthrough"] = _old_nested_r25_count
        checks["r26_builder_truth_wired"] = bool(
            STATS.get("v702_r26_builder_truth_wired", False)
        )
        checks["r26_hb_wired"] = bool(
            STATS.get("v702_r26_heartbeat_identity_wired", False)
        )
        checks["async_selftest_bridge_present"] = (
            "_v517_run_awaitable_sync(_v699_route_recalled" in src_txt
        )

        # Canonical route order truth from the actual live builder:
        # PreSend -> queue commit -> final Telegram -> venue submit.
        try:
            _all_src = Path(__file__).read_text(
                encoding="utf-8", errors="replace"
            )
            _b0 = _all_src.find(
                "async def build_and_route(exchange, symbol: str, market_data:"
            )
            _b1 = _all_src.find("\n    async def ", _b0 + 10)
            if _b0 < 0:
                bsrc = ""
            else:
                bsrc = _all_src[_b0:_b1 if _b1 > _b0 else _b0 + 220000]
        except Exception:
            bsrc = ""
        p_presend = bsrc.find("PreSendGate")
        p_queue = bsrc.find('signals_queued')
        p_tg = bsrc.find("Telegram")
        p_submit = bsrc.find("OrderExecutor.submit_entry")
        # Use runtime-statement anchors, not a generic "Telegram" comment/name,
        # so documentation/comments cannot falsify the actual execution order.
        p_tg = bsrc.find("V700 FINAL TELEGRAM COMMIT")
        if p_tg < 0:
            p_tg = bsrc.find("OpportunityTelegramNotifier.notify_canonical(")
        checks["builder_order_truth"] = (
            p_presend >= 0 and p_queue >= 0 and p_tg >= 0 and p_submit >= 0
            and p_presend < p_queue < p_tg < p_submit
        )
        details["builder_order_positions"] = {
            "presend": p_presend, "queue": p_queue,
            "telegram": p_tg, "submit": p_submit,
        }

        failed = [k for k, v in checks.items() if not bool(v)]
        result = {
            "pass": not failed,
            "checks": checks,
            "failed": failed,
            "details": details,
            "source_sha256": _v702_r26_source_sha256(),
            "revision": V702_R26_FINAL_CANONICAL_REVISION,
        }
        STATS["v702_r26_terminal_self_test"] = result
        return result
    except Exception as exc:
        result = {
            "pass": False,
            "checks": checks,
            "failed": ["validator_exception"],
            "details": details,
            "source_sha256": _v702_r26_source_sha256(),
            "revision": V702_R26_FINAL_CANONICAL_REVISION,
            "error": f"{type(exc).__name__}:{exc}",
        }
        STATS["v702_r26_terminal_self_test"] = result
        return result

