def _v702_r26_validate_config() -> bool:
    components: Dict[str, bool] = {}
    try:
        # Preserve the already-passed historical R25 closure as provenance,
        # but evaluate it under its own authority and never let a stale
        # historical boolean define the R26 result.
        try:
            r25_ok = bool(_V702_R25_VALIDATE_ONLY_REQUEST) if False else bool(
                (STATS.get("v702_r25_final_validation") or {}).get("pass", False)
            )
        except Exception:
            r25_ok = False

        # Base validator is retained as a compatibility signal. If the current
        # process has no R25 cached result, execute it once; any failure remains
        # visible rather than being swallowed.
        try:
            base_ok = bool(_V702_R26_BASE_VALIDATOR()) if callable(_V702_R26_BASE_VALIDATOR) else False
        except Exception as exc:
            base_ok = False
            STATS["v702_r26_base_validator_error"] = (
                f"{type(exc).__name__}:{exc}"
            )

        r26 = dict(_V702_R26_TERMINAL_SELF_TEST or {})
        components["historical_r25_compatibility"] = bool(r25_ok or base_ok)
        components["r26_terminal_self_test"] = bool(r26.get("pass", False))
        components["source_parseable"] = True
        # The interpreter has already parsed this module to execute it; retain
        # the source-presence check without constructing a second full AST.
        components["source_parseable"] = bool(_v702_read_source_text())
        components["source_fingerprint_available"] = (
            _v702_r26_source_sha256() != "UNAVAILABLE"
        )
        components["engines_17"] = len(tuple(_MSE_ENGINES or ())) == 17
        components["all_engines_enabled"] = all(
            bool(e.enabled()) for e in _MSE_ENGINES
        )
        components["spot_long_only"] = (
            bool(CONFIG.get("LONG_ONLY", True))
            and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT"
            and not bool(CONFIG.get("ALLOW_SHORT", False))
            and not bool(CONFIG.get("ENABLE_FUTURES", False))
        )
        components["forbidden_set"] = (
            {"CAKE", "PUMP", "BNB", "AERO", "ETHFI"}
            .issubset(set(V702_HARD_FORBIDDEN_BASES))
        )
        components["hard_gate_bypass_false"] = not bool(
            CONFIG.get("V702_R23_HARD_GATE_BYPASS", False)
        )
        components["economic_floors"] = (
            float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 2.5)) >= 2.5
            and float(CONFIG.get("MIN_NET_RR_TP1", 0.8)) >= 0.8
            and float(CONFIG.get("MIN_NET_RR_OVERALL", 1.2)) >= 1.2
            and float(CONFIG.get("MIN_SL_PCT", 0.40)) >= 0.40
        )
        components["ticket_and_slots"] = (
            float(CONFIG.get("MAX_POSITION_SIZE_USDT", 75.0)) <= 75.0
            and int(CONFIG.get("MAX_CONCURRENT_TRADES", 2) or 2) <= 2
        )
        components["discovery_shadow_only"] = (
            bool(CONFIG.get("V699_DISCOVERY_ORDER_FORBIDDEN", True))
            and not bool(CONFIG.get("V690_DISCOVERY_VERIFIED_LIVE", False))
        )
        _r26_builder_source = (
            _v702_runtime_function_source(SignalBuilder.build_and_route)
            if "_v702_r26_build_and_route" in globals()
            else ""
        )
        components["no_whole_builder_typeerror_retry"] = (
            not bool(CONFIG.get("V702_R26_BUILDER_TYPEERROR_RETRY_ENABLE", True))
            and "_v702_r26_build_and_route" in globals()
            and "except TypeError as exc:" in _r26_builder_source
            and _r26_builder_source.count(
                "result = await _V702_R26_ORIG_BUILD_AND_ROUTE("
            ) == 1
            and "retry_failed" not in _r26_builder_source
        )
        components["async_selftest_safe_bridge"] = (
            "_v517_run_awaitable_sync(_v699_route_recalled"
            in Path(__file__).read_text(
                encoding="utf-8", errors="replace"
            )
        )
        try:
            hb = _v702_runtime_function_source(_v43_hb_segment)
            components["heartbeat_r26_identity"] = "rev=R26" in hb
        except Exception:
            components["heartbeat_r26_identity"] = False

        failed = [k for k, v in components.items() if not bool(v)]
        result = {
            "pass": not failed,
            "checks": components,
            "failed": failed,
            "revision": V702_R26_FINAL_CANONICAL_REVISION,
            "source_sha256": _v702_r26_source_sha256(),
            "terminal_self_test": r26,
        }
        STATS["v702_r26_final_validation"] = result
        if failed:
            logger.critical(
                "[V702-R26] FINAL CANONICAL VALIDATION FAIL failed=%s",
                failed,
            )
        else:
            logger.info(
                "[V702-R26] FINAL CANONICAL VALIDATION PASS checks=%d "
                "sha256=%s", len(components), result["source_sha256"]
            )
        return not failed
    except Exception as exc:
        STATS["v702_r26_final_validation"] = {
            "pass": False,
            "failed": ["validator_exception"],
            "revision": V702_R26_FINAL_CANONICAL_REVISION,
            "error": f"{type(exc).__name__}:{exc}",
        }
        return False

