# =============================================================================
# R28 FINAL CANONICAL PRODUCTION CLOSURE — TELEGRAM NOTIFICATION CONVERGENCE
# -----------------------------------------------------------------------------
# Root-cause fix for operator-noise without changing trading authority:
#   * Heartbeats, discovery/shadow research, rejection batches, starvation
#     diagnostics and builder-block diagnostics are retained internally but are
#     no longer emitted as a stream of independent Telegram messages.
#   * These non-critical observability events are compacted into ONE operator
#     digest every N seconds, with latest-state + aggregated counters + top
#     diagnostics.  This is transport-level convergence only; no candidate,
#     score, liquidity, HTF, fee, risk, SL/TP, PreSend or execution gate is
#     bypassed or relaxed.
#   * Critical execution/protection/order/control messages still use the normal
#     dispatcher path immediately.  Delivery callbacks are never compacted.
#   * Every compacted event remains represented by counters/latest records in
#     the digest buffer; the scanner/logging path itself is untouched.
#   * /digest is an on-demand operator drill-down of the latest compacted state,
#     so lower Telegram volume does not mean loss of operational visibility.
# =============================================================================
V702_R28_FINAL_AUDIT_CLOSURE = True
V702_R28_CLOSURE_ID = "2026-10-07-R28-TELEGRAM-DIGEST-OPERATOR-NOISE-CLOSURE"
V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC = 1800.0  # 30 minutes; critical alerts remain immediate.
V702_R28_TELEGRAM_DIGEST_MAX_CHARS = 3700
V702_R28_TELEGRAM_DIGEST_TOP_DISCOVERY = 8
V702_R28_TELEGRAM_DIGEST_TOP_BLOCKS = 6
V702_R28_TELEGRAM_DIGEST_TOP_SHADOW = 8

CONFIG.update({
    "V702_R28_FINAL_AUDIT_CLOSURE": True,
    "V702_R28_TELEGRAM_CONVERGENCE_ENABLE": True,
    "V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC": V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC,
    "V702_R28_TELEGRAM_DIGEST_MAX_CHARS": V702_R28_TELEGRAM_DIGEST_MAX_CHARS,
    "V702_R28_TELEGRAM_HEARTBEAT_IMMEDIATE": False,
    "V702_R28_TELEGRAM_DISCOVERY_IMMEDIATE": False,
    "V702_R28_TELEGRAM_REJECTION_IMMEDIATE": False,
    "V702_R28_TELEGRAM_STARVATION_IMMEDIATE": False,
    "V702_R28_TELEGRAM_SHADOW_IMMEDIATE": False,
    "V702_R28_TELEGRAM_EDGE_IMMEDIATE": False,
    "V702_R28_TELEGRAM_BUILDER_BLOCK_IMMEDIATE": False,
})
FINAL_CANONICAL_RUNTIME["r28_closure"] = V702_R28_CLOSURE_ID
FINAL_CANONICAL_RUNTIME["telegram_operator_mode"] = "DIGEST_5M_NONCRITICAL__CRITICAL_IMMEDIATE"
STATS["v702_r28_final_audit_closure"] = V702_R28_CLOSURE_ID

try:
    import html as _html_v702_r28
except Exception:  # pragma: no cover
    _html_v702_r28 = None


class _V702R28TelegramDigest:
    """Loss-minimizing convergence buffer for non-critical Telegram telemetry."""

    _lock = threading.RLock()
    _started_ts = 0.0
    _last_flush_ts = 0.0
    _events = 0
    _heartbeat = ""
    _starvation = ""
    _edge = ""
    _latest_rejection = ""
    _rejection_captured = 0
    _selected_blocks: deque = deque(maxlen=V702_R28_TELEGRAM_DIGEST_TOP_BLOCKS)
    _scorer_blocks: deque = deque(maxlen=V702_R28_TELEGRAM_DIGEST_TOP_BLOCKS)
    _route_blocks: deque = deque(maxlen=V702_R28_TELEGRAM_DIGEST_TOP_BLOCKS)
    _shadow_events: deque = deque(maxlen=V702_R28_TELEGRAM_DIGEST_TOP_SHADOW)
    _discovery_by_symbol: Dict[str, Dict[str, Any]] = {}
    _category_counts: Dict[str, int] = defaultdict(int)

    @classmethod
    def start(cls) -> None:
        now = float(WALL_NOW())
        with cls._lock:
            if not cls._started_ts:
                cls._started_ts = now
                cls._last_flush_ts = now

    @staticmethod
    def _strip(raw: str) -> str:
        s = str(raw or "")
        try:
            s = re.sub(r"<[^>]+>", "", s)
            if _html_v702_r28 is not None:
                s = _html_v702_r28.unescape(s)
        except Exception:
            pass
        return s.replace("\r", "").strip()

    @classmethod
    def classify(cls, raw: str) -> str:
        """Return compactable category or empty for immediate Telegram delivery."""
        s = cls._strip(raw)
        u = s.upper()
        if "DISCOVERY SIGNAL — KNOWLEDGE ONLY" in u:
            return "discovery"
        if "REJECTION BATCH" in u:
            return "rejection"
        if "[V422-STARVALERT]" in u or "STARVATION ALERT" in u:
            return "starvation"
        if "KNOWLEDGE SHADOW" in u:
            return "shadow"
        if "KNOWLEDGE EDGE REPORT" in u:
            return "edge"
        if "SELECTED → BUILDER BLOCK" in u:
            stage = cls._text(r"stage=([^\s]+)", s, "").strip().lower()
            reason = cls._text(r"reason=([^\n]+)", s, "").strip().lower()
            if stage in {"scorer", "score", "score_gate"} or "score_below_threshold" in reason or "reject.score." in reason:
                return "scorer_block"
            if stage.startswith(("prequal", "preexec", "selected_preexec", "route", "policy")):
                return "route_block"
            return "builder_block"
        if re.search(r"(^|\n)\s*HEARTBEAT\s*(\n|$)", u):
            return "heartbeat"
        return ""

    @staticmethod
    def _num(pattern: str, text: str, default: Optional[float] = None):
        try:
            m = re.search(pattern, text, flags=re.I | re.S)
            if not m:
                return default
            return float(m.group(1))
        except Exception:
            return default

    @staticmethod
    def _text(pattern: str, text: str, default: str = "-") -> str:
        try:
            m = re.search(pattern, text, flags=re.I | re.S)
            if not m:
                return default
            return str(m.group(1)).strip()
        except Exception:
            return default

    @classmethod
    def _capture_discovery(cls, text: str) -> None:
        symbol = cls._text(r"(?:^|\n)\s*([A-Z0-9_.\-]+/USDT)\s*(?:\n|$)", text, "UNKNOWN/USDT")
        strategy = cls._text(r"Strategy:\s*([^\n]+)", text, "?")
        engine = cls._num(r"Engine Score:\s*([0-9.]+)", text, -1.0)
        reviewed = cls._num(r"Reviewed Score:\s*([0-9.]+)", text, -1.0)
        projected = cls._num(r"Projected Canonical Live Score:\s*([0-9.]+)", text, -1.0)
        htf = cls._num(r"HTF:\s*([0-9.]+)", text, -1.0)
        vol = cls._num(r"Vol:\s*x?([0-9.]+)", text, -1.0)
        rs = cls._num(r"RS:\s*([-0-9.]+)%", text, 0.0)
        chase = cls._num(r"Chase:\s*([-0-9.]+)\s*ATR", text, -1.0)
        tier = cls._text(r"Tier:\s*([^\n]+)", text, "?")
        context = cls._text(r"Context:\s*([^\n]+)", text, "?")
        with cls._lock:
            old = cls._discovery_by_symbol.get(symbol)
            row = {
                "symbol": symbol,
                "strategy": strategy,
                "engine": engine,
                "reviewed": reviewed,
                "projected": projected,
                "htf": htf,
                "vol": vol,
                "rs": rs,
                "chase": chase,
                "tier": tier,
                "context": context,
                "raw": text,
                "ts": float(WALL_NOW()),
            }
            # Keep the newest observation unless the previous one is strictly
            # stronger and less stale; this prevents stale high scores surviving
            # indefinitely while still deduplicating same-symbol chatter.
            if old and (float(old.get("ts", 0.0)) > row["ts"] - 2.0) and float(old.get("projected", -1.0)) > projected:
                return
            cls._discovery_by_symbol[symbol] = row
            if len(cls._discovery_by_symbol) > 40:
                ordered = sorted(cls._discovery_by_symbol.values(), key=lambda x: float(x.get("ts", 0.0)), reverse=True)[:40]
                cls._discovery_by_symbol = {str(x["symbol"]): x for x in ordered}

    @classmethod
    def capture(cls, category: str, raw: str) -> None:
        cls.start()
        text = cls._strip(raw)
        with cls._lock:
            cls._events += 1
            cls._category_counts[category] += 1
        if category == "discovery":
            cls._capture_discovery(text)
        elif category == "heartbeat":
            with cls._lock:
                cls._heartbeat = text
        elif category == "starvation":
            with cls._lock:
                cls._starvation = text
        elif category == "edge":
            with cls._lock:
                cls._edge = text
        elif category == "rejection":
            with cls._lock:
                cls._latest_rejection = text
                cls._rejection_captured += 1
        elif category == "scorer_block":
            with cls._lock:
                cls._scorer_blocks.appendleft(text)
        elif category == "route_block":
            with cls._lock:
                cls._route_blocks.appendleft(text)
        elif category == "builder_block":
            with cls._lock:
                cls._selected_blocks.appendleft(text)
        elif category == "shadow":
            with cls._lock:
                cls._shadow_events.appendleft(text)

        STATS["v702_r28_telegram_compacted_events"] = int(STATS.get("v702_r28_telegram_compacted_events", 0) or 0) + 1
        STATS[f"v702_r28_captured_{category}"] = int(STATS.get(f"v702_r28_captured_{category}", 0) or 0) + 1

    @classmethod
    def _compact_counts(cls) -> str:
        with cls._lock:
            counts = {k: int(v) for k, v in cls._category_counts.items()}
            events = int(cls._events)
            rej_batches = int(cls._rejection_captured)
        if not counts:
            return f"events={events}"
        order = ("heartbeat", "discovery", "rejection", "starvation", "shadow", "edge", "scorer_block", "route_block", "builder_block")
        bits = [f"{k}={counts.get(k,0)}" for k in order if counts.get(k,0)]
        return f"events={events} | " + " ".join(bits) + f" | rejection_batches={rej_batches}"

    @classmethod
    def _heartbeat_line(cls, text: str) -> str:
        if not text:
            return "heartbeat=-"
        keys = (
            "state", "trades", "funnel G/E/Q/S", "exec_try", "live_ready", "send_fail",
            "regime", "sev", "starv_mode", "ENTRY_STATUS", "MSE_RANK", "root", "TG"
        )
        vals = []
        for key in keys:
            if key == "funnel G/E/Q/S":
                pat = r"funnel G/E/Q/S=([^\s]+)"
                label = "funnel"
            elif key in {"MSE_RANK", "TG"}:
                pat = rf"({re.escape(key)}(?:[^ ]*)?)"
                label = key
            else:
                pat = rf"{re.escape(key)}=([^\s]+)"
                label = key
            val = cls._text(pat, text, "")
            if val:
                vals.append(f"{label}={val}")
        try:
            _mr_mode = str(STATS.get("v702_r30_micro_recall_trigger", "") or "")
            _mr_n = int(STATS.get("v702_r30_micro_recall_selected", 0) or 0)
            if _mr_mode:
                vals.append(f"micro={_mr_mode}:{_mr_n}")
        except Exception:
            pass
        return "heartbeat=" + (" ".join(vals) if vals else "seen")

    @classmethod
    def _rejection_line(cls, text: str) -> str:
        if not text:
            return "rejections=-"
        ev = cls._text(r"Rejected evaluations:\s*([0-9]+)", text, "0")
        groups = cls._text(r"Notification groups:\s*([0-9]+)", text, "0")
        uniq = cls._text(r"Unique opportunities:\s*([0-9]+)", text, "0")
        sys = cls._text(r"SYSTEM=([0-9]+)", text, "0")
        pol = cls._text(r"POLICY=([0-9]+)", text, "0")
        htf = cls._text(r"HTF=([0-9]+)", text, "0")
        liq = cls._text(r"LIQUIDITY=([0-9]+)", text, "0")
        struct = cls._text(r"STRUCTURE=([0-9]+)", text, "0")
        score = cls._text(r"SCORE=([0-9]+)", text, "0")
        # Parse the payload after removing presentation tags. The digest header
        # "Top reasons / stages / exception types" is not the reason list; only
        # accept the standalone "Top reasons" line followed by its value line.
        plain = cls._strip(text)
        m_top = re.search(r"(?:^|\n)\s*Top reasons\s*\n\s*([^\n]+)", plain, flags=re.I)
        top = str(m_top.group(1)).strip() if m_top else "-"
        return (
            f"rejections latest_window: evals={ev} groups={groups} unique={uniq} | "
            f"S/P/H/L/ST/S={sys}/{pol}/{htf}/{liq}/{struct}/{score} | top={top}"
        )

    @classmethod
    def _starvation_line(cls, text: str) -> str:
        if not text:
            return "starvation=-"
        mode = cls._text(r"mode=([^\s|]+)", text, "NONE")
        generated = cls._text(r"generated_delta=([0-9]+)", text, "0")
        pre = cls._text(r"prequal_pass_delta=([0-9]+)", text, "0")
        ranked = cls._text(r"ranked_delta=([0-9]+)", text, "0")
        selected = cls._text(r"selected_delta=([0-9]+)", text, "0")
        queued = cls._text(r"queued_delta=([0-9]+)", text, "0")
        sent = cls._text(r"sent_delta=([0-9]+)", text, "0")
        return f"starvation mode={mode} G/P/R/SEL/Q/S={generated}/{pre}/{ranked}/{selected}/{queued}/{sent}"

    @classmethod
    def _edge_line(cls, text: str) -> str:
        if not text:
            return "edge=-"
        alerts = cls._text(r"Alerts:\s*([0-9]+)", text, "0")
        entries = cls._text(r"Entries:\s*([0-9]+)", text, "0")
        tp1 = cls._text(r"TP1 hit:\s*([0-9]+)", text, "0")
        tp2 = cls._text(r"TP2:\s*([0-9]+)", text, "0")
        tp3 = cls._text(r"TP3:\s*([0-9]+)", text, "0")
        sl = cls._text(r"SL hit:\s*([0-9]+)", text, "0")
        exp = cls._text(r"First-touch expectancy:\s*([-0-9.]+R)", text, "?")
        # The source is a shadow-outcome tracker, not a live-order ledger.
        # Keep that distinction visible after the long report header is compacted.
        return f"edge shadow_alerts={alerts} shadow_entries={entries} shadow_TP1/TP2/TP3/SL={tp1}/{tp2}/{tp3}/{sl} shadow_first_touch={exp}"

    @classmethod
    def _discovery_lines(cls) -> List[str]:
        with cls._lock:
            rows = list(cls._discovery_by_symbol.values())
        rows.sort(key=lambda x: (float(x.get("projected", -1.0)), float(x.get("reviewed", -1.0)), float(x.get("ts", 0.0))), reverse=True)
        out = []
        for x in rows[:V702_R28_TELEGRAM_DIGEST_TOP_DISCOVERY]:
            ctx = str(x.get("context", "?")).replace("\n", " ")
            out.append(
                f"• {x.get('symbol','?')} {x.get('strategy','?')} "
                f"P={float(x.get('projected',-1.0)):.1f} R={float(x.get('reviewed',-1.0)):.1f} "
                f"HTF={float(x.get('htf',-1.0)):.1f} tier={x.get('tier','?')} ctx={ctx}"
            )
        return out or ["• none"]

    @classmethod
    def _format_block_lines(cls, rows) -> List[str]:
        out = []
        for t in list(rows)[:V702_R28_TELEGRAM_DIGEST_TOP_BLOCKS]:
            symbol = cls._text(r"(?:Selected → Builder BLOCK)\s+([A-Z0-9_.\-]+/USDT)", t, "?")
            root = cls._text(r"root=([^\s]+)", t, "?")
            stage = cls._text(r"stage=([^\s]+)", t, "?")
            reason = cls._text(r"reason=([^\n]+)", t, "?")
            out.append(f"• {symbol} root={root} stage={stage} reason={reason[:120]}")
        return out or ["• none"]

    @classmethod
    def _block_lines(cls) -> List[str]:
        with cls._lock:
            rows = list(cls._selected_blocks)
        return cls._format_block_lines(rows)

    @classmethod
    def _scorer_block_lines(cls) -> List[str]:
        with cls._lock:
            rows = list(cls._scorer_blocks)
        return cls._format_block_lines(rows)

    @classmethod
    def _route_block_lines(cls) -> List[str]:
        with cls._lock:
            rows = list(cls._route_blocks)
        return cls._format_block_lines(rows)

    @classmethod
    def _selected_route_summary(cls) -> str:
        """Expose the latest selected-route blocker only for the active cycle."""
        try:
            rec = STATS.get("v702_selected_route_last")
            if not isinstance(rec, dict):
                return "none"
            cycle_id = int(STATS.get("v681_runtime_cycle_id", 0) or 0)
            rec_cycle = int(rec.get("cycle_id", 0) or 0)
            if cycle_id <= 0 or rec_cycle != cycle_id:
                return "none"
            symbol = re.sub(r"[^A-Z0-9_./-]", "", str(rec.get("symbol", "?") or "?").upper())[:32] or "?"
            stage = re.sub(r"[^A-Za-z0-9_.:-]", "", str(rec.get("stage", "unknown") or "unknown"))[:48]
            reason = re.sub(r"[|\r\n]+", " ", str(rec.get("reason", "") or "")).strip()[:150]
            try:
                age = max(0.0, float(WALL_NOW()) - float(rec.get("ts", WALL_NOW()) or WALL_NOW()))
                age_text = f" age={age:.0f}s"
            except Exception:
                age_text = " age=?"
            return f"{symbol}:{stage}:{reason or 'no_detail'}{age_text}"[:240]
        except Exception:
            return "unavailable"

    @classmethod
    def _shadow_lines(cls) -> List[str]:
        with cls._lock:
            rows = list(cls._shadow_events)
        out = []
        for t in rows[:V702_R28_TELEGRAM_DIGEST_TOP_SHADOW]:
            sym = cls._text(r"(?:^|\n)\s*([A-Z0-9_.\-]+/USDT)\s*\|", t, "?")
            event = cls._text(r"Event:\s*([^\n]+)", t, "?")
            mfe = cls._text(r"MFE:\s*([^\n]+)", t, "?")
            mae = cls._text(r"MAE:\s*([^\n]+)", t, "?")
            out.append(f"• {sym} {event} MFE={mfe} MAE={mae}")
        return out or ["• none"]

    @classmethod
    def build(cls) -> str:
        cls.start()
        with cls._lock:
            hb = cls._heartbeat
            starv = cls._starvation
            edge = cls._edge
            rej = cls._latest_rejection
            cats = dict(cls._category_counts)
            events = int(cls._events)
            last_flush = float(cls._last_flush_ts or cls._started_ts or WALL_NOW())
            selected = len(cls._selected_blocks)
            scorer_blocks = len(cls._scorer_blocks)
            route_blocks = len(cls._route_blocks)
            shadow = len(cls._shadow_events)
            discovery = len(cls._discovery_by_symbol)
        age = max(0.0, float(WALL_NOW()) - last_flush)
        # A51 throughput counters were already recorded in STATS; expose them
        # in the operator digest so the optimization is observable in the same
        # canonical channel as the funnel/rejection summary. These are process
        # totals, not per-window candidate-attributed counts.
        try:
            _a51_blocks = max(0, int(STATS.get("v702_a51_regime_policy_prefilter_blocks", 0) or 0))
            _a51_saved_checks = max(0, int(STATS.get("v702_a51_regime_policy_prefilter_saved_checks", 0) or 0))
            _a51_errors = max(0, int(STATS.get("v702_a51_regime_policy_prefilter_errors", 0) or 0))
            _a51_last_error = re.sub(r"[^A-Za-z0-9_.:-]", "", str(STATS.get("v702_a51_regime_policy_prefilter_last_error", "none") or "none"))[:40] or "none"
            _cf_policy_attempts = max(0, int(STATS.get("v702_cf_shadow_policy_reject_capture_attempts", 0) or 0))
            _cf_policy_stored = max(0, int(STATS.get("v702_cf_shadow_policy_reject_capture_stored", 0) or 0))
            _cf_policy_not_stored = max(0, int(STATS.get("v702_cf_shadow_policy_reject_capture_not_stored", 0) or 0))
            _cf_policy_pending = max(0, int(STATS.get("v702_cf_shadow_io_pending", 0) or 0))
            _cf_policy_drops = max(0, int(STATS.get("v702_cf_shadow_policy_reject_backpressure_drops", 0) or 0))
            _cf_policy_errors = max(0, int(STATS.get("v702_cf_shadow_policy_reject_capture_errors", 0) or 0))
            _cf_policy_enabled = bool(CONFIG.get("V702_CF_SHADOW_ENABLE", True) and CONFIG.get("V702_CF_SHADOW_POLICY_REJECT_OBSERVE_ENABLE", True))
            _cf_htf_attempts = max(0, int(STATS.get("v702_cf_shadow_htf_reject_capture_attempts", 0) or 0))
            _cf_htf_stored = max(0, int(STATS.get("v702_cf_shadow_htf_reject_capture_stored", 0) or 0))
            _cf_htf_not_stored = max(0, int(STATS.get("v702_cf_shadow_htf_reject_capture_not_stored", 0) or 0))
            _cf_htf_drops = max(0, int(STATS.get("v702_cf_shadow_htf_reject_backpressure_drops", 0) or 0))
            _cf_htf_errors = max(0, int(STATS.get("v702_cf_shadow_htf_reject_capture_errors", 0) or 0))
            _cf_htf_enabled = bool(CONFIG.get("V702_CF_SHADOW_ENABLE", True) and CONFIG.get("V702_CF_SHADOW_HTF_REJECT_OBSERVE_ENABLE", True))
        except Exception:
            _a51_blocks, _a51_saved_checks, _a51_errors, _a51_last_error = 0, 0, 0, "unavailable"
            _cf_policy_attempts, _cf_policy_stored, _cf_policy_not_stored = 0, 0, 0
            _cf_policy_pending, _cf_policy_drops, _cf_policy_errors, _cf_policy_enabled = 0, 0, 0, False
            _cf_htf_attempts, _cf_htf_stored, _cf_htf_not_stored, _cf_htf_drops, _cf_htf_errors, _cf_htf_enabled = 0, 0, 0, 0, 0, False
        _universe_status = str(STATS.get("v702_a66_universe_status", "UNKNOWN") or "UNKNOWN")[:18]
        _universe_size = max(0, int(STATS.get("v702_a66_universe_size", 0) or 0))
        _universe_last_ok = float(STATS.get("v702_a66_universe_last_success_ts", 0.0) or 0.0)
        _universe_age = max(0, int(float(WALL_NOW()) - _universe_last_ok)) if _universe_last_ok > 0 else -1
        _scan_status = str(STATS.get("v702_a66_scan_status", "NOT_STARTED") or "NOT_STARTED")[:22]
        _scan_symbols = max(0, int(STATS.get("v702_a66_scan_symbols_attempted", 0) or 0))
        _scan_tickers = max(0, int(STATS.get("v702_a66_scan_ticker_rows", 0) or 0))
        _universe_retry = max(0, min(300, int(float(CONFIG.get("V702_A66_UNIVERSE_EMPTY_RETRY_SEC", 60.0) or 60.0))))
        _universe_error = re.sub(r"[^A-Za-z0-9_.:-]", "", str(STATS.get("v702_a66_universe_last_error", "none") or "none"))[:34]
        lines = [
            "<b>📊 V702 OPERATOR DIGEST — CANONICAL</b>",
            f"Window≈{int(age)}s | compacted_events={events} | categories={sum(cats.values())}",
            f"UNIVERSE status={_universe_status} size={_universe_size} age_sec={_universe_age} retry_sec={_universe_retry} error={_universe_error} | SCAN status={_scan_status} symbols={_scan_symbols} ticker_rows={_scan_tickers}",
            f"A51_POLICY_PREFILTER process_total blocks={_a51_blocks} saved_checks={_a51_saved_checks} errors={_a51_errors} last_error={_a51_last_error}",
            f"CF_SHADOW_POLICY_REJECT enabled={str(_cf_policy_enabled).lower()} attempted={_cf_policy_attempts} stored={_cf_policy_stored} not_stored={_cf_policy_not_stored} io_pending_all={_cf_policy_pending} backpressure_drops={_cf_policy_drops} errors={_cf_policy_errors} | CF_SHADOW_HTF_REJECT enabled={str(_cf_htf_enabled).lower()} attempted={_cf_htf_attempts} stored={_cf_htf_stored} not_stored={_cf_htf_not_stored} backpressure_drops={_cf_htf_drops} errors={_cf_htf_errors}",
            cls._compact_counts(),
            "LEGEND: ENTRY_BLOCK_ROOT=current entry classifier; starvation root/top3=window classifier; exec_try=route attempts; live_ready=epoch total; stage totals are aggregates, not proof of same-candidate attribution.",
            cls._heartbeat_line(hb),
            cls._starvation_line(starv),
            cls._rejection_line(rej),
            "<b>TOP DISCOVERY</b>",
            *cls._discovery_lines(),
            "<b>SELECTED → SCORER BLOCK</b>",
            *cls._scorer_block_lines(),
            "<b>SELECTED → ROUTE BLOCK</b>",
            *cls._route_block_lines(),
            "<b>SELECTED → BUILDER BLOCK</b>",
            *cls._block_lines(),
            "<b>KNOWLEDGE SHADOW</b>",
            *cls._shadow_lines(),
            cls._edge_line(edge),
            f"buffered_latest: discovery={discovery} scorer_blocks={scorer_blocks} route_blocks={route_blocks} builder_blocks={selected} shadow={shadow} | selected_route={cls._selected_route_summary()}",
            "Execution orders/protection/control/errors remain immediate; no gate was relaxed.",
            "Use /digest for the latest compacted state on demand.",
        ]
        raw = "\n".join(lines)
        max_chars = max(1800, int(CONFIG.get("V702_R28_TELEGRAM_DIGEST_MAX_CHARS", V702_R28_TELEGRAM_DIGEST_MAX_CHARS) or V702_R28_TELEGRAM_DIGEST_MAX_CHARS))
        if len(raw) <= max_chars:
            return raw
        # Deterministic truncation preserves the complete policy/funnel header,
        # the tail status, AND every structural section heading. Earlier A59
        # truncation stopped at the first oversized discovery row, silently
        # dropping later scorer/route/builder headings. Skip oversized detail
        # rows instead of breaking, and reserve room for all middle headings.
        def _clip_digest_line(value, limit):
            value = str(value or "")
            return value if len(value) <= limit else value[:max(1, limit - 1)] + "…"

        # Bound volatile telemetry rows before calculating the remaining
        # allowance. Without this, a very long heartbeat/window line could
        # consume the entire message and physically cut off mandatory headings.
        head_limits = (42, 70, 100, 200, 300, 125, 90, 170, 70, 130)
        head = [_clip_digest_line(line, head_limits[i]) for i, line in enumerate(lines[:10])]
        tail_source = lines[-4:]
        tail_limits = (100, 220, 80, 45)
        tail = [_clip_digest_line(line, tail_limits[i]) for i, line in enumerate(tail_source)]
        middle = lines[len(lines[:10]):-4]
        mandatory = {i for i, line in enumerate(middle) if line.startswith("<b>") and line.endswith("</b>")}
        separator_cost = len("\n".join(head + ["…"] + tail))
        heading_cost = sum(len(middle[i]) + 1 for i in mandatory)
        middle_budget = max(0, max_chars - separator_cost - heading_cost)
        keep = set(mandatory)
        for i, line in enumerate(middle):
            if i in mandatory:
                continue
            cost = len(line) + 1
            if cost <= middle_budget:
                keep.add(i)
                middle_budget -= cost
        mids = [line for i, line in enumerate(middle) if i in keep]
        rendered = "\n".join(head + mids + ["…"] + tail)
        if len(rendered) <= max_chars:
            return rendered
        # The configured minimum is 1800 chars; if an operator lowers it
        # further in a custom build, retain all headings and the hard limit.
        mandatory_text = "\n".join(head + [middle[i] for i in sorted(mandatory)] + ["…"] + tail)
        return mandatory_text[:max_chars]

    @classmethod
    def reset_after_flush(cls) -> None:
        with cls._lock:
            cls._events = 0
            cls._category_counts = defaultdict(int)
            cls._heartbeat = ""
            cls._starvation = ""
            cls._edge = ""
            cls._latest_rejection = ""
            cls._rejection_captured = 0
            cls._selected_blocks.clear()
            cls._scorer_blocks.clear()
            cls._route_blocks.clear()
            cls._shadow_events.clear()
            cls._discovery_by_symbol = {}
            cls._last_flush_ts = float(WALL_NOW())

    @classmethod
    async def flush(cls, force: bool = False) -> bool:
        with cls._lock:
            events = int(cls._events)
            last_flush = float(cls._last_flush_ts or 0.0)
            started = float(cls._started_ts or 0.0)
        if events <= 0:
            return False
        interval = max(60.0, float(CONFIG.get("V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC", 1800.0) or 1800.0))
        if not force and last_flush and float(WALL_NOW()) - last_flush < interval:
            return False
        msg = cls.build()
        try:
            # This call is explicitly allowed to pass because it is the one
            # converged operator message produced by R28, not a compacted event.
            STATS["v702_r28_digest_flush_attempts"] = int(STATS.get("v702_r28_digest_flush_attempts", 0) or 0) + 1
            ok = await _V702_R28_RAW_ENQUEUE(msg)
            if ok is False:
                STATS["v702_r28_digest_send_fail"] = int(STATS.get("v702_r28_digest_send_fail", 0) or 0) + 1
                return False
            STATS["v702_r28_digest_flushes"] = int(STATS.get("v702_r28_digest_flushes", 0) or 0) + 1
            STATS["v702_r28_digest_last_event_count"] = events
            cls.reset_after_flush()
            return True
        except Exception as exc:
            STATS["v702_r28_digest_send_fail"] = int(STATS.get("v702_r28_digest_send_fail", 0) or 0) + 1
            logger.warning("[V702-R28-TG] digest flush suppressed: %s: %s", type(exc).__name__, exc)
            return False


# Keep the raw dispatcher method exactly once so the convergence wrapper never
# calls itself recursively.  The R696 wrapper is a bound classmethod here.
try:
    _V702_R28_RAW_ENQUEUE = TelegramDispatcher.enqueue
    if not bool(getattr(TelegramDispatcher, "_v702_r28_dispatcher_installed", False)):
        async def _v702_r28_enqueue(cls, message: str, on_success=None, on_failure=None):
            raw = str(message or "")
            category = _V702R28TelegramDigest.classify(raw)
            # Delivery callbacks imply semantic ownership of the individual
            # message.  Keep those messages immediate and never compact them.
            if bool(CONFIG.get("V702_R28_TELEGRAM_CONVERGENCE_ENABLE", True)) and category and not callable(on_success) and not callable(on_failure):
                _V702R28TelegramDigest.capture(category, raw)
                STATS["v702_r28_enqueue_compacted"] = int(STATS.get("v702_r28_enqueue_compacted", 0) or 0) + 1
                return True
            return await _V702_R28_RAW_ENQUEUE(raw, on_success=on_success, on_failure=on_failure)
        _v702_r28_enqueue._v702_r28_wrapper = True
        TelegramDispatcher.enqueue = classmethod(_v702_r28_enqueue)
        TelegramDispatcher._v702_r28_dispatcher_installed = True
except Exception as exc:
    logger.error("[V702-R28-TG] dispatcher convergence install failed: %s: %s", type(exc).__name__, exc)
    CONFIG["V702_R28_TELEGRAM_CONVERGENCE_ENABLE"] = False


async def _v702_r28_telegram_digest_task() -> None:
    _V702R28TelegramDigest.start()
    try:
        while _SHUTDOWN is None or not _SHUTDOWN.is_set():
            interval = max(30.0, float(CONFIG.get("V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC", 1800.0) or 1800.0))
            await asyncio.sleep(min(30.0, max(5.0, interval / 3.0)))
            await _V702R28TelegramDigest.flush(force=False)
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        logger.warning("[V702-R28-TG] digest task stopped: %s: %s", type(exc).__name__, exc)


# Add a single on-demand drill-down command without changing any dangerous
# order-control semantics.  /digest only reads in-memory telemetry.
try:
    _V702_R28_PREV_COMMAND_HANDLE = TelegramCommandController._handle
    if not getattr(_V702_R28_PREV_COMMAND_HANDLE, "_v702_r28_wrapped", False):
        async def _v702_r28_command_handle(cls, exchange, message: Dict[str, Any]) -> None:
            try:
                if cls._authorized(message):
                    txt = str(((message or {}).get("text") or "")).strip().split()
                    cmd = (txt[0].split("@", 1)[0].lower() if txt else "")
                    if cmd == "/digest":
                        await _V702_R28_RAW_ENQUEUE(f"<b>V561 CONTROL</b>\n{_V702R28TelegramDigest.build()}")
                        return
            except Exception as exc:
                STATS["v702_r28_command_digest_errors"] = int(STATS.get("v702_r28_command_digest_errors", 0) or 0) + 1
                logger.warning("[V702-R28-TG] /digest suppressed: %s: %s", type(exc).__name__, exc)
            await _V702_R28_PREV_COMMAND_HANDLE(cls, exchange, message)
        _v702_r28_command_handle._v702_r28_wrapped = True
        TelegramCommandController._handle = classmethod(_v702_r28_command_handle)
except Exception as exc:
    logger.warning("[V702-R28-TG] /digest command install suppressed: %s: %s", type(exc).__name__, exc)


def _v702_r28_install_run_bot() -> bool:
    try:
        prev = globals().get("run_bot")
        if not callable(prev) or getattr(prev, "_v702_r28_wrapped", False):
            return True
        async def _v702_r28_run_bot(universe: List[str]):
            digest_task = None
            try:
                _V702R28TelegramDigest.start()
                digest_task = asyncio.create_task(_v702_r28_telegram_digest_task())
                return await prev(universe)
            finally:
                try:
                    await _V702R28TelegramDigest.flush(force=True)
                except Exception as exc:
                    logger.warning("[V702-R28-TG] final digest flush suppressed: %s: %s", type(exc).__name__, exc)
                if digest_task is not None:
                    digest_task.cancel()
                    try:
                        await digest_task
                    except (asyncio.CancelledError, Exception):
                        pass
        _v702_r28_run_bot._v702_r28_wrapped = True
        globals()["run_bot"] = _v702_r28_run_bot
        return True
    except Exception as exc:
        logger.error("[V702-R28] run_bot convergence install failed: %s: %s", type(exc).__name__, exc)
        return False

V702_R28_RUN_BOT_INSTALLED = _v702_r28_install_run_bot()


def _v702_r28_final_self_test() -> Dict[str, Any]:
    checks: Dict[str, bool] = {}
    details: Dict[str, Any] = {}
    try:
        checks["closure_enabled"] = bool(CONFIG.get("V702_R28_FINAL_AUDIT_CLOSURE", False))
        checks["interval_is_converged"] = abs(float(CONFIG.get("V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC", 0) or 0) - 1800.0) < 1e-9
        checks["digest_max_chars"] = int(CONFIG.get("V702_R28_TELEGRAM_DIGEST_MAX_CHARS", 0) or 0) <= 3900
        samples = {
            "heartbeat": "<b>Heartbeat</b>\n<code>state=FULL_LIVE_RUNNING trades=0 funnel G/E/Q/S=85/0/0/0 exec_try=78 live_ready=0 send_fail=0 regime=BULLISH starv_mode=LIQUIDITY root=LIQUIDITY TG[D=0]</code>",
            "discovery": "<b>ℹ️ DISCOVERY SIGNAL — KNOWLEDGE ONLY</b>\n\n<b>TEST/USDT</b>\nStrategy: <b>PULLBACK</b>\nEngine Score: 99.1 | Reviewed Score: 95.6 | Projected Canonical Live Score: 60.5 | HTF: 63.5 | Vol: x1.59 | RS: 0.00% | Chase: 0.09 ATR | Tier: MAJORS\nContext: <b>VERIFIED</b>",
            "rejection": "🧾 <b>REJECTION BATCH</b>\nRejected evaluations: 100 | Notification groups: 10 | Unique opportunities: 40\nSYSTEM=0 POLICY=20 HTF=5 LIQUIDITY=50 STRUCTURE=20 SCORE=5 FEE=0 PRE_SEND=0 EXECUTION=0 OTHER=0",
            "starvation": "[V422-StarvAlert] mode=LIQUIDITY | generated_delta=100 prequal_pass_delta=3 ranked_delta=3 selected_delta=1 queued_delta=0 sent_delta=0",
            "shadow": "🛑 <b>KNOWLEDGE SHADOW — STOP LOSS REACHED</b>\n\n<b>TEST/USDT | PULLBACK</b>\nEntry: 1 | Event: SL\nMFE: +0.1R | MAE: -1.0R",
            "edge": "📈 <b>KNOWLEDGE EDGE REPORT — SHADOW ONLY</b>\nAlerts: 8 | Entries: 8 | TP1 hit: 3 | TP2: 1 | TP3: 0 | SL hit: 8\nFirst-touch expectancy: -0.24R",
            "builder_block": "<b>Selected → Builder BLOCK</b>\nTEST/USDT\nroot=LIQUIDITY\nstage=v45_orderbook\nreason=reject.liquidity.v45_micro_orderbook_confirmation",
        }
        expected = {
            "heartbeat": "heartbeat", "discovery": "discovery", "rejection": "rejection",
            "starvation": "starvation", "shadow": "shadow", "edge": "edge", "builder_block": "builder_block",
        }
        checks["classifier_categories"] = all(_V702R28TelegramDigest.classify(v) == expected[k] for k, v in samples.items())
        # Keep the real buffer state unchanged after the synthetic probe.
        before = _V702R28TelegramDigest.build()
        _V702R28TelegramDigest.capture("discovery", samples["discovery"])
        _V702R28TelegramDigest.capture("heartbeat", samples["heartbeat"])
        after = _V702R28TelegramDigest.build()
        checks["digest_contains_header"] = "V702 OPERATOR DIGEST" in after
        checks["digest_bounded"] = len(after) <= int(CONFIG.get("V702_R28_TELEGRAM_DIGEST_MAX_CHARS", 3700) or 3700)
        checks["discovery_compaction"] = "TEST/USDT" in after
        details["synthetic_before_len"] = len(before)
        details["synthetic_after_len"] = len(after)
        details["run_bot_installed"] = bool(V702_R28_RUN_BOT_INSTALLED)
        details["dispatcher_installed"] = bool(getattr(TelegramDispatcher, "_v702_r28_dispatcher_installed", False))
        checks["run_bot_wrapped"] = bool(V702_R28_RUN_BOT_INSTALLED)
        checks["dispatcher_wrapped"] = bool(getattr(TelegramDispatcher, "_v702_r28_dispatcher_installed", False))
        try:
            import inspect as _inspect_v702_r28
            dispatcher_sig = _inspect_v702_r28.signature(TelegramDispatcher.enqueue.__func__)
            checks["dispatcher_classmethod_signature"] = bool(tuple(dispatcher_sig.parameters)[:1] == ("cls",))
            details["dispatcher_signature"] = str(dispatcher_sig)
        except Exception:
            checks["dispatcher_classmethod_signature"] = False
        # Critical messages must remain immediate by classification contract.
        checks["critical_execution_not_compacted"] = _V702R28TelegramDigest.classify("ORDER FILLED\nEXECUTION SUCCESS") == ""
        # Restore synthetic probe so the production buffer starts clean.
        _V702R28TelegramDigest.reset_after_flush()
        out = {"pass": bool(all(checks.values())), "checks": checks, "details": details, "closure": V702_R28_CLOSURE_ID}
        STATS["v702_r28_final_self_test"] = out
        return out
    except Exception as exc:
        out = {"pass": False, "checks": checks, "details": details, "error": f"{type(exc).__name__}:{exc}", "closure": V702_R28_CLOSURE_ID}
        STATS["v702_r28_final_self_test"] = out
        try:
            _V702R28TelegramDigest.reset_after_flush()
        except Exception:
            pass
        return out

_V702_R28_FINAL_SELF_TEST = _v702_r28_final_self_test()

