# --- New additive specialist engine ----------------------------------------
class LiquidityAcceptanceReclaimEngine(_EngineBase):
    """Long-only liquidity reclaim setup with explicit acceptance confirmation.

    This detector is intentionally selective. It detects a prior support sweep,
    a closed-bar reclaim, an acceptance hold, a higher-low, and a confirmation
    break with volume/RS/trend alignment. It only returns StrategyCandidate;
    it never submits, cancels, or protects orders.
    """
    engine_id = "liquidity_acceptance_reclaim"
    family_map = ("CONTINUATION_RECLAIM",)
    strategy_mode = "LIQUIDITY_ACCEPTANCE_RECLAIM"

    @classmethod
    def _config_enabled(cls):
        return bool(CONFIG.get("LAR_ENABLE", True)) and bool(CONFIG.get("V43_ADAPTIVE_ROUTER_ENABLE", True))

    @classmethod
    def generate(cls, snapshot):
        if not cls._config_enabled():
            return []
        symbol = str(snapshot.get("symbol") or "?")
        try:
            sev = _v43_macro_severity(snapshot)
            if not V425BearishSeverity.allows_new_long(sev):
                return []
            regime = str(snapshot.get("regime") or snapshot.get("macro_regime") or "").upper()
            local = str(snapshot.get("local_regime") or "").upper()
            phase_obj = snapshot.get("market_phase")
            phase = str(phase_obj.get("phase", "UNKNOWN") if isinstance(phase_obj, dict) else (phase_obj or "UNKNOWN")).upper()
            if not FamilyPolicyLayer.strategy_allowed(
                "LIQUIDITY_ACCEPTANCE_RECLAIM", regime, local, phase, sev, "SCALP"
            ):
                return []
            tier = str(snapshot.get("tier") or "").upper()
            if tier and _F456_TIER_RANK.get(tier, -1) < _F456_TIER_RANK.get(str(CONFIG.get("LAR_MIN_TIER", "MID")).upper(), 0):
                return []
            try:
                htf_strength = float(snapshot.get("htf_strength", 0.0) or 0.0)
            except Exception:
                return []
            if not math.isfinite(htf_strength) or htf_strength < float(CONFIG.get("LAR_MIN_HTF_STRENGTH", 55.0)):
                return []
            d15 = snapshot.get("df_15m")
            d5 = snapshot.get("df_5m")
            if not _PDNP_OK or d15 is None or d5 is None or len(d15) < 60 or len(d5) < 50:
                return []
            if not all(col in d5.columns for col in ("open", "high", "low", "close", "volume")):
                return []
            if not all(col in d15.columns for col in ("open", "high", "low", "close")):
                return []

            f15 = _v43_closed_features(d15, "15m")
            f5 = _v43_closed_features(d5, "5m")
            if f15 is None or f5 is None:
                return []
            if not (math.isfinite(float(f5.get("atr", 0.0) or 0.0)) and float(f5.get("atr", 0.0) or 0.0) > 0):
                return []
            atr5 = float(f5["atr"])
            atr15 = float(f15.get("atr", atr5) or atr5)
            if atr15 <= 0 or not math.isfinite(atr15):
                return []

            closes15 = d15["close"].astype(float)
            lows15 = d15["low"].astype(float)
            highs15 = d15["high"].astype(float)
            n15 = int(CONFIG.get("LAR_SUPPORT_LOOKBACK_15M", 22) or 22)
            # Use only closed 15m bars and exclude the most recent two from the
            # structural reference so the current move cannot define its own level.
            ref_slice = lows15.iloc[-(n15 + 2):-2]
            if len(ref_slice) < max(10, n15 // 2):
                return []
            support = float(ref_slice.min())
            if support <= 0 or not math.isfinite(support):
                return []

            sweep = d5.iloc[-4]
            acceptance = d5.iloc[-3]
            confirmation = d5.iloc[-2]
            current_closed = d5.iloc[-2]
            for row in (sweep, acceptance, confirmation):
                if not all(math.isfinite(float(row[k])) for k in ("open", "high", "low", "close", "volume")):
                    return []

            sweep_low = float(sweep["low"])
            sweep_close = float(sweep["close"])
            sweep_range = max(float(sweep["high"]) - sweep_low, 1e-12)
            acceptance_low = float(acceptance["low"])
            acceptance_close = float(acceptance["close"])
            confirmation_open = float(confirmation["open"])
            confirmation_close = float(confirmation["close"])
            confirmation_high = float(confirmation["high"])
            confirmation_low = float(confirmation["low"])
            confirmation_range = max(confirmation_high - confirmation_low, 1e-12)
            confirmation_body = abs(confirmation_close - confirmation_open) / confirmation_range

            swept = sweep_low < support
            reclaim = sweep_close > support
            acceptance_hold = acceptance_low >= support and acceptance_close > support
            higher_low = acceptance_low > sweep_low
            confirmation_break = confirmation_close > float(acceptance["high"]) and confirmation_close > confirmation_open
            trend_alignment = bool(
                float(f15["close"]) > float(f15["ema20"]) > float(f15["ema50"])
            )

            sweep_depth_atr = max(0.0, (support - sweep_low) / atr5)
            post_reclaim_gap_atr = max(0.0, (confirmation_close - support) / atr5)
            if sweep_depth_atr > float(CONFIG.get("LAR_SWEEP_MAX_ATR", 0.85)):
                return []
            if post_reclaim_gap_atr > float(CONFIG.get("LAR_MAX_GAP_ATR", 0.90)):
                return []
            if confirmation_body < float(CONFIG.get("LAR_CONFIRM_BODY_MIN", 0.35)):
                return []

            # Volume is measured on the confirmation closed bar vs a neutral
            # closed-bar baseline excluding the latest signal bars.
            vol_base = d5["volume"].astype(float).iloc[-26:-4]
            vol_mean = float(vol_base.mean()) if len(vol_base) else 0.0
            volume_ratio = float(confirmation["volume"]) / vol_mean if vol_mean > 0 else 0.0
            if not math.isfinite(volume_ratio) or volume_ratio < float(CONFIG.get("LAR_MIN_VOLUME_RATIO", 1.20)):
                return []

            btc5 = snapshot.get("df_btc_5m")
            btc15 = snapshot.get("df_btc_15m")
            btc1h = snapshot.get("df_btc_1h")
            d1h = snapshot.get("df_1h")
            if btc5 is not None and btc15 is not None and d1h is not None and btc1h is not None:
                rs = compute_relative_strength(d5, btc5, d15, btc15, d1h, btc1h, 8, 8)
            else:
                fallback_rs = snapshot.get("rs_5m", snapshot.get("rs", 0.0))
                try:
                    rr = float(fallback_rs or 0.0)
                    rs = {"rs_valid": math.isfinite(rr), "rs_5m": rr, "rs_15m": rr, "rs_persistence": 1.0}
                except Exception:
                    rs = {"rs_valid": False}
            if not rs.get("rs_valid") or rs.get("rs_5m") is None:
                return []
            rs5 = float(rs.get("rs_5m", 0.0) or 0.0)
            rs15 = float(rs.get("rs_15m", rs5) or rs5)
            if not math.isfinite(rs5) or rs5 < float(CONFIG.get("LAR_MIN_RS_5M", 0.0)):
                return []

            chase = max(0.0, (confirmation_close - float(f5["ema20"])) / max(atr5, 1e-12))
            if chase > float(CONFIG.get("LAR_MAX_CHASE_ATR", 1.10)):
                return []
            if not swept or not reclaim or not acceptance_hold or not higher_low or not confirmation_break or not trend_alignment:
                return []

            acceptance_distance = max(0.0, acceptance_close - support) / max(atr5, 1e-12)
            acceptance_quality = _clamp(
                0.55 * _clamp(1.0 - abs(acceptance_low - support) / max(atr5, 1e-12), 0.0, 1.0)
                + 0.45 * _clamp(acceptance_distance / 0.75, 0.0, 1.0),
                0.0, 1.0
            )
            if acceptance_quality < float(CONFIG.get("LAR_MIN_ACCEPTANCE_QUALITY", 0.60)):
                return []

            trend_quality = _clamp((float(f15["close"]) - float(f15["ema20"])) / max(atr15, 1e-12), 0.0, 1.0)
            volume_quality = _clamp((volume_ratio - 1.0) / 1.0, 0.0, 1.0)
            confirmation_quality = _clamp(confirmation_body / 0.80, 0.0, 1.0)
            sweep_quality = _clamp(1.0 - sweep_depth_atr / max(float(CONFIG.get("LAR_SWEEP_MAX_ATR", 0.85)), 1e-9), 0.0, 1.0)
            chase_quality = _clamp(1.0 - chase / max(float(CONFIG.get("LAR_MAX_CHASE_ATR", 1.10)), 1e-9), 0.0, 1.0)
            rs_quality = _clamp(rs5 * 20.0, 0.0, 1.0)
            score = _clamp(
                0.48
                + 0.10 * sweep_quality
                + 0.12 * acceptance_quality
                + 0.10 * confirmation_quality
                + 0.08 * volume_quality
                + 0.05 * rs_quality
                + 0.04 * trend_quality
                + 0.03 * chase_quality,
                0.0, 1.0
            )
            if score * 100.0 < float(CONFIG.get("LAR_MIN_SCORE", 72.0)):
                return []

            entry = confirmation_close
            sl = sweep_low - 0.15 * atr5
            if not (math.isfinite(entry) and math.isfinite(sl) and 0 < sl < entry):
                return []
            profile = StrategyExitProfiles.profile_for("LIQUIDITY_ACCEPTANCE_RECLAIM", "SCALP")
            feats = {
                "strategy_mode": "LIQUIDITY_ACCEPTANCE_RECLAIM",
                "strategy_style": "SCALP",
                "timeframe_profile": "15M_5M",
                "macro_regime": regime,
                "local_regime": local,
                "market_phase": phase,
                "bearish_severity": sev,
                "hard_valid": True,
                "liquidity_acceptance_reclaim": True,
                "sweep": True,
                "reclaim": True,
                "acceptance": True,
                "acceptance_hold": True,
                "higher_low": True,
                "confirmation_break": True,
                "trend_alignment": True,
                "support_ref": support,
                "sweep_depth_atr": sweep_depth_atr,
                "acceptance_quality": acceptance_quality,
                "confirmation_body": confirmation_body,
                "volume_ratio": volume_ratio,
                "rs_5m": rs5,
                "rs_15m": rs15,
                "rs_persistence": float(rs.get("rs_persistence", 0.0) or 0.0),
                "chase_atr": chase,
                "structure_quality": _clamp(0.70 * acceptance_quality + 0.30 * confirmation_quality, 0.0, 1.0),
                "volume_quality": volume_quality,
                "retest_quality": acceptance_quality,
                "htf_alignment": _clamp(float(snapshot.get("htf_strength", 0.0) or 0.0) / 100.0, 0.0, 1.0),
                "phase_fit": 0.90 if phase in {"TREND", "EXPANSION", "BREAKOUT"} else 0.78,
                "local_fit": 0.90 if local in {"LOCAL_BULLISH", "LOCAL_RECOVERY"} else 0.75,
                "target_rr": float(profile.tp2_rr),
                "execution_quality": 0.88,
                "exit_profile": asdict(profile),
            }
            cand = _v43_base_candidate(
                cls.engine_id, symbol, entry, atr5, float(CONFIG.get("ATR_SL_MULT", 1.2)),
                (float(profile.tp1_rr), float(profile.tp2_rr), float(profile.tp3_rr)),
                score, tier, regime, "CONTINUATION_RECLAIM", support, feats, sl_override=sl
            )
            if cand:
                STATS["v702_r29_lar_generated"] = int(STATS.get("v702_r29_lar_generated", 0) or 0) + 1
            return [cand] if cand else []
        except Exception as exc:
            STATS["v702_r29_lar_runtime_errors"] = int(STATS.get("v702_r29_lar_runtime_errors", 0) or 0) + 1
            logger.warning("[V702-R29][LAR] %s isolated exception: %s: %s", symbol, type(exc).__name__, exc)
            return []


