# --- R29 Telegram observability closure ------------------------------------
try:
    # Summary messages must be compacted too; otherwise V702 periodic summary
    # bypasses the R28 classifier and creates a second Telegram stream.
    _V702_R29_ORIG_CLASSIFY = _V702R28TelegramDigest.classify
    @classmethod
    def _v702_r29_classify(cls, raw):
        s = cls._strip(raw)
        u = s.upper()
        if "UNIFIED SCALPER V702 CANONICAL PERIODIC SUMMARY" in u:
            return "summary"
        return _V702_R29_ORIG_CLASSIFY(raw)
    _V702R28TelegramDigest.classify = _v702_r29_classify
    _V702R28TelegramDigest._periodic_summary = ""
    def _v702_r29_capture(cls, category, raw, on_success=None, on_failure=None):
        # Preserve callback ownership for deferred knowledge registration.
        text = cls._strip(raw)
        cls.start()
        with cls._lock:
            cls._events += 1
            cls._category_counts[category] += 1
        if category == "discovery":
            cls._capture_discovery(text, on_success=on_success, on_failure=on_failure)
        elif category == "heartbeat":
            with cls._lock: cls._heartbeat = text
        elif category == "starvation":
            with cls._lock: cls._starvation = text
        elif category == "edge":
            with cls._lock: cls._edge = text
        elif category == "summary":
            with cls._lock: cls._periodic_summary = text
        elif category == "rejection":
            with cls._lock:
                cls._latest_rejection = text
                cls._rejection_captured += 1
        elif category == "scorer_block":
            with cls._lock: cls._scorer_blocks.appendleft(text)
        elif category == "route_block":
            with cls._lock: cls._route_blocks.appendleft(text)
        elif category == "builder_block":
            with cls._lock: cls._selected_blocks.appendleft(text)
        elif category == "shadow":
            with cls._lock: cls._shadow_events.appendleft(text)
        STATS["v702_r29_telegram_compacted_events"] = int(STATS.get("v702_r29_telegram_compacted_events", 0) or 0) + 1
        STATS[f"v702_r29_captured_{category}"] = int(STATS.get(f"v702_r29_captured_{category}", 0) or 0) + 1
    _V702R28TelegramDigest.capture = classmethod(_v702_r29_capture)
except Exception as exc:
    STATS["v702_r29_telegram_patch_capture_error"] = f"{type(exc).__name__}:{exc}"

# Replace discovery capture so latest deduplicated row retains callbacks.
try:
    _V702_R29_OLD_CAPTURE_DISCOVERY = _V702R28TelegramDigest._capture_discovery.__func__
    @classmethod
    def _v702_r29_capture_discovery(cls, text, on_success=None, on_failure=None):
        symbol = cls._text(r"(?:^|\n)\s*([A-Z0-9_.\-]+/USDT)\s*(?:\n|$)", text, "UNKNOWN/USDT")
        strategy = cls._text(r"Strategy:\s*([^\n]+)", text, "?")
        engine = cls._num(r"Engine Score:\s*([0-9.]+)", text, -1.0)
        reviewed = cls._num(r"Reviewed Score:\s*([0-9.]+)", text, -1.0)
        projected = cls._num(r"Projected Canonical Live Score:\s*([0-9.]+)", text, -1.0)
        htf = cls._num(r"HTF:\s*([0-9.]+)", text, -1.0)
        vol = cls._num(r"Vol:\s*x?([0-9.]+)", text, -1.0)
        rs = cls._num(r"RS:\s*([-0-9.]+)%", text, 0.0)
        chase = cls._num(r"Chase:\s*([-0-9.]+)\s*ATR", text, -1.0)
        tier = cls._text(r"Tier:\s*([^\n]+)", text, "?")
        context = cls._text(r"Context:\s*([^\n]+)", text, "?")
        now = float(WALL_NOW())
        row = {"symbol":symbol,"strategy":strategy,"engine":engine,"reviewed":reviewed,"projected":projected,
               "htf":htf,"vol":vol,"rs":rs,"chase":chase,"tier":tier,"context":context,"raw":text,"ts":now,
               "on_success":on_success,"on_failure":on_failure}
        with cls._lock:
            old = cls._discovery_by_symbol.get(symbol)
            if old and (float(old.get("ts",0.0)) > now - 2.0) and float(old.get("projected",-1.0)) > projected:
                return
            cls._discovery_by_symbol[symbol] = row
            if len(cls._discovery_by_symbol) > 40:
                ordered = sorted(cls._discovery_by_symbol.values(), key=lambda x: float(x.get("ts",0.0)), reverse=True)[:40]
                cls._discovery_by_symbol = {str(x["symbol"]):x for x in ordered}
    _V702R28TelegramDigest._capture_discovery = _v702_r29_capture_discovery
except Exception as exc:
    STATS["v702_r29_telegram_patch_discovery_error"] = f"{type(exc).__name__}:{exc}"

# Rich, bounded rejection diagnosis and strategy health in the digest.
def _v702_r29_section_line(text, heading, default="-"):
    try:
        h = str(heading or "").strip().lower()
        lines = [x.strip() for x in str(text or "").replace("\r", "").split("\n")]
        for i, line in enumerate(lines):
            clean_line = re.sub(r"<[^>]+>", "", line).strip()
            low = clean_line.lower()
            # The digest section banner is "Top reasons / stages / exception types";
            # it must not be mistaken for the actual reason-list heading.
            if h == "top reasons" and low.startswith("top reasons / stages / exception types"):
                continue
            if h == "top reasons":
                matched = (low == "top reasons" or low.startswith("top reasons:"))
            else:
                matched = low.startswith(h)
            if matched:
                # Preserve inline payload when the heading is on the same line.
                inline = clean_line[len(str(heading)):].strip() if len(clean_line) >= len(str(heading)) else ""
                if inline:
                    return inline
                for nxt in lines[i+1:]:
                    clean_next = re.sub(r"<[^>]+>", "", nxt).strip()
                    if clean_next:
                        return clean_next
    except Exception:
        pass
    return default

@classmethod
def _v702_r29_rejection_line(cls, text):
    if not text:
        return "rejections=-"
    ev=cls._text(r"Rejected evaluations:\s*([0-9]+)",text,"0")
    groups=cls._text(r"Notification groups:\s*([0-9]+)",text,"0")
    uniq=cls._text(r"Unique opportunities:\s*([0-9]+)",text,"0")
    vals=[cls._text(rf"{k}=([0-9]+)",text,"0") for k in ("SYSTEM","POLICY","HTF","LIQUIDITY","STRUCTURE","SCORE")]
    top=_v702_r29_section_line(text,"Top reasons","-")[:180]
    stages=_v702_r29_section_line(text,"Stages:","-")[:160]
    families=_v702_r29_section_line(text,"Top families","-")[:160]
    reps=[]
    for line in str(text or "").splitlines():
        clean=re.sub(r"^\s*[•\-]\s*","",line).strip()
        if clean and ("/USDT" in clean) and "—" in clean:
            reps.append(clean[:170])
    reps=reps[:int(CONFIG.get("V702_R29_TELEGRAM_DIGEST_MAX_REJECTION_ROWS",4) or 4)]
    return (
        f"rejections latest_window: evals={ev} groups={groups} unique={uniq} | "
        f"S/P/H/L/ST/S={vals[0]}/{vals[1]}/{vals[2]}/{vals[3]}/{vals[4]}/{vals[5]} | "
        f"top_reason={top} | stages={stages} | families={families}" +
        (" | reps=" + " || ".join(reps) if reps else "")
    )
_V702R28TelegramDigest._rejection_line = _v702_r29_rejection_line

@classmethod
def _v702_r29_starvation_line(cls, text):
    if not text:
        return "starvation=-"
    mode=cls._text(r"mode=([^\s|]+)",text,"NONE")
    vals=[cls._text(rf"{k}=([0-9]+)",text,"0") for k in ("generated_delta","prequal_pass_delta","ranked_delta","selected_delta","queued_delta","sent_delta")]
    root=cls._text(r"live_root=([^\s|]+)",text,"NONE")
    if root=="NONE": root=cls._text(r"root=([^\s|]+)",text,"NONE")
    no_send=cls._text(r"no_send_sec=([0-9.]+)",text,"0")
    top3=cls._text(r"current_cycle_top3=([^|]+)",text,"")
    if not top3: top3=cls._text(r"top3=([^|]+)",text,"-")
    top3_text = top3.strip()[:180]
    notice = ""
    try:
        pairs = [(str(k).upper(), int(v)) for k, v in re.findall(r"([A-Z_]+):([0-9]+)", top3_text)]
        total = sum(max(0, v) for _, v in pairs)
        policy_count = sum(max(0, v) for k, v in pairs if k == "POLICY")
        if (str(root).upper() == "POLICY" and "POLICY" in str(mode).upper()
                and float(no_send or 0) >= 1800.0 and total > 0
                and policy_count / total >= 0.90):
            notice = " | NO_SEND_NOTICE=POLICY_DOMINANT_OVER_30M;CHECK_HEALTH_AND_MARKET_COMPATIBILITY"
    except Exception:
        notice = ""
    return f"starvation mode={mode} G/P/R/SEL/Q/S={'/'.join(vals)} root={root} no_send={no_send}s top3={top3_text}{notice}"
_V702R28TelegramDigest._starvation_line = _v702_r29_starvation_line

@classmethod
def _v702_r29_heartbeat_line(cls, text):
    if not text: return "heartbeat=-"
    state=cls._text(r"state=([^\s]+)",text,"")
    trades=cls._text(r"trades=([^\s]+)",text,"")
    funnel=cls._text(r"funnel G/E/Q/S=([^\s]+)",text,"")
    exec_try=cls._text(r"exec_try=([^\s]+)",text,"")
    exec_try_scope=cls._text(r"exec_try_scope=([^\s]+)",text,"")
    exec_try_cycle=cls._text(r"exec_try_cycle=([^\s]+)",text,"")
    live_ready=cls._text(r"live_ready=([^\s]+)",text,"")
    live_ready_scope=cls._text(r"live_ready_scope=([^\s]+)",text,"")
    send_fail=cls._text(r"send_fail=([^\s]+)",text,"")
    regime=cls._text(r"regime=([^\s]+)",text,"")
    sev=cls._text(r"sev=([^\s]+)",text,"")
    starv=cls._text(r"starv_mode=([^\s]+)",text,"")
    entry_status=cls._text(r"ENTRY_STATUS=([^\s]+)",text,"")
    mh=re.search(r"MSE_RANK\[([^\]]+)\]",text)
    mserank=mh.group(1)[:160] if mh else ""
    sh=re.search(r"STRAT_HEALTH\[([^\]]+)\]",text)
    strat=sh.group(1)[:120] if sh else ""
    tg=re.search(r"TG\[([^\]]+)\]",text)
    tgline=tg.group(1)[:90] if tg else ""
    parts=[f"state={state}",f"trades={trades}",f"funnel={funnel}",f"exec_try={exec_try}"]
    if exec_try_scope: parts.append("exec_scope="+exec_try_scope)
    if exec_try_cycle: parts.append("exec_try_cycle="+exec_try_cycle)
    parts.append(f"live_ready={live_ready}")
    if live_ready_scope: parts.append("live_ready_scope="+live_ready_scope)
    parts.extend([f"send_fail={send_fail}",f"regime={regime}",f"sev={sev}",f"starv_mode={starv}",f"ENTRY_STATUS={entry_status}"])
    if strat: parts.append("strategy="+strat)
    if mserank: parts.append("rank="+mserank)
    if tgline: parts.append("TG="+tgline)
    try:
        _mr_mode=str(STATS.get("v702_r30_micro_recall_trigger","") or "")
        _mr_n=int(STATS.get("v702_r30_micro_recall_selected",0) or 0)
        if _mr_mode: parts.append(f"micro={_mr_mode}:{_mr_n}")
        _mr_diag = STATS.get("v702_r30_micro_recall_diagnostics", {}) or {}
        if isinstance(_mr_diag, dict) and _mr_mode:
            _rej = _mr_diag.get("rejected", {}) or {}
            parts.append("microdiag=" +
                f"eligible:{int(_mr_diag.get('eligible_rows',0) or 0)}" +
                f"/warm:{int(_mr_diag.get('warm_pool',0) or 0)}" +
                f"/recent:{int(_rej.get('recent',0) or 0)}" +
                f"/quote:{int(_rej.get('bad_quote',0) or 0)}" +
                f"/spot:{int(_rej.get('not_spot',0) or 0)}" +
                f"/forbid:{int(_rej.get('forbidden',0) or 0)}")
        _pd = int(STATS.get("v703_route_projection_incomplete_deferred", 0) or 0)
        if _pd: parts.append(f"projection_deferred={_pd}")
    except Exception:
        pass
    return "heartbeat="+" ".join(x for x in parts if not x.endswith("="))
_V702R28TelegramDigest._heartbeat_line = _v702_r29_heartbeat_line

@classmethod
def _v702_r29_summary_line(cls, text):
    if not text: return "summary=-"
    m=re.search(r"V702 FUNNEL\s+([^\n]+)", text, flags=re.I)
    return "summary="+(m.group(1).strip()[:220] if m else "seen")
_V702R28TelegramDigest._summary_line = _v702_r29_summary_line

# Wrap build to include the periodic summary without allowing it to dominate.
_V702_R29_OLD_BUILD = _V702R28TelegramDigest.build.__func__
@classmethod
def _v702_r29_build(cls):
    # Reuse the existing bounded builder but expose summary through the final
    # compacted line set by replacing its trailing operator note.
    raw = _V702_R29_OLD_BUILD(cls)
    with cls._lock:
        summary = getattr(cls, "_periodic_summary", "")
        discovery = len(cls._discovery_by_symbol)
        blocks = len(cls._selected_blocks)
        shadow = len(cls._shadow_events)
    if summary:
        ins = cls._summary_line(summary)
        marker = "buffered_latest: discovery="
        pos = raw.find(marker)
        if pos >= 0:
            raw = raw[:pos] + ins + "\n" + raw[pos:]
        else:
            raw += "\n" + ins
    return raw
_V702R28TelegramDigest.build = _v702_r29_build

# Ensure summary state resets only after successful digest delivery.
_V702_R29_OLD_RESET = _V702R28TelegramDigest.reset_after_flush.__func__
@classmethod
def _v702_r29_reset(cls):
    _V702_R29_OLD_RESET(cls)
    with cls._lock:
        cls._periodic_summary = ""
_V702R28TelegramDigest.reset_after_flush = _v702_r29_reset

# Finalize deferred callbacks after digest success. The raw dispatcher can be
# called only by the digest flush itself here; critical messages remain direct.
_V702_R29_OLD_FLUSH = _V702R28TelegramDigest.flush.__func__
async def _v702_r29_flush(cls, force=False):
    try:
        with cls._lock:
            callbacks=[]
            for row in cls._discovery_by_symbol.values():
                okcb=row.get("on_success")
                failcb=row.get("on_failure")
                if callable(okcb) or callable(failcb):
                    callbacks.append((okcb,failcb))
        ok = await _V702_R29_OLD_FLUSH(cls, force=force)
        if ok and callbacks:
            for success, failure in callbacks:
                try:
                    if callable(success):
                        if inspect.iscoroutinefunction(success):
                            r = await success("digest_delivered")
                        else:
                            r = await asyncio.to_thread(success, "digest_delivered")
                        if inspect.isawaitable(r):
                            await r
                except Exception:
                    try:
                        if callable(failure):
                            if inspect.iscoroutinefunction(failure):
                                r = await failure("digest_callback_error")
                            else:
                                r = await asyncio.to_thread(failure, "digest_callback_error")
                            if inspect.isawaitable(r): await r
                    except Exception:
                        pass
            STATS["v702_r29_deferred_knowledge_callbacks_flushed"] = int(STATS.get("v702_r29_deferred_knowledge_callbacks_flushed",0) or 0)+len(callbacks)
        return bool(ok)
    except Exception as exc:
        STATS["v702_r29_flush_error"] = f"{type(exc).__name__}:{exc}"
        return False
_V702R28TelegramDigest.flush = classmethod(_v702_r29_flush)

# Install a callback-aware compacting enqueue. The discovered messages are
# buffered even when they carry delivery callbacks; the callback is executed
# only when the containing operator digest is delivered successfully.
try:
    _V702_R29_RAW_ENQUEUE_2 = TelegramDispatcher.enqueue
    async def _v702_r29_enqueue(cls, message: str, on_success=None, on_failure=None):
        raw = str(message or "")
        category = _V702R28TelegramDigest.classify(raw)
        if bool(CONFIG.get("V702_R28_TELEGRAM_CONVERGENCE_ENABLE", True)) and category:
            _V702R28TelegramDigest.capture(category, raw, on_success=on_success, on_failure=on_failure)
            STATS["v702_r29_enqueue_compacted"] = int(STATS.get("v702_r29_enqueue_compacted",0) or 0)+1
            return True
        return await _V702_R29_RAW_ENQUEUE_2(raw, on_success=on_success, on_failure=on_failure)
    TelegramDispatcher.enqueue = classmethod(_v702_r29_enqueue)
    TelegramDispatcher._v702_r29_dispatcher_installed = True
except Exception as exc:
    STATS["v702_r29_telegram_dispatcher_error"] = f"{type(exc).__name__}:{exc}"

# --- Current validation: historical V702/R28 stays as prerequisite baseline;
#     current R29 invariants are additive and are validated against current
#     runtime state. This prevents legacy exact-17 checks from invalidating a
#     deliberate additive strategy expansion.
def _v702_r29_make_fixture(n=160, start=100.0, drift=0.045):
    if not _PDNP_OK:
        return None
    idx5 = pd.date_range("2026-01-01", periods=n, freq="5min")
    close5 = np.array([start + drift*i for i in range(n)], dtype=float)
    d5 = pd.DataFrame({"open":close5-0.05,"high":close5+0.12,"low":close5-0.12,"close":close5,"volume":np.full(n,100.0)}, index=idx5)
    idx15 = pd.date_range("2026-01-01", periods=max(80, n//3), freq="15min")
    close15 = np.array([start*0.96 + (drift*3)*i for i in range(len(idx15))], dtype=float)
    d15 = pd.DataFrame({"open":close15-0.08,"high":close15+0.18,"low":close15-0.18,"close":close15,"volume":np.full(len(idx15),300.0)}, index=idx15)
    # Create a rising trend, then compute the final closed support and place a
    # deterministic sweep/reclaim/acceptance/confirmation pattern around it.
    support = float(d15["low"].astype(float).iloc[-24:-2].min())
    base_idx = d5.index
    vals={
        -4:{"open":support+0.20,"high":support+0.85,"low":support-0.35,"close":support+0.35,"volume":180.0},
        -3:{"open":support+0.28,"high":support+0.42,"low":support+0.18,"close":support+0.34,"volume":140.0},
        -2:{"open":support+0.31,"high":support+0.54,"low":support+0.28,"close":support+0.44,"volume":190.0},
        -1:{"open":support+0.40,"high":support+0.50,"low":support+0.30,"close":support+0.42,"volume":120.0},
    }
    for off,row in vals.items():
        ix=base_idx[off]
        for k,v in row.items(): d5.loc[ix,k]=v
    btc5=d5.copy(); btc15=d15.copy()
    btc5["close"]*=1.001; btc15["close"]*=1.001
    d1h=d15.iloc[::4].copy(); btc1h=d1h.copy(); btc1h["close"]*=1.001
    return d5,d15,d1h,btc5,btc15,btc1h


