        checks["lar_policy"] = bool(CanonicalStrategyPolicyRegistry.get("LIQUIDITY_ACCEPTANCE_RECLAIM"))
        checks["lar_exit_profile"] = bool(StrategyExitProfiles.profile_for("LIQUIDITY_ACCEPTANCE_RECLAIM").validate())
        source=getattr(LiquidityAcceptanceReclaimEngine,"generate").__func__.__code__.co_names
        checks["lar_has_no_execution_api"] = not any(str(x) in {"place_market_buy","place_entry","place_order","cancel_order_safe","TelegramDispatcher"} for x in source)
        # Critical Telegram classifications stay immediate.
        checks["critical_stays_immediate"] = _V702R28TelegramDigest.classify("ORDER FILLED\nEXECUTION SUCCESS") == ""
        checks["summary_is_compacted"] = _V702R28TelegramDigest.classify("Unified Scalper V702 Canonical Periodic Summary\nV702 FUNNEL G=1") == "summary"
        # Parser regression on a real-shaped rejection batch.
        rej="""🧾 REJECTION BATCH\nRejected evaluations: 100 | Notification groups: 10 | Unique opportunities: 40\nSYSTEM=0 POLICY=20 HTF=5 LIQUIDITY=50 STRUCTURE=20 SCORE=5\nStages: prequal×70, scorer×2\nTop reasons\nliquidity.below_tier×12, htf.family_htf_strength_below_floor×4\nTop families\nPULLBACK×20, BREAKOUT_RETEST×3\nRepresentative rejected setups\n• TEST/USDT PULLBACK — liquidity.below_tier ×2"""
        rline=_V702R28TelegramDigest._rejection_line(rej)
