# R29 current validation is additive to the already-validated historical base.
def _v702_r29_validate_config() -> bool:
    try:
        prev = bool((STATS.get("v702_r28_final_self_test") or {}).get("pass", False))
        strategy = bool((_V701_3_STRATEGY_CONTRACT_SELF_TEST or {}).get("pass", False))
        cur = dict(STATS.get("v702_r29_final_self_test") or V702_R29_FINAL_SELF_TEST or {})
        result={"pass":bool(prev and strategy and cur.get("pass",False)),"previous_r28":prev,"current_strategy_contract":strategy,"r29":cur,"closure":V702_R29_CLOSURE_ID}
        STATS["v702_r29_final_validation"]=result
        if result["pass"]:
            logger.info("[V702-R29] FINAL CANONICAL VALIDATION PASS checks=%d",len(cur.get("checks",{})))
        else:
            logger.critical("[V702-R29] FINAL CANONICAL VALIDATION FAIL failed=%s",[k for k,v in (cur.get("checks",{}) or {}).items() if not v])
        return bool(result["pass"])
    except Exception as exc:
        STATS["v702_r29_final_validation"]={"pass":False,"error":f"{type(exc).__name__}:{exc}","closure":V702_R29_CLOSURE_ID}
        return False

