_V702_R30_MICRO_SCAN_HISTORY = {}


def _v702_r30_note_scan_result(symbol: str, success: bool, now: Optional[float] = None) -> None:
    """Maintain success TTL separately from transient failed-fetch retry delay."""
    try:
        sym = str(symbol or "").strip()
        hist = globals().get("_V702_R30_MICRO_SCAN_HISTORY", {})
        if not sym or not isinstance(hist, dict) or sym not in hist:
            return
        current = float(MONO_NOW() if now is None else now)
        if not math.isfinite(current) or current <= 0.0:
            return
        ttl = max(0.0, float(CONFIG.get("V702_R30_MICRO_RECALL_RECENT_SCAN_TTL_SEC", 300.0)))
        if success:
            hist[sym] = current
            STATS["v702_r30_micro_scan_success"] = int(STATS.get("v702_r30_micro_scan_success", 0) or 0) + 1
            return
        retry = max(1.0, min(ttl if ttl > 0 else 60.0,
                             float(CONFIG.get("V702_R30_MICRO_RECALL_FAILED_RETRY_SEC", 60.0))))
        # Selector suppresses when current-last_scan < TTL. This timestamp makes
        # only `retry` seconds remain, rather than the full successful-scan TTL.
        hist[sym] = max(0.0, current - ttl + retry)
        STATS["v702_r30_micro_scan_retry_armed"] = int(STATS.get("v702_r30_micro_scan_retry_armed", 0) or 0) + 1
    except Exception:
        # This is discovery scheduling telemetry only; do not affect scan gates.
        pass


def _v702_r30_truthful_completed_liquidity_root() -> dict:
    try:
        fn = globals().get("_v699_truthful_starvation_snapshot")
        truth = dict(fn() or {}) if callable(fn) else {}
        root = str(truth.get("root") or truth.get("mode") or "NONE").upper()
        age = truth.get("age_sec", truth.get("cycle_age_sec"))
        try:
            age_f = float(age) if age is not None else None
        except Exception:
            age_f = None
        max_age = float(CONFIG.get("V702_R30_MICRO_RECALL_MAX_LOOKBACK_SEC", 900.0))
        fresh = age_f is not None and math.isfinite(age_f) and age_f <= max_age
        generated = int(truth.get("generated", 0) or 0)
        prequal = int(truth.get("prequal", 0) or 0)
        ranked = int(truth.get("ranked", truth.get("mse_raw_ranked", 0)) or 0)
        selected = int(truth.get("selected", 0) or 0)
        strong = root == "LIQUIDITY" and fresh and generated > 0 and prequal == 0
        eligible = root == "LIQUIDITY" and fresh and generated > 0 and selected == 0
        return {"eligible":bool(eligible),"strong":bool(strong),"root":root,"age_sec":age_f,
                "generated":generated,"prequal":prequal,"ranked":ranked,"selected":selected,
                "cycle_id":int(truth.get("cycle_id",0) or 0),
                "source":str(truth.get("source") or truth.get("cycle_source") or "UNKNOWN")}
    except Exception as exc:
        return {"eligible":False,"strong":False,"root":"SYSTEM","age_sec":None,
                "generated":0,"prequal":0,"ranked":0,"selected":0,"cycle_id":0,
                "source":f"ERROR:{type(exc).__name__}"}


def _v702_r30_micro_recall_budget(truth: dict) -> tuple[int,str]:
    if not isinstance(truth,dict) or not bool(truth.get("eligible")):
        return 0,"OFF"
    # Avoid compounding a cycle that already consumed its scan-time budget.
    if bool(STATS.get("v650_scan_budget_hit",False)):
        return 0,"THROTTLED:PRIOR_BUDGET_HIT"
    elapsed=float(STATS.get("v650_scan_elapsed_sec",0.0) or 0.0)
    high_latency=float(CONFIG.get("V702_R30_MICRO_RECALL_HIGH_LATENCY_SEC",105.0))
    if math.isfinite(elapsed) and elapsed >= high_latency:
        return max(1,int(CONFIG.get("V702_R30_MICRO_RECALL_THROTTLED_SYMBOLS",16))),"THROTTLED:LATENCY"
    if bool(truth.get("strong")):
        return max(1,int(CONFIG.get("V702_R30_MICRO_RECALL_MAX_SYMBOLS",40))),"STRONG:LIQUIDITY_STARVATION"
    return max(1,int(CONFIG.get("V702_R30_MICRO_RECALL_ELEVATED_SYMBOLS",24))),"ELEVATED:LIQUIDITY_STARVATION"


def _v702_r30_select_micro_symbols(tickers: dict, markets: dict, existing_symbols, budget: int, now: float|None=None) -> tuple[list[str],dict]:
    now=float(MONO_NOW() if now is None else now)
    existing={str(x) for x in (existing_symbols or [])}
    mn=float(CONFIG.get("V702_R30_MICRO_RECALL_MIN_QUOTE_VOLUME",1_000_000.0))
    mx=float(CONFIG.get("V702_R30_MICRO_RECALL_MAX_QUOTE_VOLUME",3_000_000.0))
    ttl=max(0.0,float(CONFIG.get("V702_R30_MICRO_RECALL_RECENT_SCAN_TTL_SEC",300.0)))
    rows=[]; rej={"not_spot":0,"bad_quote":0,"forbidden":0,"existing":0,"recent":0,"invalid":0}
    forbid=globals().get("_v587_is_forbidden_coin")
    for symbol,ticker in (tickers or {}).items():
        sym=str(symbol or "").strip()
        try:
            if not sym or sym in existing:
                rej["existing"]+=1; continue
            market=(markets or {}).get(sym) or {}
            if str(market.get("quote") or "").upper()!="USDT" or not bool(market.get("spot",False)) or market.get("active") is False:
                rej["not_spot"]+=1; continue
            qv=float((ticker or {}).get("quoteVolume") or 0.0); last=float((ticker or {}).get("last") or 0.0)
            if not math.isfinite(qv) or not math.isfinite(last) or qv < mn or qv >= mx or last <= 0:
                rej["bad_quote"]+=1; continue
            try:
                fr=forbid(sym) if callable(forbid) else (False,"no_checker")
                is_forbidden=bool(fr[0]) if isinstance(fr,(tuple,list)) and fr else bool(fr)
            except Exception:
                is_forbidden=True
            if is_forbidden:
                rej["forbidden"]+=1; continue
            last_scan=float(_V702_R30_MICRO_SCAN_HISTORY.get(sym,0.0) or 0.0)
            if ttl>0 and last_scan>0 and now-last_scan<ttl:
                rej["recent"]+=1; continue
            pct=float((ticker or {}).get("percentage") or 0.0)
            if not math.isfinite(pct): pct=0.0
            rows.append((qv,abs(pct),sym))
        except Exception:
            rej["invalid"]+=1
    rows.sort(key=lambda x:(x[0],x[1]),reverse=True)
    budget=max(0,int(budget))
    warm=max(budget,budget*max(1,int(CONFIG.get("V702_R30_MICRO_RECALL_WARM_POOL_MULTIPLIER",3))))
    pool=rows[:warm]
    # Deterministically spread the bounded sample over the warm pool. The previous
    # rows[:warm][:budget] expression always collapsed to rows[:budget], so the
    # configured warm-pool multiplier never changed coverage.
    if budget <= 0 or not pool:
        chosen=[]
    elif len(pool) <= budget:
        chosen=list(pool)
    elif budget == 1:
        chosen=[pool[0]]
    else:
        indices=[]
        last=len(pool)-1
        for i in range(budget):
            idx=int(round(i*last/(budget-1)))
            if not indices or idx>indices[-1]:
                indices.append(idx)
        chosen=[pool[i] for i in indices[:budget]]
        # Defensive fill if rounding ever collapses an index on unusual runtimes.
        for row in pool:
            if len(chosen)>=budget: break
            if row not in chosen: chosen.append(row)
    selected=[x[2] for x in chosen[:budget]]
    for sym in selected: _V702_R30_MICRO_SCAN_HISTORY[sym]=now
    return selected,{"eligible_rows":len(rows),"warm_pool":min(len(rows),warm),"budget":budget,
                     "selected":len(selected),"rejected":rej,"quote_min":mn,"quote_max_exclusive":mx,
                     "selection_mode":"STRATIFIED_WARM_POOL","warm_pool_multiplier":max(1,int(CONFIG.get("V702_R30_MICRO_RECALL_WARM_POOL_MULTIPLIER",3)))}


def _v702_r30_micro_engine_permitted(engine_cls) -> bool:
    allowed={str(x).upper() for x in (CONFIG.get("V702_R30_MICRO_RECALL_ALLOWED_FAMILIES") or ())}
    fams={str(x).upper() for x in (getattr(engine_cls,"family_map",()) or ())}
    mode=str(getattr(engine_cls,"strategy_mode","") or "").upper()
    return bool(fams.intersection(allowed) or mode in allowed)


