def _v702_r31_grade_ticket_target(grade: str) -> float:
    g = str(grade or "").strip().upper().replace("_PLUS", "+")
    if g in {"A+", "A PLUS"}:
        return float(CONFIG.get("V702_GRADE_TICKET_A_PLUS_USDT", 75.0))
    if g == "A":
        return float(CONFIG.get("V702_GRADE_TICKET_A_USDT", 75.0))
    if g == "B":
        return float(CONFIG.get("V702_GRADE_TICKET_B_USDT", 45.0))
    if g == "C":
        return float(CONFIG.get("V702_GRADE_TICKET_C_USDT", 30.0))
    return 0.0


def _v702_r31_normalize_builder_block(raw: str) -> str:
    """Normalize only misleading selected->builder generic-noop telemetry.

    This function never invokes a builder, changes a candidate, changes a gate,
    or authorizes an order. It only makes the operator diagnostic agree with the
    current-cycle builder blocker record when such a record is fresh and exact.
    """
    text = str(raw or "")
    if not bool(CONFIG.get("V702_R31_BUILDER_TRUTH_NORMALIZATION_ENABLE", True)):
        return text
    if not re.search(r"SELECTED → BUILDER BLOCK", text, flags=re.I) or "reason=builder_returned_none" not in text:
        return text
    try:
        _plain_text = re.sub(r"<[^>]+>", "", text)
        symbol_m = re.search(r"SELECTED → BUILDER BLOCK\s+([A-Z0-9_.\-]+/USDT)", _plain_text, flags=re.I)
        symbol = str(symbol_m.group(1)) if symbol_m else ""
        fresh = dict(STATS.get("v701_current_builder_block") or {})
        now = float(WALL_NOW())
        ts = float(fresh.get("ts", 0.0) or 0.0)
        age = now - ts if ts else float("inf")
        fresh_symbol = str(fresh.get("symbol", ""))
        fresh_reason = str(fresh.get("reason", "") or "")
        fresh_stage = str(fresh.get("stage", "") or "")
        max_age = max(1.0, float(CONFIG.get("V702_R25_BUILDER_TRUTH_MAX_AGE_SEC", 20.0)))
        usable = bool(symbol and fresh_symbol == symbol and age <= max_age and fresh_reason and fresh_reason != "builder_returned_none")
        if not usable:
            fresh_reason = "builder_terminal_no_result_unattributed"
            fresh_stage = "builder_terminal"
            STATS["v702_r31_builder_generic_noop_normalized"] = int(STATS.get("v702_r31_builder_generic_noop_normalized", 0) or 0) + 1
        else:
            STATS["v702_r31_builder_fresh_reason_recovered"] = int(STATS.get("v702_r31_builder_fresh_reason_recovered", 0) or 0) + 1
        text = re.sub(r"reason=builder_returned_none", f"reason={fresh_reason}", text, count=1)
        if fresh_stage:
            text = re.sub(r"stage=[^\s]+", f"stage={fresh_stage}", text, count=1)
        # A generic EXECUTION root is not the real blocker when a fresh blocker
        # record exists. Replace it only in this diagnostic message.
        root = str(fresh.get("root", "") or "")
        if usable and root:
            text = re.sub(r"root=[^\s]+", f"root={root}", text, count=1)
        return text
    except Exception as exc:
        STATS["v702_r31_builder_truth_normalization_errors"] = int(STATS.get("v702_r31_builder_truth_normalization_errors", 0) or 0) + 1
        return text.replace("reason=builder_returned_none", "reason=builder_terminal_no_result_unattributed", 1)


# Wire the telemetry-only builder-block normalization exactly once, after R28
# installs its classmethod capture wrapper.  Critical Telegram messages remain
# on the original immediate dispatcher path.
try:
    if not bool(getattr(_V702R28TelegramDigest, "_v702_r31_capture_installed", False)):
        _V702_R31_PREV_DIGEST_CAPTURE = _V702R28TelegramDigest.capture
        def _v702_r31_digest_capture(cls, category: str, raw: str, on_success=None, on_failure=None) -> None:
            # Preserve the R29 callback contract.  Discovery rows can carry
            # delivery callbacks used by downstream knowledge registration;
            # the R31 telemetry wrapper must not swallow those arguments.
            text = _v702_r31_normalize_builder_block(raw) if str(category) == "builder_block" else raw
            _V702_R31_PREV_DIGEST_CAPTURE(
                category, text, on_success=on_success, on_failure=on_failure
            )
        _v702_r31_digest_capture._v702_r31_wrapper = True
        _V702R28TelegramDigest.capture = classmethod(_v702_r31_digest_capture)
        _V702R28TelegramDigest._v702_r31_capture_installed = True
        STATS["v702_r31_digest_capture_wired"] = True
except Exception as exc:
    STATS["v702_r31_digest_capture_wired"] = False
    STATS["v702_r31_digest_capture_error"] = f"{type(exc).__name__}:{exc}"


