        checks["live_score_floor_preserved"] = float(CONFIG.get("MIN_LIVE_SCORE", 70.0)) >= 70.0
        checks["liquidity_floor_preserved"] = abs(float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 3_000_000.0)) - 3_000_000.0) < 1e-9
        checks["concurrent_trade_cap_preserved"] = int(CONFIG.get("MAX_CONCURRENT_TRADES", 2)) <= 2
