_V702_R34_BASE_VALIDATE = globals().get("validate_config")
def _v702_r34_validate_config() -> bool:
    try:
        base_ok = bool(_V702_R34_BASE_VALIDATE()) if callable(_V702_R34_BASE_VALIDATE) else False
        checks = {}
        engines = globals().get("_V702_ALL_MSE_ENGINES", {}) or {}
        checks["engine_registry_exact_18"] = (len(engines) == 18 and tuple(getattr(e, "__name__", "") for e in engines) == tuple(_V702_LIVE_ENGINE_CLASSES))
        checks["active_live_engine_registry_18"] = len(globals().get("_MSE_ENGINES", {}) or {}) == 18
        checks["spot_long_only"] = (bool(CONFIG.get("LONG_ONLY", True)) and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT" and not bool(CONFIG.get("FUTURES_ENABLED", False)) and not bool(CONFIG.get("ALLOW_SHORT", False)) and not bool(CONFIG.get("ALLOW_SHORTS", False)))
        checks["hard_liquidity_floor"] = abs(float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 3_000_000.0)) - 3_000_000.0) < 1e-9
        checks["source_widening_effective_floor"] = float(CONFIG.get("V702_R34_UNIVERSE_SOURCE_HARD_FLOOR", 0.0)) >= float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 3_000_000.0))
        checks["micro_recall_preserved"] = (float(CONFIG.get("V702_R30_MICRO_RECALL_MIN_QUOTE_VOLUME", 1_000_000.0)) == 1_000_000.0 and float(CONFIG.get("V702_R30_MICRO_RECALL_MAX_QUOTE_VOLUME", 3_000_000.0)) == 3_000_000.0 and bool(CONFIG.get("V702_R30_MICRO_RECALL_ENABLE", True)))
        checks["score_projection_callable"] = callable(globals().get("_v702_projected_canonical_score"))
        checks["score_projection_parity_enabled"] = bool(CONFIG.get("V702_R34_SCORE_PROJECTION_PARITY_ENABLE", False))
        checks["exact_score_prefilter_enabled"] = bool(CONFIG.get("V702_R34_EXACT_SCORE_PREFILTER_ENABLE", False))
        checks["micro_orderbook_prequal_parity_enabled"] = bool(CONFIG.get("V702_R34_MICRO_ORDERBOOK_PREQUAL_PARITY_ENABLE", False))
        checks["validate_only_cli_alias"] = "--validate-only" in globals().get("_V699_VALIDATE_ONLY_REQUEST_SOURCE", "--validate-only") or "--validate-only" in sys.argv or bool(CONFIG.get("V702_R34_VALIDATE_ONLY_CLI", False))
        checks["single_execution_authority"] = callable(getattr(globals().get("SignalBuilder"), "build_and_route", None)) and FINAL_CANONICAL_RUNTIME.get("single_execution_authority", True)
        checks["hard_gate_bypass_disabled"] = not bool(CONFIG.get("V702_R34_HARD_GATE_BYPASS", True))
        failed = [k for k, v in checks.items() if not v]
        if not base_ok:
            failed.append("previous_canonical_validation")
        result = {
            "pass": bool(base_ok and all(checks.values())),
            "previous_canonical_validation": base_ok,
            "checks": checks,
            "failed": failed,
            "historical": True,
            "superseded_by": "V702-R36 (and later canonical revisions)",
            "closure": V702_R34_CLOSURE_ID,
            "revision": V702_R34_FINAL_CANONICAL_REVISION,
        }
        STATS["v702_r34_final_validation"] = result
        FINAL_CANONICAL_RUNTIME["r34_validation"] = result
        if result["pass"]:
            logger.info("[V702-R34] historical validation pass checks=%d", len(checks))
        else:
            logger.debug("[V702-R34][HISTORICAL/SUPERSEDED] validation did not pass; failed=%s; active terminal V702-R38 is validated separately", failed)
        return bool(result["pass"])
    except Exception as exc:
        STATS["v702_r34_final_validation"] = {"pass": False, "error": f"{type(exc).__name__}:{exc}", "closure": V702_R34_CLOSURE_ID}
        return False


