# ---- Canonical exact route-orderbook validator --------------------------------
def _v703_r35_orderbook_metrics(ob: Any) -> Optional[Dict[str, float]]:
    try:
        if not isinstance(ob, dict):
            return None
        bids = list(ob.get("bids", []) or [])[:10]
        asks = list(ob.get("asks", []) or [])[:10]
        if not bids or not asks:
            return None
        bb = float(bids[0][0]); ba = float(asks[0][0])
        if not (math.isfinite(bb) and math.isfinite(ba) and bb > 0 and ba > 0 and ba >= bb):
            return None
        mid = max((bb + ba) * 0.5, 1e-12)
        spread = (ba - bb) / mid * 100.0
        bd = sum(max(0.0, float(q)) for _, q in bids)
        ad = sum(max(0.0, float(q)) for _, q in asks)
        tot = bd + ad
        if not (math.isfinite(spread) and math.isfinite(tot) and tot > 0):
            return None
        return {"best_bid":bb,"best_ask":ba,"spread_pct":spread,"bid_depth":bd,
                "ask_depth":ad,"depth_total":tot,"imbalance":bd/tot}
    except Exception:
        return None

# ---- Snapshot coherence: recompute BTC-derived macro context from this exact snapshot --
def _v702_r36_macro_context(df4: Any) -> tuple[str, Optional[float], str]:
    """Return a closed-candle BTC 4H macro regime or UNKNOWN on incomplete data."""
    try:
        if df4 is None or not hasattr(df4, "columns"):
            return "UNKNOWN", None, "macro_frame_missing"
        if "close" not in df4.columns:
            return "UNKNOWN", None, "macro_close_column_missing"
        # The active snapshot route must enforce the same 240-row minimum as
        # the shared BTC 4H availability contract. The final value is read from
        # iloc[-2] so the potentially open candle is never used as evidence.
        # Missing/short history fails closed; it must never become NEUTRAL.
        operational_min = max(240, int(CONFIG.get("BTC_SHARED_CONTEXT_MIN_CANDLES_4H", 240) or 240))
        # Evidence is read from iloc[-2] to avoid the possibly open last candle,
        # therefore total frame length must be min_closed + 1.
        if len(df4) < operational_min + 1:
            return "UNKNOWN", None, "macro_history_insufficient"
        close = float(df4["close"].iloc[-2])
        ema_series = Indicators.ema(df4["close"], 200)
        ema200 = float(ema_series.iloc[-2])
        if not (math.isfinite(close) and close > 0 and math.isfinite(ema200) and ema200 > 0):
            return "UNKNOWN", None, "macro_closed_value_invalid"
        bull = float(CONFIG.get("REGIME_BULL_THRESHOLD_PCT", 0.5))
        bear = float(CONFIG.get("REGIME_BEAR_THRESHOLD_PCT", -0.5))
        if not (math.isfinite(bull) and math.isfinite(bear) and bear < bull):
            return "UNKNOWN", None, "macro_thresholds_invalid"
        pct = (close - ema200) / ema200 * 100.0
        if not math.isfinite(pct):
            return "UNKNOWN", None, "macro_distance_invalid"
        regime = "BULLISH" if pct > bull else ("BEARISH" if pct < bear else "NEUTRAL")
        return regime, float(pct), ""
    except Exception as exc:
        return "UNKNOWN", None, f"macro_context_error:{type(exc).__name__}"


def _v702_r36_bearish_severity(df15: Any, df4: Any) -> tuple[str, str]:
    """Classify bearish BTC context; incomplete/invalid evidence always means CRASH."""
    crash = str(getattr(V425BearishSeverity, "CRASH", "BEARISH_CRASH"))
    try:
        win = int(CONFIG.get("V425_BEARISH_CRASH_WINDOW_15M", 8))
        n4 = int(CONFIG.get("V425_BEARISH_CRASH_WINDOW_4H", 3))
        need = int(CONFIG.get("V425_BEARISH_CRASH_BREAKDOWN_N", 3))
        atr_period = int(CONFIG.get("ATR_PERIOD", 14))
        crash_drop = float(CONFIG.get("V425_BEARISH_CRASH_DROP_PCT", -6.0))
        stress_drop = float(CONFIG.get("V425_BEARISH_STRESSED_DROP_PCT", -3.0))
        atr_mult = float(CONFIG.get("V425_BEARISH_CRASH_ATR_MULT", 2.5))
        if (win < 1 or n4 < 2 or need < 2 or need > n4 or atr_period < 1
                or not all(math.isfinite(x) for x in (crash_drop, stress_drop, atr_mult))
                or crash_drop > stress_drop or stress_drop >= 0 or atr_mult <= 0):
            return crash, "bearish_severity_config_invalid"
        if df15 is None or not hasattr(df15, "columns") or not {"close", "high", "low"}.issubset(set(df15.columns)):
            return crash, "bearish_15m_context_missing"
        if len(df15) < max(win + 2, 22):
            return crash, "bearish_15m_history_insufficient"
        if df4 is None or not hasattr(df4, "columns") or "low" not in df4.columns:
            return crash, "bearish_4h_low_context_missing"
        # Keep standalone severity calls aligned with the shared 4H contract;
        # the snapshot wrapper normally screens this frame first, but helpers
        # must remain safe when called directly by validation or another route.
        operational_min = max(240, int(CONFIG.get("BTC_SHARED_CONTEXT_MIN_CANDLES_4H", 240) or 240))
        if len(df4) < max(n4 + 1, operational_min + 1):
            return crash, "bearish_4h_history_insufficient"
        first = float(df15["close"].iloc[-(win + 1)])
        last = float(df15["close"].iloc[-2])
        if not (math.isfinite(first) and first > 0 and math.isfinite(last) and last > 0):
            return crash, "bearish_15m_close_invalid"
        drop_pct = (last - first) / first * 100.0
        if not math.isfinite(drop_pct):
            return crash, "bearish_15m_drop_invalid"
        atr_s = Indicators.atr(df15, atr_period)
        if atr_s is None or len(atr_s) < 22:
            return crash, "bearish_atr_history_insufficient"
        a_now = float(atr_s.iloc[-2])
        atr_reference = list(atr_s.iloc[-22:-2])
        if len(atr_reference) != 20 or any(not math.isfinite(float(x)) or float(x) <= 0 for x in atr_reference):
            return crash, "bearish_atr_reference_invalid"
        a_ref = float(sum(float(x) for x in atr_reference) / len(atr_reference))
        if not (math.isfinite(a_now) and a_now > 0 and math.isfinite(a_ref) and a_ref > 0):
            return crash, "bearish_atr_value_invalid"
        atr_expanding = (a_now / a_ref) >= atr_mult
        lows = [float(df4["low"].iloc[-k]) for k in range(2, 2 + n4)]
        if any(not math.isfinite(x) or x <= 0 for x in lows):
            return crash, "bearish_4h_lows_invalid"
        lower = sum(1 for i in range(len(lows) - 1) if lows[i] < lows[i + 1])
        breakdown = lower >= (need - 1)
        if drop_pct <= crash_drop or (atr_expanding and drop_pct <= stress_drop) or breakdown:
            return crash, "bearish_crash_confirmed"
        if drop_pct <= stress_drop or atr_expanding:
            return str(V425BearishSeverity.STRESSED), "bearish_stressed"
        return str(V425BearishSeverity.NORMAL), "bearish_normal"
    except Exception as exc:
        return crash, f"bearish_severity_error:{type(exc).__name__}"


def _v702_r36_classify_bearish_severity(cls, macro_regime: str, df_btc_15m: Any, df_btc_4h: Any = None) -> str:
    """Canonical class-level severity path shares the same fail-closed evidence contract."""
    if str(macro_regime or "").upper() != "BEARISH":
        return "NON_BEARISH"
    if not bool(CONFIG.get("V425_BEARISH_SEVERITY_ENABLE", True)):
        severity, reason = str(cls.CRASH), "bearish_severity_disabled"
    else:
        severity, reason = _v702_r36_bearish_severity(df_btc_15m, df_btc_4h)
    try:
        STATS["v702_r36_bearish_classify_calls"] = int(STATS.get("v702_r36_bearish_classify_calls", 0) or 0) + 1
        STATS["v702_r36_bearish_classify_last"] = {"severity": str(severity), "reason": str(reason)}
    except Exception:
        pass
    return str(severity)


def _v702_r36_allows_new_long(severity: Any) -> bool:
    """Unknown/missing severity is not authorization to open a new long."""
    value = str(severity or "").strip().upper()
    return value in {"NON_BEARISH", "NORMAL", "STRESSED", "BEARISH_NORMAL", "BEARISH_STRESSED"}


# Replace contradictory legacy implementations: the original docstring promised
# missing-data CRASH but its fallback values classified missing frames as NORMAL;
# the old allows_new_long accepted every unknown string except explicit CRASH.
_v702_r36_classify_bearish_severity._v702_r36_fail_closed_authority = True
_v702_r36_allows_new_long._v702_r36_fail_closed_authority = True
V425BearishSeverity.classify = classmethod(_v702_r36_classify_bearish_severity)
V425BearishSeverity.allows_new_long = staticmethod(_v702_r36_allows_new_long)


def _v702_r36_fail_closed_snapshot(symbol: str, md: Any, snap: Any, reason: str) -> Dict[str, Any]:
    """Stamp an explicit blocked snapshot instead of leaking stale/neutral context."""
    try:
        result = dict(snap or {}) if isinstance(snap, dict) else {}
    except Exception:
        result = {}
    try:
        closed_ts = str(result.get("closed_candle_ts") or result.get("candle_ts") or "")
    except Exception:
        closed_ts = ""
    sid = hashlib.sha256(f"{symbol}|{closed_ts}|UNKNOWN|FAIL_CLOSED|{reason}".encode("utf-8", "replace")).hexdigest()[:20]
    crash = str(getattr(V425BearishSeverity, "CRASH", "BEARISH_CRASH"))
    result.update({
        "regime": "UNKNOWN",
        "macro_regime": "UNKNOWN",
        "local_regime": "LOCAL_BEARISH",
        "market_phase": {"phase": "UNKNOWN"},
        "bearish_severity": crash,
        "macro_severity": crash,
        "severity": crash,
        "snapshot_id": sid,
        "v703_r36_snapshot_coherent": False,
        "v702_r36_context_blocked": True,
        "v702_r36_context_block_reason": str(reason),
    })
    try:
        _context_ts = float(WALL_NOW())
        _btc4 = md.get("df_btc_4h") if isinstance(md, dict) else None
        try:
            _btc4_rows = int(len(_btc4)) if _btc4 is not None else 0
        except Exception:
            _btc4_rows = 0
        result["v702_r36_context_block_ts"] = _context_ts
        STATS["v702_r36_snapshot_context_blocked"] = int(STATS.get("v702_r36_snapshot_context_blocked", 0) or 0) + 1
        STATS["v702_r36_last_snapshot_context_block"] = {
            "symbol": str(symbol), "reason": str(reason), "snapshot_id": sid,
            "ts": _context_ts, "btc_4h_rows": _btc4_rows,
        }
        bucket = f"v702_r36_context_block_reason:{str(reason).split(':', 1)[0]}"
        STATS[bucket] = int(STATS.get(bucket, 0) or 0) + 1
    except Exception:
        pass
    return result


def _v702_r36_snapshot_context_self_test() -> Dict[str, Any]:
    """Offline regression checks for the context helpers and the active snapshot wrapper."""
    global _V703_R36_ORIG_SNAPSHOT, STATS
    checks: Dict[str, bool] = {}
    try:
        if not bool(globals().get("_PDNP_OK", False)) or "pd" not in globals():
            return {"pass": False, "error": "pandas/numpy unavailable", "checks": {"test_dependencies_available": False}}
        closes_up = [100.0 + 1.5 * i for i in range(260)]
        up = pd.DataFrame({"close": closes_up, "high": [x + 1.0 for x in closes_up], "low": [x - 1.0 for x in closes_up]})
        closes_down = [500.0 - 1.0 * i for i in range(260)]
        down = pd.DataFrame({"close": closes_down, "high": [x + 1.0 for x in closes_down], "low": [x - 2.0 for x in closes_down]})
        nan_df = up.copy()
        nan_df.loc[nan_df.index[-2], "close"] = float("nan")
        r_missing = _v702_r36_macro_context(None)
        r_short = _v702_r36_macro_context(up.iloc[:209].copy())
        r_below_operational_floor = _v702_r36_macro_context(up.iloc[:240].copy())
        r_at_operational_floor = _v702_r36_macro_context(up.iloc[:241].copy())
        r_nan = _v702_r36_macro_context(nan_df)
        r_up = _v702_r36_macro_context(up)
        r_down = _v702_r36_macro_context(down)
        checks["missing_macro_frame_unknown"] = r_missing[0] == "UNKNOWN" and bool(r_missing[2])
        checks["short_macro_history_unknown"] = r_short[0] == "UNKNOWN" and bool(r_short[2])
        checks["operational_floor_rejects_240_total_rows_without_240_closed"] = r_below_operational_floor[0] == "UNKNOWN" and r_below_operational_floor[2] == "macro_history_insufficient"
        checks["operational_floor_accepts_241_rows_for_240_closed"] = r_at_operational_floor[0] in {"BULLISH", "BEARISH", "NEUTRAL"} and r_at_operational_floor[1] is not None and not r_at_operational_floor[2]
        checks["invalid_closed_macro_candle_unknown"] = r_nan[0] == "UNKNOWN" and bool(r_nan[2])
        checks["valid_bull_macro_classified"] = r_up[0] == "BULLISH" and r_up[1] is not None
        checks["valid_bear_macro_classified"] = r_down[0] == "BEARISH" and r_down[1] is not None
        missing_bearish = _v702_r36_bearish_severity(None, down)
        checks["missing_bearish_15m_context_crash"] = missing_bearish[0] == str(V425BearishSeverity.CRASH) and bool(missing_bearish[1])
        checks["canonical_classify_missing_context_crashes"] = V425BearishSeverity.classify("BEARISH", None, None) == str(V425BearishSeverity.CRASH)
        checks["unknown_severity_cannot_authorize_long"] = (not V425BearishSeverity.allows_new_long("UNKNOWN")) and (not V425BearishSeverity.allows_new_long("")) and V425BearishSeverity.allows_new_long("NORMAL")
        bad_atr = _v702_r36_bearish_severity(pd.DataFrame({"close": closes_down}), down)
        checks["malformed_bearish_15m_context_crash"] = bad_atr[0] == str(V425BearishSeverity.CRASH)
        # Exercise the active wrapper itself without touching exchange/network state.
        original_snapshot = _V703_R36_ORIG_SNAPSHOT
        original_stats = STATS
        # Synthetic calls must not leak into live epoch/operator telemetry.
        STATS = dict(original_stats)
        try:
            _V703_R36_ORIG_SNAPSHOT = lambda _symbol, _md: {"regime": "NEUTRAL", "macro_regime": "NEUTRAL", "bearish_severity": "NON_BEARISH", "htf_strength": 0.8, "closed_candle_ts": "offline-self-test"}
            wrapped_missing = _v703_r36_snapshot("TEST/USDT", {"df_btc_4h": None})
            wrapped_bearish_missing_15m = _v703_r36_snapshot("TEST/USDT", {"df_btc_4h": down})
            checks["active_wrapper_missing_macro_fails_closed"] = (wrapped_missing.get("regime") == "UNKNOWN" and bool(wrapped_missing.get("v702_r36_context_blocked")) and wrapped_missing.get("bearish_severity") == str(V425BearishSeverity.CRASH))
            checks["active_wrapper_bearish_missing_15m_crashes"] = (wrapped_bearish_missing_15m.get("regime") == "BEARISH" and wrapped_bearish_missing_15m.get("bearish_severity") == str(V425BearishSeverity.CRASH))
        finally:
            _V703_R36_ORIG_SNAPSHOT = original_snapshot
            STATS = original_stats
        result = {"pass": bool(all(checks.values())), "checks": checks,
                  "details": {"missing_macro_reason": r_missing[2], "short_history_reason": r_short[2],
                              "below_operational_floor_reason": r_below_operational_floor[2],
                              "at_operational_floor_regime": r_at_operational_floor[0],
                              "invalid_closed_candle_reason": r_nan[2], "missing_15m_reason": missing_bearish[1],
                              "malformed_15m_reason": bad_atr[1]}}
        return result
    except Exception as exc:
        return {"pass": False, "checks": checks, "error": f"{type(exc).__name__}:{exc}"}


_V703_R36_ORIG_SNAPSHOT = GlobalOpportunityBrain._snapshot

def _v703_r36_snapshot(symbol: str, md: Dict[str, Any]) -> Dict[str, Any]:
    snap: Dict[str, Any] = {}
    try:
        snap = dict(_V703_R36_ORIG_SNAPSHOT(symbol, md) or {})
    except Exception as exc:
        return _v702_r36_fail_closed_snapshot(symbol, md, snap, f"base_snapshot_error:{type(exc).__name__}")
    if not bool(CONFIG.get("V702_R36_SNAPSHOT_REGIME_COHERENCE_ENABLE", True)):
        return _v702_r36_fail_closed_snapshot(symbol, md, snap, "snapshot_coherence_disabled")
    try:
        if not isinstance(md, dict):
            return _v702_r36_fail_closed_snapshot(symbol, md, snap, "market_data_not_mapping")
        df15 = md.get("df_btc_15m")
        df4 = md.get("df_btc_4h")
        regime, pct, macro_reason = _v702_r36_macro_context(df4)
        if regime == "UNKNOWN" or pct is None:
            return _v702_r36_fail_closed_snapshot(symbol, md, snap, macro_reason or "macro_context_unknown")
        snap["v703_macro_pct_from_ema200"] = float(pct)
        try:
            local = V425LocalRegime.classify(regime, md.get("df_15m"), md.get("df_5m"))
            if not local:
                local = "LOCAL_BEARISH"
        except Exception:
            local = "LOCAL_BEARISH"
        # Severity is computed only from this candidate's exact closed-candle snapshot.
        if regime == "BEARISH":
            severity, severity_reason = _v702_r36_bearish_severity(df15, df4)
            if severity == str(V425BearishSeverity.CRASH):
                snap["v702_r36_bearish_severity_reason"] = severity_reason
        else:
            severity = "NON_BEARISH"
        phase = "UNKNOWN"
        try:
            phase_obj = MarketPhaseDetector.detect(dict(md, symbol=symbol, macro_regime=regime, local_regime=local))
            phase = str(getattr(phase_obj, "value", phase_obj) or "UNKNOWN").upper()
        except Exception:
            phase = "UNKNOWN"
        closed_ts = str(snap.get("closed_candle_ts") or snap.get("candle_ts") or "")
        try:
            tier = str(snap.get("tier") or LiquidityTier.classify(float(md.get("quote_vol_24h", 0.0) or 0.0)))
        except Exception:
            tier = "UNKNOWN"
        sid = hashlib.sha256(
            f"{symbol}|{closed_ts}|{regime}|{local}|{phase}|{float(snap.get('htf_strength',0.0) or 0.0):.6f}|{tier}|{str(snap.get('coherence_snapshot_id',''))}".encode("utf-8", "replace")
        ).hexdigest()[:20]
        snap.update({
            "regime": regime,
            "macro_regime": regime,
            "local_regime": str(local),
            "market_phase": {"phase": phase},
            "bearish_severity": str(severity),
            "macro_severity": str(severity),
            "severity": str(severity),
            "tier": tier,
            "snapshot_id": sid,
            "v703_r36_snapshot_coherent": True,
            "v702_r36_context_blocked": False,
            "v702_r36_context_block_reason": "",
        })
        STATS["v702_r36_snapshot_recomputed"] = int(STATS.get("v702_r36_snapshot_recomputed", 0) or 0) + 1
        STATS["v702_r36_last_snapshot_context"] = {"symbol": str(symbol), "regime": regime, "local": str(local), "severity": str(severity), "phase": phase, "snapshot_id": sid}
        return snap
    except Exception as exc:
        STATS["v702_r36_snapshot_errors"] = int(STATS.get("v702_r36_snapshot_errors", 0) or 0) + 1
        logger.debug(f"[V702-R36] snapshot coherence failed closed: {type(exc).__name__}:{exc}")
        return _v702_r36_fail_closed_snapshot(symbol, md, snap, f"snapshot_context_error:{type(exc).__name__}")

GlobalOpportunityBrain._snapshot = staticmethod(_v703_r36_snapshot)

# ---- Bounded always-on MICRO recall -----------------------------------------
_V703_R35_ORIG_MICRO_BUDGET = _v702_r30_micro_recall_budget

def _v703_r35_micro_recall_budget(truth: dict) -> tuple[int,str]:
    try:
        # Preserve R30 starvation-driven larger recall budgets exactly.
        if isinstance(truth, dict) and bool(truth.get("eligible")):
            return _V703_R35_ORIG_MICRO_BUDGET(truth)
        if not bool(CONFIG.get("V703_R35_MICRO_ALWAYS_RECALL_ENABLE", True)):
            return 0, "OFF"
        if bool(STATS.get("v650_scan_budget_hit", False)):
            return 0, "THROTTLED:PRIOR_BUDGET_HIT"
        elapsed = float(STATS.get("v650_scan_elapsed_sec",0.0) or 0.0)
        ceiling = float(CONFIG.get("V703_R35_MICRO_RECALL_LATENCY_CEILING_SEC",90.0))
        if math.isfinite(elapsed) and elapsed >= ceiling:
            return 0, "THROTTLED:LATENCY"
        budget = max(1, min(8, int(CONFIG.get("V703_R35_MICRO_ALWAYS_RECALL_SYMBOLS",8) or 8)))
        return budget, "BOUNDED:MICRO_ROTATION"
    except Exception:
        return 0, "OFF:ERROR"

_v702_r30_micro_recall_budget = _v703_r35_micro_recall_budget

# ---- Structural invalidation: CLOSED 5m bar confirmation, no tick-based emergency exit --
_V703_R35_STRUCTURAL_BAR_CACHE: Dict[str, Dict[str, Any]] = {}

async def _v703_r35_structural_failure_guard(exchange: Any, trade: TradeState, current_price: float) -> bool:
    try:
        if not bool(CONFIG.get("V702_STRUCTURAL_FAILURE_EXIT_ENABLE", True)):
            return False
        if not bool(getattr(trade, "structural_invalidation_armed", False)):
            return False
        if bool(getattr(trade, "tp1_exit_completed", False)) or str(getattr(trade, "status", "")) != "entry_filled":
            return False
        fam = str(getattr(trade, "signal_family", "") or getattr(trade, "strategy_mode", "")).upper()
        allowed = {str(x).upper() for x in CONFIG.get("V702_STRUCTURAL_FAILURE_FAMILIES", ())}
        if fam not in allowed:
            return False
        age = _v570_entry_age_sec(trade)
        min_age = max(0.0, float(CONFIG.get("V702_R36_STRUCTURAL_MIN_AGE_SEC",15.0)))
        if not math.isfinite(age) or age < min_age:
            return False
        trigger = float(getattr(trade, "structural_invalidation_trigger",0.0) or 0.0)
        cur_sl = float(getattr(trade, "current_sl",0.0) or getattr(trade, "original_sl",0.0) or 0.0)
        if not (math.isfinite(trigger) and trigger > 0 and math.isfinite(cur_sl) and cur_sl > 0 and trigger > cur_sl):
            return False
        # Structural failure is confirmed only by a NEW CLOSED 5m candle.
        raw = await safe_api_call(
            f"fetch_structural_confirm_5m_{trade.symbol}",
            exchange.fetch_ohlcv(trade.symbol, "5m", limit=5),
            retry_safe=False,
        )
        if not raw:
            return False
        df = pd.DataFrame(raw, columns=["ts","open","high","low","close","volume"])
        if len(df) < 4:
            return False
        df["ts"] = pd.to_datetime(df["ts"], unit="ms", utc=True)
        closed = df.iloc[:-1].copy()
        if len(closed) < 2:
            return False
        bar = closed.iloc[-1]
        prev_ts = str(_v703_context_scalar(closed.iloc[-2]["ts"]) if "_v703_context_scalar" in globals() else closed.iloc[-2]["ts"])
        bar_ts = str(_v703_context_scalar(bar["ts"]) if "_v703_context_scalar" in globals() else bar["ts"])
        cache = _V703_R35_STRUCTURAL_BAR_CACHE.get(str(trade.symbol), {})
        if str(cache.get("bar_ts", "")) == bar_ts:
            return False
        _V703_R35_STRUCTURAL_BAR_CACHE[str(trade.symbol)] = {"bar_ts":bar_ts,"checked_at":WALL_NOW()}
        close = float(bar["close"])
        if not (math.isfinite(close) and close > 0 and close <= trigger):
            if close > trigger:
                trade.structural_invalidation_fail_count = 0
            return False
        # Cache the exact closed-bar timestamp so the same closed candle can
        # never confirm the exit twice. A later candle is a genuinely new edge.
        trade.structural_invalidation_last_confirmed_bar_ts = bar_ts
        trade.structural_invalidation_fail_count = int(getattr(trade,"structural_invalidation_fail_count",0) or 0) + 1
        need = max(1, int(CONFIG.get("V702_R36_STRUCTURAL_CONFIRM_BARS",1) or 1))
        if trade.structural_invalidation_fail_count < need:
            return False
        trade.last_exit_authority = "STRUCTURAL_INVALIDATION_PENDING"
        ok = await OrderExecutor.emergency_close(exchange, trade, "structural_invalidation", exit_px=close)
        if ok:
            STATS["v703_r35_structural_closed_bar_exits"] = int(STATS.get("v703_r35_structural_closed_bar_exits",0) or 0) + 1
            STATS[f"v703_r35_structural_closed_bar_exits.{fam}"] = int(STATS.get(f"v703_r35_structural_closed_bar_exits.{fam}",0) or 0) + 1
            trade.structural_invalidation_fail_count = 0
            logger.warning(
                f"[V703-R35] {trade.symbol} STRUCTURAL_INVALIDATION confirmed_on_closed_5m "
                f"close={close:.10g} trigger={trigger:.10g} prev_bar={prev_ts} bar={bar_ts} family={fam}"
            )
            return True
        return False
    except Exception as exc:
        STATS["v703_r35_structural_guard_errors"] = int(STATS.get("v703_r35_structural_guard_errors",0) or 0) + 1
        try: _v593_note_suppressed_exception("v703.r35.structural_closed_bar", exc)
        except Exception: pass
        return False

def _v703_context_scalar(v: Any) -> str:
    try:
        if hasattr(v,"isoformat"):
            return str(v.isoformat())
        return str(v)
    except Exception:
        return str(v)

globals()["_v702_structural_failure_guard"] = _v703_r35_structural_failure_guard

# ---- Route symbol hygiene: placeholders can never reach execution ----------
_V703_R35_SYMBOL_RE = re.compile(r"^[A-Z0-9_.()\-]+/USDT$")

# Save R34 validator as historical and install R35 terminal validator.
_V703_R35_PREV_VALIDATE_CONFIG = _v702_r34_validate_config

def _v702_r36_retry_factory_integrity() -> bool:
    """Static contract guard: retry-safe reads must receive a callable factory, not a
    pre-created coroutine. This keeps retries replayable and prevents accidental
    reuse of an already-awaited coroutine. State-changing calls are intentionally
    excluded from retry-safe paths elsewhere in the runtime.
    """
    try:
        _source = _v702_read_source_text()
        for _call_source in _v702_iter_named_call_segments(_source, "safe_api_call"):
            try:
                _node = ast.parse(_call_source, mode="eval").body
            except Exception:
                return False
            if not isinstance(_node, ast.Call):
                return False
            _retry_safe = any(
                _kw.arg == "retry_safe"
                and isinstance(_kw.value, ast.Constant)
                and _kw.value.value is True
                for _kw in _node.keywords
            )
            if not _retry_safe:
                continue
            if len(_node.args) < 2:
                return False
            _supplied = _node.args[1]
            if isinstance(_supplied, (ast.Call, ast.Await)):
                return False
            if not isinstance(_supplied, (ast.Lambda, ast.Name, ast.Attribute, ast.Subscript)):
                return False
        return True
    except Exception:
        return False

def _v703_r36_validate_config() -> bool:
    checks: Dict[str, bool] = {}
    try:
        prev = bool(_V703_R35_PREV_VALIDATE_CONFIG())
        engines = list(globals().get("_MSE_ENGINES", ()) or ())
        enabled = []
        for eng in engines:
            try: enabled.append(bool(eng.enabled()))
            except Exception: enabled.append(False)
        # The active identity may be a later terminal closure (R37/R38); older
        # validators must verify synchronized surfaces, not freeze the release tag.
        _identity_expected = str(CANONICAL_RUNTIME_IDENTITY or V702_R36_PUBLIC_RUNTIME_IDENTITY)
        _expected_engine_ids = {
            "mtf_pullback", "pullback", "breakout", "liq_sweep",
            "mean_reversion", "trend_cont", "local_strength_breakout",
            "compression_expansion", "swing_pullback", "extreme_flush_reversal",
            "continuation_reclaim", "failed_breakout_reclaim",
            "volatility_burst_v45", "relative_strength_leader_v45",
            "micro_trend_cont_v459", "opportunity_scout_v521",
            "dual_confirmation_entry_v537", "liquidity_acceptance_reclaim",
        }
        _actual_engine_ids = {str(getattr(e, "engine_id", "")) for e in engines}
        _contracts = globals().get("_V701_3_STRATEGY_CONTRACTS", {}) or {}
        _identity_values = {
            "SCRIPT_VERSION": str(globals().get("SCRIPT_VERSION", "")),
            "CONFIG_SCRIPT_VERSION": str(CONFIG.get("SCRIPT_VERSION", "")),
            "MODULE_VERSION": str(globals().get("__version__", "")),
            "RUNTIME_BUILD_ID": str(globals().get("RUNTIME_BUILD_ID", "")),
            "CANONICAL_RUNTIME_IDENTITY": str(globals().get("CANONICAL_RUNTIME_IDENTITY", "")),
            "STATS_script_version": str(STATS.get("script_version", "")),
            "STATS_runtime_build_id": str(STATS.get("runtime_build_id", "")),
            "STATS_canonical_runtime_identity": str(STATS.get("canonical_runtime_identity", "")),
        }
        checks.update({
            # R34/R33 predecessor status is retained as historical provenance only.
            # Current R36 checks below are independently authoritative; a stale legacy
            # diagnostic must not veto a package whose current safety checks pass.
            "terminal_identity": all(v == _identity_expected for v in _identity_values.values()),
            "runtime_identity_surface_complete": len(set(_identity_values.values())) == 1 and next(iter(_identity_values.values()), "") == _identity_expected,
            "engine_registry_exact_18": len(engines) == 18 and len(enabled) == 18 and all(enabled),
            "engine_registry_exact_membership": _actual_engine_ids == _expected_engine_ids,
            "strategy_contracts_exact_23": len(_contracts) == 23,
            "spot_long_only": bool(CONFIG.get("LONG_ONLY",True)) and not bool(CONFIG.get("ALLOW_SHORT",False)) and not bool(CONFIG.get("ALLOW_SHORTS",False)) and str(CONFIG.get("TRADING_SIDE","LONG")).upper()=="LONG" and str(CONFIG.get("MARKET_TYPE","SPOT")).upper()=="SPOT" and not bool(CONFIG.get("ENABLE_FUTURES",False)) and not bool(CONFIG.get("FUTURES_ENABLED",False)),
            "forbidden_set_preserved": set(V702_HARD_FORBIDDEN_BASES).issuperset({"AERO","BNB","CAKE","ETHFI","PUMP"}),
            "live_score_floor": float(CONFIG.get("MIN_LIVE_SCORE",70.0)) >= 70.0,
            "core_liquidity_floor": float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME",3_000_000.0)) >= 3_000_000.0,
            "max_concurrent_trades": int(CONFIG.get("MAX_CONCURRENT_TRADES",2)) <= 2,
            "hard_gate_bypass_disabled": not bool(CONFIG.get("V702_R36_HARD_GATE_BYPASS",True)),
            "route_orderbook_handoff": bool(CONFIG.get("V702_R36_ORDERBOOK_ROUTE_HANDOFF_ENABLE",False)) and bool(CONFIG.get("V702_R36_BUILDER_ORDERBOOK_REUSE_ENABLE",False)),
            "snapshot_regime_coherence": bool(CONFIG.get("V702_R36_SNAPSHOT_REGIME_COHERENCE_ENABLE",False)),
            "closed_bar_structural_guard": bool(CONFIG.get("V702_R36_STRUCTURAL_CLOSED_BAR_CONFIRM_ENABLE",False)),
            "micro_bounded_recall": bool(CONFIG.get("V703_R35_MICRO_ALWAYS_RECALL_ENABLE",False)) and 1 <= int(CONFIG.get("V703_R35_MICRO_ALWAYS_RECALL_SYMBOLS",0) or 0) <= 8,
            "tp_split_invariant": abs(float(CONFIG.get("TP1_EXIT_PCT",0.5))+float(CONFIG.get("TP2_EXIT_PCT",0.3))+ (float(CONFIG.get("RUNNER_KEEP_PCT_AT_TP3",0.0)) if bool(CONFIG.get("ENABLE_RUNNER_MODE",False)) else 0.0) - 1.0) < 1e-9,
            "route_symbol_hygiene": bool(_V703_R35_SYMBOL_RE.fullmatch("BTC/USDT")) and not bool(_V703_R35_SYMBOL_RE.fullmatch("?/USDT")),
            "source_hash_matches_runtime": str(STATS.get("v702_r36_source_sha256_runtime", "")) == str(_v702_r26_source_sha256()),
            "canonical_duplicate_identical": (
                (not os.path.exists(os.path.join(os.path.dirname(__file__), "main_combined_V702_FINAL.py")))
                or (str(_v702_r26_source_sha256()) == hashlib.sha256(Path(os.path.join(os.path.dirname(__file__), "main_combined_V702_FINAL.py")).read_bytes()).hexdigest())
            ),
            "v689_boot_selftest_pass": bool(STATS.get("v689_final_boot_pass", False)),
            "mtf_1d_retry_factory_contract": "lambda _symbol=_symbol: exchange.fetch_ohlcv" in _v702_read_source_text(),
            "retry_safe_factory_integrity": _v702_r36_retry_factory_integrity(),
            "micro_trend_matches_micro_recall_tier": str(CanonicalStrategyPolicyRegistry.get("MICRO_TREND_CONTINUATION", {}).get("min_tier", "")).upper() == "MICRO",
            "btc_4h_warmup_matches_closed_ema200": int(CONFIG.get("BTC_SHARED_CONTEXT_MIN_CANDLES_4H", 0) or 0) >= 240 and 'btc_limits = {"5m":320, "15m":360, "1h":260, "4h":260}' in _v702_read_source_text(),
            "unknown_macro_policy_fails_closed": (not FamilyPolicyLayer.regime_policy_detail("PULLBACK", "UNKNOWN", local_regime="LOCAL_BEARISH")[0]) and FamilyPolicyLayer.regime_policy_detail("PULLBACK", "UNKNOWN", local_regime="LOCAL_BEARISH")[1] == "macro_context_unavailable",
            "bearish_severity_is_mandatory": bool(CONFIG.get("V425_BEARISH_SEVERITY_ENABLE", False)) and bool(getattr(getattr(V425BearishSeverity, "classify", None), "__func__", None) and getattr(V425BearishSeverity.classify.__func__, "_v702_r36_fail_closed_authority", False)),
            "unknown_severity_authority_is_fail_closed": bool(getattr(V425BearishSeverity.allows_new_long, "_v702_r36_fail_closed_authority", False)),
        })
        _context_test = _v702_r36_snapshot_context_self_test()
        STATS["v702_r36_snapshot_context_self_test"] = _context_test
        _context_checks = _context_test.get("checks", {}) if isinstance(_context_test, dict) else {}
        checks.update({
            "snapshot_context_regression_suite": bool(_context_test.get("pass", False)),
            "snapshot_missing_macro_context_fails_closed": bool(_context_checks.get("missing_macro_frame_unknown", False)),
            "snapshot_insufficient_macro_history_fails_closed": bool(_context_checks.get("short_macro_history_unknown", False)),
            "snapshot_invalid_closed_candle_fails_closed": bool(_context_checks.get("invalid_closed_macro_candle_unknown", False)),
            "bearish_missing_severity_context_fails_closed": bool(_context_checks.get("missing_bearish_15m_context_crash", False)),
            "bearish_malformed_severity_context_fails_closed": bool(_context_checks.get("malformed_bearish_15m_context_crash", False)),
            "active_snapshot_wrapper_missing_macro_fails_closed": bool(_context_checks.get("active_wrapper_missing_macro_fails_closed", False)),
            "active_snapshot_wrapper_bearish_missing_15m_crashes": bool(_context_checks.get("active_wrapper_bearish_missing_15m_crashes", False)),
        })
        STATS["v702_r36_historical_r34_validation_result"] = bool(prev)
        result = {"pass": bool(all(checks.values())), "historical_previous_r34_pass": bool(prev), "checks": checks, "closure": V702_R36_CLOSURE_ID, "revision": V702_R36_FINAL_CANONICAL_REVISION}
        STATS["v702_r36_final_validation"] = result
        FINAL_CANONICAL_RUNTIME["r36_validation"] = result
        if result["pass"]:
            logger.info("[V702-R36] FINAL CANONICAL PRODUCTION AUDIT VALIDATION PASS checks=%d", len(checks))
        else:
            logger.critical("[V702-R36] FINAL CANONICAL PRODUCTION AUDIT VALIDATION FAIL failed=%s", [k for k,v in checks.items() if not v])
        return bool(result["pass"])
    except Exception as exc:
        STATS["v702_r36_final_validation"] = {"pass":False,"error":f"{type(exc).__name__}:{exc}","closure":V702_R36_CLOSURE_ID}
        return False

