def _v702_r37_pipeline_integrity_self_test() -> Dict[str, Any]:
    checks: Dict[str, bool] = {}
    try:
        class _CandidateForHTFTest:
            def __init__(self, features):
                self.features_snapshot = dict(features)
                self.engine_score = 0.95
                self.strategy_mode = "PULLBACK"
                self.family = "PULLBACK"

        # Exact snapshot HTF always wins over the candidate's normalized alias.
        c1 = _CandidateForHTFTest({"htf_alignment": 0.6, "tier": "MID"})
        d1 = _v530_derive_context("TEST/USDT", c1, {"htf_strength": 86.5, "tier": "MID"})
        checks["snapshot_htf_strength_wins_over_candidate_alignment"] = abs(float(d1.get("htf", -1)) - 86.5) < 1e-9
        c2 = _CandidateForHTFTest({"htf_alignment": 0.6, "tier": "MID"})
        d2 = _v530_derive_context("TEST/USDT", c2, {"tier": "MID"})
        checks["normalized_htf_alignment_converted_to_percent"] = abs(float(d2.get("htf", -1)) - 60.0) < 1e-9
        c3 = _CandidateForHTFTest({"htf_alignment": 0.99, "tier": "MID"})
        d3 = _v530_derive_context("TEST/USDT", c3, {"htf_strength": 0.0, "tier": "MID"})
        checks["zero_snapshot_htf_is_not_overwritten"] = float(d3.get("htf", -1)) == 0.0
        e1 = _v540_candidate_ctx(c1, {"htf_strength": 86.5, "tier": "MID"})
        checks["elite_context_prefers_snapshot_htf"] = abs(float(e1.get("htf", -1)) - 86.5) < 1e-9
        c4 = _CandidateForHTFTest({"htf_strength": 91.0, "tier": "MID"})
        d4 = _v530_derive_context("TEST/USDT", c4, {"htf_alignment": 0.75, "tier": "MID"})
        checks["snapshot_alias_precedes_candidate_exact_htf"] = abs(float(d4.get("htf", -1)) - 75.0) < 1e-9

        sample_rejection = "\n".join([
            "<b>Top reasons / stages / exception types</b>",
            "Stages: family_policy×6",
            "Exceptions: -",
            "",
            "<b>Top reasons</b>",
            "htf.family_htf_strength_below_floor×4, liquidity.below_tier×2",
        ])
        parsed = _V702R28TelegramDigest._rejection_line(sample_rejection)
        checks["digest_extracts_actual_top_reason_list"] = (
            "htf.family_htf_strength_below_floor×4" in parsed
            and "top=/ stages / exception types" not in parsed
        )
        _had_cycle = "v681_runtime_cycle_id" in STATS
        _old_cycle = STATS.get("v681_runtime_cycle_id")
        _had_route = "v702_selected_route_last" in STATS
        _old_route = STATS.get("v702_selected_route_last")
        try:
            STATS["v681_runtime_cycle_id"] = 93701
            STATS["v702_selected_route_last"] = {
                "cycle_id": 93701, "symbol": "TEST/USDT", "stage": "selected_preexec_policy",
                "reason": "htf.family_htf_strength_below_floor", "ts": WALL_NOW(),
            }
            _current_route_line = _V702R28TelegramDigest._selected_route_summary()
            STATS["v681_runtime_cycle_id"] = 93702
            _stale_route_line = _V702R28TelegramDigest._selected_route_summary()
            checks["digest_exposes_active_selected_route_reason"] = "TEST/USDT:selected_preexec_policy:htf.family_htf_strength_below_floor" in _current_route_line
            checks["digest_hides_stale_selected_route_reason"] = _stale_route_line == "none"
        finally:
            if _had_cycle:
                STATS["v681_runtime_cycle_id"] = _old_cycle
            else:
                STATS.pop("v681_runtime_cycle_id", None)
            if _had_route:
                STATS["v702_selected_route_last"] = _old_route
            else:
                STATS.pop("v702_selected_route_last", None)
        checks["detailed_policy_reason_bucket_local"] = _v456_reason_bucket("family_regime_disallowed.local_regime_not_allowed") == "POLICY_LOCAL"
        if _PDNP_OK:
            _short = pd.DataFrame({"close": [100.0 + float(i) for i in range(60)]})
            _, _short_state, _, _short_reason = HTFGrader.grade(_short, label="R37_TEST")
            checks["short_ema200_history_is_unknown_not_bearish"] = _short_state == "UNKNOWN" and _short_reason == "insufficient_data"
            _fake_snap = {"htf_state": "UNKNOWN", "htf_reason": "insufficient_data", "htf_strength": 0.0,
                          "df_1h": _short, "df_4h": _short, "cycle_id": "R37_TEST"}
            _resolved, _source, _age = _v689_resolve_htf_strength("R37_TEST/USDT", _fake_snap)
            checks["htf_recovery_rejects_short_ema200_history"] = _resolved is None and _source == "UNAVAILABLE"
        else:
            checks["short_ema200_history_is_unknown_not_bearish"] = False
            checks["htf_recovery_rejects_short_ema200_history"] = False
        checks["htf_recompute_warmup_contract_in_source"] = (
            "required_1h=max(210,int(CONFIG.get(\"HTF_MIN_CANDLES_1H\",240) or 240))" in _v702_read_source_text()
            and "required_4h=max(210,int(CONFIG.get(\"HTF_MIN_CANDLES_4H\",200) or 200))" in _v702_read_source_text()
        )
        checks["snapshot_is_market_phase_authority"] = (
            'if "market_phase" in snap:' in _v702_read_source_text()
            and 'phase = snap.get("market_phase")' in _v702_read_source_text()
        )
        _live_engines = tuple(globals().get("_MSE_ENGINES") or ())
        _all_engines = tuple(globals().get("_V702_ALL_MSE_ENGINES") or ())
        checks["live_engine_registry_counters_reconciled"] = (
            int(STATS.get("v702_live_engine_count", -1)) == len(_live_engines)
            and int(CONFIG.get("V702_LIVE_ENGINE_COUNT", -1)) == len(_live_engines)
        )
        checks["registered_engine_registry_counters_reconciled"] = (
            int(STATS.get("v702_registered_engine_count", -1)) == len(_all_engines)
            and int(CONFIG.get("V702_REGISTERED_ENGINE_COUNT", -1)) == len(_all_engines)
        )
        checks["canonical_engine_registry_has_18_active_engines"] = (
            len(_live_engines) == 18 and len(_all_engines) == 18
            and not tuple(globals().get("_V702_DISABLED_ENGINE_NAMES") or ())
            and bool(STATS.get("v702_engine_registry_telemetry_reconciled", False))
        )
        return {"pass": bool(checks) and all(checks.values()), "checks": checks, "failed": [k for k,v in checks.items() if not v]}
    except Exception as exc:
        return {"pass": False, "checks": checks, "error": f"{type(exc).__name__}:{exc}", "failed": [k for k,v in checks.items() if not v]}


_V702_R37_PREVIOUS_VALIDATOR = globals().get("validate_config")
def _v702_r37_validate_config() -> bool:
    previous_ok = False
    try:
        previous_ok = bool(_V702_R37_PREVIOUS_VALIDATOR()) if callable(_V702_R37_PREVIOUS_VALIDATOR) else False
        test = _v702_r37_pipeline_integrity_self_test()
        STATS["v702_r37_pipeline_integrity_self_test"] = test
        old = dict(STATS.get("v702_r36_final_validation") or {})
        checks = dict(old.get("checks") or {})
        checks.update({f"r37_{k}": bool(v) for k,v in (test.get("checks") or {}).items()})
        final = {
            "pass": bool(previous_ok and test.get("pass", False)),
            "previous_validation": previous_ok,
            # Preserve forensic R34 status through the R37 compatibility alias;
            # it is informational and cannot veto the current R36/R37 checks.
            "historical_previous_r34_pass": bool(old.get("historical_previous_r34_pass", False)),
            "checks": checks,
            "closure": V702_R37_CLOSURE_ID,
            "revision": V702_R37_FINAL_CANONICAL_REVISION,
            "failed": [k for k,v in checks.items() if not v],
        }
        STATS["v702_r37_final_validation"] = final
        # Compatibility keys now point to the active final validation result.
        STATS["v702_r36_final_validation"] = final
        FINAL_CANONICAL_RUNTIME["r37_validation"] = final
        FINAL_CANONICAL_RUNTIME["r36_validation"] = final
        if final["pass"]:
            logger.info("[V702-R37] FINAL CANONICAL PRODUCTION AUDIT VALIDATION PASS checks=%d", len(checks))
        else:
            logger.critical("[V702-R37] FINAL CANONICAL PRODUCTION AUDIT VALIDATION FAIL failed=%s", final["failed"])
        return bool(final["pass"])
    except Exception as exc:
        STATS["v702_r37_final_validation"] = {"pass": False, "error": f"{type(exc).__name__}:{exc}", "previous_validation": previous_ok}
        return False

