# ---------------------------------------------------------------------------
# V702 R37 canonical runtime — S/R-aware target planning closure.
# This patch changes only final target placement; it does not add an entry path.
# Targets are bounded by completed 15m swing-resistance pivots and always return
# through the existing family-distance, RiskCoherence, fee, PreSend and execution
# authorities. Incomplete/unavailable SR context preserves canonical ExitProfile RR.
# ---------------------------------------------------------------------------
V702_SR_TARGETS_REVISION = "V702-R37-SR-AWARE-TARGETS-FINAL-2026-10-09"
CONFIG.update({
    "V702_SR_AWARE_TARGETS_ENABLE": True,
    "V702_SR_TARGET_LOOKBACK_BARS": 48,
    "V702_SR_TARGET_PIVOT_WINDOW": 2,
    "V702_SR_TARGET_CLUSTER_ATR": 0.25,
    "V702_SR_TARGET_BUFFER_ATR": 0.10,
    "V702_SR_TARGET_BUFFER_PCT": 0.0004,
    "V702_SR_TARGET_MIN_SEPARATION_ATR": 0.25,
    "V702_SR_TARGET_MIN_TOUCHES": 1,
    "V702_SR_MAX_DATA_AGE_SEC": 3600.0,
})
STATS["v702_sr_aware_target_policy"] = {
    "revision": V702_SR_TARGETS_REVISION,
    "enabled": bool(CONFIG.get("V702_SR_AWARE_TARGETS_ENABLE", True)),
    "timeframe": "15m",
    "closed_bar_only": True,
    "tp1": "cap_before_nearest_confirmed_resistance_if_inside_profile_target",
    "tp2": "cap_before_next_distinct_resistance_if_inside_profile_target",
    "tp3": "preserve_strategy_native_exit_profile_rr",
    "fallback": "canonical_exit_profile_rr",
    "hard_gate_bypass": False,
}


def _v702_sr_aware_target_plan(*, entry, sl, tp1_rr, tp2_rr, tp3_rr,
                               df_15m=None, family="", atr_hint=0.0):
    """Return (through dict) canonical RR targets capped before closed-bar SR.

    This is a long-only target planner. It never changes entry, stop, size, score,
    family policy, liquidity or fees. Only right-confirmed swing highs from a
    bounded window of completed 15m candles can cap targets. Target prices stay
    strictly ordered, while the canonical fee/RR gates decide final viability.
    """
    e = float(entry); stop = float(sl)
    r1 = float(tp1_rr); r2 = float(tp2_rr); r3 = float(tp3_rr)
    risk = e - stop
    if not all(math.isfinite(v) for v in (e, stop, r1, r2, r3)) or e <= 0 or stop <= 0 or risk <= 0 or not (0 < r1 < r2 < r3):
        raise ValueError("invalid_entry_stop_or_exit_profile")
    base1 = e + r1 * risk
    base2 = e + r2 * risk
    base3 = e + r3 * risk
    result = {
        "ok": True, "blocked": False, "enabled": bool(CONFIG.get("V702_SR_AWARE_TARGETS_ENABLE", True)),
        "revision": V702_SR_TARGETS_REVISION, "family": str(family or "").upper(),
        "entry": e, "sl": stop, "tp1": base1, "tp2": base2, "tp3": base3,
        "tp1_source": "EXIT_PROFILE_RR", "tp2_source": "EXIT_PROFILE_RR", "tp3_source": "EXIT_PROFILE_RR",
        "tp1_rr": r1, "tp2_rr": r2, "tp3_rr": r3,
        "support": None, "resistance_levels": [], "used_resistance_tp1": None,
        "used_resistance_tp2": None, "reason": "canonical_rr_fallback", "hard_gate_bypass": False,
    }
    if not result["enabled"]:
        result["reason"] = "disabled"
        return result
    if df_15m is None or not hasattr(df_15m, "iloc"):
        result["reason"] = "sr_dataframe_unavailable"
        return result

    # V702 R38: if OHLCV supplies source timestamps, never apply a stale S/R
    # ceiling as if it were current. Frames without timestamps retain the existing
    # upstream snapshot-freshness contract and are not rejected merely for format.
    try:
        _sr_ts_raw = None
        _sr_ts_source = ""
        for _ts_col in ("timestamp", "time", "ts", "datetime", "date"):
            if _ts_col in getattr(df_15m, "columns", []):
                _sr_ts_raw = df_15m[_ts_col].iloc[-2]
                _sr_ts_source = f"column:{_ts_col}"
                break
        if _sr_ts_raw is None:
            _idx = getattr(df_15m, "index", None)
            if _idx is not None and len(_idx) >= 2:
                _idx_val = _idx[-2]
                if hasattr(_idx_val, "timestamp"):
                    _sr_ts_raw = float(_idx_val.timestamp())
                    _sr_ts_source = "datetime_index"
        if _sr_ts_raw is not None:
            _sr_ts = _v705_epoch_to_seconds(_sr_ts_raw)
            if _sr_ts <= 0.0:
                # Preserve support for ISO strings, pandas Timestamp, and datetime.
                _pd_ts = __import__("pandas").to_datetime(_sr_ts_raw, utc=True, errors="raise")
                _sr_ts = float(_pd_ts.timestamp())
            if _sr_ts > 0 and math.isfinite(_sr_ts):
                _sr_age = max(0.0, float(WALL_NOW()) - (_sr_ts + 15.0 * 60.0))
                _sr_max_age = max(900.0, float(CONFIG.get("V702_SR_MAX_DATA_AGE_SEC", 3600.0) or 3600.0))
                result["sr_data_age_sec"] = float(_sr_age)
                result["sr_timestamp_source"] = _sr_ts_source
                if _sr_age > _sr_max_age:
                    result["reason"] = "sr_data_stale"
                    result["sr_data_max_age_sec"] = float(_sr_max_age)
                    return result
    except Exception as _v705_sr_freshness_exc:
        # Parsing remains a freshness-only guard; count failures instead of
        # silently swallowing them. Global snapshot sanitation stays authoritative.
        try:
            STATS["v705_sr_freshness_parse_errors"] = int(
                STATS.get("v705_sr_freshness_parse_errors", 0) or 0
            ) + 1
            STATS["v705_sr_freshness_last_error"] = {
                "type": type(_v705_sr_freshness_exc).__name__,
                "error": str(_v705_sr_freshness_exc)[:200],
                "source": str(_sr_ts_source)[:64],
                "ts": float(WALL_NOW()),
            }
        except Exception:
            logger.debug("[V705-SR] parse telemetry failed", exc_info=True)

    try:
        n = max(20, int(CONFIG.get("V702_SR_TARGET_LOOKBACK_BARS", 48) or 48))
        w = max(1, int(CONFIG.get("V702_SR_TARGET_PIVOT_WINDOW", 2) or 2))
        if len(df_15m) < max(2 * w + 10, 20):
            result["reason"] = "sr_history_too_short"
            return result
        # The last dataframe row is the forming candle; exclude it. A second
        # closed bar is omitted on purpose so each retained pivot has right-side
        # confirmation and matches the runtime's existing dynamic-S/R semantics.
        take = min(n, max(0, len(df_15m) - 2))
        prior = df_15m.iloc[-(take + 2):-2].copy() if take else df_15m.iloc[0:0].copy()
        if len(prior) < 2 * w + 3:
            result["reason"] = "sr_confirmed_window_too_short"
            return result
        atr = float(atr_hint or 0.0)
        if not math.isfinite(atr) or atr <= 0:
            try:
                av = Indicators.atr(df_15m, int(CONFIG.get("ATR_PERIOD", 14) or 14))
                atr = float(av.iloc[-2]) if av is not None and len(av) > 2 else 0.0
            except Exception:
                atr = 0.0
        if not math.isfinite(atr) or atr <= 0:
            result["reason"] = "sr_atr_unavailable"
            return result

        highs = []
        lows = []
        for i in range(w, len(prior) - w):
            hi = float(prior["high"].iloc[i]); lo = float(prior["low"].iloc[i])
            left_hi = float(prior["high"].iloc[i-w:i].max())
            right_hi = float(prior["high"].iloc[i+1:i+w+1].max())
            left_lo = float(prior["low"].iloc[i-w:i].min())
            right_lo = float(prior["low"].iloc[i+1:i+w+1].min())
            if all(math.isfinite(v) for v in (hi, lo, left_hi, right_hi, left_lo, right_lo)):
                if hi >= left_hi and hi >= right_hi:
                    highs.append(hi)
                if lo <= left_lo and lo <= right_lo:
                    lows.append(lo)

        cluster_tol = max(atr * float(CONFIG.get("V702_SR_TARGET_CLUSTER_ATR", 0.25) or 0.25), e * 1e-7)
        min_touches = max(1, int(CONFIG.get("V702_SR_TARGET_MIN_TOUCHES", 1) or 1))

        def _cluster_levels(values):
            ordered = sorted(float(x) for x in values if math.isfinite(float(x)) and float(x) > 0)
            clusters = []
            for value in ordered:
                if not clusters or value - clusters[-1][-1] > cluster_tol:
                    clusters.append([value])
                else:
                    clusters[-1].append(value)
            return [(sum(c) / len(c), len(c)) for c in clusters if len(c) >= min_touches]

        high_clusters = _cluster_levels(highs)
        low_clusters = _cluster_levels(lows)
        # A fallback range extreme is useful when no local pivot exists, but it
        # is drawn only from the confirmed historical window, never from a live bar.
        if not high_clusters:
            try:
                range_high = float(prior["high"].max())
                if math.isfinite(range_high) and range_high > 0:
                    high_clusters = [(range_high, 1)]
            except Exception:
                high_clusters = []
        support_candidates = sorted((lv, touches) for lv, touches in low_clusters if lv < e)
        if support_candidates:
            result["support"] = float(support_candidates[-1][0])
        resistances = sorted(set(round(float(lv), 12) for lv, touches in high_clusters if lv > e * (1.0 + 1e-7)))
        result["resistance_levels"] = [float(x) for x in resistances[:12]]
        if not resistances:
            result["reason"] = "no_confirmed_resistance_above_entry"
            return result

        buffer = max(atr * float(CONFIG.get("V702_SR_TARGET_BUFFER_ATR", 0.10) or 0.10), e * float(CONFIG.get("V702_SR_TARGET_BUFFER_PCT", 0.0004) or 0.0004))
        min_sep = max(atr * float(CONFIG.get("V702_SR_TARGET_MIN_SEPARATION_ATR", 0.25) or 0.25), e * 1e-5)
        effective = [(lv, lv - buffer) for lv in resistances]
        first_level, first_cap = effective[0]
        if first_cap < base1 - max(1e-12, e * 1e-10):
            if first_cap <= e + max(e * 1e-7, 1e-12):
                result.update({"ok": False, "blocked": True, "reason": "nearest_resistance_leaves_no_target_room",
                               "nearest_resistance": first_level, "buffer": buffer})
                return result
            result["tp1"] = float(first_cap)
            result["tp1_source"] = "RESISTANCE"
            result["used_resistance_tp1"] = float(first_level)

        target1 = float(result["tp1"])
        for level, cap in effective:
            if level <= target1 + buffer + min_sep:
                continue
            if cap <= target1 + min_sep:
                continue
            if cap < base2 - max(1e-12, e * 1e-10):
                result["tp2"] = float(cap)
                result["tp2_source"] = "RESISTANCE"
                result["used_resistance_tp2"] = float(level)
                break

        # TP3 remains profile-native so runner and exit manager behavior is kept.
        # Structural caps are only allowed if strict target ordering survives.
        if not (stop < e < float(result["tp1"]) < float(result["tp2"]) < float(result["tp3"])):
            raise ValueError("sr_target_ordering_invalid")
        result["tp1_rr"] = (float(result["tp1"]) - e) / risk
        result["tp2_rr"] = (float(result["tp2"]) - e) / risk
        result["tp3_rr"] = (float(result["tp3"]) - e) / risk
        result["reason"] = "sr_capped_tp1_tp2" if (result["tp1_source"] == "RESISTANCE" or result["tp2_source"] == "RESISTANCE") else "canonical_rr_preserved"
        result["buffer"] = float(buffer)
        result["atr_15m"] = float(atr)
        result["hard_gate_bypass"] = False
        return result
    except Exception as exc:
        # Return safe canonical RR levels but retain the failure reason. The
        # already-existing economic and geometry checks still validate this plan.
        result["reason"] = f"sr_calculation_fallback:{type(exc).__name__}"
        return result


def _v702_sr_target_rescue_compatible(*, entry, tp1, tp2, context):
    """Prevent the existing fee-target rescue from undoing a structural TP cap."""
    try:
        ctx = dict(context or {})
        levels = [float(x) for x in (ctx.get("resistance_levels") or []) if math.isfinite(float(x)) and float(x) > float(entry)]
        if not bool(ctx.get("enabled", False)) or not levels:
            return True, "no_sr_ceiling"
        buffer = max(0.0, float(ctx.get("buffer", 0.0) or 0.0))
        e = float(entry); t1 = float(tp1); t2 = float(tp2)
        tol = max(e * 1e-8, 1e-12)
        # TP1 must stay before the nearest overhead resistance. TP2 may lie
        # beyond the resistance already used by TP1, but not beyond the next
        # unconsumed resistance if one exists. This preserves staged exit logic.
        first = min(levels)
        first_cap = first - buffer
        if t1 > first_cap + tol:
            return False, f"tp1_crosses_resistance:{first:.12g}:cap={first_cap:.12g}:target={t1:.12g}"
        next_levels = [level for level in levels if (level - buffer) > t1 + tol]
        if next_levels:
            next_level = min(next_levels)
            next_cap = next_level - buffer
            if t2 > next_cap + tol:
                return False, f"tp2_crosses_resistance:{next_level:.12g}:cap={next_cap:.12g}:target={t2:.12g}"
        return True, "within_sr_caps"
    except Exception as exc:
        # A malformed S/R snapshot cannot authorize a fee-rescue target mutation.
        return False, f"sr_rescue_validation_error:{type(exc).__name__}"


def _v702_sr_target_plan_self_test():
    checks = {}
    try:
        import math as _math
        import numpy as _np
        import pandas as _pd
        nrows = 90
        close = _np.full(nrows, 103.2, dtype=float)
        open_ = close - 0.05
        high = _np.full(nrows, 103.8, dtype=float)
        low = _np.full(nrows, 102.8, dtype=float)
        volume = _np.full(nrows, 1000.0, dtype=float)
        # Three confirmed 105 pivots and two confirmed 107 pivots in the retained
        # closed history; normal highs stay under the entry to avoid false levels.
        for ix in (36, 45, 54): high[ix] = 105.0
        for ix in (66, 75): high[ix] = 107.0
        df = _pd.DataFrame({"open":open_,"high":high,"low":low,"close":close,"volume":volume})
        old = {k: CONFIG.get(k) for k in ("V702_SR_AWARE_TARGETS_ENABLE", "V702_SR_TARGET_LOOKBACK_BARS", "V702_SR_TARGET_PIVOT_WINDOW", "V702_SR_TARGET_CLUSTER_ATR", "V702_SR_TARGET_BUFFER_ATR", "V702_SR_TARGET_BUFFER_PCT", "V702_SR_TARGET_MIN_SEPARATION_ATR", "V702_SR_TARGET_MIN_TOUCHES")}
        try:
            CONFIG.update({"V702_SR_AWARE_TARGETS_ENABLE":True,"V702_SR_TARGET_LOOKBACK_BARS":48,"V702_SR_TARGET_PIVOT_WINDOW":2,"V702_SR_TARGET_CLUSTER_ATR":0.25,"V702_SR_TARGET_BUFFER_ATR":0.10,"V702_SR_TARGET_BUFFER_PCT":0.0004,"V702_SR_TARGET_MIN_SEPARATION_ATR":0.25,"V702_SR_TARGET_MIN_TOUCHES":1})
            capped = _v702_sr_aware_target_plan(entry=104.0,sl=103.0,tp1_rr=3.0,tp2_rr=5.0,tp3_rr=7.0,df_15m=df,atr_hint=1.0,family="PULLBACK")
            checks["caps_tp1_before_nearest_resistance"] = capped.get("tp1_source") == "RESISTANCE" and abs(float(capped["tp1"])-104.9) < 1e-9
            checks["caps_tp2_before_next_distinct_resistance"] = capped.get("tp2_source") == "RESISTANCE" and abs(float(capped["tp2"])-106.9) < 1e-9
            checks["strict_target_ordering_after_caps"] = 103.0 < 104.0 < capped["tp1"] < capped["tp2"] < capped["tp3"]
            no_sr = _v702_sr_aware_target_plan(entry=108.0,sl=107.0,tp1_rr=2.0,tp2_rr=3.0,tp3_rr=4.0,df_15m=df,atr_hint=1.0,family="PULLBACK")
            checks["rr_fallback_when_no_resistance_above_entry"] = no_sr["tp1_source"] == "EXIT_PROFILE_RR" and no_sr["tp2_source"] == "EXIT_PROFILE_RR" and no_sr["tp1"] == 110.0 and no_sr["tp2"] == 111.0
            blocked = _v702_sr_aware_target_plan(entry=104.96,sl=103.96,tp1_rr=2.0,tp2_rr=3.0,tp3_rr=4.0,df_15m=df,atr_hint=1.0,family="PULLBACK")
            checks["blocks_entry_when_nearest_resistance_has_no_room"] = bool(blocked.get("blocked")) and blocked.get("reason") == "nearest_resistance_leaves_no_target_room"
            CONFIG["V702_SR_AWARE_TARGETS_ENABLE"] = False
            disabled = _v702_sr_aware_target_plan(entry=104.0,sl=103.0,tp1_rr=1.0,tp2_rr=2.0,tp3_rr=3.0,df_15m=df,atr_hint=1.0,family="PULLBACK")
            checks["feature_disable_preserves_exit_profile"] = disabled["reason"] == "disabled" and disabled["tp1"] == 105.0 and disabled["tp2"] == 106.0 and disabled["tp3"] == 107.0
            CONFIG["V702_SR_AWARE_TARGETS_ENABLE"] = True
            malformed = _v702_sr_aware_target_plan(entry=100.0,sl=99.0,tp1_rr=1.0,tp2_rr=2.0,tp3_rr=3.0,df_15m=None,atr_hint=1.0,family="PULLBACK")
            checks["missing_sr_data_falls_back_without_exception"] = malformed["reason"] == "sr_dataframe_unavailable" and malformed["tp1"] == 101.0 and malformed["tp2"] == 102.0
            checks["sr_policy_never_authorizes_gate_bypass"] = capped.get("hard_gate_bypass") is False and blocked.get("hard_gate_bypass") is False
            compatible, _ = _v702_sr_target_rescue_compatible(entry=104.0,tp1=capped["tp1"],tp2=capped["tp2"],context=capped)
            incompatible, why = _v702_sr_target_rescue_compatible(entry=104.0,tp1=106.0,tp2=108.0,context=capped)
            checks["fee_target_rescue_cannot_erase_sr_resistance_caps"] = compatible and not incompatible and "crosses_resistance" in why
        finally:
            for k, v in old.items():
                if v is None: CONFIG.pop(k, None)
                else: CONFIG[k] = v
        return {"pass": bool(checks) and all(checks.values()), "checks": checks, "failed": [k for k,v in checks.items() if not v], "revision": V702_SR_TARGETS_REVISION}
    except Exception as exc:
        return {"pass":False,"checks":checks,"failed":[k for k,v in checks.items() if not v],"error":f"{type(exc).__name__}:{exc}","revision":V702_SR_TARGETS_REVISION}


_V702_R38_PREVIOUS_VALIDATOR = globals().get("validate_config")
def _v702_r38_validate_config() -> bool:
    previous_ok = False
    try:
        previous_ok = bool(_V702_R38_PREVIOUS_VALIDATOR()) if callable(_V702_R38_PREVIOUS_VALIDATOR) else False
        test = _v702_sr_target_plan_self_test()
        STATS["v702_sr_target_plan_self_test"] = test
        old = dict(STATS.get("v702_r37_final_validation") or {})
        checks = dict(old.get("checks") or {})
        checks.update({f"sr_targets_{k}": bool(v) for k,v in (test.get("checks") or {}).items()})
        final = {
            "pass": bool(previous_ok and test.get("pass",False)),
            "previous_validation": previous_ok,
            "checks": checks,
            "closure": V702_SR_TARGETS_REVISION,
            "revision": V702_SR_TARGETS_REVISION,
            "failed": [k for k,v in checks.items() if not v],
            "hard_gate_bypass": False,
        }
        STATS["v702_sr_target_final_validation"] = final
        FINAL_CANONICAL_RUNTIME["sr_target_revision"] = V702_SR_TARGETS_REVISION
        FINAL_CANONICAL_RUNTIME["sr_target_validation"] = final
        if final["pass"]:
            logger.info("[V702-SR-TARGETS] final validation PASS checks=%d", len(checks))
        else:
            logger.critical("[V702-SR-TARGETS] final validation FAIL failed=%s", final["failed"])
        return bool(final["pass"])
    except Exception as exc:
        STATS["v702_sr_target_final_validation"] = {"pass":False,"error":f"{type(exc).__name__}:{exc}","previous_validation":previous_ok}
        return False

globals()["validate_config"] = _v702_r38_validate_config


# ---------------------------------------------------------------------------
# V702 R38 — Canonical live pipeline ledger and final-price contract.
# This ledger is observational only: it never changes ranking, gate decisions,
# sizing, the forbidden list, or order routing. Its scope is explicitly LIVE_EPOCH
# and active cycle, unlike legacy counters that mix cycle and process totals.
# ---------------------------------------------------------------------------
_V702_PIPELINE_CONTEXT = contextvars.ContextVar("v702_pipeline_candidate_context", default=None)
_V702_PREQUAL_SOURCE = contextvars.ContextVar("v702_prequal_source", default="arbiter")


def _v702_price_to_precision(exchange, symbol, price):
    """Return a tick-normalized positive price or a fail-closed reason."""
    try:
        value = float(price)
        if not math.isfinite(value) or value <= 0:
            return False, None, "price_non_positive_or_non_finite"
        if not bool(CONFIG.get("PRECISION_PREFLIGHT_ENABLE", True)):
            return True, value, "precision_disabled_by_existing_config"
        fn = getattr(exchange, "price_to_precision", None)
        if not callable(fn):
            if bool(CONFIG.get("PRECISION_FAIL_CLOSED", True)):
                return False, None, "price_to_precision_unavailable"
            return True, value, "price_to_precision_unavailable_permitted_by_config"
        out = float(fn(str(symbol), value))
        if not math.isfinite(out) or out <= 0:
            return False, None, "precision_result_invalid"
        return True, out, "ok"
    except Exception as exc:
        if bool(CONFIG.get("PRECISION_FAIL_CLOSED", True)):
            return False, None, f"precision_error:{type(exc).__name__}"
        try:
            value = float(price)
            return (True, value, "precision_fallback_configured") if math.isfinite(value) and value > 0 else (False, None, "price_invalid")
        except Exception:
            return False, None, "price_invalid"


def _v702_normalize_final_geometry(*, exchange, symbol, entry, sl, tp1, tp2, tp3,
                                   sr_context=None, notional=0.0, check_economics=False,
                                   family="", atr=0.0, spread_pct=None):
    """Single final price authority used after PreSend and by offline integration tests."""
    names = ("entry", "sl", "tp1", "tp2", "tp3")
    raw = {"entry":entry, "sl":sl, "tp1":tp1, "tp2":tp2, "tp3":tp3}
    out = {"ok":False,"reason":"uninitialized","hard_gate_bypass":False,"precision_applied":True}
    px = {}
    for name in names:
        ok, value, reason = _v702_price_to_precision(exchange, symbol, raw[name])
        if not ok:
            out.update({"reason":f"precision_{name}:{reason}","precision_failure":name,"raw":raw})
            return out
        px[name] = float(value)
    if not (0 < px["sl"] < px["entry"] < px["tp1"] < px["tp2"] < px["tp3"]):
        out.update({"reason":"rounded_risk_reward_order_invalid","prices":px,"raw":raw})
        return out
    try:
        _rc_ok, _rc_msg = RiskCoherence.check(px["entry"],px["sl"],px["tp1"],px["tp2"],tp3=px["tp3"])
        if not _rc_ok:
            out.update({"reason":f"risk_coherence_after_precision:{_rc_msg}","prices":px,"raw":raw})
            return out
    except Exception as exc:
        out.update({"reason":f"risk_coherence_error:{type(exc).__name__}","prices":px})
        return out
    if family and bool(CONFIG.get("V410_MASTER_ENABLE", True)):
        try:
            if not FamilyPolicyLayer.tp1_distance_ok(px["entry"],px["tp1"],float(atr or 0.0),str(family)):
                out.update({"reason":"tp1_distance_invalid_after_precision","prices":px,"raw":raw})
                return out
        except Exception as exc:
            out.update({"reason":f"tp1_distance_validation_error:{type(exc).__name__}","prices":px})
            return out
    sr_ok, sr_reason = _v702_sr_target_rescue_compatible(
        entry=px["entry"],tp1=px["tp1"],tp2=px["tp2"],context=sr_context or {}
    )
    if not sr_ok:
        out.update({"reason":f"sr_cap_after_precision:{sr_reason}","prices":px,"raw":raw})
        return out
    if check_economics:
        try:
            n = float(notional or 0.0)
            if not math.isfinite(n) or n <= 0:
                out.update({"reason":"fee_notional_invalid","prices":px})
                return out
            fee = SizingEngine.fee_viability_detail(
                px["entry"], px["sl"], px["tp1"], px["tp2"], n,
                spread_pct=spread_pct,
                small_net_mode=bool(CONFIG.get("V702_SMALL_NET_PROFIT_MODE_ENABLE", False)),
            )
            if not bool(fee.get("ok",False)):
                out.update({"reason":f"fee_{fee.get('reason','unviable')}","prices":px,"fee_detail":fee})
                return out
            out["fee_detail"] = fee
        except Exception as exc:
            out.update({"reason":f"fee_validation_error:{type(exc).__name__}","prices":px})
            return out
    out.update(px)
    out.update({"ok":True,"reason":"ok","sr_compatible":True,"sr_reason":sr_reason})
    return out


def _v702_reanchor_targets_after_fill(*, exchange, symbol, planned_entry, fill_entry,
                                      planned_sl, planned_tp1, planned_tp2, planned_tp3,
                                      sr_context=None):
    """Re-anchor offsets to actual fill without discarding caps or fee-rescued RR."""
    try:
        pe=float(planned_entry); fe=float(fill_entry); ps=float(planned_sl)
        t1=float(planned_tp1); t2=float(planned_tp2); t3=float(planned_tp3)
        if not all(math.isfinite(x) and x>0 for x in (pe,fe,ps,t1,t2,t3)) or not ps < pe < t1 < t2 < t3:
            return {"ok":False,"reason":"planned_geometry_invalid"}
        shift=fe-pe; risk=pe-ps
        sl=fe-risk
        tp1=t1+shift; tp2=t2+shift; tp3=t3+shift
        ctx=dict(sr_context or {})
        if bool(ctx.get("enabled",False)):
            levels=sorted(set(float(v) for v in (ctx.get("resistance_levels") or [])
                              if math.isfinite(float(v)) and float(v)>fe))
            buffer=max(0.0,float(ctx.get("buffer",0.0) or 0.0))
            tol=max(fe*1e-8,1e-12)
            if levels:
                first_cap=levels[0]-buffer
                tp1=min(tp1,first_cap)
                if tp1 <= fe+tol:
                    return {"ok":False,"reason":"post_fill_tp1_no_room_before_resistance",
                            "resistance":levels[0],"buffer":buffer,"entry":fe,"tp1":tp1}
                next_levels=[lv for lv in levels if (lv-buffer)>tp1+tol]
                if next_levels:
                    tp2=min(tp2,next_levels[0]-buffer)
        normalized=_v702_normalize_final_geometry(
            exchange=exchange,symbol=symbol,entry=fe,sl=sl,tp1=tp1,tp2=tp2,tp3=tp3,
            sr_context=ctx,notional=0.0,check_economics=False
        )
        if not bool(normalized.get("ok",False)):
            return {**normalized,"ok":False,"reason":f"post_fill_{normalized.get('reason','geometry_invalid')}",
                    "planned_entry":pe,"fill_entry":fe,"planned_targets":[t1,t2,t3]}
        normalized.update({"planned_entry":pe,"fill_entry":fe,"shift":shift,
                           "sr_revision":str(ctx.get("revision",V702_SR_TARGETS_REVISION)),
                           "hard_gate_bypass":False})
        return normalized
    except Exception as exc:
        return {"ok":False,"reason":f"post_fill_exception:{type(exc).__name__}:{str(exc)[:120]}"}


def _v702_floor_price_to_precision(exchange, symbol, ceiling):
    """Normalize a price without rounding it above a structural price ceiling."""
    try:
        cap=float(ceiling)
        if not math.isfinite(cap) or cap<=0:
            return False, None, "ceiling_invalid"
        ok, rounded, why=_v702_price_to_precision(exchange,symbol,cap)
        tol=max(abs(cap)*1e-10,1e-12)
        if ok and float(rounded)<=cap+tol:
            return True,float(rounded),"ok"
        # A nearest-tick precision formatter may round upward. Walk downward
        # exponentially until it yields a valid tick, then return the first
        # known safe tick. This is intentionally one-sided (never above cap).
        delta=max(abs(cap)*1e-9,1e-12)
        for _ in range(48):
            ok2, value2, why2=_v702_price_to_precision(exchange,symbol,cap-delta)
            if ok2 and float(value2)>0 and float(value2)<=cap+tol:
                return True,float(value2),"floored_below_ceiling"
            delta*=2.0
        return False,None,f"cannot_floor_to_ceiling:{why}"
    except Exception as exc:
        return False,None,f"floor_exception:{type(exc).__name__}"


def _v702_post_fill_emergency_targets(*, exchange, symbol, planned_entry, fill_entry,
                                      planned_sl, planned_tp1, planned_tp2, planned_tp3,
                                      tp1_rr, tp2_rr, tp3_rr, sr_context=None):
    """Management-only recovery geometry for a position that has already filled.

    It cannot authorize/reopen an entry. If fill drift consumes the normal SR
    buffer, target 1 may be placed at (never above) the physical first resistance;
    this is recorded as an emergency management condition. TP2 is bounded by the
    next relevant physical resistance when present. If no overhead resistance
    remains, the native RR profile is used. The normal entry gates are not rerun.
    """
    try:
        pe=float(planned_entry); fe=float(fill_entry); ps=float(planned_sl)
        tps=[float(planned_tp1),float(planned_tp2),float(planned_tp3)]
        rr=[float(tp1_rr),float(tp2_rr),float(tp3_rr)]
        if not all(math.isfinite(x) and x>0 for x in [pe,fe,ps,*tps,*rr]) or not ps<pe< tps[0]<tps[1]<tps[2] or not (0<rr[0]<rr[1]<rr[2]):
            return {"ok":False,"reason":"emergency_inputs_invalid","hard_gate_bypass":False}
        risk=pe-ps
        ok_sl, sl, slwhy=_v702_price_to_precision(exchange,symbol,fe-risk)
        ok_entry, final_entry, entrywhy=_v702_price_to_precision(exchange,symbol,fe)
        if not ok_sl or not ok_entry or not (0<float(sl)<float(final_entry)):
            return {"ok":False,"reason":f"emergency_sl_or_entry_precision:{slwhy}:{entrywhy}","hard_gate_bypass":False}
        fe=float(final_entry); sl=float(sl); shift=fe-pe
        moved=[x+shift for x in tps]
        ctx=dict(sr_context or {})
        levels=[]
        if bool(ctx.get("enabled",False)):
            for value in (ctx.get("resistance_levels") or []):
                try:
                    lv=float(value)
                    if math.isfinite(lv) and lv>fe:
                        levels.append(lv)
                except Exception:
                    continue
        levels=sorted(set(levels))
        buffer=max(0.0,float(ctx.get("buffer",0.0) or 0.0))
        buffer_exception=False
        if levels:
            first=levels[0]
            cap1=first-buffer
            if cap1>fe:
                candidate=moved[0] if moved[0]>fe else cap1
                raw1=min(candidate,cap1)
                ok1,tp1,why1=_v702_floor_price_to_precision(exchange,symbol,raw1)
                if not ok1 or tp1<=fe:
                    # The configured buffer has no remaining room after fill.
                    # For an already-filled position only, use the physical
                    # resistance itself as the ceiling rather than crossing it.
                    ok1,tp1,why1=_v702_floor_price_to_precision(exchange,symbol,first)
                    buffer_exception=True
            else:
                ok1,tp1,why1=_v702_floor_price_to_precision(exchange,symbol,first)
                buffer_exception=True
            if not ok1 or tp1<=fe or tp1>first+max(first*1e-10,1e-12):
                return {"ok":False,"reason":f"emergency_tp1_cannot_respect_resistance:{why1}","hard_gate_bypass":False}
            tol=max(fe*1e-8,1e-12)
            # If TP1 remains materially before the first cap, TP2 stays beneath
            # that same resistance. Once TP1 reaches the first resistance, TP2
            # may aim at the next distinct resistance.
            first_consumed = buffer_exception or tp1 >= cap1-tol
            if first_consumed:
                next_levels=[lv for lv in levels if lv>first+tol]
                next_cap=(next_levels[0]-buffer) if next_levels else None
                next_physical=(next_levels[0] if next_levels else None)
            else:
                next_levels=[]; next_cap=cap1; next_physical=first
            candidate2=moved[1] if moved[1]>tp1 else tp1+max(risk*0.5,fe*0.0001)
            if next_cap is not None and next_cap>tp1:
                raw2=min(candidate2,next_cap)
                ok2,tp2,why2=_v702_floor_price_to_precision(exchange,symbol,raw2)
                if not ok2 or tp2<=tp1:
                    # Buffer was consumed between targets: physical resistance
                    # is still the maximum permissible management price.
                    ok2,tp2,why2=_v702_floor_price_to_precision(exchange,symbol,next_physical or next_cap)
                    buffer_exception=True
            elif next_physical is not None and next_physical>tp1:
                ok2,tp2,why2=_v702_floor_price_to_precision(exchange,symbol,next_physical)
                buffer_exception=True
            else:
                # No next overhead level is known. TP1 is the first level; the
                # next native RR target may therefore run beyond that consumed level.
                raw2=max(candidate2,tp1+max(risk*0.5,fe*0.0001))
                ok2,tp2,why2=_v702_price_to_precision(exchange,symbol,raw2)
            if not ok2 or tp2<=tp1:
                return {"ok":False,"reason":f"emergency_tp2_geometry_invalid:{why2}","hard_gate_bypass":False}
            # Respect the next physical ceiling if one exists; otherwise TP3
            # retains the strategy's native exit-profile objective.
            raw3=max(moved[2],tp2+max(risk*0.5,fe*0.0001))
            ok3,tp3,why3=_v702_price_to_precision(exchange,symbol,raw3)
            if not ok3 or tp3<=tp2:
                return {"ok":False,"reason":f"emergency_tp3_geometry_invalid:{why3}","hard_gate_bypass":False}
            if next_levels and tp2>next_levels[0]+max(next_levels[0]*1e-10,1e-12):
                return {"ok":False,"reason":"emergency_tp2_crosses_physical_resistance","hard_gate_bypass":False}
            return {"ok":True,"entry":fe,"sl":sl,"tp1":float(tp1),"tp2":float(tp2),"tp3":float(tp3),
                    "reason":"emergency_management_only","management_only":True,
                    "sr_buffer_exception":bool(buffer_exception),"resistance_levels":levels,
                    "hard_gate_bypass":False}
        # No overhead resistance remains at the actual fill; use shifted approved
        # targets when valid, otherwise the native RR profile around the real fill.
        candidate=moved if all(moved[i]>fe and (i==0 or moved[i]>moved[i-1]) for i in range(3)) else [fe+x*risk for x in rr]
        px=[]
        for name,value in zip(("tp1","tp2","tp3"),candidate):
            okv, pv, whyv=_v702_price_to_precision(exchange,symbol,value)
            if not okv: return {"ok":False,"reason":f"emergency_{name}_precision:{whyv}","hard_gate_bypass":False}
            px.append(float(pv))
        if not (fe<px[0]<px[1]<px[2]):
            px=[fe+x*risk for x in rr]
            rounded=[]
            for value in px:
                okv,pv,whyv=_v702_price_to_precision(exchange,symbol,value)
                if not okv: return {"ok":False,"reason":f"emergency_rr_precision:{whyv}","hard_gate_bypass":False}
                rounded.append(float(pv))
            px=rounded
        if not (fe<px[0]<px[1]<px[2]):
            return {"ok":False,"reason":"emergency_rr_order_invalid","hard_gate_bypass":False}
        return {"ok":True,"entry":fe,"sl":sl,"tp1":px[0],"tp2":px[1],"tp3":px[2],
                "reason":"emergency_management_only_no_overhead_resistance","management_only":True,
                "sr_buffer_exception":False,"resistance_levels":[],"hard_gate_bypass":False}
    except Exception as exc:
        return {"ok":False,"reason":f"emergency_exception:{type(exc).__name__}:{str(exc)[:100]}","hard_gate_bypass":False}


def _v702_reason_summary_token(reason: Any, width: int = 32) -> str:
    """Compact long reject reasons without collapsing distinct reasons.

    Human-readable prefixes remain where possible, while a stable digest suffix
    prevents two long reasons with the same leading characters from being counted
    as one category in the operator digest. Full reasons remain in detailed events.
    """
    try:
        raw = re.sub(r"\s+", " ", str(reason or "unknown").replace("\n", " ")).strip() or "unknown"
        width = max(16, int(width))
        _tp1_match = re.match(r"family_tp1_distance_below_floor:tp1_atr=([0-9.]+)<([0-9.]+)", raw)
        if _tp1_match:
            # Compact but actionable: unlike a hashed prefix, this exposes the
            # measured TP1/ATR distance and the exact family floor.
            return f"tp1_floor:{_tp1_match.group(1)}<{_tp1_match.group(2)}"
        if raw == "score_below_feasible_floor" or raw.startswith("score_below_feasible_floor:"):
            return "score_below_feasible_floor"[:width]
        if len(raw) <= width:
            return raw
        digest = hashlib.sha1(raw.encode("utf-8", errors="replace")).hexdigest()[:6]
        prefix_limit = width - len(digest) - 1
        prefix = raw[:prefix_limit]
        # Prefer a complete token boundary when it does not discard most of the
        # display width; digest suffix preserves uniqueness regardless.
        boundaries = [prefix.rfind(ch) for ch in (".", "_", ":", "-", " ", "=")]
        cut = max(boundaries, default=-1)
        if cut >= max(6, prefix_limit // 2):
            prefix = prefix[:cut].rstrip("._:- =")
        return f"{prefix}~{digest}"
    except Exception:
        raw = str(reason or "unknown")
        return raw[: max(8, int(width) - 7)] + "~unknown"


def _v702_pipeline_event_buffer_maxlen():
    """Bounded, configurable retained event history for 30m operator windows."""
    try:
        requested = int(os.environ.get(
            "V702_PIPELINE_EVENT_BUFFER_MAX",
            CONFIG.get("V702_PIPELINE_EVENT_BUFFER_MAX", 20000),
        ) or 20000)
    except (TypeError, ValueError):
        requested = 20000
    # Protect memory if a bad deployment value is supplied; never reduce below
    # the old capacity and default to 20k so 30m windows retain normal scans.
    return max(4096, min(100000, requested))


CONFIG.setdefault("V702_PIPELINE_EVENT_BUFFER_MAX", 20000)

def _v702_a52_reason_identity(raw_reason: Any) -> str:
    """Return a stable telemetry key while preserving exact evidence separately.

    This helper is telemetry-only: it does not alter decisions, thresholds, or
    the reason text stored in the event payload.
    """
    raw = str(raw_reason or "unknown").replace("\n", " ").strip()[:500]
    low = raw.lower()
    if low.startswith("score_below_threshold"):
        return "score_below_threshold"
    if low.startswith("score_below_feasible_floor"):
        return "score_below_feasible_floor"
    if low.startswith("liquidity.spread="):
        return "liquidity.spread"
    if low.startswith("liquidity.v45_micro~"):
        return "liquidity.v45_micro"
    if low.startswith("htf.family_htf_strength~"):
        return "htf.family_htf_strength"
    # Hashed evidence suffixes are generated identities, not separate causes.
    # Strip only a well-formed short hexadecimal suffix and leave other tildes
    # untouched so genuinely distinct reasons do not collapse together.
    import re as _re
    match = _re.match(r"^(.*)~([0-9a-f]{5,12})$", low)
    if match:
        return match.group(1)[:180]
    return raw[:180] or "unknown"


class V702PipelineMetrics:
    """Unique candidate-stage counters with explicit live-epoch/cycle scope."""
    _lock = threading.RLock()
    _enabled = False
    _epoch_id = 0
    _cycle_id = 0
    _epoch_counts = defaultdict(int)
    _cycle_keys = defaultdict(set)
    _cycle_counts = defaultdict(int)  # incrementally maintained; avoids rescanning all cycle keys per event
    _events = deque(maxlen=_v702_pipeline_event_buffer_maxlen())
    _events_dropped_total = 0         # cumulative evictions in the active live epoch
    _cycle_events_dropped_total = 0  # evictions since the current runtime cycle began
    _event_counts_by_second = {}      # bounded rolling one-hour counts of observed pipeline events
    _event_bucket_order = deque()
    _drop_counts_by_second = {}       # bounded rolling one-hour counts of ring-buffer evictions
    _drop_bucket_order = deque()
    _reasons = defaultdict(int)       # epoch sum of unique candidate-stage-reason tuples per cycle
    _cycle_reasons = defaultdict(int) # cleared whenever the runtime cycle changes
    _cycle_reason_keys = set()        # bounded by one scanner cycle; prevents repeat inflation
    _rejection_view_dirty = True      # top-rejection lists only recomputed after a rejection
    _last_block = {}                 # always belongs to _cycle_id

    # This is the observed runtime order: local composite ranking precedes the
    # canonical prequalification gate. Keep the registry in that same order so
    # operator telemetry never implies PREQUAL_PASS happened before RANKED.
    STAGES = ("DISCOVERY","RANKED","PREQUAL_SEEN","PREQUAL_PASS","PREQUAL_REJECT",
              "SELECTED","PREEXEC_PASS","PREEXEC_BLOCK","ROUTE_DEFERRED",
              "BUILDER_ENTERED","BUILDER_RETURNED_NONE","BUILDER_EXCEPTION",
              "SCORE_PASS","SCORE_BLOCK","PRESEND_PASS","QUEUED","TELEGRAM_ENQUEUED",
              "EXECUTION_ATTEMPT","ORDER_ACCEPTED","TRADE_STATE_CREATED",
              "NATIVE_SL_UNVERIFIED","PROTECTED","PROTECTION_FAILED",
              # Supplemental post-selection preflight rechecks are separate observability lanes.
              "PREQUAL_PREFLIGHT_SEEN","PREQUAL_PREFLIGHT_PASS","PREQUAL_PREFLIGHT_REJECT")

    @classmethod
    def begin_live_epoch(cls):
        with cls._lock:
            cls._epoch_id += 1
            cls._enabled = True
            cls._cycle_id = int(STATS.get("v681_runtime_cycle_id",0) or 0)
            cls._epoch_counts = defaultdict(int)
            cls._cycle_keys = defaultdict(set)
            cls._cycle_counts = defaultdict(int)
            cls._events = deque(maxlen=_v702_pipeline_event_buffer_maxlen())
            cls._events_dropped_total = 0
            cls._cycle_events_dropped_total = 0
            cls._event_counts_by_second = {}
            cls._event_bucket_order = deque()
            cls._drop_counts_by_second = {}
            cls._drop_bucket_order = deque()
            cls._reasons = defaultdict(int)
            cls._cycle_reasons = defaultdict(int)
            cls._cycle_reason_keys = set()
            cls._rejection_view_dirty = True
            cls._last_block = {}
            STATS["v702_pipeline_events_dropped_total"] = 0
            STATS["v702_pipeline_epoch_dropped"] = 0
            STATS["v702_pipeline_cycle_dropped"] = 0
            STATS["v702_pipeline_metrics_scope"] = "LIVE_EPOCH_UNIQUE_CANDIDATE_STAGES"
            STATS["v702_pipeline_metrics_epoch"] = cls._epoch_id
            STATS["v702_pipeline_metrics_hard_gate_bypass"] = False
            cls._publish_locked()

    @classmethod
    def _cycle(cls):
        try: return int(STATS.get("v681_runtime_cycle_id",0) or 0)
        except Exception: return 0

    @classmethod
    def _bump_second_bucket_locked(cls, values, order, ts, amount=1):
        """Keep event-time counters sorted when delayed evictions arrive out of order.

        An evicted record's original timestamp is expected to be older than the
        latest insertion. Treating that as a wall-clock rollback erased the drop
        history and made WINDOW_DROPPED disagree with the retained ring. The
        extracted bucket owner handles bounded, sorted event-time insertion.
        """
        bump_event_time_bucket(values, order, ts, amount=amount, max_age_sec=3600)

    @classmethod
    def _note_event_locked(cls, ts):
        cls._bump_second_bucket_locked(cls._event_counts_by_second, cls._event_bucket_order, ts, 1)

    @classmethod
    def _note_drop_locked(cls, evicted_event_ts):
        """Count a lost record against the timestamp of that record, not eviction time.

        The rolling-window ratio must answer "how many events generated in this
        window have since been evicted?" An event inserted now can evict a record
        from well before the current window; using insertion time falsely reports
        a 100% drop rate whenever the ring is saturated, even if the current
        window is still fully retained.
        """
        cls._events_dropped_total += 1
        cls._cycle_events_dropped_total += 1
        try:
            drop_ts = float(evicted_event_ts)
        except (TypeError, ValueError):
            drop_ts = float(WALL_NOW())
        cls._bump_second_bucket_locked(cls._drop_counts_by_second, cls._drop_bucket_order, drop_ts, 1)
        STATS["v702_pipeline_events_dropped_total"] = int(cls._events_dropped_total)
        STATS["v702_pipeline_epoch_dropped"] = int(cls._events_dropped_total)
        STATS["v702_pipeline_cycle_dropped"] = int(cls._cycle_events_dropped_total)

    @classmethod
    def _append_event_locked(cls, event, fallback_ts):
        """Append without losing the identity/time of the evicted ring record."""
        maxlen = getattr(cls._events, "maxlen", None)
        if maxlen and len(cls._events) >= int(maxlen):
            evicted = cls._events.popleft()
            try:
                evicted_ts = float(evicted.get("ts", fallback_ts)) if isinstance(evicted, dict) else float(fallback_ts)
            except (TypeError, ValueError):
                evicted_ts = float(fallback_ts)
            cls._note_drop_locked(evicted_ts)
        cls._events.append(event)

    @classmethod
    def drop_health_snapshot(cls, interval_sec=3600.0, now=None):
        """Return rolling telemetry retention metrics without changing trade policy."""
        interval = min(3600.0, max(60.0, float(interval_sec or 3600.0)))
        now_ts = float(WALL_NOW() if now is None else now)
        cutoff = now_ts - interval
        # Event counters are bucketed by integer epoch seconds. Use identical
        # bucket boundaries for counters and retained timestamps; comparing an
        # integer bucket key with a fractional cutoff caused false 1–few event
        # retention mismatches at window edges.
        window_start_bucket = int(math.floor(cutoff))
        window_end_bucket = int(math.floor(now_ts + 2.0))
        with cls._lock:
            event_total = sum(int(v or 0) for k, v in cls._event_counts_by_second.items()
                              if window_start_bucket <= int(float(k)) <= window_end_bucket)
            dropped = sum(int(v or 0) for k, v in cls._drop_counts_by_second.items()
                          if window_start_bucket <= int(float(k)) <= window_end_bucket)
            epoch_dropped = int(cls._events_dropped_total)
            cycle_dropped = int(cls._cycle_events_dropped_total)
            retained_events = list(cls._events)
        retained_in_window = 0
        retained_timestamps = []
        for _ev in retained_events:
            if not isinstance(_ev, dict):
                continue
            try:
                _ts = float(_ev.get("ts", 0.0) or 0.0)
            except (TypeError, ValueError):
                continue
            retained_timestamps.append(_ts)
            if window_start_bucket <= int(math.floor(_ts)) <= window_end_bucket:
                retained_in_window += 1
        oldest_age = (max(0.0, now_ts - min(retained_timestamps)) if retained_timestamps else None)
        retained_complete = bool(event_total == retained_in_window and dropped == 0)
        covered = bool(retained_timestamps and min(retained_timestamps) <= cutoff and retained_complete)
        evict_rate = round(100.0 * dropped / max(1, event_total), 3)
        return {
            "interval_sec": int(interval),
            "events_last_window": int(event_total),
            "retained_events_last_window": int(retained_in_window),
            "dropped_last_window": int(dropped),
            "drop_pct_last_window": evict_rate,  # compatibility alias: event-time eviction rate
            "evict_rate_pct": evict_rate,
            "retained_oldest_age_sec": None if oldest_age is None else round(oldest_age, 3),
            "window_covered": covered,
            "event_retention_complete": retained_complete,
            "epoch_dropped": epoch_dropped,
            "cycle_dropped": cycle_dropped,
        }

    @classmethod
    def candidate_key(cls, candidate=None, snapshot=None, symbol=""):
        try:
            c=candidate
            snap=snapshot if isinstance(snapshot,dict) else {}
            sym=str(symbol or getattr(c,"symbol","") or snap.get("symbol","") or "?").upper()
            fam=str(getattr(c,"family","") or getattr(c,"strategy_mode","")
                    or snap.get("family","") or snap.get("strategy_mode","") or "UNKNOWN").upper()
            eng=str(getattr(c,"engine_id","") or snap.get("engine_id","") or "UNKNOWN").upper()
            ts=str(getattr(c,"generated_at_ms","") or snap.get("candidate_id","")
                   or snap.get("generated_at_ms","") or snap.get("candle_ts","")
                   or snap.get("snapshot_id","") or "")
            # Prefer stable request/snapshot identity when no StrategyCandidate
            # object was passed. id() is only the final within-process fallback.
            stamp=ts or str(id(c) if c is not None else (id(snapshot) if snapshot is not None else "unknown"))
            return f"{cls._cycle()}|{sym}|{fam}|{eng}|{stamp}"
        except Exception:
            return f"{cls._cycle()}|{str(symbol or '?').upper()}|UNKNOWN|UNKNOWN|{id(candidate)}"

    @classmethod
    def current_candidate_key(cls):
        try:
            ctx=_V702_PIPELINE_CONTEXT.get()
            return str((ctx or {}).get("candidate_key") or "")
        except Exception: return ""

    @classmethod
    def record_current(cls, stage, symbol="", candidate_key="", family="", details=None):
        if not cls._enabled: return False
        key=str(candidate_key or cls.current_candidate_key() or "")
        ctx=_V702_PIPELINE_CONTEXT.get() if _V702_PIPELINE_CONTEXT is not None else None
        if not key and isinstance(ctx,dict): key=str(ctx.get("candidate_key") or "")
        if not key:
            # Candidate-stage counters must only contain events tied to a real
            # candidate. Operator notices, digests and other free-standing
            # Telegram messages are tracked separately instead of receiving a
            # synthetic trace key that inflates TG_ENQ beyond QUEUE.
            try:
                stage_key = str(stage or "UNKNOWN").strip().lower()
                STATS["v702_pipeline_unattributed_events"] = int(STATS.get("v702_pipeline_unattributed_events", 0) or 0) + 1
                stat_key = f"v702_pipeline_unattributed.{stage_key}"
                STATS[stat_key] = int(STATS.get(stat_key, 0) or 0) + 1
            except Exception:
                pass
            return False
        cls.record(stage, key, symbol=symbol or (ctx or {}).get("symbol",""),
                   family=family or (ctx or {}).get("family",""), details=details)
        return True

    @classmethod
    def record(cls, stage, candidate_key, symbol="", family="", details=None):
        if not cls._enabled: return
        st=str(stage or "UNKNOWN").upper(); ck=str(candidate_key or "")
        if not ck: return
        cycle=cls._cycle()
        with cls._lock:
            if cycle != cls._cycle_id:
                cls._cycle_id=cycle
                cls._cycle_keys=defaultdict(set)
                cls._cycle_counts=defaultdict(int)
                cls._cycle_events_dropped_total=0
                cls._cycle_reasons=defaultdict(int)
                cls._cycle_reason_keys=set()
                cls._rejection_view_dirty=True
                cls._last_block={}
                STATS["v702_pipeline_cycle_id"] = cycle
                STATS["v702_pipeline_cycle_dropped"] = 0
            dedupe_key=(cycle,st,ck)
            if dedupe_key not in cls._cycle_keys[st]:
                cls._cycle_keys[st].add(dedupe_key)
                cls._epoch_counts[st]+=1
                cls._cycle_counts[st]+=1
            event_ts=float(WALL_NOW())
            cls._note_event_locked(event_ts)
            ev={"cycle_id":cycle,"stage":st,"candidate_key":ck,
                "symbol":str(symbol or ""),"family":str(family or ""),
                "ts":event_ts,"details":dict(details or {})}
            cls._append_event_locked(ev, event_ts)
            STATS[f"v702_pipeline_epoch.{st.lower()}"]=int(cls._epoch_counts[st])
            cls._publish_locked()

    @classmethod
    def reject(cls, trace_id, symbol, taxonomy, code, stage, context=None, *, candidate_key="", source="unknown"):
        if not cls._enabled: return False
        ctx=_V702_PIPELINE_CONTEXT.get() or {}
        key=str(candidate_key or ctx.get("candidate_key") or f"{cls._cycle()}|{symbol}|trace|{trace_id or 'unknown'}")
        reason=str(code or taxonomy or "unknown").replace("\n"," ")[:500]
        reason_code=_v702_a52_reason_identity(reason)
        st=str(stage or "unknown")[:100]
        source_text = str(source or (context or {}).get("source") or "unknown")[:80]
        with cls._lock:
            cycle=cls._cycle()
            if cycle != cls._cycle_id:
                cls._cycle_id=cycle
                cls._cycle_keys=defaultdict(set)
                cls._cycle_counts=defaultdict(int)
                cls._cycle_events_dropped_total=0
                cls._cycle_reasons=defaultdict(int)
                cls._cycle_reason_keys=set()
                cls._rejection_view_dirty=True
                cls._last_block={}
                STATS["v702_pipeline_cycle_id"] = cycle
                STATS["v702_pipeline_cycle_dropped"] = 0
            reason_key=f"{st}:{reason_code}"
            reason_dedupe_key=(cycle, key, reason_key)
            if reason_dedupe_key not in cls._cycle_reason_keys:
                cls._cycle_reason_keys.add(reason_dedupe_key)
                cls._reasons[reason_key]+=1
                cls._cycle_reasons[reason_key]+=1
                cls._rejection_view_dirty=True
            event_ts=float(WALL_NOW())
            cls._last_block={"cycle_id":cycle,"symbol":str(symbol or ""),
                             "stage":st,"reason":reason,"reason_code":reason_code,"ts":event_ts,
                             "trace_id":str(trace_id or ""),"details":dict(context or {})}
            cls._note_event_locked(event_ts)
            _details = dict(context or {})
            _details.update({"stage":st,"reason":reason[:180],"reason_detail":reason,
                             "reason_code":reason_code,"source":source_text,
                             "taxonomy":str(taxonomy or "")[:80],"trace_id":str(trace_id or "")[:100]})
            cls._append_event_locked({"cycle_id":cycle,"stage":"REJECT","candidate_key":key,
                                      "symbol":str(symbol or ""),"family":str(ctx.get("family") or _details.get("family") or ""),
                                      "ts":event_ts,"details":_details}, event_ts)
            STATS["v702_pipeline_epoch.reject_events"] = sum(cls._reasons.values())
            STATS["v702_pipeline_cycle.reject_events"] = sum(cls._cycle_reasons.values())
            cls._publish_locked()
        return True

    @classmethod
    def _publish_locked(cls):
        try:
            STATS["v702_pipeline_cycle_counts"]={str(k):int(v) for k,v in cls._cycle_counts.items()}
            STATS["v702_pipeline_epoch_counts"]={str(k):int(v) for k,v in cls._epoch_counts.items()}
            STATS["v702_pipeline_epoch_dropped"] = int(cls._events_dropped_total)
            STATS["v702_pipeline_cycle_dropped"] = int(cls._cycle_events_dropped_total)
            STATS["v702_pipeline_events_dropped_total"] = int(cls._events_dropped_total)  # compatibility alias: live-epoch scope
            if cls._rejection_view_dirty or "v702_pipeline_top_rejections_epoch" not in STATS:
                STATS["v702_pipeline_top_rejections_epoch"]=sorted(
                    ((k,int(v)) for k,v in cls._reasons.items()),key=lambda x:(-x[1],x[0])
                )[:5]
                STATS["v702_pipeline_top_rejections_cycle"]=sorted(
                    ((k,int(v)) for k,v in cls._cycle_reasons.items()),key=lambda x:(-x[1],x[0])
                )[:5]
                # Compatibility alias is explicitly epoch-scoped.
                STATS["v702_pipeline_top_rejections"]=list(STATS["v702_pipeline_top_rejections_epoch"])
                cls._rejection_view_dirty=False
            STATS["v702_pipeline_last_block"]=dict(cls._last_block)
        except Exception: pass

    @classmethod
    def snapshot(cls):
        with cls._lock:
            return {"enabled":bool(cls._enabled),"scope":"LIVE_EPOCH_UNIQUE_CANDIDATE_STAGES",
                    "epoch":cls._epoch_id,"cycle_id":cls._cycle_id,
                    "counts":{str(k):int(v) for k,v in cls._epoch_counts.items()},
                    "cycle_counts":{str(k):int(v) for k,v in cls._cycle_counts.items()},
                    "epoch_dropped":int(cls._events_dropped_total),
                    "cycle_dropped":int(cls._cycle_events_dropped_total),
                    "top_rejections":sorted(((k,int(v)) for k,v in cls._cycle_reasons.items()),
                                             key=lambda x:(-x[1],x[0]))[:5],
                    "top_rejections_cycle":sorted(((k,int(v)) for k,v in cls._cycle_reasons.items()),
                                                   key=lambda x:(-x[1],x[0]))[:5],
                    "top_rejections_epoch":sorted(((k,int(v)) for k,v in cls._reasons.items()),
                                                   key=lambda x:(-x[1],x[0]))[:5],
                    "cycle_reject_count":sum(cls._cycle_reasons.values()),
                    "epoch_reject_count":sum(cls._reasons.values()),
                    "last_block":dict(cls._last_block),"hard_gate_bypass":False}

    @classmethod
    def digest_line(cls):
        snap=cls.snapshot()
        if not snap["enabled"]: return "pipeline_scope=LIVE_EPOCH_NOT_ARMED"
        c=snap["cycle_counts"]
        # Keep displayed columns in actual execution order and expose both
        # PREQUAL pass and reject outcomes. RANKED is intentionally before
        # PREQUAL because CompositeRankingEngine.rank() runs before the gate.
        order=("DISCOVERY","RANKED","PREQUAL_SEEN","PREQUAL_PASS","PREQUAL_REJECT",
               "SELECTED","PREEXEC_PASS","PREEXEC_BLOCK","ROUTE_DEFERRED",
               "BUILDER_ENTERED","BUILDER_RETURNED_NONE","BUILDER_EXCEPTION",
               "SCORE_PASS","SCORE_BLOCK","PRESEND_PASS","QUEUED","TELEGRAM_ENQUEUED",
               "EXECUTION_ATTEMPT","ORDER_ACCEPTED","TRADE_STATE_CREATED",
               "NATIVE_SL_UNVERIFIED","PROTECTED","PROTECTION_FAILED")
        vals="/".join(str(int(c.get(k,0) or 0)) for k in order)
        preflight = "/".join(str(int(c.get(k,0) or 0)) for k in
                              ("PREQUAL_PREFLIGHT_SEEN","PREQUAL_PREFLIGHT_PASS","PREQUAL_PREFLIGHT_REJECT"))
        last=snap.get("last_block") or {}
        if last and int(last.get("cycle_id",-1) or -1) == int(snap.get("cycle_id",-2) or -2):
            reason=f" last_block_cycle={last.get('symbol','?')}:{last.get('stage','?')}:{last.get('reason','?')}"
        else:
            reason=" last_block_cycle=-"
        tops_cycle=",".join(f"{k}x{v}" for k,v in snap.get("top_rejections_cycle",[])[:3]) or "-"
        tops_epoch=",".join(f"{k}x{v}" for k,v in snap.get("top_rejections_epoch",[])[:2]) or "-"
        return (f"PIPELINE[CYCLE] DISC/RANK/PRE/PASS/PRE_REJ/SEL/PREEXEC_PASS/PREEXEC_BLOCK/DEFER/BUILDER/BUILDER_NONE/BUILDER_ERR/SCORE_PASS/SCORE_BLOCK/PRESEND/QUEUE/TG_ENQ/EXEC/ORDER/STATE/NATIVE_SL_UNVERIFIED/PROTECTED/PROT_FAIL={vals} "
                f"reject_cycle_unique_candidate_stage_reason={snap.get('cycle_reject_count',0)} top_cycle={tops_cycle} "
                f"reject_epoch={snap.get('epoch_reject_count',0)}[cycle+candidate+stage+reason dedupe] top_epoch={tops_epoch}{reason} "
                f"preflight_seen/pass/rej={preflight} bypass=0 "
                f"entry_policy={STATS.get('v702_runtime_entry_policy', 'MONITOR_ONLY_NO_NEW_BUYS')}")[:1400]

    @classmethod
    def window_line(cls, interval_sec=None, now=None):
        """Summarize unique candidate-stage outcomes in the digest window.

        The CYCLE line is deliberately cycle-scoped. This second line is scoped
        to the current Telegram digest interval, avoiding invalid comparisons
        between a ~300s rejection batch and one current scanner cycle.
        """
        try:
            interval = float(interval_sec if interval_sec is not None else CONFIG.get("V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC", 1800.0))
            interval = min(3600.0, max(60.0, interval))
            now_ts = float(WALL_NOW() if now is None else now)
            cutoff = now_ts - interval
            # Align the display window with the integer-second event/drop buckets.
            # This removes false retention mismatches caused solely by fractional
            # cutoff seconds while preserving the explicitly bounded time window.
            window_start_bucket = int(math.floor(cutoff))
            window_end_bucket = int(math.floor(now_ts + 2.0))
            with cls._lock:
                # The ring, event buckets, drop buckets and cumulative counters form
                # one snapshot. Reading them under separate lock scopes can make a
                # digest report a false retention mismatch during concurrent writes.
                events = list(cls._events)
                dropped_window_bucket = sum(
                    int(v or 0) for k, v in cls._drop_counts_by_second.items()
                    if window_start_bucket <= int(float(k)) <= window_end_bucket)
                observed_window = sum(
                    int(v or 0) for k, v in cls._event_counts_by_second.items()
                    if window_start_bucket <= int(float(k)) <= window_end_bucket)
                epoch_dropped = int(cls._events_dropped_total)
                cycle_dropped = int(cls._cycle_events_dropped_total)
            recent = []
            all_ts = []
            for ev in events:
                if not isinstance(ev, dict):
                    continue
                try:
                    ts = float(ev.get("ts", 0.0) or 0.0)
                except Exception:
                    continue
                all_ts.append(ts)
                if window_start_bucket <= int(math.floor(ts)) <= window_end_bucket:
                    recent.append(ev)
            stage_keys = defaultdict(set)
            rejection_keys = set()
            reason_counts = defaultdict(int)          # canonical record_reject facade events; prequal is included
            prequal_reason_keys = set()               # unique candidate + canonical PREQUAL reason
            prequal_reason_counts = defaultdict(int)
            policy_context_keys = set()               # unique candidate + observed macro allow-list context
            policy_context_counts = defaultdict(int)
            preexec_reason_keys = set()               # unique candidate + selected-route blocker
            preexec_reason_counts = defaultdict(int)
            preflight_reason_keys = set()
            preflight_reason_counts = defaultdict(int)
            for ev in recent:
                stage = str(ev.get("stage", "UNKNOWN") or "UNKNOWN").upper()
                candidate_key = str(ev.get("candidate_key", "") or "")
                details = ev.get("details", {}) if isinstance(ev.get("details"), dict) else {}
                if stage == "REJECT":
                    reject_stage = str(details.get("stage", "unknown") or "unknown")[:48]
                    reason = str(details.get("reason", "unknown") or "unknown").replace("\n", " ")[:64]
                    reject_key = (candidate_key, reject_stage, reason)
                    if reject_key not in rejection_keys:
                        rejection_keys.add(reject_key)
                        reason_counts[reason] += 1
                elif candidate_key:
                    stage_keys[stage].add(candidate_key)
                    # PREQUAL_REJECT is itself a canonical candidate-stage
                    # outcome. It may exist without a record_rejection() event,
                    # so it must have its own reason summary rather than making
                    # the operator digest say rejects=0/top=- beside PRE_REJ>0.
                    if stage in {"PREQUAL_REJECT", "PREQUAL_PREFLIGHT_REJECT"}:
                        reason = str(details.get("reason", "unknown") or "unknown").replace("\n", " ")[:96]
                        # The unified record_rejects/record_top view is a union
                        # across legacy REJECT and explicit prequal outcomes. Use
                        # exactly candidate+stage+reason, so a paired event is not
                        # double counted, but prequal-only outcomes cannot disappear.
                        normalized_stage = "preflight" if stage == "PREQUAL_PREFLIGHT_REJECT" else "prequal"
                        reject_key = (candidate_key, normalized_stage, reason)
                        if reject_key not in rejection_keys:
                            rejection_keys.add(reject_key)
                            reason_counts[reason] += 1
                        if stage == "PREQUAL_PREFLIGHT_REJECT":
                            reason_key = (candidate_key, reason)
                            if reason_key not in preflight_reason_keys:
                                preflight_reason_keys.add(reason_key)
                                preflight_reason_counts[reason] += 1
                            continue
                        reason_key = (candidate_key, reason)
                        if reason_key not in prequal_reason_keys:
                            prequal_reason_keys.add(reason_key)
                            prequal_reason_counts[reason] += 1
                        if reason.startswith("family_regime_disallowed.macro"):
                            mode = str(details.get("policy_mode") or details.get("policy_family") or "UNKNOWN").upper()[:36]
                            macro = str(details.get("policy_macro_regime") or "UNKNOWN").upper()[:20]
                            allowed0 = details.get("policy_allowed_macro_regimes", [])
                            if isinstance(allowed0, (tuple, list, set)):
                                allowed = "+".join(sorted(str(v).upper()[:16] for v in allowed0 if str(v).strip())[:4]) or "UNKNOWN"
                            else:
                                allowed = "UNKNOWN"
                            context_token = f"{mode}@{macro}[allow={allowed}]"
                            context_key = (candidate_key, context_token)
                            if context_key not in policy_context_keys:
                                policy_context_keys.add(context_key)
                                policy_context_counts[context_token] += 1
                    elif stage == "PREEXEC_BLOCK":
                        # Selected candidates can be stopped before Builder by
                        # freshness, policy parity, canonical structure or exact
                        # orderbook checks. Surface those terminal reasons in the
                        # same window, rather than showing PX_BLK with no cause.
                        reason = str(details.get("reason", "unknown") or "unknown").replace("\n", " ")[:120]
                        for prefix in ("selected_preexec_policy:", "selected_preexec_canonical:",
                                       "selected_preexec_freshness:", "selected_route_orderbook:",
                                       "selected_route_projection:", "selected_route_orderbook_error:"):
                            if reason.startswith(prefix):
                                reason = reason[len(prefix):]
                                break
                        reason = reason[:64] or "unknown"
                        reason_key = (candidate_key, reason)
                        if reason_key not in preexec_reason_keys:
                            preexec_reason_keys.add(reason_key)
                            preexec_reason_counts[reason] += 1
            order = (
                ("DISC", "DISCOVERY"), ("RANK", "RANKED"), ("PRE", "PREQUAL_SEEN"),
                ("PASS", "PREQUAL_PASS"), ("PRE_REJ", "PREQUAL_REJECT"), ("SEL", "SELECTED"),
                ("PX_OK", "PREEXEC_PASS"), ("PX_BLK", "PREEXEC_BLOCK"), ("DEFER", "ROUTE_DEFERRED"),
                ("BUILD", "BUILDER_ENTERED"), ("B_NONE", "BUILDER_RETURNED_NONE"),
                ("B_ERR", "BUILDER_EXCEPTION"), ("SCORE_PASS", "SCORE_PASS"), ("SCORE_BLOCK", "SCORE_BLOCK"), ("PS", "PRESEND_PASS"),
                ("Q", "QUEUED"), ("TG", "TELEGRAM_ENQUEUED"), ("EXEC", "EXECUTION_ATTEMPT"),
                ("ORDER", "ORDER_ACCEPTED"), ("STATE", "TRADE_STATE_CREATED"),
                ("NATIVE_SL", "NATIVE_SL_UNVERIFIED"), ("PROT", "PROTECTED"),
                ("PROT_FAIL", "PROTECTION_FAILED"),
                ("PRE_FLIGHT", "PREQUAL_PREFLIGHT_SEEN"),
                ("PFX_OK", "PREQUAL_PREFLIGHT_PASS"),
                ("PFX_REJ", "PREQUAL_PREFLIGHT_REJECT"),
            )
            counts = ",".join(f"{label}={len(stage_keys.get(stage, set()))}" for label, stage in order)
            top = ",".join(f"{_v702_reason_summary_token(reason, 32)}x{count}" for reason, count in sorted(reason_counts.items(), key=lambda item: (-item[1], item[0]))[:2]) or "-"
            prequal_top = ",".join(
                f"{_v702_reason_summary_token(reason, 32)}x{count}"
                for reason, count in sorted(prequal_reason_counts.items(), key=lambda item: (-item[1], item[0]))[:2]
            ) or "-"
            preexec_top = ",".join(
                f"{_v702_reason_summary_token(reason, 40)}x{count}"
                for reason, count in sorted(preexec_reason_counts.items(), key=lambda item: (-item[1], item[0]))[:2]
            ) or "-"
            preflight_top = ",".join(
                f"{_v702_reason_summary_token(reason, 40)}x{count}"
                for reason, count in sorted(preflight_reason_counts.items(), key=lambda item: (-item[1], item[0]))[:2]
            ) or "-"
            policy_context_top = ",".join(
                f"{_v702_reason_summary_token(context, 64)}x{count}"
                for context, count in sorted(policy_context_counts.items(), key=lambda item: (-item[1], item[0]))[:2]
            ) or "-"
            maxlen = getattr(cls._events, "maxlen", None)
            retained_window = len(recent)
            retained_oldest_age = (max(0.0, now_ts - min(all_ts)) if all_ts else None)
            # `window_dropped` is the event-time drop bucket, not an inferred
            # residual. The residual is surfaced separately as a counter mismatch;
            # this preserves scope semantics and avoids falsely claiming a known
            # number of evictions when retained-ring and event-count evidence disagree.
            dropped_window = int(dropped_window_bucket)
            expected_retained = max(0, int(observed_window) - dropped_window)
            retention_counter_mismatch = int(retained_window) != expected_retained
            event_retention_complete = bool(
                dropped_window == 0 and retained_window == observed_window and not retention_counter_mismatch
            )
            # Coverage requires temporal span and reconciled counters. Unknown or
            # inconsistent counters fail closed, but never relabel epoch drops as
            # rolling-window drops.
            window_covered = bool(all_ts and min(all_ts) <= cutoff and event_retention_complete)
            buffer_truncated = bool(dropped_window > 0 or retention_counter_mismatch)
            label_minutes = max(1, int(round(interval / 60.0)))
            evict_rate_pct = 100.0 * float(dropped_window) / max(1.0, float(observed_window))
            age_text = "unknown" if retained_oldest_age is None else f"{retained_oldest_age:.0f}"
            mismatch_text = "yes" if retention_counter_mismatch else "no"
            # Keep window, event-time drop and cumulative epoch scopes explicit.
            _policy_context_field = f" policy_ctx_top={policy_context_top}" if policy_context_counts else ""
            return (f"PIPELINE[WINDOW_{label_minutes}M] interval_sec={int(interval)} events={len(recent)} {counts} "
                    f"stage_totals=unique_candidate_sets prequal_source=arbiter preflight_separate=yes "
                    f"record_rejects={len(rejection_keys)}[unified_candidate_stage_reason] record_top={top} "
                    f"prequal_top={prequal_top} preflight_top={preflight_top}{_policy_context_field} preexec_top={preexec_top} "
                    f"buffer_truncated={'yes' if buffer_truncated else 'no'} window_covered={'yes' if window_covered else 'no'} "
                    f"event_retention_complete={'yes' if event_retention_complete else 'no'} retention_counter_mismatch={mismatch_text} "
                    f"retained_oldest_age_sec={age_text} window_dropped={int(dropped_window)} "
                    f"window_drop_bucket={int(dropped_window_bucket)} window_events={int(observed_window)} "
                    f"evict_rate_pct={evict_rate_pct:.1f} drop_pct={evict_rate_pct:.1f} "
                    f"cycle_dropped={cycle_dropped} epoch_dropped_cumulative={epoch_dropped}")[:1850]
        except Exception as exc:
            return f"PIPELINE[WINDOW] unavailable={type(exc).__name__}"


def _v702_candidate_wrap(value, snapshot=None, symbol=""):
    candidate=value
    if candidate is not None and hasattr(candidate,"candidate"):
        candidate=getattr(candidate,"candidate",candidate)
    return V702PipelineMetrics.candidate_key(candidate,snapshot,symbol)


def _v702_a60_resolve_paper_shadow(shadow_store, candidate_key, builder_none_diag=None):
    """Resolve same-attempt Shadow evidence without conflating market/account gates.

    A scorer/pre-shadow rejection has no attempt-scoped Shadow record and remains
    NOT_REACHED. If the exact Builder attempt did evaluate Shadow and then the
    account/live path returned no TradeState (e.g. MONITOR_ONLY), the Shadow
    outcome remains a real market result and is not relabeled NOT_REACHED.
    """
    shadow_store = shadow_store if isinstance(shadow_store, dict) else {}
    key = str(candidate_key or "")
    diag = builder_none_diag if isinstance(builder_none_diag, dict) else {}
    diag_key = str(diag.get("candidate_key") or "")
    attempt_id = str(diag.get("evaluation_attempt_id") or "")
    shadow = shadow_store.get(attempt_id) if attempt_id else None
    if isinstance(shadow, dict):
        if (str(shadow.get("candidate_key") or "") == key
                and str(shadow.get("evaluation_attempt_id") or "") == attempt_id
                and bool(shadow.get("reached"))):
            result = dict(shadow)
            result["builder_returned_no_trade_state"] = bool(diag_key == key)
            if diag_key == key:
                return result, "shadow_evaluated_after_builder_none", str(result.get("reason") or "shadow_evaluated")[:180]
            return result, "shadow_evaluated", str(result.get("reason") or "")[:180]

    if key and diag_key == key:
        rejection = diag.get("candidate_rejection") if isinstance(diag.get("candidate_rejection"), dict) else {}
        stage = str(rejection.get("stage") or "")[:80]
        reason = str(rejection.get("code") or rejection.get("reason") or diag.get("reason") or "unattributed")[:140]
        display_reason = "not_reached:builder_returned_none"
        if stage or reason:
            display_reason += f":{stage or 'builder'}:{reason}"
        return ({
            "eligible": False,
            "reason": display_reason[:220],
            "not_reached": True,
            "reached": False,
            "builder_block_stage": stage,
            "builder_block_reason": reason,
            "evaluation_attempt_id": attempt_id,
        }, "builder_returned_none", display_reason[:220])

    return ({"eligible": False, "reason": "shadow_result_missing", "not_reached": False, "reached": False},
            "shadow_result_missing", "shadow_result_missing")


def _v702_prequal_policy_evidence(ranked, snap_by_symbol):
    """Return bounded, read-only evidence explaining a family/macro policy reject.

    This helper never decides whether a candidate may trade. It only makes the
    existing canonical policy inputs and allow-list visible in telemetry so a
    macro-policy bottleneck can be distinguished from a registry/context drift.
    """
    try:
        candidate = getattr(ranked, "candidate", ranked)
        fs0 = getattr(candidate, "features_snapshot", {}) or {}
        fs = dict(fs0) if isinstance(fs0, dict) else {}
        symbol = str(getattr(candidate, "symbol", "") or fs.get("symbol", "") or "")
        snapshot = {}
        if isinstance(snap_by_symbol, dict):
            candidate_snapshot = snap_by_symbol.get(symbol)
            if not isinstance(candidate_snapshot, dict):
                symbol_upper = symbol.upper()
                candidate_snapshot = next((v for k, v in snap_by_symbol.items()
                                           if str(k).upper() == symbol_upper and isinstance(v, dict)), {})
            snapshot = dict(candidate_snapshot or {}) if isinstance(candidate_snapshot, dict) else {}

        def first_text(*values):
            for value in values:
                if isinstance(value, dict):
                    value = value.get("phase", "")
                text_value = str(value or "").strip()
                if text_value:
                    return text_value[:80]
            return "UNKNOWN"

        family = first_text(getattr(candidate, "family", ""), fs.get("family"),
                            getattr(candidate, "strategy_mode", ""))
        mode = first_text(getattr(candidate, "strategy_mode", ""), fs.get("strategy_mode"), family)
        regime = first_text(snapshot.get("macro_regime"), snapshot.get("regime"),
                            fs.get("macro_regime"), fs.get("regime"))
        local = first_text(snapshot.get("local_regime"), fs.get("local_regime"), fs.get("v45_last_local_regime"))
        severity = first_text(snapshot.get("macro_severity"), snapshot.get("severity"),
                              fs.get("macro_severity"), fs.get("severity"))
        phase = first_text(snapshot.get("market_phase"), snapshot.get("phase"),
                           fs.get("market_phase"), fs.get("phase"))
        meta = {}
        source = "UNKNOWN"
        try:
            registry = CanonicalStrategyPolicyRegistry.data()
            if isinstance(registry, dict):
                meta0 = registry.get(mode) or registry.get(family)
                if isinstance(meta0, dict):
                    meta = dict(meta0)
                    source = "V43_STRATEGY_META"
        except Exception:
            meta = {}
        allowed = meta.get("allowed_regimes", ()) if isinstance(meta, dict) else ()
        if not allowed:
            family_config = CONFIG.get("FAMILY_POLICY_" + family.upper(), {})
            if isinstance(family_config, dict):
                allowed = family_config.get("allowed_regimes", ())
                if allowed:
                    source = "legacy_family_policy"
        allowed = sorted({str(v).strip().upper()[:32] for v in (allowed or ()) if str(v).strip()})[:8]
        return {
            "policy_family": family.upper()[:64],
            "policy_mode": mode.upper()[:64],
            "policy_macro_regime": regime.upper()[:32],
            "policy_allowed_macro_regimes": allowed,
            "policy_local_regime": local.upper()[:32],
            "policy_severity": severity.upper()[:32],
            "policy_phase": phase.upper()[:32],
            "policy_source": source,
        }
    except Exception:
        return {"policy_evidence": "unavailable"}


def _v702_pipeline_route_outcome(symbol, stage, reason="", source="V702_ROUTE", details=None,
                                candidate=None, candidate_key=""):
    """Attach a route outcome to the exact candidate; same-symbol fallback is intentionally forbidden."""
    try:
        sym = str(symbol or "").upper()
        try:
            live_cycle = int(STATS.get("v681_runtime_cycle_id", 0) or 0)
        except Exception:
            live_cycle = 0
        if candidate is not None:
            key = str(candidate_key or _v702_candidate_wrap(candidate) or "")
            family = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "")
        elif candidate_key:
            key = str(candidate_key)
            family = ""
        else:
            # Fallback is permitted only from the explicit selected-candidate
            # registry for this exact symbol AND current cycle, with a durable
            # candidate_key. Route callers with an alternate candidate must pass
            # that candidate object/key; symbol-only guesses remain forbidden.
            key = ""
            family = ""
            selected_map = STATS.get("v702_selected_candidate_key_by_symbol", {})
            if isinstance(selected_map, dict):
                selected_row = selected_map.get(str(symbol or "")) or selected_map.get(sym)
                if isinstance(selected_row, dict):
                    try:
                        row_cycle = int(selected_row.get("cycle_id", -1))
                    except Exception:
                        row_cycle = -1
                    row_key = str(selected_row.get("candidate_key") or "")
                    if row_key and row_cycle == live_cycle and live_cycle > 0:
                        key = row_key
                        family = str(selected_row.get("family") or "")
                        details = {**dict(details or {}), "attribution_source": "explicit_current_cycle_selected_registry",
                                   "selected_registry_cycle_id": row_cycle}
        if not key:
            STATS["v702_route_telemetry_unattributed"] = int(STATS.get("v702_route_telemetry_unattributed", 0) or 0) + 1
            STATS["v702_route_telemetry_last_unattributed"] = {
                "symbol": str(symbol or ""), "stage": str(stage or ""),
                "reason": str(reason or "")[:180], "cycle_id": live_cycle, "ts": WALL_NOW()
            }
            return False
        d = dict(details or {})
        d.update({"reason": str(reason or "")[:240], "source": str(source or "V702_ROUTE")[:80]})
        V702PipelineMetrics.record(stage, key, symbol=str(symbol or ""), family=family, details=d)
        STATS["v702_pipeline_route_outcome_last"] = {
            "symbol": str(symbol or ""), "stage": str(stage or ""), "reason": str(reason or "")[:240],
            "source": str(source or "V702_ROUTE")[:80], "cycle_id": int(STATS.get("v681_runtime_cycle_id", 0) or 0),
            "candidate_key": key, "ts": WALL_NOW()
        }
        hist = STATS.setdefault("v702_pipeline_route_outcome_history", [])
        if isinstance(hist, list):
            hist.append(dict(STATS["v702_pipeline_route_outcome_last"]))
            if len(hist) > 64:
                del hist[:-64]
        return True
    except Exception:
        try: STATS["v702_route_telemetry_errors"] = int(STATS.get("v702_route_telemetry_errors", 0) or 0) + 1
        except Exception: pass
        return False


# Install stage observers only after every legacy V702/V703 wrapper has been defined.
_V702_MSE_RUN_ORIGINAL = MultiStrategyEngine._run_engine_safe
def _v702_mse_run_observed(engine_cls, snapshot):
    rows=list(_V702_MSE_RUN_ORIGINAL(engine_cls,snapshot) or [])
    for c in rows:
        V702PipelineMetrics.record("DISCOVERY",_v702_candidate_wrap(c,snapshot),
                                   symbol=getattr(c,"symbol",""),
                                   family=getattr(c,"family","") or getattr(c,"strategy_mode",""),
                                   details={"engine":str(getattr(c,"engine_id",""))})
    return rows
MultiStrategyEngine._run_engine_safe = staticmethod(_v702_mse_run_observed)

_V702_RANK_ORIGINAL = CompositeRankingEngine.rank.__func__
def _v702_rank_observed(cls, candidates):
    rows=list(_V702_RANK_ORIGINAL(cls,candidates) or [])
    for r in rows:
        c=getattr(r,"candidate",None)
        V702PipelineMetrics.record("RANKED",_v702_candidate_wrap(c),symbol=getattr(c,"symbol",""),
                                   family=getattr(c,"family","") or getattr(c,"strategy_mode",""))
    return rows
CompositeRankingEngine.rank = classmethod(_v702_rank_observed)

_V702_PREQUAL_ORIGINAL = globals().get("_v453_prequalify")
def _v702_prequal_observed(r, snap_by_symbol):
    # Distinguish the canonical arbiter pass from builder/preflight rechecks.
    # Rechecks run the same policy, but must not inflate arbiter PRE totals.
    source = str(_V702_PREQUAL_SOURCE.get() or "arbiter").strip().lower()
    preflight = source == "preflight"
    seen_stage = "PREQUAL_PREFLIGHT_SEEN" if preflight else "PREQUAL_SEEN"
    pass_stage = "PREQUAL_PREFLIGHT_PASS" if preflight else "PREQUAL_PASS"
    reject_stage = "PREQUAL_PREFLIGHT_REJECT" if preflight else "PREQUAL_REJECT"
    c=getattr(r,"candidate",None)
    sym=str(getattr(c,"symbol","") or "")
    family=getattr(c,"family","") or getattr(c,"strategy_mode","")
    key=_v702_candidate_wrap(c,(snap_by_symbol or {}).get(sym),sym)
    try:
        V702PipelineMetrics.record(seen_stage,key,symbol=sym,family=family,details={"source":source})
    except Exception:
        # Telemetry must never become a new candidate-admission dependency.
        pass
    _prequal_context_token = None
    try:
        # The canonical rejection recorder runs inside the gate. Bind identity here
        # so its event shares the same candidate key as PREQUAL_REJECT and any
        # exact candidate route events; never fall back to same-symbol attribution.
        _ctxvar = globals().get("_V702_PIPELINE_CONTEXT")
        if _ctxvar is not None and callable(getattr(_ctxvar, "set", None)):
            try:
                _existing_ctx = _ctxvar.get()
            except Exception:
                _existing_ctx = None
            _bound_ctx = dict(_existing_ctx) if isinstance(_existing_ctx, dict) else {}
            _bound_ctx.update({"candidate_key": key, "symbol": sym, "family": str(family or ""),
                               "cycle_id": V702PipelineMetrics._cycle(), "pipeline_stage": "PREQUAL",
                               "prequal_source": source})
            _prequal_context_token = _ctxvar.set(_bound_ctx)
        result=_V702_PREQUAL_ORIGINAL(r,snap_by_symbol) if callable(_V702_PREQUAL_ORIGINAL) else (False,"prequal_function_unavailable")
    except Exception as exc:
        try:
            V702PipelineMetrics.record(reject_stage,key,symbol=sym,family=family,
                details={"reason":f"exception.{type(exc).__name__}:{str(exc)[:140]}", "source":source})
        except Exception:
            # Preserve the original canonical-gate exception if telemetry itself fails.
            pass
        raise
    finally:
        if _prequal_context_token is not None:
            try:
                _ctxvar.reset(_prequal_context_token)
            except Exception:
                pass
    try:
        ok=bool(result[0]); reason=str(result[1] if len(result)>1 else "")
        _prequal_details = {"reason": reason[:180]}
        if (not ok and (reason.startswith("family_regime_disallowed")
                        or reason.startswith("htf.family_regime_disallowed"))):
            _prequal_details.update(_v702_prequal_policy_evidence(r, snap_by_symbol))
        _prequal_details["source"] = source
        V702PipelineMetrics.record(pass_stage if ok else reject_stage,key,symbol=sym,
                                   family=family,details=_prequal_details)

    except Exception:
        # Telemetry is non-authoritative and must never alter the gate result.
        pass
    # R39 read-only counterfactual study: record accepted baseline candidates and
    # narrowly scoped HTF/MID rejects. It cannot change the prequal result or gate.
    try:
        _v702_r39_shadow_record = globals().get("_V702_R39_RECORD_PREQUAL")
        if callable(_v702_r39_shadow_record):
            _v702_r39_shadow_record(r, snap_by_symbol, result)
    except Exception as _v702_r39_shadow_exc:
        try:
            STATS["v702_cf_shadow_hook_errors"] = int(STATS.get("v702_cf_shadow_hook_errors", 0) or 0) + 1
        except Exception:
            pass
    return result
globals()["_v453_prequalify"] = _v702_prequal_observed

_V702_ARB_SELECT_ORIGINAL = GlobalOpportunityArbiter.select.__func__
def _v702_select_observed(cls, ranked, max_winners=3):
    rows=list(_V702_ARB_SELECT_ORIGINAL(cls,ranked,max_winners=max_winners) or [])
    try:
        current_cycle = int(STATS.get("v681_runtime_cycle_id", 0) or 0)
        old_map = STATS.get("v702_selected_candidate_key_by_symbol")
        if not isinstance(old_map, dict):
            old_map = {}
        # Drop old-cycle rows; never attach a later route result to a stale selection.
        selected_map = {k: v for k, v in old_map.items() if isinstance(v, dict) and int(v.get("cycle_id", -1)) == current_cycle}
    except Exception:
        current_cycle = 0
        selected_map = {}
    for r in rows:
        c=getattr(r,"candidate",None)
        key = _v702_candidate_wrap(c)
        symbol = str(getattr(c,"symbol","") or "")
        family = str(getattr(c,"family","") or getattr(c,"strategy_mode","") or "")
        V702PipelineMetrics.record("SELECTED",key,symbol=symbol,family=family)
        if symbol:
            selected_map[symbol.upper()] = {"candidate_key": key, "family": family,
                                             "cycle_id": current_cycle, "selected_ts": WALL_NOW()}
    STATS["v702_selected_candidate_key_by_symbol"] = selected_map
    return rows
GlobalOpportunityArbiter.select = classmethod(_v702_select_observed)

_V702_V423_NOTE_ORIGINAL = V423Funnel.note_stage.__func__
