def _v702_candidate_telegram_enqueue_allowed(candidate_key, msg):
    """Count TG funnel progress only for canonical opportunity alerts after Q.

    Telegram also carries operator digests and builder-block diagnostics while a
    candidate ContextVar may still be set. Those messages are useful operational
    traffic, but are not opportunity delivery and must not inflate candidate
    funnel counts. Queue commitment must exist for this exact candidate key.
    """
    key = str(candidate_key or "")
    text = str(msg or "").lstrip()
    if not key:
        return False
    if not _v702_is_canonical_opportunity_message(text):
        return False
    live_cycle = V702PipelineMetrics._cycle()
    try:
        with V702PipelineMetrics._lock:
            events = list(V702PipelineMetrics._events)
        return any(
            isinstance(ev, dict)
            and str(ev.get("stage") or "").upper() == "QUEUED"
            and str(ev.get("candidate_key") or "") == key
            and int(ev.get("cycle_id", -1)) == live_cycle
            for ev in events
        )
    except Exception:
        return False


_V702_TELEGRAM_ENQUEUE_ORIGINAL = TelegramDispatcher.enqueue.__func__
@classmethod
async def _v702_telegram_enqueue_observed(cls, msg, *args, **kwargs):
    result=await _V702_TELEGRAM_ENQUEUE_ORIGINAL(cls,msg,*args,**kwargs)
    try:
        # The dispatcher contract returns a strict bool. Unknown/None results
        # are not treated as successful queue commits for telemetry purposes.
        if result is True:
            ctx = _V702_PIPELINE_CONTEXT.get() if _V702_PIPELINE_CONTEXT is not None else None
            key = str((ctx or {}).get("candidate_key") or "") if isinstance(ctx, dict) else ""
            if _v702_candidate_telegram_enqueue_allowed(key, msg):
                V702PipelineMetrics.record_current("TELEGRAM_ENQUEUED",details={"message_chars":len(str(msg or "")), "queue_committed":True})
            else:
                STATS["v702_telegram_enqueue_unattributed"] = int(STATS.get("v702_telegram_enqueue_unattributed", 0) or 0) + 1
    except Exception:
        try: STATS["v702_telegram_enqueue_telemetry_errors"] = int(STATS.get("v702_telegram_enqueue_telemetry_errors", 0) or 0) + 1
        except Exception: pass
    return result
TelegramDispatcher.enqueue = _v702_telegram_enqueue_observed

async def _v702_a66_restore_telegram_outbox_once() -> int:
    """Rehydrate durable operator messages after process restart (at-least-once)."""
    try:
        rows = await asyncio.to_thread(DBManager.list_pending_telegram_outbox, 5000)
        restored = 0
        maxlen = int(getattr(TelegramDispatcher._queue, "maxlen", 0) or 0)
        for row in rows:
            raw = str(row.get("message") or "")
            if not raw:
                continue
            key = TelegramDispatcher._message_key(raw)
            ids = TelegramDispatcher._outbox_ids_by_key[key]
            outbox_id = str(row.get("outbox_id") or "")
            if outbox_id and outbox_id not in ids:
                ids.append(outbox_id)
            queued_keys = {TelegramDispatcher._message_key(x) for x in list(TelegramDispatcher._queue)}
            if key in queued_keys or key in TelegramDispatcher._outbox_inflight_keys:
                continue
            if maxlen and len(TelegramDispatcher._queue) >= maxlen:
                break
            if row.get("status") == "SENDING":
                # A crash may have occurred after venue acceptance; delivery is
                # at-least-once and an operator-visible replay is safer than loss.
                await asyncio.to_thread(DBManager.update_telegram_outbox, outbox_id, "RETRY_PENDING", int(row.get("attempts", 0) or 0), "recovered_after_interrupted_send")
            key_attempts = max(0, int(row.get("attempts", 0) or 0))
            if key_attempts:
                TelegramDispatcher._attempts[key] = min(key_attempts, max(0, int(CONFIG.get("V696_TELEGRAM_RETRY_MAX", 5) or 5) - 1))
            TelegramDispatcher._queue.append(raw)
            restored += 1
        if restored:
            STATS["v702_a66_telegram_outbox_restored"] = int(STATS.get("v702_a66_telegram_outbox_restored", 0) or 0) + restored
            STATS["v702_a66_telegram_outbox_callbacks_not_restored"] = int(STATS.get("v702_a66_telegram_outbox_callbacks_not_restored", 0) or 0) + restored
            logger.warning("[V702-A66-TG-OUTBOX] restored %d pending message(s); semantic callbacks are process-local and are not replayed", restored)
        return restored
    except Exception as exc:
        STATS["v702_a66_telegram_outbox_restore_errors"] = int(STATS.get("v702_a66_telegram_outbox_restore_errors", 0) or 0) + 1
        logger.critical("[V702-A66-TG-OUTBOX] restore failed: %s", exc)
        return 0

async def _v702_a66_telegram_outbox_feeder() -> None:
    next_prune_at = 0.0
    while TelegramDispatcher._running:
        try:
            await _v702_a66_restore_telegram_outbox_once()
            _now = MONO_NOW()
            if _now >= next_prune_at:
                try:
                    _prune = await asyncio.to_thread(DBManager.prune_telegram_outbox, 30, 5000)
                    STATS["v702_a66_telegram_outbox_retention"] = dict(_prune)
                    if int(_prune.get("deleted_by_age", 0)) + int(_prune.get("deleted_by_cap", 0)) > 0:
                        logger.info("[V702-A66-TG-OUTBOX] terminal retention pruned=%s", _prune)
                    next_prune_at = _now + 86400.0
                except Exception as _prune_exc:
                    STATS["v702_a66_telegram_outbox_retention_error"] = f"{type(_prune_exc).__name__}:{str(_prune_exc)[:160]}"
                    logger.warning("[V702-A66-TG-OUTBOX] terminal retention deferred: %s", _prune_exc)
                    next_prune_at = _now + 300.0
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            STATS["v702_a66_telegram_outbox_feeder_errors"] = int(STATS.get("v702_a66_telegram_outbox_feeder_errors", 0) or 0) + 1
            logger.warning("[V702-A66-TG-OUTBOX] feeder error: %s", exc)
        await asyncio.sleep(5.0)

_V702_A66_PREV_TG_RUN = TelegramDispatcher.run_forever
async def _v702_a66_tg_run_forever(cls):
    await _v702_a66_restore_telegram_outbox_once()
    cls._running = True
    feeder = asyncio.create_task(_v702_a66_telegram_outbox_feeder())
    try:
        await _V702_A66_PREV_TG_RUN()
    finally:
        cls._running = False
        feeder.cancel()
        try: await feeder
        except asyncio.CancelledError: pass
TelegramDispatcher.run_forever = classmethod(_v702_a66_tg_run_forever)

_V702_SUBMIT_ENTRY_ORIGINAL = OrderExecutor.submit_entry
async def _v702_submit_entry_observed(exchange,symbol,qty,price,*args,**kwargs):
    key=V702PipelineMetrics.current_candidate_key()
    V702PipelineMetrics.record_current("EXECUTION_ATTEMPT",symbol=symbol,candidate_key=key,
        details={"qty":float(qty or 0.0),"estimated_entry":float(price or 0.0),
                 "market_type":str(CONFIG.get("MARKET_TYPE","SPOT")),"long_only":bool(CONFIG.get("LONG_ONLY",True))})
    result=await _V702_SUBMIT_ENTRY_ORIGINAL(exchange,symbol,qty,price,*args,**kwargs)
    try:
        if isinstance(result,(tuple,list)) and result and bool(result[0]):
            V702PipelineMetrics.record_current("ORDER_ACCEPTED",symbol=symbol,candidate_key=key,
                details={"order_id":str(result[1] or ""),"fill_price":float(result[2] or 0.0)})
    except Exception: pass
    return result
OrderExecutor.submit_entry = staticmethod(_v702_submit_entry_observed)

# Protection is a separate terminal stage: an accepted entry is not counted as
# protected until native SL verification succeeds or the configured software-SL
# fallback is genuinely armed. Failed protection stays visible as a hard block.
_V702_PLACE_SL_ORIGINAL = OrderExecutor.place_sl
async def _v702_place_sl_observed(exchange, trade, *args, **kwargs):
    symbol = str(getattr(trade, "symbol", "") or "")
    try:
        result = await _V702_PLACE_SL_ORIGINAL(exchange, trade, *args, **kwargs)
    except Exception as exc:
        # Surface unexpected native-stop exceptions but preserve their original
        # control-flow semantics; do not pretend protection succeeded or swallow
        # an ambiguous venue outcome.
        try:
            V702PipelineMetrics.record_current(
                "NATIVE_SL_UNVERIFIED", symbol=symbol, details={
                    "sl_health_state": str(getattr(trade, "sl_health_state", "")),
                    "software_fallback_pending": False,
                    "exception": f"{type(exc).__name__}:{str(exc)[:120]}",
                })
        except Exception:
            _v647_record_suppressed_exception()
        raise
    try:
        native_ok = bool(isinstance(result, (tuple, list)) and result and result[0])
        if native_ok:
            V702PipelineMetrics.record_current(
                "PROTECTED", symbol=symbol, details={
                    "protection_mode": "EXCHANGE_NATIVE",
                    "sl_health_state": str(getattr(trade, "sl_health_state", "")),
                })
        else:
            # This is a failed native-stop attempt, not yet a failed protection
            # outcome: SignalBuilder may successfully arm the software-SL fallback.
            V702PipelineMetrics.record_current(
                "NATIVE_SL_UNVERIFIED", symbol=symbol, details={
                    "sl_health_state": str(getattr(trade, "sl_health_state", "")),
                    "software_fallback_pending": True,
                })
    except Exception:
        _v647_record_suppressed_exception()
    return result
OrderExecutor.place_sl = staticmethod(_v702_place_sl_observed)

# Keep operator-facing digest focused but add one authoritative, scope-labelled funnel.
try:
    _V702_DIGEST_BUILD_ORIGINAL = _V702R28TelegramDigest.build.__func__
    def _v702_digest_build_observed(cls):
        raw = _V702_DIGEST_BUILD_ORIGINAL(cls)
        line = V702PipelineMetrics.digest_line()
        window_line = V702PipelineMetrics.window_line()
        marker = "Execution orders/protection/control/errors remain immediate; no gate was relaxed."
        addition = line + "\n" + window_line
        if marker in raw:
            out = raw.replace(marker, addition + "\n" + marker, 1)
        else:
            out = raw + "\n" + addition
        # The underlying builder has already prioritized its compacted state.
        # This final cap keeps the extra pipeline truth inside Telegram's safe
        # payload budget while preserving both scope-labelled pipeline lines.
        limit = max(1000, int(CONFIG.get("V702_R28_TELEGRAM_DIGEST_MAX_CHARS", 3700) or 3700))
        if len(out) > limit:
            marker_present = marker in raw
            prefix = raw.split(marker, 1)[0] if marker_present else raw
            footer = "\n" + marker if marker_present else ""
            budget = max(100, limit - len(addition) - len(footer) - 2)

            def _compact_digest_prefix(source, char_budget):
                source_lines = str(source or "").splitlines()
                if len(source) <= char_budget:
                    return source
                def _clip(value, cap):
                    value = str(value or "")
                    return value if len(value) <= cap else value[:max(1, cap - 1)] + "…"
                head_limits = [42, 70, 110, 270, 140, 110, 420, 90, 170]
                head = [_clip(value, head_limits[i]) for i, value in enumerate(source_lines[:9])]
                tail_source = source_lines[-2:] if len(source_lines) > 11 else []
                tail = [_clip(value, cap) for value, cap in zip(tail_source, (150, 220))]
                middle = source_lines[len(source_lines[:9]):-len(tail_source)] if tail_source else source_lines[9:]
                mandatory = {i for i, value in enumerate(middle)
                             if value.startswith("<b>") and value.endswith("</b>")}
                headings = [middle[i] for i in sorted(mandatory)]

                def _compose_head():
                    base = head + headings + tail
                    return "\n".join(base), len("\n".join(base))

                base_text, base_len = _compose_head()
                # Preserve all section headings and the final operational
                # footer. If dynamic telemetry is large, progressively shorten
                # volatile header rows rather than slicing off whole sections.
                shrink_order = [(6, 70, 50), (3, 130, 40), (4, 60, 30),
                                (8, 70, 25), (5, 55, 25), (2, 55, 20), (1, 40, 15)]
                for index, minimum, step in shrink_order:
                    while base_len > char_budget and index < len(head_limits) and head_limits[index] > minimum:
                        head_limits[index] = max(minimum, head_limits[index] - step)
                        head = [_clip(value, head_limits[i]) for i, value in enumerate(source_lines[:9])]
                        base_text, base_len = _compose_head()
                if base_len > char_budget:
                    # Ultra-small custom payload: retain the main release
                    # header and section labels, not unbounded diagnostic text.
                    head = [_clip(value, cap) for value, cap in zip(source_lines[:9],
                            (32, 48, 60, 90, 70, 50, 55, 45, 70))]
                    base_text, base_len = _compose_head()
                keep = set(mandatory)
                remaining = max(0, char_budget - base_len - (len(keep) + 1))
                for i, value in enumerate(middle):
                    if i in mandatory:
                        continue
                    cost = len(value) + 1
                    if cost <= remaining:
                        keep.add(i)
                        remaining -= cost
                mid_values = [value for i, value in enumerate(middle) if i in keep]
                compacted = "\n".join(head + mid_values + tail)
                return compacted[:char_budget]

            prefix = _compact_digest_prefix(prefix, budget)
            out = prefix.rstrip() + "\n" + addition + footer
            if len(out) > limit:
                # Final guard keeps the pipeline and execution footer intact.
                prefix_budget = max(0, limit - len(addition) - len(footer) - 1)
                prefix = prefix[:prefix_budget]
                out = prefix.rstrip() + "\n" + addition + footer
        _repair = globals().get("_v702_a37_repair_telegram_html")
        return _repair(out) if callable(_repair) else out
    _V702R28TelegramDigest.build=classmethod(_v702_digest_build_observed)
except Exception:
    pass

