def record_reject(*, trace_id="", symbol="", taxonomy="", reason="", stage="unknown",
                   source="unknown", ctx=None, candidate_key=""):
    """Canonical V410/V455/V702 rejection entry point; telemetry only.

    Existing record_rejection remains responsible for legacy counts/alerts; this
    facade is the single bridge into V702's candidate-stage event ledger.
    """
    try:
        return _v702_record_reject_facade(
            V702PipelineMetrics.reject, trace_id=str(trace_id or ""),
            symbol=str(symbol or ""), taxonomy=str(taxonomy or ""),
            reason=str(reason or "unknown"), stage=str(stage or "unknown"),
            source=str(source or "unknown"), context=ctx or {},
            candidate_key=str(candidate_key or ""),
        )
    except Exception:
        STATS["v702_canonical_reject_facade_errors"] = int(STATS.get("v702_canonical_reject_facade_errors", 0) or 0) + 1
        return False

_V702_RECORD_REJECTION_ORIGINAL = globals().get("record_rejection")
def _v702_record_rejection_with_metrics(*args, **kwargs):
    result=_V702_RECORD_REJECTION_ORIGINAL(*args,**kwargs) if callable(_V702_RECORD_REJECTION_ORIGINAL) else None
    try:
        trace_id=args[0] if len(args)>0 else kwargs.get("trace_id","")
        symbol=args[1] if len(args)>1 else kwargs.get("symbol","")
        taxonomy=args[2] if len(args)>2 else kwargs.get("taxonomy","")
        code=args[3] if len(args)>3 else kwargs.get("code","")
        stage=args[4] if len(args)>4 else kwargs.get("stage","")
        context=args[6] if len(args)>6 else kwargs.get("ctx",{})
        ctx = _V702_PIPELINE_CONTEXT.get() if _V702_PIPELINE_CONTEXT is not None else None
        candidate_key = str((ctx or {}).get("candidate_key") or "") if isinstance(ctx, dict) else ""
        if candidate_key:
            _v702_store_builder_candidate_reason(candidate_key, symbol or (ctx or {}).get("symbol", ""), stage, code, taxonomy, trace_id)
        record_reject(trace_id=trace_id, symbol=symbol, taxonomy=taxonomy, reason=code,
                      stage=stage, source="record_rejection", ctx=context,
                      candidate_key=candidate_key)
        try:
            _stage_l = str(stage or "").strip().lower()
            _tax_l = str(taxonomy or "").strip().lower()
            _code_l = str(code or "").strip().lower()
            if _stage_l == "scorer" and _tax_l == "score" and "score_below_threshold" in _code_l:
                _ctx_now = _V702_PIPELINE_CONTEXT.get() if _V702_PIPELINE_CONTEXT is not None else None
                _ctx_now = _ctx_now if isinstance(_ctx_now, dict) else {}
                _score_key = str(_ctx_now.get("candidate_key") or f"{V702PipelineMetrics._cycle()}|{symbol}|trace|{trace_id or 'unknown'}")
                V702PipelineMetrics.record(
                    "SCORE_BLOCK", _score_key, symbol=symbol,
                    family=str(_ctx_now.get("family") or ""),
                    details={"reason":str(code or "")[:180], "score":(context or {}).get("score") if isinstance(context,dict) else None,
                             "threshold":((context or {}).get("min_score") if isinstance(context,dict) else None)},
                )
        except Exception:
            STATS["v702_pipeline_score_block_metrics_errors"] = int(STATS.get("v702_pipeline_score_block_metrics_errors", 0) or 0) + 1
    except Exception:
        try:
            STATS["v702_builder_rejection_context_errors"] = int(STATS.get("v702_builder_rejection_context_errors", 0) or 0) + 1
        except Exception:
            pass
    return result
globals()["record_rejection"] = _v702_record_rejection_with_metrics

