def _v702_r38_pipeline_contract_self_test() -> Dict[str, Any]:
    """Check live telemetry wiring and hard invariants without network activity."""
    checks: Dict[str, bool] = {}
    try:
        expected_stages = {
            "DISCOVERY", "PREQUAL_SEEN", "PREQUAL_PASS", "PREQUAL_REJECT",
            "PREQUAL_PREFLIGHT_SEEN", "PREQUAL_PREFLIGHT_PASS", "PREQUAL_PREFLIGHT_REJECT",
            "RANKED", "SELECTED", "PREEXEC_PASS", "PREEXEC_BLOCK", "ROUTE_DEFERRED",
            "BUILDER_ENTERED", "BUILDER_RETURNED_NONE", "BUILDER_EXCEPTION", "SCORE_PASS", "SCORE_BLOCK",
            "PRESEND_PASS", "QUEUED", "TELEGRAM_ENQUEUED", "EXECUTION_ATTEMPT",
            "ORDER_ACCEPTED", "TRADE_STATE_CREATED", "NATIVE_SL_UNVERIFIED",
            "PROTECTED", "PROTECTION_FAILED",
        }
        stages = tuple(V702PipelineMetrics.STAGES)
        checks["stage_registry_complete_and_unique"] = len(stages) == len(set(stages)) and set(stages) == expected_stages
        checks["mse_discovery_observer_installed"] = MultiStrategyEngine._run_engine_safe is _v702_mse_run_observed
        checks["ranking_observer_installed"] = getattr(CompositeRankingEngine.rank, "__func__", None) is _v702_rank_observed
        _active_prequal_observer = globals().get("_v453_prequalify")
        # R39-R2 may place a telemetry-only outer wrapper around the original
        # prequal observer; require that exact observer to remain directly in
        # the delegation chain rather than demanding pointer identity at top level.
        checks["prequal_observer_installed"] = (
            _active_prequal_observer is _v702_prequal_observed
            or (bool(getattr(_active_prequal_observer, "_v702_cf_shadow_wrapped", False))
                and getattr(_active_prequal_observer, "_v702_cf_shadow_original", None) is _v702_prequal_observed)
            or (bool(getattr(_active_prequal_observer, "_v702_a44_wrapped", False))
                and getattr(_active_prequal_observer, "_v702_a44_original_observer", None) is _v702_prequal_observed)
        )
        checks["global_select_observer_installed"] = getattr(GlobalOpportunityArbiter.select, "__func__", None) is _v702_select_observed
        checks["builder_observer_installed"] = SignalBuilder.build_and_route is _v702_builder_observed
        checks["presend_observer_installed"] = PreSendGate.evaluate is _v702_presend_observed
        checks["telegram_enqueue_observer_installed"] = getattr(TelegramDispatcher.enqueue, "__func__", None) is getattr(_v702_telegram_enqueue_observed, "__func__", _v702_telegram_enqueue_observed)
        checks["entry_observer_installed"] = OrderExecutor.submit_entry is _v702_submit_entry_observed
        checks["stop_protection_observer_installed"] = OrderExecutor.place_sl is _v702_place_sl_observed
        _current_digest_build = getattr(_V702R28TelegramDigest.build, "__func__", None)
        _digest_observer = globals().get("_v702_digest_build_observed")
        checks["digest_observer_installed"] = callable(_digest_observer) and (
            _current_digest_build is _digest_observer
            or (globals().get("_V702_A44_OLD_BUILD") is _digest_observer
                and bool(getattr(_current_digest_build, "_v702_a44_wrapped", False)))
        )
        _current_arm = globals().get("_v699_arm_live_epoch")
        checks["live_epoch_arm_observer_installed"] = (
            _current_arm is _v702_arm_live_epoch_with_pipeline_metrics
            or (globals().get("_V702_A44_OLD_ARM") is _v702_arm_live_epoch_with_pipeline_metrics
                and bool(getattr(_current_arm, "_v702_a44_wrapped", False)))
        )
        checks["rejection_observer_installed"] = globals().get("record_rejection") is _v702_record_rejection_with_metrics
        _digest_constants = tuple(V702PipelineMetrics.digest_line.__code__.co_consts) if callable(V702PipelineMetrics.digest_line) else ()
        checks["pipeline_digest_has_explicit_scope"] = callable(V702PipelineMetrics.digest_line) and any(
            isinstance(value, str) and ("PIPELINE[CYCLE]" in value or "LIVE_EPOCH_NOT_ARMED" in value)
            for value in _digest_constants
        )
        checks["pipeline_digest_order_matches_runtime"] = any(
            isinstance(value, str) and "DISC/RANK/PRE/PASS/PRE_REJ/SEL" in value
            for value in _digest_constants
        )
        checks["pipeline_digest_exposes_prequal_rejections"] = any(
            isinstance(value, str) and "PRE_REJ" in value
            for value in _digest_constants
        )
        _record_current_constants = tuple(V702PipelineMetrics.record_current.__code__.co_consts)
        checks["candidate_stage_metrics_do_not_invent_trace_keys"] = any(
            isinstance(value, str) and "v702_pipeline_unattributed_events" in value
            for value in _record_current_constants
        ) and any(isinstance(value, str) and value == "trace" for value in _record_current_constants) is False
        _route_note_constants = tuple(_v702_selected_route_note.__code__.co_consts)
        checks["selected_route_outcomes_explicit"] = (
            callable(globals().get("_v702_pipeline_route_outcome"))
            and "_v702_pipeline_route_outcome" in _v702_selected_route_note.__code__.co_names
            and any(isinstance(value, str) and value == "PREEXEC_BLOCK" for value in _route_note_constants)
            and any(isinstance(value, str) and value == "PREEXEC_PASS" for value in _route_note_constants)
        )
        _builder_constants = tuple(_v702_builder_observed.__code__.co_consts)
        checks["builder_none_and_exception_outcomes_visible"] = (
            any(isinstance(value, str) and value == "BUILDER_RETURNED_NONE" for value in _builder_constants)
            and any(isinstance(value, str) and value == "BUILDER_EXCEPTION" for value in _builder_constants)
        )
        _prequal_constants = tuple(_v702_prequal_observed.__code__.co_consts)
        checks["prequal_gate_exceptions_are_counted_then_reraised"] = (
            any(isinstance(value, str) and value == "PREQUAL_SEEN" for value in _prequal_constants)
            and any(isinstance(value, str) and value == "PREQUAL_REJECT" for value in _prequal_constants)
            and any(isinstance(value, str) and value.startswith("exception.") for value in _prequal_constants)
        )
        _native_sl_constants = tuple(_v702_place_sl_observed.__code__.co_consts)
        checks["native_sl_exceptions_are_visible"] = any(
            isinstance(value, str) and value == "NATIVE_SL_UNVERIFIED" for value in _native_sl_constants
        )
        checks["spot_long_only_invariant"] = (
            bool(CONFIG.get("LONG_ONLY", True))
            and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT"
            and str(CONFIG.get("TRADING_SIDE", "LONG")).upper() == "LONG"
            and not bool(CONFIG.get("FUTURES_ENABLED", False))
            and not bool(CONFIG.get("ENABLE_FUTURES", False))
            and not bool(CONFIG.get("ALLOW_SHORT", False))
            and not bool(CONFIG.get("ALLOW_SHORTS", False))
        )
        checks["hard_gate_bypass_disabled"] = not bool(CONFIG.get("V702_R38_HARD_GATE_BYPASS", True))
        checks["base_score_floor_preserved"] = float(CONFIG.get("MIN_LIVE_SCORE", 70.0)) >= 70.0
        checks["core_liquidity_floor_preserved"] = float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 3_000_000.0)) >= 3_000_000.0
        checks["concurrent_trade_cap_preserved"] = 1 <= int(CONFIG.get("MAX_CONCURRENT_TRADES", 2)) <= 2
        checks["forbidden_set_fail_closed"] = set(V702_HARD_FORBIDDEN_BASES).issuperset({"AERO", "BNB", "CAKE", "ETHFI", "PUMP"})
        checks["final_geometry_authority_present"] = callable(globals().get("_v702_normalize_final_geometry")) and callable(globals().get("_v702_sr_aware_target_plan")) and callable(globals().get("_v702_reanchor_targets_after_fill"))
        checks["r37_terminal_contract_passed"] = bool((STATS.get("v702_r37_final_validation") or {}).get("pass", False))
        checks["sr_target_terminal_contract_passed"] = bool((STATS.get("v702_sr_target_final_validation") or {}).get("pass", False))
        identities = (
            SCRIPT_VERSION, __version__, RUNTIME_BUILD_ID, CANONICAL_RUNTIME_IDENTITY,
            CONFIG.get("SCRIPT_VERSION", ""), STATS.get("script_version", ""),
            STATS.get("runtime_build_id", ""), STATS.get("canonical_runtime_identity", ""),
            FINAL_CANONICAL_RUNTIME.get("public_runtime_identity", ""),
        )
        checks["active_identity_surfaces_match_r38"] = all(x == V702_R38_PUBLIC_RUNTIME_IDENTITY for x in identities)
        checks["active_revision_surfaces_match_r38"] = (
            FINAL_CANONICAL_RUNTIME.get("canonical_revision") == V702_R38_FINAL_CANONICAL_REVISION
            and FINAL_CANONICAL_RUNTIME.get("terminal_authority") == "V702-R38"
        )
        return {
            "pass": bool(checks) and all(checks.values()),
            "checks": checks,
            "failed": [k for k, v in checks.items() if not v],
            "count": len(checks),
            "closure": V702_R38_CLOSURE_ID,
            "revision": V702_R38_FINAL_CANONICAL_REVISION,
            "hard_gate_bypass": False,
            "live_network_calls": 0,
        }
    except Exception as exc:
        return {"pass": False, "checks": checks, "failed": [k for k, v in checks.items() if not v],
                "error": f"{type(exc).__name__}:{exc}", "closure": V702_R38_CLOSURE_ID,
                "revision": V702_R38_FINAL_CANONICAL_REVISION, "hard_gate_bypass": False}


_V702_R38_CANONICAL_BASE_VALIDATOR = globals().get("validate_config")
def _v702_r38_terminal_validate_config() -> bool:
    base_ok = False
    try:
        base_ok = bool(_V702_R38_CANONICAL_BASE_VALIDATOR()) if callable(_V702_R38_CANONICAL_BASE_VALIDATOR) else False
        test = _v702_r38_pipeline_contract_self_test()
        STATS["v702_r38_pipeline_contract_self_test"] = test
        failed = list(test.get("failed") or [])
        if not base_ok:
            failed.append("previous_canonical_validation")
        result = {
            "pass": bool(base_ok and test.get("pass", False)),
            "previous_validation": base_ok,
            "checks": dict(test.get("checks") or {}),
            "failed": failed,
            "count": int(test.get("count", 0) or 0),
            "closure": V702_R38_CLOSURE_ID,
            "revision": V702_R38_FINAL_CANONICAL_REVISION,
            "hard_gate_bypass": False,
            "live_network_calls": 0,
        }
        STATS["v702_r38_final_validation"] = result
        FINAL_CANONICAL_RUNTIME["r38_validation"] = result
        if result["pass"]:
            logger.info("[V702-R38] FINAL CANONICAL PRODUCTION VALIDATION PASS checks=%d", result["count"])
        else:
            logger.critical("[V702-R38] FINAL CANONICAL PRODUCTION VALIDATION FAIL failed=%s", failed)
        return bool(result["pass"])
    except Exception as exc:
        STATS["v702_r38_final_validation"] = {
            "pass": False, "previous_validation": base_ok,
            "error": f"{type(exc).__name__}:{exc}",
            "closure": V702_R38_CLOSURE_ID, "revision": V702_R38_FINAL_CANONICAL_REVISION,
            "hard_gate_bypass": False,
        }
        return False


