def _v702_a3_normalize_builder_block(raw):
    """Avoid cross-candidate same-symbol attribution in SELECTED→BUILDER diagnostics."""
    text = str(raw or "")
    if not re.search(r"SELECTED → BUILDER BLOCK", text, flags=re.I) or "reason=builder_returned_none" not in text:
        return text
    try:
        plain = re.sub(r"<[^>]+>", "", text)
        symbol_m = re.search(r"SELECTED → BUILDER BLOCK\s+([^\s/<>|]{1,64}/USDT)", plain, flags=re.I | re.UNICODE)
        symbol = _v702_r39_normalize_spot_symbol(symbol_m.group(1)) if symbol_m and callable(globals().get("_v702_r39_normalize_spot_symbol")) else (symbol_m.group(1) if symbol_m else "")
        ctx = _V702_PIPELINE_CONTEXT.get() if _V702_PIPELINE_CONTEXT is not None else None
        candidate_key = str((ctx or {}).get("candidate_key") or "") if isinstance(ctx, dict) else ""
        active_symbol = str((ctx or {}).get("symbol") or "") if isinstance(ctx, dict) else ""
        with _V702_BUILDER_REJECTION_CONTEXT_LOCK:
            inflight_map = STATS.get("v702_builder_inflight_by_candidate", {})
            inflight = dict(inflight_map.get(candidate_key) or {}) if candidate_key and isinstance(inflight_map, dict) else {}
        started = float(inflight.get("started_ts", 0.0) or 0.0)
        blocker = _v702_builder_rejection_reason_for_candidate(candidate_key, started) if (candidate_key and started and (not active_symbol or active_symbol.upper() == (symbol or "").upper())) else None
        now = float(WALL_NOW())
        max_age = max(1.0, float(CONFIG.get("V702_R25_BUILDER_TRUTH_MAX_AGE_SEC", 20.0)))
        usable = bool(blocker and symbol and str(blocker.get("symbol", "")).upper() == symbol.upper() and 0.0 <= now - float(blocker.get("ts", 0.0) or 0.0) <= max_age)
        if usable:
            reason = str(blocker.get("reason") or blocker.get("code") or "candidate_scoped_block")[:180]
            stage = str(blocker.get("stage") or "builder")[:80]
            root = str(blocker.get("root") or "")[:48]
            STATS["v702_a3_builder_block_candidate_attributed"] = int(STATS.get("v702_a3_builder_block_candidate_attributed", 0) or 0) + 1
        else:
            reason, stage, root = "builder_terminal_no_result_unattributed", "builder_terminal", ""
            STATS["v702_a3_builder_block_unattributed"] = int(STATS.get("v702_a3_builder_block_unattributed", 0) or 0) + 1
        text = re.sub(r"reason=builder_returned_none", "reason=" + reason, text, count=1)
        text = re.sub(r"stage=[^\s]+", "stage=" + stage, text, count=1)
        if root:
            text = re.sub(r"root=[^\s]+", "root=" + root, text, count=1)
        return text
    except Exception:
        STATS["v702_a3_builder_block_normalize_errors"] = int(STATS.get("v702_a3_builder_block_normalize_errors", 0) or 0) + 1
        return text.replace("reason=builder_returned_none", "reason=builder_terminal_no_result_unattributed", 1)

_v702_r31_normalize_builder_block = _v702_a3_normalize_builder_block
STATS["v702_a3_builder_block_normalizer_candidate_scoped"] = True

