# =============================================================================
# V702-R39-R1 — truthful symbol attribution in compacted Telegram digests.
# The earlier ASCII-only parser lost real symbols containing parentheses or
# Unicode (for example GOLD(PAXG)/USDT), creating a false UNKNOWN/USDT row or
# a '?' shadow label. This patch is display/telemetry-only; it changes no gate.
# =============================================================================
def _v702_r39_normalize_spot_symbol(value):
    raw = str(value or "").strip()
    if not re.fullmatch(r"[^/\s<>|]{1,64}/USDT", raw, flags=re.IGNORECASE | re.UNICODE):
        return None
    base, quote = raw.split("/", 1)
    if not base:
        return None
    return f"{base.upper()}/{quote.upper()}"


def _v702_r39_escape_digest_text(value):
    raw = str(value or "")
    try:
        html_lib = globals().get("_html_v702_r28")
        if html_lib is not None and callable(getattr(html_lib, "escape", None)):
            return html_lib.escape(raw, quote=True)
    except Exception:
        pass
    return raw.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;").replace("'", "&#x27;")


def _v702_r39_extract_standalone_symbol(text):
    try:
        plain = _V702R28TelegramDigest._strip(str(text or ""))
        for line in plain.splitlines():
            symbol = _v702_r39_normalize_spot_symbol(line.strip())
            if symbol:
                return symbol
    except Exception:
        pass
    return None


def _v702_r39_capture_discovery(cls, text, on_success=None, on_failure=None):
    plain = cls._strip(str(text or ""))
    symbol = _v702_r39_extract_standalone_symbol(plain)
    display_symbol = symbol or "UNATTRIBUTED"
    if symbol:
        row_key = symbol
    else:
        # Keep callback lifecycle observable without inventing a valid-looking
        # exchange pair. A content hash prevents unrelated missing-symbol rows
        # from collapsing into one dictionary entry.
        digest = hashlib.sha256(plain.encode("utf-8", errors="replace")).hexdigest()[:16]
        row_key = f"__UNATTRIBUTED__:{digest}"
        try:
            STATS["v702_digest_discovery_symbol_unattributed"] = int(STATS.get("v702_digest_discovery_symbol_unattributed", 0) or 0) + 1
        except Exception:
            pass
    strategy = cls._text(r"Strategy:\s*([^\n]+)", plain, "?")
    engine = cls._num(r"Engine Score:\s*([0-9.]+)", plain, -1.0)
    reviewed = cls._num(r"Reviewed Score:\s*([0-9.]+)", plain, -1.0)
    projected = cls._num(r"Projected Canonical Live Score:\s*([0-9.]+)", plain, -1.0)
    htf = cls._num(r"HTF:\s*([0-9.]+)", plain, -1.0)
    vol = cls._num(r"Vol:\s*x?([0-9.]+)", plain, -1.0)
    rs = cls._num(r"RS:\s*([-0-9.]+)%", plain, 0.0)
    chase = cls._num(r"Chase:\s*([-0-9.]+)\s*ATR", plain, -1.0)
    tier = cls._text(r"Tier:\s*([^\n]+)", plain, "?")
    context = cls._text(r"Context:\s*([^\n]+)", plain, "?")
    now = float(WALL_NOW())
    row = {"symbol": display_symbol, "strategy": strategy, "engine": engine,
           "reviewed": reviewed, "projected": projected, "htf": htf, "vol": vol,
           "rs": rs, "chase": chase, "tier": tier, "context": context,
           "raw": plain, "ts": now, "on_success": on_success, "on_failure": on_failure}
    with cls._lock:
        old = cls._discovery_by_symbol.get(row_key)
        if old and (float(old.get("ts", 0.0)) > now - 2.0) and float(old.get("projected", -1.0)) > projected:
            return
        cls._discovery_by_symbol[row_key] = row
        if len(cls._discovery_by_symbol) > 40:
            ordered = sorted(cls._discovery_by_symbol.items(), key=lambda item: float(item[1].get("ts", 0.0)), reverse=True)[:40]
            cls._discovery_by_symbol = {str(k): v for k, v in ordered}


@classmethod
def _v702_r39_discovery_lines(cls):
    with cls._lock:
        rows = list(cls._discovery_by_symbol.values())
    rows.sort(key=lambda x: (float(x.get("projected", -1.0)), float(x.get("reviewed", -1.0)), float(x.get("ts", 0.0))), reverse=True)
    out = []
    for x in rows[:V702_R28_TELEGRAM_DIGEST_TOP_DISCOVERY]:
        ctx = str(x.get("context", "?")).replace("\n", " ")
        out.append(
            f"• {_v702_r39_escape_digest_text(x.get('symbol', 'UNATTRIBUTED'))} "
            f"{_v702_r39_escape_digest_text(x.get('strategy', '?'))} "
            f"P={float(x.get('projected', -1.0)):.1f} R={float(x.get('reviewed', -1.0)):.1f} "
            f"HTF={float(x.get('htf', -1.0)):.1f} tier={_v702_r39_escape_digest_text(x.get('tier', '?'))} "
            f"ctx={_v702_r39_escape_digest_text(ctx)}"
        )
    return out or ["• none"]


@classmethod
def _v702_r39_block_lines(cls):
    with cls._lock:
        rows = list(cls._selected_blocks)
    out = []
    for raw in rows[:V702_R28_TELEGRAM_DIGEST_TOP_BLOCKS]:
        plain = cls._strip(str(raw or ""))
        match = re.search(r"Selected\s*→\s*Builder\s+BLOCK\s+([^\s/<>|]{1,64}/USDT)", plain, flags=re.IGNORECASE | re.UNICODE)
        symbol = _v702_r39_normalize_spot_symbol(match.group(1)) if match else None
        root = cls._text(r"root=([^\s]+)", plain, "?")
        stage = cls._text(r"stage=([^\s]+)", plain, "?")
        reason = cls._text(r"reason=([^\n]+)", plain, "?")
        out.append(f"• {_v702_r39_escape_digest_text(symbol or 'UNATTRIBUTED')} root={_v702_r39_escape_digest_text(root)} stage={_v702_r39_escape_digest_text(stage)} reason={_v702_r39_escape_digest_text(reason[:120])}")
    return out or ["• none"]


@classmethod
def _v702_r39_selected_route_summary(cls):
    """Expose only a fresh active-cycle blocker without mangling symbol names."""
    try:
        rec = STATS.get("v702_selected_route_last")
        if not isinstance(rec, dict):
            return "none"
        cycle_id = int(STATS.get("v681_runtime_cycle_id", 0) or 0)
        rec_cycle = int(rec.get("cycle_id", 0) or 0)
        if cycle_id <= 0 or rec_cycle != cycle_id:
            return "none"
        symbol = _v702_r39_normalize_spot_symbol(rec.get("symbol"))
        if not symbol:
            symbol = "UNATTRIBUTED"
            STATS["v702_digest_selected_route_symbol_unattributed"] = int(STATS.get("v702_digest_selected_route_symbol_unattributed", 0) or 0) + 1
        stage = re.sub(r"[^A-Za-z0-9_.:-]", "", str(rec.get("stage", "unknown") or "unknown"))[:48]
        reason = re.sub(r"[|\r\n]+", " ", str(rec.get("reason", "") or "")).strip()[:150]
        try:
            age = max(0.0, float(WALL_NOW()) - float(rec.get("ts", WALL_NOW()) or WALL_NOW()))
            age_text = f" age={age:.0f}s"
        except Exception:
            age_text = " age=?"
        return f"{_v702_r39_escape_digest_text(symbol)}:{stage}:{_v702_r39_escape_digest_text(reason or 'no_detail')}{age_text}"[:240]
    except Exception:
        return "unavailable"


@classmethod
def _v702_r39_shadow_lines(cls):
    with cls._lock:
        rows = list(cls._shadow_events)
    out = []
    for raw in rows[:V702_R28_TELEGRAM_DIGEST_TOP_SHADOW]:
        plain = cls._strip(str(raw or ""))
        match = re.search(r"(?:^|\n)\s*([^\s/<>|]{1,64}/USDT)\s*\|", plain, flags=re.IGNORECASE | re.UNICODE)
        symbol = _v702_r39_normalize_spot_symbol(match.group(1)) if match else None
        event = cls._text(r"Event:\s*([^\n]+)", plain, "?")
        mfe = cls._text(r"MFE:\s*([^\n]+)", plain, "?")
        mae = cls._text(r"MAE:\s*([^\n]+)", plain, "?")
        out.append(f"• {_v702_r39_escape_digest_text(symbol or 'UNATTRIBUTED')} {_v702_r39_escape_digest_text(event)} MFE={_v702_r39_escape_digest_text(mfe)} MAE={_v702_r39_escape_digest_text(mae)}")
    return out or ["• none"]


