_V702_CF_SHADOW_RANK_HOOK_INSTALLED = False
_V702_CF_SHADOW_IO_TASKS = set()
_V702_CF_SHADOW_IO_TASKS_LOCK = threading.Lock()
_V702_CF_SHADOW_CAPTURE_STATS_LOCK = threading.Lock()


def _v702_cf_shadow_capture_lane(fn, args):
    try:
        if getattr(fn, "__name__", "") == "record_candidate" and len(args) > 1:
            return str(args[1] or "").strip().upper()
    except Exception:
        return ""
    return ""


def _v702_cf_shadow_note_policy_reject_capture(fn, args, value=None, error=False, dropped=False):
    """Thread-safe outcome counters for raw policy/HTF reject observation lanes."""
    lane = _v702_cf_shadow_capture_lane(fn, args)
    prefixes = {
        "BEARISH_POLICY_REJECT_OBSERVATION": "v702_cf_shadow_policy_reject",
        "HTF_POLICY_REJECT_OBSERVATION": "v702_cf_shadow_htf_reject",
    }
    prefix = prefixes.get(lane)
    if not prefix:
        return
    with _V702_CF_SHADOW_CAPTURE_STATS_LOCK:
        if dropped:
            key = prefix + "_backpressure_drops"
        elif error:
            key = prefix + "_capture_errors"
        elif bool(value):
            key = prefix + "_capture_stored"
        else:
            key = prefix + "_capture_not_stored"
        STATS[key] = int(STATS.get(key, 0) or 0) + 1


def _v702_cf_shadow_submit(fn, *args, **kwargs):
    """Bounded async offload for non-authoritative SQLite shadow operations."""
    if not callable(fn):
        return None
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        # Startup/validation callers outside an event loop are rare and already
        # serial; production scan callers always use the worker-thread path below.
        try:
            _value = fn(*args, **kwargs)
            _v702_cf_shadow_note_policy_reject_capture(fn, args, value=_value)
            return _value
        except Exception as exc:
            _v702_cf_shadow_note_policy_reject_capture(fn, args, error=True)
            STATS["v702_cf_shadow_process_errors"] = int(STATS.get("v702_cf_shadow_process_errors", 0) or 0) + 1
            logger.debug("[V702-CF-SHADOW] synchronous fallback suppressed: %s", exc)
            return None
    try:
        _cap = int(max(8, min(64, float(CONFIG.get("V702_CF_SHADOW_MAX_PENDING_IO", 16) or 16))))
    except Exception:
        _cap = 16
    with _V702_CF_SHADOW_IO_TASKS_LOCK:
        if len(_V702_CF_SHADOW_IO_TASKS) >= _cap:
            STATS["v702_cf_shadow_io_backpressure_drops"] = int(STATS.get("v702_cf_shadow_io_backpressure_drops", 0) or 0) + 1
            _v702_cf_shadow_note_policy_reject_capture(fn, args, dropped=True)
            return None
        async def _run_shadow_io():
            return await asyncio.to_thread(fn, *args, **kwargs)
        task = loop.create_task(_run_shadow_io(), name="v702-cf-shadow-io")
        _V702_CF_SHADOW_IO_TASKS.add(task)
    def _finish_shadow_io(done):
        with _V702_CF_SHADOW_IO_TASKS_LOCK:
            _V702_CF_SHADOW_IO_TASKS.discard(done)
            _pending_count = len(_V702_CF_SHADOW_IO_TASKS)
        STATS["v702_cf_shadow_io_pending"] = _pending_count
        try:
            value = done.result()
            _v702_cf_shadow_note_policy_reject_capture(fn, args, value=value)
            if isinstance(value, dict) and getattr(fn, "__name__", "") == "process_market_data":
                STATS["v702_cf_shadow_last_cycle"] = dict(value)
        except asyncio.CancelledError:
            _v702_cf_shadow_note_policy_reject_capture(fn, args, error=True)
        except Exception as exc:
            _v702_cf_shadow_note_policy_reject_capture(fn, args, error=True)
            STATS["v702_cf_shadow_process_errors"] = int(STATS.get("v702_cf_shadow_process_errors", 0) or 0) + 1
            logger.debug("[V702-CF-SHADOW] worker I/O suppressed: %s", exc)
    task.add_done_callback(_finish_shadow_io)
    STATS["v702_cf_shadow_io_pending"] = len(_V702_CF_SHADOW_IO_TASKS)
    return task
try:
    from v702_counterfactual_shadow import V702CounterfactualShadow as _V702CounterfactualShadow
    _v702_cf_db_path = str(CONFIG.get("DB_PATH", "./unified_scalper.db") or "./unified_scalper.db")
    _v702_cf_parent = os.path.dirname(os.path.abspath(_v702_cf_db_path))
    _V702_CF_SHADOW = _V702CounterfactualShadow(
        db_path=_v702_cf_db_path,
        report_dir=os.path.join(_v702_cf_parent, "reports"),
        config_getter=lambda: CONFIG,
    )

    _V702_CF_ORIGINAL_PREQUAL = globals().get("_v453_prequalify")
    if callable(_V702_CF_ORIGINAL_PREQUAL) and not getattr(_V702_CF_ORIGINAL_PREQUAL, "_v702_cf_shadow_wrapped", False):
        def _v702_cf_shadow_prequal_wrapper(r, snap_by_symbol):
            verdict = _V702_CF_ORIGINAL_PREQUAL(r, snap_by_symbol)
            try:
                if (not bool(CONFIG.get("V702_CF_SHADOW_ENABLE", True))
                        or bool(globals().get("_V699_VALIDATE_ONLY_REQUEST", False))
                        or _V702_CF_SHADOW is None):
                    return verdict
                ok, reason = verdict if isinstance(verdict, tuple) and len(verdict) >= 2 else (bool(verdict), "unknown")
                candidate = getattr(r, "candidate", r)
                symbol = str(getattr(candidate, "symbol", "") or "")
                snap = (snap_by_symbol or {}).get(symbol) or {}
                if not isinstance(snap, dict):
                    snap = {}
                forbidden_fn = globals().get("_v587_is_forbidden_coin")
                if callable(forbidden_fn):
                    try:
                        if bool(forbidden_fn(symbol)[0]):
                            return verdict
                    except Exception:
                        # Research capture fails closed, but canonical decision is untouched.
                        return verdict
                if ok:
                    # Separate currently admitted NEUTRAL HTF-floor relief from a stricter
                    # baseline cohort so its measured outcome is not blended with baseline.
                    try:
                        ctx_pass = _v455_prequal_context(candidate, snap) if callable(globals().get("_v455_prequal_context")) else {}
                        regime_pass = str(snap.get("macro_regime", snap.get("regime", getattr(candidate, "macro_regime", ""))) or "").upper()
                        mode_pass = str(getattr(candidate, "strategy_mode", "") or "").upper()
                        strength_raw_pass = (ctx_pass or {}).get("htf_strength", snap.get("htf_strength"))
                        if strength_raw_pass is None:
                            fs_pass = getattr(candidate, "features_snapshot", {}) or {}
                            strength_raw_pass = fs_pass.get("htf_strength") if isinstance(fs_pass, dict) else None
                        strength_pass = float(strength_raw_pass) if strength_raw_pass is not None else None
                        meta_pass = CanonicalStrategyPolicyRegistry.get(mode_pass) if callable(getattr(CanonicalStrategyPolicyRegistry, "get", None)) else None
                        strict_floor_pass = float((meta_pass or {}).get("min_htf_strength_non_bearish", 55.0))
                        effective_floor_pass = (ctx_pass or {}).get("effective_htf_floor") or (ctx_pass or {}).get("family_htf_floor") or snap.get("family_htf_floor")
                        if effective_floor_pass is None and regime_pass == "NEUTRAL" and callable(globals().get("_v453_effective_htf_floor")):
                            effective_floor_pass = _v453_effective_htf_floor(regime_pass, strict_floor_pass)
                        if effective_floor_pass is None:
                            effective_floor_pass = strict_floor_pass
                        effective_floor_pass = float(effective_floor_pass)
                        if (regime_pass == "NEUTRAL" and strength_pass is not None
                                and effective_floor_pass <= strength_pass < strict_floor_pass):
                            _v702_cf_shadow_submit(_V702_CF_SHADOW.record_candidate, candidate, "CURRENT_HTF_RELIEF_PASS", "current_neutral_htf_relief_admit", snap,
                                                              htf_strength=strength_pass, htf_floor=effective_floor_pass)
                        else:
                            _v702_cf_shadow_submit(_V702_CF_SHADOW.record_candidate, candidate, "BASELINE_PASS", "prequal_pass",
                                                              htf_strength=strength_pass, htf_floor=strict_floor_pass)
                    except Exception as _cf_pass_exc:
                        STATS["v702_cf_shadow_baseline_capture_errors"] = int(STATS.get("v702_cf_shadow_baseline_capture_errors", 0) or 0) + 1
                        logger.debug("[V702-CF-SHADOW] baseline attribution skipped: %s", _cf_pass_exc)
                elif str(reason) == "htf.family_htf_strength_below_floor":
                    try:
                        ctx = _v455_prequal_context(candidate, snap) if callable(globals().get("_v455_prequal_context")) else {}
                        regime = str(snap.get("macro_regime", snap.get("regime", getattr(candidate, "macro_regime", ""))) or "").upper()
                        local_regime = str(snap.get("local_regime", getattr(candidate, "local_regime", "")) or "").upper()
                        mode = str(getattr(candidate, "strategy_mode", "") or "").upper()
                        family = str(getattr(candidate, "family", "") or mode).upper()
                        raw_strength = (ctx or {}).get("htf_strength", snap.get("htf_strength"))
                        if raw_strength is None:
                            fs = getattr(candidate, "features_snapshot", {}) or {}
                            raw_strength = fs.get("htf_strength") if isinstance(fs, dict) else None
                        if raw_strength is None and callable(globals().get("_v689_resolve_htf_strength")):
                            try:
                                raw_strength = _v689_resolve_htf_strength(symbol, snap, candidate)[0]
                            except Exception:
                                raw_strength = None
                        strength = float(raw_strength) if raw_strength is not None else None
                        meta = CanonicalStrategyPolicyRegistry.get(mode) if callable(getattr(CanonicalStrategyPolicyRegistry, "get", None)) else None
                        base_floor = float((meta or {}).get("min_htf_strength_non_bearish", 55.0))
                        # Reproduce the canonical floor calculation for attribution only.
                        floor_val = (ctx or {}).get("effective_htf_floor") or (ctx or {}).get("family_htf_floor") or snap.get("family_htf_floor")
                        if floor_val is None and regime == "NEUTRAL" and callable(globals().get("_v453_effective_htf_floor")):
                            floor_val = _v453_effective_htf_floor(regime, base_floor)
                        if floor_val is None:
                            floor_val = base_floor
                        floor_val = float(floor_val)
                        # Broad raw HTF-reject outcome capture complements the
                        # existing narrow HTF_RELIEF near-miss lane. It never
                        # reruns the floor with a lower threshold or changes Prequal.
                        side_htf = str(getattr(candidate, "side", "") or "").strip().lower()
                        if (bool(CONFIG.get("V702_CF_SHADOW_HTF_REJECT_OBSERVE_ENABLE", True))
                                and strength is not None and side_htf in {"long", "buy"}
                                and regime in {"BULLISH", "NEUTRAL", "BEARISH"}):
                            with _V702_CF_SHADOW_CAPTURE_STATS_LOCK:
                                STATS["v702_cf_shadow_htf_reject_capture_attempts"] = int(
                                    STATS.get("v702_cf_shadow_htf_reject_capture_attempts", 0) or 0) + 1
                            htf_shadow_snapshot = dict(snap)
                            htf_shadow_snapshot.update({
                                "macro_regime": regime, "local_regime": local_regime,
                                "htf_strength": strength, "family_htf_floor": floor_val,
                                "family": family, "side": side_htf,
                                "policy_allowed": False, "policy_reason": str(reason),
                            })
                            _v702_cf_shadow_submit(
                                _V702_CF_SHADOW.record_candidate, candidate,
                                "HTF_POLICY_REJECT_OBSERVATION", str(reason), htf_shadow_snapshot,
                                htf_strength=strength, htf_floor=floor_val,
                            )
                        relief = max(0.0, min(5.0, float(CONFIG.get("V702_CF_SHADOW_HTF_RELIEF_POINTS", 3.0) or 3.0)))
                        if strength is not None and floor_val - relief <= strength < floor_val:
                            _v702_cf_shadow_submit(_V702_CF_SHADOW.record_candidate, candidate, "HTF_RELIEF", str(reason), snap,
                                                              htf_strength=strength, htf_floor=floor_val)
                    except Exception as _cf_htf_exc:
                        STATS["v702_cf_shadow_htf_capture_errors"] = int(STATS.get("v702_cf_shadow_htf_capture_errors", 0) or 0) + 1
                        logger.debug("[V702-CF-SHADOW] HTF attribution skipped: %s", _cf_htf_exc)
                elif str(reason) == "liquidity.below_tier":
                    try:
                        qv0 = snap.get("quote_vol_24h")
                        if qv0 is None:
                            fs = getattr(candidate, "features_snapshot", {}) or {}
                            qv0 = fs.get("quote_vol_24h") if isinstance(fs, dict) else None
                        qv = float(qv0) if qv0 is not None else None
                        mid_min = max(0.0, float(CONFIG.get("V702_CF_SHADOW_MID_MIN_QUOTE_VOLUME", 1_000_000.0) or 1_000_000.0))
                        core_floor = max(mid_min, float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 3_000_000.0) or 3_000_000.0))
                        if qv is not None and mid_min <= qv < core_floor:
                            _v702_cf_shadow_submit(_V702_CF_SHADOW.record_candidate, candidate, "MID_TIER_COUNTERFACTUAL", str(reason), snap)
                    except Exception as _cf_liq_exc:
                        STATS["v702_cf_shadow_liquidity_capture_errors"] = int(STATS.get("v702_cf_shadow_liquidity_capture_errors", 0) or 0) + 1
                        logger.debug("[V702-CF-SHADOW] liquidity attribution skipped: %s", _cf_liq_exc)
                elif str(reason).startswith("family_regime_disallowed.macro"):
                    # Raw Bearish policy-reject observation is intentionally independent of
                    # the stricter A48 LSR cohort. It captures long candidates for outcome
                    # measurement only; it does not rerun Prequal under a synthetic policy.
                    try:
                        ctx_shadow = _v455_prequal_context(candidate, snap) if callable(globals().get("_v455_prequal_context")) else {}
                        ctx_shadow = ctx_shadow if isinstance(ctx_shadow, dict) else {}
                        fs_shadow = getattr(candidate, "features_snapshot", {}) or {}
                        fs_shadow = fs_shadow if isinstance(fs_shadow, dict) else {}
                        family_shadow = str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()
                        regime_shadow = str(snap.get("macro_regime") or snap.get("regime") or ctx_shadow.get("macro_regime") or ctx_shadow.get("regime") or getattr(candidate, "macro_regime", "")).upper()
                        severity_shadow = str(snap.get("bearish_severity") or snap.get("macro_severity") or ctx_shadow.get("severity") or getattr(candidate, "bearish_severity", "") or fs_shadow.get("bearish_severity") or fs_shadow.get("macro_severity") or "").upper()
                        raw_htf_shadow = (ctx_shadow.get("htf_strength") if ctx_shadow else None)
                        if raw_htf_shadow is None:
                            raw_htf_shadow = snap.get("htf_strength", snap.get("v4513_htf_strength", fs_shadow.get("htf_strength")))
                        htf_shadow = float(raw_htf_shadow) if raw_htf_shadow is not None else None
                        raw_volume_shadow = snap.get("volume_ratio", fs_shadow.get("volume_ratio"))
                        volume_shadow = float(raw_volume_shadow) if raw_volume_shadow is not None else None
                        raw_quote_shadow = snap.get("quote_vol_24h", snap.get("quoteVolume", fs_shadow.get("quote_vol_24h")))
                        quote_shadow = float(raw_quote_shadow) if raw_quote_shadow is not None else None
                        side_shadow = str(getattr(candidate, "side", "") or "").strip().lower()
                        enriched_shadow = dict(snap)
                        enriched_shadow.update({
                            "macro_regime": regime_shadow, "bearish_severity": severity_shadow,
                            "volume_ratio": volume_shadow, "quote_vol_24h": quote_shadow,
                            "htf_strength": htf_shadow, "family": family_shadow,
                            "side": side_shadow, "policy_allowed": False,
                            "policy_reason": str(reason),
                            "allowed_regimes": ctx_shadow.get("allowed_regimes", snap.get("allowed_regimes", ())),
                        })
                        if (bool(CONFIG.get("V702_CF_SHADOW_POLICY_REJECT_OBSERVE_ENABLE", True))
                                and regime_shadow == "BEARISH" and side_shadow in {"long", "buy"}):
                            with _V702_CF_SHADOW_CAPTURE_STATS_LOCK:
                                STATS["v702_cf_shadow_policy_reject_capture_attempts"] = int(
                                    STATS.get("v702_cf_shadow_policy_reject_capture_attempts", 0) or 0) + 1
                            _v702_cf_shadow_submit(
                                _V702_CF_SHADOW.record_candidate, candidate,
                                "BEARISH_POLICY_REJECT_OBSERVATION", str(reason), enriched_shadow,
                                htf_strength=htf_shadow,
                            )
                        if (bool(CONFIG.get("V702_A48_BEARISH_NORMAL_SHADOW_ONLY", True))
                                and family_shadow == str(CONFIG.get("V702_A48_BEARISH_SHADOW_FAMILY", "LIQUIDITY_SWEEP_REVERSAL")).upper()
                                and regime_shadow == "BEARISH"
                                and side_shadow in {"long", "buy"}
                                and severity_shadow in {"NORMAL", "BEARISH_NORMAL"}
                                and htf_shadow is not None and htf_shadow >= float(CONFIG.get("V702_A48_BEARISH_SHADOW_MIN_HTF_STRENGTH", 47.0))
                                and volume_shadow is not None and volume_shadow >= float(CONFIG.get("V702_A48_BEARISH_SHADOW_VOLUME_FLOOR_RATIO", 1.4))
                                and quote_shadow is not None and quote_shadow >= float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 3_000_000.0))):
                            _v702_cf_shadow_submit(
                                _V702_CF_SHADOW.record_candidate, candidate, "BEARISH_NORMAL_LSR", str(reason), enriched_shadow,
                                htf_strength=htf_shadow, htf_floor=float(CONFIG.get("V702_A48_BEARISH_SHADOW_MIN_HTF_STRENGTH", 47.0)),
                            )
                    except Exception as _cf_bearish_shadow_exc:
                        STATS["v702_a48_bearish_shadow_capture_errors"] = int(STATS.get("v702_a48_bearish_shadow_capture_errors", 0) or 0) + 1
                        logger.debug("[V702-A48] bearish-normal shadow capture skipped: %s", _cf_bearish_shadow_exc)
            except Exception as _cf_exc:
                # Shadow errors must never alter or replace the canonical verdict.
                STATS["v702_cf_shadow_capture_errors"] = int(STATS.get("v702_cf_shadow_capture_errors", 0) or 0) + 1
                logger.debug("[V702-CF-SHADOW] capture suppressed: %s", _cf_exc)
            return verdict
        _v702_cf_shadow_prequal_wrapper._v702_cf_shadow_wrapped = True
        _v702_cf_shadow_prequal_wrapper._v702_cf_shadow_original = _V702_CF_ORIGINAL_PREQUAL
        _V702_CF_SHADOW_PREQUAL_WRAPPER = _v702_cf_shadow_prequal_wrapper
        globals()["_v453_prequalify"] = _v702_cf_shadow_prequal_wrapper
        _V702_CF_SHADOW_PREQUAL_HOOK_INSTALLED = True

    _V702_CF_ORIGINAL_RANK_AND_SELECT = getattr(globals().get("GlobalOpportunityBrain"), "rank_and_select", None)
    if callable(_V702_CF_ORIGINAL_RANK_AND_SELECT):
        def _v702_cf_shadow_rank_wrapper(market_data_map):
            try:
                result = _V702_CF_ORIGINAL_RANK_AND_SELECT(market_data_map)
            finally:
                try:
                    if (bool(CONFIG.get("V702_CF_SHADOW_ENABLE", True))
                            and not bool(globals().get("_V699_VALIDATE_ONLY_REQUEST", False))
                            and _V702_CF_SHADOW is not None):
                        _v702_cf_shadow_submit(_V702_CF_SHADOW.process_market_data, market_data_map)
                except Exception as _cf_proc_exc:
                    STATS["v702_cf_shadow_process_errors"] = int(STATS.get("v702_cf_shadow_process_errors", 0) or 0) + 1
                    logger.debug("[V702-CF-SHADOW] candle processing suppressed: %s", _cf_proc_exc)
            return result
        # The original attribute is class-bound; wrapping its already-bound callable avoids
        # introducing a second implicit cls argument.
        setattr(GlobalOpportunityBrain, "rank_and_select", staticmethod(_v702_cf_shadow_rank_wrapper))
        _V702_CF_SHADOW_RANK_HOOK_INSTALLED = True

    _v702_cf_selftest = _V702_CF_SHADOW.self_test()
    STATS["v702_counterfactual_shadow_self_test"] = _v702_cf_selftest
    STATS["v702_counterfactual_shadow_installed"] = bool(
        _v702_cf_selftest.get("pass") and _V702_CF_SHADOW_PREQUAL_HOOK_INSTALLED and _V702_CF_SHADOW_RANK_HOOK_INSTALLED
    )
    logger.info("[V702-CF-SHADOW] installed=%s enabled=%s prequal_hook=%s candle_hook=%s db=%s; no orders",
                STATS["v702_counterfactual_shadow_installed"], bool(CONFIG.get("V702_CF_SHADOW_ENABLE", True)),
                _V702_CF_SHADOW_PREQUAL_HOOK_INSTALLED, _V702_CF_SHADOW_RANK_HOOK_INSTALLED, _v702_cf_db_path)
except Exception as _v702_cf_install_exc:
    _V702_CF_SHADOW_INSTALL_ERROR = f"{type(_v702_cf_install_exc).__name__}:{_v702_cf_install_exc}"
    STATS["v702_counterfactual_shadow_installed"] = False
    STATS["v702_counterfactual_shadow_install_error"] = _V702_CF_SHADOW_INSTALL_ERROR
    logger.critical("[V702-CF-SHADOW] installation failed; canonical trade gates remain untouched: %s", _V702_CF_SHADOW_INSTALL_ERROR)

