def _v702_a9_note_orderbook_cause(symbol: str, cause: str, detail: Optional[Dict[str, Any]] = None) -> None:
    """Classify order-book data-path failures independently; observability only."""
    try:
        key = str(cause or "unknown").strip().lower()[:64]
        counts = STATS.setdefault("v702_a9_orderbook_cause_counts", {})
        if not isinstance(counts, dict):
            counts = {}
            STATS["v702_a9_orderbook_cause_counts"] = counts
        counts[key] = int(counts.get(key, 0) or 0) + 1
        if len(counts) > 32:
            counts = dict(sorted(counts.items(), key=lambda kv: int(kv[1] or 0), reverse=True)[:24])
            STATS["v702_a9_orderbook_cause_counts"] = counts
        safe_detail = {}
        for field in ("source", "status", "age_sec", "spread_pct", "error", "api_error_type"):
            value = (detail or {}).get(field) if isinstance(detail, dict) else None
            if value is None:
                continue
            if field in {"age_sec", "spread_pct"}:
                try:
                    fv = float(value)
                    if math.isfinite(fv): safe_detail[field] = round(fv, 4)
                except Exception:
                    pass
            else:
                safe_detail[field] = str(value)[:110]
        STATS["v702_a9_orderbook_cause_last"] = {
            "symbol": str(symbol or "").upper()[:40], "cause": key,
            "detail": safe_detail, "ts": float(WALL_NOW()),
        }
    except Exception:
        _v647_record_suppressed_exception()


def _v702_a9_ob_status_store():
    book = globals().setdefault("_V702_A9_ORDERBOOK_STATUS_BY_SYMBOL", {})
    if not isinstance(book, dict):
        book = {}
        globals()["_V702_A9_ORDERBOOK_STATUS_BY_SYMBOL"] = book
    now = float(WALL_NOW())
    for key, value in list(book.items()):
        try:
            if now - float((value or {}).get("ts", 0.0) or 0.0) > 1800.0:
                book.pop(key, None)
        except Exception:
            book.pop(key, None)
    return book


def _v702_a9_orderbook_levels_valid(ob: Any) -> Tuple[bool, str, Optional[Dict[str, float]]]:
    """Validate exact top-book levels before attaching any fetched market fact."""
    if not isinstance(ob, dict):
        return False, "response_not_mapping", None
    bids = list(ob.get("bids", []) or [])[:10]
    asks = list(ob.get("asks", []) or [])[:10]
    if not bids or not asks:
        return False, "empty_side", None
    try:
        for level in bids + asks:
            if not isinstance(level, (list, tuple)) or len(level) < 2:
                return False, "malformed_level", None
            px, qty = float(level[0]), float(level[1])
            if not (math.isfinite(px) and math.isfinite(qty) and px > 0.0 and qty >= 0.0):
                return False, "nonfinite_or_nonpositive_level", None
        bid_prices = [float(x[0]) for x in bids[:5]]
        ask_prices = [float(x[0]) for x in asks[:5]]
        if any(bid_prices[i] < bid_prices[i + 1] for i in range(len(bid_prices) - 1)):
            return False, "bids_not_descending", None
        if any(ask_prices[i] > ask_prices[i + 1] for i in range(len(ask_prices) - 1)):
            return False, "asks_not_ascending", None
    except Exception:
        return False, "level_parse_error", None
    metrics = _v703_r35_orderbook_metrics(ob) if callable(globals().get("_v703_r35_orderbook_metrics")) else None
    if not isinstance(metrics, dict):
        return False, "metrics_unverifiable", None
    if not all(math.isfinite(float(metrics.get(k, float("nan")))) for k in ("best_bid", "best_ask", "spread_pct", "depth_total", "imbalance")):
        return False, "metrics_nonfinite", None
    if float(metrics["best_ask"]) < float(metrics["best_bid"]) or float(metrics["depth_total"]) <= 0.0:
        return False, "crossed_or_zero_depth", None
    if sum(float(x[0]) * float(x[1]) for x in bids[:5]) <= 0.0:
        return False, "bid_notional_unavailable", None
    return True, "valid", metrics


async def _v702_a9_prefetch_micro_orderbooks(exchange, market_data_map: Any) -> Dict[str, Any]:
    """Bounded, pre-prequal MEXC order-book capture for A7 MICRO candidates.

    Fetch status is propagated with the exact snapshot. No quality threshold is
    relaxed here; spread, depth, imbalance, structure, volume, chase and fee gates
    remain authoritative downstream. When fetch budget is exhausted, we fail closed.
    """
    out = {"eligible": 0, "attempted": 0, "fetched_fresh": 0, "reused_fresh": 0,
           "api_errors": 0, "timeouts": 0, "empty_or_invalid": 0, "deferred_budget": 0,
           "forbidden_skips": 0, "freshness_refetches": 0, "batch_timed_out": 0,
           "task_errors": 0, "skip_reason": ""}
    if not bool(CONFIG.get("V702_A9_ORDERBOOK_PREFETCH_ENABLE", True)):
        out["disabled"] = 1
        out["skip_reason"] = "feature_disabled"
        return out
    if not isinstance(market_data_map, dict) or not market_data_map:
        out["empty_market_map"] = 1
        out["skip_reason"] = "empty_market_map"
        return out
    status_store = _v702_a9_ob_status_store()
    md_by_symbol = {str(k or "").strip().upper(): v for k, v in market_data_map.items() if isinstance(v, dict)}
    forbidden_bases = set(_V702_PREDECLARED_FORBIDDEN_BASES)
    min_qv = float(CONFIG.get("V702_A7_MICRO_HANDOFF_MIN_QUOTE_VOLUME", 1_000_000.0))
    max_qv = float(CONFIG.get("V702_A7_MICRO_HANDOFF_MAX_QUOTE_VOLUME_EXCLUSIVE", 3_000_000.0))
    max_age = max(1.0, float(CONFIG.get("V702_A9_ORDERBOOK_PREFETCH_MAX_AGE_SEC", 15.0)))
    now = float(WALL_NOW())
    pending = []

    def _qv_of(md):
        for key in ("quote_vol_24h", "quote_volume_24h", "quoteVolume"):
            try:
                if md.get(key) is not None:
                    value = float(md.get(key))
                    if math.isfinite(value): return value
            except Exception:
                pass
        ticker = md.get("ticker") if isinstance(md.get("ticker"), dict) else {}
        try:
            value = float(ticker.get("quoteVolume"))
            return value if math.isfinite(value) else None
        except Exception:
            return None

    def _status(sym, status, **extra):
        item = {"status": str(status), "ts": float(WALL_NOW()), **extra}
        status_store[str(sym).upper()] = item
        _status_md = md_by_symbol.get(str(sym or "").strip().upper())
        if isinstance(_status_md, dict):
            _status_md["v702_a9_orderbook_prefetch_status"] = str(status)
            _status_md["v702_a9_orderbook_status_ts"] = float(item["ts"])
            if item.get("book_ts") is not None:
                _status_md["v702_a9_orderbook_prefetch_ts"] = item.get("book_ts")
            if item.get("error"):
                _status_md["v702_a9_orderbook_status_error"] = str(item.get("error"))[:180]
            else:
                _status_md.pop("v702_a9_orderbook_status_error", None)
        if len(status_store) > 2048:
            for k, _v in sorted(status_store.items(), key=lambda kv: float((kv[1] or {}).get("ts", 0.0) or 0.0))[:512]:
                status_store.pop(k, None)
        return item

    def _attach(md, sym, ob, metrics, status, captured_ts=None):
        checked_ts = float(WALL_NOW())
        # `captured_ts` is the timestamp of the original book capture, not this
        # validation pass. Reusing a recent book must never make old market data
        # look newly fetched. Fresh API responses use checked_ts as capture time.
        book_ts = checked_ts if captured_ts is None else float(captured_ts)
        if book_ts > 1e12:
            book_ts /= 1000.0
        age_at_check = checked_ts - book_ts
        if not math.isfinite(book_ts) or age_at_check < -2.0:
            raise ValueError("orderbook_capture_timestamp_invalid_or_future")
        if age_at_check > float(CONFIG.get("V702_A9_ORDERBOOK_PREFETCH_MAX_AGE_SEC", 15.0)):
            raise ValueError("orderbook_capture_timestamp_stale")
        exact = {"bids": list(ob.get("bids", []) or []), "asks": list(ob.get("asks", []) or [])}
        # Use the same precise object for every handoff alias; zero depth_ratio asks
        # the existing hard validator to derive depth from the exact book, not old metadata.
        md["orderbook"] = exact
        md["depth"] = exact
        md["_v703_route_score_orderbook"] = exact
        md["_v703_route_score_orderbook_symbol"] = str(sym).upper()
        md["spread_pct"] = float(metrics["spread_pct"])
        md["spread_ts"] = book_ts
        md["orderbook_ts"] = book_ts
        md["book_ts"] = book_ts
        md["depth_ts"] = book_ts
        md["v703_route_orderbook_captured_ts"] = book_ts
        md["v703_route_orderbook_source"] = "V702_A9_PREFETCH_EXACT_BOOK"
        md["v702_a9_orderbook_prefetch_status"] = str(status)
        md["v702_a9_orderbook_prefetch_ts"] = book_ts
        md["v702_a9_orderbook_checked_ts"] = checked_ts
        md["v702_a9_orderbook_metrics"] = dict(metrics)
        md["orderbook_imbalance"] = float(metrics["imbalance"])
        md["depth_ratio"] = 0.0
        md["ticker"] = {**(md.get("ticker") if isinstance(md.get("ticker"), dict) else {}),
                        "bid": float(metrics["best_bid"]), "ask": float(metrics["best_ask"])}
        _status(sym, status, source="V702_A9_PREFETCH_EXACT_BOOK",
                spread_pct=metrics["spread_pct"], book_ts=book_ts, checked_ts=checked_ts)

    for sym, raw_md in list(market_data_map.items()):
        md = raw_md if isinstance(raw_md, dict) else None
        name = str(sym or "").strip().upper()
        if md is None or not name.endswith("/USDT") or name.count("/") != 1:
            continue
        base = name.split("/", 1)[0]
        qv = _qv_of(md)
        if qv is None or not (math.isfinite(qv) and min_qv <= qv < max_qv):
            continue
        if base in forbidden_bases:
            out["forbidden_skips"] += 1
            _status(name, "FORBIDDEN", source="hard_denylist")
            continue
        try:
            check = globals().get("_v587_is_forbidden_coin")
            if callable(check):
                verdict = check(name)
                banned = bool(verdict[0]) if isinstance(verdict, tuple) and verdict else bool(verdict)
                if banned:
                    out["forbidden_skips"] += 1
                    _status(name, "FORBIDDEN", source="canonical_blacklist")
                    continue
        except Exception as exc:
            out["forbidden_skips"] += 1
            _status(name, "BLACKLIST_UNVERIFIABLE", source="canonical_blacklist", error=_v703_route_orderbook_error_token(exc))
            continue
        out["eligible"] += 1
        ob = md.get("orderbook") or md.get("depth") or md.get("_v703_route_score_orderbook")
        valid, validation_reason, metrics = _v702_a9_orderbook_levels_valid(ob)
        ts_value = next((md.get(k) for k in ("orderbook_ts", "book_ts", "depth_ts", "v703_route_orderbook_captured_ts") if md.get(k) is not None), None)
        age = None
        capture_ts = None
        try:
            capture_ts = (float(ts_value) / 1000.0 if float(ts_value) > 1e12 else float(ts_value)) if ts_value is not None else None
            age = (now - capture_ts) if capture_ts is not None else None
        except Exception:
            age = None
            capture_ts = None
        # Freshness is measured from the original capture, never from this reuse.
        # Future-dated snapshots are not trusted; refetch them instead.
        if valid and age is not None and 0.0 <= age <= max_age:
            try:
                _attach(md, name, ob, metrics, "REUSED_FRESH", captured_ts=capture_ts)
                out["reused_fresh"] += 1
                continue
            except Exception:
                out["freshness_refetches"] += 1
        elif valid:
            out["freshness_refetches"] += 1
        pending.append((name, md, qv, validation_reason, age))

    cap = max(1, min(32, int(CONFIG.get("V702_A9_ORDERBOOK_PREFETCH_MAX_SYMBOLS_PER_CYCLE", 24) or 24)))
    if pending:
        cursor = int(STATS.get("v702_a9_orderbook_prefetch_cursor", 0) or 0) % len(pending)
        rotated = pending[cursor:] + pending[:cursor]
        chosen = rotated[:cap]
        deferred = rotated[cap:]
        STATS["v702_a9_orderbook_prefetch_cursor"] = (cursor + max(1, len(chosen))) % max(1, len(pending))
        out["deferred_budget"] += len(deferred)
        for name, _md, _qv, _why, _age in deferred:
            _status(name, "DEFERRED_BUDGET", source="per_cycle_symbol_cap")
        concurrency = max(1, min(12, int(CONFIG.get("V702_A9_ORDERBOOK_PREFETCH_CONCURRENCY", 8) or 8)))
        timeout_sec = max(0.5, min(5.0, float(CONFIG.get("V702_A9_ORDERBOOK_PREFETCH_TIMEOUT_SEC", 2.5))))
        batch_budget = max(1.0, min(10.0, float(CONFIG.get("V702_A9_ORDERBOOK_PREFETCH_BATCH_TIMEOUT_SEC", 6.0))))
        limit = max(5, min(50, int(CONFIG.get("V702_A9_ORDERBOOK_PREFETCH_LIMIT", 20) or 20)))
        sem = asyncio.Semaphore(concurrency)

        async def _one(item):
            name, md, qv, prev_reason, prev_age = item
            out["attempted"] += 1
            _status(name, "FETCHING", source="MEXC.fetch_order_book")
            async with sem:
                try:
                    raw = await asyncio.wait_for(
                        safe_api_call("fetch_ob_a9_prequal_" + name,
                                      lambda _name=name: exchange.fetch_order_book(_name, limit=limit),
                                      retry_safe=True),
                        timeout=timeout_sec,
                    )
                except asyncio.TimeoutError:
                    out["timeouts"] += 1
                    _status(name, "TIMEOUT", source="MEXC.fetch_order_book", error="fetch_timeout")
                    return
                except Exception as exc:
                    out["api_errors"] += 1
                    _status(name, "API_ERROR", source="MEXC.fetch_order_book",
                            error=_v703_route_orderbook_error_token(exc), api_error_type=type(exc).__name__)
                    return
            valid, why, metrics = _v702_a9_orderbook_levels_valid(raw)
            if not valid or metrics is None:
                out["empty_or_invalid"] += 1
                _status(name, "EMPTY_OR_INVALID", source="MEXC.fetch_order_book", error=why)
                return
            _attach(md, name, raw, metrics, "FETCHED_FRESH")
            out["fetched_fresh"] += 1

        tasks = [asyncio.create_task(_one(item)) for item in chosen]
        done, still_pending = await asyncio.wait(tasks, timeout=batch_budget) if tasks else (set(), set())
        if still_pending:
            out["batch_timed_out"] += len(still_pending)
            for task in still_pending:
                task.cancel()
            await asyncio.gather(*still_pending, return_exceptions=True)
        for item, task in zip(chosen, tasks):
            if task in still_pending:
                # Some tasks may have made the request but didn't finish before the
                # batch deadline. Keep this separate from MEXC API errors.
                _status(item[0], "BATCH_TIMEOUT", source="MEXC.fetch_order_book", error="batch_budget_exceeded")
            elif task in done:
                try:
                    task.result()
                except asyncio.CancelledError:
                    out["batch_timed_out"] += 1
                    _status(item[0], "BATCH_TIMEOUT", source="MEXC.fetch_order_book", error="task_cancelled")
                except Exception as exc:
                    out["task_errors"] += 1
                    _status(item[0], "FETCH_TASK_ERROR", source="MEXC.fetch_order_book",
                            error=_v703_route_orderbook_error_token(exc), api_error_type=type(exc).__name__)
    for field in ("eligible", "attempted", "fetched_fresh", "reused_fresh", "api_errors", "timeouts", "empty_or_invalid", "deferred_budget", "forbidden_skips", "freshness_refetches", "batch_timed_out", "task_errors"):
        key = "v702_a9_orderbook_" + field
        STATS[key] = int(STATS.get(key, 0) or 0) + int(out.get(field, 0) or 0)
    return out


def _v702_a9_orderbook_missing_cause(symbol: str, snapshot: Any, features: Any) -> Tuple[str, Dict[str, Any]]:
    """Classify a missing book by the latest source result and true capture age.

    Stale/future timestamps are checked before interpreting a successful fetch as
    a transfer failure. Status events and book-capture timestamps are separate clocks.
    """
    snap = snapshot if isinstance(snapshot, dict) else {}
    fs = features if isinstance(features, dict) else {}
    status_map = _v702_a9_ob_status_store()
    stored = status_map.get(str(symbol or "").upper(), {}) if isinstance(status_map, dict) else {}
    status = str(snap.get("v702_a9_orderbook_prefetch_status") or fs.get("v702_a9_orderbook_prefetch_status") or (stored or {}).get("status", "") or "").upper()
    detail = {"status": status, "source": (stored or {}).get("source", snap.get("v703_route_orderbook_source", ""))}
    max_age = float(CONFIG.get("V702_A9_ORDERBOOK_PREFETCH_MAX_AGE_SEC", 15.0))
    # Preserve the latest attempted fetch's actual failure classification.
    if status in {"API_ERROR", "BLACKLIST_UNVERIFIABLE", "FETCH_TASK_ERROR"}:
        detail["error"] = (stored or {}).get("error", "")
        detail["api_error_type"] = (stored or {}).get("api_error_type", "")
        return ("api_error" if status != "FETCH_TASK_ERROR" else "fetch_task_error"), detail
    if status in {"TIMEOUT", "BATCH_TIMEOUT"}:
        detail["error"] = (stored or {}).get("error", status.lower())
        return "timeout", detail
    if status == "EMPTY_OR_INVALID":
        detail["error"] = (stored or {}).get("error", "")
        return "empty_or_invalid", detail
    if status == "DEFERRED_BUDGET":
        return "not_fetched_budget", detail
    # Check all aliases, not merely the first present field; a conflicting stale
    # alias must not be hidden by a fresh alias elsewhere in the candidate.
    timestamp_sources = []
    for source_name, mapping in (("snapshot", snap), ("features", fs)):
        for key in ("orderbook_ts", "book_ts", "depth_ts", "v703_route_orderbook_captured_ts", "v702_a9_orderbook_prefetch_ts"):
            raw_ts = mapping.get(key)
            if raw_ts is None:
                continue
            try:
                ts = float(raw_ts)
                if ts > 1e12:
                    ts /= 1000.0
                if not math.isfinite(ts):
                    detail["timestamp_source"] = f"{source_name}.{key}"
                    return "invalid_timestamp", detail
                signed_age = float(WALL_NOW()) - ts
                if signed_age < -2.0:
                    detail.update({"age_sec": round(signed_age, 4), "timestamp_source": f"{source_name}.{key}"})
                    return "future_timestamp", detail
                age = max(0.0, signed_age)
                timestamp_sources.append((age, f"{source_name}.{key}"))
            except Exception:
                detail["timestamp_source"] = f"{source_name}.{key}"
                return "invalid_timestamp", detail
    # A missing-book decision is stale if ANY of the purported aliases is stale.
    if timestamp_sources:
        stale = max(timestamp_sources, key=lambda item: item[0])
        detail["age_sec"] = round(stale[0], 4)
        detail["timestamp_source"] = stale[1]
        if stale[0] > max_age:
            return "stale", detail
    # A successful fetch in this candidate without the book payload is a handoff
    # transfer failure only when the original capture itself is still fresh.
    if status in {"FETCHED_FRESH", "REUSED_FRESH"}:
        captured = None
        for candidate in (snap, fs):
            for key in ("orderbook_ts", "book_ts", "depth_ts", "v703_route_orderbook_captured_ts", "v702_a9_orderbook_prefetch_ts"):
                try:
                    raw = candidate.get(key)
                    if raw is not None:
                        captured = float(raw)
                        if captured > 1e12:
                            captured /= 1000.0
                        break
                except Exception:
                    continue
            if captured is not None:
                break
        if captured is None:
            try:
                captured = float((stored or {}).get("book_ts"))
                if captured > 1e12:
                    captured /= 1000.0
            except Exception:
                captured = None
        if captured is not None:
            age = float(WALL_NOW()) - captured
            detail["age_sec"] = round(age, 4)
            if age < -2.0:
                return "future_timestamp", detail
            if age > max_age:
                return "stale", detail
            return "snapshot_not_transferred", detail
        # A status-only record can be old even if its capture timestamp was lost.
        try:
            event_ts = float((stored or {}).get("ts", 0.0) or 0.0)
            status_age = max(0.0, float(WALL_NOW()) - event_ts) if event_ts > 0 else float("inf")
            detail["status_age_sec"] = round(status_age, 4) if math.isfinite(status_age) else None
            if status_age > max_age:
                return "stale", detail
        except Exception:
            return "invalid_timestamp", detail
        return "snapshot_not_transferred", detail
    if timestamp_sources:
        # A recent timestamp with no payload is evidence of a payload lost between
        # candidate construction and Handoff, even if the status label was stripped.
        return "snapshot_not_transferred", detail
    return "not_fetched", detail


def _v702_a8_note_orderbook_block(symbol: str, stage: str, reason: str, context: Optional[Dict[str, Any]] = None) -> None:
    """Bounded, live-epoch-only reason telemetry; never changes a gate decision."""
    try:
        if not bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
            return
        stage_key = str(stage or "unknown").strip().lower()[:24]
        reason_key = str(reason or "unknown").strip().lower()[:72]
        key = f"{stage_key}:{reason_key}"
        counts = STATS.setdefault("v702_a8_orderbook_block_counts", {})
        if not isinstance(counts, dict):
            counts = {}
            STATS["v702_a8_orderbook_block_counts"] = counts
        counts[key] = int(counts.get(key, 0) or 0) + 1
        if len(counts) > 32:
            keep = sorted(counts.items(), key=lambda kv: int(kv[1] or 0), reverse=True)[:24]
            STATS["v702_a8_orderbook_block_counts"] = counts = dict(keep)
        ctx = context if isinstance(context, dict) else {}
        safe_ctx = {}
        for field in ("spread_pct", "depth_ratio", "volume_ratio", "structure_confidence", "structure_quality", "chase_atr"):
            try:
                value = float(ctx.get(field))
                if math.isfinite(value):
                    safe_ctx[field] = round(value, 4)
            except Exception:
                pass
        STATS["v702_a8_orderbook_block_last"] = {
            "symbol": str(symbol or "")[:40].upper(), "stage": stage_key,
            "reason": reason_key, "context": safe_ctx, "ts": float(WALL_NOW()),
        }
    except Exception:
        _v647_record_suppressed_exception()


def _v702_a7_micro_handoff_evidence(candidate, snapshot, tier=None, record=False):
    """Check narrow MICRO-to-Builder handoff prerequisites; never submits an order.

    The 1M–3M quote-volume band is eligible only for allowlisted LONG families,
    a >=70 (and strategy-specific) score, known spread, a passing MICRO book,
    fresh-enough market facts where timestamps exist, and exact fee viability at
    the configured live ticket. All later Builder/PreSend/execution gates remain.
    """
    snap = snapshot if isinstance(snapshot, dict) else {}
    fs0 = getattr(candidate, "features_snapshot", {}) if candidate is not None else {}
    fs = dict(fs0 or {}) if isinstance(fs0, dict) else {}
    sym = str(getattr(candidate, "symbol", "") or snap.get("symbol", "") or "").strip().upper()
    mode = str(getattr(candidate, "strategy_mode", "") or getattr(candidate, "family", "") or "").upper()
    family = str(getattr(candidate, "family", "") or mode).upper()
    reason = "micro_handoff_unverified"
    detail = {"symbol": sym, "family": family, "strategy_mode": mode, "tier": str(tier or "").upper()}
    micro_candidate_key = f"{sym}|{getattr(candidate, 'generated_at_ms', '')}|{mode}"
    now_mono = MONO_NOW()
    seen_before = False
    if record:
        try:
            for k, ts in list(_STS_A7_MICRO_SEEN.items()):
                if now_mono - float(ts or 0.0) > 1800.0:
                    _STS_A7_MICRO_SEEN.pop(k, None)
            seen_before = micro_candidate_key in _STS_A7_MICRO_SEEN
            _STS_A7_MICRO_SEEN[micro_candidate_key] = now_mono
            if len(_STS_A7_MICRO_SEEN) > 2048:
                for k, _ in sorted(_STS_A7_MICRO_SEEN.items(), key=lambda kv: kv[1])[:512]:
                    _STS_A7_MICRO_SEEN.pop(k, None)
            if not seen_before:
                STATS["v702_a7_micro_handoff_checks"] = int(STATS.get("v702_a7_micro_handoff_checks", 0) or 0) + 1
        except Exception:
            pass

    def _finish(ok, why, extra=None):
        out = dict(detail)
        if isinstance(extra, dict):
            out.update(extra)
        out.update({"ok": bool(ok), "reason": str(why), "ts_mono": float(now_mono)})
        if record:
            try:
                if ok:
                    STATS["v702_a7_micro_handoff_passes"] = int(STATS.get("v702_a7_micro_handoff_passes", 0) or 0) + 1
                else:
                    STATS["v702_a7_micro_handoff_blocks"] = int(STATS.get("v702_a7_micro_handoff_blocks", 0) or 0) + 1
                STATS["v702_a7_micro_handoff_last"] = {k: v for k, v in out.items() if k != "ts_mono"}
            except Exception:
                pass
        return bool(ok), str(why), out

    if not bool(CONFIG.get("V702_A7_MICRO_HANDOFF_ENABLE", False)):
        return _finish(False, "micro_handoff_disabled")
    if candidate is None or not sym:
        return _finish(False, "candidate_or_symbol_missing")
    if str(getattr(candidate, "side", "long") or "long").lower() != "long":
        return _finish(False, "side_not_long")
    _allow_families = {str(x).upper() for x in CONFIG.get("V702_A7_MICRO_HANDOFF_FAMILIES", ())}
    if not ({family, mode} & _allow_families):
        return _finish(False, "family_not_allowlisted")

    # Explicitly retain the hard denylist, independent of the telemetry counters.
    try:
        base = sym.split("/", 1)[0].strip()
        hard_forbidden = set(_V702_PREDECLARED_FORBIDDEN_BASES)
        if base in hard_forbidden:
            return _finish(False, "forbidden_asset")
        forbidden_fn = globals().get("_v587_is_forbidden_coin")
        if callable(forbidden_fn):
            forbidden_result = forbidden_fn(sym)
            if isinstance(forbidden_result, tuple):
                if bool(forbidden_result[0]):
                    return _finish(False, "forbidden_asset")
            elif bool(forbidden_result):
                return _finish(False, "forbidden_asset")
    except Exception:
        return _finish(False, "forbidden_check_unverifiable")

    try:
        qv_raw = snap.get("quote_vol_24h", fs.get("quote_vol_24h", fs.get("quoteVolume", None)))
        if qv_raw is None:
            return _finish(False, "quote_volume_missing")
        qv = float(qv_raw)
        mn = float(CONFIG.get("V702_A7_MICRO_HANDOFF_MIN_QUOTE_VOLUME", 1_000_000.0))
        mx = float(CONFIG.get("V702_A7_MICRO_HANDOFF_MAX_QUOTE_VOLUME_EXCLUSIVE", 3_000_000.0))
        detail.update({"quote_volume_24h": qv, "micro_min": mn, "micro_max_exclusive": mx})
        if not math.isfinite(qv) or not (mn <= qv < mx):
            return _finish(False, "outside_micro_quote_band")
        if record and not seen_before:
            STATS["v702_a7_micro_eligible_after_quote_filter"] = int(STATS.get("v702_a7_micro_eligible_after_quote_filter", 0) or 0) + 1
        normalized_tier = _v702_normalize_liquidity_tier(snap.get("tier", tier), qv)
        if normalized_tier != "MICRO" or (tier is not None and str(tier).upper() not in {"MICRO", ""}):
            return _finish(False, "tier_not_micro")
    except Exception:
        return _finish(False, "quote_volume_unverifiable")

    score_raw = getattr(candidate, "engine_score", None)
    try:
        score100 = _v689_score_to_100(score_raw)
        hard_floor = max(70.0, float(CONFIG.get("MIN_LIVE_SCORE", 70.0)), float(CONFIG.get("V702_A7_MICRO_HANDOFF_SCORE_FLOOR", 70.0)))
        policy = CanonicalStrategyPolicyRegistry.get(mode) if callable(getattr(CanonicalStrategyPolicyRegistry, "get", None)) else {}
        policy_floor = _v689_score_to_100((policy or {}).get("min_score", 70.0), "100")
        effective_floor = max(hard_floor, policy_floor)
        detail.update({"score_100": score100, "score_floor": effective_floor, "strategy_score_floor": policy_floor})
        if not math.isfinite(score100) or score100 < effective_floor:
            return _finish(False, "score_below_micro_handoff_floor")
    except Exception:
        return _finish(False, "score_unverifiable")

    # For snapshots with explicit ages, a stale order book/spread cannot qualify.
    try:
        ages_fn = globals().get("_v689_market_fact_ages")
        ages = ages_fn(candidate, snap) if callable(ages_fn) else {}
        max_book_age = float(CONFIG.get("V690_MAX_BOOK_AGE_SEC", 15.0))
        max_spread_age = float(CONFIG.get("V690_MAX_SPREAD_AGE_SEC", 15.0))
        if ages.get("book_age_sec") is not None and float(ages["book_age_sec"]) > max_book_age:
            if record:
                _v702_a9_note_orderbook_cause(sym, "stale", {"status": "BOOK_TOO_OLD", "age_sec": ages.get("book_age_sec"), "source": snap.get("v703_route_orderbook_source", "unknown")})
            return _finish(False, "orderbook_stale", {"book_age_sec": ages.get("book_age_sec")})
        # Alias timestamps are expected to describe the SAME captured book. Do not
        # let a fresh alias conceal an older conflicting timestamp; disagreement is
        # treated as stale/unknown evidence and fails closed.
        for _book_ts_key in ("orderbook_ts", "book_ts", "depth_ts", "v703_route_orderbook_captured_ts"):
            try:
                _raw_book_ts = snap.get(_book_ts_key)
                if _raw_book_ts is None:
                    continue
                _book_ts_value = float(_raw_book_ts)
                if _book_ts_value > 1e12:
                    _book_ts_value /= 1000.0
                _book_signed_age = float(WALL_NOW()) - _book_ts_value
                if _book_signed_age < -2.0:
                    if record:
                        _v702_a9_note_orderbook_cause(sym, "future_timestamp", {"status": "BOOK_TIMESTAMP_IN_FUTURE", "age_sec": _book_signed_age, "source": _book_ts_key})
                    return _finish(False, "market_fact_timestamp_future", {"book_age_sec": _book_signed_age, "book_timestamp_source": _book_ts_key})
                _book_age_value = max(0.0, _book_signed_age)
                if _book_age_value > max_book_age:
                    if record:
                        _v702_a9_note_orderbook_cause(sym, "stale", {"status": "BOOK_TIMESTAMP_ALIAS_STALE", "age_sec": _book_age_value, "source": _book_ts_key})
                    return _finish(False, "orderbook_stale", {"book_age_sec": _book_age_value, "book_timestamp_source": _book_ts_key})
            except Exception:
                return _finish(False, "market_fact_freshness_unverifiable")
        # Spread timestamps use a separate alias set and a separate age limit.
        # In particular, a future-dated spread must not become age=0 in the
        # legacy age helper and pass as fresh.
        for _spread_ts_key in ("spread_ts", "spread_snapshot_ts"):
            try:
                _raw_spread_ts = snap.get(_spread_ts_key)
                if _raw_spread_ts is None:
                    continue
                _spread_ts_value = float(_raw_spread_ts)
                if _spread_ts_value > 1e12:
                    _spread_ts_value /= 1000.0
                _spread_signed_age = float(WALL_NOW()) - _spread_ts_value
                if not math.isfinite(_spread_ts_value) or _spread_signed_age < -2.0:
                    if record:
                        _v702_a9_note_orderbook_cause(sym, "future_timestamp", {"status": "SPREAD_TIMESTAMP_IN_FUTURE", "age_sec": _spread_signed_age, "source": _spread_ts_key})
                    return _finish(False, "market_fact_timestamp_future", {"spread_age_sec": _spread_signed_age, "spread_timestamp_source": _spread_ts_key})
                _spread_age_value = max(0.0, _spread_signed_age)
                if _spread_age_value > max_spread_age:
                    if record:
                        _v702_a9_note_orderbook_cause(sym, "spread_stale", {"status": "SPREAD_TIMESTAMP_ALIAS_STALE", "age_sec": _spread_age_value, "source": _spread_ts_key})
                    return _finish(False, "spread_stale", {"spread_age_sec": _spread_age_value, "spread_timestamp_source": _spread_ts_key})
            except Exception:
                return _finish(False, "market_fact_freshness_unverifiable")
        if ages.get("spread_age_sec") is not None and float(ages["spread_age_sec"]) > max_spread_age:
            if record:
                _v702_a9_note_orderbook_cause(sym, "spread_stale", {"status": "SPREAD_TOO_OLD", "age_sec": ages.get("spread_age_sec"), "source": snap.get("v703_route_orderbook_source", "unknown")})
            return _finish(False, "spread_stale", {"spread_age_sec": ages.get("spread_age_sec")})
    except Exception:
        return _finish(False, "market_fact_freshness_unverifiable")

    spread_raw = snap.get("spread_pct", fs.get("spread_pct"))
    if spread_raw is None:
        return _finish(False, "spread_missing")
    try:
        spread = float(spread_raw)
        if not math.isfinite(spread) or spread < 0.0:
            return _finish(False, "spread_unverifiable")
        hard_spread_ok, hard_spread_reason = tier_spread_hard_ok_v410(spread, "MICRO")
        if not hard_spread_ok:
            return _finish(False, "spread_hard_gate:" + str(hard_spread_reason), {"spread_pct": spread})
        if spread > float(CONFIG.get("V45_TIER_MICRO_MAX_SPREAD_PCT", 0.30)):
            return _finish(False, "micro_spread_hard_gate", {"spread_pct": spread})
    except Exception:
        return _finish(False, "spread_unverifiable")

    orderbook = (snap.get("orderbook") or snap.get("depth") or snap.get("_v703_route_score_orderbook")
                 or fs.get("orderbook") or fs.get("depth"))
    if not isinstance(orderbook, dict):
        if record:
            STATS["v702_a7_micro_orderbook_block"] = int(STATS.get("v702_a7_micro_orderbook_block", 0) or 0) + 1
            _cause, _cause_detail = _v702_a9_orderbook_missing_cause(sym, snap, fs)
            _v702_a9_note_orderbook_cause(sym, _cause, {**_cause_detail, "spread_pct": spread})
            _v702_a8_note_orderbook_block(sym, "handoff", "orderbook_missing", {"spread_pct": spread})
        return _finish(False, "orderbook_missing")
    # Critical market facts must be timestamped. An unaged book cannot prove it is
    # current enough for the MICRO handoff, so this remains a fail-closed condition.
    _book_ts = next((snap.get(k) for k in ("orderbook_ts", "book_ts", "depth_ts", "v703_route_orderbook_captured_ts") if snap.get(k) is not None), None)
    if _book_ts is None:
        if record:
            _v702_a9_note_orderbook_cause(sym, "timestamp_missing", {"status": str(snap.get("v702_a9_orderbook_prefetch_status", "UNKNOWN")), "source": snap.get("v703_route_orderbook_source", "unknown")})
        return _finish(False, "orderbook_timestamp_missing")
    depth_ratio = snap.get("depth_ratio", fs.get("depth_ratio", 0.0))
    volume_ratio = snap.get("volume_ratio", fs.get("volume_ratio", 0.0))
    structure = snap.get("structure_confidence", fs.get("structure_confidence", fs.get("structure_quality", 0.0)))
    chase = fs.get("chase_atr", getattr(candidate, "chase_atr", 0.0))
    ob_ctx = {
        "spread_pct": spread,
        "depth_ratio": float(depth_ratio or 0.0),
        "volume_ratio": float(volume_ratio or 0.0),
        "structure_confidence": float(structure or 0.0),
        "structure_quality": float(fs.get("structure_quality", structure or 0.0) or 0.0),
        "chase_atr": float(chase or 0.0),
    }
    try:
        ob_ok, ob_reason = _v45_orderbook_confirmation(orderbook, ob_ctx, "MICRO")
        detail.update({"spread_pct": spread, "depth_ratio": ob_ctx["depth_ratio"], "orderbook_reason": str(ob_reason)})
        if not ob_ok:
            if record:
                STATS["v702_a7_micro_orderbook_block"] = int(STATS.get("v702_a7_micro_orderbook_block", 0) or 0) + 1
                STATS["v702_a7_micro_last_orderbook_block"] = str(ob_reason)
                _v702_a8_note_orderbook_block(sym, "handoff", ob_reason, ob_ctx)
            return _finish(False, "orderbook_confirmation:" + str(ob_reason))
        if record and not seen_before:
            STATS["v702_a7_micro_orderbook_pass"] = int(STATS.get("v702_a7_micro_orderbook_pass", 0) or 0) + 1
    except Exception:
        if record:
            STATS["v702_a7_micro_orderbook_block"] = int(STATS.get("v702_a7_micro_orderbook_block", 0) or 0) + 1
        return _finish(False, "orderbook_confirmation_unverifiable")

    # Independent live-ticket economics probe. This is not a sizing fallback; a
    # failed fee/net target remains a hard stop and no micro-contract is created.
    try:
        # Pass the exact snapshot spread into the cost model rather than letting
        # the rank-time feature copy substitute the conservative/unknown fallback.
        fee_probe = type("_V702A7FeeProbe", (), {})()
        for attr in ("entry_ref", "sl_price", "tp1_rr", "tp2_rr"):
            setattr(fee_probe, attr, getattr(candidate, attr, None))
        fee_probe.features_snapshot = dict(fs)
        fee_probe.features_snapshot["spread_pct"] = float(spread)
        fee_result = CompositeRankingEngine._fee_viable(fee_probe)
        if isinstance(fee_result, tuple):
            fee_ok = bool(fee_result[0])
            fee_detail = fee_result[1] if len(fee_result) > 1 and isinstance(fee_result[1], dict) else {}
        elif isinstance(fee_result, dict):
            fee_ok = bool(fee_result.get("ok", False))
            fee_detail = fee_result
        else:
            fee_ok = bool(fee_result)
            fee_detail = {}
        detail["fee_reason"] = str((fee_detail or {}).get("reason", "ok" if fee_ok else "fee_unviable"))[:120]
        if not fee_ok:
            if record:
                STATS["v702_a7_micro_fee_unviable"] = int(STATS.get("v702_a7_micro_fee_unviable", 0) or 0) + 1
            return _finish(False, "fee_unviable")
        if record and not seen_before:
            STATS["v702_a7_micro_fee_viable"] = int(STATS.get("v702_a7_micro_fee_viable", 0) or 0) + 1
    except Exception as exc:
        if record:
            STATS["v702_a7_micro_fee_unviable"] = int(STATS.get("v702_a7_micro_fee_unviable", 0) or 0) + 1
        return _finish(False, f"fee_viability_unverifiable:{type(exc).__name__}")

    detail.update({
        "verified": True,
        "book_pass": True,
        "spread_pass": True,
        "fee_pass": True,
        "score_pass": True,
        "quote_volume_24h": qv,
        "ts_mono": now_mono,
        "proof_ttl_sec": float(CONFIG.get("V702_A7_MICRO_HANDOFF_PROOF_TTL_SEC", 90.0)),
    })
    return _finish(True, "PASS:BOOK_SPREAD_FEE_SCORE", detail)


def _v702_a7_micro_handoff_allowed(candidate, snapshot, tier=None) -> bool:
    try:
        # Cheap allowlist precheck avoids per-symbol handoff records for a lane that
        # is not eligible by design. It records an aggregate count only; admission
        # remains fail-closed and does not bypass downstream policy.
        snap = snapshot if isinstance(snapshot, dict) else {}
        family = str(getattr(candidate, "family", "") or "").upper()
        mode = str(getattr(candidate, "strategy_mode", "") or family).upper()
        allow_families = {str(x).upper() for x in CONFIG.get("V702_A7_MICRO_HANDOFF_FAMILIES", ())}
        if candidate is not None and not ({family, mode} & allow_families):
            STATS["v702_a19_micro_handoff_skipped_non_allowlisted"] = int(
                STATS.get("v702_a19_micro_handoff_skipped_non_allowlisted", 0) or 0
            ) + 1
            counts = STATS.setdefault("v702_a19_micro_handoff_reason_counts", {})
            if not isinstance(counts, dict):
                counts = {}
                STATS["v702_a19_micro_handoff_reason_counts"] = counts
            counts["family_not_allowlisted"] = int(counts.get("family_not_allowlisted", 0) or 0) + 1
            STATS["v702_a7_micro_handoff_last_block_reason"] = "family_not_allowlisted"
            return False
        ok, reason, detail = _v702_a7_micro_handoff_evidence(candidate, snap, tier=tier, record=False)
        try:
            diagnostic = globals().get("_v702_a19_record_micro_handoff_diagnostic")
            if callable(diagnostic):
                diagnostic(candidate, snap, tier, ok, reason, detail)
        except Exception:
            STATS["v702_a19_micro_handoff_diagnostic_errors"] = int(STATS.get("v702_a19_micro_handoff_diagnostic_errors", 0) or 0) + 1
        if ok:
            return True
        STATS["v702_a7_micro_handoff_last_block_reason"] = str(reason)[:180]
        return False
    except Exception as exc:
        reason = f"evidence_error:{type(exc).__name__}"
        STATS["v702_a7_micro_handoff_last_block_reason"] = reason
        try:
            diagnostic = globals().get("_v702_a19_record_micro_handoff_diagnostic")
            if callable(diagnostic): diagnostic(candidate, snapshot, tier, False, reason, {})
        except Exception:
            pass
        return False


# A verified in-prequal proof permits exactly the MICRO family-tier decision;
# every other tier decision keeps its established authority.
try:
    _V702_A7_PREV_TIER_ALLOWED = _v689_tier_allowed
    def _v702_a7_tier_allowed(family, mode, tier, score_01, features=None):
        try:
            tier_u = str(tier or "").upper()
            # MICRO is never accepted merely because a strategy registry says its
            # minimum tier permits it. It must always carry the fresh, bounded A7 proof.
            if tier_u != "MICRO":
                return bool(_V702_A7_PREV_TIER_ALLOWED(family, mode, tier, score_01, features))
            if not bool(CONFIG.get("V702_A7_MICRO_HANDOFF_ENABLE", False)):
                return False
            f = dict(features or {})
            proof = f.get("v702_a7_micro_handoff") or {}
            if not isinstance(proof, dict) or not bool(proof.get("verified")):
                return False
            allow_families = {str(x).upper() for x in CONFIG.get("V702_A7_MICRO_HANDOFF_FAMILIES", ())}
            family_modes = {str(family or "").upper(), str(mode or "").upper()}
            family_modes.discard("")
            if not (family_modes & allow_families):
                return False
            age = MONO_NOW() - float(proof.get("ts_mono", -1e12) or -1e12)
            ttl = max(1.0, float(CONFIG.get("V702_A7_MICRO_HANDOFF_PROOF_TTL_SEC", 90.0)))
            if age < 0.0 or age > ttl:
                STATS["v702_a7_micro_proof_expired"] = int(STATS.get("v702_a7_micro_proof_expired", 0) or 0) + 1
                return False
            required = ("book_pass", "spread_pass", "fee_pass", "score_pass")
            if not all(bool(proof.get(k)) for k in required):
                return False
            qv = float(proof.get("quote_volume_24h", 0.0) or 0.0)
            score = _v689_score_to_100(score_01, "01")
            policy = _v689_policy_for(family, mode)
            strategy_floor = _v689_score_to_100((policy or {}).get("min_score", 70.0), "100")
            return (
                float(CONFIG.get("V702_A7_MICRO_HANDOFF_MIN_QUOTE_VOLUME", 1_000_000.0)) <= qv
                < float(CONFIG.get("V702_A7_MICRO_HANDOFF_MAX_QUOTE_VOLUME_EXCLUSIVE", 3_000_000.0))
                and score >= max(70.0, float(CONFIG.get("MIN_LIVE_SCORE", 70.0)),
                                 float(CONFIG.get("V702_A7_MICRO_HANDOFF_SCORE_FLOOR", 70.0)), strategy_floor)
            )
        except Exception:
            return False
    _v702_a7_tier_allowed._v702_a7_wrapper = True
    _v689_tier_allowed = _v702_a7_tier_allowed
except Exception as _a7_tier_exc:
    STATS["v702_a7_tier_wrapper_error"] = f"{type(_a7_tier_exc).__name__}:{str(_a7_tier_exc)[:160]}"


# Macro policy is not made soft by Pilot mode. Instead, make NEUTRAL macro-denies
# auditable with the exact source and allow-list metadata for diagnosis.
try:
    _V702_A7_PREV_REGIME_POLICY = FamilyPolicyLayer.regime_policy_detail
    def _v702_a7_regime_policy_detail(family, regime, strategy_mode="", local_regime="", market_phase="", severity="", strategy_style=""):
        # Representation-only normalization. It strips accidental boundary
        # whitespace before the canonical policy compares exact enum tokens.
        def _canon(value):
            return str(value or "").strip().upper()
        fam_n, regime_n = _canon(family), _canon(regime)
        mode_n, local_n = _canon(strategy_mode), _canon(local_regime)
        phase_n, severity_n, style_n = _canon(market_phase), _canon(severity), _canon(strategy_style)
        result = _V702_A7_PREV_REGIME_POLICY(
            fam_n, regime_n, strategy_mode=mode_n, local_regime=local_n,
            market_phase=phase_n, severity=severity_n, strategy_style=style_n
        )
        try:
            ok, reason, ctx = result
            ctx = ctx if isinstance(ctx, dict) else {}
            reason_n = str(reason or "unknown").strip().lower()
            if not bool(globals().get("_V702_A9_BUILDING_REGIME_MATRIX", False)):
                status = "allow" if ok else reason_n
                counts = STATS.setdefault("v702_a9_regime_policy_decisions", {})
                if not isinstance(counts, dict):
                    counts = {}
                    STATS["v702_a9_regime_policy_decisions"] = counts
                counts[status] = int(counts.get(status, 0) or 0) + 1
                if not ok and reason_n == "macro":
                    allowed = [str(x).strip().upper() for x in (ctx.get("allowed_regimes", ()) or ())]
                    # Do not treat NON_BEARISH as NEUTRAL. It is not a valid macro
                    # token and should continue to fail closed rather than be aliased.
                    r = regime_n
                    conflict = bool(allowed and r in allowed)
                    expected_policy_block = bool(allowed and r not in allowed)
                    if conflict:
                        STATS["v702_a9_regime_registry_conflicts"] = int(STATS.get("v702_a9_regime_registry_conflicts", 0) or 0) + 1
                    if expected_policy_block:
                        STATS["v702_a9_macro_expected_blocks"] = int(STATS.get("v702_a9_macro_expected_blocks", 0) or 0) + 1
                    _mode_key = mode_n or fam_n or "UNKNOWN"
                    _macro_key = f"{_mode_key}|{r}"
                    _by_mode = STATS.setdefault("v702_a9_macro_block_by_mode_regime", {})
                    if not isinstance(_by_mode, dict):
                        _by_mode = {}
                        STATS["v702_a9_macro_block_by_mode_regime"] = _by_mode
                    _by_mode[_macro_key] = int(_by_mode.get(_macro_key, 0) or 0) + 1
                    if len(_by_mode) > 64:
                        _by_mode = dict(sorted(_by_mode.items(), key=lambda kv: int(kv[1] or 0), reverse=True)[:48])
                        STATS["v702_a9_macro_block_by_mode_regime"] = _by_mode
                    if r == "NEUTRAL" and bool(CONFIG.get("V702_A7_NEUTRAL_MACRO_DIAGNOSTICS_ENABLE", True)):
                        STATS["v702_a7_neutral_macro_policy_blocks"] = int(STATS.get("v702_a7_neutral_macro_policy_blocks", 0) or 0) + 1
                        STATS["v702_a7_last_neutral_macro_block"] = {
                            "family": fam_n, "strategy_mode": mode_n, "regime": r,
                            "local_regime": local_n, "phase": phase_n, "severity": severity_n,
                            "policy_source": str(ctx.get("policy_source", "unknown")),
                            "allowed_regimes": allowed, "allowed_regime_conflict": conflict,
                            "ts": WALL_NOW(),
                        }
                    elif r == "NON_BEARISH":
                        STATS["v702_a9_noncanonical_macro_blocks"] = int(STATS.get("v702_a9_noncanonical_macro_blocks", 0) or 0) + 1
                    STATS["v702_a9_last_macro_block"] = {
                        "family": fam_n, "strategy_mode": mode_n, "regime": r,
                        "local_regime": local_n, "phase": phase_n, "severity": severity_n,
                        "strategy_style": style_n, "policy_source": str(ctx.get("policy_source", "unknown")),
                        "allowed_regimes": allowed, "registry_conflict": conflict,
                        "expected_policy_block": expected_policy_block,
                        "ts": WALL_NOW(),
                    }
            return bool(ok), str(reason), ctx
        except Exception:
            # The underlying policy result remains authoritative if diagnostics fail.
            return result
    FamilyPolicyLayer.regime_policy_detail = staticmethod(_v702_a7_regime_policy_detail)
except Exception as _a7_regime_exc:
    STATS["v702_a7_regime_wrapper_error"] = f"{type(_a7_regime_exc).__name__}:{str(_a7_regime_exc)[:160]}"


def _v702_a9_regime_compatibility_matrix() -> Dict[str, Any]:
    """Compare runtime macro decisions with the single canonical strategy registry."""
    matrix: Dict[str, Any] = {}
    mismatches = []
    checked = 0
    data = CanonicalStrategyPolicyRegistry.data() if callable(getattr(CanonicalStrategyPolicyRegistry, "data", None)) else {}
    data = data if isinstance(data, dict) else {}
    globals()["_V702_A9_BUILDING_REGIME_MATRIX"] = True
    try:
        for mode, meta0 in sorted(data.items(), key=lambda item: str(item[0])):
            if not isinstance(meta0, dict):
                continue
            mode_n = str(mode or "").strip().upper()
            meta = dict(meta0)
            allowed = {str(x).strip().upper() for x in (meta.get("allowed_regimes", ()) or ()) if str(x).strip()}
            enabled = bool(meta.get("enabled", True))
            mode_row = {"enabled": enabled, "declared_allowed_regimes": sorted(allowed), "actual": {}}
            for macro in ("BULLISH", "NEUTRAL", "BEARISH"):
                checked += 1
                if not bool(CONFIG.get("V410_FAMILY_POLICY_ENABLE", True)):
                    mode_row["actual"][macro] = "policy_disabled"
                    continue
                try:
                    ok, reason, ctx = FamilyPolicyLayer.regime_policy_detail(
                        mode_n, macro, strategy_mode=mode_n, local_regime="", market_phase="",
                        severity="", strategy_style=""
                    )
                    actual = "ALLOW" if ok else str(reason or "blocked").upper()
                    mode_row["actual"][macro] = actual
                    if not enabled:
                        continue
                    expected_allowed = (not allowed) or macro in allowed
                    # Empty severity/local/phase isolates the macro-regime contract.
                    if expected_allowed and str(reason).lower() == "macro":
                        mismatches.append({"mode": mode_n, "regime": macro, "expected": "ALLOW", "actual": actual, "allowed": sorted(allowed)})
                    elif not expected_allowed and bool(ok):
                        mismatches.append({"mode": mode_n, "regime": macro, "expected": "BLOCK_MACRO", "actual": actual, "allowed": sorted(allowed)})
                except Exception as exc:
                    mode_row["actual"][macro] = "MATRIX_ERROR:" + type(exc).__name__
                    mismatches.append({"mode": mode_n, "regime": macro, "expected": "DECISION", "actual": "ERROR:" + type(exc).__name__})
            matrix[mode_n] = mode_row
    finally:
        globals()["_V702_A9_BUILDING_REGIME_MATRIX"] = False
    result = {
        "checked_mode_regime_cells": checked, "mode_count": len(matrix),
        "mismatch_count": len(mismatches), "mismatches": mismatches[:40],
        "matrix": matrix, "policy_authority": "CanonicalStrategyPolicyRegistry",
        "trend_filter_disabled": False, "unknown_macro_fails_closed": True,
        "checked_at": float(WALL_NOW()),
    }
    STATS["v702_a9_regime_compatibility_matrix"] = result
    STATS["v702_a9_regime_compatibility_matrix_ok"] = (len(mismatches) == 0 and checked > 0)
    return result


try:
    _v702_a9_regime_matrix = _v702_a9_regime_compatibility_matrix()
    logger.info("[V702-A9-REGIME-MATRIX] modes=%d cells=%d mismatches=%d trend_filter=preserved", int(_v702_a9_regime_matrix.get("mode_count", 0)), int(_v702_a9_regime_matrix.get("checked_mode_regime_cells", 0)), int(_v702_a9_regime_matrix.get("mismatch_count", 0)))
except Exception as _a9_regime_matrix_exc:
    STATS["v702_a9_regime_compatibility_matrix_ok"] = False
    STATS["v702_a9_regime_compatibility_matrix_error"] = f"{type(_a9_regime_matrix_exc).__name__}:{str(_a9_regime_matrix_exc)[:160]}"


# Digest addition: display a single root blocker + age and MICRO funnel probes.
def _v702_a7_entry_block_summary(status_text: str = ""):
    now = float(WALL_NOW())
    # Prefer the entry state printed on this heartbeat over cached route/status
    # records. A current NO_LIVE_READY state must not inherit an older blocker.
    try:
        status_match = re.search(r"\bENTRY_STATUS\s*=\s*BLOCKED:([A-Z][A-Z0-9_]*)\b", str(status_text or "").upper())
        if status_match:
            current_root = status_match.group(1)
            if current_root in {"NONE", "NO_LIVE_READY", "ENTRY_STATUS_UNVERIFIED"}:
                return "NONE", -1
            return current_root, -1
    except Exception:
        pass
    candidates = []
    try:
        rec = STATS.get("v702_selected_route_last")
        if isinstance(rec, dict):
            candidates.append((float(rec.get("ts", 0.0) or 0.0), str(rec.get("reason", "") or ""), str(rec.get("stage", "") or ""), str(rec.get("root", "") or "")))
    except Exception:
        pass
    try:
        rec = globals().get("_V698_LAST_BUILDER_BLOCK", {})
        if isinstance(rec, dict):
            ts = float(rec.get("ts", 0.0) or 0.0)
            if ts > 1e12:
                ts /= 1000.0
            candidates.append((ts, str(rec.get("reason", "") or ""), str(rec.get("stage", "builder") or "builder"), str(rec.get("root", "") or "")))
    except Exception:
        pass
    max_age = max(60.0, float(CONFIG.get("V702_A7_ENTRY_BLOCK_MAX_AGE_SEC", 1800.0)))
    fresh = [x for x in candidates if x[0] > 0.0 and 0.0 <= now - x[0] <= max_age]
    if fresh:
        ts, reason, stage, root = max(fresh, key=lambda x: x[0])
        if not root:
            try:
                root = _v698_reason_root(reason, stage)
            except Exception:
                root = "OTHER"
        return str(root or "OTHER").upper(), int(max(0.0, now - ts))
    try:
        status = str(STATS.get("v699_live_entry_status", "") or "")
        status_ts = float(STATS.get("v699_live_entry_status_ts", 0.0) or 0.0)
        status_age = now - status_ts
        m = re.search(r"BLOCKED:([A-Z_]+)", status.upper())
        if m and status_ts > 0.0 and 0.0 <= status_age <= max_age:
            return m.group(1), int(max(0.0, status_age))
    except Exception:
        pass
    return "NONE", -1

try:
    _V702_A7_PREV_HEARTBEAT_LINE = _V702R28TelegramDigest._heartbeat_line.__func__
    @classmethod
    def _v702_a7_heartbeat_line(cls, text):
        base = _V702_A7_PREV_HEARTBEAT_LINE(cls, text)
        try:
            root, age = _v702_a7_entry_block_summary(base)
            age_text = f"{age}s" if age >= 0 else "unknown"
            diag = STATS.get("v702_r30_micro_recall_diagnostics", {}) or {}
            eligible = int(STATS.get("v702_a7_micro_eligible_after_quote_filter", diag.get("eligible_rows", 0)) or 0)
            ob_pass = int(STATS.get("v702_a7_micro_orderbook_pass", 0) or 0)
            fee_pass = int(STATS.get("v702_a7_micro_fee_viable", 0) or 0)
            base += f" ENTRY_BLOCK_ROOT={root} age={age_text} MICRO_ELIG/OB_PASS/FEE_OK={eligible}/{ob_pass}/{fee_pass}"
            # A17: expose the shared-macro prefilter funnel and content-cache efficiency.
            try:
                _a17_macro = STATS.get("v702_a17_macro_prefilter_last", {}) or {}
                if isinstance(_a17_macro, dict) and _a17_macro:
                    _a17_reasons = _a17_macro.get("reasons", {}) if isinstance(_a17_macro.get("reasons", {}), dict) else {}
                    _a17_top = max(_a17_reasons.items(), key=lambda kv: int(kv[1] or 0)) if _a17_reasons else ("-", 0)
                    _a17_top_key = re.sub(r"[^A-Za-z0-9_.:-]", "_", str(_a17_top[0]))[:40]
                    base += (f" A17_MACRO_PREFILTER=seen:{int(_a17_macro.get('seen',0) or 0)}"
                             f",pass:{int(_a17_macro.get('pass',0) or 0)},block:{int(_a17_macro.get('blocked',0) or 0)}"
                             f",top:{_a17_top_key}x{int(_a17_top[1] or 0)}")
                base += (f" A17_MACRO_CACHE={int(STATS.get('v702_a17_macro_cache_hits',0) or 0)}"
                         f"/{int(STATS.get('v702_a17_macro_cache_misses',0) or 0)}"
                         f" A17_SEVERITY_CACHE={int(STATS.get('v702_a17_severity_cache_hits',0) or 0)}"
                         f"/{int(STATS.get('v702_a17_severity_cache_misses',0) or 0)}")
            except Exception:
                pass
            try:
                _a9_causes = STATS.get("v702_a9_orderbook_cause_counts", {}) or {}
                _a9_prefetch = STATS.get("v702_a9_orderbook_prefetch_last_cycle", {}) or {}
                if isinstance(_a9_causes, dict) and _a9_causes:
                    _a9_top = sorted(_a9_causes.items(), key=lambda kv: int(kv[1] or 0), reverse=True)[:3]
                    base += " A9_OB_CAUSE=" + ",".join(f"{str(k)}:{int(v or 0)}" for k, v in _a9_top)
                if isinstance(_a9_prefetch, dict) and _a9_prefetch:
                    _ob_age = max(0.0, float(WALL_NOW()) - float(_a9_prefetch.get("ts", 0.0) or 0.0)) if _a9_prefetch.get("ts") else None
                    _ob_skip = str(_a9_prefetch.get("skip_reason", "none") or "none")[:28]
                    _ob_age_text = f"{_ob_age:.0f}s" if _ob_age is not None else "unknown"
                    base += (f" A9_OB_FETCH=elig:{int(_a9_prefetch.get('eligible',0) or 0)}"
                             f",try:{int(_a9_prefetch.get('attempted',0) or 0)}"
                             f",fresh:{int(_a9_prefetch.get('fetched_fresh',0) or 0)}"
                             f",reuse:{int(_a9_prefetch.get('reused_fresh',0) or 0)}"
                             f",err:{int(_a9_prefetch.get('api_errors',0) or 0)}"
                             f",to:{int(_a9_prefetch.get('timeouts',0) or 0)}"
                             f",bad:{int(_a9_prefetch.get('empty_or_invalid',0) or 0)}"
                             f",taskerr:{int(_a9_prefetch.get('task_errors',0) or 0)}"
                             f",defer:{int(_a9_prefetch.get('deferred_budget',0) or 0)}"
                             f",skip:{_ob_skip},age:{_ob_age_text}")
                for _short, _code in (("MM1", "micro_momentum_1m"), ("SW1", "micro_sweep_reclaim_1m"), ("PB1", "micro_pullback_reclaim_1m"), ("VWRS5", "vwap_reclaim_rs_5m")):
                    _e = STATS.get("v702_a9_engine_cycle_" + _code, {}) or {}
                    _r = STATS.get("v702_a9_engine_" + _code, {}) or {}
                    if isinstance(_e, dict):
                        base += (f" A9_{_short}={int(_e.get('evaluations',0) or 0)}/{int(_e.get('signals',0) or 0)}/{int(_e.get('rejections',0) or 0)}"
                                 f"/skip:{int(_e.get('skipped',0) or 0)}"
                                 f"/blk:{int(_e.get('blocked',0) or 0)}")
                    if isinstance(_r, dict) and (_r.get("post_cost_viable") is not None or _r.get("post_cost_capped") is not None):
                        _report_age = max(0.0, float(WALL_NOW()) - float(_r.get("report_ts", 0.0) or 0.0)) if _r.get("report_ts") else None
                        _report_age_text = f"{_report_age:.0f}s" if _report_age is not None else "unknown"
                        base += f"/histNet:{int(_r.get('post_cost_viable',0) or 0)}:{int(_r.get('post_cost_capped',0) or 0)}@{_report_age_text}"
                _matrix = STATS.get("v702_a9_regime_compatibility_matrix", {}) or {}
                _policy_decisions = STATS.get("v702_a9_regime_policy_decisions", {}) or {}
                _macro_expected = int(STATS.get("v702_a9_macro_expected_blocks", 0) or 0)
                _macro_conflicts = int(STATS.get("v702_a9_regime_registry_conflicts", 0) or 0)
                _macro_top = STATS.get("v702_a9_macro_block_by_mode_regime", {}) or {}
                _macro_top_item = max(_macro_top.items(), key=lambda kv: int(kv[1] or 0)) if isinstance(_macro_top, dict) and _macro_top else None
                base += (f" A9_REGIME_MATRIX={int(_matrix.get('mode_count',0) or 0)}m/"
                         f"{int(_matrix.get('mismatch_count',0) or 0)}mismatch/"
                         f"macro_blocks={int(_policy_decisions.get('macro',0) or 0)}"
                         f"/expected={_macro_expected}/conflicts={_macro_conflicts}")
                if _macro_top_item:
                    base += f" A9_MACRO_TOP={str(_macro_top_item[0]).replace('|',':')[:48]}x{int(_macro_top_item[1] or 0)}"
                _last_macro = STATS.get("v702_a9_last_macro_block", {}) or {}
                if isinstance(_last_macro, dict) and _last_macro.get("regime"):
                    base += (f" A9_LAST_MACRO={str(_last_macro.get('strategy_mode','?'))}:{str(_last_macro.get('regime','?'))}"
                             f":allow={','.join(_last_macro.get('allowed_regimes',[]) or [])[:48]}"
                             f":expected={int(bool(_last_macro.get('expected_policy_block',False)))}"
                             f":conflict={int(bool(_last_macro.get('registry_conflict',False)))}"
                             f":src={str(_last_macro.get('policy_source','?'))[:24]}")
            except Exception:
                pass
            try:
                ob_counts = STATS.get("v702_a8_orderbook_block_counts", {}) or {}
                if isinstance(ob_counts, dict) and ob_counts:
                    top_ob = max(ob_counts.items(), key=lambda kv: int(kv[1] or 0))
                    base += f" OB_BLOCK_TOP={str(top_ob[0])[:54]}x{int(top_ob[1] or 0)}"
            except Exception:
                pass
            try:
                mse_diag = str(STATS.get("mse_snapshot_invalid_diagnostic", "") or "")
                mse_ts = float(STATS.get("mse_snapshot_invalid_diagnostic_ts", 0.0) or 0.0)
                if mse_diag and mse_ts > 0.0 and 0.0 <= float(WALL_NOW()) - mse_ts <= 900.0:
                    base += f" MSE_DATA_BLOCK={mse_diag[:100]}"
            except Exception:
                pass
            # This is explicitly the most recent failed candidate snapshot,
            # not a claim that every current candidate has the same failure.
            try:
                _ctx_block = STATS.get("v702_r36_last_snapshot_context_block", {}) or {}
                _ctx_ts = float(_ctx_block.get("ts", 0.0) or 0.0) if isinstance(_ctx_block, dict) else 0.0
                _ctx_age = float(WALL_NOW()) - _ctx_ts if _ctx_ts > 0 else -1.0
                if isinstance(_ctx_block, dict) and _ctx_ts > 0 and 0.0 <= _ctx_age <= 900.0:
                    _ctx_symbol = str(_ctx_block.get("symbol", "?") or "?")[:24]
                    _ctx_reason = re.sub(r"[^A-Z0-9_:.-]", "_", str(_ctx_block.get("reason", "unknown") or "unknown").upper())[:56]
                    _ctx_rows = int(_ctx_block.get("btc_4h_rows", 0) or 0)
                    base += f" MACRO_CTX_LAST_BLOCK={_ctx_symbol}:{_ctx_reason}:n4h={_ctx_rows}@{_ctx_age:.0f}s"
                # Expose the current BTC 4H history fetch result in the same
                # operator heartbeat that reports macro-context blocks.
                _btc4_fetch = STATS.get("v702_r40_btc4h_fetch_diag", {}) or {}
                _btc4_ts = float(_btc4_fetch.get("ts", 0.0) or 0.0) if isinstance(_btc4_fetch, dict) else 0.0
                _btc4_age = float(WALL_NOW()) - _btc4_ts if _btc4_ts > 0 else -1.0
                if isinstance(_btc4_fetch, dict) and _btc4_ts > 0 and 0.0 <= _btc4_age <= 900.0:
                    base += (f" BTC4H_FETCH=raw:{int(_btc4_fetch.get('raw_rows',0) or 0)}"
                             f",merged:{int(_btc4_fetch.get('merged_rows',0) or 0)}"
                             f",closed:{int(_btc4_fetch.get('closed_rows_available',0) or 0)}"
                             f",recover:{int(bool(_btc4_fetch.get('page_recovery_ok',False)))}"
                             f",age:{_btc4_age:.0f}s")
            except Exception:
                pass
            # A30: reveal the productive savings from the reject-only history
            # prefetch shortcut. These are diagnostics only; they do not count as
            # eligible candidates, signals, Telegram messages or executions.
            try:
                _a30_skip_count = int(STATS.get("v702_a30_cached_short_history_prefetch_skips", 0) or 0)
                _a30_saved_reads = int(STATS.get("v702_a30_saved_lower_tf_ohlcv_requests", 0) or 0)
                _a30_cache_hits = int(STATS.get("v702_a31_history_cache_hits", 0) or 0)
                _a30_cache = globals().get("_V702_A29_SHORT_HISTORY_CACHE", {})
                _a30_cache_size = len(_a30_cache) if isinstance(_a30_cache, dict) else 0
                _a30_last = STATS.get("v702_a30_last_cached_history_skip", {}) or {}
                if _a30_skip_count or _a30_cache_size:
                    if isinstance(_a30_last, dict) and _a30_last.get("ts"):
                        _a30_age = max(0.0, float(WALL_NOW()) - float(_a30_last.get("ts", 0.0) or 0.0))
                        _a30_age_text = f"@{_a30_age:.0f}s"
                        _a30_symbol = re.sub(r"[^A-Za-z0-9/_-]", "_", str(_a30_last.get("symbol", "-") or "-"))[:22]
                        _a30_last_text = (f"{_a30_symbol}:{int(_a30_last.get('got',0) or 0)}"
                                          f"/{int(_a30_last.get('required',210) or 210)}{_a30_age_text}")
                    else:
                        # cache occupancy alone is not a successful skip; make that
                        # distinction explicit instead of printing last=@unknown.
                        _a30_last_text = "none_yet" if _a30_skip_count == 0 else "telemetry_missing"
                    base += (f" A30_HISTORY_PREFETCH=skips:{_a30_skip_count},saved_reads:{_a30_saved_reads}"
                             f",hits:{_a30_cache_hits},cache:{_a30_cache_size},last:{_a30_last_text}")
            except Exception:
                pass
            # A31 makes short-history cache revalidation observable. This is a
            # bounded retry throttle, not evidence that a token is newly listed.
            try:
                _a31_rechecks = int(STATS.get("v702_a31_history_cache_expired_rechecks", 0) or 0)
                _a31_boundary = int(STATS.get("v702_a31_history_cache_boundary_invalidations", 0) or 0)
                _a31_hits = int(STATS.get("v702_a31_history_cache_hits", 0) or 0)
                _a31_ttl = max(60, min(900, int(float(CONFIG.get("V702_A31_SHORT_HISTORY_RECHECK_SEC", 420.0) or 420.0))))
                base += f" A31_HISTORY_RECHECK=ttl:{_a31_ttl}s,expired:{_a31_rechecks},hits:{_a31_hits},boundary:{_a31_boundary}"
            except Exception:
                pass
            gap = STATS.get("v702_a7_shadow_live_gap_last")
            if (isinstance(gap, dict) and bool(gap.get("same_candidate_attribution"))
                    and 0.0 <= float(WALL_NOW()) - float(gap.get("ts", 0.0) or 0.0) <= 900.0):
                gap_age = gap.get("age_sec")
                gap_age_text = f"{float(gap_age):.0f}s" if gap_age is not None else "unknown"
                base += (f" SHADOW_LIVE_GAP={str(gap.get('symbol','?'))}"
                         f":MFE+{float(gap.get('mfe_r',0.0)):.2f}R"
                         f":ref={str(gap.get('candidate_ref_short','') or '-')[:8]}"
                         f":route_ref={str(gap.get('route_candidate_ref_short','') or '-')[:8]}"
                         f":matched={int(bool(gap.get('same_candidate_attribution')))}"
                         f":age={gap_age_text}:reason={str(gap.get('reason','') or '')[:60]}")
            # MICRO diagnostics must be visible even when no shadow-gap event exists.
            mh = STATS.get("v702_a19_micro_handoff_last")
            if isinstance(mh, dict) and 0.0 <= float(WALL_NOW()) - float(mh.get("ts", 0.0) or 0.0) <= 900.0:
                base += (f" A19_MICRO_HANDOFF={str(mh.get('symbol','?'))}"
                         f":{str(mh.get('reason','unknown'))[:48]}"
                         f":ok={int(bool(mh.get('ok')))}"
                         f":ref={str(mh.get('candidate_ref','') or '-')[:8]}")
            # A23: expose short local-history candidates rejected before ranking.
            # Keep the canonical A7 heartbeat method identity intact for compatibility.
            try:
                _a23_last = STATS.get("v702_a23_last_local_history_block", {}) or {}
                _a23_n = int(STATS.get("v702_a23_local_history_blocks", 0) or 0)
                if _a23_n or (isinstance(_a23_last, dict) and _a23_last):
                    _a23_age = max(0.0, float(WALL_NOW()) - float(_a23_last.get("ts", 0.0) or 0.0)) if _a23_last.get("ts") else None
                    _a23_age_text = f"{_a23_age:.0f}s" if _a23_age is not None else "unknown"
                    _a23_symbol = re.sub(r"[^A-Za-z0-9/_-]", "_", str(_a23_last.get("symbol", "-") or "-"))[:22]
                    _a23_reason = re.sub(r"[^A-Za-z0-9_.:,=-]", "_", str(_a23_last.get("reason", "-") or "-"))[:68]
                    base += f" A23_LOCAL_HISTORY=blocks:{_a23_n},last:{_a23_symbol}:{_a23_reason}@{_a23_age_text}"
            except Exception:
                pass
        except Exception:
            pass
        return base
    _V702R28TelegramDigest._heartbeat_line = _v702_a7_heartbeat_line
except Exception as _a7_hb_exc:
    STATS["v702_a7_digest_wrapper_error"] = f"{type(_a7_hb_exc).__name__}:{str(_a7_hb_exc)[:160]}"


# A34: explicit candidate progress evidence for Shadow/live attribution.
# This ledger is telemetry-only and does not grant execution authority.
def _v702_a34_record_route_progress(candidate: Any, stage: str) -> None:
    try:
        if candidate is None:
            return
        stage_key = str(stage or "").strip().lower()
        if stage_key not in {"presend_pass", "queued", "sent"}:
            return
        ref_fn = globals().get("_v702_a19_candidate_ref")
        candidate_ref = str(ref_fn(candidate) if callable(ref_fn) else "").lower()
        if len(candidate_ref) != 40:
            return
        record = {
            "symbol": str(getattr(candidate, "symbol", "") or "").upper()[:64],
            "family": str(getattr(candidate, "family", "") or getattr(candidate, "strategy_mode", "") or "").upper()[:64],
            "candidate_ref": candidate_ref, "stage": stage_key,
            "cycle_id": int(STATS.get("v681_runtime_cycle_id", 0) or 0),
            "ts": float(WALL_NOW()),
        }
        history = STATS.setdefault("v702_candidate_route_progress_history", [])
        if not isinstance(history, list):
            history = []
            STATS["v702_candidate_route_progress_history"] = history
        history.append(record)
        if len(history) > 128:
            del history[:-128]
        STATS["v702_candidate_route_progress_last"] = dict(record)
    except Exception:
        _v647_record_suppressed_exception()


def _v702_a34_candidate_reached_presend_or_queue(candidate_ref: str, symbol: str = "", family: str = "",
                                                   now: Optional[float] = None) -> Tuple[bool, str]:
    """Require exact candidate attribution and a recent PRESEND/QUEUE/SENT event."""
    ref = str(candidate_ref or "").strip().lower()
    if len(ref) != 40:
        return False, "shadow_candidate_ref_missing"
    ts_now = float(now if now is not None else WALL_NOW())
    allowed = {"presend_pass", "queued", "sent"}
    histories = (
        STATS.get("v702_candidate_route_progress_history", []),
        STATS.get("v702_selected_route_history", []),
    )
    for history in histories:
        if not isinstance(history, list):
            continue
        for item in reversed(history[-128:]):
            if not isinstance(item, dict):
                continue
            if str(item.get("candidate_ref", "") or "").lower() != ref:
                continue
            stage = str(item.get("stage", "") or "").lower()
            if stage not in allowed:
                continue
            age = ts_now - float(item.get("ts", 0.0) or 0.0)
            if age < -2.0 or age > 900.0:
                continue
            if symbol and str(item.get("symbol", "") or "").upper() != str(symbol).upper():
                continue
            seen_family = str(item.get("family", "") or "").upper()
            if family and seen_family and seen_family != str(family).upper():
                continue
            return True, stage
    return False, "candidate_never_reached_presend_queue"


# Shadow/live comparison is telemetry-only. A match now requires the exact stable
# KnowledgeOutcomeLedger CandidateRef, same symbol/family, a fresh route record and
# a route stage that actually blocked the candidate. Same-symbol proximity alone is
# intentionally never represented as same-candidate attribution.
try:
    _V702_A7_PREV_CAPTURE = _V702R28TelegramDigest.capture.__func__
    @classmethod
    def _v702_a7_capture(cls, category, raw, *args, **kwargs):
        result = _V702_A7_PREV_CAPTURE(cls, category, raw, *args, **kwargs)
        try:
            if str(category) == "shadow" and bool(CONFIG.get("V702_A7_SHADOW_LIVE_GAP_ENABLE", True)):
                txt = cls._strip(str(raw or ""))
                m_sym = re.search(r"\b([A-Z0-9_.()\-]+/USDT)\b", txt, re.I)
                m_mfe = re.search(r"MFE\s*[:=]\s*\+?([0-9]+(?:\.[0-9]+)?)\s*R", txt, re.I)
                m_ref = re.search(r"\bCandidateRef\s*:\s*([a-f0-9]{40})\b", txt, re.I)
                mfe = float(m_mfe.group(1)) if m_mfe else None
                candidate_ref = str(m_ref.group(1) if m_ref else "").lower()
                if m_sym and mfe is not None and mfe > 1.0:
                    symbol = m_sym.group(1).upper()
                    family_m = re.search(r"\b(?:Strategy|Family)\s*:\s*([^\n]+)|\|\s*([A-Z_]+)\b", txt, re.I)
                    family = str((family_m.group(1) or family_m.group(2)) if family_m else "").strip().upper()
                    route = STATS.get("v702_selected_route_last")
                    reason = "shadow_candidate_ref_missing" if not candidate_ref else "no_recent_live_route_for_candidate"
                    age = None
                    matched = False
                    route_stage = ""
                    _progress_ok, _progress_reason = _v702_a34_candidate_reached_presend_or_queue(
                        candidate_ref, symbol, family, now=float(WALL_NOW())
                    )
                    if isinstance(route, dict) and str(route.get("symbol", "")).upper() == symbol:
                        rts = float(route.get("ts", 0.0) or 0.0)
                        age = max(0.0, float(WALL_NOW()) - rts) if rts > 0 else None
                        route_ref = str(route.get("candidate_ref", "") or "").lower()
                        rfamily = str(route.get("family", route.get("strategy_mode", "")) or "").upper()
                        route_stage = str(route.get("stage", "") or "").lower()
                        blocking_stages = {
                            "selected_preexec_freshness", "selected_preexec_policy", "selected_preexec_canonical",
                            "selected_route_orderbook", "selected_route_projection", "selected_route_orderbook_error",
                            "builder_block", "builder_exception",
                        }
                        if not candidate_ref:
                            reason = "shadow_candidate_ref_missing"
                        elif route_ref != candidate_ref:
                            reason = "candidate_ref_mismatch" if route_ref else "live_route_candidate_ref_missing"
                        elif age is None or age > 900.0:
                            reason = "live_route_stale"
                        elif family and rfamily and family != rfamily:
                            reason = "candidate_family_mismatch"
                        elif not _progress_ok:
                            reason = _progress_reason
                        elif route_stage not in blocking_stages:
                            reason = f"route_not_blocked:{route_stage or 'unknown'}"
                        else:
                            reason = str(route.get("reason", "same_candidate_live_block") or "same_candidate_live_block")
                            matched = True
                    STATS["v702_a7_shadow_live_gap_count"] = int(STATS.get("v702_a7_shadow_live_gap_count", 0) or 0) + 1
                    _gap_record = {
                        "symbol": symbol, "family": family, "mfe_r": mfe,
                        "candidate_ref": candidate_ref,
                        "candidate_ref_short": candidate_ref[:8] if candidate_ref else "",
                        "route_candidate_ref_short": str((route or {}).get("candidate_ref", "") or "")[:8] if isinstance(route, dict) else "",
                        "route_stage": route_stage,
                        "reason": reason, "same_candidate_attribution": matched,
                        "age_sec": age, "ts": float(WALL_NOW()),
                        "diagnostic_only": True,
                    }
                    if matched:
                        # Only exact, fresh, same-family candidate attribution plus
                        # an explicit live blocker may surface as an operator gap alert.
                        STATS["v702_a7_shadow_live_gap_matched_count"] = int(
                            STATS.get("v702_a7_shadow_live_gap_matched_count", 0) or 0) + 1
                        STATS["v702_a7_shadow_live_gap_last"] = _gap_record
                    else:
                        # Keep unmatched shadow observations for diagnosis, but never
                        # let them overwrite the last verified gap in the heartbeat.
                        STATS["v702_a7_shadow_live_gap_unmatched_count"] = int(
                            STATS.get("v702_a7_shadow_live_gap_unmatched_count", 0) or 0) + 1
                        STATS["v702_a7_shadow_live_gap_unmatched_last"] = _gap_record
        except Exception as exc:
            STATS["v702_a19_shadow_attribution_errors"] = int(STATS.get("v702_a19_shadow_attribution_errors", 0) or 0) + 1
            STATS["v702_a19_shadow_attribution_last_error"] = f"{type(exc).__name__}:{str(exc)[:100]}"
        return result
    _V702R28TelegramDigest.capture = _v702_a7_capture
except Exception as _a7_shadow_exc:
    STATS["v702_a7_shadow_gap_wrapper_error"] = f"{type(_a7_shadow_exc).__name__}:{str(_a7_shadow_exc)[:160]}"


# Digest build observer identity is an enforced R38 contract; keep it intact.
