# Canonical validation extension: score/portfolio invariants and helper contracts.
try:
    _V702_A7_PREV_VALIDATE_CONFIG = globals().get("validate_config")
    def _v702_a7_validate_config():
        base_ok = bool(_V702_A7_PREV_VALIDATE_CONFIG()) if callable(_V702_A7_PREV_VALIDATE_CONFIG) else False
        checks = {}
        try:
            checks["score_hard_floor_ge_70"] = float(CONFIG.get("MIN_LIVE_SCORE", 70.0)) >= 70.0 and float(CONFIG.get("V702_A7_MICRO_HANDOFF_SCORE_FLOOR",70.0)) >= 70.0
            checks["core_liquidity_floor_preserved"] = float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME",3_000_000.0)) >= 3_000_000.0
            checks["spot_long_only_preserved"] = bool(CONFIG.get("LONG_ONLY",True)) and str(CONFIG.get("MARKET_TYPE","SPOT")).upper()=="SPOT" and not bool(CONFIG.get("FUTURES_ENABLED",False)) and not bool(CONFIG.get("ENABLE_FUTURES",False)) and not bool(CONFIG.get("ALLOW_SHORT",False)) and not bool(CONFIG.get("ALLOW_SHORTS",False))
            checks["trade_cap_preserved"] = int(CONFIG.get("MAX_CONCURRENT_TRADES",2)) <= 2
            checks["micro_floor_within_core_band"] = 0.0 < float(CONFIG.get("V702_A7_MICRO_HANDOFF_MIN_QUOTE_VOLUME",0.0)) < float(CONFIG.get("V702_A7_MICRO_HANDOFF_MAX_QUOTE_VOLUME_EXCLUSIVE",0.0)) <= float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME",3_000_000.0))
            checks["hard_gate_bypass_disabled"] = not bool(CONFIG.get("V702_A7_HARD_GATE_BYPASS",True)) and not bool(CONFIG.get("V702_R34_HARD_GATE_BYPASS",True))
            checks["telegram_auth_controller_present"] = callable(getattr(TelegramCommandController,"_authorized",None))
            _hb_func = getattr(_V702R28TelegramDigest._heartbeat_line, "__func__", _V702R28TelegramDigest._heartbeat_line)
            _a17_hb_delegate = globals().get("_V702_A17_PREV_HEARTBEAT_LINE")
            checks["digest_root_diagnostic_installed"] = bool(
                getattr(_hb_func, "__name__", "") == "_v702_a7_heartbeat_line"
                or (bool(getattr(_hb_func, "_v702_a17_diagnostics", False))
                    and getattr(_a17_hb_delegate, "__name__", "") == "_v702_a7_heartbeat_line")
            )
            checks["micro_handoff_authority_present"] = callable(globals().get("_v702_a7_micro_handoff_evidence")) and callable(globals().get("_v702_a7_micro_handoff_allowed"))
            checks["no_score_relief_below_70"] = _v704_hard_global_score_floor() >= 70.0
        except Exception:
            checks["a7_checks_exception"] = False
        failed = [k for k,v in checks.items() if not v]
        result = {"pass": bool(base_ok and all(checks.values())), "previous_validation": base_ok, "checks": checks, "failed": failed, "revision": V702_A7_CANONICAL_REVISION, "hard_gate_bypass": False}
        STATS["v702_a7_final_validation"] = result
        FINAL_CANONICAL_RUNTIME["v702_a7_terminal"] = {"revision":V702_A7_CANONICAL_REVISION,"release_tag":V702_A7_RELEASE_TAG,"terminal_authority":True,"hard_gate_bypass":False,"micro_handoff":"bounded_book_spread_fee_score_verified"}
        FINAL_CANONICAL_RUNTIME["final_validation"] = result
        return bool(result["pass"])
    globals()["validate_config"] = _v702_a7_validate_config
except Exception as _a7_val_exc:
    STATS["v702_a7_validation_wrapper_error"] = f"{type(_a7_val_exc).__name__}:{str(_a7_val_exc)[:160]}"

