def _v702_a12_selection_projection_self_test() -> Dict[str, Any]:
    """Offline regression for exact-only selection and short micro-fetch retry."""
    checks: Dict[str, bool] = {}
    details: Dict[str, Any] = {}
    old_status = globals().get("_V702_R34_PROJECTION_STATUS")
    old_history = globals().get("_V702_R30_MICRO_SCAN_HISTORY")
    old_relief = globals().get("_v704_starvation_score_floor_override")
    old_config = {
        k: CONFIG.get(k) for k in (
            "ENABLE_LIVE_TRADING", "PAPER_TRADING_MODE", "MIN_LIVE_SCORE",
            "V702_ELITE_LIVE_QUALITY_GATE_ENABLE", "V704_STARVATION_SCORE_RELIEF_FLOOR",
            "V702_R30_MICRO_RECALL_RECENT_SCAN_TTL_SEC", "V702_R30_MICRO_RECALL_FAILED_RETRY_SEC",
        )
    }
    try:
        try:
            from types import SimpleNamespace as _A12NS
        except Exception:
            class _A12NS:
                def __init__(self, **kw): self.__dict__.update(kw)
        candidate = _A12NS(symbol="A12TEST/USDT", family="PULLBACK", strategy_mode="PULLBACK",
                           strategy_style="SCALP", macro_regime="BULLISH", features_snapshot={})
        snap = {"symbol":"A12TEST/USDT", "cycle_id":"A12-CYCLE", "candidate_id":"A12-CANDIDATE",
                "candle_ts":"A12-CANDLE", "regime":"BULLISH"}
        _expected_projection_floor = max(
            float(CONFIG.get("MIN_LIVE_SCORE", 70.0)),
            float(_v702_live_quality_score_floor({"family":"PULLBACK", "strategy_mode":"PULLBACK", "features_snapshot":{}})),
        )
        status = {"score":65.0, "effective_floor":_expected_projection_floor, "canonical_floor":70.0,
                  "complete":True, "symbol":"A12TEST/USDT", "candidate_object_id":id(candidate),
                  "candidate_id":"A12-CANDIDATE", "candle_ts":"A12-CANDLE",
                  "cycle_id":"A12-CYCLE", "ts":float(WALL_NOW())}
        globals()["_V702_R34_PROJECTION_STATUS"] = {"A12TEST/USDT": dict(status)}
        low = _v702_r5_projection_disposition(candidate, snap, 65.0, 0.81, blend_weight=0.40)
        checks["complete_exact_underfloor_is_preselected_out"] = bool(
            low.get("complete") and low.get("hard_block")
            and abs(float(low.get("floor", -1.0)) - _expected_projection_floor) < 1e-9
        )

        globals()["_V702_R34_PROJECTION_STATUS"] = {"A12TEST/USDT": dict(status, complete=False)}
        incomplete = _v702_r5_projection_disposition(candidate, snap, 65.0, 0.81, blend_weight=0.40)
        checks["incomplete_projection_keeps_original_arbiter_rank"] = bool(
            not incomplete.get("complete") and not incomplete.get("hard_block")
            and abs(float(incomplete.get("ranking_score", -1)) - 0.81) < 1e-9
        )

        globals()["_V702_R34_PROJECTION_STATUS"] = {"A12TEST/USDT": dict(status, score=80.0, effective_floor=_expected_projection_floor)}
        high = _v702_r5_projection_disposition(candidate, snap, 80.0, 0.70, blend_weight=0.40)
        checks["complete_passing_projection_only_blends_after_proof"] = bool(
            high.get("complete") and not high.get("hard_block") and high.get("status") == "EXACT_PASS_BLEND"
            and abs(float(high.get("ranking_score", -1)) - 0.74) < 1e-9
        )

        globals()["_V702_R34_PROJECTION_STATUS"] = {"A12TEST/USDT": dict(status, ts=float(WALL_NOW())-120.0)}
        stale = _v702_r5_projection_disposition(candidate, snap, 65.0, 0.81, blend_weight=0.40)
        checks["stale_projection_keeps_original_arbiter_rank"] = bool(
            not stale.get("complete") and not stale.get("hard_block")
            and abs(float(stale.get("ranking_score", -1)) - 0.81) < 1e-9
        )

        # Starvation relief must be reflected in the score floor used by exact
        # projection; otherwise a valid 70–75 score would be wrongly pre-blocked.
        CONFIG["ENABLE_LIVE_TRADING"] = True
        CONFIG["PAPER_TRADING_MODE"] = False
        CONFIG["MIN_LIVE_SCORE"] = 70.0
        CONFIG["V702_ELITE_LIVE_QUALITY_GATE_ENABLE"] = True
        CONFIG["V704_STARVATION_SCORE_RELIEF_FLOOR"] = 70.0
        globals()["_v704_starvation_score_floor_override"] = lambda opp, score, elite: (True, {"applied":True, "effective_floor":70.0})
        floors = _v702_projected_builder_score_floors(candidate, snap, 74.7, {})
        checks["projected_floor_mirrors_bounded_starvation_relief"] = bool(
            floors.get("is_live") and floors.get("relief_applied") and abs(float(floors.get("effective_floor", -1))-70.0)<1e-9
        )

        CONFIG["V702_R30_MICRO_RECALL_RECENT_SCAN_TTL_SEC"] = 300.0
        CONFIG["V702_R30_MICRO_RECALL_FAILED_RETRY_SEC"] = 60.0
        globals()["_V702_R30_MICRO_SCAN_HISTORY"] = {"MICROTEST/USDT": 900.0}
        _v702_r30_note_scan_result("MICROTEST/USDT", False, now=1100.0)
        failed_ts = float(globals()["_V702_R30_MICRO_SCAN_HISTORY"]["MICROTEST/USDT"])
        checks["failed_micro_fetch_uses_short_retry_backoff"] = abs((1100.0-failed_ts)-240.0)<1e-9
        _v702_r30_note_scan_result("MICROTEST/USDT", True, now=1200.0)
        checks["successful_micro_scan_refreshes_full_cooldown"] = float(globals()["_V702_R30_MICRO_SCAN_HISTORY"]["MICROTEST/USDT"]) == 1200.0
        details["failed_fetch_retry_sec"] = float(CONFIG.get("V702_R30_MICRO_RECALL_FAILED_RETRY_SEC", 60.0))
        details["successful_scan_ttl_sec"] = float(CONFIG.get("V702_R30_MICRO_RECALL_RECENT_SCAN_TTL_SEC", 300.0))
        details["selection_policy"] = "EXACT_COMPLETE_FRESH_ONLY; INCOMPLETE_OR_STALE_KEEP_CANONICAL_RANK"
    except Exception as exc:
        checks["exception_free"] = False
        details["error"] = f"{type(exc).__name__}:{str(exc)[:180]}"
    finally:
        if old_status is None: globals().pop("_V702_R34_PROJECTION_STATUS", None)
        else: globals()["_V702_R34_PROJECTION_STATUS"] = old_status
        if old_history is None: globals().pop("_V702_R30_MICRO_SCAN_HISTORY", None)
        else: globals()["_V702_R30_MICRO_SCAN_HISTORY"] = old_history
        if old_relief is None: globals().pop("_v704_starvation_score_floor_override", None)
        else: globals()["_v704_starvation_score_floor_override"] = old_relief
        for key, value in old_config.items():
            if value is None: CONFIG.pop(key, None)
            else: CONFIG[key] = value
    return {"pass": bool(checks and all(checks.values())), "checks": checks,
            "failed": [k for k,v in checks.items() if not v], "details": details,
            "revision": "A12-SELECTOR-PARITY-MICRO-RETRY-CLOSURE",
            "live_gates_relaxed": False, "hard_gate_bypass": False}

