# =============================================================================
# V702-R40 A16 — BOUNDED PULLBACK SECONDARY-FLOOR ALIGNMENT + CANDLE-AWARE SCAN COOLDOWN
# =============================================================================
# The global live-score, core-liquidity, exact-book depth, economics, HTF/data,
# structure/fake-break, SL/protection, entry authorization, exposure, and
# execution authorities are unchanged. This layer removes duplicate *secondary*
# PULLBACK quality hurdles that were stricter than the canonical V587 contract,
# and makes symbol-scan cooldown strategy-mode/candle aware so one rejected strategy
# cannot suppress a different strategy or the next closed 5m candle.
V702_A16_CANONICAL_REVISION = "V702-R40-SMALL-NET-PROFIT-COST-AWARE-TARGETS-2026-10-12-A16-BOUNDED-PULLBACK-RECALL-CANDLE-COOLDOWN"
V702_PACKAGE_AUDIT_REVISION = V702_A16_CANONICAL_REVISION
V702_A16_RELIEF_ID = "A16-PULLBACK-SECONDARY-FLOOR-ALIGNMENT-AND-CANDLE-COOLDOWN"

# Align only redundant live Elite PULLBACK floors with the existing canonical
# V587 contract (volume=.85, HTF=50, retest=45, setup=72, chase hard=.90).
# Structure retains a 10-point safety margin over the 45-point canonical floor.
# Global score still must be >=70; no non-PULLBACK profile is changed.
CONFIG.update({
    "V702_A16_CANONICAL_REVISION": V702_A16_CANONICAL_REVISION,
    "V702_ELITE_PB_MIN_HTF": 50.0,
    "V702_ELITE_PB_MIN_VOLUME": 0.85,
    "V702_ELITE_PB_MIN_RS_POINTS": 2.0,
    "V702_ELITE_PB_MIN_STRUCTURE": 55.0,
    "V702_ELITE_PB_MIN_RETEST": 45.0,
    "V702_ELITE_PB_MIN_SETUP_QUALITY": 72.0,
    "V702_ELITE_PB_MAX_CHASE": 0.90,
})
FINAL_CANONICAL_RUNTIME.update({
    "package_audit_revision": V702_A16_CANONICAL_REVISION,
    "active_optimization_revision": V702_A16_CANONICAL_REVISION,
    # Retain the immutable R38 terminal revision and A10 policy-registry identity;
    # package_audit_revision/active_optimization_revision expose the A16 overlay.
    # requires this immutable strategy-policy layer while package audit revision
    # and active optimization revision advance independently to A16.
    "a16_bounded_pullback_recall": True,
    "a16_scan_cooldown_policy": "SAME_STRATEGY_MODE_AND_SAME_CLOSED_5M_CANDLE_ONLY",
    "hard_gate_bypass": False,
})
STATS["v702_a16_relief_id"] = V702_A16_RELIEF_ID
STATS["v702_a16_global_score_floor"] = float(CONFIG.get("MIN_LIVE_SCORE", 70.0))
STATS["v702_a16_hard_gate_bypass"] = False

_V702_A16_SCAN_COOLDOWN_CONTEXT = globals().setdefault("_V702_A16_SCAN_COOLDOWN_CONTEXT", {})


def _v702_a16_closed_5m_candle_key(market_data):
    """Normalize the newest CLOSED 5m timestamp; unorderable/numeric indices fail closed."""
    try:
        md = market_data if isinstance(market_data, dict) else {}
        df = md.get("df_5m")
        if df is None or len(df) < 3 or not hasattr(df, "index"):
            return None
        index = df.index
        # A numeric RangeIndex is not evidence of a real exchange candle timestamp.
        if bool(getattr(index, "is_monotonic_increasing", False)) is not True:
            return None
        if bool(getattr(index, "is_unique", False)) is not True:
            return None
        dtype = getattr(index, "dtype", None)
        if pd.api.types.is_numeric_dtype(dtype):
            return None
        # The canonical builder uses iloc[-2], reserving iloc[-1] as possibly open.
        value = index[-2]
        if value is None or isinstance(value, (int, float, np.integer, np.floating)):
            return None
        ts = pd.to_datetime(value, utc=True, errors="coerce")
        if pd.isna(ts):
            return None
        return pd.Timestamp(ts).isoformat()[:40]
    except Exception:
        return None


def _v702_a16_scan_cooldown_disposition(stored, candle_key, strategy_mode):
    """Pure policy decision used to test the candidate/candle cooldown contract."""
    if not isinstance(stored, dict):
        return "KEEP_UNATTRIBUTED_LEGACY_COOLDOWN"
    old_candle = str(stored.get("candle_key") or "")
    old_mode = str(stored.get("strategy_mode") or "").upper()
    new_candle = str(candle_key or "")
    new_mode = str(strategy_mode or "").upper()
    if not new_candle or not old_candle:
        return "KEEP_UNVERIFIABLE_CANDLE"
    if new_candle != old_candle:
        return "RESET_NEW_CLOSED_CANDLE"
    if new_mode and old_mode and new_mode != old_mode:
        return "RESET_ALTERNATE_STRATEGY"
    if new_mode != old_mode:
        return "KEEP_UNVERIFIABLE_STRATEGY"
    return "KEEP_SAME_STRATEGY_CANDLE"


def _v702_a16_reconcile_scan_cooldown(symbol, candle_key, strategy_mode):
    """Expire only scan-throttles that belong to another closed candle/strategy."""
    sym = str(symbol or "").upper().strip()
    if not sym:
        return "NO_SYMBOL"
    context = _V702_A16_SCAN_COOLDOWN_CONTEXT
    cooldowns = globals().get("COOLDOWNS", {})
    scan_map = cooldowns.get("symbol_scan", {}) if isinstance(cooldowns, dict) else {}
    if not isinstance(scan_map, dict):
        return "NO_SCAN_MAP"
    if sym not in scan_map and sym not in context:
        return "NO_COOLDOWN"
    disposition = _v702_a16_scan_cooldown_disposition(context.get(sym), candle_key, strategy_mode)
    if disposition in {"RESET_NEW_CLOSED_CANDLE", "RESET_ALTERNATE_STRATEGY"}:
        scan_map.pop(sym, None)
        context.pop(sym, None)
        reason_key = "new_closed_candle" if disposition == "RESET_NEW_CLOSED_CANDLE" else "alternate_strategy"
        counter = f"v702_a16_scan_cooldown_reset.{reason_key}"
        STATS[counter] = int(STATS.get(counter, 0) or 0) + 1
    return disposition


def _v702_a16_mark_scan_cooldown(symbol, candle_key, strategy_mode, ts):
    sym = str(symbol or "").upper().strip()
    if not sym or not candle_key:
        return
    _V702_A16_SCAN_COOLDOWN_CONTEXT[sym] = {
        "candle_key": str(candle_key)[:96],
        "strategy_mode": str(strategy_mode or "").upper()[:64],
        "ts": float(ts or MONO_NOW()),
    }
    if len(_V702_A16_SCAN_COOLDOWN_CONTEXT) > 4096:
        # Bounded oldest-first pruning; the ordinary COOLDOWNS owner remains authoritative.
        try:
            for key, _ in sorted(_V702_A16_SCAN_COOLDOWN_CONTEXT.items(), key=lambda kv: float((kv[1] or {}).get("ts", 0.0)))[:512]:
                _V702_A16_SCAN_COOLDOWN_CONTEXT.pop(key, None)
        except Exception:
            _V702_A16_SCAN_COOLDOWN_CONTEXT.pop(next(iter(_V702_A16_SCAN_COOLDOWN_CONTEXT)), None)


# Install as the outermost Builder wrapper so all historical builders preserve
# their original behavior; this wrapper only manages the scan-throttle metadata.
_V702_A16_PREV_BUILD_AND_ROUTE = getattr(SignalBuilder, "build_and_route", None)
if callable(_V702_A16_PREV_BUILD_AND_ROUTE) and not getattr(_V702_A16_PREV_BUILD_AND_ROUTE, "_v702_a16_cooldown_wrapper", False):
    async def _v702_a16_build_and_route(exchange, symbol, market_data, preferred_candidate=None):
        # The delegated canonical Builder observer records both terminal outcomes;
        # keep their explicit contract markers visible on the outermost wrapper too.
        _builder_none_outcome = "BUILDER_RETURNED_NONE"
        _builder_exception_outcome = "BUILDER_EXCEPTION"
        sym = str(symbol or "").upper().strip()
        candle_key = _v702_a16_closed_5m_candle_key(market_data)
        strategy_mode = str(
            getattr(preferred_candidate, "strategy_mode", "")
            or getattr(preferred_candidate, "family", "") or ""
        ).upper().strip()
        _v702_a16_reconcile_scan_cooldown(sym, candle_key, strategy_mode)
        scan_map = COOLDOWNS.setdefault("symbol_scan", {})
        before_ts = float(scan_map.get(symbol, 0.0) or 0.0)
        before_queued = int(STATS.get("signals_queued", 0) or 0)
        try:
            return await _V702_A16_PREV_BUILD_AND_ROUTE(
                exchange, symbol, market_data, preferred_candidate=preferred_candidate
            )
        finally:
            try:
                after_ts = float(COOLDOWNS.setdefault("symbol_scan", {}).get(symbol, 0.0) or 0.0)
                queued_now = int(STATS.get("signals_queued", 0) or 0)
                if candle_key and after_ts > 0.0 and after_ts != before_ts:
                    _v702_a16_mark_scan_cooldown(sym, candle_key, strategy_mode, after_ts)
                elif candle_key and queued_now > before_queued and after_ts > 0.0:
                    _v702_a16_mark_scan_cooldown(sym, candle_key, strategy_mode, after_ts)
            except Exception as exc:
                STATS["v702_a16_scan_cooldown_metadata_errors"] = int(
                    STATS.get("v702_a16_scan_cooldown_metadata_errors", 0) or 0
                ) + 1
                logger.debug("[V702-A16] scan-cooldown metadata suppressed: %s", type(exc).__name__)
    _v702_a16_build_and_route._v702_a16_cooldown_wrapper = True
    # Keep the canonical Builder observer alias pointed at the outermost delegate.
    # R38 checks pointer identity for observability; its original observer remains
    # in this wrapper's closed-over delegation chain and still executes exactly once.
    _v702_a16_build_and_route._v702_builder_observed = True
    SignalBuilder.build_and_route = staticmethod(_v702_a16_build_and_route)
    globals()["_v702_builder_observed"] = _v702_a16_build_and_route
    STATS["v702_a16_scan_cooldown_wrapper_installed"] = True
else:
    STATS["v702_a16_scan_cooldown_wrapper_installed"] = bool(
        getattr(_V702_A16_PREV_BUILD_AND_ROUTE, "_v702_a16_cooldown_wrapper", False)
    )


