STATS["v702_a17_severity_cache_max_entries"] = _V702_A17_SEVERITY_CACHE_MAX


def _v702_a17_frame_digest(frame, columns, *, tail_rows=None):
    """Fast content signature; a cache hit requires same object and same relevant bytes."""
    try:
        if frame is None or not hasattr(frame, "columns") or not hasattr(frame, "iloc"):
            return None
        if not all(c in frame.columns for c in columns):
            return None
        n = len(frame)
        if n < 3:
            return None
        start = 0 if tail_rows is None else max(0, n - max(1, int(tail_rows)))
        digest = hashlib.blake2b(digest_size=12)
        for col in columns:
            values = np.asarray(frame[col].iloc[start:], dtype=np.float64)
            digest.update(str(col).encode("utf-8", "replace"))
            digest.update(values.tobytes(order="C"))
        try:
            idx_closed = str(frame.index[-2])[:64]
            idx_last = str(frame.index[-1])[:64]
        except Exception:
            idx_closed = idx_last = ""
        return (n, idx_closed, idx_last, digest.hexdigest())
    except Exception:
        return None


def _v702_a17_macro_signature(df4):
    stamp = _v702_a17_frame_digest(df4, ("close",), tail_rows=None)
    if stamp is None:
        return None
    policy = (
        int(max(240, int(CONFIG.get("BTC_SHARED_CONTEXT_MIN_CANDLES_4H", 240) or 240))),
        float(CONFIG.get("REGIME_BULL_THRESHOLD_PCT", 0.5)),
        float(CONFIG.get("REGIME_BEAR_THRESHOLD_PCT", -0.5)),
    )
    return stamp + policy


def _v702_a17_macro_context_cached(df4):
    signature = _v702_a17_macro_signature(df4)
    cache_key = id(df4) if df4 is not None else 0
    if signature is not None:
        entry = _V702_A17_MACRO_CONTEXT_CACHE.get(cache_key)
        if entry is not None and entry[0] is df4 and entry[1] == signature:
            _V702_A17_MACRO_CONTEXT_CACHE.move_to_end(cache_key)
            STATS["v702_a17_macro_cache_hits"] = int(STATS.get("v702_a17_macro_cache_hits", 0) or 0) + 1
            return entry[2]
    STATS["v702_a17_macro_cache_misses"] = int(STATS.get("v702_a17_macro_cache_misses", 0) or 0) + 1
    result = _V702_A17_PREV_MACRO_CONTEXT(df4)
    try:
        regime, pct, reason = result
        valid = regime in {"BULLISH", "BEARISH", "NEUTRAL"} and pct is not None and math.isfinite(float(pct)) and not reason
    except Exception:
        valid = False
    if signature is not None and valid:
        _V702_A17_MACRO_CONTEXT_CACHE[cache_key] = (df4, signature, result)
        _V702_A17_MACRO_CONTEXT_CACHE.move_to_end(cache_key)
        while len(_V702_A17_MACRO_CONTEXT_CACHE) > _V702_A17_MACRO_CACHE_MAX:
            _V702_A17_MACRO_CONTEXT_CACHE.popitem(last=False)
    return result


def _v702_a17_severity_signature(df15, df4):
    try:
        atr_period = int(CONFIG.get("ATR_PERIOD", 14))
        win = int(CONFIG.get("V425_BEARISH_CRASH_WINDOW_15M", 8))
        n4 = int(CONFIG.get("V425_BEARISH_CRASH_WINDOW_4H", 3))
        need = int(CONFIG.get("V425_BEARISH_CRASH_BREAKDOWN_N", 3))
        tail_15 = max(22 + atr_period + 3, win + atr_period + 3, 32)
        sig15 = _v702_a17_frame_digest(df15, ("high", "low", "close"), tail_rows=tail_15)
        sig4 = _v702_a17_frame_digest(df4, ("low",), tail_rows=max(n4 + 3, 6))
        if sig15 is None or sig4 is None:
            return None
        policy = (
            atr_period, win, n4, need,
            float(CONFIG.get("V425_BEARISH_CRASH_DROP_PCT", -6.0)),
            float(CONFIG.get("V425_BEARISH_STRESSED_DROP_PCT", -3.0)),
            float(CONFIG.get("V425_BEARISH_CRASH_ATR_MULT", 2.5)),
            int(max(240, int(CONFIG.get("BTC_SHARED_CONTEXT_MIN_CANDLES_4H", 240) or 240))),
        )
        return (sig15, sig4, policy)
    except Exception:
        return None


def _v702_a17_bearish_severity_cached(df15, df4):
    signature = _v702_a17_severity_signature(df15, df4)
    cache_key = (id(df15), id(df4)) if df15 is not None and df4 is not None else (0, 0)
    if signature is not None:
        entry = _V702_A17_BEARISH_SEVERITY_CACHE.get(cache_key)
        if entry is not None and entry[0] is df15 and entry[1] is df4 and entry[2] == signature:
            _V702_A17_BEARISH_SEVERITY_CACHE.move_to_end(cache_key)
            STATS["v702_a17_severity_cache_hits"] = int(STATS.get("v702_a17_severity_cache_hits", 0) or 0) + 1
            return entry[3]
    STATS["v702_a17_severity_cache_misses"] = int(STATS.get("v702_a17_severity_cache_misses", 0) or 0) + 1
    result = _V702_A17_PREV_BEARISH_SEVERITY(df15, df4)
    try:
        severity, reason = result
        valid = reason in {"bearish_crash_confirmed", "bearish_stressed", "bearish_normal"} and bool(severity)
    except Exception:
        valid = False
    if signature is not None and valid:
        _V702_A17_BEARISH_SEVERITY_CACHE[cache_key] = (df15, df4, signature, result)
        _V702_A17_BEARISH_SEVERITY_CACHE.move_to_end(cache_key)
        while len(_V702_A17_BEARISH_SEVERITY_CACHE) > _V702_A17_SEVERITY_CACHE_MAX:
            _V702_A17_BEARISH_SEVERITY_CACHE.popitem(last=False)
    return result


