def _v702_a17_filter_macro_market_data(market_data_map):
    """Remove only entries lacking verified shared BTC 4H macro facts, before engine fan-out."""
    valid = {}
    reasons = defaultdict(int)
    try:
        items = market_data_map.items() if isinstance(market_data_map, dict) else ()
        seen = 0
        for symbol, md in items:
            seen += 1
            if not isinstance(md, dict):
                reasons["market_data_not_mapping"] += 1
                continue
            frame = md.get("df_btc_4h")
            regime, pct, reason = _v702_r36_macro_context(frame)
            if regime not in {"BULLISH", "BEARISH", "NEUTRAL"} or pct is None or not math.isfinite(float(pct)):
                reasons[str(reason or "macro_context_unknown")[:80]] += 1
                continue
            valid[symbol] = md
        STATS["v702_a17_macro_prefilter_seen"] = int(STATS.get("v702_a17_macro_prefilter_seen", 0) or 0) + seen
        STATS["v702_a17_macro_prefilter_pass"] = int(STATS.get("v702_a17_macro_prefilter_pass", 0) or 0) + len(valid)
        STATS["v702_a17_macro_prefilter_blocked"] = int(STATS.get("v702_a17_macro_prefilter_blocked", 0) or 0) + (seen - len(valid))
        STATS["v702_a17_macro_prefilter_last"] = {
            "seen": seen, "pass": len(valid), "blocked": seen - len(valid),
            "reasons": dict(sorted(reasons.items(), key=lambda kv: (-kv[1], kv[0]))[:5]),
            "fail_closed": True,
        }
    except Exception as exc:
        STATS["v702_a17_macro_prefilter_errors"] = int(STATS.get("v702_a17_macro_prefilter_errors", 0) or 0) + 1
        logger.debug("[V702-A17] macro prefilter failed closed: %s", type(exc).__name__)
        return {}
    return valid


def _v702_a17_rank_and_select(cls, market_data_map):
    filtered = _v702_a17_filter_macro_market_data(market_data_map)
    if not filtered:
        # The prior rank implementation returns early on an empty mapping before
        # clearing its per-run MSE counts. Reset them here so an all-invalid macro
        # cycle cannot inherit a previous cycle's generated/ranked/winner totals.
        try:
            _MSEState.reset_run_counts()
            STATS["v702_a17_empty_macro_cycle_counts_reset"] = int(
                STATS.get("v702_a17_empty_macro_cycle_counts_reset", 0) or 0
            ) + 1
        except Exception as exc:
            STATS["v702_a17_empty_macro_cycle_reset_errors"] = int(
                STATS.get("v702_a17_empty_macro_cycle_reset_errors", 0) or 0
            ) + 1
            logger.debug("[V702-A17] empty-cycle count reset suppressed: %s", type(exc).__name__)
    return _V702_A17_PREV_RANK_AND_SELECT(filtered)

_v702_a17_rank_and_select._v702_a17_macro_quarantine = True
