def _v702_a17_production_self_test():
    checks = {}
    details = {}
    # Preserve live cache/telemetry state while exercising with isolated synthetic frames.
    old_macro_cache = OrderedDict(_V702_A17_MACRO_CONTEXT_CACHE)
    old_severity_cache = OrderedDict(_V702_A17_BEARISH_SEVERITY_CACHE)
    counter_keys = (
        "v702_a17_macro_cache_hits", "v702_a17_macro_cache_misses",
        "v702_a17_severity_cache_hits", "v702_a17_severity_cache_misses",
        "v702_a17_macro_prefilter_seen", "v702_a17_macro_prefilter_pass",
        "v702_a17_macro_prefilter_blocked", "v702_a17_macro_prefilter_errors",
        "v702_a17_macro_prefilter_last",
    )
    old_counters = {k: STATS.get(k, None) for k in counter_keys}
    try:
        _V702_A17_MACRO_CONTEXT_CACHE.clear()
        _V702_A17_BEARISH_SEVERITY_CACHE.clear()
        i4 = pd.date_range("2026-01-01", periods=260, freq="4h", tz="UTC")
        close4 = np.linspace(50.0, 110.0, 260)
        df4 = pd.DataFrame({"close": close4, "low": close4 - 0.8, "high": close4 + 0.8}, index=i4)
        m1 = _v702_r36_macro_context(df4)
        m2 = _v702_r36_macro_context(df4)
        checks["valid_macro_context_reused"] = m1 == m2 and m1[0] in {"BULLISH", "BEARISH", "NEUTRAL"} and int(STATS.get("v702_a17_macro_cache_hits", 0) or 0) >= 1
        checks["macro_cache_bounded"] = len(_V702_A17_MACRO_CONTEXT_CACHE) <= _V702_A17_MACRO_CACHE_MAX

        i15 = pd.date_range("2026-10-01", periods=64, freq="15min", tz="UTC")
        close15 = np.linspace(70.0, 71.0, len(i15))
        df15 = pd.DataFrame({"close": close15, "high": close15 + 0.6, "low": close15 - 0.6}, index=i15)
        z1 = _v702_r36_bearish_severity(df15, df4)
        z2 = _v702_r36_bearish_severity(df15, df4)
        checks["valid_severity_context_reused"] = z1 == z2 and z1[1] in {"bearish_crash_confirmed", "bearish_stressed", "bearish_normal"} and int(STATS.get("v702_a17_severity_cache_hits", 0) or 0) >= 1
        checks["severity_cache_bounded"] = len(_V702_A17_BEARISH_SEVERITY_CACHE) <= _V702_A17_SEVERITY_CACHE_MAX

        _short = df4.iloc[:100].copy()
        blocked = _v702_a17_filter_macro_market_data({
            "OK/USDT": {"df_btc_4h": df4},
            "MISSING/USDT": {"df_btc_4h": None},
            "SHORT/USDT": {"df_btc_4h": _short},
        })
        checks["invalid_macro_context_filtered_before_engines"] = list(blocked) == ["OK/USDT"]
        checks["shared_macro_policy_remains_fail_closed"] = _v702_r36_macro_context(None)[0] == "UNKNOWN" and _v702_r36_macro_context(_short)[0] == "UNKNOWN"

        chase_profile = _v702_elite_profile({"family": "PULLBACK", "strategy_mode": "PULLBACK", "features_snapshot": {"setup_quality": 72.0}})
        checks["pullback_chase_ceiling_matches_canonical_contract"] = abs(float(chase_profile.get("chase", float("nan"))) - 0.90) < 1e-9
        checks["rank_prefilter_installed"] = bool(STATS.get("v702_a17_rank_prefilter_installed", False)) and bool(getattr(GlobalOpportunityBrain.rank_and_select, "__func__", GlobalOpportunityBrain.rank_and_select).__dict__.get("_v702_a17_macro_quarantine", True))
        checks["operator_diagnostics_installed"] = bool(STATS.get("v702_a17_operator_diagnostics_installed", False))
        checks["hard_gate_bypass_off"] = FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass", False) is False
        checks["spot_long_only_unchanged"] = bool(CONFIG.get("LONG_ONLY", True)) and str(CONFIG.get("MARKET_TYPE", "SPOT")).upper() == "SPOT" and not bool(CONFIG.get("FUTURES_ENABLED", False)) and not bool(CONFIG.get("ENABLE_FUTURES", False)) and not bool(CONFIG.get("ALLOW_SHORT", False))
        checks["core_liquidity_floor_unchanged"] = float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 3_000_000.0)) >= 3_000_000.0
        checks["score_floor_unchanged"] = float(CONFIG.get("MIN_LIVE_SCORE", 70.0)) >= 70.0
        checks["micro_depth_floor_unchanged"] = float(CONFIG.get("V45_TIER_MICRO_MIN_DEPTH_RATIO", 1.90)) >= 1.90
        checks["denylist_unchanged"] = {"AERO", "BNB", "CAKE", "ETHFI", "PUMP"}.issubset(set(V702_HARD_FORBIDDEN_BASES))
        checks["trade_cap_unchanged"] = int(CONFIG.get("MAX_CONCURRENT_TRADES", 2)) <= 2 and float(CONFIG.get("MAX_ENTRY_NOTIONAL_USDT", 75.0)) <= 75.0
        checks["unverified_candle_identity_fails_closed"] = _v702_a16_closed_5m_candle_key({"df_5m": pd.DataFrame({"close": [1, 2, 3]})}) is None
        details = {
            "macro_cache_entries": len(_V702_A17_MACRO_CONTEXT_CACHE),
            "severity_cache_entries": len(_V702_A17_BEARISH_SEVERITY_CACHE),
            "macro_probe": {"regime": m1[0], "reason": m1[2]},
            "severity_probe": {"severity": z1[0], "reason": z1[1]},
            "prefilter_probe": STATS.get("v702_a17_macro_prefilter_last", {}),
            "execution_policy_changed": False,
            "gates_relaxed": False,
        }
    except Exception as exc:
        checks["exception_free"] = False
        details["error"] = f"{type(exc).__name__}:{str(exc)[:180]}"
    finally:
        _V702_A17_MACRO_CONTEXT_CACHE.clear()
        _V702_A17_MACRO_CONTEXT_CACHE.update(old_macro_cache)
        _V702_A17_BEARISH_SEVERITY_CACHE.clear()
        _V702_A17_BEARISH_SEVERITY_CACHE.update(old_severity_cache)
        for key, value in old_counters.items():
            if value is None:
                STATS.pop(key, None)
            else:
                STATS[key] = value
    report = {
        "pass": bool(checks and all(checks.values())), "checks": checks,
        "failed": [k for k, v in checks.items() if not v], "details": details,
        "revision": V702_A17_CANONICAL_REVISION, "hard_gate_bypass": False,
        "execution_policy_changed": False, "gates_relaxed": False,
        "macro_cache_max_entries": _V702_A17_MACRO_CACHE_MAX,
        "severity_cache_max_entries": _V702_A17_SEVERITY_CACHE_MAX,
    }
    STATS["v702_a17_production_self_test"] = report
    FINAL_CANONICAL_RUNTIME["v702_a17_production_self_test"] = report
    return report


