# =============================================================================
# V702-R40 A22 — PRE-REPRICE TP1 STARVATION CLOSURE + SHADOW-ONLY DIAGNOSTICS
# =============================================================================
_A22_PREQUAL_ORIGINAL = globals().get("_v453_prequalify")
_V702_A22_LAST_REPORT_MONO = 0.0

def _v702_a22_capture_prequal_result(ranked_candidate, snap_by_symbol, result):
    """Observability-only capture of live prequalification rejects; returns input unchanged."""
    try:
        if bool(globals().get("_V699_VALIDATE_ONLY_REQUEST", False)):
            return result
        ok, reason = result if isinstance(result, tuple) and len(result) >= 2 else (bool(result), "unknown")
        if ok:
            return result
        c = getattr(ranked_candidate, "candidate", ranked_candidate)
        symbol = str(getattr(c, "symbol", "?") or "?")
        family = str(getattr(c, "family", "") or getattr(c, "strategy_mode", "") or "UNKNOWN").upper()
        mode = str(getattr(c, "strategy_mode", "") or family).upper()
        fs = getattr(c, "features_snapshot", {}) or {}
        fs = fs if isinstance(fs, dict) else {}
        snap = (snap_by_symbol or {}).get(symbol, {}) if isinstance(snap_by_symbol, dict) else {}
        snap = snap if isinstance(snap, dict) else {}
        reason = str(reason or "unknown")[:180]
        counts = STATS.setdefault("v702_a22_prequal_reject_counts", {})
        counts[reason] = min(1_000_000, int(counts.get(reason, 0) or 0) + 1)
        if len(counts) > 64:
            keep = sorted(counts.items(), key=lambda kv: int(kv[1] or 0), reverse=True)[:48]
            STATS["v702_a22_prequal_reject_counts"] = counts = dict(keep)
        def _num(*values):
            for val in values:
                try:
                    if val is not None and math.isfinite(float(val)):
                        return float(val)
                except Exception:
                    continue
            return None
        detail = {
            "symbol": symbol, "family": family, "strategy_mode": mode, "reason": reason,
            "score": _num(getattr(c, "reviewed_score", None), getattr(c, "engine_score", None)),
            "htf_strength": _num(snap.get("htf_strength"), fs.get("htf_strength")),
            "volume_ratio": _num(fs.get("volume_ratio"), snap.get("volume_ratio")),
            "rs_5m": _num(fs.get("rs_5m"), fs.get("rs_score_val"), snap.get("rs_5m")),
            "chase_atr": _num(fs.get("chase_atr"), getattr(c, "chase_atr", None)),
            "quote_volume_usdt": _num(snap.get("quote_vol_24h"), fs.get("quote_vol_24h")),
            "tier": str(snap.get("tier", fs.get("liquidity_tier", "UNKNOWN")) or "UNKNOWN").upper(),
            "regime": str(snap.get("macro_regime", snap.get("regime", "UNKNOWN")) or "UNKNOWN").upper(),
            "local_regime": str(snap.get("local_regime", "UNKNOWN") or "UNKNOWN").upper(),
            "observation_scope": "PREQUAL_REJECTION_ONLY_NO_POLICY_CHANGE",
        }
        STATS["v702_a22_last_prequal_block"] = detail
        return result
    except Exception as exc:
        STATS["v702_a22_prequal_observer_errors"] = int(STATS.get("v702_a22_prequal_observer_errors", 0) or 0) + 1
        STATS["v702_a22_prequal_observer_last_error"] = type(exc).__name__
        return result

def _v702_a22_prequal_observer(ranked_candidate, snap_by_symbol):
    base = _A22_PREQUAL_ORIGINAL
    if not callable(base):
        return False, "a22_prequal_authority_unavailable"
    verdict = base(ranked_candidate, snap_by_symbol)
    return _v702_a22_capture_prequal_result(ranked_candidate, snap_by_symbol, verdict)

if callable(_A22_PREQUAL_ORIGINAL) and not getattr(_A22_PREQUAL_ORIGINAL, "_v702_a22_observed", False):
    _v702_a22_prequal_observer._v702_a22_observed = True
    _v702_a22_prequal_observer._v702_a22_original = _A22_PREQUAL_ORIGINAL
    # Preserve the established observer-chain contract for startup validation:
    # the A22 layer is outer telemetry only and still delegates to the A21/R39
    # canonical observer without changing verdicts.
    _v702_a22_prequal_observer._v702_cf_shadow_wrapped = bool(getattr(_A22_PREQUAL_ORIGINAL, "_v702_cf_shadow_wrapped", False))
    _v702_a22_prequal_observer._v702_cf_shadow_original = getattr(_A22_PREQUAL_ORIGINAL, "_v702_cf_shadow_original", None)
    globals()["_v453_prequalify"] = _v702_a22_prequal_observer

