def _v702_a22_terminal_self_test() -> Dict[str, Any]:
    checks: Dict[str, bool] = {}
    details: Dict[str, Any] = {}
    try:
        source = Path(__file__).read_text(encoding="utf-8", errors="replace")
        # The provisional check has no terminal return; the final post-reprice
        # SR-aware check remains the authoritative hard TP1 floor.
        pre = source.split("A22 FIX: this TP1 geometry is provisional.", 1)[-1].split("# ---- Daily circuit breaker (hard pre-gate) ----", 1)[0]
        post = source.split('"sr_aware_targets", _a22_tp1_diag', 1)[-1].split("# ---- v4.0.6 FIX #3", 1)[0]
        # A newer canonical package must be a monotonic extension of the A22
        # contract; equality here incorrectly rejects every later A23+ release.
        checks["canonical_a22_revision"] = bool(
            V702_PACKAGE_AUDIT_REVISION.startswith(V702_A22_CANONICAL_REVISION)
            and "A22-PRE-REPRICE-TP1" in V702_A22_CANONICAL_REVISION
        )
        checks["early_tp1_check_is_nonblocking"] = "return None" not in pre and "A22_PRE_REPRICE_TP1_FLOOR_WARNING" in pre
        checks["final_tp1_floor_stays_hard"] = "family_tp1_distance_below_floor" in source and "return None" in post
        checks["final_tp1_block_has_shortfall_details"] = all(k in source for k in ("tp1_distance_atr", "required_tp1_distance_atr", "shortfall_atr"))
        checks["htf_shadow_band_is_five_points"] = float(CONFIG.get("V702_CF_SHADOW_HTF_RELIEF_POINTS", 0.0)) == 5.0
        checks["htf_live_floor_helper_still_installed"] = callable(globals().get("_v702_effective_htf_floor"))
        pullback_floor = _v702_effective_htf_floor("PULLBACK", "PULLBACK", "BULLISH", "LOCAL_BULLISH", 60.0, {})
        strict_floor = _v702_effective_htf_floor("BREAKOUT_RETEST", "BREAKOUT_RETEST", "BULLISH", "LOCAL_BULLISH", 55.0, {})
        details["pullback_live_htf_floor"] = pullback_floor
        details["strict_live_htf_floor"] = strict_floor
        checks["shadow_band_does_not_lower_live_htf_floors"] = pullback_floor == 45.0 and strict_floor == 55.0
        checks["prequal_observer_preserves_original_authority"] = callable(_A22_PREQUAL_ORIGINAL) and callable(globals().get("_v453_prequalify"))
        checks["score_floor_unchanged"] = float(CONFIG.get("MIN_LIVE_SCORE", 0.0)) >= 70.0
        checks["core_liquidity_floor_unchanged"] = float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 0.0)) >= 3_000_000.0
        checks["spot_long_only_unchanged"] = bool(CONFIG.get("LONG_ONLY", False)) and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT" and not bool(CONFIG.get("ENABLE_FUTURES", False)) and not bool(CONFIG.get("ALLOW_SHORT", False))
        checks["candidate_drift_hard_guard_unchanged"] = float(CONFIG.get("V702_FINAL_ENTRY_MAX_DRIFT_ATR", 99.0)) <= 0.60
        checks["fake_break_hard_gate_remains_enabled"] = bool(CONFIG.get("V520_PREQUAL_FAKE_BREAK_ENABLE", False))
        checks["shadow_execution_disabled"] = not bool(CONFIG.get("V702_INTRADAY_SHADOW_LIVE_ENABLE", True))
    except Exception as exc:
        details["error"] = f"{type(exc).__name__}:{str(exc)[:200]}"
        checks.setdefault("exception_free", False)
    report = {
        "pass": bool(checks and all(checks.values())), "checks": checks,
        "failed": [k for k, v in checks.items() if not v], "details": details,
        "revision": V702_A22_CANONICAL_REVISION,
        "live_network_tested": False, "profitability_verified": False,
        "live_gates_relaxed": False, "hard_gate_bypass": False,
        "scope": "PRE_REPRICE_TP1_ONLY_DIAGNOSTIC; FINAL_GEOMETRY_AND_ALL_OTHER_GATES_HARD",
    }
    STATS["v702_a22_terminal_self_test"] = report
    FINAL_CANONICAL_RUNTIME["v702_a22_terminal_self_test"] = report
    return report


# =============================================================================
# V702-R40 A23 — LOCAL HISTORY PRE-RANK ADMISSION + CANONICAL FINAL CLOSURE
# =============================================================================
# Production logs showed short-history symbols (e.g. 75 local 4H rows) reaching
# discovery/selection and only then failing the mandatory MSE snapshot at the
# builder handoff. A23 applies the existing local-history contract at scanner
# admission, avoiding wasted ranking/build work while preserving the downstream
# validator and every live quality/economic/risk gate.
V702_A22_PREVIOUS_CANONICAL_REVISION = (
    "V702-R40-SMALL-NET-PROFIT-COST-AWARE-TARGETS-2026-10-13-"
    "A21-LIVE-PILOT-RELEASE-TIA-SUBMIT-HOLD-CLOSURE-A22-"
    "PRE-REPRICE-TP1-STARVATION-OBSERVABILITY-CLOSURE"
)
V702_A23_HISTORICAL_REVISION = V702_A22_PREVIOUS_CANONICAL_REVISION + "-A23-LOCAL-HISTORY-PRE-RANK-CLOSURE"
V702_A24_CANONICAL_REVISION = V702_A23_HISTORICAL_REVISION + "-A24-TRUTHFUL-STARVATION-TELEMETRY-EXACT-ATTRIBUTION-CLOSURE"
# Older variable names remain aliases for backward compatibility; the new
# canonical package/audit revision is explicit and monotonic at A24.
V702_A23_CANONICAL_REVISION = V702_A24_CANONICAL_REVISION
V702_A22_CANONICAL_REVISION = V702_A24_CANONICAL_REVISION
V702_A21_CANONICAL_REVISION = V702_A24_CANONICAL_REVISION
V702_PACKAGE_AUDIT_REVISION = V702_A24_CANONICAL_REVISION
CONFIG["V702_A23_LOCAL_HISTORY_PRE_RANK_ENABLE"] = True
FINAL_CANONICAL_RUNTIME.update({
    "package_audit_revision": V702_A23_CANONICAL_REVISION,
    "active_optimization_revision": V702_A23_CANONICAL_REVISION,
    "a23_local_history_pre_rank_gate": True,
    "a23_local_history_contract": "SAME_MINIMUMS_AS_VALIDATE_MSE_SNAPSHOT; FAIL_CLOSED; NO_SYNTHETIC_ROWS",
    "a23_builder_snapshot_validation_retained": True,
    "a23_live_policy_changed": False,
    "a23_live_gates_relaxed": False,
    "hard_gate_bypass": False,
})


def _v702_a23_terminal_self_test() -> Dict[str, Any]:
    """Behavioral A23 local-history contract; independent of source formatting."""
    checks: Dict[str, bool] = {}
    details: Dict[str, Any] = {}
    try:
        checks["current_revision_aliases_coherent"] = (
            V702_PACKAGE_AUDIT_REVISION.startswith(V702_A25_CANONICAL_REVISION)
            and V702_A24_CANONICAL_REVISION in V702_PACKAGE_AUDIT_REVISION
            and V702_A24_CANONICAL_REVISION == V702_A23_CANONICAL_REVISION
            == V702_A22_CANONICAL_REVISION == V702_A21_CANONICAL_REVISION
        )
        checks["builder_snapshot_validation_retained"] = callable(globals().get("validate_mse_snapshot"))
        checks["scan_admission_callable"] = callable(globals().get("_mse_candidate_scan_admit"))
        checks["local_history_contract_uses_bounded_50_closed_4h_floor"] = (
            callable(globals().get("_v702_a32_local_4h_min_closed_candles"))
            and 50 <= int(_v702_a32_local_4h_min_closed_candles()) <= 210
        )
        checks["spot_long_only_and_futures_off"] = bool(
            CONFIG.get("LONG_ONLY", False) and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT"
            and not bool(CONFIG.get("ENABLE_FUTURES", False))
            and not bool(CONFIG.get("FUTURES_ENABLED", False))
            and not bool(CONFIG.get("ALLOW_SHORT", False))
            and not bool(CONFIG.get("ALLOW_SHORTS", False))
        )
        checks["score_and_liquidity_floors_unchanged"] = (
            float(CONFIG.get("MIN_LIVE_SCORE", 0.0)) >= 70.0
            and float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 0.0)) >= 3_000_000.0
        )
        checks["paper_floor_is_separate_from_live_floor"] = float(CONFIG.get("MIN_PAPER_SCORE", 70.0)) < float(CONFIG.get("MIN_LIVE_SCORE",70.0)) and float(CONFIG.get("MIN_LIVE_SCORE",70.0)) >= 70.0
        checks["forbidden_assets_preserved"] = {"AERO", "BNB", "CAKE", "ETHFI", "PUMP"}.issubset(set(V702_HARD_FORBIDDEN_BASES))
        checks["hard_gate_bypass_disabled"] = FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass", True) is False
        if _PDNP_OK and pd is not None:
            def _frame(_rows: int):
                return pd.DataFrame({"open": [1.0] * _rows, "high": [1.1] * _rows,
                                     "low": [0.9] * _rows, "close": [1.0] * _rows,
                                     "volume": [10.0] * _rows})
            _frames_ok = {"df_4h": _frame(210), "df_1h": _frame(240), "df_15m": _frame(350), "df_5m": _frame(30)}
            _valid, _valid_reason = _mse_candidate_scan_precheck(_frames_ok)
            _frames_short_ok = dict(_frames_ok)
            _frames_short_ok["df_4h"] = _frame(75)
            _short_ok, _short_reason = _mse_candidate_scan_precheck(_frames_short_ok)
            _frames_too_short = dict(_frames_ok)
            _frames_too_short["df_4h"] = _frame(49)
            _too_short_ok, _too_short_reason = _mse_candidate_scan_precheck(_frames_too_short)
            _commits = []
            _blocked, _blocked_reason = _mse_candidate_scan_admit(_frames_too_short, lambda: _commits.append("blocked"))
            _admitted, _admitted_reason = _mse_candidate_scan_admit(_frames_short_ok, lambda: _commits.append("admitted"))
            checks["full_local_history_still_passes"] = bool(_valid and _valid_reason == "ok")
            checks["short_but_usable_4h_history_is_admitted"] = bool(_short_ok and _short_reason == "ok")
            checks["below_minimum_4h_history_rejected_before_rank"] = not _too_short_ok and str(_too_short_reason).startswith("df_4h:short_rows:")
            checks["rejected_candidate_never_commits"] = not _blocked and str(_blocked_reason).startswith("df_4h:short_rows:") and _commits == ["admitted"]
            checks["usable_candidate_commits_exactly_once"] = _admitted and _admitted_reason == "ok" and _commits == ["admitted"]
            details["short_history_probe_reason"] = _too_short_reason
            details["admission_probe_reason"] = _blocked_reason
        else:
            checks["pandas_available_for_history_contract"] = False
    except Exception as exc:
        checks["exception_free"] = False
        details["error"] = f"{type(exc).__name__}:{str(exc)[:180]}"
    report = {"pass": bool(checks and all(checks.values())), "checks": checks,
              "failed": [k for k, v in checks.items() if not v], "details": details,
              "revision": V702_A24_CANONICAL_REVISION, "live_network_tested": False,
              "profitability_verified": False, "live_gates_relaxed": False,
              "hard_gate_bypass": False,
              "scope": "BEHAVIORAL_LOCAL_HISTORY_PRE_RANK_ADMISSION; BUILDER_VALIDATION_AND_ALL_LIVE_GATES_RETAINED"}
    STATS["v702_a23_terminal_self_test"] = report
    FINAL_CANONICAL_RUNTIME["v702_a23_terminal_self_test"] = report
    return report


def _v702_a24_terminal_self_test() -> Dict[str, Any]:
    """Terminal regression for starvation telemetry, exact attribution and digest truth."""
    checks: Dict[str, bool] = {}
    details: Dict[str, Any] = {}
    _stale_key = None
    _stale_store = None
    _stale_prior = None
    _stale_prior_existed = False
    try:
        checks["a24_revision_is_preserved_under_monotonic_release_closure"] = (
            V702_PACKAGE_AUDIT_REVISION.startswith(V702_A25_CANONICAL_REVISION)
            and V702_A24_CANONICAL_REVISION in V702_PACKAGE_AUDIT_REVISION
            and "A24-TRUTHFUL-STARVATION-TELEMETRY-EXACT-ATTRIBUTION-CLOSURE" in V702_A24_CANONICAL_REVISION
            and "A25-STARTUP-VALIDATION-ORDER-DIAGNOSTICS-CLOSURE" in V702_A25_CANONICAL_REVISION
        )
        checks["hard_global_floor_never_below_70"] = _v704_hard_global_score_floor() >= 70.0
        checks["no_send_source_rule_is_conservative"] = callable(_v704_no_send_age_sources) and callable(_v704_no_send_age_sec)
        checks["scan_admission_is_behavioral"] = callable(_mse_candidate_scan_admit)
        checks["builder_reason_lookup_is_candidate_exact"] = callable(_v702_builder_rejection_reason_for_candidate)
        checks["digest_stage_classifier_callable"] = callable(_V702R28TelegramDigest.classify)
        checks["scorer_route_builder_queues_present"] = all(hasattr(_V702R28TelegramDigest, k) for k in ("_scorer_blocks", "_route_blocks", "_selected_blocks"))
        checks["score_block_stage_registered"] = "SCORE_BLOCK" in V702PipelineMetrics.STAGES
        checks["exact_builder_event_fallback_callable"] = callable(_v702_builder_rejection_reason_for_candidate)
        checks["telegram_funnel_requires_committed_opportunity"] = callable(_v702_candidate_telegram_enqueue_allowed)
        checks["live_floor_unchanged"] = float(CONFIG.get("MIN_LIVE_SCORE", 0.0)) >= 70.0
        checks["paper_floor_remains_non_live"] = float(CONFIG.get("MIN_PAPER_SCORE", 70.0)) < float(CONFIG.get("MIN_LIVE_SCORE",70.0))
        checks["risk_authority_unchanged"] = bool(CONFIG.get("LONG_ONLY", False)) and not bool(CONFIG.get("ENABLE_FUTURES", False)) and not bool(CONFIG.get("ALLOW_SHORT", False)) and FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass", True) is False
        checks["no_new_validate_wrapper"] = "A24" in V702_PACKAGE_AUDIT_REVISION and not callable(globals().get("_V702_A24_PREV_VALIDATE_CONFIG"))
        # Exercise the exact stage classifier without touching dispatcher/network.
        checks["score_block_classified_as_scorer"] = _V702R28TelegramDigest.classify("Selected → Builder BLOCK\nSOL/USDT\nroot=SCORE\nstage=scorer\nreason=score_below_threshold:65.0<70.0") == "scorer_block"
        checks["route_block_classified_as_route"] = _V702R28TelegramDigest.classify("Selected → Builder BLOCK\nSOL/USDT\nroot=POLICY\nstage=selected_preexec_policy\nreason=blocked") == "route_block"
        checks["true_builder_block_keeps_builder_category"] = _V702R28TelegramDigest.classify("Selected → Builder BLOCK\nSOL/USDT\nroot=BUILDER\nstage=builder\nreason=builder_returned_none") == "builder_block"
        # The helper must distinguish eligible 70+ near-miss from <70 without
        # changing any downstream structural/economic authorization gate.
        _saved = {k: STATS.get(k) for k in ("v45_no_send_sec", "last_signal_sent_ts", "v681_runtime_cycle_ranked", "v681_runtime_cycle_selected")}
        _saved_last_send = getattr(V422StarvationAlerter, "_last_send_ts", None)
        _saved_truth = globals().get("_v699_truthful_starvation_snapshot")
        _saved_hazard = globals().get("_v704_market_hazard")
        _saved_wall_now_present = "WALL_NOW" in globals()
        _saved_mono_now_present = "MONO_NOW" in globals()
        _saved_wall_now = globals().get("WALL_NOW")
        _saved_mono_now = globals().get("MONO_NOW")
        try:
            # Freeze both clocks for this assertion. Comparing two live clock
            # reads with a 1e-6-second tolerance is scheduler-dependent and
            # caused valid A23/A24 checks to fail intermittently on loaded hosts.
            now_wall = float(_saved_wall_now() if callable(_saved_wall_now) else time.time())
            now_mono = max(10000.0, float(_saved_mono_now() if callable(_saved_mono_now) else time.monotonic()))
            globals()["WALL_NOW"] = lambda: now_wall
            globals()["MONO_NOW"] = lambda: now_mono
            STATS["last_signal_sent_ts"] = now_wall - 4000.0
            STATS["v45_no_send_sec"] = 3800.0
            V422StarvationAlerter._last_send_ts = now_mono - 3700.0
            STATS["v681_runtime_cycle_ranked"] = 3
            STATS["v681_runtime_cycle_selected"] = 2
            globals()["_v699_truthful_starvation_snapshot"] = lambda: {"root": "SCORE", "detail": "score_starvation"}
            globals()["_v704_market_hazard"] = lambda: False
            _ages = _v704_no_send_age_sources()
            _expected_age = min(_ages.values()) if _ages else 0.0
            checks["no_send_age_uses_freshest_source"] = abs(_v704_no_send_age_sec() - _expected_age) < 1e-6 and _expected_age >= 3600.0
            _relief_ok, _relief = _v704_starvation_score_floor_override({"family": "PULLBACK"}, 74.0, 76.0)
            _below_ok, _below = _v704_starvation_score_floor_override({"family": "PULLBACK"}, 69.9, 76.0)
            checks["relief_is_effective_above_70"] = _relief_ok and float(_relief.get("effective_floor", 0.0)) == 70.0
            checks["relief_never_admits_below_70"] = not _below_ok and _below.get("reason") == "score_below_hard_global_floor"
            # Inject a stale/global same-symbol row; exact-candidate lookup must
            # ignore it when no current candidate-key record exists.
            _stale_key = f"{V702PipelineMetrics._cycle()}|TEST/USDT|PULLBACK|UNKNOWN|stale"
            _stale_store = STATS.setdefault("v702_builder_rejection_by_candidate", {})
            _stale_prior_existed = _stale_key in _stale_store
            _stale_prior = _stale_store.get(_stale_key)
            _stale_store[_stale_key] = {
                "candidate_key": _stale_key, "symbol": "TEST/USDT", "stage": "builder",
                "reason": "stale_reason", "ts": now_wall - 100.0, "cycle_id": V702PipelineMetrics._cycle()
            }
            checks["stale_candidate_reason_is_not_reused"] = _v702_builder_rejection_reason_for_candidate(_stale_key, now_wall) is None
        finally:
            # Restore clock providers immediately, including if any probe raises.
            if _saved_wall_now_present:
                globals()["WALL_NOW"] = _saved_wall_now
            else:
                globals().pop("WALL_NOW", None)
            if _saved_mono_now_present:
                globals()["MONO_NOW"] = _saved_mono_now
            else:
                globals().pop("MONO_NOW", None)
            for k, v in _saved.items():
                if v is None: STATS.pop(k, None)
                else: STATS[k] = v
            if _saved_last_send is None:
                try: delattr(V422StarvationAlerter, "_last_send_ts")
                except Exception: pass
            else:
                V422StarvationAlerter._last_send_ts = _saved_last_send
            if _saved_truth is None: globals().pop("_v699_truthful_starvation_snapshot", None)
            else: globals()["_v699_truthful_starvation_snapshot"] = _saved_truth
            if _saved_hazard is None: globals().pop("_v704_market_hazard", None)
            else: globals()["_v704_market_hazard"] = _saved_hazard
            try:
                if _stale_key is not None:
                    _store = _stale_store if isinstance(_stale_store, dict) else STATS.get("v702_builder_rejection_by_candidate", {})
                    if _stale_prior_existed:
                        _store[_stale_key] = _stale_prior
                    else:
                        _store.pop(_stale_key, None)
            except Exception:
                _v647_record_suppressed_exception()
    except Exception as exc:
        checks["exception_free"] = False
        details["error"] = f"{type(exc).__name__}:{str(exc)[:200]}"
    report = {"pass": bool(checks and all(checks.values())), "checks": checks,
              "failed": [k for k,v in checks.items() if not v], "details": details,
              "revision": V702_A24_CANONICAL_REVISION, "live_network_tested": False,
              "profitability_verified": False, "live_gates_relaxed": False,
              "hard_gate_bypass": False, "validate_wrapper_chain_policy": "FROZEN; A24 EXTENDS TERMINAL CLOSURE WITHOUT ADDING A VALIDATE_CONFIG WRAPPER"}
    STATS["v702_a24_terminal_self_test"] = report
    FINAL_CANONICAL_RUNTIME["v702_a24_terminal_self_test"] = report
    return report


_V702_A23_PREV_VALIDATE_CONFIG = globals().get("validate_config")
def _v702_a23_validate_config():
    # A24 freezes the historic additive validate wrapper chain: the terminal
    # closure is extended in-place, rather than introducing another wrapper.
    base_ok = bool(callable(_V702_A23_PREV_VALIDATE_CONFIG) and _V702_A23_PREV_VALIDATE_CONFIG())
    report = _v702_a23_terminal_self_test()
    a24 = _v702_a24_terminal_self_test()
    a26 = _v702_a26_terminal_self_test()
    validation = {"base": base_ok, "report": report, "a24_report": a24, "a26_report": a26,
                  "pass": bool(base_ok and report.get("pass", False) and a24.get("pass", False) and a26.get("pass", False))}
    STATS["v702_a23_final_validation"] = validation
    STATS["v702_a24_final_validation"] = {"pass": bool(a24.get("pass",False) and report.get("pass",False)), "revision": V702_A24_CANONICAL_REVISION, "report": a24}
    STATS["v702_a26_final_validation"] = {"pass": bool(a26.get("pass",False)), "revision": V702_A26_CANONICAL_REVISION, "report": a26}
    FINAL_CANONICAL_RUNTIME["v702_a23_final_validation"] = validation
    FINAL_CANONICAL_RUNTIME["v702_a24_final_validation"] = STATS["v702_a24_final_validation"]
    FINAL_CANONICAL_RUNTIME["v702_a26_final_validation"] = STATS["v702_a26_final_validation"]
    FINAL_CANONICAL_RUNTIME["package_audit_revision"] = V702_PACKAGE_AUDIT_REVISION
    FINAL_CANONICAL_RUNTIME["active_optimization_revision"] = V702_PACKAGE_AUDIT_REVISION
    FINAL_CANONICAL_RUNTIME["wrapper_chain_policy"] = "FROZEN_AT_A24; NO_ADDITIONAL_VALIDATE_CONFIG_WRAPPERS"
    if not bool(validation["pass"]):
        _upstream_failures = {}
        _historical_superseded = {}
        for _key, _value in sorted(STATS.items()):
            _key_s = str(_key)
            if not isinstance(_value, dict):
                continue
            _checks = _value.get("checks") if isinstance(_value.get("checks"), dict) else {}
            _nested_report = _value.get("report") if isinstance(_value.get("report"), dict) else {}
            _nested_checks = _nested_report.get("checks") if isinstance(_nested_report.get("checks"), dict) else {}
            _bad_checks = [str(_k) for _k, _v in _checks.items() if not bool(_v)]
            _bad_checks.extend(str(_k) for _k, _v in _nested_checks.items() if not bool(_v) and str(_k) not in _bad_checks)
            _failed = list(_value.get("failed") or _nested_report.get("failed") or _bad_checks)[:20]
            if (_value.get("pass") is False or _bad_checks or bool(_value.get("failed"))) and (
                _key_s.endswith("_final_validation") or _key_s.endswith("_terminal_self_test")
                or _key_s.endswith("_full_validation_observability")
            ):
                _is_historical = bool(_value.get("historical") or _value.get("superseded_by") or _value.get("terminal_authority") is False)
                _row = {
                    "pass": _value.get("pass"), "failed": _failed,
                    "error": str(_value.get("error") or _nested_report.get("error") or "")[:160],
                    "revision": str(_value.get("revision") or _nested_report.get("revision") or "")[:180],
                }
                if _is_historical:
                    _row["classification"] = "historical_or_superseded_non_authoritative"
                    _row["superseded_by"] = str(_value.get("superseded_by") or "")[:120]
                    _historical_superseded[_key_s] = _row
                else:
                    _upstream_failures[_key_s] = _row
        logger.critical(
            "[V702-A28-VALIDATION] fail_closed base_ok=%s a23_pass=%s a23_failed=%s a24_pass=%s a24_failed=%s a26_pass=%s a26_failed=%s upstream_failures=%s historical_superseded=%s",
            base_ok, report.get("pass"), report.get("failed", []),
            a24.get("pass"), a24.get("failed", []), a26.get("pass"), a26.get("failed", []),
            _upstream_failures or {"none_recorded": True}, _historical_superseded or {"none_recorded": True},
        )
    else:
        logger.info("[V702-A28-VALIDATION] PASS base_ok=%s a23_pass=%s a24_pass=%s a26_pass=%s; live epoch not armed until main() completes validation",
                    base_ok, report.get("pass"), a24.get("pass"), a26.get("pass"))
    return bool(validation["pass"])

globals()["validate_config"] = _v702_a23_validate_config

# A25 startup contract: validation must precede LIVE epoch arming, and failures
# must expose current terminal diagnostics rather than stale R23/V704-only keys.
V702_A25_CANONICAL_REVISION = (
    V702_A24_CANONICAL_REVISION + "-A25-STARTUP-VALIDATION-ORDER-DIAGNOSTICS-CLOSURE"
)
V702_A26_CANONICAL_REVISION = (
    V702_A25_CANONICAL_REVISION + "-A26-MONOTONIC-VALIDATION-REVISION-COMPATIBILITY-CLOSURE"
)
V702_A27_CANONICAL_REVISION = (
    V702_A26_CANONICAL_REVISION + "-A27-STARVATION-VALIDATION-CLOCK-DETERMINISM-CLOSURE"
)
V702_A28_CANONICAL_REVISION = (
    V702_A27_CANONICAL_REVISION + "-A28-CANDIDATE-REASON-AND-TELEGRAM-FUNNEL-COHERENCE-CLOSURE"
)
V702_PACKAGE_AUDIT_REVISION = V702_A28_CANONICAL_REVISION
FINAL_CANONICAL_RUNTIME["package_audit_revision"] = V702_A28_CANONICAL_REVISION
FINAL_CANONICAL_RUNTIME["active_optimization_revision"] = V702_A28_CANONICAL_REVISION
FINAL_CANONICAL_RUNTIME["startup_validation_order"] = "VALIDATE_CONFIG_BEFORE_LIVE_EPOCH_ARM"
FINAL_CANONICAL_RUNTIME["active_failure_diagnostics"] = "A7-A28_TERMINAL_REPORTS_WITH_HISTORICAL_SUPERSEDED_SEPARATION"
FINAL_CANONICAL_RUNTIME["revision_chain_policy"] = "APPEND_ONLY_PREFIX_COMPATIBLE_THROUGH_A28; HISTORICAL_A21_A22_CHECKS_MUST_NOT_REQUIRE_PACKAGE_EQUALITY"
FINAL_CANONICAL_RUNTIME["hard_gate_bypass"] = False


def _v702_a26_terminal_self_test() -> Dict[str, Any]:
    """Verify monotonic release identity without allowing historical checks to block upgrades."""
    checks: Dict[str, bool] = {}
    details: Dict[str, Any] = {}
    try:
        checks["active_revision_is_a28"] = V702_PACKAGE_AUDIT_REVISION == V702_A28_CANONICAL_REVISION
        checks["a27_is_preserved_as_prefix"] = V702_PACKAGE_AUDIT_REVISION.startswith(V702_A27_CANONICAL_REVISION)
        checks["a26_is_preserved_as_prefix"] = V702_PACKAGE_AUDIT_REVISION.startswith(V702_A26_CANONICAL_REVISION)
        checks["a25_is_preserved_as_prefix"] = V702_PACKAGE_AUDIT_REVISION.startswith(V702_A25_CANONICAL_REVISION)
        checks["a24_and_earlier_history_preserved"] = all(
            token in V702_PACKAGE_AUDIT_REVISION for token in (
                "A21-LIVE-PILOT-RELEASE", "A22-PRE-REPRICE-TP1",
                "A23-LOCAL-HISTORY-PRE-RANK-CLOSURE",
                "A24-TRUTHFUL-STARVATION-TELEMETRY-EXACT-ATTRIBUTION-CLOSURE",
                "A25-STARTUP-VALIDATION-ORDER-DIAGNOSTICS-CLOSURE",
                "A26-MONOTONIC-VALIDATION-REVISION-COMPATIBILITY-CLOSURE",
                "A27-STARVATION-VALIDATION-CLOCK-DETERMINISM-CLOSURE",
                "A28-CANDIDATE-REASON-AND-TELEGRAM-FUNNEL-COHERENCE-CLOSURE",
            )
        )
        checks["historical_a21_a22_validators_accept_monotonic_revision"] = (
            V702_PACKAGE_AUDIT_REVISION.startswith(V702_A22_CANONICAL_REVISION)
            and V702_A22_CANONICAL_REVISION == V702_A21_CANONICAL_REVISION
        )
        checks["spot_long_only_no_futures_or_short"] = bool(
            CONFIG.get("LONG_ONLY", False) and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT"
            and not bool(CONFIG.get("ENABLE_FUTURES", False))
            and not bool(CONFIG.get("FUTURES_ENABLED", False))
            and not bool(CONFIG.get("ALLOW_SHORT", False))
            and not bool(CONFIG.get("ALLOW_SHORTS", False))
        )
        checks["hard_score_and_liquidity_floors_unchanged"] = (
            float(CONFIG.get("MIN_LIVE_SCORE", 0.0)) >= 70.0
            and float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 0.0)) >= 3_000_000.0
        )
        checks["trade_caps_preserved"] = (
            1 <= int(CONFIG.get("MAX_CONCURRENT_TRADES", 0)) <= 2
            and float(CONFIG.get("FIXED_POSITION_SIZE_USDT", 0.0)) <= 75.0
            and float(CONFIG.get("MAX_POSITION_SIZE_USDT", 0.0)) <= 75.0
            and float(CONFIG.get("MAX_ENTRY_NOTIONAL_USDT", 0.0)) <= 75.0
        )
        checks["forbidden_assets_preserved"] = {"AERO", "BNB", "CAKE", "ETHFI", "PUMP"}.issubset(set(V702_HARD_FORBIDDEN_BASES))
        checks["hard_gate_bypass_disabled"] = FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass", True) is False
        checks["live_epoch_still_behind_validation"] = "VALIDATE_CONFIG_BEFORE_LIVE_EPOCH_ARM" == FINAL_CANONICAL_RUNTIME.get("startup_validation_order")
        _a21_report = _v702_a21_terminal_self_test() if callable(globals().get("_v702_a21_terminal_self_test")) else {"pass": False, "failed": ["a21_terminal_missing"]}
        details["a21_failed"] = list(_a21_report.get("failed") or [])
        details["a22_failed"] = list((_a21_report.get("a22_terminal_self_test") or {}).get("failed") or [])
        checks["a21_a22_terminal_contracts_pass"] = bool(
            _a21_report.get("pass", False)
            and (_a21_report.get("a22_terminal_self_test") or {}).get("pass", False)
        )
    except Exception as exc:
        checks["exception_free"] = False
        details["error"] = f"{type(exc).__name__}:{str(exc)[:180]}"
    report = {
        "pass": bool(checks and all(checks.values())), "checks": checks,
        "failed": [key for key, value in checks.items() if not value], "details": details,
        "revision": V702_A26_CANONICAL_REVISION, "live_network_tested": False,
        "profitability_verified": False, "live_gates_relaxed": False,
        "hard_gate_bypass": False, "scope": "APPEND_ONLY_RELEASE_REVISION_COMPATIBILITY; NO_POLICY_RELAXATION",
    }
    STATS["v702_a26_terminal_self_test"] = report
    FINAL_CANONICAL_RUNTIME["v702_a26_terminal_self_test"] = report
    return report


# =============================================================================
# V702 A29 — ADAPTIVE SOFT-QUALITY RELIEF + SCORE SHADOW + HISTORY RETRY CLOSURE
# =============================================================================
# This append-only layer admits at most ONE narrowly-bounded PULLBACK soft-factor
# near miss, and only with a strong canonical score, high setup quality, multiple
# independent CLOSED-5m confirmations, and strong remaining factors. Score >=70,
# execution economics, liquidity/depth/spread, forbidden assets, Spot LONG_ONLY,
# order sizing, stops/protection and the final execution authority remain hard.
# The 65-69.99 score band is telemetry-only; it cannot reach select/queue/Telegram.
# Short, contiguous closed 4H histories may be cached as reject-only inputs for a
# bounded TTL (420s default, clamped to 60-900s or earlier 4H boundary). This does
# not prove listing age. No stale partial candle is admitted and no candle is fabricated.
V702_A29_CANONICAL_REVISION = (
    V702_A28_CANONICAL_REVISION + "-A29-ADAPTIVE-REJECTION-RELIEF-AND-DATA-FUNNEL-CLOSURE"
)
V702_PACKAGE_AUDIT_REVISION = V702_A29_CANONICAL_REVISION
V702_A29_ADAPTIVE_RELIEF_ID = "A29-ONE-SOFT-MISS-WITH-INDEPENDENT-EVIDENCE-SCORE-SHADOW-HISTORY-RETRY"
CONFIG.update({
    "V702_A29_ADAPTIVE_PB_RELIEF_ENABLE": True,
    "V702_A29_SCORE_SHADOW_ENABLE": True,
    "V702_A29_SCORE_SHADOW_MIN": 65.0,
    "V702_A29_SCORE_SHADOW_MAX_EXCLUSIVE": 70.0,
    "V702_A29_PB_MIN_STRONG_SETUP": 76.0,
    "V702_A29_PB_MIN_COMPOSITE_QUALITY": 78.0,
    "V702_A29_PB_MIN_CLOSED_CONFIRMATIONS": 3,
    "V702_A29_PB_HTF_RELIEF_MIN": 40.0,
    "V702_A29_CLOSED_BAR_MAX_AGE_SEC": 600.0,
    "V702_A29_SHORT_HISTORY_RETRY_AT_NEXT_4H_BOUNDARY": True,
    "V702_A29_SHORT_HISTORY_CACHE_MAX": 512,
})
FINAL_CANONICAL_RUNTIME.update({
    "package_audit_revision": V702_A29_CANONICAL_REVISION,
    "active_optimization_revision": V702_A29_CANONICAL_REVISION,
    "revision_chain_policy": "APPEND_ONLY_PREFIX_COMPATIBLE_THROUGH_A29; HISTORICAL_A21_A22_CHECKS_MUST_NOT_REQUIRE_PACKAGE_EQUALITY",
    "a29_adaptive_soft_quality_relief": True,
    "a29_score_65_69_shadow_only": True,
    "a29_history_cache_reject_only": True,
    "hard_gate_bypass": False,
})
STATS["v702_a29_relief_id"] = V702_A29_ADAPTIVE_RELIEF_ID

_V702_A29_PREV_V587_PULLBACK_QUALITY = _v587_pullback_quality
_V702_A29_PREV_ELITE_LIVE_CONTEXT_GATE = _v702_elite_live_context_gate
_V702_A29_PREV_SOFT_HTF_ALIGNMENT_ALLOWED = _v702_soft_htf_alignment_allowed
_V702_A29_SHORT_HISTORY_CACHE: Dict[str, Dict[str, Any]] = globals().setdefault(
    "_V702_A29_SHORT_HISTORY_CACHE", {}
)


def _v702_a29_finite_number(value):
    try:
        x = float(value)
        return x if math.isfinite(x) else None
    except Exception:
        return None


def _v702_a29_flag(value) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        try:
            return math.isfinite(float(value)) and float(value) != 0.0
        except Exception:
            return False
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "confirmed", "bullish", "pass"}
    return False


def _v702_a29_context_parts(candidate=None, snapshot=None):
    c = getattr(candidate, "candidate", candidate)
    # Dict candidates are common in prequal/diagnostic paths; do not let the
    # empty default from getattr() shadow their actual immutable feature snapshot.
    if isinstance(c, dict):
        fs = c.get("features_snapshot", c)
    else:
        fs = getattr(c, "features_snapshot", {})
    if not isinstance(fs, dict):
        fs = {}
    snap = snapshot if isinstance(snapshot, dict) else {}
    fam = str((c.get("family", "") if isinstance(c, dict) else getattr(c, "family", "")) or fs.get("family") or "").upper()
    mode = str((c.get("strategy_mode", "") if isinstance(c, dict) else getattr(c, "strategy_mode", "")) or fs.get("strategy_mode") or fam).upper()
    def pick(*keys):
        for key in keys:
            if fs.get(key) is not None:
                return fs.get(key)
            if snap.get(key) is not None:
                return snap.get(key)
        return None
    reg = str(pick("macro_regime", "regime") or (getattr(c, "macro_regime", "") if c is not None else "") or "").upper()
    loc = str(pick("local_regime") or (getattr(c, "local_regime", "") if c is not None else "") or "").upper()
    sev = str(pick("macro_severity", "bearish_severity", "severity") or "").upper()
    state = str(pick("htf_state") or "").upper()
    reason = str(pick("htf_reason") or "").lower()
    return c, fs, snap, fam, mode, reg, loc, sev, state, reason, pick


def _v702_a29_prior_relief_metric(fs=None, snap=None):
    """Return an already-consumed soft-relief metric across stages, if any."""
    for source in (fs if isinstance(fs, dict) else {}, snap if isinstance(snap, dict) else {}):
        for key in ("v702_a29_pullback_quality_relief", "v702_a29_contextual_htf_relief"):
            value = source.get(key)
            if not isinstance(value, dict) or not _v702_a29_flag(value.get("applied")):
                continue
            metric = value.get("failed_metric") or value.get("a29_relief_metric")
            qd = value.get("quality_decision")
            if not metric and isinstance(qd, dict):
                metric = qd.get("failed_metric")
            if metric:
                return str(metric).strip().lower()
    return ""


def _v702_a29_closed_evidence(candidate=None, snapshot=None) -> Dict[str, Any]:
    """Count independent local proof groups; derive candle evidence only from closed 5m bars."""
    c, fs, snap, fam, mode, reg, loc, sev, state, reason, pick = _v702_a29_context_parts(candidate, snapshot)
    groups = set()
    signal_count = 0
    def any_flag(keys):
        return any(_v702_a29_flag(fs.get(k)) or _v702_a29_flag(snap.get(k)) for k in keys)
    reclaim = any_flag(("reclaim", "zone_reclaim", "reclaim_ema20", "reclaim_vwap", "vwap_reclaim", "liquidity_sweep_reclaim"))
    structure = any_flag(("higher_low", "bos_confirmed", "micro_bos_confirmed", "choch_bullish", "bullish_choch", "structural_reclaim"))
    candle = any_flag(("bullish_close", "bullish_engulfing", "bullish_candle_confirmed", "bullish_reclaim"))
    trend = any_flag(("ema20_slope_up", "local_recovery_confirmed", "local_trend_bullish", "trend_reclaimed"))
    if reclaim: groups.add("reclaim")
    if structure: groups.add("structure")
    if candle: groups.add("closed_candle")
    if trend: groups.add("trend")

    df5 = snap.get("df_5m")
    if df5 is None:
        df5 = fs.get("df_5m")
    valid_closed_frame = False
    frame_timestamp_valid = False
    frame_fresh = False
    frame_age_sec = None
    closed_frame_key = None
    try:
        closed_key_fn = globals().get("_v702_a16_closed_5m_candle_key")
        _closed_ts_key = closed_key_fn({"df_5m": df5}) if callable(closed_key_fn) else None
        frame_timestamp_valid = bool(_closed_ts_key is not None)
        if frame_timestamp_valid and hasattr(df5, "index") and len(df5) >= 3:
            # Data-frame indices represent candle OPEN timestamps; iloc[-2]
            # becomes closed 5 minutes after its open. Reject old/future bars
            # before they can justify an adaptive quality exception.
            _closed_open_ts = pd.to_datetime(df5.index[-2], utc=True, errors="coerce")
            if not pd.isna(_closed_open_ts):
                _closed_at_sec = float(_closed_open_ts.timestamp()) + 300.0
                _now_sec = float(WALL_NOW())
                frame_age_sec = _now_sec - _closed_at_sec
                _max_age_sec = max(300.0, min(900.0, float(CONFIG.get("V702_A29_CLOSED_BAR_MAX_AGE_SEC", 600.0))))
                frame_fresh = bool(math.isfinite(frame_age_sec) and -60.0 <= frame_age_sec <= _max_age_sec)
        if frame_timestamp_valid and len(df5) >= 4 and {"open", "low", "close"}.issubset(set(df5.columns)):
            # Fingerprint four completed candles, not just their timestamp, so
            # a validation marker cannot be reused against revised/different OHLCV.
            import hashlib as _a29_hashlib
            _sig_cols = [col for col in ("open", "high", "low", "close", "volume") if col in df5.columns]
            _sig_rows = []
            for _pos in range(max(0, len(df5) - 5), len(df5) - 1):
                _bar_ts = pd.to_datetime(df5.index[_pos], utc=True, errors="coerce")
                if pd.isna(_bar_ts):
                    raise ValueError("unparseable closed candle timestamp")
                _values = [float(df5[col].iloc[_pos]) for col in _sig_cols]
                if not all(math.isfinite(_v) for _v in _values):
                    raise ValueError("non-finite closed candle value")
                _sig_rows.append([_bar_ts.isoformat(), *_values])
            if len(_sig_rows) >= 3:
                closed_frame_key = _a29_hashlib.sha256(
                    json.dumps(_sig_rows, separators=(",", ":"), allow_nan=False).encode("utf-8")
                ).hexdigest()[:32]
        valid_closed_frame = bool(frame_timestamp_valid and frame_fresh and closed_frame_key)
        if valid_closed_frame and len(df5) >= 24 and {"open", "low", "close"}.issubset(set(df5.columns)):
            lc = float(df5["close"].iloc[-2]); pc = float(df5["close"].iloc[-3]); op = float(df5["open"].iloc[-2])
            lo, plo, p2lo = float(df5["low"].iloc[-2]), float(df5["low"].iloc[-3]), float(df5["low"].iloc[-4])
            candle_closed = bool(lc > op and lc >= pc)
            higher_low = bool(lo > plo >= p2lo)
            if candle_closed:
                groups.add("closed_candle")
            if higher_low:
                groups.add("structure")
            reclaim_zone = _v702_a29_finite_number(pick("zone_ref"))
            frame_reclaim = bool(reclaim_zone is not None and pc < reclaim_zone <= lc)
            if frame_reclaim:
                groups.add("reclaim")
            e20 = df5["close"].astype(float).ewm(span=20, adjust=False).mean()
            frame_trend = bool(len(e20) >= 10 and float(e20.iloc[-2]) > float(e20.iloc[-9]) * 1.0001)
            if frame_trend:
                groups.add("trend")
            # Count frame-derived facts, not similarly named metadata flags that
            # may have been produced from another/stale candle snapshot.
            signal_count = sum((bool(candle_closed), bool(higher_low), frame_trend, frame_reclaim))
    except Exception:
        # A missing/unorderable/invalid/stale closed-bar frame contributes no derived evidence.
        signal_count = 0
        frame_fresh = False
        valid_closed_frame = False
        closed_frame_key = None
    stored_confirmations = _v702_a29_finite_number(pick("v587_pullback_confirmations", "pullback_confirmations", "confirmations"))
    # Trust a prior validation marker only when its OHLCV fingerprint matches
    # this currently fresh closed-frame snapshot exactly.
    prior_evidence_key = str(pick("v702_a29_closed_bar_evidence_key") or "")
    trusted_prior_validation = bool(
        _v702_a29_flag(pick("v702_a29_closed_bar_evidence_verified"))
        and frame_fresh and closed_frame_key and prior_evidence_key
        and prior_evidence_key == closed_frame_key
    )
    if stored_confirmations is not None and trusted_prior_validation:
        signal_count = max(signal_count, int(stored_confirmations))
        if int(stored_confirmations) >= 3:
            groups.add("closed_5m_confirmation_bundle")
    elif stored_confirmations is not None and not valid_closed_frame:
        # Useful diagnostic count only; it cannot turn a frame-less candidate
        # into verified evidence because closed_frame_verified remains false.
        signal_count = max(signal_count, int(stored_confirmations))
    # Feature flags are useful for diagnostics, but cannot manufacture a
    # closed-bar confirmation count. Count only signals derived from the
    # validated frame above or a prior validation marker tied to this snapshot.
    closed_frame_verified = bool(signal_count > 0 and valid_closed_frame and frame_fresh and closed_frame_key)
    return {
        "groups": sorted(groups), "group_count": int(len(groups)),
        "confirmations": int(signal_count), "closed_frame_verified": closed_frame_verified,
        "valid_closed_frame": bool(valid_closed_frame),
        "frame_timestamp_valid": bool(frame_timestamp_valid),
        "frame_fresh": bool(frame_fresh), "frame_age_sec": frame_age_sec,
        "closed_frame_key": closed_frame_key,
        "prior_validated_closed_frame": bool(trusted_prior_validation),
        "family": fam, "strategy_mode": mode, "macro_regime": reg,
        "local_regime": loc, "severity": sev, "htf_state": state,
    }


def _v702_a29_pb_quality_relief_decision(candidate, snapshot, failed_metric, quality_record):
    """Return PASS only for one soft PULLBACK near-miss with strong independent corroboration."""
    result = {"applied": False, "policy": "A29_ONE_SOFT_MISS", "reason": "not_eligible", "failed_metric": str(failed_metric or "")}
    if not bool(CONFIG.get("V702_A29_ADAPTIVE_PB_RELIEF_ENABLE", True)):
        result["reason"] = "disabled"
        return False, result
    c, fs, snap, fam, mode, reg, loc, sev, state, htf_reason, pick = _v702_a29_context_parts(candidate, snapshot)
    result.update({"family": fam, "strategy_mode": mode, "regime": reg})
    prior_metric = _v702_a29_prior_relief_metric(fs, snap)
    result["prior_relief_metric"] = prior_metric or None
    if prior_metric and prior_metric != str(failed_metric or "").strip().lower():
        result["reason"] = "prior_soft_relief_already_used_for_another_metric"
        return False, result
    if fam != "PULLBACK" or mode not in {"", "PULLBACK"}:
        result["reason"] = "family_not_eligible"
        return False, result
    if reg not in {"BULLISH", "NEUTRAL"} or "CRASH" in sev or "EXTREME" in sev:
        result["reason"] = "regime_or_severity_not_eligible"
        return False, result
    if state in {"UNKNOWN", "ERROR", "UNAVAILABLE", "DATA_MISSING", "NONE"} or htf_reason.startswith("error") or htf_reason in {"insufficient_data", "snapshot_unavailable", "htf_grade_exception"}:
        result["reason"] = "htf_data_unverifiable"
        return False, result

    qr = quality_record if isinstance(quality_record, dict) else {}
    vals = {
        "htf": _v702_a29_finite_number(qr.get("htf_strength", pick("htf_strength", "htf_alignment"))),
        "volume": _v702_a29_finite_number(qr.get("volume_ratio", pick("volume_ratio"))),
        "rs": _v702_a29_finite_number(qr.get("rs_5m", pick("rs_5m", "relative_strength"))),
        "structure": _v702_a29_finite_number(qr.get("structure", pick("structure_confidence", "structure_quality"))),
        "retest": _v702_a29_finite_number(qr.get("retest", pick("retest_quality_score", "retest_quality"))),
        "chase": _v702_a29_finite_number(qr.get("chase", pick("chase_atr"))),
    }
    if vals["rs"] is not None and abs(vals["rs"]) > 1.5:
        vals["rs"] /= 100.0
    if any(v is None for v in vals.values()):
        result.update({"reason": "quality_factor_unverifiable", "values": vals})
        return False, result
    floors = {
        "htf": float(CONFIG.get("V587_PULLBACK_MIN_HTF", 50.0)),
        "volume": float(CONFIG.get("V587_PULLBACK_MIN_VOLUME_RATIO", 0.85)),
        "rs": float(CONFIG.get("V587_PULLBACK_MIN_RS", 0.0)),
        "structure": float(CONFIG.get("V587_PULLBACK_MIN_STRUCTURE_SCORE", 45.0)),
        "retest": float(CONFIG.get("V587_PULLBACK_MIN_RETEST_SCORE", 45.0)),
    }
    actual_failures = [key for key, floor in floors.items() if vals[key] < floor]
    if actual_failures != [str(failed_metric)]:
        result.update({"reason": "multiple_or_mismatched_soft_failures", "actual_failures": actual_failures, "values": vals})
        return False, result
    min_vals = {"htf": 40.0, "volume": 0.75, "rs": -0.005, "structure": 50.0, "retest": 40.0}
    if vals[str(failed_metric)] < min_vals[str(failed_metric)]:
        result.update({"reason": "outside_bounded_relief_band", "values": vals, "minimum": min_vals[str(failed_metric)]})
        return False, result
    setup = _v702_a29_finite_number(pick("v643_canonical_quality", "v587_setup_quality", "setup_quality"))
    if setup is None:
        setup = _v702_a29_finite_number(qr.get("quality"))
    quality = _v702_a29_finite_number(qr.get("quality"))
    confirmations = _v702_a29_finite_number(qr.get("confirmations"))
    evidence = _v702_a29_closed_evidence(candidate, snapshot)
    confirmations = max(int(confirmations or 0), int(evidence.get("confirmations", 0) or 0))
    result.update({"values": vals, "floors": floors, "setup_quality": setup, "composite_quality": quality,
                   "confirmations": confirmations, "evidence": evidence})
    if setup is None or setup < float(CONFIG.get("V702_A29_PB_MIN_STRONG_SETUP", 76.0)):
        result["reason"] = "setup_not_strong_enough"
        return False, result
    if quality is None or quality < float(CONFIG.get("V702_A29_PB_MIN_COMPOSITE_QUALITY", 78.0)):
        result["reason"] = "composite_quality_not_strong_enough"
        return False, result
    if confirmations < int(CONFIG.get("V702_A29_PB_MIN_CLOSED_CONFIRMATIONS", 3)) or not evidence.get("closed_frame_verified"):
        result["reason"] = "closed_candle_confirmation_insufficient"
        return False, result
    if vals["chase"] > float(CONFIG.get("V587_PULLBACK_MAX_FINAL_CHASE_ATR", 0.90)):
        result["reason"] = "chase_hard_gate"
        return False, result

    # Require at least three OTHER factors to be clearly stronger than their floor.
    support_floor = {
        "htf": floors["htf"] + 5.0,
        "volume": floors["volume"] + 0.15,
        "rs": floors["rs"] + 0.015,
        "structure": max(floors["structure"] + 10.0, 63.0),
        "retest": floors["retest"] + 10.0,
    }
    support = [key for key in floors if key != failed_metric and vals[key] >= support_floor[key]]
    if len(support) < 3:
        result.update({"reason": "independent_support_insufficient", "support": support, "support_floor": support_floor})
        return False, result
    result.update({"applied": True, "reason": "one_near_miss_compensated_by_independent_evidence", "support": support})
    return True, result


def _v702_a29_pullback_htf_relief_allowed(candidate, snapshot, *, family="", strategy_mode="", regime="",
                                           local_regime="", severity="", htf_state="", htf_strength=None,
                                           htf_reason=""):
    ctx = {"applied": False, "reason": "not_eligible", "floor": 45.0}
    c, fs, snap, fam, mode, reg, loc, sev, state, reason, pick = _v702_a29_context_parts(candidate, snapshot)
    fam = str(family or fam).upper(); mode = str(strategy_mode or mode).upper()
    reg = str(regime or reg).upper(); loc = str(local_regime or loc).upper()
    sev = str(severity or sev).upper(); state = str(htf_state or state).upper(); reason = str(htf_reason or reason).lower()
    strength = _v702_a29_finite_number(htf_strength if htf_strength is not None else pick("htf_strength", "htf_alignment"))
    ctx.update({"family": fam, "strategy_mode": mode, "regime": reg, "local_regime": loc,
                "severity": sev, "htf_state": state, "htf_strength": strength, "htf_reason": reason})
    if not bool(CONFIG.get("V702_A29_ADAPTIVE_PB_RELIEF_ENABLE", True)) or fam != "PULLBACK" or mode not in {"", "PULLBACK"}:
        ctx["reason"] = "family_or_feature_not_eligible"; return False, ctx
    if strength is None or not (float(CONFIG.get("V702_A29_PB_HTF_RELIEF_MIN", 40.0)) <= strength < 45.0):
        ctx["reason"] = "outside_contextual_htf_relief_band"; return False, ctx
    if reg not in {"BULLISH", "NEUTRAL"} or loc not in {"LOCAL_BULLISH", "LOCAL_RECOVERY", "LOCAL_NEUTRAL", "BULLISH", "NEUTRAL", "NON_BEARISH"}:
        ctx["reason"] = "local_regime_not_supported"; return False, ctx
    if "CRASH" in sev or "EXTREME" in sev or state in {"", "UNKNOWN", "ERROR", "UNAVAILABLE", "DATA_MISSING", "NONE", "BEARISH", "STRONG_BEARISH"}:
        ctx["reason"] = "htf_state_or_severity_not_eligible"; return False, ctx
    if reason.startswith("error") or reason in {"insufficient_data", "snapshot_unavailable", "htf_grade_exception"}:
        ctx["reason"] = "htf_data_unverifiable"; return False, ctx
    try:
        q = _V702_A29_PREV_V587_PULLBACK_QUALITY(c, snap)
    except Exception as exc:
        ctx["reason"] = f"quality_evaluation_error:{type(exc).__name__}"; return False, ctx
    if not isinstance(q, dict):
        ctx["reason"] = "quality_result_unverifiable"; return False, ctx
    ok, decision = _v702_a29_pb_quality_relief_decision(c, snap, "htf", q)
    if not ok:
        ctx["reason"] = decision.get("reason", "quality_evidence_not_enough")
        ctx["quality_decision"] = decision
        return False, ctx
    ctx.update({"applied": True, "reason": "pullback_htf_context_relief_with_closed_local_proof", "quality_decision": decision,
                "minimum_strength": float(CONFIG.get("V702_A29_PB_HTF_RELIEF_MIN", 40.0)), "alignment_claimed": False})
    return True, ctx


def _v702_a29_soft_htf_alignment_allowed(candidate=None, **kwargs):
    ok, ctx = _V702_A29_PREV_SOFT_HTF_ALIGNMENT_ALLOWED(candidate, **kwargs)
    if ok:
        return ok, ctx
    if not (isinstance(ctx, dict) and ctx.get("reason") == "contextual_htf_floor_not_met"):
        return ok, ctx
    a29_ok, a29_ctx = _v702_a29_pullback_htf_relief_allowed(
        candidate, kwargs.get("snapshot"), family=kwargs.get("family", ""),
        strategy_mode=kwargs.get("strategy_mode", ""), regime=kwargs.get("regime", ""),
        local_regime=kwargs.get("local_regime", ""), severity=kwargs.get("severity", ""),
        htf_state=kwargs.get("htf_state", ""), htf_strength=kwargs.get("htf_strength"),
        htf_reason=kwargs.get("htf_reason", ""),
    )
    if a29_ok:
        out = dict(ctx)
        out.update({"allowed": True, "reason": "a29_contextual_htf_relief", "alignment_claimed": False,
                    "a29_relief": dict(a29_ctx)})
        STATS["v702_a29_soft_htf_relief_passes"] = int(STATS.get("v702_a29_soft_htf_relief_passes", 0) or 0) + 1
        return True, out
    return False, {**dict(ctx or {}), "a29_relief": dict(a29_ctx or {})}


_v702_soft_htf_alignment_allowed = _v702_a29_soft_htf_alignment_allowed


def _v702_a29_v587_pullback_quality(candidate, market_data=None):
    q = _V702_A29_PREV_V587_PULLBACK_QUALITY(candidate, market_data)
    if not isinstance(q, dict):
        return q
    # Preserve provenance for the downstream elite-context gate. A count by
    # itself is insufficient: this evidence is written only after closed-frame validation.
    try:
        q = dict(q)
        q["a29_closed_evidence"] = _v702_a29_closed_evidence(candidate, market_data)
    except Exception:
        q["a29_closed_evidence"] = {"closed_frame_verified": False, "confirmations": 0, "groups": []}
    if q.get("ok"):
        return q
    reason_to_metric = {
        "htf_below_floor": "htf", "volume_below_floor": "volume", "rs_negative": "rs",
        "structure_weak": "structure", "retest_weak": "retest",
    }
    metric = reason_to_metric.get(str(q.get("reason", "")))
    if metric is None:
        return q
    c, fs, snap, fam, mode, reg, loc, sev, state, htf_reason, pick = _v702_a29_context_parts(candidate, market_data)
    if fam != "PULLBACK" or mode not in {"", "PULLBACK"}:
        return q
    ok, ctx = _v702_a29_pb_quality_relief_decision(c, market_data, metric, q)
    if not ok:
        STATS[f"v702_a29_pullback_relief_denied.{metric}.{ctx.get('reason', 'unknown')}"] = int(
            STATS.get(f"v702_a29_pullback_relief_denied.{metric}.{ctx.get('reason', 'unknown')}", 0) or 0
        ) + 1
        return q
    out = dict(q)
    out.update({"ok": True, "reason": f"a29_selective_relief:{metric}", "a29_adaptive_relief": dict(ctx)})
    STATS[f"v702_a29_pullback_relief_passes.{metric}"] = int(STATS.get(f"v702_a29_pullback_relief_passes.{metric}", 0) or 0) + 1
    return out


_v587_pullback_quality = _v702_a29_v587_pullback_quality


def _v702_a29_elite_context_gate(*, opp, score, htf_strength, volume_ratio, rs_score_val,
                                  structure_confidence, retest_quality_score, chase_atr, tier,
                                  regime="", severity=""):
    ok, reason, ctx = _V702_A29_PREV_ELITE_LIVE_CONTEXT_GATE(
        opp=opp, score=score, htf_strength=htf_strength, volume_ratio=volume_ratio,
        rs_score_val=rs_score_val, structure_confidence=structure_confidence,
        retest_quality_score=retest_quality_score, chase_atr=chase_atr, tier=tier,
        regime=regime, severity=severity,
    )
    if ok or reason not in {"htf_below_floor", "volume_below_floor", "rs_below_floor", "structure_below_floor", "retest_below_floor"}:
        return ok, reason, ctx
    _opp = opp if isinstance(opp, dict) else {}
    _fs = _opp.get("features_snapshot") if isinstance(_opp.get("features_snapshot"), dict) else _opp
    fam = str(_opp.get("family") or _opp.get("strategy_mode") or "").upper()
    if fam != "PULLBACK" or not bool(CONFIG.get("V702_A29_ADAPTIVE_PB_RELIEF_ENABLE", True)):
        return ok, reason, ctx
    failed_map = {
        "htf_below_floor": "htf", "volume_below_floor": "volume", "rs_below_floor": "rs_points",
        "structure_below_floor": "structure", "retest_below_floor": "retest",
    }
    failed_metric = failed_map[reason]
    prior_metric = _v702_a29_prior_relief_metric(_fs, _opp)
    if prior_metric and prior_metric != failed_metric:
        denied_ctx = dict(ctx or {})
        denied_ctx.update({"a29_relief_denied": "prior_soft_relief_already_used_for_another_metric",
                           "a29_prior_relief_metric": prior_metric, "a29_requested_metric": failed_metric})
        return ok, reason, denied_ctx
    # All hard dimensions are rechecked independently; they can never be rescued here.
    score_v = _v702_a29_finite_number(score)
    score_floor = _v702_a29_finite_number(ctx.get("score_floor"))
    setup = _v702_a29_finite_number(ctx.get("setup_quality"))
    setup_floor = _v702_a29_finite_number(ctx.get("setup_floor"))
    chase = _v702_a29_finite_number(chase_atr)
    chase_max = _v702_a29_finite_number(ctx.get("chase_max"))
    if (score_v is None or score_floor is None or score_v < max(75.0, score_floor + 5.0)
            or setup is None or setup_floor is None or setup < max(76.0, setup_floor + 4.0)
            or chase is None or chase_max is None or chase > chase_max):
        return ok, reason, ctx
    vals = {
        "htf": _v702_a29_finite_number(ctx.get("htf")),
        "volume": _v702_a29_finite_number(ctx.get("volume")),
        "rs_points": _v702_a29_finite_number(ctx.get("rs_points")),
        "structure": _v702_a29_finite_number(ctx.get("structure")),
        "retest": _v702_a29_finite_number(ctx.get("retest")),
    }
    floors = {
        "htf": _v702_a29_finite_number(ctx.get("htf_floor")),
        "volume": _v702_a29_finite_number(ctx.get("volume_floor")),
        "rs_points": _v702_a29_finite_number(ctx.get("rs_points_floor")),
        "structure": _v702_a29_finite_number(ctx.get("structure_floor")),
        "retest": _v702_a29_finite_number(ctx.get("retest_floor")),
    }
    if any(v is None for v in vals.values()) or any(v is None for v in floors.values()):
        return ok, reason, ctx
    actual_fails = [k for k in vals if vals[k] < floors[k]]
    if actual_fails != [failed_metric]:
        return ok, reason, ctx
    lower = {"htf": 40.0, "volume": 0.75, "rs_points": 0.0, "structure": 50.0, "retest": 40.0}
    if vals[failed_metric] < lower[failed_metric]:
        return ok, reason, ctx
    support_floor = {
        "htf": floors["htf"] + 5.0, "volume": floors["volume"] + 0.15,
        "rs_points": floors["rs_points"] + 2.0, "structure": floors["structure"] + 8.0,
        "retest": floors["retest"] + 8.0,
    }
    support = [k for k in vals if k != failed_metric and vals[k] >= support_floor[k]]
    evidence = _v702_a29_closed_evidence(_opp, _fs if isinstance(_fs, dict) else {})
    if len(support) < 3 or int(evidence.get("confirmations", 0) or 0) < 3 or not evidence.get("closed_frame_verified"):
        return ok, reason, ctx
    result_ctx = dict(ctx or {})
    result_ctx.update({"a29_relief_applied": True, "a29_relief_metric": failed_metric,
                       "a29_relief_support": support, "a29_support_floors": support_floor,
                       "a29_closed_evidence": evidence, "score_relief": False,
                       "hard_score_floor_preserved": True})
    STATS[f"v702_a29_elite_relief_passes.{failed_metric}"] = int(STATS.get(f"v702_a29_elite_relief_passes.{failed_metric}", 0) or 0) + 1
    return True, "pass_a29_selective_relief", result_ctx


_v702_elite_live_context_gate = _v702_a29_elite_context_gate


def _v702_a29_record_score_shadow(*, symbol, score, floor, family="", regime="", tier="", reason="canonical_live_score_floor"):
    """Store diagnostic-only evidence for 65–69.99 candidates; performs no routing."""
    if not bool(CONFIG.get("V702_A29_SCORE_SHADOW_ENABLE", True)):
        return {"recorded": False, "reason": "disabled", "routes": False}
    s = _v702_a29_finite_number(score)
    lo = float(CONFIG.get("V702_A29_SCORE_SHADOW_MIN", 65.0))
    hi = float(CONFIG.get("V702_A29_SCORE_SHADOW_MAX_EXCLUSIVE", 70.0))
    if s is None or not (lo <= s < hi):
        return {"recorded": False, "reason": "outside_shadow_band", "routes": False}
    sym = str(symbol or "")[:64]
    family_name = str(family or "UNKNOWN").upper()[:48]
    STATS["v702_a29_score_shadow_count"] = int(STATS.get("v702_a29_score_shadow_count", 0) or 0) + 1
    key = f"v702_a29_score_shadow.{family_name}"
    STATS[key] = int(STATS.get(key, 0) or 0) + 1
    STATS["v702_a29_score_shadow_last"] = {
        "symbol": sym, "score": float(s), "floor": float(floor), "family": family_name,
        "regime": str(regime or "")[:24], "tier": str(tier or "")[:24],
        "reason": str(reason or "")[:80], "ts": float(WALL_NOW()),
        "mode": "SHADOW_ONLY", "routes": False,
    }
    return {"recorded": True, "mode": "SHADOW_ONLY", "routes": False, "score": float(s)}


def _v702_a29_history_cache_get(symbol: str, now_ms: int):
    """Return a short-lived reject-only history result; this does not prove listing age."""
    try:
        sym = str(symbol or "")
        item = _V702_A29_SHORT_HISTORY_CACHE.get(sym)
        if not isinstance(item, dict):
            return None
        interval = 4 * 60 * 60 * 1000
        now = int(now_ms)
        current_open = now - (now % interval)
        expected_last_closed = current_open - interval
        if int(item.get("expected_last_closed_ts", 0) or 0) != expected_last_closed:
            _V702_A29_SHORT_HISTORY_CACHE.pop(sym, None)
            STATS["v702_a31_history_cache_boundary_invalidations"] = int(
                STATS.get("v702_a31_history_cache_boundary_invalidations", 0) or 0
            ) + 1
            return None
        if now >= int(item.get("valid_after_ms", 0) or 0):
            _V702_A29_SHORT_HISTORY_CACHE.pop(sym, None)
            STATS["v702_a31_history_cache_expired_rechecks"] = int(
                STATS.get("v702_a31_history_cache_expired_rechecks", 0) or 0
            ) + 1
            STATS["v702_a31_history_cache_last_recheck"] = {
                "symbol": sym, "ts_ms": now,
                "cached_rows": len(item.get("closed_rows") or []),
                "reason": "short_history_negative_cache_expired",
            }
            return None
        rows = item.get("closed_rows")
        if not isinstance(rows, list) or len(rows) >= int(item.get("required_rows", 210) or 210):
            _V702_A29_SHORT_HISTORY_CACHE.pop(sym, None)
            return None
        info = {"symbol": sym, "got": len(rows), "required": int(item.get("required_rows", 210) or 210),
                "reason": "short_history_retry_deferred_until_recheck",
                "expected_last_closed_ts": expected_last_closed, "cache_hit": True,
                "retry_at_ms": int(item.get("valid_after_ms", 0) or 0),
                "cache_policy": "BOUNDED_NEGATIVE_CACHE",
                "no_stale_open_candle_reused": True}
        STATS["v702_a31_history_cache_hits"] = int(STATS.get("v702_a31_history_cache_hits", 0) or 0) + 1
        STATS["v702_a29_local_history_deferred"] = int(STATS.get("v702_a29_local_history_deferred", 0) or 0) + 1
        STATS["v702_a29_local_history_defer_last"] = info
        return [list(row) for row in rows], info
    except Exception:
        return None


def _v702_a29_history_cache_put(symbol: str, rows, diag: dict, now_ms: int):
    """Cache contiguous short history as a bounded negative result, never as proof of listing age."""
    try:
        if not bool(CONFIG.get(
            "V702_A31_SHORT_HISTORY_NEGATIVE_CACHE_ENABLE",
            CONFIG.get("V702_A29_SHORT_HISTORY_RETRY_AT_NEXT_4H_BOUNDARY", True),
        )):
            return False
        if not isinstance(diag, dict) or bool(diag.get("complete")):
            return False
        _history_reason = str(diag.get("reason") or "")
        if _history_reason not in {"short_history", "recovery_page_added_no_rows"}:
            # Timeouts, parsing failures and explicit API errors must be retried normally.
            return False
        if _history_reason == "recovery_page_added_no_rows" and int(diag.get("pages", 0) or 0) < 2:
            return False
        if int(diag.get("synthetic_rows", 0) or 0) != 0:
            return False
        interval = 4 * 60 * 60 * 1000
        now = int(now_ms)
        current_open = now - (now % interval)
        req = max(210, int(diag.get("required_rows", 210) or 210))
        source = rows if isinstance(rows, (list, tuple)) else []
        closed = []
        for row in source:
            try:
                if isinstance(row, (list, tuple)) and len(row) >= 6 and int(row[0]) < current_open:
                    closed.append(list(row[:6]))
            except Exception:
                continue
        closed.sort(key=lambda r: int(r[0]))
        stamps = [int(r[0]) for r in closed]
        if len(stamps) < 3 or len(stamps) >= req:
            return False
        if any(stamps[i] - stamps[i-1] != interval for i in range(1, len(stamps))):
            return False
        if stamps[-1] != current_open - interval:
            return False
        # Candle continuity establishes that this subset is internally valid, but
        # does NOT prove that the symbol is newly listed: the venue may have
        # truncated a response or temporarily failed to serve older rows. A31 uses
        # a bounded negative-cache TTL and periodically retries the full OHLCV path.
        if (stamps[-1] - stamps[0]) // interval + 1 >= req:
            return False
        try:
            _recheck_sec = max(60.0, min(900.0, float(CONFIG.get("V702_A31_SHORT_HISTORY_RECHECK_SEC", 420.0))))
        except Exception:
            _recheck_sec = 420.0
        _retry_after_ms = min(current_open + interval, now + int(_recheck_sec * 1000))
        sym = str(symbol or "")
        _V702_A29_SHORT_HISTORY_CACHE[sym] = {
            "closed_rows": closed[-req:], "required_rows": req,
            "expected_last_closed_ts": current_open - interval,
            "valid_after_ms": _retry_after_ms,
            "stored_at_ms": now, "reason": "short_history_negative_cache",
            "source_reason": _history_reason,
            "cache_policy": "BOUNDED_NEGATIVE_CACHE",
            "recheck_after_sec": _recheck_sec,
        }
        # Entries can remain unreachable when a delisted symbol leaves the scan
        # universe; bound memory explicitly and evict the oldest observations.
        try:
            _cache_cap = max(64, min(2048, int(CONFIG.get("V702_A29_SHORT_HISTORY_CACHE_MAX", 512) or 512)))
        except Exception:
            _cache_cap = 512
        _evicted = 0
        while len(_V702_A29_SHORT_HISTORY_CACHE) > _cache_cap:
            _oldest_sym = min(
                _V702_A29_SHORT_HISTORY_CACHE,
                key=lambda _s: int((_V702_A29_SHORT_HISTORY_CACHE.get(_s) or {}).get("stored_at_ms", 0) or 0),
            )
            _V702_A29_SHORT_HISTORY_CACHE.pop(_oldest_sym, None)
            _evicted += 1
        if _evicted:
            STATS["v702_a29_local_history_cache_evictions"] = int(
                STATS.get("v702_a29_local_history_cache_evictions", 0) or 0
            ) + _evicted
        STATS["v702_a29_local_history_short_cache_stored"] = int(STATS.get("v702_a29_local_history_short_cache_stored", 0) or 0) + 1
        STATS["v702_a29_local_history_short_cache_last"] = {"symbol": sym, "got_closed": len(closed), "required": req,
                                                            "retry_at_ms": current_open + interval, "cache_hit": False,
                                                            "source_reason": _history_reason, "cache_size": len(_V702_A29_SHORT_HISTORY_CACHE),
                                                            "cache_cap": _cache_cap, "evicted": _evicted}
        return True
    except Exception:
        return False


def _v702_a29_terminal_self_test() -> Dict[str, Any]:
    checks = {}
    details = {}
    try:
        prior = _v702_a26_terminal_self_test()
        checks["a26_history_and_safety_contracts_pass"] = bool(prior.get("pass"))
        checks["revision_is_a29_append_only"] = bool(V702_PACKAGE_AUDIT_REVISION.startswith(V702_A28_CANONICAL_REVISION + "-A29-"))
        checks["spot_long_only_and_futures_off"] = bool(CONFIG.get("LONG_ONLY", False) and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT" and not CONFIG.get("ENABLE_FUTURES", False) and not CONFIG.get("FUTURES_ENABLED", False) and not CONFIG.get("ALLOW_SHORT", False) and not CONFIG.get("ALLOW_SHORTS", False))
        checks["score_floor_not_lowered"] = float(CONFIG.get("MIN_LIVE_SCORE", 0.0)) >= 70.0 and float(CONFIG.get("V702_ELITE_LIVE_SCORE_FLOOR_DEFAULT", 70.0)) >= 70.0
        checks["liquidity_depth_fee_and_trade_caps_preserved"] = (float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 0.0)) >= 3_000_000.0 and float(CONFIG.get("V45_TIER_MICRO_MIN_DEPTH_RATIO", 1.90)) >= 1.90 and float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 0.0)) >= 2.5 and int(CONFIG.get("MAX_CONCURRENT_TRADES", 0)) <= 2 and float(CONFIG.get("MAX_ENTRY_NOTIONAL_USDT", 0.0)) <= 75.0)
        checks["forbidden_assets_retained"] = {"AERO", "BNB", "CAKE", "ETHFI", "PUMP"}.issubset(set(V702_HARD_FORBIDDEN_BASES))
        checks["hard_gate_bypass_false"] = FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass", True) is False
        checks["quality_relief_is_one_metric_bounded"] = bool(CONFIG.get("V702_A29_ADAPTIVE_PB_RELIEF_ENABLE", False)) and float(CONFIG.get("V702_A29_PB_HTF_RELIEF_MIN", 0.0)) >= 40.0 and float(CONFIG.get("V702_A29_PB_MIN_STRONG_SETUP", 0.0)) >= 76.0 and float(CONFIG.get("V702_A29_PB_MIN_COMPOSITE_QUALITY", 0.0)) >= 78.0 and int(CONFIG.get("V702_A29_PB_MIN_CLOSED_CONFIRMATIONS", 0)) >= 3
        # The terminal self-test must be observationally pure: do not leak a
        # synthetic symbol into live/operator telemetry counters.
        _shadow_stat_keys = ("v702_a29_score_shadow_count", "v702_a29_score_shadow.PULLBACK", "v702_a29_score_shadow_last")
        _shadow_before = {k: (k in STATS, STATS.get(k)) for k in _shadow_stat_keys}
        shadow = _v702_a29_record_score_shadow(symbol="A29TEST/USDT", score=67.5, floor=70.0, family="PULLBACK")
        _shadow_seen = dict(STATS.get("v702_a29_score_shadow_last", {}) or {})
        checks["65_69_score_band_is_shadow_only"] = bool(shadow.get("recorded") and shadow.get("routes") is False and _shadow_seen.get("mode") == "SHADOW_ONLY")
        for _k, (_had, _value) in _shadow_before.items():
            if _had:
                STATS[_k] = _value
            else:
                STATS.pop(_k, None)
        checks["history_cache_is_bounded_and_reject_only"] = (
            callable(_v702_a29_history_cache_get)
            and callable(_v702_a29_history_cache_put)
            and bool(CONFIG.get("V702_A31_SHORT_HISTORY_NEGATIVE_CACHE_ENABLE", False))
            and 60.0 <= float(CONFIG.get("V702_A31_SHORT_HISTORY_RECHECK_SEC", 0.0)) <= 900.0
        )
        checks["old_hard_htf_families_remain_strict"] = (_v702_htf_policy_name("BREAKOUT_CONTINUATION", "BREAKOUT_CONTINUATION", {}) == "STRICT_ALIGNMENT" and _v702_htf_policy_name("MTF_PULLBACK", "MTF_PULLBACK", {}) == "STRICT_ALIGNMENT")
        checks["closed_bar_freshness_is_bounded"] = 300.0 <= float(CONFIG.get("V702_A29_CLOSED_BAR_MAX_AGE_SEC", 0.0)) <= 900.0
        checks["short_history_cache_is_bounded"] = 64 <= int(CONFIG.get("V702_A29_SHORT_HISTORY_CACHE_MAX", 0) or 0) <= 2048
        checks["candidate_scoped_builder_reason_capture_wired"] = callable(globals().get("_v702_store_builder_candidate_reason"))
        details["score_shadow_last"] = dict(STATS.get("v702_a29_score_shadow_last", {}) or {})
        details["hard_score_floor"] = float(CONFIG.get("MIN_LIVE_SCORE", 70.0))
        details["short_history_cache_entries"] = len(_V702_A29_SHORT_HISTORY_CACHE)
    except Exception as exc:
        checks["exception_free"] = False
        details["error"] = f"{type(exc).__name__}:{str(exc)[:200]}"
    report = {"pass": bool(checks and all(checks.values())), "checks": checks,
              "failed": [k for k, v in checks.items() if not v], "details": details,
              "revision": V702_A29_CANONICAL_REVISION, "live_network_tested": False,
              "profitability_verified": False, "soft_quality_relief_enabled": True,
              "score_65_69_live_admission": False, "hard_gate_bypass": False}
    STATS["v702_a29_terminal_self_test"] = report
    FINAL_CANONICAL_RUNTIME["v702_a29_terminal_self_test"] = report
    return report


