# =============================================================================
# V702 A30 — REJECT-ONLY SHORT-HISTORY PREFETCH THROUGHPUT CLOSURE
# =============================================================================
# A29 caches contiguous short, closed 4H history; A31 bounds negative-cache
# deferral to 420s by default (or earlier 4H boundary), because a short API response
# does not prove listing age. A30 skips three lower-timeframe reads only during this
# bounded cache window. The 210-row contract and all live gates remain unchanged.
V702_A30_CANONICAL_REVISION = (
    V702_A29_CANONICAL_REVISION + "-A30-REJECT-ONLY-HISTORY-PREFETCH-THROUGHPUT-CLOSURE"
)
V702_PACKAGE_AUDIT_REVISION = V702_A30_CANONICAL_REVISION
CONFIG["V702_A30_SHORT_HISTORY_PREFETCH_SKIP_ENABLE"] = True
FINAL_CANONICAL_RUNTIME.update({
    "package_audit_revision": V702_A30_CANONICAL_REVISION,
    "active_optimization_revision": V702_A30_CANONICAL_REVISION,
    "revision_chain_policy": "APPEND_ONLY_PREFIX_COMPATIBLE_THROUGH_A30; HISTORICAL_A21_A22_CHECKS_MUST_NOT_REQUIRE_PACKAGE_EQUALITY",
    "a30_reject_only_history_prefetch_skip": True,
    "a30_saved_reads_per_cached_reject": {"1h": 1, "15m": 1, "5m": 1},
    "a30_full_history_fetch_target": "210 contiguous closed 4H rows; no synthetic history; partial-history admission superseded by A32",
    "hard_gate_bypass": False,
})


def _v702_a30_cached_short_history_prefetch_skip(symbol: str, now_ms: Optional[int] = None):
    """Return a skip decision only for an exact, still-valid A29 reject-only cache hit.

    The function independently validates the cached timestamps before allowing the
    scanner to skip redundant lower-timeframe reads. It never changes admission:
    returned decisions always describe history that is *below* the same 210-row
    contract and therefore remains rejected by A23.
    """
    try:
        if not bool(CONFIG.get("V702_A30_SHORT_HISTORY_PREFETCH_SKIP_ENABLE", True)):
            return None
        getter = globals().get("_v702_a29_history_cache_get")
        if not callable(getter):
            return None
        now = int(now_ms if now_ms is not None else time.time() * 1000)
        cached = getter(str(symbol or ""), now)
        if not isinstance(cached, (tuple, list)) or len(cached) < 2:
            return None
        rows, info = cached[0], cached[1]
        if not isinstance(rows, (list, tuple)) or not isinstance(info, dict):
            return None
        required = max(210, int(info.get("required", 210) or 210))
        if len(rows) < 3 or len(rows) >= required or not bool(info.get("cache_hit")):
            return None
        interval = 4 * 60 * 60 * 1000
        current_open = now - (now % interval)
        stamps = []
        for row in rows:
            if not isinstance(row, (list, tuple)) or len(row) < 6:
                return None
            ts = int(row[0])
            values = [float(row[i]) for i in range(1, 6)]
            if ts <= 0 or ts >= current_open or not all(math.isfinite(v) for v in values):
                return None
            if any(values[i] <= 0 for i in range(4)) or values[4] < 0:
                return None
            stamps.append(ts)
        if stamps != sorted(stamps) or len(stamps) != len(set(stamps)):
            return None
        if stamps[-1] != current_open - interval:
            return None
        if any(stamps[i] - stamps[i - 1] != interval for i in range(1, len(stamps))):
            return None
        return {
            "skip": True, "symbol": str(symbol or ""), "got": len(rows),
            "required": required,
            "reason": "verified_reject_only_short_4h_history_cache",
            "saved_lower_tf_requests": 3,
            "execution_authority_added": False,
        }
    except Exception:
        # The scanner catches this as an optimization failure and uses the normal
        # fetch path. No cache failure can admit a candidate or block a new read.
        return None


_V702_A30_PREV_A29_SELF_TEST = _v702_a29_terminal_self_test


