# Preserve underlying cache implementation and its strict contiguous closed-bar checks,
# but expose A32 admission semantics to the scanner without turning 50–209 rows into
# reject-only hits.
_V702_A32_OLD_CACHE_GET = _v702_a29_history_cache_get
def _v702_a29_history_cache_get(symbol: str, now_ms: int):
    try:
        cached = _V702_A32_OLD_CACHE_GET(symbol, now_ms)
        if not isinstance(cached, (tuple, list)) or len(cached) < 2:
            return None
        rows, old_info = cached[0], cached[1]
        if not isinstance(old_info, dict):
            return cached
        info = dict(old_info)
        target = max(210, int(info.get("required", 210) or 210))
        minimum = _v702_a32_local_4h_min_closed_candles()
        info.update({
            "got": len(rows), "required": minimum, "target_rows": target,
            "reason": "below_minimum_short_4h_history" if len(rows) < minimum else "admissible_partial_4h_history_reuse",
            # Keep the underlying bounded-negative-cache lifecycle observable: A32
            # changes admission semantics, not the recheck TTL or cache authority.
            "cache_policy": str(info.get("cache_policy") or "BOUNDED_NEGATIVE_CACHE"),
        })
        return [list(r) for r in rows], info
    except Exception:
        return None


def _v702_a30_cached_short_history_prefetch_skip(symbol: str, now_ms: Optional[int] = None):
    """Skip lower-timeframe reads only when cached local 4H rows fail A32's 50-bar floor."""
    try:
        if not bool(CONFIG.get("V702_A30_SHORT_HISTORY_PREFETCH_SKIP_ENABLE", True)):
            return None
        getter = globals().get("_v702_a29_history_cache_get")
        if not callable(getter):
            return None
        now = int(now_ms if now_ms is not None else time.time() * 1000)
        cached = getter(str(symbol or ""), now)
        if not isinstance(cached, (tuple, list)) or len(cached) < 2:
            return None
        rows, info = cached[0], cached[1]
        if not isinstance(rows, (list, tuple)) or not isinstance(info, dict):
            return None
        minimum = _v702_a32_local_4h_min_closed_candles()
        if len(rows) >= minimum or len(rows) < 3 or not bool(info.get("cache_hit")):
            return None
        interval = 4 * 60 * 60 * 1000
        current_open = now - (now % interval)
        stamps = []
        for row in rows:
            if not isinstance(row, (list, tuple)) or len(row) < 6:
                return None
            ts = int(row[0])
            values = [float(row[i]) for i in range(1, 6)]
            if ts <= 0 or ts >= current_open or not all(math.isfinite(v) for v in values):
                return None
            if any(values[i] <= 0 for i in range(4)) or values[4] < 0:
                return None
            stamps.append(ts)
        if stamps != sorted(stamps) or len(stamps) != len(set(stamps)):
            return None
        if stamps[-1] != current_open - interval:
            return None
        if any(stamps[i] - stamps[i - 1] != interval for i in range(1, len(stamps))):
            return None
        return {
            "skip": True, "symbol": str(symbol or ""), "got": len(rows),
            "required": minimum, "target_rows": max(210, int(info.get("target_rows", 210) or 210)),
            "reason": "verified_below_minimum_contiguous_closed_4h_history",
            "saved_lower_tf_requests": 3, "execution_authority_added": False,
        }
    except Exception:
        # Optimizer errors fall through to normal data fetch; no admission is added.
        return None


def _v702_a30_record_prefetch_skip(symbol: str, decision: Any) -> bool:
    """Record one verified reject-only cache skip atomically for truthful A30 telemetry."""
    if not isinstance(decision, dict) or not bool(decision.get("skip")):
        return False
    if bool(decision.get("execution_authority_added", False)):
        # Fail closed if an optimization response unexpectedly claims admission authority.
        return False
    try:
        got = int(decision.get("got", 0) or 0)
        required = int(decision.get("required", 50) or 50)
        if got < 3 or got >= required or required != _v702_a32_local_4h_min_closed_candles():
            return False
        now = float(WALL_NOW())
        symbol_text = str(symbol or decision.get("symbol", "") or "?")
        reason = (
            f"df_4h:short_rows:got={got},required={required}:"
            "a30_reject_only_cache_prefetch"
        )
        STATS["v702_a30_cached_short_history_prefetch_skips"] = int(
            STATS.get("v702_a30_cached_short_history_prefetch_skips", 0) or 0
        ) + 1
        _saved = max(0, min(3, int(decision.get("saved_lower_tf_requests", 3) or 0)))
        STATS["v702_a30_saved_lower_tf_ohlcv_requests"] = int(
            STATS.get("v702_a30_saved_lower_tf_ohlcv_requests", 0) or 0
        ) + _saved
        STATS["v702_a23_local_history_blocks"] = int(
            STATS.get("v702_a23_local_history_blocks", 0) or 0
        ) + 1
        counts = STATS.setdefault("v702_a23_local_history_block_counts", {})
        if not isinstance(counts, dict):
            counts = {}
            STATS["v702_a23_local_history_block_counts"] = counts
        counts["df_4h"] = int(counts.get("df_4h", 0) or 0) + 1
        STATS["v702_a23_last_local_history_block"] = {
            "symbol": symbol_text, "reason": reason, "ts": now, "a30_cached_prefetch_skip": True,
        }
        STATS["v45_market_data_rejects"] = int(STATS.get("v45_market_data_rejects", 0) or 0) + 1
        STATS["v702_a30_last_cached_history_skip"] = {
            "symbol": symbol_text, "got": got, "required": required,
            "saved_lower_tf_requests": _saved, "ts": now,
        }
        STATS["v702_a30_last_skip_recorded_ts"] = now
        return True
    except Exception:
        _v647_record_suppressed_exception()
        return False


def _v702_a34_spread_context_fields(candidate: Any = None, market_data: Any = None, quality_context: Any = None) -> Dict[str, Any]:
    """Extract only scalar market-quality fields for Shadow spread diagnostics; never copy candles."""
    out: Dict[str, Any] = {}
    feature_sources = []
    try:
        features = getattr(candidate, "features_snapshot", {}) or {}
        if isinstance(features, dict): feature_sources.append(features)
    except Exception:
        pass
    if isinstance(market_data, dict): feature_sources.append(market_data)
    if isinstance(quality_context, dict): feature_sources.append(quality_context)
    def _first(keys):
        for source in feature_sources:
            for key in keys:
                try:
                    value = float(source.get(key))
                    if math.isfinite(value) and value > 0:
                        return value
                except Exception:
                    continue
        return None
    atr_pct = _first(("atr_pct", "atr_percent", "atr_percentage", "atr_pct_14", "atr_percent_14"))
    atr_pct_source = "CONTEXT_ATR_PCT" if atr_pct is not None else "UNAVAILABLE"
    if atr_pct is None:
        atr = _first(("atr", "atr_14", "atr_value", "atr14"))
        price = _first(("close", "last", "last_price", "price", "current_price", "last_close"))
        if atr is not None and price is not None:
            atr_pct = 100.0 * atr / price
            atr_pct_source = "CONTEXT_ATR_PRICE" if atr_pct > 0 and math.isfinite(atr_pct) else "UNAVAILABLE"
    # If prepared candidate features omit ATR, derive it from CLOSED OHLCV bars
    # carried in the same market snapshot. Exclude the final potentially forming
    # candle and use a fixed 14-bar true-range mean. This is shadow-only data; it
    # never modifies spread acceptance or the live ceiling.
    if atr_pct is None and isinstance(market_data, dict) and _PDNP_OK:
        for _tf in ("5m", "15m", "1h"):
            try:
                _frame = market_data.get(f"df_{_tf}")
                if _frame is None or len(_frame) < 16 or not all(k in _frame.columns for k in ("high", "low", "close")):
                    continue
                _closed = _frame.iloc[:-1]
                _high = _closed["high"].astype(float)
                _low = _closed["low"].astype(float)
                _close = _closed["close"].astype(float)
                _prev_close = _close.shift(1)
                _tr = pd.concat([_high - _low, (_high - _prev_close).abs(), (_low - _prev_close).abs()], axis=1).max(axis=1)
                _tr = _tr.replace([math.inf, -math.inf], float("nan")).dropna()
                _price = float(_close.iloc[-1])
                _atr = float(_tr.tail(14).mean()) if len(_tr) >= 14 else float("nan")
                _derived = (100.0 * _atr / _price) if _price > 0 else float("nan")
                if math.isfinite(_derived) and _derived > 0:
                    atr_pct = _derived
                    atr_pct_source = f"CLOSED_OHLCV_{_tf.upper()}_ATR14"
                    break
            except Exception:
                continue
    depth = _first(("depth_ratio", "orderbook_depth_ratio", "depth_ratio_20bps"))
    qv = _first(("quote_volume_24h", "quote_vol_24h", "quoteVolume", "quote_volume"))
    for key, value in (("atr_pct", atr_pct), ("depth_ratio", depth), ("quote_volume_24h", qv)):
        if value is not None and math.isfinite(value) and value > 0:
            out[key] = value
    out["atr_pct_source"] = atr_pct_source
    # Preserve the low-cost scoring context when present; it can help stratify rejects.
    if isinstance(quality_context, dict):
        for source_key, out_key in (("score", "quality_score"), ("reviewed_score", "reviewed_score"),
                                    ("htf", "htf_strength"), ("vol", "volume_ratio"),
                                    ("rs", "relative_strength"), ("chase", "chase_atr")):
            try:
                value = float(quality_context.get(source_key))
                if math.isfinite(value): out[out_key] = value
            except Exception:
                pass
    return out


def _v702_a34_record_spread_shadow_observation(tier: str, spread_pct: float, ceiling_pct: float, context: Any = None) -> None:
    """Record a rejected spread observation for offline study; never changes the live verdict or ceiling."""
    try:
        tier_name = str(getattr(tier, "value", tier) or "UNKNOWN").strip().upper().rsplit(".", 1)[-1]
        spread = float(spread_pct)
        ceiling = float(ceiling_pct)
        if not (math.isfinite(spread) and spread >= 0 and math.isfinite(ceiling) and ceiling > 0 and spread > ceiling):
            return
        ctx = context if isinstance(context, dict) else {}
        candidate = ctx.get("candidate")
        features = ctx.get("features") or ctx.get("features_snapshot") or ctx.get("snapshot") or ctx
        if not isinstance(features, dict) and candidate is not None:
            features = getattr(candidate, "features_snapshot", {}) or {}
        if not isinstance(features, dict):
            features = {}
        def _num(d, keys):
            for key in keys:
                try:
                    value = float(d.get(key))
                    if math.isfinite(value) and value > 0:
                        return value
                except Exception:
                    continue
            return None
        atr_keys = ("atr_pct", "atr_percent", "atr_percentage", "atr_pct_14", "atr_percent_14")
        atr_pct = _num(features, atr_keys)
        if atr_pct is None:
            # _v702_a34_spread_context_fields may have derived this value from
            # closed OHLCV while the nested `features` map remains incomplete.
            atr_pct = _num(ctx, atr_keys)
        if atr_pct is None:
            atr_raw = _num(features, ("atr", "atr_14", "atr_value", "atr14")) or _num(ctx, ("atr", "atr_14", "atr_value", "atr14"))
            price_raw = _num(features, ("close", "last", "last_price", "price", "current_price", "mark_price")) or _num(ctx, ("close", "last", "last_price", "price", "current_price", "mark_price"))
            if atr_raw is not None and price_raw is not None and price_raw > 0:
                derived = 100.0 * atr_raw / price_raw
                if math.isfinite(derived) and derived > 0:
                    atr_pct = derived
        depth = _num(features, ("depth_ratio", "orderbook_depth_ratio", "depth_ratio_20bps"))
        qv = _num(features, ("quote_volume_24h", "quote_vol_24h", "quoteVolume", "quote_volume"))
        record = {
            "tier": tier_name, "spread_pct": spread, "fixed_ceiling_pct": ceiling,
            "atr_pct": atr_pct, "atr_pct_source": str(features.get("atr_pct_source") or ctx.get("atr_pct_source") or "UNAVAILABLE")[:48],
            "spread_to_atr_ratio": (spread / atr_pct if atr_pct else None),
            "depth_ratio": depth, "quote_volume_24h": qv,
            "quality_score": _num(ctx, ("quality_score", "score")),
            "reviewed_score": _num(ctx, ("reviewed_score",)),
            "htf_strength": _num(ctx, ("htf_strength", "htf")),
            "volume_ratio": _num(ctx, ("volume_ratio", "vol")),
            "relative_strength": ctx.get("relative_strength", ctx.get("rs")),
            "chase_atr": _num(ctx, ("chase_atr", "chase")),
            "ts": float(WALL_NOW()), "mode": "SHADOW_ONLY_NO_LIVE_RELIEF",
            "actual_live_decision": "REJECTED_FIXED_CEILING",
        }
        STATS["v702_a34_spread_shadow_rejects"] = int(STATS.get("v702_a34_spread_shadow_rejects", 0) or 0) + 1
        by_tier = STATS.setdefault("v702_a34_spread_shadow_by_tier", {})
        if not isinstance(by_tier, dict):
            by_tier = {}; STATS["v702_a34_spread_shadow_by_tier"] = by_tier
        by_tier[tier_name] = int(by_tier.get(tier_name, 0) or 0) + 1
        history = STATS.setdefault("v702_a34_spread_shadow_history", [])
        if not isinstance(history, list):
            history = []; STATS["v702_a34_spread_shadow_history"] = history
        history.append(record)
        if len(history) > 256:
            del history[:-256]
        STATS["v702_a34_spread_shadow_last"] = record
    except Exception:
        _v647_record_suppressed_exception()


def tier_spread_hard_ok_v410(spread_pct: Optional[float], tier: str) -> Tuple[bool, str]:
    """Canonical tier spread check whose diagnostic operator matches the verdict."""
    try:
        tier_raw = getattr(tier, "value", tier)
        tier_name = str(tier_raw or "").strip().upper()
        if "." in tier_name:
            tier_name = tier_name.rsplit(".", 1)[-1]
        if tier_name == "BELOW":
            return False, "tier_below_minimum"
        if tier_name not in {"MAJORS", "LARGE", "MID", "MICRO"}:
            return False, f"spread_tier_unverifiable:tier={tier_name or 'MISSING'}"
        if spread_pct is None:
            return False, f"spread_missing:tier={tier_name}"
        spread = float(spread_pct)
        if not math.isfinite(spread) or spread < 0.0:
            return False, f"spread_invalid:tier={tier_name}"
        if not bool(CONFIG.get("V410_TIER_SPREAD_HARD_REJECT", True)):
            return True, f"spread_gate_disabled:tier={tier_name}"
        spread_map = CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}
        ceiling = float(spread_map.get(tier_name, CONFIG.get("SCORE_SPREAD_CEIL_PCT", 0.15)))
        if not math.isfinite(ceiling) or ceiling <= 0.0:
            return False, f"spread_ceiling_invalid:tier={tier_name}:ceil={ceiling!r}"
        if spread <= ceiling:
            return True, f"spread={spread:.4f}%<=ceil={ceiling:.4f}%:tier={tier_name}"
        # Preserve the existing ultra-elite exception only when explicitly enabled
        # and independently qualified; no global/tier ceiling is raised.
        ctx = None
        try:
            ctx = _V549_SPREAD_CONTEXT.get() or _V528_SPREAD_CONTEXT.get()
            relief_fn = globals().get("_v549_ultra_elite_spread_allow")
            if callable(relief_fn):
                allowed, relief_reason = relief_fn(spread, tier_name, ctx)
                if allowed:
                    return True, str(relief_reason)
        except Exception:
            pass
        _spread_observer = globals().get("_v702_a34_record_spread_shadow_observation")
        if callable(_spread_observer):
            _spread_observer(tier_name, spread, ceiling, ctx)
        return False, f"spread={spread:.4f}%>ceil={ceiling:.4f}%:tier={tier_name}"
    except Exception as exc:
        return False, f"spread_check_error:{type(exc).__name__}"


# Replace the active resolver with a bounded-confidence 4H proxy for 50–209 rows.
# Full-history cases continue through the previous EMA50/EMA200 calculation unchanged.
_V702_A32_PREV_HTF_RESOLVER = _v690_resolve_htf_strength
def _v702_a32_resolve_htf_strength(symbol, snapshot, candidate=None):
    snap = snapshot if isinstance(snapshot, dict) else {}
    df1, df4 = snap.get("df_1h"), snap.get("df_4h")
    try:
        raw = float(snap.get("htf_strength") or 0.0)
    except Exception:
        raw = 0.0
    state = str(snap.get("htf_state") or "UNKNOWN").upper()
    reason = str(snap.get("htf_reason") or "").strip().lower()
    unusable = reason in {"insufficient_data", "invalid_close_history", "invalid_closed_values", "snapshot_unavailable", "htf_grade_exception"} or reason.startswith("error:")
    # Valid raw 1H evidence and credible hard-bearish evidence retain precedence.
    if (math.isfinite(raw) and raw > 0.0) or (state in {"BEARISH", "HARD_REJECT", "CRASH", "BEARISH_CRASH"} and not unusable):
        return _V702_A32_PREV_HTF_RESOLVER(symbol, snap, candidate)
    try:
        full_4h_warmup = max(210, int(CONFIG.get("HTF_MIN_CANDLES_4H", 200) or 200))
        if df4 is not None and len(df4) >= full_4h_warmup:
            return _V702_A32_PREV_HTF_RESOLVER(symbol, snap, candidate)
        if not bool(CONFIG.get("V702_A32_SHORT_HISTORY_PROXY_ENABLE", True)):
            return _V702_A32_PREV_HTF_RESOLVER(symbol, snap, candidate)
        min_rows = _v702_a32_local_4h_min_closed_candles()
        if df1 is None or df4 is None or len(df4) < min_rows:
            STATS["v702_a32_htf_proxy_unavailable"] = int(STATS.get("v702_a32_htf_proxy_unavailable", 0) or 0) + 1
            STATS["v702_a32_htf_proxy_last_reason"] = "below_minimum_4h_history"
            return None, "UNAVAILABLE", 0.0
        history_ok, history_reason = _v702_a32_4h_history_integrity(df4, min_rows)
        if not history_ok:
            STATS["v702_a32_htf_proxy_unavailable"] = int(STATS.get("v702_a32_htf_proxy_unavailable", 0) or 0) + 1
            STATS["v702_a32_htf_proxy_last_reason"] = str(history_reason)
            snap["htf_recompute_reason"] = str(history_reason)
            return None, "UNAVAILABLE", 0.0
        req1 = max(210, int(CONFIG.get("HTF_MIN_CANDLES_1H", 240) or 240))
        if len(df1) < req1:
            STATS["v702_a32_htf_proxy_unavailable"] = int(STATS.get("v702_a32_htf_proxy_unavailable", 0) or 0) + 1
            STATS["v702_a32_htf_proxy_last_reason"] = "1h_ema200_warmup_insufficient"
            return None, "UNAVAILABLE", 0.0
        if not _PDNP_OK or "close" not in getattr(df1, "columns", ()) or "close" not in getattr(df4, "columns", ()):
            return None, "RECOMPUTE_ERROR", 0.0
        c1 = pd.to_numeric(df1["close"], errors="coerce")
        c4 = pd.to_numeric(df4["close"], errors="coerce")
        h1 = [float(x) for x in c1.iloc[-req1:].tolist()]
        h4 = [float(x) for x in c4.tolist()]
        if (len(h1) < req1 or len(h4) < min_rows
                or any(not math.isfinite(x) or x <= 0.0 for x in h1)
                or any(not math.isfinite(x) or x <= 0.0 for x in h4)):
            return None, "UNAVAILABLE", 0.0
        # Decisions are made only from the last CLOSED row (iloc[-2]); no current
        # forming 4H candle is used in the signal. The proxy deliberately avoids EMA200.
        e1_50 = c1.ewm(span=50, adjust=False).mean()
        e1_200 = c1.ewm(span=200, adjust=False).mean()
        e4_20 = c4.ewm(span=20, adjust=False).mean()
        e4_50 = c4.ewm(span=50, adjust=False).mean()
        idx = -2
        vals = (float(c1.iloc[idx]), float(e1_50.iloc[idx]), float(e1_200.iloc[idx]),
                float(c4.iloc[idx]), float(e4_20.iloc[idx]), float(e4_50.iloc[idx]),
                float(e4_50.iloc[-7]))
        if not all(math.isfinite(v) and v > 0.0 for v in vals):
            return None, "UNAVAILABLE", 0.0
        close1, oneh_50, oneh_200, close4, fourh_20, fourh_50, fourh_50_prev = vals
        raw_score = (
            20.0 * bool(fourh_20 > fourh_50)
            + 10.0 * bool(close4 > fourh_20)
            + 10.0 * bool(fourh_50 > fourh_50_prev)
            + 10.0 * bool(oneh_50 > oneh_200)
            + 5.0 * bool(close1 > oneh_50)
        )
        bars = len(df4)
        confidence_cap = 50.0 if bars < 75 else 52.0 if bars < 100 else 53.5 if bars < 150 else 55.0
        score = min(float(raw_score), confidence_cap)
        snap.update({
            "htf_primary_strength": raw,
            "htf_recomputed_strength": score,
            "htf_recompute_used": True,
            "htf_recompute_reason": "bounded_short_4h_history_proxy",
            "htf_history_rows": bars,
            "htf_history_minimum": min_rows,
            "htf_history_full_warmup": max(210, int(CONFIG.get("HTF_MIN_CANDLES_4H", 200) or 200)),
            "htf_history_confidence_cap": confidence_cap,
            "htf_evidence_class": "HTF_LIMITED_HISTORY",
        })
        STATS["v702_a32_htf_proxy_used"] = int(STATS.get("v702_a32_htf_proxy_used", 0) or 0) + 1
        STATS["v702_a32_htf_proxy_last"] = {
            "symbol": str(symbol or snap.get("symbol") or "?"), "rows": bars,
            "score": score, "raw_score": raw_score, "confidence_cap": confidence_cap,
            "reason": "bounded_short_4h_history_proxy", "ts": float(WALL_NOW()),
        }
        return score, "RECOMPUTED_H0", 0.0
    except Exception as exc:
        STATS["v702_a32_htf_proxy_errors"] = int(STATS.get("v702_a32_htf_proxy_errors", 0) or 0) + 1
        STATS["v702_a32_htf_proxy_last_reason"] = f"{type(exc).__name__}:{str(exc)[:120]}"
        return None, "RECOMPUTE_ERROR", 0.0


_v690_resolve_htf_strength = _v702_a32_resolve_htf_strength
_v689_resolve_htf_strength = _v702_a32_resolve_htf_strength


def _v702_a32_terminal_self_test() -> Dict[str, Any]:
    """Final A32 terminal contract: adaptive local 4H evidence without live-gate bypass."""
    try:
        base = _v702_a31_terminal_self_test()
        if not isinstance(base, dict):
            base = {"pass": False, "checks": {}, "failed": ["a31_terminal_report_missing"]}
        report = dict(base)
        checks = dict(report.get("checks") or {})
        details = dict(report.get("details") or {})
        minimum = _v702_a32_local_4h_min_closed_candles()
        checks["a32_revision_appends_a31"] = V702_PACKAGE_AUDIT_REVISION.startswith(V702_A31_CANONICAL_REVISION + "-A32-")
        checks["a32_local_4h_minimum_is_bounded"] = 50 <= minimum <= 210
        if _PDNP_OK and pd is not None:
            def _a32_frame(rows: int):
                return pd.DataFrame({"open": [1.0] * rows, "high": [1.1] * rows,
                                     "low": [0.9] * rows, "close": [1.0] * rows,
                                     "volume": [10.0] * rows})
            _good_frames = {"df_4h": _a32_frame(50), "df_1h": _a32_frame(240),
                            "df_15m": _a32_frame(350), "df_5m": _a32_frame(30)}
            _short_good, _short_good_reason = _mse_candidate_scan_precheck(_good_frames)
            _below_frames = dict(_good_frames)
            _below_frames["df_4h"] = _a32_frame(49)
            _short_bad, _short_bad_reason = _mse_candidate_scan_precheck(_below_frames)
            checks["a32_accepts_50_realistic_rows"] = bool(_short_good and _short_good_reason == "ok")
            checks["a32_rejects_below_50_without_fabrication"] = bool(not _short_bad and str(_short_bad_reason).startswith("df_4h:short_rows:"))
            details["minimum_boundary"] = {"50_rows": _short_good_reason, "49_rows": _short_bad_reason}
        else:
            checks["a32_pandas_available_for_history_contract"] = False
        checks["a32_short_history_proxy_is_installed"] = callable(_v702_a32_resolve_htf_strength) and bool(CONFIG.get("V702_A32_SHORT_HISTORY_PROXY_ENABLE", False))
        checks["a32_spread_failure_reason_matches_comparison"] = (
            not tier_spread_hard_ok_v410(0.99, "MICRO")[0]
            and ">ceil=" in tier_spread_hard_ok_v410(0.99, "MICRO")[1]
            and tier_spread_hard_ok_v410(0.25, "MICRO")[0]
        )
        checks["a32_no_bypass_and_critical_live_floors_preserved"] = (
            FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass", True) is False
            and bool(CONFIG.get("LONG_ONLY", False)) and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT"
            and not bool(CONFIG.get("ENABLE_FUTURES", False)) and not bool(CONFIG.get("ALLOW_SHORT", False))
            and float(CONFIG.get("MIN_LIVE_SCORE", 0.0)) >= 70.0
            and float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 0.0)) >= 3_000_000.0
            and float(CONFIG.get("V45_TIER_MICRO_MIN_DEPTH_RATIO", 0.0)) >= 1.90
            and float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 0.0)) >= 2.5
        )
        checks["a32_forbidden_bases_preserved"] = {"AERO", "BNB", "CAKE", "ETHFI", "PUMP"}.issubset(set(V702_HARD_FORBIDDEN_BASES))
        checks["a32_live_trade_authority_unchanged"] = (
            int(CONFIG.get("MAX_CONCURRENT_TRADES", 99)) <= 2
            and float(CONFIG.get("MAX_ENTRY_NOTIONAL_USDT", 1e9)) <= 75.0
            and FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass", True) is False
        )
        details["local_4h_history_policy"] = {
            "minimum_closed_candles": minimum,
            "full_ema200_warmup_candles": max(210, int(CONFIG.get("HTF_MIN_CANDLES_4H", 200) or 200)),
            "btc_macro_minimum_unchanged": 210,
            "short_history_proxy_enabled": bool(CONFIG.get("V702_A32_SHORT_HISTORY_PROXY_ENABLE", False)),
            "synthetic_rows": 0,
        }
        report["checks"] = checks
        report["failed"] = [k for k, v in checks.items() if not v]
        report["pass"] = bool(base.get("pass", False) and all(checks.values()))
        report["revision"] = V702_A32_CANONICAL_REVISION
        report["scope"] = str(report.get("scope") or "") + "; A32_ADAPTIVE_LOCAL_4H_HISTORY_AND_TRUTHFUL_SPREAD_DIAGNOSTICS"
        report["hard_gate_bypass"] = False
        report["live_gates_relaxed"] = False
        report["live_network_tested"] = False
        report["profitability_verified"] = False
        report["details"] = details
        STATS["v702_a32_terminal_self_test"] = report
        FINAL_CANONICAL_RUNTIME["v702_a32_terminal_self_test"] = report
        return report
    except Exception as exc:
        report = {"pass": False, "checks": {"exception_free": False},
                  "failed": [f"{type(exc).__name__}:{str(exc)[:140]}"],
                  "revision": V702_A32_CANONICAL_REVISION,
                  "hard_gate_bypass": False, "live_gates_relaxed": False,
                  "live_network_tested": False, "profitability_verified": False}
        STATS["v702_a32_terminal_self_test"] = report
        FINAL_CANONICAL_RUNTIME["v702_a32_terminal_self_test"] = report
        return report


# Keep older hook names for frozen validation wrappers, but make A32 the actual final policy.
_v702_a29_terminal_self_test = _v702_a32_terminal_self_test
_V702_A32_PREV_VALIDATE_CONFIG = validate_config
def _v702_a32_validate_config() -> bool:
    try:
        base_ok = bool(_V702_A32_PREV_VALIDATE_CONFIG())
        report = STATS.get("v702_a32_terminal_self_test")
        if not isinstance(report, dict):
            report = _v702_a32_terminal_self_test()
        result = bool(base_ok and report.get("pass", False))
        validation = {
            "pass": result, "base_validation_pass": base_ok,
            "terminal_self_test_pass": bool(report.get("pass", False)),
            "failed": list(report.get("failed") or []),
            "revision": V702_A32_CANONICAL_REVISION,
            "hard_gate_bypass": False, "live_gates_relaxed": False,
            "live_network_tested": False, "profitability_verified": False,
        }
        STATS["v702_a32_validation"] = validation
        FINAL_CANONICAL_RUNTIME["v702_a32_validation"] = validation
        FINAL_CANONICAL_RUNTIME["package_audit_revision"] = V702_A32_CANONICAL_REVISION
        FINAL_CANONICAL_RUNTIME["active_optimization_revision"] = V702_A32_CANONICAL_REVISION
        if result:
            logger.info("[V702-A32-VALIDATION] PASS local_4h_min_closed=%s hard_gate_bypass=false", _v702_a32_local_4h_min_closed_candles())
        else:
            logger.critical("[V702-A32-VALIDATION] fail_closed failed=%s hard_gate_bypass=false", validation["failed"])
        return result
    except Exception as exc:
        STATS["v702_a32_validation_error"] = f"{type(exc).__name__}:{str(exc)[:140]}"
        return False

