# =============================================================================
# V702 A33 — ADAPTIVE LOCAL 1H HISTORY + TRUTHFUL PREQUAL ROOT DIAGNOSTICS
# =============================================================================
# A32 allowed short local 4H history, but the early scanner and Builder still
# rejected 1H frames below 240 rows. A33 separates the normal fetch target (240)
# from a guarded admission minimum (210 closed 1H rows) when local 4H has passed
# A32's 50-closed-bar contract. No history is fabricated and BTC macro gates stay
# independent. Prequal root attribution is telemetry-only; it cannot change verdicts.
V702_A33_CANONICAL_REVISION = (
    V702_A32_CANONICAL_REVISION
    + "-A33-ADAPTIVE-1H-HISTORY-AND-ROOT-CAUSE-COHERENCE-CLOSURE"
)
CONFIG.update({
    "V702_A33_ADAPTIVE_1H_SHORT_HISTORY_ENABLE": True,
    "V702_A33_LOCAL_1H_MIN_CLOSED_CANDLES": 210,
    "V702_A33_LOCAL_1H_FULL_HISTORY_TARGET": max(240, int(CONFIG.get("HTF_MIN_CANDLES_1H", 240) or 240)),
})
V702_A34_CANONICAL_REVISION = V702_A33_CANONICAL_REVISION + "-A34-HF2-MICRO-ALLOWLIST-SHADOW-PROGRESS-CACHE-TTL-AND-SPREAD-SHADOW-CLOSURE"
V702_PACKAGE_AUDIT_REVISION = V702_A34_CANONICAL_REVISION
FINAL_CANONICAL_RUNTIME.update({
    "package_audit_revision": V702_A34_CANONICAL_REVISION,
    "active_optimization_revision": V702_A34_CANONICAL_REVISION,
    "active_release_tag": "UNIFIED-SCALPER-V702-A34-HF2-CANONICAL-CANDIDATE",
    "revision_chain_policy": "APPEND_ONLY_PREFIX_COMPATIBLE_THROUGH_A34; HARD_ENTRY_AND_EXECUTION_GATES_UNCHANGED",
    "a33_local_1h_history_policy": "MINIMUM_210_CLOSED_1H_ROWS_ONLY_WHEN_LOCAL_4H_MINIMUM_PASSES; FETCH_TARGET_240; NO_SYNTHETIC_ROWS",
    "a33_prequal_root_diagnostics": "CURRENT_CYCLE_SELECTION_AWARE; RECENT_PREQUAL_REASONS_ONLY; TELEMETRY_ONLY",
    "a34_micro_handoff_policy": "ALLOWLIST_CHECK_BEFORE_PER_CANDIDATE_DIAGNOSTIC; NON_ALLOWLISTED_LANES_ONLY_AGGREGATED",
    "a34_shadow_gap_policy": "EXACT_CANDIDATE_REF_PLUS_RECENT_PRESEND_OR_QUEUE_EVIDENCE_REQUIRED",
    "a31_short_history_recheck_sec": 420.0,
    "a34_spread_policy": "COLLECT_FIXED_CAP_REJECTIONS_FOR_SHADOW_ANALYSIS_ONLY; NEVER_RAISE_LIVE_CAP",
    "hard_gate_bypass": False,
})

_V702_A33_PREV_HTF_RESOLVER = _v702_a32_resolve_htf_strength
def _v702_a33_resolve_htf_strength(symbol, snapshot, candidate=None):
    """Bounded-confidence HTF proxy for valid short 4H or 1H local history."""
    snap = snapshot if isinstance(snapshot, dict) else {}
    df1, df4 = snap.get("df_1h"), snap.get("df_4h")
    try:
        raw = float(snap.get("htf_strength") or 0.0)
    except Exception:
        raw = 0.0
    state = str(snap.get("htf_state") or "UNKNOWN").upper()
    reason = str(snap.get("htf_reason") or "").strip().lower()
    unusable = reason in {"insufficient_data", "invalid_close_history", "invalid_closed_values", "snapshot_unavailable", "htf_grade_exception"} or reason.startswith("error:")
    # Valid/raw evidence and credible bearish/crash evidence retain absolute precedence.
    if ((math.isfinite(raw) and raw > 0.0)
            or (state in {"BEARISH", "HARD_REJECT", "CRASH", "BEARISH_CRASH"} and not unusable)):
        return _V702_A33_PREV_HTF_RESOLVER(symbol, snap, candidate)
    try:
        full4 = max(210, int(CONFIG.get("V702_A32_LOCAL_4H_FULL_EMA200_WARMUP_CANDLES", 210) or 210))
        full1 = max(210, int(CONFIG.get("HTF_MIN_CANDLES_1H", 240) or 240))
        min4 = _v702_a32_local_4h_min_closed_candles()
        min1 = _v702_a33_local_1h_min_closed_candles({"df_4h": df4})
        # Use the legacy full-history resolver only when both local frames meet their full warmups.
        if df4 is not None and len(df4) >= full4 and df1 is not None and len(df1) >= full1:
            return _V702_A33_PREV_HTF_RESOLVER(symbol, snap, candidate)
        if not bool(CONFIG.get("V702_A32_SHORT_HISTORY_PROXY_ENABLE", True)):
            return _V702_A33_PREV_HTF_RESOLVER(symbol, snap, candidate)
        if (df1 is None or df4 is None or len(df4) < min4 or len(df1) < min1
                or not _mse_context_ok(df4, min4) or not _mse_context_ok(df1, min1)):
            if str(STATS.get("v702_pipeline_metrics_scope", "")) == "LIVE_EPOCH_UNIQUE_CANDIDATE_STAGES":
                STATS["v702_a33_htf_proxy_unavailable"] = int(STATS.get("v702_a33_htf_proxy_unavailable", 0) or 0) + 1
            STATS["v702_a33_htf_proxy_last_reason"] = "below_minimum_local_4h_or_1h_history"
            return None, "UNAVAILABLE", 0.0
        ok4, why4 = _v702_a32_4h_history_integrity(df4, min4)
        if not ok4:
            if str(STATS.get("v702_pipeline_metrics_scope", "")) == "LIVE_EPOCH_UNIQUE_CANDIDATE_STAGES":
                STATS["v702_a33_htf_proxy_unavailable"] = int(STATS.get("v702_a33_htf_proxy_unavailable", 0) or 0) + 1
            STATS["v702_a33_htf_proxy_last_reason"] = str(why4)
            snap["htf_recompute_reason"] = str(why4)
            return None, "UNAVAILABLE", 0.0
        ok1, why1 = _v702_a33_local_1h_history_integrity(df1, min1)
        if not ok1:
            if str(STATS.get("v702_pipeline_metrics_scope", "")) == "LIVE_EPOCH_UNIQUE_CANDIDATE_STAGES":
                STATS["v702_a33_htf_proxy_unavailable"] = int(STATS.get("v702_a33_htf_proxy_unavailable", 0) or 0) + 1
            STATS["v702_a33_htf_proxy_last_reason"] = str(why1)
            snap["htf_recompute_reason"] = str(why1)
            return None, "UNAVAILABLE", 0.0
        if not (_PDNP_OK and pd is not None and "close" in getattr(df1, "columns", ()) and "close" in getattr(df4, "columns", ())):
            return None, "RECOMPUTE_ERROR", 0.0
        c1 = pd.to_numeric(df1["close"], errors="coerce")
        c4 = pd.to_numeric(df4["close"], errors="coerce")
        if (not np.isfinite(c1.to_numpy(dtype=float)).all() or not np.isfinite(c4.to_numpy(dtype=float)).all()
                or (c1 <= 0).any() or (c4 <= 0).any()):
            return None, "UNAVAILABLE", 0.0
        e1_50 = c1.ewm(span=50, adjust=False).mean()
        e1_200 = c1.ewm(span=200, adjust=False).mean()
        e4_20 = c4.ewm(span=20, adjust=False).mean()
        e4_50 = c4.ewm(span=50, adjust=False).mean()
        idx1 = _v702_a33_closed_index(df1, 60 * 60 * 1000)
        idx4 = _v702_a33_closed_index(df4, 4 * 60 * 60 * 1000)
        prev4 = idx4 - 5
        if abs(idx1) > len(c1) or abs(idx4) > len(c4) or abs(prev4) > len(c4):
            return None, "UNAVAILABLE", 0.0
        vals = (float(c1.iloc[idx1]), float(e1_50.iloc[idx1]), float(e1_200.iloc[idx1]),
                float(c4.iloc[idx4]), float(e4_20.iloc[idx4]), float(e4_50.iloc[idx4]),
                float(e4_50.iloc[prev4]))
        if not all(math.isfinite(v) and v > 0.0 for v in vals):
            return None, "UNAVAILABLE", 0.0
        close1, oneh_50, oneh_200, close4, fourh_20, fourh_50, fourh_50_prev = vals
        raw_score = (
            20.0 * bool(fourh_20 > fourh_50)
            + 10.0 * bool(close4 > fourh_20)
            + 10.0 * bool(fourh_50 > fourh_50_prev)
            + 10.0 * bool(oneh_50 > oneh_200)
            + 5.0 * bool(close1 > oneh_50)
        )
        bars4 = sum(1 for ts in (_v702_a33_timestamp_ms(df4) or [])
                    if ts < (int(time.time() * 1000) - (int(time.time() * 1000) % (4 * 60 * 60 * 1000)))) if _v702_a33_timestamp_ms(df4) else len(df4)
        bars1 = sum(1 for ts in (_v702_a33_timestamp_ms(df1) or [])
                    if ts < (int(time.time() * 1000) - (int(time.time() * 1000) % (60 * 60 * 1000)))) if _v702_a33_timestamp_ms(df1) else len(df1)
        cap4 = 50.0 if bars4 < 75 else 52.0 if bars4 < 100 else 53.5 if bars4 < 150 else 55.0
        cap1 = 50.0 if bars1 < 220 else 52.0 if bars1 < 240 else 55.0
        confidence_cap = min(cap4, cap1)
        score = min(float(raw_score), confidence_cap)
        snap.update({
            "htf_primary_strength": raw, "htf_recomputed_strength": score,
            "htf_recompute_used": True,
            "htf_recompute_reason": "bounded_short_local_4h_1h_history_proxy",
            "htf_history_rows": bars4, "htf_history_minimum": min4,
            "htf_history_full_warmup": full4,
            "htf_1h_history_rows": bars1, "htf_1h_history_minimum": min1,
            "htf_1h_history_full_warmup": full1,
            "htf_history_confidence_cap": confidence_cap,
            "htf_evidence_class": "HTF_LIMITED_HISTORY",
        })
        if str(STATS.get("v702_pipeline_metrics_scope", "")) == "LIVE_EPOCH_UNIQUE_CANDIDATE_STAGES":
            STATS["v702_a33_htf_proxy_used"] = int(STATS.get("v702_a33_htf_proxy_used", 0) or 0) + 1
            STATS["v702_a33_htf_proxy_last"] = {
                "symbol": str(symbol or snap.get("symbol") or "?"), "rows_1h": bars1,
                "rows_4h": bars4, "score": score, "raw_score": raw_score,
                "confidence_cap": confidence_cap, "reason": "bounded_short_local_4h_1h_history_proxy",
                "ts": float(WALL_NOW()),
            }
        return score, "RECOMPUTED_H0", 0.0
    except Exception as exc:
        if str(STATS.get("v702_pipeline_metrics_scope", "")) == "LIVE_EPOCH_UNIQUE_CANDIDATE_STAGES":
            STATS["v702_a33_htf_proxy_errors"] = int(STATS.get("v702_a33_htf_proxy_errors", 0) or 0) + 1
        STATS["v702_a33_htf_proxy_last_reason"] = f"{type(exc).__name__}:{str(exc)[:120]}"
        return None, "RECOMPUTE_ERROR", 0.0

_v690_resolve_htf_strength = _v702_a33_resolve_htf_strength
_v689_resolve_htf_strength = _v702_a33_resolve_htf_strength

# Correct the entry-root digest only when it is a real live heartbeat and the
# current candidate cycle has no SELECTED candidates. Historical/direct unit-call
# behavior remains unchanged. This changes telemetry, never trade admission.
_V702_A33_PREV_ENTRY_BLOCK_SUMMARY = _v702_a7_entry_block_summary
def _v702_a33_reason_root(reason: str) -> str:
    r = str(reason or "").strip().lower()
    if r.startswith("htf.") or "bearish_crash_guard" in r or r.startswith("crash."):
        return "HTF"
    if r.startswith("liquidity.") or "spread" in r or "depth_ratio" in r or "orderbook" in r:
        return "LIQUIDITY"
    if any(x in r for x in ("fee", "net_rr", "net_profit", "cost_unviable", "fee_unviable")):
        return "FEE"
    if r.startswith("structure.") or "structure" in r or "fake_break" in r:
        return "STRUCTURE"
    if r.startswith("policy.") or "family_regime_disallowed" in r or "tier." in r:
        return "POLICY"
    return "OTHER"


def _v702_a33_entry_block_summary(status_text: str = ""):
    root, age = _V702_A33_PREV_ENTRY_BLOCK_SUMMARY(status_text)
    text = str(status_text or "")
    # Preserve the public helper contract used by older validators and direct calls.
    if root != "NONE" or not ("state=" in text.lower() and "funnel=" in text.lower()):
        return root, age
    try:
        pipeline = V702PipelineMetrics.snapshot()
        cycle_counts = pipeline.get("cycle_counts", {}) if isinstance(pipeline, dict) else {}
        if not isinstance(pipeline, dict) or not pipeline.get("enabled"):
            return root, age
        if int(cycle_counts.get("SELECTED", 0) or 0) > 0:
            return root, age
        window = max(60.0, min(1800.0, float(_v456_window_sec())))
        events = _V456_EVENTS.items(window, "prequal_reject") if "_V456_EVENTS" in globals() else []
        grouped = {}
        for ts, _kind, payload in events:
            if not isinstance(payload, dict):
                continue
            reason = str(payload.get("reason", "") or "")
            bucket = _v702_a33_reason_root(reason)
            slot = grouped.setdefault(bucket, {"count": 0, "latest": 0.0, "reason": ""})
            slot["count"] += 1
            if float(ts) >= float(slot["latest"]):
                slot["latest"] = float(ts)
                slot["reason"] = reason
        if not grouped:
            return root, age
        chosen, detail = max(grouped.items(), key=lambda kv: (int(kv[1]["count"]), float(kv[1]["latest"])))
        age_s = max(0, int(float(WALL_NOW()) - float(detail["latest"]))) if detail["latest"] else -1
        STATS["v702_a33_entry_block_root_last"] = {
            "root": chosen, "count": int(detail["count"]), "reason": str(detail["reason"])[:180],
            "age_sec": age_s, "ts": float(WALL_NOW()), "source": "CURRENT_CYCLE_ZERO_SELECTED_RECENT_PREQUAL",
            "telemetry_only": True,
        }
        return chosen, age_s
    except Exception:
        return root, age

_v702_a7_entry_block_summary = _v702_a33_entry_block_summary

# Add small, explicit history-policy counters to the existing heartbeat without
# replacing or suppressing any existing digest sections.
_V702_A33_PREV_HEARTBEAT_LINE = _V702R28TelegramDigest._heartbeat_line.__func__
@classmethod
def _v702_a33_heartbeat_line(cls, text):
    base = _V702_A33_PREV_HEARTBEAT_LINE(cls, text)
    try:
        snap1 = STATS.get("v702_a33_htf_proxy_last", {}) or {}
        proxy_last = int(bool(snap1))
        used = int(STATS.get("v702_a33_htf_proxy_used", 0) or 0)
        blocked = int(STATS.get("v702_a33_htf_proxy_unavailable", 0) or 0)
        short1 = int(STATS.get("v702_a33_last_short_1h_rows", 0) or 0)
        min1 = int(CONFIG.get("V702_A33_LOCAL_1H_MIN_CLOSED_CANDLES", 210) or 210)
        target1 = max(240, int(CONFIG.get("HTF_MIN_CANDLES_1H", 240) or 240))
        base += (f" A33_HISTORY_POLICY=1h_min:{min1},target:{target1},4h_min:{_v702_a32_local_4h_min_closed_candles()}"
                 f",proxy_last:{proxy_last},proxy_used:{used},proxy_unavailable:{blocked},short1h:{short1}")
    except Exception:
        pass
    try:
        _sp_count = int(STATS.get("v702_a34_spread_shadow_rejects", 0) or 0)
        _sp_last = STATS.get("v702_a34_spread_shadow_last", {}) or {}
        if isinstance(_sp_last, dict) and float(_sp_last.get("ts", 0.0) or 0.0) > 0:
            _sp_age = float(WALL_NOW()) - float(_sp_last.get("ts", 0.0) or 0.0)
            if 0 <= _sp_age <= 900:
                _sp_ratio = _sp_last.get("spread_to_atr_ratio")
                _sp_ratio_text = f"{float(_sp_ratio):.2f}" if _sp_ratio is not None else "NA"
                base += (f" A34_SPREAD_SHADOW=rejects:{_sp_count},last:{_sp_last.get('tier','?')}"
                         f" {float(_sp_last.get('spread_pct',0.0) or 0.0):.4f}%/ceil:{float(_sp_last.get('fixed_ceiling_pct',0.0) or 0.0):.4f}%"
                         f",spread_atr:{_sp_ratio_text},atr_src:{str(_sp_last.get('atr_pct_source','UNAVAILABLE'))[:36]},mode:SHADOW_ONLY")
    except Exception:
        pass
    # A37 extends this already-canonical heartbeat function instead of replacing
    # the A7/A17/A33 observer identity relied on by terminal validation.
    try:
        _a37_root = _v702_a37_window_entry_root(900.0)
        _a37_age = "?" if _a37_root.get("age_sec") is None else f"{float(_a37_root['age_sec']):.0f}s"
        base += (f" ENTRY_BLOCK_WINDOW={_a37_root.get('root','UNKNOWN')}:{int(_a37_root.get('count',0))}/{int(_a37_root.get('total',0))}"
                 f" confidence={float(_a37_root.get('confidence_pct',0.0)):.0f}% root_age={_a37_age} window=900s")
        _a37_snap = V702PipelineMetrics.snapshot() if callable(getattr(V702PipelineMetrics, "snapshot", None)) else {}
        _a37_cycle_counts = _a37_snap.get("cycle_counts", {}) if isinstance(_a37_snap, dict) else {}
        _a37_cycle = ",".join(f"{k}={int(_a37_cycle_counts.get(src,0) or 0)}" for k,src in (("DISC","DISCOVERY"),("RANK","RANKED"),("PRE","PREQUAL_SEEN"),("PASS","PREQUAL_PASS"),("SEL","SELECTED"),("Q","QUEUED"),("TG","TELEGRAM_ENQUEUED"),("EXEC","EXECUTION_ATTEMPT")))
        _a37_win_line = V702PipelineMetrics.window_line(900.0) if callable(getattr(V702PipelineMetrics, "window_line", None)) else ""
        _a37_window_counts = {k:int(v) for k,v in re.findall(r"\b(DISC|RANK|PRE|PASS|SEL|Q|TG|EXEC)=([0-9]+)", str(_a37_win_line))}
        _a37_window = ",".join(f"{k}={_a37_window_counts.get(k,0)}" for k in ("DISC","RANK","PRE","PASS","SEL","Q","TG","EXEC"))
        base += f" funnel_cycle[{_a37_cycle}] funnel_window_15m[{_a37_window}]"
    except Exception:
        pass
    # A38 diagnostics are read-only and bounded. They explain repeated HTF
    # crash-guard decisions and exact-candidate Builder None outcomes without
    # changing the entry decision or inventing attribution.
    try:
        _a38_htf_count = int(STATS.get("v702_a38_htf_crash_guard_count", 0) or 0)
        _a38_htf = STATS.get("v702_a38_htf_crash_guard_last", {}) or {}
        if isinstance(_a38_htf, dict) and _a38_htf:
            _a38_htf_age = max(0.0, float(WALL_NOW()) - float(_a38_htf.get("ts", 0.0) or 0.0))
            _a38_strength = _a38_htf.get("htf_strength")
            _a38_strength_text = f"{float(_a38_strength):.1f}" if _a38_strength is not None else "NA"
            _a38_missing = ",".join(str(x)[:20] for x in (_a38_htf.get("missing_fields") or [])[:4]) or "none"
            base += (f" A38_HTF_GUARD=count:{_a38_htf_count},last:{str(_a38_htf.get('symbol','?'))[:24]}"
                     f",reason:{str(_a38_htf.get('reason','?'))[:40]},sev:{str(_a38_htf.get('severity','?'))[:18]}"
                     f",reg:{str(_a38_htf.get('regime','?'))[:14]},local:{str(_a38_htf.get('local_regime','?'))[:14]}"
                     f",state:{str(_a38_htf.get('htf_state','?'))[:16]},strength:{_a38_strength_text}"
                     f",src:{str(_a38_htf.get('htf_source','?'))[:24]},age:{_a38_htf.get('htf_age_sec') if _a38_htf.get('htf_age_sec') is not None else 'NA'}"
                     f",rows1h/4h:{int(_a38_htf.get('rows_1h',0) or 0)}/{int(_a38_htf.get('rows_4h',0) or 0)}"
                     f",missing:{_a38_missing},event_age:{_a38_htf_age:.0f}s")
    except Exception:
        pass
    try:
        _a38_bnone = STATS.get("v702_builder_return_none_last", {}) or {}
        if isinstance(_a38_bnone, dict) and _a38_bnone:
            _a38_bn_age = max(0.0, float(WALL_NOW()) - float(_a38_bnone.get("ts", 0.0) or 0.0))
            base += (f" A38_BUILDER_NONE=last:{str(_a38_bnone.get('symbol','?'))[:24]}"
                     f",reason:{str(_a38_bnone.get('reason','?'))[:70]}"
                     f",attr:{str(_a38_bnone.get('reason_attribution','?'))[:36]}"
                     f",key:{str(_a38_bnone.get('candidate_key','') or '')[:24] or 'NA'}"
                     f",cycle:{_a38_bnone.get('cycle_id','NA')},age:{_a38_bn_age:.0f}s")
    except Exception:
        pass
    return base
# Preserve the public identity expected by the existing A7/A17 validator chain;
# the function body now delegates and appends A33 fields without removing A7 data.
_v702_a33_heartbeat_line.__func__.__name__ = "_v702_a7_heartbeat_line"
_v702_a33_heartbeat_line.__name__ = "_v702_a7_heartbeat_line"
_V702R28TelegramDigest._heartbeat_line = _v702_a33_heartbeat_line


def _v702_a33_terminal_self_test() -> Dict[str, Any]:
    report = {"pass": False, "checks": {}, "failed": [], "revision": V702_A33_CANONICAL_REVISION,
              "hard_gate_bypass": False, "live_gates_relaxed": False,
              "live_network_tested": False, "profitability_verified": False}
    try:
        checks = {}
        checks["revision_appends_a32"] = V702_PACKAGE_AUDIT_REVISION.startswith(V702_A32_CANONICAL_REVISION + "-A33-")
        checks["fetch_target_remains_240"] = int(CONFIG.get("V702_A33_LOCAL_1H_FULL_HISTORY_TARGET", 0) or 0) >= 240
        checks["minimum_1h_is_210"] = _v702_a33_local_1h_min_closed_candles({"df_4h": None}) >= 210 and int(CONFIG.get("V702_A33_LOCAL_1H_MIN_CLOSED_CANDLES", 0) or 0) == 210
        checks["minimum_4h_unchanged"] = _v702_a32_local_4h_min_closed_candles() == 50
        checks["spot_long_only_preserved"] = bool(CONFIG.get("LONG_ONLY", False)) and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT" and not CONFIG.get("ENABLE_FUTURES", False) and not CONFIG.get("ALLOW_SHORT", False)
        checks["hard_live_floors_preserved"] = float(CONFIG.get("MIN_LIVE_SCORE", 0) or 0) >= 70 and float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 0) or 0) >= 3_000_000 and float(CONFIG.get("V45_TIER_MICRO_MIN_DEPTH_RATIO", 0) or 0) >= 1.90 and float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 0) or 0) >= 2.5
        checks["hard_gate_bypass_disabled"] = FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass", True) is False
        def frame(rows, rising=True):
            values = [1.0 + i * 0.005 if rising else 1.0 for i in range(rows)]
            return pd.DataFrame({"open": values, "high": [x * 1.01 for x in values], "low": [x * .99 for x in values], "close": values, "volume": [1000.0] * rows})
        frames = {"df_4h": frame(52), "df_1h": frame(214), "df_15m": frame(350), "df_5m": frame(30)}
        ok, why = _mse_candidate_scan_precheck(frames)
        checks["scan_admits_52_4h_plus_214_1h"] = bool(ok and why == "ok")
        short = dict(frames)
        short["df_1h"] = frame(209)
        ok_short, why_short = _mse_candidate_scan_precheck(short)
        checks["scan_rejects_209_1h_without_padding"] = (not ok_short and str(why_short).startswith("df_1h:short_rows:got=209,required=210") and len(short["df_1h"]) == 209)
        # Deterministic, closed-only fixture: never derive test data from the
        # wall clock and never append the current in-progress candle.
        fixed_current_open = pd.Timestamp("2026-10-15T15:00:00Z")
        fixed_now_ms = int((fixed_current_open + pd.Timedelta(minutes=5)).timestamp() * 1000)
        idx = pd.date_range(end=fixed_current_open - pd.Timedelta(hours=1), periods=211, freq="h", tz="UTC")
        timed = frame(len(idx))
        timed.index = idx
        valid_time, valid_reason = _v702_a33_local_1h_history_integrity(timed, 210, now_ms=fixed_now_ms)
        gapped_idx = idx.delete(10)
        gapped = timed.drop(timed.index[10]).copy()
        gapped.index = gapped_idx
        gap_ok, gap_reason = _v702_a33_local_1h_history_integrity(gapped, 210, now_ms=fixed_now_ms)
        checks["timestamp_fixture_ends_at_last_closed_bar"] = bool(len(idx) == 211 and idx[-1] == fixed_current_open - pd.Timedelta(hours=1) and idx[-1] < fixed_current_open)
        checks["timestamped_1h_closed_bars_validated"] = valid_time and valid_reason == "ok"
        checks["timestamp_gap_rejected"] = (not gap_ok and "candle_gap_detected" in str(gap_reason))
        proxy_snap = {"symbol": "A33-SHORT/USDT", "htf_strength": 0.0, "htf_state": "UNKNOWN", "htf_reason": "insufficient_data", "df_1h": frame(214), "df_4h": frame(52)}
        pscore, psource, _ = _v702_a33_resolve_htf_strength("A33-SHORT/USDT", proxy_snap)
        checks["adaptive_htf_proxy_uses_short_valid_history"] = psource == "RECOMPUTED_H0" and pscore is not None and 0.0 <= float(pscore) <= 50.0 and proxy_snap.get("htf_evidence_class") == "HTF_LIMITED_HISTORY"
        checks["proxy_confidence_cap_respects_short_1h"] = float(proxy_snap.get("htf_history_confidence_cap", 999.0)) <= 50.0
        report["checks"] = checks
        report["failed"] = [key for key, value in checks.items() if not value]
        report["pass"] = bool(all(checks.values()))
        report["local_1h_minimum"] = int(CONFIG.get("V702_A33_LOCAL_1H_MIN_CLOSED_CANDLES", 210) or 210)
        report["local_1h_fetch_target"] = max(240, int(CONFIG.get("HTF_MIN_CANDLES_1H", 240) or 240))
        report["local_4h_minimum"] = _v702_a32_local_4h_min_closed_candles()
        report["scope"] = "ADAPTIVE_LOCAL_1H_HISTORY_AND_CURRENT_CYCLE_PREQUAL_ROOT_TELEMETRY"
        STATS["v702_a33_terminal_self_test"] = report
        FINAL_CANONICAL_RUNTIME["v702_a33_terminal_self_test"] = report
        return report
    except Exception as exc:
        report["failed"] = [f"{type(exc).__name__}:{str(exc)[:160]}"]
        report["checks"] = {"exception_free": False}
        STATS["v702_a33_terminal_self_test"] = report
        FINAL_CANONICAL_RUNTIME["v702_a33_terminal_self_test"] = report
        return report

# =============================================================================
# V702 A34 — CURRENT-LOG CLOSURE (MICRO ALLOWLIST, SHADOW ATTRIBUTION, CACHE TTL, SHADOW SPREAD)
# =============================================================================
# A34 is an additive observability/cache-efficiency patch. It does not change entry
# scores, trend/macro filters, liquidity/spread hard ceilings, sizing, order routing,
# or exchange protection authority.
# A34 release identity and global runtime metadata are established above with A33's
# append-only source revision. The terminal contract is installed here before validation.
def _v702_a34_terminal_self_test() -> Dict[str, Any]:
    """Offline release contract for A34 log-driven fixes; always restore mutated telemetry."""
    report = {
        "pass": False, "checks": {}, "failed": [], "revision": V702_A34_CANONICAL_REVISION,
        "hard_gate_bypass": False, "live_gates_relaxed": False,
        "live_network_tested": False, "profitability_verified": False,
    }
    saved_stats = {}
    try:
        checks = {}
        checks["a34_revision_appends_a33"] = V702_PACKAGE_AUDIT_REVISION.startswith(
            V702_A33_CANONICAL_REVISION + "-A34-"
        )
        checks["a34_history_recheck_ttl_is_420s_bounded"] = (
            int(float(CONFIG.get("V702_A31_SHORT_HISTORY_RECHECK_SEC", 0) or 0)) == 420
            and 60 <= int(float(CONFIG.get("V702_A31_SHORT_HISTORY_RECHECK_SEC", 0) or 0)) <= 900
        )
        checks["a34_hard_live_gates_unchanged"] = (
            bool(CONFIG.get("LONG_ONLY", False))
            and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT"
            and not bool(CONFIG.get("ENABLE_FUTURES", False))
            and not bool(CONFIG.get("ALLOW_SHORT", False))
            and float(CONFIG.get("MIN_LIVE_SCORE", 0) or 0) >= 70.0
            and float(CONFIG.get("LIQUIDITY_UNIVERSE_MIN_QUOTE_VOLUME", 0) or 0) >= 3_000_000.0
            and float(CONFIG.get("V45_TIER_MICRO_MIN_DEPTH_RATIO", 0) or 0) >= 1.90
            and float(CONFIG.get("MIN_TP1_TO_FEE_RATIO", 0) or 0) >= 2.5
            and FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass", True) is False
        )
        # Exercise the same counter writer the scanner uses when a real verified
        # reject-only cache skip occurs; cache occupancy alone must not inflate savings.
        _a30_keys = (
            "v702_a30_cached_short_history_prefetch_skips",
            "v702_a30_saved_lower_tf_ohlcv_requests",
            "v702_a30_last_cached_history_skip",
            "v702_a23_local_history_blocks",
            "v702_a23_local_history_block_counts",
            "v702_a23_last_local_history_block",
            "v45_market_data_rejects",
            "v702_a30_last_skip_recorded_ts",
        )
        for key in _a30_keys:
            value = STATS.get(key)
            if isinstance(value, dict):
                value = dict(value)
            elif isinstance(value, list):
                value = list(value)
            saved_stats[key] = (key in STATS, value)
        before_skips = int(STATS.get("v702_a30_cached_short_history_prefetch_skips", 0) or 0)
        before_saved = int(STATS.get("v702_a30_saved_lower_tf_ohlcv_requests", 0) or 0)
        fake_skip = {
            "skip": True, "got": 49, "required": 50,
            "saved_lower_tf_requests": 3, "execution_authority_added": False,
        }
        accounted = _v702_a30_record_prefetch_skip("__A34_SELFTEST__/USDT", fake_skip)
        checks["a34_a30_skip_writer_counts_one_skip_and_three_reads"] = (
            accounted
            and int(STATS.get("v702_a30_cached_short_history_prefetch_skips", 0) or 0) == before_skips + 1
            and int(STATS.get("v702_a30_saved_lower_tf_ohlcv_requests", 0) or 0) == before_saved + 3
            and (STATS.get("v702_a30_last_cached_history_skip") or {}).get("symbol") == "__A34_SELFTEST__/USDT"
        )
        # Non-allowlisted families are rejected before creating a per-candidate handoff event.
        _micro_keys = (
            "v702_a19_micro_handoff_last",
            "v702_a19_micro_handoff_skipped_non_allowlisted",
            "v702_a19_micro_handoff_reason_counts",
            "v702_a7_micro_handoff_last_block_reason",
        )
        for key in _micro_keys:
            if key not in saved_stats:
                value = STATS.get(key)
                if isinstance(value, dict):
                    value = dict(value)
                elif isinstance(value, list):
                    value = list(value)
                saved_stats[key] = (key in STATS, value)
        old_micro_last = STATS.get("v702_a19_micro_handoff_last")
        fake = type("_V702A34Candidate", (), {
            "symbol": "__A34_NONALLOWLISTED__/USDT", "family": "OPPORTUNITY_SCOUT",
            "strategy_mode": "OPPORTUNITY_SCOUT", "side": "long",
        })()
        micro_ok = _v702_a7_micro_handoff_allowed(fake, {"symbol": fake.symbol}, "MICRO")
        checks["a34_nonallowlisted_micro_lane_is_rejected_without_per_candidate_event"] = (
            not micro_ok
            and STATS.get("v702_a19_micro_handoff_last") == old_micro_last
            and int(STATS.get("v702_a19_micro_handoff_skipped_non_allowlisted", 0) or 0)
                >= int((saved_stats["v702_a19_micro_handoff_skipped_non_allowlisted"][1] or 0)) + 1
        )
        checks["a34_shadow_gap_requires_exact_recent_presend_queue_ref"] = (
            _v702_a34_candidate_reached_presend_or_queue("a" * 40, "__A34__/USDT", "PULLBACK", now=1000.0)
            == (False, "candidate_never_reached_presend_queue")
        )
        checks["a34_shadow_gap_accepts_matching_recent_queue_evidence"] = False
        _old_progress = STATS.get("v702_candidate_route_progress_history")
        _old_route_hist = STATS.get("v702_selected_route_history")
        try:
            STATS["v702_candidate_route_progress_history"] = [{
                "candidate_ref": "a" * 40, "symbol": "__A34__/USDT", "family": "PULLBACK",
                "stage": "queued", "ts": 1000.0,
            }]
            STATS["v702_selected_route_history"] = []
            checks["a34_shadow_gap_accepts_matching_recent_queue_evidence"] = (
                _v702_a34_candidate_reached_presend_or_queue("a" * 40, "__A34__/USDT", "PULLBACK", now=1001.0)
                == (True, "queued")
            )
        finally:
            if _old_progress is None: STATS.pop("v702_candidate_route_progress_history", None)
            else: STATS["v702_candidate_route_progress_history"] = _old_progress
            if _old_route_hist is None: STATS.pop("v702_selected_route_history", None)
            else: STATS["v702_selected_route_history"] = _old_route_hist
        # Spread adaptation is observational only: collect facts for Shadow, keep live cap untouched.
        _spread_keys = ("v702_a34_spread_shadow_rejects", "v702_a34_spread_shadow_by_tier",
                        "v702_a34_spread_shadow_history", "v702_a34_spread_shadow_last")
        for key in _spread_keys:
            if key not in saved_stats:
                value = STATS.get(key)
                if isinstance(value, dict): value = dict(value)
                elif isinstance(value, list): value = list(value)
                saved_stats[key] = (key in STATS, value)
        _mid_cap_before = float((CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}).get("MID", 0.22))
        _before_shadow = int(STATS.get("v702_a34_spread_shadow_rejects", 0) or 0)
        _v702_a34_record_spread_shadow_observation("MID", _mid_cap_before + 0.01, _mid_cap_before,
                                                     {"features": {"atr_pct": 0.4, "depth_ratio": 2.0, "quote_volume_24h": 2_000_000}})
        _sp_after = STATS.get("v702_a34_spread_shadow_last", {}) or {}
        checks["a34_spread_adaptation_is_shadow_only"] = (
            int(STATS.get("v702_a34_spread_shadow_rejects", 0) or 0) == _before_shadow + 1
            and isinstance(_sp_after, dict)
            and _sp_after.get("mode") == "SHADOW_ONLY_NO_LIVE_RELIEF"
            and _sp_after.get("actual_live_decision") == "REJECTED_FIXED_CEILING"
            and abs(float((CONFIG.get("TIER_SPREAD_CEIL_PCT", {}) or {}).get("MID", 0.22)) - _mid_cap_before) < 1e-12
        )
        report["checks"] = checks
        report["failed"] = [name for name, value in checks.items() if not value]
        report["pass"] = not report["failed"]
        report["scope"] = "A34_MICRO_ALLOWLIST_CACHE_TELEMETRY_SHADOW_ROUTE_PROGRESS_AND_SPREAD; NO_LIVE_GATE_CHANGES"
        STATS["v702_a34_terminal_self_test"] = report
        FINAL_CANONICAL_RUNTIME["v702_a34_terminal_self_test"] = report
        return report
    except Exception as exc:
        report["checks"] = {"exception_free": False}
        report["failed"] = [f"{type(exc).__name__}:{str(exc)[:160]}"]
        report["pass"] = False
        STATS["v702_a34_terminal_self_test"] = report
        FINAL_CANONICAL_RUNTIME["v702_a34_terminal_self_test"] = report
        return report
    finally:
        for key, (existed, value) in saved_stats.items():
            if existed: STATS[key] = value
            else: STATS.pop(key, None)


