def _v702_a37_parse_block_record(raw, category="builder_block"):
    """Turn compacted free-text blockers into a stable structured record."""
    try:
        plain = _V702R28TelegramDigest._strip(str(raw or ""))
    except Exception:
        plain = str(raw or "").replace("\r", "").strip()
    # Keep a block's own leading heading (e.g. "SELECTED → BUILDER BLOCK
    # GOLD(PAXG)/USDT"). Only truncate a later heading accidentally joined to
    # the reason tail; the previous global split could erase the actual symbol.
    reason_start = re.search(r"\breason\s*=", plain, flags=re.I)
    if reason_start:
        tail = plain[reason_start.end():]
        boundary = re.search(r"\s*(?:SELECTED\s*→\s*(?:SCORER|ROUTE|BUILDER)\s+BLOCK|TOP DISCOVERY|KNOWLEDGE SHADOW|PIPELINE\[|buffered_latest:|Execution orders/protection)", tail, flags=re.I)
        if boundary:
            plain = (plain[:reason_start.end()] + tail[:boundary.start()]).strip()
    sym_match = re.search(r"(?<![A-Za-z0-9_.-])([A-Z0-9][A-Z0-9_.()\-]*/USDT)(?![A-Za-z0-9])", plain, flags=re.I)
    root_match = re.search(r"\broot=([^\s]+)", plain, flags=re.I)
    stage_match = re.search(r"\bstage=([^\s]+)", plain, flags=re.I)
    reason_match = re.search(r"\breason=(.*?)(?=\s*(?:SELECTED\s*→|TOP DISCOVERY|KNOWLEDGE SHADOW|PIPELINE\[|buffered_latest:|Execution orders/protection)|$)", plain, flags=re.I | re.S)
    reason = (reason_match.group(1) if reason_match else "?").strip()
    # A reason field is a single diagnosis, not a continuation into the next section.
    reason = re.sub(r"\s+", " ", reason)[:240]
    return {
        "symbol": sym_match.group(1).upper() if sym_match else "UNATTRIBUTED",
        "root": root_match.group(1).upper() if root_match else "?",
        "stage": stage_match.group(1) if stage_match else "?",
        "reason": reason or "?",
        "category": str(category or "block")[:32],
        "recorded_ts": float(WALL_NOW()),
        "raw": plain[:700],
    }


def _v702_a37_format_block_lines(cls, rows):
    out = []
    for row in list(rows or [])[:V702_R28_TELEGRAM_DIGEST_TOP_BLOCKS]:
        rec = row if isinstance(row, dict) else _v702_a37_parse_block_record(row)
        symbol = str(rec.get("symbol") or "UNATTRIBUTED")
        root = str(rec.get("root") or "?")
        stage = str(rec.get("stage") or "?")
        reason = re.sub(r"\s+", " ", str(rec.get("reason") or "?"))[:120]
        # The formatter uses the same escaping helper as the A39 discovery rows.
        esc = globals().get("_v702_r39_escape_digest_text")
        if callable(esc):
            symbol, root, stage, reason = (esc(x) for x in (symbol, root, stage, reason))
        out.append(f"• {symbol} root={root} stage={stage} reason={reason}")
    return out or ["• none"]


# Keep candidate/route/scorer diagnostic categories, but store their parsed fields
# at capture time so later formatting does not have to infer the symbol from a header.
_V702_A37_PREV_CAPTURE = _V702R28TelegramDigest.capture

def _v702_a37_capture(cls, category, raw, *args, **kwargs):
    result = _V702_A37_PREV_CAPTURE(category, raw, *args, **kwargs)
    try:
        cat = str(category or "")
        if cat in {"scorer_block", "route_block", "builder_block"}:
            # Parse and retain structured fields at event capture time, while keeping
            # historical string queues intact for backwards-compatible observers.
            record = _v702_a37_parse_block_record(raw, cat)
            with cls._lock:
                _V702_A37_STRUCTURED_BLOCKS[cat].appendleft(record)
            _v702_a37_stats_set("v702_a37_last_block_record_" + cat, record)
        elif cat == "heartbeat":
            # A fresh heartbeat file makes Docker health a liveness/freshness
            # check rather than merely a check that the Python PID exists.
            try:
                heartbeat_text = cls._strip(str(raw or ""))[:1000]
                path = Path(str(os.environ.get("V702_HEARTBEAT_FILE", "/tmp/unified_scalper_heartbeat.json")))
                path.parent.mkdir(parents=True, exist_ok=True)
                temp = path.with_name(path.name + ".tmp")
                telemetry = {}
                try:
                    _metrics = globals().get("V702PipelineMetrics")
                    if _metrics is not None and callable(getattr(_metrics, "drop_health_snapshot", None)):
                        telemetry = _metrics.drop_health_snapshot(interval_sec=3600.0)
                except Exception as _telemetry_exc:
                    telemetry = {"status": "UNKNOWN", "error": type(_telemetry_exc).__name__}
                payload = {"timestamp": float(time.time()), "state": (re.search(r"\bstate=([^\s]+)", heartbeat_text, re.I).group(1) if re.search(r"\bstate=([^\s]+)", heartbeat_text, re.I) else "UNKNOWN"), "source": "telegram_heartbeat_capture", "telemetry": telemetry}
                temp.write_text(json.dumps(payload, separators=(",", ":")), encoding="utf-8")
                os.replace(str(temp), str(path))
                _v702_a37_stats_inc("v702_a37_heartbeat_file_write_ok")
            except Exception as exc:
                _v702_a37_stats_inc("v702_a37_heartbeat_file_write_fail")
                STATS["v702_a37_heartbeat_file_last_error"] = type(exc).__name__
    except Exception:
        _v702_a37_stats_inc("v702_a37_telemetry_capture_errors")
    return result

_V702R28TelegramDigest.capture = classmethod(_v702_a37_capture)
_V702R28TelegramDigest._format_block_lines = classmethod(_v702_a37_format_block_lines)

def _v702_a37_rows_for(cls, category, legacy_attr):
    with cls._lock:
        structured = list(_V702_A37_STRUCTURED_BLOCKS.get(category, ()))
        legacy = list(getattr(cls, legacy_attr, ()))
    limit = int(V702_R28_TELEGRAM_DIGEST_TOP_BLOCKS)
    merged = list(structured)
    seen_raw = {str(x.get("raw", "")) for x in structured if isinstance(x, dict)}
    if len(merged) < limit:
        for row in legacy:
            record = row if isinstance(row, dict) else _v702_a37_parse_block_record(row, category)
            raw_key = str(record.get("raw", ""))
            if raw_key and raw_key in seen_raw:
                continue
            merged.append(record)
            if raw_key:
                seen_raw.add(raw_key)
            if len(merged) >= limit:
                break
    return merged[:limit]

@classmethod
def _v702_a37_block_lines(cls):
    return cls._format_block_lines(_v702_a37_rows_for(cls, "builder_block", "_selected_blocks"))

@classmethod
def _v702_a37_scorer_block_lines(cls):
    return cls._format_block_lines(_v702_a37_rows_for(cls, "scorer_block", "_scorer_blocks"))

@classmethod
def _v702_a37_route_block_lines(cls):
    return cls._format_block_lines(_v702_a37_rows_for(cls, "route_block", "_route_blocks"))

_V702R28TelegramDigest._block_lines = _v702_a37_block_lines
_V702R28TelegramDigest._scorer_block_lines = _v702_a37_scorer_block_lines
_V702R28TelegramDigest._route_block_lines = _v702_a37_route_block_lines


def _v702_a37_window_entry_root(window_sec=900.0):
    """Summarize prequal blockers over the digest window; no admission effects."""
    try:
        window = max(60.0, min(3600.0, float(window_sec)))
        items = _V456_EVENTS.items(window, "prequal_reject") if "_V456_EVENTS" in globals() else []
        grouped = {}
        now = float(WALL_NOW())
        for ts, _kind, payload in items:
            if not isinstance(payload, dict):
                continue
            reason = str(payload.get("reason", "") or "")
            root = _v702_a33_reason_root(reason) if callable(globals().get("_v702_a33_reason_root")) else "OTHER"
            rec = grouped.setdefault(root, {"count": 0, "latest": 0.0})
            rec["count"] += 1
            rec["latest"] = max(float(rec["latest"]), float(ts))
        total = sum(int(x["count"]) for x in grouped.values())
        if not total:
            return {"root": "NONE", "count": 0, "total": 0, "confidence_pct": 0.0, "age_sec": None, "window_sec": window}
        root, rec = max(grouped.items(), key=lambda kv: (int(kv[1]["count"]), float(kv[1]["latest"])))
        count = int(rec["count"])
        return {"root": root, "count": count, "total": total,
                "confidence_pct": 100.0 * count / max(total, 1),
                "age_sec": max(0.0, now-float(rec["latest"])) if rec["latest"] else None,
                "window_sec": window}
    except Exception as exc:
        return {"root": "UNKNOWN", "count": 0, "total": 0, "confidence_pct": 0.0,
                "age_sec": None, "window_sec": window_sec, "error": type(exc).__name__}


# The A37 window fields are appended inside the established A33 heartbeat body
# to preserve the canonical observer identity verified by R38/A7.


def _v702_a37_repair_telegram_html(text, max_chars=None):
    """Bound output and close any markup cut by older digest truncation paths."""
    raw = str(text or "")
    limit = int(max_chars or CONFIG.get("V702_R28_TELEGRAM_DIGEST_MAX_CHARS", 3700) or 3700)
    limit = max(1000, limit)
    if len(raw) > limit:
        # Reserve space for close tags and a marker; prefer a complete line.
        budget = max(128, limit - 160)
        part = raw[:budget]
        if "\n" in part:
            part = part.rsplit("\n", 1)[0]
        # Never end in the middle of an HTML tag or entity.
        if part.rfind("<") > part.rfind(">"):
            part = part[:part.rfind("<")]
        if part.rfind("&") > part.rfind(";") and re.match(r"&(?:#x?[0-9A-Fa-f]*|[A-Za-z][A-Za-z0-9]*)?$", part[part.rfind("&"):]):
            part = part[:part.rfind("&")]
        raw = part.rstrip() + "\n…"
    # Append closures for tags left open at the tail. Generated digest markup is
    # nested; the small allowlist excludes arbitrary/raw HTML from user fields.
    allowed = {"b", "strong", "i", "em", "u", "ins", "s", "strike", "del", "code", "pre", "a", "blockquote", "tg-spoiler"}
    stack = []
    for m in re.finditer(r"<(/?)([A-Za-z][A-Za-z0-9-]*)(?:\s+[^<>]*?)?/?>", raw):
        closing, name = bool(m.group(1)), m.group(2).lower()
        if name not in allowed:
            continue
        tag = m.group(0)
        if tag.endswith("/>"):
            continue
        if not closing:
            stack.append(name)
        elif name in stack:
            # The digest generators are well-nested; discard the matched tag and
            # any impossible trailing nested tags only for malformed old truncation.
            index = len(stack) - 1 - stack[::-1].index(name)
            stack = stack[:index]
    if stack:
        raw += "".join(f"</{name}>" for name in reversed(stack))
    if len(raw) > limit:
        raw = raw[:limit]
        if raw.rfind("<") > raw.rfind(">"):
            raw = raw[:raw.rfind("<")]
        # A second closure pass after the strict last-resort cut.
        stack = []
        for m in re.finditer(r"<(/?)([A-Za-z][A-Za-z0-9-]*)(?:\s+[^<>]*?)?/?>", raw):
            closing, name = bool(m.group(1)), m.group(2).lower()
            if name not in allowed:
                continue
            if m.group(0).endswith("/"):
                continue
            if not closing: stack.append(name)
            elif name in stack: stack = stack[:len(stack)-1-stack[::-1].index(name)]
        closers = "".join(f"</{name}>" for name in reversed(stack))
        if len(raw) + len(closers) > limit:
            raw = raw[:limit-len(closers)]
            if raw.rfind("<") > raw.rfind(">"):
                raw = raw[:raw.rfind("<")]
        raw += closers
    return raw


# The canonical _v702_digest_build_observed function keeps its enforced identity;
