_v702_a37_stats_set("v702_a37_safe_digest_build_installed", callable(globals().get("_v702_digest_build_observed")))


# A30 repeated short-history diagnostics are classified and deduplicated per symbol
# and 4H boundary. Existing saved-request totals remain event counts so throughput
# is still reported honestly; no short history gains admission authority.
_V702_A37_PREV_A30_RECORD = _v702_a30_record_prefetch_skip

def _v702_a37_record_prefetch_skip(symbol, decision):
    result = _V702_A37_PREV_A30_RECORD(symbol, decision)
    if not result:
        return result
    try:
        now_ms = int(time.time() * 1000)
        interval = 4 * 60 * 60 * 1000
        boundary = now_ms - (now_ms % interval)
        sym = str(symbol or (decision or {}).get("symbol") or "?").upper()
        got = int((decision or {}).get("got", 0) or 0)
        required = int((decision or {}).get("required", 50) or 50)
        key = f"{sym}|{boundary}"
        seen = STATS.setdefault("v702_a37_short_history_seen", {})
        if not isinstance(seen, dict):
            seen = {}; STATS["v702_a37_short_history_seen"] = seen
        prev = seen.get(key)
        unique = not isinstance(prev, dict)
        if unique:
            seen[key] = {"ts": float(WALL_NOW()), "got": got, "required": required}
            # Bound the telemetry-only dedup map by recent entries.
            if len(seen) > 1000:
                for stale_key in list(seen)[:len(seen)-800]:
                    seen.pop(stale_key, None)
            _v702_a37_stats_inc("v702_a37_short_history_unique_symbol_boundary")
        else:
            _v702_a37_stats_inc("v702_a37_short_history_repeat_skip")
        STATS["v702_a37_short_history_last"] = {
            "symbol": sym, "got": got, "required": required,
            "classification": "SHORT_HISTORY_UNVERIFIED_NOT_PROVEN_NEW_LISTING",
            "unique_symbol_boundary": unique, "boundary_ms": boundary,
            "ts": float(WALL_NOW()), "admission_authority_added": False,
        }
    except Exception:
        pass
    return result

_v702_a30_record_prefetch_skip = _v702_a37_record_prefetch_skip


