def _v702_a38_record_htf_crash_guard(symbol=None, snapshot=None, candidate=None, reason="bearish_crash_guard", stage="prequal", details=None):
    """Bounded, telemetry-only evidence for an HTF crash-guard rejection."""
    try:
        snap = snapshot if isinstance(snapshot, dict) else {}
        cand = getattr(candidate, "candidate", candidate)
        fs = getattr(cand, "features_snapshot", {}) or {}
        if not isinstance(fs, dict): fs = {}
        sym = str(symbol or snap.get("symbol") or getattr(cand, "symbol", "") or "UNKNOWN").upper()[:64]
        extra = details if isinstance(details, dict) else {}
        def _pick(*values):
            for value in values:
                if value is not None and str(value).strip() != "":
                    return value
            return None
        def _finite(value):
            try:
                num = float(value)
                return num if math.isfinite(num) else None
            except Exception:
                return None
        def _rows(key):
            frame = snap.get(key)
            try: return int(len(frame)) if frame is not None else 0
            except Exception: return 0
        missing=[]
        sev = str(_pick(extra.get("severity"), snap.get("bearish_severity"), snap.get("macro_severity"), fs.get("bearish_severity"), fs.get("macro_severity")) or "UNKNOWN").upper()[:40]
        reg = str(_pick(extra.get("regime"), snap.get("macro_regime"), snap.get("regime"), fs.get("macro_regime")) or "UNKNOWN").upper()[:40]
        local = str(_pick(extra.get("local_regime"), snap.get("local_regime"), fs.get("local_regime")) or "UNKNOWN").upper()[:40]
        state = str(_pick(extra.get("htf_state"), snap.get("htf_state"), fs.get("htf_state")) or "UNKNOWN").upper()[:40]
        strength = _finite(_pick(extra.get("htf_strength"), snap.get("htf_strength"), fs.get("htf_strength")))
        source = str(_pick(extra.get("htf_source"), snap.get("v4513_htf_source"), snap.get("htf_source"), fs.get("htf_source")) or "UNKNOWN")[:48]
        age = _finite(_pick(extra.get("htf_age_sec"), snap.get("v4513_htf_age_sec"), snap.get("htf_age_sec"), fs.get("htf_age_sec")))
        rows1, rows4 = _rows("df_1h"), _rows("df_4h")
        if rows1 == 0: missing.append("df_1h")
        if rows4 == 0: missing.append("df_4h")
        if strength is None: missing.append("htf_strength")
        if state == "UNKNOWN": missing.append("htf_state")
        if source == "UNKNOWN": missing.append("htf_source")
        candidate_key = ""
        try: candidate_key = str(V702PipelineMetrics.current_candidate_key() or "")[:96]
        except Exception: pass
        row = {"symbol":sym,"reason":str(reason or "bearish_crash_guard")[:80],"stage":str(stage or "prequal")[:32],
               "severity":sev,"regime":reg,"local_regime":local,"htf_state":state,"htf_strength":strength,
               "htf_source":source,"htf_age_sec":age,"rows_1h":rows1,"rows_4h":rows4,
               "missing_fields":missing,"candidate_key":candidate_key,"ts":float(WALL_NOW()),
               "telemetry_only":True,"decision_changed":False}
        with _V702_A38_HTF_DIAGNOSTICS_LOCK:
            STATS["v702_a38_htf_crash_guard_count"] = int(STATS.get("v702_a38_htf_crash_guard_count",0) or 0)+1
            STATS["v702_a38_htf_crash_guard_last"] = row
            by_reason = STATS.setdefault("v702_a38_htf_crash_guard_by_reason", {})
            if not isinstance(by_reason, dict): by_reason = {}; STATS["v702_a38_htf_crash_guard_by_reason"] = by_reason
            reason_key = row["reason"][:80]
            by_reason[reason_key] = int(by_reason.get(reason_key,0) or 0)+1
            history = STATS.setdefault("v702_a38_htf_crash_guard_history", [])
            if not isinstance(history, list): history=[]; STATS["v702_a38_htf_crash_guard_history"] = history
            history.append(row)
            if len(history)>64: del history[:-64]
        return row
    except Exception as exc:
        try: _v702_a37_stats_inc("v702_a38_htf_diagnostic_errors")
        except Exception: pass
        return {"recorded":False,"error":type(exc).__name__}

def _v702_a38_same_bar_stop_result(existing_first_event=""):
    """Resolve OHLC-only same-bar TP+SL conservatively and preserve prior known TP."""
    prior = str(existing_first_event or "").upper()
    if prior in {"TP1", "TP2", "TP3"}:
        return {"status":"SL_FINAL","first_event":prior,"final_outcome":"SL_AFTER_"+prior,"prior_target_proven":True}
    return {"status":"SL_FINAL","first_event":"SL","final_outcome":"SL","prior_target_proven":False}

