    checks = {}
    try:
        checks["revision_appends_a37"] = V702_PACKAGE_AUDIT_REVISION.startswith(V702_A37_CANONICAL_REVISION + "-A38-")
        checks["digest_interval_is_30m"] = abs(float(CONFIG.get("V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC",0) or 0)-1800.0)<1e-9
        checks["runtime_heartbeat_interval_is_30m"] = abs(float(CONFIG.get("HEARTBEAT_INTERVAL_SEC",0) or 0)-1800.0)<1e-9
        checks["health_freshness_exceeds_interval"] = int(os.environ.get("V702_HEARTBEAT_STALE_SEC","2100") or 2100) > int(CONFIG.get("HEARTBEAT_INTERVAL_SEC",1800) or 1800)
        checks["critical_delivery_remains_immediate"] = bool(CONFIG.get("V702_R28_TELEGRAM_CONVERGENCE_ENABLE",False)) and not any(bool(CONFIG.get(k,False)) for k in ("V702_R28_TELEGRAM_HEARTBEAT_IMMEDIATE","V702_R28_TELEGRAM_DISCOVERY_IMMEDIATE","V702_R28_TELEGRAM_REJECTION_IMMEDIATE","V702_R28_TELEGRAM_STARVATION_IMMEDIATE","V702_R28_TELEGRAM_SHADOW_IMMEDIATE","V702_R28_TELEGRAM_EDGE_IMMEDIATE","V702_R28_TELEGRAM_BUILDER_BLOCK_IMMEDIATE"))
        checks["software_sl_watchdog_unchanged"] = float(CONFIG.get("V560_SOFTWARE_SL_MAX_MISSED_HEARTBEAT_SEC",12.0) or 12.0) <= 12.0
        checks["hard_score_and_execution_gates_preserved"] = float(CONFIG.get("MIN_LIVE_SCORE",70.0) or 70.0)>=70.0 and FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass") is False
        checks["same_bar_new_target_and_stop_is_sl_first"] = _v702_a38_same_bar_stop_result("")["final_outcome"] == "SL"
        checks["previous_target_then_same_bar_stop_preserved"] = _v702_a38_same_bar_stop_result("TP1")["final_outcome"] == "SL_AFTER_TP1"
        checks["htf_diagnostic_helper_present"] = callable(_v702_a38_record_htf_crash_guard)
        checks["spread_atr_closed_frame_fallback_present"] = "CLOSED_OHLCV_" in _v702_read_source_text().split("def _v702_a34_spread_context_fields",1)[-1].split("def _v702_a34_record_spread_shadow_observation",1)[0]
        checks["short_history_not_promoted_to_tradeable"] = bool(CONFIG.get("V702_A30_SHORT_HISTORY_PREFETCH_SKIP_ENABLE",True)) and '"admission_authority_added": False' in _v702_read_source_text()
    except Exception as exc:
        checks["self_test_exception_free"] = False
        STATS["v702_a38_validation_error"] = f"{type(exc).__name__}:{str(exc)[:160]}"
    failed = [key for key,value in checks.items() if not bool(value)]
    report = {"pass":bool(checks) and not failed,"revision":V702_A38_CANONICAL_REVISION,"checks":checks,"failed":failed,
              "hard_gate_bypass":False,"live_gates_relaxed":False,"live_network_tested":False,"profitability_verified":False}
    STATS["v702_a38_terminal_self_test"] = report
    FINAL_CANONICAL_RUNTIME["a38_final_self_test"] = report
    return report

