async def _v702_a39_attempt_balance_entry_recovery(exchange) -> bool:
    """Recover a transient balance latch independently of candidate flow.

    The helper intentionally does not repair or clear execution/protection blocks.
    It asks the exchange for fresh balance only when the current latch is one of
    the exact balance-only reasons that a fresh balance can prove resolved.
    """
    try:
        if not bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
            return False
        before = str((LIVE_ENTRIES_BLOCKED or {}).get("reason") or "").strip().lower()
        if before not in _AUTO_BALANCE_RECOVERABLE_BLOCK_REASONS:
            STATS["v702_a39_balance_recovery_skipped_nonbalance"] = int(
                STATS.get("v702_a39_balance_recovery_skipped_nonbalance", 0) or 0
            ) + 1
            return False
        free, state = await BalanceReconciler.fetch(exchange)
        snap = dict(STATS.get("v702_a39_balance_snapshot") or {})
        snap.update({"recovery_attempt": True, "block_before": before, "state": str(state), "free_usdt": float(free)})
        STATS["v702_a39_balance_recovery_last"] = snap
        if str(state).upper() == "REAL" and float(free) >= float(CONFIG.get("BALANCE_MIN_ACCEPT_USDT", 5.0)) and not bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
            STATS["v702_a39_balance_recovery_successes"] = int(STATS.get("v702_a39_balance_recovery_successes", 0) or 0) + 1
            logger.warning(
                "[V702-A39-BALANCE] entry latch recovered from fresh exchange free balance; "
                "free_usdt=%.6f prior_reason=%s pending_order_locks_are_already_excluded=true",
                float(free), before,
            )
            return True
        STATS["v702_a39_balance_recovery_blocks"] = int(STATS.get("v702_a39_balance_recovery_blocks", 0) or 0) + 1
        return False
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        STATS["v702_a39_balance_recovery_errors"] = int(STATS.get("v702_a39_balance_recovery_errors", 0) or 0) + 1
        STATS["v702_a39_balance_recovery_last_error"] = f"{type(exc).__name__}:{str(exc)[:180]}"
        logger.warning("[V702-A39-BALANCE] recovery attempt failed; entry gate remains fail-closed: %s", exc)
        return False

async def _v702_a39_balance_entry_recovery_task(exchange):
    """Bounded periodic recovery; does not poll the exchange during normal operation."""
    interval = max(10.0, min(120.0, float(CONFIG.get("V702_A39_BALANCE_ENTRY_RECOVERY_INTERVAL_SEC", 30.0) or 30.0)))
    logger.info("[V702-A39-BALANCE] independent entry-block recovery task online interval=%.1fs", interval)
    while _SHUTDOWN is None or not _SHUTDOWN.is_set():
        try:
            if bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
                reason = str((LIVE_ENTRIES_BLOCKED or {}).get("reason") or "").strip().lower()
                if reason in _AUTO_BALANCE_RECOVERABLE_BLOCK_REASONS:
                    await _v702_a39_attempt_balance_entry_recovery(exchange)
                else:
                    # A skipped non-balance latch is an intentional safety decision,
                    # but it must be visible instead of appearing as a dead worker.
                    STATS["v702_a39_balance_recovery_skipped_nonbalance"] = int(
                        STATS.get("v702_a39_balance_recovery_skipped_nonbalance", 0) or 0
                    ) + 1
                    STATS["v702_a39_balance_recovery_last_skip"] = {
                        "ts": float(WALL_NOW()), "reason": reason[:120],
                        "where": str((LIVE_ENTRIES_BLOCKED or {}).get("where") or "")[:120],
                        "policy": "NO_BALANCE_ONLY_AUTO_CLEAR_FOR_NONBALANCE_BLOCK",
                    }
            await asyncio.sleep(interval)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            STATS["v702_a39_balance_recovery_task_errors"] = int(STATS.get("v702_a39_balance_recovery_task_errors", 0) or 0) + 1
            logger.warning("[V702-A39-BALANCE] recovery task iteration failed; gates unchanged: %s", exc)
            await asyncio.sleep(interval)


