def _v702_a40_entry_block_telemetry() -> Dict[str, Any]:
    """Build a bounded, read-only diagnostic from in-process state only."""
    now = float(WALL_NOW())
    block = LIVE_ENTRIES_BLOCKED if isinstance(LIVE_ENTRIES_BLOCKED, dict) else {}
    active = bool(block.get("active"))
    reason = str(block.get("reason") or "none")
    where = str(block.get("where") or "none")
    since = block.get("since")
    try:
        block_age = max(0.0, now - float(since)) if active and since is not None else None
    except Exception:
        block_age = None

    balance = STATS.get("v702_a39_balance_snapshot", {}) or {}
    if not isinstance(balance, dict):
        balance = {}
    try:
        balance_age = max(0.0, now - float(balance.get("ts", 0.0) or 0.0)) if balance.get("ts") else None
    except Exception:
        balance_age = None

    intent = STATS.get("v702_a40_unresolved_intents_latest", {}) or {}
    if not isinstance(intent, dict):
        intent = {}
    order_diag = STATS.get("v702_a40_open_orders_last", {}) or {}
    if not isinstance(order_diag, dict):
        order_diag = {}
    try:
        intent_age = max(0.0, now - float(intent.get("ts", 0.0) or 0.0)) if intent.get("ts") else None
    except Exception:
        intent_age = None
    try:
        order_age = max(0.0, now - float(order_diag.get("ts", 0.0) or 0.0)) if order_diag.get("ts") else None
    except Exception:
        order_age = None

    recover_last = STATS.get("v702_a39_balance_recovery_last", {}) or {}
    if not isinstance(recover_last, dict):
        recover_last = {}
    skip_last = STATS.get("v702_a39_balance_recovery_last_skip", {}) or {}
    if not isinstance(skip_last, dict):
        skip_last = {}
    active_recovery_last = recover_last if recover_last.get("ts") else skip_last
    try:
        recovery_age = max(0.0, now - float(active_recovery_last.get("ts", 0.0) or 0.0)) if active_recovery_last.get("ts") else None
    except Exception:
        recovery_age = None

    return {
        "block_active": active,
        "block_reason": reason[:180],
        "block_where": where[:140],
        "block_age_sec": block_age,
        "balance_free_usdt": balance.get("free_usdt"),
        "balance_used_usdt": balance.get("used_usdt"),
        "balance_total_usdt": balance.get("total_usdt"),
        "balance_state": str(balance.get("state", "REAL_SNAPSHOT" if balance.get("source") == "fetch_balance" else "UNKNOWN")),
        "balance_source": str(balance.get("source", "unknown"))[:48],
        "balance_age_sec": balance_age,
        "recovery_successes": int(STATS.get("v702_a39_balance_recovery_successes", 0) or 0),
        "recovery_blocks": int(STATS.get("v702_a39_balance_recovery_blocks", 0) or 0),
        "recovery_errors": int(STATS.get("v702_a39_balance_recovery_errors", 0) or 0),
        "recovery_skipped_nonbalance": int(STATS.get("v702_a39_balance_recovery_skipped_nonbalance", 0) or 0),
        "recovery_task_errors": int(STATS.get("v702_a39_balance_recovery_task_errors", 0) or 0),
        "recovery_last_reason": str(active_recovery_last.get("block_before") or active_recovery_last.get("reason") or "none")[:120],
        "recovery_last_state": str(active_recovery_last.get("state") or active_recovery_last.get("status") or "none")[:32],
        "recovery_last_age_sec": recovery_age,
        "recovery_last_error": str(STATS.get("v702_a39_balance_recovery_last_error", "") or "")[:180],
        "unresolved_intents_state": str(intent.get("state", "UNKNOWN"))[:20],
        "unresolved_intents_count": intent.get("count", STATS.get("startup_unresolved_execution_intents")),
        "unresolved_intents_age_sec": intent_age,
        "unresolved_intents_symbols": list(intent.get("symbols") or [])[:8],
        "open_orders_state": str(order_diag.get("state", "NOT_CHECKED"))[:24],
        "open_orders_count": order_diag.get("count"),
        "open_orders_age_sec": order_age,
        "open_orders_symbols": list(order_diag.get("symbols") or [])[:8],
        "last_reconciliation_op": str(STATS.get("v652_last_reconciliation_op", "") or "")[:100],
        "diagnostic_is_read_only": True,
        "hard_gate_bypass": False,
    }


async def _v702_a40_entry_block_diagnostic_task(exchange):
    """Bounded read-only diagnostics while entries are blocked; never clears any latch."""
    interval = max(45.0, min(300.0, float(CONFIG.get("V702_A40_ENTRY_BLOCK_DIAG_INTERVAL_SEC", 90.0) or 90.0)))
    logger.info("[V702-A40-ENTRY-DIAG] read-only blocked-entry reconciliation task online interval=%.1fs", interval)
    while _SHUTDOWN is None or not _SHUTDOWN.is_set():
        try:
            if not bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
                await asyncio.sleep(interval)
                continue

            # Query durable intents from local DB (bounded) for attribution only.
            try:
                intents = await asyncio.wait_for(DBManager.aunresolved_execution_intents(), timeout=8.0)
                intent_rows = list(intents or [])
                symbols = sorted({str(x.get("symbol") or "?") for x in intent_rows if isinstance(x, dict)})
                STATS["v702_a40_unresolved_intents_latest"] = {
                    "state": "REAL", "count": len(intent_rows), "symbols": symbols[:12],
                    "ts": float(WALL_NOW()), "source": "blocked_entry_diagnostic_task",
                }
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                STATS["v702_a40_unresolved_intents_latest"] = {
                    "state": "ERROR", "count": None, "symbols": [], "ts": float(WALL_NOW()),
                    "source": "blocked_entry_diagnostic_task",
                    "error": f"{type(exc).__name__}:{str(exc)[:160]}",
                }

            # Read exchange open orders only when an entry latch is active. This
            # snapshot is observational and is never used to clear a block.
            has = getattr(exchange, "has", {})
            supports_open_orders = not isinstance(has, dict) or has.get("fetchOpenOrders") is not False
            open_fn = getattr(exchange, "fetch_open_orders", None)
            if not callable(open_fn) or not supports_open_orders:
                STATS["v702_a40_open_orders_last"] = {
                    "state": "UNSUPPORTED", "count": None, "symbols": [], "ts": float(WALL_NOW()),
                }
            else:
                try:
                    rows = await asyncio.wait_for(
                        safe_api_call("v702_a40_blockdiag_fetch_open_orders", lambda: open_fn()),
                        timeout=10.0,
                    )
                    rows = list(rows or [])
                    symbols = sorted({str(x.get("symbol") or "?") for x in rows if isinstance(x, dict)})
                    status_counts: Dict[str, int] = {}
                    for row in rows:
                        if not isinstance(row, dict):
                            continue
                        status = str(row.get("status") or "unknown").lower()[:24]
                        status_counts[status] = status_counts.get(status, 0) + 1
                    STATS["v702_a40_open_orders_last"] = {
                        "state": "REAL", "count": len(rows), "symbols": symbols[:12],
                        "status_counts": dict(sorted(status_counts.items(), key=lambda kv: (-kv[1], kv[0]))[:8]),
                        "ts": float(WALL_NOW()), "source": "exchange.fetch_open_orders",
                    }
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    STATS["v702_a40_open_orders_last"] = {
                        "state": "ERROR", "count": None, "symbols": [], "ts": float(WALL_NOW()),
                        "source": "exchange.fetch_open_orders",
                        "error": f"{type(exc).__name__}:{str(exc)[:160]}",
                    }

            d = _v702_a40_entry_block_telemetry()
            logger.warning(
                "[V702-A40-ENTRY-DIAG] active=%s reason=%s where=%s block_age_sec=%s "
                "balance_free=%s balance_state=%s balance_age_sec=%s recovery=success:%s/block:%s/error:%s/skip_nonbalance:%s/taskerr:%s "
                "last_recovery=%s/%s@%s unresolved_intents=%s:%s@%s open_orders=%s:%s@%s symbols=%s read_only=true hard_gate_bypass=false",
                d["block_active"], re.sub(r"[^A-Za-z0-9_.:/-]", "_", d["block_reason"]),
                re.sub(r"[^A-Za-z0-9_.:/-]", "_", d["block_where"]),
                "NA" if d["block_age_sec"] is None else f"{d['block_age_sec']:.0f}",
                "NA" if d["balance_free_usdt"] is None else f"{float(d['balance_free_usdt']):.6f}",
                d["balance_state"], "NA" if d["balance_age_sec"] is None else f"{d['balance_age_sec']:.0f}",
                d["recovery_successes"], d["recovery_blocks"], d["recovery_errors"], d["recovery_skipped_nonbalance"], d["recovery_task_errors"],
                d["recovery_last_reason"], d["recovery_last_state"], "NA" if d["recovery_last_age_sec"] is None else f"{d['recovery_last_age_sec']:.0f}s",
                d["unresolved_intents_state"], "NA" if d["unresolved_intents_count"] is None else d["unresolved_intents_count"],
                "NA" if d["unresolved_intents_age_sec"] is None else f"{d['unresolved_intents_age_sec']:.0f}s",
                d["open_orders_state"], "NA" if d["open_orders_count"] is None else d["open_orders_count"],
                "NA" if d["open_orders_age_sec"] is None else f"{d['open_orders_age_sec']:.0f}s",
                ",".join(str(x) for x in d["open_orders_symbols"][:5]) or "none",
            )
            await asyncio.sleep(interval)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            STATS["v702_a40_diagnostic_task_errors"] = int(STATS.get("v702_a40_diagnostic_task_errors", 0) or 0) + 1
            logger.warning("[V702-A40-ENTRY-DIAG] iteration failed; gates unchanged: %s", exc)
            await asyncio.sleep(interval)


# Extend the existing heartbeat without replacing earlier A7/A17/A33/A38 semantics.
_V702_A40_PREV_HEARTBEAT_LINE = _V702R28TelegramDigest._heartbeat_line.__func__
@classmethod
def _v702_a40_heartbeat_line(cls, text):
    base = _V702_A40_PREV_HEARTBEAT_LINE(cls, text)
    try:
        d = _v702_a40_entry_block_telemetry()
        tok = lambda value: re.sub(r"[^A-Za-z0-9_.:/-]", "_", "none" if value is None or value == "" else str(value))[:100]
        fnum = lambda value: "NA" if value is None else f"{float(value):.3f}"
        rec = (f"{d['recovery_successes']}/{d['recovery_blocks']}/{d['recovery_errors']}/"
               f"{d['recovery_skipped_nonbalance']}/{d['recovery_task_errors']}")
        base += (
            f" A40_LIVE_BLOCK=active:{int(d['block_active'])},reason:{tok(d['block_reason'])},where:{tok(d['block_where'])},age:{fnum(d['block_age_sec'])}s"
            f" A40_BALANCE=free:{fnum(d['balance_free_usdt'])},used:{fnum(d['balance_used_usdt'])},total:{fnum(d['balance_total_usdt'])},state:{tok(d['balance_state'])},age:{fnum(d['balance_age_sec'])}s"
            f" A40_RECOVERY=success/block/error/skip_nonbalance/taskerr:{rec},last:{tok(d['recovery_last_reason'])}/{tok(d['recovery_last_state'])}@{fnum(d['recovery_last_age_sec'])}s"
            f" A40_RECON=intents:{tok(d['unresolved_intents_state'])}:{tok(d['unresolved_intents_count'])}@{fnum(d['unresolved_intents_age_sec'])}s,open_orders:{tok(d['open_orders_state'])}:{tok(d['open_orders_count'])}@{fnum(d['open_orders_age_sec'])}s,hard_gate_bypass:false"
        )
    except Exception as exc:
        # Diagnostics are never authoritative; failure must not alter the prior heartbeat.
        STATS["v702_a40_heartbeat_diagnostic_errors"] = int(STATS.get("v702_a40_heartbeat_diagnostic_errors", 0) or 0) + 1
    return base
_v702_a40_heartbeat_line.__func__.__name__ = _V702_A40_PREV_HEARTBEAT_LINE.__name__
_v702_a40_heartbeat_line.__name__ = _V702_A40_PREV_HEARTBEAT_LINE.__name__
_V702R28TelegramDigest._heartbeat_line = _v702_a40_heartbeat_line


def _v702_a40_diagnostics_self_test() -> Dict[str, Any]:
    saved_block = dict(LIVE_ENTRIES_BLOCKED)
    keys = (
        "v702_a39_balance_snapshot", "v702_a39_balance_recovery_successes",
        "v702_a39_balance_recovery_blocks", "v702_a39_balance_recovery_errors",
        "v702_a39_balance_recovery_skipped_nonbalance", "v702_a39_balance_recovery_task_errors",
        "v702_a39_balance_recovery_last", "v702_a40_unresolved_intents_latest", "v702_a40_open_orders_last",
    )
    saved_stats = {k: (k in STATS, STATS.get(k)) for k in keys}
    checks: Dict[str, bool] = {}
    try:
        LIVE_ENTRIES_BLOCKED.update({"active": True, "reason": "startup_unresolved_execution_intents:2", "where": "selftest.startup", "since": float(WALL_NOW()) - 17.0})
        STATS["v702_a39_balance_snapshot"] = {"free_usdt": 75.0, "used_usdt": 75.0, "total_usdt": 150.0, "source": "fetch_balance", "ts": float(WALL_NOW()) - 5.0}
        STATS["v702_a39_balance_recovery_successes"] = 2
        STATS["v702_a39_balance_recovery_blocks"] = 3
        STATS["v702_a39_balance_recovery_errors"] = 4
        STATS["v702_a39_balance_recovery_skipped_nonbalance"] = 5
        STATS["v702_a39_balance_recovery_task_errors"] = 6
        STATS["v702_a39_balance_recovery_last"] = {"ts": float(WALL_NOW()), "block_before": "balance_cache_untrusted", "state": "REAL"}
        STATS["v702_a40_unresolved_intents_latest"] = {"state": "REAL", "count": 2, "symbols": ["ABC/USDT"], "ts": float(WALL_NOW())}
        STATS["v702_a40_open_orders_last"] = {"state": "REAL", "count": 1, "symbols": ["XYZ/USDT"], "ts": float(WALL_NOW())}
        d = _v702_a40_entry_block_telemetry()
        checks["revision_appends_a39"] = V702_A40_CANONICAL_REVISION.startswith(V702_A39_CANONICAL_REVISION + "-A40-")
        checks["original_block_reason_and_age_visible"] = d["block_active"] and d["block_reason"] == "startup_unresolved_execution_intents:2" and d["block_age_sec"] is not None and d["block_age_sec"] >= 16.0
        checks["free_used_total_and_balance_age_visible"] = d["balance_free_usdt"] == 75.0 and d["balance_used_usdt"] == 75.0 and d["balance_total_usdt"] == 150.0 and d["balance_age_sec"] is not None
        checks["recovery_counters_all_visible"] = (d["recovery_successes"], d["recovery_blocks"], d["recovery_errors"], d["recovery_skipped_nonbalance"], d["recovery_task_errors"]) == (2, 3, 4, 5, 6)
        checks["intent_and_open_order_snapshots_visible"] = d["unresolved_intents_count"] == 2 and d["open_orders_count"] == 1 and d["open_orders_state"] == "REAL"
        checks["diagnostic_is_observational_only"] = d["diagnostic_is_read_only"] and d["hard_gate_bypass"] is False and LIVE_ENTRIES_BLOCKED["active"] is True and LIVE_ENTRIES_BLOCKED["reason"] == "startup_unresolved_execution_intents:2"
        checks["read_only_task_callable"] = callable(_v702_a40_entry_block_diagnostic_task)
        checks["spot_long_only_and_hard_gates_preserved"] = bool(CONFIG.get("LONG_ONLY", False)) and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT" and not bool(CONFIG.get("ENABLE_FUTURES", False)) and FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass") is False
    except Exception as exc:
        checks["exception_free"] = False
        STATS["v702_a40_self_test_error"] = f"{type(exc).__name__}:{str(exc)[:160]}"
    finally:
        LIVE_ENTRIES_BLOCKED.clear()
        LIVE_ENTRIES_BLOCKED.update(saved_block)
        for k, (present, value) in saved_stats.items():
            if present:
                STATS[k] = value
            else:
                STATS.pop(k, None)
    failed = [k for k, value in checks.items() if not value]
    return {"pass": bool(checks) and not failed, "revision": V702_A40_CANONICAL_REVISION, "checks": checks,
            "failed": failed, "diagnostic_is_read_only": True, "hard_gate_bypass": False,
            "live_network_tested": False, "profitability_verified": False}

STATS["v702_a40_diagnostics_self_test"] = _v702_a40_diagnostics_self_test()
FINAL_CANONICAL_RUNTIME["a40_live_entry_block_diagnostics_self_test"] = STATS["v702_a40_diagnostics_self_test"]


