def _v702_a42_is_synthetic_execution_intent(row):
    """Recognize only explicit test fixtures; a TEST-like symbol alone is insufficient."""
    if not isinstance(row, dict):
        return False
    symbol = str(row.get("symbol") or "").strip().upper()
    trace = str(row.get("trace_id") or "").strip().upper()
    venue_id = str(row.get("venue_order_id") or "").strip()
    details = row.get("details") if isinstance(row.get("details"), dict) else {}
    explicit_marker = any(details.get(k) is True for k in (
        "synthetic_selftest", "validation_fixture", "mock_exchange_fixture", "test_only_intent"
    ))
    if explicit_marker:
        return True
    # These are the exact deterministic trace IDs and MOCK order-ID formats used
    # by _v517_selftest_unknown_outcomes; both the venue ID or the trace+symbol
    # sentinel must agree. A coin symbol alone is never a quarantine criterion.
    known_trace = trace in _A42_KNOWN_V517_TEST_TRACES and symbol == "TEST/USDT"
    known_mock_order = bool(_A42_MOCK_ORDER_ID_RE.fullmatch(venue_id)) and symbol == "TEST/USDT"
    return bool(known_trace or known_mock_order)


_V702_A42_PREVIOUS_UNRESOLVED_EXECUTION_INTENTS = DBManager.unresolved_execution_intents

def _v702_a42_unresolved_execution_intents_filtered():
    """Hide explicit self-test residue from LIVE reconciliation, preserving it for audit."""
    rows = _V702_A42_PREVIOUS_UNRESOLVED_EXECUTION_INTENTS()
    # While the mock self-test is executing, it needs to inspect its own disposable
    # intents as normal. Its DB is isolated by _v702_a42_run_selftest_in_isolated_db.
    if bool(globals().get("V644_SELFTEST_ACTIVE", False)):
        return rows
    if not bool(CONFIG.get("V702_A42_SYNTHETIC_INTENT_QUARANTINE_ENABLE", True)):
        STATS["v702_a42_synthetic_intent_quarantine"] = {
            "state": "DISABLED", "count": 0, "source": "execution_intents", "ts": float(WALL_NOW())
        }
        return rows
    quarantine = [r for r in rows if _v702_a42_is_synthetic_execution_intent(r)]
    live_rows = [r for r in rows if not _v702_a42_is_synthetic_execution_intent(r)]
    # Do not delete or rewrite rows. Keep short, credential-free evidence in telemetry.
    STATS["v702_a42_synthetic_intent_quarantine"] = {
        "state": "ACTIVE", "count": len(quarantine), "source": "explicit_test_trace_or_mock_order_id",
        "rows": [{
            "intent_id": str(r.get("intent_id") or "")[:32],
            "symbol": str(r.get("symbol") or "")[:32],
            "trace_id": str(r.get("trace_id") or "")[:32],
            "status": str(r.get("status") or "")[:32],
            "venue_order_id": str(r.get("venue_order_id") or "")[:40],
            "quarantine_reason": "known_selftest_fixture;not_deleted",
        } for r in quarantine[:12]],
        "live_unresolved_count": len(live_rows), "rows_deleted": 0,
        "ts": float(WALL_NOW()),
    }
    if quarantine:
        logger.warning(
            "[V702-A42-INTENT-QUARANTINE] quarantined=%s live_unresolved=%s rows_deleted=0 source=explicit_test_provenance",
            len(quarantine), len(live_rows),
        )
    return live_rows

DBManager.unresolved_execution_intents = staticmethod(_v702_a42_unresolved_execution_intents_filtered)




