def _v702_a43_derive_depth_ratio_from_exact_book(snapshot=None, candidate=None, orderbook=None):
    """Derive the canonical top-five bid-notional/required-notional ratio only from a fresh, provenance-stamped exact book."""
    snap = snapshot if isinstance(snapshot, dict) else {}
    c = getattr(candidate, "candidate", candidate)
    ob = orderbook if isinstance(orderbook, dict) else None
    out = {"trusted_source": False, "valid": False, "depth_ratio": None, "source": "UNKNOWN",
           "bid_notional_usdt": None, "required_notional_usdt": None, "book_age_sec": None,
           "reason": "exact_book_unavailable", "levels_used": 0}
    try:
        source = str(snap.get("v703_route_orderbook_source") or snap.get("v702_a9_orderbook_source") or "").strip().upper()
        status = str(snap.get("v702_a9_orderbook_prefetch_status") or "").strip().upper()
        trusted = source in _V702_A43_ALLOWED_DEPTH_SOURCES
        out["source"] = source or "UNKNOWN"
        out["trusted_source"] = bool(trusted)
        raw_ratio = snap.get("depth_ratio", None)
        # This helper is only for the explicit missing/zero sentinel. A real nonzero
        # ratio remains the existing canonical snapshot value and is not overwritten.
        if raw_ratio is not None:
            try:
                raw_num = float(raw_ratio)
            except Exception:
                raw_num = float("nan")
            if math.isfinite(raw_num) and raw_num != 0.0:
                out.update({"reason": "existing_nonzero_ratio", "valid": True, "depth_ratio": raw_num,
                            "source": str(snap.get("v702_a43_depth_ratio_source") or snap.get("v702_r41_depth_ratio_source") or source or "SNAPSHOT_FIELD")})
                return out
        if not trusted:
            out["reason"] = "untrusted_or_missing_exact_book_provenance"
            return out
        if ob is None:
            out["reason"] = "trusted_source_without_orderbook_mapping"
            return out
        bids = ob.get("bids")
        asks = ob.get("asks")
        if not isinstance(bids, (list, tuple)) or not isinstance(asks, (list, tuple)) or not bids or not asks:
            out["reason"] = "orderbook_empty_or_malformed"
            return out
        ts = None
        for key in ("book_ts", "orderbook_ts", "depth_ts", "v703_route_orderbook_captured_ts", "v702_a9_orderbook_prefetch_ts"):
            if snap.get(key) is not None:
                try:
                    ts = float(snap.get(key))
                    if ts > 1e12:
                        ts /= 1000.0
                    break
                except Exception:
                    ts = None
        if ts is None or not math.isfinite(ts) or ts <= 0.0:
            out["reason"] = "exact_book_timestamp_missing_or_invalid"
            return out
        now = float(WALL_NOW())
        age = now - ts
        out["book_age_sec"] = round(age, 3) if math.isfinite(age) else None
        max_age = max(1.0, float(CONFIG.get("V702_A43_DEPTH_EXACT_BOOK_MAX_AGE_SEC", 15.0) or 15.0))
        if not math.isfinite(age) or age < -2.0 or age > max_age:
            out["reason"] = "exact_book_stale_or_future"
            return out
        # Only FRESH/REUSED statuses known to the prefetcher are accepted. Legacy
        # exact route books use their own source stamp and need no prefetch status.
        if source == "V702_A9_PREFETCH_EXACT_BOOK" and status not in {"FRESH", "REUSED", "REUSED_RECENT", "OK", "FETCHED_FRESH", "REUSED_FRESH"}:
            out["reason"] = f"prefetch_status_not_usable:{status or 'MISSING'}"
            return out
        prices = []
        notional = 0.0
        for level in list(bids)[:5]:
            if not isinstance(level, (list, tuple)) or len(level) < 2:
                out["reason"] = "bid_level_malformed"
                return out
            px, qty = float(level[0]), float(level[1])
            if not (math.isfinite(px) and math.isfinite(qty) and px > 0.0 and qty > 0.0):
                out["reason"] = "bid_level_nonfinite_or_nonpositive"
                return out
            prices.append(px)
            notional += px * qty
        # Verify asks too: a book with malformed asks is not a trustworthy snapshot.
        for level in list(asks)[:5]:
            if not isinstance(level, (list, tuple)) or len(level) < 2:
                out["reason"] = "ask_level_malformed"
                return out
            px, qty = float(level[0]), float(level[1])
            if not (math.isfinite(px) and math.isfinite(qty) and px > 0.0 and qty > 0.0):
                out["reason"] = "ask_level_nonfinite_or_nonpositive"
                return out
        required = max(
            float(CONFIG.get("MIN_POSITION_SIZE_USDT", 15.0) or 15.0),
            min(float(CONFIG.get("MAX_POSITION_SIZE_USDT", 80.0) or 80.0),
                float(CONFIG.get("FIXED_POSITION_SIZE_USDT", 80.0) or 80.0)),
        )
        if not math.isfinite(required) or required <= 0.0 or not math.isfinite(notional) or notional < 0.0:
            out["reason"] = "required_notional_or_depth_invalid"
            return out
        ratio = notional / max(required, 1e-9)
        if not math.isfinite(ratio) or ratio < 0.0:
            out["reason"] = "derived_ratio_invalid"
            return out
        out.update({"valid": True, "depth_ratio": float(ratio), "bid_notional_usdt": float(notional),
                    "required_notional_usdt": float(required), "reason": "derived_from_fresh_exact_book",
                    "levels_used": len(prices), "status": status or "NOT_APPLICABLE"})
        return out
    except Exception as exc:
        out["reason"] = f"depth_derivation_error:{type(exc).__name__}"
        return out


def _v702_a43_record_depth_observation(symbol, tier, depth_ratio, evidence=None, floor=None, reason="", stage="prequal"):
    """Bounded numeric depth-gate evidence; telemetry cannot approve a trade."""
    try:
        ev = evidence if isinstance(evidence, dict) else {}
        try:
            ratio = float(depth_ratio) if depth_ratio is not None else None
            if ratio is not None and not math.isfinite(ratio):
                ratio = None
        except Exception:
            ratio = None
        try:
            floor_n = float(floor) if floor is not None else None
            if floor_n is not None and not math.isfinite(floor_n):
                floor_n = None
        except Exception:
            floor_n = None
        _derived = bool(ev.get("reason") == "derived_from_fresh_exact_book")
        row = {
            "symbol": str(symbol or "UNKNOWN").upper()[:64],
            "tier": str(getattr(tier, "value", tier) or "UNKNOWN").upper()[:24],
            "stage": str(stage or "prequal")[:32], "reason": str(reason or "unknown")[:80],
            "depth_ratio": ratio, "floor": floor_n,
            "source": str(ev.get("source") or "SNAPSHOT_FIELD")[:64],
            "derived": _derived, "admission_input_derived": _derived,
            "bid_notional_usdt": ev.get("bid_notional_usdt"),
            "required_notional_usdt": ev.get("required_notional_usdt"),
            "book_age_sec": ev.get("book_age_sec"),
            "derivation_reason": str(ev.get("reason") or "not_needed")[:80],
            "ts": float(WALL_NOW()), "telemetry_only": True,
            "recorder_changed_decision": False,
        }
        # Backward-compatible alias: this refers to the recorder only. The
        # admission input may legitimately be corrected from the exact fresh book.
        row["decision_changed"] = row["recorder_changed_decision"]
        with _V702_A43_DEPTH_LOCK:
            STATS["v702_a43_depth_observation_count"] = int(STATS.get("v702_a43_depth_observation_count", 0) or 0) + 1
            STATS["v702_a43_depth_last"] = row
            if "depth_ratio_below_floor" in row["reason"]:
                STATS["v702_a43_depth_reject_count"] = int(STATS.get("v702_a43_depth_reject_count", 0) or 0) + 1
            if "unverifiable" in row["reason"]:
                STATS["v702_a43_depth_unverifiable_count"] = int(STATS.get("v702_a43_depth_unverifiable_count", 0) or 0) + 1
            hist = STATS.setdefault("v702_a43_depth_history", [])
            if not isinstance(hist, list):
                hist = []
                STATS["v702_a43_depth_history"] = hist
            hist.append(row)
            if len(hist) > 64:
                del hist[:-64]
        return row
    except Exception:
        STATS["v702_a43_depth_diagnostic_errors"] = int(STATS.get("v702_a43_depth_diagnostic_errors", 0) or 0) + 1
        return {"recorded": False}


def _v702_a43_bearish_severity(df15, df4):
    """Strict crash-vs-trend classification: standalone 4H lower lows are STRESSED, not CRASH.

    CRASH remains fail-closed for missing/invalid evidence, explicit BTCContext CRASH/BLOCK,
    a confirmed 15m drop at/below the crash threshold, or simultaneous stress-drop + ATR expansion.
    A lower-low sequence alone is meaningful bearish structure, but is not by itself proof of a
    volatility crash; it stays STRESSED and every family/HTF/score/liquidity/fee/risk gate remains.
    """
    crash = str(getattr(V425BearishSeverity, "CRASH", "BEARISH_CRASH"))
    facts = {"severity": crash, "reason": "bearish_severity_uninitialized", "cause": "FAIL_CLOSED",
             "drop_pct": None, "atr_now": None, "atr_reference": None, "atr_ratio": None,
             "atr_expanding": None, "breakdown": None, "lower_low_pairs": None, "closed_4h_lows": [],
             "btc_context_state": "UNKNOWN", "rows_15m": 0, "rows_4h": 0,
             "thresholds": {}, "closed_bar_only": True, "decision_changed_from_a42": False}
    def finish(severity, reason, cause):
        facts.update({"severity": str(severity), "reason": str(reason), "cause": str(cause), "ts": float(WALL_NOW())})
        try:
            STATS["v702_a43_bearish_classify_calls"] = int(STATS.get("v702_a43_bearish_classify_calls", 0) or 0) + 1
            STATS["v702_a43_bearish_last"] = dict(facts)
            counts = STATS.setdefault("v702_a43_bearish_counts", {})
            key = f"{str(severity)}:{str(cause)}"
            counts[key] = int(counts.get(key, 0) or 0) + 1
            hist = STATS.setdefault("v702_a43_bearish_history", [])
            if not isinstance(hist, list):
                hist = []
                STATS["v702_a43_bearish_history"] = hist
            hist.append(dict(facts))
            if len(hist) > 64:
                del hist[:-64]
        except Exception:
            pass
        return str(severity), str(reason)
    try:
        win = int(CONFIG.get("V425_BEARISH_CRASH_WINDOW_15M", 8))
        n4 = int(CONFIG.get("V425_BEARISH_CRASH_WINDOW_4H", 3))
        need = int(CONFIG.get("V425_BEARISH_CRASH_BREAKDOWN_N", 3))
        atr_period = int(CONFIG.get("ATR_PERIOD", 14))
        crash_drop = float(CONFIG.get("V425_BEARISH_CRASH_DROP_PCT", -6.0))
        stress_drop = float(CONFIG.get("V425_BEARISH_STRESSED_DROP_PCT", -3.0))
        atr_mult = float(CONFIG.get("V425_BEARISH_CRASH_ATR_MULT", 2.5))
        facts["thresholds"] = {"window_15m": win, "crash_drop_pct": crash_drop, "stress_drop_pct": stress_drop,
                               "atr_expansion_multiple": atr_mult, "window_4h": n4, "breakdown_pairs_required": need,
                               "breakdown_alone_means": "STRESSED_NOT_CRASH"}
        if (win < 1 or n4 < 2 or need < 2 or need > n4 or atr_period < 1
                or not all(math.isfinite(x) for x in (crash_drop, stress_drop, atr_mult))
                or crash_drop > stress_drop or stress_drop >= 0 or atr_mult <= 0):
            return finish(crash, "bearish_severity_config_invalid", "CONFIG_INVALID_FAIL_CLOSED")
        if df15 is None or not hasattr(df15, "columns") or not {"close", "high", "low"}.issubset(set(df15.columns)):
            return finish(crash, "bearish_15m_context_missing", "MISSING_DATA_FAIL_CLOSED")
        if len(df15) < max(win + 2, 22):
            facts["rows_15m"] = int(len(df15))
            return finish(crash, "bearish_15m_history_insufficient", "INSUFFICIENT_DATA_FAIL_CLOSED")
        if df4 is None or not hasattr(df4, "columns") or "low" not in df4.columns:
            return finish(crash, "bearish_4h_low_context_missing", "MISSING_DATA_FAIL_CLOSED")
        try:
            facts["rows_15m"] = int(len(df15)); facts["rows_4h"] = int(len(df4))
        except Exception:
            pass
        operational_min = max(240, int(CONFIG.get("BTC_SHARED_CONTEXT_MIN_CANDLES_4H", 240) or 240))
        if len(df4) < max(n4 + 1, operational_min + 1):
            return finish(crash, "bearish_4h_history_insufficient", "INSUFFICIENT_DATA_FAIL_CLOSED")
        first = float(df15["close"].iloc[-(win + 1)])
        last = float(df15["close"].iloc[-2])
        if not (math.isfinite(first) and first > 0.0 and math.isfinite(last) and last > 0.0):
            return finish(crash, "bearish_15m_close_invalid", "INVALID_DATA_FAIL_CLOSED")
        drop_pct = (last - first) / first * 100.0
        if not math.isfinite(drop_pct):
            return finish(crash, "bearish_15m_drop_invalid", "INVALID_DATA_FAIL_CLOSED")
        atr_series = Indicators.atr(df15, atr_period)
        if atr_series is None or len(atr_series) < 22:
            return finish(crash, "bearish_atr_history_insufficient", "INSUFFICIENT_DATA_FAIL_CLOSED")
        atr_now = float(atr_series.iloc[-2])
        atr_reference_values = [float(x) for x in atr_series.iloc[-22:-2]]
        if len(atr_reference_values) != 20 or any(not math.isfinite(x) or x <= 0.0 for x in atr_reference_values):
            return finish(crash, "bearish_atr_reference_invalid", "INVALID_DATA_FAIL_CLOSED")
        atr_reference = sum(atr_reference_values) / len(atr_reference_values)
        if not (math.isfinite(atr_now) and atr_now > 0.0 and math.isfinite(atr_reference) and atr_reference > 0.0):
            return finish(crash, "bearish_atr_value_invalid", "INVALID_DATA_FAIL_CLOSED")
        atr_ratio = atr_now / atr_reference
        atr_expanding = atr_ratio >= atr_mult
        closed_lows = [float(df4["low"].iloc[-k]) for k in range(2, 2 + n4)]
        if any(not math.isfinite(x) or x <= 0.0 for x in closed_lows):
            return finish(crash, "bearish_4h_lows_invalid", "INVALID_DATA_FAIL_CLOSED")
        lower_pairs = sum(1 for i in range(len(closed_lows) - 1) if closed_lows[i] < closed_lows[i + 1])
        breakdown = lower_pairs >= (need - 1)
        try:
            btc_state = str(getattr(BTCContext, "_state", "OK") or "OK").upper()
        except Exception:
            btc_state = "UNKNOWN"
        facts.update({"drop_pct": round(drop_pct, 5), "atr_now": round(atr_now, 8),
                      "atr_reference": round(atr_reference, 8), "atr_ratio": round(atr_ratio, 5),
                      "atr_expanding": bool(atr_expanding), "breakdown": bool(breakdown),
                      "lower_low_pairs": int(lower_pairs), "closed_4h_lows": [round(x, 8) for x in closed_lows],
                      "btc_context_state": btc_state})
        # Hard crash evidence remains absolute.
        if btc_state in {"CRASH", "BLOCK"}:
            return finish(crash, "bearish_crash_confirmed", "BTC_CONTEXT_HARD_CRASH")
        if drop_pct <= crash_drop:
            return finish(crash, "bearish_crash_confirmed", "15M_DROP_AT_CRASH_THRESHOLD")
        if atr_expanding and drop_pct <= stress_drop:
            return finish(crash, "bearish_crash_confirmed", "15M_STRESS_DROP_WITH_ATR_EXPANSION")
        # A lower-low sequence is bearish trend evidence, not enough alone to
        # establish a volatility crash. It remains restrictive as STRESSED.
        if breakdown:
            # A42 treated any qualifying 4H lower-low sequence as CRASH. A43
            # intentionally changes that single classification to STRESSED; record
            # the policy delta explicitly so telemetry does not imply zero change.
            facts["decision_changed_from_a42"] = True
            if drop_pct <= stress_drop or atr_expanding:
                return finish(str(V425BearishSeverity.STRESSED), "bearish_stressed", "STRESSED_MARKET_WITH_4H_BREAKDOWN")
            return finish(str(V425BearishSeverity.STRESSED), "bearish_stressed", "BREAKDOWN_ONLY_CLASSIFIED_STRESSED")
        if drop_pct <= stress_drop or atr_expanding:
            return finish(str(V425BearishSeverity.STRESSED), "bearish_stressed", "STRESSED_15M_OR_ATR_EVIDENCE")
        return finish(str(V425BearishSeverity.NORMAL), "bearish_normal", "NO_CRASH_OR_STRESS_CONFIRMATION")
    except Exception as exc:
        facts["error_type"] = type(exc).__name__
        return finish(crash, f"bearish_severity_error:{type(exc).__name__}", "EVALUATION_ERROR_FAIL_CLOSED")


# Swap only the calculation behind the established A17 cache. Cache keys and the
