def _v702_a43_depth_diagnostics_self_test():
    checks = {}
    saved_state = getattr(BTCContext, "_state", "OK")
    try:
        BTCContext._state = "OK"
        if not bool(globals().get("_PDNP_OK", False)) or "pd" not in globals():
            checks["pandas_available"] = False
        else:
            n = 64
            # Mild 15m pullback with stable ATR, paired with three closed lower 4H lows.
            close = [100.0 - 0.015 * i for i in range(n)]
            df15 = pd.DataFrame({"close": close, "high": [x + 0.50 for x in close],
                                 "low": [x - 0.50 for x in close], "volume": [1000.0] * n})
            low4 = [400.0 - 0.10 * i for i in range(261)]
            df4 = pd.DataFrame({"low": low4, "close": [x + 1.0 for x in low4], "high": [x + 2.0 for x in low4]})
            sev, why = _v702_a43_bearish_severity(df15, df4)
            last = dict(STATS.get("v702_a43_bearish_last", {}) or {})
            checks["four_hour_lower_lows_alone_are_stressed"] = sev == str(V425BearishSeverity.STRESSED) and why == "bearish_stressed" and last.get("cause") == "BREAKDOWN_ONLY_CLASSIFIED_STRESSED"
            checks["a42_classification_delta_explicitly_recorded"] = last.get("decision_changed_from_a42") is True
            checks["four_hour_breakdown_continues_to_existing_family_policy"] = sev == str(V425BearishSeverity.STRESSED) and FamilyPolicyLayer.strategy_allowed is _V702_A43_FAMILY_POLICY_AUTHORITY
            # Severe closed-bar drawdown is still an absolute crash.
            crash_close = [100.0] * n
            for i in range(n - 10, n - 1):
                crash_close[i] = 100.0 - (i - (n - 10)) * 1.0
            crash_close[-1] = crash_close[-2]
            df15_crash = pd.DataFrame({"close": crash_close, "high": [x + 0.5 for x in crash_close],
                                       "low": [x - 0.5 for x in crash_close], "volume": [1000.0] * n})
            sev_crash, why_crash = _v702_a43_bearish_severity(df15_crash, df4)
            facts_crash = dict(STATS.get("v702_a43_bearish_last", {}) or {})
            checks["severe_closed_15m_drop_remains_crash"] = sev_crash == str(V425BearishSeverity.CRASH) and why_crash == "bearish_crash_confirmed" and facts_crash.get("cause") == "15M_DROP_AT_CRASH_THRESHOLD"
            missing_sev, missing_reason = _v702_a43_bearish_severity(None, df4)
            checks["missing_context_fails_closed"] = missing_sev == str(V425BearishSeverity.CRASH) and "missing" in missing_reason
            checks["unknown_severity_never_authorizes_long"] = not V425BearishSeverity.allows_new_long("UNKNOWN")
        exact_book = {"bids": [[100.0, 1.0], [99.9, 1.0]], "asks": [[100.1, 1.0], [100.2, 1.0]]}
        trusted_snapshot = {"v703_route_orderbook_source": "V702_A9_PREFETCH_EXACT_BOOK",
                            "v702_a9_orderbook_prefetch_status": "FETCHED_FRESH", "depth_ratio": 0.0,
                            "book_ts": float(WALL_NOW())}
        ev = _v702_a43_derive_depth_ratio_from_exact_book(trusted_snapshot, None, exact_book)
        checks["zero_sentinel_derives_numeric_ratio_from_fresh_trusted_book"] = bool(ev.get("trusted_source") and ev.get("valid") and float(ev.get("depth_ratio") or 0.0) > 0.0 and ev.get("reason") == "derived_from_fresh_exact_book")
        stale = dict(trusted_snapshot, book_ts=float(WALL_NOW()) - float(CONFIG.get("V702_A43_DEPTH_EXACT_BOOK_MAX_AGE_SEC", 15.0)) - 30.0)
        ev_stale = _v702_a43_derive_depth_ratio_from_exact_book(stale, None, exact_book)
        checks["stale_exact_book_is_not_used"] = bool(ev_stale.get("trusted_source") and not ev_stale.get("valid") and ev_stale.get("reason") == "exact_book_stale_or_future")
        untrusted = dict(trusted_snapshot, v703_route_orderbook_source="")
        ev_untrusted = _v702_a43_derive_depth_ratio_from_exact_book(untrusted, None, exact_book)
        checks["untrusted_book_is_not_used"] = not ev_untrusted.get("trusted_source") and not ev_untrusted.get("valid")
        checks["hard_gate_bypass_false"] = FINAL_CANONICAL_RUNTIME.get("hard_gate_bypass") is False
        checks["thresholds_unchanged"] = float(CONFIG.get("V425_BEARISH_CRASH_DROP_PCT", -6.0)) == -6.0 and float(CONFIG.get("V425_BEARISH_STRESSED_DROP_PCT", -3.0)) == -3.0 and float(CONFIG.get("V45_TIER_MICRO_MIN_DEPTH_RATIO", 1.90)) >= 1.90
        checks["spot_long_only_preserved"] = bool(CONFIG.get("LONG_ONLY")) and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT" and not bool(CONFIG.get("ENABLE_FUTURES"))
        report = {"pass": bool(checks) and all(checks.values()), "checks": checks,
                  "revision": V702_A43_CANONICAL_REVISION, "hard_gate_bypass": False,
                  "live_gates_relaxed": False, "live_exchange_tested": False,
                  "profitability_verified": False}
    except Exception as exc:
        report = {"pass": False, "checks": checks, "failed": ["exception"],
                  "error": f"{type(exc).__name__}:{str(exc)[:160]}", "hard_gate_bypass": False, "live_gates_relaxed": False}
    finally:
        try:
            BTCContext._state = saved_state
        except Exception:
            pass
    report.setdefault("failed", [k for k, v in report.get("checks", {}).items() if not bool(v)])
    STATS["v702_a43_crash_depth_self_test"] = report
    FINAL_CANONICAL_RUNTIME["a43_crash_depth_self_test"] = report
    return report


# Extend the current heartbeat only with compact numeric diagnostics. It remains
