_V702_A43_PREVIOUS_HEARTBEAT = _V702R28TelegramDigest._heartbeat_line.__func__
@classmethod
def _v702_a43_heartbeat_line(cls, text):
    base = _V702_A43_PREVIOUS_HEARTBEAT(cls, text)
    try:
        b = STATS.get("v702_a43_bearish_last", {}) or {}
        if b:
            base += (f" A43_BEARISH=sev:{b.get('severity','?')},cause:{b.get('cause','?')},"
                     f"drop:{b.get('drop_pct','NA')},atrx:{b.get('atr_ratio','NA')},"
                     f"breakdown:{int(bool(b.get('breakdown')))},deltaA42:{int(bool(b.get('decision_changed_from_a42')))},"
                     f"btc:{b.get('btc_context_state','?')},age:{max(0.0, float(WALL_NOW())-float(b.get('ts',0.0) or 0.0)):.0f}s")
        d = STATS.get("v702_a43_depth_last", {}) or {}
        if d:
            base += (f" A43_DEPTH=sym:{d.get('symbol','?')},tier:{d.get('tier','?')},"
                     f"ratio:{d.get('depth_ratio','NA')},floor:{d.get('floor','NA')},"
                     f"bid:{d.get('bid_notional_usdt','NA')},req:{d.get('required_notional_usdt','NA')},"
                     f"derived:{int(bool(d.get('admission_input_derived', d.get('derived',False))))},"
                     f"src:{str(d.get('source','?'))[:24]},age:{d.get('book_age_sec','NA')},"
                     f"why:{str(d.get('reason','?'))[:40]}")
        base += (f" A43_GUARDS=crash_policy:{int(bool(CONFIG.get('V702_A43_HTF_CRASH_DISCRIMINATION_ENABLE',False)))},"
                 f"depth_diag:{int(bool(CONFIG.get('V702_A43_DEPTH_NUMERIC_DIAGNOSTICS_ENABLE',False)))},"
                 f"bypass:{str(FINAL_CANONICAL_RUNTIME.get('hard_gate_bypass', True)).lower()}")
    except Exception:
        STATS["v702_a43_heartbeat_errors"] = int(STATS.get("v702_a43_heartbeat_errors", 0) or 0) + 1
    return base
_v702_a43_heartbeat_line.__func__.__name__ = _V702_A43_PREVIOUS_HEARTBEAT.__name__
_v702_a43_heartbeat_line.__name__ = _V702_A43_PREVIOUS_HEARTBEAT.__name__
_V702R28TelegramDigest._heartbeat_line = _v702_a43_heartbeat_line

