class _V702A44GuardedConfig(dict):
    def __init__(self, source):
        super().__init__(source)
        self._a44_locked_values = {}
        self._a44_snapshot_ts = 0.0

    def freeze_risk_values(self):
        self._a44_locked_values = {k: self.get(k) for k in _V702_A44_RISK_CONFIG_KEYS if k in self}
        self._a44_snapshot_ts = float(WALL_NOW())
        STATS["v702_a44_config_snapshot"] = {
            "ts": self._a44_snapshot_ts,
            "keys": len(self._a44_locked_values),
            "score_floor": float(self.get("MIN_LIVE_SCORE", 70.0) or 70.0),
            "adaptive_floor_min": float(self.get("V453_SCORE_FLOOR_MIN", 70.0) or 70.0),
            "v420_adaptive_floor_min": float(self.get("V420_ADAPTIVE_FLOOR_MIN", 70.0) or 70.0),
        }

    def __setitem__(self, key, value):
        try:
            armed = bool(globals().get("_V699_LIVE_EPOCH_ARMED", False))
            locked = getattr(self, "_a44_locked_values", {})
            if (armed and bool(dict.get(self, "V702_A44_CONFIG_GUARD_ENABLE", True))
                    and key in _V702_A44_RISK_CONFIG_KEYS and key in locked
                    and value != locked[key]):
                STATS["v702_a44_config_mutation_blocked"] = int(STATS.get("v702_a44_config_mutation_blocked", 0) or 0) + 1
                logger.critical("[V702-A44-CONFIG] blocked post-validation safety-config mutation key=%s", str(key)[:100])
                return
        except Exception:
            # If the guard itself cannot inspect state, fail closed for risk keys.
            if key in _V702_A44_RISK_CONFIG_KEYS and bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
                return
        dict.__setitem__(self, key, value)

    def update(self, *args, **kwargs):
        incoming = dict(*args, **kwargs)
        for key, value in incoming.items():
            self[key] = value

    def setdefault(self, key, default=None):
        if key not in self:
            self[key] = default
        return self.get(key)

    def __delitem__(self, key):
        if (key in _V702_A44_RISK_CONFIG_KEYS and bool(globals().get("_V699_LIVE_EPOCH_ARMED", False))
                and bool(dict.get(self, "V702_A44_CONFIG_GUARD_ENABLE", True))):
            STATS["v702_a44_config_mutation_blocked"] = int(STATS.get("v702_a44_config_mutation_blocked", 0) or 0) + 1
            logger.critical("[V702-A44-CONFIG] blocked post-arm deletion of risk config key=%s", str(key)[:100])
            return
        dict.__delitem__(self, key)

    def pop(self, key, *default):
        if key in _V702_A44_RISK_CONFIG_KEYS and bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
            STATS["v702_a44_config_mutation_blocked"] = int(STATS.get("v702_a44_config_mutation_blocked", 0) or 0) + 1
            logger.critical("[V702-A44-CONFIG] blocked post-arm pop of risk config key=%s", str(key)[:100])
            return self.get(key, default[0] if default else None)
        if default:
            return dict.pop(self, key, default[0])
        return dict.pop(self, key)

    def popitem(self):
        if bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
            # A generic popitem could silently remove a risk-bearing key; fail closed.
            STATS["v702_a44_config_mutation_blocked"] = int(STATS.get("v702_a44_config_mutation_blocked", 0) or 0) + 1
            logger.critical("[V702-A44-CONFIG] blocked post-arm popitem")
            raise RuntimeError("CONFIG mutation prohibited after LIVE epoch arm")
        return dict.popitem(self)

    def clear(self):
        if bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
            STATS["v702_a44_config_mutation_blocked"] = int(STATS.get("v702_a44_config_mutation_blocked", 0) or 0) + 1
            logger.critical("[V702-A44-CONFIG] blocked post-arm CONFIG.clear")
            return
        dict.clear(self)

    def __ior__(self, other):
        self.update(other)
        return self

CONFIG = _V702A44GuardedConfig(CONFIG)

# Unified operator reason precedence. This is classification only and does not
# affect candidate admission, sizing, order submission, or protection.
def _v702_a44_reason_root(reason: str, stage: str = "") -> str:
    r = str(reason or "").strip().lower()
    token = f"{stage}:{r}".lower()
    if any(x in token for x in ("kill_switch", "kill-switch", "daily_circuit", "circuit_breaker")):
        return "KILL_SWITCH"
    if any(x in token for x in ("unprotected", "stopless", "protection", "native_sl", "cancel_unverified", "emergency_sell", "sl_health")):
        return "PROTECTION"
    if any(x in token for x in ("execution_intent", "submission_unknown", "execution_unknown", "fill_reconcile", "startup_unresolved", "maker_order_id_unknown")):
        return "EXECUTION_INTENT"
    if any(x in token for x in ("balance", "funding_latch", "free_usdt", "insufficient_funds", "reconciler_block")):
        return "BALANCE"
    if r.startswith("htf.") or "bearish_crash_guard" in token or "core_not_aligned" in token or "family_htf_strength" in token:
        return "HTF"
    if r.startswith("policy.") or "family_regime_disallowed" in token or "strategy_incompatible" in token or "family_policy" in token:
        return "POLICY"
    if any(x in token for x in ("liquidity", "spread", "depth", "orderbook", "tier_below")):
        return "LIQUIDITY"
    if any(x in token for x in ("structure", "fake_break", "reclaim", "microstruct", "bos")):
        return "STRUCTURE"
    if "score" in token or "threshold" in token:
        return "SCORE"
    if any(x in token for x in ("fee", "economic", "net_rr", "net_profit", "fee_unviable")):
        return "FEE"
    if any(x in token for x in ("pre_send", "presend", "queue", "telegram", "send_fail", "execution")):
        return "EXECUTION"
    if "exception" in token or "watchdog" in token or "network" in token or "timeout" in token or "system" in token:
        return "SYSTEM"
    return "OTHER"

try:
    _V702_A44_OLD_V698_REASON_ROOT = _v698_reason_root
    def _v698_reason_root(reason: str, stage: str = "") -> str:
        return _v702_a44_reason_root(reason, stage)
    _V702_A44_OLD_A33_REASON_ROOT = globals().get("_v702_a33_reason_root")
    def _v702_a33_reason_root(reason: str) -> str:
        return _v702_a44_reason_root(reason, "entry_block")
    _V702_A44_OLD_REJECT_BUCKET = _v453_reject_bucket
    def _v453_reject_bucket(reason: str) -> str:
        root = _v702_a44_reason_root(reason, "prequal")
        return {"BALANCE":"balance", "KILL_SWITCH":"system", "PROTECTION":"execution",
                "EXECUTION_INTENT":"execution", "HTF":"htf", "POLICY":"policy",
                "LIQUIDITY":"liquidity", "STRUCTURE":"structure", "SCORE":"score",
                "FEE":"fee", "EXECUTION":"pre_send", "SYSTEM":"system"}.get(root, "other")
except Exception as _a44_root_exc:
    STATS["v702_a44_reason_root_install_error"] = f"{type(_a44_root_exc).__name__}:{_a44_root_exc}"

# Score relief may gather evidence only on healthy cycles. A safety latch clears
# evidence and pins the adaptive floor at the canonical live floor (70).
_V702_A44_OLD_V453_TICK = V453CanonicalScoreFloor.tick.__func__
@classmethod
def _v702_a44_v453_tick(cls):
    try:
        hazard = _v453_safety_hazard()
    except Exception:
        hazard = "safety.hazard_check_failed"
    if hazard:
        try:
            cls._obs.clear()
            base = max(70.0, float(CONFIG.get("MIN_LIVE_SCORE", 70.0) or 70.0))
            _V420State.adaptive_floor = base
            STATS["v702_a44_score_relief_skipped_hazard"] = int(STATS.get("v702_a44_score_relief_skipped_hazard", 0) or 0) + 1
            STATS["v702_a44_score_relief_last_hazard"] = str(hazard)[:120]
            return base
        except Exception:
            return 70.0
    result = float(_V702_A44_OLD_V453_TICK(cls))
    floor = max(70.0, float(CONFIG.get("MIN_LIVE_SCORE", 70.0) or 70.0))
    result = max(floor, result)
    try:
        _V420State.adaptive_floor = max(floor, float(getattr(_V420State, "adaptive_floor", floor) or floor))
    except Exception:
        pass
    return result
V453CanonicalScoreFloor.tick = _v702_a44_v453_tick

# Hysteresis applies to release of a *balance-only* entry latch, not to other
# risk gates. The initial minimum remains BALANCE_MIN_ACCEPT_USDT; re-entry into
# an already active low-balance latch needs 10% headroom.
_V702_A44_OLD_LIVE_ENTRIES_UNBLOCK = live_entries_unblock
def live_entries_unblock(reason: str = "", where: str = "") -> bool:
    try:
        block = LIVE_ENTRIES_BLOCKED if isinstance(LIVE_ENTRIES_BLOCKED, dict) else {}
        recorded = str(block.get("reason") or "").lower()
        requested = str(reason or "").lower()
        if (bool(CONFIG.get("V702_A44_BALANCE_HYSTERESIS_ENABLE", True))
                and bool(block.get("active")) and recorded in _AUTO_BALANCE_RECOVERABLE_BLOCK_REASONS
                and requested in {"real_balance_recovered", "balance_reconciled", "balance_recovery_verified"}):
            min_free = max(0.0, float(CONFIG.get("BALANCE_MIN_ACCEPT_USDT", 5.0) or 5.0))
            multiplier = max(1.0, float(CONFIG.get("V702_A44_BALANCE_UNLATCH_MULTIPLIER", 1.10) or 1.10))
            free = float(getattr(BalanceReconciler, "_last_real_value", 0.0) or 0.0)
            ts = float(getattr(BalanceReconciler, "_last_real_ts", 0.0) or 0.0)
            snapshot_age = float(MONO_NOW()) - ts if ts > 0 else float("inf")
            max_age = max(5.0, min(90.0, float(CONFIG.get("BALANCE_CACHE_TTL_SEC", 45.0) or 45.0)))
            if (not math.isfinite(free) or free < min_free * multiplier
                    or not math.isfinite(snapshot_age) or snapshot_age < 0 or snapshot_age > max_age):
                STATS["v702_a44_balance_hysteresis_holds"] = int(STATS.get("v702_a44_balance_hysteresis_holds", 0) or 0) + 1
                STATS["v702_a44_balance_hysteresis_last"] = {"free":free,"minimum":min_free,"release_at":min_free*multiplier,"reason":recorded,"snapshot_age_sec":snapshot_age,"max_snapshot_age_sec":max_age,"ts":float(WALL_NOW())}
                return False
    except Exception as _a44_hyst_exc:
        STATS["v702_a44_balance_hysteresis_errors"] = int(STATS.get("v702_a44_balance_hysteresis_errors", 0) or 0) + 1
        return False
    return bool(_V702_A44_OLD_LIVE_ENTRIES_UNBLOCK(reason=reason, where=where))

# Transition-only funding/ops alert. Delivery is attempted once per block
# fingerprint, never every heartbeat. The periodic digest also retains the action.
_V702_A44_OLD_LIVE_ENTRIES_BLOCK = live_entries_block
async def _v702_a44_send_block_transition_alert(fingerprint: str, message: str):
    try:
        enqueue = globals().get("_V702_R28_RAW_ENQUEUE")
        if not callable(enqueue):
            enqueue = TelegramDispatcher.enqueue
        ok = await enqueue(message)
        STATS["v702_a44_block_alert_result"] = {"ts":float(WALL_NOW()),"fingerprint":fingerprint[:160],"ok":bool(ok)}
        if ok is False:
            STATS["v702_a44_block_alert_failures"] = int(STATS.get("v702_a44_block_alert_failures", 0) or 0) + 1
    except Exception as exc:
        STATS["v702_a44_block_alert_failures"] = int(STATS.get("v702_a44_block_alert_failures", 0) or 0) + 1
        STATS["v702_a44_block_alert_error"] = f"{type(exc).__name__}:{str(exc)[:160]}"

def _v702_a44_maybe_notify_latch():
    try:
        if not bool(CONFIG.get("V702_A44_ACTION_ALERT_ON_LATCH_TRANSITION", True)):
            return
        if not bool(globals().get("_V699_LIVE_EPOCH_ARMED", False)):
            return
        block = LIVE_ENTRIES_BLOCKED if isinstance(LIVE_ENTRIES_BLOCKED, dict) else {}
        if not bool(block.get("active")):
            return
        reason = str(block.get("reason") or "unknown")
        where = str(block.get("where") or "unknown")
        since = float(block.get("since") or WALL_NOW())
        fingerprint = f"{reason}|{where}|{since:.3f}"
        last_fp = STATS.get("v702_a44_block_alert_last_fingerprint")
        last_attempted = STATS.get("v702_a44_block_alert_attempted_fingerprint")
        if last_fp == fingerprint and (last_attempted == fingerprint or bool(STATS.get("v702_a44_block_alert_task_pending"))):
            return
        # Obtain the running loop BEFORE consuming the one-shot transition. If
        # called from a synchronous path, leave it pending for the first async
        # heartbeat instead of permanently losing the alert.
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            STATS["v702_a44_block_alert_pending"] = True
            STATS["v702_a44_block_alert_pending_fingerprint"] = fingerprint
            return
        STATS["v702_a44_block_alert_last_fingerprint"] = fingerprint
        STATS["v702_a44_block_alert_attempted_fingerprint"] = fingerprint
        STATS["v702_a44_block_alert_pending"] = False
        now = float(WALL_NOW())
        age = max(0.0, now - since)
        snap = STATS.get("v702_a39_balance_snapshot", {}) or {}
        free = snap.get("free_usdt") if isinstance(snap, dict) else None
        min_free = float(CONFIG.get("BALANCE_MIN_ACCEPT_USDT", 5.0) or 5.0)
        latch_type = "FUNDING_LATCH" if _v702_a44_reason_root(reason, where) == "BALANCE" else "OPS_LATCH"
        if latch_type == "FUNDING_LATCH" and free is not None and float(free) < min_free:
            action = f"ACTION_REQUIRED: fund account after verifying exchange balance; free={float(free):.2f} USDT, min={min_free:.2f} USDT"
        elif latch_type == "FUNDING_LATCH":
            action = f"ACTION_REQUIRED: refresh/verify free USDT and allow hysteresis release only at >= {min_free*1.10:.2f} USDT"
        else:
            action = "ACTION_REQUIRED: reconcile the named operational/protection/intent hazard; do not manually clear the latch"
        message = ("V702 A44 ENTRY LATCH\n" + latch_type + "\n" + action +
                   f"\nreason={reason[:150]}\nwhere={where[:100]}\nblocked_since={age:.0f}s\nhard_gate_bypass=false")
        task = loop.create_task(_v702_a44_send_block_transition_alert(fingerprint, message))
        STATS["v702_a44_block_alert_attempts"] = int(STATS.get("v702_a44_block_alert_attempts", 0) or 0) + 1
        STATS["v702_a44_block_alert_task_pending"] = True
        def _done(_task):
            STATS["v702_a44_block_alert_task_pending"] = False
            if _task.cancelled():
                STATS["v702_a44_block_alert_cancelled"] = int(STATS.get("v702_a44_block_alert_cancelled", 0) or 0) + 1
        task.add_done_callback(_done)
    except RuntimeError:
        # No loop was available: retain a pending transition to retry at heartbeat.
        STATS["v702_a44_block_alert_pending"] = True
    except Exception as exc:
        STATS["v702_a44_block_alert_setup_errors"] = int(STATS.get("v702_a44_block_alert_setup_errors", 0) or 0) + 1
        STATS["v702_a44_block_alert_setup_last_error"] = f"{type(exc).__name__}:{str(exc)[:120]}"

def live_entries_block(reason: str, where: str = "") -> None:
    was_active = bool((LIVE_ENTRIES_BLOCKED or {}).get("active"))
    old_reason = str((LIVE_ENTRIES_BLOCKED or {}).get("reason") or "")
    _V702_A44_OLD_LIVE_ENTRIES_BLOCK(reason, where)
    now_active = bool((LIVE_ENTRIES_BLOCKED or {}).get("active"))
    new_reason = str((LIVE_ENTRIES_BLOCKED or {}).get("reason") or "")
    if now_active and (not was_active or new_reason != old_reason):
        STATS["v702_a44_latch_transitions"] = int(STATS.get("v702_a44_latch_transitions", 0) or 0) + 1
        STATS["v702_a44_latch_transition_last"] = {"reason":new_reason,"where":str((LIVE_ENTRIES_BLOCKED or {}).get("where") or where),"ts":float(WALL_NOW())}
        _v702_a44_maybe_notify_latch()

# Truthful root classification now distinguishes funding-only blocks from other
# operations hazards. This only changes operator attribution, never gate state.
_V702_A44_OLD_TRUTHFUL_STARVATION = _v699_truthful_starvation_snapshot
def _v699_truthful_starvation_snapshot():
    block = LIVE_ENTRIES_BLOCKED if isinstance(LIVE_ENTRIES_BLOCKED, dict) else {}
    if bool(block.get("active")):
        reason = str(block.get("reason") or "")
        bucket = _v702_a44_reason_root(reason, str(block.get("where") or ""))
        mode = "FUNDING_LATCH" if bucket == "BALANCE" else "OPS_LATCH"
        cid = int(STATS.get("v681_runtime_cycle_id", 0) or globals().get("_V517_ACTIVE_CYCLE_ID", 0) or 0)
        per_cycle = STATS.get("v702_a44_latch_candidate_counts", {}) or {}
        count = int(per_cycle.get(str(cid), 0) or 0) if isinstance(per_cycle, dict) else 0
        counts = {"SAFETY":count, "BALANCE":count if mode == "FUNDING_LATCH" else 0, "OPS":count if mode == "OPS_LATCH" else 0}
        return {"root":mode,"mode":mode,"detail":f"active_entry_latch:{reason[:120]}","source":"V702_A44_LATCH_TAXONOMY",
                "cycle_id":cid,"counts":counts,"root_count":count,"current_cycle_counts":counts,
                "top3_rejects":[("safety",count)] if count else [],"hard_gate_bypass":False}
    return _V702_A44_OLD_TRUTHFUL_STARVATION()

# Strategy policy shadow telemetry: after an entry latch short-circuits a
# candidate, derive the first *provable* regime/tier/HTF/score policy reason from
# existing candidate/snapshot facts only. It does not call APIs or change result.
def _v702_a44_shadow_policy_reason(ranked, snap_by_symbol):
    c = getattr(ranked, "candidate", None)
    symbol = str(getattr(c, "symbol", "") or "?")
    fs = dict(getattr(c, "features_snapshot", {}) or {}) if c is not None else {}
    snap = dict((snap_by_symbol or {}).get(symbol) or {})
    family = str(getattr(c, "strategy_mode", "") or getattr(c, "family", "") or fs.get("strategy_mode") or fs.get("family") or "").upper()
    if not family:
        return {"reason":"shadow_incomplete:family_missing","family":"UNKNOWN","symbol":symbol}
    meta = CanonicalStrategyPolicyRegistry.get(family) or {}
    regime = str(snap.get("macro_regime") or snap.get("regime") or fs.get("macro_regime") or fs.get("regime") or "").upper()
    allowed = tuple(meta.get("allowed_macro_regimes") or meta.get("allowed_regimes") or ())
    if regime in {"BULLISH","NEUTRAL","BEARISH","BEARISH_CRASH","BEARISH_STRESSED"} and allowed and regime not in {str(x).upper() for x in allowed}:
        reason = "family_regime_disallowed.macro"
    else:
        local = str(snap.get("local_regime") or fs.get("local_regime") or "").upper()
        allowed_local = tuple(meta.get("allowed_local_regimes") or ())
        if local and allowed_local and local not in {str(x).upper() for x in allowed_local}:
            reason = "family_regime_disallowed.local"
        else:
            tier = str(snap.get("tier") or fs.get("tier") or "").upper()
            min_tier = str(meta.get("min_tier") or "").upper()
            if tier and min_tier and tier in globals().get("_FAMILY_RANK", {}) and min_tier in globals().get("_FAMILY_RANK", {}) and _FAMILY_RANK[tier] < _FAMILY_RANK[min_tier]:
                reason = "liquidity.family_tier_below_floor"
            else:
                severity = str(snap.get("macro_severity") or snap.get("severity") or fs.get("macro_severity") or "").upper()
                allowed_sev = tuple(meta.get("allowed_severity") or ())
                if severity and allowed_sev and severity not in {str(x).upper() for x in allowed_sev}:
                    reason = "family_regime_disallowed.severity"
                else:
                    try:
                        strength = float(snap.get("htf_strength", fs.get("htf_strength")))
                        minimum = float(meta.get("min_htf_strength", meta.get("min_htf_strength_non_bearish", 0.0)) or 0.0)
                        reason = "family_htf_strength_below_floor" if minimum > 0 and math.isfinite(strength) and strength < minimum else "shadow_no_policy_reject_proven"
                    except Exception:
                        reason = "shadow_incomplete:missing_htf_or_policy_evidence"
    return {"reason":reason,"family":family,"symbol":symbol,"regime":regime or "UNKNOWN",
            "allowed_regimes":list(allowed)[:8],"tier":str(snap.get("tier") or fs.get("tier") or "UNKNOWN"),
            "source":"EXISTING_CANDIDATE_SNAPSHOT_ONLY","telemetry_only":True}

def _v702_a44_record_latch_candidate(ranked, snap_by_symbol, reason):
    try:
        cid = int(STATS.get("v681_runtime_cycle_id", 0) or globals().get("_V517_ACTIVE_CYCLE_ID", 0) or 0)
        key = str(cid)
        counts = STATS.get("v702_a44_latch_candidate_counts")
        if not isinstance(counts, dict): counts = {}
        counts[key] = int(counts.get(key, 0) or 0) + 1
        if len(counts) > 32:
            for old in list(counts)[:-32]: counts.pop(old, None)
        STATS["v702_a44_latch_candidate_counts"] = counts
        last_cycle = STATS.get("v702_a44_latch_cycle_event", {}) or {}
        if not isinstance(last_cycle, dict) or int(last_cycle.get("cycle_id", -1)) != cid:
            STATS["v702_a44_latch_cycle_event"] = {"cycle_id":cid,"first_ts":float(WALL_NOW()),"reason":str(reason),"candidate_count":0}
            logger.warning("[V702-A44-LATCH-CYCLE] cycle=%s latch=%s; per-candidate safety recheck retained; candidate results aggregated", cid, str(reason)[:100])
        event = STATS.get("v702_a44_latch_cycle_event") or {}
        event["candidate_count"] = counts[key]
        STATS["v702_a44_latch_cycle_event"] = event
        if bool(CONFIG.get("V702_A44_SHADOW_POLICY_REASON_ENABLE", True)):
            shadow = _v702_a44_shadow_policy_reason(ranked, snap_by_symbol)
            rows = STATS.get("v702_a44_shadow_policy_rows")
            if not isinstance(rows, list): rows = []
            # Candidate/cycle scoped dedupe: one first-shadow result per opportunity.
            sym = str(shadow.get("symbol") or "?")
            fam = str(shadow.get("family") or "?")
            skey = f"{cid}|{sym}|{fam}"
            seen = STATS.get("v702_a44_shadow_policy_seen")
            if not isinstance(seen, dict): seen = {}
            if skey not in seen:
                seen[skey] = float(WALL_NOW())
                rows.append({"key":skey,**shadow,"entry_latch_reason":str(reason)[:120],"ts":float(WALL_NOW())})
                counts_shadow = STATS.get("v702_a44_shadow_policy_counts")
                if not isinstance(counts_shadow, dict): counts_shadow = {}
                sh_reason = str(shadow.get("reason") or "unknown")
                counts_shadow[sh_reason] = int(counts_shadow.get(sh_reason, 0) or 0) + 1
                STATS["v702_a44_shadow_policy_counts"] = counts_shadow
            if len(rows) > 128: rows = rows[-128:]
            if len(seen) > 512: seen = dict(list(seen.items())[-256:])
            STATS["v702_a44_shadow_policy_rows"] = rows
            STATS["v702_a44_shadow_policy_seen"] = seen
        try:
            c = getattr(ranked, "candidate", None)
            symbol = str(getattr(c,"symbol","") or "")
            family = str(getattr(c,"family","") or getattr(c,"strategy_mode","") or "")
            key_obj = _v702_candidate_wrap(c, (snap_by_symbol or {}).get(symbol), symbol)
            V702PipelineMetrics.record("PREQUAL_SEEN",key_obj,symbol=symbol,family=family,details={"latch_fastpath":True})
            _latch_details = {"reason":str(reason),"latch_fastpath":True,"source":"a44_latch_fastpath"}
            V702PipelineMetrics.record("PREQUAL_REJECT",key_obj,symbol=symbol,family=family,details=_latch_details)
            record_reject(trace_id="", symbol=symbol, taxonomy="prequal", reason=str(reason),
                          stage="prequal", source="a44_latch_fastpath", ctx=_latch_details,
                          candidate_key=key_obj)
        except Exception:
            _v647_record_suppressed_exception()
        try:
            hook = globals().get("_V702_R39_RECORD_PREQUAL")
            if callable(hook): hook(ranked, snap_by_symbol, (False, str(reason)))
        except Exception:
            STATS["v702_a44_shadow_hook_errors"] = int(STATS.get("v702_a44_shadow_hook_errors",0) or 0)+1
    except Exception as exc:
        STATS["v702_a44_latch_telemetry_errors"] = int(STATS.get("v702_a44_latch_telemetry_errors", 0) or 0) + 1
        STATS["v702_a44_latch_telemetry_last_error"] = f"{type(exc).__name__}:{str(exc)[:120]}"

# Fast path saves enrichment/policy work during a global latch. The safety
# hazard is still checked for every candidate as a second line of defense.
_V702_A44_PREVIOUS_PREQUAL = globals().get("_v453_prequalify")
def _v702_a44_prequal_latch_fastpath(ranked, snap_by_symbol):
    if bool(CONFIG.get("V702_A44_LATCH_PREQUAL_FASTPATH_ENABLE", True)) and bool((LIVE_ENTRIES_BLOCKED or {}).get("active")):
        try:
            hazard = _v453_safety_hazard()
        except Exception:
            hazard = "safety.hazard_check_failed"
        if hazard:
            _v702_a44_record_latch_candidate(ranked, snap_by_symbol, hazard)
            return False, hazard
    return _V702_A44_PREVIOUS_PREQUAL(ranked, snap_by_symbol) if callable(_V702_A44_PREVIOUS_PREQUAL) else (False,"prequal_function_unavailable")
_v702_a44_prequal_latch_fastpath._v702_a44_wrapped = True
_v702_a44_prequal_latch_fastpath._v702_a44_original_observer = getattr(
    _V702_A44_PREVIOUS_PREQUAL, "_v702_cf_shadow_original", _V702_A44_PREVIOUS_PREQUAL)
globals()["_v453_prequalify"] = _v702_a44_prequal_latch_fastpath

# Exception suppression is now observable by caller stage and rolling window.
_V702_A44_PREVIOUS_SUPPRESSED_EXCEPTION = _v647_record_suppressed_exception
_V702_A44_SUPPRESSED_EXC_EVENTS = deque(maxlen=2048)
def _v647_record_suppressed_exception() -> None:
    try:
        frame = sys._getframe(1)
        stage = str(frame.f_code.co_name or "unknown")[:96]
    except Exception:
        stage = "unknown"
    try:
        now = float(MONO_NOW())
        _V702_A44_SUPPRESSED_EXC_EVENTS.append((now, stage))
        by_stage = STATS.get("v647_suppressed_exception_by_stage")
        if not isinstance(by_stage, dict): by_stage = {}
        by_stage[stage] = int(by_stage.get(stage, 0) or 0) + 1
        if len(by_stage) > 64:
            by_stage = dict(sorted(by_stage.items(), key=lambda kv: int(kv[1] or 0), reverse=True)[:64])
        STATS["v647_suppressed_exception_by_stage"] = by_stage
        STATS["v702_a44_suppressed_exception_window_events"] = len(_V702_A44_SUPPRESSED_EXC_EVENTS)
    except Exception:
        pass
    try:
        _V702_A44_PREVIOUS_SUPPRESSED_EXCEPTION()
    except Exception:
        pass

# Replace A40's fixed diagnostic cadence with latch-family-aware cadence. It
# remains read-only; balance-only latches poll intent/open-order state at 300s,
# while execution/protection latches retain the 90s cadence. A41 still owns
# authoritative intent reconciliation for startup-execution latches.
async def _v702_a44_entry_block_diagnostic_task(exchange):
    base_interval = max(45.0, min(180.0, float(CONFIG.get("V702_A44_OPS_DIAG_INTERVAL_SEC", 90.0) or 90.0)))
    logger.info("[V702-A44-ENTRY-DIAG] family-aware read-only diagnostics online")
    while _SHUTDOWN is None or not _SHUTDOWN.is_set():
        try:
            block = LIVE_ENTRIES_BLOCKED if isinstance(LIVE_ENTRIES_BLOCKED, dict) else {}
            if not bool(block.get("active")):
                await asyncio.sleep(base_interval)
                continue
            reason = str(block.get("reason") or "")
            root = _v702_a44_reason_root(reason, str(block.get("where") or ""))
            balance_only = root == "BALANCE"
            interval = max(120.0, min(600.0, float(CONFIG.get("V702_A44_BALANCE_DIAG_INTERVAL_SEC", 300.0) or 300.0))) if balance_only else base_interval
            now = float(WALL_NOW())
            # Durable intent reads are necessary but can be slower under a pure
            # balance latch. Read errors remain explicit; unknown is never zero.
            try:
                rows = await asyncio.wait_for(DBManager.aunresolved_execution_intents(), timeout=8.0)
                rows = list(rows or [])
                STATS["v702_a40_unresolved_intents_latest"] = {"state":"REAL","count":len(rows),
                    "symbols":sorted({str(x.get("symbol") or "?") for x in rows if isinstance(x,dict)})[:12],
                    "ts":now,"source":"a44_family_aware_block_diag"}
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                STATS["v702_a40_unresolved_intents_latest"] = {"state":"ERROR","count":None,"symbols":[],"ts":now,
                    "source":"a44_family_aware_block_diag","error":f"{type(exc).__name__}:{str(exc)[:140]}"}
            order_prev = STATS.get("v702_a40_open_orders_last", {}) or {}
            order_prev_ts = float(order_prev.get("ts", 0.0) or 0.0) if isinstance(order_prev,dict) else 0.0
            order_due = (not balance_only) or (now-order_prev_ts >= interval)
            if order_due:
                try:
                    has = getattr(exchange,"has",{})
                    fn = getattr(exchange,"fetch_open_orders",None)
                    if not callable(fn) or (isinstance(has,dict) and has.get("fetchOpenOrders") is False):
                        STATS["v702_a40_open_orders_last"] = {"state":"UNSUPPORTED","count":None,"symbols":[],"ts":now,"source":"exchange.fetch_open_orders"}
                    else:
                        orders = await asyncio.wait_for(safe_api_call("v702_a44_blockdiag_open_orders",lambda:fn(),retry_safe=True),timeout=10.0)
                        if not isinstance(orders,list): raise TypeError("fetch_open_orders_non_list")
                        STATS["v702_a40_open_orders_last"] = {"state":"REAL","count":len(orders),
                            "symbols":sorted({str(x.get("symbol") or "?") for x in orders if isinstance(x,dict)})[:12],
                            "ts":float(WALL_NOW()),"source":"exchange.fetch_open_orders"}
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    STATS["v702_a40_open_orders_last"] = {"state":"ERROR","count":None,"symbols":[],"ts":float(WALL_NOW()),
                        "source":"exchange.fetch_open_orders","error":f"{type(exc).__name__}:{str(exc)[:140]}"}
            _v702_a44_maybe_notify_latch()
            d = _v702_a40_entry_block_telemetry()
            free = d.get("balance_free_usdt")
            minimum = float(CONFIG.get("BALANCE_MIN_ACCEPT_USDT",5.0) or 5.0)
            action = "none"
            if balance_only:
                if free is None or d.get("balance_age_sec") is None or float(d.get("balance_age_sec") or 0)>90:
                    action = "REFRESH_BALANCE_DATA"
                elif float(free)<minimum:
                    action = f"FUND_ACCOUNT_FREE_LOW_{float(free):.2f}_MIN_{minimum:.2f}"
                else:
                    action = f"WAIT_FOR_HYSTERESIS_FREE_GE_{minimum*1.10:.2f}"
            logger.warning("[V702-A44-ENTRY-DIAG] latch=%s root=%s free=%s min=%.2f action=%s intents=%s:%s orders=%s:%s interval=%.0f read_only=true hard_gate_bypass=false",
                reason[:100],root,"NA" if free is None else f"{float(free):.2f}",minimum,action,
                d.get("unresolved_intents_state"),d.get("unresolved_intents_count"),d.get("open_orders_state"),d.get("open_orders_count"),interval)
            await asyncio.sleep(interval)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            STATS["v702_a40_diagnostic_task_errors"] = int(STATS.get("v702_a40_diagnostic_task_errors",0) or 0)+1
            logger.warning("[V702-A44-ENTRY-DIAG] iteration failed; gates unchanged: %s",exc)
            await asyncio.sleep(base_interval)
_v702_a44_entry_block_diagnostic_task._v702_a44_wrapped = True
globals()["_v702_a40_entry_block_diagnostic_task"] = _v702_a44_entry_block_diagnostic_task

# Extend truthful starvation diagnostics for active latches only. Existing
# policy/HTF/score windows continue unchanged when no operational latch exists.
_V702_A44_OLD_V669_STARVATION = globals().get("_v669_starvation_classify")
def _v702_a44_starvation_classifier(*args, **kwargs):
    block = LIVE_ENTRIES_BLOCKED if isinstance(LIVE_ENTRIES_BLOCKED,dict) else {}
    if bool(block.get("active")):
        reason = str(block.get("reason") or "")
        mode = "FUNDING_LATCH" if _v702_a44_reason_root(reason, str(block.get("where") or "")) == "BALANCE" else "OPS_LATCH"
        cid = int(STATS.get("v681_runtime_cycle_id",0) or globals().get("_V517_ACTIVE_CYCLE_ID",0) or 0)
        cc = STATS.get("v702_a44_latch_candidate_counts",{}) or {}
        n = int(cc.get(str(cid),0) or 0) if isinstance(cc,dict) else 0
        counts = {"SAFETY":n,"BALANCE":n if mode=="FUNDING_LATCH" else 0,"OPS":n if mode=="OPS_LATCH" else 0}
        return {"root":mode,"mode":mode,"counts":counts,"current_cycle_counts":counts,
                "top3_rejects":[("safety",n)] if n else [],"source":"V702_A44_LATCH_TAXONOMY","detail":reason[:120]}
    return _V702_A44_OLD_V669_STARVATION(*args, **kwargs) if callable(_V702_A44_OLD_V669_STARVATION) else {"root":"NONE","counts":{}}
if callable(_V702_A44_OLD_V669_STARVATION):
    globals()["_v669_starvation_classify"] = _v702_a44_starvation_classifier

# A44 compact digest places the action/critical latch first and partitions the
# plain-text digest into Telegram-safe messages <= 1700 chars at line boundaries.
def _v702_a44_partition_digest_lines(source_lines, limit=1700, max_parts=4):
    limit=max(500,min(1700,int(limit or 1700)))
    body_limit=limit-24
    chunks=[]; buf=""
    for original in (list(source_lines) or ["V702 OPERATOR DIGEST: no telemetry"]):
        line=str(original); segments=[]
        while len(line)>body_limit:
            cut=line.rfind(" ",0,body_limit)
            if cut<120: cut=body_limit
            segments.append(line[:cut]); line=line[cut:].lstrip()
        segments.append(line)
        for seg in segments:
            if len(seg)>body_limit: raise ValueError("digest_segment_exceeds_budget")
            candidate=(buf+"\n"+seg).strip() if buf else seg
            if len(candidate)>body_limit and buf: chunks.append(buf); buf=seg
            else: buf=candidate
    if buf: chunks.append(buf)
    if not chunks: chunks=["V702 OPERATOR DIGEST: empty"]
    if len(chunks)>max_parts:
        chunks=chunks[:max_parts-1]+["Additional digest content omitted by bounded partitioner; use /digest for the current summary."]
    for i, chunk in enumerate(chunks,1):
        if len(f"DIGEST {i}/{len(chunks)}\n{chunk}")>limit: raise ValueError("tagged_digest_part_over_limit")
    return chunks

_V702_A44_OLD_BUILD = _V702R28TelegramDigest.build.__func__
@classmethod
def _v702_a44_build_digest(cls):
    raw = str(_V702_A44_OLD_BUILD(cls) or "")
    _a75_post = globals().get("_V702_A75_DIGEST_POSTPROCESS")
    if callable(_a75_post):
        raw = str(_a75_post(cls, raw) or raw)
    block = LIVE_ENTRIES_BLOCKED if isinstance(LIVE_ENTRIES_BLOCKED,dict) else {}
    if not bool(block.get("active")):
        return raw
    d = _v702_a40_entry_block_telemetry()
    root = _v702_a44_reason_root(d.get("block_reason",""),d.get("block_where",""))
    age = d.get("block_age_sec")
    age_text = "unknown" if age is None else f"{float(age):.0f}s"
    free = d.get("balance_free_usdt")
    minimum = float(CONFIG.get("BALANCE_MIN_ACCEPT_USDT",5.0) or 5.0)
    if root == "BALANCE":
        if free is not None and float(free)<minimum:
            action=f"ACTION_REQUIRED: FUND ACCOUNT after verifying MEXC free USDT; free={float(free):.2f}, min={minimum:.2f}, release_at>={minimum*1.10:.2f} USDT"
        elif free is None or d.get("balance_age_sec") is None or float(d.get("balance_age_sec") or 0)>90:
            action="ACTION_REQUIRED: refresh/verify MEXC free-balance snapshot; do not infer spendable funds from total"
        else:
            action=f"ACTION_REQUIRED: keep latch until verified free USDT >= {minimum*1.10:.2f}; current free={float(free):.2f}"
        mode="FUNDING_LATCH"
    else:
        action="ACTION_REQUIRED: resolve the exact operational/protection/execution-intent block; do not clear manually"
        mode="OPS_LATCH"
    action_line=f"{mode} | {action} | blocked_since={age_text} | reason={str(d.get('block_reason') or 'unknown')[:100]}"
    lines=raw.splitlines()
    if lines:
        lines.insert(1,action_line)
    else:
        lines=["V702 OPERATOR DIGEST",action_line]
    # Do not truncate before the structured partitioner sees the full digest;
    # early slicing silently hid lower-priority diagnostics and could cut a field.
    return "\n".join(lines)
_v702_a44_build_digest.__func__._v702_a44_wrapped = True
_V702R28TelegramDigest.build = _v702_a44_build_digest

@classmethod
async def _v702_a44_flush_digest(cls, force: bool = False) -> bool:
    with cls._lock:
        events=int(cls._events); last_flush=float(cls._last_flush_ts or 0.0)
    if events<=0: return False
    interval=max(60.0,float(CONFIG.get("V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC",1800.0) or 1800.0))
    if not force and last_flush and float(WALL_NOW())-last_flush<interval: return False
    try:
        plain=cls._strip(cls.build())
        limit=max(500,min(1700,int(CONFIG.get("V702_A44_TELEGRAM_PART_MAX_CHARS",1700) or 1700)))
        chunks=_v702_a44_partition_digest_lines(plain.splitlines(),limit=limit,max_parts=4)
        STATS["v702_a44_digest_parts_last"] = len(chunks)
        STATS["v702_a44_digest_part_chars_last"] = [len(x)+len(f"DIGEST {i+1}/{len(chunks)}\n") for i,x in enumerate(chunks)]
        STATS["v702_r28_digest_flush_attempts"] = int(STATS.get("v702_r28_digest_flush_attempts",0) or 0)+1
        for index,part in enumerate(chunks,1):
            tagged=f"DIGEST {index}/{len(chunks)}\n{part}"
            if len(tagged)>limit:
                raise ValueError(f"digest_part_over_limit:{index}:{len(tagged)}>{limit}")
            ok=await _V702_R28_RAW_ENQUEUE(tagged)
            if ok is False:
                STATS["v702_r28_digest_send_fail"] = int(STATS.get("v702_r28_digest_send_fail",0) or 0)+1
                STATS["v702_a44_digest_send_failed_part"] = index
                return False
        STATS["v702_r28_digest_flushes"] = int(STATS.get("v702_r28_digest_flushes",0) or 0)+1
        STATS["v702_r28_digest_last_event_count"] = events
        STATS["v702_a44_digest_parts_sent_total"] = int(STATS.get("v702_a44_digest_parts_sent_total",0) or 0)+len(chunks)
        cls.reset_after_flush()
        return True
    except Exception as exc:
        STATS["v702_r28_digest_send_fail"] = int(STATS.get("v702_r28_digest_send_fail",0) or 0)+1
        STATS["v702_a44_digest_flush_error"] = f"{type(exc).__name__}:{str(exc)[:160]}"
        logger.warning("[V702-A44-TG] digest partition failed: %s: %s",type(exc).__name__,exc)
        return False
_V702R28TelegramDigest.flush = _v702_a44_flush_digest

# A63: snapshot-and-swap digest windows. A reset after `await enqueue()` could
# erase events captured while Telegram dispatch was suspended. The new buffer
# generation is detached atomically before the first await; failures merge the
# old snapshot back without deleting events recorded in the meantime.
_V702_A63_PREVIOUS_DIGEST_FLUSH = _V702R28TelegramDigest.flush.__func__

@classmethod
async def _v702_a63_flush_digest(cls, force: bool = False) -> bool:
    interval = max(60.0, float(CONFIG.get("V702_R28_TELEGRAM_DIGEST_INTERVAL_SEC", 1800.0) or 1800.0))
    snapshot = None
    with cls._lock:
        events = int(cls._events)
        last_flush = float(cls._last_flush_ts or 0.0)
        if events <= 0:
            return False
        if not force and last_flush and float(WALL_NOW()) - last_flush < interval:
            return False
        # build() and the generation swap share the same re-entrant lock, so
        # the exact text and the captured state describe one consistent window.
        plain = cls._strip(cls.build())
        snapshot = {
            "events": events,
            "category_counts": dict(cls._category_counts),
            "heartbeat": str(cls._heartbeat or ""),
            "starvation": str(cls._starvation or ""),
            "edge": str(cls._edge or ""),
            "latest_rejection": str(cls._latest_rejection or ""),
            "rejection_captured": int(cls._rejection_captured or 0),
            "selected_blocks": list(cls._selected_blocks),
            "scorer_blocks": list(cls._scorer_blocks),
            "route_blocks": list(cls._route_blocks),
            "shadow_events": list(cls._shadow_events),
            "discovery_by_symbol": copy.deepcopy(cls._discovery_by_symbol),
            "periodic_summary": str(getattr(cls, "_periodic_summary", "") or ""),
            "last_flush_ts": last_flush,
            "structured": {
                name: list(queue)
                for name, queue in (globals().get("_V702_A37_STRUCTURED_BLOCKS", {}) or {}).items()
                if hasattr(queue, "__iter__")
            },
        }
        cls.reset_after_flush()
    restored = False

    def _row_callbacks(row):
        if not isinstance(row, dict):
            return []
        existing = row.get("_v702_a64_delivery_callbacks")
        pairs = list(existing) if isinstance(existing, (list, tuple)) else []
        if not pairs and (callable(row.get("on_success")) or callable(row.get("on_failure"))):
            pairs.append((row.get("on_success"), row.get("on_failure")))
        return [(ok, fail) for ok, fail in pairs if callable(ok) or callable(fail)]

    def _unique_callback_pairs(rows):
        out = []
        for row in rows:
            for pair in _row_callbacks(row):
                if not any(pair[0] is old[0] and pair[1] is old[1] for old in out):
                    out.append(pair)
        return out

    delivery_callbacks = _unique_callback_pairs(
        list((snapshot.get("discovery_by_symbol") or {}).values())
    )

    async def _invoke_one_callback(callback, reason):
        if not callable(callback):
            return
        if asyncio.iscoroutinefunction(callback):
            result = await callback(reason)
        else:
            result = await asyncio.to_thread(callback, reason)
            if asyncio.iscoroutine(result) or asyncio.isfuture(result) or hasattr(result, "__await__"):
                await result

    async def _settle_discovery_callbacks(delivered: bool, reason: str):
        fired = 0
        for success_cb, failure_cb in delivery_callbacks:
            callback = success_cb if delivered else failure_cb
            if not callable(callback):
                continue
            try:
                await _invoke_one_callback(callback, reason)
                fired += 1
            except Exception as callback_exc:
                STATS["v702_a64_digest_callback_errors"] = int(
                    STATS.get("v702_a64_digest_callback_errors", 0) or 0
                ) + 1
                STATS["v702_a64_digest_callback_last_error"] = type(callback_exc).__name__
                # Preserve the existing R29 fallback contract: a failed
                # success callback is recorded through its failure callback.
                if delivered and callable(failure_cb):
                    try:
                        await _invoke_one_callback(failure_cb, "digest_callback_error")
                    except Exception:
                        STATS["v702_a64_digest_callback_errors"] = int(
                            STATS.get("v702_a64_digest_callback_errors", 0) or 0
                        ) + 1
        key = "v702_a64_digest_callbacks_delivered" if delivered else "v702_a64_digest_callbacks_failed"
        STATS[key] = int(STATS.get(key, 0) or 0) + fired

    # Queue acceptance is deliberately not delivery. When Discovery rows have
    # callbacks, each digest part gets an ACK hook; the aggregate settles only
    # after every part has been delivered, or one part has terminally failed.
    delivery_group = {"acked": 0, "settled": False}
    delivery_group_lock = threading.RLock()

    def _part_success(_reason="delivered"):
        with delivery_group_lock:
            if delivery_group["settled"]:
                return None
            delivery_group["acked"] += 1
            if delivery_group["acked"] < max(1, len(chunks)):
                return None
            delivery_group["settled"] = True
        return _settle_discovery_callbacks(True, "digest_delivered")

    def _part_failure(reason="permanent_failure"):
        with delivery_group_lock:
            if delivery_group["settled"]:
                return None
            delivery_group["settled"] = True
        # A terminal Telegram failure must restore the exact window for retry,
        # even when this digest contained no Discovery callbacks.
        _restore_failed_snapshot()
        return _settle_discovery_callbacks(False, str(reason or "permanent_failure"))

    def _cancel_delivery_group():
        # An enqueue rejection is retryable at the Digest layer. Do not emit
        # a delivery-failure outcome for a message that never entered Queue.
        with delivery_group_lock:
            delivery_group["settled"] = True

    def _restore_failed_snapshot():
        nonlocal restored
        if restored or not isinstance(snapshot, dict):
            return
        with cls._lock:
            # New-generation events are retained and remain newer than the
            # restored pre-send snapshot.
            cls._events = int(cls._events or 0) + int(snapshot.get("events", 0) or 0)
            counts = defaultdict(int)
            for k, v in snapshot.get("category_counts", {}).items():
                counts[str(k)] += int(v or 0)
            for k, v in dict(cls._category_counts).items():
                counts[str(k)] += int(v or 0)
            cls._category_counts = counts
            for attr in ("_heartbeat", "_starvation", "_edge", "_latest_rejection"):
                newer = str(getattr(cls, attr, "") or "").strip()
                older = str(snapshot.get(attr.lstrip("_"), "") or "").strip()
                if older and newer and older != newer:
                    combined = newer + "\n[PREVIOUS DIGEST WINDOW] " + older
                    setattr(cls, attr, combined[-2400:])
                elif older and not newer:
                    setattr(cls, attr, older[-2400:])
            old_summary = str(snapshot.get("periodic_summary", "") or "").strip()
            new_summary = str(getattr(cls, "_periodic_summary", "") or "").strip()
            if old_summary and new_summary and old_summary != new_summary:
                cls._periodic_summary = (new_summary + "\n[PREVIOUS DIGEST WINDOW] " + old_summary)[-2400:]
            elif old_summary and not new_summary:
                cls._periodic_summary = old_summary[-2400:]
            cls._rejection_captured = int(cls._rejection_captured or 0) + int(snapshot.get("rejection_captured", 0) or 0)
            for attr, key in (("_selected_blocks", "selected_blocks"), ("_scorer_blocks", "scorer_blocks"),
                              ("_route_blocks", "route_blocks"), ("_shadow_events", "shadow_events")):
                q = getattr(cls, attr)
                new_items = list(q)
                q.clear()
                for item in reversed(list(snapshot.get(key, []))):
                    q.appendleft(item)
                for item in reversed(new_items):
                    q.appendleft(item)

            old_discovery = copy.deepcopy(snapshot.get("discovery_by_symbol", {}))
            new_discovery = copy.deepcopy(cls._discovery_by_symbol)
            merged_discovery = dict(old_discovery)
            for key, new_row in new_discovery.items():
                old_row = merged_discovery.get(key)
                if isinstance(old_row, dict) and isinstance(new_row, dict):
                    callback_pairs = _unique_callback_pairs([old_row, new_row])
                    merged_row = dict(old_row)
                    merged_row.update(new_row)
                    if callback_pairs:
                        merged_row["_v702_a64_delivery_callbacks"] = callback_pairs
                    merged_discovery[key] = merged_row
                else:
                    merged_discovery[key] = new_row
            if len(merged_discovery) > 40:
                ordered = sorted(merged_discovery.items(), key=lambda item: float(item[1].get("ts", 0.0) or 0.0), reverse=True)[:40]
                merged_discovery = {str(k): v for k, v in ordered}
            cls._discovery_by_symbol = merged_discovery
            cls._last_flush_ts = min(float(cls._last_flush_ts or 0.0), float(snapshot.get("last_flush_ts", 0.0) or 0.0))
            structured = globals().get("_V702_A37_STRUCTURED_BLOCKS", {})
            if isinstance(structured, dict):
                for name, old_items in snapshot.get("structured", {}).items():
                    q = structured.get(name)
                    if q is None or not callable(getattr(q, "appendleft", None)):
                        continue
                    new_items = list(q)
                    q.clear()
                    for item in reversed(list(old_items)):
                        q.appendleft(item)
                    for item in reversed(new_items):
                        q.appendleft(item)
        restored = True
        STATS["v702_a63_digest_snapshot_restored"] = int(STATS.get("v702_a63_digest_snapshot_restored", 0) or 0) + 1

    try:
        limit = max(500, min(1700, int(CONFIG.get("V702_A44_TELEGRAM_PART_MAX_CHARS", 1700) or 1700)))
        chunks = _v702_a44_partition_digest_lines(plain.splitlines(), limit=limit, max_parts=4)
        STATS["v702_a44_digest_parts_last"] = len(chunks)
        STATS["v702_a44_digest_part_chars_last"] = [len(x) + len(f"DIGEST {i+1}/{len(chunks)}\n") for i, x in enumerate(chunks)]
        STATS["v702_r28_digest_flush_attempts"] = int(STATS.get("v702_r28_digest_flush_attempts", 0) or 0) + 1
        for index, part in enumerate(chunks, 1):
            tagged = f"DIGEST {index}/{len(chunks)}\n{part}"
            if len(tagged) > limit:
                raise ValueError(f"digest_part_over_limit:{index}:{len(tagged)}>{limit}")
            admission = {"accepted": False}
            def _on_part_success(reason="delivered", _admission=admission):
                return _part_success(reason) if _admission["accepted"] else None
            def _on_part_failure(reason="permanent_failure", _admission=admission):
                return _part_failure(reason) if _admission["accepted"] else None
            ok = await _V702_R28_RAW_ENQUEUE(
                tagged, on_success=_on_part_success, on_failure=_on_part_failure
            )
            if ok is not False:
                admission["accepted"] = True
            if ok is False:
                _cancel_delivery_group()
                STATS["v702_r28_digest_send_fail"] = int(STATS.get("v702_r28_digest_send_fail", 0) or 0) + 1
                STATS["v702_a44_digest_send_failed_part"] = index
                STATS["v702_a63_digest_partial_enqueue_possible"] = bool(index > 1)
                _restore_failed_snapshot()
                return False
        STATS["v702_r28_digest_flushes"] = int(STATS.get("v702_r28_digest_flushes", 0) or 0) + 1
        STATS["v702_r28_digest_last_event_count"] = events
        STATS["v702_a44_digest_parts_sent_total"] = int(STATS.get("v702_a44_digest_parts_sent_total", 0) or 0) + len(chunks)
        STATS["v702_a63_digest_generation_flushes"] = int(STATS.get("v702_a63_digest_generation_flushes", 0) or 0) + 1
        # Raw enqueue confirms QUEUED only. The aggregate ACK hooks above fire
        # knowledge callbacks only after every digest part is Telegram-ACKed.
        STATS["v702_a63_digest_delivery_state"] = "QUEUED_NOT_DELIVERED_ACK"
        return True
    except asyncio.CancelledError:
        _cancel_delivery_group()
        _restore_failed_snapshot()
        STATS["v702_a63_digest_cancelled_after_snapshot"] = int(
            STATS.get("v702_a63_digest_cancelled_after_snapshot", 0) or 0
        ) + 1
        raise
    except Exception as exc:
        _cancel_delivery_group()
        _restore_failed_snapshot()
        STATS["v702_r28_digest_send_fail"] = int(STATS.get("v702_r28_digest_send_fail", 0) or 0) + 1
        STATS["v702_a44_digest_flush_error"] = f"{type(exc).__name__}:{str(exc)[:160]}"
        logger.warning("[V702-A64-TG] digest generation retained for retry: %s: %s", type(exc).__name__, exc)
        return False

