_V702_A44_OLD_HEARTBEAT_LINE = _V702R28TelegramDigest._heartbeat_line.__func__
@classmethod
def _v702_a44_heartbeat_line(cls, text):
    base=str(_V702_A44_OLD_HEARTBEAT_LINE(cls,text) or "")
    try:
        block=LIVE_ENTRIES_BLOCKED if isinstance(LIVE_ENTRIES_BLOCKED,dict) else {}
        if bool(block.get("active")):
            mode="FUNDING_LATCH" if _v702_a44_reason_root(block.get("reason",""),block.get("where",""))=="BALANCE" else "OPS_LATCH"
            base=re.sub(r"\bstarv_mode=[^\s]+",f"starv_mode={mode}",base, count=1)
            d=_v702_a40_entry_block_telemetry(); free=d.get("balance_free_usdt")
            min_free=float(CONFIG.get("BALANCE_MIN_ACCEPT_USDT",5.0) or 5.0)
            age=d.get("block_age_sec"); age_s="unknown" if age is None else f"{float(age):.0f}s"
            action=(f"fund/free<{min_free:.2f}/release>={min_free*1.10:.2f}" if mode=="FUNDING_LATCH" and free is not None and float(free)<min_free
                    else f"refresh_balance/release>={min_free*1.10:.2f}" if mode=="FUNDING_LATCH"
                    else "resolve_operational_hazard")
            base += f" A44_LATCH={mode},reason={str(block.get('reason') or 'unknown')[:72]},free={('NA' if free is None else f'{float(free):.2f}')},min={min_free:.2f},age={age_s},action={action}"
            _v702_a44_maybe_notify_latch()
        counts=STATS.get("v702_a44_shadow_policy_counts",{}) or {}
        top=sorted(((str(k),int(v or 0)) for k,v in counts.items() if int(v or 0)>0),key=lambda kv:(-kv[1],kv[0]))[:1] if isinstance(counts,dict) else []
        if top: base += f" A44_SHADOW={top[0][0]}x{top[0][1]}"
        now=float(MONO_NOW()); window=[(ts,stage) for ts,stage in list(_V702_A44_SUPPRESSED_EXC_EVENTS) if now-ts<=1800.0]
        exc_counts={}
        for _,stage in window: exc_counts[stage]=exc_counts.get(stage,0)+1
        top_exc=sorted(exc_counts.items(),key=lambda kv:(-kv[1],kv[0]))[:2]
        span_min=max(1.0, (now-min((ts for ts,_ in window), default=now))/60.0) if window else 30.0
        base += f" A44_SUPPRESSED_EXC=30m:{len(window)},span:{span_min:.1f}m,top:"+(",".join(f"{k}:{v}({v/span_min:.2f}/min)" for k,v in top_exc) or "none")
        sev=STATS.get("v425_macro_severity",STATS.get("v702_a43_macro_severity","UNKNOWN"))
        sev_txt=str(sev or "UNKNOWN").upper()
        base=re.sub(r"\bsev=\?(?=\s|$)",f"sev={sev_txt}",base)
        # Empty/invalid aggregates are printed explicitly, never as broken placeholders.
        base=re.sub(r"SWING_BLOCK_TOP=\[\s*(?=rank=CYCLE=)","SWING_BLOCK_TOP=none ",base)
    except Exception:
        STATS["v702_a44_heartbeat_errors"] = int(STATS.get("v702_a44_heartbeat_errors",0) or 0)+1
    return base
_v702_a44_heartbeat_line.__func__.__name__ = _V702_A44_OLD_HEARTBEAT_LINE.__name__
