_V702_A44_OLD_STARVATION_LINE = _V702R28TelegramDigest._starvation_line.__func__
@classmethod
def _v702_a44_starvation_line(cls, text):
    block=LIVE_ENTRIES_BLOCKED if isinstance(LIVE_ENTRIES_BLOCKED,dict) else {}
    if bool(block.get("active")):
        reason=str(block.get("reason") or "")
        mode="FUNDING_LATCH" if _v702_a44_reason_root(reason,str(block.get("where") or ""))=="BALANCE" else "OPS_LATCH"
        cid=int(STATS.get("v681_runtime_cycle_id",0) or globals().get("_V517_ACTIVE_CYCLE_ID",0) or 0)
        cc=STATS.get("v702_a44_latch_candidate_counts",{}) or {}
        n=int(cc.get(str(cid),0) or 0) if isinstance(cc,dict) else 0
        return f"starvation mode={mode} starvation_root={mode} root={mode} safety_rejects={n} top3={'safety:'+str(n) if n else 'none'} current_cycle_counts={{'safety': {n}}} no_opportunity_starvation=true"
    raw=str(_V702_A44_OLD_STARVATION_LINE(cls,text) or "")
    raw=raw.replace("top3=-","top3=none").replace("edge=-","edge=none")
    # Prefer an explicit current-cycle root carried by the alert; fall back to
    # the latest truthful classifier rather than inferring from stale window totals.
    root=cls._text(r"live_root=([^\s|]+)", str(text or ""), "")
    if not root:
        try:
            _truth=_v699_truthful_starvation_snapshot()
            root=str((_truth or {}).get("root") or (_truth or {}).get("mode") or "OTHER")
        except Exception:
            root="OTHER"
    root=str(root or "OTHER").strip().upper()[:40]
    return f"{raw} starvation_root={root} root={root}".strip()
