# Final launch guard: reject any risk-setting drift between validated preflight and
# the live epoch arm. No market/exchange call is made here.
_V702_A44_OLD_ARM = globals().get("_v699_arm_live_epoch")
def _v702_a44_guarded_arm_live_epoch(*args, **kwargs):
    if not callable(_V702_A44_OLD_ARM):
        raise RuntimeError("live_epoch_arm_function_unavailable")
    if bool(CONFIG.get("V702_A44_CONFIG_GUARD_ENABLE", True)) and isinstance(CONFIG, _V702A44GuardedConfig):
        snap = dict(getattr(CONFIG, "_a44_locked_values", {}) or {})
        if not snap:
            if not _v702_a44_validate_config():
                STATS["v702_a44_arm_rejected"] = "validation_failed_or_snapshot_missing"
                raise RuntimeError("live_epoch_arm_rejected_config_validation")
            snap = dict(getattr(CONFIG, "_a44_locked_values", {}) or {})
        drift = [k for k,v in snap.items() if CONFIG.get(k) != v]
        if drift:
            STATS["v702_a44_arm_rejected"] = {"reason":"risk_config_changed_after_validation","keys":drift[:32]}
            logger.critical("[V702-A44-CONFIG] refusing LIVE epoch arm; risk config drift after validation keys=%s", drift[:32])
            raise RuntimeError("live_epoch_arm_rejected_risk_config_drift")
    result = _V702_A44_OLD_ARM(*args, **kwargs)
    STATS["v702_a44_live_epoch_config_verified"] = {
        "verified":True,"snapshot_ts":float(getattr(CONFIG,"_a44_snapshot_ts",0.0) or 0.0),
        "keys":len(getattr(CONFIG,"_a44_locked_values",{}) or {}),"hard_gate_bypass":False}
    return result
