        checks["latch_alert_one_shot_hook"] = callable(globals().get("_v702_a44_maybe_notify_latch")) and bool(CONFIG.get("V702_A44_ACTION_ALERT_ON_LATCH_TRANSITION",False))
        checks["family_aware_diagnostics"] = bool(getattr(_v702_a44_entry_block_diagnostic_task,"_v702_a44_wrapped",False)) and float(CONFIG.get("V702_A44_BALANCE_DIAG_INTERVAL_SEC",0) or 0)>=300.0
