def _v702_a48_configured_score_floor_value(raw_value: Any) -> float:
    """Parse the configured live floor without masking explicit invalid values.

    A zero, False, empty string, or None must not silently become the default
    floor; the final configuration validator should fail closed on malformed
    operator input instead of reporting a healthy default.
    """
    try:
        if raw_value is None:
            return float("nan")
        return float(raw_value)
    except (TypeError, ValueError, OverflowError):
        return float("nan")


