def _v702_a58_read_release_env_example(path: Optional[Path] = None) -> str:
    """Read the non-secret release defaults template without masking a missing artifact."""
    _env_path = Path(path) if path is not None else Path(__file__).with_name(".env.example")
    try:
        _value = _env_path.read_text(encoding="utf-8")
        STATS["v702_a58_release_env_example_present"] = True
        STATS.pop("v702_a58_release_env_example_error", None)
        return _value
    except OSError as _exc:
        STATS["v702_a58_release_env_example_present"] = False
        STATS["v702_a58_release_env_example_error"] = f"{type(_exc).__name__}:{str(_exc)[:180]}"
        return ""


def _v702_a58_parse_env_defaults(source: str) -> Dict[str, str]:
    """Parse active KEY=value lines only; comments never satisfy release safety checks."""
    _values: Dict[str, str] = {}
    for _raw_line in str(source or "").splitlines():
        _line = _raw_line.strip()
        if not _line or _line.startswith("#") or "=" not in _line:
            continue
        _key, _sep, _value = _line.partition("=")
        _key, _value = _key.strip(), _value.strip()
        if _key:
            _values[_key] = _value
    return _values


_V702_A58_PREVIOUS_VALIDATE_CONFIG = globals().get("validate_config")
def _v702_a58_validate_config():
    # Historical compatibility: the A57 validator is invoked here through
    # _V702_A57_PREVIOUS_VALIDATE_CONFIG() in its preserved wrapper chain.
    # Run the complete A57 validator against its own frozen identity, then
    # restore the A58 identity before evaluating the new release contracts.
    _current_revision = V702_PACKAGE_AUDIT_REVISION
    _current_release = V702_FINAL_CANONICAL_RELEASE
    _current_config_identity = CONFIG.get("V702_FINAL_CANONICAL_RUNTIME_IDENTITY")
    _current_runtime = dict(FINAL_CANONICAL_RUNTIME)
    try:
        globals()["V702_PACKAGE_AUDIT_REVISION"] = V702_A58_PRIOR_PACKAGE_AUDIT_REVISION
        globals()["V702_FINAL_CANONICAL_RELEASE"] = V702_A58_PRIOR_FINAL_CANONICAL_RELEASE
        if V702_A58_PRIOR_CONFIG_RUNTIME_IDENTITY is None:
            CONFIG.pop("V702_FINAL_CANONICAL_RUNTIME_IDENTITY", None)
        else:
            CONFIG["V702_FINAL_CANONICAL_RUNTIME_IDENTITY"] = V702_A58_PRIOR_CONFIG_RUNTIME_IDENTITY
        FINAL_CANONICAL_RUNTIME.clear()
        FINAL_CANONICAL_RUNTIME.update(V702_A58_PRIOR_FINAL_RUNTIME)
        _previous_ok = bool(_V702_A58_PREVIOUS_VALIDATE_CONFIG()) if callable(_V702_A58_PREVIOUS_VALIDATE_CONFIG) else False
    except Exception as _exc:
        _previous_ok = False
        STATS["v702_a58_previous_validation_exception"] = f"{type(_exc).__name__}:{str(_exc)[:180]}"
    finally:
        globals()["V702_PACKAGE_AUDIT_REVISION"] = _current_revision
        globals()["V702_FINAL_CANONICAL_RELEASE"] = _current_release
        if _current_config_identity is None:
            CONFIG.pop("V702_FINAL_CANONICAL_RUNTIME_IDENTITY", None)
        else:
            CONFIG["V702_FINAL_CANONICAL_RUNTIME_IDENTITY"] = _current_config_identity
        FINAL_CANONICAL_RUNTIME.clear()
        FINAL_CANONICAL_RUNTIME.update(_current_runtime)
    _source = _v702_read_source_text()
    try:
        _guard_source = Path(__file__).with_name("production_guardrails.py").read_text(encoding="utf-8")
        _health_source = Path(__file__).with_name("healthcheck.py").read_text(encoding="utf-8")
    except Exception:
        _guard_source, _health_source = "", ""
    _env_path = Path(__file__).with_name(".env.example")
    _env_source = _v702_a58_read_release_env_example(_env_path)
    _env_defaults = _v702_a58_parse_env_defaults(_env_source)
    _checks = {
        "previous_validation_pass": bool(_previous_ok),
        "release_env_example_present": bool(_env_source.strip()) and bool(STATS.get("v702_a58_release_env_example_present")),
        "legacy_authorizer_fails_closed": "entry_policy_authority_missing" in _guard_source and "legacy_token_ignored" in _guard_source,
        "unified_round_trip_cost_model": "from v702_core__execution__cost_model import unified_round_trip_cost_model as _v702_cost_model" in _source and "return _v702_cost_model(" in _source,
        "paper_fill_requires_buffered_breakout": "REFERENCE_PLUS_BUFFERED_BREAKOUT_V1" in _source and "h >= _trigger" in _source and "WAIT_FOR_BUFFERED_BREAKOUT" in _source,
        "paper_capacity_single_default_20_hard_cap_120": int(CONFIG.get("V702_KNOWLEDGE_OUTCOME_MAX_ACTIVE", 0) or 0) == 20 and KnowledgeOutcomeLedger.max_active() <= 120,
        "sqlite_updates_leave_event_loop": "await cls._active_async" in _source and "await cls._update_async" in _source and "asyncio.to_thread(cls._update" in _source,
        "ledger_single_writer_reapplied_after_overlays": all(getattr(getattr(KnowledgeOutcomeLedger, name), "__func__", getattr(KnowledgeOutcomeLedger, name)).__dict__.get("_v702_single_writer", False) for name in ("ensure_schema", "register_alert", "annotate_paper_edge", "_active", "_update", "_edge_report", "export_memory")),
        "crash_and_missing_data_excluded_from_htf_relief": "_hard_exclusions" in _guard_source and '"crash"' in _guard_source and '"unavailable"' in _guard_source,
        "shadow_same_bar_is_stop_first": "if touch_sl:\n                        hit_sl = 1" in _guard_source and "AMBIGUOUS_SAME_BAR_SL_TARGET" not in _guard_source,
        "pm_heartbeat_enforced_when_positions_open": "pm_heartbeat" in _health_source and "pm_age > pm_stale" in _health_source and "boot_id" in _health_source,
        "pm_starts_before_market_scan": "startup_protection_before_scan" in _source and _source.index("startup_protection_before_scan") < _source.index("universe = await build_top_liquidity_universe"),
        "shared_account_snapshot_and_explicit_ignore_list": "v702_equity_balance_snapshot" in _source and "V702_EQUITY_IGNORE_ASSETS" in _guard_source and "V702_EQUITY_TICKER_CACHE_TTL_SEC" in _guard_source,
        "bounded_exchange_token_bucket": "class V702PlatformRateLimiter" in _source and "await _V702_PLATFORM_RATE_LIMITER.acquire(op_label)" in _source,
        "all_submit_entry_calls_have_context": bool(V702_WRAPPER_CHAIN_VALIDATION.get("pass")),
        "spot_long_only_and_score_floor_preserved": bool(CONFIG.get("LONG_ONLY")) and str(CONFIG.get("MARKET_TYPE", "")).upper() == "SPOT" and not bool(CONFIG.get("ENABLE_FUTURES")) and float(CONFIG.get("MIN_LIVE_SCORE", 0)) >= 70.0,
        "operator_keys_off_by_default": _env_defaults.get("UNIFIED_LIVE_PILOT_ENABLE") == "0" and _env_defaults.get("UNIFIED_A55_LIVE_ARM") == "0",
        "forbidden_bases_preserved": {"PUMP", "BNB", "CAKE", "AERO", "ETHFI"}.issubset(set(V702_HARD_FORBIDDEN_BASES)),
        "runtime_and_pm_heartbeats_fail_closed": "V702_RUNTIME_HEARTBEAT_STALE_SEC" in _health_source and "V702_PM_HEARTBEAT_STALE_SEC" in _health_source,
    }
    _report = {
        "pass": bool(_previous_ok and all(_checks.values())),
        "revision": V702_A58_RELEASE_REVISION,
        "checks": _checks,
        "failed": [k for k, v in _checks.items() if not v],
        "wrapper_registry": V702_WRAPPER_CHAIN_VALIDATION,
        "previous_a57_validation": STATS.get("v702_a57_validation", {}),
        "live_network_tested": False,
        "telegram_delivery_tested": False,
        "mexc_order_fill_cancel_reconciliation_tested": False,
        "mexc_native_stop_verified": False,
        "docker_build_tested": False,
        "python_312_target_tested": False,
        "transitive_dependency_hash_lock_committed": False,
        "profitability_verified": False,
        "production_decision": "NO_GO_UNATTENDED_LIVE",
        "hard_gate_bypass": False,
        "live_gates_relaxed": False,
    }
    STATS["v702_a58_validation"] = _report
    FINAL_CANONICAL_RUNTIME.update({"a58_validation": _report, "production_decision": "NO_GO_UNATTENDED_LIVE"})
    return bool(_report["pass"])

