CONFIG.setdefault("V702_OPPORTUNITY_HUNTER_MAX_ALERTS_PER_MINUTE", 3)
CONFIG.setdefault("V702_OPPORTUNITY_HUNTER_MAX_ALERTS_PER_SCAN", 6)
